INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'Am Anfang schuf Gott den Himmel und die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'Und die Erde war eine Leere und Öde, und Finsternis war auf den Angesichten des Abgrunds; und der Geist Gottes schwebte über den Wassern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'Und Gott sprach: Es werde Licht, und es ward Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'Und Gott sah das Licht, daß es gut war, und Gott schied zwischen dem Licht und zwischen der Finsternis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'Und Gott nannte das Licht Tag und die Finsternis nannte Er Nacht; und es war Abend und es war Morgen, der erste Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'Und Gott sprach: Es sei eine Ausbreitung inmitten der Wasser und scheide zwischen den Wassern für die Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Und Gott machte die Ausbreitung und schied zwischen den Wassern die unter der Ausbreitung und den Wassern die über der Ausbreitung waren, und ward also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Und Gott nannte die Ausbreitung Himmel; und es war Abend und es war Morgen der zweite Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'Und Gott sprach: Die Wasser unter dem Himmel sammeln sich an einen Ort, und das Trockene erscheine. Und es ward also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'Und Gott nannte das Trockene Erde, und die Sammlung der Wasser nannte Er Meer. Und Gott sah, daß es gut war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Und Gott sprach: Die Erde lasse hervorkeimen das junge Grün, das Kraut, das Samen säet, den Fruchtbaum, der Frucht trägt nach seiner Art, worin sein Samen ist auf der Erde. Und es ward also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'Und die Erde brachte hervor das junge Grün, das Kraut, das Samen säet nach seiner Art, und den Baum, der Frucht trägt worin sein Samen ist nach seiner Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'Und es war Abend und es war Morgen, der dritte Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Und Gott sprach: Es seien Lichter an der Ausbreitung des Himmels, zu scheiden zwischen dem Tag und zwischen der Nacht, und sollen sein zu Zeichen und zu bestimmten Zeiten, und zu Tagen und Jahren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'Und sie seien zu Lichtern an der Ausbreitung des Himmels, zu leuchten auf der Erde. Und es ward also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'Und Gott machte die zwei großen Lichter, das große Licht am Tag zu herrschen, und das kleine Licht bei Nacht zu herrschen, und die Sterne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'Und Gott gab sie an die Ausbreitung des Himmels, zu leuchten auf der Erde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'Und zu herrschen am Tage und bei Nacht, und zu scheiden zwischen dem Licht und zwischen der Finsternis. Und Gott sah, daß es gut war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'Und es war Abend und es war Morgen, der vierte Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'Und Gott sprach: Es wimmle das Wasser vom Gewimmel, von der lebendigen Seele und das Gevögel fliege über der Erde, über die Angesichte der Ausbreitung der Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'Und Gott schuf die großen Walfische, und jede lebendige Seele, die da kriecht, wovon die Wasser wimmeln, nach ihrer Art, und alles Gevögel, das da Flügel hat, nach seiner Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'Und Gott segnete sie und sprach: Seid fruchtbar und mehret euch und füllet die Wasser in den Meeren, und das Gevögel mehre sich auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'Und es war Abend und es war Morgen, der fünfte Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'Und Gott sprach: Die Erde bringe hervor die lebendige Seele nach ihrer Art, Vieh und Kriechtier und das wilde Tier der Erde nach seiner Art. Und es ward also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'Und Gott machte das wilde Tier der Erde nach seiner Art, und das Vieh nach seiner Art und alles Kriechtier auf dem Erdboden nach seiner Art. Und Gott sah, daß es gut war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'Und Gott sprach: Lasset uns den Menschen machen in unser Bild, nach unserer Ähnlichkeit, und laßt sie beherrschen die Fische des Meeres und das Gevögel der Himmel und das Vieh und die ganze Erde und alles Kriechtier, das auf der Erde kriecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'Und Gott schuf den Menschen in Sein Bild, in das Bild Gottes schuf Er ihn, männlich und weiblich schuf Er sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'Und Gott segnete sie, und Gott sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde und machet sie euch untertan und beherrschet den Fisch des Meeres und das Gevögel der Himmel und alles wilde Tier, das auf der Erde kriecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'Und Gott sprach: Siehe, Ich gebe euch alles Kraut, das Samen säet, auf den Angesichten der ganzen Erde, und jeglichen Baum, an dem Frucht ist; der Baum, der die Samen säet, sei euch zur Speise.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Und allem Getier der Erde und allem Gevögel des Himmels, und allem, das auf Erden kriecht, in dem eine lebendige Seele ist, gebe Ich alles grüne Kraut zur Speise. Und es ward so.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Und Gott sah alles, was Er gemacht hatte, und siehe, es war sehr gut. Und es war Abend und es war Morgen, der sechste Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'Und es wurden vollendet die Himmel und die Erde und all ihr Heer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'Und Gott vollendete am siebenten Tage Sein Werk, das Er gemacht, und feierte am siebenten Tag von all Seinem Werke, das Er gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'Und Gott segnete den siebenten Tag und heiligte ihn, weil Er an ihm feierte von all Seinem Werk, das Gott geschaffen es zu machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'Dies sind die Zeugungen der Himmel und der Erde. Als Er sie schuf am Tage, da Jehovah Gott Erde und Himmel machte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'Und kein Gesträuch des Feldes war noch auf Erden, und kein Kraut des Feldes sproßte noch, denn Jehovah Gott hatte noch nicht auf Erden regnen lassen, und noch war kein Mensch da, den Boden zu bebauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'Und Er ließ einen Dunst aufgehen von der Erde und bewässerte alle Angesichte des Bodens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Und Jehovah Gott bildete den Menschen, Staub vom Boden und blies ihm des Lebens Odem in die Nase; und der Mensch ward zur lebendigen Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Und Jehovah Gott pflanzte in Eden vom Osten einen Garten und setzte darein den Menschen, den Er gebildet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'Und Jehovah Gott ließ aus dem Boden sprossen allerlei Bäume lustig anzusehen und gut zur Speise; und den Baum der Leben in der Mitte des Gartens und den Baum der Erkenntnis des Guten und des Bösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'Und von Eden ging aus ein Fluß, den Garten zu bewässern, und von da trennte er sich und ward zu vier Hauptwassern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Der Name des einen ist Pischon, der umgibt das ganze Land Chavilah, wo Gold ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'Und das Gold desselbigen Landes ist gut. Daselbst ist Bdellium und der Stein Onyx.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'Und der Name des zweiten Flusses ist Gichon. Der umgibt das ganze Land Kusch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'Und der Name des dritten Flusses ist Hiddekel. Der geht östlich nach Aschur; und der vierte Fluß der ist der Phrath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Und Jehovah Gott nahm den Menschen und setzte ihn nieder in dem Garten Eden, ihn zu bebauen und ihn zu hüten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'Und Jehovah Gott gebot über ihn dem Menschen und sprach: Von jeglichem Baume im Garten darfst du essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'Aber vom Baume der Erkenntnis des Guten und des Bösen, von dem sollst du nicht essen; denn welches Tages du davon issest, wirst du des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Und Jehovah Gott sprach: Es ist nicht gut, daß der Mensch allein sei, Ich will ihm einen Beistand machen der wie bei ihm sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Und Jehovah Gott bildete aus dem Boden jegliches Getier des Feldes und alles Gevögel der Himmel und brachte sie zum Menschen, auf daß Er sähe, wie er sie nennete; und alles, was sie der Mensch nennete, die lebendige Seele, das war dessen Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'Und der Mensch nannte mit Namen alles Vieh und das Gevögel der Himmel und alles Wild des Feldes, aber für den Menschen fand Er keinen Beistand, der wie bei ihm wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'Und Jehovah Gott ließ einen tiefen Schlaf auf den Menschen fallen, daß er schlief, und Er nahm eine von seinen Rippen und schloß Fleisch zu an deren Stelle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'Und Jehovah baute die Rippe, die Er vom Menschen genommen hatte, zu einem Weibe, und brachte sie zu dem Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Und der Mensch sprach: Das ist einmal Bein von meinen Beinen, und Fleisch von meinem Fleisch. Sie soll Männin heißen; denn vom Manne ist sie genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Darum wird der Mann seinen Vater und seine Mutter verlassen und seinem Weibe anhangen, und sie werden ein Fleisch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Und sie waren beide nackt, der Mensch und sein Weib, und schämten sich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Und die Schlange war listiger als alles Wild des Feldes, das Jehovah Gott gemacht hatte, und sprach zu dem Weibe: Hat denn Gott auch gesagt: Esset nicht von jedem Baume des Gartens?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'Und das Weib sprach zur Schlange: Von der Frucht des Baumes des Gartens dürfen wir essen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'Aber von der Frucht des Baumes, der in der Mitte des Gartens ist, sprach Gott, ihr sollt nicht von ihr essen und sie nicht berühren, auf daß ihr nicht sterbet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Und die Schlange sprach zum Weibe: Ihr werdet nicht des Todes sterben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Denn Gott weiß, daß welches Tages ihr davon esset, eure Augen sich auftun, und ihr seid wie Gott und wisset was Gutes und Böses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'Und das Weib sah, daß der Baum gut zu essen und daß er ein Gelüste für die Augen und begehrenswert sei, klug zu machen. Und sie nahm von seiner Frucht und aß, und gab auch ihrem Manne bei ihr, und er aß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Und beider Augen wurden aufgetan und sie erkannten, daß sie nackt wären, und sie hefteten Feigenblätter zusammen und machten sich Schürzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'Und sie hörten die Stimme Jehovah Gottes, im Garten sich ergehend in der Kühlung des Tages, und der Mann und sein Weib versteckten sich vor dem Angesichte Jehovah Gottes inmitten des Baumes des Gartens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Und Jehovah Gott rief dem Menschen zu und sprach zu ihm: Wo bist du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'Und er sprach: Ich hörte Deine Stimme im Garten und fürchtete mich, weil ich nackt bin, und versteckte mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Und Er sprach: Wer sagte dir an, daß du nackt seiest? Hast du von dem Baume gegessen, von dem Ich dir gebot nicht zu essen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Und der Mensch sprach: Das Weib, daß Du mir beigegeben hast, die gab mir von dem Baume, und ich aß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'Und Jehovah Gott sprach zu dem Weibe: Warum hast du das getan? Und das Weib sprach: Die Schlange hat mich verführt und ich aß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'Und Jehovah Gott sprach zu der Schlange: Weil du das getan hast, bist du verflucht vor allem Vieh und vor allem Wild des Feldes. Auf deinem Bauche sollst du gehen und Staub essen alle Tage deines Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'Und Feindschaft will Ich setzen zwischen dir und zwischen dem Weibe, und zwischen deinem Samen und zwischen ihrem Samen. Er soll dir den Kopf zertreten und du wirst ihm die Verse verletzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Zum Weibe sprach Er: Deine Schmerzen will Ich dir vielfach vermehren und deine Empfängnis. Mit Schmerzen sollst du Söhne gebären. Nach deinem Manne sollst du verlangen und er soll herrschen über dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Und zum Menschen sprach Er: Weil du auf die Stimme deines Weibes gehört, und von dem Baume gegessen hast, von dem Ich dir geboten und gesagt: du sollst nicht davon essen! ist verflucht der Boden wegen deiner. Mit Schmerzen sollst du davon essen alle Tage deines Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'Und Dorn und Distel läßt er dir sprossen und das Kraut des Feldes sollst du essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'Im Schweiß deines Antlitzes sollst du Brot essen, bis du zurück zum Boden kehrst, weil von ihm du genommen bist; denn Staub bist du, und zum Staube kehrst du zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'Und der Mensch nannte den Namen seines Weibes Chavah darum daß sie die Mutter alles Lebendigen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'Und Jehovah Gott machte dem Menschen und seinem Weibe Röcke von Fell und zog sie ihnen an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'Und Jehovah Gott sprach: Siehe, der Mensch war wie einer von Uns, wissend Gutes und Böses; und nun, daß er nicht seine Hand ausstrecke und nehme auch vom Baume des Lebens und esse und lebe ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'Und Jehovah Gott sandte ihn fort aus dem Garten Eden, den Boden zu bebauen, aus dem er genommen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'Und Er trieb den Menschen fort, und ließ vom Osten an dem Garten Eden die Cherube wohnen und die Flamme des sich wendenden Schwertes, um den Weg zum Baume des Lebens zu hüten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'Und der Mensch erkannte sein Weib Chavah und sie empfing und gebar Kain, und sprach: Ich habe einen Mann erworben, den Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'Und sie fuhr fort und gebar seinen Bruder Habel; und Habel ward ein Hirte des Kleinviehs, und Kain war ein Bebauer des Bodens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Und es geschah am Ende der Tage, daß Kain von der Frucht des Bodens Jehovah ein Opfer brachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'Und auch Habel brachte dar von den Erstlingen seines Kleinviehs und von ihrem Fette; und Jehovah schaute hin auf Habel und auf sein Opfer,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'Aber auf Kain und sein Opfer schaute Er nicht hin. Und Kain entbrannte sehr und sein Angesicht senkte sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Und Jehovah sprach zu Kain: Warum entbrennst du, und warum senkt sich dein Angesicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Ist es nicht also? Wenn du Gutes tust so ist Erhebung. Wenn du aber nicht Gutes tust, lagert die Sünde vor der Tür, und verlanget nach dir aber du sollst darüber herrschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'Und Kain sprach mit seinem Bruder Habel. Und es geschah, als sie auf dem Felde waren, daß Kain wider seinen Bruder Habel aufstand und ihn erwürgete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'Und Jehovah sprach zu Kain: Wo ist dein Bruder Habel? Und er sprach: Ich weiß es nicht. Bin ich meines Bruders Hüter?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'Und Er sprach: Was hast du getan? Die Stimme von deines Bruders Blut schreit zu Mir von dem Boden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Und nun - verflucht seist du von dem Boden der seinen Mund hat aufgesperrt, um das Blut deines Bruders von deiner Hand zu nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Wenn du den Boden bebaust gibt er dir seine Kraft nicht mehr. Du wirst umherwandern und flüchtig sein auf Erden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Und Kain sprach zu Jehovah: Zu groß ist meine Missetat, als daß sie könnte weggenommen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Siehe! Du treibst mich heute von diesem Boden fort, und vor Deinem Angesichte muß ich mich verbergen, und wandern und flüchtig sein auf Erden. Und wird geschehen, daß jeder, der mich findet, mich erwürgt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Aber Jehovah sprach zu ihm: Fürwahr, wer Kain erwürgt, das soll siebenfach gerächt werden. Und Jehovah setzte ein Zeichen an Kain, auf daß wer ihn fände, ihn nicht erschlüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Und Kain ging hinaus vom Angesicht Jehovahs und wohnte im Lande Nod im Osten von Eden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'Und Kain erkannte sein Weib, und sie empfing und gebar Chanoch. Und er baute eine Stadt, und nannte den Namen der Stadt nach dem Namen seines Sohnes Chanoch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Und dem Chanoch ward Irad geboren, und Irad zeugte Mechujael, und Mechujael zeugte den Methuschael, und Methuschael, zeugte den Lamech.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Und Lamech nahm sich zwei Weiber. Der Name der einen war Adah, und der Name der zweiten Zillah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'Und Adah gebar Jabal. Dieser war der Vater derer, die in Zelten und bei Viehherden wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'Und seines Bruders Name war Jubal. Er ward der Vater aller so die Harfe und die Flöte handhaben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Und Zillah, auch sie gebar, den Tubalkain, den Meister aller Werkleute in Erz und Eisen, und Tubalkains Schwester war Naamah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'Und Lamech sprach zu seinen Weibern Adah und Zillah: Höret meine Stimme, ihr Weiber Lamechs und nehmet zu Ohren meine Rede. Einen Mann habe ich erwürget zu meiner Wunde und ein Kind zu meiner Strieme,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Wenn Kain siebenfach gerächt wird, so wird es Lamech siebenundsiebzigmal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Und der Mensch erkannte abermals sein Weib und sie gebar einen Sohn, und sie nannte seinen Namen Scheth; denn Gott hat mir andern Samen gesetzt für Habel, dafür daß Kain ihn erwürget hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'Und auch dem Scheth ward ein Sohn geboren und er nannte seinen Namen Enosch. Damals fing man an, den Namen Jehovahs anzurufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'Dies ist das Buch der Zeugungen Adams, am Tage, da Gott den Menschen schuf. In die Ähnlichkeit Gottes machte Er ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'Männlich und weiblich schuf Er sie, und Er segnete sie und nannte ihren Namen Mensch, am Tage da sie geschaffen wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Und der Mensch lebte hundertdreißig Jahre, und er zeugte in seine Ähnlichkeit nach seinem Bilde, und nannte seinen Namen Scheth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'Und der Tage des Menschen nachdem er Scheth gezeugt, waren achthundert Jahre, und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'Und es waren all die Tage des Menschen, die er lebte, neunhundert Jahre und dreißig Jahre und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Und Scheth lebte fünf Jahre und hundert Jahre, und er zeugte Enosch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'Und Scheth lebte, nachdem er Enosch gezeugt, sieben Jahre und achthundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'Und alle Tage Scheths waren zwölf Jahre und neunhundert Jahre, und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Und Enosch lebte neunzig Jahre und zeugte Kenan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'Und Enosch lebte, nachdem er Kenan gezeugt, fünfzehn Jahre und achthundert Jahre und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'Und alle Tage Enoschs waren fünf Jahre und neunhundert Jahre, und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Und Kenan lebte siebzig Jahre und zeugte Mahalaleel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'Und Kenan lebte, nachdem er Mahalaleel gezeugt, vierzig Jahre und achthundert Jahre und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'Und alle Tage Kenans waren zehn Jahre und neunhundert Jahre; und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Und Mahalaleel lebte fünf Jahre und sechzig Jahre und zeugte Jared.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'Und Mahalaleel lebte, nachdem er Jared gezeugt hatte, dreißig Jahre und achthundert Jahre und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'Und alle Tage Mahalaleels waren fünfundneunzig Jahre und achthundert Jahre, und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Und Jared lebte zweiundsechzig Jahre und hundert Jahre und zeugte Chanoch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'Und Jared lebte, nachdem er Chanoch gezeugt, achthundert Jahre und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'Und alle Tage Jareds waren zweiundsechzig Jahre und neunhundert Jahre und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Und Chanoch lebte fünfundsechzig Jahre und zeugte Methuschelach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'Und Chanoch erging sich mit Gott, nachdem er den Methuschelach gezeugt hatte, dreihundert Jahre und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'Und alle Tage Chanochs waren fünfundsechzig Jahre und dreihundert Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'Und Chanoch erging sich mit Gott, und er war nicht; denn Gott hatte ihn hinweggenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Und Methuschelach lebte siebenundachtzig Jahre und hundert Jahre und zeugte Lamech.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'Und Methuschelach lebte, nachdem er Lamech gezeugt, zweiundachtzig Jahre und siebenhundert Jahre, und zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'Und alle Tage Methuschelachs waren neunundsechzig Jahre und neunhundert Jahre und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Und Lamech lebte zweiundachtzig Jahre und hundert Jahre und zeugte einen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'Und er nannte seinen Namen Noach, sagend: der wird uns trösten ob unserem Tun und ob den Schmerzen unserer Hände vom Boden, den Jehovah verflucht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'Und Lamech lebte, nachdem er Noach gezeugt hatte, fünfundneunzig Jahre und fünfhundert Jahre, und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'Und es waren alle Tage Lamechs siebenundsiebzig Jahre und siebenhundert Jahre, und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Und Noach war fünfhundert Jahre alt, und Noach zeugte Schem, Cham und Japheth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Und es geschah, daß der Mensch anfing sich zu mehren auf dem Angesichte des Bodens und Töchter ihnen geboren wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'Und die Söhne Gottes sahen die Töchter des Menschen, daß sie gut wären und nahmen sich Weiber von allen, die sie erwählten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Und Jehovah sprach: Mein Geist wird nicht ewiglich rechten mit dem Menschen; denn er ist Fleisch, und seine Tage werden sein hundertzwanzig Jahre!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'In denselben Tagen waren die Nephilim auf der Erde, und auch nachher, da die Söhne Gottes zu den Töchtern des Menschen eingingen, und diese ihnen gebaren. Dieselben wurden die Mächtigen von Alters her, Männer von Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Und Jehovah sah, daß des Bösen des Menschen viel ward auf Erden, und daß alles Bilden der Gedanken seines Herzens nur böse war den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'Und es reuete Jehovah, daß Er den Menschen auf Erden gemacht, und es schmerzte Ihn in Seinem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'Und Jehovah sprach: Ich will vertilgen den Menschen, den Ich geschaffen, von dem Boden vom Menschen bis zum Vieh, bis zum Kriechtier, und bis zum Gevögel der Himmel; denn es reuet Mich, daß Ich sie machte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Aber Noach fand Gnade in den Augen Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'Dies sind die Geburten Noachs. Noach war ein gerechter Mann und untadelig in seinen Geschlechtern. Noach erging sich mit Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Und Noach zeugte drei Söhne: Schem, Cham und Japheth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'Und die Erde war verdorben vor Gott; und die Erde war erfüllt mit Gewalttat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'Und Gott sah die Erde, und siehe, sie war verdorben; weil alles Fleisch seinen Weg verderbt hatte auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'Und Gott sprach zu Noach: Das Ende alles Fleisches ist vor Mich gekommen; denn die Erde ist erfüllt mit Gewalttat vor ihrem Angesicht; und siehe Ich will sie verderben mit der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Mache dir eine Arche von Gopherholz. Mit Kammern mache die Arche und verpiche sie von innen und außen mit Pech.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'Und also sollst du sie machen: Dreihundert Ellen sei die Länge der Arche, fünfzig Ellen ihre Breite und dreißig Ellen ihre Höhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Ein Fenster sollst du machen der Arche und es oben vollenden bis zu einer Elle; und den Eingang der Arche sollst du an die Seite setzen. Ein unterstes, zweites und drittes Stockwerk sollst du machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'Und Ich, siehe, Ich bringe die Flut von Wassern über die Erde, zu verderben alles Fleisch unter den Himmeln, in dem der Geist des Lebens ist. Alles, was auf Erden ist, soll verscheiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'Aber mit dir will Ich einen Bund aufrichten. Und du sollst in die Arche eingehen, du und deine Söhne und dein Weib und deiner Söhne Weiber mit dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'Und von allem Lebendigen, von allem Fleische sollst du je zwei von allem in die Arche einbringen, auf daß sie mit dir am Leben bleiben, ein Männliches und ein Weibliches sollen sie sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Von dem Gevögel nach seiner Art, und vom Vieh nach seiner Art, von allem Kriechtier des Bodens nach seiner Art, sollen je zwei von allen zu dir hereinkommen, auf daß sie am Leben bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Und du, nimm dir von jeglicher Speise, die gegessen wird, und sammle sie dir, auf daß sie dir und ihnen zur Speise seien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'Und Noach tat es. Nach allem, wie ihm Gott geboten hatte, so tat er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Und Jehovah sprach zu Noach: Gehe ein, du und all dein Haus, zur Arche; denn dich habe Ich gerecht vor Mir gesehen in diesem Geschlechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Von allem reinen Vieh nimm dir sieben und sieben, ein Männchen und sein Weibchen, und von dem Vieh, das nicht rein ist, je zwei, ein Männchen und sein Weibchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'Auch von dem Gevögel der Himmel sieben und sieben, ein Männliches und ein Weibliches, auf daß Samen auf der ganzen Erde erhalten werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Denn in noch sieben Tagen lasse Ich regnen auf Erden vierzig Tage und vierzig Nächte, und vertilge jegliches Geschöpf, das Ich gemacht, von dem Boden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'Und Noach tat nach allem, das Jehovah geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Und Noach war sechshundert Jahre alt und die Flut der Wasser war auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'Und Noach und seine Söhne und sein Weib und die Weiber seiner Söhne mit ihm gingen ein in die Arche vor den Wassern der Flut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Von dem reinen Vieh und von dem Vieh, das nicht rein war, und von dem Gevögel und von allem, das auf dem Boden kreucht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'Kamen sie hinein zwei und zwei zu Noach zur Arche, ein Männliches und ein Weibliches, wie Gott dem Noach geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Und es geschah, daß in sieben Tagen die Wasser der Flut auf der Erde waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Im sechshundersten Jahre des Lebens Noachs im zweiten Monat, am siebzehnten Tage des Monats, an diesem Tage war es, daß alle Brunnquellen des großen Abgrundes sich zerspalteten, und alle Fenster des Himmels geöffnet wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'Und vierzig Tage und vierzig Nächte war der Regen auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'An diesem selbigen Tage ging Noach, und Schem und Cham und Japhet, die Söhne Noachs und Noachs Weib und die drei Weiber seiner Söhne mit ihnen ein in die Arche;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'Sie, und alles Wild nach seiner Art, und alles Vieh nach seiner Art, und alles Kriechtier, das auf der Erde kriecht, nach seiner Art, und alles Gevögel nach seiner Art, jeder Vogel, alles Geflügelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'Und sie gingen ein zu Noach zur Arche zwei und zwei, von allem Fleisch, in welchem der Geist des Lebens war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'Und die hineingingen, Männliche und Weibliche, von allem Fleisch gingen sie hinein, wie Gott ihm geboten hatte, und Jehovah schloß hinter ihm zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'Und die Flut war vierzig Tage auf der Erde, und die Wasser mehrten sich und hoben die Arche auf und sie ward emporgehoben über die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'Und es wurden mächtig die Wasser und mehrten sich sehr auf der Erde, und die Arche ging über die Wasser dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'Und die Wasser wurden sehr, sehr mächtig auf Erden, und es wurden alle hohe Berge unter dem ganzen Himmel bedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Fünfzehn Ellen darüber wurden die Wasser mächtig und sie bedeckten die Berge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Und alles Fleisch verschied, das auf Erden kriecht, an Gevögel und an Vieh und an Wild und an allem Gewürm, das auf Erden wimmelt, und aller Mensch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'Alles, was den Odem des Geistes des Lebens in seiner Nase hatte von allem, das im Trocknen war, starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'Und Er vertilgte jegliches Geschöpf, das auf dem Boden war, vom Menschen bis zum Vieh, zum Kriechtier, und zum Gevögel des Himmels; und sie wurden vertilgt von der Erde, und nur Noach verblieb, und was mit ihm in der Arche war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Und die Wasser waren mächtig auf Erden hundertfünfzig Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Und Gott gedachte Noachs und alles Wildes und alles Viehs, das mit ihm in der Arche war, und Gott ließ einen Wind hingehen über die Erde und die Wasser legten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'Und die Brunnquellen des Abgrundes und die Fenster des Himmels wurden verstopft, und dem Regen vom Himmel ward gewehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'Und die Wasser kehrten zurück von der Erde, sie gingen und kehrten zurück, und die Wasser verringerten sich am Ende von hundertfünfzig Tagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'Und die Arche ruhte im siebenten Monat am siebzehnten Tage des Monats auf den Bergen Ararat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'Und die Wasser gingen und verringerten sich bis zum zehnten Monat. Am ersten des zehnten Monats wurden die Spitzen der Berge gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'Und es geschah am Ende von vierzig Tagen, daß Noach öffnete das Fenster der Arche, das er gemacht hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'Und er sandte den Raben aus. Und er ging aus, ausgehend und zurückkehrend, bis die Wasser von der Erde vertrockneten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'Und er sandte die Taube von sich fort, um zu sehen, ob die Wasser auf dem Boden leichter wären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Aber die Taube fand keine Ruhe für die Sohle ihres Fußes; und sie kehrte zu ihm zurück zur Arche; denn die Wasser waren auf dem Angesichte der ganzen Erde, und er streckte seine Hand aus und nahm sie und brachte sie herein zu sich in die Arche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Und er wartete noch sieben andere Tage und sandte die Taube wieder aus der Arche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'Und die Taube kam herein zu ihm um die Abendzeit, und siehe, sie hatte ein abgepflücktes Blatt vom Ölbaum in ihrem Munde. Und Noach wußte, daß die Wasser auf der Erde leichter geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'Und er wartete noch sieben andere Tage und entsandte die Taube; und sie kam nicht abermals wieder zu ihm zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'Und es geschah im sechshundert und ersten Jahre, im Anfang, am ersten des Monats, waren die Wasser von der Erde aufgetrocknet. Und Noach nahm die Decke weg von der Arche, und sah, und siehe, die Angesichte des Bodens waren aufgetrocknet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Und im zweiten Monat am siebenundzwanzigsten Tage des Monats ward die Erde trocken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Und Gott redete zu Noach und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Geh aus von der Arche du und dein Weib, und deine Söhne und deiner Söhne Weiber mit dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Alles Wild, das mit dir ist, von allem Fleisch, an Gevögel und an Vieh, und an allem Kriechtiere, das kriecht auf der Erde, laß herausgehen mit dir, und laß sie wimmeln auf der Erde und fruchtbar sein und sich mehren auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Und Noach ging heraus, und seine Söhne und sein Weib und seiner Söhne Weiber mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Alles Wild, alles Kriechtier und alles Gevögel, alles, was kriecht auf der Erde, nach ihren Familien gingen sie heraus aus der Arche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Und Noach baute dem Jehovah einen Altar, und nahm von allem reinen Vieh und von allem reinen Gevögel und opferte Brandopfer auf auf dem Altare.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'Und Jehovah roch den Geruch der Ruhe, und Jehovah sprach in Seinem Herzen: Ich will fortan dem Boden nicht mehr fluchen um des Menschen halben; denn das Gebilde des Menschen Herzens ist böse von seiner Jugend auf, und Ich will hinfort nicht mehr alles Lebendige schlagen, wie Ich getan habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Forthin, während aller Tage der Erde soll nimmermehr aufhören Samen und Ernte und Frost und Hitze und Sommer und Winter, und Tag und Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Und Gott segnete Noach und seine Söhne und sprach zu ihnen: Seid fruchtbar und mehret euch und füllet die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'Und die Frucht vor euch und das Erschrecken vor euch sei über allem wilden Getier der Erde und über allem Gevögel des Himmels; über allem, was auf dem Boden kriecht, und über allen Fischen des Meeres; sie seien in eure Hände gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Alles Kriechtier, das Leben hat, soll eure Speise sein, wie das grüne Kraut habe Ich euch alles gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Nur Fleisch in seiner Seele, seinem Blut, sollt ihr nicht essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Und fürwahr, euer Blut will Ich von euern Seelen fordern, von der Hand alles wilden Tiers will Ich es fordern und von der Hand des Menschen, von der Hand des Mannes, seines Bruders, will Ich fordern die Seele des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Wer das Blut des Menschen im Menschen vergießt, dessen Blut soll vergossen werden, weil im Bilde Gottes Er den Menschen gemacht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Und ihr, seid fruchtbar und mehret euch, wimmelt auf der Erde und mehret euch auf ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'Und Gott sprach zu Noach und zu seinen Söhnen mit ihm, und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Und Ich, siehe, Ich richte Meinen Bund auf mit euch und mit eurem Samen nach euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'Und mit aller lebendigen Seele, die bei euch ist, an Gevögel, an Vieh, und an allem wilden Tiere der Erde bei euch, von allen, die von der Arche ausgegangen, von allem wilden Tier der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Und Ich richte Meinen Bund auf mit euch, und es soll nicht mehr alles Fleisch von den Wassern der Flut ausgerottet werden, und es wird nicht mehr eine Flut sein, die Erde zu verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'Und Gott sprach: Dies sei das Zeichen des Bundes, den Ich zwischen Mir und zwischen euch und zwischen aller lebendigen Seele, die bei euch ist, für die Geschlechter des Zeitlaufs gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'Meinen Bogen gebe Ich in die Wolke, und er soll sein zum Zeichen des Bundes zwischen Mir und zwischen der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'Und es wird geschehen, wenn Ich Wolken zusammenwölke über der Erde, und der Bogen in den Wolken gesehen wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'So will Ich gedenken Meines Bundes zwischen Mir und zwischen euch und zwischen aller lebendigen Seele in allem Fleisch; und die Wasser sollen nicht mehr zur Flut werden, alles Fleisch zu verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Und der Bogen wird in der Wolke sein, und Ich werde ihn sehen, zu gedenken des ewigen Bundes zwischen Gott und zwischen aller lebendigen Seele in allem Fleisch, das auf Erden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'Und Gott sprach zu Noach: Dies sei das Zeichen des Bundes, den Ich aufrichte zwischen Mir und zwischen allem Fleisch, das auf Erden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'Und die Söhne Noachs, die von der Arche ausgingen, waren Schem und Cham und Japhet; und Cham ist der Vater Kanaans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Diese drei sind die Söhne Noachs und von ihnen ward die ganze Erde überstreut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'Und Noach fing an als Mann des Bodens und pflanzte einen Weinberg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'Und er trank von dem Wein und ward trunken und war aufgedeckt mitten in seinem Zelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Und Cham, der Vater Kanaans, sah die Blöße seines Vaters und sagte es seinen zweien Brüdern draußen an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Und Schem und Japhet nahmen das Gewand und legten es auf ihre beiden Schultern und gingen rückwärts und bedeckten die Blöße ihres Vaters, und ihre Angesichter waren rückwärts, und die Blöße ihres Vaters sahen sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Und Noach erwachte von seinem Weine, und er erfuhr, was ihm sein kleiner Sohn getan hatte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'Und er sprach: Verflucht sei Kanaan! Der Knecht der Knechte soll er seinen Brüdern sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Und er sprach: Gesegnet sei Jehovah, der Gott Schems und Kanaan soll ihm Knecht sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Weit breite Gott Japhet aus, und er soll wohnen in den Zelten Schems, und Kanaan soll ihm Knecht sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Und Noach lebte nach der Flut dreihundert Jahre und fünfzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'Und es waren alle Tage Noachs neunhundert Jahre und fünfzig Jahre, und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Und dies sind die Zeugungen der Söhne Noachs: Schem, Cham und Japheth; und es wurden ihnen nach der Flut Söhne geboren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Die Söhne Japheths sind Gomer und Magog und Madai und Javan und Thubal und Meschech und Thiras.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'Und die Söhne Gomers: Aschkenas und Riphath und Thogarmah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'Und die Söhne Javans: Elischah und Tarschisch, Kitthim und Dodanim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Von diesen trennten sich ab die Inseln der Völkerschaften in ihren Ländern, jede nach ihrer Zunge, nach ihren Familien, in ihren Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Und die Söhne Chams: Kusch und Mizraim und Put und Kanaan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'Und die Söhne Kuschs waren Seba und Chavilah und Sabtha und Raemah und Sabtheka; und die Söhne Raemahs: Scheba und Dedan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'Und Kusch zeugte Nimrod; der fing an ein Mächtiger zu werden auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'Er war ein mächtiger Jäger vor Jehovah. Darum sagte man: Wie Nimrod ein mächtiger Jäger vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'Und der Anfang seines Königreiches war Babel und Erech und Akkad und Kalneh im Lande Schinear.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Von diesem Lande zog aus Aschur, und baute Niniveh und die Stadt Rechoboth und Kalach;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'Und Resen zwischen Niniveh und zwischen Kalach. Dies ist die große Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Und Mizraim zeugte die Ludim und Lehabim und Naphtuchim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Und die Pathrusim und die Kasluchim. Woher die Philister ausgingen, und die Kaphthorim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Und Kanaan zeugte Zidon, seinen Erstgeborenen, und Cheth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'Und den Jebusiter und den Amoriter und den Girgaschiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Und den Chiviter und den Arkiter und den Siniter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Und den Arvaditer und den Zemariter und den Chamathiter; und nachher zerstreuten sich die Familien des Kanaaniters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'Und die Grenze des Kanaaniters war von Zidon, da man nach Gerar und Gazah kommt, da man gen Sodom und Gomorrah, und Admah und Zeboim bis Lascha kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'Dies sind die Söhne Chams nach ihren Familien, nach ihren Zungen in ihren Ländern, in ihren Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Und dem Schem, auch ihm ward geboren; er war der Vater aller Söhne Ebers; der größere Bruder Japheths.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Schems Söhne sind Elam und Aschur und Arpachschad und Lud und Aram.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'Und Arams Söhne sind Uz und Chul und Gether und Masch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Und Arpachschad zeugte Schelach und Schelach zeugte Eber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'Und dem Eber wurden zwei Söhne geboren. Der Name des einen war Peleg, weil in seinen Tagen die Erde zerteilt ward, und der Name seines Bruders war Joktan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'Und Joktan zeugte Almodad und Schaleph und Chazarmaveth und Jerach;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Und Hadoram und Uzal und Diklah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Und Obal und Abimael und Scheba;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Und Ophir und Chavilah und Jobab. Alle diese waren Söhne Joktans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'Und ihre Wohnung war von Mescha, da man gen Sephar, einen Berg in Osten kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Dies sind die Söhne Schems nach ihren Familien, nach ihren Zungen, in ihren Ländern, nach ihren Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Dies sind die Familien der Söhne Noachs nach ihren Geburten, in ihren Völkerschaften; und von ihnen trennten sich ab die Völkerschaften auf der Erde nach der Flut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Und die ganze Erde hatte eine Lippe und einerlei Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Und es geschah, daß sie von Osten auszogen und ein Tal im Lande Schinear fanden und daselbst wohnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'Und sie sprachen zueinander: Wohlan, lasset uns Ziegel streichen und im Feuer brennen; und sie hatten Ziegel statt Stein und Erdharz hatten sie statt Mörtel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'Und sie sprachen: Wohlan, lasset uns eine Stadt bauen, und einen Turm und seine Spitze sei im Himmel, und laßt uns einen Namen für uns machen, daß wir uns nicht über die ganze Erde zerstreuen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Und Jehovah kam herab um zu sehen die Stadt und den Turm, den die Söhne des Menschen bauten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'Und Jehovah sprach: Siehe, sie sind alle ein Volk und haben eine Lippe und dies fangen sie an zu tun und nun wird nichts von ihnen zurückgehalten werden was sie gedenken zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Wohlan, lasset uns hinabgehen und ihre Lippe verwirren, daß keiner auf die Lippe des anderen höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Und Jehovah zerstreute sie von da über die ganze Erde und sie hörten auf die Stadt zu bauen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Deshalb nannte man ihren Namen Babel, weil dort Jehovah die Lippe der ganzen Erde verwirrte; und von da zerstreute sie Jehovah über die ganze Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'Dies sind die Geburten des Schem. Schem war hundert Jahre alt, und er zeugte den Arpachschad zwei Jahre nach der Flut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'Und Schem lebte, nachdem er den Arpachschad gezeugt, fünfhundert Jahre und zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Und Arpachschad lebte fünfunddreißig Jahre, und er zeugte Schelach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'Und nachdem er Schelach gezeugt, lebte Arpachschad drei Jahre und vierhundert Jahre, und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Und Schelach lebte dreißig Jahre, und zeugte den Eber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'Und Schelach lebte, nachdem er Eber gezeugt hatte, drei Jahre und vierhundert Jahre, und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Und Eber lebte vierunddreißig Jahre, und zeugte den Peleg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'Und Eber lebte, nachdem er den Peleg gezeugt, dreißig Jahre und vierhundert Jahre, und zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Und Peleg lebte dreißig Jahre und zeugte Reu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'Und Peleg lebte, nachdem er Reu gezeugt neun Jahre und zweihundert Jahre, und zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Und Reu lebte zweiunddreißig Jahre, und zeugte Serug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'Und Reu lebte, nachdem er Serug gezeugt hatte, sieben Jahre und zweihundert Jahre, und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Und Serug lebte dreißig Jahre, und zeugte Nachor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'Und Serug lebte, nachdem er Nachor gezeugt hatte, zweihundert Jahre, und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Und Nachor lebte neunundzwanzig Jahre, und zeugte Tharach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'Und Nachor lebte, nachdem er den Tharach gezeugt hatte, neunzehn Jahre und hundert Jahre, und er zeugte Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Und Tharach lebte siebzig Jahre, und zeugte Abram, Nachor und Haran.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'Und dies sind die Geburten Tharachs: Tharach zeugte Abram, Nachor und Haran; und Haran zeugte Lot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Und Haran starb auf dem Angesichte seines Vaters Tharach im Lande seiner Geburt in Ur der Chaldäer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'Und Abram und Nachor nahmen sich Weiber. Der Name von Abrams Weib war Sarai, und der Name von Nachors Weib Milkah, eine Tochter Harans, des Vaters der Milkah und des Vaters der Jiskah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'Und Sarai war unfruchtbar, sie hatte kein Kind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Und Tharach nahm Abram seinen Sohn und Lot, den Sohn Harans seines Sohnes Sohn, und Sarai, seine Schwiegertochter, seines Sohnes Abrams Weib, und sie zogen aus mit ihnen aus Ur der Chaldäer um nach dem Lande Kanaan zu gehen, und sie kamen bis Charan und wohnten daselbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'Und Tharachs Tage waren fünf Jahre und zweihundert Jahre, und Tharach starb in Charan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'Und Jehovah sprach zu Abram: Gehe aus deinem Lande, und aus deinem Geburtsort und aus dem Hause deines Vaters nach dem Lande, das Ich dir zeigen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'Und Ich will dich zu einer großen Völkerschaft machen und dich segnen und groß machen deinen Namen, und du sollst zum Segen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'Und Ich will segnen, die dich segnen und verfluchen, wer dir flucht; und in dir sollen gesegnet werden alle Familien des Bodens!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'Und Abram ging, wie Jehovah zu ihm geredet hatte, und Lot ging mit ihm, und Abram war fünfundsiebzig Jahre alt da er von Charan auszog.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Und Abram nahm Sarai sein Weib und Lot, seines Bruders Sohn, und all ihre Habe, die sie gewonnen und die Seelen, die sie sich in Charan verschafft, und sie zogen aus, um nach dem Lande Kanaan zu gehen, und kamen ins Land Kanaan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'Und Abram zog hin im Lande bis an den Ort Sichem, zum Eichenhain Moreh, und der Kanaaniter war damals in dem Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'Und Jehovah erschien dem Abram und sprach: Deinem Samen will Ich geben dieses Land; und er baute da einen Altar dem Jehovah, Der ihm erschienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'Und von da zog er weiter nach dem Berge im Osten von Bethel und schlug sein Zelt auf mit Bethel dem Meere zu und Haai im Osten und er baute dort dem Jehovah einen Altar, und rief den Namen Jehovahs an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Und Abram brach auf und ging und zog aus nach Mittag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Und es war eine Hungersnot im Land, und Abram ging hinab nach Ägypten um dort sich aufzuhalten; denn die Hungersnot war schwer in dem Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'Und es geschah, als er nahe war, nach Ägypten zu kommen, sprach er zu Sarai, seinem Weibe: Siehe ich weiß, daß du ein Weib, schön anzusehen, bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Und es wird geschehen, wenn dich die Ägypter sehen und sagen: das ist sein Weib! daß sie mich erwürgen und dich am Leben lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Sage doch, du seiest meine Schwester; auf daß es mir gut gehe um deinetwillen, und meine Seele am Leben bleibe deinetwegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'Und es geschah, als Abram nach Ägypten kam, daß die Ägypter das Weib sahen, daß sie sehr schön war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'Und die Obersten Pharaos sahen sie und lobten sie dem Pharao; und das Weib wurde in das Haus des Pharao genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Und er tat dem Abram Gutes um ihrethalben; und er hatte Kleinvieh und Rinder und Esel und Knechte und Dienstmägde und Eselinnen und Kamele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Und Jehovah plagte Pharao und sein Haus mit großen Plagen ob Sarai, des Weibes Abrams.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'Und Pharao rief Abram und sprach: Was hast du mir das getan? Warum sagtest du mir nicht an, daß sie dein Weib ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Warum sagtest du: sie ist meine Schwester, und ich hätte sie mir zum Weibe genommen? Und nun siehe, da ist dein Weib! Nimm sie und geh!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Und Pharao gebot seinen Männern über ihn, und sie entsandten ihn und sein Weib mit allem, was er hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Und Abram kam herauf aus Ägypten er und sein Weib und alles, das er hatte, und Lot mit ihm gen Mittag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Und Abram war sehr reich an Viehherden, an Silber und an Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'Und er ging in seinen Zügen von Mittag bis nach Bethel zu dem Orte wo sein Zelt zum Anbeginn war, zwischen Bethel und Haai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'An den Ort des Altars, den er am Anfang gemacht; und Abram rief dort den Namen Jehovahs an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'Und auch Lot, der mit Abram zog, hatte Kleinvieh und Rinder und Zelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Aber das Land trug sie nicht, daß sie beisammen wohnten; denn ihrer Habe war viel, und sie konnten nicht beisammen wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'Und es war Hader zwischen den Hirten von Abrams Viehherden und zwischen den Hirten von Lots Viehherden. Und der Kanaaniter und der Pheresiter wohnten damals im Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Und Abram sprach zu Lot: Laß doch nicht Hader zwischen mir und zwischen dir, und zwischen meinen Hirten, und zwischen deinen Hirten sein, denn wir sind Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Ist nicht das ganze Land vor dir? So trenne dich doch von mir. Wenn zur Linken, so will ich zur Rechten gehen, und wenn zur Rechten, so will ich zur Linken gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'Und Lot hob seine Augen auf und sah den ganzen Umkreis, daß dieser ganz vom Jordan bewässert war. Ehe Jehovah Sodom und Gomorrah verdarb, war das Land wie ein Garten Jehovahs, wie Ägypten, wo man nach Zoar kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'Und Lot erwählte den ganzen Umkreis des Jordans für sich; und Lot brach auf vom Osten und sie trennten sich der Mann von seinem Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram wohnte im Lande Kanaan, und Lot wohnte in den Städten des Umkreises und zeltete bis gen Sodom.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Und die Männer Sodoms waren sehr böse und Sünder gegen Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'Und Jehovah sprach zu Abram, nachdem sich Lot von ihm getrennt hatte: Hebe doch deine Augen auf und siehe von dem Ort aus, wo du bist gen Mitternacht und gen Mittag und gen Osten und dem Meere zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'Denn alles Land, das du siehst, will Ich dir und deinem Samen geben ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'Und will deinen Samen machen wie Staub der Erde. So ein Mann den Staub der Erde zu berechnen vermag, so wird auch dein Same berechnet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Mache dich auf und ziehe durch das Land, seiner Länge nach und seiner Breite nach; denn dir will Ich es geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Und Abram zeltete und kam und wohnte in den Eichenhainen Mamres, die in Hebron sind, und baute daselbst dem Jehovah einen Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Und es geschah, in den Tagen Amraphels, des Königs von Schinear, Ariochs, des Königs von Ellasar, Kedorlaomers, des Königs von Elam und Thideals, des Königs von Gojim,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'Daß sie Krieg machten mit Bera, König von Sodom, und mit Birscha, König von Gomorrah, Schineab, König von Admah, und Schemeber, König von Zebojim, und dem Könige von Bela, das ist Zoar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Diese alle verbündeten sich im Talgrunde Siddim, das ist das Salzmeer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Zwölf Jahre hatten sie dem Kedorlaomer gedient, und im dreizehnten empörten sie sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'Und im vierzehnten Jahre kam Kedorlaomer und die Könige, die mit ihm waren, und schlugen die Rephaim in Aschteroth-Karnaim und die Susim in Ham und die Emim in Schaveh Kirjathaim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'Und die Choriter auf ihrem Berge Seir bis El-Paran, das oben an der Wüste ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'Und sie kehrten zurück, und kamen nach En-Mischpat, das ist Kadesch, und schlugen das ganze Gefilde des Amalekiters, und auch den Amoriter, der in Chazezon Thamar wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'Und der König von Sodom zog aus, und der König von Gomorrah, und der König von Admah, und der König von Zeboim und der König von Bela, und ordneten sich zum Streit mit ihnen im Talgrund Siddim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'Mit Kedorlaomer, König von Elam, und Thideal, König von Gojim, und Amraphel, König von Schinear, und Arioch, König von Ellasar, vier Könige mit fünf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Und der Talgrund Siddim hat Gruben an Gruben mit Erdharz, und der König von Sodom und von Gomorrah flohen und fielen daselbst, und die übrigen flohen aufs Gebirge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'Und sie nahmen alle Habe von Sodom und Gomorrah und all ihre Speise und zogen hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Und sie nahmen Lot, den Sohn von Abrams Bruder, und seine Habe und zogen hin; und er wohnte in Sodom.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'Und es kam einer, der entkommen war, und sagte es Abram, dem Hebräer an, der da wohnte in den Eichenhainen Mamres, des Amoriters, des Bruders von Eskol und Bruders von Aner, und diese waren im Bunde mit Abram.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Und Abram hörte, daß sein Bruder gefangen war, und er ließ ausziehen seine Eingeübten in seinem Hause Geborenen dreihundertachtzehn, und setzte ihnen nach bis gen Da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'Und er teilte sich wider sie in der Nacht, er und seine Knechte, und schlug sie, und setzte ihnen nach bis nach Chobah, das zur Linken von Damaskus ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'Und brachte alle ihre Habe zurück; auch seinen Bruder Lot und seine Habe brachte er zurück und auch die Weiber und das Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'Und der König von Sodom kam heraus, ihm entgegen, nachdem er zurückgekommen, als er Kedorlaomer und die Könige, die mit ihm waren geschlagen in dem Talgrund Schaveh, das ist des Königs Talgrund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Und Melchizedek, König von Schalem, brachte heraus Brot und Wein, und er war Priester des höchsten Gottes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'Und er segnete ihn und sprach: Gesegnet sei Abram dem höchsten Gotte, der Himmel und Erde besitzet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'Und gesegnet sei der höchste Gott, daß Er deine Dränger in deine Hand geliefert. Und er gab ihm von allem den Zehnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'Und der König von Sodom sprach zu Abram: Gib mir die Seelen und nimm die Habe für dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Abram aber sprach zu dem König von Sodom: Ich habe meine Hand emporgehoben zu Jehovah, dem höchsten Gott, der Himmel und Erde besitzet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'Daß ich vom Faden bis zum Schuhriemen, von allem das dein ist, nichts nehmen will; und du sollst nicht sagen: Ich habe den Abram reich gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Nichts für mich! außer dem, was die Jünglinge verzehrten, und dem Teil der Männer, die mit mir zogen. Aner, Eschkol und Mamre, sie sollen ihren Teil nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Nach diesen Dingen geschah das Wort Jehovahs zu Abram im Gesichte, und sprach: Fürchte dich nicht, Abram, Ich bin ein Schild dir, deines Lohnes ist sehr viel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Und Abram sprach: Was willst Du mir geben, Herr, Jehovah, und ich gehe hin kinderlos, und der Sohn, der Hausvogt, ist dieser Damasker Elieser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Und Abram sprach: Siehe, Du hast mir keinen Samen gegeben. Und siehe, der Sohn meines Hauses wird mich beerben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'Und siehe, das Wort Jehovahs zu ihm sprach: Nicht soll dieser dich beerben sondern der ausgehen wird aus deinen Eingeweiden, der soll dich beerben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Und Er führte ihn hinaus und sprach: Blicke doch gen Himmel und zähle die Sterne, wenn du sie zu zählen vermagst! und Er sprach zu ihm: So wird dein Same sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'Und er glaubte an Jehovah, und Er gedachte es ihm zur Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'Und Er sprach zu ihm: Ich bin Jehovah, Der dich herausführte aus Ur der Chaldäer, dir dieses Land zum Erbbesitze zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'Und er sprach: Herr, Jehovah, woran soll ich erkennen, daß ich es erblich besitzen werde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'Und Er sprach zu ihm: Hole Mir eine dreijährige Färse und eine dreijährige Ziege und einen dreijährigen Widder und eine Turteltaube und eine junge Taube.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Und er holte sich sie alle und zerstückte sie in der Mitte, und legte jegliches Stück dem anderen gegenüber, den Vogel aber zerstückte er nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Und es kam der Raubvogel herab auf die Leiber her; aber Abram wandte sie zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'Und die Sonne war am Untergehen, und ein tiefer Schlaf fiel auf Abram; und siehe, der Schrecken großer Finsternis fiel über ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'Und Er sprach zu Abram: Du sollst gewißlich wissen, daß dein Same sich wird aufhalten in einem Lande, das nicht das seine ist. Und sie werden ihnen dienen; und sie werden sie drücken vierhundert Jahre lang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'Aber auch mit der Völkerschaft, der sie dienen werden, werde Ich rechten; und danach sollen sie ausziehen mit großer Habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Du aber sollst eingehen zu deinen Vätern im Frieden, du sollst in gutem Greisenalter begraben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Und im vierten Geschlecht sollen sie hierher zurückkehren; denn die Missetat des Amoriters ist bis jetzt noch nicht voll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'Und es geschah, daß die Sonne unterging, und es war düster, und siehe, ein rauchender Ofen und eine Feuerfackel zog zwischen den Stücken hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'An jenem Tage schloß Jehovah mit Abram einen Bund und sprach: Deinem Samen habe Ich dieses Land gegeben, von dem Flusse Ägyptens bis zu dem großen Flusse, dem Flusse Phrat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Den Keniter und den Kenissiter und den Kadmoniter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'Und den Chethiter und den Pherisiter und die Rephaim;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'Und den Amoriter und den Kanaaniter und den Gergasiter und den Jebusiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Und Sarai, Abrams Weib, gebar ihm nicht. Sie hatte aber eine ägyptische Dienstmagd und ihr Name war Hagar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Und Sarai sprach zu Abram: Siehe doch, Jehovah hat mich vom Gebären zurückgehalten; so gehe doch ein zu meiner Dienstmagd, vielleicht werde ich durch sie aufgebaut. Und Abram hörte auf Sarais Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'Und Sarai, Abrams Weib, nachdem zehn Jahre zu Ende waren, seit Abram im Lande Kanaan wohnte, nahm die Ägypterin Hagar, ihre Dienstmagd, und gab sie ihrem Manne Abram ihm zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'Und er ging ein zu Hagar und sie empfing; und da sie sah, daß sie empfangen hatte, ward ihre Gebieterin gering in ihren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Und Sarai sprach zu Abram: Mein Unrecht sei auf dir! Ich gab dir meine Dienstmagd an deinen Busen. Und sie sieht, daß sie empfangen hat, und ich werde gering in ihren Augen. Jehovah richte zwischen mir und dir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Abram aber sprach zu Sarai: Siehe, deine Dienstmagd ist in deiner Hand, tue ihr, was gut in deinen Augen ist. Und Sarai demütigte sie, und sie floh vor ihrem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'Und der Engel Jehovahs fand sie in der Wüste an einer Wasserquelle; an der Quelle am Wege nach Schur.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'Und Er sprach: Hagar, Sarais Dienstmagd, woher kommst du und wohin gehst du? Und sie sprach: Vor meiner Gebieterin Sarai fliehe ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'Und Jehovahs Engel sprach zu ihr: Kehre zurück zu deiner Gebieterin und demütige dich unter ihre Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'Und der Engel Jehovahs sprach zu ihr: Mehren will Ich deinen Samen und er wird vor Menge nicht gezählt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'Und der Engel Jehovahs sprach zu ihr: Siehe, du hast empfangen und gebierst einen Sohn, und sollst seinen Namen Ismael nennen, darum, daß Jehovah auf dein Elend gehört hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'Und er wird ein Waldesel-Mensch sein, seine Hand wider alle, und die Hand aller wider ihn; und wird wohnen wider aller seiner Brüder Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Und sie nannte den Namen Jehovahs, Der mit ihr redete: Du bist der Gott, Der mich siehet; denn sie sprach: Hab ich auch hier gesehen, nach Dem, Der mich gesehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Daher nannte man den Brunnen: Brunnen Lachai Roi. Siehe, er ist zwischen Kadesch und zwischen Bared.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Und Hagar gebar dem Abram einen Sohn, und Abram nannte den Namen seines Sohnes, den Hagar geboren, Ismael.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Und Abram war achtzig Jahre und sechs Jahre alt, da Hagar den Ismael dem Abram gebar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Und Abram war neunzig Jahre und neun Jahre alt, und Jehovah erschien dem Abram und sprach zu ihm: Ich bin Gott Schaddai, wandle vor Mir und sei untadelig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'Und Ich will Meinen Bund geben zwischen Mir und zwischen dir und dich gar sehr vermehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Und Abram fiel auf sein Angesicht; und Gott redete mit ihm und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Ich, siehe Mein Bund ist mit dir; und du sollst der Vater einer Menge Völkerschaften werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'Und deinen Namen soll man fortan nicht mehr Abram nennen, sondern dein Name soll Abraham sein; denn zum Vater einer Menge von Völkerschaften gebe Ich dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'Und Ich will dich gar sehr fruchtbar machen, und gebe dich zu Völkerschaften, und Könige sollen von dir ausgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'Und Ich richte auf Meinen Bund zwischen Mir und zwischen dir und zwischen deinem Samen nach dir für ihre Geschlechter, als einen ewigen Bund, dir und deinem Samen nach dir Gott zu sein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'Und Ich gebe dir und deinem Samen nach dir das Land deiner Wanderungen, das ganze Land Kanaan, zum ewigen Eigentum, und werde ihnen Gott sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'Und Gott sprach zu Abraham: Du aber, du sollst Meinen Bund halten, du und dein Same nach dir, nach ihren Geschlechtern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Das ist Mein Bund, den ihr halten sollt zwischen Mir und zwischen euch und zwischen deinem Samen nach dir. Beschnitten werde euch alles Männliche!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Und ihr sollet beschnitten werden am Fleische eurer Vorhaut; und das sei zum Zeichen des Bundes zwischen Mir und zwischen euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Und acht Tage alt werde von euch alles Männliche beschnitten in euern Geschlechtern, der im Hause geboren und der mit Silber erworben ist von irgendwelchem Sohne des Auslands, der nicht deines Samens ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Gewißlich soll beschnitten werden, wer in deinem Hause geboren und wer mit deinem Silber erworben ist. Und Mein Bund soll in eurem Fleische sein zum ewigen Bunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Und der unbeschnittene Männliche, der sich nicht das Fleisch seiner Vorhaut beschneiden ließ, dessen Seele soll ausgerottet werden von seinen Völkern, er hat Meinen Bund zunichte gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'Und Gott sprach zu Abraham: Dein Weib Sarai - ihren Namen sollst du nicht Sarai nennen, sondern Sarah soll ihr Name sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Und Ich segne sie, und gebe dir auch von ihr einen Sohn; und Ich segne sie, daß sie zu Völkerschaften werde; Könige von Völkern sollen aus ihr werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Und Abraham fiel auf sein Angesicht und lachte, und sprach in seinem Herzen: Soll mir, dem hundert Jahre alten, geboren werden, und Sarah soll, neunzig Jahre alt, gebären?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'Und Abraham sprach zu Gott: Oh, möchte Ismael leben vor dir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'Und Gott sprach: Fürwahr, dein Weib Sarah wird dir einen Sohn gebären, und du sollst seinen Namen Isaak nennen, und Ich werde Meinen Bund mit ihm aufrichten zu einem Bunde der Ewigkeit für seinen Samen nach ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'Und wegen Ismael habe Ich dich erhört. Siehe, Ich segne ihn, und mach ihn fruchtbar und mehre ihn sehr, sehr. Zwölf Fürsten wird er zeugen, und zu einer großen Völkerschaft gebe Ich ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Aber Meinen Bund richte Ich mit Isaak auf, den Sarah dir um diese bestimmte Zeit im anderen Jahr gebären wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'Und Er vollendete Seine Rede mit ihm, und Gott stieg auf von Abraham.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Und Abraham nahm seinen Sohn Ismael und alle in seinem Haus Geborenen und alle mit seinem Silber Erworbenen, alles Männliche unter den Männern des Hauses Abrahams, und beschnitt das Fleisch ihrer Vorhaut an diesem selbigen Tage, wie Gott mit ihm geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Und Abraham war neunundneunzig Jahre alt, als er das Fleisch seiner Vorhaut beschnitt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Und Sein Sohn Ismael war dreizehn Jahre alt, als ihm das Fleisch seiner Vorhaut beschnitten wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'An diesem selbigen Tage wurde Abraham und sein Sohn Ismael beschnitten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'Und alle Männer seines Hauses, der im Haus Geborene und der von dem Sohne des Auslandes mit Silber Erworbene, wurden mit ihm beschnitten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'Und Jehovah erschien ihm in den Eichenhainen Mamres, und er saß am Eingang des Zeltes als der Tag heiß ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'Und er hob seine Augen auf und sah, und siehe, drei Männer standen bei ihm; und er sah, und lief ihnen entgegen vom Eingang des Zeltes und verbeugte sich zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'Und sprach: Mein Herr, wenn ich doch Gnade fände in deinen Augen! Zieh doch nicht vorüber an deinem Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Nehmet doch ein wenig Wasser, und waschet eure Füße und lehnet euch unter den Baum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'Und ich will einen Bissen Brot holen, daß ihr euer Herz stützet, hernach möget ihr vorüberziehen. Denn darum seid ihr bei eurem Knechte vorübergezogen. Und sie sprachen: Tue, wie du geredet hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Und Abraham eilte nach dem Zelt zu Sarah, und sprach: Nimm eilends drei Seah Mehl, Semmelmehl, knete und mache Kuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Und Abraham lief zu den Rindern, und nahm ein Kalb, zart und gut, und gab es dem Jungen; und er eilte, es zu bereiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Und er nahm Butter und Milch und das Kalb, das er bereiten ließ, und setzte ihnen vor, und er stand bei ihnen unter dem Baum und sie aßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Und sie sprachen zu ihm: Wo ist dein Weib Sarah? Und er sagte: sehet, in dem Zelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'Und Er sprach: Zu dieser Zeit des Lebens kehre Ich zu dir zurück, und siehe, dein Weib Sarah hat einen Sohn; und Sarah hörte es am Eingang des Zeltes, und dieser war hinter ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Und Abraham und Sarah waren alt, gekommen in die Tage und es hatte aufgehört mit Sarah zu sein nach der Weiber Weise.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Und Sarah lachte bei sich und sprach: Nachdem ich alt geworden bin, sollt ich noch Wollust haben? Und mein Herr ist alt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'Und Jehovah sprach zu Abraham: Warum lacht Sarah und spricht: Sollte ich fürwahr gebären, so ich doch alt bin?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Sollte für Jehovah ein Ding zu wunderbar sein? Zur bestimmten Zeit kehre Ich zu dir zurück, um diese Zeit des Lebens und Sarah hat einen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Und Sarah leugnete und sagte: Ich habe nicht gelacht; denn sie fürchtete sich. Er aber sprach: Nein, du hast gelacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Und die Männer standen auf von da und schauten aus gegen Sodom, und Abraham ging mit ihnen, sie zu entsenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Und Jehovah sprach: Soll Ich vor Abraham verdecken, was Ich tun will?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Und Abraham wird doch zur großen und zahlreichen Völkerschaft, und alle Völkerschaften der Erde sollen in ihm gesegnet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Denn Ich habe ihn dahin erkannt, daß er seinen Söhnen und seinem Hause nach ihm wird gebieten, daß sie den Weg Jehovahs halten, zu tun Gerechtigkeit und Recht, auf daß Jehovah auf Abraham kommen lasse, was Er über ihn geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Und Jehovah sprach: Weil des Geschreis über Sodom und Gomorrah viel geworden, und ihre Sünde sehr schwer ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'Will Ich nun doch hinabsteigen und sehen, ob sie nach dem Geschrei, das zu Mir gekommen, eine Vollendung gemacht, und ob nicht, will Ich wissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'Die Männer aber wandten sich von da und gingen gen Sodom; und Abraham stand noch vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'Und Abraham trat herzu und sprach: Willst Du auch wegraffen den Gerechten mit dem Ungerechten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Vielleicht sind fünfzig Gerechte in der Mitte der Stadt. Willst Du den Ort auch dann wegraffen, und nicht ihm verzeihen um der fünfzig Gerechten willen, die in seiner Mitte sind?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Das sei ferne von Dir, nach solchem Worte zu tun, daß Du tötest den Gerechten mit dem Ungerechten, und daß der Gerechte sei, wie der Ungerechte; das sei ferne von Dir. Sollte der Rier der ganzen Erde nicht Gericht üben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'Und Jehovah sprach: Wenn Ich in Sodom fünfzig Gerechte in der Mitte der Stadt finde, so verzeihe Ich dem ganzen Orte um ihretwillen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Und Abraham antwortete und sprach: Siehe doch, ich habe mich unterstanden, mit meinem Herrn zu reden, und ich bin Staub und Asche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'Vielleicht mangeln zu den fünfzig Gerechten fünf, wirst du die ganze Stadt um der fünfe willen verderben? Und Er sprach: Ich will sie nicht verderben, wenn Ich dort fünfundvierzig finde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'Und er fuhr fort, mit Ihm zu reden, und sprach: Vielleicht finden sich dort vierzig; und Er sprach: Ich will es nicht tun um der vierzig willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'Und er sprach: Entbrenne doch nicht, mein Herr, und ich will reden; vielleicht würden dreißig dort gefunden. Und Er sprach: Ich will es nicht tun, wenn Ich dort dreißig finde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'Und er sprach: Siehe doch, ich habe mich unterstanden, mit meinem Herrn zu reden. Vielleicht wird man dort zwanzig finden. Und Er sprach: Ich verderbe sie nicht um der zwanzig willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'Und er sprach: Es entbrenne nicht mein Herr, daß ich nur noch diesmal rede. Vielleicht werden dort zehn gefunden. Und Er sprach: Um der zehn willen verderbe Ich sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'Und Jehovah ging hin, als Er mit Abraham vollendet zu reden; und Abraham kehrte zurück an seinen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'Und die zwei Engel kamen am Abend nach Sodom, und Lot saß im Tore Sodoms. Und Lot sah sie und er stand auf, ihnen entgegen, und verbeugte sich mit dem Antlitz zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'Und er sprach: Siehe doch, meine Herren, lenket doch in das Haus eures Knechtes ab und übernachtet und waschet eure Füße, und stehet früh auf und gehet eures Weges. Sie sagten aber: Nein, denn wir werden auf der Straße übernachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Und er drang sehr in sie; und sie lenkten zu ihm ab und kamen in sein Haus. Und er machte ihnen ein Gastmahl und buk Ungesäuertes, und sie aßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Ehe sie sich legten, da umgaben die Männer der Stadt, die Männer von Sodom, das Haus, vom Jungen bis zum Alten, das ganze Volk vom Ende her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'Und sie riefen Lot, und sagten zu ihm: Wo sind die Männer, die diese Nacht zu dir gekommen sind. Bringe sie zu uns heraus, daß wir sie erkennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lot aber ging hinaus zu ihnen an den Eingang, und schloß die Tür hinter sich zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'Und sprach: Nicht doch, meine Brüder, tut nicht Böses!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Sehet doch, ich habe zwei Töchter, die keinen Mann erkannt haben, laßt sie mich doch zu euch herausbringen, und tut mit ihnen, was gut ist in euren Augen, nur diesen Männern tut nichts; denn dafür sind sie unter den Schatten meines Daches gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Und sie sprachen: Tritt hier herzu. Und sie sagten: Ist einer gekommen, sich hier aufzuhalten, und will als Rier richten? Nun wollen wir dir Böseres tun, denn jenen; und sie drangen sehr ein auf den Mann, auf Lot, und sie traten herzu, um die Tür aufzubrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Und die Männer streckten ihre Hand hinaus und brachten Lot zu sich herein ins Haus und verschlossen die Tür.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'Die Männer aber am Eingang zum Hause schlugen sie mit Blindheit vom Kleinen bis zum Großen und sie müheten sich ab, den Eingang zu finden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Und die Männer sprachen zu Lot: Wen hast du noch hier? Eidam und deine Söhne und deine Töchter und jeden, den du in der Stadt hast, bringe heraus aus diesem Orte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Denn wir verderben diesen Ort, weil das Geschrei über sie groß ist vor Jehovah, und Jehovah hat uns gesandt, ihn zu verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Und Lot ging hinaus und redete zu seinen Eidamen, die seine Töchter nehmen wollten, und sprach: Machet euch auf, gehet aus von diesem Ort, denn Jehovah verdirbt die Stadt. Er war aber vor den Augen seiner Eidame, wie ein Scherzender.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Und als die Morgenröte aufging, trieben die Engel Lot an, und sprachen: Mache dich auf, nimm dein Weib und deine zwei Töchter, die sich finden, daß du nicht in der Missetat der Stadt weggerafft werdest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'Und er zauderte; die Männer aber faßten ihn an seiner Hand und sein Weib bei der Hand und seine zwei Töchter bei der Hand, weil Jehovah ihn bemitleidete, und brachten ihn hinaus und ließen ihn draußen vor der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'Und es geschah, als sie dieselben hinausgebracht hatten, sprach Er: Entrinne ob deiner Seele, blicke nicht hinter dich und bleib nicht stehen in dem ganzen Umkreis, entrinne auf den Berg, auf daß du nicht weggerafft werdest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Lot aber sprach zu ihnen: Nicht doch, meine Herren!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Siehe doch, Dein Knecht hat Gnade gefunden in Deinen Augen, und Du hast groß gemacht Deine Barmherzigkeit, die Du an mir getan, daß Du meine Seele am Leben erhalten; aber ich vermag nicht auf den Berg zu entrinnen, daß mir nicht das Böse anklebe, daß ich stürbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Siehe doch diese Stadt ist nahe, um dahin zu fliehen. Und sie ist klein, laß mich dahin entrinnen; ist sie nicht klein? und meine Seele wird leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'Und Er sprach zu ihm: Siehe auch in diesem Worte erhöre Ich dich, daß Ich die Stadt nicht umkehre, von der du geredet hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Eile, entrinne dahin, weil Ich nichts zu tun vermag, bis du dahin kommst. Deshalb nannte man den Namen der Stadt Zoar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Die Sonne ging auf über die Erde und Lot kam gen Zoar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'Und Jehovah ließ regnen über Sodom und über Gomorrah Schwefel und Feuer von Jehovah aus dem Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'Und Er kehrte um diese Städte und den ganzen Umkreis und alle Einwohner der Städte und das Gewächs des Bodens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'Aber sein Weib blickte um hinter ihm und ward zur Salzsäule.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Und Abraham machte sich früh am Morgen auf nach dem Orte, wo er vor Jehovah gestanden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'Und schaute aus über Sodom und Gomorrah und über das ganze Land des Umkreises und er sah, und siehe da, es stieg der Qualm der Erde auf, wie der Qualm eines Ofens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Und es geschah, als Gott die Städte des Umkreises verdarb, daß Gott des Abrahams gedachte, und Lot mitten aus der Zerstörung entsandte wie er die Städte umkehrte in denen Lot gewohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lot aber ging hinauf aus Zoar und wohnte auf dem Berge und seine zwei Töchter mit ihm; denn er fürchtete sich in Zoar zu wohnen; und er wohnte in der Höhle, er und seine zwei Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Und die Erstgeborene sprach zur Jüngeren: Unser Vater ist alt und kein Mann ist im Lande, der zu uns käme, nach der Weise der ganzen Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'So komm, laß uns unserem Vater Wein zu trinken geben und bei ihm liegen, auf daß wir von unserem Vater Samen lebendig machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Und sie ließen ihren Vater Wein trinken in derselben Nacht, und die Erstgeborene kam und lag bei ihrem Vater, und er wußte es nicht, da sie sich niederlegte, noch da sie aufstand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'Und es geschah am morgenden Tag, daß die Erstgeborene zur Jüngeren sprach: Siehe ich bin gestern bei meinem Vater gelegen. Lassen wir ihn auch diese Nacht Wein trinken, und gehe du hinein und liege bei ihm, daß wir von unserem Vater Samen lebendig machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Und sie ließen ihren Vater Wein trinken; und die Jüngere machte sich auf und lag bei ihm, und er wußte es nicht, da sie sich legte, noch da sie aufstand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Und die zwei Töchter Lots empfingen von ihrem Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'Und die Erstgeborene gebar einen Sohn und nannte seinen Namen Moab. Er ist der Vater Moabs bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'Und die Jüngere gebar auch einen Sohn, und nannte seinen Namen Ben-Ammi. Er ist der Vater der Söhne Ammons bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Und Abraham zog aus von da nach dem Lande gegen Mittag, und wohnte zwischen Kadesch und zwischen Schur, und hielt sich in Gerar auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'Und Abraham sagte von seinem Weibe Sarah: Sie ist meine Schwester. Und Abimelech, König von Gerar, sandte und nahm Sarah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Und Gott kam zu Abimelech im Traume bei Nacht, und sprach zu ihm: Siehe, du stirbst ob dem Weibe, das du genommen hast; denn sie ist einem Gemahle vermählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelech aber hatte sich ihr nicht genaht, und sprach: Herr, wirst du auch eine gerechte Völkerschaft erwürgen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Sagte er mir nicht: Sie ist meine Schwester? Und sie auch, sagte sie nicht selbst: Er ist mein Bruder? In Rechtschaffenheit meines Herzens und mit Unschuld meiner Hände habe ich das getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'Und Gott sprach zu ihm im Traum: Auch Ich weiß, daß du dies in der Rechtschaffenheit deines Herzens getan hast; und Ich hielt dich auch zurück, daß du nicht wider Mich sündigest; deshalb gab Ich es nicht zu, daß du sie berührtest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Nun aber gib zurück des Mannes Weib; denn er ist ein Prophet, und er wird beten für dich, daß du am Leben bleibst; und gibst du sie nicht zurück, so wisse, daß du des Todes sterben mußt, du und alles, was du hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Und Abimelech stand früh am Morgen auf und rief alle seine Knechte, und redet alle diese Worte vor ihren Ohren. Und die Männer fürchteten sich sehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Und Abimelech rief dem Abraham, und sprach zu ihm: Was hast du uns getan? Und was habe ich an dir gesündigt, daß du über mich und über mein Reich so große Sünde gebracht? Du hast Taten an mir getan, die man nicht tun sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Und Abimelech sprach zu Abraham: Was hast du gesehen, daß du solches tatest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Und Abraham sprach: Ich sagte: Es ist doch keine Furcht Gottes an diesem Orte, und sie werden mich erwürgen wegen meines Weibes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Und sie ist auch in Wahrheit meine Schwester, die Tochter meines Vaters ist sie, aber nicht die Tochter meiner Mutter, und sie ward mir zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Und es geschah als mich Gott aus meines Vaters Hause wandern ließ, da sprach ich zu ihr: das ist deine Barmherzigkeit, die du an mir tun sollst an jedem Ort, an den wir kommen, daß du von mir sagst: Er ist mein Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Und Abimelech nahm Kleinvieh und Rinder und Knechte und Dienstmägde, und gab sie Abraham, und gab ihm Sarah, sein Weib, zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'Und Abimelech sprach: Siehe, mein Land ist vor dir, wohne, wo es gut ist in deinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Und zu Sarah sprach er: Siehe, deinem Bruder gebe ich tausend Silberstücke. Siehe, das ist für dich eine Decke der Augen für alle, die mit dir sind, und für alle. Und für sie ward gerügt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'Und Abraham betete zu Gott; und Gott heilte Abimelech, sein Weib und seine Mägde, und sie gebaren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Denn Jehovah hatte jeglichen Mutterschoß in Abimelechs Haus zurückgehalten ob Sarah, dem Weibe Abrahams.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'Und Jehovah suchte Sarah heim, wie Er gesagt, und Jehovah tat mit Sarah, wie Er geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Und Sarah empfing und gebar Abraham einen Sohn in seinem Alter zu der bestimmten Zeit, wie Gott mit ihm geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'Und Abraham nannte den Namen seines Sohnes, der ihm geboren worden, den ihm Sarah gebar, Isaak.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'Und Abraham beschnitt Isaak, seinen Sohn, am achten Tage, wie ihm Gott geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Und Abraham war hundert Jahre alt, da ihm Isaak, sein Sohn, geboren wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'Und Sarah sprach: Ein Lachen hat mir Gott bereitet. Jeder, der es hört, wird lachen über mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Und sie sprach: Wer hätte dem Abraham gesagt: Sarah säugt Söhne! daß ich seinem Alter einen Sohn gebären würde!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'Und das Kind ward groß und ward entwöhnt, und Abraham machte ein großes Gastmahl am Tage von Isaaks Entwöhnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'Und Sarah sah den Sohn der Hagar, der Ägypterin, den sie dem Abraham geboren hatte, spotten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'Und sie sprach zu Abraham: Treibe diese Magd und ihren Sohn fort; denn der Sohn dieser Magd darf nicht mit meinem Sohne, mit Isaak, erblich besitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'Und das Wort war sehr böse in den Augen Abrahams wegen seines Sohnes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'Und Gott sprach zu Abraham: Es sei nicht böse in deinen Augen wegen des Jungen und deiner Magd. Alles, was Sarah zu dir sagt, höre auf ihre Stimme; denn in Isaak soll dir ein Same genannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Und auch den Sohn der Magd will Ich als eine Völkerschaft setzen, weil er dein Same ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Und Abraham stand früh am Morgen auf, und nahm Brot und einen Schlauch mit Wasser, und gab sie Hagar, legte sie auf ihre Schulter, und den Knaben und entsandte sie. Und sie ging hin und wanderte umher in der Wüste Beerschaba.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Und das Wasser war alle aus dem Schlauche; und sie warf den Knaben unter eines der Gesträuche;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'Und sie ging hin und setzte sich von ferne, einen Bogenschuß weit gegenüber; denn, sprach sie, ich will nicht sehen, wie der Knabe stirbt. Und sie saß da gegenüber, und hob ihre Stimme auf und weinte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Und Gott hörte die Stimme des Jungen, und der Engel Gottes rief der Hagar vom Himmel zu, und sprach zu ihr: Was ist dir, Hagar? Früchte dich nicht! denn Gott hat die Stimme des Jungen gehört dort, wo er ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Steh auf, nimm den Jungen und faß ihn an der Hand; denn Ich will ihn zu einer großen Völkerschaft setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Und Gott tat ihre Augen auf, und sie sah einen Brunnen mit Wasser; und sie ging und füllte den Schlauch mit Wasser und ließ den Jungen trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'Und Gott war mit dem Jungen, und er ward groß, und wohnte in der Wüste, und er ward ein Bogenschütze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'Und er wohnte in der Wüste Paran, und seine Mutter nahm ihm ein Weib aus dem Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Und es geschah um diese Zeit, daß Abimelech und der Oberste seines Heeres, Pichol, mit Abraham sprachen und sagten: Gott ist mit dir in allem, was du tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Und nun schwöre mir bei Gott hier, daß du gegen mich, meinen Sohn und meinen Enkel nicht lügen willst. Nach der Barmherzigkeit, die ich an dir getan, tue auch an mir und an dem Lande, in dem du dich aufgehalten hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'Und Abraham sprach: Ich will schwören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Und Abraham rügte den Abimelech über einen Wasserbrunnen, den Abimelechs Knechte ihm entrissen hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abimelech aber sprach: Ich weiß nicht, wer das Ding getan, und du hast mir es auch nicht angesagt, und ich hörte nichts davon bis heute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'Und Abraham nahm Kleinvieh und Rinder und gab sie Abimelech, und sie beide schlossen einen Bund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Und Abraham stellte sieben Lämmer von dem Kleinvieh besonders.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Und Abimelech sprach zu Abraham: Was sollen diese sieben Lämmer, die du besonders gestellt hast?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'Und er sprach: Die sieben Lämmer sollst du nehmen aus meiner Hand, auf daß es mir zum Zeugnis sei, daß ich diesen Brunnen gegraben habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Daher nennt man diesen Ort Beerschaba, weil sie beide dort einander geschworen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'Und sie schlossen einen Bund in Beerschaba. Und Abimelech und Pichol, der Oberste seines Heeres, machten sich auf und kehrten zurück in das Land der Philister.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Und Abraham pflanzte in Beerschaba einen Hain, und rief dort den Namen Jehovahs, des ewigen Gottes an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'Und Abraham hielt sich viele Tage im Lande der Philister auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Und es geschah nach diesen Dingen, daß Gott versuchte Abraham und sprach zu ihm: Abraham! Und er sagte: Hier bin ich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'Und Er sprach: Nimm doch deinen Sohn, deinen einzigen, den du liebst, den Isaak, und geh in das Land Moriah und opfere ihn auf daselbst als Brandopfer auf einem der Berge, den Ich dir sagen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Und Abraham stand früh am Morgen auf, und sattelte seinen Esel und nahm seine zwei Jungen und seinen Sohn Isaak mit sich, und spaltete Holz zum Brandopfer, und machte sich auf und ging an den Ort, den ihm Gott gesagt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Am dritten Tage, da hob Abraham seine Augen auf und sah den Ort von ferne;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'Und Abraham sprach zu seinen Jungen: Bleibet ihr hier mit dem Esel; und ich und der Junge wollen dorthin gehen und uns niederbeugen und zu euch zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'Und Abraham nahm das Holz für das Brandopfer und legte es auf seinen Sohn Isaak. Und er nahm das Feuer und das Messer in seine Hand, und sie beide gingen miteinander.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Und Isaak sprach zu seinem Vater Abraham und sagte: Mein Vater! Und er sprach: Hier bin ich, mein Sohn. Und er sprach: Siehe das Feuer und das Holz, wo ist aber das Lamm zum Brandopfer?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Und Abraham sprach: Gott wird sich das Lamm zum Brandopfer ausersehen, mein Sohn; und sie beide gingen miteinander.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Und sie kamen an den Ort, den ihm Gott gesagt hatte; und Abraham baute dort den Altar und legte das Holz zurecht und band Isaak seinen Sohn und legte ihn auf den Altar über das Holz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'Und Abraham reckte seine Hand aus und nahm das Messer, um seinen Sohn zu schlachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Und der Engel Jehovahs rief ihm vom Himmel, und sprach: Abraham! Abraham! Und er sprach: Hier bin ich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'Und Er sprach: Recke deine Hand nicht aus über den Jungen, und tue ihm nichts; denn nun weiß Ich, daß du Gott fürchtest, und hast deinen Sohn, deinen einzigen, Mir nicht zurückbehalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'Und Abraham hob seine Augen auf und sah, und siehe, ein Widder hinten mit seinen Hörnern im Dickicht verfangen. Und Abraham ging und nahm den Widder und opferte ihn auf zum Brandopfer statt seines Sohnes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Und Abraham nannte den Namen dieses Ortes Jehovah sieht; daher man noch diesen Tages sagt: â¬SAuf dem Berge wird Jehovah sehenâ¬_.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'Und der Engel Jehovahs rief Abraham zum zweitenmal vom Himmel,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'Und sprach: Ich habe bei Mir geschworen, spricht Jehovah, weil du dies Ding getan und deinen Sohn, deinen einzigen, nicht zurückbehalten hast;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'Will Ich gewißlich dich segnen und deinen Samen mehren, wie die Sterne der Himmel und wie den Sand am Ufer des Meeres, und dein Same soll das Tor seiner Feinde erblich besitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'Und gesegnet sollen werden in deinem Samen alle Völkerschaften der Erde, darum, daß du auf Meine Stimme gehört hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'Und Abraham kehrte zu seinen Jungen zurück, und sie machten sich auf und gingen miteinander nach Beerschaba; und Abraham wohnte in Beerschaba.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'Und es geschah nach diesen Dingen, daß dem Abraham angesagt wurde sprechend: Siehe, auch Milkah, sie hat deinem Bruder Nachor Söhne geboren:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Uz, seinen Erstgeborenen, und seinen Bruder Bus, und Kemuel, den Vater Arams,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'Und Chesed und Chaso und Pildasch und Jidlaph und Bethuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Und Bethuel zeugte Rebekah. Diese acht gebar Milkah dem Nachor, Abrahams Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Und sein Kebsweib, deren Name war Reumah, und auch sie gebar Tebach und Gacham und Thachasch und Maachah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Und es war das Leben Sarahs hundert Jahre und zwanzig Jahre und sieben Jahre. Dies sind die Jahre des Lebens Sarahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'Und Sarah starb in Kiriath-Arba, das ist Chebron, im Lande Kanaan; und Abraham kam zu klagen um Sarah und sie zu beweinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Und Abraham stand auf über dem Angesichte seiner Toten und redete zu den Söhnen Cheths, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Ein Fremdling und Beisasse bin ich bei euch. Gebt mir das Eigentum eines Grabes bei euch, daß ich meine Tote von meinem Angesichte weg begrabe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Und die Söhne Cheths antworteten Abraham, und sprachen zu ihm:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Höre uns, mein Herr. Du bist ein Fürst Gottes in unserer Mitte. In der Auswahl unserer Gräber begrabe deine Tote. Kein Mann von uns wird dir sein Grab verwehren, daß du deine Tote begrabest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Und Abraham stand auf und verbeugte sich vor dem Volke des Landes, vor den Söhnen Cheths.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'Und er redete mit ihnen, und sprach: Wenn es in eurer Seele ist, daß ich die Tote von meinem Angesichte weg begrabe, so höret mich an, und vermittelt für mich bei Ephron, Zochars Sohn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'Daß er mir gebe die Höhle Machpelah, die sein ist, am Ende seines Feldes; um volles Silber gebe er sie mir in eurer Mitte zum Grabeseigentum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Und Ephron saß in der Mitte der Söhne Cheths, und Ephron, der Chethiter, antwortete Abraham vor den Ohren der Söhne Cheths, vor allen, die zum Tore seiner Stadt eingingen, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nein, mein Herr, höre mich. Das Feld gebe ich dir, und die Höhle, die darinnen ist, gebe ich dir, vor den Augen der Söhne meines Volkes gebe ich sie dir, begrabe deine Tote.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Und Abraham verbeugte sich vor dem Volke des Landes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'Und er redete zu Ephron vor den Ohren des Volkes des Landes und sprach: Wolltest du doch auf mich hören. Ich gebe dir das Silber des Feldes. Nimm es von mir, und ich will meine Tote dort begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Und Ephron antwortete Abraham und sprach zu ihm:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Mein Herr, höre mich: Ein Land, vierhundert Schekel Silbers wert, was ist das zwischen mir und dir? So begrabe nun deine Tote.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Und Abraham hörte auf Ephron; und Abraham wog Ephron das Silber dar, wie dieser vor den Ohren der Söhne Cheths geredet hatte, vierhundert Schekel Silbers, wie es beim Händler gangbar ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Und es ward erstanden das Feld Ephrons, das in Machpelah vor Mamre ist, das Feld und die Höhle die darin ist und jeder Baum auf dem Felde, die in all seiner Grenze umher,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Dem Abraham als Erworbenes vor den Augen der Söhne Cheths, vor allen, die zum Tor seiner Stadt eingingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Und danach begrub Abraham Sarah, sein Weib, in der Höhle des Feldes Machpelah, vor Mamre, das ist Chebron, im Lande Kanaan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'Und es war das Feld und die Höhle darin als Grabeigentum von den Söhnen Cheths von Abraham erstanden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Und Abraham war alt, in die Tage gekommen, und Jehovah hatte Abraham in allem gesegnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'Und Abraham sprach zu dem ältesten Knechte seines Hauses, der über alles, was er hatte, herrschte: Lege doch deine Hand unter meine Hüfte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'Und beschwöre dich bei Jehovah, dem Gott der Himmel und dem Gott der Erde, daß du meinem Sohne kein Weib nehmest von den Töchtern des Kanaaniters, in dessen Mitte ich wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'Sondern zu meinem Land und zu meinem Geburtsort sollst du gehen, und meinem Sohne Isaak ein Weib nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'Und der Knecht sprach zu ihm: Vielleicht will das Weib mir nicht zu diesem Lande nachgehen. Soll ich dann deinen Sohn zu dem Land zurückbringen, aus dem du ausgezogen bist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Und Abraham sprach zu ihm: Hüte dich, daß du meinen Sohn dahin zurückbringest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Jehovah, der Gott der Himmel, Der mich vom Hause meines Vaters und von dem Lande meiner Geburt genommen und zu mir geredet, und mir geschworen hat und gesagt: Deinem Samen will Ich dieses Land geben, Der wird Seinen Engel vor dir senden, und du wirst von dorther für meinen Sohn ein Weib nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Und wenn das Weib dir nicht nachgehen will, so bist du dieses Schwurs ledig. Nur bringe meinen Sohn nicht dorthin zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Und der Knecht legte seine Hand unter die Hüfte Abrahams, seines Herrn, und schwur ihm dieses Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Und der Knecht nahm zehn Kamele von den Kamelen seines Herrn, und er ging und alles Gut seines Herrn war in seiner Hand, und er machte sich auf und zog gen Aram der beiden Flüsse, nach der Stadt Nachors.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'Und er ließ die Kamele niederknien außerhalb der Stadt an dem Wasserbrunnen zur Abendzeit, zur Zeit, da die Wasserschöpferinnen herauskommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'Und er sprach: Jehovah, Gott meines Herrn Abraham, laß es doch vor mir heute begegnen, und tue Barmherzigkeit meinem Herrn Abraham.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Siehe, ich stelle mich an die Wasserquelle, und die Töchter der Männer der Stadt kommen heraus, Wasser zu schöpfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Lasse es geschehen, daß das Mädchen, zu der ich spreche: Neige doch deinen Krug, daß ich trinke, und die dann sagt: Trinke, und ich will auch deine Kamele tränken, die sei, die Du für deinen Knecht, für Isaak, bestimmt hast, und daß ich daran erkenne, daß Du mit meinem Herrn Barmherzigkeit tuest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Und es geschah, ehe er die Rede vollendet hatte, siehe, da kam Rebekah heraus, die dem Bethuel geboren ward, dem Sohne Milkahs, des Weibes von Nachor, dem Bruder Abrahams, und ihr Krug war auf ihrer Schulter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Und das Mädchen war sehr gut anzusehen, eine Jungfrau, und kein Mann hatte sie erkannt. Und sie ging zur Quelle hinab und füllte ihren Krug, und kam herauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Und der Knecht lief ihr entgegen und sprach: Bitte, laß mich ein wenig Wasser aus deinem Kruge schlürfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'Und sie sprach: Trinke, mein Herr, und sie eilte und ließ ihren Krug herab auf ihre Hand und tränkte ihn;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'Und als sie ihn zu tränken vollendet, sprach sie: Auch deinen Kamelen will ich schöpfen, bis daß sie vollends getrunken haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'Und sie eilte und ergoß ihren Krug in die Tränke, und lief wieder zum Brunnen, zu schöpfen, und schöpfte für alle seine Kamele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'Und der Mann staunte sie stillschweigend an, um zu erkennen, ob Jehovah seinen Weg gelingen lasse oder nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Und es geschah, da die Kamele aufhörten zu trinken, da nahm der Mann einen goldenen Reif, vom Gewicht eines halben Schekels, und zwei Armbänder an ihre Hände, zehn Goldschekel an Gewicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'Und er sprach: Wessen Tochter bist du? Bitte, sage mir an, ob im Hause deines Vaters ein Ort zum übernachten für uns ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'Und sie sprach zu ihm: Ich bin Bethuels Tochter, des Sohns der Milkah, den sie Nachor gebar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Und sie sprach zu ihm: Auch haben wir viel Stroh und Futter bei uns, auch einen Ort zum übernachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Und der Mann verneigte sich und beugte sich vor Jehovah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'Und sprach: Gesegnet sei Jehovah, der Gott meines Herrn Abraham, der von Seiner Barmherzigkeit und Wahrheit gegen meinen Herrn nicht gelassen; und mich hat Jehovah auf dem Weg nach dem Hause der Brüder meines Herrn geführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Und das Mädchen lief, und sagte es dem Hause ihrer Mutter an, gemäß diesen Worten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Und Rebekah hatte einen Bruder, und sein Name war Laban; und Laban lief hinaus zu dem Manne an der Quelle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'Und es geschah, als er den Reif und die Armbänder an den Händen seiner Schwester sah, und als er hörte die Worte seiner Schwester Rebekah, die sprach: So hat der Mann zu mir geredet, da kam er zu dem Manne, und siehe, er stand bei den Kamelen an der Quelle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'Und er sprach: Komm, Gesegneter Jehovahs, warum stehst du draußen, und ich habe das Haus geräumt, und den Ort für die Kamele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'Und der Mann kam in das Haus; und er löste die Kamele und gab Stroh und Futter den Kamelen, und Wasser, zu waschen seine Füße und die Füße der Männer, die mit ihm waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Und man setzte ihm zu essen vor. Er sprach aber: Ich will nicht essen bis ich meine Worte geredet habe. Und er sprach: Rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Und er sprach: Ich bin Abrahams Knecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Und Jehovah hat meinen Herrn sehr gesegnet, und er ist groß geworden, und Er hat ihm Kleinvieh und Rinder und Silber und Gold und Knechte und Dienstmägde und Kamele und Esel gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Und Sarah, meines Herrn Weib, gebar, nachdem sie alt geworden, meinem Herrn einen Sohn, und er hat ihm alles gegeben, was er hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'Und mein Herr ließ mich schwören, und sagte: Du sollst meinem Sohne kein Weib nehmen von den Töchtern des Kanaaniters, in dessen Lande ich wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Vielmehr sollst du zum Hause meines Vaters und zu meiner Familie gehen, und meinem Sohne ein Weib nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Und ich sprach zu meinem Herrn: Vielleicht wird das Weib mir nicht nachgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'Und er sprach zu mir: Jehovah, vor Dem ich gewandelt bin, wird Seinen Engel mit dir senden, und deinen Weg gelingen lassen, auf daß du meinem Sohne ein Weib von meiner Familie und aus dem Hause meines Vaters nehmest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Dann bist du deines Eides ledig, wenn du zu meiner Familie kommst, und sie dir sie nicht geben; dann bist du deines Eides ledig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Und ich kam heute zu der Quelle, und sprach: Jehovah, Gott meines Herrn Abraham, sei es doch, daß Du den Weg, auf dem ich gehe, gelingen lassest!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Siehe ich stelle mich an die Wasserquelle, und es geschehe, daß die Jungfrau, die herauskommt zu schöpfen, und zu der ich spreche, gib mir doch ein wenig Wasser zu trinken aus deinem Krug,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'Und die zu mir sagt: Trinke du, und ich will auch deinen Kamelen schöpfen; daß sie das Weib sei, die Jehovah für den Sohn meines Herrn bestimmt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Ehe ich vollendet zu reden zu meinem Herzen, und siehe, da kommt Rebekah heraus und ihr Krug auf ihrer Schulter und sie ging zur Quelle hinab und schöpfte; und ich sprach zu ihr: Gib mir doch zu trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Und sie eilte und ließ ihren Krug von sich herab und sprach: Trinke, und ich will auch deine Kamele tränken; und ich trank und auch die Kamele tränkte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Und ich fragte sie und sprach: Wessen Tochter bist du? Und sie sprach: Ich bin die Tochter Bethuels, des Sohns von Nachor, den ihm Milkah gebar. Und ich legte den Reif an ihre Nase und die Armbänder an ihre Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'Und ich verneigte und verbeugte mich vor Jehovah und segnete Jehovah, den Gott meines Herrn Abraham, Der mich auf den Weg der Wahrheit geführt, um die Tochter von meines Herrn Bruder seinem Sohne zu nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Und nun, wenn es bei euch ist Barmherzigkeit und Wahrheit an meinem Herrn zu tun, sagt es mir an, und wo nicht, so sagt es mir an, auf daß ich das Gesicht zur Rechten oder zur Linken wende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'Und Laban antwortete und Bethuel und sie sprachen: Von Jehovah geht das Wort aus, wir vermögen nicht zu dir zu reden, weder Böses noch Gutes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Siehe Rebekah ist vor dir, nimm sie und gehe, und sie sei das Weib des Sohnes deines Herrn, wie Jehovah geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'Und es geschah, wie der Knecht Abrahams ihre Worte hörte, verbeugte er sich zur Erde vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'Und der Knecht brachte silberne Geräte und goldene Geräte und Kleider heraus und gab sie der Rebekah, und Kostbarkeiten gab er ihrem Bruder und ihrer Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Und sie aßen und tranken, er und die Männer, die mit ihm waren, und sie übernachteten. Und sie standen am Morgen auf und er sprach: Entsendet mich zu meinem Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Und ihr Bruder und ihre Mutter sprachen: Laß das Mädchen etwa zehn Tage bei uns bleiben, danach magst du gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Er aber sprach zu ihnen: Haltet mich nicht auf; denn Jehovah hat meinen Weg gelingen lassen. Entsendet mich, daß ich zu meinem Herrn gehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Und sie sprachen: Wir wollen das Mädchen rufen und ihren Mund fragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'Und sie riefen Rebekah, und sprachen zu ihr: Willst du mit diesem Manne gehen? Und sie sprach: Ich will gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'Und sie entsandten Rebekah, ihre Schwester und ihre Amme, und Abrahams Knecht und seine Männer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'Und sie segneten Rebekah, und sprachen zu ihr: Du bist unsere Schwester. Werde zu tausenden der Zehntausend, und dein Same besitze erblich das Tor seiner Hasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Und Rebekah machte sich auf und ihre Mädchen, und sie ritten auf den Kamelen und gingen dem Manne nach. Und der Knecht nahm Rebekah und ging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Und Isaak kam von einem Gange nach dem Brunnen Lachai-Roi; und er wohnte im Lande des Mittags.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'Und Isaak war, als sich der Abend wendete, in das Feld hinausgegangen zu sinnen, und er hob seine Augen auf, und sah, und siehe, Kamele kamen daher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'Und Rebekah hob ihre Augen auf, und sah Isaak, und sie glitt herab vom Kamel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'Und sie sprach zu dem Knechte: Wer ist der Mann da, der auf dem Feld geht uns entgegen? Und der Knecht sprach: Das ist mein Herr. Und sie nahm den Schleier und bedeckte sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Und der Knecht erzählte Isaak alles, was er getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'Und Isaak brachte sie herein in das Zelt seiner Mutter Sarah, und nahm Rebekah, und sie ward sein Weib, und er liebte sie. Und Isaak ward getröstet nach seiner Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Und Abraham nahm wieder ein Weib, und ihr Name war Keturah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Und sie gebar ihm Simran und Jokschan und Medan und Midjan und Jischbak und Schuach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Und Jokschan zeugte Scheba und Dedan, und die Söhne Dedans waren die Aschurim und die Letuschim und die Leumim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Und die Söhne Midjans waren Ephah und Epher und Chanoch und Abidah und Eldaah. Alle diese waren Söhne Keturahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'Und Abraham gab all das Seine dem Isaak.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Und den Söhnen der Kebsweiber, die Abraham hatte, gab Abraham Gaben, und entsandte sie weg von seinem Sohne Isaak, noch während er lebte, gegen Osten, in das Land des Ostens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Und dies sind die Tage der Jahre des Lebens Abrahams, die er lebte: hundert Jahre und siebzig Jahre und fünf Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Und Abraham verschied und starb in gutem Greisenalter, alt und satt, und ward zu seinen Völkern versammelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'Und es begruben ihn Isaak und Ismael, seine Söhne, in die Höhle Machpelah, nach dem Felde Ephrons, des Sohnes Zochar, des Chethiters, das ob dem Angesichte von Mamre ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'Auf dem Felde, das Abraham von den Söhnen Chets erworben, da ward Abraham und Sarah, sein Weib, begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'Und es geschah nach dem Tode Abrahams, daß Gott segnete Isaak, seinen Sohn; und Isaak wohnte bei dem Brunnen Lachai-Roi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Und dies sind die Geburten Ismaels, des Sohnes Abrahams, den Hagar die Ägypterin, die Dienstmagd Sarahs, dem Abraham gebar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'Und dies sind die Namen der Söhne Ismaels in ihren Namen nach ihren Geburten: der Erstgeborene Ismaels Nebajoth, und Kedar und Adbeel und Mibsam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'Und Mischma und Dumah und Massa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Chadar und Thema, Jetur, Naphisch und Kedmah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Dies sind sie, die Söhne Ismaels, und dies ihre Namen in ihren Gehöften und in ihren Zeltlagern zwölf Fürsten ihrer Volksstämme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Und dies sind die Jahre des Lebens Ismaels: hundert Jahre und dreißig Jahre und sieben Jahre. Und er verschied und starb, und ward zu seinen Völkern versammelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Und sie wohnten von Chavilah bis Schur, das ob den Angesichten Ägyptens ist, wenn man nach Aschur kommt; vor allen seinen Brüdern fiel er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Und dies sind die Geburten Isaaks des Sohnes Abrahams: Abraham zeugte Isaak.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'Und Isaak war vierzig Jahre alt als er Rebekah, die Tochter Bethuels, des Aramiten von Padan Aram, die Schwester Labans, des Aramiten, sich zum Weibe nahm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'Und Isaak flehte wegen seines Weibes zu Jehovah; denn sie war unfruchtbar, und Jehovah ließ sich von ihm erflehen, und Rebekah, sein Weib, empfing.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'Und die Stöhne stießen sich in ihrer Mitte, und sie sprach: Wenn dem so ist, warum bin ich so? Und sie ging Jehovah zu fragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Und Jehovah sprach zu ihr: Zwei Völkerschaften sind in deinem Leibe, und zwei Volksstämme werden sich aus deinen Eingeweiden trennen; und ein Volksstamm wird stärker als der andere Volksstamm und der Große wird dem Kleinen dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Und die Tage erfüllten sich, daß sie gebären sollte, und siehe Zwillinge waren in ihrem Leibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Und der erste kam heraus, ganz rötlich, wie ein haariger Mantel, und sie nannten seinen Namen Esau.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Und nachher kam sein Bruder heraus, und seine Hand ergriff die Ferse Esaus und man nannte seinen Namen Jakob. Und Isaak war sechzig Jahre alt, da sie geboren wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'Und die Jungen wurden groß, und Esau war ein Mann kundig der Jagd, ein Mann des Feldes; und Jakob war ein untadeliger Mann, und wohnte in den Zelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Und Isaak liebte den Esau; denn Wildbret war in seinem Munde; und Rebekah liebte Jakob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'Und Jakob kochte ein Gemüse und Esau kam vom Felde und war matt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'Und Esau sprach zu Jakob: Laß mich doch von dem Roten, diesem Roten da kosten, denn ich bin matt. Deshalb nannte man seinen Namen Edom.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Und Jakob sprach: Verkaufe mir wie heute deine Erstgeburt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Und Esau sagte: Siehe, ich gehe hin zu sterben, und wozu ist mir da die Erstgeburt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'Und Jakob sprach: Schwöre mir wie heute; und er schwur ihm, und verkaufte seine Erstgeburt dem Jakob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'Und Jakob gab dem Esau Brot und das Gemüse von Linsen; und er aß und trank und stand auf und ging. Und Esau verachtete die Erstgeburt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Und es war eine Hungersnot im Lande außer der ersten Hungersnot, die in den Tagen Abrahams war; und Isaak ging zu Abimelech, dem Könige der Philister nach Gerar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Und Jehovah erschien ihm, und sprach: Geh nicht nach Ägypten hinab, sondern wohne in dem Lande, das Ich dir sage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Halte dich in diesem Lande auf, und Ich will mit dir sein und will dich segnen; denn dir und deinem Samen will Ich alle diese Lande geben und den Schwur bestätigen, den Ich Abraham, deinem Vater, geschworen habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'Und Ich will mehren deinen Samen wie die Sterne der Himmel, und deinem Samen alle diese Lande geben, und es sollen in deinem Samen gesegnet werden alle Völkerschaften der Erde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'Infolge davon, daß Abraham Meiner Stimme gehorchte, und Meine Verordnung, Meine Gebote, Meine Satzungen und Meine Gesetze hielt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Und Isaak wohnte in Gerar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'Und die Männer des Ortes fragten über sein Weib, und er sagte: Sie ist meine Schwester; denn er fürchtete sich zu sagen: Sie ist mein Weib, damit die Männer des Ortes ihn nicht erwürgeten ob Rebekah; denn sie war gut von Ansehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Und es geschah, als seine Tage dort sich verlängerten, daß Abimelech, König der Philister, durch das Fenster schaute und sah, und siehe, Isaak lachte mit Rebekah, seinem Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Und Abimelech rief den Isaak, und sprach: Siehe doch, sie ist dein Weib! und was sagtest du: sie ist meine Schwester? Und Isaak sprach zu ihm: Weil ich sagte, damit ich nicht sterbe wegen ihrer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Und Abimelech sagte. Warum hast du uns das getan? Um ein kleines, so wäre einer vom Volke bei deinem Weibe gelegen, und du hättest eine Schuld über uns gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'Und Abimelech gebot allem Volk und sprach: Wer diesen Mann und sein Weib berührt, der soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'Und Isaak säte in diesem Lande, und fand desselbigen Jahres hundert Maße; und Jehovah segnete ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'Und der Mann ward groß, und ging hin und ward groß, bis er sehr groß war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'Und er hatte Besitztum an Kleinvieh und Besitztum an Rindern, und viele Knechte, und die Philister beneideten ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'Und alle die Brunnen seines Vaters, welche die Knechte seines Vaters in den Tagen seines Vaters Abraham gegraben hatten, verstopften die Philister und füllten sie mit Staub.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'Und Abimelech sprach zu Isaak: Gehe von uns, denn du bist uns zu sehr mächtig geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Und Isaak ging von dannen, und lagerte im Bachtal Gerar, und wohnte allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Und Isaak grub wieder die Wasserbrunnen auf, die sie in den Tagen seines Vaters Abraham gegraben, die Philister aber nach dem Tode Abrahams verstopft hatten, und nannte sie mit Namen, nach den Namen, womit sein Vater sie genannt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'Und die Knechte Isaaks gruben in dem Bachtal, und fanden dort einen Brunnen lebendigen Wassers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Und die Hirten von Gerar haderten mit den Hirten Isaaks, und sprachen: Unser ist das Wasser. Und er nannte den Namen des Brunnens Esek, weil sie mit ihm gezankt hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'Und sie gruben einen anderen Brunnen, und sie haderten auch über diesen, und er nannte seinen Namen Sitnah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Und von da zog er weiter, und grub einen anderen Brunnen, und über den haderten sie nicht; und er nannte seinen Namen Rechoboth, und sprach: Denn nun hat uns Jehovah breit werden lassen, und wir werden fruchtbar sein im Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Und von da ging er hinauf gen Beerschaba.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Und Jehovah erschien ihm in derselben Nacht und sprach: Ich bin der Gott Abrahams deines Vaters, fürchte dich nicht; denn Ich bin mit dir und segne dich, und will deinen Samen mehren um Abrahams, Meines Knechtes, willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'Und er baute allda einen Altar und rief den Namen Jehovahs an, und schlug daselbst sein Zelt auf. Und die Knechte Isaaks bohrten hier einen Brunnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Und Abimelech ging zu ihm von Gerar, und Achusath sein Genosse und Pichol, der Oberste seines Heeres.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'Und Isaak sprach zu ihnen: Warum kommet ihr zu mir, und ihr hasset mich und habt mich von euch fortgesandt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Sie aber sprachen: Wir haben gesehen, daß Jehovah mit dir ist, und da sagten wir: Es sei doch ein Eid zwischen uns, zwischen uns und zwischen dir, und wir wollen einen Bund mit dir schließen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'Daß du an uns nichts Böses tuest, wie wir dich nicht berührt, und wie wir an dir nur Gutes getan, und dich in Frieden entsandten: Nun bist du ein Gesegneter Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'Und er machte ihnen ein Gastmahl, und sie aßen und tranken:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Und sie standen früh am Morgen auf und schwuren einander; und Isaak entsandte sie, und sie gingen von ihm im Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Und es geschah an diesem Tage, daß Isaaks Knechte kamen und sagten ihm an, wegen dem Brunnen, den sie gegraben, und sie sprachen zu ihm: Wir haben Wasser gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'Und er nannte ihn Schibah, weshalb der Name der Stadt bis auf diesen Tag Beerscheba ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Und Esau war vierzig Jahre alt, und er nahm zum Weibe Jehudith, die Tochter Beeris, des Chethiters, und Basemath, die Tochter des Chethiters Elon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'Und sie waren für Isaak und Rebekah Bitterkeit des Geistes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Und es geschah als Isaak alt geworden, und seine Augen getrübt wurden zum Sehen, daß er seinen größeren Sohn Esau rief und zu ihm sprach: Mein Sohn! Und er sprach: Siehe, hier bin ich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Und er sprach: Siehe doch, ich bin alt geworden, ich weiß nicht den Tag meines Todes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Und nun nimm doch dein Geräte, deinen Köcher und deinen Bogen, und geh hinaus auf das Feld und jage mir ein Wildbret,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'Und mache mir ein schmackhaftes Gericht, wie ich es liebe, und bringe mir es herein, daß ich esse, auf daß dich meine Seele segne bevor ich sterbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Und Rebekah hörte, wie Isaak zu Esau, seinem Sohne, redete, und wie Esau auf das Feld ging, daß er ein Wildbret jage und es hereinbrächte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'Und Rebekah sagte zu ihrem Sohne Jakob und sprach: Siehe, ich hörte deinen Vater zu deinem Bruder Esau reden und sagen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Bring mir ein Wildbret herein und mache mir ein schmackhaftes Gericht, daß ich esse, und dich segne vor Jehovah, bevor ich sterbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Und nun, mein Sohn, höre auf meine Stimme, was ich dir gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Geh doch zum Kleinvieh und hole mir von dort zwei gute Böcklein von den Ziegen, daß ich davon deinem Vater ein schmackhaftes Gericht mache, wie er es liebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'Und du bringst es deinem Vater hinein, daß er esse, auf daß er dich segne, bevor er stirbt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Und Jakob sprach zu Rebekah, seiner Mutter: Siehe, Esau, mein Bruder, ist ein behaarter Mann und ich bin ein glatter Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Vielleicht betastet mich mein Vater und ich wäre in seinen Augen als Einer, der irreführt, und bringe Fluch herein über mich und nicht Segen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Und seine Mutter sprach zu ihm: Auf mir sei dein Fluch, mein Sohn. Nur höre auf meine Stimme, und geh und hole mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Und er ging und holte, und brachte sie seiner Mutter, und seine Mutter machte ein schmackhaftes Gericht, wie es sein Vater liebte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Und Rebekah nahm die köstlichen Kleider ihres größeren Sohnes Esau, die bei ihr im Hause waren, und ließ sie ihren kleineren Sohn Jakob anziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'Und sie tat ihm die Felle der Ziegenböcklein auf seine Hände und auf die Glätte seines Halses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'Und gab das schmackhafte Gericht und das Brot, das sie gemacht, in die Hand ihres Sohnes Jakob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'Und er ging hinein zu seinem Vater und sprach: Mein Vater! Und er sprach: Siehe, hier bin ich. Wer bist du, mein Sohn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Und Jakob sprach zu seinem Vater: Ich bin Esau, dein Erstgeborener, ich habe getan, wie du zu mir geredet hast. Mache dich doch auf, sitze und iß von meinem Wildbret, auf daß mich segne deine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Und Isaak sprach zu seinem Sohne: Wie hast du so eilends gefunden, mein Sohn? Und er sprach: Jehovah, dein Gott, ließ es meinem Angesichte entgegenkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Und Isaak sprach zu Jakob: Tritt doch herzu, daß ich dich betaste, mein Sohn, ob du da mein Sohn Esau bist oder nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Und Jakob trat hinzu zu seinem Vater Isaak, und er betastete ihn und sprach: Die Stimme ist Jakobs Stimme, und die Hände sind Esaus Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'Und er erkannte ihn nicht; denn seine Hände waren wie die Hände Esaus, seines Bruders, haarig, und er segnete ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'Und er sprach, bist du da mein Sohn Esau? Und er sprach: Ich bin es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'Und er sprach: Reiche mir her, daß ich esse von dem Wildbret meines Sohnes, auf daß meine Seele dich segne. Und er reichte es ihm her und er aß, und er brachte ihm Wein herein und er trank.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Und Isaak, sein Vater, sprach zu ihm: Tritt doch herzu und küsse mich, mein Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Und er trat hinzu und küßte ihn. Und er roch den Geruch seiner Kleider, und segnete ihn und sprach: Siehe, der Geruch meines Sohnes ist wie der Geruch des Feldes, das Jehovah gesegnet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Und Gott gebe dir von dem Tau des Himmels und von dem Fett der Erde und viel Korn und Most.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Völker sollen dir dienen und Volksstämme sich vor dir verbeugen. Sei ein Gebieter über deine Brüder, und deiner Mutter Söhne sollen sich vor dir verbeugen. Verflucht sei, wer dich verflucht! Und gesegnet sei, wer dich segnet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Und es geschah, als Isaak Jakobs Segen vollendet und Jakob kaum von dem Angesichte seines Vaters Isaak hinausgegangen war, daß Esau, sein Bruder, kam von seiner Jagd.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'Und auch er machte ein schmackhaftes Gericht, und brachte es seinem Vater herein und sprach zu seinem Vater: Mein Vater mache sich auf und esse von dem Wildbret seines Sohnes, auf daß deine Seele mich segne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Und sein Vater Isaak sprach zu ihm: Wer bist du? Und er sprach: Ich bin dein Sohn, dein Erstgeborener, Esau.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Und Isaak zitterte mir sehr großem Zittern und sprach: Wer war dann der, so das Wildbret jagte und mir hereinbrachte? Und ich aß von allem ehe du kamst und segnete ihn. Gesegnet soll er auch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Wie Esau die Worte seines Vaters hörte, tat er einen großen, sehr bitteren Schrei, und sprach zu seinem Vater: Segne mich, auch mich, mein Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'Und er sprach: Dein Bruder ist trüglich gekommen und hat deinen Segen genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'Und er sprach: Hat man seinen Namen nicht Jakob genannt? Und diese zweimal hat er mich überlistet. Meine Erstgeburt hat er genommen, und siehe, jetzt nimmt er meinen Segen. Und er sprach: Hast du denn keinen Segen mehr für mich vorbehalten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Und Isaak antwortete und sprach zu Esau: Siehe, zum Gebieter habe ich ihn über dich gesetzt, und alle seine Brüder ihm zu Knechten gegeben, mit Korn und Most ihn gekräftigt. Und nun, was soll ich tun für dich, mein Sohn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Und Esau sprach zu seinem Vater: Hattest du nur diesen einen Segen, mein Vater? Segne mich, auch mich, mein Vater! Und Esau hob auf seine Stimme und weinte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'Und sein Vater Isaak antwortete und sprach zu ihm: Siehe, vom Fetten des Landes wird dein Wohnsitz sein, und von dem Tau des Himmels von oben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'Und du wirst ob deinem Schwerte leben und deinem Bruder dienen. Und es wird geschehen, wenn du herrschen wirst, daß du sein Joch von deinem Halse abreißest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'Und Esau grollte dem Jakob ob dem Segen, womit sein Vater ihn gesegnet hatte; und Esau sprach in seinem Herzen: Es nahen die Tage der Trauer für meinen Vater und ich erwürge Jakob, meinen Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'Und es wurden Rebekah die Worte Esaus, ihres größeren Sohnes angesagt, und sie sandte und rief Jakob, ihren kleineren Sohn, und sprach zu ihm: Siehe, Esau, dein Bruder, vertröstet sich wegen dir und will dich erwürgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Und nun, mein Sohn, höre auf meine Stimme und mache dich auf, entweiche zu meinem Bruder Laban nach Charan,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Und bleibe einige Tage bei ihm, bis sich der Grimm deines Bruders zurückgewendet hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'Bis sich zurückgewendet hat der Zorn deines Bruders wider dich, und er vergessen hat, was du ihm getan, und ich werde senden und dich von dort holen. Warum sollte ich auch euer beider an einem Tage beraubt werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Und Rebekah sprach zu Isaak: Mir ist das Leben zum Überdruß vor den Töchtern Cheths; wenn Jakob ein Weib nehmen soll von den Töchtern Cheths, wie die da von den Töchtern des Landes, was soll mir dann das Leben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Und Isaak rief dem Jakob und er segnete ihn und gebot ihm und sprach zu ihm: Du sollst dir kein Weib von den Töchtern Kanaans nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Mache dich auf, geh nach Padan Aram zu dem Hause Bethuels, des Vaters deiner Mutter, und nimm dir von da ein Weib von den Töchtern Labans, des Bruders deiner Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'Und Gott Schaddai wird dich segnen und dich fruchtbar machen und dich mehren, daß du zu einer Versammlung von Völkern werdest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'Und wird dir geben den Segen Abrahams, dir und deinem Samen mit dir, auf daß du das Land deiner Wanderungen erblich besitzest, das Gott dem Abraham gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Und Isaak entsandte den Jakob, und er ging nach Padan Aram zu Laban, dem Sohne Bethuels, des Aramiters, dem Bruder der Rebekah, der Mutter Jakobs und Esaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'Und Esau sah, daß Isaak den Jakob segnete und nach Padan Aram sandte, um sich von dort ein Weib zu holen, und ihm mit seinem Segen gebot und sprach: Du sollst dir kein Weib von den Töchtern Kanaans nehmen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'Und daß Jakob seinem Vater und seiner Mutter gehorchte und nach Padan Aram ging;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Und Esau sah, daß die Töchter Kanaans böse waren in den Augen seines Vaters Isaak;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Und Esau ging zu Ismael, und nahm über seine Weiber Machalath, die Tochter Ismaels, des Sohns von Abraham, eine Schwester des Nebajoth zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Und Jakob ging aus von Beerschaba und ging nach Charan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'Und er stieß auf einen Ort und übernachtete daselbst, denn die Sonne war untergegangen; und er nahm von den Steinen des Ortes und legte sie zu seinen Häupten, und legte sich an demselben Orte nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'Und es träumte ihm, und siehe, eine Leiter war auf die Erde gestellt und ihre Spitze berührte den Himmel, und siehe, die Engel Gottes stiegen auf und stiegen nieder daran.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'Und siehe, Jehovah stand oben darauf und sprach: Ich bin Jehovah, der Gott Abrahams, deines Vaters, und der Gott Isaaks. Das Land, darauf du liegst, will Ich dir und deinem Samen geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'Und dein Same soll wie der Staub der Erde sein, und du sollst hervorbrechen nach dem Meere zu und nach Osten und nach Norden und nach Mittag; und alle Familien des Bodens sollen in dir und deinem Samen gesegnet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Und siehe, Ich bin mit dir, und werde dich behüten überall, wohin du gehst, und dich zurückbringen auf diesen Boden; denn Ich werde dich nicht verlassen, bis daß Ich getan habe, was Ich zu dir geredet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'Und Jakob erwachte von seinem Schlaf und sprach: Fürwahr, Jehovah ist an diesem Orte und ich wußte es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'Und er fürchtete sich und sprach: Wie furchtbar ist dieser Ort! Hier ist nichts denn Gottes Haus; und dies ist das Tor des Himmels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'Und Jakob stand früh am Morgen auf, und nahm den Stein, den er zu seinen Häupten gelegt hatte und setzte ihn auf zu einer Denksäule, und goß Öl oben darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'Und er nannte den Namen dieses Ortes Bethel. Früher aber war der Name der Stadt Lus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'Und Jakob gelobte ein Gelübde und sprach: Wenn Gott mit mir sein und mich behüten wird auf diesem Wege, den ich gehe, und mir Brot zu essen und ein Kleid zum Anziehen gibt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'Und ich in Frieden zum Hause meines Vaters zurückkehre, so soll Jehovah mir zum Gotte sein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'Und dieser Stein, den ich zur Denksäule gesetzt, soll sein ein Gotteshaus; und alles, was Du mir geben wirst, will ich Dir verzehnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Und Jakob hob seine Füße auf, und ging nach dem Lande der Söhne des Ostens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Und er sah, und siehe, ein Brunnen auf dem Felde, und siehe, dabei waren drei Herden Kleinvieh gelagert; denn von diesem Brunnen tränkten sie die Herden; und ein großer Stein war auf der Mündung des Brunnens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Und dorthin versammelten sich alle Herden, und sie wälzten den Stein von der Mündung des Brunnens und tränkten das Kleinvieh, und brachten den Stein zurück auf die Mündung des Brunnens an seinen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'Und Jakob sprach zu ihnen: Meine Brüder, woher seid ihr? Und sie sprachen: Von Charan sind wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'Und er sprach zu ihnen: Kennet ihr Laban, den Sohn Nachors? Und sie sprachen: Wir kennen ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Und er sprach zu ihnen: Hat er Frieden? Und sie sprachen: Frieden; und siehe, Rachel, seine Tochter, kommt mit dem Kleinvieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Und er sprach: Siehe, der Tag ist noch lang, es ist nicht die Zeit, die Viehherden zu versammeln. Tränket das Kleinvieh und gehet, weidet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Und sie sprachen: Wir können nicht, bevor die Herden alle versammelt sind, da wälzen sie den Stein von der Mündung des Brunnens und wir tränken das Kleinvieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Noch redete er mit ihnen, da kam Rachel mit dem Kleinvieh ihres Vaters; denn sie war Hirtin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'Und es geschah, wie Jakob Rachel, die Tochter Labans, des Bruders seiner Mutter, und das Kleinvieh Labans, des Bruders seiner Mutter sah, da trat Jakob herzu und wälzte den Stein von der Mündung des Brunnens und tränkte das Kleinvieh Labans, des Bruders seiner Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'Und Jakob küßte Rachel, und hob seine Stimme auf und weinte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'Und Jakob sagte der Rachel an, daß er ein Bruder ihres Vaters und ein Sohn Rebekahs sei. Und sie lief und sagte es ihrem Vater an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'Und es geschah, als Laban die Kunde von Jakob, dem Sohne seiner Schwerster, hörte, da lief er ihm entgegen und umarmte ihn und küßte ihn, und brachte ihn in sein Haus herein. Und er erzählte Laban alle diese Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'Und Laban sprach zu ihm: Fürwahr, du bist mein Bein und mein Fleisch, und er wohnte bei ihm einen Monat von Tagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Und Laban sprach zu Jakob: Solltest du, weil du mein Bruder bist, mir umsonst dienen? Sage mir an, was soll dein Lohn sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Und Laban hatte zwei Töchter, die ältere mit Namen Leah und die Jüngere mit Namen Rachel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Und Leahs Augen waren blöde, Rachel aber war schön von Gestalt und schön von Ansehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'Und Jakob liebte Rachel und sprach: Ich will dir sieben Jahre um Rachel, deine jüngste Tochter, dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'Und Laban sprach: Es ist besser, ich gebe sie dir, als daß ich sie einem anderen Manne gebe; bleibe bei mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Und Jakob diente um Rachel sieben Jahre; und sie waren in seinen Augen wie einige Tage, in seiner Liebe für sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Und Jakob sprach zu Laban: Gib mir mein Weib; denn meine Tage sind erfüllt, daß ich zu ihr komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'Und Laban versammelte alle Männer des Ortes und machte ein Gastmahl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Und es geschah am Abend, da nahm er Leah, seine Tochter, und brachte sie zu ihm hinein, und er ging zu ihr ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'Und Laban gab ihr Silpah seine Dienstmagd, seiner Tochter Leah zur Dienstmagd.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'Und es war am Morgen - siehe, da war es Leah. Und er sprach zu Laban: Warum hast du mir das getan? Habe ich nicht bei dir um Rachel gedient, und warum hast du mich betrogen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Und Laban sprach: Man tut nicht also in unserem Orte, daß man die Jüngere gibt vor der Erstgeborenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Erfülle diese Woche, dann wollen wir dir auch diese geben um den Dienst, den du bei mir noch andere sieben Jahre dienen sollst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'Und Jakob tat also, und erfüllte diese Woche, und er gab ihm Rachel, seine Tochter, ihm zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'Und Laban gab Rachel, seiner Tochter, seine Dienstmagd Bilhah, ihr zur Dienstmagd.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'Und er kam auch zu Rachel und liebte auch die Rachel mehr denn die Leah, und diente bei ihm noch andere sieben Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Und Jehovah sah, daß Leah gehaßt wurde und Er öffnete ihren Mutterschoß, Rachel aber war unfruchtbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'Und Leah empfing und gebar einen Sohn und sie nannte seinen Namen Ruben; denn, sprach sie, Jehovah hat mein Elend gesehen. Denn jetzt wird mich mein Mann lieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'Und sie empfing wieder und gebar einen Sohn, und sprach: Jehovah hat gehört, daß ich gehaßt bin und hat mir auch diesen gegeben, und nannte seinen Namen Schimeon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'Und sie empfing wieder und gebar einen Sohn, und sprach: Jetzt, diesmal wird mein Mann mir anhangen, denn ich habe ihm drei Söhne geboren; deshalb nannte sie seinen Namen Levi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Und sie empfing wieder und gebar einen Sohn, und sprach: Diesmal bekenne ich Jehovah; daher nannte sie seinen Namen Jehudah, und sie hörte auf zu gebären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Und Rachel sah, daß sie dem Jakob nicht gebar, und Rachel eiferte wider ihrer Schwester und sprach zu Jakob: Gib mir Söhne und wo nicht, so sterbe ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'Und es entbrannte Jakobs Zorn wider Rachel, und er sprach: Bin ich an Gottes Statt, Der dir die Frucht des Leibes vorenthält?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Und sie sprach: Siehe, da ist meine Magd Bilhah. Komm zu ihr, auf daß sie auf meinen Knien gebäre, und auch ich aus ihr aufgebaut werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'Und sie gab ihm Bilhah, ihre Dienstmagd zum Weibe, und Jakob kam zu ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Und Bilhah empfing und gebar dem Jakob einen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Und Rachel sprach: Gott hat für mich gerechtet und auch auf meine Stimme gehört und mir einen Sohn gegeben; daher nannte sie seinen Namen Dan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Und Bilhah, Rachels Dienstmagd, empfing wieder und gebar Jakob einen zweiten Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'Und Rachel sprach: Mit dem Ringen Gottes habe ich mit meiner Schwester gerungen, auch sie übermocht, und nannte seinen Namen Naphthali.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Und Leah sah, daß sie aufhörte zu gebären, und sie nahm Silpah, ihre Dienstmagd und gab sie Jakob zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'Und Silpah, Leahs Dienstmagd, gebar Jakob einen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'Und Leah sprach: Mit einer Schar! und sie nannte seinen Namen Gad.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'Und Silpah, Leahs Dienstmagd, gebar dem Jakob einen zweiten Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'Und Leah sprach: Zu meiner Seligkeit! denn selig preisen mich die Töchter; und sie nannte seinen Namen Ascher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'Und Ruben ging in den Tagen der Weizenernte und fand Dudaim auf dem Felde und brachte sie Leah, seiner Mutter. Und Rachel sprach zu Leah: Gib mir doch von den Dudaim deines Sohnes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Und sie sprach zu ihr: ist es ein Kleines, daß du meinen Mann genommen hast, daß du auch die Dudaim meines Sohnes nehmen willst? Und Rachel sagte: Darum soll er denn diese Nacht bei dir liegen für deines Sohnes Dudaim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'Und Jakob kam am Abend vom Felde, und Leah ging hinaus ihm entgegen und sprach: Zu mir sollst du kommen, denn ich habe dich mit meines Sohnes Dudaim gedingt. Und er lag diese Nacht bei ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Und Gott erhörte Leah, und sie empfing und gebar dem Jakob einen fünften Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'Und Leah sprach: Gott hat mir dafür meinen Lohn gegeben, daß ich meine Dienstmagd meinem Manne gab, und sie nannte seinen Namen Isaschar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'Und Leah empfing wieder und gebar dem Jakob den sechsten Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'Und Leah sprach: Gott hat mir eine gute Bescherung beschert. Diesmal wird mein Mann mir beiwohnen, denn sechs Söhne habe ich ihm geboren; und sie nannte seinen Namen Sebulon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'Und danach gebar sie eine Tochter, und sie nannte ihren Namen Dinah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Und Gott gedachte der Rachel, und Gott hörte auf sie und öffnete ihren Mutterschoß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'Und sie empfing und gebar einen Sohn und sprach: Gott hat meine Schmach von mir weggenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'Und sie nannte seinen Namen Joseph, und sprach: Jehovah wolle mir einen anderen Sohn hinzutun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Und es geschah, als Rachel den Joseph geboren hatte, da sprach Jakob zu Laban: Entsende mich, daß ich nach meinem Orte und meinem Lande gehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Gib mir meine Weiber und meine Kinder, für die ich dir gedient, und ich will gehen; denn du weißt meinen Dienst, damit ich dir gedient.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Und Laban sprach zu ihm: Möchte ich doch Gnade in deinen Augen finden. Ich deute mir, daß Jehovah deinetwegen mich gesegnet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Und er sprach: Benenne deinen Lohn bei mir, und ich gebe dir ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Und er sprach zu ihm: Du weißt, wie ich dir gedient habe, und was deine Vieherde unter mir geworden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Denn wenig war es, das du vor mir hattest, und es ist zur Menge hervorgebrochen, und Jehovah hat dich durch meinen Fuß gesegnet, und nun, wann soll auch ich etwas für mein Haus tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'Und er sprach: Was soll ich dir geben? Und Jakob sprach: Du sollst mir nichts geben. Wenn du mir tust nach diesem Worte, so kehre ich zurück, weide dein Kleinvieh, hüte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'Ich will heute durch all dein Kleinvieh durchgehen, und daraus jedes gesprenkelte und gefleckte Lamm, und jedes schwarze Lamm unter den Schafen, und jedes gefleckte und gesprenkelte unter den Ziegen wegnehmen; und soll mein Lohn sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'Und antworten soll für mich meine Gerechtigkeit am morgenden Tage, wenn du über meinen Lohn, der vor dir ist, kommen wirst. Alles, was nicht gesprenkelt und gefleckt unter den Ziegen und schwarz unter den Schafen ist, das sei bei mir gestohlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'Und Laban sprach: Siehe, es geschehe nach deinem Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'Und an demselben Tage nahm er die bunten und gefleckten Böcke und alle gesprenkelten und gefleckten Ziegen, alle, an denen etwas Weißes war, weg, und alles Schwarze unter den Schafen, und gab sie in die Hand seiner Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'Und er setzte einen Weg von drei Tagen zwischen sich und zwischen Jakob. Und Jakob weidete des übrige Kleinvieh Labans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Und Jakob nahm sich frische Stöcke von Weißpappel und Hasel und Platane, und schälte weiße Streifen darein, so daß das Weiße an den Stöcken entblößt wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'Und er stellte die Stöcke, die er geschält hatte, in die Rinnen in den Tränken des Wassers, zu denen das Kleinvieh kam, um zu trinken, dem Kleinvieh gegenüber auf, daß sie brünstig würden, wenn sie kämen zu trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Und das Kleinvieh wurde brünstig bei den Stöcken, und das Kleinvieh gebar bunte, gesprenkelte und gefleckte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'Und die Schafe trennte Jakob und wandte die Angesichter des Kleinviehs gegen das Bunte und alles Schwarze unter dem Kleinvieh Labans, und er stellte Herden für sich besonders, und er stellte sie nicht zu Labans Kleinvieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'Und es geschah, daß, sobald die Feisteren der Herde brünstig wurden, Jakob die Stöcke vor die Augen der Herde in die Rinnen legte, damit sie bei den Stöcken brünstig würden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'Aber bei den Späteren des Kleinviehs legte er sie nicht hinein, und so wurden die Späteren Labans, und die Feisteren des Jakob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Und es breitete sich der Mann sehr, sehr aus, und hatte viel Kleinvieh und Dienstmägde und Knechte und Kamele und Esel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Und er hörte die Worte der Söhne Labans, die sagten: Jakob hat alles, was unseres Vaters war, genommen, und von dem, was unseres Vaters war, hat er sich all diese Herrlichkeit gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Und Jakob sah das Angesicht Labans, und siehe, es war nicht mehr mit ihm wie gestern und ehegestern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'Und Jehovah sprach zu Jakob: Kehre zurück in das Land deiner Väter und in deinen Geburtsort, und Ich will mit dir sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'Und Jakob sandte und rief Rachel und Leah ins Feld zu seinem Kleinvieh;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'Und er sprach zu ihnen: Ich sehe, daß eures Vaters Angesicht gegen mich nicht ist wie gestern und ehegestern: und der Gott meines Vaters ist mit mir gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'Und ihr wisset, daß ich mit all meiner Kraft eurem Vater gedient habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Aber euer Vater hat mich hintergangen und meinen Lohn zehnmal abgeändert; aber Gott gab nicht zu, daß er mir Böses täte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Wenn er sagte: Gesprenkelte seien dein Lohn, so hat alles Kleinvieh bunte geboren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Und Gott entriß die Viehherden eures Vaters und gab sie mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Und es geschah zur Zeit der Brunst des Kleinviehs, daß ich meine Augen aufhob und sah im Traum, und siehe: die Böcke, welche das Kleinvieh besprangen, waren bunt und gesprenkelt und getüpfelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'Und der Engel Gottes sprach zu mir im Traum: Jakob! Und ich sprach: Siehe, hier bin ich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'Und Er sprach: Hebe doch deine Augen auf und siehe: Alle Böcke, welche das Kleinvieh bespringen, sind bunt und gesprenkelt und getüpfelt; denn Ich habe alles gesehen, was Laban dir tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Ich bin der Gott Bethels, woselbst du die Denksäule gesalbt, woselbst du Mir ein Gelübde gelobtest. Mache dich nun auf gehe aus von diesem Lande, und kehre nach dem Lande deiner Geburt zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'Und Rachel und Leah antworteten und sprachen zu ihm: Haben wir noch ein Teil und Erbe in unseres Vaters Haus?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Wird unser von ihm nicht als der Auswärtigen gedacht? denn er hat uns verkauft, und unser Silber verzehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Denn aller Reichtum, den Gott unsrem Vater entrissen hat, gehört uns und unseren Söhnen. Und nun, alles, was Gott zu dir gesprochen hat, das tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Und Jakob machte sich auf und hob seine Söhne und seine Weiber auf die Kamele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'Und trieb hinweg all seine Viehherden und all seine Habe, die er gewonnen, und die Viehherden, die er erworben, so er in Padan Aram gewonnen; um zu Isaak, seinem Vater, in das Land Kanaan zu kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Laban aber war gegangen, sein Kleinvieh zu scheren, und Rachel stahl die Theraphim, die ihrem Vater gehörten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Und Jakob stahl das Herz Labans, des Aramiters, indem er ihm nicht ansagte, daß er entweiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Und er entwich, er und alles, das er hatte, und machte sich auf und setzte über den Fluß und richtete sein Angesicht nach dem Berge Gilead.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'Und man sagte am dritten Tage Laban an, daß Jakob entwichen sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'Und er nahm seine Brüder mit sich, und setze ihm nach sieben Tagereisen, und holte ihn ein am Berge Gilead.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Gott aber kam zu dem Aramiter Laban im Traum in der Nacht und sprach zu ihm: Hüte dich, daß du nicht mit Jakob vom Guten bis zum Bösen redest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'Und Laban erreichte den Jakob. Jakob aber hatte sein Zelt auf dem Berge aufgeschlagen, und Laban schlug mit seinen Brüdern sein Zelt auf dem Berge Gilead auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Und Laban sprach zu Jakob: Was hast du getan, und hast mein Herz gestohlen und meine Töchter wie mit dem Schwert gefangen weggeführt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Warum bist du heimlich entwichen, und hast mich bestohlen und mir nicht angesagt, auf daß ich dich mit Fröhlichkeit und mit Gesängen, mit Pauke und mit Harfe entlassen hätte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'Und hast mir nicht gestattet meine Söhne und meine Töchter zu küssen? Nun hast du närrisch gehandelt in deinem Tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Es wäre bei Gott in meiner Hand, euch Böses zu tun, aber der Gott eures Vaters hat gestern Nacht zu mir gesprochen und gesagt: Hüte dich mit Jakob vom Guten bis zum Bösen zu reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Und nun, bist du gegangen, weil du dir das Haus deines Vaters ersehnt hast - warum aber hast du mir meine Götter gestohlen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'Und Jakob antwortete und sprach zu Laban: Weil ich fürchtete und sprach: Daß du mir deine Töchter nicht entreißest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Bei wem du aber deine Götter findest, der soll nicht am Leben bleiben vor unseren Brüdern. Besieh dir, was ich bei mir habe, und nimm es dir. Denn Jakob wußte nicht, daß Rachel sie gestohlen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Und Laban kam in das Zelt Jakobs und in das Zelt Leahs und in das Zelt der beiden Mägde und fand nichts. Und er ging heraus von dem Zelte Leahs und kam in Rachels Zelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Rachel aber hatte die Theraphim genommen und unter die Kamelsstreue gelegt und saß darauf. Und Laban betastete alles im Zelt und fand nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Und sie sprach zu ihrem Vater: Es entbrenne nicht Zorn in den Augen meines Herrn, daß ich nicht aufzustehen vermag vor dir, denn es geht mir nach der Weiber Weise; und er durchsuchte es, fand aber die Theraphim nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Und Jakob entbrannte und er haderte mit Laban; und Jakob antwortete und sprach zu Laban: Was ist meine Übertretung, was ist meine Sünde, daß du hinter mir nachgejagt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'Du hast alle meine Gefäße betastet, was hast du von allen Gefäßen deines Hauses gefunden? Lege es her hier vor meine Brüder und vor deine Brüder, sie mögen bestimmen zwischen uns beiden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Diese zwanzig Jahre bin ich bei dir gewesen. Deine Mutterschafe und deine Ziegen haben nicht fehlgeboren, und die Widder deines Kleinviehs habe ich nicht gegessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Das Zerfleischte habe ich dir nicht hereingebracht; ich habe es erstattet. Von meiner Hand hast du gesucht das bei Tag Gestohlene und das bei Nacht Gestohlene.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Und so bin ich gewesen, bei Tag verzehrte mich die Hitze, und der Frost bei Nacht; und der Schlaf entfloh von meinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'Diese zwanzig Jahre sind es, daß ich in deinem Hause diente, vierzehn Jahre um deine zwei Töchter und sechs Jahre um dein Kleinvieh, und zehn Mal hast du meinen Lohn abgeändert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Wäre nicht der Gott meines Vaters, der Gott Abrahams, und der Schauer Isaaks mit mir gewesen, du hättest mich jetzt leer entsandt. Mein Elend und die Ermüdung meiner Hände hat Gott gesehen, und gestern Nacht hat Er es gerügt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Und Laban antwortete und sprach zu Jakob: Die Töchter sind meine Töchter und die Söhne sind meine Söhne, und das Kleinvieh ist mein Kleinvieh, und alles, was du siehst, ist mein. Aber meinen Töchtern, was sollte ich ihnen heute tun, oder ihren Söhnen, die sie geboren?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'Und nun, geh zu, wir wollen einen Bund schließen, ich und du, und er soll zum Zeugnis sein zwischen mir und zwischen dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Und Jakob nahm einen Stein und richtete ihn zu einer Denksäule empor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'Und Jakob sprach zu seinen Brüdern: Leset Steine auf, und sie nahmen Steine und machten einen Haufen, und aßen dort über dem Haufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'Und Laban nannte ihn Jegar Sahaduta und Jakob nannte ihn Gal-Eed.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Und Laban sprach: Dieser Haufen sei Zeuge zwischen mir und dir an diesem Tage. Daher hieß man ihn Gal-Eed.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'Und auch Mizpah denn er sagte: Jehovah wache zwischen mir und zwischen dir, wenn einer wird dem andern verborgen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Denn so du bedrückest meine Töchter und so du Weiber zu meinen Töchtern nimmst, während kein Mann bei uns ist; siehe, so ist Gott Zeuge zwischen mir und zwischen dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Und Laban sprach zu Jakob: Siehe diesen Haufen und siehe die Denksäule, die ich aufgeworfen zwischen mir und zwischen dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'Zeuge sei dieser Haufen und Zeuge die Denksäule, ob ich nicht über diesen Haufen hinziehe gegen dich, und ob du nicht über diesen Haufen und die Denksäule da hinziehest gegen mich zum Bösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Der Gott Abrahams und der Gott Nachors soll richten zwischen uns, der Gott ihres Vaters; und Jakob schwur bei dem Schauer seines Vaters Isaak.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Und Jakob brachte ein Opfer auf dem Berge und rief seine Brüder, Brot zu essen, und sie aßen Brot und übernachteten auf dem Berge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Und Laban stand frühe am Morgen auf, und küßte seine Söhne und seine Töchter und segnete sie; und Laban ging und kehrte zurück an seinen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'Und Jakob ging seinen Weg und die Engel Gottes stießen auf ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'Und da Jakob sie sah, sprach er: Dies ist ein Lager Gottes, und er nannte den Namen desselben Ortes Machanaim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'Und Jakob sandte Boten vor sich her an Esau, seinen Bruder, in das Land Seir, ins Gefilde Edom;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Und gebot ihnen und sagte: So sprecht zu meinem Herrn, zu Esau: Also spricht dein Knecht Jakob: Bei Laban habe ich mich aufgehalten und bis jetzt verweilet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'Und ich habe Ochs und Esel, Kleinvieh, und Knechte und Dienstmägde, und ich sende es meinem Herrn, anzusagen, um Gnade in deinen Augen zu finden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'Und die Boten kehrten zurück zu Jakob und sprachen: Wir sind zu deinem Bruder, zu Esau, gekommen, und auch er zieht dir entgegen und vierhundert Mann mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Und Jakob fürchtete sich sehr und er ward bedrängt; und er verteilte das Volk, das bei ihm war, und das Kleinvieh und die Rinder und die Kamele in zwei Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'Und er sprach: So Esau kommt zu dem einen Lager und schlägt es, so wird das Lager, das verbleibt, entkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Und Jakob sprach: Gott meines Vaters Abraham, und Gott meines Vaters Isaak, Jehovah, Der Du zu mir gesprochen hast: Kehr in dein Land und deinen Geburtsort zurück, und Ich will dir Gutes tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Ich bin zu gering all der Barmherzigkeit und all der Wahrheit, die Du an Deinem Knechte getan hast; denn mit meinem Stocke setzte ich über den Jordan da, und nun bin ich zu zwei Lagern geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Errette mich doch aus der Hand meines Bruders, aus der Hand Esaus; denn ich fürchte ihn, er möchte kommen und mich schlagen, die Mutter über den Söhnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'Aber Du hast gesagt: Ich will dir gewiß-lich Gutes tun und deinen Samen machen wie den Sand des Meeres, den man nicht zählt vor Menge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'Und er übernachtete daselbst in selbiger Nacht, und nahm von dem, was in seine Hand kam, ein Geschenk für Esau, seinen Bruder,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'Zweihundert Ziegen und zwanzig Böcke, zweihundert Mutterschafe und zwanzig Widder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'Dreißig säugende Kamele und ihre Füllen, vierzig Kühe und zehn Farren, zwanzig Eselinnen und zehn Eselsfüllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'Und er gab sie in die Hand seiner Knechte, jegliche Herde besonders und sprach zu seinen Knechten: Ziehet vor mir her und setzet einen Abstand zwischen Herde und zwischen Herde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'Und er gebot dem ersten und sprach: Wenn Esau, mein Bruder, auf dich trifft und dich fragt und sagt: Wem gehörst du an, und wohin gehst du, und für wen sind die da vor dir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'So sage: Deinem Knechte Jakob; es ist ein Geschenk, das er meinem Herrn, dem Esau, sendet, und siehe, auch er ist hinter uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'Und er gebot auch dem zweiten und auch dem dritten, auch allen, die hinter den Herden hergingen, und sagte: Solche Worte sollt ihr reden mit Esau, wenn ihr ihn findet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'Und ihr sollt auch sagen: Siehe, dein Knecht Jakob ist hinter uns; denn, sagte er, ich will sein Angesicht versöhnen mit dem Geschenk, das vor mir geht; und danach will ich sein Angesicht sehen, vielleicht erhebt er mein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'Und das Geschenk zog vor ihm her, und er übernachtete in dem Lager dieselbige Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'Und er machte sich in jener Nacht auf, und nahm seine zwei Weiber und seine zwei Dienstmägde und seine elf Kinder, und setzte über die Furt des Jabbok.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'Und er nahm sie und ließ sie über den Bach setzen, und alles, was er hatte, ließ er übersetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'Und Jakob blieb allein übrig; und es rang ein Mann mit ihm, bis die Morgenröte heraufkam,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'Und Er sah, daß er nichts über ihn vermochte, und berührte ihn an der Hüftpfanne, und die Hüftpfanne Jakobs verrenkte sich, indem er mit Ihm rang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'Und Er sprach: Entlaß mich, denn die Morgenröte ist heraufgekommen; er aber sprach: Ich entlasse Dich nicht, Du segnest mich denn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Und Er sprach zu ihm: Was ist dein Name? Und er sprach: Jakob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Und Er sprach: Dein Name heiße hinfort nicht mehr Jakob, sondern Israel; denn du hast wie ein Fürst mit Gott und mit Männern gekämpft, und hast sie übermocht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Und Jakob fragte und sprach: Sage mir doch an Deinen Namen; und Er sprach: Warum fragst du nach Meinem Namen? Und Er segnete ihn daselbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Und Jakob nannte den Namen des Ortes Peniel; denn, ich habe Gott von Angesicht zu Angesicht gesehen; und meine Seele ist errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Und es ging ihm die Sonne auf, wie er bei Peniel hinzog, und er hinkte an seiner Hüfte. Daher essen die Söhne Israels nicht die Bewegungssehne über der Hüftpfanne bis auf diesen Tag; weil Er an der Hüftpfanne Jakobs die Bewegungssehne berührt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'Und Jakob hob seine Augen auf und sah, und siehe, Esau kam, und mit ihm vierhundert Mann; und er verteilte die Kinder an Leah und an Rachel und die beiden Dienstmägde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'Und stellte die Dienstmägde und ihre Kinder zuerst, und Leah und ihre Kinder hernach, und Rachel und Joseph nach ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Und er zog hin vor ihnen und verbeugte sich siebenmal zur Erde, bis daß er zu seinem Bruder hinzutrat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'Und Esau lief ihm entgegen und umarmte ihn und fiel ihm um den Hals und küßte ihn, und sie weinten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'Und er hob seine Augen auf, und sah die Weiber und die Kinder und sprach: Wer sind diese bei dir? Und er sprach: Die Kinder, mit denen Gott in Gnade deinen Knecht begabt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Und die Dienstmägde traten herzu, sie und ihre Kinder, und verbeugten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Und auch Leah trat herzu und ihre Kinder und verbeugten sich, und nachher traten Joseph und Rachel herzu und verbeugten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'Und er sprach: Was soll dir das ganze Lager da, auf das ich getroffen bin? Und er sprach: Auf daß ich Gnade finde in den Augen meines Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'Und Esau sprach: Ich habe viele; mein Bruder, laß dein sein, was dein ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'Und Jakob sprach: Nicht doch, fände ich doch Gnade in deinen Augen, daß du mein Geschenk aus meiner Hand nähmest! denn darum habe ich dein Angesicht gesehen, wie man das Angesicht Gottes sieht; und du hattest Wohlgefallen an mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Nimm doch meinen Segen, der dir gebracht wurde; denn Gott hat mich gnädig begabt und ich habe alles; und er drang in ihn, und er nahm es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Und er sprach: Laß uns aufbrechen und gehen; und ich will vor dir gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Und er sprach zu ihm: Mein Herr weiß, daß die Kinder zart sind, und daß das Kleinvieh und Rindvieh bei mir säugt; und übertriebe man sie einen Tag, so würde alles Kleinvieh sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Ziehe doch mein Herr vor seinem Knechte hin, und ich will sie sachte leiten, je nach dem Schritte des Viehs vor mir her, und nach dem Schritte der Kinder, bis daß ich zu meinem Herrn nach Seir komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Und Esau sprach: Ich will doch von dem Volke, das bei mir ist, dir zustellen. Er aber sprach: Wozu das? laß mich doch Gnade in den Augen meines Herrn finden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Und Esau kehrte an demselben Tag auf seinem Weg nach Seir zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Und Jakob brach nach Sukkoth auf, und baute sich ein Haus, und für seine Viehherde machte er Hütten. Deshalb nannte man den Namen des Ortes Sukkoth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'Und Jakob kam nach Schalem, die Stadt des Schechem, im Lande Kanaan, wenn man von Padan Aram kommt, und lagerte sich vor der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'Und er kaufte einen Teil des Feldes, auf dem er sein Zelt aufschlug, von der Hand der Söhne Chamors, des Vaters von Schechem, um hundert Kesitah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'Und er stellte dort einen Altar auf und nannte ihn El Elohe Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Und Dinah, die Tochter Leahs, die sie dem Jakob gebar, ging aus, um die Töchter des Landes zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'Und Schechem, der Sohn Chamors, des Chiviters, des Fürsten des Landes, sah sie und nahm sie und lag bei ihr und schwächte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'Und seine Seele hing an Dinah, der Tochter Jakobs, und er liebte das Mädchen und redete zu dem Herzen des Mädchens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'Und Schechem sprach zu Chamor, seinem Vater, und sagte: Nimm mir dieses Mädchen zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Und Jakob hörte, daß er Dinah, seine Tochter, geschändet hatte; seine Söhne aber waren bei seiner Viehherde auf dem Felde, und Jakob schwieg stille, bis sie kamen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Chamor aber, Schechems Vater, ging heraus zu Jakob, um mit ihm zu reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'Und die Söhne Jakobs kamen vom Felde, als sie es hörten, und es schmerzte die Männer und sie entbrannten sehr, daß er eine Torheit in Israel getan und bei der Tochter Jakobs gelegen hatte, und solches sollte nicht getan werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'Und Chamor redete mit ihnen und sprach: Die Seele meines Sohnes Schechem hat Gefallen an eurer Tochter, gebet sie ihm doch zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'Und verschwägert euch mit uns, gebt uns eure Töchter und nehmet euch unsre Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'Und wohnet bei uns; und das Land soll vor eurem Angesichte sein, wohnet und handelt darin und habet Eigentum in demselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'Und Schechem sprach zu ihrem Vater und zu ihren Brüdern: Möchte ich Gnade finden in euren Augen und was ihr zu mir saget, will ich geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Mehret mir sehr die Morgengabe und Gabe, und ich will geben, was ihr zu mir saget, nur gebet mir das Mädchen zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Und die Söhne Jakobs antworteten dem Schechem und Chamor, seinem Vater, trüglich, und redeten so, weil er Dinah, ihre Schwester, geschändet hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'Und sagten zu ihnen: Wir können das Wort nicht tun, daß wir unsre Schwester einem Manne geben, der Vorhaut hat; denn es wäre eine Schmach für uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Wir können nur einwilligen, wenn ihr werdet wie wir, daß ihr alles Männliche bei euch beschneidet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'Und dann geben wir euch unsere Töchter und nehmen uns eure Töchter, und werden dann bei euch wohnen und zu einem Volke werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Wenn ihr aber nicht auf uns höret, euch zu beschneiden, dann nehmen wir unsre Tochter und gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'Und ihre Worte waren gut in den Augen Chamors und in den Augen Schechems, des Sohnes Chamors.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'Und der Jüngling zögerte nicht nach diesem Worte zu tun; denn er hatte Lust an Jakobs Tochter, und war vor allen geehrt im Hause seines Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Und Chamor kam und Schechem, sein Sohn, zum Tore ihrer Stadt und redeten mit den Männern ihrer Stadt und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Diese Männer sind friedlich unter uns und wollen im Lande wohnen und darin handeln, und siehe, das Land ist weit zu beiden Seiten vor ihnen. Lasset uns ihre Töchter uns zu Weibern nehmen und unsere Töchter ihnen geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Aber nur so wollen die Männer einwilligen bei uns zu wohnen und ein Volk zu werden, daß wir bei uns alles Männliche beschneiden, so wie sie beschnitten sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Ihre Viehherden und ihr Angekauftes und all ihr Vieh, wird es nicht unser sein, wenn wir nur ihnen einwilligen, und sie werden bei uns wohnen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Und sie hörten auf Chamor und auf Schechem, seinen Sohn, alle, die von dem Tor seiner Stadt ausgingen, und ließen alles Männliche beschneiden, alles, das von dem Tor seiner Stadt ausging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Und es geschah am dritten Tage, während sie in Schmerzen waren, nahmen zwei Söhne Jakobs, Simeon und Levi, Brüder Dinahs, jeder Mann sein Schwert und kamen kecklich in die Stadt und erwürgten alles Männliche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Und den Chamor und Schechem, seinen Sohn, erwürgten sie mit der Schärfe des Schwertes und nahmen Dinah aus dem Hause Schechems und gingen hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Die Söhne Jakobs kamen über die Erschlagenen und beraubten die Stadt dafür, daß sie ihre Schwester geschändet hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Ihr Kleinvieh und ihre Rinder und ihre Esel, und was in der Stadt war und was auf dem Felde war, nahmen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'Und all ihr Vermögen, und alle ihre Kindlein und ihre Weiber nahmen sie gefangen und raubten alles, was im Hause war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Und Jakob sprach zu Simeon und zu Levi: Ihr habt mich zerrüttet, daß ich stinke bei dem Einwohner des Landes, bei dem Kanaaniter und dem Pherisiter. Und ich habe nur wenig Leute. Und sie werden sich versammeln wider mich und mich schlagen, und ich und mein Haus werden vernichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Sie aber sagten: Soll man unsrer Schwester tun wie einer Buhlerin?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Und Gott sprach zu Jakob: Mache dich auf, gehe hinauf nach Bethel und wohne daselbst, und mache dort einen Altar dem Gotte, Der dir erschienen ist, da du vor deinem Bruder Esau flohest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'Und Jakob sprach zu seinem Hause und allen, die mit ihm waren: Nehmt weg die ausländischen Götter, die in eurer Mitte sind und reinigt euch und wechselt eure Gewänder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'Und wir wollen uns aufmachen und hinauf gen Bethel gehen; und dort will ich einen Altar machen dem Gotte, Der mir geantwortet hat am Tage meiner Bedrängnis und mit mir war auf dem Wege, den ich wandelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Und sie gaben Jakob alle ausländischen Götter, die in ihrer Hand waren, und die Reife, die sie in ihren Ohren hatten und Jakob verbarg sie unter der Eiche, die bei Schechem war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Und sie brachen auf, und das Entsetzen Gottes war über den Städten um sie her, so daß sie hinter den Söhnen Jakobs nicht nachsetzten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'Und Jakob kam nach Luz im Lande Kanaan, das ist Bethel, er und alles Volk, das mit ihm war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'Und daselbst baute er einen Altar und nannte den Ort El-Bethel, weil dort sich ihm Gott offenbarte, als er vor seinem Bruder entwich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Und es starb Deborah, Rebekahs Amme, und ward unterhalb Bethel unter der Eiche begraben, und man nannte ihren Namen Allon Bachuth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Und Gott erschien dem Jakob wieder, als er von Padan Aram gekommen war, und segnete ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'Und Gott sprach zu ihm: Dein Name ist Jakob; dein Name soll nicht mehr Jakob genannt werden, vielmehr Israel soll dein Name sein. Und Er nannte seinen Namen Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Und Gott sprach zu ihm: Ich bin der Gott Schaddai; sei fruchtbar und mehre dich, eine Völkerschaft und eine Versammlung von Völkerschaften soll von dir werden, und Könige sollen von deinen Hüften hervorgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Und das Land, daß Ich Abraham und Isaak gegeben, werde Ich dir geben, und deinem Samen nach dir werde Ich das Land geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'Und Gott stieg von ihm auf an dem Ort, da Er mit ihm geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'Und Jakob stellte eine Denksäule auf an dem Orte, da er mit Ihm geredet, eine Denksäule von Stein, und spendete darauf ein Trankopfer und goß Öl darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'Und Jakob nannte den Namen des Ortes, da Gott mit ihm geredet hatte, Bethel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'Und von Bethel brachen sie auf, und es war noch eine Strecke Landes, bis man nach Ephratah kam, und Rachel gebar und litt Hartes bei der Geburt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'Und es geschah, daß es ihr hart ward über der Geburt, da sprach die Wehmutter zu ihr: Fürchte dich nicht, denn auch dies ist dir ein Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'Und es geschah, da ihr die Seele ausging, daß sie am Sterben war, da nannte sie seinen Namen Benoni, sein Vater aber nannte ihn Benjamin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'Und Rachel starb und ward begraben auf dem Wege nach Ephratah, das ist Bethlehem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'Und Jakob stellte eine Denksäule über ihrem Grabe auf, das ist die Denksäule von Rachels Grab bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Und Israel brach auf und schlug sein Zelt auf jenseits des Migdal Eder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Und es geschah, da Israel in diesem Lande wohnte, da ging Ruben hin und lag bei Bilhah, dem Kebsweibe seines Vaters, und Israel hörte es. Jakob aber hatte zwölf Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Die Söhne Leahs: Der Erstgeborene Jakobs: Ruben und Simeon, und Levi und Judah und Isaschar und Sebulun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'Die Söhne Rachels: Joseph und Benjamin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'Und die Söhne Bilhahs, der Dienstmagd Rachels: Dan und Naphthali.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'Und die Söhne Silpahs, Leahs Dienstmagd: Gad und Ascher. Dies sind die Söhne Jakobs, die ihm in Padan Aram geboren wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'Und Jakob kam zu Isaak, seinem Vater, nach Mamre bei Kiriath Arba, das ist Chebron, woselbst Abraham und Isaak sich aufgehalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Und es waren Isaaks Tage hundert Jahre und achtzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'Und Isaak verschied und starb und ward zu seinen Völkern versammelt, alt und an Tagen satt. Und es begruben ihn Esau und Jakob, seine Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'Und dies sind die Geburten Esaus, das ist Edom.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Esau nahm seine Weiber von den Töchtern Kanaans: Adah, die Tochter Elons, des Chethiters und Oholibamah, Tochter Anahs, Tochter des Zibeon, des Chiviters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'Und Basemath eine Tochter Ismaels, Schwester des Nabajoth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'Und Adah gebar dem Esau Eliphas und Basemath gebar Reguel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'Und Oholibamah gebar Jeusch und Jaelam und Korach. Dies sind die Söhne Esaus, die ihm im Lande Kanaan geboren wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Und Esau nahm seine Weiber und seine Söhne und sein Töchter und alle Seelen seines Hauses, und sein Besitztum und all sein Vieh, und all sein Erkauftes, das er im Lande Kanaan gewonnen, und ging in ein Land, hinweg von Jakob, seinem Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Denn ihrer Habe war zu viel, als daß sie beisammen hätten wohnen können; und das Land ihrer Wanderungen vermochte nicht, wegen ihrer Viehherden sie zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'Und Esau wohnte auf dem Berge Seir; Esau, das ist Edom.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'Und dies sind die Geburten Esaus, des Vaters von Edom auf dem Berge Seir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Dies sind die Namen der Söhne Esaus: Eliphas, Sohn von Adah, Esaus Weib; Reguel, Sohn von Basemath, Esaus Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Und die Söhne des Eliphas waren Theman, Omar, Zepho und Gaetham und Kenas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Und Thimna war Kebsweib des Eliphas, des Sohnes Esaus, und gebar dem Eliphas Amalek. Dies sind die Söhne von Adah, Esaus Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Und das sind die Söhne Reguels: Nachath und Serach, Schammah und Missah. Dies waren die Söhne Basemaths, Esaus Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'Und dies waren die Söhne Oholibamahs, der Tochter Anahs, der Tochter Zibeons, Esaus Weib. Und sie gebar dem Esau Jeusch und Jaelam und Korach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'Dies waren die Stammhäupter der Söhne Esaus: Die Söhne von Eliphas, dem Erstgeborenen Esaus: das Stammhaupt Theman, das Stammhaupt Omar, das Stammhaupt Zepho, das Stammhaupt Kenas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'Das Stammhaupt Korach, das Stammhaupt Gaetham, das Stammhaupt Amalek. Dies die Stammhäupter des Eliphas im Lande Edom. Dies sind die Söhne Adahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'Und das sind die Söhne Reguels, des Sohnes Esaus: Das Stammhaupt Nachath, das Stammhaupt Serach, das Stammhaupt Schammah, das Stammhaupt Missah. Dies sind die Stammhäupter Reguels im Lande Edom. Dies die Söhne von Basemath, Esaus Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'Und das sind die Söhne Oholibamahs, Esaus Weib: Das Stammhaupt Jeusch, das Stammhaupt Jaelam, das Stammhaupt Korach. Dies die Stammhäupter Oholibamahs, der Tochter Anahs, Esaus Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Das sind die Söhne Esaus, und das ihre Stammhäupter, er ist Edom.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'Das sind die Söhne Seirs, des Horiten, die das Land bewohnen: Lotan und Schobal und Zibeon und Anah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Und Dischon und Ezer und Dischan. Dies die Stammhäupter des Horiten, die Söhne Seirs im Lande Edom.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'Und Lotans Söhne waren Hori und Hemam und die Schwester Lotans war Thimna.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Und das sind die Söhne Schobals: Alwan, und Manachath, und Ebal, Schepho und Onam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'Und das sind die Söhne Zibeons: Ajah, und Anah. Dies ist der Anah, der in der Wüste die Maulesel fand, als er die Esel seines Vaters Zibeon weidete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Und das sind die Söhne Anahs: Dischon und Oholibamah war Anahs Tochter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'Und das sind die Söhne Dischons: Chemdan und Eschban, und Jithran und Cheran.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Das sind die Söhne Ezers: Bilhan und Saawan und Akan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Das sind die Söhne Dischans: Uz und Aran.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Das sind die Stammhäupter des Horiten: Das Stammhaupt Lotan, das Stammhaupt Schobal das Stammhaupt Zibeon, das Stammhaupt Anah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'Das Stammhaupt Dischon, das Stammhaupt Ezer, das Stammhaupt Dischan: Dies die Stammhäupter des Horiten nach ihren Stammhäuptern im Lande Seir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Und das sind die Könige, die im Lande Edom regierten, ehe ein König über die Söhne Israel regierte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Und in Edom regierte Bela, der Sohn Beors, und der Name seiner Stadt war Dinhabah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'Und Bela starb, und an seiner Statt regierte Jobab, der Sohn Serachs aus Bozrah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'Und Jobab starb, und statt seiner regierte Chuscham aus dem Lande der Themaniter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'Und Chuscham starb, und an seiner Statt regierte Hadad, der Sohn Bedads, der Midjan schlug in dem Gefilde Moabs, und der Name seiner Stadt war Awith.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'Und Hadad starb, und es regierte an seiner Statt Samlah aus Masrekah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'Und Samlah starb, und an seiner Statt regierte Schaul aus Rechoboth am Flusse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'Und Schaul starb, und es regierte statt seiner Baal Chanan, der Sohn Achbors.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'Und Baal Chanan, der Sohn Achbors, starb, und es regierte statt seiner Hadar, und der Name seiner Stadt war Pau, und der Name seines Weibes war Mehetabeel, Tochter der Matred, die eine Tochter Mesahabs war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'Und das sind die Namen der Stammhäupter Esaus nach ihren Familien, nach ihren Orten, bei ihren Namen: Stammhaupt Thimna, Stammhaupt Alwah, Stammhaupt Jetheth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'Stammhaupt Oholibamah, Stammhaupt Elah, Stammhaupt Pinon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'Stammhaupt Kenas, Stammhaupt Theman, Stammhaupt Mibzar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'Stammhaupt Magdiel, Stammhaupt Iram. Dies sind die Stammhäupter Edoms nach ihren Wohnsitzen in dem Lande ihres Eigentums. Das ist Esau, der Vater Edoms.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Und Jakob wohnte im Lande der Wanderungen seines Vaters, im Lande Kanaan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Das sind die Geburten Jakobs. Joseph war siebzehn Jahre alt, er war mit seinen Brüdern ein Hirte beim Kleinvieh. Und der Junge war bei den Söhnen der Bilhah und den Söhnen Silpahs, der Weiber seines Vaters, und Joseph brachte das böse Gerede von ihnen herein zu ihrem Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Und Israel liebte Joseph mehr denn alle seine Söhne, weil er der Sohn seines Alters war, und machte ihm einen buntfarbigen Rock.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Und seine Brüder sahen, daß ihr Vater ihn mehr als alle seine Brüder liebte, und sie haßten ihn, und vermochten nicht im Frieden mit ihm reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Und Joseph träumte einen Traum, und sagte ihn seinen Brüdern an, und sie haßten ihn noch mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Und er sprach zu ihnen: Höret doch diesen Traum, den ich geträumt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Und siehe, wir banden Garben inmitten des Feldes, und siehe, es richtete sich auf meine Garbe und stand aufrecht, und siehe, eure Garben umgaben sie und verbeugten sich vor meiner Garbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Und seine Brüder sprachen zu ihm: Du willst wohl gar über uns regieren, willst du über uns herrschen? und sie haßten ihn noch mehr ob seinen Träumen und ob seinen Worten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Und er träumte noch einen anderen Traum und erzählte ihn seinen Brüdern. Und er sprach: Siehe, ich träumte noch einen Traum, und siehe, die Sonne und der Mond und elf Sterne verbeugten sich vor mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Und er erzählte es seinem Vater und seinen Brüdern; sein Vater aber bedrohte ihn und sagte zu ihm: Was soll es mit diesem Traume, den du geträumt hast? Sollen wir, ich und deine Mutter und deine Brüder kommen und uns vor dir zu Erde verbeugen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Und seine Brüder beneideten ihn; sein Vater aber behielt das Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Und seine Brüder gingen das Kleinvieh ihres Vaters zu weiden in Schechem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'Und Israel sprach zu Joseph: Sind nicht deine Brüder auf der Weide in Schechem? Gehe, und ich will dich zu ihnen senden. Und er sprach zu ihm: Siehe, hier bin ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Und er sprach zu ihm: Geh doch und sieh, wie es deinen Brüdern geht, und wie es mit dem Kleinvieh geht und bring mir das Wort zurück. Und er sandte ihn aus dem Talgrunde Chebron und er kam nach Schechem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Und es fand ihn ein Mann, und siehe, er wanderte auf dem Felde umher. Und der Mann fragte ihn und sprach: Was suchest du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'Und er sprach: Meine Brüder suche ich. Sage mir doch an, wo sie auf der Weide sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Und der Mann sagte ihm: Sie sind von hier aufgebrochen; denn ich hörte sie sagen: Wir wollen nach Dothan gehen. Und Joseph ging seinen Brüdern nach und fand sie in Dothan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Und sie sahen ihn von ferne, und ehe er ihnen nahe kam, faßten sie den Anschlag wider ihn, ihn zu töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Und sie sprachen der eine zum anderen: Siehe, da kommt dieser Traummeister.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Und nun kommet, laßt uns ihn erwürgen und in eine der Gruben werfen und sagen: Ein böses, wildes Tier hat ihn gefressen, und wir wollen sehen, was aus seinen Träumen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Und Ruben hörte dies und wollte ihn aus ihrer Hand erretten, und sprach: Wir wollen ihm nicht an die Seele gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'Und Ruben sprach zu ihnen: Vergießet nicht Blut, werfet ihn in die Grube dort in der Wüste, strecket aber eure Hand nicht aus gegen ihn; auf daß er ihn aus ihrer Hand errette, um ihn zu seinem Vater zurückzubringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'Und es geschah, da Joseph zu seinen Brüdern kam, zogen sie dem Joseph seinen Rock, den buntfarbigen Rock aus, den er anhatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'Und sie nahmen ihn und warfen ihn in die Grube; die Grube aber war leer, kein Wasser war darin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Und sie setzten sich, das Brot zu essen, und hoben ihre Augen auf und sahen, und siehe, ein Wanderzug Ismaeliten kam von Gilead; und ihre Kamele trugen Gewürze und Balsam und Stakte, und sie gingen, sie hinab nach Ägypten zu bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'Und Judah sprach zu seinen Brüdern: Welchen Gewinn haben wir davon, daß wir unseren Bruder erwürgen und sein Blut verbergen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Kommt lasset uns ihn an die Ismaeliten verkaufen; und unsre Hand sei nicht an ihm; denn er ist unser Bruder, unser Fleisch ist er; und seine Brüder hörten auf ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Und die midianitischen Männer, die Händler, zogen daher; sie aber zogen Joseph heraus und brachten ihn herauf aus der Grube, und verkauften Joseph an die Ismaeliten um zwanzig Silberlinge; und sie brachten Joseph nach Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Und Ruben kehrte nach der Grube zurück, und siehe: kein Joseph war in der Grube; und er zerriß seine Kleider;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'Und er kehrte zu seinen Brüdern zurück und sprach: Das Kind ist nicht mehr da. Und ich, wohin komme ich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Sie aber nahmen Josephs Rock und schlachteten einen Bock von den Ziegen, und tauchten den Rock in das Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Und sie sandten den buntfarbigen Rock fort und brachten ihn zu ihrem Vater und sagten: Diesen haben wir gefunden! besieh ihn doch, ob es deines Sohnes Rock ist, oder nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'Und er erkannte ihn und sprach: Es ist der Rock meines Sohnes, ein böses, wildes Tier hat ihn gefressen. Zerfleischt ist Joseph.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'Und Jakob zerriß seine Gewänder und legte einen Sack um seine Lenden, und trauerte viele Tage um seinen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'Und alle seine Söhne und alle seine Töchter, machten sich auf, ihn zu trösten; aber er weigerte, sich trösten zu lassen und sprach: Ich will trauend in die Gruft hinabgehen zu meinem Sohne; und es beweinte ihn sein Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Die Midianiter aber verkauften ihn nach Ägypten an Potiphar, einen Hofbeamten Pharaos, Obersten der Leibwachen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Und es geschah um jene Zeit, daß Judah hinabging von seinen Brüdern, und sich zu einem adullamitischen Manne abwandte, und sein Name war Chirah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'Und dort sah Judah die Tochter eines kanaanitischen Mannes, dessen Name Schua war und er nahm sie und kam zu ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'Und sie empfing und gebar einen Sohn, und er nannte seinen Namen Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Und sie empfing wieder und gebar einen Sohn, und sie nannte seinen Namen Onan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Und sie gebar wieder einen Sohn, und sie nannte seinen Namen Schelah; und er war in Chesib, da sie ihn gebar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Und Judah nahm dem Er seinem Erstgeborenen ein Weib, und ihr Name war Thamar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'Und Er, Judahs Erstgeborener, war böse in den Augen Jehovahs, und Jehovah ließ ihn sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Und Judah sprach zu Onan: Komm zu dem Weibe deines Bruders und leiste ihr die Schwagerpflicht, und erwecke Samen deinem Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Und Onan wußte, daß der Same nicht sein eigen sein sollte, und es geschah, als er zu dem Weibe seines Bruders kam, da verdarb er ihn auf die Erde, um seinem Bruder keinen Samen zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Und es war böse in den Augen Jehovahs, was er tat; und Er ließ auch ihn sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Und Judah sprach zu Thamar, seiner Schnur: Bleib Witwe im Hause deines Vaters, bis Schelah, mein Sohn, groß geworden ist; denn er sprach: Sonst könnte auch er sterben, wie seine Brüder. Und Thamar ging und blieb in ihres Vaters Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Und es wurden der Tage viel, und es starb die Tochter Schuas, Judahs Weib; und Judah tröstete sich, und ging hinauf zu den Scherern seines Kleinviehs er und Chirah, sein Genosse, der Adullamite, nach Thimnath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'Und es ward der Thamar angesagt, sprechend: Siehe, dein Schwäher geht hinauf gen Thimnath, sein Vieh zu scheren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'Und sie legte die Kleider ihrer Witwenschaft ab von ihr und bedeckte sich mit einem Schleier und verhüllte sich und setzte sich an den Eingang zu Enajim, die auf dem Wege nach Thimnath ist; denn sie sah, daß Schelah groß geworden und sie ihm nicht zum Weibe gegeben ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Und Judah sah sie und dachte, sie wäre eine Buhlerin; denn sie hatte ihr Gesicht bedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Und er wandte sich ab zu ihr am Wege und sprach: Laß mich doch zu dir kommen; denn er wußte nicht, daß sie seine Schnur war. Sie aber sagte: Was gibst du mir, daß du zu mir kommst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'Und er sprach: Ich will dir ein Ziegenböcklein von dem Kleinvieh senden; sie aber sagte: Wenn du ein Pfand gibst, bis du es sendest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Und er sagte: Was ist das Pfand, das ich dir geben soll? Und sie sprach: Deinen Siegelring und deine Schnur und deinen Stab, der in deiner Hand ist; und er gab sie ihr und kam zu ihr; und sie empfing von ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Sie aber machte sich auf und ging und legte ihren Schleier ab von ihr und zog die Kleider ihrer Witwenschaft an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Und Judah sandte das Ziegenböcklein durch die Hand seines Genossen, den Adullamiten, um das Pfand von der Hand des Weibes zu holen, fand sie aber nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'Und er fragte die Männer ihres Ortes und sprach: Wo ist die Buhlpriesterin bei Enajim am Wege; sie aber sagten: Es ist keine Buhlpriesterin dagewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Und er kehrte zu Judah zurück und sagte: Ich habe sie nicht gefunden, und auch die Männer des Ortes sagten: Es ist keine Buhlpriesterin dagewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'Judah aber sagte: Sie mag es zu sich nehmen, daß wir nicht verachtet werden. Siehe, ich habe dieses Böcklein gesandt und du hast sie nicht gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Und es geschah nach drei Monaten, daß man Judah ansagte und sprach: Deine Schnur Thamar hat gebuhlt, und siehe, sie hat auch von ihren Buhlereien empfangen. Und Judah sprach: Bringt sie heraus, daß sie verbrannt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Sie ward hinausgebracht und sie sandte an ihren Schwäher und sprach: Von dem Manne, dem dieses zugehört, hab ich empfangen. Und sie sprach: Besieh dir doch, wessen dieser Siegelring und diese Schnur und dieser Stab sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'Und Judah besah sie und sprach: Sie ist gerechter denn ich gewesen, weil ich sie nicht meinem Sohne Schelah gegeben; aber er erkannte sie hinfort nicht mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'Und es geschah zur Zeit, da sie gebar, und siehe, es waren Zwillinge in ihrem Leibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'Und es geschah, als sie gebar, daß einer eine Hand hergab. Und die Wehmutter nahm seine Hand und band Scharlach darum und sprach: Der ist zuerst herausgekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'Und es geschah, da er seine Hand zurückzog, siehe, da kam sein Bruder heraus; und sie sprach: Was hast du für dich einen Durchbruch durchgebrochen? Und er nannte seinen Namen Perez.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Und nachher kam sein Bruder heraus, an dessen Hand der Scharlach war, und er nannte seinen Namen Serach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Und Joseph ward nach Ägypten hinabgebracht, und es kaufte ihn Potiphar, ein Hofbeamter Pharaos, Oberster der Leibwachen, ein ägyptischer Mann, aus der Hand der Ismaeliten, die ihn hinabgebracht hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'Und Jehovah war mit Joseph, und er war ein Mann, dem es gelang; und er war im Hause seines Herrn, des Ägypters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'Und sein Herr sah, daß Jehovah mit ihm war und alles, was er tat, Jehovah in seiner Hand gelingen ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'Und Joseph fand Gnade in seinen Augen, und er tat ihm Dienst. Und er bestellte ihn über sein Haus und alles, was er hatte, gab er in seine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'Und es geschah, von da an, daß er ihn über sein Haus und alles, was er hatte, bestellt hatte, da segnete Jehovah das Haus des Ägypters wegen Josephs; und der Segen Jehovahs war in allem, das er hatte im Haus und im Feld.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Und er ließ alles, das er hatte, in der Hand Josephs, und wußte bei ihm um nichts, als das Brot, das er aß; und Joseph war schön von Gestalt und schön von Ansehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Und es geschah nach diesen Dingen, daß das Weib seines Herrn ihre Augen aufhob zu Joseph und zu ihm sprach: Liege bei mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'Er aber weigerte sich und sprach zu dem Weibe seines Herrn: Siehe, mein Herr weiß um nichts bei mir, was im Hause ist, und hat alles, was er hat, in meine Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Es ist kein Größerer denn ich in diesem Hause, und nichts hat er von mir zurückgehalten, außer dir, weil du sein Weib bist; und warum sollte ich solch großes Böses tun, und wider Gott sündigen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'Und es geschah, daß sie mit Joseph redete Tag für Tag, er hörte aber nicht auf sie, daß er neben ihr läge und bei ihr wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Und es geschah eines Tages, daß er in das Haus kam, um sein Werk zu tun, und kein Mann von den Männern des Hauses war dort im Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Und sie erfaßte ihn an seinem Kleid und sprach: Liege bei mir! Er aber ließ sein Kleid in ihrer Hand und floh und ging hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Und es geschah, da sie sah, daß er sein Kleid in ihrer Hand ließ und hinausfloh,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'Daß sie rief den Männern ihres Hauses und sprach zu ihnen und sagte: Seht, da brachte er einen hebräischen Mann zu uns herein, seinen Scherz mit uns zu treiben; er kam zu mir, um bei mir zu liegen. Ich aber rief mit großer Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'Und es geschah, wie er hörte, daß ich meine Stimme erhob und rief, da ließ er sein Kleid bei mir, und floh und ging hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Und sie legte sein Kleid neben sich nieder, bis sein Herr in sein Haus kam;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Und sie redete zu ihm dieselben Worte und sprach: Der hebräische Knecht, den du zu uns hereingebracht, ist zu mir hereingekommen, um seinen Scherz mit mir zu treiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Und es geschah, wie ich meine Stimme erhob und rief, da ließ er sein Kleid neben mir und floh hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'Und es geschah, als sein Herr die Worte seines Weibes hörte, die sie zu ihm redete, indem sie sprach: Solches hat mir dein Knecht getan, da entbrannte sein Zorn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'Und Josephs Herr nahm ihn und gab ihn in das Gefängnishaus, den Ort, wo die Gebundenen des Königs gebunden waren; und er war dort in dem Gefängnishaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Aber Jehovah war mit Joseph und neigte ihm Barmherzigkeit zu, und gab ihm Gnade in den Augen des Obersten des Gefängnishauses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'Und der Oberste des Gefängnishauses gab in Josephs Hand alle Gebundenen, die im Gefängnishause waren, und alles, was sie dort taten, das tat er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Der Oberste des Gefängnishauses sah nach nichts, von allem, das in seiner Hand war, weil Jehovah mit ihm war, und was er tat, Jehovah gelingen ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Und es geschah nach diesen Dingen, daß der Mundschenk des Königs von Ägypten und der Bäcker an ihrem Herrn, dem Könige von Ägypten, sündigten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'Und Pharao war entrüstet über seine beiden Hofbeamten, über den Obersten der Mundschenken und über den Obersten der Bäcker;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'Und gab sie in Gewahrsam in das Haus des Obersten der Leibwachen, in das Gefängnishaus, an den Ort, in dem Joseph gebunden war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'Und der Oberste der Leibwachen bestellte Joseph bei ihnen, daß er ihnen Dienst tun sollte, und sie waren etliche Tage in Gewahrsam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Und sie träumten beide einen Traum, jeder Mann seinen Traum, in einer Nacht, jeder nach der Deutung seines Traums, der Mundschenk und der Bäcker, die der König von Ägypten hatte, und die gebunden waren in dem Gefängnishaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'Und am Morgen kam Joseph zu ihnen hinein und sah sie und siehe, sie waren verdrossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'Und er fragte die Hofbeamten Pharaos, die mit ihm in dem Gewahrsam des Hauses seines Herrn waren und sagte: Warum ist euer Angesicht heute böse?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Und sie sprachen zu ihm: Wir haben einen Traum geträumt, und niemand ist da, der ihn deute. Joseph aber sprach zu ihnen: Gehören Deutungen nicht Gott zu? Erzählt sie mir doch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Und der Oberste der Mundschenken erzählte dem Joseph seinen Traum und sprach zu ihm: In meinem Traume siehe, da war ein Weinstock vor mir;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'Und an dem Weinstock waren drei Reben; und es war, als sproßte er, seine Blüte ging auf und seine Trauben ließen die Weinbeeren reifen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'Und Pharaos Becher war in meiner Hand, und ich nahm die Weinbeeren und drückte sie aus in den Becher Pharaos, und ich gab den Becher in Pharaos Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Und Joseph sprach zu ihm: Dies ist seine Deutung: Die drei Reben, sie sind drei Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'In noch drei Tagen wird Pharao dein Haupt aufheben und dich in deine Stelle zurückbringen, und du wirst den Becher Pharaos in seine Hand geben in der früheren Weise, da du sein Mundschenk warst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Aber möchtest du meiner bei dir gedenken, wenn es gut bei dir ist, und Barmherzigkeit an mir tun, und meiner bei Pharao gedenken, daß du mich aus diesem Hause herausbrächtest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'Denn gestohlen bin ich worden aus dem Lande der Hebräer, und auch hier habe ich nichts getan, daß sie mich in die Grube legten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Und der Oberste der Bäcker sah, daß er gut gedeutet hatte, und sprach zu Joseph: Auch ich war in meinem Traum, und siehe, drei durchbrochene Körbe waren auf meinem Haupte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'Und in dem obersten Korb waren von allen Speisen Pharaos, die der Bäcker macht, und das Gevögel fraß sie aus dem Korb von meinem Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Und Joseph antwortete und sprach: Dies ist seine Deutung: Die drei Körbe, sie sind drei Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'In noch drei Tagen wird Pharao dein Haupt von dir aufheben und dich ans Holz hängen, und das Gevögel wird dein Fleisch von dir fressen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'Und es geschah am dritten Tage, Pharaos Geburtstag, daß er allen seinen Knechten ein Gastmahl machte; und er hob auf das Haupt des Obersten der Mundschenken und das Haupt des Obersten der Bäcker inmitten seiner Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'Und brachte den Obersten der Mundschenken in sein Mundschenkenamt zurück, und er gab den Becher in Pharaos Hand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Aber den Obersten der Bäcker ließ er hängen, wie ihnen Joseph gedeutet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'Aber der Oberste der Mundschenken gedachte nicht an Joseph, und vergaß sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Und es geschah am Ende zweier Jahre von Tagen, daß Pharao träumte, und siehe, er stand am Strome.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Und siehe, aus dem Strome stiegen auf sieben Kühe, schön anzusehen und feist an Fleisch, und weideten im Riedgras.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'Und siehe, sieben andere Kühe stiegen nach ihnen auf aus dem Strome, übel anzusehen und mager an Fleisch, und sie standen neben den Kühen am Ufer des Stromes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Und die Kühe, übel anzusehen und mager an Fleisch, fraßen die sieben Kühe, die schön anzusehen und feist waren; und Pharao erwachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Und er schlief ein und träumte zum zweiten Mal; und siehe, sieben Ähren kamen herauf an einem Halm, feist und gut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Und siehe, sieben Ähren, mager und vom Ostwind versengt, sproßten nach ihnen auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Und die mageren Ähren verschlangen die sieben feisten und vollen Ähren, und Pharao erwachte, und siehe, es war ein Traum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'Und es geschah am Morgen, daß sein Geist beunruhigt war, und er sandte aus und rief all die Wahrsager Ägyptens und alle seine Weisen, und Pharao erzählte ihnen seinen Traum, und es war keiner, der sie dem Pharao deutete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Und der Oberste der Mundschenken redete mit Pharao und sprach: Ich gedenke heute meiner Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Pharao war entrüstet über seine Knechte und gab mich in Gewahrsam in das Haus des Obersten der Leibwachen, mich und den Obersten der Bäcker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Und wir träumten einen Traum in einer Nacht, ich und er, jeder Mann nach der Deutung seines Traumes träumten wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Und daselbst war bei uns ein hebräischer Jüngling, ein Knecht des Obersten der Leibwachen, und wir erzählten es ihm und er deutete uns unsere Träume, jedem Mann nach seinem Traume deutete er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'Und es geschah, wie er uns gedeutet hatte, so war es. Mich brachte er wieder an meine Stelle, und ihn ließ er hängen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Und Pharao sandte und rief Joseph, und sie brachten ihn eilends aus der Grube. Und er schor sich und wechselte seine Gewänder und kam zu Pharao.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Und Pharao sprach zu Joseph: Ich habe einen Traum geträumt und ist niemand der ihn deutet. Von dir aber hörte ich sagen, du hörest einen Traum, ihn zu deuten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Und Joseph antwortete dem Pharao und sprach: Bei mir ist es nicht. Gott wird dem Pharao Frieden antworten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Und Pharao redete zu Joseph: Siehe, ich stand in meinem Traume am Ufer des Stromes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'Und siehe, aus dem Strome stiegen auf sieben Kühe, feist an Fleisch und schön von Gestalt, und sie weideten im Riedgras.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Und siehe, sieben andere Kühe stiegen nach ihnen auf, ärmlich und sehr übel von Gestalt und abgemagert an Fleisch, ich sah dergleichen nicht in ganz Ägyptenland, so schlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'Und die abgemagerten und schlechten Kühe fraßen die sieben ersten feisten Kühe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'Und sie gingen in sie hinein, und man wußte es nicht, daß sie in sie hineingekommen, und ihr Ansehen war so schlecht, wie im Anbeginn; und ich erwachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Und ich sah in meinem Traume, und siehe, sieben Ähren kamen hervor an einem Halm, voll und gut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Und siehe, sieben Ähren, verdorrt, mager, vom Ostwind versengt, sproßten nach denselben auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Und die mageren Ähren verschlangen die sieben guten Ähren; und ich sagte es den Wahrsagern und keiner konnte mir es ansagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Und Joseph sprach zu Pharao: Der Traum Pharaos ist einer. Was Gott tun wird, hat er Pharao angesagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Die sieben guten Kühe, die sind sieben Jahre; und die sieben guten Ähren, die sind sieben Jahre. Es ist ein Traum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Und die sieben abgemagerten und schlechten Kühe, die nach ihnen aufstiegen, die sind sieben Jahre und die sieben leeren, vom Ostwind versengten Ähren werden sieben Jahre des Hungers sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'Das ist das Wort, das ich zu Pharao geredet habe; was Gott tun wird, das hat er Pharao gezeigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Siehe, es kommen sieben Jahre großen Überflusses in ganz Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'Und es erstehen nach ihnen sieben Hungerjahre; und man vergißt all des Überflusses im Land Ägypten, und der Hunger verzehrt das Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'Und man wird nichts mehr wissen von dem Überfluß im Lande vor dieser Hungersnot, die hernach sein wird; denn sehr schwer wird sie sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Und daß der Traum für Pharao zum zweiten Male wiederholt worden ist, ist, weil das Wort von Gott bereitet ist, und Gott eilt, es zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Und jetzt sehe Pharao nach einem einsichtsvollen und weisen Mann und setze ihn über Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'Dies tue Pharao und bestelle Amtleute über das Land, und nehme in den sieben Jahren des Überflusses den Fünften im Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Und sie sollen alle die Speise dieser guten Jahre, die da kommen, zusammenbringen und unter der Hand Pharaos Getreide in den Städten zur Speise aufhäufen und behalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'Und die Speise sei ein Vorrat für das Land auf die sieben Hungerjahre, die sein werden im Lande Ägypten, und das Land wird nicht ausgerottet werden durch den Hunger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'Und das Wort war gut in den Augen Pharaos und in den Augen aller seiner Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'Und Pharao sprach zu seinen Knechten: Können wir einen Mann finden wie diesen, in dem der Geist Gottes ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Und Pharao sprach zu Joseph: Nachdem dir Gott alles dies zu wissen getan, ist keiner so verständig und weise wie du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Du sollst sein über mein Haus, und auf deinen Mund soll küssen all mein Volk; nur um den Thron will ich größer sein, als du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Und Pharao sprach zu Joseph: Siehe, ich hab dich gesetzt über ganz Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'Und Pharao nahm seinen Ring ab von seiner Hand und gab ihn an Josephs Hand, und ließ ihm Kleider von Byssus anziehen und legte eine goldene Kette an seinen Hals.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'Und ließ ihn in dem zweiten Streitwagen fahren, den er hatte, und sie riefen vor ihm Abrech! und setzte ihn über ganz Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'Und Pharao sprach zu Joseph: Ich bin Pharao; und ohne dich soll niemand seine Hand und seinen Fuß emporheben in ganz Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Und Pharao nannte den Namen Josephs Zaphnath Paneach, und gab ihm Asnath, die Tochter Potipheras, Priester von On, zum Weibe, und Joseph ging aus über Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Und Joseph war dreißig Jahre alt, als er vor Pharao, dem Könige von Ägypten stand. Und Joseph ging aus von Pharao und zog hin in das ganze Land Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Und das Land trug in den sieben Jahren des Überflusses zu vollen Händen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Und er brachte alle Speise der sieben Jahre, die im Lande Ägypten waren, zusammen und gab die Speise in die Städte; die Speise von dem Felde, das rings um die Stadt war, gab er in ihre Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Und Joseph häufte Getreide auf wie Sand am Meere, so sehr viel, daß er aufhörte zu zählen, denn es war ohne Zahl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Und dem Joseph wurden zwei Söhne geboren, ehe das Hungerjahr kam, die ihm gebar Asnath, die Tochter Potipheras, des Priesters von On.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'Und Joseph nannte den Namen des Erstgeborenen Menascheh; denn Gott, sprach er, ließ mich all mein Mühsal und das ganze Haus meines Vaters vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Und den Namen des zweiten nannte er Ephraim; denn Gott hat mich im Land meines Elends fruchtbar gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'Und die sieben Jahre des Überflusses, der im Lande Ägypten war, waren vollendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'Und es fingen die sieben Hungerjahre an zu kommen, wie Joseph gesprochen, und Hunger war in allen Ländern, aber im ganzen Lande Ägypten war Brot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'Und ganz Ägyptenland litt Hunger und das Volk schrie zu Pharao um Brot. Pharao sprach aber zu ganz Ägypten: Gehet zu Joseph; was er euch sagt, das tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'Und die Hungersnot war über das ganze Land; und Joseph öffnete alles, wo etwas war, und verkaufte Getreide an Ägypten, und die Hungersnot wurde stark im Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'Und alle Länder kamen nach Ägypten zu Joseph, um Getreide zu kaufen, weil auf der ganzen Erde die Hungersnot stark war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Und Jakob sah, daß in Ägypten Getreide war, und Jakob sprach zu seinen Söhnen: Was sehet ihr einander an?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Und er sprach: Siehe, ich habe gehört, daß in Ägypten Getreide ist. Gehet dort hinab und kaufet Getreide für uns von dort, auf daß wir leben und nicht sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Und die zehn Brüder Josephs gingen hinab, um aus Ägypten Getreide zu kaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Aber Benjamin, Josephs Bruder, sandte Jakob nicht mit seinen Brüdern; denn, sagte er, es möchte ihm ein Unfall begegnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'Und die Söhne Israels kamen, um Getreide zu kaufen, inmitten der Kommenden; denn die Hungersnot war im Lande Kanaan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Und Joseph war der Gewalthaber über das Land, er selbst verkaufte das Getreide an alles Volk des Landes. Und die Brüder Josephs kamen und verbeugten sich vor ihm mit dem Antlitz zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'Und Joseph sah seine Brüder, und er erkannte sie, und stellte sich fremd gegen sie, und redete sie hart an und sprach zu ihnen: Woher kommet ihr? Und sie sprachen: Aus dem Lande Kanaan, um Speise zu kaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Und Joseph erkannte seine Brüder, sie aber erkannten ihn nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'Und Joseph gedachte der Träume, die er von ihnen geträumt hatte und sprach zu ihnen: Kundschafter seid ihr; um die Blöße des Landes zu sehen seid ihr gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Sie aber sprachen zu ihm: Nein, mein Herr, sondern deine Knechte sind gekommen, Speise zu kaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Wir alle sind Söhne eines Mannes; wir sind redlich. Deine Knechte sind keine Kundschafter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'Und er sprach zu ihnen: Nein, ihr seid gekommen, die Blöße des Landes zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'Sie aber sprachen: Wir, deine Knechte, sind zwölf Brüder, Söhne eines Mannes im Lande Kanaan, und siehe, der kleine ist diesen Tag mit unserm Vater, und einer ist nicht mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Und Joseph sprach zu ihnen: Es ist, wie ich zu euch geredet und gesagt: Ihr seid Kundschafter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'Daran sollt ihr geprüft werden; beim Leben Pharaos, ihr sollt nicht von dannen ausgehen, es komme denn euer kleiner Bruder hierher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Sendet einen von euch, daß er euern Bruder hole; ihr aber seid gebunden, daß eure Worte geprüft werden, ob Wahrheit bei euch ist; und wo nicht, so seid ihr beim Leben Pharaos Kundschafter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'Und er tat sie beisammen im Gewahrsam drei Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Und am dritten Tage sprach Joseph zu ihnen: So tut, auf daß ihr lebet. Ich fürchte Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'Wenn ihr redlich seid, so werde ein Bruder von euch gebunden im Hause eures Gewahrsams, ihr aber gehet und bringt Getreide für den Hunger eurer Häuser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Euren jüngsten Bruder aber bringt ihr zu mir, auf daß euren Worten geglaubt werde, und ihr nicht sterbet. Und sie taten so.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Und sie sprachen einer zum anderen: Fürwahr, das haben wir an unsrem Bruder verschuldet; wir sahen ihn in der Bedrängnis seiner Seele, wie er zu uns flehte, und wir hörten nicht. Deshalb kommt diese Bedrängnis über uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'Und Ruben antwortete ihnen und sprach: Habe ich nicht zu euch gesprochen und gesagt: Sündiget nicht an dem Kinde; aber ihr hörtet nicht. Und siehe, es wird auch sein Blut von uns gefordert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Und sie wußten nicht, daß Joseph es hörte; denn ein Dolmetscher war zwischen ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'Er wandte sich aber herum von ihnen und weinte; und er kehrte zu ihnen zurück und redete mit ihnen. Und er nahm Simeon aus ihnen und band ihn vor ihren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'Und Joseph gebot und sie füllten ihre Gefäße mit Getreide und gaben ihr Silber einem jeden Mann in seinen Sack zurück und gaben ihnen Zehrung auf den Weg; und man tat ihnen also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Und sie hoben ihr Getreide auf ihre Esel und gingen von dannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Und es öffnete einer seinen Sack, um seinem Esel Futter zu geben in dem Nachtlager; und sah sein Silber und siehe es war in der Öffnung seines Mantelsackes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'Und er sprach zu seinen Brüdern: Mein Silber ist zurückgegeben, und siehe es ist auch in meinem Mantelsack. Und es ging ihnen das Herz aus, und erzitternd sprachen sie zueinander: Warum hat uns Gott das getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'Und sie kamen zu Jakob, ihrem Vater, ins Land Kanaan und sagten ihm alles an, was ihnen begegnet war, und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Der Mann, der Herr des Landes, redete uns hart an und gab uns für Kundschafter des Landes aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'Wir aber sagten zu ihm: Wir sind redlich, wir sind keine Kundschafter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Zwölf Brüder sind wir, Söhne unseres Vaters, einer ist nicht mehr und der Kleine ist heute bei unserem Vater im Lande Kanaan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'Und der Mann, der Herr des Landes, sprach zu uns: Daran will ich wissen, daß ihr redlich seid: Lasset einen von euch Brüdern bei mir bleiben; und nehmet für den Hunger eurer Häuser und gehet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'Und bringet euren kleinen Bruder zu mir, auf daß ich wisse, daß ihr keine Kundschafter seid, daß ihr redlich seid. Euren Bruder gebe ich euch, und ihr dürft im Lande handeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Und es geschah, da sie ihre Säcke leerten und siehe, das Bündelchen mit eines jeden Mannes Silber war in seinem Sacke; und sie sahen die Bündelchen ihres Silbers, sie und ihr Vater und sie fürchteten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'Und Jakob, ihr Vater, sprach zu ihnen: Ihr machet mich kinderlos. Joseph ist nicht da und Simeon ist nicht da und Benjamin wollet ihr nehmen. Dies alles kommt über mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'Und Ruben sprach zu seinem Vater und sagte: Meine zwei Söhne sollst du töten, wenn ich ihn nicht zu dir herbringe; gib ihn auf meine Hand und ich bringe ihn dir zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'Er aber sprach: Mein Sohn soll nicht mit euch hinabgehen; denn sein Bruder ist tot, und er allein ist mir geblieben; und begegnet ihm ein Unfall auf dem Wege, auf dem ihr gehet, so bringet ihr mein Greisenhaar mit Gram in die Gruft hinab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'Und die Hungersnot war schwer im Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'Und es geschah, als sie das Getreide, das sie aus Ägypten gebracht, aufgezehrt hatten, da sprach ihr Vater zu ihnen: Gehet zurück und kaufet uns ein wenig zu essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'Und Judah sprach zu ihm und sagte: Der Mann hat uns höchlich bezeugt und gesagt: Ihr sollt mein Angesicht nicht sehen, wofern nicht euer Bruder mit euch ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Ist es nun, daß du unseren Bruder mit uns sendest, so wollen wir hinabgehen und dir Speise kaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Sendest du ihn aber nicht, so gehen wir nicht hinab; denn der Mann hat uns gesagt: Ihr sollt mein Angesicht nicht sehen, es sei den euer Bruder mit euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Und Israel sprach: Warum habt ihr so übel an mir getan, daß ihr dem Manne ansagtet, ihr hättet noch einen Bruder?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Und sie sprachen: Der Mann hat uns über uns und unsre Geburt gefragt und gesagt: Lebt euer Vater noch? Habt ihr einen Bruder? Und wir sagten ihm an, gemäß diesen Worten. Konnten wir irgendwie wissen, daß er sagen würde: Bringet euren Bruder herab?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'Und Judah sprach zu Israel, seinem Vater: Sende den Jungen mit mir, und wir machen uns auf und gehen, daß wir leben und nicht sterben, beides, wir und du und unsre Kindlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Ich verbürge mich für ihn, von meiner Hand sollst du ihn fordern. Wenn ich ihn nicht zu dir herbringe und dir ihn vor das Angesicht stelle, so will ich alle Tage an dir gesündigt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Denn hätten wir nicht gezaudert, schon diese zweimal wären wir zurückgekehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Und Israel, ihr Vater, sprach zu ihnen: Wenn dem nun so ist, so tut es, nehmet von dem Gepriesenen des Landes in eure Gefäße, und bringt dem Manne ein Geschenk hinab, ein wenig Balsam und ein wenig Honig und Harz und Stakte, Terebinthennüsse und Mandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Und an Silber nehmet das Doppelte in eure Hand, und das Silber, das in die Öffnung eurer Mantelsäcke zurückgegeben wurde, bringt zurück in eurer Hand, vielleicht ist es ein Versehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Und euren Bruder nehmet, und macht euch auf und kehrt zu dem Manne zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'Und Gott Schaddai gebe euch Erbarmungen vor dem Manne, daß er euch entlasse euern andern Bruder und Benjamin; und ich, sei ich denn kinderlos, wie ich kinderlos sein soll!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Und die Männer nahmen dieses Geschenk und das Doppelte des Silbers nahmen sie in ihre Hand, und Benjamin, und sie machten sich auf und gingen hinab nach Ägypten und standen vor Joseph.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Und Joseph sah Benjamin mit ihnen und sprach zu dem, der über sein Haus war: Bringe die Männer herein ins Haus und schlachte und bereite; denn die Männer sollen mit mir essen am Mittag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'Und der Mann tat, wie Joseph sagte; und der Mann brachte die Männer herein in Josephs Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Die Männer aber fürchteten sich, daß sie in Josephs Haus hereingebracht wurden und sprachen: Wegen des Silbers, das im Anbeginn wieder in unsre Mantelsäcke zurückkam, werden wir hereingebracht, um es auf uns zu wälzen und über uns herzufallen und uns zu Knechten zu nehmen und unsere Esel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'Und sie traten herzu zu dem Manne, der über Josephs Haus war und redeten zu ihm am Eingang des Hauses;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'Und sprachen: Bitte, mein Herr, wir sind im Anbeginn herabgekommen, um Speise zu kaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Und es geschah, wie wir in das Nachtlager kamen und unsre Mantelsäcke öffneten, da siehe, da war eines jeden Mannes Silber in der Öffnung seines Mantelsackes, unser Silber nach seinem Gewicht, und wir bringen es hier in unserer Hand zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'Und anderes Silber brachten wir in unsrer Hand herab, um Speise zu kaufen. Wir wissen nicht, wer unser Silber in unsre Mantelsäcke gelegt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'Und er sprach: Friede sei mit euch! Fürchtet euch nicht: Euer Gott und der Gott eures Vaters hat euch etwas Verborgenes in eure Mantelsäcke gegeben. Euer Silber ist mir zugekommen; und er brachte Simeon zu ihnen heraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'Und der Mann brachte die Männer herein in Josephs Haus, und gab Wasser und sie wuschen ihre Füße, und ihren Eseln gab er Futter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'Und sie machten das Geschenk bereit bis Joseph am Mittag käme, denn sie hatten gehört, daß sie das Brot da essen sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Und Joseph kam nach Hause und sie brachten ihm das Geschenk, das in ihrer Hand war, herein ins Haus und sie beugten sich vor ihm nieder zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'Und er fragte nach ihrem Frieden und sprach: Und hat Frieden euer alter Vater, von dem ihr gesagt? Lebt er noch?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Und sie sagten: Dein Knecht, unser Vater, hat Frieden. Er lebt noch. Und sie verneigten sich und beugten sich nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'Und er hob seine Augen auf und sah Benjamin, seinen Bruder, den Sohn seiner Mutter, und sprach: Ist dies euer kleiner Bruder, von dem ihr mir gesprochen habt? Und er sprach: Gott sei dir gnädig, mein Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'Und Joseph eilte; denn sein Erbarmen erregte sich für seinen Bruder, und er suchte, wo er weinte; und er ging in die Kammer hinein und weinte daselbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Und er wusch sein Gesicht und kam heraus, und hielt an sich und sprach: Setzet Brot auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'Und sie legten ihm besonders vor, und ihnen besonders, und den Ägyptern, die mit ihm aßen, besonders; denn die Ägypter können nicht Brot essen mit den Hebräern, weil dies den Ägyptern ein Greuel ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Und sie saßen vor ihm, der Erstgeborene nach seiner Erstgeburt und der Jüngste nach seiner Jugend; und die Männer verwunderten sich, jeder Mann zu seinem Genossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'Und man hob Gerichte von seinem Angesichte weg vor sie hin, aber Benjamins Gericht war fünfmal mehr denn das Gericht von ihnen allen. Und sie tranken und wurden trunken mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Und er gebot dem, der über sein Haus war, und sprach: Fülle die Mantelsäcke der Männer mit Speise, so viel sie tragen können, und eines jeden Mannes Silber lege in die Öffnung seines Mantelsackes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Und meinen Kelch, den silbernen Kelch, lege in die Öffnung des Mantelsackes des Kleinsten und das Geld für sein Getreide; und er tat nach Josephs Wort, das er geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Am Morgen ward es Licht, und die Männer wurden entsendet, sie und ihre Esel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Sie gingen aus von der Stadt und waren noch nicht ferne, da sprach Joseph zu dem, der über sein Haus war: Mache dich auf, setze den Männern nach, und wenn du sie erreichst, da sprich zu ihnen: Warum habt ihr Gutes mit Bösem vergolten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Ist es nicht der, aus dem mein Herr trinkt, und aus dem er voraussagt? Ihr habt übel getan an dem, was ihr tatet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Und er erreichte sie und redete zu ihnen diese Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Und sie sprachen zu ihm: Warum redet mein Herr solche Worte? Fern sei von deinen Knechten, nach diesem Worte zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Siehe, das Silber, das wir in der Öffnung unsrer Mantelsäcke gefunden, haben wir dir aus dem Lande Kanaan zurückgebracht. Und wie sollten wir aus dem Hause deines Herrn Silber oder Gold stehlen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Bei welchem von deinen Knechten es gefunden wird, der soll sterben; und auch wir wollen meinem Herrn zu Knechten sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'Und er sprach: Es sei nun auch so nach euren Worten! Der, bei dem er gefunden wird, der soll mein Knecht sein, ihr aber sollt ungestraft sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Und sie eilten und ließen jeder Mann seinen Mantelsack auf die Erde herab und öffneten jeder Mann seinen Mantelsack.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'Und er forschte nach, fing bei dem Größten an und hörte beim Kleinsten auf; und der Kelch fand sich in Benjamins Mantelsack.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Und sie zerrissen ihre Gewänder, und jeder Mann belud seinen Esel und sie kehrten nach der Stadt zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'Und Judah und seine Brüder kamen in Josephs Haus und er war noch da, und sie fielen vor ihm zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Und Joseph sprach zu ihnen: Was ist das für eine Tat, die ihr getan? wußtet ihr nicht, daß ein Mann, wie ich, vorhersagen kann?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Und Judah sprach: Was sollen wir sagen zu meinem Herrn, was sollen wir reden und wie uns rechtfertigen? Gott hat gefunden die Missetat deiner Knechte. Siehe, wir sind Knechte meinem Herrn, sowohl wir als er, in dessen Hand der Kelch gefunden worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'Und er sprach: Ferne sei von mir, solches zu tun. Der Mann, in dessen Hand der Kelch gefunden worden, der soll mein Knecht sein. Und ihr, gehet ihr im Frieden hinauf zu eurem Vater!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Und Judah trat her zu ihm und sprach: Bitte, mein Herr, laß doch deinen Knecht ein Wort reden in den Ohren meines Herrn, und es entbrenne nicht dein Zorn gegen deinen Knecht; denn du bist wie Pharao.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Mein Herr fragte seine Knechte und sprach: Habt ihr einen Vater oder einen Bruder?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Und wir sagten zu meinem Herrn: Wir haben einen alten Vater und ein Kind seines Alters, den Kleinsten, und sein Bruder ist tot, und er ist allein übrig geblieben von seiner Mutter, und sein Vater liebt ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'Und du sprachst zu deinen Knechten: Bringet ihn herab zu mir, daß ich mein Auge auf ihn richte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'Und wir sprachen zu meinem Herrn: Der Junge kann seinen Vater nicht verlassen; und verläßt er seinen Vater, so stirbt dieser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'Und du sprachst zu deinen Knechten: Wenn euer kleiner Bruder nicht mit euch herabkommt, so sollt ihr nicht wieder mein Angesicht sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Und es geschah, daß wir hinaufgingen zu deinem Knecht, meinem Vater, und sagten ihm an die Worte meines Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Und unser Vater sprach: Kehret zurück, kaufet uns ein wenig zu essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'Wir aber sagten: Wir können nicht hinabgehen; wenn unser kleiner Bruder mit uns ist, dann wollen wir hinabgehen; denn wir können das Angesicht des Mannes nicht sehen, wenn unser kleiner Bruder nicht mit uns ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'Und es sprach dein Knecht, mein Vater, zu uns: Ihr wisset, daß mein Weib, mir zwei geboren hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'Und der eine ist von mir hinausgegangen, und ich sprach: Gewiß, er ist zerfleischt, und ich hab ihn nicht gesehen bisher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Und nehmet ihr auch diesen von meinem Angesicht, und begegnet ihm ein Unfall, dann bringet ihr mein Greisenhaar durch Übel in die Gruft hinab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Und nun, wenn ich zu deinem Knecht, meinem Vater, komme, und der Junge ist nicht mit uns - und seine Seele ist mit dessen Seele verbunden -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'So wird es geschehen, wenn er sieht, daß der Junge nicht da ist, daß er stirbt. Und es werden deine Knechte das Greisenhaar deines Knechtes, unseres Vaters, mit Gram in die Gruft bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Denn dein Knecht hat sich verbürgt für den Jungen bei meinem Vater und gesagt: Wenn ich ihn nicht zu dir hereinbringe, so will ich alle Tage gegen meinen Vater gesündigt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Und nun laß deinen Knecht anstatt des Jungen als Knecht meinem Herrn bleiben, und den Jungen mit seinen Brüdern hinaufgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Denn wie sollte ich zu meinem Vater hinaufgehen, ohne daß der Junge bei mir ist? Ich müßte nur das Böse sehen, das meinen Vater trifft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Und Joseph vermochte nicht an sich zu halten vor allen, die bei ihm standen und rief: Lasset jeden Mann hinausgehen von mir! Und es stand kein Mann bei ihm, als Joseph sich seinen Brüdern zu erkennen gab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Und seine Stimme brach in Weinen aus, und es hörten es die Ägypter und das Haus Pharaos hörte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'Und Joseph sprach zu seinen Brüdern: Ich bin Joseph. Lebt mein Vater noch? Aber seine Brüder vermochten nicht ihm zu antworten; denn sie waren bestürzt vor seinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Und Joseph sprach zu seinen Brüdern: Tretet doch her zu mir; und sie traten herzu. Und er sprach: Ich bin Joseph, euer Bruder, ich, den ihr nach Ägypten verkauft habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Nun aber laßt es euch nicht schmerzen, und laßt es nicht entbrennen in euren Augen, daß ihr mich hierher verkauft habt; denn um am Leben zu erhalten, hat mich Gott vor euch hergesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Denn diese zwei Jahre war Hungersnot inmitten des Landes; und noch sind es fünf Jahre, in denen kein Pflügen und Ernten sein wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Und Gott hat mich vor euch hergesandt, um euch seinen Überrest zu setzen auf Erden, und euch das Leben zu erhalten, zu einer großen Errettung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Und nun seid nicht ihr es, die mich hierher gesandt, sondern Gott. Und Er hat mich dem Pharao zum Vater, und seinem ganzen Hause zum Herrn, und zum Herrscher im ganzen Land Ägypten gesetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Eilet und gehet hinauf zu meinem Vater und saget ihm: Also spricht dein Sohn Joseph: Gott hat mich zum Herrn über ganz Ägypten gesetzt; komm herab zu mir, bleib nicht stehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'Und du sollst im Lande Gosen wohnen und mir nahe sein, du und deine Söhne und die Söhne deiner Söhne, und dein Kleinvieh und deine Rinder, und alles, was dein ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'Und ich will dich da versorgen; denn noch sind fünf Hungerjahre, auf daß du nicht verkommest, du und dein Haus und alles, was dein ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Und siehe, eure Augen sehen es, und die Augen meines Bruders Benjamin, daß es mein Mund ist, der zu euch redet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Und saget an meinem Vater alle meine Herrlichkeit in Ägypten und alles, was ihr gesehen habt, und eilet und bringt meinen Vater hier herab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Und er fiel seinem Bruder Benjamin um den Hals und weinte, und Benjamin weinte an seinem Hals.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'Und er küßte alle seine Brüder und weinte über ihnen, und nachher redeten seine Brüder mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'Und ihre Stimme ward gehört im Hause Pharaos, und man sagte: Josephs Brüder sind gekommen. Und es war gut in den Augen Pharaos und in den Augen seiner Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'Und Pharao sprach zu Joseph: Sag deinen Brüdern: Das tut, ladet euren Lasttieren auf und gehet, kommt nach dem Lande Kanaan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'Und nehmet euren Vater und eure Häuser, und kommet zu mir, und ich will euch das Gute des Landes Ägypten geben, und ihr sollt essen das Fett des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Und du sollst ihnen gebieten: Dies tut, nehmet euch vom Lande Ägypten Wagen für eure Kindlein und für eure Weiber, und bringet euren Vater und kommet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Und lasset eure Augen euer Geräte nicht schonen; denn das Gut vom ganzen Lande Ägypten ist euer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'Und die Söhne Israels taten so, und Joseph gab ihnen Wagen nach Pharaos Ausspruch, und gab ihnen Zehrung auf den Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'Ihnen allen gab er, einem jeden Mann, Gewänder zum Wechseln; dem Benjamin aber gab er dreihundert Silberlinge und fünf Gewänder zum Wechseln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Seinem Vater aber schickte er wie folgt: Zehn Esel, tragend vom Guten Ägyptens, und zehn Eselinnen, tragend Getreide und Brot und Lebensmittel für seinen Vater auf den Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'Und er entsandte seine Brüder und sie gingen, und er sprach zu ihnen: Zanket nicht auf dem Wege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Sie aber gingen hinauf von Ägypten und kamen ins Land Kanaan zu Jakob, ihrem Vater;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'Und sie sagten es ihm an und sprachen: Joseph lebt noch und er herrscht im ganzen Land Ägypten; aber sein Herz erstarrte, denn er glaubte ihnen nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'Und sie redeten zu ihm alle Worte Josephs, die er zu ihnen geredet hatte. Und er sah die Wagen, die Joseph sandte, um ihn hinzufahren, und der Geist ihres Vaters Jakob lebte auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'Und Israel sprach: Das ist viel! Mein Sohn Joseph lebt noch. Ich will gehen und ihn sehen, bevor ich sterbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'Und Israel brach auf und alles, was er hatte, und kam nach Beerscheba, und opferte dem Gotte seines Vaters Isaak Opfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'Und Gott sprach zu Israel in Gesichten der Nacht, und Er sprach: Jakob, Jakob! Und er sprach: Hier bin ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'Und Er sprach: Ich bin der Gott, der Gott deines Vaters. Fürchte dich nicht, nach Ägypten hinabzugehen; denn ich will dich dort zu einer großen Völkerschaft setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Ich werde mit dir hinabgehen nach Ägypten und dich auch heraufkommen lassen, und Joseph wird seine Hand auf deine Augen legen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Und Jakob machte sich auf von Beerscheba, und die Söhne Israels hoben ihren Vater Jakob, ihre Kindlein und ihre Weiber auf in die Wagen, die Pharao gesandt, ihn zu fahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Und sie nahmen ihre Viehherden und ihre Habe, die sie im Lande Kanaan gewonnen hatten und kamen nach Ägypten, Jakob und all sein Same mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'Seine Söhne und seiner Söhne Söhne mit ihm, seine Töchter und seiner Söhne Töchter, und all seinen Samen brachte er mit sich nach Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Und dies sind die Namen der Söhne Israels, die nach Ägypten kamen, Jakobs und seiner Söhne: der Erstgeborene Jakobs: Ruben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Und die Söhne Rubens waren: Chanoch und Phallu und Chezron und Karmi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'Und die Söhne Simeons: Jemuel und Jamin und Ohad und Jachin und Zochar und Schaul, der Sohn einer Kanaaniterin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'Und die Söhne Levis: Gerschon und Kohath und Merari.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'Und die Söhne Judahs: Er und Onan und Schelah und Pherez und Serach; Er und Onan aber waren gestorben im Lande Kanaan; und die Söhne des Pherez waren Chezron und Chamul.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'Und die Söhne Isaschars: Thola und Phuvah und Job und Schimron.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'Und die Söhne Sebulons: Sered und Elon und Jachleel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Dies sind die Söhne der Leah, die sie dem Jakob in Padan Aram gebar, und Dinah, seine Tochter. Alle Seelen seiner Söhne und seiner Töchter waren dreiundreißig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'Und die Söhne Gads: Ziphjon und Chaggi, Schuni und Ezbon, Eri und Arodi und Areli.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'Und die Söhne Aschers: Jimnah und Jischvah und Jischvi und Berijah und Serach, ihre Schwester, und die Söhne Berijahs: Cheber und Malchiel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Dies sind die Söhne Silpahs, die Laban seiner Tochter Leah gab. Und sie gebar diese dem Jakob, sechszehn Seelen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Die Söhne von Rachel, Jakobs Weib, waren Joseph und Benjamin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'Und dem Joseph wurden geboren in Ägyptenland, die Asenath, die Tochter Potipheras, des Priesters von Ohn, ihm gebar, Menascheh und Ephraim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'Und die Söhne Benjamins waren: Bela und Becher und Aschbel, Gera und Naaman, Echi und Rosch, Muppim und Chuppim und Arde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Dies sind die Söhne Rachels, die dem Jakob geboren wurden, alle Seelen, vierzehn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Und die Söhne Dans: Chuschim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'Und die Söhne Naphthalis waren: Jachzeel und Guni und Jezer und Schillem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Dies sind die Söhne Bilhahs, die Laban seiner Tochter Rachel gab. Und sie gebar sie dem Jakob, alle Seelen, sieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Alle Seelen, die mit Jakob nach Ägypten kamen, die aus seinen Hüften hervorgingen, außer den Weibern der Söhne Jakobs, waren es alle Seelen, sechsundsechzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Und die Söhne Josephs, die ihm in Ägypten geboren wurden, waren zwei Seelen. Alle Seelen vom Hause Jakobs, die nach Ägypten kamen, waren siebzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'Und den Judah sandte er vor sich hin an Joseph, vor ihm her zu weisen nach Goschen; und sie kamen nach dem Lande Goschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Und Joseph spannte seinen Streitwagen an und ging hinauf, seinem Vater Israel entgegen nach Goschen. Und als er sich ihm zeigte, da fiel er ihm um den Hals und weinte lange an seinem Hals.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Und Israel sprach zu Joseph: Nunmehr will ich sterben, nachdem ich dein Angesicht gesehen, daß du noch lebst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Und Joseph sprach zu seinen Brüdern und zu dem Haus seines Vaters: Ich will hinaufgehen und Pharao ansagen, und ich will zu ihm sagen: Meine Brüder und das Haus meines Vaters, die im Lande Kanaan waren, sind zu mir gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'Und die Männer sind Hirten des Kleinviehs; denn sie sind Männer der Viehherden und haben ihr Kleinvieh und ihre Rinder und alles, was sie haben, hergebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Und wenn es geschieht, daß Pharao euch ruft und sagt: Was ist euer Tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'Dann saget: Männer der Viehherden sind deine Knechte gewesen von unsrer Jugend auf und bis jetzt, sowohl wir als unsre Väter; auf daß ihr wohnen möget im Lande Goschen; denn alle, die Kleinvieh weiden, sind den Ägyptern ein Greuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Und Joseph kam und sagte es Pharao an und sprach: Mein Vater und meine Brüder und ihr Kleinvieh und ihre Rinder und alles, was sie haben, sind aus dem Lande Kanaan gekommen; und siehe, sie sind im Lande Goschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'Und aus der Zahl seiner Brüder nahm er fünf Männer und stellte sie vor Pharao.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'Und Pharao sprach zu seinen Brüdern: Was ist euer Tun? Und sie sprachen zu Pharao: Hirten des Kleinviehs sind deine Knechte, sowohl wir, als auch unsre Väter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Und sie sprachen zu Pharao: Um uns aufzuhalten im Lande, sind wir gekommen, weil keine Weide ist für das Kleinvieh, das deine Knechte haben; denn die Hungersnot ist schwer im Lande Kanaan; und nun möchten deine Knechte im Lande Gosen wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'Und Pharao sprach zu Joseph und sagte: Dein Vater und deine Brüder sind zu dir gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Das Land Ägypten, das ist vor dir. Laß deinen Vater und deine Brüder im Besten des Landes wohnen. Sie mögen wohnen im Lande Goschen. Und wenn du weißt, daß tüchtige Männer unter ihnen sind, so setze sie als Oberste über die Viehherden, die ich habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Und Joseph brachte Jakob, seinen Vater, und stellte ihn vor Pharao; und Jakob segnete Pharao.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'Und Pharao sprach zu Jakob: Wieviel sind die Tage deiner Lebensjahre?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Und Jakob sprach zu Pharao: Die Tage der Jahre meiner Wanderungen sind hundertdreißig Jahre. Wenig und böse waren die Tage meiner Lebensjahre, und reichen nicht an die Tage der Lebensjahre meiner Väter in den Tagen ihrer Wanderungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'Und Jakob segnete den Pharao, und ging hinaus von Pharao.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Joseph aber ließ seinen Vater und seine Brüder wohnen und gab ihnen Eigentum im Lande Ägypten, im Besten des Landes, im Lande Raamses, wie Pharao geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'Und Joseph versorgte seinen Vater und seine Brüder und das ganze Haus seines Vaters mit Brot nach dem Munde der Kindlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'Und es war kein Brot im ganzen Lande; denn die Hungersnot war sehr schwer, und das Land Ägypten und das Land Kanaan schmachteten vor Hunger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'Und Joseph sammelte alles Silber, das sich im Lande Ägypten und im Lande Kanaan fand, für das Getreide, das sie kauften, und Joseph brachte das Silber herein in das Haus Pharaos.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Und das Silber vom Lande Ägypten und vom Lande Kanaan war ganz aus, da kamen alle Ägypter zu Joseph und sprachen: Gib uns Brot! Warum sollen wir sterben vor dir, weil das Silber zu Ende ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Und Joseph sprach: Gebt eure Viehherden, und ich will es euch für eure Viehherden geben, wenn das Silber zu Ende ist!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Und sie brachten ihre Viehherden zu Joseph und Joseph gab ihnen Brot für die Pferde und für die Viehherden von Kleinvieh und für die Viehherden von Rindern und für die Esel, und er versorgte sie in diesem Jahr mit Brot für all ihre Viehherden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Und dieses Jahr war ganz aus, und sie kamen im zweiten Jahr zu ihm und sprachen zu ihm: Wir wollen es vor dem Herrn nicht verhehlen, daß unser Silber ganz aus ist, und das Besitztum des Viehs unsres Herrn ist, und uns vor dem Herrn nichts bleibt, als unser Leib und unser Boden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Warum sollten wir vor deinen Augen sterben, so wir, wie unser Boden. Kaufe uns und unseren Boden für das Brot, dann wollen wir und unser Boden dem Pharao Knechte sein, und gib Samen, daß wir leben und nicht sterben und der Boden nicht wüste werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Und Joseph kaufte allen Boden Ägyptens für Pharao; denn die Ägypter verkauften jeder Mann sein Feld, weil die Hungersnot stark war über ihnen, und das Land wurde des Pharao.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Und das Volk ließ er hinziehen nach den Städten vom Ende der Grenze Ägyptens und bis zu seinem Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Nur den Boden der Priester kaufte er nicht; denn die Priester hatten von Pharao ihr Bestimmtes, und sie aßen ihr Bestimmtes, das ihnen Pharao gegeben hatte, deshalb verkauften sie ihren Boden nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Und Joseph sprach zu dem Volke: Siehe, ich habe euch und euern Boden heute für Pharao gekauft. Da ist Samen für euch und besäet den Boden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Und von dem Ertrage sollet ihr den Fünften an Pharao geben, und vier Teile sollen euer sein für den Samen des Feldes und zu eurer Speise und derer, so in euern Häusern sind, und für eure Kindlein zum Essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Und sie sprachen: Du hast uns das Leben erhalten. Wir haben Gnade in den Augen des Herrn gefunden; und wir wollen Knechte sein dem Pharao.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'Und Joseph setzte dies zur Satzung ein bis auf diesen Tag über den Boden Ägyptens, dem Pharao den Fünften zu geben. Nur der Boden der Priester allein ward nicht des Pharaos.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'Und Israel wohnte im Lande Ägypten, im Lande Goschen; und sie hatten dort Eigentum, und waren fruchtbar und mehrten sich sehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Und Jakob lebte im Lande Ägypten siebzehn Jahre; und die Tage Jakobs, seiner Lebensjahre waren hundertsiebenundvierzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Und die Tage Israels nahten, daß er sterben sollte, und er rief seinen Sohn Joseph und sprach zu ihm: Wenn ich Gnade gefunden in deinen Augen, so lege doch deine Hand unter meine Hüfte und tue mir die Barmherzigkeit und Wahrheit, daß du mich doch nicht in Ägypten begrabest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Und laß mich liegen bei meinen Vätern, und trage mich hinauf aus Ägypten und begrabe mich in ihrem Grabe. Und er sprach: Ich will tun nach deinem Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Und er sprach: Schwöre mir! und er schwur ihm. Und Israel verbeugte sich über das Haupt seines Bettes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'Und es geschah nach diesen Dingen, daß man Joseph sagte: Siehe, dein Vater ist krank. Und er nahm seine zwei Söhne Menascheh und Ephraim mit sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'Und man sagte dem Jakob an und sprach: Siehe, dein Sohn Joseph kommt zu dir. Und Israel machte sich stark und setzte sich im Bette.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'Und Jakob sprach zu Joseph: Der Gott Schaddai erschien mir in Lus im Lande Kanaan und segnete mich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'Und Er sprach zu mir: Siehe, Ich mache dich fruchtbar und mehre dich und mache dich zu einem Haufen von Völkern, und gebe dieses Land deinem Samen nach dir zu ewigem Eigentum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'Und nun, deine zwei Söhne, die dir im Lande Ägypten geboren wurden, bis ich zu dir kam nach Ägypten, sind mein. Ephraim und Menascheh, wie Ruben und Simeon sollen sie mir sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Aber deine Erzeugten, die du nach ihnen zeugst, die sollen dein sein. Nach dem Namen ihrer Brüder sollen sie genannt werden in ihrem Erbteil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Und ich, als ich aus Padan kam, starb mir Rachel im Lande Kanaan auf dem Wege, da noch eine Strecke Landes war, bis man nach Ephratah kommt, und ich begrub sie daselbst im Wege Ephrath, das ist Bethlehem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Und Israel sah die Söhne Josephs und sprach: Wer sind diese?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'Und Joseph sprach zu seinem Vater: Meine Söhne sind es, die mir Gott hier gegeben hat. Und er sprach: Bring sie mir doch her, daß ich sie segne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Und Israels Augen waren schwer vor Alter, so daß er nicht sehen konnte, und er ließ sie herzutreten zu ihm, und er küßte und umarmte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'Und Israel sprach zu Joseph: Ich meinte nicht, dein Angesicht zu sehen, und siehe, Gott ließ mich auch deinen Samen sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Und Joseph ließ sie herauskommen von seinen Knien und verbeugte sich mit dem Antlitz zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'Und Joseph nahm sie beide, Ephraim mit seiner Rechten zur Linken Israels, und Menascheh mit seiner Linken zur Rechten Israels, und ließ sie zu ihm herzutreten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Und Israel streckte seine Rechte aus und legte sie auf das Haupt Ephraims, und der war der Jüngere, und seine Linke auf das Haupt Menaschehs, indem er seine Hände kreuzte, denn Menascheh war der Erstgeborene.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'Und er segnete Joseph und sprach: Der Gott, vor Dem meine Väter wandelten, Abraham und Isaak, der Gott, Der mich weidete, seit ich bin, bis auf diesen Tag;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'Der Engel, Der mich erlöset hat von allem Übel, segne die Jungen und mein Name werde in ihnen genannt, und der Name meiner Väter Abraham und Isaak, und sie sollen zunehmen zu einer Menge inmitten des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Und Joseph sah, daß sein Vater seine rechte Hand auf Ephraims Haupt legte, und es war böse in seinen Augen, und er hielt die Hand seines Vaters, um sie vom Haupte Ephraims wegzunehmen auf Menaschehs Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'Und Joseph sprach zu seinem Vater: Nicht also, mein Vater, denn dieser ist der Erstgeborene. Lege deine Rechte auf sein Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Sein Vater aber weigerte sich und sprach: Ich weiß es, mein Sohn, ich weiß es. Auch er wird zu einem Volke werden, und auch er wird groß werden; und gleichwohl wird sein kleiner Bruder größer werden, denn er; und sein Same wird eine Fülle von Völkerschaften sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'Und er segnete sie an diesem Tag und sprach: Mit dir soll Israel segnen und sprechen: Gott setze dich wie Ephraim und wie Menascheh; und er setzte Ephraim vor Menascheh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'Und Israel sprach zu Joseph: Siehe, ich sterbe, und Gott wird mit euch sein und euch zurückbringen zum Lande eurer Väter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'Und ich gebe dir einen Anteil über deine Brüder, denn ich aus der Hand der Amoriter mit meinem Schwert und meinem Bogen genommen habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'Und Jakob rief seine Söhne und sprach: Versammelt euch, und ich sage euch an, was euch in späteren Tagen begegnen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Kommet zusammen und höret, ihr Söhne Jakobs, und höret auf Israel, euern Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, mein Erstgeborener bist du, meine Kraft und der Anfang meiner Vollkraft, hervorragend an Erhabenheit und hervorragend an Stärke!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Leicht wie Wasser sollst du nicht hervorragen; denn du hast deines Vaters Lager bestiegen, da hast du es entweiht. Auf meine Lagerstätte ist er hinaufgestiegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon und Levi sind Brüder; Werkzeuge der Gewalttat sind ihre Dolche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'In ihr Geheimnis gehe nicht ein, meine Seele, mit ihrer Versammlung vereine dich nicht, meine Herrlichkeit; denn in ihrem Zorn erwürgten sie einen Mann, und in ihrem Wohlgefallen lähmten sie einen Ochsen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Verflucht sei ihr Zorn, denn er ist stark und ihr Wüten, denn es ist hart. Ich werde sie verteilen in Jakob und sie zerstreuen in Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Judah bist du; es werden dich lobpreisen deine Brüder; deine Hand soll sein am Nacken deiner Feinde; es werden sich vor dir niederbeugen die Söhne deines Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Das Junge eines Löwen ist Judah; vom Zerfleischten, mein Sohn, kommst du herauf. Er hat sich gebeugt und sich gelagert, wie der Löwe, wie ein gealterter Löwe! Wer will machen, daß er stehe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Nicht weggenommen wird von Judah das Zepter, noch der Gesetzgeber von zwischen seinen Füßen, bis daß Schiloh kommt; und ihm wird der Gehorsam der Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Er bindet an den Weinstock sein Eselsfüllen, und an die Edelrebe den Sohn seiner Eselin. Er wäscht im Weine seinen Anzug und im Blut der Weinbeeren seinen Mantel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'Tiefrot sind seine Augen vom Wein, und die Zähne sind weiß von Milch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Sebulon wird wohnen am Hafen der Meere, an dem Hafen der Schiffe und seine Seite über Sidon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isaschar ist ein knochiger Esel, der sich zwischen den Bürden lagert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Und er sieht die Ruhe, daß sie gut, und das Land, daß es lieblich sei, und neigt seine Schulter zum Lasttragen; und er wird ein zinsbarer Knecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan wird rechten für sein Volk, als einer der Stämme Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan wird eine Schlange am Wege und eine Pfeilschlange auf dem Pfade sein, die das Pferd in die Fersen beißt, so daß sein Reiter Rücklings fällt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Auf dein Heil hoffe ich, Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad werden Scharen verwüsten, aber er verwundet die Ferse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Fett ist das Brot, das von Ascher kommt, und Wonnen des Königs gibt er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Naphthali ist eine losgelassene Hindin; er gibt zierliche Reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Der Sohn einer Fruchtbaren ist Joseph, der Sohn einer Fruchtbaren an der Quelle, einer Tochter, die auf der Mauer einherschreitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Es erbittern ihn und schießen und grollen ihm die Meister der Pfeile.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'Aber sie wird sitzen in der Tüchtigkeit seines Bogens; und gestärkt werden die Arme seiner Hände von den Händen des Gewaltigen Jakobs. Von dort her ist der Hirte, der Stein Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'Von dem Gott deines Vaters, Der dir beistehen und mit Schaddai, Der dich segnen wird mit Segnungen des Himmels von oben, mit Segnungen des Abgrundes, der unten lagert, mit Segnungen der Brüste und des Mutterschoßes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Die Segnungen deines Vaters werden mächtiger sein, als die Segnungen meiner Erzeuger, bis zum Sehnen der Hügel des Zeitlaufs, sie werden sein auf Josephs Haupt und auf den Scheitel des Nasirs unter seinen Brüdern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin ist ein Wolf, der zerfleischt am Morgen, den Raub frißt und am Abend die Beute verteilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Das sind alle die zwölf Stämme Israels, und das ist, was ihr Vater zu ihnen redete. Und er segnete sie; jeden Mann gemäß seinem Segen segnete er sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'Und er gebot ihnen und sprach zu ihnen: Ich werde zu meinem Volke versammelt. Begrabet mich bei meinen Vätern in der Höhle, die im Felde Ephrons, des Chethiters, ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'In der Höhle, die im Felde Machpelah ist, bei dem Angesichte Mamres, im Lande Kanaan, welches Abraham mit dem Felde von Ephron, dem Chethiter gekauft für ein Grabeigentum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'Dorthin begruben sie Abraham und Sarah, sein Weib; dorthin begruben sie Isaak und Rebekah, sein Weib, und dorthin begrub ich Leah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Das Feld und die Höhle darin sind ein Ankauf von den Söhnen Cheths.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'Und Jakob vollendete seinen Söhnen zu gebieten, und er zog seine Füße zusammen in das Bett und verschied, und ward zu seinen Völkern versammelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Und es fiel Joseph auf das Angesicht seines Vaters und er weinte über ihm und küßte ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'Und Joseph gebot seinen Knechten, den Ärzten, seinen Vater einzubalsamieren, und die Ärzte balsamierten Israel ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'Und es wurden ihm erfüllt vierzig Tage; denn so werden die Tage der Einbalsamierten erfüllt; und die Ägypter beweinten ihn siebzig Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Und die Tage des Beweinens gingen vorüber, und Joseph redete zu dem Hause Pharaos und sagte: Wenn ich nun Gnade in euern Augen gefunden, so redet doch vor den Ohren Pharaos und saget:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Mein Vater hat mich schwören lassen und gesagt: Siehe, ich sterbe, du aber begrabe mich, dort in meinem Grabe, das ich mir im Lande Kanaan gegraben habe, und nun laß mich hinaufgehen und meinen Vater begraben und zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'Und Pharao sprach: Gehe hinauf und begrabe deinen Vater, wie er dich hat schwören lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Und Joseph ging hinauf, seinen Vater zu begraben; und es gingen mit ihm hinauf alle Knechte Pharaos, die Ältesten seines Hauses und alle Ältesten vom Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'Und das ganze Haus Josephs und seine Brüder und das Haus seines Vaters. Nur ihre Kindlein und ihr Kleinvieh und ihre Rinder ließen sie im Lande Goschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Und es gingen auch mit ihm hinauf Streitwagen und auch Reiter, und es war ein sehr großes Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Und sie kamen zur Tenne Atad, die am Übergang des Jordans ist, und sie klagten daselbst eine große und sehr schwere Klage, und Joseph stellte um seinen Vater eine Trauer von sieben Tagen an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Und der Einwohner des Landes, der Kanaaniter, sah die Trauer auf der Tenne Atad und sie sagten: Das ist eine schwere Trauer der Ägypter; deshalb nannte man den Namen Abel Mizraim, am Übergang des Jordans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Und seine Söhne taten ihm wie er ihnen geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'Und seine Söhne trugen ihn nach dem Lande Kanaan, und begruben ihn in der Höhle des Feldes Machpelah, die Abraham samt dem Felde zu einem Grabeigentum gekauft hatte von dem Chethiter Ephron, Mamre gegenüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'Und Joseph kehrte zurück nach Ägypten, er und seine Brüder und alle, die mit ihm heraufgezogen, um seinen Vater zu begraben, nachdem er seinen Vater begraben hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Und die Brüder Josephs sahen, daß ihr Vater tot war und sie sprachen: Joseph grollt uns vielleicht und gibt uns zurück all das Böse, das wir ihm angetan haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Und sie entboten dem Joseph und sagten: Dein Vater hat vor seinem Tode geboten und gesagt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'So sollt ihr sagen zu Joseph: Verzeihe doch die Übertretung deiner Brüder und ihre Sünde; denn Böses haben sie dir angetan; und nun verzeihe doch die Übertretung der Knechte des Gottes deines Vaters. Und Joseph weinte, als sie zu ihm redeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Und seine Brüder gingen auch und fielen vor ihm nieder und sprachen: Siehe, wir sind dir Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Und Joseph sprach zu ihnen: Fürchtet euch nicht. Bin ich denn an Gottes Statt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Ihr gedachtet über mir Böses, Gott aber gedachte es zum Guten, um zu tun wie es an diesem Tage ist, daß Er viel Volks am Leben erhalte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Und nun fürchtet euch nicht: Ich werde euch versorgen, euch und eure Kindlein; und er tröstete sie und redete zu ihrem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'Und Joseph wohnte in Ägypten, er und das Haus seines Vaters. Und Joseph lebte hundertzehn Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'Und Joseph sah von Ephraim Söhne bis ins dritte Glied, auch die Söhne von Machir, dem Sohne Menaschehs wurden auf Josephs Knien geboren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'Und Joseph sprach zu seinen Brüdern: Ich sterbe, und Gott wird euch gewißlich heimsuchen und euch hinaufbringen aus diesem Lande zum Lande, das Er Abraham, Isaak und Jakob geschworen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'Und Joseph ließ die Söhne Israels schwören und sprach: Gewißlich wird Gott euch heimsuchen, und ihr sollt meine Gebeine von da hinaufbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Und Joseph starb in einem Alter von hundertzehn Jahren, und sie balsamierten ihn ein; und er ward in eine Lade gelegt in Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'Und dies sind die Namen der Söhne Israels, die mit Jakob nach Ägypten kamen. Ein Mann und sein Haus kamen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi und Judah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isaschar, Sebulon und Benjamin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan und Naphthali, Gad und Ascher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'Und es waren alle Seelen, die aus Jakobs Hüfte hervorgegangen, siebzig Seelen. Joseph aber war in Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'Und Joseph starb und alle seine Brüder und selbiges ganze Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'Und die Söhne Israels waren fruchtbar und zeugten sich fort und mehrten sich und wurden sehr sehr zahlreich, und das Land ward angefüllt von ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Und es stand ein neuer König über Ägypten auf, der Joseph nicht kannte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Und er sprach zu seinem Volke: Siehe, das Volk der Söhne Israels wird mehr und zahlreicher denn wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Wohlan, lasset uns weislich handeln gegen dasselbe, daß es nicht sich mehre und wenn uns Krieg begegne, sich auch zu unseren Hassern hinzutue, und wider uns streite und aus dem Lande hinaufziehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Und sie setzten Oberste der Fröner über dasselbe, um es durch Lasten zu bedrücken; und es baute dem Pharao die Vorratsstädte Pithon und Raamses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'Aber je mehr sie es bedrückten, desto mehr vermehrte es sich und brach es hervor, so daß ihnen die Söhne Israels zum Überdrusse wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'Und die Ägypter hielten die Söhne Israels zum Dienst an mit Strenge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'Und verbitterten ihnen ihr Leben mit hartem Dienst in Lehm und Ziegeln und in allerlei Dienst auf dem Feld, nebst all ihren Diensten, zu denen sie mit Strenge sie dienstbar machten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'Und der König Ägyptens sprach zu den Wehmüttern der Hebräerinnen, wovon der Name der einen war Schiphrah, und der Name der andern Puah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'Und er sprach: Wenn ihr die Hebräerinnen entbindet und sie auf den Geburtsstühlen sehet, wenn es ein Sohn ist, so tötet ihn, ist es aber eine Tochter, so mag sie leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Die Wehmütter aber fürchteten Gott und taten nicht wie der König von Ägypten zu ihnen geredet hatte und ließen die Knaben am Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'Und der König von Ägypten rief die Wehmütter und sprach zu ihnen: Warum habt ihr so getan und die Knaben am Leben gelassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Die Wehmütter aber sprachen zu Pharao: Weil die Hebräerinnen nicht sind wie die ägyptischen Weiber; denn sie sind lebhaft, ehe die Wehmutter zu ihnen kommt, da haben sie geboren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'Und Gott tat den Wehmüttern Gutes; und das Volk mehrte sich und ward sehr zahlreich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'Und es geschah, weil die Wehmütter Gott fürchteten, so machte er ihnen Häuser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'Und Pharao gebot all seinem Volk und sprach: Jeglichen Sohn, der geboren wird, werfet in den Strom, jede Tochter aber lasset leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Und ein Mann vom Hause Levi ging hin und nahm eine Tochter Levi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'Und das Weib empfing und gebar einen Sohn; und sie sah ihn, daß er gut war, und verbarg ihn drei Monate.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'Und sie vermochte ihn nicht länger zu verbergen, und nahm ihm ein Kästlein von Binsen und verklebte es mit Erdharz und Pech, und legte das Kind hinein und legte es in das Schilf am Ufer des Stroms.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Und seine Schwester stellte sich von ferne, um zu erfahren, was mit ihm werden würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'Und Pharaos Tochter kam herab an den Strom, um zu baden, und ihre Mädchen gingen am Rande des Stromes; und sie sah das Kästlein mitten im Schilf und sandte ihre Magd und ließ es holen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Und sie öffnete es und sah das Kind, und siehe, der Junge weinte, und sie bemitleidete ihn und sprach: Es ist eines von den Kindern der Hebräer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'Und seine Schwester sprach zu der Tochter Pharaos: Soll ich gehen und dir ein säugendes Weib rufen von den Hebräerinnen, daß sie dir das Kind säuge?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'Und die Tochter Pharaos sprach zu ihr: Geh hin! Und die Jungfrau ging und rief die Mutter des Kindes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'Und die Tochter Pharaos sprach zu ihr: Nimm dieses Kind und säuge mir es und ich will dir deinen Lohn geben. Und das Weib nahm das Kind und säugte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'Und das Kind ward groß und sie brachte ihn zur Tochter des Pharao und er ward ihr zum Sohn, und sie nannte seinen Namen Mose; und sprach: Weil aus dem Wasser ich ihn habe gezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'Und es geschah in jenen Tagen, als Mose war groß geworden, daß er hinausging zu seinen Brüdern und ihre Lasten sah. Und er sah, wie ein ägyptischer Mann einen hebräischen Mann von seinen Brüdern schlug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'Und er wandte sich hin und her und sah, daß kein Mann da war, und schlug den Ägypter und verbarg ihn im Sande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'Und er ging am zweiten Tag aus und siehe, zwei hebräische Männer zankten sich. Und er sprach zu dem, der Unrecht hatte: Warum schlägst du deinen Genossen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Und er sprach: Wer hat dich zum Manne, der Oberste und Richter über uns gesetzt? Sprichst du so, um mich auch zu erwürgen, wie du den Ägypter erwürgt hast? Und Mose fürchtete sich und sprach: So ist also die Sache bekannt geworden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'Und Pharao hörte diese Sache und er suchte den Mose zu erwürgen. Mose aber entfloh vor Pharao und wohnte im Lande Midian; und er wohnte bei einem Brunnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Und der Priester Midians hatte sieben Töchter. Und sie kamen und schöpften und füllten die Rinnen, um das Kleinvieh ihres Vaters zu tränken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'Und die Hirten kamen und trieben sie fort. Und Mose erhob sich und half ihnen und tränkte ihr Kleinvieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'Und sie kamen zu ihrem Vater Reuel und er sprach: Warum kommet ihr heute so eilig nach Hause?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'Und sie sagten: Ein ägyptischer Mann rettete uns aus der Hand der Hirten und hat uns auch geschöpft und das Kleinvieh getränkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'Und er sprach zu seinen Töchtern: Und wo ist er? Warum habt ihr den Mann zurückgelassen? Ruft ihm, daß er Brot esse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'Und Mose war willens, bei dem Manne zu wohnen; und er gab dem Mose seine Tochter Zipporah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'Und sie gebar einen Sohn und er nannte seinen Namen Gerschom; denn er sprach: Ich war ein Fremdling in einem auswärtigen Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'Und es geschah nach vielen Tagen, daß der König von Ägypten starb. Und die Söhne Israels seufzten über ihre Knechtschaft und schrien und ihr Geschrei stieg auf zu Gott ob der Knechtschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'Und Gott hörte ihr Stöhnen und Gott gedachte seines Bundes mit Abraham, mit Isaak und mit Jakob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'Und Gott sah die Söhne Israels und Gott wußte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Und Mose weidete das Kleinvieh Jethros, seines Schwähers, des Priesters von Midian, und führte das Kleinvieh hinter die Wüste und kam zum Berge Gottes Horeb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'Und es erschien ihm der Engel Jehovahs in der Flamme des Feuers mitten aus dem Dornbusch; und er sah hin und siehe, der Dornbusch brannte mit Feuer; und der Dornbusch ward doch nicht verzehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'Und Mose sprach: Ich will doch ablenken und sehen dies große Gesicht, warum der Dornbusch nicht brennt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Und Jehovah sah, daß er ablenkte zu sehen und Gott rief ihm mitten aus dem Dornbusche und sprach: Mose! Mose! Und er sprach: Hier bin ich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'Und Er sprach: Nahe dich nicht hierher! Zieh deine Schuhe von deinen Füßen; denn der Ort, auf dem du stehst, ist Boden der Heiligkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'Und sagte: Ich bin der Gott deines Vaters, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs. Und Mose verbarg sein Ange- sicht; denn er fürchtete sich, auf Gott zu blicken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'Und Jehovah sprach: Ich habe das Elend Meines Volkes in Ägypten gesehen und ihr Schreien gehört ob ihren Fronvögten; denn Ich kenne seine Schmerzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'Und Ich bin herabgestiegen, es aus der Hand der Ägypter zu erretten, und es aus diesem Lande heraufzuführen in ein Land, gut und weit, in ein Land, das von Milch und Honig fließt, zum Orte der Kanaaniter und Chethiter und Amoriter und Pherisiter und Chiviter und Jebusiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'Und nun siehe, das Geschrei, der Söhne Israels ist zu Mir gekommen und Ich habe auch den Druck gesehen, wie die Ägypter sie unterdrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Und nun, gehe hin, und Ich sende dich zu Pharao; und bringe Mein Volk, die Söhne Israels aus Ägypten heraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'Und Mose sprach zu Gott: Wer bin ich, daß ich zu Pharao ginge und die Söhne Israels aus Ägypten brächte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'Und Er sprach: Weil Ich mit dir sein werde; und dies soll das Zeichen sein, daß Ich dich gesandt habe: Wenn du das Volk aus Ägypten herausgebracht, werdet ihr an diesem Berge Gott dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'Und Mose sprach zu Gott: Siehe, wenn ich zu den Söhnen Israels komme und ihnen sage: Der Gott eurer Väter hat mich zu euch gesandt und sie zu mir sagen: Welches ist Sein Name, was soll ich zu ihnen sagen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'Und Gott sprach zu Mose: Ich bin, der Ich bin; und Er sprach: So sollst du zu den Söhnen Israels sprechen: Der Ich bin hat mich zu euch gesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'Und weiter sprach Gott zu Mose: So sollst du zu den Söhnen Israels sprechen: Jehovah, der Gott eurer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs hat mich zu euch gesandt. Das ist Mein Name in Ewigkeit, und das ist Mein Gedächtnis zum Geschlecht des Geschlechts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Geh und versammle die Ältesten Israels und sprich zu ihnen: Jehovah, der Gott eurer Väter ist mir erschienen, der Gott Abrahams, Isaaks und Jakobs, und hat gesagt: Ich habe euch heimgesucht und was euch in Ägyptenland getan worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'Und Ich sage: Ich werde euch aus dem Elende Ägyptens in das Land der Kanaaniter und Chethiter und Amoriter und Pherisiter und Chiviter und Jebusiter in ein Land heraufbringen, das von Milch und Honig fließt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'Und hören sie auf deine Stimme, dann gehst du und die Ältesten Israels zum Könige von Ägypten, und ihr saget ihm: Jehovah, der Gott der Hebräer, ist uns begegnet, und nun laß uns doch drei Tagreisen in die Wüste ziehen, daß wir Jehovah, unserem Gotte, opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Und Ich weiß, daß euch der König von Ägypten nicht wird ziehen lassen, auch nicht durch starke Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'Und Ich werde Meine Hand ausstrecken und Ägypten schlagen mit allen Meinen Wundern, die Ich in seiner Mitte tun werde; und danach wird er euch entlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'Und Ich werde diesem Volke Gnade in den Augen der Ägypter geben, und es wird geschehen, daß wenn ihr gehet, ihr nicht leer gehet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'Und ein jegliches Weib soll sich von ihrer Nachbarin und von ihrer Hausgenossin Gefäße von Silber und Gefäße von Gold und Gewänder erbeten, und ihr sollet sie auf eure Söhne und auf eure Töchter legen und den Ägyptern entreißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Und Mose antwortete und sprach: Aber siehe, sie werden mir nicht glauben und nicht auf meine Stimme hören; denn sie werden sagen: Jehovah ist dir nicht erschienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'Und Jehovah sprach zu ihm: Was hast du in deiner Hand? Und er sprach: Einen Stab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'Und Er sprach: Wirf ihn zur Erde. Und er warf ihn zur Erde; und er ward zu einer Schlange und Mose floh vor ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'Und Jehovah sprach zu Mose: Strecke deine Hand aus und ergreife sie beim Schwanz. Und er streckte seine Hand aus und faßte sie fest; und sie ward zum Stab in seiner Hand:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'Auf daß sie glauben, daß Jehovah, der Gott ihrer Väter, der Gott Abrahams, der Gott Isaaks und der Gott Jakobs, dir erschienen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Und Jehovah sprach weiter zu ihm: Strecke doch deine Hand in deinen Busen. Und er streckte seine Hand in seinen Busen und zog sie heraus und siehe! seine Hand war aussätzig, wie Schnee.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'Und Er sprach: Steck deine Hand zurück in deinen Busen. Und er steckte seine Hand zurück in seinen Busen und zog sie heraus aus seinem Busen, und siehe! sie ward wieder wie sein Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'Und es soll geschehen, wenn sie dir nicht glauben, noch auf die Stimme des ersten Zeichens hören, so werden sie der Stimme des nachfolgenden Zeichens glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'Und es soll geschehen, wenn sie auch diesen zwei Zeichen nicht glauben, noch auf deine Stimme hören, dann nimm von dem Wasser des Stromes und gieß es auf das Trockene, so wird das Wasser, das du aus dem Strom genommen, auf dem Trockenen zu Blut werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'Und Mose sprach zu Jehovah: Ach, Herr, ich bin kein Mann von Worten, weder gestern, noch ehegestern, noch seit Du mit deinem Knechte redest; denn ich bin schwer von Mund und schwer von Zunge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'Und Jehovah sprach zu ihm: Wer macht des Menschen Mund? Oder wer macht stumm oder taub oder sehend oder blind? Bin nicht Ich es, Jehovah?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'Und nun gehe und Ich will mit deinem Munde sein und dich unterweisen, was du reden sollst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'Und er sprach: Ach, Herr sende doch, durch wessen Hand du senden willst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'Und es entbrannte der Zorn Jehovahs wider Moses und Er sprach: Ist nicht Aharon, der Levite, dein Bruder? Ich weiß, daß er reden kann. Und siehe, er geht auch aus dir entgegen, und wird dich sehen und fröhlich sein in seinem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Und du sollst zu ihm reden und die Worte in seinen Mund legen und Ich will mit deinem Munde und mit seinem Munde sein und euch unterweisen, was ihr tun sollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'Und er soll für dich zum Volke reden, und es wird geschehen, daß er dein Mund ist und du ihm der Gott bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'Und diesen Stab nimm in deine Hand, mit ihm sollst du die Zeichen tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'Und Mose ging und kehrte zu Jethro, seinem Schwäher zurück und sprach zu ihm: Laß mich doch gehen, und zu meinen Brüdern, die in Ägypten sind, zurückkehren, auf daß ich sehe, ob sie noch leben. Und Jethro sprach zu Mose: Gehe hin im Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'Und Jehovah sprach zu Mose in Midian: Gehe, kehre zurück nach Ägypten; denn gestorben sind alle die Männer, die dir nach deiner Seele trachteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Und Mose nahm sein Weib und seine Söhne und ließ sie auf dem Esel reiten, und kehrte nach Ägyptenland zurück, und Mose nahm den Stab Gottes in seine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'Und Jehovah sprach zu Mose: Wenn du gehst, um nach Ägypten zurückzukehren, so siehe zu, daß du alle Wahrzeichen, die Ich in deine Hand gelegt habe, vor Pharao tust. Ich aber werde sein Herz bestärken, daß er das Volk nicht entläßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'Und du sollst zu Pharao sprechen: Also spricht Jehovah: Mein Sohn, Mein Erstgeborener, ist Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'Und Ich sage dir: Entlasse Meinen Sohn, auf daß er Mir diene. Weigerst du dich aber, ihn zu entlassen, siehe, so erwürge Ich deinen Sohn, deinen Erstgeborenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'Und es geschah auf dem Wege in dem Nachtlager, daß Jehovah auf ihn traf und trachtete ihn zu töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'Und Zipporah nahm einen Stein und beschnitt die Vorhaut ihres Sohnes und ließ sie seine Füße berühren und sprach: Ein Bräutigam des Blutes bist du mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'Und Er ließ von ihm ab; da sagte sie: Ein Bräutigam des Blutes um der Beschneidung willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'Und Jehovah sprach zu Aharon: Geh Mose entgegen nach der Wüste. Und er ging und traf ihn auf dem Berge Gottes und küßte ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'Und Mose sagte dem Aharon an alle Worte Jehovahs, womit Er ihn gesendet und alle Zeichen, die Er ihm geboten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Und Mose und Aharon gingen und sie versammelten alle Ältesten der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'Und Aharon redete alle die Worte, die Jehovah zu Mose geredet hatte, und tat die Zeichen vor den Augen des Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'Und das Volk glaubte; und sie hörten, daß Jehovah die Söhne Israels heimgesucht und ihr Elend gesehen; und sie verneigten und sie verbeugten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'Und danach kamen Mose und Aharon und sprachen zu Pharao: So spricht Jehovah, der Gott Israels: Entlasse Mein Volk, daß sie Mir ein Fest feiern in der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'Und Pharao sprach: Wer ist der Jehovah, auf Dessen Stimme ich hören soll, Israel zu entlassen? Ich kenne den Jehovah nicht und entlasse auch Israel nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'Und sie sprachen: Der Gott der Hebräer ist uns begegnet. Laß uns doch einen Weg von drei Tagreisen in die Wüste ziehen, daß wir Jehovah, unserem Gott, opfern, auf daß Er nicht mit Pest oder dem Schwerte auf uns stoße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'Und der König von Ägypten sprach zu ihnen: Warum wollt ihr, Mose und Aharon, das Volk von seinen Werken abwendig machen? Geht an eure Lasten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'Und Pharao sprach: Siehe, viel ist schon des Volkes im Lande und ihr wollt sie von ihren Lasten feiern lassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'Und an jenem Tage gebot Pharao den Fronvögten im Volk und seinen Vorstehern, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Gebet nicht ferner Stroh dem Volke zum Ziegelmachen, wie gestern und ehegestern. Lasset sie gehen und selber sich Stroh zusammenstoppeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Und das Maß der Ziegel, die sie gestern und ehegestern machten, leget ihnen auf, nehmet nichts weg davon. Lässig sind sie, deshalb schreien sie und sagen: Lasset uns gehen, daß wir unserem Gotte opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Schwer sei der Dienst auf den Männern, und lasset sie ihn tun und nicht nach lügenhaften Worten schauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'Und die Fronvögte des Volkes und seine Vorsteher gingen hinaus und sprachen zu dem Volk und sagten: So spricht Pharao: Ich gebe euch kein Stroh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Gehet selber und nehmet euch Stroh, wo ihr es findet. Doch vom Dienst wird euch nichts abgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'Und das Volk zerstreute sich im ganzen Land Ägypten, um Stoppeln für das Stroh zusammenzutragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Und die Fronvögte trieben sie an und sprachen: Vollendet euer Werk, das Tagewerk an seinem Tage, wie, da ihr Stroh hattet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'Und die Vorsteher der Söhne Israels, welche die Fronvögte Pharaos über sie gesetzt, wurden geschlagen, indem man sagte: Warum habt ihr nicht vollendet eure Satzung Ziegel zu machen wie gestern und ehegestern, weder gestern noch heute?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'Und die Vorsteher der Söhne Israels kamen und schrien vor Pharao und sprachen: Warum tust du also deinen Knechten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Stroh wird deinen Knechten keines gegeben, und sie sagen uns: Ihr habet Ziegel zu machen, und siehe, deine Knechte schlägt man, und dein Volk hat gesündigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'Und er sprach: Lässig seid ihr, lässig, deshalb sprecht ihr: Lasset uns gehen und dem Jehovah opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'Und nun gehet und dienet; und Stroh wird euch keines gegeben; aber euer Maß Ziegel habt ihr zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'Und die Vorsteher der Söhne Israels sahen, daß sie übel daran waren; denn man sagte: Ihr dürfet von euern Ziegeln nichts ablassen, vom Tagewerk an seinem Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Und sie stießen auf Mose und Aharon, die sich ihnen gegenüberstellten, als sie von Pharao herauskamen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'Und sie sprachen zu ihnen: Jehovah sehe auf euch und richte. Ihr habt unseren Geruch stinkend gemacht in den Augen Pharaos und in den Augen seiner Knechte, um ihnen das Schwert in die Hand zu geben, uns zu erwürgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'Und Mose kehrte zu Jehovah zurück und sprach: Herr, warum hast Du diesem Volk übel getan? Warum hast Du mich denn gesandt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Und seitdem ich zu Pharao gekommen bin, um in Deinem Namen zu reden, hat er diesem Volke Böses getan, und Du hast Dein Volk nicht errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'Und Jehovah sprach zu Mose: Nun sollst du sehen, was Ich dem Pharao tun werde. Denn durch starke Hand soll er sie entlassen, und durch starke Hand sie aus seinem Lande forttreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'Und Gott redet zu Mose und sprach zu ihm: Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'Und bin Abraham, Isaak und Jakob als Gott Schaddai erschienen, aber bei Meinem Namen Jehovah wurde Ich ihnen nicht bekannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Und habe auch Meinen Bund mit ihnen aufgerichtet, ihnen das Land Kanaan zu geben, das Land ihrer Wanderungen, in dem sie Fremdlinge waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Und Ich habe das Stöhnen der Söhne Israels gehört, welche die Ägypter knechten, und gedenke Meines Bundes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Darum sprich zu den Söhnen Israels: Ich bin Jehovah, und Ich bringe euch von den Lasten der Ägypter heraus und errette euch aus ihrer Knechtschaft, mit ausgestrecktem Arm und mit großen Gerichten will Ich euch erlösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'Und Ich nehme euch Mir zum Volk und werde euch Gott sein, und ihr sollt wissen, daß Ich Jehovah, euer Gott bin, Der euch von den Lasten Ägyptens herausgebracht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'Und bringe euch zu dem Land, das Ich dem Abraham, Isaak und Jakob zu geben Meine Hand aufhob, und euch nun zum erblichen Besitztum gebe; Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'Und Mose redete so mit den Söhnen Israels; aber sie hörten vor Ungeduld des Geistes und harter Knechtschaft nicht auf Mose.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'Und Jehovah redete mit Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Gehe hinein, rede zu Pharao, dem Könige Ägyptens, und er soll die Söhne Israels aus seinem Land entlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'Und Mose redete vor Jehovah und sprach: Siehe, die Söhne Israels hörten nicht auf mich; und wie sollte Pharao auf mich hören? und ich bin unbeschnitten an Lippen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'Und Jehovah redete zu Mose und zu Aharon und gebot ihnen an die Söhne Israels und an Pharao, den König von Ägypten, die Söhne Israels aus Ägyptenland herauszubringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'Das sind die Häupter des Hauses ihrer Väter: Die Söhne Rubens, des Erstgeborenen Israels: Chanoch und Pallu, Chezron und Karmi. Das sind die Familien Rubens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'Und die Söhne Simeons: Jemuel und Jamin und Ohad und Jachin und Zochar und Schaul, der Sohn der Kanaaniterin. Dies die Familien Simeons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'Und das sind die Namen der Söhne Levis nach ihren Geschlechtern: Gerschon und Kohath und Merari, und die Jahre des Lebens Levis waren hundertsiebenunddreißig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Die Söhne Gerschons sind Libni und Schimei nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'Und die Söhne Kohaths: Amram und Jizhar und Chebron und Ussiel, und die Jahre des Lebens Kohaths sind hundertdreiunddreißig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'Und die Söhne Meraris sind Machli und Muschi. Dies die Familien Levis nach ihren Geschlechtern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'Und Amram nahm sich seine Muhme Jochebed zum Weibe, und sie gebar ihm Aharon und Mose; und die Jahre des Lebens Amrams waren hundertsiebenunddreißig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'Und die Söhne Jizhars waren Korach und Nepheg und Sichri.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'Und die Söhne Ussiels: Mischael und Elzaphan und Sithri.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'Und Aharon nahm Elischeba, Tochter Aminadabs, Schwester des Nachasson, sich zum Weibe und sie gebar ihm Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'Und die Söhne Korachs: Assir und Elkanah und Abiasaph. Das sind die Familien der Korachiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'Und Eleasar, Sohn Aharons, nahm sich eine von Putiels Töchtern zum Weibe, und sie gebar ihm Pinechas. Dies sind die Häupter der Väter der Leviten nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'Das ist Aharon und Mose, zu denen Jehovah sprach: Bringet Israels Söhne heraus aus dem Lande Ägypten nach ihren Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Sie sind es, die zu Pharao, dem Könige von Ägypten, redeten, daß sie möchten die Söhne Israels aus Ägypten herausbringen, das ist Moses und Aharon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'Und es geschah an dem Tage, da Jehovah zu Mose redete im Lande Ägypten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'Und Jehovah redete zu Mose und sprach: Ich bin Jehovah! Rede zu Pharao, Ägyptens König, alles, was Ich zu dir rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'Und Mose sprach vor Jehovah: Siehe, ich bin unbeschnitten an Lippen, und wie wird Pharao auf mich hören?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'Und Jehovah sprach zu Mose: Siehe, Ich habe dich zum Gott für Pharao gegeben, und Aharon, dein Bruder, soll dein Prophet sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Du sollst alles reden, was Ich dir gebiete und dein Bruder Aharon soll reden zu Pharao, auf daß er die Söhne Israels aus seinem Lande entlasse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Und Ich will verhärten Pharaos Herz, und viel machen Meiner Zeichen und Meiner Wahrzeichen in Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'Und Pharao wird nicht auf euch hören; aber Ich werde Meine Hand auf die Ägypter legen und durch große Gerichte Meine Heerscharen, Mein Volk, die Söhne Israels aus Ägyptenland herausbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'Und wissen sollen die Ägypter, daß Ich Jehovah bin, wenn Ich Meine Hand ausstrecke über Ägypten und Israels Söhne aus ihrer Mitte herausbringe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Und Mose und Aharon taten wie Jehovah ihnen geboten hatte, so taten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'Und Mose war achtzig Jahre alt und Aharon dreiundachtzig Jahre alt, als sie zu Pharao redeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'Und Jehovah redete zu Mose und zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'So Pharao zu euch redet und spricht: Gebet für euch ein Wahrzeichen, dann sprich zu Aharon: Nimm deinen Stab und wirf ihn hin vor Pharao. Er soll zur Wasserschlange werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'Und Mose ging hinein und Aharon zu Pharao und sie taten so wie Jehovah geboten hatte, und Aharon warf seinen Stab vor Pharao und vor seine Knechte und er ward zur Wasserschlange.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Und Pharao rief auch die Weisen und Zauberer, und auch sie, die Wahrsager Ägyptens, taten also mit ihren Zauberformeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'Und sie warfen jeder Mann seinen Stab hin, und sie wurden zu Wasserschlangen; aber Aharons Stab verschlang ihre Stäbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Und Pharaos Herz ward bestärkt; und er hörte nicht auf sie, wie Jehovah geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'Und Jehovah sprach zu Mose: Schwer ist Pharaos Herz; er weigert sich, das Volk zu entlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Gehe zu Pharao am Morgen! Siehe, er geht aus an das Wasser, und stelle dich ihm entgegen am Ufer des Stromes, und nimm den Stab, der in eine Schlange verwandelt worden, in deine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'Und sprich zu ihm: Jehovah, der Gott der Hebräer, hat mich zu dir gesandt und spricht: Entlaß Mein Volk, daß sie Mir dienen in der Wüste! Und siehe, du hast bis jetzt nicht darauf gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'So spricht Jehovah: Daran sollst du wissen, daß Ich Jehovah bin: Siehe, ich schlage mit dem Stabe, der in meiner Hand ist, auf die Wasser, die im Strome sind, und sie werden in Blut verwandelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Und der Fisch im Strom soll sterben, und stinken soll der Strom, daß die Ägypter sich abmühen, Wasser aus dem Strome zu trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'Und Jehovah sprach zu Mose: Sprich zu Aharon: Nimm deinen Stab und strecke deine Hand aus über die Wasser Ägyptens, über ihre Flüsse, über ihre Ströme und über ihre Seen und über jegliche Sammlung ihrer Wasser, und sie sollen zu Blut werden; und soll Blut sein im ganzen Land Ägypten und in Holz und in Stein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'Und Mose und Aharon taten so, wie Jehovah geboten hatte. Und er hob den Stab empor und schlug die Wasser in dem Strom vor den Augen Pharaos und vor den Augen seiner Knechte, und alle Wasser in dem Strom wurden in Blut verwandelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'Und der Fisch im Strome starb und der Strom stank, und die Ägypter vermochten nicht das Wasser aus dem Strom zu trinken; und das Blut war in ganz Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'Und es taten so auch die Wahrsager Ägyptens mit ihren Zauberformeln und Pharaos Herz ward bestärkt und er hörte nicht auf sie, wie Jehovah geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'Und Pharao wandte sich und kam in sein Haus, und nahm auch dies nicht zu Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'Und alle Ägypter gruben in den Umgebungen des Stroms nach Wasser zum Trinken; denn sie vermochten nicht von dem Wasser des Stromes zu trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'Und es wurden erfüllt sieben Tage, seitdem Jehovah den Strom geschlagen hatte. Und Jehovah sprach zu Mose: Gehe hinein zu Pharao und sprich zu ihm: So spricht Jehovah: Entlaß Mein Volk, daß sie Mir dienen. Und wenn du dich weigerst, es zu entlassen, siehe, so schlage ich all deine Grenze mit Fröschen. Und der Strom soll von Fröschen wimmeln, und sie sollen heraufsteigen und kommen in dein Haus und in deine Schlafkammer und auf dein Bett, und in das Haus deiner Knechte und zu deinem Volk, und in deine Öfen und in deine Backtröge. Und an dich und dein Volk und an alle deine Knechte sollen die Frösche heraufkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Und Jehovah sprach zu Mose: Sprich zu Aharon: Strecke deine Hand aus mit deinem Stab über die Flüsse, über die Ströme und über die Seen, und bringe die Frösche herauf über Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Und Aharon streckte seine Hand aus über die Wasser Ägyptens, und herauf kam der Frosch und bedeckte Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'Und die Wahrsager taten mit ihren Zauberformeln gleich also. Und sie brachten Frösche herauf über Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'Und Pharao rief Mose und Aharon und sprach: Flehet zu Jehovah, daß Er die Frösche von mir und Meinem Volk wegnehme; und ich will das Volk entlassen, daß sie dem Jehovah opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'Und Mose sprach zu Pharao: Habe du den Ruhm über mich, bis wann soll ich für dich und für deine Knechte und für dein Volk flehen, daß die Frösche von dir und deinen Häusern ausgerottet werden; nur im Strom werden sie verbleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'Und er sprach: Auf morgen! und er sprach: Nach deinem Wort! auf daß du wissest, daß keiner ist wie Jehovah, unser Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'Und die Frösche sollen weichen von dir und deinen Häusern und von deinen Knechten und von deinem Volk; nur in dem Strome sollen sie verbleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Und Mose ging hinaus und Aharon fort von Pharao, und Mose schrie zu Jehovah der Frösche wegen, die Er über Pharao gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'Und Jehovah tat nach Moses Wort, und die Frösche starben weg aus den Häusern, aus den Höfen und aus den Feldern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'Und sie häuften sie auf zu Haufen und Haufen, und das Land stank.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'Und Pharao sah, daß er wieder atmen konnte und er verstockte sein Herz und hörte nicht auf sie, wie Jehovah geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'Und Jehovah sprach zu Mose: Sprich zu Aharon: Strecke deinen Stab aus und schlage den Staub der Erde, daß er zu Läusen werde in ganz Ägyptenland!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'Und sie taten also, und Aharon streckte seine Hand aus mit seinem Stab und schlug den Staub der Erde, und die Läuse waren an Mensch und Vieh; aller Staub der Erde ward zu Läusen im ganzen Land Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'Und es taten die Wahrsager auch also mit ihren Zauberformeln, um Läuse hervorzubringen und sie vermochten es nicht, und die Läuse waren an Mensch und Vieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Und die Wahrsager sprachen zu Pharao: Dies ist der Finger Gottes! Und das Herz Pharaos bestärkte sich und er hörte nicht auf sie, wie Jehovah geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'Und Jehovah sprach zu Mose: Stehe früh am Morgen auf und stelle dich vor Pharao. Siehe, er geht aus an das Wasser; und sprich zu ihm: So spricht Jehovah: Entlaß Mein Volk, daß sie Mir dienen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'Entlässest du nicht Mein Volk, siehe, da sende Ich Ungeziefer wider dich, wider deine Knechte und wider dein Volk und wider deine Häuser und die Häuser der Ägypter sollen voll vom Ungeziefer sein, und auch der Boden, auf dem sie sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'Und Ich will unterscheiden an jenem Tag Goschens Land, auf dem Mein Volk steht; daß dort das Ungeziefer nicht soll sein, damit du wissest daß Ich Jehovah bin inmitten des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Und eine Erlösung will Ich zwischen Mein Volk und zwischen deinem Volk setzen; morgen geschehe dieses Zeichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'Und Jehovah tat also. Und schwer kam das Ungeziefer in Pharaos Haus und in seiner Knechte Haus und in das ganze Ägyptenland; das Land verdarb vor Ungeziefer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Und Pharao rief Mose und Aharon und sprach: Gehet, opfert eurem Gott in dem Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'Mose aber sprach: Es ist nicht richtig, so zu tun, denn sonst würden wir den Greuel der Ägypter Jehovah, unserem Gotte, opfern. Siehe, würden wir den Greuel der Ägypter vor ihren Augen opfern, würden sie uns nicht steinigen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'Drei Tagreisen wollen wir in die Wüste ziehen und Jehovah, unserem Gotte, opfern, wie Er uns sagte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'Und Pharao sprach: Ich will euch entlassen, daß ihr Jehovah, eurem Gotte, opfert in der Wüste. Nur sollt ihr nicht ferne gehen; flehet für mich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Und Mose sprach: Siehe, ich gehe hinaus von dir und werde zu Jehovah flehen; und Er wird morgen wegnehmen das Ungeziefer von Pharao, von seinen Knechten und von seinem Volke. Nur möge Pharao nicht mehr uns hintergehen, das Volk nicht zu entlassen, daß es Jehovah opfere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'Und Mose ging hinaus von Pharao und flehte zu Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Und Jehovah tat nach dem Worte Moses und nahm weg das Ungeziefer von Pharao, von seinen Knechten und von seinem Volk; nicht eines verblieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'Aber Pharao verstockte sein Herz auch diesmal und entließ das Volk nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Und Jehovah sprach zu Mose: Gehe hinein zu Pharao und rede zu ihm: So spricht Jehovah, der Gott der Hebräer: Entlaß Mein Volk, daß sie Mir dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Denn, wenn du dich weigerst, sie zu entlassen und sie noch länger festhältst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'Siehe, so ist die Hand Jehovahs wider deine Viehherden, die auf dem Felde sind, wider die Pferde, wider die Esel, wider die Kamele, wider das Rindvieh und wider das Kleinvieh mit sehr schwerer Pestilenz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'Und Jehovah wird unterscheiden zwischen den Viehherden Israels und den Viehherden Ägyptens, so daß nicht ein Stück von dem, das die Söhne Israels haben, sterben wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'Und Jehovah setzte eine bestimmte Zeit und sprach: Morgen wird Jehovah dies im Lande tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'Und Jehovah tat dies am morgenden Tag, und alle Viehherden Ägyptens starben, und von den Viehherden Israels starb nicht eines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Und Pharao sandte und siehe, von den Viehherden Israels war nicht eines gestorben. Aber Pharaos Herz verstockte sich und er entließ das Volk nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Und Jehovah sprach zu Mose und zu Aharon: Nehmet euch die Fäuste voll Ruß des Ofens und Mose sprenge ihn gen Himmel vor den Augen Pharaos.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'Und er soll zu feinem Staub werden über ganz Ägyptenland, und soll werden an Menschen und an Vieh zu einem Geschwür, das aufbricht mit Blattern, in ganz Ägyptenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Und sie nahmen den Ofenruß, standen vor Pharao und Mose sprengte ihn gen Himmel, und er ward zu einem Geschwür, das ausbrach in Blattern, an Mensch und an Vieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'Und es vermochten die Wahrsager nicht zu stehen vor Mose wegen des Geschwürs; denn das Geschwür war an den Wahrsagern und an allen Ägyptern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Und Jehovah bestärkte Pharaos Herz, so daß er nicht auf sie hörte, so wie Jehovah zu Mose geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'Und Jehovah sprach zu Mose: Stehe auf früh am Morgen und stelle dich vor Pharao und sprich zu ihm: So spricht Jehovah, der Gott der Hebräer: Entlaß Mein Volk, daß sie Mir dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Denn diesmal sende Ich alle Meine Plagen über dein Herz und über deine Knechte und über dein Volk, auf daß du wissest, daß keiner ist wie Ich, auf der ganzen Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Und nun hätte Ich Meine Hand ausgestreckt und dich und dein Volk mit der Pestilenz geschlagen, daß von der Erde du weggeschafft werdest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Aber darum ließ Ich dich noch stehen, darum, daß Ich dich sehen lasse Meine Kraft, und man von Meinem Namen auf der ganzen Erde erzähle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Wirfst du dich gegen Mein Volk noch länger, auf daß du sie nicht entlässest:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'Siehe, so lasse Ich um die morgende Zeit einen sehr schweren Hagel regnen, wie noch keiner in Ägypten gewesen ist, seit dem Tage, daß es gegründet ward, bis jetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Und nun, sende und laß zusammenflüchten deine Viehherden und alles, was du auf dem Felde hast. Jedweder Mensch und das Vieh, das auf dem Feld sich findet und nicht ins Haus versammelt ist, so der Hagel auf sie herabkommt, wird sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Wer von den Knechten Pharaos das Wort Jehovahs fürchtete, der ließ seine Knechte und seine Viehherden in die Häuser fliehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Wer sich aber Jehovahs Wort nicht zu Herzen legte, der ließ seine Knechte und seine Viehherden auf dem Felde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'Und Jehovah sprach zu Mose: Strecke deine Haus aus gen Himmel, daß es hagle auf ganz Ägyptenland, auf Mensch und Vieh und auf alles Kraut des Feldes im Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'Und Mose streckte seinen Stab aus gen Himmel und Jehovah gab Stimmen und Hagel und ineinanderfahrendes Feuer zur Erde hin; und Jehovah ließ Hagel regnen auf das Land Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'Und es ward ein Hagel und ein ineinanderfahrendes Feuer inmitten des Hagels; sehr schwer, so daß desgleichen noch nie gewesen war in ganz Ägyptenland, seit es zu einer Völkerschaft wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'Und der Hagel schlug in ganz Ägyptenland alles, was auf dem Felde war, vom Menschen bis zum Vieh, und alles Kraut des Feldes schlug der Hagel, und jeglichen Baum des Feldes zerbrach er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Nur im Lande Goschen, wo die Söhne Israels waren, war kein Hagel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'Und Pharao sandte und rief Mose und Aharon und sprach zu ihnen: Diesmal habe ich gesündigt, Jehovah ist der Gerechte, und ich und mein Volk sind ungerecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Flehet zu Jehovah, auf daß genug sei der Stimmen Gottes und des Hagels; so will ich euch entlassen, und ihr sollt nicht länger bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'Und Mose sprach zu ihm: Wenn ich hinaus vor die Stadt komme, will ich meine Hände ausbreiten zu Jehovah, da sollen die Stimmen aufhören und kein Hagel mehr sein, auf daß du wissest, daß die Erde Jehovahs ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Du aber und deine Knechte - das weiß ich - ihr fürchtet euch noch nicht vor dem Angesichte Jehovah Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'Und der Flachs und die Gerste wurden geschlagen; denn die Gerste hatte Ähren und der Flachs hatte Knoten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Und der Weizen und der Spelt wurden nicht geschlagen, weil sie verdeckt waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'Und Mose ging weg von Pharao, hinaus zur Stadt, und breitete seine Hände aus zu Jehovah, und die Stimmen hörten auf und der Hagel und der Regen ergossen sich nicht mehr zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Und Pharao sah, daß der Regen aufhörte und der Hagel und die Stimmen, und er fuhr fort zu sündigen und verstockte sein Herz, er und seine Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'Und Pharaos Herz ward bestärkt und er entließ die Söhne Israels nicht, wie Jehovah durch die Hand Moses geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'Und Jehovah sprach zu Mose: Gehe hinein zu Pharao; denn Ich habe sein Herz und das Herz seiner Knechte verstockt, auf daß Ich diese Meine Zeichen in seine Mitte setze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'Und auf daß du erzählest vor den Ohren deines Sohnes und des Sohnes deines Sohnes, was Ich in Ägypten ausgerichtet, und Meine Zeichen, die Ich unter sie gesetzt, und ihr wisset, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'Und Mose und Aharon gingen hinein zu Pharao und sprachen zu ihm: So spricht Jehovah, der Gott der Hebräer: Wie lange weigerst du dich, vor Mir dich zu demütigen. Entlaß Mein Volk, daß sie Mir dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Denn wenn du dich weigerst, Mein Volk zu entlassen, siehe, dann bringe Ich morgen Heuschrecken in deine Grenze,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'So daß sie das Angesicht der Erde bedekken, daß man die Erde nicht zu sehen vermag, und sollen fressen das Übergebliebene des Entkommenen, das auch vom Hagel geblieben, und fressen jeglichen Baum, der für euch aus dem Felde sproßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'Und sollen füllen deine Häuser und die Häuser aller deiner Knechte und die Häuser aller Ägypter, wie es nicht gesehen deine Väter, noch deiner Väter Väter, seit dem Tage, da sie auf dem Boden waren, bis auf diesen Tag. Und er wandte sich und ging hinaus von Pharao.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Und Pharaos Knechte sprachen zu ihm: Wie lange soll uns dies zum Fallstrick sein? Entlaß die Männer, daß sie Jehovah, ihrem Gotte dienen? Weißt du noch nicht, daß Ägypten vergeht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'Und man brachte Mose und Aharon zurück zu Pharao, und er sprach zu ihnen: Gehet, dienet Jehovah, eurem Gott. Wer und wer sind die, so da gehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'Und Mose sprach: Mit unseren Jungen und unseren Alten wollen wir ziehen, mit unseren Söhnen und mit unseren Töchtern, mit unserem Kleinvieh und mit unseren Rindern wollen wir ziehen; denn wir haben ein Fest Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'Und er sprach zu ihnen: So sei Jehovah mit euch, wie ich euch entlasse und eure Kindlein. Sehet, daß Böses ist vor euern Angesichtern!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Nicht also! So gehet doch, ihr junge Männer, und dienet dem Jehovah; denn das suchet ihr ja. Und man trieb sie fort von dem Angesichte Pharaos.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Und Jehovah sprach zu Mose: Strecke deine Hand aus über Ägyptenland wegen der Heuschrecken. Und herauf sollen sie kommen über das Land Ägypten und alles Kraut des Landes fressen, alles, was vom Hagel verblieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'Und Mose streckte seinen Stab über Ägyptenland aus. Und Jehovah führte einen Ostwind über das Land jenen ganzen Tag und die ganze Nacht. Es ward Morgen und der Ostwind trug die Heuschrecken daher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'Und die Heuschrecken kamen herauf über das ganze Land Ägypten, und ließen sich sehr schwer in aller Grenze Ägyptens nieder. Vordem hatte es nie also Heuschrecken gege- ben und nachher wird es auch nie mehr also geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Und sie bedeckten das Angesicht des ganzen Landes und das Land ward verfinstert. Und sie fraßen alles Kraut der Erde und alle Frucht des Baumes, die der Hagel übrig gelassen; und blieb nichts Grünes am Baum, noch am Kraut des Feldes in ganz Ägyptenland übrig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Und Pharao rief eilig Mose und Aharon und sprach: Ich habe gesündigt wider Jehovah, euern Gott, und wider euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Und nun vergib doch nur diesmal meine Sünde und flehet zu Jehovah, eurem Gott, daß Er von mir nur diesen Tod wegnehme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'Und er ging hinaus von Pharao und flehte zu Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'Und Jehovah ließ kehren einen sehr starken Wind vom Meere, und Er hob die Heuschrecke auf und warf sie ins Schilfmeer, in aller Grenze Ägyptens verblieb nicht eine Heuschrecke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Und Jehovah bestärkte das Herz Pharaos, und er entließ die Söhne Israels nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'Und Jehovah sprach zu Mose: Strecke deine Hand aus gen Himmel, daß Finsternis sei über Ägyptenland und man in der Finsternis herumtastet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'Und Mose streckte seine Hand aus gen Himmel und es ward Finsternis, dichte Finsternis in ganz Ägyptenland für drei Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Es sah der Mann den Bruder nicht; und drei Tage stand kein Mann von seiner Stelle auf; aber die Söhne Israels hatten Licht in ihren Wohnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'Und Pharao rief Mose und sprach: Gehet, dienet Jehovah. Nur euer Kleinvieh und eure Rinder lasset zurück; auch eure Kindlein mögen mit euch gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Und Mose sprach: Auch Schlachtopfer und Brandopfer sollst du in unsre Hand geben, daß wir sie darbringen Jehovah, unserem Gotte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Und auch unsere Viehherden sollen mit uns gehen; keine Klaue darf dahinten verbleiben; denn davon müssen wir nehmen, Jehovah, unserem Gott, zu dienen; und wir wissen nicht, womit wir Jehovah dienen sollen, bis wir dahin kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Und Jehovah bestärkte Pharaos Herz und er wollte sie nicht entlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'Und Pharao sprach zu ihm: Gehe von mir! Hüte dich, mein Angesicht wieder zu sehen; denn am Tage, da du mein Angesicht siehst, sollst du sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'Und Mose sprach: Richtig hast du geredet. Ich werde dein Angesicht hinfort nicht mehr sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Und Jehovah sprach zu Mose: Noch eine Plage werde Ich über Pharao und über Ägypten hereinbringen, danach wird er euch von dannen entlassen. Wenn er euch entläßt allzumal, dann wird er euch von dannen forttreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Rede doch vor des Volkes Ohren: Jeder Mann soll von seinem Genossen, und jedes Weib von ihrer Genossin Gefäße von Silber und Gefäße von Gold sich erbeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'Und Jehovah gab dem Volke Gnade in den Augen der Ägypter; auch war der Mann Mose sehr groß im Lande Ägypten in den Augen der Knechte Pharaos und in den Augen des Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'Und Mose sprach: So spricht Jehovah: Um die Mitte der Nacht gehe Ich aus in die Mitte Ägyptens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'Und sterben soll alle Erstgeburt im Lande Ägypten von dem Erstgeborenen Pharaos, der auf seinem Throne sitzt, bis auf den Erstgeborenen der Dienstmagd, die hinter der Mühle ist, und alle Erstgeburt des Viehs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'Und ein groß Geschrei wird sein im ganzen Lande Ägypten, desgleichen nie gewesen ist und desgleichen nie mehr sein wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'Und bei allen Söhnen Israels soll kein Hund die Zunge regen, vom Manne bis zum Vieh, auf daß ihr wisset, daß Jehovah unterscheidet zwischen Ägyptern und zwischen Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'Und all diese deine Knechte kommen herab zu mir und verbeugen sich vor mir und sprechen: Geh aus, du und all das Volk, das deinem Fuße folgt; und danach gehe ich aus. Und er ging in dem Entbrennen des Zornes hinaus von Pharao.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'Und Jehovah sprach zu Mose: Pharao wird auf euch nicht hören, auf daß Meiner Wahrzeichen viel werde im Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'Und Mose und Aharon taten alle diese Wahrzeichen vor Pharao; und Jehovah bestärkte Pharaos Herz, so daß er die Söhne Israel nicht aus seinem Land entließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'Und Jehovah sprach zu Mose und zu Aharon im Lande Ägypten und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Dieser Monat sei euch das Haupt der Monate. Der erste sei er euch unter den Monaten des Jahres.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Redet zu der ganzen Gemeinde Israels und saget: Am zehnten dieses Monats da nehme von euch jeder Mann sich ein Lamm für das Haus der Väter, ein Lammauf das Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Und wenn das Haus zu klein ist für ein Lamm, so nehme er es und sein Nachbar, der seinem Hause nahe ist, nach der Zahl der Seelen, je wie Einer von dem Lamm essen mag zählet ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Ein Lamm ohne Fehl, männlich von einem Jahre soll es sein für euch. Von den Lämmern und von den Ziegen sollt ihr es nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'Und bis zum vierzehnten Tage dieses Monats bewahrt es auf, behaltet es und die ganze Versammlung der Gemeinde Israels schlachte es gegen Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'Und von dem Blute sollen sie nehmen und an die zwei Türpfosten und an die Oberschwelle tun, an den Häusern, in denen sie essen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'Und sollen das Fleisch in dieser Nacht essen, am Feuer gebraten, und mit Ungesäuertem und mit bitteren Kräutern sollen sie es essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Nicht roh oder gekocht, im Wasser gekocht, sollt ihr davon essen, sondern am Feuer gebraten, seinen Kopf auf seinen Schenkeln und seinen Eingeweiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'Und sollt nichts davon übrig lassen bis zum Morgen, was aber davon übrig bleibt bis zum Morgen, sollt ihr im Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Und so sollt ihr es essen: Eure Lenden gegürtet, eure Schuhe an euren Füßen und eure Stöcke in eurer Hand, und sollt es mit Hast essen; es soll ein Passah dem Jehovah sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Und in dieser Nacht durchzieh Ich das Land Ägypten und schlage alle Erstgeburt im Lande Ägypten vom Menschen und bis zum Vieh, und über alle Götter Ägyptens halte Ich Gericht, Ich Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'Und das Blut sei euch zum Zeichen an den Häusern, worin ihr seid, und sehe Ich das Blut, gehe Ich an euch vorüber und keine Plage vom Verderben soll an euch sein, wenn Ich das Land Ägypten schlage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'Und dieser Tag sei zum Gedächtnis für euch; und als ein Fest Jehovahs sollet ihr ihn feiern in euren Geschlechtern, als ewige Satzung sollet ihr ihn feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sieben Tage sollt ihr Ungesäuertes essen; schon am ersten Tage sollt ihr den Sauerteig aus euren Häusern wegschaffen; denn jeder, der Gesäuertes ißt, dessen Seele soll aus Israel ausgerottet werden; vom ersten bis zum siebenten Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'Und am ersten Tage soll heilige Zusammenberufung und am siebenten Tage heilige Zusammenberufung bei euch sein. Keinerlei Arbeit werde an denselben getan. Nur was jede Seele ißt, darf bei euch zugerichtet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Und haltet das Ungesäuerte; denn an diesem selben Tage habe Ich eure Heerscharen aus dem Land Ägypten ausgeführt, und haltet diesen Tag in euren Geschlechtern als ewige Satzung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'In dem ersten, am vierzehnten Tage des Monats am Abend sollt ihr Ungesäuertes essen bis zum einundzwanzigsten Tage des Monats am Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sieben Tage soll kein Sauerteig in euren Häusern gefunden werden; denn jeder, der Gesäuertes ißt, dessen Seele soll aus der Gemeinde Israels ausgerottet werden, bei dem Fremdling, und bei dem Eingeborenen des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nichts Gesäuertes sollt ihr essen, in allen euren Wohnungen sollt ihr Ungesäuertes essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'Und Mose berief alle Ältesten Israels und sprach zu ihnen: Ziehet hervor und nehmet euch Kleinvieh nach euren Familien und schlachtet das Passah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'Und nehmet ein Bündel Ysop und tauchet es in das Blut, das im Becken ist und berührt die Oberschwelle und die beiden Türpfosten mit dem Blut, das in dem Becken ist; und kein Mann von euch gehe aus dem Eingang seines Hauses bis zum Morgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Und Jehovah wird durchziehen, die Ägypter zu schlagen, und wenn Er das Blut an der Oberschwelle und an den zwei Türpfosten sieht, so geht Jehovah vorbei an dem Eingang und gibt nicht zu, daß der Verderber in eure Häuser komme, um zu schlagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Und ihr sollt halten dieses Wort als Satzung für dich und für deine Söhne ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'Und soll geschehen, wenn ihr in das Land kommet, das Jehovah euch geben wird, wie Er geredet hat, da sollt ihr diesen Dienst halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'Und es soll geschehen, wenn eure Söhne zu euch sagen: Was ist euch dieser Dienst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'Und ihr sollt sagen: Es ist das Passahopfer für Jehovah, Der an den Häusern der Söhne Israels in Ägypten vorbeiging, da Er Ägypten schlug, und unsere Häuser errettete. Und das Volk verneigte sich und sie beteten an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'Und die Söhne Israels gingen hin und taten, wie Jehovah Mose und Aharon geboten, so taten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'Und es geschah um Mitternacht, daß Jehovah schlug alle Erstgeburt im Lande Ägypten, vom Erstgeborenen Pharaos, der auf seinem Throne sitzen sollte, bis zum Erstgeborenen des Gefangenen, der im Hause der Grube war, und alle Erstgeburt des Viehs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'Und Pharao stand auf in der Nacht, er und alle seine Knechte, und alle Ägypter, und es war ein großes Geschrei in Ägypten; denn es war kein Haus, wo nicht ein Toter war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'Und er rief Mose und Aharon in der Nacht und sprach: Machet euch auf, gehet hinaus aus meines Volkes Mitte, sowohl ihr, als auch die Söhne Israels und gehet und dienet Jehovah, wie ihr geredet habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Auch euer Kleinvieh und eure Rinder nehmet mit, wie ihr geredet habt, und geht und segnet auch mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'Und Ägypten drang auf das Volk, sie eilig aus dem Lande zu senden; denn, sagten sie, wir alle sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'Und das Volk trug seinen Teig, ehe er gesäuert war, ihre Backtröge, in ihre Gewänder zugebunden, auf ihren Schultern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'Und die Söhne Israels hatten getan, nach dem Worte Moses, und die Ägypter um Gefä-ße von Silber und Gefäße von Gold und Gewänder gefragt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Und Jehovah hatte dem Volke Gnade in den Augen der Ägypter gegeben und sie gewährten sie ihnen. Und sie entrissen es den Ägyptern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'Und die Söhne Israels brachen von Ramses auf gen Sukkoth, bei sechshunderttausend zu Fuß, die Männer ohne die Kindlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Und auch viel Troß zog mit ihnen hinauf und Kleinvieh und Rinder, eine sehr große Viehherde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'Und sie buken den Teig, den sie aus Ägypten herausgebracht, zu ungesäuerten Kuchen; denn es war nicht gesäuert, weil sie aus Ägypten fortgetrieben wurden und nicht vermochten zu zaudern und auch keine Zehrung für sich zugerichtet hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'Und das Wohnen der Söhne Israel, da sie in Ägypten gewohnt hatten, war dreißig Jahre und vierhundert Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'Und es geschah am Ende der vierhundertdreißig Jahre, daß auf eben diesen selben Tag alle Heerscharen Jehovahs von Ägyptenland ausgingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'Eine Nacht der Wachen war es dem Jehovah, da Er sie herausbrachte aus dem Lande Ägypten; diese Nacht sei dem Jehovah zur Wache für alle Söhne Israels nach ihren Geschlechtern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'Und Jehovah sprach zu Mose und Aharon: Dies ist die Satzung für das Passah: Kein Sohn eines Ausländischen soll davon essen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Aber jeden Knecht, den Mann, den du für Geld gekauft, sollst du beschneiden. Dann esse er davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Ein Beisaß und Mietling soll nicht davon essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'In einem Hause soll es gegessen werden. Du sollst nichts von dem Fleisch aus dem Hause hinausbringen. Und ihr sollt kein Bein an ihm brechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Die ganze Gemeinde Israels soll es tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Und wenn sich ein Fremdling bei dir aufhält und dem Jehovah das Passah halten will, dem soll alles Männliche beschnitten werden; dann nahe er sich, es zu halten, und soll sein wie der Eingeborene des Landes; aber ein Unbeschnittener soll nicht davon essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Ein Gesetz soll sein für den Eingeborenen und den Fremdling, der in eurer Mitte sich aufhält.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'Und alle Söhne Israels taten, wie Jehovah dem Mose und Aharon geboten hatte, also taten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'Und an eben demselben Tage geschah es, daß Jehovah die Söhne Israels nach ihren Heerscharen aus Ägyptenland herausbrachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Heilige Mir alle Erstgeburt; alles, was die Mutter bricht bei den Söhnen Israels, bei Mensch und bei Vieh, Mein ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'Und Mose sprach zu dem Volk: Gedenket dieses Tages, da ihr aus Ägypten, aus dem Hause der Knechte ausgegangen seid; denn mit starker Hand hat euch Jehovah von da herausgebracht; und nichts Gesäuertes soll gegessen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Heute gehet ihr aus im Monat Abib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'Und soll geschehen, wenn dich Jehovah in das Land der Kanaaniter und der Chethiter und der Amoriter und der Chiviter und der Jebusiter, das Er deinen Vätern geschworen, dir zu geben, hineinbringen wird, in ein Land, da Milch und Honig fließt, so sollst du diesen Dienst in diesem Monat dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sieben Tage sollst du Ungesäuertes essen, und am siebenten Tage ist ein Fest dem Jeho- vah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Ungesäuertes esse man die sieben Tage. Und nichts Gesäuertes soll man bei dir sehen, und kein Sauerteig soll in deiner ganzen Grenze bei dir zu sehen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'Und sage an deinem Sohn an diesem Tage und sprich: Darum ist es, daß Jehovah dies mir getan, da ich aus Ägypten ausging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'Und es sei dir zum Zeichen auf deiner Hand und zum Andenken zwischen deinen Augen, auf daß Jehovahs Gesetz in deinem Munde sei; denn mit starker Hand hat Jehovah dich aus Ägypten herausgebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Und du sollst halten diese Satzung zur bestimmten Zeit von Jahr zu Jahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'Und soll geschehen, wenn dich Jehovah ins Land der Kanaaniter hereingebracht, wie Er dir und deinen Vätern geschworen und dir es gegeben hat:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'Und alles, was die Mutter bricht, soll an Jehovah übergehen und alle Erstgeburt vom Wurf des Viehs, sei Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'Und alle Erstgeburt vom Esel sollst du mit einem Lamme einlösen, und lösest du es nicht ein, so brich ihr das Genick; aber alle Erstgeburt vom Menschen unter deinen Söhnen sollst du einlösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'Und es wird geschehen, daß dich dein Sohn morgen fragt und sagt: Was soll das? und du sagst ihm: Mit starker Hand hat uns Jehovah aus Ägypten, der Knechte Haus, herausgebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'Und es geschah, da Pharao sich verhärtete, uns zu entlassen, da erwürgte Jehovah alle Erstgeburt im Land Ägypten, von der Erstgeburt des Menschen bis zur Erstgeburt des Viehs; darum opfere ich Jehovah alles Männliche, das die Mutter bricht, und löse alle Erstgeburt meiner Söhne ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'Und es sei zum Zeichen auf deiner Hand und zum Stirnband zwischen deinen Augen, daß mit starker Hand Jehovah uns aus Ägypten herausgebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'Und es geschah, als Pharao das Volk entließ, daß Gott sie nicht auf dem Weg zu der Philister Land, weil er nahe war, führte; denn Gott sprach: Das Volk möchte sich es gereuen lassen, wenn es Streit sieht, und wieder nach Ägypten zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Und Gott ließ das Volk herumziehen, auf dem Weg der Wüste nach dem Schilfmeer, und kampfgerüstet zogen die Söhne Israels herauf aus dem Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'Und Mose hatte die Gebeine Josephs mit sich genommen; denn der hatte die Söhne Israels einen Eid schwören lassen, und gesprochen: Gewißlich wird euch Gott heimsuchen, und ihr sollt meine Gebeine von da mit euch hinaufbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'Und sie brachen von Sukkoth auf und lagerten in Etham, am Ende der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'Und Jehovah ging vor ihnen her, bei Tag in einer Wolkensäule, um sie den Weg zu führen, und bei Nacht in einer Feuersäule, um ihnen zu leuchten, auf daß sie bei Tag und bei Nacht gehen könnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Nicht wich die Wolkensäule bei Tag, noch die Feuersäule bei Nacht, vor dem Volke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Rede zu den Söhnen Israels, daß sie sollen zurückkehren und sich vor Pi-Hachiroth zwischen Migdol und zwischen dem Meere lagern; vor Baal-Zephon, dem gegenüber am Meere sollt ihr euch lagern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Und Pharao wird über die Söhne Israels sagen: Sie sind verirrt im Lande, die Wüste hat sie eingeschlossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Und Ich bestärke Pharaos Herz, daß er ihnen nachsetze, und Ich will Mich verherr- lichen an Pharao und all seiner Streitmacht, auf daß die Ägypter wissen, daß Ich Jehovah bin. Und sie taten also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'Und es ward dem Könige von Ägypten angesagt, daß das Volk geflohen sei; und das Herz Pharaos und seiner Knechte kehrte sich wider das Volk und sie sprachen: Was haben wir getan, daß wir Israel entließen und sie uns nicht mehr dienen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Und er spannte seinen Streitwagen an und nahm sein Volk mit sich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'Und nahm sechshundert auserwählte Streitwagen und alle Streitwagen Ägyptens und Wagenkämpfer auf jeden davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'Und Jehovah hatte das Herz Pharaos, des Königs von Ägypten bestärkt, daß er den Söhnen Israels nachsetzte. Und die Söhne Israels waren mit erhöhter Hand ausgegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Und die Ägypter setzten ihnen nach und erreichten sie, da sie am Meere lagerten; alle Rosse der Streitwagen Pharaos und seine Reiter und seine Streitmacht bei Pi-Hachiroth vor Baal-Zephon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Und Pharao nahte sich; und die Söhne Israels hoben ihre Augen auf und siehe, der Ägypter zog aus hinter ihnen her; und sie fürchteten sich sehr, und die Söhne Israels schrien zu Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'Und zu Mose sprachen sie: Waren keine Gräber in Ägypten, daß du uns nehmen muß-test, um in der Wüste zu sterben? Warum hast du uns das getan, daß du uns aus Ägyptenland herausbrachtest?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Ist nicht dies das Wort, das wir in Ägypten zu dir redeten und sagten: Höre auf von uns, daß wir den Ägyptern dienen; denn es ist besser für uns, den Ägyptern zu dienen, als in der Wüste zu sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'Und Mose sprach zu dem Volk: Fürchtet euch nicht, stellet euch auf und sehet das Heil Jehovahs, das Er heute an euch tut; denn die Ägypter, die ihr heute saht, die sehet ihr fortan nimmer in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Jehovah streitet für euch; und ihr sollt nur stille schweigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'Und Jehovah sprach zu Mose: Was schreist du zu Mir? Rede zu den Söhnen Israels, daß sie aufbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Und du erhebe deinen Stab und strecke deine Hand aus über das Meer, und spalte es entzwei, auf daß die Söhne Israels mitten im Meer im Trockenen gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'Und Ich, siehe Ich bestärke der Ägypter Herz, daß sie hinter ihnen herziehen, und Ich will an Pharao, an all seiner Streitmacht, an seinen Streitwagen und seinen Reitern Mich verherrlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'Und die Ägypter sollen wissen, daß Ich Jehovah bin, wenn Ich an Pharao, an seinen Streitwagen und an seinen Reitern Mich verherrliche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'Und es brach auf der Engel Gottes, der vor dem Lager Israels einherzog, und ging hinter sie, und die Wolkensäule vor ihnen brach auf und stand hinter ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'Und kam zwischen Ägyptens Lager und zwischen das Lager Israels; und es war da die Wolke und Finsternis und sie erleuchtete die Nacht; und das eine nahte dem andern nicht die ganze Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Und Mose streckte seine Hand aus über das Meer, und durch einen starken Ostwind ließ Jehovah das Meer hingehen die ganze Nacht hindurch und legte das Meer trocken, und die Wasser spalteten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'Und die Söhne Israels gingen im Trockenen mitten durch das Meer, und das Wasser ward ihnen eine Mauer zu ihrer Rechten und zu ihrer Linken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'Und die Ägypter setzten ihnen nach; und alle Rosse Pharaos, seine Streitwagen und seine Reiter kamen ihnen nach mitten in das Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'Und es geschah, um die Morgenwache, daß Jehovah in der Feuer- und Wolkensäule auf das Lager der Ägypter schaute und das Lager der Ägypter verwirrte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'Und die Räder von den Streitwagen wegnahm und sie mit Beschwerde fahren ließ. Und die Ägypter sagten: Lasset uns fliehen vor Israel; denn Jehovah streitet für sie wider die Ägypter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'Und Jehovah sprach zu Moses: Strecke deine Hand aus über das Meer, auf daß die Wasser über den Ägypter, über seinen Streitwagen und über seine Reiter zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Und Mose streckte seine Hand aus über das Meer; und das Meer kehrte bei der Wendung des Morgens zur Stärke seiner Strömung zurück; und die Ägypter flohen ihm entgegen, und Jehovah schüttelte die Ägypter ab mitten in das Meer. Neunzig Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'Und die Wasser kehrten zurück und bedeckten die Streitwagen und die Reiter, samt der ganzen Streitmacht Pharaos, die hinter ihnen her in das Meer kam, so daß nicht einer von ihnen verblieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Und die Söhne Israel gingen im Trockenen mitten im Meer, und die Wasser waren ihnen zur Mauer zu ihrer Rechten und zu ihrer Linken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Und Jehovah rettete an diesem Tage Israel aus der Hand der Ägypter; und Israel sah die Ägypter tot am Ufer des Meeres.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'Und Israel sah die große Hand, die Jehovah wider die Ägypter erzeigt hatte, und das Volk fürchtete Jehovah, und sie glaubten an Jehovah und an Mose, seinen Knecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Da sang Mose und die Söhne Israels dieses Lied dem Jehovah und sprachen und sagten: Ich will singen dem Jehovah; denn hoch erhaben ist Er! Roß und Reiter stürzte Er ins Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Meine Stärke und mein Gesang ist Jah. Und Er ward mir zum Heil. Er ist mein Gott, und einen Wohnort will ich Ihm bereiten. Er ist der Gott meines Vater, und Ihn will ich erhöhen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Jehovah ist ein Mann des Streites. Jehovah ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Die Streitwagen Pharaos und seine Streitmacht warf Er ins Meer, und die Auswahl seiner Wagenkämpfer ist ins Schilfmeer versunken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Abgründe bedeckten sie, sie gingen hinab in die Schlünde wie ein Stein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Deine Rechte, Jehovah, ist verklärt in Kraft, Deine Rechte, Jehovah, zerschmettert den Feind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'Und in der Fülle Deiner Hoheit reißest Du nieder, die wider Dich aufstehen; Du sendest aus Dein Entbrennen; es frißt sie auf wie Stoppel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'Und bei dem Hauchen Deiner Nase türmten sich die Wasser auf; gleich einem Haufen stellten sich auf die Strömungen. Die Abgründe starrten im Herzen des Meeres.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Es spricht der Feind: Ich setze nach; ich erreiche sie; ich teile die Beute, meine Seele soll sich an ihnen füllen. Ich entblöße mein Schwert, meine Hand treibt sie aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'Du bliesest mit Deinem Winde, das Meer bedeckte sie. Wie Blei versanken sie in die gewaltigen Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Wer ist wie Du unter den Göttern, Jehovah? Wer ist wie Du, prachtvoll in Heiligkeit, furchtbar im Lobe, Wunder tuend!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Du strecktest aus Deine Rechte, da verschlang sie die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Du führtest in Deiner Barmherzigkeit das Volk, das Du erlöstest, durch Deine Stärke hast Du es geleitet zum Wohnort Deiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Die Völker hörten es und zitterten; Wehen ergriffen die Einwohner Philistäas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Da wurden bestürzt Edoms Stammhäupter; Moabs Gewaltige ergriff ein Zittern, es zerflossen alle Einwohner Kanaans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Schrecken und Schauer fiel auf sie, ob der Größe Deines Armes wurden sie stille wie der Stein, bis Dein Volk, Jehovah, vorüberzieht, bis vorüberzieht das Volk, das Du erworben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Du bringst sie hinein und pflanzest sie auf den Berg Deines Erbes, zur Stätte, die Du, Jehovah, zu Deiner Wohnung machtest, zum Heiligtum, o Herr, das Deine Hände Dir zugerichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Jehovah sei König ewig und immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Denn Pharaos Roß mit seinem Streitwagen und mit seinen Reitern kam hinein ins Meer; und Jehovah ließ des Meeres Wasser über sie zurückkommen; und die Söhne Israels gingen im Trockenen mitten im Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'Und Mirjam, die Prophetin, Aharons Schwester, nahm die Pauke in ihre Hand, und alle Weiber gingen aus mit Pauken und im Reigentanz ihr nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'Und Mirjam antwortete ihnen: Singt dem Jehovah; denn hoch erhaben ist Er. Roß und Reiter stürzt Er ins Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'Und Mose ließ Israel vom Schilfmeer aufbrechen, und sie gingen aus nach der Wüste Schur, und gingen drei Tage in der Wüste und fanden kein Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'Und sie kamen nach Marah und vermochten nicht das Wasser zu trinken vor Bitterkeit; denn es war bitter; deshalb nannte man seinen Namen Marah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'Und das Volk murrte über Mose und sagte: Was sollen wir trinken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'Und er rief zu Jehovah und Jehovah zeigte ihm Holz; und er warf es in das Wasser, und das Wasser ward süß. Daselbst setzte Er ihnen Satzung und Recht, und versuchte sie allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'Und Er sprach: Wenn du auf die Stimme Jehovahs, deines Gottes, hörst und tust, was recht in Seinen Augen ist, und Seine Gebote zu Ohren nimmst und alle Seine Satzungen hältst, so werde Ich keine der Krankheiten, die Ich auf die Ägypter gelegt, auf dich legen; denn Ich, Jehovah, bin dein Heiler.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'Und sie kamen nach Elim und daselbst waren zwölf Wasserquellen und siebzig Palmen; und sie lagerten da an den Wassern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'Und von Elim brachen sie auf, und die ganze Gemeinde der Söhne Israels kam nach der Wüste Sin, die zwischen Elim und Sinai ist, am fünfzehnten Tage des zweiten Monats seit ihrem Auszug aus dem Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'Und es murrte die ganze Gemeinde der Söhne Israel wider Mose und Aharon in der Wüste;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'Und die Söhne Israels sagten zu ihnen: Wären wir doch durch die Hand Jehovahs im Lande Ägypten gestorben, wo wir beim Fleischtopfe saßen, wo wir Brot aßen bis wir satt waren; denn ihr habt uns in diese Wüste herausgeführt, um diese ganze Versammlung Hungers sterben zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Und Jehovah sprach zu Mose: Siehe, Ich lasse euch Brot vom Himmel regnen und das Volk gehe aus und lese auf den täglichen Bedarf an seinem Tage, auf daß Ich dasselbe versuche, ob es in Meinem Gesetz wandle oder nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'Und am sechsten Tage soll geschehen, wenn sie bereiten, was sie eingebracht haben, daß es das Doppelte ist von dem, was sie Tag für Tag auflesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'Und Mose und Aharon sprachen zu allen Söhnen Israels: Wenn es Abend wird, sollt ihr wissen, daß es Jehovah ist, Der euch aus Ägyptenland ausgeführt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'Und am Morgen sollt ihr sehen Jehovahs Herrlichkeit, daran, daß Er euer Murren gegen Jehovah gehört hat; denn wir, was sind wir, daß ihr wider uns murret?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'Und Mose sprach: Daran, daß Jehovah euch am Abend Fleisch zu essen gibt und Brot am Morgen zur Sättigung; daran, daß Er, Jehovah, auf euer Murren gehört, mit dem ihr wider Ihn murrtet; denn was sind wir? Nicht wider uns war euer Murren, sondern wider Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'Und Mose sprach zu Aharon: Sprich zu der ganzen Gemeinde der Söhne Israels: Nahet euch herzu vor Jehovah; denn Er hat euer Murren gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'Und es geschah als Aharon zur Gemeinde der Söhne Israels redete, daß sie sich gegen die Wüste wandten, und siehe, die Herrlichkeit Jehovahs erschien in einer Wolke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Ich habe das Murren der Söhne Israels gehört. Rede zu ihnen und sprich: Gegen Abend sollt ihr Fleisch essen und am Morgen euch sättigen mit Brot, und sollt wissen, daß Ich, Jehovah, euer Gott bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'Und es geschah am Abend, daß die Wachtel heraufkam und das Lager bedeckte, und am Morgen war eine Lagerung von Tau rings um das Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Und als die Taulagerung aufstieg, siehe, da war auf der Oberfläche der Wüste etwas Feines, Rundes, so fein wie der Reif auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'Und die Söhne Israels sahen es und sie sagten der Mann zu seinem Bruder: Was ist das? denn sie wußten nicht, was es war. Und Mose sprach zu ihnen: Es ist das Brot, das Jehovah euch zu essen gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'Das ist das Wort, das Jehovah geboten hat: Leset davon auf, der Mann nach seinem Mundbedarf; ein Gomer auf den Kopf, nach der Zahl eurer Seelen, der Mann für die, so in seinem Zelte sind, sollt ihr nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'Und die Söhne Israels taten so, und lasen auf viel und wenig;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'Und maßen mit dem Gomer, und so hatte denn, der viel sammelte, keinen Überfluß, und der wenig sammelte, mangelte nicht. Jeder Mann hatte nach seinem Mundbedarf gesammelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'Und Mose sprach zu ihnen: Kein Mann lasse davon übrig bis zum Morgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Sie hörten aber nicht auf Mose und einige Männer ließen übrig davon auf den Morgen. Und es wuchsen Würmer darin und es stank. Und Mose war entrüstet über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'Und sie lasen es auf von Morgen zu Morgen, der Mann nach seinem Mundbedarf; und wenn die Sonne heiß wurde, da zerschmolz es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'Und am sechsten Tage geschah es, daß sie das Doppelte des Brotes, je zwei Gomer für einen auflasen. Und alle Fürsten der Gemeinde sagten es Mose an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'Und er sprach zu ihnen: Das ist es, was Jehovah geredet hat: Morgen ist Sabbath, der heilige Sabbath Jehovahs! Was ihr backen wollet, das backet, und was ihr kochen wollet, das kochet, und alles, was überflüssig ist, das legt für euch nieder, um es für morgen aufzubewahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Und sie legten es nieder bis zum Morgen, wie Mose geboten hatte, und es stank nicht; auch war keine Made darin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'Und Mose sprach: Esset es heute, denn es ist heute Sabbath dem Jehovah; heute werdet ihr es nicht finden auf dem Felde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Sechs Tage sollt ihr es auflesen, aber am siebenten Tage, am Sabbath, wird es nicht dort sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Und am siebenten Tage geschah es, daß einige vom Volk ausgingen es aufzulesen, und sie fanden nichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'Und Jehovah sprach zu Mose: Wie lange wollet ihr euch weigern, Meine Gebote und Meine Gesetze zu halten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Sehet, Jehovah hat euch den Sabbath gegeben; deshalb gibt Er euch am sechsten Tag Brot für zwei Tage. Bleibet, jeder Mann für sich; kein Mann gehe aus von seinem Ort am siebenten Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Und es feierte das Volk am siebenten Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'Und das Haus Israel nannte dessen Namen Man. Und es war wie weißer Koriandersamen und sein Geschmack war wie Kuchen mit Honig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'Und Mose sprach: Dies ist das Wort, das Jehovah geboten hat: Füllet ein Gomer davon, daß es werde aufbewahrt für eure Geschlechter, auf daß sie das Brot sehen, das Ich euch ließ essen in der Wüste, als Ich euch aus Ägyptenland herausbrachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Und Mose sprach zu Aharon: Nimm eine Urne und tue ein Gomer voll Man hinein und stelle es nieder vor Jehovah zur Aufbewahrung für eure Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Wie Jehovah dem Mose geboten hatte, so stellte es Aharon nieder vor das Zeugnis zur Aufbewahrung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'Und die Söhne Israels aßen das Man vierzig Jahre, bis sie in bewohntes Land kamen. Das Man aßen sie, bis sie an die Grenze des Landes Kanaan kamen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Und das Gomer ist ein Zehntel des Ephah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'Und die ganze Gemeinde der Söhne Israels brach auf von der Wüste Sin auf ihre Wanderzüge nach dem Munde Jehovahs und sie lagerten in Rephidim, und das Volk hatte kein Wasser zu trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'Und das Volk haderte mit Mose und sie sprachen: Gib uns Wasser, daß wir trinken! Und Mose sprach zu ihnen: Was hadert ihr mit mir? Was versuchet ihr Jehovah?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'Und das Volk dürstete daselbst nach Wasser; und das Volk murrte wider Mose und sprach: Warum hast du uns aus Ägypten heraufgebracht, daß du mich und meine Söhne und meine Viehherden vor Durst sterben lässest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'Und Mose schrie zu Jehovah und sprach: Was soll ich mit diesem Volke tun: Noch ein wenig und sie steinigen mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'Und Jehovah sprach zu Mose: Zieh hin vor dem Volke und nimm mit dir von den Ältesten Israels; und deinen Stab, mit dem du den Strom geschlagen, nimm in deine Hand und geh hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Siehe, Ich stehe dort vor dir auf dem Felsen in Horeb. Und du sollst den Felsen schlagen und Wasser kommt aus ihm heraus, auf daß das Volk trinke; und Mose tat also vor den Augen der Ältesten Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'Und er nannte den Namen des Ortes Massah und Meribah, darum, daß die Söhne Israels haderten und Jehovah verfluchten, indem sie sagten: Ist Jehovah in unserer Mitte oder nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'Und es kam Amalek und stritt mit Israel in Rephidim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'Und Mose sprach zu Jehoschua: Wähl uns Männer aus und gehe aus und streite wider Amalek. Ich werde mich morgen auf des Hügels Gipfel stellen und der Stab Gottes in meiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'Und Jehoschua tat, wie ihm Mose gesagt hatte, daß er wider Amalek streiten sollte. Und Mose, Aharon und Chur stiegen auf den Gipfel des Hügels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'Und es geschah, so wie Mose seine Hand emporhob, da hatte Israel die Übermacht und wie er seine Hand niedersinken ließ, hatte Amalek die Übermacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'Und Moses Hände wurden schwer; und sie nahmen einen Stein und legten denselben unter ihn und er setzte sich darauf, und Aharon und Chur stützten seine Hände, der eine hier, der andere dort, und so geschah es, daß seine Hände festblieben, bis die Sonne unterging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'Und Jehoschua schwächte den Amalek und sein Volk mit der Schärfe des Schwertes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Und Jehovah sprach zu Mose: Schreib dies zum Andenken in das Buch und bring es vor die Ohren Jehoschuas, daß Ich das Andenken an Amalek gänzlich auswischen will unter dem Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'Und Mose baute einen Altar und nannte seinen Namen Jehovah Nissi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'Und sprach: Weil die Hand ist wider den Thron Jahs, hat Jehovah Krieg wider Amalek von Geschlecht zu Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'Und Jethro, der Priester von Midjan, Moses Schwäher, hörte alles, was Gott an Mose und seinem Volke Israel getan, daß Jehovah Israel von Ägypten herausgebracht hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'Und Jethro, Moses Schwäher, nahm Zipporah, Moses Weib, nach ihrer Entlassung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'Und ihre zwei Söhne, von denen der Name des einen Gerschon war; denn er sprach: Ich war ein Fremdling in auswärtigem Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'Und der Name des anderen war Eleser; denn der Gott meines Vaters war mein Beistand und errette mich von dem Schwerte Pharaos.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'Und es kam Jethro, Moses Schwäher, und seine Söhne und sein Weib zu Mose in die Wüste, wo er lagerte am Berge Gottes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'Und er sprach zu Mose: Ich, dein Schwäher Jethro, komme zu dir und dein Weib und ihre zwei Söhne mit ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'Und Mose ging hinaus seinem Schwäher entgegen und verbeugte sich vor ihm und küßte ihn; und sie fragten einander um den Frieden und kamen in das Zelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'Und Mose erzählte seinem Schwäher alles, was Jehovah an Pharao und an den Ägyptern um Israels willen getan, all das Mühsal, das sie auf dem Wege getroffen und wie Jehovah sie errettet hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'Und Jethro freute sich über alles Gute, das Jehovah an Israel getan, daß Er es aus der Hand der Ägypter errettet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'Und Jethro sprach: Gesegnet sei Jehovah, Der euch errettet aus der Hand der Ägypter und aus der Hand Pharaos, Der das Volk aus der Hand der Ägypter errettet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Nun weiß ich, daß Jehovah größer ist denn alle Götter; denn es war in der Sache, in der sie sich vermaßen über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'Und Jethro, Moses Schwäher, nahm für Gott Brandopfer und Schlachtopfer, und Aharon kam und alle Ältesten Israels, das Brot zu essen mit Moses Schwäher vor Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'Und am morgenden Tage geschah, daß Mose saß das Volk zu richten; und das Volk stand bei Mose vom Morgen bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'Und Moses Schwäher sah alles, was er dem Volke tat, und sagte: Was ist dies, das du dem Volke tust? Warum sitzest du allein und alles Volk stellt sich bei dir vom Morgen bis zum Abend?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'Und Mose sprach zu seinem Schwäher: Das Volk kommt zu mir, Gott zu befragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'So sie eine Sache haben, kommen sie zu mir, und ich richte zwischen dem Mann und seinem Genossen und lasse sie die Satzungen Gottes und seine Gesetze wissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'Und Moses Schwäher sagte zu ihm: Das Wort ist nicht gut, das du tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Du ermattest und auch dieses Volk, das bei dir ist. Denn die Sache ist zu schwer für dich, du vermagst es allein nicht zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'So höre denn auf meine Stimme. Ich will dir raten und Gott sei mit dir! Sei du für das Volk vor Gott und bringe du die Sachen vor Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'Und warne sie ob der Satzungen und Gesetze, und laß sie den Weg wissen, den sie gehen und das Werk, das sie tun sollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Und du erschaue dir aus allem Volk tüchtige Männer, gottesfürchtige, Männer der Wahrheit, die Gewinn hassen, und setze sie über dasselbe als Oberste über tausend, als Oberste über hundert, als Oberste über fünfzig und als Oberste über zehn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Und sie sollen das Volk richten zu jeder Zeit. Und soll sein, jede große Sache sollen sie zu dir bringen und jede kleine Sache selber richten; so wirst du es leichter haben und sie tragen mit dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Tust du dies Ding und gebietet dir es Gott, so vermagst du zu bestehen, und auch dies Volk mag in Frieden an seinen Ort kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'Und Mose hörte auf die Stimme seines Schwähers und tat alles, was er gesagt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'Und Mose wählte tüchtige Männer aus ganz Israel und setzte sie zur Häuptern über das Volk, zu Obersten über tausend, zu Obersten über hundert, zu Obersten über fünfzig und zu Obersten über zehn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'Und sie richteten das Volk zu jeder Zeit, brachten die härtere Sache zu Mose, und alle kleinere Sache richteten sie selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'Und Mose entließ seinen Schwäher und er ging für sich in sein Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Im dritten Monat des Auszugs der Söhne Israels aus dem Lande Ägypten an demselben Tage kamen sie in die Wüste Sinai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Und von Rephidim brachen sie auf und kamen in die Wüste Sinai, und lagerten in der Wüste, und Israel lagerte sich dem Berge gegenüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'Und Mose stieg hinauf zu Gott, und Jehovah rief ihm vom Berge und sprach: So sollst du sprechen zum Hause Jakob, und ansagen den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Ihr habt gesehen, was Ich den Ägyptern getan, und wie Ich euch auf Adlersflügeln getragen und zu Mir gebracht habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'Und nun, wenn ihr gewißlich auf Meine Stimme höret und Meinen Bund haltet, so sollt ihr Mir zum Eigentum sein vor allen Völkern; denn Mein ist die ganze Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'Und ihr sollt Mir ein Königreich von Priestern sein und eine heilige Völkerschaft. Dies sind die Worte, die du zu den Söhnen Israels reden sollst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'Und Mose kam und rief die Ältesten des Volkes und legte ihnen alle diese Worte vor, die ihm Jehovah geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'Und das ganze Volk antwortete allzumal und sie sprachen: Alles, was Jehovah geredet hat, wollen wir tun. Und Mose brachte die Worte des Volkes zurück zu Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'Und Jehovah sprach zu Mose: Siehe, Ich komme zu dir in einer dichten Wolke, auf daß das Volk höre, wenn Ich mit dir rede, und auch an dich glaube ewiglich. Und Mose sagte an die Worte des Volkes dem Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'Und Jehovah sprach zu Mose: Gehe zu dem Volk und heilige sie heute und morgen, und laß sie ihre Gewänder waschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'Und sie sollen bereit sein auf den dritten Tag; denn am dritten Tage wird Jehovah vor den Augen des ganzen Volkes herabkommen auf den Berg Sinai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'Und setze dem Volk eine Grenze ringsum und sprich: Hütet euch, daß ihr nicht auf den Berg hinaufsteiget, noch sein Ende berühret. Jeder, der den Berg berührt, soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Keine Hand soll ihn berühren; sondern gesteinigt oder mit Geschoß erschossen soll er werden. Sei es Vieh oder Mensch, er soll nicht am Leben bleiben. Beim Blasen des Jobelhorns sollen sie den Berg heraufkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'Und Mose kam vom Berg herab zum Volk und heiligte das Volk, und sie wuschen ihre Gewänder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'Und er sprach zu dem Volke: Seid bereit in drei Tagen und nahet keinem Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'Und es geschah am dritten Tage, als es Morgen ward, daß da waren Stimmen und Blitze und eine schwere Wolke auf dem Berge und eine sehr starke Stimme der Posaune, so daß das ganze Volk, das im Lager war, erzitterte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'Und Mose brachte das Volk aus dem Lager Gott entgegen und sie stellten sich unten am Berge auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Und der ganze Berg Sinai rauchte, darum daß Jehovah im Feuer auf ihn herabkam, und sein Rauch stieg auf, wie der Rauch eines Ofens, und der ganze Berg erzitterte sehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'Und die Stimme der Posaune erging und ward sehr stark. Mose redete und Gott antwortete ihm mit einer Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'Und Jehovah stieg herab auf den Berg Sinai, auf den Gipfel des Berges, und Jehovah rief Mose auf den Gipfel des Berges und Mose stieg hinauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'Und Jehovah sprach zu Mose: Geh hinab und bezeuge dem Volk, daß sie nicht durchbrechen zu Jehovah, um zu sehen und viele von ihnen fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Und auch die Priester, die zu Jehovah herzutreten, sollen sich heiligen, auf daß Jehovah nicht gegen sie hervorbreche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'Und Mose sprach zu Jehovah: Das Volk vermag nicht zu dem Berg Sinai heraufzukommen; denn Du hast uns bezeugt und gesprochen: Setze Grenzen an den Berg und heilige ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'Und Jehovah sprach zu ihm: Geh, steig hinab und komm du und Aharon mit dir herauf; und die Priester und das Volk sollen nicht durchbrechen, um zu Jehovah heraufzusteigen, auf daß Er nicht hervorbreche gegen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'Und Mose ging hinab zum Volk und sprach zu ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'Und Gott redete all diese Worte und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Ich bin Jehovah, dein Gott, Der dich aus Ägyptenland, aus dem Hause der Knechte herausgebracht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Du sollst keine anderen Götter haben vor Meinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Du sollst dir kein Schnitzbild, noch irgendein Abbild dessen machen, was im Himmel oben, noch dessen, was auf Erden unten, noch dessen, was in den Wassern unter der Erde ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'Du sollst sie nicht anbeten, noch ihnen dienen; denn Ich bin Jehovah, dein Gott, ein eifriger Gott, Der da heimsucht die Missetat der Väter an den Söhnen bis ins dritte und vierte Glied, bei denen, die Mich hassen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'Und tue Barmherzigkeit an Tausenden, die Mich lieben und Meine Gebote halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Du sollst den Namen Jehovahs, deines Gottes, nicht ins Eitle führen; denn Jehovah wird den nicht ungestraft lassen, der Seinen Namen ins Eitle führt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Gedenke des Sabbathtages, daß du ihn heiligest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Sechs Tage sollst du arbeiten und all dein Werk tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'Aber der siebente Tag ist ein Sabbath Jehovah, deinem Gott. Da sollst du kein Werk tun, weder du, noch dein Sohn, noch deine Tochter, dein Knecht, noch deine Magd, noch dein Vieh, noch dein Fremdling, der in deinen Toren ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Denn in sechs Tagen hat Jehovah den Himmel und die Erde gemacht, das Meer und alles, was darinnen ist, und geruht am siebenten Tage; darum segnete Jehovah den Sabbathtag und heiligte ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Ehre deinen Vater und deine Mutter, damit deine Tage verlängert werden auf dem Boden, den Jehovah, dein Gott, dir geben wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Du sollst nicht töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Du sollst nicht ehebrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Du sollst nicht stehlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Du sollst kein falsch Zeugnis reden, wider deinen Nächsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Du sollst dich nicht gelüsten lassen des Hauses deines Nächsten; du sollst dich nicht gelüsten lassen des Weibes deines Nächsten, noch seines Knechtes, noch seiner Magd, noch seines Ochsen, noch seines Esels, noch irgend etwas, das dein Nächster hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'Und alles Volk sah die Stimmen und die Flammen, und den Schall der Posaunen und das Rauchen des Berges. Und das Volk sah es, und sie erbebten und stunden von ferne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'Und sprachen zu Mose: Rede du mit uns und wir wollen hören. Gott aber möge nicht mit uns reden; auf daß wir nicht sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'Und Mose sprach zum Volke: Fürchtet euch nicht; denn Gott ist darum gekommen, daß Er euch versuche, und darum daß Seine Furcht vor eurem Angesicht sei, auf daß ihr nicht sündigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'Und das Volk stand von ferne, Mose aber trat herzu zu dem Wolkendunkel, da Gott war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'Und Jehovah sprach zu Mose: So sprich zu den Söhnen Israels: Ihr habt gesehen, daß Ich aus dem Himmel mit euch geredet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Ihr sollt neben Mir nicht silberne Götter machen und Götter von Gold sollt ihr euch nicht machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Einen Altar aus Grund sollst du Mir machen, und darauf deine Brandopfer und deine Friedensopfer, dein Kleinvieh und deine Rinder opfern. An jeglichem Orte, wo Ich ein Gedächtnis Meines Namens stiften werde, will Ich zu dir kommen und dich segnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'Und wenn du Mir einen Altar von Steinen machst, so baue ihn nicht mit behauenen; denn so du deine Eisen darüber schwingst, entweihst du ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Und du sollst nicht auf Stufen zu Meinem Altar hinaufsteigen, auf daß deine Blöße nicht aufgedeckt werde an ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'Und dies sind die Gerichte, die du vor sie legen sollst:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'So du einen hebräischen Knecht kaufst, soll er sechs Jahre dienen und im siebenten soll er frei ausgehen umsonst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Ist er allein gekommen, so soll er auch allein ausgehen. Ist er der Gemahl eines Weibes, so soll sein Weib mit ihm ausgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Hat ihm sein Herr ein Weib gegeben, und sie ihm Söhne oder Töchter geboren, so sei das Weib und ihre Kinder ihrem Herrn, und er geht allein aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Und wenn der Knecht spricht: Ich liebe meinen Herrn, mein Weib und meine Söhne, ich will nicht frei ausgehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'So lasse ihn sein Herr herzutreten vor Gott, und lasse ihn an die Tür oder den Türpfosten treten, und sein Herr durchbohre ihm mit einem Pfriemen das Ohr, daß er ihm diene für immer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Und verkauft ein Mann seine Tochter als Magd, so soll sie nicht ausgehen, wie die Knechte ausgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Ist sie übel in den Augen ihres Herrn, daß er sie sich nicht antraut, so lasse er sie einlösen; an auswärtiges Volk sie zu verkaufen, soll er keine Macht haben, daß er treulos gegen sie handle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'So er sie aber seinem Sohne antraut, so soll er nach dem Gericht der Töchter an ihr tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Nimmt er ihm eine andere dazu, so soll er von ihrer Kost, ihrer Decke und ihrer ehelichen Pflicht nichts verringern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'Und tut er ihr diese drei nicht, so soll sie frei ohne Silber ausgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Wer einen Mann schlägt, daß er stirbt, der soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Hat er ihm aber nicht nachgestellt und ließ ihn Gott seiner Hand begegnen, so will ich dir einen Ort bestimmen, dahin er fliehen mag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Vermißt sich aber ein Mann an seinem Genossen, um ihn mit List zu erwürgen, sollst du ihn von Meinem Altare wegnehmen, daß er sterbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'Und wer seinen Vater und seine Mutter schlägt, der soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'Und wer einen Mann stiehlt und ihn verkauft, und er wird in seiner Hand gefunden, der soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'Und wer seinem Vater und seiner Mutter flucht, der soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Und wenn Männer miteinander hadern und ein Mann den Genossen schlägt mit einem Stein oder mit der Faust und stirbt nicht, fällt aber auf das Lager;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'So soll, wenn er aufsteht und mit einer Stütze auf der Straße geht, der ihn schlug, ungestraft bleiben, nur für seine Versäumnis soll er ihm geben und ihn heilen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'Und schlägt ein Mann seinen Knecht, oder seine Magd mit dem Stocke, so daß er unter seiner Hand stirbt, so soll es gerächt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'Bleibt er aber noch einen oder zwei Tage, so soll es nicht gerächt werden; denn es ist sein Geld.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'Und wenn Männer sich zanken und stoßen ein schwangeres Weib, daß die Frucht von ihr ausgeht, aber sonst kein Unfall geschieht, so soll er um Geld gestraft werden, so viel der Gemahl des Weibes ihm auferlegt, und soll es vor Schiedsrichter geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Ist aber ein Unfall geschehen, sollst du geben Seele um Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'Brandmal um Brandmal, Wunde um Wunde, Strieme um Strieme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'Und schlägt ein Mann seinen Knecht ins Auge oder seine Magd ins Auge und verdirbt es, soll er ihn frei entlassen um des Auges willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'Und wenn einer seinem Knecht einen Zahn oder seiner Magd einen Zahn ausschlägt, so soll er ihn frei entlassen um des Zahnes willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'Und wenn ein Ochse einen Mann oder ein Weib stößt, so daß er stirbt, so soll der Ochse gesteinigt, sein Fleisch aber nicht gegessen werden, und der Herr des Ochsen soll ungestraft bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'War aber der Ochse stößig seit gestern und ehegestern, und es war seinem Herrn bezeugt worden, und er hat ihn nicht verwahrt, und tötet er einen Mann oder ein Weib, so soll der Ochse gesteinigt werden und auch sein Herr sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Wird ihm eine Sühne auferlegt, so gebe er als Lösegeld für seine Seele, alles, was ihm auferlegt worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Oder stößt er einen Sohn oder stößt er eine Tochter, so tue man ihm nach dem selbigen Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Stößt der Ochse einen Knecht oder eine Magd, so gebe er dreißig Silbersekel seinem Herrn und der Ochse werde gesteinigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'Und so ein Mann eine Grube öffnet, oder so ein Mann eine Grube gräbt, und sie nicht bedeckt, und es fällt ein Ochse oder ein Esel hinein,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'So soll der Herr der Grube Ersatz geben und seinem Herrn das Silber zurückgeben, das Tote aber gehört ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'Und so eines Mannes Ochse, den Ochsen seines Genossen stößt, daß er stirbt, so sollen sie den lebendigen Ochsen verkaufen und das Silber teilen und auch den toten sollen sie teilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Oder, wenn bekannt war, daß der Ochse stößig war seit gestern und ehegestern, und sein Herr ihn nicht verwahrt hatte, so soll er Ochsen für Ochsen erstatten, der tote aber soll ihm gehören. Wenn ein Mann einen Ochsen oder eines vom Kleinvieh gestohlen und es geschlachtet oder verkauft hat, so soll er fünf Rinder für den Ochsen, und vier vom Kleinvieh für eines vom Kleinvieh erstatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Wenn ein Dieb über dem Einbruch erfunden und geschlagen wird, daß er stirbt, so ist es keine Blutschuld.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Ist aber die Sonne über ihm aufgegangen, so ist es ihm Blutschuld. Er soll erstatten. Hat er nichts, so soll er für seinen Diebstahl verkauft werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'Wird das Gestohlene in seiner Hand gefunden, sei es Ochse oder Esel oder Lamm, lebendig, so soll er das Doppelte erstatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'So ein Mann ein Feld oder einen Weinberg abweidet und sein Vieh hineinläßt, daß es das Feld eines anderen abweide, so soll er es mit dem Besten seines Feldes und dem Besten seines Weinbergs erstatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'So ein Feuer ausgeht und Dornen ergreift, so daß ein Garbenhaufe oder die stehende Saat oder das Feld verzehrt wird, so hat, der den Brand angesteckt, es zu erstatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Wenn ein Mann seinem Genossen Silber oder Gerät zur Verwahrung gibt, und es wird gestohlen aus dem Hause des Mannes, so soll der Dieb, wenn man ihn findet, das Doppelte erstatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Wenn der Dieb nicht gefunden wird, so lasse man den Hausmeister vor Gott nahen, ob er nicht seine Hand nach seines Genossen Habe ausgestreckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'Über jeder Sache der Übertretung, sei es ein Ochse, ein Esel, ein Schaf, ein Kleid, alles Verlorene, wovon man sagt, daß es dies sei, so soll beider Sache vor Gott gebracht werden. Wen Gott für ungerecht erklärt, der soll dem Genossen das Doppelte erstatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Wenn ein Mann seinem Genossen einen Esel oder einen Ochsen, oder ein Schaf oder irgendein Stück Vieh in Verwahrung gibt, und es stirbt oder wird beschädigt oder gefangen weggetrieben, ohne daß es jemand sieht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'So soll ein Schwur vor Jehovah, zwischen beiden sein, ob er nicht seine Hand nach seines Genossen Habe ausgestreckt und sein Herr nehme es an, und er hat es nicht zu erstatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'Ist es ihm aber gestohlen worden, so soll er es seinem Herrn erstatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Ist es zerfleischt worden, so bringe er es zum Zeugnis. Das Zerfleischte hat er nicht zu erstatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Und wenn ein Mann von seinem Genossen etwas entlehnt hat, und es wird beschädigt oder stirbt, ohne daß sein Herr dabei ist, so soll er es erstatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'Wenn sein Herr dabei ist, so soll er es nicht erstatten. Ist es gemietet, so geht es in die Miete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'Und wenn ein Mann eine Jungfrau beredet, die noch nicht verlobt ist, und liegt bei ihr, so soll er sie sich durch Morgengabe zum Weib erwerben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Weigert sich aber ihr Vater, sie ihm zu geben, so soll er Silber darwägen, je nach der Morgengabe der Jungfrauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Eine Zauberin sollst du nicht am Leben lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Jeder, der bei dem Vieh liegt, der soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Wer den Göttern opfert außer dem Jehovah allein, der sei verbannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Und den Fremdling sollst du nicht drängen, noch unterdrücken; denn ihr waret Fremdlinge im Land Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Keine Witwe oder Waise sollt ihr niederdrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Wenn du sie niederdrückst, und er schreit zu Mir, so werde Ich sein Schreien hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Und Mein Zorn wird entbrennen und Ich werde euch mit dem Schwerte erwürgen, und eure Weiber sollen Witwen und eure Söhne Waisen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'Wenn du Meinem Volk, das elend ist bei dir, Silber leihst, so sollst du ihm nicht wie Wucherer sein, ihr sollt ihm keinen Zins auferlegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Wenn du von deinem Genossen das Gewand zum Pfande nimmst, sollst du es ihm, wenn die Sonne untergeht, zurückgeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Denn seine einzige Decke ist es für seine Haut ist sein Gewand, darin er sich legt. Und wird sein, wenn er zu Mir schreit, so werde Ich ihn hören; denn Ich bin gnädig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'Gott sollst du nicht fluchen, noch einen Fürsten in deinem Volk verfluchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Mit den Erstlingen deines Getreides und deines Weines sollst du nicht zögern. Den Erstgeborenen deiner Söhne sollst du Mir geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Also sollst du tun mit deinem Ochsen und deinem Kleinvieh. Sieben Tage soll es bei seiner Mutter sein, am achten Tage sollst du es Mir geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Und Männer der Heiligkeit sollt ihr Mir sein; und Fleisch dessen, das auf dem Feld zerfleischt worden, sollt ihr nicht essen, den Hunden werfet es hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Trage kein eitles Gerücht aus. Biete deine Hand nicht dem Ungerechten, um Zeuge für eine Gewalttat zu werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Folge nicht den Vielen zum Bösen; und zeuge nicht bei einem Rechtshandel, um ihn abzulenken, so daß du zu der Menge ablenkst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Und den Armen sollst du in seinem Rechtshandel nicht begünstigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'So du auf den Ochsen deines Feindes oder seinen Esel, der in der Irre geht, stoßest, sollst du ihn ihm zurückbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Wenn du den Esel dessen, der dich haßt, unter seiner Last niederliegen siehst, und wolltest unterlassen, ihn zu entledigen, so sollst du gleichwohl ihn mit jenem entledigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Du sollst das Recht deines Dürftigen nicht ablenken in seinem Rechtshandel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Halte dich fern vom Worte der Lüge und erwürge nicht den Unschuldigen und Gerechten; denn Ich werde den Ungerechten nicht rechtfertigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Und ein Geschenk sollst du nicht nehmen; denn Geschenk verblendet die Sehenden und verdreht die Worte der Gerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'Und den Fremdling unterdrücke nicht; denn ihr wisset um des Fremdlings Seele, denn ihr waret Fremdlinge im Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Und sechs Jahre sollst du in dein Land säen und dessen Ertrag sammeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'Im siebenten aber sollst du ablassen und es preisgeben, daß die Dürftigen deines Volkes davon essen, und was sie übriglassen, das Wild des Feldes fresse. So sollst du mit deinem Weinberg und deinem Ölgarten tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Sechs Tage sollst du dein Werk tun, am siebenten Tag aber feiern, auf daß dein Ochse und dein Esel ruhen, und der Sohn deiner Magd und der Fremdling sich erholen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'Und alles, was Ich zu euch gesprochen, sollt ihr halten; und des Namens anderer Götter sollt ihr nicht gedenken, er soll nicht aus eurem Munde gehört werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Dreimal sollst du Mir Fest feiern im Jahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Das Fest des Ungesäuerten sollst du halten, sieben Tage Ungesäuertes essen, wie Ich dir geboten, zur bestimmten Zeit des Monats Abib; denn in demselben bist du aus Ägypten ausgegangen. Ihr sollt aber nicht leer Mein Angesicht sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'Und das Fest der Ernte, der Erstlinge deiner Werke, die du sätest in das Feld; und das Fest der Einsammlung am Ausgang des Jahres, wenn du deine Werke vom Feld sammelst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Dreimal im Jahr erscheine alles Männliche bei dir vor dem Angesicht des Herrn Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Nicht sollst du auf Gesäuertem opfern das Blut Meines Opfers, noch soll bleiben das Fett Meines Festes über Nacht bis zum Morgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Das Erste der Erstlinge deines Bodens sollst du ins Haus Jehovahs, deines Gottes, bringen, das Böcklein nicht in der Milch seiner Mutter kochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Siehe, Ich sende einen Engel vor dir her, dich zu behüten auf dem Weg, und dich zu bringen an den Ort, den Ich bereitet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Hüte dich vor Seinem Angesicht und höre auf Seine Stimme; erbittere Ihn nicht, denn eure Übertretung erträgt Er nicht; denn Mein Name ist in Seiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Wenn du aber auf Seine Stimme hören und alles tun wirst, was Ich zu dir reden werde, so will Ich ein Feind sein deinen Feinden und ein Bedränger deiner Bedränger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Wenn vor dir hergehen wird Mein Engel und dich bringen zu den Amoritern und Chethitern und Pherisitern und Kanaanitern und den Chivitern und den Jebusitern, die Ich wegschaffen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Du sollst ihre Götter nicht anbeten, noch ihnen dienen, und sollst nicht tun nach ihrem Tun, sondern niederreißen und zerbrechen ihre Bildsäulen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'Aber Jehovah, eurem Gotte sollt ihr dienen, so wird Er segnen dein Brot und dein Wasser, und Krankheit von eurer Mitte werde Ich wegnehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Keine wird fehlgebären, keine unfruchtbar sein in deinem Lande. Ich werde deiner Tage Zahl voll machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Meinen Schrecken will Ich vor dir senden und verwirren alles Volk, zu dem du kommst, und geben, daß alle Feinde dir den Nacken kehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'Und Hornisse will Ich vor dir senden und die Chiviter, die Kanaaniter und die Chethiter vor dir vertreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Nicht in einem Jahr will Ich sie vor dir vertreiben, auf daß das Land nicht wüste werde, und sich das Wild des Feldes wider dich vermehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Nach und nach vertreibe Ich sie vor dir, bis daß du fruchtbar wirst und das Land erbest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'Und deine Grenze werde Ich setzen vom Schilfmeer bis zum Meer der Philister, und von der Wüste bis zum Flusse; denn Ich will die Einwohner des Landes geben in eure Hand, und sie vertreiben vor dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Keinen Bund sollst du mit ihnen und ihren Göttern schließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Sie sollen nicht in deinem Lande wohnen, daß sie dich nicht sündigen machen wider Mich; denn so du ihren Göttern dienest, wird es dir zum Fallstrick werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'Und zu Mose sprach Er: Steige herauf zu Jehovah, du und Aharon, Nadab und Abihu, und siebzig von den Ältesten Israels, und betet an von ferne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'Und Mose trete allein herzu zu Jehovah, sie aber sollen nicht herzutreten, und das Volk komme nicht mit ihm herauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'Und Mose kam und erzählte dem Volke alle die Worte Jehovahs und alle die Gerichte, und das ganze Volk antwortete mit einer Stimme und sie sprachen: Alle Worte, die Jehovah geredet, werden wir tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'Und Mose schrieb alle die Worte Jehovahs, und machte sich früh auf am Morgen und baute einen Altar unten am Berge und zwölf Denksäulen für die zwölf Stämme Israels;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'Und sandte Jünglinge der Söhne Israels hin, und sie ließen Brandopfer aufgehen und opferten Opfer des Friedens von Farren dem Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'Und Mose nahm die Hälfte des Blutes und tat es in die Becken, die Hälfte des Blutes aber sprengte er über den Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'Und er nahm das Buch des Bundes und las es vor den Ohren des Volkes, und sie sprachen: Alles, was Jehovah geredet hat, werden wir tun und Ihm gehorchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'Und Mose nahm das Blut und sprengte es über das Volk und sprach: Siehe, dies ist das Blut des Bundes, den Jehovah über alle diese Worte mit euch geschlossen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Und Mose stieg, und Aharon, Nadab und Abihu und siebzig von den Ältesten Israels hinauf;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'Und sie sahen den Gott Israels, und unter Seinen Füßen war wie ein Werk von Saphirstein und wie Stoff des Himmels an Reinheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'Und an die Ausgesonderten der Söhne Israels legte Er nicht Seine Hand. Und sie erschauten Gott und aßen und tranken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'Und Jehovah sprach zu Mose: Steige herauf zu Mir auf den Berg und sei da, und Ich werde dir die steinernen Tafeln und das Gesetz und das Gebot geben, das Ich zu ihrer Unterweisung geschrieben habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Und Mose machte sich auf und Jehoschua sein Diener; und Mose stieg auf den Berg Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Und zu den Ältesten sprach er: Sitzet für uns hier, bis wir zu euch zurückkommen, und siehe, Aharon und Chur sind bei euch. Wer immer eine Streitsache hat, der trete herbei zu ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'Und Mose stieg auf den Berg, und die Wolke bedeckte den Berg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'Und die Herrlichkeit Jehovahs wohnte auf dem Berge Sinai, und die Wolke bedeckte ihn sechs Tage; und Er rief zu Mose am siebenten mitten aus der Wolke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'Und das Ansehen der Herrlichkeit Jehovahs war wie ein fressendes Feuer auf dem Gipfel des Berges vor den Augen der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'Und Mose ging mitten in die Wolke und stieg den Berg hinauf; und Mose war vierzig Tage und vierzig Nächte auf dem Berg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Rede zu den Söhnen Israels, daß sie für Mich eine Hebe nehmen; von jedem Manne, den sein Herz freiwillig treibt, sollt ihr nehmen die Hebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'Und das ist die Hebe, die ihr von ihnen nehmen sollet: Gold und Silber und Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'Und Purpurblau und Purpurrot, Scharlach doppelt gefärbt und Byssus und Ziegenhaar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'Und rote Widderfelle und Dachsfelle und Schittimholz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'Öl für den Leuchter, Gewürze zum Salböl und zum Räucherwerk der Spezereien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'Onychsteine, und Steine zu Füllungen für das Ephod und für das Brustschildlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'Und sie sollen Mir ein Heiligtum machen, auf daß Ich in ihrer Mitte wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Nach allem wozu Ich dir das Vorbild der Wohnung und das Vorbild aller seiner Geräte sehen lasse, so sollt ihr es machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Und sie sollen eine Lade von Schittimholz machen, zwei Ellen und eine halbe seine Länge, und eine Elle und eine halbe ihre Breite, und eine Elle und eine halbe ihre Höhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'Und überziehe sie mit reinem Gold, von innen und von außen sollst du sie überziehen, und mache rings herum einen goldenen Kranz daran.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'Und gieße für sie vier goldene Ringe und setze sie an ihre vier Ecken, und zwei Ringe auf der einen Seitenwand und zwei auf der zweiten Seitenwand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'Und mache Stangen aus Schittimholz und überziehe sie mit Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'Und bringe die Stangen in die Ringe an den Seitenwänden der Lade, die Lade damit zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'In den Ringen der Lade sollen die Stangen sein, sie sollen nicht daraus weggenommen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'Und gib in die Lade das Zeugnis, das Ich dir geben werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'Und du sollst einen Gnadenstuhl von reinem Golde machen, zwei Ellen und eine halbe soll seine Länge, und eine Elle und eine halbe seine Breite sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Und sollst zwei Cherube machen, von getriebenem Golde, aus den beiden Enden des Gnadenstuhls sollst du sie machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'Und mache den einen Cherub von dem einen Ende, und den anderen Cherub von dem anderen Ende; machet die Cherube an den beiden Enden aus dem Gnadenstuhl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'Und die Cherube sollen die Flügel darüberhin ausbreiten, mit ihren Flügeln den Gnadenstuhl überdeckend, und ihre Gesichter einander zugewandt; gegen den Gnadenstuhl seien die Gesichter der Cherube.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'Und du sollst den Gnadenstuhl oben auf die Lade tun, und in die Lade das Zeugnis geben, das Ich dir geben will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'Und dort komme Ich mit dir zusammen und rede mit dir von dem Gnadenstuhl zwischen den beiden Cheruben hervor, die auf der Lade des Zeugnisses sind, mit dir zu reden alles, was Ich dir an die Söhne Israels gebieten werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Und einen Tisch sollst du machen von Schittimholz, zwei Ellen seine Länge, und eine Elle seine Breite, und eine Elle und eine halbe seine Höhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'Und sollst ihn mit reinem Gold überziehen, und ihm ringsum einen Kranz von Gold machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'Und eine Randleiste eine Handbreit sollst du machen rings herum, und einen Kranz von Gold ringsum für die Randleiste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'Und sollst ihm vier goldene Ringe machen, und die Ringe auf die vier Ecken setzen, die an seinen vier Füßen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Nächst der Randleiste sollen die Ringe sein, als Behälter für die Stangen, um den Tisch zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'Und die Stangen mache aus Schittimholz und überziehe sie mit Gold, daß mit ihnen der Tisch getragen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'Auch mache seine Schüsseln und seine Platten und seine Becher und seine Trankopferschalen, womit er gedeckt wird; aus reinem Gold sollst du sie machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'Und gib auf den Tisch die Schaubrote vor Mein Angesicht beständig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Und mache einen Leuchter von reinem Gold; in getriebener Arbeit werde der Leuchter gemacht. Sein Schaft und seine Röhre, seine Kelche, seine Knäufe und seine Blumen sollen aus ihm sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'Und sechs Röhren sollen aus seinen Seiten ausgehen; drei Röhren des Leuchters aus der einen Seite, und drei Röhren des Leuchters aus der zweiten Seite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Drei mandelblütförmige Kelche seien an einer Röhre mit Knauf und Blume, und drei mandelblütförmige Kelche an der anderen Röhre mit Knauf und Blume, so bei den sechs Röhren, die von dem Leuchter ausgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Und am Leuchter sollen vier mandelblütförmige Kelche mit ihren Knäufen und Blumen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'Und ein Knauf sei unter zwei Röhren aus demselben, und ein Knauf unter zwei Röhren aus demselben, und ein Knauf unter zwei Röhren unter demselben; an den sechs Röhren, die von dem Leuchter ausgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Ihre Käufe und Röhren seien aus ihm selbst; alles an ihm sei aus einer getriebenen Arbeit von reinem Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'Und mache seiner Lampen sieben, daß man seine Lampen aufstecke und leuchten lasse gegen sein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Und seine Lichtputzen und Löschnäpfe seien von reinem Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Aus einem Talent reinen Goldes mache man ihn, samt allen diesen Gefäßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Und siehe zu, und mache es nach dem Vorbild derselben, das dir auf dem Berge gezeigt worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'Und die Wohnung sollst du machen aus zehn Teppichen von gezwirntem Byssus und blauem und rotem Purpur und Scharlach; mit Cheruben, dem Werke des Kunstwirkers, sollst du sie machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Die Länge eines Teppichs sei achtundzwanzig Ellen und die Breite vier Ellen für einen Teppich; ein Maß für alle Teppiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Fünf Teppiche füge man zusammen, einen an den anderen, und wieder fünf Teppiche füge man zusammen, einen an den andern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'Und mache Schleifen von blauem Purpur an den Saum des einen Teppichs am Ende bei der Zusammenfügung, und so sollst du es machen am Saume des äußersten Teppichs bei der zweiten Zusammenfügung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Fünfzig Schleifen sollst du an dem einen Teppich machen, und fünfzig Schleifen sollst du machen am Ende des Teppichs an der zweiten Zusammenfügung, so daß die Schleifen einander gegenüberstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'Und mache fünfzig Haken von Gold, und füge die Teppiche zusammen durch die Haken aneinander, so daß es eine Wohnung werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'Und mache Teppiche von Ziegenhaar zu einem Zelte über die Wohnung, elf Teppiche sollst du sie machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Die Länge eines Teppichs soll dreißig Ellen sein, und die Breite vier Ellen für einen Teppich; ein Maß für die elf Teppiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'Und füge die fünf Teppiche besonders zusammen und die sechs Teppiche besonders, und mache den sechsten Teppich doppelt an der Vorderseite des Zeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'Und mache fünfzig Schleifen an den Saum des einen äußersten Teppichs an der Zusammenfügung und fünfzig Schleifen an den Saum des Teppichs an der zweiten Zusammenfügung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'Und mache fünfzig Haken von Erz, und bringe die Haken in die Schleifen, und füge das Zelt zusammen, daß es eines sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Und das Überhangende, was von den Teppichen des Zeltes überfließt, die Hälfte des Teppichs, die überfließt, soll hinten an der Wohnung überhängen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'Und die Elle von hier und die Elle von dort, die von der Länge der Teppiche des Zeltes überflüssig ist, soll auf beiden Seiten der Wohnung überhängen, um sie zu bedekken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'Und mache eine Decke für das Zelt von roten Widderfellen und eine Decke von Dachsfellen darüberhin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'Und mache die Bretter zur Wohnung von Schittimholz, aufrecht stehend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'Zehn Ellen sei die Länge des Brettes und eine Elle und eine halbe Elle die Breite eines Brettes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'Zwei Zapfen an dem einen Brett, fügend ineinander, sollst du machen an allen Brettern der Wohnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'Und mache die Bretter für die Wohnung: zwanzig Bretter an der Ecke gegen Mittag, südwärts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'Und vierzig silberne Untersätze sollst du machen unter die zwanzig Bretter, zwei Untersätze unter je ein Brett für seine beiden Zapfen, und zwei Untersätze unter ein Brett für seine zwei Zapfen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Und an der zweiten Seitenwand der Wohnung, in die Ecke gegen Mitternacht, zwanzig Bretter;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'Und vierzig Untersätze von Silber; zwei Untersätze unter ein Brett, und zwei Untersätze unter jedes andere Brett;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'Und an der hinteren Seite gegen das Meer mache sechs Bretter;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'Und zwei Bretter sollst du machen für die Eckstücke der Wohnung an der Hinterseite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'Und sie sollen sein zwiefach von unten an und zugleich zwiefach auf seiner Spitze bis zum ersten Ring. So soll es mit diesen beiden sein, an den zwei Eckstücken sollen sie sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Und acht Bretter sollen es sein und ihre silbernen Untersätze, sechzehn Untersätze, zwei Untersätze unter einem Brett, und zwei Untersätze unter jedem anderen Brett.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'Und mache Riegel von Schittimholz, fünf für die Bretter einer Seitenwand der Wohnung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'Und fünf Riegel für die Bretter der zweiten Seitenwand der Wohnung an der Hinterseite gegen das Meer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'Und der mittlere Riegel laufe mitten an den Brettern hin von Ende bis zu Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'Und die Bretter überziehe mit Gold, und ihre Ringe mache von Gold, als Behälter für die Riegel, und überziehe die Riegel mit Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'Und so richte die Wohnung auf nach ihrer Weise, die dir auf dem Berge gezeigt worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'Und mache einen Vorhang von blauem und rotem Purpur und Scharlach, und gezwirntem Byssus, als Werk des Kunstwirkers soll man es machen mit Cheruben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'Und gib ihn an vier Säulen von Schittim, mit Gold überzogen, und ihre Nägel von Gold, auf vier silbernen Untersätzen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Und den Vorhang gib unter die Haken, und bringe dahin innerhalb des Vorhangs die Lade des Zeugnisses; und der Vorhang scheide euch zwischen dem Heiligen und zwischen dem Allerheiligsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'Und setze den Gnadenstuhl auf die Lade des Zeugnisses im Allerheiligsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Und den Tisch setze außerhalb des Vorhangs, und den Leuchter dem Tisch gerade gegenüber an die Seitenwand der Wohnung gegen Mittag, und den Tisch gib an die Seitenwand gegen Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'Und mache eine Decke für den Eingang zum Zelte von blauem und rotem Purpur und Scharlach doppelt gefärbt und gezwirntem Byssus, das Werk eines Buntwirkers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'Und mache zu der Decke fünf Säulen von Schittim, und überziehe sie mit Gold, und ihre Nägel von Gold, und gieße für sie fünf eherne Untersätze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'Und den Altar mache aus Schittimholz, fünf Ellen die Länge und fünf Ellen die Breite, Geviert sei der Altar, und drei Ellen seine Höhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'Und mache seine Hörner an seinen vier Ecken. Aus ihm heraus sollen seine Hörner sein, und überziehe ihn mit Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'Und mache seine Töpfe, die Asche wegzutun, und seine Schaufeln und seine Sprengbecken, und seine Fleischgabeln und seine Kohlpfannen. Alle seine Geräte sollst du von Erz machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'Und mache für ihn ein Gitter, ein Netzwerk aus Erz, und an das Netz sollst du an seinen vier Enden vier eherne Ringe machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'Und sollst es setzen unter die Einfassung des Altars von unten her, und das Netz sei bis an die Mitte des Altars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'Und mache Stangen für den Altar, Stangen von Schittimholz, und überziehe sie mit Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'Und seine Stangen bringe man in die Ringe, und sollen die Stangen an beiden Seitenwänden des Altars sein, wenn man ihn trägt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Hohl, von Brettern sollst du ihn machen, wie man dir zeigte auf dem Berge, so sollen sie ihn machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Und den Vorhof der Wohnung mache an der Seite gegen Mittag südwärts; Behänge für den Vorhof von gezwirntem Byssus hundert Ellen die Länge an der einen Seite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'Und seiner Säulen zwanzig und seiner Untersätze zwanzig von Erz, die Nägel der Säulen und deren Umgürtungen von Silber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'Und so an der Seite gegen Mitternacht der Länge nach Behänge, hundert in die Länge, und seine zwanzig Säulen und deren zwanzig Untersätze von Erz, die Nägel der Säulen und ihre Umgürtungen von Silber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Und in die Breite des Vorhofs auf der Seite nach dem Meer Behänge, fünfzig Ellen, ihre Säulen zehn und deren zehn Untersätze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'Und in die Breite des Vorhofs auf der Vorderseite gegen Aufgang fünfzig Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'Und fünfzehn Ellen Behänge auf dem Flügel, ihre Säulen drei und ihre Untersätze drei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'Und auf dem zweiten Flügel fünfzehn Behänge, ihre Säulen drei und ihre Untersätze drei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'Und zum Tor des Vorhofs eine Decke von zwanzig Ellen, von blauem und rotem Purpur und doppelt gefärbtem Scharlach und gezwirntem Byssus, das Werk des Buntwirkers, seine Säulen vier und ihre Untersätze vier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Alle Säulen des Vorhofs ringsum mit silbernen Umgürtungen und ihren silbernen Nägeln und ihren ehernen Untersätzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Die Länge des Vorhofes hundert Ellen, und die Breite fünfzig gegen fünfzig, und die Höhe fünf Ellen von gezwirntem Byssus, und ihre Untersätze von Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Alle Geräte der Wohnung für all ihren Dienst, und all ihre Pflöcke und alle Pflöcke des Vorhofs seien von Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Und du gebiete den Söhnen Israels, daß sie dir reines, gestoßenes Olivenöl zum Licht bringen, auf daß man die Lampe beständig aufgehen lasse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'Im Versammlungszelte außerhalb des Vorhangs, der vor dem Zeugnisse ist, soll es Aharon und seine Söhne zurichten vom Abend bis zum Morgen, vor Jehovah. Eine ewige Satzung sei es für ihre Geschlechter aus den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Und du, laß sich nahen zu dir Aharon, deinen Bruder, und seine Söhne mit ihm aus der Mitte der Söhne Israels, daß er Mir als Priester diene, Aharon, Nadab und Abihu, Eleazar und Ithamar, Aharons Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'Und mache Kleider der Heiligkeit deinem Bruder Aharon zur Herrlichkeit und zum Schmuck.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'Und du rede mit allen denen, die weisen Herzens sind, die Ich mit dem Geiste der Weisheit erfüllt, daß sie Aharons Kleider machen, ihn zu heiligen, auf daß er Mir Priester sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'Und dies sind die Kleider, die sie machen sollen: das Brustschildlein und das Ephod und das Oberkleid und der Leibrock, zellenförmig gewirkt, die Tiara und der Gürtel. Und sie sollen Kleider der Heiligkeit machen für Aharon, deinen Bruder und für seine Söhne, daß er Mir Priester sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'Und sie sollen dazu nehmen das Gold, und den blauen und roten Purpur, und doppelt gefärbten Scharlach und den Byssus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Und das Ephod sollen sie machen aus Gold, blauem und rotem Purpur, doppelt gefärbtem Scharlach und gezwirnten Byssus, ein Werk des Kunstwirkers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Zwei zusammengefügte Schulterstücke soll es haben an seinen zwei Enden, daß es zusammengefügt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'Und der Gurt seines Ephods, der darauf ist, soll von demselben Werke und aus demselben sein, von Gold, blauem und rotem Purpur, doppelt gefärbtem Scharlach und gezwirntem Byssus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'Und nimm zwei Onychsteine und grabe die Namen der Söhne Israels darein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'Sechs von ihren Namen auf den einen Stein und die sechs übrigen Namen auf den zweiten Stein, nach ihren Geburten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Mit dem Werke des Werkmanns in Steinen mit Siegelstecherei sollst du auf die zwei Steine die Namen der Söhne Israels eingraben. Rings in Gold gefaßt sollst du sie machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'Und setze die zwei Steine auf die Schultern des Ephod, als Gedenksteine für die Söhne Israels, und Aharon trage ihre Namen vor Jehovah auf seinen beiden Schultern zum Andenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'Und mache die Einfassungen von Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'Und zwei Kettchen reinen Goldes sollst du an ihren Enden machen von Flechtwerk, und lege die geflochtenen Kettchen an die Einfassungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'Und mache das Brustschildlein des Gerichts ein Werk des Kunstwirkers; wie das Werk des Ephod sollst du es machen; von Gold, von blauem und rotem Purpur und doppelt gefärbtem Scharlach und gezwirntem Byssus sollst du es machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Geviert sei es, gedoppelt, eine Spanne seine Länge und eine Spanne seine Breite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'Und du sollst es füllen mit einer Füllung von Steinen, vier Reihen von Steinen, eine Reihe von Rubin, Topas und Karfunkel: die erste Reihe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'Und die zweite Reihe: Chrysopras, Saphir und Diamant.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'Und die dritte Reihe: Lasurstein, Achat und Amethyst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'Und die vierte Reihe: Tharschisch, Onych und Jaspis; in Gold eingefaßt, seien sie in ihren Füllungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Und die Steine seien nach den Namen der Söhne Israels, zwölf nach ihren Namen, wie Siegel eingegraben jeder Mann mit seinem Namen für die zwölf Stämme seien sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'Und an die Enden des Brustschildleins mache Kettchen, Flechtwerk von reinem Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'Und an das Brustschildlein mache zwei goldene Ringe, und tue die zwei Ringe an die zwei Enden des Brustschildleins.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'Und tue die zwei goldenen Geflechte an die zwei Ringe an den Enden des Brustschildleins.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'Und die zwei Enden der beiden Geflechte setze an die zwei Einfassungen, und setze sie an die Schulterstücke des Ephod auf dessen Vorderseite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'Und mache zwei Ringe von Gold, und setze sie an die zwei Enden des Brustschildleins an dessen Saum, gegen das Ephod zu, einwärts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Und mache zwei Ringe von Gold, und setze sie an die zwei Schulterstücke des Ephod von unten an seiner Vorderseite nächst der Zusammenfügung über dem Gurt des Ephod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'Und sie sollen das Brustschildlein mit seinen Ringen schnüren an die Ringe des Ephod mit einer purpurblauen Schnur, so daß es über dem Gurt des Ephod sei, und das Brustschildlein sich nicht von dem Ephod verrücke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'Und Aharon trage die Namen der Söhne Israels im Brustschildlein des Gerichts auf seinem Herzen, wenn er hineingeht ins Heiligtum, vor Jehovah zu beständigem Andenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'Und in das Brustschildlein des Gerichts sollst du die Urim und die Thummim tun und sie seien auf dem Herzen Aharons, wenn er eingeht vor Jehovah, und Aharon trage beständig auf seinem Herzen das Gericht der Söhne Israels vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'Und du sollst das Oberkleid des Ephod gänzlich von blauem Purpur machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'Und es sei seine Kopföffnung in seiner Mitte. Eine Borte soll sein an seiner Öffnung rings umher, das Werk des Webers; wie die Öffnung eines Panzers sei sie ihm, daß es nicht zerreiße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Und an seine Säume mache Granatäpfel von blauem und rotem Purpur, und doppelt gefärbten Scharlach an seine Säume ringsherum, und goldene Glöckchen in ihrer Mitte ringsherum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'Ein goldenes Glöckchen und ein Granatapfel, ein goldenes Glöckchen und ein Granatapfel an den Säumen des Oberkleides ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'Und Aharon soll es haben, wenn er Dienst tut, daß ihre Stimme gehört werde, wenn er ins Heiligtum eingeht vor Jehovah und wenn er herauskommt, auf daß er nicht sterbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'Und ein Blatt mache von reinem Gold, und grabe darein mit Siegelstich: Heiligkeit dem Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'Und sollst es an eine Schnur von blauem Purpur setzen, und es soll sein an der Tiara; vorn an der Tiara soll es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'Und auf Aharons Stirn soll es sein, und Aharon trage die Missetat des Heiligen, das die Söhne Israels heiligen mit allen ihren heiligen Gaben, und es soll beständig auf seiner Stirn sein, zum Wohlgefallen für sie vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'Und du sollst den Leibrock zellenförmig wirken von Byssus, und die Tiara von Byssus machen, und den Gürtel machen mit dem Werk des Buntwirkers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'Und für die Söhne Aharons sollst du Leibröcke machen, und sollst ihnen Gürtel machen, und Kopfbünde sollst du ihnen machen zur Herrlichkeit und zum Schmuck.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'Und sollst sie deinem Bruder Aharon und seinen Söhnen mit ihm anziehen, und sollst sie salben, und ihre Hand füllen, und sie heiligen, auf daß sie Mir Priesterdienst tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Und mache ihnen Beinkleider von Linnen, das Fleisch ihrer Blöße zu bedecken, sie sollen sein von den Lenden bis an die Schenkel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'Und Aharon und seine Söhne sollen sie anhaben, wenn sie in das Versammlungszelt eingehen, oder herzutreten zu dem Altare, um im Heiligtum Dienst zu tun, auf daß sie nicht eine Missetat tragen und sterben. Dies soll eine ewige Satzung für ihn und seinen Samen nach ihm sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'Und das ist das Wort, das du ihnen tun sollst, um sie zu heiligen, auf daß sie Mir Priesterdienst tun. Nimm einen Farren, den Sohn der Herde, und zwei Widder ohne Fehl;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'Und ungesäuertes Brot und ungesäuerte Kuchen, mit Öl vermischt, und ungesäuerte Fladen, mit Öl gesalbt, vom Semmelmehl des Weizens sollst du sie machen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'Und lege sie in einen Korb und bringe sie dar in dem Korbe, und den Farren und die zwei Widder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Und Aharon und seine Söhne lasse nahen dem Eingang des Versammlungszeltes und wasche sie mit Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Und nimm die Kleider und ziehe dem Aharon den Leibrock und das Oberkleid des Ephod und das Ephod und das Brustschildlein an, und binde ihm den Gurt des Ephod um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'Und setze ihm die Tiara auf das Haupt, und tue das Diadem der Heiligkeit auf die Tiara.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'Und nimm das Salböl und gieße es auf sein Haupt und salbe ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Und laß nahen seine Söhne und ziehe ihnen die Leibröcke an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'Und gürte sie mit dem Gürtel, Aharon und seine Söhne, und binde ihnen die Kopfbünde um, auf daß sie das Priestertum haben zur ewigen Satzung; und sollst die Hand Aharons und die Hand seiner Söhne füllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'Und bringe dar den Farren vor das Versammlungszelt, und Aharon und seine Söhne sollen ihre Hände dem Farren auf das Haupt legen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'Und sollst den Farren vor Jehovah schlachten am Eingang des Versammlungszeltes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'Und sollst vom Blut des Farren nehmen und mit deinem Finger auf die Hörner des Altars tun, und das ganze Blut an den Grund des Altars ausgießen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'Und sollst nehmen alles Fett, das die Eingeweide bedeckt und das Netz über der Leber und die zwei Nieren und das Fett, das über ihnen ist, und es anzünden auf dem Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Und das Fleisch des Farren, und seine Haut und seinen Mist verbrenne mit Feuer außen vor dem Lager; denn ein Sündopfer ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Und den einen Widder nimm, und Aharon und seine Söhne sollen ihre Hände auf das Haupt des Widders legen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'Und du sollst den Widder schlachten, und sein Blut nehmen und auf den Altar sprengen ringsherum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Und den Widder zerstücke in seine Stücke, und wasche seine Eingeweide und seine Schenkel und lege sie auf seine Stücke und auf sein Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'Und den ganzen Widder zünde an auf dem Altar; ein Brandopfer ist es dem Jehovah, ein Geruch der Ruhe, ein Feueropfer für Jehovah ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Und nimm den zweiten Widder, und Aharon und seine Söhne sollen ihre Hände auf das Haupt des Widders legen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'Und schlachte den Widder und nimm von seinem Blut und tue es auf das rechte Ohrläppchen Aharons und auf das rechte Ohrläppchen seiner Söhne und auf den Daumen ihrer rechten Hand und auf die große Zehe ihres rechten Fußes, und sprenge das Blut auf dem Altar ringsherum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'Und nimm von dem Blut, das auf dem Altar ist, und von dem Salböl, und besprenge Aharon und seine Kleider und seine Söhne und die Kleider seiner Söhne mit ihm; und er soll heilig sein und seine Kleider, und seine Söhne und die Kleider seiner Söhne mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Und nimm von dem Widder das Fett und den Fettschwanz und das Fett, das die Eingeweide bedeckt, und das Lebernetz und die zwei Nieren und das Fett auf ihnen und die rechte Keule; denn es ist ein Widder der Füllungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'Und einen Laib Brot und einen Kuchen von Ölbrot und einen Fladen aus dem Korb des Ungesäuerten, der da ist vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'Und lege alles auf die Hände Aharons und auf die Hände seiner Söhne, und laß es weben als eine Webe vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Und nimm sie aus ihrer Hand und zünde sie an auf dem Altar über dem Brandopfer, zu einem Geruch der Ruhe vor Jehovah. Ein Feueropfer ist es für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'Und nimm die Brust von dem Widder der Füllungen für Aharon, und webe sie als eine Webe vor Jehovah und sie sei dir zum Anteil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'Und heilige die Brust der Webe und die Hebekeule, die gewebt und gehoben worden von dem Widder der Füllungen, von dem für Aharon und von dem für seine Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'Und soll sein Aharons und seiner Söhne als ewige Satzung von den Söhnen Israels; denn es ist eine Hebe; und eine Hebe soll es sein von den Söhnen Israels von ihren Friedensopfern, als ihr Hebeopfer vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Und die Kleider der Heiligkeit, die Aharon hat, seien seinen Söhnen nach ihm, um sie darin zu salben und darin ihre Hand zu füllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Sieben Tage soll sie anziehen, wer von seinen Söhnen statt seiner Priester wird, der eingeht in das Versammlungszelt, um in dem Heiligtum Dienst zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Und den Widder der Füllungen sollst du nehmen und sein Fleisch kochen an heiligem Orte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'Und Aharon und seine Söhne sollen das Fleisch des Widders und das Brot, das in dem Korbe ist, essen am Eingang des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'Und sie sollen dieselben essen, durch die sie sind versöhnt worden, zu füllen ihre Hand, um sie zu heiligen, aber ein Fremder soll nicht davon essen, denn heilig sind sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Und wenn von dem Fleisch der Füllungen und von dem Brot bis zum Morgen übrigbleibt, sollst du das Übrige im Feuer verbrennen, es soll nicht gegessen werden, denn es ist Heiliges.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Und mit Aharon und seinen Söhnen sollst du so tun, nach allem was Ich dir geboten habe. Sieben Tage sollst du ihre Hand füllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'Und einen Farren sollst du als Sündopfer jeden Tag zubereiten zur Versöhnung, und den Altar entsündigen, indem du dich über ihm versöhnst, und sollst ihn salben, um ihn zu heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sieben Tage sollst du versöhnen über den Altar und ihn heiligen, und der Altar soll das Allerheiligste sein. Jeder, der den Altar berührt, soll geheiligt sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'Und dies ist, was du auf dem Altar zubereiten sollst: zwei einjährige Lämmer an jedem Tage beständig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Das eine Lamm sollst du am Morgen zubereiten und das zweite Lamm sollst du zubereiten gegen Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'Und ein Zehntel Semmelmehl, mit gestoßenem Öl vermischt, ein Viertel eines Hin, und als Trankopfer den vierten Teil eines Hin Wein für das eine Lamm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'Und das zweite Lamm sollst du zubereiten gegen Abend, wie das Speiseopfer am Morgen, und wie sein Trankopfer sollst du es machen, zum Geruch der Ruhe, ein Feueropfer für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'Ein beständiges Brandopfer für eure Geschlechter am Eingang zum Versammlungszelt vor Jehovah, wo Ich mit euch zusammenkommen werde, um zu dir daselbst zu reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'Und dort werde Ich zusammenkommen mit den Söhnen Israels, und geheiligt soll es werden durch Meine Herrlichkeit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'Und Ich werde heiligen das Versammlungszelt und den Altar; und Aharon und seine Söhne werde Ich heiligen, daß sie Mir Priesterdienste tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'Und Ich werde wohnen inmitten der Söhne Israels, und werde ihnen Gott sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'Und sie sollen wissen, daß Ich Jehovah ihr Gott bin, Der sie aus Ägyptenland herausgebracht hat, auf daß Ich in ihrer Mitte wohne, Ich Jehovah, ihr Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Und du sollst einen Räuchaltar machen für das Räucherwerk. Aus Schittimholz sollst du ihn machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'Eine Elle seine Länge und eine Elle seine Breite, geviert soll er sein, und zwei Ellen seine Höhe, aus ihm seien seine Hörner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'Und du sollst ihn mit reinem Gold überziehen, sein Dach und seine Wände ringsum und seine Hörner, und du sollst ihm einen goldenen Kranz machen ringsumher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'Und zwei goldene Ringe mache ihm daran, unterhalb seines Kranzes, an seinen zwei Seitenwänden, auf seinen beiden Seiten sollst du sie machen, und sie seien Behälter für die Stangen, ihn damit zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Und die Stangen mache von Schittimholz und überziehe sie mit Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'Und stelle ihn vor den Vorhang, der bei der Lade des Zeugnisses ist, vor dem Gnadenstuhl, der über dem Zeugnisse, wo Ich mit dir zusammenkomme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'Und auf ihm lasse Aharon Morgen nach Morgen Räucherwerk der Spezereien anzünden. Wenn er die Lampen zurichtet, soll er damit räuchern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Und wenn Aharon die Lampen aufsteckt gegen Abend, soll er damit räuchern, ein beständiges Räuchwerk vor Jehovah in euren Geschlechtern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Kein fremdes Räuchwerk sollt ihr darauf aufgehen lassen, noch Brandopfer und Speiseopfer. Und kein Trankopfer sollt ihr daraufgießen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'Und Aharon versöhne einmal im Jahr auf den Hörnern desselben mit dem Blut des Sündopfers der Versöhnungen. Einmal im Jahr soll er darauf versöhnen für eure Geschlechter. Das Allerheiligste ist er für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Wenn du die Häupter erhebst der Söhne Israels nach ihrer Musterung, soll jeder Mann dem Jehovah eine Sühne für seine Seele geben, wenn man sie mustert; auf daß in der Musterung keine Plage wider sie komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'Jeder, der zu den Gemusterten übergeht, soll einen halben Schekel geben, nach dem Schekel des Heiligtums, zwanzig Gerah auf den Schekel. Der halbe Schekel soll ein Hebeopfer für Jehovah sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Jeder, der zu den Gemusterten übergeht von dem Sohne von zwanzig Jahren und darüber, soll dem Jehovah ein Hebeopfer geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Der Reiche mehre nicht und der Arme mache es nicht weniger als die Hälfte eines Schekels, um eine Hebe zu geben für Jehovah, für eure Seelen zu sühnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'Und nimm das Silber der Versöhnungen von den Söhnen Israels, und gib es zum Dienste des Versammlungszeltes, und es sei den Söhnen Israels zum Gedächtnis vor Jehovah, daß ihr für eure Seelen sühnetet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Und du sollst ein Becken von Erz und sein Gestell von Erz machen zum Waschen, und es zwischen das Versammlungszelt und den Altar stellen und Wasser darein tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'Und Aharon und seine Söhne sollen daraus ihre Hände und Füße waschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'Wenn sie in das Versammlungszelt hineingehen, sollen sie sich mit Wasser waschen, auf daß sie nicht sterben; oder wenn sie zu dem Altare herzutreten, um den Dienst zu tun, dem Jehovah ein Feueropfer anzuzünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Und sie sollen ihre Hände und ihre Füße waschen, auf daß sie nicht sterben; und es soll dies ihnen eine ewige Satzung sein, ihm und seinem Samen für ihre Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Und du, nimm dir die hauptsächlichen Gewürze, der edelsten Myrrhe fünfhundert, und würzigen Zimt, die Hälfte davon, zweihundertfünfzig, und würzigen Kalmus zweihundertfünfzig,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'Und Kassia fünfhundert, nach dem Schekel des Heiligtums, und Olivenöl ein Hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'Und mache es zu Salböl der Heiligkeit, die Salbe der Salbe, ein Werk des Salbenmischers, das Salböl der Heiligkeit soll es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'Und salbe damit das Versammlungszelt und die Lade des Zeugnisses,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'Und den Tisch und alle seine Geräte, und den Leuchter und seine Geräte, und den Rauchaltar;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'Und den Brandopferaltar und alle seine Geräte, und das Becken und sein Gestell;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'Und sollst sie heiligen, und sie sollen das Allerheiligste sein; ein jeder, der sie anrührt, soll geheiligt sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'Und Aharon und seine Söhne sollst du salben und sie heiligen, auf daß sie Mir Priesterdienst tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Und zu den Söhnen Israels sollst du reden und sprechen: Das Salböl der Heiligkeit ist dies für Mich in euren Geschlechtern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Auf das Fleisch eines Menschen soll es nicht gegossen werden; auch sollt ihr nach seinem Maß kein solches machen. Heilig ist es, heilig sei es euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Der Mann, der eines mischt gleich ihm, und davon einem Fremden gibt, der soll von seinem Volke ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'Und Jehovah sprach zu Mose: Nimm dir Spezereien, Stakte, Räucherklaue und Galbanum, Spezereien, riechenden und lauteren Weihrauch. Teil zu Teil soll es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'Und mache daraus ein Räuchwerk, eine Mischung, ein Werk des Salbenmischers; gesalzen, rein, heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'Und zermalme davon, zerstoße und tue davon vor das Zeugnis in das Versammlungszelt, wo Ich mit dir zusammenkomme, das Allerheiligste sei es euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'Und solch Räucherwerk, das du machst, nach demselben Maß sollt ihr es euch nicht machen, Heiliges sei es dir für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Der Mann, der ein solches macht, um den Geruch davon zu machen, der soll von seinem Volke ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Siehe, Ich habe mit Namen gerufen Bezaleel, den Sohn Uris, des Sohnes Churs, vom Stamme Judah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'Und habe ihn erfüllt mit dem Geiste Gottes, mit Weisheit und mit Einsicht und mit Erkenntnis und allerlei Werk;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'Auszudenken Gedanken, sie zu machen in Gold und in Silber und in Erz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'Und im Steinschneiden zum Ausfüllen, und im Holzschneiden, um allerlei Werk zu machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'Und siehe, Ich habe ihm gegeben Oholiab, den Sohn Achisamachs, vom Stamme Dan, und jedem, der weise ist von Herzen, in das Herz gegeben Weisheit, daß sie alles machen, was Ich dir geboten habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'Das Versammlungszelt und die Lade für das Zeugnis und den Gnadenstuhl darauf, und alle Geräte des Zeltes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'Und den Tisch und seine Geräte, und den reinen Leuchter und alle seine Geräte, und den Rauchaltar;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'Und den Brandopferaltar und alle seine Geräte, und das Becken und sein Gestell.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'Und die Kleider des Dienstes, und die heiligen Kleider für Aharon, den Priester und die Kleider seiner Söhne, um Priesterdienst zu tun;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'Und das Salböl und das Räuchwerk der Spezereien für das Heiligtum; nach allem, was Ich dir geboten habe, sollen sie es machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Und du, rede zu den Söhnen Israels und sprich: Haltet ja Meine Sabbathe; denn dies ist ein Zeichen zwischen Mir und zwischen euch in euren Geschlechtern, auf daß ihr wisset, daß Ich Jehovah es bin, Der euch heiligt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Und haltet den Sabbath; denn heilig ist er euch. Wer ihn entweiht, soll des Todes sterben; denn jeder, der an ihm eine Arbeit tut, dessen Seele soll aus der Mitte seines Volkes ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Sechs Tage soll man Arbeit tun, am siebenten Tag aber ist der Sabbath des Sabbaths, dem Jehovah heilig. Wer eine Arbeit tut am Sabbathtage, soll des Todes sterben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Und die Söhne Israels sollen den Sabbath halten, zu machen den Sabbath in ihren Geschlechtern zum Bunde der Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Zwischen Mir und den Söhnen Israels sei er ein Zeichen ewiglich; denn in sechs Tagen machte Jehovah die Himmel und die Erde, am siebenten Tage aber hat Er gefeiert und Sich erholt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'Und Er gab dem Mose, als Er vollendet hatte mit ihm zu reden, auf dem Berge Sinai die zwei Tafeln des Zeugnisses, Tafeln von Stein, geschrieben mit dem Finger Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'Und das Volk sah, daß Mose verzog, vom Berge herabzukommen; und das Volk kam zusammen zu Aharon und sprachen zu ihm: Mache dich auf! mach uns Götter, die vor uns gehen; denn dieser Mose, der Mann, der uns aus Ägyptenland heraufgebracht: wir wissen nicht, was mit ihm geschehen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'Und Aharon sprach zu ihnen: Reißet ab die goldenen Reife in den Ohren eurer Weiber, eurer Söhne und eurer Töchter und bringt sie mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'Und das ganze Volk riß sich die goldenen Reife, die in ihren Ohren waren, ab, und brachten sie zu Aharon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'Und er nahm sie von ihrer Hand und bildete es mit dem Meißel und machte es zu einem gegossenen Kalb. Und sie sprachen: Dies sind deine Götter, Israel, die dich aus Ägyptenland heraufgebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'Und Aharon sah es, und baute einen Altar vor ihm, und Aharon rief aus und sprach: Morgen ist ein Fest für Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'Und früh am morgenden Tag standen sie auf und opferten Brandopfer auf und brachten Friedensopfer herbei, und das Volk setzte sich zu essen und zu trinken, und standen auf zum Spiel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Und Jehovah redete zu Mose: Geh, steig hinab; denn verderblich handelt dein Volk, das du aus Ägyptenland heraufgebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Eilends sind sie von dem Wege gewichen, den Ich ihnen geboten hatte. Sie haben sich ein gegossen Kalb gemacht und haben es angebetet und ihm geopfert, und gesagt: Dies sind deine Götter, Israel, die dich aus Ägyptenland heraufgebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'Und Jehovah sprach zu Mose: Ich habe dieses Volk gesehen, und siehe, es ist ein hartnäckiges Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'Und nun laß Mich bleiben, daß Mein Zorn gegen sie entbrenne, und Ich sie verzehre. Dich aber will Ich zu einer großen Völkerschaft machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Und Mose flehte vor dem Angesicht Jehovahs, seines Gottes, und sprach: Warum soll Dein Zorn entbrennen, Jehovah, wider Dein Volk, das Du mit großer Kraft und starker Hand aus Ägyptenland heraufgebracht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Warum sollen die Ägypter sprechen und sagen: Zum Übel hat Er sie herausgebracht, um sie auf den Bergen zu erwürgen und vom Boden sie wegzutilgen? Kehre zurück vom Entbrennen Deines Zorns, und laß Dich des Bösen über Dein Volk gereuen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Gedenke Abrahams, Isaaks und Israels, Deiner Knechte, denen Du geschworen bei Dir selbst, und zu denen Du geredet hast: Euren Samen will Ich mehren wie die Sterne des Himmels, und all dieses Land, davon Ich sagte, will Ich eurem Samen geben, und sie sollen es ewiglich erben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'Und Jehovah ließ Sich gereuen des Bösen, wovon Er geredet hatte, Seinem Volke anzutun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'Und Mose wandte sich und ging vom Berg hinab, und die zwei Tafeln des Zeugnisses waren in seiner Hand, Tafeln von beiden Seiten her beschrieben. Von dieser und von der anderen Seite waren sie geschrieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'Und die Tafeln waren von Gott gemacht. Und das Geschriebene war von Gott geschrieben und auf die Tafeln eingegraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'Und Jehoschuah hörte die Stimme des Volkes in seinem Jubeln und sprach zu Mose: Die Stimme des Kriegs ist im Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'Und er sprach: Das ist nicht Stimme des Geschreis des Obsiegens, noch die Stimme des Geschreis des Unterliegens; solches ist wie die Stimme des Elends, was ich höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'Und es geschah, als er dem Lager nahte und das Kalb und die Reigentänze sah, da entbrannte Moses Zorn, und er warf die Tafeln aus seinen Händen und zerbrach sie unten am Berg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'Und er nahm das Kalb, das sie gemacht hatten und verbrannte es im Feuer, und zermahlte es, bis daß es fein war, und sprengte es auf das Wasser und ließ die Söhne Israels es trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'Und Mose sprach zu Aharon: Was hat dir dieses Volk getan, daß du eine so große Sünde über dasselbe gebracht hast?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Und Aharon sprach: Es entbrenne nicht der Zorn meines Herrn; du weißt, daß dieses Volk im Bösen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Und sie sprachen zu mir: Mache uns Götter, daß sie vor uns hergehen; denn der Mose da, der Mann, der uns von Ägyptenland heraufgebracht: wir wissen nicht, was ihm geschehen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Und ich sprach zu ihnen: Wer Gold hat, der reiße es sich ab. Und sie gaben es mir, und ich warf es ins Feuer, und dieses Kalb kam heraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'Und Mose sah, daß das Volk losgelassen war, da es Aharon losgelassen, so daß sie zum Gespötte würden denen, die wider sie aufständen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Und Mose stand am Tor des Lagers und sprach: Her zu mir, wer Jehovahs ist! Und es versammelten sich alle Söhne Levis zu ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'Und er sprach zu ihnen: So spricht Jehovah, der Gott Israels: Jeder von euch lege sein Schwert an seine Hüfte und gehe hin durch das Lager und kehre wieder von Tor zu Tor und erwürge jeder Mann seinen Bruder, und jeder Mann seinen Genossen, und jeder Mann seinen Nächsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'Und die Söhne Levis taten nach dem Worte des Mose, und es fielen von dem Volk an selbigem Tag bei dreitausend Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'Und Mose sprach: Füllet heute eure Hand dem Jehovah, weil jeder wider seinen Sohn und wider seinen Bruder war, auf daß heute ein Segen über euch gegeben werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'Und es geschah am morgenden Tag, daß Mose zu dem Volke sprach: Ihr habt eine große Sünde gesündigt, und nun will ich zu Jehovah hinaufgehen. Vielleicht daß ich eure Sünde versöhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Und Mose kehrte zu Jehovah zurück und sprach: Ach, dieses Volk hat eine große Sünde gesündigt, und sich Götter aus Gold gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'Und nun, möchtest Du doch ihnen ihre Sünde vergeben, wo nicht, so wische mich doch aus Deinem Buche, das Du geschrieben hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'Und Jehovah sprach zu Mose: Wer gegen Mich gesündigt hat, den werde Ich von Meinem Buche wischen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'Und nun geh, führe das Volk, wohin Ich dir gesagt habe, siehe, Mein Engel wird vor dir hergehen; aber am Tage Meiner Heimsuchung werde Ich ihre Sünde an ihnen heimsuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'Und Jehovah schlug das Volk darüber, daß sie das Kalb machten, das Aharon gemacht hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'Und Jehovah redete zu Mose: Geh, zieh hinauf von hinnen, du und das Volk, das du aus Ägyptenland heraufgebracht hast, in das Land, von dem Ich dem Abraham, dem Isaak und dem Jakob geschworen habe und gesagt: Deinem Samen will Ich es geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'Und Ich will einen Engel vor dir hersenden, und vertreiben den Kanaaniter, den Amoriter und den Chethiter und den Pherisiter, den Chiviter und den Jebusiter;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'In ein Land, da Milch und Honig fließt; denn Ich werde nicht in deiner Mitte hinaufziehen, weil du ein hartnäckiges Volk bist, Ich möchte dich sonst verzehren auf dem Wege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'Und das Volk hörte das böse Wort, und sie trauerten, und keiner legte seinen Schmuck an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Und Jehovah sprach zu Mose: Sprich zu den Söhnen Israels: Ein hartnäckiges Volk seid ihr. In einem Augeblick, so Ich in deiner Mitte hinaufzöge, würde Ich dich verzehren. Und nun nimm deinen Schmuck von dir herunter, daß Ich wisse, was Ich mit dir tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'Und die Söhne Israels rissen sich ihren Schmuck vor dem Berge Horeb ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'Und Mose nahm das Zelt und schlug es außerhalb des Lagers für sich auf, fern von dem Lager, und nannte es Versammlungszelt; und es geschah, daß jeder, der Jehovah fragen wollte, zum Versammlungszelt außerhalb des Lagers hinausging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'Und es geschah, wenn Mose hinausging zum Zelt, stand alles Volk auf, und jeder Mann stellte sich an den Eingang seines Zeltes; und sie blickten Mose nach, bis er in das Zelt eingegangen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Und es geschah, wenn Mose in das Zelt einging, kam die Wolkensäule herab und stand am Eingang des Zeltes und redete mit Mose.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'Und alles Volk sah die Wolkensäule am Eingang des Zeltes stehen, und das ganze Volk stand auf und verbeugte sich, jeder Mann am Eingang seines Zeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'Und Jehovah redete zu Mose von Angesicht zu Angesicht, wie ein Mann zu seinem Genossen redet; und er kehrte in das Lager zurück; und Jehoschuah, sein Diener, Nuns Sohn, der Jüngling, wich nicht aus des Zeltes Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'Und Mose sprach zu Jehovah: Siehe, Du sprichst zu mir: Bringe dieses Volk hinauf, und hast mich nicht wissen lassen, wen Du mit mir senden willst, und hast doch gesagt: Ich kenne dich beim Namen, und du hast auch Gnade in Meinen Augen gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Und nun, wenn ich doch Gnade in Deinen Augen gefunden habe, so laß mich doch wissen Deinen Weg, auf daß ich Dich kenne, weil ich Gnade gefunden in Deinen Augen, und siehe, daß Dein Volk ist diese Völkerschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'Und Er sprach: Mein Angesicht soll gehen, und Ich werde dich zur Ruhe bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'Und er sprach zu Ihm: Wenn Dein Angesicht nicht geht, so bringe uns nicht von dannen hinauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'Und woran soll dann erkannt werden, daß ich in Deinen Augen Gnade gefunden, ich und Dein Volk? Wenn nicht daran, daß Du mit uns gehst, und daß wir, ich und Dein Volk, ausgezeichnet werden vor allem Volke, das auf dem Boden ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'Und Jehovah sprach zu Mose: Auch dieses Wort, das du geredet, will Ich tun; denn du hast Gnade in Meinen Augen gefunden, und Ich kenne dich beim Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'Und er sprach: Laß mich doch Deine Herrlichkeit sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'Und Er sprach: Ich will alle Meine Güte vor deinem Angesicht vorübergehen lassen, und den Namen Jehovahs anrufen vor dir. Und Ich bin gnädig, wem Ich gnädig bin, und erbarme Mich, wessen Ich Mich erbarme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'Und Er sprach: Mein Angesicht vermagst du nicht zu sehen; denn nicht sieht Mich ein Mensch und lebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'Und Jehovah sprach: Siehe, es ist ein Ort bei Mir, und du sollst auf den Fels dich stellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'Und es wird geschehen, wenn Meine Herrlichkeit vorüberzieht, so will Ich dich in die Kluft des Felsens stellen und Meine Hand über dich decken, bis Ich vorübergezogen bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Und Ich will Meine Hand wegnehmen, daß du Mich von hinten sehest, aber Mein Angesicht soll man nicht sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'Und Jehovah sprach zu Mose: Haue dir zwei steinerne Tafeln zu, wie die ersten, und Ich will auf die Tafeln die Worte schreiben, die auf den ersten Tafeln waren, die du zerbrochen hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'Und sei bereit für den Morgen, und steig am Morgen auf den Berg Sinai und stelle dich Mir daselbst auf des Berges Spitze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Und niemand steige mit dir hinauf, und soll sich auch niemand auf dem Berge sehen lassen. Auch Kleinvieh und Rind soll nicht vor diesem Berg weiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'Und er hieb zwei steinerne Tafeln zu, gleich den ersten, und Mose machte sich früh am Morgen auf und stieg auf den Berg Sinai, wie Jehovah ihm geboten hatte, und nahm die zwei steinernen Tafeln in seine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'Und Jehovah kam in der Wolke herab und stellte Sich zu ihm daselbst und rief Jehovahs Namen an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'Und Jehovah zog vorüber vor seinem Angesicht und rief: Jehovah, Jehovah, Gott, erbarmungsvoll und gnädig, langmütig und groß an Barmherzigkeit und Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'Bewahrend Barmherzigkeit Tausenden, tragend Missetat und Übertretung und Sünde, aber nicht ungestraft lassend, heimsuchend die Missetat der Väter an den Söhnen und an der Söhne Söhnen bis ins dritte und vierte Glied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'Und Mose eilte und verneigte sich zur Erde und betete an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'Und sprach: Wenn ich doch Gnade fände in Deinen Augen, o Herr, daß der Herr doch in unserer Mitte zöge. Denn es ist ein hartnäckiges Volk; aber vergib unsrer Missetat und unsrer Sünde und mach uns zum Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'Und Er sprach: Siehe, Ich schließe einen Bund; vor all deinem Volke will Ich Wunder tun, dergleichen nicht geschaffen sind auf der ganzen Erde und unter allen Völkerschaften; und sehen wird das ganze Volk, in dessen Mitte du bist, das Tun Jehovahs; denn furchtbar wird sein, was Ich mit dir tun werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Halte dir, was heut Ich dir gebiete. Siehe, Ich vertreibe vor dir den Amoriter und den Kanaaniter, und den Chethiter und den Pherisiter und den Chiviter und den Jebusiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Hüte dich, daß du nicht einen Bund mit dem Einwohner des Landes schließest, in das du kommst; auf daß er nicht zum Fallstrick in deiner Mitte werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'Darum sollt ihr ihre Altäre einreißen und ihre Bildsäulen zerbrechen und ihre Ascheren ausrotten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'Denn du sollst keinen anderen Gott anbeten; denn Jehovah, Eiferer ist Sein Name, ein eifriger Gott ist Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'Daß du keinen Bund schließest mit dem Einwohner des Landes, und sie nachbuhlen ihren Göttern und opfern ihren Göttern, und er dann dich rufe und du essest von ihrem Opfer,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'Und nehmest von ihren Töchtern für deine Söhne, und dann ihre Töchter ihren Göttern nachbuhlen, und machen deine Söhne ihren Göttern nachbuhlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Mache dir keine gegossenen Götter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Das Fest des Ungesäuerten sollst du halten, sieben Tage Ungesäuertes essen, wie Ich dir geboten habe, zur bestimmten Zeit des Monats Abib; denn im Monat Abib bist du aus Ägypten ausgegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Alles, was die Mutter bricht, ist Mein, und von all deiner Viehherde sollst du das Männliche geben, alles Erstgeborene von Ochs und von Kleinvieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Und das Erstgeborene des Esels sollst du mit einem Lamme einlösen; und wenn du es nicht einlösest, so brich ihm das Genick. Jeden Erstgeborenen deiner Söhne sollst du lösen; und vor Meinem Angesicht soll man nicht leer erscheinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Sechs Tage sollst du arbeiten, aber am siebenten Tage feiern; mit dem Pflügen und dem Ernten sollst du feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'Und das Fest der Woche sollst du bei dir halten mit den Erstlingen der Weizenernte, und das Fest der Einsammlung im Verlaufe des Jahres.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Dreimal des Jahres erscheine all dein Männliches vor dem Angesicht des Herrn Jehovah, des Gottes Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Denn Ich will die Völkerschaften vor deinem Angesicht austreiben und deine Grenze erweitern, und niemand soll dein Land begehren, wenn du hinaufgehst, dreimal im Jahre das Angesicht Jehovahs, deines Gottes, zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Du sollst nicht über Gesäuertem das Blut Meines Opfers schlachten, noch soll über Nacht bis zum Morgen bleiben das Opfer des Passahfestes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Das Erste der Erstlinge deines Bodens sollst du in das Haus Jehovahs deines Gottes bringen. Du sollst nicht kochen das Böcklein in der Milch seiner Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'Und Jehovah sprach zu Mose: Schreibe dir diese Worte auf; denn nach dem Ausspruch dieser Worte schließe Ich einen Bund mit dir und mit Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'Und er war dort mit Jehovah vierzig Tage und vierzig Nächte, er aß kein Brot und trank kein Wasser; und Er schrieb die Worte des Bundes, die Zehn Worte, auf die Tafeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'Und es geschah, als Mose vom Berge Sinai herabkam, und die zwei Tafeln des Zeugnisses in Moses Hand waren, bei seinem Herabkommen vom Berg, daß Mose nicht wußte, daß die Haut seines Angesichts davon strahlte, daß er mit Ihm geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Und Aharon und alle Söhne Israels sahen Mose, und siehe, die Haut seines Angesichts strahlte, und sie fürchteten sich, zu ihm herzutreten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'Und Mose rief ihnen zu, und Aharon und alle die Fürsten in der Gemeinde kehrten zurück, und Mose redete zu ihnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'Und nachher traten alle Söhne Israels herzu und er gebot ihnen alles, was Jehovah mit ihm auf dem Berge Sinai geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'Und Mose vollendete mit ihnen zu reden, und er tat eine Hülle über sein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Und wenn Mose hineinging vor Jehovah, mit Ihm zu reden, nahm er die Hülle ab, bis er herausging; und er ging heraus und redete zu den Söhnen Israels, was ihm geboten war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'Und die Söhne Israels sahen das Angesicht Moses, daß die Haut von Moses Ange- sicht strahlte, und Mose tat die Hülle zurück über sein Angesicht, bis er hineinging, mit Ihm zu reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'Und Mose versammelte die ganze Gemeinde der Söhne Israels und sprach zu ihnen: Das sind die Worte, die Jehovah geboten hat, sie zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Sechs Tage soll die Arbeit getan werden, und am siebenten Tag sei euch ein heiliger Sabbath des Feierns für Jehovah; jeder, der an ihm Arbeit tut, soll sterben:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Ihr sollt kein Feuer in allen euren Wohnungen brennen lassen am Sabbathtag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Und Mose sprach zur ganzen Gemeinde der Söhne Israels und sagte: Dies ist das Wort, das Jehovah geboten hat und gesagt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Nehmet von euch eine Hebe für Jehovah, ein jeder, der freiwilligen Herzens ist, bringe als Hebe dem Jehovah: Gold und Silber und Erz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'Und blauen und roten Purpur, und Scharlach, doppelt gefärbt, und Byssus und Ziegenhaar;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'Und rote Widderfelle und Dachsfelle und Schittimholz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'Und Öl für den Leuchter, und Gewürze zum Salböl und zum Räuchwerk der Spezereien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'Und Onychsteine und Füllungssteine für das Ephod und für das Brustschildlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'Und jeder unter euch, der weisen Herzens ist, komme und mache alles, was Jehovah geboten hat:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'Die Wohnung, ihr Zelt und ihre Decke; ihre Haken und ihre Bretter, ihre Riegel, ihre Säulen und ihre Untersätze;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'Die Lade und ihre Stangen, den Gnadenstuhl und den Vorhang der Decke;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'Den Tisch und seine Stangen und all seine Geräte und das Schaubrot;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'Und den Leuchter der Beleuchtung und seine Geräte und seine Lampen und das Öl zur Beleuchtung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'Und den Räuchaltar und seine Stangen und das Salböl und das Räuchwerk der Spezereien; und die Decke am Eingang für den Eingang zur Wohnung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'Den Brandopferaltar und sein ehernes Gitter, seine Stangen und all seine Geräte; das Becken und sein Gestell;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'Die Behänge des Vorhofs, seine Säulen und seine Untersätze, und die Decke zum Tor des Vorhofs;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'Die Pflöcke der Wohnung und die Pflöcke des Vorhofs und ihre Seile;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'Die Dienstkleider zum Dienst tun im Heiligtum; die heiligen Kleider für Aharon den Priester und die Kleider seiner Söhne, den Priesterdienst zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'Und sie gingen hinaus, die ganze Gemeinde der Söhne Israels von Mose.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'Und sie kamen, jeder Mann, den sein Herz erhob, und jeder, der seinen Geist freiwillig machte; sie brachten die Hebe Jehovahs zur Arbeit des Versammlungszeltes und für all seinen Dienst und für die heiligen Kleider.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'Und es kamen die Männer samt den Weibern, alle mit freiwilligem Herzen, und brachten Haften und Ohrringe und Ringe und Gürtel, allerlei Gerät von Gold, und wie jeder Mann ein Webeopfer von Gold Jehovah bringen wollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'Und jeder Mann, bei dem sich blauer und roter Purpur und doppelt gefärbter Scharlach und Byssus und Ziegenhaar fand, und rote Widderfelle und Dachsfelle, brachte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Jeder, der eine Hebe an Silber und Erz hob, brachte es als Hebeopfer Jehovahs, und jeder, bei dem sich Schittimholz zu irgendwelchem Dienstwerk fand, brachte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'Und alle Weiber, die weisen Herzens waren, spannen mit ihren Händen und brachten das Gesponnene, blauen und roten Purpur, doppelt gefärbten Scharlach und Byssus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'Und alle Weiber, die ihr Herz mit Weisheit erhob, spannen Ziegenhaar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Und die Fürsten brachten Onychsteine und Füllungssteine für das Ephod und das Brustschildlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'Und Gewürz und Öl für Beleuchtung und für das Öl zum Salben, und für das Räuchwerk der Spezereien;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Alles, Mann und Weib, die ihr Herz freiwillig machte, brachten für jegliches Werk, das Jehovah zu machen geboten hatte, durch Moses Hand; das brachten die Söhne Israels dem Jehovah als freiwillige Gabe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'Und Mose sprach zu den Söhnen Israels: Sehet, Jehovah hat mit Namen gerufen Bezaleel, den Sohn Uris, des Sohnes Churs, vom Stamme Judah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'Und ihn erfüllt mit dem Geiste Gottes, mit Weisheit, mit Einsicht und mit Kenntnis und in aller Arbeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'Und Gedanken auszudenken, um es in Gold und in Silber und in Erz zu machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'Und im Steinschneiden zum Einfüllen, und im Holzschneiden, um zu machen alle Arbeit, die er ausgedacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Und zu unterweisen gab Er ihm ins Herz, ihm und Oholiab, dem Sohne Achisamachs, vom Stamme Dan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Er hat sie erfüllt mit Weisheit des Herzens, zu machen alle Arbeit des Werkmannes und des Ausdenkers und des Buntwirkers in Purpurblau und Purpurrot, in doppelt gefärbtem Scharlach und in Byssus, und des Webers, daß sie allerlei Arbeit tun und Gedanken ausdenken mögen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'Und es tat Bezaleel und Oholiab und alle Männer weisen Herzens, denen Jehovah Weisheit und Einsicht gegeben, um zu wissen, wie sie jegliche Arbeit zum Dienste des Heiligtums nach allem, was Jehovah geboten hatte, machen sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'Und Mose rief Bezaleel und Oholiab und jeglichen Mann weisen Herzens, denen Jehovah Weisheit ins Herz gegeben hatte, jeden, den sein Herz erhob, sich zu nahen zur Arbeit, um sie zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'Und sie holten sich von Mose alle Hebe, welche die Söhne Israels brachten, zu machen die Arbeit zum Dienste des Heiligtums; und sie brachten ihm von Morgen zu Morgen noch freiwillige Gaben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'Und es kamen alle Weisen, die alle Arbeit des Heiligtums machten, Mann für Mann von seinem Werk, das er machte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'Und sprachen zu Mose und sagten: Das Volk bringt mehr denn genug zum Dienst der Arbeit, die Jehovah geboten hat zu machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Und Mose gebot, daß man eine Stimme im Lager hinziehen lasse und sage: Mann und Weib soll keine Arbeit weitermachen für die Hebe des Heiligtums. Und das Volk wurde abgehalten vom Bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Denn der Arbeit war genug für jegliche Arbeit, die getan werden sollte, und war übrig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Und alle, die weisen Herzens waren, machten mit denen, welche die Arbeit taten, die Wohnung aus zehn Teppichen von gezwirntem Byssus und blauem und rotem Purpur und Scharlach, doppelt gefärbt, mit Cheruben, ein Werk des Künstlers machte man sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Die Länge des einen Teppichs war achtundzwanzig Ellen und vier Ellen die Breite eines Teppichs; alle Teppiche hatten ein Maß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'Und er fügte fünf Teppiche zusammen, je einen an den andern, und fügte fünf Teppiche zusammen, eins an das andere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'Und machte Schleifen von blauem Purpur an den Saum des einen Teppichs am Ende der Zusammenfügung. So tat er am Saume des äußersten Teppichs bei der zweiten Zusammenfügung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Fünfzig Schleifen machte er an den einen Teppich und fünfzig Schleifen machte er an das Ende des Teppichs an der zweiten Zusammenfügung, so daß die Schleifen einander gegenüber waren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'Und er machte fünfzig goldene Haken, und durch die Haken fügte er die Teppiche zusammen, einen an den anderen, so daß die Wohnung eins wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'Und er machte Teppiche von Ziegenhaar für das Zelt über die Wohnung, elf Teppiche machte er sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Die Länge eines Teppichs war dreißig Ellen, und vier Ellen die Breite des einen Teppichs. Die elf Teppiche hatten ein Maß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'Und er fügte fünf Teppiche zusammen besonders, und sechs Teppiche besonders;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'Und machte fünfzig Schleifen an den Saum des äußersten Teppichs an die Zusammenfügung, und fünfzig Schleifen machte er an den Saum des Teppichs an der zweiten Zusammenfügung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'Und er machte fünfzig Haken von Erz, um das Zelt zusammenzufügen, daß es eins wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'Und machte eine Decke für das Zelt von roten Widderfellen, und eine Decke von Dachsfellen darüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'Und er machte Bretter von Schittimholz für die Wohnung; aufrecht zu stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Zehn Ellen die Länge des Brettes, und eine Elle und eine halbe Elle die Breite eines Brettes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Zwei Zapfen für ein Brett fügend das eine an das andere machte er an allen Brettern der Wohnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'Und er machte die Bretter für die Wohnung, zwanzig Bretter für die Ecke gegen Mittag südwärts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'Und vierzig silberne Untersätze machte er unter die zwanzig Bretter, zwei Untersätze unter ein Brett für seine zwei Zapfen, und zwei Untersätze unter das andere Brett für seine zwei Zapfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'Und für die zweite Seitenwand der Wohnung in die Ecke gegen Mitternacht machte er zwanzig Bretter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'Und ihre vierzig Untersätze von Silber, zwei Untersätze unter das eine Brett und zwei Untersätze unter das eine Brett.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'Und für die Hinterseite der Wohnung gegen das Meer hin machte er sechs Bretter;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'Und zwei Bretter machte er für die Eckstücke der Wohnung an der Hinterseite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'Und sie waren zweifach von unten an und zugleich ganz bis an die Spitze, an dem einen Ring. So tat er es mit beiden, an den beiden Eckstücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Und acht Bretter waren es, und ihre Untersätze von Silber, sechzehn Untersätze, zwei Untersätze und zwei Untersätze unter einem Brett.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'Und er machte Riegel von Schittimholz, fünf für die Bretter einer Seitenwand der Wohnung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'Und fünf Riegel für die Bretter der zweiten Seitenwand der Wohnung, und fünf Riegel für die Bretter der Wohnung auf der Hinterseite gegen das Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'Und den mittleren Riegel machte er so, daß er von Ende zu Ende mitten hinlief an den Brettern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'Und die Bretter überzog er mit Gold und machte ihre Ringe von Gold, als Behälter für die Riegel, und die Riegel überzog er mit Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'Und den Vorhang machte er von blauem und rotem Purpur und Scharlach, doppelt gefärbt und gezwirntem Byssus. Als Werk des Kunstwirkers machte er es mit Cheruben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'Und machte dafür vier Säulen von Schittimholz und überzog sie mit Gold; ihre Nägel waren von Gold, und vier silberne Untersätze goß er für sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'Und für den Eingang zum Zelt machte er eine Decke von blauem und rotem Purpur und Scharlach, doppelt gefärbt und gezwirntem Byssus, das Werk eines Buntwirkers;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'Und ihre fünf Säulen und ihre Nägel; und überzog ihre Köpfe und Umgürtungen mit Gold, und ihre fünf Untersätze waren von Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'Und Bezaleel machte die Lade von Schittimholz, zwei Ellen und eine halbe ihre Länge, und eine Elle und eine halbe ihre Breite und eine Elle und eine halbe ihre Höhe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'Und überzog sie mit reinem Gold von innen und von außen, und machte ihr einen goldenen Kranz ringsumher;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'Und goß ihr vier goldene Ringe auf ihre vier Ecken, und zwei Ringe auf ihre eine Seitenwand und zwei auf ihre zweite Seitenwand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'Und er machte Stangen von Schittimholz und überzog sie mit Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'Und er brachte die Stangen in die Ringe an der Seitenwand der Lade, um die Lade zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'Und machte den Gnadenstuhl von reinem Gold, zwei Ellen und eine halbe ihre Länge und eine Elle und eine halbe ihre Breite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'Und er machte zwei Cherube von Gold, in getriebener Arbeit aus den beiden Enden des Gnadenstuhls machte er sie;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'Einen Cherub von dem einen Ende und einen Cherub von dem anderen Ende an dem Gnadenstuhl machte er die Cherube aus seinen zwei Enden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'Und die Cherube breiteten die zwei Flügel darüber aus und deckten den Gnadenstuhl mit ihren Flügeln, und ihre Angesichter waren gegeneinander; zu dem Gnadenstuhl waren die Angesichter der Cherube.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Und den Tisch machte er von Schittimholz, zwei Ellen seine Länge und eine Elle seine Breite und eine Elle und eine halbe seine Höhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'Und er überzog ihn mit reinem Gold, und machte ihm einen goldenen Kranz ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'Und er machte eine Randleiste an ihm ringsumher eine Hand breit, und einen goldenen Kranz machte er an seine Randleiste ringsumher;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'Und goß für ihn vier goldene Ringe, und tat die Ringe an die vier Ecken, die bei seinen vier Füßen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Zunächst der Randleiste waren die Ringe, als Behälter für die Stangen, den Tisch damit zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'Und die Stangen machte er aus Schittimholz und überzog sie mit Gold, um den Tisch zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'Und er machte die Gefäße auf den Tisch, seine Schüsseln und seine Platten, und seine Becher und die Trankopferschalen, womit er gedeckt wird, aus reinem Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Und den Leuchter machte er von reinem Gold; in getriebener Arbeit machte er den Leuchter, sein Schaft und seine Röhre, seine Kelche, seine Knäufe und seine Blumen sollen aus ihm sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'Und sechs Röhren gingen von seinen Seiten aus; drei Röhren des Leuchters von seiner einen Seite, und drei Röhren des Leuchters von seiner zweiten Seite;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Drei mandelblütförmige Kelche waren an der einen Röhre, Knauf und Blume, und drei mandelblütförmige Kelche an der anderen Röhre, Knauf und Blume; so bei den sechs Röhren, die von dem Leuchter ausgingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'Und an dem Leuchter waren vier mandelblütförmige Kelche, seine Knäufe und seine Blumen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'Und ein Knauf war unter zwei Röhren aus ihm, und ein Knauf unter zwei Röhren aus ihm, und ein Knauf unter zwei Röhren aus ihm, für die sechs Röhren, die aus ihm ausgingen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Ihre Knäufe und ihre Röhren waren aus ihm, sein Ganzes war ein Getriebenes aus reinem Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'Und er machte seine sieben Lampen, und seine Lichtputzen und seine Löschnäpfe von reinem Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Aus einem Talent reinen Goldes machte er ihn und all seine Geräte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'Und er machte den Räuchaltar von Schittimholz, eine Elle seine Länge, und eine Elle seine Breite ins Gevierte, und zwei Ellen hoch. Aus ihm waren seine Hörner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'Und er überzog ihn mit reinem Gold, sein Dach und seine Wände ringsum und seine Hörner, und machte ihm einen Kranz von Gold ringsumher;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'Und zwei Ringe von Gold machte er ihm unter seinen Kranz an seinen beiden Seitenwänden, an seinen Seiten, als Behälter für die Stangen, um ihn damit zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'Und die Stangen machte er von Schittimholz und überzog sie mit Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'Und machte das heilige Salböl und reines Räucherwerk der Spezereien, ein Werk des Salbenmischers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'Und er machte den Brandopferaltar aus Schittimholz, fünf Ellen seine Länge, und fünf Ellen seine Breite ins Gevierte, und drei Ellen seine Höhe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'Und machte seine Hörner auf seine vier Ecken; aus ihm selbst waren seine Hörner, und er überzog ihn mit Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'Und er machte alle Geräte des Altars: die Töpfe und die Schaufeln und Sprengbecken, die Fleischgabeln und die Kohlpfannen; alle seine Gerätschaften machte er von Erz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Und machte am Altar ein Gitter, ein Netzwerk von Erz, unter seiner Einfassung, von unten auf bis an die Mitte desselben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'Und goß vier Ringe an die vier Enden des ehernen Gitters, als Behälter für die Stangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Und die Stangen machte er von Schittimholz und überzog sie mit Erz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'Und brachte die Stangen in die Ringe an den Seitenwänden des Altars, diesen damit zu tragen; hohl, von Brettern machte er ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'Und das Becken machte er von Erz, und sein Gestell von Erz in Sicht der Ausdrückenden, die da ausdrückten vor den Eingang des Versammlungszeltes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'Und machte den Vorhof zur Mittagsecke südwärts, die Umhänge des Vorhofs von gezwirntem Byssus hundert Ellen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'Ihre zwanzig Säulen und deren zwanzig Untersätze von Erz; die Nägel der Säulen und deren Umgürtungen von Silber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'Und auf der Mitternachtecke hundert Ellen: ihre zwanzig Säulen, und ihre zwanzig Untersätze von Erz, die Nägel der Säulen und ihre Umgürtungen von Silber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'Und auf der Abendecke fünfzig Ellen Umhänge: ihre zehn Säulen und ihre zehn Untersätze, die Nägel der Säulen und ihre Umgürtungen von Silber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'Und auf der Vorderecke gegen Aufgang fünfzig Ellen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'Fünfzehn Ellen Umhänge auf dem einen Flügel: ihre drei Säulen und ihre drei Untersätze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'Und auf dem zweiten Flügel hier und dort am Tor des Vorhofs fünfzehn Ellen Umhänge, ihre drei Säulen und ihre drei Untersätze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Alle Umhänge des Vorhofs ringsum von gezwirntem Byssus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'Und die Untersätze zu den Säulen von Erz, die Nägel der Säulen und ihre Umgürtungen von Silber, und der Überzug ihrer Köpfe von Silber, und waren dieselben mit Silber umgürtet, alle Säulen des Vorhofs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'Und die Decke am Tor des Vorhofs war Buntwirkerarbeit von blauem und rotem Purpur und doppelt gefärbtem Scharlach und gezwirntem Byssus, und zwanzig Ellen lang und bei fünf Ellen hoch, in der Breite gemäß den Umhängen des Vorhofs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'Und ihre vier Säulen und ihre vier Untersätze waren von Erz; ihre Nägel von Silber, und deren Köpfe und Umgürtungen mit Silber überzogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'Und alle Pflöcke für die Wohnung und für den Vorhof ringsum waren von Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'Das ist die Musterung für die Wohnung, die Wohnung des Zeugnisses, die gemustert wurden nach Moses Befehl, zum Dienste der Leviten, durch die Hand Ithamars, des Sohnes Aharons, des Priesters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Und Bezaleel, der Sohn Uris, des Sohnes Churs, vom Stamme Judah, machte alles, das Jehovah dem Mose geboten hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'Und mit ihm Oholiab, der Sohn Achisamachs vom Stamme Dan, Werkmann und Ausdenker und Buntwirker in blauem und rotem Purpur, und in doppelt gefärbtem Scharlach und Byssus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Alles Gold, aus dem gemacht wurde die Arbeit für die ganze Arbeit des Heiligtums - und es war das Gold der Webe - war neunundzwanzig Talente und siebenhundertdreißig Schekel nach dem Schekel des Heiligtums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Und das Silber der Gemusterten der Gemeinde war hundert Talente, und tausend und siebenhundertfünfundsiebzig Schekel nach dem Schekel des Heiligtums;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'Ein Beka auf den Kopf, ein halber Schekel nach dem Schekel des Heiligtums, von einem jeden, der zu den Gemusterten überging, der zwanzig Jahre und darüber alt war, von sechsmalhundertausend und dreitausend und fünfhundertfünfzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'Und von hundert Talenten Silbers goß man die Untersätze des Heiligtums und die Untersätze des Vorhangs; für hundert Untersätze hundert Talente, ein Talent für einen Untersatz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'Und mit den tausend und siebenhundertfünfundsiebzig machte er die Nägel für die Säulen, und überzog ihre Köpfe und umgürtete sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'Und das Erz der Webe war siebzig Talente und zweitausend und vierhundert Schekel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'Und damit machte er die Untersätze des Eingangs zum Versammlungszelt und den ehernen Altar und das eherne Gitter daran, und alle Geräte des Altars;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'Und die Untersätze des Vorhofs ringsum, und die Untersätze des Tores an dem Vorhof, und alle Pflöcke der Wohnung und alle Pflökke des Vorhofs ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'Und von dem blauen und dem roten Purpur und dem doppelt gefärbten Scharlach machten sie die Dienstkleider für das Diensttun im Heiligtum, und machten die heiligen Kleider für Aharon, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'Und er machte das Ephod von Gold, blauem und rotem Purpur und doppelt gefärbtem Scharlach und gezwirntem Byssus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'Und die Goldplatten schlugen sie breit, und er schnitt sie ab in Fäden, um sie inmitten des blauen und inmitten des roten Purpurs und inmitten des doppelt gefärbten Scharlach und inmitten des Byssus zu tun, mit dem Werke des Denkers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Schulterstücke machten sie daran, die sich zusammenfügten, an ihren beiden Enden fügte man sie zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'Und der Gurt zum Anlegen, der daran war, war aus ihm und wie sein Werk, von Gold, blauem und rotem Purpur und Scharlach, doppelt gefärbt und gezwirntem Byssus, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'Und sie machten die Onychsteine, ringsum in Gold gefaßt, und sie gruben darauf, wie im Siegelstich, nach den Namen der Söhne Israels ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'Und er setzte sie auf die Schulterstücke des Ephod als Gedenksteine für die Söhne Israels, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'Und das Brustschildlein machte er mit dem Werke des Kunstwirkers, wie das Werk des Ephods gemacht war, aus Gold, blauem und rotem Purpur, und doppelt gefärbtem Scharlach und gezwirntem Byssus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Geviert war es, gedoppelt machten sie das Brustschildlein, eine Spanne seine Länge und eine Spanne seine Breite, gedoppelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'Und sie füllten es mit vier Reihen von Steinen; eine Reihe war Rubin, Topas und Karfunkel, die erste Reihe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'Und die zweite Reihe: Chrysopras, Saphir und Diamant.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'Und die dritte Reihe: Lasurstein, Achat und Amethyst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'Und die vierte Reihe: Tharschisch, Onych und Jaspis, ringsum mit Goldeinfassungen in ihren Füllungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'Und die Steine waren nach den Namen der Söhne Israels, zwölf nach ihren Namen; wie Siegel eingegraben mit eines jeden Namen für die zwölf Stämme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'Und an das Brustschildlein machten sie Kettchen am Rande, Flechtwerk von reinem Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'Und sie machten zwei Einfassungen von Gold und zwei Ringe von Gold und setzten die zwei Ringe an die zwei Enden des Brustschildleins.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'Und die zwei Geflechte von Gold taten sie in die zwei Ringe an den Enden des Brustschildleins.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'Und die zwei Enden der zwei Geflechte taten sie in die zwei Einfassungen, und setzten sie an die Schulterstücke des Ephod auf dessen Vorderseite;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'Und machten zwei Ringe von Gold, und setzten sie an die zwei Enden des Brustschildleins an seinen Saum, welcher gegen das Ephod zu einwärts ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Und sie machten zwei goldene Ringe, und setzten sie an die zwei Schulterstücke des Ephod von unten an seiner Vorderseite nächst der Zusammenfügung über dem Gurt des Ephod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'Und sie schnürten das Brustschildlein mit seinen Ringen an die Ringe des Ephod mit einer purpurblauen Schnur, so daß es über dem Gurt des Ephod war und das Brustschildlein sich nicht vom Ephod verrückte, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'Und das Oberkleid des Ephods machte er mit dem Werke des Webers, gänzlich von Purpurblau.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'Und in der Mitte des Oberkleides eine Öffnung, gleich der Öffnung am Panzer, und eine Borte rings um die Öffnung, auf daß es nicht reiße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'Und an die Säume des Oberkleides machten sie Granatäpfel von blauem und rotem Purpur, und von doppelt gefärbtem Scharlach hineingewirkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'Und sie machten Glöcklein von reinem Gold, und setzten die Glöcklein inmitten der Granatäpfel an die Säume des Oberkleides, ringsum inmitten der Granatäpfel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'Ein Glöckchen und ein Granatapfel, ein Glöckchen und ein Granatapfel ringsum an den Säumen des Oberkleides für das Diensttun, wie es Jehovah dem Mose geboten hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'Und sie machten die Leibröcke von Byssus, mit dem Werke des Webers; für Aharon und seine Söhne;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'Und die Tiara von Byssus und den Schmuck der Kopfbünde von Byssus, und die leinenen Beinkleider von gezwirntem Byssus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'Und den Gürtel von gezwirntem Byssus und von blauem und rotem Purpur und doppelt gefärbtem Scharlach in des Buntwirkers Werke, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'Und sie machten das Blatt des heiligen Diadems von reinem Gold, und schrieben darauf mit der Schrift des Siegelstichs: Heiligkeit dem Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'Und taten daran eine Schnur von blauem Purpur, um es oben an die Tiara zu setzen, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Und es ward der ganze Dienst an der Wohnung des Versammlungszeltes vollendet; und die Söhne Israels taten nach allem, was Jehovah dem Mose geboten hatte; also taten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'Und sie brachten die Wohnung zu Mose: das Zelt und all seine Geräte, seine Haken, seine Bretter, seine Riegel, seine Säulen und seine Untersätze;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'Und die Decke von roten Widderfellen, und die Decke von Dachsfellen, und den Vorhang der Decke;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'Die Lade des Zeugnisses und ihre Stangen und den Gnadenstuhl;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'Den Tisch, alle seine Gefäße und das Schaubrot,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'Den reinen Leuchter, seine Lampen, die Lampen zum Anordnen, und alle seine Gefäße, und das Öl der Beleuchtung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'Und den goldenen Altar, und das Salböl, und das Räucherwerk der Spezereien und die Decke zum Eingang des Zeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'Den ehernen Altar und sein Gitter daran von Erz, seine Stangen, und all seine Geräte, das Becken und sein Gestell.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'Die Umhänge des Vorhofs, seine Säulen und seine Untersätze, und die Decke für das Tor des Vorhofs, seine Seile und seine Pflökke, und alle Geräte zum Dienst in der Wohnung für das Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'Dienstkleider für das Diensttun im Heiligtum, die heiligen Kleider für Aharon, den Priester, und die Kleider für seine Söhne zum Priesterdienst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Nach allem, was Jehovah dem Mose geboten hatte, also taten die Söhne Israels allen Dienst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'Und Mose sah all das Werk, und siehe, sie hatten es gemacht, wie Jehovah geboten hatte, also hatten sie es gemacht, und Mose segnete sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Am Tage des ersten Monats, am ersten des Monats sollst du die Wohnung des Versammlungszeltes aufrichten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'Und darein die Lade des Zeugnisses setzen, und über die Lade den Vorhang dekken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'Und den Tisch hereinbringen, und anordnen seine Anordnung: und sollst den Leuchter hereinbringen und seine Lampen aufstecken;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'Und den goldenen Räuchaltar vor die Lade des Zeugnisses stellen, und den Vorhang des Eingangs an die Wohnung setzen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'Und den Brandopferaltar vor den Eingang zur Wohnung des Versammlungszeltes setzen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'Und das Becken zwischen das Versammlungszelt und zwischen den Altar stellen und Wasser darein tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'Und setze den Vorhof ringsum, und tue die Decke an das Tor des Vorhofs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'Und nimm das Salböl und salbe die Wohnung und alles, was in ihr ist, und heilige sie und all ihr Gerät, und sie sei ein Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'Und du sollst den Brandopferaltar salben und alle seine Geräte, und den Altar heiligen, auf daß der Altar allerheiligst sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'Und du sollst das Becken und sein Gestell salben und es heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'Und laß Aharon und seine Söhne sich nahen dem Eingang des Versammlungszeltes, und wasche sie mit dem Wasser;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'Und ziehe dem Aharon die heiligen Kleider an und salbe ihn und heilige ihn, auf daß er Mir Priesterdienst tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Und laß seine Söhne sich nahen, und ziehe ihnen die Leibröcke an;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'Und salbe sie, wie du ihren Vater gesalbt hast, daß sie Mir Priesterdienst tun, und es soll ihnen ihre Salbung zu ewigem Priestertum werden in ihren Geschlechtern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'Und Mose tat nach allem, das ihm Jehovah geboten hatte; also tat er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'Und es geschah im ersten Monat im zweiten Jahr, am ersten des Monats, daß die Wohnung aufgerichtet wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'Und Mose richtete die Wohnung auf, und er setzte ihre Untersätze und stellte ihre Bretter, und tat ihre Riegel daran und richtete ihre Säulen auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'Und er breitete das Zelt aus über die Wohnung, und legte die Decke des Zeltes oben darüber, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'Und er nahm das Zeugnis und tat es in die Lade, und legte die Stangen an die Lade und setzte den Gnadenstuhl oben auf die Lade;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'Und brachte die Lade in die Wohnung, und tat den Vorhang der Decke davor und bedeckte die Lade des Zeugnisses, wie Jehovah Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'Und den Tisch stellte er in das Versammlungszelt an die Seite der Wohnung gegen Mitternacht außerhalb des Vorhangs;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'Und ordnete darauf die Anordnung des Brotes vor Jehovah, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'Und den Leuchter stellte er in das Versammlungszelt gerade gegenüber dem Tisch zur Seite der Wohnung gegen Mittag;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'Und steckte die Lampen auf vor Jehovah, wie dem Mose Jehovah geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'Und den goldenen Altar setzte er in das Versammlungszelt vor den Vorhang;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'Und räucherte darauf mit dem Räuchwerk der Spezereien, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'Und vor den Eingang zur Wohnung tat er die Decke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'Und den Brandopferaltar setzte er an den Eingang zur Wohnung des Versammlungszeltes, und ließ darauf das Brandopfer und das Speiseopfer aufgehen, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'Und das Becken setzte er zwischen das Versammlungszelt und zwischen den Altar und tat Wasser darein zum Waschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'Und Mose und Aharon und seine Söhne wuschen sich ihre Hände und ihre Füße daraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'Wenn sie in das Versammlungszelt eingingen und dem Altare nahten, wuschen sie sich, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'Und er richtete rings um die Wohnung und den Altar den Vorhof auf und in das Tor des Vorhofs tat er die Decke; und Mose vollendete das Werk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'Und die Wolke bedeckte das Versammlungszelt, und die Herrlichkeit Jehovahs füllte die Wohnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'Und Mose vermochte nicht in das Versammlungszelt einzugehen; denn die Wolke lagerte darauf, und die Herrlichkeit Jehovahs füllte die Wohnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'Und wenn die Wolke aufstieg von der Wohnung, brachen die Söhne Israels auf allen ihren Zügen auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Und wenn die Wolke nicht aufstieg, so brachen sie nicht auf, bis zu dem Tage, da sie aufstieg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Denn bei Tag war die Wolke Jehovahs über der Wohnung, und bei Nacht war Feuer darin vor den Augen des ganzen Hauses Israel auf allen ihren Zügen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'Und Jehovah rief Mose und redete mit ihm aus dem Versammlungszelt und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Rede zu den Söhnen Israels und sprich zu ihnen: Der Mensch unter euch, der Jehovah eine Opfergabe darbringen will vom Vieh: vom Rind und vom Kleinvieh sollet ihr eure Opfergabe darbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Wenn seine Opfergabe ein Brandopfer ist vom Rind, soll er ein männliches ohne Fehl darbringen. Er bringe es dar am Eingang zum Versammlungszelt, auf daß er vor Jehovah wohlgefällig sei;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'Und lege seine Hand auf den Kopf des Brandopfers, auf daß es wohlgefällig sei für ihn, und ihm zur Versöhnung sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'Und er schlachte das junge Rind vor Jehovah, und die Söhne Aharons und die Priester sollen das Blut darbringen, und das Blut ringsum auf den Altar sprengen, der am Eingang des Versammlungszeltes ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'Und er enthäute das Brandopfer und zerstücke es in seine Stücke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'Und die Söhne Aharons, des Priesters, sollen Feuer auf den Altar tun und Hölzer auf das Feuer zurechtlegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Und Aharons Söhne, die Priester, sollen die Stücke, den Kopf und das Fett zurechtlegen auf den Hölzern, die auf dem Feuer auf dem Altare sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Und seine Eingeweide und seine Schenkel wasche er im Wasser, und dann zünde der Priester das Ganze auf dem Altare an, zum Brandopfer, zum Feueropfer des Geruchs der Ruhe für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Und ist seine Opfergabe vom Kleinvieh, von den Schafen oder von den Ziegen als Brandopfer, so bringe er ein männliches ohne Fehl dar;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'Und schlachte es vor Jehovah zur Seite des Altars gegen Mitternacht; und Aharons Söhne, die Priester, sollen sein Blut ringsum sprengen auf den Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'Und er zerstücke es in seine Stücke, samt seinem Kopf und seinem Fett, und der Priester lege sie auf den Hölzern auf dem Feuer, das auf dem Altare ist, zurecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Und das Eingeweide und die Schenkel wasche er im Wasser, und der Priester bringe das Ganze dar und zünde es auf dem Altar an. Ein Brandopfer ist es, ein Feueropfer des Geruchs der Ruhe für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Und ist seine Opfergabe für Jehovah ein Brandopfer vom Gevögel, so bringe er von Turteltauben oder jungen Tauben seine Opfergabe dar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'Und der Priester bringe sie dar an dem Altar, und knicke ihr ihren Kopf ab und zünde sie auf dem Altar an, und drücke ihr Blut aus an der Wand des Altars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Ihren Kropf aber mit ihrem Unrat nehme er weg und werfe ihn neben den Altar gegen Osten auf den Ort der Asche;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'Und spalte sie mit ihren Flügeln, trenne sie aber nicht ab, und der Priester zünde sie auf dem Altar an auf den Hölzern, die auf dem Feuer sind; ein Brandopfer sei es, ein Feueropfer des Geruchs der Ruhe für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Und bringt eine Seele Jehovah ein Speiseopfer als Opfergabe dar, so sei Semmelmehl seine Opfergabe, und er gieße Öl darauf, und gebe Weihrauch darauf;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'Und bringe es zu den Söhnen Aharons, den Priestern, und nehme davon eine Handvoll von seinem Semmelmehl und von seinem Öl samt all seinem Weihrauch, und der Priester zünde seinen Gedenkteil auf dem Altar an, als Feueropfer des Geruchs der Ruhe für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Und das übrige von dem Speiseopfer ist für Aharon und für seine Söhne; das Allerheiligste ist es von den Feueropfern Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Und so du darbringst als Opfergabe ein Speiseopfer von Gebackenem im Ofen, so sei es von Semmelmehl, ungesäuerte Kuchen mit Öl vermischt und Fladen des Ungesäuerten, mit Öl gesalbt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Und ist deine Opfergabe ein Speiseopfer auf der Pfanne, so sei es von Semmelmehl, mit Öl vermischt, ungesäuert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Bröckle es in Brocken und gieß Öl darauf; so ist es ein Speiseopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Und ist deine Opfergabe ein Speiseopfer aus der Bratpfanne, so werde es aus Semmelmehl mit Öl gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'Und bringe dein Speiseopfer, das davon gemacht wird, herein für Jehovah, und bring es dem Priester dar, und er bringe sie herbei zum Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'Und der Priester hebe von dem Speiseopfer den Gedenkteil dessen und zünde es auf dem Altar an, als ein Feueropfer des Geruchs der Ruhe für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Und das übrige von dem Speiseopfer ist für Aharon und für seine Söhne; das Allerheiligste ist es von den Feueropfern Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Kein Speiseopfer, das ihr Jehovah darbringet, soll gesäuert sein, denn weder von Gesäuertem, noch von Honig sollt ihr Jehovah ein Feueropfer anzünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Als Opfergabe der Erstlinge dürft ihr sie Jehovah darbringen, aber auf dem Altar sollen sie nicht aufgeopfert werden zu einem Geruch der Ruhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'Und jede Opfergabe deines Speiseopfers sollst du salzen mit Salz, und nicht bei deinem Speiseopfer das Salz des Bundes deines Gottes feiern lassen. Zu deiner jeglichen Opfergabe sollst du Salz darbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'Und wenn du das Speiseopfer der Erstlinge dem Jehovah darbringst, sollst du Ähren, geröstet am Feuer, Geschrotenes von frischen Ähren als Speiseopfer der Erstlinge darbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'Und gib Öl darauf, und lege Weihrauch darauf. Dies ist das Speiseopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'Und der Priester zünde seinen Gedenkteil von seinem Geschrotenen und von seinem Öl auf all seinem Weihrauch an, ein Feueropfer dem Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'Und wenn seine Opfergabe ein Dankopfer ist, wenn er es von dem Rinde darbringt, sei es männlich, sei es weiblich, so soll er es vor Jehovah darbringen ohne Fehl,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'Und seine Hand auf den Kopf seiner Opfergabe legen und es schlachten am Eingang zum Versammlungszelt, und die Söhne Aharons, die Priester, sollen das Blut auf den Altar sprengen ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'Und er bringe von dem Dankopfer ein Feueropfer dar dem Jehovah, das Fett, das die Eingeweide bedeckt und alles Fett über den Eingeweiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'Und die zwei Nieren und das Fett, das darüber, das an den Weichen ist, und das Netz über der Leber, über den Nieren nehme er weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'Und die Söhne Aharons sollen es auf dem Altar auf dem Brandopfer, das auf den Holzstücken auf dem Feuer ist, anzünden, als ein Feueropfer des Geruchs der Ruhe für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Und ist seine Opfergabe vom Kleinvieh als ein Dankopfer für Jehovah, so darf er ein männliches oder ein weibliches darbringen, das ohne Fehl ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Ist es ein Schaf, das er als seine Opfergabe darbringt, und bringt er es dar vor Jehovah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'So lege er seine Hand auf den Kopf seiner Opfergabe, und schlachte es vor dem Versammlungszelt, und die Söhne Aharons sollen sein Blut ringsum auf den Altar sprengen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'Und er bringe von dem Dankopfer als Feueropfer Jehovah dar sein Fett, den ganzen Fettschwanz und das Fett, das die Eingeweide bedeckt, und alles Fett, das auf den Eigneweiden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'Und die zwei Nieren und das Fett daran an den Weichen, und das Netz über der Leber, auf den Nieren nehme er weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'Und der Priester zünde es auf dem Altare an, als Brot des Feueropfers für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Und ist seine Opfergabe eine Ziege, so bringe er sie dar vor Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'Und lege seine Hand auf ihren Kopf und schlachte sie vor dem Versammlungszelt, und Aharons Söhne sollen ihr Blut ringsum auf den Altar sprengen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'Und er bringe dar davon als seine Opfergabe Jehovah als Feueropfer: Das Fett, das die Eingeweide bedeckt und alles Fett, das auf dem Eingeweide ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'Und die zwei Nieren und das Fett darüber, das an den Weichen ist, und das Netz über der Leber auf den Nieren nehme er weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'Und der Priester zünde es an auf dem Altar, ein Brot des Feueropfers zu einem Geruch der Ruhe. Alles Fett sei für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Eine ewige Satzung für eure Geschlechter in all euren Wohnungen sei es: Kein Fett und kein Blut sollt ihr essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Rede zu den Söhnen Israels und sprich: Wenn eine Seele aus Versehen sündigt gegen irgendeines der Gebote Jehovahs, in dem, das nicht hätte getan werden sollen, und davon eines tut;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'So der gesalbte Priester sündigt zur Verschuldung des Volkes, so bringe er für die Sünde, die er gesündigt, Jehovah einen jungen Farren ohne Fehl dar, als Sündopfer für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'Und er bringe den Farren zum Eingang des Versammlungszeltes vor Jehovah, er lege seine Hand auf den Kopf des Farren und schlachte den Farren vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'Und der gesalbte Priester nehme von dem Blut des Farren und bringe es zum Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'Und der Priester tauche seinen Finger in das Blut und spritze von dem Blut siebenmal vor Jehovah vor dem Vorhang des Heiligtums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'Und der Priester gebe von dem Blut auf die Hörner des Altars des Räucherwerks der Spezereien vor Jehovah im Versammlungszelt. Und alles Blut des Farren gieße er an den Grund des Brandopferaltars, der am Eingang zum Versammlungszelt ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'Und hebe alles Fett des Farren des Sündopfers davon empor, das Fett, welches das Eingeweide bedeckt, und alles Fett, das auf dem Eingeweide ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'Und die zwei Nieren und das Fett über ihnen, das an den Weichen ist, und das Netz über der Leber, über den Nieren nehme er weg,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'Wie gehoben wird vom Ochsen des Dankopfers; und der Priester zünde sie auf dem Brandopferaltar an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Und die Haut des Farren und all sein Fleisch samt seinem Kopf und samt seinen Schenkeln, und sein Eingeweide und seinen Mist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'Und den ganzen Farren bringe er hinaus außerhalb des Lagers an einen reinen Ort, wohin man die Fettasche schüttet, und verbrenne ihn auf dem Holz im Feuer. Auf dem Schutt der Fettasche werde er verbrannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'Und wenn die ganze Gemeinde Israel sich versieht, und die Sache verborgen war vor den Augen der Versammlung, und sie taten wider eines der Gebote Jehovahs, was nicht sollte getan werden, und sich damit verschulden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'Und die Sünde bekannt wird, worin sie sich versündigt haben, so bringe die Versammlung einen jungen Farren zum Sündopfer dar, und bringe ihn hinein vor das Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'Und die Ältesten der Gemeinde sollen ihre Hände legen auf den Kopf des Farren vor Jehovah, und man schlachte den Farren vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'Und der gesalbte Priester bringe von dem Blut des Farren zum Versammlungszelt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'Und es tauche der Priester seinen Finger in das Blut und spritze siebenmal vor Jehovah vor dem Vorhang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'Und von dem Blute gebe er auf die Hörner des Altars, der vor Jehovah in dem Versammlungszelte ist, und gieße alles Blut an den Grund des Brandopferaltars am Eingang des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'Und all sein Fett hebe er von ihm und zünde es an auf dem Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'Und er tue mit dem Farren, wie er mit dem Farren des Sündopfers tat; so tue er ihm; und der Priester sühne sie, und es werde ihnen vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'Und den Farren bringe man hinaus außerhalb des Lagers und verbrenne ihn, wie man den ersten Farren verbrannte. Ein Sündopfer der Versammlung sei er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Versündigt sich ein Fürst und tut aus Versehen wider irgendeines der Gebote Jehovahs, seines Gottes, was nicht getan werden sollte, und verschuldigt sich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'Oder so ihm seine Sünde, worin er sich versündigt, bekannt wird, so bringe er als seine Opfergabe einen Ziegenbock, ein Männchen ohne Fehl;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'Und lege seine Hand auf den Kopf des Bockes und schlachte ihn an dem Orte, wo man das Brandopfer schlachtet vor Jehovah. Ein Sündopfer ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'Und der Priester nehme von dem Blute des Sündopfers mit seinem Finger und gebe es auf die Hörner des Brandopferaltars, und sein Blut gieße er an den Grund des Brandopferaltars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'Aber all sein Fett zünde er an auf dem Altar, wie das Fett des Dankopfers, und der Priester sühne für ihn für seine Sünde, und es wird ihm vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Und so eine Seele aus dem Volke des Landes sündigt aus Versehen, indem sie wider eines der Gebote Jehovahs tut, was nicht getan werden sollte, und verschuldigt sich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'Oder so ihm seine Sünde, die er gesündigt, bekannt wird, so bringe er als Opfergabe eine zottige Ziege, ein Weibliches ohne Fehl, für seine Sünde, die er gesündigt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'Und lege seine Hand auf den Kopf des Sündopfers und schlachte das Sündopfer auf dem Orte des Brandopfers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'Und der Priester nehme von ihrem Blut mit seinem Finger und gebe es auf die Hörner des Brandopferaltars, und gieße all ihr Blut an den Grund des Altars;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'Und all ihr Fett nehme er weg, wie das Fett von dem Dankopfer weggenommen wird, und der Priester zünde es auf dem Altar an zu einem Geruch der Ruhe für Jehovah, und der Priester sühne über ihm, und es wird ihm vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Und so er ein Lamm als Opfergabe für die Sünde bringt, so bringe er ein Weibliches ohne Fehl;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'Und er lege seine Hand auf den Kopf des Sündopfers und schlachte es zum Sündopfer an dem Orte, wo man das Brandopfer schlachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'Und der Priester nehme vom Blut des Sündopfers mit dem Finger und gebe es auf die Hörner des Brandopferaltars, und all ihr Blut gieße er an den Grund des Altars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'Und all ihr Fett nehme er ab, wie das Fett von dem Schaf des Dankopfers abgenommen wird, und der Priester zünde es an auf dem Altar, auf den Feueropfern Jehovahs, und der Priester sühne über ihm über seine Sünde, die er gesündigt, und es wird ihm vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'Und wenn eine Seele sündigt, indem sie die Stimme der Verwünschung hört und Zeuge war, sei es, daß sie es sah oder wußte, wenn sie es nicht ansagt, so trägt sie ihre Missetat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'Oder wenn eine Seele irgendein unreines Ding berührt hat, entweder das Aas eines unreinen Wildes oder das Aas eines unreinen Viehs, oder das Aas eines unreinen Kriechtiers, und es ist vor ihm verborgen, so ist er unrein und verschuldet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'Oder wenn er das Unreine eines Menschen, irgendeine Unreinheit von ihm berührt, durch die er unrein geworden, und es ihm verborgen war; wenn er es weiß, so ist er verschuldet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'Oder wenn eine Seele einen Schwur tut, der ihm über die Lippen fährt, er wolle etwas tun, sei es zum Bösen oder zum Guten, nach allem, was dem Menschen mit einem Schwur entfahren mag, und es ihm verborgen war; wenn er es weiß, und er ist verschuldet durch eines dergleichen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'So geschehe es, wenn er verschuldet ist durch eines von diesen, so bekenne er, womit er gesündigt hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'Und bringe sein Schuldopfer zu Jehovah für seine Sünde, die er gesündigt, ein Weibliches vom Kleinvieh, ein Schaf oder eine zottige Ziege zum Sündopfer, und der Priester sühne ihn ob seiner Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Und wenn seine Hand nicht hinreicht genug zu einem Stück Kleinvieh, so bringe er Jehovah für die Schuld, die er gesündigt, zwei Turteltauben oder zwei junge Tauben, eine als Sündopfer und eine als Brandopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'Und bringe sie zu dem Priester, und er bringe die für das Sündopfer zuerst dar, und knicke ihr ihren Kopf ab vorne am Genick, trenne ihn aber nicht ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'Und spritze von dem Blut des Sündopfers auf die Wand des Altars; und was vom Blut bleibt, werde an den Grund des Altars ausgedrückt. Ein Sündopfer ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Und die zweite mache er zum Brandopfer gemäß der Weise, und der Priester sühne ihn von seiner Sünde, die er gesündigt, und es wird im vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Und reicht seine Hand nicht hin zu zwei Turteltauben oder zwei jungen Tauben, so bringe er als seine Opfergabe für seine Sünde das Zehntel eines Ephah Semmelmehl als Sündopfer. Er tue kein Öl daran und gebe keinen Weihrauch darauf; denn ein Sündopfer ist es;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'Und bringe es zu dem Priester, und der Priester nehme eine Handvoll davon als dessen Gedenkteil und zünde es auf dem Altar an, auf den Feueropfern Jehovahs. Ein Sündopfer ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'Und der Priester sühne ihn für seine Sünde, die er wider deren eines gesündigt, und es wird ihm vergeben. Und es soll des Priesters sein, wie das Speiseopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'Und Jehovah redete mit Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Wenn eine Seele eine Untreue begeht, und sich durch Versehen versündigt an dem, was Jehovah geheiligt ist, so bringe sie dem Jehovah als sein Schuldopfer einen Widder ohne Fehl von dem Kleinvieh nach deiner Schätzung nach den Schekeln Silbers, nach dem Schekel des Heiligtums, zum Schuldopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'Und das, was er gesündigt hat am Geheiligten, erstatte er, und tue ein Fünftel darauf hinzu und gebe es dem Priester, und der Priester sühne über ihm mit dem Widder des Schuldopfers, und es wird ihm vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'Und wenn eine Seele sich versündigt, und wider irgendeines der Gebote Jehovahs tut, was nicht getan werden sollte, es aber nicht weiß, und dadurch sich verschuldet, und trägt seine Missetat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'So bringe er einen Widder von dem Kleinvieh ohne Fehl nach deiner Schätzung, als Schuldopfer dem Priester, und der Priester sühne über ihm für sein Versehen, worin er sich versehen, ohne daß er es wußte; und es wird ihm vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Ein Schuldopfer ist es; er ist Jehovah verschuldet. Und Jehovah redete zu Mose und sprach: So eine Seele sich versündigt und Untreue gegen Jehovah begeht, indem er seinem Nächsten Anvertrautes oder in seine Hand Hinterlegtes oder Entrissenes ableugnet, oder von seinem Nächsten erpreßt, Oder Verlorenes gefunden hat und es ableugnet und zur Lüge schwört, in irgendeinem von allem, das ein Mensch tun mag, sich daran zu versündigen; So es geschieht, daß er sich versündigt und verschuldet hat, so gebe er das Entrissene zurück, das er entrissen, oder das Erpreßte, das er erpreßt, oder das Anvertraute, das ihm anvertraut worden, oder das Verlorene, das er gefunden; Oder von allem, worüber er zur Lüge geschworen, erstatte er nach seiner Summe und tue hinzu den fünften Teil darauf und gebe es dem, welchem es gehört, am Tage seines Schuldopfers. Und als sein Schuldopfer bringe er Jehovah einen Widder ohne Fehl von dem Kleinvieh nach deiner Schätzung, als Schuldopfer dem Priester. Und der Priester sühne über ihm vor Jehovah, und es wird ihm vergeben wegen irgendeinem, das er getan, sich damit zu verschulden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Gebiete Aharon und seinen Söhnen und sprich: Das ist das Gesetz des Brandopfers: Es soll das Brandopfer auf der Brandstelle auf dem Altar die ganze Nacht sein bis zum Morgen und das Feuer des Altars darauf lodern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'Und der Priester ziehe sein linnenes Obergewand an, und über seine Blöße ziehe er die linnenen Beinkleider an, und hebe die Fettasche empor, zu welcher das Feuer das Brandopfer auf dem Altare verzehrt hat, und tue sie neben den Altar;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'Und ziehe seine Kleider aus und ziehe andere Kleider an, und bringe die Fettasche hinaus außerhalb des Lagers an einen reinen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'Und das Feuer auf dem Altar lodere darauf, und soll nicht ausgelöscht werden, und der Priester brenne Morgen nach Morgen Holz darauf an und lege das Brandopfer darauf zurecht und zünde die Fettstücke des Dankopfers darauf an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'Ein beständiges Feuer lodere auf dem Altar. Nie erlösche es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'Und das ist das Gesetz des Speiseopfers: Die Söhne Aharons sollen es vor Jehovah auf dem Altar dar- bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'Und er hebe davon eine Handvoll von dem Semmelmehl des Speiseopfers und von seinem Öl, und allen Weihrauch, der auf dem Speiseopfer ist, und zünde an auf dem Altar dessen Gedenkteil zum Geruch der Ruhe für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Und das übrige davon sollen Aharon und seine Söhne essen, ungesäuert soll es an heiligem Orte gegessen werden. Im Vorhof des Versammlungszeltes sollen sie es essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'Nicht gesäuert soll es gebacken werden; als ihren Teil gebe Ich es ihnen von Meinen Feueropfern. Das Allerheiligste ist es, wie das Sündopfer und wie das Schuldopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Alles Männliche unter den Söhnen Aharons soll es essen. Ewige Satzung sei es für eure Geschlechter von den Feueropfern Jehovahs. Jeder, der sie berührt, wird heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Dies ist die Opfergabe Aharons und seiner Söhne, die sie Jehovah darbringen sollen am Tage seiner Salbung: ein zehntel Ephah Semmelmehl als beständiges Speiseopfer, die Hälfte davon am Morgen, und die Hälfte davon am Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'Auf der Pfanne soll es gemacht werden mit Öl, angerührt sollst du es bringen. In Brocken gebacken als Speiseopfer sollst du es darbringen, als Geruch der Ruhe für Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Und der Priester von seinen Söhnen, der an seiner Statt gesalbt wird, soll es tun. Eine ewige Satzung soll es sein Jehovah, und gänzlich soll es verbrannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Und jegliches Speiseopfer eines Priesters soll ein gänzliches sein, es soll nicht gegessen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Rede zu Aharon und zu seinen Söhnen und sprich: Dies ist das Gesetz des Sündopfers. An dem Orte, da das Brandopfer geschlachtet wird, soll das Sündopfer vor Jehovah geschlachtet werden. Das Allerheiligste ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'Der Priester, der entsündigt, soll es essen. An heiligem Orte soll es gegessen werden, im Vorhof des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'Jeder, der Fleisch davon berührt, soll heilig sein. Und wenn er von dem Blute auf das Kleid spritzt, sollst du, was er spritzt, an heiligem Orte waschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'Und ein irdenes Gefäß, in dem es gekocht worden, soll zerbrochen, ein ehernes Gefäß aber, wenn es darin gekocht ward, gescheuert und mit Wasser ausgespült werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'Alles Männliche unter den Priestern soll es essen. Es ist das Allerheiligste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'Und jegliches Sündopfer, von dessen Blut zur Sühne in dem Heiligtum in das Versammlungszelt gebracht worden, soll nicht gegessen, sondern im Feuer verbrannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'Und dies ist das Gesetz des Schuldopfers. Das Allerheiligste ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'An dem Orte, an dem sie das Brandopfer schlachten, sollen sie das Schuldopfer schlachten; und sein Blut sprenge man ringsum auf den Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'Und all sein Fett bringe er dar davon, den Fettschwanz und das Fett, welches das Eingeweide bedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'Und die zwei Nieren und das Fett daran, das an den Weichen ist, und das Netz über der Leber, über den Nieren nehme er weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'Und der Priester zünde sie an auf dem Altar, als ein Feueropfer für Jehovah. Ein Schuldopfer ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Alles Männliche unter den Priestern darf es essen. An heiligem Orte werde es gegessen. Das Allerheiligste ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Wie das Sündopfer, so das Schuldopfer! Es sei ein Gesetz für sie. Des Priesters, der damit sühnt, sei es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'Und des Priesters, der das Brandopfer eines Mannes darbringt, soll die Haut des Brandopfers sein, das er dargebracht: des Priesters soll es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'Und alles Speiseopfer, das im Ofen gebacken wird, und alles, das in der Bratpfanne oder auf der Pfanne gemacht wird, soll des Priesters, der es darbringt, sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'Und alles Speiseopfer, das mit Öl vermischt, oder trocken ist, soll allen Söhnen Aharons, dem einen wie dem andern gehören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'Und das ist das Gesetz des Dankopfers, das man Jehovah darbringt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Wenn er es als Lobopfer darbringt, so bringe er auf dem Lobopfer dar ungesäuerte Kuchen mit Öl gemischt, und ungesäuerte Fladen mit Öl gesalbt, und Semmelmehl mit Öl angerührt, Kuchen, vermischt mit Öl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Auf den Kuchen gesäuerten Brotes bringe er seine Opfergabe dar, zum Lobopfer seines Dankes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'Und er bringe davon einen von der ganzen Opfergabe dem Jehovah als Hebe dar. Dem Priester, der das Blut des Dankopfers sprengt, ihm gehöre es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Und das Fleisch des Lobopfers seines Dankes soll am Tage der Opfergabe gegessen werden und man lasse nichts bis zum Morgen übrigbleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Und wenn das dargebrachte Opfer ein Gelübde oder Freiwilliges ist, soll es am Tage der Darbringung seines Opfers gegessen werden; und auch am morgenden Tage darf, was davon übrigblieb, gegessen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'Was aber von dem Opferfleisch noch am dritten Tage übrig ist, soll im Feuer verbrannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Und wenn man am dritten Tage von dem Fleische des Dankopfers ißt, so wird der Darbringende nicht wohlgefällig sein, es wird ihm nicht gedacht werden: Abscheulich ist es, und die Seele, die davon ißt, soll ihre Missetat tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'Und das Fleisch, das irgend etwas Unreines berührt, soll nicht gegessen werden. Es soll im Feuer verbrannt werden. Das Fleisch anlangend, darf das Fleisch jeder Reine essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'Und wenn eine Seele Fleisch vom Dankopfer ißt, das dem Jehovah gehört, und hat seine Unreinheit an sich, so soll diese Seele von seinem Volke ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'Und wenn eine Seele irgend etwas Unreines, eine Unreinheit eines Menschen, oder ein unreines Vieh oder irgendein unreines Scheusal angerührt hat und vom Fleisch des Dankopfers ißt, das für Jehovah ist, so soll diese Seele aus ihrem Volk ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Rede zu den Söhnen Israels und sprich: Alles Fett eines Ochsen, eines Schafs oder einer Ziege sollt ihr nicht essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Und das Fett vom Aas und Fett vom Zerfleischten mag zu allerlei Arbeit verwendet werden, aber essen sollt ihr es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Denn wer das Fett von dem Vieh ißt, von dem man Jehovah Feueropfer darbringt, die Seele, die es ißt, soll aus ihrem Volk ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'Und kein Blut sollt ihr essen in all euren Wohnungen, weder vom Gevögel, noch vom Vieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Jede Seele, die irgend Blut ißt, die Seele soll aus ihrem Volk ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Rede zu den Söhnen Israels und sprich: Wer Jehovah sein Dankopfer darbringt, der soll Jehovah seine Opfergabe von seinem Dankopfer bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'Seine Hände sollen das Feueropfer Jehovahs hineinbringen. Das Fett auf der Brust soll er hineinbringen, samt der Brust, sie als Webeopfer vor Jehovah zu weben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'Und der Priester soll das Fett anzünden auf dem Altar; und die Brust soll Aharons und seiner Söhne sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'Und die rechte Schulter sollt ihr als Hebe dem Priester von euren Dankopfern geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Dem von Aharons Söhnen, der das Blut der Dankopfer und das Fett darbringt, soll die rechte Schulter als Anteil sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Denn die Webebrust und die Hebeschulter nehme Ich von den Söhnen Israels von den Dankopfern, und gebe sie dem Priester Aharon und seinen Söhnen als ewige Satzung von den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'Dies ist die Salbung Aharons und die Salbung seiner Söhne von den Feueropfern Jehovahs, am Tage, da Er sie nahen ließ, Jehovah Priesterdienst zu tun;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'Was Jehovah gebot, ihnen zu geben am Tage, da Er sie salbte von den Söhnen Israels, eine ewige Satzung für ihre Geschlechter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'Das ist das Gesetz für das Brandopfer, für das Speiseopfer und für das Sündopfer und für das Schuldopfer und für die Füllopfer und für das Dankopfer,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'Die Jehovah dem Mose auf dem Berge Sinai geboten hat, am Tage, da Er den Söhnen Israels gebot, ihre Opfergaben Jehovah in der Wüste Sinai darzubringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Nimm Aharon und seine Söhne mit ihm, und die Kleider und das Salböl, und den Farren des Sündopfers und die zwei Widder, und den Korb des Ungesäuerten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'Und versammle die ganze Gemeinde zum Eingang des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'Und Mose tat, wie ihm Jehovah geboten, und die Gemeinde versammelte sich am Eingang des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'Und Mose sprach zu der Gemeinde: Dies ist das Wort, das Jehovah geboten hat zu tun;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'Und Mose ließ Aharon und seine Söhne sich nahen, und wusch sie mit Wasser;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'Und gab ihm den Leibrock und gürtete ihn mit dem Gürtel, und zog ihm das Oberkleid an, gab auf ihn das Ephod und gürtete ihn mit dem Gurt des Ephod und legte es ihm an;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'Und tat ihm das Brustschildlein an und gab die Urim und die Thummim in das Brustschildlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'Und er setzte die Tiara auf sein Haupt, und an die Tiara vorn über dem Gesicht setzte er das goldene Blatt, das heilige Diadem, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'Und Mose nahm das Salböl und salbte die Wohnung und alles, was darin war, und heiligte sie;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'Und spritzte davon siebenmal auf den Altar, und salbte den Altar und alle seine Geräte und das Becken und sein Gestell, um sie zu heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'Und er goß von dem Salböl auf das Haupt Aharons und salbte ihn, um ihn zu heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'Und Mose ließ die Söhne Aharons sich nahen, und zog ihnen Leibröcke an, und gürtete sie mit dem Gürtel und band ihnen Kopfbünde um, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'Und er brachte den Farren des Sündopfers herbei; und Aharon und seine Söhne legten ihre Hände auf den Kopf des Farren des Sündopfers;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'Und er schlachtete ihn. Und Mose nahm das Blut und gab es auf die Hörner des Altars ringsum mit seinem Finger und entsündigte den Altar, und das Blut goß er an den Grund des Altars und heiligte ihn, um darauf zu sühnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'Und er nahm alles Fett, das an dem Eingeweide war, und das Netz der Leber, und die zwei Nieren und ihr Fett, und Mose zündete es an auf dem Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Und den Farren und seine Haut und sein Fleisch und seinen Mist verbrannte er im Feuer außerhalb des Lagers, wie Jehovah Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Und er brachte den Widder zum Brandopfer dar, und Aharon und seine Söhne legten ihre Hände auf den Kopf des Widders,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'Und schlachtete ihn, und Mose sprengte das Blut auf den Altar ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'Und den Widder zerstückte er in seine Stücke und Mose zündete den Kopf und die Stücke und das Fett an;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Und das Eingeweide und die Schenkel wusch er im Wasser, und Mose zündete den ganzen Widder auf dem Altar an. Ein Brandopfer war es zum Geruch der Ruhe, ein Feueropfer für Jehovah, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'Und er brachte den zweiten Widder dar, den Widder der Füllungen, und Aharon und seine Söhne legten ihre Hände auf den Kopf des Widders.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'Und er schlachtete ihn, und Mose nahm von seinem Blut und gab es auf Aharons rechtes Ohrläppchen und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'Und er ließ die Söhne Aharons sich nahen, und Mose gab von dem Blute auf ihr rechtes Ohrläppchen und auf den Daumen ihrer rechten Hand und auf die große Zehe ihres rechten Fußes, und Mose sprengte das Blut ringsum auf den Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'Und er nahm das Fett und den Fettschwanz und alles Fett auf dem Eingeweide und das Netz der Leber und die zwei Nieren und ihr Fett und die rechte Schulter;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'Und aus dem Korb des Ungesäuerten vor Jehovah nahm er einen ungesäuerten Kuchen und einen Kuchen von Ölbrot und einen Fladen und legte sie auf die Fettstücke und auf die rechte Schulter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'Und gab alles auf die Hände Aharons und auf die Hände seiner Söhne und webte sie zur Webe vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'Und Mose nahm sie von ihren Händen und zündete sie an auf dem Altar über dem Brandopfer. Ein Füllungsopfer waren sie zum Geruch der Ruhe, ein Feueropfer war es für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'Und die Brust nahm Mose und webte sie zur Webe vor Jehovah. Vom Widder der Füllungen ward es dem Mose zum Anteil, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Und Mose nahm von dem Salböl und von dem Blut, das auf dem Altar war, und spritze es auf Aharon, auf seine Kleider und auf seine Söhne und auf die Kleider seiner Söhne mit ihm, und heiligte Aharon, seine Kleider, und seine Söhne und die Kleider seiner Söhne mit ihm;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'Und Mose sprach zu Aharon und seinen Söhnen: Kochet das Fleisch am Eingang des Versammlungszeltes, und dort esset es und das Brot, das in dem Korbe der Füllungen ist, wie ich geboten und gesprochen habe: Aharon und seine Söhne sollen es essen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Und was vom Fleisch und vom Brot übrig ist, sollt ihr im Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Und von dem Eingang des Versammlungszeltes sollt ihr nicht ausgehen sieben Tage, bis zum Tage, da die Tage eurer Füllungen erfüllet sind; denn sieben Tage wird eure Hand gefüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Sowie man getan hat an diesem Tage, hat Jehovah geboten zu tun, um über euch zu sühnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'Und am Eingang des Versammlungszeltes sollt ihr sitzen bei Tag und bei Nacht, sieben Tage und die Hut Jehovahs hüten, auf daß ihr nicht sterbet; denn so ist es mir geboten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'Und Aharon und seine Söhne taten alle Dinge, die Jehovah durch die Hand Moses geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'Und am achten Tage geschah es, daß Mose Aharon und seine Söhne und die Ältesten Israels rief.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'Und er sprach zu Aharon: Nimm für dich ein junges Stierkalb zum Sündopfer und einen Widder ohne Fehl zum Brandopfer und bringe sie dar vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'Und zu den Söhnen Israels sollst du reden und sprechen: Nehmet einen Ziegenbock zu einem Sündopfer, und ein Kalb und ein Lamm von einem Jahr ohne Fehl zu einem Brandopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'Und einen Ochsen und einen Widder zum Dankopfer, zu opfern vor Jehovah, und ein Speiseopfer, mit Öl vermischt; denn es erscheint euch Jehovah an diesem Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Und sie nahmen, was Mose geboten hatte, an den Eingang des Versammlungszeltes, und es nahte die ganze Gemeinde und sie standen vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'Und Mose sprach: Dies ist das Wort, das Jehovah geboten hat, daß ihr tun sollt; auf daß euch die Herrlichkeit Jehovahs erscheine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Und Mose sprach zu Aharon: Nahe dich zum Altar, und tue dein Sündopfer und dein Brandopfer, und sühne für dich und für das Volk, und mache die Opfergabe des Volkes, und sühne für sie, wie Jehovah geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'Und Aharon nahte zum Altar und schlachtete das Kalb des Sündopfers, das er hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'Und Aharons Söhne brachten ihm das Blut dar, und er tauchte seinen Finger in das Blut und gab es auf die Hörner des Altars, und das Blut goß er an den Grund des Altars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Und das Fett und die Nieren und das Netz von der Leber von dem Sündopfer zündete er auf dem Altar an, wie Jehovah Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'Und das Fleisch und die Haut verbrannte er im Feuer außerhalb des Lagers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'Und er schlachtete das Brandopfer, und Aharons Söhne reichten ihm das Blut dar, und er sprengte es ringsum auf den Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Und das Brandopfer reichten sie ihm dar in seinen Stücken und den Kopf, und er zündete es an auf dem Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'Und er wusch das Eingeweide und die Schenkel und zündete sie auf dem Brandopfer auf dem Altare an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'Und er brachte die Opfergabe des Volkes dar, und nahm den Bock des Sündopfers, das für das Volk war, und schlachtete ihn und brachte ihn als Sündopfer dar, wie das erste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'Und er brachte das Brandopfer dar, und er machte es nach dem Rechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'Und er brachte das Speiseopfer dar, und füllte seine Hand davon und zündete es auf dem Altare an außer dem Brandopfer des Morgens,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'Und er schlachtete den Ochsen und den Widder zum Dankopfer für das Volk, und die Söhne Aharons reichten ihm das Blut dar, und er sprengte es ringsum auf den Altar;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'Und die Fettstücke von dem Ochsen und von dem Widder, den Fettschwanz und die Netzhaut und die Nieren und das Netz der Leber;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'Und sie legten die Fettstücke auf die Bruststücke, und er zündete die Fettstücke an auf dem Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'Und die Bruststücke und die rechte Schulter webte Aharon als Webe vor Jehovah, wie Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Und Aharon hob seine Hände auf über das Volk und segnete sie, und kam herab, nachdem er das Sündopfer und das Brandopfer und das Dankopfer getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Und Mose und Aharon gingen in das Versammlungszelt und kamen heraus und segneten das Volk. Und es erschien die Herrlichkeit Jehovahs dem ganzen Volke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'Und es ging Feuer aus von Jehovahs und fraß auf dem Altar das Brandopfer und die Fettstücke. Und das ganze Volk sah es, und sie jauchzten und fielen auf ihr Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Und Nadab und Abihu, Aharons Söhne, nahmen jeder Mann seine Rauchpfanne und taten Feuer hinein und legten Räuchwerk darauf und brachten vor Jehovah fremdes Feuer dar, das Er ihnen nicht geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Und Feuer ging aus von Jehovah, und fraß sie auf und sie starben vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Und Mose sprach zu Aharon: Das ist es, was Jehovah geredet und gesprochen hat: An denen, die Mir nahe sind, will ich geheiligt und vor dem Angesichte des ganzen Volkes verherrlicht werden. Und Aharon war stille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'Und Mose rief Mischael und Elzaphan, die Söhne Ussiels, des Oheims von Aharon, und sprach zu ihnen: Nahet, traget eure Brüder hinweg vom Heiligtum, zum Lager hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Und sie nahten und trugen sie in ihren Leibröcken zum Lager hinaus, wie Mose geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'Und Mose sprach zu Aharon und seinen Söhne Eleasar und Ithamar: Eure Häupter sollt ihr nicht blößen und eure Kleider nicht aufrei-ßen, daß ihr nicht sterbet, und Er über die ganze Gemeinde entrüstet werde. Aber eure Brüder, das ganze Haus Israel mögen weinen über den Brand derer, die Jehovah verbrannte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'Und von dem Eingang des Versammlungszeltes sollt ihr nicht ausgehen, auf daß ihr nicht sterbet; denn Jehovahs Salbungsöl ist auf euch. Und sie taten nach Moses Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'Und Jehovah redete zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Wein und starkes Getränk sollst du und deine Söhne mit dir nicht trinken, wenn ihr zum Versammlungszelt eingehet, auf daß ihr nicht sterbet. Eine ewige Satzung soll es sein für eure Geschlechter;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'Und auf daß ihr scheidet zwischen dem Heiligen und zwischen dem Gemeinen und zwischen dem Unreinen und zwischen dem Reinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'Und daß ihr die Söhne Israels unterweiset in allen Satzungen, die Jehovah zu ihnen durch die Hand Moses geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'Und Mose redete zu Aharon und zu seinen Söhnen Eleasar und Ithamar, die übriggeblieben: Nehmet das Speiseopfer, das übrig ist von den Feueropfern Jehovahs und esset es ungesäuert neben dem Altar; denn allerheiligst ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Und sollt es essen an heiligem Ort; denn es ist deine Satzung und deiner Söhne Satzung von Jehovahs Feueropfern; denn so ist es mir geboten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Und die Webebrust und die Hebeschulter sollt ihr essen an reinem Orte, du und deine Söhne und deine Töchter mit dir; denn als deine Satzung und deiner Söhne Satzung von den Dankopfern der Söhne Israels werden sie gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Die Schulter der Hebe und die Brust der Webe sollen sie auf dem Fettstück der Feueropfer hereinbringen, um sie als Webe vor Jehovah zu weben; und sie sollen für dich und deine Söhne mit dir eine ewige Satzung sein, wie Jehovah geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Und Mose befragte sie über den Bock des Sündopfers, und siehe, er war verbrannt. Und er war entrüstet über Eleasar und Ithamar, die Söhne Aharons, die übriggeblieben und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Warum habt ihr das Sündopfer nicht an heiligem Orte gegessen; denn allerheiligst ist es. Und Er hat es euch gegeben, zu tragen die Missetat der Gemeinde, über sie vor Jehovah zu sühnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Siehe! Sein Blut ist nicht in das Innere des Heiligtums gebracht worden. Ihr hättet es im Heiligtum essen sollen, wie ich geboten habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Und Aharon redete zu Mose: Siehe, heute haben sie ihr Sündopfer und ihr Brandopfer vor Jehovah dargebracht, und solches ist mir begegnet. Und äße ich heute Sündopfer, wäre es gut in den Augen Jehovahs?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Und Mose hörte, und es war gut in seinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'Und Jehovah redete zu Mose und zu Aharon und sprach zu ihnen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Redet zu den Söhnen Israels und sprechet: Das sind die Tiere, die ihr essen dürfet von allem Vieh auf Erden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Alles, was einen durchbrochenen Huf, einen in Klauen gespaltenen Huf hat und wiederkäut vom Vieh, das dürft ihr essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Doch sollt ihr nicht essen von denen, die wiederkäuen und denen mit durchbrochenem Huf: Das Kamel; denn es wiederkäut zwar, hat aber keinen durchbrochenen Huf. Unrein sei es euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'Und das Kaninchen; denn es ist wiederkäuend und hat keinen durchbrochenen Huf. Unrein sei es euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'Und den Hasen; denn er wiederkäut und hat keinen durchbrochenen Huf. Unrein sei er euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'Und das Schwein; denn es hat einen durchbrochenen Huf und die Klauen gespalten, aber es wiederkäut nicht. Unrein sei es euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Von ihrem Fleisch sollt ihr nicht essen und ihr Aas nicht berühren. Unrein seien sie euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Und das dürfet ihr essen von allem, was im Wasser ist: Alles, was Flossen und Schuppen hat im Wasser, in den Meeren und in den Bächen, das dürfet ihr essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Aber alles, was keine Flosse und Schuppe hat in Meeren und Bächen, von allem, das im Wasser wimmelt und von aller lebendigen Seele im Wasser, ein Abscheu sei es euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Zum Abscheu sollen sie euch sein. Von ihrem Fleisch sollt ihr nicht essen, und ihr Aas sei euch ein Abscheu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Alles, was nicht Flosse und Schuppe hat im Wasser, soll euch zum Abscheu sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'Und diese sollt ihr vom Gevögel verabscheuen. Sie sollen nicht gegessen werden, zum Abscheu sein: Der Adler und der Seeadler und der Lämmergeier;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'Und der Weihe und der Falke nach seiner Art;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'Alle Raben nach ihren Arten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'Und das Käuzlein und der Strauß und die Möwe und der Habicht nach seiner Art;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'Und der Uhu und der Taucher und die Eule.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'Und die Dohle und der Pelikan und der Aasgeier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'Und der Storch, der Reiher nach seiner Art, und der Wiedehopf und die Fledermaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Alles Kriechtier mit Flügeln, das auf Vieren geht, soll euch zum Abscheu sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Nur das sollt ihr essen von allem geflügelten Kriechtier, das auf Vieren geht, das Schenkel über den Füßen hat, um damit auf der Erde zu hüpfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Diese möget ihr davon essen: Die Heu- schrecke nach ihrer Art, den Solam nach seiner Art und den Chargol nach seiner Art, und den Chagab nach seiner Art.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Und alles andere geflügelte Kriechtier mit vier Füßen soll euch ein Abscheu sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'Und mit diesen verunreinigt ihr euch. Wer ihr Aas berührt, ist bis zum Abend unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'Und jeder, der von ihrem Aase trägt, soll seine Kleider waschen, und ist unrein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Alles Vieh, das einen durchbrochenen Huf hat und den Huf nicht spaltet, und nicht wiederkäut, soll unrein für euch sein. Wer immer es berührt, ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'Und alles, was auf seinen Tatzen geht unter allem Wild, das auf Vieren geht, ist unrein für euch, ein jeder, der ihr Aas anrührt, ist unrein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'Und wer ihr Aas trägt, soll seine Kleider waschen und ist unrein bis zum Abend. Unrein seien sie euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'Und das sei euch unrein unter dem Kriechtier, das auf dem Lande wimmelt: Das Wiesel und die Maus und die gelbe Eidechse nach ihrer Art.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'Und die Feldmaus und das Chamäleon und die Schildkröte und die Schnecke und der Maulwurf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Diese seien euch unrein unter allem Kriechtier. Wer sie anrührt, wenn sie tot sind, ist unrein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'Und alles, worauf ein solches unter ihnen fällt, wenn es tot ist, ist unrein, irgendein hölzernes Gerät oder ein Kleid oder Fell oder Sack, jegliches Gerät, mit dem man eine Arbeit tut, soll ins Wasser hineingebracht werden und ist unrein bis zum Abend, und dann ist es rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'Und jegliches irdene Gefäß, in dessen Mitte derselben eines fällt, wird unrein, alles, was in dessen Mitte ist; und ihr sollt es zerbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Jegliche Speise, die gegessen wird, über die solches Wasser kommt, ist unrein, und alles Getränk, das aus irgend solchem Gefäß getrunken wird, ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'Und alles, worauf von ihrem Aase fällt ist unrein. Der Ofen oder Herd werde eingerissen; sie sind unrein, und sollen euch unrein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Nur der Brunnquell und die Grube, in denen sich Wasser sammelt, sollen rein sein; was aber ihr Aas berührt, soll unrein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'Und so von ihrem Aas auf irgendwelchen Saatsamen fällt, der gesät werden soll, so ist er rein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'Wird aber Wasser auf den Samen getan, und es fällt von ihrem Aas darauf, so ist es unrein für euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'Und so von dem Vieh, das euch zur Speise ist, eines stirbt, so ist der, welcher sein Aas berührt, unrein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'Und wer von seinem Aase ißt, soll seine Kleider waschen, und unrein sein bis zum Abend, und wer sein Aas trägt, soll seine Kleider waschen und ist unrein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'Und alles Gewimmel, das auf der Erde wimmelt, ist ein Abscheu; es soll nicht gegessen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Alles, was auf dem Bauche geht, und alles, was auf vieren und bis zu dem, das auf mehr Füßen geht, von allem Gewimmel, das auf der Erde wimmelt, sollt ihr nicht essen; denn sie sind ein Abscheu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Ihr sollt eure Seele nicht abscheulich machen durch irgendwelches Gewimmel, das da wimmelt, und euch damit nicht verunreinigen, daß ihr dadurch unrein werdet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Denn Ich bin Jehovah, euer Gott, und ihr sollt euch heiligen, auf daß ihr heilig seid; denn Ich bin heilig; und sollt eure Seele nicht verunreinigen mit irgendwelchem Gewimmel, das auf der Erde kriecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Denn Ich bin Jehovah, Der euch aus Ägyptenland heraufgebracht, auf daß Ich euer Gott sei. So seid denn heilig, denn Ich bin heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'Das ist das Gesetz vom Vieh und Gevögel und allen lebendigen Seelen, die sich im Wasser regen, und allen Seelen, die auf der Erde wimmeln;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'Damit ihr scheidet zwischen Unreinem und zwischen Reinem, und zwischen dem Tiere, das ihr essen und dem Tier, das ihr nicht essen sollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Rede zu den Söhnen Israels und sprich: Wenn ein Weib empfängt und ein Männliches gebiert, so ist sie sieben Tage unrein. Wie die Tage der Abgeschiedenheit ihrer Krankheit soll sie unrein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'Und am achten Tage soll das Fleisch seiner Vorhaut beschnitten werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Und sie soll drei Tage und dreißig Tage im Blute ihrer Reinigung bleiben, nichts Heiliges anrühren, und nicht zum Heiligtum kommen, bis die Tage ihrer Reinigung voll sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Und gebiert sie ein Weibliches, soll sie zwei Wochen unrein sein, wie bei ihrer Abgeschiedenheit und soll sechs Tage und sechzig Tage im Blute ihrer Reinigung bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Und wenn die Tage ihrer Reinigung für Sohn oder für Tochter erfüllt sind, soll sie ein einjähriges Lamm als Brandopfer und eine junge Taube oder eine Turteltaube als Sündopfer zum Eingang des Versammlungszeltes zu dem Priester bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Und er bringe es dar vor Jehovah und sühne über sie, auf daß sie rein sei vom Born ihres Blutes. Dies ist das Gesetz für die, so ein Männliches oder ein Weibliches geboren hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Und reicht ihre Hand nicht genug zu einem Lamm, so nehme sie zwei Turteltauben oder zwei junge Tauben, eine zum Brandopfer und eine zum Sündopfer, und der Priester sühne über sie und sie sei rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'Und Jehovah redete zu Mose und zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'So bei einem Menschen auf der Haut seines Fleisches eine Erhebung oder ein Schorf oder ein lichter Fleck ist, und dies auf der Haut seines Fleisches zum Male des Aussatzes werden könnte, so werde er zu Aharon, dem Priester, oder zu einem von seinen Söhnen, den Priestern, gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Und wenn der Priester das Mal auf der Haut des Fleisches gesehen, und das Haar in dem Male in Weiß verwandelt worden, und das Mal ist tiefer anzusehen als die Haut seines Fleisches, so ist es ein Aussatzmal, und der Priester sehe ihn und erkläre ihn für unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Und wenn ein weißer, lichter Fleck auf der Haut seines Fleisches ist, aber nicht tiefer als die Haut anzusehen, und das Haar nicht in Weiß verwandelt ist, so lasse der Priester den mit dem Male sieben Tage einschließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'Und am siebenten Tage sehe ihn der Priester, und siehe, das Mal ist in seinen Augen stehengeblieben, und das Mal hat auf der Haut nicht um sich gegriffen, so lasse ihn der Priester zum zweitenmal sieben Tage einschließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'Und wenn ihn dann der Priester am siebenten Tag zum zweitenmal sieht, und siehe, das Mal ist trüber geworden, und das Mal hat auf der Haut nicht um sich gegriffen, so erkläre ihn der Priester rein. Es ist ein Schorf. Und er wasche seine Kleider und ist rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Hat aber der Schorf um sich gegriffen auf der Haut, nachdem er vom Priester für seine Reinsprechung besehen worden ist, so werde er vom Priester zum zweitenmal besehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'Und sieht ihn der Priester, und siehe, der Schorf hat in der Haut um sich gegriffen, so erkläre ihn der Priester für unrein: es ist Aussatz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Ist das Aussatzmal am Menschen, so werde er zum Priester gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'Und sieht der Priester, und siehe, eine weiße Erhebung ist in der Haut und hat das Haar in Weiß verwandelt, und frisches wildes Fleisch in der Erhebung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'So ist alter Aussatz in der Haut seines Fleisches; und der Priester erkläre ihn für unrein. Er schließe ihn nicht ein; denn er ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'So aber der Aussatz so in der Haut hervorbricht, daß der Aussatz die ganze Haut mit dem Male bedeckt, von seinem Kopfe und bis zu seinen Füßen, soweit das Auge des Priesters sieht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'Und der Priester sieht, und siehe, der Aussatz hat sein ganzes Fleisch bedeckt, so soll er das Mal für rein erklären. Alles an ihm ist in Weiß verwandelt; er ist rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Am Tage aber, da sich wildes Fleisch an ihm sehen läßt, wird er unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'Und sieht der Priester das wilde Fleisch, so erkläre er ihn für unrein; das wilde Fleisch ist unrein, es ist der Aussatz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Oder wenn das wilde Fleisch sich zurückzieht und verwandelt sich in Weiß, so komme er zu dem Priester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'Und sieht ihn der Priester und siehe, das Mal ist in Weiß verwandelt, so erkläre der Priester das Mal für rein. Er ist rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'Und so an jemandes Fleisch in der Haut ein Geschwür ist und geheilt wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'Und an dem Orte des Geschwürs eine weiße Erhebung oder ein lichter weißrötlicher Fleck wird, so erscheine er bei dem Priester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'Und sieht der Priester, und siehe, es ist niedriger anzusehen als die Haut, und das Haar ist in Weiß verwandelt, so erkläre ihn der Priester für unrein; denn das Aussatzmal ist an dem Geschwür ausgebrochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Und sieht sie der Priester, und siehe, es ist kein weißes Haar darin, und es ist nicht niedriger als die Haut und ist trübe, so lasse ihn der Priester sieben Tage einschließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'Greift es aber um sich in der Haut, so erkläre ihn der Priester für unrein: es ist das Mal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Blieb aber der lichte Fleck an seiner Stelle stehen und greift nicht um sich, so ist es eine Entzündung des Geschwürs, und der Priester erkläre ihn für rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Oder so am Fleische in der Haut ein Brandmal vom Feuer ist und wildes Fleisch am Brandmal und ein weißrötlicher oder weißer, lichter Fleck wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'Und der Priester sieht es, und siehe, das Haar ist auf dem lichten Fleck in Weiß verwandelt und ist tiefer anzusehen als die Haut, so ist es Aussatz, der auf dem Brandmal ausgebrochen ist, und der Priester soll ihn für unrein erklären: es ist das Aussatzmal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Und wenn es der Priester sieht, und siehe, es ist an dem lichten Fleck kein weißes Haar, und er ist nicht niedriger als die Haut und ist trübe, so schließe ihn der Priester ein sieben Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'Und sieht ihn der Priester am siebenten Tag, und es hat in der Haut um sich gegriffen: so erkläre ihn der Priester für unrein. Es ist das Aussatzmal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Steht aber der lichte Fleck an derselben Stelle und hat nicht in der Haut um sich gegriffen, und die Erhebung des Brandmals ist trübe geworden, so erkläre der Priester ihn für rein, denn es ist die Entzündung des Brandmals.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'Und hat ein Mann oder ein Weib ein Mal auf dem Kopf oder am Bart:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'Und sieht der Priester das Mal, und siehe, es ist tiefer anzusehen als die Haut, und es ist feines, goldgelbes Haar darin, so erkläre der Priester ihn für unrein: es ist der Nethek, der Aussatz am Kopf oder Bart.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Und sieht der Priester das Mal des Nethek und siehe, es ist nicht tiefer im Ansehen als die Haut, und ist kein schwarzes Haar darin, so lasse der Priester den mit dem Male des Nethek einschließen sieben Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'Und sieht der Priester das Mal am siebenten Tag, und siehe, der Nethek hat nicht um sich gegriffen, und ist kein goldgelbes Haar darin, und ist der Nethek nicht tiefer im Ansehen als die Haut:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'So soll er sich scheren, den Nethek aber soll er nicht scheren. Und der Priester schließe den mit Nethek Behafteten zum zweiten Male sieben Tage ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'Und sieht der Priester den Nethek am siebenten Tage, und siehe, der Nethek hat nicht in der Haut um sich gegriffen, und ist nicht tiefer anzusehen als die Haut ist, so erkläre ihn der Priester für rein. Und er wasche seine Kleider, und ist rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Greift aber der Nethek in der Haut um sich, nachdem er für rein erklärt worden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'Und sieht ihn der Priester und siehe, der Nethek hat in der Haut um sich gegriffen, so forsche der Priester nicht nach dem goldgelben Haar. Er ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Wenn aber in seinen Augen der Nethek stille steht, und schwarzes Haar darin sproßt, so ist der Nethek geheilt. Er ist rein und der Priester erkläre ihn für rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'Und wenn beim Mann oder beim Weib auf der Haut ihres Fleisches lichte Flecken, weiße lichte Flecken sind;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'Und der Priester sieht sie, und siehe, auf der Haut ihres Fleisches sind trübe, weiße lichte Flecken, so ist es der Bohak, der in der Haut ausgebrochen. Er ist rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Und wenn einem Manne die Haare seines Hauptes ausfallen, und er wird ein Kahlkopf, so ist er rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'Und wenn einem auf der Seite seines Angesichts das Haar seines Hauptes ausfällt, und eine Vorderglatze wird, so ist er rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Und wenn in der Hinterglatze oder in der Vorderglatze ein weißrötliches Mal wird, so ist es der Aussatz, der auf seiner Hinterglatze oder seiner Vorderglatze ausgebrochen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'Und sieht ihn der Priester, und siehe, ein weißrötliches Erhebungsmal ist auf seiner Hinterglatze oder seiner Vorderglatze, wie das Ansehen des Aussatzes auf der Haut des Fleisches:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'So ist er ein aussätziger Mann, er ist unrein. Der Priester soll ihn für unrein erklären. Auf seinem Haupte ist sein Mal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Und der Aussätzige, an dem das Mal ist, soll aufgerissene Kleider haben, und das Haupt blößen, und bis an den Bart sich einhüllen und Unrein! Unrein! rufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Alle Tage, die das Mal an ihm ist, soll er unrein sein! Unrein ist er. Allein soll er wohnen. Außerhalb des Lagers soll sein Wohnen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'Und wenn an einem Kleide das Aussatzmal ist, an einem Kleide von Wolle oder einem Kleide von Linnen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'Oder am Aufzug, oder am Einschlag von Lein oder von Wolle, oder am Fell oder an irgendeiner Arbeit von Fell;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'Und ist das Mal grünlich oder rötlich am Kleide oder am Fell, oder am Aufzug oder am Einschlag oder an irgendeinem Gerät von Fell, so ist es ein Aussatzmal; und man soll es den Priester sehen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'Und hat der Priester das Mal gesehen, so lasse er das Mal sieben Tage einschließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'Und sieht er das Mal am siebenten Tage, daß das Mal um sich gegriffen hat am Kleide, oder am Aufzug oder am Einschlag oder am Fell, an allem, was aus Fell gemacht wird zur Arbeit, so ist das Mal ein zerfressender Aussatz. Es ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Und er verbrenne das Kleid, oder den Aufzug, oder den Einschlag von Wolle oder von Lein, oder jegliches Gerät von Leder, oder an dem das Mal ist, denn ein zerfressender Aussatz ist es. Es werde im Feuer verbrannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Sieht aber der Priester, und siehe, das Mal hat nicht am Kleide oder am Aufzug oder am Einschlag oder an irgendwelchem ledernen Gerät um sich gegriffen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'So soll der Priester gebieten, daß man das, an dem das Mal ist, wasche, und soll es andere sieben Tage verschließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'Und sieht der Priester, nachdem das Mal gewaschen ist, und siehe, das Mal hat sein Aussehen nicht verwandelt, und das Mal hat nicht weiter um sich gegriffen, so ist es unrein, und du sollst es im Feuer verbrennen. Es ist eingefressen auf der Kehrseite wie auf der rechten Seite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'Sieht aber der Priester, und siehe, das Mal ist nach dem Waschen trübe, so reiße er es aus dem Kleide oder aus dem Fell oder aus dem Aufzug oder aus dem Einschlag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Wird es aber am Kleid oder am Aufzug oder am Einschlag oder an irgendeinem Gerät von Fell wieder gesehen, so ist es ein Ausbruch; dann sollst du das, woran das Mal ist, im Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Das Kleid aber oder der Aufzug oder der Einschlag oder irgendwelches Gerät von Fell, das du gewaschen hast, und von dem das Mal gewichen ist, soll zum zweitenmal gewaschen werden, und dann ist es rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'Dies ist das Gesetz über das Aussatzmal an Kleidern von Wolle oder Lein, oder am Aufzug oder am Einschlag oder an jeglichem Gerät von Fell, es für rein zu erklären oder es unrein zu erklären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'Dies ist das Gesetz für den Aussätzigen am Tage seiner Reinigung. Und er werde vor den Priester gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'Und der Priester gehe hinaus außerhalb des Lagers, und der Priester sehe: und siehe, ist das Aussatzmal geheilt an dem Aussätzigen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'So gebiete der Priester, daß man für den, der sich reinigen läßt, zwei lebendige, reine Vögel und Zedernholz und Scharlach doppelt gefärbt und Ysop nehme;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'Und der Priester gebiete, daß man einen der Vögel schlachte in ein irdenes Gefäß über lebendigem Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Und den lebendigen Vogel, den nehme er und das Zederholz und den doppelt gefärbten Scharlach und den Ysop und tauche sie und den lebendigen Vogel in das Blut des Vogels, der über dem lebendigen Wasser geschlachtet worden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'Und spritze davon siebenmal über den, der sich vom Aussatze reinigen läßt, und reinige ihn; und entsende den lebendigen Vogel über das Feld hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Und der zu Reinigende wasche seine Kleider und schere all sein Haar ab und bade im Wasser, so ist er rein, und nachher komme er ins Lager, bleibe aber sieben Tage außerhalb seines Zeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'Und am siebenten Tag schere er all sein Haar, sein Haupt und seinen Bart und seine Augenbrauen und all sein Haar schere er; und wasche seine Kleider und bade sein Fleisch im Wasser und er ist rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Und am achten Tage nehme er zwei Lämmer ohne Fehl und ein Mutterlamm ohne Fehl von einem Jahr und drei Zehntel Semmelmehl als Speiseopfer, mit Öl vermischt, und ein Log Öl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Und der reinigende Priester lasse den Mann, der sich reinigen läßt, samt denselben vor Jehovah an den Eingang des Versammlungszeltes stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'Und der Priester nehme das eine Lamm und bringe es dar zum Schuldopfer, und das Log Öl, und webe sie als Webe vor Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'Und er schlachte das Lamm an dem Orte, wo man das Sündopfer und das Brandopfer schlachtet, an heiligem Orte; denn wie das Sündopfer ist das Schuldopfer des Priesters; es ist allerheiligst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'Und der Priester nehme von dem Blute des Schuldopfers und der Priester gebe es auf das rechte Ohrläppchen des zu Reinigenden und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'Und der Priester nehme von dem Log Öl und gieße in seine linke flache Hand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'Und tauche der Priester seinen rechten Finger in das Öl, das in seiner linken flachen Hand ist, und spritze mit seinem Finger von dem Öl siebenmal vor Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Und von dem übrigen des Öls aus seiner flachen Hand gebe der Priester dem sich Reinigenden auf das rechte Ohrläppchen und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes, auf dem Blute des Schuldopfers;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Und gebe das übrige von dem Öl, das auf des Priesters flacher Hand ist, auf das Haupt des zu Reinigenden, und der Priester sühne über ihm vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'Und der Priester mache das Sündopfer und sühne über den sich Reinigenden von seiner Unreinheit, und schlachte hernach das Brandopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Und der Priester lasse aufgehen das Brandopfer und das Speiseopfer auf dem Altar, und der Priester sühne über ihm, und er ist rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Und wenn er arm ist und seine Hand nicht hinreicht, so nehme er ein Lamm als Schuldopfer zur Webe, über ihm zu sühnen, und ein Zehntel Semmelmehl, mit Öl vermischt, zum Speiseopfer, und ein Log Öl;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'Und zwei Turteltauben oder zwei junge Tauben, wofür seine Hand hinreicht, und eine sei ein Sündopfer und die andere ein Brandopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'Und am achten Tage seiner Reinigung bringe er sie zum Priester an den Eingang des Versammlungszeltes vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Und der Priester nehme das Lamm des Schuldopfers und das Log Öl, und der Priester webe sie als Webe vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'Und er schlachte das Lamm des Schuldopfers, und der Priester nehme von dem Blut des Schuldopfers und gebe es dem sich Reinigenden auf das rechte Ohrläppchen und auf den Daumen seiner rechten Hand, und auf die große Zehe seines rechten Fußes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Und von dem Öl gieße der Priester auf des Priesters linke flache Hand,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'Und es spritze der Priester mit seinem rechten Finger siebenmal von dem Öl auf seiner linken flachen Hand vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'Und der Priester gebe von dem Öl auf seiner flachen Hand auf das rechte Ohrläppchen des zu Reinigenden, und auf den Daumen seiner rechten Hand und auf die große Zehe seines rechten Fußes auf den Ort des Blutes des Schuldopfers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Und das übrige von dem Öl auf des Priesters flacher Hand gebe er auf den Kopf des sich Reinigenden, um über ihm zu sühnen vor Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'Und opfere die eine von den Turteltauben oder von den jungen Tauben, wozu seine Hand reicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'Das, wozu seine Hand reicht, die eine als Sündopfer und die andere als Brandopfer, auf dem Speiseopfer; und der Priester sühne über dem sich Reinigenden vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'Dies ist das Gesetz für den, an dem das Aussatzmal war, und dessen Hand zu seiner Reinigung nicht hinreichte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'Und Jehovah redete zu Mose und zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Wenn ihr zum Land Kanaan kommet, das Ich euch zum Eigentum gebe, und Ich tue das Aussatzmal in ein Haus im Lande eures Eigentums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'So komme der, dessen das Haus ist, und sage dem Priester an und spreche: Es hat sich mir etwas wie ein Mal im Haus gezeigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Und der Priester gebiete, daß sie das Haus räumen, bevor der Priester kommt, um das Mal zu sehen, auf daß nicht alles im Hause unrein werde; und danach gehe der Priester hinein, das Haus zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'Und sieht er das Mal, und siehe, das Mal ist an den Wänden des Hauses: grünliche oder rötliche Vertiefungen, und ihr Ansehen ist niedriger als die Wand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'So gehe der Priester aus dem Haus an den Eingang des Hauses und verschließe das Haus für sieben Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'Und am siebenten Tage kehre der Priester zurück und sehe es, und siehe, hat das Mal an den Wänden des Hauses um sich gegriffen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'So gebiete der Priester, die Steine, an denen das Mal ist, herauszuziehen und sie sollen sie hinaus zur Stadt an einen unreinen Ort werfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Und das Haus kratze man von innen ringsum ab und schütte den Staub, den man abgekratzt, außerhalb der Stadt an einen unreinen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'Und sie sollen andere Steine nehmen und sie an die Stelle der Steine bringen, und man nehme anderen Staub und übertünche das Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Wenn aber das Mal zurückkehrt und am Hause ausbricht, nachdem man die Steine herausgezogen, und nachdem man das Haus abgekratzt und nachdem man es übertüncht hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'Und der Priester kommt und sieht, und siehe, das Mal hat um sich gegriffen im Hause, so ist es ein zerfressender Aussatz im Hause: es ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Und man reiße das Haus ein, seine Steine und seine Hölzer und all den Staub des Hauses, und bringe es hinaus außerhalb der Stadt an einen unreinen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'Und wer in das Haus hineingeht in all den Tagen, da er es verschlossen hat, soll unrein sein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'Und wer in dem Hause liegt, soll seine Kleider waschen; und wer im Hause ißt, soll seine Kleider waschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Kommt aber der Priester und sieht, und siehe, das Mal hat im Hause nicht um sich gegriffen, nachdem das Haus übertüncht worden ist, so erkläre der Priester das Haus für rein, denn das Mal ist geheilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'Und er nehme, um das Haus zu entsündigen, zwei Vögel und Zedernholz und Scharlach doppelt gefärbt und Ysop;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'Und schlachte den einen Vogel in ein irdenes Gefäß über lebendigem Wasser,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'Und nehme das Zedernholz und den Ysop und den doppelt gefärbten Scharlach und den lebendigen Vogel und tauche sie in das Blut des geschlachteten Vogels und in die lebendigen Wasser und spritze siebenmal gegen das Haus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'Und entsündige das Haus mit dem Blut des Vogels und mit dem lebendigen Wasser und mit dem lebendigen Vogel und mit dem Zedernholz und mit dem Ysop und mit dem doppelt gefärbten Scharlach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'Und den lebendigen Vogel entsende er hinaus aus der Stadt über das Feld hin, und sühne über dem Haus; und es ist rein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'Dies ist das Gesetz für alles Aussatzmal und den Nethek;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'Und für den Aussatz am Kleide und am Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'Und über die Geschwulst, den Schorf und den lichten Fleck.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'Zu unterweisen über den Tag, da man unrein, und den Tag, da man rein ist. Das ist das Gesetz von dem Aussatz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'Und Jehovah redete zu Mose und zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Redet zu den Söhnen Israels und saget ihnen: Jeder Mann der einen Fluß hat aus seinem Fleische, der ist durch seinen Fluß unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'Und dies soll seine Unreinheit von seinem Flusse sein: Schleimet sein Fleisch von seinem Flusse oder ist sein Fleisch verstopft von seinem Flusse, so ist es seine Unreinheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Alles Lager, auf dem der Flüssige liegt, soll unrein sein; und jegliches Gerät, auf dem er sitzt soll unrein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'Und der Mann, der sein Lager berührt, soll seine Kleider waschen und sich im Wasser baden, und ist bis an den Abend unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'Und wer auf einem Gerät sitzt, auf dem der Flüssige gesessen, der soll seine Kleider waschen und sich im Wasser baden, und bis zum Abend unrein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'Und wer das Fleisch des Flüssigen berührt, soll seine Kleider waschen und sich im Wasser baden und soll unrein sein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'Und wenn der Flüssige auf den Reinen spuckt, so soll dieser seine Kleider waschen und sich im Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Und jeglicher Wagen, in dem der Flüssige fährt, soll unrein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'Und jeder, der irgend etwas berührt, das er unter sich hatte, soll unrein sein bis zum Abend. Und der sie trägt, wasche seine Kleider und bade sich im Wasser, und ist unrein bis an den Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Und jeder, den der Flüssige berührt und seine Hände nicht im Wasser abgespült hatte, soll seine Kleider waschen und sich im Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Und das irdene Gefäß, das der Flüssige berührt, soll zerbrochen, und jedes hölzerne Gefäß soll ausgespült werden im Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Und so der Flüssige rein wird von seinem Flusse, soll er sieben Tage zählen von seiner Reinigung an, und seine Kleider waschen und sein Fleisch in fließendem Wasser baden, und er ist rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Und am achten Tage nehme er für sich zwei Turteltauben oder zwei junge Tauben und komme vor das Angesicht Jehovahs zum Eingang des Versammlungszeltes und gebe sie dem Priester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'Und der Priester mache die eine als Sündopfer und die andere als Brandopfer, und der Priester sühne über ihm vor Jehovah von seinem Flusse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'Und der Mann, von dem ein Samenerguß ausgeht, bade sein ganzes Fleisch im Wasser, und ist unrein bis an den Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'Und jegliches Kleid und jegliches Fell, auf dem von dem Samenerguß ist, werde im Wasser gewaschen, und ist unrein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'Und das Weib, mit dem ein Mann liegt, und der Samen sich ergießt: sie sollen sich im Wasser baden, und sind unrein bis auf den Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'Und so ein Weib flüssig ist, so sie ihren Fluß von Blut hat an ihrem Fleische, soll sie sieben Tage in ihrer Abgeschiedenheit sein, und jeder, der sie berührt, sei unrein bis an den Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'Und alles, worauf sie liegt in ihrer Abgeschiedenheit, ist unrein, und alles, worauf sie sitzt, ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'Und jeder, der ihr Lager berührt, soll seine Kleider waschen und sich im Wasser baden, und ist unrein bis auf den Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'Und jeder, der irgendein Gerät berührt, auf dem sie sitzt, soll seine Kleider waschen und sich im Wasser baden, und ist bis zum Abend unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'Und wenn es auf dem Lager ist oder an dem Gerät, auf dem sie saß, da er es berührt, soll er unrein sein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'Und wenn ein Mann bei ihr liegt und von ihrer Befleckung an ihm ist, so ist er sieben Tage unrein, und das ganze Lager, auf dem er lag, ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'Und wenn einem Weib ihr Blutfluß viele Tage fließt außer der Zeit ihrer Abgeschiedenheit oder derselbe fließt über die Zeit ihrer Abgeschiedenheit hinaus, soll sie alle Tage des Flusses ihrer Unreinheit wie in den Tagen ihrer Abgeschiedenheit unrein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Alles Lager, worauf sie liegt alle Tage ihres Flusses, sei ihr wie das Lager ihrer Abgeschiedenheit, und alles Gerät, worauf sie sitzt, sei unrein, wie die Unreinheit ihrer Abgeschiedenheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'Und jeder, der das anrührt, wird unrein und soll seine Kleider waschen und sich im Wasser baden und unrein sein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'Und wird sie rein von ihrem Flusse, so soll sie sich sieben Tage zählen, und nachher ist sie rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'Und am achten Tage nehme sie für sich zwei Turteltauben oder zwei junge Tauben und bringe sie zum Priester zum Eingang des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'Und der Priester bereite die eine als Sündopfer und die andere als Brandopfer, und der Priester sühne über ihr vor Jehovah von dem Flusse ihrer Unreinheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Und ihr sollt die Söhne Israel absondern von ihrer Unreinheit, auf daß sie nicht sterben in ihrer Unreinheit, indem sie verunreinigen Meine Wohnung in ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'Dies ist das Gesetz für den Flüssigen und von dem Samenerguß ausgeht und der dadurch unrein wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'Und für die, so krank ist in ihrer Abgeschiedenheit und für dasjenige, das am Flusse leidet, männlich oder weiblich, und für den Mann, der bei einer Unreinen liegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'Und Jehovah redete zu Mose nach dem Tode der zwei Söhne Aharons, die sich vor Jehovah nahten und starben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'Und Jehovah sprach zu Mose: Rede zu Aharon, deinem Bruder, daß er nicht zu jeder Zeit eingehe in das Heiligtum innerhalb des Vorhangs vor den Gnadenstuhl, der auf der Lade ist, auf daß er nicht sterbe; denn in der Wolke erscheine Ich auf dem Gnadenstuhl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'So soll Aharon eingehen in das Heiligtum: mit einem jungen Farren zum Sündopfer und einem Widder zum Brandopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Einen Leibrock der Heiligkeit von Lein soll er anziehen, und linnene Beinkleider über seinem Fleische haben, und mit einem linnenen Gürtel sich gürten, und eine linnene Tiara sich umwinden. Kleider der Heiligkeit sind es. Und er soll sein Fleisch im Wasser baden, und sie anziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'Und von der Gemeinde der Söhne Israels soll er zwei Ziegenböcke zum Sündopfer und einen Widder zum Brandopfer nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'Und Aharon bringe den Farren des Sündopfers dar, der für ihn ist, und sühne für sich und für sein Haus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Und nehme die zwei Böcke und lasse sie vor Jehovah am Eingang des Versammlungszeltes stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'Und Aharon gebe Lose über die zwei Böcke; ein Los für Jehovah und das andere Los für Asasel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'Und Aharon bringe den Bock dar, auf den das Los für Jehovah aufkam und mache ihn als Sündopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Und der Bock, auf den das Los für Asasel aufkam, soll lebendig vor Jehovah stehen, um über ihm zu sühnen, und ihn dann für Asasel in die Wüste zu entsenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Und Aharon bringe den Farren des Sündopfers dar, der für ihn ist, und sühne für sich und für sein Haus, und schlachte den Farren des Sündopfers, der für ihn ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'Und nehme eine Rauchpfanne voll Kohlen des Feuers vom Altar vor Jehovah und seine Hände voll zerstoßenes Räuchwerk von Spezereien und bringe sie innerhalb des Vorhangs;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'Und gebe das Räuchwerk auf das Feuer vor Jehovah, auf daß die Wolke des Räuchwerks den Gnadenstuhl über dem Zeugnis bedecke und er nicht sterbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Und er nehme von dem Blute des Farren und spritze mit seinem Finger vor dem Gnadenstuhl gegen Osten und vor den Gnadenstuhl hin spritze er mit seinem Finger siebenmal von dem Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Und er schlachte den Bock des Sündopfers, der für das Volk ist, und bringe sein Blut innerhalb des Vorhangs und tue mit seinem Blut, wie er mit dem Blute des Farren getan, und spritze es auf den Gnadenstuhl und vor den Gnadenstuhl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'Und sühne so über dem Heiligtum wegen der Unreinheiten der Söhne Israels und wegen ihrer Übertretungen nach allen ihren Sünden, und so tue er dem Versammlungszelt, das bei ihnen mitten unter ihren Unreinheiten wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Und kein Mensch soll sein im Versammlungszelt, wenn er hineingeht, zu sühnen in dem Heiligtum, bis er herauskommt, und er sühne für sich und für sein Haus und für die ganze Versammlung Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'Und er komme heraus an den Altar, der vor Jehovah ist, und sühne über ihm, und nehme von dem Blut des Farren und von dem Blut des Bockes und gebe es auf die Hörner des Altars ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'Und er spritze darauf von dem Blute mit seinem Finger siebenmal; und er reinige ihn und heilige ihn von den Unreinheiten der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'Und hat er vollendet zu sühnen das Heiligtum und das Versammlungszelt und den Altar, so bringe er den lebendigen Ziegenbock dar;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'Und Aharon lege seine beiden Hände auf den Kopf des lebendigen Bockes, und bekenne über ihm alle Missetaten der Söhne Israels und alle ihre Übertretungen nach ihren Sünden, und lege sie auf den Kopf des Bockes, und entsende ihn durch die Hand eines Mannes, der bereit ist, in die Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'Und der Bock trage auf sich alle ihre Missetaten in ein abgeschnittenes Land; und er entsende den Bock in die Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Und Aharon gehe ein zum Versammlungszelt, und ziehe die linnenen Kleider aus, die er angezogen, als er in das Heiligtum einging, und lege sie daselbst nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'Und er bade sein Fleisch im Wasser an heiligem Orte, und ziehe seine Kleider an, und komme heraus und mache seine Brandopfer und das Brandopfer des Volkes, und sühne für sich und für das Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'Und das Fett des Sündopfers zünde er auf dem Altar an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'Der aber den Bock zu Asasel entsandte, soll seine Kleider waschen und sein Fleisch im Wasser baden und danach komme er zum Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'Und den Farren des Sündopfers und den Bock des Sündopfers, deren Blut hineingebracht worden war, um im Heiligtum zu sühnen, bringe er hinaus außerhalb des Lagers, und lasse ihre Häute und ihr Fleisch und ihren Mist im Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'Und der sie verbrennt, soll seine Kleider waschen und sein Fleisch im Wasser baden und danach komme er zum Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'Und es sei euch zu ewiger Satzung: Im siebenten Monat, im zehnten des Monats sollet ihr eure Seelen demütigen und keinerlei Arbeit tun, weder der Eingeborene, noch der Fremdling, der in eurer Mitte sich aufhält.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Denn an diesem Tage wird er über euch sühnen, um euch zu reinigen von allen euren Sünden. Vor Jehovah sollt ihr rein werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Ein Sabbath der Sabbathe sei es euch, und ihr sollt eure Seelen demütigen. Eine ewige Satzung sei es!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Und es sühne der Priester, den man salben und dessen Hand man füllen wird, um an seines Vaters Statt den Priesterdienst zu tun; und er soll die linnenen Kleider anziehen, die Kleider der Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'Und er sühne das Allerheiligste, und das Versammlungszelt; und den Altar soll er sühnen, und die Priester und das ganze Volk der Versammlung soll er sühnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'Und ewige Satzung sei das euch, einmal im Jahr die Söhne Israels wegen aller ihrer Sünden zu sühnen. Und er tat, wie Jehovah Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Rede zu Aharon und zu seinen Söhnen und zu allen Söhnen Israels und sprich zu ihnen: Dies ist das Wort, das Jehovah geboten hat und gesagt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Jeder Mann vom Haus Israel, der einen Ochsen oder ein Schaf oder eine Ziege im Lager schlachtet, oder der sie außerhalb des Lagers schlachtet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'Und es nicht zum Eingang des Versammlungszeltes bringt, um es Jehovah vor der Wohnung Jehovahs als Opfergabe darzubringen, dem Manne wird es als Blutschuld gedacht; er hat Blut vergossen; und selbiger Mann soll aus der Mitte seines Volkes ausgerottet werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'Auf daß die Söhne Israels ihre Opfer, die sie auf dem Angesichte des Feldes opfern, herbeibringen dem Jehovah, zum Eingang des Versammlungszeltes zu dem Priester bringen, und sie Jehovah als Dankopfer opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'Und der Priester sprenge das Blut auf Jehovahs Altar am Eingang des Versammlungszeltes und zünde das Fett an zum Geruch der Ruhe für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'Und sie sollen nicht ferner ihre Opfer opfern den Dämonen, denen sie nachbuhlen. Dies sei ihnen eine ewige Satzung für ihre Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Und sage ihnen: Welcher Mann aus dem Hause Israels und von den Fremdlingen, die in eurer Mitte sich aufhalten, ein Brandopfer oder Schlachtopfer aufgehen läßt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'Und es nicht zum Eingang des Versammlungszeltes bringt, um es allda dem Jehovah zu opfern, der Mann werde aus seinem Volke ausgerottet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'Und welcher Mann vom Hause Israels und von den Fremdlingen, die in eurer Mitte sich aufhalten, irgend Blut ißt, wider die Seele, die Blut ißt, werde Ich Mein Angesicht richten, und sie ausrotten aus der Mitte ihres Volkes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Denn die Seele des Fleisches ist in dem Blute, und darum habe Ich sie euch auf den Altar gegeben, um über eure Seelen zu sühnen, weil das Blut es ist, das für die Seele sühnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Deshalb sprach Ich zu den Söhnen Israels: Keine Seele unter euch soll Blut essen; und der Fremdling, der in eurer Mitte sich aufhält, soll kein Blut essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'Und welcher Mann von den Söhnen Israels und von den Fremdlingen, die in eurer Mitte sich aufhalten, ein lebendiges Tier erjagt, oder einen Vogel, der gegessen wird, der gieße sein Blut aus und decke es mit Staub zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Denn die Seele alles Fleisches ist sein Blut; es ist für seine Seele. Und Ich sage den Söhnen Israels: Das Blut alles Fleisches sollt ihr nicht essen; denn die Seele alles Fleisches ist sein Blut. Jeder, der es ißt, soll ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'Und jede Seele, Eingeborener oder Fremdling, der ein Aas oder Zerfleischtes ißt, soll seine Kleider waschen und sich im Wasser baden, und unrein sein bis zum Abend. Dann ist er rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Und wäscht er sie nicht und badet sein Fleisch nicht, so trage er seine Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Rede zu den Söhnen Israels und sprich zu ihnen: Ich bin Jehovah, euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Nach dem Tun des Landes Ägypten, in dem ihr gewohnt, sollt ihr nicht tun, und nach dem Tun des Landes Kanaan, dahin Ich euch bringen werde, sollt ihr nicht tun, und in ihren Satzungen sollt ihr nicht wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Meine Rechte sollt ihr tun und Meine Satzungen halten, um in ihnen zu wandeln. Ich bin Jehovah, euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Und Meine Satzungen und Rechte sollt ihr halten. Der Mensch, der sie tut, der wird leben in ihnen. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Kein Mann soll seiner Fleischesverwandten nahen, ihre Blöße aufzudecken. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Die Blöße deines Vaters und die Blöße deiner Mutter sollst du nicht aufdecken. Deine Mutter ist sie. Du sollst nicht aufdecken ihre Blöße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Die Blöße von deines Vaters Weib sollst du nicht aufdecken: Es ist die Blöße deines Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Die Blöße deiner Schwester, der Tochter deines Vaters oder der Tochter deiner Mutter, sei sie im Hause geboren oder draußen geboren, ihre Blöße sollst du nicht aufdecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Die Blöße der Tochter deines Sohnes oder der Tochter deiner Tochter, ihre Blöße sollst du nicht aufdecken; denn sie sind deine Blöße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Die Blöße der Tochter von deines Vaters Weib, die deinem Vater geboren ist, - sie ist deine Schwester - ihre Blöße sollst du nicht aufdecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Die Blöße der Schwester deines Vaters sollst du nicht aufdecken: sie ist die Verwandte deines Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Du sollst die Blöße der Schwester deiner Mutter nicht aufdecken, denn sie ist die Verwandte deiner Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Du sollst die Blöße des Bruders deines Vaters nicht aufdecken, sollst seinem Weibe nicht nahen; denn sie ist deine Tante.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Du sollst die Blöße deiner Schwiegertochter nicht aufdecken: sie ist deines Sohnes Weib. Du sollst ihre Blöße nicht aufdecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Du sollst die Blöße von deines Bruders Weib nicht aufdecken; denn es ist die Blöße deines Bruders.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Decke nicht auf die Blöße eines Weibes und ihrer Tochter; die Tochter ihres Sohnes und die Tochter ihrer Tochter sollst du nicht nehmen, ihre Blöße aufzudecken. Sie sind Verwandte. Es ist eine Schandtat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Und du sollst nicht ein Weib zu ihrer Schwester nehmen, sie zu bedrängen und ihre Blöße aufzudecken neben ihr bei ihrem Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'Und einem Weibe in der Abgeschiedenheit ihrer Unreinheit sollst du nicht nahen, ihre Blöße aufzudecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Du sollst nicht deines Nächsten Weib Samenerguß geben und unrein werden durch sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'Du sollst nicht von deinem Samen geben, ihn dem Moloch durchziehen zu lassen, auf daß du nicht den Namen deines Gottes entweihst: Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Und bei dem Männlichen sollst du nicht liegen, wie man beim Weibe liegt: ein Greuel ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Und du sollst deinen Erguß keinem Vieh geben, und dich damit verunreinigen. Und kein Weib soll vor dem Vieh stehen, sich mit ihm zu begatten. Eine Besudelung ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Verunreinigt euch mit keinerlei davon; denn mit allem dem verunreinigten sich die Völkerschaften, die Ich vor euch her fortsende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'Und das Land ist unrein geworden, und Ich habe ihre Missetat an ihm heimgesucht, so daß das Land seine Einwohner ausspeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Und haltet Meine Satzungen und Meine Rechte, und tut keinen dieser Greuel, weder Eingeborene, noch der Fremdling, der in eurer Mitte sich aufhält.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, 'Denn alle diese Greuel taten die Männer des Landes, das vor euch ist; und das Land ist verunreinigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'Auf daß euch nicht ausspeie das Land, darum, daß ihr es verunreinigt, wie es die Völkerschaft ausspie, die vor euch gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Denn jeder, der einen dieser Greuel tut, die Seelen, die solches tun, sollen aus ihres Volkes Mitte ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Und ihr sollt halten Meine Vorschrift, daß ihr nach keiner der greulichen Satzungen tut, die vor euch getan worden sind, und ihr dadurch verunreinigt werdet. Ich bin Jehovah, euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Rede zu der ganzen Gemeinde der Söhne Israels und sprich zu ihnen: Ihr sollt heilig sein; denn Ich, Jehovah, euer Gott, bin heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Der Mann fürchte seine Mutter und seinen Vater. Und ihr sollt Meine Sabbathe halten: Ich bin Jehovah, euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Wendet euch nicht zu Götzen, und machet euch nicht gegossene Götter. Ich, Jehovah, bin euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'Und so ihr Jehovah ein Dankopfer opfert, sollt ihr es opfern, daß ihr wohlgefallet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Am Tage, da ihr opfert, soll davon gegessen werden, und am morgenden, was aber bis zum dritten Tage übrig ist, soll im Feuer verbrannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Und so man es am dritten Tage ißt, ist es ein Abscheu und nicht wohlgefällig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'Und der es ißt, trägt seine Missetat, weil er das Heilige Jehovahs entweiht hat, und solche Seele soll aus ihrem Volke ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'Und wenn ihr die Ernte von eurem Lande einerntet, sollst du nicht die Ecken deines Feldes ganz einernten, auch nicht die Nachlese von deiner Ernte auflesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'Und auf deinem Weinberg sollst du nicht nachlesen und das Zerstreute auf deinem Weinberg nicht auflesen; dem Elenden und dem Fremdling lasse es: Ich, Jehovah, bin dein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ihr sollt nicht stehlen und nicht trügen und lügen der Mann gegen seinen Nächsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'Und ihr sollet nicht zur Lüge schwören bei Meinem Namen, so daß du den Namen deines Gottes entweihst. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Du sollst deinen Genossen nicht bedrükken, noch ihm etwas entreißen; und der Arbeitslohn des Lohnarbeiters soll nicht bei dir über Nacht bleiben bis zum Morgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Dem Tauben sollst du nicht fluchen, und vor den Blinden keinen Anstoß legen, und dich vor deinem Gotte fürchten: Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'Ihr sollt nichts Verkehrtes tun beim Richten, nicht das Angesicht des Armen erheben, noch das Angesicht des Großen ehren: gerecht sollst du deinen Nächsten richten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Gehe nicht umher als Zwischenträger unter deinem Volke, und stehe nicht nach dem Blute deines Genossen. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Du sollst deinen Bruder nicht hassen in deinem Herzen, sondern sollst deinen Nächsten rügen, daß du darob keine Sünde tragest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Du sollst dich nicht rächen und den Söhnen deines Volkes nichts nachtragen, und sollst deinen Genossen lieben, wie dich selbst. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Meine Satzungen sollet ihr halten: Laß nicht zweierlei Vieh sich begatten; säe nicht zweierlei auf dein Feld, und ein Kleid, aus zweierlei Stoffen gewebt, komme nicht auf dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'Und wenn ein Mann bei einem Weibe liegt mit Samenerguß, und es ist eine Dienstmagd, einem Manne hingegeben, aber noch nicht eingelöst, noch ihr Freiheit gegeben, so soll das gezüchtigt werden; sie sollen aber nicht getötet werden; denn sie war nicht frei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'Und er bringe für seine Schuld dem Jehovah am Eingang des Versammlungszeltes einen Widder zum Schuldopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'Und der Priester sühne über ihm mit dem Widder des Schuldopfers vor Jehovah ob der Sünde, die er gesündigt; auf daß die Sünde, die er gesündigt, ihm verziehen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'Und so ihr in das Land kommet und allerlei Fruchtbäume pflanzet, so beschneidet die Vorhaut ihrer Frucht. Drei Jahre sollen sie euch unbeschnitten sein und soll nicht von ihnen gegessen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'Und im vierten Jahre sei all seine Frucht Heiligkeit zum Lobe Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'Und im fünften Jahre sollt ihr seine Frucht essen, daß ihr seinen Ertrag für euch einsammelt. Ich, Jehovah, bin euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ihr sollet nichts mit Blut essen; sollt nicht Beschwörungen noch Wolkendeuterei treiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ihr sollt den Rand eures Haupthaares nicht rund abschneiden, noch die Ecke eures Bartes verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'Und ihr sollt um einer Seele willen euch keine Einschnitte in euer Fleisch machen, noch euch Einätzung geben einer Schrift. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Entweihe nicht deine Tochter, sie buhlen zu lassen, auf daß nicht das Land buhle und das Land voller Schandtat werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Meine Sabbathe sollt ihr halten, und Mein Heiligtum fürchten. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Wendet euch nicht zu den Geisterbannern und Zeichendeutern. Befraget sie nicht, auf daß ihr nicht durch sie verunreinigt werdet. Ich, Jehovah, bin euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Vor einem Greisen sollst du aufstehen, und des Alten Angesicht ehren, und dich vor deinem Gotte fürchten. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'Und wenn ein Fremdling bei dir in deinem Lande sich aufhält, so sollt ihr ihn nicht bedrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'Wie der Eingeborene unter euch sei euch der Fremdling, der bei euch sich aufhält. Und du sollst ihn lieben, wie dich selbst; denn Fremdlinge seid ihr in Ägyptenland gewesen. Ich, Jehovah, bin euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Tut nicht Verkehrtes im Gericht, im Längenmaß, im Gewicht und im Hohlmaß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'Waagen der Gerechtigkeit, Gewichtsteine der Gerechtigkeit, ein Epha der Gerechtigkeit, ein Hin der Gerechtigkeit sollt ihr haben: Ich bin Jehovah, euer Gott, Der euch aus Ägyptenland herausbrachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Und haltet alle Meine Satzungen und alle Meine Rechte und tut sie. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Und sprich zu den Söhnen Israels: Jeder Mann von den Söhnen Israels und der Fremdling, der in Israel sich aufhält, der dem Moloch von seinem Samen gibt, soll des Todes sterben; das Volk des Landes soll ihn mit Steinen steinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Und Ich werde Mein Angesicht setzen wider solchen Mann und ihn ausrotten aus seines Volkes Mitte, darum, daß er von seinem Samen dem Moloch gegeben, so daß er Mein Heiligtum verunreinigt und Meiner Heiligkeit Namen entweiht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'Und wenn das Volk des Landes seine Augen verbirgt von solchem Manne, wenn er von seinem Samen dem Moloch gibt, so daß es ihn nicht tötet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'So will Ich Mein Angesicht setzen wider solchen Mann und wider seine Familie, und ihn und alle, die ihm nachbuhlen, um dem Moloch nachzubuhlen, ausrotten aus ihres Volkes Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Und wider die Seele, die sich zu den Geisterbannern und Zeichendeutern wendet, um ihnen nachzubuhlen, wider solche Seele werde Ich Mein Angesicht setzten und sie ausrotten aus ihres Volkes Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Und heiliget euch, auf daß ihr heilig seid; denn Ich, Jehovah, bin euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'Und haltet Meine Satzungen und tut sie: Ich bin Jehovah, Der euch heiligt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Denn jeder Mann, der seinem Vater oder seiner Mutter flucht, soll des Todes sterben. Seinem Vater und seiner Mutter hat er geflucht. Sein Blut sei auf ihm!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'Und ein Mann, der die Ehe bricht mit dem Weib eines Mannes; wer die Ehe bricht mit dem Weib seines Genossen, soll des Todes sterben, der Ehebrecher und die Ehebrecherin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'Und der Mann, der bei seines Vaters Weibe liegt, hat seines Vaters Blöße aufgedeckt. Beide sollen des Todes sterben. Ihr Blut sei auf ihnen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'Und der Mann, der bei seiner Schwiegertochter liegt: sie sollen beide des Todes sterben; sie haben eine Besudelung gemacht. Ihr Blut sei auf ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'Und der Mann, so bei einem, der männlich ist, liegt, wie man bei einem Weibe liegt: die beiden haben einen Greuel getan. Sie sollen des Todes sterben. Ihr Blut sei auf ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'Und der Mann, so ein Weib nimmt und ihre Mutter dazu: eine Schandtat ist es. Im Feuer sollen sie ihn und sie beide verbrennen, auf daß keine Schandtat sei in eurer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'Und so ein Mann einem Vieh einen Erguß gibt, so soll er des Todes sterben, und auch das Tier erwürge man.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'Und so ein Weib zu irgendeinem Vieh sich naht, um sich mit ihm zu begatten, sollst du das Weib und das Vieh erwürgen. Sie sollen des Todes sterben. Ihr Blut sei über ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'Und so ein Mann seine Schwester, die Tochter seines Vaters, oder die Tochter seiner Mutter nimmt, und sieht ihre Blöße, und sie sieht seine Blöße, so ist es Blutschande, und sie sollen vor den Augen der Söhne ihres Volkes ausgerottet werden: er hat die Blöße seiner Schwester aufgedeckt. Er trage seine Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'Und so ein Mann bei einem Weibe in ihrer Krankheit liegt, und deckt ihre Blöße auf, und er hat ihren Born entblößt, und sie hat den Born ihres Blutes aufgedeckt, und sie sollen beide aus ihres Volkes Mitte ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'Und die Blöße der Schwester deiner Mutter und der Schwester deines Vaters sollst du nicht aufdecken; denn ein solcher hat das ihm Verwandte entblößt. Sie sollen ihre Missetat tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'Und so ein Mann bei seiner Muhme liegt, hat er seines Oheims Blöße aufgedeckt. Sie haben ihre Sünde zu tragen; sie sollen kinderlos sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'Und wenn ein Mann das Weib seines Bruders nimmt, so ist es eine Befleckung. Er hat die Blöße seines Bruders aufgedeckt. Sie sollen kinderlos sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Und ihr sollt halten alle Meine Satzungen und alle Meine Rechte und sie tun, auf daß euch nicht ausspeie das Land, in das Ich euch bringe, um darin zu wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'Und sollt nicht wandeln in den Satzungen der Völkerschaft, die Ich vertreibe vor euch; denn alles dies hatten sie getan, und sind Mir zum Überdruß geworden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'Und habe euch gesagt: Ihr sollt ihren Boden erblich besitzen, und Ich will ihn euch zum Erbbesitze geben, ein Land, das von Milch und Honig fließt. Ich, Jehovah, bin euer Gott, Der euch von den Völkern geschieden hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'So scheidet denn zwischen reinem und unreinem Vieh und zwischen unreinem und reinem Gevögel, und macht eure Seelen nicht zum Abscheu mit Vieh oder Gevögel, noch mit irgend etwas, das auf dem Boden kriecht, und das Ich für euch ausgeschieden habe, daß es unrein sei;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'Und seid Mir heilig; denn Ich, Jehovah, bin heilig und habe euch von den Völkern ausgeschieden, auf daß ihr Mein sein sollet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Und Mann oder Weib, die unter euch Geisterbanner oder Zeichendeuter sind, sollen des Todes sterben. Mit Steinen soll man sie steinigen! Ihr Blut sei über ihnen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'Und Jehovah sprach zu Mose: Sprich zu den Priestern, den Söhnen Aharons, und sage ihnen: Keiner verunreinige sich an einer Seele in seinem Volke;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'Außer an seinem Verwandten, der ihm am nächsten ist, seiner Mutter und seinem Vater, und seinem Sohne und seiner Tochter und seinem Bruder,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'Und seiner Schwester, die eine Jungfrau und ihm nahe ist, und noch keinen Mann hatte. An ihr darf er unrein werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Er soll sich nicht verunreinigen als Herr in seinem Volke, so daß er dadurch entweiht würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Sie sollen sich keine Kahlheit auf dem Haupte machen, und die Ecke ihres Bartes nicht scheren, noch Einschnitte an ihrem Fleische einschneiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sie sollen ihrem Gott heilig sein, und den Namen ihres Gottes nicht entweihen; denn die Feueropfer Jehovahs, das Brot ihres Gottes bringen sie dar; darum seien sie heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Sie sollen kein Weib, das eine Buhlerin ist, noch eine Entweihte nehmen, noch sollen sie eine, die von ihrem Manne verstoßen worden, nehmen; denn heilig ist er seinem Gotte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Und du sollst ihn heilig halten; denn das Brot deines Gottes bringt er dar. Heilig sei er dir; denn heilig bin Ich, Jehovah, Der euch heiligt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Und die Tochter eines Mannes, der Priester ist, die zu buhlen anfängt, entweiht ihren Vater, und soll im Feuer verbrannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Aber wer Hohepriester ist unter seinen Brüdern, auf dessen Haupt das Salböl gegossen, und dessen Hand gefüllt worden ist, die Kleider anzuziehen, der soll sein Haupt nicht blößen und seine Kleider nicht aufreißen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'Und soll zu keiner Seele gehen, darf sich weder bei seinem Vater, noch bei seiner Mutter verunreinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'Und aus dem Heiligtum komme er nicht heraus, auf daß er das Heiligtum seines Gottes nicht entweihe; denn die Weihe des Salböls seines Gottes ist auf ihm. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'Und er soll ein Weib in ihrer Jungfrauschaft nehmen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Keine Witwe, keine Verstoßene, keine Entweihte, keine Buhlerin; keine solche soll er nehmen, sondern eine Jungfrau von seinem Volke nehme er zum Weibe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'Und er soll seinen Samen nicht entweihen in seinem Volk; denn Ich, Jehovah, heilige ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Rede zu Aharon und sprich: Kein Mann deines Samens in seinen Geschlechtern, an dem ein Makel ist, soll sich nahen das Brot seines Gottes darzubringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'Denn kein Mann, an dem ein Makel ist, soll sich nahen, kein blinder Mann oder Lahmer oder an dem etwas zu kurz oder zu lang ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'Oder ein Mann, dem ein Fuß gebrochen oder eine Hand gebrochen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'Oder ein Mann, der höckerig oder abgemagert ist, oder einen Fleck im Auge oder die Krätze oder die Flechte oder zerdrückte Hoden hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Kein Mann vom Samen des Priesters Aharon, der einen Makel an ihm hat, soll herzutreten, die Feueropfer Jehovahs darzubringen. Ein Makel ist an ihm: er darf nicht herzutreten, das Brot seines Gottes darzubringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Das Brot seines Gottes vom Hochheiligen und vom Heiligen darf er essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'Nur zum Vorhang darf er nicht eingehen, und zum Altar nicht hinzutreten; denn ein Makel ist an ihm, auf daß er Meine Heiligtümer nicht entweihe; denn Ich, Jehovah, bin es, Der sie heiligt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'Und Mose redete so zu Aharon und zu seinen Söhnen und zu allen Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Rede zu Aharon und zu seinen Söhnen, daß sie sich absondern von dem, was die Söhne Israels heiligen, und den Namen Meiner Heiligkeit nicht entweihen in dem, was sie Mir heiligen: Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Sage ihnen in euren Geschlechtern: Jeder Mann, der von all eurem Samen den Heiligtümern naht, welche die Söhne Israels Jehovah heiligen, und hat seine Unreinheit an sich, solche Seele soll von Meinem Angesichte ausgerottet werden: Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Jeder Mann, der vom Samen Aharons aussätzig oder flüssig ist, soll nicht von dem Geheiligten essen, bis er rein ist, und wer irgend jemand berührt, der durch eine Seele verunreinigt ist, oder einen Mann, von dem der Samenerguß ausgeht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'Oder ein Mann, der irgendein Kriechtier berührt, an dem er unrein wird, oder einen Menschen, an dem er unrein wird durch irgendwelche Verunreinigung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'Die Seele, die solches berührt, soll unrein sein bis zum Abend, und soll nicht essen von dem Geheiligten, er habe denn zuvor sein Fleisch im Wasser gebadet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'Ist dann die Sonne untergegangen, so ist er rein und nachher darf er von dem Geheiligten essen; denn sein Brot ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Ein Aas oder Zerfleischtes soll er nicht essen, auf daß er nicht dadurch unrein werde; Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Halten sollen sie Meine Verordnungen, auf daß sie darob keine Sünde tragen und sterben, wenn sie es entweihen. Ich, Jehovah, heilige sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Und kein Fremder soll Heiliges essen. Kein Beisaß und kein Lohnarbeiter des Priesters soll Heiliges essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Erwirbt aber der Priester eine Seele durch Erwerbung mit seinem Silber, mag solche davon essen, und der in seinem Hause geboren ward, sie dürfen von seinem Brote essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'Und die Tochter eines Priesters, die eines fremden Mannes wird, darf von der Hebe des Geheiligten nicht essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Und die Tochter eines Priesters, die Witwe wird oder verstoßen ist und keinen Samen hat, und in das Haus ihres Vaters zurückkehrt, darf, wie in ihrer Jugend, vom Brote ihres Vaters essen; aber kein Fremder darf davon essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Und so ein Mann aus Versehen Heiliges ißt, tue er das Fünftel davon dazu und gebe dem Priester das Heilige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Und sie sollen das Heilige der Söhne Israels, das sie Jehovah heben, nicht entweihen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'Auf daß sie nicht die Missetat der Schuld tragen, indem sie ihr Heiliges essen; denn Ich, Jehovah, bin es, Der sie heiligt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Rede zu Aharon und zu seinen Söhnen und zu allen Söhnen Israels und sage ihnen: Jeder Mann vom Hause Israel oder von den Fremdlingen in Israel, der seine Opfergabe darbringt, irgendein Gelobtes und irgendein Freiwilliges, das sie Jehovah zum Brandopfer darbringen wollen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'Daß ihr wohlgefällig seid, so sei es ein Männliches ohne Fehl vom Rind, von Schafen und von Ziegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Keines, an dem ein Makel ist, sollt ihr darbringen; denn ihr würdet damit nicht wohlgefällig werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'Und wenn ein Mann Jehovah ein Dankopfer, für ein besonders gelobtes, oder als sein freiwilliges darbringen will vom Rind oder vom Kleinvieh, so es ohne Fehl ist, ist es wohlgefällig; kein Makel sei daran.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Ist es blind oder gebrochen oder verwundet, oder eiternd oder krätzig oder mit Flechten behaftet, solche sollt ihr Jehovah nicht darbringen. Und kein Feueropfer sollt ihr davon auf den Altar dem Jehovah geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Als freiwilliges Opfer magst du einen Ochsen oder ein Schaf, dem etwas zu lang oder zu kurz ist, darbringen, aber als gelobtes Opfer ist es nicht wohlgefällig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Etwas Zerdrücktes aber, und Zerstoßenes und Zerrissenes und Geschnittenes sollt ihr nicht Jehovah darbringen; und sollt dergleichen nicht in eurem Lande tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Und von der Hand eines Sohnes des Auslandes sollt ihr dergleichen nicht darbringen als Brot eures Gottes; denn ihre Verderbnis ist an ihnen; ein Makel ist an ihnen: ihr könnt damit nicht wohlgefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Ochse oder Schaf oder Ziege, so geboren wird, soll sieben Tage unter dessen Mutter sein, und vom achten Tage an und fürder ist es als Opfergabe wohlgefällig zu einem Feueropfer für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Und Ochse oder Schaf, es selbst und sein Junges, sollt ihr nicht an einem Tage schlachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'Und so ihr Jehovah ein Lobopfer opfert, sollt ihr es zu eurem Wohlgefallen opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Am selben Tage soll es gegessen werden und nichts davon bis zum Morgen übrigbleiben. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Und haltet Meine Gebote und tut sie. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'Und entweihet nicht den Namen Meiner Heiligkeit, auf daß Ich geheiligt werde inmitten der Söhne Israels. Ich bin Jehovah, Der euch heiligt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'Der euch aus Ägyptenland herausgebracht, euch Gott zu sein, Ich, Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Rede zu den Söhnen Israels und sprich zu ihnen: Anlangend die Feiertage Jehovahs, die ihr ausrufen sollt, als Zusammenberufungen der Heiligkeit, so sind dies Meine Feiertage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Sechs Tage soll man Arbeit tun; und am siebenten Tag ist Sabbath der Sabbathe, Zusammenberufung der Heiligkeit. Keinerlei Arbeit sollet ihr tun. Ein Sabbath sei es für Jehovah in allen euren Wohnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'Dies sind Jehovahs Feiertage, Zusammenberufungen der Heiligkeit die ihr an den Feiertagen berufen sollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Im ersten Monat, am vierzehnten des Monats gegen Abend ist das Passah Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'Und am fünfzehnten Tage dieses Monats ist das Fest des Ungesäuerten für Jehovah. Sieben Tage sollt ihr Ungesäuertes essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Am ersten Tage soll bei euch Zusammenberufung der Heiligkeit sein. Keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'Und sieben Tage sollt ihr Jehovah ein Feueropfer darbringen. Am siebenten Tage ist Zusammenberufung der Heiligkeit. Keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Rede zu den Söhnen Israels und sage ihnen: Wenn ihr in das Land kommet, daß Ich euch gebe, und ihr seine Ernte einerntet, so sollt ihr die Erstlingsgarbe eurer Ernte zum Priester bringen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'Und er webe die Garbe vor Jehovah, auf daß ihr wohlgefallet. Am morgenden Tag nach dem Sabbath webe sie der Priester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Und ihr sollt am Tage, da ihr die Garbe webt, ein einjähriges Lamm ohne Fehl Jehovah als Brandopfer bereiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'Und sein Speiseopfer: zwei Zehntel Semmelmehl mit Öl vermischt als Feueropfer für Jehovah zum Geruch der Ruhe, und sein Trankopfer ein viertel Hin Wein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'Und Brot und geröstete und frische Ähren sollt ihr nicht essen bis zu demselben Tag, da ihr die Opfergabe eures Gottes gebracht. Eine ewige Satzung sei es für eure Geschlechter in allen euren Wohnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Und zählet für euch vom morgenden Tage nach dem Sabbath, von dem Tage an, da ihr die Garbe der Webe gebracht; sieben ganze Wochen sollen es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'Bis zum morgenden Tag nach dem siebenten Sabbathe sollt ihr zählen, fünfzig Tage, und ein neues Speiseopfer dem Jehovah darbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Aus euren Wohnungen sollt ihr Webebrot bringen, zwei von zwei Zehnteln Semmelmehls sollen es sein; gesäuert sollen sie gebakken werden, als Erstlingsgaben für Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'Und zu dem Brote sollt ihr darbringen sieben einjährige Lämmer ohne Fehl, und einen jungen Farren vom Rind und zwei Widder. Sie sollen ein Brandopfer sein für Jehovah, und ihr Speiseopfer und ihr Trankopfer als Feueropfer zum Geruch der Ruhe für Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'Und sollt einen Ziegenbock als Sündopfer machen, und als Dankopfer zwei einjährige Lämmer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'Und der Priester webe sie auf dem Erstlingsbrote als Webe vor Jehovah samt den zwei Lämmern. Geheiligt seien sie Jehovah für den Priester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'Und rufet denselben Tag aus: Eine Zusammenberufung der Heiligkeit soll es für euch sein. Keine Dienstarbeit sollt ihr tun. Eine ewige Satzung sei dies in all euren Wohnsitzen für eure Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'Und so ihr die Ernte eures Landes einerntet, sollst du nicht vollenden die Ecke deines Feldes beim Einernten, auch eine Nachlese deiner Ernte sollst du nicht auflesen. Dem Elenden und dem Fremdling sollst du es lassen. Ich bin Jehovah, euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Rede zu den Söhnen Israels und sprich: Im siebenten Monat, am ersten des Monats soll euch ein Sabbath sein, zum Gedächtnistag des Lärmblasens, eine Zusammenberufung der Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Keine Dienstarbeit sollt ihr tun, und dem Jehovah ein Feueropfer darbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Jedoch am zehnten dieses siebenten Monats sei euch der Sühnungstag; eine Zusammenberufung der Heiligkeit soll es für euch sein. Und ihr sollt eure Seele demütigen und Jehovah ein Feueropfer darbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Und keine Arbeit sollt ihr an diesem selbigen Tage tun, denn ein Tag der Sühnung ist er, euch zu sühnen vor Jehovah, eurem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Denn jede Seele, die an diesem selbigen Tage sich nicht demütigt, soll aus ihrem Volke ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'Und jede Seele, die irgendeine Arbeit an diesem selbigen Tage tut, die Seele werde Ich aus der Mitte ihres Volkes zugrunde richten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Keine Arbeit sollt ihr tun. Dies sei ewige Satzung für eure Geschlechter in all euren Wohnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Ein Sabbath der Sabbathe sei es euch, und ihr sollet eure Seelen demütigen. Am neunten des Monats am Abend sollt ihr euern Sabbath feiern vom Abend bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Rede zu den Söhnen Israels und sprich: Am fünfzehnten Tage dieses siebenten Monats ist das Laubhüttenfest sieben Tage für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Am ersten Tage sei Zusammenberufung der Heiligkeit. Keine Dienstarbeit sollt ihr tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sieben Tage sollt ihr Jehovah Feueropfer darbringen; am achten Tage sei Zusammenberufung der Heiligkeit für euch, und ihr sollt Jehovah ein Feueropfer bringen. Eine Festversammlung ist es; da sollt ihr keine Dienstarbeit tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'Dies sind die Festzeiten Jehovahs, die ihr für Zusammenberufungen der Heiligkeit ausrufen sollt, um Jehovah Feueropfer darzubringen, Brandopfer und Speiseopfer, Schlachtopfer und Trankopfer, jeden Tages Sache an seinem Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'Außer den Sabbathen Jehovahs, und außer euren Gaben, und außer allen euren Gelübden und außer allen euren freiwilligen Opfern, die ihr Jehovah geben werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Jedoch sollt ihr am fünfzehnten Tage des siebenten Monats, da ihr des Landes Ertrag einsammelt, sieben Tage das Fest Jehovahs feiern. Am ersten Tage ist Sabbath und am achten Tage Sabbath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'Und nehmet euch am ersten Tage Frucht vom Zierbaum, Palmzweige und Zweige von dichtbelaubten Bäumen und Weiden des Baches und seid fröhlich sieben Tage vor Jehovah, eurem Gotte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'Und feiert es als ein Fest für Jehovah sieben Tage im Jahr. Eine ewige Satzung sei es für eure Geschlechter. Im siebenten Monat sollt ihr es feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'In Hütten sollt ihr wohnen sieben Tage; alle Eingeborene in Israel sollen in Hütten wohnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'Auf daß eure Geschlechter wissen, daß Ich die Söhne Israels in Hütten wohnen ließ, da Ich sie aus Ägyptenland herausbrachte. Ich, Jehovah, bin euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'Und Mose redete von den Festzeiten Jehovahs zu den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Gebeut den Söhnen Israels, daß sie vor dich lauteres Öl von zerstoßenen Oliven bringen zur Beleuchtung, um beständig die Lampen aufzustecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Außerhalb des Vorhangs des Zeugnisses im Versammlungszelt soll Aharon es anordnen vom Abend bis zum Morgen vor Jehovah beständig. Es sei eine ewige Satzung für eure Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Auf dem reinen Leuchter ordne er die Lampen an vor Jehovah beständig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'Und nimm Semmelmehl und backe es zu zwölf Kuchen, zwei Zehntel, sei jeder Kuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'Und lege sie in zwei Reihen sechs in eine Reihe auf den reinen Tisch vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'Und gib auf die Reihe lauteren Weihrauch, und es sei zum Brote, zum Gedenken, ein Feueropfer für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Am Sabbathtage, am Sabbathtage soll er es anordnen vor Jehovah beständig, es ist von den Söhnen Israels, zum ewigen Bunde!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'Und es sei für Aharon und für seine Söhne, und sie sollen es essen an heiligem Orte; denn hochheilig ist es ihm von den Feueropfern Jehovahs, eine ewige Satzung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'Und es ging hinaus der Sohn eines israelitischen Weibes, und er war Sohn eines Ägypters, mitten unter die Söhne Israels, und es zankten sich in dem Lager der Sohn der Israelitin und ein israelitischer Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'Und der Sohn des israelitischen Weibes verwünschte den Namen und fluchte und sie brachten ihn zu Mose. Und der Name seiner Mutter war Schelomith, Dibris Tochter, vom Stamme Dan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'Und sie legten ihn in Gewahrsam nieder, um sie nach dem Munde Jehovahs zu bescheiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Bringe den, der da fluchte, hinaus, außerhalb des Lagers, und alle, die es hörten, sollen ihre Hände auf sein Haupt legen, und die ganze Gemeinde soll ihn steinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Und zu den Söhnen Israels sollst du reden und sprechen: Jeglicher Mann, der seinem Gotte flucht, der trage denn seine Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'Und wer den Namen Jehovahs verwünscht, der soll des Todes sterben; ihn steinige die ganze Gemeinde, wie der Fremdling so der Eingeborene; wenn er den Namen verwünscht, soll er sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'Und der Mann, der die Seele irgendeines Menschen schlägt, der soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'Und wer die Seele des Viehs schlägt, der soll erstatten Stück für Stück, Seele für Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'Und der Mann, der seinen Nächsten verletzt, dem soll man tun, wie er getan hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'Bruch um Bruch, Auge um Auge, Zahn um Zahn, der gleiche Makel, den er einem Menschen angetan, werde auch ihm angetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Und wer ein Vieh erschlägt, der soll es erstatten, und wer einen Menschen erschlägt, soll sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Ein Recht sei bei euch, wie für den Eingeborenen, so für den Fremdling sei es; denn Ich bin Jehovah, euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'Und Mose redete zu den Söhnen Israels, und sie brachten den Flucher aus dem Lager hinaus und steinigten ihn mit Steinen; und die Söhne Israels taten, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'Und Jehovah redete zu Mose auf dem Berge Sinai und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Rede zu den Söhnen Israels und sprich zu ihnen: Wenn ihr in das Land kommet, das Ich euch gebe, soll das Land Jehovah einen Sabbath feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Sechs Jahre sollst du dein Feld besäen, und sechs Jahre deinen Weinberg beschneiden und seinen Ertrag sammeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'Aber im siebenten Jahr soll für das Land ein Sabbath der Sabbathe sein, ein Sabbath für Jehovah; dein Feld sollst du nicht besäen und deinen Weinberg nicht beschneiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Den Nachwuchs deiner Ernte sollst du nicht einernten, und die Weinbeeren deines ungeschnittenen nicht lesen: ein Jahr des Sabbaths sei es dem Lande!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'Und der Sabbath des Landes ist euch zur Speise; für dich und für deinen Knecht und für deine Magd, und für deinen Lohnarbeiter und für deinen Beisassen, die sich bei dir aufhalten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'Und für dein Vieh und für das Wild in deinem Lande soll all sein Ertrag zur Speise sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Und zähle dir sieben Sabbathe der Jahre, sieben Jahre siebenmal, und die Tage der sieben Sabbathjahre seien neunundvierzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'Und laß im siebenten Monat am zehnten des Monats die Posaunen zum Lärmblasen durchziehen; am Tage der Sühnung durchziehe die Posaune all euer Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'Und heiligen sollt ihr das Jahr, das fünfzigste Jahr, und Freilassung ausrufen im Lande für alle seine Einwohner. Ein Jubel soll es euch sein. Und jeder Mann kehre zu seinem Eigentum, und jeder Mann zu seiner Familie zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Ein Jubeljahr soll das fünfzigste Jahr euch sein. Ihr sollt nicht säen, noch seinen Nachwuchs einernten, und nicht lesen, von dem ungeschnittenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Denn ein Jubel ist es, heilig sei es euch. Vom Feld weg esset den Ertrag davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'In diesem Jubeljahr kehre jeder Mann zu seinem Eigentum zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'Und so ihr verkauft an euern Nächsten einen Verkauf oder kauft von der Hand eures Nächsten, so bedrücke kein Mann seinen Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Nach der Zahl der Jahre nach dem Jubel sollst du von deinem Nächsten kaufen, nach der Zahl der Jahre des Ertrages soll er an dich verkaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Je nach der Menge der Jahre sollst du den Kaufpreis mehren, und nach den wenigeren Jahren den Kaufpreis weniger machen; denn die Zahl der Erträge verkauft er dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Es bedrücke kein Mann seinen Nächsten: und fürchte dich vor deinem Gott! Denn Ich bin Jehovah, euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Und tut nach Meinen Satzungen und haltet Meine Rechte und tut sie, so werdet ihr in Sicherheit im Lande wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'Und das Land wird seine Frucht geben, und ihr werdet essen zur Sättigung und darin wohnen in Sicherheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Und wenn ihr sprechet: Was sollen wir essen im siebenten Jahr? Siehe, wir säen nicht und werden auch nicht einsammeln unseren Ertrag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Ich aber will Meinem Segen über euch gebieten im sechsten Jahr, daß es den Ertrag für die drei Jahre traget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'Und wenn ihr säet im achten Jahr, sollt ihr vom alten Ertrage essen, bis in das neunte Jahr, bis sein Ertrag kommt, sollt ihr Altes essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'Und das Land darf nicht verkauft werden, so daß es verfallen bliebe; denn Mein ist das Land. Ihr seid Fremdlinge und Beisassen bei Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Und im ganzen Lande eures Eigentums, sollt ihr Lösung geben für das Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'So dein Bruder verarmt und von seinem Eigentum verkauft, so komme sein nächster Löser und löse, was sein Bruder verkauft hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Ist aber kein Löser für den Mann da, und seine Hand reicht aus, daß er genügend findet für die Lösung,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'So rechne er die Jahre des Verkaufs und gebe das Überflüssige dem Manne, dem er verkauft hat, zurück, und kehre in sein Eigentum zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Und findet seine Hand nicht genug zum Rückkauf, so sei sein Verkauftes in der Hand des Käufers bis zum Jubeljahr; und es gehe aus in dem Jubeljahr, und er kehre in sein Eigentum zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Und so ein Mann ein Haus zum Wohnsitz in einer Stadt mit Mauern verkauft, so steht ihm Lösung zu, bis das Jahr ganz ist seit dem Verkauf. Ein volles Jahr sei ihm Lösung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Wird es aber, ehe das ganze Jahr voll wird, nicht gelöst, so soll das Haus in der Stadt, die eine Mauer hat, dem Käufer in seinen Geschlechtern verfallen sein; es wird nicht ausgehen im Jubeljahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Und die Häuser der Dörfer, die keine Mauer ringsum haben: ein solches wird zu dem Felde des Landes gerechnet, Lösung soll sein für dasselbe, und es soll ausgehen im Jubeljahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Und anlangend die Städte der Leviten, die Häuser in den Städten ihres Eigentums, sollen die Leviten ewiges Lösungsrecht haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'Und wer etwas löst von den Leviten, dem soll das Verkaufte des Hauses und seiner Eigentumsstadt durch den Jubel ausgehen, denn die Häuser der Städte der Leviten sind ihr Eigentum inmitten der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Und das Feld im Weichbild ihrer Städte soll nicht verkauft werden; denn ein ewiges Eigentum ist es ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'Und wenn dein Bruder verarmt und seine Hand wankt bei dir, so sollst du ihn stärken, als Fremdling oder Beisasse, daß er bei dir lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Nimm keine Zinsen von ihm und keine Mehrung, und fürchte dich vor deinem Gott, auf daß dein Bruder bei dir lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Gib ihm dein Silber nicht auf Zins, und auf Mehrung gib ihm deine Speise nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Ich bin Jehovah, euer Gott, Der Ich euch aus Ägyptenland herausbrachte, um euch das Land Kanaan zu geben, auf daß Ich euer Gott sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'Und wenn dein Bruder bei dir verarmt und sich dir verkauft, so sollst du dich seiner nicht zum Knechtdienst bedienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'Wie ein Lohnarbeiter, wie ein Beisasse sei er bei dir. Bis zum Jubeljahr soll er bei dir dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Und dann soll er von dir ausgehen, er und seine Söhne mit ihm, und zurückkehren zu seiner Familie, und in das Eigentum seiner Väter soll er zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Denn Meine Knechte sind sie, die Ich aus Ägyptenland herausbrachte, sie sollen nicht verkauft werden, wie man Knechte verkauft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Beherrsche ihn nicht mit Strenge, und fürchte dich vor deinem Gotte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'Und was deinen Knecht und deine Magd anbelangt, die du haben magst, so sollst du von den Völkerschaften, die rings um euch sind, von ihnen Knechte und Mägde kaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Und auch von den Söhnen der Beisassen, die sich bei euch aufhalten, von ihnen und ihren Familien, die bei euch sind, die sie in eurem Lande gezeugt, könnet ihr solche kaufen, so daß sie euer Eigentum werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'Und sie könnet ihr vererben als erblichen Besitz euren Söhnen nach euch zum Eigentum, daß sie euch ewiglich dienen; aber deine Brüder, Söhne Israels, soll der Mann nicht seinen Bruder mit Strenge beherrschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Und so die Hand eines Fremdlings und eines Beisassen, der bei dir ist, ausreicht, und dein Bruder bei ihm verarmt, und sich dem Fremdling, der Beisasse ist bei dir, oder einem vom Familienstamm des Fremdlings verkauft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'So soll, nachdem er sich verkauft hat, Lösung für ihn sein; einer von seinen Brüdern mag ihn lösen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'Oder sein Oheim oder der Sohn seines Oheims soll ihn lösen; oder sonst einer von den Verwandten seines Fleisches aus seiner Familie soll ihn lösen; oder reicht seine Hand aus, soll er sich selbst lösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'Und er rechne mit dem, der ihn kauft, von dem Jahr, da er sich ihm verkauft, bis zum Jubeljahr, und das Silber seines Verkaufs sei nach der Zahl der Jahre, wie die Tage eines Lohnarbeiters soll er bei ihm sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Sind es noch viele Jahre, so gebe er nach Verhältnis zurück von dem Silber seines Kaufpreises seine Lösung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'Und bleiben wenig Jahre bis zum Jubeljahr, so rechne er mit ihm. Je nach Verhältnis seiner Jahre gebe er seine Lösung zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Wie ein Lohnarbeiter sei er Jahr für Jahr bei ihm, nicht mit Strenge soll er vor deinen Augen ihn beherrschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'Und wird er nicht so gelöst, so gehe er und seine Söhne im Jubeljahr aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Denn Mir sind Knechte die Söhne Israels, Meine Knechte sind sie, die Ich aus Ägyptenland herausbrachte. Ich bin Jehovah, euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Machet euch keine Götzen und richtet euch keine Schnitzbilder oder Bildsäulen auf, und setzet kein Steingebilde in eurem Lande, um davor anzubeten; denn Ich, Jeho- vah, bin euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Haltet Meine Sabbathe und fürchtet euch vor Meinem Heiligtum. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Wenn ihr nach Meinen Satzungen wandelt und Meine Gebote haltet und sie tuet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'So werde Ich eure Regen geben zu ihrer Zeit, und die Erde wird geben ihr Gewächs und der Baum des Feldes wird geben seine Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'Und reichen soll euch das Dreschen bis zur Weinlese, und die Weinlese soll reichen bis zur Aussaat, und sollet euer Brot essen zur Sättigung und in Sicherheit in eurem Lande wohnen');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'Und Frieden werde Ich im Lande geben, und ihr sollt euch niederlegen und niemand mache euch erzittern, und Ich will das böse wilde Tier aus dem Lande aufhören lassen und kein Schwert soll euer Land durchziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'Und ihr werdet nachsetzen euren Feinden und sie sollen vor euch fallen durch das Schwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'Fünf von euch sollen hunderten nachsetzen, und hundert von euch sollen zehntausenden nachsetzen; und eure Feinde sollen vor euch fallen durch das Schwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Und Ich will Mich zu euch wenden und euch fruchtbar machen und euch mehren, und aufrichten Meinen Bund mit euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'Alt gewordenes Altes sollt ihr essen und das Alte hinausbringen vor dem Neuen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'Und Meine Wohnung will Ich in eure Mitte setzen, und Meine Seele wird euer nicht überdrüssig werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'Und Ich will in eurer Mitte ziehen und ein Gott euch sein, und ihr sollt sein Mein Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Ich, Jehovah, bin euer Gott, Der euch aus Ägyptenland herausgebracht, daß ihr nicht ihre Knechte wäret, und brach eures Joches Stäbe, und ließ euch aufrecht gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Höret ihr aber nicht auf Mich und tut nicht alle diese Gebote,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'Und verschmähet Meine Satzungen und eure Seele wird Meiner Rechte überdrüssig, so daß ihr nicht alle Meine Gebote tut, so daß ihr Meinen Bund zunichte macht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'So will auch Ich euch solches tun: Und Ich werde euch heimsuchen mit Bestürzung, Schwindsucht und Fieberglut, so daß die Augen sich verzehren und eure Seele vergeht. Vergeblich sollt ihr euren Samen säen und eure Feinde sollen ihn essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'Und Ich werde Mein Angesicht wider euch setzen, daß ihr geschlagen werdet vor euren Feinden und eure Hasser euch unterwerfen, und ihr fliehet, da euch niemand nachsetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Und höret ihr über diesem noch nicht auf Mich, so werde Ich euch siebenfach mehr ob euren Sünden züchtigen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'Und will brechen den Stolz eurer Stärke und euern Himmel wie Eisen, und euer Land euch wie Erz machen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'Zu Ende kommen soll eure Kraft vergeblich; und das Land wird sein Gewächs nicht geben und der Baum des Landes nicht geben seine Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'Und wandelt ihr Mir zuwider und wollet nicht auf Mich hören, so füge Ich siebenmal mehr Schläge hinzu nach euren Sünden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'Und sende wider euch das wilde Tier des Feldes, und es soll euch kinderlos machen und ausrotten euer Vieh, und mache euer weniger, und mache eure Straßen wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'Und lasset ihr auch damit euch noch nicht von Mir züchtigen und wandelt Mir zuwider,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'So gehe auch Ich wider euch und schlage euch, auch Ich, noch siebenfach um eurer Sünden willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'Und bringe über euch das Schwert der Rache, das den Bund rächet. Und ihr werdet euch in eure Städte sammeln, Ich aber werde die Pest in eure Mitte senden, und ihr werdet in des Feindes Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Wenn Ich euch den Stab des Brotes zerbrechen werde, und zehn Weiber werden euer Brot in einem Ofen backen und euer Brot nach dem Gewicht zurückgeben, und ihr es sollet essen und nicht gesättigt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'Und so ihr trotzdem nicht auf Mich höret und wandelt Mir zuwider:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'So gehe Ich im Grimme der Begegnung wider euch, daß Ich, auch Ich, euch züchtige siebenfach ob euren Sünden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'Und ihr werdet essen eurer Söhne Fleisch und eurer Töchter Fleisch werdet ihr essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'Vernichten werde Ich eure Opferhöhen und ausrotten eure Sonnensäulen und eure Leichen auf eurer Götzen Leichen legen, und Meine Seele euch verwerfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'Und Ich werde eure Städte öde machen und verwüsten eure Heiligtümer, und nicht den Geruch eurer Ruhe riechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'Und Ich werde verwüsten das Land, daß eure Feinde, die darin wohnen, sich darob entsetzen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Und Ich werde euch zersprengen unter die Völkerschaften und ausziehen ein Schwert hinter euch her, und euer Land soll eine Wüste und eure Städte eine Öde werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Dann läßt sich wohlgefallen das Land seine Sabbathe alle Tage, die es wüste ist und ihr im Land eurer Feinde seid; dann wird das Land feiern und läßt sich wohlgefallen seine Sabbathe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'Alle Tage des Wüsteliegens feiert es dann, wie es nicht gefeiert an euren Sabbathen, da ihr noch darin wohntet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'Und die von euch, so verblieben: Verzagtheit will Ich bringen in ihr Herz, in ihrer Feinde Landen, daß sie jagt das Rauschen eines dahingetriebenen Blattes und sie fliehen, wie man vor dem Schwerte flieht, und fallen, da niemand ihnen nachsetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'Und der Mann wird straucheln über seinen Bruder, wie vor dem Schwerte, wo ihnen niemand nachsetzt und ihr vor euren Feinden nicht bestehen könnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'Unter den Völkerschaften geht ihr zugrunde, und eurer Feinde Land frißt euch auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'Und die von euch, so verblieben, vergehen durch ihre Missetat in ihrer Feinde Landen, und auch durch ihrer Väter Missetaten vergehen sie mit ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'Und sie werden bekennen ihre Missetat und die Missetat ihrer Väter damit, daß sie Mir abgefallen und Mir zuwider gewandelt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'Darum werde Ich auch wider sie gehen, und sie in das Land ihrer Feinde bringen, ob nicht dann ihr unbeschnittenes Herz sich niederbeuge und sie dann ihre Missetat abtragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'Und Ich werde gedenken an Meinen Bund mit Jakob und auch an Meinen Bund mit Isaak und auch an Meinen Bund mit Abraham werde Ich gedenken, und an das Land gedenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Und das Land wird von ihnen verlassen sein und seine Sabbathe sich gefallen lassen, während es von ihnen wüste gelassen wird, sie selbst aber werden ihre Missetat abtragen, weil und weil sie Meine Rechte verschmäht und ihre Seele Meiner Satzungen überdrüssig geworden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'Und selbst da noch, während sie im Lande ihrer Feinde sind, habe Ich sie nicht verschmäht und ihrer nicht so überdrüssig geworden, daß Ich sie wegtilgte und Meinen Bund mit ihnen zunichte machte; denn Ich, Jehovah, bin ihr Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Und Ich gedenke für sie an den Bund mit den Vorfahren, die Ich vor den Augen der Völkerschaften aus Ägyptenland herausgebracht, um ihnen ein Gott zu sein. Ich, Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'Dies sind die Satzungen und die Rechte und Gesetze, die Jehovah zwischen Sich und zwischen den Söhnen Israels auf dem Berge Sinai durch die Hand Moses gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Rede zu den Söhnen Israels und sprich zu ihnen: So ein Mann ein besonderes Gelübde tut, so sollen die Seelen dem Jehovah nach deiner Schätzung sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Und es sei deine Schätzung eines Männlichen vom zwanzigsten bis zum sechzigsten Jahre, und es sei deine Schätzung fünfzig Schekel Silber; nach dem Schekel des Heiligtums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'Und ist es ein Weib, soll deine Schätzung dreißig Schekel sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'Und wenn von fünf zu zwanzig Jahren, so soll deine Schätzung für das männliche zwanzig Schekel und für das weibliche zehn Schekel sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'Und wenn von einem Monat bis zu fünf Jahren, so soll deine Schätzung für das männliche fünf Schekel Silber und für das weibliche deine Schätzung drei Schekel Silber sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'Und wenn sechzig Jahre und darüber, so sei deine Schätzung, wenn männlich, fünfzehn Schekel und für das weibliche zehn Schekel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Und ist er zu arm für deine Schätzung, so stelle man ihn vor den Priester, und der Priester schätze ihn; je nach dem, wozu die Hand des Gelobenden zureicht, schätze ihn der Priester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Und ist es ein Vieh, davon man Jehovah eine Opfergabe darbringen will, so soll alles, was man davon dem Herrn gibt, heilig sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Man soll dasselbe nicht wechseln und nicht vertauschen, weder das gute um ein schlechtes, noch das schlechte um ein gutes; vertauscht man es aber doch Vieh um Vieh, so soll es und das Vertauschte heilig sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Und ist es irgendein unreines Vieh, das man Jehovah nicht als Opfergabe darbringen kann, so stelle man das Stück Vieh vor den Priester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'Und der Priester schätze es, sei es gut oder schlecht; wie der Priester es schätzt, so sei es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Und will man es lösen, so tue man ein Fünftel über die Schätzung dazu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'Und so ein Mann sein Haus dem Jehovah heiligt, so daß es ihm heilig sei, so schätze es der Priester, wie gut oder wie schlecht es sei. So wie es der Priester schätzt, so bestehe es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'So aber, der sein Haus geheiligt hat, es lösen will, der tue den fünften Teil der Schätzung in Silber dazu, so ist es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'Und so ein Mann von dem Felde seines Eigentums Jehovah heiliget, so geschehe deine Schätzung im Verhältnis zu der Aussaat; die Aussaat von einem Chomer Gerste für fünfzig Schekel Silbers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Wenn er vom Jubeljahr an sein Feld heiligt, so bestehe es nach deiner Schätzung!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'Und heiligt er sein Feld nach dem Jubeljahr, so rechne ihm der Priester das Silber nach den Jahren, die noch bis zum Jubeljahr übrig sind; und es werde von deiner Schätzung abgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Und will, der es heiligte, das Feld lösen, so tue er ein Fünftel des Silbers deiner Schätzung dazu, und es bestehe als sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'Und löset er das Feld nicht und verkauft er das Feld an einen anderen Mann, so soll es nicht mehr gelöst werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'Wenn das Feld im Jubeljahr ausgeht, so ist es dem Jehovah heilig, wie ein gebanntes Feld. Es wird Eigentum des Priesters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Und heiligt einer dem Jehovah ein Feld, das er kaufte, welches nicht vom Felde seines Eigentums ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'So rechne ihm der Priester den Betrag deiner Schätzung bis zum Jubeljahr und gebe deine Schätzung an demselben Tag, auf daß es Jehovah heilig sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'Im Jubeljahr kehrt das Feld an den zurück, von dem er es gekauft, dem es als Eigentum im Lande zugehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'Und all deine Schätzung sei nach dem Schekel des Heiligtums. Zwanzig Gera sei der Schekel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Nur das Erstgeborene vom Vieh, das Jehovahs Erstgeburt ist, soll kein Mann heiligen, weder Ochse noch Kleinvieh. Jehovahs ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Und ist es von unreinem Vieh, so löse man es ein nach deiner Schätzung und tue ein Fünftel dazu; wird es aber nicht gelöst, so verkaufe man es nach deiner Schätzung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Alles Gebannte jedoch, das ein Mann Jehovah bannt, von allem, das sein ist, vom Mensch und vom Vieh und vom Felde seines Eigentums, soll weder verkauft, noch gelöst werden: alles Gebannte ist Jehovah hochheilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Alles Gebannte, was von Menschen gebannt wird, darf nicht eingelöst werden, es muß des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'Und aller Zehnte des Landes, von der Saat des Landes von der Baumfrucht, ist Jehovahs, es ist Jehovah heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Und will ein Mann etwas von seinem Zehnten lösen, so tue er ein Fünftel dazu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'Und aller Zehnte vom Rinde und vom Kleinvieh, von allem, das unter der Rute durchzieht, soll das zehnte Jehovah heilig sein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'Er soll nicht forschen, ob es gut oder schlecht sei, und er soll nicht vertauschen. Und vertauscht er es, so soll es mit dem Eingetauschten heilig sein und nicht gelöst werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'Dies sind die Gebote, die Jehovah dem Mose an die Söhne Israels auf dem Berg Sinai geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'Und Jehovah redete zu Mose in der Wüste Sinai im Versammlungszelt am ersten des zweiten Monats im zweiten Jahre nach ihrem Auszug aus Ägyptenland, und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Nehmet auf die Kopfzahl der ganzen Gemeinde der Söhne Israels nach ihren Familien, nach ihrer Väter Häusern nach der Zahl der Namen aller Männlichen nach ihren Köpfen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'Vom Sohne von zwanzig Jahren und darüber, alle, die im Heer ausziehen in Israel. Mustert sie, du und Aharon, nach ihren Heeren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'Und mit euch sei je ein Mann aus dem Stamme, der Mann, der das Haupt des Hauses seiner Väter ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'Und dies sind die Namen der Männer, die bei euch stehen sollen: Von Ruben Elizur, Schedeurs Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'Von Simeon: Schelumiel, der Sohn Zurischaddais;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'Von Judah: Nachschon, der Sohn Amminadabs;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'Von Issaschar: Nathaneel, der Sohn Zuars;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'Von Sebulun: Eliab, Chelons Sohn;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'Von den Söhnen Josephs für Ephraim: Elischama, der Sohn Ammihuds; für Menascheh: Gamliel, der Sohn Pedahzurs;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'Von Benjamin: Abidan, Sohn Gideonis;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'Von Dan: Achieser, der Sohn Ammischaddais;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'Von Ascher: Pagiel, der Sohn Ochrans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'Von Gad: Eljasaph, der Sohn Deguels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'Von Naphthali: Achira, Enans Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Das sind die aus der Gemeinde Berufenen, die Fürsten der Stämme ihrer Väter, die Häupter der Tausende Israels sind sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Und Mose und Aharon nahmen diese Männer, die mit Namen benannt sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'Und versammelten am ersten des zweiten Monats die ganze Gemeinde, und sie ließen sich nach ihren Familien, nach den Häusern ihrer Väter, der Zahl der Namen und nach den Köpfen von dem zwanzigsten Jahr an und darüber in die Geburtslisten eintragen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Wie Jehovah dem Mose geboten hatte; und er musterte sie in der Wüste Sinai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'Und es waren die Söhne Rubens, des Erstgeborenen Israels, ihre Geburten nach ihren Familien den Häusern ihrer Väter, nach der Zahl ihrer Namen nach ihren Köpfen, alles Männliche von zwanzig Jahren und aufwärts, alle, die im Heer auszogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'Ihre Gemusterten vom Stamme Ruben sechsundvierzigtausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Für die Söhne Simeons: ihre Geburten nach ihren Familien, nach den Häusern ihrer Väter, ihre Gemusterten nach der Zahl der Namen, nach ihren Köpfen, alle Männlichen von zwanzig Jahren und aufwärts, alle, die im Heer auszogen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'Ihre Gemusterten vom Stamme Simeons neunundfünfzigtausenddreihundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Für die Söhne Gads: ihre Geburten nach ihren Familien, nach dem Haus ihrer Väter, in der Zahl von Namen, vom zwanzigsten Jahre und aufwärts, alle, die im Heer auszogen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'Ihre Gemusterten vom Stamme Gad fünfundvierzigtausendsechshundertfünfzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Für die Söhne Judahs: ihre Geburten nach ihren Familien, nach dem Haus ihrer Väter, in der Zahl von Namen vom zwanzigsten Jahr und aufwärts, alle im Heere ausziehend,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'Ihre Gemusterten nach dem Stamm Judah vierundsiebzigtausendsechshundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Für die Söhne Issaschars: ihre Geburten nach ihren Familien, nach dem Haus ihrer Väter, in der Zahl der Namen vom zwanzigsten Jahre an und aufwärts, alle, die im Heere ausziehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'Ihre Gemusterten nach dem Stamme Issaschar waren vierundfünfzigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Für die Söhne Sebuluns: ihre Geburten nach ihren Familien, nach dem Haus ihrer Väter, in der Zahl der Namen vom zwanzigsten Jahr und aufwärts, alle, die im Heer ausziehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'Ihre Gemusterten vom Stamme Sebulun waren siebenundfünfzigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Für die Söhne Josephs, für die Söhne Ephraims: ihre Geburten nach ihren Familien, nach dem Haus ihrer Väter in der Zahl der Namen vom zwanzigsten Jahr und aufwärts, alle, die in dem Heer ausziehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'Ihre Gemusterten für den Stamm Ephraim vierzigtausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Für die Söhne Menaschehs: ihre Geburten nach ihren Familien, nach dem Haus ihrer Väter, in der Zahl der Namen vom zwanzigsten Jahr und darüber, alle, die im Heer ausziehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'Ihre Gemusterten für den Stamm Menascheh zweiunddreißigtausendzweihundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Für die Söhne Benjamins: ihre Geburten nach ihren Familien, nach dem Haus ihrer Väter, in der Zahl der Namen vom zwanzigsten Jahr und aufwärts, alle, die im Heer ausziehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'Ihre Gemusterten für den Stamm Benjamin fünfunddreißigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Für die Söhne Dans: ihre Geburten nach ihren Familien, nach dem Haus ihrer Väter, in der Zahl der Namen vom zwanzigsten Jahr und darüber, alle, die im Heere ausziehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'Ihre Gemusterten für den Stamm Dan zweiundsechzigtausendsiebenhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Für die Söhne Aschers: ihre Geburten nach ihren Familien, nach dem Haus ihrer Väter, in der Zahl der Namen vom zwanzigsten Jahr und darüber, alle, die im Heer ausziehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'Ihre Gemusterten für den Stamm Ascher einundvierzigtausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Für die Söhne Naphthalis: ihre Geburten nach ihren Familien, nach dem Haus ihrer Väter, in der Zahl der Namen vom zwanzigsten Jahr und darüber, alle, die im Heer ausziehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'Ihre Gemusterten für den Stamm Naphthali dreiundfünfzigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'Das sind die Gemusterten, die Mose und Aharon und die Fürsten Israels musterten, zwölf Männer, ein Mann für das Haus seiner Väter waren es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Und es waren aller Gemusterten der Söhne Israels nach dem Haus ihrer Väter vom zwanzigsten Jahr und darüber, alle, die im Heer ausziehen in Israel,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'Und aller Gemusterten waren sechshunderttausend und dreitausendfünfhundert- fünfzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Und die Leviten nach ihrer Väter Stamm wurden nicht in ihrer Mitte gemustert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Nur den Stamm Levi sollst du nicht mustern und ihre Kopfzahl nicht aufnehmen inmitten der Söhne Israels;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'Und du sollst die Leviten mustern über die Wohnung des Zeugnisses und über all deren Geräte und über alles, was zu ihr gehört. Sie sollen die Wohnung tragen und all ihre Geräte, und Dienst bei ihr tun, und rings um die Wohnung sich lagern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'Und wenn die Wohnung aufbricht, sollen die Leviten sie abnehmen, und wenn die Wohnung sich lagert, sollen die Leviten sie aufrichten, und der Fremde, der nahet, soll sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'Und die Söhne Israels sollen sich lagern, jeder Mann bei seinem Lager und jeder Mann bei seinem Banner nach ihren Heerscharen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'Und die Leviten sollen rings um die Wohnung des Zeugnisses lagern, auf daß keine Entrüstung sei über die Gemeinde der Söhne Israels, und die Leviten sollen die Hut der Wohnung des Zeugnisses halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'Und die Söhne Israels taten nach allem, was Jehovah dem Mose geboten hatte; also taten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'Und Jehovah redete zu Mose und zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Jeder Mann bei seinem Banner, bei den Zeichen des Hauses seiner Väter, sollen sich die Söhne Israels lagern; gegenüber dem Versammlungszelte sollen sie sich ringsum lagern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Nach vorn, dem Aufgang zu, soll sich lagern das Banner des Lagers Judahs nach seinen Heerscharen, und Fürst der Söhne Judahs ist Nachschon, der Sohn Amminadabs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'Und sein Heer und seine Gemusterten vierundsiebzigtausendsechshundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'Und bei ihm lagere sich der Stamm Issaschars, und Fürst der Söhne Issaschars ist Nathaneel, der Sohn Zuars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'Und sein Heer und seine Gemusterten vierundfünfzigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'Der Stamm Sebulons, und Fürst der Söhne Sebulons ist Eliab, der Sohn Chelons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'Und sein Heer und seine Gemusterten siebenundfünfzigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Alle Gemusterten des Lagers Jehudahs sind hunderttausend und achtzigtausend und sechstausend und vierhundert nach ihren Heerscharen. Sie sollen zuerst aufbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Das Banner von Rubens Lager zur Rechten nach seinen Heerscharen, und Fürst ist für die Söhne Rubens Elizur, Schedeurs Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'Und sein Heer und seine Gemusterten sind sechsundvierzigtausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'Und bei ihm lagere der Stamm Simeons. Und Fürst der Söhne Simeons ist Schelumiel, der Sohn des Zurischaddai;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'Und sein Heer und seine Gemusterten sind neunundfünfzigtausenddreihundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'Und der Stamm Gads. Und Fürst der Söhne Gads ist Eljasaph, Reguels Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'Und sein Heer und seine Gemusterten fünfundvierzigtausendsechshundertfünfzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Alle Gemusterten von Rubens Lager sind hunderttausend und einundfünfzigtausend und vierhundert und fünfzig in ihren Heerscharen. Und sie sollen als zweite aufbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'Und es breche das Versammlungszelt, das Lager der Leviten inmitten der Lager, auf; so wie sie lagerten, so brechen sie auf, jeder Mann zur Hand nach seinem Banner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Das Banner von Ephraims Lager nach seinen Heerscharen dem Meere zu. Und Fürst der Söhne Ephraims ist Elischama, der Sohn Ammihuds.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'Und sein Heer und seine Gemusterten vierzigtausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'Und bei ihm Menaschehs Stamm, und Fürst von Menaschehs Söhnen ist Gamliel, Pedahzurs Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'Und sein Heer und ihre Gemusterten sind zweiunddreißigtausendzweihundert;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'Und der Stamm Benjamins, und Fürst der Söhne Benjamins ist Abidan, Gideonis Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'Und sein Heer und ihre Gemusterten sind fünfunddreißigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Alle Gemusterten nach dem Lager Ephraims waren einhunderttausend und achttausend und einhundert nach ihren Heerscharen, und sollen die dritten im Aufbrechen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Das Banner des Lagers Dans nach seinen Heerscharen sei nach Mitternacht, und Fürst für die Söhne Dans Achieser, Ammischaddais Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'Und sein Heer und ihre Gemusterten zweiundsechzigtausendsiebenhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'Und bei ihm lagere Aschers Stamm, und Fürst für die Söhne Aschers Pagiel, Ochrans Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'Und sein Heer und ihre Gemusterten einundvierzigtausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'Und der Stamm Naphthalis, und Fürst für die Söhne Naphthalis Achira, Enans Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'Und sein Heer und ihre Gemusterten dreiundfünfzigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Alle Gemusterten für das Lager Dans waren hunderttausend und siebenundfünfzigtausend und sechshundert. Sie sollen nach ihren Bannern zuletzt aufbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Das sind die Gemusterten der Söhne Israels nach dem Haus ihrer Väter, alle Gemusterten der Lager nach ihren Heerscharen: Sechshunderttausend und dreitausend und fünfhundert und fünfzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Und die Leviten wurden nicht inmitten der Söhne Israels gemustert; wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'Und die Söhne Israels taten nach allem, das Jehovah dem Mose geboten hatte, so lagerten sie nach ihren Bannern und so brachen sie auf, jeder Mann nach seiner Familie, bei dem Hause seines Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Und dies die Geburten Aharons und Moses am Tage, da Jehovah mit Mose redete am Berge Sinai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'Und dies sind die Namen der Söhne Aharons: Der Erstgeborene Nadab, und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Das sind die Namen der Söhne Aharons, der gesalbten Priester, deren Hand er gefüllt hatte zum Priesterdienst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Und Nadab und Abihu starben vor Jehovah, da sie in der Wüste Sinai fremdes Feuer vor Jehovah darbrachten, und hatten keine Söhne. Und Eleasar und Ithamar taten Priesterdienst vor ihrem Vater Aharon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Laß den Stamm Levi sich nahen und laß ihn vor Aharon, den Priester stehen, daß sie ihm Dienste tun,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'Und halten seine Hut und die Hut der ganzen Gemeinde vor dem Versammlungszelt, daß sie den Dienst der Wohnung dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'Und hüten all die Geräte des Versammlungszeltes und der Hut der Söhne Israels, um zu dienen den Dienst der Wohnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'Und sollst die Leviten dem Aharon und seinen Söhnen geben. Gegeben, gegeben seien sie ihm von den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Und Aharon und seine Söhne sollst du mustern, daß sie ihren Priesterdienst halten. Und der Fremde, der sich naht, soll sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Und Ich, siehe, Ich habe die Leviten aus der Mitte der Söhne Israels genommen, statt aller Erstgeburt, die den Mutterschoß bricht, von den Söhnen Israels, und Mein sollen die Leviten sein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Denn Mein ist alle Erstgeburt: Am Tage, da Ich alle Erstgeburt im Lande Ägypten schlug, heiligte Ich Mir alle Erstgeburt in Israel vom Menschen bis zum Vieh. Mein sind sie. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'Und Jehovah redete zu Mose in der Wüste Sinai und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Mustere die Söhne Levis nach dem Hause ihrer Väter, nach ihren Familien, alles Männliche von einem Monat und darüber sollst du sie mustern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Und Mose musterte sie nach dem Munde Jehovahs, wie Er geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'Und das waren die Söhne Levis in ihren Namen: Gerschon und Kohath und Merari.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'Und das sind die Namen der Söhne Gerschons nach ihren Familien: Libni und Schimei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'Und die Söhne Kohaths nach ihren Familien: Amram und Jizhar, Chebron und Ussiel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'Und die Söhne Meraris nach ihren Familien: Machli und Muschi. Das sind sie, die Familien Levis nach dem Haus ihrer Väter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Für Gerschon ist die Familie des Libniten und die Familie des Schimiten. Das sind sie, die Familien der Gerschoniten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Ihre Gemusterten in ihrer Zahl, alles Männliche von einem Monat und darüber. Ihre Gemusterten waren siebentausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Die Familien der Gerschoniten sollen lagern hinter der Wohnung gegen das Meer hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'Und Fürst des Vaterhauses der Gerschoniten war Eljasaph, Laels Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'Und die Hut der Söhne Gerschons war im Versammlungszelt die Wohnung und das Zelt, ihre Decke und der Behang an dem Eingang des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'Und die Umhänge des Vorhofs und der Behang des Eingangs des Vorhofs, der rings um die Wohnung und den Altar ist, und seine Seile für all den Dienst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Und für Kohath die Familie des Amramiten, und die Familie des Jizhariten, und die Familie des Chebroniten, und die Familie des Ussieliten. Das sind die Familien des Kohathiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'In der Zahl alles Männlichen von einem Monat und darüber waren es achttausendsechshundert, welche die Hut des Heiligtums hüteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Die Familien der Söhne des Kohaths lagerten zur Seite der Wohnung rechts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'Und Fürst des Vaterhauses nach den Familien des Kohathiten war Elizaphan, der Sohn Ussiels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'Und ihre Hut war die Lade, und der Tisch und der Leuchter und die Altäre und Geräte des Heiligtums, damit sie Dienst taten, und der Behang und all sein Dienst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Und Fürst über die Fürsten der Leviten war Eleasar, Sohn Aharons des Priesters, der bestellt war über die Hüter der Hut des Heiligtums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Für Merari, die Familie der Machliten und die Familie der Muschiten. Das sind sie, Meraris Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'Und ihre Gemusterten waren in der Zahl alles Männlichen von einem Monat und darüber sechstausendzweihundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'Und Fürst des Vaterhauses für die Familien des Merariten war Zuriel, Abichails Sohn. Sie lagerten auf der Seite der Wohnung gegen Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'Und das Anvertraute der Hut der Söhne Meraris waren die Bretter der Wohnung und ihre Riegel und ihre Säulen und ihre Unter- sätze, und alle ihre Gerätschaften und ihr Dienst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'Und die Säulen des Vorhofs ringsum und ihre Untersätze und ihre Pflöcke und ihre Seile.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Und die, so vor der Wohnung vorn vor dem Versammlungszelt gegen Aufgang lagerten, waren Mose, und Aharon und seine Söhne, welche die Hut des Heiligtums, die Hut der Söhne Israels hüteten; und der Fremde, der naht, soll sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Alle Gemusterten der Leviten, die Mose und Aharon musterten, nach Jehovahs Munde, nach ihren Familien, alles Männliche von einem Monat und aufwärts, waren es zweiundzwanzigtausend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'Und Jehovah sprach zu Mose: Mustere alle männliche Erstegeburt für die Söhne Israels von einem Monat und darüber, und nimm die Zahl ihrer Namen auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'Und nimm für Mich die Leviten, Ich bin Jehovah, statt aller Erstgeburt unter den Söhnen Israels, und das Vieh der Leviten, statt aller Erstgeburt unter dem Vieh der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Und Mose musterte, wie ihm Jehovah geboten hatte, alle Erstgeburt unter den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'Und alle männliche Erstgeburt in der Zahl der Namen von einem Monat und aufwärts nach ihren Gemusterten war zweiundzwanzigtausend und dreiundsiebzig und zweihundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Nimm die Leviten statt aller Erstgeburt unter den Söhnen Israels und das Vieh der Leviten, statt ihres Viehs, und die Leviten sollen Mein sein. Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'Und für die Einlösung der dreiundsiebzig und zweihundert Erstgeburten der Söhne Israels, die überzählig sind über die Leviten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'Sollst du je fünf Schekel nehmen für den Kopf. Nach dem Schekel des Heiligtums sollst du es nehmen, zwanzig Gera der Schekel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'Und das Silber gib Aharon und seinen Söhnen als Einlösung für die Überzähligen unter ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Und Mose nahm das Silber der Einlösung von den Überzähligen über die Einlösung der Leviten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'Von dem Erstgeborenen der Söhne Israels nahm er das Silber, fünfundsechzig und dreihundert und tausend nach dem Schekel des Heiligtums;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'Und Mose gab das Silber der Eingelösten dem Aharon und seinen Söhnen, nach Jehovahs Munde, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'Und Jehovah redete zu Mose und zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Nehmet auf die Kopfzahl der Söhne Kohaths aus der Mitte der Söhne Levis nach ihren Familien, nach ihrer Väter Haus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'Von dreißig Jahren aufwärts bis zu fünfzig Jahren, alle, die zum Heer ausziehen, auf daß sie die Arbeit tun im Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'Dies ist der Dienst von Kohaths Söhnen im Versammlungszelt: Der allerheiligste ist er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Und Aharon und seine Söhne sollen kommen, wenn das Lager aufbricht, und abnehmen den Vorhang der Decke und bedecken damit die Lade des Zeugnisses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'Und geben darüber eine Decke von Dachsfell und breiten darüber ein Tuch gänzlich von Purpurblau, und legen ihre Stangen an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'Und über den Schaubrottisch sollen sie ein purpurblaues Tuch breiten und auf denselben die Schüsseln und Platten und die Becher und die Trankopferschalen stellen; und das beständige Brot soll darauf sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'Und sollen ein Tuch von Scharlach doppelt gefärbt darüberbreiten, und es mit einer Decke von Dachsfellen bedecken, und seine Stangen anlegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'Und sollen nehmen ein purpurblaues Tuch, und den Leuchter der Beleuchtung und seine Lampen und seine Lichtputzen und seine Kohlenpfannen und alle seine Ölgeräte, womit sie dabei Dienst tun, damit bedecken;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'Und sollen um ihn und um all seine Gerätschaften eine Decke von Dachsfellen legen und auf die Trage stellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'Und über den goldenen Altar sollen sie ein purpurblaues Tuch breiten und mit einer Decke von Dachsfellen bedecken und die Stangen anlegen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Und nehmen alles Geräte des Dienstes, womit sie Dienst tun im Heiligtum, und in ein purpurblaues Tuch legen und mit einer Decke von Dachsfellen bedecken und auf die Trage bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Und von dem Altar sollen sie die Fettasche wegnehmen und darüber ein purpurrotes Tuch breiten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'Und darauf alle seine Geräte, damit sie darauf Dienst tun, die Kohlpfannen, die Fleischgabeln, die Schaufeln und die Sprengbecken, alle Geräte des Altars legen und darüber eine Decke von Dachsfellen breiten, und die Stangen anlegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Und wenn Aharon und seine Söhne das Heiligtum und alle Gerätschaft des Heiligtums völlig bedeckt haben, wenn das Lager aufbricht, so sollen nachher die Söhne Kohaths kommen zum Tragen, auf daß sie nicht das Heiligtum berühren und sterben. Das ist, was die Kohathiten an dem Versammlungszelt zu tragen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Und es sei anvertraut dem Eleasar, dem Sohne Aharons, des Priesters, das Beleuchtungsöl und das Räuchwerk der Spezereien und das beständige Speiseopfer und das Salböl. Die Bestellung der ganzen Wohnung und von allem, was darin ist, im Heiligtum und in seinem Geräte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'Und Jehovah redete zu Mose und zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Lasset den Stamm der Familien des Kohathiten aus der Mitte der Leviten nicht ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'Und tuet ihnen also, auf daß sie leben und nicht sterben, wenn sie zu dem Allerheiligsten herzutreten: Aharon und seine Söhne sollen hineingehen und jeden Mann setzen an seinen Dienst und was er zu tragen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Und sie sollen nicht hineingehen, um das Heiligtum zu sehen, wenn es eingehüllt wird, und sie sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Nehmet auf die Kopfzahl der Söhne Gerschons, auch sie, nach ihrer Väter Haus, nach ihren Familien;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'Von ihrem dreißigsten Jahre und aufwärts bis zum fünfzigsten Jahre sollst du sie mustern, alle, die kommen auszurücken zum Heere, auf daß sie Dienst tun im Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'Das ist der Dienst der Familie des Gerschoniten, zu dienen und zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Und sie sollen tragen die Teppiche der Wohnung und das Versammlungszelt, seine Decke und die Decke von Dachsfellen, die oben darüber ist, und die Decke zu dem Eingang des Versammlungszeltes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'Und die Umhänge des Vorhofs und die Decke des Eingangs des Tors zum Vorhof, der um die Wohnung und den Altar ringsum ist, und ihre Seile und alle Geräte des Dienstes, und alles, was dafür getan werden muß, auf daß sie dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Nach dem Munde Aharons und seiner Söhne soll aller Dienst der Söhne des Gerschoniten geschehen, alles, was sie zu tragen und alles, was sie zu dienen haben; und ihr sollt in ihre Hut bestellen alles, was sie zu tragen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'Das ist der Dienst der Familien der Söhne des Gerschoniten im Versammlungszelt. Und ihre Hut ist unter der Hand Ithamars des Sohnes des Priesters Aharon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Meraris Söhne sollst du nach ihren Familien, nach ihrer Väter Haus mustern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'Vom dreißigsten Jahre und aufwärts bis zum fünfzigsten sollst du sie mustern. Jeder, der zum Heer käme, soll dienen seinen Dienst im Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'Und das ist die Hut ihres Tragens von allem Dienste im Versammlungszelt: Die Bretter der Wohnung und ihre Riegel und ihre Säulen und ihre Untersätze;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'Und die Säulen des Vorhofs ringsum und ihre Untersätze und ihre Pflöcke und ihre Seile und alle ihre Geräte, und alles, was zum Dienste gehört; allen nach ihren Namen sollt ihr die Geräte ihrer Hut zum Tragen anvertrauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'Dies sei der Dienst der Familien der Söhne Meraris nach all ihrem Dienste im Versammlungszelt unter der Hand von Ithamar, Aharons Sohn, des Priesters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'Und Mose und Aharon und die Fürsten der Gemeinde musterten die Söhne des Kohathiten nach ihren Familien und nach dem Hause ihrer Väter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'Vom dreißigsten Jahre und darüber und bis zum fünfzigsten Jahre, alle, die zum Heere kommen, auf daß sie dienen im Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'Und ihre Gemusterten nach ihren Familien waren zweitausendsiebenhundertfünfzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Das sind die Gemusterten der Familien des Kohathiten, die alle im Versammlungszelte dienen sollten, welche Mose und Aharon nach dem Munde Jehovahs durch die Hand Moses musterten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'Und die Gemusterten der Söhne Gerschons nach ihren Familien nach ihrer Väter Haus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'Vom dreißigsten Jahre aufwärts bis zum fünfzigsten Jahre, alle, die zum Heere kamen für den Dienst im Versammlungszelt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'Und ihre Gemusterten nach ihren Familien, nach ihrer Väter Haus waren zweitausendsechshundertdreißig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Das sind die Gemusterten der Familien der Söhne Gerschons, alle, die im Versammlungszelte dienen sollten, welche Mose und Aharon nach dem Munde Jehovahs musterten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'Und die Gemusterten der Familien der Söhne Meraris nach ihren Familien nach dem Haus ihrer Väter;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'Vom dreißigsten Jahre aufwärts bis zum fünfzigsten Jahre, alle, die zum Heere kamen, für den Dienst im Versammlungszelt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'Und ihre Gemusterten nach ihren Familien waren dreitausendzweihundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Das sind die Gemusterten der Familien von Meraris Söhnen, die Mose und Aharon nach dem Munde Jehovahs durch Moses Hand musterten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Alle Gemusterten, die Mose und Aharon und die Fürsten Israels bei den Leviten nach ihren Familien und nach ihrer Väter Haus musterten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'Vom dreißigsten Jahre und aufwärts bis zum fünfzigsten Jahre, alle, die zum Dienen des Dienstes des Dienens kamen und zum Dienst des Tragens im Versammlungszelt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'Und ihre Gemusterten waren achttausendfünfhundertachtzig;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Nach dem Befehle Jehovahs durch Moses Hand musterte man sie, jeden Mann zu seinem Dienst und zu was er zu tragen hatte und was ihm anvertraut war, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Gebiete den Söhnen Israels, daß sie jeden Aussätzigen und jeden mit einem Fluß Behafteten und alle durch Tote Verunreinigte aus dem Lager senden sollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'Vom Männlichen bis zum Weiblichen sollt ihr entsenden, aus dem Lager sollt ihr sie entsenden; daß sie euer Lager nicht verunreinigen, in deren Mitte Ich wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'Und die Söhne Israels taten so, und entsandten sie aus dem Lager. Wie Jehovah zu Mose geredet hatte, also taten die Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'Und Jehovah redete mit Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Rede zu den Söhnen Israel: So ein Mann oder ein Weib eine der menschlichen Sünden tut und damit eine Untreue gegen Jehovah begeht, so ist solche Seele verschuldet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'Und sie sollen ihre Sünde, die sie taten, bekennen, und er soll die Hauptsumme der Schuld zurückgeben und ein Fünftel dazutun, und es dem geben, an dem er es verschuldet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Und hat der Mann keinen Einlöser, an den die Schuld zurückgegeben werden könnte, so sei die zurückzugebende Schuld dem Jehovah, dem Priester, außer dem Widder der Sühne, womit er ihn sühnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Und jegliche Habe von allem Heiligen der Söhne Israels, das sie dem Priester dar- bringen, sein soll es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'Und so ein Mann etwas heiligt, soll es ihm gehören. Was ein Mann dem Priester gibt, sein soll es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Rede mit den Söhnen Israels und sprich zu ihnen: Wenn irgendeines Mannes Weib abweicht und Untreue an ihm begeht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'So daß ein Mann bei ihr liegt und sie besamt, und es ist vor den Augen ihres Mannes verborgen, und sie hat es verheimlicht, daß sie sich verunreinigt hat, und kein Zeuge gegen sie da ist, und sie ist nicht erfaßt worden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'Und in ihn ist der Geist der Eifersucht übergegangen, und er auf sein Weib eifersüchtig ist, ob sie sich nicht verunreinigt hätte; oder es geht in ihn ein Geist der Eifersucht über, und er ist auf sein Weib eifersüchtig, und sie ist nicht unrein,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'So bringe der Mann sein Weib zu dem Priester, und bringe ihre Opfergabe ihrethalben ein zehntel Epha Gerstenmehl dar, er gieße kein Öl darauf und gebe keinen Weihrauch bei; denn ein Speiseopfer der Eifersucht ist es, ein Speiseopfer der Gedenkung, das einer Missetat gedenken läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'Und der Priester lasse sie nahen und vor Jehovah stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'Und der Priester nehme heiliges Wasser in ein irdenes Gefäß; und von dem Staub, der auf der Flur der Wohnung ist, nehme der Priester und gebe ihn in das Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Und der Priester lasse das Weib vor Jehovah stehen und Blöße das Haupt des Weibes, und gebe auf ihre Handflächen das Speiseopfer der Gedenkung. Das Speiseopfer der Eifersuchten ist es; und in der Hand des Priesters seien die bitteren Wasser, die verfluchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Und der Priester beschwöre sie und spreche zu dem Weibe: Hat kein Mann bei dir gelegen und bist du nicht abgewichen zur Unreinheit hinter deinem Manne, so bleibe ungestraft von diesen bitteren Wassern, den verfluchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'So du aber abgewichen hinter deinem Manne und dich verunreinigt hast, und ein Mann dich beschlafen hat außer deinem Manne;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'So schwöre der Priester dem Weibe mit einem Schwur der Verwünschung, und spreche der Priester zu dem Weibe: Jehovah wird dich zur Verwünschung und zum Schwur geben inmitten deines Volkes, damit, daß Jehovah deine Hüfte verfallen und den Leib dir schwellen läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Und es komme dieses verfluchte Wasser in deine Eingeweide, auf daß der Leib dir schwelle und deine Hüfte verfalle. Und das Weib spreche: Amen! Amen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Und der Priester schreibe diese Verwünschungen in das Buch, und wische es ab in die bitteren Wasser;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'Und lasse das Weib das bittere verfluchte Wasser trinken, und das verfluchte Wasser komme in sie zur Bitterkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'Und der Priester nehme von der Hand es Weibes das Speiseopfer der Eifersuchten und webe das Speiseopfer vor Jehovah und bringe es dar auf dem Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Und der Priester nehme eine Handvoll von ihrem Speiseopfer, ihrem Gedenkteil, und zünde es an auf dem Altar, und hierauf lasse er das Weib das Wasser trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'Und hat er ihr das Wasser zu trinken gegeben, dann wird geschehen, wenn sie sich verunreinigt und wider ihren Mann untreu geworden ist, daß das Wasser, das verfluchte, in sie kommt zur Bitterkeit, und ihr Leib schwillt und ihre Hüfte verfällt, und das Weib zur Verwünschung wird in ihres Volkes Mitte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Hat sich das Weib aber nicht verunreinigt und ist sie rein, so bleibt sie ungestraft und kann Samen empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'Dies ist das Gesetz über Eifersucht, wenn ein Weib hinter ihrem Manne abweicht und sich verunreinigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'Oder wenn in einen Mann der Geist der Eifersucht übergeht und er auf sein Weib eifersüchtig wird, so lasse er das Weib vor Jehovah stehen und der Priester tue ihr alles nach diesem Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'Und der Mann sei unschuldig an der Missetat, das Weib aber trägt ihre Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Rede zu den Söhnen Israels und sprich zu ihnen: So ein Mann oder ein Weib ein besonderes Nasiräatsgelübde gelobt, dem Jehovah sich zu enthalten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'Von Wein und starkem Getränke enthalte er sich, Essig von Wein und Essig von starkem Getränk soll er nicht trinken, auch keinerlei Getränk von Weinbeeren soll er trinken, auch keine frischen Weinbeeren oder getrocknete essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Alle Tage seiner Weihe soll er nichts essen, was vom Weinstock des Weines bereitet wird, von den Kernen bis zur Hülse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Alle Tage des Gelübdes seiner Weihe gehe kein Schermesser über sein Haupt. Bis die Tage erfüllt sind, die er sich Jehovah geweiht hat, soll er heilig sein und die Blöße des Haares seines Hauptes wachsen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Alle Tage seiner Weihe für Jehovah soll er zu keinem Toten gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'An seinem Vater und an seiner Mutter, an seinem Bruder und an seiner Schwester verunreinige er sich nicht, wenn sie sterben; denn die Weihe seines Gottes ist auf seinem Haupte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Alle Tage seiner Weihe ist er dem Jehovah heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Und wenn einer unversehens plötzlich vor ihm stirbt und das Haupt seines Nasiräats verunreinigt, so schere er sein Haupt am Tage seiner Reinigung. Am siebenten Tage schere er es ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'Und am achten Tage bringe er zwei Turteltauben oder zwei junge Tauben zum Priester zum Eingang des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Und der Priester mache eine als Sündopfer und eine als Brandopfer und sühne über ihm dafür, daß er sich über dem Toten versündigt hat, und heilige sein Haupt an diesem Tag;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'Und er weihe Jehovah die Tage seines Nasiräats und bringe ein einjähriges Lamm als Schuldopfer; und die ersteren Tage soll er fallen lassen, darum daß seine Weihe verunreinigt worden war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'Und dies ist das Gesetz des Nasiräers: Am Tage, da die Tage seiner Weihe sich erfüllen, bringe man ihn zum Eingang des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'Und er bringe seine Opfergabe dar dem Jehovah, ein einjähriges Lamm ohne Fehl als Brandopfer, ein einjähriges Mutterlamm ohne Fehl als Sündopfer und einen Widder ohne Fehl als Dankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'Und einen Korb mit Ungesäuertem aus Semmelmehl, Kuchen mit Öl vermischt, und ungesäuerte Fladen mit Öl gesalbt, beides ihr Speiseopfer und ihre Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Und der Priester bringe sie dar vor Jehovah und mache sein Sündopfer und sein Brandopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'Und dem Widder soll er dem Jehovah zum Dankopfer machen mit dem Korb des Ungesäuerten, und der Priester mache sein Speiseopfer und sein Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'Und der Nasiräer schere am Eingang des Versammlungszeltes sein geweihtes Haupt, und nehme das Haar des Hauptes seines Nasiräats und gebe es auf das Feuer, das unter dem Dankopfer ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Und der Priester nehme den gekochten Bug von dem Widder und einen ungesäuerten Kuchen aus dem Korb und einen ungesäuerten Fladen und gebe sie auf die Hände des Nasiräers, nachdem er sein Geweihtes geschoren hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'Und der Priester webe sie als Webe vor Jehovah. Heilig ist es dem Priester samt der Webebrust und der Hebeschulter; und danach trinke der Nasiräer Wein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'Das ist das Gesetz für den Nasiräer, der seine Opfergabe dem Jehovah gelobt wegen seiner Weihe, außer dem, wozu seine Hand zureicht. Gemäß seinem Gelübde, das er gelobt, so soll er tun nach dem Gesetz seiner Weihe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Rede zu Aharon und zu seinen Söhnen und sprich: So sollt ihr segnen die Söhne Israels. Sprechet zu ihnen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Jehovah segne dich und behüte dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Jehovah lasse Sein Angesicht leuchten über dir und sei dir gnädig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Jehovah erhebe Sein Angesicht auf dich und gebe dir Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Und sie sollen Meinen Namen legen auf die Söhne Israel, und Ich werde sie segnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'Und es geschah am Tage, da Mose die Aufrichtung der Wohnung vollendete und sie gesalbt und sie geheiligt und alle ihre Geräte und den Altar und all seine Geräte, und er sie gesalbt und geheiligt hatte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'Brachten die Fürsten Israels, die Häupter des Hauses ihrer Väter, sie, die Fürsten der Stämme, sie, die über den Gemusterten standen, dar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'Und sie brachten ihre Opfergabe vor Jehovah sechs Sänftewagen und zwölf Rinder, einen Wagen auf zwei Fürsten, und einen Ochsen auf einen; und sie brachten sie dar vor die Wohnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Und Jehovah sprach zu Mose und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Nimm sie von ihnen und sie seien zu dienen zum Dienste des Versammlungszeltes, und gib sie den Leviten, einem jeden Mann nach Bedarf seines Dienstes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Und Mose nahm die Wagen und die Rinder und gab sie den Leviten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Zwei der Wagen und vier der Rinder gab er den Söhnen Gerschons nach Bedarf ihres Dienstes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'Und vier Wagen und acht Rinder gab er Meraris Söhnen nach dem Bedarf ihres Dienstes unter der Hand von Ithamar, dem Sohne Aharons, des Priesters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Und den Söhnen Kohaths gab er nichts; denn der Dienst des Heiligtums war auf ihnen; auf der Schulter trugen sie es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'Und die Fürsten brachten dar das Einweihungsopfer des Altars am Tage, da er gesalbt wurde, und die Fürsten brachten dar ihre Opfergabe vor den Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Und Jehovah sprach zu Mose: Ein Fürst den Tag, ein Fürst den Tag laß sie darbringen ihre Opfergabe zur Einweihung des Altars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Und der am ersten Tage seine Opfergabe darbrachte, war Nachschon, der Sohn Amminadabs, vom Stamme Judah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'Und seine Opfergabe war eine Schüssel von Silber von hundertdreißig Schekeln, ein Sprengbecken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide gefüllt mit Semmelmehl, mit Öl vermischt, zu einem Speiseopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'Eine Schale von zehn Goldschekeln, voll Räucherwerks.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'Ein Farre, ein Junges von den Rindern, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'Und zum Dankopfer, zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe von Nachschon, dem Sohne Amminadabs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Am zweiten Tage brachte dar Nethaneel, der Sohn Zuars, der Fürst von Issaschar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'Er brachte seine Opfergabe dar: eine Schüssel von Silber von hundertdreißig Schekeln, ein Sprengbecken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide gefüllt mit Semmelmehl, mit Öl vermischt, zum Speiseopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'Eine Schale von zehn Goldschekeln, voll Räuchwerks,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'Ein Farre, eine Junges von den Rindern, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'Und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe von Nethaneel, Zuars Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Am dritten Tage der Fürst der Söhne Sebuluns, Eliab, der Sohn Chelons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Seine Opfergabe war: eine Schüssel von Silber von hundertdreißig Schekeln, ein Sprengbecken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide gefüllt mit Semmelmehl, mit Öl vermischt, zum Speiseopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'Eine Schale von zehn Goldschekeln, voll Räuchwerks;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'Ein Farre, ein Junges von den Rindern, ein Widder, ein einjähriges Lamm zum Brandopfer,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'Und zum Dankopfer: zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe von Eliab, dem Sohne Chelons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Am vierten Tage der Fürst der Söhne Rubens, Elizur, der Sohn Sche- deurs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Seine Opfergabe war: eine Schüssel von Silber von hundertdreißig Schekeln, ein Sprengbecken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide voll Semmelmehls mit Öl vermischt, als Speiseopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'Eine Schale von zehn Goldschekeln voll Räuchwerks,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'Ein Farre, ein Junges von den Rindern, ein Widder, ein einjähriges Lamm zum Brandopfer,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'Und als Dankopfer: zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe Elizurs, des Sohnes von Schedeur.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Am fünften Tage der Fürst der Söhne Simeons, Schelumiel, der Sohn Zurischaddais.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Seine Opfergabe war: eine Schüssel von Silber von hundertdreißig Schekeln, ein Sprengbecken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide mit Semmelmehl gefüllt, mit Öl vermischt, zum Speiseopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'Eine Schale von zehn Goldschekeln, voll von Räuchwerk;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'Ein Farre, das Junge von den Rindern, ein Widder, ein einjähriges Lamm zum Brandopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'Und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe Schelumiels, des Sohns von Zurischaddai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Am sechsten Tage der Fürst der Söhne Gads, Eljasaph, der Sohn Deguels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Seine Opfergabe: eine Schüssel von Silber, hundertdreißig Schekeln, ein Sprengbecken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide voll von Semmelmehl, mit Öl vermischt, zum Speiseopfer.');
