INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'Und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe von Eljasaph, dem Sohne Deguels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Am siebenten Tage der Fürst der Söhne Ephraims, Elischama, der Sohn Ammihuds.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Seine Opfergabe war: eine Schüssel von Silber, hundertdreißig Schekel, ein Sprengbekken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide gefüllt mit Semmelmehl, mit Öl vermischt, zum Speiseopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'Eine Schale von zehn Schekeln Gold, mit Räuchwerk gefüllt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'Ein Farre, das Junge vom Rind, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'Und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe von Elischama, dem Sohne Ammihuds.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Am achten Tage, der Fürst der Söhne Menaschehs Gamliel, der Sohn Pedahzurs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Seine Opfergabe war: eine Schüssel von Silber, hundertdreißig Schekel, ein Sprengbekken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide gefüllt mit Semmelmehl, mit Öl vermischt, zum Speiseopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'Eine Schale von zehn Goldschekeln, mit Räuchwerk gefüllt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'Ein Farre, das Junge vom Rind, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'Und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe von Gamliel, dem Sohn des Pedahzur.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Am neunten Tage, der Fürst der Söhne Benjamins Abidan, der Sohn des Gideoni.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Seine Opfergabe war: eine Schüssel von Silber, von hundertdreißig Schekeln, ein Sprengbecken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide gefüllt mit Semmelmehl, mit Öl vermischt, zum Speiseopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'Eine Schale von zehn Goldschekeln, mit Räuchwerk gefüllt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'Ein Farre, das Junge vom Rind, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'Und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe von Abidan, Gideonis Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Am zehnten Tage der Fürst der Söhne Dans, Achieser, der Sohn des Ammischaddai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Seine Opfergabe war: eine Schüssel von Silber, von hundertdreißig Schekeln, ein Sprengbecken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide gefüllt mit Semmelmehl, mit Öl vermischt, zum Speiseopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'Eine Schale von zehn Goldschekeln, mit Räuchwerk gefüllt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'Ein Farre, das Junge vom Rind, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'Und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe von Achieser, des Ammischaddais Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Am elften Tage der Fürst der Söhne Aschers, Pagiel, der Sohn Ochrans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Seine Opfergabe war: eine Schüssel von Silber, von hundertdreißig Schekeln, ein Sprengbecken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide gefüllt mit Semmelmehl, mit Öl vermischt, zum Speiseopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'Eine Schale von zehn Goldschekeln, mit Räuchwerk gefüllt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'Ein Farre, das Junge vom Rind, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'Und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe von Pagiel, dem Sohne Ochrans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Am zwölften Tage der Fürst der Söhne Naphthalis, Achira, Enans Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Seine Opfergabe war: eine Schüssel von Silber, von hundertdreißig Schekeln, ein Sprengbecken von Silber von siebzig Schekeln, nach dem Schekel des Heiligtums, beide gefüllt mit Semmelmehl, mit Öl vermischt, zum Speiseopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'Eine Schale von zehn Goldschekeln, mit Räuchwerk gefüllt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'Ein Farre, das Junge vom Rind, ein Widder, ein einjähriges Lamm zum Brandopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'Ein Ziegenbock zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'Und zum Dankopfer zwei Rinder, fünf Widder, fünf Böcke, fünf einjährige Lämmer. Dies die Opfergabe von Achirahs, des Sohns von Enan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'Dies ist das Einweihungsopfer des Altars am Tag seiner Salbung von den Fürsten von Israel; zwölf Schüsseln von Silber, zwölf Sprengbecken von Silber, zwölf Schalen von Gold,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'Hundertdreißig Schekel Silber die eine Schüssel, und siebzig das eine Sprengbecken. Alles Silber der Gefäße war zweitausendvierhundert, nach dem Schekel des Heiligtums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Zwölf Schalen von Gold, mit Räuchwerk gefüllt, zehn und zehn die Schale, nach dem Schekel des Heiligtums, alles Gold der Schalen war hundertzwanzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Alle Rinder zum Brandopfer: zwölf Farren, zwölf Rinder, zwölf Lämmer von einem Jahr, und ihr Speiseopfer; und zwölf Ziegenböcke zum Sündopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'Und alles Rind des Dankopfers: vierundzwanzig Farren, sechzig Widder, sechzig Böcke, sechzig einjährige Lämmer. Das ist die Einweihung des Altars, nachdem er gesalbt worden war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'Und als Mose in das Versammlungszelt einging, um mit Ihm zu reden, da hörte er die Stimme zu ihm reden vom Gnadenstuhl herab, der auf der Lade des Zeugnisses war, zwischen den beiden Cheruben heraus, und Er redete zu ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Rede zu Aharon und sprich zu ihm: Wenn du die Lampen aufsteckst, an der Vorderseite des Leuchters sollen die sieben Lampen leuchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'Und Aharon tat also, und steckte seine Lampen auf die Vorderseite des Leuchters, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'Und das Werk des Leuchters war dies: getriebenes Gold an seinem Schaft und an seinen Blumen getrieben; nach dem Gesicht, das Jehovah den Mose hatte sehen lassen, so machte er den Leuchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Nimm die Leviten aus der Mitte der Söhne Israels und reinige sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'Und tue also mit ihnen, sie zu reinigen: Sprenge auf sie Wasser der Entsündigung; und sie sollen das Schermesser über ihr ganzes Fleisch gehen lassen, und ihre Kleider waschen, und sich reinigen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Und sollen nehmen einen Farren, das Junge vom Rind, und sein Speiseopfer, Semmelmehl mit Öl vermischt, und einen zweiten jungen Farren vom Rind sollst du nehmen zum Sündopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'Und lasse die Leviten vor das Versammlungszelt nahen, und versammle die ganze Gemeinde der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Und lasse die Leviten vor Jehovah nahen, und die Söhne Israels ihre Hände auf die Leviten legen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'Und Aharon webe die Leviten als Webe vor Jehovah von den Söhnen Israels, auf daß sie den Dienst Jehovahs dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'Und die Leviten sollen ihre Hände auf den Kopf der Farren legen, und du sollst den einen als Sündopfer und den andern als Brandopfer machen, die Leviten zu sühnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'Und laß die Leviten vor Aharon und vor seine Söhne stehen und sollst sie weben als Webe für Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Und sollst die Leviten aus der Mitte der Söhne Israels scheiden, auf daß die Leviten Mein seien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Und danach sollen die Leviten eingehen, in dem Versammlungszelt zu dienen. Und du sollst sie reinigen und als Webe weben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Denn gegeben, gegeben sind sie Mir aus der Mitte der Söhne Israels statt allem, was den Mutterschoß bricht, für alle Erstgeburt an den Söhnen Israels habe Ich sie Mir genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Denn Mein ist alle Erstgeburt unter den Söhnen Israels vom Menschen und vom Vieh. Am Tage, da Ich alle Erstgeburt im Lande Ägypten schlug, habe Ich sie Mir geheiligt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Und habe die Leviten statt aller Erstgeburt unter den Söhnen Israels genommen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'Und gegeben die Leviten Aharon und seinen Söhnen als Gegebene aus der Mitte der Söhne Israels, zu dienen den Dienst der Söhne Israels im Versammlungszelt und zu sühnen über die Söhne Israels, daß keine Plage sei über die Söhne Israels, wenn die Söhne Israels zu dem Heiligtum herzutreten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'Und Mose und Aharon und die ganze Gemeinde der Söhne Israels taten den Leviten nach allem, was Jehovah dem Mose über die Leviten geboten hatte, so taten ihnen die Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'Und die Leviten entsündigten sich, und wuschen ihre Kleider, und Aharon webte sie als Webe vor Jehovah, und Aharon sühnte sie, um sie zu reinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Und danach kamen die Leviten hinein, ihren Dienst zu dienen im Versammlungszelt vor Aharon und vor seinen Söhnen. Wie Jehovah Mose über die Leviten geboten hatte, also taten sie ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'Dies ist für die Leviten: Von dem fünfundzwanzigsten Jahre und aufwärts rückte er aus in das Heer in den Dienst beim Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'Und von fünfzig Jahren an trete er aus dem Heere des Dienstes zurück und diene nicht mehr;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'Und er mag Dienst tun mit seinen Brüdern im Versammlungszelt, um der Hut zu warten. Keinen Dienst soll er aber dienen. Also sollst du den Leviten tun in ihrer Hut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'Und Jehovah redete zu Mose in der Wüste Sinai im zweiten Jahr, da sie aus dem Lande Ägypten ausgingen, im ersten Monat, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Die Söhne Israels sollen das Passah zu seiner bestimmten Zeit halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Am vierzehnten Tage dieses Monats sollt ihr es bereiten gegen Abend zur bestimmten Zeit; nach allen seinen Satzungen und nach allen seinen Rechten sollt ihr es bereiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Und Mose redete zu den Söhnen Israels, sie sollten das Passah bereiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'Und sie bereiteten das Passah im ersten Monat am vierzehnten Tage gegen Abend in der Wüste Sinai. Nach allem, was Jehovah dem Mose geboten hatte, also taten die Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Und es geschah, daß Männer, die wegen der Leiche eines Menschen unrein waren, das Passah an diesem Tage nicht zu bereiten vermochten. Und sie nahten vor Mose und Aharon an jenem Tage:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'Und es sprachen diese Männer zu ihm: Wir sind unrein einer Leiche eines Menschen wegen. Warum soll es uns entzogen sein, daß wir unsere Opfergabe nicht zu seiner bestimmten Zeit dem Jehovah inmitten der Söhne Israels darbringen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'Und Mose sprach zu ihnen: Stehet hier, und ich will hören, was Jehovah euch gebietet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Rede zu den Söhnen Israels und sprich: Jeder Mann, der ob einer Leiche unrein oder auf fernem Wege bei euch oder euren Geschlechtern ist, soll dem Jehovah das Passah bereiten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'Im zweiten Monat am vierzehnten Tage gegen Abend sollen sie es bereiten; mit ungesäuertem Brot und Bitterem sollen sie es essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'Sie sollen nichts davon bis zum Morgen verbleiben lassen und kein Bein daran zerbrechen. Nach aller Satzung des Passah sollen sie es bereiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Aber der Mann, der rein und nicht auf dem Wege war, und unterließ, das Passah zu bereiten, dessen Seele soll ausgerottet werden von seinem Volke, daß er die Opfergabe Jehovahs zu seiner bestimmten Zeit nicht dargebracht hat. Dieser Mann soll tragen seine Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Und wenn ein Fremdling bei euch sich aufhält und will dem Jehovah das Passah bereiten, der soll es bereiten nach der Satzung des Passah und nach seinem Recht. Eine Satzung soll bei euch sein für den Fremdling wie für den Eingeborenen des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'Und am Tage der Aufrichtung der Wohnung bedeckte die Wolke die Wohnung des Zeltes des Zeugnisses; und am Abend war es auf der Wohnung anzusehen wie ein Feuer bis an den Morgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'So war es beständig. Die Wolke bedeckte sie; und des Nachts war es anzusehen wie Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'Und je wie die Wolke vom Zelte aufstieg, danach brachen die Söhne Israels auf, und an dem Orte, da sich die Wolke niederließ, da lagerten sich die Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Nach dem Befehl Jehovahs brachen die Söhne Israels auf, und nach dem Befehl Jehovahs lagerten sie sich. Alle die Tage, welche die Wolke über der Wohnung weilte, lagerte sie sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'Und wenn die Wolke viele Tage lang über der Wohnung weilte, da hüteten die Söhne Israels der Hut Jehovahs und brachen nicht auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'Und geschah es, daß die Wolke nur wenige Tage über der Wohnung war, so lagerten sie sich auf den Befehl Jehovahs, und auf Jehovahs Befehl brachen sie auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'Und geschah es, daß die Wolke vom Abend bis zum Morgen da war, und daß die Wolke am Morgen aufstieg, so brachen sie auf; und ob die Wolke bei Tag oder bei Nacht aufstieg, so brachen sie auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Wenn die Wolke zwei Tage oder einen Monat oder längere Tage über der Wohnung weilte, so blieben die Söhne Israels gelagert und brachen nicht auf, und wenn sie aufstieg, so brachen sie auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Nach dem Befehl Jehovahs lagerten sie, und nach dem Befehl Jehovahs brachen sie auf; sie hüteten der Hut Jehovahs nach dem Befehl Jehovahs durch die Hand Moses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Mache dir zwei Trompeten von Silber; von getriebener Arbeit sollst du sie machen, auf daß sie dir seien zur Zusammenberufung der Gemeinde und zum Aufbrechen der Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Und stößt man in sie, so soll die ganze Gemeinde zum Eingang des Versammlungszeltes zu dir zusammenkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Und stoßen sie in eine, so sollen die Fürsten, die Häupter der Tausende Israels zu dir zusammenkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Und blaset ihr Lärm, so sollen die Lager aufbrechen, die vorn gelagert sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Und blaset ihr Lärm zum zweitenmal, so brechen die Lager auf, die zur rechten lagern. Für die Aufbrüche sollen sie Lärm blasen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Und wenn ihr zur Versammlung versammelt, sollt ihr hineinstoßen und nicht Lärm blasen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'Und die Söhne Aharons, die Priester, sollen in die Trompeten stoßen, und sie sollen euch zu einer ewigen Satzung sein für eure Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'Und wenn ihr in den Streit einziehet in eurem Land wider den Dränger, der euch bedrängt, so sollt ihr mit den Trompeten Lärm blasen, und euer wird vor Jehovah, eurem Gott, gedacht, auf daß ihr von euren Feinden gerettet werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'Und an den Tagen eurer Fröhlichkeit und an euren Festzeiten und an euren Neumonden, da sollt ihr in die Trompeten stoßen über euren Brandopfern und über euren Dank- opfern, und sie werden zum Andenken an euch vor eurem Gott sein. Ich, Jehovah, bin euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'Und es geschah im zweiten Jahr, im zweiten Monat, am zwanzigsten des Monats, daß die Wolke von der Wohnung des Zeugnisses aufstieg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'Und die Söhne Israels brachen auf nach ihren Wanderungen aus der Wüste Sinai, und die Wolke weilte in der Wüste Paran.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Und sie brachen zuerst auf nach dem Befehl Jehovahs durch Moses Hand:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'Und zuerst brach auf das Banner des Lagers der Söhne Judahs nach seinen Heerscharen, und über sein Heer war Nachschon, der Sohn Amminadabs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'Und über das Heer des Stammes der Söhne Issaschars Nethaneel, der Sohn Zuars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'Und über das Heer des Stammes der Söhne Sebuluns Eliab, der Sohn Chelons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Und die Wohnung ward abgenommen, und die Söhne Gerschons brachen auf und die Söhne Meraris, welche die Wohnung trugen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Und das Banner von Rubens Lager nach seinen Heerscharen brach auf. Und über ihr Heer war Elizur, Schedeurs Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'Und über das Heer des Stammes der Söhne Simeons Schelumiel, der Sohn Zurischaddais.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'Und über das Heer des Stammes der Söhne Gads Eljasaph, der Sohn Deguels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Und es brachen die Kohathiten auf, die das Heiligtum trugen. Und sie richteten die Wohnung auf, bis diese kamen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Und das Banner des Lagers der Söhne Ephraims brach auf nach seinen Heerscharen, und über sein Heer war Elischama, der Sohn Ammihuds;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'Und über das Heer des Stammes der Söhne Menaschehs Gamliel, der Sohn Pedahzurs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'Und über das Heer des Stammes der Söhne Benjamins Abidan, Sohn Gideonis;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Und das Banner des Lagers der Söhne Dans brach auf, als Nachzug für alle Lager nach ihren Heerscharen, und über sein Heer war Achieser, der Sohn Ammischaddais,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'Und über das Heer des Stammes der Söhne Aschers Pagiel, Sohn Ochrans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'Und über das Heer des Stammes der Söhne Naphthalis, Achira, der Sohn Enans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'Dies sind die Wanderzüge der Söhne Israels nach ihren Heerscharen; und sie brachen auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'Und Mose sprach zu Chobab, dem Sohne Reguels, dem Midianiter, Moses Schwager: Wir brechen auf nach dem Orte, von dem uns Jehovah sprach: Ich will ihn euch geben. Geh mit uns, so wollen wir dir Gutes tun; denn Jehovah hat Gutes geredet über Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'Und er sprach zu ihm: Ich will nicht gehen; sondern ich will in mein Land und in meinen Geburtsort gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'Und er sprach: Verlaß uns doch nicht; denn du weißt, wo wir uns lagern in der Wüste, und sollst unser Auge sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Und es soll geschehen, wenn du mit uns gehst, und das Gute uns wird, das Jehovah an uns Gutes tun will, so wollen wir dir Gutes tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'Und sie brachen auf vom Berge Jehovahs drei Tagereisen, und die Bundeslade Jehovahs brach auf vor ihnen her drei Tagreisen, um ihnen eine Ruhestätte auszuspähen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Und die Wolke Jehovahs war über ihnen bei Tag, wenn sie vom Lager aufbrachen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'Und es geschah, wenn die Lade aufbrach, daß Mose sprach: Mache dich auf, Jehovah, daß Deine Feinde sich zerstreuen und Deine Hasser vor Dir fliehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Und wenn sie ruhte, sprach er: Kehre zurück, Jehovah, zu den Zehntausenden der Tausende Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'Und da das Volk sich übel beklagte vor den Ohren Jehovahs, hörte es Jehovah, und Sein Zorn entbrannte, und Jehovahs Feuer brannte wider sie und fraß am Ende des Lagers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'Und das Volk schrie zu Mose, und Mose betete zu Jehovah und das Feuer legte sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'Und er nannte den Namen dieses Orts Taberah, weil das Feuer Jehovahs unter ihnen gebrannt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Und es gelüstete das Gesindel, das unter ihnen war, ein Gelüste, also, daß auch die Söhne Israels wieder weinten und sagten: Wer speist uns mit Fleisch?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Wir gedenken der Fische, die wir in Ägypten umsonst aßen, und der Gurken und der Melonen und des Lauchs und der Zwiebeln und des Knoblauchs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Und nun vertrocknet unsere Seele; nichts von allem ist da. Nichts als das Man ist vor unseren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Und das Man war wie der Samen von Koriander und sein Aussehen war wie das Aussehen des Bedellion.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Das Volk lief umher und las auf; und sie mahlten es in der Mühle oder zerstießen es im Mörser und kochten es im Kessel und machten Kuchen daraus, und sein Geschmack war wie der Geschmack eines Ölkuchens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'Und wenn der Tau nachts auf das Lager herabkam, da kam auch das Man darauf herab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Und Mose hörte das Volk weinen in seinen Familien, jeden Mann am Eingang seines Zeltes, und der Zorn Jehovahs entbrannte sehr, und in Moses Augen war es böse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'Und Mose sprach zu Jehovah: Für was tust Du so übel an Deinem Knechte? Und warum habe ich nicht Gnade in Deinen Augen gefunden, daß Du die Last dieses ganzen Volkes auf mich legst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Habe denn ich all dies Volk empfangen, habe ich es geboren, daß Du zu mir sprichst: Hebe es aus auf an deinen Busen, wie der Wärter den Säugling hinaufträgt, auf den Boden, den Du seinen Vätern geschworen hast?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Woher habe ich Fleisch, daß ich es diesem ganzen Volke gebe? Denn sie weinen wider mich und sagen: Gib uns Fleisch, daß wir essen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Ich vermag nicht allein all dieses Volk zu tragen; denn es ist zu schwer für mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Und wenn Du also mit mir tust, so erwürge mich doch, habe ich Gnade in Deinen Augen gefunden, daß ich mein Übel nicht sehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Und Jehovah sprach zu Mose: Versammle Mir siebzig Männer aus den Ältesten Israels, die du als Älteste des Volkes und als seine Vorsteher kennst, und nimm sie zum Versammlungszelt und lasse sie sich dort mit dir hinstellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Und Ich will herabkommen und mit dir daselbst reden und von dem Geiste, der auf dir ist, wegnehmen und auf sie legen, auf daß sie mit dir an der Last des Volkes tragen, und du sie nicht allein tragest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Und zu dem Volke sollst du sprechen: Heiliget euch auf morgen. Und ihr sollt Fleisch essen; denn ihr habt vor den Ohren Jehovahs geweint und gesprochen: Wer läßt uns Fleisch essen? Denn wir hatten es gut in Ägypten. Und Jehovah wird euch Fleisch geben, daß ihr esset.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'Nicht einen Tag sollt ihr es essen und nicht zwei Tage und nicht fünf Tage und nicht zehn Tage und nicht zwanzig Tage;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'Bis zu einem Monat der Tage, bis es euch zur Nase herauskommt und zum Überdruß wird, weil ihr Jehovah, Der in eurer Mitte ist, verschmäht und vor Ihm geweint habt und gesagt: Warum sind wir doch aus Ägypten ausgegangen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'Und Mose sprach: Sechshunderttausend Fußgänger ist das Volk, in dessen Mitte bin ich, und Du sprichst: Ich will ihnen Fleisch geben, daß sie einen Monat der Tage essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Soll Kleinvieh und Rind für sie geschlachtet werden, daß es sich findet für sie? Oder sollen sich alle Fische des Meeres für sie versammeln, daß es sich findet für sie?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Und Jehovah sprach zu Mose: Ist die Hand Jehovahs zu kurz geworden? Du sollst nun sehen, ob Mein Wort bei dir zutrifft oder nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Und Mose ging heraus und redete zu dem Volk die Worte Jehovahs und versammelte siebzig Männer aus den Ältesten des Volkes und ließ sie um das Zelt her stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'Und Jehovah kam in der Wolke herab und redete zu ihm und nahm weg von dem Geiste, der auf ihm war, und gab ihn auf die siebzig Männer, die Ältesten; und es geschah, als der Geist auf ihnen ruhte, daß sie weissagten, aber nicht wieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'Und zwei Männer waren im Lager verblieben, der Name des einen war Eldad und der Name des zweiten Medad: und der Geist ruhte auf ihnen: und sie waren unter den Aufgeschriebenen, waren aber nicht zu dem Zelte herausgekommen, und sie weissagten in dem Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Und ein Junge lief und sagte es Mose an und sprach: Eldad und Medad weissagen in dem Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Und Joschua, der Sohn Nuns, Moses Diener, von seinen Auserwählten, antwortete und sprach: Mein Herr, Mose, wehre es ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Mose aber sprach zu ihm: Eiferst du für mich? Und wer gäbe es, daß das ganze Volk Jehovahs weissagte, daß Jehovah Seinen Geist auf sie gäbe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'Und Mose versammelte sich, er und die Ältesten Israels, in das Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Und ein Wind brach auf von Jehovah und raffte Wachteln vom Meere auf und ließ sie herab auf das Lager, wie eine Tagereise hier und wie eine Tagereise da, rings um das Lager her, und etwa zwei Ellen über der Oberfläche der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'Und das Volk machte sich auf diesen ganzen Tag und die ganze Nacht und den ganzen morgenden Tag, und sie sammelten die Wachteln. Wer wenig hatte, sammelte zehn Chomer. Und sie breiteten sie für sich aus rings um das Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Noch war das Fleisch zwischen ihren Zähnen, ehe es zerkaut war, da entbrannte der Zorn Jehovahs wider das Volk, und Jehovah schlug das Volk mit einem sehr großen Schlag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'Und man nannte den Namen dieses Ortes Kibroth Hattaavah, weil sie allda das Volk, das es gelüstet hatte, begruben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Von Kibroth Hattaavah brach das Volk auf nach Chazeroth und sie waren in Chazeroth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'Und Mirjam und Aharon redeten wider Mose wegen des kuschitischen Weibes, das er nahm; denn er hatte ein kuschitisches Weib genommen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'Und sprachen: Redet Jehovah bloß in Mose? Redet Er nicht auch in uns? Und Jehovah hörte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Und der Mann Mose war sehr sanftmütig, mehr denn irgendein Mensch auf dem Boden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'Und Jehovah sprach plötzlich zu Mose und zu Aharon und zu Mirjam: Gehet hinaus, ihr drei, zu dem Versammlungszelt! Und sie gingen hinaus, sie drei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'Und Jehovah kam in einer Wolkensäule herab und stand am Eingang des Zeltes und rief Aharon und Mirjam und sie kamen beide heraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'Und Er sprach: Höret nun Meine Worte: Wenn ein Prophet Jehovahs bei euch ist, so tue Ich Mich ihm kund im Gesichte; im Traume rede Ich in ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Nicht so mit Meinem Knechte Mose. In Meinem ganzen Hause ist er Mir treu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Mund zu Mund rede Ich in ihm und im Gesicht, und nicht in Rätseln. Und das Abbild Jehovahs erblickt er. Und warum habt ihr euch nicht gefürchtet, wider Meinen Knecht, wider Mose zu reden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'Und es entbrannte der Zorn Jehovahs wider sie, und Er ging weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'Und die Wolke wich von dem Zelt weg, und siehe, Mirjam ward aussätzig wie der Schnee. Und Aharon wandte sich zu Mirjam, und siehe, sie war aussätzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'Und Aharon sprach zu Mose: Ach, Herr, lege doch die Sünde nicht auf uns, worin wir zu Toren und worin wir zu Sündern geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Laß sie doch nicht sein, wie der Tote, der aus seiner Mutter Schoß ausgeht, und dessen Fleisch schon halb zerfressen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Und Mose schrie zu Jehovah und sprach: Ach Gott, heile sie doch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'Und Jehovah sprach zu Mose: Und hätte ihr Vater ihr ins Gesicht gespuckt, sollte sie nicht darob sieben Tage Schande fühlen? Man schließe sie sieben Tage außerhalb des Lagers ein, und danach nehme man sie auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'Und Mirjam wurde sieben Tage au-ßerhalb des Lagers eingeschlossen, und das Volk brach nicht auf, bis Mirjam aufgenommen ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Und danach brach das Volk auf von Chazeroth und sie lagerten in der Wüste Paran.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Sende die Männer aus, daß sie das Land Kanaan, das Ich den Söhnen Israels gebe, ausspähen; je einen Mann von dem Stamm seiner Väter, ein jeder ein Fürst unter ihnen, sollt ihr aussenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Und Mose sandte sie von der Wüste Paran aus, nach Jehovahs Befehl; sie alle waren Männer, die Häupter der Söhne Israels waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'Und das sind ihre Namen: Für den Stamm Ruben Schammna, Sakkurs Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'Für den Stamm Schimeon Schaphat, Choris Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'Für den Stamm Judah Kaleb, Sohn des Jephunneh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'Für den Stamm Jissaschar Jigeal, Josephs Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'Für den Stamm Ephraim Hoschea, Sohn des Nun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'Für den Stamm Benjamin Palti, den Sohn Raphus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'Für den Stamm Sebulon Gadiel, Sodis Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'Für Josephs Stamm, für den Stamm Menascheh Gaddi, Susis Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'Für den Stamm Dan Ammiel, Gemallis Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'Für den Stamm Ascher Sethur, den Sohn Michaels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'Für den Stamm Naphthali Nachbi, Vaphsis Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'Für den Stamm Gad Geuel, Machis Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'Dies sind die Namen der Männer, die Mose sandte, das Land auszuspähen. Und Mose nannte Hoschea, den Sohn Nuns Jehoschua.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'Und Mose sandte sie aus, das Land Kanaan auszuspähen und sprach zu ihnen: Gehet hier hinauf gen Mittag und steiget auf den Berg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'Und sehet das Land, wie es ist, und das Volk, das darin wohnt, ob es stark ist oder schwach, ob ihrer wenige oder viele sind;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'Und wie das Land ist, wo es wohnet, ob es gut oder schlecht ist, und wie die Städte sind, in denen es wohnt, ob sie in Lagern oder in Festungen wohnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'Und wie das Land ist, ob fett oder mager, ob es Bäume darin gibt, oder nicht. Und seid stark und nehmet von der Frucht des Landes; und es waren eben die Tage der Erstlinge der Weinbeeren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Und sie zogen hinauf und spähten das Land aus von der Wüste Zin bis Rehob, da man nach Chamath kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Und sie gingen hinauf gen Mittag und kamen bis Chebron und dort waren Achiman, Scheschai und Thalmai, Enaks Kinder; und Chebron war sieben Jahre vor Zoan in Ägypten erbaut;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'Und kamen bis in das Bachtal Eschkol und schnitten dort eine Rebe mit einer Traube von Weinbeeren ab und trugen sie auf einer Trage zu zweien, und auch von den Granatäpfeln und von den Feigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Diesen Ort nennt man das Bachtal Eschkol, wegen der Traube, welche die Söhne Israels dort schnitten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'Und sie kehrten von der Ausspähung des Landes am Ende von vierzig Tagen zurück;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'Und gingen und kamen zu Mose und zu Aharon und zur ganzen Gemeinde der Söhne Israels zur Wüste Paran nach Kadesch, und brachten ihnen und der ganzen Gemeinde Bericht und ließen sie die Frucht des Landes sehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'Und erzählten ihm und sagten: Wir kamen in das Land, wohin du uns sandtest; und es fließet auch von Milch und Honig, und das ist seine Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Nur ist das Volk, das in dem Lande wohnt, stark; und die Städte sind befestigt und sehr groß, und auch die Enakskinder haben wir dort gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalek wohnt im Lande des Mittags und der Chethiter und der Jebusiter und der Amoriter wohnt auf dem Gebirge, und der Kanaaniter wohnt an dem Meer und zur Seite des Jordans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'Und Kaleb stillte das Volk für Mose und sprach: Lasset uns hinaufziehen und es einnehmen; denn wir vermögen es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Die Männer aber, die mit ihm hinaufgezogen waren, sprachen: Wir vermögen nicht wider das Volk hinaufzuziehen; denn es ist stärker denn wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'Und sie brachten ein Gerede aus über das Land, das sie ausgespäht, unter die Söhne Israels und sagten: Das Land, das wir durchzogen, es auszuspähen, ist ein Land, das seine Einwohner frißt, und alles Volk, das wir darinnen sahen, sind hohe Männer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Und wir haben dort die Riesen gesehen, Enaks Söhne, von den Riesen; und wir waren in unseren Augen wie Heuschrekken, und so waren wir in ihren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Und es erhob sich die ganze Gemeinde, und sie ließen hören ihre Stimme, und es weinte das Volk in dieser Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'Und es murrten wider Mose und wider Aharon alle Söhne Israels, und die ganze Gemeinde sprach zu ihnen: Wären wir doch im Land Ägypten gestorben, oder stürben wir doch in der Wüste da!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'Und warum bringt uns Jehovah in dieses Land hinein, daß wir durch das Schwert fallen, unsere Weiber und Kindlein zum Raube werden? Wäre es nicht besser für uns, wir kehrten nach Ägypten zurück?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'Und der eine sprach zu seinem Bruder: Lasset uns ein Haupt setzen und zurückkehren nach Ägypten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Und Mose und Aharon fielen auf ihr Angesicht vor der ganzen Versammlung der Gemeinde der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Und Joschua, der Sohn Nuns, und Kaleb, der Sohn Jephunnehs, von denen, die das Land ausgespäht, zerrissen ihre Kleider,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'Und sprachen zur ganzen Gemeinde der Söhne Israels und sagten: Das Land, das wir durchzogen, es auszuspähen, ist ein sehr, sehr gutes Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Wenn Jehovah Lust an uns hat, so wird Er uns in dieses Land hineinbringen und es uns geben, ein Land, das von Milch und Honig fließt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Nur empört euch nicht gegen Jehovah, dann dürfet ihr euch vor dem Volke des Landes nicht fürchten; denn unser Brot sind sie. Gewichen ist ihr Schatten von ihnen; und Jehovah ist mit uns, fürchtet sie nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Und es sprach die ganze Gemeinde, man solle sie mit Steinen steinigen. Und es erschien die Herrlichkeit Jehovahs in dem Versammlungszelt all den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'Und Jehovah sprach zu Mose: Wie lange will Mich dieses Volk lästern, und wie lange wollen sie nicht an Mich glauben bei all den Zeichen, die Ich in ihrer Mitte getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Ich will es schlagen mit Pestilenz und es hinaustreiben, will aber dich zu einer Völkerschaft machen, größer und mächtiger denn sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'Und Mose sprach zu Jehovah: Aber hören werden es die Ägypter, aus deren Mitte Du dies Volk mit Deiner Kraft heraufgeführt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'Und werden dem Einwohner dieses Landes sagen, welche hörten, daß Du, Jehovah, inmitten dieses Volkes bist, dem Du, Jehovah, Auge in Auge erschienst, und über dem Deine Wolke stand, und vor dem Du in der Wolkensäule gingst bei Tag, und in der Nacht in der Feuersäule,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Und der Du dieses Volk wie einen Mann getötet hast - sagen werden die Völkerschaften, die dieses Gerücht von Dir hören, und sprechen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Weil Jehovah nicht vermochte, dies Volk hineinzubringen in das Land, das Er ihm geschworen, da hat Er sie in der Wüste hingeschlachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Und nun laß doch Deine Kraft groß werden, o Herr, wie Du geredet hast und gesprochen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Jehovah ist langmütig und von großer Barmherzigkeit, der Missetat und Übertretung verzeiht, aber nicht ungestraft läßt, der heimsucht der Väter Missetat an den Söhnen ins dritte und vierte Glied;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Vergib doch der Missetat dieses Volkes nach Deiner großen Barmherzigkeit, wie Du auch verziehen hast diesem Volk von Ägypten an bis hierher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'Und Jehovah sprach: Ich habe vergeben nach deinem Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Und doch - Ich lebe, und die ganze Erde soll voll sein der Herrlichkeit Jehovahs -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'Denn alle diese Männer, die Meine Herrlichkeit und Meine Zeichen, die Ich in Ägypten und in der Wüste tat, gesehen, und nun diese zehnmal Mich versucht und nicht auf Meine Stimme gehört,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'Sollen nimmermehr das Land sehen, das ihren Vätern Ich zugeschworen habe, und alle, die Mich gelästert haben, sollen es nicht sehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Aber Meinen Knecht Kaleb will Ich, da ein anderer Geist in ihm war, und er Mir völlig nachgefolgt ist, in das Land hineinbringen, in das er gekommen war, und sein Same soll es erblich besitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Und der Amalekiter und der Kanaaniter wohnt im Talgrunde. Wendet euch morgen und brechet ihr nach der Wüste auf, auf den Weg dem Schilfmeer zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'Und Jehovah redete zu Mose und zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Wie lange ist es noch mit dieser bösen Gemeinde, daß sie wider Mich murren? Das Murren der Söhne Israels, das sie wider Mich gemurrt, habe Ich gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Sage ihnen: Ich lebe, spricht Jehovah, und will nach dem, was ihr vor Meinen Ohren geredet habt, also euch tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'In dieser Wüste sollen fallen eure Leichen, und alle, die gemustert worden unter euch, nach eurer ganzen Zahl, von zwanzig Jahren und darüber, die ihr wider Mich gemurrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'Ihr sollt nicht hineinkommen in das Land, in dem Ich Meine Hand erhoben, euch wohnen zu lassen, außer Kaleb, Jephunnehs Sohn, und Jehoschuah, der Sohn des Nun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Eure Kindlein aber, von denen ihr gesagt, daß sie zum Raube würden, sie will Ich hineinbringen; und sie sollen kennen das Land, das ihr verschmäht habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'Und eure Leichen sollen in dieser Wüste fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'Und eure Söhne sollen in der Wüste weiden vierzig Jahre und eure Buhlerei tragen, bis daß eure Leichen in der Wüste alle sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Nach der Zahl der Tage, die ihr das Land ausgespäht habt, vierzig Tage, sollt ihr ein Jahr für einen Tag und ein Jahr für einen Tag eure Missetaten tragen, vierzig Jahre, und wissen Meine Abwendung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Ich, Jehovah, habe es geredet: So werde Ich dieser ganzen bösen Gemeinde tun, die sich wider Mich zusammengetan hat. In dieser Wüste sollen sie alle werden und hier sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'Und die Männer, die Mose gesandt, das Land auszuspähen, und die zurückkehrten und die ganze Gemeinde wider ihn murren machten und ein Gerede über das Land ausbrachten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'Die Männer, die das böse Gerede ausbrachten, starben vor Jehovah durch die Plage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'Jehoschuah aber, der Sohn Nuns, und Kaleb, Jephunnehs Sohn, blieben am Leben von diesen Männern, die gegangen, das Land auszuspähen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'Und Mose redete diese Worte zu allen Söhnen Israels. Und es trauerte das Volk sehr;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'Und sie standen am frühen Morgen auf und zogen hinauf auf die Spitze des Berges und sprachen: Siehe uns hier, daß wir hinaufziehen nach dem Orte, von dem Jehovah gesprochen; denn wir haben gesündigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Und Mose sprach: Warum überschreitet ihr so den Befehl Jehovahs. Es wird euch nicht gelingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Zieht nicht hinauf; denn Jehovah ist nicht in eurer Mitte, auf daß ihr nicht geschlagen werdet vor euren Feinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Denn der Amalekiter und der Kanaaniter sind vor euch daselbst, und ihr werdet fallen durch das Schwert, darum, daß ihr euch von Jehovah zurückgewendet habt, und Jehovah nicht mit euch ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Sie aber waren aufgetrieben, und wollten auf die Spitze des Gebirges ziehen; die Bundeslade Jehovahs aber und Mose wichen nicht aus der Mitte des Lagers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Und der Amalekiter und der Kanaaniter, der auf diesem Gebirge wohnt, kamen herab und schlugen sie und zerstießen sie bis gen Chormah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Rede zu den Söhnen Israels und sprich zu ihnen: Wenn ihr kommt zum Land eurer Wohnsitze, das Ich euch geben werde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'Und Jehovah als Feueropfer ein Brandopfer oder Schlachtopfer machet zu besonderem Gelübde, oder ein freiwilliges, oder an euren Festzeiten, dem Jehovah einen Geruch der Ruhe zu machen vom Rind oder vom Kleinvieh;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'Dann bringe der seine Opfergabe vor Jehovah Darbringende ein Speiseopfer dar von einem Zehntel Semmelmehl mit einem viertel Hin Öl vermischt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'Und Wein zum Trankopfer sollst du ein viertel Hin zum Brandopfer oder zum Schlachtopfer tun für ein Lamm;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Oder zu einem Widder sollst du als Speiseopfer zwei Zehntel Semmelmehl tun, mit einem drittel Hin Öl vermischt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'Und Wein zum Trankopfer sollst du ein drittel Hin als Geruch der Ruhe dem Jehovah darbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Und bereitest du ein junges Rind als Brandopfer oder Schlachtopfer zu einem besonderen Gelübde oder einem Dankopfer dem Jehovah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'So sollst du zum jungen Rind als Speiseopfer darbringen drei Zehntel Semmelmehl mit einem halben Hin Öl vermischt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'Und Wein sollst du zum Trankopfer ein halbes Hin darbringen, als Feueropfer zum Geruch der Ruhe für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'So soll man tun bei dem einen Ochsen oder bei dem einen Widder, oder beim jungen Kleinvieh von Schafen oder Ziegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Je nach der Zahl, die ihr bereitet so sollt ihr für das einzelne nach ihrer Zahl bereiten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Jeder Eingeborene soll dieses so tun, wenn er Jehovah zum Geruch der Ruhe ein Feueropfer darbringt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'Und so ein Fremdling sich bei euch aufhält oder in eurer Mitte ist nach euren Geschlechtern, und Jehovah zum Geruch der Ruhe ein Feueropfer bereitet, der tue, wie ihr tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'Die Versammlung soll eine Satzung für euch und für den bei euch sich aufhaltenden Fremdling haben, eine ewige Satzung für eure Geschlechter; wie ihr, so soll auch der Fremdling vor Jehovah sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'Ein Gesetz und ein Recht soll für euch und den Fremdling sein, der unter euch sich aufhält.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Rede zu den Söhnen Israels und sprich zu ihnen: Wenn ihr in das Land kommt, in das Ich euch hineinbringen werde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'Und es geschehe, daß ihr esset von dem Brot des Landes, sollt ihr Jehovah ein Hebeopfer heben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'Als Erstling eures Teiges sollt ihr einen Kuchen als Hebeopfer heben, wie die Hebe der Tenne, so sollt ihr es heben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Von den Erstlingen eures Teiges sollt ihr Jehovah ein Hebeopfer geben in euren Geschlechtern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'Und wenn ihr euch versehet und nicht alle diese Gebote tut, die Jehovah zu Mose geredet hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'Alles, was Jehovah euch durch Mose geboten hat, von dem Tage an, da Jehovah es geboten, und weiterhin in euren Geschlechtern;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'So geschehe also: Ist es unbeachtet von den Augen der Gemeinde aus Versehen getan worden, so bereite die ganze Gemeinde einen Farren, ein Junges von den Rindern als Brandopfer zum Geruch der Ruhe für Jehovah, und sein Speiseopfer und sein Trankopfer nach dem Rechte, und einen Ziegenbock als Sündopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'Und der Priester sühne für die ganze Gemeinde der Söhne Israels, auf daß es ihnen vergeben werde; denn ein Versehen war es, und sie haben ihre Opfergabe dem Jehovah, ein Feueropfer, und ihr Sündopfer vor Jehovah gebracht für ihr Versehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'Und es wird der ganzen Gemeinde der Söhne Israels und dem Fremdling, der in ihrer Mitte sich aufhält, vergeben; denn es war beim ganzen Volk ein Versehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Versündigt sich aber eine Seele aus Versehen, so bringe er eine einjährige Ziege dar als Sündopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'Und der Priester sühne für die Seele, die sich versehen hat, durch Versündigung aus Versehen vor Jehovah, damit er ihn sühne und ihm vergeben werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'Der Eingeborene unter den Söhnen Israels und der Fremdling, der in ihrer Mitte sich aufhält, ihr sollet ein Gesetz haben für den, der aus Versehen etwas tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Und die Seele von den Eingeborenen und von den Fremdlingen, die mit erhöhter Hand etwas tut, die verhöhnt Jehovah. Und diese Seele soll von mitten seines Volkes ausgerottet werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Denn sie hat Jehovahs Wort verachtet und Sein Gebot zunichte gemacht. Diese Seele soll ausgerottet werden; ihre Missetat sei auf ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'Und die Söhne Israels waren in der Wüste, und sie fanden einen Mann, der am Sabbathtage Holz zusammenlas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'Und die, so ihn beim Zusammenlesen des Holzes gefunden hatten, brachten ihn herbei zu Mose und zu Aharon und zu der ganzen Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'Und sie legten ihn in Gewahrsam nieder, da noch nicht beschieden war, was ihm getan werden sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Und Jehovah sprach zu Mose: Der Mann soll des Todes sterben! Die ganze Gemeinde soll ihn mit Steinen steinigen außerhalb des Lagers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Und die ganze Gemeinde brachte ihn hinaus zum Lager, und sie steinigten ihn mit Steinen, und er starb, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'Und Jehovah sprach zu Mose und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Rede zu den Söhnen Israels und sprich zu ihnen: und sie sollen sich Quasten an die Fittiche ihrer Kleider machen in ihren Geschlechtern, und an die Quaste des Fittichs eine purpurblaue Schnur setzen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'Und dies soll euch eine Quaste sein, und bei ihrem Ansehen sollt ihr gedenken an alle die Gebote Jehovahs, daß ihr sie tuet, und ihr nicht euren Herzen und euren Augen nachspähet, denen ihr nachbuhlet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'Auf daß ihr gedenket und tuet alle Meine Gebote und heilig seid eurem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Ich, Jehovah, bin euer Gott, Der euch aus dem Lande Ägypten herausbrachte, daß Ich euer Gott wäre, Ich, Jehovah, euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Und es unternahm sich Korach, der Sohn Jizhars, des Sohnes Kohaths, des Sohnes Levis, und Dathan und Abiram, Söhne Eliabs, und On, Peleths Sohn, Rubens Söhne,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'Und sie standen auf vor Mose und zweihundertfünfzig Männer aus den Söhnen Israels, Fürsten der Gemeinde, Berufene der Versammlung, Männer von Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'Und sie versammelten sich gegen Mose und gegen Aharon und sprachen zu ihnen: Zu viel wollet ihr für euch! Denn die ganze Gemeinde, alle in ihr sind heilig, und Jehovah ist in ihrer Mitte. Und warum erhebt ihr euch über die Versammlung Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'Und Mose hörte es und fiel auf sein Angesicht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'Und redete zu Korach und zu seiner ganzen Gemeinde und sprach: Am Morgen, da wird Jehovah wissen lassen, wer Sein und wer heilig ist, daß Er ihn Sich nahen läßt; und wen Er erwählt, den wird Er Sich nahen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Tut so: Nehmet euch Rauchpfannen, Korach und seine ganze Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'Und tut Feuer darein und legt Räuchwerk darauf vor Jehovah, morgen. Und es soll sein, der Mann, den Jehovah erwählen wird, der soll heilig sein. Ihr wollt zu viel, Söhne Levis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'Und Mose sprach zu Korach: Höret doch, ihr Söhne Levis!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Ist es euch zu wenig, daß der Gott Israels aus der Gemeinde Israels euch ausgeschieden hat, daß Er euch Ihm nahen läßt, daß ihr dienet den Dienst an der Wohnung Jehovahs, und vor der Gemeinde stehet Dienst zu tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Und Er hat dich und all deine Brüder, die Söhne Levis, mit dir Sich nahen lassen, und nun trachtet ihr auch nach dem Priestertum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Fürwahr, du und all deine Gemeinde, ihr tut euch wider Jehovah zusammen; denn was ist Aharon, daß ihr wider ihn murret?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'Und Mose sandte hin, Dathan und Abiram, die Söhne Eliabs, zu rufen; sie sagten aber: Wir gehen nicht hinauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Ist es noch zu wenig, daß du uns aus einem Lande heraufgeführt, das von Milch und Honig fließt, um uns in der Wüste zu töten, und willst auch noch als Oberster über uns schalten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Ja, auch nicht in ein Land, das von Milch und Honig fließt, hast du uns hineingebracht, daß du uns ein Erbe an Feld und Weinberg gäbest. Willst du diesen Leuten die Augen ausstechen? Wir kommen nicht hinauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Und Mose entbrannte sehr und er sprach zu Jehovah: Wende Dich nicht zu ihrem Opfer. Nicht einen Esel habe ich von ihnen genommen, und keinem von ihnen etwas Böses getan!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Und zu Korach sprach Mose: Du und deine ganze Gemeinde seid vor Jehovah, du und sie und Aharon, morgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'Und jeder Mann nehme seine Rauchpfanne und tue Räuchwerk darauf, und bringet vor Jehovah dar, jeder Mann seine Rauchpfanne, zweihundertfünfzig Rauchpfannen, und du und Aharon, jeder Mann seine Rauchpfanne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Und ein jeder Mann nahm seine Rauchpfanne und tat Feuer darauf und legten Räuchwerk darauf, und sie standen am Eingang des Versammlungszeltes, und auch Mose und Aharon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'Und Korach hatte die ganze Gemeinde an den Eingang des Versammlungszeltes wider sie versammelt. Und es erschien die Herrlichkeit Jehovahs der ganzen Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Und Jehovah redete zu Mose und zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Scheidet euch aus von der Mitte dieser Gemeinde, auf daß Ich sie im Augenblick wegtilge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Sie aber fielen auf ihr Angesicht und sprachen: Gott, Der Du bist der Gott der Geister alles Fleisches. Ein Mann hat gesündigt und bist Du entrüstet über die ganze Gemeinde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Rede zu der Gemeinde und sprich: Gehet hinauf von der Wohnung Korachs, Dathans und Abirams ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'Und Mose machte sich auf und ging zu Dathan und Abiram, und hinter ihm gingen die Ältesten Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'Und er redete zu der Gemeinde und sprach: Weichet doch von den Zelten dieser ungerechten Männer und rühret nichts an von allem, das sie haben, auf daß ihr nicht in all ihren Sünden weggerafft werdet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'Und sie gingen weg ringsum hinauf von der Wohnung Korachs, Dathans und Abirams. Dathan und Abiram aber kamen heraus, stellten sich an den Eingang ihrer Zelte mit ihren Weibern, ihren Söhnen und ihren Kindlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'Und Mose sprach: Daran sollt ihr wissen, daß Jehovah mich gesandt hat, alle diese Taten zu tun, und sie nicht aus meinem Herzen sind;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Wenn diese sterben, wie alle Menschen sterben, und sie heimgesucht werden, wie alle Menschen heimgesucht werden, so hat Jehovah mich nicht gesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Schafft aber Jehovah etwas und sperrt der Boden seinen Mund auf und verschlingt sie und alles, das sie haben, und gehen sie lebendig zur Hölle hinab, so wisset, daß diese Männer Jehovah gelästert haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'Und als er zu Ende war mit dem Reden all dieser Worte, da spaltete sich der Boden unter ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'Und die Erde öffnete ihren Mund und verschlang sie und ihre Häuser, und alle Menschen, die zu Korach gehörten, und all ihre Habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Und sie gingen zur Hölle hinab, lebendig sie und alles, was sie hatten, und die Erde bedeckte sie, und sie waren zerstört aus der Mitte der Versammlung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'Und ganz Israel, das rings um sie war, floh auf ihre Stimme; denn sie sprachen: Daß die Erde uns nicht verschlinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Und Feuer ging aus von Jehovah und fraß auf die zweihundertfünfzig Männer, die das Räuchwerk dargebracht hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Sage dem Eleasar, dem Sohne Aharons, des Priesters, er solle die Rauchpfannen aus dem Brande emporheben, und das Feuer fernhin zersprengen, denn sie sind heilig,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Die Rauchpfannen dieser Sünder gegen ihre Seele; und ihr sollt sie zu breitem Blech schlagen, als Überzug über den Altar; denn sie brachten sie dar vor Jehovah; und sie sind darum geheiligt, und sollen zum Zeichen sein für die Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'Und Eleasar, der Priester, nahm die ehernen Rauchpfannen, welche die Verbrannten dargebracht hatten, und sie schlugen sie breit zu einem Überzug für den Altar;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'Zum Andenken für die Söhne Israels, damit kein fremder Mann sich nahe, der nicht vom Samen Aharons ist, um Räuchwerk vor Jehovah zu räuchern, auf daß ihm nicht wie Korach und seiner Gemeinde geschehe; wie Jehovah durch die Hand Moses zu ihm geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'Und am morgenden Tag murrte die ganze Gemeinde der Söhne Israels gegen Mose und gegen Aharon und sagte: Ihr habt das Volk Jehovahs getötet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Und es geschah, da die Gemeinde sich wider Mose und wider Aharon versammelte, und sie sich zum Versammlungszelte wandten, siehe, da bedeckte die Wolke dasselbe und die Herrlichkeit Jehovahs erschien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'Und Mose und Aharon kamen vor das Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Hebet euch weg aus der Mitte dieser Gemeinde! Und Ich werde sie wie im Augenblick verzehren. Und sie fielen auf ihr Angesicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Und Mose sprach zu Aharon: Nimm die Rauchpfanne und tue Feuer vom Altar darauf, und lege Räuchwerk darauf, und gehe eilig zu der Gemeinde und sühne sie; denn Entrüstung ist vom Angesichte Jehovahs ausgegangen, die Plage hat angefangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'Und Aharon nahm sie, wie Mose zu ihm geredet hatte, und lief mitten in die Versammlung, und siehe, die Plage hatte im Volke angefangen, und er tat das Räuchwerk darauf und sühnte das Volk;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Und stand zwischen die Toten und zwischen die Lebendigen, und der Plage ward Einhalt getan. Und der Toten in der Plage waren vierzehntausendsiebenhundert, außer den Toten wegen der Sache Korachs. Und Aharon kehrte zu Mose zurück an den Eingang des Versammlungszeltes, und der Plage war Einhalt getan. Und Jehovah redete zu Mose und sprach: Rede zu den Söhnen Israels und nimm von ihnen je einen Stab für ein Vaterhaus von allen ihren Fürsten, nach dem Hause ihrer Väter, zwölf Stäbe. Jedes Mannes Namen sollst du auf seinen Stab schreiben. Und Aharons Namen sollst du auf den Stab Levis schreiben; denn ein Stab sei für das Haupt des Hauses ihrer Väter. Und lege sie nieder im Versammlungszelt vor dem Zeugnis, wo Ich Mich bei euch einstelle. Und es wird geschehen, daß der Stab des Mannes, den Ich erwähle, sprossen wird, und so werde Ich das Murren der Söhne Israels gegen Mich, das sie wider euch murren, sich legen lassen. Und Mose redete zu den Söhnen Israels, und es gaben ihm alle ihre Fürsten je einen Stab auf einen Fürsten nach dem Hause ihrer Väter, zwölf Stäbe, und inmitten ihrer Stäbe war Aharons Stab. Und Mose legte die Stäbe vor Jehovah im Versammlungszelt nieder. Und es geschah, als Mose am morgenden Tag in das Zelt des Zeugnisses hineinkam, siehe, da hatte der Stab Aharons vom Hause Levi gesproßt und Knospen hervorgebracht, daß Blüten daran blühten, und Mandeln reiften. Und Mose brachte alle Stäbe vom Angesicht Jehovahs heraus vor alle Söhne Israels, und sie sahen sie, und jeder Mann nahm seinen Stab. Und Jehovah sprach zu Mose: Bringe den Stab Aharons zurück vor das Zeugnis zur Aufbewahrung als Zeichen für die Sühne der Widerspenstigkeit, daß ihr Murren von Mir alle werde und sie nicht sterben. Und Mose tat, wie Jehovah ihm geboten hatte. Also tat er. Und die Söhne Israels sprachen zu Mose und sagten: Siehe, wir verscheiden, wir sind verloren, wir alle sind verloren! Jeder, der sich nahet, der sich naht der Wohnung Jehovahs, stirbt. Sollen wir alle umkommen, daß wir verscheiden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'Und Jehovah sprach zu Aharon: Du und deine Söhne und das Haus deines Vaters mit dir, ihr sollt die Missetat des Heiligtums tragen; und du und deine Söhne mit dir, ihr sollt die Missetat eures Priestertums tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Aber auch deine Brüder, den Stamm Levi, den Stamm deines Vaters sollst du mit dir lassen nahen, daß sie dir anhangen und dir Dienste tun; du aber und deine Söhne mit dir, ihr sollt vor dem Zelte des Zeugnisses sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'Und sie sollen deine Hut und die Hut des ganzen Zeltes halten. Nur den Geräten des Heiligtums und dem Altar sollen sie nicht nahen, auf daß nicht beide, sie und ihr, sterbet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Und sie sollen dir anhangen und die Hut des Versammlungszeltes halten, den ganzen Dienst am Zelte, und ein Fremder soll euch nicht nahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Und ihr haltet die Hut des Heiligtums und die Hut des Altars, daß keine Entrüstung mehr über die Söhne Israels sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Und siehe, Ich habe eure Brüder, die Leviten, aus der Mitte der Söhne Israels genommen, für euch als Gabe sind sie Jehovah gegeben, zu dienen den Dienst des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Und du und deine Söhne mit dir, ihr sollt euer Priestertum hüten, und jedes Ding, das am Altar und innerhalb des Vorhangs ist, und ihr sollet dienen. Den Dienst eures Priestertums gebe Ich euch als Gabe. Und der Fremde, der sich naht, soll des Todes sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'Und Jehovah redete zu Aharon: Und Ich, siehe, Ich habe dir die Hut Meiner Hebeopfer gegeben; von allem, was die Söhne Israels geheiligt, gab Ich sie dir für die Salbung; und deinen Söhnen zu ewiger Satzung gab Ich sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'Dies sei dein vom Hochheiligen, vom Feuer! All ihre Opfergabe, all ihr Speiseopfer und all ihr Sündopfer und all ihr Schuldopfer, das sie Mir zurückgeben, als Allerheiligstes, sei es dein und deiner Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Im Allerheiligsten sollst du es essen. Alles, was männlich ist, soll es essen. Heilig sei es dir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'Und dies sei dein: die Hebe ihrer Gabe in allen Webeopfern der Söhne Israels gebe Ich dir und deinen Söhnen und deinen Töchtern mit dir zu ewiger Satzung. Alles Reine in deinem Hause soll es essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Alles Beste vom Öl und all das Beste vom Most und Korn, ihre Erstlinge, die sie Jehovah geben, sie gebe Ich dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Die Erstlinge von allem, das in ihrem Lande ist, das sie Jehovah hereinbringen, sollen dein sein. Alles Reine in deinem Haus soll es essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Alles Gebannte in Israel soll dein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Alles, was die Mutter bricht von allem Fleisch, das sie Jehovah darbringen, vom Menschen oder vom Vieh, soll dein sein. Nur sollst du die Erstgeburt vom Menschen einlösen lassen, und auch die Erstgeburt von unreinem Vieh muß du einlösen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Und was die Einlösung anlangt, sollst du einlösen, was einen Monat alt ist, nach deiner Schätzung fünf Schekel Silber, nach dem Schekel des Heiligtums, zwanzig Gerah hat er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Das Erstgeborene vom Rind, oder das Erstgeborene vom Schaf oder das Erstgeborene der Ziege sollst du nicht einlösen. Heilig sind sie. Ihr Blut sollst du sprengen auf den Altar, und ihr Fett als Feueropfer anzünden, als Geruch der Ruhe dem Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Ihr Fleisch aber sei dein, wie die Webebrust und die rechte Schulter soll es dein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Alle heiligen Heben, welche die Söhne Israels für Jehovah heben, gebe Ich dir und deinen Söhnen und deinen Töchtern mit dir zu ewiger Satzung. Ein ewiger Salzbund sei es vor Jehovah dir und deinem Samen mit dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Und Jehovah sprach zu Aharon: In ihrem Lande sollst du nicht erben, und kein Teil in ihrer Mitte soll dein sein. Ich bin dein Teil und dein Erbe inmitten der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Und siehe, den Söhnen Levis gebe Ich all den Zehnten in Israel zum Erbe wegen ihres Dienstes, den sie dienen, den Dienst in den Versammlungszelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Und die Söhne Israels sollen nicht fürder dem Versammlungszelte nahen, so daß sie eine Sünde tragen, daß sie sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'Und der Levite soll den Dienst des Versammlungszeltes dienen, und sie sollen ihre Missetat tragen. Ewige Satzung sei es für eure Geschlechter; und inmitten der Söhne Israels sollen sie kein Erbe erben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'Denn den Zehnten von den Söhnen Israels, den sie Jehovah als Hebeopfer heben, gebe Ich den Leviten als Erbe. Darum sagte Ich ihnen, sie sollen inmitten der Söhne Israels kein Erbe erben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Und zu den Leviten sollst du reden und ihnen sagen: Wenn ihr von den Söhnen Israels den Zehnten nehmet, den Ich euch von ihnen als euer Erbe gegeben habe, so sollt ihr davon heben den Zehnten von dem Zehnten Jehovah als Hebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'Und es soll euch als euer Hebeopfer gerechnet werden, wie Korn von der Tenne und wie die Fülle von der Weinkufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'So sollt auch ihr von allen euren Zehnten, die ihr von den Söhnen Israels nehmet, Jehovah ein Hebeopfer heben, und davon die Hebe Jehovahs Aharon dem Priester geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Von allen euren Gaben sollt ihr alle Hebe dem Jehovah heben, von all seinem Besten sein Heiliges davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Und sage ihnen: Hebt ihr das Beste davon, so wird es den Leviten gerechnet wie der Ertrag der Tenne und wie der Ertrag der Weinkufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'Und ihr dürfet es aller Orten essen, ihr und euer Haus; denn es ist euer Lohn wegen eures Dienstes in dem Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Und ihr werdet keine Sünde deswegen tragen, wenn ihr sein Bestes davon hebet. Und das von den Söhnen Israels Geheiligte sollt ihr nicht entweihen, auf daß ihr nicht sterbet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'Und Jehovah redete zu Mose und zu Aharon und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'Dies ist die Satzung des Gesetzes, die Jehovah geboten hat und gesagt: Rede zu den Söhnen Israels, sie sollen dir eine rote Färse ohne Fehl, an der kein Makel ist, auf die noch kein Joch gekommen, nehmen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'Und sie dem Priester Eleasar geben; und er bringe sie hinaus außerhalb des Lagers und lasse sie vor ihm schlachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Und der Priester Eleasar nehme von ihrem Blut mit seinem Finger und spritze von ihrem Blut siebenmal gegenüber der Vorderseite des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'Und lasse die Färse vor seinen Augen verbrennen; ihre Haut und ihr Fleisch und ihr Blut samt ihrem Mist verbrenne man.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'Und der Priester nehme Zedernholz und Ysop und doppelt gefärbten Scharlach und werfe sie mitten in den Brand der Färse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'Und der Priester wasche seine Kleider und bade sein Fleisch im Wasser, und danach komme er herein in das Lager; aber der Priester ist unrein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'Und der sie verbrannt hat, soll seine Kleider im Wasser waschen, und sein Fleisch baden im Wasser und unrein sein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'Und ein reiner Mann sammle die Asche der Färse und lege sie an einen reinen Ort außerhalb des Lagers nieder; und sie bleibe in Verwahrung zum Wasser der Ausscheidung für die Gemeinde der Söhne Israels. Ein Sündopfer ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Der aber die Asche von der Färse gesammelt, wasche seine Kleider und ist unrein bis zum Abend. Und dies sei ewige Satzung für die Söhne Israels und für den Fremdling, der sich in ihrer Mitte aufhält.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Wer einen Toten, die Leiche irgendeines Menschen anrührt, soll sieben Tage unrein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Der lasse sich damit entsündigen am dritten Tage und am siebenten Tage wird er rein. Und läßt er sich nicht entsündigen am dritten und am siebenten Tag, so wird er nicht rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Wer einen Toten, die Leiche eines Menschen anrührt, der gestorben ist, und sich nicht entsündigen läßt, der verunreinigt die Wohnung Jehovahs, und diese Seele werde ausgerottet aus Israel. Weil das Wasser der Ausscheidung nicht auf ihn gesprengt worden, ist er unrein; seine Unreinheit ist noch auf ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'Dies ist das Gesetz: Wenn ein Mensch stirbt im Zelt, so ist jeder, der in das Zelt hineinkommt, und jeder, der im Zelte ist, sieben Tage unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'Und alles Gerät, das offen ist, und auf das kein Deckel gebunden ist, ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Und jeder, der auf dem Angesichte des Feldes einen vom Schwert Erschlagenen oder einen Toten oder Menschengebeine oder ein Grab anrührt, ist sieben Tage unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'Und sie sollen nehmen für den Unreinen von dem Staube des verbrannten Sündopfers und frisches Wasser in ein Gefäß schütten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'Und ein reiner Mann nehme Ysop und tauche denselben in das Wasser und spritze auf das Zelt und auf alle Gefäße und auf die Seelen, die daselbst waren, und auf den, der ein Gebein oder einen Erschlagenen oder einen Toten oder ein Grab angerührt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Und der Reine sprenge auf den Unreinen am dritten Tag und am siebenten Tag und entsündige ihn am siebenten Tag. Und er soll seine Kleider waschen und baden im Wasser, und am Abend rein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Und ein Mann, der unrein ist, und sich nicht entsündigen läßt, solche Seele soll ausgerottet werden aus der Mitte der Versammlung; denn er hat Jehovahs Heiligtum verunreinigt. Das Wasser der Ausscheidung ist nicht über ihn gesprengt worden: er ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'Und dies soll ihnen ewige Satzung sein. Und der da mit dem Ausscheidungswasser besprengt, soll seine Kleider waschen, und der das Ausscheidungswasser anrührt, sei unrein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'Und alles, was der Unreine anrührt, wird unrein, und die Seele, die ihn anrührt, wird unrein bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'Und die Söhne Israels, die ganze Gemeinde, kamen in die Wüste Zin im ersten Monate, und das Volk wohnte in Kadesch; und Mirjam starb allda und ward allda begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'Und die Gemeinde hatte kein Wasser; und sie versammelten sich wider Mose und wider Aharon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'Und das Volk haderte mit Mose und sie sprachen und sagten: Ach, hätten wir doch dürfen verscheiden bei dem Verscheiden unserer Brüder vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Und wozu habt ihr die Versammlung Jehovahs in diese Wüste hereingebracht, auf daß wir darin sterben, wir und unser Vieh?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'Und warum habt ihr uns aus Ägypten heraufgebracht, um uns an diesen schlechten Ort hereinzubringen, wo kein Ort ist zur Saat, noch Feigenbaum, noch Weinstock, noch Granatbaum, noch Wasser zum trinken ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Und Mose und Aharon gingen von der Versammlung hinein nach dem Eingang des Versammlungszeltes und fielen auf ihr Angesicht; und die Herrlichkeit Jehovahs erschien ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Nimm den Stab und versammle die Gemeinde, du und dein Bruder Aharon, und redet zu dem Felsen vor ihren Augen, daß er sein Wasser gebe. Und du sollst für sie Wasser aus dem Felsen hervorbringen und die Gemeinde und ihr Vieh tränken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Und Mose nahm den Stab vor dem Angesichte Jehovahs, wie Er ihm geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'Und Mose und Aharon ließen die Versammlung vor dem Felsen sich versammeln und er sprach zu ihnen: So höret denn, ihr Widerspenstigen! Sollen wir aus dem Felsen da für euch Wasser hervorbringen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'Und Mose hob seine Hand empor und schlug den Felsen zweimal mit seinem Stab. Und viele Wasser kamen heraus, und die Gemeinde trank und ihr Vieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'Und Jehovah sprach zu Mose und zu Aharon: Darum, daß ihr nicht an Mich geglaubt habt, daß ihr Mich heiligtet vor den Augen der Söhne Israels, deshalb sollt ihr diese Versammlung nicht zum Land hineinbringen, das Ich ihnen gegeben habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'Dies sind die Wasser des Haders, den die Söhne Israels haderten mit Jehovah und Er heiligte Sich unter ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'Und Mose sandte von Kadesch Boten an den König von Edom: So spricht dein Bruder Israel: Du weißt all das Mühsal, das uns getroffen hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'Und unsre Väter gingen hinab nach Ägypten und wir wohnten viele Tage in Ägypten, und die Ägypter taten übel an uns und an unseren Vätern;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'Und wir schrien zu Jehovah, und Er hörte unsere Stimme und sandte einen Engel und brachte uns aus Ägypten heraus, und siehe, wir sind in Kadesch, einer Stadt am Ende deiner Grenze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Laß uns durch dein Land durchziehen. Wir wollen nicht durch Feld und durch Weinberg gehen, und nicht Wasser aus den Brunnen trinken, sondern auf dem Wege des Königs gehen, nicht rechts oder links ablenken, bis wir deine Grenze durchzogen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Edom aber sprach zu ihm: Du sollst nicht durch mich hindurchziehen, sonst gehe ich mit dem Schwerte aus dir entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'Und die Söhne Israels sprachen zu ihm: Auf der Landstraße wollen wir hinaufziehen, und wenn wir von deinem Wasser trinken, ich und meine Viehherden, so will ich dir den Preis dafür geben. Das ist nichts nur zu Fuß will ich durchziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'Er aber sprach: Du sollst nicht durchziehen; und Edom ging aus mit schwerem Volk und starker Hand ihm entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Und Edom weigerte sich, Israel zu gewähren durch seine Grenzen durchzuziehen, und Israel lenkte von ihm ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Und sie brachen auf von Kadesch, und die Söhne Israels, die ganze Gemeinde, kamen nach dem Berge Hor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'Und Jehovah sprach zu Mose und zu Aharon an dem Berge Hor, an der Grenze des Landes Edom, und er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Aharon soll versammelt werden zu seinem Volke; denn er soll nicht in das Land hineinkommen, das Ich den Söhnen Israels gegeben habe, darum, daß ihr an dem Haderwasser gegen Meinen Befehl widerspenstig waret.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Nimm Aharon und Eleasar, seinen Sohn, und laß sie hinaufgehen auf den Berg Hor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'Und laß Aharon seine Kleider ausziehen und ziehe sie Eleasar, seinem Sohne an, und Aharon soll gesammelt werden und sterben allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Und Mose tat, wie Jehovah geboten hatte, und sie stiegen hinauf auf den Berg Hor vor den Augen der ganzen Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'Und Mose zog dem Aharon seine Kleider aus und zog sie Eleasar, seinem Sohne, an; und Aharon starb daselbst auf der Spitze des Berges; und Mose und Eleasar kamen vom Berge herab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'Und die ganze Gemeinde sah, daß Aharon verschieden, und sie beweinten den Aharon dreißig Tage, das ganze Haus Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'Und der Kanaaniter, König von Arad, der gegen Mittag wohnte, hörte, daß Israel auf dem Wege der Kundschafter hereinkomme, und er stritt wider Israel und nahm etliche von ihm gefangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Und Israel gelobte ein Gelübde dem Jehovah und sprach: Wenn Du dies Volk in meine Hand gibst, so will ich seine Städte bannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'Und Jehovah hörte auf die Stimme Israels und gab ihm den Kanaaniter, und er bannte sie und ihre Städte und nannte den Namen des Ortes Chormah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'Und vom Berge Hor brachen sie auf auf dem Wege nach dem Suph-Meer, um das Land Edoms zu umziehen, und die Seele des Volkes ward ungeduldig auf dem Wege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'Und das Volk redete wider Gott und wider Mose: Warum habt ihr uns aus Ägypten heraufgebracht, daß wir in der Wüste sterben? Wir haben kein Brot und kein Wasser, und unsere Seele hat Überdruß an dem leichten Brot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Und Jehovah sandte gegen das Volk die feurigen Schlangen und sie bissen das Volk, und viel Volks von Israel starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'Und das Volk kam zu Mose und sie sprachen: Wir haben gesündigt, daß wir wider Jehovah und wider dich geredet haben. Bete zu Jehovah, daß Er die Schlange von uns wegnehme. Und Mose betete für das Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'Und Jehovah sprach zu Mose: Mache dir eine Feuerschlange und setze sie auf ein Panier. Und es soll geschehen, daß jeder, der gebissen wird, und sieht sie an, der soll leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Und Mose machte eine eherne Schlange und setzte sie auf ein Panier, und es geschah, daß, wenn die Schlange einen Mann biß, und er auf die eherne Schlange blickte, er am Leben blieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'Und die Söhne Israels brachen auf und lagerten in Oboth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'Und von Oboth brachen sie auf und lagerten in Ijje Abarim in der Wüste, die vor Moab gegen Aufgang der Sonne ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Von da brachen sie auf und lagerten im Bachtal Sared.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Von hier brachen sie auf und lagerten am Übergang des Arnon, der in der Wüste ist und aus der Grenze des Amoriters herauskommt; denn der Arnon ist die Grenze von Moab, ist zwischen Moab und zwischen dem Amoriter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Darum sagt man im Buche der Kriege Jehovahs: Baheb in Suphah und die Bäche, der Arnon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'Und der Ausfluß der Bäche, der sich lenket dahin, wo man wohnt in Ar und sich lehnt an die Grenze von Moab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'Und von da nach Beer; dies das Beer, von dem Jehovah zu Mose sagte: Versammle das Volk, und Ich will ihnen Wasser geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Damals sang Israel diesen Gesang: Steig auf, du Brunnen, antwortet über ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Den Brunnen, den gruben die Obersten, ihn höhlten des Volkes Edle aus durch den Gesetzgeber, mit ihren Stäben. - Und aus der Wüste nach Matthanah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'Und von Matthanah gen Nachaliel, und von Nachaliel nach Bamoth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'Und von Bamoth nach dem Tal, das im Gefilde von Moab ist, nach der Spitze des Pisgah hin und hinausschaut über die Angesichte des Wüstenlandes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'Und Israel sandte Boten zu Sichon, den König der Amoriter und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Laß mich durch dein Land durchziehen. Wir wollen nicht in Feld, noch in Weinberg ablenken, wollen nicht trinken das Wasser des Brunnens, sondern auf dem Königswege durchgehen, bis wir durch deine Grenze durchgezogen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Sichon aber gab nicht zu, daß Israel durch seine Grenze durchzöge; und Sichon sammelte all sein Volk und er ging aus, Israel entgegen nach der Wüste und kam bis Jahza, und stritt wider Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'Israel aber schlug ihn mit der Schärfe des Schwertes und nahm sein Land ein vom Arnon bis an den Jabbok bis zu den Söhnen Ammons; denn stark war die Grenze der Söhne Ammons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'Und Israel nahm alle diese Städte, und Israel wohnte in allen Städten des Amoriters, in Cheschbon und allen ihren Töchtern,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Denn Cheschbon war die Stadt Sichons, des Amoriterkönigs; und dieser hatte gestritten gegen den früheren König Moabs und ihm all sein Land bis zum Arnon aus seiner Hand genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Darum sagen die Verkünder der Aussprüche: Kommet hinein nach Cheschbon! Aufgebauet und befestigt werde Sichons Stadt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Denn ein Feuer ging aus von Cheschbon, eine Flamme aus Sichons Stadt, sie fraß Ar Moab und die Bürger von Arnons Opferhöhen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Wehe dir, Moab! Verloren bist du, Kamos Volk. Er gab seine Söhne, die Entkommenen, und seine Töchter in Gefangenschaft Sichon, dem Amoriterkönig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Und wir schossen sie nieder. Cheschbon ist verloren bis Dibon. Wir verwüsteten sie bis Nophach, das bis Medebah reicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Und Israel wohnte im Land der Amoriter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'Und Mose sandte nach Jaeser, es auszukundschaften, und sie eroberten dessen Töchter und trieben aus den Amoriter, der darin war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Und sie wandten sich und zogen den Weg nach Baschan hinauf; und Og, der König von Baschan, ging aus, er und all sein Volk ihnen entgegen zum Streite nach Edrei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'Und Jehovah sprach zu Mose: Fürchte dich nicht vor ihm; denn Ich habe ihn in deine Hand gegeben und all sein Volk und sein Land, und du sollst ihm tun, wie du Sichon, dem Amoriterkönige, getan, der in Cheschbon wohnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Und sie schlugen ihn und seine Söhne und all sein Volk, bis ihm kein Rest blieb, und nahmen sein Land ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'Und die Söhne Israels brachen auf und lagerten in dem Flachlande Moabs am Übergang über den Jordan bei Jericho.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'Und Balak, Zippors Sohn, sah alles, was Israel dem Amoriter getan;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'Und Moab war sehr bange vor dem Volke, weil ihrer viel war; und Moab hatte Überdruß an den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'Und Moab sprach zu den Ältesten Midjans: Diese Versammlung wird alles um uns her auflecken, wie der Ochse das Grüne auf dem Felde aufleckt. Und zur selben Zeit war Balak, Zippors Sohn, König über Moab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Und er sandte Boten zu Bileam, Beors Sohn, nach Pethor am Flusse, in das Land der Söhne seines Volkes, ihn zu rufen; und er sprach: Siehe, ein Volk ist aus Ägypten ausgegangen, siehe, es bedeckt die Fläche der Erde, und wohnt mir gegenüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Und nun komm doch, verfluche mir dies Volk, denn es ist mächtiger denn ich. Vielleicht vermag ich es, daß wir es schlagen und ich es von dem Land vertreibe; denn ich weiß, wen du segnest, der ist gesegnet, und wen du verfluchst, der ist verflucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Und die Ältesten Moabs und die Ältesten Midjans gingen hin mit Wahrsagegaben in ihren Händen, und kamen hinein zu Bileam und redeten die Worte Balaks zu ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'Und er sprach zu ihnen: Übernachtet hier diese Nacht, so will ich euch ein Wort erwidern, wie Jehovah zu mir reden wird. Und die Obersten Moabs blieben bei Bileam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Und Gott kam zu Bileam und sprach: Wer sind die Männer da bei dir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'Und Bileam sprach zu Gott: Balak, Zippors Sohn, König von Moab, hat zu mir gesandt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Siehe, das Volk, das aus Ägypten ausgegangen, bedeckt die Fläche der Erde. So komm nun, und verwünsche es mir, auf daß ich vielleicht vermöge, wider dasselbe zu streiten und es zu vertreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Und Gott sprach zu Bileam: Gehe nicht mit ihnen, verfluche das Volk nicht, denn es ist gesegnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'Und Bileam stand am Morgen auf und sprach zu den Obersten Balaks: Gehet nach eurem Land, denn Jehovah weigert Sich zuzugeben, daß ich mit euch gehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Und die Obersten Moabs machten sich auf und kamen zu Balak und sprach: Bileam weigert sich, mit uns zu gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Und Balak sandte abermals noch mehr und gewichtigere Obersten denn diese waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Und sie kamen zu Bileam und sprachen zu ihm: So sprach Balak, Zippors Sohn: Laß dich nicht abhalten, zu mir zu kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Denn ich will dich sehr verherrlichen und alles tun, was du zu mir sagst; aber gehe doch, verwünsche mir dieses Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Und Bileam antwortete und sprach zu Balaks Knechten: Wenn Balak mir auch sein Haus voll Silber und Goldes gäbe, so vermöchte ich den Befehl Jehovahs, meines Gottes, nicht zu überschreiten, Kleines oder Großes zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Und nun bleibet doch auch ihr diese Nacht hier, und ich werde wissen, was Jehovah weiter zu mir redet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'Und Gott kam zu Bileam in der Nacht und sprach zu ihm: Wenn diese Männer gekommen sind, dich zu rufen, so mache dich auf, gehe mit ihnen! Aber nur das Wort, das Ich zu dir reden werde, sollst du tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Und Bileam machte sich am Morgen auf und sattelte seine Eselin und ging mit den Obersten Moabs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'Und der Zorn Gottes entbrannte, daß er ging; und der Engel Jehovahs stellte sich ihm zum Widersacher in den Weg, und er ritt auf seiner Eselin, und zwei seiner Jungen waren bei ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'Und die Eselin sah den Engel Jehovahs, Der sich in den Weg gestellt, und Sein gezücktes Schwert in Seiner Hand; und die Eselin lenkte ab von dem Wege und ging in das Feld. Und Bileam schlug die Eselin, um sie in den Weg zu lenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'Und der Engel Jehovahs stand in dem Fußweg im Weinberg, da hier eine Mauerwand und dort eine Mauerwand war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Und die Eselin sah den Engel Jehovahs und drückte sich an die Wandung, und drückte Bileams Fuß gegen die Wandung; und er schlug sie abermals.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'Und der Engel Jehovahs zog wiederum hin und stand an einem engen Orte, da kein Weg zum Ablenken zur Rechten oder zur Linken war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Und die Eselin sah den Engel Jehovahs und legte sich nieder unter Bileam; und es entbrannte der Zorn Bileams und er schlug die Eselin mit dem Stock,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Und Jehovah öffnete der Eselin den Mund und sie sprach zu Bileam: Was habe ich dir getan, daß du mich diese dreimal geschlagen hast?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Und Bileam sprach zu der Eselin: Weil du mir es so getrieben hast. Wäre doch ein Schwert in meiner Hand, ich würde dich jetzt erwürgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'Und die Eselin sprach zu Bileam: Bin ich nicht deine Eselin, auf der du geritten bist, seit ich dein bin, bis auf diesen Tag. War ich je gewohnt, dir so zu tun? Und er sprach: Nein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Und Jehovah deckte Bileam die Augen auf und er sah den Engel Jehovahs mit Seinem gezückten Schwert in Seiner Hand, Der Sich in den Weg gestellt. Und er neigte sich und verbeugte sich auf sein Antlitz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'Und der Engel Jehovahs sprach zu ihm: Warum hast du deine Eselin diese dreimal geschlagen? Siehe, Ich bin ausgegangen als dein Widersacher, denn verkehrt ist der Weg vor Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'Und die Eselin hat Mich gesehen und hat diese dreimal vor Mir abgelenkt. Hätte sie vor Mir nicht abgelenkt, so hätte Ich dich auch jetzt erwürgt, sie aber leben lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'Und Bileam sprach zum Engel Jehovahs: Ich habe gesündigt, daß ich nicht wußte, daß Du Dich mir im Wege entgegenstelltest. Und nun, wenn es böse in Deinen Augen ist, will ich für mich zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Und der Engel Jehovahs sprach zu Bileam: Gehe mit den Männern, jedoch das Wort, welches Ich zu dir reden werde, das rede. Und Bileam ging mit Balaks Obersten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'Und Balak hörte, daß Bileam komme und er ging aus ihm entgegen bis Ir Moab, das an der Grenze Arnons, der am Ende der Grenze ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'Und Balak sprach zu Bileam: Habe ich nicht zu dir gesandt, dich zu rufen? Warum bist du nicht zu mir gekommen? Vermag ich fürwahr nicht dich zu verherrlichen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Und Bileam sprach zu Balak: Siehe, ich bin zu dir gekommen, aber vermag ich jetzt irgend etwas zu reden? Das Wort, das Gott mir in den Mund legt, das muß ich reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'Und Bileam ging mit Balak, und sie kamen gen Kirjath Chuzoth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Und Balak opferte Rind und Kleinvieh und sandte nach Bileam und den Obersten, die mit ihm waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'Und am Morgen geschah es, daß Balak den Bileam nahm und ihn auf Bamoth-Baal hinaufbrachte und von dort sah er das Ende des Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Und Bileam sprach zu Balak: Baue mir hier sieben Altäre, und richte mir sieben Farren und sieben Widder zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'Und Balak tat wie Bileam geredet; und Balak und Bileam opferten einen Farren und einen Widder auf dem Altar auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Und Bileam sprach zu Balak: Stelle dich bei deinem Brandopfer, und ich will hingehen. Vielleicht begegnet mir Jehovah; und was Er mich sehen läßt, will ich dir ansagen. Und er ging auf einen kahlen Hügel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Und Gott begegnete dem Bileam, und er sprach zu Ihm: Sieben Altäre habe ich zugerichtet und einen Farren und einen Widder auf dem Altar aufgeopfert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Und Jehovah legte dem Bileam ein Wort in den Mund und sprach: Kehre zurück zu Balak und also sollst du reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'Und er kehrte zu ihm zurück und siehe, er hatte sich zu seinem Brandopfer gestellt, er und alle Obersten Moabs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Und er hob an seinen Spruch und sprach: Von Aram her führt mich Balak, Moabs König, von den Bergen des Ostens: Komm und verfluche mir Jakob, und komm und ergrimme über Israel!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Was soll ich verwünschen, den Gott nicht verwünscht? Und was ergrimmen, wo Jehovah nicht ergrimmt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Von der Spitze der Felsen sehe ich ihn, und von den Hügeln betrachte ich ihn. Siehe, ein Volk, das besonders wohnt und unter die Völkerschaften nicht gerechnet wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Wer berechnet den Staub Jakobs und die Zahl des vierten Teils von Israel? Möge meine Seele sterben den Tod der Redlichen, und mein Letztes sein wie das seine!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Und Balak sprach zu Bileam: Was tust du mir? Meine Feinde zu verwünschen, habe ich dich genommen, und siehe, du segnest sie!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'Und er antwortete und sprach: Muß ich nicht das, was mir Jehovah in den Mund legt, halten, es zu reden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Und Balak sprach zu ihm: Komm doch mit mir an einen andern Ort, von wo aus du es sehen wirst. Aber nur sein Ende wirst du sehen, und wirst nicht alles von ihm sehen, und von da sollst du ihn verwünschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'Und er nahm ihn auf das Feld Zophim, auf das Haupt des Pisgah und baute sieben Altäre und opferte einen Farren und einen Widder auf dem Altar auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'Und er sprach zu Balak: Stelle dich hier bei deinem Brandopfer und ich will dort entgegengehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'Und Jehovah begegnete Bileam und legte ein Wort in seinen Mund und sprach: Kehre zurück zu Balak, und also sollst du reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'Und er kam zu ihm und siehe, er hatte sich bei seinem Brandopfer gestellt und mit ihm Moabs Obersten. Und Balak sprach zu ihm: Was hat Jehovah geredet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'Und er hob seinen Spruch an und sprach: Stehe auf, Balak, und höre, Sohn Zippors nimm es zu Ohren!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Nicht ist Gott ein Mann, daß Er Falsches rede, noch eines Menschen Sohn, daß Ihn reuete. Sollte Er es sprechen und nicht tun? und reden und es nicht zustande bringen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Siehe, Segen habe ich empfangen. Er hat gesegnet und ich kann es nicht zurücknehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Unrecht erblickt Er in Jakob nicht, und Mühsal sieht Er nicht in Israel. Jehovah, sein Gott, ist mit ihm, und der Jubelruf des Königs ist bei ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Gott hat sie aus Ägypten herausgebracht und Er hat die Festigkeit des Einhorns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Keine Beschwörung gibt es gegen Jakob, und keinen Wahrsagespruch gegen Israel. Zu dieser Zeit wird man zu Jakob und zu Israel sagen: Was hat Gott getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Siehe da, dem alten Löwen gleich wird aufstehen das Volk, es wird sich erheben gleich dem Leuen, es wird sich nicht legen, bis es das Zerfleischte verzehrt und das Blut Erschlagener getrunken hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'Und Balak sprach zu Bileam: So sollst du es weder verwünschen, noch es segnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Bileam aber antwortete und sprach zu Balak: Habe ich zu dir nicht geredet und gesagt: Alles, was Gott reden wird, das muß ich tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'Und Balak sprach zu Bileam: Komm doch, ich will dich an einen anderen Ort nehmen. Vielleicht ist es recht vor den Augen Gottes, daß du es mir von dort verwünschest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Und Balak nahm Bileam auf das Haupt des Peor, der schaut über das Angesicht des Wüstenlandes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'Und Bileam sprach zu Balak: Baue mir hier sieben Altäre und mache mir hier sieben Farren und sieben Widder bereit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'Und Balak tat, wie Bileam sagte und opferte einen Farren und einen Widder auf dem Altare auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Und Bileam sah, daß es vor den Augen Jehovahs gut war, Israel zu segnen, und er ging nicht mehr, wie einmal und das andere Mal auf Beschwörungen aus, sondern richtete sein Angesicht der Wüste zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'Und Bileam erhob seine Augen und sah Israel, wie es nach seinen Stämmen wohnte, und der Geist Gottes war auf ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'Und Bileam hob seinen Spruch an und sprach: So spricht Bileam, der Sohn Beors, und so spricht der Mann, dem das Auge erschlossen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'So spricht, der die Reden Gottes hört, der das Gesichte Schaddais erschaut, der niederfällt, und dem die Augen sind aufge- deckt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Wie gut sind deine Zelte, Jakob! deine Wohnungen, Israel!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Wie Bachtäler sich erstrecken, wie Gärten am Flusse, wie Sandelbäume, die Jehovah gepflanzt, wie Zedern an dem Gewässer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Wasser wird ausströmen aus seinen Eimern; und seine Aussaat in vielen Wassern. Erhöhet über Agag wird sein König sein, und erhaben sein Reich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Gott hat ihn aus Ägypten ausgeführt. Mit der Festigkeit des Einhorns ist Er bei ihm. Er verzehrt die Völkerschaften, seine Dränger und ihre Gebeine zermalmt und ihre Pfeile zerschmettert Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Er kauert sich nieder und legt sich wie der Löwe und wie der alte Löwe; wer will ihn aufscheuchen? Wer dich segnet, der ist gesegnet, und wer dich verflucht, ist verflucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Und es entbrannte Balaks Zorn über Bileam, daß er die Hände zusammenschlug; und Balak sprach zu Bileam: Zu verwünschen meine Feinde hatte ich dich gerufen, und siehe, du hast sie dreimal gesegnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Und nun entweiche an deinen Ort. Ich hatte gesagt: Ich würde dich verherrlichen, und siehe, Jehovah hat dir Herrlichkeit vorenthalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Und Bileam sprach zu Balak: Redete ich nicht auch zu den Boten, die du zu mir sandtest, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Gäbe mir Balak sein Haus voll Silber und Gold, so vermöchte ich doch nicht, Jehovahs Befehl zu überschreiten, Gutes oder Böses aus meinem Herzen zu tun. Was Jehovah zu mir rede, das würde ich reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'Und nun siehe, ich gehe zu meinem Volk. Komm, ich will dich beraten, was dieses Volk in späteren Tagen deinem Volk tun wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'Und er hob an seinen Spruch und sprach: Der Spruch Bileams, des Sohnes Beors, und der Spruch des Mannes, dem das Auge erschlossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'Der Spruch dessen, der die Reden Gottes hört, und der da kennt die Kunde des Höchsten, der Schaddais Gesicht erschaut, der da niederfällt, und dem die Augen sind aufgedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Ich sehe Ihn, aber nicht jetzt, ich betrachte Ihn, aber nicht nahe. Ein Stern wird aufgehen aus Jakob, und eine Rute steht auf aus Israel und zerschmettert die Ecken Moabs und stürzet alle Söhne Scheths danieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'Und Edom wird ein Erbbesitz und Seir wird ein Erbbesitz Seiner Feinde, Israel aber übt Tapferkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'Und Er wird beherrschen den Jakob, und zerstören den Rest aus der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'Und er sah Amalek und hob seinen Spruch an und sprach: Der Völkerschaften Erstling ist Amalek: aber um kommt seine Nachkommenschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'Und er sah den Keniter, und hob seinen Spruch an und sprach: Fest ist dein Wohnsitz, und auf die Felsenklippe hast du dein Nest gesetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'Jedoch Kain wird zum Brande sein. Wie lange, so wird Assur dich gefangennehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'Und er hob an seinen Spruch und er sprach: Wehe, wer wird leben, wenn Gott es tun wird?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'Aber Schiffe kommen aus der Kittim Ufer, und sie demütigen Aschur und demütigen Eber, aber auch er muß umkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'Und Bileam machte sich auf, und ging und kehrte zurück an seinen Ort, und auch Balak ging seines Weges.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Und Israel wohnte in Schittim. Und das Volk fing an mit den Töchtern Moabs zu buhlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'Und sie riefen das Volk zu den Opfern ihrer Götter, und das Volk aß und betete ihre Götter an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'Und Israel hängte sich an den Baal Peor. Und der Zorn Jehovahs entbrannte wider Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'Und Jehovah sprach zu Mose: Nimm alle Häupter des Volkes und hänge sie auf dem Jehovah vor der Sonne, daß der brennende Zorn Jehovahs sich kehre von Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Und Mose sprach zu den Richtern Israels: Jeder Mann erwürge seine Männer, die sich an Baal Peor gehängt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'Und siehe, ein Mann von den Söhnen Israels kam und brachte die Midianitin zu seinen Brüdern herbei vor den Augen Moses und den Augen der ganzen Gemeinde der Söhne Israels, und sei weinten am Eingang des Versammlungszeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Und Pinechas, der Sohn Eleasars, des Sohnes Aharons, des Priesters, sah es, und er stand auf aus der Mitte der Gemeinde und nahm einen Speer in seine Hand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'Und er ging hinein, dem israelitischen Mann nach, in die Schlafkammer und durchstach sie beide, den israelitischen Mann und das Weib, durch ihren Leib. Und der Plage an den Söhnen Israels ward Einhalt getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Und der Toten an der Plage waren vierundzwanzigtausend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Pinechas, der Sohn Eleasars, des Sohnes Aharons, des Priesters, hat Meinen Grimm zurückgewendet von den Söhnen Israels, indem er Meinen Eifer in ihrer Mitte eiferte, so daß Ich die Söhne Israels in Meinem Eifer nicht verzehrte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Darum sprich: Siehe, Ich gebe ihm Meinen Bund des Friedens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'Und der soll ihm und seinem Samen nach ihm der Bund ewigen Priestertums sein dafür, daß er für seinen Gott geeifert und die Söhne Israels gesühnt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Und der Name des erschlagenen israelitischen Mannes, der mit der Midianitin erschlagen worden, war Simri, der ein Sohn Salus und Fürst eines Vaterhauses der Simeoniten war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'Und der Name des erschlagenen midianitischen Weibes war Kosbi, die Tochter Zurs, der Haupt eines Volksstammes eines Vaterhauses in Midian war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Bedränge die Midianiter und schlaget sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'Denn sie haben euch mit ihrem Anschlag, den sie wider euch faßten, bedrängt, mit der Sache Peors und mit der Sache der Kosbi, der Tochter des Midianiter-Fürsten, ihrer Schwester, die am Tage der Plage um der Sache Peors willen erschlagen ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'Und es geschah nach der Plage, daß Jehovah sprach zu Mose und zu Eleasar, dem Sohne Aharons, des Priesters; und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Nehmet auf die Kopfzahl der ganzen Gemeinde der Söhne Israels vom zwanzigsten Jahre und aufwärts nach dem Hause ihrer Väter, alle, die im Heer ausziehen in Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Und Mose und Eleasar, der Priester, redete mit ihnen in Arboth Moab am Jordan, bei Jericho und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Vom zwanzigsten Jahre an und aufwärts, wie Jehovah dem Mose und den Söhnen Israels, die aus Ägyptenland auszogen, geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben, Israels Erstgeborener: Söhne Rubens waren Chanoch, die Familie der Chanochiten; von Phallu die Familie der Phalluiten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'Von Chezron die Familie der Chezroniten, von Charmi die Familie der Charmiten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'Dies sind die Familien der Rubeniten. Ihrer Gemusterten aber waren es dreiundvierzigtausendsiebenhundertdreißig;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Und die Söhne Phallus Eliab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'Und die Söhne Eliabs Nemuel und Dathan und Abiram - das waren Dathan und Abiram, Berufene der Gemeinde, die zankten mit Mose und mit Aharon in der Gemeinde Korachs, als sie wider Jehovah zankten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'Und die Erde öffnete ihren Mund und verschlang sie und Korach, da die Gemeinde starb, indem das Feuer die zweihundertfünfzig Männer auffraß und sie zum Zeichen wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Korachs Söhne waren aber nicht gestorben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Die Söhne Simeons nach ihren Familien: Von Nemuel die Familie der Nemueliten, von Jamin die Familie der Jaminiten, von Jachin die Familie der Jachiniten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'Von Serach die Familie der Serachiten, von Schaul die Familie der Schauliten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'Dies sind die Familien der Simeoniten: Zweiundzwanzigtausendzweihundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Die Söhne Gads nach ihren Familien: Von Zephon die Familie der Zephoniten, von Chaggi die Familie der Chaggiten, von Schuni die Familie der Schuniten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'Von Osni die Familie der Osniten, von Eri die Familie der Eriten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'Von Arod die Familie der Aroditen; von Areli die Familie der Areliten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'Dies sind die Familien der Söhne Gads nach ihren Gemusterten: vierzigtausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Die Söhne Judahs: Er und Onan. Und Er und Onan starben im Lande Kanaan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Und die Söhne Judahs waren nach ihren Familien: Von Schelah die Familie der Schelaniten, von Perez die Familie der Parziten, von Serach die Familie der Sarchiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'Und die Söhne des Perez waren: Von Chezron die Familie der Chezroniten, von Chamul die Familie der Chamuliten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'Dies sind die Familien Judahs nach ihren Gemusterten: sechsundsiebzigtausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Die Söhne Issaschars nach ihren Familien: Von Thola die Familie der Tholaiten; von Puvah die Familie der Puniten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'Von Jaschub die Familie der Jaschubiten; von Schimron die Familie der Schimroniten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'Das sind die Familien Issaschars nach ihren Gemusterten: vierundsechzigtausenddreihundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Die Söhne Sebuluns nach ihren Familien: Von Sared die Familie der Sarditen; von Elon die Familie der Eloniten; von Jachleel die Familie der Jachleeliten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'Dies sind die Familien der Sebuluniten nach ihren Gemusterten: sechzigtausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Die Söhne Josephs nach ihren Familien sind Menascheh und Ephraim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Die Söhne Menaschehs: Von Machir die Familie der Machiriten. Und Machir zeugte Gilead. Von Gilead die Familie der Gileaditen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'Das sind die Söhne Gileads: Jeser, die Familie der Jesriten; von Chelek, die Familie der Chelekiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'Und Asriel, die Familie der Asrieliten; und Schechem, die Familie der Schichmiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'Und Schemidah, die Familie der Schemidaiten, und Chepher, die Familie der Chephriten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Und Zelaphechad, Chephers Sohn, hatte keine Söhne, nur Töchter. Und die Namen von Zelaphechads Töchtern waren Machlah und Noah, Choglah, Milkah und Thirzah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'Das sind die Familien Menaschehs; und ihrer Gemusterten sind zweiundfünfzigtausendsiebenhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Das sind die Söhne Ephraims nach ihren Familien: Von Schuthelach die Familie der Schuthalchiten; von Becher die Familie der Bachriten; von Thachan die Familie der Thachaniten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Und dies sind die Söhne Schuthelachs: Von Eran die Familie der Eraniten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'Dies sind die Familien der Söhne Ephraims nach ihren Gemusterten: zweiundreißigtausendfünfhundert. Das sind die Söhne Josephs nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Die Söhne Benjamins nach ihren Familien: Von Bela die Familie der Baliten; von Aschbel die Familie der Aschbeliten; von Achiram die Familie der Achiramiten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'Von Schephupham die Familie der Schuphamiten; von Chupham die Familie der Chuphamiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Und die Söhne Belahs sind Ard und Naaman; die Familie der Arditen, von Naaman die Familie der Naamiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'Dies sind die Söhne Benjamins nach ihren Familien; und ihrer Gemusterten waren es fünfundvierzigtausendsechshundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'Das sind die Söhne Dans nach ihren Familien: Von Schucham die Familie der Schuchamiten. Dies die Familien Dans nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'Alle Familien der Schuchaniten nach ihren Gemusterten waren vierundsechzigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Die Söhne Aschers nach ihren Familien sind: Von Jimmah die Familie der Jimniten; von Jischvi die Familie der Jischviten; von Beriah die Familie der Beriiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Von den Söhnen Beriah, von Cheber die Familie der Chebriten; von Malkiel die Familie der Malkieliten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Und der Name der Tochter Aschers war Serach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'Dies sind die Familien der Söhne Aschers nach ihren Gemusterten: dreiundfünfzigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Die Söhne Naphthalis nach ihren Familien: Von Jachzeel die Familie der Jachzeeliten; von Guni die Familie der Guniten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'Von Jezer die Familie der Jizriten; von Schillem die Familie der Schillemiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'Das sind die Familien Naphthalis nach ihren Familien; und ihrer Gemusterten waren es fünfundvierzigtausendvierhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'Dies sind die Gemusterten der Söhne Israels sechshunderttausend und tausendsiebenhundertdreißig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'An diese soll das Land verteilt werden zum Erbe nach der Zahl der Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Dem Vielen werde viel zu seinem Erbe und dem Wenigen wenig zu seinem Erbe. Jeglichem Manne werde sein Erbe gegeben nach dem Verhältnis seiner Gemusterten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Man verteile jedoch das Land durch das Los; nach den Namen der Stämme ihrer Väter sollen sie es erben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Nach dem Los soll man sein Erbe verteilen, zwischen viel oder wenig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Und das sind die gemusterten der Leviten nach ihren Familien: Von Gerschon die Familie der Gerschoniten; von Kohath die Familie der Kohathiten; von Merari die Familie der Merariten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'Dies sind die Familien Levis, die Familien der Libniten, der Familien der Chebroniten, die Familie der Machliten, die Familie der Muschiten, die Familie der Korchiten, und Kohath zeugte den Amram.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'Und der Name von Amrams Weib war Jochebet, eine Tochter Levis, die dem Levi in Ägypten geboren ward. Und sie gebar dem Amram den Aharon und den Mose und Mirjam, ihre Schwester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Und dem Aharon wurden geboren Nadab und Abihu, Eleasar und Ithamar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'Und Nadab und Abihu waren gestorben, da sie fremdes Feuer vor Jehovah darbrachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'Und ihrer Gemusterten waren es dreiundzwanzigtausend, alles Männliche von einem Monat und aufwärts: denn sie wurden nicht inmitten der Söhne Israels gemustert, weil ihnen kein Erbe inmitten der Söhne Israels gegeben ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'Dies sind die von Mose und dem Priester Eleasar Gemusterten, da sie die Söhne Israels in Arboth Moab am Jordan, bei Jericho, musterten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Und unter ihnen war kein Mann, der von Mose und Aharon, dem Priester, Gemusterten, da sie die Söhne Israels in der Wüste Sinai musterten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Denn Jehovah hatte von ihnen gesprochen, daß sie in der Wüste des Todes sterben sollten. Und kein Mann blieb von ihnen übrig außer Kaleb, der Sohn Jephunnehs und Joschua, der Sohn Nuns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Und es nahten sich die Töchter Zelaphechads, des Sohnes Chephers, des Sohnes Giledas, des Sohnes Machirs, des Sohnes Menaschehs, von den Familien Menaschehs, des Sohnes Josephs; und dies sind die Namen seiner Töchter: Machlah, Noah und Choglah und Milkah und Thirzah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Und sie standen vor Mose und vor Eleasar, den Priester, und vor die Fürsten und die ganze Gemeinde an den Eingang des Versammlungszeltes und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Unser Vater ist in der Wüste gestorben, er war aber nicht inmitten der Gemeinde, die sich wider Jehovah zusammentat in Korachs Gemeinde, sondern ist ob seiner Sünde gestorben, und hatte keine Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Warum soll der Name unseres Vaters aus der Mitte seiner Familie weggelassen werden, weil er keinen Sohn hatte? Gib uns ein Eigentum inmitten der Brüder unseres Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Und Mose brachte ihre Rechtssache dar vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'Und Jehovah sprach zu Mose, und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Zelaphechads Töchter haben richtig geredet. Du sollst ihnen das Eigentum eines Erbes inmitten der Brüder ihres Vaters geben und das Erbe ihres Vaters auf sie übergehen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Und zu den Söhnen Israels rede und sprich: So ein Mann stirbt und hat keinen Sohn, so lasset sein Erbe an seine Tochter übergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'Und hat er keine Tochter, so gebet sein Erbe seinen Brüdern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'Und hat er keine Brüder, so gebt sein Erbe den Brüdern seines Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'Und wenn sein Vater keine Brüder hat, so gebt sein Erbe dem nächsten Blutsverwandten aus seiner Familie, und er soll es erblich besitzen; und das sei für die Söhne Israels eine Rechtssatzung, so wie Jehovah dem Mose geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'Und Jehovah sprach zu Mose: Steig hinauf auf den Berg Abarim da, und siehe das Land, das Ich den Söhnen Israels gegeben habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'Und wenn du es gesehen hast, sollst auch du zu deinem Volke versammelt werden, wie dein Bruder Aharon versammelt worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'Weil ihr widerspenstig waret wider Meinen Befehl in der Wüste Zin beim Hadern der Gemeinde, da ihr Mich solltet durch das Wasser, vor ihren Augen heiligen. Dies sind die Haderwasser von Kadesch in der Wüste Zin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Und Mose redete zu Jehovah und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Es bestelle Jehovah, der Gott der Geister alles Fleisches, einen Mann über die Gemeinde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'Der vor ihnen her ausgehe und vor ihnen eingehe, und der sie ausführe und der sie einführe, auf daß Jehovahs Gemeinde nicht sei wie die Herde, die keinen Hirten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Und Jehovah sprach zu Mose: Nimm dir Jehoschua, den Sohn Nuns, einen Mann, in dem der Geist ist, und lege deine Hand auf ihn;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'Und laß ihn vor Eleasar, den Priester, und vor die ganze Gemeinde stehen, und gebiete ihm vor ihren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'Und lege von deiner Majestät auf ihn, so daß die ganze Gemeinde der Söhne Israels es höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'Und er stehe vor Eleasar, dem Priester, und er frage für ihn nach dem Rechte der Urim vor Jehovah. Nach seinem Befehl sollen ausgehen und nach seinem Befehl sollen eingehen er und alle Söhne Israels mit ihm und die ganze Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Und Mose tat, wie Jehovah ihm geboten hatte, und nahm den Jehoschua und ließ ihn vor Eleasar, den Priester, und vor die ganze Gemeinde stehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'Und legte seine Hände auf ihn und gebot ihm, wie Jehovah durch Mose geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Gebiete den Söhnen Israels und sprich zu ihnen: Meine Opfergabe, Mein Brot, zu Meinen Feueropfern des Geruches Meiner Ruhe sollt ihr halten, daß ihr sie Mir darbringet zur bestimmten Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'Und sprich zu ihnen: Dies ist das Feueropfer, das ihr dem Jehovah darbringen sollt: Jährige Lämmer ohne Fehl, zwei am Tage, als beständiges Brandopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Das eine Lamm sollst du am Morgen bereiten und das zweite Lamm sollst du bereiten gegen Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'Und ein zehntel Ephah Semmelmehl zu einem Speiseopfer, mit zerstoßenem Öl vermischt, ein viertel Hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'Ein beständiges Brandopfer ist es, das am Berge Sinai bereitet worden zum Geruch der Ruhe, ein Feueropfer für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Und sein Trankopfer ein viertel Hin auf das eine Lamm. Im Heiligtum gieße aus ein Trankopfer starken Getränkes dem Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Und das zweite Lamm bereite zu gegen Abend, wie das Speiseopfer des Morgens, und wie sein Trankopfer sollst du es bereiten, ein Feueropfer des Geruchs der Ruhe dem Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'Und am Sabbathtage zwei einjährige Lämmer ohne Fehl und zwei Zehntel Semmelmehl als Speiseopfer, mit Öl vermischt, und sein Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'Das Brandopfer des Sabbaths an seinem Sabbathtag, außer dem beständigen Brandopfer und seinem Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'Und am Ersten eurer Monate sollt ihr Jehovah ein Brandopfer darbringen: Zwei junge Farren von den Rindern, und einen Widder und sieben einjährige Lämmer ohne Fehl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'Und drei Zehntel Semmelmehl als Speiseopfer, mit Öl vermischt, auf den einen Farren, und zwei Zehntel Semmelmehl mit Öl vermischt auf den einen Widder, zum Speiseopfer,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'Und je ein Zehntel Semmelmehl als Speiseopfer, mit Öl vermischt, auf je ein Lamm, als Brandopfer zum Geruch der Ruhe; ein Feueropfer für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'Und ihre Trankopfer sollen sein ein halbes Hin zu dem Farren und ein drittel Hin zu dem Widder und ein viertel Hin Wein auf das Lamm. Dies ist das Brandopfer des Neumonds an seinem Neumond an den Neumonden des Jahres.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'Und einen Ziegenbock als Sündopfer für Jehovah, außer dem beständigen Brandopfer mache man und sein Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'Und im ersten Monat am vierzehnten Tage des Monats ist das Passah für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'Und am fünfzehnten Tag dieses Monats ist Fest. Sieben Tage soll ungesäuertes Brot gegessen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Am ersten Tage soll heilige Zusammenberufung sein; keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'Und ein Feueropfer sollt ihr, ein Brandopfer für Jehovah von zwei jungen Farren von den Rindern und einen Widder und sieben einjährigen Lämmern darbringen. Ohne Fehl sollen sie euch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'Und ihr Speiseopfer, Semmelmehl mit Öl vermischt, drei Zehntel auf den Farren und zwei Zehntel auf den Widder, sollt ihr sie bereiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'Je ein Zehntel sollt ihr es machen für ein Lamm, für die sieben Lämmer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Und einen Bock zum Sündopfer, euch zu sühnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Außer dem Morgenbrandopfer, das ein beständiges Brandopfer ist, sollt ihr diese machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Wie mit diesen sollt ihr an jedem Tage der sieben Tage es machen, das Brot des Feueropfers als Geruch der Ruhe für Jehovah; außer dem beständigen Brandopfer und seinem Trankopfer werde es gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Und am siebenten Tage soll heilige Zusammenberufung für euch sein. Keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Und am Tage der Erstlinge, wenn ihr dem Jehovah in euren Wochen neues Speiseopfer darbringet, soll bei euch heilige Zusammenberufung sein, und keinerlei Dienstarbeit sollt ihr tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'Und ihr sollt Jehovah ein Brandopfer darbringen zum Geruch der Ruhe, zwei junge Farren von den Rindern, einen Widder, sieben einjährige Lämmer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'Und ihr Speiseopfer, Semmelmehl, mit Öl vermischt, drei Zehntel auf den einen Farren, zwei Zehntel auf den einen Widder;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'Je ein Zehntel auf ein Lamm für die sieben Lämmer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'Einen Ziegenbock, euch zu sühnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Außer dem beständigen Brandopfer und seinem Speiseopfer sollt ihr sie machen; ohne Fehl seien sie für euch, und ihre Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'Und im siebenten Monat, am ersten des Monats sollt ihr heilige Zusammenberufung haben; keinerlei Dienstarbeit sollt ihr tun. Ein Tag des Lärmblasens sei er euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'Und ein Brandopfer sollt ihr Jehovah machen zum Geruch der Ruhe, einen jungen Farren von den Rindern, einen Widder, sieben einjährige Lämmer ohne Fehl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'Und ihr Speiseopfer sei drei Zehntel Semmelmehl mit Öl vermischt auf den Farren, zwei Zehntel auf den Widder;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'Und ein Zehntel auf das eine Lamm, für die sieben Lämmer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'Und ein Ziegenbock, als Sündopfer, euch zu sühnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'Außer dem Brandopfer des Neumondes und seinem Speiseopfer, und dem beständigen Brandopfer und dessen Speiseopfer und deren Trankopfern, nach ihrem Rechte, zum Geruch der Ruhe, ein Feueropfer für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'Und am zehnten dieses siebenten Monats sollt ihr eine heilige Zusammenberufung haben und eure Seelen demütigen. Keinerlei Arbeit sollt ihr tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Und dem Jehovah sollt ihr zum Geruch der Ruhe als Brandopfer darbringen einen jungen Farren von den Rindern, einen Widder, sieben einjährige Lämmer. Ohne Fehl sollen sie sein für euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'Und ihr Speiseopfer sei Semmelmehl mit Öl vermischt, drei Zehntel auf den Farren, zwei Zehntel auf den einen Widder;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'Je ein Zehntel auf das eine Lamm für die sieben Lämmer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'Ein Ziegenbock als Sündopfer, außer dem Sündopfer der Sühne und dem beständigen Brandopfer und seinem Speiseopfer und ihre Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'Und am fünfzehnten Tag des siebenten Monats sollt ihr eine heilige Zusammenberufung haben und keinerlei Dienstarbeit tun, sondern sieben Tage ein Fest für Jehovah feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'Und sollt als Brandopfer darbringen dem Jehovah ein Feueropfer zum Geruch der Ruhe: dreizehn junge Farren von den Rindern, zwei Widder, vierzehn einjährige Lämmer. Ohne Fehl sollen sie sein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'Und ihr Speiseopfer, Semmelmehl mit Öl vermischt, drei Zehntel zu dem einen Farren für die dreizehn Farren, zwei Zehntel für den einen Widder, für die zwei Widder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'Und je ein Zehntel für das eine Lamm, für die vierzehn Lämmer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'Und einen Ziegenbock zum Sündopfer, außer dem beständigen Brandopfer, seinem Speiseopfer und seinem Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Und am zweiten Tage zwölf junge Farren von den Rindern, zwei Widder, vierzehn einjährige Lämmer ohne Fehl;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'Und ihr Speiseopfer und ihre Trankopfer zu den Farren, den Widdern und den Lämmern in ihrer Zahl gemäß dem Recht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'Und einen Ziegenbock als Sündopfer, außer dem beständigen Brandopfer und seinem Speiseopfer und ihren Trankopfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Und am dritten Tage elf Farren, zwei Widder, vierzehn einjährige Lämmer ohne Fehl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'Und ihr Speiseopfer und ihre Trankopfer zu den Farren, zu den Widdern und zu den Lämmern in ihrer Zahl gemäß dem Recht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'Und einen Bock als Sündopfer, außer dem beständigen Brandopfer und seinem Speiseopfer und seinem Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Und am vierten Tage zehn Farren, zwei Widder, vierzehn einjährige Lämmer ohne Fehl;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'Ihr Speiseopfer und ihre Trankopfer zu den Farren, zu den Widdern und zu den Lämmern in ihrer Zahl gemäß dem Recht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'Und einen Ziegenbock als Sündopfer, außer dem beständigen Brandopfer, seinem Speiseopfer und seinem Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Und am fünften Tage neun Farren, zwei Widder, vierzehn einjährige Lämmer ohne Fehl;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'Und ihr Speiseopfer und ihre Trankopfer zu den Farren, zu den Widdern und zu den Lämmern in ihrer Zahl gemäß dem Recht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'Und einen Bock zum Sündopfer, außer dem beständigen Brandopfer und seinem Speiseopfer und seinem Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Und am sechsten Tage acht Farren, zwei Widder, vierzehn einjährige Lämmer ohne Fehl;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'Und ihr Speiseopfer und ihre Trankopfer zu den Farren, zu den Widdern und zu den Lämmern in ihrer Zahl gemäß dem Recht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'Und einen Bock zum Sündopfer, außer dem beständigen Brandopfer und seinem Speiseopfer und seinen Trankopfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Und am siebenten Tage sieben Farren, zwei Widder, vierzehn einjährige Lämmer ohne Fehl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'Und ihr Speiseopfer und ihre Trankopfer zu den Farren, zu den Widdern und zu den Lämmern in ihrer Zahl gemäß dem Recht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'Und einen Bock zum Sündopfer, außer dem beständigen Brandopfer, seinem Speiseopfer und seinem Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'Am achten Tage soll bei euch Festversammlung sein, und sollt keinerlei Dienstarbeit tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Und sollt als Brandopfer dem Jehovah ein Feueropfer zum Geruch der Ruhe darbringen: einen Farren, einen Widder, sieben einjährige Lämmer ohne Fehl;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'Ihr Speiseopfer und ihre Trankopfer zu dem Farren, zu dem Widder und zu den Lämmern in ihrer Zahl und dem Recht gemäß;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'Und einen Bock als Sündopfer, außer dem beständigen Brandopfer und seinem Speiseopfer und seinem Trankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Dies sollt ihr tun für Jehovah an euren Festzeiten außer euren Gelübden und freiwilligen Opfern, euren Brandopfern und euren Speiseopfern und euren Trankopfern und euern Dankopfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'Und Mose sprach zu den Söhnen Israels gemäß allem, das Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Und Mose redete zu den Häuptern der Stämme der Söhne Israels und sprach: Dies ist das Wort, das Jehovah geboten hat:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'So ein Mann ein Gelübde gelobt dem Jehovah, oder einen Schwur schwört, daß er eine Verbindlichkeit auf seine Seele bindet, so soll er sein Wort nicht entweihen, er soll gemäß allem tun, das von seinem Munde ausgegangen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'Und so ein Weib dem Jehovah ein Gelübde gelobt und bindet eine Verbindlichkeit in ihres Vaters Hause, in ihrer Jugend,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Und ihr Vater hört ihr Gelübde und die Verbindlichkeit, die sie auf ihre Seele gebunden hat, und ihr Vater schweigt stille gegen sie, so bestehen alle ihre Gelübde, und alle Verbindlichkeit, die sie auf ihre Seele gebunden, besteht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'So aber ihr Vater ihr wehrt am Tage, da er irgendein Gelübde von ihr und eine Verbindlichkeit hört, die sie auf ihre Seele gebunden, so besteht es nicht, und Jehovah vergibt ihr, weil ihr Vater ihr gewehret hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'Gehört sie aber einem Manne an, und hat ein Gelübde auf sich, oder ist etwas über ihre Lippen gefahren, das sie auf ihre Seele bindet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Und ihr Mann hört es und schweigt stille gegen sie am Tage seines Hörens, so bestehen ihre Gelübde, und die Verbindlichkeiten, die sie auf ihre Seele gebunden, haben Bestand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Wenn ihr aber ihr Mann am Tage, da er es hört, wehrt, und er ihr Gelübde zunichte macht, das sie auf sich hat, und das, was über ihre Lippen gefahren, das sie auf ihre Seele gebunden hat, so vergibt ihr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'Anlangend das Gelübde einer Witwe und einer Verstoßenen, so besteht für sie alles, was sie auf ihre Seele gebunden hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'Wenn sie aber im Haus ihres Mannes gelobte, oder mit einem Schwur eine Verbindlichkeit auf ihre Seele gebunden hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Und ihr Mann hört es und schweigt stille dazu vor ihr, wehrt es ihr nicht, so bestehen alle ihre Gelübde, und alle Verbindlichkeit, die sie auf ihre Seele gebunden, besteht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Wenn ihr Mann aber am Tage, da er davon hört, sie zunichte macht, so soll alles, das von ihren Lippen ausgeht, für ihre Gelübde und für die Verbindlichkeit ihrer Seele nicht bestehen; ihr Mann hat sie zunichte gemacht, und Jehovah vergibt ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Alles Gelübde und allen Schwur, den sie zur Demütigung ihrer Seele auf sich gebunden, kann ihr Mann bestätigen und ihr Mann zunichte machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Schweigt ihr Mann ihr aber stille dazu von Tag zu Tag, und hat er damit bestätigt alle ihre Gelübde oder alle Verbindlichkeiten, die sie auf sich hat, so hat er sie bestätigt, weil er am Tage, da er es gehört, gegen sie stillegeschwiegen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'Macht er sie aber zunichte, nachdem er sie gehört hat, so trägt er ihre Missetat. Dies sind die Satzungen, die Jehovah Mose geboten hat zwischen dem Mann und seinem Weib, zwischen dem Vater und seiner Tochter in ihrer Jugend im Hause ihres Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Nimm Rache für die Söhne Israels an den Midianitern. Danach sollst du zu deinen Völkern versammelt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Und Mose redete zu dem Volke und sprach: Rüstet Männer unter euch zu einem Heere aus und sie seien wider Midian, um Jehovah Rache zu geben an Midian.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Je tausend für jeden Stamm von allen Stämmen Israels sollt ihr senden zum Heere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'Und es wurden aus den Tausenden Israels je tausend aus jedem Stamm, zwölftausend zum Heere Ausgerüstete, ausgehoben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'Und Mose sandte sie zum Heere, Tausend vom Stamme, sie und Pinechas, Eleasars, des Priesters Sohn, zum Heer, und die heiligen Geräte, und die Trompeten zum Lärmblasen in seiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'Und sie rückten aus wider Midian, wie Jehovah dem Mose geboten hatte, und erwürgten alles, was männlich war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Und die Könige Midians erwürgten sie samt den Erschlagenen, Evi und Rekem und Zur und Chur und Reba, fünf Könige Midians. Und Bileam, Beors Sohn, erwürgten sie mit dem Schwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'Und die Söhne Israels nahmen die Weiber Midians und ihre Kindlein gefangen, und all ihr Vieh und all ihre Viehherden und all ihr Vermögen raubten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'Und alle ihre Städte in ihren Wohnsitzen und all ihre Gehöfte verbrannten sie mit Feuer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'Und sie nahmen alle Beute und alles, was sie genommen an Menschen und an Vieh,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'Und brachten zu Mose und zu Eleasar, dem Priester, und zu der Gemeinde der Söhne Israels herein die Gefangenen und das Genommene und die Beute zum Lager nach Arboth Moab am Jordan bei Jericho.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Und Mose und Eleasar, der Priester, und alle Fürsten der Gemeinde gingen hinaus außerhalb des Lagers ihnen entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'Und Mose ward entrüstet über die Anführer der Streitmacht, die Obersten über Tausende und die Obersten über Hunderte, die aus dem Heerstreite kamen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'Und Mose sprach zu ihnen: Habt ihr denn alle Weiber leben lassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Sehet, sie sind es gewesen, die nach Bileams Worten die Söhne Israels ob der Sache Peors dem Jehovah Untreue anheben ließen und die Plage war in der Gemeinde Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Und nun erwürget alles Männliche unter den Kindlein, und jedes Weib, das einen Mann erkannt durch Liegen mit dem Männlichen, erwürget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Und alle weiblichen Kindlein, die das Beilager des Männlichen nicht kannten, sollt ihr für euch leben lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'Ihr aber sollt sieben Tage lagern au-ßerhalb des Lagers, jeder, der jemand erwürgt, und jeder, der einen Erschlagenen berührt hat. Ihr sollt euch entsündigen am dritten Tage und am siebenten Tage, ihr und eure Gefangenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Und jedes Kleid und jedes lederne Gefäß, und alles, was aus Ziegenhaaren gemacht ist, und alles hölzerne Gefäß sollt ihr für euch entsündigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Und Eleasar, der Priester, sprach zu den Männern des Streites, die zum Streite auszogen: Dies ist die Satzung des Gesetzes, die Jehovah dem Mose geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Nur das Gold und das Silber, das Erz, das Eisen, das Zinn und das Blei,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'Alles Ding, was ins Feuer kommt, sollt ihr durch das Feuer durchgehen lassen, daß es rein werde, nur soll es mit dem Ausscheidungswasser entsündigt werden, alles aber, das nicht ins Feuer kommen darf, sollt ihr durch das Wasser durchgehen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'Und waschet eure Kleider am siebenten Tag, und ihr seid rein und dürfet danach in das Lager kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'Und Jehovah sprach zu Mose, und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Nimm die Kopfzahl auf des Genommenen der Gefangenen an Menschen und an Vieh, du und Eleasar, der Priester, und die Häupter der Väter der Gemeinde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'Und halbiere das Genommene zwischen denen, die im Streite angefaßt, die zum Heer auszogen, und zwischen der ganzen Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'Und erhebe eine Abgabe für Jehovah von den Männern des Streites, die zum Heere ausgezogen, eine Seele von fünfhundert, vom Menschen und vom Rind und von den Eseln und vom Kleinvieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'Von ihrer Hälfte sollst du es nehmen und gib es Eleasar, dem Priester, als Hebe für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Und von der Hälfte der Söhne Israels sollst du nehmen ein Stück von fünfzig, vom Menschen, vom Rind, von Eseln und vom Kleinvieh, von allem Vieh, und sie den Leviten geben, so die Hut der Wohnung Jehovahs hüten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'Und Mose und Eleasar, der Priester, taten, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'Das Genommene aber, das übrig war von dem Raub, des Heeres Volk war an Kleinvieh sechshunderttausend und siebzigtausend und fünftausend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'Und Rinder zweiundsiebzigtausend;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'Und Esel einundsechzigtausend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'Und die Seelen der Menschen von den Weibern, die das männliche Beilager nicht gekannt, aller Seelen waren zweiunddreißigtausend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Und die Hälfte, der Teil derer, die in dem Heere ausgezogen waren, war in Kleinvieh an Zahl dreihunderttausend und dreißigtausend und siebentausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'Und die Abgabe für Jehovah vom Kleinvieh sechshundertfünfundsiebzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'Und Rinder waren es sechsunddreißigtausend; und die Abgabe für Jehovah zweiundsiebzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'Und Esel dreißigtausendfünfhundert; und die Abgabe für Jehovah einundsechzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'Und an Menschenseelen sechzehntausend; und Abgabe für Jehovah zweiunddreißig Seelen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Und Mose gab die Abgabe, eine Hebe für Jehovah Eleasar, dem Priester, so wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Und von der Hälfte der Söhne Israels, die Mose von den Männern, die im Heere waren, abgehälftet hatte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, 'Da war die Hälfte der Gemeinde an Kleinvieh dreihunderttausend und dreißigtausend und siebentausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'Und Rinder sechsunddreißigtausend;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'Und Esel dreißigtausendfünfhundert;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'Und Menschenseelen sechzehntausend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'Und Mose nahm von der Hälfte der Söhne Israels ein Stück von fünfzig, von den Menschen und vom Vieh, und gab sie den Leviten, welche die Hut der Wohnung des Jehovah hüten, wie Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Und es nahten zu Mose die Anführer, welche über die Tausende des Heeres waren, die Obersten der Tausende und die Obersten der Hunderte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'Und sprachen zu Mose: Deine Knechte haben die Kopfzahl der Männer des Streites aufgenommen, die unter unseren Händen waren, und nicht ein Mann von ihnen ward vermißt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Und so bringen wir denn eine Opfergabe dem Jehovah dar, was jeder Mann von goldenem Geräte, Fußspangen und Armbändern, Ringen, Ohrringen und Schmuckkügelchen gefunden hat, um unsere Seelen vor Jehovah zu sühnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'Und Mose und Eleasar, der Priester, nahmen das Gold von ihnen und alles Kunstgeräte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'Und alles Hebegold, das sie Jehovah hoben, war sechzehntausendsiebenhundertfünfzig Schekel, von den Obersten der Tausende und von den Obersten der Hunderte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, 'Die Männer des Heeres hatten jeder Mann für sich geraubt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'Mose aber und Eleasar, der Priester, nahmen das Gold von den Obersten der Tausende und der Hunderte und brachten es herein zum Versammlungszelt zum Andenken für die Söhne Israels vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Und der Viehherden der Söhne Rubens und der Söhne Gads waren viel und sehr mächtige; und sie sahen das Land Jaser und das Land Gilead und siehe, der Ort war ein Ort für Viehherden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Und die Söhne Gads und die Söhne Rubens kamen und sprachen zu Mose und zu Eleasar, dem Priester, und zu den Fürsten der Gemeinde und sagten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Ataroth und Dibon und Jaser und Nimrah und Cheschbon und Elealeh und Sebam und Nebo und Beon,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'Das Land, das Jehovah geschlagen hat vor der Gemeinde Israels, ist ein Land für Viehherden, und deine Knechte haben Viehherden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Und sie sprachen: Haben wir Gnade in deinen Augen gefunden, so gebe man dieses Land deinen Knechten zum Eigentum. Laß uns nicht über den Jordan setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'Und Mose sprach zu den Söhnen Gads und zu den Söhnen Rubens: Sollen eure Brüder in den Streit eingehen und ihr wollet hier wohnen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'Und warum wollet ihr dem Herzen der Söhne Israels wehren, daß sie nicht in das Land hinziehen, das Jehovah ihnen gegeben hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'So taten eure Väter, da ich sie sandte von Kadesch Barnea, das Land zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'Und sie gingen hinauf bis zum Bachtale Eschkol und sahen das Land, und wehrten dem Herzen der Söhne Israels, daß sie nicht in das Land eingehen sollten, das ihnen Jehovah gegeben hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'Und der Zorn Jehovahs entbrannte an jenem Tage, und Er schwur und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Nimmermehr sollen die Männer, die von Ägypten heraufzogen, vom zwanzigsten Jahr und darüber, den Boden sehen, den Ich dem Abraham, dem Isaak und dem Jakob zugeschworen; denn sie folgen Mir nicht vollständig nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'Außer Kaleb, dem Sohne Jephunnehs, dem Kenissiter, und Nuns Sohn Jehoschua, die Mir vollständig gefolgt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'Und der Zorn Jehovahs entbrannte wider Israel und Er ließ sie vierzig Jahre in der Wüste umherwandern, bis alle war das ganze Geschlecht, das getan, was böse war in Jehovahs Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'Und siehe, ihr seid aufgestanden an eurer Väter Statt, eine Menge von Männern, von Sündern, zu mehren das Entbrennen des Zorns Jehovahs über Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Wendet ihr euch zurück von Ihm, so läßt Er sie noch länger in der Wüste bleiben, und ihr werdet all dies Volk verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'Und sie traten heran zu ihm und sprachen: Hürden für das Kleinvieh wollen wir hier für unsre Viehherden bauen und Städte für unsre Kindlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'Wir aber wollen uns schleunig ausrüsten vor den Söhnen Israels her, bis daß wir sie an ihren Ort hineingebracht haben; unsre Kindlein aber sollen in den festen Städten wohnen vor den Einwohnern des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Wir wollen nicht in unsre Häuser zurückkehren, bis die Söhne Israels jeder Mann sein Erbe geerbet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Denn wir wollen nicht mit ihnen erben jenseits des Jordans und weiterhin, da unser Erbe diesseits des Jordans gegen Aufgang an uns gekommen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Und Mose sprach zu ihnen: Wenn ihr nach diesem Worte tut, wenn ihr euch ausrüstet zum Streite vor Jehovah her,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'So daß jeder von euch ausgerüstet über den Jordan hinüberziehe vor Jehovah, bis daß Er Seine Feinde vor Ihm ausgetrieben hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'Und das Land vor dem Angesichte Jehovahs unterworfen ist; und danach dürft ihr zurückkehren und seid unschuldig vor Jehovah und vor Israel, und dieses Land sei euer Eigentum vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Wenn ihr aber nicht so tut, siehe, so versündiget ihr euch an Jehovah und sollt wissen, daß eure Sünde euch finden wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Bauet euch Städte für eure Kindlein und Hürden für euer Kleinvieh; und was aus eurem Munde ausging, das tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'Und die Söhne Gads und die Söhne Rubens sprachen zu Mose und sagten: Deine Knechte werden tun, wie mein Herr gebietet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Unsere Kindlein, unsre Weiber, unsere Viehherden und all unser Vieh soll hier in den Städten Gileads sein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'Deine Knechte aber werden, jeglicher zum Heere ausgerüstet, vor Jehovah hinziehen zum Streite, wie mein Herr geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Und Mose gebot ihretwegen Eleasar, dem Priester, und Jehoschua, Nuns Sohn, und den Häuptern der Väter der Stämme der Söhne Israels,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'Und Mose sprach zu ihnen: Wenn die Söhne Gads und die Söhne Rubens allesamt zum Streite ausgerüstet vor Jehovah mit euch über den Jordan hinüberziehen, und das Land vor euch unterworfen ist, so sollt ihr ihnen das Land Gilead zum Eigentume geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'Ziehen sie aber nicht ausgerüstet mit euch hinüber, so sollen sie in eurer Mitte im Lande Kanaan Besitz haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Und die Söhne Gads und die Söhne Rubens antworteten und sprachen: Wie Jehovah zu deinen Knechten geredet hat, so wollen wir tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Wir wollen ausgerüstet vor Jehovah ins Land Kanaan hinüberziehen und für uns das Eigentum unseres Erbes diesseits des Jordans haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'Und Mose gab ihnen, den Söhnen Gads und den Söhnen Rubens und dem halben Stamm Menascheh, des Sohnes Josephs, das Reich Sichons, des Amoriterkönigs, und das Reich Ogs, des Königs von Baschan, das Land nach seinen Städten in den Grenzen, die Städte des Landes ringsumher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'Und die Söhne Gads bauten Dibon und Ataroth und Aroer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Und Atroth Schophan und Jaser und Jogbehah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Und Beth-Nimrah und Beth-Haran, feste Städte und Hürden des Kleinviehs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Und Rubens Söhne bauten Cheschbon und Elealeh und Kirjathaim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Und Nebo und Baal Meon, deren Namen verändert wurden, und Sibmah, und nannten mit Namen die Namen der Städte, die sie bauten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'Und die Söhne Machirs, des Sohnes Menaschehs, gingen gen Gilead und eroberten es; und trieben aus die Amoriter, die darinnen waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'Und Mose gab Gilead dem Machir, dem Sohn Menaschehs, und er wohnte darin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Und Jair, Menaschehs Sohn, ging und eroberte ihre Dörfer und nannte sie Chavoth Jair.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Und Nobach ging und eroberte Kenath und ihre Töchterstädte und nannte sie nach seinem Namen Nobach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'Dies sind die Lagerorte der Söhne Israels, da sie aus Ägyptenland ausgingen, nach ihren Heerscharen unter der Hand des Mose und Aharon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'Und Mose schrieb auf ihre Auszüge nach ihren Lagerorten auf Befehl Jehovahs; und dies sind ihre Lagerorte nach ihren Auszügen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Und sie brachen auf von Ramses im ersten Monat am fünfzehnten Tage des ersten Monats. Am morgenden Tag nach dem Passah zogen die Söhne Israels aus mit erhöhter Hand vor den Augen aller Ägypter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'Und die Ägypter begruben all die Erstgeburt, die Jehovah unter ihnen geschlagen hatte; und an ihren Göttern hatte Jehovah Gerichte geübt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'Und die Söhne Israels brachen von Ramses auf und lagerten in Sukkoth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'Und von Sukkoth brachen sie auf und lagerten in Etham, das am Ende der Wüste ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'Und von Etham brachen sie auf und wandten sich zurück nach Pi Hachiroth, das vor Baal Zephon ist und lagerten vor Migdol.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'Und vor Hachiroth brachen sie auf und zogen mitten durch das Meer nach der Wüste hin und gingen einen Weg von drei Tagen in der Wüste Etham und lagerten in Marah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'Und von Marah brachen sie auf und kamen nach Elim; und in Elim waren zwölf Wasserquellen und siebzig Palmbäume, und sie lagerten daselbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Und sie brachen auf von Elim und lagerten am Schilfmeer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'Und vom Schilfmeer brachen sie auf und lagerten in der Wüste Sin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Und von der Wüste Sin brachen sie auf und lagerten in Dophkah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'Und von Dophkah brachen sie auf und lagerten in Alusch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'Und von Alusch brachen sie auf und lagerten in Rephidim, und daselbst war kein Wasser für das Volk zum Trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'Und sie brachen auf von Rephidim und lagerten sich in der Wüste Sinai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Und aus der Wüste Sinai brachen sie auf und lagerten in Kibroth Thaavah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Und von Kibroth Thaavah brachen sie auf und lagerten in Chazeroth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Und von Chazeroth brachen sie auf und lagerten in Rithmah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Und von Rithmah brachen sie auf und lagerten in Rimmon Parez.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'Und von Rimmon Parez brachen sie auf und lagerten in Libnah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Und von Libnah brachen sie auf und lagerten in Rissah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Und von Rissah brachen sie auf und lagerten in Kehelathah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Und von Kehelathah brachen sie auf und lagerten am Berge Schapher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Und vom Berge Schapher brachen sie auf und lagerten in Charadah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'Und von Charadah brachen sie auf und lagerten sich in Makheloth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Und von Makheloth brachen sie auf und lagerten in Thachath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Und von Thachath brachen sie auf und lagerten in Tharach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Und von Tharach brachen sie auf und lagerten sich in Mithkah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'Und von Mithkah brachen sie auf und lagerten in Chaschmonah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Und von Chaschmonah brachen sie auf und lagerten in Moseroth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Und von Moseroth brachen sie auf und lagerten in Bene Jaakan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Und von Bene Jaakan brachen sie auf und lagerten in Chor Gidgad.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Und von Chor Gidgad brachen sie auf und lagerten in Jotbathah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'Und von Jotbathah brachen sie auf und lagerten in Abronah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Und von Abronah aber brachen sie auf und lagerten in Ezjon Geber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Und von Ezjon Geber brachen sie auf und lagerten in der Wüste Zin, das ist Kadesch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Und sie brachen auf von Kadesch und lagerten am Hor, dem Berge an dem Ende vom Lande Edom.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'Und Aharon, der Priester, stieg auf den Berg Hor nach dem Befehl Jehovahs und starb allda im vierzigsten Jahre des Auszugs der Söhne Israels aus Ägyptenland, im fünften Monat im ersten des Monats.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'Und Aharon war hundertdreiundzwanzig Jahre alt, da er starb auf dem Berge Hor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Und der Kanaaniterkönig Arad, der da wohnte im Mittag im Lande Kanaan, hörte von dem Kommen der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'Und sie brachen auf vom Berge Hor und lagerten in Zalmonah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Und von Zalmonah brachen sie auf und lagerten in Phunon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Und von Phunon brachen sie auf und lagerten in Oboth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'Und von Oboth brachen sie auf und lagerten in Ijim Haabarim, an der Grenze Moabs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'Und von Ijim brachen sie auf und lagerten in Dibon Gad.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Und von Dibon Gad brachen sie auf und lagerten in Almon Diblathaim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Und von Almon Diblathaim brachen sie auf und lagerten in den Bergen Abarim vor Nebo.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Und von den Bergen Abarim brachen sie auf und lagerten in Arboth Moab am Jordan bei Jericho.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'Und sie lagerten am Jordan von Beth Jeschimoth bis Abel Schittim in Moabs Flachland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'Und Jehovah redete zu Mose in dem Flachland Moabs am Jordan bei Jericho und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Rede zu den Söhnen Israels und sprich zu ihnen: Wenn ihr über den Jordan setzet in das Land Kanaan,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'So sollet ihr alle, die im Lande wohnen, vor eurem Angesichte austreiben, und all ihr Gebilde und all ihre gegossenen Bilder sollt ihr zerstören, und alle ihre Opferhöhen vernichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'Und sollt das Land erblich besitzen und darin wohnen: denn euch habe Ich das Land gegeben, es erblich zu besitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'Und nach dem Lose sollt ihr das Land unter euch zum Erbe verteilen nach euren Familien; dem, der viele hat, mehrt sein Erbe, und dem der wenige hat, mindert das Erbe. Wohin das Los ihm ausgeht, das soll das Seinige sein. Nach den Stämmen eurer Väter sollt ihr es zum Erbe unter euch verteilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Und so ihr, die im Lande wohnen, nicht austreibet vor eurem Angesicht, so sollen die, so ihr von ihnen übriglasset, euch zu Dornen in den Augen und zu Stacheln in den Seiten werden und euch bedrängen auf dem Lande, da ihr innen wohnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'Und es wird geschehen, daß, wie Ich ihnen zu tun gesonnen war, Ich euch tun werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Gebiete den Söhnen Israels und sprich zu ihnen: So ihr in das Land Kanaan kommet, so sei das das Land, das euch zum Erbe fällt, das Land Kanaan nach seinen Grenzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Und die Ecke im Mittag soll euch sein von der Wüste Zin an bei der Seite Edom, eure Mittagsgrenze soll sein vom Ende des Salzmeeres nach Osten zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'Und es wendet sich euch die Grenze herum mittäglich von Maaleh Akkrabin und zieht sich nach Zin hinüber; und ihre Ausgänge seien mittäglich von Kadesch Barnea und gehen aus nach Chazar Addar und ziehen sich hinüber nach Azmon;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'Und von Azmon wende sich die Grenze herum nach dem Bache Ägyptens, und ihre Ausgänge seien nach dem Meere hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Und die Grenze nach dem Meere zu soll euch sein das große Meer und seine Grenze. Dies soll euch die Grenze nach dem Meere zu sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'Und die Grenze nach Mitternacht soll euch diese sein: Von dem großen Meere sollt ihr euch abmessen bis zum Berge Hor;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'Vom Berge Hor sollt ihr abmessen bis man gen Hamath kommt, und sollen sein die Ausgänge der Grenze bis nach Zedad hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'Und die Grenze gehe dann aus gen Siphron und ihre Ausgänge seien Chazar Enan. Dies soll euch die Grenze nach Mitternacht sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Und messet ab für euch als Grenze gegen Osten von Chazar Enan bis Schepham.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'Und die Grenze gehe hinab von Schepham nach Riblah östlich von Ain und die Grenze gehe hinab und stoße auf das Ufer des Meeres Kinnereth gegen den Osten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'Und die Grenze gehe hinab nach dem Jordan und ihre Ausgänge seien das Salzmeer. Das sei euch das Land nach seinen Grenzen ringsumher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Und Mose gebot den Söhnen Israels und sprach: Dies ist das Land, das ihr unter euch durch das Los zum Erbe verteilen sollt, das Jehovah gebot zu geben den neun Stämmen und dem halben Stamm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Denn es haben genommen der Stamm der Söhne des Rubeniten nach dem Hause ihrer Väter und der Stamm der Söhne des Gaditen nach dem Hause ihrer Väter und der halbe Stamm Menaschehs - sie haben ihr Erbe genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Die zwei Stämme und der halbe Stamm haben ihr Erbe genommen diesseits des Jordans bei Jericho auf der Ostseite gegen den Aufgang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Das sind die Namen der Männer, welche euch das Land zum Erbe verteilen sollen: Eleasar, der Priester, und Jehoschua, der Sohn Nuns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'Und je einen Fürsten von dem Stamme sollt ihr nehmen, das Land als Erbe zu verteilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'Und das sind die Namen der Männer: Vom Stamme Judah Kaleb, der Sohn Jephunnehs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'Und vom Stamme der Söhne Schimeons Schemuel, Sohn Ammihuds.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'Vom Stamme Benjamins Elidad, der Sohn Chislons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'Und vom Stamme der Söhne Dans ein Fürst, Bukki, Joglis Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'Für die Söhne Josephs vom Stamme der Söhne Menaschehs ein Fürst, Hanniel, Ephods Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'Und vom Stamme der Söhne Ephraims ein Fürst, Kemuel, ein Sohn Schiphtans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'Und vom Stamme der Söhne Sebuluns ein Fürst, Elizaphan, Parnachs Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'Und vom Stamme der Söhne Issaschars ein Fürst, Paltiel, Assans Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'Und vom Stamme der Söhne Aschers, ein Fürst, Achihud, Schelomis Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'Und vom Stamme der Söhne Naphthalis ein Fürst, Pedahel, der Sohn Ammihuds.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'Diese sind es, denen Jehovah gebot, den Söhnen Israels das Erbe zu verteilen im Lande Kanaan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'Und Jehovah redete zu Mose im Flachland Moabs am Jordan bei Jericho und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Gebiete den Söhnen Israels, sie sollen den Leviten von dem Erbe ihres Eigentums Städte zum Wohnen geben: und ein Weichbild für die Städte rings um sie her sollt ihr den Leviten geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'Und die Städte sollen sie haben zum Wohnen, und ihre Weichbilder sollen sie haben für ihr Vieh und ihre Habe und für all ihre anderen Tiere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Und die Weichbilder der Städte, die ihr den Leviten geben sollt, sollen von der Mauer der Stadt ringsum auswärts tausend Ellen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Und ihr sollt außerhalb der Stadt messen die Seite gegen Osten zweitausend nach der Elle, und die Seite gegen Mittag zweitausend nach der Elle, und die Seite nach dem Meere zu zweitausend nach der Elle, und die Seite gegen Mitternacht zweitausend nach der Elle, und die Stadt in der Mitte. Das soll ihnen das Weichbild der Städte sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Und die Städte, die ihr den Leviten geben sollet, sollen sein die sechs Freistädte, die ihr gebet, daß dahin fliehe der Totschläger; und außer denselben sollt ihr zweiundvierzig Städte geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Alle die Städte, die ihr den Leviten geben sollt, sollen achtundvierzig Städte sein, sie selbst und ihre Weichbilder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Und die Städte, die ihr von dem Eigentum der Söhne Israels gebet, sollt ihr von dem, der viel hat, viel, und von dem, der wenig hat, wenig nehmen. Jeder Mann soll nach Verhältnis seines Erbes, das er ererbte, von seinen Städten an die Leviten geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'Und Jehovah redete zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Rede zu den Söhnen Israels und sprich zu ihnen: Wenn ihr über den Jordan in das Land Kanaan setzet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'So leset euch Städte aus, die Freistädte für euch sein sollen, daß dahin fliehe ein Totschläger, der jemand aus Versehen erschlagen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'Und die Städte sollen euch zur Freistätte sein vor dem Bluträcher, auf daß der Totschläger nicht sterbe, bis er vor der Gemeinde zu Gericht gestanden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Und die Städte, die ihr geben sollt, sollen sechs Freistädte für euch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Drei der Städte sollt ihr diesseits des Jordans geben und drei Städte sollt ihr geben im Lande Kanaan; Freistädte sollen sie sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Für die Söhne Israels und für den Fremdling und den Beisaßen in ihrer Mitte sollen diese sechs Freistädte sein, daß dahin fliehe ein jeder, der jemand aus Versehen erschlagen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Und wenn einer mit einem eisernen Gerät ihn geschlagen hat und er stirbt, der ist ein Mörder: Und der Mörder soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'Und hat er ihn mit einem Stein der Hand, wovon man sterben kann, geschlagen, und er starb, so ist er ein Mörder: Der Mörder soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Oder hat er ihn mit einem hölzernen Gerät der Hand, davon man sterben kann, geschlagen, und er starb, so ist er ein Mörder: Der Mörder soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Der Bluträcher töte den Mörder. Wo er auf ihn stößt, soll er ihn töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Und hat er ihn aus Haß gestoßen, oder durch Nachstellung auf ihn geworfen, und er starb,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'Oder hat er ihn aus Feindschaft mit seiner Hand geschlagen, und er starb, so soll der Schläger des Todes sterben, er ist ein Mörder. Der Bluträcher soll den Mörder töten, wo er auf ihn stößt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Stößt er ihn aber unversehens ohne Feindschaft, oder wirft er auf ihn irgend etwas, ohne Nachstellung,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'Oder trifft ihn mit irgendeinem Stein, der ihn töten kann ohne daß er es sieht, und er fällt auf ihn, und er stirbt; er war ihm aber nicht feind und suchte nicht sein Übel,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'So soll die Gemeinde richten zwischen dem, der geschlagen hat und dem Bluträcher nach diesen Rechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'Und die Gemeinde errette den Totschläger aus der Hand des Bluträchers, und die Gemeinde bringe ihn zurück zur Freistadt, wohin er geflohen war, und er wohne darin bis zum Tode des Hohenpriesters, den man mit heiligem Öle gesalbt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Geht aber der Totschläger heraus über die Grenze der Freistadt, dahin er geflohen ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'Und findet ihn der Bluträcher außerhalb der Grenze der Freistadt, und schlägt der Bluträcher den Totschläger zu Tode, so hat er keine Blutschuld.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'Denn in der Freistadt soll er wohnen bis zum Tod des Hohenpriesters; nach des Hohenpriesters Tod aber mag der Totschläger in sein Landeseigentum zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'Und dies soll Satzung des Rechtes für euch sein bei euren Geschlechtern in allen euren Wohnsitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Wenn irgendeiner jemand erschlägt, soll man den Totschläger totschlagen nach dem Munde von Zeugen. Ein Zeuge aber kann nicht aussagen wider eine Seele, so daß sie sterbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Und ihr sollt keine Sühne für die Seele eines Mörders nehmen, der des Todes schuldig ist; sondern er soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Und ihr sollt keine Sühne nehmen von dem, der in die Freistadt geflohen, daß er zurückkehrete, im Lande zu wohnen, vor dem Tode des Priesters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Auf daß ihr das Land, darin ihr seid, nicht entheiliget; denn das Blut ist es, welches das Land entheiligt, und das Land wird nicht gesühnt für das Blut, das in ihm vergossen worden, außer durch das Blut dessen, der es vergossen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Und du sollst nicht verunreinigen das Land, in dem ihr wohnet, in dessen Mitte Ich Selbst wohne; denn Ich, Jehovah, wohne inmitten der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'Und es nahten die Häupter der Väter der Familie der Söhne Gileads, des Sohnes Machirs, des Sohnes Menaschehs, von den Familien der Söhne Josephs, und sie redeten vor Mose und vor den Fürsten, den Häuptern der Väter der Söhne Israels,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'Und sie sprachen: Meinem Herrn hat Jehovah geboten, das Land den Söhnen Israels durch das Los zum Erbe zu geben; und meinem Herrn ward geboten von Jehovah, das Erbe unseres Bruders Zelaphechad seinen Töchtern zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Werden sie nun einem von den Söhnen der Stämme der Söhne Israels zu Weibern, da wird ihr Erbe von dem Erbe unserer Väter weggenommen und dem Erbe des Stammes, in dem sie dann sind, hinzugetan, und von dem Los unseres Erbes weggenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'Und wenn nun das Jubeljahr der Söhne Israels ist, so wird ihr Erbe zum Erbe des Stammes, in dem sie sind, hinzugetan und vom Erbe des Stammes unserer Väter wird ihr Erbe weggenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Und Mose gebot den Söhnen Israels nach dem Munde Jehovahs und sprach: Der Stamm der Söhne Josephs hat recht geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'Das ist das Wort, das Jehovah den Töchtern Zelaphechads gebietet und spricht: Sie mögen denen, die in ihren Augen gut sind, zu Weibern werden; nur daß sie denen zu Weibern werden, die aus der Familie des Stammes ihres Vaters sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'Auf daß nicht ein Erbe der Söhne Israels von Stamm zu Stamm herumziehe, denn es soll jeder Mann der Söhne Israels dem Erbe vom Stamme seiner Väter anhangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Und jede Tochter, die ein Erbe von den Stämmen der Söhne Israels erblich besitzt, soll nur einem aus der Familie von ihres Vaters Stamm zum Weibe werden, auf daß jeder Mann von den Söhnen Israels das Erbe seiner Väter erblich besitze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'Und nicht ein Erbe von einem Stamm zu einem anderen Stamm umherziehe, sondern jeder Mann der Stämme der Söhne Israels seinem Erbe anhange.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Wie Jehovah Mose geboten hatte, so taten die Töchter Zelaphechads;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'Und Machlah, Thirzah und Choglah und Milkah und Noah, Zelaphechads Töchter, wurden den Söhnen ihrer Oheime zu Weibern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Aus den Familien der Söhne Menaschehs, des Sohnes Josephs, wurden sie zu Weibern genommen, und ihr Erbe wurde dem Stamme der Familie ihres Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'Das sind die Gebote und Rechte, die Jehovah im Flachland Moabs am Jordan bei Jericho den Söhnen Israels durch Moses Hand geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'Dies sind die Worte, welche Mose redete zu dem ganzen Israel jenseits des Jordans in der Wüste, in dem Flachlande, Suph gegenüber, zwischen Paran und zwischen Tophel und Laban und Chazeroth und Di-Sahab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Elf Tage sind es von Choreb auf dem Wege nach dem Gebirge Seir bis Kadesch Barnea.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'Und es geschah im vierzigsten Jahre, im elften Monat, am ersten des Monats, daß Mose redete zu den Söhnen Israels nach alle dem, was Jehovah ihm an sie geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'Nachdem er Sichon geschlagen, den König der Amoriter, der in Cheschbon wohnte, und Og, den König von Baschan, der in Aschtaroth bei Edrei wohnte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Jenseits des Jordans im Lande Moab begann Mose dieses Gesetz zu erklären und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Jehovah, unser Gott, redete zu uns auf Choreb und sprach: Ihr habt viel auf diesem Berge gewohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'Wendet euch und brechet auf und kommt zum Gebirge der Amoriter und zu allen ihren Nachbarn, in dem Flachland, auf dem Gebirge und in der Niederung und im Mittag und am Gestade des Meeres, in das Land der Kanaaniter und zum Libanon bis zum großen Flusse, dem Flusse Euphrat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Siehe, Ich habe das Land vor euer Angesicht gegeben; kommet und nehmet ein das Land, das Jehovah geschworen euren Vätern, dem Abraham, dem Isaak und dem Jakob, ihnen und ihrem Samen nach ihnen zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'Und ich sagte zu jener Zeit zu euch und sprach: Ich allein vermag euch nicht zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Jehovah, euer Gott, hat euch gemehret, und siehe, ihr seid diesen Tag wie die Sterne am Himmel an Menge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Jehovah, der Gott eurer Väter, möge dazutun zu euch noch tausendmal mehr, als ihr seid, und segne euch, wie Er zu euch geredet hat!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Aber wie kann ich eure Bürde und eure Last und euren Hader allein tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Gebt für euch weise und einsichtsvolle und euren Stämmen bekannte Männer, auf daß ich sie euch zu Häuptern setze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'Und ihr antwortetet mir und spracht: Das Wort ist gut, das du geredet; man tue es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Und ich nahm die Häupter eurer Stämme, weise und bekannte Männer, und gab sie zu Häuptern über euch; zu Obersten von Tausenden und zu Obersten von Hunderten und zu Obersten von Fünfzig und zu Obersten von Zehn und zu Vorstehern für eure Stämme;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'Und gebot euren Richtern zur selbigen Zeit und sprach: Höret zwischen euren Brüdern und richtet gerecht zwischen dem Mann und zwischen seinem Bruder und zwischen dem Fremdling.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Ihr sollt nicht die Angesichter ansehen im Gericht. Den Kleinen wie den Großen sollt ihr hören; laßt euch nicht bangen vor dem Angesicht eines Mannes, denn das Richten ist Gottes. Ist euch eine Sache zu hart, so bringet sie vor mich dar, daß ich sie höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'Und ich gebot euch zur selben Zeit alle die Worte, die ihr tun sollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Und wir brachen auf vom Choreb und zogen durch diese ganze so große und furchtbare Wüste, die ihr gesehen auf dem Weg zum Gebirge der Amoriter, wie Jehovah, unser Gott, uns geboten, und kamen bis Kadesch Barnea.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Und ich sprach zu euch: Ihr seid an das Gebirge des Amoriters gekommen, das Jehovah, unser Gott, uns gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Siehe, Jehovah, dein Gott, hat das Land vor dich hingegeben. Ziehe hinauf und nimm es ein, wie Jehovah, deiner Väter Gott, zu dir geredet hat. Fürchte dich nicht und entsetze dich nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Und ihr nahtet allesamt zu mir und sprachet: Laß uns Männer vor uns hersenden, daß sie uns das Land ausforschen und uns Bescheid zurückbringen über den Weg, auf dem wir hinaufziehen, und die Städte, an die wir kommen sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'Und das Wort war gut in meinen Augen, und ich nahm aus euch zwölf Männer, einen Mann auf den Stamm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Und sie wandten sich und gingen das Gebirge hinauf und kamen bis zum Bachtal Eschkol und kundschafteten es aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'Und sie nahmen in ihre Hand von der Frucht des Landes und brachten sie herab zu uns und brachten uns Wort zurück und sprachen: Gut ist das Land, das Jehovah, unser Gott, uns geben will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Aber ihr wolltet nicht hinaufziehen und waret widerspenstig dem Munde Jehovahs, eures Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'Und ihr beschwertet euch in euren Zelten und sprachet: Aus Haß hat Jehovah uns aus Ägyptenland ausgeführt, um uns in die Hand der Amoriter zu geben, uns zu vernichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Wo sollen wir hinaufziehen? Unsere Brüder haben unser Herz zerfließen gemacht, als sie sagten: Größer und höher denn wir ist dies Volk; ihre Städte sind groß und bis in den Himmel befestigt, und wir haben auch Enaks Söhne dort gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Und ich sprach zu euch: Laßt euch nicht grauen und fürchtet euch nicht vor ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Jehovah, euer Gott, Der vor euch herzieht, Er wird für euch streiten, wie in allem, was Er mit euch tat in Ägypten vor euren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'Und in der Wüste, wo du gesehen hast, wie Jehovah, dein Gott, dich trug, wie ein Mann trägt seinen Sohn, auf dem ganzen Weg, den ihr ginget, bis ihr an diesen Ort kamet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'Und trotz diesem Worte glaubtet ihr nicht an Jehovah, euren Gott,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'Der vor euch herzog auf dem Wege, um euch den Ort auszuspähen, wo ihr lagern solltet durch das Feuer bei Nacht, auf daß ihr sehet auf dem Weg, auf dem ihr gehen solltet, und in der Wolke am Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Und Jehovah hörte die Stimme eurer Worte und war entrüstet, und schwor und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Es soll kein Mann dieser Männer, von diesem bösen Geschlecht das gute Land sehen, das Ich euren Vätern zu geben geschworen hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'Außer Kaleb, Jephunnehs Sohn. Er soll es sehen, und ihm will Ich das Land geben, das er betreten hatte, und seinen Söhnen, dafür, daß er vollständig Jehovah nachgefolgt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Auch über mich zürnte Jehovah euretwegen und sprach: Auch du sollst nicht dahin kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Jehoschua, der Sohn Nuns, der vor dir steht, er soll dahin kommen; ihn stärke; denn er soll es Israel zum Erbe verteilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Und eure Kindlein, von denen ihr sagtet: Sie werden zum Raube werden; und eure Söhne, die diesen Tag nicht wissen, was gut oder böse ist; sie sollen dahin kommen, und ihnen will Ich es geben, und sie sollen es erblich besitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Ihr aber, wendet euch ab und brechet auf nach der Wüste auf dem Weg dem Schilfmeere zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Und ihr antwortetet und sprachet zu mir: Wir haben gesündigt wider Jehovah, wir wollen hinaufziehen und streiten gemäß allem, das Jehovah, unser Gott, uns geboten hat. Und jeder Mann gürtete sich mit seinen Kriegswaffen und waret dafür, auf das Gebirge hinaufzuziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Und Jehovah sprach zu mir: Sprich zu ihnen: Ziehet nicht hinauf und streitet nicht, denn Ich bin nicht in eurer Mitte, auf daß ihr nicht geschlagen werdet vor euren Feinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'Und ich redete zu euch; ihr aber hörtet nicht, und waret widerspenstig gegen Jehovahs Mund, und waret vermessen und zoget hinauf auf das Gebirge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Und der Amoriter, der auf diesem Gebirge wohnte, ging aus, euch entgegen; und sie setzten euch nach, wie die Bienen tun, und zerstießen euch von Seir bis Chormah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'Und ihr kehrtet zurück und weintet vor Jehovah; Jehovah hörte aber nicht auf eure Stimme und gab euch kein Gehör.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Und ihr wohntet in Kadesch viele Tage, gemäß den Tagen eures Wohnens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Und wir wandten uns und brachen auf nach der Wüste auf dem Wege nach dem Schilfmeer, wie Jehovah zu mir redete, und umzogen das Gebirge Seir viele Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Und Jehovah sprach zu mir und Er sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Es ist viel für euch, das Gebirge zu umziehen; wendet euch gegen Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Und dem Volke gebiete und sprich: Ihr durchziehet nun die Grenze eurer Brüder, der Söhne Esau, die in Seir wohnen, und sie fürchten euch. Hütet euch aber sehr!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'Hebe nicht Streit an mit ihnen, denn keinen fußbreit von ihrem Land werde Ich euch geben, denn das Gebirge Seir habe Ich Esau zum Erbbesitz gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Speise sollt ihr um Silber von ihnen kaufen, auf daß ihr esset, und auch das Wasser sollt ihr um Silber von ihnen einkaufen und trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Denn Jehovah, dein Gott, hat dich gesegnet in allem Tun deiner Hand; Er wußte um dein Ziehen in dieser großen Wüste. Die vierzig Jahre war Jehovah, dein Gott, mit dir, und es mangelte dir an nichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Und wir zogen vorüber an unseren Brüdern, den Söhnen Esaus, die auf Seir wohnen, ab von dem Wege durch das Flachland, von Elath und von Ezion Geber, und wandten uns und zogen hin auf dem Wege nach der Wüste Moab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'Und Jehovah sprach zu mir: Bedränge nicht Moab und hebe nicht Streit an mit ihnen, denn Ich will dir nichts von seinem Land zum Erbbesitz geben, weil Ich den Söhnen Lots Ar zum Erbbesitz gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, 'Die Emim hatten vordem darin gewohnt, ein Volk, groß und viel und hoch, wie die Enakim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Auch sie wurden, wie die Enakim, unter die Riesen gerechnet, die Moabiter aber nannten sie Emim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'In Seir aber hatten vordem die Choriter gewohnt; und die Söhne Esaus trieben sie aus und vernichteten sie vor sich her, und wohnten an ihrer Statt, wie Israel mit dem Lande seines Erbbesitzes tat, das Jehovah ihnen gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Nun machet euch auf und setzet über den Bach Sered. Und wir setzten über den Bach Sered.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Und die Tage, in denen wir von Kadesch Barnea zogen, bis daß wir über den Bach Sered setzten, waren achtunddreißig Jahre, bis das ganze Geschlecht der Kriegsleute aus der Mitte des Lagers alle ward, wie Jehovah ihnen geschworen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Und auch die Hand Jehovahs war wider sie, auf daß Er sie aus der Mitte des Lagers austilgte, bis sie alle wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'Und es geschah, als alle Kriegsleute aus der Mitte des Volkes alle waren, daß sie gestorben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'Daß Jehovah zu mir redete und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Du setzest heute über Moabs Grenze, an Ar vorbei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'Und wirst nahe kommen gegenüber den Söhnen Ammons. Bedränge sie nicht und hebe nicht Streit an mit ihnen, denn Ich werde dir nichts vom Lande der Söhne Ammon zum Erbbesitze geben, denn Ich gab es den Söhnen Lots zum Erbbesitz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, 'Als ein Land von Riesen ward auch dieses gerechnet, Riesen wohnten vordem darinnen; und die Ammoniter nannten sie Samsummim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'Ein Volk war es, groß und viel und hoch, wie die Enakim; aber Jehovah vernichtete sie vor ihnen und trieb sie aus und sie wohnten an ihrer Statt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'Wie Er getan hatte für die Söhne Esaus, die da wohnen in Seir, vor denen Er die Choriter vernichtete und sie austrieb; und sie wohnten an ihrer Statt bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'Und die Avim, die in Dörfern wohnten bis Gazah, die Kaphthorim, die von Kaphthor ausgingen, vernichteten sie; und sie wohnten an ihrer Statt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Machet euch auf, brechet auf und setzet über den Bach Arnon. Siehe, Ich habe Sichon, den König von Cheschbon, den Amoriter und sein Land in deine Hand gegeben. Fang an, nimm es ein, hebe Streit an mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Diesen Tag will Ich anfangen zu geben Schauer und Furcht vor dir über die Völker unter dem ganzen Himmel, und sie werden zittern und beben vor deinem Angesicht, wenn sie das Gerücht von dir hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Und ich sandte Boten aus der Wüste Kedemoth an Sichon, den König von Cheschbon, mit Worten des Friedens und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Ich will dein Land durchziehen, will nur auf dem Wege gehen, weder zur Rechten, noch zur Linken abweichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Speise sollst du mir um Silber verkaufen, daß ich esse, und Wasser mir geben um Silber, daß ich trinke. Nur laß mich durchziehen zu Fuß;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'Wie mir Esaus Söhne taten, die da wohnen in Seir, und die Moabiter, die da wohnen in Ar, bis daß ich über den Jordan übersetze in das Land, das Jehovah, unser Gott, uns gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Und Sichon, Cheschbons König, war nicht willens, uns da durchziehen zu lassen, weil Jehovah, dein Gott, seinen Geist verhärtete und sein Herz verstockte, auf daß Er ihn in deine Hand gebe, wie es heutzutage ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'Und Jehovah sprach zu mir: Siehe, Ich habe angefangen, Sichon und sein Land vor dir zu geben. Fange an, nimm ein, um sein Land einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'Und Sichon ging aus, uns entgegen, er und all sein Volk zum Streite nach Jahza.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'Und Jehovah, unser Gott, gab ihn vor uns, und wir schlugen ihn und seine Söhne und all sein Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'Und wir eroberten zu selbiger Zeit alle seine Städte und bannten in jeder Stadt Männer, Weiber und Kindlein und ließen keinen Rest verbleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'Nur das Vieh raubten wir für uns und die Beute der Städte, die wir eroberten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Von Aroer an, das am Ufer des Baches Arnon, und die Stadt, die in dem Bachtale liegt, und bis Gilead war keine Stadt zu erhaben für uns; alle gab Jehovah vor uns hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Nur dem Land der Söhne Ammons bist du nicht nahe gekommen, allem, das am Ufer des Baches Jabboks ist, noch den Städten auf dem Gebirge, noch irgend etwas, das Jehovah, unser Gott, verboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Und wir wandten uns und zogen hinauf den Weg nach Baschan; und Og, der König von Baschan, ging aus, uns entgegen, er und all sein Volk, zum Streite bei Edrei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Und Jehovah sprach zu mir: Fürchte ihn nicht, denn Ich habe ihn und all sein Volk und sein Land in deine Hand gegeben; und tue ihm, wie du Sichon, dem Amoriterkönig, der in Cheschbon wohnte, getan hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Und Jehovah, unser Gott, gab auch Og, den König von Baschan, und all sein Volk in unsre Hand, und wir schlugen ihn, bis kein Rest verblieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Und wir eroberten zur selben Zeit alle seine Städte; da war keine Stadt, die wir ihnen nicht nahmen, sechzig Städte, den ganzen Landstrich von Argob, das Königreich Ogs in Baschan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Alle diese Städte waren fest mit hohen Mauern, mit Flügeltoren und Riegeln, außer den sehr vielen nicht ummauerten Städten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'Und wir bannten sie, wie wir Sichon, dem König von Cheschbon taten, alle Städte mit Männern, Weibern und Kindlein wurden gebannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Und alles Vieh und die Beute der Städte raubten wir für uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Und wir nahmen zur selben Zeit das Land aus der Hand der zwei Könige der Amoriter, diesseits des Jordans, vom Bache Arnon bis zum Berge Chermon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, 'Die Zidonier nennen den Chermon Sirion, und die Amoriter nennen ihn Senir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'Alle Städte der Ebene und ganz Gilead und ganz Baschan bis Salcha und Edrei, Städte des Königsreiches Ogs in Baschan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, 'Denn Og, König von Baschan, verblieb allein von den Übriggebliebenen der Rephaim. Siehe, sein Ruhebett, ein Ruhebett von Eisen, ist es nicht in Rabbath der Söhne Ammons? Neun Ellen ist seine Länge und vier Ellen seine Breite nach dem Mannes- Ellenbogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'Und dieses Land haben wir zur selben Zeit eingenommen, von Aroer an, das am Bache Arnon ist; und die Hälfte des Berges Gilead und dessen Städte habe ich dem Rubeniter und dem Gaditer gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Und das übrige Gilead und ganz Baschan, Ogs Königreich, gab ich dem halben Stamme Menascheh, den ganzen Landstrich von Argob, samt dem ganzen Baschan; es heißt das Land der Rephaim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, Menaschehs Sohn, nahm den ganzen Landstrich Argob bis an die Grenze der Gaschuriter und der Maachathiter, und nannte Baschan nach seinem Namen die Dörfer Jairs bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Und dem Machir gab ich Gilead.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'Und dem Rubeniter und dem Gaditer gab ich von Gilead und bis an den Bach Arnon, zur Mitte des Baches als Grenze, und bis zum Bache Jabbok, der Grenze der Söhne Ammons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'Und das Flachland und den Jordan als Grenze. Vom Kinnereth und bis zum Meer des Flachlandes, zum Salzmeer unter den Abhängen des Pisgah dem Aufgang zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'Und ich gebot euch zur selben Zeit und sprach: Jehovah, euer Gott, hat euch dieses Land gegeben zum Erbbesitz. Ausgerüstet sollt ihr vor euren Brüdern, den Söhnen Israels, hinüberziehen, alle tapferen Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Nur eure Weiber und eure Kindlein und eure Viehherden - ich weiß, ihr habt viel Viehherden - sollen in euren Städten bleiben, die ich euch gegeben habe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'Bis Jehovah eure Brüder wie euch zur Ruhe gebracht, und auch sie das Land einnehmen, das Jehovah, euer Gott, ihnen jenseits des Jordans geben wird. Und ihr kehret, jeder Mann, zu seinem Erbbesitz zurück, das ich euch gegeben habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'Und dem Jehoschua habe ich zur selben Zeit geboten und gesagt: Deine Augen haben gesehen alles, was Jehovah, euer Gott, diesen zwei Königen getan hat. So wird Jehovah allen den Königreichen tun, in die du hinüberziehen wirst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Fürchtet sie nicht; denn Jehovah, euer Gott, Er streitet für euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Und ich flehte zur selben Zeit zu Jehovah und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'O Herr, Jehovah, Du hast angefangen, Deinem Knechte Deine Größe und Deine starke Hand zu zeigen; denn welcher Gott im Himmel und auf Erden kann Deine Taten und nach Deiner Macht tun!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Laß mich doch hinüberziehen und sehen das gute Land, das jenseits des Jordans ist! dies gute Gebirge und den Libanon!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Aber Jehovah wütete gegen mich um euretwillen und hörte nicht auf mich. Und Jehovah sprach zu mir: Dir ist viel geworden. Rede zu Mir nicht weiter von dieser Sache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Steige auf die Spitze des Pisgah und erhebe deine Augen dem Meere zu und nach Mitternacht, und nach Süden und gegen Aufgang, und siehe mit deinen Augen; denn du sollst nicht über diesen Jordan übersetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Gebiete aber Jehoschua, stärke ihn und mache ihn rüstig; denn er soll vor diesem Volke hinüberziehen und ihnen das Land zum Erbe verteilen, das du sehen wirst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Wir aber blieben in dem Tale, Beth Peor gegenüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Und nun höre, Israel, auf die Satzungen und auf die Rechte, welche ich euch lehre zu tun, auf daß ihr lebet und hineinkommet und einnehmet das Land, das euch Jehovah, der Gott eurer Väter, geben wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ihr sollt nicht dazutun zu dem Worte, das Ich euch gebiete, noch sollt ihr etwas davon wegnehmen, auf daß ihr haltet die Gebote Jehovahs, eures Gottes, die ich euch gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Eure Augen haben gesehen, was Jehovah getan hat in Baal-Peor; denn jeden Mann, der dem Baal-Peor nachging, hat Jehovah, dein Gott, aus deiner Mitte vernichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Ihr aber, die ihr Jehovah, eurem Gotte, anhinget, seid diesen Tag noch alle am Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Siehe, ich habe euch Satzungen und Rechte gelehrt, wie mir Jehovah, mein Gott, geboten hat, daß ihr danach tut inmitten des Landes, dahin ihr kommen werdet, es einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Haltet aber und tut sie. Denn das sei eure Weisheit und eure Einsicht vor den Augen der Völker, wenn sie hören werden alle diese Satzungen und sagen: Nur ein weises und einsichtsvolles Volk ist diese große Völkerschaft!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Denn wo ist eine Völkerschaft so groß, dem Gott nahe ist, wie Jehovah, unser Gott, so oft wir zu Ihm rufen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'Und wo ist eine Völkerschaft so groß, die so gerechte Satzungen und Rechte hätte, wie dies ganze Gesetz, das ich diesen Tag vor euch gebe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Nur hüte dich, und hüte deine Seele sehr, daß du nicht vergissest die Dinge, die deine Augen gesehen haben, auf daß sie alle Tage deines Lebens nicht aus deinem Herzen weichen, und sollst sie deine Söhne und die Söhne deiner Söhne wissen lassen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'Den Tag, da du standest vor Jehovah, deinem Gott, am Choreb, da Jehovah zu mir sprach: Versammle Mir das Volk, daß Ich sie hören lasse Meine Worte, die sie lernen sollen, Mich zu fürchten alle Tage, die sie auf dem Boden leben, und daß sie ihre Söhne lehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Und ihr nahtet hinzu und standet unten am Berg, und der Berg brannte im Feuer bis in das Herz der Himmel. Da war Finsternis, eine Wolke und Wolkendunkel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'Und Jehovah redete zu euch mitten aus dem Feuer. Die Stimme der Worte hörtet ihr; aber ein Abbild sahet ihr nicht, nur eine Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'Und Er sagte euch an Seinen Bund, den Er euch gebot zu tun, die Zehn Worte, und schrieb sie auf zwei steinerne Tafeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Und mir gebot Jehovah zur selben Zeit, euch zu lehren Satzungen und Rechte, daß ihr sie tun solltet in dem Lande, in das ihr überziehen würdet, um es einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Hütet euch aber sehr für eure Seelen, denn ihr habt kein Abbild gesehen am Tage, da Jehovah auf Choreb mitten aus dem Feuer zu euch redete;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'Auf daß ihr es nicht verderbt und euch kein Schnitzbild machet, ein Abbild irgendeiner Form nach dem männlichen oder weiblichen Vorbild;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'Das Vorbild irgendeines Viehs, das auf Erden ist, das Vorbild irgendeines geflügelten Vogels, das am Himmel fliegt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'Das Vorbild irgendeines Kriechtieres auf dem Boden, das Vorbild irgendeines Fisches, der im Wasser unter der Erde ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'Und daß du nicht deine Augen zum Himmel erhebest und die Sonne, und den Mond und die Sterne sehest, all das Heer des Himmels, und du irre gehst und sie anbetest und ihnen dienst, die Jehovah, dein Gott, allen Völkern unter allen Himmeln zugeteilt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Euch aber hat Jehovah genommen und euch aus dem Schmelzofen des Eisens, aus Ägypten ausgeführt, auf daß ihr Ihm zum Erbvolke werdet, wie an diesem Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'Aber Jehovah zürnte mir euretwegen, und schwur, daß ich nicht sollte über den Jordan setzen, und daß ich nicht kommen solle zum guten Land, das Jehovah, dein Gott, dir zum Erbe gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'Denn ich sterbe in diesem Land, ich werde nicht über den Jordan setzen; ihr aber setzet über und nehmet dies gute Land ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Hütet euch, daß ihr nicht vergesset den Bund Jehovahs, eures Gottes, den Er mit euch geschlossen hat, so ihr euch machtet ein Schnitzbild, in dem Abbild von irgend etwas, das euch Jehovah, euer Gott, verboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Denn Jehovah, dein Gott, ist ein fressendes Feuer, ein eifernder Gott;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Wenn du zeugst Söhne und Söhne der Söhne, und ihr alt geworden seid im Lande, und ihr verderbt euch, so daß ihr ein Schnitzbild in dem Abbild von irgend etwas machet, und tut, was übel ist in den Augen Jehovahs, eures Gottes, so daß ihr Ihn reizet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'So nehme ich heute Himmel und Erde zu Zeugen wider euch, daß ihr eilends umkommt aus dem Lande weg, in das ihr über den Jordan übersetzt, um es einzunehmen; nicht sollet ihr eure Tage darin verlängern, weil ihr vernichtet werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'Und zerstreuen wird euch Jehovah unter die Völker, und wird euer eine geringe Zahl bleiben unter den Völkerschaften, dahin euch Jehovah treiben läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'Und dort werdet ihr Göttern dienen, die von Menschenhänden gemacht sind, Holz und Stein, die nicht sehen und nicht hören und nicht essen und nicht riechen können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Und von dort werdet ihr nach Jehovah, deinem Gott, suchen und du wirst Ihn finden, wenn du nach Ihm suchst von deinem ganzen Herzen und von deiner ganzen Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'In deiner Drangsal und wenn dich alle diese Dinge treffen, in den späteren Tagen wirst du zurückkehren zu Jehovah, deinem Gott und wirst auf seine Stimme hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Weil Jehovah, dein Gott, ein erbarmungsvoller Gott ist, wird Er nicht von dir ablassen noch dich verderben, und wird nicht vergessen den Bund mit deinen Vätern, den Er ihnen geschworen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Dann frage doch nach den früheren Tagen, die vor dir gewesen, seit dem Tage, da Gott den Menschen auf der Erde geschaffen, und von einem Ende des Himmels bis zum anderen Ende des Himmels, ob je so Großes geschehen oder gehört worden ist, wie dies?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Hat je ein Volk die Stimme Gottes mitten aus dem Feuer reden gehört, wie du gehört hast, und ist am Leben geblieben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Oder hat Gott jemals versucht, hinzugehen und Sich eine Völkerschaft mitten aus einer Völkerschaft herauszunehmen mit Versuchungen, mit Zeichen und mit Wahrzeichen, und mit Streit und mit starker Hand und mit ausgestrecktem Arm, und mit großen, furchtbaren Taten, wie das alles Jehovah, euer Gott, für euch vor euren Augen in Ägypten getan hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Du hast es gesehen, damit du wissest, daß Jehovah der Gott ist, und daß keiner recht ist außer Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Aus dem Himmel ließ Er dich Seine Stimme hören, um dich zu belehren, und auf Erden ließ Er dich Sein großes Feuer sehen, und Seine Worte hast du gehört mitten aus dem Feuer!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'Und darum, daß Er deine Väter liebte, und ihren Samen nach ihnen erwählte, und dich mit Seinem Angesichte mit Seiner großen Kraft aus Ägypten ausführte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'Um größere und gewaltigere Völkerschaften, als du bist, vor dir auszutreiben, um dich hineinzuführen und dir ihr Land zum Erbe zu geben, wie an diesem Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Und du sollst an diesem Tag wissen, und dir ins Herz zurückbringen, daß Jehovah der Gott ist im Himmel oben und unten auf Erden, keiner sonst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'Und sollst Seine Satzungen und Seine Gebote halten, die ich dir heute gebiete, auf daß es dir und deinen Söhnen nach dir wohlergehe, auf daß du deine Tage verlängerst auf dem Boden, den dir Jehovah, dein Gott, für alle Tage geben wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Da schied Mose drei Städte jenseits des Jordans gegen Aufgang der Sonne aus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'Auf daß dahin flöhe der Totschläger, der seinen Genossen ohne Wissen tot geschlagen, ohne daß er ihn haßte seit gestern und ehegestern. Und er soll fliehen in eine von diesen Städten und soll am Leben bleiben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Bezer in der Wüste im Lande der Ebene für die Rubeniter, und Ramoth in Gilead für die Gaditer, und Golan in Baschan für die Menaschiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'Und dies ist das Gesetz, welches Mose vor die Söhne Israels legte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'Das sind die Zeugnisse und die Satzungen und die Rechte, die Mose zu den Söhnen Israels auf ihrem Auszug aus Ägypten geredet hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'Jenseits des Jordans im Tal, Beth-Peor gegenüber, im Lande Sichons, des Königs der Amoriter, der in Cheschbon wohnte, den Mose und die Söhne Israels schlugen auf ihrem Auszug aus Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'Und sie nahmen sein Land ein und das Land Ogs, des Königs von Baschan, der zwei Könige der Amoriter, am Übergang über den Jordan, gegen Aufgang der Sonne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'Von Aroer, das am Ufer des Baches Arnon ist, und bis zum Berge Sion, das ist der Chermon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'Und all das Flachland jenseits des Jordans gegen Aufgang und bis zum Meere des Flachlandes unter den Abhängen des Pisgah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'Und Mose rief das ganze Israel und sprach zu ihnen: Höre, Israel, die Satzungen und die Rechte, welche ich heute vor euren Ohren rede, und lernet sie und haltet sie, daß ihr sie tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Jehovah, unser Gott, hat mit uns auf dem Choreb einen Bund geschlossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Nicht mit unseren Vätern hat Jehovah diesen Bund geschlossen, sondern mit uns, mit uns selbst, die wir alle heute hier am Leben sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Von Angesicht zu Angesicht redete Jehovah mit euch auf dem Berge mitten aus dem Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, 'Ich stand zwischen Jehovah und zwischen euch zu jener Zeit, um euch das Wort Jehovahs anzusagen; denn ihr fürchtetet euch vor dem Feuer und stiegt nicht auf den Berg. Und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Ich bin Jehovah, dein Gott, Der dich aus Ägyptenland, aus dem Hause der Knechte ausgeführt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Du sollst keine anderen Götter vor Mir haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Du sollst dir kein Schnitzbild irgendeines Abbildes machen von irgend etwas, das im Himmel oben, noch unten auf Erden, noch im Wasser unter der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'Du sollst sie nicht anbeten, noch ihnen dienen; denn Ich, Jehovah, dein Gott, bin ein eifernder Gott, Der heimsucht die Missetat der Väter an den Söhnen und auf den dritten und auf den vierten bei denen, die Mich hassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'Und Barmherzigkeit erzeige Tausenden, die Mich lieben und Meine Gebote halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Du sollst den Namen Jehovahs, deines Gottes, nicht ins Eitle führen; denn Jehovah wird den nicht ungestraft lassen, der Seinen Namen ins Eitle führt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Halte den Sabbathtag, daß du ihn heiligst, wie Jehovah, dein Gott, dir geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Sechs Tage sollst du arbeiten und all dein Werk tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'Aber der siebente Tag ist der Sabbath dem Jehovah, deinem Gotte. Da sollst du keine Arbeit tun, weder du, noch dein Sohn, noch deine Tochter, noch dein Knecht, noch deine Magd, noch dein Ochse, noch dein Esel, noch all dein Vieh, noch dein Fremdling, der in deinen Toren ist, auf daß dein Knecht und deine Magd ruhe gleich wie du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'Und du sollst gedenken, daß du warst ein Knecht in Ägyptenland, und daß Jehovah, dein Gott, dich von da ausgeführt hat mit starker Hand und ausgestrecktem Arm. Darum hat Jehovah, dein Gott, dir geboten, daß du den Sabbathtag halten sollst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Ehre deinen Vater und deine Mutter, wie dir Jehovah, dein Gott, geboten hat, auf daß deine Tage verlängert werden und daß es dir wohl gehe auf dem Boden, den Jehovah, dein Gott, dir geben wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Du sollst nicht morden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Du sollst nicht ehebrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Du sollst nicht stehlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Du sollst kein falsch Zeugnis reden wider deinen Nächsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Noch sollst du begehren deines Nächsten Weib, und sollst dich nicht gelüsten lassen deines Nächsten Haus, sein Feld, noch seinen Knecht, noch seine Magd, seinen Ochsen noch seinen Esel, noch irgend etwas, das dein Nächster hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Diese Worte hat Jehovah zu eurer ganzen Versammlung geredet auf dem Berge, mitten aus dem Feuer, der Wolke und dem Wolkendunkel mit großer Stimme, und tat nichts dazu, und Er schrieb sie auf zwei steinerne Tafeln und gab sie mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Und es geschah, als ihr die Stimme mitten aus der Finsternis hörtet, und der Berg im Feuer brannte, daß zu mir nahten alle Häupter eurer Stämme und eure Ältesten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'Und ihr sprachet: Siehe, Jehovah, unser Gott, hat uns Seine Herrlichkeit und Seine Größe sehen lassen, und wir haben Seine Stimme mitten aus dem Feuer gehört. An diesem Tage haben wir gesehen, daß Gott mit dem Menschen reden kann, und er am Leben bleibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Und nun - warum sollen wir sterben; denn das große Feuer da frißt uns auf. Wenn wir noch länger die Stimme Jehovahs, unseres Gottes, hören, so sterben wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Denn wer, der von allem Fleisch die Stimme des lebendigen Gottes mitten aus dem Feuer reden hörte, wie wir, ist am Leben geblieben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Nahe du, und höre alles, was Jehovah, unser Gott, sprechen wird, und du rede zu uns alles, was Jehovah, unser Gott, zu dir reden wird, und wir wollen es hören und tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'Und Jehovah hörte auf die Stimme eurer Worte, da ihr zu mir redetet, und Jehovah sprach zu mir: Ich habe die Stimme der Worte dieses Volkes gehört, die sie zu dir redeten; es ist alles gut, was sie geredet haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'Wäre es, daß dies ihr Herz immer so wäre, daß sie Mich fürchteten und alle Meine Gebote hielten alle Tage, auf daß es ihnen und ihren Söhnen ewiglich gut erginge!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Geh, sprich zu ihnen: Kehret zurück zu euren Zelten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Und du stehe allda bei Mir, und Ich will zu dir alles Gebot und die Satzungen und die Rechte reden, die du sie lehren sollst, auf daß sie sie tun in dem Lande, das Ich ihnen zum Erbbesitze geben will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Und ihr sollt sie halten, daß ihr tut, wie Jehovah, euer Gott, euch geboten hat, ihr sollt nicht davon abweichen rechts oder links.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'In all dem Weg, den Jehovah, euer Gott, euch geboten hat, sollt ihr wandeln, auf daß ihr lebet und es euch gut ergehe, und ihr eure Tage verlängert in dem Lande, das ihr einnehmen werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'Und dies ist das Gebot, die Satzungen und die Rechte, so Jehovah, euer Gott, geboten hat euch zu lehren, auf daß ihr sie tut in dem Lande, in das ihr hinüberziehet, um es einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'Damit du fürchtest Jehovah, deinen Gott, und haltest alle Seine Satzungen und Seine Gebote, die ich dir gebiete, du und dein Sohn und deines Sohnes Sohn, alle Tage deines Lebens, und auf daß deine Tage verlängert werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Und höre, Israel, und hüte dich, daß du es tust, auf daß es dir gut gehe und ihr euch sehr mehret, wie Jehovah, der Gott deiner Väter, zu dir geredet hat, in dem Lande, das von Milch und Honig fließt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Höre, Israel, Jehovah, unser Gott, ist ein Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Und du sollst lieben Jehovah, deinen Gott, von deinem ganzen Herzen und von deiner ganzen Seele und mit deiner ganzen Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'Und diese Worte, die ich dir heute gebiete, seien in deinem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'Und sollst sie deinen Söhnen einschärfen, und sollst davon reden wenn du sitzest in deinem Hause oder auf dem Wege gehst, und wenn du dich niederlegst und wenn du aufsteht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'Und sollst sie als Zeichen auf deine Hand binden und sie seien als Stirnband zwischen deinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Und sollst sie auf die Türpfosten deines Hauses und an deine Tore schreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Und es soll geschehen, wenn dich Jehovah, dein Gott, in das Land hineingebracht, daß Er deinen Vätern, dem Abraham, dem Isaak und dem Jakob geschworen hat, dir zu geben, große und gute Städte, die du nicht bautest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'Und Häuser, alles Guten voll, die du nicht gefüllt, und ausgehauene Brunnen, die du nicht ausgehauen, Weinberge und Ölgärten, die du nicht gepflanzt hast, und davon issest und satt wirst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'So hüte dich, daß du Jehovahs nicht vergessest, Der dich aus Ägyptenland, aus dem Hause der Knechte, ausgeführt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Jehovah, deinen Gott, sollst du fürchten und Ihm dienen und bei Seinem Namen schwören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Ihr sollt nicht anderen Göttern nachgehen, von den Göttern der Völker, die rings um euch sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'Denn ein eifernder Gott ist Jehovah, dein Gott, in deiner Mitte, auf daß nicht der Zorn Jehovahs, deines Gottes, entbrenne wider dich, und Er dich von den Angesichten des Bodens vernichte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Ihr sollt Jehovah, euren Gott, nicht versuchen, wie ihr Ihn in Massah versucht habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Ihr sollt halten die Gebote Jehovahs, eures Gottes, und Seine Zeugnisse und Seine Satzungen, die Er dir geboten hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'Und sollst tun, was recht und gut ist in den Augen Jehovahs, auf daß es dir gut gehe und du hineinkommst und das gute Land einnehmest, das Jehovah deinen Vätern geschworen hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'Auf daß Er vertreibe alle deine Feinde vor dir, wie Jehovah geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Wenn dich dein Sohn morgen fragen wird und sagen: Was sollen diese Zeugnisse und die Satzungen und die Rechte, die Jehovah, unser Gott, euch geboten hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'So sollst du deinem Sohne sagen: Wir waren Knechte dem Pharao in Ägypten; und Jehovah hat uns mit starker Hand aus Ägypten ausgeführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'Und Jehovah tat große und schlimme Zeichen und Wahrzeichen an Ägypten, an Pharao und an seinem ganzen Haus vor unseren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'Und führte uns aus von da, auf daß Er uns heranbrächte und gäbe uns das Land, das Er unseren Vätern geschworen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'Und Jehovah hat uns geboten, all diese Satzungen zu tun, Jehovah, unseren Gott, zu fürchten, auf daß es uns gut gehe alle Tage, daß Er uns am Leben erhalte, wie es heutigentags ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'Und es wird für uns Gerechtigkeit sein, wenn wir daran halten, daß wir all dies Gebot tun vor Jehovah, unserem Gott, wie Er uns geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Wenn dich Jehovah, dein Gott, in das Land hineinbringt, in das du einziehst, um es einzunehmen, und Er ausstößt viele Völkerschaften vor dir, die Chethiter und die Girgaschiter und die Amoriter und die Kanaaniter und die Pherisiter und die Chiviter und die Jebusiter, sieben größere und mächtigere Völkerschaften als du;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'Und Jehovah, dein Gott, gibt sie vor dich dahin und du schlägst sie, so sollst du sie ganz und gar bannen, und keinen Bund mit ihnen schließen, noch ihnen gnädig sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Und du sollst dich mit ihnen nicht verschwägern: Deine Töchter sollst du nicht geben seinem Sohne und seine Tochter nicht deinem Sohne nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Denn er wird deinen Sohn von Mir abwenden, daß sie anderen Göttern dienen, und der Zorn Jehovahs wird wider euch entbrennen und Er wird eilends dich vernichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Vielmehr sollt ihr ihnen also tun: Ihre Altäre sollt ihr einreißen und ihre Bildsäulen zerbrechen und ihre Ascheren niederhauen und ihre Schnitzbilder im Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Denn ein heilig Volk bist du deinem Gott Jehovah; dich hat Jehovah, dein Gott, erwählt, daß du ein Volk des Eigentums Ihm sein sollst vor allen Völkern, die auf dem Angesichte des Bodens sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Nicht weil euer mehr sind als alle Völker, hat Jehovah Gefallen an euch und hat euch erwählt; denn ihr seid das kleinste unter allen Völkern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'Sondern weil Jehovah euch liebte, und daß Er Seinen Schwur hielte, den Er euren Vätern geschworen hatte, führte euch Jehovah aus mit starker Hand und löste dich ein aus dem Hause der Knechte, aus der Hand Pharaos, des Königs von Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Und du sollst wissen, daß Jehovah, dein Gott, der Gott ist, der wahre Gott, der Bund und Barmherzigkeit hält denen, die Ihn lieben und Seine Gebote halten, in das tausendste Geschlecht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'Und vergilt denen, die Ihn hassen, ins Angesicht, ihn zu verderben. Nicht zögert Er Seinem Hasser, ins Angesicht vergilt Er ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'So halte denn das Gebot und die Satzungen und die Rechte, die ich dir heute gebiete, auf daß du sie tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'Und es wird geschehen, daß darum, daß ihr auf diese Rechte höret und sie haltet und sie tut, auch Jehovah, dein Gott, dir den Bund und die Barmherzigkeit hält, die Er deinen Vätern geschworen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'Und Er liebt dich und segnet dich und mehret dich, und segnet die Frucht deines Mutterleibes und die Frucht deines Bodens, dein Korn und deinen Most und dein Öl, den Wurf deiner Rinder und die Zucht deines Kleinviehs auf dem Boden, den Jehovah deinen Vätern geschworen hat, dir zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Gesegnet wirst du sein vor allen Völkern; kein Unfruchtbarer und keine Unfruchtbare wird sein bei dir und bei deinem Vieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Und Jehovah wird alle Krankheit von dir abwenden; und keine der bösen Seuchen Ägyptens, von denen du weißt, wird Er auf dich legen, sondern sie über alle deine Hasser bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'Und du sollst verzehren alle Völker, die Jehovah, dein Gott, dir gibt, und dein Auge soll ihrer nicht schonen, auf daß du ihren Göttern nicht dienst: denn dies ist ein Fallstrick für dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'So du in deinem Herzen sprichst: Dieser Völkerschaften sind zu viele für mich, wie werde ich vermögen, sie auszutreiben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'So fürchte dich nicht vor ihnen: Gedenke dessen, was Jehovah, dein Gott, dem Pharao und ganz Ägypten getan!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'Der großen Versuchungen, die deine Augen gesehen, und der Zeichen und Wahrzeichen, und wie Jehovah, dein Gott, dich mit starker Hand und ausgerecktem Arm herausgeführt; also wird Jehovah, dein Gott, allen den Völkern tun, vor denen du dich fürchtest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Und auch den Horniß sendet Jehovah, dein Gott, über sie, bis auch die Übriggebliebenen und die sich verborgen vor deinem Angesicht, umgekommen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Laß dir nicht vor ihnen grauen. Denn Jehovah, dein Gott, ist in deiner Mitte, ein großer und furchtbarer Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Und ausstoßen wird Jehovah, dein Gott, nach und nach diese Völkerschaften vor deinem Angesicht. Nicht eilig wirst du vermögen sie wegzutilgen, auf daß der wilden Tiere des Feldes nicht zu viel werden wider dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'Und Jehovah, dein Gott, gibt sie vor dir dahin und verwirrt sie in großer Verwirrung, bis daß sie vernichtet sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Und ihre Könige gibt Er in deine Hand, auf daß du ihren Namen unter dem Himmel zerstörst. Kein Mann soll vor dir bestehen, bis du sie vernichtet hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Die Schnitzbilder ihrer Götter sollt ihr im Feuer verbrennen, du sollst nicht das Silber und das Gold daran begehren und zu dir nehmen; auf daß es nicht zum Fallstrick für dich werde; denn ein Greuel ist es Jehovah, deinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'Und du sollst keinen Greuel in dein Haus bringen, auf daß du nicht gleich ihm gebannet werdest. Verabscheuen sollst du es und Grauen davor haben; denn es ist Verbanntes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Alles Gebot, das ich dir heute gebiete, sollt ihr halten, es zu tun, auf daß ihr lebet und euch mehret und hineinkommet und das Land einnehmet, das Jehovah euren Vätern zugeschworen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'Und gedenke all des Weges, den dich Jehovah, dein Gott, diese vierzig Jahre in der Wüste gehen ließ, um dich zu demütigen, dich zu versuchen, damit Er wisse, was in deinem Herzen ist, ob du Seine Gebote halten wirst oder nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'Und Er demütigte dich und ließ dich hungern, und ließ dich Manna essen, das du nicht gekannt und das deine Väter nicht gekannt hatten, um dich wissen zu lassen, daß der Mensch nicht lebt vom Brot allein, sondern daß von allem, das aus dem Munde Jehovahs geht, der Mensch lebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Dein Gewand alterte nicht an dir und dein Fuß schwoll nicht diese vierzig Jahre lang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Und du weißt mit deinem Herzen, daß wie ein Mann seinen Sohn in Zucht nimmt, so Jehovah, dein Gott, dich in Zucht genommen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'Und halte die Gebote Jehovahs, deines Gottes, daß du wandelst in Seinen Wegen und Ihn fürchtest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Denn Jehovah, dein Gott, bringt dich in ein gutes Land, ein Land der Bäche von Wasser, der Quellen und Tiefen, die im Tal und im Gebirge herauskommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'Ein Land des Weizens und der Gerste und des Weinstocks und des Feigenbaums und des Granatbaums, ein Land des Olivenbaums mit Öl und des Honigs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'Ein Land, in dem du nicht kärgliches Brot issest, in dem es dir an nichts mangelt; ein Land, dessen Steine Eisen sind, und aus dessen Gebirgen du Erz aushaust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'Du sollst essen und satt werden und sollst Jehovah, deinen Gott, segnen ob deinem Lande, das Er dir gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Hüte dich, daß du Jehovah, deinen Gott, nicht vergissest, nicht zu halten Seine Gebote und Seine Rechte und Seine Satzungen, die ich dir heute gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'Auf daß nicht, wenn du issest und dich sättigst und gute Häuser baust und darin wohnst,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'Und dein Rind und dein Kleinvieh sich mehrt, und deines Silbers und Goldes dir viel wird, und alles, das du hast, sich mehrt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'Dein Herz dann sich emporhebt und du Jehovah, deinen Gott, vergissest, Der dich aus Ägyptenland, dem Hause der Knechte ausgeführt hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'Ihn, Der dich durch die große und furchtbare Wüste gehen ließ, wo die Schlangen, der Saraph und der Skorpion, und ein dürstendes Land, darin kein Wasser ist, Ihn, Der für dich Wasser aus dem Felsen von Kiesel hervorkommen ließ;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'Ihn, Der dich in der Wüste Manna essen ließ, das deine Väter nicht gekannt hatten, auf daß Er dich demütige und auf daß Er dich versuche, um dir danach Gutes zu tun;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'Und du sprächest in deinem Herzen: Meine Kraft und die Macht meiner Hand hat mir dieses Vermögen bereitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'So gedenke Jehovahs, deines Gottes, denn Er gibt dir Kraft, das Vermögen zu bereiten, auf daß Er Seinen Bund, den Er deinen Vätern geschworen hat, bestätige wie dieses Tages.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Und es wird sein, so du Jehovahs, deines Gottes, vergissest und anderen Göttern nachgehst, ihnen dienst und sie anbetest, so zeuge ich heute wider euch, daß ihr umkommen werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'Wie die Völkerschaften, die Jehovah vor eurem Angesicht zerstört, so werdet ihr zerstört, weil ihr nicht auf die Stimme Jehovahs, eures Gottes, gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Höre, Israel, du setzest heute über den Jordan, um hineinzuziehen, um Völkerschaften, die größer und mächtiger sind als du, mit großen bis an den Himmel befestigten Städten, auszutreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'Ein großes, hohes Volk, Söhne der Enakim, die du kennst und von denen du gehört: Wer kann bestehen vor Enaks Söhnen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'So wisse denn heute, daß Jehovah, dein Gott, Der vor dir hinüberzieht, ein fressend Feuer, sie vernichten wird und sie vor dir niederbeugen; und du sollst sie austreiben und eilends zerstören, wie Jehovah zu dir geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Nicht sprich in deinem Herzen, wenn Jehovah, dein Gott, sie vor dir verteilt, und sage: Um meiner Gerechtigkeit willen hat Jehovah mich hereingebracht, dieses Land einzunehmen, und wegen der Ungerechtigkeit dieser Völkerschaften treibe sie Jehovah vor dir aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'Nicht um deiner Gerechtigkeit und um der Redlichkeit deines Herzens willen kannst du ihr Land einnehmen, sondern ob der Ungerechtigkeit dieser Völkerschaften treibt Jehovah, dein Gott, sie vor dir aus, und auf daß Er das Wort bestätige, das Jehovah deinen Vätern, dem Abraham, dem Isaak und dem Jakob, geschworen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Und du sollst wissen, daß nicht ob deiner Gerechtigkeit Jehovah, dein Gott, dir dies gute Land zum Erbbesitze geben wird, denn du bist ein halsstarriges Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Gedenke, vergiß es nicht, wie du Jehovah, deinen Gott, in der Wüste entrüstet hast; von dem Tage an, da du aus Ägyptenland ausgegangen, bis ihr an diesen Ort gekommen seid, seid ihr wider Jehovah widerspenstig gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Und am Choreb habt ihr Jehovah entrüstet, und Jehovah zürnte wider euch, euch zu vernichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Als ich auf den Berg stieg, um die steinernen Tafeln, die Tafeln des Bundes, den Jehovah mit euch schloß, zu holen, und ich auf dem Berge blieb vierzig Tage und vierzig Nächte, aß ich kein Brot und trank kein Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'Und Jehovah gab mir die zwei steinernen Tafeln, mit dem Finger Gottes beschrieben und auf denselben alle Worte, die Jehovah auf dem Berge mitten aus dem Feuer am Tage der Versammlung mit euch geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Und es geschah am Ende der vierzig Tage und vierzig Nächte, daß mir Jehovah die zwei steinernen Tafeln, die Tafeln des Bundes gab;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'Und Jehovah sprach zu mir: Mache dich auf, gehe eilig von da hinab: Denn dein Volk, das du aus Ägypten ausgeführt hast, verdirbt. Eilig sind sie von dem Wege gewichen, den Ich ihnen geboten habe. Sie haben sich ein Gußbild gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Und Jehovah sprach zu mir und sagte: Ich sah dieses Volk und siehe: es ist ein halsstarriges Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'Laß ab von Mir, daß Ich sie vernichte und ihren Namen auswische unter dem Himmel. Dich aber will Ich zu einer Völkerschaft machen, mächtiger und mehr denn sie!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Und ich wandte mich und kam herab vom Berge, und der Berg brannte im Feuer. Und die zwei Tafeln des Bundes waren auf meinen zwei Händen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'Und ich sah und siehe: Ihr hattet gesündigt gegen Jehovah, euren Gott, ihr hattet euch ein gegossen Kalb gemacht. Ihr waret eilig von dem Wege gewichen, den Jehovah euch geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Und ich erfaßte die zwei Tafeln und warf sie aus meinen beiden Händen, und ich zerbrach sie vor euren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'Und ich fiel nieder vor Jehovah, wie zuerst, vierzig Tage und vierzig Nächte, aß kein Brot und trank kein Wasser, um aller eurer Sünden willen, die ihr gesündigt, daß ihr tatet, was böse war in den Augen Jehovahs, womit ihr Ihn reiztet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Denn mir war bange vor dem Zorn und Grimm, von dem Jehovah wider euch entrüstet war, so daß Er euch vernichten wollte, und Jehovah hörte auch jenes Mal auf mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Und über Aharon zürnte Jehovah sehr, so daß Er ihn vernichten wollte, und ich betete auch für Aharon zur selben Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'Und eure Sünde, die ihr gemacht, das Kalb, nahm ich und verbrannte es im Feuer und zerstieß und zermahlte es wohl, bis daß es fein ward zu Staub und warf den Staub davon in den Bach, der vom Berge herabkommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Und in Taberah und in Massah und bei Kibroth Hattaavah habt ihr Jehovah entrüstet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'Und als Jehovah euch von Kadesch Barnea sandte und sprach: Ziehet hinauf und nehmet das Land ein, das Ich euch gegeben habe, da waret ihr widerspenstig wider den Mund Jehovahs, eures Gottes, und glaubtet Ihm nicht und hörtet nicht auf Seine Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Ihr waret widerspenstig wider Jehovah von dem Tage an, da ich euch kenne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Und ich fiel nieder vor Jehovah vierzig Tage und vierzig Nächte, die ich niederfiel; denn Jehovah sprach, Er wolle euch vernichten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'Und ich betete zu Jehovah und sprach: Herr Jehovah, verdirb nicht Dein Volk und Dein Erbe, das Du eingelöst hast durch Deine Größe, das Du mit starker Hand aus Ägypten herausgeführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Gedenke deiner Knechte Abraham, Isaak und Jakob und wende dich nicht an die Härtigkeit dieses Volkes und an seine Ungerechtigkeit und an seine Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'Daß man nicht sage im Lande, aus dem Du uns ausgeführt hast: Da Jehovah nicht vermochte, sie in das Land hineinzubringen, von dem Er zu ihnen geredet hatte, und weil Er sie haßte, hat Er sie herausgeführt, um sie in der Wüste zu töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Und sie sind Dein Volk und Dein Erbe, das Du mit Deiner großen Kraft und Deinem ausgereckten Arm hast ausgeführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Zu selbiger Zeit sprach Jehovah zu mir: Haue dir zwei steinerne Tafeln zu, wie die ersten und steige herauf zu Mir auf den Berg, und mache dir eine Lade von Holz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'Und Ich will auf die Tafeln die Worte schreiben, die auf den ersten Tafeln waren, die du zerbrochen hast. Und du sollst sie in die Lade legen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Und ich machte eine Lade von Schittimholz und hieb zwei steinerne Tafeln zu, wie die ersten, und stieg auf den Berg und die zwei Tafeln in meiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Und Er schrieb auf die Tafeln wie die erste Schrift war, die Zehn Worte, die Jehovah auf dem Berge mitten aus dem Feuer, am Tage der Versammlung zu euch geredet hatte; und Jehovah gab sie mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'Und ich wandte mich und kam vom Berg herab, und legte die Tafeln in die Lade, die ich gemacht hatte, und sie waren dort, wie Jehovah geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Und die Söhne Israels brachen auf von Beeroth Bene Jaakan nach Moserah; dort starb Aharon und ward dort begraben; und sein Sohn Eleasar ward Priester an seiner Statt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Von da brachen sie auf nach Gudgodah und von Gudgodah nach Jotbathah, in ein Land mit Bächen des Wassers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Zu selbiger Zeit schied Jehovah den Stamm Levi aus, daß er die Lade des Bundes Jehovahs trüge, vor Jehovah stünde Ihm Dienst zu tun und in Seinem Namen zu segnen bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Darum ward Levi kein Teil und Erbe mit seinen Brüdern. Jehovah ist sein Erbe, wie Jehovah, dein Gott, zu ihm geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Und ich stand, wie in den ersten Tagen, vierzig Tage und vierzig Nächte auf dem Berge, und Jehovah hörte auf mich auch diesmal; Jehovah wollte dich nicht verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'Und Jehovah sprach zu mir: Mache dich auf, gehe, vor dem Volke herzuziehen, auf daß sie hineinkommen und das Land einnehmen, das Ich ihren Vätern geschworen habe, ihnen zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Und nun, Israel, was fordert Jehovah, dein Gott, von dir, als daß du Jehovah, deinen Gott, fürchtest, daß du in allen Seinen Wegen wandelst und Ihn liebst und Jehovah, deinem Gotte, dienst von ganzem Herzen und von ganzer Seele?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'Daß du haltest die Gebote Jehovahs und Seine Satzungen, die ich dir heute gebiete, daß es gut mit dir sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Siehe, Jehovah, deines Gottes, sind die Himmel und die Himmel der Himmel, und die Erde und alles, was in ihr ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'An deinen Vätern nur hatte Jehovah Gefallen, sie zu lieben, und hat ihren Samen nach ihnen, euch, Sich vor allen Völkern erwählt, wie an diesem Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Beschneidet aber die Vorhaut eures Herzens und verhärtet euren Nacken nicht mehr!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Denn Jehovah, euer Gott, ist der Gott der Götter und der Herr der Herren, der große, mächtige und furchtbare Gott, Der keine Person ansieht und kein Geschenk nimmt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'Der Recht tut dem Waisen und der Witwe, und den Fremdling liebt, so daß Er ihm Brot und Gewand gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Und ihr sollt den Fremdling lieben; denn ihr seid Fremdlinge in Ägyptenland gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Jehovah, deinen Gott sollst du fürchten, Ihm dienen und Ihm anhangen und bei Seinem Namen schwören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'Er sei dein Lob; und Er, dein Gott, ist es, Der mit dir solch Großes und Furchtbares getan, wie deine Augen gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'Mit siebzig Seelen gingen deine Väter hinab nach Ägypten, und nun hat Jehovah, dein Gott, dich gesetzt wie die Sterne des Himmels an Menge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Und du sollst lieben Jehovah, deinen Gott, und halten Seine Verordnungen und Seine Satzungen und Seine Rechte und Seine Gebote alle Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'Und wisset heute - nicht eure Söhne, die es nicht wissen und die es nicht gesehen haben - die Zucht Jehovahs, eures Gottes, Seine Größe, Seine starke Hand und Seinen ausgereckten Arm,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'Und Seine Zeichen und Taten, die Er inmitten Ägyptens getan an Pharao, Ägyptens König, und an seinem ganzen Land,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'Und was Er tat an Ägyptens Streitmacht, an seinen Rossen und an seinen Wagen, über deren Angesicht Er die Wasser des Schilfmeeres strömen ließ, da sie euch nachsetzten, und wie Jehovah sie zerstörte bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'Und was Er an euch getan in der Wüste, bis ihr hereinkamt an diesen Ort,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'Und was Er tat dem Dathan und dem Abiram, den Söhnen Eliabs, des Sohnes Rubens, wie die Erde ihren Mund aufsperrte und verschlang sie und ihre Häuser und ihre Zelte und allen Bestand, der in ihrem Gefolge war, inmitten von ganz Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Denn eure Augen haben gesehen all die große Tat Jehovahs, die Er getan hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'So haltet denn alles Gebot, das ich euch heute gebiete, auf daß ihr erstarket und hineinkommt, und das Land einnehmet, in das ihr hinüberziehet, es einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'Und daß ihr eure Tage verlängert auf dem Boden, den Jehovah euren Väter geschworen hat, ihnen und ihrem Samen zu geben, ein Land, das von Milch und Honig fließt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Denn das Land, da du hineinkommst, es einzunehmen, ist nicht wie das Land Ägypten, aus dem du ausgegangen bist, in das du deinen Samen sätest, und das du mit deinem Fuße bewässertest wie einen Kohlgarten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Das Land aber, dahin ihr übersetzet, es einzunehmen, ist ein Land der Berge und Täler; es trinkt Wasser von des Himmels Regen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'Ein Land, nach dem Jehovah, dein Gott, fragt. Die Augen Jehovahs, deines Gottes, sind vom Anfang des Jahres und bis zum Letzten des Jahres beständig auf demselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Und es wird geschehen, wenn ihr auf meine Gebote hört, die ich euch heute gebiete, so daß ihr Jehovah, euren Gott, liebet und Ihm dienet von eurem ganzen Herzen und von eurer ganzen Seele,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'So werde ich Regen für euer Land geben zu seiner Zeit, Frühregen und Spätregen, so daß du einsammelst dein Korn und deinen Most und dein Öl,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'Und werde Kräuter auf deinem Felde für dein Vieh geben, und du sollst essen und satt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Hütet euch, daß euer Herz sich nicht bereden lasse, und ihr abweichet und anderen Göttern dient und sie anbetet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'Und der Zorn Jehovahs wider euch entbrenne, und Er den Himmel verschließe und kein Regen sei und der Boden sein Gewächs nicht gebe, und ihr eilends umkommet, weg von dem guten Land, das Jehovah euch gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Und ihr sollt diese meine Worte euch zu Herzen legen und in eure Seelen, und sollt sie binden als Zeichen auf eure Hand, und sie sollen als Stirnband zwischen euren Augen sein,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'Und sollt sie eure Söhne lehren, und davon reden, wenn du sitzest in deinem Hause, und wenn du auf dem Wege gehst, wenn du dich niederlegst, und wenn du aufstehst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'Und sollst sie auf die Türpfosten deines Hauses und an deine Tore schreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'Auf daß eurer Tage und eurer Söhne Tage so viel werden auf dem Boden, den Jehovah euren Vätern geschworen hat, ihnen zu geben, wie der Tage der Himmel über der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Denn wenn ihr all dies Gebot, das ich euch gebiete zu tun, haltet, daß ihr Jehovah, euren Gott, liebet und in all Seinen Wegen wandelt und Ihm anhanget,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'So wird Jehovah alle diese Völkerschaften vor euch austreiben, und ihr werdet austreiben größere und mächtigere Völkerschaften, als ihr seid;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Jeglicher Ort, den eure Fußsohle betritt, soll euer sein, von der Wüste und dem Libanon, von dem Fluß, dem Flusse Phrath bis zum hinteren Meere soll eure Grenze sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Kein Mann soll bestehen vor euch. Schauer und Furcht vor euch wird Jehovah, euer Gott, legen auf alles Land, das ihr betreten werdet, wie Er zu euch geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Siehe, ich lege heute Segen und Fluch vor euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'Den Segen, so ihr höret auf die Gebote Jehovahs eures Gottes, die ich euch heute gebiete;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'Und den Fluch, so ihr nicht auf die Gebote Jehovahs, eures Gottes, hört, und abweichet von dem Wege, den ich euch heute gebiete, daß ihr anderen Göttern nachgehet, von denen ihr nichts wisset.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'Und es soll geschehen: Wenn dich Jehovah, dein Gott, in das Land bringt, in das du hineinziehst, um es einzunehmen, so sollst du den Segen geben, auf dem Berge Gerissim und den Fluch auf dem Berge Ebal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'Sind sie nicht jenseits des Jordans hinter dem Wege gegen Sonnenuntergang im Land der Kanaaniter, die in der Arabah Gilgal gegenüber wohnen, neben den Eichen von Moreh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Denn ihr setzet über den Jordan, um hineinzukommen, um das Land einzunehmen, das Jehovah, euer Gott, euch gibt, auf daß ihr es erblich besitzet und darinnen wohnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'So haltet denn, daß ihr tut alle Satzungen und Rechte, die ich heute gebe vor eurem Angesichte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'Das sind die Satzungen und die Rechte, die ihr halten sollt sie zu tun in dem Lande, das Jehovah, der Gott deiner Väter, dir zum Erbbesitze gibt, alle Tage, die ihr auf dem Boden lebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Gänzlich zerstören sollt ihr alle Orte, da die Völkerschaften, die ihr austreibt, ihren Göttern gedient auf den hohen Bergen und auf den Hügeln und unter all den grünen Bäumen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'Und ihr sollt einreißen ihre Altäre und ihre Bildsäulen zerbrechen, und ihre Ascheren im Feuer verbrennen, und die Schnitzbilder ihrer Götter niederhauen und ihren Namen von selbigem Ort zerstören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Nicht also sollt ihr Jehovah, eurem Gotte, tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'Vielmehr sollt ihr nach dem Orte, den Jehovah, euer Gott, aus all euren Stämmen erwählen wird, um Seinen Namen dort zu setzen, um dort zu wohnen, selbigem nachfragen und dahin kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'Und dahin sollt ihr eure Brandopfer und eure Schlachtopfer und eure Zehnten, und die Hebe eurer Hand, und eure Gelübde und eure freiwilligen Opfer und die Erstlinge eures Rindviehs und eures Kleinviehs hinbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'Und dort sollt ihr essen vor Jehovah, eurem Gott, und ihr und euer Haus sollt fröh- lich sein ob allem, nach dem ihr eure Hand ausgereckt, womit Jehovah, dein Gott, dich gesegnet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Ihr sollt nicht tun, nach allem, das wir heute hier tun, ein jeder Mann alles, das recht ist in seinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'Denn bis jetzt seid ihr noch nicht zur Ruhe und zu dem Erbe hineingekommen, das Jehovah, dein Gott, dir geben wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Nun aber setzt ihr über den Jordan und wohnet in dem Lande, das Jehovah, euer Gott, euch zum Erbe gibt, und Er wird euch zur Ruhe bringen vor allen euren Feinden ringsum, so daß ihr wohnet in Sicherheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'Und es soll sein, daß an dem Orte, den Jehovah, euer Gott, erwählen wird, da Seinen Namen wohnen zu lassen, dahin sollt ihr hinbringen alles, was ich euch gebiete, eure Brandopfer und eure Schlachtopfer, eure Zehnten und die Hebe eurer Hand, und alle die Auswahl eurer Gelübde, die ihr Jehovah geloben werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'Und ihr sollt fröhlich sein vor Jehovah, eurem Gotte, ihr und eure Söhne und eure Töchter, und eure Knechte und eure Mägde und der Levite, der in euren Toren ist; denn er hat kein Teil und kein Erbe mit euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Hüte dich, daß du deine Brandopfer nicht aufopferst an jeglichem Orte, den du siehst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'Sondern an dem Ort, den Jehovah unter einem deiner Stämme erwählt, dort sollst du deine Brandopfer aufopfern, und dort alles das tun, was ich dir gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Doch magst du, nach allem Gelüste deiner Seele schlachten und Fleisch essen, je nach dem Segen, den dir Jehovah, dein Gott, geben wird, in all deinen Toren, der Unreine und der Reine mögen es essen, wie das Reh und den Hirsch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Nur das Blut sollt ihr nicht essen. Auf die Erde gießet es aus, wie das Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Du darfst nicht in deinen Toren essen den Zehnten deines Korns und deines Mosts und deines Öls, noch die Erstgeburt deines Rindes und deines Kleinviehs, noch irgendwelche von deinen Gelübden, die du gelobt, noch deine freiwilligen Opfer, noch die Hebe deiner Hand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'Sondern vor Jehovah, deinem Gotte, sollst du es essen am Orte, den Jehovah, dein Gott, erwählen wird, du und dein Sohn und deine Tochter und dein Knecht und deine Magd und der Levite, der in deinen Toren ist, und sollst fröhlich sein vor Jehovah, deinem Gotte, an allem, wo du deine Hand ausstreckst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Hüte dich, daß du den Leviten nicht verlässest, alle deine Tage auf deinem Boden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Wenn Jehovah, dein Gott, deine Grenze ausbreitet, wie Er zu dir geredet hat, und du sprichst: Ich möchte Fleisch essen, weil deine Seele danach gelüstet, Fleisch zu essen, darfst du nach all deiner Seele Gelüste Fleisch essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Wenn der Ort, den Jehovah, dein Gott, erwählt, Seinen Namen daselbst einzusetzen, fern von dir ist, so schlachte von deinem Rind und deinem Kleinvieh, das Jehovah dir gegeben, wie ich dir geboten habe, und iß in deinen Toren, nach allen Gelüsten deiner Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Nur wie man das Reh und den Hirsch ißt, sollst du es essen. Der Unreine und der Reine zugleich mögen davon essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Nur halte fest daran, daß du das Blut nicht issest; denn das Blut ist die Seele und die Seele sollst du nicht mit dem Fleisch essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Du sollst es nicht essen; auf die Erde, wie Wasser gieß es aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Du sollst es nicht essen, auf daß es gut gehe dir und deinen Söhnen nach dir, so du tust, was recht ist in Jehovahs Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Nur dein Geheiligtes, das du haben wirst, und deine Gelübde sollst du aufheben und kommen zu dem Ort, den Jehovah erwählen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'Und bereite deine Brandopfer, das Fleisch und das Blut auf dem Altare Jehovahs, deines Gottes, und das Blut deiner Schlachtopfer gieße man auf den Altar Jehovahs, deines Gottes; und das Fleisch sollst du essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Halte und höre alle diese Worte, die ich dir gebiete, auf daß es gut gehe dir und deinen Söhnen nach dir ewiglich, darum, daß du tust, was gut und recht ist in den Augen Jehovahs, deines Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Wenn Jehovah, dein Gott, ausrotten wird die Völkerschaften, dahin du kommst, sie vor dir auszutreiben, und du sie austreibst und in ihrem Lande wohnest;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'Hüte dich, daß du nicht ihnen nach dich verstrickst, nach ihrer Vernichtung vor dir; und nicht nach ihren Göttern fragst, und sagst: Wie diese Völkerschaften ihren Göttern dienten, so will auch ich tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Tue nicht also Jehovah, deinem Gott; denn alles, was Jehovah ein Greuel ist, den Er haßt, haben sie ihren Göttern getan, so daß sie auch ihre Söhne und ihre Töchter ihren Göttern im Feuer verbrannten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'All das Wort, das ich euch gebiete, sollet ihr halten es zu tun, und nichts dazu tun und nichts davon tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'Wenn ein Prophet oder einer, der Träume träumt, in deiner Mitte aufsteht, und dir ein Zeichen oder Wahrzeichen gibt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'Und das Zeichen und das Wahrzeichen kommt, davon er zu dir geredet hat, und spricht: Lasset uns anderen Göttern, die ihr nicht kennt, nachgehen und ihnen dienen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'So höre nicht auf die Worte dieses Propheten oder auf den Traum dieses Träumers; denn Jehovah, euer Gott, versucht euch, um zu wissen, ob ihr auch wirklich Jehovah, euren Gott, von eurem ganzem Herzen und von eurer ganzen Seele liebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Jehovah, eurem Gotte, sollt ihr nachwandeln, und Ihn sollt ihr fürchten und Seine Gebote halten, und auf Seine Stimme sollt ihr hören und Ihm dienen und Ihm sollt ihr anhangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Und dieser Prophet oder dieser träumende Träumer soll sterben dafür, daß er von Abfall geredet wider Jehovah, euren Gott, Der euch aus Ägyptenland ausgeführt und dich aus dem Hause der Knechte eingelöst hat, um dich abzuführen von dem Wege, darin zu wandeln Jehovah, dein Gott, dir geboten hat; und du sollst das Böse wegschaffen aus deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'So dich dein Bruder, der Sohn deiner Mutter, oder dein Sohn oder deine Tochter oder das Weib deines Busens, oder dein Genosse, der dir wie deine Seele ist, insgeheim antreibt und spricht: Komm, laß uns anderen Göttern dienen, die du und deine Väter nicht gekannt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'Einen der Götter der Völker, die rings um uns sind, die dir nahe oder ferne von dir sind, von einem Ende der Erde und bis zum anderen Ende der Erde:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'So willige ihm nicht ein und höre nicht auf ihn, und dein Auge schone seiner nicht, und habe kein Mitleid und verdecke es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'Erwürgen sollst du ihn! Deine Hand sei zuerst an ihm, ihn zu töten, und die Hand alles Volkes hinten nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'Und sollst ihn mit Steinen steinigen, daß er sterbe, darum, daß er suchte, dich abzuführen von Jehovah, deinem Gotte, Der dich aus Ägyptenland, aus dem Hause der Knechte, ausgeführt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Und ganz Israel höre es, und fürchte sich, und sie sollen nicht mehr solch Übel tun in deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Wenn du von einer deiner Städte, die Jehovah, dein Gott, dir geben wird, darin zu wohnen, wirst hören sagen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'Es sind Männer, Söhne Belials, ausgegangen aus deiner Mitte, und haben die Einwohner ihrer Stadt abgeführt und gesprochen: Kommt, lasset uns anderen Göttern dienen, die ihr nicht kennt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'So sollst du wohl nachfragen und ergründen und fragen, und siehe, ist das Wort wahr und richtig, daß dieser Greuel in deiner Mitte ist getan worden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'So sollst du die Einwohner dieser Stadt mit der Schärfe des Schwertes schlagen, sie verbannen und alles, was in ihr ist, auch ihr Vieh, mit der Schärfe des Schwertes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'Und alle Beute aus ihr sollst du mitten auf ihrem Platze zusammenbringen und die Stadt und all ihre Beute allesamt mit Feuer verbrennen Jehovah, deinem Gott. Ein Schutthaufen soll sie sein ewiglich, soll nie mehr aufgebaut werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'Und nichts von dem Verbannten hange an deiner Hand, auf daß Jehovah von der Entbrennung Seines Zorns Sich zurückwende und dir Erbarmen gebe, und Sich dein erbarme und dich mehre, wie Er deinen Vätern zugeschworen hat, Weil du auf die Stimme Jehovahs, deines Gottes, hörest zu halten alle Seine Gebote, die ich heute dir gebiete, auf daß du tust, was recht ist in den Augen Jehovahs deines Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Ihr seid Söhne Jehovahs, eures Gottes, ihr sollt euch keine Einschnitte machen, noch euch zwischen euren Augen kahl machen um eines Toten willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Denn du bist ein heiliges Volk Jehovah, deinem Gott, und dich hat Jehovah erwählt, daß du Ihm ein Volk des Eigentums vor allen Völkern, auf dem Angesichte des Bodens seiest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Du sollst nichts essen, das ein Greuel ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'Dies ist das Vieh, das du essen darfst: Ochse, Junges der Schafe und Junges der Ziegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'Hirsch und Reh und Damhirsch, Steinbock und Antilope und Büffelochs und Samer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'Und alles Vieh, das durchbrochene Hufe, und in zwei Klauen gespaltene Hufe hat, und wiederkäut unter dem Vieh, das dürfet ihr essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Nur das sollt ihr nicht essen von den Wiederkäuenden und von denen, welche Hufe mit gespaltenen Klauben haben: Das Kamel, den Hasen und das Kaninchen; denn wiederkäuend sind sie, aber sie spalten den Huf nicht. Unrein seien sie euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'Und das Schwein; denn es spaltet zwar den Huf, ist aber nicht wiederkäuend; unrein sei es euch. Von ihrem Fleisch sollt ihr nicht essen, noch ihr Aas berühren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Das dürfet ihr essen von allem, was im Wasser ist: Alles, was Flossen hat und Schuppen, dürfet ihr essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'Alles aber, was keine Flossen und Schuppen hat, sollt ihr nicht essen. Es sei euch unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Alle reine Vögel dürft ihr essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Und das sind die von ihnen, so ihr nicht essen sollt: Der Adler und der Seeadler und der Lämmergeier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'Und der Weihe und der Falke und der Geier nach seiner Art.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'Und alle Raben nach ihrer Art.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'Und das Käuzlein und der Strauß und die Möwe und der Habicht nach seiner Art.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'Der Uhu, die Eule und die Dohle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'Und der Pelikan und der Aasgeier und der Taucher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'Und der Storch und der Reiher nach seiner Art, und der Wiedehopf und die Fledermaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'Und alles kriechende Gevögel sei euch unrein. Man darf es nicht essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Alles reine Gevögel dürft ihr essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Kein Aas sollt ihr essen. Dem Fremdling, der in deinen Toren ist, magst du es geben, daß er es esse, oder verkaufe es einem Auswärtigen; denn du bist ein heiliges Volk Jehovah, deinem Gott. Das Böcklein sollst du nicht in der Milch seiner Mutter kochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Du sollst verzehnten allen Ertrag deiner Saat, das, was aus dem Felde ausgeht Jahr für Jahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'Und du sollst vor Jehovah, deinem Gott, an dem Ort, den Er erwählen wird, Seinen Namen daselbst wohnen zu lassen, essen den Zehnten deines Korns, deines Mostes und deines Öls, und die Erstlinge deines Rindviehs und deines Kleinviehs, auf daß du lernest Jehovah, deinen Gott, fürchten alle Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'Und wenn dir des Weges zu viel ist, daß du es nicht hinzutragen vermagst, weil der Ort, den Jehovah, dein Gott, erwählen wird, Seinen Namen daselbst einzusetzen, zu fern für dich ist, wenn dich Jehovah, dein Gott, gesegnet hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'So gib es in Silber und fasse das Silber in deine Hand und gehe an den Ort, den Jehovah, dein Gott, Sich wird erwählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'Und das Silber magst du geben für alles, was deine Seele gelüstet, für Rindvieh und für Kleinvieh, und für Wein und für starkes Getränk, und für alles, nach dem deine Seele verlangt, und sollst essen daselbst vor Jehovah, deinem Gott, und fröhlich sein, du und dein Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Und den Leviten, der in deinen Toren ist, ihn sollst du nicht verlassen; denn er hat keinen Teil und kein Erbe mit dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Am Ende dreier Jahre sollst du herausbringen all den Zehnten deines Ertrages in diesem Jahr und ihn niederlegen in deinen Toren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'Und der Levite, weil er kein Teil und Erbe mit dir hat, komme, und der Fremdling, und die Waise und die Witwe, die in deinen Toren sind, und sie sollen essen und satt werden, damit Jehovah, dein Gott, dich segne in allem Tun deiner Hand, das du tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Am Ende von sieben Jahren sollst du einen Erlaß machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'Und dies ist das Wort des Erlasses: Jeder Schuldherr soll seine Hand in demselben ablassen von dem Darlehen, das er seinem Genossen gemacht, er soll es nicht eintreiben von seinem Genossen und seinem Bruder; denn dem Jehovah hat man einen Erlaß ausgerufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'Vom Auswärtigen magst du eintreiben, was du aber bei deinem Bruder hast, das soll deine Hand erlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Es sei denn, daß unter dir kein Dürftiger ist; denn Jehovah wird dich segnen in dem Lande, das Jehovah, dein Gott, dir zum Erbe einzunehmen gibt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'Nur wenn du auf die Stimme Jehovahs, deines Gottes, hörst, so daß du hältst und tust all dies Gebot, das ich dir heute gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Denn Jehovah, dein Gott, hat dich gesegnet, wie Er zu dir geredet hat, so daß du vielen Völkerschaften borgen und nichts von ihnen borgen, und über viele Völkerschaften herrschen wirst, sie aber werden nicht herrschen über dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Wenn unter dir ein Dürftiger ist, einer deiner Brüder in einem deiner Tore in deinem Land, das Jehovah, dein Gott, dir gibt, so sollst du dein Herz nicht verstocken und deine Hand nicht vor deinem dürftigen Bruder zudrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'Vielmehr sollst du deine Hand ihm auftun, und ihm borgen je nach seinem Mangel, worin er mangelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Hüte dich, daß nicht in deinem Herzen das Wort Belials sei: das sagt: Das siebente Jahr nahet, das Jahr des Erlasses; und dein Auge deinem dürftigen Bruder böse sei, daß du es ihm nicht gebest und er über dich zu Jehovah rufe, so daß es dir zur Sünde werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Geben sollst du es ihm, und dein Herz soll nicht erbosen, daß du es ihm gibst; denn wegen dieses Wortes wird Jehovah, dein Gott, dich segnen in all deinem Tun, und in allem, wonach du die Hand ausreckst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Denn Dürftige werden niemals aufhören von des Landes Mitte. Deshalb gebiete ich dir und spreche: Tue deine Hand auf deinem Bruder, dem Elenden und dem Dürftigen in deinem Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Wenn sich dein Bruder, ein Hebräer oder eine Hebräerin, an dich verkauft, so soll er sechs Jahre dir dienen, im siebenten Jahre aber sollst du ihn frei von dir entlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'Und wenn du ihn frei entlässest von dir, so entlasse ihn nicht leer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'Du sollst ihm aufladen von deinem Kleinvieh und von deiner Tenne und von deiner Weinkufe, womit Jehovah, dein Gott, dich gesegnet hat, sollst du ihm geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'Und gedenke, daß du ein Knecht warst in Ägyptenland, und Jehovah, dein Gott, dich eingelöst hat. Deshalb gebiete ich dir dies Wort heute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'So es aber geschieht, daß er zu dir spricht: Ich will nicht von dir ausgehen, weil Ich dich und dein Haus liebe, - weil es ihm gut geht bei dir;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'So nimm eine Pfrieme und treibe sie durch sein Ohr und die Tür; und er soll dein Knecht sein ewiglich, und auch deiner Magd sollst du also tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Und laß es dir nicht hart sein in deinen Augen, wenn du ihn frei entlässest von dir; denn das Doppelte von eines Lohnarbeiters Lohn hat er dir gedient sechs Jahre, und Jehovah, dein Gott, wird dich segnen in allem, was du tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Alles Erstgeborene, das dir geboren wird von deinem Rindvieh oder von deinem Kleinvieh, sollst du, wenn es männlich ist, Jehovah, deinem Gotte, heiligen. Du sollst nicht arbeiten mit dem Erstgeborenen deines Ochsen, noch scheren das Erstgeborene deines Kleinviehs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Vor Jehovah, deinem Gotte, sollst du es essen Jahr für Jahr an dem Orte, den Jehovah erwählen wird, du und dein Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Und so daran ein Makel ist, so es lahm oder blind ist, irgendein böser Makel, sollst du es Jehovah, deinem Gotte, nicht opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'In deinen Toren magst du es essen, der Unreine und der Reine zugleich, wie das Reh und wie den Hirsch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'Nur sein Blut sollst du nicht essen; auf die Erde sollst du es ausgießen, wie das Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Halte den Monat Abib, und bereite das Passah Jehovah, deinem Gott, denn im Monat Abib hat Jehovah, dein Gott, dich ausgeführt aus Ägypten in der Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Und du sollst Jehovah, deinem Gott, das Passah opfern, Kleinvieh und Rind, an dem Orte, den Jehovah erwählen wird, Seinen Namen allda wohnen zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Du sollst an ihm nichts Gesäuertes essen, sieben Tage sollst du an ihm essen ungesäuertes Brot des Elends; denn in Hast bist du aus Ägyptenland ausgegangen, auf daß du gedenkst des Tages, da du auszogst aus Ägypten- land, alle Tage deines Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'Und man soll in sieben Tagen keinen Sauerteig in all deinen Grenzen sehen, und nichts von dem Fleisch, das du am Abend am ersten Tage opferst, soll über Nacht bis zum Morgen bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Du vermagst nicht das Passah zu opfern in einem der Tore, die Jehovah, dein Gott, dir geben wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'Sondern am Orte, den Jehovah, dein Gott, erwählt, Seinen Namen allda wohnen zu lassen, sollst du das Passah opfern am Abend beim Untergang der Sonne, zur bestimmten Zeit, da du aus Ägypten zogst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'Und sollst es kochen und essen am Orte, den Jehovah, dein Gott, erwählt, und dann dich wenden am Morgen und nach deinen Zelten gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Sechs Tage sollst du Ungesäuertes essen, und am siebenten Tag ist Festversammlung Jehovah, deinem Gott. Da sollst du keine Arbeit tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sieben Wochen sollst du dir zählen. Von da an, wo die Sichel anfängt an die stehende Saat zu kommen, sollst du anfangen sieben Wochen zu zählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Und du sollst das Fest der Wochen feiern Jehovah, deinem Gott, mit der freiwilligen Schatzung deiner Hand, die du gibst, je wie Jehovah, dein Gott, dich gesegnet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'Und sollst fröhlich sein vor Jehovah, deinem Gott, du und dein Sohn und deine Tochter und dein Knecht und deine Magd und der Levit, der in deinen Toren ist, und der Fremdling und die Waise und die Witwe, die in deiner Mitte sind, an dem Orte, den Jehovah, dein Gott, erwählt, Seinen Namen allda wohnen zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'Und sollst gedenken, daß du ein Knecht warst in Ägypten, und sollst diese Satzungen halten und tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Das Fest der Laubhütten sollst du feiern sieben Tage, wenn du einsammelst von deiner Tenne und von deiner Kelter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'Und sollst fröhlich sein an deinem Feste, du, dein Sohn und deine Tochter, und dein Knecht und deine Magd und der Levit und der Fremdling und die Waise und die Witwe, die in deinen Toren sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Sieben Tage sollst du das Fest feiern Jehovah, deinem Gott, an dem Orte, den Jehovah erwählt; denn Jehovah, dein Gott, wird dich segnen in all deinem Ertrag und in allem Tun deiner Hände; und du sollst nur fröhlich sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Dreimal im Jahr soll alles, was männlich bei dir ist, vor dem Angesicht Jehovahs, deines Gottes, erscheinen an dem Orte, den Er Sich erwählt, am Fest des Ungesäuerten und am Fest der Wochen und am Laubhüttenfest, und soll vor dem Angesichte Jehovahs nicht leer erscheinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'Jeder Mann nach der Gabe seiner Hand, je nach dem Segen Jehovahs, deines Gottes, den Er dir gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Richter und Vorsteher sollst du dir setzen in all deinen Toren, die Jehovah, dein Gott, dir geben wird, nach deinen Stämmen, auf daß sie richten das Volk mit dem Gerichte der Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Du sollst das Recht nicht ablenken, keine Person ansehen und kein Geschenk nehmen; denn das Geschenk blendet die Augen der Weisen und verdreht die Worte der Gerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Der Gerechtigkeit, der Gerechtigkeit sollst du nachsetzen, auf daß du lebest und einnehmest das Land, das Jehovah, dein Gott, dir geben wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Keine Aschere von irgendeinem Holze sollst du dir pflanzen, neben dem Altar Jehovahs, deines Gottes, den du dir machst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Auch sollst du dir keine Bildsäulen aufrichten, die Jehovah, dein Gott, hasset.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Du sollst Jehovah, deinem Gotte, keinen Ochsen oder Schaf opfern, an dem ein Makel oder irgend etwas Böses ist; denn es ist Jehovah, deinem Gott, ein Greuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Wenn in deiner Mitte, in einem deiner Tore, die Jehovah, dein Gott, dir gibt, sich ein Mann oder eine Frau findet, die tun, was böse ist in den Augen Jehovahs, deines Gottes, so daß sie Seinen Bund überschreiten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'Und ginge und diente anderen Göttern und betete sie an, und die Sonne oder den Mond oder das ganze Himmelsheer, was ich nicht geboten habe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'Und es wird dir angesagt, und du hast es gehört und wohl nachgefragt, und siehe, das Wort ist richtig und wahr, und dieser Greuel ist getan worden in Israel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'So sollst du diesen Mann oder diese Frau, die dieses Böse getan haben, hinaus an deine Tore führen, den Mann oder die Frau, und sie steinigen mit Steinen, daß sie sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Auf zweier Zeugen Mund oder dreier Zeugen soll der zu Tötende sterben. Auf eines Zeugen Mund soll er nicht sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Die Hand der Zeugen sei zuerst an ihm, ihn zu töten, und die Hand des ganzen Volkes hinten nach. So sollst du das Böse wegschaffen aus deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Ist dir eine Sache des Gerichts zu schwierig zu richten, zwischen Blut und Blut, zwischen Rechtssache und Rechtssache, zwischen Schlag und Schlag in Sachen der Rechtshändel in deinen Toren, so mache dich auf und zieh hinauf nach dem Orte, den Jehovah, dein Gott, erwählen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'Und gehe hinein zu den Priestern, den Leviten und zu dem Richter, der in jenen Tagen sein wird, und frage nach, auf daß sie dir ansagen das Wort des Gerichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Und tue nach dem Worte, das sie dir ansagen werden von jenem Orte, den Jehovah erwählt, und halte darauf, zu tun nach allem, das sie dir weisen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Nach dem Ausspruch des Gesetzes, den sie dir weisen, und dem Recht, das sie dir sprechen, sollst du tun, und von dem Worte, das sie dir ansagen, weder zur Rechten noch zur Linken abweichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Und der Mann, der in Vermessenheit handelt, daß er nicht auf den Priester, der da steht, Jehovah, deinem Gotte, dort Dienst zu tun, oder auf den Richter hört, dieser Mann soll sterben, und du sollst das Böse wegschaffen aus Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'Und das ganze Volk höre und fürchte sich, und sei nicht mehr vermessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Wenn du hineinkommst in das Land, das Jehovah, dein Gott, dir gibt, und es einnimmst, und darin wohnst, und du sprichst: Ich will einen König über mich setzen, wie alle die Völkerschaften, rings um mich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'So magst du immerhin einen König über dich setzen, den Jehovah, dein Gott, erwählen wird. Aus deiner Brüder Mitte sollst du dann einen König über dich setzen. Du vermagst nicht einen ausländischen Mann, der nicht dein Bruder ist, über dich setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Nur soll er Pferde bei sich nicht vermehren, noch das Volk zurück nach Ägypten führen, um die Pferde zu vermehren; denn Jehovah sprach zu euch, ihr sollt nicht ferner mehr zurückkehren auf diesem Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Auch soll er sich nicht Weiber mehren, auf daß sein Herz nicht abweiche, noch soll er Silber und Gold sehr mehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'Und es soll sein, wenn er auf seinem Königsthrone sitzt, soll er sich eine Abschrift dieses Gesetzes in ein Buch schreiben vor den Priestern, den Leviten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'Und sie soll bei ihm sein, und er soll darin lesen alle Tage seines Lebens, auf daß er lerne Jehovah, seinen Gott, fürchten, und halten alle Worte dieses Gesetzes und diese Satzungen, sie zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'Auf daß sein Herz sich nicht erhöhe über seine Brüder, und daß er nicht vom Gebot abweiche weder zur Rechten noch zur Linken, auf daß er seine Tage verlängere in seinem Königtum, er und seine Söhne in Israels Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Die Priester, die Leviten, der ganze Stamm Levi soll keinen Teil und Erbe mit Israel haben. Die Feueropfer Jehovahs und sein Erbe sollen sie essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Aber ein Erbe soll er nicht haben in seiner Brüder Mitte. Jehovah ist sein Erbe, wie Er zu ihm geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'Und dies sei das Recht der Priester von dem Volke, von denen, die opfern das Opfer, ob Ochse, ob Kleinvieh: so gebe man dem Priester den Bug und die Kinnbacken und den Magen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Die Erstlinge deines Korns, deines Mostes und deines Öls, und die Erstlinge der Schur deines Kleinviehs sollst du ihm geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Denn ihn hat Jehovah, dein Gott, aus allen deinen Stämmen erwählt, daß er stehe, um Dienst zu tun im Namen Jehovahs, er und seine Söhne alle Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Und so der Levite hereinkommt aus einem deiner Tore von ganz Israel, wo er sich aufhält, und kommt nach allem Gelüsten seiner Seele zu dem Ort, den Jehovah erwählen wird,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'Und tut den Dienst im Namen Jehovahs, seines Gottes, wie alle seine Brüder, die Leviten, die dort stehen vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'So sollen sie zu gleichen Teilen essen, außer dem Verkauften von seinen Vätern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'So du in das Land hereinkommst, das Jehovah, dein Gott, dir gibt, sollst du nicht lernen zu tun nach den Greueln dieser Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Nicht soll bei dir gefunden werden einer, der seinen Sohn und seine Tochter durch das Feuer durchgehen läßt, der Wahrsagerei treibt, ein Wolkendeuter und ein Beschwörer und ein Zauberer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'Ein Bannsprecher, ein Geisterfrager, ein Zeichendeuter, einer, der Tote befragt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Denn ein jeder, der solches tut, der ist Jehovah ein Greuel, und dieser Greuel wegen treibt Jehovah, dein Gott, sie vor dir aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Untadelig sollst du sein mit Jehovah, deinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Denn diese Völkerschaften, die du austreibst, hörten auf Wolkendeuter und auf Wahrsager, dir aber hat Jehovah, dein Gott, solches nicht gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Einen Propheten wie mich wird Jehovah, dein Gott, dir aus deiner Mitte von deinen Brüdern erstehen lassen. Ihn sollt ihr hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'Nach allem, das du am Choreb am Tage der Versammlung von Jehovah, deinem Gott, dir erbatest, da du sprachst: Ich will nicht weiter die Stimme Jehovahs, meines Gottes, hören, und das große Feuer da nicht ferner sehen, daß ich nicht sterbe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'Und es sprach zu mir Jehovah: Es ist gut, was sie reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Und will ihnen aus ihrer Brüder Mitte einen Propheten erstehen lassen wie du, und Meine Worte will Ich ihm in den Mund geben, auf daß er alles zu ihnen rede, was Ich ihm gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'Und es wird geschehen, daß von dem Mann, der nicht auf Meine Worte hört, die er in Meinem Namen reden soll, Ich es von ihm fordern werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Der Prophet aber, der sich vermißt, ein Wort zu reden in Meinem Namen, das Ich ihm nicht geboten habe zu reden, und der im Namen anderer Götter redet, derselbe Prophet soll sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'Und wenn du sprichst in deinem Herzen: Wie sollen wir erkennen das Wort, das Jehovah nicht zu ihm geredet hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'Was der Prophet im Namen Jehovahs reden wird, und das Wort geschieht nicht und kommt nicht, das ist das Wort, das Jehovah nicht geredet hat. Mit Vermessenheit hat es der Prophet geredet. Laß dir vor ihm nicht bange sein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Wenn Jehovah, dein Gott, die Völkerschaften, deren Land Jehovah, dein Gott, dir geben wird, ausrottet, und du sie austreibst und in ihren Städten und in ihren Häusern wohnst,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'Sollst du dir inmitten deines Landes, das Jehovah, dein Gott, dir gibt es einzunehmen, drei Städte ausscheiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Mache dir den Weg bereit und teile die Grenze deines Landes, das Jehovah, dein Gott, dir zum Erbe austeilt, in drei Teile, so daß jeder Totschläger dahin fliehen kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'Und das soll die Sache sein mit dem Totschläger, der dahin fliehen darf, damit er lebe: Wer seinen Genossen erschlägt unwissentlich und ohne daß er ihn haßte von gestern und ehegestern;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'Und wer mit seinem Genossen in den Wald hineingeht, um Holz zu hauen, und seine Hand holt aus mit der Axt, den Baum abzuhauen, und das Eisen fährt ab vom Holz und trifft seinen Genossen, daß er stirbt, der fliehe in eine dieser Städte, auf daß er lebe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'Auf daß nicht der Bluträcher dem Totschläger nachsetze, da sein Herz erhitzt ist und ihn erreiche, wenn ihm der Weg zu viel ist, und schlage ihn am Leben, so doch kein Gericht des Todes an ihm ist, weil er keinen Haß gegen ihn hatte von gestern und ehegestern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Darum gebiete ich dir und spreche: Drei Städte sollst du dir ausscheiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'Und wenn Jehovah, dein Gott, deine Grenze erweitert, wie Er deinen Vätern geschworen und dir all das Land gibt, das Er deinen Vätern zu geben geredet hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'So du hältst all dieses Gebot, es zu tun, das ich dir heute gebiete, daß du Jehovah, deinen Gott, liebst und in Seinen Wegen wandelst alle Tage; so sollst du dir zu diesen dreien noch drei Städte hinzutun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'Auf daß nicht unschuldig Blut vergossen werde inmitten deines Landes, das Jehovah, dein Gott, dir zum Erbe gibt, und Blut auf dir sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'Wenn aber ein Mann einen Haß hat wider seinen Genossen und liegt im Hinterhalt gegen ihn und macht sich über ihn auf und schlägt ihn am Leben, daß er stirbt und flieht in eine dieser Städte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'So sollen die Ältesten seiner Stadt senden und ihn von dannen nehmen, und ihn geben in des Bluträchers Hand, daß er sterbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Dein Auge schone seiner nicht, auf daß du wegschaffst das Blut des Unschuldigen aus Israel und es gut mit diesem sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Du sollst nicht verrücken deines Nächsten Grenze, welche die Vorfahren abgegrenzt haben auf deinem Erbe, das du erbst in dem Lande, das Jehovah, dein Gott, dir zum Erbbesitze gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Nicht soll ein einzelner Zeuge aufstehen wider einen Mann ob irgendeiner Missetat und irgendeiner Sünde, über irgendeine Sünde, womit man sündigt. Durch den Mund zweier Zeugen oder den Mund dreier Zeugen soll ein Wort bestätigt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'So ein Zeuge der Gewalttat aufsteht wider einen Mann, um wider ihn wegen eines Abfalls zu bezeugen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'So sollen die beiden Männer, die einen Rechtshandel haben, vor Jehovah stehen, vor die Priester und die Richter, die in selbigen Tagen sein werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'Und die Richter sollen wohl untersuchen. Und siehe, ist der Zeuge ein lügenhafter Zeuge und hat Lügen geantwortet wider seinen Bruder,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'So sollt ihr ihm tun, wie er sann, seinem Bruder zu tun, und du sollst wegschaffen das Böse aus deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'Auf daß die Übrigbleibenden es hören und sich fürchten und solches Böse nicht weiter tun in deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'Und dein Auge schone nicht. Seele um Seele, Auge um Auge, Zahn um Zahn, Hand um Hand, Fuß um Fuß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Wenn du zum Streite ausgehst wider deinen Feind und siehst Roß und Wagen und mehr Volk als du, so fürchte dich nicht vor ihnen, denn Jehovah, dein Gott, Der dich aus Ägyptenland heraufgeführt, ist mit dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'Und es geschehe, wenn ihr nahet zum Streit, da trete der Priester herzu und rede zu dem Volk,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'Und spreche zu ihnen: Höre, Israel, ihr nahet heute zum Streite wider eure Feinde. Euer Herz werde nicht weich, fürchtet nicht, seid nicht bange und es graue dir nicht vor ihnen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Denn Jehovah, euer Gott, zieht mit euch, daß Er für euch streite wider eure Feinde, euch zu retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Und die Vorsteher sollen zum Volk reden und sprechen: Wer ist der Mann, der ein neues Haus gebaut und noch nicht eingeweiht hat? Der gehe und kehre zu seinem Haus zurück, auf daß er nicht sterbe im Streite und ein anderer Mann weihe es ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Und wer ist der Mann, der einen Weinberg gepflanzt und noch nicht von ihm genossen hat? Der gehe und kehre zurück zu seinem Haus, auf daß er nicht sterbe im Streite und ein anderer ihn genieße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'Und wer ist der Mann, der sich einem Weibe verlobt und sie noch nicht zu sich genommen hat? Der gehe und kehre zurück zu seinem Haus, auf daß er nicht sterbe im Streite und ein anderer Mann sie nehme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'Und die Vorsteher sollen weiter zum Volke reden und sprechen: Wer ist der Mann, der da Furcht hat und weichen Herzens ist? Der gehe und kehre zurück zu seinem Haus, auf daß nicht auch seiner Brüder Herz zerschmelze, wie sein Herz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'Und es geschehe, wenn die Vorsteher zu Ende sind mit dem Reden zum Volke, dann sollen sie die Obersten der Heerscharen an die Spitze des Volkes stellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Wenn einer Stadt du nahest, um wider sie zu streiten, so rufe sie zum Frieden auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Und es geschehe, so sie friedlich ant- wortet und öffnet dir, so soll alles Volk, das sich in ihr findet, dir zinsbar sein und dir dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Will sie aber nicht friedlich mit dir handeln und führt Streit wider dich und du belagerst sie,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'Und Jehovah, dein Gott, gibt sie in deine Hand, so sollst du alles, was männlich ist darinnen, mit der Schärfe des Schwertes schlagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'Nur die Weiber und die Kindlein und das Vieh, und alles, was in der Stadt ist, alle ihre Beute magst du dir rauben und verzehren die Beute deiner Feinde, die Jehovah, dein Gott, dir gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'So sollst du allen Städten tun, die sehr fern von dir und die nicht unter den Städten dieser Völkerschaften hier sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Hingegen in den Städten dieser Völker, die Jehovah, dein Gott, dir zum Erbe gibt, sollst du keines von allem, das Odem hat, leben lassen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'Sondern sie sollst du ganz und gar verbannen, den Chethiter und den Amoriter, den Kanaaniter und den Pherisiter, den Chiviter und den Jebusiter, wie Jehovah, dein Gott, geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'Daß sie euch nicht lehren zu tun nach all ihren Greueln, den sie ihren Göttern tun, und ihr an Jehovah, eurem Gott, sündigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Wenn du eine Stadt viele Tage belagerst, so daß du wider sie streitest, um sie zu gewinnen, so sollst du ihre Bäume nicht verderben, daß du mit der Axt dagegen ausholst; denn du kannst davon essen, und darum sollst du sie nicht ausrotten; ist denn der Baum des Feldes ein Mensch, daß er vor dir in Belagerung komme?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Nur einen Baum, von dem du weißt, daß er kein Baum ist, von dem man ißt, ihn magst du verderben und ausrotten, und daraus bauen ein Bollwerk wider die Stadt, die mit dir Streit führt, bis du sie unterwirfst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Wenn ein Erschlagener, auf dem Felde gefallen, gefunden wird auf dem Boden, den dir Jehovah, dein Gott, gibt einzunehmen, und man nicht weiß, wer ihn erschlagen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'So sollen deine Ältesten und deine Richter hinausgehen und messen nach den Städten hin, die rings um den Erschlagenen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Und es soll geschehen, daß, welche Stadt dem Erschlagenen die nächste ist, derselben Stadt Älteste sollen eine Kalbe vom Rind nehmen, mit der noch nicht gearbeitet worden, die noch an keinem Joche gezogen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'Und die Ältesten dieser Stadt sollen die Kalbe hinabbringen an einen Bach, der nicht bebaut noch besät wird, und dort der Kalbe das Genick brechen in den Bach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Und es sollen hinzutreten die Priester, die Söhne Levis, denn sie hat erwählt Jehovah, dein Gott, Ihm Dienst zu tun und im Namen Jehovahs zu segnen, und nach ihrem Munde geschehe jeder Rechtshandel und Schlag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'Und alle Ältesten derselben Stadt, die dem Erschlagenen am nächsten sind, sollen ihre Hände waschen über der Kalbe, der im Bach das Genick gebrochen worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'Und sollen antworten und sprechen: Unsere Hände haben dies Blut nicht vergossen und unsere Augen haben es nicht gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Sühne dein Volk Israel, das Du eingelöst hast, o Jehovah, und bringe nicht unschuldig Blut inmitten deines Volkes Israel. So sollen sie von dem Blute gesühnt sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Und du sollst das unschuldige Blut aus deiner Mitte wegschaffen wenn du tust, was recht ist in den Augen Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'So du ausgehst zum Streite wider deine Feinde, und Jehovah, dein Gott, ihn in deine Hand gibt, und du von ihm gefangen nimmst,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'Und siehst unter den Gefangenen ein Weib, schön von Gestalt, und hast Gefallen an ihr und nimmst sie dir zum Weibe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'So bringe sie hinein in deines Hauses Mitte; und laß sie ihr Haupt scheren und ihre Nägel zurechtmachen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'Und sie lege ab von sich das Gewand ihrer Gefangenschaft und sitze in deinem Haus und beweine ihren Vater und ihre Mutter einen Monat der Tage. Und danach gehe ein zu ihr, werde ihr Gemahl und sie sei dir zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Und es geschehe, wenn du keine Lust an ihr hast, so entlasse sie nach ihrem Begehr, darfst sie aber nicht um Silber verkaufen, noch sie mißhandeln, weil du sie geschwächt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'So ein Mann zwei Weiber hat, die eine geliebt und die andere gehaßt, und sie ihm Söhne gebären, die Geliebte und die Gehaßte, und der erstgeborene Sohn der gehaßten gehört,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'So vermag er am Tage, da er seinen Söhnen das Erbe austeilt, das er hat, den Sohn der Geliebten nicht zum Erstgeborenen zu machen, vor dem Sohne der Gehaßten, des Erstgeborenen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'Sondern muß den Erstgeborenen, den Sohn der Gehaßten anerkennen und ihm zwiefältig geben von allem, das sich bei ihm findet, denn er ist der Anfang seiner Vollkraft; er hat das Recht der Erstgeburt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'So ein Mann einen eigenwilligen und widerspenstigen Sohn hat, der nicht auf seines Vaters Stimme, noch auf seiner Mutter Stimme hört, und sie ihn züchtigen, er aber nicht auf sie hört,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'So sollen ihn sein Vater und seine Mutter erfassen und ihn hinausführen zu den Ältesten seiner Stadt und zu dem Tor seines Ortes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'Und sollen sprechen zu den Ältesten seiner Stadt: Unser Sohn da ist eigenwillig und widerspenstig, er hört nicht auf unsere Stimme, ist ein Schlemmer und ein Zecher;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Und sollen ihn steinigen mit Steinen alle Männer seiner Stadt, daß er stirbt, auf daß du wegschaffest das Böse aus deiner Mitte; und ganz Israel, sie sollen es hören und sich fürchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'Und so in einem Manne eine Sünde ist, die todeswürdig ist, und er getötet wird und du ihn anhängst an das Holz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'So soll sein Leichnam nicht über Nacht an dem Holze bleiben; sondern du sollst ihn begraben an demselben Tag, denn ein Fluch Gottes ist ein Gehenkter. Und du sollst nicht verunreinigen deinen Boden, den dir Jehovah, dein Gott, zum Erbe gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Du sollst den Ochsen deines Bruders oder sein Kleinvieh nicht sich verlaufen sehen und dich denselben entziehen, sondern sie zurück zu deinem Bruder bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Und ist dein Bruder nicht nahe bei dir, und du kennst ihn nicht, so nimm sie zu dir mitten in dein Haus, daß es bei dir sei, bis dein Bruder nachfragt und du es ihm zurückgibst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Und also sollst du tun mit seinem Esel, und sollst also tun mit seinem Gewand, und also tun mit allem Verlorenen deines Bruders, das von ihm verloren wird. So du es findest, vermagst du nicht dich zu entziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Du sollst den Esel deines Bruders oder seinen Ochsen nicht auf dem Wege fallen sehen und dich denselben entziehen; sondern sollst sie mit ihm aufrichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Mannesgeräte soll auf keinem Weibe sein, und das Gewand eines Weibes soll kein Mann anziehen, denn ein jeder, der solches tut, ist Jehovah, deinem Gott, ein Greuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Triffst du ein Vogelnest vor dir auf einem Weg auf irgendeinem Baum oder auf der Erde, mit einer Brut oder Eiern, und die Mutter sitzt auf der Brut oder auf den Eiern, so sollst du nicht die Mutter samt den Jungen aufnehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'Entlaß die Mutter und nimm für dich die Jungen, auf daß es dir gut ergehe und du die Tage verlängerst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Wenn du ein neues Haus baust, so mache ein Geländer um dein Dach, daß du nicht Blut ladest auf dein Haus, so jemand davon hinunterfiele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Säe nicht zweierlei in deinem Weinberg, daß nicht die Fülle des Samens, den du säst, samt dem Ertrag des Weinbergs dem Heiligtum verfalle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Du sollst nicht pflügen mit einem Ochsen und einem Esel zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Du sollst nicht anziehen Zeug von zweierlei Stoff, Wolle und Flachs zusammen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Fransen sollst du dir machen an den vier Zipfeln deines Mantels, mit dem du dich bedeckst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Wenn ein Mann ein Weib nimmt und geht ein zu ihr und haßt sie,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'Und legt ihr erdichtete Dinge bei, und bringt einen bösen Namen aus über sie und sagt: Dies Weib habe ich genommen und mich ihr genaht, aber die Jungfrauschaft bei ihr nicht gefunden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'Da sollen der Vater des Mädchens und ihre Mutter die Zeichen der Jungfrauschaft des Mädchens nehmen und zu den Ältesten der Stadt nach dem Tore hinausbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'Und der Vater des Mädchens spreche zu den Ältesten: Meine Tochter habe ich diesem Manne zum Weibe gegeben, und er haßt sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'Und siehe, er legt ihr erdichtete Dinge bei und sagt: Ich habe bei deiner Tochter die Jungfrauschaft nicht gefunden. Und das hier ist die Jungfrauschaft meiner Tochter. Und sie sollen ausbreiten das Gewand vor den Ältesten der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'Und die Ältesten dieser Stadt sollen den Mann nehmen und ihn züchtigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'Und sollen ihn büßen um hundert Schekel Silbers, und es dem Vater des Mädchens geben, weil er einen bösen Namen über eine Jungfrau Israels ausbrachte; und sie soll sein Weib sein, und er vermag nicht sie zu entlassen alle Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Ist aber dieses Wort wahr und hat sich keine Jungfrauschaft bei dem Mädchen gefunden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'So führe man das Mädchen hinaus an den Eingang von ihres Vaters Haus, und die Männer der Stadt sollen sie steinigen mit Steinen, daß sie stirbt; denn sie hat Torheit getan in Israel, daß sie in ihres Vaters Hause gebuhlt hat; und du sollst wegschaffen das Böse aus deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Wenn ein Mann gefunden wird bei einem Weibe liegen, die einem Gemahl vermählt ist, so sollen sie beide sterben, der Mann, der bei dem Weibe lag und das Weib, und du sollst wegschaffen das Böse aus Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Ist ein Mädchen, eine Jungfrau, einem Manne verlobt und ein Mann findet sie in der Stadt und liegt bei ihr,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'So sollt ihr sie beide nach dem Tore dieser Stadt hinausführen und sie steinigen mit Steinen, daß sie sterben: das Mädchen, weil sie nicht geschrien hat in der Stadt, und den Mann, weil er das Weib seines Genossen geschwächt hat. Und du sollst wegschaffen das Böse aus deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Wenn aber der Mann das verlobte Mädchen auf dem Felde findet, und der Mann faßt sie und liegt bei ihr, so soll der Mann, der bei ihr lag, alleine sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'Dem Mädchen tue aber nichts; denn auf dem Mädchen ist keine Todsünde; denn wie wenn ein Mann sich aufmacht über seinen Genossen und ihn totschlägt, so ist diese Sache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'Denn auf dem Felde hat er sie gefunden. Das verlobte Mädchen schrie, aber niemand half ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Wenn aber ein Mann ein Mädchen, eine Jungfrau, findet, die nicht verlobt ist, und sie erfaßt und liegt bei ihr und man findet sie:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'So soll der Mann, der bei ihr gelegen, dem Vater des Mädchens fünfzig Schekel Silbers geben, und sie soll sein Weib sein; weil er sie geschwächt hat, vermag er sie nicht zu entlassen alle seine Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'Kein Mann soll seines Vaters Weib nehmen, noch seines Vaters Decke aufdecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Kein Zermalmter oder an dem Gliede Verwachsener soll in die Versammlung Jehovahs kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Kein Bastard soll in die Versammlung Jehovahs kommen; auch das zehnte Geschlecht von ihm soll nicht in die Versammlung Jehovahs kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'Kein Ammoniter und kein Moabiter soll in die Versammlung Jehovahs kommen; auch das zehnte Geschlecht von ihnen soll nicht in die Versammlung Jehovahs kommen in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Darum daß sie nicht mit Brot und mit Wasser vor euch kamen auf dem Wege, da ihr aus Ägypten auszogt und daß sie gegen dich Bileam, Beors Sohn, aus Pethor in Aram der beiden Flüsse gedungen, dir zu fluchen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Aber Jehovah, dein Gott, wollte nicht hören auf Bileam, und Jehovah, dein Gott, verwandelte für dich den Fluch zum Segen, weil Jehovah, dein Gott, dich liebte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Du sollst nicht ihrem Frieden, noch ihrem Wohlergehen nachfragen all deine Tage ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Du sollst nicht den Edomiter für Greuel halten, denn er ist dein Bruder, nicht sollst du für Greuel halten den Ägypter, denn du bist ein Fremdling in seinem Lande gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Söhne, die ihnen geboren werden, dürfen im dritten Geschlecht in die Versammlung Jehovahs hineinkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Wenn du in das Lager ausziehst wider deine Feinde, so hüte dich vor jedem bösen Dinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'Wenn unter dir ein Mann nicht rein ist von einem Begegnis in der Nacht, so soll er hinaus zum Lager gehen und nicht in die Mitte des Lagers kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Und es geschehe, wenn es sich wendet gegen Abend, bade er sich im Wasser; und mit der Sonne Untergang darf er inmitten des Lagers hineinkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'Du sollst einen Platz haben außerhalb des Lagers, daß du hinausgehst dort hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Und du sollst ein Schäuflein haben bei deinen Gerätschaften, und wenn du dich draußen hinsetzest, damit graben und dich zurückwenden, zu bedecken, was von dir gegangen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Denn Jehovah, dein Gott, wandelt inmitten deines Lagers, dich zu erretten und deine Feinde vor dir hinzugeben. Und dein Lager soll heilig sein, auf daß Er keine Blöße bei dir sehe und Sich von dir zurückwende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Du sollst den Knecht nicht seinem Herrn überantworten, wenn er von seinem Herrn zu dir sich errettet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Laß ihn bei dir wohnen in deiner Mitte, an dem Orte, den er sich in einem deiner Tore erwählt, wo es ihm gut dünkt, und sollst ihn nicht bedrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Es soll kein Buhlmädchen sein unter den Töchtern Israels, noch ein Buhlknabe unter den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Du sollst nicht den Lohn einer Buhlerin oder den Preis eines Hundes für irgendein Gelübde in das Haus Jehovahs, deines Gottes, bringen, denn beides ist ein Greuel Jehovah, deinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Du sollst nicht Zins nehmen von deinem Bruder, Zins an Silber, Zins an Speise, Zins von sonst etwas, das man verzinsen kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Vom Ausländer magst du Zins nehmen, aber von deinem Bruder sollst du keinen Zins nehmen; auf daß Jehovah, dein Gott, dich segne in allem, wo du deine Hand ausreckst in dem Lande, in das du hineinkommen sollst, es einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Wenn du Jehovah, deinem Gott, ein Gelübde gelobst, so sollst du nicht zögern, es zu vollbringen; denn Jehovah, dein Gott, wird es fordern von dir, und es wird dir zu Sünde werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Wenn du unterlässest zu geloben, so ist es dir keine Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Was von deinen Lippen ausgeht, das halte und tue, wie du Jehovah, deinem Gott, freiwillig gelobt hast, was du mit deinem Munde geredet hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Wenn du in deines Genossen Weinberg kommst, so magst du Weinbeeren essen nach deinem Begehr, bis du satt bist, aber du sollst keine in dein Gefäß tun. Wenn du in die stehende Saat deines Genossen kommst, so magst du mit deiner Hand Ähren abpflücken; aber die Sichel sollst du nicht über die stehende Saat deines Genossen schwingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Wenn ein Mann ein Weib nimmt und sich ihr vermählt, und es geschieht, daß sie nicht Gnade findet in seinen Augen, weil er eine Blöße an ihr gefunden hat, daß er einen Scheidebrief schreibt und in ihre Hand gibt und sie aus seinem Haus entläßt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Und sie aus seinem Hause ausgeht, und geht und eines anderen Mannes wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'Und der andere Mann sie auch haßt und ihr einen Scheidebrief schreibt, und selben ihr in die Hand gibt, und sie aus seinem Haus entläßt, oder wenn der andere Mann stirbt, der sie sich zum Weibe genommen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'So kann ihr erster Gemahl, der sie entließ, nicht umkehren, sie zu nehmen, daß sie sein Weib sei, nachdem sie verunreinigt worden war, denn ein Greuel ist es vor Jehovah, und du sollst keine Sünde bringen über das Land, das Jehovah, dein Gott, dir zum Erbe gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'So ein Mann ein neues Weib genommen hat, so soll er nicht ausziehen in das Heer, noch soll man etwas über ihn entgehen lassen. Er soll bürdelos sein für sein Haus für ein Jahr, und fröhlich sein mit seinem Weib, das er genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Man soll nicht Mühle und Mühlstein pfänden, denn die Seele pfändet man damit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Wenn ein Mann gefunden wird, der eine Seele stiehlt von seinen Brüdern, von den Söhnen Israel, und ihn mißhandelt und ihn verkauft, so soll selbiger Dieb sterben, auf daß du wegschaffst das Böse aus deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Hüte dich vor der Plage des Aussatzes, daß du sehr haltest und tuest nach allem dem, was die Priester, die Leviten, euch weisen. Wie ich denselben geboten habe, sollt ihr halten es zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Gedenke, was Jehovah, dein Gott, tat der Mirjam auf dem Wege, da ihr aus Ägypten ausginget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Wenn du deinen Genossen irgendein Darlehn ausleihst, so sollst du nicht in sein Haus hineingehen, um ein Pfand von ihm zu pfänden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'Draußen sollst du stehen, und der Mann, dem du ausleihst, soll dir das Pfand hinausbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'Und wenn der Mann im Elend ist, sollst du dich nicht niederlegen mit seinem Pfande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'Du sollst ihm das Pfand zurückgeben, so wie die Sonne untergeht, auf daß er in seinem Gewande sich lege und dich segne; und dir wird es zur Gerechtigkeit vor Jehovah, deinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Du sollst den elenden und dürftigen Tagelöhner nicht unterdrücken, sei er von deinen Brüdern, oder von deinem Fremdling, der in deinem Lande in deinen Toren ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'An seinem Tage sollst du seinen Lohn geben, und die Sonne soll nicht darüber untergehen, denn er ist im Elend, und seine Seele erhebt sich danach; auf daß er nicht über dich zu Jehovah rufe und dir es zur Sünde werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Die Väter sollen nicht sterben um der Söhne willen, und die Söhne sollen nicht um der Väter willen sterben. Jeder Mann soll für seine Sünde sterben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Du sollst dem Fremdling und der Waise, das Recht nicht abwenden, noch der Witwe das Kleid pfänden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'Und gedenken, daß du ein Knecht in Ägypten warst, und daß dich Jehovah, dein Gott, von dannen eingelöst hat. Darum gebiete ich dir, dieses Wort zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Wenn du auf deinem Felde die Ernte eingeerntet und eine Garbe auf dem Felde vergessen hast, sollst du nicht zurückkehren, sie zu holen. Dem Fremdling, der Waise und der Witwe soll sie sein, auf daß dich Jehovah, dein Gott, segne in allem Tun deiner Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Wenn du deine Olive abgeschlagen, sollst du nicht hinter dir nachpflücken. Dem Fremdling, der Waise und der Witwe soll es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Wenn du deinen Weinberg abgelesen, sollst du nicht hinter dir nachlesen. Dem Fremdling, der Waise und der Witwe soll es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'Und du sollst gedenken, daß du ein Knecht warst in Ägyptenland; darum gebiete ich dir, dies Wort zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Wenn Hader ist unter Männern, so sollen sie zum Gericht herzutreten, auf daß man sie richte, und den Gerechten rechtfertige und den Ungerechten verdamme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'Und es soll geschehen, so der Ungerechte Schläge verdient, der Richter ihn niederfallen lasse, auf daß man ihn schlage vor ihm, an Zahl nach dem Maße seines Unrechts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Vierzig Schläge gebe man ihm und tue nichts hinzu; auf daß nicht durch weiteres Schlagen der Schläge viel werden, und dein Bruder vor deinen Augen gering geachtet werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Du sollst dem Ochsen, der da drischt, nicht das Maul zubinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Wenn Brüder zusammen wohnen, und einer von ihnen stirbt und hat keinen Sohn, so soll das Weib des Toten nicht draußen eines fremden Mannes werden. Ihr Schwager soll zu ihr eingehen und sie sich zum Weibe nehmen, und ihr Schwagerpflicht leisten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'Und es soll geschehen, daß der Erstgeborene, den sie gebiert, auf den Namen seines toten Bruders erstehe, und sein Name nicht aus Israel ausgewischt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Hat aber der Mann keine Lust, seine Schwägerin zu nehmen, so soll seine Schwägerin hinaufgehen nach dem Tor zu den Ältesten und sprechen: Mein Schwager weigert sich, seinem Bruder einen Namen in Israel aufzurichten; er will mir nicht Schwagerpflicht leisten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Und sollen die Ältesten seiner Stadt ihn rufen und zu ihm reden; und so er steht und spricht: Ich habe nicht Lust, sie zu nehmen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'So soll seine Schwägerin vor den Augen der Ältesten zu ihm herzutreten und ihm den Schuh von seinem Fuß ausziehen und ihm ins Gesicht spucken und antworten und sprechen: So tue man dem Manne, der das Haus seines Bruders nicht baut!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'Und sein Name soll in Israel heißen: Des Barfüßlers Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Wenn Männer miteinander zanken, ein Mann und sein Bruder, und das Weib des einen naht sich, ihren Mann aus der Hand des Schlagenden zu erretten, und ihre Hand ausreckt und ihn bei seiner Scham faßt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'So sollst du ihr die Hand abschneiden, dein Auge soll nicht schonen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Du sollst nicht zweierlei Gewichtsteine in deinem Beutel tragen, einen großen und einen kleinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Du sollst nicht zweierlei Epha, ein großes und ein kleines, in deinem Hause haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Ganze und gerechte Gewichtsteine sollst du haben; und ein ganzes, gerechtes Epha sollst du haben, auf daß deine Tage verlängert werden auf dem Boden, den Jehovah, dein Gott, dir gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Denn ein Greuel ist Jehovah, deinem Gott, ein jeglicher, der solches tut, ein jeglicher, der Verkehrtes tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Gedenke, was Amalek dir tat auf dem Wege, da du aus Ägypten auszogst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'Wie er dir begegnete auf dem Wege und hinter dir alle Schwächlinge abschnitt, da du matt und müde warst, und er Gott nicht fürch- tete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Und es soll geschehen, wenn dann Jehovah, dein Gott, dich zur Ruhe bringt von allen deinen Feinden ringsum in dem Lande, das Jehovah, dein Gott, dir als Erbe gibt, es erblich zu besitzen, sollst du das Andenken Amaleks unter dem Himmel auswischen. Vergiß es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Und es soll geschehen, wenn du in das Land hineinkommst, das Jehovah, dein Gott, dir zum Erbe gibt, und es einnimmst und darin wohnst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'So sollst du nehmen von den Erstlingen aller Frucht des Bodens, die du einbringst aus deinem Lande, das Jehovah, dein Gott, dir gibt, und in einen Korb legen und gehen an den Ort, den Jehovah, dein Gott, erwählt, Seinen Namen dort wohnen zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'Und sollst kommen zum Priester, der in jenen Tagen sein wird, und zu ihm sprechen: Ich sage an heute Jehovah, deinem Gott, daß ich gekommen bin in das Land, das Jehovah unseren Vätern geschworen hat, uns zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'Und der Priester soll den Korb nehmen aus deiner Hand und vor den Altar Jehovahs, deines Gottes, niederstellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'Und du sollst antworten und sprechen vor Jehovah, deinem Gott: Ein umherirrender Aramäer war mein Vater. Und er ging hinab nach Ägypten und hielt sich dort als Fremdling auf mit wenig Leuten, und ward allda zu einer Völkerschaft, groß, mächtig und viel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Aber die Ägypter taten uns Böses und bedrückten uns und legten harten Dienst auf uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'Und wir schrien zu Jehovah, dem Gott unsrer Väter, und Jehovah hörte unsere Stim- me und sah unser Elend und unsere Mühsal und unsere Unterdrückung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'Und Jehovah führte uns heraus aus Ägypten mit starker Hand und ausgerecktem Arm und mit großer Furcht, und mit Zeichen und mit Wahrzeichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'Und brachte uns herein an diesen Ort, und gab uns dieses Land, ein Land, das von Milch und Honig fließt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'Und nun siehe, ich habe hereingebracht die Erstlinge der Frucht des Bodens, den du mir gegeben hast, o Jehovah! Und du sollst es vor Jehovah, deinem Gotte, niederlegen und sollst anbeten vor Jehovah, deinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'Und sollst fröhlich sein über all das Gute, das Jehovah, dein Gott, dir und deinem Hause gegeben hat, du und der Levite und der Fremdling, der in deiner Mitte ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Wenn du vollendet hast die Verzehntung aller Zehnten deines Ertrages im dritten Jahre, dem Zehntjahre, und dem Leviten, dem Fremdling, der Waise und der Witwe gegeben hast, daß sie aßen in deinen Toren und satt wurden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'So sollst du sprechen vor Jehovah, deinem Gott: Ich habe das Geheiligte aus dem Hause weggeschafft, und auch dem Leviten und dem Fremdling, der Waise und der Witwe gegeben nach all Deinem Gebot, das Du mir geboten hast. Ich habe keines von Deinen Geboten überschritten oder vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'Ich habe nicht davon gegessen in meinem Leid, und nichts davon weggeschafft in Unreinheit, und nichts davon für einen Toten gegeben. Ich habe gehört auf die Stimme Jehovahs, meines Gottes, ich habe getan nach allem, das Du mir geboten hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Schaue von der Wohnstätte Deiner Heiligkeit, aus den Himmeln und segne Dein Volk Israel und den Boden, den Du uns gegeben hast, wie Du unseren Vätern geschworen hast, ein Land, das von Milch und Honig fließt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'An diesem Tage gebietet dir Jehovah, dein Gott, zu tun diese Satzungen und die Rechte, und du sollst sie halten und tun von deinem ganzen Herzen und von deiner ganzen Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Jehovah hast du heute zugesagt, daß Er dir Gott sei, und daß du in Seinen Wegen wandeln und Seine Satzungen und Seine Gebote und Seine Rechte halten und auf Seine Stimme hören wollest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'Und Jehovah hat dir heute zugesagt, du sollst Sein Eigentumsvolk sein, wie Er zu dir geredet hat, und sollst alle Seine Gebote halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'Und daß Er dich höher mache denn alle Völkerschaften, die Er gemacht hat, und zum Lobe und zum Namen und zum Schmucke gebe, daß du ein heiliges Volk seiest Jehovah, deinem Gotte, wie Er geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'Und es geboten Mose und die Ältesten Israels dem Volke und sprachen: Haltet all das Gebot, das ich euch heute gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'Und es geschehe, daß am Tage, da ihr über den Jordan in das Land übersetzet, das Jehovah, dein Gott, dir geben wird, so sollst du dir große Steine aufrichten und sie mit Kalk übertünchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'Und du sollst darauf alle Worte dieses Gesetzes schreiben, wenn du hinüberziehst, auf daß du in das Land eingehst, das Jehovah, dein Gott, dir gibt, ein Land, das von Milch und Honig fließt, wie Jehovah, der Gott deiner Väter, zu dir geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Und es geschehe, daß, wenn ihr über den Jordan übersetzet, sollet ihr diese Steine aufrichten, wie ich euch heute gebiete, auf dem Berge Ebal und sie mit Kalk übertünchen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'Und sollst allda einen Altar bauen Jehovah, deinem Gott, einen Altar von Steinen, du sollst kein Eisen schwingen über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Von ganzen Steinen sollst du den Altar Jehovahs, deines Gottes, bauen, und sollst Jehovah, deinem Gotte, Brandopfer darauf opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Und sollst Dankopfer opfern und allda essen und fröhlich sein vor Jehovah, deinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'Und schreibe auf diese Steine alle Worte dieses Gesetzes und präge sie wohl ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'Und Mose redete und die Priester, die Leviten, zu ganz Israel und sprachen: Merke und höre, Israel! An diesem Tage bist du Jehovah, deinem Gott, zum Volk geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Und du sollst hören auf die Stimme Jehovahs, deines Gottes, und tun Seine Gebote und Seine Satzungen, die ich dir heute gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'Und Mose gebot dem Volk an selbigem Tage und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Diese sollen auf dem Berge Gerissim stehen, um das Volk zu segnen, wenn ihr über den Jordan übersetzet: Schimeon und Levi und Judah und Issaschar und Joseph und Benjamin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'Und diese sollen stehen zum Fluche auf dem Berg Ebal: Ruben, Gad und Ascher und Sebulon, Dan und Naphthali.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'Und die Leviten sollen anheben und mit erhöhter Stimme zu jedem Mann in Israel sprechen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Verflucht sei der Mann, der ein Schnitzbild oder Gußbild macht, einen Greuel Jehovahs, ein Werk von den Händen des Werkmanns gemacht, und es insgeheim aufstellt. Und das ganze Volk antworte und spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Verflucht sei, wer seinen Vater und seine Mutter gering achtet! Und das ganze Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Verflucht sei, wer seines Genossen Grenze verrückt, und alles Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Verflucht sei, wer einen Blinden auf dem Wege fehlgehen läßt! Und das ganze Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Verflucht sei, wer dem Fremdling, der Waise und der Witwe das Recht abwendet, und das ganze Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Verflucht sei, wer bei dem Weibe seines Vaters liegt; denn er hat seines Vaters Decke aufgedeckt, und das ganze Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Verflucht sei, der bei irgendeinem Vieh liegt, und das ganze Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Verflucht, wer bei seiner Schwester, der Tochter seines Vaters oder der Tochter seiner Mutter liegt; und das ganze Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Verflucht sei, wer bei seiner Schwiegermutter liegt; und das ganze Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Verflucht sei, wer seinen Genossen heimlich erschlägt! Und das ganze Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Verflucht sei, wer Geschenk nimmt, um eine Seele, unschuldiges Blut, zu erschlagen! Und das ganze Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Verflucht sei, wer die Worte dieses Gesetzes nicht bestätigt, daß er sie tue! Und das ganze Volk spreche: Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'Und es soll geschehen, wenn du auf die Stimme Jehovahs, deines Gottes, hörst, daß du hältst und tust alle Seine Gebote, die ich dir heute gebiete, daß Jehovah, dein Gott, dich höher machen wird denn alle Völkerschaften der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'Und werden über dich kommen alle diese Segnungen und dich erreichen, wenn du hörst auf die Stimme Jehovahs, deines Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Gesegnet wirst du sein in der Stadt und gesegnet wirst du sein auf dem Feld.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Gesegnet wird sein die Frucht deines Leibes und die Frucht deines Bodens, und die Frucht deines Viehs, der Wurf deiner Rinder und die Zucht deines Kleinviehs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Gesegnet wird dein Korb sein und dein Backtrog.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Gesegnet wirst du sein in deinem Eingang und gesegnet in deinem Ausgang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Jehovah läßt deine Feinde, die wider dich aufstehen, vor dir geschlagen werden. Auf einen Weg ziehen sie gegen dich aus und auf sieben Wegen fliehen sie vor dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Jehovah entbietet den Segen in deine Speicher bei dir und in alles, wo deine Hand du ausreckst; und Er segnet dich in dem Land, das Jehovah, dein Gott, dir gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Jehovah richtet dich für Sich zu einem heiligen Volke auf, wie Er dir geschworen hat, wenn du die Gebote Jehovahs, deines Gottes, hältst und in Seinen Wegen wandelst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'Und sehen sollen alle Völker der Erde, daß Jehovahs Namen über dir genannt ist, und sich vor dir fürchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'Und Jehovah wird dir einen Überfluß geben vom Guten in der Frucht deines Leibes und in der Frucht deines Viehs, und in der Frucht deines Bodens, auf dem Boden, den dir zu geben Jehovah deinen Vätern geschworen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Öffnen wird Jehovah dir Seinen guten Schatz, die Himmel, um Regen zu geben in deinem Land zu seiner Zeit und zu segnen alles Tun deiner Hand, und du leihst vielen Völkerschaften, du aber entlehnst nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Und Jehovah wird dich machen zum Haupt und nicht zum Schwanze, daß du nur oben bist und nicht unten seiest, wenn du hörst auf Jehovahs, deines Gottes, Gebote, die ich dir heute gebiete, daß du sie haltest und tust;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'Und nicht von all den Worten, die ich euch heute gebiete, weder zur Rechten noch zur Linken abweichest, so daß du anderen Göttern nachgehst ihnen zu dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Aber wenn du nicht hörst auf die Stimme Jehovahs, deines Gottes, so daß du haltest zu tun alle Seine Gebote und Seine Satzungen, die ich dir heute gebiete, so wird geschehen, daß alle diese Flüche über dich kommen und dich erreichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Verflucht bist du in der Stadt und verflucht bist du auf dem Felde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Verflucht dein Korb und dein Backtrog;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Verflucht ist deines Leibes Frucht und die Frucht deines Bodens, der Wurf deiner Rinder und die Zucht deines Kleinviehs;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Verflucht bist du in deinem Eingang und verflucht in deinem Ausgang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Senden wird Jehovah wider dich die Verfluchung, die Bestürzung und die Bedrohung in allem, wozu du deine Hand ausreckst, das du tust, bis du vernichtet wirst, und du eilends umkommst, vor dem Bösen deiner Handlungen, daß du Mich verlassen hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Jehovah wird dir anhängen die Pest, bis daß sie dich verzehrt von dem Boden, auf den du kommen wirst, ihn einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Schlagen wird dich Jehovah mit Schwindsucht und mit Fieberglut und mit hitzigem und mit entzündlichem Fieber, und mit Dürre und mit Kornbrand und mit Vergilbung, und sie werden dir nachsetzen, bis du umkommst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Und deine Himmel über deinem Haupte werden Erz und unter dir die Erde wird Eisen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Als Regen für dein Land wird Jehovah dir Staubpulver und Flugsand geben; vom Himmel kommt er herab über dich, bis daß du vernichtet bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Jehovah wird dich geschlagen dahingeben vor deinem Feind; auf einem Wege wirst du wider ihn ausziehen, und auf sieben Wegen vor ihm fliehen, und wirst zum Grauen werden allen Königreichen der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'Und dein Leichnam wird zur Speise allem Gevögel des Himmels und für das Getier der Erde, und niemand wird sie von dannen aufscheuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Und Jehovah wird dich schlagen mit dem Geschwür Ägyptens und mit Goldaderknoten und mit Krätze und mit Ausschlag, die niemand zu heilen vermag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Schlagen wird dich Jehovah mit Wahnsinn und mit Blindheit und Stumpfsinn des Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Und du wirst tappen in der Mittagshelle, wie der Blinde tappt im Dunkeln, du wirst kein Gelingen haben auf deinen Wegen, und wirst eitel Unterdrückung und Plünderung erleiden alle Tage, und niemand wird dich retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Du wirst dir ein Weib verloben, aber ein anderer Mann wird sie beschlafen. Ein Haus wirst du bauen, aber nicht darin wohnen, einen Weinberg pflanzen, aber nicht genießen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Dein Ochse wird vor deinen Augen geschlachtet und du wirst nicht davon essen. Dein Esel wird dir vor deinem Angesicht entrissen und er wird nicht zu dir zurückkehren. Dein Kleinvieh wird deinem Feind gegeben, und niemand ist da, der dich rettete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Deine Söhne und deine Töchter werden einem anderen Volke gegeben, und deine Augen sehen es und verzehren ob ihnen den ganzen Tag, aber nichts ist in der Kraft deiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Die Frucht deines Bodens und all deinen Erwerb verzehrt ein Volk, das du nicht kennst, und nur unterdrückt und zerschlagen bist du alle deine Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'Und wirst wahnsinnig sein ob all dem Anblick dessen, was dein Auge sehen muß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Schlagen wird dich Jehovah mit dem bösen Geschwür an den Knien und an den Schenkeln, von dem du nicht vermagst geheilt zu werden, von der Sohle deines Fußes bis zu deinem Scheitel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Jehovah läßt dich und deinen König, den du über dich eingesetzt, zu einer Völkerschaft gehen, die du nicht kennst, weder du, noch deine Väter, und wirst dort anderen Göttern dienen, dem Holz und Stein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'Und wirst zum Entsetzen, zum Sprichwort und zur Stachelrede werden unter allen den Völkern, unter die dich Jehovah führen läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Viel Samen wirst du in das Feld hinausbringen und wenig einsammeln; denn die Heuschrecke frißt es ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Weinberge wirst du pflanzen und bebauen; aber den Wein sollst du nicht trinken noch heimbringen, weil der Wurm ihn fressen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Ölbäume wirst du haben in all deiner Grenze; aber nicht mit Öl dich salben; denn dein Ölbaum wirft ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Söhne und Töchter wirst du zeugen, aber sie werden dein nicht sein, denn sie werden in die Gefangenschaft gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Alle deine Bäume und deines Bodens Frucht nimmt die Grille ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Der Fremdling, der in deiner Mitte ist, wird höher und höher hinaufsteigen über dich, und du wirst immer tiefer und tiefer hinabkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'Er wird dir leihen und du wirst ihm nicht leihen. Er wird zum Haupte sein, du aber wirst zum Schwanze werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'Und all diese Flüche kommen über dich, und setzen dir nach und erreichen dich, bis du vernichtet bist, denn du hast auf die Stimme Jehovahs, deines Gottes nicht gehört, so daß du hieltest Seine Gebote und Seine Satzungen, die Er dir gebot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'Und sie werden zum Zeichen und Wahrzeichen an dir und an deinem Samen werden ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'Darum, daß du bei all dem Vielen Jehovah, deinem Gott, nicht mit Fröhlichkeit und gutem Herzen gedient hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Und dienen sollst du deinen Feinden, denn Jehovah sandte wider dich, mit Hunger und mit Durst und mit Nacktheit und mit Mangel an allem; und ein eisern Joch wird Er auf deinen Nacken legen, bis daß Er dich vernichte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Aus der Ferne vom Ende der Erde wird Jehovah eine Völkerschaft heraufbringen wider dich, wie der Adler daherschießt, eine Völkerschaft, deren Zunge du nicht verstehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'Eine Völkerschaft starken Angesichts, die das Angesicht des Alten nicht ansieht, noch Gnade für den Jungen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Und sie verzehrt die Frucht deines Viehs und deines Bodens Frucht, bis daß du vernichtet bist, die dir nichts verbleiben läßt von Korn, von Most und Öl, vom Wurfe deiner Rinder und von deines Kleinviehs Zucht, bis daß es dich zerstört hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'Und wird dich bedrängen in allen deinen Toren, bis herabkommen deine Mauern, die hohen und festen, auf welche du vertrautest, in deinem ganzen Land, und wird dich bedrängen in allen deinen Toren, in deinem ganzen Lande, das Jehovah, dein Gott, dir gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Und wirst verzehren deine Leibesfrucht, deiner Söhne und deiner Töchter Fleisch, die Jehovah, dein Gott, dir gab, in der Bedrängnis und der Enge, womit dein Feind dich beengt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Der Mann, der weichlich und sehr üppig ist in dir, - sein Auge wird böse sein wider seinen Bruder und wider das Weib seines Busens und wider die übrigen seiner Söhne, die er übrigließ,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'Wenn er einem von ihnen geben sollte von dem Fleisch seiner Söhne, die er ißt; weil ihm nichts von allem war, bleibt in der Bedrängnis und in der Enge, womit der Feind dich beengen wird in all deinen Toren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Die Weichlichste und die Üppigste unter dir, die niemals versuchte, die Fußsohle auf die Erde zu setzen, vor Üppigkeit und vor Weichlichkeit, ihr Auge wird böse auf den Mann ihres Busens und auf ihren Sohn und auf ihre Tochter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'Und ob ihrer Nachgeburt, die zwischen ihren Füßen herausging, und ob ihren Söhnen, die sie gebiert; denn sie ißt sie im Geheimen auf, aus Mangel an allem, in der Bedrängnis und Enge, womit dich dein Feind in deinen Toren beengt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Wenn du nicht hältst, daß du tust alle die Worte dieses Gesetzes, die in diesem Buch geschrieben sind, so daß du fürchtest diesen herrlichen und furchtbaren Namen, Jehovah, deinen Gott:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'So wird Jehovah wundersame Schläge führen wider dich und Schläge wider deinen Samen, große, dauernde Schläge, und böse, dauernde Krankheiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'Und Er wird wieder bringen über dich all die Seuchen Ägyptens, von denen dir bangte, und sie werden dir anhangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Auch allerlei Krankheiten und allerlei Schläge, die nicht in dem Buche des Gesetzes geschrieben sind, wird Jehovah über dich heraufbringen, bis daß du vernichtet bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'Und euer werden wenig Leute verbleiben, statt daß ihr waret wie die Sterne der Himmel an Menge, weil du nicht gehört hast auf die Stimme Jehovahs, deines Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'Und es wird geschehen, wie Jehovah Sich über euch gefreut hatte, daß Er Gutes täte und euch mehrete, so freuet Sich jetzt Jehovah über euch, euch zu zerstören und auch zu vernichten, daß ihr hingerafft werdet von dem Boden, dahin du kommst, ihn einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'Und Jehovah wird dich zerstreuen unter alle Völker von einem Ende der Erde bis zum anderen Ende der Erde; und wirst da anderen Göttern dienen, die du nicht kanntest, du, noch deine Väter, Holz und Stein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'Und unter diesen Völkerschaften sollst du nicht rasten und keine Ruhe sein für die Sohle deines Fußes und Jehovah gibt dir dort ein zitterndes Herz und ein Verschmachten der Augen und ein Vergehen der Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'Daß dein Leben dir gegenüber hängt und du Nacht und Tag schauderst, und nicht an dein Leben glaubst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Am Morgen wirst du sagen: Ach, wäre es doch Abend, und am Abend wirst du sagen: Wäre es doch Morgen! - Vor Schauer des Herzens, wie es dich schaudert, und bei dem Anblick dessen, das dein Auge sieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'Und Jehovah bringt dich dann zurück auf Schiffen nach Ägypten auf dem Wege, davon ich dir gesagt, du sollst ihn nicht mehr sehen; und ihr müsset euch dort verkaufen an deine Feinde zu Knechten und zu Dienstmägden, und niemand will euch kaufen. Das sind die Worte des Bundes, den Jehovah Mose gebot im Lande Moab mit den Söhnen Israels zu schließen, außer dem Bund, den Er in Choreb mit ihnen geschlossen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'Und Mose rief dem ganzen Israel und sprach zu ihnen: Ihr habt gesehen alles, was Jehovah vor euren Augen in Ägyptenland getan an Pharao und allen seinen Knechten und an seinem ganzen Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'Die großen Versuchungen, die deine Augen sahen, Seine Zeichen und großen Wahrzeichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'Aber Jehovah hat euch kein Herz gegeben zu erkennen, noch Augen zu sehen, noch Ohren zu hören, bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Und die vierzig Jahre, die ich euch in der Wüste geführt, alterten nicht eure Gewänder an euch, und dein Schuh alterte nicht an deinem Fuß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'Ihr habt kein Brot gegessen und keinen Wein noch starkes Getränk getrunken, auf daß ihr wisset, daß Ich, Jehovah, euer Gott, bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Und ihr kamt an diesen Ort, und es zog aus Sichon der König von Cheschbon und Og, König von Baschan, uns entgegen zum Streite, und wir schlugen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'Und wir nahmen ihr Land und gaben es zum Erbe dem Rubeniter und dem Gaditer und dem halben Stamm Menascheh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'Und ihr sollt die Worte dieses Bundes halten und sie tun, auf daß ihr klug seiet in allem, was ihr tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Ihr habt auch heute alle von euch vor Jehovah, euren Gott, gestellt: eure Häupter, eure Stämme, eure Ältesten und eure Vorsteher, alle Männer Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Eure Kindlein, eure Weiber und dein Fremdling, der in der Mitte deines Lagers ist, von dem, der dein Holz haut, bis zu dem, der dein Wasser schöpft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'Auf daß du heute in den Bund Jehovahs, deines Gottes, übergehst und in Seinen Eid, den Jehovah, dein Gott, heute mit dir schließt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'Auf daß Er heute dich als Sein Volk bestätige, und Er zum Gott dir sei, wie Er zu dir geredet hat, und wie Er deinen Vätern, dem Abraham, dem Isaak und dem Jakob geschworen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'Und nicht mit euch, euch allein schließe Ich diesen Bund und diesen Eid,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'Sondern sowohl mit dem, der heute hier mit uns vor Jehovah, unserem Gotte, steht, als auch mit dem, der heute nicht bei uns ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'Denn ihr wisset, wie wir in Ägyptenland wohnten, und wie wir mitten durch die Völkerschaften durchzogen, durch die ihr durchzoget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Und sahet ihre Scheusale und ihre Götzen, Holz und Stein, Silber und Gold, die bei ihnen waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'Daß nicht unter euch ein Mann sei oder ein Weib, oder eine Familie oder ein Stamm, der heute sein Herz wende von Jehovah, unserem Gott, um zu gehen, zu dienen den Göttern dieser Völkerschaften, daß nicht unter euch sei eine Wurzel, die mit Galle und Wermut fruchtbar sei;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Und es geschehe, daß er, wenn er die Worte dieses Eides hört, sich in seinem Herzen segne und spreche: Friede ist mir, wenn gleich ich in meines Herzens Eigensinn wandle, um das Schwelgende mit dem Dürstenden wegzuraffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'Jehovah ist nicht willens ihm zu vergeben, vielmehr wird dann Jehovahs Zorn und Sein Eifer rauchen wider diesen Mann, und auf ihm lagern alle Verwünschung, die in diesem Buch geschrieben ist, und Jehovah wird seinen Namen unter den Himmeln auswischen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Und Jehovah wird ihn ausscheiden zum Übel aus allen Stämmen Israels, nach all den Verwünschungen des Bundes, der im Buche dieses Gesetzes geschrieben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'Und sprechen wird das spätere Geschlecht, eure Söhne, die nach euch erstehen, und der Ausländer, der aus fernem Lande kommt, und die sehen die Schläge dieses Landes und seine Krankheiten, die Jehovah sie erkranken läßt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'Schwefel und Salz, eine Brandstätte wird all ihr Land sein, wird nicht besät werden, und nicht sprossen, und wird in ihm kein Kraut aufgehen, wie mit der Umkehrung von Sodom, Gomorrah, Admah und Zeboim, die Jehovah in Seinem Zorn und Grimm hat umgekehrt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'Und alle Völkerschaften werden sprechen: Warum hat Jehovah also diesem Lande getan? Warum großer Zorn entbrannt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'Und sie werden sagen: Darum, daß sie verließen den Bund Jehovahs, ihrer Väter Gott, den Er mit ihnen geschlossen, da Er sie aus Ägyptenland ausführte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Und gegangen sind und anderen Göttern dienten und sie anbeteten, Götter, die sie nicht kannten, und die ihnen nicht verteilt worden sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'Und es entbrannte Jehovahs Zorn wider dieses Land, so daß Er all den Fluch, der in diesem Buch geschrieben steht, über dasselbe hat gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Und Jehovah rodete sie aus von ihrem Boden, in Zorn und in Grimm und in großer Entrüstung, und warf sie in ein anderes Land, wie an diesem Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'Das Geheime ist Jehovahs, unseres Gottes, und das Geoffenbarte unser und unsrer Söhne ewiglich, zu tun all die Worte dieses Gesetzes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'Und geschehen wird, wenn alle diese Dinge über dich kommen, der Segen und der Fluch, die ich vor dich lege; wenn du zu deinem Herzen dich zurückwendest, wo du auch unter den Völkerschaften bist, dahin dich Jehovah, dein Gott, verstoßen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'Und kehrst zurück zu Jehovah, deinem Gott, und hörst auf Seine Stimme nach allem, was ich heute dir gebiete, du und deine Söhne, mit deinem ganzen Herzen und mit deiner ganzen Seele;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'So wendet Jehovah, dein Gott, deine Gefangenschaft zurück, und erbarmt Sich deiner, und wendet Sich zurück und bringt dich zusammen aus allen Völkern, wohin dich Jehovah, dein Gott, zerstreut hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Wenn deine Verstoßenen am Ende der Himmel wären, so wird doch Jehovah, dein Gott, dich von dannen zusammenbringen und von dannen holen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'Und wird dich hineinbringen Jehovah, dein Gott, zum Lande, das deine Väter erblich besessen hatten, und du wirst es erblich besitzen; und Er wird Gutes dir tun, und deiner mehr machen, als deiner Väter waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'Und Jehovah, dein Gott, wird dein Herz beschneiden und das Herz deines Samens, so daß du Jehovah, deinen Gott, liebst von deinem ganzen Herzen und von deiner ganzen Seele, auf daß du leben mögest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'Und Jehovah, dein Gott, wird all diese Verwünschungen auf deine Feinde legen und auf die, so dich hassen, die dir nachsetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Und du wirst dich zurückwenden und auf die Stimme Jehovahs hören und alle Seine Gebote tun, die ich dir gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'Und Jehovah, dein Gott, wird dir Überfluß geben in allem Tun deiner Hand, an der Frucht deines Leibes und an der Frucht deines Viehs und an der Frucht deines Bodens, zum Guten; denn Jehovah wird Sich wieder über dich freuen zum Guten, wie Er Sich über deine Väter freute;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'So du hörst auf die Stimme Jehovahs, deines Gottes, daß du hältst Seine Gebote und Seine Satzungen, die geschrieben sind im Buche dieses Gesetzes, wenn du dich von deinem ganzen Herzen und von deiner ganzen Seele zu Jehovah, deinem Gotte, zurückwenden wirst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Denn dieses Gebot, das ich dir heute gebiete, ist nicht zu wundersam für dich und ist nicht zu fern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'Es ist nicht in den Himmeln, daß du sagen könntest: Wer steigt für uns hinauf gen Himmel und holt es für uns und läßt es uns hören, auf daß wir es tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Und es ist nicht jenseits des Meeres, daß du sagen könntest: Wer fährt für uns jenseits des Meeres und holt es für uns hinüber und läßt es uns hören, daß wir es tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Denn das Wort ist dir sehr nahe; in deinem Mund und in deinem Herzen ist es, daß du es tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Siehe, ich habe heute vor dich gegeben Leben und das Gute, und den Tod und das Böse;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 'Da ich dir heute gebiete, Jehovah, deinen Gott, zu lieben, in Seinen Wegen zu wandeln und Seine Gebote und Seine Satzungen und Seine Rechte zu halten. Und du wirst leben und dich mehren, und Jehovah, dein Gott, wird dich segnen in dem Lande, dahin du kommst, es einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'So aber sich dein Herz wendet und du nicht gehorchst, und wirst abgeführt, daß du andere Götter anbetest und ihnen dienst:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'Sage ich euch heute an, daß ihr umkommen werdet und eure Tage nicht verlängert werden auf dem Boden, da du über den Jordan übersetzest, um hineinzukommen, ihn in Besitz zu nehmen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Himmel und Erde nehme ich heute wider euch zu Zeugen. Leben und Tod, Segen und Fluch habe ich vor dich gelegt. So erwähle das Leben auf daß du lebest, du und dein Same!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'Daß du Jehovah, deinen Gott, liebest, auf Seine Stimme hörst und Ihm anhangest; denn Er ist dein Leben und die Länge deiner Tage, daß du wohnst auf dem Boden, den Jehovah deinen Vätern, dem Abraham, dem Isaak und dem Jakob geschworen hat, ihnen zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'Und Mose ging und redete diese Worte zu ganz Israel,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'Und sprach zu ihnen: Hundertzwanzig Jahre bin ich heute alt; ich vermag nicht ferner auszugehen und einzugehen, und Jehovah hat zu mir gesprochen: Du sollst nicht über diesen Jordan übersetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Jehovah, dein Gott, Er zieht vor dir hinüber; Er vernichtet diese Völkerschaften vor dir, auf daß du sie einnehmest. Joschua, der zieht vor dir hinüber, wie Jehovah geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'Und Jehovah wird ihnen tun, wie Er dem Sichon und dem Og, den Königen des Amoriters und ihrem Lande tat, die Er vernichtet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'Und Jehovah gibt sie vor euch dahin, und ihr sollt ihnen tun nach all dem Gebot, das ich euch geboten habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Seid stark und rüstig, fürchtet euch nicht und laßt euch nicht vor ihnen grauen. Denn Jehovah, dein Gott, geht mit dir. Er wird dich nicht aufgeben noch verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'Und Mose rief den Joschua und sprach zu ihm vor den Augen von ganz Israel: Sei stark und rüstig; denn du sollst dieses Volk hineinbringen in das Land, das Jehovah ihren Vätern geschworen hat, ihnen zu geben; und sollst es unter sie zum Erbe verteilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Und Jehovah ist es, Der vor dir geht und Er wird mit dir sein. Er wird dich nicht aufgeben noch verlassen; fürchte dich nicht und entsetze dich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'Und Mose schrieb dieses Gesetz und gab es den Priestern, den Söhnen Levis, welche die Bundeslade Jehovahs trugen, und all den Ältesten von Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'Und Mose gebot ihnen und sprach: Am Ende von sieben Jahren zur bestimmten Zeit des Erlaßjahres, am Feste der Laubhütten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'Da ganz Israel kommt, zu sehen das Angesicht Jehovahs, deines Gottes, an dem Orte, den Er erwählen wird, sollst du vorlesen dieses Gesetz in Gegenwart von ganz Israel vor ihren Ohren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Versammle das Volk, die Männer und die Weiber und die Kindlein und deinen Fremdling, der in deinen Toren ist, auf daß sie hören und auf daß sie lernen, und Jehovah, euren Gott fürchten, und halten und tun alle Worte dieses Gesetzes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'Und ihre Söhne, die davon nichts wuß-ten, sollen hören und lernen fürchten Jehovah, euren Gott, alle Tage, die ihr lebt auf dem Boden, dahin ihr über den Jordan übergeht, ihn einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Und Jehovah sprach zu Mose: Siehe, deine Tage nahen zum Sterben. Rufe Joschua und stellet euch in das Versammlungszelt, damit Ich ihm gebiete. Und Mose ging mit Joschua und stellten sich in das Versammlungszelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'Und Jehovah erschien im Zelt in einer Wolkensäule, und die Wolkensäule stand über dem Eingang des Zeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'Und Jehovah sprach zu Mose: Siehe, du legst dich zu deinen Vätern, und dieses Volk möchte aufstehen und den ausländischen Göttern des Landes nachbuhlen, in dessen Mitte es hineinkommen wird, und Mich verlassen und den Bund zunichte machen, den Ich mit ihm geschlossen habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'Und Mein Zorn würde entbrennen an jenem Tag wider dasselbe; und Ich werde es verlassen und Mein Angesicht vor ihnen verbergen, daß es verzehrt werde; und viele Übel und Drangsale werden es treffen; und an jenem Tag wird es sprechen: Ist es nicht also, daß diese Übel mich treffen, weil mein Gott nicht in meiner Mitte ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Ich aber will Mein Antlitz ganz und gar vor ihm verbergen an jenem Tag ob all dem Bösen, das es getan, weil es sich zu anderen Göttern wendete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Und nun schreibe euch diesen Gesang auf und lehre ihn die Söhne Israels, lege ihn in ihren Mund, auf daß Mir dieser Gesang Zeuge sei wider die Söhne Israels,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Wenn Ich sie auf den Boden hineinbringe, den Ich seinen Vätern geschworen habe, da Milch und Honig fließen, und es ißt und satt wird und fett, und sich wendet zu anderen Göttern und ihnen dient, und Mich verschmäht und Meinen Bund zunichte macht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Und es wird geschehen, daß viele Übel und Drangsale es treffen; und dann soll es diesen Gesang anheben vor ihm zum Zeugnis, - denn es soll nicht vergessen werden aus dem Munde seines Samens, weil Ich sein Gebilde weiß, was es tut heutzutage, bevor Ich es noch in das Land hineingebracht, das Ich geschworen habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Und Mose schrieb diesen Gesang an selbigem Tage und lehrte ihn die Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'Und Joschua, dem Sohne Nuns, gebot Er und sprach: Sei stark und mächtig; denn du sollst die Söhne Israels in das Land hineinbringen, das Ich ihnen geschworen habe; und Ich werde mit dir sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Und es geschah, da Mose vollendet hatte die Worte dieses Gesetzes allesamt in das Buch zu schreiben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'Da gebot Mose den Leviten, welche die Lade des Bundes Jehovahs trugen und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Nehmet das Buch dieses Gesetzes und legt es zur Seite der Bundeslade Jehovahs, eures Gottes, auf daß es dort sei ein Zeuge wider dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Denn ich weiß deine Widerspenstigkeit und deinen Nacken, den harten. Sehet, während ich noch heute lebe unter euch, seid ihr gegen Jehovah widerspenstig gewesen; und wie werdet ihr es erst nach meinem Tode sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Versammelt zu mir alle Ältesten eurer Stämme und eure Vorsteher, und ich will vor ihren Ohren diese Worte reden und Himmel und Erde, wider sie zu Zeugen nehmen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Denn ich weiß, daß ihr nach meinem Tode verderblich handelt, und von dem Wege abweichet, den ich euch geboten habe, und es wird euch in späteren Tagen Böses widerfahren, wenn ihr tut, was in Jehovahs Augen böse ist, und durch eurer Hände Tat Ihn reizet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'Und Mose redete vor den Ohren der ganzen Versammlung Israels die Worte dieses Gesangs, bis sie alle waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Ihr Himmel horchet auf, und ich werde reden; und meines Mundes Sprüche höre die Erde!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Wie Regen träufle meine Lehre und mein Spruch riesle wie der Tau. Wie Regenschauer auf junges Grün, wie Regengüsse auf das Kraut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'Denn ich rufe an Jehovahs Namen. Gebt Größe unserem Gotte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'Der Fels! Vollkommen ist Sein Werk! Denn Recht sind alle Seine Wege. Ein Gott der Treue, ohne Verkehrtheit! Gerecht und gerade ist Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Es hat sich Ihm verdorben; nicht Seine Söhne, ihr eigener Makel sind sie; ein Geschlecht, krumm und verdreht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Vergeltet ihr also dem Jehovah, ihr töricht und unweises Volk? Ist Er dein Vater nicht, Der dich erworben, - Er, Der dich gemacht und bereitet hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Gedenk der Ewigkeit Tage, merke auf die Jahre von Geschlecht zu Geschlecht. Frage deinen Vater, der sagt es dir an, deine Ältesten, und sie werden es dir sagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Da der Höchste den Völkerschaften ihr Erbe austeilte, da Er trennte die Söhne der Menschen, bestellte Er der Völker Grenzen, nach der Zahl der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Denn Jehovahs Teil ist Sein Volk, Jakob der Anteil Seines Erbes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Er fand ihn im Land der Wüste, und in der Leere, dem Geheul, im Wüstenland; Er führte ihn umher, verständigte ihn und bewahrte ihn wie Seinen Augapfel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Wie der Adler aufregt sein Nest, über seinen Jungen schwebt, seine Flügel ausbreitet, ihn nimmt und auf seinen Fittichen trägt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'Jehovah führte ihn allein, und kein ausländischer Gott war mit Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Er ließ ihn fahren über der Erde Opferhöhen und essen des Feldes Ertrag; und ließ ihn saugen Honig aus der Felsklippe und Öl aus dem Kiesel des Felsen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'Butter von dem Rinde und des Kleinviehs Milch, mit dem Fett der Lämmer und Widder, der Söhne Baschans und der Böcke, mit dem Nierenfett des Weizens und der Weinbeere Blut, den Wein, trankest du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'Und Jeschurum ward fett und schlug aus - du wurdest fett, dick und feist - er gab auf Gott, Der ihn machte und verunehrte den Felsen seines Heils.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Sie erregten Ihn zum Eifern durch Fremde, sie reizten Ihn durch Greuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Sie opferten den Unholden, die Gott nicht sind, Göttern, die sie nicht gekannt, neuen, die aus der Nähe kamen, die eure Väter nicht scheuten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Dem Felsen, Der dich gezeugt, läßt du außer Acht, hast Gott, Der dich gestaltet, vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'Und das sah Jehovah und verwarf gereizt Seine Söhne und Seine Töchter;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Und Er sprach: Mein Angesicht will Ich vor ihnen verbergen, will sehen, was ihr Letzteres sein wird; denn ein verkehrt Geschlecht sind sie, Söhne, keine Treue ist in ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Sie erregten Mich zum Eifern durch Nicht-Götter, sie reizten Mich durch ihre Nichtigkeiten, Ich aber will sie erregen zum Eifern, an einem Nicht-Volk, durch eine törichte Völkerschaft will Ich sie reizen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Denn ein Feuer ist angefacht in Meinem Zorn und es lodert bis zur untersten Hölle, und es frißt auf die Erde und ihr Gewächs und entflammt die Grundfesten der Berge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Böses will Ich sammeln über sie, will Meine Pfeile auf sie verschießen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Erschöpft vom Hunger und abgezehrt von Fieberglut und bitterer Seuche, entsende Ich der Untiere Zahn über sie mit dem brennenden Gift der im Staube Kriechenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Draußen beraubt das Schwert, und der Schrecken aus den Kammern, Jüngling wie Jungfrau, den Säugling mit dem greisen Manne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Ich spräche: Zerstieben will Ich sie, will zu Ende bringen ihr Andenken bei den Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'Bangte mir nicht vor des Feindes Unmut, daß nicht ihre Dränger es besäen, daß sie nicht sprächen: Unsere erhabene Hand und nicht Jehovah hat all dies getan!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Denn eine Völkerschaft sind sie, bei denen der Rat verloren ist, und ist in ihnen keine Einsicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'O daß sie weise wären und es vernähmen, daß sie ihr Letzteres einsehen möchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Wie sollte einer sonst Tausenden nach- setzen, und zwei Zehntausend in die Flucht schlagen, wenn nicht ihr Fels sie verkauft, Jehovah sie nicht überantwortet hätte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Denn nicht wie unser Fels ist ihr Fels und unsere Feinde seien Schiedsrichter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Denn von Sodoms Weinstock ist ihr Weinstock und von Gomorrahs Gefilden; Weinbeeren von Galle sind ihre Weinbeeren, und sie haben bittere Trauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Ihr Wein ist Gift der Drachen und grausame Galle der Ottern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Ist das nicht verschlossen bei Mir, versiegelt in Meinen Schätzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Mein ist Rache und Vergeltung zur Zeit, da ihr Fuß wankt; denn nahe ist der Tag ihrer Not, und ihr Verhängnis kommt schleunig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Denn Jehovah wird rechten für Sein Volk; und über Seine Knechte wird es Ihn gereuen, wenn Er sieht, daß die Hand vergangen und mit dem Eingeschlossenen und Verlassenen zu Ende ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'Und man sagt: Wo sind nun ihre Götter, der Fels, auf den sie sich verließen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'Die das Fett ihrer Opfer aßen, den Wein ihrer Trankopfer tranken? Sie mögen sich jetzt aufmachen und euch beistehen, ein Schirm sein über euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Sehet nun, daß Ich, Ich es bin, und kein Gott bei Mir. Ich töte und Ich mache lebendig; Ich habe zerschmettert und Ich werde heilen, und keiner ist, der aus Meiner Hand errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Wenn Ich Meine Hand zum Himmel erhebe und spreche: Ich lebe in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Habe Ich den Blitz Meines Schwertes geschärft, und Meine Hand greift zum Gericht, und werde Rache wiederbringen Meinen Drängern und vergelten denen, so Mich hassen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Werde Meine Pfeile vom Blut berauschen und Mein Schwert soll Fleisch fressen, vom Blute der Erschlagenen und Gefangenen, von der Galle der Rache an dem Feind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Jauchzet ihr Völkerschaften, Sein Volk; denn das Blut Seiner Knechte wird Er rächen, und Rache zurückgeben Seinen Drängern und sühnen Seinen Boden, Sein Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'Und Mose kam und redete alle Worte dieses Gesangs vor den Ohren des Volkes, er und Joschua, der Sohn Nuns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'Und Mose vollendete das Reden aller dieser Worte an ganz Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'Und er sprach zu ihnen: Nehmet euch zu Herzen alle die Worte, die ich euch heute bezeuge, auf daß ihr euren Söhnen gebietet, zu halten, zu tun alle Worte dieses Gesetzes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Denn es ist kein leeres Wort für euch, denn es ist euer Leben, und durch dieses Wort verlängert ihr die Tage auf dem Boden, da ihr über den Jordan übersetzet, ihn einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'Und Jehovah redete an diesem selbigen Tage zu Mose und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Steig hinauf auf diesen Berg Abarim, den Berg Nebo, der im Lande Moab ist, der vor Jericho ist, und siehe das Land Kanaan, das Ich den Söhnen Israels zum Eigentum gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'Und stirb auf dem Berge, da du hinaufsteigst, und werde zu deinen Völkern versammelt, wie Aharon, dein Bruder, auf dem Berge Hor gestorben und zu seinen Völkern versammelt worden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'Darum, daß ihr Mir untreu wurdet inmitten der Söhne Israels am Haderwasser Kadesch, in der Wüste Zin, daß ihr Mich nicht habt geheiligt inmitten der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Denn du sollst das Land vor dir gegenüber sehen, aber nicht dahin in das Land hineinkommen, das Ich den Söhnen Israels gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'Und dies ist der Segen, mit dem Mose, der Mann Gottes, die Söhne Israels vor seinem Tode segnete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'Und er sprach: Jehovah ist von Sinai gekommen und von Seir ihnen aufgegangen; Er strahlte vom Berge Paran und ist hergekommen von den Zehntausenden der Heiligkeit, von Seiner Rechten haben sie das Feuer des Gesetzes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Auch hat Er die Völker lieb. Alle Seine Heiligen sind in deiner Hand und sie sind hingelagert zu Deinen Füßen, und Er wird aufnehmen von Deinen Worten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Ein Gesetz hat für uns Mose geboten, als Erbbesitz der Versammlung Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'Und Er ist König in Jeschurun, da sich die Häupter des Volkes versammeln, Israels Stämme allzumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Ruben soll leben und nicht sterben, aber seiner Leute wird eine Zahl sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'Und dies für Judah; und er sprach: Höre, Jehovah, die Stimme Judahs, daß Du ihn zu seinem Volke hineinbringst. Laß ihm seiner Hände viel sein und sei ihm ein Beistand wider seine Dränger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'Und über Levi sprach er: Deine Thummim und deine Urim gehören dem heiligen Mann, Den du versuchtest in Massah, mit Dem du hadertest an den Haderwassern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'Der zu seinem Vater und zu seiner Mutter spricht: Ich habe ihn nicht gesehen; und seine Brüder erkennt er nicht an, und kennt nicht seine Söhne; denn sie halten Deine Rede und bewahren Deinen Bund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Sie werden Jakob Deine Rechte weisen und Israel Dein Gesetz; sie werden Räuchwerk vor Deine Nase bringen und ganze Opfer auf Deinen Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Segne, Jehovah, sein Vermögen, und laß das Werk seiner Hände Dir wohlgefallen! Zerschmettere die Lenden derer, die wider ihn aufstehen und die ihn hassen, daß sie nimmer stehen auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Von Benjamin sprach er: Der Liebling Jehovahs wird in Sicherheit wohnen bei Ihm. Er wird ihn schützen den ganzen Tag, und zwischen Seinen Schultern wohnt er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'Und von Joseph sprach er: Gesegnet von Jehovah sei sein Land von des Himmels Köstlichstem, vom Tau und von der Tiefe, die unten lagert,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'Mit dem köstlichsten Ertrage der Sonne und mit dem Köstlichsten, das die Monde hervortreiben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'Und mit den Erstlingen der Berge des Ostens und dem Köstlichsten der Hügel der Ewigkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'Und von der Erde Köstlichstem und ihrer Fülle und das Wohlgefallen dessen, Der im Dornbusch wohnte. Es komme auf Josephs Haupt und auf den Scheitel des Nasiräers seiner Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Dem Erstgeborenen seines Ochsen sei Ehre, und Einhorns Hörner seien seine Hörner; er stößt damit die Völker allzumal bis an der Erde Enden. Und sie sind Ephraims Zehntausende, und sie sind Menaschehs Tausende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Und zu Sebulun sprach er: Sei fröhlich, Sebulun, in deinem Ausgang und du Issaschar, in deinen Zelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Völker werden auf den Berg sie rufen, dort werden Opfer der Gerechtigkeit sie opfern, weil des Meeres Überfluß sie saugen und die im Sand verborgenen Schätze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Und von Gad sprach er: Gesegnet sei, der Gad erweitert. Wie ein alter Löwe liegt er hin und zerfleischt Arm und Schädel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'Den Erstling ersah er sich; denn allda war der Teil des verborgenen Gesetzgebers: und es kamen her die Häupter des Volkes: er übte die Gerechtigkeit Jehovahs und Seine Rechte mit Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'Und von Dan sprach er: Dan ist das Junge eines Löwen, aus Baschan springt er hervor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Und von Naphthali sprach er: Gesättigt mit Wohlgefallen und voll des Segens von Jehovah ist Naphthali; das Meer und den Mittag wird er erblich besitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'Und von Ascher sprach er: Gesegnet vor den Söhnen ist Ascher. Er sei seiner Brüder Wohlgefallen; und er tauche in Öl seinen Fuß,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Eisen und Erz sind dein Schuh, und wie deine Tage, so dein Ruhm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Keiner ist wie der Gott Jeschuruns, Welcher fährt auf den Himmeln, dir beizustehen, und in Seiner Hoheit auf dem Wolkenhimmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Die Wohnstätte des Gottes der Vorzeit und unten die Arme der Welt. Er hat den Feind fortgetrieben vor dir und gesprochen: Vernichte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'Und Israel wird wohnen in Sicherheit, allein an Jakobs Quell, im Land des Korns und Mostes, auch werden seine Himmel Tau träufeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Glücklich bist du, Israel, wer ist wie du, ein Volk, gerettet in Jehovah, Der Schild deines Beistandes, und Der das Schwert ist deiner Hoheit. Und deine Feinde täuschen sich an dir und auf ihren Opferhöhen trittst du einher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'Und Mose stieg von dem Flachland Moabs hinauf auf den Berg Nebo, die Spitze des Pisgah, vor Jericho, und Jehovah ließ ihn sehen das ganze Land Gilead bis Dan,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'Und ganz Naphthali und das Land Ephraim und Menascheh und das ganze Land Judah bis zum hintern Meer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'Und das Mittagsland und den Umkreis, das Tal von Jericho, der Palmenstadt, bis Zoar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'Und Jehovah sprach zu ihm: Dies ist das Land, das Ich dem Abraham, dem Isaak und dem Jakob zugeschworen habe und gesagt: Deinem Samen will Ich es geben. Mit deinen Augen habe Ich dich es sehen lassen; du sollst aber nicht hinüberkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Und Mose, der Knecht Jehovahs, starb allda im Lande Moab nach dem Ausspruch Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'Und Er begrub ihn im Tal im Lande Moab, gegenüber Beth Peor, und kein Mann weiß sein Grab bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Und Mose war hundertzwanzig Jahre alt, da er starb; sein Auge war nicht trüb geworden, noch seine Frische entflohen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'Und die Söhne Israels beweinten Mose im Flachlande Moabs dreißig Tage; und die Tage des Weinens der Trauer um Mose waren aus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Und Joschua, der Sohn Nuns, ward erfüllt mit dem Geiste der Weisheit; denn Mose hatte seine Hände auf ihn gelegt, und die Söhne Israels hörten auf ihn und taten, wie Jehovah Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'Und es stand in Israel kein Prophet mehr auf wie Mose, den Jehovah gekannt hätte von Angesicht zu Angesicht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'Mit allen den Zeichen und Wundern, dazu ihn Jehovah sandte, daß er sie täte im Lande Ägypten an Pharao und an allen seinen Knechten und an all seinem Lande,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'Und mit all der starken Hand und all der großen Furcht, so Mose tat vor den Augen von ganz Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'Und es geschah nach dem Tode Moses, des Knechtes Jehovahs, daß Jehovah zu Joschua, dem Sohne Nuns, Moses Diener, sprach und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mose, mein Knecht, ist tot, und nun mache du dich auf, gehe über diesen Jordan, du und all dies Volk, nach dem Lande, das Ich ihnen, den Söhnen Israels gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Jeder Ort, darauf eure Fußsohle tritt, habe Ich euch gegeben, wie Ich zu Mose geredet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Von der Wüste und diesem Libanon und bis zu dem großen Flusse, dem Flusse Euphrat, alles Land der Chethiter und bis zum großen Meer, zum Untergang der Sonne, soll eure Grenze sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Kein Mensch soll bestehen vor dir alle Tage deines Lebens. Wie Ich mit Mose war, will Ich mit dir sein, und dich nicht aufgeben, noch dich verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Sei stark und rüstig; denn du sollst diesem Volk das Land, das Ich ihren Vätern geschworen habe, ihnen zu geben, als Erbe austeilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Sei nur stark und sehr rüstig, daß du haltest zu tun nach all dem Gesetz, das dir Mose, Mein Knecht, geboten hat. Weiche nicht ab davon, weder zur Rechten, noch zur Linken, auf daß du klüglich handelst überall, wo du hingehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Laß dieses Gesetzbuch nicht von deinem Munde weichen und sinne darüber Tag und Nacht, auf daß du haltest zu tun nach allem, das darin geschrieben ist; denn dann gelingt dir es auf deinem Wege, und dann handelst du klüglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Habe Ich dir nicht geboten, du sollest stark sein und rüstig, sollst kein Grauen und kein Entsetzen haben?, denn Jehovah, dein Gott, ist mit dir, überall wo du hingehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Und Joschua gebot den Vorstehern des Volkes und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Gehet hin mitten durch das Lager und gebietet dem Volke und sprechet: Bereitet euch Zehrung; denn in noch drei Tagen ziehet ihr über diesen Jordan, daß ihr hineinkommt und das Land einnehmet, das Jehovah, euer Gott, euch zum Erbbesitze gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Und zu den Rubeniten und den Gaditern und zu dem halben Stamm Menascheh sprach Joschua und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Gedenket des Wortes, das euch Mose, der Knecht Jehovahs, geboten hat und gesagt: Jehovah, euer Gott, hat euch zur Ruhe gebracht und euch dies Land gegeben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Eure Weiber, eure Kindlein und eure Viehherden dürfen in dem Lande bleiben, das euch Mose diesseits des Jordans gegeben hat. Ihr aber sollt kampfgerüstet vor euren Brüdern hinüberziehen, alle tapferen Männer, und sollt ihnen beistehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'Bis daß Jehovah eure Brüder wie euch zur Ruhe gebracht hat, und auch sie das Land eingenommen haben, das Jehovah, euer Gott, ihnen gibt. Dann dürft ihr in das Land eures Erbbesitzes zurückkehren und dasselbe erblich besitzen, das euch Mose, der Knecht Jehovahs, diesseits des Jordans gegen Aufgang der Sonne gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'Und sie antworteten Joschua und sprachen: Alles, was du uns geboten hast, wollen wir tun, und wohin du uns sendest, wollen wir gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Ganz so, wie wir auf Mose hörten, so werden wir auf dich hören. Nur möge Jehovah, dein Gott, mit dir sein, wie Er mit Mose gewesen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Jeder Mann, der deinem Mund widerspenstig ist und nicht hört auf deine Worte in allem, das du uns gebietest, der soll getötet werden. Nur sei stark und rüstig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'Und Joschua, der Sohn Nuns, sandte im Stillen von Schittim zwei Männer als Kundschafter und sagte ihnen: Gehet, beseht das Land und Jericho. Und sie gingen und kamen in das Haus eines Weibes, einer Buhlerin, und ihr Name war Rachab, und sie legten sich da nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Und sie sagten dem Könige von Jericho und sprachen: Siehe, es sind in dieser Nacht Männer von den Söhnen Israels hierher hereingekommen, um das Land auszuforschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'Und der König von Jericho sandte zu Rachab und sprach: Bringe die Männer, die zu dir hereingekommen, heraus, die in dein Haus eingegangen; denn sie sind hereingekommen, das ganze Land auszuforschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Das Weib aber nahm die zwei Männer und verbarg sie und sagte: Es ist also, die Männer sind hereingekommen; aber ich wußte nicht, von wannen sie waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'Und als man das Tor schließen wollte in der Finsternis, gingen die Männer hinaus; ich weiß nicht, wohin die Männer gegangen sind. Setzet ihnen eilends nach; denn ihr werdet sie erreichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Sie hatte sie aber auf das Dach hinaufsteigen lassen und mit Flachsstengeln verdeckt, die auf dem Dach von ihr waren zurechtgelegt worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'Und die Männer setzten ihnen nach auf dem Wege nach dem Jordan, nach den Furten, und sie schlossen das Tor hinter ihnen zu, da die hinausgegangen waren, die ihnen nachsetzten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Ehe sie sich aber niederlegten, da stieg sie zu ihnen hinauf auf das Dach,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'Und sprach zu den Männern: Ich weiß, daß Jehovah euch das Land gegeben hat, und daß ein Schrecken vor euch auf uns gefallen ist, und alle Einwohner des Landes vor euch zerfließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Denn wir haben gehört, wie Jehovah die Wasser des Schilfmeeres vor euch vertrocknete, als ihr aus Ägypten auszogt, und was ihr den zwei Königen des Amoriters, dem Sichon und dem Og, jenseits des Jordans getan, die ihr verbannt habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'Und wir haben es gehört, und nun ist unser Herz zerschmolzen und der Geist ist in keinem Mann mehr aufrecht vor euch; denn Jehovah, euer Gott, Welcher ist Gott in den Himmeln oben und auf Erden unten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Und nun schwöret mir doch bei Jehovah, daß, wie ich an euch Barmherzigkeit getan, so auch ihr Barmherzigkeit tut an dem Hause meines Vaters; und gebet mir ein Zeichen der Wahrheit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'Daß ihr meinen Vater und meine Mutter und meine Brüder und meine Schwestern und alles, was sie haben, am Leben lasset und unsere Seelen vom Tode errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'Und die Männer sprachen zu ihr: Unsere Seele sei statt eurer des Todes. Wenn ihr dies, unsere Sache nicht ansaget, so soll geschehen, daß wir, wenn Jehovah uns das Land gibt, Barmherzigkeit und Wahrheit an dir tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Und sie ließ dieselben an einem Stricke durch das Fenster hinab; denn ihr Haus war mit der Wand in der Stadtmauer, und in der Stadtmauer wohnte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'Und sie sagte ihnen: Gehet nach dem Berge, daß, die euch nachsetzen, nicht auf euch stoßen, und versteckt euch dort drei Tage, bis die euch nachsetzen, zurückkehren, und hernach geht eures Weges.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Und die Männer sprachen zu ihr: Wir sind dieses deines Schwures ledig, den du uns hast schwören lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'Siehe, so wir kommen in das Land, sollst du diese Schnur von Scharlachfaden in das Fenster binden, durch das du uns herabgelassen hast, und deinen Vater und deine Mutter und deine Brüder und das ganze Haus deines Vaters zu dir ins Haus versammeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'Und es geschehe, daß jeder, der aus der Tür deines Hauses hinaus auf die Gasse geht, dessen Blut sei auf seinem Haupt, und wir sind unschuldig. Jeder aber, der bei dir im Hause ist, dessen Blut komme auf unser Haupt, so eine Hand wider ihn sein wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Und wenn du diese unsere Sache ansagst, so sind wir ledig des Schwures, den du uns schwören ließest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Und sie sprach: Nach euren Worten, so sei es! Und sie entließ dieselben und sie gingen; sie aber band die Scharlachschnur in das Fenster.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Und sie gingen und kamen auf den Berg und blieben allda drei Tage, bis die, so ihnen nachgesetzt, zurückgekehrt waren. Und die, so ihnen nachgesetzt, hatten auf dem ganzen Wege gesucht und sie nicht gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Und die zwei Männer kehrten zurück und kamen vom Berge herab und setzten über und kamen zu Joschua, dem Sohne Nuns und erzählten ihm alles, was sie betroffen hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'Und sprachen zu Joschua: Jehovah hat das ganze Land in unsre Hand gegeben; und alle Einwohner des Landes zerfließen auch vor uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'Und Joschua stand früh am Morgen auf, und sie brachen auf von Schittim und kamen an den Jordan, er und alle Söhne Israels und übernachteten allda, ehe sie hinüberzogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'Und es geschah am Ende dreier Tage, daß die Vorsteher inmitten des Lagers durchgingen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'Und geboten dem Volk und sprachen: Wenn ihr die Bundeslade Jehovahs, eures Gottes, sehet und die Priester, die Leviten, sie tragen, so brechet auf von eurem Orte und gehet ihr nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Doch soll zwischen euch und zwischen ihr eine Entfernung sein, bei zweitausend Ellen gemessen. Kommt ihr nicht nahe, auf daß ihr den Weg wisset, auf dem ihr gehen sollt; denn ihr seid des Weges nicht hinübergezogen gestern oder ehegestern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'Und Joschua sprach zum Volke: Heiligt euch; denn morgen wird Jehovah in eurer Mitte Wunder tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'Und zu den Priestern sprach Joschua und sagte: Traget die Bundeslande und ziehet vor dem Volke hinüber, und sie trugen die Bundeslade und zogen vor dem Volke hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'Und Jehovah sprach zu Joschua: An diesem Tage will Ich anfangen, dich groß zu machen in den Augen von ganz Israel, auf daß sie wissen, daß, wie Ich mit Mose war, so Ich mit dir sein werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Und du gebiete den Priestern, so die Bundeslade tragen, und sprich: Wenn ihr an den Rand der Wasser des Jordans kommt, so sollt ihr im Jordan stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'Und Joschua sprach zu den Söhnen Israel: Tretet hier herzu und höret die Worte Jehovahs, eures Gottes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'Und Joschua sprach: Daran sollt ihr wissen, daß ein lebendiger Gott in eurer Mitte ist, und daß Er den Kanaaniter und den Chethiter und den Chiviter und den Pherisiter und den Girgaschiter und den Amoriter und den Jebusiter vor euch austreibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'Siehe, die Bundeslade des Herrn der ganzen Erde zieht vor euch hinüber im Jordan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Und nun nehmet euch zwölf Männer aus den Stämmen Israels, aus jedem Stamm je einen Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Und es wird geschehen, sowie die Sohlen der Füße der Priester, so die Lade Jehovahs, des Herrn der ganzen Erde, tragen, in den Wassern des Jordans ruhen, so werden die Wasser des Jordans abgeschnitten und die Wasser, die von oben herabkommen, werden wie ein Haufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Und es geschah, als das Volk aufbrach aus seinen Zelten, um über den Jordan zu setzen, und die Priester, so die Bundeslade vor dem Volke trugen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'Und wie die Träger der Lade bis an den Jordan kamen, und die Füße der Priester, welche die Lade trugen, ins Ende des Wassers sich tauchten, - der Jordan aber ist voll über allen seinen Ufern alle Tage der Ernte -,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'Da standen die Wasser, die von oben herabkamen, sie richteten sich auf in einen Haufen, sehr fern von der Stadt Adam, die zur Seite von Zarthan ist, und die Wasser, so zum Meer der Arabah, zum Salzmeer hinabgingen wurden alle, sie wurden abgeschnitten, und das Volk zog hinüber, gegenüber von Jericho.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Die Priester aber, welche die Bundeslade Jehovahs trugen, standen fest im Trockenen mitten im Jordan. Und ganz Israel ging im Trockenen durch, bis daß die ganze Völkerschaft den Durchzug des Jordans vollendet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'Und es geschah, wie die ganze Völkerschaft allesamt über den Jordan gegangen war, daß Jehovah zu Joschua sprach und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Nehmet euch aus dem Volk zwölf Männer, je einen Mann aus einem Stamm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'Und gebietet ihnen und sprechet: Hebt euch auf hier mitten aus dem Jordan, von der Stelle, wo die Füße der Priester festgestanden, zwölf Steine, und bringt sie mit euch hinüber und legt sie nieder an dem Nachtlager, darin ihr über Nacht bleibt diese Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Und Joschua rief den zwölf Männer aus den Söhnen Israels, die er bereit hatte, je einen Mann aus einem Stamm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'Und Joschua sprach zu ihnen: Gehet hinüber vor der Lade Jehovahs, eures Gottes, mitten in den Jordan, und hebt euch empor jeder Mann einen Stein auf seine Schulter nach der Zahl der Stämme der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'Auf daß dies ein Zeichen sei in eurer Mitte, wenn eure Söhne euch morgen fragen und sagen: Was sollen euch diese Steine?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'Da sollt ihr ihnen sagen, wie die Wasser des Jordans abgeschnitten wurden vor der Bundeslande Jehovahs, daß bei ihrem Übergang durch den Jordan die Wasser des Jordans abgeschnitten wurden, und daß diese Steine für die Söhne Israels seien ewiglich zum Andenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'Und die Söhne Israels taten also, wie ihnen Joschua geboten hatte, und hoben zwölf Steine aus der Mitte des Jordans auf, wie Jehovah zu Joschua geredet, nach der Zahl der Stämme der Söhne Israel, und brachten sie mit sich hinüber nach dem Nachtlager und legten sie nieder allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Und Joschua richtete zwölf Steine auf mitten im Jordan, an der Stelle der Füße der Priester, so die Bundeslade trugen, und sie sind dort bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Und die Priester, welche die Lade trugen, standen mitten im Jordan, bis daß alles getan war, das Jehovah dem Joschua geboten hatte, zu dem Volke zu reden, nach allem, das Mose dem Joschua geboten hatte; und das Volk eilte und zog hindurch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'Und es geschah, als das ganze Volk allesamt hindurchgegangen war, daß auch die Lade Jehovahs hindurchging und die Priester, angesichts des Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'Und die Söhne Rubens und die Söhne Gads und der halbe Stamm Menaschehs zogen kampfgerüstet vor den Söhnen Israels hinüber, wie Mose zu ihnen geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Bei vierzigtausend, zum Heere ausgerüstet, zogen hinüber vor Jehovah zum Streite auf Jerichos Flachland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'An jenem Tage machte Jehovah den Joschua groß vor den Augen von ganz Israel, und sie fürchteten ihn, wie sie Mose gefürchtet hatten, alle Tage seines Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'Und Jehovah sprach zu Joschua und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Gebiete den Priestern, welche die Lade des Zeugnisses tragen, daß sie aus dem Jordan heraufsteigen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Und Joschua gebot den Priestern und sprach: Steiget herauf aus dem Jordan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'Und es geschah, als die Priester, welche die Bundeslade Jehovahs trugen, heraufstiegen aus der Mitte des Jordans, als die Fußsohlen der Priester auf das Trockene sich herauszogen, da kehrten die Wasser des Jordans an ihren Ort zurück und gingen wie gestern und ehegestern, über alle seine Ufer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Und das Volk kam herauf aus dem Jordan am zehnten des ersten Monats und sie lagerten in Gilgal an der Grenze Jerichos gegen Aufgang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'Und jene zwölf Steine, die sie aus dem Jordan genommen, richtete Joschua in Gilgal auf;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'Und er sprach zu den Söhnen Israels und sagte: So eure Söhne morgen ihre Väter fragen werden und sagen: Was sollen diese Steine?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'So sollt ihr eure Söhne wissen lassen und ihnen sagen: Im Trockenen ist Israel durch den Jordan da durchgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Weil Jehovah, euer Gott, die Wasser des Jordans vor euch vertrocknet hatte, bis ihr durchgezogen waret, gleich wie Jehovah, euer Gott, mit dem Schilfmeere tat, das Er vor uns vertrocknete, bis wir durchgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'Auf daß alle Völker der Erde erkennen die Hand Jehovahs, daß sie stark ist, auf daß ihr Jehovah, euren Gott, fürchtet alle Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Und es geschah, da alle die Könige der Amoriter diesseits des Jordans nach dem Meere hin und alle die Könige der Kanaaniter am Meere hörten, wie Jehovah die Wasser des Jordans vor den Söhnen Israels vertrocknete, bis sie durchgezogen waren, da zerschmolz ihr Herz und es war kein Geist mehr in ihnen vor den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Zu selbiger Zeit sprach Jehovah zu Joschua: Mache dir steinerne Messer und beschneide wieder die Söhne Israels zum zweiten Male.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'Und Joschua machte sich steinerne Messer und beschnitt die Söhne Israels am Hügel Araloth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'Und so ist die Sache, daß Joschua sie beschnitt: Alles Volk, das aus Ägyptenland ausgezogen, die Männlichen, alle Männer des Streites, waren in der Wüste gestorben, auf dem Wege, da sie aus Ägypten auszogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'Denn alles Volk, das auszog, war beschnitten, aber alles Volk, das in der Wüste auf dem Wege, da man auszog aus Ägypten, geboren worden, war nicht beschnitten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Denn vierzig Jahre zogen die Söhne Israels in der Wüste, bis die ganze Völkerschaft alle war, die Männer des Streites, die aus Ägypten auszogen, weil sie nicht auf die Stimme Jehovahs gehört; weshalb ihnen Jehovah schwur, daß Er sie nicht wollte sehen lassen das Land, das uns zu geben Jehovah ihren Vätern geschworen hatte, ein Land, das mit Milch und Honig fließt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'Und er ließ aufstehen ihre Söhne an ihrer Statt; sie beschnitt Joschua; denn sie hatten Vorhaut, weil man sie auf dem Wege nicht beschnitt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'Und es geschah, als er beendigt hatte die ganze Völkerschaft zu beschneiden, daß sie an ihrer Stelle im Lager blieben, bis sie genesen waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'Und Jehovah sprach zu Joschua: Heute habe Ich die Schmach Ägyptens von euch gewälzt; und man nannte den Namen jenes Ortes Gilgal bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'Und die Söhne Israels lagerten in Gilgal und begingen das Passah, am vierzehnten Tage des Monats am Abend im Flachland Jerichos;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'Und sie aßen von der Frucht des Landes vom morgenden Tage nach dem Passah, Ungesäuertes und Geröstetes, an eben dem Tage;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'Und das Mannah hörte auf am morgenden Tag, da sie von der Frucht des Landes aßen; und die Söhne Israel hatten kein Mannah mehr; sondern sie aßen von dem Ertrag des Landes Kanaan in demselbigen Jahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Und es geschah, als Joschua bei Jericho war, daß er seine Augen aufhob und sah, und siehe, ein Mann stand ihm gegenüber und Sein gezücktes Schwert in Seiner Hand. Und Joschua ging zu Ihm und sprach zu Ihm: Bist Du für uns oder für unsere Dränger?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'Und Er sprach zu ihm: Nicht doch! Ich bin der Oberste des Heeres Jehovahs, jetzt komme Ich. Und Joschua fiel auf sein Angesicht zur Erde und betete an und sprach zu Ihm: Was redet Mein Herr zu Seinem Knechte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'Und der Oberste des Heeres Jehovahs sprach zu Joschua: Ziehe ab deinen Schuh von deinem Fuß; denn der Ort, auf dem du stehst, ist heilig. Und Joschua tat also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Und Jericho hatte geschlossen und war verschlossen vor den Söhnen Israels. Niemand kam heraus und niemand ging hinein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'Und Jehovah sprach zu Joschua: Siehe, Ich habe Jericho und seinen König samt den Mächtigen seiner Streitmacht in deine Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Und ihr sollt die Stadt umziehen, all ihr Männer des Streites, umringen die Stadt einmal; sechs Tage sollst du also tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'Und sieben Priester sollen sieben Jubelposaunen vor der Lade tragen. Und am siebenten Tage sollt ihr siebenmal die Stadt umziehen und die Priester in die Posaunen stoßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'Und es soll geschehen, wenn das Jubelhorn geblasen wird und ihr die Stimme der Posaune hört, so soll alles Volk mit großem Jubelruf jubeln, und die Mauer der Stadt wird fallen unter sich, und das Volk soll hinaufziehen, jeder Mann vor sich hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Und Joschua, der Sohn Nuns, rief die Priester und sprach zu ihnen: Traget die Bundeslade und sieben Priester sollen sieben Jubelposaunen vor der Lade Jehovahs tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Und zum Volke sprach er: Ziehet hin und umziehet die Stadt, und der Ausgerüstete ziehe her vor der Lade Jehovahs!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'Und es geschah, als Joschua zum Volke gesprochen hatte, daß die sieben Priester, welche die sieben Jubelposaunen vor Jehovah trugen, hinzogen und in die Posaunen stießen, und die Bundeslade Jehovahs hinter ihnen herging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'Der Ausgerüstete aber ging hin vor den Priestern, welche in die Posaune stießen und der Nachzug ging hinter der Lade, und sie gingen und stießen in die Posaunen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Und dem Volke hatte Joschua geboten und gesagt: Ihr sollt nicht jubeln und eure Stimme nicht hören lassen, und kein Wort soll aus eurem Munde gehen, bis zum Tage, da ich euch sage: Jubelt! Dann sollt ihr jubeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Und die Lade Jehovahs umzog einmal die Stadt, sie umringend; und sie kamen in das Lager und blieben über die Nacht im Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'Und Joschua machte sich früh am Morgen auf, und die Priester trugen die Lade Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'Und es gingen hin, die sieben Priester, welche die sieben Jubelposaunen vor der Lade Jehovahs trugen, sie gingen hin und stießen in die Posaunen, und der Ausgerüstete ging vor ihnen her, und der Nachzug ging hinter der Lade Jehovahs, sie zogen und stießen in die Posaunen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Und am zweiten Tage umzogen sie einmal die Stadt und kehrten in das Lager zurück. So taten sie sechs Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Und es geschah am siebenten Tage, daß sie früh aufstanden, da die Morgenröte aufging und nach dieser Weise siebenmal um die Stadt zogen. Nur an diesem Tage zogen sie siebenmal rings um die Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'Und es geschah beim siebenten Male, daß die Priester in die Posaunen stießen, und Joschua sprach zu dem Volke: Jubelt; denn Jehovah hat euch die Stadt gegeben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Und die Stadt sei, sie und alles, was in ihr ist, dem Jehovah verbannt! Nur die Buhlerin Rachab, sie und alles, was bei ihr im Haus ist, soll am Leben bleiben, weil sie die Boten, die wir sandten, versteckt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Hütet euch aber nur vor dem Verbannten, daß ihr euch nicht verbannt und nehmet vom Verbannten, daß ihr nicht das Lager Israels in Verbann bringt und es zerrüttet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Aber alles Silber und Gold und das eherne und eiserne Gerät soll Jehovah geheiligt sein, es soll in den Schatz Jehovahs kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Und das Volk jubelte und sie stießen in die Posaunen; und es geschah, als das Volk den Schall der Posaune hörte, und das Volk mit großem Jubelruf jubelte, da fiel die Mauer unter sich zusammen und das Volk ging hinauf in die Stadt, jeder Mann vor sich hin, und so eroberten sie die Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'Und sie verbannten alles in der Stadt mit der Schärfe des Schwertes, vom Manne bis zum Weibe, vom Jungen bis zum Alten und zum Ochsen und Kleinvieh und Esel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Und zu den zwei Männern, die das Land hatten ausgekundschaftet, sprach Joschua: Gehet hinein in das Haus des Weibes, der Buhlerin, und bringt von da heraus das Weib und alles, was sie hat, wie ihr derselben geschworen habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'Und die Jünglinge, die Kundschafter, gingen hinein und brachten die Rachab und ihren Vater und ihre Mutter und ihre Brüder und alles, das sie hatte, heraus; und sie brachten ihre ganze Familie heraus und ließen sie außerhalb des Lagers Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Und die Stadt verbrannten sie mit Feuer und alles, was darin war. Nur das Silber und das Gold und die ehernen und eisernen Geräte gaben sie in den Schatz des Hauses Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'Und Rachab, die Buhlerin, und ihres Vaters Haus und alles, was sie hatte, ließ Joschua am Leben und sie wohnte inmitten Israels bis auf diesen Tag, dafür, daß sie die Boten, die Joschua gesandt, um Jericho auszukundschaften, versteckt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Und Joschua schwur zur selben Zeit und sprach: Verflucht sei der Mann vor Jehovah, der aufsteht und diese Stadt Jericho baut. Um seinen Erstgeborenen soll er sie gründen, und um seinen Jüngstgeborenen ihre Tore einsetzen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Und Jehovah war mit Joschua, und im ganzen Lande war das Gerüchte ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Und die Söhne Israels begingen Untreue an dem Verbannten; und Achan, der Sohn Karmis, des Sohnes Sabdis, des Sohnes Serachs, vom Stamme Judah, nahm von dem Verbannten. Und der Zorn Jehovahs entbrannte wider die Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Und Joschua sandte Männer aus von Jericho nach Ai, das bei Beth Aven östlich von Bethel ist, und sprach zu ihnen und sagte: Ziehet hinauf und kundschaftet das Land aus. Und die Männer gingen hinauf und kundschafteten Ai aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'Und sie kehrten zu Joschua zurück und sprachen zu ihm: Laß nicht das ganze Volk hinaufziehen. Bei zweitausend Mann oder bei dreitausend Mann mögen hinaufziehen und Ai schlagen. Bemühe nicht das ganze Volk dahin; denn ihrer sind wenige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Und es zogen vom Volke bei dreitausend Mann dort hinauf, aber sie flohen vor den Männern von Ai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'Und die Männer von Ai schlugen ihrer bei sechsunddreißig Mann und setzten ihnen nach vor das Tor bis Schebarim, und schlugen sie beim Hinabgehen. Und dem Volke zerschmolz das Herz und ward zu Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Und Joschua zerriß seine Gewänder und fiel auf sein Angesicht zur Erde vor der Lade Jehovahs bis zum Abend, er und die Ältesten Israels und taten Staub auf ihr Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'Und Joschua sprach: Ach, Herr, Jehovah! Warum ließest Du doch dieses Volk über den Jordan herüberziehen, um uns in die Hand des Amoriters zu geben und uns zu zerstören! Hätten wir doch jenseits des Jordans bleiben wollen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Bitte, Herr, was soll ich sagen, nachdem Israel vor seinen Feinden den Rücken gekehrt hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'Und der Kanaaniter und alle Einwohner des Landes werden es hören, und uns umgeben und unseren Namen von der Erde ausrotten. Und was wirst Du für deinen großen Namen tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'Und Jehovah sprach zu Joschua: Stehe auf! Was fällst du da auf dein Angesicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Israel hat gesündigt und sie haben auch Meinen Bund überschritten, den Ich ihnen geboten; und sie haben auch von dem Verbannten genommen, und haben auch gestohlen, sie haben es auch abgeleugnet und es auch in ihr Gerät getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Und die Söhne Israels vermögen nicht aufzustehen vor ihren Feinden, sie müssen vor ihren Feinden den Rücken wenden; denn sie sind im Bann. Ich werde ferner nicht mit euch sein, wenn ihr den Bann nicht aus eurer Mitte vernichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Stehe auf, heilige das Volk und sprich: Heiligt euch auf morgen; denn also spricht Jehovah, der Gott Israels: Ein Bann ist in deiner Mitte, Israel. Du vermagst nicht aufzustehen vor deinen Feinden, bis ihr den Bann aus eurer Mitte tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Am Morgen aber sollt ihr nahen nach euren Stämmen, und es soll geschehen, daß der Stamm, den Jehovah herausnimmt, nahe nach seinen Familien, und die Familie, die Jehovah herausnimmt, soll nahen nach den Häusern, und das Haus, das Jehovah herausnimmt, soll nahen nach den Männern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'Und es soll geschehen, daß der, als im Bann herausgenommen wird, mit Feuer verbrannt werde, er und all das Seine, weil er den Bund Jehovahs überschritten und eine Torheit in Israel getan hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Und Joschua stand früh am Morgen auf und ließ Israel nach seinen Stämmen nahen, und der Stamm Judah ward herausgenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'Und er ließ die Familien Judahs nahen und die Familie der Sarchiten ward herausgenommen; und er ließ die Familie der Sarchiten nahen nach den Männern, und Sabdi ward herausgenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'Und er ließ nahen sein Haus nach den Männern, und es ward herausgenommen Achan, der Sohn Karmis, des Sohnes Serach, vom Stamme Judah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'Und Joschua sprach zu Achan: Mein Sohn, gib Jehovah, dem Gotte Israels die Ehre, und gib Ihm ein Bekenntnis, und sage mir doch an, was du getan hast und verhehle es nicht vor mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Und Achan antwortete dem Joschua und sprach: In Wahrheit, ich habe gesündigt an Jehovah, dem Gott Israels und so und so habe ich getan;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'Und ich sah unter der Beute einen guten Mantel aus Schinear und zweihundert Schekel Silber und eine Barre Goldes, fünfzig Schekel sein Gewicht. Und ich begehrte danach, und ich nahm sie. Und siehe, sie sind in der Erde verdeckt in der Mitte meines Zeltes, und das Silber darunter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Und Joschua sandte Boten, und sie liefen nach dem Zelt, und siehe, es war verdeckt in seinem Zelt, und das Silber darunter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'Und sie nahmen dieselben aus der Mitte des Zeltes und brachten sie herein zu Joschua und zu allen Söhnen Israels und schütteten sie aus vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Und Joschua nahm den Achan, den Sohn Serachs, und das Silber und den Mantel und die Zunge Goldes und seine Söhne und seine Töchter und seinen Ochsen und seinen Esel und sein Kleinvieh und sein Zelt und alles, was er hatte, und ganz Israel mit ihm brachten sie hinauf in den Talgrund Achor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'Und Joschua sprach: Wie du uns zerrüttet, so zerrütte dich Jehovah an diesem Tage. Und ganz Israel steinigte ihn mit Steinen und sie verbrannten sie mit Feuer und warfen Steine auf sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'Und sie errichteten über ihm einen großen Steinhaufen bis auf diesen Tag. Und Jehovah kehrte Sich zurück von der Entbrennung Seines Zornes. Darum nennt man den Namen selbigen Ortes Emek Achor bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'Und Jehovah sprach zu Joschua: Fürchte dich nicht und entsetze dich nicht. Nimm alles Kriegsvolk mit dir und mache dich auf und zieh hinauf nach Ai. Siehe, Ich habe den König von Ai und sein Volk und seine Stadt und sein Land in deine Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'Und du sollst mit Ai und seinem Könige tun, wie du mit Jericho und seinem Könige getan, nur möget ihr ihre Beute und ihr Vieh für euch rauben. Lege dir einen Hinterhalt für die Stadt hinter ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Und Joschua machte sich auf und alles Kriegsvolk, um nach Ai hinaufzuziehen. Und Joschua erwählte sich dreißigtausend Mann, Helden der Tapferkeit, und sandte sie ab in der Nacht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'Und er gebot ihnen und sprach: Sehet, ihr sollt wider die Stadt im Hinterhalte liegen hinter der Stadt. Entfernt euch nicht zu sehr von der Stadt, und seid allesamt bereit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Ich aber und alles Volk, das mit mir ist, wir werden uns der Stadt nähern, und wenn sie ausgehen uns entgegen wie zuerst, so werden wir vor ihnen fliehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'Und sie werden ausziehen uns nach, bis wir sie von der Stadt abgezogen haben; denn sie werden sagen: Sie fliehen vor uns, wie zuerst. Und wir werden fliehen vor ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'Ihr aber machet euch aus dem Hinterhalte auf und nehmt die Stadt ein. Und Jehovah, euer Gott, wird sie in eure Hand geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'Und es geschehe, wenn ihr die Stadt gewonnen habt, dann sollt ihr die Stadt mit Feuer anzünden; nach dem Worte Jehovahs sollt ihr tun. Sehet, ich habe es euch geboten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Und Joschua entließ sie und sie gingen in den Hinterhalt und blieben zwischen Bethel und Ai auf der Meerseite von Ai. Und Joschua blieb über Nacht inmitten des Volkes in dieser Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Und am Morgen stand Joschua früh auf, und musterte das Volk und zog hinauf, er und die Ältesten Jehovahs vor dem Volke nach Ai hinauf;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Und alles Kriegsvolk, das mit ihm war, zog hinauf, und sie traten herzu und kamen der Stadt gegenüber, und lagerten gen Mitternacht von Ai, und das Tal war zwischen ihm und Ai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Und er nahm bei fünftausend Mann und legte sie zwischen Bethel und Ai auf der Meerseite von Ai in Hinterhalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'Und so stellten sie das Volk, das ganze Lager, das gegen Mitternacht von der Stadt war, daß der hintere Teil auf der Meerseite der Stadt war, und Jehoschua zog in jener Nacht in die Mitte des Talgrundes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Und es geschah, als der König von Ai es sah, eilten die Männer von der Stadt und standen früh auf und zogen aus, Israel entgegen, zum Streite, er und all sein Volk, zur bestimmten Zeit vor das Flachland; er wußte aber nicht, daß hinter der Stadt ein Hinterhalt gegen ihn war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Und Jehoschua und ganz Israel wurden geschlagen vor ihnen, und sie flohen auf dem Wege nach der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'Und sie riefen alles Volk in der Stadt, hinter ihnen nachzusetzen, und sie setzten hinter dem Joschua nach und wurden von der Stadt abgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'Und kein Mann verblieb in Ai und Bethel, der nicht ausgezogen wäre, hinter Israel her; und sie ließen die Stadt geöffnet und setzten hinter Israel nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Und Jehovah sprach zu Joschua: Recke den Wurfspieß in deiner Hand wider Ai aus; denn Ich will sie in deine Hand geben. Und Joschua reckte den Wurfspieß, den er in seiner Hand hatte, wider die Stadt aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'Und der Hinterhalt stand eilig auf von seinem Orte und sie liefen, wie er seine Hand ausreckte, und kamen in die Stadt und eroberten sie; und sie eilten und steckten die Stadt mit Feuer an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Und die Männer von Ai wandten sich um hinter sich und sahen, und siehe, der Rauch der Stadt stieg gen Himmel auf, und sie hatten nicht, wohin sie fliehen sollten, dahin oder dorthin, und das Volk, das nach der Wüste geflohen war, kehrte um wider die, so ihnen nachgesetzt hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Und Joschua und ganz Israel sahen, daß der Hinterhalt die Stadt erobert hatte und daß der Rauch der Stadt aufging, und sie kehrten um und schlugen die Männer von Ai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'Und jene gingen aus der Stadt ihnen entgegen, so daß sie mitten zwischen Israel waren, die einen von hier und die anderen dorther; und sie schlugen sie, bis daß ihnen kein Rest verblieb, noch einer entkam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Und den König von Ai erfaßten sie lebendig und ließen ihn dem Joschua nahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'Und da Israel alle Einwohner von Ai auf dem Felde in der Wüste, wohin sie ihnen nachsetzten, vollends erwürgt hatte, und alle durch die Schärfe des Schwertes gefallen, so daß sie alle waren, da kehrte ganz Israel nach Ai zurück und sie schlugen es mit der Schärfe des Schwertes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'Und alle, die an jenem Tage gefallen waren, vom Manne bis zum Weibe, waren zwölftausend, alle Leute von Ai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Und Joschua zog seine Hand, damit er den Wurfspieß ausreckte, nicht zurück, bis daß er alle Einwohner von Ai verbannt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Nur das Vieh und die Beute dieser Stadt nahm Israel als Raub für sich, nach dem Worte Jehovahs, das Er dem Joschua geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Und Ai verbrannte Joschua und machte es zu einem ewiglichen Schutthaufen, zur Verwüstung, bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Und den König von Ai hängte er an einem Baume auf bis zur Zeit des Abends, und da die Sonne unterging, gebot Joschua, daß sie seinen Leichnam vom Baume abnehmen und an den Eingang des Stadttores werfen sollten. Und sie richteten einen großen Steinhaufen über ihm, bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Nun baute Joschua Jehovah, dem Gotte Israels einen Altar auf dem Berge Ebal,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'Wie Mose, der Knecht Jehovahs, den Söhnen Israels geboten hatte, wie geschrieben ist im Gesetzbuche Moses: einen Altar von ganzen Steinen, über die kein Eisen geschwungen ward, und sie opferten darauf Jehovah Brandopfer und schlachteten Dankopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'Und allda schrieb er auf die Steine eine Abschrift des Gesetzes Moses, das er vor den Söhnen Israels geschrieben hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'Und ganz Israel und seine Ältesten und Vorsteher und seine Richter standen auf beiden Seiten der Lade, gegenüber den Priestern, den Leviten, so die Bundeslade Jehovahs trugen, wie der Fremdling so der Eingeborene; die eine Hälfte gegenüber dem Berge Gerissim, und die andere Hälfte dem Berge Ebal gegenüber, wie Mose, der Knecht Jehovahs, zuerst geboten hatte, das Volk Israel zu segnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'Und danach las er alle Worte des Gesetzes, den Segen und den Fluch, wie alles geschrieben ist im Buche des Gesetzes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Da war kein Wort von allem, das Mose geboten hatte, das Joschua nicht las in Gegenwart der ganzen Versammlung Israels und den Weibern und Kindlein und dem Fremdling, der in ihrer Mitte wandelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Und es geschah, als dies hörten alle die Könige, die diesseits des Jordans auf dem Gebirge und in der Niederung und am ganzen Gestade des großen Meeres dem Libanon gegenüber wohnten, der Chethiter und der Amoriter, der Kanaaniter und der Pherisiter, der Chiviter und der Jebusiter;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'Kamen sie zusammen zu Hauf, einmütig wider Joschua und Israel zu streiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'Und die Einwohner Gibeons hörten, was Joschua mit Jericho und mit Ai getan hatte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'Da handelten sie auch mit List, gingen hin, machten sich eine Gesandtschaft und sie nahmen alte Säcke auf ihre Esel und alte, rissige und zusammengebundene Weinschläuche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'Und alte, geflickte Schuhe an ihre Füße und alte Gewänder an sich, und alles Brot ihrer Zehrung war vertrocknet und hatte Schimmelflecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'Und sie gingen zu Joschua in das Lager zu Gilgal und sprachen zu ihm und zu den Männern von Israel: Wir kommen aus fernem Lande, und nun schließet einen Bund mit uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Und die Männer von Israel sprachen zu dem Chiviter: Vielleicht wohnst du mitten unter mir, und wie sollte ich einen Bund mit dir schließen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'Und sie sprachen zu Joschua: Wir sind deine Knechte. Und Joschua sprach zu ihnen: Wer seid ihr, und von wannen kommt ihr?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Und sie sagten zu ihm: Aus einem sehr fernen Lande kommen deine Knechte wegen des Namens Jehovahs, deines Gottes; denn wir hörten Sein Gerücht, und alles, was Er in Ägypten hat getan;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'Und alles, was Er getan hat den zwei Königen des Amoriters jenseits des Jordans, dem Sichon, dem Könige von Cheschbon und Og, dem Könige von Baschan, der zu Aschtaroth war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Und unsere Ältesten und alle, die in unserem Lande wohnen, sprachen zu uns und sagten: Nehmet Zehrung in eure Hand auf den Weg, und geht ihnen entgegen und sprechet zu ihnen: Wir sind eure Knechte, und nun schließet einen Bund mit uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Dies unser Brot nahmen wir warm als Zehrung aus unseren Häusern am Tage, da wir auszogen, zu euch zu gehen, und siehe, nun ist es vertrocknet und mit Schimmelflecken;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'Und diese Weinschläuche füllten wir neu, und siehe, sie sind rissig geworden; und das sind unsere Gewänder und unsere Schuhe, sie sind von dem sehr vielen Wege alt geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'Und die Männer nahmen von ihrer Zehrung; aber den Mund Jehovahs fragten sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'Und Joschua machte Frieden mit ihnen und schloß einen Bund mit ihnen, sie am Leben zu lassen; und die Fürsten der Gemeinde schworen denselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Und es geschah am Ende dreier Tage, nachdem sie den Bund mit ihnen geschlossen hatten, da hörten sie, daß sie ihnen nahe wären und in ihrer Mitte wohnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Und die Söhne Israels brachen auf und kamen zu ihren Städten am dritten Tage; und ihre Städte waren Gibeon und Kephirah und Beeroth und Kirjath Jearim;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'Und die Söhne Israels schlugen sie nicht, weil die Fürsten der Gemeinde ihnen bei Jehovah, dem Gotte Israels, geschworen hatten; und die ganze Gemeinde murrte wider die Fürsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Und alle die Fürsten sprachen zu der ganzen Gemeinde: Wir haben ihnen bei Jehovah, dem Gotte Israels, geschworen, und nun vermögen wir nicht sie anzurühren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Das wollen wir ihnen tun, daß wir sie leben lassen, auf daß keine Entrüstung über uns sei um des Schwures willen, den wir ihnen geschworen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'Und die Fürsten sprachen zu ihnen: Sie sollen am Leben bleiben, aber Holzhauer und Wasserschöpfer für die ganze Gemeinde werden, wie die Fürsten zu ihnen geredet hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Und Joschua rief sie und redete zu ihnen und sprach: Warum habt ihr uns betrogen und gesagt: Wir sind sehr ferne von euch, und ihr wohnet doch mitten unter uns?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Und nun seid ihr verflucht! Nicht sollen unter euch aufhören der Knecht und die Holz hauen und Wasser schöpfen für das Haus meines Gottes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Und sie antworteten Joschua und sprachen: Man hatte deinen Knechten angesagt, was Jehovah, dein Gott, dem Mose, Seinem Knechte, geboten hat, daß er euch das ganze Land gebe, und daß ihr alle Einwohner des Landes vor euch her vernichten sollet. Darum fürchteten wir sehr für unsere Seelen vor euch, so daß wir dieses taten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Und nun, siehe, wir sind in deiner Hand. Was gut und was recht ist in deinen Augen uns zu tun, das tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'Und er tat ihnen also und errettete sie aus der Hand der Söhne Israels, daß sie sie nicht erwürgeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'Und Joschua machte sie selbigen Tages zu Holzhauern und Wasserschöpfern für die Gemeinde und für den Altar Jehovahs bis auf diesen Tag, an dem Ort, den Er erwählen würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Und es geschah, da Adoni-Zedek, König von Jerusalem, hörte, daß Joschua Ai erobert und es verbannt hatte, wie er Jericho und ihrem Könige getan, also tat er mit Ai und seinem Könige, und daß die Einwohner Gibeons mit Israel Frieden gemacht hätten und in ihrer Mitte waren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'Da fürchteten sie sich sehr; denn Gibeon war eine große Stadt, wie eine der Königsstädte, und weil sie größer den Ai und alle ihre Männer Helden waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Und Adoni-Zedek, König von Jerusalem, sandte zu Hoham, König von Chebron, und zu Piram, König von Jarmuth, und zu Japhia, König von Lachisch und zu Debir, König von Eglon, und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Ziehet herauf zu mir und stehet mir bei, daß wir Gibeon schlagen, weil es Frieden mit Joschua und mit den Söhnen Israels gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Und sie sammelten sich und zogen herauf, fünf Könige der Amoriter, der König von Jerusalem, der König von Chebron, der König von Jarmuth, der König von Lachisch, der König von Eglon, sie und all ihre Lager, und sie lagerten sich wider Gibeon und stritten dawider.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Und die Männer Gibeons sandten zu Joschua zum Lager nach Gilgal, und ließen ihm sagen: Laß deine Hand nicht ab von deinen Knechten. Zieh eilig herauf zu uns, und hilf uns und stehe uns bei; denn es sind wider uns zusammengekommen alle Könige des Amoriters, die auf dem Gebirge wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Und Joschua zog herauf von Gilgal, er und alles Kriegsvolk mit ihm, und alle tapferen Helden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Und Jehovah sprach zu Joschua: Fürchte dich nicht vor ihnen; denn Ich habe sie in deine Hände gegeben. Kein Mann von ihnen wird stehen vor dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'Und Joschua kam plötzlich über sie; denn er war die ganze Nacht von Gilgal heraufgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'Und Jehovah verwirrte sie vor Israel, und er schlug sie in einer großen Schlacht in Gibeon und setzte ihnen nach, den Weg der Steige von Beth-Choron hinan, und schlug sie bis nach Asekah und bis Makkedah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'Und es geschah, daß, als sie vor Israel flohen, da sie am Hinabsteigen von Beth-Choron waren, daß Jehovah große Steine vom Himmel auf sie warf, bis nach Asekah, daß sie starben. Mehr starben durch die Hagelsteine, als die Söhne Israels durch das Schwert erwürgt hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Damals redete Joschua zu Jehovah, am Tage, da Jehovah die Amoriter hingab vor den Söhnen Israels, und sprach vor den Augen Israels: Sonne, sei still in Gibeon, und du, Mond im Talgrunde Ajalon!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'Und die Sonne war stille, und der Mond stand, bis die Völkerschaft sich an den Feinden gerächt. Ist das nicht geschrieben in dem Buch Jaschar? Und es stand die Sonne an des Himmels Mitte und eilte nicht unterzugehen fast einen ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'Und vor ihm und nach ihm war kein solcher Tag, daß Jehovah auf eines Mannes Stimme hörte; denn Jehovah stritt für Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'Und Joschua und ganz Israel mit ihm kehrte zum Lager nach Gilgal zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'Und diese fünf Könige flohen und versteckten sich in der Höhle in Makkedah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'Und man sagte es dem Joschua an und sprach: Die fünf Könige sind gefunden, in der Höhle in Makkedah versteckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'Und Joschua sprach: Wälzet große Steine an die Mündung der Höhle und bestellet Männer darüber, die ihrer hüten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'Ihr aber bleibt nicht stehen, setzet hinter euren Feinden nach, schlagt von ihnen die Hintersten und laßt sie nicht in ihre Städte eingehen; denn Jehovah, euer Gott, hat sie in eure Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Und es geschah, als Joschua und die Söhne Israels vollendeten, und sie in der sehr großen Schlacht geschlagen hatten, bis sie alle wurden, und ein Rest von ihnen überblieb, und in die festen Städte gekommen war;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'Da kehrte alles Volk im Frieden in das Lager zu Joschua nach Makkedah zurück. Und keiner durfte wider einen Mann der Söhne Israels die Zunge spitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Und Joschua sprach: Öffnet die Mündung der Höhle und bringt diese fünf Könige zu mir heraus aus der Höhle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'Und sie taten so, und brachten zu ihm heraus aus der Höhle diese fünf Könige, den König von Jerusalem, den König von Chebron, den König von Jarmuth, den König von Lachisch, den König von Eglon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'Und es geschah, als man diese Könige zu Joschua herausgebracht hatte, da rief Joschua allen Männern von Israel und sprach zu den Anführern der Kriegsleute, die mit ihm gezogen: Nahet euch und setzet eure Füße auf die Hälse dieser Könige! Und sie nahten und setzten ihr Füße auf ihre Hälse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Und Joschua sprach zu ihnen: Fürchtet euch nicht und entsetzet euch nicht, seid stark und rüstig; denn so wird Jehovah allen euren Feinden tun, mit denen ihr streitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'Und Joschua schlug sie danach und tötete sie und hängte sie an fünf Bäume, und sie hingen an den Bäumen bis zum Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Und es geschah zur Zeit, da die Sonne unterging, gebot Joschua, sie sollten sie von den Bäumen abnehmen, und sie warfen sie in die Höhle, in der sie sich versteckt hatten, und sie legten große Steine auf die Mündung der Höhle, bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Und Makkedah eroberte Joschua an demselben Tage und schlug sie und ihren König mit der Schärfe des Schwertes; er verbannte sie und jede Seele, die darin war, und ließ keinen Rest verbleiben; und dem Könige von Makkedah tat er, wie er dem Könige von Jericho getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'Und Joschua und ganz Israel mit ihm zog hinüber von Makkedah gegen Libnah und er stritt wider Libnah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'Und Jehovah gab auch sie in die Hand Israels und ihren König, und er schlug sie mit der Schärfe des Schwertes, und jede Seele, die darin war; er ließ keinen Rest übrig, und tat ihrem Könige, wie er dem König von Jericho getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Und Joschua und ganz Israel mit ihm zog hinüber von Libnah nach Lachisch, und er lagerte wider dieselbe und stritt mit ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'Und Jehovah gab Lachisch in die Hand Israels, und es eroberte sie am zweiten Tag, und schlug sie mit der Schärfe des Schwertes und jede Seele darin, ganz so, wie er Libnah getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Damals zog Horam, König von Geser, herauf, um Lachisch beizustehen, aber Joschua schlug ihn und sein Volk, so daß er keinen Rest überließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'Und Joschua zog hinüber und ganz Israel mit ihm, von Lachisch nach Eglon, und sie lagerten wider dieselbe und stritten mit ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'Und sie eroberten sie am selbigen Tage und schlugen sie mit der Schärfe des Schwertes; und alle Seele, die darin war, verbannte er an selbigem Tage, ganz so wie er mit Lachisch getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'Und von Eglon zog Joschua und ganz Israel mit ihm hinauf nach Chebron, und sie stritten mit ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'Und sie eroberten sie, und schlugen sie und ihren König und alle ihre Städte, und jede Seele, die darin war, mit der Schärfe des Schwertes; er ließ keinen Rest übrig, ganz so wie er Eglon getan hatte, und verbannte sie und jede Seele, die darin war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Und Joschua und ganz Israel mit ihm kehrten zurück gen Debir und stritten mit ihr;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'Und eroberte dasselbe und seinen König und alle seine Städte, und sie schlugen sie mit der Schärfe des Schwertes, und sie verbannten jede Seele, die darinnen war, und ließen keinen Rest übrig. Wie er Chebron getan, so tat er Debir und ihrem Könige, und so wie er an Libnah und ihrem Könige getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Und Joschua schlug das ganze Land, das Gebirge und das Mittagland, und die Niederung und die Abhänge, und alle ihre Könige, er ließ keinen Rest übrig, und verbannte alles, was Odem hatte, wie Jehovah, der Gott Israels, geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'Und Joschua schlug sie von Kadesch-Barnea bis Gazah und das ganze Land Goschen bis Gibeon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'Und alle diese Könige und ihr Land eroberte Joschua mit einem Mal; denn Jehovah, der Gott Israels, stritt für Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'Und Joschua und ganz Israel mit ihm kehrte zum Lager nach Gilgal zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Und es geschah, da Jabin, der König von Chazor, es hörte, da sandte er an Jobab, den König von Madon und an den König von Schimron und an den König von Achschaph;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'Und an die Könige, die von Mitternacht her auf dem Gebirge und auf dem Flachland gen Mittag von Kinneroth und in der Niederung und in Naphoth Dor vom Meere her waren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'An den Kanaaniter vom Aufgang her und vom Meere her und den Amoriter und den Chethiter und den Pherisiter und den Jebusiter in dem Gebirge und den Chiviter unter dem Chermon im Lande Mizpah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'Und diese zogen aus, und all ihre Lager mit ihnen, viel Volkes wie der Sand am Ufer des Meeres an Menge; und sehr viel Rosse und Streitwagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Und es taten sich zusammen alle diese Könige, und kamen und lagerten beisammen an den Wassern Merom, um mit Israel zu streiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'Und Jehovah sprach zu Joschua: Fürchte dich nicht vor ihnen; denn morgen um diese Zeit gebe Ich sie alle erschlagen dahin vor Israel. Ihre Rosse sollst du lähmen und ihre Streitwagen im Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'Und Joschua und all das Kriegsvolk mit ihm kam plötzlich über sie an den Wassern Merom und fiel über sie her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'Und Jehovah gab sie in die Hand Israels; und sie schlugen sie und setzten ihnen nach bis Zidon, die große Stadt, und bis Misrephoth Majim und bis zur Talebene Mizpeh gegen Aufgang, und sie schlugen sie, bis ihnen kein Rest übrig war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'Und Joschua tat ihnen, wie ihm Jehovah gesagt hatte: Ihre Rosse lähmte er und verbrannte ihre Streitwagen im Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'Und Joschua kehrte um in selbiger Zeit und eroberte Chazor, und schlug dessen König mit dem Schwert. Denn Chazor war vordem das Haupt aller dieser Königreiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'Und jede Seele in ihr erschlugen sie mit der Schärfe des Schwertes und verbannten es, so daß nichts überblieb, in dem Odem war. Und Chazor verbrannte er mit Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'Und Joschua eroberte alle Städte dieser Könige und all ihre Könige, und schlug sie mit der Schärfe des Schwertes und verbannte sie, wie Mose, der Knecht Jehovahs, geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Jedoch verbrannte Israel keine der Städte, die auf Anhöhen standen; nur Chazor allein verbrannte Joschua.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'Und alle Beute dieser Städte und das Vieh nahmen die Söhne Israels als Raub für sich; nur die Menschen alle schlugen sie mit der Schärfe des Schwertes, bis sie sie vernichtet hatten. Nichts, das Odem hatte, ließen sie verbleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Wie Jehovah Seinem Knechte Mose geboten hatte, also gebot Mose dem Joschua; und also tat Joschua, und in keinem Worte wich dieser von allem ab, was Jehovah dem Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Und Joschua nahm dies ganze Land, das Gebirge und das ganze Mittagsland, und das ganze Land Goschen und die Niederung, und das Flachland, und das Gebirge Israel und seine Niederung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'Von dem kahlen Berge, der aufsteigt gen Seir, bis Baal Gad in der Talebene des Libanon unten am Berge Chermon; und alle ihre Könige eroberte er und schlug und tötete sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Viele Tage hatte Joschua Streit mit allen diesen Königen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Es war keine Stadt, die mit den Söhnen Israels Frieden machte, außer den Chivitern, den Einwohnern Gibeons; sie nahmen alle im Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Denn von Jehovah war es, daß sie ihr Herz bestärkten, im Streite Israel zu begegnen, um sie zu verbannen, auf daß ihnen keine Gnade widerführe, sondern sie vernichtet würden, wie Jehovah Mose geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'Und Joschua kam in selbiger Zeit und rottete die Enakim aus vom Gebirge, von Chebron, von Debir, von Anab, und vom ganzen Gebirge Judah und vom ganzen Gebirge Israel; mit ihren Städten verbannte sie Joschua.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Und man ließ keine Enakim im Lande der Söhne Israels übrigbleiben. Nur in Gazah, in Gath und in Aschdod verblieben sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Und Joschua nahm das ganze Land gemäß allem, was Jehovah zu Mose geredet hatte, und Joschua gab es Israel zum Erbe, nach den Teilen in ihren Stämmen, und das Land rastete vom Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Und dies sind die Könige des Landes, welche die Söhne Israels schlugen und deren Land sie eingenommen, jenseits des Jordans gegen Aufgang der Sonne vom Bache Arnon bis zum Berge Chermon, und das ganze Flachland gegen Aufgang;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sichon, der Amoriterkönig, der in Cheschbon wohnte und herrschte vor Aroer am Ufer des Baches Arnon und der Mitte des Baches und über die Hälfte von Gilead bis zum Bache Jabbok, der Grenze der Söhne Ammons;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'Und über das Flachland bis zum Meer Kinneroth gegen Aufgang und bis zum Meer des Flachlandes, dem Salzmeer, gegen Aufgang auf dem Wege nach Beth-Jeschimoth, und im Süden unten an den Abhängen des Pisgah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'Und die Grenze Ogs, des Königs von Baschan, der von den Riesen übrigblieb, und zu Aschtaroth und Edrei wohnte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'Und herrschte auf dem Berge Chermon und in Salchah und in ganz Baschan bis zur Grenze des Geschuriters und des Maachathiters, und über das halbe Gilead, zur Grenze Sichons, des Königs von Cheschbon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mose, der Knecht Jehovahs, und die Söhne Israels schlugen sie, und Mose, der Knecht Jehovahs, gab es als Erbbesitz dem Rubeniter und dem Gaditer und dem halben Stamm Menascheh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'Und dies sind die Könige des Landes, die Joschua schlug und die Söhne Israels diesseits des Jordans, dem Meere zu von Baal-Gad in der Talebene des Libanons und bis zum kahlen Berg, der aufsteigt gen Seir; und Joschua gab es den Stämmen Israels nach ihren Teilen zum Erbbesitz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'Auf dem Gebirge und in der Niederung und in dem Flachlande und an den Abhängen und in der Wüste und im Mittagsland; die Chethiter, die Amoriter und die Kanaaniter, die Pherisiter, die Chiviter und die Jebusiter:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'Der König von Jericho einer; der König von Ai, das zur Seite von Beth-El ist, einer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'Der König von Jerusalem einer; der König von Chebron einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'Der König von Jarmuth einer; der König von Lachisch einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'Der König von Eglon einer; der König von Geser einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'Der König von Debir einer; der König von Geder einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'Der König von Chorma einer; der König von Arad einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'Der König von Libnah einer; der König von Adullam einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'Der König von Makkedah einer; der König von Bethel einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'Der König von Tappuach einer; der König von Chepher einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'Der König von Aphek einer; der König Laschscharon einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'Der König von Madon einer; der König von Chazor einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'Der König von Schimron-Meron einer; der König von Achschaph einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'Der König von Taanach einer; der König von Megiddo einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'Der König von Kedesch einer; der König von Jokneam am Karmel einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'Der König von Dor zu Naphoth-Dor einer; der König von Gojim zu Gilgal einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'Der König von Tirzah einer. Aller Könige sind es einunddreißig..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Und Joschua war alt und betagt; und Jehovah sprach zu ihm: Du bist alt und betagt, und vom Lande verbleibt noch sehr viel einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'Das ist das verbleibende Land: alle Kreise der Philister und ganz Geschuri.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'Von Schichor, welcher vor Ägypten ist, und bis zur Grenze von Ektron gegen Norden wird es dem Kanaaniter zugerechnet; fünf Philisterfürsten sind es: der Gassiter, der Aschdoditer, der Aschkeloniter, der Gathiter, der Ekroniter und der Aviter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'Vom Süden, das ganze Land des Kanaaniters und Mearah der Zidonier bis Aphekah bis an die Grenze der Amoriter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'Und das Land der Gibliter und der ganze Libanon gegen Aufgang der Sonne von Baal-Gad an unten am Berge Chermon, bis man nach Chamath kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Alle, die auf dem Gebirge wohnen vom Libanon bis Misrephoth Maim, alle Zidonier werde Ich austreiben vor den Söhnen Israels. Nur verlose es Israel zum Erbe, wie Ich dir geboten habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Und nun teile dies Land zum Erbe den neun Stämmen und dem halben Stamm Menascheh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Mit ihm hatte der Rubeniter und der Gaditer ihr Erbe genommen, das ihnen Mose gab jenseits des Jordans gegen Aufgang, wie Mose, der Knecht Gottes, ihnen gegeben hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Von Aroer an, das am Ufer des Baches Arnon ist, und die Stadt in der Mitte des Baches, und die ganze Ebene Medebah bis Dibon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'Und alle Städte Sichons des Amoriter Königs, der in Cheschbon regierte, bis zur Grenze der Söhne Ammons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'Und Gilead und die Grenze der Geschuriter und Maachathiter und der ganze Berg Chermon und ganz Baschan bis Salchah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'Das ganze Königreich Ogs in Baschan, welcher in Aschtaroth und Edrei regierte. Er verblieb von dem Überreste der Riesen. Und Mose schlug sie und trieb sie aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'Und die Geschuriter und die Maachathiter trieben die Söhne Israels nicht aus; und Geschur und Maachath wohnen bis auf diesen Tag inmitten Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Nur dem Stamme Levi gab Er kein Erbe, die Feueropfer Jehovahs, des Gottes Israels, sind sein Erbe, wie Er zu ihm geredet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Und Mose gab dem Stamme der Söhne Ruben nach ihren Familien;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'Und ihre Grenze war von Aroer, das am Ufer des Baches Arnon ist, und die Stadt, die in der Mitte des Baches ist, und die ganze Ebene bei Medebah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Cheschbon und alle seine Städte, die in der Ebene sind, Dibon und Bamoth-Baal und Beth-Baal- Meon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Und Jahzah und Kedemoth und Mephaath;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Und Kirjathajim und Sibmah und ZerethHaschachar auf dem Berge des Talgrundes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Und Beth-Peor und die Abhänge des Pisgah, und Beth Hajeschimoth;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'Und alle Städte der Ebene und das ganze Königreich Sichons, des Amoriterkönigs, der in Cheschbon regierte, den Mose schlug, und die Fürsten Midians Evi und Rekem und Zur und Chur und Reba, die Gesalbten Sichons, die im Lande wohnten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Und Bileam, den Sohn Beors, den Wahrsager, erwürgten die Söhne Israels mit dem Schwert, samt den Erschlagenen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'Und es war die Grenze der Söhne Rubens der Jordan und die Grenze. Dies ist das Erbe der Söhne Rubens nach ihren Familien, die Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'Und Mose gab dem Stamme Gad, den Söhnen Gads, nach ihren Familien:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'Und ihre Grenze war Jaeser und alle Städte Gileads und die Hälfte des Landes der Söhne Ammons bis Aroer, welches vor Rabbah ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'Und von Cheschbon bis Ramath-Mizpeh und Betonim, und von Machanajim bis an die Grenze von Debir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'Und im Talgrunde Beth-Haram und Beth-Nimrah und Sukkoth und Zaphon, das übrige vom Königreiche des Sichon, des Königs von Cheschbon, war der Jordan die Grenze bis an das Ende des Meeres Kinneroth über dem Jordan nach dem Aufgang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'Dies ist das Erbe der Söhne Gads nach ihren Familien, die Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'Und Mose gab dem halben Stamme Menascheh, und der halbe Stamm der Söhne Menascheh sollte nach ihren Familien haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'Als Grenze von Machanajim an ganz Baschan, das ganze Königreich Ogs, des Königs von Baschan, und alle Flecken Jairs, die in Baschan waren, sechzig Städte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'Und das halbe Gilead und Aschtaroth und Edrei, die Städte in dem Königreiche Ogs in Baschan, den Söhnen Machirs, des Sohnes von Menascheh, der Hälfte der Söhne Machirs, nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Dies ist es, was Mose in dem Flachlande Moabs jenseits des Jordans gegen Aufgang von Jericho als Erbe verteilte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Und dem Stamm Levi gab Mose kein Erbe. Jehovah, der Gott Israels, ist ihr Erbe, wie Er zu ihnen geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Und dies ist, was die Söhne Israels im Lande Kanaan als Erbe erhielten, das ihnen zum Erbe verteilten Eleasar, der Priester, und Joschua, der Sohn Nuns, und die Häupter der Väter der Stämme, der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'Durch das Los, wie Jehovah durch Mose geboten hatte, verteilten sie das Erbe den neun Stämmen und dem halben Stamm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Denn Mose hatte den zwei Stämmen und dem halben Stamm das Erbe jenseits des Jordans gegeben, und den Leviten gab er kein Erbe in ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Denn die Söhne Josephs wurden zwei Stämme: Menascheh und Ephraim; und den Leviten gaben sie keinen Teil im Lande, sondern Städte zum Wohnen und deren Weichbilde für ihre Viehherden und ihren Besitz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Wie Jehovah Mose geboten hatte, so taten die Söhne Israels und verteilten das Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Und die Söhne Judahs traten herzu zu Joschua in Gilgal; und Kaleb, der Sohn Jephunnehs, der Kenissite, sprach zu ihm: Du weißt das Wort, das Jehovah zu Mose, dem Manne Gottes, in Kadesch Barnea meinetwegen und deinetwegen geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Vierzig Jahre war ich alt, als Mose der Knecht Jehovahs, mich aus Kadesch Barnea sandte, das Land auszukundschaften, und ich brachte ihm Nachricht zurück, wie es in meinem Herzen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Aber meine Brüder, die mit mir hinaufgezogen waren, machten das Herz des Volkes zerschmelzen; ich aber folgte Jehovah, meinem Gotte, völlig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'Und Mose schwur selbigen Tages und sprach: Fürwahr, das Land, das dein Fuß betreten hat, soll dir und deinen Söhnen zum Erbe sein ewiglich; denn du folgtest Jehovah, meinem Gotte, völlig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'Und nun siehe, Jehovah hat mich am Leben erhalten, wie Er geredet hat, diese fünfundvierzig Jahre, seit Jehovah dies Wort geredet hat zu Mose, da Israel in der Wüste zog, und nun siehe, ich bin diesen Tag fünfundachtzig Jahre alt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'Noch bin ich diesen Tag so stark, wie am Tage, da Mose mich sandte; wie meine Kraft war damals, so ist meine Kraft jetzt, zum Streit, zum Ausgang und zum Eingang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Und nun, gib mir diesen Berg, davon Jehovah an selbigem Tag geredet hat. Denn du hast an demselben Tage gehört, daß Enakim dort sind, und große, feste Städte. Vielleicht ist Jehovah mit mir, daß ich sie austreibe, wie Jehovah geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Und Joschua segnete ihn und gab Chebron dem Kaleb, dem Sohne Jephunnehs, zum Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Deshalb ward Chebron dem Kaleb, dem Sohne Jephunnehs, dem Kenissiten zum Erbe bis auf diesen Tag, darum, daß er Jehovah, dem Gotte Israels, völlig gefolgt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Und der Name Chebron war vordem Kirjath Arbah, eines Menschen, der groß war unter den Enakim; und das Land rastete vom Krieg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'Und das Los für den Stamm der Söhne Judahs nach ihren Familien war an der Grenze Edoms, die Wüste Zin, gegen Mittag am südlichen Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'Und ihre Mittagsgrenze war vom Ende des Salzmeeres an, von der Zunge, die sich gegen Mittag wendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'Und ging hinaus mittäglich von Maaleh Akrabbim und ging hinüber nach Zin und stieg mittäglich von Kadesch Barnea auf, und ging hinüber nach Chezron und stieg auf nach Addar und wandte sich nach Karka um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'Und ging hinüber nach Azmon und ging aus am Bache Ägyptens, und die Ausläufe der Grenze waren nach dem Meere hin. Dies soll eure Mittagsgrenze sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Und die Grenze nach Osten ist das Salzmeer bis an das Ende des Jordans. Und die Grenze nach der Seite gegen Mitternacht ist von der Meereszunge an vom Ende des Jordans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'Und die Grenze steigt auf nach Beth-Choglah, und geht hinüber von Mitternacht nach Beth-Arabah, und die Grenze steigt auf nach dem Stein Bohans, des Sohnes Rubens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'Und die Grenze steigt auf gen Debir vom Talgrunde Achor, und Mitternacht zu wendet sie sich gen Gilgal, der Maaleh Adummim stracks gegenüber, welches auf der Mittagseite des Baches liegt. Und die Grenze geht hinüber zu den Wassern von En-Schemesch, und seine Ausläufe gehen bis En-Rogel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'Und die Grenze steigt auf nach der Schlucht Ben Hinnom auf der Mittagseite des Jebusiters, das ist von Jerusalem, und von da steigt die Grenze auf die Spitze des Berges, der vor Ge Hinnom ist, dem Meere zu, am Ende des Talgrundes Rephaim gegen Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Und vom Gipfel des Berges erstreckt sich die Grenze hin nach dem Brunnquell der Wasser von Nephthoach und geht aus nach den Städten des Berges Ephron und die Grenze erstreckt sich nach Baalah, das ist Kirjath Jearim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'Und die Grenze wendet sich herum von Baalah nach dem Meere zum Berge Seir und geht hinüber an die Mitternachtseite des Jearimgebirges, das ist Chesalon, und geht hinab nach Beth-Schemesch und geht hinüber nach Timnah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'Und die Grenze geht aus nach der Mitternachtseite von Ekron; und die Grenze erstreckte sich nach Schikkeron und geht hinüber nach dem Berg von Baalah und geht aus nach Jabneel, und die Ausläufe der Grenze sind dem Meere zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'Und die Meeresgrenze ist am großen Meer und seiner Grenze. Dies ist die Grenze der Söhne Judah ringsum nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Und dem Kaleb, dem Sohne Jephunnehs, gab man nach Jehovahs Befehl an Joschua als Teil inmitten der Söhne Judahs Kirjath Arbah des Vaters des Enak, das ist Chebron.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'Und Kaleb trieb aus von da die drei Söhne Enaks, Scheschai und Achiman und Thalmai, die Enakskinder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'Und von dannen zog er hinauf gegen die Einwohner Debirs, und der Name Debirs war vordem Kirjath Sepher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'Und Kaleb sprach: Wer Kirjath Sepher schlägt und es erobert, dem gebe ich meine Tochter Achsah zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'Und Othniel, Sohn von Kenas, Kalebs Bruder, eroberte sie, und er gab ihm seine Tochter Achsah zum Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'Und es geschah, als sie einzog, trieb sie ihn an, von ihrem Vater Feld zu erbitten; und sie ließ sich vom Esel herab und Kaleb sprach zu ihr: Was ist dir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Und sie sprach: Gib mir einen Segen; du hast mir ein Mittagsland gegeben, so gib mir auch Wasser. Und er gab ihr die oberen Wasserquellen und die unteren Wasserquellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'Dies ist das Erbe des Stammes der Söhne Judahs nach seinen Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'Und es waren die Städte vom Ende des Stammes der Söhne Judahs an der Grenze Edoms gen Mittag: Kabzeel und Eder und Jagur.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Und Kinah und Dimonah und Adadah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Und Kadesch und Chazor und Jithnan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Siph und Telem und Bealoth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Und Chazor, Chadathah und Kerijoth, Chezron, das ist Chazor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam und Schema und Moladah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Und Chazar-Gaddah und Cheschmon und Beth Pelet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Und Chazar Schual und Beerschabah und Bisjothjah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baalah und Ijim und Ezem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Und Eltholad und Chesil und Chormah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Und Ziklag und Madmannah und Sansannah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Und Lebaoth und Schilchim und Ain und Rimmon, im ganzen neunundzwanzig Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'In der Niederung Eschthaol und Zorah und Aschnah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Und Sanoach, und En-Gannim, Tappuach und Enam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmuth und Adullam, Sochoh und Asekah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Und Schaarajim und Adithaim und Gederah und Gederothajim, vierzehn Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Zenan und Chadaschah und Migdal-Gad.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Und Dilean, Mizpeh und Joktheel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lachisch und Bozkath und Eglon;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Und Chabbon und Lachmas und Kithlisch;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Und Gederoth, Beth-Dagon und Naamah und Makkedah; sechzehn Städte und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libnah und Ether und Aschan;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Und Jiphtach und Aschnah und Nezib;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Kegilah und Achsib und Mareschah; neun Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron und ihre Töchterstädte und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'Von Ekron ab und dem Meere zu alles, was zur Seite von Aschdod ist, und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Aschdod, seine Töchterstädte und seine Dörfer, Gassah, seine Töchterstädte und seine Dörfer; bis an den Bach Ägyptens und an das große Meer und seine Grenze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'Und auf dem Gebirge Schamir und Jathir und Sochoh;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Und Dannah und Kirjath-Sannah, das ist Debir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Und Anab, Eschthemoh und Anim;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Und Goschen und Cholon und Giloh, elf Städte und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab und Dumah und Eschan;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Und Janum und Beth-Tappuach und Aphekah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Und Chummetah und Kirjath-Arbah, das ist Chebron, und Zior, neun Städte und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel und Siph und Jutah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Und Jisreel und Jokdeam und Sanoach;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kajin, Gibeah und Timnah, zehn Städte und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Chalchul, Beth-Zur und Gedor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Und Maarath und Beth und Anoth und Elthekon, sechs Städte und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjath Baal das ist Kirjath Jearim und Rabbah, zwei Städte und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'In der Wüste Beth-Arabah, Middin und Sechachah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Und Nibschan und Ir-Hammelach und En-Gedi, sechs Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Und die Jebusiter, die in Jerusalem wohnen, vermochten die Söhne Judahs nicht auszutreiben; und der Jebusiter wohnt mit den Söhnen Judahs in Jerusalem bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'Und für die Söhne Josephs kam heraus das Los vom Jordan bei Jericho an die Wasser von Jericho gegen Aufgang; die Wüste hinaufsteigend von Jericho in das Gebirge nach Bethel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'Und sie ging aus von Bethel gen Lus und zog sich hinüber nach der Grenze des Architers nach Ataroth;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'Und ging hinab dem Meere zu an die Grenze des Japhletiters bis zur Grenze des unteren Beth-Chorons und bis nach Geser, und seine Ausläufe waren an das Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'Und die Söhne Josephs erhielten es als Erbe, Menascheh und Ephraim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'Und die Grenze der Söhne Ephraims nach ihren Familien war: die Grenze ihres Erbes war aber gegen den Aufgang von Atroth-Addar bis gegen das obere Beth-Choron.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'Und die Grenze ging hinaus nach dem Meere, gen Michmethath nördlich; und die Grenze wandte sich herum nach dem Aufgang bis Thaanath-Schiloh und zog sich hinüber vom Aufgang gen Janochah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'Und ging hinab von Janochah nach Ataroth und Naarath und stieß an Jericho und ging aus an den Jordan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Von Tappuach ging die Grenze dem Meere zu gen Nachal Kanah. Und ihre Ausläufe waren an das Meer. Dies ist das Erbe des Stammes der Söhne Ephraims nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'Und die den Söhnen Ephraims ausgeschiedenen Städte waren inmitten des Erbes der Söhne Menaschehs, alle Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Sie trieben aber die Kanaaniter, die in Geser wohnten, nicht aus; und der Kanaaniter wohnt mitten unter Ephraim bis auf diesen Tag und wurde zum zinsbaren Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'Und es ward ein Los dem Stamme Menaschehs, denn er war der Erstgeborene Josephs: an Machir, den Erstgeborenen Menaschehs, den Vater des Gilead; denn er war ein Kriegsmann, und es ward ihm Gilead und Baschan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Und die übrigen Söhne Menaschehs nach ihren Familien: an die Söhne Abiesers und an die Söhne Cheleks und an die Söhne Asriels und an die Söhne Schechems und an die Söhne Chephers und an die Söhne Schemidas. Dies sind die Söhne Menaschehs, des Sohnes Josephs, die männlichen nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Und Zelophchad, der Sohn Chephers ein Sohn Gileads, des Sohnes Machirs, des Sohnes Menaschehs, hatte keine Söhne, sondern nur Töchter. Und dies sind die Namen seiner Töchter: Machlah und Noah, Choglah, Milkah und Thirzah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Und sie nahten vor Eleasar, den Priester, und vor Joschua, den Sohn Nuns, und die Fürsten und sprachen: Jehovah hat dem Mose geboten, uns ein Erbe inmitten unserer Brüder zu geben; und er gab ihnen nach dem Munde Jehovahs ein Erbe in der Mitte der Brüder ihres Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'Und es fielen auf Menascheh zehn Erbteile, außer dem Lande Gilead und Baschan, jenseits des Jordans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'Denn die Töchter Menaschehs erbten ein Erbe in der Mitte seiner Söhne, und das Land Gilead ward den übrigen Söhnen Menaschehs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'Und es war die Grenze Menaschehs von Ascher bis Michmethath, welches vor Schechem ist, und es ging die Grenze zur Rechten zu den Einwohnern von En-Tappuach;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Dem Menascheh ward das Land Tappuach; aber Tappuach an der Grenze Menaschehs ward den Söhnen Ephraims. Jos.16/8f.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Und die Grenze ging hinab an Nachal Kanah auf der Mittagseite von dem Bache. Diese Städte sind Ephraims in der Mitte der Städte Menaschehs. Und die Grenze Menaschehs war nördlich vom Bache; und ihre Ausläufe waren an das Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'Nach Mittag war es des Ephraim und nach Norden des Menascheh, und das Meer war seine Grenze; und an Ascher stießen sie gegen Mitternacht und gegen Aufgang an Issaschar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Und des Menascheh waren in Issaschar und in Ascher: Beth-Schean und ihre Töchter- städte, und Jibleam und ihre Töchterstädte, und die Einwohner von Dor und ihre Töchterstädte, und die Einwohner von Endor und deren Töchterstädte, und die Einwohner von Thaanach und ihre Töchterstädte, und die Einwohner von Megiddo und ihre Töchterstädte, drei Landstriche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Und die Söhne Menaschehs vermochten nicht diese Städte einzunehmen und ließen den Kanaaniter im Lande wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Und es geschah, als die Söhne Israels stärker wurden, machten sie sich den Kanaaniter zinsbar, trieben ihn aber nicht aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Und die Söhne Josephs redeten zu Joschua und sagten: Warum hast du mir nur ein Los und einen Erbteil zum Erbe gegeben, und ich habe viel Volks, sintemal Jehovah mich so gesegnet hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'Und Joschua sprach zu ihnen: Wenn du viel Volk hast, so zieh hinauf in den Wald und haue ihn dir dort nieder, im Lande der Pherisiter und der Rephaim, so euch zu eng ist das Gebirge Ephraim!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'Und die Söhne Josephs sprachen: Den Berg werden wir nicht erlangen, und alle Kanaaniter, die in dem Lande des Talgrundes wohnen, die in Beth-Schean und ihren Töchterstädten und die im Tale Jesreel haben eiserne Streitwagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Und Joschua sprach zu dem Hause Joseph, zu Ephraim und Menascheh und sagte: Viel Volks hast du und hast große Kraft. Du sollst nicht ein Los haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'Sondern einen Berg sollst du haben, da Wald ist, und so du ihn niederhaust, sollen seine Ausläufe dein sein, denn du wirst den Kanaaniter austreiben, so er auch eiserne Wagen hat, so stark ist er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'Und es versammelte sich die ganze Gemeinde der Söhne Israels in Schiloh und richteten daselbst das Versammlungszelt auf; denn das Land war vor ihnen unterworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Und es waren noch sieben Stämme unter den Söhnen Israels übrig, denen noch nicht ein Erbe verteilt war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'Und Joschua sprach zu den Söhnen Israels: Wie lange wollt ihr lässig sein, hinzugehen und das Land einzunehmen, das Jehovah, der Gott eurer Väter, euch gegeben hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Gebet her für euch von je einem Stamm drei Männer, daß ich sie sende und sie sich aufmachen und im Land umhergehen und es beschreiben zum Behuf ihres Erbes und kommen zu mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'Und ihr sollt es in sieben Teile teilen. Judah bleibe im Mittagsland in seinen Grenzen stehen, und das Haus Joseph bleibe auf seinen Grenzen im Norden stehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Und ihr sollt das Land in sieben Teile schreiben, und es zu mir hierher bringen, auf daß ich euch hier vor Jehovah, unserem Gott, das Los werfe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Denn keinen Teil haben in eurer Mitte die Leviten; denn das Priestertum Jehovahs ist ihr Erbe. Und Gad und Ruben und der halbe Stamm Menaschehs haben jenseits des Jordans gegen den Aufgang ihr Erbe, das ihnen Mose, der Knecht Jehovahs, gegeben hat, genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Und die Männer machten sich auf und gingen. Und Joschua gebot denen, die gingen, das Land zu beschreiben und sprach: Gehet hin und durchwandelt das Land und beschreibt es und kommt zu mir zurück, auf daß ich hier vor Jehovah in Schiloh das Los für euch werfe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'Und die Männer gingen und durchzogen das Land und beschrieben es nach den Städten zu sieben Teilen in ein Buch und kamen zu Joschua in das Lager nach Schiloh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Und Joschua warf für sie das Los in Schiloh vor Jehovah, und Joschua verteilte allda das Land den Söhnen Israels nach ihren Teilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'Und herauf kam das Los des Stammes der Söhne Benjamins nach seinen Familien. Und die Grenze ihres Loses kam heraus zwischen den Söhnen Judahs und den Söhnen Josephs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'Und ihre Grenze war an der Nordecke am Jordan, und die Grenze stieg auf hinter auf der Nordseite und ging hinauf auf den Berg gegen das Meer, und ihre Ausläufe waren nach der Wüste Beth Aven.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'Und von dannen ging die Grenze hinüber nach Lus, an die Mittagseite von Lus, das ist Bethel, und die Grenze geht hinab nach Atroth Addar auf den Berg, der an der Mittagseite des unteren Beth-Chorons ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Und die Grenze erstreckte sich und wendete sich herum zur Westseite mittäglich von dem Berge, der gegen Mittag vor Beth-Choron liegt, und seine Ausläufe waren bis Kirjath-Baal, das ist Kirjath-Jearim, eine Stadt der Söhne Judahs. Dies ist die Westseite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Und die Mittagsecke ist vom Ende von Kirjath-Jearim, und die Grenze ging aus meerwärts, und ging aus nach dem Brunnquell der Wasser des Nephtoach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'Und die Grenze ging hinab nach dem Ende des Berges, der vor der Schlucht Ben-Hinnoms, die im Talgrunde Rephaim gegen Mitternacht ist, und ging hinab in die Schlucht Hinnoms zur Mittagseite des Jebusiters und ging hinab bis En Rogel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'Und erstreckte sich von Mitternacht und ging hinaus nach En Schemesch und ging aus nach Geliloth, das der Steige Adummim gerade gegenüber, und geht hinab zum Stein Bohans, des Sohnes Rubens;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'Und sie zog hinüber an die Seite der Arabah gegen Mitternacht und ging hinab nach der Arabah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'Und die Grenze ging hinüber nach dem Rücken von Beth-Choglah gegen Mitternacht, und waren seine Ausläufe, die Grenze nach der Zunge des Salzmeeres gegen Mitternacht an dem mittäglichen Ende des Jordans. Das ist die Grenze gegen Mittag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Und der Jordan begrenzt es auf der Ostseite. Das ist das Erbe der Söhne Benjamins nach ihren Grenzen ringsum nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Und die Städte des Stammes der Söhne Benjamins nach ihren Familien waren Jericho und Beth-Chogla und Emik Geziz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Und Beth-Arabah und Zemarajim und Bethel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Und Avim und Parah und Ophrah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Und Chephar Ammonai und Ophni und Geba, zwölf Städte und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon und Ramah und Beeroth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Und Mizpeh und Chephirah und Mozah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Und Rekem und Jirpeel und Tharalah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Und Zela, Eleph und Jebusi, das ist Jerusalem, Gibath, Kirjath, vierzehn Städte und ihre Dörfer. Das ist das Erbe der Söhne Benjamins nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'Und das zweite Los kam heraus für Schimeon, für den Stamm der Söhne Schimeons nach ihren Familien; und ihr Erbe war inmitten des Erbes der Söhne Judahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'Und für sie waren in ihrem Erbe: Beer-Schaba und Scheba und Moladah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Und Chazar-Schual und Balah und Ezem;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Und Eltholad und Bethul und Chormah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Und Ziklag und Beth Marchaboth und Chazar Susah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Und Beth-Lebaoth und Scharuchen, dreizehn Städte und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ain, Rimmon und Ether und Aschan, vier Städte und ihre Dörfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'Und alle Dörfer, die rings um diese Städte waren bis Baalath-Beer, Ramath-Negeb. Dies das Erbe des Stammes der Söhne Schimeons nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Von dem Erbteil der Söhne Judahs ward das Erbe der Söhne Schimeons; denn der Teil der Söhne Judahs war zu viel für sie und die Söhne Schimeons erbten in der Mitte ihres Erbes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Und das dritte Los stieg auf für die Söhne Sebuluns nach ihren Familien und die Grenze ihres Erbes war bis Sarid;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'Und ihre Grenze ging hinauf gegen das Meer und Maralah und stieß an den Bach vor Jokneam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'Und von Sarid wendete es sich herum nach Osten, nach dem Aufgang der Sonne nach der Grenze von Chisloth-Thabor und ging hinaus nach Dabrath und ging hinauf nach Japhia.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'Und von da ging sie hinüber nach Osten nach dem Aufgang gen Gath-Chepher, gen Itha-Kazin und ging aus nach Rimmon- Methoar, Neah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'Und die Grenze wandte sich um dieses nördlich nach Channathon, und ihre Ausläufe waren in der Schlucht Jiphtach-El.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'Und Kattath und Nahalal und Schimron und Jidalah und Bethlechem, zwölf Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'Dies ist das Erbe der Söhne Sebuluns nach ihren Familien: Diese Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Für Issaschar kam das vierte Los heraus, für die Söhne Issaschars nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'Und ihre Grenze war: Jisreel, Chessulloth und Schunem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Und Chapharajim und Schion und Anacharath;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Und Rabbith und Kischjon und Ebez;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Und Remeth und En-Gannim und En-Chaddah und Beth-Pazzez;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'Und stieß die Grenze an Thabor und Schachazimah und Beth-Schemesch, und waren die Ausläufe ihrer Grenze am Jordan. Sechzehn Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'Das ist das Erbe des Stammes der Söhne Issaschars nach ihren Familien, die Städte und ihr Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Und das fünfte Los kam heraus für den Stamm der Söhne Aschers nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'Und ihre Grenze war: Chelkath und Chali und Beten und Achschaph.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Und Allammelech und Amad und Mischal; und dem Meere zu stieß sie an den Karmel und an Schichor-Libnath;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'Und wandte sich zurück nach dem Aufgang der Sonne gen Beth-Dagon und stieß an Sebulun und an die Schlucht Jiphthach-El, nördlich von Beth-Emek und Negiel und ging hinaus nach Kabul zur Linken;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'Und Ebron und Rechob und Chammon und Kanah bis Zidon, der großen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'Und die Grenze wandte sich zurück nach Ramah und bis zur Stadt Mizbar-Zor; und die Grenze wandte sich zurück nach Chosah, und ihre Ausläufe waren nach dem Meere hin vom Landstrich nach Achsib;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'Und Ummah und Aphek und Rechob, zweiundzwanzig Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'Dies ist das Erbe des Stammes der Söhne Aschers nach ihren Familien, diese Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Für die Söhne Naphthalis kam das sechste Los heraus, für die Söhne Naphthalis nach ihren Familien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'Und ihre Grenze war von Cheleph, von Elon in Zaanannim und Adami Nekeb und Jabneel bis Lakkum, und ihre Ausläufe waren an den Jordan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'Und die Grenze wandte sich zurück dem Meere zu nach Asnoth Thabor und ging von da aus nach Chukkok und stieß an Sebulun auf der Mittagseite und an Ascher stieß sie gegen das Meer, und am Jordan gegen Aufgang der Sonne an Judah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'Und feste Städte hatten sie: Ziddim, Zer und Chammath, Rakkath und Chinnereth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Und Adamah und Ramah und Chazor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Und Kedesch und Edrei und En-Chazor;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Und Jiron und Migdal-El, Chorem und Beth-Anath und Beth-Schemesch, neunzehn Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'Dies ist das Erbe des Stammes der Söhne Naphthalis nach ihren Familien: die Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Für den Stamm der Söhne Dans nach ihren Familien kam heraus das siebente Los.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'Und die Grenze ihres Erbes war: Zorah und Eschthaol und Ir-Schemesch;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Und Schaalabbin und Ajalon und Jithlah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Und Elon und Timnatha und Ekron');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Und Elthekeh und Gibbethon und Baa- lath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Und Jehud und Bene-Barak, und Gath-Rimmon;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Und Me-Jarkon und Rakkon mit der Grenze gegen Japho.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'Und die Grenze der Söhne Dans ging über sie hinaus, und die Söhne Dans zogen hinauf und stritten mit Leschem und eroberten sie und schlugen sie mit der Schärfe des Schwertes und nahmen sie ein und wohnten darin, und nannten Leschem Dan nach dem Namen ihres Vaters Dan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'Das ist das Erbe des Stammes der Söhne Dans nach ihren Familien, diese Städte und ihre Dörfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Und als sie die Erbverteilung des Landes nach seinen Grenzen vollendet hatten, da gaben die Söhne Israels Joschua, dem Sohne Nuns, ein Erbe in ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'Nach dem Munde Jehovahs gaben sie ihm die Stadt, die er sich erbeten, Timnath-Serach, auf dem Gebirge Ephraim, und er baute die Stadt und wohnte darin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'Dies sind die Erbe, die Eleasar, der Priester, und Joschua, der Sohn Nuns, und die Häupter der Väter der Stämme der Söhne Israels in Schiloh vor Jehovah am Eingang des Versammlungszeltes durch das Los zum Erbe verteilten, und sie vollendeten die Verteilung des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'Und Jehovah redete zu Joschua und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Rede zu den Söhnen Israels und sprich: Nehmet euch die Zufluchtsstätte, von denen Ich zu euch durch Moses Hand geredet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'Auf daß dahin fliehe der Totschläger, der eine Seele aus Versehen und ohne Wissen geschlagen hat; und sie sollen euch eine Zuflucht vor dem Bluträcher sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'Und der da flieht zu einer von diesen Städten, soll stehen am Eingang des Tores der Stadt, und soll vor den Ohren der Ältesten dieser Stadt seine Worte reden, und sie sollen ihn zu sich in die Stadt nehmen und ihm einen Ort geben, daß er bei ihnen wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'Und so der Bluträcher ihm hinten nachsetzt, sollen sie den Totschläger nicht in seine Hand überantworten, weil er ohne Wissen seinen Genossen geschlagen hat, und hat ihn nicht seit gestern oder ehegestern gehaßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Und er wohne in selbiger Stadt, bis daß er vor der Gemeinde zu Gericht stehe, bis daß sterbe der Hohepriester, der in denselben Tagen sein wird. Alsdann darf der Totschläger in seine Stadt und in sein Haus zurückkehren, zur Stadt, aus der er geflohen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'Und sie heiligten Kedesch im Galil auf dem Gebirge Naphthali und Schechem auf dem Gebirge Ephraim und Kirjath-Arbah, das ist Chebron, auf dem Gebirge Judah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'Und jenseits des Jordans bei Jericho nach dem Aufgang zu, gaben sie Bezer in der Wüste in der Ebene vom Stamme Rubens, und Ramoth in Gilead vom Stamme Gad, und Golan in Baschan vom Stamm Menascheh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Dies waren die Städte, bestimmt für alle Söhne Israels und den Fremdling, der sich in ihrer Mitte aufhält, auf daß dahin fliehe jeder, der aus Versehen eine Seele schlägt, auf daß er nicht durch die Hand des Bluträchers sterbe, bis daß er vor der Gemeinde gestanden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Und es traten herzu die Häupter der Väter der Leviten zu Eleasar, dem Priester, und zu Joschua, dem Sohne Nuns, und zu den Häuptern der Stammväter der Söhne Israels;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'Und redeten zu ihnen in Schiloh im Lande Kanaan und sprachen: Jehovah hat durch Moses Hand geboten, daß man uns Städte zum Wohnen und ihre Weichbilder für unser Vieh geben soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Und die Söhne Israels gaben den Leviten von ihrem Erbe, nach dem Ausspruch Jehovahs, diese Städte und ihre Weichbilder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'Und es kam heraus das Los für die Familien der Kohathiter, und es wurden den Söhnen Aharons, des Priesters, aus den Leviten, vom Stamme Judah und vom Stamme der Schimeoniter und vom Stamme Benjamin durch das Los dreizehn Städte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Und den übrigen Söhnen Kohaths von den Familien des Stammes Ephraim und vom Stamme Dan und vom halben Stamm Menascheh durch das Los zehn Städte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Und den Söhnen Gerschons von den Familien des Stammes Issaschar und von dem Stamme Ascher und von dem Stamme Naphthali und dem halben Stamm Menascheh und Baschan durch das Los dreizehn Städte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Den Söhnen Meraris nach ihren Familien vom Stamme Ruben und vom Stamme Gad und vom Stamme Sebulun zwölf Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'So gaben durch das Los die Söhne Israels den Leviten diese Städte und ihre Weichbilder, wie Jehovah durch die Hand Moses geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Und aus dem Stamme der Söhne Judahs und aus dem Stamme der Söhne Schimeons gaben sie diese Städte, die mit Namen genannt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'Und sie wurden den Söhnen Aharons von den Familien der Kohathiter, von den Söhnen Levis, denn ihnen ward das Los zuerst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Und sie gaben ihnen Kirjath Arbahs, des Vaters von Anok, das ist Chebron, auf dem Gebirge Judah und sein Weichbild rings um sie her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Aber das Feld der Stadt und ihre Dörfer gaben sie Kaleb, dem Sohn Jephunnehs als Eigentum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'Und den Söhnen Aharons, des Priesters, gaben sie die Zufluchtsstadt für den Totschläger, Chebron und ihr Weichbild,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'Und Jathir und ihr Weichbild und Eschthemoa und ihr Weichbild.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'Und Cholon und ihr Weichbild und Debir und ihr Weichbild.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'Und Ajin und ihr Weichbild, und Juttah und ihr Weichbild, und Beth Schemesch und ihr Weichbild, und neun Städte von diesen zwei Stämmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Und vom Stamme Benjamin Gibeon und ihr Weichbild, und Gebah und ihr Weichbild,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Und Anathoth und ihr Weichbild und Almon und ihr Weichbild, vier Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Alle Städte der Söhne Aharons, des Priesters, waren dreizehn Städte und ihre Weichbilder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'Und den übrigen Familien der Söhne Kohaths, der Leviten von den Söhnen Kohaths, wurden Städte ihres Loses vom Stamme Ephraim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'Und sie gaben ihnen die Zufluchtsstadt für den Totschläger: Sichem und dessen Weichbild auf dem Gebirge Ephraim und Geser und ihr Weichbild,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'Und Kibzajim und ihr Weichbild und Beth-Choron und ihr Weichbild, vier Städte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'Und vom Stamme Dan: Eltheke und ihr Weichbild und Gibbethon und ihr Weichbild,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajjalon und ihr Weichbild, Gath-Rimmon und ihr Weichbild, vier Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Und von der Hälfte des Stammes Menascheh Thaanach und ihr Weichbild, zwei Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Aller Städte waren es zehn mit ihren Weichbildern für die Familien der Söhne Kohaths, die noch übrig waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'Und den Söhnen Gerschons von den Familien der Leviten gab man vom halben Stamm Menascheh die Zufluchtsstadt des Totschlägers: Golan in Baschan und ihr Weichbild, und Beeschtherah und ihr Weichbild, zwei Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Und vom Stamme Issaschar Kischjon und ihr Weichbild, Dobrath und ihr Weichbild,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmuth und ihr Weichbild, En-Gannim und ihr Weichbild, vier Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'Und vom Stamme Ascher Mischal und ihr Weichbild, Abdon und ihr Weichbild,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Chelkath und ihr Weichbild, und Rechob und ihr Weichbild, vier Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'Und vom Stamme Naphthali die Zufluchtsstadt für den Totschläger: Kedesch im Galil und ihr Weichbild, und ChammothDor und ihr Weichbild, und Karthan und ihr Weichbild, drei Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Alle Städte der Gerschumiter nach ihren Familien waren dreizehn Städte und ihre Weichbilder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'Und den Familien der Söhne Meraris, den Leviten, die noch übrig waren vom Stamme Sebulun: Jokneam und ihr Weichbild, Karthah und ihr Weichbild.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimnah und ihr Weichbild, und Nahalal und ihr Weichbild, vier Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'Und vom Stamme Ruben: Bezer und ihr Weichbild, und Jahzah und ihr Weichbild,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemoth und ihr Weichbild, und Mephaath und ihr Weichbild, vier Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'Und vom Stamme Gad die Zufluchtsstadt für den Totschläger: Ramoth in Gilead und ihr Weichbild und Machanajim und ihr Weichbild,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Cheschbon und ihr Weichbild, und Jaser und ihr Weichbild; aller Städte waren es vier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Alle Städte der Söhne Meraris nach ihren Familien, die übrig waren von den Familien der Leviten, und ihr Los waren zwölf Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Alle Städte der Leviten in der Mitte des Eigentums der Söhne Israels waren achtundvierzig Städte und ihre Weichbilder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Dies waren die Städte, jede Stadt und ihr Weichbild rings um sie her. So war es bei allen diesen Städten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Und Jehovah gab Israel das ganze Land, das Er seinen Vätern zu geben geschworen hatte, und sie nahmen es ein und wohnten darin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'Und Jehovah ließ sie ruhen von denen ringsum, nach allem, das Er ihren Vätern geschworen hatte. Und kein Mann stand vor ihnen von allen ihren Feinden. Alle ihre Feinde gab Jehovah in ihre Hand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Und es fiel kein Wort von all dem guten Worte, das Jehovah zu dem Hause Israel geredet hatte, alles kam zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Nun rief Joschua den Rubeniten und den Gaditen und den halben Stamm Menascheh,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'Und sprach zu ihnen: Ihr habt alles gehalten, was euch Mose, der Knecht Jehovahs, geboten, und habt gehört auf meine Stimme in allem, was ich euch gebot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Ihr habt diese vielen Tage eure Brüder nicht verlassen bis auf diesen Tag, und die Verordnung, das Gebot Jehovahs, eures Gottes, gehalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Und nun läßt Jehovah, euer Gott, eure Brüder ruhen, wie Er zu ihnen geredet hatte. So wendet euch denn und ziehet auch nach euren Zelten in das Land eures Eigentums, das euch Mose, der Knecht Jehovahs, jenseits des Jordan gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Nur hütet euch sehr, daß ihr tut das Gebot und das Gesetz, das euch Mose, der Knecht Jehovahs, geboten hat, daß ihr liebet Jehovah, euren Gott, und in all Seinen Wegen wandelt und haltet Seine Gebote, und Ihm dienet von eurem ganzen Herzen und von eurer ganzen Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'Und Joschua segnete sie und entließ sie, und sie zogen nach ihren Zelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Und dem einen halben Stamm Menascheh hatte Mose in Baschan gegeben, und dem anderen halben gab Joschua mit ihren Brüdern diesseits des Jordan dem Meere zu; und als Joschua sie entließ zu ihren Zelten, segnete er sie auch,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'Und sprach zu ihnen und sagte: Kehret zurück zu euren Zelten mit vielem Wohlstand und mit sehr vielen Viehherden, mit Silber und mit Gold, und mit Erz und mit Eisen und mit sehr vielen Gewändern. Teilet die Beute von euren Feinden mit euren Brüdern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'Und sie kehrten zurück, die Söhne Rubens und die Söhne Gads und der halbe Stamm Menascheh, und sie gingen von den Söhnen Israels von Schiloh im Lande Kanaan, daß sie in das Land Gilead in das Land ihres Eigentums zogen, das sie nach dem Befehl Jehovahs durch Moses Hand zum Eigentum hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'Und sie kamen in die Kreise des Jordans, im Lande Kanaan, und die Söhne Rubens und die Söhne Gads und der halbe Stamm Menascheh bauten allda am Jordan einen Altar, einen Altar groß zum Ansehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'Und die Söhne Israels hörten sagen: Siehe, die Söhne Rubens und die Söhne Gads und der halbe Stamm Menascheh haben den Altar gebaut dem Lande Kanaan gegenüber, in den Kreisen des Jordans, jenseits der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'Und die Söhne Israels hörten es, und es versammelte sich die ganze Gemeinde der Söhne Israels nach Schiloh, um wider sie hinaufzuziehen zum Heerzug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'Und die Söhne Israels sandten an die Söhne Rubens und an die Söhne Gads und an den halben Stamm Menascheh nach dem Lande Gilead, Pinechas, den Sohn Eleasars, des Priesters,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'Und zehn Fürsten mit ihm, je einen Fürsten auf das Vaterhaus für alle Stämme Israels, und deren jeder Mann das Haupt des Hauses seiner Väter unter den Tausenden Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'Und sie kamen zu den Söhnen Rubens und zu den Söhnen Gads und zu dem halben Stamm Menascheh, nach dem Lande Gilead und redeten mit ihnen und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Also hat die ganze Gemeinde Jehovahs gesprochen: Was ist diese Untreue, daß ihr dem Gotte Israels untreu geworden seid, daß ihr euch heute von Jehovah zurückgewendet, indem ihr euch einen Altar gebaut habt, so daß ihr euch heute wider Jehovah empört habt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Ist es uns zu wenig an der Missetat von Peor, von der wir uns nicht gereinigt bis auf diesen Tag und ob der die Plage über die Gemeinde Jehovahs kam?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'Und ihr wendet euch heute von Jehovah zurück und empört euch heute wider Jehovah, so daß Er morgen über die ganze Gemeinde Israel Sich entrüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Und wenn ja das Land eures Eigentums unrein ist, so ziehet herüber in das Land des Eigentums Jehovahs, wo die Wohnung Jehovahs wohnt, und habt Eigentum in unserer Mitte, und empört euch nicht wider Jehovah, und empört euch nicht wider uns, daß ihr euch einen Altar baut außer dem Altar unseres Gottes Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Hat nicht Achan, der Sohn Serachs ob dem Bann eine Untreue begangen, und war da nicht über die ganze Gemeinde eine Entrüstung, so daß nicht nur der eine Mann ob seiner Missetat verscheiden mußte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Und die Söhne Rubens und die Söhne Gads und der halbe Stamm Menascheh antworteten und redeten mit den Häuptern der Tausende Israels:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Der Gott der Götter, Jehovah, der Gott der Götter Jehovah, Er weiß es, und Israel, es soll es wissen: Wenn es Empörung und wenn es Untreue gegen Jehovah war - dann mögest Du an diesem Tag uns nicht retten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Daß wir uns einen Altar bauten, um von Jehovah uns zurückzuwenden, und wenn es geschah, um darauf Brandopfer und Speiseopfer aufzuopfern, um darauf Dankopfer zu schlachten, so möge Jehovah es fordern!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Und wenn wir das nicht taten aus Besorgnis für die Sache, daß wir sagten: Morgen könnten eure Söhne sprechen zu unseren Söhnen und sagen: Was geht euch Jehovah, der Gott Israels an?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Und Jehovah hat eine Grenze zwischen uns und euch, ihr Söhne Rubens und Söhne Gads, den Jordan, gesetzt. Ihr habt keinen Teil an Jehovah, und es möchten eure Söhne unsere Söhne abbringen von der Furcht Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Und wir sprachen: Lasset uns doch das für uns tun, daß wir den Altar bauen, nicht zum Brandopfer und nicht zum Schlachtopfer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'Sondern daß er ein Zeuge sei zwischen uns und euch und zwischen unseren Geschlechtern nach uns, auf daß wir den Dienst Jehovahs dienen vor Ihm mit unseren Brandopfern und mit unseren Schlachtopfern und mit unseren Dankopfern, auf daß eure Söhne nicht morgen sagen zu unseren Söhnen: Ihr habt kein Teil an Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Und wir sprachen: Wenn es dennoch geschieht, daß sie so zu uns und zu unseren Geschlechtern morgen sprechen, so werden wir sagen: sehet das Muster von Jehovahs Altar, das unsere Väter gemacht, nicht zum Brandopfer, noch zum Schlachtopfer, sondern daß er ein Zeuge sei zwischen uns und euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Das sei ferne von uns, daß wir uns wider Jehovah empörten und heute von Jehovah uns zurückwendeten und einen Altar erbaueten zum Brandopfer, zum Speiseopfer und zum Schlachtopfer außer dem Altare Jehovahs, unseres Gottes, Der vor Seiner Wohnung ist!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Und es hörte Pinechas, der Priester, und die Fürsten der Gemeinde und die Häupter der Tausende Israels, die mit ihm waren, die Worte, welche die Söhne Rubens und die Söhne Gads und die Söhne Menaschehs redeten; und es war gut in ihren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'Und Pinechas, der Sohn Eleasars, des Priesters, sprach zu den Söhnen Rubens und zu den Söhnen Gads und zu den Söhnen Menaschehs: Heute wissen wir, daß Jehovah in unserer Mitte ist, weil ihr nicht diese Untreue an Jehovah begangen habt. Nun habt ihr die Söhne Israels aus der Hand Jehovahs errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Und Pinechas, der Sohn Eleasars, des Priesters, und die Fürsten kehrten von den Söhnen Rubens und von den Söhnen Gads aus dem Lande Gilead zurück ins Land Kanaan zu den Söhnen Israels und brachten ihnen das Wort zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'Und das Wort war gut in den Augen der Söhne Israels, und die Söhne Israels segneten Gott und sprachen nicht mehr, man müßte wider sie hinaufziehen zum Heerzug und das Land verderben, darin die Söhne Rubens und die Söhne Gads wohnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'Und die Söhne Rubens und die Söhne Gads nannten den Altar: Er ist Zeuge zwischen uns, daß Jehovah ist Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'Und es geschah nach vielen Tagen, nachdem Jehovah Israel von allen seinen Feinden ringsumher zur Ruhe gebracht, und Joschua alt und betagt war,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'Da rief Joschua ganz Israel, seine Ältesten und seine Häupter und seine Richter und seine Vorsteher und sprach zu ihnen: Ich bin alt geworden und betagt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'Und ihr habt gesehen alles, was Jehovah, euer Gott, all diesen Völkerschaften vor euch her getan hat; denn Jehovah, euer Gott, war es, Der für euch stritt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Sehet, ich habe euch diese Völkerschaften, die verbleiben, nach euren Stämmen zum Erbe zufallen lassen, vom Jordan an, und alle Völkerschaften, die ich ausgerottet habe, bis an das große Meer, wo die Sonne untergeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Und Jehovah, euer Gott, Er wird sie vertreiben, vor euch her und sie vor euch austreiben, daß ihr deren Land einnehmet, wie Jehovah, euer Gott, zu euch geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'So seid denn sehr stark und haltet und tut alles, was in Moses Buche des Gesetzes geschrieben ist, daß ihr davon nicht abweichet weder zur Rechten, noch zur Linken;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'Auf daß ihr nicht unter diese Völkerschaften eingeht, die noch bei euch verbleiben, und nicht des Namens ihrer Götter gedenkt, noch bei ihnen schwört und ihnen nicht dient, noch sie anbetet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'Sondern nur Jehovah, eurem Gotte, anhanget, wie ihr getan habt bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Und Jehovah trieb große und mächtige Völkerschaften vor euch aus, und ihr, kein Mann bestand vor euch, bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Ein Mann von euch setzt Tausenden nach; denn Jehovah, euer Gott, ist es, Der für euch streitet, wie Er zu euch geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'So hütet euch sehr für eure Seelen, daß ihr Jehovah, euren Gott, liebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Denn wenn ihr euch wieder zurückwendet und euch hängt an diese übrigen Völkerschaften, die unter euch verblieben, und euch verschwägert mit ihnen und unter sie eingehet und sie unter euch;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'So werdet ihr erfahren, daß Jehovah, euer Gott, diese Völkerschaften nicht ferner austreibt vor euch, daß sie euch zur Schlinge und zum Fallstrick werden und zur Geißel an euren Seiten und zu Stacheln in euren Augen, bis daß ihr umkommt von diesem guten Boden, den euch Jehovah, euer Gott, gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'Und siehe, ich gehe heute den Weg aller Erde; ihr aber sollt wissen von eurem ganzen Herzen und von eurer ganzen Seele, daß kein einziges Wort von all den guten Worten, die Jehovah, euer Gott, über euch geredet hat, weggefallen, daß alle über euch gekommen sind, kein einziges Wort davon ist weggefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Und es wird geschehen, daß, sowie jedes gute Wort, das Jehovah, euer Gott, zu euch geredet hat, über euch kam, so Jehovah über euch jedes böse Wort kommen läßt, bis daß Er euch von diesem guten Boden, den euch Jehovah, euer Gott, gegeben hat, vernichtet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'So ihr den Bund Jehovahs, eures Gottes, überschreitet, den Er euch geboten, und hingeht und anderen Göttern dient und sie anbetet, so wird der Zorn Jehovahs wider euch entbrennen, und ihr werdet eilends umkommen von dem guten Land, das Er euch gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'Und Joschua versammelte alle Stämme Israels nach Schechem und rief den Ältesten Israels, seinen Häuptern und seinen Richtern und seinen Vorstehern, und sie stellten sich vor Gott;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'Und Joschua sprach zu dem ganzen Volke: So sprach Jehovah, der Gott Israels: Jenseits des Flusses wohnten vor Zeiten eure Väter Terach, der Vater Abrahams und der Vater Nachors und dienten anderen Göttern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'Und Ich nahm euren Vater Abraham von jenseits des Flusses und ließ ihn ziehen durch das ganze Land Kanaan und mehrte seinen Samen und gab ihm den Isaak.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'Und dem Isaak gab Ich Jakob und Esau; und dem Esau gab Ich das Gebirge Seir, es erblich zu besitzen, und Jakob und seine Söhne gingen hinab nach Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'Und Ich sandte Mose und Aharon und schlug Ägypten. Wie Ich so getan in seiner Mitte, führte Ich euch danach aus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Und Ich führte eure Väter aus von Ägypten, und ihr kamt an das Meer. Und die Ägypter setzten euren Vätern nach mit Streitwagen und Reitern an das Schilfmeer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'Und sie schrien zu Jehovah, und Er setzte Dunkelheit zwischen euch und die Ägypter, und brachte über sie das Meer herein, daß es sie bedeckte; und eure Augen sahen, was Ich an Ägypten getan, und viele Tage wohntet ihr in der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'Und Ich brachte euch nach dem Lande des Amoriters, der jenseits des Jordan wohnte und sie stritten mit euch. Und Ich gab sie in eure Hand, und ihr nahmt ihr Land ein, und Ich vernichtete sie vor euch her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Und Balak machte sich auf, der Sohn Zippors, Moabs König, und stritt mit Israel, und sandte und rief Bileam, Beors Sohn, daß er euch fluchete;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'Und Ich wollte nicht hören auf Bileam, und er segnete euch, und Ich errettete euch aus seiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'Und ihr setztet über den Jordan und kamt nach Jericho; und es stritten wider euch die Bürger von Jericho, der Amoriter und der Pherisiter und der Kanaaniter und der Chethiter und der Girgaschiter, der Chiviter und der Jebusiter, und Ich gab sie in eure Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'Und Ich sandte die Hornisse vor euch her und Ich trieb sie fort vor Euch, die zwei Könige des Amoriters, nicht mit deinem Schwert und nicht mit deinem Bogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'Und Ich habe euch ein Land gegeben, um das du dich nicht bemüht hast, und die Städte, die ihr nicht gebaut, und ihr wohnt darin; von Weinbergen und Ölgärten, die ihr nicht gepflanzt habt, esset ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Und nun fürchtet Jehovah und dient Ihm untadelig und mit Treue, und wendet euch ab von den Göttern, denen eure Väter jenseits des Flusses und in Ägypten gedient, und dienet Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'Ist es aber böse in euren Augen, daß ihr Jehovah dient, so erwählet heute für euch, wem ihr dienen wollt; ob den Göttern, denen eure Väter, die jenseits des Flusses waren, gedient, oder den Göttern des Amoriters, in dessen Lande ihr wohnt; ich aber und mein Haus, wir werden Jehovah dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Und das Volk antwortete und sprach: Ferne sei von uns, daß wir Jehovah verließen, um anderen Göttern zu dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Ist es ja Jehovah, unser Gott, Der uns heraufgeführt und unsere Väter aus Ägyptenland und aus der Knechte Haus, und Der vor unseren Augen diese großen Zeichen getan und uns behütet hat auf dem ganzen Wege, auf dem wir gegangen, und unter allen Völkern, durch deren Mitte wir gezogen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'Und Jehovah trieb fort vor uns alle die Völker und den Amoriter, der im Lande wohnte. Darum wollen auch wir Jehovah dienen; denn Er ist unser Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Und Joschua sprach zu dem Volk: Ihr werdet Jehovah nicht zu dienen vermögen; denn Er ist ein heiliger Gott, ein eifernder Gott, Der euch eure Übertretungen und Sünden nicht verzeihen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Wenn ihr Jehovah verlasset und Göttern des Auslandes dient, so wird Er Sich zurückwenden und euch Übles tun und euch verzehren, nachdem Er euch Gutes getan hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Und das Volk sprach zu Joschua: Nein, sondern Jehovah wollen wir dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'Und Joschua sprach zum Volk: Ihr selbst seid Zeugen gegen euch, daß ihr Jehovah für euch erwählt habt, Ihm zu dienen. Und sie sprachen: Wir sind Zeugen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Und nun tut weg von euch die Götter des Auslandes, die in eurer Mitte sind, und neigt euer Herz zu Jehovah, dem Gott Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'Und das Volk sprach zu Joschua: Jehovah, unserem Gott, werden wir dienen und auf Seine Stimme hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Und Joschua schloß selbigen Tages für das Volk einen Bund und setzte ihm Satzung und Recht in Schechem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'Und Joschua schrieb diese Worte in das Buch des Gesetzes Gottes und nahm einen großen Stein und richtete ihn allda auf unter der Eiche, die am Heiligtum Jehovahs war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'Und Joschua sprach zu allem Volk: Siehe, dieser Stein soll gegen uns zum Zeugen sein, daß er hörte all die Reden Jehovahs, die Er mit uns geredet hat, und soll zum Zeugen sein wider euch, auf daß ihr euren Gott nicht verleugnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Und Joschua entließ das Volk, jeden Mann in sein Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'Und nach diesen Dingen geschah, daß Joschua, der Sohn Nuns, der Knecht Jehovahs, starb, einhundertzehn Jahre alt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'Und sie begruben ihn in der Grenze seines Erbes in Timnath-Serach, auf dem Gebirge Ephraim, nördlich vom Berge Gaasch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'Und Israel diente Jehovah all die Tage Joschuas und all die Tage der Ältesten, deren Tage verlängert wurden nach Joschua, und die um alle Taten Jehovahs wußten, die Er für Israel tat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'Und die Gebeine Josephs, welche die Söhne Israel aus Ägypten heraufgebracht, begruben sie in Schechem in dem Teile des Feldes, das Jakob von den Söhnen Chamors, des Vaters Schichems, um hundert Kesitah gekauft hatte, und sie waren Josephs Söhnen zum Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Und Eleasar, der Sohn Aharons, starb, und sie begruben ihn in Gibeah des Pinechas, seines Sohnes, das ihm auf dem Gebirge Ephraims gegeben ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'Und es geschah nach dem Tode Joschuas, daß die Söhne Israels Jehovah fragten und sprachen: Wer soll für uns hinaufziehen wider den Kanaaniter, um zu beginnen, mit ihm zu streiten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'Und Jehovah sprach: Judah soll hinaufziehen. Siehe, Ich habe das Land in seine Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Und Judah sprach zu Schimeon, seinem Bruder: Ziehe mit mir hinauf in mein Los und laß uns wider den Kanaaniter streiten, und ich werde auch mit dir gehen in dein Los. Und Schimeon ging mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'Und Judah zog hinauf, und Jehovah gab den Kanaaniter und den Pherisiter in ihre Hand, und sie schlugen ihrer in Besek zehntausend Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'Und sie trafen in Besek auf Adoni-Besek und stritten wider ihn und schlugen den Kanaaniter und den Pherisiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Und Adoni-Besek floh, und sie setzten ihm nach hinter ihm her und griffen ihn und schnitten ihm die Daumen an Händen und Füßen ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Und Adoni-Besek sprach: Siebzig Könige mit abgeschnittenen Daumen an Händen und Füßen lasen unter meinem Tische auf. Wie ich getan, so hat mir Gott vergolten. Und sie brachten ihn herein nach Jerusalem, und er starb allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Und die Söhne Judahs stritten gegen Jerusalem und eroberten es und schlugen es mit der Schärfe des Schwertes und steckten die Stadt mit Feuer an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Und danach gingen die Söhne Judahs hinab, wider den Kanaaniter zu streiten, der auf dem Gebirge und im Mittag und in der Niederung wohnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Und Judah zog gegen den Kanaaniter, der in Chebron wohnte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'Und von da ging er gegen die Einwohner von Debir. Und der Name Debir war vordem Kirjath Sepher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'Und Kaleb sprach: Wer Kirjath Sepher schlägt und es erobert, dem gebe ich Achsah, meine Tochter, zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'Und Othniel eroberte sie, der Sohn des Kenas, des Bruders von Kaleb, der jünger war als er, und er gab ihm Achsah, seine Tochter, zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'Und es geschah, als sie hereinkam, trieb sie ihn an, von ihrem Vater Feld zu erbitten. Und sie ließ sich vom Esel herab und Kaleb sprach zu ihr: Was ist dir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Und sie sprach zu ihm: Gib mir einen Segen, denn du hast mir Mittagsland gegeben, so gib mir auch Wasserquellen. Und Kaleb gab ihr die oberen und die unteren Wasserquellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'Und die Söhne des Keniters, des Schwagers Moses, zogen von der Palmenstadt mit den Söhnen Judahs herauf in die Wüste Judah, die gegen Mittag von Arad ist, und ging hin und wohnte beim Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Und Judah zog mit seinem Bruder Schimeon hin, und sie schlugen den Kanaaniter, der in Zephath wohnte und verbannten dasselbe, und man nannte den Namen der Stadt Chormah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Und Judah eroberte Gazah und ihre Grenze und Aschkelon und ihre Grenze und Ekron und ihre Grenze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'Und Jehovah war mit Judah, daß er das Gebirge einnahm; aber die im Talgrunde wohnten, vermochte er nicht auszutreiben, weil sie eiserne Wagen hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'Und dem Kaleb gaben sie Chebron, wie Mose geredet hatte, und er trieb aus von da die drei Enakssöhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'Und den Jebusiter, der in Jerusalem wohnte, trieben die Söhne Benjamins nicht aus, und der Jebusiter wohnt mit den Söhnen Benjamins in Jerusalem bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Und das Haus Josephs zog auch hinauf wider Beth-El, und Jehovah war mit ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'Und das Haus Josephs spähte Beth-El aus der Name der Stadt war aber vordem Lus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'Und die Hüter sahen einen Mann aus der Stadt herauskommen und sprachen zu ihm: Zeige uns doch den Eingang in die Stadt, und wir wollen Barmherzigkeit an dir tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'Und er zeigte ihnen den Eingang in die Stadt, und sie schlugen die Stadt mit der Schärfe des Schwertes; den Mann aber und seine ganze Familie entließen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Und der Mann ging hin in das Land der Chethiter und baute eine Stadt und nannte ihren Namen Lus. Das ist ihr Name bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Und Menascheh nahm nicht ein Beth-Schean und seine Töchterstädte, noch Thaanach und seine Töchterstädte, noch die Einwohner Dors und ihre Töchterstädte, noch die Einwohner Jibleams und dessen Töchterstädte, noch Megiddos Einwohner und ihre Töchterstädte; und der Kanaaniter wollte in diesem Lande wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Und es geschah, als Israel stark ward, machte es den Kanaaniter zinsbar und trieb ihn nicht ganz aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Und Ephraim trieb den Kanaaniter nicht aus, der in Geser wohnte, und der Kanaaniter wohnte in seiner Mitte in Geser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Sebulun trieb die Einwohner Kitrons, und die in Nahalal wohnten nicht aus, und der Kanaaniter wohnte in seiner Mitte und wurde zinsbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Ascher trieb nicht aus die Einwohner von Akko, noch die Einwohner von Zidon und Achlab und Achsib und Chelbah und Aphik und Rechob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'Und der Ascherite wohnte inmitten der Kanaaniter, die im Lande wohnten; denn er trieb sie nicht aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Naphthali trieb nicht aus die Einwohner von Beth-Schemesch, noch die Einwohner von Beth-Anath und wohnte inmitten der Kanaaniter, die im Lande wohnten; und die Einwohner von Beth-Schemesch und Beth-Anath waren ihnen zinsbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Und die Amoriter drängten die Söhne Dans auf das Gebirge und gestatteten ihnen nicht, in den Talgrund herabzukommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'Und der Amoriter wollte auf dem Berg Cheres in Aijalon und in Schaalbim wohnen; und die Hand des Hauses Josephs ward schwer, so daß sie zinsbar wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'Und die Grenze des Amoriters war Maaleh Akrabbim von der Felsklippe an und aufwärts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Und ein Engel Jehovahs stieg von Gilgal herauf nach Bochim und sprach: Ich habe euch aus Ägypten heraufgeführt und euch in das Land gebracht, das Ich euren Vätern geschworen hatte und gesprochen: Ich will Meinen Bund mit euch nicht zunichte machen ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'Und ihr sollt keinen Bund schließen mit den Einwohnern dieses Landes, ihre Altäre sollt ihr niederreißen; aber ihr habt nicht auf Meine Stimme gehört. Warum habt ihr das getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Und Ich habe auch gesprochen: Ich will sie nicht vor euch forttreiben, und sie sollen euch zu Stacheln und ihre Götter zum Fallstrick werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'Und es geschah, da der Engel Jehovahs diese Worte zu allen Söhnen Israels redete, hob das Volk seine Stimme auf und sie weinten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'Und sie nannten den Namen dieses Ortes Bochim und opferten allda dem Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Und Joschua entließ das Volk, und die Söhne Israels gingen, jeglicher Mann nach seinem Erbe, um das Land einzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'Und das Volk diente Jehovah alle die Tage Joschuas und all die Tage der Ältesten, die ihre Tage verlängerten nach Joschua, welche alle die großen Taten Jehovahs gesehen, die Er an Israel getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'Und Joschua, der Sohn Nuns, der Knecht Jehovahs, starb in einem Alter von hundertzehn Jahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'Und sie begruben ihn in der Grenze seines Erbes in Thimnath Cheres auf dem Gebirge Ephraim, nördlich vom Berge Gaasch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'Und auch jenes ganze Geschlecht wurde zu seinen Vätern versammelt, und es erstand nach ihnen ein anderes Geschlecht, das Jehovah nicht kannte, noch auch die Taten, die Er an Israel getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'Und die Söhne Israel taten, was böse war in den Augen Jehovahs, und dienten den Baalim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'Und verließen Jehovah, den Gott ihrer Väter, Der sie aus Ägyptenland ausgeführt, und gingen anderen Göttern nach, von den Göttern der Völker, die rings um sie waren, und beteten sie an und reizten Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'Und sie verließen Jehovah und dienten Baal und Aschtharoth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Und es entbrannte der Zorn Jehovahs wider Israel, und Er gab sie in die Hand von Plünderern, und sie plünderten sie, und Er verkaufte sie in die Hand ihrer Feinde ringsum. Und sie vermochten nicht mehr vor ihren Feinden zu bestehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Überall, wo sie auszogen, war die Hand Jehovahs wider sie zum Bösen, wie Jehovah geredet und wie Jehovah ihnen geschworen hatte. Und sie wurden sehr bedrängt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'Und Jehovah ließ Richter aufstehen, und sie retteten sie aus der Hand ihrer Plünderer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Aber auf die Richter hörten sie nicht, sondern buhlten anderen Göttern nach und beteten sie an, und eilends wichen sie ab von dem Wege, den ihre Väter gegangen waren, daß sie auf die Gebote Jehovahs hörten. Sie taten nicht also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'Und wenn Jehovah für sie Richter aufstehen ließ, so war Jehovah mit dem Richter, und Er rettete sie aus der Hand ihrer Feinde alle die Tage des Richters; denn es jammerte Jehovah ob ihrem Stöhnen ob denen, so sie bedrückten und zwangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Und es geschah, wenn der Richter starb, so wandten sie sich zurück und taten noch Verderblicheres, als ihre Väter, daß sie anderen Göttern nachgingen, ihnen zu dienen und sie anzubeten, und ließen nichts fallen von ihren Handlungen und von ihrem harten Wege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Und es entbrannte der Zorn Jehovahs wider Israel und Er sprach: Weil diese Völkerschaft Meinen Bund überschritten, den Ich ihren Vätern geboten, und nicht auf Meine Stimme gehört haben:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'So werde Ich keinen Mann mehr vor ihnen austreiben von den Völkerschaften, die Joschua gelassen, da er starb,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'Auf daß Ich Israel durch sie versuche, ob sie den Weg Jehovahs halten, um darauf zu wandeln, wie ihre Väter daran hielten, oder nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Darum ließ Jehovah diese Völkerschaften bleiben, daß Er sie nicht eilends austrieb und nicht in Joschuas Hand gab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Und das sind die Völkerschaften, die Jehovah ließ bleiben, daß Er an ihnen Israel versuchete, alle, die nichts wußten von all den Kriegen Kanaans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'Nur damit die Geschlechter der Söhne Israel es wüßten, um sie streiten zu lehren, nur sie, die vordem davon nichts wußten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'Die fünf Fürsten der Philister und alle Kanaaniter und die Zidonier und die Chiviter, die da wohnen auf dem Berge Libanon, vom Berge Baal Chermon, bis man kommt gen Chamath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Und sie waren dazu da, Israel an ihnen zu versuchen, auf daß man wisse, ob sie auf die Gebote Jehovahs, die Er ihren Vätern durch Moses Hand geboten hatte, hören wollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'Und die Söhne Israels wohnten inmitten der Kanaaniter, der Chethiter und Amoriter und Pherisiter und Chiviter und Jebusiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'Und sie nahmen sich ihre Töchter zu Weibern und gaben ihre Töchter ihren Söhnen und dienten ihren Göttern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'Und die Söhne Israels taten Böses in den Augen Jehovahs und vergaßen Jehovahs, ihres Gottes, und dienten den Baalim und den Ascheren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Und es entbrannte der Zorn Jehovahs gegen Israel, und Er verkaufte sie in die Hand des Kuschan Rischathajim, König von Aram der beiden Flüsse, und die Söhne Israels dienten dem Kuschan Rischathajim acht Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'Und die Söhne Israels schrien zu Jehovah, und Jehovah ließ den Söhnen Israels einen Retter erstehen, und er rettete sie: Othniel, den Sohn des Kenas, des Bruders von Kaleb, jünger als er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'Und der Geist Jehovahs war auf ihm, und er richtete Israel und zog zum Streite aus, und Jehovah gab Kuschan Rischathajim, den König Arams, in seine Hand; und seine Hand ward stark über Kuschan Rischathajim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'Und das Land war stille vierzig Jahre, und Othniel, des Kenas Sohn, starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'Und die Söhne Israels taten wiederum Böses in den Augen Jehovahs, und Jehovah stärkte Eglon, Moabs König, wider Israel, darum, daß sie taten, was böse war in den Augen Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'Und er sammelte wider dasselbe die Söhne Ammons und Amaleks und zog hin und schlug Israel und sie nahmen ein die Palmenstadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'Und die Söhne Israels dienten Eglon, Moabs König, achtzehn Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Und die Söhne Israels schrien zu Jehovah, und Jehovah ließ ihnen erstehen einen Retter, den Ehud, Geras Sohn, den Benjaminiter, einen Mann, dessen rechte Hand lahm war; und die Söhne Israels sandten durch seine Hand an Eglon, Moabs König, ein Geschenk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Und Ehud machte sich ein Schwert, das zwei Schneiden hatte, eine Elle lang, und gürtete es unter seine Obergewänder auf seine rechte Hüfte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'Und er brachte das Geschenk dar dem Eglon, dem König von Moab. Eglon aber war ein sehr feister Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'Und es geschah, da er das Darbringen des Geschenkes vollendet, da entließ er das Volk, welches das Geschenk getragen hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Und er kehrte von den Schnitzbildern, die bei Gilgal sind, zurück und sprach: Ich habe ein geheimes Wort an dich, König. Und er gebot Stille, und alle gingen von ihm hinaus, die bei ihm gestanden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'Und Ehud kam zu ihm hinein. Und er saß in dem Söller seines Kühlungsgemachs allein. Und Ehud sprach: Ich habe ein Wort Gottes an dich. Und er stand auf von seinem Thron.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Und Ehud reckte seine linke Hand aus und nahm das Schwert von seiner rechten Hüfte und stieß es ihm in den Leib,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'Und auch das Heft ging nach der Klinge hinein, und das Fett schloß sich hinter der Klinge, denn er zog das Schwert nicht aus seinem Leib, und es ging durch den Mastdarm hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Und Ehud ging auf den Vorsaal hinaus und verschloß die Türen des Söllers hinter sich und riegelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Und er ging hinaus und seine Diener kamen und sahen, und siehe, die Türen des Söllers waren verriegelt, und sie sprachen: Er bedeckt nur seine Füße in der Kammer des Kühlungsgemachs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'Und sie warteten, bis sie sich schämten, und siehe, niemand öffnete die Türen des Söllers, und sie nahmen den Schlüssel und öffneten, und siehe, ihr Herr war zur Erde gefallen, tot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Und Ehud entrann, während sie zauderten, und kam an den Schnitzbildern vorüber und entrann nach Seirath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'Und wie er dorthin kam, stieß er auf dem Gebirge Ephraim in die Posaune. Und die Söhne Israels kamen hinter ihm vom Berge herab und er vor ihnen her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'Und er sprach zu ihnen: Setzet mir nach; denn Jehovah hat eure Feinde, die Moabiter, in eure Hand gegeben, und sie kamen hinter ihm herab und gewannen die Furten des Jordans, Moab zu, und gestatteten niemand, überzusetzen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'Und sie schlugen Moab zu selbiger Zeit bei zehntausend Mann, alle feiste und alle tapfere Männer, und kein Mann entrann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Und Moab wurde am selbigen Tage unter die Hand Israels niedergebeugt, und das Land war stille achtzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'Und nach ihm war Schamgar, der Sohn des Anath; und er schlug den Philistern sechshundert Mann mit einem Ochsenstecken, und auch er rettete Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'Und die Söhne Israels taten wieder Böses in den Augen Jehovahs, und Ehud war tot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'Und Jehovah verkaufte sie in die Hand Jabins, eines Königs von Kanaan, der in Chazor regierte. Und der Oberste seines Heeres war Sisera und wohnte in Charoschet Gojim');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'Und die Söhne Israels schrien zu Jehovah; denn er hatte neunhundert eiserne Streitwagen und bedrückte stark die Söhne Israels zwanzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'Und das Weib Deborah, das Weib des Lappidoth, war eine Prophetin, sie richtete Israel um diese Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'Und sie saß unter der Palme Deborahs zwischen Ramah und Bethel auf dem Gebirge Ephraim. Die Söhne Israels kamen zu ihr hinauf zum Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Und sie sandte hin und rief Barak, Abinoams Sohn, aus Kedesch Naphthali und sprach zu ihm: Hat nicht Jehovah, der Gott Israels, dir geboten: Gehe hin und zieh hinaus auf den Berg Thabor und nimm mit dir zehntausend Mann von den Söhnen Naphthalis und von den Söhnen Sebuluns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Und ich locke heraus wider dich an den Bach Kischon Sisera, den Obersten des Heeres Jabins, mit seinem Streitwagen und seiner Menge, und gebe ihn in deine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'Und Barak sprach zu ihr: Wenn du mit mir gehst, so gehe ich; und gehst du nicht mit mir, so gehe ich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Und sie antwortete. Wohl will ich mit dir gehen, allein es wird dir keinen Ruhm bringen auf dem Wege, den du gehst, denn in der Hand eines Weibes wird Jehovah den Sisera verkaufen. Und Deborah machte sich auf und ging mit Barak gen Kedesch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Und Barak berief Sebulun und Naphthali nach Kedesch, und zehntausend Mann zogen zu Fuß hinauf zu ihm, und Deborah zog mit ihm hinauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Und Cheber, der Keniter, hatte sich von Kajin, von den Söhnen Chobabs, des Schwagers von Mose, getrennt und sein Zelt bei Elon in Zaannajim, das bei Kedesch ist, aufgeschlagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'Und man sagte Sisera an, daß Barak, der Sohn Abinoams, auf den Berg Thabor hinaufgezogen wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'Und Sisera berief alle seine Streitwagen, neunhundert eiserne Streitwagen, und all sein Volk, das mit ihm war, von Charoscheth Gojim, an den Bach Kischon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Und Deborah sprach zu Barak: Mache dich auf, denn das ist der Tag, an dem Jehovah den Sisera in deine Hand gegeben hat. Geht nicht Jehovah aus vor dir? Und Barak ging hinab von dem Berge Thabor und zehntausend Mann hinter ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'Und Jehovah brachte den Sisera und all seine Streitwagen und all sein Lager mit der Schärfe des Schwertes vor Barak her in Verwirrung und Sisera kam vom Streitwagen herab und floh zu Fuß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Und Barak setzte hinter den Streitwagen und dem Heere nach bis Charoscheth Gojim; und das ganze Heer Siseras fiel mit der Schärfe des Schwertes, daß nicht einer verblieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Und Sisera floh zu Fuß zu dem Zelte von Jael, Chebers, des Keniten Weib; denn es war Frieden zwischen dem König Jabin von Chazor und des Keniten Chebers Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'Und Jael kam heraus, dem Sisera entgegen und sprach zu ihm: Kehre bei mir ein, Herr, kehre bei mir ein, fürchte dich nicht. Und er kehrte zu ihr ein in das Zelt, und sie bedeckte ihn mit einer Decke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'Und er sprach zu ihr: Gib mir doch ein wenig Wasser zu trinken; denn mich dürstet. Und sie öffnete einen Milchschlauch und gab ihm zu trinken und bedeckte ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'Und er sprach zu ihr: Stehe am Eingang des Zeltes, und es sei, so ein Mann kommt und dich fragt und sagt: Ist ein Mann hier? so sprich: Nein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Und Jael, Chebers Weib, nahm den Zeltpflock und nahm den Hammer in ihre Hand und ging sachte zu ihm hinein und schlug den Pflock in seine Schläfe, und er drang in die Erde hinein. Er aber lag im festen Schlaf, denn er war müde, und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'Und siehe, Barak setzte dem Sisera nach, und Jael kam heraus, ihm entgegen, und sprach zu ihm: Komm, und ich zeige dir den Mann, den du suchst. Und er kam zu ihr hinein, und siehe, Sisera war gefallen, tot, und der Pflock in seiner Schläfe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Und Gott beugte an selbigem Tage Jabin, den König Kanaans, nieder vor den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'Und die Hand der Söhne Israels war immer härter über Jabin, dem Könige Kanaans, bis sie Jabin, den König von Kanaan, ausgerottet hatten..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'Und es sang Deborah und Barak, der Sohn Abinoams, am selben Tag und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Weil sie mit Hingebung sich hingaben in Israel, weil das Volk willig war, segnet Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Höret ihr Könige, nehmet zu Ohren, ihr Beherrscher! Ich, ich will Jehovah singen, ich will Psalmen singen Jehovah, dem Gott Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'Da du, Jehovah, ausgingst aus Seir, da Du aus dem Felde Edoms schrittest einher, erbebte die Erde, auch die Himmel troffen, auch die dichten Wolken troffen Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Berge zerflossen vor Jehovah, dieser Sinai vor Jehovah, dem Gott Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'In den Tagen Schamgars, des Sohnes Anaths, in den Tagen Jaels hörten die Pfade auf; die auf Steigen gingen, gingen auf krummen Pfaden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Die Landstädte hörten in Israel auf, sie hörten auf, bis daß ich aufstand, ich Deborah, bis daß ich aufstand, eine Mutter in Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Er wählet neue Götter. Da war Streit an den Toren. Man sieht nicht Schild noch Speer bei den Vierzigtausenden in Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Mein Herz ist für die Gesetzgeber Israels, die willig sich zeigten in dem Volk. Segnet Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Ihr, die ihr reitet auf weißen Eselinnen, die ihr sitzet auf Prachtteppichen, die ihr auf dem Weg geht. Sinnet nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Mit der Stimme der Pfeilschützen zwischen den Schöpferinnen. Laßt erzählen sie die Gerechtigkeiten Jehovahs, die Gerechtigkeiten Seiner Landstädte in Israel. Dann lasset sie, Jehovahs Volk, hinabgehen zu den Toren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Wach auf, wach auf, du Deborah! Wach auf, wach auf! Sprich den Gesang! Mache auf dich, Barak, nimm deine Gefangenschaft gefangen, Sohn Abinoams.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Nun wird der Rest beherrschen die Stattlichen, o Volk; Jehovah wird für mich beherrschen die Mächtigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Von Ephraim, was auf dem Amalek wurzelt, hinter dir her Benjamin mit deinen Völkern. Von Machir kommen die Gesetzgeber herab, und von Sebulun, die des Schreibers Rute führen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'Und Oberste in Issaschar sind mit Deborah. Und wie Barak ist Issaschar. Auf seinen Füßen wird er in den Talgrund gesandt. In den Reihen Rubens sind große Bedenken des Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Warum bliebst du sitzen zwischen zwei Bürden, zu hören das Flöten bei den Herden. In den Reihen Rubens sind große Ergründungen des Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead wohnt jenseits des Jordan. Und Dan, weshalb bangt dir vor den Schiffen? Ascher sitzt am Gestade der Meere und wohnt an seinen Buchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Sebulun ist ein Volk, das sein Leben bloßlegt dem Tod, und Naphthali auf den Höhen des Feldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Könige kamen, sie stritten. Da stritten die Könige Kanaans in Thaanach, an Megiddos Wassern. Keinen Gewinn von Silber nahmen sie davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Vom Himmel stritten sie, die Sterne stritten von ihren Bahnen wider Sisera.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Weg schwemmte sie der Bach Kischon. Ein Bach der Vorzeit ist der Bach Kischon. Tritt, meine Seele, auf die Stärke!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Da stampften die Hufe der Rosse von dem Jagen, von dem Jagen seiner Gewaltigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Verfluchet Meros! spricht Jehovahs Engel. Verfluchet seine Einwohner; denn sie kamen nicht Jehovah beizustehen, beizustehen Jehovah wider die Mächtigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Gesegnet sei vor den Weibern Jael, das Weib des Cheber, des Keniten; vor den Weibern im Zelte sei sie gesegnet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Er erbat sich Wasser, sie gab Milch. In der Schale des Stattlichen brachte sie Rahm dar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Sie reckte ihre Hand aus nach dem Pflocke und ihre Rechte nach der Arbeiter Hammer. Und sie zerhämmerte Sisera, zerschlug sein Haupt; und sie zerschmetterte und durchbohrte seine Schläfe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Zwischen ihren Füßen krümmt er sich, er fällt, er liegt. Zwischen ihren Füßen krümmt er sich, er fällt. Wie er sich krümmt, da fällt er zerscheitert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Durch das Fenster schaute aus, durch das Gitter jammerte die Mutter Siseras. Warum verzieht sein Streitwagen, daß er komme? Warum zögern seiner Streitwagen Rollgänge?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Die weisen von ihren Edelfrauen antworten ihr; auch sie erwidert selber sich Rede:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Ob sie nicht Beute finden und verteilen? Eine Dirne, zwei Dirnen auf jedes Mannes Haupt? Beute an bunten Gewändern für Sisera; Beute an bunten gewirkten Gewändern. Bunte, doppelt gewirkte Zeuge um den Hals der Beute?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Also müssen umkommen alle deine Feinde, Jehovah! Und die Ihn lieben, wie die Sonne ausgeht in ihrer Macht! - Und das Land war stille vierzig Jahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'Und die Söhne Israels taten Böses in den Augen Jehovahs, und Jehovah gab sie in die Hand Midjans sieben Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'Und die Hand Midjans ward stark über Israel. Da machten sich die Söhne Israels vor Midjan Klüfte an den Bergen und Höhlen und Bergfesten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'Und es geschah, wenn Israel säte, da zog herauf Midjan und Amalek und die Söhne des Ostens, und kamen herauf über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'Und sie lagerten sich wider sie und verdarben das Gewächs des Landes, bis man gen Gazah kommt, und ließen in Israel keine Lebensmittel übrig, weder Kleinvieh, noch Ochse, noch Esel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Denn sie zogen herauf mit ihren Viehherden und ihren Zelten. Wie die Heuschrecken an Menge kamen sie, und sie und ihre Kamele waren ohne Zahl, und sie kamen in das Land, es zu verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'Und Israel verarmte sehr vor Midjan, und die Söhne Israels schrien zu Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'Und es geschah, da die Söhne Israels schrien zu Jehovah um Midjans willen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'Da sandte Jehovah einen Mann, einen Propheten, zu den Söhnen Israels, und er sprach zu ihnen: Also spricht Jehovah, der Gott Israels: Ich habe euch aus Ägypten heraufgeführt und euch ausgeführt aus dem Hause der Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'Und habe euch errettet aus der Ägypter Hand und aus der Hand aller, die euch unterdrückt und habe sie vor euch ausgetrieben, und euch ihr Land gegeben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'Und habe zu euch gesprochen: Ich, Jehovah, bin euer Gott. Fürchtet nicht die Götter der Amoriter, in deren Land ihr wohnt; aber ihr habt nicht auf Meine Stimme gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'Und es kam ein Engel Jehovahs und setzte Sich unter die Eiche zu Ophrah, die des Joasch, des Abiesriters war; und sein Sohn Gideon, der klopfte Weizen aus in der Kelterkufe, auf daß er es flüchtete vor Midjan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'Und es erschien ihm der Engel Jehovahs und sprach zu ihm: Jehovah sei mit dir, du tapferer Held!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Und Gideon sprach zu Ihm: Ach, Mein Herr, und ist Jehovah mit uns, warum trifft uns alles dies? Und wo sind alle Seine Wunder, von denen unsere Väter uns erzählen und sagen: Hat uns Jehovah nicht aus Ägypten heraufgebracht? Jetzt aber hat Jehovah uns fahren lassen und uns in die Hand Midjans gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'Und Jehovah wandte Sich ihm zu und sprach: Gehe mit dieser deiner Kraft und rette Israel aus der Hand Midjans. Habe Ich dich nicht gesandt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'Und er aber sprach zu Ihm: Ach, Herr, womit soll ich Israel retten? Siehe, mein Tausend ist das ärmste in Menascheh; und ich bin der jüngste in meines Vaters Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'Und Jehovah sprach zu ihm: Weil Ich werde mit dir sein; und du sollst Midjan schlagen wie einen Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'Und er sprach zu Ihm: Finde ich doch Gnade in Deinen Augen, daß Du mir ein Zeichen tust, daß Du es bist, Der mit mir redet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Weiche doch nicht von hinnen, bis ich zu Dir kommen und mein Speiseopfer herausbringe und vor dir niederlege. Und Er sprach: Ich will bleiben, bis du zurückkommst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'Und Gideon ging hinein und bereitete ein Ziegenböcklein und von einem Epha Mehls ungesäuerte Kuchen; das Fleisch tat er in einen Korb, und die Brühe tat er in einen Topf, und brachte es zu Ihm heraus unter die Eiche und reichte es her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Und der Engel Gottes sprach zu ihm: Nimm das Fleisch und die ungesäuerten Kuchen und lege sie nieder auf den Fels da und gieße die Brühe aus; und er tat also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Und der Engel Jehovahs reckte das Ende des Steckens aus, der in Seiner Hand war, und berührte das Fleisch und die ungesäuerten Kuchen, und von dem Felsen stieg ein Feuer auf und fraß auf das Fleisch und die ungesäuerten Kuchen; und der Engel Jehovahs ging fort aus seinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'Und Gideon sah, daß Er der Engel Jehovahs war, und Gideon sprach: Ach, Herr, Jehovah, denn nun habe ich den Engel Jehovahs von Angesicht zu Angesicht gesehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'Und Jehovah sprach zu ihm: Friede sei mit dir! Fürchte dich nicht. Du sollst nicht sterben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Und Gideon baute allda einen Altar dem Jehovah und nannte ihn: Jehovah Schalom. Bis auf diesen Tag ist er noch in Ophra des Abiesriten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'Und es geschah in der selbigen Nacht, daß Jehovah zu ihm sprach: Nimm den Farren, den Ochsen deines Vaters, und den zweiten Farren von sieben Jahren, und reiße den Altar des Baal ein, der deinem Vater gehört, und die Aschere, die dabei steht, haue um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'Und baue Jehovah, deinem Gott, einen Altar auf der Spitze dieser Feste nach der Ordnung, und nimm den zweiten Farren und opfere ihn auf als Brandopfer mit dem Holze der Aschere, die du umhauen wirst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Und Gideon nahm zehn Männer von seinen Knechten und tat, wie Jehovah zu ihm geredet hatte. Und es geschah, da er sich fürchtete vor dem Hause seines Vaters und den Männern der Stadt, daß er es bei Tag täte, so tat er es bei der Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Und die Männer der Stadt standen früh am Morgen auf und siehe, da war der Baalsaltar niedergerissen und die Aschere, die dabei war, umgehauen, und der zweite Farre als Brandopfer auf dem gebauten Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'Und sie sagten, der Mann zu seinen Genossen: Wer hat das getan? Und sie fragten nach und forschten und sie sagten: Gideon, des Joasch Sohn, hat es getan!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Und die Männer der Stadt sprachen zu Joasch: Bringe deinen Sohn heraus, daß er sterbe; denn er hat den Altar des Baal niedergerissen und die Aschere, die dabei stand, umgehauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Joasch aber sprach zu allen, die bei ihm standen: Wollt ihr für den Baal hadern? Wollt ihr ihm helfen? Wer für ihn hadert, soll diesen Morgen des Todes sterben. Ist er ein Gott, so hadere er selber mit ihm, weil er seinen Altar niedergerissen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Und an dem Tage hieß man ihn Jerubbaal, indem man sprach: Es hadere Baal mit ihm, weil er seinen Altar niedergerissen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Und ganz Midjan und Amalek und die Söhne des Ostens sammelten sich allzumal und setzten über und lagerten sich im Talgrunde Jesreel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'Und der Geist Gottes zog Gideon an, und er stieß in die Posaune und Abieser ward gerufen, ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'Und er sandte Boten in ganz Menascheh, und auch dieses ward gerufen ihm nach; und nach Ascher und Sebulun und Naphthali sandte er Boten, und sie zogen herauf, ihnen entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'Und Gideon sprach zu Gott: Wenn Du Israel durch meine Hand retten willst, wie Du gesagt hast;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'Siehe, so lege ich die Wollenschur in die Tenne. Wenn Tau auf der Schur allein und die ganze Erde trocken sein wird, so weiß ich, daß Du Israel durch meine Hand retten willst, wie Du gesagt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'Und es geschah also. Und am morgenden Tage stand er früh auf und drückte die Schur zusammen, und drückte den Tau aus von der Schur, eine Schale voll Wassers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'Und Gideon sprach zu Gott: Dein Zorn wird nicht entbrennen wider mich, daß ich nur diesmal rede. Ich will nur noch diesmal versuchen mit der Schur: Laß es doch auf der Schur allein trocken sein, und auf der ganzen Erde sei Tau.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'Und Gott tat also in selbiger Nacht: Trockenheit war auf der Schur allein, und auf der ganzen Erde war Tau.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Und Jerubbaal, das ist Gideon, stand früh auf und alles Volk, das mit ihm war, und sie lagerten an der Quelle Charod, und das Lager Midjans war ihm gegen Mitternacht am Hügel Moreh im Talgrunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Und Jehovah sprach zu Gideon: Zu viel ist das Volk mit dir, als daß Ich Midjan in ihre Hand geben könnte, auf daß Israel nicht prahle über Mich und spreche: Meine Hand hat mich gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Und rufe nun aus vor den Ohren des Volkes und sage: Wer sich fürchtet und erzittert, der kehre zurück und hebe sich hinweg vom Gebirge Gilead. Und es kehrten vom Volke zurück zweiundzwanzigtausend, und zehntausend verblieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'Und Jehovah sprach zu Gideon: Noch ist des Volkes zu viel. Bringe sie hinab an das Wasser. Daselbst will Ich sie läutern; und soll sein, von wem Ich dir sagen werde, dieser soll mit dir ziehen, der soll mit dir ziehen; und jeder, von dem Ich dir sage, dieser soll nicht mit dir ziehen, der ziehe nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'Und er brachte das Volk hinab an das Wasser, und Jehovah sprach zu Gideon: Jeder, der vom Wasser mit der Zunge leckt, wie der Hund leckt, den stelle besonders, und auch jeden, der auf die Knie niederkauert, um zu trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'Und es war die Zahl derer, die mit der Hand zum Munde geleckt hatten, dreihundert Mann; und alles übrige Volk kauerte auf die Knie nieder, um Wasser zu trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'Und Jehovah sprach zu Gideon: Mit den dreihundert Mann, die geleckt haben, rette Ich euch und gebe Midjan in deine Hand; und all das Volk laß jeden Mann an seinen Ort gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'Und sie nahmen Zehrung für das Volk in ihre Hand, und ihre Posaunen, und alle Männer Israels entließ er, jeden Mann in sein Zelt, und die dreihundert Mann hielt er zurück. Und das Lager Midjans war unter ihnen im Talgrunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'Und es geschah in selbiger Nacht, daß Jehovah zu ihm sprach: Mache dich auf und gehe hinab in das Lager, denn Ich habe es in deine Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Fürchtest du dich aber, hinabzugehen, so gehe du und dein Junge Purah hinab zum Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'Und du wirst hören, was sie reden, und danach werden deine Hände stark werden, daß du in das Lager hinabgehst. Und er ging hinab, er und Purah, sein Junge, an das Ende der Kampfgerüsteten im Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'Und Midjan und Amalek und alle Söhne des Ostens lagen im Talgrunde, wie die Heuschrecke an Menge, und ihrer Kamele war keine Zahl, wie der Sand am Strande des Meeres an Menge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'Und Gideon kam und siehe, ein Mann erzählte seinem Genossen einen Traum und sprach: Siehe, ich träumte einen Traum, und siehe, ein geröstet Gerstenbrot rollte in das Lager Midjans und kam an das Zelt und schlug dasselbe, daß es fiel, und kehrte es zuoberst, und das Zelt war gefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'Und sein Genosse antwortete und sprach: Dies ist nichts anderes, als das Schwert Gideons, des Sohnes von Joasch, des Mannes von Israel. Gott hat Midjan und das ganze Lager in seine Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'Und es geschah, als Gideon den Traum erzählen und deuten hörte, so betete er an und kehrte in Israels Lager zurück und sprach. Machet euch auf, denn Jehovah hat das Lager Midjans in eure Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Und er teilte die dreihundert Mann in drei Haufen und gab ihnen allen Posaunen in die Hand und leere Krüge und Fackeln inmitten der Krüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'Und er sprach zu ihnen: Von mir sehet es ab und tuet also; und siehe, ich komme dahin an das Ende des Lagers, und es geschehe, daß wie ich tue, also sollt ihr tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Und stoße ich in die Posaune, ich und alle, die mit mir sind, so stoßet auch ihr rings um das ganze Lager in die Posaunen und sprechet: Für Jehovah und für Gideon!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Und es kam Gideon und die hundert Mann, die mit ihm waren, am Anfang der mittleren Nachtwache an das Ende des Lagers, da sie eben die Hut aufgestellt hatten, und stießen in die Posaunen und zerschmissen die Krüge in ihrer Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'Und es bliesen alle drei Haufen mit den Posaunen und zerbrachen die Krüge und hielten die Fackeln in der linken Hand und die Posaunen zum Blasen in der rechten Hand und riefen: Schwert für Jehovah und für Gideon!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'Und sie standen, jeder Mann an seiner Stelle, rings um das Lager; und das ganze Lager rannte, und sie schrien und flohen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'Und die dreihundert bliesen die Posaunen, und Jehovah setzte im Lager das Schwert eines jeden Mannes wider seine Genossen und wider das ganze Lager; und das Lager floh bis Beth-Schittah, Zererath zu, bis an den Rand von Abel-Mecholah bei Tabbath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'Und die Männer Israels wurden aufgerufen aus Naphthali und aus Ascher und aus ganz Menascheh, und sie setzten hinter Midjan nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'Und Gideon sandte Boten in das ganze Gebirge Ephraim und sprach: Gehet hinab, Midjan entgegen, und gewinnet die Wasser vor ihnen bis Beth-Barah und den Jordan; und jeder Mann in Ephraim wurde aufgerufen, und sie gewannen die Wasser bis Beth-Barah und den Jordan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'Und sie fingen zwei Oberste Midjans, Oreb und Seeb, und erwürgten Oreb auf Zur-Oreb und Seeb erwürgten sie in Jekeb-Seeb und sie setzten Midjan nach, und brachten die Köpfe Orebs und Seebs zu Gideon, jenseits des Jordan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'Und die Männer von Ephraim sprachen zu ihm: Warum hast du uns das getan, daß du uns nicht riefst, als du zogst wider Midjan zu streiten? Und sie haderten gewaltig mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'Und er sprach zu ihnen: Was habe ich nun getan wie ihr? Ist nicht die Nachlese Ephraims besser, als die Weinlese Abiesers?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'In eure Hand hat Gott die Obersten Midjans gegeben, den Oreb und den Seeb! Und was konnte ich tun, wie ihr? Da ließ ihr Geist von ihm ab, da er solches Wort redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'Und Gideon kam an den Jordan und setzte über, er und die dreihundert Mann, die mit ihm waren, matt, und doch setzten sie nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'Und er sprach zu den Männern von Sukkoth: Gebt doch dem Volke, das mir zu Fuße folgt, einige Laibe Brot, denn sie sind matt, und ich setze hinter dem Sebach und Zalmunna, Midjans Königen, nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'Und die Obersten von Sukkoth sprachen: Hast du die Faust Sebachs und Zalmunnas schon in deiner Hand, daß wir deinem Heere Brot geben sollen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Und Gideon sprach: Deshalb will ich, wenn Jehovah Sebach und Zalmunna in meine Hand gibt, dann euer Fleisch mit Dornen der Wüste und mit Stechdisteln dreschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'Und von dannen zog er hinauf gen Penuel und sprach zu ihnen ebenso. Und die Männer von Penuel antworteten ihm, wie die Männer von Sukkoth geantwortet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'Und er sprach auch zu den Männern von Penuel und sagte: Komme ich mit Frieden zurück, so will ich diesen Turm niederreißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Und Sebach und Zalmunna waren in Karkor und ihr Lager mit ihnen bei fünfzehntausend Mann, alle, die noch übrig waren vom ganzen Lager der Söhne des Ostens; der Gefallenen aber waren hundertzwanzigtausend Männer, die das Schwert zogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'Und Gideon zog den Weg der Zeltbewohner hinauf auf der Ostseite von Nobach und Jogbehah und schlug das Lager. Das Lager war sicher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'Und Sebach und Zalmunna flohen, und er setzte hinter ihnen nach und fing die zwei Könige Midjans, Sebach und Zalmunna, und scheuchte ihr ganzes Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'Und Gideon, der Sohn des Joasch, kehrte, bevor die Sonne aufging, vom Streite zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'Und er fing einen Jungen der Männer von Sukkoth auf und befragte ihn. Und der schrieb ihm die Obersten von Sukkoth und ihre Ältesten auf, siebenundsiebzig Männer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'Und er kam zu den Männern von Sukkoth und sprach. Siehe, hier sind Sebach und Zalmunna, wegen derer ihr mich geschmäht und gesagt habt: Sind die Fäuste Sebachs und Zalmunnas schon in deiner Hand, daß wir deinen Männern, die matt sind, Brot geben sollen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'Und er nahm die Ältesten der Stadt und Dornen der Wüste und Stechdisteln und ließ die Männer von Sukkoth sie fühlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Und den Turm von Penuel riß er nieder und erwürgte die Männer der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'Und zu Sebach und Zalmunna sprach er: Wie waren die Männer, die ihr auf Thabor erwürgtet? Und sie sprachen: Wie du, so waren sie, ein jeder von Gestalt wie Königssöhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'Und er sprach. Es waren meine Brüder, meiner Mutter Söhne. Beim Leben Jehovahs: Wenn ihr sie hättet leben lassen, so wollte ich euch nicht erwürgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'Und er sprach zu Jether, seinem Erstgeborenen: Stehe auf und erwürge sie. Der Junge aber zog sein Schwert nicht, denn er fürchtete sich, weil er noch ein Junge war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Und Sebach und Zalmunna sprachen: Stehe du auf und stoß auf uns, denn wie der Mann ist, ist auch seine Macht. Und Gideon stand auf und erwürgte Sebach und Zalmunna nun und nahm dann die Halbmonde, die an den Hälsen ihrer Kamele waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Und die Männer Israels sprachen zu Gideon: Herrsche du über uns, du und auch dein Sohn und auch deines Sohnes Sohn; denn du hast uns aus der Hand Midjans gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Und Gideon sprach zu ihnen: Ich will nicht herrschen über euch, und auch mein Sohn soll nicht herrschen über euch. Jehovah soll über euch herrschen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Und Gideon sprach zu ihnen: Eine Bitte will ich mir von euch erbitten: So gebt mir ein jeder Mann den Ring von seiner Beute; denn sie hatten goldene Ringe, weil sie Ischmaeliten waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'Und sie sprachen: Wir wollen sie geben. Und sie breiteten ein Gewand aus, und sie warfen darein, jeder Mann den Ring von seiner Beute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'Und das Gewicht der goldenen Ringe, die er sich erbeten, war tausendsiebenhundert Goldschekel außer den Halbmonden und Ohrgehängen und Purpurkleidern, die Midjans Könige anhatten, und außer dem Halsgehänge am Halse der Kamele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'Und Gideon machte es zu einem Ephod, und stellte es auf in seiner Stadt Ophrah; und ganz Israel buhlte ihm nach daselbst; und es ward Gideon und seinem Hause zum Fallstricke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'Midjan aber beugte sich vor den Söhnen Israels und sie erhoben ihr Haupt nicht mehr, und das Land war stille vierzig Jahre in den Tagen Gideons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'Und Jerubbaal, der Sohn des Joasch, ging hin und wohnte in seinem Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Und Gideon hatte siebzig Söhne, die aus seiner Hüfte hervorgingen; denn er hatte viele Weiber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'Und sein Kebsweib, das er in Schechem hatte, gebar ihm auch einen Sohn, dem er den Namen Abimelech gab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'Gideon, der Sohn des Joasch, starb in gutem Greisenalter und ward begraben im Grab des Joasch, seines Vaters, in Ophrah der Abieseriter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Und es geschah, als Gideon gestorben war, da kehrten die Söhne Israels zurück und buhlten den Baalim nach, und setzten Baal-Berith zu ihrem Gotte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'Und die Söhne Israels gedachten nicht an Jehovah, ihren Gott, Der sie aus der Hand aller ihrer Feinde ringsum errettet hatte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'Und taten keine Barmherzigkeit dem Hause des Jerubbaal-Gideon nach all dem Guten, das er an Israel getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Und Abimelech, Jerubbaals Sohn, ging nach Schechem zu den Brüdern seiner Mutter und redete zu ihnen und zu der ganzen Familie des Hauses des Vaters seiner Mutter und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Redet doch vor den Ohren aller Bürger Schechems: Was ist besser für euch, daß über euch herrschen siebzig Männer, alle Söhne Jerubbaals, oder daß ein Mann über euch herrscht; und gedenket, daß ich bin euer Gebein und euer Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'Und die Brüder seiner Mutter redeten über ihn vor den Ohren aller Bürger Schechems alle diese Worte; und ihr Herz neigte sich dem Abimelech nach; denn sie sagten: Er ist unser Bruder;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'Und gaben ihm siebzig Silberlinge aus dem Hause des Baal-Berith; und Abimelech dingte damit lose leichtfertige Männer, die ihm nachfolgten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'Und er kam in das Haus seines Vaters nach Ophrath und erwürgte seine Brüder, die siebzig Mann, Söhne Jerubbaals, auf einem Stein; aber Jotham, Jerubbaals jüngster Sohn blieb übrig, denn er hatte sich versteckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'Und es sammelten sich alle Bürger Schechems und das ganze Haus Millo und gingen und machten Abimelech zum König bei der Eiche der Denksäule in Schechem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Und man sagte dem Jotham an, und er ging hin und stand auf der Spitze des Berges Gerissim und erhob seine Stimme und rief und sprach zu ihnen: Höret auf mich, Bürger von Schechem, auf daß Gott auf euch höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Die Bäume gingen einen König über sich zu salben und sprachen zum Ölbaum: Sei König über uns!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'Und der Ölbaum sprach zu ihnen: Soll ich aufgeben meine Fettigkeit, die an mir Gott und die Menschen verherrlichen, und hingehen, um über den Bäumen zu schwanken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'Und die Bäume sprachen zum Feigenbaum: Gehe du, und sei König über uns!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'Und der Feigenbaum sprach zu ihnen: Soll ich aufgeben meine Süßigkeit und meinen guten Ertrag, um hinzugehen und über den Bäumen zu schwanken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Und die Bäume sprachen zu dem Weinstock: Gehe du, und sei König über uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Und der Weinstock sprach zu ihnen: Soll ich aufgeben meinen Most, der Gott und die Menschen fröhlich macht, und gehen, um über den Bäumen zu schwanken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Und alle Bäume sprachen zum Dornbusch: Gehe du, und sei König über uns!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'Und der Dornbusch sprach zu den Bäumen: Wenn ihr in Wahrheit mich über euch zum König salbet, so kommt, verlaßt euch auf meinen Schatten; und wo nicht, so gehe Feuer von dem Dornbusch aus und verzehre die Zedern Libanons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Und nun, wenn ihr in Treue und Tadellosigkeit gehandelt, daß ihr den Abimelech zum Könige gemacht, und wenn ihr an dem Jerubbaal und an seinem Hause Gutes habt getan, und wenn ihr nach seiner Hände Wohltun ihm getan,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, 'Dafür, daß mein Vater für euch gestritten und sein Leben von sich geworfen und euch errettet hat aus Midjans Hand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'Und ihr seid heute aufgestanden wider meines Vaters Haus, und habt seine Söhne, siebzig Männer, auf einem Stein erwürgt, und machet seiner Magd Sohn, Abimelech, zum König über Schechems Bürger, weil er euer Bruder ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'Und wenn ihr mit Treue und Tadellosigkeit an Jerubbaal und an seinem Haus heute habt gehandelt, so seid fröhlich über Abimelech und auch er sei fröhlich über euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Wo aber nicht, so gehe Feuer von Abimelech aus und fresse Schechems Bürger und Millos Haus! Und es gehe Feuer aus von den Bürgern Schechems und von Millos Haus und fresse den Abimelech.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Und Jotham floh und entwich und ging nach Beer und wohnte da wegen seines Bruders Abimelech.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Und Abimelech war drei Jahre der Oberste über Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'Und Gott sandte einen bösen Geist zwischen Abimelech und Schechems Bürger, daß Schechems Bürger gegen Abimelech treulos handelten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'Auf daß die Gewalttat an den siebzig Söhnen Jerubbaals über sie komme, und man ihr Blut lege auf Abimelech, ihren Bruder, der sie erwürgte, und auf Schechems Bürger, die seine Hände stärkten, seine Brüder zu erwürgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'Und die Bürger Schechems legten wider ihn einen Hinterhalt auf die Spitzen der Berge und plünderten jeden aus, der bei ihnen auf dem Wege vorüberzog, und es ward Abimelech angesagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Und es kam Gaal, Ebeds Sohn, und seine Brüder und zogen hinüber nach Schechem, und die Bürger Schechems vertrauten auf ihn;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'Und sie gingen hinaus auf das Feld, lasen ihre Weinberge ab, und kelterten, und machten Loblieder und gingen hinein in das Haus ihres Gottes und aßen und tranken und fluchten auf Abimelech.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'Und Gaal, Ebeds Sohn, sprach: Wer ist Abimelech und wer Schechem, daß wir ihm dienen? Ist er nicht Jerubbaals Sohn und Sebul sein Amtsmann? Dienet den Männern von Chamor, Schechems Vater; aber warum sollen wir ihm dienen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'O, wer gäbe doch dies Volk in meine Hand, dann wollte ich Abimelech wegtun! Und zu Abimelech sprach er: Mehre dein Heer und zieh aus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Und Sebul, der Oberste der Stadt, hörte die Worte Gaals, des Sohnes Ebeds, und sein Zorn entbrannte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'Und er sandte Boten an Abimelech insgeheim und sagte: Siehe, Gaal, der Sohn Ebeds, und seine Brüder sind nach Schechem gekommen, und siehe, sie drängen die Stadt wider dich auf!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Und nun mache dich auf bei der Nacht, du und das Volk, das bei dir ist, und lege einen Hinterhalt im Felde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Und es soll sein, am Morgen, wenn die Sonne aufgeht, stehe früh auf und rücke wider die Stadt und siehe, er und das Volk, das mit ihm ist, gehen hinaus gegen dich, und dann tue mit ihnen, wie es deine Hand findet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'Und Abimelech machte sich auf in der Nacht und alles Volk, das mit ihm war, und sie legten sich wider Schechem mit vier Haufen in Hinterhalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'Und Gaal, der Sohn Ebeds, kam heraus und stand am Eingang des Tores der Stadt; und Abimelech und das Volk mit ihm machte sich auf aus dem Hinterhalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'Und Gaal sah das Volk und sprach zu Sebul: Siehe, Volk kommt von den Spitzen der Berge herab. Und Sebul sagte zu ihm: Den Schatten der Berge siehst du für Männer an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'Und Gaal redete wiederum und sprach: Siehe, von der Anhöhe des Landes dort kommt Volk herab, und ein Haufe kommt von dem Weg der Eiche der Wolkendeuter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Und Sebul sprach zu ihm: Wo ist denn dein Maul, daß du sprachst: Wer ist der Abimelech, daß wir ihm dienen sollen? Ist dies nicht das Volk, das du verschmäht hast? Gehe nun aus und streite mit ihm!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'Und Gaal zog aus vor den Bürgern von Schechem und stritt wider Abimelech.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Und Abimelech setzte ihm nach, und er floh vor ihm; und es fielen viele Erschlagene bis zum Eingang des Tores.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'Und Abimelech blieb in Arumah; und Sebul vertrieb Gaal und seine Brüder, da sie nicht in Schechem wohnen durften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'Und es geschah am morgenden Tage, daß das Volk hinausging ins Feld, und es ward dem Abimelech angesagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'Und er nahm das Volk und teilte es in drei Haufen und legte sich auf dem Felde in Hinterhalt. Und er sah, und siehe, das Volk ging aus von der Stadt. Und er machte sich auf wider sie und schlug sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Und Abimelech und die Haufen, die mit ihm waren, rückten aus und standen am Eingang des Tores der Stadt, und zwei Haufen rückten aus wider alle, die auf dem Felde waren und schlugen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'Den ganzen Tag stritt Abimelech wider die Stadt, und er gewann die Stadt, und er erwürgte das Volk darin und riß die Stadt nieder und besäte sie mit Salz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Und alle Bürger in dem Turme von Schechem hörten es, und sie gingen in die Feste des Hauses des Gottes Berith.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'Und dem Abimelech wurde angesagt, daß alle Bürger des Turmes Schechems zusammengekommen seien;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'Und Abimelech zog hinauf auf den Berg Zalmon, er und alles Volk, das mit ihm war; und Abimelech nahm die Axt in seine Hand und hieb einen Baumast ab und hob ihn auf und legte ihn auf seine Schulter und sprach zu dem Volke, das mit ihm war: Was ihr mich habt tun sehen, das tut eilends wie ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'Und es hieb auch alles Volk, jeder Mann seinen Ast ab, und sie gingen hinter Abimelech her und legten selben an die Feste und zündeten über ihnen ein Feuer an, und es starben auch alle Männer des Turmes Schechems, über tausend, Mann und Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Und Abimelech ging nach Thebez und lagerte wider Thebez und eroberte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Und es war ein starker Turm in der Mitte der Stadt, und dahin flohen alle Männer und Weiber und alle Bürger der Stadt, und schlossen hinter sich zu und stiegen auf das Dach des Turmes hinauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'Und Abimelech kam bis an den Turm und stritt wider ihn, und er trat hinzu bis an den Eingang des Turmes, daß er ihn mit Feuer verbrennete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Und ein Weib warf dem Abimelech einen oberen Mühlstein auf den Kopf und zerbrach ihm den Schädel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Und er rief eilends den Jungen, der ihm die Waffen trug, und sprach zu ihm: Zieh dein Schwert heraus und töte mich, daß sie nicht von mir sagen: Ein Weib hat ihn erwürgt. Und der Junge durchstach ihn, und er starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Und die Männer Israels sahen, daß Abimelech tot war, und sie gingen jeder an seinen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'So ließ zurückkommen Gott dem Abimelech das Böse, das er an seinem Vater tat, daß er seine siebzig Brüder erwürgte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'Und Gott ließ alles Böse der Männer von Schechem zurückkommen auf ihr Haupt. Und der Fluch Jothams, des Sohnes Jerubbaals, kam über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'Und nach Abimelech stand auf, Israel zu retten, Thola, der Sohn Puahs, der Sohn Dodos, ein Mann aus Issaschar; und er wohnte in Schamir auf dem Gebirge Ephraim;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'Und er richtete Israel dreiundzwanzig Jahre; und er starb und ward in Schamir begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'Und nach ihm stand auf Jair, der Gileaditer, und richtete Israel zweiundzwanzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'Und er hatte dreißig Söhne, die auf drei-ßig Eselsfüllen ritten und dreißig Städte hatten, die auf diesen Tag Jairdörfer heißen, und sind im Lande Gilead.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'Und Jair starb und ward in Kamon begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'Und die Söhne Israels taten wider, was böse war in den Augen Jehovahs, und dienten den Baalim und Aschtaroth und den Göttern Arams und den Göttern Zidons und den Göttern Moabs und den Göttern der Philister, und verließen Jehovah und dienten Ihm nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Und es entbrannte der Zorn Jehovahs wider Israel, und Er verkaufte sie in die Hand der Philister und in die Hand der Söhne Ammons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'Und sie zerschmetterten und zerschlugen die Söhne Israels in dem Jahre, achtzehn Jahre, alle Söhne Israel, jenseits des Jordan im Land des Amoriters, das ist Gilead.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Und die Söhne Ammons setzten über den Jordan, um auch wider Judah, Benjamin und das Haus Ephraims zu streiten, und Israel war sehr bedrängt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'Und die Söhne Israels schrien zu Jehovah und sprachen: Wir haben gesündigt gegen Dich und daß wir unseren Gott verlassen und den Baalim gedient haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'Und Jehovah sprach zu den Söhnen Israels: Habe Ich euch nicht von den Ägyptern und von den Amoritern und von den Söhnen Ammons und von den Philistern,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Und von den Zidoniern und von dem Amalek und Maon, die euch unterdrückten, und ihr zu Mir schriet, aus ihrer Hand gerettet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'Und ihr habt Mich verlassen und anderen Göttern gedient, darum will Ich nicht fortfahren, euch zu helfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Gehet hin und schreit zu den Göttern, die ihr euch erwählt habt; sie sollen zur Zeit der Drangsal euch helfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Und die Söhne Israels sprachen zu Jehovah: Wir haben gesündigt. Tue Du an uns, wie es gut in Deinen Augen ist, nur errette uns doch diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'Und sie taten weg die Götter des Auslands aus ihrer Mitte und dienten Jehovah; und Seine Seele ward ungeduldig über dem Mühsal Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'Und es wurden zusammengerufen die Söhne Ammons, und sie lagerten sich in Gilead, und die Söhne Israels versammelten sich und lagerten in Mizpah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'Und das Volk, die Obersten Gileads, sprachen einer zum Genossen: Wer ist der Mann, der anfängt zu streiten wider die Söhne Ammons, der soll das Haupt sein über alle, die in Gilead wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Und Jephthach, der Gileaditer, war ein tapferer Held, und er war der Sohn eines Weibes, einer Buhlerin, und Gilead hatte Jephthach gezeugt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Und das Weib Gileads gebar ihm Söhne, und die Söhne des Weibes wurden groß und vertrieben den Jephthach und sprachen zu ihm: Du sollst nicht erben im Hause unseres Vaters; denn du bist der Sohn eines anderen Weibes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Und Jephthach entwich vor seinen Brüdern und wohnte im Lande Tob; und es sammelten sich zu Jephthach lose Männer und zogen mit ihm aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Und es geschah nach einigen Tagen, daß die Söhne Ammons mit Israel stritten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Und es geschah, als die Söhne Ammons mit Israel im Streit waren, da gingen die Ältesten Gileads hin, den Jephthach aus dem Lande Tob zu holen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'Und sie sprachen zu Jephthach: Komm und sei unser Anführer, und wir wollen wider die Söhne Ammons streiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Und Jephthach sprach zu den Ältesten Gileads: Habt ihr nicht mich gehaßt und mich aus meines Vaters Haus vertrieben? Und warum kommt ihr jetzt zu mir, da ihr in Bedrängnis seid?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'Und die Ältesten Gileads sprachen zu Jephthach: Darum sind wir jetzt zu dir zurückgekommen, daß du sollst mit uns gehen und streiten wider Ammons Söhne und unser Haupt sein, aller, die in Gilead wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Und Jephthach sprach zu den Ältesten Gileads: Holet ihr mich zurück, auf daß ich streite wider die Söhne Ammons, und wollet ihr, so Jehovah sie vor mir dahin gibt, daß ich euer Haupt sein soll?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Und die Ältesten Gileads sprachen zu Jephthach: Jehovah höre zwischen uns, wenn wir nicht also tun nach deinem Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Und Jephthach ging mit den Ältesten Gileads und das Volk setzte ihn zum Haupt und Anführer über sich, und Jephthach redete alle seine Worte vor Jehovah in Mizpah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Und Jephthach sandte Boten an den König der Söhne Ammons, ihm zu sagen: Was habe ich mit dir zu schaffen, daß du gekommen bist, wider mein Land zu streiten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Und der König der Söhne Ammons sprach zu den Boten Jephthachs: Darum, daß Israel mein Land weggenommen hat vom Arnon und bis zum Jabbok und bis an den Jordan, als es aus Ägypten heraufzog; und nun gib es zurück in Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Und Jephthach sandte abermals Boten an den König der Söhne Ammons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'Und sprach zu ihm: So spricht Jephthach: Israel hat nicht genommen das Land Moab und das Land der Söhne Ammons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'Denn als sie aus Ägypten heraufzogen, da ging Israel in der Wüste bis an das Schilfmeer und kam gen Kadesch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'Und Israel sandte Boten an den König von Edom, ihm zu sagen: Laß mich doch durch dein Land hindurchziehen; aber der König von Edom hörte nicht darauf, und auch an den König von Moab sandte es, aber er wollte nicht. Und Israel blieb in Kadesch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Und es zog in der Wüste und umging das Land Edom und das Land Moab und kam von Aufgang der Sonne an das Land Moab und sie lagerten jenseits des Arnon und kamen nicht in Moabs Grenze; denn der Arnon war Moabs Grenze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'Und Israel sandte Boten an Sichon, der Amoriter König, König zu Cheschbon, und Israel sprach zu ihm: Laß uns doch durch dein Land ziehen bis an meinen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'Und Sichon traute Israel nicht, daß es durch seine Grenze hindurchzöge und Sichon versammelte all sein Volk und sie lagerten in Jahzah, und er stritt mit Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Und Jehovah, der Gott Israels, gab Sichon und all sein Volk in die Hand Israels, und sie schlugen sie. Und Israel nahm ein das ganze Land des Amoriters, der in selbigem Land wohnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'Und sie nahmen die ganze Grenze des Amoriters ein, vom Arnon und bis an den Jabbok und von der Wüste bis an den Jordan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Und nun hat Jehovah, der Gott Israels, den Amoriter vor seinem Volk Israel ausgetrieben, und du willst es einnehmen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Willst du nicht, was dir dein Gott Kemosch zum Erbsitze gibt, einnehmen? und alles, was Jehovah, unser Gott, vor uns zum Erbsitze gibt, das nehmen wir ein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Und nun, bist du denn wohl besser als Balak, Zippors Sohn, der König Moabs? Hat er je mit Israel gehadert. Hat er je gestritten wider sie?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Während Israel in Cheschbon und seinen Töchterstädten und in Aroer und seinen Töchterstädten und in allen Städten, die an Arnons Ufer liegen, dreihundert Jahre wohnte; warum habt ihr es nicht in dieser Zeit an euch entrissen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Und ich habe nichts an dir gesündigt und du tust böse an mir, daß du wider mich streitest? Jehovah, der Richter, soll heute richten zwischen den Söhnen Israels und Ammons Söhnen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Aber der König der Söhne Ammons hörte nicht auf Jephthachs Worte, die er an ihn sandte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Und der Geist Jehovahs war auf Jephthach, und er zog hindurch durch Gilead und Menascheh, und zog hindurch bis gen Mizpeh in Gilead, und von Mizpeh in Gelead zog er hindurch wider die Söhne Ammons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'Und Jephthach gelobte Jehovah ein Gelübde und sprach: Wenn Du die Söhne Ammons in meine Hand gibst,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'So soll geschehen, daß das Herauskommende, das herauskommt aus meines Hauses Türen mir entgegen, wenn ich in Frieden zurückkehre von den Söhnen Ammons, das sei Jehovahs, und ich will es Ihm als Brandopfer aufopfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Und Jephthach zog hin zu den Söhnen Ammons und stritt wider sie, und Jehovah gab sie in seine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'Und er schlug sie von Aroer und bis du nach Minnith kommst, zwanzig Städte, und bis Abel-Keramim in einer sehr großen Schlacht. Und die Söhne Ammons wurden niedergebeugt vor den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Und Jephthach kam gen Mizpah zu seinem Hause, und siehe: Seine Tochter kam heraus, ihm entgegen, mit Pauken und mit Reigen; und sie war seine einzige. Außer ihr hatte er weder Sohn noch Tochter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'Und es geschah, da er sie sah, zerriß er seine Kleider und sprach: Ach, meine Tochter, du beugst mich und zerrüttest mich. Und ich habe meinen Mund aufgetan dem Jehovah und kann nicht zurückgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Und sie sprach zu ihm: Mein Vater, du hast deinen Mund aufgetan dem Jehovah, tue mir, wie es aus deinem Munde ausging, nachdem Jehovah dir an deinen Feinden, den Söhnen Ammons, Rache hat bereitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Und sie sprach zu ihrem Vater: Das eine wollest du mir tun: Zwei Monde lasse von mir ab, und ich will hingehen und niedersteigen auf die Berge, und ich will meine Jungfrauschaft beweinen, ich und meine Genossinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'Und er sprach: Gehe hin! Und entließ sie auf zwei Monde. Und sie ging hin, sie und ihre Genossinnen, und beweinte auf den Bergen ihre Jungfrauschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'Und es geschah am Ende zweier Monde, daß sie zurückkehrte zu ihrem Vater, und er tat an ihr nach seinem Gelübde, das er gelobt. Und sie erkannte nie einen Mann. Und es ward eine Satzung in Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'Von Jahr zu Jahr gehen die Töchter Israels hin, zu trauern um die Tochter Jephthachs, des Gileaditen, vier Tage im Jahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'Und Ephraims Mannen wurden zusammengerufen und zogen hin nach Mitternacht, und sie sprachen zu Jephthach: Warum bist du hingezogen, zu streiten wider die Söhne Ammons, und hast uns nicht gerufen, daß wir mit dir zögen? Dein Haus verbrennen wir über dir mit Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Und Jephthach sprach zu ihnen: Ein Mann des Haders war ich sehr, ich und mein Volk und die Söhne Ammons, und ich schrie zu euch, aber ihr halfet mir nicht aus ihrer Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'Und ich sah, daß du uns nicht halfest, und ich nahm meine Seele in meine Hand und zog hinüber wider die Söhne Ammons, und Jehovah gab sie in meine Hand, und warum zieht ihr nun heute herauf, wider mich zu streiten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'Und Jephthach brachte alle Männer Gileads zusammen und sie stritten mit Ephraim, und die Männer Gileads schlugen Ephraim; weil sie sagten: Entkommene Ephraims seid ihr, Gilead ist inmitten Ephraims und inmitten Menaschehs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'Und Gilead besetzte die Furten des Jordan vor Ephraim; und es geschah, wenn die Entkommenen Ephraims sprachen: Laßt mich hinüber, so sprachen zu ihm die Männer von Gilead: Bist du ein Ephraimite? Und wenn er sagte: Nein,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'Da sagten sie zu ihm: Sprich doch: Schibboleth. Sprach er aber Sibboleth und konnte es nicht richtig reden, so ergriffen sie ihn und schlachteten ihn an den Furten des Jordans. Und es fielen zu selbiger Zeit von Ephraim zweiundvierzigtausend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Und Jephthach richtete Israel sechs Jahre. Und Jephthach, der Gileaditer, starb und ward begraben in den Städten Gileads.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Und nach ihm richtete Israel Ibzan von Bethlechem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Und er hatte dreißig Söhne; und dreißig Töchter entließ er hinaus und dreißig Töchter brachte er seinen Söhnen von draußen, und richtete Israel sieben Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'Und Ibzan starb und ward in Bethlechem begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'Und nach ihm richtete Israel Elon, der Sebuluniter, und er richtete Israel zehn Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'Und Elon, der Sebuluniter, starb und ward begraben in Aijalon, im Lande Sebulun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'Und nach ihm richtete Israel Abdon, Hillels Sohn, der Pirathoniter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Und er hatte vierzig Söhne und dreißig Söhne seiner Töchter, die auf siebzig Eselfüllen ritten, und richtete Israel acht Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'Und Abdon, der Sohn Hillels, der Pirathoniter, starb und ward begraben in Pirathon, im Lande Ephraim, auf dem Gebirge des Amalekiters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'Und die Söhne Israels taten wiederum Böses in den Augen Jehovahs, und Jehovah gab sie in die Hand der Philister vierzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Und es war ein Mann aus Zorah, aus der Familie der Daniten, und sein Name war Manoach; und sein Weib war unfruchtbar und gebar nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'Und es erschien dem Weibe der Engel Jehovahs und sprach zu ihr: Siehe doch, du bist unfruchtbar und gebierst nicht, aber du wirst empfangen und einen Sohn gebären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'So hüte dich nun, daß du nicht Wein noch starkes Getränk trinkst, noch irgend etwas Unreines issest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Denn siehe, du wirst empfangen und einen Sohn gebären. Und es soll ihm kein Schermesser auf das Haupt kommen, denn ein Nasiräer Gottes soll der Junge sein von Mutterleib an, und er soll anfangen, Israel aus der Hand der Philister zu retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'Und das Weib kam und sprach zu ihrem Manne und sagte: Ein Mann Gottes kam zu mir und sein Ansehen war wie das Ansehen eines Engels Gottes, sehr furchtbar, und ich fragte ihn nicht, woher er wäre und seinen Namen hat er mir nicht angesagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'Und er sprach zu mir: Siehe, du wirst empfangen und einen Sohn gebären. So trinke nun keinen Wein, noch starkes Getränk und iß nicht irgend etwa Unreines, denn der Junge soll ein Nasiräer Gottes sein von Mutterleib an bis zum Tage seines Todes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Und Manoach flehte zu Jehovah und sprach: Laß doch, o Herr, den Mann Gottes, den Du gesendet hast, abermals zu uns kommen, daß Er uns unterweise, was wir zu tun haben mit dem Jungen, der geboren werden soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'Und Gott hörte auf die Stimme Manoachs, und der Engel Gottes kam abermals zu dem Weibe und sie saß auf dem Felde, und Manoach, ihr Mann, war nicht bei ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Und das Weib eilte und lief, und sagte es ihrem Manne an und sprach zu ihm: Siehe, der Mann ist mir erschienen, der an jenem Tage zu mir gekommen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'Und Manoach machte sich auf und ging seinem Weibe nach und kam zu dem Manne und sprach zu ihm: Bist du der Mann, der mit dem Weibe geredet hat? Und Er sprach: Ich bin es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'Und Manoach sprach: Wenn nun kommen wird, was Du geredet hast, was soll dann des Jungen Weise sein und sein Tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'Und der Engel Jehovahs sprach zu Manoach: Vor allem, was Ich dem Weibe gesagt, soll sie sich hüten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Von allem, das vom Weinstock ausgeht, soll sie nichts essen, und Wein und starkes Getränk soll sie nicht trinken und nichts Unreines essen. Alles, was Ich ihr gebot, das soll sie halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'Und Manoach sprach zu dem Engel Jehovahs: Laß Dich doch von uns zurückhalten, daß wir vor Dir ein Ziegenböcklein bereiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Und der Engel Jehovahs sprach zu Manoach: Wenn du mich auch zurückhieltest, so äße Ich doch nicht von deinem Brote; aber wenn du Jehovah ein Brandopfer machen willst, so opfere es dem Jehovah auf; denn Manoach wußte nicht, daß es der Engel Jehovahs war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'Und Manoach sprach zu dem Engel Jehovahs: Was ist Dein Name? daß wir Dich ehren, wenn Dein Wort kommen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Und der Engel Jehovahs sprach zu ihm: Warum fragst du nach Meinem Namen? Und er ist: Wunderbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Und Manoach nahm denn das Ziegenböcklein und das Speiseopfer und opferte es dem Jehovah auf auf dem Felsen. Und Er tat eine Wundertat und Manoach und sein Weib sahen es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Und es geschah, als die Flammen vom Altar zum Himmel aufstieg, da stieg der Engel Jehovahs in der Flamme des Altars auf, und Manoach und sein Weib sahen es und fielen auf ihr Gesicht zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'Und der Engel Jehovahs erschien dem Manoach und seinem Weibe nicht wieder. Da wußte Manoach, daß es der Engel Jehovahs war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'Und Manoach sprach zu seinem Weibe: Wir müssen des Todes sterben; denn wir haben Gott gesehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Und sein Weib sprach zu ihm: Wenn Jehovah Lust hätte, uns zu töten, so hätte Er nicht aus unserer Hand das Brandopfer und das Speiseopfer angenommen, und hätte nicht uns solches alles sehen lassen, und in dieser Zeit uns nicht solches hören lassen, wie dies.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'Und das Weib gebar einen Sohn und nannte seinen Namen Simson; und der Junge ward groß, und Jehovah segnete ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'Und der Geist Jehovahs fing an, ihn zu treiben in Machaneh-Dan, zwischen Zorah und Eschtaol.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'Und Simson ging hinab nach Thimnatha und sah in Thimnatha ein Weib unter den Töchtern der Philister;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'Und er kam herauf und sagte es seinem Vater und seiner Mutter an und sprach: Ich habe ein Weib gesehen in Thimnatha von den Töchtern der Philister, und nun nehmt sie mir zum Weibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Und sein Vater und seine Mutter sprachen zu ihm: Ist denn unter den Töchtern deiner Brüder und unter all meinem Volk kein Weib, daß du hingehst und nimmst ein Weib von den unbeschnittenen Philistern? Und Simson sprach zu seinem Vater: Die nimm mir, denn sie ist recht im meinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Und sein Vater und seine Mutter wußten nicht, daß es von Jehovah war, daß er Gelegenheit suchte gegen die Philister. Und zu der Zeit herrschten die Philister über Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Und Simson ging mit seinem Vater und seiner Mutter hinab nach Thimnatha; und sie kamen an die Weinberge von Thimnatha, und siehe, ein junger Löwe brüllte ihm entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'Und der Geist Jehovahs fuhr in ihn und er zerriß denselben, wie man ein Böcklein zerreißt, und doch hatte er gar nichts in seiner Hand. Und er sagte seinem Vater und seiner Mutter nicht an, was er getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'Und er ging hinab und redete zu dem Weibe und sie war recht in Simsons Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'Und er kam zurück nach einigen Tagen, um sie zu nehmen; und er lenkte ab, um nach dem Aas des Löwen zu sehen, und siehe, ein Schwarm Bienen war in dem Leib des Löwen, und Honig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'Und er nahm diesen heraus in seine Hände, und ging und aß davon, während er hinging, und ging zu seinem Vater und seiner Mutter, und er gab ihnen, und sie aßen; er sagte ihnen aber nicht, daß er aus des Löwen Leib den Honig herausgenommen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'Und sein Vater ging hinab zu dem Weibe, und Simson machte daselbst ein Gastmahl, denn so machten es die Jünglinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'Und es geschah, da sie ihn sahen, nahmen sie dreißig Genossen, die bei ihm sein sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'Und Simson sprach zu ihnen: Ich will euch ein Rätsel raten lassen, und wenn ihr es mir während der sieben Tage des Gastmahls ansagt und ausfindet, so gebe ich euch dreißig Hemden und dreißig Feierkleider.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Und könnt ihr es mir nicht ansagen, so gebt ihr mir dreißig Hemden und dreißig Feierkleider. Und sie sagten zu ihm: Laß raten dein Rätsel, daß wir es hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'Und er sprach zu ihnen: Von dem Esser ging aus Speise, und Süßes ging aus von dem Starken. Und sie konnten in drei Tagen das Rätsel nicht ansagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'Und es geschah am siebenten Tage, daß sie sprachen zu Simsons Weib: Berede deinen Mann, daß er uns das Rätsel ansage; sonst verbrennen wir dich und deines Vaters Haus mit Feuer. Habt ihr uns hierher gerufen, um uns arm zu machen oder nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Und das Weib Simsons weinte bei ihm und sprach: Fürwahr, du hassest mich und hast mich nicht lieb. Du läßt die Söhne meines Volkes das Rätsel raten, und mir sagst du es nicht an. Und er sprach zu ihr: Siehe, meinem Vater und meiner Mutter habe ich es nicht angesagt. Und dir sollt ich es ansagen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'Und sie weinte bei ihm sieben Tage, solange sie das Gastmahl hatten. Und es geschah, am siebenten Tage sagte er es ihr an, weil sie ihn beengte; und sie sagte das Rätsel den Söhnen ihres Volkes an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Und die Männer der Stadt sprachen zu ihm am siebenten Tage, bevor die Sonne unterging: Was ist süßer als Honig und was stärker als der Löwe? Er aber sprach zu ihnen: Hättet ihr nicht mit meiner Färse gepflügt, ihr hättet mein Rätsel nicht ausgefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'Und der Geist Jehovahs fuhr in ihn, und er ging hinab nach Aschkelon, und erschlug ihrer dreißig Männer, und er nahm, was er ihnen auszog und gab die Feierkleider denen, die das Rätsel angesagt. Und sein Zorn entbrannte, und er ging hinauf in seines Vaters Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Und Simsons Weib ward seinem Freunde, der sein Genosse war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Und es geschah nach etlichen Tagen, in den Tagen der Weizenernte, daß Simson sein Weib besuchte mit einem Ziegenböcklein, und er sprach: Ich will zu meinem Weibe hineingehen in die Kammer. Und ihr Vater ließ ihn nicht hineingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'Und ihr Vater sprach: Ich sprach: Du hassest sie, und gab sie denn deinem Freunde. Ist ihre jüngere Schwester nicht besser, denn sie? Sie sei dein an ihrer Statt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Und Simson sprach zu ihnen: Diesmal bin ich unschuldig an den Philistern, wenn ich an ihnen Böses tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'Und Simson ging und fing dreihundert Füchse und nahm Fackeln, und wandte sie, Schwanz gegen Schwanz, und tat je eine Fackel zwischen die zwei Schwänze in die Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'Und zündete die Fackeln mit Feuer an und entsandte sie in die Saatfelder der Philister, und zündete an von den Garbenhaufen und bis an die noch stehende Saat, und bis an die Weinberge und Ölgärten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Und die Philister sprachen: Wer hat das getan? Und sie sagten: Simson, der Schwiegersohn des Thimniters, weil dieser sein Weib nahm und sie seinem Freunde gab. Und die Philister zogen herauf und verbrannten sie und ihren Vater mit Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'Simson aber sprach zu ihnen: Obwohl ihr solches getan, muß ich doch erst Rache an euch nehmen. Dann will ich aufhören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'Und er schlug sie, Schenkel und Hüfte, mit einem großen Schlage; und er ging hinab und wohnte im Geklüfte der Felsklippe Etam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Und die Philister zogen hinauf und lagerten in Judah und ließen sich nieder in Lechi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Und die Männer von Judah sprachen: Warum seid ihr gegen uns heraufgezogen? Und sie sprachen: Den Simson zu binden, sind wir heraufgezogen, zu tun ihm, wie er uns getan hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Und dreitausend Mann von Judah zogen hinab nach dem Geklüfte der Felsklippe Etam und sprachen zu Simson: Weißt du nicht, daß die Philister über uns herrschen? Warum hast du uns aber das getan? Und er sprach zu ihnen: Wie sie mir taten, so habe ich ihnen getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Und sie sprachen zu ihm: Dich zu binden, sind wir herabgezogen, um dich in der Philister Hand zu geben. Und Simson sprach zu ihnen: Schwöret mir, daß ihr nicht auf mich stoßet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Und sie sprachen zu ihm und sagten: Nein, nur binden wollen wir dich und dich in ihre Hand geben; und werden dich nicht töten. Und sie banden ihn mit zwei neuen Seilen und brachten ihn herauf von der Felsklippe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Und er kam bis Lechi, und die Philister schrien ihm entgegen; aber der Geist Jehovahs fuhr in ihn, und die Seile an seinen Armen wurden wie Flachsfäden, die man im Feuer verbrennt, und seine Bande schmolzen ab von seinen Händen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'Und er fand einen frischen Kinnbacken eines Esels, und reckte seine Hand aus und nahm ihn und erschlug damit tausend Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'Und Simson sprach: Mit dem Eselskinnbacken habe ich einen Haufen, zwei Haufen, mit dem Eselskinnbacken habe ich tausend Mann erschlagen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'Und als er zu reden vollendet, warf er den Kinnbacken aus seiner Hand, und man nannte diesen Ort Ramath-Lechi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Und es dürstete ihn sehr, und er rief zu Jehovah und sprach: Du hast durch die Hand Deines Knechtes dieses große Heil gegeben, und nun sterbe ich vor Durst und falle in die Hand der Unbeschnittenen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Und Gott spaltete das Gebiß in dem Kinnbacken, und hervor kam daraus Wasser, und er trank und sein Geist kehrte zurück und er lebte auf. Darum nennt man ihren Namen Rufersquell, die bis auf diesen Tag in Lechi ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'Und er richtete Israel in den Tagen der Philister zwanzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'Und Simson ging nach Gassah und sah daselbst ein Weib, eine Buhlerin, und ging zu ihr ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'Den Gassitern ward gesagt: Simson ist hier hereingekommen. Und sie umgaben ihn und lagerten im Hinterhalt auf ihn die ganze Nacht am Tore der Stadt, und sie schwiegen die ganze Nacht stille und sagten: Bis an das Licht des Morgens, dann erwürgen wir ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'Und Simson lag bis Mitternacht; und um Mitternacht stand er auf und ergriff die Türen des Stadttores und die zwei Türpfosten und zog sie aus mit dem Riegel und legte sie auf seine Schultern und trug sie hinauf auf die Spitze des Berges vor Chebron.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Und es geschah danach, da liebte er ein Weib im Bachtal Schorek, und ihr Name war Delilah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'Und die Fürsten der Philister gingen zu ihr hinauf und sprachen zu ihr: Berede ihn und siehe, worin seine große Kraft ist, und wodurch wir ihn übermögen, so daß wir ihn binden und bezwingen können. Und wir wollen dir, jeder Mann tausend und hundert Silberlinge geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Und Delilah sprach zu Simson: Sage mir doch an, worin deine große Kraft ist, und womit man dich binden könnte, um dich zu bezwingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'Und Simson sagte zu ihr: Wenn man mich mit sieben frischen Stricken bindet, die noch nicht ausgetrocknet sind, so würde ich schwach und sein wie einer der Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Und die Fürsten der Philister, brachten ihr sieben frische Stricke, die noch nicht ausgetrocknet waren, herauf, und sie band ihn damit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'Und der Hinterhalt saß bei ihr in der Kammer. Und sie sprach zu ihm: Philister über dir, Simson! Und er riß die Stricke ab, wie man die Wergschnur abreißt, wenn sie nach Feuer riecht; und nicht ward bekannt seine Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'Und Delilah sprach zu Simson: Siehe, du hast mich hintergangen und Falsches zu mir geredet. Jetzt sage mir doch an, womit man dich binden kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'Und er sprach zu ihr: Wenn man mich bände mit neuen Seilen, mit denen noch keine Arbeit getan worden ist, dann würde ich schwach und wäre wie einer der Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Und Delilah nahm neue Seile und band ihn damit und sprach zu ihm: Philister über dir, Simson! Und der Hinterhalt war in der Kammer; und wie Faden riß er sie von seinen Armen ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'Und Delilah sprach zu Simson: Bisher hast du mich hintergangen und Falsches zu mir geredet. Sage mir an, womit kann man dich binden? Und er sprach zu ihr: Wenn du die sieben Locken meines Hauptes einwebst mit dem Webeaufzug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'Und sie schlug sie mit dem Pflock fest und sprach zu ihm: Philister über dir, Simson! Und er erwachte aus seinem Schlafe und zog den Pflock mitsamt dem Webeaufzug aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'Und sie sprach zu ihm: Wie kannst du doch sagen: Ich liebe dich, und ist doch dein Herz nicht bei mir? Diese dreimal hast du mich hintergangen und hast mir nicht angesagt, durch was so groß ist deine Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'Und es geschah, als sie so mit ihren Worten alle Tage ihn beengte und ihn zerplagte, ward seine Seele ungeduldig bis zum Tode.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Und er sagte ihr an sein ganzes Herz und sprach zu ihr: Kein Schermesser ist über mein Haupt gekommen; denn vom Leibe meiner Mutter an bin ich ein Nasiräer Gottes. Würde ich geschoren, so entwiche meine Kraft von mir, und ich würde schwach und wäre wie alle Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'Und Delilah sah, daß er ihr sein ganzes Herz angesagt hatte, und sie sandte und rief die Fürsten der Philister und sprach: Kommet herauf diesmal, denn er hat mir sein ganzes Herz angesagt. Und die Fürsten der Philister kamen herauf zu ihr, und sie brachten das Silber in ihrer Hand herauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'Und sie ließ ihn einschlafen auf ihren Knien und rief dem Manne, und er schor die sieben Locken seines Hauptes ab, und sie fing an, ihm zuzusetzen, und seine Kraft entwich von ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'Und sie sprach: Philister über dir, Simson! Und er erwachte von seinem Schlaf und sprach: Ich will hinausgehen, diesmal wie ehemals, und mich abschütteln, und er wußte nicht, daß Jehovah von ihm entwichen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Und die Philister griffen ihn und stachen ihm die Augen aus und brachten ihn hinab nach Gassah, und banden ihn mit Erzfesseln, und er mußte mahlen in dem Hause der Gebundenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Und das Haar seines Hauptes fing wieder an zu sprossen, nachdem es abgeschoren war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'Und die Fürsten der Philister versammelten sich, um ihrem Gotte Dagon ein großes Opfer zu opfern und fröhlich zu sein; und sie sprachen: Unser Gott hat den Simson, unseren Feind, in unsere Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'Und das Volk sah ihn, und sie lobten ihren Gott; denn sie sprachen: Unser Gott hat unseren Feind, den, der unser Land verödete und unsere Erschlagenen mehrte, in unsere Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'Und es geschah, als ihr Herz guter Dinge war, daß sie sprachen: Rufet uns Simson, daß er vor uns spiele. Und sie riefen Simson aus dem Hause der Gebundenen und er spielte vor ihnen, und sie ließen ihn zwischen den Säulen stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'Und Simson sprach zu dem Jungen, der ihn an der Hand hielt: Laß mich, daß ich die Säulen betaste, auf denen das Haus errichtet ist, auf daß ich mich darauf stütze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Und das Haus war voll von Männern und Weibern, und es waren allda alle Fürsten der Philister, und auf dem Dache bei dreitausend, Mann und Weib, die sehen wollten, wie Simson spiele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Und Simson rief zu Jehovah und sprach: O Herr, Jehovah! Gedenke doch meiner und stärke mich doch diesmal, Gott, daß ich mich mit einer Rache an den Philistern für meine zwei Augen räche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'Und Simson umfaßte die zwei Säulen in der Mitte, auf denen das Haus errichtet war, und stemmte sich auf sie, auf die eine mit seiner Rechten, auf die andere mit seiner Linken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'Und Simson sprach: Meine Seele sterbe mit den Philistern! Und er neigte sich mit Kraft; und das Haus fiel auf die Fürsten und auf alles Volk darin. Und es waren der Toten, die er bei seinem Tode tötete, mehr, als er bei seinem Leben getötet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'Und seine Brüder und das ganze Haus seines Vaters kamen herab, und sie hoben ihn auf und brachten ihn hinauf und begruben ihn zwischen Zorah und Eschtaol im Grabe seines Vaters Manoach. Und er hatte Israel zwanzig Jahre gerichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Und es war ein Mann vom Gebirge Ephraim und sein Name war Michajehu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Und er sprach zu seiner Mutter: Die tausendeinhundert Silberlinge, die dir genommen worden, und die du verwünscht und auch vor meinen Ohren gesprochen hast; siehe, dieses Silber ist bei mir, ich habe es genommen. Und seine Mutter sprach: Gesegnet sei mein Sohn von Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'Und er gab die tausendeinhundert Silberlinge seiner Mutter zurück. Und seine Mutter sprach: Ich heiligte das Silber dem Jehovah von meiner Hand für meinen Sohn, um ein Schnitzbild und ein Gußbild zu machen. Und nun gebe ich dir es zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'Und er gab das Silber seiner Mutter zurück und seine Mutter nahm davon zweihundert Silberlinge und gab es dem Goldschmied und er machte ein Schnitzbild und ein Gußbild davon, und es war im Hause Michajehus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'Und der Mann Michah hatte ein Gotteshaus und machte ein Ephod und Teraphim, und er füllte die Hand eines seiner Söhne, daß er sein Priester ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'In jenen Tagen war kein König in Israel. Jeder Mann tat, was recht in seinen Augen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'Und es war ein Jüngling aus Bethlehem Judah, aus der Familie Judahs; und er war ein Levite, und hielt sich dort als Fremdling auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Und der Mann war von der Stadt von Bethlehem Judah ausgezogen, um sich als Fremdling aufzuhalten, wo es sich fände, und er kam, als er seiner Wege ging, auf das Gebirge Ephraim zum Hause des Michah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'Und Michah sprach zu ihm: Woher kommst du? Und er sprach zu ihm: Ich bin ein Levite aus Bethlehem Judah, und ich gehe als Fremdling mich aufzuhalten, wo es sich findet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'Und Micha sprach zu ihm: Wohne bei mir und du sollst mir ein Vater und Priester sein. Und ich gebe dir jährlich zehn Silberlinge, einen Anzug von Kleidern und Lebensmittel. Und der Levite ging hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'Und der Levite war willens, bei dem Manne zu wohnen, und der Junge ward ihm wie einer seiner Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'Und Michah füllte die Hand des Leviten, und der Jüngling war ihm zum Priester. Und er war in Michahs Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Und Michah sprach: Nun weiß ich, daß Jehovah mir wohl tun wird, denn ich habe einen Leviten zum Priester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'In jenen Tagen war kein König in Israel; und in jenen Tagen suchte sich der Stamm der Daniter ein Erbe zum Wohnen; denn bis auf selbigen Tag war ihm noch kein Erbe inmitten der Stämme Israels zugefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'Und die Söhne Dans sandten aus ihrer Familie fünf Männer aus ihren Enden, streitbare Männer aus Zorah und aus Eschtaol, das Land auszukundschaften und es zu erforschen, und sprachen zu ihnen: Geht und erforschet das Land. Und sie kamen auf das Gebirge Ephraim zum Hause Michahs und übernachteten allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Sie waren am Hause Michahs, und sie erkannten die Stimme des Jünglings, des Leviten, und kehrten da ein und sprachen zu ihm: Wer hat dich hierher gebracht. Und was tust du hier? Und was hast du hier?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'Und er sprach zu ihnen: So und so hat Michah an mir getan, und hat mich gedingt, und ich ward sein Priester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'Und sie sprachen zu ihm: Frage doch an bei Gott, daß wir wissen, ob uns gelinge der Weg, auf dem wir ziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Und der Priester sprach zu ihnen: Gehet hin im Frieden; euer Weg, den ihr geht, ist gerade vor Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'Und die fünf Männer gingen hin und kamen gen Laisch und sahen das Volk, das in seiner Mitte war, sicher wohnen, nach der Weise der Zidonier, stille und sicher. Da war keiner, der wegen etwas einem Schande antat, oder Gewalt besäße. Und sie waren fern von den Zidoniern und hatten mit keinem Menschen etwas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Und sie kamen zu ihren Brüdern nach Zorah und Eschtaol, und ihre Brüder sprachen zu ihnen: Wie ist es mit euch?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'Und sie sprachen: Machet euch auf, und lasset uns hinaufziehen wider sie; denn wir haben das Land gesehen, und siehe, es ist sehr gut. Und nun schweiget ihr? Verziehet nicht, zu gehen, kommet, um das Land einzunehmen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'So ihr hinkommt, werdet ihr zu einem sicheren Volke kommen, und das Land ist weit nach beiden Seiten. Denn Gott hat es in eure Hand gegeben. Es ist ein Ort, da es keinen Mangel hat an irgend etwas, das auf Erden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'Und sie brachen auf von dannen von der Familie der Daniter, aus Zorah und aus Eschtaol, sechshundert Mann, mit Waffen zum Streit gegürtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'Und sie zogen hinauf und lagerten in Kirjath-Jearim in Judah, daher nennt man selbigen Ort bis auf diesen Tag Machaneh-Dan. Siehe, es ist hinter Kirjath-Jearim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'Und von dannen zogen sie hinüber auf das Gebirge Ephraim und kamen zum Hause des Michah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Und die fünf Männer, die gegangen waren, das Land Laisch auszukundschaften, hoben an und sprachen zu ihren Brüdern: Wisset ihr, daß da ist in diesen Häusern ein Ephod und Teraphim, und ein Schnitzbild und ein Gußbild? Und nun wisset ihr, was ihr tun sollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'Und sie wandten sich dorthin und kamen zum Haus des Jungen, des Leviten, zum Haus Michahs und fragten ihn nach seinem Wohlsein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Und die sechshundert Mann von den Söhnen Dans, gegürtet mit ihren Waffen des Streites, hatten sich am Eingang des Tores aufgestellt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'Und die fünf Männer, die gegangen waren, das Land auszukundschaften, gingen hinauf, kamen da hinein, nahmen das Schnitzbild und das Ephod und die Teraphim und das Gußbild. Und der Priester stand am Eingang des Tores und die sechshundert Männer, gegürtet mit Waffen des Streites.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'Und sie kamen in Michahs Haus und nahmen das Schnitzbild, das Ephod, die Teraphim und das Gußbild und der Priester sprach zu ihnen: Was tut ihr?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Und sie sprachen zu ihm: Schweig still, lege deine Hand auf deinen Mund und gehe mit uns und sei uns zum Vater und zum Priester. Ist es besser für dich, daß du für das Haus eines Mannes Priester bist, oder daß du Priester seiest für einen Stamm und eine Familie in Israel?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'Und das Herz des Leviten ward begütigt, und er nahm das Ephod und die Teraphim und das Schnitzbild und kam in des Volkes Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'Und sie wandten sich und zogen hin, und sie hatten Kinder, Viehherden und schwere Habe vorausgestellt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Sie entfernten sich von Michahs Haus, da wurden die Männer in den Häusern, bei Michahs Haus berufen, und holten Dans Söhne ein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'Und sie riefen den Söhnen Dans zu; und sie wandten ihre Angesichte herum und sprachen zu Michah: Was hast du, daß du sie berufen hast?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'Und er sprach: Meine Götter, die ich gemacht habe, habt ihr genommen und den Priester, und seid davongegangen. Und was habe ich noch? Und was ist es, daß ihr zu mir sagt: Was hast du denn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Und die Söhne Dans sprachen zu ihm: Laß deine Stimme nicht bei uns hören, auf daß nicht Männer von erbitterter Seele auf euch stoßen, und du deine Seele und deines Hauses Seele hinraffst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'Und die Söhne Dans zogen ihres Weges, und Michah sah, daß sie ihm zu stark waren, und er wandte sich und kehrte in sein Haus zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Und sie nahmen, was Michah gemacht, und den Priester, den er hatte, und sie kamen wider Laisch und wider das stille und sichere Volk, und schlugen sie mit der Schärfe des Schwertes und verbrannten die Stadt mit Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'Und niemand errettete sie; denn sie war ferne von Zidon und hatte mit keinem Menschen etwas. Und sie war im Talgrunde bei Beth-Rechob. Sie aber bauten die Stadt und wohnten darin,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'Und nannten den Namen der Stadt Dan, nach dem Namen ihres Vaters Dan, der dem Israel geboren wurde. Aber zuerst war der Name der Stadt Laisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'Und die Söhne Dans richteten sich das Schnitzbild auf, und Jehonathan, der Sohn Gerschom, des Sohnes Menaschehs, er und seine Söhne waren Priester dem Stamme des Daniters, bis auf den Tag, da das Land weggeführt wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Und sie stellten für sich auf das Schnitzbild Michahs, das er gemacht hatte, alle die Tage, die das Haus Gottes in Schiloh war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'Und es geschah in jenen Tagen, da kein König in Israel war, daß ein Mann, ein Levite, sich auf der Hinterseite des Gebirges Ephraim als Fremdling aufhielt, und sich ein Weib, ein Kebsweib nahm, aus Bethlehem Judah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Und sein Kebsweib buhlte neben ihm und ging fort von ihm zum Haus ihres Vaters nach Bethlehem Judah, und war allda etliche Tage, vier Monate.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Und ihr Mann machte sich auf und ging ihr nach, um an ihr Herz zu reden, um sie zurückzubringen, und hatte seinen Jungen und ein Paar Esel mit sich. Und sie führte ihn hinein in das Haus ihres Vaters. Und der Vater der Dirne sah ihn und ging ihm fröhlich entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'Und sein Schwäher, der Vater der Dirne, hielt ihn, und er blieb bei ihm drei Tage; und sie aßen und tranken und übernachteten daselbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Und es geschah am vierten Tage, daß sie sich früh am Morgen aufmachten, und er machte sich auf, um zu gehen. Und der Vater der Dirne sprach zu seinem Eidam: Labe dein Herz mit einem Bissen Brot und danach möget ihr gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Und sie saßen nieder und aßen beide miteinander und tranken. Und der Vater der Dirne sprach zu dem Manne: Beliebe doch und bleib über Nacht, und laß dein Herz guter Dinge sein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'Und der Mann stand auf, um zu gehen; sein Schwäher aber drang in ihn, und er kehrte zurück und übernachtete allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Und am fünften Tag stand er früh am Morgen auf, um zu gehen; und der Vater der Dirne sprach: Labe doch dein Herz und säumet, bis der Tag sich neigt. Und sie aßen beide.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'Und der Mann stand auf, um zu gehen, er und sein Kebsweib und sein Junge. Und sein Schwäher, der Vater der Dirne, sprach zu ihm: Siehe doch, der Tag senkt sich zum Abend; übernachtet doch! Siehe, der Tag hat sich geneigt. Übernachte hier! Laß dein Herz guter Dinge sein, und morgen machet ihr euch früh auf euren Weg, und du gehst nach deinem Zelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'Der Mann aber wollte nicht übernachten und machte sich auf, und zog hin und kam bis vor Jebus, das ist Jerusalem, und mit ihm sein Paar beladene Esel und sein Kebsweib war mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Sie waren bei Jebus, und der Tag hatte sich sehr geneigt. Und der Junge sprach zu seinem Herrn: Komm doch und laß uns einkehren in dieser Stadt der Jebusiter und in ihr übernachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Und sein Herr sprach zu ihm: Nein, wir wollen nicht in der Stadt der Ausländischen einkehren, die nicht von den Söhnen Israels sind, sondern nach Gibeah hinüberziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Und er sagte zu seinem Jungen: Gehe, daß wir einem der Orte uns nähern und in Gibeah oder Ramah übernachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Und sie gingen vorüber und zogen hin; bei Gibeah aber, das des Benjamin ist, ging ihnen die Sonne unter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'Und sie wandten sich dort ab, um nach Gibeah zu kommen zum Übernachten. Und er kam hinein und setzte sich nieder in der Straße der Stadt; und es war kein Mann, der sie ins Haus zum Übernachten aufgenommen hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Und siehe, ein alter Mann kam am Abend von seiner Arbeit vom Feld. Und der Mann war vom Gebirge Ephraim, und er hielt sich als Fremdling in Gibeah auf; die Männer des Ortes aber waren Benjaminiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'Und er hob seine Augen auf und sah den Mann, den Reisenden, auf der Straße der Stadt; und der alte Mann sprach: Wohin gehst du, und woher kommst du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'Und er sprach zu ihm: Wir ziehen hin von Bethlehem Judah an die Seite des Gebirges Ephraim. Von dort bin ich, und ging nach Bethlehem Judah, und ich gehe nach dem Hause Jehovahs, und kein Mann nimmt mich ins Haus auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Und wir haben sowohl Stroh und Futter für unsere Esel, als auch Brot und Wein für mich und deine Magd und für den Jungen, der bei deinem Knechte ist; es ist kein Mangel an irgend etwas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Und der alte Mann sprach: Friede sei mit dir! Nur sei alles, was dir mangelt, auf mir, nur übernachte nicht hier auf der Straße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'Und er brachte ihn in sein Haus, und mischte Futter für die Esel, und sie wuschen ihre Füße, und sie aßen und tranken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'Und ihr Herz war guter Dinge; aber siehe, die Männer der Stadt, Männer, die Belialssöhne waren, umgaben das Haus, pochten an die Tür und sprachen zu dem Manne, dem Meister des Hauses, dem Alten, und sagten: Bringe den Mann heraus, der zu deinem Haus gekommen ist, daß wir ihn erkennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'Und der Mann, der Meister des Hauses, ging zu ihnen hinaus und sprach zu ihnen: Nicht doch, meine Brüder, tut doch nicht Böses, nachdem der Mann zu meinem Haus gekommen ist. Machet nicht solche Torheit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Siehe, meine Tochter, die Jungfrau und sein Kebsweib, sie lasset mich zu euch herausführen, und schwächet sie und tut mit ihnen, was gut in euren Augen ist; aber an diesem Manne sollt ihr nichts von solcher Torheit tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'Aber die Männer waren nicht willens, auf ihn zu hören; da faßte der Mann sein Kebsweib und brachte sie hinaus zu ihnen, und sie erkannten sie und mißhandelten sie die ganze Nacht bis zum Morgen, und als die Morgenröte aufging entließen sie dieselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'Und das Weib kam mit Anbruch des Morgens und fiel hin am Eingang des Hauses des Mannes, wo ihr Herr war, bis es licht ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Und ihr Herr stand am Morgen auf und öffnete die Türen des Hauses und kam heraus, um seines Weges zu gehen, und siehe, das Weib, sein Kebsweib, war am Eingang des Hauses hingefallen und ihre Hände auf der Schwelle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'Und er sprach zu ihr: Stehe auf, wir wollen gehen, aber niemand antwortete; und er nahm sie auf den Esel, und der Mann machte sich auf und ging an seinen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'Und er kam in sein Haus und nahm ein Messer und faßte sein Kebsweib und zerstückte sie nach ihren Gebeinen in zwölf Stücke und sandte sie in alle Grenzen von Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'Und es geschah, daß jeder, der es sah, sprach: So etwas ist nicht geschehen, noch gesehen worden, seit dem Tage, da die Söhne Israels aus dem Lande Ägypten heraufzogen bis auf diesen Tag. Überlegt es bei euch, ratet und redet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Und alle Söhne Israels zogen aus, und die Gemeinde versammelte sich wie ein Mann von Dan bis Beer-Scheba und das Land Gilead zu Jehovah nach Mizpah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'Und es stellten sich ein die Anführer des ganzen Volkes, alle Stämme Israels in der Versammlung des Volkes Gottes, vierhunderttausend Mann zu Fuß, die das Schwert zogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Und die Söhne Benjamins hörten, daß die Söhne Israels nach Mizpah heraufzogen. Und die Söhne Israels sprachen: Redet, wie dieses Böse geschehen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'Und der Mann, der Levite, der Mann des gemordeten Weibes antwortete und sprach: Nach Gibeah, das Benjamin gehört, kam ich, ich und mein Kebsweib, um zu übernachten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'Und es machten sich wider mich auf die Bürger von Gibeah und umgaben ob meiner das Haus in der Nacht, und waren gesonnen, mich zu erwürgen, und sie schändeten mein Kebsweib, daß sie starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Und ich ergriff mein Kebsweib und zerstückte sie und sandte sie in das ganze Gefilde von Israels Erbe, darum, daß sie solche Schandtat und Torheit in Israel getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Siehe, ihr alle seid Söhne Israels. Gebet für euch Wort und Rat allhier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Und das ganze Volk stand auf wie ein Mann und sprach: Kein Mann von uns gehe nach seinem Zelt, und kein Mann wende sich ab nach seinem Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'Und das ist jetzt, was wir an Gibeah tun wollen, wider dasselbe nach dem Los:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Daß wir nehmen zehn Mann vom Hundert von allen Stämmen Israels, und hundert von tausend und tausend von zehntausend, auf daß sie Zehrung holen für das Volk, um bei ihrem Kommen zu tun an Gibeah Benjamin nach all der Torheit, die es in Israel getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Und es versammelten sich alle Männer Israels nach der Stadt, wie ein Mann verbündet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'Und die Stämme Israels sandten Männer zu allen Geschlechtern Benjamins, um zu sagen: Was ist dieses Böse, das unter euch geschehen ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Und nun gebet die Männer, die Belialssöhne zu Gibeah her, auf daß wir sie töten und das Böse aus Israel austilgen. Aber die Söhne Benjamins waren nicht willens, zu hören auf die Stimme ihrer Brüder, der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Und die Söhne Benjamins versammelten sich aus den Städten nach Gibeah, um zum Streite mit den Söhnen Israels auszuziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'Und es wurden gemustert Söhne Benjamins am selbigen Tage aus den Städten sechsundzwanzigtausend Mann, die das Schwert zogen, ohne die Einwohner Gibeahs; und ihrer wurden siebenhundert auserwählte Männer gemustert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Aus all diesem Volke waren siebenhundert auserwählte Männer, die an der rechten Hand lahm waren. Ein jeder derselben schleuderte mit dem Stein auf ein Haar und fehlte nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'Und der Männer Israels wurden gemustert ohne Benjamin vierhunderttausend Mann, die das Schwert zogen, alle Männer des Streites.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'Und sie machten sich auf und zogen hinauf gen Bethel und fragten Gott, und die Söhne Israels sprachen: Wer soll hinaufziehen für uns zum Streit mit den Söhnen Benjamins zum Anbeginn? Und Jehovah sprach: Judah soll beginnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Und die Söhne Israels machten sich am Morgen auf und lagerten wider Gibeah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'Und Israels Mannschaft zog aus zum Streite mit Benjamin, und die Männer Israels ordneten sich bei ihnen zum Streite gegen Gibeah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Und die Söhne Benjamins zogen aus aus Gibeah und schlugen an selbigem Tage von Israel zweiundzwanzigtausend Mann zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Das Volk aber, die Mannschaft Israels, verstärkte sich und sie ordneten sich an demselben Orte, wo sie am ersten Tage sich geordnet hatten, wiederum zum Streite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'Und die Söhne Israels gingen hinauf und weinten vor Jehovah bis zum Abend, und fragten Jehovah und sprachen: Soll ich abermals herzutreten zum Streite mit den Söhnen meines Bruders Benjamin? Und Jehovah sprach: Ziehet hinauf wider ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'Und die Söhne Israels nahten sich den Söhnen Benjamins am zweiten Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'Und Benjamin zog am zweiten Tag aus von Gibeah ihnen entgegen und schlugen abermals von den Söhnen Israels achtzehntausend Mann zur Erde, die alle das Schwert zogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Und alle Söhne Israels und alles Volk zogen hinauf und kamen nach Bethel und weinten und saßen da vor Jehovah und fasteten an selbigem Tage bis an den Abend und ließen Brandopfer und Dankopfer vor Jehovah aufgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'Und die Söhne Israels fragten an bei Jehovah, und die Bundeslade Gottes war allda in selbigen Tagen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'Und Pinechas, der Sohn Eleasars, des Sohnes Aharons, stand in selbigen Tagen vor Ihm, und sie sprachen: Soll ich abermals ausziehen zum Streite mit den Söhnen meines Bruders Benjamin, oder soll ich aufhören? Und Jehovah sprach: Ziehet hinauf; denn morgen werde Ich ihn in deine Hand geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'Und Israel legte Hinterhalte gegen Gibeah ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Und die Söhne Israels zogen hinauf wider die Söhne Benjamins am dritten Tage und ordneten sich an wider Gibeah diesmal wie das andere Mal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'Und die Söhne Benjamins zogen aus, dem Volke entgegen; sie wurden von der Stadt abgezogen und fingen an, diesmal wie das andere Mal, auf den Heerstraßen, von denen eine hinaufgeht nach Bethel und die andere durch das Feld hin nach Gibeah, von dem Volk zu schlagen bei dreißig Mann Erschlagener in Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Und die Söhne Benjamins sprachen: Sie sind geschlagen vor uns wie zuerst. Und die Söhne Israels sprachen: Lasset uns fliehen und sie von der Stadt auf die Heerstraßen abziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'Und alle Männer Israels standen auf von ihren Orten und ordneten sich zu Baal-Thamar an; und der Hinterhalt Israels brach hervor aus seinem Ort aus Gibeahs Umkreis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'Und von Gibeah her kamen zehntausend Mann, aus ganz Israel auserwählt, und der Streit ward schwer; und sie wußten nicht, daß das Übel sie erreichen sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'Und Jehovah schlug Benjamin vor Israel, und die Söhne Israels verdarben in Benjamin an diesem Tage fünfundzwanzigtausend und hundert Mann, die alle das Schwert zogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'Und die Söhne Benjamins sahen, daß sie geschlagen waren, die Männer von Israel aber gaben Benjamin Raum, weil sie auf den Hinterhalt vertrauten, den sie wider Gibeah gelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'Die in dem Hinterhalte aber kamen schleunig und rückten an gegen Gibeah, und der Hinterhalt zog aus und schlug die ganze Stadt mit der Schärfe des Schwertes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Und die Bestimmung der Männer Israels mit dem Hinterhalte war, daß sie eine große Erhebung von Rauch aus der Stadt aufsteigen lassen sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'Und die Männer Israels kehrten um in dem Streit, und Benjamin fing an, zu schlagen von den Männern Israels bei dreißig Mann Erschlagener, denn sie sagten: Sie sind eben geschlagen vor uns, wie im ersten Streit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Da fing aber an, eine Erhebung aufzusteigen von der Stadt, eine Rauchsäule. Und Benjamin wandte sich hinter sich und siehe: die ganze Stadt ging auf zum Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'Und die Männer Israels wandten sich um, und die Söhne Benjamins wurden bestürzt, denn sie sahen, daß das Übel sie erreicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Und sie wandten sich vor den Männern Israels nach dem Wege zur Wüste, aber der Streit holte sie ein, und die aus den Städten verdarben sie in der Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'Und sie umringten Benjamin, setzten ihm nach und zertraten ihn, wo er ruhen wollte, bis gegenüber von Gibeah gegen Aufgang der Sonne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'Und es fielen von Benjamin achtzehntausend Mann, alle diese tapfere Männer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'Und sie wandten sich und flohen der Wüste zu an die Felsenklippe Rimmon; und sie hielten Nachlese über sie auf den Heerstraßen noch fünftausend Mann, und hängten sich hinten an sie bis Gideom und schlugen von ihnen zweitausend Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Und aller, die an selbigem Tage von Benjamin fielen, waren fünfundzwanzigtausend Mann, die das Schwert zogen, alle diese tapfere Männer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Und sechshundert Mann wandten sich und flohen der Wüste zu nach der Felsenklippe Rimmon, und blieben auf der Felsenklippe Rimmon vier Monate.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'Und die Männer Israels kamen zurück zu den Söhnen Benjamin und schlugen die von der Stadt mit der Schärfe des Schwertes, von den Leuten bis zum Vieh, bis zu allem, das man fand, und alle Städte, die sie fanden, steckten sie in Brand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'Und die Männer Israels hatten in Mizpah geschworen und gesagt: Kein Mann von uns soll seine Tochter dem Benjamin zum Weibe geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'Und das Volk kam gen Bethel und blieb allda bis zum Abend vor Gott, und sie hoben auf ihre Stimme und weinten mit gro-ßem Weinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'Und sie sprachen: Warum, o Jehovah, Gott Israels, geschah dies in Israel, daß heute ein Stamm vermißt wird aus Israel?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Und es geschah am morgenden Tag, daß sich das Volk früh aufmachte und baute allda einen Altar und opferte Brand- und Dankopfer auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'Und die Söhne Israels sprachen: Wer ist es von allen Stämmen Israels, der nicht heraufgekommen ist in die Versammlung zu Jehovah? Denn der große Schwur geschah, daß, wer nicht zu Jehovah nach Mizpah heraufgekommen ist, der, sprach man, sollte des Todes sterben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'Und es reute die Söhne Israels wegen ihres Bruders Benjamin und sie sprachen: Heute ist ein Stamm aus Israel niedergehauen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Was sollen wir mit ihnen, mit den Übriggebliebenen behufs der Weiber tun? Wir haben ja geschworen bei Jehovah, daß wir ihnen keine von unseren Töchtern zu Weibern geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Und sie sprachen: Wer ist der eine aus den Stämmen Israels, der nicht zu Jehovah nach Mizpah heraufgekommen ist. Und siehe, es war kein Mann aus Jabesch Gilead in das Lager zu der Versammlung gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Und das Volk ward gemustert, und siehe, es war kein Mann da von den Einwohnern von Jabesch Gilead.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'Und die Gemeinde sandte dorthin zwölftausend Männer von den Söhnen der Tapferkeit, und sie geboten ihnen und sprachen: Gehet hin und schlaget die Einwohner von Jabesch Gilead mit der Schärfe des Schwertes, beides, Weiber und Kinder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Und dies ist das Ding, das ihr tun sollt, jedes Männliche und jedes Weib, welches das Beilager des Männlichen gekannt, sollt ihr verbannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'Und sie fanden unter den Einwohnern von Jabesch Gilead vierhundert Mädchen, Jungfrauen, die noch keinen Mann im Beilager des Männlichen erkannt, und brachten sie zum Lager nach Schiloh, das im Lande Kanaan ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'Und die ganze Gemeinde sandte, und sie redeten mit den Söhnen Benjamins, die auf der Felsenklippe Rimmon waren, und riefen ihnen Frieden zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Und Benjamin kehrte zurück um selbige Zeit, und sie gaben ihnen die Weiber, die man von den Weibern in Jabesch Gilead hatte am Leben gelassen; aber man fand sie nicht zureichend für sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'Und es reute das Volk wegen Benjamins, daß Jehovah bei den Stämmen Israels einen Durchbruch gemacht hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Und die Ältesten der Gemeinde sprachen: Was sollen wir tun für die Überbleibenden behufs der Weiber? das Weib ist ja aus Benjamin vernichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'Und sie sprachen: Der Erbbesitz der Entronnen sei des Benjamin, auf daß nicht ein Stamm vertilgt werde aus Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Und wir können ihnen keine Weiber von unseren Töchtern geben; denn die Söhne Israels haben geschworen und gesagt: Verflucht sei, wer ein Weib gibt einem Benjaminiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Und sie sprachen: Siehe, es ist von Jahr zu Jahr ein Fest Jehovahs zu Schiloh, das mitternächtlich von Bethel ist gegen Aufgang der Sonne an der Heerstraße, die von Bethel hinauf gen Sichem geht, und mittäglich von Lebona;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'Und sie geboten den Söhnen Benjamins und sprachen: Geht und legt euch in Hinterhalt in den Weinbergen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Und ihr werdet sehen, und siehe, Schilohs Töchter kommen heraus zum Tanze im Reigen, da geht ihr heraus aus den Weinbergen, und jeder Mann erhasche sich sein Weib von Schilohs Töchtern und geht nach dem Lande Benjamins.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Und es wird geschehen, wenn ihre Väter oder ihre Brüder zu uns kommen, zu hadern, dann wollen wir zu ihnen sprechen: Seid ihnen gnädig unserthalben, wir haben im Streite nicht für jeden Mann sein Weib genommen. Ihr habt sie ihnen ja nicht gegeben, daß ihr zur Zeit würdet schuldig sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'Und Benjamins Söhne taten also und holten sich Weiber nach ihrer Zahl von den Tänzerinnen, die sie entrissen, und gingen hin und kehrten zurück zu ihrem Erbe, und bauten die Städte und wohnten darin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Und die Söhne Israels zogen ab von da zu selbiger Zeit, jeder Mann zu seinem Stamm und zu seiner Familie, und sie gingen aus von dannen, jeder Mann zu seinem Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'In jenen Tagen war kein König in Israel, ein jeder Mann tat, was recht in seinen Augen war.');
