INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Selig der Mann, der in der Ungerechten Rat nicht wandelt, und auf der Sünder Weg nicht steht, noch sitzet auf der Spötter Sitz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Sondern hat seine Lust am Gesetze Jehovahs, und sinnet in Seinem Gesetze Tag und Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Und er ist wie ein Baum gepflanzet an Bächlein der Wasser, der seine Frucht gibt zu seiner Zeit und seine Blätter welken nicht, und alles, was er tut, gelingt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Nicht so die Ungerechten, sondern wie die Spreu sind sie, welche der Wind vertreibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Darum bestehen die Ungerechten nicht im Gericht, noch die Sünder in der Gemeinde der Gerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Denn Jehovah kennt den Weg der Gerechten, aber der Ungerechten Weg vergeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Warum stürmen die Völkerschaften und sinnen Leeres die Völker?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Die Könige der Erde stehen auf, und die Beherrscher ratschlagen miteinander wider Jehovah und wider Seinen Gesalbten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'Laßt uns abreißen ihre Bande und von uns werfen ihre Seile!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'Der in den Himmeln wohnt, lacht; der Herr verlacht sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Dann redet Er mit ihnen in Seinem Zorn, und macht sie bestürzt in Seinem Entbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Ich aber habe Meinen König gesalbt auf Zijon, dem Berge Meiner Heiligkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Erzählen will Ich von der Satzung: Jehovah sprach zu Mir, Mein Sohn bist Du, Ich habe heute Dich gezeugt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Bitte von Mir, so will zum Erbe Ich dir die Völkerschaften, zum Eigentum der Erde Enden geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Du sollst sie zerbrechen mit eisernem Zepter, wie des Töpfers Gefäße sie zerschmei-ßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Und nun, werdet klug, ihr Könige, laßt euch züchtigen, ihr Richter der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'Dient Jehovah mit Furcht, und frohlockt Ihm mit Beben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Küsset den Sohn, daß Er nicht zürne und ihr umkommet auf dem Weg! denn über ein Kleines so entbrennt Sein Zorn. Selig sind alle, die auf Ihn sich verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, 'Ein Psalm Davids, da er entwich vor seinem Sohne Absalom.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Jehovah, wieviel sind meiner Dränger. Viele sind es, die wider mich aufstehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Viele sprechen von meiner Seele: Keine Rettung hat er in Gott. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Doch Du, Jehovah, bist ein Schild für mich, meine Herrlichkeit, Du hebst mein Haupt empor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Mit meiner Stimme rufe ich zu Jehovah; und Er antwortet mir von dem Berg Seiner Heiligkeit. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Ich liege und schlafe; ich erwache; denn Jehovah erhält mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Nicht fürchte ich mich vor Zehntausenden des Volks, die ringsum sich wider mich setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Mache Dich auf, Jehovah, rette mich, mein Gott! denn Du schlägst alle meine Feinde auf den Backen, Du zerbrichst der Ungerechten Zähne. Bei Jehovah ist Heil! Dein Segen sei auf Deinem Volke. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, 'Dem Sangmeister zum Saitenspiel. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Antworte mir, wenn ich rufe, Gott meiner Gerechtigkeit! Aus der Bedrängnis bringst Du mich ins Weite. Sei mir gnädig und höre auf mein Beten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Ihr Mannessöhne, wie lang wird meine Herrlichkeit zur Schande? Ihr liebet das Leere, trachtet nach Falschem! Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Erkennet aber, daß Jehovah Wunderbares an Seinem Frommen tut. Jehovah hört, wenn ich zu Ihm rufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Seid ihr erregt, so sündigt nicht! Sprechet in eurem Herzen auf eurem Lager und seid stille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Opfert Opfer der Gerechtigkeit, und vertrauet auf Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Es sprechen viele: Wer läßt uns Gutes sehen? Erhebe Du, Jehovah, das Licht Deines Angesichts über uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'Du gibst Fröhlichkeit in mein Herz mehr denn zur Zeit, da ihr Korn und ihr Most sich mehren. Im Frieden lege ich mich nieder zumal und schlafe; denn Du allein, Jehovah, läßt sicher mich wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, 'Dem Sangmeister auf den Nechiloth. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Jehovah, nimm zu Ohren meine Reden, und merke auf mein Sinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Horch auf die Stimme meines Angstschreis, mein König und mein Gott; denn zu Dir bete ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Jehovah, höre am Morgen meine Stimme. Am Morgen richte ich mich an Dich und schaue empor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Denn Du bist nicht ein Gott, Der Lust hat an Ungerechtigkeit. Der Böse weilt nicht bei Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Nicht dürfen sich die, so sich rühmen, Dir vor Augen stellen, Du hassest alle, welche Unrecht tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Du zerstörst die, so Falsches reden. Der Mann des Blutes und des Trugs ist ein Greuel dem Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Ich aber komme in Dein Haus in Deiner vielen Barmherzigkeit; ich bete Dich an in Deiner Furcht im Tempel Deiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Jehovah führe mich in Deiner Gerechtigkeit um meiner Widersacher willen, mache eben Deinen Weg vor mir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Denn nichts Richtiges ist in ihrem Mund, Verstörung ist ihr Inneres, ein offen Grab ist ihre Kehle, mit ihrer Zunge schmeicheln sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'Laß ihre Schuld sie tragen, Gott, laß fallen sie durch ihre eigenen Ratschläge. Ob ihrer vielen Übertretungen stoße sie aus; denn sie sind widerspenstig gegen Dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Daß alle fröhlich seien, die sich auf Dich verlassen, ewiglich lobpreisen, daß Du sie beschirmst; und laß über Dir jauchzen, die Deinen Namen lieben. Denn den Gerechten segnest Du, Jehovah, umgibst mit Wohlgefallen ihn wie mit dem Schilde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, 'Dem Sangmeister, auf der Oktave mit Saitenspiel. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Jehovah, strafe mich nicht in Deinem Zorn, und züchtige mich nicht in Deinem Grimm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'Sei gnädig mir, Jehovah; denn ich verschmachte. Heile mich, Jehovah; denn meine Gebeine sind bestürzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Und meine Seele ist sehr bestürzt. Und Du, Jehovah, wie lange.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Kehre zurück, Jehovah, befreie meine Seele, rette mich um Deiner Barmherzigkeit willen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Denn man gedenkt Dein nicht im Tode. Wer in der Hölle bekennt Dich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Ich bin müde von meinem Seufzen, schwemme die ganze Nacht mein Bett, netze mit meinen Tränen mein Ruhebett.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Mein Auge schmachtet vor Verdruß, ist alt geworden ob aller meiner Dränger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Weicht ab von mir alle, die ihr Unrecht tut; denn Jehovah hört auf die Stimme meines Weinens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Jehovah hat gehört mein Flehen. Jehovah nimmt an mein Gebet. Beschämt werden alle meine Feinde und sehr bestürzt; zurückkehren sie beschämt im Augenblick.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, 'Schiggajon Davids, das er Jehovah sang wegen der Worte des Benjaminiters Kusch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'Jehovah, mein Gott, auf Dich verlasse ich mich, hilf mir von allen meinen Verfolgern, und errette mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'Auf daß er meine Seele nicht zerfleische wie ein Löwe, und zerbreche, daß niemand errette.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'Jehovah, mein Gott, habe solches ich getan, ist Verkehrtheit in meinen Händen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'Habe Böses ich erwidert dem, der friedlich mit mir war, habe ausgeplündert den, der ohne Grund mich drängte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'So setze der Feind meiner Seele nach und erreiche sie, er stampfe mein Leben zur Erde und lege meine Herrlichkeit in den Staub! Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Stehe auf, Jehovah, in Deinem Zorn, erhebe Dich wider das Wüten meiner Dränger, und wache auf für mich, Du hast das Gericht geboten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Und Dich umgebe die Gemeinde der Volksstämme, und über ihr kehre zurück zur Höhe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Jehovah spricht den Völkern Recht. Jehovah richte mich, nach meiner Gerechtigkeit und meiner Rechtschaffenheit über mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Laß doch der Ungerechten Bosheit zu Ende kommen! Und befestige Du den Gerechten, Der Du die Herzen und die Nieren prüfst, gerechter Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Mein Schild ist bei Gott. Er hilft denen, so geraden Herzens sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Gott ist ein gerechter Richter, aber ein Gott, Der den ganzen Tag Unwillen hegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'Kehrt er nicht um, so schärft Er Sein Schwert, spannt und richtet Er Seinen Bogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Und hat des Todes Geräte Sich bereitet, und macht zu Brandern Seine Pfeile.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Siehe, mit Unrecht hat er Geburtsnot, und ist mit Mühsal schwanger, und Lüge hat er geboren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Er hat eine Grube gegraben und sie ausgehöhlt, fiel aber selber in den Graben, den er gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Sein Mühsal kehrt auf sein Haupt zurück, und die Gewalttat kommt herab auf seinen Scheitel. Bekennen will ich Jehovah nach Seiner Gerechtigkeit und Psalmen singen dem Namen Jehovahs, des Allerhöchsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, 'Dem Sangmeister auf der Githith. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Jehovah, unser Herr, wie herrlich ist Dein Name auf der ganzen Erde, Der Du Deine Majestät hast gegeben über die Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Aus dem Munde der Kindlein und der Säuglinge hast Du Dir Stärke gegründet, um Deiner Dränger willen, daß der Feind und der Rachgierige zu Ende komme!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'Wenn Deine Himmel ich sehe, Deiner Finger Werk, Mond und Gestirne, die Du bereitet hast:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Was ist der Mensch, daß seiner Du gedenkst? Und des Menschen Sohn, daß Du ihn heimsuchst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Ein wenig lässest Du ihm zu einem Engel mangeln und krönest ihn mit Herrlichkeit und Ehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'Du machst ihn zum Herrscher über Deiner Hände Werk, alles hast Du unter seine Füße gelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'Kleinvieh und Rinder, alle von ihnen, und auch das Vieh des Feldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Den Vogel der Himmel und des Meeres Fische, was der Meere Pfade durchzieht. Jehovah, unser Herr, wie herrlich ist Dein Name auf der ganzen Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, 'Dem Sangmeister auf Muth Labben. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Jehovah bekenne ich von ganzem Herzen, will erzählen alle Deine Wunder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'In Dir will ich fröhlich sein und jauchzen, Psalmen singen Deinem Namen, Du Allerhöchster.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Wenn meine Feinde hinter sich zurückweichen, straucheln sie und gehen zugrunde vor Dir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'Denn Du tust mir Gericht und Recht, Du sitzest auf dem Throne, ein gerechter Richter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Du hast bedroht die Heiden, hast zerstört den Ungerechten. Du hast ihren Namen ausgewischt ewiglich und immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'Die Feinde: zunichte sind die Verheerungen auf immerdar, und die Städte hast Du ausgerissen, ihr Andenken verging mit ihnen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'Jehovah aber sitzet in Ewigkeit, Er hat zum Gerichte bereitet Seinen Thron.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Und Er richtet die Welt mit Gerechtigkeit; Recht spricht Er den Volksstämmen mit Geradheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'Jehovah ist dem Schwachen eine Burg, eine Burg zur Zeit der Drangsal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Und es vertrauen auf Dich, die Deinen Namen kennen, denn Du verlässest nicht, die Dir nachfragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Singt Psalmen dem Jehovah, Welcher wohnt zu Zion; sagt an unter den Völkern Seine Taten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Denn Er fragt nach dem Blute, Er gedenkt ihrer, vergißt nicht das Schreien der Elenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'Sei mir gnädig, Jehovah, siehe an mein Elend wegen meiner Hasser, Der Du von des Todes Toren mich emporhebst!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Auf daß all Dein Lob ich in den Toren der Tochter Zions erzähle, und frohlocke ob Deines Heils.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Die Völkerschaften sanken in den Graben, den sie gemacht; im Netz, das sie hehlings gelegt, hat sich ihr Fuß gefangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Jehovah ward kund; Er hat Recht geschafft; in Seiner Hände Werk hat der Ungerechte sich verstrickt. Higgajon, Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Die Ungerechten kehren zurück zur Hölle, alle Völkerschaften, die Gottes vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Denn nicht immerdar wird der Dürftige vergessen; noch vergeht immerfort der Elenden Hoffnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'Mache Dich auf, Jehovah! Nicht erstarke der Mensch! Es werden die Völkerschaften gerichtet vor Deinem Angesicht! Setze ihnen, o Jehovah, eine Unterweisung, laß die Völkerschaften wissen, daß sie Menschen sind. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Warum, Jehovah, stehst Du von ferne, verbirgst Dich zur Zeit der Drangsal?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Im Übermut jagt der Ungerechte dem Elenden nach; in den Tücken, die sie erdacht, laß sie erfaßt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Denn der Ungerechte rühmt sich der Gelüste seiner Seele, und der Geizige segnet, er lästert Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Der Ungerechte im Hochmut seines Antlitzes fragt nicht danach; â¬SEs ist kein Gott!â¬_ ist all sein Sinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Seine Wege sind verdreht alle Zeit. Zu hoch ihm gegenüber sind Deine Gerichte. All seine Dränger schnaubt er an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'Er spricht in seinem Herzen: Nicht werde ich wanken; von Geschlecht zu Geschlecht bin ich nicht im Übel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Sein Mund ist voll Verwünschung, Trug und Hinterlist. Mühsal und Unrecht ist unter seiner Zunge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Er sitzt im Hinterhalt der Höfe, insgeheim erwürgt er den Unschuldigen; seine Augen spähen nach den Unglücklichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'Insgeheim lauert er, wie der Löwe lauert unterm Blätterdach zu erhaschen den Elenden; er erhascht den Elenden, zieht ihn in sein Netz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Er duckt, er bückt sich, und unter seinen Mächtigen fällt der Unglückliche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'Er spricht in seinem Herzen: Gott hat es vergessen, hat Sein Angesicht verborgen, sieht es nimmermehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Mache Dich auf, Jehovah, hebe Deine Hand auf, o Gott! Vergiß nicht der Elenden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Warum soll der Ungerechte Gott lästern, in seinem Herzen sprechen: Du fragst nicht danach?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Du siehst es, denn Du blickst auf Mühsal und Verdruß, um mit Deiner Hand zu geben. Dir überläßt sich der Unglückliche. Dem Waisen bist Du ein Beistand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Zerbrich den Arm des Ungerechten; und beim Bösen: suche seine Ungerechtigkeit bis Du nichts mehr findest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Jehovah ist König ewiglich und immerfort; die Völkerschaften vergehen aus Seinem Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Der Elenden Sehnen hörst Du, Jehovah; Du bereitest ihr Herz; es horcht auf sie Dein Ohr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'Auf daß Du schaffest Recht, dem Waisen und dem Schwachen, daß der Mensch von der Erde nicht mehr trotze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, 'Dem Sangmeister. Von David. Ich verlasse mich auf Jehovah. Wie sprechet ihr zu meiner Seele: Flieht auf euren Berg wie ein Vogel!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Denn siehe, die Ungerechten spannen den Bogen, sie richten auf der Sehne ihren Pfeil, im Dunkeln zu schießen auf die, so geraden Herzens sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Wenn die Grundfesten umgerissen sind, was soll der Gerechte tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Jehovah ist im Tempel Seiner Heiligkeit; Jehovah, Sein Thron ist im Himmel! Seine Augen schauen, Seine Augenlider prüfen die Söhne des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Jehovah prüft den Gerechten und den Ungerechten, den aber, der Gewalttat liebt, haßt Seine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Auf Ungerechte läßt Er regnen Schlingen, Feuer und Schwefel; und der Wind des Glutsturmes ist ihres Bechers Anteil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Denn gerecht ist Jehovah; Er liebt Gerechtigkeit. Sein Angesicht schaut auf den Redlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, 'Dem Sangmeister auf der Oktave. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Rette, o Jehovah! Denn es ist aus mit dem Frommen. Denn geschwunden ist die Treue unter den Menschensöhnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Sie reden Eitles, der Mann mit seinem Genossen; mit glatter Lippe, mit Doppelherzen reden sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'Jehovah rotte aus all die glatten Lippen und die Zunge, die Großes redet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Die da sprechen: mit unserer Zunge machen wir uns mächtig, unsere Lippe ist mit uns. Wer ist Herr über uns?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Ob der Verheerung der Elenden, ob dem Jammer der Dürftigen, mache Ich Mich auf, spricht Jehovah, und schaffe dem Heil, den man anschnaubt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Die Reden Jehovahs sind reine Reden, Silber, geläutert im Tiegel der Erde, abgetrieben siebenmal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Jehovah, behüte Du sie, bewahre uns vor diesem Geschlecht in Ewigkeit. Ringsum ergehen Ungerechte sich, wo Niedertracht sich erhöhet unter den Söhnen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, 'Dem Sangmeister. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Wie lange, Jehovah, willst Du mein vergessen immerdar? Wie lange Dein Ange- sicht vor mir verbergen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Wie lange stelle ich Ratschläge an in meiner Seele, habe Gram in meinem Herzen täglich? Wie lange erhöht sich über mich mein Feind?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'Blicke her, antworte mir, Jehovah, mein Gott, erleuchte meine Augen, daß ich nicht zum Tod entschlafe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Daß nicht mein Feind sage: Ich habe ihn übermocht, meine Dränger frohlocken, daß ich wanke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'Ich aber vertraue auf Deine Barmherzigkeit, mein Herz frohlockt in Deinem Heile. Jehovah singe ich, daß Er mir vergolten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, 'Dem Sangmeister. Von David. Der Thor spricht in seinem Herzen: Es ist kein Gott! Sie verderben, machten greulich ihr Tun. Da ist keiner, der Gutes tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Jehovah schaut vom Himmel auf des Menschen Söhne, daß Er sehe, ob einer verständig sei, nach Gott frage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Alles ist abgewichen; allesamt sind sie unnütz! Da ist keiner, der Gutes tue, auch nicht einer!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Wissen nicht alle, die Unrecht tun, die mein Volk auffressen, wie man Brot ißt, aber nicht zu Jehovah rufen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Dort schauern sie mit Schauern; denn Jehovah ist im Geschlecht der Gerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Ihr beschämt des Elenden Rat, daß Jehovah ist seine Zuversicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'Wer gibt aus Zion das Heil Israels? Wenn Jehovah die Gefangenen Seines Volkes zurückführt, wird Jakob frohlocken, und Israel fröhlich sein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, 'Jehovah, wer darf weilen in Deinem Zelte, wer wohnen auf dem Berg Deiner Heiligkeit?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Wer untadelig wandelt und tut Gerechtigkeit, und redet Wahrheit in seinem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'Wer nicht verleumdet mit seiner Zunge, seinem Genossen nichts Böses tut, nicht Schmähung trägt wider seinen Nächsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'In dessen Augen verächtlich ist der Verworfene, der aber ehret die, so Jehovah fürchten, der zum eigenen Bösen schwört, und ändert es nicht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'Sein Silber nicht gibt er auf Wucher, und nimmt kein Geschenk wider den Unschuldigen. Wer solches tut, wanket nicht ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, 'Michtham Davids. Behüte mich, Gott, denn ich verlasse mich auf Dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Ich spreche zu Jehovah: Du bist mein Herr, mein Gutes reicht nicht an Dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'An den Heiligen, die im Lande sind, und an den Herrlichen, an ihnen habe ich all meine Lust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Sie mehren ihre Schmerzen, einem anderen eilen sie nach. Nicht gieße ich ihre Trankopfer von Blut, und trage ihre Namen nicht auf meinen Lippen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Jehovah, mein Anteil bist Du am Teile und mein Becher; Du erhältst mein Los.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Mein Los ist mir aufs Lieblichste gefallen, ja, mein Erbe ist hold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Jehovah segne ich, Der mich beraten hat, ja, in den Nächten züchtigen mich meine Nieren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Jehovah habe ich beständig vor mich gestellt. Weil Er mir zur Rechten ist, wanke ich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Darum ist fröhlich mein Herz, und frohlockt meine Herrlichkeit; ja, mein Fleisch wohnt in Sicherheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Denn nicht läßt Du in der Hölle meine Seele, Deinen Heiligen gibst Du nicht hin, die Verwesung zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Du machst kund mir des Lebens Pfad, Fülle der Fröhlichkeit ist vor Deinem Angesicht, Lieblichkeit in Deiner Rechten immerdar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, 'Ein Gebet Davids. Höre die Gerechtigkeit, Jehovah, horch auf meinen Angstschrei; nimm zu Ohren mein Gebet, aus Lippen ohne Trug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Von Deinem Angesicht gehe aus mein Gericht! Deine Augen erschauen das Gerade.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Du prüfst mein Herz, suchst es heim bei Nacht, läuterst mich, findest nichts; es ist mein Sinnen, daß mein Mund nicht übertrete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Bei der Menschen Tun hüte ich mich mit dem Worte Deiner Lippen, vor den Pfaden der Räuber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Ich erhielt meine Schritte in Deinen Geleisen, daß nicht wankten meine Tritte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Ich rufe zu Dir, denn Du antwortest mir, o Gott. Neige Dein Ohr mir zu, höre auf meine Rede!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Mach wundersam Deine Barmherzigkeit gegen die, so auf Dich sich verlassen, Der Du rettest mit Deiner Rechten von denen, so wider mich aufstehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Behüte mich wie den Augapfel, des Auges Tochter, verbirg mich im Schatten Deiner Flügel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'Vor den Ungerechten, die mich verheeren, vor den Feinden, die wider meine Seele mich umringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Sie schließen sich ein in ihr Fett, mit ihrem Munde reden sie im Hochmut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Nun umgeben sie unsere Tritte, ihre Augen richten sie auf uns, zur Erde uns zu strecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Dem Löwen gleichen sie, der zu zerfleischen lechzt, und dem jungen Löwen, der in Verstecken sitzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Mache Dich auf, Jehovah, tritt ihm vor das Angesicht, beuge ihn nieder, befreie von dem Ungerechten meine Seele mit Deinem Schwert;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Von den Leuten Deiner Hand, Jehovah, von den Leuten der Zeitlichkeit, deren Teil im Leben ist, und mit Deinem Schatze füllst Du ihren Bauch; die Söhne werden gesättigt, und sie hinterlassen ihren Kindlein ihr Übriges,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Ich aber will Dein Angesicht schauen in Gerechtigkeit, will, wenn ich erwache, mich an Deinem Abbild sättigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, 'Dem Sangmeister. Von dem Knechte Jehovahs, von David, der dem Jehovah die Worte dieses Liedes geredet am Tage, da ihn Jehovah aus der Hand aller seiner Feinde und aus Sauls Hand errettet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Innigst lieb habe ich Dich, Jehovah, meine Stärke!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Jehovah, mein Hort, meine Feste und mein Befreier, mein Gott, mein Fels, auf den ich mich verlasse, mein Schild und Horn meines Heils, meine Burg!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Ich rufe an den Gelobten, Jehovah, und ich werde von meinen Feinden gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'Stricke des Todes umfingen mich, und Bäche Belials verstörten mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'Stricke der Hölle umgaben mich, des Todes Fallstricke kamen mir entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'In meiner Drangsal rufe ich zu Jehovah, und schreie auf zu meinem Gott; Er hört von Seinem Tempel meine Stimme, und mein Angstschrei kommt vor Ihn in Seine Ohren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Und es schwankt und erbebt die Erde, und der Berge Grundfesten zittern und schwanken; denn Er entbrannte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Rauch stieg auf von Seiner Nase, und Feuer fraß aus Seinem Mund, Glühkohlen brannten aus Ihm hervor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'Und Er neigte die Himmel und kam herab, und Wolkendunkel unter Seinen Füßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Und Er fuhr auf dem Cherub und flog, und schwebte auf den Flügeln des Windes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Er setzt Finsternis zu Seiner Hülle, Seine Hütte ringsum war der Wasser Finsternis, dichte Wolken des Dunstkreises.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Vom Glanze vor Ihm zogen vorüber Seine dichten Wolken, Hagel und feurige Glühkohlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'Und es donnerte Jehovah in den Himmeln, und der Höchste gab Seine Stimme: Hagel und feurige Glühkohlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'Und Er sandte Seine Pfeile und zerstreute sie, und der Blitze viel, und verwirrte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Und der Wasser Flußbette wurden gesehen, und die Grundfesten der Welt aufgedeckt von Deinem Drohen, Jehovah, vom Odem des Hauches Seiner Nase.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Er sandte aus von der Höhe, und holte mich und zog mich aus vielen Wassern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Er errettete mich von meinem starken Feind, und von meinen Hassern, denn sie waren zu gewaltig für mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'Am Tage meiner Not kamen sie wider mich; doch ward Jehovah meine Stütze;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Und Er brachte mich heraus ins Weite; Er riß mich heraus, denn Er hatte Lust an mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'Jehovah vergilt mir nach meiner Gerechtigkeit; nach meiner Hände Lauterkeit gibt Er mir zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Denn ich hielt Jehovahs Wege, und war nicht gottlos wider meinen Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'Denn alle Seine Rechte sind vor mir, und Seine Satzungen tue ich nicht weg von mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Und ich bin untadelig bei Ihm, und hüte mich vor meiner Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Und Jehovah gibt mir wieder nach meiner Gerechtigkeit, nach meiner Hände Lauterkeit vor Seinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'Mit dem Heiligen bist Du heilig, und mit dem untadeligen Manne bist Du untadelig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Mit dem Lauteren bist Du lauter und mit dem Krummen bist Du verdreht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Denn das elende Volk rettest Du, und erhöhte Augen erniedrigst Du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'Denn meine Lampe erleuchtest Du, Jehovah, mein Gott, Du läßt glänzen meine Finsternis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Denn mit Dir durchlaufe ich Kriegshaufen, und mit meinem Gotte überspringe ich die Mauer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Gott untadelig ist Sein Weg; geläutert ist die Rede Jehovahs, ein Schild ist Er allen, die auf Ihn sich verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Denn wer ist Gott außer Jehovah? Und wer ein Fels ohne unsern Gott?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Der Gott, Der mich mit Tapferkeit umgürtet und macht meinen Weg untadelig,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Der macht meine Füße gleich denen der Hindinnen, und mich auf meine Höhen stehen läßt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Der meine Hand lehrt den Streit, daß meine Arme den ehernen Bogen niederdrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Und gibst mir den Schild Deines Heils, und Deine Rechte unterstützt mich, und Deine Demütigung mehrt mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Weit machst Du meine Schritte unter mir, daß meine Knöchel nicht gleiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Nachsetzen will ich meinen Feinden und sie erreichen, und nicht zurückkehren, bis ich sie weggetilgt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Zerschmettern will ich sie, daß sie nicht mehr aufstehen; sie sollen unter meine Füße fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'Und Du umgürtest mich mit Tapferkeit zum Streite, Du läßt, die wider mich aufstehen, sich krümmen unter mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Und gibst mir meiner Feinde Nacken, und meiner Hasser, sie vertilge ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Sie schreien auf, und es ist kein Retter, zu Jehovah, und Er antwortet ihnen nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Und ich zermalme sie wie Staub vor dem Winde; wie den Kot der Gassen leere ich sie aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Du befreist mich von des Volkes Hadern, Du setzest mich zum Haupt der Völkerschaften; ein Volk, das ich nicht kannte, dienet mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Nach dem Hören des Ohrs hören sie auf mich; des Auslands Söhne huldigen mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Des Auslands Söhne welken hin, und zittern hervor aus ihren Schlössern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Jehovah lebt, und gesegnet sei mein Fels, und erhöhet der Gott meines Heils.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'Der Gott, Der mir Rache gibt, und Völker unter mich zwingt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Der mich von meinen Feinden befreit, ja über die, so wider mich aufstehen, mich erhöht, mich vom Manne der Gewalttat errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'Darum will ich Dich bekennen, Jehovah, unter den Völkerschaften und Psalmen singen Deinem Namen. Der groß macht das Heil Seines Königs, und Barmherzigkeit tut Seinem Gesalbten, dem David und Seinem Samen in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, 'Dem Sangmeister. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Die Himmel erzählen Gottes Herrlichkeit und Seiner Hände Werk sagt an die Feste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Der Tag läßt dem Tage hervorquellen die Rede, und Nacht zeigt an der Nacht die Kunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Nicht Rede ist es, es sind nicht Worte, nicht wird ihre Stimme gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'In alles Land geht aus ihre Schnur, und an der Welt Ende ihre Worte; der Sonne setzt Er darinnen das Zelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Und wie ein Bräutigam kommt sie hervor aus ihrem Gemach, freut sich wie ein Held zu laufen die Bahn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Ihr Ausgang ist vom Ende der Himmel, und ihr Umlauf bis zu deren Enden; und nichts ist vor ihrer Glut verborgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'Das Gesetz Jehovahs ist untadelig, es erquickt die Seele; das Zeugnis Jehovahs ist wahrhaftig, es macht den Einfältigen weise.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'Die Verordnungen Jehovahs sind gerade, machen fröhlich das Herz; das Gebot Jehovahs ist lauter, erleuchtet die Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'Die Furcht Jehovahs ist rein und besteht immerfort. Die Gerichte Jehovahs sind Wahrheit, allesamt gerecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Sie sind mehr zu begehren denn Gold und viel geläutertes Gold, und süßer denn Honig und Honigseim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'Auch wird Dein Knecht gewarnt durch sie, und im Halten derselben ist viel Belohnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Wer sieht ein die Verirrungen? Mache mich frei von den verborgenen Fehlern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Auch von den Vermessungen halte Deinen Knecht zurück, daß sie über mich nicht herrschen. Dann werde ich untadelig und unschuldig von vieler Übertretung sein. Laß die Reden meines Mundes und das Sinnen meines Herzens wohlgefällig sein vor Dir, Jehovah, mein Fels und mein Erlöser!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, 'Dem Sangmeister. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Jehovah antworte dir am Tage der Drangsal! Der Name des Gottes Jakobs hebe dich empor!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Er sende dir Beistand aus dem Heiligtum, und unterstütze dich aus Zion!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Er gedenke aller deiner Speiseopfer, und dein Brandopfer sei fett. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Er gebe dir nach deinem Herzen, und erfülle alle deine Ratschläge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Lobsingen wollen wir ob Deines Heils, und das Banner erheben im Namen unseres Gottes. Jehovah erfülle dir all deine Bitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Nun erkenne ich, daß Jehovah Seinen Gesalbten rettet, daß Er ihm antwortet aus den Himmeln Seiner Heiligkeit, durch die Machttaten des Heils Seiner Rechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Diese gedenken der Streitwagen und jene der Rosse, wir aber des Namens Jehovahs, unseres Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Jene krümmen sich und fallen, wir aber machen uns auf und stehen fest. Jehovah, rette! Der König antworte uns am Tage, da wir rufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, 'Dem Sangmeister. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Jehovah, in Deiner Stärke ist fröhlich der König, und wie frohlockt er so sehr in Deinem Heil!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Seines Herzens Sehnen hast Du ihm gegeben, und den Wunsch seiner Lippen ihm nicht vorenthalten! Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Denn Du kommst ihm zuvor mit Segnungen des Guten, und setzest eine Krone feinen Goldes auf sein Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Leben erbat er von Dir, Du hast es ihm gegeben, Länge der Tage ewig und immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Groß ist seine Herrlichkeit in Deinem Heil; Majestät und Ehre legst Du auf ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Denn Du machst ihn zum Segen immerfort, und erheiterst ihn mit Fröhlichkeit vor Deinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Denn der König vertraut auf Jehovah, und in des Allerhöchsten Barmherzigkeit wird er nicht wanken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Deine Hand findet alle Deine Feinde, Deine Rechte trifft die, so Dich hassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Du setzest sie wie einen Ofen des Feuers zur Zeit deines Angesichts. In Seinem Zorne verschlingt sie Jehovah, und Feuer frißt sie auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Ihre Frucht wirst von der Erde Du zerstören, ihren Samen von den Söhnen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Denn wider Dich spannten sie aus das Böse, haben Tücke sich ausgedacht, nichts haben sie vermocht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Denn Du setzest wider sie die Schulter, Du zielst mit Deiner Sehne auf ihr Angesicht. Erhöhe Dich, Jehovah, in Deiner Stärke; so singen und lobpreisen wir Deine Macht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, 'Dem Sangmeister auf die â¬SHindin der Morgenröteâ¬_. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'Mein Gott, mein Gott, warum hast Du mich verlassen? Bist fern von meinem Heil, von den Worten meiner Klage?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Mein Gott, ich rufe am Tag und Du antwortest nicht, und des Nachts, und bin nicht stille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'Du aber bist der Heilige, Du wohnst im Lobe Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'Auf Dich vertrauten unsere Väter, sie vertrauten, und Du befreitest sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Sie schrien zu Dir, und sie entrannen, auf Dich vertrauten sie und wurden nicht beschämt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Ich aber bin ein Wurm und kein Mann, die Schmach der Menschen, und vom Volke verachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Alle, die mich sehen, verlachen mich, sperren die Lippen auf, schütteln das Haupt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Er übergebe sich dem Jehovah, Der befreie ihn; Er errette ihn, denn Er hat Lust an ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Denn Du ließest aus dem Mutterleibe mich hervorbrechen. Du warst meine Zuversicht an meiner Mutter Brüsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Auf Dich bin ich geworfen aus dem Mutterschoß; von meiner Mutter Leibe an bist Du mein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Entferne Dich nicht von mir; denn Drangsal ist nah, denn keiner ist da zum Beistand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Mich haben viele Farren umgeben, Baschans Gewaltige haben mich umringt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Sie sperrten ihren Mund auf wider mich; ein zerfleischender und brüllender Löwe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Wie Wasser bin ich ausgeschüttet, alle meine Gebeine sind zertrennt. Wie Wachs ist mein Herz, es zerschmolz in meiner Eingeweide Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Wie ein Scherben ist meine Kraft vertrocknet, und meine Zunge klebt mir an dem Gaumen; und in den Staub des Todes hast Du mich hinabgelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Denn Hunde haben mich umgeben, der Bösen Rotte mich umringt; sie haben Hände und Füße mir durchbohrt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Ich zähle all meine Gebeine; sie blicken, sie sehen auf mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Sie teilen meine Kleider unter sich, und werfen über mein Gewande das Los.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Aber Du, Jehovah, sei nicht fern! Du, meine Stärke, stehe mir schleunig bei!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Errette vom Schwerte meine Seele, und aus der Gewalt des Hundes meine einzige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Rette mich von des Löwen Rachen und von des Einhorns Hörnern antworte mir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Ich will erzählen Deinen Namen meinen Brüdern, inmitten der Versammlung will ich Dich loben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Ihr, die ihr Jehovah fürchtet, lobet Ihn; aller Same Jakobs, verherrlicht ihn; es bange vor Ihm aller Same Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Denn nicht verachtet, noch verabscheut Er das Elend des Bedrückten, und verbirgt Sein Angesicht nicht vor ihm. Wenn er zu Ihm aufschreit, hört Er ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Von Dir ist mein Lob in großer Versammlung; meine Gelübde zahle ich vor denen, die Ihn fürchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Die Elenden sollen essen und satt werden. Jehovah sollen loben, die nach Ihm fragen. Es lebe euer Herz immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Gedenken sollen und zu Jehovah zurückkehren alle Enden der Erde und anbeten vor Dir alle Familien der Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Denn das Königtum ist Jehovahs, und Er herrscht über die Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Essen und Ihn anbeten sollen alle Feisten der Erde, vor Ihm sollen sich beugen alle, die in den Staub hinabfahren, und der, dessen Seele Er nicht am Leben erhält.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Ein Same, der Ihm dient, wird dem Herrn gezählt in das Geschlecht. Sie werden kommen und ansagen Seine Gerechtigkeit, einem Volke, das geboren wird, daß Er es getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, 'Jehovah ist mein Hirte, mir wird nichts mangeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Auf Auen des jungen Grüns läßt Er mich lagern, zu den Wassern der Ruhe leitet Er mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Er labt meine Seele, führt mich in Geleisen der Gerechtigkeit um Seines Namens willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Auch wann ich gehe im Tale des Todesschattens, fürchte ich nichts Böses; denn Du bist mit mir. Dein Stab und Deine Stütze, sie trösten mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Du richtest vor mir einen Tisch zu gegenüber meinen Drängern, Du salbst mein Haupt mit Öl, mein Becher läuft über.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Ja, Gutes und Barmherzigkeit werden mir folgen alle Tage meines Lebens, und ich werde wohnen im Hause Jehovahs in die Länge der Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, 'Die Erde ist Jehovahs, und ihre Fülle, die Welt, und die darauf wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Denn Er hat auf die Meere sie gegründet, und auf den Flüssen sie festgestellt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Wer wird hinaufgehen auf den Berg Jehovahs, und wer wird aufstehen am Orte Seiner Heiligkeit?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Wer unschuldige Hände hat und lauteren Herzens ist, der seine Seele nicht erhebt auf Eitles und nicht schwört zum Trug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Der wird empfangen Segen von Jehovah, und Gerechtigkeit vom Gotte seines Heils.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'Dies das Geschlecht, das Ihm nachfragt, das Dein Angesicht sucht, o Jakob. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Erhebt eure Häupter, ihr Tore, und erhebt euch, ihr ewigen Pforten, daß einziehe der König der Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Wer ist dieser König der Herrlichkeit? Jehovah, der Starke, der Held, Jehovah, der Held im Streite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Erhebt eure Häupter ihr Tore, und erhebt euch, ihr ewigen Pforten, daß einziehe der König der Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Wer ist Er, dieser König der Herrlichkeit? Jehovah der Heerscharen ist es. Er ist der König der Herrlichkeit. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, 'Zu Dir, Jehovah, erhebe ich meine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Mein Gott, auf Dich vertraue ich, laß mich nicht beschämt werden, laß meine Feinde nicht über mich jauchzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Auch werden nicht beschämt alle, die auf Dich hoffen; aber beschämt werden, die ohne Ursache treulos handeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Laß mich erkennen, Jehovah, Deine Wege, lehre mich Deine Pfade!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Laß mich einhertreten in Deiner Wahrheit, und lehre mich; denn Du bist meines Heiles Gott. Auf Dich hoffe ich den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Gedenke Deiner Erbarmungen und Deiner Barmherzigkeit, o Jehovah, denn sie sind von Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Der Sünden meiner Jugend und meiner Übertretungen gedenke nicht; nach Deiner Barmherzigkeit gedenke Du mein um Deiner Güte willen, Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Gut und gerade ist Jehovah, darum weist auf den Weg Er die Sünder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Er leitet die Elenden nach dem Recht und lehrt die Elenden Seinen Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'All die Pfade Jehovahs sind Barmherzigkeit und Wahrheit für die, so Seinen Bund und Seine Zeugnisse wahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Um Deines Namens willen, Jehovah, vergib meiner Missetat; denn ihrer ist viel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Wer ist der Mann, der Jehovah fürchtet? Ihm weiset Er den Weg, den er wählen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Im Guten herbergt Seine Seele und das Land besitzt Sein Same.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Das Geheimnis Jehovahs ist für die, so Ihn fürchten, und Seinen Bund läßt Er sie wissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Meine Augen sind beständig auf Jehovah, denn aus dem Netze zieht Er meine Füße heraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Wende Dich zu mir und sei mir gnädig; denn einsam bin ich und elend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Die Bedrängnisse meines Herzens erweitern sich, führe mich heraus aus meinen Ängsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Siehe an mein Elend und meine Mühsal, und verzeihe all meine Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Sieh meine Feinde, daß ihrer sind viele, und mit gewalttätigem Hasse hassen sie mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Behüte meine Seele und errette mich, daß ich nicht beschämt werde; denn auf Dich verlasse ich mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Rechtschaffenheit und Redlichkeit bewahren mich; denn auf Dich hoffe ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'O Gott, erlöse Israel aus allen seinen Drangsalen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, 'Jehovah, richte mich; denn ich wandle in meiner Rechtschaffenheit und vertraue auf Jehovah, ich gleite nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Jehovah, prüfe mich und versuche mich, läutere meine Nieren und mein Herz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Denn Deine Barmherzigkeit ist vor meinen Augen, und in Deiner Wahrheit wandle ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Ich sitze nicht mit eitlen Leuten, und gehe nicht ein mit den Hehlern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Ich hasse der Bösen Versammlung, und mit den Ungerechten sitze ich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'Ich wasche in Unschuld meine Hände, und umziehe Deinen Altar, Jehovah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'Um hören zu lassen die Stimme des Bekennens und all Deine Wunder zu erzählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Ich habe lieb, Jehovah, die Wohnstätte Deines Hauses und den Ort, da Deine Herrlichkeit wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Raffe meine Seele nicht mit den Sündern hin, noch mit den Männern des Blutes mein Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'In deren Händen Tücke ist, und deren Rechte von Geschenken voll ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Ich aber wandle in meiner Rechtschaffenheit; erlöse mich und sei mir gnädig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Mein Fuß steht in der Geradheit; ich will Jehovah segnen in den Versammlungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, 'Jehovah ist mein Licht und mein Heil. Vor wem sollte ich mich fürchten? Jehovah ist meines Lebens Stärke. Vor wem sollte mir grauen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Wenn Bösewichter sich mir nahen, mein Fleisch zu fressen, meine Dränger und meine Feinde, so straucheln und fallen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Wenn sich ein Heer wider mich lagert, so fürchtet sich doch mein Herz nicht, und wenn der Streit ersteht wider mich, vertraue ich darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Eins bitte ich von Jehovah, das will ich suchen: Daß ich wohne im Hause Jehovahs alle Tage meines Lebens, zu schauen die Lieblichkeit Jehovahs, und früh zu besuchen Seinen Tempel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Denn Er deckt mich zu in Seiner Hütte am bösen Tage, Er verbirgt mich in der Heimlichkeit Seines Zeltes, Er erhöht mich auf den Felsen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'Und nun erhöht Er mein Haupt über meine Feinde rings umher. Und ein Hallopfer opfere ich in Seinem Zelt, singe Ihm und lobpreise Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Jehovah, höre meine Stimme, wenn ich rufe, und sei mir gnädig und antworte mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Dir sagt mein Herz: Suchet mein Angesicht; Dein Angesicht, Jehovah, will ich suchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Verbirg nicht Dein Angesicht vor mir, weise nicht ab im Zorn Deinen Knecht. Du bist mein Beistand, gib mich nicht dahin, verlaß mich nicht, Gott meines Heils!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Denn mein Vater und meine Mutter verlassen mich, aber Jehovah nimmt mich auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Jehovah, weise mir Deinen Weg, und führe mich auf dem geraden Pfad um meiner Gegner willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Gib mich nicht in den Willen meiner Dränger! Denn Zeugen der Lüge stehen auf wider mich, und der, so Gewalttat schnaubt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Dürfte ich doch glauben, die Güte Jehovahs zu sehen im Lande der Lebendigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Hoffe auf Jehovah, sei stark, und dein Herz sei unverzagt und hoffe auf Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'Zu Dir rufe ich, Jehovah; mein Fels, schweige nicht stille gegen mich; auf daß nicht, wenn Du schweigst gegen mich, ich denen gleiche, die in die Grube hinabfahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Höre auf die Stimme meines Flehens, wenn ich zu Dir schreie, wenn ich aufhebe meine Hände zum Sprechort Deines Heiligtums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Ziehe mich nicht hin mit den Ungerechten und denen, so Unrecht tun, die Frieden reden mit ihren Genossen, und Böses ist in ihrem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Gib ihnen nach ihrem Tun und nach dem Bösen ihres Handelns, gib ihnen nach ihrer Hände Werk, gib ihnen ihre Vergeltung zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Weil sie nicht verstehen Jehovahs Tun und das Werk Seiner Hände, reiße Er sie nieder und baue sie nicht auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Gesegnet sei Jehovah, daß Er auf die Stimme meines Flehens hörte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Jehovah ist meine Stärke und mein Schild. Auf Ihn vertraut mein Herz, und mir wird geholfen und mein Herz jauchzt, und ich will Ihn mit meinem Lied bekennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Jehovah ist ihre Stärke, und die Feste des Heils Seines Gesalbten ist Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'Hilf Deinem Volke, und segne Dein Erbe, und weide sie und trage sie in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, 'Bringt her Jehovah, ihr Söhne Gottes, bringt her Jehovah Herrlichkeit und Stärke!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Bringt her Jehovah die Herrlichkeit Seines Namens, betet an Jehovah in der Pracht der Heiligkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Die Stimme Jehovahs ist auf den Wassern, der Gott der Herrlichkeit donnert, Jehovah auf vielen Wassern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Die Stimme Jehovahs ist mit Kraft; Jehovahs Stimme ist mit Ehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Die Stimme Jehovahs zerbricht die Zedern und Jehovah zerbricht die Zedern des Libanon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'Und Er läßt sie hüpfen wie ein Kalb; den Libanon und den Sirjon wie den Sohn der Einhörner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Die Stimme Jehovahs haut die Flammen des Feuers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Jehovahs Stimme erschüttert die Wüste, Jehovah erschüttert die Wüste Kadesch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Jehovahs Stimme macht die Hindinnen kreißen, und entblößt die Wälder. Und in Seinem Tempel sagt alles Herrlichkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Jehovah sitzt bei der Flut, und Jehovah sitzt als König in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Jehovah wird Seinem Volk Stärke geben, Jehovah wird Sein Volk im Frieden segnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, 'Ein Psalm. Lied zur Einweihung des Hauses. Von David.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Jehovah, ich erhöhe Dich, Du hast mich emporgezogen und ließest meine Feinde nicht fröhlich sein über mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Jehovah, mein Gott, ich schrie auf zu Dir, und Du hast mich geheilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Du brachtest, Jehovah, meine Seele aus der Hölle herauf, Du hast mich belebt vor denen, die in die Grube fuhren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Singet Psalmen dem Jehovah, ihr, Seine Heiligen, und bekennet das Andenken Seiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Denn einen Augenblick nur ist Er in Seinem Zorn, ein Leben in Seinem Wohlgefallen; am Abend kehrt Weinen ein, und am Morgen Lobpreisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Ich aber sprach in meiner Gelassenheit: Ich werde nicht wanken in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'Jehovah, in Deinem Wohlgefallen ließest Du mich stehen auf meinem Berg der Stärke, Du verbargst Dein Angesicht, ich ward bestürzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Zu Dir, Jehovah, rufe ich, und zu Jehovah flehe ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Was für Gewinn ist mein Blut, wenn ich zur Grube hinabsteige? Wird der Staub Dich bekennen, wird er Deine Treue ansagen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Jehovah höre und sei mir gnädig, sei Du, Jehovah, mein Beistand!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'In einen Reigen hast Du mir verwandelt meine Klage, den Sack mir aufgetan und mich mit Fröhlichkeit umgürtet; Auf daß Dir Psalmen singe die Herrlichkeit, und nicht stille werde. Jehovah, mein Gott, Dich will ich in Ewigkeit bekennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, 'Dem Sangmeister. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Auf Dich, Jehovah, verlasse ich mich, lasse nimmermehr mich beschämt werden! Befreie mich in Deiner Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Neige Dein Ohr zu mir, errette mich in Eile. Sei mir ein Fels der Stärke, zum Haus der Feste, mich zu retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Denn mein Hort und meine Feste bist Du. Und um Deines Namens willen führe und geleite mich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'Bring aus dem Netz mich heraus, das sie mir hehlings stellten; denn Du bist meine Stärke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'In Deine Hand bestelle ich meinen Geist. Du hast erlöst mich, Jehovah, Gott der Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Ich hasse, die auf nichtige Eitelkeiten halten, ich aber vertraue auf Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'Frohlocken will ich und fröhlich sein, ob Deiner Barmherzigkeit, daß Du mein Elend gesehen, und meine Seele in ihren Drangsalen erkannt hast;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Und mich nicht in Feindeshand überantwortet, und meine Füße im Weiten stehen ließest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Sei mir gnädig, Jehovah; denn ich bin in Drangsal; vor Unmut verschmachtet mein Auge, meine Seele und mein Leib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Denn das Leben ist vor Gram mir verzehrt und meine Jahre vor Seufzen; es strauchelt meine Kraft ob meiner Missetat, und meine Gebeine verschmachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'Vor all meinen Drängern bin ich eine Schmach geworden auch meinen Nachbarn sehr, und zum Schauer meinen Bekannten. Die mich draußen sehen, entfliehen vor mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Vergessen bin ich aus dem Herzen wie ein Toter, geworden wie ein verkommenes Geschirr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Denn vieler Gerede hörte ich, Bangen ringsumher, wie sie heimlich zusammen wider mich ratschlagen und darauf sinnen, mir die Seele zu nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'Ich aber traue auf Dich, Jehovah; spreche: Mein Gott bist Du!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'In Deiner Hand sind meine Zeiten! Errette mich aus der Hand meiner Feinde und derer, die mich verfolgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Dein Angesicht leuchte über Deinen Knecht. Hilf mir nach Deiner Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Jehovah, laß mich nicht beschämt werden, weil ich Dich anrufe. Die Ungerechten laß beschämt werden, gestillt werden in der Hölle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'Die lügenden Lippen lasse verstummen, die Freches reden wider den Gerechten in Übermut und Verachtung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Wie groß ist Deine Güte, die Du geborgen hast für die, so Dich fürchten, und tust an denen, die sich auf Dich verlassen vor den Söhnen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'In der Heimlichkeit Deines Angesichts verbirgst Du sie vor den Überhebungen des Mannes; in Deiner Hütte birgst Du sie vor der Zungen Hader.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Gesegnet sei Jehovah, daß Er wunderbar gemacht Seine Barmherzigkeit in der Stadt der Bedrängnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Ich aber sprach in meiner Eilfertigkeit: Ich bin entrückt aus Deinen Augen; doch Du hörtest meines Flehens Stimme, da ich zu Dir aufschrie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Liebet Jehovah, alle Seine Heiligen. Die Treuen bewahrt Jehovah und vergilt im Übermaß dem, der Übermut tut. Seid fest und euer Herz sei unverzagt, alle, die ihr auf Jehovah wartet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, 'Selig der, dem Übertretungen verziehen sind, dem die Sünde ist bedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Selig der Mensch, dem Jehovah die Missetat nicht zurechnet, und in dessen Geist kein Trug ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Denn da ich stille schwieg, alterten meine Gebeine bei meinem Stöhnen den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Denn Deine Hand war bei Tag und bei Nacht schwer auf mir, verwandelt ward mein Saft wie in des Sommers Dürre. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Ich tat Dir meine Sünde kund und bedeckte nicht meine Missetat. Ich sprach: Ich will Jehovah wegen meiner Übertretung bekennen, und Du verziehest die Missetat meiner Sünde. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Darum soll beten zu Dir jeder Heilige zur Zeit des Findens. Ja bei der Überflutung vieler Wasser werden sie ihn nicht berühren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Du bist mein Schirm, bewahrst vor Drangsal mich, mit Lobpreisung der Befreiung umgibst Du mich, Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Ich mache dich verständig und weise dir den Weg, den du gehen sollst. Ich will dir raten mit Meinem Auge über dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Seid nicht wie das Roß, wie das Maultier ohne Einsicht, denen man mit Zaum und Gebiß ihren Mund muß bändigen, wenn sie dir nicht nahen wollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Viel Schmerzen hat der Ungerechte; wer aber auf Jehovah traut, den umgibt Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Seid fröhlich in Jehovah und frohlocket, ihr Gerechten, und lobpreiset, alle, die geraden Herzens sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Lobpreiset Jehovah, ihr Gerechten, den Redlichen ziemet das Lob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Bekennt mit der Harfe den Jehovah, mit zehnsaitigem Psalter singet Ihm Psalmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Singt Ihm ein neues Lied, macht es gut mit Spielen im Jubelsang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Denn gerade ist Jehovahs Wort, und all Sein Tun in Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Er liebt Gerechtigkeit und Gericht, der Barmherzigkeit Jehovahs ist die Erde voll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Die Himmel sind gemacht durch Jehovahs Wort, und vom Hauche Seines Mundes all ihr Heer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Er faßt zusammen wie in einen Haufen des Meeres Wasser, Er gibt die Tiefen in Schatzkammern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Es fürchte sich vor Jehovah all die Erde; vor Ihm sei bange allen, die in der Welt wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Denn Er spricht, und es geschieht; Er gebeut, und es steht da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Jehovah macht zunichte den Rat der Völkerschaften, stößt um die Gedanken der Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Jehovahs Ratschluß steht in Ewigkeit, die Gedanken Seines Herzens für Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Selig die Völkerschaft, deren Gott Jehovah ist, das Volk, das Er Sich zum Erbe hat erwählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Vom Himmel blickt Jehovah, Er sieht alle Söhne des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Von der Wohnstätte Seines Sitzes erschaut Er alle, so auf Erden wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'Der ihr Herz bildet zumal, Der merkt auf all ihr Tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Dem König hilft nicht seine viele Streitmacht; der Held wird nicht errettet durch die viele Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Lug ist des Rosses Heil und durch seine viele Kraft läßt es nicht entrinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Siehe, Jehovahs Auge ist auf denen, so Ihn fürchten, die auf Seine Barmherzigkeit warten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'Daß ihre Seele Er vom Tod errette und sie am Leben erhalte in der Hungersnot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Unsere Seele wartet auf Jehovah, unser Beistand und unser Schild ist Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Denn in Ihm ist fröhlich unser Herz, denn wir vertrauen auf den Namen Seiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Jehovah, Deine Barmherzigkeit sei über uns, wie wir Deiner warten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, 'Von David, da er seine Gebärde verstellte vor Abimelech, und dieser ihn forttrieb, und er ging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'Ich will Jehovah segnen alle Zeit; Sein Lob soll beständig in meinem Munde sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Jehovahs rühme meine Seele sich; die Elenden sollen es hören und fröhlich sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Machet groß mit mir Jehovah, laßt uns erhöhen Seinen Namen allzumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Ich fragte nach Jehovah, und Er antwortete mir und errettete mich aus all meinem Bangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Sie blicken zu Ihm auf und strahlen. Und ihr Angesicht darf nicht erröten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Es rief dieser Elende, und Jehovah hörte ihn, und rettete ihn aus allen seinen Drangsalen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Jehovahs Engel lagert sich rings um die, so Ihn fürchten, und Er zieht sie heraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Schmecket und sehet, wie gut Jehovah ist. Selig der Mann, der auf Ihn sich verläßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Fürchtet Jehovah, ihr Seine Heiligen; denn denen, die Ihn fürchten, mangelt nichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Die jungen Löwen darben und hungern; aber denen, die nach Jehovah fragen, mangelt es an keinem Gut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Kommt, Söhne, höret mir zu, ich will euch die Furcht Jehovahs lehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Wer ist der Mann, der Lust hat am Leben, und die Tage liebt, Gutes zu sehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Bewahre deine Zunge vor Bösem und deine Lippen, daß sie nicht Trug reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Weiche ab vom Bösen und tue Gutes. Suche Frieden und setze ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Die Augen Jehovahs sind auf den Gerechten und Seine Ohren auf ihrem Angstschrei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Das Angesicht Jehovahs ist wider die, so Böses tun, daß Er ihr Gedächtnis ausrotte von der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Schreien jene, so hört Jehovah und errettet sie aus allen ihren Drangsalen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Jehovah ist denen nahe, die gebrochenen Herzens sind, und hilft denen, die einen zerschlagenen Geist haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Viel sind der Übel des Gerechten, aus allen aber errettet ihn Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Alle seine Gebeine hütet Er, daß keines ihm zerbrochen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Den Ungerechten tötet das Böse, und die den Gerechten hassen, werden schuldig. Jehovah löset die Seele Seiner Knechte ein, und alle, die auf Ihn sich verlassen, haben keine Schuld.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, 'Jehovah hadere mit meinen Haderern, und streite mit denen, die streiten wider mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Erfasse Tartsche und Schild und mache Dich auf, mir beizustehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'Ziehe hervor den Spieß und tritt dazwischen, meinen Verfolgern entgegen. Sprich zu meiner Seele: Dein Heil bin Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Beschämt und zuschanden werden die, so nach meiner Seele trachten; hinter sich müssen zurückweichen und erröten, die mir Böses ausdenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Sie müssen werden wie die Spreu vor dem Wind, und der Engel Jehovahs stoße sie hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Finsternis und Schlüpfrigkeit sei ihr Weg, und der Engel Jehovahs setze ihnen nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Denn ohne Ursache stellen sie mir hehlings den Graben ihres Netzes; ohne Ursache gruben sie wider meine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Verstörung komme über ihn, ohne daß er es weiß; ihn fange sein Netz, daß er hehlings gestellt; mit Verstörung falle er hinein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'Und meine Seele frohlockt in Jehovah, sie freut sich ob Seines Heils.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Alle meine Gebeine sprechen: Jehovah, wer ist wie Du, der errettet den Elenden von dem, der stärker ist, denn er; und den Elenden und Dürftigen von dem, so ihn ausplündert?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Es stehen Zeugen der Gewalttat auf. Sie fragen mich, was ich nicht weiß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Sie vergelten mir Böses für Gutes; daß sie meine Seele kinderlos machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'Aber ich, wenn sie erkrankten, zog den Sack an, demütigte mit Fasten meine Seele, und mein Gebet kehrte mir auf den Busen zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Wie für einen Genossen, einen Bruder, ging ich einher, bückte mich düster wie bei der Trauer um die Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Sie aber sind fröhlich, wenn ich hinke, und versammeln sich; die Lahmen, die ich nicht kenne, versammeln sich wider mich, sie zerreißen und sind nicht stille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'Bei den Heuchlern, die um Kuchen spotten, knirschen sie mit ihren Zähnen über mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Herr, wie lange willst Du zusehen? Bringe von ihrem Verstören meine Seele zurück, von den jungen Löwen mein einziges.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Ich will Dich bekennen in der großen Versammlung, vor gewaltigem Volke will ich Dich loben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Lasse nicht über mich fröhlich sein, die mir fälschlich Feind sind, nicht mit dem Auge winken, die mich hassen ohne Ursache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Denn nicht Frieden reden sie, und wider die Ruhigen im Lande erdenken sie Worte des Trugs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'Weit sperren sie ihren Mund auf wider mich, sie sagen Ha! Ha! unser Auge sieht es!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Du siehst es, Jehovah; schweige nicht stille, Herr, sei nicht fern von mir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Wache auf, erwache mir zum Gericht, mein Gott und Herr, zu meinem Hader!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Richte mich nach Deiner Gerechtigkeit, Jehovah, mein Gott, und laß sie nicht fröhlich sein über mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Nicht sollen sie in ihrem Herzen sagen: Ha, unser Wunsch! Sie sollen nicht sagen: Wir haben ihn verschlungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Sich schämen müssen und erröten allesamt, die ob meinem Übel fröhlich sind; Scham und Schande anziehen, die sich über mich groß machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'Es müssen lobpreisen und fröhlich sein, die Lust haben an meiner Gerechtigkeit, und beständig sprechen: Groß ist Jehovah, Der Lust hat am Frieden Seines Knechtes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'Und meine Zunge soll singen von Deiner Gerechtigkeit, alltäglich von Deinem Lob..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, 'Dem Sangmeister. Von David, dem Knechte Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Ein Spruch der Übertretung zu dem Ungerechten inmitten meines Herzens: Keine Furcht Gottes ist vor seinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Denn er schmeichelt sich in seinen Augen, daß er ausfinde seine Missetat, daß er sie hasse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Die Worte seines Mundes sind Unrecht und Trug, er unterläßt, verständig zu werden und Gutes zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Er denkt Unrecht auf seinem Lager, und stellt sich auf einen Weg, der gut nicht ist, und verschmäht nicht Böses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Jehovah, Deine Barmherzigkeit ist in den Himmeln, bis an die Ätherkreise Deine Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Wie die Berge Gottes ist Deine Gerechtigkeit, Deine Gerichte sind wie die große Tiefe. Du rettest, Jehovah, Menschen und Vieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Wie köstlich ist, Gott, Deine Barmherzigkeit, daß Söhne der Menschen sich verlassen auf den Schatten Deiner Flügel!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Sie schwelgen an der Fettigkeit Deines Hauses, und mit Deiner Wonnen Bach tränkest Du sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Denn bei Dir ist des Lebens Born, in Deinem Lichte sehen wir Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Breite Deine Barmherzigkeit über die, so Dich kennen, und Deine Gerechtigkeit über die, so geraden Herzens sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Laß nicht den Fuß des Übermuts über mich kommen; und nicht des Ungerechten Hand mich hinwegtreiben. Da sind gefallen, die Unrecht tun, sie sind ausgestoßen und vermögen nicht mehr aufzustehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, 'Entbrenne nicht ob den Bösen, ereifre dich nicht über die, so Verkehrtes tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Denn eilig wie Gras werden sie abgeschnitten, und welken wie das Grün des jungen Krautes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Traue auf Jehovah, und tue Gutes! Wohne im Land und nähre dich an Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'Ergötze dich an Jehovah, und Er wird dir geben die Bitten deines Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Befiehl Jehovah deinen Weg und traue auf Ihn, und Er wird es machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'Und Er bringt heraus wie ein Licht deine Gerechtigkeit, und dein Recht wie Mittagshelle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Sei still dem Jehovah und warte Seiner. Entbrenne nicht wider den, dem sein Weg gelingt, wider den Mann, der Tücke übt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Lasse ab vom Zorn und verlasse den Grimm; entbrenne nicht, daß du Böses tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Denn die, so Böses tun, werden ausgerottet, die aber auf Jehovah hoffen, werden das Land besitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Und noch um ein Kleines, so ist nicht mehr der Ungerechte; du betrachtest seinen Ort, und er ist nicht mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Die Demütigen aber werden das Land besitzen und sich ergötzen an dem vielen Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Der Ungerechte sinnet wider den Gerechten und knirscht mit seinen Zähnen über ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Der Herr lacht seiner; denn Er sieht, daß sein Tag kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Die Ungerechten ziehen das Schwert aus, und sie spannen ihren Bogen, den Elenden und Dürftigen zu fällen, zu schlachten, die auf geradem Wege sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'Ihr Schwert geht hinein in ihr eigen Herz, und ihre Bogen werden zerbrochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Das Wenige, das der Gerechte hat, ist besser, denn der Haufe vieler Ungerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Denn des Ungerechten Arme zerbrechen; aber den Gerechten erhält Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Der Herr kennt die Tage der Rechtschaffenen und ihr Erbe ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Sie werden nicht beschämt in der bösen Zeit, und werden gesättigt in den Tagen der Hungersnot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Denn die Ungerechten vergehen, und die Feinde Jehovahs werden alle wie der Fluren Pracht, sie werden alle wie der Rauch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Der Ungerechte borgt und erstattet nicht zurück, der Gerechte aber ist gnädig und gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Denn Seine Gesegneten besitzen das Land, und Seine Verfluchten werden ausgerottet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Des Mannes Schritte werden von Jehovah fest gestellt, an seinem Wege hat Er Lust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Fällt er, so wird er nicht weggeworfen; denn Jehovah erhält seine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Ich war jung, bin auch alt geworden, und nie sah ich verlassen den Gerechten, noch seinen Samen nach Brot suchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Alltäglich ist er gnädig und leiht, und sein Same ist zum Segen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Weiche ab vom Bösen, tue Gutes, und wohne ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Denn Jehovah liebt das Recht, und Seine Heiligen verläßt Er nicht. Sie sind behütet ewiglich; aber der Ungerechten Same wird ausgerottet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Die Gerechten besitzen das Land und wohnen darin immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Des Gerechten Mund sinnt Weisheit, und seine Zunge redet das Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'Das Gesetz Gottes ist in seinem Herzen, und seine Tritte gleiten nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Der Böse späht auf den Gerechten und sucht ihn zu töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'Jehovah verläßt ihn nicht in Seiner Hand, und läßt ihn nicht verdammen, wenn er gerichtet wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Hoffe auf Jehovah und halte Seinen Weg, daß Er dich erhöhe, auf daß du das Land besitzest, und du wirst die Ausrottung der Ungerechten sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Den Ungerechten sah ich trotzig sich spreizen wie den grünen Urwaldsbaum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'Und man ging vorüber, und siehe, er war nicht mehr; und ich suchte nach ihm, und er ward nicht gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Habe Acht auf den Untadeligen und siehe den Redlichen, denn das Ende für den Mann ist Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Die Übertreter werden allesamt vernichtet. Das Ende der Ungerechten ist, daß sie ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'Aber das Heil der Gerechten ist von Jehovah; Er ist ihre Stärke zur Zeit der Drangsal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'Jehovah steht ihnen bei und befreit sie; Er befreit sie von den Ungerechten und rettet sie; denn sie verlassen sich auf Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, 'Ein Psalm Davids. Zum Gedächtnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Jehovah, strafe mich nicht in Deiner Entrüstung, und züchtige mich nicht in Deinem Grimm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Denn Deine Pfeile fahren auf mich nieder, und Deine Hand fährt nieder auf mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Nichts Gesundes ist an meinem Fleisch ob Deinem Unwillen, und kein Frieden in meinen Gebeinen ob meiner Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Denn meine Missetaten gehen über mein Haupt. Wie eine schwere Last sind sie zu schwer für mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Es stinken eiternd meine Striemen ob meiner Narrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Ich bin gekrümmt und gar sehr niedergebeugt, düster gehe ich einher den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Denn meine Lenden sind voll Feuerbrands, und nichts Gesundes ist an meinem Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Erstarrt bin ich, und sehr zerstoßen, ich brülle vor dem Grollen meines Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'O Herr, vor Dir ist all mein Sehnen, und mein Seufzen ist Dir nicht verborgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Mein Herz pocht, meine Kraft verläßt mich, und meiner Augen Licht, auch das ist nicht mehr bei mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Meine Lieben und Genossen stehen meiner Plage gegenüber und meine Nächsten stehen von ferne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Und die mir nach der Seele trachten, legen Fallstricke, und die mein Übel suchen, reden Unheil und sinnen auf Trug den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Ich aber, wie ein Tauber, höre nicht, und wie ein Stummer, der seinen Mund nicht öffnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Und ich bin wie ein Mann, der nicht hört und keine Strafrede in seinem Munde hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Denn auf Dich, Jehovah, warte ich, Du wirst mir antworten, Herr, mein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Denn ich spreche: Laß sie nicht fröhlich sein über mich. Wenn mein Fuß wankt, machen sie sich groß wider mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Denn ich bin zum Sturze bereit, und mein Schmerz ist beständig vor mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Denn ich sage an meine Missetat, und härme mich ob meiner Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'Und meine Feinde sind am Leben, sie sind mächtig, und viel sind derer, die mich fälschlich hassen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Und welche Böses mir um Gutes vergelten, die sich wider mich setzen, weil ich dem Guten nachsetze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Verlasse mich nicht, Jehovah, mein Gott. Sei nicht fern von mir. Stehe mir schleunig bei, Herr, mein Heil!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, 'Dem Sangmeister für Jeduthun. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Ich sprach: Ich will hüten meine Wege, daß ich nicht sündige mit meiner Zunge, ich will im Zaume halten meinen Mund, während der Ungerechte vor mir ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Stumm war ich in Stille, schwieg vom Guten, und mein Schmerz war erregt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Mein Herz war heiß in meinem Innern. In meinem Sinnen brannte das Feuer, und ich redete mit meiner Zunge:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Tue mir, Jehovah, kund mein Ende und meiner Tage Maß, was es ist, laß mich erkennen, wie vergänglich ich bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Siehe, spannenlang gabst Du meine Tage, und meine Lebenszeit ist wie nichts vor Dir. Ein bloßer Hauch ist jeder Mensch hingestellt. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'Nur ein Bild geht der Mann dahin, um einen Hauch müht er sich ab. Er häuft auf und weiß nicht, wer es einsammelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Und nun, was soll ich hoffen? Ich harre Deiner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Errette mich von allen meinen Übertretungen. Setze mich nicht aus der Schmähung des Toren!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Ich bin verstummt, öffne den Mund nicht; denn Du hast es getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Nimm Deine Plage weg von mir. Ob dem Streiche Deiner Hand werde ich verzehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Züchtigst Du einen Mann mit Strafen ob der Missetat, so läßt Du sein Begehrenswertes wie die Motte zerschmelzen. Nur ein Hauch ist jeder Mensch. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Höre mein Gebet, Jehovah, nimm zu Ohren meinen Angstschrei, schweig nicht still zu meiner Träne! denn ein Fremdling bin ich bei Dir, ein Beisasse, wie alle meine Väter. Blicke hinweg von mir, daß ich erheitert werde, ehe daß ich hingehe und nicht mehr bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, 'Dem Sangmeister. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'Gehofft habe ich auf Jehovah, und Er neigte ich zu mir und hörte mein Schreien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'Und Er zog mich herauf aus der Grube des Tosens, aus kotigem Schlamm, und stellte meine Füße auf den Fels und festigte meine Tritte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Und gab ein neues Lied in meinen Mund, das Lob unseres Gottes. Viele sehen es und fürchten und trauen auf Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Selig der Mann, der auf Jehovah sein Vertrauen setzt, und nicht sich wendet zu Hoffärtigen, und zu solchen, die zu Falschem sich wegwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Vieles hast Du getan, Jehovah, mein Gott, Deine Wunder und Deine Gedanken gegen uns; nichts ist Dir gleichzustellen; will ich sie ansagen und reden: sie sind zu zahlreich sie zu zählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Am Schlachtopfer und Speiseopfer hast Du keine Lust; die Ohren hast Du mir aufgetan; Brandopfer und Sündopfer forderst Du nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'Da sprach ich: Siehe, ich komme; in der Rolle des Buches ist über mich geschrieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Nach Deinem Wohlgefallen zu tun, mein Gott, ist meine Lust; und Dein Gesetz ist inmitten meiner Eingeweide.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Ich habe Gerechtigkeit verkündet in großer Versammlung. Siehe, meinen Lippen habe ich nicht gewehrt. Du weißt es, Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Ich deckte nicht zu Deine Gerechtigkeit inmitten meines Herzens; von Deiner Treue und Deinem Heile sprach ich, Deine Barmherzigkeit und Deine Wahrheit verhehlte ich vor der großen Versammlung nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Hemme nicht, Jehovah, Deine Erbarmungen gegen mich. Laß Deine Barmherzigkeit und Wahrheit beständig mich bewahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Denn Böses ohne Zahl umfängt mich. Es haben meine Missetaten mich erreicht; und ich vermag nicht zu sehen. Zahlreicher sind sie, als die Haare auf meinem Haupt und mein Herz hat mich verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Laß Dir wohlgefallen, Jehovah, mich zu erretten! Jehovah, stehe mir schleunig bei!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Sich schämen müssen und erröten allzumal, die nach meiner Seele trachten, sie wegzuraffen; hinter sich zurückweichen und zuschanden werden, die an meinem Übel Lust haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Entsetzen müssen sich zur Belohnung ihrer Scham, die zu mir sagen: Ha! Ha!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Es sollen sich freuen und fröhlich sein, alle, die Dich suchen. Die, so Dein Heil lieben, sollen beständig sprechen: Groß ist Jehovah! Doch ich bin elend und dürftig. Der Herr gedenket mein. Mein Beistand und mein Befreier Du, verziehe nicht, o mein Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, 'Dem Sangmeister. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Selig der, welcher verständig handelt mit dem Armen. Am bösen Tag läßt ihn Jehovah entrinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Jehovah wird behüten und beleben ihn. Selig wird er auf der Erde, und Er wird ihn nicht geben in seiner Feinde Willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Jehovah unterstützt ihn auf dem Siechbette, Du kehrst um sein ganzes Lager in seiner Krankheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Ich sprach: Jehovah, sei mir gnädig und heile meine Seele; denn ich habe gesündigt wider Dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'Meine Feinde sprachen Böses wider mich: Wann wird er sterben und sein Name vergehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Und kommt einer, um zu sehen, so redet er Eitles; sein Herz bringt Unrecht zusammen. Er geht hinaus, draußen redet er es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Alle meine Hasser flüstern zusammen wider mich, wider mich erdenken sie mir Böses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Ein Wort Belials ergieße sich über ihn! Und wenn er liegt, so stehe er nicht wieder auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Auch der Mann, der mit mir in Frieden ist, dem ich vertraute, der mein Brot ißt, hebt hoch die Ferse wider mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'Du aber, Jehovah, sei mir gnädig, und richte mich auf, daß ich ihnen vergelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Daran erkenne ich, daß Du Lust an mir hast, daß mein Feind nicht jubelt über mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Und mich erhältst Du in meiner Rechtschaffenheit, und stellst mich vor Dein Angesicht in Ewigkeit. Gesegnet sei Jehovah, der Gott Israels, von Ewigkeit zu Ewigkeit. Amen und Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, 'Dem Sangmeister. Unterweisung für die Söhne Korachs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Wie der Hirsch lechzt nach Wasserbächen, so lechzt nach Dir, Gott, meine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Es dürstet meine Seele nach Gott, nach dem lebendigen Gott. Wann werde ich kommen und sehen Gottes Angesicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Meine Träne ward mein Brot bei Tag und bei Nacht, wenn man den ganzen Tag mir sagte: Wo ist dein Gott?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Ich gedenke daran und schütte aus meine Seele bei mir, denn ich zog hin in der Schar, ich wallte mit ihnen zum Hause Gottes, mit der Stimme der Lobpreisung und des Bekennens in der feiernden Menge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Was bist du niedergebeugt, meine Seele, und bist beunruhigt über mich? Warte auf Gott; denn noch werde ich ihm bekennen das Heil Seines Angesichtes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'O Gott, meine Seele ist niedergebeugt in mir, weil ich Dein gedenke von Jordans Landen her und den Charmonim, vom Berge Mizar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Abgrund ruft dem Abgrund bei der Stimme Deiner Wassergüsse; alle Deine Brandungen und Deine Wogen gehen über mich hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Am Tage gebietet Jehovah Seiner Barmherzigkeit und in der Nacht ist Sein Lied bei mir, ein Gebet zum Gott meines Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Ich spreche zu Gott, zu meinem Hort: Warum hast Du meiner vergessen? Warum muß ich düster dahingehen unter Feindes Druck?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Bei der Zermalmung in meinen Gebeinen schmähen mich meine Dränger, indem sie den ganzen Tag zu mir sagen: Wo ist dein Gott? Was bist du niedergebeugt, meine Seele, und was bist du beunruhigt über mich? Warte auf Gott; denn noch werde ich ihm bekennen, dem Heile meines Angesichts und meinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Richte mich, o Gott, und hadere meinen Hader mit der unheiligen Völkerschaft; von dem Mann des Trugs und der Verkehrtheit befreie mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Denn Du bist meiner Stärke Gott! Warum verwirfst Du mich? Warum muß ich düster wandeln unter des Feindes Druck?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Sende Dein Licht und Deine Wahrheit, daß sie mich führen und bringen mich herein zu dem Berge Deiner Heiligkeit, und zu Deinen Wohnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'Und ich hineingehe zum Altare Gottes, zum Gotte der Fröhlichkeit meines Frohlokkens, auf daß ich Dich bekenne auf der Harfe, o Gott, mein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Was bist du niedergebeugt, meine Seele, und was bist du beunruhigt über mich? Warte auf Gott; denn noch werde ich Ihm bekennen, dem Heil meines Angesichts und meinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, 'Dem Sangmeister. Eine Unterweisung für die Söhne Korachs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'O Gott, mit unseren Ohren haben wir es gehört, unsere Väter haben uns erzählt das Werk, das Du getan in ihren Tagen, in den Tagen der Vorzeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Du hast mit Deiner Hand die Völkerschaften ausgetrieben, und sie gepflanzt, Du hast den Volksstämmen Böses getan und sie fortgesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Denn nicht mit ihrem Schwert nahmen sie das Land ein, und nicht ihr Arm rettete sie, sondern Deine Rechte und Dein Arm und das Licht Deines Angesichts, weil Du an ihnen Wohlgefallen hattest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'Du Selbst bist es, mein König, Gott. Gebiete Jakobs Heil!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Durch Dich stoßen wir unsere Dränger nieder, durch Deinen Namen zertreten wir die, so wider uns aufstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Denn nicht auf meinen Bogen vertraue ich, und mein Schwert rettet mich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Denn Du rettest uns von unseren Drängern, und die uns hassen, machst Du beschämt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'In Gott rühmen wir uns den ganzen Tag, und Deinen Namen bekennen wir in Ewigkeit. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Gleichwohl verwarfst Du uns und ließest uns zuschanden werden, und zogst nicht in unseren Heeren aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Rückwärts ließest Du uns zurückkehren vor dem Dränger und es plünderten uns die, so uns haßten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Wie Schafe gabst Du uns dahin zum Fraß, und unter die Völkerschaften hast Du uns versprengt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Du hast Dein Volk verkauft nicht für Güter, und ihren Kaufpreis nicht gemehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Zur Schmach unseren Nachbarn hast du uns gesetzt, zum Gelächter und zum Schimpf vor denen rings um uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Zum Sprichworte setztest Du uns unter den Völkerschaften, zum Schütteln des Hauptes unter den Volksstämmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Den ganzen Tag ist meine Schande vor mir, und Scham bedeckt mein Angesicht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Vor der Stimme dessen, der schmäht und verhöhnt, vor dem Feinde und Rachgierigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'All das ist über uns gekommen, und doch vergaßen wir Dein nicht und handelten nicht lügnerisch an Deinem Bunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'Nicht wich unser Herz zurück hinter sich; noch neigte sich unser Tritt von Deinem Pfade.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Als Du zerschlugst uns am Orte der Drachen, und uns mit Todesschatten bedecktest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'So wir den Namen unseres Gottes vergessen, und unsere Hände zu einem fremden Gotte ausgebreitet haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Wird Gott dies nicht ergründen? Er kennt ja des Herzens Verheimlichtes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Denn um Deinetwillen werden wir den ganzen Tag erwürgt, man denkt unser als der Schafe zum Schlachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Wache auf! Warum schläfst Du, Herr? Erwache! Verwirf uns nicht für immerdar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Warum birgst Du Dein Angesicht, vergissest unser Elend und unsere Bedrükkung?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Denn es beugt sich unsere Seele zum Staube, und unser Bauch klebt an der Erde. Mache Dich auf, uns beizustehen! und erlöse uns um Deiner Barmherzigkeit willen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, 'Dem Sangmeister auf Schoschannim für die Söhne Korachs. Unterweisung. Ein Lied der Liebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Aufwallet mein Herz mit gutem Wort. Ich spreche, was ich dem Könige gemacht. Meine Zunge ist der Griffel eines eiligen Schreibers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Schöner bist Du, denn die Söhne des Menschen. Gnade ist ausgegossen über Deine Lippen. Darum hat Gott Dich ewiglich gesegnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'Gürte Dein Schwert auf Deine Hüfte, Du Held, in Deiner Majestät und Deiner Ehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Und in Deiner Ehre steig auf, fahre daher auf dem Wort der Wahrheit und der Sanftmut der Gerechtigkeit, und furchtbare Dinge wird Dir Deine Rechte weisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Geschärft sind Deine Pfeile, Völker fallen vor Dir, im Herzen Feinde des Königs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Dein Thron, o Gott, ist ewig und immerfort; ein Zepter der Geradheit ist das Zepter Deines Königreiches.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Du liebst Gerechtigkeit und hassest Ungerechtigkeit; darum hat Gott, Dein Gott, Dich mit Öl der Freude gesalbt vor Deinen Gefährten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Myrrhe und Aloe und Kassia alle Deine Gewänder; aus Palästen von Elfenbein machen Saitenspiele Dich fröhlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Töchter von Königen sind unter Deinen Köstlichen. In bestem Ophirgold steht die Königin zu Deiner Rechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'Höre, Tochter, und siehe und neige dein Ohr und vergiß dein Volk und das Haus deines Vaters!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'Und es wird der König sich sehnen nach deiner Schönheit; denn Er ist dein Herr, und beuge dich nieder vor Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Und Tyrus Tochter mit einem Geschenk! Die Reichen des Volkes flehen an Dein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'Gar herrlich ist die Tochter des Königs, innen aus Gold gewirkt ist ihr Anzug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'In Stickereien wird sie geleitet zum König, Jungfrauen hinter ihr her, ihre Genossinnen werden zu Dir hereingebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Sie werden geleitet mit Fröhlichkeit und Frohlocken, sie kommen in den Palast des Königs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'An Deiner Väter Stelle werden Deine Söhne sein, Du setzest sie zu Obersten über die ganze Erde. Gedenken will ich Deines Namens in jedem Geschlechte und Geschlecht, darum werden die Völker Dich bekennen in Ewigkeit und immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, 'Dem Sangmeister für die Söhne Korachs ein Lied auf Alamoth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Gott ist unsere Zuversicht und Stärke; ein Beistand erfunden in Drangsalen, mächtig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Darum fürchten wir uns nicht, wenn die Erde sich umwandelt, und die Berge wanken im Herzen der Meere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Deren Wasser toben, sie brausen auf; die Berge erbeben in deren Übermut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Es ist ein Fluß, dessen Bäche fröhlich machen die Stadt Gottes, das Heilige der Wohnungen des Allerhöchsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Gott ist in ihrer Mitte; sie wankt nicht, Gott steht ihr bei, wenn es sich zum Morgen wendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Es toben Völkerschaften, Königreiche wanken. Er gibt Seine Stimme hervor, es zerfließt die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Jehovah der Heerscharen ist mit uns; eine Burg ist uns der Gott Jakobs! Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Kommt, erschauet die Taten Jehovahs, Der Verwüstung setzet auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, 'Der die Kriege feiern läßt bis zum Ende der Erde, Der den Bogen zerbricht und die Spieße abschlägt, Der die Wagen verbrennt im Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Laßt ab und erkennt, daß Ich Gott bin; Ich will erhöht sein unter den Völkerschaften, Ich will erhöht sein auf Erden. Jehovah der Heerscharen ist mit uns, eine Burg ist uns der Gott Jakobs. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, 'Dem Sangmeister für die Söhne Korachs. Ein Psalm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Ihr Völker alle, klatschet in die Hände, jubelt zu Gott mit der Stimme der Lobpreisung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Denn Jehovah, der Allerhöchste, ist furchtbar, ein großer König über alle Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Er bezwingt Völker unter uns, und Volksstämme unter unsere Füße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Er hat uns unser Erbe auserwählt, Jakobs Stolz, den Er geliebt. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Hinauf steigt Gott mit Jubel, Jehovah mit der Stimme der Posaune.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Singt Psalmen unserem Gott, singt Psalmen; singt Psalmen unserem König, singt Psalmen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Denn König der ganzen Erde ist Gott, singt Ihm Psalmen verständig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Gott ist König über Völkerschaften, Gott sitzt auf dem Thron Seiner Heiligkeit. Der Völker Freiwillige haben sich versammelt, das Volk des Gottes Abrahams; denn Gottes sind der Erde Schilder; sehr erhöht ist Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, 'Ein Lied, ein Psalm für die Söhne Korachs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Groß ist Jehovah, und sehr zu loben in unseres Gottes Stadt, auf dem Berge Seiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Schön erstreckt sich der ganzen Erde Freude, der Berg Zion von den Seiten der Mitternacht, die Stadt des großen Königs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Gott ist in ihren Palästen bekannt als Burg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'Denn siehe, die Könige taten sich zusammen, sie gingen allesamt vorüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Sie sahen, so staunten sie, sie waren bestürzt, sie enteilten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Beben ergriff sie da, ein Kreißen wie die Gebärerin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Durch den Ostwind zerbrichst Du die Schiffe von Tharschisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Wie wir es gehört hatten, so sahen wir es in der Stadt Jehovahs der Heerscharen, in unseres Gottes Stadt; Gott festigt sie ewiglich. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Gott, wir bedenken Deine Barmherzigkeit inmitten Deines Tempels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Wie Dein Name, o Gott, so ist Dein Lob bis an die Enden der Erde. Voller Gerechtigkeit ist Deine Rechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Es sei fröhlich der Berg Zion, frohlocken sollen Judahs Töchter um Deiner Gerichte willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Ziehet um Zion, umringet es, zählt seine Türme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Und richtet euer Herz auf seine Vormauer, durchforscht seine Paläste, daß ihr es einem späteren Geschlechte erzählt, Daß dieser Gott ist unser Gott ewig und immerfort, Er geleitet uns bis zum Tode.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, 'Dem Sangmeister für die Söhne Korachs. Ein Psalm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'Hört dies, ihr Völker alle, nehmet zu Ohren alle Bewohner der Zeitlichkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Söhne des Menschen sowohl, als Söhne des Mannes, der Reiche und der Dürftige allzumal!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Mein Mund soll Weisheit reden und meines Herzens Sinnen Einsicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Zum Spruch neige ich mein Ohr, eröffne zur Harfe meine Rätsel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'Warum sollte ich in bösen Tagen fürchten, wenn meiner Fersen Missetat mich umgibt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'O die, so auf ihr Vermögen vertrauen, sich ihres vielen Reichtums rühmen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, 'Kann doch der Mann den Bruder nicht einlösen, noch Gott Sühnung für ihn geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'Zu kostbar ist ihrer Seele Lösegeld, daß er es muß unterlassen ewiglich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Auf daß er immerdar lebe und nicht den Graben sehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Denn er sieht, daß die Weisen sterben, der Dumme und der Tierische, sie vergehen allzumal, und lassen anderen ihr Vermögen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'In ihrem Inneren ist es, daß ihre Häuser seien ewiglich, ihre Wohnungen von Geschlecht zu Geschlecht; sie nennen den Boden nach ihrem Namen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'Und der Mensch verbleibt nicht in der Würde, dem Vieh gleicht er: sie gehen unter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Das ist ihr Weg: sie sind dumm, aber ihre Nachkommen haben Wohlgefallen an ihrem Munde. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Wie Kleinvieh legt man sie in die Hölle. Es weidet sie der Tod; und die Redlichen unterwerfen sie sich am Morgen. Und ihr Gebilde veraltet. Die Hölle ist ihr Wohnort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Gott aber löst meine Seele ein aus der Hölle; denn Er nimmt mich an. Selah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Fürchte dich nicht, wenn ein Mann reich wird, wenn die Herrlichkeit seines Hauses sich mehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Denn das alles nimmt er bei seinem Sterben nicht mit sich. Nicht steigt hinunter ihm nach seine Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'Mag er seine Seele segnen in seinem Leben, und mögen sie dich bekennen, wenn du dir gütlich tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'So kommt sie doch zu dem Geschlechte seiner Väter; nimmermehr werden diese das Licht sehen. Der Mensch, der in Würde ist und ohne Einsicht, ist gleich wie das Vieh, sie gehen unter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, 'Ein Psalm von Asaph. Der Gott, der Gott Jehovah, redet und ruft der Erde von der Sonne Aufgang bis zu ihrem Untergang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'Aus Zion strahlt der Schönheit Vollendung, Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Unser Gott kommt und schweigt nicht stille; Feuer frißt vor Ihm, und rings um Ihn stürmt es sehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Er wird rufen den Himmeln droben und der Erde, auf daß Er Seinem Volke Recht spreche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, 'Versammelt Mir Meine Heiligen, die über dem Opfer den Bund mit Mir geschlossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'Und die Himmel sagen an Seine Gerechtigkeit, denn Gott Selbst ist Richter. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Höre, mein Volk, und Ich will reden; Israel, Ich will gegen dich zeugen, Gott, dein Gott, bin Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Nicht rüge Ich dich ob deiner Opfer und deine Brandopfer sind beständig vor Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Ich will nicht Farren nehmen aus deinem Haus, Böcke aus deinen Hürden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Denn Mein ist alles Wild des Waldes, das Vieh auf Tausenden der Berge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Ich kenne alles Gevögel der Berge, und das Gewild des Feldes ist bei Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Sollte Ich hungern, Ich sagte es dir nicht; denn Mein ist die Welt und was sie füllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Soll Ich der Gewaltigen Fleisch essen und das Blut der Böcke trinken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Opfere Gott Bekennen, und erstatte dem Allerhöchsten deine Gelübde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'Und rufe Mich an am Tage der Drangsal, so reiße Ich dich heraus, und du sollst Mich verherrlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Und zu dem Ungerechten spricht Gott: Was ist es mit dir, daß du Meine Satzungen erzählst, und Meinen Bund in deinem Munde trägst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Und du hassest Zucht und wirfst Meine Worte hinter dich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Ersiehst du einen Dieb, so läufst du mit ihm, und mit den Ehebrechern ist dein Teil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Du entsendest deinen Mund zum Bösen, und Trug flicht deine Zunge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Du sitzest, redest wider deinen Bruder und wider deiner Mutter Sohn gibst du Verleumdung aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'Das tatest du, und Ich habe still geschwiegen, da meintest du, Ich sei wie du; doch Ich rüge dich und lege es zurecht vor deinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Betrachtet doch das, ihr, die ihr Gott vergesset, daß Ich euch nicht zerfleische und keiner errette.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Wer Bekenntnis opfert, der verherrlicht Mich, und wer den Weg zurichtet, den lasse Ich sehen das Heil Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, 'Dem Sangmeister. Ein Psalm von David;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Als Nathan, der Prophet, zu ihm kam, als er zu Bathscheba eingegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Gott, sei mir gnädig nach Deiner Barmherzigkeit und wisch aus meine Übertretungen nach Deinen vielen Erbarmungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Wasche mich wohl von meiner Missetat, und reinige mich von meiner Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Denn ich erkenne meine Übertretungen, und meine Sünde ist beständig vor mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'An Dir, an Dir allein habe ich gesündigt und getan, was böse ist in Deinen Augen, auf daß Du gerecht seiest, wenn Du redest, daß Du lauter seiest in Deinem Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Siehe, in Missetat ward ich geboren, und in Sünde empfing mich meine Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Siehe, Du hast Lust zu Wahrheit in den Nieren, und lässest mich erkennen Weisheit im Verborgenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Entsündige mich mit Ysop, und ich werde rein, wasche mich, und ich werde weißer denn Schnee.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Laß Freude und Fröhlichkeit hören mich, daß die Gebeine frohlocken, die Du zerschlagen hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Dein Angesicht birg vor meinen Sünden, wische aus alle meine Missetaten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Schaffe mir ein reines Herz, o Gott, und einen festen Geist erneue in meinem Inneren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Wirf mich nicht weg von Deinem Angesicht, und nimm den Geist Deiner Heiligkeit nicht von mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Gib mir zurück die Freude Deines Heils, und ein freiwilliger Geist erhalte mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Übertreter will ich Deine Wege lehren, und Sünder sollen zurückkehren zu Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Errette mich von Blutschuld, Gott, Gott meines Heils, daß meine Zunge lobpreise Deine Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Herr, öffne meine Lippen und mein Mund sagt an Dein Lob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Denn am Opfer hast Du keine Lust, daß ich es gäbe; Brandopfer gefällt Dir nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Opfer Gottes sind ein gebrochener Geist; ein gebrochenes und zerschlagenes Herz verachtest Du nicht, o Gott! Tue Zion wohl nach Deinem Wohlgefallen, baue die Mauern Jerusalems. Dann hast Du Lust an Opfern der Gerechtigkeit, an Brandopfer und ganzem Opfer. Dann läßt man Farren auf Deinem Altare aufgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, 'Dem Sangmeister. Eine Unterweisung von David.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Da Doeg, der Edomiter, kam, und Saul ansagte und sprach zu ihm: David ist in Achimelechs Haus gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Was rühmst du dich des Bösen, o Mächtiger? die Barmherzigkeit Gottes ist alle Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Unheil denkt deine Zunge, wie ein scharfes Schermesser tust du Trug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Du liebst Böses mehr denn Gutes; Lüge mehr denn gerecht reden. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'Du liebst des Verschlingens Worte alle, die Zunge des Trugs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Darum wird dich Gott zertrümmern auf immerdar, dich zerbrechen und dich aus dem Zelte hinraffen, entwurzeln aus dem Lande der Lebendigen. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Und sehen werden es die Gerechten und sich fürchten und lachen über ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Siehe den Mann, der Gott nicht zur Stärke setzte, der auf seinen vielen Reichtum vertraute, der stark war in seinem Unheil. Ich aber bin wie ein grünender Ölbaum in Gottes Haus, vertraue auf die Barmherzigkeit Gottes ewiglich und immerfort. Ich will Dich bekennen ewiglich, daß Du es getan, und hoffen auf Deinen Namen; denn gut bist Du vor Deinen Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, 'Dem Sangmeister auf Machalath. Eine Unterweisung von David.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Der Tor in seinem Herzen spricht: Es ist kein Gott! Verderblich, greulich ist die Verkehrtheit. Da ist keiner, der Gutes tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Gott schaut aus dem Himmel auf des Menschen Söhne, daß Er sehe, ob einer verständig sei, der nach Gott frage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Alles ist zurückgewichen; allzumal sind sie untüchtig! Da ist keiner, der Gutes tue, auch nicht einer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Wissen sie es nicht, die Unrecht tun, die Mein Volk auffressen, wie man Brot ißt, aber Gott nicht anrufen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'Da schauern sie mit einem Schauer, wo nichts zu schauern ist; denn Gott zersprengt die Gebeine der wider dich sich Lagernden. Du beschämst sie, denn Gott verschmäht sie. Wer gibt aus Zion das Heil Israels? Wenn Gott die Gefangenen Seines Volkes zurückbringt, wird Jakob frohlocken, Israel fröhlich sein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, 'Dem Sangmeister auf Saitenspielen. Eine Unterweisung von David.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Als die Siphiter kamen und sprachen zu Saul: Hat sich David nicht bei uns verborgen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'O Gott, rette mich durch Deinen Namen und sprich mir Recht durch Deine Macht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Gott, höre mein Gebet, und nimm zu Ohren die Reden meines Mundes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'Denn Fremde sind aufgestanden wider mich, und Trotzige trachten nach meiner Seele, weil sie Gott nicht vor sich setzen. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Siehe, Gott ist Beistand mir, der Herr ist unter denen, die meine Seele erhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Das Böse kehre zurück auf meine Gegner! Vertilge sie durch Deine Wahrheit! Freiwillig will ich Dir opfern, will bekennen Deinen Namen, Jehovah, denn er ist gut. Denn aus aller Drangsal errettest Du mich; und auf meine Feinde sieht mein Auge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, 'Dem Sangmeister für Saitenspiele. Eine Unterweisung Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Nimm zu Ohren, o Gott, mein Gebet, und verbirg Dich nicht vor meinem Flehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'Horche auf mich und antworte mir. In meinem Sinnen irre ich umher und stöhne,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Ob der Stimme meines Feindes, ob dem Zwängen des Ungerechten, denn sie erregen Unrecht über mich und grollen mir im Zorne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Mein Herz kreißet in mir; und Schrecken des Todes fallen über mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'Furcht und Beben kommen über mich, und Grausen hat mich bedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Und ich spreche: Wer gibt mir Fittiche wie der Taube, ich flöge hin, wo ich wohnete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Siehe, ferne würde ich entfliehen, in der Wüste würde ich übernachten. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Schleunigst würde ich entkommen vom Sturme des Windes, vom Wetter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Verschlinge, Herr, zerteile ihre Zunge; denn ich sehe Gewalttat und Hader in der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Sie gehen bei Tag und bei Nacht in ihr umher, auf ihren Mauern, und Unrecht und Mühsal ist in ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Unheil ist in ihrer Mitte, und nicht weicht von ihrer Straße Hinterlist und Trug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'Denn nicht ein Feind schmäht mich, das ertrüge ich; nicht der mich haßte, macht sich groß über mich, ich könnte mich vor ihm verbergen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'Du aber bist es, ein Mensch wie meinesgleichen, mein Leiter und mein Bekannter;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Die wir zusammen süße, heimliche Beratung pflogen und im Zuge zum Gotteshause wallten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Tod über sie! Laß sie lebendig in die Hölle hinabfahren; denn Böses ist in ihrem Aufenthalt, in ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Ich rufe zu Gott, und Jehovah wird mich retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Des Abends, des Morgens und des Mittags will ich klagen und jammern, und Er wird meine Stimme hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Er löst meine Seele ein im Frieden, daß sie mir nicht nahen; denn viele waren ihrer bei mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Gott wird es hören und sie demütigen, Der von Alters her sitzet, Selah; weil bei ihnen kein Wechsel ist, und sie Gott nicht fürchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Er hat seine Hände ausgestreckt wider die so friedlich mit ihm waren, hat seinen Bund entweiht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Sie machen glatt wie Butter seinen Mund, und es nähert sich sein Herz. Weicher denn Öl sind seine Worte, und sind gezückte Schwerter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'Wirf dein Anliegen auf Jehovah, und Er wird für dich sorgen, und den Gerechten nicht wanken lassen in Ewigkeit. Aber Du, Gott, wirst sie in den Brunnen des Grabens hinabbringen. Die Männer des Bluts und des Trugs werden ihre Tage nicht zur Hälfte bringen. Ich aber vertraue auf Dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, 'Dem Sangmeister nach â¬SJonatholem rechokimâ¬_. Ein Goldlied von David, da ihn die Philister zu Gath ergriffen hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Sei mir gnädig, o Gott; denn der Mensch schnappt nach mir. Den ganzen Tag streitend will er mich unterdrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Den ganzen Tag schnappen meine Gegner; denn viele streiten wider mich in der Höhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'Den Tag, da ich mich fürchte, will ich auf Dich vertrauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'In Gott rühme ich Sein Wort, auf Gott vertraue ich, nicht fürchte ich, was mir das Fleisch kann tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Den ganzen Tag fechten sie meine Worte an; alle ihre Gedanken sind wider mich zum Bösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Sie rotten sich zusammen, verbergen sich, halten auf meine Fersen, wenn sie auf meine Seele warten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Wegen ihres Unrechts sollen sie entkommen? Im Zorne unterwirf Dir die Völker, o Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Mein Entfliehen zählst Du, tue meine Träne in Deinen Schlauch. Sind sie nicht in Deiner Zahl?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'Dann müssen meine Feinde hinter sich zurückkehren, am Tage, da ich rufe: Das weiß ich, daß Gott für mich ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'In Gott rühme ich das Wort, in Jehovah rühme ich das Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Auf Gott vertraue ich, ich fürchte mich nicht, was kann der Mensch mir tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Auf mir sind Deine Gelübde, o Gott, ich will Dir Dankopfer bezahlen. Denn Du hast meine Seele vom Tod errettet, meine Füße von dem Anstoß, daß ich vor Gott wandle im Lichte der Lebendigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, 'Dem Sangmeister nach â¬SAl Taschchethâ¬_, ein Goldlied von David, als er vor Saul in die Höhle entwich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Sei mir gnädig, o Gott, sei mir gnädig; denn auf Dich verläßt meine Seele sich und auf den Schatten Deiner Flügel verlasse ich mich, bis das Unheil vorüber ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Ich rufe zu Gott, zum Allerhöchsten, zu Gott, Der es für mich ausführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Er sendet vom Himmel und rettet mich vom Schmähen dessen, der nach mir schnappt. Selah. Gott sendet aus Seine Barmherzigkeit und Seine Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Ich liege mit meiner Seele inmitten der Löwen. Des Menschen Söhne sind entflammt; ihre Zähne sind Spieße und Pfeile und ihre Zunge scharfe Schwerter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Erhöhe Dich über die Himmel, o Gott, über die ganze Erde Deine Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Ein Netz bereiten sie meinen Tritten, daß meine Seele sich krümmte. Sie gruben vor mir eine Fallgrube, sie fallen selbst mitten hinein. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Mein Herz ist fest, o Gott, mein Herz ist fest. Ich will singen und lobpreisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Wache auf, meine Herrlichkeit, wachet auf, Psalter und Harfe, ich will das Morgenrot aufwecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Ich will bekennen Dich, Herr, unter den Völkern, Dir Psalmen singen unter den Volksstämmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Denn groß bis an die Himmel ist Deine Barmherzigkeit, und Deine Wahrheit bis zu den Ätherkreisen. Erhöhe über die Himmel Dich, o Gott, über die ganze Erde Deine Herrlichkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, 'Dem Sangmeister nach â¬SAl Taschchethâ¬_. Ein Goldlied von David.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Sprechet ihr wahrlich stumme Gerechtigkeit? Richtet ihr nach Geradheit, o ihr Söhne des Menschen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Übet ihr nicht im Herzen Verkehrtheiten, und wägt die Gewalttat eurer Hände im Lande dar?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Vom Mutterschoß an sind die Ungerechten entfremdet, vom Mutterleib aus abgeirrt, die Falsches reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'Gift haben sie, dem Gifte gleich der Schlange, gleich der tauben Otter, die ihr Ohr verstopft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'Die nicht hört auf die Stimme der Beschwörer, des Bannsprechers, weise im Bannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Reiße heraus, o Gott, die Zähne in ihrem Munde! Zertrümmere, o Jehovah, die Backenzähne der jungen Löwen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Lasse sie zerfließen wie Wasser, die dahingehen; spannt er seine Pfeile, so werden sie wie abgeschnitten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Sie seien gleich der Wegschnecke, die dahingehend zerfließt, der Fehlgeburt des Weibes, welche die Sonne nicht erschauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Bevor noch eure Töpfe die Dornen merken, hat sie frisch oder brennend der Sturm weggerafft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'Der Gerechte ist fröhlich, wenn er die Rache erschaut, er badet im Blute der Ungerechten seine Schritte. Und es spricht der Mensch: Ja, Frucht hat der Gerechte. Ja, ein Gott ist Richter auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, 'Dem Sangmeister nach â¬SAl Taschchethâ¬_. Ein Goldlied von David, da Saul sandte, und sie das Haus bewachten, ihn zu töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Errette mich von meinen Feinden, o mein Gott; vor denen, so sich wider mich aufmachen, hebe mich empor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Errette mich von denen, die Unrecht tun, und rette mich von den Männern des Bluts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Denn siehe, sie lauern auf meine Seele; Starke rotten sich wider mich, nicht um meiner Übertretung noch meiner Sünde willen, Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Ohne Missetat laufen sie, und bereiten sich zu; wache auf, mir entgegen und siehe darein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Und Du, Jehovah, Gott Zebaoth, Gott Israels, erwache, heimzusuchen alle die Völkerschaften, sei keinem gnädig von allen denen, die treulos Unrecht üben. Selah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Am Abend kehren sie zurück, tummeln sich wie der Hund, und ziehen in der Stadt umher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Siehe, sie lassen es mit dem Munde hervorquellen, Schwerter sind auf ihren Lippen. Denn wer hört es?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Doch Du, Jehovah, lachst ihrer, Du verlachst alle Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Vor seiner Stärke halte ich mich zu Dir; denn Gott ist meine Burg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Gott kommt mir nach Seiner Barmherzigkeit entgegen, und Gott läßt mich sehen auf meinen Gegner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Erwürge sie nicht, damit mein Volk nicht vergesse; aber laß sie wandern durch Deine Macht, und bringe sie hinab, Du, unser Schild, o Herr!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Die Sünde ihres Mundes ist das Wort von ihren Lippen; laß sie denn sich fangen in ihrem Stolze, und um ihrer Verwünschung und der Lügen willen, die sie erzählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'Verzehre sie im Grimm, verzehre sie, daß sie nicht mehr sind, und sie wissen, daß Gott in Jakob herrscht bis an der Erde Enden! Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Und am Abend kehren sie zurück, tummeln sich wie der Hund und ziehen in der Stadt umher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Und sie wandern umher nach Speise, und ohne satt zu sein, bleiben sie über Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'Ich aber will von Deiner Stärke singen, lobpreisen am Morgen Deine Barmherzigkeit, daß Du mir eine Burg und Zuflucht wardst am Tage meiner Drangsal. Du, meine Stärke, Dir singe ich Psalmen; denn Gott ist meine Burg, der Gott meiner Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, 'Dem Sangmeister. Auf â¬SSchuschan Eduthâ¬_. Ein Goldlied Davids zum Lehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Als er mit Aram der zwei Flüsse und mit Aram von Zobah kämpfte, und Joab zurückkehrte und im Salztal zwölftausend Edomiter schlug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Gott, Du hast uns verworfen, einen Durchbruch wider uns gemacht, Du zürntest, kehre zurück zu uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Du hast die Erde erbeben lassen, sie zerrüttet, heile ihre Brüche; denn sie wankt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Du hast gezeigt Hartes Deinem Volk, hast uns getränkt mit Wein des Taumels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Du hattest denen, die Dich fürchten, ein Panier gegeben, um ein Panier zu erheben wegen der Wahrheit, Selah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Auf daß Deine Lieben herausgezogen werden, rette mit Deiner Rechten und antworte uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Gott hat geredet in Seiner Heiligkeit: Ich werde jauchzen; Ich will Sichem verteilen, und den Talgrund Sukkoth ausmessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Mein ist Gilead, und Mein Menascheh, und Ephraim ist Meines Hauptes Stärke, Mein Gesetzgeber Jehudah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Moab, der Topf Meines Waschens; über Edom werfe Ich Meine Schuhe; über Philistäa juble Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Wer wird mich geleiten zur befestigten Stadt? Wer mich bis Edom führen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'Nicht Du, o Gott, Der Du uns verworfen, und nicht auszogst, o Gott, in unseren Heerscharen? Gib Du uns Beistand von dem Dränger; ist eitel doch des Menschen Heil. Mit Gott tun wir Tapferes; und Er zertritt unsere Dränger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, 'Dem Sangmeister auf Saitenspiel. Von David.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Höre, o Gott, auf mein Rufen, horche auf mein Gebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Vom Ende der Erde rufe ich zu Dir, wenn mein Herz verzagt. Führe mich auf den Felsen, der höher ist denn ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Denn Du wardst meine Zuversicht, ein starker Turm vor dem Feinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Laß weilen mich in Deinem Zelte ewiglich, mich verlassen auf Deiner Flügel Verborgenheit. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Denn Du, o Gott, hörst auf meine Gelübde, Du gibst mir das Besitztum derer, die Deinen Namen fürchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Du tust hinzu Tage zu des Königs Tagen, seine Jahre seien wie Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Er wird sitzen ewiglich vor Gott. O verschaffe Barmherzigkeit und Wahrheit, lasse sie ihn bewahren. Dann will ich immerfort Psalmen singen Deinem Namen, indem ich Dir meine Gelübde bezahle Tag für Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, 'Dem Sangmeister auf Jeduthun. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Sei stille nur in Gott, du meine Seele; von Ihm kommt mein Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Nur Er ist mein Fels und mein Heil, meine Burg, ich werde viel nicht wanken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Wie lange wollt ihr auf einen Mann anstürmen, wollt ihr alle ihn morden, wie eine sich neigende Wand, wie eine umgestoßene Mauer?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Sie gehen nur zu Rate, ihn von seiner Erhabenheit zu stoßen, sie haben Gefallen am Falschen, segnen mit dem Mund, und in ihrem Inneren fluchen sie. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'In Gott nur, meine Seele, sei stille; denn von Ihm ist meine Hoffnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Nur Er ist mein Fels und mein Heil, meine Burg, ich werde nicht wanken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Mein Heil und meine Herrlichkeit ist bei Gott, der Fels meiner Stärke und meiner Zuversicht ist in Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Vertraue alle Zeit auf Ihn, o Volk, vor Ihm schüttet euer Herz aus, Gott ist unsere Zuversicht! Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Nur Nichtigkeit sind die Söhne des Menschen, Falschheit die Söhne des Mannes; sie steigen auf in der Waage allzumal mehr als die Nichtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Vertraut nicht auf Erpreßtes und werdet nicht ob Entrissenem nichtig; wächst euer Vermögen heran, so setzet euer Herz nicht darein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'Einmal hat Gott geredet, zweimal habe ich das gehört, daß Gottes ist die Stärke. Und Dein, Herr, ist Barmherzigkeit, denn Du erstattest dem Manne nach seinem Tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, 'Ein Psalm Davids, als er in der Wüste Judah war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Gott, mein Gott bist Du, nach Dir suche ich frühe, nach Dir dürstet meine Seele, nach Dir schmachtet mein Fleisch im Lande der Dürre, und wenn matt, ohne Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'So habe ich nach dir im Heiligtum geschaut, um Deine Stärke und Herrlichkeit zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Denn besser als Leben ist Deine Barmherzigkeit. Meine Lippen sollen Dich preisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'So will ich segnen Dich in meinem Leben, will in Deinem Namen meine Hände erheben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'Gleich wie an Fett und an Feistem sich sättigt meine Seele, und mit Lippen der Lobpreisung lobt Dich mein Mund,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Wenn Deiner ich gedenke auf meiner Lagerstätte, in Nachtwachen sinne über Dich,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Daß Du mir Beistand warst, darum lobpreise ich im Schatten Deiner Flügel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'An Dir hängt meine Seele, mich erhält Deine Rechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Sie aber, die nach meiner Seele trachten, sie zu zerstören: Laß sie kommen in der Erde Unterstes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Lasse sie durch die Hand des Schwertes vergehen, Schakalen zum Anteil werden. Der König aber wird fröhlich sein in Gott, und jeder sich rühmen, der bei Ihm schwört, wenn der Mund wird verstopft denen, so Lüge reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, 'Dem Sangmeister. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Höre meine Stimme, Gott, in meiner Klage, bewahre mein Leben vor des Feindes Schauer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'Verbirg mich vor der Bösen Rotte, vor dem Gedränge derer, die Unrecht tun;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'Die ihre Zunge schärfen wie ein Schwert, die mit ihren Pfeilen zielen, mit bitterem Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Die im Verborgenen schießen auf den Untadeligen; plötzlich schießen sie und fürchten sich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Sie machen fest für sich die böse Sache, erzählen, wie sie hehlings Fallstricke legen; sie sagen: Wer sieht sie?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Sie erforschen Verkehrtes: Wir sind fertig, der Plan ist wohl überlegt; und das Innere des Mannes und das Herz sind tief.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'Aber Gott schießt sie mit einem Pfeil; plötzlich kommen ihre Schläge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'Und sie machen, daß sie straucheln; ihre Zunge ist wider sie; sie entfliehen, ein jeder, der sie sieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Und alle Menschen fürchten sich und sagen an Gottes Werk und verstehen, was Er getan hat. Der Gerechte ist fröhlich in Jehovah und verläßt sich auf Ihn, und es rühmen sich alle, die geraden Herzens sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, 'Dem Sangmeister. Ein Psalm von David. Ein Lied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'Dir, Gott, ist die Stille ein Lob auf Zion, und Dir bezahlt man Gelübde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Du hörst das Gebet, zu Dir kommt alles Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Uns überwältigten die Worte der Missetaten, doch sühnest Du unsere Übertretungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'Selig der, den Du erwählst und lässest nahen, zu wohnen in Deinen Vorhöfen; lasse satt uns werden des Guten Deines Hauses, des Heiligen Deines Tempels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Wunderbares in Gerechtigkeit antwortest Du uns, Gott unseres Heils, auf Den vertrauen alle Enden der Erde, und das Meer der Fernen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Der Berge festigt in Seiner Kraft und Sich mit Macht umgürtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'Der beruhigt das Tosen der Meere, das Tosen ihrer Wogen und das Getümmel der Volksstämme;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Und vor Deinen Zeichen fürchten sich, die wohnen an den Enden; die Ausgänge des Morgens und des Abends lässest Du lobpreisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'Du suchst heim die Erde und erfreust sie; Du hast sie sehr bereichert; das Bächlein Gottes ist voll Wassers; Du bereitest ihr Korn, denn so hast Du sie bereitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Du netzst ihre Furchen, senkst ihre Schollen, läßt mit Regengüssen sie zerfließen, und segnest ihre Sprossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Du krönst das Jahr mit Deiner Güte, Deine Fußstapfen triefen mit Fettigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Der Wüste Auen triefen, und mit Frohlocken gürten sich die Hügel. Die Fluren kleiden sich mit Schafen, und die Talgründe hüllen sich in Korn; sie jubeln, ja, sie singen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, 'Es juble zu Gott die ganze Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'Singt Psalmen der Herrlichkeit Seines Namens, machet Sein Lob zur Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Sprechet zu Gott: Wie furchtbar sind Deine Taten! Dir huldigen Deine Feinde ob Deiner vielen Stärke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Alles Land bete Dich an, und singe Dir Psalmen, Deinem Namen singen sie Psalmen! Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Kommet her und sehet die Werke Gottes! Furchtbar ist Sein Tun an den Söhnen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Das Meer hat Er ins Trockene verwandelt; zu Fuß zogen sie hinüber durch den Fluß. Da sind wir fröhlich in Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Ewiglich herrscht Er in Seiner Macht. Sein Auge erspäht die Völkerschaften. Nicht mögen die Aufrührer sich erhöhen. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Segnet unseren Gott, ihr Völker, und laßt hören die Stimme Seines Lobes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Der unsere Seele setzt unter die Lebendigen, und unseren Fuß nicht wanken läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Denn Du hast uns geprüft, Gott, uns geläutert, wie man Silber läutert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Ins Garn hast Du uns gebracht, hast Trübsal gelegt auf unsere Lenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Du ließest den Menschen reiten über unser Haupt, wir kamen ins Feuer und ins Wasser; doch hast Du uns herausgeführt ins Weite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Ich will mit Brandopfern in Dein Haus kommen, will meine Gelübde Dir bezahlen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'Was meine Lippen ausgesprochen, und mein Mund geredet hat in meiner Drangsal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Ich will Dir markige Brandopfer aufopfern, mit der Widder Räuchwerk, will Rinder Dir samt Böcken darbringen. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Kommt, höret alle, die ihr Gott fürchtet, und ich erzähle euch, was Er an meiner Seele getan hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'Mit meinem Munde rief ich zu Ihm, und Erhöhung ist unter meiner Zunge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Hätte auf Unrecht ich gesehen in meinem Herzen, nicht hätte der Herr gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Allein Gott hörte, Er horchte auf meines Gebetes Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Gesegnet sei Gott, Der mein Gebet nicht wegnahm, noch Seine Barmherzigkeit von mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, 'Dem Sangmeister. Zum Saitenspiel. Ein Psalm, ein Lied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'Gott, sei uns gnädig und segne uns, Er lasse Sein Angesicht leuchten bei uns. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Daß man erkenne Deinen Weg auf Erden, unter allen Völkerschaften Dein Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Dich bekennen, Gott, die Völker, Dich bekennen alle Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Die Volksstämme sind fröhlich und lobpreisen, daß die Völker Du richtest in Geradheit, und die Volksstämme führest auf Erden. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Dich bekennen, Gott, die Völker, alle Völker bekennen Dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Die Erde gibt ihr Gewächs. Es segnet uns Gott, unser Gott. Gott segne uns, und alle Enden der Erde sollen Ihn fürchten, Dein Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, 'Dem Sangmeister. Von David, ein Psalm, ein Lied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Gott mache Sich auf, lasse Seine Feinde sich zerstreuen und fliehen, die Ihn hassen, vor Seinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Wie Rauch dahingetrieben wird, treibe Du sie dahin, wie Wachs zerschmilzt vor Feuer, so vergehen die Ungerechten vor Gottes Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Und die Gerechten sind fröhlich, sie jauchzen vor Gott, und freuen sich in Fröhlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Singet Gott, singt Psalmen Seinem Namen, macht Bahn Ihm, Der daherfährt auf Wolken, bei Seinem Namen Jah, und jauchzet vor Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Der Waisen Vater, und Der Recht schafft den Witwen, ist Gott in der Wohnstätte Seiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'Gott läßt im Hause wohnen die Einsamen, und führt die in Fesseln Gebundenen hinaus, doch in der Dürre wohnen die Aufrührer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'Gott, da Du auszogest vor Deinem Volk, da Du einherschrittest im Wüstenland, Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Erbebte die Erde, ja es troffen die Himmel, vor Gott; jener Sinai vor Gott, dem Gotte Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Freiwillige Regengüsse schüttelst Du herab, o Gott, und festigst Dein ermüdetes Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Darin wird wohnen Dein Wild; Du festigst, o Gott, mit Deinem Gut den Elenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Der Herr gibt die Rede; die Heil verkünden, ein großes Heer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Die Könige der Heere sind entflohen, sind entflohen, und die Bewohnerin des Hauses verteilt Beute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Wenn ihr zwischen Hürden lieget, dann sind der Taube Flügel mit Silber bedeckt, und ihre Fittiche mit grünlichem Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Wenn Schaddai die Könige in ihr ausbreitet, wird es schneeweiß auf dem Zalmon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Ein Berg Gottes ist der Berg Baschans, ein Berg der Hügel ist Baschans Berg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Was hüpfet ihr, Berge, ihr Hügel des Berges? Gott hat begehrt darauf zu wohnen, ja, Jehovah wird ihn bewohnen immerdar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Der Streitwagen Gottes sind es zwei Myriaden, Tausende verdoppelt! Der Herr ist in ihnen, Sinai ist im Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Du bist emporgestiegen in die Höhe, hast Gefangene weggeführt; Gaben hast Du angenommen bei dem Menschen, auch die Aufrührer, daß Gott Jah wohnen möge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'Gesegnet sei Tag für Tag der Herr! Ladet man uns eine Last auf, ist Gott unser Heil. Selah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Gott ist ein Gott des Heiles uns, und bei Jehovah, dem Herrn, sind die Ausgänge vom Tode.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Gott aber wird zerschmettern Seiner Feinde Haupt, den Scheitel dessen, der in seiner Schuld dahingeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'Es spricht der Herr: Ich bringe aus Baschan sie zurück, bringe zurück sie von des Meeres Schlund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Daß deinen Fuß du eindrückst ins Blut, und deiner Hunde Zunge sich ihren Teil vom Feinde nehme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'Sie sehen Deine Gänge, o Gott, die Gänge meines Gottes, meines Königs im Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'Voran ziehen die Sänger, danach die Saitenspieler in paukender Jungfrauen Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Segnet Gott in den Versammlungen, den Herrn aus dem Borne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Da ist Benjamin der Kleine, ihr Herrscher; die Fürsten Judahs mit ihrer Schar, die Fürsten Sebulons, die Fürsten Naphthalis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Dein Gott hat deine Stärke geboten, zeige stark Dich, o Gott, das hast Du an uns getan;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Von Deinem Tempel über Jerusalem; dir werden Könige Geschenke bringen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Schilt Du das wilde Tier des Schilfs, die Gemeinde der Gewaltigen, unter den Kälbern der Völker, das niedertritt die Stücke Silbers, das umherstreut die Völker; sie haben Lust an Kämpfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Es werden Fette kommen aus Ägypten. Zu Gott wird eilig Kusch seine Hände erheben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'Singt Gott, ihr Reiche der Erde, singt Psalmen dem Herrn. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Ihm, Der einherfährt auf den Himmeln der Himmel der Vorzeit. Siehe, Er läßt ergehen Seine Stimme, die Stimme der Stärke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Gebt Gott die Stärke, über Israel ist Seine Hoheit, und Seine Stärke im Wolkenhimmel. Furchtbar bist Du, o Gott, aus Deinen Heiligtümern, Israels Gott. Er gibt Stärke dem Volke und Macht. Gesegnet sei Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, 'Dem Sangmeister. Auf Schoschannim. Von David.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Rette mich, o Gott; denn bis an die Seele kommen mir die Wasser!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'Versunken bin ich im Schlamm des Schlundes, und es ist kein Stehen; ich bin in die Tiefen der Wasser gekommen, und die Flut strömt über mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Müde bin ich von meinen Rufen, meine Kehle ist heiser, meine Augen sind verzehrt vom Warten auf meinen Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'Mehr denn der Haare meines Hauptes sind derer, die ohne Grund mich hassen, mächtig sind meine Vertilger, die mich aus Lug befeinden. Ich soll zurückgeben, was ich nicht entrissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Du kennst, Gott, meine Albernheit, und nicht verhohlen ist vor Dir, was ich verschuldet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Laß nicht in mir beschämt werden die, so auf Dich hoffen, Herr Jehovah der Heerscharen. Laß nicht zuschanden werden, die Dich suchen, Gott Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Denn Deinetwegen trage ich Schmach, Schande hat mein Angesicht bedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Entfremdet bin ich meinen Brüdern, und ein Fremder meiner Mutter Söhnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Denn der Eifer um Dein Haus hat mich verzehrt, und die Schmach derer, die Dich schmähen, ist auf mich gefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Und ich weinte beim Fasten meiner Seele, und es ward mir zur Schmach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'Und ich nahm den Sack mir zum Anzug, und bin ihnen zum Sprichwort geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Die im Tore sitzen, schwatzen über mich, denen, so starken Trank trinken, bin ich zum Lied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Aber ich, mein Gebet ist zu Dir, Jehovah, zur Zeit des Wohlgefallens, o Gott, nach Deiner großen Barmherzigkeit; antworte mir in der Wahrheit Deines Heils.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Errette mich aus dem Kote, daß ich nicht sinke, daß ich von meinen Hassern errettet werde und aus des Wassers Tiefen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Daß nicht die Flut der Wasser mich überströme, und der Schlund mich nicht verschlinge, und die Grube ihren Mund nicht zuschließe über mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'Antworte mir, Jehovah; denn gut ist Deine Barmherzigkeit; wende Dich zu mir nach der Größe Deines Erbarmens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Und verbirg Dein Angesicht nicht vor Deinem Knecht, denn ich bin bedrängt; eile, antworte mir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Nahe Dich meiner Seele, erlöse sie; meiner Feinde wegen löse mich ein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Du weißt meine Schmach und meine Scham und meine Schande, alle meine Gegner sind Dir gegenwärtig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Die Schmach bricht mir das Herz, und ich bin todkrank, und ich hoffte auf Beileid, aber keiner ist da, und auf Tröster, finde aber keine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Sie gaben Galle mir zur Nahrung und tränkten für meinen Durst mich mit Essig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Ihr Tisch werde vor ihnen zur Schlinge, und zur Vergeltung, zum Fallstrick.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Lasse ihre Augen sich verfinstern, daß sie nicht sehen, und lasse ihre Lenden beständig schwanken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Gieße Deinen Unwillen aus über sie, und sie erreiche Deines Zornes Entbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Ihr Gehöfte müsse wüste werden, niemand in ihren Zelten wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Denn sie verfolgen den, so Du geschlagen, und erzählen von dem Schmerz der von Dir Durchbohrten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Gib Missetat zu ihrer Missetat, und laß sie nicht kommen in Deine Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Wische sie aus von dem Buch des Lebens, und lasse sie nicht geschrieben werden mit den Gerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Ich aber bin elend und in Schmerzen, doch wird, o Gott, Dein Heil mich emporführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'Ich will den Namen Gottes loben mit Gesang, und Ihn groß preisen mit Dank.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Und der wird dem Jehovah besser sein, denn ein Ochse, ein Farren mit Horn und Klauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Die Elenden sehen es, sie sind fröhlich, die nach Gott fragen; und es lebe euer Herz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Denn auf die Dürftigen hört Jehovah und verachtet nicht Seine Gebundenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Ihn loben Himmel und Erde, die Meere und alles, was sich darin regt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'Denn Gott wird Zion retten und bauen die Städte Judahs, daß sie darinnen wohnen und es besitzen. Und der Same Seiner Knechte wird es erben, und die, so Seinen Namen lieben, werden darin wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, 'Dem Sangmeister. Von David. Zum Andenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'O Gott, komm schleunig mich zu erretten, Jehovah, mir beizustehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Sich schämen müssen und erröten, die nach meiner Seele trachten, hinter sich zurückweichen und zuschanden werden, die Lust haben an meinem Bösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Umkehren müssen zur Belohnung ihrer Scham, die zu mir sagen: Ha! Ha!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Freuen müssen sich und in Dir fröhlich sein, alle, die Dich suchen; und beständig sagen: Groß ist Gott! sie, die Dein Heil lieben. Ich aber bin elend und dürftig. O Gott, komm schleunig zu mir; mein Beistand und Befreier bist Du, Jehovah, zögere nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'Auf Dich, Jehovah, verlasse ich mich. Laß mich ewiglich nicht beschämt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Errette und befreie mich in Deiner Gerechtigkeit, neige Dein Ohr mir zu, und rette mich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Sei Du mir ein Fels, eine Wohnstätte, dahin ich beständig kommen mag; Du hast geboten, mich zu retten. Meine Felsklippe und meine Feste bist Du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Mein Gott, befreie mich aus der Hand des Ungerechten, aus der Hand des Verkehrten und des Heftigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Denn Du bist meine Hoffnung, Herr Jehovah, mein Vertrauen von meiner Jugend auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Auf Dich habe ich von Mutterleib an mich gelehnt. Aus meiner Mutter Eingeweide zogst Du mich heraus. In Dir ist mein Lob beständig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Wie ein Wahrzeichen war ich vielen; denn Du warst meine Zuversicht der Stärke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Mein Mund ist Deines Lobes voll und Deines Ruhmes den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Verwirf mich nicht zur Zeit des Alters, verlaß mich nicht, wenn meine Kraft zu Ende geht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Denn meine Feinde sprechen über mich; und die auf meine Seele halten, ratschlagen zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'Sie sprechen: Gott hat ihn verlassen, setzet ihm nach, und fasset ihn; denn niemand ist, der ihn errette.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Gott, sei nicht fern von mir, komm schleunig mir zum Beistand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Schämen müssen sich und verzehrt werden, die meine Seele anfeinden; Schmach und Schande umhülle sie, die mir Übles suchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Ich aber will beständig warten und hinzutun zu all Deinem Lobe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Mein Mund soll Deine Gerechtigkeit erzählen, Dein Heil den ganzen Tag; denn ich weiß sie nicht zu zählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Ich will kommen in der Macht des Herrn Jehovah, ich will gedenken Deiner Gerechtigkeit, Deiner allein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Gott, Du hast von Jugend auf mich gelehrt, und bis hierher will ich Deine Wunder ansagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Und auch bis ins Alter und ins Greisentum, o Gott, verlasse mich nicht, bis daß ich dem Geschlechte Deinen Arm ansage, jedem, der kommen wird, Deine Macht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'Und Deine Gerechtigkeit, o Gott, bis in die Höhe; was Du Großes getan hast, o Gott; wer ist, wie Du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Der Du mich viele und böse Drangsale hast sehen lassen, kehre zurück, belebe Du mich und bringe Du mich zurück aus der Erde Abgründen, bringe mich herauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'Mehre Du meine Größe und wende Dich um, tröste mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Auch ich will Dich bekennen mit dem Instrument des Psalters, Deiner Wahrheit, o Gott; will Dir in Psalmen singen zur Harfe, Du Heiliger Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Lobpreisen werden meine Lippen, wenn ich Dir Psalmen singe, und meine Seele, die Du eingelöst hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Auch meine Zunge sinnt den ganzen Tag Deine Gerechtigkeit, denn beschämt werden, denn es erröten, die mir Übles suchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, 'Von Salomoh. Gott, gib dem König Deine Gerichte, und Deine Gerechtigkeit dem Sohn des Königs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Er spricht Recht Deinem Volke in Gerechtigkeit, und Deinem Elenden mit Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Die Berge werden dem Volk Frieden tragen, und Gerechtigkeit die Hügel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'Er richtet die Elenden des Volkes, Er rettet die Söhne des Dürftigen und zerschlägt den, der niederdrückt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Sie werden Dich fürchten bei der Sonne, und vor dem Mond, ein Geschlecht der Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Wie Regen kommt Er auf Wiesenschur herab, wie Regengüsse auf rissiges Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Aufblühen wird in seinen Tagen der Gerechte, und viel Friede sein, bis daß kein Mond mehr ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'Und herrschen wird Er von Meer zu Meer, und von dem Fluß bis zu der Erde Enden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Die Barbaren werden beugen sich vor Ihm, und Seine Feinde Staub auflecken;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Die Könige von Tarschisch und den Inseln werden Geschenke bringen, Schebas und Sebas Könige sich mit Ehrengaben nahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'Ihn werden alle Könige anbeten, alle Völkerschaften werden Ihm dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Denn Er wird erretten den Dürftigen, der aufschreit, und den Elenden, der keinen Beistand hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Er wird des Armen und Dürftigen schonen, und der Dürftigen Seelen retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Von Hinterlist und von Gewalttat erlöst Er ihre Seele, und köstlich ist ihr Blut in Seinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'Und Er wird leben, und man wird Ihm von Schebas Gold geben, und beständig für Ihn beten, Ihn segnen jeden Tag!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Des Kornes Fülle wird im Lande sein, auf der Spitze der Berge erzittert Seine Frucht, wie der Libanon, und aufblühen werden sie aus der Stadt, wie das Kraut der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Sein Name wird sein in Ewigkeit, vor der Sonne wird Er den Namen eines Sohnes haben, und segnen werden sich in Ihm alle Völkerschaften; sie werden Ihn seligpreisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Gesegnet sei Jehovah Gott, Israels Gott, Der Wunder tut allein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'Und ewiglich sei der Name Seiner Herrlichkeit gesegnet, und alles Land soll voll werden Seiner Herrlichkeit. Amen und Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Die Gebete Davids, des Sohnes Ischais sind vollendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, 'Nur gut gegen Israel ist Gott, gegen die, so lauteren Herzens sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Ich aber, um ein Kleines, so hätten sich meine Füße abgewendet, wie nichts, so wären ausgeglitten meine Tritte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Denn ich eiferte gegen die sich Rühmenden, ich sah den Frieden der Ungerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Sie sind nicht in Banden, bis zu ihrem Tode; und feist ist ihr Leib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'In der Mühsal des Menschen sind sie nicht, und sind nicht mit dem Menschen geplagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Darum ist Übermut ihr Halsband, Gewalttat hüllt sie als Putz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Vor Fett tritt hervor ihr Auge; des Herzens Einbildungen gehen über.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Sie höhnen und reden im Bösen von Plackerei, sie reden aus der Höhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Sie setzen in den Himmel ihren Mund, und ihre Zunge geht auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Darum kehrt Sein Volk dahin zurück, und des Wassers Fülle wird ihnen ausgepreßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'Und sie sprechen: Wie sollte Gott es wissen, und Kunde bei dem Höchsten sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Siehe, das sind die Ungerechten, sie sind sorglos im Zeitalter; sie vermehren das Vermögen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Nur umsonst hielt lauter ich mein Herz, und wusch in Unschuld meine Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'Und ich werde jeden Tag geplagt und in den Morgen wird mir Rüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Spräche ich: Ich will wie jene reden, siehe, so werde ich treulos an dem Geschlechte Deiner Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Und ich dachte das zu wissen: Mühsal war es in meinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Bis ich in Gottes Heiligtümer einging und merkte auf ihr Letztes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Du stellst sie nur aufs Schlüpfrige und läßt sie in Verstörung fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Wie sind sie doch im Augenblick verwüstet, dahingerafft und mit Bestürzung zunichte worden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'Wie einen Traum nach dem Erwachen verachtest Du, Herr, beim Aufwachen ihr Bild.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Als es in meinem Herzen gor und mich in die Nieren stach;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'Da ich noch tierisch war und nichts wußte, war ich wie das Vieh bei Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'Ich aber war bei Dir beständig, du ergriffst mich bei meiner Rechten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Nach Deinem Ratschluß führst Du mich und nimmst mich nachher auf in Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Wen habe ich im Himmel? Und neben Dir habe keine Lust ich an der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Verzehrt ist mein Fleisch und mein Herz, Fels meines Herzens, und mein Teil ist Gott in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Denn siehe, die ferne sind von Dir, vergehen, Du vertilgst alle, die von Dir abbuhlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Mir aber ist die Nähe Gottes gut. In den Herrn Jehovah setze ich meine Zuversicht, daß alle Deine Werke ich erzähle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, 'Warum, o Gott, verwirfst Du für immer, warum raucht Dein Zorn wider die Herde Deiner Weide?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Gedenke Deiner Gemeinde, die in der Vorzeit Du erworben, erlöst zum Stamme Deines Erbes, des Berges Zion, auf dem Du gewohnt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Erhöhe Deine Tritte zu den immerwährenden Verstörungen. Alles hat der Feind im Heiligtume übel zugerichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Es brüllten Deine Gegner in des Festes Mitte; sie haben ihre Zeichen als Zeichen gesetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Er wird erkannt, als einer, der die Axt schwingt empor in des Holzes Dickicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'Und schon zerschlagen sie sein Schnitzwerk, zumal mit Beil und Hämmern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Sie legen Feuer an Dein Heiligtum, zur Erde hin entweihen sie die Wohnung Deines Namens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Sie sprechen in ihrem Herzen: Laßt uns sie zerdrücken zumal. Sie verbrennen alle Festorte Gottes im Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Wir sehen nicht mehr unsere Zeichen. Kein Prophet ist mehr, und keiner, welcher wüßte, wie lange.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Wie lange, o Gott, soll schmähen der Dränger, soll lästern Deinen Namen immerdar der Feind?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Warum wendest Deine Hand und Deine Rechte Du zurück? Heraus aus der Mitte Deines Busens! Mache ein Ende!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Aber Gott ist mein König von der Vorzeit her, Der Heil schafft in des Landes Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Du ließest klaffen das Meer durch Deine Stärke, Du zerbrachst auf den Wassern die Köpfe der Walfische.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Die Köpfe des Leviathans zerschlugst Du, gabst es zur Speise dem Volke, den Ziim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Du hast gespalten Quelle und Bach, hast Flüsse der Stärke vertrocknet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Dein ist der Tag, auch Dein die Nacht; Du hast bereitet Licht und Sonne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Du stellst alle Grenzen der Erde, Sommer und Winter hast Du gebildet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Gedenke das: Der Feind schmäht Jehovah, und ein töricht Volk lästert Deinen Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Gib nicht dem wilden Tiere die Seele Deiner Turteltaube, vergiß nicht immerdar das Leben Deiner Elenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Blicke auf den Bund, denn in des Landes Finsternissen sind Wohnplätze der Gewalttat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Nicht trete der Schwache zurück mit Schanden. Der Elende und Dürftige lobe Deinen Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Mache Dich auf, Gott, hadere Deinen Hader, gedenke Deiner Schmähung von dem Toren den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Vergiß nicht der Stimme Deiner Gegner, des Tosens derer, die wider Dich aufstehen, das beständig aufsteigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, 'Dem Sangmeister nach Al Taschcheth. Ein Psalm, ein Lied von Asaph.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Wir bekennen Dich, o Gott, wir bekennen, daß nahe ist Dein Name; sie erzählen Deine Wunder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Wenn Ich die bestimmte Zeit erhalte, richte ich Geradheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Die Erde zerfließt und alle, die auf ihr wohnen; Ich festige ihre Säulen. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Zu den sich Rühmenden spreche Ich: Rühmet euch nicht; und zu den Ungerechten: Erhöhet nicht das Horn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Erhöhet nicht in die Höhe euer Horn. Redet nicht mit starrem Halse!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Denn nicht vom Aufgang, noch vom Abend, und nicht von der Wüste der Berge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Sondern Gott ist Richter: Diesen erniedrigt Er, und jenen erhöht Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Denn ein Becher ist in der Hand Jehovahs, Er läßt ihn aufwallen mit Wein, Er füllt ihn mit Mischung; und gießt davon ein, aber die Hefen davon schlürfen, trinken alle Ungerechten der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'Ich aber will es ansagen ewiglich, will Psalmen singen dem Gotte Jakobs. Und alle Hörner der Ungerechten will ich niederhauen, erhöhen sollen sich die Hörner der Gerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, 'Dem Singmeister mit Saitenspiel. Ein Psalm Asaphs, ein Lied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'Bekannt in Jehudah ist Gott. In Israel ist groß Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Und Seine Hütte ist in Schalem und in Zion Seine Wohnstätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Da zerbricht Er des Bogens Feuerpfeile, Schild und Schwert und Streit. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Du leuchtest stattlicher, denn die Berge des Raubes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Zur Beute wurden die Gewaltigen von Herzen, sie schlummern ihren Schlaf; und nicht fanden alle die Männer der Tapferkeit ihre Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Von Deinem Drohen, Gott Jakobs, entschlafen beides: Streitwagen und Roß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Du bist furchtbar, Du, und wer könnte vor Dir stehen, wenn Du zürnst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'Vom Himmel her läßt Du hören das Urteil, die Erde fürchtet sich und rastet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Wenn Gott Sich zum Gericht aufmacht, zu retten alle Elenden der Erde. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Denn Dich bekennt des Menschen Grimm, mit dem Überrest des Grimmes gürtest Du Dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Gelobet und entrichtet Jehovah, eurem Gotte, ihr alle ringsumher. Bringet dem Furchtbaren Geschenke dar. Er demütigt den Geist der Führer, Er ist furchtbar den Königen der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, 'Dem Sangmeister. Auf Jeduthun. Von Asaph, ein Psalm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Meine Stimme ist zu Gott und ich schreie; meine Stimme ist zu Gott und Er nimmt mir es zu Ohren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Am Tage meiner Drangsal suche ich Dich, Herr, des Nachts reckt meine Hand sich aus und läßt nicht nach; meine Seele weigert sich des Trostes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Ich gedenke Gottes, und bin beunruhigt, ich überdenke es, und mein Geist verzagt. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Du hältst wach meine Augen, ich bin erschüttert und kann nicht reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Ich denke der Vorzeit Tage, der Jahre der Zeitalter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Ich gedenke an mein Saitenspiel bei Nacht, in meinem Herzen überdenke ich es, und es forscht mein Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Wird der Herr in die Ewigkeiten verwerfen? und nicht wieder Wohlgefallen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Hat denn für immerfort Seine Barmherzigkeit ein Ende? Ist es gar aus mit der Rede von Geschlecht zu Geschlecht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Hat Gott vergessen Seine Gnaden, im Zorn verschlossen Seine Erbarmungen? Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'Ich aber sprach: Dies ist mein Flehen. Ändern kann es des Allerhöchsten Rechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'Der Taten Jahs gedenke ich, denn ich gedenke Deiner Wunder in der Vorzeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'Und ich sinne über all Dein Werk und überdenke Deine Taten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Gott, in Heiligkeit ist Dein Weg! Wer ist ein Gott so groß wie Gott?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Du, Gott, tust Wunder, hast Deine Stärke unter den Völkern kundgetan;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Mit dem Arm hast Du Dein Volk erlöst, die Söhne Jakobs und Josephs. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Die Wasser sahen Dich, o Gott, die Wasser sahen Dich und kreißten, ja die Abgründe zitterten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Die dichten Wolken strömten Wasser, die Ätherkreise gaben Stimme, auch fuhren dahin Deine Pfeile.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Die Stimme Deines Donners war im Wirbelwind, Blitze erleuchteten die Welt, es zitterte und bebte die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Im Meere war Dein Weg, durch viele Wasser Deine Fußpfade, und Deine Fußstapfen wurden nicht erkannt! Du führtest Dein Volk wie eine Herde, durch die Hand Moses und Aharons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, 'Nimm zu Ohren, mein Volk, mein Gesetz, zu meines Mundes Reden neigt euer Ohr!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'Ich will in Sprüchen meinen Mund auftun, ich lasse aus der Vorzeit Rätsel hervorquellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Was wir gehört und erkannt, und unsere Väter uns erzählt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'Nicht wollen wir es verhehlen ihren Söhnen, wollen dem späteren Geschlecht Jehovahs Lob erzählen, und Seine Stärke und Seine Wunder, die Er getan hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Und Er richtete ein Zeugnis auf in Jakob und setzte ein Gesetz in Israel ein, das unseren Vätern Er gebot, sie ihren Söhnen zu wissen zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Auf daß es erkennete das spätere Geschlecht, die Söhne, die geboren werden, daß sie aufstünden und es ihren Söhnen erzähleten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Und daß sie auf Gott ihr Zutrauen setzeten, und nicht der Taten Gottes vergäßen, und Seine Gebote bewahrten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'Und nicht wie ihre Väter würden ein aufrührerisches und widerspenstiges Geschlecht, dessen Herz nicht fest war, und dessen Geist nicht treu war mit Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Die Söhne Ephraims waren bewaffnete Bogenschützen, die am Tage des Kampfes sich umkehrten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Sie hielten den Bund Gottes nicht, und weigerten sich, in Seinem Gesetz zu wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'Und sie vergaßen Seiner Taten und Seiner Wunder, die Er sie sehen ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Vor ihren Vätern tat Er Wunder im Lande Ägypten, in Zoans Gefilde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Er spaltete das Meer und führte sie hindurch, und stellte die Wasser wie einen Haufen auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'Und Er führte sie am Tag in einer Wolke, und die ganze Nacht im Lichte des Feuers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Er spaltete in der Wüste Felsen, und tränkte sie viel wie aus Abgründen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Und Bächlein ließ Er aus der Felsklippe ausgehen, und Wasser wie Flüsse herabflie-ßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Und noch fuhren sie fort zu sündigen gegen Ihn, sich in der Dürre dem Höchsten zu widersetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'Und sie versuchten Gott in ihrem Herzen, und fragten um Speise für ihre Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'Und sie redeten wider Gott, sie sagten: Kann Gott in der Wüste einen Tisch zurichten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Siehe, Er schlug den Felsen und Wasser floß und Bäche fluteten; wird Er auch Brot geben können? wird Er Fleisch bereiten Seinem Volk?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Darum hörte Jehovah, und Er wütete, und Feuer loderte auf gegen Jakob, und Zorn stieg auch auf wider Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Weil sie an Gott nicht glaubten und auf Sein Heil nicht vertrauten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'Und Er gebot den Ätherkreisen oben und öffnete des Himmels Türen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'Und Er ließ Manna auf sie regnen, zu essen, und gab ihnen Korn des Himmels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Brot der Gewaltigen aß der Mann, Zehrung sandte Er ihnen zur Sättigung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Und Er ließ herfahren am Himmel den Ostwind, und trieb in Seiner Stärke den Südwind her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'Und ließ Fleisch regnen auf sie wie Staub, und wie Sand der Meere das geflügelte Gevögel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'Und ließ sie fallen mitten in sein Lager, rings um seine Wohnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'Und sie aßen und wurden sehr satt. Er brachte ihnen, wonach sie gelüsteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Sie waren ihren Gelüsten nicht entfremdet, ihre Speise war noch in ihrem Munde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'Da stieg auf wider sie der Zorn Gottes. Und Er würgte unter ihren Fetten, und streckte nieder Israels Jünglinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Bei all dem sündigten sie noch und glaubten nicht an Seine Wunder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Und Er ließ ihre Tage sich verzehren in Nichtigkeit, und ihre Jahre in Bestürzung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Wenn Er sie würgte, fragen sie nach Ihm, und kehrten zurück und verlangten frühe nach Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'Und sie gedachten, daß Gott ihr Fels und Gott, der Allerhöchste, ihr Erlöser sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Und sie beredeten Ihn mit ihrem Munde und redeten Ihm Falsches mit ihrer Zunge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'Ihr Herz aber war nicht fest bei Ihm und waren nicht treu in Seinem Bund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Er aber ist erbarmungsvoll, Er sühnte die Missetat und verdarb sie nicht, und kehrte vielmals zurück von Seinem Zorn und erweckte nicht all Seinen Grimm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Und Er gedachte, daß Fleisch sie sind, ein Hauch, der hingeht und nicht zurückkehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Wie oft waren sie widerspenstig wider Ihn in der Wüste, machten Ihm Schmerzen im Wüstenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Und sie versuchten wieder Gott, und machten Kummer dem Heiligen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Sie gedachten nicht Seiner Hand des Tages, da Er aus der Drangsal sie einlöste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'Wie Er tat Seine Zeichen in Ägypten und Seine Wahrzeichen in Zoans Gefilde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'Und Er verwandelte in Blut ihre Ströme und ihre Bächlein, daß sie nicht trinken konnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Er sandte wider sie das Ungeziefer und es fraß sie, und den Frosch und er verdarb sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'Und Er gab dem Käfer ihr Gewächs und ihren Erwerb der Heuschrecke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Er zerschlug mit Hagel ihren Weinstock und mit Schloßen ihre Maulbeerfeigenbäume.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Und ihr Getier gab Er dem Hagel preis und ihre Viehherden den Glühkohlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Er sandte wider sie Seines Zornes Glut, Wut und Unwille und Drangsal, eine Entsendung böser Engel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Er ebnete Seinem Zorn den Steig, und hielt ihre Seele nicht zurück vom Tod, und gab der Pest ihr Leben preis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'Und Er schlug alle Erstgeburt in Ägypten, die Erstlinge der Vollkraft in den Zelten Chams.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Und wie Schafe ließ Er aufbrechen Sein Volk und geleitete es wie eine Herde in der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'Und Er führte sie sicher, daß sie vor nichts schauderten; und ihre Feinde deckte das Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Und brachte sie zur Grenze Seines Heiligtums, zum Berge da, den Seine Rechte hat erworben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Und trieb die Völkerschaften aus vor ihnen, und ließ es ihnen zufallen, nach dem Stricke als Erbe, und ließ die Stämme Israels in ihren Zelten wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Sie aber versuchten und erbitterten Gott, den Allerhöchsten, und hielten nicht Seine Zeugnisse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Und wichen zurück und wurden treulos wie ihre Väter, und kehrten sich ab wie ein trüglicher Bogen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Und reizten Ihn durch ihre Opferhöhen, und erregten Ihn zum Eifer mit ihren Schnitzbildern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Gott hörte es und wütete, und verschmähte Israel sehr;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'Er gab dahin die Wohnung Schilos, das Zelt, darin unter Menschen Er wohnte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'Und gab Seine Stärke in Gefangenschaft, und Seinen Schmuck in des Drängers Hand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Er überantwortete Sein Volk dem Schwerte und wütete wider Sein Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Es fraß das Feuer Seine Jünglinge, und Seine Jungfrauen wurden nicht gefreit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Es fielen Seine Priester durch das Schwert, und Seine Witwen weinten nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Aber der Herr erwachte, wie ein Schlafender, wie ein Held aufjauchzt vom Wein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'Und schlug Seine Dränger von hinten, und ewige Schmach legte Er auf sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Aber Er verschmähte Josephs Zelt, und wählte den Stamm Ephraim nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Und Er erwählte Jehudahs Stamm, den Berg Zion, den Er liebte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'Und baute wie die Höhen Sein Heiligtum, wie die Erde, die auf ewig Er gegründet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'Und erwählte David, Seinen Knecht, und nahm ihn von der Schafe Hürden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'Hinter den Milchschafen weg brachte Er ihn, daß er weide Jakob, Sein Volk, und Israel, Sein Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Und er weidete sie nach der Rechtschaffenheit seines Herzens, und führte sie nach der Einsicht seiner Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, 'Gott, Völkerschaften sind gekommen in Dein Erbe, sie haben verunreinigt den Tempel Deiner Heiligkeit, haben Jerusalem gelegt in Trümmer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Die Leichname Deiner Knechte gaben sie zum Fraß dem Gevögel der Himmel, das Fleisch Deiner Heiligen dem wilden Tier der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Ihr Blut vergossen sie wie Wasser rings um Jerusalem, und niemand begrub sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'Zur Schmach wurden wir unseren Nachbarn, zum Gelächter und Schimpf denen, die um uns sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Wie lange, Jehovah, willst Du zürnen, immerfort, wird wie Feuer Dein Eifer brennen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Gieß deinen Grimm aus auf die Völkerschaften, die Dich nicht kennen, und auf die Königreiche, die Deinen Namen nicht anrufen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Denn Jakob haben sie gefressen und seine Wohnorte verwüstet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Gedenke uns nicht der früheren Missetaten. Eile, laß Deine Erbarmungen uns entgegenkommen, denn sehr arm sind wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Stehe uns bei, Gott unseres Heils, um des Wortes der Herrlichkeit Deines Namens willen, und errette uns und sühne unsere Sünden um Deines Namens willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Warum sprechen die Völkerschaften: Wo ist ihr Gott? Lasse kundbar werden unter den Völkerschaften vor unseren Augen die Rache des Blutes Deiner Knechte, das vergossen ward!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Laß vor Dich kommen den Angstruf des Gebundenen; nach Deines Armes Größe lasse übrigbleiben des Todes Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'Und siebenfach gib zurück in ihren Busen unseren Nachbarn ihr Schmähen, womit sie Dich schmähten, Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Wir aber, Dein Volk und die Herde Deiner Weide, wollen Dich bekennen in Ewigkeit, von Geschlecht zu Geschlecht Dein Lob erzählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, 'Dem Sangmeister. Auf Schoschannim Eduth. Ein Psalm Asaphs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Hirt Israels, nimm zu Ohren, Der Du wie eine Herde Joseph geleitest, Der Du sitzest auf den Cheruben, strahle hervor!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'Vor Ephraim und Benjamin und Menascheh wecke auf Deine Macht und gehe für uns zur Rettung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Gott, bringe uns zurück, lasse leuchten Dein Angesicht, und wir werden gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Jehovah, Gott der Heerscharen, wie lange rauchst Du bei Deines Volkes Gebet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Du läßt uns Tränenbrot essen und tränkst uns im Übermaß mit Tränen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'Du setzest uns unseren Nachbarn zum Zank, und unsere Feinde verlachen uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Gott der Heerscharen, bringe uns zurück und lasse leuchten Dein Angesicht, und wir werden gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Du ließest einen Weinstock aus Ägypten ausziehen, vertriebst die Völkerschaften und pflanztest ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Du hast vor ihm ausgeräumt, Du ließest ihn seine Wurzeln schlagen, und er füllte das Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Von seinem Schatten wurden Berge bedeckt, und von seinen Reben die Zedern Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Du hast seine Ranken bis zum Meer entsandt und seine Schößlinge bis zum Fluß,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Warum doch hast Du seine Mauern durchbrochen, daß jeder, der des Weges vorüberzieht, ihn berupft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'Der Eber vom Walde hat ihn zerwühlt und das wilde Tier des Feldes ihn abgeweidet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'Gott der Heerscharen, wende Dich doch zurück! Blicke von den Himmeln, siehe und suche diesen Weinstock heim,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Und den Setzling, den Deine Rechte gepflanzt hat, den Sohn, den Du Dir gekräftigt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Verbrannt vom Feuer ist er, zerhauen: vom Dräuen Deines Angesichts vergehen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'Deine Hand sei über dem Manne Deiner Rechten, über dem Menschensohn, den Du Dir gekräftigt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Und wir wollen nicht von Dir zurückweichen. Belebe uns, daß wir anrufen Deinen Namen. Jehovah, Gott der Heerscharen, bringe uns zurück, lasse leuchten Dein Angesicht, und wir werden gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, 'Dem Sangmeister. Auf der Githith. Von Asaph.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Jubelt dem Gott, unserer Stärke, jauchzet auf dem Gotte Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Erhebet den Psalm und schlaget die Pauke, die lieblich Harfe mit dem Psalter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Am Neumond stoßt in die Posaune, zur Feier am Tage unseres Festes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'Denn Satzung ist das für Israel, ein Recht für Jakobs Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Ein Zeugnis setzte Er es für Joseph, da Er auszog wider das Land Ägypten. Eine Lippe, die ich nicht kannte, hörte ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Ich habe seine Schulter von der Last weggenommen, und seine Hände gingen vorbei an dem Ofen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Du riefst in der Drangsal, und Ich zog dich heraus, antwortete dir in des Donners Verborgenheit, Ich prüfte dich am Haderwasser. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Höre, Mein Volk, daß wider dich Ich zeuge; o daß du auf Mich hörtest, Israel!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Es soll kein fremder Gott in dir sein, und du sollst keinen ausländischen Gott anbeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Ich, Jehovah, bin dein Gott, Der dich aus dem Lande Ägypten heraufgeführt. Tue weit auf deinen Mund und Ich will ihn füllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Und Mein Volk hörte nicht auf Meine Stimme, und Israel wollte nichts von Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'Und Ich entsandte sie im Eigensinn ihres Herzens, sie wandelten nach ihren Ratschlägen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'O, daß Mein Volk auf Mich hörte, Israel in Meinen Wegen wandelte!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Um ein Weniges hätte Ich ihre Feinde niedergebeugt, und wider ihre Dränger Meine Hand zurückgekehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'Die, so Jehovah hassen, müßten Ihm huldigen, und ihre Zeit wäre ewig. Und Ich würde sie von dem Fett des Weizens essen lassen und aus dem Felsen sie mit Honig sättigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, 'Gott steht in der Gemeinde Gottes. Inmitten der Götter wird Er richten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Wie lange wollt ihr verkehrt richten und das Angesicht des Ungerechten erheben? Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Richtet für den Armen und Waisen; rechtfertigt den Elenden und Darbenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Befreit den Armen und Dürftigen, aus der Hand der Ungerechten errettet ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'Sie erkennen nicht, sie sehen nicht ein, sie wandeln im Finstern, es wanken alle Grundfesten des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Ich sagte: Götter seid ihr, und des Allerhöchsten Söhne allesamt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Doch werdet ihr sterben, wie der Mensch, und wie der Obersten einer werdet ihr fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Mache Dich auf, Gott, richte die Erde; denn Du erbst alle Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, 'Ein Lied, ein Psalm Asaphs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Gott sei dir nicht stille, schweige nicht, raste nicht, o Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Denn siehe, Deine Feinde toben; und das Haupt erheben, die Dich hassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Wider Dein Volk handeln sie insgeheim mit Arglist, und ratschlagen wider die, so Du verdeckst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Sie sagen: Kommt, wir schaffen sie weg, daß sie keine Völkerschaft mehr sind, und des Namens Israels nicht mehr gedacht werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'Denn sie ratschlagen miteinander im Herzen und schließen wider Dich einen Bund,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Die Zelte Edoms und die Ismaeliter, Moab und die Hagriter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'Gebal und Ammon und Amalek, Philistäa mit denen, die in Tyrus wohnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Auch Assur hängt ihnen an, ein Arm sind sie den Söhnen Lots. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'Tue ihnen, wie Midjan, wie dem Sisera, wie Jabin im Bachtal Kischon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Sie wurden in Endor vernichtet, wurden zum Dünger auf dem Boden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Mache ihre Edlen wie Oreb und wie Seeb, und wie Sebach und wie Zalmunna, alle ihre Gesalbten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Sie, die da sagen: Lasset uns einnehmen für uns Gottes Wohnplätze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Mache sie, mein Gott, wie Wirbelstaub, wie Spreu vor dem Winde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'Wie Feuer den Wald verbrennt, und wie die Flamme, die Berge entflammt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'So setze ihnen nach mit Deinem Wetter, und mit Deinem Sturmwind mache sie bestürzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Fülle ihr Gesicht mit Unehre, und lasse sie, Jehovah, Deinen Namen suchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'Lasse sie beschämt und bestürzt werden fort und fort, und lasse sie erröten und vergehen. Und sie sollen erkennen, daß Du, Dein Name, Jehovah, allein der Allerhöchste bist auf der ganzen Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, 'Dem Sangmeister. Auf der Githith. Für die Söhne Korachs ein Psalm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Wie lieblich sind Deine Wohnungen, o Jehovah der Heerscharen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Meine Seele lechzt und verzehrt sich nach Jehovahs Vorhöfen. Mein Herz und Fleisch jubeln dem lebendigen Gott zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Auch der Vogel findet ein Haus, und die Schwalbe ein Nest für sich, darin sie ihre Brut hinlegt, Deine Altäre, Jehovah der Heerscharen, mein König und mein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Selig die, so in Deinem Hause wohnen, noch loben sie Dich. Selah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Selig der Mensch, der seine Stärke hat in Dir, in dessen Herzen Bahnen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Sie durchziehen den Talgrund des Weinens, sie machen es zum Quellenort. Auch umhüllt es der Frühregen mit Segen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Sie gehen von Kraft zu Kraft; er erscheint bei Gott in Zion.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Jehovah, Gott der Heerscharen, höre mein Gebet, nimm es zu Ohren, Gott Jakobs. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Unser Schild, Gott, siehe, und blicke auf Deines Gesalbten Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Denn besser ist ein Tag in Deinen Vorhöfen, denn tausende; ich habe erwählt, lieber an der Schwelle zu stehen im Hause meines Gottes, als zu weilen in den Zelten der Gottlosigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Denn Sonne ist und Schild Jehovah Gott; Gnade und Herrlichkeit gibt Jehovah. Er wird kein Gut vorenthalten denen, die wandeln in Rechtschaffenheit. Jehovah der Heerscharen, selig der Mensch, der auf Dich vertraut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, 'Dem Gesangmeister für die Söhne Korachs. Ein Psalm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Du hattest Wohlgefallen an Deinem Land, Jehovah, hattest Jakobs Gefangenschaft zurückgewendet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Verziehen Deines Volkes Missetat, bedeckt alle ihre Sünden. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'All Dein Wüten weggerafft, von Deines Zornes Glut Dich zurückgewendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Bringe uns zurück, Gott unseres Heils, und brich ab Deinen Unmut gegen uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Willst Du ewiglich wider uns zürnen, Deinen Zorn fortdauern lassen auf Geschlecht und Geschlecht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Willst Du nicht zurückkehren, uns beleben, auf daß Dein Volk fröhlich sei in Dir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Lasse uns sehen, Jehovah, Deine Barmherzigkeit und gib uns Dein Heil!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Ich will hören, was der Gott Jehovah redet; denn Er redet Frieden zu Seinem Volk und zu Seinen Heiligen. Aber sie sollen sich nicht wieder zur Narrheit kehren!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Nahe ist ja denen, die Ihn fürchten, Sein Heil, daß Herrlichkeit in unserem Lande wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Es sollen Barmherzigkeit und Wahrheit sich treffen, sich küssen Gerechtigkeit und Frieden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Wahrheit soll aus der Erde sprossen, und Gerechtigkeit vom Himmel schauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Auch wird Jehovah das Gute geben, und unser Land wird geben sein Gewächs. Gerechtigkeit geht vor Ihm her, und setzt ihre Tritte auf den Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, 'Jehovah, neige Dein Ohr, antworte mir; denn elend und dürftig bin ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Behüte meine Seele, denn ich bin heilig; rette Du, mein Gott, Deinen Knecht, der auf Dich vertraut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Herr, sei mir gnädig; denn zu Dir rufe ich den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Mache fröhlich die Seele Deines Knechtes, denn zu Dir, Herr, erhebe ich meine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Denn Du, Herr, bist gut und vergibst, und viel ist Deiner Barmherzigkeit gegen alle, die Dich anrufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Nimm zu Ohren, o Jehovah, mein Gebet, und horche auf die Stimme meines Flehens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'Am Tage meiner Drangsal rufe ich zu Dir; denn Du antwortest mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Keiner ist wie Du, Herr, unter den Göttern, und keine Taten wie die Deinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Alle Völkerschaften, die Du gemacht, werden kommen und anbeten, Herr, vor Dir, und Deinen Namen verherrlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Denn groß bist Du und tust Wunder, Du bist Gott allein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Weise mir, Jehovah, Deinen Weg, ich will in Deiner Wahrheit wandeln, einige mein Herz zur Furcht Deines Namens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Ich bekenne Dich, Herr, mein Gott, von ganzem Herzen und verherrliche Deinen Namen ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Denn Deine Barmherzigkeit ist groß über mir, und Du hast errettet meine Seele aus der untersten Hölle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'O Gott, Vermessene sind aufgestanden wider mich, und eine Rotte Trotziger trachtet mir nach der Seele, und setzen Dich nicht vor sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Du aber, Herr, bist ein Gott, erbarmungsvoll und gnädig, langmütig und von großer Barmherzigkeit und Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Wende Dich zu mir und sei mir gnädig, gib Deinem Knecht Deine Stärke und rette den Sohn Deiner Magd.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Ein Zeichen tue an mir zum Guten, daß es sehen, die mich hassen, und sie sich schämen. Denn Du bist mein Beistand, Jehovah, und tröstest mich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, 'Seine Grundfeste ist auf den Bergen der Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'Jehovah liebt die Tore Zions über alle Wohnungen Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Herrliches soll in dir geredet werden, Stadt Gottes. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, 'Ich werde Rahabs gedenken und Babels unter denen, die mich erkennen; siehe, das Philisterland und Zor samt Kusch; dieser ist dort geboren!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Und von Zion wird man sagen: Der Mann und der Mann ist geboren in ihr, und Er, der Allerhöchste, wird sie festigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Jehovah wird erzählen beim Aufschreiben der Völker: Dieser ist geboren allda. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'Und die Sänger wie die im Reigen: Alle meine Brunnquellen sind in Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, 'Ein Lied, ein Psalm für die Söhne Korachs. Dem Sangmeister auf Flöten zum Wechselsang. Unterweisung von dem Esrachiter Heman.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Jehovah, Gott meines Heils, bei Tag schreie ich, bei Nacht vor Dir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Lasse vor Dich kommen mein Gebet, neige Dein Ohr zu meinem Aufschrei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Denn meine Seele ist satt des Bösen und mein Leben berührt die Hölle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Ich werde geachtet wie die, so zur Grube fahren, ich werde wie der Mann, der keine Kräfte hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Zu den Toten hingestreckt, wie die Erschlagenen, die im Grabe liegen, deren Du nicht mehr gedenkst, und die von Deiner Hand abgeschnitten sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Du hast mich in der Gruben unterste gelegt, in Finsternisse, in Schlünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Dein Grimm lehnt sich auf mich und mit all Deinen Brandungen drückst Du mich nieder. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Du hast von mir entfernt meine Bekannten, zum Greuel ihnen mich gesetzt. Ich bin eingesperrt und kann nicht herauskommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Vor Elend ist mein Auge hingeschwunden. Den ganzen Tag rufe ich Dich an, Jehovah, breite meine Hände zu Dir aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Wirst Du an den Toten Wunder tun? Werden die Rephaim aufstehen, Dich bekennen? Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Wird man im Grab Deine Barmherzigkeit erzählen, Deine Wahrheit in der Zerstörung?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Kennt in der Finsternis man Deine Wunder, und Deine Gerechtigkeit im Lande der Vergessenheit?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Ich aber schreie zu Dir auf, Jehovah, und am frühen Morgen kommt Dir mein Gebet entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Warum verwirfst Du, Jehovah, meine Seele, verbirgst vor mir Dein Angesicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Elend bin ich und am Verscheiden, von Jugend auf trage ich Deine Schrecken, ich verzage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'Es fahren Deine Gluten über mich, Deine Schrecknisse vertilgen mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Sie umgeben mich wie Wasser, sie umringen mich zumal. Den Lieben und Genossen entfernst Du von mir, meine Bekannten sind im Finstern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, 'Unterweisung von Ethan, dem Esrachiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Von Jehovahs Barmherzigkeit will ich ewiglich singen, will Deine Wahrheit zu wissen tun zu Geschlecht und Geschlecht mit meinem Munde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, 'Denn ewiglich, sage ich, wird die Barmherzigkeit aufgebaut; durch sie festigst Du in den Himmeln Deine Wahrheit:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Ich habe mit Meinem Auserwählten einen Bund geschlossen, geschworen Meinem Knechte David.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Auf ewig festige Ich deinen Samen und baue deinen Thron für Geschlecht und Geschlecht. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Und die Himmel werden Deine Wunder bekennen, o Jehovah, auch Deine Wahrheit in der Versammlung der Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'Denn wer in den Ätherkreisen stellt sich Jehovah gleich? ist Jehovah gleich unter den Söhnen der Götter?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'Gott ist ein Grauen im großen Geheimrat der Heiligen, und furchtbar über alle um Ihn her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Jehovah, Gott der Heerscharen, wer ist mächtig wie Du, Jah, und Deine Wahrheit um Dich her?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Du herrschest über des Meeres Übermut; wenn es seine Wogen erhebt, beruhigst Du sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Du zerstoßest Rachab wie den Erschlagenen, mit dem Arm Deiner Stärke versprengst Du Deine Feinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Dein sind die Himmel, Dein auch die Erde; die Welt und ihre Fülle, Du hast sie gegründet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Nord und Süd, Du schufest sie, Thabor und Chermon jauchzen in Deinem Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Dein ist ein Arm mit Macht, stark ist Deine Hand, erhöht Deine Rechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Gerechtigkeit und Recht sind Deines Thrones Festigung, Barmherzigkeit und Wahrheit kommen hervor vor Dein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'Selig das Volk, das den Jubelruf kennt, Jehovah, im Lichte Deines Angesichts wandeln sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'In Deinem Namen frohlocken sie den ganzen Tag, und in Deiner Gerechtigkeit werden sie erhöht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Weil Du der Schmuck bist ihrer Stärke, und nach Deinem Wohlgefallen unser Horn erhöhst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Denn unser Schild gehört Jehovah und dem Heiligen Israels, unserem König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Damals redetest Du im Gesichte zu Deinem Heiligen und sprachst: Ich habe Beistand auf den Helden gelegt, habe Meinen Auserwählten erhöht aus dem Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Ich habe gefunden David, Meinen Knecht, mit dem Öl Meiner Heiligkeit ihn gesalbt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Mit ihm soll Meine Hand fest sein, auch Mein Arm ihn stärken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Der Feind soll ihn nicht übervorteilen, und der Verkehrtheit Sohn soll ihn nicht demütigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'Und vor seinem Angesicht will seine Dränger Ich zerstoßen, und will schlagen, die ihn hassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'Und Meine Wahrheit und Meine Barmherzigkeit soll mit ihm sein, und in Meinem Namen sich sein Horn erhöhen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'Und in das Meer will seine Hand Ich legen, und seine Rechte in die Flüsse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Er wird Mich anrufen: Mein Vater bist Du, mein Gott und meines Heiles Felsen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Auch will Ich ihn zum Erstgeborenen geben, zum Allerhöchsten den Königen der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'Auf ewig will Ich ihm behalten Meine Barmherzigkeit, und Mein Bund soll ihm bewährt sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Und Ich setze ihm Samen auf immerdar, und seinen Thron, wie der Himmel Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'Wenn seine Söhne Mein Gesetz verlassen und nicht in Meinen Rechten wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'Wenn sie entweihen Meine Satzungen, und Meine Gebote nicht halten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'So will Ich mit der Rute ihre Übertretung heimsuchen, und mit Plagen ihre Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Aber Meine Barmherzigkeit werde Ich nicht bei ihm zunichte machen und Meine Wahrheit nicht zur Lüge machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Ich werde nicht Meinen Bund entweihen, und nicht ändern, was aus Meinen Lippen ist ausgegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Einmal habe Ich bei Meiner Heiligkeit geschworen. Ich will David nicht Falsches reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Sein Same soll sein ewiglich, und wie die Sonne vor Mir sein Thron,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Wie der Mond soll er gefestigt sein ewiglich, ein treuer Zeuge an dem Wolkenhimmel. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Und Du hast verworfen und verschmäht, hast gewütet wider Deinen Gesalbten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Du hast niedergestoßen den Bund mit Deinem Knechte, hast zur Erde entweiht sein Diadem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Du durchbrachst alle seine Mauern, Du hast seine Festungen gesetzt in Entsetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Ihn plündern alle, die des Weges vorüberziehen, zur Schmach ist er geworden seinen Nachbarn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Du hast erhöht die Rechte seiner Dränger, hast fröhlich gemacht alle seine Feinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Du wandtest zurück die Schärfe seines Schwertes, und ließest ihn im Streite nicht bestehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Du hast weggeschafft seine Reinheit und seinen Thron gestürzt zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Du hast die Tage seiner Jugendzeit verkürzt, ihn mit Scham umhüllt. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Wie lange willst Du noch, Jehovah, Dich verbergen, Deinen Grimm wie Feuer brennen lassen immerdar?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Gedenke, was meine Lebenszeit ist! zu welcher Eitelkeit Du erschaffen alle Söhne des Menschen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Welcher Mann lebt und sieht nicht den Tod, der seine Seele kann entrinnen lassen aus der Hand der Hölle! Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Wo ist Deine frühere Barmherzigkeit, Herr, die Du bei Deiner Wahrheit David zugeschworen hast?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 'Gedenke, Herr, der Schmach Deiner Knechte, daß ich in meinem Busen trage die vielen Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Womit geschmäht Deine Feinde, o Jehovah, womit sie schmähen die Fußstapfen Deines Gesalbten. Gesegnet sei Jehovah in Ewigkeit! Amen und Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, 'Herr, Du warst unsere Wohnstätte in Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Bevor die Berge geboren und die Erde und die Welt gestaltet wurden, bist Du Gott von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Du läßt den Menschen zurückkehren zum Zermalmten und sprichst: Kehret zurück, ihr Menschensöhne!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Denn tausend Jahre sind in Deinen Augen, wie der Tag, der gestrige, wenn er vorübergegangen ist, und wie eine Wache in der Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Du schwemmst sie dahin, sie sind im Schlaf; am Morgen sind sie wie das Gras, das emporsproßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Am Morgen blüht und sproßt es empor, am Abend ist es abgeschnitten und vertrocknet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Vor Deinem Zorn werden wir verzehrt, und vor Deinem Grimme werden wir bestürzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Du stellst vor Dich unsere Missetaten; was wir verborgen, in Deines Angesichtes Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Denn alle unsere Tage schwinden vor Deinem Wüten, wie ein Sinnen vollenden wir unsere Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Die Tage unserer Jahre sind ihrer siebzig Jahre, und wenn es hoch kommt achtzig Jahre, und ihr Umfang ist Mühsal und Unrecht, denn es eilt schleunig dahin, als flögen wir davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'Wer kennt die Stärke Deines Zorns, und Deiner Furcht gemäß Dein Wüten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Unsere Tage zu berechnen tue uns recht kund, daß wir darbringen ein Herz der Weisheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Jehovah, kehre zurück! Wie lange? Und lasse Dich es gereuen über Deinen Knecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Sättige uns mit Deiner Barmherzigkeit am Morgen, daß wir jubeln und fröhlich sind alle unsere Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Mache uns fröhlich gemäß den Tagen, da Du uns gedemütigt hast, gemäß den Jahren, da wir Böses sahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Dein Werk erscheine Deinen Knechten, und deine Ehre über ihren Söhnen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Daß auf uns sei die Lieblichkeit Jehovahs, unseres Gottes. Und festige unserer Hände Werk bei uns, festige Du unserer Hände Werk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Wer sitzt im Verborgenen des Höchsten, und wer weilt unter dem Schatten von Schaddai,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Der spricht zu Jehovah: Meine Zuversicht und meine Feste, mein Gott, auf Den ich vertraue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Denn vor der Schlinge des Vogelstellers wird Er dich erretten, vor der Pest des Unheils.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'Mit Seinem Fittich deckt Er dich, unter Seinem Flügel sollst du deine Zuversicht haben, Schild und Tartsche ist Seine Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Nicht darfst du vor dem Schauer der Nacht dich fürchten, noch vor dem Pfeile, der bei Tage fliegt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'Vor der Pest, die im Dunkel dahingeht, vor der Seuche, die am Mittag verheert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Ob dir zur Seite fallen Tausend und Zehntausend zu deiner Rechten; an dich tritt es nicht heran.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Mit deinen Augen nur erblickst du es und siehst die Vergeltung der Ungerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Denn Du bist meine Zuversicht, Jehovah! - Den Höchsten hast du dir zu deiner Wohnstätte gesetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'Dir wird nichts Böses widerfahren, und keine Plage deinem Zelt sich nahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Denn Seinen Engeln hat Er über dir geboten, daß sie auf allen deinen Wegen dich behüten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Daß auf den Händen sie dich tragen, daß du deinen Fuß nicht stoßest an den Stein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Auf Löwen und auf Ottern wirst du treten, und zerstampfen den jungen Löwen und den Drachen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Weil er nach Mir verlangt, werde Ich ihn befreien, in beschützen, weil er Meinen Namen kennt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Er rufe Mich an, und Ich antworte ihm, bin mit ihm in der Drangsal, reiße ihn heraus und verherrliche ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Mit Länge der Tage will Ich ihn sättigen, und lasse Mein Heil ihn sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, 'Ein Psalm, ein Lied für den Sabbathtag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Gut ist es, den Jehovah zu bekennen, und Psalmen zu singen Deinem Namen, o Allerhöchster.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'Anzusagen am Morgen Deine Barmherzigkeit, und in den Nächten Deine Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Auf den zehn Saiten und auf dem Psalter, auf dem Higgajon der Harfe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Denn Du machst mich fröhlich mit Deinem Werke, Jehovah; ob den Taten Deiner Hände juble ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Wie groß, Jehovah, sind Deine Taten, o Jehovah, wie sehr tief Deine Gedanken!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Der tierische Mann weiß es nicht, und der Narr versteht es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Wen die Ungerechten sprossen wie das Kraut und alle, die Unrecht tun, blühen auf, um auf immerfort vernichtet zu werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Du aber, bist ewiglich erhöht, o Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Denn siehe, Jehovah, Deine Feinde, denn siehe Deine Feinde vergehen, alle, die Unrecht tun, werden zerstreut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'Du aber willst mein Horn, wie das des Einhorns erhöhen, und mit frischem Öle werde ich alt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Mein Auge blickt auf die, so mir nachstellen; meine Ohren hören von den Bösen, die wider mich aufstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Der Palme gleich sproßt der Gerechte auf, wie die Zeder auf dem Libanon wächst er empor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Gepflanzt sind sie in Jehovahs Haus, sie sprossen in unseres Gottes Vorhöfen empor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'Im Greisenalter bringen sie noch Frucht, sind saftreich und grün. Um anzusagen, daß Jehovah ist gerade, mein Fels, und es ist in Ihm keine Verkehrtheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Jehovah ist König, mit Hoheit ist Er angetan, Jehovah hat Sich angetan mit Stärke, Er hat Sich umgürtet; gefestigt ist die Welt, sie wankt nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Gefestigt ist Dein Thron hinfort, von Ewigkeit bist Du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Flüsse erheben, Jehovah, Flüsse erheben ihre Stimme, Flüsse erheben ihren Wogenschlag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Herrlicher als die Stimmen vieler herrlichen Wasser, als des Meeres Brandungen ist Jehovah in der Höhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Deine Zeugnisse sind sehr wahrhaftig, Deinem Hause ziemt Heiligkeit, o Jehovah, für der Tage Länge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Der Rache Gott, Jehovah, Gott der Rache, strahle hervor!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Erhebe Dich, Richter der Erde, Vergeltung gib zurück den Hochmütigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Wie lange sollen die Ungerechten, Jehovah, wie lange die Ungerechten jauchzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Sie lassen es hervorquellen, reden frech, von sich sprechen alle, die Unrecht tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Dein Volk zerstoßen sie, Jehovah, und bedrücken Dein Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Die Witwe und den Fremdling würgen sie und morden Waisen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'Und sprechen: Jah sieht es nicht, und Jakobs Gott merkt es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Merkt auf, ihr Unvernünftigen im Volk, und wann wollt ihr Narren klug werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Er, Der das Ohr gepflanzt, sollte Er nicht hören, Der das Auge bildete, nichts erblicken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Der Völkerschaften züchtigt, sollte Er nicht rügen, Er, Der den Menschen Erkenntnis lehrt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Jehovah kennt die Gedanken des Menschen, daß sie nichtig sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Selig der Mann, den Du, Jah, züchtigst, und den aus Deinem Gesetz Du lehrst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'Ihn zu beruhigen vor bösen Tagen, bis der Graben für den Ungerechten gegraben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Denn Jehovah gibt Sein Volk nicht dahin und verläßt Sein Erbe nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Denn zur Gerechtigkeit kehrt das Gericht zurück, und ihm folgen alle, die geraden Herzens sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Wer steht für mich wider die Bösen auf? Wer stellt sich für mich wider die, so Unrecht tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Wäre nicht Jehovah mein Beistand, um ein Weniges, so wohnte meine Seele in der Stille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Spreche ich: Es wankt mein Fuß, so unterstützt, Jehovah, Deine Barmherzigkeit mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Wenn viel Bekümmernis ist in meinem Inneren, so ergötzen meine Seele Deine Tröstungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Ist Dir verbündet der Thron des Unheils, der Mühsal bildet wider die Satzung?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Sie rotten sich zusammen wider des Gerechten Seele, und verdammen unschuldiges Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'Doch ist Jehovah meine Burgfeste geworden und mein Gott der Fels meiner Zuversicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'Ihr Unrecht gib ihnen zurück, und in ihrer Bosheit vertilge sie, es vertilge sie Jehovah, unser Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Kommet, laßt uns Jehovah lobpreisen, lasset uns aufjauchzen dem Felsen unseres Heils.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Laßt uns mit Bekennen vor Sein Angesicht kommen, laßt uns Ihm aufjauchzen mit Psalmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Denn ein großer Gott ist Jehovah, und ein großer König über alle Götter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'In Dessen Hand sind der Erde Ergründungen, und Dessen sind der Berge Kräfte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Dessen ist das Meer und Er hat es gemacht, und das Trockene, das Seine Hände bildeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Kommt, laßt uns anbeten und uns beugen und knien vor Jehovah, Der uns gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Denn Er ist unser Gott und wir sind Seiner Weide Volk, und die Schafe Seiner Hand, diesen Tag, wenn ihr auf Seine Stimme hört,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'Verhärtet nicht euer Herz, wie in Meribah, wie am Tage Massahs in der Wüste;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'Wo eure Väter Mich versuchten, Mich prüften, auch Mein Werk sahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Vierzig Jahre hatte Ich Verdruß an dem Geschlecht, und Ich sprach: Es ist ein Volk, das irren Herzens ist, und sie erkennen Meine Wege nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Denen Ich in Meinem Zorn schwur: Sie sollen nicht eingehen zu Meiner Ruhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Singet ein neues Lied dem Jehovah, singet dem Jehovah, die ganze Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Singet Jehovah, segnet Seinen Namen! Verkündigt Sein Heil von Tag zu Tag!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Erzählt Seine Herrlichkeit unter den Völkerschaften, unter allen Völkern Seine Wunder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Denn groß und sehr zu loben ist Jehovah. Furchtbar ist Er über allen Göttern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Denn alle Götter der Völker sind Götzen, aber Jehovah machte die Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Majestät ist und Ehre vor Seinem Angesicht, Stärke und Schmuck in Seinem Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Gebt her Jehovah, ihr Familien der Völker, gebt her Jehovah Herrlichkeit und Stärke!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Gebt her Jehovah die Herrlichkeit Seines Namens, bringt Speiseopfer und kommt in Seine Vorhöfe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Jehovah betet an in der Ehre der Heiligkeit! Es kreiße vor Ihm die ganze Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Sprecht unter den Völkerschaften: Jehovah ist König; auch ist gefestigt die Welt, nicht wankt sie. Er schafft Recht den Völkern in Geradheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Es seien fröhlich die Himmel und die Erde frohlocke, es brause das Meer und seine Fülle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'Das Gefilde jauchze und alles, was darauf, dann lasset lobpreisen alle Bäume des Waldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'Vor Jehovah; denn Er kommt, Er kommt zu richten die Erde. Er richtet die Welt in Gerechtigkeit und die Völker in Seiner Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Jehovah ist König, die Erde frohlocke, es seien fröhlich die vielen Inseln!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Wolke und Wetternacht sind rings um Ihn, Gerechtigkeit und Recht sind Seines Thrones Festigung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Feuer geht vor Seinem Angesicht und setzt in Flammen Seine Dränger ringsumher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Seine Blitze erleuchten die Welt; die Erde sieht es und kreißet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Wie Wachs zerschmelzen Berge vor Jehovahs Angesicht, vor dem Angesicht des Herrn der ganzen Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Seine Gerechtigkeit sagen an die Himmel, und alle Völker sehen Seine Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Beschämt werden alle Diener der Schnitzbilder, die, so sich rühmen der Götzen! Betet Ihn an, ihr Götter alle!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Zion hört es und ist fröhlich, Jehudahs Töchter frohlocken ob Deiner Gerichte, o Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Denn Du, Jehovah, bist der Höchste über der ganzen Erde, bist sehr erhöht über alle Götter!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Die ihr Jehovah liebet, haßt das Böse. Er hütet die Seelen Seiner Heiligen, Er errettet sie aus der Ungerechten Händen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Licht wird gesät für den Gerechten, Fröhlichkeit für die, so geraden Herzens sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Seid fröhlich in Jehovah, ihr Gerechten, und bekennt dem Andenken Seiner Heiligkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, 'Ein Psalm. Singet Jehovah ein neues Lied; denn Wunder hat Er getan; gerettet hat Ihn Seine Rechte und der Arm Seiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Jehovah hat kundgetan Sein Heil; vor der Völkerschaften Augen hat Seine Gerechtigkeit Er geoffenbart.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Er gedachte Seiner Barmherzigkeit und Seiner Wahrheit dem Hause Israels, alle Enden der Erde haben das Heil unseres Gottes gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Jubelt Jehovah, alle die Erde, brechet aus und lobpreiset und singet Psalmen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Singt Psalmen dem Jehovah zur Harfe, auf der Harfe und des Psalmen Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'Mit Trompeten und Schall der Posaune jauchzet auf vor dem König Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Es brause Ihm das Meer und seine Fülle; die Welt und die darin wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Die Flüsse sollen in die Hände klatschen, die Berge aufjubeln allzumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'Vor Jehovah; denn Er kommt zu richten die Erde; Er richtet die Welt in Gerechtigkeit und die Völker in Geradheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Jehovah ist König, die Völker zittern. Er sitzt auf den Cheruben, es wankt die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Groß ist Jehovah in Zion und Er ist erhöht über alle Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Sie sollen bekennen Deinen Namen. Groß und furchtbar, heilig ist er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'Und die Stärke des Königs liebt das Recht. Du festigst, was gerade ist. Recht und Gerechtigkeit tust Du in Jakob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Erhöht Jehovah, unseren Gott, und betet an vor Seiner Füße Schemel, - heilig ist Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mose und Aharon unter Seinen Priestern, und Samuel unter denen, die Seinen Namen anriefen. Sie riefen zu Jehovah, und Er antwortete ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'Gott redete zu ihnen in der Wolkensäule. Sie hielten Seine Zeugnisse, und die Satzung gab Er ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Jehovah, unser Gott, Du antwortest ihnen, warst ihnen ein Gott, Der verzieh, aber rächte ihre Handlungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Erhöht Jehovah, unseren Gott, und betet an am Berge Seiner Heiligkeit; denn heilig ist Jehovah, unser Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, 'Ein Psalm des Bekennens. Jauchzet auf zu Jehovah, die ganze Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Dienet Jehovah in Fröhlichkeit! Kommt vor Sein Angesicht mit Lobpreisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Erkennet, daß Jehovah Selbst Gott ist, Er hat uns gemacht, und nicht wir selbst, Sein Volk und die Herde Seiner Weide.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Geht ein zu Seinen Toren mit Bekennen, in Seine Vorhöfe mit Lob, bekennet Ihn, segnet Seinen Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Denn gut ist Jehovah, ewig ist Seine Barmherzigkeit, und auf Geschlecht und Geschlecht Seine Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, 'Von Barmherzigkeit und Recht will ich singen, will Dir, Jehovah, Psalmen singen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Ich will den Rechtschaffenen unterweisen im Wege. Wann kommst Du zu mir? Ich will wandeln in Rechtschaffenheit meines Herzens inmitten meines Hauses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Ich will kein Wort Belials vor meine Augen stellen. Das Tun der Abtrünnigen hasse ich. Nicht soll es mir anhangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Ein verdrehtes Herz weiche weg von mir. Von Bösem will ich nichts wissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Wer seinem Genossen im Verborgenen nachredet, den vertilge ich; den, der hochmütig von Augen und weit von Herzen ist, vermag ich nicht zu ertragen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Meine Augen sind auf den Treuen des Landes, daß sie bei mir sitzen; wer auf rechtschaffenem Weg geht, soll mein Diener sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Nicht soll sitzen inmitten meines Hauses, wer Trug tut; wer Lügen redet, soll nicht gefestigt werden vor meinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Am Morgen vertilge ich alle Ungerechten des Landes, daß ich ausrotte alle, die Unrecht tun, aus Jehovahs Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, 'Gebet eines Elenden, der verzagt und vor Jehovah sein Sinnen ausschüttet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Jehovah, höre mein Gebet, und zu Dir komme mein Angstschrei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Verbirg Dein Angesicht nicht von mir; am Tag meiner Drangsal neige zu mir Dein Ohr; am Tage, da ich rufe, eile, antworte mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Denn meine Tage sind vollendet wie Rauch, und meine Gebeine entbrannt wie ein Feuerbrand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Geschlagen wie das Kraut ist mein Herz und vertrocknet, daß ich vergaß, mein Brot zu essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Von meines Seufzens Stimme klebt mein Gebein an meinem Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Dem Pelikan der Wüste gleich bin ich, bin wie der Uhu der Einöden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Ich bin wach, bin wie der vereinsamte Vogel auf dem Dach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Den ganzen Tag schmähen mich meine Feinde; die wider mich rasen, schwören bei mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'Denn Asche esse ich wie Brot, und mische mit Weinen meinen Trank.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Vor Deinem Unwillen und Deiner Entrüstung; denn Du hobst mich auf und warfst mich hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Meine Tage sind wie der sich neigende Schatten, und wie das Kraut vertrockne ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Doch Du, Jehovah, sitzest ewiglich, und Dein Gedächtnis zu Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Du wirst aufstehen und Zions Dich erbarmen; denn Zeit ist es, ihr gnädig zu sein, denn die bestimmte Zeit ist gekommen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'Denn Deine Knechte haben Wohlgefallen an seinen Steinen, und sind gnädig gegen seinen Staub.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Und die Völkerschaften fürchten Jehovahs Namen, und alle Könige der Erde Deine Herrlichkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'Daß Zion hat gebaut Jehovah, daß Er in Seiner Herrlichkeit erschienen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Er hat Sich gewandt zu dem Gebete des Einsamen, und nicht verachtet ihr Gebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'Dies sei geschrieben für ein späteres Geschlecht. Ein Volk, das erschaffen wird, soll Dich loben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'Denn von der Höhe Seines Heiligtums schaut Er herab, Jehovah blickt von den Himmeln auf die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'Daß Er den Angstruf des Gebundenen höre und losmache des Todes Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'Auf daß man in Zion von dem Namen Jehovahs erzähle und von Seinem Lobe in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Wenn sich die Völker zusammenziehen allzumal, und die Königreiche, Jehovah zu dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Er demütigt auf dem Wege meine Kraft, Er kürzt meine Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Ich spreche: Mein Gott, nimm mich nicht hinauf in der Hälfte meiner Tage. Deine Jahre sind für ein Geschlecht der Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Die Erde, die vordem Du gegründet, und die Himmel, Deiner Hände Werk,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Sie werden vergehen, aber Du bestehst; und wie ein Kleid veralten sie alle; Du wandelst sie wie ein Gewand und sie sind verwandelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Du aber bist Derselbe, und Deine Jahre gehen nie aus. Die Söhne Deiner Knechte werden wohnen, und ihr Same wird vor Dir gefestigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, 'Segne Jehovah, meine Seele, und all mein Inneres den Namen Seiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Segne, Jehovah, meine Seele, und vergiß nicht aller Seiner Wohltaten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Der dir vergibt alle deine Missetaten, Der alle deine Krankheiten heilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'Der aus der Grube dein Leben erlöset, Der dich krönt mit Barmherzigkeit und Erbarmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'Der deinen Mund mit Gutem sättigt, daß deine Jugend gleich dem Adler sich erneut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Jehovah tut Gerechtigkeit und Gericht allen Niedergedrückten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Kund tat Er Mose Seine Wege, Seine Handlungen den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Erbarmungsvoll und gnädig ist Jehovah, langmütig und von großer Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Er hadert nicht immerdar, noch trägt Er ewiglich nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Nicht hat Er uns nach unseren Sünden getan, noch vergalt Er uns nach unseren Missetaten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Denn so hoch der Himmel über der Erde ist, so mächtig ist Seine Barmherzigkeit für die, so Ihn fürchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'So fern der Aufgang ist vom Abend, so weit von uns entfernt Er unsere Übertretungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Wie sich ein Vater über die Söhne erbarmt, erbarmt Jehovah derer Sich, so Ihn fürchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Denn Er kennt, was für ein Gebilde wir sind, Er gedenkt, daß wir sind Staub.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Der Mensch, wie Gras sind seine Tage; wie des Feldes Blume, also blüht er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'Wenn der Wind über sie dahingeht, ist sie nicht mehr, und man erkennt nicht mehr ihren Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'Jehovahs Barmherzigkeit aber ist von Ewigkeit zu Ewigkeit über die, so Ihn fürchten, und Seine Gerechtigkeit auf der Söhne Söhne,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'Auf die, so halten Seinen Bund und Seiner Ordnungen gedenken, daß sie danach tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Jehovah hat im Himmel Seinen Thron bereitet, und Sein Reich herrscht über alles.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Segnet Jehovah, ihr, Seine Engel, ihr Helden der Kraft, die Sein Wort tun, auf daß man auf die Stimme Seines Wortes höre!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Segnet Jehovah, alle Seine Heerscharen, Seine Diener, die nach Seinem Wohlgefallen tun!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Segnet Jehovah, alle Seine Werke an allen Orten Seiner Herrschaft! Segne, meine Seele, den Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Segne, Jehovah, meine Seele! Jehovah, mein Gott, Du bist sehr groß. Majestät und Ehre hast Du angezogen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'Er umhüllt Sich mit Licht wie mit einem Gewand, Er spannt die Himmel aus wie einen Teppich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Er zimmert mit Wassern Seine Söller, setzt dichte Wolken zu Seinem Wagen und geht auf den Flügeln des Windes einher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'Er macht zu Seinen Boten die Winde, zu Seinen Dienern flammend Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Er hat die Erde auf ihre Grundlagen gegründet, daß sie nicht wankt in Ewigkeit und immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Mit dem Abgrund hast Du sie bedeckt, wie mit einem Anzug; die Wasser stehen auf den Bergen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Vor Deinem Drohen fliehen sie, enteilen vor der Stimme Deines Donners.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'Die Berge steigen auf, die Talgründe sinken hernieder zum Ort, den Du für sie gegründet hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Du setztest eine Grenze, die sie nicht überschreiten; sie kehren nicht zurück, die Erde zu bedecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Er sendet Quellen in die Bachtäler; zwischen den Bergen gehen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'Sie tränken alle wilden Tiere des Gefildes; Waldesel löschen ihren Durst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Des Himmels Gevögel wohnen an ihnen, aus dem Gezweig geben sie ihre Stimme hervor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'Von Seinen Söllern aus tränkt Er die Berge, von Seiner Werke Frucht wird satt die Erde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'Er läßt Gras sprossen für das Vieh und Kraut zum Dienst des Menschen, damit er Brot herausbringe aus der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'Und Wein macht fröhlich des Menschen Herz; daß von Öl sein Antlitz glänze und Brot das Herz des Menschen labe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Jehovahs Bäume werden satt, die Zedern Libanons, die Er gepflanzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'Daselbst nisten die Vögel; der Storch hat sein Haus auf Tannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Die hohen Berge sind der Gemsen, der Kaninchen Schirm die Felsenklippen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Er hat den Mond gemacht für die bestimmten Festzeiten, die Sonne weiß ihren Niedergang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Du setzest Finsternis und es wird Nacht; da kriechen hervor alle wilden Tiere des Waldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'Die jungen Löwen brüllen nach dem Zerfleischen, und suchen von Gott ihre Speise.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Die Sonne geht auf, sie sammeln sich und lagern sich in ihren Wohnstätten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Der Mensch geht aus an sein Werk, und zu seinem Dienst bis an den Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Wie viel sind Deiner Werke, o Jehovah, sie alle hast mit Weisheit Du gemacht. Voll ist die Erde Deines Besitztums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Da ist das Meer, groß und weit zu beiden Händen, dort sind Kriechtiere auch ohne Zahl, kleine Getiere und große.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Da gehen Schiffe, der Leviathan, den Du gebildet, um darin zu scherzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Sie alle warten auf Dich, daß Du ihnen ihre Speise gebest zu seiner Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Du gibst ihnen, sie lesen auf, Du tust Deine Hand auf, sie werden mit Gutem gesättigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Du verbirgst Dein Angesicht, sie sind bestürzt, Du raffst ihren Geist weg, sie verscheiden und kehren zu ihrem Staub zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Sendest Du Deinen Geist aus, sind sie geschaffen, und Du erneuerst das Angesicht des Bodens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Jehovahs Herrlichkeit sei in Ewigkeit. Es sei fröhlich Jehovah in Seinen Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Er blickt zur Erde, und sie bebt. Er rührt die Berge an, und sie rauchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'In meinem Leben will ich Jehovah singen, will Psalmen singen meinem Gott, weil ich bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'Es möge Ihm genehm sein mein Nachsinnen! Ich will fröhlich sein in Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Möchten die Sünder ein Ende nehmen von der Erde, und die Ungerechten nicht mehr sein! Segne Jehovah, meine Seele! Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Bekennet Jehovah, rufet Seinen Namen an! Macht Seine Taten kund unter den Völkern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Singet Ihm, singt Psalmen, sinnet nach über alle Seine Wunder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Rühmet euch des Namens Seiner Heiligkeit; es sei fröhlich das Herz derer, die Jehovah suchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Nach Jehovah fragt und nach Seiner Stärke; sucht beständig Sein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Gedenket Seiner Wunder, die Er getan, Seiner Wahrzeichen und der Gerichte Seines Mundes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'Ihr Samen Abrahams, Seines Knechtes, ihr Söhne Jakobs, Seine Auserwählten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'Er, Jehovah, ist unser Gott; auf der ganzen Erde sind Seine Gerichte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'In Ewigkeit gedenkt Er Seines Bundes, des Wortes, das Er geboten, für tausend Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'Den Er mit Abraham geschlossen, und Seines Schwures an Isaak.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'Und Er ließ ihn erstehen für Jakob zur Satzung, für Israel zu ewigem Bunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'Und sprach: Dir will Ich geben das Land Kanaan zur Schnur deines Erbes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Als sie noch Leute gering an Zahl waren, nur wenige, und Fremdlinge darinnen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'Von Völkerschaft zu Völkerschaft zogen sie, von einem Königreich zu einem anderen Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'Er ließ keinen Menschen sie niederdrücken, und rügte Könige um sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Rührt nicht an Meine Gesalbten und tut Meinen Propheten nichts Böses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Er rief den Hunger über das Land, Er brach jeglichen Stab des Brotes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Er sandte ihnen einen Mann voraus; zum Knechte ward Joseph verkauft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'In Fußschellen zwangen sie seinen Fuß; in Eisen kam seine Seele,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'Bis zur Zeit, daß Sein Wort kam, Jehovahs Rede ihn läuterte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Der König sandte und ließ ihn los, der Herrscher der Völker, und tat ihm auf,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Er setzte ihn zum Herrn für sein Haus und zum Herrscher über all sein Besitztum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'Damit er nach seinem Willen binde seine Obersten, und weise mache seine Ältesten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Und Israel kam nach Ägypten, und Jakob hielt sich auf als Fremdling im Lande Chams.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Und Er machte Sein Volk sehr fruchtbar und zahlreicher, denn seine Dränger waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Und Er verwandelte ihr Herz, Sein Volk zu hassen und wider Seine Knechte trüglich zu handeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Er sandte Mose, Seinen Knecht, und Aharon, den Er auserwählt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Sie taten unter ihnen Seiner Zeichen Worte und Wahrzeichen im Lande Cham.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Er sandte Finsternis und es ward finster; und sie widersetzten sich Seinen Worten nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Er verwandelte in Blut ihre Wasser und ließ ihre Fische sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Von Fröschen wimmelte ihr Land, in den Kammern ihrer Könige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Er sprach es und es kam der Arob, die Läuse in all ihrer Grenze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Ihre Platzregen machte Er zu Hagel, des Feuers Flammen in ihrem Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'Und ihren Weinstock schlug Er und ihren Feigenbaum, und brach den Baum an ihrer Grenze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Er sprach es und es kam die Heuschrecke und Grille sonder Zahl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'Und alles Kraut in ihrem Lande fraß sie, und fraß die Frucht ihres Bodens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Und Er schlug alle Erstgeburt in ihrem Lande, die Erstlinge all ihrer Vollkraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Und mit Silber und Gold brachte Er sie aus. Und keiner strauchelte in seinen Stämmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Ägypten ward fröhlich über ihren Auszug; denn Schauer vor ihnen war auf sie gefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Er breitete als Decke aus die Wolke, und Feuer, ihnen zu leuchten des Nachts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Er erbat sich es und Er ließ Wachteln kommen, und Er sättigte sie mit dem Brote der Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Er tat den Felsen auf und es flossen Wasser, ein Fluß lief durch die Dürre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Denn Er gedachte des Wortes Seiner Heiligkeit an Abraham, Seinen Knecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Und in Freuden führte Er Sein Volk aus, mit Lobpreisungen Seine Auserwählten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'Und Er gab ihnen der Völkerschaften Lande, und die Mühsal der Volksstämme nahmen sie ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'Auf daß sie hielten Seine Satzungen und bewahrten Seine Gesetze. Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Hallelujah! Bekennet Jehovah, denn Er ist gut, denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Wer kann aussagen die Machttaten Jehovahs, kann hören lassen all Sein Lob?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'Selig, die das Recht halten und Gerechtigkeit tun alle Zeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Gedenke mein, Jehovah, mit dem Wohlgefallen für Dein Volk, und suche mich heim mit Deinem Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'Daß ich sehe das Gute Deiner Auserwählten, daß ich fröhlich sei in der Fröhlichkeit Deiner Völkerschaften, mich rühme mit Deinem Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Wir sündigten mit unseren Vätern, wir haben Missetat, Ungerechtigkeit begangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Unsere Väter in Ägypten begriffen Deine Wunder nicht, gedachten nicht Deiner vielen Barmherzigkeit, und sie widersetzten sich am Meer, am Meere des Schilfs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Er aber rettete sie um Seines Namens willen, um Seine Macht kund zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Und Er bedrohte das Schilfmeer, und es trocknete aus, und Er ließ sie durch Abgründe gehen wie durch die Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Und Er rettete sie aus des Hassers Hand, und aus des Feindes Hand erlöste Er sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Und Wasser bedeckten ihre Dränger, nicht einer blieb von ihnen übrig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Und sie glaubten an Seine Worte, sie sangen Sein Lob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Eilig hatten Seine Werke sie vergessen, warteten nicht auf Seinen Ratschluß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'Und es gelüstete sie in der Wüste ein Gelüste, und sie versuchten Gott im Wüstenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'Und Er gab ihnen ihr Erbetenes, sandte aber Magerkeit in ihre Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Und sie eiferten wider Mose in dem Lager, wider Aharon, den Heiligen Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'Die Erde tat sich auf und verschlang Dathan und überdeckte Abirams Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'Und es brannte Feuer in ihrer Gemeinde, und die Flamme entflammte die Ungerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Am Choreb machten sie ein Kalb und beteten das Gußbild an,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'Und sie vertauschten ihre Herrlichkeit mit dem Vorbilde eines Ochsen, der das Kraut frißt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Sie vergaßen des Gottes, Der sie gerettet, Der in Ägypten Großes tat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'Wunder im Lande Cham, Furchtbares an dem Meere des Schilfs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Und Er sagte, Er wollte sie vernichten, wenn Mose, Sein Auserwählter, nicht vor Ihm vor den Riß gestanden wäre, um Seinen Grimm vom Verderben zurückzuwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Und sie verschmähten das begehrte Land, sie glaubten Seinem Worte nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'Und sie beschwerten sich in ihren Zelten, und hörten nicht auf Jehovahs Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Und Er hob Seine Hand auf wider sie, sie zu fällen in der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'Und ihren Samen unter die Völkerschaften fallen zu lassen, und sie in die Länder zu zersprengen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Und sie klammerten sich an Baal-Peor und aßen die Opfer der Toten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Und reizten Ihn durch ihr Tun, daß eine Plage ausbrach unter ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Und Phinechas stand da und schlichtete, und der Plage ward Einhalt getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'Und ihm ward es zur Gerechtigkeit gerechnet ins Geschlecht und Geschlecht in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Und sie reizten zur Entrüstung am Wasser Meribah, und es war übel mit Mose um ihretwillen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'Denn sie erbitterten den Geist ihm, und es entfuhr seinen Lippen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Sie vernichteten die Völker nicht, wie Jehovah zu ihnen gesprochen hatte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'Und vermengten sich mit den Völkerschaften und lernten ihr Tun;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'Und sie dienten ihren Götzenbildern und sie wurden ihnen zum Fallstrick.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'Und sie opferten den Dämonen ihre Söhne und Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'Und sie vergossen unschuldig Blut, das Blut ihrer Söhne und ihrer Töchter, die sie den Götzenbildern Kanaans opferten, und das Land ward durch Blut entheiligt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'Und sie verunreinigten sich durch ihre Werke, und buhlten durch ihr Tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Und es entbrannte Jehovahs Zorn wider Sein Volk, und Sein Erbe ward Ihm zum Greuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'Und Er gab sie in der Völkerschaften Hand, und ihre Hasser herrschten über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'Und ihre Feinde unterdrückten sie, und sie wurden unter ihre Hand gebeugt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Viel Male errettete Er sie, doch sie widersetzten sich in ihrem Ratschlusse, und schwanden dahin in ihrer Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Und Er sah ihre Drangsal, wie Er ihren Angstschrei hörte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'Und Er gedachte ihnen an Seinen Bund, und es gereute Ihn nach Seiner vielen Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'Und Er ließ sie Erbarmen finden vor allen, die sie gefangen führten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Rette uns, Jehovah, unser Gott, und bringe uns zusammen aus den Völkerschaften, auf daß wir bekennen den Namen Deiner Heiligkeit und preisen Dein Lob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Gesegnet sei Jehovah, der Gott Israels, von Ewigkeit und zu Ewigkeit! und alles Volk spreche: Amen. Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Bekennet Jehovah; denn Er ist gut, denn Seine Barmherzigkeit ist ewig,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Sprechen die Erlösten Jehovahs, die Er aus des Drängers Hand erlöst hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'Und sie zusammen hat gebracht aus den Ländern vom Aufgang und vom Abend, von Mitternacht und vom Meere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Sie irrten in der Wüste, im Wüstenland, des Weges, sie fanden keine Stadt, um darinnen zu wohnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'Hungernd, auch dürstend, ihre Seele verzagte in ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Und sie schrien zu Jehovah in ihrer Drangsal, aus ihren Ängsten rettete Er sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'Und ließ sie den geraden Weg gehen, daß sie zur Stadt gingen, um darinnen zu wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Sie sollen Jehovah bekennen ob Seiner Barmherzigkeit, und ob Seiner Wunder an den Söhnen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'Daß Er sättigt die lechzende Seele, und die hungernde Seele mit Gutem erfüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Die, so in Finsternis und Todesschatten saßen, im Elend und in Eisen gebunden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'Weil Gottes Reden sie sich widersetzt, und den Rat des Höchsten gelästert hatten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'Und Er beugte ihr Herz durch Mühsal. Sie strauchelten, und niemand stand ihnen bei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Und sie schrien zu Jehovah in ihrer Drangsal, und Er rettete sie aus ihren Ängsten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'Und brachte sie heraus aus Finsternis und Todesschatten, und riß ab ihre Bande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Sie sollen Jehovah bekennen ob Seiner Barmherzigkeit, und ob Seiner Wunder an den Söhnen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'Daß Er eherne Türen brach und eiserne Riegel zerhieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Die Törichten, ob dem Wege ihrer Übertretung und ob ihren Missetaten wurden sie gedemütigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Daß ihrer Seele vor aller Speise graute, und sie die Tore des Todes berührten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Und sie schrien zu Jehovah in ihrer Drangsal, aus ihren Ängsten rettete Er sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'Er sandte Sein Wort und heilte sie, und ließ sie entrinnen aus ihren Gruben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Sie sollen Jehovah bekennen ob Seiner Barmherzigkeit und ob Seiner Wunder an den Söhnen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'Und sie sollen Opfer des Dankes opfern, und erzählen Seine Taten mit Lobpreisung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Die hinabsteigen auf das Meer in Schiffen, die Geschäft tun auf vielen Wassern;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'Sie sehen Jehovahs Taten, und Seine Wunder in dem Schlunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Er spricht und läßt erstehen des Sturmes Wind, der seine Wogen emporhebt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'Sie steigen hinauf zum Himmel, sie fahren hinab in Abgründe, ihre Seele zerfließt vor Bösem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'Sie taumeln und schwanken wie ein Trunkener, und all ihre Weisheit ist verschlungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Und sie schreien zu Jehovah in ihrer Drangsal, und aus ihren Ängsten bringt Er sie heraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'Er läßt zur Stille erstehen den Sturm, und ihre Wogen schweigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Und sie sind fröhlich, daß sie zur Ruhe kommen, und Er führt sie zum Hafen ihrer Lust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Sie sollen Jehovah bekennen ob Seiner Barmherzigkeit und ob Seiner Wunder an des Menschen Söhnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'Und sie sollen Ihn erhöhen in der Versammlung des Volkes, und Ihn loben auf dem Sitze der Alten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Flüsse setzt Er zur Wüste, die Ausflüsse des Wassers zum Durstland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'Ein fruchtbar Land zum Salzgrund, ob der Bosheit derer, die darin wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Die Wüste setzt Er zum Teich der Wasser, und dürres Land zu Ausflüssen der Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'Und läßt Hungrige dort wohnen, daß eine Stadt sie bereiten zum Wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'Und daß Felder sie besäen, und Weinberge pflanzen und machen des Ertrages Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Und Er segnet sie, daß sie sich sehr mehren, und macht ihres Viehs nicht wenig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Und ihrer waren wenig und sie beugten sich ob des Zwanges von Übel und Gram.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'Er goß Verachtung auf die Edlen und ließ sie irren in der Öde ohne Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'Und Er hebt in die Höhe aus dem Elend den Dürftigen und setzt die Familien wie eine Herde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Die Redlichen sehen es und sind fröhlich, und aller Verkehrtheit wird ihr Mund zugestopft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Wer ist weise und behält dies, und versteht Jehovahs Barmherzigkeit?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, 'Ein Lied, ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Mein Herz ist bereit, o Gott, ich will singen, will Psalmen singen, auch meine Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Psalter und Harfe wachet auf, ich will das Morgenrot wecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Ich will Dich bekennen, Jehovah, unter den Völkern, und Dir Psalmen singen unter den Volksstämmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Denn über die Himmel groß ist Deine Barmherzigkeit, und Deine Wahrheit bis an die Ätherkreise.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Erhöhe Dich über die Himmel, o Gott, und über die ganze Erde Deine Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Auf daß gerettet werden Deine Lieben, rette mit Deiner Rechten und antworte mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Gott hat geredet in Seiner Heiligkeit: Ich will jauchzen, Ich will Schechem verteilen und den Talgrund Sukkoth ausmessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Mein ist Gilead, Mein Menascheh, und Ephraim ist Meines Hauptes Stärke, Mein Gesetzgeber Jehudah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Moab, der Topf Meines Waschens, über Edom werfe Ich Meinen Schuh, über Philistäa will Ich jubeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Wer wird mich geleiten zu der festen Stadt, wer mich bis Edom führen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Nicht Du, o Gott, Der Du uns verstoßen, und nicht auszogst, o Gott in unseren Heerscharen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'Gib Du uns Beistand von dem Dränger. Ist eitel doch das Heil des Menschen. Mit Gott wollen wir Tapferes tun; und Er zertritt unsere Dränger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, 'Gott meines Lobes, schweig nicht stille!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Denn der Mund des Ungerechten und der Mund des Truges haben wider mich sich geöffnet, sie reden mit mir mit Zungen der Lüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'Und mit des Hasses Worten umgeben sie mich, und streiten ohne Ursache wider mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Für meine Liebe sind sie meine Widersacher; ich aber bin im Gebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'Und sie tun Böses mir, statt Gutes, und Haß für meine Liebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Bestelle einen Ungerechten über ihn, und lasse Satanas ihm zur Rechten stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Wird er gerichtet, gehe er als Ungerechter hervor und zur Sünde werde ihm sein Gebet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Es sollen seiner Tage wenig sein, sein Amt nehme ein anderer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Seine Söhne seien Waisen und sein Weib eine Witwe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'Und lasse umherwandern seine Söhne und betteln und nachsuchen aus ihren Verödungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Es umstricke der Gläubiger alles, was er hat, und Fremde rauben seine Arbeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Keiner reiche ihm Barmherzigkeit dar, und keiner sei gnädig seinen Waisen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Seine Nachkommen werden ausgerottet! ihr Name im anderen Geschlecht ausgewischt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'Es müsse seiner Väter Missetat bei Jehovah gedacht und seiner Mutter Sünde nicht ausgewischt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Sie sollen beständig vor Jehovah sein, daß ihr Gedächtnis Er ausrotte von der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Weil Er nicht gedachte Barmherzigkeit zu tun, und den elenden Mann und den Dürftigen verfolgte und den, so verzagten Herzens, daß er ihn töte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'Und er liebte den Fluch, so komme der über ihn; und er hatte keine Lust am Segen, so sei er ferne von ihm!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Und er ziehe Fluch an, wie sein Obergewand, und er komme in sein Inneres wie Wasser, und wie Öl in seine Gebeine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Er sei ihm wie ein Kleid, das ihn umhüllt, und wie eine Umgürtung, die beständig ihn gürtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'Dies sei die Belohnung meiner Widersacher von Jehovah, und derer, so Böses reden wider meine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Und Du, Jehovah, Herr, handle mit mir um Deines Namens willen; denn gut ist Deine Barmherzigkeit, errette mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Denn elend bin ich und dürftig, und durchbohrt ist mein Herz in meinem Inneren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Wie der Schatten, wenn er sich neigt, gehe ich dahin, wie die Heuschrecke werde ich abgeschüttelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Meine Knie straucheln vom Fasten, und mein Fleisch fällt ab vom Fett.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Und ich bin ihnen zur Schmach; sie sehen mich und nicken mit dem Kopf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Stehe mir bei, Jehovah, mein Gott, rette mich nach Deiner Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'Und lasse sie wissen, daß das Deine Hand ist, daß Du, Jehovah, es tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Fluchen sie, so segne Du, stehen sie auf, so lasse sie beschämt werden! Aber Dein Knecht müsse fröhlich sein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Meine Widersacher müssen mit Schande angezogen werden, und mit ihrer Scham umhüllt werden wie mit einem Oberkleid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Ich will Jehovah sehr danken mit meinem Mund, und in Vieler Mitte will ich Ihn loben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'Denn Er steht dem Dürftigen zur Rechten, ihn zu retten von denen, die seine Seele richten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, 'Jehovah sprach zu Meinem Herrn: Setze Dich zu Meiner Rechten, bis Ich Deine Feinde zum Schemel Deiner Füße lege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Das Zepter Deiner Stärke wird aussenden Jehovah aus Zion; herrsche inmitten Deiner Feinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Dein Volk ist Willigkeit am Tage Deiner Tapferkeit, in den Ehren der Heiligkeit. Aus dem Mutterschoße des Morgenrots hast Du den Tau Deiner Geburt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Jehovah hat es geschworen, und es gereut Ihn nicht: Ewiglich sollst Du Priester sein nach Meinem Worte Malkizedek.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Der Herr zu Deiner Rechten zerschmettert am Tage Seines Zornes Könige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'Er schafft Recht unter den Völkerschaften, Er füllt mit Leichen, Er zerschmettert das Haupt über viel Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Aus dem Bach auf dem Wege wird Er trinken, darum erhöht Er das Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Hallelujah! Bekennen will ich Jehovah von ganzem Herzen im Kreise der Redlichen und in der Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Groß sind Jehovahs Taten, nachgesucht von allen, die Lust daran haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Majestät und Ehre ist Sein Werk, und Seine Gerechtigkeit besteht immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Er machte ein Andenken für Seine Wunder, gnädig und erbarmungsvoll ist Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Er gibt Speise denen, die Ihn fürchten, Er gedenkt Seines Bundes ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Er sagt an Seinem Volke Seiner Werke Kraft, indem Er ihnen gab der Völkerschaften Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Die Werke Seiner Hände sind Wahrheit und Recht, wahrhaft sind alle Seine Verordnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'Sie werden erhalten immerfort, in Ewigkeit; sie sind getan in Wahrheit und Redlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Er sandte Seinem Volk Erlösung, Er gebot auf ewig Seinen Bund. Heilig und furchtbar ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Der Weisheit Anfang ist die Furcht Jehovahs, guten Verstand haben alle, so danach tun. Sein Lob besteht immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Hallelujah! Selig der Mann, der Jehovah fürchtet, der sehr Lust hat an Seinen Geboten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Mächtig wird sein Same sein auf Erden, das Geschlecht der Redlichen wird gesegnet sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Güter und Reichtum sind in seinem Hause, und seine Gerechtigkeit besteht immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'Den Redlichen geht ein Licht auf in der Finsternis, gnädig und erbarmungsvoll und gerecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Der gute Mann ist gnädig und leicht; er besorgt seine Worte im Gerichte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Denn ewig wankt er nicht, in ewigem Gedächtnis wird der Gerechte sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Vor bösem Gerücht fürchtet er sich nicht, fest ist sein Herz, vertrauet auf Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'Sein Herz wird erhalten, er fürchtet sich nicht, bis er auf seine Dränger hinsieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Er streut aus, er gibt den Dürftigen, seine Gerechtigkeit besteht immerfort. Sein Horn ist erhöht in Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Der Ungerechte sieht es und ärgert sich. Er knirscht mit seinen Zähnen und zerschmilzt. Verloren geht das Gelüste der Ungerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Hallelujah! Lobet, ihr Knechte Jehovahs, lobet Jehovahs Namen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Jehovahs Name sei gesegnet von nun an und bis in Ewigkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Vom Aufgang der Sonne bis zu ihrem Niedergang sei gelobt Jehovahs Name!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Erhöht über alle Völkerschaften ist Jehovah, über die Himmel Seine Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Wer ist wie Jehovah, unser Gott, Der hoch macht Seinen Sitz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'Der Sich erniedrigt, zu sehen in die Himmel und die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'Der aus dem Staub aufrichtet den Armen, von dem Düngerhaufen erhöht den Dürftigen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'Daß Er ihn lasse sitzen mit den Edlen, mit den Edlen Seines Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'Der die Unfruchtbare läßt im Hause wohnen, eine frohe Mutter von Söhnen. Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Da Israel von Ägypten auszog, Jakobs Haus weg von dem fremden Volke,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'Da ward Jehudah zu Seinem Heiligtum, Israel zu Seinen Herrschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Das Meer sah und floh, der Jordan wandte sich herum rückwärts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Die Berge hüpften wie Widder, Hügel wie der Herde Lämmer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Was ist dir, Meer, daß du fliehst, du Jordan, daß du dich rückwärts herumwendest?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'Euch Bergen, daß ihr hüpfet wie Widder, ihr Hügel, wie der Herde Lämmer?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Vor dem Angesicht des Herrn kreiße, du Erde! Vor dem Angesicht des Gottes Jakobs!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'Der den Fels verwandelt in einen Teich des Wassers, die Kiesel zum Brunnquell der Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Nicht uns, Jehovah, nicht uns, sondern Deinem Namen gib Herrlichkeit, um Deiner Barmherzigkeit, um Deiner Wahrheit willen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Warum sollen die Völkerschaften sagen: Wo ist nun ihr Gott?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'Aber unser Gott ist in den Himmeln, Er kann tun, wozu Er Lust hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Ihre Götzenbilder sind Silber und Gold, gemacht von den Händen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Einen Mund haben sie und reden nicht, Augen haben sie und sehen nicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'Ohren haben sie und hören nicht, eine Nase haben sie und riechen nicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'Ihre Hände, und sie tasten nicht, ihre Füße, und sie gehen nicht, sie sprechen nicht aus ihrer Kehle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Wie sie sind die, so sie machen, jeder, der auf sie vertraut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Israel, vertraue auf Jehovah! Ihr Beistand und ihr Schild ist Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Haus Aharons, vertrauet auf Jehovah; ihr Beistand und ihr Schild ist Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Ihr, die ihr Jehovah fürchtet, vertrauet auf Jehovah; ihr Beistand und ihr Schild ist Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Jehovah gedenkt unser, Er segnet: Er segnet das Haus Israel, Er segnet das Haus Aharons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Er segnet die, so Jehovah fürchten, die Kleinen mit den Großen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Jehovah wird zu euch hinzutun, zu euch und zu euren Söhnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Gesegnet seid ihr dem Jehovah, Der Himmel und Erde gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Die Himmel, die Himmel sind Jehovahs, und die Erde gab Er den Söhnen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Die Toten loben nicht Jah, noch alle, die zur Stille hinabfahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'Wir aber segnen Jah von nun an und bis in Ewigkeit. Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Das ist mir lieb, daß Jehovah hört meine Stimme, mein Flehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Daß Er Sein Ohr neigt zu mir; und in meinen Tagen will ich Ihn anrufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Des Todes Stricke umfingen mich, und der Hölle Drangsale trafen mich, und ich fand Drangsal und Gram.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Ich aber rief den Namen Jehovahs an. Lasse doch, Jehovah, entrinnen meine Seele!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Gnädig ist Jehovah und gerecht, und unser Gott erbarmt Sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Jehovah hütet die Einfältigen; ich ward schwach, und Er rettete mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Kehre, meine Seele, zurück zu deiner Ruhe; denn Jehovah hat dir wohlgetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Denn Du hast meine Seele vom Tod herausgerissen, mein Auge von der Träne, meinen Fuß von dem Anstoßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Ich will vor dem Angesicht Jehovahs wandeln in den Landen der Lebendigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Ich glaubte, darum rede ich. Ich war sehr im Elend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Ich sprach in meiner Hast: Jeder Mensch ist falsch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Wie soll ich Jehovah wiedergeben all Seine Wohltaten an mir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Den Becher des Heils erhebe ich und rufe Jehovahs Namen an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'Meine Gelübde will ich Jehovah entrichten nun vor all Seinem Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Kostbar in den Augen Jehovahs ist der Tod Seiner Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'O Jehovah, ich bin ja Dein Knecht, Dein Knecht bin ich, der Sohn Deiner Magd. Du hast aufgetan meine Bande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Dir will ich ein Opfer des Bekennens opfern, und Jehovahs Namen anrufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Ich will dem Jehovah meine Gelübde nun vor allem Seinem Volke entrichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'In den Vorhöfen von Jehovahs Haus, mitten in dir, Jerusalem. Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Lobet Jehovah, alle Völkerschaften, preiset Ihn, alle Volksstämme!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Denn mächtig ist Seine Barmherzigkeit über uns, und die Wahrheit Jehovahs ewiglich. Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Bekennet Jehovah, denn Er ist gut, denn Seine Barmherzigkeit ist ewig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Israel spreche nun, daß Seine Barmherzigkeit ist ewig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Es spreche nun Aharons Haus: Seine Barmherzigkeit ist ewig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Es sprechen nun die, so Jehovah fürchten: Seine Barmherzigkeit ist ewig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Aus der Bedrängnis rief ich zum Jah; es antwortete mir in der Weite Jah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Jehovah ist für mich. Ich fürchte mich nicht. Was kann der Mensch mir tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Jehovah ist unter denen, so mir beistehen, und ich werde sehen auf die, so mich hassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Besser ist es, daß man sich auf Jehovah verläßt, denn daß man vertraut auf den Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Besser ist es, daß man sich auf Jehovah verläßt, denn daß man vertraut auf Fürsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Die Völkerschaften alle haben mich umgeben; in Jehovahs Namen haue ich sie nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Sie haben mich umgeben, ja, rings umgeben, doch in Jehovahs Namen haue ich sie nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Wie Bienen umgaben sie mich, sie sind verloschen, wie ein Feuer von Dornen; in Jehovahs Namen haue ich sie nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Du stießest mich an, damit ich fiele; doch Jehovah stand mir bei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Meine Stärke und mein Psalm ist Jah, und Er wird mir zum Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Des Lobpreisens Stimme und des Heils ist in den Zelten der Gerechten; Jehovahs Rechte tut Tapferes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'Jehovahs Rechte ist erhöht, Jehovahs Rechte tut Tapferes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Nicht sterben werde ich, sondern leben und Jahs Taten erzählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Jah züchtigt mich, aber dem Tode gibt Er mich nicht hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Öffnet die Tore der Gerechtigkeit mir, ich gehe darinnen ein, ich bekenne Jah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Dies ist Jehovahs Tor, laßt die Gerechten darinnen einziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Ich will Dich bekennen, daß Du mir antwortest, und mir zum Heile bist geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Der Stein, den die Bauleute verschmäht, ist zum Haupt der Ecke geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Das ist geschehen von Jehovah, es ist wunderbar in unseren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'Dies ist der Tag, den Jehovah gemacht. Laßt uns an ihm frohlocken und fröhlich sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'O, rette uns doch, Jehovah, o lasse es, Jehovah, doch gelingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Gesegnet sei, der da kommt in Jehovahs Namen! Wir segnen euch aus dem Hause Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Gott ist Jehovah, und Er erleuchtet uns. Bindet mit Seilen das Festopfer an die Hörner des Altars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Du bist mein Gott; und Dich bekenne ich, mein Gott, ich will Dich erhöhen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Bekennet Jehovah, denn Er ist gut; denn ewig ist Seine Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Selig die, deren Weg untadelig ist, die in dem Gesetz Jehovahs wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Selig die, die Seine Zeugnisse bewahren, die Ihn von ganzem Herzen suchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'Auch tun sie nichts Verkehrtes. In Seinen Wegen wandeln sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Du hast geboten, Deine Ordnungen sehr zu halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'Möchten doch meine Wege dahin sich richten, daß ich hielte Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Dann werde ich nicht beschämt, wenn ich auf alle Deine Gebote blicke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Ich bekenne Dich in Geradheit des Herzens, wenn ich lerne die Rechte Deiner Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Deine Satzungen will ich halten; verlasse mich nicht zu sehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Wie wird ein Jüngling seinen Pfad lauter machen? Daß er sich halte nach Deinem Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Von ganzem Herzen suche ich nach Dir. Laß mich von Deinen Geboten nicht fehlgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'In meinem Herzen verdecke ich Deine Rede, daß ich nicht wider Dich sündige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Gesegnet bist Du, Jehovah, lehre mich Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Mit meinen Lippen habe ich alle die Rechte Deines Mundes erzählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Auf dem Weg Deiner Zeugnisse freue ich mich mehr, als über alle Güter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Ich überdenke Deine Ordnungen und blicke auf Deine Pfade.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'An Deinen Satzungen ergötze ich mich, ich vergesse nicht Deines Wortes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Tue wohl Deinem Knechte, daß ich lebe und halte Dein Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Tue meine Augen auf, daß ich Wunder aus Deinem Gesetz erblicke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Ein Fremdling bin ich auf Erden, verbirg Deine Gebote nicht vor mir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Zerdrückt ist meine Seele vor Sehnsucht nach Deinen Rechten alle Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Du bedrohst die verfluchten Vermessenen, die von Deinen Geboten fehlgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Wälze von mir Schmach und Verachtung ab; denn Deine Zeugnisse habe ich bewahrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Selbst Oberste sitzen und bereden sich wider mich; Dein Knecht überdenkt Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Deine Zeugnisse sind auch mein Ergötzen, die Männer meines Rates.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Am Staube klebt meine Seele, belebe mich nach Deinem Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Ich erzählte meine Wege, und Du antwortetest mir. Lehre Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Laß mich den Weg Deiner Ordnungen einsehen, daß ich überdenke Deine Wunder,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Es verfließt vor Gram meine Seele, richte mich auf nach Deinem Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Den Weg der Lüge wende von mir ab, und mit Deinem Gesetz begnade mich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Den Weg der Wahrheit habe ich erwählt. Ich stelle vor mich Deine Rechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Ich hafte an Deinen Zeugnissen, Jehovah, lasse mich nicht beschämt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Den Weg Deiner Gebote will ich laufen, weil Du mein Herz erweiterst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'Weise mich, Jehovah, den Weg Deiner Satzungen, und ich will ihn stets bewahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Mache mich einsichtsvoll, und ich bewahre Dein Gesetz, und halte es von ganzem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Lasse mich einhertreten auf dem Steige Deiner Gebote, denn ich habe Lust dazu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Neige mein Herz zu Deinen Zeugnissen, und nicht zum Gewinn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Laß meine Augen vorübergehen, daß sie nicht auf Eitles sehen. Belebe mich auf Deinem Wege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Bestätige Deinem Knecht Deine Rede, daß man Dich fürchte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Laß die Schmach an mir vorübergehen, vor der mir bangt; denn gut sind Deine Rechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Siehe, ich sehne mich nach Deinen Ordnungen, mit Deiner Gerechtigkeit belebe mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Laß Deine Barmherzigkeit auf mich kommen, Jehovah, Dein Heil, nach Deiner Rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'Und ich antworte ein Wort denen, die mich schmähen; denn auf Dein Wort vertraue ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'Und entreiße meinem Mund nicht so sehr das Wort der Wahrheit; denn auf Deine Gerichte warte ich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'Und will beständig halten Dein Gesetz ewiglich und immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'Und will in der Weite wandeln, denn ich frage nach Deinen Ordnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Und will reden vor Königen von Deinen Zeugnissen, und nicht mich schämen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'Und mich ergötzen an Deinen Geboten, die ich liebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'Und will erheben meine Hände zu Deinen Geboten, die ich liebe, und überdenken Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Gedenke Deinem Knecht des Wortes, dessen Du mich ließest warten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'Das ist mein Trost in meinem Elend, weil mich Deine Rede belebt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Mich haben Vermessene gar sehr verspottet; von Deinem Gesetz wende ich mich nicht ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Ich gedenke Deiner Gerichte von Ewigkeit her, Jehovah, und bin getröstet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Ein Glutwind hat mich ergriffen wegen der Ungerechten, die Dein Gesetz verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Psalmen waren mir Deine Satzungen im Hause meiner Wanderungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Ich gedenke Deines Namens des Nachts, Jehovah, und halte Dein Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'Das ward mir, weil ich bewahrte Deine Ordnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Mein Teil, Jehovah, sprach ich, ist, daß ich Deine Worte halte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Ich flehe an Dein Angesicht von ganzem Herzen: Sei gnädig mir nach Deiner Rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Ich denke meiner Wege und kehre meinen Fuß zu Deinen Zeugnissen zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Ich spute mich und zaudere nicht, Deine Gebote zu halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Der Ungerechten Stricke haben mich umstrickt, ich vergesse Deines Gesetzes nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Ich stehe auf um Mitternacht, Dich zu bekennen, ob der Gerichte Deiner Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Ich bin ein Gefährte aller, die Dich fürchten und Deine Ordnungen halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Jehovah, Deiner Barmherzigkeit ist die Erde voll, lehre mich Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Du hast, Jehovah, Gutes an Deinem Knecht getan nach Deinem Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Das Gut des Verstandes und der Kenntnis lehre mich; denn an Deine Gebote glaube ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Bevor ich ward gedemütigt, ging ich fehl, nun aber halte ich Deine Rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Gut bist Du und tust Gutes, lehre mich Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Die Vermessenen dichten Lüge wider mich, ich bewahre Deine Ordnungen von ganzem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Ihr Herz ist fühllos, wie Fett. Ich ergötze mich an Deinem Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'Gut war es für mich, daß ich gedemütigt ward, damit ich lernte Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Besser ist mir das Gesetz Deines Mundes, denn Tausende von Gold und Silber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Deine Hände haben mich gemacht und bereitet. Gib Einsicht mir, und ich lerne Deine Gebote.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Mich sehen, die Dich fürchten, und sind froh, denn ich warte auf Dein Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Ich weiß, Jehovah, daß Deine Gerichte sind gerecht, und daß in Treue Du mich gedemütigt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Laß doch Deine Barmherzigkeit mir zum Troste werden, nach Deiner Rede an Deinem Knecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Laß Dein Erbarmen kommen über mich, auf daß ich lebe; denn Dein Gesetz ist mein Ergötzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Beschämt werden die Vermessenen; sie stürzen mich um mit Lügen, ich aber überdenke Deine Ordnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Es müssen zurückkehren zu mir die, so Dich fürchten, und Deine Zeugnisse kennen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Untadelig sei mein Herz in Deinen Satzungen, auf daß ich nicht beschämt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Nach Deinem Heile verzehrt sich meine Seele, auf Dein Wort habe ich gewartet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Es verzehren sich meine Augen nach Deiner Rede und sagen: Wann tröstest Du mich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Denn wie der Schlauch im Rauch bin ich; doch Deiner Satzungen vergesse ich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Wie viele sind der Tage Deines Knechtes? Wann tust Du Gericht an meinen Verfolgern?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Fallgruben graben mir die Vermessenen, die nicht nach Deinem Gesetz sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Alle Deine Gebote sind Wahrheit. Sie verfolgen mich mit Lügen, stehe Du mir bei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Um ein Kleines hätten sie mich von der Erde aufgerieben; doch verließ ich nicht Deine Ordnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Belebe mich nach Deiner Barmherzigkeit, und ich werde das Zeugnis Deines Mundes halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Ewiglich, o Jehovah, steht fest in den Himmeln Dein Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Deine Wahrheit ist zu Geschlecht und Geschlecht. Du festigst die Erde, und sie steht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Nach Deinen Rechten stehen sie heute; denn alles dient Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Wäre Dein Gesetz nicht mein Ergötzen, dann wäre ich in meinem Elend vergangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Ewig vergesse ich nicht Deine Ordnungen; denn durch sie belebst Du mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Dein bin ich, rette mich, denn Deinen Ordnungen frage ich nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Die Ungerechten erwarten mich, daß sie mich zerstören, ich habe Einsicht in Deine Ordnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Aller Vollkommenheit sah ich ein Ende; doch Dein Gebot ist sehr weit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Wie liebe ich Dein Gesetz! Es ist den ganzen Tag mein Nachsinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Weiser denn meine Feinde machen mich Deine Gebote; denn mein sind sie ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Vor allen meinen Lehrern bin ich verständig geworden; denn Deine Zeugnisse überdenke ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Einsichtsvoller bin ich, als die Alten; denn Deine Ordnungen bewahre ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Von jedem bösen Pfade halte ich meine Füße weg, auf daß Dein Wort ich halte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Von Deinen Rechten weiche ich nicht ab, denn Du hast mich unterwiesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Wie hold ist meinem Gaumen Deine Rede, mehr als Honig meinem Munde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Von Deinen Ordnungen werde ich einsichtsvoll; darum hasse ich jeglichen Pfad der Lüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Dein Wort ist eine Leuchte meinem Fuß, und ein Licht auf meinem Steig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Ich habe es geschworen und bestätige es, zu halten die Rechte Deiner Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Gar sehr bin ich gedemütigt; Jehovah, belebe mich nach Deinem Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Das Freiwillige meines Mundes lasse Dir doch wohlgefallen, o Jehovah, und lehre mich Deine Rechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Meine Seele ist beständig in meinen Händen; und ich vergesse Deines Gesetzes nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Die Ungerechten legten Schlingen mir, doch irrte ich nicht ab von Deinen Ordnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Deine Zeugnisse sind mir ewiges Erbe; denn sie sind die Freude meines Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Ich neige mein Herz, stets zu tun Deine Satzungen ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Ich hasse die Zweifler und liebe Dein Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Mein Schutz und mein Schild bist Du, ich warte auf Dein Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Weichet ab von mir, ihr Bösen; und ich will die Gebote meines Gottes bewahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Sei mir zum Anhalt nach Deiner Rede, und ich werde leben und laß mich beschämt nicht werden mit meiner Erwartung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Labe Du mich, daß ich gerettet werde und beständig schaue auf Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Alle trittst Du nieder, die fehlgehen von Deinen Satzungen; denn Lüge ist ihr Trug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Als Schlacken schaffst Du alle Ungerechten im Lande weg, darum liebe ich Deine Zeugnisse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Mein Fleisch durchschaudert der Schauer vor Dir, und vor Deinen Gerichten fürchte ich mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Recht tue ich und Gerechtigkeit. Überlasse mich nicht denen, die mich niederdrükken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Sei Bürge für Deinen Knecht zum Guten, daß die Vermessenen mich nicht niederdrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Es verzehren sich meine Augen ob Deines Heils, und ob der Rede Deiner Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Tue mit Deinem Knecht nach Deiner Barmherzigkeit, und lehre mich Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Dein Knecht bin ich, gib Du mir Einsicht, daß Deine Zeugnisse ich wisse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Zeit ist es zum Tun für Jehovah: sie haben Dein Gesetz zunichte gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Darum liebe ich Deine Gebote mehr als Gold, und als feines Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Darum halte ich als gerade all Deine Ordnungen gänzlich; ich hasse allen Pfad der Lüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Deine Zeugnisse sind wunderbar; darum bewahrt meine Seele sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Die Eröffnung Deiner Worte erleuchtet, sie gibt Einsicht den Einfältigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Ich öffne meinen Mund weit und lechze, denn nach Deinen Geboten sehne ich mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Wende Dich zu mir und sei mir gnädig, nach dem Recht gegen die, so Deinen Namen lieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Festige meine Tritte durch Deine Rede, und laß nicht irgendein Unrecht in mir walten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Erlöse mich von der Niederdrückung des Menschen, daß ich Deine Ordnungen halte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Laß Dein Angesicht leuchten auf Deinen Knecht, und lehre mich Deine Satzungen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Bächlein von Wasser rinnen herab von meinen Augen, über die, so nicht halten Dein Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Gerecht bist Du, Jehovah, und gerade sind Deine Gerichte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Gerechtigkeit gebietest Du in Deinen Zeugnissen und gar sehr die Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Vertilgt hat mich mein Eifer, daß meine Dränger Deiner Worte vergessen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Sehr geläutert ist Deine Rede, und Dein Knecht liebt sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Gering bin ich und verachtet, ich vergesse nicht Deiner Ordnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Ewiglich ist gerecht Deine Gerechtigkeit, und Wahrheit Dein Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Mich haben Drangsal und Angst betroffen; Deine Gebote sind mein Ergötzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Gerechtigkeit sind Deine Zeugnisse ewiglich. Gib Einsicht mir, auf daß ich lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Von ganzem Herzen rufe ich: Antworte mir, Jehovah! Deine Satzungen will ich wahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Ich rufe zu Dir: Rette mich, und ich halte Deine Zeugnisse!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Früh in der Dämmerung stehe ich auf, und schreie, ich warte auf Deine Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Es kommen meine Augen den Nachtwachen zuvor, auf daß ich überdenke Deine Rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Höre meine Stimme nach Deiner Barmherzigkeit, Jehovah, nach Deinem Rechte belebe mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Es nahen sich die, die den Schandtaten nachsetzen, von Deinem Gesetz sind sie fern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'Nahe bist Du, Jehovah, und Wahrheit sind alle Deine Gebote.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Von der Vorzeit her weiß ich aus Deinen Zeugnissen, daß Du sie ewiglich gegründet hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Siehe mein Elend und reiße mich heraus; denn Deines Gesetzes habe ich nicht vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Hadere Du meinen Hader und erlöse mich. Belebe mich nach Deiner Rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Fern von den Ungerechten ist das Heil, denn sie fragen nicht nach Deinen Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Viel sind, Jehovah, Deiner Erbarmungen. Nach Deinen Rechten belebe Du mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Viel sind meiner Verfolger und meiner Dränger; ich wende mich nicht ab von Deinen Zeugnissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Ich sehe die Treulosen und bin verdrossen, daß sie Deine Rede nicht halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Siehe, wie ich liebe Deine Ordnungen, Jehovah, nach Deiner Barmherzigkeit belebe Du mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Die Summe Deines Wortes ist Wahrheit, und ewig ist alles Gericht Deiner Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Oberste verfolgen mich ohne Ursache; und mein Herz scheut sich vor Deinen Worten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Ich freue mich Deiner Rede, wie einer, der viel Beute findet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Ich hasse die Lüge, und sie ist mir zum Greuel, ich liebe Dein Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Des Tages siebenmal lobe ich Dich wegen der Rechte Deiner Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Viel Frieden haben die, so Dein Gesetz lieben, und sie straucheln nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Ich habe Dein Heil erwartet, Jehovah, und getan nach Deinen Geboten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Meine Seele hält Deine Zeugnisse, und ich liebe sie sehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Ich habe Deine Ordnungen und Zeugnisse gehalten; denn alle meine Wege sind vor Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Lasse meinen Klageruf Dir sich nahen, Jehovah, gib mir Einsicht nach Deinem Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Mein Flehen komme vor Dein Angesicht; errette mich nach Deiner Rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Lasse meine Lippen hervorquellen Lob, denn Du lehrest mich Deine Satzungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Meine Zunge antworte Deiner Rede; denn Gerechtigkeit sind alle Deine Gebote.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'Lasse Deine Hand mir zum Beistand sein, denn Deine Ordnungen habe ich erwählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Nach Deinem Heil sehne ich mich, Jehovah, und Dein Gesetz ist mein Ergötzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Laß meine Seele leben und Dich loben, und dein Gericht müsse mir beistehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Wie ein verloren Schaf gehe ich in der Irre; suche Deinen Knecht! denn Deiner Gebote habe ich nicht vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, 'Ich rufe zu Jehovah in meiner Drangsal, und Er antwortet mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'Jehovah, errette meine Seele von der Lüge Lippe, von der Zunge des Trugs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Was gibt dir und was tut sie dir dazu, die Zunge des Trugs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Die Pfeile des Helden sind geschärft an den Glühkohlen des Wacholders.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Wehe mir, daß ich in Meschech mich aufhalte, daß ich wohne bei Kedars Zelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Zu viel wohnt meine Seele bei dem, der Frieden haßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Ich bin für Frieden; aber wenn ich rede, sind sie für Krieg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, 'Ich hebe meine Augen auf zu den Bergen, von wannen mir Beistand kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Der Beistand kommt mir von Jehovah, Der Himmel und Erde hat gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Er läßt nicht wanken deinen Fuß, dein Hüter schlummert nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Siehe, nicht schlummert und nicht schläft der Hüter Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Jehovah ist Dein Hüter; Jehovah ist dein Schatten über deiner rechten Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Des Tages wird die Sonne dich nicht stechen, noch der Mond des Nachts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Jehovah wird vor allem Bösen dich behüten. Er wird behüten deine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Jehovah behütet deinen Ausgang und deinen Eingang von nun an und bis in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, 'Ich bin froh, wenn sie zu mir sagen: Lasset uns gehen nach dem Hause Jehovahs!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'In deinen Toren stehen unsere Füße, o Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jerusalem, die gebaut ist wie eine Stadt, die für sich zusammengefügt ist in eins.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'Wo hinaufziehen die Stämme, die Stämme Jahs, ein Zeugnis für Israel, zu bekennen den Namen Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Denn dort sitzen Throne zum Gericht, Throne von Davids Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Bittet um den Frieden Jerusalems. In Ruhe seien, die dich lieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Friede sei in deiner Vormauer, Ruhe in deinen Palästen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Um meiner Brüder und Genossen willen laß mich doch reden: Friede sei in dir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Um des Hauses Jehovahs unseres Gottes willen will ich dir Gutes suchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, 'Ich hebe meine Augen auf zu Dir, Der Du im Himmel wohnst!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Siehe, wie der Knechte Augen auf ihres Herrn Hand, wie die Augen der Dienstmagd auf die Hand ihrer Gebieterin, so sind unsere Augen auf Jehovah, unseren Gott, bis daß Er uns gnädig sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Sei uns gnädig, Jehovah, sei uns gnädig; denn von Verachtung sind wir übersättigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Gar übersättigt ist geworden unsere Seele des Hohns der Sorglosen, der Verachtung der Hochmütigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, 'Wäre nicht Jehovah mit uns, spreche nun Israel,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'Wäre nicht Jehovah mit uns, da der Mensch wider uns aufstand:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'Dann hätten sie lebendig uns verschlungen, als wider uns ihr Zorn entbrannte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Dann hätten uns die Wasser überflutet; der Bach wäre über unsere Seele hingegangen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'Dann wären über unsere Seele hingegangen die übermütigen Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Gesegnet sei Jehovah, Der uns ihren Zähnen nicht zum Zerfleischen gab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Unsere Seele ist wie der Vogel, so aus der Vogler Schlinge ist entronnen; die Schlinge riß, und wir sind entronnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Unser Beistand ist in dem Namen Jehovahs, Der Himmel und Erde gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, 'Die auf Jehovah vertrauen, sind wie der Berg Zions, der nimmer wankt, der bleibt ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Jerusalem, Berge sind rings um sie her, und Jehovah ist rings um Sein Volk von nun an und bis in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Denn des Ungerechten Rute soll nicht auf dem Lose der Gerechten ruhen, damit die Gerechten ihre Hände nicht zur Verkehrtheit ausstrecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Jehovah, tue Gutes den Guten und denen, die gerade sind in ihren Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Die aber sich abwenden auf das Krumme, lasse Jehovah dahingehen mit denen, so Unrecht tun. Friede sei über Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, 'Wenn Jehovah die Gefangenen Zions zurückbringt, werden wir sein wie Träumende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Da wird des Lachens voll sein unser Mund, und unsere Zunge von Jubelsang. Da werden sie unter den Völkerschaften sagen: Großes hat Jehovah getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Jehovah hat Großes mit uns getan. Wir sind froh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Bringe unsere Gefangenschaft zurück, Jehovah, wie die Gießbäche im Mittagsland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Die, so mit Tränen säen, werden mit Jubelsang ernten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Weinend geht dahin der den Samenwurf trägt, er kommt mit Jubelsang, er trägt seine Garben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, 'Wo Jehovah nicht das Haus baut, da mühen sich umsonst, die daran bauen. Wo Jehovah nicht die Stadt hütet, da wachet der Hüter umsonst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Es ist euch umsonst, daß ihr früh aufsteht und spät aufsitzet, das Brot der Schmerzen esset, so gibt Er es Seinen Geliebten im Schlaf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Siehe, ein Erbe Jehovahs sind Söhne, ein Lohn die Frucht des Leibes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Wie Pfeile in der Hand des Helden so sind die Söhne der Jugend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'Selig der Mann, der seinen Köcher mit ihnen gefüllt hat; sie werden nicht beschämt, wenn sie mit den Feinden in dem Tore reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, 'Selig ein jeder, der Jehovah fürchtet, der in Seinen Wegen wandelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Denn du issest deiner Hände Arbeit. Selig bist du, und du hast es gut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Dein Weib ist wie ein fruchtbarer Weinstock an den Seiten deines Hauses, deine Söhne sind wie Pflänzlinge des Ölbaumes rings um deinen Tisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Siehe, so wird der Mann gesegnet, der Jehovah fürchtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Jehovah wird dich segnen aus Zion, und du sollst sehen das Wohl Jerusalems alle Tage deines Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'Und wirst sehen Söhne von deinen Söhnen, Frieden über Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, 'Viel haben sie bedrängt mich von meiner Jugend auf! So spreche nun Israel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'Viel haben sie bedrängt mich von meiner Jugend auf, doch haben sie mich nicht überwältigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Auf meinem Rücken haben die Pflüger gepflügt und ihre Furchen langgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Jehovah ist gerecht, der Ungerechten Seile schnitt Er ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Beschämt müssen werden und hinter sich zurückweichen alle, die Zion hassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Sie werden wie das Gras der Dächer, das, ehe man es herausrauft, verdorrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 'Mit dem nicht füllt seine Hand der Schnitter, noch seinen Schoß der Garbenbinder;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'Und die vorübergehen sprechen nicht: Jehovahs Segen sei über euch! Wir segnen euch in dem Namen Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, 'Aus den Tiefen rufe ich zu Dir, Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Herr, höre auf meine Stimme, es mögen Deine Ohren aufmerken auf die Stimme meines Flehens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Wenn Du, Jah, Missetaten behältst, wer wird, o Herr, bestehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Doch ist bei Dir Vergebung, daß man Dich fürchte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Ich hoffe auf Jehovah, meine Seele hofft, und Seines Wortes warte ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Meine Seele ist auf den Herrn, mehr als die Hüter auf den Morgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Warte auf Jehovah, Israel; denn bei Jehovah ist Barmherzigkeit und mit Ihm viel Erlösung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'Und Er wird Israel lösen von allen seinen Missetaten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, 'Jehovah, mein Herz ist nicht hoffärtig, meine Augen sind nicht erhöht, und ich gehe nicht mit Dingen um, die zu groß und wunderbarlich für mich sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Habe ich nicht meine Seele gesetzt und stille gehalten wie ein von der Mutter Entwöhntes; wie ein Entwöhntes ist bei mir meine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Israel warte auf Jehovah von nun an und bis in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, 'Gedenke, Jehovah, an David, an all sein Elend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'An ihn, der Jehovah schwor, gelobte dem Gewaltigen Jakobs:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Ich gehe nicht hinein in meines Hauses Zelt, steige nicht hinauf auf das Ruhebett meiner Lagerstätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'Ich gebe meinen Augen keinen Schlaf, den Augenwimpern keinen Schlummer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'Bis ich gefunden habe einen Ort für Jehovah, Wohnungen für den Gewaltigen Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Siehe, wir hörten von Ihm in Ephratha, wir fanden Ihn in dem Gefilde des Waldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Laßt uns zu Seinen Wohnungen eingehen, anbeten zu Seiner Füße Schemel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Mache Dich auf, Jehovah, zu Deiner Ruhe, Du und die Lade Deiner Stärke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Laß Deine Priester sich kleiden in Gerechtigkeit, und jubeln Deine Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Um Davids, Deines Knechtes willen wende nicht zurück das Angesicht Deines Gesalbten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Jehovah hat dem David Wahrheit geschworen. Nimmer wird Er davon zurückgehen: Von deines Leibes Frucht will Ich dir setzen auf den Thron.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Wenn deine Söhne halten Meinen Bund und Mein Zeugnis, das Ich sie lehre, sollen auch ihre Söhne fort und fort sitzen auf deinem Thron.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Denn Jehovah hat Sich Zion erwählt, zum Wohnsitz für Sich ersehnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'Dies ist Meine Ruhe fort und fort, hier will Ich wohnen; denn Ich habe es ersehnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Ich werde seine Zehrung mit Segen segnen; werde seine Dürftigen sättigen mit Brot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'Und seine Priester will Ich Heil anziehen lassen, und seine Heiligen sollen jubeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Da will Ich David sprossen lassen ein Horn, will Meinem Gesalbten eine Leuchte zurichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Seine Feinde will Ich Scham anziehen lassen, aber auf ihm soll erblühen sein Diadem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, 'Siehe, wie gut und lieblich ist es, daß Brüder als eins zusammen wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Wie das gute Öl auf dem Haupte, das herabfließt auf den Bart, Aharons Bart, das herabfließt auf die Mündung seiner Obergewänder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Wie Chermons Tau, der herabkommt auf die Berge Zions, weil Jehovah dahin entboten hat den Segen, Leben bis in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, 'Siehe, segnet Jehovah, alle ihr Knechte Jehovahs, die ihr steht im Hause Jehovahs in den Nächten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Hebt eure Hände auf zum Heiligtum und segnet Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Jehovah segne dich aus Zion, Er, Der Himmel und Erde hat gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Hallelujah! Lobet den Namen Jehovahs, lobet, ihr Knechte Jehovahs!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'Ihr, die ihr steht in dem Hause Jehovahs, in den Höfen des Hauses unseres Gottes:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Hallelujah; denn gut ist Jehovah. Singt Psalmen Seinem Namen; denn lieblich ist Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Denn Jakob hat Jah Sich erwählt, Israel zu Seinem besonderen Eigentum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Denn ich weiß, daß groß ist Jehovah, und unser Herr vor allen Göttern;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Alles, wozu Jehovah Lust hat, tut Er im Himmel und auf Erden, im Meer und allen Abgründen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'Er führt Dünste herauf vom Ende der Erde, macht Blitze zu Regen, bringt den Wind heraus aus Seinen Schätzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'Der die Erstgeborenen Ägyptens schlug vom Menschen bis zum Vieh;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Er sandte Zeichen und Wahrzeichen, in deine Mitte Ägypten, wider Pharao und wider alle seine Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'Der viele Völkerschaften hat geschlagen und mächtige Könige erwürgte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sichon, den König der Amoriter, und Og, den König Baschans, und alle Königreiche Kanaans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'Und Der ihr Land zum Erbe hat gegeben, zum Erbe Israel, Seinem Volke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'Jehovah, Dein Name ist ewig, Jehovah, Dein Gedächtnis zu Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Denn Recht wird sprechen Seinem Volk Jehovah, und es wird Ihn gereuen wegen Seiner Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Die Götzen der Völkerschaften sind Silber und Gold, sie sind gemacht von den Händen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'Einen Mund haben sie und reden nicht; Augen haben sie und sehen nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'Sie haben Ohren und nehmen nicht zu Ohren, auch ist in ihrem Mund kein Hauch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Wie sie werden sein, die sie machen, ein jeder, der auf sie vertraut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'O Haus Israel, segnet Jehovah; o Haus Aharons, segnet Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'O Haus Levi, segnet Jehovah; die ihr Jehovah fürchtet, segnet Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Gesegnet sei Jehovah aus Zion, Er, Der in Jerusalem wohnt. Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Bekennet Jehovah, denn Er ist gut, denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Bekennet den Gott der Götter, denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Bekennet den Herrn der Herren, denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Ihn, Der allein große Wunder tut; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Ihn, Der mit Einsicht die Himmel gemacht; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Der auf den Wassern hat die Erde ausgebreitet; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Der große Lichter gemacht; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Die Sonne, um am Tag zu herrschen; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Den Mond und die Sterne, um des Nachts zu herrschen; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Ihn, Der Ägypten schlug an seinen Erstgeburten; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'Und brachte Israel heraus aus ihrer Mitte; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Mit starker Hand und ausgerecktem Arm; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Der das Meer Suph entzweischnitt in Stücke; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'Und Israel mitten hindurchbrachte; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'Und Pharao und seine Streitmacht in das Meer Suph abschüttelte; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Ihn, Der Sein Volk ließ ziehen durch die Wüste; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Der große König erschlug; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'Und stattliche Könige erwürgte; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sichon, den König der Amoriter; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'Und Og, den König Baschans; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'Und gab ihr Land zum Erbe; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'Zum Erbe Israel, Seinem Knechte; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Der unser gedachte in unserer Niedrigkeit; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'Und uns losriß von unseren Drängern; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Der Brot gibt allem Fleisch; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Bekennet den Gott der Himmel; denn Seine Barmherzigkeit ist in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'An den Flüssen Babels da saßen wir; wir weinten auch, wenn wir Zions gedachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'An die Weiden in seiner Mitte hingen wir unsere Harfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Da baten uns, die uns gefangen hielten, um die Worte eines Liedes, die so uns quälten, um Fröhlichkeit: Singt uns von dem Liede Zions.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Wie sollten wir das Lied Jehovahs singen auf dem Boden des Auslandes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'So ich deiner vergäße, Jerusalem, so soll vergessen meine Rechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'So soll kleben meine Zunge an meinem Gaumen, so ich dein nicht gedenke, so ich nicht erhebe Jerusalem über das Höchste meiner Fröhlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Gedenke Du, Jehovah, der Söhne Edoms am Tag Jerusalems, da sie sprachen: Entblößt, entblößt sie bis auf die Gründe darin!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'Tochter Babels, der verheerten, selig der dir entrichtet nach der Erwiderung, die du uns erwidert hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Selig der, der deine Kindlein ergreift und sie zerschmettert an der Felsenklippe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, 'Ich bekenne Dich von ganzem Herzen, vor den Göttern singe ich Dir Psalmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Ich will anbeten zum Tempel Deiner Heiligkeit, und bekennen Deinen Namen für Deine Barmherzigkeit, und für Deine Wahrheit, daß über all Deinen Namen Du groß erwiesen hast, Deine Rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'Am Tage, da ich Dich anrief, antwortest Du mir, und erweiterst mir in meiner Seele die Stärke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Bekennen werden Dich, Jehovah, alle Könige der Erde, wenn sie die Reden Deines Mundes hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'Und sie werden singen auf Jehovahs Wegen, daß groß ist Jehovahs Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Denn erhöht ist Jehovah und sieht auf den Niedrigen, aber den Hoffärtigen kennt Er aus der Ferne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Gehe ich mitten durch Drangsal, so belebst Du mich, reckst Deine Hand aus wider meiner Feinde Zorn, und rettest mich mit Deiner Rechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Jehovah wird es für mich durchführen, Jehovah, Deine Barmherzigkeit ist in Ewigkeit. Du wollest Deiner Hände Werk nicht lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, 'Jehovah, Du erforschest mich und kennst mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Du weißt mein Sitzen und mein Aufstehen, Du merkst meine Gedanken von ferne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Meinen Pfad und mein Niederliegen durchsuchst Du, und bist vertraut mit allen meinen Wegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Denn kein Wort ist auf meiner Zunge, siehe Jehovah! Du weißt es alles.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Hinten und vorne hast Du mich umlagert, und Deine Hand auf mich gelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Das Wissen ist zu wunderbar für mich, zu hoch, ich fasse es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Wohin soll ich gehen vor Deinem Geist und wohin entweichen vor Deinem Angesicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Führe empor ich zum Himmel, so bist Du da, bettete ich mich in der Hölle, siehe, Du bist hier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Erhöbe ich der Morgenröte Flügel, wohnte am hintersten Meere:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'Auch dort würde mich führen Deine Hand, und Deine Rechte mich ergreifen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Und spräche ich: Finsternis umhülle mich doch, so würde Nacht zum Lichte um mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'Auch Finsternis macht finster nicht vor Dir; und Nacht leuchtet wie der Tag, Finsternis ist wie das Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Denn Du besitzest meine Nieren, mich bedecktest Du in meiner Mutter Leibe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Ich bekenne Dich: Weil furchtbar, wunderbar ich bin gemacht; wunderbar sind Deine Taten, und dies weiß meine Seele sehr wohl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Es war Dir nicht verhohlen mein Gebein, da im Verborgenen ich gemacht ward, da ich gewirkt ward in der Erde unteren Räumen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Als ich noch ungestaltet war, sahen mich Deine Augen, und sie alle waren in Dein Buch geschrieben, die Tage, die bestimmt worden, und von denen nicht einer da war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Und wie köstlich sind mir Deine Gedanken, Gott! Wie ist so mächtig ihre Summe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Sollte ich sie zählen, sind ihrer mehr denn des Sandes, erwache ich, so bin ich noch bei Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'O daß Du tötetest den Ungerechten, o Gott, und die Männer des Blutes von mir abwichen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Die von Dir mit Arglist sprechen, zum Eitlen erheben sich Deine Gegner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Hasse ich nicht, Jehovah, die Dich hassen, und habe Verdruß auf die, so sich wider Dich erheben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'Mit ganzem Hasse hasse ich sie, sie sind zu Feinden mir geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Erforsche mich Gott und kenne mein Herz, prüfe mich und kenne meine Bekümmernis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'Und siehe, ob ich auf dem Wege des Schmerzes bin, und führe mich auf den Weg der Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, 'Dem Sangmeister. Ein Psalm Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'Reiß mich heraus, Jehovah, von dem bösen Menschen, vor dem Manne der Gewalttaten bewahre mich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Die da im Herzen Böses denken, den ganzen Tag zum Streite sich zusammenrotten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Sie spitzen ihre Zunge wie die Schlange, und Natterngift ist unter ihren Lippen. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Behüte mich, Jehovah, vor den Händen des Ungerechten, bewahre mich vor dem Manne der Gewalttaten; die darauf denken, daß meine Tritte sie umstoßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Die Hochmütigen legen mir hehlings Schlingen und Stricke; sie breiten Netze mir zur Seite des Geleises, haben Fallstricke mir gelegt. Selah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Ich spreche zu Jehovah: Mein Gott bist Du, Jehovah, nimm zu Ohren die Stimme meines Flehens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Jehovah, Herr, Du Stärke meines Heils, Du deckst mein Haupt am Tag der Waffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Jehovah, gib nicht zu des Ungerechten Gelüste, laß seinen Anschlag nicht gewähren, daß sie sich erhöhen. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Mit Galle umgaben sie mich. Die Mühsal ihrer Lippen decke sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Lasse Glühkohlen herabfallen auf sie, man stürze sie ins Feuer, in Untiefen, daß nimmer sie aufstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Der Mann der Zunge werde nicht im Lande gefestigt, den Mann der Gewalttat jage das Böse zum Sturz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Ich weiß, daß Jehovah Recht schafft für den Elenden, ein Gericht für den Dürftigen. Ja, die Gerechten bekennen Deinen Namen, die Redlichen wohnen vor Deinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, 'Jehovah, ich rufe zu Dir, eile zu mir, nimm zu Ohren meine Stimme, wenn ich Dich anrufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Als Weihrauch sei mein Gebet zugerichtet vor Dir, meiner Hände Erhebung als Speiseopfer des Abends.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Jehovah, setze eine Hut über meinen Mund, bewahre meiner Lippen Tür.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Laß nicht zu bösem Worte mein Herz sich neigen, noch mit Männern, die Unrecht tun, mein Wesen treiben in Ungerechtigkeit, daß ich nicht esse von ihren Leckerspeisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Lasse den Gerechten mich schlagen, Barmherzigkeit ist es; und rügt er mich, sei es Öl meinem Haupt. Nicht weigern soll sich mein Haupt; denn noch ist mein Gebet in ihren Bosheiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Hinab an den Seiten der Felsenklippe stürze man ihre Richter, und sie sollen hören meine Reden: denn sie sind lieblich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Wie man die Erde pflügt und spaltet, sind unsere Gebeine hingestreut an der Mündung der Hölle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Doch auf Dich sind meine Augen, Jehovah, Herr, auf Dich verlasse ich mich, entblöße meine Seele nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Behüte mich vor der Hand der Schlinge, die sie mir legten, und vor den Fallstricken derer, die Unrecht tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Die Ungerechten lasse in ihre Fangnetze fallen allzumal, während ich vorübergehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, 'Eine Unterweisung von David, da er in der Höhle war; ein Gebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'Ich schreie zu Jehovah mit meiner Stimme. Ich flehe mit meiner Stimme zu Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Ich schütte vor Ihm meinen Kummer aus, meine Drangsal sage ich an vor Ihm:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Wenn mein Geist über mir verzagt, kennst Du doch meinen Steig. Auf dem Pfade, den ich wandle, legen sie hehlings eine Schlinge mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'Blicke zur Rechten, und siehe, so ist keiner, der mich erkennt. Verloren für mich ist die Zuflucht, es fragt niemand nach meiner Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Zu Dir schreie ich, Jehovah. Ich spreche: Du bist meine Zuversicht, mein Teil im Lande der Lebendigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Horch auf meinen Angstschrei, denn ich bin sehr erschöpft. Errette mich von meinen Verfolgern, denn sie sind mir zu mächtig. Bringe meine Seele heraus aus dem Kerker, daß ich Deinen Namen bekenne. Die Gerechten werden mich umringen, wenn Du mir wohltust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, 'Jehovah, höre mein Gebet, nimm zu Ohren mein Flehen, in Deiner Wahrheit, antworte mir in Deiner Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'Und komme nicht mit Deinem Knechte in das Gericht; denn vor Dir ist kein Lebendiger gerecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Denn der Feind verfolgt meine Seele, er zerstößt zur Erde mein Leben, er läßt mich sitzen in Finsternissen wie die Toten der Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'Mein Geist verzagt in mir, mein Herz entsetzt sich in meinem Inneren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Ich gedenke der Vorzeit Tage, ich sinne über alle Deine Werke, und überdenke Deiner Hände Tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Ich breite meine Hände zu Dir; meine Seele ist wie durstig Land vor Dir. Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Eile, antworte mir, Jehovah; mein Geist verzehrt sich, birg Dein Angesicht nicht vor mir, sonst werde ich gleich denen, so hinab zur Grube fahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Laß mich am Morgen hören Deine Barmherzigkeit; denn ich vertraue auf Dich. Tue kund mir den Weg, den ich soll gehen; denn zu Dir erhebe ich meine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Errette mich, Jehovah, von meinen Feinden, bei Dir bin ich bedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Lehre Du mich tun nach Deinem Wohlgefallen; denn Du bist mein Gott. Dein guter Geist führe mich in das Land der Geradheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Um Deines Namens willen, Jehovah, belebe mich in Deiner Gerechtigkeit, bringe meine Seele aus der Drangsal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'Und vertilge meine Feinde in Deiner Barmherzigkeit, und zerstöre alle Dränger meiner Seele; denn ich bin Dein Knecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, 'Von David. Gesegnet sei Jehovah, mein Fels, Der meine Hände den Kampf lehret, meine Finger den Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'Meine Barmherzigkeit und Feste, meine Burg und mein Befreier mir, mein Schild und Der, auf Den ich mich verlasse, Der mein Volk mir unterworfen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Jehovah, was ist der Mensch, daß Du ihn kennst, des Menschen Sohn, daß Du an ihn denkst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Dem Hauche gleicht der Mensch: wie ein Schatten, der vorübergeht, sind seine Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Jehovah, neige Deine Himmel, und fahre hernieder, rühre die Berge an, auf daß sie rauchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Blitze Deine Blitze, und zerstreue sie, sende Deine Pfeile, und verwirre sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Sende Deine Hand aus von der Höhe, befreie und errette mich aus vielen Wassern, aus der Hand der Söhne des Auslands,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Deren Mund Eitles redet, und deren Rechte eine Rechte der Lüge ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'O Gott, ein neues Lied will ich Dir singen, Dir Psalmen singen zum Psalter mit zehn Saiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'Der Du den Königen Sieg gibst; Der Du David, Deinen Knecht, vom bösen Schwerte befreit hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Befreie mich und errette mich aus der Hand der Söhne des Auslands, deren Mund Eitles redet, und deren Rechte eine Rechte der Lüge ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Denn unsere Söhne sind wie Pflanzen groß geworden in ihrer Jugend, unsere Töchter als wie Ecksäulen zu Vorbildern für Paläste ausgehauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'Unsere Speicher sind voll, gewährend von Sorte zu Sorte, unser Kleinvieh ist tausendfältig, zehntausende sind auf unseren Gassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'Unsere Rinder sind beladen, kein Durchbruch und kein Ausgang ist da und kein Klageschrei auf unseren Straßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Selig das Volk, dem also geschieht. Selig das Volk, dessen Gott Jehovah ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, 'Erhöhen will ich Dich, mein Gott, Du König, und will segnen Deinen Namen in Ewigkeit und immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Jeden Tag will ich Dich segnen und loben Deinen Namen in Ewigkeit und immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Groß ist Jehovah und sehr zu loben, und unerforschlich Seine Größe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Geschlecht preiset dem Geschlechte Deine Taten, und sagen an Deine Macht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Die Ehre der Herrlichkeit Deiner Majestät und die Worte Deiner Wunder will ich überdenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'Und von der Stärke Deiner furchtbaren Taten sprechen sie, und von Deiner Größe will ich erzählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Sie lassen hervorquellen das Andenken Deiner vielen Güte, und lobpreisen Deine Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Gnädig und erbarmungsvoll ist Jehovah, langmütig und von großer Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'Jehovah ist allen gut, und Seine Erbarmungen sind über all Seinen Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Es sollen bekennen Dich, Jehovah, alle Deine Werke, und Deine Heiligen Dich segnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Sie sollen sprechen von Deines Reiches Herrlichkeit; und reden von Deiner Macht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'Um kund zu tun den Söhnen des Menschen Deine Macht, und die Herrlichkeit der Ehre Seines Reiches.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Dein Reich ist ein Reich aller Ewigkeiten, und Deine Herrschaft ist auf jedes Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Jehovah ist ein Anhalt allen, die da fallen, und richtet alle die Gebeugten auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Aller Augen warten auf Dich, und Du gibst ihnen ihre Speise zu seiner Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'Du tust Deine Hand auf und sättigst alles, was lebt, mit Wohlgefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Jehovah ist gerecht in allen Seinen Wegen, und heilig in allen Seinen Taten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Jehovah ist allen nahe, die Ihn anrufen, allen, die Ihn anrufen in Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Nach dem Wohlgefallen derer, die Ihn fürchten, tut Er, und hört auf ihren Angstschrei und rettet sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Jehovah hütet alle, die Ihn lieben, und vernichtet alle Ungerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Das Lob Jehovahs rede mein Mund und alles Fleisch segne den Namen Seiner Heiligkeit in Ewigkeit und immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Hallelujah! Lobe Jehovah, meine Seele!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Ich will Jehovah loben in meinem Leben, will meinem Gotte Psalmen singen, weil ich bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Vertrauet nicht auf Fürsten, nicht auf den Sohn eines Menschen, in dem kein Heil ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Sein Geist geht aus, er kehrt zurück zu seinem Boden; an selbigem Tage vergehen alle seine Pläne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Selig der, des Beistand der Gott Jakobs ist, des Erwartung ist auf Jehovah, seinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'Der Himmel und Erde, das Meer, und alles, was darin ist, hat gemacht, Der Wahrheit hält in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'Der Gericht tut für den Niedergedrückten, Brot gibt den Hungrigen; Jehovah löst die Gebundenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Jehovah macht Blinde sehend, Jehovah richtet die Gebeugten auf, Jehovah liebt die Gerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Jehovah hütet die Fremdlinge; Er läßt feststehen Waise und Witwe, und stürzt um der Ungerechten Wege,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Jehovah ist König in Ewigkeit, dein Gott, o Zion, für Geschlecht und Geschlecht! Hallelujah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Hallelujah! Denn es ist gut Psalmen zu singen unserem Gott, denn es ist lieblich; ziemend ist Lob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Jehovah baut Jerusalem, Er faßt zusammen die Verstoßenen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'Er heilt, die gebrochenen Herzens sind, und verbindet ihre Schmerzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'Der Sterne Zahl berechnet Er, sie alle nennt Er mit Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Groß ist unser Herr und hat viel Kraft, und unermeßlich ist Seine Einsicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Jehovah läßt feststehen die Elenden, Er erniedrigt die Ungerechten bis zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Singet Jehovah zu mit Bekennen, singet Psalmen unserem Gott zur Harfe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Die Himmel deckt Er mit dichten Wolken, Regen bereitet Er der Erde, läßt auf den Bergen Gras sprossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Er gibt dem Vieh seine Nahrung den jungen Raben, die Ihn anrufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Er hat nicht Lust an Rosses Macht, noch an des Mannes Beinen Wohlgefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Jehovah hat Wohlgefallen an denen, die Ihn fürchten, die auf Seine Barmherzigkeit warten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'Preise Jehovah, o Jerusalem, lobe deinen Gott, o Zion.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Weil Er die Riegel deiner Tore stark gemacht, gesegnet deine Söhne in deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'Der deiner Grenze Frieden setzt, dich mit des Weizens Fett sättigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'Der auf die Erde sendet Seine Rede, so daß in Eile läuft dahin Sein Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'Der Schnee wie Wolle gibt, wie Asche den Reif ausstreut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'Der Sein Eis wie Brocken wirft. Vor Seinem Froste, wer kann stehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Er sendet Sein Wort und schmelzt sie, läßt wehen Seinen Wind; es rieseln die Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Jakob sagt Er an Sein Wort, Israel Seine Satzungen und Rechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Nicht also tat Er irgendeiner Völkerschaft, und sie kennen die Rechte nicht. Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Hallelujah, lobet Jehovah von den Himmeln her, lobet Ihn in den Höhen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Lobet Ihn, alle Seine Engel! Lobet Ihn alle Seine Heerscharen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Lobet Ihn, Sonne und Mond, lobet Ihn, all ihr Sterne des Lichtes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Lobet Ihn, ihr Himmel der Himmel, und ihr Wasser, die ihr über den Himmeln seid!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'Sie sollen den Namen Jehovahs loben; denn Er gebot, und sie waren geschaffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'Und Er läßt sie stehen immerfort und in Ewigkeit, eine Satzung hat Er gegeben, und sie geht nicht vorüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Lobet Jehovah von der Erde, Walfische und alle Abgründe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'Feuer und Hagel, Schnee und Dampf, Wind des Sturmes, der Sein Wort tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 'Berge und Hügel alle, Fruchtbäume und alle Zedern!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'Wild und alles Vieh, Kriechtiere und befiederte Vögel!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'Könige der Erde und alle Volksstämme, ihr Obersten und alle Richter der Erde!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'Jünglinge und auch Jungfrauen, Alte mit den Jungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'Jehovahs Namen sollen sie loben; denn hoch ist Sein Name allein, Seine Majestät über Erde und Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'Und erhöht hat Er das Horn Seinem Volke, das Lob all Seinen Heiligen, den Söhnen Israel, dem Volke, das Ihm nahe ist. Hallelujah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Hallelujah! Singet Jehovah ein neues Lied, Sein Lob in der Versammlung der Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Israel, sei fröhlich in Dem, so Ihn gemacht hat! Die Söhne Zions sollen frohlocken in ihrem König!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Sie sollen loben Seinen Namen in Reigen, singt Ihm Psalmen auf Pauke und Harfe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Denn Wohlgefallen hat Jehovah an Seinem Volke. Die Elenden schmückt Er mit Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Jauchzen sollen in Herrlichkeit die Heiligen, auf ihren Lagern jubeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Mit ihren Kehlen Gott erhöhen, und in ihrer Hand das zweischneidige Schwert,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'Zu üben Rache an den Völkerschaften, an den Volksstämmen Strafen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'Zu binden ihre Könige mit Ketten, und ihre Herrlichen mit eisernen Fußschellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'An ihnen das geschriebene Gericht zu tun. Solche Ehre haben alle Seine Heiligen. Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Hallelujah! Lobet Gott in Seinem Heiligtum! Lobet Ihn in der Ausbreitung Seiner Stärke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Lobet Ihn in Seiner Macht! Lobet Ihn nach Seiner vielen Größe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Lobet Ihn mit dem Schall der Posaune! Lobet Ihn mit Psalter und Harfe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Lobet Ihn mit Pauke und Reigen! Lobet Ihn mit Saitenspiel und der Orgel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Lobet Ihn mit helltönenden Zimbeln! Lobet mit schmetternden Zimbeln!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Alles, was Odem hat, lobe Jah! Hallelujah!');
