INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Gesicht Jesajahs, des Sohnes Amoz, das er erschaute über Jehudah und Jerusalem in den Tagen Ussijahs, Jothams, Achas, Chiskijahus, der Könige von Jehudah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Höret, ihr Himmel und nimm zu Ohren du Erde, denn Jehovah redet: Söhne habe Ich großgezogen und erhöht und sie sind von Mir abgefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Der Ochse kennt seinen Besitzer und der Esel die Krippe seines Meisters; Israel weiß es nicht, und Mein Volk hat keine Einsicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Wehe der sündhaften Völkerschaft, dem Volk mit Missetat beschwert, dem Samen der Bösewichter, den verdorbenen Söhnen! Verlassen haben sie Jehovah, verlästert den Heiligen Israels, und sind Ihm entfremdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Was sollt ihr weiter geschlagen werden? Ihr mehret den Abfall. Das ganze Haupt ist krank und es siecht das ganze Herz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Von der Fußsohle und bis zum Haupt ist nichts Gesundes an ihm. Wunde und Strieme und frischer Schlag, nicht ausgedrückt noch verbunden, noch mit Öl erweicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Euer Land ist wüste, eure Städte verbrannt mit Feuer. Vor euch fressen Fremde euren Boden auf; und er ist wüste, als von Fremden umgekehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'Und Zions Tochter bleibt übrig, wie eine Hütte im Weinberg, wie eine Nachthütte im Gurkenfeld, wie eine belagerte Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Hätte uns Jehovah der Heerscharen nicht einen Rest übriggelassen, wie ein Kleines, wie Sodom wären wir, Gomorrah glichen wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Höret das Wort Jehovahs, Sodoms Anführer; nimm zu Ohren das Gesetz unseres Gottes, Volk Gomorrahs!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Was soll Mir eurer Opfer Menge? spricht Jehovah. Satt bin Ich der Brandopfer der Widder und des Fettes der Gemästeten, und habe keine Lust am Blut der Farren und der Schafe und Böcke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Wenn ihr hereinkommt, Mein Angesicht zu sehen, wer hat solches von eurer Hand gefordert, daß ihr Meine Vorhöfe zerstampfen sollt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Bringt nicht mehr eitel Speiseopfer herein! Ein Greuel ist Mir Räuchwerk, Neumond und Sabbath, das Ausrufen der Zusammenberufung. Nicht ertrag Ich das Unrecht und die Festversammlung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Eure Neumonde und Festzeiten hasset Meine Seele, zur Beschwerde sind sie geworden Mir, Ich bin es müde, sie zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'Und wenn ihr eure Hände ausbreitet, so decke Ich Meine Augen zu vor euch. Auch wenn ihr viel des Betens macht, höre Ich es nicht: eure Hände sind voll Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Waschet, läutert euch, tut weg vor meinen Augen das Böse eurer Werke. Höret auf, Böses zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'Lernet Gutes tun, fraget nach Recht, helfet auf den Unterdrückten, richtet die Waise, hadert für die Witwe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Kommt doch und laßt uns rechten, spricht Jehovah. Sind wie Scharlach eure Sünden, sie sollen weiß wie der Schnee werden, und sind sie rot wie Rosinfarbe, sie sollen wie die Wolle werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Seid ihr willig und höret, sollet ihr essen das Gute des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Weigert ihr euch aber, und seid widerspenstig, werdet ihr vom Schwert gefressen, denn der Mund Jehovahs hat es geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'Wie ist zur Buhlerin geworden die treue Stadt, sie war voll von Recht, Gerechtigkeit übernachtete in ihr, jetzt aber Mörder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Dein Silber ist zu Schlacken geworden, dein Wein mit Wasser vermischt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Störrisch sind deine Obersten und Gesellen von Dieben, jeder liebt Geschenke und jagen der Vergeltung nach, schaffen nicht Recht dem Waisen, lassen der Witwe Rechtshandel nicht vor sich kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Darum, so spricht der Herr, Jehovah der Heerscharen, der Gewaltige Israels: Wehe! Ich tröste Mich an Meinen Drängern und räche Mich an Meinen Feinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'Und Ich wende Meine Hand zurück gegen dich und läutere wie Lauterkeit deine Schlacken und tue weg all dein Zinn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'Und gebe dir wieder deine Richter, wie zuerst, und deine Räte, wie zu Anbeginn. Danach wird man dich nennen Stadt der Gerechtigkeit, die getreue Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Zion wird durch das Gericht eingelöst werden, und durch Gerechtigkeit, die in ihm zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Und Bruch über die Übertreter und Sünder allzumal, und verzehrt werden, die Jehovah verließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Denn sie werden sich der Eichen schämen, die ihr begehrtet, und erröten ob den Gärten, die ihr euch erwähltet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Denn ihr werdet wie eine Eiche sein, deren Blatt welkt, und wie ein Garten, der kein Wasser hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'Und werden wird zu Werg der Mächtige und sein Tun zum Funken, daß beide zusammen brennen und niemand es lösche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Das Wort, das Jeschajahu, Amoz Sohn, erschaute über Judah und Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'Und wird geschehen in den letzten Tagen, daß der Berg von Jehovahs Haus befestigt wird als Haupt der Berge, und erhaben über den Hügeln, und zu ihm alle Völkerschaften strömen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'Und viele Völker werden gehen und sprechen: Lasset uns gehen und hinaufziehen zum Berg Jehovahs, zum Haus des Gottes Jakobs, daß Er uns weise Seine Wege und wir wandeln in Seinen Pfaden, denn von Zion geht aus das Gesetz, und das Wort Jehovahs von Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'Und richten wird Er zwischen den Völkerschaften und strafen viele Völker. Und sie werden ihre Schwerter zu Hacken und ihre Spieße zu Winzermessern schmieden. Nicht wird Völkerschaft wider Völkerschaft das Schwert erheben, nicht wird man fürder streiten lernen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'Gehet, o Haus Jakobs, laßt uns im Lichte Jehovahs wandeln!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Denn Du gabst dahin Dein Volk, das Haus Jakobs, weil es voll vom Morgenland, und Zeichendeuter sind gleich den Philistern und fallen den Kindern des Auslandes bei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'Und voll ward sein Land von Silber und von Gold, und seiner Schätze war kein Ende, und sein Land ward voller Rosse, und seiner Streitwagen war kein Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Und sein Land ward voller Götzen; vor seiner Hände Werk, das ihre Finger machten, beugten sie sich nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'Und der Mensch beugt sich nieder und der Mann erniedrigt sich davor, das wirst Du ihnen nicht vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Gehe ein in den Felsen und verkrieche dich in den Staub vor Jehovahs Schauer und vor der Ehre Seiner Hoheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Die hoffärtigen Augen des Menschen müssen erniedrigt werden, der Männer Überhebung sich bücken; und allein hoch wird an jenem Tage Jehovah sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Denn der Tag Jehovahs ist über alles Hochmütige und Erhöhte und über alles Erhabene, und es wird erniedrigt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'Und über alle Zedern Libanons, die Erhöhten und die Erhabenen, und über alle Eichen Baschans;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'Und über alle erhöhten Berge und über alle erhabenen Hügel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'Und über jeden emporragenden Turm und über jegliche befestigte Mauer,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'Und über alle Schiffe von Tharschisch und über alle Bilder des Begehrens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Und die Hoheit des Menschen muß sich beugen, sich erniedrigen der Männer Überhebung; und allein hoch wird an jenem Tage Jehovah sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'Und mit den Götzen wird es ganz und gar vorbei sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'Und sie gehen ein in die Höhlen der Felsen und in des Staubes Löcher vor dem Schauer Jehovahs und vor der Ehre Seiner Hoheit, wenn Er Sich aufmacht, die Erde zu schrecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'An jenem Tage wirft der Mensch die Götzen von seinem Silber und Götzen von seinem Gold, die sie zur Anbetung sich gemacht, den Maulwürfen und Fledermäusen hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'Daß er eingehe in die Klüfte der Felsen und in das Geklüfte der Felsenklippen vor dem Schauer Jehovahs, und vor der Ehre Seiner Hoheit, wenn Er Sich aufmacht, die Erde zu schrecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Höret auf auch vom Menschen, in dessen Nase der Odem ist; denn für was ist er zu achten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Denn siehe, der Herr Jehovah Zebaoth nimmt von Jerusalem und von Judah Stütze und Stecken weg, alle Stütze des Brotes und alle Stütze des Wassers,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'Den Helden und den Mann des Krieges, den Richter und den Propheten, den Wahrsager und den Ältesten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'Den Obersten von Fünfzig, den Angesehenen und den Rat, den weisen Flüsterer und den, der Beschwörung versteht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'Und Ich gebe Jungen zu ihren Obersten, und Unmündige sollen herrschen über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'Und erpressen wird das Volk, Mann wider Mann, und der Mann wider seinen Genossen. Wider den Greis erfrecht sich der Junge und wider den Geehrten der Geringe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Ein Mann erfaßt seinen Bruder von des Vaters Haus: Du hast ein Gewand, sollst unser Anführer sein, und dieser Trümmerhaufen sei unter deine Hand!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'Der hebt an selben Tage an zu sprechen: Ich werde nicht verbinden; und es ist kein Brot in meinem Haus und kein Gewand; setzt mich nicht dem Volk zum Anführer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Denn es strauchelt Jerusalem und Jehudah ist gefallen, weil ihre Zunge und was sie tun wider Jehovah ist, sich dem Auge Seiner Herrlichkeit widersetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Die Frechheit ihres Angesichts antwortet wider sie. Und sie sagen an ihre Sünde wie Sodom, verhehlen nicht. Wehe ihrer Seele, sie erweisen sich selber Böses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Saget dem Gerechten: Es ist gut, denn die Frucht ihrer Handlungen werden sie essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Wehe dem Ungerechten, es ist böse; denn seiner Hände Verdienst wird ihm getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Mein Volk, seine Treiber sind Kindlein und Weiber herrschen über es. Mein Volk, die so dich anleiten, führen dich irre, und verschlingen deiner Pfade Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Jehovah ist aufgetreten zu hadern, und steht, den Völkern Recht zu sprechen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Jehovah kommt ins Gericht mit den Ältesten Seines Volkes und seinen Obersten: Und ihr habt den Weinberg abgebrannt und das dem Elenden Entrissene in euren Häusern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Was ist euch? Zerstoßen habt ihr Mein Volk und das Angesicht der Elenden zermahlen! spricht der Herr, Jehovah Zebaoth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Und Jehovah spricht: Weil Zions Töchter hoffärtig sind, und die Kehle gereckt dahergehen und die Augen umherwerfen, gehen und trippelnd einhergehen und mit ihren Fußspangen klirren:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'So wird der Herr den Scheitel der Töchter Zions kahl machen, und Jehovah wird ihre Scham entblößen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Am selben Tage wird der Herr wegnehmen der Knöchelringe Schmuck und der Netze und der kleinen Monde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'Das Halsgeschmeide und die Kettchen und die Goldblättchen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'Den Kopfschmuck und die Schrittfesseln, die Bänder und die Riechfläschchen und Ohrgehänge;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'Die Fingerringe und die Nasenringe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'Die Feierkleider und die Mäntel, und die Oberkleider und die Beutel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'Die Spiegel, und die Hemdchen und die Kopfbinden und Überwürfe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'Und geschehen wird, daß statt Gewürzduft Moder da sein wird, statt eines Gürtels Lappen, Kahlheit statt des Lockwerks, und statt des weiten Mantels ein Sack umgegürtet, Brandmal statt Schönheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Es werden deine Leute durch das Schwert fallen und deine Macht im Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'Und ihre Pforten ächzen und trauern, und verödet sitzt sie auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'Und es werden sieben Weiber anfassen einen Mann an selbigem Tage und sprechen: wir wollen unser Brot essen, und anziehen unser eigenes Gewand, nur laß uns nach deinem Namen nennen, nimm unsere Schmach von uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'An jenem Tage wird Jehovahs Sproß zur Zierde und zur Herrlichkeit, und der Erde Frucht zum Stolz und zum Schmuck sein denen aus Israel, die entkommen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'Und wer da verbleibt auf Zion und die übrigen in Jerusalem, der wird Ihm heilig heißen, ein jeglicher, der in Jerusalem zum Leben geschrieben worden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'Wenn der Herr den Unflat der Töchter Zions gewaschen und das Blut Jerusalems aus seiner Mitte abgespült hat mit dem Geist des Gerichts und mit dem Geist des Brennens,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'Da schafft Jehovah über jede Stätte des Berges Zion und über ihre Zusammenberufung bei Tag die Wolke und bei Nacht Rauch und den Glanz der Flamme des Feuers; denn über alle Herrlichkeit wird eine Hülle sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'Und sie sei eine Hütte zum Schatten vor der Gluthitze am Tag, und ein Schirm und eine Verbergung vor Überschwemmung und vor Regen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Laß mich doch meinem Geliebten singen ein Lied meines Freundes von Seinem Weinberg. Mein Geliebter hatte einen Weinberg auf dem Horn des Ölsohns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Und Er umzäunte ihn und säuberte ihn von Steinen, und pflanzte ihn mit Edelreben. Und Er baute einen Turm in seiner Mitte, und Er grub auch darin eine Weinkufe aus und hoffte, daß er Trauben brächte und er brachte Herlinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Und nun, Bewohner Jerusalems und Mann Jehudahs richtet doch zwischen Mir und Meinem Weinberge!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Was sollte Ich noch für Meinen Weinberg tun, das Ich nicht an ihm tat? Was hoffte Ich, daß er Trauben brächte - und er brachte Herlinge?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Und nun will Ich euch doch zu wissen tun, was Ich Meinem Weinberge tun werde: Sein Heckenzaun wird weggetan, daß man ihn abweidet, seine Mauer durchbrochen, daß er zerstampft wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Zur Abödung mache Ich ihn, daß man ihn nicht schneidet, noch behackt, und Dornsträucher und Dorngestrüpp auf ihm aufgeht, und den Wolken verbiete Ich, Regen auf ihn regnen zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Denn der Weinberg Jehovahs der Heerscharen ist das Haus Israels und der Mann Jehudahs die Pflanzung Seiner Ergötzungen. Und Er hoffte auf Gericht, und siehe: Krätze; auf Gerechtigkeit, und siehe: ein Schreien!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Wehe denen, die Haus an Haus reihen, die Feld an Feld fügen, bis kein Raum da ist, und ihr allein inmitten des Landes wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'In meinen Ohren ist es von Jehovah der Heerscharen: Fürwahr, zur Verwüstung sollen werden die vielen Häuser, die großen und guten, daß niemand in ihnen wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Denn zehn Joch Weinberg sollen ein Bath geben, und ein Chomer Samen ein Ephah bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Wehe denen, die früh aufstehen am Morgen, um starkem Getränk nachzusetzen, in der Abenddämmung verweilen, daß der Wein ihnen einschürt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Und da sind Harfe und Psalter, Pauke und Pfeife und der Wein ihrer Gastmahle, und auf Jehovahs Werk blicken sie nicht, und das Tun Seiner Hände sehen sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Darum wird Mein Volk, weil es nichts weiß, weggeführt und seine Herrlichkeit sind Leute des Hungers, und seine Menge verdorrt vor Durst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Darum erweitert die Hölle ihre Seele, öffnet weit ohne Maß ihren Mund und hinabfährt seine Ehre, und seine Menge und sein Tosen und sein Jauchzen darin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'Und es wird gebeugt der Mensch und erniedrigt der Mann. Und erniedrigt werden die Augen der Hoffärtigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'Und hoch ist Jehovah der Heerscharen im Gericht und geheiligt in Gerechtigkeit Gott, der Heilige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'Und Lämmer sollen weiden wie auf ihrer Trift und Fremde zehren auf die Einöden der Feisten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Wehe denen, so die Missetat an Stricken der Eitelkeit herbeiziehen und die Sünde wie mit Wagenseilen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'Die sprechen: Er eile, Er beschleunige Sein Tun, auf daß wir es sehen! Und der Ratschluß des Heiligen Israels nahe und komme, daß wir es wissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Wehe denen, so Böses gut und Gutes böse heißen, die Finsternis zum Licht und Licht setzen zur Finsternis; die aus bitter süß und aus süß bitter machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Wehe denen, die in ihren Augen weise sind, und sind vor ihrem Angesichte einsichtsvoll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Wehe den Helden im Weintrinken und den Männern der Tapferkeit im Mischen starker Getränke!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'Die um ein Geschenk den Ungerechten rechtfertigen und die Gerechtigkeit des Gerechten von ihm wegwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Darum, wie des Feuers Zunge frißt die Stoppel und Heu hinsinkt in der Flamme, so wird wie Moder sein ihre Wurzel und ihre Blüte fliege auf wie feiner Staub, weil sie das Gesetz Jehovahs der Heerscharen verschmähten und die Rede des Heiligen von Israel lästerten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Darum ist Jehovahs Zorn entbrannt wider Sein Volk und Seine Hand darüber ausgestreckt; und Er schlägt es. Und die Berge zittern und ihr Leichnam liegt wie Unrat inmitten der Gassen. Bei all dem kehret Sein Zorn sich nicht zurück und noch ist Seine Hand ausgestreckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'Und Er erhebt ein Banner den Völkerschaften von ferne und pfeift ihm von dem Ende der Erde; und siehe, eilend, schnell, kommt Er daher!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Kein Matter und kein Strauchelnder ist darin. Er schlummert nicht, noch schläft Er; Er tut nicht auf den Gürtel Seiner Hüften, reißt den Riemen Seiner Schuhe nicht auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Geschärft sind Seine Pfeile und alle Seine Bogen gespannt, wie Felsen sind geachtet Seiner Rosse Hufen und wie der Sturmwind Seine Räder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Sein Gebrüll ist wie das des Löwen und wie junger Löwen Gebrüll, und Er tobt und ergreift das Zerfleischte und entschleppt, und keiner befreit es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'Und Er tobt darüber her an selbem Tag wie das Toben des Meeres; und Er blickt zur Erde, und siehe, Finsternis, Bedrängnis und das Licht wird Finsternis in ihren Trümmern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'Im Jahr, da König Ussijahu starb, sah ich den Herrn auf hohem und erhabenem Throne sitzen, und Seine Säume füllten den Tempel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Seraphe standen über Ihm, sechs Flügel, sechs Flügel hatte einer. Mit zweien deckte er sein Angesicht und mit zweien deckte er seine Füße und mit zweien flog er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'Und einer rief zum anderen und sprach: Heilig, heilig, heilig ist Jehovah der Heerscharen, die Fülle der ganzen Erde ist Seine Herrlichkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'Und es erbebten der Schwellen Pfosten vor der Stimme des Rufenden, und das Haus ward voll Rauch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Und ich sprach: Wehe mir, ich vergehe; denn ein Mann unreiner Lippen bin ich und inmitten eines Volkes unreiner Lippen wohne ich; denn meine Augen sahen den König, Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'Und es flog einer von den Seraphen zu mir und in seiner Hand eine glühende Kohle, die mit einer Zange er vom Altar genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'Und er berührte damit meinen Mund und sprach: Siehe, diese berührt deine Lippen und weggewichen ist deine Missetat und deine Sünde ist gesühnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'Und ich hörte die Stimme des Herrn, Der sprach: Wen soll Ich senden, und wer geht für Uns? Und ich sprach: Siehe mich, sende mich,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'Und Er sprach: Gehe hin und sprich zu diesem Volk: Höret immerhin und verstehet nicht, sehet immerhin und erkennet nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Verstocke dieses Volkes Herz und mache seine Ohren schwer, verklebe seine Augen, daß es nicht mit den Augen sehe und höre mit seinen Ohren, und sein Herz verstehe und sich umkehre, und ihm Heilung werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Und ich sprach: Bis wie lange Herr? Und Er sprach: Bis daß die Städte verödet sind, daß niemand darin wohnt und die Häuser ohne einen Menschen, und bis der Boden zur Wüste verödet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'Und Jehovah wird entfernen den Menschen, und viel Verlassenheit wird in des Landes Mitte sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'Und der zehnte Teil wird noch darin sein, und wird zurückkehren und ausgerottet werden, wie eine Eiche und wie eine Steineiche; wenn sie hingeworfen wird, bleibt ihr Stock. Ein Same der Heiligkeit ist ihr Stock!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'Und es geschah in den Tagen Achas des Sohnes Jothams, des Sohnes Ussijahus, König von Judah, daß Rezin, König von Aram, und Pekach, der Sohn Remaljahus, König von Israel, gen Jerusalem heraufzogen, um wider dasselbe zu streiten, sie vermochten aber nicht, es zu erstreiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'Und es ward dem Hause Davids angesagt und man sprach: Aram ruht auf Ephraim. Und es erbebten sein Herz und das Herz seines Volkes, wie die Bäume des Waldes vor dem Winde schwanken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Und Jehovah sprach zu Jeschajahu: Gehe doch hinaus, dem Achas entgegen, du und dein Sohn Schear-Jaschub an das Ende der Wassergraben des oberen Teiches, an die Landstraße beim Walkerfeld.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'Und sprich zu ihm: Hüte dich und sei ruhig, fürchte dich nicht, und dein Herz werde nicht weich, ob diesen zwei Schwänzen rauchender Feuerbrände, ob dem Entbrennen des Zornes von Rezin und Aram und dem Sohn Remaljahus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Darob, daß Aram Böses ratschlagte wider dich, Ephraim und Remaljahus Sohn und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Laßt uns hinauf nach Jehudah ziehen und es aufwecken und für uns spalten, und Tabeels Sohn als König in seiner Mitte regieren lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'So spricht der Herr Jehovah: Nicht soll es erstehen, und es soll nicht sein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Denn Arams Haupt ist Damask, und Damasks Haupt Rezin. Und in noch fünfundsechzig Jahren ist Ephraim zerrüttet, daß sie kein Volk mehr seien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'Und Schomron ist Ephraims Haupt, und Schomroms Haupt der Sohn Remaljahus. Und glaubt ihr nicht, so bewähret ihr euch nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'Und Jehovah redete wiederum zu Achas und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Bitte dir ein Zeichen von Jehovah, deinem Gott, mache was du dir bittest, in der Tiefe, oder droben in der Höhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Und Achas sprach: Ich bitte um nichts und will Jehovah nicht versuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Und Er sprach: So hört denn, o Haus Davids! Ist es euch zu wenig, daß ihr die Männer ermüdet, müßt ihr auch meinen Gott ermüden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Darum wird der Herr euch Selbst ein Zeichen geben: Siehe, eine Jungfrau wird empfangen und einen Sohn gebären, und Seinen Namen nennen Immanuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Butter und Honig wird Er essen, daß Er wisse, Böses zu verschmähen und Gutes zu erwählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Denn ehe noch der Junge weiß, Böses zu verschmähen und Gutes zu erwählen, wir der Boden, vor dem dir graut verlassen sein vor seinen zwei Königen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Jehovah läßt über dich und über dein Volk und über deines Vaters Haus Tage kommen, wie sie nicht sind gekommen seit dem Tag, da Ephraim von Judah abfiel: den König von Assyrien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'Und es geschieht an jenem Tage, daß Jehovah der Fliege zischt, die an den Enden der Ströme Ägyptens ist, und der Biene im dem Lande Aschurs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'Und sie werden kommen und allesamt ruhen an den Bächen der Abödungen und in den Klüften der Felsenklippen, und in allen Dorngebüschen und an allen Bächlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'An jenem Tage wird der Herr mit dem Schermesser, gedungen an den Furten des Flusses, durch Aschurs König abscheren das Haupt und das Haar an den Füßen, und auch den Bart nimmt es hinweg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'Und es geschieht an jenem Tag, daß ein Mann eine Färse vom Rinde lebendig behält und zwei Schafe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'Und ob der vielen Milch, die er gewinnt, wird er Butter essen; denn Butter und Honig ißt jeder, der inmitten des Landes übrigblieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Und an jenem Tage wird geschehen, daß jeder Ort, da tausend Weinstöcke gewesen, zu tausend Silberlingen, zum Dornstrauch und Dorngestrüppe wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'Mit Pfeilen und mit dem Bogen kommt man hin: denn Dornsträucher und Dorngestrüppe sind im ganzen Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Und auf alle die Berge, die mit der Hacke man behackt, dorthin wird nicht kommen die Furcht von Dornstrauch und von Dorngestrüpp; und es wird sein, daß man Ochsen hinsendet, und von Schafen es zerstampfen läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'Und Jehovah sprach zu mir: Nimm dir eine große Tafel und schreibe darauf mit dem Griffel eines Menschen: Es eilt die Beute, es sputet der Raub.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'Und ich ließ es mir bezeugen mit treuen Zeugen, den Priester Urijah und Secharjahu, Jeberechjahus Sohn;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'Und nahte der Prophetin und sie empfing und gebar einen Sohn und Jehovah sprach zu mir: Nenne seinen Namen Maher Schalal Chaschbas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Denn ehe der Junge wird wissen, Vater und Mutter zu rufen, trägt man das Vermögen von Damask und Schomrons Beute vor Aschurs König her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'Und Jehovah redete wiederum weiter zu mir und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Weil dies Volk Schiloachs Wasser verschmäht, die sachte gehen und sich freut an Rezin und Remaljahus Sohn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'Darum, siehe, bringt herauf über sie der Herr des Flusses Wasser, die mächtigen und vielen, Aschurs König und all seine Herrlichkeit. Und er kommt herauf über all seine Flußbette und geht über alle seine Ufer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'Und dringt in Jehudah ein, überflutet und geht darüber, er reicht bis zum Hals. Und die Ausbreitung seiner Flügel wird sein die Fülle der Breite Deines Landes, Immanuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Gesellet euch zusammen, ihr Völker und entsetzet euch, und nehmet zu Ohren, all ihr Fernen der Erde, umgürtet euch und entsetzet euch, umgürtet euch und entsetzet euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Faßt einen Ratschluß und er soll zunichte werden. Redet das Wort, und es kommt nicht zustande; denn mit uns ist Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Denn so sprach Jehovah zu mir mit Kräftigung der Hand, und belehrte mich, nicht auf dem Wege dieses Volkes zu gehen, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Saget nicht: Ein Bündnis! mit allen, mit denen dieses Volk sagt: Ein Bündnis! und fürchtet nicht was sie fürchten, laßt euch nicht grauen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Jehovah Zebaoth, Ihn heiligt! Und Er sei eure Furcht und Er sei euer Grauen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'Und Er wird sein zum Heiligtum; aber ein Stein des Anstoßes und ein Fels des Strauchelns den zwei Häusern Israels, eine Schlinge und ein Fallstrick dem Bewohner Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'Und ihrer viele werden daran straucheln und fallen und zerbrechen, und darin bestrickt und gefangen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Schnüret zu das Zeugnis, versiegle das Gesetz für Meine Jünger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'Ich aber harre auf Jehovah, Der Sein Antlitz birgt vor Jakobs Haus und hoffe auf Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Siehe, hier bin ich und die Kinder, die Jehovah mir gegeben zu Zeichen und zu Wahrzeichen in Israel von Jehovah der Heerscharen, Der auf dem Berge Zion wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'Und wenn sie zu euch sagen: Fraget nach den Totenbeschwörern und den Zeichendeutern, die flüstern und murmeln: Soll nicht ein Volk nach seinem Gott fragen? Soll man für die Lebendigen zu den Toten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Zum Gesetz und zum Zeugnis! Sprechen sie nicht nach solchem Wort, so haben sie noch keine Morgenröte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'Und hart gedrückt und hungernd zieht es darin vorbei; und wenn es hungert, dann ist es entrüstet und flucht seinem König und seinem Gott, und wendet sich aufwärts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'Und blickt es zur Erde, und siehe, Drangsal und Finsternis, umnachtet von Angst, und ins Dunkel hinausgestoßen. Denn nicht ist umnachtet, der geängstigt war; wie Er in früherer Zeit gering hielt im Lande Sebulon und im Lande Naphthali, aber es später verherrlichte auf dem Weg nach dem Meere jenseits des Jordans, in Galiläa, der Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Das Volk, das wandelt in der Finsternis, hat ein großes Licht gesehen. Über die, so im Land des Todesschattens wohnen, erglänzt ein Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Du machst der Völkerschaft viel, hast die Fröhlichkeit groß gemacht. Sie sind fröhlich vor Dir, wie man in der Ernte fröhlich ist, wie man frohlockt beim Teilen der Beute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Denn das Joch seiner Last und den Stab seiner Schulter, und die Rute, damit man ihn trieb, hast Du zerbrochen, wie am Tage Midians.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Denn alles Gedränge wird verdrängt mit Erdbeben, und das Gewand im Blut gewälzet wird verbrannt, ein Fraß des Feuers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Denn ein Kind ist uns geboren, ein Sohn ist uns gegeben, Der auf Seiner Schulter das Fürstentum hat; und Sein Name wird genannt Wunderbar, Rat, Gott, Held, Vater der Ewigkeit, Friedensfürst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Der da mehret das Fürstentum, und des Friedens ist kein Ende, auf Davids Throne und seinem Königreich, es zu befestigen und zu stützen mit Recht und Gerechtigkeit von nun an und bis in Ewigkeit. Der Eifer Jehovahs der Heerscharen tut solches.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'In Jakob hat der Herr ein Wort gesandt. Und es fällt in Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Und wissen soll es das Volk allzumal, Ephraim und Schomrons Bewohner, die im Übermut und Großtun des Herzens sprechen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'Backsteine sind gefallen, laßt uns bauen mit Quadersteinen. Die Sykomoren sind niedergehauen, laßt uns sie mit Zedern ersetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Und Rezins Widersacher wird Jehovah emporheben über ihn, und beschirmen seine Feinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'Aram von vorn und die Philister von hinten, und sie fressen Israel auf mit ganzem Munde. Bei all dem wendet sich Sein Zorn nicht zurück und ist noch ausgestreckt Seine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Aber das Volk kehrt nicht um zu Dem, Der es schlägt, und fragt nicht nach Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'Und abschneiden wird Jehovah von Israel Haupt und Schwanz, Palmzweig und Binse an einem Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Der Alte und Angesehene ist das Haupt, und der Prophet, der in Lüge unterweist, der ist der Schwanz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Die dieses Volk anleiten, führen irre, und verschlungen werden, die sich anleiten lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Darum ist der Herr nicht fröhlich über Seine Jünglinge, und erbarmt Sich Seiner Waisen und Witwen nicht; denn heuchlerisch und böse sind sie alle. Und jeglicher Mund redet Torheit. Ob all dem wendet sich Sein Zorn nicht zurück, und Seine Hand ist noch ausgestreckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Denn die Ungerechtigkeit brennt wie Feuer, das Dornstrauch und Dorngestrüpp auffrißt, daß sich des Waldes Dickicht entzündet und im Emporsteigen des Rauches aufwallt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'In dem Wüten Jehovahs der Heerscharen ist verdunkelt das Land, wie Feuers Speise ist das Volk, der Mann bemitleidet den Bruder nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Und er schneidet ab zur Rechten und hungert, und er ißt zur Linken und wird nicht satt. Ein jeder Mann frißt das Fleisch seines Arms.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Menascheh frißt auf den Ephraim, und Ephraim den Menascheh. Zusammen sind sie gegen Judah. Ob all dem wendet sich Sein Zorn nicht zurück und Seine Hand ist noch ausgestreckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Wehe denen, die Satzungen des Unrechts aufsetzen und Vorschriften der Mühsal schreiben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'Die Armen vom Rechtsspruch zu verdrängen und den Elenden Meines Volkes das Recht zu entreißen, daß Witwen ihre Beute werden und sie die Waisen berauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Und was wollt ihr tun am Tag der Heimsuchung und des Unwetters, das von ferne kommt? Zu wem wollt ihr um Beistand fliehen, und wo lassen eure Herrlichkeit?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Der sich noch nie gebeugt, fällt unter die Gefangenen und unter die Erwürgten. Bei all dem wendet sich Sein Zorn nicht zurück, und Seine Hand ist noch ausgestreckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Wehe, Aschur, die Rute Meines Zorns, und er ist der Stab Meines Unwillens in ihrer Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Ich sende ihn wider eine heuchlerische Völkerschaft und gegen das Volk Meines Wütens entbiete Ich ihn, um Beute zu erbeuten und Raub zu rauben, es zu setzen zum Zerstampfen wie der Gassen Ton.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'Er aber meint es nicht recht und sein Herz denkt das Rechte nicht; weil es in seinem Herzen ist zu vernichten und auszurotten Völkerschaften, nicht wenige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Denn er spricht: Sind meine Obersten nicht allzumal Könige?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Ist nicht Kalno wie Karchemisch, nicht Chamath wie Arpad? nicht Schomron wie Damaskus?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Wie meine Hand gefunden hat die Königreiche der Götzen und die Schnitzbilder derer in Jerusalem und Schomron?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'Kann ich nicht, wie ich Schomron und seinen Götzen getan, auch Jerusalem und seinen Götzenbildern tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Und geschehen wird, wenn der Herr all Sein Tun am Zionsberg und an Jerusalem ausgeführt hat, will ich heimsuchen die Frucht des Großtuns des Herzens von Aschurs König und das Prahlen der Überhebung seiner Augen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Daß er sprach: Ich habe es getan mit der Kraft meiner Hand und mit meiner Weisheit; denn ich bin einsichtsvoll, tue weg der Völker Grenzen und plündere ihre Vorräte, unterwerfe als Gewaltiger die Bewohner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'Und es findet wie ein Vogelnest meine Hand das Vermögen der Völker, und wie man verlassene Eier einsammelt, sammle ich die ganze Erde ein, und keiner ist, der nur mit dem Flügel flattert, noch den Mund aufsperrt und zirpt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Prahlet die Axt gegen den, der mit ihr haut? Tut auch die Säge groß gegen den, der sie zieht? Als schwänge die Rute den, der sie emporhebt; als höbe der Stab den empor, der kein Holz ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Darum sendet der Herr, der Herr der Heerscharen, Magerkeit unter seine Fetten und statt seiner Herrlichkeit läßt Er auflodern eine Lohe wie eines Feuers Lohe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'Und Israels Licht wird zum Feuer und sein Heiliger zur Flamme und brennt und frißt auf sein Dorngestrüpp und seinen Dornenstrauch an einem Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'Und die Herrlichkeit seines Waldes und seines Fruchtgefildes wird Er verzehren von der Seele und bis zum Fleische, und wird werden wie das Hinschwinden eines Siechenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'Und der Überrest der Bäume seines Waldes ist eine Zahl, so daß ein Junge sie schreiben kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'Und es wird geschehen an jenem Tag, daß der Überrest Israels und der Entkommene von Jakobs Haus sich nicht mehr stützt auf den, der es geschlagen, sondern sich stützet auf Jehovah, den Heiligen Israels in Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Der Überrest, Jakobs Überrest, kehrt dann zurück zum Gott dem Mächtigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Denn war auch dein Volk, o Israel, wie der Sand des Meeres, so kehrt ein Überrest davon zurück; Vollendung ist entschieden, es überflutet die Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Denn eine Vollendung macht und eine Entscheidung der Herr Jehovah der Heerscharen in des ganzen Landes Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Darum so sprach der Herr, Jehovah der Heerscharen: Fürchte dich nicht, Mein Volk, Zions Bewohner, vor Aschur, der mit der Rute dich schlägt und seinen Stab aufhebt wider dich im Weg Ägyptens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Denn noch um ein winzig Kleines ist der Unwille vollendet und auf ihren Untergang ist Mein Zorn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'Und Jehovah der Heerscharen schwingt über ihn die Geißel, wie Er am Felsen Oreb Midjan schlug; und über dem Meere ist Sein Stab, und Er erhebt ihn auf dem Wege Ägyptens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'Und an jenem Tag geschieht, daß seine Last von deiner Schulter weggenommen wird, und sein Joch von deinem Nacken, und in Stücke geht das Joch vor dem Fette.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Er kommt gen Ajath, zieht hin durch Migron, mustert zu Michmasch sein Zeug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'Sie ziehen durch Mebara; unser Nachtlager ist zu Geba, Ramah erzittert, Gibea Schaul flieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Laß tönen deine Stimme, Gallims Tochter, horche, Laisch, elendes Anathoth!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmenah entflieht, die so in Gebim wohnen flüchten sich zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Noch diesen Tag zu stehen in Nob; es wird schwingen seine Hand der Berg der Tochter Zions, der Hügel Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Siehe, der Herr Jehovah der Heerscharen haut ab das Geäste mit Grauen, und die von hohem Wuchse werden niedergehauen, und die Emporragenden erniedrigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'Und umgehauen werden des Waldes Dickichte vom Eisen, und durch den Stattlichen fällt der Libanon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'Und ein Reis geht aus Jischais Stamm hervor, und ein Schößling aus seinen Wurzeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'Und auf Ihm ruht der Geist Jehovahs, der Geist der Weisheit und der Einsicht, der Geist des Rates und der Macht, der Geist der Kenntnis und der Furcht Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'Und Sein Wohlgefallen wird sein in der Furcht Jehovahs. Und Er richtet nicht nach dem, was Seine Augen sehen, und rügt nicht nach dem, was Seine Ohren hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'Sondern Er richtet mit Gerechtigkeit die Armen, und rügt in Geradheit die Elenden im Lande, und schlägt die Erde mit der Rute Seines Mundes, und tötet den Ungerechten mit dem Hauch Seiner Lippen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'Und Gerechtigkeit ist Seiner Lenden Gurt und Wahrheit der Gurt Seiner Hüften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'Und der Wolf weilt beim Lamm und der Pardel lagert sich bei dem Böcklein; und das Kalb und der junge Löwe und das Mastvieh beisammen, und ein kleiner Junge treibt sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'Und die Färse und die Bärin weiden, zusammen lagern ihre Jungen. Und der Löwe frißt Stroh wie das Rind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'Und es spielt der Säugling an der Natter Loch, und in des Basilisken Höhle steckt seine Hand das Entwöhnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Sie tun nichts Böses, noch verderben sie auf dem ganzen Berg Meiner Heiligkeit; denn die Erde wird voll sein der Kenntnis Jehovahs, wie die Wasser das Meer bedecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'Und geschehen wird an jenem Tag, daß nach Jischais Wurzel, die dasteht, ein Panier den Völkern, nach Ihm die Völkerschaften fragen werden; und Seine Ruhe ist Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'Und an jenem Tage geschieht, daß der Herr zum zweitenmal hinzutut Seine Hand, den Überrest Seines Volkes zu erwerben, der verblieben ist von Aschur und von Ägypten und von Pathros und von Kusch und von Elam und von Schinear und von Chamath und von des Meeres Inseln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'Und wird den Völkerschaften ein Panier erheben, und sammeln Israels Verstoßene und die Zerstreuten Jehudahs zusammenbringen von den vier Fittichen der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Und die Eifersucht Ephraims weicht fort, und ausgerottet werden Jehudahs Dränger. Ephraim eifert nicht wider Jehudah, und Jehudah bedrängt nicht Ephraim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'Und sie werden fliegen auf die Schulter der Philister dem Meere zu, und berauben zusammen des Ostens Söhne; nach Edom und Moab ihre Hand ausstrecken, und Ammons Söhne werden auf sie hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'Und verbannen wird Jehovah die Zunge des Meeres von Ägypten und Seine Hand schwingen über den Fluß, mit Seines Hauches Heftigkeit und ihn zerschlagen zu sieben Bächen, daß man in Schuhen ihn betritt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'Und eine Bahn wird sein für Seines Volkes Überrest, der verbleibt von Aschur, wie eine war für Israel am Tag, da es heraufzog aus dem Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'Und du wirst sprechen an jenem Tage: Ich bekenne Dich, Jehovah, denn Du zürntest mir; Dein Zorn hat sich zurückgewandt, und Du hast mich getröstet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Siehe, der Gott meines Heils! Ich will vertrauen und will nicht schaudern, denn meine Stärke und Gesang ist Jah Jehovah, und Er ward mir zum Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'Und Wasser werdet ihr schöpfen mit Freudigkeit aus dem Brunnquell des Heils;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'Und werdet sagen an jenem Tag: Bekennet Jehovah, rufet Seinen Namen an! Machet kund unter den Völkern Seine Taten! Laßt gedenken, daß erhaben ist Sein Name!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Singt Psalmen dem Jehovah; denn Hohes hat Er getan. Kund ist es auf der ganzen Erde!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Laß es ertönen und juble, Zions Bewohnerin; denn groß in deiner Mitte ist der Heilige Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Die Weissagung über Babel, was Jeschajahu, Amoz Sohn, erschaute:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Auf ragendem Berge erhebet das Panier, erhöhet die Stimme für sie, winket mit der Hand, daß sie eingehen durch der Fürsten Eingänge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Ich habe geboten meinen Geheiligten, auch meine Helden gerufen zu meinem Zorn, die jauchzen ob meiner Hoheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Die Stimme einer Menge ist auf den Bergen, gleich wie von vielem Volk, die Stimme des Tosens von Königsreichen versammelter Völkerschaften. Jehovah der Heerscharen mustert das Heer zum Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Aus fernem Lande kommen sie, von der Himmel Ende, Jehovah und die Werkzeuge Seines Unwillens, um zu zerstören alles Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Heulet, denn nahe ist Jehovahs Tag. Verheerung von Schaddai kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Darob erschlaffen die Hände aller, und jegliches Menschen Herz zerschmilzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'Sie sind bestürzt, Wehen und Geburtsnöte ergreifen sie, sie kreißen wie eine Gebärerin; ein Mann starrt an seinen Genossen. Flammengesichter sind ihre Angesichter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Siehe, Jehovahs Tag kommt grausam und wütend und mit Entbrennung des Zornes, das Land in Verwüstung zu legen und seine Sünder daraus zu vernichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Denn die Sterne der Himmel und ihre Sternbilder lassen ihr Licht nicht leuchten, die Sonne ist finster in ihrem Ausgang und der Mond läßt sein Licht nicht glänzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'Und heimsuchen will Ich in der Welt das Böse, und an den Ungerechten ihre Misse- tat und dem Stolz der Vermessenen Einhalt tun, und der Trotzigen Übermut erniedrigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Kostbarer will Ich den Mann machen, denn feines Gold, und den Menschen, denn Ophirs lauteres Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Darum lasse Ich die Himmel zittern und die Erde erbeben von ihrem Ort, bei dem Wüten Jehovahs der Heerscharen und am Tage des Entbrennens Seines Zornes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'Und es geschieht, daß wie ein verscheuchtes Reh, und wie die Herde, die keiner zusammenbringt, der Mann zu seinem Volke sich wendet und der Mann nach seinem Lande flieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Jeder, der gefunden wird, wird durchstochen, und jeder, der sich versammelt, fällt durch das Schwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'Und ihre Kindlein werden vor ihren Augen zerschmettert, geplündert ihre Häuser und geschändet ihre Weiber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Siehe, Ich errege wider sie die Meder, die Silber nicht achten und keine Lust am Golde haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'Und die Jünglinge zerschmettern die Bogen und erbarmen sich nicht der Frucht des Leibes, noch schont ihr Auge der Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'Und Babel, die Zierde der Königreiche, der Schmuck des Stolzes der Chaldäer wird wie die Umkehrung Gottes von Sodom und Gomorrah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Nimmermehr wird man darin wohnen, und nicht wohne man da auf Geschlecht und Geschlecht, nicht zeltet dort der Araber und die Hirten lassen dort nicht lagern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Und die Zijim lagern dort, und ihre Häuser füllen die Ochim, und die Töchter der Nachteulen wohnen da, und allda hüpfen die Feldteufel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'Und die Ijim antworten einander in ihren Palästen und Drachen in den Tempeln der Üppigkeit. Und nah ist ihre Zeit, daß sie komme und ihre Tage werden nicht verziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Denn Jehovah wird Sich Jakobs erbarmen und Israel wiederum erwählen und sie auf ihren Boden setzen, und ihnen hängt an der Fremdling und hält sich zum Hause Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'Und die Völker werden sie nehmen und hineinbringen an ihren Ort. Und das Haus Israel wird sie ererben auf dem Boden Jehovahs zu Knechten und zu Dienstmägden, und wird gefangen führen, die so es hatten gefangengeführt, und sich unterwerfen seine Treiber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'Und es wird geschehen, daß am Tag, da dir Jehovah Ruhe gibt von deinen Schmerzen und von deiner Beunruhigung und von der harten Knechtschaft, in der du dienen mußtest,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'Da wirst du diesen Spruch erheben über den König Babels und sprechen: Wie hört doch der Treiber auf, wie hört die Goldsucht auf!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Zerbrochen hat Jehovah den Stab der Ungerechten, die Rute der Herrschenden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'Er, Der die Völker schlug in Wut, mit Schlägen ohne Ablenken, Der die Völkerschaften beherrscht im Zorn, Der verfolgt ohne Zurückhaltung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Es ruhet und rastet die ganze Erde, sie sind in Jubel ausgebrochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Auch die Tannen sind fröhlich ob dir, die Zedern Libanons: Seitdem du liegst, kommt niemand herauf, um uns umzuhauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Die Hölle drunten zitterte ob dir, entgegen dir zu kommen, sie erregte dir die Rephaim, alle die Rüstigen der Erde; sie ließ aufstehen von ihren Thronen alle Könige der Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Sie alle antworten und sprechen zu dir: Auch du bist wie wir hinfällig geworden, bist uns gleich geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'Zur Hölle ist hinabgefahren dein Stolz und deiner Psalter Toben; Maden sind deine Streue unter dir und deine Decke Würmer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Wie bist vom Himmel du gefallen, du Leuchtender, Sohn der Morgenröte? Zur Erde niedergehauen, geschwächt unter den Völkerschaften!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Und du sprachst in deinem Herzen: Zu den Himmeln steige ich auf, über die Sterne Gottes erhöhe ich meinen Thron, und will sitzen auf dem Berg der Versammlung auf den Hinterseiten der Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Ich will hinaufsteigen auf der Wolken Höhen, will mich dem Höchsten gleichmachen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Doch wirst du hinabgestürzt zur Hölle, auf die Hinterseiten der Grube.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Die dich sehen, schauen dich an, betrachten dich: Ist das der Mann, der die Erde zittern, die Königreiche erbeben machte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'Er machte zur Wüste die Welt, riß nieder ihre Städte, löste seine Gebundenen nicht, nach Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Alle Könige der Völkerschaften liegen allzumal in Herrlichkeit, jeder Mann in seinem Haus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'Du aber wirst aus deinem Grab geworfen, wie ein verabscheuter Schößling, das Kleid Erwürgter, vom Schwert Durchbohrter, die an die Steine der Grube hinabfahren, wie eine zertretene Leiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Nicht wirst du mit ihnen vereint in dem Grabe; denn du hast verdorben dein Land und hast dein Volk erwürgt, nicht wird in Ewigkeit genannt der Bösen Samen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Bereitet für ein Schlachten seine Söhne um ihrer Väter Missetat willen, daß sie nicht aufstehen und das Land besitzen, und der Welt Angesicht mit Städten füllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'Und Ich will Mich aufmachen wider sie, spricht Jehovah der Heerscharen, und ausrotten zu Babel Namen und Überrest und Sproß und Schoß, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'Und will es machen zum Erbbesitze der Entenadler und zu Teichen des Wassers; und sie fortkehren mit dem Besen der Vernichtung, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Jehovah der Heerscharen schwor es und sprach: Wie Ich es gemeint, so soll es werden, und wie Ich es beratschlagte, soll es erstehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'Daß Aschur zerbreche in Meinem Land und Ich ihn zertrete auf Meinen Bergen, auf daß sein Joch von ihnen fortweiche und seine Last fortweiche von ihrer Schulter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'Dies ist der Ratschluß, beschlossen über alles Land, und das ist die Hand, über alle Völkerschaften ausgestreckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Denn Jehovah der Heerscharen hat es beschlossen, und wer will es zunichte machen? Und Seine Hand ist ausgereckt. Und wer will sie zurückwenden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'Im Jahr, da König Achas starb, war dies die Weissagung:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Sei nicht fröhlich, du ganz Philistäa, daß die Rute, die dich schlug, zerbrochen ist; denn aus der Wurzel der Schlange geht ein Basilisk hervor, und seine Frucht ist eine fliegende Feuerschlange.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'Und die Erstgeborenen der Armen weiden und die Dürftigen lagern in Sicherheit, aber durch Hunger töte Ich deine Wurzel und deinen Überrest erwürget er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Heule, Tor! Schreie, Stadt! Zerfließe, du ganz Philistäa, weil von Mitternacht ein Rauch kommt, und kein Einsamer in seinen Versammlungen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Und was wird man den Boten der Völkerschaft antworten? Daß Jehovah hat Zion gegründet, und auf es verlassen sich die Elenden von Seinem Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Weissagung über Moab. Fürwahr, in der Nacht ist Ar verheert, ist Moab untergegangen. Fürwahr in der Nacht ist Kir-Moab verheert, ist untergegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Bajith und Dibon ziehen hinauf nach Bamoth, zu weinen. Auf Nebo und auf Medeba heult Moab. Kahlheit ist auf aller Haupt, jeder Bart ist abgeschoren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'In seinen Gassen gehen sie mit Säcken gegürtet. Auf seinen Dächern und in seinen Straßen heult alles, es rinnt herab mit Weinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'Und Chesbon schreit und Elealeh, bis Jahaz wird ihre Stimme gehört. Darum schreien auf Moabs Gerüstete, Übel ist es in seiner Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Mein Herz schreit um Moab, seine Flüchtlinge sind bis Zoar hin, eine dreijährige Färse, denn den Steig nach Luchith - unter Weinen steigt man ihn hinan; denn auf dem Weg nach Choronajim erregen sie ein Geschrei des Zerbrechens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Denn wüste sind die Wasser Nimrims; denn vertrocknet ist das Gras, verzehrt das junge Kraut, nichts Grünes ist da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Darum tragen sie das übrige, das sie gemacht, und ihr Erspartes über den Bach der Weiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Denn Geschrei umringt Moabs Grenze; bis Eglajim ihr Heulen, und das Heulen bis Beer-Elim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Denn Dimons Wasser sind voll Blut; denn weiteres lege Ich auf Dimon, auf Moabs Entkommene: einen Löwen, und für das übrige des Bodens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Sendet das Lamm des Herrschers des Landes von Sela nach der Wüste zum Berg der Tochter Zions.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'Und wie ein flüchtiger Vogel, ein entsandtes Nest, werden die Töchter Moabs sein an Arnons Furten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Bringet Rat, machet Entscheid, setze deinen Schatten in der Mitte des Mittags wie die Nacht, birg die Verstoßenen und offenbare den Flüchtigen nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Lasset meine Verstoßene in dir weilen; o Moab, sei ihnen eine Burg vor dem Verheerer, bis der Bedrücker ein Ende hat, alle wird der Verheerer, der Zerstampfer ein Ende nimmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'Und befestigt wird der Thron durch Barmherzigkeit, und auf ihm sitzt in Wahrheit in Davids Zelt ein Richter, der nach Recht fragt und eilends fördert die Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Wir hören von Moabs Stolz, er ist sehr hochmütig, von seinem Hochmut und seinem Stolz und seinem Wüten, und von seinen Unwahrheiten, die nicht richtig sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Darob wird heulen Moab, ganz Moab wird heulen ob den Grundfesten von Kir-Chareseth; ihr werdet seufzen ganz zerknirscht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Denn Cheschbons Gefilde ist verschmachtet, der Weinstock Sibmahs; die Meister der Völkerschaften zerschlugen seine Edelreben, bis Jaeser reichten sie, sie wanderten über die Wüste hin, und seine Ranken breiteten sich hin und gingen hinüber über das Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Darum beweine ich mit Weinen Jaeser, den Weinstock Sibmahs, netze mit meiner Träne dich, Cheschbon und Elealeh, daß auf deine Lese und auf deine Ernte fällt das Kelterlied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'Und Fröhlichkeit und Frohlocken ist weggenommen vom Karmel, und in den Weinbergen jubelt man nicht, man schreit nicht, Wein in den Kufen tritt nicht der Treter. Den Kelterruf lasse ich feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Darum dröhnen meine Eingeweide um Moab, wie die Harfe, und mein Inwendiges über Kir-Chares.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'Und es geschieht, daß man sieht, wie Moab sich abmüht auf der Opferhöhe, und er kommt in sein Heiligtum zu beten und vermag nichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'Dies ist das Wort, das vordem Jehovah über Moab geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Nun aber redet Jehovah und sagt: In drei Jahren, wie des Löhners Jahren, wird Moabs Herrlichkeit gering werden bei aller seiner vielen Menge, und verbleibt nur ein winzig Weniges, ohne Gewalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Weissagung über Damask. Siehe, hinweggenommen ist Damask, so daß es keine Stadt mehr ist, und ist zum Trümmerhaufen verfallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Verlassen sind Aroers Städte, für Herden sind sie, und sie lagern sich und niemand scheucht sie auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'Zu Ende ist die Festung aus Ephraim und das Königreich aus Damask, und Arams Überrest wird wie die Herrlichkeit von Israels Söhnen! spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Und an jenem Tag geschieht, daß Jakobs Herrlichkeit verarmt und seines Fleisches Fett wird mager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'Und sein wird es, wie wenn einer die Ernte sammelt, die stehende Saat, und sein Arm die Ähren erntet, so wird es sein, wie wenn einer im Talgrunde Rephaim Ähren aufliest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Und eine Nachlese verbleibt darin, wie beim Abschlagen der Oliven zwei, drei Beeren an des Gipfels Spitze, vier, fünf im Geäst des Fruchtbaumes, spricht Jehovah, der Gott Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'Am selben Tage schaut aus der Mensch nach Dem, so ihn gemacht, und seine Augen sehen auf den Heiligen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'Und er schaut nicht aus auf die Altäre, die seine Hände gemacht, noch sieht er auf das, was seine Finger gemacht, und auf Ascheren und Sonnensäulen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'An jenem Tage sind die Städte seiner Stärke wie Verlassenes des Forstes und des Gipfels, das sie verlassen vor den Söhnen Israels und sind Wüstenei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Weil du vergessen den Gott deines Heils, und des Felsen deiner Stärke nicht gedacht hast, darum wirst du liebliche Pflanzen anpflanzen, aber du wirst es besäen mit des Fremden Reben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'Am Tage bringst du deine Pflanzen zum Wachsen, und am Morgen blüht deine Saat: Der Erntehaufen am Tage des Erbes und ein verzweifelter Schmerz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Wehe! Ein Getobe vieler Völker, wie das Getobe von Meeren toben sie, und ein Tosen von Volksstämmen, wie gewaltiger Wasser Tosen tosen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Wie Tosen vieler Wasser tosen die Volksstämme; und Er droht ihm und von ferne flieht er und wird gejagt, wie Spreu der Berge vor dem Wind, wie vor dem Sturmwind der Staubwirbel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Zur Zeit des Abends, und siehe, da ist Bestürzung; bevor es Morgen wird, ist keiner da. Das ist das Teil, das unseren Plünderern wird, und das Los unserer Räuber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Wehe dem Lande, von Flügeln beschattet, das jenseits der Flüsse von Kusch ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'Das Botschafter auf das Meer sendet und in Fahrzeugen aus Binsen auf den Angesichten der Wasser: Gehet hin, ihr schnellen Boten zu der langgestreckten und ausgeplünderten Völkerschaft, dem Volke furchtbar, seitdem es ist und fürderhin, der Völkerschaft ausgemessen und zerstampft, dessen Land Flüsse berauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Ihr alle, die ihr wohnt in der Welt und ihr Einwohner der Erde, so man auf den Bergen das Panier erhebt, so sehet, und wenn man in die Posaune stößt, höret!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Denn also spricht zu mir Jehovah: Ich will rasten und blicken in Meiner Stätte, wie die heitere Hitze über dem Licht, wie eine Wolke von Tau in der Ernte Hitze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Denn vor der Ernte, wenn die Blüte zu Ende ist, und die Blume zum reifenden Herling geworden ist, wird man die Ranken abschneiden und die Reben wegtun und abkippen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Sie werden allesamt den Raubvögeln der Berge und dem Vieh des Landes überlassen; aber dem Raubvogel ekelt davor, und alles Vieh des Landes schmäht sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'Zu jener Zeit wird dem Jehovah der Heerscharen eine Opfergabe herbeigebracht, ein langgestrecktes und ausgeplündertes Volk, von einem Volke furchtbar, seitdem es ist und fürderhin, einer ausgemessenen und zerstampften Völkerschaft, dessen Land die Flüsse berauben, an den Ort des Namens Jehovahs, nach dem Berge Zion.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Weissagung über Ägypten. Siehe, Jehovah fährt daher auf leichter Wolke und kommt nach Ägypten, und Ägyptens Götzen erbeben vor Seinem Angesicht, und Ägyptens Herz zerschmilzt in seinem Inneren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'Und Ich will Ägypter wider Ägypter verwirren, daß sie streiten, der Mann gegen seinen Bruder, und ein Mann gegen seinen Genossen, Stadt gegen Stadt, Königreich wider Königreich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'Und ausgeleert soll werden der Geist Ägyptens in seinem Inneren, und seinen Rat will Ich verschlingen. Und sie werden die Götzen befragen und die Bezauberer und die Totenbeschwörer und die Zeichendeuter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'Und Ich überantworte die Ägypter in die Hand eines harten Herrn, und ein starker König soll herrschen über sie, spricht der Herr Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'Und versiegen sollen die Wasser aus dem Meer, und der Fluß soll austrocknen und trocken werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'Und die Flüsse werden verlaufen, arm und ausgetrocknet werden die Ströme Ägyptens; Rohr und Schilf versiechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Und die Auen am Strom und an der Mündung des Stromes, und alle Saat des Stromes verdorrt, zerstiebt und ist nicht mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Und die Fischer ächzen und es trauern alle, so die Angel werfen in den Strom; und die, so das Fischernetz ausbreiten über der Wasser Fläche, verschmachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'Beschämt werden die, so in Seidenflachs arbeiten, und die weben durchbrochenes Zeug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'Zerstoßen sind seine Grundpfeiler; alle, die um den Lohn Teiche für Fische machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Nur Narren sind die Obersten Zoans, die Weisen der Räte Pharaos, ihr Rat ist unvernünftig geworden. Wie sprechet ihr zu Pharao: Ein Sohn der Weisen bin ich, ein Sohn von Königen der Vorzeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Wo sind sie nun, deine Weisen? Und laß doch sie dir ansagen und wissen, was Jehovah der Heerscharen über Ägypten hat beratschlagt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Närrisch sind Zoans Oberste, verführt die Obersten Nophs, sie führen Ägypten, den Eckstein seiner Stämme, irre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Jehovah goß den Geist der Verkehrtheiten in sein Inneres, daß sie Ägypten in all seinem Tun irre führen, wie in seinem Gespei der Trunkene irre geht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'Kein Werk hat Ägypten, das Kopf und Schwanz, Palmast und Binse ausmachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'An jenem Tage wird Ägypten sein wie Weiber, und wird erzittern und schaudern vor dem Schwingen der Hand Jehovahs der Heerscharen, wenn Er sie schwingt über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'Und Jehudahs Boden wird für Ägypten ein Schreckwort. Jeder, der sein gedenkt bei ihm, schaudert vor dem Ratschluß Jehovahs der Heerscharen, den Er gegen es beschlossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'An jenem Tage werden in Ägyptenland fünf Städte sein, so reden mit der Lippe Kanaans und schwören bei Jehovah der Heerscharen. Sonnenstadt heißt man die eine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'An jenem Tag wird ein Altar für Jehovah sein in der Mitte des Landes Ägypten und neben seiner Grenze eine Denksäule für Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'Und wird zum Zeichen und zum Zeugnis für Jehovah der Heerscharen im Land Ägypten. Wenn sie schreien zu Jehovah ob den Unterdrückern, wird Er ihnen einen Retter und Fürsten senden, daß Er sie errette.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'Und kund wird den Ägyptern Jehovah werden, daß an jenem Tage die Ägypter Jehovah kennen und Ihm mit Schlachtopfer und Speiseopfer dienen, und Gelübde Jehovah geloben und entrichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Und Jehovah wird Ägypten schlagen, es schlagen und heilen, und sie werden zu Jehovah zurückkehren, und Er läßt Sich von ihnen erflehen und heilt sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'An jenem Tag wird eine Bahn von Ägypten nach Aschur sein, und Aschur nach Ägypten und Ägypten nach Aschur kommen; und die Ägypter werden Aschur dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'An jenem Tag wird Israel der dritte sein für Ägypten und für Aschur, ein Segen inmitten des Landes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'Das segnen wird Jehovah der Heerscharen und sprechen: Gesegnet sei Mein Volk Ägypten und Aschur, Meiner Hände Werk, und Israel, Mein Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'Im Jahr, da Tharthan nach Aschdod kam, da ihn Sargon, König von Aschur, sandte, und er wider Aschdod stritt und es gewann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'Zur selben Zeit redete Jehovah durch die Hand Jeschajahus, des Sohnes des Amoz, und sprach: Gehe und löse den Sack von deinen Lenden und zieh ab den Schuh von deinem Fuß. Und er tat so und ging nackt und barfuß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Und Jehovah sprach: Wie mein Knecht Jeschajahu nackt und barfuß geht drei Jahre, als Zeichen und Wahrzeichen über Ägypten und über Kusch:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'So wird wegtreiben Aschurs König die Gefangenschaft Ägyptens und Kuschs Verbannte, Junge und Alte, nackt und barfuß mit aufgedecktem Gesäß, die Blöße Ägyptens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'Daß sie entsetzt und beschämt werden ob Kusch, auf den sie vertrauten, und auf Ägypten, ihren Schmuck.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'Und sprechen wird an jenem Tag, der auf dieser Insel wohnt: Siehe, so ist unsere Zuversicht, zu der wir flohen um Beistand, zur Errettung vor Aschurs König! Und wie sind wir entronnen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Weissagung über des Meeres Wüste. Wie Stürme eindringen im Mittag, kommt es von der Wüste, vom furchtbaren Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Ein hartes Gesicht ward mir angesagt: Der Treulose handelt treulos, es verheert der Verheerer. Zieh herauf, Elam, belagere Madai; alles Seufzen laß Ich zu Ende kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Darum sind von Pein erfüllt meine Lenden; Wehen wie Wehen der Gebärerin ergreifen mich. Ich krümme mich, daß ich nichts höre; ich bin bestürzt, daß ich nichts sehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Mein Herz geht irre, Grausen hat geängstigt mich; die Dämmerung, nach der mich verlangt, macht Er zum Erzittern mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Man richte den Tisch zu, man wache auf der Wache, man esse, trinke. Machet euch auf, ihr Obersten, salbet den Schild!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Denn also spricht der Herr zu mir: Gehe, laß den Wächter stehen, der, was er sieht, ansage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'Und er sah einen Streitwagen, ein Paar Reiter, einen Streitwagen mit Esel, einen Streitwagen mit Kamel, und horchend horchte er mit vielem Horchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'Und es ruft der Löwe auf der Warte: Herr, ich stehe am Tag beständig, und alle Nächte stelle ich mich auf meine Hut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'Und siehe, da kam der Streitwagen eines Mannes, ein Paar Reiter. Und er antwortete und sprach: Gefallen, gefallen ist Babel; und alle Schnitzbilder ihrer Götter sind zerbrochen auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'Du, meine Gedroschene und du, Sohn meiner Tenne: was ich von Jehovah der Heerscharen, dem Gott Israels gehört, sage ich euch an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Weissagung über Dumah: Man ruft zu mir aus Seir: Hüter, wie ist es mit der Nacht? Hüter, wie ist es mit der Nacht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Der Hüter spricht: Der Morgen kommt, und es kommt auch die Nacht. Wenn ihr es wollt erfragen, erfraget, kehret zurück, kommet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Weissagung über Arabien: Im Walde in Arabien übernachtet, ihr Wanderzüge der Dedaniter!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Bringet Wasser dem Dürstenden entgegen, die ihr im Land Thema wohnet; mit seinem Brot empfanget die Flüchtigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Denn vor dem Schwerte entfliehen sie, vor dem gezückten Schwert und vor dem gespannten Bogen, vor des Streites Schwere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Denn also spricht der Herr zu mir: Ein Jahr noch, wie des Löhners Jahre, dann ist zu Ende Kedars ganze Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'Und der Überrest der Zahl, des Bogens der Mächtigen, der Söhne Kedars soll weniger werden, denn Jehovah, der Gott Israels, hat geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Weissagung über die Schlucht des Schauens: Was ist dir doch, daß dir alles auf die Dächer hinaufsteigt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'Du Stadt, voll Tobens und Getümmels, du Stadt des Jauchzens! Deine Erschlagenen sind nicht vom Schwert erschlagen und nicht im Streit gestorben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Alle deine Anführer zumal entfliehen, vor dem Bogen sind sie gebunden, alle, die man in dir fand, sind gebunden, von ferne entwichen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Darum sprach ich: Schauet von mir weg, laßt bitterlich mich weinen, dringet nicht in mich, mich zu trösten ob der Verheerung der Tochter meines Volkes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Denn ein Tag ist es des Getümmels und der Zertretung und Verworrenheit, vom Herrn Jehovah der Heerscharen in der Schlucht des Schauens; ob des Untergrabens der Mauer und des Getöses bis zum Berge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'Und Elam trägt den Köcher, im Streitwagen des Menschen, mit Reitern, und Kir entblößt den Schild.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'Und geschehen wird es, daß deiner Talgründe auserwählte sich füllen mit Streitwagen und Reitern, sie stellen sich in Stellung an das Tor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'Und er deckt auf die Decke von Jehudah, und nach den Waffen im Waldhause blickst du an diesem Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'Und ihr seht die Mauerrisse der Stadt Davids, daß ihrer viel sind; und ihr bringt zusammen des unteren Teiches Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'Und ihr zählet die Häuser Jerusalems und reißet die Häuser nieder, die Mauer zu befestigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'Und ihr machet einen Behälter zwischen den beiden Mauern, für das Wasser des alten Teiches. Und ihr blicket nicht nach Dem, Der solches tut; auf Den, Der solches aus der Ferne bildet, seht ihr nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Und an selbem Tage ruft der Herr Jehovah der Heerscharen zum Weinen und zum Klagen, und zur Kahlheit und zur Gürtung mit dem Sacke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'Und siehe, Freude und Fröhlichkeit ist es, man würgt Rinder und schlachtet Kleinvieh, man ißt Fleisch und trinkt Wein: Laßt essen uns und trinken; denn morgen sterben wir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'Und es ist geoffenbart in meinen Ohren von Jehovah der Heerscharen: Fürwahr, gesühnt wird diese Missetat euch nicht, bis daß ihr sterbet! spricht der Herr, Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'So spricht der Herr Jehovah der Heerscharen: Komm, gehe hinein zu diesem Pfleger, zu Schebna, der über das Haus ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Was hast du hier? Und wen hast du hier, daß du dir hier ein Grab aushaust? Er haut hier in der Höhe sich sein Grab aus, gräbt sich eine Wohnung in die Felsenklippe ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Siehe, Jehovah schleudert dich hin mit dem Wurf eines Mannes, und umhüllt dich mit einer Umhüllung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'Zu einem Bündel bündelt Er dich, zu einem Knäuel, in ein Land, weit nach beiden Seiten, dort sollst du sterben und dort seien die Streitwagen deiner Herrlichkeit, du Unehre des Hauses deines Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Von deiner Stelle stürze Ich dich herab, von deinem Stande reiße man dich nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'Und an jenem Tage geschieht es, daß Ich rufe Meinen Knecht Elijakim, Chilkijahus Sohn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'Und ziehe ihm an deinen Leibrock und stärke ihn mit deinem Gurt, und gebe deine Herrschaft in seine Hand, daß er Vater sei dem, der in Jerusalem wohnt und dem Haus Jehudahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'Und gebe auf seine Schulter den Schlüssel von Davids Haus: und er öffnet und niemand schließt, und er schließt und niemand öffnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'Und Ich will ihn einschlagen als Pflock an festem Ort, und er soll zum Thron der Herrlichkeit dem Hause seines Vaters werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Daß sie an ihn hängen alle Herrlichkeit des Hauses seines Vaters, der Söhne und der Enkel, alle Gefäße des Kleinen, von den Gefäßen der Becken und bis zu allen Gefäßen der Psalter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'An jenem Tage, spricht Jehovah der Heerscharen, wird der Pflock, der an festem Ort eingeschlagen, weichen und wird abgehauen und wird niederfallen, und die Last, die an ihm hing, ausgerottet werden; denn Jehovah hat geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Die Weissagung über Zor: Heulet, ihr Schiffe von Tharschisch; denn es ist verheert, kein Haus, kein Eingehen; aus dem Lande der Kittäer wird es ihnen geoffenbart.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Still sind der Insel Bewohner, der Händler Zidons, der über das Meer fuhr, der dich füllte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'Und in vielen Wassern war Schichors Saat; des Stromes Ernte war sein Ertrag. Und es war der Handelsplatz der Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Schäme dich, Zidon, denn es spricht das Meer, des Meeres Festung und sagt: Ich kreiße nicht und gebäre nicht, ich ziehe keine Jünglinge groß und erziehe keine Jungfrauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Wie bei dem Gerücht von Ägypten kreiß-ten sie ob dem Gerücht von Zor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Fahret hinüber nach Tharschisch, heulet, ihr Bewohner der Insel!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Ist das euch die Jauchzende? Aus der Vorzeit Tagen ist ihre Vorzeit. Es werden ihre Füße sie fernhin tragen, als Fremdling sich aufzuhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Wer hat solches beschlossen über Zor, die sich krönte, deren Händler Fürsten, deren Kaufleute die Herrlichen des Landes waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Jehovah der Heerscharen hat es beschlossen, den Stolz jeglicher Zierde zu entweihen, und gering zu machen alle Herrlichen des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Gehe durch dein Land hin, wie der Strom, Tochter von Tharschisch; da ist keine Umgürtung mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Er reckte Seine Hand über das Meer aus, machte zittern Königreiche, Jehovah gebot über Kanaan, seine Festungen zu vernichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'Und Er sprach: Jauchze nicht noch weiter, niedergedrückte Jungfrau, Tochter von Zidon, mache dich auf, ziehe zu den Kittäern hinüber! Auch dort wird keine Ruhe dir werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Siehe der Chaldäer Land, kein Volk war es, Aschur hat es gegründet in Zijim, sie werden ihre Warttürme aufrichten, aufführen ihre Paläste - zum Fall hat Er es gesetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Heulet, ihr Schiffe von Tharschisch, denn eure Festung ist verheert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'Und an selbem Tage wird geschehen, daß Zor siebzig Jahre vergessen wird, gleich eines Königs Tagen. Vom Ende der siebzig Jahre an wird es mit Zor sein wie das Lied der Buhlerin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, 'Nimm die Harfe, zieh in der Stadt umher, vergessene Buhlerin, mache es gut mit Spielen, mehre den Gesang, daß deiner man gedenke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Und am Ende von siebzig Jahren wird geschehen, daß Jehovah Zor heimsucht, und sie zu ihrem Buhlerlohn zurückkommt, und buhlt mit allen Königreichen der Erde auf den Angesichten des Bodens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'Und ihr Erhandeltes und ihr Buhlerlohn wird Jehovah geheiligt werden. Nicht werden sie aufgehäuft, noch zurückgelegt; aber denen, die vor Jehovah wohnen, wird ihr Erhandeltes sein zum Essen bis zur Sättigung und zur dauernden Bedeckung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Siehe, Jehovah leert das Land aus und legt es öde und verkehrt dessen Angesicht, und zerstreut, die darin wohnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'Und wird sein wie das Volk, so der Priester; wie der Knecht, so sein Herr; wie die Dienstmagd, so ihre Gebieterin; wie der Käufer, so der Verkäufer; wie der Leiher, so der Borger; wie der Gläubiger, so der Schuldner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Ausgeleert wird das Land und beraubt; denn Jehovah hat dies Wort geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Es trauert und welkt das Land, die Welt verschmachtet und welket, es verschmachtet die Höhe des Volkes des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Und das Land wird entheiligt unter seinen Bewohnern, weil sie die Gesetze übergehen, die Satzung verändern; den Bund der Ewigkeit zunichte machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Darum frißt der Fluch das Land, und die darin wohnen sind schuldig; darum entbrennen die Bewohner des Landes, daß nur wenige Leute verbleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Es trauert der Most, der Weinstock verschmachtet, alle, die fröhlichen Herzens waren, seufzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Der Pauken Freude feiert, der Jauchzenden Tosen hört auf; es feiert der Harfe Freude.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'Sie trinken nicht Wein bei Gesang, bitter wird stark Getränk den Trinkenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Gebrochen ist die Stadt der Leere, verschlossen jedes Haus, daß man nicht eingeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Klagegeschrei auf den Gassen um den Wein, abgeödet ist alle Fröhlichkeit, alle Freude aus dem Lande verbannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Verwüstung nur ist in der Stadt verblieben. Zu Trümmern ist das Tor geschlagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Denn so wird es sein, inmitten des Landes, in der Mitte der Völker, wie beim Abschlagen der Oliven, wie bei der Nachlese, wenn die Weinlese vollendet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Sie erheben ihre Stimme, sie jubeln, ob der Hoheit Jehovahs lassen sie es ertönen vom Meere her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Darum verherrlicht Jehovah in Urim, auf des Meeres Inseln den Namen Jehovahs, des Gottes Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Vom Saum der Erde her hören wir Psalmen zur Zierde des Gerechten. Und ich spreche: Meine Magerkeit! meine Magerkeit! wehe mir! Die Treulosen handeln treulos! Und mit Treulosigkeit handeln die Treulosen treulos,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Schauer und Fallgrube und Schlinge über dich, der du im Lande wohnst!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'Und es wird geschehen, daß wer da flieht vor des Schauers Stimme, fällt in die Fallgrube, und wer aufsteigt aus der Fallgrube Mitte, der wird in der Schlinge gefangen; denn der Höhe Fenster haben sich geöffnet, und der Erde Grundfesten erbeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Berstend birst die Erde, klaffend klaffet die Erde, wankend wanket die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'Schwankend schwankt die Erde, wie ein Trunkener, und sie schaukelt wie eine Hängematte, und ihre Übertretung ist schwer auf ihr; und sie fällt und steht nicht wieder auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'Und an selbigem Tage sucht Jehovah das Heer der Höhe in der Höhe heim, und die Könige des Bodens auf dem Boden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'Zur Sammlung werden sie versammelt, gebunden zur Grube und verschlossen für den Verschluß, und nach vielen Tagen werden sie heimgesucht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Und der Mond wird erröten und die Sonne sich schämen; denn Jehovah der Heerscharen regiert auf dem Berge Zion und in Jerusalem und vor Seinen Ältesten in Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'Jehovah, mein Gott bist Du! Ich will Dich erhöhen, will bekennen Deinen Namen; denn Wunder tatest Du, Ratschlüsse von ferne her sind Wahrheit, Treue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Du hast zum Haufen die Stadt gesetzt, in Verfall die befestigte Stadt; der Palast der Fremden, daß er keine Stadt sei, soll in Ewigkeit nicht aufgebaut werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Darum verherrlicht Dich ein starkes Volk, Dich fürchtet die Stadt gewaltiger Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Denn zur Festung wurdest Du dem Armen, zur Festung dem Dürftigen in seiner Drangsal, zum Verlaß vor der Überschwemmung, ein Schatten vor der Gluthitze; denn der Hauch der Trotzigen ist wie eine Überschwemmung wider die Mauer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Wie Gluthitze in der Dürre beugst Du das Tosen der Fremden, die Gluthitze durch den Schatten dichter Wolken; Er demütigt den Siegesjubel der Trotzigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'Und allen Völkern wird Jehovah der Heerscharen ein Festmahl auf diesem Berg machen von Fettigkeiten, ein Festmahl von süßen Weinen, von markigem Fett, von geläuterten süßen Weinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'Und verschlingen wird Er auf diesem Berge das Angesicht der Umschleierung, womit alle Völker umschleiert sind, und die Decke, die über alle Völkerschaften gedeckt ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Für immer verschlingt den Tod und wischt aber der Herr Jehovah die Träne von allen Angesichten, und Seines Volkes Schmach nimmt Er weg von der ganzen Erde; denn Jehovah hat es geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'Und sprechen wird man an jenem Tag: Siehe, das ist unser Gott, auf Den wir hofften, daß Er uns rette, das ist Jehovah, auf Den wir hofften. Laßt uns frohlocken und fröhlich sein in Seinem Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Denn es ruht Jehovahs Hand auf diesem Berg, und Moab wird unter ihm gedroschen, wie gedroschen wird Stroh in der Mistjauche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'Und breitet Seine Hände aus inmitten darin, wie sie der Schwimmer ausbreitet, um zu schwimmen. Und Er erniedrigt seinen Stolz mit Seiner Hände Schwingen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'Und die Festung der Bergfeste deiner Mauer beugt Er nieder, erniedrigt sie, bringt sie zur Erde nieder bis in den Staub.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'An jenem Tage wird im Lande Jehudahs dies Lied gesungen: Wir haben eine starke Stadt. Zum Heile stellet Er Mauern und Vormauer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Öffnet die Tore, daß einziehe eine gerechte Völkerschaft, welche die Treue hält;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Dem stetigen Gemüte bewahrst Du Frieden, den Frieden; denn es vertraut auf Dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Vertrauet auf Jehovah fort und fort, denn in Jah Jehovah ist der Fels der Ewigkeiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Denn Er beugt, die in der Höhe wohnen; die emporragende Stadt niedrigt Er; Er niedrigt sie bis zur Erde, bringt sie nieder bis in den Staub.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Der Fuß zerstampft sie, die Füße des Elenden, die Fußtritte des Armen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Gerade ist des Gerechten Pfad; gerade ebnest Du das Geleise des Gerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Auch auf dem Pfade Deiner Gerichte, o Jehovah, haben wir auf Dich gehofft, nach Deinem Namen und nach Deinem Gedächtnis ist der Seele Sehnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Nach Dir sehnt sich meine Seele in der Nacht, auch sucht nach Dir mein Geist in meinem Inneren in der Frühe; denn wie Deine Gerichte auf der Erde, lernen Gerechtigkeit, die in der Welt wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Begnadigt man den Ungerechten, so lernt er nicht Gerechtigkeit. Im Land der Nichtigkeit tut er Verkehrtheit und sieht nicht die Hoheit Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Erhöht ist, Jehovah, Deine Hand, sie erschauen es nicht. Sie werden es erschauen und sich schämen ob dem Eifer des Volkes; ja, Feuer fresse sie, Deine Dränger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Jehovah, Du bestellst Frieden für uns; denn auch alles unser Tun hast Du für uns gewirkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Jehovah, unser Gott, gemustert haben uns Herren außer Dir, in Dir allein gedenken wir Deines Namens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Die Toten leben nicht auf, die Rephaim erstehen nicht, weil Du sie heimsuchtest, sie vernichtetest, und lässest verzehren all ihr Gedächtnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Hinzugetan hast Du, Jehovah, zu der Völkerschaft, hinzugetan zu der Völkerschaft, Du wardst verherrlicht, all des Landes Enden hast Du fern gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Jehovah, in der Bedrängnis suchten sie Dich, gossen ihr Flüstern aus, als Du sie züchtigtest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Wie einer Schwangeren, wenn es nahet, daß sie gebären soll: sie kreißet, schreit in ihren Geburtsnöten, also waren wir vor Deinem Angesichte, o Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Wir empfingen, wir kreißten und gebaren gleich wie Wind; doch kein Heil taten wir dem Land, und die Bewohner des Erdkreises fielen nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Es werden leben Deine Toten, auferstehen mein Leichnam; erwachet und jubelt ihr Bewohner des Staubes; denn ein Tau der Pflanzen ist Dein Tau, aber das Land der Rephaim stürzest Du hinab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Gehe hin, mein Volk, gehe hinein in deine Kammern, schließ deine Türe hinter dir, verstecke dich einen kleinen Augenblick, bis daß der Unwille vorüber ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Denn siehe, Jehovah geht aus von seinem Orte, daß Er die Missetat der Bewohner der Erde heimsuche; und die Erde wird ihr Blut aufdecken und nicht mehr bedecken ihre Erwürgten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'An jenem Tage wird Jehovah mit Seinem harten und großen und gewaltigen Schwert heimsuchen den Leviathan, die längliche Schlange, und Leviathan, die gewundene Schlange, und erwürgen die Walfische im Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'An jedem Tage singet vom Weinberg des Weines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Ihn bewahre Ich, Jehovah, und tränke ihn alle Augenblicke, daß keiner ihn heimsuche, Nacht und Tag bewahre Ich ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Grimm ist nicht bei Mir. Wer gibt Mir Dornstrauch, Dorngestrüpp in den Streit? Ich greife sie an und entzünde sie insgesamt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Oder wenn er erfaßt Meine Stärke, und Frieden mit Mir macht, so mag er Frieden mit Mir machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'Die Kommenden läßt Jakob Wurzeln schlagen und Israel wird blühen und sprossen, und die Angesichte der Welt werden voll vom Ertrag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Schlug Er es denn, wie er seinen Schläger schlug? Ward er erwürgt, wie seine Erwürgten er erwürgte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Nach dem Maße, durch Fortsendung haderst du mit Ihm. Er besann Sich über Seinen harten Wind am Tage des Ostwindes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Darum ist dadurch Jakobs Missetat gesühnt, und dies ist alle Frucht: Wegnahme seiner Sünde, daß er alle Steine des Altares macht wie zerstreute Kalksteine. Nimmer erstehen werden die Ascheren und die Sonnensäulen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Denn die befestigte Stadt ist einsam, der Wohnort verstoßen und verlassen wie die Wüste; das Kalb weidet dort und lagert dort, und frißt ab das Geäste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Ist ihre Ernte vertrocknet, so kommen Weiber, brechen sie ab es anzuzünden; denn kein einsichtsvolles Volk ist es, darum erbarmt Sich nicht, Der es gemacht, und Der es bildete, wird ihm nicht gnädig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'Und geschehen wird an jenem Tage, daß Jehovah die Ähren abschlägt vom Flusse bis zum Bache Ägyptens, und ihr zusammengelesen werdet, der eine zum anderen, ihr Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'Und an jenem Tag geschieht, daß man in die große Posaune stößt, und daß die Verlorenen im Lande Aschur und die Verstoßenen im Lande Ägypten kommen und werden anbeten, Jehovah, auf dem Berge Seiner Heiligkeit in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Wehe der Krone des Hochmuts, den Trunkenen Ephraims, und der abfallenden Blüte, der Zierde seines Schmuckes, der da ist auf dem Haupte der Schlucht der Fetten, die berauscht vom Weine sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Siehe, ein Starker und Gewaltiger kommt für den Herrn, wie Überschwemmung von Hagelwetter, ein Sturm der Zerstörung, wie eine Überschwemmung ungestümer überflutender Gewässer stürzt Er sie mit der Hand zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Mit den Füßen werden sie zerstampft, die Krone des Hochmuts, die Trunkenen Ephraims.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'Und es wird sein mit der abgefallenen Blüte, der Zierde seines Schmuckes auf dem Haupt der Schlucht der Fetten, wie mit der Frühfeige vor dem Sommer, die sieht, wer sie sieht - kaum ist sie in seiner Hand, so hat er sie verschlungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'An jenem Tage wird Jehovah der Heerscharen eine Krone der Zierde sein und ein Kopfbund des Schmuckes dem Überrest Seines Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'Und zum Geist des Gerichts dem, der da sitzt zum Gericht, und zur Macht denen, die den Streit zum Tor zurücktreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'Aber auch diese gehen fehl vom Weine und gehen irre durch stark Getränk, Priester und Prophet gehen fehl durch stark Getränk, sie sind verschlungen vom Wein, wegen starkem Getränk gehen sie irre, sie gehen fehl unter den Sehenden, sie schlottern im Urteil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Denn alle Tische sind voll unflätigen Gespeis, daß kein Ort mehr da ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Wen soll Er unterweisen in der Wissenschaft, wem Einsicht geben für das Gehörte? Den von der Milch Entwöhnten, den von den Brüsten Weggerissenen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Denn es ist: Gebot auf Gebot, Gebot auf Gebot! Regel auf Regel, Regel auf Regel! Hier ein wenig, dort ein wenig!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Dann wird Er mit unverständlicher Lippe und mit einer anderen Zunge zu diesem Volke reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'Er, Der zu ihnen sprach: Dies ist die Ruhe, laßt den Matten ruhen, dies ist die Erquickung! Sie aber wollten nicht hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Und das Wort Jehovahs wird ihnen werden. Gebot auf Gebot, Gebot auf Gebot! Regel auf Regel, Regel auf Regel! Hier ein wenig, da ein wenig; so daß sie hingehen und rückwärts straucheln, zerbrechen, und sich verstricken und sich fangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Darum hört das Wort Jehovahs, ihr Männer des Spottes, die ihr herrscht über dies Volk, so in Jerusalem ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Weil ihr sprechet: Mit dem Tode haben wir einen Bund geschlossen und ein Gesicht mit der Hölle, daß, wenn die Geißel überflutet, sie vorüberfährt und nicht an uns kommt; denn Falschheit haben wir zu unserem Verlaß gesetzt und in Lüge uns verborgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Darum spricht so der Herr, Jehovah: Siehe, Ich legte auf Zion einen Stein zum Grund, einen Stein der Prüfung, einen kostbaren Eckstein, gegründet auf den Grund. Wer daran glaubt, wird sich nicht sputen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'Und das Gericht werde Ich zur Regel setzen, und Gerechtigkeit zum Senkblei, und den Verlaß der Falschheit fegt der Hagel, und die Burg überfluten die Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Und zunichte wird euer Bund mit dem Tod, und euer Gesicht mit der Hölle hat keinen Bestand, die Geißel überflutet, wenn sie herüberkommt, so werdet ihr zerstampft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Sooft als sie vorübergeht, nimmt sie euch, denn Morgen nach Morgen geht sie vorüber, bei Tag und bei Nacht; und nur Aufregung ist es das Gerücht zu verstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Zu kurz wird sein das Lager, sich zu strecken, zu schmal die Decke, sich darein einzuwickeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Denn wie auf dem Berg Perazim wird Jehovah erstehen, Sich erregen wie im Talgrund zu Gibeon, Sein Werk zu tun, Sein fremdes Werk, und zu dienen Seinen Dienst, Seinen ausländischen Dienst!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Und nun spottet nicht, daß nicht verstärkt werden eure Banden, denn Vollendung und Entscheidung über die ganze Erde habe ich gehört von dem Herrn, Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Nehmet zu Ohren und höret auf meine Stimme, horchet auf, und höret meine Rede!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Pflügt wohl der Pflüger den ganzen Tag, zu säen, öffnet und eggt seinen Boden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Nicht wahr? Wenn seine Fläche er geebnet hat, streut er Dill aus und sprengt Kümmel, und legt den gemessenen Weizen hinein und die dazu auserlesene Gerste und den dazu bestimmten Spelt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Und so belehrt Er ihn im Recht, sein Gott unterweist ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Denn man drischt den Dill nicht mit dem Dreschwagen, läßt nicht das Wagenrad über den Kümmel herumgehen; sondern mit dem Stabe wird der Dill geklopft und der Kümmel mit dem Stock.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Wird das Brot zerstoßen? Vielmehr soll man nicht dreschen immerdar und toben mit dem Walzen seines Wagens und der Reiter es nicht zerstoßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Auch dies ist von Jehovah der Heerscharen ausgegangen. Wunderbar macht Er den Rat, groß Seine Weisheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Wehe, Ariel, Ariel, du Stadt, in der David sich hat gelagert. Tut Jahr zu Jahr, laßt Feste umlaufen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'Aber ängstigen will Ich Ariel, da wird Ächzen und Geächze sein, wie Ariel wird sie Mir sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'Und Ich lagere wider dich wie ein Knäuel, und bedränge dich mit Besatzungen, und richte Bollwerke auf wider dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Und du wirst erniedrigt, von der Erde aus redest du, gedämpft steigt deine Rede aus vom Staub, und deine Stimme ist wie die eines Geistesbanners aus der Erde, und auf dem Staube flüstert deine Rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'Und wie feiner Staub wird die Menge deiner Fremden, gleich vorbeigehender Spreu die Menge der Trotzigen, und wird sein plötzlich, unversehens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Heimgesucht wirst du von Jehovah der Heerscharen mit Donner und Erdbeben und großer Stimme, Sturmwind und Gewitter, und mit der Flamme fressenden Feuers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'Und wird sein wie ein Traum, ein Gesicht der Nacht, die Menge aller Völkerschaften, die ausrückten wider Ariel und all seine Heerscharen und seine Feste, und die sie ängstigten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Und wird sein, wie der Hungernde, der träumt, und siehe, er ißt, und er erwacht, und seine Seele ist leer; und wie wenn dem Dürstenden träumt, und siehe, ertrinkt, und er erwacht und siehe, er ist matt und seine Seele verlangt. So wird es mit der Menge aller Völkerschaften sein, die wider den Berg Zion ausrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Zaudert und staunet, stieret und schreit. Sie sind trunken, und nicht vom Wein, sie schwanken, und nicht vom starken Getränk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Denn des tiefen Schlafes Geist hat über euch Jehovah ausgegossen und eure Augen zugedrückt, die Propheten und eure Häupter, die Seher hat Er bedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Und alles Gesichte ist euch wie die Worte eines versiegelten Buches, das man einem gibt, der die Buchstaben kennt und sagt: Lies doch das! Und er sagt: Ich kann nicht, denn es ist versiegelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'Und man gibt das Buch einem, der die Buchstaben nicht kennt und sagt: Lies doch das! Und der sagt: Ich kenne die Buchstaben nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'Und der Herr spricht: Weil dies Volk zu Mir herzutritt mit dem Mund und Mich mit seinen Lippen verherrlicht, aber sein Herz fern von Mir ist; und ihre Furcht vor Mir nur Gebot ist, von Menschen angelernt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'Darum, siehe, will Ich, Jehovah, hinzutun, wunderbar mit diesem Volk umzugehen, wunderbar und wundersam, daß seiner Weisen Weisheit vergeht und seiner Einsichtsvollen Einsicht sich verberge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Wehe denen, die vor Jehovah ihren Rat tief bergen wollen, und ihr Werk ist im Finstern, und sie sprechen: Wer sieht uns, und wer kennt uns?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'Wie seid ihr so verkehrt! Wird der Töpfer dem Ton gleich geachtet, daß das Werk von dem, der es macht, spräche: Er hat mich nicht gemacht! Und das Gebilde von dem Bildner spräche: Er hat keine Einsicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Ist es nicht noch um ein gar Kleines, so wird der Libanon wieder zum Fruchtland, und das Fruchtland wird dem Walde gleich geachtet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'Und an jenem Tag werden die Tauben hören die Worte des Buches, und aus Dunkel und Finsternis der Blinden Augen sehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'Und Fröhlichkeit werden die Elenden wiederum in Jehovah haben, und die Dürftigen der Menschen im Heiligen Israels frohlocken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Denn ein Ende hat der Trotzige, denn zu Ende ist es mit dem Spötter, und ausgerottet sind alle, die auf Unrecht lauerten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'Die, so Menschen sündigen machten mit einem Worte, und den verstricken, so am Tore rügt, und den Gerechten ins Öde abwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Darum spricht so Jehovah zu dem Hause Jakobs, Er, Der Abraham einlöste. Nicht soll Jakob nun sich schämen, und sein Angesicht soll nun nicht erblassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'Denn wenn er sieht seine Kinder, Meiner Hände Werk, werden in ihrer Mitte sie Meinen Namen heiligen, und heiligen Jakobs Heiligen, und vor dem Gotte Israels wird ihnen grauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'Und die, so irren im Geiste, werden kennen Einsicht, und die Murrenden werden Lehre lernen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Wehe den störrischen Söhnen, spricht Jehovah, die zu Rate gehen ohne Mich, sich Gußbilder gießen und nicht aus Meinem Geist, so daß sie Sünde zu Sünde hinzutun;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'Die hingehen, um hinabzusteigen nach Ägypten, und Meinen Mund nicht erfragen, sich mit Pharaos Stärke zu stärken und sich zu verlassen auf Ägyptens Schatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Aber Pharaos Stärke wird euch zur Scham und der Verlaß auf Ägyptens Schatten zur Schande euch werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Denn seine Obersten sind in Zoan gewesen, und seine Boten haben Chanes erreicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'Jeder wird beschämt über das Volk, sie nützen ihnen nichts; nicht zum Beistand, noch zum Nutzen, sondern zur Scham und auch zur Schmach sind sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Weissagung über die Tiere des Mittags: Im Land der Drangsal und der Angst sind der alte Löwe und der Löwe, aus ihnen die Natter und die fliegende Feuerschlange; sie tragen auf der Schulter der Eselsfüllen ihr Vermögen, und auf dem Höcker der Kamele ihre Schätze zu einem Volk, das ihnen nichts nützt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Und Ägypten - nichtig, und leer ist, was die beistehen! Darum nenne ich es: Rahab; sie feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Komme nun, schreibe es auf eine Tafel vor ihnen; verzeichne es in einem Buch, daß es für einen späteren Tag bleibe, immerfort und in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Denn ein Volk der Widerspenstigkeit sind sie, Söhne der Täuschung, Söhne, die das Gesetz Jehovahs nicht hören wollen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'Die zu den Sehern sagen: Sehet nicht! und zu denen, so ein Gesicht haben: Erschauet für uns nicht das Richtige! Redet zu uns Schmeicheleien, erschauet uns Blendwerke!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Weicht ab vom Weg, wendet euch ab von dem Pfad! Schaffet weg von unserem Angesicht den Heiligen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Darum spricht also der Heilige Israels: Weil ihr solches Wort verschmäht, und auf Plackerei und Verdrehung vertrauet und darauf euch stützet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'Darum soll diese Missetat euch werden zum fallenden Durchbruch, in hochragender Mauer, die sich vorbiegt und plötzlich, unversehens kommt ihr Bruch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'Und zerbricht, wie ein Geschirr des Töpfers zerbricht, das man zerstößt und nicht schont, und unter dessen Bruchstücken kein Scherben sich findet, Feuer vom Herd zu nehmen, oder Wasser zu schöpfen aus der Pfütze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Denn so spricht der Herr Jehovah, der Heilige Israels: Durch Rückkehr und Ruhe kann euch Heil werden. Durch Stillesein und Vertrauen wird euch Macht. Ihr aber habt es nicht gewollt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'Und sagtet: Nein, zu Rosse wollen wir fliehen, darum sollt ihr fliehen; und auf dem Schnellen wollen wir reiten, darum sind schnell, die euch verfolgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Vor eines einzigen Drohen werden euer eintausend, vor dem Drohen von fünfen werdet ihr fliehen, bis nicht mehr von euch verbleibt, als ein Mastbaum auf des Berges Spitze und als ein Panier auf dem Hügel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'Und darum harret Jehovah, daß Er euch gnädig sei, und darum wird Er Sich erhöhen, Sich euer zu erbarmen, denn Jehovah ist ein Gott des Gerichts, selig sind alle, die auf Ihn harren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Denn du Volk in Zion, das da wohnt in Jerusalem: Du sollst nicht weinen, gnädig ist Er dir, gnädig auf die Stimme deines Schreiens. Wie Er es hört, so antwortet Er dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Und geben wird euch der Herr der Drangsal Brot, und das Wasser der Unterdrückung, aber die dich unterweisen, müssen nimmermehr davonfliehen, und deine Augen werden sehen die, so dich unterweisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'Und deine Ohren hören hinter dir das Wort sprechen: Dies ist der Weg! Gehet darin, ob rechts ihr oder links euch wenden wollet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'Und unrein wird euch sein der Überzug der Schnitzbilder deines Silbers und die Bekleidung der Gußbilder deines Goldes. Als befleckt wirfst du sie hin und heißest es Unflat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Und Er gibt Regen deiner Saat, womit du den Berg eingesät, und Brot von dem Ertrag des Bodens, und es wird sein fett und ölig; deine Viehherde wird Er an jenem Tag auf weiter Flur weiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'Und die Ochsen und die Eselsfüllen, die den Boden bauen, fressen gemengtes Futter, das einer worfelt mit der Wanne und der Wurfschaufel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'Und auf jeglichem hohen Berge und jeglichem erhabenen Hügel sind Bäche, Wasserströme am Tag des großen Würgens, da die Türme fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'Und wird das Licht des Mondes wie das Licht der Sonne sein, und das Licht der Sonne siebenfach, wie das Licht von sieben Tagen am Tage, da Jehovah Seines Volkes Bruch verbinden und Seines Schlages Wunden heilen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Siehe, Jehovahs Name kommt von fern, es brennt Sein Zorn und lastet schwer, voll Unwillens sind Seine Lippen und Seine Zunge ist wie fressend Feuer,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'Und Sein Geist wie ein überflutender Bach, der bis zum Halse zweiteilt, zu sieben die Völkerschaften in dem Siebe der Eitelkeit, und ein Gebiß, das in die Irre führt, ist an den Kinnbacken der Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Der Gesang wird sein bei euch, wie in der Nacht, da ihr ein Fest heiligt. Und Fröhlichkeit wird in eurem Herzen sein, wie da man unter Flöten wallt, zu kommen auf den Berg Jehovahs, zum Felsen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'Und Seiner Stimme Majestät läßt Jehovah hören, und Ruhe läßt sehen Sein Arm: mit Grollen des Zornes und der Flamme fressenden Feuers, und Zerstreuung und Überschwemmung und Steine des Hagels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Denn vor Jehovahs Stimme entsetzt sich Aschur, Er schlägt ihn mit der Rute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'Und wird sein jeglicher Übergang des Stabs auf dem Grunde, auf dem Jehovah es wird ruhen lassen, unter Pauken und Harfen. Und im Streite des Schwingens streitet Er wider sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Denn seit gestern ist das Thophet zugerichtet, auch für den König ist es zubereitet, tief und weit. Sein Scheiterhaufen hat viel Feuer und Holz. Der Odem Jehovahs, wie ein Bach von Schwefel macht ihn brennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Wehe denen, die um Beistand hinab nach Ägypten ziehen, und sich auf Rosse stützen und auf Streitwagen vertrauen, daß deren viel sind, und auf Reiter, daß sehr mächtig sie sind, und nicht schauen auf den Heiligen Israels, und nicht fragen nach Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Aber Er ist auch weise und bringt Böses, und tut nicht weg Seine Worte und steht auf wider das Haus der Bösen und wider den Beistand derer, die Unrecht wirken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Und Ägypten ist ein Mensch und nicht Gott, und ihre Rosse Fleisch und nicht Geist. Und Jehovah reckt Seine Hand aus, und es strauchelt der Beistand, und der, dem er beisteht, fällt, und es ist aus mit ihnen allen zumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Denn also sprach zu mir Jehovah: Gleich wie der Löwe knurrt, und der junge Löwe ob dem Zerfleischten, wenn ihm der Hirten Fülle begegnet, sich nicht entsetzt ob ihrer Stimme und von ihrem Toben nicht gedrückt wird; so steigt herab Jehovah der Heerscharen, zu kriegen auf dem Berge Zion und auf seinem Hügel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Wie Vögel daherfliegen, so schirmt Jehovah der Heerscharen über Jerusalem, Er schirmt und errettet, überspringt und läßt entrinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Kehret zurück zu Dem, von Dem so tief ihr seid abgewichen, Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Denn an selbigem Tage werden sie verschmähen, jeder Mann die Götzen seines Silbers und die Götzen seines Goldes, die eure Hände euch gemacht als Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Und fallen wird Aschur durch das Schwert nicht eines Mannes, und das Schwert nicht eines Menschen wird ihn fressen, und er wird für sich fliehen vor dem Schwert, und zinsbar werden seine Jünglinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'Und seine Felsenklippe wird vergehen vor Bangen, und vor dem Panier sich entsetzen seine Fürsten, spricht Jehovah, Der einen Feuerherd hat auf Zion und einen Ofen in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Siehe, in Gerechtigkeit wird regieren ein König, und die Fürsten - sie werden schalten nach dem Recht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'Und der Mann ist wie ein Versteck vor dem Winde und eine Burg in der Überschwemmung, wie Bäche der Wasser in der Dürre, wie der Schatten einer schweren Felsenklippe in dem matten Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'Verklebt werden nicht sein die Augen der Sehenden, und horchen werden die Ohren der Hörenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'Und es wird einsichtsvoll zur Kenntnis das Herz der Eiligen, und die Zunge der Stammelnden ist eilig, Deutliches zu reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'Den Toren nennt man dann nicht mehr einen Edlen, noch heißt der Habsüchtige freigebig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Denn Torheit wird der Tor reden und sein Herz wird Unrecht tun, Heuchelei tun und Irriges reden wider Jehovah, will leeren des Hungernden Seele und dem Dürstenden das Getränk lassen mangeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Und der Habsüchtige - seine Werkzeuge sind böse, er berät Schandtaten, die Elenden zu verstören mit der lüge Reden, wenn auch der Dürftige redet nach Recht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Der Edle aber berät Edles und besteht bei Edlem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Ihr sorglosen Weiber, stehet auf, höret meine Stimme; ihr sicheren Töchter, nehmet zu Ohren meine Rede!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'Jahr auf Jahr sollt ihr zittern, ihr Sicheren! Denn zu Ende ist es mit der Weinlese, ein Einsammeln kommt nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Erbebt, ihr Sorglosen, zittert, ihr Sicheren! Ziehet euch aus und entblößt euch, und umgürtet eure Hüften!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Schlagt auf die Brüste, klagend um die Felder des Begehrens, um den fruchtbaren Weinstock!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Auf meines Volkes Boden schießt der Dorn, der Dornstrauch auf, ja in allen Häusern der Freude in der jauchzenden Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Denn dahingegeben ist der Palast, verlassen die Menge der Stadt, Anhöhe und Wartturm sind Höhlen bis in Ewigkeit, die Freude der Waldesel und Weideplatz für die Herden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'Bis daß sich über uns ergießt der Geist aus der Höhe; und es wird die Wüste zum Fruchtgefilde und das Fruchtgefilde wird als Wald geachtet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'Und in der Wüste wohnt das Recht, und die Gerechtigkeit hat ihren Wohnsitz in dem Fruchtgefilde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'Und das Werk der Gerechtigkeit wird Friede sein, und der Gerechtigkeit Arbeit Rast und Sicherheit ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'Und mein Volk wohnt in Wohnorten des Friedens und in sicheren Wohnungen und in sorglosen Ruhestätten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'Und es wird hageln, bis der Wald hinabsteigt, und in der Niederung die Stadt wird erniedrigt sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Selig ihr, die ihr an allen Wassern sät; die ihr entsendet den Fuß des Ochsen und des Esels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Wehe dir, Verwüster. Und der du nicht bist verwüstet worden, und dir, Treuloser, den sie nicht treulos behandelt haben. Wenn du zu Ende mit Verwüsten bist, wirst du verwüstet werden. Wenn du deine Treulosigkeit zu Ende hast gebracht, wird man auch dich treulos behandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'Jehovah, sei uns gnädig! Auf Dich hoffen wir. Sei ihr Arm an dem Morgen, und unser Heil in der Zeit der Drangsal!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Vor der Stimme des Getümmels entfliehen die Völker, vor deiner Erhöhung zerstreuen sich die Völkerschaften;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'Und weggerafft wird eure Beute, wie Grillen aufraffen; wie Heuschrecken dahinrennen, wird man in ihr dahinrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Erhaben ist Jehovah, denn Er wohnt in der Höhe, Er füllt Zion mit Gericht und Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'Und die Wahrheit deiner Zeiten wird die Festigkeit sein des Heils, der Weisheit und der Kenntnis, und die Furcht Jehovahs wird sein Schatz sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Siehe, ihre Helden schreien draußen, die Friedensengel weinen bitterlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Wüste sind die Landstraßen, es feiert, der auf dem Pfade vorübergeht; den Bund macht er zunichte, verschmäht die Städte, achtet nicht des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Das Land trauert, verschmachtet; es errötet der Libanon, er versiecht. Der Scharon ist wie die Einöde, und der Baschan und der Karmel entblättern sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Nun stehe Ich auf, spricht Jehovah, nun erhöhe Ich Mich, nun erhebe Ich Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Mit Heu gehet ihr schwanger und gebäret Stoppeln. Und euer Geist, ein Feuer frißt euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'Und die Völker werden zu Kalk verbrannt, sind abgehauene Dornen, die zum Feuer angezündet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Höret, ihr Fernen, was Ich habe getan; und wisset, ihr Nahen, Meine Macht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'In Zion schauert es den Sündern, Beben ergreift die Heuchler. Wer weilt uns bei dem fressenden Feuer? Wer weilt uns bei dem ewigen Glutherd?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Wer in Gerechtigkeit wandelt und redet Geradheit, verschmäht, durch Plackereien zu gewinnen, schüttelt seine Hände, daß sie nicht Geschenke erhalten, sein Ohr verstopft, daß er von Blut nicht hört, seine Augen zudrückt, daß sie Böses nicht sehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'Der wird auf den Höhen wohnen, und Festen der Felsenklippe sind seine Burgfeste, sein Brot wird ihm gegeben, sein Wasser ist ihm gewiß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Den König in Seiner Schönheit werden deine Augen erschauen, sie werden sehen das Land der Fernen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Dein Herz wird sinnen über den Schrekken. Wo ist er, der da zählt? Wo, der da darwägt? Wo, der die Türme zählt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Das bestärkte Volk siehst du nicht, das Volk von tiefen Lippen, daß man es nicht hören kann, von stammelnder Zunge, daß man es nicht versteht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Erschaue Zion, die Stadt unserer Festversammlung, deine Augen sehen Jerusalem, den sorglosen Wohnort, das Zelt, das nicht fortwandert, dessen Pflöcke nimmermehr aufgezogen werden und von dessen Seile keines abgerissen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'Denn der herrliche Jehovah ist daselbst bei uns, ein Ort der Flüsse, der Ströme, weit von Räumen, nicht geht darin ein Fahrzeug mit Rudern und ein stattlich Schiff fährt nicht da durch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Denn Jehovah ist unser Richter, Jehovah unser Gesetzgeber, Jehovah unser König, Er rettet uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Losgelassen sind deine Seile, nicht stärken sie ihres Mastes Gestell, sie breiten nicht aus das Segel. Dann teilt man der vielen Beute Plunder; die Hinkenden rauben den Raub.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'Und keiner, der da wohnt wird sagen: Ich bin krank. Dem Volk, das drinnen wohnt, ist die Missetat verziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Ihr Völkerschaften, nahet euch zu hören, und horchet, ihr Volksstämme. Die Erde höre und was sie füllt, die Welt und all ihre Spröß-linge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Denn über alle Völkerschaften ist entrüstet Jehovah und ergrimmt wider all ihr Heer, verbannt hat Er sie, zum Schlachten sie gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'Und hingeworfen werden ihre Erschlagenen, und von ihren Leichen steigt ihr Gestank auf, und Berge zerfließen von ihrem Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'Und das ganze Himmelsheer schwindet hin, und die Himmel rollen sich zusammen wie ein Buch, und all ihr Heer fällt ab, gleich wie das Blatt vom Weinstock abfällt, und das, so vom Feigenbaum abfällt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Denn es schwelgt Mein Schwert im Himmel; siehe, auf Edom fährt es herab und auf das Volk Meines Bannes zum Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Das Schwert Jehovahs ist voll Blut, fett gemacht von dem Fett, vom Blut der Lämmer und der Böcke, vom Fett der Nieren der Widder; denn ein Opfer hat Jehovah zu Bozrah, und ein großes Schlachten in dem Lande Edom.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Und niederstürzen werden die Einhörner mit ihnen, und die Farren samt den Gewaltigen, und schwelgen wird ihr Land im Blut und ihr Staub vom Fett fett gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Denn für Jehovah ist es ein Tag der Rache, das Jahr der Vergeltung, daß Er für Zion hadert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'Und seine Bäche verwandeln sich in Pech, und Schwefel wird ihr Staub und zu brennendem Pech ihr Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Bei Nacht und bei Tag erlischt es nicht, ewiglich steigt Rauch davon auf, von Geschlecht zu Geschlecht ist es verödet, nimmermehr und nimmermehr geht man da hindurch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Und Pelikan und Entenadler besitzen es erblich, Eulen und Raben wohnen darin. Die Meßschnur der Verwüstung spannt Er aus über sie, die Senksteine der Verödung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Und seine Edelleute, keine sind da, daß sie das Königtum ausriefen; und alle ihre Obersten sind zu Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'Und Dornen steigen auf in ihren Palästen, und Disteln und Dornsträucher in ihren Festungen. Ein Wohnort wird es der Drachen, ein Gehöft für Käuzlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'Dort treffen sich die Zijim und die Ijim, der Waldteufel begegnet dem Genossen, auch rastet dort die Nachteule und findet für sich eine Ruhestätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Dort nistet auch die Pfeilschlange, und legt, heckt aus und häuft an unter ihrem Schatten ihre Jungen; ja, dort kommen zusammen die Weihen, einer zum anderen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Suchet nach im Buch Jehovahs und leset. Nicht eines wird davon fehlen. Das eine wird das andere nicht vermissen; denn mit dem Munde hat Er es geboten und Sein Geist brachte sie zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'Und Er ließ ihnen fallen das Los und Seine Hand teilt es ihnen nach der Meßschnur zu. Sie nehmen es in ewigen Besitz; auf Geschlecht und Geschlecht wohnen sie darinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Freuen wird sich Wüste und Dürre, und frohlocken die Einöde, und blühen wie die Rose.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Blühend erblüht sie und frohlockt; nur Frohlocken und Jubel ist da. Die Herrlichkeit des Libanon wird ihr gegeben, Karmels und Scharons Ehre. Sie sehen die Herrlichkeit Jehovahs, die Ehre unseres Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Stärket die schlaffen Hände und kräftigt die strauchelnden Knie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Sprecht zu den übereiligen Herzen: Seid stark, fürchtet euch nicht! Siehe, euer Gott kommt zur Rache, zur Vergeltung Gottes; Er kommt und rettet euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Dann werden aufgetan der Blinden Augen und die Ohren der Tauben geöffnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Dann hüpft wie ein Hirsch der Lahme und des Stummen Zunge jubelt, denn Wasser brechen in der Wüste hervor und Bäche in der Einöde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Zum Teiche wird die Sandwüste und das durstige Land zum Quellengrunde der Wasser. In der Drachen Wohnort, wo er lagert, ist Gras statt Rohr und Binsen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'Und eine Bahn wird dort sein und ein Weg, und man nennt ihn den Weg der Heiligkeit. Kein Unreiner geht darüber, sondern er ist für sie. Wer auf dem Wege geht, auch Narren, gehen nicht irre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Dort ist kein Löwe und kein reißend Tier geht darin hinauf; es läßt sich dort nicht finden. Aber die Erlösten gehen ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'Und die Losgekauften Jehovahs kehren zurück und kommen mit Jubeln nach Zion, und ewige Fröhlichkeit auf ihrem Haupt; Freude und Fröhlichkeit ergreift sie, und Gram flieht und Seufzer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'Und es geschah im vierzehnten Jahr des Königs Chiskijahu, daß Sancherib, König von Aschur, wider alle festen Städte Jehudahs heraufzog und sie einnahm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Und der König von Aschur sandte Rabschakeh mit schwerer Streitmacht von Lachisch gen Jerusalem an den König Chiskijahu, und er stand an dem Wassergraben des oberen Teiches auf der Landstraße beim Feld des Walkers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Und es ging zu ihm hinaus Eljakim, der Sohn Chilkijahus, der über das Haus war, und Schebna, der Schreiber, und Joach, Asaphs Sohn, der Kanzler.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Und Rabschakeh sprach zu ihnen: Saget doch dem Chiskijahu: So spricht der große König, der König von Aschur: Was für ein Vertrauen ist das, womit du vertraust?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Ich sage, nur ein Wort der Lippen ist es: Rat und Macht habe ich zum Streit. Nun, auf wen vertraust du, daß du dich empörtest wider mich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Siehe, du vertraust auf die Stütze dieses zerquetschten Rohres, auf Ägypten. So ein Mann sich darauf lehnt, dem fährt es in die Hand hinein und durchsticht sie. So ist Pharao, Ägyptens König, für alle, die auf ihn vertrauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Und wenn du zu mir sagst: Wir vertrauen auf Jehovah, unseren Gott; ist es denn nicht Der, Dessen Opferhöhen und Altäre Chiskijahu hat weggetan und zu Jehudah und Jerusalem gesprochen hat: Vor diesem Altar da sollt ihr anbeten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'Und nun, verbürge dich doch meinem Herrn, dem König von Aschur, und ich will dir zweitausend Rosse geben, wenn du vermagst für dich zu geben, die darauf reiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Und wie wolltest du das Angesicht eines der Statthalter, der geringsten Knechte meines Herrn zurückwenden; und du vertraust auf Ägypten, auf Streitwagen und auf Reiter?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Und nun bin ich ohne Jehovah heraufgezogen wider dieses Land, es zu verderben? Jehovah hat zu mir gesprochen: Ziehe hinauf wider dieses Land und verdirb es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Und Eljakim und Schebna und Joach sprachen zu Rabschakeh: Rede doch zu deinen Knechten auf aramäisch; denn wir verstehen es. Und rede nicht auf jüdisch mit uns vor den Ohren des Volkes auf der Mauer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Rabschakeh aber sprach: Hat mein Herr mich zu deinem Herrn und zu dir gesandt, diese Worte zu reden, und nicht zu den Männern, die auf der Mauer sitzen, um ihren eigenen Kot zu essen und mit euch ihren eigenen Harn zu trinken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Und Rabschakeh stand und rief mit großer Stimme auf jüdisch und sprach: Höret die Worte des großen Königs, des Königs von Aschur.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'So spricht der König: Laßt euch von Chiskijahu nicht verführen; denn er vermag euch nicht zu erretten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'Und laßt euch nicht von Chiskijahu auf Jehovah vertrösten, indem er spricht: Jehovah wird gewißlich uns erretten, daß diese Stadt nicht in die Hand des Königs von Aschur gegeben werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Hört nicht auf Chiskijahu; denn so spricht der König von Aschur: Macht bei mir einen Segen, und kommt heraus zu mir. Und esset, jeder Mann von seinem Weinstock und jeder Mann von seinem Feigenbaum, und jeder Mann trinke vom Wasser seiner Grube.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'Bis daß ich komme und euch nehme in ein Land, wie euer Land, ein Land des Korns und Mostes, ein Land des Brotes und der Weinberge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Laßt Chiskijahu euch nicht antreiben, wenn er sagt: Jehovah wird uns erretten. Hat von den Göttern der Völkerschaften ein Mann sein Land von der Hand des Königs von Aschur errettet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Wo waren denn die Götter von Chamath und von Arpad, wo die Götter von Sepharvajim? Haben sie denn Schomron aus meiner Hand errettet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Wer von allen Göttern dieser Länder hat sein Land aus meiner Hand errettet, daß Jehovah Jerusalem aus meiner Hand erretten sollte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'Und sie schwiegen stille und antworteten ihm kein Wort; denn des Königs Gebot war das, indem er sprach: Antwortet ihm nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Und es kamen Eljakim, Chilkijahus Sohn, der über das Haus war, und Schebna, der Schreiber, und Joach, Asaphs Sohn, der Kanzler, zu Chiskijahu mit zerrissenen Kleidern und sagten ihm die Worte Rabschakehs an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'Und es geschah, da der König Chiskijahu es hörte, da zerriß er seine Kleider und bedeckte sich mit dem Sack und ging hinein in das Haus Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'Und sandte Eljakim, der über das Haus war, und Schebna, den Schreiber, und die Ältesten der Priester mit Säcken bedeckt, an Jeschajahu, des Amoz Sohn, den Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'Und sie sagten zu ihm: So spricht Chiskijahu: Ein Tag der Drangsal, der Rüge und der Lästerung ist dieser Tag; denn die Söhne sind gekommen bis zum Durchbruch, und keine Kraft ist zum Gebären da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Vielleicht hört Jehovah, dein Gott, die Worte Rabschakehs, den der König von Aschur, sein Herr, gesendet hat, zu schmähen den lebendigen Gott und straft ihn für die Worte, die Jehovah, dein Gott, gehört hat, und du, erhebe ein Gebet für den Überrest, der sich findet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Und die Knechte des Königs Chiskijahu kamen zu Jeschajahu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'Und Jeschajahu sprach zu ihnen: So sollt ihr sprechen zu eurem Herrn: Also spricht Jehovah: Fürchte dich nicht vor den Worten, die du gehört, mit denen Mich die Jungen des Königs von Aschur verhöhnt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Siehe, Ich will einen Geist in ihn geben, daß er ein Gerücht hört und in sein Land zurückkehrt, und Ich lasse ihn durch das Schwert in seinem Lande fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'Und Rabschakeh kehrte zurück und fand den König von Aschur im Streit wider Libnah; denn er hatte gehört, daß er von Lachisch aufgebrochen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'Und er hörte über Tirhakah, den König von Kusch sprechen: Er ist ausgezogen, mit dir zu streiten. Und er hörte es und sandte Boten an Chiskijahu, die sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'So sprechet zu Chiskijahu, dem König von Judah und sagt: Laß dich nicht verführen von deinem Gotte, auf Den du vertraust, daß du sprächest: Jerusalem wird nicht in die Hand des Königs von Aschur gegeben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Siehe, du hast gehört, was die Könige von Aschur allen den Ländern getan, daß sie dieselben verbannten, und du willst errettet werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'Haben die Götter der Völkerschaften diejenigen errettet, die meine Väter verdorben haben: Gosan und Charan und Rezeph und die Söhne Edens, zu Thelassar?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Wo ist der König von Chamath und der König von Arpad und der König der Stadt Sepharvajim, Hena und Ivah?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'Und Chiskijahu nahm die Briefe aus der Hand der Boten und las sie und ging hinauf in das Haus Jehovahs und Chiskijahu breitete sie aus vor dem Angesichte Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'Und Chiskijahu betete zu Jehovah und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Jehovah der Heerscharen, der Gott Israels, Der Du auf den Cheruben sitzest. Du allein bist der Gott über alle Königreiche der Erde, Du hast die Himmel und die Erde gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Neige, Jehovah, Dein Ohr und höre. Tue auf, Jehovah, Dein Auge und siehe, und höre alle die Worte Sancheribs, die er gesandt hat, den lebendigen Gott zu schmähen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Wahr ist es, Jehovah, Aschurs Könige haben alle Länder und ihr Land verödet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'Und ihre Götter in das Feuer gegeben; denn sie sind keine Götter, sondern das Werk der Hände des Menschen, Holz und Stein; und die haben sie zerstört,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Und nun, Jehovah, unser Gott, rette uns aus seiner Hand, daß alle Reiche der Erde wissen, daß Du allein, Jehovah, bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Und Jeschajahu, Amoz Sohn, sandte an Chiskijahu und sprach: So spricht Jehovah, der Gott Israels: Was du zu Mir wegen Sancherib, des Königs von Aschur, gebetet hast:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'Ist dies das Wort, das Jehovah über ihn geredet hat: Die Jungfrau, die Tochter Zions, verachtet dich, verlacht dich, es schüttelt hinter dir mit dem Haupt die Tochter Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Wen hast du geschmäht und verhöhnt, und gegen wen deine Stimme erhöht und zur Höhe erhoben deine Augen? Gegen den Heiligen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Durch deiner Knechte Hand hast du den Herrn geschmäht und gesprochen: Mit meiner Streitwagen Menge stieg ich auf der Berge Höhen, die Seiten des Libanon und ich haue um den Wuchs seiner Zedern und die auserwählten seiner Tannen, und komme in die Höhe an sein Ende, in den Wald seines Karmels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Ich grabe hinab und trinke Wasser und trockne mit der Sohle meiner Füße alle Ströme Mazors.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'Hast du nicht gehört, daß aus der Ferne Ich es getan, seit der Vorzeit Tagen, und habe es gebildet? Nun lasse Ich es kommen, und wird sein, daß Ich zu Steinhaufen zertrümmere die Bollwerke, die befestigten Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Und ihre Bewohner sind kurz von Hand, entsetzt und beschämt; sie werden Kraut des Feldes und Grünes vom jungen Kraut, Gras der Dächer und Brandkorn, ehe es aufschießt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'Aber Ich weiß dein Sitzen und deinen Ausgang und deinen Eingang und deinen Aufruhr wider Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Weil dein Aufruhr wider Mich und deine Sorglosigkeit zu Meinen Ohren aufgestiegen ist, so lege Ich Meinen Haken in deine Nase und Meinen Zaum an deine Lippen, und bringe dich auf dem Weg zurück, den du gekommen bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'Und das soll dir das Zeichen sein: Esset dieses Jahr solches, das von selbst gewachsen und das zweite Jahr solches, das aus diesem nachgewachsen; und im dritten Jahre säet und erntet und pflanzet Weinberge, und esset ihre Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'Und wiederum werden die Entkommenen des Hauses Jehudah, die verbleiben, Wurzeln ansetzen nach unten und Frucht bringen nach oben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Denn von Jerusalem wird ausgehen der Überrest, und die Entkommenen vom Berge Zion. Der Eifer Jehovahs der Heerscharen wird solches tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Darum, so spricht Jehovah über Aschurs König: Nicht soll er kommen an diese Stadt und soll keinen Pfeil dahin abschießen, und nicht vor sie bringen den Schild, noch einen Wall aufschütten wider sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Auf dem Wege, den er gekommen, kehre er zurück, aber zu dieser Stadt soll er nicht kommen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Und schirmen will Ich diese Stadt, sie zu retten um Meinetwillen und um Davids, Meines Knechtes, willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'Und es ging der Engel Jehovahs aus und schlug im Lager Aschurs hundertfünfundachtzigtausend. Und da sie des Morgens früh aufstanden, und siehe, da waren sie alle tote Leichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Und Sancherib, Aschurs König, brach auf und ging hin und kehrte zurück und wohnte in Niniveh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'Und es geschah, als er im Hause Misrochs, seines Gottes, anbetete, daß seine Söhne Adrammelech und Scharezer ihn mit dem Schwert schlugen. Und sie entrannen nach dem Lande Ararat, und sein Sohn Esarchaddon ward König an seiner Stelle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'In selbigen Tagen erkrankte Chiskijahu auf den Tod. Und Jeschajahu, der Sohn des Amoz, der Prophet, kam zu ihm und sprach zu ihm: So spricht Jehovah: Gebiete deinem Hause, denn du wirst sterben und nicht leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Und Chiskijahu wandte sein Angesicht zur Wand und betete zu Jehovah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'Und sprach: Ach, Jehovah, gedenke doch, daß ich in Wahrheit und mit ganzem Herzen vor Deinem Angesicht gewandelt und getan habe, was gut in Deinen Augen ist. Und Chiskijahu weinte sehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Und es geschah das Wort Jehovahs zu Jeschajahu, und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Gehe hin und sprich zu Chiskijahu: So spricht Jehovah, der Gott Davids, deines Vaters: Ich habe dein Gebet gehört, gesehen deine Träne. Siehe, Ich werde fünfzehn Jahre zu deinen Tagen dazutun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'Und von der Hand von Aschurs König dich und diese Stadt erretten und schirmen diese Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'Und dies sei von Jehovah dir das Zeichen, daß Jehovah dieses Wort, das Er geredet hat, tun wird:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'Siehe, Ich will den Schatten an den Stufen, welcher ist herabgegangen an des Achas Stufen durch die Sonne, zehn Stufen hinter sich zurückkehren lassen, und die Sonne kehrte zehn Stufen zurück, an den Stufen, die sie hinabgegangen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Die Schrift des Chiskijahu, König von Judah, da er erkrankt und von der Krankheit wieder auflebte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Ich sprach: Durch Verstörung meiner Tage gehe ich zu den Toren des Grabes, ich ward gemustert, der Rest meiner Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Ich sprach: Nicht sehe ich mehr Jah, Jah im Lande der Lebendigen, nicht erblicke ich hinfort den Menschen bei den Bewohnern der Vergänglichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Mein Wohnplatz wird abgebrochen und von mir weggeführt wie das Zelt des Hirten. Ich ziehe wie der Weber mein Leben ein, Er schneidet es ab vom Trumm. Vom Tage bis zur Nacht machst Du mit mir ein Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Ich stellte es mir vor bis zum Morgen: Wie ein Löwe, so zerbricht Er meine Gebeine. Vom Tage bis zur Nacht machst Du mit mir ein Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Wie die Schwalbe, der Kranich zwitscherte ich; ich girrte wie die Taube. Schwach waren meine Augen zur Höhe. Jehovah, ich bin beklommen, bürge für mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Was soll ich reden? Und Er sprach zu mir und tat es. Alle meine Jahre will ich zu Ihm dahinwallen, ob der Bitterkeit meiner Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'Herr, dadurch leben sie; und in ihnen allen hat mein Geist Leben. Und Du ließest mich genesen und leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Siehe, zum Frieden ward mir das Bittere, das Bittere. Aber Du hattest Gefallen an meiner Seele, mehr als am nichtigen Graben; denn hinter Deinen Rücken warfst Du alle meine Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Denn nicht bekennt Dich die Hölle, noch lobt Dich der Tod, nicht harren auf Deine Wahrheit die, so in die Grube hinabfahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Der Lebende, der Lebende, der bekennt Dich, wie ich heute. Der Vater wird den Söhnen kundtun Deine Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Jehovah rettet mich; und lasset uns alle Tage unseres Lebens zum Saitenspiel meine Lieder singen im Hause Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Und Jeschajahu sprach: Bringt einen Feigenkuchen und zerquetscht ihn auf das Geschwür, daß er am Leben bleibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Und Chiskijahu hatte gesagt: Was ist das Zeichen, daß ich hinaufgehe zum Hause Jehovahs?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'Um diese Zeit sandte Merodach Baladan, der Sohn Baladans König von Babel, ein Schreiben und ein Geschenk an Chiskijahu, denn er hatte gehört, daß er erkrankt und wieder erstarkt war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'Und Chiskijahu ward fröhlich über sie, und ließ sie sehen das Haus seines Vorrats, das Silber und das Gold, und die Gewürze und das gute Öl und das ganze Rüsthaus und alles, was sich in seinen Schätzen fand. Es war nichts das Chiskijahu in seinem Hause und in seiner ganzen Herrschaft ihnen nicht zeigte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Und es kam Jeschajahu, der Prophet, zum König Chiskijahu und sprach zu ihm: Was sagten diese Männer und woher kamen sie zu dir? Und Chiskijahu sprach: Aus fernem Lande kamen sie zu mir, von Babel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'Und er sprach: Was haben sie in deinem Hause gesehen? Und Chiskijahu sprach: Alles, was in meinem Hause ist, sahen sie. Da ist nichts, das ich sie nicht sehen ließ in meinen Schätzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Und Jeschajahu sprach zu Chiskijahu: Höre das Wort Jehovahs der Heerscharen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Siehe, Tage kommen, da alles, was in deinem Hause ist, und was deine Väter aufgespeichert haben bis auf diesen Tag, nach Babel getragen wird, und nichts überbleibt, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Und von deinen Söhnen, die von dir ausgehen werden, die du zeugst, wird man nehmen und sie werden Hofbeamte sein im Palaste des Königs von Babel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'Und Chiskijahu sprach zu Jeschajahu: Gut ist das Wort Jehovahs, das du geredet hast. Und er sagte: Denn es wird Friede und Treue in meinen Tagen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Tröstet, tröstet Mein Volk! spricht euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Redet zum Herzen Jerusalems und ruft ihr zu: Vollendet ist ihr Kriegsdienst, abgetragen ihre Missetat; denn Doppeltes hat sie empfangen von Jehovahs Hand für alle ihre Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Die Stimme eines Rufenden in der Wüste: Räumt den Weg Jehovahs, macht gerade eine Bahn in der Einöde unserem Gotte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Erhoben soll jedes Tal, geniedrigt aller Berg und Hügel werden; und was krumm ist, soll gerade, das Abschüssige zur Ebene werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'Und die Herrlichkeit Jehovahs wird geoffenbart und alles Fleisch wird sie sehen allzumal; denn Jehovahs Mund hat es geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Es spricht eine Stimme: Rufe! und er sprach: Was soll ich rufen? - Alles Fleisch ist Gras; und alle seine Heiligkeit ist wie des Feldes Blume.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Es verdorrt das Gras, es fällt ab die Blume, denn Jehovahs Hauch hat sie angeweht. Fürwahr, Gras ist das Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Es verdorrt das Gras, die Blume fällt ab, aber das Wort unseres Gottes besteht ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Auf hohen Berg steige hinauf, du Heilsbotin Zion, erhöhe deine Stimme mit Kraft, Heilsbotin Jerusalem. Erhöhe sie, fürchte dich nicht. Sprich zu den Städten Jehudahs: Seht, euer Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Siehe, der Herr, Jehovah kommt mit Stärke, und Sein Arm herrscht für Ihn. Siehe, Sein Lohn ist bei Ihm und Sein Werk vor Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Er weidet wie ein Hirte Seine Herde, bringt die Lämmchen zusammen in Seinen Arm und trägt sie in Seinem Busen und leitet die Säugenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Wer hat die Wasser mit der hohlen Hand gemessen, und die Himmel mit der Spanne hergerichtet und im Dreiling der Erde Staub gefaßt, und die Berge in der Waagschale, die Hügel gewogen in der Waage?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Wer hat Jehovahs Geist dahin gerichtet und als der Mann Seines Rates es Ihm kund getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'Mit wem beriet Er Sich, der Ihm Einsicht gegeben hätte und Ihn lehrte den Pfad des Gerichtes, und Ihn Kenntnis lehrte und Ihm den Weg der Einsicht kund täte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Siehe, Völkerschaften sind wie der Tropfen vom Eimer, wie ein Stäubchen in der Waagschale geachtet: siehe, Er hebt wie das Winzigste die Inseln empor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Und nicht zum Brennen genügt der Libanon, nicht zum Brandopfer genügt sein Wild.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Alle Völkerschaften sind vor Ihm wie nichts, für weniger denn nichts, und Ödes vor Ihm geachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Und wem wollt ihr Gott vergleichen, und welches Gebilde Ihm gleichstellen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Der Künstler gießt das Bild, und der Goldschmied breitet Gold darauf aus und Silberkettchen schmelzt er daran.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Wer zu verarmt ist für solche Hebe, wählt ein nicht faulend Holz, sucht sich einen weisen Künstler, ein Schnitzbild ihm zu bereiten, das nicht wankt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Wisset ihr es nicht, hört ihr nicht, hat man es euch nicht von Anfang angesagt; habt ihr nicht Einsicht in der Erde Gründungen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'Ihm, Der über dem Runde der Erde sitzt, Dem sind wie Heuschrecken, die darauf wohnen; Ihm, Der die Himmel wie dünnen Teppich ausspannt, sie ausdehnt wie ein Zelt zum Wohnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'Ihm, Der zu Nichts macht die Beherrscher, und die Richter der Erde wie die Leere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Kaum sind sie eingepflanzt, kaum gesät, kaum wurzelt in der Erde ihr Stamm, da haucht Er sie auch an, und sie verdorren, und wie Stoppeln trägt sie dahin der Wettersturm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Und wem wollt ihr Mich vergleichen, daß Ich ähnlich wäre? spricht der Heilige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Erhebt eure Augen in die Höhe und sehet: Wer schuf dies? Er, Der ihr Heer herausbringt nach der Zahl, sie alle mit Namen nennt; aus der Menge Seiner Vollkräftigen, rüstig an Kraft, darf kein Mann fehlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Warum sprichst du, Jakob, und redest du, Israel: Mein Weg ist vor Jehovah verborgen, und vorüber ist mein Gericht vor meinem Gott gegangen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Weißt du nicht, hast du nicht gehört, daß ein Gott der Ewigkeit Jehovah ist, Welcher der Erde Enden geschaffen hat, Der nicht matt, noch müde wird, daß kein Ergründen Seiner Einsicht ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Er gibt dem Matten Kraft, und mehrt die Stärke dem Unvermögenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Und die Jungen werden matt und müde werden, und Jünglinge straucheln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'Die aber auf Jehovah hoffen, verjüngen die Kraft, sie steigen auf mit Schwingen wie Adler, sie laufen und ermüden nicht, sie gehen und werden nicht matt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Schweigt mir stille, ihr Inseln, und laßt die Volksstämme die Kraft verjüngen. Lasset sie herzutreten, dann laßt sie reden, laßt zusammen uns dem Gerichte uns nahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Wer hat erweckt vom Aufgang den Gerechten, Ihn gerufen, Ihm auf dem Fuße zu folgen, vor Ihm die Völkerschaften dahingegeben und Ihm Könige unterworfen und sie wie Staub Seinem Schwerte, wie dahingetriebene Stoppel Seinem Bogen gegeben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'Er setzt ihnen nach, zieht vorbei im Frieden, Sein Fuß kommt nicht auf den Pfad.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Wer hat es getan und gemacht? Wer ruft von Anfang den Geschlechtern? Ich, Jehovah, bin der Erste und mit den Letzten bin Ich derselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Die Inseln sahen es und fürchteten sich, die Enden der Erde erzittern, sie nahen und kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Ein Mann steht dem Genossen bei und spricht zu seinem Bruder: Sei stark!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'Und der Künstler stärkt den Goldschmied, der Glätter mit dem Hammer sagt zum Amboßschläger von der Lötung: Es ist gut, und macht es fest mit Nägeln, auf daß es nicht wanke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Du aber, Israel, Mein Knecht Jakob, den Ich erwählt habe, Samen Abrahams, Meines Freundes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'Du, den Ich von der Erde Enden erfaßte und von ihren Säumen rief und zu dir sprach: Mein Knecht bist du; dich habe Ich erwählt und verschmähe dich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Fürchte dich nicht, denn Ich bin mit dir; schaue nicht um dich, denn Ich bin dein Gott; Ich stärke dich, ja, Ich stehe dir bei, erhalte dich mit der Rechten Meiner Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Siehe, beschämt und zuschanden werden alle, die wider dich entbrannten, sie werden wie Nichts und vergehen, die Männer, die mit dir hadern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Du wirst nach ihnen suchen, und sie nicht finden, die Männer, die mit dir zankten. Sie werden nicht mehr sein, zu Ende kommen die Männer, die mit dir stritten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Denn Ich, Jehovah, bin dein Gott, fasse dich an deiner Rechten, spreche zu dir: Fürchte dich nicht, Ich stehe dir bei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Fürchte nicht, du Wurm Jakob, ihr Sterbende Israels, Ich stehe dir bei, spricht Jehovah und dein Erlöser, der Heilige Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Siehe, Ich mache dich zur Dreschwalze, zum neuen Dreschwagen, vielzackig; Berge sollst du zerdreschen und zermalmen, und wie Spreu die Hügel machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Du wirst sie worfeln, und der Wind wird sie forttragen, der Wettersturm sie zerstreuen, und in Jehovah wirst du frohlocken, des Heiligen in Israel dich rühmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Die Elenden und Dürftigen suchen Wasser und keines ist da; vor Durst verlechzt ihre Zunge; Ich, Jehovah, werde sie erhören, Ich, der Gott Israels, verlasse sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Auf Abhängen will Ich Flüsse öffnen, und Quellen in der Täler Mitte, zum Wasserteiche die Wüste machen, und dürres Land zu Ausgängen von Wassern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Ich gebe in der Wüste die Zeder von Schittah und die Myrte und den Ölbaum, und setze in die Einöde Tanne und Kiefer und Buchsbaum zumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'Auf daß sie sehen und wissen, und merken und verstehen zumal, daß Jehovahs Hand dies tut, und der Heilige in Israel es schafft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Laßt nahen euren Hader, spricht Jehovah; bringt herbei eure Bekräftigungen, spricht der König Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Laßt sie herbeibringen und uns ansagen, was begegnen wird. Das Erste, was war es? Sagt es an, daß wir es zu Herzen nehmen und wissen das Spätere daraus, oder laßt uns hören, was da kommen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Sagt an die Zeichen für das Nachherige, daß wir wissen, daß ihr Götter seid, auch Gutes und Böses könnet tun. Dann wollen wir es beschauen und es sehen zumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Siehe, ihr seid aus Nichts und weniger als nichts ist euer Tun, zum Greuel wird, wer euch erwählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Von Mitternacht her erwecke Ich den, der kommt, vom Aufgang der Sonne ihn, der Meinen Namen anruft; und er kommt an die Vorsteher wie an Lehm und gleichwie der Töpfer zerstampft er den Ton.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Wer hat es angesagt vom Anbeginn, daß wir es wußten? und vor Zeiten, daß wir sprächen: Gerecht? Ja, da ist keiner, der es ansagte; ja keiner, der es hören ließ, ja keiner, der eure Reden hörte!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Der Erste bin Ich, Der zu Zion sagt: Siehe, siehe, sie sind da! und Ich sende an Jerusalem einen Heilsboten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'Und Ich sehe hin und da ist kein Mann; und unter ihnen, und da ist keiner, der Rat gäbe, die Ich fragte und die Mir ein Wort erwiderten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Siehe, Unrecht und Nichtigkeit sind alle ihre Werke, Hauch und Leere sind ihre Guß-bilder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Siehe, Mein Knecht, auf Den Ich Mich stütze, Mein Auserwählter, an Dem Meine Seele Wohlgefallen hat! Ich habe Meinen Geist auf Ihn gegeben, das Recht läßt Er für die Völkerschaften ausgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Er wird nicht schreien und nicht erheben, und nicht hören lassen Seine Stimme auf der Gasse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Das zerquetschte Rohr zerbricht Er nicht und den verlöschenden Flachs löscht Er nicht aus, zur Wahrheit bringt Er heraus das Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Er wird nicht verlöschen, noch zerquetschen bis Er das Recht auf Erden gesetzt hat; und die Inseln warten auf Sein Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'So spricht der Gott Jehovah, Der die Himmel erschaffen und sie ausgespannt, die Erde ausgebreitet und ihre Sprößlinge, Der Odem gibt dem Volk darauf, und Geist denen, so darauf wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Ich, Jehovah, habe Dich gerufen in Gerechtigkeit und fasse Dich an der Hand und werde Dich bewahren und will zum Bund Dich geben des Volkes, zum Licht der Völkerschaften;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'Aufzutun blinde Augen, auszubringen aus dem Verschluß die Gebundenen, aus dem Hause des Kerkers die, so im Finstern sitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Ich bin Jehovah, dies ist Mein Name, und Meine Herrlichkeit werde Ich nicht einem anderen geben, noch Mein Lob den Schnitzbildern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Siehe, das Erste ist gekommen und das Neue sage Ich an, bevor es noch ist gesproßt, lasse Ich es euch hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Singt ein neues Lied Jehovah, Sein Lob von dem Ende der Erde, die ihr zum Meer hinabsteigt, und was es füllt, die Inseln und ihre Bewohner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Es erhebe Ihn die Wüste und ihre Städte und die Gehöfte, da Kedar wohnt. Jubelt, ihr Bewohner der Felsenklippe. Laßt es ertönen von der Berge Häuptern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Laßt sie dem Jehovah Herrlichkeit geben und Sein Lob ansagen auf den Inseln!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Jehovah wird wie ein Held ausziehen, wie ein Mann des Streites den Eifer erregen, aufschreien, laut tönen lassen und Seiner Feinde mächtig werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Ich habe geschwiegen von Ewigkeit her, Ich habe still geschwiegen, hielt an Mich; wie eine Gebärerin will Ich ausschreien, will verwüsten und hinabschlingen zumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Ich will Berge und Hügel veröden und all ihr Kraut verdorren lassen, und Flüsse setzen zu Inseln, und Teiche vertrocknen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'Und die Blinden lasse Ich auf einem Wege gehen, den sie nicht kannten, lasse sie Steige betreten, die sie nicht kannten, will Finsternis vor ihnen zum Licht setzen, und was krumm war, gerade machen. Diese Dinge will Ich tun und sie nicht verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Hinter sich sollen sie zurückweichen, mit Scham sich schämen, die auf das Schnitzbild vertrauten; die zu dem Gußbild sprachen: Ihr seid unsere Götter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Ihr Tauben, höret, und ihr Blinden, blicket her, auf daß ihr sehet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Wer ist blind, wenn nicht Mein Knecht, und taub, wie Mein Bote, Den Ich sende? Wer ist blind, wenn nicht der Vollkommene, und so blind, als der Knecht Jehovahs?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Vieles hast du gesehen, und du hältst es nicht, hast die Ohren aufgetan und hörst nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Jehovah hatte Lust, wegen Seiner Gerechtigkeit, daß Er das Gesetz groß und herrlich machte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'Und doch ist es ein beraubt und geplündert Volk, bestrickt sind alle seine Jünglinge und in Kerkerhäusern versteckt, zum Raube geworden, und da war kein Erretter, geplündert, und niemand sprach: Gib zurück!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Wer unter euch nimmt dies zu Ohren, horcht und hört auf das Spätere?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Wer hat zur Plünderung Jakob hingegeben und Israel den Räubern? Ist es nicht Jehovah, wider Den wir sündigten, in Dessen Wegen sie nicht willens waren zu wandeln und nicht hörten auf Sein Gesetz?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Und Er ergoß über dasselbe Seines Zornes Grimm und die Stärke des Streites. Und sie flammte rings um dasselbe her, und es wußte es nicht; und es brannte an ihm, aber es nahm es nicht zu Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Und nun, so spricht Jehovah, dein Schöpfer, o Jakob, und dein Bildner, o Israel. Fürchte nicht; denn Ich habe dich erlöst, gerufen bei deinem Namen. Mein bist du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Wenn du durch das Wasser hindurchgehst, will Ich bei dir sein, und durch die Flüsse, so werden sie dich nicht überfluten. So du durch das Feuer gehst, sollst du nicht versengt werden, noch soll die Flamme an dir brennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Denn Ich bin Jehovah, dein Gott, der Heilige Israels, dein Heiland; Ich habe als deine Sühne Ägypten, Kusch und Seba an deiner Statt gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Weil du kostbar bist in Meinen Augen, bist du verherrlicht, und Ich liebe dich, und gebe den Menschen hin statt deiner, und Volksstämme statt deiner Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Fürchte dich nicht, denn Ich bin mit dir; vom Aufgang lasse Ich deinen Samen kommen und bringe dich zusammen vom Abend;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Zur Mitternacht spreche Ich: Gib her! und zum Süden: Wehre nicht! Bringe herein Meine Söhne von der Ferne und Meine Töchter vom Ende der Erde!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'Jeglichen, der genannt ist nach Meinem Namen, den habe Ich zu Meiner Herrlichkeit geschaffen, ihn gebildet und ihn gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Bringe heraus das Volk, das blind ist und hat Augen, und die Tauben, die Ohren haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Kommt zusammen alle Völkerschaften zumal, und sammelt euch ihr Volksstämme. Wer unter ihnen saget solches an, und läßt uns Früheres hören? Sie mögen ihre Zeugen geben und sich rechtfertigen, und sie werden hören und sagen: Wahrheit ist es!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Ihr seid Mir Zeugen, spricht Jehovah, und Mein Knecht, Den Ich erwählt, auf daß ihr wisset und Mir glaubet und einsehet, daß Ich es bin. Vor Mir ward kein Gott gebildet, und nach Mir wird keiner sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Ich, Ich bin Jehovah, und kein Heiland ist außer Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Ich habe es angesagt und habe gerettet und hören lassen, und kein Fremder war unter euch; und ihr seid Meine Zeugen, spricht Jehovah, und Ich bin Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Auch seit ein Tag ist, bin Ich. Und niemand errettet aus Meiner Hand. Ich tue, wer wendet es zurück?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'So spricht Jehovah, euer Erlöser, der Heilige Israels: Um euretwillen habe Ich gen Babel gesandt und alle Riegel heruntergebracht, und die Chaldäer, deren Jubel ist in den Schiffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Ich, Jehovah, bin euer Heiliger, der Israel erschaffen, euer König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'So spricht Jehovah, Der einen Weg gibt in dem Meer und Steige in starken Wassern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'Der Streitwagen und Roß läßt herauskommen, die Streitmacht und den Starken; da liegen sie beisammen, sie stehen nimmer auf, sie sind verloschen; wie der Flachs erlöschen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Gedenkt nicht an das Frühere, und auf die Vorzeit merket nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Siehe, Neues tue Ich, nun wird es emporsprossen. Werdet ihr es nicht erkennen? Ich mache in der Wüste einen Weg, im Wüstenland Flüsse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Mich wird verherrlichen des Feldes Wild, Drachen und Käuzlein, daß Wasser Ich gegeben in der Wüste, Flüsse im Wüstenland, zu tränken Mein auserwähltes Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'Dies Volk habe Ich Mir gebildet, es soll Mein Lob erzählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Und nicht, daß du Mich hättest gerufen, Jakob, daß du um Mich dich gemüht hättest, Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Du hast Mir nicht Schafe zu deinen Brandopfern hereingebracht, noch Mich durch Schlachtopfer verherrlicht. Ich habe dich nicht mit Speiseopfern dienen lassen, nicht mit Weihrauch dich ermüdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'Du hast Mir nicht für Silber Kalmus gekauft, hast Mich nicht in dem Fette deiner Opfer schwelgen lassen; du ließest Mich dienen mit deinen Sünden, und Mich hast du ermüdet mit deinen Missetaten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Ich, Ich bin es, Der deine Übertretungen ausgewischt, wegen Meiner, und habe deiner Sünden nicht gedacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Gedenke Meiner, laß uns zusammen rechten; erzähle du, daß du dich rechtfertigst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Dein erster Vater hat gesündigt, und deine Dolmetscher sind abgefallen von Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Und Ich entweihe die Obersten der Heiligkeit, und gebe Jakob zum Bann und Israel der Verhöhnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Und nun höre, Jakob, Mein Knecht, und Israel, den Ich habe erwählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'So spricht Jehovah, Der dich gemacht, und dein Bildner vom Mutterleib her, Der dir steht bei: Fürchte dich nicht, Mein Knecht, Jakob, und Jeschurun, den Ich habe auserwählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Denn Ich will Wasser gießen auf Dürstendes und Bächlein auf das Trockene, will Meinen Geist gießen auf deinen Samen und Meinen Segen auf deine Sprößlinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'Und sie sollen sprossen zwischen dem Grase, wie Weiden über Wasserströme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Dieser wird sprechen: Ich bin Jehovahs; und dieser wird sich nach dem Namen Jakobs nennen. Und jener verschreibt sich mit seiner Hand dem Jehovah und benennt sich mit dem Namen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'So spricht Jehovah, der König Israels und sein Erlöser, Jehovah der Heerscharen: Ich bin der Erste und Ich bin der Letzte und außer Mir ist kein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'Und wer ist wie Ich, der rufet und ansagt und Mir es anordnet, seit Ich ein Volk der Ewigkeit setzte; und laßt sie ihnen die Zeichen und was da kommen soll, ansagen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Laßt euch nicht schauern und fürchtet euch nicht! Habe Ich es nicht von jeher dich hören lassen und angesagt, und ihr seid Mir Zeugen. Ist ein Gott da außer Mir? Es ist kein Fels; Ich weiß keinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Die Bildner der Schnitzbilder sind allesamt eitel, und ihr Vielbegehrtes ist nichts nütze; und ihre Zeugen sind sie selber: sie sehen nicht und wissen nichts, so daß sie beschämt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Wer bildet einen Gott und gießt ein Schnitzbild, das nichts nütze ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Siehe, alle seine Gesellen werden beschämt, und von Menschen sind die Künstler. Laßt zusammenkommen sie alle, laßt sie stehen, schauern, beschämt werden allzumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Er schmiedet das Eisen mit der Zange, und arbeitet mit der Kohle, und bildet es mit Hämmern, und arbeitet daran mit dem Arme seiner Kraft; er hungert auch und ist keine Kraft da; er trinkt kein Wasser und ist matt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Er schnitzt das Holz, er spannt die Meß-schnur und gestaltet es mit dem Stift; er macht es an den Ecken und gestaltet es mit dem Zirkel; und macht es nach dem Vorbild eines Mannes, wie ein schmucker Mensch, auf daß es im Hause wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Er haut sich Zedern um und nimmt Buchen und Eichen, und macht sich stark mit des Waldes Bäumen, und er pflanzt einen Ornusbaum, daß der Regen ihn groß mache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'Und es ist für den Menschen zum Brennen, und er nimmt davon und wärmt sich, und er zündet es an und bäckt Brot; er macht sich auch einen Gott daraus und betet ihn an, er macht es zu einem Schnitzbild und fällt vor ihm nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Die Hälfte davon verbrennt er im Feuer, mit der anderen Hälfte ißt er Fleisch, brät Braten und sättigt sich, auch wärmt er sich und spricht: Bruder, ich bin warm, ich habe Feuer gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Und dessen Überrest macht er sich zu einem Gott, zu seinem Schnitzbild, fällt vor ihm nieder und verbeugt sich und betet zu ihm und spricht: Errette mich, denn mein Gott bist du!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Sie wissen nicht und sehen nicht ein, denn verkleistert sind ihre Augen, daß sie nicht sehen, ihre Herzen, daß sie nicht verstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'Und er nimmt es nicht zu Herzen und weiß nicht und sieht nicht ein, daß er spräche: Die Hälfte davon verbrannte ich im Feuer, und buk auch über seinen Kohlen Brot, briet Fleisch und aß, und das übrige sollte ich zum Greuel machen, vor dem Holzklotz niederfallen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'Er weidet sich mit Asche, und sein hintergangenes Herz wendet ihn ab, daß seine Seele er nicht erretten kann und nicht spricht: Ist nicht eine Lüge in meiner Rechten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Daran gedenke, Jakob und Israel; denn Mein Knecht bist du. Ich habe dich gebildet, Mein Knecht bist du, Israel, und sollst Mir nicht vergessen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Wie eine dichte Wolke wische Ich aus deine Übertretungen und wie eine Wolke deine Sünden. Kehre zu Mir zurück, denn Ich habe dich erlöst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Jubelt ihr Himmel, denn Jehovah hat es getan; rufet laut ihr unteren Räume der Erde, brecht aus in Jubel ihr Berge, der Wald und jeder Baum darin; denn erlöst hat Jehovah Jakob, und sich in Israel verklärt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'So spricht Jehovah, dein Erlöser und dein Bildner von Mutterleib an: Ich, Jehovah, tue alles, spanne aus die Himmel, Ich allein breite die Erde aus von Mir Selbst,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Er macht zunichte der Unwahren Zeichen, macht rasen die Wahrsager, wendet zurück die Weisen hinter Sich, und ihr Wissen macht Er zur Narrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'Die Worte Seines Knechtes bestätigt Er, vollbringt Seiner Boten Rat, Er spricht zu Jerusalem: Werde bewohnt, und zu den Städten Jehudahs: Werdet gebaut, und seine Verödungen richte Ich auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'Zum Schlunde spreche Ich: Vertrockne! Und deine Flüsse trockne Ich aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'Ich spreche zu Koresch: Mein Hirte! Und er vollbringt alles, wozu Ich Lust habe; und zu Jerusalem spreche Ich: Werde gebaut! und zu dem Tempel: Werde gegründet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'So spricht Jehovah zu Seinem Gesalbten, zu Koresch, den Ich bei seiner Rechten fasse, vor ihm zu unterwerfen die Völkerschaften, und die Lenden der Könige löse, die Türen vor ihm zu öffnen, daß die Tore nicht geschlossen sind:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Ich ziehe vor dir her, mache die Krümmungen gerade, zerbreche eherne Torflügel, zerhaue eiserne Riegel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'Und gebe dir die Schätze der Finsternis und das Verhohlene des Verborgenen, daß du wissest, daß Ich Jehovah bin, Der dich bei deinem Namen gerufen, der Gott Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Wegen Meines Knechte Jakobs und Israels, Meines Auserwählten; und Ich rief bei deinem Namen dich, benannte dich, da du Mich nicht kanntest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Ich bin Jehovah, und sonst keiner, außer Mir ist kein Gott. Ich habe dich umgürtet, da du Mich nicht kanntest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'Daß sie wissen von der Sonne Aufgang und vom Abend, daß nichts ist außer Mir; daß Ich Jehovah bin, und keiner mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'Ich bilde das Licht und schaffe Finsternis, mache Frieden und schaffe Böses; Ich, Jehovah, Der tuet alles dies.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Träufelt, ihr Himmel, von oben und rieselt ihr Ätherkreise Gerechtigkeit. Die Erde öffne sich und bringe die Frucht des Heils, und Gerechtigkeit sprosse zumal. Ich, Jehovah, schaffe es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Wehe dem, der mit seinem Bildner hadert, der Scherbe, mit den Scherben des Bodens! Sagt denn der Ton zu seinem Bildner: Was machst du? und dein Werk: es hat keine Hände?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Wehe dem, der zum Vater sagt: Was zeugest du? und zum Weibe: Was kreißest du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'So spricht Jehovah, der Heilige Israels und sein Bildner: Zeichen erbittet von Mir über Meine Söhne und gebietet Mir über Meiner Hände Werk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Ich habe die Erde gemacht und den Menschen auf ihr geschaffen; Ich, Meine Hände haben ausgespannt die Himmel und all ihr Heer habe Ich geboten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Ich habe ihn erregt in Gerechtigkeit und alle seine Wege mache Ich gerade. Er soll bauen Meine Stadt und Meine Weggeführten entlassen ohne Kaufpreis und ohne Geschenk! spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'So spricht Jehovah: Ägyptens Arbeit und die Handelsware von Kusch und von den Sabäern, den Männern des Maßes, wird auf Dich übergehen und dein sein, Dir werden sie nachfolgen, in Fesseln werden sie vorübergehen, vor Dir sich niederbeugen, zu dir beten, nur in Dir ist Gott, und ist sonst kein anderer Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Fürwahr, ein verborgener Gott bist Du, Du Gott Israels, der Heiland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Beschämt und auch zuschanden werden sie alle, in Schanden ziehen sie hin allzumal, die Werkleute der Gebilde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Israel wird von Jehovah gerettet mit dem Heile der Ewigkeit. Ihr werdet nicht beschämt noch zuschanden in die Zeitläufe immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Denn so spricht Jehovah, Der die Himmel hat geschaffen, Er, der Gott, Der die Erde gebildet und gemacht, Er, Der sie gefestigt, Er hat sie nicht geschaffen, daß sie eine Leere sein soll, sondern sie gebildet, daß man auf ihr wohnen sollte: Ich bin Jehovah, und sonst keiner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Ich habe nicht im Verborgenen geredet, nicht in eines finsteren Landes Ort, nicht gesprochen zu dem Samen Jakobs: Umsonst suchet ihr Mich. Ich bin Jehovah, rede Gerechtigkeit, sage an das Gerade.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Ziehet euch zusammen und kommet, tretet herbei zumal, ihr Entkommenen der Völkerschaften. Nichts wissen, die das Holz ihres Schnitzbildes tragen und beten zu einem Gotte, der nicht retten kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Saget an und lasset sie herbeitreten und auch zusammen beraten: Wer hat von der Vorzeit her solches hören lassen, es von jeher angesagt? Bin Ich es nicht, Jehovah, und sonst kein Gott außer Mir, ein gerechter Gott und Heiland, es ist keiner außer Mir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Wendet euch zu Mir und werdet gerettet alle Enden der Erde; denn Ich bin Gott und keiner sonst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Bei Mir habe Ich geschworen, von Meinem Mund geht aus Gerechtigkeit, ein Wort, und es kehrt nicht zurück: Vor Mir wird jedes Knie sich beugen, jede Zunge schwören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Nur in Jehovah, sagte er mir, ist Gerechtigkeit und Stärke! Es werden zu Ihm kommen und sich schämen alle, die wider Ihn entbrannten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'In Jehovah werden gerecht werden und sich rühmen aller Same Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Bel beugt sich, es krümmt sich Nebo. Ihre Götzenbilder sind für das wilde Tier und das Vieh. Was ihr herumtragt wird aufgeladen, eine Last der Matten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Sie krümmen sich, sie beugen sich allzumal, sie können die Last nicht wegbringen, und ihre Seele geht in die Gefangenschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Höret auf Mich, o Haus Jakobs und aller Überrest vom Hause Israels, ihr, die ihr Mir aufgeladen seid vom Mutterleibe an und getragen vom Mutterschoß an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'Und bis zum Alter bin Ich Derselbe, und bis zum Greisenhaar werde Ich euch forttragen; Ich habe es getan und werde euch tragen und forttragen und befreien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Wem macht ihr Mich gleich und stellet Mich gleich? Und vergleicht Mich, daß wir ähnlich wären?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Die Gold aus dem Beutel herausschütteln und Silber mit dem Rohre wägen, einen Goldschmied dingen, daß er es mache zu einem Gott, vor dem sie niederfallen, ihn auch anbeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'Sie tragen ihn auf der Schulter, sie laden ihn auf und lassen ihn nieder an seiner Stelle. Und er steht und weicht nicht von seinem Orte. Schreit einer auch zu ihm, er antwortet nicht, er rettet ihn nicht aus seiner Drangsal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Gedenket dessen und ermannet euch; nehmt es zurück zu Herzen, ihr Übertreter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Gedenket des Früheren aus der Urzeit; denn Ich bin Gott, und kein Gott mehr, und nichts ist wie Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'Von Anfang an sagte Ich an das Letzte, und von der Vorzeit her, was noch nicht getan war, und spreche: Mein Ratschluß wird bestehen, und alles, wozu Ich Lust habe, tue Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'Vom Aufgang rufe Ich einen Raubvogel, aus dem Land der Ferne den Mann Meines Rates. Was Ich nun geredet, lasse Ich auch kommen; was Ich gebildet, das tue Ich auch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Höret auf Mich, ihr Gewaltigen von Herzen, ihr, die ihr ferne seid von der Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Ich habe nahe gebracht Meine Gerechtigkeit, sie ist nicht fern; und Mein Heil wird nicht zögern. Und Ich gebe Heil in Zion, Israel Meinen Schmuck.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Steige herunter und sitze auf dem Staub, du Jungfrau, Tochter Babels. Sitze auf die Erde, da ist kein Thron, Tochter der Chaldäer. Denn man nennt dich hinfort nicht mehr: die Zarte und Üppige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Nimm die Mühle und mahle Mehl, decke auf dein Lockenhaar, entblöße den Fuß, decke auf den Schenkel, gehe durch die Flüsse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Deine Blöße werde aufgedeckt, gesehen auch deine Schmach. Ich nehme Rache und soll kein Mensch vermitteln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Unser Erlöser, Jehovah der Heerscharen ist Sein Name, der Heilige Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Setze dich stille und gehe hinein in das Finstere, Tochter der Chaldäer, weil man dich fürder nicht mehr nennt Gebieterin der Königreiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Ich war über Mein Volk entrüstet, ließ Mein Erbe entweihen und gab sie in deine Hand. Du hattest kein Erbarmen mit ihnen, machtest dein Joch über den Greis sehr schwer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'Und du sprachst: Ich werde Gebieterin sein ewiglich; so daß du dieses nicht legtest auf dein Herz, und gedachtest nicht dessen Letztes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Nun aber höre dies, du Wollüstige, die in Sicherheit sitzt und spricht in ihrem Herzen: Ich und keine sonst; ich werde nicht als Witwe sitzen und Kinderlosigkeit nicht kennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Und es kommen die zwei über dich, augenblicklich, an einem Tage bist du kinderlos und Witwe. Vollauf kommen sie über dich ob deiner vielen Zaubereien und ob der sehr großen Macht deiner Bannsprüche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Und du vertrautest auf deine Bosheit und sagtest: Es sieht mich niemand. Deine Weisheit und dein Wissen verleiteten dich, daß du in deinem Herzen sprachst: Ich und sonst keine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Und Böses wird kommen über dich, das du nicht weißt abzubitten, und Unheil wird fallen über dich, das du nicht zu sühnen vermagst, und plötzlich wird ein Unwetter über dich kommen, das du nicht weißt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Bleibe doch stehen bei deinen Bannsprüchen und deinen vielen Zaubereien, mit denen du dich von Jugend auf hast abgemüdet. Vielleicht vermagst du zu nützen, vielleicht erregst du Grauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Bist du ermüdet von deinen vielen Ratschlägen? Lasse sie doch stehen und dich retten, die Beobachter des Himmels, die Beschauer der Sterne, die aus den Neumonden wissen wollen, was über dich wird kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Siehe, wie die Stoppel sind sie worden, das Feuer hat sie verbrannt. Sie erretten ihre Seele nicht aus der Hand der Flamme. Da ist keine Kohle zum Wärmen, kein Feuer, davor zu sitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'So werden dir sein die, mit denen du dich mühtest, deine Händler von deiner Jugend auf. Jeder Mann wird irren nach seiner Seite hin, und keiner dich retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Höret das, o Haus Jakobs, die ihr genannt seid mit dem Namen Israels, und die ihr aus den Wassern Jehudahs hervorgegangen seid; die ihr schwört bei dem Namen Jehovahs, und des Gottes Israels gedenket nicht in Wahrheit und nicht in Gerechtigkeit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'Weil ihr genannt seid nach der Stadt der Heiligkeit und euch lehnet auf den Gott Israels; Jehovah der Heerscharen ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Das Frühere sage Ich an zuvor und von Meinem Munde ging es aus, und Ich ließ sie es hören, und plötzlich tue Ich es, daß es kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Weil Ich weiß, daß du hart bist, und dein Nacken eine Sehne von Eisen und deine Stirne ist Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'Und Ich sage es dir an zuvor, lasse es dich hören, ehe denn es gekommen ist, daß du nicht sprechest: Mein Götzenbild hat es getan, und mein Schnitzbild, und mein Gußbild hat es so geboten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Du hast es gehört, erschaue dir das alles, und ihr, wollt ihr es nicht ansagen? Ich laß dich Neues hören von nun an, und Verwahrtes, das du nicht hast gewußt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Nun ist es erschaffen und nicht zuvor und den Tag vorher, und du hattest es nicht gehört, auf daß du nicht sagen möchtest: Siehe, ich habe es gewußt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Du hast es weder gehört, noch gewußt; auch war dein Ohr zuvor nicht geöffnet; denn Ich wußte, daß du treulos, ja treulos handeln würdest, und man dich einen Übertreter von Mutterleibe an nannte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Um Meines Namens willen übe Ich Langmut, und Meines Lobes wegen halte Ich Mich ab von dir, daß Ich dich nicht ausrotte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Siehe, Ich will dich läutern, aber nicht zu Silber, will dich erwählen in des Elends Schmelzofen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Um Meinetwillen, um Meinetwillen tue Ich es; denn was sollte es entweiht werden? Und Meine Herrlichkeit will Ich keinem anderen geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Höre auf Mich, Jakob, und du, Israel, von Mir berufen, Ich bin Derselbe, Ich der Erste, Ich auch der Letzte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Auch hat gegründet Meine Hand die Erde, und Meine Rechte die Himmel umspannt. Ich rufe ihnen, sie stehen da allzumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Kommt zusammen ihr alle und höret. Wer unter ihnen hat solches angesagt? Jehovah liebt ihn, und wird tun, wozu Er Lust hat, an Babel und Seinen Arm an den Chaldäern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Ich, Ich habe geredet, auch ihn gerufen, Ich habe ihn kommen lassen, und sein Weg gelingt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Nahet zu Mir, höret dies: Ich habe vom Anfang an nicht im Verborgenen geredet. Von der Zeit, da es geschah, bin Ich allda. Und nun hat Mich der Herr Jehovah und Sein Geist gesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'So spricht Jehovah, dein Erlöser, der Heilige Israels: Ich bin Jehovah, dein Gott, Der dich lehrt zum Nutzen, Der dich auf dem Wege, den du wandeln sollst, gehen läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'O, daß du auf Meine Gebote horchtest! Dann wäre dein Friede gleich dem Flusse, und deine Gerechtigkeit so wie die Wogen des Meeres.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'Und dein Same wäre wie der Sand, und deiner Eingeweide Sprößlinge wie dessen Kies. Sein Name würde nicht ausgerottet, noch vernichtet vor Meinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Gehet aus von Babel; entweichet von den Chaldäern mit Stimmen des Jubelgesangs; saget an, lasset solches hören, bringt es aus bis an das Ende der Erde; sprechet: Jehovah hat erlöst Seinen Knecht Jakob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'Und sie haben keinen Durst, Er läßt sie gehen in den Einöden, läßt für sie Wasser aus dem Felsen rieseln, und spaltet den Felsen, daß Wasser ihm entfließt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Keinen Frieden haben die Ungerechten, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Höret auf mich, ihr Inseln; ihr Volksstämme aus der Ferne, horchet: Jehovah hat mich aus dem Mutterleibe gerufen, und in den Eingeweiden meiner Mutter meines Namens gedacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'Und hat meinen Mund gesetzt zum scharfen Schwert, mich in dem Schatten Seiner Hand versteckt, mich gesetzt zum lauter gemachten Pfeil, hat in Seinem Köcher mich verborgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'Und sprach zu mir: Mein Knecht bist du, Israel, in dir will Ich Mich verklären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Ich aber sprach: Vergeblich habe ich mich abgemüht, umsonst und um nichts habe ich meine Kraft verzehrt? Doch ist mein Recht bei Jehovah und mein Arbeitslohn bei meinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Nun aber spricht Jehovah, Der mich von Mutterleib zum Knecht für Sich gebildet, um Jakob zu Ihm zurückzubringen, und daß Israel sich zu Ihm versammle, und ich verherrlicht werde in Jehovahs Augen, und mein Gott sei meine Stärke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'Und spricht: Noch zu gering ist es, daß du Mir Knecht wirst, die Stämme Jakobs aufzurichten, und die Bewahrten von Israel zurückzubringen. Und Ich werde dich zum Licht der Völkerschaften geben, daß Mein Heil sei bis an das Ende der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'So spricht Jehovah, der Erlöser Israels, sein Heiliger, zu dem von der Seele Verachteten, der den Völkerschaften zum Greuel ist, dem Knechte der Herrscher: Könige werden sehen und aufstehen, Oberste, und vor dir sich niederbeugen wegen Jehovahs, Welcher ist treu, ob dem Heiligen Israels, Der dich erwählte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'So spricht Jehovah: Zur Zeit des Wohlgefallens antworte Ich dir, und am Tage des Heils stehe Ich dir bei und bewahre dich, und gebe dich zum Bunde des Volkes, aufzurichten das Land, die verwüsteten Erbstücke zum Erbe auszuteilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'Zu sprechen zu den Gebundenen: Kommet heraus; zu denen in der Finsternis: Werdet offenbar. Sie sollen weiden auf den Wegen, und auf allen Abhängen ihre Weide haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Sie sollen nicht hungern und nicht dürsten, nicht soll sie Glut, noch Sonne treffen; denn ihr Erbarmer geleitet sie und wird sie zu den Quellgründen der Wasser leiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'Und Ich setze alle Meine Berge zum Weg, und Meine Bahnen werden erhöht sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Siehe, diese kommen von Ferne und siehe, diese von Mitternacht und von dem Meer und jene vom Lande Sinim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Jubelt, ihr Himmel, und frohlocke du Erde, in Jubelgesang brecht aus ihr Berge; denn Jehovah tröstet Sein Volk und erbarmt Sich Seiner Elenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'Und Zion sprach: Jehovah hat mich verlassen und der Herr hat mein vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'Wird auch ein Weib vergessen ihres Kindleins, daß sie sich nicht sollte erbarmen über ihres Leibes Sohn? Ob auch sie vergäßen, so will Ich doch deiner nicht vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Siehe, in die Hände habe Ich dich eingezeichnet; deine Mauern sind beständig vor mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Es eilen deine Söhne; die dich niederrei-ßen und veröden, ziehen aus von dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Erhebe ringsum deine Augen und siehe, sie alle kommen zusammen zu dir. Bei Meinem Leben, spricht Jehovah, wie Geschmeide ziehst du sie an und bindest sie um wie eine Braut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Und deine Öden und deine Verwüstungen und dein umgerissenes Land wird dir dann zu eng, darin zu wohnen, und die dich verschlingen, müssen sich entfernen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Noch sprechen vor deinen Ohren die Söhne deiner Kinderlosigkeit! Zu eng ist mir der Ort, rücke mir hin, auf daß ich wohne!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Und du wirst in deinem Herzen sprechen: Wer hat mir diese gezeugt? - war ich doch kinderlos, vereinsamt, weggeführt und weggetan; und sie - wer hat sie großgezogen? Siehe, war ich doch allein verblieben! Wo waren sie?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'So spricht der Herr Jehovah: Siehe, Ich will nach den Völkerschaften Meine Hand aufheben und zu den Völkern Mein Panier erhöhen, daß sie im Busen deine Söhne hereinbringen, und deine Töchter tragen auf der Schulter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'Und Könige werden deine Wärter sein, und deine Säugammen ihre Fürstinnen. Auf das Antlitz beugen sie sich zur Erde vor dir nieder und lecken auf deiner Füße Staub, daß du wissest, daß Ich Jehovah bin, und die, so auf Mich hoffen, nicht beschämt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Kann man dem Helden sein Genommenes abnehmen? Und kann dem Gerechten der Gefangene entrinnen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Denn also spricht Jehovah: Auch dem Helden soll das Gefangene genommen werden, und des Trotzigen Genommenes entrinnen, und wider deine Haderer will Ich hadern und Ich will deine Söhne retten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'Und deine Bedrücker lasse Ich ihr eigen Fleisch essen, und wie im Moste sie im eigenen Blute trunken machen, auf daß alles Fleisch wisse, daß Ich Jehovah bin, dein Heiland und dein Erlöser, der Gewaltige Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'So spricht Jehovah: Wo ist der Scheidebrief eurer Mutter, mit dem Ich sie entlassen hätte? Oder wer ist von Meinen Gläubigern, an den Ich euch verkauft hätte? Siehe, um eurer Missetaten willen seid ihr verkauft, und wegen eurer Übertretungen ist eure Mutter entlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Warum kam Ich, und kein Mann war da? Rief Ich, und da war keiner, der antwortete? Ist Meine Hand zu kurz zum Lösen, und ist keine Kraft in Mir, daß Ich errettete? Siehe, Ich vertrockne das Meer mit Meinem Drohen, mache zur Wüste Flüsse. Es stinkt ihr Fisch, weil er kein Wasser hat, und stirbt vor Durst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'In Düsterheit kleide Ich die Himmel, mache den Sack zu ihrer Decke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Der Herr Jehovah hat mir eine gelehrige Zunge gegeben, auf daß ich wisse, den Matten mit dem Worte zu erquicken. Er erweckt Morgen nach Morgen, Er erweckt mir das Ohr, zu hören wie ein Lehrling.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Der Herr Jehovah hat mir das Ohr geöffnet und ich war nicht widerspenstig, wich nicht zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Den Schlagenden bot meinen Rükken ich, und meine Wangen den Raufenden, mein Angesicht verbarg ich nicht vor Schande und Speichel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Aber der Herr Jehovah steht mir bei, darum werde ich nicht zuschanden, darum setze ich mein Angesicht wie den Kieselstein, und weiß, daß ich nicht beschämt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Nahe ist, der mich rechtfertigt. Wer will hadern mit mir? Laßt uns zusammen hinstehen. Wer ist mein Gegner im Gericht? er trete herbei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Siehe, der Herr Jehovah steht mir bei. Wer will mich verdammen? Siehe, sie alle veralten wie ein Kleid, die Motte frißt sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Wer unter euch fürchtet Jehovah, hört auf die Stimme Seines Knechtes? Der, so in Finsternissen wandelt ohne Glanz, der vertraue auf Jehovahs Namen und stütze sich auf seinen Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Siehe, ihr alle, die ihr Feuer angefacht, euch mit Funken umgürtet habt, gehet hin in eures Feuers Glut und in die Funken, die ihr brennen lasset. Von Meiner Hand wird euch dies, ihr liegt im Schmerz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Höret auf Mich, ihr, die ihr der Gerechtigkeit nachsetzet, die ihr Jehovah suchet. Blicket auf den Fels, aus dem ihr gehauen seid, und auf die ausgehöhlte Grube, daraus ihr seid gegraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Blicket auf Abraham, euren Vater, und auf Sarah, die mit euch gekreißet; denn ihn, den einen habe Ich gerufen und ihn werde Ich segnen und ihn mehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Denn Jehovah wird Zion trösten, wird trösten alle seine Öden, und machen seine Wüste wie Eden, und seine Einöde wie den Garten Jehovahs; Freude und Fröhlichkeit findet man darin, Bekenntnis und die Stimme des Lobgesangs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Horchet auf Mich, ihr Mein Volk, und nehmt es Mir zu Ohren, ihr, Mein Volksstamm: denn von Mir wird ausgehen das Gesetz, und Mein Gericht will Ich einsetzen zum Licht der Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Nahe ist Meine Gerechtigkeit, Mein Heil zieht aus und Meine Arme richten die Völker; die Inseln hoffen auf Mich und warten auf Meinen Arm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Erhebt eure Augen zum Himmel und blicket auf die Erde unten; denn die Himmel schwinden dahin wie Rauch und wie ein Kleid veraltet die Erde, und die, so auf ihr wohnen, sterben ebenso dahin; Mein Heil aber ist in Ewigkeit und Meine Gerechtigkeit wird nicht zerbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Höret Mir zu, die ihr kennet Gerechtigkeit, du Volk, in dessen Herze Mein Gesetz ist, fürchtet die Schmach des Menschen nicht, und entsetzet euch nicht vor ihren Verhöhnungen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Denn wie das Kleid wird sie die Motte fressen, und fressen wird sie die Schabe wie die Wolle; Meine Gerechtigkeit aber ist in Ewigkeit, und Mein Heil in das Geschlecht der Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Erwache, erwache, ziehe Stärke an, Arm Jehovahs, erwache wie in der Vorzeit Tagen, den Geschlechtern der Ewigkeiten. Bist Du es nicht, Der Rahab zerhauen, den Drachen erschlagen hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Bist Du es nicht, Der das Meer, die Wasser des großen Abgrundes vertrocknete; Der die Tiefen des Meeres zum Wege machte, auf dem die Erlösten hinüberzogen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'Und die Erlösten Jehovahs kehren zurück und kommen gen Zion mit Jubelsang, und ewige Fröhlichkeit auf ihrem Haupt. Freude und Fröhlichkeit erreichen sie, es fliehen Gram und Seufzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Ich, Ich bin euer Tröster. Wer bist du, daß du dich fürchtest vor einem Menschen, der doch stirbt; vor dem Sohne des Menschen, wie Gras dahingegeben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'Und du vergaßest Jehovah, Der dich gemacht, Der die Himmel ausgespannt und die Erde gegründet; und schauderst beständig den ganzen Tag vor dem Grimme des Ängstigers, wenn er bereit ist, zu verderben? Und wo ist nun der Grimm des Ängstigers?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Der herausführt, wird eilen, zu öffnen. Und er wird nicht sterben in der Grube, und es wird ihm nicht an seinem Brot mangeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Denn Ich bin Jehovah, dein Gott, Der das Meer aufregt, daß seine Wogen toben. Jehovah der Heerscharen ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'Und Ich lege Meine Worte in deinen Mund und decke dich im Schatten Meiner Hand, zu pflanzen den Himmel und die Erde zu gründen, und zu Zion zu sprechen: Mein Volk bist du!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Erwecke dich, erwecke dich, stehe auf, Jerusalem, die du getrunken aus Jehovahs Hand den Becher Seines Grimmes; die Hefe des Bechers des Taumelns hast du getrunken, ausgeschlürft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Es leitet sie keiner von all den Söhnen, die sie gebar; und keiner faßt sie bei der Hand von all den Söhnen, die sie großgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Diese zwei sind es, die dir begegnen. Wer hätte Mitleid mit dir? Verheerung und Zerbrechen, und Hunger und das Schwert. Wer möchte dich trösten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Erschöpft liegen deine Söhne an den Häuptern aller Gassen, wie im Netz der Büffel, voll vom Grimm Jehovahs, von dem Drohen deines Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Darum höre doch dies, Elende und Trunkene, aber nicht vom Wein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'So spricht dein Herr Jehovah und dein Gott, Der hadert für Sein Volk: Siehe, Ich nehme von deiner Hand den Taumelbecher, die Hefen des Bechers Meines Grimmes, du sollst ihn nicht noch fürder trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Und gebe ihn in die Hand derer, die dich grämten, die zu deiner Seele sprachen: Beuge dich nieder, daß wir darübergehen, und lege wie die Erde deinen Rücken und wie eine Gasse denen, die vorübergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Erwache, erwache, ziehe deine Stärke an, Zion; ziehe an die Kleider deines Schmukkes, Jerusalem, du Stadt der Heiligkeit, weil nicht fürder mehr eingehen wird in dich, wer Vorhaut hat und unrein ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Schüttle ab den Staub von dir, stehe auf, setze dich, Jerusalem, öffne deines Nackens Bande, du Gefangene, Tochter Zions.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Denn also spricht Jehovah: Umsonst seid ihr verkauft worden, und sollt nicht mit Silber erlöst werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Denn also spricht der Herr Jehovah: Nach Ägypten zog Mein Volk im Anfang hinab, allda sich aufzuhalten als Fremdlinge, und Aschur hat um nichts es niedergedrückt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Und nun, was wird Mir hier, spricht Jehovah, daß Mein Volk umsonst wird weggenommen? Seine Herrscher heulen, sagt Jehovah, und beständig den ganzen Tag wird Mein Name gelästert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Darum soll Mein Volk kennen Meinen Namen, soll es darum an jenem Tage, daß Ich es bin, Der redet: Hier bin Ich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Wie lieblich sind auf den Bergen die Füße des Heilsboten, der Frieden hören läßt, Gutes verkündet, Heil hören läßt, der zu Zion spricht: Dein Gott ist König!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Die Stimme deiner Wächter! allzumal erheben sie die Stimme, sie jubeln, daß Auge an Auge sie sehen, wie Jehovah nach Zion wiederkehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Brechet aus, jubelt zumal, ihr Öden Jerusalems; denn Jehovah tröstet Sein Volk, Er erlöst Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Jehovah hat entblößt den Arm Seiner Heiligkeit den Augen aller Völkerschaften, und alle Enden der Erde sehen das Heil unseres Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Geht weg, geht weg! Zieht aus von dannen, rührt nichts Unreines an! Zieht aus von ihrer Mitte, macht euch lauter, ihr Träger der Geräte Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Ja, nicht in Hast sollt ihr ausziehen, und nicht gehen in Flucht: denn Jehovah geht her vor euch, und Israels Gott schließt euren Zug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Siehe, Mein Knecht wird es klüglich tun, er wird erhöht und wird erhaben und sehr hoch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Wie über dich viele erstaunten, so niedergebeugt wird sein Ansehen sein, mehr denn das eines Mannes, und seine Gestalt mehr denn der Söhne des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'So wird er besprengen viele Völkerschaften, Könige werden ihren Mund vor ihm zudrücken; denn was man ihnen nicht erzählte, sehen sie, und was sie nie gehört, verstehen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Wer hat dem von uns Gehörten geglaubt? Und wem hat sich Jehovahs Arm geoffenbart?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Denn wie ein Schößling stieg Er auf vor Ihm, und wie die Wurzel aus dem dürren Land. Keine Gestalt hat Er und keine Ehre; und wir sahen Ihn, aber da war kein Ansehen, daß wir Sein begehrten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Und Er war verachtet und gemieden unter den Männern, ein Mann der Schmerzen, und bekannt mit Krankheit; und als einen, vor dem man das Gesicht verbirgt, verachteten wir Ihn und achteten Ihn nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Fürwahr, Er trug unsere Krankheiten und lud auf Sich unsere Schmerzen. Wir aber achteten Ihn als einen Geplagten von Gott Geschlagenen und Gepeinigten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'Er ist durchbohrt um unserer Übertretungen willen, zerstoßen ob unseren Missetaten. Die Züchtigung zu unserem Frieden ist auf Ihm, und durch Seine Striemen wird uns Heilung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Wir gingen alle in der Irre, wie die Schafe, wir wandten uns, jeder Mann auf seinen eigenen Weg; und Jehovah ließ auf Ihn stoßen unser aller Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Er ward mißhandelt und gepeinigt, und öffnete nicht Seinen Mund, wie das Lamm, das man zum Schlachten herbeibringt, und wie das Schaf verstummt vor seinen Scherern, öffnete Er nicht Seinen Mund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Aus Haft und vom Gericht ward Er genommen! Und Sein Geschlecht - wer bedachte es, daß Er vom Lande der Lebendigen ward abgeschnitten, daß ob der Übertretung Meines Volkes Er ward geplagt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'Und Er übergab die Ungerechten ihrem Grabe, und die Reichen ihrem Tode; weil Er tat keine Gewalttat, und kein Trug in Seinem Munde war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Jehovah aber wollte Ihn zerstoßen, erkranken lassen; wenn Er zur Schuld setzt Seine Seele, wird Er Samen sehen, verlängern die Tage und Jehovahs Wille durch Seine Hand gelingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Aus Seiner Seele Mühsal sieht Er und wird gesättigt; durch Sein Wissen macht Mein gerechter Knecht viele gerecht, deren Missetaten Er Sich aufgeladen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Darum will Ich Ihm es austeilen unter vielen, und mit den Mächtigen teilt Er die Beute, dafür, daß Er Seine Seele dem Tode bloßgestellt, und zu den Übertretern Sich rechnen ließ, und vieler Sünden trug, und für die Übertreter vermittelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Juble, du Unfruchtbare; die du nicht geboren hast, brich aus in Jubelsang! Laß ertönen, die du nicht gekreißt; denn mehr sind der Söhne der Verwüsteten, denn der Söhne der Vermählten, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Erweitere den Ort deines Zeltes, laß ausspannen die Vorhänge deiner Wohnungen, halte nicht zurück, mache deine Seile lang und dein Pflöcke fest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Denn zur Rechten und zur Linken wirst du hervorbrechen, und Völkerschaften wird dein Same als Erbe besitzen, und verwüstete Städte werden sie bewohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Fürchte dich nicht, denn du wirst nicht beschämt. Und sei nicht verschämt, denn du wirst nicht erröten, denn deiner Jugendzeit Schande wirst du vergessen, und der Schmach deiner Witwenschaft nicht mehr gedenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Denn dein Gemahl ist es, Der dich gemacht, Jehovah der Heerscharen ist Sein Name; und dein Erlöser, der Heilige Israels, der Gott der ganzen Erde wird Er genannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Denn wie ein Weib, verlassen und kummervollen Geistes hat dich Jehovah gerufen und der Jugend Weib; als sie verschmäht war, sprach dein Gott:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Ich habe einen kleinen Augenblick dich verlassen, und mit großen Erbarmungen bringe Ich dich wieder zu Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'In der Entrüstung Überflutung verbarg Ich Mein Angesicht einen Augenblick vor dir, aber mit ewiger Barmherzigkeit erbarme Ich Mich deiner, spricht dein Erlöser, Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Denn dies sind Mir die Wasser Noachs, da Ich schwur, daß Noachs Wasser nicht mehr über die Erde übergehen sollten; so schwöre Ich, daß Ich wider dich nicht mehr entrüstet sein, noch dir drohen will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Denn Berge mögen weichen und die Hügel wanken, doch Meine Barmherzigkeit soll nicht von dir weichen, und Mein Bund des Friedens nicht wanken, spricht dein Erbarmer, Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'Du Elende, vom Sturm Umhergeworfene, Trostlose, siehe, Ich laß lagern in Bleiglanz deine Steine, und gründe dich auf Saphire.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'Und deine Fenster mache Ich von Rubinen, und deine Tore von Karfunkelsteinen, und deine ganze Grenze von Steinen der Lust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'Und alle deine Söhne werden von Jehovah gelehrt, und viel ist der Friede deiner Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Gefestigt wirst du in Gerechtigkeit. Halte fern dich von Bedrückung, denn du sollst nicht fürchten, und vom Entsetzen, denn es naht dir nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Siehe, ob sie sich zusammenrotten wider dich, so ist es nicht von Mir. Wer sich zusammenrottet wider dich, soll über dir fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Siehe, Ich schaffe den Werkmann, der das Feuer der Kohle anfacht, und das Gerät hervorbringt für sein Werk; und Ich schaffe den Verderber zum Zerstören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Allem Gerät, so wider dich gebildet wird, soll es nicht gelingen, und jede Zunge, die wider dich sich aufmacht, wirst du verdammen. Dies ist das Erbe der Knechte Jehovahs, und ihre Gerechtigkeit ist von Mir, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Auf! ein jeder, der dürstet, gehe hin zu den Wassern, und wer Silber nicht hat, gehet hin, kaufet und esset! und gehet, kaufet ohne Silber und ohne Kaufpreis, Wein und Milch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Warum wäget ihr Silber dar für Nicht-Brot und eure Arbeit für etwas, das nicht sättigt? Hört, ja hört auf Mich und esset Gutes, und laben wird sich eure Seele an der Fettigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Neigt euer Ohr und kommt zu Mir, hört, daß eure Seele lebe und Ich mit euch schließe einen Bund der Ewigkeit, die bewährte Barmherzigkeit Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Siehe, zum Zeugen für die Volksstämme gab Ich ihn, zum Führer und Gebieter den Volksstämmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Siehe, rufen wirst du eine Völkerschaft, die du nicht kennst, und eine Völkerschaft, die dich nicht kannte, wird zu dir laufen, um Jehovahs, deines Gottes willen und wegen des Heiligen Israels, weil Er dich verklärt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Suchet nach Jehovah, da Er zu finden ist, rufet Ihn an, da Er nahe ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Der Ungerechte verlasse seinen Weg und der Mann des Unrechts seine Gedanken und kehre zu Jehovah zurück, und Er wird Sich sein erbarmen, und zu unserem Gott, weil Er viel vergibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Denn Meine Gedanken sind nicht eure Gedanken und eure Wege sind nicht Meine Wege, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Denn die Himmel sind höher denn die Erde, so sind Meine Wege höher denn eure Wege, und Meine Gedanken denn eure Gedanken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Denn wie der Platzregen und der Schnee herab vom Himmel kommt und nicht dahin zurückkehrt, vielmehr die Erde netzt und sie hervorbringen und sprossen läßt, und Samen gibt dem, der sät, und Brot dem, der da ißt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'So wird Mein Wort sein, das von Meinem Mund ausgeht. Nicht kehrt es leer zu Mir zurück, sondern tut das, woran Ich Lust habe, und läßt gelingen, wozu Ich es gesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Denn ihr zieht aus in Fröhlichkeit und werdet geleitet im Frieden; die Berge und die Hügel brechen in Jubelsang aus vor euch, und alle Bäume des Gefildes klatschen mit der Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Statt des Dorngebüsches steigt auf die Tanne, statt des Stechdorns steigt auf die Myrte und soll für Jehovah zum Namen und zum ewigen Zeichen sein, das nicht wird ausgerottet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'So spricht Jehovah: Haltet das Recht und tut Gerechtigkeit; denn nahe ist Mein Heil zu kommen, und sich zu offenbaren Meine Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Gesegnet der Mann, der solches tut, und des Menschen Sohn, der daran festhält; der den Sabbath hält, auf daß er ihn nicht entweihe; der Seine Hand hält, auf daß sie kein Böses tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Und der Sohn des Auslandes, der Jehovah anhängt, sage nicht: Jehovah scheidet mich von Seinem Volk, nicht soll der Verschnittene sagen: Siehe, ich bin ein trocken Holz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Denn also spricht Jehovah zu den Verschnittenen: Die, so Meine Sabbathe halten, und erwählen, woran Ich Lust habe, und meinen Bund festhalten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'So will Ich ihnen in Meinem Haus und in Meinen Mauern eine Stätte und einen Namen geben, besser als Söhne und als Töchter; einen ewigen Namen will Ich ihm geben, der nicht soll ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Und die Söhne des Auslandes, die Jehovah anhangen, daß sie Ihm Dienst tun und Jehovahs Namen lieben, daß sie Ihm Knechte seien, sie alle, die den Sabbath halten, daß sie ihn nicht entweihen, und die fest an Meinem Bunde halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'So will Ich sie bringen zum Berg Meiner Heiligkeit und lassen fröhlich sein in Meinem Bethaus, ihre Brandopfer und Schlachtopfer auf Meinem Altare sollen wohlgefällig sein: denn Mein Haus soll man ein Bethaus nennen für alle Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Der Herr Jehovah spricht, Der die Verstoßenen Israels zusammenbringt: Ich will noch mehr zu ihm zusammenbringen, zu seinen Zusammengebrachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Alles wilde Tier des Feldes komme zum Fraß, alles wilde Tier des Waldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'All seine Wächter sind blind, sie alle wissen nichts, sie alle sind stumme Hunde, die nicht bellen können, sie schauen umher, sie liegen, sie lieben den Schlummer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'Und die Hunde sind von verstockter Seele, wissen nichts von Sättigung, und sie, die Hirten, wissen nichts von Einsicht, sie alle wenden sich auf ihren eigenen Weg, jeder Man von seinem Ende, seinem Gewinne zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, 'Kommt, Ich will Wein nehmen und zechen lasset uns in starkem Getränk, und morgen soll es sein wie an diesem Tage, in sehr großem Überfluß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Der Gerechte vergeht, und niemand ist, der es sich zu Herzen nehme, und Männer der Heiligkeit werden weggerafft, ohne daß man einsieht, daß vor dem Bösen der Gerechte wird hingerafft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'Es geht ein im Frieden, es ruht auf seinem Lager, wer geradeaus wandelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Und ihr, nahet euch hierher, ihr Söhne der Zeichendeuterin, ihr Same des Ehebrechers und ihrer, die gebuhlt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'An wem labet ihr euch? Ob wem sperrt ihr weit auf den Mund, recket lang die Zunge aus? Seid ihr nicht Kinder der Übertretung, der Lüge Samen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'Die ihr euch erhitzt für die Götzen unter jedem grünen Baum, die ihr schlachtet die Kinder in die Bäche unter den Klüften der Felsenklippen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Im Glatten des Bachtales ist dein Teil, sie, sie sind dein Los, auch hast du ihnen ein Trankopfer ausgegossen und ein Speiseopfer dargebracht. Soll Ich Mich dessen trösten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Auf hohem und erhabenem Berg setzest du dein Lager, auch steigst du dort hinauf ein Schlachtopfer zu opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'Und hinter Tür und Pfosten setzest du dein Andenken. Denn hinweg von Mir deckst du dich auf und steigst hinauf, du machst dein Lager weit, und schließest ab mit ihnen, deren Lager du liebst, so du eine Hand erschaust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'Du bringst eine Spende dem König in Öl und mehrst deine Würzen, und sendest deine Botschafter in die Ferne und erniedrigst dich zur Hölle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Du bist ermüdet von deinem vielen Wege; du sprichst nicht: Es ist verzweifelt. Du findest das Leben deiner Hand, darum erkrankst du nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'Und vor wem bist du besorgt und fürchtest du dich, daß du falsch bist? Und du gedenkst Meiner nicht, du nimmst dir es nicht zu Herzen. Ich schweige, und von Ewigkeit her, und Mich fürchtest du nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Ich will deine Gerechtigkeit ansagen und deine Gemächte, sie werden dich nichts nützen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Wenn du schreist, werden deine Zusammengekommenen dich erretten? Sie alle erhebt ein Wind und nimmt fort ein Hauch. Wer aber auf Mich sich verläßt, der erbt das Land, und besitzt erblich den Berg Meiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'Und Er spricht: Bahnet, bahnet, räumt den Weg, hebt weg allen Anstoß aus dem Wege Meines Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Denn also spricht der Hohe und Erhabene, Der wohnt immerfort, und der Heilige ist Sein Name: Hoch und heilig wohne Ich und bei dem zerknirschten und erniedrigten Geiste, daß Ich belebe den Geist der Niedrigen und belebe das Herz der Zerknirschten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Denn Ich will nicht ewiglich hadern und nicht entrüstet sein immerdar. Denn der Geist könnte vor Mir verzagen, und die Atmenden habe Ich gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Ob der Missetat seiner Gewinnsucht war Ich entrüstet, und schlug ihn, verbarg Mich und war entrüstet; er aber ging abwendig auf dem Wege seines Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Ich sah seine Wege und heilte ihn, und führte ihn und gewährte Tröstungen ihm und seinen Trauernden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Ich schaffe Frucht der Lippen. Friede, Friede dem Fernen und dem Nahen, spricht Jehovah, und Ich heile ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Aber die Ungerechten sind wie ein aufgewühltes Meer, das sich zu beruhigen nicht vermag, und seine Wasser wühlen Schmutz und Kot auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Die Ungerechten haben keinen Frieden, spricht mein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Rufe aus der Kehle, halt nicht zurück; wie eine Posaune erhöhe deine Stimme und sage an Meinem Volke seine Übertretungen und Jakobs Hause seine Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Und sie suchen nach Mir Tag für Tag und haben Lust an der Kenntnis Meiner Wege, als eine Völkerschaft, die Gerechtigkeit tut, und ihres Gottes Gericht nicht verläßt; sie fragen Mich um die Rechte der Gerechtigkeit, sie haben Lust an der Nähe Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, 'Warum fasten wir, und Du siehst es nicht, demütigen unsere Seele, und Du weißt es nicht? Siehe, am Tage, da ihr fastet, findet ihr Lust und erpresset alle eure Schmerzenswerke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Siehe, zum Hader und Zwist fastet ihr, und daß mit Fäusten der Ungerechtigkeit ihr schlaget. Nicht fastet ihr, wie an diesem Tag, daß eure Stimme in der Höhe sollte gehört werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Ist das ein Fasten, wie Ich es erwähle, ein Tag, daß seine Seele demütige der Mensch, daß er den Kopf hänge wie die Binse und sich in Sack und Asche bette? Nennst du das ein Fasten und einen Tag des Wohlgefallens für Jehovah?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Ist nicht das ein Fasten, wie Ich es erwähle, die Bande der Ungerechtigkeit zu lösen, die Fesseln des Joches aufzumachen, frei zu entsenden die Zerschlagenen und jedes Joch abzureißen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Ist es nicht, daß du brichst dein Brot dem Hungrigen, und die Elenden, die umherirren, hineinbringst in dein Haus, den, so du nackend siehst bedeckst und vor deinem Fleische dich nicht verbirgst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Dann bricht dein Licht an wie das Morgenrot und eilends sproßt auf deine Heilung. Und deine Gerechtigkeit zieht vor dir her, deine Nachhut ist Jehovahs Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Dann rufst du, und Jehovah antwortet; du schreist auf, und Er spricht: Hier bin Ich! Wenn du das Jochholz wegnimmst aus deiner Mitte, das Ausstrecken des Fingers und das unrecht Reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'Reichst du dem Hungrigen deine Seele dar und sättigst die Seele des Elenden, so geht dein Licht auf in der Finsternis, und wie Mittagshelle wird deine Dunkelheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'Und führen wird Jehovah dich beständig, und deine Seele in den dürren Steppen sättigen und rüstig machen dein Gebein, und wie ein bewässerter Garten wirst du sein und wie ein Ausfluß der Wasser, dessen Wasser nie täuschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'Und sie werden bauen aus dir die Öden der Urzeit, die Gründe von Geschlecht und Geschlecht sollst du aufrichten, und nennen wird man dich: der den Durchbruch verzäunt und die Steige zurückbringt, daß man wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'So deinen Fuß du von dem Sabbath zurückkehrest, vom Tun deines Willens, am Tage Meiner Heiligkeit, und den Sabbath nennst ein Labsal dem Heiligen Jehovahs, und es verherrlichst, indem du nicht nach deinen Wegen tust, noch deine Lust findest und ein Wort redest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'Dann labst du dich an Jehovah, und Ich lasse dich über der Erde Höhen dahinfahren, und du sollst essen das Erbe Jakobs, deines Vaters; denn der Mund Jehovahs hat es geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Siehe, Jehovahs Hand ist nicht zu kurz, daß Er nicht retten könnte, und Sein Ohr nicht schwer, daß er nicht hörete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'Sondern eure Missetaten scheiden zwischen euch und eurem Gott, und eure Sünden verbergen das Angesicht von euch, daß Er nicht hörte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Denn eure Hände sind befleckt mit Blut und eure Finger mit Missetat. Eure Lippen reden Lüge, eure Zunge sinnt Verkehrtheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Keiner ruft nach Gerechtigkeit, keiner richtet nach Wahrheit. Auf Leeres vertrauen sie und reden Eitles, sie empfangen Mühsal und gebären Unrecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Eier von Basilisken brüten sie aus und weben das Gewebe von Spinnen. Wer ißt von ihren Eiern, stirbt. Und drückt man sie zusammen, wird eine Natter ausgebrütet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Nicht wird zum Kleide ihr Gewebe, und man kann mit ihrem Machwerk sich nicht decken; ihr Tun ist ein Tun des Unrechts, und das Werk der Gewalttat ist in ihren Händen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Nach Bösem laufen ihre Füße, und unschuldig Blut zu vergießen, eilen sie. Ihre Gedanken sind Gedanken des Unrechts, Verheerung und Zerbrechen ist auf ihren Bahnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Den Weg des Friedens kennen sie nicht, und kein Gericht ist auf ihren Geleisen. Ihre Steige machen sie sich krumm; wer sie betritt, kennt keinen Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Darum ist fern von uns das Gericht und die Gerechtigkeit erreicht uns nicht. Wir hoffen auf das Licht und siehe, da ist Finsternis; auf Glanz, wir wandeln in Dunkelheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Wir tasten wie die Blinden an der Wand und wie die, so keine Augen haben, tasten wir. In der Mittagshelle straucheln wir, wie in der Dämmerung, wir sind wie Tote unter den Lebendigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Wir brummen wie die Bären allesamt, und wie die Tauben girren wir, wir hoffen auf Gericht und es ist nicht da, und auf Heil, es ist fern von uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Denn viel sind unsere Übertretungen vor Dir, und unsere Sünden antworten wider uns; denn unsere Übertretungen sind bei uns, und unsere Missetaten kennen wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'Wir fielen ab und verleugneten Jehovah und wichen zurück hinter sich von unserem Gott, wir redeten von Plackerei und von Abfall, empfingen und sannen von Herzen Worte der Lüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Und das Recht wich zurück hinter sich und Gerechtigkeit stand von ferne; denn auf der Straße strauchelte die Wahrheit und Richtigkeit vermag nicht herbeizukommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'Und es geschah, daß es an Wahrheit fehlte, und ausgebeutet wurde, wer vom Bösen abwich, und Jehovah sah es, und es war böse in Seinen Augen, daß kein Gericht da war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'Und Er sah, daß kein Mann da war, und Er erstaunte, daß kein Vermittler da war. Und es rettete Sein Arm Ihm und Seine Gerechtigkeit ward Ihm Anhalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'Und Er zog wie einen Panzer an Gerechtigkeit und auf Sein Haupt den Helm des Heils; und Er zog als Anzug der Rache Kleider an, und umhüllte Sich mit Eifer wie mit einem Oberkleid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Wie zur Erwiderung, wie damit Er vergelte Seinen Drängern den Grimm, Seinen Feinden zur Erwiderung wird Er den Inseln die Erwiderung vergelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'Und die vom Abend fürchten Jehovahs Namen und die vom Aufgang der Sonne Seine Herrlichkeit; denn Er wird kommen wie ein eingeengter Fluß, Jehovahs Geist wird erheben in ihm das Panier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'Und für Zijon wird kommen ein Erlöser und für die in Jakob, die umkehren von der Übertretung, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Und Ich - das ist Mein Bund mit ihnen, spricht Jehovah. Mein Geist, der auf dir ist, und Meine Worte, die Ich in deinen Mund gelegt, sie sollen von deinem Munde nicht weichen und von dem Munde deines Samens und von dem Munde des Samens deines Samens, spricht Jehovah, von nun an und bis in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Mache dich auf, werde Licht; denn dein Licht kommt, und Jehovahs Herrlichkeit ist aufgegangen über dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Denn siehe, Finsternis bedeckt die Erde, und Dunkel die Volksstämme; aber über dir geht auf Jehovah, und Seine Herrlichkeit erscheint über dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'Und Völkerschaften werden zu deinem Lichte wandeln und Könige zum Glanze deines Aufgangs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Erhebe ringsum deine Augen, und siehe, sie alle kommen zusammen, sie kommen zu dir, von ferne werden deine Söhne kommen und deine Töchter werden zur Seite von Wärterinnen herbeigetragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Dann wirst du es sehen, und herbeiströmen und schauern wird dein Herz und sich erweitern, denn zu dir wird umkehren des Meeres Menge, und die Streitmacht der Völkerschaften zu dir kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Bedecken wird dich der Kamele Unzahl, Midjans und Ephahs Dromedare; sie alle kommen von Scheba, Gold und Weihrauch tragen sie und verkünden das Lob Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Zu dir kommen zusammen alle Herden Kedars, dir sind zu Dienste die Widder Nebajoths und werden zum Wohlgefallen aufsteigen auf Meinem Altar, und verklären will Ich Meines Schmuckes Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Wer sind diese, die daher wie eine dichte Wolke fliegen, und wie die Tauben zu ihren Fenstern?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Denn auf Mich hoffen die Inseln, und zuerst die Schiffe von Tharschisch, zu bringen deine Söhne von ferne, ihr Silber und ihr Gold mit ihnen, dem Namen Jehovahs, deines Gottes, und dem Heiligen Israels; daß Er dich hat verklärt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'Und die Söhne des Auslandes werden deine Mauern bauen, und ihre Könige dir zu Dienste sein, denn in Meiner Entrüstung habe Ich dich geschlagen, und in Meinem Wohlgefallen deiner Mich erbarmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'Und geöffnet sind deine Tore beständig, bei Tag und bei Nacht werden sie nicht geschlossen, damit man zu dir bringe der Völkerschaften Streitmacht, und ihre Könige werden herzugeleitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Denn die Völkerschaften und das Königreich, die dir nicht dienen, vergehen, und verödet werden die Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Die Herrlichkeit des Libanon wird zu dir kommen; Tanne, Kiefer und Buchsbaum allzumal, den Ort Meines Heiligtums zu schmücken, und den Ort Meiner Füße will Ich verherrlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'Und zu dir kommen niedergebeugt die Söhne derer, die dich niedergedrückt, und sie beugen sich nieder zu den Sohlen deiner Füße, alle, die dich gelästert; und nennen werden sie dich die Stadt Jehovahs, das Zion des Heiligen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'Statt daß du warst verlassen und gehaßt, daß niemand durchging, will Ich dich machen zum ewigen Stolze, zur Freude von Geschlecht zu Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Und die Milch der Völkerschaften wirst du saugen, und der Könige Brust wirst du saugen, daß du wissest, daß Ich, Jehovah, bin dein Heiland und dein Erlöser, der Gewaltige Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Statt Erzes bringe Ich Gold, und statt Eisens bringe Ich Silber, und statt des Holzes Erz und statt der Steine Eisen, und Ich will zu deiner Obrigkeit Frieden setzten, und zu deinen Fronvögten Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Nicht wird man mehr in deinem Lande von Gewalttat hören, in deinen Grenzen von Verheerung und vom Zerbrechen, und deine Mauern wirst du nennen Heil und deine Tore Lob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Nicht wird die Sonne mehr bei Tag dir zum Lichte sein, noch zum Glanz der Mond dir scheinen; sondern Jehovah wird dir sein ein ewig Licht, und dein Gott zu deinem Schmuck.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Nicht wird mehr deine Sonne untergehen, und dein Mond sich nicht zurückziehen; denn Jehovah wird dir sein ein Licht der Ewigkeit, und die Tage deiner Trauer sind vollbracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'Und all dein Volk werden Gerechte sein, ewiglich sollen sie das Land erblich besitzen, ein Reis meiner Pflanzungen sind sie, ein Werk von Meinen Händen, Mich zu verklären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Der Kleine soll zu Tausend und der Geringe zur zahlreichen Völkerschaft werden. Ich, Jehovah, werde es zu seiner Zeit beschleunigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Der Geist des Herrn Jehovah ist auf Mir, weil Jehovah Mich gesalbt, den Elenden Botschaft zu bringen, gesandt Mich, zu verbinden die gebrochenen Herzens sind, Freilassung auszurufen für die Gefangenen und für die Gebundenen Entfesselung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'Ein Jahr des Wohlgefallens auszurufen für Jehovah und einen Tag der Rache für unseren Gott, zu trösten alle Trauernden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'Den Trauernden in Zijon zu schaffen, ihnen zu geben Kopfschmuck statt Asche, Öl der Freude statt Trauer, ein Feierkleid des Lobes statt trüben Geistes, und nennen wird man sie Eichen der Gerechtigkeit, Jehovahs Pflanzung zur Verklärung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'Und aufbauen werden sie die Öden der Urzeit, aufrichten die früheren Verwüstungen, und erneuern die öden Städte, die Verwüstungen von Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'Und Fremde werden stehen und eure Herde weiden, und des Auslandes Söhne eure Ackerleute und Winzer sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Und ihr werdet Jehovahs Priester genannt. Diener unseres Gottes wird man euch heißen. Ihr werdet das Vermögen der Völkerschaften essen, und euch brüsten ihrer Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Statt eurer Scham wird euch Zwiefältiges; und für Schande sollen sie jubeln in ihrem Teil; darum sollen sie Zwiefältiges erblich besitzen in ihrem Lande; ewige Fröhlichkeit wird ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Denn Ich, Jehovah, liebe das Recht, hasse das durch Verkehrtheit Entrissene und gebe in Wahrheit ihnen den Arbeitslohn und schlie-ße einen ewigen Bund mit ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'Und ihr Same soll kund werden unter den Völkerschaften, und ihre Sprößlinge inmitten der Völker, daß sie erkennen, alle die sie erkennen, daß sie der Same sind, den Jehovah segnete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Mit Freude will ich mich freuen in Jehovah, meine Seele wird frohlocken in meinem Gott; denn mit Kleidern des Heils hat Er mich angetan, und mich umhüllt mit dem Mantel der Gerechtigkeit; wie ein Bräutigam sich priesterlich ziert mit dem Kopfschmuck und wie die Braut prangt mit ihrem Gerät.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Denn wie die Erde ihre Sprossen hervorbringt, und wie der Garten sein Gesämâ¬Ü läßt sprossen, so läßt der Herr Jehovah sprossen Gerechtigkeit und Lob vor allen Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Ob Zijon schweige Ich nicht, und ob Jerusalem raste Ich nicht, bis wie ein Glanz ausgeht ihre Gerechtigkeit, und wie eine Fackel brennt ihr Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'Und sehen werden die Völkerschaften deine Gerechtigkeit, und deine Herrlichkeit alle Könige, und nennen wird man dich mit einem neuen Namen, den Jehovahs Mund bestimmen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'Und eine Krone des Schmuckes wirst du sein in Jehovahs Hand, und ein Kopfbund des Königtums in der Hand deines Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Man wird zu dir nicht mehr sagen: Verlassene, und von deinem Lande nicht mehr sagen: die Verwüstung! sondern Meine Lust an ihr wird man dich nennen, und dein Land: Vermählet, denn Seine Lust hat Jehovah an dir, und dein Land wird vermählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Denn wie der Jüngling sich vermählt der Jungfrau, vermählen deine Söhne sich mit dir; und mit der Freude eines Bräutigams über die Braut, freuet sich über dich dein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Auf deine Mauern, Jerusalem, habe Ich Hüter bestellt den ganzen Tag und die ganze Nacht. Nimmer werden sie schweigen, Jehovahs gedenkend: Ihr sollt nicht stille sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'Und gebt Ihm keine Stille, bis Er bereitet und bis Er setzt Jerusalem zum Lob auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Geschworen hat Jehovah bei Seiner Rechten und bei dem Arme Seiner Stärke: Ich gebe fortan nicht mehr dein Korn deinen Feinden zu essen, und des Auslandes Söhne sollen deinen Most nicht trinken, darum du dich bemühtest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Sondern, die es einsammeln, sollen es essen und Jehovah loben, und die ihn lesen, die sollen trinken ihn in den Vorhöfen Meiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Ziehet durch, ziehet durch die Tore, räumet dem Volk den Weg; bahnet, bahnet die Bahn, säubert sie von Steinen, erhöht das Panier über die Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Siehe, Jehovah läßt es hören bis an das Ende der Erde: Saget der Tochter Zions: Siehe, dein Heil kommt. Siehe, Sein Lohn ist mit Ihm und vor Ihm ist Sein Arbeitslohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'Und nennen wird man sie das Volk der Heiligkeit, die Erlösten Jehovahs, und dich wird man nennen die gesuchte Stadt, die nicht wird verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Wer ist Der, so von Edom kommt in bespritzten Kleidern, von Bozrah, Der geehrt ist in Seinem Anzug, einherschreitet in Seiner vielen Kraft? Ich, Der da rede in Gerechtigkeit, groß im Retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Warum ist es an Deinem Anzuge rot? Und Deine Kleider wie eines, der die Kelter tritt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Das Kelterfaß trat Ich allein und von den Völkern war kein Mann mit Mir, und Ich trat sie in Meinem Zorn und zerstampfte sie in Meinem Grimm, und ihr Sieg ist gespritzt auf Meine Kleider, und all Meinen Anzug befleckte Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Denn der Tag der Rache ist in Meinem Herzen; und das Jahr Meiner Erlösten ist gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'Und Ich blickte, und da war kein Beistand, und Ich staunte, und es war da kein Anhalt. Und Mein Arm ward Mir zum Heil, und Mein Grimm, der Mir ward zum Anhalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'Und Ich zertrat die Völker in Meinem Zorn und machte sie trunken in Meinem Grimm, und brachte zur Erde herab ihren Sieg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Jehovahs Barmherzigkeit gedenke ich, des Lobes Jehovahs, nach allem, das uns Jehovah erwiesen hat, und das viele Gute an dem Haus Israels, das Er nach Seinen Erbarmungen und Seiner vielen Barmherzigkeit hat erwiesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Und Er sprach: Fürwahr, Mein Volk sind sie, sind Söhne, die nicht lügen; und Er ward ihnen zum Heiland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'In aller ihrer Drangsal ward Er bedrängt, und der Engel Seines Angesichtes rettete sie. Ob Seiner Liebe und Seines Mitleides erlöste Er sie, und hob sie empor und trug sie alle Tage der Urzeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Aber sie waren widerspenstig und betrübten den Geist Seiner Heiligkeit; und Er ward ihnen gewandelt zum Feind, Er Selber stritt wider sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Und Er gedachte der Ewigkeit Tage, an Mose, Sein Volk. Wo ist Er, Der sie aus dem Meer heraufgeführt, mit dem Hirten Seiner Herde, wo ist Er, Der den Geist Seiner Heiligkeit in ihre Mitte hat gelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'Der gehen ließ zur Rechten Moses Seinen Arm des Ruhms, Der vor ihnen die Wasser spaltete, um einen Namen für Sich zu machen in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'Der durch die Abgründe sie gehen ließ, wie das Roß in der Wüste; sie strauchelten nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Wie in das Tal das Vieh herniedersteigt, brachte sie Jehovahs Geist zur Ruhe. Also geleitetest Du dein Volk, um Dir einen Namen des Ruhmes zu machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Blicke vom Himmel, und siehe aus dem Wohnort Deiner Heiligkeit und Deines Schmuckes. Wo ist Dein Eifer und Deine Macht? Die Regung Deiner Eingeweide und Deine Erbarmungen gegen mich sind anhaltend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Denn Du bist unser Vater; denn Abraham weiß nicht von uns und Israel erkennt uns nicht. Du, Jehovah, bist unser Vater, unser Erlöser; von Ewigkeit ist Dein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Warum Jehovah, ließest Du uns von deinen Wegen irren, verhärten unser Herz, daß wir Dich nicht fürchteten? Kehre zurück um Deiner Knechte willen, um der Stämme Deines Erbes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Um ein Winziges, so hätten sie das Volk Deiner Heiligkeit besessen, da zertraten unsere Dränger Dein Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Wir sind, als ob Du von Ewigkeit her nicht über uns geherrscht, als ob wir nicht nach Deinem Namen genannt wären. O, daß Du die Himmel zerrissest, herniederstiegest, daß die Berge vor Deinem Angesicht zerrieselten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'Wie Feuer Reisig entzündet, Wasser vom Feuer aufwallt, so müssest Deinen Namen Du Deinen Drängern kundtun, daß die Völkerschaften zittern vor Deinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, 'Daß Furchtbares Du tätest, das wir nicht hofften; daß Du herabführest und Berge vor Dir zerrieselten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 'Und was man von Ewigkeit nicht hat gehört, noch mit dem Ohr vernommen, kein Auge gesehen, außer Dir, o Gott, wird getan für die, so auf Dich warten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Du begegnest dem, der freudig ist und Gerechtigkeit tut, der auf Deinen Wegen Deiner gedenkt. Siehe, Du warst entrüstet, daß wir sündigten darin eine Ewigkeit: laß uns geholfen werden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Und wir allesamt sind wie unrein, wie ein Kleid der Besudelung ist all unsere Gerechtigkeit, und wir alle fallen ab, wie das Blatt, und unsere Missetaten tragen uns wie der Wind dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'Und niemand rief Deinen Namen an, erregte sich, Dich festzuhalten; denn Du verbargst vor uns Dein Angesicht, und ließest uns zerfließen durch die Gewalt unserer Missetaten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'Und nun, Jehovah, Du bist unser Vater, wir sind der Ton und Du bist unser Töpfer, und wir alle sind Deiner Hände Werk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Jehovah, sei nicht zu sehr entrüstet, gedenke nicht immerfort der Missetat. Siehe, blicke her, Dein Volk sind wir ja alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Die Städte Deiner Heiligkeit sind Wüste, Zion ist Wüste, Jerusalem eine Verwüstung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Das Haus unserer Heiligkeit und unser Schmuck, wo Dich unsere Väter lobten, ist mit Feuer verbrannt und all unser Begehr, das ward zur Öde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Willst Du bei solchem an Dich halten, Jehovah? Schweigst Du und demütigst Du uns so sehr?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Ich werde erfragt von denen, die nicht gefragt haben, Ich werde gefunden von denen, so nicht nach Mir gesucht. Ich spreche: Hier bin Ich! Hier bin Ich! zu einer Völkerschaft, die nicht nach Meinem Namen ist genannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Den ganzen Tag breite Ich Meine Hände aus nach einem störrischen Volk, das auf einem nicht guten Weg wandelt nach seinen Gedanken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'Ein Volk, das Mich reizt, ist beständig vor Meinem Angesicht. Sie opfern in den Gärten und räuchern auf den Ziegelsteinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'Sie sitzen in den Gräbern und übernachten in abgeschlossenen Orten. Sie essen Fleisch des Schweigens, und Stücke des Abscheus sind in ihren Gefäßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'Sie sprechen: Bleibe für Dich!, tritt nicht her zu mir, denn ich bin zu heilig für Dich. Solche sind ein Rauch in Meiner Nase, ein Feuer, das den ganzen Tag lodert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Siehe, geschrieben ist es vor Mir: Ich schweige nicht, sondern vergelte, und vergelte in ihren Busen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'Eure Missetaten und die Missetaten eurer Väter allzumal, spricht Jehovah, die auf den Bergen räucherten und Mich schmähten auf den Hügeln; daß Ich maß ihren früheren Arbeitslohn in ihren Busen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'So spricht Jehovah: Wie Most in der Traube wird gefunden und man spricht: Verdirb sie nicht, weil Segen darin ist, so will Ich tun, um Meiner Knechte willen, daß Ich nicht alles will verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'Und laß von Jakob ausgehen einen Samen, und von Jehudah den, der erblich besitze Meine Berge; und erblich besitzen sollen es Meine Auserwählten, und Meine Knechte allda wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'Und Scharon soll der Schafherde zur Hürde und der Talgrund Achor den Rindern zur Lagerung werden für Mein Volk, das nach Mir hat gefragt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Ihr aber, die ihr Jehovah verlassen, die ihr vergessen habt den Berg Meiner Heiligkeit, die ihr den Tisch zurichtet für Gad und dem Meni ein Trankopfer füllet:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'So will Ich euch berechnen für das Schwert, daß ihr euch alle zur Schlachtung beugt, weil Ich rief und ihr nicht antwortetet, Ich redete und ihr nicht hörtet; und ihr tut, was böse ist in Meinen Augen, und woran Ich keine Lust habe, das wählet ihr aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Darum spricht so der Herr Jehovah: Siehe, Meine Knechte sollen essen und ihr sollt hungern; siehe, Meine Knechte sollen trinken und ihr sollt dürsten; siehe, Meine Knechte sollen fröhlich sein und ihr sollt euch schämen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'Siehe, Meine Knechte sollen vor Wohlsein des Herzens jubeln, ihr aber schreien vor Herzeleid und heulen vor Zerbrochenheit des Geistes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'Und euren Namen sollt ihr Meinen Auserwählten zum Schwur hinterlassen, dich aber wird der Herr Jehovah töten, und Seine Knechte mit einem anderen Namen nennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'So daß, wer sich im Lande segnet, sich segne in dem Gott der Wahrheit, und wer im Lande schwört, bei dem Gott der Wahrheit schwören wird; denn vergessen sind die früheren Drangsale und verborgen vor Meinen Augen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Denn siehe, Ich schaffe neue Himmel und eine neue Erde, und der früheren wird man nicht mehr gedenken, noch werden sie ins Herz aufsteigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Sondern freuen sollen sie sich und frohlocken fort und fort über dem, was Ich schaffe. Denn siehe, Jerusalem will Ich zum Frohlocken erschaffen und sein Volk zur Freude.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'Und Ich will frohlocken ob Jerusalems, und ob Meines Volkes Mich freuen; und nicht soll man mehr hören in ihr die Stimme des Weinens, noch die Stimme des Geschreis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Nicht wird von dort ein Kindlein der Tage sein, noch ein Alter, der seine Tage nicht erfüllt; denn der Junge wird sterben hundert Jahre alt, und der Sünder wird verflucht werden hundert Jahre alt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'Und sie werden Häuser bauen und darin wohnen, und Weinberge pflanzen und essen ihre Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Sie werden nicht bauen und ein anderer darin wohnen, nicht pflanzen, und ein anderer essen; denn Meines Volkes Tage werden wie die Tage des Baumes sein, und ihrer Hände Werk werden altern lassen Meine Auserwählte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Nicht sollen sie vergeblich sich bemühen und nicht zeugen für die Bestürzung; denn ein Same der Gesegneten Jehovahs sind sie, und ihre Sprößlinge mit ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'Und wird geschehen, daß, ehe sie rufen, Ich antworte; noch reden sie, da höre Ich es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Wolf und Lamm sollen weiden als eines, und der Löwe soll Stroh fressen wie das Rind, und der Schlange Brot soll der Staub sein. Sie sollen nichts Böses tun und nichts verderben auf dem ganzen Berg Meiner Heiligkeit, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Also spricht Jehovah: Die Himmel sind Mein Thron, und die Erde Meiner Füße Schemel. Was für ein Haus wollt ihr Mir denn bauen, und welchen Ort zu Meiner Ruhe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Und alles dies hat Meine Hand gemacht, so daß das alles geworden ist, spricht Jehovah. Und Ich blicke auf diesen, auf den Elenden, und auf den, der zerschlagenen Geistes ist, und der erzittert ob Meinem Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Wer einen Ochsen schlachtet, ist, als erschlüge er einen Mann; wer ein Schaf opfert, als bräche er einem Hunde das Genick, wer ein Speiseopfer als einer, der Blut der Schweine darbringt, wer Weihrauch anzündet, wie wer das Unrecht segnet; wie ihre eigenen Wege sie erwählten, und an ihren Abscheulichkeiten ihre Seele Lust hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'So wähle auch Ich Mir ihre Mißhandlung aus, und laß ihr Bangen kommen über sie; weil Ich rief und niemand antwortete, Ich redete und niemand hörte, und sie taten, was böse war in Meinen Augen, und wählten zu tun, woran Ich keine Lust hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Höret Jehovahs Wort, ihr, die ihr erzittert vor Seinem Wort: Es sprachen eure Brüder, die euch hassen, euch ob Meines Namens ausscheiden: Jehovah verherrliche Sich, daß wir eure Fröhlichkeit sehen; aber sie sollen beschämt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Man hört die Stimme des Tosens aus der Stadt, vom Tempel eine Stimme, Jehovahs Stimme, Der Vergeltung erweist Seinen Feinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Ehe sie kreißt, gebiert sie; ehe sie in Geburtsnöten kommt, ist sie eines Männlichen entbunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Wer hat solches gehört; wer solches gesehen? Hat ein Land an einem Tag gekreißt eine Völkerschaft, geboren mit einem Mal, wie Zijon mit seinen Söhnen gekreißt und sie geboren hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Und sollte Ich brechen und nicht gebären lassen, spricht Jehovah, und sollte Ich, Der gebären ließ, verschließen? spricht dein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Seid fröhlich mit Jerusalem, und frohlokket in ihr, ihr alle, die ihr es liebt. Freuet euch mit Freude mit ihr, die ihr über sie getrauert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'Denn ihr sollt saugen und euch sättigen aus der Brust ihrer Tröstungen, denn ihr sollt ausdrücken und euch erlaben an der Pracht ihrer Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Denn also spricht Jehovah: Siehe, Ich breite Frieden wie einen Strom aus auf sie, und wie einen überflutenden Bach die Herrlichkeit der Völkerschaften, daß ihr sauget. Auf der Seite wird man euch tragen und werdet euch ergötzen auf den Knien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Wie einen seine Mutter tröstet, so will Ich euch trösten, und ihr sollt getröstet werden in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'Und ihr werdet es sehen, und euer Herz wird sich freuen, und sprossen werden eure Gebeine wie junges Kraut; und kund wird Jehovahs Hand an Seinen Knechten, und wider Seine Feinde ist Er unwillig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Denn siehe, Jehovah kommt im Feuer und wie der Sturmwind Seine Streitwagen, zu vergelten in Seines Zornes Grimm und Sein Drohen in den Flammen des Feuers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Denn mit dem Feuer wird Jehovah richten, und mit Seinem Schwerte alles Fleisch, und viel wird werden der Erschlagenen Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Die, so sich heiligen und reinigen für die Gärten hinter einem her inmitten ihrer, die da essen des Schweines Fleisch und des Abscheulichen und der Mäuse, sie werden weggerafft allzumal! spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Ich aber kenne ihre Werke und Gedanken. Es kommt, daß man zusammenbringt alle Völkerschaften und Zungen und sie kommen und sehen Meine Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'Und setzen werde Ich unter sie ein Zeichen und senden aus ihnen Entkommene zu den Völkerschaften Tharschisch, Pul und Lud, die den Bogen spannen, Thubal und Javan und zu den fernen Inseln, die nicht Mein Gerücht gehört und nicht gesehen Meine Herrlichkeit. Und sie werden Meine Herrlichkeit verkünden unter den Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'Und werden alle eure Brüder aus allen Völkerschaften herbeibringen als Speiseopfer dem Jehovah auf Rossen und auf Streitwagen und auf Sänften und auf Maultieren und Dromedaren, auf den Berg Meiner Heiligkeit, gen Jerusalem, spricht Jehovah, wie die Söhne Israels in reinem Gefäß das Speiseopfer bringen in das Haus Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'Und Ich will auch aus denselben nehmen zu Priestern und zu Leviten, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Denn wie die neuen Himmel und die neue Erde, so Ich mache, vor Mir stehen, spricht Jehovah, so soll auch euer Same und euer Name stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'Und es wird geschehen, daß von Monat zu Monat und von Sabbath zu Sabbath alles Fleisch kommen wird, vor Mir anzubeten, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'Und sie werden hinausgehen und sehen die Leichen der Männer, die von Mir abgefallen sind; denn ihr Wurm wird nicht sterben und ihr Feuer nicht erlöschen, und sie sind zum Widerwillen allem Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Die Worte Jirmejahus, des Sohnes Chilkijahus von den Priestern in Anathoth im Lande Benjamin,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'An den das Wort Jehovahs geschah, in den Tagen Joschijahus, des Sohnes Amons, König von Judah, im dreizehnten Jahr seiner Regierung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'Und es geschah in den Tagen Jehojakims, des Sohnes Joschijahus, König von Judah, bis an das Ende des elften Jahres, Zidkijahus, des Sohnes Joschijahus, König von Judah, bis zur Wegführung Jerusalems im fünften Monat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Und Jehovahs Wort geschah an mich und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Ehe Ich dich im Mutterleib gebildet hatte, kannte Ich dich, und ehe aus dem Mutterschoß du ausgingst, heiligte Ich dich zum Propheten, für die Völkerschaften gab Ich dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Und ich sprach: Ach, Herr Jehovah! Siehe, ich weiß nicht zu reden: denn ein Junge bin ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Und es sprach Jehovah zu mir: Sprich nicht: Ich bin ein Junge, sondern gehe, überall, wohin Ich dich sende, und alles, was Ich dir gebiete, das rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Fürchte dich nicht vor ihnen, denn Ich bin mit dir, dich zu erretten, spricht Jehovah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'Und Jehovah reckte Seine Hand aus und berührte meinen Mund, und Jehovah sprach zu mir: Siehe, Meine Worte gebe Ich in deinen Mund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Siehe zu, an diesem Tage habe Ich dich bestellt über die Völkerschaften und über die Königreiche, auszuroden, niederzureißen, zu zerstören und einzureißen, zu bauen und zu pflanzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'Und es geschah Jehovahs Wort an mich, sprechend: Was siehst du, Jirmejahu? Und ich sprach: Ich sehe einen Stock vom Mandelbaum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Und Jehovah sprach zu mir: Du hast wohl gesehen. Denn Ich will wachen über Mein Wort, daß Ich es tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'Und es geschah zum zweitenmal Jehovahs Wort an mich sprechend: Was siehst du? Und ich sprach: Ich sehe einen Topf, der überwallt und seine Vorderseite ist Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Und Jehovah sprach zu mir: Von Mitternacht tut sich auf das Böse über alle Bewohner des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Denn siehe, Ich rufe allen Familien der Königreiche gegen Mitternacht, spricht Jehovah, daß sie kommen und setzen jeder Mann seinen Thron an den Eingang der Tore Jerusalems und an alle ihre Mauern ringsumher und an alle Städte Judahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'Und will Meine Gerichte reden mit ihnen über all ihr Böses, daß sie Mich verlassen und anderen Göttern geräuchert und Werke ihrer Hände angebetet haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Du aber umgürte deine Lenden und stehe auf und rede zu ihnen alles, was Ich dir gebiete, erschrick vor ihnen nicht, daß Ich dich nicht vor ihnen erschrecke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Denn siehe, Ich gebe dich heute zur festen Stadt und zur eisernen Säule und zur ehernen Mauer wider das ganze Land, wider die Könige Jehudah, wider dessen Obersten, wider dessen Priester und wider das Volk des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'Und streiten werden sie wider dich und dich nicht übermögen: denn Ich bin mit dir, spricht Jehovah, daß Ich dich errette.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'Und es geschah an mich Jehovahs Wort sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Gehe hin und rufe vor den Ohren Jerusalems und sprich: So spricht Jehovah: Ich habe dir gedacht der Barmherzigkeit deiner Jugend, der Liebe deiner Bräutlichkeit, da du gingst Mir nach in der Wüste, in einem Land, das nicht besät wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Dem Jehovah heilig war Israel, der Erstling des Ertrages. Jeder, der sie auffressen wollte, verschuldete sich; Böses kam über sie, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Höret das Wort Jehovahs, ihr vom Hause Jakobs und alle ihr Familien vom Hause Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'So spricht Jehovah: Was haben eure Väter Verkehrtes an Mir gefunden, daß sie sich von Mir entfernten und der Nichtigkeit nachgingen und nichtig wurden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'Und sie sagten nicht: Wo ist Jehovah, Der uns aus dem Land Ägypten hat heraufgebracht, Der uns in der Wüste gehen ließ, in dem Land der Einöde und der Fallgruben, im Land der Dürre und des Todesschattens, im Land, da kein Mann hindurchgeht, und kein Mensch darin wohnt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'Und Ich brachte euch in ein Land der Fruchtgefilde, damit ihr äßet seine Frucht und sein Gut; ihr aber kamt und verunreinigtet Mein Land und machtet Mein Erbe zum Greuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Die Priester sagen nicht: Wo ist Jehovah? Und die das Gesetz handhaben, kennen Mich nicht, und die Hirten sind von Mir abgefallen, und die Propheten weissagen durch Baal, und gehen denen nach, die nichts nützen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Darum muß Ich noch mit euch hadern, spricht Jehovah, und mit den Söhnen eurer Söhne muß Ich hadern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Denn geht hinüber nach den Inseln der Kittäer und sehet, und sendet nach Kedar und merket sehr darauf, und sehet, ob dergleichen geschieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Hat je eine Völkerschaft die Götter vertauscht, obschon sie keine Götter sind? Aber Mein Volk hat seine Herrlichkeit vertauscht mit etwas, das kein nütze ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Erstaunt darob, ihr Himmel und schaudert, werdet sehr öde, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Denn zweifach Böses hat Mein Volk getan: sie haben Mich verlassen, den Born lebendiger Wasser, um sich Gruben auszuhauen, zerbrochene Gruben, die kein Wasser fassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Ist Israel ein Knecht, ist er ein Kind des Hauses? Warum ist er zum Raub geworden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Wider ihn brüllen die jungen Löwen, sie geben ihre Stimme hervor und machen sein Land zur Verwüstung, seine Städte werden angezündet, ohne Bewohner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Auch die Söhne von Noph und Thachpanches weiden ab dir den Scheitel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Hast du nicht selbst dir dies damit getan, daß du Jehovah, deinen Gott, verließest zur Zeit, da Er dich auf dem Wege gehen ließ?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'Und nun, was hast du mit dem Weg Ägyptens, daß du Schichors Wasser trinkst, und was hast du mit dem Wege Aschurs, daß du des Flusses Wasser trinkst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Züchtigen wird dich deine Bosheit und dein Zurückwenden dich rügen, und wisse und siehe, daß es böse und bitter ist, daß du Jehovah, deinen Gott, verließest, und keine Scheu vor Mir in dir ist, spricht der Herr Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Denn du hast von Ewigkeit her dein Joch zerbrochen, abgerissen deine Bande und gesagt: Ich will nicht dienen; aber auf jedem hohen Hügel und unter jedem grünen Baum hast du als Buhlerin dich gelagert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'Und Ich hatte dich gepflanzt ganz als Edelrebe, einen Samen der Wahrheit, und wie hast du dich Mir in einen ausgearteten ausländischen Weinstock verwandelt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Ja, wüschest du mit Lauge dich und mehrtest dir die Seife, ist deine Missetat doch vor Mir besudelt, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Wie sagst du: Ich bin nicht verunreinigt, gehe den Baalen nicht nach? Siehe deinen Weg in der Schlucht und erkenne, was du getan! Ein schnelles Dromedar bist du, das seine Wege kreuzt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Eine Waldeselin, der Wüste gewohnt, schnappt sie in ihrer Seele Gelüste nach dem Winde; wer hält ihre Brunst zurück? Alle, so sie suchen, werden nicht matt, in ihrem Monat finden sie sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Halt ab deinen Fuß von der Blöße, und deine Kehle von dem Durst! Du sprichst aber: Es ist verzweifelt! Nein! denn Fremde liebe ich und gehe ihnen nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Wie die Scham des Diebes, wenn er ausgefunden wird, so werden beschämt die vom Hause Israel, sie, ihre Könige, ihre Obersten und ihre Priester und ihre Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'Zum Holze sagten sie: Du bist mein Vater, und zum Steine: Du hast mich gezeugt! Mir aber wandten sie den Rücken zu, und nicht das Angesicht. Aber zur Zeit ihres Übels sprechen sie: Stehe auf und rette uns!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Und wo sind deine Götter, die du dir gemacht? Laß sie aufstehen, ob sie zur Zeit deines Übels dich retten können? Denn wie die Zahl deiner Städte, so waren deine Götter, Judah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Warum wollt ihr mit Mir hadern? Ihr alle seid von Mir abgefallen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Vergeblich schlug Ich eure Söhne; sie nahmen keine Zucht an. Euer Schwert fraß eure Propheten, wie der Löwe, der verdirbt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'O Geschlecht, ihr sehet das Wort Jehovahs! War eine Wüste Ich für Israel, ein Land des Dunkels? Warum spricht denn Mein Volk: Wir herrschen, wir kommen nicht mehr zu Dir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Vergißt denn die Jungfrau ihres Schmukkes, die Braut ihres Bandes? Aber Mein Volk hat Tage ohne Zahl Mein vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Was willst du deinen Weg gut machen, Liebe zu suchen? Darum hast du auch die Bosheiten deine Wege gelehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Auch ist an deinen Fittichen gefunden worden das Blut der Seelen der Dürftigen, der Unschuldigen; nicht beim Einbruch fand Ich sie, sondern allüberall.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Und du sprichst: Ich bin unschuldig, ja, Sein Zorn hat von mir sich zurückgewendet. Siehe, wir wollen rechten mit dir ob deiner Rede: Ich habe nicht gesündigt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Was rennst du, so deinen Weg zu verändern? Auch Ägyptens wirst du dich schämen, wie du dich Aschurs schämtest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'Von da auch wirst du ausgehen, und deine Hände auf deinem Haupte; denn Jehovah hat das verschmäht, worauf du vertraut hast, so daß dir mit ihnen nichts gelingen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Er spricht: Siehe, wenn ein Mann sein Weib entläßt und sie geht von ihm fort und wird eines anderen Mannes, wird er noch zu ihr zurückkehren? Ist nicht ein solches Land ganz und gar entheiligt, und du hast gebuhlt mit vielen Genossen. Aber kehre zurück zu Mir! spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Erhebe deine Augen zu den Anhöhen und siehe wo du nicht bist geschändet worden? An den Wegen saßest du für sie, wie der Araber in der Wüste, und entheiligtest das Land durch deine Buhlereien und durch deine Bosheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Da wurden die Regengüsse vorenthalten und es ward kein Spätregen; du aber hast die Stirn eines Buhlweibes, du weigerst dich, Schande zu fühlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Riefst du nicht eben noch zu Mir: Mein Vater, der Leiter meiner Jugend warst Du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Wird Er es ewiglich nachtragen, immerdar es behalten? Siehe, du redetest und tatest das Böse und vermochtest es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Und Jehovah sprach zu mir in den Tagen des Königs Joschijahu: Hast du gesehen, was das abwendige Israel hat getan, wie es hinging auf jeden hohen Berg und unter jeden grünen Baum und allda buhlte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'Und Ich sprach, nachdem sie alles dies getan: Kehre zurück zu Mir. Sie kehrte aber nicht zurück, und seine treulose Schwester Judah sah es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'Und Ich sah, daß nach all der Weise, in der das abwendige Israel Ehebruch begangen, Ich sie entließ und ihr einen Scheidebrief gab, so fürchtete das treulose Jehudah, ihre Schwester, sich doch nicht, und ging und buhlte auch sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'Und von der Stimme ihrer Buhlerei ward entheiligt das Land und sie trieb Ehebruch mit Stein und Holz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'Und auch bei all dem kehrt ihre treulose Schwester Judah nicht zurück zu Mir von ganzem Herzen, sondern mit Lüge, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'Und Jehovah sprach zu mir: Das abwendige Israel rechtfertigt ihre Seele gegen das treulose Jehudah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Gehe und rufe aus gegen Mitternacht diese Worte und sprich: Kehre zurück abwendiges Israel, spricht Jehovah: Ich will Mein Angesicht nicht fallen lassen wider euch, denn Ich bin barmherzig, spricht Jehovah, Ich will nicht ewig nachtragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Allein erkenne deine Missetat, daß du von Jehovah, deinem Gotte, abgefallen bist, und deine Wege verteiltest den Fremden unter jedem grünen Baum, und daß ihr nicht auf Meine Stimme hörtet, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Kehret zurück, ihr abwendigen Söhne, spricht Jehovah, denn Ich habe euch Mir vermählt und will euch nehmen, einen aus einer Stadt und zwei aus einer Familie, und euch gen Zion bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'Und will euch Hirten geben nach Meinem Herzen, daß sie euch weiden mit Erkenntnis und Verstand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'Und wird geschehen, wenn ihr euch mehret und fruchtbar werdet in dem Land in jenen Tagen, spricht Jehovah, daß man nicht mehr spricht von der Lade des Bundes Jehovahs, noch wird sie einem in das Herz kommen, noch wird man ihrer gedenken oder sie vermissen und wird nicht mehr gemacht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Zur selben Zeit wird man Jerusalem den Thron Jehovahs nennen, und werden sich allda ansammeln alle Völkerschaften zum Namen Jehovahs nach Jerusalem und nicht mehr wandeln nach dem Eigensinn ihres bösen Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'In jenen Tagen geht das Haus Jehudahs zu dem Hause Israel, und sie kommen allzumal aus dem Lande der Mitternacht in das Land, das Ich eure Väter erben ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Und Ich sprach: Wie will Ich dich unter die Söhne stellen und dir ein begehrenswertes Land, ein Erbe, die Zierde der Zierden der Völkerschaften geben?! Und Ich sprach: Ihr würdet Mich Vater nennen, und nicht hinter Mir zurückweichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Doch wie ein Weib treulos wird ihrem Genossen, seid ihr, Haus Israels, Mir treulos worden, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Auf den Anhöhen hat man eine Stimme gehört, Weinen, Flehen der Söhne Israels, daß sie ihren Weg krumm gemacht, daß sie Jehovah, ihren Gott, vergessen hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Kehret zurück, ihr abwendigen Söhne; Ich will heilen eure Abwendung. Siehe uns, wir kommen zu Dir, denn Du bist Jehovah, unser Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Fürwahr, zur Lüge ist es mit den Hügeln, der Menge der Berge; fürwahr in Jehovah, unserem Gott, ist Israels Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Und die Beschämung hat von unserer Jugend an die Arbeit unserer Väter, ihr Kleinvieh und ihre Rinder, und ihre Söhne und Töchter aufgefressen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Wir liegen da in unserer Scham, und unsere Schande bedeckt uns; denn wider Jehovah, unseren Gott, haben gesündigt wir und unsere Väter von unserer Jugend auf, und bis auf diesen Tag, und auf die Stimme Jehovahs, unseres Gottes, nicht gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Wenn du zurückkehrst, Israel, spricht Jehovah, zu Mir zurückkehrst und deine Scheusale wegtust vor Meinem Angesicht, und nicht schwankst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'Und schwörst bei Jehovahs Leben in Wahrheit, in Recht und in Gerechtigkeit: so werden in Ihm die Völkerschaften gesegnet werden und in Ihm sich rühmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Denn so spricht Jehovah zu dem Mann von Judah und zu Jerusalem: Brecht einen Neubruch euch und sät nicht unter Dornen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Beschneidet euch dem Jehovah und tut weg die Vorhaut eures Herzens, o Mann Jehudahs und Bewohner von Jerusalem, daß nicht wie Feuer ausgehe Mein Grimm und brenne und niemand da sei, der lösche, ob der Bosheit eures Tuns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Sagt es an in Jehudah und in Jerusalem laßt es hören, und sprechet und blaset die Posaune im Land, macht es voll und sprecht: Sammelt euch und laßt uns in die festen Städte gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Erhebt das Panier Zijon zu, flüchtet euch zusammen und bleibt nicht stehen, denn Böses laß Ich kommen von Mittenacht und ein großes Zerbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Ein Löwe kommt herauf aus seinem Dickicht und wird Völkerschaften verderben, er ist aufgebrochen, aus seinem Orte ausgezogen, dein Land zur Wüstenei zu machen, daß deine Städte zertrümmert werden, niemand darin wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Darum gürtet euch mit Säcken, klaget und heulet; denn die Entbrennung von Jehovahs Zorn kehrt nicht von uns zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Und an jenem Tage wird geschehen, spricht Jehovah, daß das Herz des Königs und das Herz der Obersten vergeht, daß die Priester erstaunen und die Propheten sich verwundern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Und ich sprach: Ach, Herr Jehovah, fürwahr hast Du dies Volk und Jerusalem verführen und ihm sagen lassen: Ihr werdet Frieden haben, und es reicht bis an die Seele das Schwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'Zur selben Zeit wird man diesem Volk und Jerusalem sagen: Ein sengender Wind der Anhöhen in der Wüste ist der Weg der Tochter Meines Volkes, nicht um zu worfeln und zu säubern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'Ein voller Wind kommt Mir von ihnen. Nun will Ich auch mit diesen von Gerichten reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Siehe, wie Wolken zieht es herauf und wie der Sturmwind sind seine Streitwagen, schneller denn Adler seine Rosse! Wehe uns! wir sind verheert!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Wasche dein Herz vom Bösen, Jerusalem, daß du gerettet werdest! Wie lange willst du in deinem Inneren herbergen deines Unrechts Gedanken!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Denn eine Stimme, die es ansagt, kommt von Dan, er, der Unrechtes hören läßt, von Ephraims Gebirge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Meldet es den Völkerschaften! Siehe! Laßt es hören über Jerusalem! Wächter kommen aus fernem Land und geben ihre Stimme wider Jehudahs Städte hervor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'Wie Hüter des Feldes sind sie wider sie rings umher, weil sie widerspenstig geworden ist, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Dein Weg und dein Tun haben dir es getan. Das ist deine Bosheit, daß dir es bitter ist, daß dir es an das Herz reicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Mein Eingeweide! Mein Eingeweide! Es kreißen die Wände meines Herzens. Mein Herz tobt auf, ich kann nicht stille schweigen; denn der Posaune Stimme hört meine Seele, des Streites Feldgeschrei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'Bruch auf Bruch begegnet man. Denn verheert ist das ganze Land, plötzlich verheert sind meine Zelte, in einem Augenblick meine Teppiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Wie lange soll Ich sehen das Panier, hören der Posaune Stimme?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Denn Mein Volk ist dumm, Mich kennt es nicht. Närrische Söhne sind sie, und ohne Einsicht sind sie, weise sind sie zum Böses tun, aber Gutes zu tun, wissen sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Ich sah die Erde, und siehe! eine Leere und Öde, und auf zu den Himmeln, und ihr Licht war nicht da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Ich sah die Berge und siehe! sie bebten, und alle Hügel wankten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Ich sah, und siehe! da war kein Mensch, und alles Gevögel der Himmel war entflohen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Ich sah, und siehe! der Karmel war eine Wüste, und alle seine Städte waren eingerissen vor Jehovah, vor der Entbrennung Seines Zorns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Denn so spricht Jehovah: Verwüstet soll sein das ganze Land, doch will Ich nicht eine Vollendung machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Darüber soll das Land trauern und die Himmel droben sich verdunkeln, weil, was Ich geredet habe, habe Ich beschlossen, und nicht gereut es Mich, noch wende Ich Mich davon zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Vor der Stimme des Reiters und des Bogenschützen entweicht die ganze Stadt; sie gehen hinein in die dichten Wolken und zu den Felskuppen steigen sie auf. Verlassen ist die ganze Stadt und kein Mann wohnt darinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Und du, Verheerte, was tust du? Ziehst du Scharlach an, schmückst dich mit Goldschmuck, schminkst mit Bleiglanz deine Augen, - umsonst machst du dich schön - es verschmähen dich deine Liebhaber, sie trachten dir nach der Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Ich höre die Stimme wie einer Kreißenden, Bedrängnis wie einer, die zum erstenmal gebiert, die Stimme der Tochter Zijons, die schluchzt, die ihre Hände ausbreitet. O weh, mir doch; denn meine Seele ermattet vor den Mordenden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Streifet umher in den Gassen von Jerusalem, und seht doch und erkennt und sucht in seinen Straßen, ob einen Mann ihr findet, ob einer da ist, der Recht tut, der Wahrheit sucht: so will Ich ihr vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'Und ob sie sprechen: Beim Leben Jehovahs! schwören sie dennoch zur Lüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'Jehovah, sind Deine Augen nicht auf dem Wahren? Du schlugst sie und es erschütterte sie nicht; Du riebst sie auf, sie weigerten sich, Zucht anzunehmen, machen fester denn die Felsenklippe ihr Angesicht, weigern sich, umzukehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Und ich sprach: Es sind nur die Armen, die dumm sind, weil sie den Weg Jehovahs, ihres Gottes Recht, nicht kennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Ich will doch zu den Großen gehen und will mit ihnen reden, denn sie kennen den Weg Jehovahs, ihres Gottes Recht. Aber sie hatten allzumal das Joch gebrochen, die Bande abgerissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Darum schlägt sie der Löwe aus dem Wald, es verheert sie der Wolf der Einöden, der Pardel lauert wider ihre Städte. Jeder, der aus denselben herausgeht, wird zerfleischt, denn viel ist ihrer Übertretungen, mächtig ist ihre Abwendung geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Ob dem sollte Ich vergeben dir? Deine Söhne verließen Mich und schwuren bei einem, der nicht Gott ist: und als Ich sie sättigte, trieben sie Ehebruch und scharten sich zusammen in der Buhlerin Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Wie geile Rosse sind sie früh auf und wiehern, ein jeder Mann nach des Genossen Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Sollte Ich deshalb nicht heimsuchen? spricht Jehovah. - Oder soll an einer Völkerschaft wie diese Meine Seele nicht Rache nehmen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Steigt auf ihre Mauern und verderbt sie; aber macht keine Vollendung. Tut weg ihre Ranken, denn sie sind nicht Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Denn treulos haben an Mir gehandelt das Haus Israel und das Haus Judah, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Verleugnet haben sie Jehovah und gesagt: Er ist nicht, und es wird nichts Böses kommen über uns. Und Schwert und Hunger werden wir nicht sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'Und die Propheten werden zu Wind werden und das Wort ist nicht in ihnen. So wird es ihnen geschehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Darum spricht also Jehovah, der Gott der Heerscharen: Weil ihr redet solches Wort, siehe, so will Ich Meine Worte in deinen Mund geben zum Feuer, und dieses Volk zu Holz, daß es sie auffresse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Siehe, aus der Ferne bringe Ich über euch eine Völkerschaft, Haus Israel, spricht Jehovah: Eine mächtige Völkerschaft ist es, eine uralte Völkerschaft, eine Völkerschaft, deren Zunge du nicht kennst und nicht verstehst, was es redet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Sein Köcher ist wie ein geöffnetes Grab, sie alle sind Helden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'Und es wird auffressen deine Ernte und dein Brot; sie werden auffressen deine Söhne und deine Töchter; auffressen dein Kleinvieh und dein Rind; auffressen deinen Weinstock und deinen Feigenbaum; es wird deine festen Städte, auf die du vertraut, arm machen mit dem Schwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Aber auch in jenen Tagen, spricht Jehovah, will Ich mit euch keine Vollendung machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'Und soll geschehen, wenn ihr sagt, warum hat uns Jehovah, unser Gott, solches alles getan, daß du ihnen sagst: Wie ihr Mich habt verlassen und Göttern des Auslandes in eurem Lande gedient, so sollt ihr Fremden dienen in einem Lande, das nicht euer ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Sagt solches an im Hause Jakobs und laßt hören in Jehudah und sprechet:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Höret doch dies, närrisches Volk, ohne Herz; die Augen haben und sehen nicht, Ohren haben und hören nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Mich wollt ihr nicht fürchten, spricht Jehovah, vor Mir nicht erschüttert sein, Der Ich den Sand dem Meere zur Grenze setze, zur ewigen Satzung, und es überschreitet sie nicht; und es wogt einher und vermag nichts; die Wogen toben und überschreiten es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Aber dies Volk hat ein störrisch und widerspenstig Herz. Sie sind abgewichen und sind dahingegangen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'Und sagten nicht in ihrem Herzen: Lasset uns doch Jehovah fürchten, unseren Gott, Der den Platzregen uns, den Frühregen und Spätregen gibt zu seiner Zeit, Der die Wochen, die Satzungen der Ernte, für uns behütet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Eure Missetaten wendeten dies ab, und eure Sünden hielten ab von euch das Gute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Denn Ungerechte finden sich in Meinem Volk, sie schauen zu, wie Vogelsteller sich duckend die Fallen stellen, sie fangen Männer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Wie ein Vogelbauer voll vom Gevögel ist, sind vom Betruge ihre Häuser voll. Daher werden sie groß und reich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Sie werden fett, sie glitzern, auch fließen sie über mit Worten der Bosheit. Die Rechtssache rechten sie nicht, die Rechtssache der Waise, daß es ihnen gelänge, und das Recht der Dürftigen richten sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Und solches sollte Ich nicht heimsuchen? spricht Jehovah, an einer Völkerschaft wie diese soll Meine Seele nicht Rache nehmen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Erstaunliches und Schauerliches geschieht im Lande!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'Lüge weissagen die Propheten und die Priester herrschen durch deren Hände, und Mein Volk liebt es so. Und was wollt ihr zuletzt dabei tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Flüchtet euch zusammen, Benjamins Söhne, aus Jerusalems Mitte. In Thekoa stoßet in die Posaune und auf dem Hause des Weinbergs erhebt das Feuerzeichen; denn Böses schaut hervor aus Mitternacht und großes Zerbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Einer Holden und Üppigen vergleiche Ich die Tochter Zijon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'Zu ihr kommen die Hirten und ihre Herden, sie schlagen ihre Zelte ringsum bei ihr auf; sie weiden, jeder Mann seine Stelle ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, 'Heiligt wider sie den Streit; stehet auf und lasset uns gen Mittag hinaufziehen! Wehe uns, denn der Tag hat sich gewendet, und die Schatten des Abends strecken sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Stehet auf! und laßt uns in der Nacht hinaufziehen und ihre Paläste verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Denn also spricht Jehovah der Heerscharen: Haut Bäume um und schüttet einen Wall auf wider Jerusalem; sie ist die Stadt, die heimgesucht wird. In ihrem Inneren ist alles Erpressung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Wie der Brunnen läßt hervorquellen sein Wasser, so quillt hervor ihre Bosheit. Gewalttat und Verheerung hört man in ihr, vor Meinem Angesicht beständig Krankheit und Schlag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Nimm Zucht an, Jerusalem, daß sich Meine Seele nicht von dir abneige, daß Ich dich nicht zur Verwüstung mache, zu einem Lande, das man nicht bewohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'So spricht Jehovah der Heerscharen: Eine Nachlese soll man nachlesen, wie am Weinstock, an dem Überrest Israels. Deine Hand soll sie in die Körbe bringen wie der Winzer!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Zu wem soll ich reden und zeugen, daß sie es hören? Siehe, ihr Ohr ist unbeschnitten, sie vermögen nicht zu horchen. Siehe, das Wort Jehovahs ist ihnen zur Schmach geworden. Sie haben keine Lust dazu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Aber ich bin voll vom Grimme Jehovahs, bin ermüdet, davon ihn zurückzuhalten. Schütte ihn aus über das Kindlein auf der Gasse und über den Kreis der Jünglinge allzumal; denn auch der Mann mit dem Weib wird gefangen werden, der Alte mit dem, der voll ist von Tagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'Und ihre Häuser gehen an andere über, Felder und Weiber allzumal, wenn Meine Hand Ich ausrecke über die, so im Lande wohnen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Denn von ihren Kleinen bis zu ihren Großen geizt alles nach Gewinn, und vom Propheten bis zum Priester tut alles Lüge;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'Und heilen den Bruch der Tochter Meines Volkes leichthin und sagen: Friede, Friede, und ist kein Friede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Schämen sie sich, daß sie Greuel tun? Sie schämen sich mit keiner Scham, auch wissen sie nichts von Schande; darum sollen sie fallen unter den Fallenden; zur Zeit, da Ich sie heimsuche, straucheln sie, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'So spricht Jehovah: Stehet bei den Wegen und sehet und fraget nach den Steigen der Ewigkeit, welches der gute Weg sei, und wandelt darin, und ihr werdet Rast finden für eure Seele. Sie aber sprechen: Wir wollen nicht darauf wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'Und Ich habe Wächter über euch eingesetzt. Horchet auf die Stimme der Posaune. Sie aber sprachen: Wir wollen nicht horchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'So hört denn, ihr Völkerschaften, und wisse, du Gemeinde, was in ihnen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Höre, du Erde: Siehe, Ich bringe Böses über dieses Volk, die Frucht ihrer Gedanken, daß sie auf Meine Worte nicht horchen, und Mein Gesetz, das verschmähen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Was soll Mir dies, daß Weihrauch aus Scheba kommt und der gute Kalmus aus fernem Lande? Eure Brandopfer sind nicht nach Meinem Wohlgefallen, und eure Schlachtopfer sind Mir nicht angenehm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Darum spricht also Jehovah: Siehe, Ich gebe einen Anstoß diesem Volk, daß sich daran anstoßen Väter und Söhne allzumal, daß der Nachbar und sein Genosse vergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'So spricht Jehovah: Siehe, ein Volk kommt von dem Land der Mitternacht, und eine große Völkerschaft wird auferweckt von der Erde Seiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Bogen und Wurfspieß erfassen sie, sind grausam und haben kein Erbarmen; ihre Stimme tobt wie das Meer; und sie reiten auf Rossen, gerüstet wie ein Mann zum Streite wider dich, Tochter Zions.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Wir hören ihr Gerücht, unsere Hände erschlaffen. Bedrängnis erfaßt uns, ein Kreißen wie der Gebärerin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Geht nicht hinaus auf das Feld und wandelt nicht auf dem Weg; denn des Feindes Schwert, Bangen ist ringsumher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'O Tochter meines Volkes, gürte dich mit dem Sacke, wälze dich umher in der Asche, mache dir Trauer wie um den Einzigen, eine Klage der Bitterkeit; denn plötzlich kommt der Verheerer über uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Zum Prüfer gebe Ich dich, zur Festung unter Mein Volk, daß ihren Weg du kennen und prüfen sollst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Sie alle sind Abgefallene der Abgefallenen; sie gehen als Zwischenträger, Erz und Eisen sind sie, sie sind alle Verderber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Es glüht der Blasebalg; verzehrt vom Feuer ist das Blei; umsonst läutert man, die Bösen lassen sich nicht abreißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Verschmähtes Silber nennt man sie; denn Jehovah hat sie verschmäht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Das Wort, das von Jehovah an Jirmejahu geschah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Stehe in dem Tor des Hauses Jehovahs und rufe allda dies Wort und sprich: Höret das Wort Jehovahs ganz Jehudah, ihr, die ihr zu diesen Toren eingeht, Jehovah anzubeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'So spricht Jehovah der Heerscharen, der Gott Israels: Macht eure Wege gut und euer Tun, so will Ich euch wohnen lassen an diesem Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Vertraut euch nicht auf Worte der Lüge, sprechend: Der Tempel Jehovahs, der Tempel Jehovahs, der Tempel Jehovahs ist das.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Sondern macht eure Wege gut und euer Tun, daß ihr das Recht tuet zwischen dem Mann und seinem Genossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'Gegen den Fremdling, die Waise und die Witwe übet nicht Erpressung, und vergießet nicht unschuldig Blut an diesem Ort, und geht nicht anderen Göttern nach, euch zum Übel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'Dann will Ich euch an diesem Ort, in dem Lande wohnen lassen, das Ich euren Vätern gegeben habe, von Ewigkeit zu Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Siehe, ihr vertraut euch auf Worte der Lüge, die kein nütze sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Wollt ihr stehlen, morden und ehebrechen und zur Lüge schwören und dem Baal räuchern und anderen Göttern nachgehen, die ihr nicht kennt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'Und hereinkommen und stehen vor Mein Angesicht in diesem Hause, über dem Mein Name ist genannt, und sprechen: Wir sind errettet! während ihr alle diese Greuel tut?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Ist dies Haus, über dem Mein Name ist genannt, in euren Augen zur Höhle der Räuber geworden? Siehe, auch Ich habe es gesehen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Gehet doch hin an Meinen Ort in Schilo, wo Meinen Namen Ich hatte früher wohnen lassen, und sehet, was Ich mit ihm getan wegen der Bosheit Meines Volkes Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'Und nun, weil ihr alle diese Werke tut, spricht Jehovah, und Ich zu euch geredet, indem Ich früh aufstand und redete, und ihr nicht hörtet, und Ich euch rief und ihr nicht antwortet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'So will Ich dem Hause tun, über dem Mein Name genannt wird, worauf ihr vertrauet, und dem Orte, den Ich euch und euren Vätern gegeben habe, wie Ich Schilo getan habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'Und werfe euch weg von Meinem Angesicht, wie Ich weggeworfen habe alle eure Brüder, allen Samen Ephraims.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Du aber bete nicht für dieses Volk, und erhebe nicht Klageruf, noch Gebet für sie, und dränge nicht in Mich, denn Ich höre nicht auf dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Siehst du nicht, was sie in den Städten Jehudahs tun und in den Gassen Jerusalems?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Die Söhne lesen Holz auf und die Väter zünden das Feuer an und die Weiber kneten Teig, Kuchen zu machen für die Königin des Himmels und zu gießen anderen Göttern Trankopfer, daß sie Mich reizen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Reizen sie Mich, spricht Jehovah, nicht vielmehr sich selbst zur Beschämung ihres Angesichts?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Darum, so spricht der Herr Jehovah: Siehe Mein Zorn und Mein Grimm sind ergossen über diesen Ort, über Mensch und über Vieh, und über den Baum des Feldes, und über die Frucht des Bodens; und es brennt und erlöscht nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'So spricht Jehovah der Heerscharen, der Gott Israels: Tut eure Brandopfer hinzu zu euren Schlachtopfern und esset Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Denn Ich habe nicht zu euren Vätern geredet, noch ihnen geboten am Tage, da Ich sie aus dem Lande Ägypten herausgebracht, über Worte des Brandopfers und des Schlachtopfers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'Sondern Ich gebot ihnen dies Wort und sprach: Höret auf Meine Stimme, so will Ich Gott euch sein, und ihr sollt Mir zum Volke sein, und wandeln auf jeglichem Wege, den Ich euch gebiete, daß es gut mit euch sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Aber sie hörten nicht und neigten nicht ihr Ohr, und wandeln nach den Ratschlägen, nach der Verstocktheit ihres bösen Herzens, und kehrten sich nach hinten, und nicht nach vorn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Vom Tage, da eure Väter auszogen aus dem Lande Ägypten bis auf diesen Tag, da sandte Ich zu euch alle Meine Knechte, die Propheten, indem Ich täglich früh aufstand und sie sandte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'Sie aber hörten nicht auf Mich und neigten nicht ihr Ohr und verhärteten ihren Nacken, und machten es schlimmer als ihre Väter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'Und redest du zu ihnen alle diese Worte, so hören sie nicht auf dich, und rufst du ihnen, so antworten sie dir nicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Und du, sprich zu ihnen: Das ist die Völkerschaft, die nicht gehört hat auf die Stimme Jehovahs, ihres Gottes, und keine Zucht annahm. Vergangen ist die Wahrheit und aus ihrem Munde ausgerottet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Scher ab dein Nasiräat und wirf es hin und erhebe auf den Abhängen ein Klagelied. Denn Jehovah hat verschmäht und hingegeben das Geschlecht Seines Wütens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Denn die Söhne Jehudahs tun, was böse ist in Meinen Augen, spricht Jehovah, sie stellen ihre Scheusale in dem Hause auf, über dem Mein Name ist genannt, es zu verunreinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'Und bauen die Opferhöhen des Topheth in der Schlucht des Ben-Hinnom, um ihre Söhne und ihre Töchter im Feuer zu verbrennen, was Ich nicht geboten, und was Mir nicht in das Herz heraufgekommen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Darum, siehe, es kommen Tage, spricht Jehovah, da man nicht mehr wird sagen Topheth oder die Schlucht des Ben-Hinnom, sondern die Schlucht des Würgens und in Topheth werden sie begraben, bis daß kein Raum da ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'Und dieses Volkes Leichname werden zur Speise sein für des Himmels Gevögel und dem Getier der Erde, und niemand wird sie aufscheuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Und von den Städten Judahs und von den Gassen Jerusalems lasse Ich aufhören die Stimme der Freude und die Stimme der Fröhlichkeit, die Stimme des Bräutigams und die Stimme der Braut; denn zur Öde wird das Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'Zu derselben Zeit, spricht Jehovah, wird man die Gebeine der Könige Jehudahs und die Gebeine seiner Obersten und die Gebeine der Priester und die Gebeine der Propheten und die Gebeine der Bewohner Jerusalems aus ihren Gräbern herausbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'Und sie werden sie ausspreiten vor die Sonne und den Mond und alles Heer der Himmel, die sie geliebt und denen sie gedient und denen sie nachgegangen und denen sie nachgefragt und die sie angebetet hatten. Sie werden nicht gesammelt und nicht begraben. Zum Dünger auf dem Angesichte des Bodens werden sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'Und der Tod wird gewählt werden vor dem Leben bei all dem Überrest, der von dieser bösen Familie verblieben ist an allen übriggebliebenen Orten, wohin Ich sie verstoßen hatte, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Und sprich zu ihnen: Also spricht Jehovah: Werden sie fallen, und nicht aufstehen? Wird der, so sich hat abgekehrt, nicht zurückkehren?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Warum hat dieses Volk sich abgekehrt, Jerusalem, in immerwährender Abkehr? Sie halten an ihrem Truge fest, sie weigern sich zurückzukehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Ich horchte und hörte: Nichts Rechtes reden sie. Da ist kein Mann, den seine Bosheit reuete, der spräche: Was habe ich getan? Sie alle kehren zurück in ihrem Lauf, wie das Roß hinrennt in den Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Auch der Storch am Himmel weiß seine bestimmte Zeit, und die Turteltaube und die Schwalbe und der Kranich halten die Zeit ihres Kommens, aber Mein Volk weiß nicht das Recht Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Wie möget ihr sprechen: Weise sind wir, und das Gesetz Jehovahs ist bei uns! Aber siehe, zur Lüge hat es gemacht der Lügengriffel der Schreiber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Beschämt sind die Weisen, sie sind entsetzt und gefangen. Siehe, das Wort Jehovahs verschmähten sie, und was für Weisheit haben sie?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Darum gebe Ich anderen ihre Weiber, ihre Felder denen, so sie erblich besitzen. Denn allesamt vom Kleinen und bis zum Großen geizen sie nach Gewinn. Von den Propheten und bis zum Priester treibt jeder Lüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'Und sie heilen leichthin den Bruch der Tochter Meines Volkes und sprechen: Friede, Friede! und ist kein Friede da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Schämen sie sich, daß sie Greuel taten? Sie schämen sich auch mit keiner Scham und wissen nichts von Schande; darum müssen sie zur Zeit ihrer Heimsuchung fallen unter den Fallenden, sie sollen straucheln, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Wegraffend raffe Ich sie weg, spricht Jehovah: Keine Weinbeeren sind am Weinstock und keine Feigen am Feigenbaum, und das Blatt ist abgefallen; und Ich will sie geben denen, so an ihnen vorübergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, 'Wofür sitzen wir da? Versammelt euch, und lasset uns in die festen Städte eingehen und daselbst untergehen; denn untergehen läßt uns Jehovah, unser Gott, und läßt uns Wasser der Galle trinken, weil wir wider Jehovah gesündigt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Man hofft auf Frieden und nichts Gutes ist da; auf eine Zeit der Heilung, und siehe da, Schrecknis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Von Dan her hört man seiner Rosse Schnauben, von der Stimme des Wieherns seiner Gewaltigen erbebt das ganze Land. Und sie kommen und fressen auf das Land und seine Fülle, die Stadt und die darin wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Denn siehe, Schlangen, Basilisken sende Ich wider euch. Für die ist keine Beschwörung, und sie sollen euch beißen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'Gibt es Linderung für mich über den Gram? Mein Herz ist siech!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Siehe, die Stimme des Angstschreis der Tochter meines Volkes aus dem Lande der Ferne! Ist denn Jehovah nicht in Zijon? Ist ihr König nicht in ihr? Warum haben sie mich gereizt mit ihren Schnitzbildern, mit des Auslandes Nichtigkeiten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, 'Die Ernte ist vorbei, der Sommer ist zu Ende, und wir sind nicht gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Ich bin gebrochen ob dem Bruch der Tochter meines Volkes, ich bin verdüstert, Erstaunen erfasset mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Ist kein Balsam in Gilead? Ist kein Arzt daselbst? Warum ersteht keine Genesung der Tochter meines Volkes? Wer gäbe, daß mein Haupt Wasser werde, und mein Auge ein Born der Tränen, daß ich bei Tag und Nacht beweinete die Erschlagenen der Tochter meines Volkes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'Wer gibt Mir in der Wüste eine Herberge der Reisenden, so verließe Ich Mein Volk und ginge von ihnen; denn sie alle sind Ehebrecher, eine Rotte von Treulosen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'Und sie spannen ihre Zungen als ihren Bogen der Lüge, und nicht für Wahrheit sind mächtig sie im Lande; denn von Bösem gehen sie auf Böses aus, und Mich kennen sie nicht, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'Der Mann hüte sich vor seinem Genossen, und vertraue auf keinen Bruder; denn jeder Bruder überlistet und jeder Genosse geht als Zwischenträger um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Und der Mann hintergeht seinen Genossen, und Wahrheit reden sie nicht. Sie lehren ihre Zunge Lüge reden. Sie mühen sich ab, verkehrt zu handeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'Du wohnst mitten unter Trug. Vor Trug weigern sie sich, Mich zu erkennen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Darum spricht also Jehovah der Heerscharen: Siehe, läutern und prüfen will Ich sie. Denn was sollte Ich tun vor der Tochter Meines Volkes?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Ein geschärfter Pfeil ist ihre Zunge. Trug redet sie. Mit seinem Munde redet er Frieden mit dem Genossen, und in seinem Inneren legt er ihm einen Hinterhalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Sollte über solchem Ich sie nicht heimsuchen? spricht Jehovah. Sollte an einer Völkerschaft wie diese nicht Meine Seele Rache nehmen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Über die Berge will Ich ein Weinen erheben und ein Trauerlied, und über der Wüste Auen ein Klagelied. Denn sie sind versengt, so daß kein Mann vorübergeht, und man nicht hört die Stimme der Viehherde. Sie sind entflohen, hingegangen, vom Gevögel der Himmel bis zum Vieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Und Ich gebe Jerusalem dahin, zum Trümmerhaufen, zur Wohnstätte der Drachen und die Städte Jehudahs gebe Ich zur Verwüstung ohne Bewohner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'Wer ist der weise Mann, daß er dies einsehe und zu dem Jehovahs Mund geredet, daß er es ansage? Weshalb wird dieses Land zerstört, versengt wie die Wüste, daß niemand durchgeht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Und Jehovah spricht: Darum, daß sie verlassen Mein Gesetz, das Ich vor sie gegeben, und auf Meine Stimme nicht gehört und nicht danach gewandelt haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'Und gingen der Verstocktheit ihrer Herzen nach und nach den Baalen, wie ihre Väter sie gelehrt hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'Darum, so spricht Jehovah der Heerscharen, der Gott Israels, siehe, Ich lasse dieses Volk Wermut essen und tränke sie mit Wasser der Galle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'Und zerstreue sie unter die Völkerschaften, die weder sie selbst noch ihre Väter kannten, und sende ihnen das Schwert nach, bis Ich sie aufgerieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'So spricht Jehovah der Heerscharen: Merket auf und ruft den Klageweibern, daß sie kommen, und sendet nach den weisen Frauen, daß sie kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Daß sie eilen und über uns das Trauerlied erheben, und Tränen von unseren Augen herabrinnen, und Wasser von unseren Wim- pern riesle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'Denn aus Zijon hört man des Trauerliedes Stimme: Wie sind wir verheert, wir sind beschämt sehr. Denn wir verlassen das Land, denn niedergeworfen sind unsere Wohnungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Ja, höret, ihr Weiber, Jehovahs Wort, und Seines Mundes Wort nehmet zu Ohr, und lehret eure Töchter das Trauerlied und das Weib die Genossin das Klagelied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Denn zu unseren Fenstern steigt herauf der Tod, er kommt in unsere Paläste, auszurotten das Kindlein aus der Gasse, die Jünglinge aus der Straße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Rede: So spricht Jehovah: Wie Dünger fällt des Menschen Leichnam auf des Feldes Angesicht und wie die Garbe hinter dem Schnitter, und keiner sammelt sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'So spricht Jehovah: Nicht rühme der Weise sich seiner Weisheit und nicht rühme der Mächtige sich seiner Macht; nicht rühme der Reiche sich seines Reichtums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Sondern wer sich rühmen will, der rühme sich, daß er verständig ist und Mich kennt, daß Ich Jehovah bin, Welcher tut Barmherzigkeit, Recht und Gerechtigkeit auf Erden; denn daran habe Ich Lust, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'Siehe, es kommen Tage, spricht Jehovah, daß Ich an allen die Beschneidung in der Vorhaut heimsuche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'An Ägypten und an Jehudah und an Edom, und an den Söhnen Ammons und an Moab und an allen, welche die Ecke stutzen, die in der Wüste wohnen; denn alle die Heiden sind unbeschnitten und das ganze Haus Israels ist unbeschnittenen Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Höret das Wort, das Jehovah über euch redet, ihr vom Hause Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'So spricht Jehovah: Lernet nicht den Weg der Völkerschaften und entsetzet euch nicht ob den Zeichen an dem Himmel, denn die Völkerschaften entsetzen sich darob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Denn nichtig sind die Satzungen der Völker: Wenn man den Baum im Walde umgehauen, ein Werk von den Händen der Werkleute mit dem Beile.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Mit Silber und mit Gold macht er ihn schön, und macht ihn fest mit Nägeln und mit Hämmern, daß er nicht schlottere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Fest wie die Palmen sind sie und reden nicht, sie müssen sie tragen, weil sie nicht schreiten. Fürchtet euch nicht vor ihnen: Sie können kein Übel tun, und auch Gutes zu tun, ist nicht bei ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Von wannen ist einer wie Du, Jehovah? Du bist groß und groß ist Dein Name an Macht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Wer sollte Dich nicht fürchten, Du König der Völkerschaften? Dir ja kommt es zu. Denn von wannen unter allen Weisen der Völkerschaften und in irgendeinem ihrer Reiche ist einer wie Du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'Allzumal sind sie tierisch und dumm. Eine nichtige Belehrung ist das Holz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Breitgeschlagenes Silber wird aus Tharschisch herbeigebracht und das Gold aus Uphas, gemacht vom Werkmann und den Händen des Goldschmiedes, blauer und roter Purpur ihr Gewand; ein Machwerk der Weisen sind sie alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Aber Jehovah ist ein Gott der Wahrheit, ein lebendiger Gott ist Er und ein König der Ewigkeit. Vor Seiner Entrüstung erbebt die Erde, und Seinen Unwillen halten die Völkerschaften nicht aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Also sollt ihr zu ihnen sprechen: Die Götter, die den Himmel und die Erde nicht gemacht, sie sollen von der Erde und unter dem Himmel weg zerstört werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'Er hat die Erde gemacht durch Seine Kraft, die Welt bereitet durch Seine Weisheit und durch Seine Einsicht die Himmel ausgespannt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Gibt Seine Stimme Er dahin, so ist eine Menge der Wasser an den Himmeln, und von der Erde Ende läßt Er Dünste aufsteigen, Er macht Blitze für den Regen und bringt heraus die Winde aus Seinen Schatzkammern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Tierisch ist jeder Mensch durch das Wissen, beschämt wird jeder Goldschmied durch sein Schnitzbild. Denn sein Gußbild ist Lüge und kein Hauch ist in denselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Nichtigkeit sind sie, ein Machwerk der Irrtümer, sie vergehen zur Zeit ihrer Heimsuchung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Nicht wie sie ist Jakobs Teil; denn Er ist es, Der das Ganze gebildet hat, und Israel ist Seines Erbes Rute; Jehovah der Heerscharen ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Sammle ein deine Ware von der Erde, die du im Bollwerk sitzest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Denn also spricht Jehovah: Siehe, diesmal schleudere Ich weg die, so im Lande wohnen, und bedränge sie, daß sie es ausfinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Wehe mir, ob meinem Bruch, mein Schlag ist schmerzhaft, aber ich spreche: Das ist eben meine Krankheit und ich will sie tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Verheert ist mein Zelt und alle meine Seile abgerissen, meine Söhne sind von mir ausgezogen und sind nicht mehr. Ich habe keinen, der noch mein Zelt aufspannt und meine Teppiche aufrichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Denn tierisch sind geworden die Hirten, und haben Jehovah nicht nachgefragt und waren darum nicht klug, und alles, was sie weiden, wird zerstreut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Die Stimme eines Gerüchtes, siehe, es kommt und ein groß Erbeben vom Land der Mitternacht, um die Städte Jehudahs zur Verwüstung zu setzen, eine Wohnstätte der Drachen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Ich weiß, Jehovah, daß dem Menschen sein Weg nicht gehört, noch dem Manne, zu wandeln und seinen Schritt zu richten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Züchtige mich, Jehovah, doch nach dem Recht, nicht in Deinem Zorne, daß Du meiner nicht wenig machst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Schütte Deinen Grimm aus über die Völkerschaften, die Dich nicht kennen, und über die Familien, die Deinen Namen nicht anrufen, denn sie fraßen Jakob auf, sie fraßen ihn auf und rieben ihn auf, und machten wüste seinen Wohnort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Das Wort, das von Jehovah an Jirmejahu geschah und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Höret die Worte dieses Bundes und redet zu dem Mann Jehudahs und zu denen, die da wohnen in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Und sprich zu ihnen: Also spricht Jehovah, der Gott Israels: Verflucht der Mann, der nicht hört auf die Worte dieses Bundes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'Den Ich euren Vätern habe geboten am Tage, da Ich sie herausbrachte aus dem Lande Ägypten, aus dem Schmelzofen von Eisen, und sprach: Höret auf Meine Stimme und tut sie, nach allem, was Ich euch geboten habe, auf daß ihr Mein Volk seiet, und Ich euer Gott sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'Auf daß den Schwur Ich aufrecht erhalte, den euren Vätern Ich geschworen habe, ihnen ein Land zu geben, da Milch und Honig fließt, wie an diesem Tag. Und ich antwortete und sprach: Amen, Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'Und Jehovah sprach zu mir: Rufe alle diese Worte in den Städten Jehudahs und in den Gassen Jerusalems und sprich: Höret die Worte dieses Bundes und tut sie!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Denn Ich habe euren Vätern ernstlich bezeugt an dem Tage, da Ich sie aus dem Lande Ägypten heraufbrachte bis auf diesen Tag, indem Ich früh aufstand, und bezeugte, sprechend: Höret auf Meine Stimme!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Aber sie hörten nicht und neigten nicht ihr Ohr, und wandelten jeder Mann nach der Verstockung ihres bösen Herzens; so will Ich denn auch über sie kommen lassen alle die Worte dieses Bundes, die Ich gebot zu tun, und sie taten es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'Und Jehovah sprach zu mir: Es findet sich eine Verschwörung bei dem Manne Jehudahs und bei den Bewohnern Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Sie sind zu den früheren Missetaten ihrer Väter zurückgekehrt, die sich geweigert hatten, auf Meine Worte zu hören, und anderen Göttern nachgingen, ihnen zu dienen. Sie, das Haus Israel und das Haus Jehudah, haben Meinen Bund zunichte gemacht, den Ich mit ihren Vätern geschlossen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Darum siehe, so spricht Jehovah, Ich bringe Böses über sie, aus dem sie nicht vermögen herauszukommen; und sie werden zu Mir schreien, aber Ich höre nicht auf sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Und die Städte Jehudahs und die Bewohner Jerusalems sollen gehen und zu den Göttern schreien, denen sie räucherten; aber sie werden ihnen zur Zeit ihres Übels nicht helfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Denn nach der Zahl deiner Städte, Jehudah, waren deine Götter, und nach der Zahl der Gassen Jerusalems stelltest du Altäre der Scham auf, Altäre dem Baal zu räuchern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Du aber bete nicht für dieses Volk und erhebe für sie keinen Klageruf, noch Gebet; denn Ich höre nicht zur Zeit, da sie zu Mir rufen in ihrem Übel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Was hat mein Liebling in meinem Haus zu tun, wenn die vielen Arglist üben und das Fleisch der Heiligkeit von dir hinübergeht. Bei deiner Bosheit jauchzest du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Einen grünen Ölbaum, schön von Frucht, von Gestalt, nannte Jehovah deinen Namen. Mit der Stimme eines großen Brausens zündet Er ein Feuer wider ihn an und sie zerbrechen seine Äste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Und Jehovah der Heerscharen, Der dich gepflanzt, hat Böses über dich geredet wegen der Bosheit des Hauses Israel und des Hauses Jehudah, das sie für sich getan, damit daß sie Mich reizten, daß sie dem Baal räucherten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'Und mir hat es zu wissen getan Jehovah, und ich weiß es, da hast Du ihr Tun mich sehen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'Ich aber war wie ein Leiter der Schafe, der zum Schlachten dargebracht wird, und wußte nicht, daß sie über mich Gedanken dachten: Laßt uns den Baum in seinem Saft verderben und ihn aus dem der Lebenden ausrotten, daß seines Namens nicht mehr werde gedacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Du aber, Jehovah der Heerscharen, bist ein gerechter Richter, prüfest Nieren und Herz. Laß Deine Rache mich an ihnen sehen; denn Dir habe ich meinen Hader geoffenbart.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Darum, so spricht Jehovah über die Männer Anathoths, die dir nach der Seele trachten und sagen: Weissage nicht in Jehovahs Namen, daß du nicht durch unsere Hände sterbest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'Darum, so spricht Jehovah der Heerscharen: Siehe, Ich werde sie heimsuchen; die Jünglinge sollen durch das Schwert sterben, ihre Söhne und ihre Töchter vor Hunger sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'Und kein Überrest wird von ihnen sein, denn Böses lasse Ich kommen über die Männer Anathoths im Jahre ihrer Heimsuchung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Gerecht bist Du, Jehovah, wenn ich mit Dir hadere, doch will ich von Gerichten mit Dir reden. Warum gelingt der Weg der Ungerechten? behaglich sind alle Treulosen, die treulos handeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Du pflanztest sie, auch wurzeln sie. Sie gehen und bringen auch Frucht. Nah bist Du ihrem Mund, und fern von ihren Nieren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Du aber kennst mich, Jehovah, Du siehst mich und prüfst mein Herz bei Dir. Reiße sie weg wie Schafe zur Schlachtung und heilige sie für den Tag des Würgens!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Wie lange soll das Land trauern und das Kraut auf allem Felde verdorren ob der Bosheit derer, die darin wohnen, Vieh und Gevögel weggerafft werden, weil sie sagen: Er sieht nicht auf unser Letztes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Wenn du mit Fußgängern läufst, und sie dich ermüden, wie willst du es Rossen gleichtun? und wenn im Land des Friedens du vertraust, und was tust du, bei des Jordans Hochmut?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Denn auch deine Brüder und deines Vaters Haus, auch sie wurden dir treulos, auch sie riefen vollauf dir nach. Glaube ihnen nicht, wenn Gutes sie mit dir reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Mein Haus habe Ich verlassen, Mein Erbe hingegeben, habe das Liebste Meiner Seele in die Hand ihrer Feinde gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Mein Erbe ist Mir wie der Löwe im Wald geworden, gibt seine Stimme wider Mich hervor, darum hasse Ich es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Ist ein buntfarbiger Raubvogel Mir Mein Erbe? Raubvögel ringsum wider dasselbe. Geht, sammelt alles wilde Tier des Feldes! Bringt es her zum Fraß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Viele Hirten haben Meinen Weinberg verdorben, Meinen Teil zertreten, sie machen den Teil Meines Begehrens zur Wüste der Einöde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Zur Verwüstung hat man ihn gemacht. Er trauert vor Mir, verwüstet und wüste gelegt ist das ganze Land; denn kein Mann ist da, der es zu Herzen nimmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Über alle Anhöhen in der Wüste kommen die Verheerer; denn Jehovahs Schwert frißt vom Landesende und bis zum Landesende. Kein Fleisch hat Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Weizen säen sie und ernten Dornen, mühen sich ab und haben keinen Nutzen. Und ihr schämt euch eures Ertrages vor der Entbrennung von Jehovahs Zorn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'So spricht Jehovah: Über alle Meine bösen Nachbarn, die das Erbe anrühren, das Ich Mein Volk Israel erben ließ: Siehe, Ich reiße sie aus ihrem Boden und das Haus Jehudah reiße Ich aus ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'Und soll geschehen, wenn Ich sie ausgerissen habe, daß Ich Mich zurückwende und ihrer Mich erbarme, und sie zurückbringe; jeden Mann in sein Erbe und jeden Mann in sein Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Und soll geschehen, wenn sie die Wege Meines Volkes lernen, zu schwören bei Meinem Namen: Beim Leben Jehovahs, wie sie Mein Volk gelehrt hatten, beim Baal zu schwören, so sollen sie inmitten Meines Volkes aufgebaut werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Wo aber sie nicht hören, will Ich solche Völkerschaft ausreißen und zerstören, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'So spricht zu mir Jehovah: Gehe und kaufe dir einen leinenen Gurt und lege ihn um deine Lenden, aber bring ihn nicht ins Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Und ich kaufte den Gurt nach dem Wort Jehovahs und legte ihn um meine Lenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Und es geschah Jehovahs Wort an mich zum zweitenmal, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Nimm den Gurt, den du gekauft, der um deine Lenden ist, und stehe auf und gehe nach dem Phrath und lege ihn da hehlings in die Kluft der Felsenklippe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Und ich ging und legte ihn hehlings an dem Phrath so, wie Jehovah mir geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Und es geschah am Ende vieler Tage, daß Jehovah zu mir sprach: Stehe auf, gehe nach dem Phrath und nimm von da den Gurt, den Ich dir gebot allda hehlings hinzulegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Und ich ging nach dem Phrath und ich grub und nahm den Gurt vom Ort, da ich ihn hehlings hingelegt hatte, und siehe, der Gurt war verdorben, daß er zu nichts mehr taugte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Und es geschah an mich Jehovahs Wort, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'So spricht Jehovah: Ebenso will Ich verderben den Stolz Jehudahs und den vielen Stolz Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'Dies böse Volk, sie, die sich weigern zu hören auf Meine Worte, die hingehen in der Verstocktheit ihres Herzens und anderen Göttern nachgehen, ihnen zu dienen und sie anzubeten, soll werden gleich wie dieser Gurt, der zu nichts taugt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Denn wie der Gurt anhaftet an des Mannes Lenden, so habe Ich Mir lassen anhaften das ganze Haus Israels und das ganze Haus Jehudahs, spricht Jehovah, daß es Mir sei zum Volk und zum Namen und zum Lob und zum Schmuck, aber sie haben nicht gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'So sage ihnen dies Wort: So spricht Jehovah, der Gott Israels: Jeglicher Schlauch wird mit Wein gefüllt! Und sagen sie zu dir: Wissen wir nicht, daß jeglicher Schlauch soll mit Wein gefüllt werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'So sprich zu ihnen: So spricht Jehovah: Siehe, Ich erfülle alle, die in diesem Lande wohnen, und die Könige, die von David auf seinem Throne sitzen, und die Priester und die Propheten und alle Bewohner Jerusalems, mit starkem Getränk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'Und will zerstreuen den Mann mit seinem Bruder und die Väter und die Söhne allzumal, spricht Jehovah. Ich will nicht Mitleid haben, noch schonen, und Mich nicht erbarmen, daß Ich sie nicht verderbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Höret und nehmt zu Ohren, seid nicht hoffärtig. Denn Jehovah redet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Gebet Jehovah, eurem Gott, die Herrlichkeit, bevor Er es finster werden läßt und bevor eure Füße sich stoßen an den Bergen der Dämmerung und ihr hoffet auf Licht; Er aber wird es zum Todesschatten machen, und in Wolkendunkel setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Und wenn ihr nicht darauf hört, wird meine Seele im Verborgenen weinen ob dem Hochmut und mein Auge tränt und fließt in Tränen herab, daß Jehovahs Herde gefangengenommen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Saget dem Könige und der Gebieterin: Erniedrigt euch, setzt euch hin, denn herabgefallen ist euer Kopfputz, die Krone eures Schmuckes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Des Mittags Städte sind geschlossen und niemand öffnet sie; ganz Jehudah ist weggeführt, weggeführt ist Schelomim!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Erhebet eure Augen und sehet, die da kommen von Mitternacht! Wo ist nun die Herde, die dir gegeben war, die Herde, deines Schmuckes?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Was wirst du sagen, wenn Er über dir heimsucht? Und du hast sie gelehrt als Leiter über dich zum Haupte zu sein. Sollten nicht Geburtsnöte dich ergreifen, wie ein Weib, die gebären soll?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Und wenn du sprichst in deinem Herzen: Warum ist solches mir begegnet? Ob der Menge deiner Missetat wurden deine Säume aufgedeckt und deinen Fersen wurde Gewalt angetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'Kann auch ein Mohr seine Haut wandeln, und ein Pardel seine Flecken? So vermöchtet auch ihr Gutes zu tun, die ihr gelernt habt, Böses tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Und Ich will sie zerstreuen wie die Spreu, die bei der Wüste Wind vorüberfährt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'Das soll dein Los sein, dein Anteil, von Mir dir zugemessen, spricht Jehovah, daß du hast Mein vergessen und auf die Lüge vertraust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Und Ich will auch deine Säume entblößen über dein Angesicht, daß deine Unehre gesehen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Deine Ehebrüche und dein Wiehern, die Unzucht deiner Buhlerei auf den Hügeln, im Felde, deine Scheusale habe Ich gesehen. Wehe dir, Jerusalem, willst du dich nicht hernachmals reinigen? Wie lange noch?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Was als Jehovahs Wort geschah an Jirmejahu über das Wort der Dürre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Jehudah trauert und seine Tore verschmachten, verdüstert bis zur Erde, und das Klagegeschrei Jerusalems steigt auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Und ihre Stattlichen senden nach Wasser ihre Geringen. Sie kommen zu den Graben, sie finden kein Wasser, leer kehren ihre Gefäße zurück. Sie sind beschämt und in Schande, und haben verhüllt ihr Haupt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Weil der Boden klaffet, denn kein Regen war im Land. Beschämt sind die Ackerleute, sie haben verhüllt ihr Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Denn auch die Hindin auf dem Felde gebiert und verläßt es, weil kein junges Grün da ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'Und Waldesel stehen auf den Anhöhen, schnappen nach Wind wie die Walfische, ihre Augen sind verzehrt, denn kein Kraut ist da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Wenn unsere Missetaten wider uns antworten, o Jehovah, tue Du es um Deines Namens willen; denn viel sind unserer Abwendungen; wider Dich haben wir gesündigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'Du Hoffnung Israels, Du, sein Retter zur Zeit der Drangsal, warum willst Du sein wie ein Fremdling in dem Lande, und wie ein Wanderer, der einkehrt, um zu übernachten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Warum bist Du wie ein verlegener Mann, wie ein Held, der nicht zu retten vermag? Und Du bist in unserer Mitte, Jehovah, und Dein Name wird über uns genannt. Laß nicht ab von uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'So spricht Jehovah zu diesem Volke: So lieben sie es umherzuwandern, und halten ihre Füße nicht zurück, und Jehovah hat kein Gefallen an ihnen. Jetzt gedenkt Er ihrer Missetat und sucht heim ihre Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'Und Jehovah sprach zu mir: Bete nicht für dieses Volk zum Guten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Wenn sie gleich fasten, höre Ich nicht auf ihren Klageruf, und wenn sie gleich Brandopfer und Speiseopfer darbringen, habe Ich kein Gefallen; mit Schwert und mit Hunger und mit Pestilenz mache Ich sie alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Und ich sagte: Ach, Herr Jehovah, siehe, die Propheten sagen ihnen: Ihr werdet kein Schwert sehen und Hunger wird nicht bei euch sein, sondern der Wahrheit Frieden gebe ich euch an diesem Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Jehovah aber sprach zu mir: Lüge weissagen die Propheten in Meinem Namen, Ich habe sie nicht gesandt und ihnen nicht geboten und nicht zu ihnen geredet. Ein Gesicht der Lüge und Wahrsagerei und Nichtiges und den Trug ihres Herzens weissagen sie euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Darum spricht also Jehovah über die Propheten, die weissagen in Meinem Namen und Ich habe sie nicht gesandt, und die da sagen: Schwert und Hunger wird nicht sein in diesem Lande: Durch Schwert und Hunger sollen diese Propheten umkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Und hingeworfen wird das Volk, dem sie geweissagt, auf die Gassen Jerusalems vor dem Hunger und dem Schwert und ist niemand, der sie begräbt, sie, ihre Weiber und ihre Söhne und ihre Töchter, und Ich schütte über sie ihre Bosheit aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Und du sprich dieses Wort zu ihnen: Nacht und Tag fließen herab mit Tränen Meine Augen, und wollen nicht stille sein, denn mit großem Bruch ist die Jungfrau, die Tochter Meines Volkes zerbrochen, mit einem sehr schmerzhaften Schlage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Gehe Ich hinaus auf das Feld, und siehe, vom Schwert Erschlagene; und komme Ich in die Stadt, und siehe, Erkrankungen vom Hunger; denn beide, der Prophet wie der Priester, wandern im Land umher und wissen nichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Hast Du Jehudah ganz verschmäht? Ist Deine Seele Zijons überdrüssig? Warum hast Du uns geschlagen, daß keine Heilung für uns da ist? Wir hofften auf Frieden und da war nichts Gutes, und auf eine Zeit der Heilung, und siehe, Schrecknis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Jehovah, wir erkennen unsere Ungerechtigkeit, unserer Väter Missetat, daß wider Dich wir sündigten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Verwirf nicht um Deines Namens willen, verunehre nicht den Thron Deiner Herrlichkeit; gedenke, mache nicht zunichte Deinen Bund mit uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Ist da einer der Nichtigkeiten der Völkerschaften, der regnen lassen kann, und können die Himmel Regengüsse geben? Bist Du es nicht, Jehovah, unser Gott? Und auf Dich hoffen wir; denn Du tust alles dies.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'Und Jehovah sprach zu mir: Ständen Mose und Samuel vor Meinem Angesicht, so wäre Meine Seele doch nicht für dieses Volk. Sende sie von Meinem Angesicht, daß sie hinausgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'Und es geschehe, wenn sie zu dir sagen: Wohin sollen wir hinausgehen? so sprich zu ihnen: So spricht Jehovah! Die, so da sind für den Tod, zum Tode; die für das Schwert, zum Schwert; die für den Hunger, zum Hunger; und die für die Gefangenschaft, zur Gefangenschaft!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Und mit vier Arten suche Ich sie heim, spricht Jehovah, mit dem Schwerte, sie zu erwürgen, und mit den Hunden, sie herumzuschleifen, und mit dem Gevögel der Himmel und dem Getier der Erde, sie zu fressen und zu verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'Und Ich gebe sie zu einer Aufregung für alle Königreiche der Erde, wegen Menascheh, dem Sohne Jechiskijahus, des Königs von Jehudah, ob dem, das er getan hat in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Denn wer wird dich bemitleiden, Jerusalem, und wer dich bedauern, und wer sich hinwenden, um nach deinem Frieden zu fragen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Du hast Mich aufgegeben, spricht Jehovah, bist hinter dich gegangen. Und Ich habe Meine Hand über dich ausgereckt, daß Ich dich verderbe, Ich bin des Tröstens müde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Und will sie mit der Worfschaufel zu des Landes Toren hinausschaufeln, kinderlos machen, zerstören Mein Volk, da sie von ihren Wegen nicht zurückkehrten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Zahlreicher werden Mir seine Witwen als der Sand der Meere, und Ich bringe über die Mutter des Jünglings den Verheerer am Mittage, und lasse plötzlich über sie fallen Wehen und Bestürzung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Es verschmachtet die, so sieben geboren, sie haucht ihre Seele aus, ihre Sonne geht unter, während es noch Tag ist. Sie ist beschämt und errötet; und ihren Überrest gebe Ich dem Schwerte vor ihren Feinden, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, 'Wehe mir, meine Mutter, daß du mich geboren! Ein Mann des Haders bin ich und ein Mann des Rechtens für das ganze Land. Ich lieh nicht und sie liehen mir nicht. Sie alle doch fluchen mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Es sprach Jehovah: Lasse Ich dich nicht befreien zum Guten, lasse Ich nicht vermitteln für dich beim Feind zur Zeit des Übels und zur Zeit der Drangsal?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'Wird denn zerbrochen werden das Eisen, das Eisen von Mitternacht und das Erz?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Dein Vermögen und deine Schätze will Ich ohne Kaufpreis zum Raube geben, und das um all eurer Sünden willen, und in allen euren Grenzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'Und Ich lasse deine Feinde übergehen in ein Land, das du nicht kennst. Denn Feuer ist angefacht in Meinem Zorn, über euch lodert es auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'Du weißt es, Jehovah, gedenke meiner und suche mich heim, und räche mich an meinen Verfolgern. Nimm mich nicht hin in Deiner Langmut, wisse, daß ob Deiner ich Schmach trage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Deine Worte wurden gefunden und ich verzehrte sie, und Deine Worte wurden mir zur Freude und zur Fröhlichkeit meines Herzens; denn Dein Name ward über mich genannt, Jehovah, Gott der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Ich saß nicht in dem Kreis der Scherzenden und jauchzte. Einsam saß ich vor Deiner Hand; denn mit Unwillen hattest Du mich erfüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Warum ist mein Schmerz immerwährend und meine Wunde verzweifelt, weigert sich zu heilen? Bist du wirklich mir falsch, Wasser, die nicht währen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Darum, so spricht Jehovah: So du zurückkehrst und Ich dich zu Mir zurückwende, sollst du vor Meinem Angesicht stehen und wenn du herausbringst das Kostbare von dem Mißachteten, sollst du sein, wie Mein Mund. Sie sollen zu dir zurückkehren und du sollst dich nicht zu ihnen zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'Und Ich mache dich für dies Volk zu einer befestigten Mauer von Erz, und sie werden streiten wider dich, werden aber nichts wider dich vermögen; denn Ich bin mit dir, dir zu helfen und dich zu erretten, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'Und Ich will dich erretten aus der Hand der Bösen und dich loskaufen aus der Faust der Trotzigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'Und es geschah das Wort Jehovahs an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Du sollst dir kein Weib nehmen und keine Söhne, noch Töchter haben an diesem Ort!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Denn also spricht Jehovah über die Söhne und über die Töchter, die an diesem Ort geboren werden, und über ihre Mütter, die sie gebären, und über ihre Väter, die sie in diesem Lande zeugen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Sie, die des Todes sterben an Krankheiten, sollen nicht beklagt noch begraben werden; zum Dünger sollen sie auf des Bodens Oberfläche werden, und sollen durch das Schwert und durch Hunger alle werden und ihre Leichen zum Fraß dem Gevögel des Himmels und dem Getier der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Denn also spricht Jehovah: Gehe nicht hinein in das Haus des Klageschreis, und gehe nicht zu klagen, noch ihnen Beileid zu erzeigen, denn weggenommen habe Ich Meinen Frieden von diesem Volke, spricht Jehovah, die Barmherzigkeit und die Erbarmungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'Und Kleine und Große werden in diesem Lande sterben, nicht begraben werden sie und nicht wird um sie geklagt werden, und man wird sich ihretwegen nicht ritzen, noch sich kahl machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'Und sie werden ihnen nichts austeilen ob der Trauer, ihn zu trösten über den Toten, sie auch nicht mit des Trostes Becher tränken über seinen Vater und über seine Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Und in das Haus des Gastmahls sollst du nicht eingehen, mit ihnen zu sitzen, zu essen und zu trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Denn also spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich lasse von diesem Ort zu Ende kommen vor euren Augen und in euren Tagen die Stimme der Fröhlichkeit, die Stimme des Bräutigams und die Stimme der Braut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'Und soll geschehen, wenn du alle diese Worte diesem Volk ansagst und sie zu dir sprechen: Warum denn hat Jehovah all dies große Übel über uns geredet, und was ist unsere Missetat und was unsere Sünde, die wir gesündigt wider Jehovah, unseren Gott?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'So sollst du zu ihnen sagen: Dafür, daß eure Väter Mich verlassen haben, spricht Jehovah, und gingen anderen Göttern nach, und haben denselben gedient und sie angebetet und Mich verlassen, und haben Mein Gesetz nicht gehalten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Und ihr noch ärger tut, denn eure Väter, und siehe, ihr geht, jeder Mann der Verstockt- heit seines bösen Herzens nach, daß er nicht hört auf Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Und Ich will euch schleudern aus diesem Lande in das Land, das ihr nicht kennt, weder ihr, noch eure Väter. Und dort mögt ihr anderen Göttern dienen bei Tag und bei Nacht, wo Ich euch keine Gnade geben werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Darum seht: Tage kommen, spricht Jehovah, daß man nicht mehr sagen wird: Jehovah lebt, Der die Söhne Israels heraufgebracht hat aus dem Lande Ägypten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'Sondern: Jehovah lebt, Der die Söhne Israels heraufgebracht hat aus dem Land der Mitternacht und aus allen Ländern, dahin Ich sie verstoßen hatte; und Ich will sie wiederbringen auf ihren Boden, den Ich ihren Vätern gegeben hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Siehe, Ich sende nach vielen Fischern, spricht Jehovah, und sie fischen sie, und danach sende Ich nach vielen Jägern, und sie erjagen sie von jedem Berg und von jedem Hügel und aus den Klüften der Felsenklippen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Denn Meine Augen sind auf allen ihren Wegen; sie können sich vor Meinem Angesichte nicht verbergen, und nicht ist verdeckt vor Meinen Augen ihre Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Und Ich vergelte vorerst zweifach ihre Missetat und ihre Sünde, darum, daß sie Mein Land entweiht haben mit dem Leichnam ihrer Scheusale, und mit ihren Greueln Mein Erbe angefüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'Jehovah, meine Stärke und meine Feste und meine Zuflucht am Tag der Drangsal! Zu Dir werden die Völkerschaften kommen vom Äußersten der Erde und sagen: Nur Lüge haben unsere Väter als Erbe gehabt, Nichtigkeit, und worin kein Nutzen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Kann der Mensch sich Götter machen? Und Götter sind sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Darum siehe, Ich tue ihnen zu wissen diesmal, Ich tue ihnen Meine Hand und Meine Macht zu wissen, auf daß sie wissen, daß Mein Name ist Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Die Sünde Jehudahs ist geschrieben mit eisernem Griffel, mit der Spitze des Demants auf die Tafel ihres Herzens und auf die Hörner eurer Altäre eingegraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'Gleichwie ihre Söhne gedenken ihrer Altäre und ihrer Ascheren bei grünem Baum auf den hohen Hügeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Mein Berg im Felde, dein Vermögen, all deine Schätze gebe Ich dem Raube hin, deine Opferhöhen, ob der Sünde in allen deinen Grenzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'Und du wirst, und zwar von dir selbst, von deinem Erbe ablassen, das Ich dir gab, und Ich werde dich deinem Feinde dienen lassen in einem Land, das du nicht kennst; denn ihr habt in Meinem Zorn ein Feuer angefacht, das ewiglich wird lodern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'So spricht Jehovah: Verflucht der Mann, der auf den Menschen vertraut, und Fleisch zu seinem Arme setzt, und sein Herz abwendet von Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Und wird sein wie ein bloßes Gesträuch in der Einöde, und nicht sehen, wenn Gutes kommt, und wird wohnen in versengten Orten in der Wüste in salzigem Land, da niemand wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Gesegnet ist der Mann, der vertraut auf Jehovah und dessen Vertrauen Jehovah ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Und er ist wie der Baum, gepflanzt am Wasser, der seine Wurzeln ausstreckt an die Wasserleitung, und sieht es nicht, wenn die Hitze kommt. Sein Blatt ist grün, und hat nichts zu sorgen in dem Jahr der Dürre und läßt nicht ab, Frucht zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Hinterlistig ist das Herz über alles und ein verzweifelt Ding. Wer kennt es?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Ich, Jehovah, erforsche das Herz, Ich prüfe die Nieren, und gebe dem Mann nach seinen Wegen, nach der Frucht seines Tuns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Ein Rebhuhn, das da sammelt, aber nicht legt, ist, wer Reichtum gewinnt nicht mit Recht. In der Hälfte seiner Tage wird er ihn verlassen, und zuletzt ist er ein Tor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Der Thron der Herrlichkeit, die Höhe von Anbeginn ist der Ort unseres Heiligtums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'Jehovah, Hoffnung Israels, alle, die Dich verlassen, werden beschämt, Abtrünnige müssen in die Erde geschrieben werden; denn sie haben den Born lebendiger Wasser, Jehovah, verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Heile mich, Jehovah, so werde ich heil; rette Du mich, so bin ich gerettet; denn mein Lob bist Du!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Siehe, sie sprechen zu mir: Wo ist das Wort Jehovahs? O, so komme es doch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'Ich aber drängte mich nicht danach, daß ich nicht ein Hirte wäre hinter Dir her und ersehnte den Tag der Verzweiflung nicht. Du weißt es, was von meinen Lippen ausging, war vor Deinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Sei Du mir nicht zum Entsetzen! Mein Verlaß bist Du am Tag des Übels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Laß sie sich schämen, die mich verfolgen, und lasse mich nicht beschämt werden. Laß sie sich entsetzen, aber ich sei nicht entsetzt. Bringe über sie den Tag des Übels und zerbrich sie mit zweifacher Zerbrechung!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Also sprach zu mir Jehovah: Gehe hin und stehe im Tor der Söhne des Volkes, durch das die Könige Jehudahs eingehen und durch das sie ausgehen, und in allen Toren Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'Und sprich zu ihnen: Höret das Wort Jehovahs, ihr Könige Jehudahs und ganz Jehudah und alle Bewohner Jerusalems, die zu diesen Toren eingehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'So spricht Jehovah: Hütet euch für eure Seelen und tragt keine Last am Tage des Sabbaths, daß ihr sie einbringt durch die Tore Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Und bringt keine Last aus euren Häusern am Tage des Sabbaths und tut keine Arbeit und heiligt den Tag des Sabbaths, wie Ich geboten habe euren Vätern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'Und sie hörten nicht und neigten nicht ihr Ohr und sie verhärteten ihren Nacken, daß sie nicht hörten und keine Zucht annahmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'Und es soll geschehen, so ihr hört auf Mich, spricht Jehovah, daß ihr keine Last einbringt zu den Toren dieser Stadt am Tage des Sabbaths und heiligt den Tag des Sabbaths, daß ihr an ihm keine Arbeit tut:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'Dann sollen Könige und Oberste, sitzend auf Davids Thron, eingehen zu den Toren dieser Stadt, fahrend auf Streitwagen und auf Rossen, sie und ihre Obersten, der Mann Jehudahs und Jerusalems Bewohner, und diese Stadt soll ewiglich bewohnt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'Und sollen kommen die aus den Städten Jehudahs und den Umgebungen Jerusalems, und aus dem Lande Benjamins und aus der Niederung und vom Gebirge und vom Mittag, und hereinbringen Brandopfer und Schlachtopfer und Speiseopfer und Weihrauch, und bringen herein Dankopfer zum Haus Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Und wenn ihr nicht auf Mich hört, daß ihr den Tag des Sabbaths heiligt, und keine Last tragt und damit eingeht zu den Toren Jerusalems am Tage des Sabbaths, so will Ich ein Feuer anzünden in seinen Toren, und es wird die Paläste Jerusalems auffressen, und nicht erlöschen..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Das Wort, das an Jirmejahu von Jehovah geschah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Stehe auf und gehe in des Töpfers Haus hinab, und da will Ich dich Meine Worte hören lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Und ich ging in des Töpfers Haus hinab, und siehe, er tat Arbeit auf der Scheibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'Und das Gefäß, das er machte, verdarb, wie der Ton unter des Töpfers Hand; und er kehrte um und machte ein anderes Gefäß daraus, wie es in des Töpfers Augen recht war zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Und es geschah Jehovahs Wort an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Vermag Ich nicht, wie der Töpfer da, mit euch zu tun, ihr vom Hause Israel? spricht Jehovah. Siehe, wie der Ton ist in des Töpfers Hand, so seid ihr in Meiner Hand, Haus Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Im Augenblicke rede Ich über eine Völkerschaft und über ein Königreich, daß Ich es ausreißen und abbrechen und zerstören will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'Kehret aber diese Völkerschaft von ihrer Bosheit um, dawider Ich geredet, so gereut Mich des Bösen, das Ich ihm zu tun gedachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Und im Augenblick rede Ich über eine Völkerschaft und über ein Königreich, daß Ich es bauen und pflanzen will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'Und tut es, was böse in Meinen Augen ist, daß es nicht auf Meine Stimme hört, so reut Mich des Guten, davon Ich sprach ihm wohlzutun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Und nun sprich doch zu dem Manne Jehudahs und zu Jerusalems Bewohnern, sprechend: Also spricht Jehovah: Siehe, Ich bilde Böses wider euch und denke einen Gedanken über euch. Kehre doch um, ein jeder Mann von seinem bösen Weg, und macht eure Wege und euer Tun gut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Sie aber sprechen: Vergeblich! Denn nach unseren Gedanken wandeln wir, und tun ein jeder Mann nach der Verstocktheit seines bösen Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Darum spricht also Jehovah: Fragt doch unter den Völkerschaften: Wer hat solches gehört? Gar Schauerhaftes tut die Jungfrau Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Verläßt auch der Schnee des Libanon vom Felsen Meine Felder? Werden auch die fremden, kalten, rieselnden Wasser ausgerottet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Dennoch vergißt Meiner Mein Volk und räuchert dem Eitlen; und sie lassen sie straucheln auf ihren Wegen, den ewigen Fußpfaden, zu gehen auf Steigen, einen ungebahnten Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'Daß sie ihr Land zur Verwüstung machen, zum Gezische ewiglich, daß jeder, der vorüberzieht, erstaune und den Kopf schüttle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Wie der Ostwind will Ich sie zerstreuen vor dem Feind. Mit dem Nacken und nicht dem Angesicht will Ich sie ansehen am Tage Not.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Sie aber sprechen: Gehet zu, laßt uns ratschlagen wider Jirmejahu; denn nicht wird das Gesetz dem Priester verlorengehen und dem Weisen der Rat und das Wort dem Propheten. Gehet zu, und laßt uns ihn schlagen mit der Zunge und nicht horchen auf alle seine Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'So horche Du auf mich, Jehovah, und höre auf die Stimme meiner Haderer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Darf man Gutes mit Bösem vergelten, daß meiner Seele sie eine Fallgrube graben? Gedenke, wie ich vor Dir stand Gutes für sie zu reden, um Deinen Grimm von ihnen zurückzuwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Darum gib ihre Söhne dem Hunger hin und reiße sie hin in die Macht des Schwertes, daß ihre Weiber kinderlos und Witwen seien, und ihre Männer in den Tod hingewürgt, ihre Jünglinge werden vom Schwert geschlagen im Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Man höre Geschrei aus ihren Häusern, daß plötzlich Du über sie die Kriegshaufen hereingebracht, weil sie eine Fallgrube gegraben, mich zu fangen, und meinen Füßen hehlings Schlingen gelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Und Du, Jehovah, weißt all ihren Rat wider mich zum Tode. Überdecke nicht ihre Missetat und wische nicht aus ihre Sünde vor Deinem Angesicht, laß sie straucheln vor Deinem Angesicht, zur Zeit Deines Zornes handle mit ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'So sprach Jehovah: Gehe hin und kaufe einen Krug vom Töpfer des Geschirrs, und mit etlichen von den Ältesten des Volkes und von den Ältesten der Priester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'Und gehe hinaus nach der Schlucht Ben-Hinnoms, das am Eingang zum Tore der Scherben ist, und rufe aus allda die Worte, die Ich zu dir reden werde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'Und sprich: Höret das Wort Jehovahs, Könige Jehudahs und Bewohner Jerusalems! So spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich bringe Böses über diesen Ort, daß jedem, der es hört, seine Ohren gellen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Darum, daß sie Mich verließen und diesen Ort Mir entfremdeten und darin anderen Göttern räucherten, die sie nicht kannten, weder sie noch ihre Väter, noch Jehudahs Könige, und diesen Ort mit dem Blut Unschuldiger erfüllten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'Und dem Baal Opferhöhen bauten, um im Feuer ihre Söhne zu verbrennen als Brandopfer dem Baal, was Ich nicht geboten, noch geredet hatte: und was Mir nicht ins Herz aufgestiegen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'Darum, seht, es kommen Tage, spricht Jehovah, daß diesen Ort man nicht mehr Topheth und die Schlucht Ben-Hinnom, sondern die Schlucht des Würgens nennen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'Und vereiteln will Ich an diesem Ort den Rat Jehudahs und Jerusalems, und sie durch das Schwert vor ihren Feinden fallen lassen, und durch die Hand derer, die nach ihrer Seele trachten und ihren Leichnam zum Fraß dem Gevögel des Himmels und dem Getier der Erde geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'Und diese Stadt will Ich zur Verwüstung machen und zum Gezisch. Ein jeder, der an ihr vorübergeht, soll ob ihr erstaunen und zischen über alle ihre Schläge,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'Und lasse sie essen das Fleisch ihrer Söhne und das Fleisch ihrer Töchter, und der Mann wird das Fleisch seines Genossen essen in der Belagerung und der Beängstigung, mit der sie ihre Feinde und die, so ihnen nach der Seele trachten, beängstigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Und du sollst den Krug zerbrechen vor der Männer Augen, die mit dir gegangen sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'Und sollst zu ihnen sprechen: Also spricht Jehovah der Heerscharen: So zerbreche Ich dieses Volk und diese Stadt, wie einer des Töpfers Gefäß zerbricht, daß man es nicht wieder heilen kann. Und in Topheth werden sie begraben, weil sonst kein Ort mehr ist zu begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'So werde Ich, spricht Jehovah, diesem Ort und seinen Bewohnern tun, daß Ich diese Stadt wie Topheth mache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'Und es sollen die Häuser Jerusalems und die Häuser der Könige Jehudahs, die unreinen, werden wie der Ort Topheth, alle die Häuser, auf deren Dächern sie geräuchert allem Heer der Himmel, und Trankopfer gegossen anderen Göttern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Und Jirmejahu kam von Topheth, wo Jehovah ihn hingesandt zu weissagen, und stand in dem Vorhof von Jehovahs Haus und sprach zu allem Volk:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'So spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich bringe herein über diese Stadt und über alle ihre Städte all das Böse, das Ich über sie geredet habe, weil sie ihren Nacken verhärten und auf Meine Worte nicht hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Und Paschchur, Immers Sohn, des Priesters, der zum Fürsten im Hause Jehovahs bestellt war, hörte Jirmejahu solche Worte weissagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'Und Paschchur schlug den Propheten Jirmejahu und tat ihn in den Block, der im oberen Tore Benjamins, im Hause Jehovahs war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Und am morgenden Tag geschah, daß Paschchur Jirmejahu aus dem Blocke herausbrachte, und Jirmejahu sprach zu ihm: Nicht Paschchur hat Jehovah deinen Namen genannt, sondern Magor ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Denn also hat Jehovah gesprochen: Siehe, Ich gebe dich dem Bangen hin, dich und alle deine Liebhaber, und fallen sollen sie durch das Schwert ihrer Feinde, und deine Augen es sehen, und ganz Jehudah gebe Ich in die Hand von Babels König, daß er sie gen Babel wegführe und mit dem Schwert sie schlage;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Und Ich gebe allen Reichtum dieser Stadt und all ihren Erwerb und alle ihre Kostbarkeit, und alle Schätze der Könige Jehudahs gebe Ich in ihrer Feinde Hand, daß sie sie berauben und nehmen und nach Babel bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Und du, Paschchur, und alle Bewohner deines Hauses, ihr werdet in die Gefangenschaft gehen, und nach Babel wirst du kommen und dort sterben und dort begraben werden, du und alle deine Liebhaber, denen du mit Lüge geweissagt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Und Du hast mich beredet, Jehovah, und ich ließ mich bereden, Du hast mich erfaßt und hast mich übermocht. Alltäglich werde ich zum Gelächter. Sie alle verlachen mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Denn sooft ich rede, muß ich schreien, Gewalttat und Verwüstung rufen; denn den ganzen Tag ist mir Jehovahs Wort zu Schmach und Schimpf geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Und ich sprach: Ich will Seiner nicht gedenken, nicht mehr in Seinem Namen reden; und es ward in meinem Herzen wie ein brennend Feuer, zurückgehalten in meinem Gebein und ich mühte mich ab, an mich zu halten und ich vermochte es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Denn vieler Gerede höre ich, Bangen ringsum. Sagt an! wir wollen es ansagen! Alle Männer meines Friedens, Hüter meiner Seite: Vielleicht läßt er sich überreden, daß wir ihn übermögen und unsere Rache an ihm nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Aber Jehovah ist mit mir, wie ein gewaltiger Held, darum werden, die mich verfolgen, straucheln und nichts vermögen, sehr beschämt werden, daß sie nicht verständig handelten, zu ewiger Schande, die nie vergessen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Und Du, Jehovah der Heerscharen, Der Du prüfst den Gerechten, Du siehst Nieren und Herz, laß Deine Rache mich an ihnen sehen; denn auf Dich habe meinen Hader ich gewälzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Singet Jehovah, lobet Jehovah, daß Er die Seele des Dürftigen aus der Hand der Boshaften errettet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Verflucht sei der Tag, an dem ich geboren ward! der Tag, an dem mich meine Mutter gebar, sei nicht gesegnet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Verflucht der Mann, der meinem Vater die Botschaft brachte und sprach: Dir ist ein Sohn, ein Männliches geboren, und ihn fröhlich machte!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'Und selbiger Mann sei wie die Städte, die Jehovah umgekehrt und es nicht bereut hat. Und er höre Geschrei am Morgen und Feldgeschrei zur Mittagszeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'O, daß man mich nicht tötete vom Mutterschoße an, und meine Mutter mir zum Grabe ward und ewig schwanger ging ihr Mutterschoß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Wozu ging ich hervor aus dem Mutterschoß, zu sehen Mühsal und Gram und daß in Beschämung meine Tage alle werden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Das Wort, das von Jehovah an Jirmejahu geschah, als König Zidkijahu Paschchur, Malchijahs Sohn, und Zephanjah, den Sohn Maasejahs, den Priester, zu ihm sandte und ihm sagen ließ:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Frage doch nach bei Jehovah für uns; denn Nebuchadrezzar, der König von Babel, streitet wider uns: Vielleicht tut Jehovah uns nach allen Seinen Wundern, daß Er von uns hinaufzöge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Und Jirmejahu sprach zu ihnen: So sollt ihr zu Zidkijahu sagen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'So spricht Jehovah, der Gott Israels: Siehe, Ich will die Waffen des Krieges umwenden, die ihr in eurer Hand habt, damit ihr streitet wider Babels König und die Chaldäer, die euch belagern außerhalb der Mauer, und Ich will sie versammeln inmitten dieser Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'Und Ich werde streiten wider euch mit ausgereckter Hand, und mit starkem Arm, und mit Zorn und mit Grimm, und mit großer Entrüstung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'Und werde schlagen die Bewohner dieser Stadt, beide, den Menschen und das Vieh, sie sollen sterben durch große Pest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Und danach gebe Ich, spricht Jehovah, Zidkijahu, Jehudahs König, und seine Knechte und das Volk, und die von der Pestilenz, vom Schwert und vom Hunger verblieben in dieser Stadt, in die Hand von Nebuchadrezzar, Babels König, und in die Hand ihrer Feinde und in die Hand derer, die ihnen nach der Seele trachten, daß er sie schlage mit der Schärfe des Schwertes und sie nicht schone, und kein Mitleid mit ihnen und kein Erbarmen habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Und zu diesem Volke sollst du sagen: So spricht Jehovah: Siehe, Ich habe vor euch gegeben den Weg des Lebens und den Weg des Todes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Wer in dieser Stadt wohnen bleibt, wird sterben durch das Schwert und vom Hunger und von der Pestilenz; wer aber hinausgeht und den Chaldäern zufällt, die euch belagern, wird leben und soll seine Seele zur Beute haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Denn Ich setze Mein Angesicht wider diese Stadt zum Bösen und nicht zum Guten, spricht Jehovah; in die Hand von Babels König soll sie gegeben werden, daß er sie mit Feuer verbrenne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Und ihr vom Hause von Jehudahs König, höret das Wort Jehovahs!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'Haus Davids, so spricht Jehovah: Rechtet im Gericht am Morgen und errettet den Ausgeplünderten aus der Hand des Erpressers, daß nicht wie Feuer ausgehe Mein Grimm und brenne, daß niemand lösche ob der Bosheit eures Tuns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Siehe, Ich bin wider dich, Bewohnerin des Talgrundes, du Fels der Ebene, spricht Jehovah, die ihr sprechet: Wer fährt wider uns herab, und wer mag in unsere Wohnstätten kommen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'Ich aber will euch heimsuchen nach der Frucht eures Tuns, spricht Jehovah, und anzünden ein Feuer in ihrem Wald, daß es auffresse alles rings um sie her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'So spricht Jehovah: Gehe hinab in das Haus des Königs von Jehudah und rede allda dieses Wort');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'Und sprich: Höre das Wort Jehovahs, König Jehudahs, der du auf dem Throne Davids sitzest, du und deine Knechte und dein Volk, die eingehen zu diesen Toren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'So spricht Jehovah: Tuet Recht und Gerechtigkeit, und errettet den Ausgeplünderten aus der Hand des Erpressers, und den Fremdling, die Waise und die Witwe bedrücket nicht, übet nicht Gewalttat und vergießet kein unschuldig Blut an diesem Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'So ihr nach diesem Worte tut, dann werden durch dieses Hauses Tore Könige eingehen, die dem David auf seinem Throne sitzen, fahrend auf Streitwagen und auf Rossen, sie und ihre Knechte und ihr Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'So aber ihr nicht hört auf diese Worte, schwöre Ich bei Mir, spricht Jehovah, daß dieses Haus zur Verödung werden soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Denn also spricht Jehovah über das Haus des Königs von Jehudah: Ein Gilead warst du Mir, das Haupt des Libanons; werde Ich dich nicht zur Wüste setzen, zu Städten, die nicht bewohnt sind?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'Und Ich heilige Verderber wider dich, den Mann und seine Waffen, daß sie die Auswahl deiner Zedern umhauen und sie fällen für das Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Und viele Völkerschaften werden an dieser Stadt vorübergehen und sprechen, der Mann zu seinen Genossen: Warum hat dieser großen Stadt Jehovah so getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'Und werden sagen: Darum, daß sie den Bund Jehovahs, ihres Gottes, verließen, und andere Götter anbeteten und ihnen dienten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Weint nicht über den Toten und tragt nicht Leid um ihn, weint vielmehr über den, der hingeht und nicht mehr zurückkehrt und sieht das Land seiner Geburt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Denn also spricht Jehovah über Schallum, Joschijahus Sohn, Jehudahs König, der an seines Vaters Joschijahus Statt König ist, der von diesem Orte ausgezogen. Er wird nimmer dahin zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'Denn an dem Orte, da sie ihn weggeführt, dort wird er sterben und dieses Land nicht mehr sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Wehe dem, der sein Haus baut ohne Gerechtigkeit und seine Söller ohne Recht, der seines Genossen sich bedient umsonst und ihm seinen Arbeitslohn nicht gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'Der sagt: Ich will ein Haus mir bauen nach dem Maßstab, und luftige Söller! und Fenster sich aushaut und es mit Zedern täfelt, und mit Bergrot bestreicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Solltest du König sein, daß du in Zedern wetteiferst? Dein Vater, aß und trank er nicht auch, und tat Recht und Gerechtigkeit? Dann war es gut mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Er rechtete dem Elenden und Dürftigen die Rechtssache, da war es gut. Heißt das nicht Mich erkennen? spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Denn deine Augen und dein Herz sind auf nichts aus, als auf deinen Gewinn, und auf unschuldig Blut, zu vergießen, und auf Erpressung und Plackerei, um es zu üben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Darum, so spricht Jehovah zu Jehojakim, Joschijahus Sohn, dem Könige Jehudahs, sie werden nicht um ihn klagen: O weh, mein Bruder! Und wehe, Schwester! Sie werden nicht um ihn klagen: O weh dem Herrn, und wehe der Majestät!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Mit dem Begräbnis eines Esels wird er begraben, geschleift und hingeworfen au-ßerhalb der Tore Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Steige hinauf auf den Libanon und schreie, gib deine Stimme in Baschan hervor, und schreie von Abarim; denn alle, die dich liebten, sind zerbrochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Ich redete zu dir in deiner Behaglichkeit. Du sprachst: Ich will es nicht hören. Dies war dein Weg von deiner Jugend auf, daß du auf Meine Stimme nicht hörtest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'All deine Hirten weidet ab der Wind, und deine Liebhaber gehen in Gefangenschaft. Denn beschämt und zuschanden wirst du dann ob aller deiner Bosheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'Die du wohntest auf dem Libanon, nistetest in den Zedern, wie wirst du begnadigt werden, wenn Geburtsnöten dich und ein Kreißen ankommen, wie die Gebärende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Bei Meinem Leben, spricht Jehovah, wärst du auch Chonjahu, der Sohn Jojakims, der König von Jehudah, der Siegelring an Meiner rechten Hand, abreißen müßte Ich dich von da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'Und habe dich in die Hand derer gegeben, die dir nach der Seele trachten, und in die Hand derer, vor deren Angesicht du bangst, und in Nebuchadrezzars Hand, des Königs von Babel, und in die Hand der Chaldäer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'Und Ich schleudere dich und deine Mutter, die dich geboren hat, in ein anderes Land, da ihr nicht seid geboren; und allda sollt ihr sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'Und nach dem Lande, wohin sie erheben ihre Seele dahin zurückzukehren, dorthin sollen sie nicht zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Ist dieser Mann Chonjahu denn ein verachtetes, zerschelltes Gebilde, ein Gefäß, an dem man keine Lust hat? Warum schleudern sie ihn und seinen Samen hin und werfen ihn in ein Land, das sie nicht kannten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'O Land, Land, Land! Höre Jehovahs Wort!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'So spricht Jehovah: Schreibet diesen Mann als kinderlos, als einen Mann, der kein Gelingen hat in seinen Tagen; denn nicht wird es einem Mann aus seinem Samen gelingen, daß er auf Davids Thron sitze und noch über Jehudah herrsche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Wehe euch Hirten, die ihr die Herde Meiner Weide zerstört und zerstreut! spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Darum spricht also Jehovah, der Gott Israels, über die Hirten, die Mein Volk weiden: Ihr habt zerstreut Meine Herde und sie versto-ßen und sie nicht heimgesucht. Siehe, heimsuchen will Ich an euch die Bosheit eures Tuns, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Und Ich will Meiner Herde Überrest zusammenbringen aus allen Ländern, wohin Ich sie verstoßen, und sie zurückbringen zu ihren Hürden, daß sie fruchtbar seien und sich mehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'Und Ich will Hirten einsetzen über sie, daß sie sie weiden, und sie sich nicht mehr fürchten noch entsetzen und keine vermißt werden, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Siehe, Tage kommen, spricht Jehovah, da Ich dem David einen gerechten Sproß erstehen lasse, daß Er als König regiere und klüglich handle, und tue Recht und Gerechtigkeit auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'In Seinen Tagen wird Jehudah gerettet werden, und Israel wohnen in Sicherheit, und dies ist Sein Name, womit man Ihn nennen wird: Jehovah, unsere Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Darum siehe, Tage kommen, spricht Jehovah, da man nicht mehr sagen wird: Beim Leben Jehovahs, Der die Söhne Israels heraufgebracht hat aus dem Land Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'Vielmehr: Beim Leben Jehovahs, Der den Samen des Hauses Israels heraufgeführt und hereingebracht hat aus dem Land gen Mitternacht und aus allen Landen, wohin Ich sie verstoßen, auf daß sie auf ihrem Boden wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'Ob den Propheten bricht mein Herz in meinem Inneren; all meine Gebeine sind durchschauert. Mir ist wie einem trunkenen Mann, und wie dem Menschen, den der Wein hat überkommen, vor Jehovah und vor den Worten Seiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Denn voll von Ehebrechern ist das Land, denn wegen der Verwünschung trauert das Land, verdorren der Wüste Auen; und ihr Lauf ist böse und ihre Macht nicht richtig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Denn Heuchler sind sowohl Prophet als auch Priester. Auch in Meinem Hause finde Ich ihre Bosheit, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Darum ist ihr Weg für sie wie das Schlüpfrige in der Dunkelheit; sie werden gestoßen und fallen drin; denn Übel bringe Ich über sie im Jahr ihrer Heimsuchung, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Und an Samariens Propheten sah Ich Torheit; sie weissagten durch den Baal und führten in die Irre Mein Volk Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Aber bei den Propheten Jerusalems sah Ich Schauerliches, Ehebruch und Wandel in der Lüge, und sie stärkten der Bösen Hände, auf daß kein Mann von seiner Bosheit umkehre. Wie Sodom sind sie alle Mir geworden und ihre Bewohner wie Gomorrah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Darum spricht Jehovah der Heerscharen also über die Propheten: Siehe, Ich lasse sie Wermut essen und Wasser der Galle trinken; denn von Jerusalems Propheten geht aus Heuchelei durch das ganze Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Also spricht Jehovah der Heerscharen: Höret nicht auf die Worte der Propheten, die euch weissagen; sie machen euch nichtig, sie reden das Gesichte ihres Herzens, nicht aus Jehovahs Mund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Sie sprechen zu denen, die mich lästern: Jehovah hat geredet: Friede wird mit euch sein; und zu jedem, der in der Verstocktheit seines Herzens wandelt, sprechen sie: Kein Böses kommt über euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Denn wer steht im geheimen Rat Jehovahs, daß er sehe und höre Sein Wort? Wer horcht auf Sein Wort und hört darauf?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Siehe, ein Wetter Jehovahs, Grimm geht aus, und ein Wetter wälzt sich daher und kreist über der Ungerechten Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Der Zorn Jehovahs kehrt nicht zurück bis Er es getan, bis Er erstehen läßt die Beschlüsse Seines Herzens. In den letzten der Tage werdet ihr es mit Einsicht einsehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Ich sandte die Propheten nicht und doch liefen sie. Ich redete nicht zu ihnen und doch weissagten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Und wären sie in Meinem geheimen Rat gestanden und ließen sie Mein Volk Meine Worte hören, so brächten sie sie zurück von ihrem bösen Weg und von der Bosheit ihres Tuns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Bin Ich ein Gott von nahe, spricht Jehovah, und nicht ein Gott von ferne?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Kann sich ein Mann in Verborgenheit verbergen, daß Ich ihn nicht sähe? spricht Jehovah. Erfülle Ich nicht die Himmel und die Erde? spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Ich hörte was die Propheten sagen, die in Meinem Namen Lüge weissagen, sie sagen: Ich träumte, ich träumte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Wie lange noch ist etwas in dem Herzen der Propheten, die Lüge weissagen und weissagen den Betrug ihres Herzens?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'Die denken, daß sie Mein Volk Meinen Namen vergessen lassen mit ihren Träumen, die der Mann erzählt seinem Genossen, gleichwie ihre Väter Meinen Namen ob dem Baal vergaßen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Ist einem Propheten ein Traum geworden, erzähle er den Traum; und bei dem Mein Wort ist, der rede Mein Wort der Wahrheit. Was soll das Stroh beim Getreide? spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Ist nicht Mein Wort gleich wie das Feuer? spricht Jehovah, und wie der Hammer, der die Felsenklippe zerschellen läßt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Darum siehe, spricht Jehovah, Ich bin wider die Propheten, die Meine Worte stehlen, der Mann von seinem Genossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Siehe, Ich bin wider die Propheten, spricht Jehovah, die ihre Zunge nehmen und damit einen Spruch sprechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Siehe, Ich bin wider die, so Träume der Lüge weissagen, spricht Jehovah, und sie erzählen und Mein Volk mit ihren Lügen und ihrer Leichtfertigkeit irreführen, und Ich habe sie nicht gesandt, noch ihnen geboten und sie nützen keinen Nutzen diesem Volk, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Und wenn dies Volk dich fragt, sei es ein Prophet oder ein Priester, und spricht: Was ist Jehovahs Last? so sage ihnen, was die Last ist: Ich gebe euch dahin! spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Und wo der Prophet und der Priester und das Volk spricht: eine Last Jehovahs, den Mann werde Ich samt seinem Haus heimsuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'So sollt ihr sprechen, ein Mann zu seinem Genossen und ein Mann zu seinem Bruder: Was hat geantwortet Jehovah, und was hat geredet Jehovah?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, 'Und einer Last Jehovahs sollet ihr nicht mehr gedenken; denn zur Last soll einem Manne sein Wort werden. Und ihr kehret um die Worte des lebendigen Gottes, Jehovahs der Heerscharen, unseres Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Zu dem Propheten sollst du also sprechen: Was hat Jehovah dir geantwortet und was hat Jehovah geredet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Und wenn ihr Last Jehovahs sprechet, darum, so spricht Jehovah, darum, daß ihr dies Wort Jehovahs Last gesprochen, und Ich zu euch sandte und euch sagte: Ihr sollt nicht sprechen: Jehovahs Last,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'Darum, siehe, so vergesse Ich euch gänzlich und gebe euch dahin und die Stadt, die Ich euch und euren Vätern gegeben, hinweg von Meinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'Und lege ewige Schmach auf euch und ewige Schande, die nicht vergessen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Jehovah ließ mich sehen und siehe, da waren zwei Körbe mit Feigen gestellt vor Jehovahs Tempel, nachdem Nebuchadrezzar, Babels König, Jechonjahu, den Sohn Jehojakims, Jehudahs König, und die Obersten Jehudahs, die Werkleute und Schlosser aus Jerusalem weggeführt und nach Babel hineingebracht hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'Der eine Korb hatte sehr gute Feigen, wie die Erstlinge der Feigen, und der andere Korb sehr schlechte Feigen, die man vor Schlechtigkeit nicht essen konnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'Und Jehovah sprach zu mir: Was siehst du, Jirmejahu? Und ich sprach: Feigen. Die guten Feigen sind sehr gut und die schlechten sind sehr schlecht, so daß man sie vor Schlechtigkeit nicht ißt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Und es geschah an mich das Wort Jehovahs und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'So spricht Jehovah, der Gott Israels: Wie diese guten Feigen, so will Ich die Weggeführten Jehudahs zum Guten erkennen, die Ich aus diesem Orte nach der Chaldäer Land habe gesendet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Und will Mein Auge auf sie richten zum Guten und sie in dieses Land zurückbringen, und sie aufbauen und nicht umreißen, und sie pflanzen und nicht ausrotten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'Und Ich will ihnen ein Herz geben, daß sie Mich kennen, daß Ich Jehovah bin, und sie sollen Mein Volk werden, und Ich werde ihnen Gott sein, wenn sie von ganzem Herzen zu Mir zurückkehren werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Aber wie die schlechten Feigen, die man nicht ißt vor Schlechtigkeit, fürwahr, so spricht Jehovah, also will Ich geben Zidkijahu, Jehudahs König, und seine Obersten und den Überrest Jerusalems, der verblieb in diesem Land, und die, so im Lande Ägypten wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Und will sie geben zur Aufregung, zum Übel für alle Reiche der Erde, zur Schmach und zum Sprichwort, zur Stachelrede und zum Fluch an allen Orten, dahin Ich sie verstoße;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'Und Ich sende unter sie das Schwert, den Hunger und die Pestilenz, bis sie gar aus sind von dem Boden, den Ich ihnen und ihren Vätern gegeben hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Das Wort, welches geschah an Jirmejahu über alles Volk Jehudahs im vierten Jahre Jehojakims, des Sohnes Joschijahus, König von Judah, welches ist das erste Jahr Nebuchadrezzars, des Königs von Babel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'Das Jirmejahu, der Prophet, redete zu allem Volk Jehudahs und zu allen Bewohnern Jerusalems, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Von dem dreizehnten Jahre Joschijahus, des Sohnes Amons, König von Judah an und bis auf diesen Tag, diese dreiundzwanzig Jahre her ist das Wort Jehovahs an mich geschehen, und ich redete früh aufstehend und redend, und ihr habt nicht gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Und Jehovah sandte an euch alle seine Knechte, die Propheten, früh aufstehend und sendend, ihr aber habt sie nicht gehört, und euer Ohr nicht geneigt, auf daß ihr hörtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'Sie sprachen: Kehret doch zurück, jeder Mann von seinem bösen Wege und von der Bosheit eurer Taten, und ihr sollt auf dem Boden, den Jehovah euch und euren Vätern gegeben hat, von Ewigkeit und bis zu Ewigkeit wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'Und gehet keinen anderen Göttern nach, ihnen zu dienen und sie anzubeten, daß ihr Mich nicht reizet durch eurer Hände Tun, euch Böses zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Ihr aber hörtet nicht auf Mich, spricht Jehovah, daß ihr Mich reiztet durch eurer Hände Tun, euch Böses zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Darum, so spricht Jehovah der Heerscharen: Weil ihr nicht auf Meine Worte hörtet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'Siehe, so sende Ich aus und nehme alle Familien der Mitternacht, spricht Jehovah, und Nebuchadrezzar, Babels König, Meinen Knecht, und bringe sie herein wider dieses Land und wider seine Bewohner, und wider alle diese Völkerschaften ringsumher; daß Ich sie verbanne und setze sie zur Wüstenei und zum Gezisch und zu ewigen Verödungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'Und Ich will von ihnen vergehen lassen die Stimme der Freude und die Stimme der Fröhlichkeit, die Stimme des Bräutigams und die Stimme der Braut, die Stimme der Mühle und das Licht der Lampe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'Und dieses ganze Land wird zur Öde und zur Wüstenei werden; und sollen diese Völkerschaften dem König Babels siebzig Jahre dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'Und es wird geschehen, wenn siebzig Jahre voll sind, daß Ich heimsuche an Babels König und an jener Völkerschaft, spricht Jehovah, ihre Missetat und an der Chaldäer Land, und Ich setze sie zu ewigen Wüsteneien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'Und Ich bringe über dieses Land herein alle Meine Worte, die Ich über dasselbe geredet, alles, was in diesem Buch geschrieben ist, das Jirmejahu über alle Völkerschaften geweissagt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Denn die vielen Völkerschaften und großen Könige sollen sie dienstbar machen, auch sie, und nach ihrem Werke und ihrer Hände Tun vergelte Ich ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Denn also spricht zu mir Jehovah, der Gott Israels: Nimm diesen Becher Wein des Grimmes aus Meiner Hand, und lasse daraus trinken alle Völkerschaften, zu denen Ich dich senden werde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'Auf daß sie trinken und schwanken und rasen vor dem Schwerte, das Ich sende unter sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Und ich nahm den Becher aus der Hand Jehovahs und ließ trinken alle Völkerschaften, zu denen mich Jehovah sendete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jerusalem und Jehudahs Städte, und ihre Könige und ihre Obersten, sie zu geben zur Verödung, zur Wüstenei, zum Gezisch und zum Fluch, wie an diesem Tag;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Den Pharao, Ägyptens König, und seine Knechte und seine Obersten und all sein Volk:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'Und alle gegen Abend und alle Könige des Landes Uz, und alle Könige des Landes der Philister, und Aschkalon und Gazah und Ekron und Aschdods Überrest;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edom und Moab und Ammons Söhne;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'Und alle Könige von Zor und alle Könige von Zidon, und die Könige der Inseln, die jenseits des Meeres sind;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedan und Thema und Bus und alle, welche die Ecke stutzen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'Und alle Könige Arabiens und alle Könige des Abends, die in der Wüste wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'Und alle Könige von Simri und alle Könige von Elam und alle Könige Madais;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'Und alle Könige von Mitternacht, die nahen und die fernen, den Mann zu seinem Bruder, und alle Königreiche der Erde, die auf der Oberfläche des Bodens sind, und nach ihnen soll König Scheschach trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'Und sprich zu ihnen: So spricht Jehovah der Heerscharen, der Gott Israels: Trinket und werdet trunken, und speiet und fallet und stehet nicht auf vor dem Schwerte, das Ich sende unter euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Und wenn geschieht, daß sie sich weigern, den Becher aus deiner Hand zu nehmen, zu trinken, so sprich zu ihnen: Also spricht Jehovah der Heerscharen: Ihr sollt gewißlich trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Denn siehe, der Stadt, über der Mein Name genannt wird, fange Ich an, Übles anzutun. Und ihr, ihr wollt straflos sein? Ihr sollt nicht straflos sein! Denn Ich rufe ein Schwert über alle Bewohner der Erde, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Und du, weissage über sie alle diese Worte und sprich zu ihnen: Jehovah brüllt aus der Höhe und gibt Seine Stimme hervor aus der Wohnstätte Seiner Heiligkeit; Er brüllt wider Seinen Wohnort, antwortet im Kelterlied wie die Keltertreter, allen, so auf Erden wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Es kommt ein Tosen bis ans Ende der Erde; denn im Hader ist Jehovah mit den Völkerschaften. Er richtet alles Fleisch. Die Ungerechten - Er gibt sie dem Schwerte, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'So spricht Jehovah der Heerscharen: Siehe, Böses zieht aus von Völkerschaft zu Völkerschaft, ein großes Wetter wird erweckt von der Erde Seiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'Und die Erschlagenen Jehovahs sind an jenem Tag von einem Ende der Erde bis zum anderen Ende der Erde; sie werden nicht beklagt, noch gesammelt, noch begraben, sie werden zu Dünger auf der Fläche des Bodens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Heulet, ihr Hirten und schreiet, wälzet euch umher ihr Stattlichen der Herde, denn eure Tage zum Schlachten sind erfüllt, und Ich zerschelle euch und ihr fallet wie ein köstliches Gefäß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'Und die Zuflucht vergeht für die Hirten, und das Entkommen für die Stattlichen der Herde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Die Stimme des Schreiens der Hirten! und ein Heulen von den Stattlichen der Herde; denn ihre Weide hat verheert Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'Und von der Glut des Zornes Jehovahs gehen unter die Hürden des Friedens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Verlassen hat Er Seine Hütte wie der junge Löwe; denn eine Wüstenei ist ihr Land geworden vor der Glut des Bedrückers und vor der Glut seines Zornes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'Im Anfang der Regierung Jehojakims, des Sohnes Joschijahus, des Königs von Jehudah, geschah von Jehovah dieses Wort, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'So spricht Jehovah: Stehe in den Vorhof von Jehovahs Haus und rede zu allen Städten Jehudahs, die hereinkommen, im Haus Jehovahs anzubeten, all die Worte, die Ich dir gebiete, zu ihnen zu reden, und sollst kein Wort davontun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Vielleicht hören sie darauf und der Mann kehrt von seinem bösen Wege zurück, daß Mich des Bösen gereue, das Ich dachte ihnen zu tun, ob der Bosheit ihrer Taten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Und sprich zu ihnen: So spricht Jehovah: Wenn ihr nicht auf Mich hört, so daß ihr wandelt in Meinem Gesetz, das Ich vor euch gegeben habe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'So daß ihr hört auf die Worte Meiner Knechte, der Propheten, die Ich an euch sandte, früh aufstehend und sendend, aber ihr hörtet nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'So gebe Ich dieses Haus dahin wie Schiloh, und diese Stadt gebe Ich zum Fluch allen Völkerschaften auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Und die Priester und die Propheten und alles Volk hörten Jirmejahu diese Worte im Hause Jehovahs reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'Und es geschah, wie Jirmejahu vollendet hatte, alles zu reden, was ihm Jehovah vor dem ganzen Volk zu reden geboten hatte, da faßten ihn an die Priester und die Propheten und alles Volk und sprachen: Du mußt des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Warum weissagst du im Namen Jehovahs und sprichst: Wie Schiloh soll dies Haus werden, und diese Stadt soll verödet werden, so daß niemand darin wohne? Und alles Volk kam zusammen im Hause Jehovahs wider Jirmejahu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Und als die Obersten Jehudahs hörten diese Dinge, kamen sie herauf vom Königshause zum Haus Jehovahs und setzen sich am Eingang des neuen Tores Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Und die Priester und die Propheten sprachen zu den Obersten und zu dem ganzen Volk und sagten: Ein Gericht des Todes für diesen Mann; denn er hat wider diese Stadt geweissagt, wie ihr mit euren Ohren hörtet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Und Jirmejahu sprach zu all den Obersten und zu allem Volk und sagte: Jehovah hat mich gesandt über dieses Haus und über diese Stadt alle die Worte zu weissagen, die ihr gehört habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Und nun macht eure Wege gut und eure Taten und hört auf die Stimme Jehovahs eures Gottes, daß Jehovah gereue des Bösen, das Er wider euch geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Und siehe, ich bin in eurer Hand, tut mit mir, wie es gut und recht in euren Augen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Nur sollt ihr wissen, daß ihr, wenn ihr mich tötet, unschuldig Blut bringt über euch und über diese Stadt, und über die, so in ihr wohnen; denn in Wahrheit hat Jehovah mich zu euch gesandt, in euren Ohren zu reden alle diese Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Und es sprachen die Obersten und das ganze Volk zu den Priestern und zu den Propheten: Für den Mann da gibt es kein Gericht des Todes; denn im Namen Jehovahs unseres Gottes, hat er zu uns geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'Und es standen Männer von den Ältesten des Landes auf und sprachen zur ganzen Versammlung des Volkes und sagten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Michajah, der Moraschthite, war ein Prophet in den Tagen Chiskijahus, des Königs von Jehudah, und sprach zu allem Volk Jehudahs und sagte: So spricht Jehovah der Heerscharen: Zijon soll als Feld gepflügt und Jerusalem zu Trümmerhaufen und der Berg des Hauses zu Opferhöhen des Waldes werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'Hat Chiskijahu, Jehudahs König, und ganz Jehudah ihn getötet? Hat er nicht Jehovah gefürchtet und angefleht das Angesicht Jehovahs? Und es reute Jehovah wegen des Bösen, das Er wider sie geredet. Wir aber tun großes Übel wider unsere Seelen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, 'Und es war auch ein Mann, der weissagte im Namen Jehovahs, Urijahu, Schemajahus Sohn, aus Kirjath-Jearim, und er weissagte wider diese Stadt und wider dieses Land nach allen Worten Jirmejahus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'Und König Jehojakim und alle seine Mächtigen und alle Obersten hörten seine Worte, und der König suchte ihn zu töten, und Urijahu hörte es und fürchtete sich und entwich, und kam nach Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Und König Jehojakim sandte Männer nach Ägypten, Elnathan, Achbors Sohn, und Männer mit ihm nach Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'Und sie brachten Urijahu heraus aus Ägypten und brachten ihn herein zum König Jehojakim und er schlug ihn mit dem Schwerte, und warf seinen Leichnam hin bei den Gräbern der Söhne des Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Doch die Hand Achikams, des Sohnes Schaphans, war mit Jirmejahu, daß man ihn nicht in die Hand des Volkes gab, um ihn zu töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'Im Anfang der Regierung Jehojakims, des Sohnes Joschijahus, König von Jehudah, geschah dies Wort an Jirmejahu von Jehovah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'So spricht Jehovah zu mir: Mache dir Bande und Jochhölzer und gib sie auf deinen Hals.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Und sende sie an den König Edoms und an den König Moabs und an den König der Söhne Ammons und an den König Zors und an den König Zidons durch die Hand der Boten, die gen Jerusalem zu Zidkijahu, Jehudahs König, kamen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'Und gebiete ihnen an ihre Herren, zu sagen: So spricht Jehovah der Heerscharen, der Gott Israels: So sollt ihr euren Herren sagen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Ich habe gemacht die Erde und den Menschen und das Vieh, die auf den Angesichten der Erde sind, durch Meine große Kraft und Meinen ausgestreckten Arm, und gebe sie, wem es recht in Meinen Augen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'Und nun habe Ich alle diese Länder in die Hand Nebuchadnezzars, des Königs von Babel, Meines Knechtes, gegeben; und auch das wilde Tier des Feldes habe Ich ihm gegeben, daß sie ihm dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'Und alle Völkerschaften sollen dienen ihm und seinem Sohn, und seines Sohnes Sohn, bis auch seines Landes Zeit kommt, und viele Völkerschaften und große Könige es dienstbar machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Und soll geschehen, daß die Völkerschaft und das Königreich, das ihm, Nebuchadnezzar, Babels König, nicht dienen und seinen Hals nicht in das Joch des Königs von Babel geben will, Ich solche Völkerschaft mit Schwert und mit Hunger und mit Pest heimsuche, spricht Jehovah, bis daß Ich es durch seine Hand umkommen lasse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Und ihr sollt nicht hören auf eure Propheten und auf eure Wahrsager und auf eure Träume und auf eure Wolkendeuter und auf eure Zauberer, die zu euch sprechen und sagen: Ihr sollt Babels König nicht dienen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Denn Lüge weissagen sie euch, von eurem Boden euch zu entfernen, und daß Ich euch verstoße und ihr vergeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Aber die Völkerschaft, die ihren Hals hineingibt in das Joch von Babels König und ihm dient, das lasse Ich auf seinem Boden, spricht Jehovah, daß es ihn baue und darauf wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'Und zu Zidkijah, Jehudahs König, habe ich geredet, nach allen diesen Worten und gesagt: Bringt euren Hals hinein in das Joch von Babels König, und dient ihm und seinem Volk, auf daß ihr lebt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Warum doch wollt ihr sterben, du und dein Volk durch das Schwert, durch Hunger und durch Pest, wie Jehovah geredet hat über die Völkerschaft, die Babels König nicht dienen will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Und hört nicht auf die Worte der Propheten, die zu euch sprechen und sagen: Dient Babels König nicht; denn Lüge weissagen sie euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Denn Ich habe sie nicht gesendet, spricht Jehovah, und Lügen weissagen sie in Meinem Namen; auf daß Ich euch verstoße und ihr vergeht, ihr und die Propheten, die euch weissagten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Und zu den Priestern und zu all diesem Volk redete ich und sprach: So spricht Jehovah, hört nicht auf die Worte eurer Propheten, die euch weissagen und sprechen: Siehe, die Gefäße von Jehovahs Haus werden jetzt in Eile von Babel zurückgebracht; denn Lüge weissagen sie euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Hört nicht auf sie, dient dem König Babels, auf daß ihr lebet. Warum soll diese Stadt zur Öde werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Und wenn sie Propheten sind und Jehovahs Wort bei ihnen ist, so laßt sie doch bei Jehovah der Heerscharen vermitteln, daß die Gefäße, die noch übrig sind im Haus Jehovahs und im Haus des Königs von Jehudah und in Jerusalem, nicht auch nach Babel kommen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Denn also spricht Jehovah der Heerscharen von den Säulen und von dem Meer und von den Gestellen und von den übrigen Gefäßen, die noch übriggeblieben sind in dieser Stadt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'Die Nebuchadnezzar, Babels König, nicht von Jerusalem nach Babel genommen hat, da er Jechonjah, Jehojakims Sohn, Jehudahs König mit allen Vornehmen Jehudahs und Jerusalems nach Babel wegführte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'Denn so spricht Jehovah der Heerscharen, der Gott Israels, über die Gefäße, die im Haus Jehovahs und im Haus des Königs von Jehudah und in Jerusalem übriggeblieben sind:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'Nach Babel sollen sie gebracht werden und allda sein bis zu dem Tag, da Ich sie heimsuche, spricht Jehovah, und Ich sie heraufbringe und an diesen Ort zurückbringe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'Und es geschah im selbigen Jahr im Anfang der Regierung Zidkijahs, König von Jehudah, im vierten Jahr im fünften Monat, daß Chananjah, der Sohn Assurs, der Prophet, aus Gibeon zu mir sprach im Haus Jehovahs vor den Augen der Priester und vor allem Volke sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'So spricht Jehovah der Heerscharen, der Gott Israels, sprechend: Zerbrochen habe Ich das Joch von Babels König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'Noch zwei Jahre der Tage, so bringe Ich zurück an diesen Ort alle Gefäße von Jehovahs Haus, die Nebuchadnezzar, Babels König, von diesem Orte genommen und nach Babel gebracht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Und den Jechonjah, den Sohn Jehojakims, König von Jehudah und alle die Weggeführten Jehudahs, die nach Babel gekommen, bringe Ich zurück an diesen Ort, spricht Jehovah; denn Ich zerbreche das Joch des Königs von Babel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Und Jirmejahu, der Prophet, sprach zu Chananjah, dem Propheten, vor den Augen der Priester und vor den Augen des ganzen Volkes, so im Haus Jehovahs standen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'Und Jirmejahu, der Prophet, sprach: Amen! So tue Jehovah! Jehovah bestätige deine Worte, die du geweissagt hast, daß Er die Gefäße des Hauses Jehovahs und alle die Weggeführten aus Babel nach diesem Ort zurückbringe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Nur höre doch dies Wort, das ich in deine Ohren und in die Ohren des ganzen Volkes rede:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Die Propheten, die vor mir und vor dir waren, von der Urzeit her und haben über viele Länder und über große Königreiche geweissagt von Streit und von Bösem und von Pestilenz,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Der Prophet, der zum Frieden weissagt, wenn das Wort des Propheten kommt, wird der Prophet bezeugt, daß ihn Jehovah gesandt hat in Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Und Chananjah, der Prophet, nahm vom Nacken Jirmejahus, des Propheten, das Jochstück ab und zerbrach es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'Und Chananjah sprach vor den Augen des ganzen Volkes und sagte: So spricht Jehovah: Also zerbreche Ich das Joch Nebuchadnezzars, des Königs von Babel, in noch zwei Jahren der Tage von dem Halse aller Völkerschaften. Und der Prophet Jirmejahu ging seines Weges.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Und es geschah das Wort Jehovahs an Jirmejahu, nachdem Chananjah, der Prophet, das Jochstück vom Nacken Jirmejahus, des Propheten, zerbrochen und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Gehe und sprich zu Chananjah und sage: So spricht Jehovah: Die Jochstücke von Holz hast du zerbrochen; so mache nun an ihrer Statt Jochstücke von Eisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Denn also spricht Jehovah der Heerscharen, der Gott Israels: Ein Joch von Eisen gebe Ich auf den Hals all dieser Völkerschaften, Nebuchadnezzar, dem Könige von Babel, zu dienen, und sie müssen dienen ihm, und auch das wilde Tier des Feldes habe Ich ihm gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Und Jirmejahu, der Prophet, sprach zu Chananjah, dem Propheten: Höre doch, Chananjah, Jehovah hat dich nicht gesandt, und du hast dieses Volk auf Lügen vertrauen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Darum spricht Jehovah also: Siehe, Ich sende dich fort von den Angesichten des Bodens; in diesem Jahre stirbst du; denn Abfall von Jehovah hast du geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'Und Chananjah, der Prophet, starb desselbigen Jahres im siebten Monat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'Und dies sind die Worte des Schreibens, das Jirmejahu, der Prophet, von Jerusalem sandte an die übergebliebenen Ältesten der Weggeführten und an die Priester und an die Propheten und an alles Volk, das Nebuchadnezzar von Jerusalem nach Babel wegführte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, 'Nachdem Jechonjah, der König, und die Gebieterin und die Hofbeamten, die Obersten Judahs und Jerusalems, und der Werkmann und der Schlosser von Jerusalem ausgezogen waren,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'Durch die Hand Eleasahs, des Sohnes Schaphans, und Gemarjahs, des Sohnes Chilkijahs, die Zidkijah, der König Jehudahs, an Nebuchadnezzar, Babels König, nach Babel gesandt hatte, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'So spricht Jehovah der Heerscharen, der Gott Israels, zu allen Weggeführten, die Ich von Jerusalem nach Babel weggeführt habe:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Baut Häuser und wohnet und pflanzet Gärten und esset ihre Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Nehmt Weiber und zeugt Söhne und Töchter, und nehmt euren Söhnen Weiber und eure Töchter gebet Männern, daß Söhne und Töchter sie gebären, und ihr euch allda mehret und nicht weniger werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'Und sucht nach dem Frieden der Stadt, dahin Ich euch wegführte, und betet für sie zu Jehovah: denn in ihrem Frieden wird auch für euch Friede werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Denn also spricht Jehovah der Heerscharen, der Gott Israels: Lasset euch nicht verführen von Propheten in eurer Mitte, noch von euren Wahrsagern, und hört nicht auf eure Träume, die ihr euch träumen lasset.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Denn mit Lüge weissagen sie euch in Meinem Namen, Ich habe sie nicht gesandt, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Denn also spricht Jehovah: Wenn siebzig Jahre voll sind für Babel, werde Ich euch heimsuchen und über euch Mein gutes Wort bestätigen, daß Ich euch zurückbringe an diesen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Denn Ich weiß die Gedanken, die Ich denke über euch, spricht Jehovah, Gedanken des Friedens und nicht zum Bösen, euch zu geben eine Zukunft und Hoffnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'Und rufet ihr Mich und wandelt und betet zu Mir, so werde Ich auf euch hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'Und ihr werdet Mich suchen und finden, wenn ihr nach Mir sucht von ganzem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'Und Ich werde Mich von euch finden lassen, spricht Jehovah, und werde zurückwenden eure Gefangenschaft und euch zusammenbringen aus allen Völkerschaften und aus allen Orten, wohin Ich euch verstoßen habe, spricht Jehovah. Und Ich will euch zurückbringen an den Ort, von wo Ich euch weggeführt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Wenn ihr sagt: Jehovah hat uns in Babel Propheten auferstehen lassen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'Nun so sprach Jehovah zu dem König, der auf dem Throne Davids sitzt, und zu allem Volk, das in dieser Stadt wohnt, euren Brüdern, die nicht in die Wegführung mit euch sind ausgezogen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'So spricht Jehovah der Heerscharen: Siehe, Ich sende gegen sie das Schwert, den Hunger und die Pest, und gebe sie wie die herben Feigen, die man nicht essen mag vor Schlechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'Und setze hinter ihnen nach mit dem Schwert, mit Hunger und mit Pest, und mache sie zum Grauen für alle Königreiche der Erde, zur Verwünschung und zur Verwüstung und zum Gezisch und zur Schmach für alle Völkerschaften, wohin Ich sie verstoßen habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'Dafür, daß sie auf Meine Worte nicht gehört, spricht Jehovah, während Ich zu ihnen sandte Meine Knechte, die Propheten, früh aufstehend und sendend, aber ihr hörtet nicht, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'So hört denn ihr das Wort Jehovahs, ihr alle, die ihr weggeführt worden, die Ich von Jerusalem gen Babel habe gesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'So spricht Jehovah der Heerscharen, der Gott Israels, wider Achab, den Sohn Kolajahs, und wider Zidkijahu, Maasejahs Sohn, die euch in Meinem Namen Lüge weissagten: Siehe, Ich gebe sie in die Hand Nebuchadrezzars, des Königs von Babel, und er schlägt sie vor euren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'Und wird genommen werden von ihnen her ein Fluch bei allen Weggeführten Jehudahs in Babel, sprechend: Jehovah mache dich wie Zidkijahu und wie Achab, die Babels König am Feuer gebraten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'Weil sie Torheit in Israel taten und Ehebruch trieben mit den Weibern ihrer Genossen, und in Meinem Namen das Wort der Lüge redeten, welches Ich ihnen nicht geboten hatte. Und Ich, Ich weiß es und bin Zeuge, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Und sprich zu Schemajahu aus Nechalam, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'So spricht Jehovah der Heerscharen, der Gott Israels, sprechend: Darum, daß du unter deinem Namen Briefe an alles Volk, das in Jerusalem ist, und an Zephanjah, Maasejahs Sohn, den Priester, und an alle Priester gesandt hast und gesagt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Jehovah hat dich zum Priester gegeben anstatt des Priesters Jehojada, auf daß ihr sollt Aufseher sein des Hauses Jehovahs, über jeden Mann, der wahnsinnig ist und weissagen will, daß du ihn in Block und Stock legest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Und nun, warum hast du den Jirmejahu von Anathoth nicht bedroht, der euch weissagt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'So hat er denn an uns nach Babel gesendet und gesagt: Es ist noch lange. Bauet Häuser und wohnet und pflanzet Gärten und esset ihre Frucht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Und Zephanjah, der Priester, las diesen Brief vor den Ohren Jirmejahus, des Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'Und es geschah das Wort Jehovahs an Jirmejahu, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Sende an alle Weggeführten, sprechend: So spricht Jehovah zu Schemajah von Nechalam: Weil Schemajah euch geweissagt und Ich ihn nicht gesendet habe; und er euch auf Lüge vertrauen läßt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'Darum spricht also Jehovah: Siehe, Ich suche heim Schemajah aus Nechalam und seinen Samen. Kein Mann sei ihm, der in der Mitte dieses Volkes wohne, und er soll nicht das Gute sehen, das Ich Meinem Volke tue, spricht Jehovah, weil er zum Abfall von Jehovah hat geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Das Wort, das von Jehovah an Jirmejahu geschah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'So spricht Jehovah, der Gott Israels, und sagt: Schreibe dir alle Worte, die Ich zu dir geredet habe, in ein Buch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Denn siehe, Tage kommen, spricht Jehovah, daß Ich die Gefangenschaft Meines Volkes Israel und Jehudah zurückwende, spricht Jehovah, und sie zurückbringe in das Land, das ihren Vätern Ich gegeben hatte, und sie als Erbe es besitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'Und dies sind die Worte, die Jehovah hat geredet an Israel und Jehudah:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Denn also spricht Jehovah: Die Stimme des Erzitterns hörten wir, des Schauers, und keinen Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Fragt doch und sehet, ob das Männliche gebären kann! Warum sehe Ich jeglichen Mann seine Hände an seinen Hüften, wie ein Gebärerin, und alle Angesichte in Blässe verwandelt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Wehe! Denn groß ist dieser Tag, keiner wie er! Und eine Zeit der Drangsal ist er für Jakob. Aber er soll daraus gerettet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Und an selbigem Tage soll geschehen, spricht Jehovah der Heerscharen, daß Ich sein Joch von deinem Hals zerbreche und abreiße deine Bande und Fremde nicht mehr damit ihn dienstbar machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'Und dienen sollen sie Jehovah, ihrem Gott, und David, ihrem König, den Ich ihnen erstehen lasse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Du aber fürchte dich nicht, Mein Knecht Jakob, spricht Jehovah, und entsetze dich nicht, Israel; denn siehe Ich rette dich aus der Ferne, und deinen Samen aus dem Lande ihrer Gefangenschaft, daß Jakob wiederkehre, ruhig und sorglos sei, und niemand ihn aufscheuche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Denn Ich werde mit dir sein, spricht Jehovah, dich zu retten; wenn Ich Vollendung mache mit allen Völkerschaften, unter die Ich dich zerstreute, will Ich nur mit dir keine Vollendung machen, sondern dich züchtigen nach Recht und dich nicht ungestraft lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Denn also spricht Jehovah: Verzweifelt ist dein Bruch, schmerzhaft dein Schlag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Niemand rechtet deine Rechtssache; Heilmittel zum Aufkommen hast du nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Alle deine Liebhaber vergessen dich, sie fragen nicht nach dir. Mit einem Schlage des Feindes schlug Ich dich in grausamer Züchtigung ob der Menge deiner Missetat, zahlreich sind deine Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Was schreist du über deinen Bruch, daß verzweifelt dein Schmerz ist? Ob der Menge deiner Missetat, weil deine Sünden zahlreich sind, habe Ich dir das getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Darum werden alle, die dich auffraßen, aufgefressen, und alle deine Dränger, sie alle ziehen in die Gefangenschaft, und die dich plünderten werden zur Plünderung, und alle, die dich beraubten, gebe Ich dem Raube hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Dir aber bringe Ich Genesung herauf, und heile dich von deinen Schlägen, spricht Jehovah. Denn die Verstoßene nannte man dich, Zijon, nach der niemand fragt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'So spricht Jehovah: Siehe, Ich wende die Gefangenschaft der Zelte Jakobs zurück, und seiner Wohnungen erbarme Ich Mich, und aufgebaut wird die Stadt auf ihrem Schutthaufen und der Palast wird nach seiner Weise bewohnt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'Und von ihnen aus geht Bekenntnis und die Stimme der Spielenden, und Ich will sie mehren und nicht sollen sie sich mindern, und Ich verherrliche sie und sie sollen sich nicht verringern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'Und seine Söhne sollen sein wie vordem, und seine Gemeinde soll vor Mir befestigt werden, und heimsuchen werde Ich all seine Unterdrücker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'Und sein Stattlicher wird aus ihm sein, und sein Herrscher geht aus seiner Mitte hervor, und Ich lasse ihn nahen, und er wird zu Mir herzutreten; denn wer ist es, der sein Herz verbürgt, herzutreten zu Mir, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'Und ihr sollt Mein Volk sein, und Ich will euch Gott sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Siehe ein Wetter Jehovahs, ein Grimm geht aus, ein Wetter rottet sich zusammen und kreist über dem Haupt der Ungerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Die Glut des Zornes Jehovahs geht nicht zurück, bis Er es getan und die Beschlüsse Seines Herzens erstehen läßt. In den letzten Tagen werdet ihr es einsehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'Zur selben Zeit, spricht Jehovah, will Ich allen Familien Israels Gott sein und sie sollen Mir zum Volk sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'So spricht Jehovah: Gnade hat in der Wüste das Volk, der Rest vom Schwert, gefunden, da Er hinging, ihm, Israel, Ruhe zu verschaffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, 'Von Ferne ist Jehovah mir erschienen: Und mit ewiger Liebe habe Ich dich geliebt, darum habe Ich dich hergezogen aus Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Ich baue dich noch, und du sollst erbaut werden, Jungfrau Israel, daß du dich schmückst mit deinen Pauken und im Reigen der Spielenden ausziehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Weinberge sollst du noch pflanzen auf den Bergen Samariens, und die Pflanzer, die sie pflanzten, sollen sie genießen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Denn der Tag ist da! rufen die Wächter auf dem Gebirge Ephraim. Steht auf und laßt uns hinauf gen Zijon, zu Jehovah unserem Gotte, ziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Denn also spricht Jehovah: Jubelt dem Jakob zu in Fröhlichkeit, und laßt es ertönen dem Haupte der Völkerschaften! Laßt es hören, lobet und sprechet: Rette dein Volk, Jehovah, den Überrest von Israel!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Siehe, Ich bringe sie vom Land der Mitternacht, und lasse sie zusammenkommen von den Seiten der Erde, mit ihnen den Blinden und den Lahmen, die Schwangere und die Gebärende allzumal; eine große Versammlung kommen sie hierher zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Mit Weinen kommen sie, und unter Flehen geleite Ich sie und lasse sie zu Wasserbächen gehen auf geradem Weg, da sie nicht straucheln; denn Ich bin Israel zum Vater geworden, und Ephraim, er ist Mein Erst- geborener.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Höret das Wort Jehovahs, Völkerschaften, und sagt es auf den Inseln aus der Ferne an und sprechet: Der Israel zersprengte, bringt es zusammen und hütet es wie ein Hirt seine Herde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Denn Jehovah hat eingelöst Jakob und ihn erlöst aus der Hand des Stärkeren denn er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'Und sie werden kommen und lobpreisen auf Zijons Höhe, und zusammenströmen zum Guten Jehovahs, zum Korn und zum Most und zum Öl und zu dem jungen Kleinvieh und Rind, und ihre Seele wird wie ein bewässerter Garten sein, und sie werden fürder nicht mehr sich betrüben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Dann ist fröhlich die Jungfrau im Reigentanz, und die Jünglinge und die Alten allzumal; und ihre Trauer verwandle Ich in Freude und tröste sie und mache sie fröhlich aus ihrem Gram.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'Und will die Seele der Priester laben mit Fettigkeit, und Mein Volk soll sich an Meinem Guten sättigen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'So spricht Jehovah: Eine Stimme hört man in Ramah, eine Klage, bitterliches Weinen: Rachel weint über ihre Söhne. Sie weigert sich, sich trösten zu lassen über ihre Söhne; denn sie sind nicht da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'So spricht Jehovah: Halt ab deine Stimme vom Weinen, deine Augen von Tränen! Denn ein Lohn wird dir für dein Werk, spricht Jehovah, und sie kommen zurück aus dem Lande des Feindes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'Und Hoffnung ist da für deine Zukunft, spricht Jehovah; und die Söhne werden zurück in ihre Grenze kehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Ich hörte wohl Ephraim sich beklagen: Du hast gezüchtigt mich; und wie ein ungelehriges Kalb ward ich gezüchtigt. Wende mich zurück, so will ich zurückkehren; denn Du, Jehovah, bist mein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Denn, nachdem ich zurückgekehrt bin, fühle ich Reue, und nachdem ich erkenne, schlage ich auf meine Hüfte, fühle ich Scham und Schande; denn ich trage die Schmach meiner Jugend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Ist nicht ein köstlicher Sohn Mir Ephraim, ein Kind des Ergötzens? Denn obschon Ich wider ihn geredet habe, gedenke Ich noch sein. Darum sind Meine Eingeweide rege für ihn, mit Erbarmen will Ich sein Mich erbarmen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Stelle dir Malzeichen auf, setze dir Pfeiler, richte dein Herz auf die Landstraße, den Weg, den du gegangen bist, kehre zurück, Jungfrau Israel, kehre zurück zu diesen deinen Städten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Wie lange willst du umherstreifen, du abwendige Tochter? Denn Jehovah schafft Neues im Lande. Das Weib soll den Mann umgeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'So spricht Jehovah der Heerscharen, der Gott Israels: Sie werden noch sagen dieses Wort im Land Jehudahs und in seinen Städten, wenn Ich ihre Gefangenschaft zurückwende: Es segne Jehovah dich, den Wohnort der Gerechtigkeit, den Berg der Heiligkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'Und wohnen werden darin Jehudah und all seine Städte allzumal, die Ackersleute und die, so mit der Herde ausziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Denn Ich erquicke die matte Seele und erfülle jede Seele, die Leid trägt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Darob erwachte ich und ich sah, und süß war mir mein Schlaf gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Siehe, Tage kommen, spricht Jehovah, da Ich besäen werde das Haus Israels und das Haus Jehudahs mit Samen des Menschen und mit Samen des Viehs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'Und es soll geschehen, wie Ich wachsam war über sie, auszuroden und abzubrechen und niederzureißen und zu zerstören und übel zu tun: so will Ich wachsam sein über sie, sie zu bauen und zu pflanzen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'In selbigen Tagen werden sie nicht mehr sagen: Die Väter haben Herlinge gegessen und den Söhnen sind die Zähne stumpf geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'Sondern ein jeder Mann wird sterben in seiner Missetat. Einem jeden Menschen, der Herlinge ißt, sollen seine Zähne stumpf werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Siehe, Tage kommen, spricht Jehovah, da Ich mit dem Haus Israel und dem Haus Jehudah einen neuen Bund schließen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'Nicht wie der Bund, den Ich mit ihren Vätern schloß, am Tag, da Ich sie an der Hand faßte, sie aus dem Lande Ägypten herauszubringen; weil sie Meinen Bund zunichte gemacht haben, und Ich ward Meister über sie, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Sondern dies wird sein der Bund, den Ich nach jenen Tagen mit dem Hause Israels schließen werde, spricht Jehovah: In ihre Mitte will Ich geben Mein Gesetz und auf ihr Herz es schreiben; und Ich will ihnen zum Gott sein, und sie sollen Mir zum Volke werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'Und nicht mehr werden sie lehren, ein Mann seinen Genossen und ein Mann seinen Bruder, und sagen: Erkennet Jehovah; denn sie alle werden Mich kennen vom Kleinsten unter ihnen bis zu ihrem Größten, spricht Jehovah; denn Ich vergebe ihre Missetat und ihrer Sünde werde Ich nicht mehr gedenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'So spricht Jehovah, Der die Sonne gibt zum Licht bei Tag, die Satzungen des Mondes und der Sterne zum Lichte bei Nacht, Der das Meer aufregt, daß seine Wogen toben. - Jehovah der Heerscharen ist Sein Name:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Wenn diese Satzungen vor Mir weichen, spricht Jehovah, soll auch der Same Israels aufhören, alle die Tage eine Völkerschaft vor Mir zu sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'So spricht Jehovah: Wenn die Himmel oben werden gemessen und der Erde Grundfesten unten erforscht, will auch Ich verschmähen all den Samen Israels wegen alles dessen, was sie getan, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Siehe, Tage kommen, spricht Jehovah, daß die Stadt wird gebaut für Jehovah vom Turm Chananeel bis zum Tore der Ecke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'Und ausgehen soll noch die Meßschnur gegenüber über den Hügel Gareb weg und sich gen Goath herumwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'Und aller Talgrund der Leichen und der Fettasche, und all die Äcker, bis zum Bache Kidron, bis zur Ecke des Tores der Rosse gen Aufgang sollen Jehovah heilig sein, nichts soll da ausgerodet noch niedergerissen werden ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Das Wort, das zu Jirmejahu geschah, von Jehovah, im zehnten Jahr Zidkijahus, des Königs von Jehudah; dieses Jahr war das achtzehnte Jahr Nebuchadrezzars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Und dazumal belagerte die Streitmacht des Königs zu Babel Jerusalem, und Jirmejahu, der Prophet, war eingesperrt im Vorhof der Wacht am Hause des Königs von Judah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Ihn hatte Zidkijahu, Jehudahs König, eingesperrt und sagte: Warum weissagst du und sagst: So spricht Jehovah: Siehe, Ich gebe diese Stadt in die Hand des Königs von Babel und er wird sie erobern?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Und Zidkijahu, Jehudahs König, wird nicht entrinnen aus der Chaldäer Hand; denn gewißlich wird er gegeben in die Hand des Königs von Babel, daß sein Mund zu seinem Munde rede, und seine Augen sehen seine Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'Und nach Babel wird er den Zidkijahu führen; und dort soll er sein, bis Ich ihn heimsuche, spricht Jehovah. Wenn ihr mit den Chaldäern streitet, wird es euch nicht gelingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Und Jirmejahu sprach: Das Wort Jehovahs ist an Mich geschehen, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Siehe, Chanameel, der Sohn des Schallum, deines Oheims, kommt zu dir und spricht: Kaufe für dich mein Feld in Anathoth; denn dein ist das Recht der Einlösung, es zu kaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Und Chanameel, meines Oheims Sohn, kam zu mir nach dem Wort Jehovahs in den Vorhof der Wacht und sprach zu mir: Kaufe doch mein Feld zu Anathoth im Lande Benjamin; denn du hast das Recht des Erbbesitzes und dein ist die Einlösung. Kaufe es für dich. Und ich erkannte, daß es das Wort Jehovahs war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'Und ich kaufte das Feld von Chanameel, dem Sohne meines Oheims, in Anathoth, und wog ihm dar das Silber, sieben Schekel und zehn des Silbers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'Und ich schrieb es in einen Brief und siegelte ihn und bezeugte es mit Zeugen und wog das Silber auf einer Waage;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Und nahm den Kaufbrief, den versiegelten, mit dem Gebot und den Satzungen und den offenen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'Und gab den Kaufbrief an Baruch, den Sohn Nerijahs, Sohn Machsejahs, vor den Augen Chanameels, meines Oheims, und vor den Augen der Zeugen, die in dem Kaufbrief geschrieben waren, und vor den Augen aller Juden, die in dem Vorhof der Wacht saßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'Und ich gebot dem Baruch vor ihren Augen, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'So spricht Jehovah der Heerscharen, der Gott Israels: Nimm diese Briefe, den Kaufbrief da und das Versiegelte, und diesen offenen Brief, und gib sie in ein irdenes Gefäß, auf daß sie auf viele Tage bestehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Denn so spricht Jehovah der Heerscharen, der Gott Israels: Noch wird man Häuser und Felder und Weinberge kaufen in diesem Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'Und ich betete zu Jehovah, nachdem ich den Kaufbrief dem Baruch, Nerijahs Sohn, gegeben hatte und ich sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'O Herr, Jehovah, siehe, Du hast die Himmel und die Erde durch Deine große Kraft und Deinen ausgereckten Arm gemacht. Nichts ist Dir zu wunderbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'Der Barmherzigkeit tut an Tausenden, und der Väter Missetat vergilt in ihrer Söhne Busen nach ihnen, der große, mächtige Gott, Jehovah der Heerscharen ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'Du, groß an Rat und viel an Tat, Dessen Augen aufgetan sind über alle Wege der Söhne des Menschen, dem Manne zu geben nach seinen Wegen und nach seiner Taten Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'Der Du Zeichen setztest und Wahrzeichen im Lande Ägypten bis auf diesen Tag an Israel, und am Menschen gesetzt hast, und Dir einen Namen gemacht, wie es an diesem Tage ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'Und hast Dein Volk Israel aus dem Land Ägypten mit Zeichen herausgebracht und mit Wahrzeichen und mit starker Hand und mit ausgerecktem Arm und mit großer Furcht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'Und ihnen dieses Land gegeben, das Du ihren Vätern geschworen hattest ihnen zu geben, ein Land, da Milch und Honig fließt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Und sie kamen und nahmen es in Besitz, aber sie hörten nicht auf Deine Stimme und wandelten nicht nach Deinem Gesetz; alles, was Du ihnen zu tun geboten hattest, taten sie nicht; und Du ließest ihnen all dies Übel begegnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Siehe, die Wälle sind bis an die Stadt gekommen, sie zu erobern; und die Stadt wird in der Chaldäer Hand, die wider sie streiten, gegeben, Angesichts des Schwertes und des Hungers und der Pest. Und es geschieht, was Du geredet und siehe da, Du siehst es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'Und Du hast zu mir gesprochen, Herr Jehovah: Kaufe dir das Feld mit Silber und laß Zeugen es bezeugen; und die Stadt wird in der Chaldäer Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Und es geschah Jehovahs Wort an Jirmejahu, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Siehe, Ich bin Jehovah, der Gott alles Fleisches. Sollte irgendein Ding vor Mir zu wunderbar sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Darum spricht also Jehovah: Siehe, Ich gebe diese Stadt in der Chaldäer Hand und in die Hand Nebuchadrezzars, des Königs von Babel, daß er sie erobere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'Und die Chaldäer, die wider diese Stadt streiten, werden kommen und diese Stadt mit Feuer anzünden und sie verbrennen samt den Häusern, auf deren Dächern sie dem Baal räucherten und anderen Göttern Trankopfer gossen, um Mich zu reizen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Denn die Söhne Israels und die Söhne Jehudahs taten von Jugend auf nur, was böse war in Meinen Augen. Denn die Söhne Israels reizten Mich nur durch ihrer Hände Tun, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Denn diese Stadt ward Mir zum Zorne und zum Grimme von dem Tage an, da sie sie bauten und bis auf diesen Tag, daß Ich sie von Meinem Angesicht wegtue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'Ob all dem Bösen der Söhne Israels und der Söhne Jehudahs, das sie taten, Mich zu reizen, sie, ihre Könige, ihre Obersten, ihre Priester und ihre Propheten und der Mann Jehudahs und die da wohnen in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Und sie wandten Mir den Nacken zu und nicht das Angesicht, und man belehrte sie, früh aufstehend und lehrend, aber sie hörten es nicht, um Zucht anzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Und setzten ihre Scheusale in das Haus, über dem Mein Name ist genannt, es zu verunreinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'Und sie bauten die Opferhöhen des Baal im Tal Ben-Hinnoms, um ihre Söhne und ihre Töchter dem Molech durchzuführen, was Ich ihnen nicht geboten und Mir nicht in das Herz aufgekommen ist, daß solchen Greuel sie tun sollten, und Jehudah sündig machten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Und nun um dessentwillen spricht also Jehovah, der Gott Israels, von dieser Stadt, von der ihr sprechet: Sie ist gegeben in die Hand des Königs von Babel durch das Schwert und durch Hunger und durch die Pest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Siehe, Ich bringe sie zusammen aus allen Ländern, wohin Ich sie in Meinem Zorn und in Meinem Grimm und in großer Entrüstung verstoßen habe, und bringe sie zurück an diesen Ort und lasse sie wohnen in Sicherheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'Daß sie Mir zum Volk seien, und Ich will ihnen zum Gott sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'Und Ich gebe ihnen ein Herz und einen Weg, zu fürchten Mich alle Tage, ihnen und ihren Söhnen nach ihnen zum Guten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'Und einen ewigen Bund schließe Ich mit ihnen, daß Ich Mich nicht von ihnen zurückwende, ihnen Gutes zu tun; und in ihr Herz gebe Ich Furcht vor Mir, daß sie von Mir sich nicht abwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'Und werde Mich freuen über sie, um ihnen Gutes zu tun, und werde sie in diesem Lande pflanzen in Wahrheit, mit Meinem ganzen Herzen und mit Meiner ganzen Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Denn also spricht Jehovah: Wie Ich all dies große Übel über dies Volk gebracht, so bringe Ich über sie alles das Gute, das Ich über sie redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Und das Feld soll gekauft werden in diesem Land, von dem ihr sagtet: Eine Verwüstung ist es, ohne Mensch und Vieh; in der Chaldäer Hand ist es gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Felder werden sie um Silber kaufen und den Brief schreiben und besiegeln und dafür Zeugen zeugen lassen im Lande Benjamin, und in Jerusalems Umgebungen und in den Städten Jehudahs, und in den Städten des Gebirges, und in den Städten der Niederung, und in den Städten des Mittagslandes; denn Ich wende zurück ihre Gefangenschaft, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Und zum zweitenmal geschah Jehovahs Wort an Jirmejahu, und er war noch im Vorhof der Wacht eingesperrt, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'So spricht Jehovah, Der es tut, Jehovah, Der es bildet, um es zu festigen, Jehovah ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Rufe Mich an und Ich antworte dir und sage dir große und sichere Dinge an, die du nicht weißt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Denn also spricht Jehovah, der Gott Israels, über die Häuser dieser Stadt und über die Häuser der Könige Jehudahs, die abgebrochen werden wider die Wälle und wider das Schwert:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Sie sind gekommen, um zu streiten mit den Chaldäern, um sie zu füllen mit den Leichen des Menschen, die Ich in Meinem Zorn und in Meinem Grimm geschlagen; und ob all ihrer Bosheit habe Ich Mein Angesicht verborgen von dieser Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Siehe, Ich bringe ihr herauf Genesung und Heilung, und heile sie und offenbare ihnen einen Überfluß des Friedens und der Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'Und bringe wieder die Gefangenschaft Jehudahs und die Gefangenschaft Israels, und baue sie wie zuerst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'Und mache sie rein von aller ihrer Missetat, womit sie wider Mich gesündigt, und vergebe alle ihre Missetaten, womit sie wider Mich gesündigt und womit sie von Mir abgefallen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'Und sie wird Mir zum Namen der Freude, zum Lob und zum Schmuck bei allen Völkerschaften der Erde werden, wenn sie von all dem Guten hören, das Ich ihnen tue, und werden schauen und zittern ob all dem Guten und ob all dem Frieden, den Ich ihr bereite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'So spricht Jehovah: Man wird noch hören an diesem Ort, - von dem ihr sprechet: Er ist verödet, so daß kein Mensch und kein Vieh da ist; in den Städten Jehudahs und in den Gassen Jerusalems, die verwüstet ist, so daß kein Mensch und kein Bewohner und kein Vieh da ist, -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'Die Stimme der Freude und die Stimme der Fröhlichkeit, die Stimme des Bräutigams und die Stimme der Braut, die Stimme derer, die da sagen: Bekennet Jehovah der Heerscharen, denn gut ist Jehovah, denn ewig ist Seine Barmherzigkeit; derer, die da Dankopfer hereinbringen in das Haus Jehovahs; denn Ich wende zurück die Gefangenschaft des Landes, wie zuerst, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'So spricht Jehovah der Heerscharen: Wieder werden an diesem Orte, dem verödeten, da weder Mensch noch Vieh war, und in allen seinen Städten Wohnorte für Hirten sein, die das Kleinvieh lagern lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'Im des Gebirges Städten, in den Städten der Niederung und in den Städten des Mittagslandes und dem Lande Benjamin und in Jerusalems Umgebungen und in den Städten Jehudahs wird vorüberziehen das Kleinvieh unter des Zählers Händen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Siehe, Tage kommen, spricht Jehovah, da Ich bestätige das gute Wort, das Ich geredet habe zum Hause Israel und über das Haus Jehudahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'In jenen Tagen und zu jener Zeit will Ich sprossen lassen für David einen gerechten Sproß, und Er soll Recht und Gerechtigkeit tun auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'In jenen Tagen wird Jehudah gerettet werden und Jerusalem in Sicherheit wohnen, und so wird man Ihn nennen: Jehovah, unsere Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Denn also spricht Jehovah: Dem David soll nicht ausgerottet werden ein Mann, der da sitze auf dem Thron des Hauses Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'Und den Priestern, den Leviten, soll nicht ausgerottet werden ein Mann vor Meinem Angesicht, der Brandopfer aufopfere und Speiseopfer anzünde und Schlachtopfer bereite alle Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'Und es geschah das Wort Jehovahs an Jirmejahu, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'So spricht Jehovah: Wenn ihr zunichte macht Meinen Bund des Tages und Meinen Bund der Nacht, daß Tag und Nacht nicht sei zu seiner Zeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'Soll auch Mein Bund mit David, Meinem Knecht, zunichte sein, daß er nicht einen Sohn habe, der König sei auf seinem Thron, und mit den Leviten, den Priestern, die Mir Dienst tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Wie man der Himmel Heer nicht zählen und den Sand des Meeres nicht messen kann, so will Ich mehren den Samen Davids, Meines Knechtes, und die Leviten, die Mir Dienst tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Und es geschah das Wort Jehovahs an Jirmejahu, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Sahst du nicht, was dieses Volk geredet und gesagt hat? Die zwei Familien, die Jehovah auserwählt hatte, hat Er verschmäht. Und sie lästern Mein Volk, als sollte es eine Völkerschaft nicht fürder vor ihnen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'So spricht Jehovah: Wenn Ich Meinen Bund des Tages und der Nacht, die Satzungen der Himmel und der Erde nicht gesetzt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'Dann werde Ich auch den Samen Jakobs und Davids, Meines Knechtes, verschmähen, daß Ich nicht nehme von seinem Samen Herrscher über den Samen Abrahams, Isaaks und Jakobs, wenn Ich ihre Gefangenschaft zurückbringe und ihrer Mich erbarme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Das Wort, das von Jehovah geschah an Jirmejahu, während Nebuchadnezzar, der König Babels, und all seine Streitmacht und alle Königreiche der Erde unter der Herrschaft seiner Hand, und alle Völker stritten wider Jerusalem und wider alle seine Städte, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'So spricht Jehovah, der Gott Israels: Gehe hin und sprich zu Zidkijahu, dem König Jehudahs, und sprich zu ihm: So spricht Jehovah: Siehe, Ich gebe diese Stadt in die Hand des Königs von Babel, daß er sie mit Feuer verbrenne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Und du wirst nicht aus seiner Hand entrinnen, sondern erfaßt und in seine Hand gegeben werden, und deine Augen sollen die Augen des Königs von Babel sehen, und sein Mund soll zu deinem Munde reden, und du sollst gen Babel kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Höre nur das Wort Jehovahs, Zidkijahu, König von Jehudah! So spricht Jehovah über dich: Du sollst nicht sterben durch das Schwert;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'In Frieden sollst du sterben und mit dem Brande deiner Väter, den früheren Königen, die vor dir waren, so werden sie auch dir einen verbrennen und um dich klagen: Wehe, Herr! Denn ein Wort habe Ich geredet, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Und Jirmejahu, der Prophet, redete zu Zidkijahu, dem König Judahs, alle diese Worte in Jerusalem;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'Und die Streitmacht des Königs von Babel stritt wider Jerusalem und wider alle die übrigen Städte Jehudahs, wider Lachisch und wider Asekah, denn sie waren als feste Städte verblieben unter Jehudahs Städten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Das Wort, das an Jirmejahu von Jehovah geschah, nachdem der König Zidkijahu mit allem Volk in Jerusalem einen Bund geschlossen, daß sie Freilassung wollten ausrufen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'Daß jeder Mann seinen Knecht und jeder Mann seine Dienstmagd, Hebräer und Hebräerin, frei entsende, so daß kein Mann unter ihnen einen Juden, seinen Bruder, knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'Und alle Obersten und alles Volk, so den Bund eingegangen waren, gehorchten, daß jeder Mann seinen Knecht und jeder Mann seine Dienstmagd frei entsandte, daß sie sie nicht mehr knechteten. Und sie gehorchten und entsandten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Und hernach wandten sie sich zurück und brachten die Knechte und die Dienstmägde, die sie frei entsandt hatten, zurück; und unterwarfen sie sich zu Knechten und Dienstmägden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Und es geschah das Wort Jehovahs an Jirmejahu von Jehovah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'So spricht Jehovah, der Gott Israels: Ich hatte mit euren Vätern einen Bund geschlossen am Tage, da Ich sie herausbrachte aus dem Lande Ägypten, aus dem Hause der Knechte, und gesprochen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Am Ende von sieben Jahren sollt ihr entsenden jeder Mann seinen Bruder, den Hebräer, der sich dir verkauft hat und dir sechs Jahre diente, und ihn frei von dir entsenden; aber eure Väter hörten nicht auf Mich und neigten nicht ihr Ohr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Und ihr waret diesen Tag zurückgekehrt, und hattet getan, was recht in Meinen Augen ist, daß ihr Freilassung jeder Mann seinem Genossen ausrufen ließet, und vor Mir in dem Hause, über dem Mein Name genannt wird, einen Bund geschlossen habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Ihr aber seid zurückgekehrt und habt entweiht Meinen Namen, und habt jeder Mann seinen Knecht und jeder Mann seine Dienstmagd, die ihr frei entsandt hattet, nach ihrem Wunsche, zu euch zurückgebracht und euch unterworfen, daß sie euch Knechte und Dienstmägde wären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Darum spricht also Jehovah: Ihr habt nicht auf Mich gehört, daß ihr Freilassung, jeder Mann für seinen Bruder und jeder Mann für seinen Genossen, ließet ausrufen. Siehe, Ich rufe euch Freilassung aus, spricht Jehovah, für das Schwert, für Pest und für Hungersnot; und mache euch zum Schrecknis für alle Königreiche der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'Und mache die Männer, die überschritten Meinen Bund, weil sie nicht bestätigten die Worte des Bundes, den sie vor Mir geschlossen, wie das Kalb, das sie entzweischnitten und zwischen seinen Stücken durchgegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'Die Obersten Jehudahs und die Obersten Jerusalems, die Verschnittenen und die Priester und alles Volk des Landes, die zwischen des Kalbes Stücken durchgegangen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'Und gebe sie in ihrer Feinde Hand und in die Hand derer, die ihnen nach der Seele trachten, daß ihre Leichname den Vögeln des Himmels und dem Getier der Erde zur Speise werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Und Zidkijahu, Jehudahs König, und seine Obersten gebe Ich in ihrer Feinde Hand und in die Hand derer, die ihnen nach der Seele trachten und in die Hand der Streitmacht des Königs von Babel, die von euch hinaufgezogen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Siehe, Ich gebiete, spricht Jehovah, und bringe sie zurück zu dieser Stadt, auf daß sie streiten wider sie und sie erobern und mit Feuer verbrennen, und Jehudahs Städte gebe Ich zur Verwüstung, daß niemand darinnen wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Das Wort, das an Jirmejahu geschah von Jehovah in den Tagen Jehojakims, des Sohnes von Joschijahu, dem Könige Jehudahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Gehe zum Haus der Rechabiter und rede mit ihnen und bringe sie herein in das Haus Jehovahs in eine der Zellen und gib ihnen Wein zu trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Und ich nahm Jaasanjah, Jirmejahus Sohn, des Sohnes Chabazzinjahs und seine Brüder und alle seine Söhne und das ganze Haus der Rechabiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'Und brachte sie herein zum Hause Jehovahs, zur Zelle der Söhne Chanans, des Sohnes Jigdaljahus, des Mannes Gottes, die neben der Zelle des Obersten ist, die über der Zelle Maasejahus, des Sohnes Schallums, ist, der die Schwelle hütete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'Und vor die Söhne des Hauses der Rechabiter gab ich Kelche voll von Wein und Becher, und sprach zu ihnen: Trinket Wein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Und sie sprachen: Wir trinken keinen Wein; denn Jonadab, der Sohn Rechabs, unser Vater, hat über uns geboten und gesagt: Ihr sollt keinen Wein trinken, ihr und eure Söhne ewiglich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'Und ein Haus sollt ihr nicht bauen, noch Samen säen und keinen Weinberg pflanzen, noch einen haben, sondern in Zelten wohnen alle eure Tage, daß ihr lebet viele Tage auf dem Boden, darauf ihr Fremdlinge seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'Und wir haben gehört auf die Stimme, Jehonadabs, des Sohnes Rechabs, unseres Vaters, nach allem, was er uns geboten, daß keinen Wein wir trinken all unsere Tage, wir, unsere Weiber, unsere Söhne und unsere Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'Und daß wir keine Häuser bauen, darin zu wohnen, und Weinberg und Feld und Samen haben wir nicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'Und wir wohnen in Zelten, und gehorchen und tun nach allem, was uns Jonadab, unser Vater, geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Und es geschah, da Nebuchadrezzar, Babels König, heraufzog wider das Land, da sprachen wir: Kommt, und laßt uns kommen gen Jerusalem vor der Chaldäer Streitmacht und vor der Streitmacht Arams, und wir wohnen in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Und es geschah Jehovahs Wort an Jirmejahu, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'So spricht Jehovah der Heerscharen, der Gott Israels: Gehe hin und sprich zum Manne Jehudahs und zu Jerusalems Bewohnern: Nehmet ihr nicht Zucht an, daß ihr auf Meine Worte hört? spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Es erstehen die Worte Jehonadabs, des Sohnes Rechabs, die er seinen Söhnen gebot, nicht Wein zu trinken; und sie trinken keinen bis auf diesen Tag; denn sie hören auf das Gebot ihres Vaters; und Ich redete zu euch, früh aufstehend und redend, und ihr höret nicht auf Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'Und Ich sandte zu euch all Meine Knechte, die Propheten, früh aufstehend und sendend, und sprach: Kehret doch zurück, jeder Mann von seinem bösen Wege, und machet eure Taten gut, und geht nicht anderen Göttern nach, ihnen zu dienen, auf daß ihr wohnet auf dem Boden, den Ich euch gab und euren Vätern; ihr aber neigtet nicht euer Ohr und hörtet nicht auf Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Die Söhne Jehonadabs, des Sohnes Rechabs, bestätigen das Gebot ihres Vaters, das er ihnen geboten, aber dieses Volk hört nicht auf Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Darum, so spricht Jehovah, der Gott der Heerscharen, der Gott Israels: Siehe, Ich bringe über Jehudah und über alle Bewohner Jerusalems all das Böse, das Ich über sie geredet habe: weil Ich zu ihnen redete und sie hörten nicht, und Ich ihnen rief und sie antworteten nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'Und zu dem Haus der Rechabiter sprach Jirmejahu: Also spricht Jehovah der Heerscharen, der Gott Israels: Weil ihr gehört habt auf das Gebot Jehonadabs, eures Vaters, und hieltet alle seine Gebote und tatet nach allem, was er euch geboten hat:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'Darum, so spricht Jehovah der Heerscharen, der Gott Israels, soll dem Jonadab, dem Sohne Rechabs, nicht ausgerottet werden ein Mann, der vor Mir stehe alle Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Und es geschah im vierten Jahr Jehojakims, des Sohnes Joschijahus, des Königs von Jehudah: Da geschah dieses Wort an Jirmejahu von Jehovah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Nimm dir die Rolle eines Buches und schreibe darauf alle die Worte, die Ich zu dir geredet habe über Israel und über Jehudah und über alle Völkerschaften von dem Tag an, da Ich zu dir geredet, seit den Tagen Joschijahus und bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Vielleicht daß die vom Hause Jehudah all das Böse hören, das Ich denke ihnen zu tun, daß sie zurückkehren jeder Mann von seinem bösen Weg, und Ich vergebe ihrer Missetat und ihrer Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Und Jirmejahu rief Baruch, den Sohn Nerijahs, und Baruch schrieb vom Munde Jirmejahus alle Worte Jehovahs, die Er zu ihm geredet hatte, auf die Rolle eines Buches.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Und Jirmejahu gebot Baruch und sprach: Ich bin eingesperrt, vermag nicht in das Haus Jehovahs zu kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'So gehe du und lies aus der Rolle, in der du aus Meinem Mund die Worte Jehovahs hast geschrieben, vor den Ohren des Volkes, im Hause Jehovahs am Tage des Fastens; und auch vor den Ohren derer von ganz Jehudah, die da von ihren Städten kommen, sollst du sie lesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Vielleicht fällt ihr Flehen vor dem Angesichte Jehovahs, daß sie zurückkehren jeder Mann von seinem bösen Wege; denn groß ist der Zorn und Grimm, den Jehovah geredet zu diesem Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'Und Baruch, der Sohn Nerijahs, tat nach allem, das Jirmejahu, der Prophet, ihm gebot, zu lesen Jehovahs Worte in dem Buch am Haus Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'Und es geschah im fünften Jahr Jehojakims, des Sohnes Joschijahus, des Königs von Jehudah, im neunten Monat, riefen sie ein Fasten aus vor dem Angesichte Jehovahs für alles Volk in Jerusalem und alles Volk, das aus den Städten Jehudahs kommt nach Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'Und Baruch las in dem Buche die Worte Jirmejahus an Jehovahs Hause in der Zelle Gemarjahus, des Sohnes Schaphans, des Schreibers, am oberen Vorhof, am Eingang des neuen Tores zum Haus Jehovahs in den Ohren alles Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Und Michajehu, der Sohn Gemarjahus, Sohn von Schaphan, hörte alle Worte Jehovahs aus dem Buche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'Und er ging hinab in das Haus des Königs zur Zelle des Schreibers und siehe, da saßen alle Obersten: Elischama, der Schreiber, und Delajahu, Schemajahus Sohn, und Elnathan, Achbors Sohn, und Gemarjahu, Schaphans Sohn, und Zidkijahu, Chananjahus Sohn, und alle Obersten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'Und Michajehu sagte ihnen alle Worte an, die er gehört hatte, als Baruch in dem Buche las vor den Ohren des Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Und alle Obersten sandten an Baruch Jehudi, den Sohn Nethanjahus, des Sohnes Schelemjahus, des Sohnes Kuschis und sagten: Die Rolle, in der du hast gelesen vor des Volkes Ohren, - nimm sie in deine Hand und komm! Und Baruch, der Sohn Nerijahus, nahm die Rolle in seine Hand und kam zu ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Und sie sprachen zu ihm: Setze dich doch und lies es vor unseren Ohren. Und Baruch las es vor ihren Ohren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'Und es geschah, wie sie alle die Worte gehört hatten, schauderten sie, jeder Mann gegen seinen Genossen und sprachen zu Baruch: Wir müssen dem König alle diese Worte ansagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Und den Baruch fragten sie und sagten: Sage uns doch an, wie du alle diese Worte aus seinem Mund geschrieben hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Und Baruch sprach zu ihnen: Mit seinem Munde las er mir alle diese Worte vor, und ich schrieb sie mit Tinte in das Buch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Und die Obersten sprachen zu Baruch: Gehe und verbirg dich, du und Jirmejahu, daß kein Mann wisse, wo ihr seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'Und sie kamen zum König in den Vorhof, und die Rolle hatten sie in der Zelle Elischamas, des Schreibers aufgehoben, und sagten vor den Ohren des Königs all die Worte an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Und der König sandte den Jehudi, daß er die Rolle hole, und er holte sie aus der Zelle Elischamas, des Schreibers, und Jehudi las sie vor den Ohren des Königs und vor den Ohren aller Obersten, die bei dem König standen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Und der König saß in dem Winterhaus, im neunten Monat, und das Feuerbecken brannte vor ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'Und es geschah, wenn Jehudi drei oder vier Blätter gelesen hatte, schnitt er sie mit dem Messer des Schreibers aus und warf sie auf das Feuer im Feuerbecken, bis die ganze Rolle über dem Feuer in dem Feuerbekken verzehrt ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Und sie schauerten nicht, noch zerrissen sie ihre Kleider, der König und alle seine Knechte, die alle diese Worte gehört hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'Doch aber vermittelten Elnathan und Delajahu und Gemarjahu bei dem König, daß er die Rolle nicht verbrennen sollte; er hörte aber nicht auf sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'Und der König gebot Jerachmeel, dem Sohne des Königs, und Serajahu, dem Sohne Asriels, und Schelemjahu, dem Sohne Abdeels, Baruch, den Schreiber, und Jirmejahu, den Propheten, zu holen, aber Jehovah hatte sie verborgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Und es geschah Jehovahs Wort an Jirmejahu, nachdem der König die Rolle und die Worte, die Baruch aus dem Munde Jirmejahus geschrieben, verbrannt hatte, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Nimm dir wiederum eine andere Rolle und schreibe darauf alle die früheren Worte, die auf der früheren Rolle waren, die Jehojakim, der König Jehudahs, hat verbrannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'Und über Jehojakim, den König Jehudahs, sollst du sagen: Also spricht Jehovah: Du hast diese Rolle verbrannt und gesagt: Warum hast du darauf geschrieben und gesagt: Der König Babels kommt und verdirbt dieses Land und läßt daraus aufhören Mensch und Vieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Darum, so spricht Jehovah über Jehojakim, den König Jehudahs: Er soll keinen haben, der auf dem Throne Davids sitze, und sein Leichnam soll der Hitze am Tag und dem Frost bei Nacht hingeworfen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Und heimsuchen werde Ich an ihm und seinem Samen und an seinen Knechten ihre Missetat und bringen über sie und über Jerusalems Bewohner und über den Mann Jehudahs all das Böse, das Ich über sie geredet habe, und sie hörten nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Und Jirmejahu nahm eine andere Rolle und gab sie Baruch, dem Sohne Nerijahus, dem Schreiber, und er schrieb darauf aus Jirmejahus Mund alle die Worte des Buches, das Jehojakim, der König Jehudahs, im Feuer verbrannte, und wurden noch viele Worte, gleich jenen, dazugetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'Und es regierte als König Zidkijahu, der Sohn Joschijahus, anstatt Chonjahus, des Sohnes Jehojakims, den Nebuchadrezzar, König von Babel, zum König im Land Jehudah hatte gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Er aber und seine Knechte und das Volk des Landes hörten nicht auf Jehovahs Worte, die Er durch die Hand Jirmejahus, des Propheten, redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Und es sandte der König Zidkijahu Jehuchal, Schelemjahs Sohn, und Zephanjahu, Maasejahs Sohn, den Priester, zu Jirmejahu, dem Propheten, und sprach: Bete doch für uns zu Jehovah, unserem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Und Jirmejahu ging ein und ging aus inmitten des Volkes und sie hatten ihn nicht in das Haus des Kerkers gesetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'Und eine Streitmacht Pharaos war von Ägypten ausgezogen, und die Chaldäer, die Jerusalem belagerten, hörten das Gerücht von ihnen und zogen hinauf von Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'Und es geschah Jehovahs Wort an Jirmejahu, den Propheten, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Also spricht Jehovah, der Gott Israels: So sprechet zu dem König Jehudahs, der euch zu Mir sendet, Mich zu befragen: Siehe, die Streitmacht des Pharao, die euch zum Beistand ausgezogen, kehrt in ihr Land Ägypten zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'Und die Chaldäer kehren zurück und streiten gegen diese Stadt und erobern sie und verbrennen sie mit Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'So spricht Jehovah: Laßt eure Seelen nicht verführen und sprechet: Die Chaldäer sind von uns gezogen, - denn sie werden nicht gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Ja, schlüget ihr die ganze Streitmacht der Chaldäer, die mit euch streiten und es verblieben unter ihnen nur durchstochene Männer, sie würden aufstehen, jeder Mann in seinem Zelte und diese Stadt mit Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'Und es geschah, als der Chaldäer Heeresmacht von Jerusalem hinaufgezogen war vor der Streitmacht Pharaos,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'Da ging Jirmejahu aus Jerusalem hinaus, um nach dem Lande Benjamin zu gehen, um dort inmitten des Volkes seinen Teil zu nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'Und er war an dem Tor Benjamins und es war dort ein Hauptmann der Wache und sein Name war Jirijah, ein Sohn Schelemjahs, des Sohnes Chananjahs, und er erfaßte Jirmejahu, den Propheten, und sprach: Zu den Chaldäern willst du abfallen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jirmejahu aber sprach: Lüge ist es, ich falle nicht zu den Chaldäern ab. Er aber hörte nicht auf ihn, und Jirijah erfaßte den Jirmejahu und brachte ihn hinein zu den Obersten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Und die Obersten waren entrüstet über Jirmejahu und schlugen ihn und taten ihn in das Haus der Gebundenen, in das Haus Jehonathans, des Schreibers; denn dieses Haus hatten sie zum Haus des Kerkers gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'So kam Jirmejahu in das Haus der Grube und in die Gewölbe; und Jirmejahu saß dort viele Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'Und König Zidkijahu sandte und ließ ihn holen, und der König fragte ihn in seinem Hause insgeheim und sprach: Ist ein Wort von Jehovah da? Und Jirmejahu sprach: Ja, und er sprach: Du wirst in die Hand des Königs zu Babel gegeben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Und Jirmejahu sprach zum König Zidkijahu: Was habe ich wider dich und wider deine Knechte und wider dieses Volk gesündigt, daß ihr mich in das Haus des Kerkers gegeben habt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Und wo sind eure Propheten, die euch weissagten und sprachen: Der König Babels kommt nicht wider euch und wider dieses Land?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Und nun, mein Herr König, höre doch und laß mein Flehen vor dich kommen, und laß mich nicht in Jehonathans, des Schreibers Haus zurückkehren, daß ich daselbst nicht sterbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Und König Zidkijahu gebot, daß man Jirmejahu im Vorhof der Wache behalte, und gebe ihm einen Laib Brot des Tages aus der Gasse der Bäcker, bis alles Brot aus der Stadt gar aus wäre. Und Jirmejahu blieb im Vorhof der Wacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'Es hörten aber Schephatjah, Mathans Sohn, und Gedaljahu, Paschchurs Sohn, und Juchal, der Sohn Schelemjahus, und Paschchur, Malchijahs Sohn, die Worte, die Jirmejehu zu allem Volke redete und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'So spricht Jehovah: Wer bleibt in dieser Stadt, wird sterben durch das Schwert, durch Hunger und durch Pest, und wer hinaus zu den Chaldäern geht, der wird leben, und hat als Beute seine Seele, daß er lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'So spricht Jehovah: Diese Stadt wird in die Hand der Streitmacht des Königs von Babel gegeben, daß er sie erobere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'Und die Obersten sprachen zu dem König: Es sterbe doch dieser Mann, weil er läßt erschlaffen die Hände aller Männer des Streites, die in dieser Stadt verbleiben, und die Hände alles Volkes, da er zu ihnen Worte wie diese redet; denn dieser Mann fragt nicht nach dem Frieden dieses Volkes, sondern nach dem Bösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Und König Zidkijahu sprach: Siehe, er ist in eurer Hand; denn nichts vermag der König mit euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Und sie nahmen Jirmejahu und warfen ihn in die Grube Malchijahus, des Sohnes des Königs, die im Vorhof der Wacht war, und ließen Jirmejahu an Stricken hinab, und in der Grube war kein Wasser, sondern Schlamm, und Jirmejahu sank in den Schlamm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'Und Ebedmelech, der Kuschite, ein Mann, ein Verschnittener, der im Hause des Königs war, hörte, daß sie Jirmejahu in die Grube taten, und der König saß im Tore Benjamins.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'Und Ebedmelech ging hinaus aus des Königs Hause und redete mit dem König und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Herr König, Böses taten diese Männer in allem, das sie an Jirmejahu, dem Propheten, getan, daß sie ihn in die Grube warfen, so daß er auf der Stelle vor Hunger sterben müßte; denn es ist kein Brot mehr in der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'Und der König gebot Ebedmelech, dem Kuschiten, und sprach: Nimm unter deine Hand von hinnen dreißig Männer und bringe Jirmejahu, den Propheten, herauf aus der Grube, ehe denn er stirbt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Und Ebedmelech nahm die Männer unter seine Hand und ging in das Haus des Königs unter die Schatzkammer und nahm von da altes Abgetragenes und altes Zerlumptes, und warf sie dem Jirmejahu an Stricken in die Grube zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'Und Ebedmelech, der Kuschite, sprach zu Jirmejahu: Lege doch das alte Abgetragene und Zerlumpte unter die Achselhöhlen deiner Hände unter die Stricke. Und Jirmejahu tat also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'Und sie zogen Jirmejahu mit den Strikken empor und brachten ihn aus der Grube herauf, und Jirmejahu blieb im Vorhof der Wacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'Und König Zidkijahu sandte und ließ Jirmejahu, den Propheten, zu sich holen in den dritten Eingang an Jehovahs Haus. Und der König sprach zu Jirmejahu: Ich frage dich ein Wort, verhehle kein Wort!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'Und Jirmejahu sprach zu Zidkijahu: Wenn ich es dir ansage, läßt du mich nicht töten? Und wenn ich dir rate, hörst du nicht auf mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Und König Zidkijahu schwur dem Jirmejahu insgeheim und sprach: Beim Leben Jehovahs, Der diese Seele uns gemacht hat, ich lasse dich nicht töten, und gebe dich nicht in dieser Männer Hand, die dir nach der Seele trachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Und Jirmejahu sprach zu Zidkijahu: So spricht Jehovah, der Gott der Heerscharen, der Gott Israels: Wenn du hinausgehst zu den Obersten des Königs von Babel, so wird deine Seele leben und diese Stadt wird nicht verbrannt mit Feuer und du lebst und dein Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Und wenn du nicht hinausgehst zu den Obersten des Königs von Babel, so wird diese Stadt in der Chaldäer Hand gegeben, und sie verbrennen sie mit Feuer, und du wirst nicht aus ihrer Hand entrinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Und König Zidkijahu sprach zu Jirmejahu: Ich besorge die Juden, die zu den Chaldäern abgefallen sind, daß sie mich in ihre Hand geben und sie mich mißhandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'Und Jirmejahu sprach: Man gibt dich nicht hin. Höre doch auf Jehovahs Stimme, auf das, was ich rede mit dir, auf daß es gut mit dir sei, und deine Seele lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Und wenn du dich weigerst, hinauszugehen, so ist dies das Wort, das mir Jehovah zeigte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Und siehe, alle Weiber, die im Haus von Jehudahs König verblieben, werden zu den Obersten des Königs von Babel hinausgebracht; und siehe, sie sprechen nun: Angetrieben und übermocht haben dich die Männer deines Friedens, gesunken in den Sumpf sind deine Füße; sie sind hinter sich zurückgewichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'Und alle deine Weiber und deine Söhne bringen sie hinaus zu den Chaldäern, und du wirst nicht aus ihrer Hand entrinnen, sondern durch die Hand des Königs von Babel erfaßt werden, und diese Stadt wird mit Feuer verbrannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Und Zidkijahu sprach zu Jirmejahu: Kein Mann soll von diesen Worten wissen, auf daß du nicht sterbest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Und wenn die Obersten hören, daß ich mit dir redete, und zu dir kommen und zu dir sprechen: Sage uns doch an, was du zum König geredet, verhehle nichts von uns, daß wir dich nicht töten; und was hat der König zu dir geredet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'So sprich zu ihnen: Ich legte mein Flehen vor dem König nieder, daß man mich nicht in das Haus Jonathans zurückbringe, daß ich dort stürbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Und alle Obersten kamen zu Jirmejahu und fragten ihn, und er sagte ihnen an nach allen diesen Worten, die der König gebot, und sie schwiegen von ihm; denn es ward nichts gehört von der Sache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'Und Jirmejahu blieb im Vorhof der Wacht bis zu dem Tage, da Jerusalem ward erobert. Und es geschah also, da Jerusalem erobert ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'Im neunten Jahr Zidkijahus, des Königs von Jehudah, im zehnten Monat, kam Nebuchadrezzar, Babels König, und seine ganze Streitmacht wider Jerusalem und belagerten dasselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'Im elften Jahre Zidkijahus, im vierten Monat, im neunten des Monats, ward in die Stadt gebrochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'Und alle Obersten des Königs von Babel kamen und saßen am Mitteltor: Nergal Scharezer, Samgar, Nebu Sarsechim, der Hauptmann der Verschnittenen, Nergal Scharezer, der Hauptmann der Magier, und alle die übrigen Obersten des Königs von Babel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Und es geschah, daß Zidkijahu, der König Jehudahs, und alle Kriegsleute sie sahen, so entwichen sie und gingen hinaus bei Nacht aus der Stadt auf dem Weg nach dem Garten des Königs durch das Tor zwischen den zwei Mauern und gingen auf dem Wege nach dem Blachfelde hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Und der Chaldäer Streitmacht setzte hinter ihnen nach, und sie erreichten Zidkijahu auf dem Blachfelde Jerichos, und nahmen ihn und brachten ihn hinauf zu Nebuchadnezzar, dem König Babels, nach Riblah im Lande Chamath, und er redete mit ihm im Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'Und Babels König schlachtete die Söhne Zidkijahus in Riblah vor seinen Augen, und alle Vornehmen Jehudahs schlachtete der König Babels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'Und die Augen Zidkijahus blendete er und band ihn mit Ketten, ihn nach Babel zu bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Und des Königs Haus und die Häuser des Volkes verbrannten die Chaldäer mit Feuer und rissen die Mauern Jerusalems ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'Und das übrige Volk, die so in der Stadt verblieben, und die Abgefallenen, die zu ihm abgefallen, und das übrige Volk, die Verbliebenen, führte Nebusaradan, der Hauptmann der Leibwachen, nach Babel weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'Und vom Volke die Armen, die gar nichts hatten, ließ Nebusaradan, der Hauptmann der Leibwachen, im Lande Jehudah verbleiben, und gab ihnen an jenem Tage Weinberge und Grundstücke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Und Nebuchadrezzar, der König von Babel, gebot über Jirmejahu, durch die Hand des Nebusaradan, des Hauptmanns der Leibwachen, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Nimm ihn und setze deine Augen auf ihn und tue ihm nichts Böses, sondern wie er zu dir reden wird, so tue mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'Und Nebusaradan, der Hauptmann der Leibwachen, und Nebuschasban, der Hauptmann der Verschnittenen, und Nergal Scharezer, der Hauptmann der Magier, und alle Hauptleute des Königs von Babel, sandten hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'Und sie sandten und ließen Jirmejahu aus dem Vorhof der Wache holen und übergaben ihn Gedaljahu, dem Sohne Achikams, des Sohnes Schaphans, ihn hinauszubringen in das Haus und er wohnte in des Volkes Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'Und an Jirmejahu geschah das Wort Jehovahs, da er noch im Vorhof der Wache eingesperrt war, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Gehe hin und sprich zu Ebedmelech, dem Kuschiten, sprechend: So spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich lasse Meine Worte über diese Stadt kommen zum Bösen, und nicht zum Guten, und sie werden an jenem Tage geschehen vor deinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Und Ich errette dich an jenem Tage, spricht Jehovah, und du wirst nicht in die Hand der Männer, vor denen dir bangt, gegeben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Denn Ich lasse dich entrinnen und du sollst nicht fallen durch das Schwert, und deine Seele soll dir zur Beute sein, weil du auf Mich vertraut hast, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Das Wort, welches geschah an Jirmejahu von Jehovah, nachdem Nebusaradan, der Hauptmann der Leibwachen, ihn aus Ramah entsandt hatte. Als man ihn holte, da war er in Ketten gebunden inmitten all der Weggeführten Jerusalems und Jehudahs, die nach Babel weggeführt wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Und der Hauptmann der Leibwachen nahm Jirmejahu und sprach zu ihm: Jehovah, dein Gott, hat dieses Böse über diesen Ort geredet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'Und Jehovah hat es kommen lassen und getan, wie Er geredet; denn ihr habt gesündigt wider Jehovah und nicht gehört auf Seine Stimme, und es geschah euch nach diesem Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'Und nun siehe, ich mache dir heute die Ketten an deiner Hand auf. Wenn es in deinen Augen gut ist, mit mir nach Babel zu kommen, komm, und ich will mein Auge auf dich setzen. Wenn es aber in deinen Augen böse ist, mit mir nach Babel zu kommen, unterlaß es. Siehe, das ganze Land ist vor dir. Wohin es gut und recht ist in deinen Augen zu gehen, dahin gehe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Und noch hatte er nicht erwidert - Und kehre zu Gedaljah, dem Sohne Achikams, dem Sohne Schaphans, zurück, den der König von Babel über die Städte Jehudahs bestellt, und wohne mit ihm inmitten des Volkes, oder gehe irgendwohin, wohin zu gehen in deinen Augen recht ist. Und der Hauptmann der Leibwachen gab ihm Unterhalt und eine Ehrengabe und entsandte ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'Und Jirmejahu kam zu Gedaljah, dem Sohne Achikams nach Mizpah und wohnte mit ihm inmitten des Volkes, das im Land verblieben war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Und alle Obersten der Streitmächte, so auf dem Felde waren, sie und ihre Männer, hörten, daß der König von Babel, Gedaljahu, Achikams Sohn, im Land bestellt und ihm anvertraut hatte Männer und Weiber und Kindlein und die Armen des Landes, die nicht nach Babel weggeführt worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'Und sie kamen zu Gedaljah nach Mizpah, und Jischmael, Sohn Nethanjahus und Jochanan und Jonathan, die Söhne Kareachs, und Serajah, Sohn des Tanchumeth, und Ephais Söhne, des Netophathiters, und Jesanjahu, Maachathis Sohn und ihre Männer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'Und Gedaljahu, der Sohn Achikams, des Sohnes Schaphans, schwur ihnen und ihren Leuten und sprach: Fürchtet euch nicht den Chaldäern zu dienen; wohnet im Lande und dient dem König Babels, so wird es gut mit euch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Und siehe, ich bleibe in Mizpah, zu stehen vor den Chaldäern, die werden zu uns kommen. Und ihr sammelt Wein und Obst und Öl ein und tut sie in eure Gefäße, und wohnt in euren Städten, die ihr eingenommen habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'Und auch alle Juden, die in Moab und unter den Söhnen Ammons und in Edom und in allen Ländern waren, hörten, daß der König Babels Jehudah einen Überrest gegeben und über sie Gedaljahu, den Sohn Achikams, des Sohnes Schaphans, bestellt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'Und alle Juden kehrten zurück von allen Orten, wohin sie verstoßen waren, und kamen in das Land Jehudah zu Gedaljah nach Mizpah, und sammelten Wein und Obst sehr viel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Und Jochanan, der Sohn Kareachs, und alle Obersten der Streitmächte, die auf dem Felde waren, kamen zu Gedaljahu nach Mizpah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'Und sprachen zu ihm: Weißt du, daß Baalis, der König der Söhne Ammons, Jischmael, Nethanjahs Sohn, gesandt, dir die Seele zu erschlagen? Und Gedaljah, Achikams Sohn, glaubte ihnen nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'Und Jochanan, der Sohn Kareachs, sprach zu Gedaljah insgeheim in Mizpah und sprach: Laß mich doch gehen und Jischmael, den Sohn Nethanjahs schlagen, und kein Mann soll es wissen. Warum doch soll er dir die Seele schlagen und wir zerstreut werden, ganz Jehudah, die wir zu dir zusammengekommen sind, und der Überrest Jehudahs verlorengehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Und Gedaljah, der Sohn Achikams, sprach zu Jochanan, Kareachs Sohn: Tue nicht nach diesem Wort; denn Lügen redest du wider Jischmael.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Und es geschah im siebenten Monat, da kam Jischmael, der Sohn Nethanjahs, des Sohnes Elischamas, vom Samen des Königtums, und die Hauptleute des Königs und zehn Männer mit ihm zu Gedaljahu, dem Sohne Achikams, nach Mizpah, und sie aßen das Brot allzumal in Mizpah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Und Jischmael, Nethanjahs Sohn, stand auf und die zehn Männer, die mit ihm waren, und schlugen Gedaljahu, den Sohn Achikams, des Sohnes Schaphans, mit dem Schwert, und er tötete ihn, den Babels König im Lande bestellt hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'Und alle Juden, die mit ihm, mit Gedaljahu, in Mizpah waren, und die Chaldäer, die dort sich fanden, die Kriegsleute, schlug Jischmael.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Und es geschah am zweiten Tage, da er Gedaljahu getötet hatte und kein Mann es wußte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'Daß achtzig Männer von Schichem, von Schilo und von Schomron kamen mit geschorenem Barte und zerrissenen Kleidern und hatten sich geritzt und hatten Speiseopfer und Weihrauch in ihrer Hand, daß sie sie brächten in Jehovahs Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'Und Jischmael, der Sohn Nethanjahs, ging heraus von Mizpah ihnen entgegen, ging daher und weinte, und als er auf sie traf, so sprach er zu ihnen: Kommt herein, zu Gedaljahu, dem Sohne Achikams.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Und es geschah, da sie mitten in die Stadt kamen, schlachtete sie Jischmael, der Sohn Nethanjahs mitten in die Grube, er und die Männer, die mit ihm waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Zehn Männer aber fanden sich unter ihnen, und die sprachen zu Jischmael: Töte uns nicht. Wir haben Verheimlichtes in dem Feld, Weizen und Gerste und Öl und Honig. Und er hörte auf und tötete sie nicht inmitten ihrer Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Und die Grube, worein Jischmael all die Leichen der Männer, die er zur Seite Gedaljahus geschlagen, warf, war die, welche König Asa wider Baascha, den König Israels, gemacht hatte; sie füllte Jischmael, der Sohn Nethanjahus, mit Erschlagenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'Und Jischmael nahm gefangen all den Überrest des Volkes, das in Mizpah war, die Töchter des Königs und alles Volk, das verblieb in Mizpah, über welche Nebusaradan, der Hauptmann der Leibwachen, Gedaljahu, den Sohn Achikams, bestellt hatte. Und Jischmael, der Sohn Nethanjahs, führte sie gefangen und ging dahin, um zu den Söhnen Ammons hinüberzuziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'Und Jochanan, der Sohn Kareachs, und alle Obersten der Streitmächte, die mit ihm waren, hörten alles das Böse, das Jischmael, Nethanjahs Sohn, getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'Und sie nahmen alle Männer und zogen hin, mit Jischmael, dem Sohn Nethanjahs, zu streiten, und fanden ihn bei dem großen Wasser zu Gibeon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'Und es geschah, wie alles Volk, das mit Jischmael war, Jochanan sah, den Sohn des Kareach, und alle Obersten der Streitmächte, die mit ihm waren, da wurden sie fröhlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Und alles Volk, das Jischmael aus Mizpah gefangen führte, wandte sich um und kehrten zurück, und gingen zu Jochanan, dem Sohn Kareachs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Und Jischmael, der Sohn Nethanjahs, entrann mit acht Männern vor Jochanan und ging zu den Söhnen Ammons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Und Jochanan, der Sohn Kareachs, und alle Obersten der Streitmächte, die mit ihm waren, nahmen all den Überrest des Volkes, das er zurückgebracht von Jischmael, dem Sohne Nethanjahs, aus Mizpah, nachdem derselbe geschlagen den Gedaljah, den Sohn des Achikam, die Leute, die Kriegsleute und die Weiber und die Kindlein, und die Verschnittenen, die er von Gibeon zurückgebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'Und sie gingen hin und blieben in der Herberge Kimham, die neben Bethlehem ist, um hinzuziehen, um nach Ägypten zu kommen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'Vor den Chaldäern; denn sie fürchteten sich vor ihnen, weil Jischmael, der Sohn Nethanjahs, Gedaljah, den Sohn Achikams, geschlagen, den der König von Babel im Lande bestellt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Und alle Obersten der Streitmächte und Jochanan, Kareachs Sohn, und Jesanjah, Hoschajahs Sohn, und alles Volk vom Kleinen bis zum Großen traten herzu,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'Und sprachen zu Jirmejahu, dem Propheten: Laß unser Flehen doch vor dich fallen und bete für uns zu Jehovah, deinem Gott, für allen diesen Überrest, denn wenige sind von den Vielen verblieben, wie deine Augen uns sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'Daß Jehovah, dein Gott, uns ansage den Weg, auf dem wir gehen, und das, was wir tun sollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'Und Jirmejahu, der Prophet, sprach zu ihnen: Ich habe gehört, seht, ich bete zu Jehovah, eurem Gott, nach euren Worten, und es soll geschehen, daß all das Wort, das Jehovah euch antwortet, ich euch ansage und euch kein Wort vorenthalte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'Und sie sprachen zu Jirmejahu: Es sei Jehovah ein wahrhafter und treuer Zeuge unter uns, wenn wir nicht nach all dem Wort, womit Jehovah, dein Gott, dich zu uns sendet, also tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Es sei gut oder böse, auf die Stimme Jehovahs, unseres Gottes, zu Dem wir dich senden, auf Ihn hören wir, auf daß es gut für uns sei, wenn auf die Stimme Jehovahs, unseres Gottes, wir hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Und es geschah am Ende von zehn Tagen, daß Jehovahs Wort an Jirmejahu geschah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Und er rief Jochanan, den Sohn Kareachs, und alle Obersten der Streitmächte, die mit ihm waren, und alles Volk vom Kleinen und bis zum Großen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'Und sprach zu ihnen: Also spricht Jehovah der Gott Israels, an Den ihr mich gesandt, daß euer Flehen ich fallen lasse vor Sein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Wenn ihr in diesem Lande wohnen bleibt, so will Ich euch bauen und nicht niederreißen, und euch pflanzen und nicht ausroden; denn Mich gereut des Bösen, das Ich euch getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Fürchtet euch nicht vor Babels König, vor dem ihr euch fürchtet! Fürchtet euch nicht vor ihm, spricht Jehovah, denn Ich bin mit euch, euch zu helfen und euch aus seiner Hand zu erretten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'Und Ich will euch Erbarmen geben, und er wird euer sich erbarmen und euch auf euren Boden zurückkehren lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Und wenn ihr sprechet: Wir werden nicht in diesem Lande wohnen, so daß ihr nicht hört auf die Stimme Jehovahs, eures Gottes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'Wenn ihr sagt: Nein, laßt uns in das Land Ägypten eingehen, daß wir nicht Streit sehen und nicht hören die Stimme der Posaune, und nicht nach Brot hungern. Und lasset uns dort wohnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'So hört nun darum das Wort Jehovahs, ihr Überrest Jehudahs: So spricht Jehovah der Heerscharen, der Gott Israels: Setzet ihr euer Angesicht, einzugehen nach Ägypten, und ihr kommt hinein, als Fremdlinge allda zu weilen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'So soll geschehen, daß das Schwert, vor dem ihr euch fürchtet, euch dort erreicht in dem Land Ägypten, und der Hunger, dessen ihr euch besorgtet, soll dort hinter euch her sich an euch hängen in Ägypten, daß dort ihr sterbet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'Und wird geschehen, daß alle Männer, die ihre Angesichte setzen, nach Ägypten zu kommen, daß sie dort als Fremdlinge weileten, daselbst sterben durch das Schwert, durch Hunger und durch Pest, und wird kein Rest unter ihnen sein und keiner entkommen vor dem Bösen, das Ich kommen lasse über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Denn also spricht Jehovah der Heerscharen, der Gott Israels: Wie sich ergoß Mein Zorn und Grimm über Jerusalems Bewohner, so wird Mein Grimm sich ergießen über euch, wenn ihr nach Ägypten kommt, und sollt zur Verwünschung, zum Erstaunen und zum Fluch und zur Schmach werden, und diesen Ort nicht wieder sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Geredet hat Jehovah über euch, ihr Überrest Jehudahs: Geht nicht ein nach Ägypten! Ihr sollt wissen, daß heute ich unter euch gezeugt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Denn ihr seid in euren Seelen abgeirrt, da ihr mich an Jehovah, euren Gott, sandtet und sprachet: Bete für uns zu Jehovah, unserem Gotte; und nach allem, was Jehovah, unser Gott, spricht, also sage uns an, und wir wollen es tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'Und ich sagte es heute euch an, ihr aber höret nicht auf Jehovahs, eures Gottes, Stimme, und auf alles, was Er euch durch mich sendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Und nun sollet ihr wissen, daß ihr durch das Schwert, durch Hunger und Pestilenz an dem Orte sterben werdet, dahin ihr Lust habt zu gehen, um allda als Fremdlinge zu weilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Und es geschah, als Jirmejahu vollendet hatte zu reden zu allem Volk alle Worte Jehovahs, ihres Gottes, die Jehovah, ihr Gott, an sie durch ihn gesandt hatte, alle diese Worte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'Da sprach Asarjah, Hoschajahs Sohn, und Jochanan, Kareachs Sohn, und alle vermessenen Männer, und sprachen zu Jirmejahu: Lüge redest du. Jehovah, unser Gott, hat dich nicht gesandt zu sprechen: Kommt nicht nach Ägypten, als Fremdlinge dort zu weilen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'Denn Baruch, der Sohn Nerijahs, hat dich angetrieben wider uns, damit er uns in der Chaldäer Hand gebe, daß sie uns töten und uns nach Babel wegführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'Und Jochanan, Kareachs Sohn, und alle Obersten der Streitmächte und das ganze Volk hörten nicht auf Jehovahs Stimme, daß sie im Lande Jehudah wohnen sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'Und Jochanan, der Sohn Kareachs, und alle Obersten der Streitmächte nahmen allen Überrest von Jehudah, die, so von allen Völkerschaften, dahin sie verstoßen worden, zurückgekommen waren, um im Lande Jehudah zu weilen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'Die Männer und die Weiber und die Kindlein und die Töchter des Königs und jede Seele, die Nebusaradan, der Hauptmann der Leibwachen bei Gedaljahu, dem Sohne Achikams, des Sohnes von Schaphan, und bei Jirmejahu, dem Propheten, und bei Baruch, Nerijahs Sohn, gelassen hatte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'Und sie gingen ein in das Land Ägypten, weil sie nicht auf die Stimme Jehovahs hörten, und kamen bis Thachpanches.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Und es geschah das Wort Jehovahs an Jirmejahu in Thachpanches, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Nimm in deine Hand große Steine und lege sie hehlings in den Lehm im Ziegelofen an den Eingang in das Haus Pharos, in Thachpanches vor den Augen der jüdischen Männer,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'Und sprich zu ihnen: Also spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich sende und hole Nebuchadrezzar, Babels König, meinen Knecht, und setze seinen Thron über diese Steine, die Ich hehlings hingelegt habe, und er spanne sein Gezelt aus über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Und er kommt und schlägt das Land Ägypten: mit dem Tode die, so des Todes sind, mit Gefangenschaft die, so für Gefangenschaft sind, mit dem Schwert, die für das Schwert sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'Und Feuer zünde Ich an in den Häusern der Götter Ägyptens, daß er sie verbrenne, und sie gefangen führe und sich umhülle mit dem Lande Ägypten, wie der Hirt sich mit seinem Kleid umhüllt und geht aus davon im Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'Und soll die Bildsäulen des Sonnenhauses im Lande Ägypten zerbrechen und die Häuser der Götter Ägyptens mit Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Das Wort, das an Jirmejahu geschah, über alle Juden, so im Lande Ägypten wohnen, die so in Migdol und in Thachpanches und in Noph und im Lande Pathros wohnen, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'So spricht Jehovah der Heerscharen, der Gott Israels: Ihr habt gesehen all das Böse, das Ich über Jerusalem und über alle Städte Jehudahs kommen ließ und seht, eine Öde sind sie dieses Tages und niemand wohnt darin;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'Ob ihrer Bosheit, die sie taten, daß sie Mich reizten, daß sie hingingen zu räuchern, zu dienen anderen Göttern, die sie nicht kannten, weder sie, noch ihr, noch eure Väter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Und Ich sandte zu euch alle Meine Knechte, die Propheten, fing früh an und sandte sie und sprach: Tut doch solchen Greuel nicht, den Ich hasse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'Aber sie hörten nicht und sie neigten nicht ihr Ohr, daß sie umkehrten von ihrer Bosheit, daß sie anderen Göttern nicht räucherten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Und es ergoß sich Mein Grimm und Mein Zorn und brannte in den Städten Jehudahs und in den Gassen Jerusalems, und sie wurden zur Öde, zur Verwüstung, wie an diesem Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Und nun spricht also Jehovah, der Gott der Heerscharen, der Gott Israels: Warum tut ihr großes Böse wider eure Seelen, daß ihr für euch ausrottet, Mann und Weib, Kindlein und Säugling, aus Jehudahs Mitte, daß euch kein Überrest mehr übrigbleibt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Daß ihr Mich reizet durch eurer Hände Werk, da ihr anderen Göttern räuchert im Lande Ägypten, in das ihr kamt, um allda zu weilen, daß ihr euch ausrottet, und daß ihr zum Fluch und zur Schmach unter allen Völkerschaften der Erde werdet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Habt ihr vergessen die Bosheiten eurer Väter, und die Bosheiten der Könige Jehudahs, und die Bosheiten ihrer Weiber und eure Bosheiten, und die Bosheiten eurer Weiber, die sie im Lande Jehudahs taten, und auf den Gassen Jerusalems?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Noch sind sie nicht zerknirscht bis auf diesen Tag, und fürchten sich nicht und wandeln nicht in Meinem Gesetz und in Meinen Satzungen, die Ich vor euch und eure Väter gegeben habe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Darum, so spricht Jehovah der Heerscharen, der Gott Israels: Siehe, Ich setze Mein Angesicht wieder euch zum Bösen, und zur Ausrottung von ganz Jehudah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'Und Ich werde den Überrest von Jehudah nehmen, die, so ihr Angesicht gesetzt haben in das Land Ägypten einzuziehen, da zu weilen; sie alle sollen umkommen im Lande Ägypten, sie sollen fallen durch das Schwert und durch Hunger umkommen, vom Kleinen bis zum Großen. Durch das Schwert und durch Hunger sollen sie sterben und zur Verwünschung, zum Erstaunen und zum Fluch und zur Schmach werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Und die so im Lande Ägypten wohnen, will Ich heimsuchen, wie Ich Jerusalem durch das Schwert, durch Hunger und durch Pest habe heimgesucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'Und soll kein Entkommen noch Rest sein für den Überrest Jehudahs, die gekommen sind, dort im Land Ägypten zu weilen, und um in das Land Jehudah zurückzukehren, wohin sie ihre Seele erhoben, dahin zurückzukehren, um allda zu wohnen; denn sie werden nicht zurückkehren, es sei denn die Entkommenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Und es antworteten dem Jirmejahu alle Männer, die da wußten, daß ihre Weiber anderen Göttern räucherten und alle Weiber, die in großer Versammlung standen, und alles Volk, die, so im Land Ägypten, in Pathros wohnten und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Das Wort, das du zu uns im Namen Jehovahs geredet hast, darin hören wir nicht auf dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'Sondern lasset uns tun jedes Wort, das aus unserem Munde ausging, der Königin der Himmel räuchern und ihr Trankopfer ausgießen, wie wir getan, wir und unsere Väter, unsere Könige und unsere Obersten in Jehudahs Städten und in den Gassen Jerusalems. Und wir wurden satt am Brot und hatten es gut und sahen nichts Böses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Und seit wir aufhörten, der Königin der Himmel zu räuchern und ihr Trankopfer auszugießen, mangelt es uns an allem, und wir kamen um durch das Schwert und durch den Hunger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Und wenn wir der Königin der Himmel räuchern und ihr Trankopfer ausgießen, machen wir ihr ohne unsere Männer Kuchen, sie zu verehren, und gießen ihr Trankopfer aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'Und Jirmejahu sprach zum ganzen Volke, zu den Männern und zu den Weibern und zu allem Volke, zu denen, die ihm das Wort antworteten, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Hat nicht eurer Räucherungen, mit denen ihr in Jehudahs Städten und in den Gassen Jerusalems, ihr und eure Väter, eure Könige und eure Obersten und das Volk des Landes räucherten, hat nicht ihrer Jehovah gedacht, und stieg es nicht auf in Sein Herz?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'Und Jehovah vermochte es nicht mehr zu tragen vor der Bosheit eurer Handlungen, vor den Greueln, die ihr tatet, so daß euer Land zur Öde und zum Erstaunen und zum Fluche ward, daß niemand wohnt darin, wie an diesem Tag?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Davor, daß ihr geräuchert und daß ihr wider Jehovah gesündigt und auf Jehovahs Stimme nicht gehört habt, und in Seinem Gesetz und in Seinen Satzungen und in Seinen Zeugnissen nicht wandeltet, darum ist euch dieses Böse begegnet, wie an diesem Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Und Jirmejahu sprach zu allem Volk und zu allen Weibern: Hört das Wort Jehovahs, ganz Jehudah, die ihr im Land Ägypten seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'So spricht Jehovah der Heerscharen, der Gott Israels, sprechend: Ihr und eure Weiber habt mit eurem Mund geredet und erfüllt mit euren Händen was ihr sprachet: Wir wollen nach unseren Gelübden, die wir gelobt, tun, daß wir räuchern der Königin der Himmel und ihr Trankopfer ausgießen. Bestätigt eure Gelübde und tut eure Gelübde!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Darum höret das Wort Jehovahs, ganz Jehudah, die ihr im Land Ägypten wohnt: Siehe, Ich schwöre es bei Meinem großen Namen, spricht Jehovah: Nie mehr soll Mein Name angerufen werden mit dem Munde irgendeines Mannes aus Jehudah, daß er spreche: Es lebt der Herr Jehovah! im ganzen Land Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Siehe, Ich wache über sie zum Bösen und nicht zum Guten, daß jeder Mann aus Jehudah im Land Ägypten umkomme, durch das Schwert und durch den Hunger, bis sie alle sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'Und die dem Schwert entkommen, werden aus dem Lande Ägypten in das Land Jehudah zurückkommen, in geringer Zahl; und wird erkennen aller Überrest Jehudahs, so zum Lande Ägypten gekommen war, dort zu weilen, wessen Wort besteht, das von Mir oder das ihrige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'Und dies sei euch das Zeichen, spricht Jehovah, daß Ich euch heimsuche an diesem Ort, auf daß ihr erkennt, daß Ich Meine Worte über euch bestätige zum Bösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'So spricht Jehovah: Siehe, Ich gebe den Pharao Chophra, Ägyptens König, in seiner Feinde Hand und in die Hand derer, die ihm nach der Seele trachten, wie Ich Zidkijahu, Jehudahs König, gab in die Hand Nebuchadrezzars, des Königs von Babel, seines Feindes, und dessen, der ihm nach der Seele trachtete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Das Wort, das Jirmejahu, der Prophet, zu Baruch, Nerijahs Sohn, redete, da er diese Worte in ein Buch schrieb aus Jirmejahus Mund im vierten Jahre Jehojakims, des Sohnes Joschijahus, des Königs von Jehudah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'So spricht Jehovah, der Gott Israels, über dich, Baruch:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Du sprachst: Wehe mir doch, daß Jehovah Gram zu meinem Schmerz hinzutut. Ich bin müde von meinem Seufzen, und Ruhe finde ich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'So sollst du zu ihm sagen: So spricht Jehovah: Siehe, was Ich baute, reiße Ich nieder, und was Ich pflanzte, rode Ich aus, und dieses ganze Land ist es;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'Und du trachtest für dich nach Großem. Trachte nicht danach; denn siehe, Ich lasse Böses kommen über alles Fleisch, spricht Jehovah; dir aber gebe Ich deine Seele zur Beute an allen Orten, dahin du gehen wirst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Das Wort Jehovahs, das an Jirmejahu, den Propheten, geschah über die Völkerschaften,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'Wider Ägypten, wider die Streitmacht des Pharao Necho, des Königs von Ägypten, die am Flusse Phrath in Charchemisch war, die Nebuchadrezzar, Babels König, schlug im vierten Jahr Jehojakims, des Sohnes Joschijahus, des Königs von Jehudah:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Richtet her Tartsche und Schild, und tretet herzu zum Streit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Spannet die Rosse ein, steigt auf, ihr Reiter, und stellt euch auf in Helmen, scheuert die Speere, zieht die Panzer an!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Warum sehe Ich sie entsetzt hinter sich zurückweichen, und ihre Helden zerstoßen? In Flucht fliehen sie und wenden sich nicht; Bangen ringsum! spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Der Schnelle soll nicht entfliehen, und nicht entrinnen der Held; gegen Mitternacht, entlang dem Ufer des Flusses Phrath straucheln und fallen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Wer ist es, der aufsteigt wie der Strom, dessen Wasser wie Flüsse wogen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Ägypten, wie der Strom steigt es auf, und die Wasser wogen wie die Flüsse. Und es spricht: Ich steige auf und bedecke das Land, ich zerstöre die Stadt und die darin wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Steiget herauf, ihr Rosse, rast ihr Streitwagen; und lasset die Helden ausziehen, Kusch und Put, so die Tartsche erfassen, und die Ludim, so erfassen, spannen den Bogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Und dies ist der Tag für den Herrn Jehovah der Heerscharen, ein Tag der Rache, daß Er Sich an Seinen Drängern räche; und das Schwert fresse und werde satt und schwelge in ihrem Blut; denn ein Schlachtopfer sind sie dem Herrn Jehovah der Heerscharen im Lande der Mitternacht, am Flusse Phrath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Steige hinauf, Gilead und hole Balsam, Jungfrau, Tochter Ägyptens. Vergeblich machst du viel der Heilmittel. Da ist für dich kein Aufkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Die Völkerschaften hörten deine Unehre, deines Klageschreis ist voll die Erde; denn der Held strauchelt über den Helden, miteinander fallen sie beide.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Das Wort, welches Jehovah zu Jirmejahu, dem Propheten, redete, da Nebuchadrezzar, der König von Babel, kam, das Land Ägypten zu schlagen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Sagt es in Ägypten an, und laßt es in Migdol hören, und laßt es hören in Noph und in Thachpanches; sprechet: Stelle dich auf und bereite dich; denn das Schwert frißt rings um dich her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Warum ist weggefegt dein Gewaltiger? steht er nicht? denn Jehovah hat ihn fortgetrieben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Er macht viel der Strauchelnden, auch fällt der Mann über seinen Genossen. Und sie sprechen: Stehe auf, laßt uns zu unserem Volk zurückkehren, und zum Land unserer Geburt vor dem bedrückenden Schwerte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Sie rufen da: Zertrümmert ist Pharao, Ägyptens König. Seine bestimmte Zeit hat er vorbeigelassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Bei meinem Leben, spricht der König, Jehovah der Heerscharen ist Sein Name: denn wie der Thabor unter den Bergen und wie der Karmel an dem Meer kommt Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'Mache dir Geräte der Wegführung, du Einwohnerin, Tochter Ägyptens, denn verwüstet wird Noph werden und wird angezündet, daß niemand darin wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Ägypten ist eine gar schöne Färse, Zerrüttung kommt von Mitternacht, sie kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Auch ihre Söldlinge in ihrer Mitte sind wie gemästete Kälber; denn auch sie wenden sich, sie fliehen allzumal, sie stehen nicht; denn gekommen ist über sie der Tag ihrer Not, die Zeit ihrer Heimsuchung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Ihre Stimme geht wie einer Schlange; denn sie gehen mit Gewalt, und mit Äxten kommen sie zu ihr, wie die Holzhauer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'Sie hauen ihren Wald um, spricht Jehovah; denn er wird nicht ergründet, denn mehr sind ihrer, als der Heuschrecken, und ihrer ist keine Zahl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Die Tochter Ägyptens ist beschämt; sie ist in die Hand des Volks der Mitternacht gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Jehovah der Heerscharen, der Gott Israels, spricht: Siehe, Ich werde heimsuchen über Amon von No, und über Pharao und über Ägypten und über seine Götter und über seine Könige, und über Pharao und über die, so auf ihn vertrauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'Und gebe sie in derer Hand, die ihnen nach der Seele trachten, und in die Hand Nebuchadrezzars, des Königs von Babel, und in seiner Knechte Hand, aber nachher soll es wohnen, wie in der Vorzeit Tagen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Du aber fürchte dich nicht, Mein Knecht Jakob, und entsetze dich nicht, Israel; denn siehe, Ich rette dich aus der Ferne, und deinen Samen aus dem Land ihrer Gefangenschaft, und Jakob soll zurückkehren und ruhig und sorglos sein, und niemand soll ihn aufscheuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Du, fürchte dich nicht, Mein Knecht Jakob, spricht Jehovah; denn Ich bin mit dir. Wenn Ich Vollendung mache mit allen Völkerschaften, dahin Ich dich verstoßen hatte, so mache Ich doch mit dir keine Vollendung, aber züchtige dich nach dem Recht, und lasse dich nicht ungestraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Das Wort Jehovahs, das an den Propheten Jirmejahu geschah wider die Philister, ehe denn Pharao Gazah schlug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'So spricht Jehovah: Siehe, Wasser steigen auf von Mitternacht und werden zu einem überflutenden Bache, und sie überfluten das Land und seine Fülle, die Stadt und die darin wohnen; und schreien werden die Menschen und heulen wird alles, was im Lande wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Ob dem Lärm des Stampfens der Hufe ihrer Gewaltigen, ob dem Gerassel ihrer Streitwagen und dem Getümmel ihrer Räder wenden sich Väter nicht zu den Söhnen vor Erschlaffung ihrer Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'Ob dem Tag, der da kommen wird, alle Philister zu verheeren, auszurotten Zor und Zidon, und allen Rest, der beisteht, denn Jehovah verheert die Philister, den Überrest der Insel Kaphthor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Kahlheit kommt über Gazah, Aschkalon geht unter, der Überrest ihres Talgrundes. Bis wann wirst du dich ritzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'O Schwert Jehovahs, bis wann wirst du nicht rasten? Ziehe dich zurück in deine Scheide. Ruhe dich aus und sei stille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Wie kannst du rasten? Und Jehovah hat ihm wider Aschkalon geboten und an des Meeres Gestade es beschieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'Über Moab. So spricht Jehovah der Heerscharen, der Gott Israels. Wehe über Nebo! Denn es ist verheert worden, beschämt und erobert ist Kirjathaim; Misgab ist beschämt und entsetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Nichts mehr ist es mit dem Lobe Moabs. In Cheschbon gedenkt man Böses wider dasselbe. Kommt, lasset uns es ausrotten, daß es keine Völkerschaft mehr ist. Auch Madmen geht unter. Hinter dir geht das Schwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Die Stimme des Geschreis von Choronajim: Verheerung und großes Zerbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Zerbrochen ist Moab. Ein Geschrei lassen seine Jüngeren hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Denn Weinen steigt die Steige von Luchith herauf mit Weinen; denn beim Herabsteigen von Choronaim hören die Dränger das Geschrei des Zerbrechens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Fliehet, laßt entrinnen eure Seele, und sie seien wie ein bloßer Strauch der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Darum, daß du vertraust auf deine Werke und auf deine Schätze, wirst auch du erobert werden: und Chemosch wird in Verbannung ausziehen, seine Priester und seine Obersten allzumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'Und der Verheerer kommt über jegliche Stadt, und keine Stadt entrinnt, und verloren ist der Talgrund, und die Ebene vernichtet, so spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Gebet Moab Flügel, denn im Ausflug wird es ausfliegen, und seine Städte werden zur Verwüstung, daß niemand darin wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Verflucht sei, wer das Werk Jehovahs trüglich tut, und verflucht, wer abhält sein Schwert vom Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Sorglos war Moab von Jugend auf und rastete auf seinen Hefen, es ward nicht ausgeleert von Gefäß zu Gefäß; und es ging nicht zur Wegführung. Darum ist sein Geschmack ihm stehengeblieben, und sein Geruch ward nicht umgewandelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Darum siehe, Tage kommen, spricht Jehovah, daß Ich Umleerer sende, die es umleeren, und seine Gefäße umleeren und zerschmeißen seine Schläuche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Und Moab soll beschämt werden ob dem Chemosch, wie das Haus Israel beschämt ward ob Bethel, auf das es vertraute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Wie sprechet ihr: Wir sind Helden und tapfere Männer zum Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Verheert ist Moab, und seine Städte gehen auf. Und die Auswahl seiner Jünglinge geht hinab zur Schlachtbank, spricht der König, Jehovah der Heerscharen ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Nah, daß es komme, ist Moabs Not. Und sein Übel eilt sehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Zeiget ihm Beileid, alle ringsum und alle, die ihr seinen Namen kennt, sprechet: Wie ist doch der Stab der Stärke zerbrochen, der Stock des Schmuckes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Steige herab von der Herrlichkeit, sitze im Durste, Einwohnerin, Tochter von Dibon; denn der Verheerer Moabs steigt wider dich herauf, verdirbt deine Festungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Stehe an den Weg und spähe aus, Einwohnerin von Aroer, frage den Flüchtigen und was entronnen ist, sprich: Was ist geschehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Beschämt ist Moab, ja entsetzt. Heulet und schreit! Sagt es am Arnon an, daß Moab verheert ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'Und ein Gericht ist über das Land der Ebene gekommen, über Cholon und über Jahzah und über Mephaath,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'Und über Dibon und über Nebo und über Beth-Diblathajim,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'Und über Kirjathajim und über BethGamul und über Beth-Meon,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'Und über Kerijoth und über Bozrah und über alle Städte des Landes Moab, die fernen und die nahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Das Horn Moabs ist zerhauen und sein Arm gebrochen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Berauschet es; denn über Jehovah machte es sich groß, und es patsche Moab in sein Gespei, und werde selbst auch zum Gelächter!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Und war dir Israel nicht zum Gelächter oder war es unter den Dieben gefunden, daß du, sooft du von ihm redetest, dich geschüttelt hast?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Verlasset die Städte und wohnet auf der Felsenklippe, die ihr in Moab wohnet, und seiet wie die Taube, die an den Seiten der Mündung der Höhle nistet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Wir haben von dem Stolze Moabs gehört, es ist sehr hochmütig von seiner Hoffart und seinem Stolz und seinem Übermut, und der Überhebung seines Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Ich kenne, spricht Jehovah, sein Wüten, daß es nicht recht ist, seine Unwahrheiten, daß sie, was nicht recht ist, getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Darum heule Ich über Moab und schreie über ganz Moab, über die Männer von Kir-Cheres muß man stöhnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Mehr als man weinte über Jaeser, weine Ich über dich, du Weinstock Sibmahs. Deine Ranken gingen über das Meer, bis zum Meer Jaesers reichten sie. In deine Obsternte und deine Weinlese fällt der Verheerer ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'Fröhlichkeit und Frohlocken ist weggenommen von dem Fruchtgefilde und von dem Lande Moabs, und den Wein laß von den Kufen Ich zu Ende kommen. Man keltert nimmer bei dem Kelterlied. Das Hedad ist kein Hedad.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'Vom Geschrei Cheschbons an bis Elealeh, bis Jahaz erheben sie ihre Stimme; von Zoar bis Choronajim, eine dreijährige Färse; denn auch die Wasser Nimrims werden verwüstet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'Und Ich lasse zu Ende kommen für Moab, spricht Jehovah, das Opfern auf den Opferhöhen und das Räuchern für seine Götter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Darum dröhnt mein Herz um Moab wie Flöten, um die Männer von Kir-Cheres dröhnt mein Herz wie Flöten, weil das übrige, das es gemacht, verloren ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Denn auf jedem Haupt ist Kahlheit und jeder Bart ist abgeschoren, auf allen Händen Ritze und auf den Lenden Säcke,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Auf allen Dächern Moabs und in seinen Straßen ist alles Klagen; denn zerbrochen habe Ich Moab, wie ein Gefäß, an dem man keine Lust hat, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Wie ist es entsetzt! Heulet! Wie hat Moab den Nacken gewendet! Schäme dich! Und Moab ist zum Gelächter und zum Entsetzen allen ringsumher geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Denn so spricht Jehovah: Siehe, wie der Adler schwebt er daher und breitet seine Flügel über Moab aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kerioth wird erobert und die Festen, sie wird eingenommen. Und an selbigem Tage wird das Herz der Helden Moabs wie das Herz des Weibes, das am Kreißen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'Und Moab wird vernichtet, daß es kein Volk ist; denn wider Jehovah hat es sich groß gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Schauer und Fallgrube und Schlinge über dich, der du in Moab wohnst, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Wer vor dem Schauer flieht, fällt in die Fallgrube, und wer heraufkommt aus der Fallgrube, wird in der Schlinge gefangen; denn Ich lasse über dasselbe, über Moab, das Jahr ihrer Heimsuchung kommen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'Im Schatten Cheschbons stehen die, so aus Kräften flohen; jedoch ein Feuer geht von Cheschbon aus und eine Flamme zwischen Sichon hervor und frißt die Ecke Moabs und den Scheitel der Söhne des Tosens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Wehe dir, Moab, verloren ist das Volk des Chemosch, denn man hat deine Söhne in Gefangenschaft genommen und deine Töchter in Gefangenschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Doch will Ich die Gefangenschaft Moabs in den letzten der Tage zurückwenden, spricht Jehovah. Bis hierher das Gericht Moabs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'Wider die Söhne Ammons: So spricht Jehovah: Hat Israel keine Söhne? Hat es keinen Erbbesitzer? Warum beerbet ihr König Gad und wohnt sein Volk in dessen Städten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Darum seht, kommen Tage, spricht Jehovah, da Ich hören lasse über Rabbah der Söhne Ammon Feldgeschrei des Streites, und da es zum wüsten Schutthaufen wird, und seine Töchter mit Feuer angezündet werden, und Israel beerben wird die, so ihn beerbt hatten, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Heule, Cheschbon; denn verheert ist Ai. Schreit, ihr Töchter Rabbahs, gürtet euch mit Säcken, klaget und rennet zwischen den Mauern umher, denn ihr König geht hin, weggeführt, seine Priester und seine Obersten allzumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Was rühmst du dich der Talgründe? dein Talgrund, der fließt dahin, abwendige Tochter, die vertraut auf ihre Schätze: Wer kommt an mich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Siehe, Ich bringe Schauder über dich, spricht der Herr, Jehovah der Heerscharen, von allen rings um dich her; und ihr werdet verstoßen, jeder Mann vor sich hin, und niemand bringt die Flüchtigen zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Doch hernach wende Ich zurück die Gefangenschaft der Söhne Ammons, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'Wider Edom spricht also Jehovah der Heerscharen: Ist keine Weisheit mehr in Theman? Ist der Rat der Einsichtsvollen verlorengegangen? Ist ihre Weisheit stinkend geworden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Fliehet! Sie sind abgewandt, sie machten tief ihren Wohnsitz, die Bewohner Dedans; denn Esaus Not bringe Ich über ihn, die Zeit, da Ich ihn heimsuche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Wenn über dich Weinleser kommen, würden sie dir nicht Nachlese überlassen? wenn Diebe in der Nacht, verderben sie nach ihrer Genüge?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Denn Ich entblöße Esau, decke auf sein Verborgenes. Nicht kann er sich verstecken. Verheert ist sein Same und seine Brüder und seine Nachbarn, und er ist nicht mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Verlaß deine Waisen! Ich erhalte sie am Leben. Und deine Witwen sollen Mir vertrauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Denn so spricht Jehovah: Siehe, deren Gericht nicht war den Becher zu trinken, die tranken. Und du sollst ungestraft bleiben? Du sollst nicht ungestraft bleiben, du sollst trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Denn Ich habe bei Mir geschworen, spricht Jehovah, daß zur Verwüstung, zur Schmach, zur Öde und zum Fluch Bozrah soll werden, und alle seine Städte zu ewigen Öden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Ein Gerücht habe Ich gehört von Jehovah und eine Gesandtschaft wird an die Völkerschaften gesandt: Ziehet euch zusammen und kommt wider es und stehet auf zum Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Denn siehe, klein habe Ich dich hingegeben unter den Völkerschaften, verachtet unter den Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Dein Trotz hat dich verführt und deines Herzens Vermessenheit, der du in Klüften der Felsenklippe wohnst und die Höhe der Hügel eingenommen hast. Ob du hoch wie der Adler machst dein Nest, Ich bringe dich von da herab, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'Und Edom wird zur Verwüstung sein, jeder, der an ihm vorübergeht, erstaunt sich und zischt ob allen seinen Schlägen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Gleichwie in der Umkehrung Sodoms und Gomorrahs und ihrer Nachbarn, spricht Jehovah, soll allda kein Mann wohnen, nicht sich in ihm aufhalten ein Sohn des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Siehe, wie der Löwe von dem Anschwellen des Jordans aufsteigt nach dem Wohnorte Ethans. Aber im Augenblick lasse Ich ihn von dannen laufen. Und wer ist der Auserwählte, den Ich über sie bestellt? Denn wer ist wie Ich? Und wer ruft Mich zum Zeugen vor, und wer ist der Hirte, der vor Meinem Angesicht steht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Darum hört den Ratschluß Jehovahs, den Er über Edom beschlossen hat, und Seine Gedanken, die Er wider Themans Bewohner denkt: Schleppen sie nicht davon die Geringen der Herde; verwüsten sie nicht ihren Wohnort?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Die Erde bebt von dem Getöse ihres Falls, am Schilfmeere hört man die Stimme seines Geschreis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Siehe, wie der Adler steigt er auf und schwebt und breitet seine Flügel über Bozrah, und das Herz der Helden Edoms wird an dem Tage wie das Herz des Weibes im Kreißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'Wider Damask. Beschämt ist Chamath und Arpad; denn ein böses Gerücht hören sie, sie zerfließen. Am Meer ist Besorgnis, sie vermögen nicht zu rasten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Damask erschlafft, hat sich zur Flucht gewandt, und grauen hat sie gefaßt, Drangsal und Geburtsnöten sie ergriffen, wie die Gebärerin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, 'Wie ist sie nicht verlassen, die Stadt des Lobes, Meiner Freude Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Darum fallen sie auf ihren Straßen ihre Jünglinge, und alle Männer des Streites gehen unter an jenem Tage, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'Und in der Mauer von Damask zünde Ich Feuer an, daß es Benhadads Paläste auffresse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'Wider Kedar und wider die Königreiche Chazors, die Nebuchadrezzar, Babels König, schlug. So spricht Jehovah: Steht auf und ziehet wider Kedar hinauf und verheeret die Söhne des Ostens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Und ihre Zelte und ihr Kleinvieh nehmen sie, ihre Teppiche und all ihre Geräte und ihre Kamele nehmen sie für sich fort, und rufen über sie: Bangen ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Fliehet, schweifet sehr umher! Gehet in die Tiefe zu wohnen Chazors Bewohner, spricht Jehovah; denn Nebuchadrezzar, der König Babels, hat einen Ratschluß wider euch beschlossen; und er denkt einen Gedanken wider sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Steht auf, zieht hinauf zu einer zufriedenen Völkerschaft, die da wohnt in Sicherheit, spricht Jehovah, keine Türflügel und keine Riegel hat sie, einsam wohnen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'Und ihre Kamele sollen zum Raube werden, und ihrer Viehherden Menge zur Beute, und Ich zersprenge in alle Winde die im Winkel Abgeschnittenen, und lasse ihre Not von allen Seiten kommen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Und Chazor soll werden zur Behausung der Drachen, zur Verwüstung ewiglich. Nicht wird ein Mann darin wohnen, und nicht in ihr sich aufhalten ein Menschensohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Das Wort Jehovahs, das geschah an Jirmejahu, den Propheten, wider Elam im Anfang der Regierung Zidkijahus, des Königs von Jehudah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'So spricht Jehovah der Heerscharen: Siehe, Ich breche Elams Bogen, den Erstling seiner Macht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'Und Ich lasse kommen über Elam vier Winde von den vier Enden der Himmel, und zersprenge sie nach allen diesen Winden, und keine Völkerschaft soll sein, wohin nicht kämen Verstoßene von Elam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'Und Ich lasse Elam sich entsetzen vor seinen Feinden und vor denen, die nach seiner Seele trachten, und werde Böses über sie bringen, Meines Zornes Entbrennen, spricht Jehovah, und hinter ihnen her das Schwert senden, bis daß Ich sie alle gemacht habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'Und Meinen Thron will Ich in Elam setzen und von da König und Oberste zerstören, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Und in den letzten der Tage wird geschehen, daß Ich zurückwende Elams Gefangenschaft, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Das Wort, welches Jehovah wider Babel, wider das Land der Chaldäer, durch die Hand Jirmejahus, des Propheten, geredet hat:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Sagt an unter den Völkerschaften und laßt hören, und erhebt ein Panier, laßt hören, verhehlet nicht, sprechet: Babel ist eingenommen, Bel ist beschämt, Merodach ist entsetzt, beschämt sind seine Götzenbilder, entsetzt seine Götzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Denn wider dasselbe zieht herauf eine Völkerschaft von Mitternacht. Sie wird ihr Land zur Verwüstung setzen, und kein Bewohner wird darinnen sein. Vom Menschen und bis zum Vieh entfliehen sie und gehen davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'In jenen Tagen und zu jener Zeit, spricht Jehovah, werden die Söhne Israels kommen, sie und die Söhne Jehudahs allzumal, gehend und weinend gehen sie, Jehovah, ihren Gott, zu suchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Nach Zijon fragen sie den Weg, dahin ist ihr Angesicht: Kommt und laßt uns Jehovah anhangen, in ewigem Bunde, der nicht soll vergessen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Eine verlorene Herde ist Mein Volk, ihre Hirten führten es irre, abwendige Berge, von Berg zu Hügel gingen sie, vergaßen ihrer Lagerstätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Alle die, so sie fanden, fraßen sie auf, und ihre Dränger sprachen: Wir verschulden uns nicht, darum, daß sie sich wider Jehovah, den Wohnort der Gerechtigkeit, und ihrer Väter Hoffnung, wider Jehovah, versündigt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Entfliehet aus Babels Mitte, und vom Lande der Chaldäer gehet aus, und seiet als die Böcke, vor den Schafen her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Denn siehe, Ich errege und bringe herauf wider Babel eine Versammlung großer Völkerschaften aus dem Lande der Mitternacht, und sie ordnen sich wider sie; von dorther soll es erobert werden; seine Pfeile sind wie die des klugen Helden, sie kehren nicht leer zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'Und Chaldäa wird zur Beute; alle, die sie erbeuten, sollen satt werden, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Denn ihr seid fröhlich, denn ihr jauchzet, ihr Plünderer Meines Erbes, wachset heran wie die Färse, die drischt, und wiehert wie die Gewaltigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'Sehr beschämt ist eure Mutter, sie errötet, die euch gebar. Siehe, die letzte der Völkerschaften, eine Wüste, eine Dürre, und eine Einöde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Ob der Entrüstung Jehovahs wird sie nicht bewohnt, und wird ganz zur Verwüstung werden. Ein jeder, der vorübergeht an Babel, wird erstaunen, und wird ob allen ihren Schlägen zischen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Ordnet euch wider Babel ringsumher, all ihr Spanner des Bogens, schießt auf sie, schont des Pfeiles nicht; denn wider Jehovah hat sie gesündigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Erhebet ringsum wider sie das Feldgeschrei. Ihre Hand gibt sie, ihre Grundfesten fallen, ihre Mauern reißt man nieder; denn Jehovahs Rache ist es. Rächt euch an ihr! Wie sie getan hat, tuet ihr!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Rottet den Sämann aus von Babel, und den, so die Sichel faßt zur Zeit der Ernte. Vor dem bedrückenden Schwerte wendet sich jeder Mann zu seinem Volk, und jeder Mann flieht in sein Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Ein verscheuchtes Schaf ist Israel, Löwen verjagten es. Zuerst fraß es der König Aschurs, und hernach zerdrückte ihm das Gebein Nebuchadrezzar, Babels König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Darum spricht also Jehovah der Heerscharen, der Gott Israels: Siehe, Ich suche heim den König Babels und sein Land, wie Ich den König Aschurs heimgesucht habe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'Und bringe Israel zurück in seinen Wohnort, so daß es auf Karmel und in Baschan weidet, und auf dem Gebirge Ephraim und Gilead sich seine Seele sättige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'In jenen Tagen und zu jener Zeit, spricht Jehovah, wird man die Missetat Israels suchen, und wird keine da sein, und Jehudahs Sünde, und man wird keine finden; denn Ich werde dem vergeben, den Ich verbleiben ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Wider das Land der zweifachen Widerspenstigkeit: Ziehe hinauf wider dasselbe und wider die, so in Pekod wohnen, veröde und banne ihre Nachkommen, spricht Jehovah, und tue nach allem, was Ich dir gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Des Streites Stimme ist im Lande, und großes Zerbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Wie ist der Hammer doch des ganzen Landes zerhauen und zerbrochen! Wie ward Babel zur Verwüstung unter den Völkerschaften!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Ich legte dir Fallstricke, Babel, und du fingst dich auch, und du wußtest es nicht. Du wardst gefunden und auch erfaßt, denn Jehovah hast du befehdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Jehovah hat Seine Schatzkammer geöffnet und die Geräte Seines Unwillens herausgebracht, denn ein Geschäft hat der Herr Jehovah der Heerscharen im Lande der Chaldäer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Kommt wider sie vom Ende, öffnet ihre Scheunen, schichtet sie auf wie Kornhaufen und verbannt sie, daß ihr kein Überrest sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Würgt alle ihre Farren, laßt sie zur Schlachtbank herabkommen. Wehe über sie, denn ihr Tag ist gekommen, die Zeit ihrer Heimsuchung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Die Stimme der Flüchtenden und der Entrinnenden aus Babels Land! anzusagen in Zijon die Rache Jehovahs, unseres Gottes, die Rache für Seinen Tempel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Rufet Schützen auf wider Babel, alle die den Bogen spannen; lagert euch ringsumher, daß kein Entkommen ist. Vergeltet ihr nach ihren Werken, tut ihr nach allem, was sie tat; denn wider Jehovah, den Heiligen Israels, vermaß sie sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Darum sollen ihre Jünglinge auf ihren Straßen fallen, und alle ihre Männer des Streites an jenem Tage untergehen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Siehe, Ich bin wider dich, Vermessene, spricht der Herr Jehovah der Heerscharen; denn gekommen ist dein Tag, die Zeit deiner Heimsuchung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Und straucheln wird der Vermessene und fallen, und keiner richtet ihn auf; und Ich zünde ein Feuer an in seinen Städten, das alles um ihn her auffresse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'So spricht Jehovah der Heerscharen: Unterdrückt sind die Söhne Israels und Jehudahs Söhne allzumal, und alle, die sie gefangenführten, halten sie fest, sie weigern sich, sie zu entsenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Stark ist ihr Erlöser! Jehovah der Heerscharen ist Sein Name. Er hadert ihren Hader, auf daß Er das Land ausruhen lasse, und zittern lasse, die in Babel wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Das Schwert ist wider die Chaldäer, spricht Jehovah, und wider die Einwohner Babels und wider seine Obersten und wider seine Weisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'Das Schwert ist wider die Unwahren, und zu Narren werden sie; das Schwert ist wider seine Helden, daß sie sich entsetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'Das Schwert ist wider seine Rosse und wider seine Streitwagen und wider allen Troß in seiner Mitte, daß sie zu Weibern werden; das Schwert ist wider seine Schätze, daß sie geraubt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'Dürre kommt über ihre Wasser, daß sie vertrocknen; denn ein Land der Schnitzbilder ist es, und sie rühmen sich ihrer Schreckbilder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Darum sollen Zijim mit Ijim und Käuzlein darin wohnen. Und man soll nimmermehr darin wohnen, noch soll man dort wohnen zu Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Und wie Gott Sodom und Gomorrah und deren Nachbarn umkehrte, spricht Jehovah, soll allda kein Mann wohnen, noch darin sich aufhalten ein Sohn des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Siehe, ein Volk kommt von Mitternacht, und eine große Völkerschaft und viele Könige werden auferweckt von den Seiten der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Bogen und Wurfspieß fassen sie, sind grausam und erbarmen sich nicht, ihre Stimme ist wie ein tobend Meer, und auf Rossen reiten sie, geordnet wie der Mann zum Streite, wider dich, Tochter Babels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Der König Babels hört ihr Gerücht und seine Hände werden schlaff, Angst ergreift ihn, Wehen, wie die Gebärerin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Siehe, wie der Löwe von dem Anschwellen des Jordan aufsteigt nach dem Wohnorte Ethans! Aber im Augenblick lasse Ich ihn von ihr laufen. Und wer ist der Auserwählte, den Ich über sie bestellte? Denn wer ist wie Ich? Und wer ruft Mich zum Zeugen vor, und wer ist der Hirte, der vor Meinem Angesichte steht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Darum hört Jehovahs Ratschluß, den Er über Babel beschlossen hat, und Seine Gedanken, die Er denkt wider der Chaldäer Land. Denn schleppen sie nicht davon die Geringen der Herde? Verwüsten sie nicht ihren Wohnort über ihnen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Von der Stimme: Babel ist eingenommen! erbebt die Erde, und das Geschrei wird gehört unter den Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'So spricht Jehovah: Siehe, Ich errege wider Babel, und wider die Bewohner, die im Herzen wider Mich aufstanden, einen verderblichen Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'Und Ich sende Worfler gen Babel, daß sie dasselbe worfeln und sein Land ausleeren; denn sie werden am Tag des Bösen rings um sie her sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Dawider spanne, spanne, der spannet seinen Bogen, und dawider steige er herauf in seinem Panzer. Und bemitleidet nicht ihre Jünglinge, verbannet all ihr Heer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'Daß Erschlagene fallen im Land der Chaldäer und Durchstochene in ihren Gassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Denn Israel und Jehudah sollen nicht verwitwet sein von ihrem Gotte, von Jehovah der Heerscharen, denn ihr Land ist voller Schuld am Heiligen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Fliehet aus Babels Mitte und es lasse entrinnen jeder Mann seine Seele, daß er nicht untergehe in seiner Missetat; denn der Rache Zeit ist für Jehovah, nach Verdienst vergilt Er ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Ein Becher von Gold war Babel in der Hand Jehovahs, der berauschte die ganze Erde. Von seinem Wein tranken die Völkerschaften, darum rasen die Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Plötzlich ist gefallen Babel und zerbrochen. Heulet über sie. Holt Balsam für ihre Schmerzen, vielleicht wird sie geheilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, 'Wir heilten an Babel, aber sie ließ sich nicht heilen. Verlasset sie und laßt uns gehen, jeder Mann in sein Land; denn zum Himmel reicht ihr Gericht, und hat bis an den Wolkenhimmel sich erhoben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Jehovah ließ unsere Gerechtigkeit hervorgehen; kommt und laßt in Zijon uns erzählen das Tun Jehovahs, unseres Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Feget die Pfeile, füllt die Schilde. Jehovah hat den Geist der Könige Madais auferweckt, denn Sein Sinnen ist wider Babel, es zu verderben; denn dies ist Jehovahs Rache, die Rache Seines Tempels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Wider die Mauern Babels erhebet ein Panier, macht stark die Hut, stellt Hüter auf, bereitet einen Hinterhalt; denn Jehovah ersinnt sowohl als Er auch tut, was Er wider die, so in Babel wohnen, geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'Die du auf vielen Wassern wohnst, groß an Schätzen, gekommen ist dein Ende, das Maß deines Gewinns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Geschworen hat bei Seiner Seele Jehovah der Heerscharen: Fürwahr, Ich fülle dich an mit Menschen, wie mit Heuschrecken, und sie antworteten ob dir mit einem Kelterlied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'Er hat die Erde gemacht durch Seine Kraft, die Welt bereitet durch Seine Weisheit, und durch Seine Einsicht die Himmel ausge- spannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Gibt Seine Stimme Er dahin, so ist Wasser die Menge an den Himmeln, und Er läßt Dünste aufsteigen von der Erde Ende, macht Blitze für den Regen, und bringt den Wind heraus aus Seinen Schatzkammern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Tierisch ist jeder Mensch durch das Wissen, beschämt wird jeder Goldschmied durch sein Schnitzbild, denn Lüge ist sein Gußbild, und kein Hauch in ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Nichtigkeit sind sie, ein Machwerk der Irrtümer. Sie vergehen zur Zeit ihrer Heimsuchung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Nicht wie sie ist Jakobs Teil; denn Er ist der Bildner des Ganzen, und die Rute Seines Erbes. Jehovah der Heerscharen ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Ein Hammer bist du Mir, ein Gerät des Streites; und mit dir zerschmeiße Ich Völkerschaften, und mit dir verderbe Ich Königreiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'Und durch dich zerschmeiße Ich das Roß und dessen Reiter, und zerschmeiße mit dir den Streitwagen und den, der darin fährt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'Und durch dich zerschmeiße Ich Mann und Weib, und durch dich zerschmeiße Ich den Alten und den Jungen, und zerschmeiße durch dich den Jüngling und die Jungfrau.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'Und durch dich zerschmeiße Ich den Hirten und seinen Trieb, und zerschmeiße durch dich den Ackersmann und sein Gespann; und durch dich zerschmeiße Ich Statthalter und Landvögte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'Und Ich vergelte Babel und allen, die in Chaldäa wohnen, all ihr Böses, das sie in Zijon vor euren Augen taten, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Siehe, Ich bin wider dich, du verderbender Berg, spricht Jehovah, der du verdirbst die ganze Erde, und recke Meine Hand aus wider dich und wälze dich von den Felsenklippen, und gebe dich zum Berge der Verbrennung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'Und man soll nicht von dir nehmen einen Stein zur Ecke noch zu den Grundfesten; denn du sollst zu ewigen Verwüstungen werden, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Erhebet ein Panier im Lande, stoßt in die Posaune unter den Völkerschaften, heiligt Völkerschaften wider sie, laßt hören wider sie Königreiche Ararat, Minni und Aschbenas. Bestellt einen Befehlshaber wider sie, bringt Rosse herauf gleich borstigen Heuschrecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Heiligt Völkerschaften wider sie, die Könige Madais, dessen Statthalter und alle seine Landvögte und alle Lande seiner Herrschaft;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'So daß das Land erbebe und kreiße; denn die Gedanken Jehovahs wider Babel stehen fest, daß Er zur Verwüstung setze Babels Land, daß niemand darin wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Die Helden Babels hören auf zu streiten; sie sitzen in den Festen; ihre Macht versiegt; zu Weibern sind sie geworden. Ihre Wohnungen werden angezündet, zerbrochen ihre Riegel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Ein Läufer läuft dem Läufer entgegen, und Verkünder begegnet Verkünder, dem König Babels anzusagen, daß seine Stadt vom Ende her erobert ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'Die Brücken sind eingenommen, die Binsenbüsche verbrannt mit Feuer, und die Männer des Streites sind bestürzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Denn also spricht Jehovah der Heerscharen, der Gott Israels: Wie eine Tenne ist die Tochter Babels zur Zeit, da man sie tritt, ein wenig noch und es kommt für sie die Zeit der Ernte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Gefressen hat mich, mich verwirrt Nebuchadrezzar, Babels König, mich hingestellt, ein leer Gefäß, hat mich verschlungen wie ein Walfisch hat seinen Wanst gefüllt mit meinen Leckerbissen und mich verstoßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Die Gewalttat an mir und meinem Fleisch sei über Babel! spricht Zijons Bewohnerin, und mein Blut auf die, so in Chaldäa wohnen! spricht Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Darum, so spricht Jehovah: Siehe, Ich hadere deinen Hader und räche deine Rache, und lasse vertrocknen ihr Meer und ihren Born trocken werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'Und Babel wird zu Steinhaufen, zur Wohnstätte der Drachen, zum Erstaunen und zum Zischen, daß niemand darin wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Sie brüllen wie junge Löwen allzumal, sie knurren wie die Jungen der Löwinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'In ihrer Hitze will Ich ihnen ein Gastmahl vorsetzten und sie berauschen, daß sie jauchzen und schlafen einen ewigen Schlaf, und nicht erwachen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Wie Lämmer bringe Ich sie hinab zum Schlachten, wie Widder mit den Böcken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Wie ward Scheschach erobert, und das Lob der ganzen Erde eingenommen! wie wurde Babel zur Verwüstung unter den Völkerschaften!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Über Babel stieg auf das Meer, von seiner Wogen Menge ist es bedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Zur Verwüstung wurden ihre Städte, ein dürres Land und eine Einöde, ein Land, da kein Mann innen wohnt, und da kein Menschsohn durchgeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'Und Ich suche heim den Bel in Babel, und bringe sein Verschlungenes heraus aus seinem Mund, und sollen fürder nimmer Völkerschaften zu ihm strömen. Auch Babels Mauer fällt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Zieh aus, Mein Volk, aus seiner Mitte, jeder Mann lasse seine Seele entrinnen vor der Entbrennung von Jehovahs Zorn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'Und damit euer Herz nicht weich werde, und ihr euch fürchtet ob dem Gerücht, das man im Lande hört, und wenn im Jahre das Gerücht kommt und im Jahr darauf kommt das Gerücht und Gewalttat ist im Lande: Herrscher wider Heerscher:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Darum siehe, Tage kommen, da Ich Babels Schnitzbilder heimsuche und all ihr Land beschämt wird, und alle ihre Erschlagenen in ihrer Mitte fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Und aufjauchzen werden über Babel Himmel und Erde und alles, was darinnen ist; denn von Mitternacht werden ihr kommen die Verheerer, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Wie Babel gefällt hat die Erschlagenen in Israel, so auch werden für Babel die Erschlagenen des ganzen Landes fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'Ihr, die ihr seid dem Schwert entkommen, gehet hin und bleibt nicht stehen. Gedenket aus der Ferne an Jehovah, und Jerusalem steige auf in eurem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Wir schämten uns, als wir die Schmach vernahmen, Schande bedeckte unser Angesicht, als Fremde über die Heiligtümer kamen von Jehovahs Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Darum siehe, Tage kommen, spricht Jehovah, da Ich ihre Schnitzbilder heimsuche, und der Durchbohrte in ihrem ganzen Lande jammern wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Stiege Babel auf gen Himmel und befestigte allda die Höhe seiner Stärke, sollen von Mir an sie Verheerer kommen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Die Stimme des Geschreis von Babel und großes Zerbrechen aus dem Lande der Chaldäer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'Denn Jehovah verheert Babel und zerstört sie mit großer Stimme, und ihre Wogen toben wie viele Wasser, sie geben dahin das Getöse ihrer Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Denn der Verheerer ist gekommen wider sie, wider Babel, und seine Helden sind gefangen, seine Bogen sind zerbrochen, denn ein Gott der Erwiderung ist Jehovah, vergeltend vergilt Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'Und Ich berausche seine Obersten und seine Weisen, seine Statthalter und seine Landvögte und seine Helden, daß einen ewigen Schlaf sie schlafen und nicht erwachen, spricht der König. Jehovah der Heerscharen ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'So spricht Jehovah der Heerscharen: Die Mauern Babels, des breiten, sie werden umgegraben und seine hohen Tore mit Feuer angezündet, so daß die Völker sich umsonst ermüdet und die Volksstämme für das Feuer, und sich abgemattet haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Das Wort, das Jirmejahu, der Prophet, gebot Serajah, dem Sohn Nerijahs, des Sohnes Machsejahs, als er mit Zidkijahu, dem König Jehudahs, gen Babel zog, im vierten Jahr seiner Regierung, und Serajah war Oberster des Ruheortes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'Und Jirmejahu schrieb all das Böse, das über Babel kommen sollte, in ein Buch, all diese Worte, die über Babel geschrieben sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'Und Jirmejahu sprach zu Serajah: Wie du nach Babel kommst, so siehe, daß du alle diese Worte lesest,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'Und sprich: Du hast, Jehovah, über diesen Ort geredet, ihn auszurotten, daß kein Bewohner darinnen sei, vom Menschen und bis zum Vieh; sondern eine Verwüstung sei ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Und es geschehe, wenn du das Lesen dieses Buches vollendet hast, so binde einen Stein daran und wirf es mitten in den Phrath,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'Und sprich: Also sinke unter, Babel, und stehe nicht mehr auf vor dem Bösen, das ich bringe über sie, und sie ermatten. Soweit die Reden Jirmejahus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Einundzwanzig Jahre alt war Zidkijahu, da er König ward, und regierte elf Jahre zu Jerusalem. Und der Name seiner Mutter war Chamutal, eine Tochter Jirmejahus aus Libnah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'Und er tat, was böse war in Jehovahs Augen, nach allem, was Jehojakim getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Denn nach dem Zorn Jehovahs über Jerusalem und Jehudah geschah es, daß Er sie verwarf vor Seinem Angesicht, und Zidkijahu empörte sich wider den König Babels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Und es geschah im neunten Jahr seiner Regierung, im zehnten Monat, am zehnten des Monats, daß Nebuchadrezzar, Babels König, kam, er und all seine Streitmacht, wider Jerusalem und sie lagerten sich wider sie und bauten ein Bollwerk dawider ringsumher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'Und die Stadt kam in Belagerung bis in das elfte Jahr des Königs Zidkijahu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Und im vierten Monat, am neunten des Monats, war die Hungersnot in der Stadt stark geworden, und es war kein Brot mehr da für das Volk des Landes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Und die Stadt ward erbrochen und all die Männer des Streites entwichen, und zogen bei Nacht zur Stadt hinaus auf dem Weg zum Tor zwischen der Doppelmauer bei dem Garten des Königs. Und die Chaldäer waren wider die Stadt ringsumher, und sie gingen den Weg nach dem Blachfelde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Und die Streitmacht der Chaldäer setzte hinter dem König nach, und sie erreichten Zidkijahu auf dem Blachfeld Jerichos, und alle seine Streitmacht zerstreute sich von ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'Und sie erfaßten den König und brachten ihn hinauf zum König von Babel nach Riblah im Lande Chamath, und er redete mit ihm in Gerichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'Und Babels König schlachtete die Söhne Zidkijahus vor seinen Augen. Und auch alle Obersten Jehudahs schlachtete er in Riblah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Und blendete die Augen Zidkijahus und band ihn mit zwei Erzfesseln, und der König Babels brachte ihn nach Babel und gab ihn in das Strafhaus bis an den Tag seines Todes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Und im fünften Monat am zehnten des Monats, das Jahr war das neunzehnte Jahr Nebuchadrezzars, des Königs von Babel, kam Nebusaradan, der Hauptmann der Leibwachen, der vor dem König zu Babel stand, nach Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'Und verbrannte das Haus Jehovahs und des Königs Haus und alle Häuser Jerusalems; und jedes große Haus verbrannte er mit Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'Und alle Mauern Jerusalems ringsumher riß die ganze Streitmacht, die mit dem Hauptmann der Leibwachen war, ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'Und von den Armen des Volkes und das übrige Volk, das in der Stadt verblieben war, und die Abgefallenen, die zum König von Babel abgefallen waren, und die übrigen Werkleute führte Nebusaradan, der Hauptmann der Leibwachen, weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Und von den Armen des Landes ließ Nebusaradan, der Hauptmann der Leibwachen, verbleiben zu Weingärtnern und Feldarbeitern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'Und die Säulen von Erz am Haus Jehovahs und die Gestelle und das Meer von Erz, das im Haus Jehovahs war, zerbrachen die Chaldäer und brachten alles Erz davon nach Babel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Und die Töpfe und Schaufeln und Messer, und die Sprengbecken und die Pfannen und alle Gefäße von Erz, womit man den Dienst tat, nahmen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Und die Becken und Rauchpfannen und Sprengschalen und die Töpfe und die Leuchter und die Pfannen und die Kannen von den goldenen, was Gold, und von den silbernen, was Silber war, nahm der Hauptmann der Leibwachen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Die zwei Säulen, das eine Meer und die zwölf Rinder von Erz, die unter den Gestellen waren, die König Salomoh für das Haus Jehovahs gemacht hatte, - es war das Erz von all diesen Geräten nicht zu wägen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Und die Säulen - achtzehn Ellen war die Höhe der einen Säule, und ein Faden von zwölf Ellen umgab sie, und ihre Dicke war vier Finger. Sie war hohl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'Und ein Knauf darauf von Erz, und die Höhe des einen Knaufs war fünf Ellen, und ein Flechtwerk und Granatäpfel ringsum auf dem Knauf, alles von Erz, und desgleichen an der zweiten Säule und die Granatäpfel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'Es waren aber der Granatäpfel sechsundneunzig nach dem Winde zu; aller Granatäpfel ringsum an dem Flechtwerk waren es hundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'Und der Hauptmann der Leibwachen, nahm Serajah, den Oberpriester und Zephanjah, den zweiten Priester, und die drei Hüter der Schwelle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'Und aus der Stadt nahm er einen Verschnittenen, der über die Männer des Streites bestellt war, und sieben Männer von denen, die das Angesicht des Königs sahen, die in der Stadt gefunden wurden, und den Schreiber des Obersten des Heeres, der das Volk des Landes für das Heer eintrug, und sechzig Männer von dem Volk des Landes, die inmitten der Stadt gefunden wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'Und Nebusaradan, der Hauptmann der Leibwachen, nahm sie und ließ sie zum König von Babel nach Riblah gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'Und Babels König schlug sie und tötete sie in Riblah im Lande Hamath, und Jehudah wurde von seinem Boden weggeführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'Dies ist das Volk, das Nebuchadrezzar im siebenten Jahre weggeführt, dreitausend- dreiundzwanzig Juden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'Im achtzehnten Jahre Nebuchadrezzars aus Jerusalem achthundertzweiunddreißig Seelen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'Im dreiundzwanzigsten Jahr Nebuchadrezzars führte Nebusaradan, der Hauptmann der Leibwachen, Juden, siebenhundertfünfundvierzig Seelen, im ganzen viertausendsechshundert Seelen weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Und es geschah im siebenunddreißigsten Jahre der Wegführung Jehojachins, des Königs von Jehudah, im zwölften Monat am fünfundzwanzigsten des Monats, daß Evil-Merodach, König von Babel, im Jahre, da er König ward, das Haupt Jehojachins, des Königs von Jehudah, erhob, und ihn aus dem Haus des Kerkers herausbrachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'Und er redete Gutes mit ihm und setzte seinen Thron über die Throne der Könige, die bei ihm in Babel waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'Und er veränderte die Kleider seines Kerkers und er aß beständig das Brot vor ihm alle Tage seines Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Und sein Unterhalt, ein beständiger Unterhalt ward ihm vom König von Babel Tag für Tag gegeben, bis zum Tage seines Todes, alle Tage seines Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Wie sitzet so einsam die Stadt! wo viel Volkes war, wie eine Witwe ist sie geworden! Die Große unter den Völkerschaften, die Fürstin der Landschaften, ist zinsbar geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Weinend weint sie bei Nacht, und ihre Träne ist auf ihrer Wange; und keiner ist, der sie tröstete, von allen ihren Liebhabern; alle ihre Genossen sind ihr treulos, sind zu Feinden ihr geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Jehudah ist weggeführt ob dem Elend, und ob dem vielen Dienste, sie wohnt unter den Völkerschaften, sie findet keine Ruhe; alle, die es verfolgen, erreichen sie in den Bedrängnissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Die Wege Zijons trauern, daß niemand kommt zur Festzeit. Alle ihre Tore sind verwüstet, ihre Priester seufzen, ihre Jungfrauen grämen sich, und sie - ihr ist es bitter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Ihre Dränger sind worden zum Haupt, ihre Feinde sind im Behagen, weil Jehovah sie grämen läßt ob der Menge ihrer Übertretungen. Ihre Kindlein gehen in die Gefangenschaft vor dem Dränger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'Und fortgegangen von der Tochter Zijon ist alle ihre Ehre. Ihre Obersten sind wie Hirsche, die keine Weide finden, und sie gehen hin, ohne Kraft vor dem Verfolger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'Jerusalem gedenkt in den Tagen ihres Elends und ihrer Trübsal all ihrer Annehmlichkeiten von der Vorzeit Tagen. Da ihr Volk ist gefallen in die Hand des Drängers und ihr niemand beisteht, sehen es die Dränger und lachen über ihr Feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Jerusalem hat gesündigt; darum ist sie zur Befleckung geworden. Alle die, so sie verherrlicht, miß-achten sie; denn ihre Blöße haben sie gesehen; auch seufzt sie und hat sich zurückgewendet rückwärts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Ihre Unreinheit ist an ihren Säumen. Sie hat an ihre Zukunft nicht gedacht, und ist wunderbarlich herabgekommen. Niemand tröstet sie. Jehovah, siehe mein Elend; denn groß macht sich der Feind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Der Dränger hat seine Hand über all ihre Kleinode ausgebreitet; denn sie sah, daß Völkerschaften kamen in ihr Heiligtum, von denen Du geboten, daß sie nicht in Deine Versammlung kommen sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'All ihr Volk seufzt, sie suchen Brot, sie gaben ihre Kleinode für Speise, daß sie erquicketen ihre Seele. Siehe, Jehovah, und blicke her, wie ich mißachtet bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Ist es euch nichts, ihr alle, die ihr des Weges vorübergeht? Blicket und seht, ob ein Schmerz ist wie mein Schmerz, der mir ward angetan, womit Jehovah mich am Tage der Entbrennung Seines Zorns betrübt hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Er sandte Feuer aus der Höhe in mein Gebein und es beherrschte dasselbe. Er breitete ein Netz aus für meine Füße; Er hat mich rückwärts zurückgewandt; Er hat mich der Verwüstung hingegeben; ich sieche den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Meiner Übertretungen Joch ist festgeknüpft durch Seine Hand, sie sind verflochten über meinem Hals heraufgekommen, es hat meine Kraft zum Straucheln gebracht, der Herr hat in Hände mich gegeben, daß ich nicht aufkommen kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Alle meine Gewaltigen in meiner Mitte hat der Herr hinuntergetreten, über mich die bestimmte Zeit ausgerufen, um meine Jünglinge zu zerbrechen. Die Kelter hat der Herr getreten der Jungfrau, der Tochter Jehudahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Darob weine ich; mein Auge, mein Auge, herab rinnt Wasser; denn ferne ist von mir der Tröster, der meine Seele erquickt. Meine Söhne sind verwüstet; denn der Feind ward übermächtig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Zijon breitet ihre Hände aus, es ist für sie kein Tröster. Jehovah hat wider Jakob rings um ihn seine Dränger entboten. Jerusalem ist unter ihnen zur Befleckung geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Gerecht ist Er, Jehovah; denn ich war widerspenstig wider Seinen Mund. Hört doch, ihr Völker alle, und sehet meinen Schmerz! Meine Jungfrauen und meine Jünglinge sind gegangen in Gefangenschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Ich rief meinen Liebhabern - sie betrogen mich. Meine Priester und meine Ältesten sind verschieden in der Stadt, denn sie suchten Speise für sich, um ihre Seele zu erquicken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Siehe, Jehovah, wie mir angst ist. Mein Eingeweide wallt auf, mein Herz kehrt sich um in meinem Inneren, weil ich widerspenstig war. Draußen macht das Schwert mich kinder- los, im Haus ist es wie der Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Sie hörten, wie ich seufzte, ich habe keinen Tröster; alle meine Feinde hörten, was mir Böses geschah; sie freuen sich, daß du es getan hast. Du bringst den Tag, den Du gerufen hast, und sie werden wie ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Laß alle ihre Bosheit vor Dich kommen, und tue ihnen an, wie Du mir ob aller meiner Übertretungen hast angetan; denn viel sind meiner Seufzer, und mein Herz ist siech.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Wie hat der Herr in Seinem Zorn umwölkt die Tochter Zijons, geworfen aus den Himmeln auf die Erde Israels Schmuck, und hat nicht gedacht des Schemels Seiner Füße am Tage Seines Zorns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Verschlungen hat der Herr und nicht bemitleidet alle Wohnorte Jakobs, hat in Seinem Wüten die Festungen der Tochter Jehudahs eingerissen, zur Erde niedergebracht, das Königtum entweiht und ihre Obersten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'In der Entbrennung Seines Zornes hat Er alles Horn Israels zerhauen, hat Seine Rechte rückwärts vor dem Feind zurückgezogen, und es brennt in Jakob wie ein Feuer, eine Flamme frißt auf ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Er spannte Seinen Bogen, wie der Feind; Seine Rechte stellte sich wie ein Dränger, und würgte alles, was das Auge begehrt; im Zelte der Tochter Zijons goß Er aus wie ein Feuer Seinen Grimm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Der Herr ist wie ein Feind geworden, Er hat verschlungen Israel, verschlungen alle seine Paläste, verdorben seine Festungen und gemehrt über die Tochter Jehudahs Geächze und Ächzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'Und Er tut Gewalt an Seiner Hütte wie einem Garten; Er verdirbt Seinen Versammlungsort. Jehovah läßt in Zijon vergessen Festzeit und Sabbath, und verschmäht König und Priester im Unwillen Seines Zorns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Der Herr verwirft Seinen Altar, mißachtet Sein Heiligtum, überantwortet in die Hand des Feindes die Mauern ihrer Paläste. Sie erheben die Stimme im Hause Jehovahs wie am Tage der Festzeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Jehovah dachte die Mauer der Tochter Zijons zu verderben, Er hat Seine Richtschnur ausgespannt, zieht Seine Hand nicht zurück vom Verschlingen; und Vormauer und Mauer trauern allzumal; sie verschmachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'Versunken in die Erde sind ihre Tore. Zerstört und zerbrochen hat Er ihre Riegel, ihr König und ihre Obersten sind unter den Völkerschaften. Kein Gesetz ist da, auch ihre Propheten finden kein Gesicht von Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Die Ältesten der Tochter Zijon sitzen auf der Erde, sie sind stille, sie haben Staub auf ihr Haupt heraufgebracht, sich gegürtet mit Säcken. Die Jungfrauen Jerusalems lassen zur Erde ihr Haupt herabsinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'In Tränen verzehren sich meine Augen, meine Eingeweide wallen auf, meine Leber ist ausgeschüttet auf die Erde ob dem Bruche der Tochter meines Volkes. Kindlein und Säuglinge schmachten dahin in den Straßen der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Sie sprechen zu ihren Müttern: Wo ist Korn und Wein? Weil sie wie der Durchbohrte dahinschmachten in den Straßen der Stadt, da sie ihre Seele am Busen ihrer Mütter ausgießen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Womit soll ich bezeugen dir, womit vergleichen dich, Tochter Jerusalems? was dir ähnlich stellen, daß ich dich tröste, Jungfrau, Tochter Zijons; denn groß wie das Meer ist dein Bruch. Wer wird dich heilen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Deine Propheten schauten dir Eitles und Untaugliches, und deckten deine Missetat nicht auf, deine Gefangenschaft zurückzuwenden, und schauten dir Weissagungen des Eitlen, und Verstoßungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Die Hände schlagen über dir zusammen alle, die des Weges vorübergehen, sie zischen und schütteln ihr Haupt über die Tochter Jerusalems: Ist das die Stadt, von der sie sagten, sie sei die Vollendung der Schönheit, die Freude der ganzen Erde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Sie sperren ihren Mund auf, alle deine Feinde über dich, sie zischen und knirschen mit den Zähnen, sie sprechen: Wir haben sie verschlungen. Ja, dies ist der Tag, auf den wir hofften. Wir haben ihn gefunden, ihn gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Jehovah hat getan, was Er gesonnen; hat ausgeführt Seine Rede, die Er geboten seit der Vorzeit Tagen, riß ein und bemitleidete nicht, ließ den Feind über dir fröhlich sein, hob empor deiner Dränger Horn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Ihr Herz schreit zum Herrn: Du Mauer der Tochter Zijons, laß Tränen herabrinnen wie einem Bach Tag und Nacht, gib dir keine Unterbrechung, dein Augapfel sei nicht stille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Stehe auf, schreie auf in der Nacht beim Anfang der Nachtwachen, schütte wie Wasser aus dein Herz vor dem Angesicht des Herrn, erhebe deine Hände zu Ihm für die Seele deiner Kindlein, die am Anfang aller Gassen vor Hunger dahinschmachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Siehe, Jehovah, und blicke, wem hast Du solches angetan! Sollen die Weiber ihre Frucht essen, die Kindlein ihrer Pflege? Soll im Heiligtum des Herrn erwürgt werden Priester und Prophet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Sie liegen auf der Erde, auf den Gassen Jung und Alt; meine Jungfrauen und meine Jünglinge sind durch das Schwert gefallen. Du hast sie erwürgt am Tage Deines Zornes, sie hingeschlachtet, nicht bemitleidet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Du rufst wie am Tag der Festzeit mein Bangen ringsumher, und am Tage des Zornes Jehovahs ist kein Entkommener, noch Rest. Die, welche ich gepflegt und großgezogen, hat mein Feind alle gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Ich bin der Mann, der Elend hat gesehen unter der Rute Seines Wütens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Mich geleitete Er, und ließ mich gehen in Finsternis und nicht im Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Nur wider mich hat Er zurückgewendet, umgekehrt Seine Hand den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Mein Fleisch ließ altern Er und meine Haut, zerbrach meine Gebeine,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Er hat wider mich gebaut, umfangen mit Gift mich und mit Mühsal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'In Finsternissen ließ Er mich wohnen, wie die ewig Toten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Er hat mich eingehegt, daß ich nicht hinausgehen kann, Er hat meine Erzfesseln schwer gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Auch wenn ich schreie und laut schreie, wehret Er ab mein Gebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Mit Quadern hat Er meine Wege vermauert, meine Steige verkehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Ein Bär im Hinterhalt ist Er mir, ein Löwe im Verborgenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Er lenkt ab meine Wege, zerpflückt mich und verwüstet mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Er hat gespannt Seinen Bogen, und gestellt mich zum Ziel dem Pfeil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'In meine Nieren ließ Er hineinfahren Seiner Köcher Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'All meinem Volke bin ich zum Gelächter, zum Saitenspiel den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Mit Bitterkeiten hat Er mich gesättigt, mich in Wermut schwelgen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'Und Er läßt meine Zähne sich auf Kies zerdrücken, hat in die Asche mich hinabgedrückt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'Und verworfen vom Frieden ist meine Seele. Vergessen habe ich des Guten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'Und ich sprach: Verloren ist mein Sieg, und mein Warten auf Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Gedenke meines Elends und meiner Trübsal, des Wermuts und des Giftes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Gedenkend gedenkst du dessen und nieder beugt sich meine Seele in mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'Das führe ich mir ins Herz zurück, darum will ich warten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Jehovahs Barmherzigkeit ist, daß wir nicht ganz aus sind, und Seine Erbarmungen nicht alle sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'Neu sind sie an den Morgen, viel ist Deiner Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Jehovah ist mein Teil, spricht meine Seele, darum warte ich auf Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Gut ist Jehovah denen, die auf Ihn hoffen, der Seele, die nach Ihm fragt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Gut ist es, daß man warte und stille sei auf Jehovahs Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Gut ist es dem Manne, daß in seiner Jugend er das Joch trage;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Daß er allein sitzt und stille sei, wenn man es ihm auferlegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'Daß seinen Mund er in den Staub stecke, ob vielleicht noch Hoffnung sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Und dem, der ihn schlägt, die Wange biete, sich sättige mit Schmach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Denn nicht ewiglich verwirft der Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'Denn wenn Er hat betrübt, so erbarmt Er Sich nach Seiner großen Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Denn nicht von Seinem Herzen aus bedrückt Er und bereitet Gram den Söhnen des Mannes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Daß Er zerstoße unter Seinen Füßen alle Gebundenen des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'Daß eines Mannes Recht Er vor dem Angesicht des Höchsten beugen ließe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'Daß man den Menschen in seinem Rechtshandel verkehrt mache, das sieht der Herr nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Wer ist es, der spricht und es geschieht, das der Herr nicht geboten hätte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Geht aus dem Mund des Höchsten nicht hervor das Böse und das Gute?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Was beklagt sich der Mensch, der lebt, der Mann ob seinen Sünden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Laßt unsere Wege uns erforschen und ergründen, und zu Jehovah zurückkehren!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Erheben wir unser Herz samt den Händen zu Gott in den Himmeln!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Wir waren abgefallen und widerspenstig, Du hast nicht vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Du hast Dich bedeckt im Zorn und hast uns nachgesetzt, uns erwürgt, hast kein Mitleid gehabt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Du hast Dich mit einer Wolke bedeckt, daß das Gebet nicht durchkommen konnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Zum Kehricht und zur Verschmähung hast du uns gesetzt inmitten der Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Alle unsere Feinde sperren ihren Mund auf wider uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Schauer und Fallgrube ward uns, Unwetter und Zerbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Bächlein von Wasser rinnt mein Auge herab über das Zerbrechen der Tochter meines Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Mein Auge ergießt sich und ist nicht stille, ohne Unterlaß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'Bis daß Jehovah schaut und sieht vom Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Mein Auge tut es meiner Seele an ob allen Töchtern meiner Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Sie jagen mich, wie einen Vogel, sie, die mich umsonst anfeinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'Sie vertilgen mein Leben in der Grube und werfen einen Stein auf mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Wasser überströmen mein Haupt; ich sprach: Ich bin abgeschnitten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Ich rief Deinen Namen an, Jehovah, aus der untersten Grube;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Du hörtest meine Stimme: Verbirg doch nicht Dein Ohr vor meinem Hauche, meinem Angstschrei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Du nahst dich am Tage, da ich zu Dir rufe, Du sprichst: Fürchte dich nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Du haderst, Herr, meiner Seele Hader, und Du erlöst mein Leben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Du siehst, Jehovah, wie man mir Unrecht tut. Richte Du mein Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Du siehst alle ihre Rache, alle ihre Gedanken wider mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Du hörst, Jehovah, ihr Schmähen, alle ihre Gedanken wider mich,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'Die Lippen meiner Widersacher und ihr Sinnen wider mich den ganzen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Sitzen sie oder stehen sie auf, blicke her, bin ich ihr Lied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Gib ihnen zurück, Jehovah, Vergeltung nach ihrer Hände Werk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Gib ihnen Verblendung des Herzens, und auf sie Deinen Fluch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Setze ihnen nach im Zorn und vernichte sie unter Jehovahs Himmeln!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Wie ist das Gold verdunkelt, das gute, lautere Gold verändert, wie sind die Steine des Heiligtums an aller Gassen Anfang hingeschüttet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Die köstlichen Söhne Zijons, mit feinem Golde aufgewogen, wie werden sie wie irdene Krüge, das Werk der Hände des Töpfers, geachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Selbst die Walfische reichen ihre Brust, sie säugen ihre Jungen; meines Volkes Tochter ist grausam geworden, wie Käuzlein in der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Die Zunge des Säuglings klebt vor Durst an seinem Gaumen. Die Kindlein fragen nach Brot, doch niemand reicht es ihnen dar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Die Leckerbissen aßen, werden auf den Gassen verwüstet, und die in Scharlach auferzogen wurden, umarmen Kothaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'Die Missetat der Tochter meines Volkes ist größer geworden denn die Sünde Sodoms, das wie im Augenblick ward umgekehrt, und keine Hände gestalteten es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Lauterer waren ihre Nasiräer denn Schnee, hellglänzender denn Milch, röter an Gebein denn Edelsteine, ihre Glätte wie Saphir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Finsterer denn Schwärze ist jetzt ihre Gestalt. Man erkennt sie auf den Gassen nicht, ihre Haut hängt fest an ihrem Gebein, verdorrt war es wie Holz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Besser daran waren die durch das Schwert Erschlagenen, denn die vom Hunger erschlagen, die dahinsinken durchbohrt wegen dem Ertrag des Feldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Die Hände erbarmungsvoller Weiber kochen ihre Kinder, zur Nahrung sind sie ihnen bei dem Bruch der Tochter meines Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Vollendet hat Jehovah Seinen Grimm, und die Entbrennung Seines Zorns ausgeschüttet und in Zijon entzündet ein Feuer, das ihre Grundfesten auffraß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Die Könige der Erde und alle, so in der Welt wohnen, glaubten nicht, daß ein Dränger und Feind werde eingehen in die Tore Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Ob der Sünden ihrer Propheten, der Missetaten ihrer Priester, die in ihrer Mitte der Gerechten Blut vergossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Blind wanderten in den Gassen sie umher, waren mit Blut befleckt, daß man ihren Anzug nicht zu berühren vermochte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, 'Weichet! Ein Unreiner! riefen sie vor ihnen. Weichet, weichet! Rühret nicht an! Wenn sie davongeflohen und fortgewandert sind, sagt man unter den Völkerschaften: Sie sollen nicht länger da sich aufhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Jehovahs Angesicht hat sie zerteilt. Nicht länger blickt Er sie an. Das Angesicht der Priester erhoben sie nicht und zeigten keine Gnade den Ältesten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Noch waren wir - unsere Augen vergingen wegen unserer nichtigen Hilfe. Wir spähten auf unserer Warte nach einer Völkerschaft, die nicht rettete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Sie machten Jagd auf unsere Schritte, daß wir nicht in unseren Straßen gingen. Unser Ende war genaht, unsere Tage voll; denn unser Ende war gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Schneller waren unsere Verfolger als des Himmels Adler. Auf den Bergen jagten sie uns nach, lagen im Hinterhalt auf uns in der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Der Hauch unsrer Nase, der Gesalbte des Jehovah, ist in ihren Gruben gefangen, von Dem wir sagten: In Seinem Schatten wollen wir unter den Völkerschaften leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Freue dich und sei fröhlich, du Tochter Edoms, die du wohnst im Lande Uz. An dich auch kommt der Becher herüber. Du wirst dich berauschen und entblößen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Deine Missetat, Tochter Zijon, ist vollendet. Er läßt dich nicht mehr wegführen. Deine Missetat, Tochter Edoms, sucht Er heim, hat deine Sünden aufgedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Gedenke, Jehovah, wie es mit uns war, blicke und siehe unsere Schmach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Unser Erbe ist Fremden zugewendet, unsere Häuser den Ausländern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Waisen sind wir und ohne Vater, unsere Mütter sind wie Witwen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Für Silber trinken wir unser Wasser. Um einen Kaufpreis kommt uns unser Holz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Auf unseren Nacken wird uns nachgesetzt, wir werden ermüdet, man läßt uns keine Ruhe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Ägypten gaben wir die Hand, Aschur, um Brotes satt zu werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Gesündigt haben unsere Väter und sind nicht mehr, ihre Missetaten sind uns aufgebürdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Über uns herrschen Knechte. Niemand reißt uns los aus ihrer Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Mit unserer Seele holen wir unser Brot herein vor dem Schwert der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Unsere Haut wird erhitzt wie der Ofen von des Hungers Gluten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Sie haben Weiber in Zijon geschwächt, Jungfrauen in Jehudahs Städten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Oberste wurden von ihrer Hand gehenkt, der Alten Angesichte wurden nicht geehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Jünglinge nahmen sie zur Mühle fort und Junge strauchelten unter dem Holze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Die Ältesten haben vom Tore aufgehört, die Jünglinge vom Saitenspiel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Unseres Herzens Freude feiert, in Trauer ist der Reigentanz verwandelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Gefallen ist die Krone unseres Hauptes. Wehe uns nun, daß wir gesündigt haben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Darum siecht unser Herz. Darum sind unsere Augen finster geworden');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'Ob dem Berg Zijon, der so wüste liegt, daß Füchse darüber gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Du, Jehovah, bleibst ewiglich, Dein Thron zu Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Warum hast Du für immerdar uns vergessen, für der Tage Länge uns verlassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Bringe uns zu Dir zurück, Jehovah, und wir kehren zurück. Erneuere unsere Tage, wie vor Zeiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Denn solltest Du uns gänzlich verschmäht haben, so gar sehr über uns entrüstet sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'Und es geschah im dreißigsten Jahr im vierten, am fünften des Monats, da ich inmitten der Weggeführten am Flusse Chebar war, daß die Himmel sich öffneten, und ich sah Gesichte Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Am fünften des Monats - es war das fünfte Jahr der Wegführung des Königs Jojachin, -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'Geschah das Wort Jehovahs an Jecheskel, den Sohn Busis, den Priester, im Lande der Chaldäer am Flusse Chebar, und es war allda die Hand Jehovahs auf ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'Und ich sah, und siehe, der Wind eines Wetters kam von Mitternacht, eine große Wolke, und ein wirbelndes Feuer, und ein Glanz dabei ringsumher, und aus seiner Mitte wie der Anblick der Glühkohle aus des Feuers Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'Und inmitten ihrer war die Ähnlichkeit von vier Tieren, und ihr Aussehen war: Sie hatten die Ähnlichkeit eines Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'Und vier Gesichter hatte eines, und vier Flügel ein jedes von ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Und ihre Füße waren ein gerader Fuß, und ihrer Füße Sohle wie die Fußsohle eines Kalbes und schimmernd wie der Anblick von geglättetem Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'Und Menschenhände waren unter ihren Flügeln, bei ihren vier Richtungen, und ihrer Angesichter und ihrer Flügel waren je vier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Aneinander zusammengefügt waren ihre Flügel, und sie wandten sich nicht um bei ihrem Gehen; sie gingen, jeder Mann stracks vor seinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'Und die Ähnlichkeit ihrer Angesichter war eines Menschen Angesicht, und eines Löwen Angesicht zur Rechten der vier und das Angesicht eines Ochsen zur Linken der vier, und das Angesicht eines Adlers für die vier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Und ihre Angesichter und ihre Flügel waren oben getrennt, jeder Mann hatte zwei zusammengefügte, jeder Mann zwei, die ihre Leiber bedeckten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'Und sie gingen, jeder Mann stracks vor seinem Angesicht; wohin der Geist war zu gehen, gingen sie, sie wandten sich nicht um bei ihrem Gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'Und die Ähnlichkeit der Tiere war wie brennende Kohlen des Feuers anzusehen, wie Fackeln anzusehen ging es zwischen den Tieren dahin, und einen Glanz hatte das Feuer, und aus dem Feuer ging Blitz hervor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'Und die Tiere liefen und kehrten zurück, wie der Blitz anzusehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Und ich sah die Tiere, und siehe, ein Rad war auf der Erde neben den Tieren, bei ihren vier Gesichtern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Die Räder und ihr Werk waren anzusehen wie der Anblick des Tharschischsteins, und eine Ähnlichkeit hatten alle vier. Und ihr Aussehen und ihr Werk waren, als ob ein Rad inmitten des Rades wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Nach ihren vier Richtungen gingen sie bei ihrem Gehen; sie wandten sich nicht um bei ihrem Gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Und sie hatten ihre Felgen und ihre Höhe und waren furchtbar; und ihre Felgen voller Augen rings um die vier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'Und beim Gehen der Tiere, gingen die Räder neben ihnen; und wenn die Tiere sich erhoben von der Erde, erhoben sich die Räder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Wohin der Geist war zu gehen, gingen sie, dahin war der Geist zu gehen. Und die Räder hoben sich samt ihnen; denn der Geist des Tieres war in den Rädern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Wenn sie gingen, gingen sie; und wenn sie standen, standen sie; und wenn sie sich erhoben von der Erde, erhoben sich samt ihnen die Räder, denn der Geist des Tieres war in den Rädern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'Und über den Häuptern des Tieres die Ähnlichkeit einer Ausbreitung, wie der Anblick von Kristall, furchtbar, ausgespannt oben über ihren Häuptern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'Und unter der Ausbreitung waren ihre Flügel gerade gegeneinander. Jeder Mann hatte zwei, die hier bedeckten, und jeder Mann zwei, die dort bedeckten ihre Leiber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'Und ich hörte die Stimme ihrer Flügel, wie die Stimme vieler Wasser, wie die Stimme des Schaddai. Bei ihrem Gehen war die Stimme des Brausens wie die Stimme des Heerlagers. Bei ihrem Stehen ließen sie ihre Flügel sinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'Und eine Stimme geschah über der Ausbreitung, die über ihrem Haupte war. Bei ihrem Stehen ließen sie ihre Flügel sinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'Und oben über der Ausbreitung, die war über ihrem Haupte, wie das Aussehen eines Saphirsteines, die Ähnlichkeit eines Thrones, und auf der Ähnlichkeit des Thrones war eine Ähnlichkeit anzusehen wie ein Mensch oben darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'Und ich sah wie den Anblick der Glühkohle, wie das Aussehen eines Feuers innerhalb desselben ringsum; vom Aussehen seiner Lenden und aufwärts, und vom Aussehen seiner Lenden unterwärts sah ich wie das Aussehen von Feuer, und hatte Glanz ringsumher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Wie das Aussehen des Bogens, der in der Wolke ist am Tag des Platzregens, so war anzusehen der Glanz ringsumher. Es war das Aussehen der Ähnlichkeit der Herrlichkeit Jehovahs. Und ich sah und fiel auf mein Angesicht und hörte die Stimme Eines, Der redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'Und Er sprach zu mir: Menschensohn, stehe auf deine Füße, und Ich will mit dir reden:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'Und es kam ein Geist in mich, wie Er zu mir redete, und ließ mich auf meine Füße stehen, und ich hörte Den, Der zu mir redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'Und Er sprach zu mir: Menschensohn, Ich sende dich zu den Söhnen Israels, zu einer empörerischen Völkerschaft, die sich wider Mich empörte; sie und ihre Väter sind von Mir abgefallen bis auf diesen selbigen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'Und die Söhne sind harten Angesichts und bestärkten Herzens; zu ihnen sende Ich dich, und zu denselben sollst du sprechen: Also spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Und sie, ob sie darauf hören oder es unterlassen, denn sie sind ein widerspenstig Haus, aber sie sollen wissen, daß ein Prophet in ihrer Mitte ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Du aber, Menschensohn, sollst dich nicht fürchten vor ihnen, und vor ihren Worten sollst du dich nicht fürchten; zwar sind sie Aufwiegler und Dornen bei dir, und bei Skorpionen wohnst du. Vor ihren Worten sollst du dich nicht fürchten, und vor ihrem Angesicht nicht entsetzen, obwohl sie sind ein widerspenstig Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'Und Meine Worte sollst du zu ihnen reden, ob sie darauf hören oder es unterlassen; denn widerspenstig sind sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Du aber, Menschensohn, höre, was Ich zu dir rede. Sei du nicht widerspenstig, wie das widerspenstige Haus, sperre deinen Mund auf und iß, was Ich dir gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'Und ich sah, und siehe, eine Hand war gegen mich ausgestreckt, und siehe, die Rolle eines Buches war darin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'Und Er breitete sie vor mir aus, und sie war inwendig und auf der Rückseite geschrieben, und geschrieben waren darauf Klagelieder, Seufzer und Weh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'Und Er sprach zu mir: Menschensohn, iß, was du findest, iß diese Rolle und gehe, rede zu dem Hause Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'Und ich öffnete meinen Mund, und Er ließ mich essen diese Rolle,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'Und Er sprach zu mir: Menschensohn, laß essen deinen Bauch und fülle deine Eingeweide mit dieser Rolle, die Ich dir gebe. Und ich aß, und sie war in meinem Mund wie Honig an Süße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Und Er sprach zu mir: Menschensohn, gehe hin, komme zu dem Hause Israels und rede zu ihm mit Meinen Worten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Denn nicht zu einem Volk von tiefer Lippe und von schwerer Zunge bist du gesandt; zum Hause Israels,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'Nicht zu vielen Völkern von tiefer Lippe und von schwerer Zunge, deren Worte du nicht hörst. Würden sie nicht, wenn Ich zu ihnen dich sendete, auf dich hören?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Aber das Haus Israels ist nicht willens, auf dich zu hören, denn sie sind nicht willens auf Mich zu hören, weil das ganze Haus Israels von bestärkter Stirne und von hartem Herzen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Siehe, Ich mache dein Angesicht stark ihrem Angesicht entgegen, und deine Stirne stark entgegen ihrer Stirne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'Wie den Diamant, stärker denn der Fels, mache Ich deine Stirne. Fürchte dich nicht und entsetze dich nicht vor ihnen, daß sie ein widerspenstig Haus sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Und Er sprach zu mir: Menschensohn, alle Meine Worte, die Ich zu dir rede, nimm zu deinem Herzen und höre sie mit deinen Ohren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Und gehe hin, komme zu den Weggeführten, zu den Söhnen deines Volkes und rede zu ihnen und sprich zu ihnen: Also spricht der Herr Jehovah; ob sie es hören, oder ob sie es unterlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Und der Geist erhob mich, und ich hörte hinter mir die Stimme eines großen Erdbebens: Gesegnet sei die Herrlichkeit Jehovahs von Seinem Orte aus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'Und die Stimme der Flügel, der Tiere, die einander küß-ten, und die Stimme der Räder samt ihnen und eines großen Erdbebens Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'Und der Geist erhob mich und nahm mich, und bitter im Grimm meines Geistes ging ich; und die Hand Jehovahs war stark über mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'Und ich kam zu den Weggeführten gen Tel Abib, zu denen, die sitzen am Flusse Chebar, und betrachtete sie allda sitzen, und saß da sieben Tage erstaunt in ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'Und es geschah am Ende der sieben Tage, daß Jehovahs Wort an mich geschah, und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Menschensohn, zum Wächter habe Ich dich gegeben für das Haus Israel, und hören sollst du aus Meinem Mund ein Wort, und sie von Mir warnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Wenn Ich zu den Ungerechten spreche: Du sollst des Todes sterben, und du warnst ihn nicht und redest nicht, den Ungerechten zu warnen vor seinem ungerechten Weg, um ihn am Leben zu erhalten, so stirbt er, der Ungerechte, in seiner Missetat, aber Ich fordere sein Blut von deiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Und so du den Ungerechten gewarnt hast, und er nicht zurückkehrt von seiner Ungerechtigkeit und von seinem ungerechten Wege, so wird er sterben in seiner Missetat, und du hast deine Seele errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'Und wenn sich ein Gerechter zurückwendet von seiner Gerechtigkeit und Verkehrtes tut, und Ich einen Anstoß vor ihn tue, daß er stirbt; so du ihn nicht verwarnt hast ob seiner Sünde, so stirbt er, und nicht gedacht wird seiner Gerechtigkeit, die er getan, aber Ich fordere sein Blut von deiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Und so du den Gerechten hast gewarnt, daß der Gerechte nicht sündige, und er nicht sündigt, soll er leben, weil er sich hat warnen lassen; und du hast deine Seele errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'Und allda war die Hand Jehovahs über mir, und Er sprach zu mir: Stehe auf und gehe in den Talgrund hinaus, und dort werde Ich zu dir reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Und ich stand auf und ging hinaus in den Talgrund, und siehe, allda stand die Herrlichkeit Jehovahs, wie die Herrlichkeit, die ich am Flusse Chebar sah, und ich fiel auf mein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'Und in mich kam der Geist und ließ mich auf meine Füße stehen, und Er redete mit mir und sprach zu mir: Gehe hinein und schließe dich ein in deines Hauses Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'Und du, Menschensohn, siehe, man legt dir Stricke an und bindet dich damit, daß du nicht mitten unter sie ausgehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'Und deine Zunge will Ich an deinem Gaumen kleben lassen, daß du verstummen sollst und nicht mehr für sie ein Mann der Rüge sein mögest; denn ein widerspenstig Haus sind sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Und wenn Ich mit dir rede, will Ich deinen Mund öffnen, daß du zu ihnen sprechest: Also spricht der Herr Jehovah: Der, so es höret, höre es, und der es unterläßt, unterlasse es, weil sie sind ein widerspenstig Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Und du, Menschensohn, nimm dir einen Ziegelstein und lege ihn vor dich hin und zeichne die Stadt Jerusalem darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'Und gib wider sie eine Belagerung, und baue ein Bollwerk wider sie, und schütte einen Wall auf wider sie und gib wider sie Heerlager, und setze rings um sie Sturmböcke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'Du aber nimm dir eine eiserne Pfanne und gib sie als eiserne Wand zwischen dich und die Stadt und richte dein Gesicht wider sie, und sie sei in Belagerung, und du sollst sie belagern. Ein Zeichen sei es dem Hause Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Und du sollst auf deine linke Seite liegen, und lege darauf die Missetat des Hauses Israel. Die Zahl der Tage, die du darauf liegst, sollst ihre Missetat du tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Ich aber gebe dir die Jahre ihrer Missetat zur Zahl der Tage: dreihundertneunzig Tage, daß du die Missetat des Hauses Israel sollst tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'Und hast du solches vollendet, sollst du ein zweites Mal auf deiner rechten Seite liegen und die Missetat des Hauses Jehudah tragen vierzig Tage, einen Tag auf das Jahr, einen Tag auf das Jahr gebe Ich dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'Und auf Jerusalems Belagerung richte dein Angesicht und deinen entblößten Arm und weissage wider sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'Und siehe, Ich lege dir Stricke an, daß du dich nicht von deiner einen Seite auf deine andere Seite kehren kannst, bis du die Tage deiner Belagerung hast vollendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Und du, nimm du dir Weizen und Gerste und Bohnen und Linsen und Hirse und Spelt, und tue sie in ein Gefäß und mache dir davon Brot nach der Zahl der Tage, die du auf deiner Seite liegst, dreihundertneunzig Tage sollst du es essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'Und deine Speise, die du essen sollst nach dem Gewicht, sei zwanzig Schekel auf den Tag, von Zeit zu Zeit sollst du sie essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Und Wasser sollst du trinken nach dem Maß, ein sechstel Hin. Von Zeit zu Zeit sollst du es trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'Und sollst als Gerstenkuchen es essen; mit Kot, dem Auswurf von Menschen sollst du Kuchen machen vor ihren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'Und Jehovah sprach: Also werden die Söhne Israels ihr unrein Brot essen unter den Völkerschaften, wohin Ich sie verstoßen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Und ich sprach: Ach, Herr Jehovah, siehe, meine Seele ist nicht verunreinigt, und Aas und Zerfleischtes habe ich nicht gegessen von meiner Jugend bis jetzt, und ist kein abscheuliches Fleisch in meinen Mund gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Und Er sprach zu mir: Siehe, Ich gebe dir Rinderdung statt Menschenkot, damit du dein Brot damit machst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Und Er sprach zu mir: Menschensohn, siehe, Ich breche den Stab des Brotes in Jerusalem, und sie sollen Brot essen nach dem Gewichte und mit Sorgen, und Wasser trinken nach dem Maß und mit Erstaunen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'Weil sie des Brotes und des Wassers mangeln, und sich erstaunen werden, der Mann und sein Bruder und abzehren ob ihrer Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Und du, Menschensohn, nimm dir ein scharfes Schwert; ein Schermesser der Bartscherer sollst du dir nehmen und lasse es über dein Haupt und über deinen Bart hinfahren, und nimm dir Waagen des Gewichts und teile sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Ein Drittel sollst du im Feuer verbrennen inmitten der Stadt, wenn die Tage der Belagerung erfüllt sind, und nehmen sollst du ein Drittel und mit dem Schwerte schlagen ringsumher und ein Drittel zersprengen in den Wind, und hinter ihnen her will Ich das Schwert ausziehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'Und nimm von da ein wenig an der Zahl und binde sie zusammen an deine Fittiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Und nimm noch von ihnen und wirf sie in des Feuers Mitte und verbrenne sie im Feuer; von ihnen wird ein Feuer ausgehen über das ganze Haus Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'So spricht der Herr Jehovah: Dieses Jerusalem, inmitten der Völkerschaften setzte Ich es, und Lande rings um sie her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'Sie aber wandelten Meine Rechte in Ungerechtigkeit mehr als die Völkerschaften, und Meine Satzungen mehr als die Lande, die rings um sie her sind; denn sie verschmähten Meine Rechte und Meine Satzungen, sie wandelten nicht darin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Darum, so spricht der Herr Jehovah, weil ihr mehr tobet denn die Völkerschaften, die um euch her sind, in Meinen Satzungen nicht wandeltet und Meine Rechte nicht tatet, und nicht nach den Rechten der Völkerschaften, die um euch her sind, tatet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'Darum spricht also der Herr Jehovah: Siehe, so bin auch Ich wider dich, und tue Gerichte in deiner Mitte vor den Augen der Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'Und tue in dir, was Ich nicht getan, und desgleichen Ich nicht mehr tun werde ob aller deiner Greuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Darum sollen Väter die Söhne essen inmitten deiner, und Söhne ihre Väter essen, und Gerichte werde Ich tun in dir und nach allen Winden zersprengen all deinen Überrest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Darum, bei Meinem Leben, ist der Spruch des Herrn Jehovahs, weil du Mein Heiligtum verunreinigtest mit allen deinen Scheusalen und allen deinen Greueln, so werde auch Ich dich verringern und Mein Auge wird nicht schonen, und auch Ich werde nicht Mitleid haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Ein Drittel von dir wird sterben an der Pest und vor Hunger in deiner Mitte alle werden, und ein Drittel fallen durch das Schwert rings um dich her, und ein Drittel werde Ich zersprengen nach allen Winden, und das Schwert ausziehen hinter ihnen her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Aber Mein Zorn soll vollendet werden, und Mein Grimm wider sie zur Ruhe kommen, daß es Mich gereut, und wissen sollen sie, daß Ich, Jehovah, in Meinem Eifer geredet hatte, da Mein Grimm wider sie vollendet ward;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'Und Ich werde dich dahingeben zur Öde und zur Schmach unter den Völkerschaften rings um dich her, und vor den Augen eines jeden, der vorübergeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'Und du wirst zur Schmach und Verhöhnung, zur Züchtigung und zum Erstaunen werden den Völkerschaften rings um dich her, da Ich an dir Gerichte tue in Zorn und in Grimm und in Strafen des Grimms; Ich, Jehovah, habe es geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Wenn Ich des Hungers böse Pfeile unter sie sende, die sein sollen zum Verderben, die Ich senden werde, euch zu verderben; und den Hunger werde Ich dazutun wider euch, und euch den Stab des Brotes brechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'Und den Hunger und das böse wilde Tier sende Ich wider euch, daß sie dich machen kinderlos. Und Pest und Blut soll in dir durchziehen. Und das Schwert bringe Ich über dich. Ich, Jehovah, habe es geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'Und Jehovahs Wort geschah an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Menschensohn, richte dein Angesicht gegen die Berge Israels und weissage wider sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'Und sprich: Ihr, Berge Israels, höret das Wort des Herrn Jehovahs. So spricht der Herr Jehovah zu den Bergen und zu den Hügeln, zu den Flußbetten und zu den Schluchten: Siehe, Ich bringe über euch das Schwert und zerstöre eure Opferhöhen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'Und verwüstet werden eure Altäre und zerbrochen eure Sonnensäulen, und eure Erschlagenen lasse Ich fallen vor eure Götzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'Und die Leichen der Söhne Israels gebe Ich hin vor eure Götzen und zersprenge euer Gebein rings um eure Altäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'In allen euren Wohnsitzen sollen die Städte verödet und die Opferhöhen verwüstet sein, auf daß verödet und verwüstet seien eure Altäre, und zerbrochen seien und feiern eure Götzen, und niedergehauen eure Sonnensäulen, und euer Machwerk ausgewischt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'Und fallen soll der Erschlagene in eurer Mitte, und ihr sollt wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Und Ich will übriglassen, so daß seien für euch Entkommene in den Völkerschaften, wenn ihr zersprengt seid in den Ländern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'Und eure Entkommenen werden Mein gedenken unter den Völkerschaften, wohin sie gefangen geführt werden, wenn Ich gebrochen ihr buhlerisches Herz, das von Mir gewichen, und ihre Augen, die ihren Götzen nachgebuhlt, und sie ob ihnen verdrossen werden, wegen der Bosheiten, die sie getan ob aller ihrer Greuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Und sollen wissen, daß Ich, Jehovah, nicht umsonst geredet habe, daß Ich all dieses Böse an ihnen tun werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'So spricht der Herr Jehovah: Schlage in deine Hände und stampfe mit deinem Fuß und sprich: Ach! über all die bösen Greuel des Hauses Israels, darum sie durch das Schwert, durch Hunger und durch Pest fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Wer ferne ist, stirbt an der Pest, und der Nahe fällt durch das Schwert, wer aber verbleibt und bewahrt wird, der wird Hungers sterben. Und Ich vollende Meinen Grimm an ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'Daß ihr wisset, daß Ich Jehovah bin, wenn ihre Erschlagenen liegen in ihrer Götzen Mitte rings um ihre Altäre her, auf jedem erhabenen Hügel, auf allen Häuptern der Berge, und unter jedem belaubten Baum und unter jeder dichtverzweigten Eiche, am Orte, wo sie den Geruch der Ruhe allen ihren Götzen gaben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'Und Ich strecke Meine Hand aus wider sie, und mache das Land zur Verwüstung und Wüstenei, von der Wüste bis nach Diblath an allen ihren Wohnsitzen, und sie sollen wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Und es geschah das Wort Jehovahs an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'Und du, Menschensohn, also spricht der Herr Jehovah: Dem Boden Israels ist das Ende da! Das Ende ist gekommen über die vier Ecken des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Nun ist das Ende über dich, und Meinen Zorn entsende Ich wider dich, daß Ich nach deinen Wegen dich richte und alle deine Greuel auf dich lege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'Und Mein Auge soll deiner nicht schonen, und Ich werde dich nicht bemitleiden. Denn deine Wege bringe Ich über dich, und deine Greuel sollen in deiner Mitte sein, daß ihr wisset, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'So spricht der Herr Jehovah: Ein Übel, ein Übel, - siehe - es kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Ein Ende kommt, es kommt das Ende, es erwacht über dich, siehe, es kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Es kommt der Morgen über dich, der du im Lande wohnst. Es kommt die Zeit, nahe ist der Tag des Getümmels, und ist kein Kelterlied auf den Bergen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Jetzt aus der Nähe schütte Ich Meinen Grimm aus über dich und vollende Meinen Zorn an dir, daß Ich dich nach deinen Wegen richte, und über dich all deine Greuel gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'Und Mein Auge wird dich nicht schonen, auch werde Ich dich nicht bemitleiden. Nach deinen Wegen gebe Ich es über dich, und deine Greuel sollen in deiner Mitte sein, daß ihr wisset, daß Ich Jehovah es bin, Der schlägt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Siehe, der Tag! Siehe, er kommt! Hervor geht der Morgen. Es blüht der Stab, es sproßt die Vermessenheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'Die Gewalt macht sich auf für der Ungerechtigkeit Stab. Nichts ist von ihnen und von ihrer Menge und von ihrem Brausen da, und kein Trauerlied über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Es kommt die Zeit, der Tag reicht heran. Der Käufer soll nicht fröhlich sein, noch trauern der Verkäufer; denn Entbrennung ist über all ihrer Menge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Denn der Verkäufer kehrt nicht zum Verkauften zurück, obschon sein Leben unter den Lebendigen ist; denn das Gesicht über all seine Menge geht nicht zurück, und eines jeden Mannes Leben ist in seiner Missetat; sie stärken sich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Sie stoßen in das Lärmhorn, und alles macht bereit; aber keiner geht in den Streit; denn Mein Entbrennen ist wider all seine Menge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Das Schwert ist draußen, und Pest und Hunger innen. Wer auf dem Felde ist, der stirbt durch das Schwert, und den, so in der Stadt ist, frißt der Hunger und die Pest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'Und ihre Entkommenen entkommen und sind auf den Bergen wie die Tauben der Talschluchten; sie alle girren, jeder Mann über seine Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Schlaff werden alle Hände und aller Knie gehen zu Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'Und mit Säcken gürten sie sich, und sie bedecket Grausen, und Scham ist auf aller Angesicht, und auf all ihren Häuptern Kahlheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Ihr Silber werfen sie auf die Gassen, und zur Befleckung wird ihr Gold. Ihr Silber und ihr Gold vermögen nicht, sie zu erretten am Tag des Wütens Jehovahs. Sie sättigen nicht ihre Seele und füllen nicht ihre Eingeweide; denn zum Straucheln ward ihre Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Und die Zierde ihres Geschmeides setzten sie zum Stolz, und machten daraus die Bilder ihrer Greuel, ihrer Scheusale; darum habe Ich es ihnen zur Befleckung gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'Und in die Hand der Fremden gebe Ich es zum Raub, und zur Beute den Ungerechten der Erde, daß sie es entweihen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Und Ich habe Mein Angesicht von ihnen herumgewandt, und Mein Verborgenes entweihen sie, und Räuber kommen hinein und entweihen es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Mache eine Kette; denn das Land ist voll vom Gericht des Blutes, und die Stadt ist voll von Gewalttat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Und Ich lasse die Bösen der Völkerschaften kommen, daß sie derselben Häuser in Besitz nehmen, und lasse zu Ende kommen den Stolz der Starken, und ihre Heiligtümer sollen entweiht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Es kommt der Untergang; und sie suchen Frieden, und es wird keiner sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Unheil kommt auf Unheil; Gerücht auf Gerücht ist da. Und sie suchen Gesichte von den Propheten; aber das Gesetz ging dem Priester und Rat von den Ältesten verloren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'In Trauer ist der König, und der Fürst zieht an Erstaunen; und bestürzt sind die Hände des Volkes des Landes. Nach ihrem Wege tue Ich ihnen, und nach ihren Gerichten richte Ich sie, daß sie wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'Und es geschah im sechsten Jahr, im sechsten, am fünften des Monats, saß ich in meinem Hause und die Ältesten Jehudahs saßen vor mir, und allda fiel auf mich die Hand des Herrn Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'Und ich sah, und siehe, eine Ähnlichkeit wie Feuer anzusehen. Von dem Aussehen seiner Lenden und abwärts, Feuer; und von seinen Lenden und aufwärts das Aussehen von Lichtglanz, wie der Anblick der Glühkohle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'Und es reckte wie das Gebilde einer Hand aus und nahm mich bei den Locken meines Hauptes, und der Geist erhob mich zwischen Erde und Himmel und brachte mich gen Jerusalem in Gesichten Gottes zum Eingang des inneren Tores, das gen Mitternacht gewendet ist, wo der Sitz des Standbildes der Eifersucht war, das zum Eifern reizte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'Und siehe, allda war die Herrlichkeit des Gottes Israels wie das Aussehen dessen, den ich in dem Talgrund sah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'Und Er sprach zu mir: Menschensohn, hebe deine Augen auf gegen den Weg der Mitternacht; und ich hob meine Augen auf gegen den Weg der Mitternacht, und siehe, nördlich vom Tore des Altars war dieses Standbild der Eifersucht beim Hineingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'Und Er sprach zu mir: Menschensohn, siehst du, was diese tun? Große Greuel tut hier das Haus Israels. Mich zu entfernen von Meinem Heiligtum. Und kehre dich noch um, du wirst noch größere Greuel sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'Und Er brachte mich hinein zum Eingang des Vorhofs, und ich sah, und siehe, ein Loch war in der Wand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Und Er sprach zu mir: Menschensohn, durchbohre doch die Wand; und ich durchbohrte die Wand, und siehe, da war ein Eingang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'Und Er sprach zu mir: Gehe hinein und siehe die bösen Greuel, die sie allda tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'Und ich ging hinein und sah, und siehe, allerlei Gebilde von Kriechtier und Vieh, Scheusale und allerlei Götzen des Hauses Israel waren auf der Wand ringsum, ringsum gemalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'Und siebzig Männer von den Ältesten des Hauses Israels, und Jaasanjahu, der Sohn Schaphans, stand in ihrer Mitte; sie standen vor denselben und jeder Mann hatte sein Rauchfaß in seiner Hand, und der Wohlgeruch einer Wolke von Räuchwerk stieg auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'Und Er sprach zu mir: Siehst du, Menschensohn, was die Ältesten des Hauses Israels tun im Finstern, jeder Mann in den Kammern seines Gebildes? Denn sie sagen: Jehovah sieht uns nicht. Jehovah hat das Land verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Und Er sprach zu mir: Kehre dich noch zurück, siehe die großen Greuel, die sie tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Und Er brachte mich zum Eingang des Tores zu Jehovahs Haus gen Mitternacht hinein, und siehe, da saßen die Weiber, die um den Thammus weinten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'Und Er sprach zu mir: hast du gesehen, Menschensohn? Du wirst noch zurückkehren und größere Greuel denn diese sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'Und Er brachte mich hinein zum inneren Vorhof von Jehovahs Haus, und siehe, am Eingang zu Jehovahs Tempel zwischen der Halle und dem Altar war es, als wären fünfundzwanzig Männer mit ihrem Rücken gegen Jehovahs Tempel und mit ihrem Angesichte gegen Osten und beteten dem Osten zu die Sonne an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Und Er sprach zu mir: Siehst du es, Menschensohn? ist es ein Leichtes vom Hause Jehudah, daß sie die Greuel tun, die sie hier getan, daß sie das Land mit Gewalttat erfüllen, und zurückkehren, Mich zu reizen? Und siehe, sie recken das Rebmesser an ihre Nase aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Und auch Ich, Ich werde es im Grimme tun. Nicht schont Mein Auge, noch bemitleide Ich. Und rufen werden sie in Meine Ohren mit großer Stimme, aber Ich höre sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'Und Er rief in meine Ohren mit großer Stimme, sprechend: Sie nahen die Heimsucher der Stadt, und jeder Mann hat ein Werkzeug des Verderbens in seiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'Und siehe, sechs Männer kamen des Weges vom oberen Tor, das gegen Mitternacht gewendet ist, und jeder Mann hatte sein Werkzeug des Zerstreuens in seiner Hand, und ein Mann in ihrer Mitte war mit Lein angetan und hatte eines Schreibers Tintenfaß an seinen Lenden, und sie kamen herein und standen neben dem Altar von Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Und die Herrlichkeit des Gottes Israels stieg auf von dem Cherub, auf dem sie war, nach der Schwelle des Hauses hin und rief dem Mann, der mit Lein angetan war und des Schreibers Tintenfaß an seinen Lenden hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'Und Jehovah sprach zu ihm: Ziehe hindurch inmitten der Stadt, inmitten Jerusalems, und zeichne ein Zeichen auf die Stirne der Männer, die seufzen und jammern über all die Greuel, die in ihrer Mitte getan werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Und zu jenen sprach Er vor meinen Ohren: Zieht hindurch in die Stadt ihm nach und schlaget. Nicht schone euer Auge und habet kein Mitleid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Den Alten, den Jüngling und die Jungfrau, und das Kindlein und die Weiber sollt ihr erwürgen, sie zu verderben; aber an keinen Mann sollt ihr hinzutreten, an dem das Zeichen ist; und ihr sollt an Meinem Heiligtum anfangen. Und sie fingen bei den alten Männern an, die vor dem Hause waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'Und Er sprach zu ihnen: Verunreinigt das Haus und füllet mit Erschlagenen die Vorhöfe; ziehet aus. Und sie zogen aus und schlugen in der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'Und es geschah, da sie geschlagen hatten, daß ich verblieb. Und ich fiel auf mein Angesicht und schrie und sprach: Ach, Herr Jehovah, willst Du allen Überrest Israels verderben, daß Deinen Grimm Du ausgießest über Jerusalem?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Und Er sprach zu mir: Die Missetat des Hauses Israels und Jehudahs ist gar sehr groß und das Land ist gefüllt mit Blut, und voller Rechtsverdrehung ist die Stadt; denn sie sagen: Jehovah hat das Land verlassen, und Jehovah sieht nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Und auch Ich - Mein Auge wird nicht schonen, und Ich will nicht bemitleiden. Ihren Weg gebe Ich auf ihr Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'Und siehe, der Mann, der mit der Lein war angetan und das Tintenfaß an seinen Lenden hatte, brachte Wort zurück und sprach: Ich habe getan, wie Du mir geboten hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'Und ich sah, und siehe, auf der Ausbreitung über dem Haupte der Cherube war es wie der Stein Saphir, wie das Aussehen der Ähnlichkeit von einem Thron, über ihnen zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'Und Er sprach zu dem Manne, der mit Lein war angetan, und Er sprach: Gehe hinein zwischen das Räderwerk unter den Cherub, und fülle deine Hände mit Feuerkohlen, zwischen den Cheruben heraus und sprenge sie über die Stadt. Und er ging hinein vor meinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Und die Cherube standen rechts vom Hause, da der Mann hineinging, und die Wolke füllte den inneren Vorhof.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'Und es hob sich die Herrlichkeit Jehovahs empor über dem Cherub über des Hauses Schwelle, und von der Wolke ward das Haus erfüllt, und der Vorhof ward erfüllt vom Glanz der Herrlichkeit Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'Und die Stimme der Flügel der Cherube ward gehört bis zu dem äußeren Vorhof, wie die Stimme des Gottes Schaddai, wenn Er redet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'Und es geschah, als Er dem Manne mit Lein angetan geboten und gesagt hatte: Nimm Feuer zwischen dem Räderwerk heraus, zwischen den Cheruben, und der hineinging und neben dem Rad stand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'Da reckte der Cherub seine Hand aus zwischen den Cheruben her zum Feuer, das zwischen den Cheruben war, und hob auf und gab es dem, der mit Lein angetan war, in die Hände; und er nahm es und ging hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'Und man sah an den Cheruben unter ihren Flügeln das Gebilde der Hand eines Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'Und ich sah, und siehe, vier Räder neben den Cheruben, ein Rad neben dem einen Cherub und ein Rad neben dem anderen Cherub, und das Aussehen der Räder war wie der Anblick des Steins von Tharschisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Und ihr Aussehen hatte eine Ähnlichkeit für die vier, als ob ein Rad wäre inmitten eines Rades.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Bei ihrem Gehen gingen sie ihren vier Richtungen zu; sie wandten sich nicht um bei ihrem Gehen, denn nach dem Ort, dahin das Haupt sich wandte, danach gingen sie; sie wandten sich nicht um bei ihrem Gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'Und all ihr Fleisch und ihr Rücken und ihre Hände und ihre Flügel und die Räder waren voller Augen ringsum, für ihre vier Räder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'Die Räder - sie wurden Räderwerk genannt vor meinen Ohren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'Und vier Angesichte hatte einer: Das eine Angesicht das Angesicht des Cherubs und das zweite Angesicht war eines Menschen Angesicht und das dritte eines Löwen Angesicht und das vierte eines Adlers Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'Und es hoben sich empor die Cherube; das war das Tier, das ich am Flusse Chebar sah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'Und wenn die Cherube gingen, gingen die Räder neben ihnen, und wenn die Cherube die Flügel erhoben, sich über die Erde emporzuheben, so wandten auch die Räder sich nicht um von ihrer Seite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Und wenn dieselben standen, standen sie, und wenn sie sich emporhoben, hoben sie mit ihnen sich empor; denn der Geist des Tieres war in ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'Und von des Hauses Schwelle ging die Herrlichkeit Jehovahs aus und stand über den Cheruben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'Und die Cherube erhoben ihre Flügel und hoben sich von der Erde empor vor meinen Augen. Da sie hinausgingen, waren die Räder ihnen beigesellt. Und es stand am Eingang des östlichen Tores am Hause Jehovahs, und die Herrlichkeit des Gottes Israels war oben über ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'Das ist das Tier, das ich unter dem Gotte Israels am Flusse Chebar sah; und ich wußte, daß es Cherube waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Je vier Gesichter hatte einer und vier Flügel einer, und die Ähnlichkeit der Hände von Menschen unter ihren Flügeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Und die Ähnlichkeit ihrer Angesichter waren die Angesichter, die ich am Flusse Chebar sah, ihr Aussehen und sie selbst. Sie gingen, jeder Mann stracks vor seinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'Und es erhob mich der Geist und brachte mich herein an das vordere Tor von dem Hause Jehovahs, das nach Osten gewandt ist; und siehe, an des Tores Eingang waren fünfundzwanzig Männer, und ich sah in ihrer Mitte Jaasanjah, den Sohn Assurs, und Pelatjahu, Benajahus Sohn, Oberste des Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'Und Er sprach zu mir: Menschensohn, dies die Männer, die Unrecht denken und raten bösen Rat in dieser Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'Sie, die da sprechen: Es ist nicht nahe, daß man Häuser baue! Sie ist der Topf, und wir sind das Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Darum weissage wider sie, weissage, Menschensohn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'Und es fiel der Geist Jehovahs auf mich und sprach zu mir: Sprich: Also spricht Jehovah: So sprechet ihr, Haus Israel, und was in eurem Geiste aufsteigt, weiß Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Eurer Erschlagenen in dieser Stadt habt ihr viel gemacht, und ihre Gassen mit Erschlagenen gefüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Darum so spricht der Herr Jehovah: Eure Erschlagenen, die ihr in ihrer Mitte hingestreckt, sie sind das Fleisch, und sie ist der Topf. Euch aber bringt man heraus aus ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Das Schwert habt ihr gefürchtet, und das Schwert bringe Ich herein über euch: spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'Und aus ihrer Mitte lasse Ich euch hinausbringen, und gebe euch in der Fremden Hand und tue Gerichte über euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Ihr sollt fallen durch das Schwert, Ich richte euch an der Grenze Israels, auf daß ihr wisset, daß Ich bin Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'Sie soll euch der Topf nicht sein, noch sollt ihr das Fleisch darinnen sein, an Israels Grenze werde Ich euch richten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'Und ihr sollt wissen, daß Ich Jehovah bin, in dessen Satzungen ihr nicht gewandelt seid, und Meine Rechte habt ihr nicht getan, sondern habt getan nach den Rechten der Völkerschaften um euch her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'Und es geschah, wie ich weissagte, da starb Pelatjahu, der Sohn Benajahus, und ich fiel auf mein Angesicht und schrie mit großer Stimme und sprach: Ach, Herr Jehovah, willst Du Vollendung machen dem Überrest von Israel?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'Und es geschah an mich Jehovahs Wort, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Menschensohn, deine Brüder, deine Brüder, deiner Verwandtschaft Männer und das ganze Haus Israels allzumal, sie sind es, zu denen die, so in Jerusalem wohnen, sprechen: Bleibt ferne von Jehovah, uns ist es, das Land, zum Erbbesitz gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Sprich darum: So spricht der Herr Jehovah: Zwar werde Ich euch unter die Völkerschaften entfernen, und euch zerstreuen in die Länder; doch werde Ich ihnen ein kleines Heiligtum in den Ländern sein, dahin sie kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Darum sprich: Also spricht der Herr Jehovah: Und Ich werde euch zusammenbringen von den Völkern und euch versammeln aus den Ländern, dahin ihr seid zerstreut, und euch geben den Boden Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'Und sie werden dorthin kommen und wegtun alle seine Scheusale und alle seine Greuel aus demselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'Und geben will Ich ihnen ein Herz, und einen neuen Geist will Ich geben in eure Mitte, und wegnehmen das Herz von Stein aus ihrem Fleisch und ihnen geben ein Herz von Fleisch;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'Damit sie in Meinen Satzungen wandeln und Meine Rechte halten, und sie tun. Und sie werden Mir zum Volk, und Ich will ihnen Gott sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Aber dem Herzen ihrer Scheusale und ihren Greueln geht ihr Herz nach; ihren Weg will Ich auf ihr Haupt geben, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Und die Cherube erhoben ihre Flügel, und die Räder samt ihnen, und die Herrlichkeit des Gottes Israels war oben über ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'Und die Herrlichkeit Jehovahs stieg hinauf aus der Mitte der Stadt und stand über dem Berg, der im Osten der Stadt ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'Und es erhob mich der Geist und brachte mich hinein gen Chaldäa zu den Weggeführten in dem Gesicht, im Geiste Gottes; und das Gesichte das ich gesehen, stieg auf von mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'Ich aber redete zu den Weggeführten alle Worte Jehovahs, die Er mich sehen ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'Und es geschah an mich Jehovahs Wort, und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Menschensohn, du sitzest inmitten eines widerspenstigen Hauses; die haben Augen zum Sehen und sehen nicht; Ohren haben sie zum Hören und hören nicht, weil sie ein widerspenstig Haus sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Und du, Menschensohn, mache dir Geräte zur Wegführung und wandere aus am Tag vor ihren Augen, und wandere aus vor ihren Augen von deinem Ort an einen anderen Ort. Vielleicht daß sie sehen, daß sie sind ein widerspenstig Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'Und bringe heraus deine Geräte, wie Geräte zur Wegführung am Tage vor ihren Augen, und du, ziehe aus am Abend vor ihren Augen, wie die Weggeführten ausziehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Vor ihren Augen bohre dir durch die Wand, und bringe sie da hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'Vor ihren Augen erhebe sie auf die Schultern und in der Düsternis bringe sie hinaus, bedecke dein Gesicht, daß du das Land nicht sehest; denn Ich gebe dich zum Wahrzeichen dem Hause Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'Und ich tat so, wie mir geboten ward, meine Geräte brachte ich bei Tag als Geräte der Wegführung heraus, und am Abend bohrte ich mir mit der Hand durch die Wand; in der Düsternis brachte ich sie hinaus, erhob sie auf die Schulter vor ihren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'Und am Morgen geschah an mich das Wort Jehovahs sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Menschensohn, sprechen nicht zu dir die von dem Hause Israel, dem widerspenstigen Hause: Was tust du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Sprich zu ihnen: Also spricht der Herr Jehovah: Für den Fürsten ist diese Weissagung in Jerusalem und das ganze Haus Israel, das in seiner Mitte ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Sprich: Ich bin euch ein Wahrzeichen; wie ich getan habe, so wird euch getan, ihr werdet in Verbannung, in Gefangenschaft gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'Und den Fürsten, der in ihrer Mitte ist, ihn wird man auf die Schulter erheben in der Düsternis, daß er hinauskomme durch die Wand, die sie durchbohren, um ihn da hinauszubringen. Er wird sein Angesicht bedecken, daß er nicht selbst mit dem Auge das Land sehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'Und Ich will gegen ihn Mein Netz ausbreiten, daß er in Meinem Garn erfaßt werde, und will ihn nach Babel hineinbringen in der Chaldäer Land, und er wird es nicht sehen, und allda soll er sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'Und alles um ihn her, was ihm beistand, und alle seine Scharen will Ich in allen Winden hin zersprengen, und das Schwert ausziehen hinter ihnen her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'Auf daß sie wissen, daß Ich Jehovah bin, indem Ich unter die Völkerschaften sie zerstreue und sie versprenge in die Länder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Und ihrer will Ich nur wenige Männer vom Schwert, vom Hunger und von der Pest übrigbleiben lassen, daß sie unter den Völkerschaften, dahin sie kommen, alle ihre Greuel erzählen und wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'Und es geschah Jehovahs Wort an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Menschensohn, du sollst dein Brot mit Beben essen und dein Wasser mit Zittern und Sorgen trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'Und zu dem Volk des Landes sollst du sagen: So spricht der Herr Jehovah zu Jerusalems Bewohnern, zum Boden Israels: Ihr Brot sollen sie in Sorge essen und mit Erstaunen ihr Wasser trinken, weil ihr Land verwüstet ist, seiner Fülle bar ob der Gewalttat aller, die in ihm wohnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'Und die bewohnten Städte werden verödet, und das Land verwüstet werden, auf daß sie wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Und es geschah Jehovahs Wort an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Menschensohn, was habt ihr für ein Sprichwort auf dem Boden Israels, und ihr sprechet: Die Tage verlängern sich und alles Gesichte ist verloren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Darum sprich zu ihnen: Also spricht der Herr Jehovah: Ich lasse zu Ende kommen dieses Sprichwort. Und sie sollen nicht mehr das Sprichwort führen in Israel. Sondern rede zu ihnen: Die Tage nahen und jeglichen Gesichtes Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Denn nicht soll fürder irgendein eitel Gesichte, noch schmeichlerische Wahrsagung inmitten des Hauses Israels sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Denn Ich bin Jehovah. Was Ich rede, das rede Ich, das Wort wird getan und verzieht sich nicht mehr; denn in euren Tagen, du widerspenstig Haus, rede Ich ein Wort und tue es, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Und es geschah Jehovahs Wort an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Menschensohn, siehe, das Haus Israels spricht: Das Gesichte, das er erschaut, ist auf viele Tage, und für ferne Zeiten weissagt er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Darum sprich zu ihnen: Also spricht der Herr Jehovah: Keines Meiner Worte soll fürder mehr verziehen; was Ich geredet, das Wort, wird getan, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'Und es geschah das Wort Jehovahs an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Menschensohn, weissage über die Propheten Israels, die da weissagen, und sprich zu denen, die aus ihrem Herzen weissagen: Hört das Wort Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'So spricht der Herr Jehovah: Wehe über die törichten Propheten, die nach ihrem Geiste gehen und dem, was sie nicht sahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Wie Füchse in den Öden sind, Israel, deine Propheten geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Ihr stieget nicht hinauf in die Durchbrüche, noch zäuntet ihr einen Zaun für das Haus Israel, zu stehen im Streit am Tag Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Sie schauen Eitles und wahrsagen Falsches, sie sprechen: Jehovahs Spruch! und Jehovah hat sie nicht gesandt, und lassen darauf warten, daß Er das Wort bestätige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Habt ihr nicht ein eitel Gesicht geschaut, falsche Wahrsagungen gesprochen? und ihr sprechet: Jehovahs Spruch! und Ich habe nicht geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Darum spricht so der Herr Jehovah: Weil ihr Eitles redet und Falsches schaut, darum sehet, bin Ich wider euch, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'Und Meine Hand soll sein wider die Propheten, die Eitles schauen und Falsches wahrsagen. Im Kreise Meines Volkes sollen sie nicht sein und nicht eingeschrieben in die Schrift des Hauses Israels und nicht kommen auf den Boden Israels, auf daß ihr wisset, daß Ich der Herr Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Weil und alldieweil sie Mein Volk verleiten und sprechen: Friede! und ist kein Friede. Und baut es eine Scheidemauer - sie übertünchen sie mit Untauglichem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'Sprich zu den Tünchern mit dem Untauglichen: Sie falle! Ein überflutender Platzregen ist da, und ihr, Steine des Hagels, sollet fallen, und ein Wind des Wettersturmes soll sie durchbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Und siehe, die Wand fällt. Wird man nicht zu euch sagen: Wo ist die Tünche, mit der ihr habt getüncht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Darum, so spricht der Herr Jehovah, lasse Ich den Wind des Wettersturmes durchbrechen in Meinem Grimm, und ein überflutender Platzregen kommt in Meinem Zorn, und Steine des Hagels im Grimm zur Vollendung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Und reiße nieder die Wand, die ihr mit Untauglichem getüncht, und bringe sie zur Erde danieder, daß ihre Grundfeste aufgedeckt wird, und sie fällt, daß ihr alle werdet in ihrer Mitte; auf daß ihr wisset, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'Und Ich vollende Meinen Grimm an der Wand, und an denen, die mit dem Untauglichem sie getüncht haben, und spreche zu euch: Nicht mehr ist die Mauer, und nicht mehr die, die so übertünchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'Die Propheten Israels, die über Jerusalem weissagten, und die Schauer, die für sie Frieden schauten, und ist kein Frieden, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Du aber, Menschensohn, richte dein Angesicht auf deines Volkes Töchter, die da aus ihrem Herzen weissagen, und weissage über sie!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'Und sprich: So spricht der Herr Jehovah: Wehe euch, die ihr Kissen nähet an alle Gelenke der Hände, und Kopftücher für Köpfe jeglichen Wuchses machet, um Seelen zu erjagen. - Die Seelen erjaget ihr Meinem Volk, und erhaltet euch Seelen am Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'Und ihr entweiht Mich bei Meinem Volke für eine Handvoll Gerste und für Bissen Brotes, damit, daß ihr Seelen zum Tode bringt, die nicht sterben sollten, und am Leben erhaltet Seelen, die nicht leben sollten, damit, daß ihr täuschet Mein Volk, die, so auf Falsches hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Darum, so spricht der Herr Jehovah, siehe, Ich will an eure Kissen, womit ihr die Seelen jaget, daß sie entfliegen. Aber Ich reiße sie ab von euren Armen und entsende die Seelen, die ihr jagtet, - die Seelen, daß sie entfliegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Und Ich zerreiße eure Kopftücher und errette Mein Volk aus eurer Hand, daß sie nicht mehr in eurer Hand als Erjagtes sind, und ihr wisset, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Weil ihr durch Lüge des Gerechten Herz verzagen lasset, dem Ich nicht wehe tun will, und ihr stärket die Hände des Ungerechten, daß er von seinem bösen Weg nicht umkehre und am Leben bleibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'Darum sollt ihr nicht Eitles schauen, und Wahrsagung nicht weiter wahrsagen. Und Ich errette Mein Volk aus eurer Hand, daß ihr wisset, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'Und es kamen Männer von den Ältesten Israels zu mir und saßen vor meinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Und es geschah an mich das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Menschensohn, diese Männer ließen ihre Götzen in ihr Herz aufsteigen und gaben den Anstoß ihrer Missetat vor ihr Angesicht. Soll Ich von ihnen Mich befragen lassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Darum rede mit ihnen und sprich zu ihnen: So spricht der Herr Jehovah: Jeder Mann aus dem Hause Israels, der seine Götzen ließ in sein Herz aufsteigen, und seiner Missetat Anstoß sich vor sein Angesicht setzte, und zum Propheten kommt, sollte Ich, Jehovah, ihm antworten, der mit seiner Götzen Menge kommt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'Auf daß Ich das ganze Haus Israel an ihrem Herzen erfasse, weil sie sich allesamt durch ihre Götzen von Mir entfremdet haben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Darum sprich zu dem Hause Israels: So spricht der Herr Jehovah: Kehret zurück und wendet euch zurück von euren Götzen, und von allen euren Greueln wendet zurück euer Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Denn jeder Mann vom Hause Israel und von den Fremdlingen, die in Israel sich aufhalten, der sich rückwärts von Mir entfremdet und seine Götzen in sein Herz aufsteigen läßt, und den Anstoß seiner Missetat setzt vor sein Angesicht und kommt zu dem Propheten, Mich für sich zu befragen, so will Ich, Jehovah, ihm von Mir aus antworten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'Ich will Mein Angesicht hingeben wider solchen Mann und ihn verwüsten, zu einem Zeichen und Sprichwort und ihn ausrotten aus der Mitte Meines Volkes, auf daß ihr wisset, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Und wenn ein Prophet sich bereden läßt, daß er ein Wort redet, selbigen Propheten lasse auch Ich, Jehovah, bereden und recke Meine Hand aus wider ihn, daß Ich ihn aus der Mitte Meines Volkes Israel vernichte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'Und ihre Missetat sollen sie tragen. Die Missetat dessen, der da befragt, soll sein wie des Propheten Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'Auf daß das Haus Israel nicht mehr von Mir abirre und sich nicht mehr verunreinige mit allen ihren Übertretungen, und daß sie Mir zum Volke werden und Ich ihr Gott sei, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'Und es geschah an mich Jehovahs Wort, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Menschensohn, so ein Land sündigt wider Mich, daß es untreu Mir untreu wird, da recke Ich Meine Hand aus wider dasselbe und zerbreche ihm den Stab des Brotes und sende dahin den Hunger und rotte aus davon Mensch und Vieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'Und wenn in ihrer Mitte diese drei Männer wären: Noach, Daniel und Hiob, würden sie durch ihre Gerechtigkeit ihre Seelen erretten, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Wenn Ich böses wildes Tier lasse durch das Land hingehen, daß es dasselbe kinderlos macht, und es verwüstet, daß vor dem wilden Tier nichts da hindurchgeht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'Wenn diese drei Männer wären in ihrer Mitte, bei Meinem Leben, spricht der Herr Jehovah, sie würden ihre Söhne und Töchter nicht erretten, nur sie allein würden errettet, aber das Land wäre verwüstet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Oder bringe Ich das Schwert herein über jenes Land und spreche: Das Schwert ziehe durch das Land, und Ich rotte daraus Mensch und Vieh aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'Und diese drei Männer wären in seiner Mitte, bei Meinem Leben, spricht der Herr Jehovah, sie würden Söhne und Töchter nicht erretten; denn sie allein würden errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Oder sendete Ich die Pest über dieses Land und gösse Meinen Grimm aus wider es mit Blut, um aus ihm Mensch und Vieh auszurotten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'Und Noach, Daniel und Hiob wären in ihrer Mitte, bei Meinem Leben, spricht der Herr Jehovah, sie würden weder Sohn noch Tochter erretten, sie würden durch die Gerechtigkeit ihrer Seele errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Doch also spricht der Herr Jehovah: Wenn Ich auch sende Meine bösen vier Gerichte: Schwert und Hunger und das böse wilde Tier und Pest über Jerusalem, daß Ich daraus Mensch und Vieh ausrotte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'Und siehe, es verbleiben in ihr noch übrig Entkommene, die herausgebracht werden, Söhne und Töchter, siehe, sie kommen heraus zu euch und ihr werdet ihren Weg und ihre Handlungen sehen, und ihr werdet euch trösten über dem Bösen, das Ich über Jerusalem hereingebracht, über alles, das Ich über dasselbe hatte kommen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'Und sie werden euch trösten, wenn ihr ihren Weg und ihre Handlungen sehet, und ihr werdet wissen, daß Ich nicht umsonst all das getan, was Ich in ihm getan habe, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'Und es geschah zu mir das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Menschensohn, was ist das Holz des Weinstocks vor allem Holz? Die Rebe, die unter den Bäumen des Waldes ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Nimmt man davon Holz, um ein Werk zu machen? nimmt man davon einen Pflock, um irgendein Gerät daran aufzuhängen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Siehe, man gibt es dem Feuer zur Speise. Seine zwei Enden hat das Feuer aufgefressen, und in der Mitte ist es entbrannt. Gerät es zu einem Werk?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Siehe, da es noch ganz war, machte man kein Werk daraus. Nun aber das Feuer es aufgefressen und es entbrannt ist, kann man noch ein Werk davon machen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Darum spricht also der Herr Jehovah: Gleichwie das Holz des Weinstocks ist unter dem Holz des Waldes, das Ich zur Speise dem Feuer gebe, so gebe Ich Jerusalems Bewohner,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'Und gebe wider sie Mein Angesicht, daß, wo sie auch dem Feuer sind entgangen, das Feuer sie doch fressen wird. Und ihr sollt wissen, daß Ich Jehovah bin, wenn Ich Mein Angesicht setze wider sie,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Und Ich das Land zur Wüste hingebe, weil sie sind untreu worden, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Und es geschah an mich das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Menschensohn, tue Jerusalem ihre Greuel zu wissen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'Und sprich: So spricht der Herr Jehovah zu Jerusalem: Dein Handel und deine Geburt ist aus dem Land des Kanaaniters; dein Vater ist der Amoriter und deine Mutter eine Chethiterin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'Und bei deiner Geburt, am Tag, da du geboren wardst, wurde dein Nabel nicht abgeschnitten, und du wurdest im Wasser nicht gebadet für Mein Anschauen, nicht mit Salz gesalzen und in Windeln nicht gewickelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Kein Auge schonte dein, dir eins von diesen zu tun, dich zu bemitleiden, und du wurdest auf des Feldes Fläche hingeworfen, aus Ekel vor deiner Seele am Tag, da du geboren wardst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Und Ich ging an dir vorüber und sah dich zertreten in deinem Blut, und sprach zu dir in deinem Blut: Lebe! Und Ich sprach zu dir in deinem Blute: Lebe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'Zur Mehrung, wie den Sproß des Feldes gab Ich dich, und du wuchsest und wurdest groß, und kamst in dem Schmuck deines Schmuckes, die Brüste wurden fest, und dein Haar sproßte; du aber warst nackt und bloß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Und Ich ging an dir vorüber und sah dich, und siehe, es war deine Zeit, die Zeit der Liebkosungen, und Ich breitete Meinen Fittich über dich und deckte deine Blöße und schwor dir und ging einen Bund ein mit dir, spricht der Herr Jehovah, und du wardst Mein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Und Ich badete dich mit Wasser und spülte ab dein Blut von dir und salbte dich mit Öl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'Und Ich zog dir Gewirktes an, und beschuhte dich mit Tachaschfell, umwand dich mit Byssus und bedeckte dich mit Seide.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'Und ich schmückte dich mit Geschmeide und gab Armbänder an deine Hände und ein Kettchen um deinen Nacken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'Und gab einen Reif an deine Nase und Ohrringe an deine Ohren und eine Krone der Zierde auf dein Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'Und du warst geschmückt mit Gold und Silber, und dein Anzug war Byssus und Seide und Gewirktes. Semmelmehl und Honig und Öl aßest du, und wardst gar sehr schön, und gelangtest zum Königtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'Und dein Name ging aus ob deiner Schönheit, denn sie war vollkommen durch Mein Geschmeide, das Ich dir angelegt hatte, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Du aber vertrautest auf deine Schönheit und buhltest auf deinen Namen und gossest deine Buhlereien aus auf jeden, der vorüberging, sein war sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'Und nahmst von deinen Kleidern und machtest dir bunte Opferhöhen und buhltest auf ihnen, was nicht gekommen ist noch geschehen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Und du hast Geräte deines Schmuckes von Meinem Gold und Meinem Silber, das Ich dir gegeben hatte, genommen und männliche Bilder dir gemacht und mit ihnen gebuhlt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'Und hast deine gewirkten Kleider genommen und sie bedeckt und Mein Öl und Mein Räucherwerk gabst du vor sie;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Und Mein Brot, das Ich dir hatte gegeben, Semmelmehl und Öl und Honig, so Ich dich essen ließ, hast du vor sie gegeben zum Geruch der Ruhe, und es geschah, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Und du nahmst deine Söhne und Töchter, die du Mir geboren, und opfertest sie ihnen zum Fraß. War es zu wenig für deine Buhlereien?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'Und Meine Söhne hast du geschlachtet und sie gegeben, daß sie für sie durch das Feuer hindurchgingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'Und bei all deinen Greueln und Buhlereien gedenkst du nicht der Tage deiner Jugend, wie du nackt und bloß warst, zertreten in deinem Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'Und es geschah nach all deiner Bosheit - wehe, wehe dir, spricht der Herr Jehovah-');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'Daß du dir bautest eine Hochwarte und dir eine Höhe machtest in jeder Straße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'Am Anfang jedes Weges bautest du deine Höhe, und machtest zum Greuel deine Schönheit, und spreiztest dein Füße jedem, der vorüberging, und mehrtest deine Buhlerei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Und buhltest mit Ägyptens Söhnen, deinen Nachbarn groß an Fleisch, und mehrtest deine Buhlerei, Mich zu reizen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'Und siehe, Ich habe Meine Hand ausgestreckt über dich und verringerte dein Bestimmtes, und gebe dich in den Willen derer, die dich hassen der Töchter der Philister, die Schande fühlten ob deiner Unzucht Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Und du buhltest mit Aschurs Söhnen, weil du nicht satt kannst werden. Und mit ihnen hast du gebuhlt und wurdest auch nicht satt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Und du mehrtest deine Buhlerei bis in das Land des Handels Chaldäa, und auch da bist du nicht satt geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Wie verschmachtet dein Herz, spricht der Herr Jehovah, weil du all dies tust, das Werk eines buhlerischen, herrischen Weibes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'Indem du deine Hochwarte bautest am Anfang jedes Weges und deine Höhe machtest in jeder Straße, warst du nicht wie die Buhlerin, die ihrer Buhlgabe sich brüstet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'Das ehebrecherische Weib nimmt anstatt ihres Mannes Fremde an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Man gibt jeglicher Buhlerin ein Buhlgeschenk, aber du gibst allen deinen Liebhabern deine Buhlgeschenke, und beschenkst sie, daß sie von ringsumher zu deiner Buhlschaft zu dir kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'Und ist bei dir das Umgekehrte gegen die Weiber bei deinen Buhlereien, daß dir nicht nachgebuhlt wird, und damit, daß du die Buhlgabe gibst und dir keine Buhlgabe gegeben wird. Und du warst zum Umgekehrten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Darum, Buhlerin, höre das Wort Jehovahs!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'So spricht der Herr Jehovah: Weil dein Erz ausgeschüttet ist und deine Blöße aufgedeckt in deinen Buhlereien mit deinen Liebhabern und mit allen Götzen deiner Greuel und ob dem Blute deiner Söhne, die du ihnen hast gegeben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'Darum, siehe, will Ich zusammenbringen alle deine Liebhaber, denen du angenehm gewesen und alle, die du geliebt hast, mit allen, die du gehaßt hast, und Ich will sie zusammenbringen wider dich von ringsumher, und will deine Blöße vor ihnen aufdecken, daß sie alle deine Blöße sehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'Und Ich will richten über dich Gerichte der Ehebrecherinnen und derer, die Blut vergießen, und gebe dich zum Blut des Grimmes und des Eifers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'Und Ich gebe dich in ihre Hand, daß sie deine Hochwarten umreißen, und abbrechen deine Höhen und dir deine Kleider ausziehen, und sie nehmen die Geräte deines Schmuckes, und dich nackt und bloß lassen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'Und sie bringen eine Versammlung wider dich herauf, die mit dem Stein dich sollen steinigen und mit ihren Schwertern zerstücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'Und deine Häuser verbrennen sie mit Feuer und tun an dir Gerichte vor vieler Weiber Augen. Und ich mache deiner Buhlerei ein Ende und du sollst keine Buhlgabe mehr geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'Und Ich lasse ruhen Meinen Grimm wider dich, und Mein Eifer weicht von dir, und Ich raste und bin nicht mehr gereizt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Weil du der Tage deiner Jugend nicht gedacht und Mich mit alledem hast aufgebracht, siehe, so gebe auch Ich deinen Weg dir auf dein Haupt, spricht der Herr Jehovah, auf daß du nicht tust zu allen deinen Greueln noch Unzucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Siehe, jeder, der Sprichworte redet, wird über dich das Sprichwort reden und sagen: Wie die Mutter, so ihre Tochter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Die Tochter deiner Mutter bist du, die ihres Mannes und ihrer Söhne überdrüssig ward; und die Schwester deiner Schwestern bist du, die ihrer Männer und ihrer Söhne überdrüssig wurden; eure Mutter ist eine Chethiterin und euer Vater ein Amoriter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Und deine große Schwester ist Schomron, sie und ihre Töchter, die dir zu Linken wohnt; und deine kleine Schwester, die zu deiner Rechten wohnt, ist Sodom und ihre Töchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Nicht bist du in ihren Wegen gewandelt und hast nach ihren Greueln getan. Um ein wenig verdroß es dich, und du hast in allen deinen Wegen Verderblicheres denn sie getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Bei Meinem Leben, spricht der Herr Jehovah, deine Schwester Sodom, sie und ihre Töchter haben nicht getan, wie du und deine Töchter getan habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Siehe, das war deiner Schwester Sodom Missetat: Stolz, Sättigung an Brot und sorgloses Rasten bei ihr und ihren Töchtern, und die Hand des Elenden und Dürftigen hat sie nicht gestärkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'Sie wurden aber hoffärtig und taten Greuel vor Mir, und Ich tat sie hinweg, wie Ich es sah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Schomron hatte nicht die Hälfte deiner Sünden gesündigt, und du mehrtest deine Greuel mehr denn sie und hast deine Schwester gerechtfertigt durch alle deine Greuel, die du getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'So trage auch du denn deine Schande, wozu du deine Schwester verurteiltest; durch deine Sünden, durch die du dich greulicher denn sie gemacht, machst du sie gerechter denn du, und auch du schäme dich und trage deine Schande, daß deine Schwestern du gerechtfertigt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Ich aber bringe zurück ihre Gefangenschaft, Sodoms und seiner Töchter Gefangenschaft und Schomrons und seiner Töchter Gefangenschaft und die Gefangenen deiner Gefangenschaft in ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'Auf daß du tragest deine Schande und bist zuschanden worden ob allem, das du tatest, indem du ihnen zum Troste wirst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'Und deine Schwestern Sodom und ihre Töchter sollen zurückkehren in ihren früheren Stand und Schomron und seine Töchter werden zurückkehren in ihren früheren Stand, und du und deine Töchter sollet zurückkehren in euren früheren Stand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Und war nicht deine Schwester Sodom am Tage deines Stolzes zum Gerücht in deinem Mund,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'Ehe deine Bosheit aufgedeckt war, wie zur Zeit der Schmähung von Arams Töchtern und allen seinen Umgebungen, den Töchtern der Philister, die ringsumher dich verhöhnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Deine Unzucht und deine Greuel hast du getragen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Denn also spricht der Herr Jehovah: Und Ich tue dir, wie du hast getan, weil du den Eid hast verachtet und den Bund zunichte gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Ich will aber Meines Bundes mit dir in den Tagen deiner Jugend gedenken und einen Bund mit dir aufrichten der Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Du aber sollst gedenken deiner Wege, und Schande fühlen, wenn du deine Schwestern nimmst, die größer sind denn du, zusamt den kleineren als du, und Ich sie dir zu Töchtern gebe, aber nicht wegen deines Bundes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'Aber Ich will Meinen Bund mit dir aufrichten, auf daß du wissest, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'Auf daß du dessen gedenkst und dich schämst und deinen Mund nicht auftun dürfest vor Schanden, wenn Ich Mich versöhne mit dir, ob allem, das du getan, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'Und es geschah an mich das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Menschensohn, rätsle ein Rätsel und sprich ein Sprichwort von dem Hause Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'Und sprich: Also spricht der Herr Jehovah: Der große Adler, groß an Flügeln, mit langen Fittichen, voll Gefieder, bunt an Farben, kam auf den Libanon und nahm den Wipfel einer Zeder;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Das Haupt von seinen Reisern pflückte er ab und brachte es hinein in ein Land des Handels und setzte es in eine Stadt der Kaufleute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'Und er nahm von des Landes Samen und tat ihn in ein Feld der Saat, er nahm ihn an viel Wasser, vorsichtig setzte er ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'Und er sproßte und wurde zu einem üppigen Weinstock niedrigen Wuchses, so daß seine Ranken sich zu ihm selber wandten, und seine Wurzeln unter ihm waren; und er ward zu einem Weinstock und machte Zweige und entsandte Schosse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Und da war ein großer Adler, groß an Flügeln und mit viel Gefieder, und siehe, dieser Weinstock bog seine Wurzeln zu ihm hin und entsandte seine Ranken nach ihm, daß er ihn tränkete von den Beeten seiner Pflanzung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'In einem guten Felde, an vielen Wassern war er eingepflanzt, daß er solle Zweige machen und Frucht tragen, so daß er ein stattlicher Weinstock wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Sprich: Also spricht der Herr Jehovah: Wird er gedeihen? Wird man nicht seine Wurzeln ausreißen, und seine Frucht abstreifen, daß er verdorrt, daß all sein abgepflücktes Gesproß verdorrt? Aber ohne einen großen Arm und viel Volk wird man ihn von seinen Wurzeln erheben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'Und siehe, er ist eingepflanzt, wird der gedeihen? Wenn ihn berührt der Wind von Osten, wird er nicht ganz verdorren? Wird er nicht in den Beeten, da er sproßt, verdorren?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Und es geschah das Wort Jehovahs zu mir, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Sprich doch zu dem widerspenstigen Haus: Wißt ihr nicht, was dies ist? Sprich: Siehe, der König Babels kommt nach Jerusalem und nimmt dessen König und seine Obersten und bringt sie zu sich hinein nach Babel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'Und er nahm einen vom Samen des Königtums und schloß einen Bund mit ihm, und ging einen Eid ein mit ihm, und die Widder des Landes nahm er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'Auf daß das Königreich niedrig sei und sich nicht erhebe, den Bund halte und dastehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Und er empörte sich wider ihn und sandte seine Boten nach Ägypten, daß man ihm Rosse und viel Volkes gebe. Wird es ihm gelingen? Wird der entrinnen, der solches tut? Und er hat den Bund zunichte gemacht und sollte entrinnen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Bei Meinem Leben, spricht der Herr Jehovah: Er wird am Ort des Königs, der ihn zum König machte, dessen Eid er verachtet und dessen Bund er zunichte gemacht hat, bei ihm inmitten Babels sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'Und nicht mit großer Streitmacht und vieler Versammlung wird Pharao mit ihm tun im Streite, wenn einen Wall man aufschüttet und ein Bollwerk baut, um viele Seelen auszurotten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Und er hat den Eid verachtet, daß er den Bund zunichte machte, und siehe, er hatte seine Hand gegeben und alles dies getan; er wird nicht entrinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Darum, so spricht der Herr Jehovah, werde Ich, bei Meinem Leben, Meinen Eid, den er verachtet, und Meinen Bund, den er zunichte gemacht hat, auf sein Haupt geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'Und Mein Netz über ihn ausbreiten, daß er erfaßt wird in Meinem Garn, und werde ihn nach Babel hineinbringen und rechten allda mit ihm ob der Untreue, die er an Mir begangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'Und all seine Auserwählten, in allen seinen Scharen sollen durch das Schwert fallen, und die, so verblieben, ausgebreitet werden in allen Wind, und ihr sollt wissen, daß Ich, Jehovah, geredet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'So spricht der Herr Jehovah: Und Ich nehme vom Wipfel der emporragenden Zeder und gebe es, Ich pflücke vom Haupte ihrer Reiser ein zartes ab, und Ich pflanze es ein auf einen hohen und ragenden Berg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Ich will es einpflanzen auf den emporragenden Berg Israels, daß es den Zweig erhebe und Frucht trage und zur stattlichen Zeder werde, und unter ihm jeder Vogel jeglichen Gefieders wohne; im Schatten seiner Zweige sollen sie wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'Und alle Bäume des Feldes sollen wissen, daß Ich, Jehovah, erniedrige den hohen Baum, daß Ich hoch mache den niedrigen Baum, verdorren lasse den grünen Baum, und aufsprossen den dürren Baum. Ich, Jehovah, habe geredet, und Ich tue es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'Und es geschah an mich das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Was führt ihr auf Israels Boden dies Sprichwort, daß ihr sagt: Die Väter essen Herlinge und den Söhnen werden die Zähne stumpf davon?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Bei Meinem Leben, spricht der Herr Jehovah, ihr sollt dies Sprichwort nimmer führen in Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Seht, Mein sind sie, alle Seelen, wie des Vaters Seele, so des Sohnes Seele, sie sind Mein. Die Seele, die da sündigt, sie soll sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'Und der Mann, so da gerecht ist, und Recht tut und Gerechtigkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'Der auf den Bergen nicht ißt, und seine Augen nicht erhebt zu den Götzen des Hauses Israels und nicht verunreinigt seines Nächsten Weib, und dem Weibe in ihrer Unreinheit nicht naht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'Und der Mann, der nicht bedrückt, sein Pfand für die Schuld zurückgibt, keinen ausplündert, dem Hungernden sein Brot gibt und den Nackten bedeckt mit einem Kleide,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'Nicht gibt auf Wucher, und keine Mehrung nimmt, vom Verkehrten seine Hand zurückwendet, ein wahrhaft Urteil tut zwischen Mann und Mann,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'Wandelt in Meinen Satzungen und hält Meine Rechte, daß er Wahrheit tue: gerecht ist er, er soll leben, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Und zeugt er einen Sohn, einen Räuber, der Blut vergießt, und tut auch nur deren eines;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'Und er tut das alles nicht: denn er ißt auf den Bergen und verunreinigt das Weib seines Nächsten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'Der den Elenden und Dürftigen bedrükket, der ausplündert, das Pfand nicht zurückgibt und zu den Götzen erhebt seine Augen, Greuel tut,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'Auf Wucher gibt und Mehrung nimmt. Und der soll leben? Nicht soll er leben! All diese Greuel tut er. Er soll des Todes sterben. Sein Blut soll auf ihm sein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'Und siehe, er zeugt einen Sohn, und der sieht alle Sünden seines Vaters, die er tut, und er fürchtet sich und tut nicht dergleichen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'Ißt nicht auf den Bergen und erhebt nicht seine Augen zu den Götzen des Hauses Israels und verunreinigt nicht seines Nächsten Weib;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'Und bedrückt den Mann nicht, behält kein Pfand zurück und plündert nicht aus, gibt dem Hungrigen sein Brot, und bedeckt den Nackten mit einem Kleid,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'Kehrt von dem Elenden die Hand nicht zurück, nimmt nicht Wucher, noch Mehrung, tut Meine Rechte, wandelt in Meinen Satzungen - er soll nicht sterben ob seines Vaters Missetat! Er soll leben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Sein Vater, der mit Erpressung erpreßte, den Bruder ausplünderte, und der nicht das Gute tat inmitten seines Volkes, und siehe, der stirbt in seiner Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'Und sprechet ihr: Warum soll denn der Sohn an des Vaters Missetat nicht tragen? Weil der Sohn Recht und Gerechtigkeit getan, all Meine Satzungen gehalten und sie getan, soll er leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Die Seele, die da sündigt, sie soll sterben. Der Sohn soll nicht tragen an der Missetat des Vaters, und der Vater soll nicht tragen an der Missetat des Sohnes, des Gerechten Gerechtigkeit soll sein auf ihm, und die Unge- rechtigkeit des Ungerechten soll auf ihm sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Wo aber der Ungerechte zurückkehrt von allen seinen Sünden, die er getan, und hält alle Meine Satzungen, und tut Recht und Gerechtigkeit, der soll gewißlich leben; er soll nicht sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'All seiner Übertretungen, die er getan, soll ihm nicht mehr gedacht werden, er soll leben in seiner Gerechtigkeit, die er hat getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Habe Ich Lust am Tode des Ungerechten, spricht der Herr Jehovah, und nicht an seiner Rückkehr von seinen Wegen, daß er lebe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Und wo der Gerechte kehrt zurück von seiner Gerechtigkeit und tut Verkehrtes nach all den Greueln, die der Ungerechte tut, sollte der es tun und leben? All seiner Gerechtigkeit, die er getan, wird man nicht mehr gedenken in der Untreue, die er begangen und in den Sünden, die er gesündigt hat, in ihnen soll er sterben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'Und ihr sprecht: Nicht recht ist der Weg des Herrn. So höret doch, ihr Haus Israel: Ist denn Mein Weg nicht recht, und sind nicht eure Wege nicht recht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Wenn der Gerechte sich zurückkehrt von seiner Gerechtigkeit und tut Verkehrtes, so stirbt er darob. Ob seiner Verkehrtheit, die er tat, stirbt er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'Und wenn der Ungerechte zurückkehrt von seiner Ungerechtigkeit, die er getan, und Recht tut und Gerechtigkeit, soll seine Seele er am Leben erhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Denn er sah es und kehrte zurück von allen seinen Übertretungen, die er getan, er soll leben, soll nicht sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'Und die vom Hause Israel sprechen: Des Herrn Weg ist nicht recht. Sind Meine Wege nicht recht, du Haus Israel, sind nicht eure Wege nicht recht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Darum werde Ich euch, jeden Mann nach seinen Wegen, richten, Haus Israel, spricht der Herr Jehovah. Kehrt zurück und wendet euch zurück von allen euren Übertretungen, daß die Missetat euch nicht zum Anstoß werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Werfet von euch all eure Übertretungen, wodurch ihr abgefallen waret, und machet euch ein neues Herz und einen neuen Geist! Denn warum wollt ihr sterben, ihr vom Hause Israel?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Denn Ich habe keine Lust am Tod des Sterbenden, spricht der Herr Jehovah; darum kehrt zurück und lebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Und du erhebe ein Trauerlied über die Fürsten Israels,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'Und sprich: Was war deine Mutter? Eine alte Löwin, unter Löwen lagerte sie, inmitten junger Löwen erzog sie ihre Jungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'Und es stieg herauf eines von ihren Jungen. Ein junger Löwe war es, und lernte zerfleischen, Menschen fressen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'Und von ihm hörten die Völkerschaften; er ward in ihrer Fallgrube erfaßt, und an Haken brachten sie ihn herein nach dem Land Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'Sie aber sah, daß sie gewartet, aber ihre Hoffnung verloren war, und nahm ihrer Jungen eines, setzte es zum jungen Löwen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Und inmitten der Löwen ging er einher, ward zum jungen Löwen und lernte das Zerfleischen, fraß Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'Und erkannte ihre Witwen und verödete ihre Städte, und verwüstete das Land und seine Fülle durch die Stimme seines Brüllens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Und die Völkerschaften setzten sich wider ihn aus den Landschaften ringsumher, und breiteten ihr Netz aus wider ihn, und in ihrer Fallgrube ward er erfaßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'Und sie taten ihn in den Käfig an Haken und brachten ihn herein zum König von Babel und brachten ihn in die Festen, damit seine Stimme nicht mehr auf Israels Bergen gehört würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Deine Mutter war wie ein Weinstock, dir ähnlich, am Wasser hingepflanzt; fruchtbar und rebenvoll ward er vom vielen Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'Und hatte starke Stäbe zu Zeptern der Herrscher, und sein Wuchs ward hoch zwischen Dichtverflochtenem; so ward er sichtbar durch seine Höhe, durch die Menge seiner Zweige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'Aber er ist im Grimm ausgerissen, zur Erde geworfen, und der Wind vom Osten hat verdorrt seine Frucht. Abgerissen und verdorrt wurden die Stäbe seiner Stärke. Das Feuer fraß sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'Und nun ist er eingepflanzt in die Wüste, in ein Land der Dürre und des Durstes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'Und nun ist von dem Stabe seiner Zweige Feuer ausgegangen, es frißt auf seine Frucht, und ist daran kein Stab der Stärke zum Zepter eines Herrschers. Ein Trauerlied ist es, und ward zum Trauerlied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'Und es geschah im siebenten Jahr am zehnten im fünften Monat, daß Männer von den Ältesten Israels kamen, Jehovah zu befragen, und sie saßen vor mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'Und es geschah zu mir das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Menschensohn, rede mit den Ältesten von Israel und sprich zu ihnen: Also spricht der Herr Jehovah: Seid ihr gekommen, Mich zu befragen? Bei Meinem Leben lasse Ich Mich von euch nicht befragen, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Willst du sie richten, willst du sie richten, Menschensohn, so tue ihnen die Greuel ihrer Väter zu wissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'Und sprich zu ihnen: Also spricht der Herr Jehovah: Am Tage, da Ich Israel erwählte, und erhob Meine Hand für den Samen des Hauses Jakob und tat Mich ihnen zu wissen im Land Ägypten, und erhob ihnen Meine Hand, sprechend: Ich bin Jehovah, euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'An selbem Tag erhob Ich Meine Hand für sie, sie herauszubringen aus dem Land Ägypten in ein Land, das für sie Ich ausgespäht hatte, das von Milch und Honig fließt, das die Zierde für alle Länder ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'Und Ich sprach zu ihnen: Werft ein jeder Mann die Scheusale seiner Augen hin, und mit den Götzen Ägyptens verunreinigt euch nicht! Ich, Jehovah, bin euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Und sie wurden widerspenstig wider Mich und wollten nicht auf Mich hören, und kein Mann warf die Scheusale seiner Augen weg, und sie verließen Ägyptens Götzen nicht, so daß Ich sprach, Ich wollte Meinen Grimm ausschütten über sie, allen Meinen Zorn an ihnen zu vollenden mitten im Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Aber Ich tat es um Meines Namens willen, daß er nicht entweiht würde vor den Augen der Völkerschaften, in deren Mitte sie waren, denen Ich vor deren Augen war bekannt geworden, daß Ich sie herausbrachte aus dem Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'Und Ich brachte sie heraus aus dem Lande Ägypten und brachte sie herein in die Wüste,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'Und gab ihnen Meine Satzungen und tat ihnen Meine Rechte zu wissen, die der Mensch tun soll, daß er durch sie lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Und auch Meine Sabbathe habe Ich ihnen gegeben, daß sie zum Zeichen seien zwischen Mir und ihnen, auf daß sie wüßten, daß Ich, Jehovah, bin, Der sie heiligt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Aber das Haus Israels war widerspenstig wider Mich in der Wüste; sie wandelten nicht in Meinen Satzungen und verschmähten Meine Rechte, die der Mensch tun soll, daß er durch sie lebe. Und sie entweihten Meine Sabbathe sehr. Und Ich sagte, daß Ich Meinen Grimm in der Wüste werde ausschütten über sie, um sie alle zu machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Aber Ich tat es um Meines Namens willen, daß er nicht entweiht würde vor den Augen der Völkerschaften, vor deren Augen Ich sie herausgebracht hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Und auch in der Wüste erhob Ich Meine Hand wider sie, daß Ich sie nicht wollte in das Land hereinbringen, das Ich ihnen gab, welches von Milch und Honig fließt, das die Zierde für alle Länder ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'Weil sie Meine Rechte verschmähten und in Meinen Satzungen nicht wandelten und Meine Sabbathe entweihten, indem ihr Herz wandelte ihren Götzen nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Aber Mein Auge schonte ihrer, daß Ich sie nicht verdarb, und Ich es mit ihnen nicht alle machte in der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'Und Ich sprach zu ihren Söhnen in der Wüste: Ihr sollt nach eurer Väter Satzungen nicht wandeln und nicht halten ihre Rechte, noch mit ihren Götzen euch verunreinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Ich, Jehovah, bin euer Gott. Nach Meinen Satzungen sollt ihr wandeln und Meine Rechte halten und sie tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'Und Meine Sabbathe sollt ihr heiligen, daß sie ein Zeichen seien zwischen Mir und euch, auf daß ihr wisset, daß Ich, Jehovah, euer Gott bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Aber die Söhne waren gegen Mich widerspenstig, sie wandelten nicht in Meinen Satzungen und hielten Meine Rechte nicht, daß sie solche getan hätten, die der Mensch tut und durch sie lebt. Meine Sabbathe entweihten sie; und Ich sagte, Ich wolle Meinen Grimm ausschütten über sie, daß Mein Zorn sie alle mache in der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'Ich kehrte aber Meine Hand zurück und tat es um Meines Namens willen, auf daß er vor den Augen der Völkerschaften nicht entweiht würde, vor deren Augen Ich sie herausgebracht hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Auch hob Ich in der Wüste Meine Hand auf wider sie, sie zu zerstreuen unter die Völkerschaften und sie zu zersprengen in die Länder,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'Weil sie Meine Rechte nicht taten und Meine Satzungen verschmähten und Meine Sabbathe entweihten und nach den Götzen ihrer Väter waren ihre Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Und darum gab Ich ihnen auch Satzungen, die nicht gut waren, und Rechte, darinnen sie kein Leben haben konnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'Und ließ sie sich verunreinigen an ihren Gaben, daß sie durch das Feuer durchführten alles, was die Mutter bricht, sie zu verwüsten, auf daß sie wüßten, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Darum, Menschensohn, sollst du reden zu dem Haus Israel und zu ihnen sprechen: So spricht der Herr Jehovah: Noch darin verhöhnten Mich eure Väter, daß Untreue sie wider Mich begingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Und Ich brachte sie herein zu dem Land, das Ich Meine Hand aufgehoben, ihnen zu geben; und wenn sie sahen irgendeinen emporragenden Hügel, oder irgendeinen dichtbelaubten Baum, so opferten sie da ihre Opfer, und gaben da den Unmut ihrer Opfergaben, und legten hin den Geruch der Ruhe, und gossen ihre Trankopfer aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'Und Ich sprach zu ihnen: Was ist die Opferhöhe, wohin ihr kommt? Und ihr Name wurde genannt bis auf diesen Tag Bamah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Darum sprich zum Hause Israels: So spricht der Herr Jehovah: Wollt ihr euch auf dem Wege eurer Väter verunreinigen und ihren Scheusalen nachbuhlen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'Und wenn ihr eure Gaben erhebt, wenn ihr eure Söhne in das Feuer hindurchführt, ihr euch mit allen euren Götzen verunreinigt bis auf diesen Tag, sollte Ich Mich von euch, o Haus Israels, befragen lassen? Bei Meinem Leben, spricht der Herr Jehovah, Ich lasse Mich nicht von euch befragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'Und das, was in eurem Geist aufsteigt, soll nicht geschehen - wie ihr sprecht: Laßt uns sein wie die Völkerschaften, wie die Familien der Länder, daß wir dem Holze und dem Steine Dienst tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Bei Meinem Leben, spricht der Herr, Jehovah, mit starker Hand und mit ausgestrecktem Arm und ausgeschüttetem Grimm will Ich über euch regieren,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'Und aus den Völkern euch herausbringen und euch zusammenbringen aus den Ländern, wohin ihr zerstreut seid, mit starker Hand und mit ausgestrecktem Arm und mit ausgeschüttetem Grimm,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'Und werde euch hereinbringen zu der Wüste der Völker und mit euch allda rechten von Angesicht zu Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'Wie Ich mit euren Vätern habe gerechtet in der Wüste beim Lande Ägypten, so will Ich mit euch rechten, spricht der Herr Jehovah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'Und lasse euch dann vorüberziehen, unter der Rute und bringe euch herein in das Band des Bundes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'Und scheide von euch aus die Empörer und die von Mir abfielen. Herausbringen werde Ich sie vom Lande ihrer Wanderungen, aber auf den Boden Israels soll keiner kommen, auf daß ihr wisset, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Und ihr vom Hause Israels - so spricht der Herr Jehovah - geht, dienet, ein jeder Mann seinen Götzen, danach aber, wenn ihr nicht auf Mich hört, so entweiht nicht mehr Meinen Namen mit euren Gaben und mit euren Götzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Denn auf dem Berge Meiner Heiligkeit, auf dem Berg der Höhe Israels, spricht der Herr Jehovah, allda wird dienen Mir das ganze Haus Israels, sie alle im Lande. Dort werde Ich Wohlgefallen haben an ihnen, und allda will Ich fordern eure Hebeopfer und eure Opfergaben, Erstlinge von allem, was ihr Mir heiligt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Durch den Geruch der Ruhe werde Ich an euch Wohlgefallen haben, wenn Ich euch von den Völkern herausgebracht und euch zusammengebracht habe aus den Ländern, dahin ihr seid zerstreut worden, und werde in euch geheiligt werden in den Augen der Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'Und ihr sollt wissen, daß Ich Jehovah bin, wenn Ich euch auf Israels Boden hereingebracht, in das Land, das Meine Hand Ich erhob, zu geben euren Vätern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'Und allda werdet ihr gedenken eurer Wege und aller eurer Handlungen, durch die ihr euch verunreinigt habt, und euch selbst zum Verdruß geworden seid durch all eure Bosheiten, die ihr getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'Und ihr sollt wissen, daß Ich Jehovah bin, wenn Ich mit euch tue um Meines Namens willen, nicht nach euren bösen Wegen und euren verderblichen Handlungen, du Haus Israel, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'Und es geschah Jehovahs Wort an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Menschensohn, richte dein Angesicht gen Süden und träufle dem Südwinde zu und weissage über den Wald des Feldes im Mittage,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'Und sprich zum Wald im Mittag: Höre das Wort Jehovahs: So spricht der Herr Jehovah: Siehe, Ich entzünde in dir ein Feuer, und es soll in dir allen grünen Baum und allen dürren Baum auffressen, und soll die lohe Flamme nicht erlöschen, und sollen von ihr alle Flächen von Mittag nach Mitternacht verbrannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Und alles Fleisch soll sehen, daß Ich, Jehovah, es brennen lasse. Nicht soll es erlöschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'Und ich sprach: Ach, Herr Jehovah, sie sagen von mir: Führt er nicht Sprichwörter?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Und es geschah Jehovahs Wort zu mir, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'Menschensohn, richte dein Angesicht gen Jerusalem und laß träufeln gegen die Heiligtümer und weissage wider den Boden Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Und sprich zum Boden Israels: So spricht Jehovah: Siehe, Ich bin wider dich und ziehe Mein Schwert heraus aus seiner Scheide und rotte aus von dir den Gerechten und den Ungerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Weil Ich von dir ausrotte den Gerechten und den Ungerechten, darum geht heraus Mein Schwert aus seiner Scheide über alles Fleisch von Mittag bis gen Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Und alles Fleisch soll wissen, daß Ich, Jehovah, Mein Schwert aus seiner Scheide zog, es kehrt nimmer zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Und du, Menschensohn, seufze, daß die Lenden dir brechen, und seufze bitterlich vor ihren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Und es wird geschehen, daß sie zu dir sprechen: Warum seufzest du? Und du sollst sprechen: Ob dem Gerücht, das da kommt. Ein jeglich Herz wird zerschmelzen und alle Hände erschlaffen, aller Geist wird getrübt, und alle Knie gehen im Wasser. Siehe, es kommt und es geschieht, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Und es geschah zu mir das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Menschensohn, weissage und sprich: So spricht Jehovah: Sprich: Das Schwert, das Schwert! Geschärft und auch blank gemacht ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Zu schlachten eine Schlachtung, ist es geschärft; auf daß es werde zum Blitz, ist es blank gemacht. Oder sollen wir uns freuen? Die Rute meines Sohnes verschmäht jeglich Holz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Und er gab es zum Blankmachen, um es mit der Hand zu fassen. Es ist geschärft, das Schwert, und ist blank gemacht, um es zu geben in die Hand des Würgers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Schreie und heule, Menschensohn; denn es ist wider Mein Volk, es ist wider all die Fürsten Israels. Dem Schwert verfallen sind sie samt Meinem Volk, darum schlage an deine Hüfte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Denn es ist eine Prüfung. Und wozu? wenn auch die verschmähte Rute nicht mehr ist! spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'Du aber, Menschensohn, weissage und schlage Hand auf Hand. Zum drittenmal wiederhole sich das Schwert, das Schwert der Erschlagenen, es ist das Schwert der großen Erschlagung für sie in den Kammern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Auf daß das Herz zerfließe, und das Straucheln sich mehre, und Ich richte die Spitze des Schwertes wider alle ihre Tore, nur gemacht zum Blitze, zum Schlachten gewetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Einige dich, wende dich rechts, richte dich, wende dich links, wohin du dein Angesicht kehren magst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'Und auch Ich werde Hand auf Hand schlagen und zur Ruhe bringen Meinen Grimm. Ich, Jehovah, habe geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'Und es geschah Jehovahs Wort zu mir. Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Und du, Menschensohn, setze dir zwei Wege, auf denen das Schwert des Königs von Babel kommen soll. Aus einem Land sollen beide ausgehen; und schaffe einen Wegweiser. Am Anfang des Weges nach der Stadt sollst du ihn schaffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Den Weg sollst du setzen, daß das Schwert komme gen Rabbath der Söhne Ammons, und gen Jehudah in das befestigte Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'Denn Babels König steht an der Wegscheide still, am Anfang der zwei Wege, um sich wahrsagen zu lassen, er schüttelt die Pfeile, er fragt die Theraphim, besieht die Leber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Zu seiner Rechten ist die Wahrsagung Jerusalem, die Sturmböcke zu setzen, ein Loch zu öffnen, durch Zerstoßung die Stimme zu erhöhen im Feldgeschrei, die Sturmböcke zu setzen wider die Tore, aufzuschütten einen Wall, Bollwerk zu bauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Doch wie eitel Wahrsagerei ist es in ihren Augen, mit Schwüren ihnen beschworen. Und er läßt sie gedenken der Missetat, sie zu erfassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, 'Darum spricht also der Herr Jehovah: Weil er euch gedenken ließ an eure Missetat durch Aufdeckung eurer Übertretungen, euch eure Sünden sehen ließ in allen euren Handlungen, darum, daß er euch derselben gedenken ließ, sollt ihr mit der Hand erfaßt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Und du, Erschlagener, ungerechter Fürst Israels, dessen Tag kommt, zur Zeit der Missetat des Endes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'So spricht der Herr Jehovah: Nimm weg die Tiare, erhöhet die Krone! Das sei nicht so! Das Niedrige soll erhöht und das Hohe erniedrigt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Verdreht, verdreht, verdreht setze Ich sie; auch das soll nicht so sein, bis der kommt, der das Gericht hat, und dem Ich es gebe. Du aber, Menschensohn, weissage und sprich: So spricht der Herr Jehovah über die Söhne Ammons und über ihre Schmähung, und sprich: Schwert, Schwert, gezückt zum Schlachten, blank gemacht zum Verzehren, daß es zum Blitz sei. Als du dir Eitles schauen und dir Falsches wahrsagen ließest, um dich zu legen über die Hälse der Erschlagenen, der Ungerechten, deren Tag kommt zur Zeit der Missetat des Endes; Laß zurück es kehren in seine Scheide; am Ort, da du erschaffen wardst, im Lande deines Handels richte Ich dich, Und schütte Meinen Unwillen aus über dich, mit dem Feuer Meines Wütens hauche Ich dich an und gebe dich in die Hand brennender Männer, der Werkleute des Verderbens. Dem Feuer sollst du zur Speise werden. Dein Blut soll sein in des Landes Mitte. Nicht soll man deiner mehr gedenken; denn Ich, Jehovah, habe es geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Und es geschah Jehovahs Wort an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'Du aber, Menschensohn, willst du richten, willst du richten die Stadt des Blutes, und sie wissen lassen all ihre Greuel?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'Und sprich: So spricht der Herr Jehovah: Stadt, die in ihrer Mitte Blut vergossen, daß ihre Zeit komme, und Götzen für sich gemacht hat zu ihrer Verunreinigung,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Durch dein Blut, das du vergossen, bist du schuldig und hast durch die Götzen, die du machtest, dich verunreinigt, und hast nahen lassen deine Tage und bist zu deinen Jahren gekommen. Darum gebe Ich dich den Völkerschaften, zur Schmähung und zum Schimpf allen Landen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Die Nahen und die ferne von dir sind, beschimpfen dich, die du unrein von Namen, mit vielem Getümmel bist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Siehe, die Fürsten Israels sind jeder Mann nach seinem Arm in dir, Blut zu vergießen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Vater und Mutter achten sie gering in dir. Am Fremdling tun sie Erpressung in deiner Mitte. Waise und Witwe bedrücken sie in dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Meine Heiligtümer hast du verachtet und Meine Sabbathe entweiht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Zwischenträgerische Männer sind in dir, Blut zu vergießen; und auf den Bergen aßen sie in dir und taten Schandtat in deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'Man deckt die Blöße des Vaters auf, und sie schwächten die Unreine in ihrer Befleckung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'Und ein Mann tut Greuel mit des Genossen Weib. Und mit der Schnur verunreinigt sich der Mann durch Schandtat; der Mann schwächt seine Schwester, seines Vaters Tochter, in dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'Geschenk nehmen sie in dir, Blut zu vergießen. Wucher und Mehrung nimmst du und übervorteilst durch Erpressung deinen Nächsten, und vergessen Meiner, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Und siehe, Ich schlage Meine Hände zusammen über dem Geiz, den du übst und dem Blute, das in deiner Mitte ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Wird dein Herz bestehen, werden deine Hände stark sein in den Tagen, da Ich mit dir zu tun habe? Ich, Jehovah, habe es geredet und tue es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'Und werde dich zerstreuen unter die Völkerschaften und dich zersprengen in die Länder und mache zunichte deine Unreinheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'Und du sollst durch dich entweiht werden in den Augen der Völkerschaften, und sollst wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'Und es geschah an mich Jehovahs Wort, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Menschensohn, die vom Haus Israels sind Mir zu Schlacken geworden. Sie alle sind Erz und Zinn und Eisen und Blei mitten im Schmelzofen, Schlacken des Silbers sind sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Darum spricht also der Herr Jehovah: Weil ihr alle seid zu Schlacken geworden, darum, siehe, will Ich euch zusammenbringen inmitten Jerusalems,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'Ein Zusammenbringen von Silber und Erz und Eisen und Blei und Zinn inmitten des Schmelzofens, daß man ein Feuer dafür anbläst zum Schmelzen, also will auch Ich in Meinem Zorn und Meinem Grimm euch zusammenbringen und hineinlegen und schmelzen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Und euch zusammenfassen und mit dem Feuer Meines Wütens hinblasen über euch, daß ihr in seiner Mitte geschmolzen werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Gleichwie das Silber schmilzt in des Schmelzofens Mitte, so sollt ihr in seiner Mitte geschmolzen werden, und wissen, daß Ich, Jehovah, Meinen Grimm über euch ausgeschüttet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'Und es geschah zu mir Jehovahs Wort, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Menschensohn, sprich zu ihr: Du bist ein Land, das nicht gereinigt ist, nicht beregnet am Tage des Unwillens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Eine Verschwörung ihrer Propheten ist in ihrer Mitte, wie der brüllende Löwe, der das Zerfleischte zerfleischt, fressen sie die Seele, Gut und Kostbarkeit nehmen sie und machen in ihr viel der Witwen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Meinem Gesetze tun ihre Priester Gewalt an, und entweihen Meine Heiligtümer, zwischen Heiligem und Entweihtem scheiden sie nicht und tun nicht zu wissen, was rein und unrein ist, und vor Meinen Sabbathen verbergen sie die Augen, und Ich werde entweiht in ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Ihre Obersten sind in ihrer Mitte wie Wölfe, die das Zerfleischte zerfleischen, Blut zu vergießen, Seelen zu zerstören, daß sie Gewinn gewinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'Und ihre Propheten übertünchen ihnen Untaugliches, indem sie Eitles schauen und ihnen Falsches wahrsagen, sprechend: So spricht der Herr Jehovah, und Jehovah hat nicht geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Das Volk des Landes übt Erpressung und plündert aus, bedrückt den Elenden und Dürftigen und übt Erpressung an dem Fremdling wider Recht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'Und Ich suchte unter ihnen nach einem Mann, der den Zaun zäunete, der vor dem Durchbruch stünde vor Mir für das Land, daß Ich es nicht verderbete, und Ich fand keinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Darum schütte Meinen Unwillen Ich über sie aus, im Feuer Meines Wütens mache Ich sie alle, Ich gebe ihren Weg auf ihr Haupt, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Und es geschah das Wort Jehovahs zu mir, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Menschensohn, es waren zwei Weiber, Töchter einer Mutter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'Und sie buhlten in Ägypten, in ihrer Jugend buhlten sie, ließen dort drücken ihre Brüste, und sie betasteten die Zitzen ihrer Jungfrauschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Und dies sind ihre Namen: Oholah, die große, und ihre Schwester Oholibah; und sie wurden Mein, und gebaren Söhne und Töchter; und ihre Namen: Samaria ist Oholah, und Jerusalem Oholibah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'Und Oholah buhlte neben Mir, und es lüstete sie nach ihren Liebhabern, nach denen von Aschur, die nahe waren,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'Die sich in blauen Purpur kleideten, Statthalter und Landvögte, Jünglinge, allesamt begehrenswert, Reiter, die auf Rossen reiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'Und sie gab ihre Buhlereien über sie, die Auswahl der Söhne Aschurs allesamt, und verunreinigte sich mit allen, nach denen sie es lüstete, mit allen ihren Götzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Und ihre Buhlerei von Ägypten her verließ sie nicht, denn in ihrer Jugend lagen sie bei ihr, die Zitzen ihrer Jungfrauschaft betasteten sie, und ergossen ihre Buhlereien über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Darum gab Ich sie in ihrer Liebhaber Hand, in die Hand der Söhne Aschurs, nach denen sie es lüstete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Sie deckten ihre Blöße auf, sie nahmen ihre Söhne und ihre Töchter, sie aber erwürgten sie mit dem Schwerte, und ihr Name unter den Weibern, daß sie Gericht gehalten über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'Und ihre Schwester Oholibah, sah es, und ihre Wollust war verderblicher denn die ihrige, und ihre Buhlereien denn die Buhlereien ihrer Schwester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Sie lüstete nach Aschurs Söhnen, Statthaltern und Landvögten, die nahe waren, prächtig angetan, Reiter, die auf Rossen ritten, begehrenswerte Jünglinge allesamt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'Und Ich sah, daß sie sich verunreinigte, einen Weg für sie beide.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'Und sie tat hinzu zu ihren Buhlereien und sah Männer an die Wand gemalt, die Bilder der Chaldäer mit Mennigrot gemalt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'Umgürtet mit dem Gurt um ihre Lenden, mit überhängenden Turbanen auf ihren Häuptern, sie alle anzusehen wie Kriegshäuptlinge, nach der Ähnlichkeit der Söhne Babels, der Chaldäer, im Land ihrer Geburt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'Und sie lüstete nach ihnen nach den Ansehen ihrer Augen und sandte Boten zu ihnen nach Chaldäa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'Und zu ihr kamen Babels Söhne zum Liebeslager, und sie verunreinigten sie mit ihrer Buhlerei, und sie verunreinigte sich mit ihnen, bis ihre Seele sich von ihnen abneigte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'Und sie hatte ihre Buhlereien aufgedeckt und aufgedeckt ihre Blöße, und Meine Seele ward ihr abgeneigt, wie Meine Seele sich von ihrer Schwester abgeneigt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'Und sie mehrte ihre Buhlereien, daß an die Tage ihrer Jugend sie gedachte, da sie im Land Ägypten gebuhlt hatte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'Und sie lüstete nach ihren Kebsmännern, deren Fleisch das Fleisch der Esel und deren Erguß der Hengste Erguß ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Und du sahst dich nach deiner Jugend Unzucht um, da man in Ägypten deine Zitzen betastete, um deiner Jugend Brüste willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Darum, Oholibah, so spricht der Herr Jehovah, siehe, Ich errege deine Liebhaber wider dich, von denen deine Seele sich abgeneigt hatte, und bringe sie ringsum wider dich herbei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Die Söhne Babels und alle Chaldäer, Pekod und Schoa und Koa, alle Söhne Aschurs mit ihnen, begehrenswerte Jünglinge, Statthalter und Landvögte allesamt, Kriegshäuptlinge und Aufgerufene, reitend auf Rossen allzumal,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'Und sie kommen wider dich mit Rasseln der Streitwagen und Räder, und mit einer Versammlung von Völkern, sie richten Schild und Tartsche und Helm ringsumher wider dich, und vor sie gebe Ich das Gericht, daß sie dich nach ihren Rechten richten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'Und setze Meinen Eifer wider dich, daß sie mit dir tun im Grimm, dir Nase und Ohren abschneiden, und was noch von dir nachkommt, falle durch das Schwert. Sie sollen deine Söhne und Töchter nehmen, und was nachkommt von dir, [soll] vom Feuer gefressen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Sie sollen deine Kleider dir ausziehen und nehmen deines Schmuckes Geräte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'Und Ich lasse zu Ende kommen von dir deine Unzucht und deine Buhlerei vom Land Ägypten her, daß nimmer zu ihnen deine Augen du erhebst und Ägyptens nicht mehr gedenkst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Denn also spricht der Herr Jehovah: Siehe, Ich gebe dich in die Hand dessen, den du haßtest, in dessen Hand, von dem sich deine Seele abgeneigt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'Daß sie im Haß mit dir handeln, und dir all dein Erarbeitetes nehmen, und nackt und bloß dich lassen, daß die Blöße deiner Buhlereien und deine Unzucht und deine Buhlereien aufgedeckt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'Solches geschieht dir, weil du den Völkerschaften nachgebuhlt, daß mit ihren Götzen du dich verunreinigt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Auf deiner Schwester Weg bist du gegangen, und ihren Becher gebe Ich in deine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'So spricht der Herr Jehovah: Deiner Schwester Becher sollst du trinken, den tiefen und weiten, sollst zum Gelächter und Hohne werden - er fasset viel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Voll Trunkenheit und Grames sollst du werden: denn ein Becher der Verwüstung und Wüstenei ist der Becher deiner Schwester Schomron.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Und sollst ihn trinken und ausdrücken und seine Scherben zermalmen und dein Brüste damit zerreißen; denn Ich habe es geredet, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Darum spricht also der Herr Jehovah: Weil du Mein vergessen und hinter deinen Rücken Mich geworfen hast, so trage denn auch deine Unzucht und deine Buhlereien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Und Jehovah sprach zu mir: Menschensohn, willst du Oholah und Oholibah richten und ihnen ihre Greuel ansagen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Wie Ehebruch sie trieben und Blut an ihren Händen haben, und durch ihre Götzen sie die Ehe brachen, und auch ihre Söhne, die sie Mir geboren, ihnen zur Speise hindurchführten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Noch taten sie Mir dies: Mein Heiligtum verunreinigten sie an jenem Tage und entweihten Meine Sabbathe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Und damit, daß sie ihre Söhne ihren Götzen schlachteten, und an selbem Tage kamen in Mein Heiligtum, es zu entweihen. Und siehe, so taten sie inmitten Meines Hauses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Und sie sandten auch an Männer, die aus der Ferne kommen sollten, an die ein Bote ward gesandt, und siehe, sie kamen, du hast dich für sie gebadet, deine Augen geschminkt und mit deinem Geschmeide geschmückt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'Und saßest auf einem herrlichen Bette, und ein Tisch ward vor dir zugerichtet, und Mein Räuchwerk und Mein Öl setztest du darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'Und die Stimme einer achtlosen Menge war in ihr, und zu den Männern der Menge der Menschen wurden Sabäer aus der Wüste hereingebracht, und sie gaben Armbänder an ihre Hände und eine Krone des Schmuckes auf ihre Häupter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Und Ich sprach von der, so alt ist in Ehebrüchen: Nun buhlet sie ihre Buhlereien, auch sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'Und sie gingen zu ihr ein, wie man zu einem Weibe, einer Buhlerin eingeht. So gingen sie ein zu Oholah und Oholibah, den Weibern der Unzucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Und gerechte Männer, die werden sie richten nach dem Recht der Ehebrecherinnen, und nach dem Recht derer, so Blut vergießen; denn Ehebrecherinnen sind sie, und Blut ist an ihren Händen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Denn also spricht der Herr Jehovah: Ich bringe eine Versammlung wider sie herauf und gebe sie dem Grausen und dem Raube hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'Und die Versammlung - sie werden sie mit dem Steine steinigen, und mit ihren Schwertern sie niederhauen, ihre Söhne und ihre Töchter erwürgen, und mit Feuer ihre Häuser verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'Und so will Ich der Unzucht im Lande ein Ende machen, daß alle Weiber Zucht annehmen und nicht nach ihrer Unzucht tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'Und eure Unzucht soll man auf euch legen und die Sünden ob euren Götzen sollt ihr tragen, und wissen, daß Ich der Herr Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'Und es geschah Jehovahs Wort zu mir im neunten Jahr, im zehnten Monat, am zehnten des Monats, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Menschensohn, schreibe dir den Namen dieses Tages, diesen selben Tag an. An diesem selben Tag legt sich der König Babels an Jerusalem hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'Und sprich dem Haus der Widerspenstigkeit ein Sprichwort und sprich zu ihnen: Also spricht der Herr Jehovah: Setze den Topf zu, setze zu und gieße auch Wasser darein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Sammle die Stücke darein, jeglich gut Stück, Hüfte und Schulter, mit der Auswahl der Knochen fülle ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Die Auswahl vom Kleinvieh nimm und auch Feuerung von Knochen darunter. Siede seinen Sud. Laß auch seine Knochen in dessen Mitte kochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Darum spricht also der Herr Jehovah: Wehe der Stadt des Blutes. Ein Topf ist sie, in der dessen Schaum ist, und sein Schaum geht nicht davon heraus. Nimm Stück für Stück heraus. Laß nicht das Los darüber fallen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Denn ihr Blut ist in ihrer Mitte. Auf die dürre Felsenklippe hat sie es gelegt, nicht auf die Erde es geschüttet, um mit Staub es zuzudecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Um Grimm aufsteigen zu lassen, Rache zu rächen, ließ Ich ihr Blut auf die dürre Felsenklippe tun, daß es nicht werde zugedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Darum spricht also der Herr Jehovah: Wehe der Stadt des Blutes, Ich will auch die Feuerstätte groß machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Mache viel der Holzstücke, schüre das Feuer an, mache gar das Fleisch und würze die Würze, und laß die Knochen erglühen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Und laß ihn leer auf seinen Kohlen stehen, auf daß er heiß werde und sein Erz erglühe, und in seiner Mitte seine Unreinheit schmelze, und sein Schaum ganz aus sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Sie ermüdet mit Beschwerden, und sein vieler Schaum will nicht hinausgehen. In das Feuer mit seinem Schaum!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'In deiner Unreinheit ist Unzucht. Weil Ich dich wollte reinigen, und du nicht wolltest rein werden von deiner Unreinheit, sollst du nicht mehr rein werden, bis Mein Grimm wider dich ausruht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Ich, Jehovah, habe es geredet. Es kommt, und Ich tue es, und lasse nicht los, und schone nicht und lasse Mich es nicht gereuen. Nach deinen Wegen und nach deinen Handlungen richten sie dich; spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'Und es geschah Jehovahs Wort an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Menschensohn, siehe, Ich nehme von dir deiner Augen Begehr durch eine Seuche, und du sollst nicht klagen und nicht weinen, und soll dir keine Träne kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Jammere stille, über die Toten mache keine Trauer, binde deinen Kopfbund um auf dir, und lege deine Schuhe an deine Füße, und umhülle nicht den Bart und iß kein Brot der Männer!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'Und ich redete am Morgen zu dem Volk, und am Abend starb mein Weib, und am Morgen tat ich, wie mir geboten ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'Und das Volk sprach zu mir: Willst du uns nicht ansagen, was uns das ist, was du tust?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Und ich sprach zu ihnen: Jehovahs Wort geschah zu mir und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Sprich zu dem Hause Israel: So spricht der Herr Jehovah: Siehe, Ich lasse Mein Heiligtum entweihen, eurer Stärke Stolz und eurer Augen Begehr, und was eure Seele bemitleidet; und eure Söhne und eure Töchter, die ihr hinterlassen, sollen durch das Schwert fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Und ihr sollt tun, wie ich getan, sollt nicht umhüllen euren Bart, und sollt das Brot der Männer nicht essen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'Und euer Kopfbund sei auf euren Häuptern, und eure Schuhe an euren Füßen, ihr sollt nicht klagen und nicht weinen und sollt dahinschwinden ob euren Missetaten, und sollt grollen jeder Mann seinem Bruder;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Und soll Jecheskel euch zum Wahrzeichen sein; nach allem, was er tat, sollt ihr tun, wenn es kommt, daß ihr erkennt, daß Ich der Herr Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Und du, Menschensohn, wird nicht am Tage, da Ich von ihnen nehme ihre Stärke, die Freude ihrer Zierde, ihrer Augen Begehr und das, wonach sie die Seele erheben, ihre Söhne und ihre Töchter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'An jenem Tage wird ein Entkommener zu dir kommen, um es deine Ohren hören zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'An jenem Tage wird dein Mund sich öffnen mit dem Entkommenen, und du wirst reden und nicht mehr stumm sein, und wirst ihnen zum Wahrzeichen sein, daß sie wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'Und es geschah Jehovahs Wort zu mir, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Menschensohn, richte dein Angesicht wider die Söhne Ammons und weissage wider sie,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'Und sprich zu den Söhnen Ammons: Höret das Wort des Herrn Jehovah! So spricht der Herr Jehovah: Weil du Ha! gesagt über Mein Heiligtum, als es entweiht wurde, und über den Boden Israels, als er verwüstet ward, und über das Haus Jehudah, als es in die Verbannung ging;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'Darum, siehe, gebe Ich dich den Söhnen des Ostens zum Erbbesitz, daß ihre Gehöfte sie bei dir bewohnen, und ihre Wohnungen bei dir machen. Sie werden essen deine Frucht und sie werden trinken deine Milch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'Und Rabbah gebe Ich zum Wohnort für die Kamele, und die Söhne Ammons zum Lagerplatz des Kleinviehs, und wissen sollt ihr, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Denn also spricht der Herr Jehovah: Weil du in die Hand geklatscht und mit dem Fuße gestampft und mit aller Verhöhnung in der Seele über den Boden Israels fröhlich warst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'Darum, siehe, recke Ich Meine Hand aus über dich, und gebe dich zum Raub den Völkerschaften und rotte dich von den Völkern aus und zerstöre dich aus den Ländern und vernichte dich, daß du wissest, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'So spricht der Herr Jehovah: Weil Moab und Seir sprachen: Siehe, wie alle Völkerschaften ist das Haus Jehudah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'Darum, siehe, öffne Ich die Seite Moabs von den Städten her, von seinen Städten her von seinem Ende, die Zierde des Landes, Beth Jeschimoth, Baal Meon und Kirjathajim zu,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'Den Söhnen des Ostens, bei den Söhnen Ammons, und gebe sie zum Erbbesitz, damit man der Söhne Ammons nicht mehr gedenken soll unter den Völkerschafen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'Und über Moab übe Ich Gerichte, daß sie wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'So spricht der Herr Jehovah: Weil Edom es tat und mit Rache sich rächte am Hause Jehudah, und mit Schuld sich verschuldete und sich an ihnen rächte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'Darum, spricht also der Herr Jehovah, will Meine Hand Ich ausstrecken über Edom und von ihm ausrotten Mensch und Vieh, und es zur Öde machen, von Theman an, und bis nach Dedan; sie sollen fallen durch das Schwert;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'Und Meine Rache will Ich üben an Edom durch die Hand Meines Volkes Israel, so daß sie tun an Edom nach Meinem Zorn und nach Meinem Grimm. Und sie sollen erkennen Meine Rache, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'So spricht der Herr Jehovah: Dafür, daß die Philister mit Rache handelten und sich mit Rache rächten mit Verhöhnung in der Seele, sie zu verderben aus ewiger Feindschaft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'Darum, so spricht der Herr Jehovah: Siehe, Ich strecke Meine Hand aus über die Philister und rotte aus die Kerether und zerstöre den Überrest am Gestade des Meeres.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'Und Ich will große Rache üben wider sie im Grimme, daß sie wissen, daß Ich Jehovah bin, wenn Meine Rache Ich an ihnen übe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'Und es geschah im elften Jahr am ersten des Monats, da geschah Jehovahs Wort an mich, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Menschensohn! Weil Zor sprach über Jerusalem: Ha! zerbrochen ist die Tür der Völker. Nun wendet man sich herum zu mir. Ich werde voll, sie ist verödet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'Darum, so spricht der Herr Jehovah, siehe, Ich bin wider dich, Zor, und bringe viele Völkerschaften wider dich herauf, wie das Meer heraufbringt seine Wogen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'Daß sie verderben Zors Mauern und seine Türme niederreißen, und seinen Staub fege Ich von ihm weg, daß Ich es zur dürren Felsenklippe mache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Ein Platz zum Ausspreiten des Garnes soll es inmitten des Meeres sein; denn Ich habe es geredet, spricht der Herr Jehovah; und zum Raub soll es den Völkerschaften werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'Und seine Töchter auf dem Felde werden durch das Schwert erwürgt, und sie sollen wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Denn also spricht der Herr Jehovah: Siehe, Ich bringe wider Zor Nebuchadrezzar, den König Babels, von Norden her, den König der Könige mit Roß und mit Streitwagen und mit Reitern und einer Versammlung und viel Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'Deine Töchter wird er auf dem Felde mit dem Schwerte erwürgen, und mit Bollwerken dich umgeben, und einen Wall aufschütten wider dich, und Schilddächer aufrichten gegen dich,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'Und seines Brechers Stoß auf deine Mauern richten und deine Türme mit seinen Schwertern niederreißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Die Unzahl seiner Rosse wird dich mit ihrem Staub bedecken. Von der Stimme der Reiter und Räder und Streitwagen werden deine Mauern beben, sein Einzug in deinen Toren wird sein gleich den Einzügen in eine erstürmte Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'Mit seiner Rosse Hufen zerstampft er alle deine Gassen, erwürgt dein Volk mit dem Schwerte und deiner Stärke Denksäulen wird er zur Erde stürzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'Sie werden dein Vermögen erbeuten, und deine Waren rauben, und umreißen deine Mauern und niederreißen deine Häuser der Begehr, und deine Steine und dein Holz und deinen Staub mitten in das Wasser werfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'Und deiner Lieder Tosen lasse Ich zu Ende kommen, und deiner Harfen Stimme wird nicht mehr gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'Und Ich mache dich zur dürren Felsenklippe; zur Ausspreitung von Garben sollst du werden, sollst nicht mehr aufgebaut werden; denn Ich, Jehovah, habe geredet, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'So spricht der Herr Jehovah zu Zor: Beben nicht die Inseln vor dem Getöse deines Falles, vom Jammern der Durchstochenen, vom Würgen der in dir Erwürgten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Und alle Fürsten des Meeres steigen herab von ihren Thronen, und tun ihre Oberkleider weg, und ziehen ihre gewirkten Kleider aus, ziehen an das Erzittern, sitzen auf der Erde, und erzittern jeden Augenblick und erstaunen über dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'Und erheben ein Klagelied über dich und sprechen zu dir: Wie bist du zerstört, die du in den Meeren wohntest; die gelobte Stadt, die stark war im Meere, sie und ihre Bewohner, die bei allen, so daran wohnten, Schrecken verbreitete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Nun erzittern die Inseln am Tage deines Falls, und bestürzt sind die Eilande im Meer ob deinem Ausgange.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Denn also spricht der Herr Jehovah: Wenn Ich dich habe gemacht zu einer verödeten Stadt, wie die Städte, die nicht bewohnt werden, wenn Ich den Abgrund über dich heraufgebracht, und dich die vielen Wasser bedeckt haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'Und Ich hinab dich fahren lasse mit denen, die in die Grube hinabfahren zu der Urzeit Volk, und dich im Land der Unteren habe wohnen lassen, in den ewigen Öden mit denen, die in die Grube hinabfahren, so daß du nicht bewohnt wirst. Und Ich gebe eine Zierde im Lande der Lebendigen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'Aber zur Schrecknis will Ich dich machen, daß du nicht mehr seiest. Daß man dich sucht und du nicht mehr gefunden werdest ewiglich, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Und es geschah zu mir Jehovahs Wort, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Du aber, Menschensohn, erhebe ein Klagelied über Zor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'Und sprich zu Zor: Du, die du wohnst an den Zugängen des Meeres, Händlerin der Völker nach den vielen Inseln, also spricht der Herr Jehovah: Zor, du sprichst: Ich bin die Vollendung der Schönheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Im Herzen der Meere sind deine Grenzen; deine Bauleute haben vollendet deine Schönheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Aus Senirs Tannen bauten sie dir all dein Tafelwerk. Die Zeder nahmen sie vom Libanon, Masten auf dir zu machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'Aus Eichen von Baschan machten sie deine Ruder; aus Elfenbein machten sie die Ruderbank, die Tochter des Schreitens aus den Inseln Chittims.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Byssus, buntgewirkt aus Ägypten, war dein Segel, dir ein Panier zu sein, blau und roter Purpur aus Elischahs Inseln war deine Zeltdecke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Die, so in Zidon und in Arvad wohnen, sie waren deine Ruderer; deine Weisen, o Tyrus, waren in dir, sie waren deine Steuerleute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'Gebals Älteste und seine Weisen waren in dir, zu bessern deinen Leck. Alle Schiffe des Meeres und ihre Seeleute waren in dir, daß sie verkehrten in deinem Verkehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Paras und Lud und Put waren in deiner Streitmacht, Männer deines Streites, sie hingen auf in dir Tartsche und Helm, sie gaben dir deine Ehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Die Söhne Arvads und deine eigene Streitmacht waren auf deinen Mauern ringsumher, und die Gamader waren in deinen Türmen. Sie hängten ihre Schilde ringsum an deinen Mauern auf, sie vollendeten deine Schönheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tharschisch handelte mit dir mit aller Güter Menge, und gaben in deinen Markt Silber, Eisen, Zinn und Blei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Thubal und Meschech waren deine Kaufleute und gaben Menschenseelen und eherne Gefäße in deinen Verkehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Von Beththogarmah gaben sie Rosse und Reiter und Maultiere in deinen Markt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Die Söhne Dedans waren deine Kaufleute; in viele Inseln ging der Handel deiner Hand: Hörner, Elfenbein und Ebenholz gaben sie dir zurück als deine Gegengabe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Aram handelte mit dir um die Menge deiner Werke; Chrysopras, Purpur und buntgewirkten Zeug und Byssus und Korallen und Karfunkeln gaben sie in deine Märkte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Jehudah und das Land Israel waren deine Kaufleute, Weizen von Minnith, und Pannag und Honig und Öl und Balsam geben sie in deinen Verkehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damaskus handelte mit dir in der Menge deiner Werke um eine Menge aller Güter, um Wein von Chelbon und um Wolle von Zachar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Und Dan und Javan von Usal gaben auf deinen Markt verarbeitet Eisen, Kassia und Kalmus war in deinem Verkehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan war dein Kaufmann mit Decken zum Ausbreiten für den Wagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabien und alle Fürsten Kedars waren Händler dir zur Hand in Lämmern und Widdern und Böcken; in diesen waren sie deine Händler.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Die von Scheba und Raamah, sie waren deine Kaufleute mit den Erstlingen alles Gewürzes, und mit allen kostbaren Steinen, und Gold gaben sie dir für deinen Markt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Charan und Channeh und Eden, die Kaufleute Schebas; Aschur und Chilmad waren deine Kaufleute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Sie waren deine Kaufleute in dem Vollkommensten in Ballen von purpurblauen und gestickten Zeugen und in Schätzen von Prachtgewändern, mit Stricken umbunden; und Zedernholz war in deinem Handel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Die Tharschischschiffe waren deine Karawanen für deinen Verkehr, und du wurdest angefüllt und sehr verherrlicht im Herzen der Meere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'In viele Wasser brachten deine Ruderer dich: der Wind vom Osten hat dich im Herzen der Meere zerbrochen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Dein Gut und dein Markt, dein Verkehr, deine Seeleute und deine Steuerleute, die, so deine Lecke bessern, die so in deinem Verkehr verkehren, und alle Männer deines Streites, die in dir sind, und in all deiner Versammlung, die in deiner Mitte ist, sie werden fallen in der Meere Herz am Tage deines Falles.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Ob der Stimme des Geschreis deiner Steuerleute beben die Vorstädte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'Und alle, die das Ruder fassen, steigen herab aus ihren Schiffen, die Seeleute, alle die Steuerleute des Meeres stehen auf dem Land;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'Und lassen ihre Stimme hören über dich und schreien bitterlich, und bringen Staub herauf auf ihre Häupter; sie wälzen sich umher in der Asche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Und scheren sich kahl über dir und gürten sich mit Säcken, und weinen über dich in Bitterkeit der Seele bittere Klage;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'Und werden über dich ihr Trauerlied erheben, ein Klagelied, und über dich ein Klagelied anstimmen: Wer war wie Zor, verstört inmitten des Meeres!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Als dein Handel hervorging aus den Meeren, sättigtest du viele Völker; mit der Menge deiner Güter und deines Verkehrs bereichertest du die Könige der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Nun du zerbrochen bist von den Meeren in der Wasser Tiefen, fällt dahin dein Verkehr und all deine Versammlung in deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'Alle, so auf den Inseln wohnen erstaunen über dir, und ihre Könige schaudern mit Schauder, ihre Gesichter sind verstört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Die Händler unter den Völkern zischen über dich, daß du bist zur Bestürzung geworden, und bist nichts in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'Und es geschah Jehovahs Wort zu mir, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Menschensohn, sprich zum Führer Zors: So spricht der Herr Jehovah: Weil dein Herz hoffärtig ist geworden, und du sprichst: Ein Gott bin ich, auf dem Sitze Gottes sitze ich, im Herzen der Meere. Und du bist ein Mensch und kein Gott, und hast dein Herz wie Gottes Herz gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'Siehe, weise bist du, mehr denn Daniel, und kein Geheimnis ist vor dir verdeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'Durch deine Weisheit und deine Einsicht hast du Vermögen dir gemacht, und hast Gold und Silber in deine Schatzkammern geschafft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'Durch deine viele Weisheit hast du in deinem Handel dein Vermögen gemehrt, und durch dein Vermögen ist hoch dein Herz geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'Darum spricht so der Herr Jehovah: Weil du dein Herz wie Gottes Herz gemacht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'Darum, siehe, bringe Ich Fremde über dich, die Trotzigen der Völkerschaften. Die sollen ihre Schwerter ziehen wider die Schöne deiner Weisheit und deinen Strahlenglanz entweihen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'Zur Grube bringen sie dich hinab, so daß du stirbst den Tod der Erschlagenen im Herzen der Meere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Wirst du Angesichts deiner Würger sprechen: Ich bin Gott, da du doch Mensch bist und kein Gott in der Hand derer, die dich erschlagen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Den Tod der Unbeschnittenen wirst du sterben von der Hand der Fremden; denn Ich habe es geredet, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Und es geschah Jehovahs Wort zu mir, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Du, Menschensohn, erhebe ein Klagelied über den König Zors und sprich zu ihm: So spricht der Herr Jehovah: Besiegelnd das Ebenmaß, voller Weisheit warst du und vollkommen von Schönheit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'In Eden, dem Garten Gottes, warst du, jeglicher kostbare Stein war deine Bedeckung, Rubin, Topas, Diamant, Tharschisch, Schoham und Jaspis, Saphir, Chrysopras und Smaragd und Gold, das Werk deiner Pauken und deiner Pfeifen war in dir; am Tage, da du geschaffen wardst, wurden sie bereitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Du warst ein Cherub, die Ausdehnung des Deckenden, und Ich setzte dich, du warst auf dem Berg der Heiligkeit Gottes, inmitten der Steine des Feuers bist du gewandelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Untadelig warst du in deinen Wegen vom Tage an, da du geschaffen wardst, bis Verkehrtheit in dir gefunden ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Durch deinen vielen Handel ist deine Mitte voll von Gewalttat geworden, und du sündigtest, und Ich entweihe dich, weg vom Berge Gottes, und zerstöre dich, deckender Cherub, aus der Mitte der Steine des Feuers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Ob deiner Schönheit ward dein Herz hoffärtig, hast verdorben deine Weisheit ob deinem Strahlenglanz. Zur Erde werfe Ich dich herab, gebe dich hin vor den Königen, daß sie auf dich sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Ob deiner vielen Missetaten, ob der Verkehrtheit deines Handels hast du entweiht deine Heiligtümer. Und Ich lasse Feuer aus deiner Mitte ausgehen, daß es dich auffresse, und mache dich zur Asche auf der Erde vor den Augen aller, die dich sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Alle, die dich kennen unter den Völkern, erstaunen ob dir; zu Schrecknissen bist du geworden und bist nicht mehr in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'Und es geschah Jehovahs Wort an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Menschensohn, richte dein Angesicht wider Zidon und weissage wider dasselbe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'Und sprich: So spricht der Herr Jehovah: Siehe, Ich bin wider dich, Zidon, und will Mich in deiner Mitte verherrlichen, auf daß sie wissen, daß Ich Jehovah bin, wenn Ich Gerichte in ihm tue, und in ihm geheiligt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'Und Ich sende Pest darein, und Blut in seine Gassen, daß in seiner Mitte falle der Erschlagene durch das Schwert, das wider dasselbe ist von ringsumher, damit sie wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Und soll nicht mehr für das Haus Israel ein stechender Stachel sein und ein schmerzender Dorn von allen ihren Umgebungen, die sie verhöhnen, und sie sollen wissen, daß Ich der Herr Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'So spricht der Herr Jehovah: Wenn Ich das Haus Israel zusammenbringe aus den Völkern, unter die sie zerstreut worden, und Mich heilige in ihnen vor den Augen der Völkerschaften, dann sollen sie auf ihrem Boden wohnen, den Ich Meinem Knecht, dem Jakob, gegeben hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'Und sie sollen sicher darauf wohnen und Häuser bauen und Weinberge pflanzen, und sicher sollen sie wohnen, wenn Ich Gerichte halte über alle die, so sie verhöhnen ringsumher, und sie sollen wissen, daß Ich, Jehovah, bin ihr Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'Im zehnten Jahr, im zehnten, am zwölften des Monats, geschah an mich das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Menschensohn, richte dein Angesicht wider Pharao, Ägyptens König, und weissage wider ihn und wider ganz Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'Rede und sprich: So spricht der Herr Jehovah: Siehe, Ich bin wider dich, Pharao, Ägyptens König, du großes Ungetüm, das inmitten seiner Ströme sich lagert, das spricht: Mein Strom ist es, und ich habe mich gemacht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'Und Ich lege Haken in deine Kinnbacken und lasse die Fische deiner Ströme an deinen Schuppen haften und ziehe dich herauf aus deiner Ströme Mitte, und alle Fische deiner Ströme, die an deinen Schuppen haften,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'Und gebe dich dahin in die Wüste, dich und alle Fische deiner Ströme; auf des Feldes Oberfläche sollst du fallen, nicht gesammelt noch zusammengebracht werden, dem wilden Tiere des Landes und dem Gevögel der Himmel gebe Ich dich zur Speise.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'Und alle, die in Ägypten wohnen, sollen wissen, daß Ich Jehovah bin, weil sie eine Stütze von Rohr waren dem Hause Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Wenn sie dich faßten mit der Hand, ward er zerquetscht und durchstachst ihnen die ganze Schulter; und wenn sie sich auf dich stützten, brachst du und machtest alle die Lenden stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Darum spricht der Herr Jehovah also: Siehe, Ich bringe über dich das Schwert, und Ich rotte aus von dir Mensch und Vieh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'Und das Land Ägypten wird zur Verwüstung und Öde werden, auf daß sie wissen, daß Ich Jehovah bin, weil es sprach: Mein ist der Strom, und Ich habe ihn gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'Darum, siehe, bin Ich wider dich und wider deine Ströme, und will das Land Ägypten zur Öde der Verwüstung machen von dem Turme von Seveneh und bis zur Grenze Kusch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Nicht durch dasselbe soll hingehen eines Menschen Fuß und nicht dadurch hingehen des Viehes Fuß, und nicht soll man darin wohnen vierzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'Und Ich mache das Land Ägypten zur Verwüstung mitten unter verwüsteten Ländern, und seine Städte sollen vierzig Jahre eine Verwüstung mitten unter verödeten Städten sein, und Ich will die Ägypter unter die Völkerschaften zerstreuen und sie versprengen in die Länder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Denn also spricht der Herr Jehovah: Vom Ende von vierzig Jahren will Ich Ägypten zusammenbringen aus den Völkern, dahin sie zerstreut worden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'Und Ich will die Gefangenschaft Ägyptens zurückbringen und sie zurückbringen in das Land Pathros, in das Land ihres Handels, und sie sollen ein niedriges Königreich sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'Es soll niedriger sein denn die Königreiche und sich nicht mehr erheben über die Völkerschaften; und Ich werde ihrer wenig machen, daß sie nicht mehr beherrschen die Völkerschaften;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'Und es soll dem Hause Israel nicht mehr zum Vertrauen sein, erinnernd an die Missetat, daß sie sich nach ihnen wandten. Und wissen sollen sie, daß Ich der Herr Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'Und es geschah im siebenundzwanzigsten Jahr, im ersten am ersten des Monats, daß Jehovahs Wort an mich geschah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Menschensohn, Nebuchadrezzar, Babels König, läßt seine Streitmacht wider Zor einen großen Dienst dienen, ein jeglich Haupt ward kahl gemacht, und jegliche Schulter abgerieben, und ihm und seiner Streitmacht wird kein Lohn von Zor für den Dienst, den wider dasselbe er gedient hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Darum spricht so der Herr Jehovah: Siehe, Ich gebe Nebuchadrezzar, Babels König, das Land Ägypten, daß seine Volks- menge er wegnehme und erbeute dessen Beute und raube dessen Raub, und es der Lohn sei seiner Heeresmacht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'Für seine Arbeit, mit der er gedient, gebe Ich ihm das Land Ägypten, weil sie es für Mich getan, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'An jenem Tage lasse Ich sprossen ein Horn dem Hause Israel, und gebe dir das Öffnen des Mundes inmitten ihrer, und sie sollen wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'Und es geschah Jehovahs Wort zu mir, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Menschensohn, weissage und sprich: So spricht der Herr Jehovah: Heulet, wehe dem Tag!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Denn nahe ist der Tag, und nahe ist der Tag Jehovahs, ein Tag der Wolke, eine Zeit der Völkerschaften wird es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'Und kommen wird das Schwert nach Ägypten, und in Kusch wird Pein sein, wenn der Erschlagene in Ägypten fällt, und seine Volksmenge sie fortnehmen und seine Grundfesten umreißen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Kusch und Put und Lud, und ganz Ereb und Chub und die Söhne des Landes des Bundes, mit ihnen fallen sie durch das Schwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'So spricht Jehovah: Und es werden fallen, die für Ägypten ein Anhalt waren, und seiner Stärke Stolz wird hinabsinken. Vom Turme von Seveneh werden sie darin fallen durch das Schwert, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'Und sie werden verwüstet sein inmitten der verwüsteten Länder, und ihre Städte werden inmitten der verödeten Städte sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'Und sie werden wissen, daß Ich Jehovah bin, wenn Feuer Ich gebe in Ägypten, und alle, die ihm beistanden, zerbrochen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'An jenem Tage werden Boten von Meinem Angesicht ausgehen auf Fahrzeugen, Kusch, das sichere, aufzuscheuchen, und Pein wird unter ihnen sein, wie an dem Tag Ägyptens, denn siehe, es kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'So spricht der Herr Jehovah: Und ein Ende mache Ich mit der Volksmenge Ägyptens durch die Hand Nebuchadrezzars, des Königs von Babel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'Er und sein Volk mit ihm, die Trotzigen der Völkerschaften, werden hereingebracht, das Land zu verderben, und ziehen ihre Schwerter gegen die Ägypter und füllen mit Erschlagenen das Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'Und Ich lasse die Ströme vertrocknen, und das Land verkaufe Ich in die Hand der Bösen und verwüste das Land und seine Fülle durch die Hand der Fremden. Ich, Jehovah, habe geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'So spricht der Herr Jehovah: Und Ich zerstöre die Götzen und mache ein Ende mit den Abgöttern aus Noph, und ein Fürst wird nicht mehr sein vom Lande Ägypten, und Ich gebe Furcht im Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'Und will Pathros verwüsten und Feuer in Zoan geben und über No Gerichte halten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'Und Meinen Grimm ausschütten über Sin, Ägyptens Stärke, und ausrotten die Volksmenge No,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'Und Feuer gebe Ich in Ägypten, krei-ßend soll Sin kreißen, und No zum Durchbruch kommen, und Noph am Tage bedrängt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Avens und Pibeseths Jünglinge fallen durch das Schwert, und siehe! sie gehen in Gefangenschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'Und in Techaphneches verfinstert sich der Tag, wenn Ich dort breche die Jochhölzer Ägyptens und seiner Stärke Stolz zu Ende kommt; eine Wolke bedeckt dasselbe, und seine Töchter gehen in Gefangenschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'Und Ich halte Gerichte in Ägypten, und sie werden wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'Und es geschah im elften Jahr am siebenten des ersten Monats, daß Jehovahs Wort an mich geschah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Menschensohn, den Arm Pharaos, des Königs von Ägypten, werde Ich zerbrechen, und siehe, er wird nicht verbunden ihm Heilung zu geben, man legt keinen Verband auf, daß er verbunden werde und erstarke, um das Schwert zu erfassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Darum, so spricht der Herr Jehovah, siehe, Ich bin wider Pharao, Ägyptens König, daß Ich seine Arme zerbreche, den starken und den gebrochenen, und lasse ihm das Schwert aus seiner Hand fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'Und will die Ägypter unter die Völkerschaften zerstreuen und sie zersprengen in die Länder,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'Und Ich will stärken die Arme des Königs von Babel und geben Mein Schwert in seine Hand, und zerbrechen die Arme Pharaos, daß er stöhne vor ihm das Stöhnen des Durchbohrten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'Und Ich will stärken die Arme des Königs von Babel, und die Arme Pharaos sollen sinken, daß sie wissen, daß Ich Jehovah bin, wenn Ich Mein Schwert dem König von Babel in seine Hand gebe, daß er es über Ägyptenland ausstrecke,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'Und Ich zerstreue die Ägypter unter die Völkerschaften und zersprenge sie in die Länder, auf daß sie wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'Und es geschah im elften Jahr am ersten des dritten Monats, daß das Wort Jehovahs an mich geschah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Menschensohn, sprich zu Pharao, dem Könige Ägyptens, und zu seiner Volksmenge: Wem gleichst du in deiner Größe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Siehe, Aschur war eine Zeder auf dem Libanon, schön von Ästen und schattigem Laubwerk und hoch von Wuchs, und zwischen dichten Zweigen war sein Wipfel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Wasser machten sie groß, der Abgrund ließ sie sich emporheben, daß er mit seinen Flüssen rings um ihre Pflanzung ging und ihre Kanäle zu allen Bäumen des Feldes sandte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Darum ward hoch ihr Wuchs vor allen Bäumen des Feldes und ihres Gezweiges wurde viel und ihre Zweige lang von den vielen Wassern, als sie sie aussandte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Auf ihrem Gezweige nistete alles Gevögel des Himmels, und unter ihren Zweigen gebar alles wilde Tier des Feldes, und unter ihrem Schatten saßen all die vielen Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'Und sie war schön in ihrer Größe, mit ihren langen Schossen; denn ihre Wurzel war an vielen Wassern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Die Zedern mochten sie nicht verdecken im Garten Gottes, die Tannen waren ihr nicht zu gleichen mit ihrem Gezweige, und Platanen waren nicht wie ihre Zweige. Kein Baum im Garten Gottes war ihr an Schönheit gleich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Schön hatte Ich sie gemacht in ihrer Schosse Menge, und alle Bäume Edens im Garten Gottes beneideten dieselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Darum, so spricht der Herr Jehovah: Weil sie hoch war an Wuchs und ihr Wipfel zwischen den dichten Zweigen war, und ihr Herz ob ihrer Höhe sich emporhob,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'So gebe Ich ihn in die Hand des Starken der Völkerschaften; er wird es an ihm tun, und ob seiner Ungerechtigkeit treibe Ich ihn fort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'Und Fremde rotten sie aus, die Gewaltigen der Völkerschaften, und lassen sie fahren. Auf die Berge und in alle Schluchten fallen ihre Schosse und ihre Zweige zerbrechen in allen Flußbetten des Landes; und alle Völker der Erde zogen herab aus ihrem Schatten und ließen sie fahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'Auf seinem umgefallenen Stamme wohnt alles Gevögel der Himmel, und auf seinen Zweigen war alles wilde Tier des Feldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'Auf daß nicht hoffärtig seien in ihrem Wuchse alle Bäume der Wasser, und ihren Wipfel nicht zwischen den dichten Gezweigen erheben, und nicht zu ihnen stehen wegen ihrer Höhe alle, die da Wasser trinken; denn sie alle werden dem Tode gegeben in die untere Erde inmitten der Menschensöhne, zu denen, die in die Grube hinabfahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'So spricht der Herr Jehovah: Am Tage, da er in die Hölle hinunterfährt, lasse Ich trauern, lasse Ich sich bedecken über ihn den Abgrund, und halte ab seine Flüsse, daß den vielen Wassern gewehrt werde, und lasse sich verdunkeln über ihm den Libanon, und alle Bäume des Feldes um ihn schmachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Vor dem Getöse seines Falls lasse Ich die Völkerschaften erbeben, wenn Ich ihn in die Hölle fahren lasse mit denen, die zur Grube hinabfahren, und in der unteren Erde trösten sich alle Bäume Edens, das Auserwählte und das Beste des Libanon, alle, die Wasser trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Auch sie fahren mit ihm hinab zur Hölle, zu den durch das Schwert Erschlagenen, die als sein Arm gesessen in seinem Schatten inmitten der Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Wem gleichst du also an Herrlichkeit und Größe unter den Bäumen Edens, und hinabgestoßen wirst du mit den Bäumen Edens zur unteren Erde; inmitten der Unbeschnittenen liegst du mit den durch das Schwert Erschlagenen, das ist Pharao und alle seine Volksmenge, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'Und es geschah im zwölften Jahr, im zwölften Monat, am ersten des Monats, daß Jehovahs Wort an mich geschah. Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Menschensohn, erhebe ein Klagelied über Pharao, Ägyptens König, und sprich zu ihm: Dem jungen Löwen der Völkerschaften glichest du und bist wie der Walfisch in den Meeren und brichst hervor mit deinen Flüssen und trübst mit deinen Füßen die Wasser und störst auf deine Flüsse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'So spricht der Herr Jehovah: Und Ich habe Mein Garn über dich ausgebreitet mit einer Versammlung vieler Völker, daß sie in Meinem Garn dich heraufziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'Ich werde dich auf das Land hinstoßen und auf die Angesichte des Feldes hinschleudern, und lasse alles Gevögel des Himmels auf dir hausen und das wilde Tier der ganzen Erde von dir sich sättigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'Und will dein Fleisch geben auf die Berge, und mit deiner Höhe die Schluchten füllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'Und tränken will Ich das Land mit deinem Ausfluß von deinem Blut bis an die Berge hin, und die Flußbette sollen voll von dir werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'Und Ich bedecke, wenn Ich dich auslösche, die Himmel und verdunkle ihre Sterne; die Sonne bedecke Ich mit einer Wolke, und der Mond soll sein Licht nicht leuchten lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Alle Leuchten des Lichtes am Himmel will Ich verdunkeln über dir und Finsternis bringen über dein Land, spricht der Herr Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'Und will reizen vieler Völker Herz, wenn Ich dein Zerbrechen hereinbringe unter die Völkerschaften, über Länder, die du nicht gekannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'Und Ich mache, daß viele Völker über dir erstaunen und ihren Königen das Haar sich sträubt über dir, wenn Ich Mein Schwert vor ihrem Angesichte umherschwinge, daß jeder Mann in Augenblicken für seine Seele erzittert am Tage deines Falls.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Denn so spricht der Herr Jehovah: Das Schwert des Königs von Babel soll an dich kommen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Mit den Schwertern der Helden bringe Ich deine Volksmenge zu Fall, die Gewaltigen der Völkerschaften allesamt, und sie sollen den Stolz Ägyptens verheeren und vernichten all seine Volksmenge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Und Ich zerstöre all sein Vieh an vielen Wassern; und nicht mehr trüben soll sie eines Menschen Fuß und nicht sie trüben die Klaue des Viehs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Dann lasse Ich ihre Wasser hinabsinken und ihre Flüsse dahinfließen wie Öl, spricht der Herr Jehovah:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Wenn Ich das Land Ägypten zur Verwüstung gemacht, und das Land von seiner Fülle verwüstet, wenn Ich geschlagen habe alle, so in ihm wohnen, und sie wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'Ein Klagelied ist es, und ein Klagelied sollen anstimmen die Töchter der Völkerschaften, sie sollen es anstimmen; über Ägypten und über alle seine Volksmenge sollen sie solches anstimmen, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'Und es geschah im zwölften Jahr, am fünfzehnten Tag des Monats, daß das Wort Jehovahs an mich geschah. Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Menschensohn, wehklage über die Volksmenge Ägyptens und laß sie hinabfahren, sie und die Töchter stattlicher Völkerschaften zur Erde der Unteren, mit denen, die in die Grube hinabfahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Wem gehst du vor an Lieblichkeit? Fahre hinab und lege dich zu den Unbeschnittenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Sie werden fallen mitten unter die durch das Schwert Erschlagenen. Das Schwert ist gegeben, sie ziehen sie hin mit all ihrer Volksmenge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Es werden zu ihm reden die Starken der Mächtigen aus der Mitte der Hölle mit denen, die ihm beistanden. Sie sind hinabgefahren, sie liegen da, die Unbeschnittenen, die vom Schwert Erschlagenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Da ist Aschur und all seine Versammlung, rings um ihn her sind seine Gräber; sie alle sind erschlagen, die durch das Schwert Gefallenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Denn Gräber sind gegeben an den Seiten der Grube, und seine Versammlung ist rings um sein Grab, sie alle durchbohrt, gefallen durch das Schwert, die Entsetzen verbreiteten im Lande der Lebendigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Dort ist Elam und all seine Volksmenge rings um sein Grab, sie alle sind erschlagen, durch das Schwert gefallen, die unbeschnitten in das Land der unteren Orte sind hinabgefahren, sie, die Entsetzen verbreiteten im Lande der Lebendigen, und tragen ihre Schande bei denen, die in die Grube hinabgefahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Ein Lager gab man ihm mit seiner ganzen Volksmenge, inmitten der Erschlagenen; rings um ihn her sind seine Gräber. Sie alle sind unbeschnitten, erschlagen mit dem Schwert, die Entsetzen verbreiteten im Lande der Lebendigen. Und sie tragen ihre Schande bei denen, die in die Grube hinabfahren. Inmitten der Erschlagenen wurde er gelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Da ist Meschech, Thubal und all seine Volksmenge, um ihn her sind seine Gräber. Sie alle sind Unbeschnittene, mit dem Schwert durchbohrt, weil sie ihr Entsetzen verbreiteten im Lande der Lebendigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'Aber sie sollen nicht liegen mit den Mächtigen, die von den Unbeschnittenen gefallen sind, die in die Hölle hinabgefahren in ihrer Kriegsrüstung, und denen sie ihre Schwerter unter ihre Häupter gegeben; und ihre Missetaten waren auf ihren Gebeinen; denn ein Entsetzen waren die Mächtigen im Lande der Lebendigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Und du wirst inmitten der Unbeschnittenen zerbrochen werden, und liegen mit den durch das Schwert Erschlagenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Da ist Edom! Seine Könige und all seine Fürsten wurden in ihrem Heldentum zu den durch das Schwert Erschlagenen gelegt; sie sollen liegen bei den Unbeschnittenen und bei denen, die in die Grube hinabfahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Dort die Gebieter von Mitternacht allesamt und jeder Sidonier, die mit den Erschlagenen hinabgefahren sind, in ihrem Entsetzen wegen ihres Heldentums schämen sie sich; und die Unbeschnittenen liegen mit den Erschlagenen durch das Schwert, und tragen ihre Schande mit denen, die zur Grube hinabfahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Diese wird Pharao sehen und sich trösten über alle seine Volksmenge, die durch das Schwert Erschlagenen, Pharao und seine ganze Streitmacht, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Denn Mein Entsetzen gebe Ich in dem Land der Lebendigen; er aber wird gelegt inmitten der Unbeschnittenen, bei den durch das Schwert Erschlagenen, Pharao und alle seine Volksmenge, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'Und es geschah zu mir das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Menschensohn, rede zu den Söhnen deines Volkes und sprich zu ihnen: Wenn Ich das Schwert über ein Land bringe, und das Volk des Landes nimmt einen Mann von seinen Enden und bestellt sich ihn zum Wächter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'Und er sieht das Schwert kommen über das Land, und stößt in die Posaune und warnt das Volk;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'Und so der Hörer hört den Schall der Posaune und läßt sich nicht warnen, und das Schwert kommt und nimmt ihn weg, dessen Blut sei auf seinem Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Er hat den Schall der Posaune gehört und sich nicht warnen lassen, sein Blut sei auf ihm. Wer sich aber warnen läßt, der rettet seine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Wenn aber der Wächter das Schwert sieht kommen und nicht in die Posaune stößt, und das Volk wird nicht gewarnt, und das Schwert kommt und nimmt von ihnen eine Seele weg, so wird dieser weggenommen in seiner Missetat; aber sein Blut werde Ich fordern von des Wächters Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Und dich, Menschensohn, habe Ich zum Wächter über das Haus Israel gegeben, daß du aus Meinem Munde hörst das Wort und sie von Mir aus warnst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Wenn Ich nun zu dem Ungerechten sage: Du, Ungerechter, sollst des Todes sterben -und du redest es nicht, daß du den Ungerechten warnst vor seinem Wege; so stirbt der Ungerechte in seiner Missetat, von deiner Hand aber fordere Ich sein Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Hast du aber den Ungerechten vor seinem Wege gewarnt, daß er davon zurückkehre, und er kehrt nicht zurück von seinem Weg, so muß er sterben in seiner Missetat, du aber errettest deine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Und du, Menschensohn, sprich zu dem Hause Israel: Also sprechet ihr sagend: Ja, unsere Übertretungen und unsere Sünden sind auf uns, daß wir darin dahinschwinden; und wie sollen wir leben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Sprich du zu ihnen: Bei Meinem Leben, spricht der Herr Jehovah: Ich habe keine Lust am Tode des Ungerechten, sondern daß der Ungerechte zurückkehre von seinem Weg und lebe. Kehrt zurück, kehrt zurück von euren bösen Wegen. Warum wollt ihr sterben, ihr Haus Israel?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Und du, Menschensohn, sprich zu den Söhnen deines Volkes: Des Gerechten Gerechtigkeit soll ihn nicht erretten am Tage seiner Übertretung, und die Ungerechtigkeit des Ungerechten bringt ihn nicht zum Fall am Tage, da er zurückkehrt von seiner Ungerechtigkeit. Und der Gerechte kann nicht leben dadurch am Tage, da er sündigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Wenn Ich zu dem Gerechten spreche: Er soll leben, und er vertraut auf seine Gerechtigkeit und tut Verkehrtes, so wird all seiner Gerechtigkeit nicht gedacht werden; und ob seiner Verkehrtheit, die er getan, darob stirbt er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Und wenn Ich zum Ungerechten spreche: Du mußt des Todes sterben, und er kehrt zurück von seiner Sünde und tut Recht und Gerechtigkeit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'Wenn der Ungerechte das Pfand zurückgibt, das Entrissene erstattet, in den Satzungen des Lebens wandelt, so daß er nichts Verkehrtes tut; so soll er leben, er soll nicht sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'All seiner Sünden, die er hat gesündigt, soll ihm nicht gedacht werden, Recht und Gerechtigkeit tut er, er soll leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Und es sprechen die Söhne deines Volkes: Nicht richtig ist der Weg des Herrn; aber sie, ihr Weg ist nicht richtig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Wenn der Gerechte zurückkehrt von seiner Gerechtigkeit und Verkehrtes tut, so stirbt er dadurch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'Und wo der Ungerechte zurückkehrt von seiner Ungerechtigkeit und Recht tut und Gerechtigkeit, so soll er deshalb leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'Und ihr sprechet: der Weg des Herrn ist nicht richtig. Nach seinen Wegen richte Ich einen jeden Mann von euch, o Haus Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'Und es geschah im zwölften Jahr, am fünften des zehnten Monats unserer Wegführung, daß ein Entkommener aus Jerusalem zu mir kam und sprach: Geschlagen ist die Stadt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Und die Hand Jehovahs war über mir am Abend ehe der Entkommene kam, und Er öffnete meinen Mund, bis er zu mir kam am Morgen, und mir ward geöffnet der Mund und ich war nicht mehr stumm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'Und es geschah an mich das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Menschensohn, die auf jenen Öden wohnen auf Israels Boden, sie sprechen und sagen: Einer war Abraham und besaß das Land erblich. Und unser sind es viel. Uns ward das Land zum Erbbesitz gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Darum sprich du zu ihnen: So spricht der Herr Jehovah: Ihr habt mit dem Blut gegessen und eure Augen zu euren Götzen erhoben und Blut vergossen, und wollt das Land erblich besitzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Ihr standet auf euer Schwert, ihr tatet Greuel, und ein Mann verunreinigte seines Genossen Weib, und ihr wollt das Land erblich besitzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'So sollst du zu ihnen sprechen: So spricht der Herr Jehovah: Bei Meinem Leben, die, so in den Öden sind, sollen durch das Schwert fallen. Und wer auf dem offenen Feld ist, den gebe Ich zum Fraß dem wilden Tier; und die in Festen und in Höhlen sind, sollen sterben durch die Pest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'Zur Verwüstung und Wüstenei mache Ich das Land und ein Ende hat seiner Stärke Stolz. Verwüstet sind die Berge Israels, daß niemand mehr darübergeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Und sie sollen erkennen, daß Ich Jehovah bin, wenn Ich das Land mache zur Verwüstung und Wüstenei ob allen ihren Greueln, die sie taten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Und du, Menschensohn, die Söhne deines Volkes, die neben den Wänden und an den Eingängen der Häuser über dich reden und einer zum anderen redet, ein Mann zu seinem Bruder, und sagt: Kommt doch und hört, was für ein Wort ausgeht von Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'Und sie kommen zu dir, wie das Volk kommt, und setzen sich als Mein Volk vor dich und hören deine Worte und - tun sie nicht. Denn Wollüste sind in ihrem Munde, sie tun sie; ihr Herz geht ihrem Gewinn nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'Und siehe, du bist ihnen, wie ein wollüstiges Lied, wie einer, der eine schöne Stimme hat und gut spielt. Und sie hören deine Worte an und tun nichts davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'Und kommt es - siehe, es kommt - da sollen sie erkennen, daß ein Prophet in ihrer Mitte war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'Und es geschah an mich das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Menschensohn, weissage wider die Hirten Israels, weissage und sprich zu ihnen, zu den Hirten: So spricht der Herr Jehovah: Wehe den Hirten Israels, die sich selber weiden. Sollten nicht die Hirten die Herde weiden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Das Fett esset ihr, und in die Wolle kleidet ihr euch, das Gemästete schlachtet ihr, die Herde weidet ihr nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Die Siechen stärkt ihr nicht und die Kranken heilt ihr nicht und die Gebrochenen verbindet ihr nicht, und die Verscheuchten bringt ihr nicht zurück, und die Verlorenen sucht ihr nicht, und mit Härte und mit Gewalt beherrscht ihr sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'Und ohne Hirten wurden sie zerstreut und wurden zum Fraße allem wilden Tiere des Feldes und sind zerstreut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Und Meine Herde, sie gehen fehl auf allen Bergen und auf allen emporragenden Hügeln; und über die ganze Erde ist Meine Herde zerstreut, und niemand ist, der nach ihr fragt, und niemand, der sie sucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Darum, ihr Hirten, hört Jehovahs Wort:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Bei Meinem Leben, spricht der Herr Jehovah, fürwahr, weil meine Herde zum Raube ward, und weil Meine Herde zum Fraß ward allem wilden Tiere des Feldes, weil sie keinen Hirten hat, und Meine Hirten nicht nach Meiner Herde fragen, und die Hirten sich selber weiden und Meine Herde nicht weiden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'Darum, ihr Hirten, hört das Wort Jehovahs:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'So spricht der Herr Jehovah: Siehe, Ich bin wider die Hirten und fordere Meine Herde von ihrer Hand und mache ein Ende ihrem Weiden der Herde, daß die Hirten nicht mehr sich selber weiden, und Ich errette aus ihrem Munde Meine Herde, daß sie nicht mehr ihnen zur Speise sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Denn also spricht der Herr Jehovah: Siehe, Ich, Ich will nach Meiner Herde fragen, nach ihnen forschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Gleichwie der Hirte nach seinem Triebe forscht am Tage, da er inmitten seiner verstreuten Herde ist, so will Ich nach Meiner Herde forschen und sie erretten von allen Orten, dahin sie zerstreut werden am Tage der Wolke und der Düsterheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'Und Ich will sie von den Völkern herausführen und sie zusammenbringen aus den Ländern, und will sie hereinbringen auf ihren Boden und sie weiden auf den Bergen Israels, in den Tälern und in allen Wohnsitzen des Landes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Auf guter Weide werde Ich sie weiden, und auf den emporragenden Bergen Israels soll ihre Hürde sein, dort sollen sie sich lagern in guter Hürde, und auf fetter Weide weiden auf den Bergen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Ich selbst will Meine Herde weiden, und Ich will sie lagern lassen, spricht der Herr Jehovah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Die Verlorenen will Ich suchen und die Verscheuchten zurückbringen und die Gebrochenen verbinden und die Kranken stärken, das Fette aber und Starke will Ich vernichten; Ich werde sie weiden nach dem Recht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Und ihr, Meine Herde, so spricht der Herr Jehovah, siehe, Ich richte zwischen Schaf und Schaf, zwischen den Widdern und Böcken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Ist es euch zu wenig, daß ihr die gute Weide abweidet, und daß ihr, was überbleibt von eurer Weide, zerstampft mit euren Füßen? und daß ihr das abgestandene Wasser trinkt und das übrige mit euren Füßen aufstört?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'Und Meine Herde weidet ab, was ihr zerstampft habt mit den Füßen, und trinkt, was eure Füße aufgestört haben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Darum spricht so der Herr Jehovah zu ihnen: Sehet Mich, Ich richte zwischen gemästetem Schaf und magerem Schaf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Weil ihr mit Seite und Schulter hintreibt und stoßt mit euren Hörnern alle die schwachen Schafe, bis ihr sie hinauszerstreut habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'Ich aber rette Meine Herde, daß sie nicht mehr zum Raube werden, und richte zwischen Schaf und Schaf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'Und einen Hirten lasse Ich über sie erstehen, daß Er sie weide, Meinen Knecht David. Er soll sie weiden, und Er soll ihr Hirte sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'Und Ich, Jehovah, will ihnen zum Gott sein, und Mein Knecht David soll Fürst in ihrer Mitte sein. Ich, Jehovah, habe es geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'Und will mit ihnen einen Bund des Friedens schließen, und wegschaffen aus dem Lande das böse wilde Tier, daß in der Wüste sie in Sicherheit wohnen, und in den Wäldern schlafen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'Und will sie selbst und die Umgebungen Meines Hügels zum Segen geben, und zu seiner Zeit Platzregen herabgießen, Platzregen des Segens sollen es sein,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'Und der Baum des Feldes wird geben seine Frucht, und die Erde geben ihr Gewächs, und sie sollen auf ihrem Boden sicher sein und wissen, daß Ich Jehovah bin, wenn Ich die Stäbe ihres Joches breche, und sie errette aus der Hand derer, die sie sich dienstbar machten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'Und sie sollen nicht mehr ein Raub der Heiden werden, und das wilde Tier der Erde soll sie nicht fressen, so daß sie in Sicherheit wohnen und niemand sie aufscheuche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'Und Ich lasse ihnen eine Pflanze erstehen zum Namen, daß sie nicht mehr vom Hunger im Lande dahingerafft werden, und nicht mehr die Schande der Völkerschaften tragen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'Und sie sollen wissen, daß Ich, Jehovah, ihr Gott, mit ihnen bin, und sie, das Haus Israels, Mein Volk sind, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Und ihr seid Meine Herde, die Herde Meiner Weide, ein Mensch seid ihr; Ich bin euer Gott, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Und das Wort Jehovahs geschah an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Menschensohn, richte dein Angesicht wider den Berg Seir und weissage dawider!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'Und sprich zu ihm: So spricht der Herr Jehovah: Siehe, Ich bin wider dich, Berg Seir, und strecke Meine Hand aus wider dich und mache dich zur Verwüstung und Wüstenei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Zur Öde will Ich deine Städte machen, und zur Verwüstung sollst du werden, und du sollst wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Darum, daß du ewige Feindschaft hast und Israels Söhne in die Hände des Schwertes hingabst zur Zeit ihrer Not, zur Zeit des Endes der Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'Darum, bei Meinem Leben, spricht der Herr Jehovah, mache Ich dich zu Blut, und Blut soll dich verfolgen; da du Blut nicht haß-test, soll dich Blut verfolgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Darum mache Ich den Berg Seir zur Verwüstung und Wüstenei und rotte aus von ihm, der darüber hingeht und zurückkehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'Und seine Berge fülle Ich mit seinen Erschlagenen; deine Hügel und deine Schluchten und all deine Flußbette - vom Schwert Erschlagene sollen allda fallen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'Zur ewigen Verwüstung mache Ich dich, und deine Städte sollen nicht bewohnt werden, und ihr sollt wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Weil du gesprochen hast: Die zwei Völkerschaften und die zwei Länder sollen mein sein, und wir werden sie erblich besitzen; und Jehovah ist dort,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'Darum, bei Meinem Leben, spricht der Herr Jehovah, so tue Ich nach deinem Zorn und nach deiner Eifersucht, wie du aus deinem Haß wider sie hast getan, und tue Mich kund an ihnen, wenn Ich dich richte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'Und du sollst wissen, daß Ich, Jehovah, hörte all deine Lästerungen, die du wider die Berge Israels gesprochen hast, sprechend: Sie sind verwüstet, sind zur Speise uns gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'Und ihr tatet groß wider Mich mit eurem Munde, und eure Worte wider Mich habt ihr gehäuft. Ich hörte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'So spricht der Herr Jehovah: Während fröhlich ist die ganze Erde, mache Ich zur Verwüstung dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Wie du fröhlich warst über das Erbe des Hauses Israel, daß es verwüstet ward, also werde Ich tun an dir. Zur Verwüstung sollst du werden, der Berg Seir und ganz Edom zumal, und sie sollen wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Und du, Menschensohn, weissage über die Berge Israels, und sprich: Höret, ihr Berge Israels, das Wort Jehovahs!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'So spricht der Herr Jehovah: Darum, daß der Feind über euch sagt: Aha! und die Opferhöhen der Ewigkeit sind uns zum Erbbesitz worden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'Darum weissage und sprich: So spricht der Herr Jehovah: Weil und weil immer man rings umher euch verwüstet und wider euch schnaubt, daß ihr ein Erbbesitz werdet dem Überrest der Völkerschaften, und weil ihr seid aufgestiegen auf die Lippe der Zunge und zum Gerede des Volkes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'Darum hört, ihr Berge Israels, das Wort des Herrn Jehovah: So spricht der Herr Jehovah zu den Bergen und zu den Hügeln, zu den Flußbetten und zu den Schluchten, und zu den Öden, den verwüsteten, und zu den verlassenen Städten, die dem Überrest der Völkerschaften ringsumher zum Raub und Gelächter geworden waren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'Darum, so spricht der Herr Jehovah, habe Ich im Feuer Meines Eifers geredet über den Überrest der Völkerschaften und über Edom allzumal, die sich selbst Mein Land mit Fröhlichkeit des ganzen Herzens, mit dem Hohne der Seele zum Erbbesitz gegeben hatten, um seinen Ertrag zu rauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Darum weissage über den Boden Israels und sprich zu den Bergen und zu den Hügeln, zu den Flußbetten und zu den Schluchten: Also spricht der Herr Jehovah: Siehe, in Meinem Eifer und in Meinem Grimm habe Ich geredet, weil ihr die Schande der Völkerschaften getragen habt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Darum spricht also der Herr Jehovah, habe Meine Hand Ich erhoben. Fürwahr, die Völkerschaften rings um euch her, sie sollen tragen ihre Schande!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Ihr aber, Berge Israels, sollt eure Zweige treiben und eure Frucht tragen für Mein Volk Israel; denn sie nahen sich, daß sie kommen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Denn siehe, Ich bin bei euch und wende Mich zu euch, und ihr werdet bebaut und besät werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'Und will auf euch den Menschen mehren, das ganze Haus Israel allzumal, und die Städte sollen bewohnt und die Öden aufgebaut werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'Und Ich will auf euch den Menschen und das Vieh mehren, und sie sollen sich mehren und fruchtbar sein, und lasse euch wohnen wie in euren Vorzeiten, und tue euch mehr Gutes, denn in euren Anfängen, und ihr sollt wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'Und Ich will den Menschen auf euch wandeln lassen, Mein Volk Israel, daß sie dich erblich besitzen und du ihr Erbe seiest, und sollst sie nicht mehr kinderlos machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'So spricht der Herr Jehovah: Weil sie zu euch sprechen: Du frißt den Menschen und machst kinderlos deine Völkerschaften;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'Darum sollst du nicht mehr den Menschen fressen und deine Völkerschaften nicht mehr kinderlos machen, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Und Ich lasse nicht mehr über dich die Beschimpfung der Völkerschaften hören, und die Schmähung der Völker sollst du nicht mehr tragen, und deine Völkerschaften sollst du nicht mehr kinderlos machen, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Und es geschah zu mir Jehovahs Wort, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Menschensohn, das Haus Israel, sie wohnten auf ihrem Boden, und verunreinigten ihn mit ihrem Weg und ihrem Tun. Wie die Unreinheit der Befleckung war ihr Weg vor Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Und Ich ergoß Meinen Grimm über sie des Blutes wegen, das sie vergossen in dem Land, und durch ihre Götzen hatten sie es verunreinigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'Und Ich zerstreute sie unter die Völkerschaften; und in die Länder wurden sie versprengt. Nach ihrem Weg und ihrem Tun hatte Ich sie gerichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'Und sie kamen unter die Völkerschaften, dahin sie kamen, und entweihten den Namen Meiner Heiligkeit, indem man von ihnen sagte: Die sind das Volk Jehovahs, und aus Seinem Lande sind sie ausgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'Ich aber will schonen den Namen Meiner Heiligkeit, den sie, das Haus Israel, entweihten, unter den Völkerschaften, dahin sie kamen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Darum sprich zu dem Hause Israels: So spricht der Herr Jehovah: Nicht euretwegen tue Ich es, ihr vom Hause Israels, sondern für den Namen Meiner Heiligkeit, den ihr entweihtet unter den Völkerschaften, dahin ihr kamet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Daß Meinen großen Namen Ich heilige, der unter den Völkerschaften ist entweiht worden, den ihr in ihrer Mitte entweiht habt, auf daß die Völkerschaften wissen, daß Ich Jehovah bin, spricht der Herr Jehovah, da Ich Mich heilige in euch vor euren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Und Ich werde euch von den Völkerschaften nehmen und euch zusammenbringen aus allen Ländern, und euch hereinbringen auf euern Boden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'Und werde sprengen reine Wasser über euch, daß ihr von allen euren Unreinheiten rein werdet, und werde euch reinigen von allen euren Götzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'Und Ich gebe euch ein neues Herz, und will euch einen neuen Geist in euer Inneres geben; und will das Herz von Stein wegtun aus eurem Fleische und euch ein Herz von Fleisch geben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'Und Meinen Geist will Ich in euer Inneres geben und machen, daß ihr in Meinen Satzungen wandelt und Meine Rechte haltet und sie tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'Und ihr sollt wohnen in dem Land, das euren Vätern Ich gegeben habe, und sollt Mein Volk sein, und Ich will Gott euch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'Und Ich will euch von allen euren Unreinheiten retten, und will rufen dem Korn und es mehren, und gebe keine Hungersnot auf euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Und Ich will die Frucht des Baumes und den Ertrag des Feldes mehren, daß ihr nicht mehr unter den Völkerschaften die Schmach der Hungersnot auf euch nehmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Und ihr werdet eurer bösen Wege gedenken, und eures Tuns, das nicht gut war, und euch wird vor euch selber verdrießen ob eurer Missetaten und ob eurer Greuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Nicht euretwegen tue Ich es, spricht der Herr Jehovah; das sei euch zu wissen getan. Schämt euch und werdet zuschanden über euren Wegen, o Haus Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'So spricht der Herr Jehovah: Am Tage, da Ich euch reinige von all euren Missetaten, da lasse Ich die Städte wieder bewohnen und die Öden werden aufgebaut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'Und das verwüstete Land soll bebaut werden, statt daß es eine Verwüstung war vor den Augen eines jeden, der vorüber- ging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'Und sagen sollen sie: Dies Land, das verwüstet war, ist wie der Garten Edens, und die Städte, die verödet und verwüstet und eingerissen waren, sind befestigt, sie sind bewohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Und die Völkerschaften, die verblieben um euch her, sollen wissen, daß Ich, Jehovah, das Eingerissene gebaut, bepflanzt das Verwüstete. Ich, Jehovah, habe es geredet und getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'So spricht der Herr Jehovah: Noch darin lasse Ich Mich erbitten vom Hause Israels, daß Ich es ihnen tue. Ich will sie mehren, wie eine Herde von Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Wie die Herde der Heiligtümer, wie die Herde Jerusalems an seinen Festzeiten, so sollen die verödeten Städte voll sein von einer Herde von Menschen, und sie sollen wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Und es war auf mir Jehovahs Hand, und Er brachte mich heraus im Geist Jehovahs, und ließ mich nieder inmitten einer Talebene, und sie war voll von Gebeinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'Und Er ließ mich darüber hinziehen ringsum und ringsum, und siehe, ihrer waren sehr viel auf der Fläche der Talebene; und siehe, sie waren gar sehr verdorrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'Und er sprach zu mir: Menschensohn, werden diese Gebeine leben? Und ich sprach: Herr Jehovah, Du weißt es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Und Er sprach zu mir: Weissage über diese Gebeine und sprich zu ihnen: Ihr verdorrte Gebeine, hört das Wort Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'So spricht der Herr Jehovah zu diesen Gebeinen: Siehe, Ich bringe Geist in euch, auf daß ihr lebet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'Und Ich gebe Sehnen auf euch, und lasse Fleisch auf euch heraufkommen und überdecke euch mit Haut, und gebe Geist in euch, auf daß ihr lebet, und ihr sollt wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'Und ich weissagte, wie mir geboten war, und es ward eine Stimme, als ich weissagte, und siehe, ein Beben und die Gebeine nahten sich, Gebein zu seinem Gebein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'Und ich sah und siehe, über sie kamen herauf Sehnen und Fleisch, und es überdeckte sie Haut von oben; und es war kein Geist in ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Und Er sprach zu mir: Weissage über den Geist! Weissage, Menschensohn, und sprich zum Geist: So spricht der Herr Jehovah: Von den vier Winden komme Geist, und hauche diese Erwürgten an, auf daß sie leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'Und ich weissagte, wie Er mir gebot; und der Geist kam in sie, und sie lebten, und sie standen auf ihren Füßen, eine sehr, sehr große Streitmacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'Und Er sprach zu mir: Menschensohn, diese Gebeine, sie sind das ganze Haus Israel. Siehe, sie sprechen: Verdorrt sind unsere Gebeine, und verloren unsere Hoffnung, wir sind abgeschnitten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Darum weissage und sprich zu ihnen: Also spricht der Herr Jehovah: Siehe, Ich öffne eure Gräber und bringe euch herauf aus euren Gräbern, Mein Volk, und bringe euch hinein auf den Boden Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'Und ihr sollt wissen, daß Ich Jehovah bin, wenn eure Gräber Ich geöffnet und euch, Mein Volk, aus euren Gräbern habe lassen aufsteigen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'Und gebe Meinen Geist in euch, auf daß ihr lebet, und lasse euch auf euren Boden nieder, auf daß ihr wisset, daß Ich, Jehovah, es habe geredet und getan, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'Und es geschah Jehovahs Wort an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'Und du, Menschensohn, nimm ein Holz dir und schreibe darauf: Dem Jehudah und den Söhnen Israels, seinen Gefährten; und nimm ein Holz und schreibe darauf: Dem Joseph, das Holz Ephraims und des ganzen Hauses Israels, seiner Gefährten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'Und bringe sie für dich nahe, eins zum anderen, zu einem Holz, daß sie eins seien in deiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'Und wie die Söhne deines Volkes zu dir sprechen und sagen: Willst du uns nicht ansagen, was dir das sein soll?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'Rede du zu ihnen: So spricht der Herr Jehovah: Siehe, Ich nehme Josephs Holz, das in der Hand Ephraims und der Stämme Israels, seiner Gefährten, ist, und Ich gebe sie, die darauf sind, zum Holze Jehudahs und mache sie zu einem Holz, auf daß sie eins seien in Meiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Und sie sollen die Hölzer, auf die du geschrieben hast, in deiner Hand vor ihren Augen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'Und rede du zu ihnen: Also spricht der Herr Jehovah: Siehe, Ich nehme die Völker Israels heraus von den Völkerschaften, dahin sie gegangen waren, und bringe sie zusammen von ringsumher und bringe sie herein auf ihren Boden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'Und Ich mache sie zu einer Völkerschaft im Lande auf Israels Bergen, und ein König soll für sie alle König sein, daß nicht mehr zwei Völkerschaften seien und sie nicht noch in zwei Reiche mehr sich teilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Und nicht werden sie sich mehr mit ihren Götzen und ihren Scheusalen und auf all ihren Übertretungen verunreinigen. Und Ich rette sie aus allen ihren Wohnsitzen, worin sie sündigten, und reinige sie, daß sie Mein Volk werden, und Ich ihnen Gott sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'Und Mein Knecht David wird König sein über sie und wird ein Hirte sein für sie alle, und in Meinen Rechten werden sie wandeln, und halten Meine Satzungen und sie tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'Und werden in dem Lande wohnen, das Ich Meinem Knechte, dem Jakob, gegeben habe, in dem wohnten eure Väter, und in ihm werden wohnen sie und ihre Söhne und ihrer Söhne Söhne in Ewigkeit, und Mein Knecht David soll ihr Fürst sein ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'Und Ich will einen Bund des Friedens mit ihnen schließen, ein Bund der Ewigkeit soll es für sie sein. Und Ich gebe sie und mehre sie und gebe Mein Heiligtum in ihre Mitte ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'Und Meine Wohnung soll sein bei ihnen, und Ich will ihr Gott sein und sie sollen Mein Volk sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'Und die Völkerschaften sollen wissen, daß Ich, Jehovah, Israel heilige, wenn Mein Heiligtum ewiglich in ihrer Mitte ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'Und es geschah Jehovahs Wort zu mir, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Menschensohn, richte dein Angesicht gegen Gog, das Land Magog, den Fürsten, das Haupt von Meschech und Thubal, und weissage wider ihn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'Und sprich: So spricht der Herr Jehovah: Siehe, Ich bin wider dich, Gog, du Fürst, Haupt von Meschech und Thubal,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'Und Ich wende dich zurück und tue Haken in deine Kinnbacken und bringe heraus dich und all deine Streitmacht, Rosse und Reiter, alle vollkommen gekleidet, eine große Versammlung mit Schild und Tartsche, allesamt fassend die Schwerter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Perser, Kusch und Pud mit ihnen, sie alle mit Tartsche und Helm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomer und alle seine Scharen, Beth Thogarmah, an den Seiten der Mitternacht, und alle seine Scharen, viele Völker mit dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Sei bereit und bereite dich, du und alle deine Versammlung, die sich um dich angesammelt, und sei ihnen zur Hut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Nach vielen Tagen wirst du heimgesucht werden, in der Zukunft Jahren wirst du kommen in ein Land, das vom Schwert zurückgebracht aus vielen Völkern zusammengebracht worden, auf die Berge Israels, die beständig eine Öde gewesen, das aus den Völkern herausgebracht worden ist, und wohnen allesamt sicher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'Und wie ein Unwetter ziehst du herauf, du kommst, wie eine Wolke, das Land zu bedecken wirst du sein, du und all deine Scharen, und viele Völker mit dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'So spricht der Herr Jehovah: Und geschehen wird an jenem Tag, daß Dinge in dein Herz aufsteigen und du böse Gedanken denkst,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'Und sprichst: Ich will hinaufziehen in ein offenliegendes Land, will kommen zu denen, die rasten, die wohnen in Sicherheit. Sie alle wohnen ohne Mauer und Riegel, und Torflügel haben sie keine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'Um Beute zu erbeuten und Raub zu rauben, und deine Hand zurückzukehren wider die Öden, die bewohnt sind, und wider ein Volk, das aus den Völkerschaften ist gesammelt worden, und Viehherden und Habe sich schafft und wohnt im Nabel der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Scheba und Dedan und die Händler von Tharschisch und alle seine jungen Löwen werden zu dir sagen: Bist du gekommen Beute zu erbeuten, um Raub zu rauben, hast deine Versammlung du angesammelt, auf daß du Silber und Gold wegtragest, Viehherde und Habe wegnehmest, um große Beute zu erbeuten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Darum weissage, Menschensohn, und sprich zu Gog: So spricht der Herr Jehovah: Wirst du nicht an jenem Tag es wissen, daß Mein Volk Israel wohnt in Sicherheit?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'Und du kommst von deinem Ort, von den Seiten der Mitternacht, du und viele Völker mit dir, sie alle auf Rossen reitend, eine große Versammlung und viele Streitmacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'Und ziehst herauf wider Mein Volk Israel, wie eine Wolke das Land zu bedecken. In der Zukunft der Tage wird es geschehen, daß Ich dich in Mein Land hereinbringe, auf daß die Völkerschaften Mich erkennen, wie Ich Mich durch dich, o Gog, vor ihren Augen heilige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'So spricht der Herr Jehovah: Bist du es, von dem Ich in den Tagen der Vorzeit durch die Hand Meiner Knechte, der Propheten Israels, geredet habe, die in jenen Tagen jahrelang weissagten, daß Ich dich wider sie hereinbringen würde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Und wird geschehen an selbigem Tage, am Tage, da Gog auf den Boden Israels kommt, sagt der Herr Jehovah, daß Mein Grimm aufsteigt in Meinem Zorn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Und in Meinem Eifer, im Feuer Meines Wütens, rede Ich: Fürwahr, an jenem Tage wird ein großes Erdbeben sein auf dem Boden Israels,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'Daß vor Meinem Angesicht beben die Fische des Meeres und der Himmel Gevögel und das wilde Tier des Feldes und all das Kriechtier, das auf dem Boden kriecht, und jeder Mensch auf den Angesichten des Bodens; und Berge werden umgerissen und Felsenwände fallen und zur Erde fällt jede Mauer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'Und Ich rufe wider ihn auf allen Meinen Bergen das Schwert, spricht der Herr Jehovah, das Schwert des Mannes soll wider seinen Bruder sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'Und Ich will mit ihm rechten mit Pest und mit Blut, und mit überflutendem Platzregen; und Steine des Hagels, Feuer und Schwefel, lasse Ich regnen über ihn und über seine Scharen, und über die vielen Völker, die mit ihm sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'Und Ich erweise Mich groß und heilige Mich, und tue Mich kund vor den Augen vieler Völkerschaften, auf daß sie wissen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Und du, Menschensohn, weissage wider Gog und sprich: So spricht der Herr Jehovah: Siehe, Ich bin wider dich, Gog, Fürst, Haupt über Meschech und Thubal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'Und Ich wende dich zurück und sechsteile dich und lasse dich von den Seiten der Mitternacht heraufsteigen und bringe dich herein auf die Berge Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'Und schlage dir deinen Bogen aus deiner linken Hand und lasse dir deine Pfeile aus der rechten Hand fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Auf den Bergen Israels sollst du fallen, du und alle deine Scharen, und die Völker, die mit dir sind; und den Raubvögeln, den Vögeln jeglichen Flügels und dem wilden Tier des Feldes gebe Ich dich zur Speise.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Auf dem Angesichte des Feldes sollst du fallen, denn Ich habe geredet, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'Und Feuer sende Ich gegen Magog und die, so sicher auf den Inseln wohnen, auf daß sie erkennen, daß Ich Jehovah bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'Und den Namen Meiner Heiligkeit tue Ich kund inmitten Meines Volkes Israel, und lasse nicht mehr entweihen den Namen Meiner Heiligkeit, und erkennen sollen die Völkerschaften, daß Ich Jehovah bin, der Heilige in Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Siehe, es kommt und es geschieht, spricht der Herr Jehovah, dies ist der Tag, von dem Ich geredet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'Und die, so in den Städten Israels wohnen, gehen hinaus und brennen, und feuern mit Waffen, und mit Tartsche und Schild, mit dem Bogen und Pfeilen und dem Stecken der Hand, und mit dem Speere; und Feuer davon brennen sie sieben Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'Und sie werden kein Holz vom Feld tragen, noch es hauen aus den Wäldern; denn mit den Waffen lassen sie brennen das Feuer. Und sie machen Beute von denen, welchen sie zur Beute waren, und rauben von ihren Räubern, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'Und am selbigen Tage wird geschehen, daß Ich dem Gog dort Platz für ein Grab in Israel gebe, die Schlucht der Vorübergehenden, ostwärts vom Meere, und es ist eine Sperre für die Vorübergehenden; und dort werden sie den Gog und all seine Volksmenge begraben und es nennen die Schlucht der Volksmenge Gogs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'Und das Haus Israel wird sie begraben, um das Land zu reinigen, sieben Monate.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'Und alles Volk des Landes wird begraben, und es wird ihnen zum Namen sein an dem Tag, da Ich Mich verherrliche, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'Und beständige Männer werden sie ausscheiden, die das Land durchziehen und mit den Durchziehenden begraben sie die, so auf den Angesichten des Landes übriggeblieben sind, es zu reinigen. Nach dem Ende von sieben Monaten werden sie forschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'Und die Durchziehenden werden das Land durchziehen, und sieht einer das Gebein eines Menschen, so baut er ein Mahlzeichen daneben auf, bis die Begrabenden es in Ge-Hamon-Gog begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Und auch der Name der Stadt ist Hamonah, und sie reinigen das Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'Und du, Menschensohn, so spricht der Herr Jehovah: Sprich zu den Vögeln jeglichen Flügels und zu allem wilden Tiere des Feldes: Tut euch zusammen und kommet, versammelt euch ringsumher zu Meinem Opfer, das Ich für euch opfere, ein großes Opfer auf den Bergen Israels, und esset Fleisch und trinket Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Das Fleisch der Helden sollt ihr essen, und das Blut der Fürsten der Erde trinken, Widder, Lämmer und Böcke, Farren, die gemästeten Baschans allzumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'Und ihr sollt Fett essen bis zur Sättigung, und Blut trinken bis zur Trunkenheit von Meinem Opfer, das Ich für euch opfere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'Und sättigt euch an Meinem Tisch von Roß und Streitwagen, vom Helden und jeglichem Manne des Streites, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'Und Ich werde Meine Herrlichkeit unter die Völkerschaften geben, daß alle Völkerschaften sehen Mein Gericht, das Ich habe geübt, und Meine Hand, die Ich an sie gelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'Und daß sie, das Haus Israel, wissen, daß Ich, Jehovah, ihr Gott bin von diesem Tage an und hinfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Und daß wissen die Völkerschaften, daß die vom Hause Israel ob ihrer Missetat fortgeführt wurden, weil sie Mir untreu wurden; darum Ich Mein Angesicht verbarg vor ihnen und sie in die Hände ihrer Dränger gab, so daß sie allesamt durch das Schwert fielen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Ob ihrer Unreinheiten und ihrer Übertretungen habe Ich so getan an ihnen und Mein Angesicht verborgen vor denselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Darum spricht so der Herr Jehovah: Nun bringe Ich die Gefangenschaft Jakobs zurück und erbarme Mich des ganzen Hauses Israel und eifere für den Namen Meiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'Und sie sollen tragen ihre Schande und alle ihre Untreue, die sie begingen gegen Mich, wenn sie in Sicherheit auf ihrem Boden wohnen und niemand sie aufscheucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'Wenn Ich sie aus den Völkern zurückbringe und sie zusammenbringe aus den Ländern ihrer Feinde, und Mich heilige an ihnen vor den Augen vieler Völkerschaften;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'Und sie sollen wissen, daß Ich Jehovah bin, ihr Gott, Der sie wegführte unter die Völkerschaften, und sie wieder zusammenfaßte auf ihren Boden und keinen mehr von ihnen übrig ließ;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'Und will Mein Angesicht nicht mehr verbergen vor ihnen, weil Meinen Geist Ich über das Haus Israel ausgießen werde, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'Im fünfundzwanzigsten Jahr unserer Wegführung, im Anfang des Jahres, am zehnten Tag des Monats, im vierzehnten Jahr, nachdem die Stadt geschlagen war, an ebendemselben Tag, war über mir die Hand Jehovahs und brachte mich dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'In Gesichten Gottes brachte Er mich hinein zum Land Israels und ließ mich nieder auf einen sehr hohen Berg, und auf ihm war wie das Gebäu einer Stadt vom Mittag her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'Und Er brachte mich dahin, und siehe, da war ein Mann, sein Ansehen wie das Ansehen von Erz, und eine leinene Schnur war in seiner Hand und ein Rohr zum Messen; und er stand in dem Tor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'Und der Mann redete zu mir: Menschensohn, siehe mit deinen Augen und mit deinen Ohren höre, und richte dein Herz auf alles, was ich dich sehen lasse; denn damit ich dir es zeige, bist du hierher gebracht. Alles, was du siehst, sage an dem Hause Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'Und siehe, eine Mauer war von außen am Hause, ringsum, ringsum. Und der Mann hatte in der Hand ein Rohr zum Messen von sechs Ellen, nach der Elle und eine Handbreite; und er maß die Breite des Gebäus eine Rute und die Höhe eine Rute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Und er ging hinein zum Tor, das am Wege gegen Osten war, und stieg dessen Stufen hinauf und maß die Schwelle des Tores zu einer Rute in die Breite und die andere Schwelle eine Rute breit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'Und die Wachtzelle eine Rute nach der Länge, eine Rute in der Breite. Und zwischen den Wachtzellen waren es fünf Ellen, und die Schwelle des Tores neben der Vorhalle des Tores von innen her eine Rute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Und er maß die Vorhalle des Tores von innen zu einer Rute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Und er maß die Vorhalle des Tores acht Ellen, und die Vorsprünge davon zwei Ellen; und die Vorhalle des Tores innerhalb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'Und der Wachtzellen des Tores am Wege gegen Osten waren drei hüben und drei drüben, ein Maß für deren drei, und ein Maß für die Vorsprünge hüben und drüben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'Und er maß die Breite des Eingangs des Tores zehn Ellen, die Länge des Tores dreizehn Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'Und die Grenzwehr vor den Wachtzellen war eine Elle, und eine Elle Grenzwehr dort. Aber die Wachtzellen waren von sechs Ellen hier und von sechs Ellen dort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'Und er maß das Tor vom Dach der Wachtzelle bis zu seinem Dach, fünfundzwanzig Ellen in die Breite, Eingang gegen Eingang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'Und er machte die Erker sechzig Ellen, und vor dem Erker war der Vorhof am Tore ringsum und ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'Und vor dem Tore des Eintritts bis vor die Vorhalle am inneren Tor waren es fünfzig Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'Und geschlitzte Fenster waren an den Wachtzellen, und an ihren Vorsprüngen einwärts dem Tore zu, ringsum und ringsum, und so an den Vorhallen, und Fenster waren ringsum und ringsum einwärts. Und an den Vorsprüngen waren Palmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Und er brachte mich zu dem äußeren Vorhof, und siehe, da waren Zellen und ein Pflaster gemacht am Vorhof ringsum, ringsum, dreißig Zellen waren auf dem Pflaster.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'Und das Pflaster war zur Seite der Tore, der Länge der Tore entlang, - das niedere Pflaster.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'Und er maß die Breite vor dem unteren Tor, vor dem inneren Vorhof, außerhalb, hundert Ellen, gegen Osten und gegen Mitternacht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'Und das Tor, dessen Vorderseite am Wege nach Mitternacht des äußeren Vorhofs ist, maß er nach seiner Länge und nach seiner Breite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'Und seiner Wachtzellen waren drei hier und drei dort, und seine Vorsprünge und seine Vorhallen waren nach dem Maß des ersten Tores fünfzig Ellen in die Länge und fünfundzwanzig Ellen in die Breite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'Und seine Fenster und seine Vorhallen und seine Palmen waren nach dem Maß des Tores, dessen Angesicht auf dem Wege nach Morgen ist, und auf sieben Stufen stieg man dazu hinauf, und seine Vorhalle war vor denselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'Und das Tor zum inneren Vorhof war gegenüber dem Tore nach Mitternacht und nach Osten, und er maß hundert Ellen von Tor zu Tor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'Und er ließ mich den Weg gen Mittag gehen, und siehe, ein Tor am Weg nach Mittag, und er maß seine Pfeiler und seine Vorhallen nach denselben Maßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'Und Fenster hatte es, und seine Vorhallen ringsum und ringsum, wie die selbigen Fenster fünfzig Ellen die Länge und die Breite fünfundzwanzig Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'Und sieben Stufen hatten seine Treppen und seine Vorhalle davor, und hatte Palmen, eine hüben und eine drüben an seinen Pfeilern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'Und ein Tor zum inneren Vorhof war am Wege nach Mittag, und er maß von Tor zu Tor am Wege nach Mittag hundert Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Und er brachte mich hinein in den inneren Vorhof durch das Tor nach Mittag, und maß das Tor nach Mittag, nach denselben Maßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'Und seine Wachtzellen und seine Pfeiler und seine Vorhallen waren nach diesen Maßen, und waren Fenster daran und an seinen Vorhallen ringsum und ringsum: fünfzig Ellen in die Länge und fünfundzwanzig in die Breite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'Und ringsum und ringsum waren Vorhallen, fünfundzwanzig Ellen in der Länge und fünf Ellen in der Breite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'Und seine Vorhallen waren dem äußeren Vorhof zu, und Palmen waren an seinen Pfeilern, und acht Stufen stieg man zu ihm hinauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'Und er brachte mich hinein nach dem inneren Vorhof am Wege nach Osten, und maß das Tor nach denselben Maßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'Und seine Wachtzellen und seine Pfeiler und seine Vorhallen waren nach denselben Maßen, und Fenster hatte es und seine Vorhallen ringsum, ringsum, in die Länge fünfzig Ellen, fünfundzwanzig Ellen in die Breite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'Und seine Vorhalle war nach dem äußeren Vorhof, und Palmen waren an seinen Pfeilern hüben und drüben, und acht Stufen stieg man zu ihm hinauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'Und er brachte mich hinein zum Tor nach Mitternacht, und maß nach denselben Maßen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'Seine Wachtzellen, seine Pfeiler und seine Vorhallen, und seine Fenster waren ringsum, ringsum, fünfzig Ellen in die Länge und fünfundzwanzig Ellen in die Breite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'Und seine Pfeiler waren dem äußeren Vorhof zu, und Palmen waren an seinen Pfeilern hier und dort, und acht Stufen stieg man zu ihm hinauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'Und da war eine Zelle, und ihr Eingang war an den Pfeilern der Tore. Da wuschen sie das Brandopfer ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'Und in der Vorhalle des Tores waren zwei Tische hüben und zwei Tische drüben, das Brandopfer und das Sündopfer und das Schuldopfer darauf zu schlachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'Und auf der Seite nach außen, da man zum Eingang des Tores nach Mitternacht aufsteigt, waren zwei Tische, und auf der anderen Seite der Vorhalle des Tores waren zwei Tische.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'Vier Tische hüben und vier Tische drüben zur Seite des Tores: acht Tische, auf denen sie schlachteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'Und die vier Tische für das Brandopfer waren von behauenen Steinen, anderthalb Ellen die Länge und anderthalb Ellen die Breite, und eine Elle die Höhe, auf dieselben legten sie die Geräte nieder, mit denen sie das Brandopfer und das Schlachtopfer schlachteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'Und Herdsteine von einer Handbreite waren einwärts zugerichtet ringsum, ringsum, und auf den Tischen das Fleisch der Opfergabe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'Und außerhalb des inneren Tores waren Zellen der Sänger in dem inneren Hofe zur Seite des Tores gen Mitternacht, und ihre Vorderseiten waren des Weges gen Mittag; eine war an der Seite des Tores gen Osten, mit der Vorderseite des Weges gen Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'Und er redete zu mir: Diese Zelle, deren Vorderseite des Weges gen Mittag ist, ist für die Priester, die der Hut des Hauses hüten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Die Zelle aber, deren Vorderseite des Weges gen Mitternacht ist, ist für die Priester, welche die Hut des Altares hüten. Dies sind die Söhne Zadoks, die von den Söhnen Levis dem Jehovah nahen, Ihm Dienst zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'Und er maß den Hof, zu einer Länge von hundert Ellen, und hundert Ellen Breite in das Gevierte. Und der Altar war vor dem Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'Und er brachte mich hinein zur Vorhalle des Hauses, und maß den Pfeiler der Vorhalle zu fünf Ellen hüben und fünf Ellen drüben, und die Breite des Tores war drei Ellen hüben und drei Ellen drüben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Die Länge der Halle zwanzig Ellen, und die Breite elf Ellen, und samt den Stufen, auf denen sie hinangingen zu derselben, und Säulen waren bei den Pfeilern, eine hüben und eine drüben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'Und er ließ mich in den Tempel eingehen, und er maß die Pfeiler, sechs Ellen Breite hier und sechs Ellen Breite dort, nach der Breite des Zeltes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'Und die Breite des Eingangs war zehn Ellen, und die Seiten des Eingangs fünf Ellen hier und fünf Ellen dort, und er maß seine Länge, vierzig Ellen und die Breite zwanzig Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'Und er ging in das Innere und maß den Pfeiler des Eingangs, zwei Ellen, und den Eingang, sechs Ellen, und die Breite des Eingangs sieben Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'Und er maß seine Länge, zwanzig Ellen, und die Breite, zwanzig Ellen vor dem Tempel; und er sprach zu mir: Dies ist das Heilige der Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'Und er maß die Wand des Hauses, sechs Ellen, und die Breite des Seitengemachs vier Ellen, ringsum und rings um das Haus herum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Und die Seitengemächer, Seitengemach an Seitengemach waren es dreiunddreißig, zweimal, und sie gingen herein in die Wand am Hause, die für die Seitengemächer ringsum, ringsum war zum Ergreifen, aber in die Wand des Hauses selbst griffen sie nicht ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'Und es ward breiter aufwärts und aufwärts, wie es umherlief; denn die Umgänge am Hause waren übereinander, ringsum, rings um das Haus. Darum nahm die Breite am Hause aufwärts zu, wie man von unteren durch das mittlere nach dem oberen aufstieg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'Und ich sah am Hause die Höhe ringsum, ringsum von den Grundlagen der Seitengemächer, eine volle Rute, sechs Ellen bis an das Gelenk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Die Breite der Mauer zum Seitengemach nach außen war fünf Ellen, und was gelassen wurde, war das Inwendige der Seitengemächer des Hauses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'Und zwischen den Zellen war eine Breite von zwanzig Ellen, rings um das Haus, ringsum und ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'Und der Eingang zum Seitengemach war nach dem Freigelassenen, ein Eingang des Weges gen Mitternacht, und ein Eingang gen Mittag, und die Breite des freigelassenen Raumes war fünf Ellen ringsum und um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'Und der Bau auf der Fläche des Hofraumes an der Ecke des Weges nach dem Meere war siebzig Ellen die Breite, und die Wand des Baues hatte eine Breite von fünf Ellen ringsum und ringsum, und seine Länge neunzig Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'Und er maß das Haus, eine Länge von hundert Ellen, und den Hofraum, und den Bau und seine Wände, eine Länge von hundert Ellen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'Und die Breite der Vorderseite des Hauses und den Hofraum gegen Osten hundert Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'Und er maß die Länge des Baues vor dem Hofraum dahinter, und seine Galerien hier und dort hundert Ellen, und den inneren Tempel und des Vorhofs Hallen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'Die Schwellen und die verengten Fenster und die Galerien ringsum an den drei Seiten, gegenüber der Schwelle, war hölzernes Getäfel ringsum, ringsum, und von der Erde bis zu den Fenstern, und die Fenster waren bedeckt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'Über dem Eingang oben und bis in das innere Haus und außen und an der ganzen Wand ringsum, ringsum, im Inwendigen und im Auswendigen war es nach den Maßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'Und waren gemacht Cherube und Palmen, und eine Palme zwischen Cherub und Cherub, und der Cherub hatte zwei Gesichter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'Und eines Menschen Angesicht der Palme zu hüben, und eines jungen Löwen Angesicht der Palme zu drüben. Das ward getan dem ganzen Haus ringsum, ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Von der Erde bis oberhalb des Eingangs waren die Cherube und die Palmen gemacht, und an der Wand des Tempels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Die Türpfosten des Tempels waren viereckig und am Vorderteil des Heiligtums war Ansehen wie Ansehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Der Altar von Holz war drei Ellen an Höhe und seine Länge zwei Ellen. Und die Ecken an ihm und seine Länge und seine Wände waren von Holz. Und er redete zu mir: Dies ist der Tisch, der vor Jehovah ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'Und zwei Türflügel hatte der Tempel und das Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'Und zwei Türflügel hatten die Türen, zwei sich umwendende Türflügel; zwei für die eine Tür und zwei Türflügel für die andere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'Und an ihnen, an den Türflügeln des Tempels, waren Cherube und Palmen gemacht, so wie sie an den Wänden gemacht waren. Auch waren dicke Balken vorne außen an der Vorhalle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'Und die Fenster waren geschlitzt, und Palmen hüben und drüben an den Seiten der Vorhalle und an den Seitengemächern des Hauses und an den Balken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'Und er brachte mich hinaus, in den äußeren Vorhof, den Weg gen Mitternacht zu, und brachte mich hinein nach der Zelle, gegenüber dem Hofraum und gegenüber dem Gebäu nach Mitternacht hin;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'Zu der Vorderseite, in einer Länge von hundert Ellen nach dem Eingang gen Mitternacht, und die Breite war fünfzig Ellen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'Gegenüber den zwanzigen im inneren Vorhof und gegenüber dem Pflaster im äußeren Vorhof war eine Galerie vor der anderen Galerie dreifach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Und vor den Zellen war ein Gang von zehn Ellen Breite nach dem Inneren, ein Weg von einer Elle, und ihre Eingänge waren gen Mitternacht zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'Und die oberen Zellen waren kürzer; denn die Galerien nahmen von ihnen, von den unteren und von den mittleren, weg am Gebäu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Denn dreistöckig waren sie, und hatten keine Säulen wie die Säulen der Vorhöfe; darum zog man zurück von den untersten und von den mittleren von der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'Und die Hofmauer, die außerhalb den Zellen entlang lief, des Weges dem äußeren Vorhof zu vor den Zellen, deren Länge war fünfzig Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Denn die Länge der Zellen dem äußeren Vorhof zu war fünfzig Ellen; aber siehe, vor dem Tempel hin war sie hundert Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'Und unterhalb dieser Zellen war der Zugang vom Osten her, da man in sie hineinging vom äußeren Vorhof aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'In der Breite der Hofmauer des Vorhofes, des Weges nach Osten hin, an der Vorderseite des Hofraumes und vor dem Gebäu, waren Zellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'Und der Weg vor denselben hin war anzusehen wie der vor den Zellen am Weg gegen Mitternacht, nach ihrer Länge so war ihre Breite, und nach all ihren Ausgängen und nach ihren Einrichtungen und ihren Eingängen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'Und wie die Eingänge der Zellen des Weges gen Mittag war ein Eingang am Anfang des Weges, des Weges vor der geraden Hofmauer, des Weges gen Morgen, wo man durch sie eingeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'Und er sprach zu mir: Die Zellen gen Mitternacht, die Zellen gen Mittag, die vor dem Hofraum sind, sie sind Zellen der Heiligkeit, wo die Priester essen, die Jehovah darbringen das Heilige des Heiligen. Dort legen sie nieder das Heilige des Heiligen, und das Speiseopfer und das Sündopfer und das Schuldopfer; denn der Ort ist heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Wenn die Priester hineingehen, so sollen sie nicht aus dem Heiligtum hinausgehen in den äußeren Vorhof, sondern allda ihre Kleider, in denen sie Dienst getan, niederlegen, denn Heiligkeit sind sie; und andere Kleider anziehen, und dem nahen, was des Volkes ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'Und er vollendete die Messungen des inneren Hauses und brachte mich hinaus, des Weges des Tores, dessen Vorderseite des Weges gen Osten ist, und maß es ringsum, ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Er maß gegen den Ostwind mit dem Meßrohr fünfhundert Ruten, mit dem Meßrohr ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Er maß gegen den Wind der Mitternacht, fünfhundert Ruten mit dem Meßrohr ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Gegen den Wind des Mittags maß er fünfhundert Ruten mit dem Meßrohr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Er wandte sich um zum Wind der Meeresseite; er maß fünfhundert Ruten mit dem Meßrohr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Nach den vier Winden maß er es. Es hatte eine Mauer ringsum, ringsum, in der Länge fünfhundert und in der Breite fünfhundert, um zu scheiden zwischen dem Heiligen und dem Gemeinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Und er ließ mich gehen zum Tor, dem Tor, das des Weges gen Osten gewendet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'Und siehe, die Herrlichkeit des Gottes Israels kam des Weges von Osten her, und Seine Stimme war wie die Stimme vieler Wasser, und die Erde leuchtete von Seiner Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'Und das Ansehen der Erscheinung, die ich sah, war wie die Erscheinung, die ich sah, als ich kam die Stadt zu verderben, und die Erscheinung war wie die Erscheinung, die ich sah am Fluß Chebar, und ich fiel auf mein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'Und die Herrlichkeit Jehovahs kam herein zu dem Haus, auf dem Wege des Tores, dessen Vorderseite auf dem Wege nach dem Osten ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'Und der Geist hob mich auf und brachte mich hinein nach dem inneren Vorhof, und siehe, das Haus war voll der Herrlichkeit Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'Und ich hörte, wie Einer aus dem Hause zu mir sprach; und ein Mann stand neben mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'Und Er sprach zu mir: Menschensohn, dies ist der Ort Meines Thrones und der Ort der Sohlen Meiner Füße, wo Ich wohnen werde inmitten der Söhne Israels in Ewigkeit; und nicht sollen mehr verunreinigen die vom Hause Israels den Namen Meiner Heiligkeit, sie und ihre Könige, durch ihre Buhlerei und durch die Leichen ihrer Könige, wenn sie gestorben sind;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'Weil sie ihre Schwelle neben Meine Schwelle und ihre Türpfosten neben Meine Türpfosten setzten, und die Wand war zwischen Mir und ihnen, und sie den Namen Meiner Heiligkeit verunreinigten durch ihre Greuel, die sie taten, da verzehrte Ich sie in Meinem Zorn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Nun sollen sie fernhalten von Mir ihre Buhlerei und die Leichen ihrer Könige, und Ich will ewiglich in ihrer Mitte wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Du, Menschensohn, sage dem Hause Israels das Haus an, daß sie zuschanden werden ob ihrer Missetaten und dessen Ebenmaß messen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'Und werden sie zuschanden ob allem, was sie getan, so lasse sie erkennen die Gestaltung und das Ebenmaß des Hauses, und seine Ausgänge und seine Eingänge, und alle seine Gestaltungen, und alle seine Satzungen und all seine Gestaltungen, und all seine Gesetze, und schreibe sie vor ihren Augen nieder, daß sie alle seine Gestaltung und alle seine Satzungen halten und sie tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'Dies ist das Gesetz des Hauses, das auf dem Gipfel des Berges ist: All seine Grenze ringsum, ringsum ist das Heilige des Heiligen. Siehe, dies ist das Gesetz des Hauses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'Und dies sind die Maße des Altars nach Ellen. Die Elle ist eine Elle und eine Handbreite. Und der Untersatz ist eine Elle und eine Elle die Breite, und sein Rand an seiner Einfassung ist ringsumher eine Spanne, und das ist der Rücken des Altars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'Und von dem Untersatz von Erde bis an die untere Einfassung sind es zwei Ellen, und die Breite eine Elle, und von der kleineren Einfassung bis zu der großen Einfassung sind es vier Ellen, und die Breite eine Elle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'Und der Herd vier Ellen, und von dem Herd und oberhalb sind vier Hörner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'Und der Herd war zwölf in der Länge bei zwölf in die Breite, viereckig nach seinen vier Seiten hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'Und die Einfassung war vierzehn in die Länge bei vierzehn in die Breite an seinen vier Seiten, und sein Rand rings um denselben eine halbe Elle, und sein Untersatz eine Elle rings herum, und seine Stufen sind gegen Osten gewendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'Und Er sprach zu mir: Menschensohn, so spricht der Herr Jehovah: Dies sind die Satzungen für den Altar am Tage, da man ihn macht, um Brandopfer darauf aufzuopfern und Blut darauf zu sprengen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Und den Priestern, den Leviten, die aus dem Samen Zadoks sind, die Mir nahen, um Mir Dienst zu tun, spricht der Herr Jehovah, sollst du einen Farren, ein junges Rind als Sündopfer geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'Und sollst von desselben Blut nehmen und auf seine vier Hörner sprengen, und an die vier Ecken der Einfassung, und an den Rand rings herum, und ihn entsündigen und sühnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'Und sollst den Farren des Sündopfers nehmen und ihn verbrennen an einem verordneten Platz des Hauses, außerhalb des Heiligtums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Und am zweiten Tage sollst du darbringen einen Bock der Ziegen ohne Fehl zum Sündopfer, und den Altar damit entsündigen, wie man ihn mit dem Farren entsündigte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Und wenn du das Entsündigen vollendet hast, sollst du darbringen einen Farren, ein junges Rind ohne Fehl, und einen Widder von der Herde ohne Fehl,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'Und sollst sie vor Jehovah darbringen, und sollen die Priester Salz über sie werfen, und sie als Brandopfer dem Jehovah aufopfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Sieben Tage sollst du des Tages zurichten einen Bock als Sündopfer. Und einen Farren, ein junges Rind und einen Widder von der Herde ohne Fehl sollen sie zurichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Sieben Tage sollen sie den Altar sühnen und ihn reinigen und seine Hände füllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'Und haben sie die Tage vollendet, so soll geschehen am achten Tage und fernerhin, daß die Priester auf dem Altare zurichten eure Brandopfer und eure Dankopfer, und Ich werde Wohlgefallen an euch haben, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Und er brachte mich zurück des Weges zum äußeren Tor des Heiligtums, das nach Osten gewendet ist, und es war verschlossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'Und Jehovah sprach zu mir: Dies Tor soll verschlossen sein, es werde nicht geöffnet, und kein Mann gehe durch dasselbe ein; sondern Jehovah, der Gott Israels, geht durch dasselbe ein, und es sei verschlossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Doch der Fürst, da er Fürst ist, soll darin sitzen, um Brot zu essen vor Jehovah. Des Weges der Halle des Tores soll er eingehen und auf seinem Wege ausgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Und Er brachte mich herein des Weges des Tores gen Mitternacht auf die Vorderseite des Hauses, und ich sah und siehe, es erfüllte die Herrlichkeit Jehovahs das Haus Jehovahs, und ich fiel auf mein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'Und Jehovah sprach zu mir: Menschensohn, nimm es dir zu Herzen, und siehe mit deinen Augen und höre mit deinen Ohren alles, was Ich mit dir rede von allen Satzungen des Hauses Jehovahs und allen seinen Gesetzen, und nimm dir zu Herzen das Eingehen in das Haus mit all dem Ausgehen aus dem Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'Und sprich zu den Widerspenstigen, zum Hause Israels: So spricht der Herr Jehovah: Zuviel für euch sind all eure Greuel, Haus Israels,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'Darum, daß ihr Söhne des Auslandes, unbeschnittenen Herzens und unbeschnittenen Fleisches, hereinbrachtet, daß sie in Meinem Heiligtum sein sollten, Mein Haus zu entweihen, indem ihr Mein Brot, das Fett und das Blut darbrachtet, und Meinen Bund mit allen euren Greueln zunichte machtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'Und nicht selbst die Hut Meiner Heiligtümer hütet, und sie euch zu Hütern der Hut Meines Heiligtums setztet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'So spricht der Herr Jehovah: Kein Sohn des Auslandes, unbeschnittenen Herzens und unbeschnittenen Fleisches, soll kommen in Mein Heiligtum, von allen Söhnen des Auslandes, die inmitten der Söhne Israels sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Noch die Leviten, die sich von Mir entfernten bei der Abirrung Israels, das von Mir abirrte ihren Götzen nach; und sie sollen tragen ihre Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'Und sie sollen in Meinem Heiligtum Dienste tun, bestellt über die Tore des Hauses, und im Hause Dienste tun, sie sollen das Brandopfer und das Schlachtopfer schlachten für das Volk und vor ihnen stehen, um ihnen Dienst zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Weil sie ihnen Dienst taten vor ihren Götzen, und dem Hause Israels ein Anstoß zur Missetat wurden, darum habe Ich Meine Hand aufgehoben über sie, spricht der Herr Jehovah, daß sie ihre Missetat tragen sollen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'Und sie dürfen nicht zu Mir hinzutreten, um Mir Priesterdienst zu tun, noch herzutreten zu irgendeinem Meiner Heiligtümer, zu dem Heiligen des Heiligen, daß ihre Schande sie tragen und ihre Greuel, die sie taten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Und Ich gebe sie, die Hut des Hauses zu hüten für allen Dienst desselben, und was darinnen ist zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Und die Priester, die Leviten, Zadoks Söhne, welche die Hut Meines Heiligtums hüteten, indes die Söhne Israels von Mir abirrten, sie sollen Mir nahen, Mir Dienst zu tun, und sollen vor Mir stehen, Mir Fett und Blut darzubringen, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Sie sollen in Mein Heiligtum eingehen, und sie nahen Meinem Tisch, um Mir Dienst zu tun, und hüten Meine Hut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Und soll geschehen, wenn sie zu den Toren des inneren Vorhofes eingehen, sollen sie leinene Kleider anziehen, und keine Wolle soll auf sie kommen, wenn sie in den Toren des inneren Vorhofs und im Hause Dienst tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Leinene Kopfbünde sollen auf ihrem Haupte sein, und leinene Beinkleider sollen an ihren Lenden sein, sie sollen sich nicht im Schweiße gürten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Und wenn sie in den äußeren Hof hinausgehen, in den äußeren Vorhof zum Volk, sollen sie ausziehen ihre Kleider, in denen sie Dienst getan, und sie in den Zellen der Heiligkeit niederlegen und andere Kleider anziehen, auf daß sie nicht das Volk durch ihre Kleider heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'Und sie sollen ihr Haupt nicht bescheren, aber das Haar auch nicht frei wachsen lassen, verschneiden sollen sie ihre Häupter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Und Wein soll kein Priester trinken, wenn in den inneren Vorhof sie eingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'Und eine Witwe und eine Verstoßene sollen sie sich nicht zu Weibern nehmen, sondern Jungfrauen aus dem Samen des Hauses Israel; aber eine Witwe, die eines Priesters Witwe ist, mögen sie nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'Und sollen unterweisen Mein Volk in dem Unterschied zwischen dem Heiligen und dem Gemeinen, und den zwischen Unreinem und Reinem ihnen zu wissen tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'Und im Rechtsstreite sollen sie stehen, zu richten nach Meinen Rechten; sie sollen ihn richten. Und Meine Gesetze und Meine Satzungen sollen sie halten bei allen Meinen Festzeiten, und heiligen Meine Sabbathe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Und zu einem toten Menschen sollen sie nicht hineinkommen und sich verunreinigen; nur bei Vater und bei Mutter und bei Sohn und bei Tochter, bei Bruder und bei Schwestern, die keinen Mann gehabt haben, mögen sie sich verunreinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'Und nach seiner Reinigung sollen sie ihm sieben Tage zählen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'Und an dem Tage, da er zum Heiligtum, zum inneren Vorhof hereinkommt, um Dienst zu tun im Heiligtum, soll er sein Sündopfer darbringen, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'Und ihr Erbe, das sie haben sollen: Ich bin ihr Erbe. Und ihr sollt ihnen kein Eigentum geben in Israel: Ich bin ihr Eigentum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Das Speiseopfer und das Sündopfer und das Schuldopfer, die sollen sie essen, und alles Verbannte in Israel soll ihnen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'Und die Erstlinge von allen Erstgeburten, von allem, und alles Hebeopfer von allem, von euren Hebeopfern sollen die Priester haben, und die Erstlinge eures Teiges gebt dem Priester, auf daß Segen ruhe auf deinem Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Alles Gefallene und Zerfleischte vom Gevögel und vom Vieh sollen die Priester nicht essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'Und wenn ihr das Land durch das Los verteilt zum Erbe, sollt ihr für Jehovah eine Hebe heben als Heiliges vom Land, die Länge sei fünfundzwanzigtausend in die Länge, und die Länge zehntausend. Heilig sei es in all seiner Grenze ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Von diesem sei für das Heiligtum fünfhundert bei fünfhundert ins Gevierte ringsum und fünfzig Ellen sei sein Weichbild ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'Und sollst von diesem Maß messen in die Länge fünfundzwanzigtausend und in die Breite zehntausend, und darauf soll das Heiligtum, das Heilige des Heiligen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Das Heiligtum vom Lande ist für die Priester, die Diener des Heiligtums; die zum Dienst tun Jehovah nahen, und ihnen sei es zum Orte für Häuser und das Geheiligte als Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'Und fünfundzwanzigtausend in die Länge und zehntausend in die Breite soll für die Leviten sein, die Diener des Hauses, ihnen zum Eigentum für zwanzig Zellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'Und als Eigentum der Stadt sollt ihr geben fünftausend in die Breite und in die Länge fünfundzwanzigtausend entlang der Hebe für das Heiligtum. Es sei für das ganze Haus Israel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'Und für den Fürsten sei hüben und drüben von der Hebe des Heiligtums und dem Eigentum der Stadt, vor der Hebe des Heiligtums und vor dem Eigentum der Stadt, von der Meeresseite dem Meere zu, und von der Ostseite dem Osten zu; und die Länge sei entlang einem der Teile von der Grenze meerwärts bis zur Grenze ostwärts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'Es sei ihm zum Lande, zum Eigentum in Israel; und nicht mehr sollen Meine Fürsten Mein Volk bedrücken und sollen das Land dem Hause Israels geben für seine Stämme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'So spricht der Herr Jehovah: Es ist genug für euch, ihr Fürsten Israels. Tut weg Gewalttat und Verheerung, und tut Recht und Gerechtigkeit, und hebt auf eure Austreibungen von Meinem Volk, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Eine Waage der Gerechtigkeit und ein Ephah der Gerechtigkeit und ein Bath der Gerechtigkeit seien bei euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Ephah und Bath sollen ein Maß sein, so daß man das Bath als ein Zehntel vom Chomer halte und das Ephah den Zehntel des Chomers. Nach dem Chomer soll sein ihr Maß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'Und ein Schekel sei zwanzig Gerah, und zwanzig Schekel, fünfundzwanzig Schekel, fünfzehn Schekel sei bei euch die Mine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'Das soll die Hebe sein, die ihr hebet: Ein Sechstel Ephah von dem Chomer Weizen, und ein Sechstel Ephah von dem Chomer Gerste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'Und die Satzung vom Öl, das Bath Öl, der zehnte Teil des Baths vom Cor. Zehn Bath sind ein Chomer; denn zehn Bath machen ein Chomer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'Und ein Schaf von der Herde von zweihundert von den bewässerten Wiesen Israels zum Speiseopfer und zum Brandopfer und zu Dankopfern, um für sie zu sühnen, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Alles Volk im Lande sei für diese Hebe an den Fürsten in Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'Und auf dem Fürsten seien die Brandopfer und das Speiseopfer und das Trankopfer an den Festen und an den Neumonden und an den Sabbathen bei allen Festversammlungen des Hauses Israel. Er soll das Sündopfer und das Speiseopfer und das Brandopfer und die Dankopfer bringen, zu sühnen für das Haus Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'So spricht der Herr Jehovah: Im ersten am ersten des Monats sollst du einen Farren nehmen, ein junges Rind, ohne Fehl, und das Heiligtum entsündigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'Und der Priester soll von dem Blut des Sündopfers nehmen und an die Türpfosten des Hauses und an die vier Ecken der Einfassung des Altars und an die Türpfosten am Tor des inneren Vorhofs sprengen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Und du sollst also tun am siebenten des Monats wegen des Mannes, der sich versehen, und wegen des Einfältigen, auf daß ihr sühnt für das Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Im ersten, am vierzehnten Tag des Monats soll bei euch das Paschah sein, das Fest der sieben Tage; Ungesäuertes sollt ihr essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'Und am selben Tage soll der Fürst für sich und für das ganze Volk des Landes einen Farren als Sündopfer bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'Und die sieben Tage des Festes soll er als Brandopfer Jehovah sieben Farren opfern und sieben Widder ohne Fehl die sieben Tage täglich, und als Sündopfer einen Bock der Ziegen täglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'Und als Speiseopfer soll er ein Ephah für den Farren und ein Ephah für den Widder und für das Ephah ein Hin Öl nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Im siebenten, am fünfzehnten Tag des Monats soll er am Feste dasselbe tun, sieben Tage, nach dem Sündopfer, nach dem Brandopfer und nach dem Speiseopfer und nach dem Öl..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'So spricht der Herr Jehovah: Das Tor des inneren Vorhofs, das gegen Osten ist gewendet, soll die sechs Werktage geschlossen sein, aber am Sabbathtage soll es geöffnet werden; auch am Tag des Neumonds soll es geöffnet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'Und der Fürst soll eingehen des Weges durch die Halle des äußeren Tores, und stehen an dem Türpfosten des Tores, und die Priester sollen zurichten sein Brandopfer und seine Dankopfer, und er soll an der Schwelle des Tores anbeten und hinausgehen, und das Tor soll bis zum Abend nicht geschlossen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'Und das Volk des Landes soll am Eingang desselben Tores anbeten vor Jehovah an den Sabbathen und an den Neumonden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'Und das Brandopfer, das der Fürst Jehovah darbringen soll am Tag des Sabbaths, sind sechs Lämmer ohne Fehl und ein Widder ohne Fehl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'Und das Speiseopfer: ein Ephah auf den Widder, und zu den Lämmern ein Speiseopfer, eine Gabe seiner Hand und ein Hin Öl auf das Ephah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'Und am Tag des Neumonds seien es ein Farren, ein junges Rind ohne Fehl und sechs Lämmer und ein Widder ohne Fehl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'Und ein Ephah auf den Farren und ein Ephah auf den Widder soll er als Speiseopfer bringen, und für die Lämmer, wie seine Hand reichen mag, und ein Hin Öl auf das Ephah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'Und wenn der Fürst eingeht, soll er des Weges der Vorhalle des Tores eingehen und herausgehen seines Weges.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Und wenn das Volk des Landes hineingeht vor Jehovah an den Feiertagen, soll, wer des Weges durch das Tor der Mitternacht eingeht, um anzubeten, herausgehen auf dem Weg des Tores nach Mittag, und wer auf dem Weg des Tores nach Mittag ist eingegangen, gehe hinaus auf dem Weg des Tores nach Mitternacht. Er kehre nicht zurück auf dem Weg des Tores, auf dem er eingegangen ist, sondern gehe stracks vor sich hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Der Fürst aber soll in der Mitte der Einziehenden einziehen, und wenn sie ausziehen, sollen sie ausziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'Und an den Festen und an den Feiertagen sei das Speiseopfer ein Ephah für den Farren und ein Ephah für den Widder, und für die Lämmer eine Gabe seiner Hand, und Öls ein Hin für das Ephah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'Und wenn der Fürst als Freiwillgabe ein Brandopfer oder Dankopfer Jehovah freiwillig machen will, so öffne man ihm das Tor, das nach Osten gewendet ist, und er mache sein Brandopfer und seine Dankopfer, wie er am Sabbathtage tut, und er gehe hinaus und man schließe das Tor, nachdem er hinausgegangen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'Und ein einjährig Lamm ohne Fehl sollst du täglich dem Jehovah als Brandopfer machen; Morgen für Morgen sollst du es machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'Und als Speiseopfer sollst du darauf Morgen für Morgen das Sechstel eines Ephah tun, und Öl ein Drittel Hin, das Semmelmehl damit zu beträufeln, dem Jehovah als Speiseopfer, ewige Satzungen beständiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Und sie sollen das Lamm und das Speiseopfer und das Öl Morgen für Morgen als ein beständig Brandopfer bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'So spricht der Herr Jehovah: Wenn der Fürst einem Manne von seinen Söhnen eine Gabe gibt, so ist sie sein Erbe, es ist für seine Söhne. Ihr Eigentum ist es als Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Wenn er aber an einen von seinen Knechten eine Gabe von seinem Erbe gibt, so soll es ihm sein bis zum Jahr der Freilassung, und es kommt zurück an den Fürsten. Allein sein Erbe soll für seine Söhne sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Und der Fürst soll nichts nehmen von dem Erbe des Volkes, sie zu verdrängen aus ihrem Eigentum. Aus seinem Eigentum soll er seinen Söhnen Erbe geben, auf daß Mein Volk nicht zerstreut werde, der Mann aus seinem Eigentum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'Und der Engel brachte mich in den Eingang zur Seite des Tores zu den Zellen des Heiligtums, zu denen der Priester, die der Mitternacht sind zugewendet; und siehe, da war ein Ort an ihren Seiten gegen das Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'Und er sprach zu mir: Dies ist der Ort, allwo die Priester das Schuldopfer und das Sündopfer kochen, wo sie das Speiseopfer backen, auf daß sie es nicht in den äußeren Hof hinausbringen, um das Volk zu heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Und er brachte mich hinaus in den äußeren Vorhof und ließ mich herumgehen nach den vier Winkeln des Vorhofs, und siehe, ein Vorhof war in dem Winkel des Vorhofs, ein Vorhof in dem Winkel des Vorhofs;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'In den vier Winkeln des Vorhofs Vorhöfe mit Rauchfängen, vierzig in der Länge und dreißig in der Breite. Ein Maß war für die viere in den Winkeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'Und eine Einfriedung war ringsum an ihnen, rings um die viere; und Kochherde gemacht unter den Einfriedungen ringsum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'Und er sprach zu mir: Dies ist das Haus der Küchen, darin des Hauses Diener kochen das Schlachtopfer des Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'Und er brachte mich zurück an den Eingang des Hauses. Und siehe, Wasser kamen heraus unter der Schwelle des Hauses gegen Osten; denn des Hauses Vorderseite ist gegen Osten, und die Wasser kamen herab unter der rechten Seite des Hauses, zu Mittag vom Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Und er brachte mich heraus des Weges durch das Tor gegen Mitternacht, und er ließ mich den äußeren Weg herumgehen zum äußeren Tor, auf dem Weg gegen Osten gewendet, und siehe, die Wasser quollen von der rechten Seite hervor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'Als der Mann hinausging gegen Osten, da war eine Meßschnur in seiner Hand, und er maß tausend mit der Elle, und führte mich durch die Wasser: Wasser der Knöchel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Und er maß tausend und führte mich durch die Wasser hindurch: Wasser der Knie; und er maß tausend, und führte mich hindurch: Wasser der Lenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Und er maß tausend; ein Bach, durch den ich nicht hindurchgehen konnte; denn die Wasser waren hoch, Wasser zum Schwimmen, ein Bach, da man nicht hindurchgehen konnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'Und er sprach zu mir: Siehst du, Menschensohn? Und er führte mich und brachte mich zurück an das Ufer des Baches.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Als ich zurückkam, da siehe, es waren am Ufer des Baches sehr viele Bäume hüben und drüben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Und er sprach zu mir: Diese Wasser fließen hinaus zum östlichen Umkreis, und kommen hinab auf das Blachfeld, und kommen zum Meere; und werden sie in das Meer hinausgeführt, so werden die Wasser geheilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'Und geschehen wird, daß jegliche lebendige Seele, die da kreucht, wohin die Bäche kommen, lebt, und der Fische sehr viel sein wird; weil diese Wasser dahin kommen, so werden sie geheilt, und alles lebt, wohin der Bach wird kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'Und es wird geschehen, daß Fischer werden daran stehen; von Engedi bis Enegla- jim werden sie Garne ausbreiten; und nach seiner Art wird ihr Fisch sein, wie der Fisch des großen Meeres, sehr viel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'Seine Lachen und seine Pfützen werden nicht geheilt, sie sind dem Salze übergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'Und an dem Bache steigen auf hüben und drüben an seinem Ufer jeglicher Baum zur Speise. Nicht welkt sein Blatt, und seine Frucht geht nicht zu Ende; gemäß seinen Monaten treibt er Erstlinge; denn seine Wasser gehen aus vom Heiligtum. Und seine Frucht ist zum Essen und sein Blatt zur Arznei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'So spricht der Herr Jehovah: Dies ist die Grenze, zu der ihr das Land zum Erbe verteilen sollt an die zwölf Stämme Israels: Für Joseph Schnüre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'Und ihr sollt es erben, der eine Mann, wie sein Bruder, weil Ich Meine Hand aufhob, es euren Vätern zu geben, darum dies Land euch zum Erbe fallen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'Und dies ist des Landes Grenze: Auf der Seite nach Mitternacht, vom großen Meer an, des Weges nach Chethlon, wo man nach Zedad kommt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Chamath, Berothah, Sibraim, das zwischen der Grenze von Damask und zwischen der Grenze von Chamath ist, das mittlere Chazer an der Grenze Chaurans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Und die Grenze sei vom Meere aus nach Chazar, Enon, die Grenze von Damask, und die von Mitternacht, gen Mitternacht, und die Grenze Chamaths: und das ist die Seite gen Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'Und die Seite gegen Osten ist zwischen Chauran und zwischen Damask und zwischen Gilead, und zwischen dem Lande Israels der Jordan. Von der Grenze gegen das östliche Meer sollt ihr messen. Und das ist die Seite nach Osten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'Und die Seite gen Mittag sei südwärts, von Thamar bis zum Haderwasser Kadesch, nach dem Bache, dem großen Meere zu, und dies sei die Südseite mittagwärts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'Und die Seite des Meeres ist das große Meer von der Grenze bis gegenüber von da, wo man nach Chamath kommt; das ist die Seite nach dem Meere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'Und ihr sollt dieses Land unter euch, die Stämme Israels, verteilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'Und es soll geschehen, daß ihr es als Erbe zufallen lasset euch und den Fremdlingen, die in eurer Mitte weilen und Söhne gezeugt haben in eurer Mitte; und sie sollen euch wie Eingeborene sein unter den Söhnen Israels, mit euch soll ihnen das Erbe fallen inmitten der Stämme Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'Und es soll geschehen, daß in dem Stamme, da der Fremdling verweilt, ihr ihm dort sein Erbe gebet, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Und das sind die Namen der Stämme: Vom Ende gen Mitternacht, zur Seite des Weges nach Chethlon, wo man kommt gen Chamath, Chazar Enan an der Grenze von Damask, mitternachtwärts, zur Seite Chamaths von der Ostecke zum Meere ist eins für Dan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'Und an der Grenze Dans von der Ostecke bis zur Ecke meerwärts, hat Ascher eines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'Und an der Grenze Aschers von der Ostecke bis zur Ecke meerwärts hat Naphthali eines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'Und an der Grenze Naphthalis von der Ostecke bis zur Ecke meerwärts hat Menascheh eines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'Und an der Grenze Menaschehs von der Ecke ostwärts bis zur Ecke meerwärts hat Ephraim eines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'Und an der Grenze Ephraims von der Ecke ostwärts und bis zur Ecke meerwärts hat Ruben eines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'Und an der Grenze Rubens von der Ostecke bis zur Ecke meerwärts hat Jehudah eines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'Und an der Grenze Jehudahs von der Ostecke bis zur Ecke meerwärts soll die Hebe sein, die ihr heben sollt, fünfundzwanzigtausend in die Breite, und in die Länge wie einer der Teile von der Ecke ostwärts bis zur Ecke meerwärts, und in seiner Mitte sei das Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Die Hebe, die ihr Jehovah hebet, soll in die Länge fünfundzwanzigtausend und in die Breite zehntausend sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'Und für diese soll die Hebe der Heiligkeit sein den Priestern, gegen Mitternacht fünfundzwanzigtausend und gegen das Meer zehntausend in die Breite, und gegen Osten zehntausend in die Breite, und gegen Mittag in die Länge fünfundzwanzigtausend, und in ihrer Mitte sei Jehovahs Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Es soll sein für die Priester, die geheiligt sind von den Söhnen Zadoks, welche die Hut gehütet, die nicht abgeirrt, als die Söhne Israels abirrten, wie die Leviten abgeirrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'Und eine Hebe von der Hebe des Landes soll ihnen sein, das Heilige des Heiligen bei der Grenze der Leviten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Und die Leviten sollen haben der Grenze der Priester entlang fünfundzwanzigtausend in die Länge, und in die Breite zehntausend. Die ganze Länge soll sein fünfundzwanzigtausend und die Breite zehntausend;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'Und sollen nichts davon verkaufen noch vertauschen, noch veräußern das Erstling des Landes, denn Heiligkeit ist es dem Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'Und die fünftausend, die übrig sind in der Breite vorn an den fünfundzwanzigtausend, sollen gemeines Land sein, für die Stadt zum Wohnen und zum Weichbilde, und die Stadt sei in der Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'Und das sind ihre Maße: Die Mitternachtseite viertausendfünfhundert, und die Mittagseite viertausendfünfhundert, und die Ostseite viertausendfünfhundert, und die Meerseite viertausendfünfhundert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'Und das Weichbild der Stadt soll sein gen Mitternacht zweihundertfünfzig, und gen Mittag zweihundertfünfzig, und gen Osten zweihundertfünfzig, und gegen das Meer zweihundertfünfzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'Und was neben der Hebe des Heiligtums noch übrigbleibt in der Länge entlang der Hebe der Heiligkeit, zehntausend gegen Osten und zehntausend dem Meere zu, und ist entlang der Hebe des Heiligtums, dessen Ertrag sei zum Brot für die, welche der Stadt dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Und die, so in der Stadt dienen, sollen aus allen Stämmen Israels ihr dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Die ganze Hebe sei fünfundzwanzigtausend bei fünfundzwanzigtausend; als Geviertes sollt ihr die Hebe des Heiligtums heben zum Eigentum der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Und das übrige sei für den Fürsten hüben und drüben an der Hebe der Heiligkeit und am Eigentum der Stadt vorn an den fünfundzwanzigtausend der Hebe bis zur Grenze gen Osten und meerwärts, vor den fünfundzwanzigtausend bei der Grenze meerwärts, den Teilen entlang sei für den Fürsten; und die Hebe der Heiligkeit und das Heiligtum des Hauses seien in dessen Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'Und von dem Eigentum der Leviten, vom Eigentum der Stadt, die inmitten dessen sind, das des Fürsten ist, zwischen der Grenze Jehudahs und der Grenze Benjamins, das sei des Fürsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'Und von den übrigen Stämmen von der Ecke ostwärts bis zur Ecke meerwärts hat Benjamin einen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'Und an der Grenze Benjamins von der Ecke ostwärts bis zur Ecke meerwärts hat Simeon einen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'Und an der Grenze Simeons von der Ecke ostwärts bis zur Ecke meerwärts hat Jissaschar einen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'Und an der Grenze Jissaschars von der Ecke ostwärts bis zur Ecke meerwärts hat Sebulon einen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'Und an der Grenze Sebuluns von der Ecke ostwärts bis zur Ecke meerwärts hat Gad einen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'Und an der Grenze Gads auf der Seite gen Mittag südlich sei die Grenze von Thamar bis zum Haderwasser, von Kadesch bis gegen den Bach hin zum großen Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'Dies ist das Land, das ihr als Erbe den Stämmen Israels zufallen lassen sollt, und dies sind ihre Teile, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'Und dies sind die Ausgänge der Stadt: von der Ecke der Mitternacht viertausendfünfhundert sei ihr Maß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'Und die Tore der Stadt seien nach dem Namen der Stämme Israels: drei Tore gen Mitternacht, ein Tor Ruben, ein Tor Jehudah, ein Tor Levi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'Und auf der Ecke gen Osten viertausendfünfhundert; und drei Tore, und zwar: Tor Joseph eines, Tor Benjamin eines und Tor Dan eines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'Und auf der Mittagseite viertausendfünfhundert das Maß, und drei Tore: Tor Schimeon eines, Tor Jissaschar eines, Tor Sebulun eines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Die Seite nach dem Meer viertausendfünfhundert. Ihrer Tore sind drei: ein Tor Gad, ein Tor Ascher, Naphthali ein Tor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Ringsum achtzehntausend, und der Name der Stadt sei von dem Tage an Jehovah allda!.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'Im dritten Jahre der Regierung Jehojakims, des Königs von Jehudah, kam Nebuchadnezzar, der König von Babel, nach Jerusalem und belagerte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'Und der Herr gab Jehojakim, den König von Jehudah, und einen Teil der Geräte des Hauses Gottes in seine Hand, und er brachte sie hinein in das Land Schinear in das Haus seines Gottes, und brachte die Geräte hinein in das Haus des Schatzes seines Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'Und der König sprach zu Aschpenas, dem Hauptmann seiner Verschnittenen, er solle einige von den Söhnen Israels und vom Samen des Königtums und von den Vornehmen hereinbringen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'Knaben, die keinerlei Fehl an sich hätten, und von gutem Aussehen, und klug in aller Weisheit und kundig an Wissen und einsichtsvoll an Kenntnis, und welche die Kraft hätten, zu stehen im Palaste des Königs, und sie Schrift und Zunge der Chaldäer lehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'Und der König bestimmte ihnen den Bedarf des Tages an seinem Tage von den leckeren Speisen des Königs und von dem Wein, den er trank, und drei Jahre sollten sie großgezogen werden, und am Ende derselben vor dem König stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Und es waren unter ihnen von den Söhnen Jehudahs: Daniel, Chananjah, Mischael und Asarjah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'Und der Oberste der Verschnittenen legte ihnen Namen bei und nannte Daniel Beltschazzar, und Chananjah Schadrach, und Mischael Meschach, und Asarjah Abed Nego.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Daniel aber setzte sich vor in seinem Herzen, daß er sich nicht mit den leckeren Speisen des Königs und mit dem Weine, den er trank, beflecken wollte, und ersuchte den Obersten der Verschnittenen, daß er sich nicht beflecken müßte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Und Gott gab Daniel Barmherzigkeit und Erbarmen vor dem Obersten der Verschnittenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'Und der Oberste der Verschnittenen sprach zu Daniel: Ich fürchte meinen Herrn, den König, der eure Speise und euren Trank bestimmt hat: denn würde er sehen, daß eure Angesichter verdrossen wären gegen die der Knaben eures Alters, so würdet ihr mein Haupt dem König verwirken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Und Daniel sprach zu Melzar, den der Oberste der Verschnittenen über Daniel, Chananjah, Mischael und Asarjah bestimmt hatte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Versuche es doch mit deinen Knechten zehn Tage, daß man uns von den Hülsenfrüchten zu essen und Wasser zu trinken gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Und man sehe an vor dir unser Aussehen und das Aussehen der Knaben, die des Königs leckere Speisen essen, und wie du sehen wirst, so tue mit deinen Knechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Und er hörte auf sie in dieser Sache, und versuchte es mit ihnen zehn Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'Und am Ende der zehn Tage sah man, daß ihr Aussehen besser und ihr Fleisch feister war, als bei allen Knaben, die des Königs leckere Speisen aßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Und Melzar nahm ihre leckeren Speisen und den Wein, den sie trinken sollten, weg, und gab ihnen Hülsenfrüchte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Und diesen vier Knaben gab Gott Kenntnisse und Verstand in aller Schrift und Weisheit, und Daniel hatte eine Einsicht in allerlei Gesichte und Träume.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'Und am Ende der Tage, nach denen der König befohlen hatte sie hereinzubringen, brachte sie der Oberste der Verschnittenen, hinein vor Nebuchadnezzar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'Und der König redete mit ihnen, und es fand sich unter allen keiner, wie Daniel, Chananjah, Mischael und Asarjah, und sie standen vor dem König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'Und in allem Worte der Weisheit der Einsicht, über das der König sie befragte, fand er sie zehnmal über allen Magiern und Wahrsagern in seinem ganzen Reich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'Und Daniel war bis in das erste Jahr des Königs Koresch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'Und im zweiten Jahre der Regierung Nebuchadnezzars träumte Nebuchadnezzar Träume, und sein Geist war beunruhigt, und sein Schlaf war ihm dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Und der König befahl, die Magier und die Wahrsager und die Zauberer und die Chaldäer zu rufen, daß sie dem König seine Träume ansagen sollten, und sie kamen hinein und standen vor dem König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'Und der König sprach zu ihnen: Ich habe einen Traum geträumt, und mein Geist ist beunruhigt, daß ich den Traum wissen möchte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Und die Chaldäer redeten zum König aramäisch: O König, lebe in Ewigkeit, sage deinen Knechten den Traum, so wollen wir dir die Deutung anzeigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Der König antwortete und sprach zu den Chaldäern: Das Wort ist mein Ernst: Wenn ihr mir nicht den Traum kundtut und seine Deutung, so sollt ihr in Stücke zerhauen und eure Häuser zu Düngerhaufen gemacht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'Wenn ihr aber den Traum und seine Deutung anzeigt, so sollet ihr viele Gaben und Ehrensold und viele Kostbarkeiten von mir empfangen. Darum zeigt mir den Traum und seine Deutung an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Sie antworteten ihm zum zweitenmal und sprachen: Der König sage seinen Knechten den Traum, so wollen wir die Deutung anzeigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Der König antwortete und sprach: Gewiß-lich weiß ich nun, daß ihr Zeit gewinnen wollt, weil ihr erschaut habt, daß das Wort mein Ernst ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Wenn ihr den Traum mir nicht kundtut, so ist dies der alleinige Erlaß für euch: Ihr habt verabredet ein falsch und verdorbenes Wort vor mir zu sprechen, bis daß die Zeit sich ändere. Darum sagt mir den Traum, daß ich erkenne, daß ihr mir auch seine Deutung anzeigen könnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Die Chaldäer antworteten vor dem König und sprachen: Kein Mensch ist auf dem Erdboden, der das Wort dem König anzeigen könnte, alldieweil kein König, wie groß und gewaltig er auch sei, ein Ding, wie dieses, von irgendeinem Magier und Wahrsager und Chaldäer fordert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Und das Wort, das der König fordert, ist zu schwer, und einen anderen gibt es nicht, der es vor dem König anzeigen könnte, als die Götter, deren Verweilen nicht beim Fleische ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Ob alledem ward der König sehr aufgebracht und entrüstet, und befahl, alle Weisen Babels zu zerstören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'Und es erging der Erlaß, daß die Weisen sollten getötet werden, und sie suchten Daniel und seine Gesellen, um sie zu töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Da erteilte Daniel Rat und Weisung Arjoch, dem Hauptmann der Leibwachen des Königs, der ausging, die Weisen Babels zu töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'Er antwortete und sprach zu Arjoch, dem Gewalthaber des Königs: Warum ergeht so hastig der Erlaß vom König? Und Arjoch tat Daniel die Sache kund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Und Daniel ging hinein und ersuchte den König, daß er ihm Frist gebe, auf daß er dem König die Deutung anzeige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Da ging Daniel nach Haus, und tat Chananjah, Mischael und Asarjah, seinen Gesellen, die Sache kund,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'Daß sie vom Gott der Himmel Erbarmen ersuchten ob diesem Geheimnisse, damit sie Daniel und seine Gesellen nicht samt den übrigen Weisen Babels zerstörten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Da ward dem Daniel in dem Gesichte der Nacht das Geheimnis geoffenbart. Da segnete Daniel den Gott der Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel antwortete und sprach: Gesegnet sei der Name Gottes von Ewigkeit zu Ewigkeit: denn Sein ist die Weisheit und die Macht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'Und Er ändert Zeiten und Fristen, läßt Könige dahingehen und läßt erstehen Könige, Er gibt Weisen die Weisheit und Wissenschaft denen, die Einsicht kennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'Er offenbart die Tiefen und das Verborgene, Er weiß, was in der Finsternis ist, und bei Ihm wohnt das Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Dich, o Gott meiner Väter, bekenne ich und preise Dich, Der Du mir Weisheit und Macht gegeben hast, und mich jetzt hast wissen lassen, was wir von Dir ersuchten, Der Du uns hast die Sache des Königs kundgetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Deswegen ging Daniel hinein zu Arjoch, den der König bestimmt hatte, die Weisen Babels zu zerstören. Er ging hin und sprach zu ihm also: Die Weisen Babels sollst du nicht zerstören, bringe mich hinein vor den König, und ich werde dem König die Deutung anzeigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Da brachte Arjoch den Daniel eilig hinein vor den König und sprach zu ihm also: Ich habe einen Mann von den Söhnen der Verbannung aus Jehudah gefunden, der dem König die Deutung kundtun wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Der König antwortete und sprach zu Daniel, dessen Name Beltschazzar war: Ver- magst du den Traum, den ich geschaut, und dessen Deutung mir kundzutun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel antwortete vor dem König und sprach: Das Geheimnis, das der König gefordert hat, vermögen Weise, Wahrsager, Magier und Sterndeuter dem König nicht anzuzeigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Jedoch ist ein Gott in den Himmeln, Der Geheimnisse offenbart, und ließ den König Nebuchadnezzar wissen, was in den letzten der Tage sein wird. Dein Traum und das Gesicht deines Hauptes auf deinem Lager ist dies:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Du, König, warst mit deinen Gedanken auf deinem Lager; sie gingen dahin, was wohl hernach sein werde? Und Der da offenbart Geheimnisse, tat dir kund, was da sein wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Und mir ist nicht durch eine Weisheit, die in mir wäre vor allen, die da leben, dies Geheimnis geoffenbart worden, sondern damit sie die Deutung dem König kundtun möchten und du die Gedanken deines Herzens wissest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Du, König, schautest und siehe, ein gewaltig Standbild war da, dies Standbild war groß und sein Glanz über die Maßen, und stand dir gegenüber, und war schauerlich anzusehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Das Haupt dieses Standbildes war von gutem Gold, seine Brust und seine Arme von Silber, sein Bauch und seine Hüften von Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'Seine Schenkel von Eisen, seine Füße waren teils von Eisen und teils von Ton.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Solches schautest du, bis daß ein Stein ausgehauen ward, nicht durch Hände, und stieß das Standbild an seine Füße, die Eisen und Ton waren, und zermalmte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Da wurden mit einem Mal das Eisen, der Ton, das Erz, das Silber und das Gold zermalmt, und sie wurden wie Spreu von den Tennen des Sommers, und der Wind nahm sie weg, so daß man ihre Stätte nicht mehr ausfand, und der Stein, der an das Standbild stieß, ward zu einen großen Felsen, und füllte die ganze Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'Dies ist der Traum, und seine Deutung wollen wir vor dem Könige sagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Du, o König, bist der König der Könige, dem der Gott der Himmel das Königtum, die Gewalt und die Stärke und Herrlichkeit gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'Und überall, da Menschensöhne verweilen, das wilde Tier des Feldes und das Gevögel der Himmel hat Er in deine Hand gegeben und dich schalten lassen über sie alle: du bist das Haupt von Gold.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'Und nach dir ersteht ein anderes Reich, niedriger denn das deine, und ein anderes drittes Reich von Erz, das auf der ganzen Erde schalten wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'Und das vierte Reich wird stark sein wie das Eisen, alldieweil das Eisen alles zermalmt und zerschlägt, und wie das Eisen, das zerschmettert all dies, wird es zermalmen und zerschmettern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'Und da du schautest die Füße und die Zehen teils vom Ton des Töpfers und teils von Eisen, so wird es ein zerteiltes Reich sein, und von der Beständigkeit des Eisens wird darinnen sein, alldieweil du erschautest, daß Eisen mit dem schlammigen Ton vermengt war,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'Und da die Zehen der Füße teils von Eisen und teils von Ton waren, so wird das Reich teilweise stark, und teilweise gebrechlich sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Und weil du erschautest das Eisen mit schlammigem Ton vermengt, so werden sie durch Samen des Menschen sich vermengen, aber nicht kleben das eine an dem anderen, so wie Eisen sich nicht mit Ton vermengen läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'Und in den Tagen dieser Könige wird der Gott der Himmel ein Königreich aufrichten, das in Ewigkeiten nicht umgestoßen, und dessen Königtum keinem anderen Volk überlassen werden wird. Es wird zermalmen und wegraffen alle jene Königreiche, es wird aber bestehen in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'Alldieweil du erschautest, daß ein Stein ausgehauen ward aus dem Felsen nicht durch Hände, und zermalmte das Eisen, das Erz, den Ton, das Silber und das Gold; hat der große Gott den König wissen lassen, was hernach sein wird, und gewiß ist der Traum, und seine Deutung wahrhaftig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Da fiel der König Nebuchadnezzar auf sein Antlitz, und betete an vor Daniel und befahl, ihm Speiseopfer und Ruheopfer zu spenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Der König antwortete dem Daniel und sprach: Es ist eine Wahrheit, daß euer Gott ist der Gott der Götter, und der Herr der Könige, und Er offenbart Geheimnisse, weil du vermochtest dies Geheimnis zu offenbaren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Da machte der König Daniel groß und gab ihm viele große Gaben, und ließ ihn schalten über die ganze Landschaft Babel, und machte ihn zum Hauptvorsteher über alle die Weisen Babels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Und Daniel ersuchte den König, daß er einsetzen sollte über die Verwaltung der Landschaft Babel Schadrach, Meschach und Abed Nego; und Daniel war im Tore des Königs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Der König Nebuchadnezzar machte ein Standbild von Gold, seine Höhe sechzig Ellen, seine Breite sechs Ellen; er richtete es auf in der Ebene Dura in der Landschaft Babel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Und der König Nebuchadnezzar sandte aus, daß zusammentreten die Satrapen, Landvögte, Statthalter, Oberrichter, Schatzmeister, Richter, Rechtsgelehrten und alle Verwalter der Landschaften, zur Einweihung des Standbildes zu kommen, das der König Nebuchadnezzar aufgerichtet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Da traten zusammen die Satrapen, die Landvögte und die Statthalter, die Oberrichter, die Schatzmeister, die Richter, die Rechtsgelehrten und alle Verwalter der Landschaften zur Einweihung des Standbildes, das der König Nebuchadnezzar hatte aufgerichtet, und sie traten vor das Bild, das Nebuchadnezzar aufgerichtet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'Und der Herold rief mit Macht: Euch wird es gesagt: ihr Völker, Volksstämme und Zungen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Zur Zeit, da ihr hören werdet den Schall des Horns, der Pfeife, der Harfe, der Sambuke, des Psalters, der Sackpfeife und allerlei Saitenspiele, sollt ihr niederfallen und anbeten das Standbild von Gold, das der König Nebuchadnezzar aufgerichtet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Und wer nicht niederfällt und anbetet, der soll im selben Augenblick mitten in den Ofen, der mit Feuer brennt, hinabgeworfen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Darum zur Zeit, da alle Völker den Schall des Horns, der Pfeife, der Harfe, der Sambuke, des Psalters und von allerlei Saitenspiel hörten, fielen alle Völker, Volksstämme und Zungen nieder, und beteten das Standbild von Gold an, das der König Nebuchadnezzar aufgerichtet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Darum, zur selben Zeit, nahten sich chaldäische Männer und klagten die Juden an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Sie antworteten und sagten zu dem König Nebuchadnezzar: Lebe, o König, in Ewigkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Du hast, o König, eine Weisung erlassen, daß jeder Mensch, wenn er höre den Schall des Horns, der Pfeife, der Harfe, der Sambuke, des Psalters, der Sackpfeife und allerlei Saitenspiel, niederfallen und das Standbild von Gold anbeten soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'Wer aber nicht niederfällt und anbetet, der soll mitten in den Ofen, der mit Feuer brennt, hinabgeworfen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'Da sind jüdische Männer, die du zur Verwaltung der Landschaft Babel eingesetzt, Schadrach, Meschach und Abed Nego. Diese Männer haben nicht auf deine Weisung geachtet, o König. Deinen Gott verehren sie nicht, und das Standbild von Gold, das du aufgerichtet, beten sie nicht an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Da befahl Nebuchadnezzar in Wut und Grimm, Schadrach, Meschach und Abed Nego herbeizubringen. Da brachten sie diese Männer vor den König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nebuchadnezzar antwortete und sprach zu ihnen: Ist es aus Vorsatz, daß ihr, Schadrach, Meschach und Abed Nego, meinen Gott nicht verehrt und das Standbild von Gold nicht anbetet, das ich aufgerichtet habe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Nun denn, wenn ihr bereit seid, zur Zeit, da ihr hört den Schall des Horns, der Pfeife, der Harfe, der Sambuke, des Psalters, der Sackpfeife und allerlei Saitenspiel, niederzufallen und das Standbild anzubeten, das ich gemacht habe - und wenn ihr es nicht anbetet, sollt ihr augenblicklich mitten in den Ofen, der mit Feuer brennt, hinabgeworfen werden! Und wer ist der Gott, der euch aus meinen Händen befreien kann?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Da antworteten Schadrach, Meschach und Abed Nego, und sprachen zu dem König Nebuchadnezzar: Es ist nicht notwendig, daß wir auf die Rede erwidern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Siehe, unser Gott, Den wir verehren, vermag uns aus dem Ofen, der mit Feuer brennt, zu befreien, und aus deiner Hand, o König, wird Er uns befreien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'Und wenn nicht, so wisse, o König, daß wir deinen Gott nicht verehren, und das goldene Standbild, das du aufgerichtet hast, nicht anbeten wollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Da ward Nebuchadnezzar voll Grimmes und das Bild seines Antlitzes veränderte sich wider Schadrach, Meschach und Abed Nego. Er antwortete und befahl, den Ofen siebenmal mehr zu heizen, als man ihn jemals hatte heizen geschaut;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'Und den Männern, den Helden der Tapferkeit in seiner Streitmacht, befahl er, Schadrach, Meschach und Abed Nego zu binden, um sie in den Ofen, der mit Feuer brennt, hinabzuwerfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Da wurden diese Männer gebunden in ihren Beinkleidern, ihren Unterkleidern und ihren Mänteln und ihren Anzügen, und wurden mitten in den Ofen, der mit Feuer brennt, hinabgeworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Weil das Wort des Königs so hastig war, und der Ofen über die Maßen geheizt worden, tötete die Flamme des Feuers die Männer, die Schadrach, Meschach und Abed Nego hinaufbrachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'Und diese drei Männer, Schadrach, Meschach und Abed Nego fielen gebunden mitten in den Ofen, der mit Feuer brennt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Da entsetzte sich der König Nebuchadnezzar und stand bestürzt auf, hob an und sprach zu seinen Räten: Haben wir nicht drei Männer gebunden mitten ins Feuer hinabgeworfen? Sie antworteten und sprachen zum König: Gewißlich, o König!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Er antwortete und sprach: Siehe, ich schaue vier Männer lose mitten im Feuer umhergehen, und haben keinen Schaden an sich und das Aussehen des vierten gleicht einem Sohne der Götter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Da nahte Nebuchadnezzar dem Tor des Ofens, der mit Feuer brennt, hob an und sprach: Schadrach, Meschach und Abed Nego, ihr Knechte des höchsten Gottes, geht heraus und kommt her. Da gingen Schadrach, Meschach und Abed Nego mitten aus dem Feuer heraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'Und die Satrapen, die Landvögte, die Statthalter und die Räte des Königs traten zusammen, und schauten die Männer, über deren Leib das Feuer nicht schaltete, und das Haar von deren Haupt nicht versengt, und deren Beinkleider nicht verändert waren, und an die der Geruch des Feuers nicht gekommen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Da hob Nebuchadnezzar an und sprach: Gesegnet sei der Gott von Schadrach, Meschach und Abed Nego, Der Seinen Engel gesandt und Seine Knechte, die auf Ihn vertrauten, befreit hat, daß sie das Wort des Königs und ihre Leiber hingaben, daß sie einen anderen Gott, als ihren Gott, nicht verehrten und ihn anbeteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Und von mir ergeht die Weisung, daß jegliches Volk, jeder Volksstamm und jede Zunge, die gegen den Gott Schadrachs, Meschachs und Abed Negos etwas spricht, soll in Stücke zerhauen und sein Haus zu einem Düngerhaufen gemacht werden, alldieweil daß kein anderer Gott ist, der erretten kann, wie Dieser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Dann gab der König dem Schadrach, Meschach und Abed Nego Gedeihen in der Landschaft Babel. Nebuchadnezzar, der König an alle Völker, Volksstämme und Zungen, die wohnen auf der ganzen Erde, euer Friede mehre sich! Es hat mir gefallen, die Zeichen und Wunder, die der höchste Gott an mir getan, euch anzuzeigen. Seine Zeichen, wie groß sind sie, und wie gewaltig Seine Wunder, Sein Reich ist ein Reich der Ewigkeit, und Seine Herrschaft zu Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Ich, Nebuchadnezzar, war ruhig in meinem Hause und gedeihlich in meinem Palast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Da schaute ich einen Traum, und schauderte, und die Gedanken auf meinem Lager und die Gesichte meines Hauptes bestürzten mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Da erging von mir eine Weisung, alle Weisen Babels vor mich zu bringen, daß sie mir die Deutung des Traumes kundtun möchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Da kamen herein die Magier, die Wahrsager, die Chaldäer und die Sterndeuter, und ich sagte vor ihnen den Traum, aber sie machten mir seine Deutung nicht kund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'Und zuletzt trat vor mich Daniel, dessen Name ist Beltschazzar, wie der Name meines Gottes, und in dem der Geist der heiligen Götter ist, und ich sagte vor ihm den Traum:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Beltschazzar, du Oberster der Magier, von dem ich weiß, daß der Geist der heiligen Götter in dir ist, und daß dir kein Geheimnis zu schwer ist: Sage mir die Gesichte meines Traumes, die ich geschaut, und die Deutung davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Und dies sind die Gesichte meines Hauptes auf meinem Lager: Ich schaute, und siehe, ein Baum inmitten der Erde, und seine Höhe war gewaltig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Der Baum ward groß und stark, und bis an die Himmel reichte seine Höhe, und er war zu schauen bis an das Ende der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Sein Gezweige war schön, und seiner Frucht viel, und Nahrung an ihm für alle, und das Tier des Feldes hatte Schatten unter ihm, und auf seinen Ästen verweilten die Vögel der Himmel, und alles Fleisch nährte sich von ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Ich schaute in Gesichten meines Hauptes auf meinem Lager, und siehe, ein Wächter und ein Heiliger stieg von Himmel herab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Er rief mit Macht und sprach also: Hauet um den Baum, und hauet ab seine Äste, streifet ab sein Gezweige und streut umher seine Frucht. Es fliehe weg unter ihm das Getier und die Vögel von seinen Ästen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Doch den Stamm seiner Wurzel belasset in der Erde, aber in Banden von Eisen und Erz, im jungen Grün auf dem Felde. Und mit dem Tau der Himmel werde er benetzt, und mit dem Getier habe er sein Teil am Kraut der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Sein Herz soll von dem eines Menschen verändert, und ihm das Herz eines Tieres gegeben werden, und sieben Zeiten sollen über ihn hingleiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'Im Beschlusse der Wächter ist die Sache, und auf dem Befehl der Heiligen das Betreffnis zu dem Ende, daß erkennen die Lebendigen, daß der Höchste Gewalt hat über das Reich des Menschen und gibt es, wem er will, und den niedrigsten der Menschen darauf erhebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Diesen Traum schaute ich, der König Nebuchadnezzar, und du, Beltschazzar, sage mir die Deutung, alldieweil alle Weisen meines Reiches nicht vermögen, mir die Deutung kundzutun, du aber vermagst es, denn der Geist der heiligen Götter ist in dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Da war Daniel, dessen Name Beltschazzar ist, bei einer Stunde lang in Erstaunen, und seine Gedanken machten ihn bestürzt. Der König hob an und sprach: Beltschazzar, der Traum und seine Deutung mache dich nicht bestürzt! Beltschazzar antwortete und sprach: Mein Herr! Der Traum sei für die, so dich hassen, und seine Deutung deinen Widersachern!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Der Baum, den du schautest, daß er groß und stark ward, und dessen Höhe bis an die Himmel reichte, und der auf der ganzen Erde zu schauen war,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Und dessen Gezweige schön und dessen Frucht viel war, und Nahrung für alle darauf, unter dem das Tier des Feldes verweilte, und auf dessen Ästen die Vögel der Himmel wohnten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Dies bist du, o König, der du groß und stark wurdest, und deine Größe wuchs und reichte bis zu den Himmeln, und deine Herrschaft bis an das Ende der Erde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Und daß der König schaute einen Wächter und einen Heiligen herabsteigen von den Himmeln, und daß er sprach: Hauet den Baum um und zerstört ihn, aber den Stamm seiner Wurzeln belasset in der Erde und in Banden von Eisen und Erz im jungen Grün des Feldes, und vom Tau der Himmel werde er benetzt und habe sein Teil mit dem Getier des Feldes, bis daß sieben Zeiten über ihm hingleiten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'Dies ist die Deutung, o König! und solcher Beschluß des Höchsten ergeht über meinen Herrn, den König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'Dich verstößt man von dem Menschen, und bei dem wilden Tier des Feldes mußt du verweilen, und sie lassen dich das Kraut schmecken wie die Ochsen und vom Tau der Himmel benetzt werden; und sieben Zeiten werden hingleiten über dich, bis daß du erkennst, daß der Höchste schaltet über das Reich des Menschen und es gibt, wem Er will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'Daß sie aber sagten: man solle den Stamm der Wurzeln des Baumes belassen: Dein Königtum soll dir bestehen, daß du wissest, daß die Himmel schalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'Darum, o König, laß dir meinen Rat gefallen und brich ab von deinen Sünden durch Gerechtigkeit, und von deinen Verkehrtheiten durch Gnade gegen die Elenden, wenn deine Ruhe soll verlängert werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Das alles traf den König Nebuchadnezzar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'Am Ende von zwölf Monden erging er sich auf dem Palast des Königtums in Babel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Da hub der König an und sprach: Ist dies nicht die große Babel, die ich erbaut habe zum Königshause durch die Stärke meiner Macht und zum Ruhme meiner Ehre?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Noch war das Wort im Munde des Königs, da fiel eine Stimme vom Himmel: Dir, König Nebuchadnezzar, wird gesagt: das Reich ist von dir gewichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Und von den Menschen wirst du verstoßen und bei dem Getier des Feldes wirst du verweilen, gleich den Ochsen lassen sie das Kraut dich schmecken, und sieben Zeiten werden über dich hingleiten, bis du wissest, daß der Höchste schaltet über das Reich des Menschen, und gibt es dem, dem Er Sich zuneigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'Zur selben Stunde ward das Wort an Nebuchadnezzar vollzogen, und von den Menschen ward er verstoßen, und wie die Ochsen aß er vom Kraut, und vom Tau der Himmel ward sein Leib benetzt, bis daß sein Haar wuchs wie das der Adler, und seine Nägel wie Vogelklauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Und am Ende der Tage hob ich, Nebuchadnezzar, meine Augen auf zu den Himmeln, und meine Erkenntnis kehrte mir zurück, und ich segnete den Höchsten, und pries und ehrte Ihn, Der da lebt in Ewigkeit, Dessen Herrschaft eine ewige Herrschaft ist, und Dessen Reich ist zu Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'Und alle Bewohner der Erde sind als nichts zu achten, und nach Seiner Neigung tut Er mit der Streitmacht der Himmel und mit denen, die auf der Erde wohnen. Und da ist keiner, der Seiner Hand wehrete und zu Ihm spräche: Was tust du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'Zur selben Zeit kam mir meine Kenntnis zurück, und die Pracht meines Reiches, meine Ehre und mein Glanz kehrte mir zurück, und meine Räte und meine Großen suchten mich, und ich ward wieder in mein Königtum eingesetzt und über die Maßen Größe ward mir hinzugetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Nun preise und erhöhe und ehre ich, Nebuchadnezzar, den König der Himmel, Dessen ganzes Tun ist Wahrheit, und Dessen Pfade sind Gericht, und die, so im Übermut dahingehen, vermag Er zu erniedrigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'König Belschazzar machte seinen tausend Großen ein großes Mahl und trank vor den Tausenden Wein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Belschazzar befahl, als er den Wein geschmeckt, die Gefäße von Gold und von Silber zu bringen, die sein Vater Nebuchadnezzar aus dem Tempel in Jerusalem weggenommen, daß daraus tränken der König und seine Großen, seine Gemahlinnen und seine Kebsen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Da brachten sie die goldenen Gefäße, die sie aus dem Tempel des Hauses Gottes in Jerusalem hinweggenommen hatten, und der König und seine Großen, seine Gemahlinnen und Kebsen tranken daraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Sie tranken den Wein und priesen die Götter von Gold und von Silber, von Erz, von Eisen, von Holz und von Stein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'Zur selben Stunde kamen Finger der Hand eines Menschen hervor und schrieben dem Leuchter gegenüber auf den Kalk der Wand des Palastes des Königs, und der König schaute das Gelenke der Hand, die schrieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Da veränderte sich des Königs Farbe und seine Gedanken machten ihn bestürzt, und die Bande seiner Lenden lösten sich und seine Knie schlugen eins ans andere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Da rief der König mit Macht, man solle die Wahrsager, die Chaldäer und die Sterndeuter hereinbringen; der König hob an und sprach zu den Weisen Babels: Jeder Mensch, der diese Schrift liest und ihre Deutung mir anzeigt, soll in Purpur gekleidet werden, eine Halskette von Gold um den Hals haben und als der Dritte im Königreich schalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Da kamen herein alle Weisen des Königs, aber sie vermochten nicht, die Schrift zu lesen, noch deren Deutung dem König kundzutun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Da ward der König sehr bestürzt, und seine Farbe veränderte sich, und auch seine Großen wurden verwirrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Die Königin wegen der Worte des Königs und seiner Großen trat in den Tranksaal, und die Königin hob an und sprach: Der König lebe ewiglich; laß dich deine Gedanken nicht bestürzt machen und dein Gesicht sich nicht verändern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Es ist ein Mann in deinem Königreich, in dem der Geist der heiligen Götter ist; und in den Tagen deines Vaters ist Erleuchtung und Verstand und Weisheit wie die Weisheit der Götter in ihm erfunden worden, und der König Nebuchadnezzar, dein Vater, hat ihn zum Obersten der Magier, der Wahrsager, der Chaldäer, der Sterndeuter eingesetzt, dein Vater, der König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'Alldieweil ein Geist über die Maßen, und Kenntnis und Verstand, die Deutung von Träumen und das Anzeigen von Rätseln, und die Auflösung knotiger Fragen in ihm ist erfunden worden, in Daniel, dem der König den Namen Beltschazzar beilegte. Nun rufe man Daniel, und er wird die Deutung anzeigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Da ward Daniel hereingebracht vor den König. Der König hob an und sprach zu Daniel: Du bist Daniel, von den Söhnen der Verbannung Jehudahs, die mein Vater, der König, aus Jehudah gebracht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Und ich habe von dir gehört, daß der Geist der Götter in dir ist, und Erleuchtung und Verstand und Weisheit über die Maßen in dir ist erfunden worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'Und nun wurden vor mich geführt die Weisen, die Wahrsager, auf daß sie diese Schrift lesen und deren Deutung mir kundtun, aber sie vermögen nicht die Deutung des Wortes anzuzeigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'Und ich hörte von dir, daß du Deutungen zu deuten und knotige Fragen aufzulösen vermögest. Wenn du nun vermagst, die Schrift zu lesen und ihre Deutung mir kund zu tun, sollst du dich mit Purpur anziehen und eine Halskette von Gold um deinen Hals haben, und als der Dritte im Königreich schalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Da antwortete Daniel und sprach vor dem König: Deine Gaben seien dein und deinen Ehrensold gib einem anderen! Jedoch die Schrift will ich dem König lesen und die Deutung ihm zu wissen tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'O du König, der höchste Gott hatte Nebuchadnezzar, deinem Vater, das Königreich und die Größe und die Pracht und die Ehre gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'Und vor der Größe, die Er ihm gab, erzitterten alle Völker, Volksstämme und Zungen und scheuten sich vor ihm. Wen er wollte, tötete er, und wen er wollte, ließ er am Leben, und wen er wollte, erhöhte er, und wen er wollte, erniedrigte er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Und darob erhöhte sich sein Herz, und sein Geist ward stark, so daß er vermessen handelte, und er ward vom Thron seines Königtums hinabgestoßen, und seine Pracht wich von ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'Und von den Menschensöhnen ward er verstoßen, und sein Herz machte er gleich mit dem Tier, und mit den wilden Eseln verweilte er und schmeckte Kraut wie die Ochsen, und von dem Tau des Himmels ward sein Leib benetzt, bis daß er erkannte, daß der höchste Gott schaltet über des Menschen Reich, und wen Er will, über sie einsetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'Und du, sein Sohn, Belschazzar, hast dein Herz nicht erniedrigt, während du all dies wußtest;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'Und hast dich erhöht über den Herrn der Himmel, und die Gefäße Seines Hauses vor dich bringen lassen; und du und deine Großen, deine Gemahlinnen und deine Kebsen haben Wein daraus getrunken, und die Götter aus Silber und Gold, Erz, Eisen, Holz und Stein, die nicht schauen und nicht hören und nichts wissen, gepriesen, und dem Gott, in Dessen Hand dein Odem ist und all deine Pfade sind, Ihn hast du nicht geehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Darum hat Er von Ihm das Gelenk der Hand ausgereckt und diese Schrift gezeichnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'Und das ist die Schrift, die gezeichnet ist: Mene, mene, tekel, upharsin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'Dies ist die Deutung des Wortes: Mene, Gott hat gezählt dein Königtum und hat es vollendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'Tekel, du bist in der Waage gewogen und mangelnd erfunden worden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'Peres, zerteilt wird dein Königreich und den Medern und Persern gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Da befahl Belschazzar, und man zog dem Daniel Purpur an und eine Halskette von Gold um seinen Hals, und riefen aus über ihn, daß er als Dritter schalten solle im Königreich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'In derselben Nacht ward Belschazzar, der König der Chaldäer, getötet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Und Darius, der Meder, empfing das Königreich, da er zweiundsechzig Jahre alt war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'Und es gefiel Darius, daß er über das Königreich hundertzwanzig Satrapen einsetzte, die in dem ganzen Königreich sein sollten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Und über sie drei Fürsten, von denen einer Daniel war, so daß ihnen diese Satrapen Rechenschaft geben sollten, und der König keinen Schaden hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Da übertraf dieser Daniel die Fürsten und die Satrapen, alldieweil ein Geist über die Maßen in ihm war; und der König gedachte ihn über das ganze Reich einzusetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Deshalb suchten die Fürsten und die Satrapen eine Sache zu finden wider Daniel von seiten des Königreichs; aber sie vermochten keine Sache und keine Verdorbenheit zu finden, denn er war treu und kein Fehler und keine Verdorbenheit ward an ihm gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Da sprachen diese Männer: Wir werden an diesem Daniel keine Sache finden, wofern wir nicht etwas wider ihn im Gesetze seines Gottes finden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Da bestürmten diese Fürsten und Satrapen den König und sprachen zu ihm also: Ewiglich lebe der König Darius!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Es sind alle Fürsten des Königreiches, die Landvögte und die Satrapen, die Räte und die Statthalter zu Rate gegangen, daß der König solle eine Satzung aufsetzen und ein Verbot bestärken, daß jeder, der eine Bitte erbittet von irgendeinem Gott oder Menschen, binnen dreißig Tagen, außer von dir, o König, in die Löwengrube hinabgeworfen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Nun solltest du, o König, das Verbot aufsetzen und das Schreiben unterzeichnen, auf daß es nicht geändert werde, als ein Gesetz von Medien und Persien, das nicht vergeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'Darum unterzeichnete der König Darius denn die Schrift und das Verbot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Und als Daniel wußte, daß die Schrift unterzeichnet war, ging er in sein Haus; und die Fenster waren offen in seinem Obergemach gegen Jerusalem hin, und dreimal des Tages kniete er auf seine Knie und betete und bekannte vor seinem Gott, gleichwie er vordem getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Da stürmten diese Männer herein und fanden Daniel, wie er ersuchte und flehte vor seinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Da nahten sie und sprachen vor dem König über das Verbot des Königs: Hast du nicht ein Verbot unterzeichnet, daß jeder Mensch, der von irgendeinem Gott oder Menschen binnen dreißig Tagen außer von dir, o König, etwas ersuche, in die Löwengrube hinabgeworfen werden solle? Der König antwortete und sprach: Fest steht das Wort als Gesetz von Medien und Persien, das nicht vergeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Da antworteten sie und sprachen vor dem Könige: Daniel, der einer der Söhne der Verbannung von Jehudah ist, hat nicht Acht auf dich, o König, und auf das Verbot, das du unterzeichnet hast, und dreimal des Tages ersucht er sein Ersuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Als der König dies Wort hörte, ward er sehr betrübt darob, und war besorgt für Daniel, daß er ihn befreite und bestrebte sich bis Sonnenuntergang, daß er ihn errettete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Da stürmten diese Männer herein zu dem Könige und sprachen zum König: Wisse, o König, daß es ein Gesetz von Medien und Persien ist, daß kein Verbot oder Satzung, vom König aufgesetzt, verändert werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'Da befahl der König und sie brachten Daniel herbei und warfen ihn hinab in die Löwengrube. Der König hob an und sprach zu Daniel: Dein Gott, Den du unablässig verehrst, befreie dich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Und es ward ein Stein gebracht, und auf die Öffnung der Grube gelegt, und mit dem Siegelring des Königs und dem Siegelring seiner Großen versiegelt, auf daß sein Wille über Daniel nicht verändert werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'Da ging der König weg in seinen Palast und brachte die Nacht in Fasten zu, und ließ keine Tänzerinnen vor sich kommen, und sein Schlaf floh weg von ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'Dann mit der Morgenröte, mit dem Lichte erhob sich der König und ging in Eile nach der Löwengrube.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Und wie er der Grube nahte, schrie er mit schmerzlicher Stimme zu Daniel. Der König hob an und sprach zu Daniel: Daniel, Knecht des lebendigen Gottes, hat dein Gott, Den du unablässig verehrst, vermocht, dich von den Löwen zu befreien?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Da redete Daniel mit dem Könige: Ewig lebe der König!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Mein Gott hat Seinen Engel gesandt und den Löwen den Rachen verschlossen, daß sie mich nicht schädigten, alldieweil vor Ihm Lauterkeit an mir erfunden worden, und ich auch vor dir keinen Schaden getan habe, o König!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'Da ward der König sehr froh über ihn, und befahl, den Daniel aus der Grube heraufzubringen. Und Daniel ward aus der Grube heraufgebracht, und war keine Schädigung an ihm erfunden, weil er an seinen Gott geglaubt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Und der König befahl, daß man diese Männer bringe, die Daniel angeklagt hatten, und man warf sie, ihre Söhne und ihre Weiber in die Löwengrube hinab, und sie hatten kaum den Boden der Grube erreicht, als die Löwen ihrer mächtig wurden und all ihre Gebeine zermalmten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Da schrieb König Darius an alle Völker, Volksstämme und Zungen, die auf der ganzen Erde weilen: Euer Friede nehme zu!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'Von mir aus ergeht die Weisung, daß man in der ganzen Herrschaft meines Königreichs vor dem Gotte Daniels erzittern und sich scheuen soll: Denn Er ist der lebendige Gott, Der besteht in Ewigkeit, und Sein Reich wird nicht umgestoßen, und bis an das Ende ist Seine Herrschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'Er befreit und errettet und tut Zeichen und Wunder am Himmel und auf Erden, Er, Der Daniel aus der Gewalt der Löwen befreit hat. Und dieser Daniel hatte Gedeihen unter der Regierung des Darius und unter der Regierung von Koresch dem Perser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'Im ersten Jahre Belschazzars, König von Babel, schaute Daniel einen Traum und Gesichte seines Hauptes auf seinem Lager. Er schrieb dann den Traum nieder; er sagte den Inhalt der Sache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel hob an und sprach: Ich schaute in meinem Gesichte bei der Nacht, und siehe, die vier Winde des Himmels brachen hervor auf das große Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'Und vier große Tiere stiegen herauf aus dem Meer, eines verschieden von dem anderen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Das erste war wie ein Löwe und hatte Adlersschwingen; und ich schaute, bis seine Schwingen ihm ausgerauft wurden und es sich erhob von der Erde und richtete sich auf auf seine Füße wie ein Mensch, und ein Menschenherz ward ihm gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'Und siehe, ein anderes, zweites Tier glich einem Bären, und richtete sich auf einer Seite auf, und drei Rippen waren in seinem Rachen zwischen seinen Zähnen, und sie sagten ihm also: Stehe auf, friß viel Fleisch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Hierauf schaute ich, und siehe, ein anderes, wie ein Parder, und es hatte vier Schwingen wie ein Vogel auf seinem Rücken, und das Tier hatte vier Häupter, und ihm ward Herrschaft gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Nach diesen schaute ich in Gesichten der Nacht und siehe, ein viertes Tier, schauerlich und schrecklich und über die Maßen stark, und es hatte große Zähne von Eisen, es fraß und zermalmte und zertrat, was übrigblieb, mit seinen Füßen, und es war verschieden von allen Tieren vor ihm, und hatte zehn Hörner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Ich gab acht auf die Hörner; und siehe, ein anderes, kleines Horn kam herauf zwischen ihnen, und vor ihm wurden drei der ersten Hörner ausgerissen, und siehe, Augen wie Menschenaugen waren an diesem Horn, und ein Mund, der Großes redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Ich schaute, bis Throne hinabgeworfen wurden, und der Alte der Tage setzte Sich. Sein Gewand war weiß wie Schnee, und das Haar Seines Hauptes wie reine Wolle, Sein Thron Flammen des Feuers, dessen Räder brennendes Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Ein Strom von Feuer ergoß sich, und ging vor Ihm aus, und tausendmal Tausende dienten Ihm, und zehntausendmal Zehntausende standen vor Ihm. Das Gericht saß, und Bücher wurden geöffnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Ich schaute zu wegen der Stimme der großen Worte, die das Horn redete; ich schaute, bis daß das Tier getötet ward und sein Leib zerstört wurde und dem brennenden Feuer übergeben ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'Und den übrigen Tieren ward ihre Herrschaft genommen, aber des Lebens Länge ward ihnen gegeben, bis auf eine Frist und eine Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Ich schaute in den Gesichten der Nacht, und siehe, mit den Wolken der Himmel kam wie des Menschen Sohn und gelangte bis zum Alten der Tage, und sie ließen Ihn vor Denselben nahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'Und Ihm ward gegeben Herrschaft und Pracht und Reich, und alle Völker, Volksstämme und Zungen sollen Ihm dienen. Seine Herrschaft ist eine ewige Herrschaft, die nicht vergeht, und Sein Königtum, das nicht wird umgestoßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Und ich, Daniel, ward betrübt in meinem Geiste, inmitten seiner Hülle, und die Gesichte meines Hauptes machten mich bestürzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Ich nahte mich einem von denen, die da standen, und ersuchte ihn um Gewisses über all dies; und er sprach mit mir und tat mir die Deutung der Dinge kund:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Diese großen Tiere, deren es vier sind, sind vier Könige, die auf Erden erstehen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Aber die Heiligen des Höchsten werden das Reich empfangen, und das Reich innehaben in Ewigkeit, und in die Ewigkeit der Ewigkeiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Dann wollte ich Gewisses über das vierte Tier, das von ihnen allen verschieden war, über die Maßen schauerlich, seine Zähne von Eisen und seine Klauen von Erz, es fraß und zermalmte und zertrat den Überrest mit den Füßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'Und über die zehn Hörner auf seinem Haupte, und das andere, das heraufkam, und es fielen vor ihm drei; und dieses Horn hatte Augen und einen Mund, der Großes redete, und sein Ansehen war größer denn seiner Gesellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Und ich schaute, und dieses Horn geriet in Kampf mit den Heiligen und überwand sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'Bis daß kam der Alte der Tage und Gericht gab den Heiligen des Höchsten, und es kam die bestimmte Zeit, daß die Heiligen das Reich innehaben sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Er sprach also: Das vierte Tier ist das vierte Königreich, das sein wird auf Erden, das verschieden sein wird von allen Königreichen, und wird fressen die ganze Erde, und sie zerstampfen und zermalmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'Und was anlangt die zehn Hörner, so werden aus ihm, dem Königreiche, zehn Könige erstehen und ein anderer wird erstehen nach ihnen, und wird verschieden sein von den ersten, und wird drei Könige erniedrigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'Und er wird Worte reden wider den Höchsten, und verstören die Heiligen des Höchsten, und wird sich unterfangen, Zeiten und Gesetz zu ändern, und sie werden in seine Hand gegeben werden, eine Zeit und Zeiten und eine halbe Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Und das Gericht wird sitzen und seine Herrschaft wird man wegnehmen, vernichten und zerstören bis zum Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'Und das Reich und die Herrschaft und die Größe der Königreiche unter all den Himmeln wird dem Volk der Heiligen des Höchsten gegeben werden; Sein Reich wird sein ein Reich der Ewigkeit, und alle Herrschaften werden Ihn verehren und Ihm gehorchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Bis hierher das Ende des Wortes. Ich, Daniel, war sehr bestürzt in meinen Gedanken, und meine Farbe veränderte sich an mir und ich bewahrte das Wort in meinem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'Im dritten Jahre der Regierung Belschazzars, des Königs, erschien mir, Daniel, ein Gesichte nach dem, das mir zu Anbeginn erschienen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'Und ich sah in dem Gesichte, und es geschah, da ich es sah, da war ich auf der Burg Susan, die in der Landschaft Elam ist, und ich sah in dem Gesichte und war an dem Flusse Ulai.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'Und ich hob meine Augen auf und sah, und siehe, ein Widder stand vor dem Flusse und hatte zwei Hörner, und die Hörner waren hoch, und das eine war höher als das zweite, und das höhere wuchs später herauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Und ich sah den Widder stoßen dem Meere zu und nach Mitternacht und nach Mittag, und keine Tiere konnten vor ihm bestehen und niemand erretten von seiner Hand, und tat nach seinem Wohlgefallen und machte sich groß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'Und ich betrachtete ihn, und siehe, ein Bock von den Ziegen kam vom Abend über die Oberfläche der ganzen Erde daher und berührte die Erde nicht; und der Bock hatte ein ansehnliches Horn zwischen seinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'Und er kam zu dem Widder mit den zwei Hörnern, den ich vor dem Flusse stehen sah, und lief auf ihn zu im Grimm seiner Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'Und ich sah, daß er den Widder erreichte und sich gegen ihn erbitterte, und den Widder schlug, und seine zwei Hörner zerbrach, so daß der Widder keine Kraft hatte vor ihm zu stehen, und er ihn zur Erde warf und zerstampfte, und niemand den Widder aus seiner Hand errettete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Und der Bock von den Ziegen tat sehr groß; da er aber mächtig wurde, zerbrach das große Horn, und es kamen vier ansehnliche anstatt seiner herauf nach den vier Winden der Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'Und aus dem einen von ihnen kam ein kleines Horn hervor, und ward über die Maßen groß gen Mittag und gegen Aufgang und gegen die Zierde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'Und es wurde groß bis zum Heer der Himmel, und fällte zur Erde etliche von dem Heere und von den Sternen, und zerstampfte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Und bis zum Obersten des Heeres machte es sich groß, und nahm Ihm weg das Beständige und warf hinab die Stätte Seiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'Und das Heer ward hingegeben samt dem Beständigen zur Übertretung, und man warf die Wahrheit zur Erde, und tat es und es gelang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'Und ich hörte einen Heiligen reden, und ein Heiliger sprach zu einem, der da redete: Wie lange ist dies Gesichte, das Beständige und die verwüstende Übertretung, das Heiligtum hinzugeben und das Herr zum Zerstampfen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'Und Er sprach zu mir bis zum Abend, zum Morgen, zweitausend und dreihundert; so wird das Heilige gerechtfertigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Und es geschah, als ich, Daniel, das Gesichte sah, und dessen Verständnis suchte, und siehe, da stand einer mir gegenüber, anzusehen wie ein Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'Und ich hörte die Stimme eines Menschen zwischen dem Ulai hervor, und er rief und sprach: Gabriel, laß diesen das Gesichte verstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'Und er kam daneben, wo ich stand; und wie er kam, ward ich verstört und fiel auf mein Angesicht. Und er sprach zu mir: Merke auf, Menschensohn, denn das Gesichte ist für die Zeit des Endes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'Und wie er mit mir redete, fiel ich im tiefen Schlaf auf mein Angesicht zur Erde; und er rührte mich an, und ließ mich stehen, daß ich stand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'Und er sprach: Siehe, ich tue dir kund, was geschehen wird auf die Letzte des Unwillens: denn zur bestimmten Zeit ist das Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Der Widder mit den zwei Hörnern, den du gesehen hast, sind die Könige von Medien und Persien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Und der Bock von den Ziegen ist der König von Griechenland, und das große Horn zwischen seinen Augen, er ist der erste König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'Und daß es zerbrochen ward und vier statt seiner aufstanden, sind vier Königreiche, die aus der Völkerschaft aufstehen, aber nicht mit seiner Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'Und in der Letzte ihres Reiches, wenn die Übertreter ihr Maß erfüllt haben, wird ein König dastehen, frech von Angesicht und der Tücke versteht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'Und gewaltig wird seine Kraft, aber nicht durch seine eigene Kraft, und er wird wunderlich verderben, und es wird ihm gelingen, daß er es tue, und er wird verderben Gewaltige und das Volk der Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'Und durch seine Klugheit, und weil ihm Trug gelingt unter seiner Hand, und er wird in seinem Herzen groß tun, wird er in ihrer Sicherheit viele verderben, und stehen wider den Obersten der Obersten, und wird ohne Hand zerbrochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'Und das Gesichte des Abends und des Morgens, wovon gesagt worden ist, das ist Wahrheit; aber du sollst das Gesichte verschließen; denn es ist für viele Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Ich aber, Daniel, war dahin, und war mehrere Tage krank, aber ich stand auf und tat das Geschäft des Königs, und ich erstaunte ob der Erscheinung, und niemand verstand es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'Im ersten Jahre von Darius, dem Sohne des Achaschverosch, von dem Samen der Meder, der über der Chaldäer Reich zum König gemacht ward,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'Im ersten Jahre seines Königtums vermerkte ich, Daniel, in den Büchern die Zahl der Jahre, davon das Wort Jehovahs zum Propheten Jeremiah geschehen, daß die Verödungen Jerusalems erfüllt würden siebzig Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'Und ich wandte mein Angesicht zum Herrn Gott, zu bitten ein Gebet und ein Flehen, mit Fasten und Sack und Asche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'Und ich betete zu Jehovah, meinem Gott, und bekannte und sprach: Ach Herr, großer und furchtbarer Gott, Der Bund und Barmherzigkeit hält denen, die Ihn lieben und Seine Gebote halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Wir haben gesündigt und Missetat begangen, und ungerecht gehandelt, und uns empört, und sind von Deinen Geboten und Rechten abgewichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'Und haben nicht gehört auf Deine Knechte, die Propheten, die in Deinem Namen zu unseren Königen, unseren Obersten und Vätern und zu allem Volk des Landes geredet haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Dein, o Herr, ist Gerechtigkeit, unser aber Scham des Angesichts wie dieses Tages bei dem Mann von Jehudah und bei denen, so in Jerusalem und in ganz Israel wohnen, denen, die nahe und die fern sind in allen Landen, wohin Du sie verstoßen hast ob der Untreue, daß sie von Dir abgefallen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'O Herr, unser ist Scham des Angesichts, unseren Königen, unseren Obersten und unseren Vätern, die wir wider Dich gesündigt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Dein, o Herr, unser Gott, ist Erbarmen und Vergebung, denn wir haben uns empört wider Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'Und haben nicht gehört auf die Stimme Jehovahs, unseres Gottes, daß wir gewandelt wären nach Seinen Gesetzen, die Er durch die Hand Seiner Knechte, die Propheten, vor uns gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Und ganz Israel hat Dein Gesetz übertreten und ist abgewichen und hat nicht auf Deine Stimme gehört; darum ergoß sich über uns die Verwünschung und der Schwur, der geschrieben ist im Gesetze Moses, des Knechts Gottes, weil wir wider Ihn gesündigt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'Und Er hat Sein Wort bestätigt, das Er geredet hat über uns und über unsere Richter, die uns richteten, und über uns kommen lassen so großes Übel, desgleichen nicht geschehen unter allen Himmeln, wie es geschehen ist in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Wie im Gesetze Moses geschrieben ist, ist all dieses Böse über uns gekommen; wir aber flehten nicht an vor Jehovah, unserem Gotte, daß wir von unseren Missetaten umkehrten und merkten auf Deine Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Und der Herr ist wach gewesen mit dem Übel und hat es über uns kommen lassen; denn gerecht ist Jehovah, unser Gott, in allen Seinen Taten, die Er tut, aber wir haben nicht auf Seine Stimme gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'Und nun, Herr, unser Gott, Der Du Dein Volk mit starker Hand aus dem Lande Ägypten herausgebracht, und Dir einen Namen gemacht hast, wie er ist an diesem Tage, wir haben gesündigt und ungerecht gehandelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'Herr, nach all Deiner Gerechtigkeit wende zurück Deinen Zorn und Deinen Grimm von Deiner Stadt Jerusalem, von dem Berge Deiner Heiligkeit! Denn durch unsere Sünden und durch die Missetaten unserer Väter ist Jerusalem und Dein Volk zur Schmach geworden bei allen, die uns umgeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'Und nun höre, unser Gott, auf das Gebet Deines Knechtes und auf sein Flehen, und laß leuchten Dein Angesicht über Dein Heiligtum, das verwüstete, um des Herrn willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Neige, o Gott, Dein Ohr und höre, tue auf Deine Augen und siehe, wie verwüstet sind wir und die Stadt, über der Dein Name genannt wird, denn nicht um unserer Gerechtigkeit willen lassen wir unser Flehen vor Dein Angesicht niederfallen, sondern um Deiner vielen Erbarmungen willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'O Herr, höre, o Herr, vergib, o Herr, horche und tue es und zögere nicht, um Deiner selbst willen, o mein Gott, denn Dein Name wird über Deiner Stadt und über Deinem Volke genannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Und noch redete ich, und betete und bekannte meine Sünde und die Sünde meines Volkes Israel, und ließ mein Flehen fallen vor Jehovah, meinem Gott, für den Berg der Heiligkeit meines Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'Und noch redete ich im Gebet, da flog daher im Flug der Mann Gabriel, den ich zu Anbeginn im Gesichte gesehen, und rührte mich an um die Zeit des Speiseopfers am Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'Und er unterrichtete mich und redete mit mir und sprach: Daniel, ich bin nun ausgegangen, dich zu unterrichten in Einsicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'Zu Anbeginn deines Flehens ging das Wort aus, und ich bin gekommen, dir anzusagen, daß du bist ein Liebling; und merke du auf das Wort und merke auf die Erscheinung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Siebzig Wochen sind bestimmt über dein Volk und über die Stadt deiner Heiligkeit, zu vollenden die Übertretung und zu besiegeln die Sünden und zu sühnen die Missetat, und hereinzubringen die Gerechtigkeit der Zeitalter und zu besiegeln das Gesetz und den Propheten und zu salben das Heilige des Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Und du sollst wissen und merken: Vom Ausgehen des Wortes, daß Jerusalem wieder hergestellt und gebaut werden soll, bis auf den Messias, den Fürsten, sind es sieben Wochen und zweiundsechzig Wochen, da werden die Straße und der Graben wieder hergestellt und gebaut, aber in der Angst der Zeiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'Und nach den zweiundsechzig Wochen wird der Gesalbte ausgerottet, aber nicht für Sich. Und die Stadt und das Heiligtum wird verderben das Volk eines Fürsten, der da kommt, und sein Ende wird sein mit einer Flut, und bis zum Ende des Streites sind die Verwüstungen entschieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'Er wird aber vielen den Bund bestärken eine Woche, und in der Hälfte der Woche das Schlachtopfer und Speiseopfer zu Ende bringen, und auf den Vogel der Scheusale die Verwüstung, und bis zur Vollendung und Entscheidung wird es sich ergießen über die Verwüstung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'Im dritten Jahre des Koresch, des Königs von Persien, wurde Daniel, den man mit Namen Beltschazzar nannte, ein Wort geoffenbart, und das Wort ist Wahrheit und ein großer Heereszug; und er verstand das Wort, und es ward ihm das Verständnis des Gesichtes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'In selbigen Tagen trauerte ich, Daniel, drei Wochen der Tage,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Ich aß kein leckeres Brot, Fleisch und Wein kam nicht zu meinem Munde, auch salbte ich mich nicht mit Salben, bis die drei Wochen der Tage sich erfüllten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'Und am vierundzwanzigsten Tage des ersten Monats, da war ich am Ufer des großen Flusses, welcher ist der Chiddekel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'Und ich hob meine Augen auf und sah, und siehe, da stand ein Mann, in Linnen gekleidet, und seine Lenden gegürtet mit lauterem Gold aus Uphas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'Und sein Leib war wie ein Tharschisch, und sein Angesicht wie das Ansehen des Blitzes und seine Augen wie Fackeln von Feuer, und seine Arme und seine Füße wie der Anblick des geglätteten Erzes, und die Stimme seiner Worte wie die Stimme einer Volksmenge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'Und ich, Daniel, allein sah die Erscheinung, und die Männer, so mit mir waren, sahen die Erscheinung nicht; aber ein großes Erzittern fiel über sie, und sie entwichen, sich zu verstecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'Und ich allein verblieb und sah diese große Erscheinung; es verblieb aber keine Kraft in mir und meine Majestät verwandelte sich bis zum Verderben, und ich behielt keine Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Und ich hörte die Stimme seiner Worte, und wie ich die Stimme seiner Worte gehört, war ich in tiefem Schlaf, auf meinem Angesicht, und mein Angesicht zur Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'Und siehe, eine Hand rührte mich an und hob mich auf die Knie und auf die flachen Hände;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'Und sprach zu mir: Mann des Wohlgefallens merke auf die Worte, die ich zu dir rede und stehe auf deine Stätte, denn ich bin jetzt zu dir gesandt. Und wie er diese Worte mit mir redete, stand ich mit Beben auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Und er sprach zu mir: Fürchte dich nicht, Daniel, denn seit dem ersten Tage, da du dein Herz hingabst, Verständnis zu erlangen und dich zu demütigen vor deinem Gotte, sind deine Worte erhört worden, und ich bin gekommen um deiner Worte willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Und der Oberste des Reiches Persiens ist einundzwanzig Tage wider mich gestanden; und siehe, Michael, einer der ersten Obersten, ist gekommen, mir beizustehen, und ich blieb übrig neben den Königen von Persien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'Und ich bin gekommen, dich zu unterrichten, was in den letzten der Tage deinem Volke begegnen wird, denn das Gesichte geht noch auf Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'Und wie er so mit mir diese Worte redete, schlug ich mein Angesicht nieder zur Erde und war stumm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'Und siehe, einer, ähnlich wie ein Menschensohn, rührte an meine Lippen, und ich öffnete meinen Mund und redete und sprach zu dem, der mir gegenüber stand: Mein Herr, über der Erscheinung kehren meine Wehen sich wider mich, und ich habe keine Kraft mehr behalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Und wie vermag der Knecht dieses meines Herrn zu reden mit diesem meinem Herrn, weil seit der Zeit keine Kraft in mir besteht und kein Odem mehr in mir verblieben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Und es rührte mich wiederum einer an, der das Ansehen eines Menschen hatte, und stärkte mich,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'Und sprach: Fürchte dich nicht, Mann des Wohlgefallens, Friede sei mit dir, sei stark, sei stark! Und wie er mit mir redete, erstarkte ich und sagte: Mein Herr, rede, denn du hast mich gestärkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Und er sprach: Weißt du, warum ich zu dir gekommen bin? Und jetzt kehre ich zurück, zu streiten mit dem Obersten Persiens, aber wenn ich hinausgehe, siehe, da kommt der Oberste von Griechenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Aber ich will dir ansagen, was in der Schrift der Wahrheit verzeichnet ist, und es ist nicht einer, der sich mit mir stärkt wider diesen, als euer Oberster Michael.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'Und ich stand bei ihm im ersten Jahre des Darius, des Meders, ihn zu halten und ihm zur Stärke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'Und nun will ich dir Wahrheit ansagen: Siehe, noch drei Könige werden in Persien stehen; und der vierte wird mit größerem Reichtum sich bereichern denn alle, und wenn er am stärksten ist durch seinen Reichtum, wird er alles erregen gegen das griechische Reich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'Und ein mächtiger König wird erstehen, und eine große Herrschaft beherrschen und tun nach seinem Wohlgefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'Und wenn er so steht, wird sein Reich zerbrechen und sich nach den vier Winden der Himmel zerteilen, und nicht für seine Nachkommen, und nicht mit der Herrschaft, mit der er geherrscht, und sein Reich wird ausgerodet und anderen außer ihnen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'Und der König des Mittags und einer seiner Obersten wird stark sein, und wird stark werden wider ihn und herrschen; eine große Herrschaft wird seine Herrschaft sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'Und am Ende von Jahren werden sie sich verbünden, und die Tochter des Königs von Mittag wird zum König gen Mitternacht kommen, um das Gerade zu tun, aber sie wird die Kraft des Arms nicht behalten und er und sein Arm werden nicht bestehen, und sie wird hingegeben, sie und die sie hergeführt, so wie auch ihr Erzeuger und der, der sie gestärkt hatte in den Zeiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Aber es wird ein Reis von ihrer Wurzel an seiner Stelle erstehen und zur Streitmacht kommen, und kommen in die Festung des Königs der Mitternacht, und wider sie tun und siegen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'Und auch ihre Götter mit ihren Guß-bildern samt den kostbaren Gefäßen von Silber und Gold in Gefangenschaft wegführen nach Ägypten, und wird Jahrelang stehen vor dem König von Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Und er wird kommen in das Reich des Königs von Mittag, aber wieder auf seinen Boden zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Und seine Söhne werden Fehden erheben und eine Volksmenge vieler Streitmächte versammeln, und wird kommen und überfluten und daherfahren, und wird zurückkehren und bis zu seinen Festungen befehden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'Und der König vom Mittag wird sich erbittern und ausziehen und streiten mit ihm, mit dem König von Mitternacht, und wird aufstellen viel Volksmenge, aber die Volksmenge wird in seine Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'Und er wird die Volksmenge wegnehmen und sein Herz wird sich erhöhen, und Zehntausende fällen, wird ihn aber nicht überwältigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'Und der König von Mitternacht wird widerkommen und eine Volksmenge aufstellen, größer denn die vorige, und am Ende der Zeiten der Jahre wird er daherkommen mit großer Streitmacht und mit vieler Habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'Und in selbigen Zeiten werden viele wider den König von Mittag stehen, und auch die Söhne der Räuber deines Volkes sich erheben, so daß sie das Gesichte bestätigen, und werden straucheln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'Und wird kommen der König von Mitternacht und einen Wall aufschütten und die feste Stadt erobern, und die Arme des Mittags werden nicht bestehen, und sein auserwähltes Volk; und werden keine Kraft haben zum Widerstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'Und wer wider ihn kommt, tut nach seinem Wohlgefallen, und wird niemand vor ihm bestehen, und er wird stehen im Land der Zierde, und wird es vollenden durch seine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'Und er wird sein Angesicht richten, daß er mit der Stärke seines ganzen Reiches komme, und wird das Gerade mit ihm tun, und ihm die Tochter der Weiber geben, daß sie ihn verderbe, aber sie wird nicht bestehen, und wird nicht für ihn sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'Und er wird sein Angesicht zurückwenden wider die Inseln und viele erobern; aber ein Heerführer wird seinem Schmähen ein Ende machen, daß er ihm sein Schmähen zurückgebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'Und er wird sein Angesicht zurückwenden zu den Festen seines Landes; und er wird straucheln und fallen, und nicht gefunden werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'Und an seiner Stelle wird einer erstehen, der wird den Erpresser nach des Reiches Ehre umhersenden; aber in einigen Tagen wird er zerbrechen, doch nicht im Zorn und nicht im Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'Und an seiner Stelle steht ein Verachteter, und ihm geben sie die Majestät des Königtums nicht; und er kommt unversehens und erfaßt das Reich durch Schmeicheleien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'Und die Arme des Überflutenden werden vor ihm überflutet und zerbrochen werden, und auch der Fürst des Bundes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Denn nachdem er sich mit ihm verbündet, wird er trüglich handeln und heraufziehen, und mit wenig Völkerschaft ihn besiegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'Und wird unversehens in die fetten Plätze der Landschaft kommen und tun, was seine Väter und seiner Väter Väter nicht zu tun vermochten, mit Rauben, Beutemachen und dem Verstreuen der Habe unter sie, und wird seine Gedanken denken wider die Festungen und bis auf eine Zeit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'Und wird seine Kraft und sein Herz auferwecken wider den König vom Mittag mit großer Streitmacht. Und der König vom Mittag wird ihn befehden im Streit mit großer und sehr gewaltiger Streitmacht, wird aber nicht bestehen, denn sie werden Anschläge wider ihn ausdenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'Und die seine leckere Speise essen, werden ihn zerbrechen, und seine Streitmacht wird er überfluten, und viele Erschlagene werden fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'Und die beiden, die Könige, ihr Herz wird darauf sein, Böses zu tun, und an einem Tische werden sie Falsches miteinander reden. Es wird ihnen aber nicht gelingen, denn das Ende ist erst zur bestimmten Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'Und er wird zurückkehren in sein Land mit großer Habe und wird sein Herz setzen wider den Bund der Heiligkeit, und wird es tun und in sein Land zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Zur bestimmten Zeit wird er zurückkehren und gen Mittag kommen; aber es wird zuletzt nicht sein wie vormals.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Und es werden Schiffe aus Chitthim wider ihn kommen, und er wird sich betrüben und zurückkehren und unwillig sein wider den Bund der Heiligkeit, und wird es tun; und er wird zurückkehren und sich verständigen mit denen, die den Bund der Heiligkeit verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'Und Arme von ihm werden stehen und das Heiligtum, die Feste, entweihen und das Beständige wegtun und das verwüstende Scheusal aufstellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'Und er wird die, so ungerecht handeln wider den Bund, mit Schmeicheleien entheiligen; aber das Volk derer, so ihren Gott kennen, werden sich stärken und es tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'Und die Verständigen des Volkes werden viele zur Einsicht bringen; aber sie werden straucheln ob dem Schwerte und ob der Flamme, ob der Gefangenschaft und dem Raube, einige Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Und wenn sie straucheln, werden sie ihnen mit kleinem Beistande beistehen; aber viele werden ihnen anhangen mit Schmeicheleien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'Und von den Verständigen werden etliche straucheln, um unter ihnen abgetrieben, geläutert und weiß gemacht zu werden auf die Zeit des Endes: denn es ist noch auf die bestimmte Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'Und der König wird tun nach seinem Wohlgefallen und sich erhöhen und groß tun wider jeglichen Gott, und wider den Gott der Götter Wunderliches reden, und wird ihm gelingen, bis vollendet ist der Unwille und die Entscheidung ist gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Und er wird nicht aufmerken auf die Götter seiner Väter, noch auf die Begierde der Frauen, noch aufmerken auf irgendeinen Gott, sondern groß tun wider alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Und er wird den Gott der Befestigungen an seiner Stelle verherrlichen, und den Gott, den seine Väter nicht gekannt, mit Gold und mit Silber, und mit kostbarem Steine und mit Kleinodien verherrlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'Und er arbeitet an den Festungen der Festen mit einem ausländischen Gotte. Wer ihn anerkennt, dem mehrt er die Herrlichkeit und läßt ihn herrschen über viele, und den Boden teilt er aus zum Lohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'Und zur Zeit des Endes wird der König vom Mittag sich mit ihm stoßen, und der König von Mitternacht wird stürmen wider ihn mit Streitwagen und mit Reitern und mit vielen Schiffen, und wird in die Länder kommen und sie überfluten und durchziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'Und wird in das Land der Zierde kommen, und viele werden dahinstürzen, aber diese werden entrinnen seiner Hand: Edom und Moab und die Erstlinge der Söhne Ammons.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'Und er wird seine Hand in die Länder ausstrecken, und das Land Ägypten wird ihm nicht entkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'Und er wird herrschen über die Schätze Goldes und Silbers und über alle Kleinodien Ägyptens, und Libyer und Kuschiten in seinen Schritten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Und Gerüchte vom Aufgang und von Mitternacht machen ihn bestürzt, und mit großem Grimme zieht er aus, um viele zu vernichten und zu verbannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'Und er wird seine Palastzelte aufschlagen zwischen den Meeren, an dem Berge der Zierde der Heiligkeit; und er kommt zu seinem Ende und niemand steht ihm bei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'Und zur selben Zeit wird dastehen der große Fürst Michael, der da steht für die Söhne deines Volkes, und wird sein eine Zeit der Drangsale, dergleichen nicht gewesen ist, seit Völkerschaften da sind bis auf selbige Zeit, und in jener Zeit wird dein Volk entrinnen, ein jeder, der in dem Buche sich geschrieben findet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'Und viele derer, die im Staub des Bodens schlafen, werden erwachen, etliche zum ewigen Leben und etliche zur Schmach und zu ewiger Abneigung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'Die Verständigen aber werden glänzen wie der Glanz der Himmelsfeste, und die, so viele gerecht gemacht, wie die Sterne in Ewigkeit und immerdar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Du aber, Daniel, verschließe die Worte und versiegle das Buch bis zur Zeit des Endes; viele werden es dann durchlaufen und die Erkenntnis sich mehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Und ich, Daniel, sah, und siehe, zwei andere standen da, der eine auf diesem Ufer des Stromes und der andere auf jenem Ufer des Stromes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'Und er sprach zu dem Manne in Linnen gekleidet, der über den Wassern des Stromes war: Bis wann wird es ein Ende mit den Wundern?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'Und ich hörte den Mann, der in Linnen gekleidet war, der über den Wassern des Stromes war, und er erhob seine Rechte und seine Linke zu den Himmeln, und schwur bei Dem, Der da lebt in Ewigkeit: daß es auf eine bestimmte Zeit, bestimmte Zeiten und eine halbe sein soll, und wenn die Zerstreuung der Hand des Volkes der Heiligkeit vollendet ist, wird alles dies vollendet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'Und ich hörte es und verstand es nicht, und sprach: Mein Herr, was wird das Letzte davon sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'Und er sprach: Gehe hin, Daniel, denn die Worte sind verschlossen und versiegelt bis zur Zeit des Endes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Viele werden sich säubern und weiß machen und läutern, und Ungerechte werden ungerecht handeln, und alle Ungerechten werden nicht aufmerken, aber die Verständigen werden aufmerken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'Und von der Zeit an, wenn das Beständige abgetan und das verwüstende Scheusal eingesetzt wird, sind es tausendzweihundertneunzig Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Selig, der da wartet und erreicht die tausenddreihundertfünfunddreißig Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Und du, gehe zum Ende und ruhe, und stehe zu deinem Lose bis zum Ende der Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Das Wort Jehovahs, das geschah an Hoschea, den Sohn Beeris, in den Tagen Ussijahs, Jothams, Achas, Jechiskijahs, der Könige Jehudahs, und in den Tagen Jerobeams, des Sohnes von Tagen Jerobeams, König von Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Anbeginn dessen, was Jehovah redete durch Hoschea. Und Jehovah sprach zu Hoschea: Gehe, nimm dir ein Weib der Buhlereien und Kinder der Buhlereien, denn das Land buhlt hinweg von Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Und er ging hin und nahm Gomer, Tochter Diblajims, und sie empfing und gebar ihm einen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'Und Jehovah sprach zu ihm: Nenne seinen Namen Jisreel; denn noch um ein Kleines, so suche Ich das Blut Jisreels am Hause Jehus heim und mache ein Ende mit dem Reiche des Hauses Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'Und am selbigen Tage soll es geschehen, daß Ich den Bogen Israels zerbreche im Talgrund Jisreel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'Und sie empfing wieder und gebar eine Tochter; und Er sprach zu ihm: Nenne ihren Namen Lo-Ruchamah; denn Ich erbarme Mich fortan nicht mehr des Hauses Israel, daß Ich ihnen verzeihe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Des Hauses Jehudah aber erbarme Ich Mich und rette sie durch Jehovah, ihren Gott; und Ich helfe ihnen, nicht durch Bogen und durch Schwert und durch Streit, durch Rosse und durch Reiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Und sie entwöhnte Lo-Ruchamah, und empfing und gebar einen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'Und Er sprach: Nenne seinen Namen Lo-Ammi; denn ihr seid nicht Mein Volk; und Ich werde nicht der eurige sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Aber die Zahl der Söhne Israels wird sein wie der Sand des Meeres, den man nicht messen und nicht zählen kann; und am Orte, da man zu ihnen sagte: Ihr seid nicht Mein Volk, wird man zu ihnen sagen: Söhne des lebendigen Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Und es werden sich zusammentun die Söhne Jehudahs und die Söhne Israels allzumal, und ein Haupt über sich setzen und aus dem Lande heraufziehen; denn groß wird sein der Tag Jisreels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'Sprechet zu euren Brüdern: Ammis, und zu euren Schwestern: Ruchamah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'Hadert mit eurer Mutter, hadert, denn sie ist nicht Mein Weib, und Ich nicht ihr Mann, auf daß sie ihre Buhlereien wegtue von ihrem Angesicht, und ihre Ehebrecherei von ihren Brüsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Auf daß Ich sie nicht nackt ausziehe und hinstelle wie am Tage, da sie geboren ward, und sie mache wie die Wüste, und sie hinsetze wie ein dürres Land, und lasse sie sterben vor Durst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Und Ich Mich ihrer Söhne nicht erbarme, darum, daß sie Söhne der Buhlereien sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'Denn gebuhlt hat ihre Mutter und Schändliches tut, die sie empfangen hat. Denn sie sprach: Ich will gehen hinter meinen Liebhabern her, die mir geben mein Brot und mein Wasser, meine Wolle und mein Linnen, mein Öl und mein Getränk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'Darum siehe, Ich umhege deinen Weg mit Dornen, und ummauere dich mit einer Mauer, daß deine Steige du nicht finden sollst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Und sie setzt ihren Liebhabern nach, aber kann sie nicht erreichen, und sucht sie, aber findet sie nicht; da spricht sie: Ich will gehen und zurückkehren zu meinem ersten Manne; denn besser war es mir da, als jetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'Und sie wußte nicht, daß Ich ihr gab das Korn und den Most und das Öl, und ihr das Silber mehrte und das Gold, das sie ihrem Baale machten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Darum will Ich zurückkehren und zu seiner Zeit nehmen Mein Korn und Meinen Most zu seiner bestimmten Zeit, und ihr entreißen Meine Wolle und Mein Linnen, womit sie ihre Blöße deckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'Und nun will Ich ihre Torheit aufdecken vor den Augen ihrer Liebhaber, und kein Mann soll sie aus Meiner Hand entreißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'Und Ich will ein Ende machen all ihrer Freude, ihrem Feste, ihrem Neumond und ihrem Sabbath und all ihrem Feiertage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Und will verwüsten ihren Weinstock und ihren Feigenbaum, von denen sie sagte: Sie sind eine Buhlgabe mir, die meine Liebhaber mir gegeben; und setze sie zum Walde, daß das wilde Tier des Feldes sie frißt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'Und will heimsuchen an ihr die Tage der Baale, an denen sie ihnen räucherte, und sich schmückte mit ihrem Nasenreif und ihrem Geschmeide, und ihren Liebhabern nachging, und Mein vergaß, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'Darum siehe, Ich will sie bereden und in die Wüste bringen und ihr ans Herz reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Und Ich will ihr von da ihre Weinberge und den Talgrund Achor zur Pforte der Hoffnung geben; und sie wird singen dort wie in den Tagen ihrer Jugend, und wie am Tage ihres Heraufziehens aus dem Lande Ägypten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'Und es soll geschehen an jenem Tage, daß du Mich nennen wirst: Mein Mann, und wirst Mich nicht mehr mein Baal nennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'Und Ich will die Namen der Baale aus ihrem Munde wegtun, und sie sollen ihres Namens nicht mehr gedenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'Und Ich will ihnen an jenem Tage einen Bund schließen mit dem wilden Tier des Feldes, und mit dem Gevögel der Himmel und dem Kriechtier des Bodens, und will Bogen und Schwert und Streit zerbrechen von der Erde, und lasse sie in Sicherheit niederliegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'Und will dich mit Mir verloben in Ewigkeit, und dich Mir verloben in Gerechtigkeit und in Gericht, und in Barmherzigkeit und in Erbarmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'Und werde dich Mir verloben in Treue, und du sollst Jehovah erkennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'Und soll geschehen am selbigen Tage, daß Ich erhöre, spricht Jehovah, daß Ich erhöre die Himmel und sie werden erhören die Erde, Und die Erde soll erhören das Korn und den Most und das Öl, und diese erhören Jisreel. Und Ich will sie Mir säen im Lande, und will Mich erbarmen der Lo-Ruchamah, und sprechen zu Lo-Ammi: Mein Volk bist du, und es wird sprechen: Mein Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'Und Jehovah sprach zu mir: Gehe abermals hin, liebe ein Weib, das von einem Genossen geliebt wird und Ehebruch treibt, wie Jehovah die Söhne Israels liebt, sie aber wenden sich anderen Göttern zu und lieben Kuchen von Weinbeeren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'Und ich erkaufte sie mir um fünfzehn Silberlinge und einen Chomer Gerste und einen Lethech Gerste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'Und ich sprach zu ihr: Viele Tage sollst du bei mir wohnen; du sollst nicht buhlen und sollst keines Mannes sein, und auch ich will dein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Denn viele Tage werden die Söhne Israels wohnen ohne König, und ohne Obersten, und ohne Opfer, und ohne Denksäule, und ohne Ephod und Theraphim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Danach werden die Söhne Israels zurückkehren und suchen Jehovah, ihren Gott, und David, ihren König, und mit Schauern kommen zu Jehovah und zu Seinem Guten, in den letzten der Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Höret, ihr Söhne Israels, das Wort Jehovahs; denn einen Hader hat Jehovah mit denen, die im Lande wohnen, darum, daß keine Wahrheit und keine Barmherzigkeit und keine Kenntnis Gottes im Lande ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Eide und Verleugnung, und Morden und Stehlen und Ehebruch brechen hervor, und Blut reicht an Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Darum trauert das Land und verschmachtet alles, das darin wohnt, beim wilden Tier des Feldes, und beim Gevögel der Himmel; und auch die Fische des Meeres werden hingerafft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Nur hadere der Mann nicht, noch strafe der Mann; und dein Volk ist wie solche, die mit dem Priester hadern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'Und du strauchelst am Tage, und auch der Prophet strauchelt in der Nacht mit dir, und deine Mutter lasse Ich untergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Mein Volk geht unter, weil es ohne Kenntnis ist; weil du die Kenntnis verschmäht hast, will auch Ich dich verschmähen, daß du nicht mehr Mein Priester seiest, und weil du das Gesetz deines Gottes vergaßest, will auch Ich deine Söhne vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Je mehr ihrer wurden, desto mehr sündigten sie wider Mich; ihre Herrlichkeit will Ich in Unehre umwandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Sie essen Meines Volkes Sündopfer, und nach ihrer Missetat erheben sie ihre Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'Darum soll es mit dem Volk sein wie mit den Priestern, und Ich will seine Wege an ihm heimsuchen und nach seinem Handeln ihm zurückgeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'Und sie sollen essen und nicht satt werden, und sie werden buhlen, und doch nicht sich ausbreiten, darum, daß sie unterließen, auf Jehovah zu halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Buhlerei und Wein und Most hat ihr Herz eingenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Mein Volk befragt sein Holz, und sein Stock sagt ihm an; denn der Geist der Buhlereien hat es irregeführt; und sie buhlen weg von ihrem Gotte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Auf den Gipfeln der Berge opfern sie und räuchern auf den Hügeln, unter der Eiche und der Weißpappel und Steineiche; denn gut ist ihr Schatten. Darum buhlen eure Töchter, und eure Schnüre treiben Ehebruch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Nicht will Ich es heimsuchen an euren Töchtern, daß sie buhlen, und an euren Schnüren, daß sie ehebrechen; denn sie selbst trennen sich ab mit Buhlerinnen, und opfern mit Tempeldirnen; und das unverständige Volk wird zu Fall gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Wenn du buhlst, Israel, so verschulde sich doch Jehudah nicht. Und laß sie nicht kommen nach Gilgal und nicht hinaufgehen gen Beth-Aven, und nicht schwören: Beim Leben Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Denn wie eine störrische Kuh ist störrisch Israel, nun wird Jehovah sie wie ein Lamm auf weiter Trift weiden lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Ephraim hat sich mit den Götzen verbündet, so lasset ihn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Ihr Weintrank entweicht, sie haben gebuhlt, sie lieben, ihre Schilde geben Unehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Der Wind schnürt sie in seinen Flügeln zusammen, und sie schämen sich ob ihrem Opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Höret dies, ihr Priester, und horchet, ihr, o Haus Israel, und du, Haus des Königs; nehmt es zu Ohren; denn für euch ist das Gericht, weil ihr eine Schlinge geworden seid für Mizpah und ein ausgebreitet Netz über Tabor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'Und mit dem Schlachten vertiefen sich die, so sich wegwenden; aber Ich will ihnen allen eine Züchtigung sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Ich kenne Ephraim, und Israel ist mir nicht verhohlen; denn du, Ephraim, hast jetzt gebuhlt, Israel hat sich verunreinigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Ihre Handlungen gestatteten nicht, zu ihrem Gotte zurückzukehren; denn der Geist der Buhlereien ist in ihrem Inneren, und sie kennen Jehovah nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'Und Israels Stolz wird antworten wider sein Angesicht; und Israel und Ephraim werden straucheln durch ihre Missetat; es strauchelt auch Jehudah mit ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'Mit ihrem Kleinvieh und ihren Rindern werden sie kommen, zu suchen Jehovah, und werden Ihn nicht finden; denn Er hat Sich ihnen entzogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Dem Jehovah wurden sie untreu; denn fremde Söhne zeugten sie, nun soll sie der Neumond fressen samt ihrem Teile.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Stoßet in die Posaune in Gibeah, in die Trompete in Ramah, blaset Lärm in Beth-Aven, hinter dir her, Benjamin!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Ephraim soll zur Verwüstung werden am Tage der Strafe. Unter den Stämmen Israels habe Ich das Wahrhaftige kundgetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Die Obersten Jehudahs sind wie die, so die Grenze verrücken; auf sie will Ich wie Wasser Mein Wüten ausschütten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Bedrückt war Ephraim, zerschlagen mit Recht; denn nach dem Gebot wollte es willig wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'Und ich bin Ephraim wie die Motte, wie der Wurmfraß dem Hause Jehudahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Und Ephraim sah seine Krankheit und Jehudah seine Wunde; und Ephraim ging nach Aschur, und sandte zum König Jareb; er aber konnte euch nicht heilen und eure Wunde nicht schließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Denn wie der Löwe bin Ich Ephraim, und wie der junge Löwe Jehudahs Hause. Ich, Ich zerfleische und gehe hin; Ich trage davon, und niemand ist, der errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Ich gehe hin, Ich kehre zurück an Meinen Ort, bis daß sie ihre Schuld erkennen und Mein Angesicht suchen. In ihrer Angst werden sie früh nach Mir suchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Kommt, und lasset uns zurückkehren zu Jehovah; denn Er hat zerfleischt, und Er wird uns heilen; Er schlug, und Er wird uns verbinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Er macht uns lebendig nach zwei Tagen, am dritten Tage richtet Er uns auf, auf daß wir vor Ihm leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'Und lasset uns erkennen, und lasset uns nachjagen, zu erkennen Jehovah; wie die Morgenröte ist bereitet Sein Ausgang, und wie der Regen kommt Er zu uns, wie der Spätregen, der das Land feuchtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Was soll Ich dir tun, Ephraim? Was soll Ich dir tun, Jehudah? Und eure Barmherzigkeit ist wie die Wolke des Mor- gens, und wie der Tau, der in der Früh fortgeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Darum haue Ich unter die Propheten und erwürge sie durch Meines Mundes Reden, und deine Gerichte sind ein Licht, das ausgeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Denn an Barmherzigkeit habe Ich Lust und nicht am Opfer, und an der Erkenntnis Gottes mehr, denn am Brandopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Und sie haben gleich Adam den Bund übertreten, da wurden sie Mir untreu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gilead ist die Hauptstadt derer, die Missetat tun, mit Fußstapfen von Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'Und wie Kriegshaufen, die auf einen Mann harren, ist die Gesellschaft der Priester; auf dem Wege nach Schechem morden sie, denn Schandtaten tun sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'Schauerliches habe Ich im Hause Israels gesehen. Da buhlt Ephraim, und Israel verunreinigt sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Auch Jehudah bringt dir eine Ernte, wenn Ich die Gefangenschaft Meines Volkes zurückwenden werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Da Ich Israel heilte, ward Ephraims Missetat aufgedeckt, und die Bosheiten Samariens, wie sie Lüge tun, und der Dieb kommt, und draußen Kriegshaufen ausrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'Und sie sagen nicht zu ihrem Herzen, Ich gedenke aller ihrer Bosheiten. Nun umgeben sie ihre Handlungen ringsumher; vor Meinem Angesichte sind sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'Mit ihrer Bosheit machen den König sie froh, mit ihren Verstellungen die Obersten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Sie alle sind Ehebrecher, wie ein Ofen geheizt vom Bäcker; der Kneter feiert vom Kneten des Teiges bis zu seiner Säuerung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'Am Tage unseres Königs erkranken die Obersten von der Glut des Weins; er reicht die Hand den Spöttern hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Wenn sie ihr Herz wie einen Ofen darbringen, während sie auflauern, die ganze Nacht schläft ihr Bäcker; am Morgen brennt es wie ein flammendes Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Wie der Ofen sind sie alle erhitzt; und sie fressen ihre Richter auf. All ihre Könige fallen. Da ist keiner unter ihnen, der Mich anriefe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Ephraim vermengt sich mit den Völkern. Ephraim ist zu einem Kuchen geworden, der nicht umgekehrt worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Fremde fressen seine Kraft, und er weiß es nicht; Greisenhaar auch wird über ihn gesprengt, und er weiß es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'Und der Stolz Israels antwortet wider sein Angesicht; aber sie kehren nicht zurück zu Jehovah, ihrem Gott, und suchen Ihn nicht in alle dem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'Und Ephraim wird wie eine dumme Taube, ohne Herz. Ägypten riefen sie, nach Aschur gingen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Wie sie hingehen, breite Ich Mein Netz über sie aus, Ich bringe sie herab wie des Himmels Gevögel, züchtige sie, wie in ihrer Gemeinde gehört worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Wehe ihnen, daß sie von Mir entflohen; Verheerung über sie, daß sie von Mir abgefallen! Und Ich hätte sie eingelöst, aber sie redeten Falsches über Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'Und sie schrien nicht zu Mir in ihrem Herzen, wenn sie auf ihren Lagern heulten, ob dem Korn und Most. Sie rotteten sich zusammen und wichen ab von Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'Und Ich hätte sie in Zucht genommen und ihre Arme gestärkt, aber sie denken Böses wider Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Sie wenden sich zurück, nicht nach oben; wie der trügliche Bogen sind sie. Durch das Schwert sollen ihre Obersten fallen ob dem Unwillen ihrer Zunge. Das ist ihr Hohn im Lande Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'An deinen Gaumen die Posaune! Wie ein Adler über das Haus des Jehovah! Weil sie Meinen Bund übertreten und von Meinem Gesetz abgefallen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Sie werden schreien zu Mir: Mein Gott! Wir, Israel, erkennen Dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Das Gute hat Israel verworfen! Der Feind setze ihm nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Ohne Mich machten sie Könige, und Oberste, ohne daß Ich es wußte. Ihr Silber und ihr Gold machten sie sich zu Götzenbildern, auf daß Er ausgerottet werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Dein Kalb, Samaria, verwirft dich, Mein Zorn entbrennt wider sie. Wie lange vermögen sie nicht, sich unsträflich zu halten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Denn aus Israel ist es, und er, der Werkmann, hat es gemacht, und kein Gott ist es. Zu Stücken wird das Kalb Samariens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Denn Wind säen sie, und Sturmwind ernten sie. Eine Saat hat er nicht, und was da sproßt, gibt kein Mehl, gäbe es vielleicht, so verschlingen es die Fremden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Verschlungen ist Israel; nun sind sie unter den Völkerschaften wie ein Gefäß, an dem man keine Lust hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Weil sie hinaufzogen nach Aschur, ein Waldesel, einsam für sich. Ephraim dingt sich Liebschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Obgleich sie dingten unter den Völkerschaften, nun bringe Ich sie zusammen, und sie sollen zusammenbringen, und sie sollen anfangen sich zu mindern unter der Last des Königs der Obersten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Denn Ephraim mehrte die Altäre zur Sünde; zur Sünde sind ihm die Altäre geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Schrieb Ich ihm viele Meiner Gesetze, wie fremd wurden sie geachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Als Schlachtopfer opfern sie Mir Gaben des Fleisches, und essen es. Jehovah hat daran kein Gefallen. Er gedenkt nun ihrer Missetat, und sucht heim ihre Sünden. Sie möchten nach Ägypten zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Und Israel vergißt Dessen, Der ihn gemacht, und baut Tempel, und Jehudah mehrt die festen Städte; Ich aber will Feuer in ihre Städte senden, und es soll seine Paläste auffressen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Sei nicht froh zum Frohlocken, Israel, wie die Völker, da du von deinem Gotte fortgebuhlt; du liebtest Buhlgaben auf all deinen Tennen des Korns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Tenne und Kelterkufe soll sie nicht weiden, und der Most soll sie täuschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Sie wohnen nicht im Lande Jehovahs, und Ephraim kehrt zurück nach Ägypten, und sie essen Unreines in Aschur.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Nicht gießen sie für Jehovah Wein aus, noch sind Ihm ihre Schlachtopfer angenehm. Wie Brot der Bekümmerten sind sie für sie; alle, so davon essen, verunreinigen sich; denn ihr Brot ist für ihre Seelen, es kommt nicht in das Haus Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Was werdet ihr tun am Tage der Feier, und am Tage des Festes Jehovahs?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Denn siehe, sie sind weggezogen vor der Verheerung, Ägypten wird sie zusammenbringen, Moph sie begraben, das Kleinod ihres Silbers wird die Distel einnehmen, Dornhecken sind in ihren Zelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Gekommen sind die Tage der Heimsuchung, gekommen die Tage der Vergeltung. Wissen soll Israel: ein Narr ist der Prophet, irrsinnig der Mann des Geistes ob der Menge deiner Missetat und ob der vielen Anfeindung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Ephraim ist ein Wächter mit meinem Gott; der Prophet die Schlinge eines Vogelstellers auf allen seinen Wegen, Anfeindung im Hause seines Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Tief verdorben sind sie, wie in den Tagen Gibeahs. Er wird gedenken ihrer Missetat, wird heimsuchen ihre Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Wie Weinbeeren in der Wüste fand Ich Israel, wie den Erstling am Feigenbaum in ihrem Anfange sah Ich eure Väter. Nach Baal-Peor kamen sie, und da weihten sie sich der Schande und wurden abscheulich, wie ihr Lieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Ephraim: wie ein Vogel fliegt fort seine Herrlichkeit, von der Geburt, von dem Mutterleib und von der Empfängnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'Ja, wenn sie ihre Söhne großziehen, so mache Ich sie kinderlos, ohne Menschen. Ja, wehe auch ihnen, wenn Ich weggehe von ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Ephraim, wie Ich ihn sehe bis nach Zor, ist gepflanzt in Lieblichkeit; aber Ephraim muß seine Söhne hinaus zum Würger bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Gib ihnen, Jehovah - was sollst Du ihnen geben? - gib ihnen einen fehlgebärenden Mutterschoß und versiegende Brüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'All ihre Bosheit ist in Gilgal; daselbst hasse Ich sie. Ob der Bosheit ihrer Handlungen vertreibe Ich sie aus Meinem Haus. Nicht will Ich fürderhin sie lieben. Alle ihre Obersten sind störrisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Geschlagen ist Ephraim, ihre Wurzel verdorrt, daß sie keine Frucht bringen; und ob sie erzeugen, so wollte Ich doch ihres Leibes Begehrte töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Mein Gott verschmäht sie, darum, daß sie auf Ihn nicht hörten; und sie sollen unter die Völkerschaften entfliehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Ein abgeleerter Weinstock ist Israel; seine Frucht ist gleich wie er; nach der Menge seiner Frucht mehrte er die Altäre. Nach der Güte seines Landes machte er gut die Bildsäulen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Es schmeichelte ihr Herz. Nun werden sie verwüstet, Er wird zerwerfen ihre Altäre, zerscheitern ihre Bildsäulen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Ja, nun sprechen sie: Wir haben keinen König, weil wir Jehovah nicht fürchten; und der König, was könnte der für uns tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Sie reden Reden, mit eitlen Eiden schlie-ßen sie einen Bund. Wie Schierling sproßt auf das Gericht auf den Furchen des Feldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Um die Kälber in Beth-Aven bangen sie, der Bewohner Schomrons; denn sein Volk trauert darum, es zittern seine Götzenpriester für seine Herrlichkeit, daß sie von ihm weggeführt wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'Auch geleitet man es nach Aschur als Geschenk für den König Jareb. Scham ergreift Ephraim, und ob seinem Ratschluß schämt sich Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Schomron ist verstört, sein König ist wie der Schaum auf des Wassers Fläche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'Und vernichtet werden die Opferhöhen Avens, die Sünde Israels; Dorn und Distel kommen herauf auf ihren Altären, und sie sprechen zu den Bergen: Decket uns! und zu den Hügeln: Fallet über uns!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Seit den Tagen Gibeahs hast du gesündigt, Israel! Da standen sie; der Streit wider die Söhne der Verkehrtheit erreichte sie nicht in Gibeah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Nach Meinem Sehnen werde Ich sie züchtigen. Und versammeln sollen sich Völker wider sie, für ihre zwei Missetaten sie zu binden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'Und Ephraim ist eine abgerichtete Kalbe, die das Dreschen liebt; aber Ich will hinfahren über das Gute ihres Nackens und Ephraim reiten lassen; pflügen soll Jehudah und Jakob soll ihm eggen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Sät euch zur Gerechtigkeit; erntet nach dem Munde der Gerechtigkeit, brechet auch den Brachacker um. Und es ist Zeit Jehovah zu suchen; bis daß Er komme und euch unterweise in der Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Ihr habt Ungerechtigkeit gepflügt und Verkehrtheit geerntet, habt die Frucht der Falschheit gegessen, darum daß du auf deine Wege, auf deine vielen Helden vertrautest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Und es ersteht ein Getöse unter deinen Völkern, und alle deine Festungen werden verheert, gleich der Verheerung von SchalmanBeth-Arbel am Tage des Streites, da die Mutter mit den Söhnen zerschmettert ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'Solches tut euch Beth-El um des Bösen eures Bösen willen. Mit dem Morgenrot wird verstört der König von Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Als Israel jung war, liebte Ich ihn, und aus Ägypten rief Ich Meinen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'So man ihnen jetzt ruft, so gehen sie fort von ihrem Angesicht, opfern den Baalen und räuchern den Schnitzbildern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Ich gängelte Ephraim. Er nahm sie auf Seine Arme. Aber sie wußten nicht, daß Ich sie heilte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'Mit Stricken des Menschen zog Ich sie, mit Seilen der Liebe, und ward ihnen wie einer, der das Joch emporhebt über ihre Kinnbacken, und reichte ihm zu essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Nicht sollte er zurück nach dem Lande Ägypten kehren; und Aschur, der ist sein König, weil sie sich weigerten, zurückzukehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'Und kreisen wird das Schwert in seinen Städten und verzehren seine Riegel und auffressen wegen ihrer Ratschläge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'Und Mein Volk ist es müde, zu Mir zurückzukehren. Rufen sie ihm aufwärts, so richtet sich keiner empor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Wie soll Ich dich dahingeben, Ephraim? Soll Ich dich hinliefern, Israel? Soll Ich dich hingeben wie Adamah, dich setzen wie Zeboim? Mein Herz kehrt sich um in Mir; allzumal ist Meine Reue entbrannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Nicht will Ich tun nach Meines Zornes Entbrennen; will nicht zurückkehren, Ephraim zu verderben; denn ein Gott bin Ich, und nicht ein Mann. In deiner Mitte ist der Heilige; nicht will Ich kommen in die Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Jehovah nach werden sie gehen. Wie ein Löwe wird Er brüllen. Weil Er brüllt, werden die Söhne vom Meere einherzittern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'Einherzittern werden sie wie die Vögel aus Ägypten und wie die Taube aus dem Lande Aschur; und Ich werde sie wohnen lassen in ihren Häusern, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Umgeben hat Mich Ephraim mit Vorstellung, und mit Trug das Haus Israel; aber Jehudah herrscht noch mit Gott, und getreu mit den Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Ephraim weidet sich am Wind, und setzt dem Ostwind nach den ganzen Tag; Falschheit und Verheerung mehrt es, und sie schließen einen Bund mit Aschur, und Öl wird nach Ägypten gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'Und einen Hader hat Jehovah mit Jehudah, und wird heimsuchen Jakob nach seinen Wegen, nach seinen Handlungen ihm es zurückgeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'Im Mutterleibe hat er seinem Bruder die Ferse unterschlagen, und in seiner Vollkraft mit Gott gekämpft;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'Und gekämpft mit dem Engel und ihn übermocht. Er weinte und erflehte ihn. In Bethel sollte er ihn finden, und daselbst mit uns reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Jehovah ist der Gott Zebaoth; Jehovah ist sein Gedächtnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Und du, kehre zurück zu deinem Gott; halte Gerechtigkeit und Gericht, und hoffe beständig auf deinen Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'Kanaan hat in seiner Hand die Waage des Betrugs, er liebt zu bedrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Und Ephraim spricht: Wohl bin ich reich geworden, habe Wohlstand mir gefunden; aber bei all meinem Bemühen wird man an mir keine Missetat finden, die Sünde wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'Aber Ich bin Jehovah, dein Gott, vom Lande Ägypten her; Ich werde dich noch in Zelten wohnen lassen, wie in den Tagen der Festzeit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Und Ich rede zu den Propheten, und Ich bin es, Der des Gesichtes viel macht, und durch der Propheten Hand Gleichnisse gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'Ist Gilead ein Aven? Sie werden zur Eitelkeit. In Gilgal opfern sie Ochsen; auch sind ihre Altäre wie Steinhaufen auf den Furchen des Feldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'Und Jakobs entwich in das Gefilde Arams, und Israel diente um ein Weib, und um ein Weib hütete er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Und durch einen Propheten führte Jehovah Israel herauf aus Ägypten, und durch einen Propheten ward es gehütet. Ephraim hat gereizt durch Bitterkeiten, und Er läßt sein Blut auf ihm, und sein Herr gibt ihm zurück seine Schmach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Als Ephraim Schauderhaftes redete, trug er es in Israel; und er ward schuldig am Baal und starb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Und jetzt tut es zur Sünde hinzu, und sie haben sich ein Gußbild gemacht von ihrem Silber, in ihrer Einsicht, Götzenbilder, gänzlich gemacht von Werkleuten. Zu sich selber sagen sie: Die, so einen Menschen opfern, sollen küssen die Kälber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Daher werden sie sein wie die Wolke des Morgens und wie der Tau, der in der Früh fallend dahingeht, wie die Spreu von der Tenne verweht, und wie der Rauch aus dem Gitterfenster.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Bin Ich doch Jehovah, dein Gott vom Lande Ägypten her, und einen Gott außer Mir kennst du nicht; und ohne Mich ist kein Heiland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Ich kannte dich in der Wüste, im Lande der Gluthitze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Wie sie ihre Weide hatten, wurden sie satt, und da sie satt waren, erhöhte sich ihr Herz, so daß sie Mein vergaßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Und Ich werde ihnen sein wie ein Löwe, wie ein Pardel am Wege betrachte Ich sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'Ich treffe auf sie wie ein beraubter Bär und zerreiße den Verschluß ihres Herzens und fresse sie da wie der alte Löwe; das wilde Tier des Feldes schlitzt sie auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Dein Verderben ist es, Israel, daß du wider Mich bist, wider deinen Beistand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Wo ist nun dein König hin, daß er dich rette in allen deinen Städten, und deine Richter, da du doch sprachst: Gib mir einen König und Oberste?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Ich gebe dir einen König in Meinem Zorn und nehme ihn in Meinem Wüten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Zugebunden ist Ephraims Missetat, aufbewahrt seine Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Es kommen Geburtsnöte der Gebärerin über es; ein unweiser Sohn ist es; er steht nicht die Zeit in der Söhne Durchbruch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Aus der Hand der Hölle löse Ich sei ein; vom Tode will Ich sie erlösen. Tod, Ich will deine Pest, Hölle, Ich will dein Zerstörer sein! Reue ist vor Meinen Augen verborgen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Denn ein wilder Esel ist er unter seinen Brüdern; der Ostwind, der Wind Jehovahs, kommt, aufsteigend von der Wüste, und es vertrocknet sein Born, und sein Brunnquell trocknet aus, er plündert den Schatz jeglichen köstlichen Geräts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Schomron wird verwüstet, denn es war aufrührerisch wider seinen Gott; durch das Schwert werden seine Kindlein fallen, sie werden zerschmettert, und die Schwangeren werden aufgeschlitzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Kehre zurück, Israel, zu Jehovah, deinem Gott; denn du strauchelst in deiner Missetat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Nehmt zu euch die Worte und kehrt zurück zu Jehovah; sprecht zu Ihm: Verzeihe alle Missetat, und nimm es gut, und laß uns entrichten die Farren unserer Lippen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Aschur soll uns nicht retten, auf dem Roß wollen wir nicht reiten, und wollen nicht mehr zu unserer Hände Machwerk sagen: Unser Gott! Weil bei dir die Waise Erbarmen findet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Ich heile ihren Abfall, Ich liebe sie freiwillig; denn Mein Zorn ist von ihm zurückgewendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Wie der Tau will Ich für Israel sein, erblühen soll es gleich der Lilie, und seine Wurzel schlagen, wie der Libanon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Seine Zweige sollen dahingehen, und seine Majestät soll sein wie die des Ölbaums; und sein Geruch wie des Libanon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Zurückkehren sollen sie, die in Seinem Schatten saßen, und beleben das Korn, und erblühen, wie der Weinstock; sein Andenken soll sein wie des Weins vom Libanon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Ephraim, was sollen Mir fürder die Götzenbilder? Ich will antworten und ihm singen. Ich will sein wie die grünende Tanne. Aus Mir soll deine Frucht gefunden werden. Wer ist weise, daß er dies einsehe, einsichtsvoll, daß er es wisse? Denn gerade sind die Wege Jehovahs, und die Gerechten wandeln darauf, die Übertreter aber kommen darauf zu Fall.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Das Wort Jehovahs, welches geschah an Joel, den Sohn Pethuels,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Höret dies, ihr Ältesten, und nehmt es zu Ohren, alle Bewohner des Landes! Ist solches geschehen in euren Tagen und in den Tagen eurer Väter?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Davon erzählt euren Söhnen, und eure Söhne ihren Söhnen, und deren Söhne dem späteren Geschlecht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Was die Raupe übrig läßt, frißt die Heuschrecke, und was die Heuschrecke übrig läßt, frißt die Grille, und was die Grille übrig läßt, frißt der Schröter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Erwachet, ihr Trunkenen, und weint und heult alle Trinker des Weines, ob dem Most, daß er von eurem Munde abgeschnitten wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Denn eine Völkerschaft zieht herauf in Mein Land, mächtig und ohne Zahl, seine Zähne sind eines Löwen Zähne, und hat die Backenzähne des alten Löwen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'Meinen Weinstock setzt sie in Verwüstung, zerfetzt Meinen Feigenbaum, blößet ihn bloß, wirft ihn weg und macht seine Reben weiß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Wehklage, wie die Jungfrau, mit dem Sacke gegürtet über den Gemahl ihrer Jugend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Abgeschnitten ist Speiseopfer und Trankopfer vom Hause Jehovahs. Die Priester, Jehovahs Diener, trauern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Verheert ist das Feld, der Boden trauert; denn verheert ist das Korn, der Most ausgetrocknet, das Öl verschmachtet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Die Ackerleute sind beschämt, die Winzer heulen, ob dem Weizen und ob der Gerste, daß des Feldes Ernte ist verloren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Der Weinstock ist verdorrt und der Feigenbaum verschmachtet; Granatbaum, auch Palme und Apfelbaum, alle Bäume des Feldes sind verdorrt: denn verdorrt ist die Freude von den Söhnen des Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Gürtet euch und klagt, ihr Priester, heult, ihr Diener des Altars, kommt und liegt über Nacht in Säcken, ihr Diener meines Gottes: denn Speiseopfer und Trankopfer wird dem Hause eures Gottes vorenthalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Heiligt ein Fasten, ruft eine Festversammlung aus, versammelt die Ältesten, alle Bewohner des Landes in das Haus Jehovahs, eures Gottes, und schreit zu Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Ach des Tages! denn nahe ist der Tag Jehovahs. Und wie Verheerung von dem Verheerer wird er kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Wird nicht vor unseren Augen die Speise abgeschnitten, vom Hause unseres Gottes Fröhlichkeit und Frohlocken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Die Körner verschrumpfen unter ihren Schollen. Verwüstet sind die Speicher, eingerissen die Scheunen; denn verdorrt ist das Korn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Wie seufzt das Vieh! Verwirrt sind der Rinder Triebe; denn keine Weide haben sie, auch die Triebe des Kleinviehs sind verwüstet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'Zu dir, Jehovah, rufe ich; denn Feuer frißt die Auen der Wüste und die Flamme entflammt alle Bäume des Feldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Auch das Vieh des Feldes lechzt auf zu Dir; denn ausgetrocknet sind die Flußbette der Wasser, und Feuer frißt die Auen der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Stoßt in die Posaune in Zion und blaset Lärm auf dem Berg Meiner Heiligkeit! Zittern sollen alle, die im Lande wohnen; denn der Tag Jehovahs kommt, denn er ist nahe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'Ein Tag der Finsternis und des Dunkels, ein Tag der Wolke und der Wolkenmacht, wie die Morgenröte sich ausbreitet über die Berge, ein zahlreich und mächtiges Volk, wie keines war in Ewigkeit, noch nach ihm fürder sein wird in den Jahren von Geschlecht und Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Vor ihm her frißt Feuer und hinter ihm flammt die Flamme. Wie ein Garten Edens ist das Land vor ihm, und hinter ihm ist wie der Wüste Verwüstung; und wird vor ihm auch kein Entkommen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Wie der Rosse Ansehen ist sein Ansehen; und wie die Reiter, so laufen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Wie die Stimme der Streitwagen, so hüpfen sie auf den Häuptern der Berge daher; wie mit der Stimme der Feuerflamme, da sie die Stoppeln frißt; wie ein mächtig Volk, zum Streit geordnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Davor kreißen die Völker, alle Angesichter ziehen ihr Wangenrot ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Wie Helden laufen sie, wie Männer des Streites steigen sie auf die Mauer hinauf; und jeder Mann geht seinen Weg, nicht wechseln sie ihre Pfade um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'Und kein Mann stößt wider seinen Bruder an; jeder Mann geht auf seiner Bahn. Sie fallen unter den Geschossen und brechen nicht ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'In der Stadt rennen sie umher, auf der Mauer laufen sie, steigen in die Häuser hinauf und kommen hinein durch die Fenster, wie der Dieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Vor ihm zittert die Erde, erbeben die Himmel, Sonne und Mond werden verdunkelt und die Sterne ziehen zusammen ihren Glanz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'Und Jehovah gibt Seine Stimme hervor vor Seiner Streitmacht; denn sehr groß ist Sein Heerlager, denn zahlreich sind die, so Sein Wort tun; denn groß ist der Tag Jehovahs, und sehr furchtbar, und wer kann ihn aushalten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Aber auch jetzt, spricht Jehovah, kehrt zurück zu Mir mit eurem ganzen Herzen, und mit Fasten und mit Weinen und mit Klagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Und zerreißt euer Herz und nicht eure Kleider, und kehrt zurück zu Jehovah, eurem Gott; denn Er ist gnädig und erbarmungsvoll, langmütig und von großer Barmherzigkeit, und reuet Sich des Bösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Wer weiß, Er kehrt zurück, und es reut Ihn und Er läßt verbleiben hinter ihm einen Segen: Speiseopfer und Trankopfer für Jehovah, euren Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Stoßt in die Posaune in Zion, heiligt ein Fasten, ruft zu einer Festversammlung!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Versammelt das Volk, heiligt die Versammlung, bringt zusammen die Ältesten, versammelt die Kindlein und die Säuglinge an den Brüsten. Der Bräutigam komme heraus aus seiner Kammer, und die Braut aus ihrem Brautgemach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Zwischen der Vorhalle und dem Altar weinen die Priester, die Diener Jehovahs, und sprechen: Schone, Jehovah, Deines Volkes und gib Dein Erbe nicht hin der Schmach, daß die Völkerschaften über es herrschen. Warum sollen sie sprechen unter den Völkern: Wo ist ihr Gott?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Und Jehovah eifert für Sein Land, und bemitleidet Sein Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'Und Jehovah wird antworten und sprechen zu Seinem Volk: Siehe, Ich sende euch das Korn und den Most und das Öl, auf daß ihr davon euch sättigt, und gebe euch nicht mehr zur Schmach unter den Völkerschaften dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'Und den von Mitternacht will Ich von euch entfernen und ihn verstoßen in ein dürres, wüstes Land, sein Angesicht zum östlichen Meer und seine Nachhut an das hintere Meer, und soll sein Gestank aufsteigen und seine Fäulnis aufsteigen; denn er hat sein Tun groß gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Fürchte dich nicht, o Boden, frohlocke und sei fröhlich, daß Jehovah hat Großes getan!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Fürchtet euch nicht, ihr Vieh des Feldes, denn die Auen der Wüste keimen hervor, denn der Baum trägt seine Frucht, der Feigenbaum und der Weinstock geben ihr Vermögen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'Und ihr Söhne Zions frohlocket und seid fröhlich in Jehovah, eurem Gotte, daß Er euch gibt den Frühregen zur Gerechtigkeit, und für euch herabströmen läßt den Platzregen, den Frühregen und den Spätregen im ersten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'Und die Tennen werden voll von Getreide und die Kufen sollen von Most und Öl überfließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'Und Ich erstatte euch die Jahre, welche die Heuschrecke, die Grille, der Schröter und die Raupe fraß, Meine große Streitmacht, die unter euch Ich sandte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'Und ihr sollt essen, essen und satt werden, und den Namen Jehovahs, eures Gottes, loben, Der Wunderbares mit euch getan, und Mein Volk soll nicht beschämt werden ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'Und ihr sollt wissen, daß Ich inmitten Israels bin und Ich Jehovah bin, euer Gott, und keiner mehr. Und Mein Volk soll nicht beschämt werden ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Und es wird geschehen nach diesem, daß Ich Meinen Geist ausgieße über alles Fleisch, und weissagen werden eure Söhne und eure Töchter; eure Alten werden Träume träumen und eure Jünglinge Gesichte sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'Und auch über die Knechte und die Dienstmägde will Ich in jenen Tagen Meinen Geist ausgießen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'Und will Wahrzeichen geben in den Himmeln und auf Erden, Blut und Feuer und Säulen von Rauch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Die Sonne wird sich in Finsternis und der Mond in Blut verwandeln, bevor der Tag Jehovahs kommt, der große und der furchtbare.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Und geschehen wird, daß jeglicher, der Jehovahs Namen anrufen wird, der wird entrinnen; denn auf dem Berge Zion und in Jerusalem wird ein Entkommen sein, wie Jehovah gesprochen hat, und unter dem Rest, den Jehovah ruft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'Denn siehe, in jenen Tagen und zu selbiger Zeit werde Ich zurückbringen die Gefangenschaft Jehudahs und Jerusalems. Und alle Völkerschaften will Ich zusammenbringen und hinabführen in den Talgrund Jehoschaphat, und rechten allda mit ihnen über Mein Volk und Mein Erbe Israel, daß sie es versprengt haben unter die Völkerschaften und Mein Land geteilt; Und um Mein Volk das Los geworfen, und gegeben den Knaben um eine Buhlerin, und das Mägdlein um Wein verkauft, den sie vertranken. Und ihr auch, Zor und Zidon, und all ihr Kreise des Philisterlandes, was wollt ihr von Mir? Wollt ihr Mir mit Erwiderung vergelten? Und wollt ihr Mir erwidern? Schnell, eilends lasse Ich eure Erwiderung auf euer Haupt zurückfallen. Die ihr Mein Silber und Mein Gold habt genommen, und Mein gutes Begehrtes in eure Tempel habt gebracht; Und Jehudahs Söhne und die Söhne Jerusalems verkauft an Javans Söhne, um sie von ihrer Grenze zu entfernen; Siehe, Ich erwecke sie auf aus dem Orte, dahin ihr sie verkauft, und bringe die Erwiderung zurück auf euer Haupt. Und verkaufe eure Söhne und eure Töchter in die Hand der Söhne Jehudahs, und sie verkaufen sie an die Sabäer, an eine ferne Völkerschaft; denn Jehovah hat es geredet. Rufet dies aus unter die Völkerschaften, heiligt den Streit, weckt auf die Helden, sie sollen herzutreten, heraufziehen alle Männer des Streites! Eure Hacken schmiedet euch zu Schwertern um, zu Speeren eure Winzermesser! Es spreche der Schwache: Ich bin mächtig! Tut euch zusammen und kommt, all ihr Völkerschaften ringsumher, und kommt zusammen allda! Laß Deine Helden hinabziehen, Jehovah. Die Völkerschaften werden auferweckt und kommen herauf in den Talgrund Jehoschaphat: denn allda werde Ich sitzen, zu richten alle Völkerschaften ringsumher. Streckt aus die Sichel, denn die Ernte ist reif. Kommt, zieht hinab; denn voll ist die Kelter, die Kufen fließen über; denn viel ist ihrer Bosheit. Haufen über Haufen im Talgrund der Entscheidung; denn nahe ist der Tag Jehovahs im Talgrund der Entscheidung. Sonne und Mond verdunkeln sich und die Sterne ziehen ihren Glanz zusammen. Und Jehovah brüllt aus Zijon, und aus Jerusalem gibt Er Seine Stimme hervor, und Himmel und Erde erbeben; aber Jehovah ist ein Verlaß Seinem Volk und die Stärke den Söhnen Israels. Und ihr werdet erkennen, daß Ich Jehovah bin, euer Gott, Der auf Zijon wohnt, dem Berge Meiner Heiligkeit; und Jerusalem wird Heiligkeit sein; und Fremde sollen nicht mehr hindurchgehen! Und am selben Tage wird geschehen, daß von Most die Berge triefen und von Milch die Hügel fließen, und alle Flußbette Jehudahs mit Wasser flie-ßen, und vom Hause Jehovahs ein Quell ausgeht und tränkt das Bachtal von Schittim. Ägypten wird zur Verwüstung werden, und Edom zur Wüste der Verwüstung ob der Gewalttat gegen Jehudahs Söhne, in deren Land sie haben unschuldig Blut vergossen. Jehudah aber wird sitzen ewiglich und Jerusalem zu Geschlecht und Geschlecht. Und Ich werde unschuldig erklären ihr Blut, das Ich nicht unschuldig erklärt, und Jehovah wird wohnen in Zijon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Die Worte des Amos, der unter den Viehhirten von Thekoa war, die er geschaut hat über Israel in den Tagen des Ussiah, König von Jehudah, und in den Tagen von Jerobeam, dem Sohne des Joasch, des Königs von Israel, zwei Jahre vor dem Erdbeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'Und er sprach: Jehovah brüllt von Zion, und aus Jerusalem gibt Er Seine Stimme hervor. Und der Hirten Auen trauern, und das Haupt des Karmel verdorrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'So spricht Jehovah: Ob dreier Übertretungen Damasks und ob vierer wende Ich es nicht zurück: Darum, daß sie Gilead mit eisernen Dreschwagen gedroschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'Und Ich sende ein Feuer in Chasaels Haus, daß es Ben-Hadads Paläste auffresse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'Und Damasks Riegel zerbreche Ich und rotte aus die Bewohner der Talebene Aven, und den, der das Zepter hält aus Beth-Eden, und in Verbannung zieht Arams Volk nach Kir! spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'So spricht Jehovah: Ob dreier Übertretungen Gazahs und ob vierer wende Ich es nicht zurück: Darum, daß sie eine Vollzahl der Weggeführten haben weggeführt, um sie an Edom zu überantworten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'Und Ich sende ein Feuer in Gazahs Mauern, daß es seine Paläste auffresse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'Und Ich rotte aus den Bewohner aus Aschdod und den, der das Zepter hält aus Aschkalon, und wende zurück Meine Hand wider Ekron, und sie sollen vergehen, der Überrest der Philister, spricht der Herr, Jeho- vah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Also spricht Jehovah: Ob dreier Übertretungen Zors und ob vierer wende Ich es nicht zurück: Darum, daß sie die Vollzahl der Weggeführten an Edom überantworteten, und nicht gedachten des Bundes der Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'Und Ich sende Feuer in die Mauern Zors, daß seine Paläste es auffresse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Also spricht Jehovah: Ob dreier Übertretungen Edoms und ob vierer wende Ich es nicht zurück: Darum, daß er seinem Bruder mit dem Schwerte nachsetzte, und verdarb seine Erbarmungen, und sein Zorn immerfort zerfleischte, und er sein Wüten immerdar behielt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'Und Ich sende Feuer gen Theman, daß es Bozrahs Paläste auffresse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'So spricht Jehovah: Ob dreier Übertretungen der Söhne Ammons und ob vierer wende Ich es nicht zurück: Weil sie Gileads Schwangere aufschlitzten, um ihre Grenze zu erweitern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'Und Ich entzünde ein Feuer in der Mauer Rabbahs, daß es seine Paläste auffresse unter Feldgeschrei am Tage des Streites, mit einem Wetter am Tage des Sturmwindes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'Und ihr König soll in Verbannung gehen, er und seine Obersten zumal, spricht Jehovah..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'So spricht Jehovah: Ob dreier Übertretungen Moabs und ob vierer wende Ich es nicht zurück: Darum, daß sie die Gebeine von Edoms König zu Kalk verbrannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'Und Ich will ein Feuer senden in Moab, daß es auffresse die Paläste von Kerioth, und sterben soll Moab im Tosen, im Feldgeschrei und mit Stimme der Posaune.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'Und Ich rotte aus den Richter aus seiner Mitte, und erwürge mit ihm alle seine Obersten, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'So spricht Jehovah: Ob dreier Übertretungen Jehudahs und ob vierer wende Ich es nicht zurück: Darum, daß sie Jehovahs Gesetz verschmähten und Seine Satzungen nicht hielten, und ihre Falschheiten sie irre geführt, denen schon ihre Väter nachgegangen sind;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'Und Ich will Feuer nach Jehudah senden, daß es auffresse die Paläste Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'So spricht Jehovah: Ob dreier Übertretungen Israels und ob vierer wende Ich es nicht zurück: Darum, daß sie um Silber verkauften den Gerechten, und den Dürftigen um ein paar Schuhe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'Die da schnauben nach dem Stäubchen Erde auf dem Haupt der Armen, und den Weg der Elenden beugen; und ein Mann und sein Vater gehen zur Dirne, damit sie den Namen Meiner Heiligkeit entweihen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'Und auf verpfändeten Kleidern strecken sie sich hin neben jedem Altar; und den Wein der Gebüßten trinken sie im Haus ihrer Götter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'Und Ich vernichtete den Amoriter vor ihnen, dessen Höhe war wie die Höhe der Zedern, und dessen Festigkeit war wie die der Eichen, und seine Frucht von oben und seine Wurzeln von unten vernichtete Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'Und brachte euch aus dem Lande Ägypten herauf, und ließ euch vierzig Jahre in der Wüste gehen, auf daß ihr des Amoriters Land erblich besitzet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'Und habe welche von euren Söhnen zu Propheten und von euren Jünglingen als Nasiräer erstehen lassen. Ist selbst das nichts, Söhne Israels? spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Und den Nasiräern gabt ihr Wein zu trinken, und den Propheten gebotet ihr und sprachet: Ihr sollt nicht weissagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Siehe, Ich will euch unter sich niederdrücken, wie der volle Wagen unter den Garben niedergedrückt wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'Und dem Schnellen geht seine Zuflucht verloren, und den Starken machte seine Kraft nicht mächtig, und der Held rettet nicht seine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'Daß, der den Bogen faßt, nicht besteht, und der leicht auf den Füßen ist, nicht entrinnt, und der auf dem Rosse reitet, seine Seele nicht retten wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'Und der in seinem Herzen Rüstige unter den Helden wird nackend fliehen an jenem Tag, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Hört dieses Wort, das Jehovah über euch geredet, ihr Söhne Israels, über jegliche Familie, die aus dem Lande Ägypten Ich heraufgebracht, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Nur euch habe Ich gekannt unter allen Familien des Bodens; darum werde Ich an euch heimsuchen alle eure Missetaten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Gehen wohl zwei zusammen, ohne daß sie überein geworden sind?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Brüllt auch der Löwe im Walde, ohne daß er zerfleischt hat, und gibt der junge Löwe seine Stimme hervor aus seiner Wohnstätte, er habe denn einen Fang getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Fällt auch ein Vogel in die Schlinge zur Erde, ohne daß ein Fallstrick für ihn da ist? Steigt eine Schlinge empor vom Boden, ohne daß sie einen Fang gefangen hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Stößt man in die Posaune in der Stadt, daß nicht das Volk erzittere? Geschieht ein Übel in der Stadt, das nicht Jehovah tue?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Denn der Herr Jehovah tut nichts, Er habe denn Seinen Beschluß Seinen Knechten, den Propheten, geoffenbart.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Der Löwe brüllt, wer sollte sich nicht fürchten? Der Herr Jehovah redet, wer sollte nicht weissagen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Lasset hören auf den Palästen in Aschdod und auf den Palästen im Lande Ägypten, und sprechet: Versammelt euch auf den Bergen Schomrons und sehet das viele Toben in seiner Mitte und die Bedrückungen in seinem Inneren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'Und nicht wußten sie das Richtige zu tun, spricht Jehovah. Sie häufen sich Schätze von Gewalttat und Verheerung in ihren Palästen auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Darum, so spricht der Herr Jehovah: Der Dränger ist da und ringsum in dem Land, und wird dir deine Stärke herunterbringen und deine Paläste berauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'So spricht Jehovah: Wie der Hirte aus des Löwen Rachen zwei Beine oder den Zipfel eines Ohres entreißt, so werden die Söhne Israels, die in Schomron sitzen in des Bettes Ecke und am Äußersten des Ruhebettes errettet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Hört und zeugt wider das Haus Jakobs! spricht der Herr Jehovah, der Gott der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'Denn am Tage, da Ich Israels Übertretungen an ihm heimsuche, da werde Ich auch heimsuchen die Altäre Bethels; und niedergehauen sollen werden die Hörner des Altars und zur Erde fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'Und Ich schlage das Winterhaus samt dem Sommerhaus, und zerstört werden die Häuser von Elfenbein und weggerafft werden die großen Häuser, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Hört dies Wort, ihr Kühe Baschans, ihr auf dem Berge Schomrons, die ihr bedrückt die Armen, zerschlagt die Dürftigen, die ihr sprecht zu ihren Herren: Bringt herein, daß wir trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Der Herr Jehovah hat es geschworen bei Seiner Heiligkeit: Siehe, es kommen Tage über euch, da man euch mit Angeln heraufholen wird und eure Nachkommen mit Haken zum fischen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'Durch die Durchbrüche geht ihr hinaus, jede vor sich hin, und werfet nieder den Palast, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Kommt nach Bethel und übertretet, nach Gilgal, mehret die Übertretung. Bringt herein am Morgen eure Schlachtopfer und an den dritten Tagen eure Zehnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'Und räuchert von Gesäuertem zum Dankopfer, und ruft freiwillige Opfer aus, lasset es hören, denn so liebt ihr es, Söhne Israels, spricht der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Und auch Ich gebe euch müßige Zähne in all euren Städten, und Mangel an Brot euch in allen euren Orten; aber ihr seid nicht zurückgekehrt zu Mir, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'Und Ich habe euch auch vorenthalten den Regen, da noch drei Monate zur Ernte waren; und ließ regnen über eine Stadt, und nicht regnen über eine andere Stadt; der eine Teil ward beregnet und der Teil, der nicht beregnet ward, verdorrte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'Und zwei, drei Städte wanderten nach einer Stadt, Wasser zu trinken, und wurden nicht satt, aber ihr kehrtet nicht zurück zu Mir, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Ich schlug euch mit Kornbrand und Vergilbung; die meisten eurer Gärten und eurer Weinberge, und eurer Feigenbäume und eurer Ölbäume fraß die Raupe; aber ihr kehrtet nicht zu Mir zurück, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Ich sandte die Pest unter euch in der Weise Ägyptens, erwürgte eure Jünglinge durch das Schwert, mit Gefangenschaft eurer Rosse, und ließ den Gestank eurer Heerlager in eure Nase aufsteigen; aber ihr kehrtet nicht zurück zu Mir, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Ich machte eine Umkehrung unter euch, wie Gott Sodom und Gomorrah umkehrte; und ihr wart wie ein Brand aus der Feuersbrunst gerissen, und ihr kehrtet nicht zurück zu Mir, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Darum werde Ich solches an dir tun, Israel: Weil Ich solches an dir tun werde, bereite dich, Israel, deinem Gott zu begegnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Und siehe, Er, Der die Berge bildet und schafft den Geist und sagt dem Menschen an, was sein Sinnen ist: Er, Der macht das Morgenrot, Dunkelheit, und auf der Erde Höhen tritt, ist Jehovah, der Heerscharen Gott ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Hört dieses Wort; denn ein Klagelied erhebe ich über euch vom Hause Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Gefallen ist, nicht steht sie wieder auf, die Jungfrau Israel, auf ihren Boden hingegeben, niemand richtet sie auf!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Denn so spricht der Herr Jehovah: Die Stadt, die auszieht mit tausend, da verbleiben hundert, und die mit hundert auszieht, da verbleiben zehn dem Hause Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Denn also spricht Jehovah zum Hause Israels: Suchet nach Mir, auf daß ihr lebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'Und sucht Bethel nicht, und kommt nicht nach Gilgal, und nach Beerscheba zieht nicht hinüber; denn Gilgal wird in Verbannung weggeführt, und Bethel wird zum Unrecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Suchet nach Jehovah, daß ihr lebet, auf daß Er nicht wie Feuer hereinbreche in das Haus Joseph, und auffresse und niemand sei, der lösche in Bethel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Die ihr das Recht in Wermut verwandelt und Gerechtigkeit zur Erde niederstoßet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'Er, Der das Siebengestirn und den Orion machte, Der in Morgen den Todesschatten verwandelt, und den Tag zur Nacht verfinstert, Der den Wassern des Meeres ruft und über der Erde Flächen ausgießt, Jehovah ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'Er, Der Verheerung losbrechen läßt über den Starken, daß Verheerung über die Festung kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Sie hassen den, der rügt in dem Tor; und der da rechtschaffen redet, ist ihnen ein Greuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Darum, weil ihr den Armen zertretet und die Tracht Getreide von ihm nehmt, baut ihr Häuser aus Quadersteinen, aber ihr sollt nicht darin wohnen; Weingärten der Lust pflanzet ihr, aber den Wein davon sollt ihr nicht trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Denn Ich weiß, eurer Übertretungen sind viel, und zahlreich eure Sünden, die ihr bedrängt den Gerechten, die ihr ein Sühngeld nehmt und im Tor die Dürftigen beugt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Darum wird stille zu solcher Zeit der Kluge; denn eine böse Zeit ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Suchet nach dem Guten und nicht nach dem Bösen, auf daß ihr lebt, und also Jehovah, der Gott der Heerscharen, mit euch sei, wie ihr gesprochen habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Hasset das Böse und liebt das Gute, und bestellt das Recht im Tor; Jehovah, der Gott der Heerscharen, ist vielleicht gnädig dem Überrest von Joseph.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Darum, so spricht Jehovah, der Gott der Heerscharen, der Herr: In allen Straßen ist Klage, und auf allen Gassen sagen sie Wehe! Wehe! Und sie rufen den Ackersmann zur Trauer und zur Klage die des Trauerliedes Kundigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'Und in allen Weingärten ist Klage; denn Ich werde durch deine Mitte hindurchgehen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Wehe denen, die nach dem Tag Jehovahs sich sehnen! Was soll er euch? Der Tag Jehovahs, der ist Finsternis und nicht Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Wie ein Mann, der vor dem Löwen flieht, und stößt auf einen Bären, und kommt in das Haus, und die Hand an die Wand lehnt, und von einer Schlange gebissen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Ist nicht Finsternis der Tag Jehovahs, und nicht Licht? Und Dunkelheit darin, und kein Glanz?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Ich hasse, Ich schmähe eure Feste, und mag nicht riechen eure Festversammlungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'Denn lasset ihr Mir Brandopfer aufsteigen und eure Speiseopfer, so finde Ich kein Wohlgefallen daran; und das Friedensopfer eures Mastviehs blicke Ich nicht an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Tue weg von Mir das Dröhnen deiner Lieder, und auf das Saitenspiel deines Psalters höre Ich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'Und wie die Wasser soll sich das Gericht daherwälzen, und die Gerechtigkeit wie ein reißender Bach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Habt ihr Mir Schlachtopfer und Speiseopfer die vierzig Jahre in der Wüste herbeigebracht, ihr Haus Israel?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Und ihr trugt den Sichuth, euren König, und Chiun, eure Bilder, den Stern eurer Götter, die ihr aufgemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Und Ich werde euch jenseits Damaskus wegführen lassen, spricht Jehovah, Gott der Heerscharen ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Wehe den Sorglosen in Zion und den Sicheren auf dem Berge Schomrons, die der Erstling der Völkerschaften benannt werden, und zu denen das Haus Israel kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Geht hinüber nach Chalneh, und seht, und geht von da nach Chamath der Großen, und geht hinab nach Gath der Philister. Seid ihr besser als diese Königreiche? Ist ihre Grenze größer als eure Grenze?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'Die ihr weit hinausschiebt den bösen Tag, und herbeizieht der Gewalttat Sitz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'Die da liegen auf Betten von Elfenbein und üppig hingestreckt auf ihren Ruhebetten, und essen Lämmer von der Herde und Kälber aus der Mitte des Maststalls;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'Die Lieder anstimmen, zu des Psalters Klang, und wie David sich Instrumente zum Dazusingen ausdenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'Sie trinken aus Schalen den Wein und salben sich mit dem Erstling des Öls, und tragen nicht Leid um den Bruch Josephs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Darum werden sie weggeführt an der Spitze der Weggeführten, und fortgewichen ist das Jubilieren der üppig Hingestreckten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Geschworen hat der Herr Jehovah bei Seiner Seele. Es spricht Jehovah, der Gott der Heerscharen: Zum Greuel ist Mir der Stolz Jakobs, und Ich hasse seine Paläste und überantworte die Stadt und ihre Fülle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'Und es wird geschehen, wenn zehn Männer in einem Hause übrig wären, so sollen sie sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'Und es hebt einen sein Oheim und der ihn verbrennt auf, um die Gebeine aus dem Hause hinauszubringen, und spricht zu dem, der an der hinteren Seite des Hauses ist: Ist noch jemand bei dir? Und er sagt: Niemand. Und er wird sprechen: Still! denn des Namens Jehovahs ist nicht zu gedenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Den siehe, Jehovah hat es geboten, und hat das große Haus mit Ritzen geschlagen und das kleine Haus mit Rissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Laufen auch Rosse auf der Felsenklippe? Pflügt man dort mit Rindern? Denn ihr habt das Recht in Galle verwandelt, und in Wermut die Frucht der Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'Ihr seid fröhlich über das, was nichts ist, und sprecht: Haben wir nicht mit unserer Stärke uns Hörner geholt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Denn siehe, Ich lasse erstehen wider euch vom Hause Israel, spricht Jehovah, der Gott der Heerscharen, eine Völkerschaft, die soll euch bedrücken von da an, wo man nach Chamath kommt, bis an den Bach der Einöde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'Also ließ mich sehen der Herr Jehovah, und siehe, Er bildete Heuschrecken, als das Grummet begann heraufzukommen, und siehe, es war Grummet nach dem Mähen des Königs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'Und es geschah, da sie das Kraut des Landes ganz abgefressen hatten, da sprach ich: O Herr Jehovah, vergib doch! Wie kann Jakob bestehen, da er klein ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Es reute Jehovah dessen: Es soll nicht geschehen! sprach Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'Also ließ mich sehen der Herr Jehovah, und siehe, der Herr Jehovah rief das Feuer zum Hadern; und es fraß den großen Abgrund, und es fraß einen Teil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Und ich sprach: Herr Jehovah! Höre doch auf! Wie kann Jakob bestehen, denn er ist klein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Es reute solches Jehovah. Auch das soll nicht geschehen! sprach der Herr Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'Also ließ Er mich sehen, und siehe, der Herr stand auf einer senkrechten Mauer und hatte ein Senkblei in der Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'Und Jehovah sprach zu mir: Was siehst du, Amos? Und ich sprach: Ein Senkblei. Und der Herr sprach: Siehe, Ich lege das Senkblei an inmitten meines Volkes Israel, und werde ihn nicht ferner übergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'Und die Opferhöhen Isaaks sollen verwüstet, und die Heiligtümer Israels verödet werden, und Ich will wider das Haus Jerobeams mit dem Schwert aufstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Und Amazjah, der Priester von Bethel, sandte an Jerobeam, den König von Israel, sprechend: Amos erregt inmitten des Hauses Israel Verschwörung wider dich. Das Land vermag nicht zu fassen alle seine Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Denn so hat Amos gesprochen: Durch das Schwert wird Jerobeam sterben, und Israel von seinem Boden weggeführt werden in Verbannung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'Und Amazjah sprach zu Amos: Gehe, Seher, entweiche dir nach dem Lande Jehudah und iß dort Brot, und allda weissage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'Aber in Bethel sollst du nicht mehr weissagen, weil dies ein Heiligtum des Königs und es das Haus des Königreiches ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'Aber Amos antwortete und sprach zu Amazjah: Ich bin kein Prophet und keines Propheten Sohn, sondern ein Kuhhirte bin ich und Maulbeerfeigenzüchter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Und Jehovah nahm mich hinter der Herde weg; und Jehovah sprach zu mir: Gehe, weissage wider Mein Volk Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'Und nun höre Jehovahs Wort! Du sprichst: Weissage nicht wider Israel; und träufle nicht wider Isaaks Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Darum, so spricht Jehovah: Dein Weib wird buhlen in der Stadt, und deine Söhne und deine Töchter werden fallen durch das Schwert, und dein Boden wird durch die Meßschnur verteilt werden, und du sollst auf unreinem Boden sterben, und Israel soll in Verbannung von seinem Boden weggeführt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'Also ließ der Herr Jehovah mich sehen, und siehe, ein Korb mit Sommerfrüchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'Und Er sprach: Was siehst du, Amos? Und ich sprach: Einen Korb mit Sommerfrüchten. Und Jehovah sprach zu mir: Gekommen ist das Ende über Mein Volk Israel; Ich werde ihn nimmer übergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'Und heulen werden sie am selben Tage des Tempels Lieder! spricht der Herr Jehovah. Viel der Leichen wirft man still an jeden Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Hört dies, die ihr schnappt nach dem Dürftigen, und wegschafft die Elenden im Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'Indem ihr sprecht: Wann ist doch der Neumond vorüber, daß wir Getreide verkaufen, und der Sabbath, daß wir das Kornhaus öffnen? auf daß wir das Ephah ringern, und groß den Schekel und verkehrt des Truges Waage machen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'Daß wir um Silber die Armen kaufen und den Dürftigen um ein Paar Schuhe, und den Abfall des Getreides verkaufen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Geschworen hat es Jehovah bei der Erhabenheit Jakobs: Nimmermehr werde Ich vergessen all ihr Tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Sollte darob nicht die Erde erzittern und trauern jeder, der darin wohnt? Daß das Ganze heraufsteige wie ein Strom und fortgetrieben und versenkt werde wie vom Strome Ägyptens!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'An selbem Tage soll geschehen, spricht der Herr Jehovah, daß Ich die Sonne am hellen Mittage lasse untergehen, und die Erde finster werden am Tage des Lichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'Und eure Feste verwandle in Trauer Ich, und alle eure Lieder in Klagelieder, und will über alle Lenden den Sack heraufziehen, und auf jedes Haupt Kahlheit, und will sie setzen wie in Trauer um den Einzigen, und ihr Letztes wie einen bitteren Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Siehe, die Tage kommen, spricht der Herr Jehovah, da einen Hunger Ich in das Land sende, nicht einen Hunger nach Brot und keinen Durst nach Wasser, sondern zu hören die Worte Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'Und sie streifen umher von Meer zu Meer, und von Mitternacht bis gen Aufgang; und sie ziehen umher, zu suchen Jehovahs Wort, und werden es nicht finden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'An selbem Tage schmachten dahin die schönen Jungfrauen und die Jünglinge vor Durst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'Die schwören bei der Schuld Schomrons und sprechen: Beim Leben deines Gottes, Dan! und: Es lebe der Weg nach Beerscheba! Sie sollen fallen und nicht mehr aufstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Ich sah den Herrn auf dem Altare stehen, und Er sprach: Schlag auf den Knauf, daß die Schwellen beben, und zertrümmere sie auf ihrer aller Haupt, und ihre Nachkommen will Ich mit dem Schwert erwürgen, und kein Flüchtling soll von ihnen entfliehen, und kein Entrinnender von ihnen wird entkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Bohrten sie durch in die Hölle, so holte meine Hand sie von da; und stiegen sie auf in den Himmel, so würde Ich sie von da herniederbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'Und versteckten sie sich auf Karmels Spitze, Ich forschte sie von da heraus und holte sie; und verbärgen sie sich vor meinen Augen in des Meeres Grund, so geböte Ich von da der Schlange, daß sie sie beiße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'Und wenn sie vor ihren Feinden her in die Gefangenschaft ziehen, werde Ich von da dem Schwert gebieten, daß es sie erwürge, und setze Mein Auge auf sie zum Bösen und nicht zum Guten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Und der Herr Jehovah der Heerscharen ist es, Der die Erde anrührt und sie zerfließt, und alle trauern, die darauf wohnen; und es soll ganz über sie aufsteigen wie ein Strom, und versinken wie vom Strome Ägyptens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'Er baut in den Himmeln Seine Stufen, und Sein Gewölbe, über der Erde gründet Er es. Er ruft des Meeres Wassern und gießt sie aus über der Erde Flächen! Jehovah ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Seid ihr Mir nicht gleich der Kuschiter Söhne, ihr Söhne Israels, spricht Jehovah. Habe Ich nicht Israel heraufgebracht aus dem Lande Ägypten, und aus Kaphthor die Philister, und Aram aus Kir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Siehe, die Augen des Herrn Jehovah sind wider das sündhafte Königreich, daß Ich es vernichte vom Angesicht des Bodens; nur will Ich nicht ganz vernichten Jakobs Haus, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Denn siehe, Ich gebiete und lasse umherwandern unter allen Völkerschaften das Haus Israel, wie man im Siebe umherschwingt, und kein Körnchen soll auf die Erde fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Durch das Schwert sollen sterben alle Sünder Meines Volkes, die sprechen: Nicht erreicht, nicht begegnet uns das Böse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'An demselben Tage werde Ich Davids Hütte aufrichten, die gefallen; und vermauern ihre Durchbrüche, aufrichten, was daran eingerissen ist, und sie bauen wie in den Tagen der Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'Auf daß sie in Erbbesitz nehmen den Überrest Edoms und alle Völkerschaften, über die Mein Name wird gerufen, spricht Jehovah, Der solches tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Siehe, spricht Jehovah, die Tage kommen, da der Pflüger an den Schnitter reicht, und der Weinbeeren tritt an den, der Samen sät, und von süßem Most die Berge triefen und alle Hügel zerfließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'Und Ich wende zurück die Gefangenschaft Meines Volkes Israel; und sie werden die verwüsteten Städte bauen und darin wohnen, und Weingärten pflanzen und deren Wein trinken, und Gärten machen und essen ihre Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'Und Ich werde sie pflanzen auf ihren Boden; und sie sollen nicht mehr ausgerissen werden aus ihrem Boden, den Ich ihnen gab, spricht Jehovah, dein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Gesicht Obadjahs. So spricht der Herr Jehovah zu Edom: Wir haben ein Gerücht gehört von Jehovah, und eine Gesandtschaft wird gesandt unter die Völkerschaften: Steht auf, und laßt uns aufstehen wider sie zum Streite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Siehe, Ich mache dich klein unter den Völkerschaften. Sehr verachtet bist du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Die Vermessenheit deines Herzens hat dich verführt, die du wohnst in den Klüften der Felsenklippen, der Höhe deines Sitzes. Er spricht in seinem Herzen: Wer wird mich zur Erde hinabstürzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Und wenn du wie der Adler in die Höhe führest und setztest dein Nest zwischen die Sterne, will Ich dich von da herabziehen, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Wenn Diebe über dich kommen, wenn Verheerer der Nacht, wie wirst du da untergehen! Werden sie nicht stehlen, bis sie genug haben? Wenn Winzer über dich kommen, werden sie dir nicht eine Nachlese verbleiben lassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Wie wird Esau durchforscht, seine Schlupfwinkel durchsucht werden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Bis zur Grenze geleiten dich alle Männer deines Bundes, die Männer, die in Frieden mit dir waren, verführen, sie überwältigen dich; dein Brot - sie legen unter dir einen Fallstrick; du aber merkst nicht darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Wird es nicht, spricht Jehovah, an jenem Tage geschehen, daß Ich die Weisen aus Edom und die Einsicht aus dem Berge Esaus zerstöre?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'Und entsetzt werden sein deine Helden, Theman, daß der Mann ausgerottet wird vom Berge Esaus ob dem Morden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Ob der Gewalttat an deinem Bruder Jakob wirst du bedeckt mit Scham, und wirst ausgerottet werden in Ewigkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Am Tage, da du gegenüber standest, am Tage, da Fremde seine Streitmacht gefangen führten, und Ausländer durch seine Tore einzogen und über Jerusalem das Los warfen, warst auch du wie einer von ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'Du solltest nicht zusehen am Tage deines Bruders, am Tage der Entfremdung, und nicht froh sein über die Söhne Jehudahs am Tage ihrer Zerstörung, und nicht deinen Mund groß machen am Tage der Drangsal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'Nicht solltest du zum Tore Meines Volkes eingehen am Tage ihrer Not, du solltest nicht, auch du, sein Übel ansehen am Tage seiner Not; und nicht ausstrecken an sein Vermögen am Tage seiner Not.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'Und solltest nicht stehen an der Wegscheide, seine Entkommenen auszurotten; und nicht sollst du seinen Rest überantworten am Tag der Drangsal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Denn nahe ist Jehovahs Tag über alle Völkerschaften; wie du getan hast, so wird dir getan; deine Vergeltung kehrt auf dein Haupt zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Denn wie ihr getrunken habt auf dem Berg Meiner Heiligkeit, so sollen alle Völkerschaften beständig trinken, und sie sollen trinken und hinabschlingen, und sollen sein, als wären sie nicht gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Aber auf dem Berge Zijons wird ein Entkommen sein, und wird sein eine Heiligkeit, und das Haus Jakob wird erblich besitzen ihren Erbbesitz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'Und das Haus Jakob wird ein Feuer und das Haus Joseph eine Flamme und das Haus Esaus zur Stoppel werden, und sie zünden sie an und fressen sie auf, daß Esaus Hause kein Rest überbleibt; denn Jehovah hat es geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'Und die vom Mittag nehmen ein den Berg Esaus, und die in der Niederung die Philister, und sie besitzen erblich das Feld Schomrons, und Benjamin das Gilead.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Und die Weggeführten dieser Streitmacht der Söhne Israels, so unter den Kanaanitern bis gen Zarpath sind, und die Weggeführten Jerusalems, die in Sepharad sind, werden die Städte im Mittag erblich besitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'Und Retter werden auf den Berg Zijon heraufziehen, zu richten den Berg Esaus, und Jehovahs wird sein das Königtum!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'Und es geschah das Wort Jehovahs an Jonah, den Sohn Amitthais, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Stehe auf und gehe nach Niniveh, der großen Stadt, und predige wider sie; denn ihre Bosheit ist vor Mich heraufgestiegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Und Jonah stand auf, um von dem Angesichte Jehovahs nach Tharschisch zu entweichen; und er ging hinab gen Japho und fand ein Schiff, das nach Tharschisch fuhr, und gab sein Fährgeld und stieg hinab in dasselbe, um mit ihnen nach Tharschisch zu kommen, hinweg vom Angesicht Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'Und Jehovah ließ einen großen Wind auf das Meer kommen, und es ward ein großes Wetter auf dem Meere, und das Schiff wollte zerbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'Und die Seeleute fürchteten sich und schrien jeder Mann zu seinem Gott, und warfen die Geräte, die im Schiff waren, in das Meer, daß sie sich leichter machten; Jonah war aber in das Hinterteil des Fahrzeuges hinabgestiegen, und lag da in tiefem Schlaf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Und es nahte sich ihm der Hauptsteuermann und sprach zu ihm: Was ist dir? Was liegst du im tiefen Schlaf? Stehe auf, rufe zu deinem Gott, vielleicht daß Er es Sich über uns bedenke und wir nicht verloren seien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'Und sie sprachen, der Mann zu seinen Genossen: Kommt, laßt uns Lose werden, daß wir wissen, ob wem uns solch Übel geschieht. Und sie warfen Lose, und das Los fiel auf Jonah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Und sie sagten zu ihm: Sage uns doch an, um wessen willen uns dieses Übel widerfährt? Was ist dein Geschäft, und von wannen kommst du? Was ist dein Land, und von welchem Volke bist du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'Und er sagte zu ihnen: Ich bin ein Hebräer und fürchte Jehovah, den Gott der Himmel, Der das Meer und das Trockene gemacht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Und die Männer fürchteten sich mit großer Furcht und sagten zu ihm: Warum hast du dies getan? denn die Leute wußten, daß er vor dem Angesichte Jehovahs entwich; denn er hatte es ihnen angesagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'Und sie sagten zu ihm: Was sollen wir dir tun, auf daß das Meer vor uns zur Ruhe komme? Denn das Meer ward immer stürmischer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'Und er sagte zu ihnen: hebt mich auf und werft mich ins Meer, auf daß das Meer vor euch zur Ruhe komme; denn ich weiß, daß meinetwegen dieses große Wetter über euch ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'Und die Männer ruderten, daß sie wieder zum trockenen Land zurückkämen und vermochten es nicht; denn das Meer ward immer stürmischer über ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Und sie riefen Jehovah an und sprachen: Laß uns doch, o Jehovah, nicht verlorengehen ob der Seele dieses Mannes und lege nicht unschuldig Blut auf uns. Denn Du bist Jehovah, wie Du Lust hattest, hast Du getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Und sie hoben den Jonah auf und warfen ihn ins Meer; und das Meer stand still von seinem Grollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Und die Männer fürchteten Jehovah mit großer Furcht, und sie opferten dem Jehovah Schlachtopfer, und gelobten Gelübde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'Und Jehovah verschaffte einen großen Fisch, den Jonah zu verschlingen. Und Jonah war im Leib des Fisches drei Tage und drei Nächte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'Und Jonah betete zu Jehovah, seinem Gotte, aus dem Leib des Fisches,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Und sprach: Ich rief aus meiner Drangsal zu Jehovah, und Er antwortete mir; aus dem Bauche der Hölle habe ich aufgeschrien, Du hörtest meine Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'Und Du warfst mich in den Schlund, in das Herz der Meere, und eine Strömung umgab mich, all Deine Brandungen und deine Wogen gingen über mich hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Und ich sprach: Ich bin aus Deinen Augen vertrieben, doch werde ich wiederum den Tempel Deiner Heiligkeit erblicken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Die Wasser umfingen mich bis an die Seele, mich umgab der Abgrund, Schilf war mir um mein Haupt umgebunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Ich sank hinunter zu der Berge Gründe, die Erde - ihre Riegel waren um mich ewiglich. Du aber hast mein Leben aus der Grube heraufgebracht, Jehovah, mein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Da meine Seele verzagte ob mir, gedachte ich an Jehovah, und mein Gebet kam zu Dir zum Tempel Deiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Die zu der Eitelkeit Nichtigem halten, verlassen ihre Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'Ich aber will Dir mit der Stimme des Bekenntnisses opfern. Was ich gelobt habe, will ich entrichten. Das Heil ist bei Jehovah. Und Jehovah sprach zu dem Fisch, und er spie den Jonah aus an das Trockene.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'Und das Wort Jehovahs geschah an Jonah zum zweitenmal, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Stehe auf, gehe nach Niniveh, der großen Stadt und predige die Predigt, die Ich zu dir rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Und Jonah stand auf und ging nach Niniveh, nach dem Worte Jehovahs; und Niniveh war eine große Stadt vor Gott, eine Reise von drei Tagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'Und Jonah fing an, in die Stadt hineinzugehen, eine Reise von einem Tag, und rief und sprach: Noch vierzig Tage, und Niniveh wird umgekehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'Und die Männer Ninivehs glaubten an Gott und riefen ein Fasten aus, und kleideten sich in Säcke vom Großen bis zum Kleinen derselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'Und als das Wort den König Ninivehs erreichte, da stand er auf von seinem Throne und legte seinen Mantel von sich ab, und deckte sich mit einem Sack und saß in Asche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'Und ließ ausschreien und sagen in Niniveh auf Weisung des Königs und seiner Großen und sprechen: Mensch und Vieh, Rind und Kleinvieh sollen nichts schmecken, nicht weiden und kein Wasser trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'Und es sollen sich bedecken mit Säcken Mensch und Vieh, und sollen zu Gott rufen kräftiglich und zurückkehren jeder Mann von seinem bösen Weg, und von der Gewalttat, die an ihren Händen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Wer weiß, ob Gott nicht zurückkehrt und es bereut und zurückkehrt von der Entbrennung Seines Zornes, daß wir nicht vergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'Und Gott sah ihr Tun, daß sie von ihrem bösen Weg zurückkehrten; und es reute Gott des Bösen, das Er geredet hatte ihnen zu tun, und tat es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'Und es war sehr böse vor Jonah, und er entbrannte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'Und er betete zu Jehovah und sprach: Ach Jehovah, war nicht das mein Wort, da ich noch auf meinem Boden war, darum ich wollte zuvorkommen und nach Tharschisch entweichen? Denn ich wußte ja, daß Du ein gnädiger und erbarmungsvoller Gott, langmütig und von großer Barmherzigkeit bist, und Dich des Bösen gereuen läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'Und nun, Jehovah, nimm doch meine Seele von mir! Besser ist, ich sterbe, denn daß ich lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Und Jehovah sprach: Ist es gut, daß du entbrennst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'Und Jonah ging hinaus aus der Stadt, und setzte sich gegen Osten von der Stadt, und machte sich allda eine Hütte, und setzte sich darunter in den Schatten, bis daß er sähe, was mit der Stadt würde werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'Und Jehovah Gott verschaffte einen Wunderbaum, und er stieg auf über Jonah, so daß über seinem Haupte Schatten wäre, so daß er ihn von seinem Bösen errettete; und Jonah ward froh über den Wunderbaum mit großer Fröhlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Und Gott verschaffte einen Wurm, als das Morgenrot aufstieg am morgenden Tag, und er stach den Wunderbaum, daß er verdorrte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'Und als die Sonne aufging, geschah, daß Gott einen versengenden Ostwind verschaffte, und die Sonne stach Jonah auf den Kopf, daß er dahinschmachtete; und er erbat seiner Seele, daß er stürbe, und sprach: Besser ist mir, daß ich sterbe, denn daß ich lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Und Gott sprach zu Jonah: Tust du wohl, daß du bei dir entbrennst über den Wunderbaum? Und er sprach: Ich tue wohl, daß ich entbrenne bis zum Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Und Jehovah sprach: Du würdest schonen den Wunderbaum, mit dem du keine Mühe hattest, und den du nicht großgezogen hattest, der in einer Nacht ward und in einer Nacht verging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'Und Ich sollte nicht schonen Niniveh, die große Stadt, in der sind mehr den zwölf Myriaden von Menschen, die nicht wissen den Unterschied zwischen ihrer Rechten und ihrer Linken, und viel Vieh?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Das Wort Jehovahs, das geschah an Michah, den Moraschthiter, in den Tagen Jothams, Achas, Jechiskijahs, der Könige von Judah, das er schaute über Schomron und Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Höret, ihr Völker allzumal, horche, o Erde und ihre Fülle; und zum Zeugen sei wider euch der Herr Jehovah, der Herr aus dem Tempel Seiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Denn siehe, Jehovah geht aus von Seinem Ort und steigt herab und tritt auf der Erde Höhen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'Daß unter Ihm die Berge schmelzen und Talgründe sich spalten, wie Wachs vor dem Feuer, wie Wasser, das man auf den Abhang hingießt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Wegen Jakobs Übertretung ist alles dies und wegen der Sünden des Hauses Israel. Was ist die Übertretung Jakobs? Ist es nicht Schomron? Und was Jehudahs Opferhöhen? Ist es nicht Jerusalem?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Und zum Trümmerhaufen auf dem Felde mache Ich Schomron, zu Pflanzungen eines Weinbergs, und gieße seine Steine in die Schlucht hin, und decke seine Grundfesten auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'Zerstoßen werden alle ihre Schnitzbilder, und verbrannt im Feuer alle ihre Buhlgaben, und alle ihre Götzenbilder setze Ich in Verwüstung, denn von der Buhlgabe einer Buhlerin hat sie es zusammengebracht, und zu den Buhlgaben einer Buhlerin kehren sie zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Darüber klage und heule ich, gehe ausgebeutet und nackt daher, mache eine Klage wie die Drachen, und trauere wie die jungen Eulen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Denn verzweifelt sind ihre Schläge, denn bis Jehudah kommt er, berührt Meines Volkes Tor bis an Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'In Gath sagt es nicht an mit Weinen, weint nicht im Hause Aphras! Wälze dich umher im Staube!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Ziehet für euch hinüber, Einwohnerschaft Schaphirs, entblößt mit Scham. Nicht komm heraus, die du in Zaanan wohnest. Die Klage von Beth-Haezel nehme ihren Stand von euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Denn die Bewohnerin von Maroth wartet auf Gutes; denn von Jehovah kam Böses herab bis an das Tor von Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Schirre den Renner an den Streitwagen, Bewohnerin von Lachisch, Anfängerin der Sünde ist sie für Zijons Tochter; denn in dir fanden sich die Übertretungen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Darum tue Verzicht auf den Erbbesitz Gaths; die Häuser Achsibs sind eine Täuschung für Israels Könige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Noch bringe Ich dir den Erbbesitzer herein, Mareschahs Wohnerschaft. Bis Adul- lam wird kommen Israels Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Mache dich kahl und schere dich ob den Söhnen deiner Wonne; mache deine Kahlheit breit, wie der Adler; denn sie sind von dir weggeführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Wehe denen, die auf Unrecht denken, die Böses auf ihren Lagern wirken, am Licht des Morgens es tun, weil ihre Hand ihnen zum Gotte ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Und sie begehren Felder und entreißen sie, und Häuser, und nehmen sie weg; und sie bedrücken den Mann und sein Haus, und den Mann und sein Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Darum, so spricht Jehovah: Siehe, Ich denke auf Böses wider diese Familie, aus der ihr eure Hälse nicht herausziehen sollet, daß ihr aufrecht ginget; denn es ist eine Zeit des Bösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'An jenem Tage erhebt man einen Spruch über euch und stimmt ein Trauerlied an: Es ist vorbei! spricht man. Mit Verheerung sind wir verheert. Das Teil meines Volkes wird vertauscht. Wie entzieht er es mir, und teilt unsere Felder an die Abtrünnigen aus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Darum wird keiner sein, der in der Versammlung Jehovahs dir die Meßschnur zum Lose werfe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, 'Sie faseln: Ihr sollt nicht weissagen! Sie sollen nicht von solchem weissagen! Die Schande wird nicht zurückweichen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Darf man so sprechen, Jakobs Haus? Ist der Geist Jehovahs verkürzt? Sind das Seine Taten? Sind Meine Worte nicht gut mit dem, der da gerade wandelt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Aber zum Feinde hat sich Mein Volk Mir entgegen aufgestellt wegen des Gewandes, den Mantel zieht ihr denen aus, die sicher vorüberziehen, die vom Streite zurückkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Die Weiber Meines Volkes vertreibt ihr jede aus dem Hause ihrer Wonne, nehmt ihren Kindlein Meine Ehre ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Steht auf und geht hin! Dies ist kein Ruheort. Wegen der Unreinheit wird sie euch heillos verstören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Ja, ein Mann, der im Geiste wandelt, und mit Lüge täuscht: Ich will dir mit Wein und starkem Getränk wahrsagen! das wäre ein Wahrsagen für dieses Volk!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Versammeln werde Ich dich, Jakob, allzumal, zusammenbringen den Überrest von Israel, sie zusammenstellen wie Bozrahs Herde, wie einen Trieb inmitten seines Weideplatzes: sie dröhnen mit Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Vor ihnen geht der Durchbrecher herauf. Sie brechen durch und ziehen durch das Tor und ziehen dadurch aus, und vor ihnen her zieht ihr König vorüber, und Jehovah ihnen zum Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'Und ich sprach: Höret doch, ihr Häupter Jakobs, und ihr Anführer vom Hause Israel: Ist es nicht an euch, das Recht zu wissen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'Die ihr das Gute hasset und liebt das Böse, ihr reißt ab von ihnen die Haut und ihr Fleisch von ihrem Gebein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'Und die das Fleisch von Meinem Volk gegessen, und habt die Haut ihm abgezogen, und zerzahnt sein Gebein und es zerlegt, wie in den Topf, und wie Fleisch in der Mitte eines Kessels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Dann werden sie schreien zu Jehovah, und Er wird ihnen nicht antworten und wird vor ihnen Sein Angesicht verbergen zu jener Zeit, so wie sie böse machten ihr Tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'So spricht Jehovah wider die Propheten, die Mein Volk irre führen, die mit ihren Zähnen beißen und rufen Frieden aus; und wer ihnen nichts gibt vor ihren Mund, wider den heiligen sie den Streit..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Darum habt ihr statt des Gesichtes Nacht, und Finsternis habt ihr statt Wahrsagung, und über den Propheten geht die Sonne unter, und verdunkelt wird über ihnen der Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'Und die Seher werden beschämt, und die Wahrsager erröten, und über den Bart verhüllen alle sich, weil keine Antwort Gottes da ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Aber ich jedoch bin erfüllt mit Kraft, mit dem Geiste Jehovahs und mit Recht und Macht, um Jakob seine Übertretung anzusagen und Israel seine Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Höret doch dies, ihr Häupter des Hauses Jakob, und ihr Anführer vom Hause Israel,denen das Recht zum Greuel ist, und die krumm machen alles, was gerade ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'Die ihr Zijon mit Blut bauet und Jerusalem mit Verkehrtheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Es richten ihre Häupter um ein Geschenk, und ihre Priester unterweisen um das Entgelt, und ihre Propheten wahrsagen um Silber, und stützen auf Jehovah sich und sagen: Ist nicht Jehovah unter uns, kein Übel kommt über uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Darum wird euretwegen Zijon als Feld bepflügt und Jerusalem zum Trümmerhaufen werden und der Berg des Hauses zu Opferhöhen des Waldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'Und in den letzten der Tage wird geschehen, daß der Berg des Hauses Jehovahs feststehen wird als das Haupt der Berge und erhaben über den Hügeln, und Völker auf ihn strömen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'Und viel Völkerschaften werden gehen und sprechen: Laßt uns gehen und hinaufziehen zum Berg Jehovahs und zum Hause des Gottes Jakobs, daß Er uns unterweise in Seinen Wegen, und wir wandeln auf Seinen Pfaden; denn von Zijon geht das Gesetz aus, und das Wort Jehovahs von Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'Und richten wird Er zwischen vielen Völkern und rügen mächtige Völkerschaften in die Ferne; und ihre Schwerter schmieden sie zu Hacken und ihre Spieße zu Winzermessern. Nicht wird das Schwert erheben Völkerschaft wider Völkerschaft; und nicht lernen fürder sie den Streit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'Und jeder Mann sitzt unter seinem Weinstock und unter seinem Feigenbaum, und niemand scheucht auf; denn der Mund Jehovahs der Heerscharen hat es geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Denn alle Völker werden, jedes im Namen seines Gottes, wandeln, und wir werden im Namen Jehovahs, unseres Gottes, wandeln in Ewigkeit und immerfort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'An jenem Tage, spricht Jehovah, will sammeln Ich, was hinkt, und das Verstoßene zusammenbringen, und dem Ich Übles getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'Und das Hinkende werde Ich zum Überrest setzen, und das Versprengte zu zahlreicher Völkerschaft, und König wird sein über sie Jehovah auf dem Berge Zijon von nun an und bis in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'Und du, der Herde Turm, Anhöhe der Tochter Zijons, zu dir wird kom- men und eingehen die frühere Herrschaft, das Reich der Tochter Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Nun, was schreist du so laut? Ist kein König in dir? Ist dein Ratgeber verloren? Daß eine Wehe dich erfaßt wie die Gebärerin?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Habe Wehen und lasse hervorbrechen, Tochter Zijons, wie die Gebärerin, denn nun ziehst du aus von der Hauptstadt, und wohnst im Felde, und kommst bis Babel! Dort wirst du errettet, dort erlöst dich Jehovah aus der Hand deiner Feinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'Und jetzt sammeln sich viele Völkerschaften wider dich, die sprechen: Sie wird entheiligt, daß unser Auge auf Zion schaue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Sie aber wissen die Gedanken Jehovahs nicht, und verstehen Seinen Ratschluß nicht; denn wie die Garbe bringt Er sie auf die Tenne zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Stehe auf und drisch, du Tochter Zijons; denn dein Horn will Ich von Eisen machen, und deine Hufe will von Erz Ich machen, daß du zermalmst viele Völker; und ihren Gewinn verbanne Ich dem Jehovah und ihr Vermögen dem Herrn der ganzen Erde. Nun sammle deinen Kriegshaufen, du Tochter der Kriegshaufen! Denn ein Bollwerk macht man wider uns. Sie schlagen mit der Rute auf den Backen den Richter Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Und du, Bethlehem Ephratha, bist klein, zu sein unter den Tausenden Jehudahs: Aus dir soll Mir hervorgehen, Der in Israel soll Herrscher sein, und Dessen Ausgänge von der Vorzeit sind, von den Tagen der Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'Darum gibt Er sie dahin bis auf die Zeit, da die, so gebären soll, geboren hat. Und die übrig sind von Seinen Brüdern, zurückkehren zu den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Und Er wird stehen und weiden in der Stärke Jehovahs und in der Hoheit des Namens Jehovahs, Seines Gottes, und sie werden sitzen, denn jetzt wird Er groß werden bis an der Erde Äußerstes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'Und dies wird sein der Friede: Wenn Aschur kommt in unser Land, daß unsere Paläste es betrete, so stellen wir sieben Hirten wider ihn auf und acht Gesalbte der Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'Und sie werden Aschurs Land mit dem Schwerte weiden und Nimrods Land an seinen Pforten, und Er wird erretten von Aschur, wenn Er kommt in unser Land und unsere Grenze betritt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'Und Jakobs Überrest wird inmitten vieler Völker sein, wie der Tau von Jehovah, wie Regenschauer auf das Kraut, der nicht harrt auf den Mann, und nicht wartet auf des Menschen Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'Und Jakobs Überrest wird unter den Völkerschaften sein inmitten vieler Völker wie der Löwe unter des Waldes Tieren, wie der junge Löwe unter den Trieben der Herde, der, wenn er hindurchgeht, zerstampft und zerfleischt, und niemand errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'Erhöht wird deine Hand über deine Dränger, und alle deine Feinde sollen ausgerottet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Und am selben Tage wird geschehen, spricht Jehovah, daß deine Rosse Ich aus deiner Mitte ausrotten und deine Streitwagen zerstören werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'Und deines Landes Städte rotte Ich aus und reiße alle deine Festungen ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'Und Ich werde ausrotten aus deiner Hand die Zaubereien; und Zeichendeuter sollen nicht bei dir sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'Und deine Schnitzbilder und deine Bildsäulen rotte Ich aus deiner Mitte aus, und du sollst nicht mehr anbeten deiner Hände Werk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'Und deine Ascheren rode Ich aus aus deiner Mitte und vernichte deine Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'Und tue Rache mit Zorn und mit Grimm an den Völkerschaften, die nicht gehorchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Höret doch, was Jehovah spricht: Stehe auf, hadere mit den Bergen, und laß die Hügel deine Stimme hören!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Höret, ihr Berge, Jehovahs Hader, und ihr starken Grundfesten der Erde; denn Hader hat Jehovah mit Seinem Volk und rügt Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Mein Volk, was habe Ich dir getan? Womit habe Ich dich ermüdet? antworte wider Mich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Daß Ich dich aus dem Lande Ägypten heraufgebracht, und aus dem Haus der Knechte dich habe eingelöst, und Moses, Aharon und Mirjam vor dir hergesandt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Gedenke doch, Mein Volk, was Balak, Moabs König, beriet, und was ihm Bileam, Beors Sohn, antwortete, von Schittim bis Gilgal; daß man erkenne die Gerechtigkeit Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'Womit soll ich zuvorkommen dem Jehovah, mich beugen vor dem Gott der Höhe? Soll ich Ihm zuvorkommen mit Brandopfern, mit einjährigen Kälbern?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Hat Jehovah Wohlgefallen an tausenden von Widdern, an zehntausenden von Bächen Öls? Soll meinen Erstgeborenen ich geben für meine Übertretung, für meiner Seele Sünde meines Leibes Frucht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Er hat dir angesagt, o Mensch, was gut ist. Und was fordert Jehovah von dir, als das Recht zu tun und Barmherzigkeit zu lieben, und in Demut zu wandeln vor deinem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Jehovahs Stimme ruft der Stadt, und Weisheit ist es, zu fürchten Deinen Namen. Hört auf den Stab und Ihn, Der ihn bestellt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'Sind nicht noch im Haus des Ungerechten der Ungerechtigkeit Schätze, und das magere Ephah, das verfluchte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, 'Sollte Ich lautersprechen sie mit der ungerechten Waage und mit dem Beutel, mit Gewichten des Betrugs?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Wo die Reichen voll sind von Gewalttat, und deren Einwohner Lüge reden, und deren Zunge Trug ist in ihrem Munde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Und auch Ich bin müde, dich zu schlagen, dich zu verwüsten ob deinen Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Du sollst essen und nicht satt werden, und dein Heißhunger wird in deinem Inneren sein. Und was du entrückst, sollst du nicht sichern, und was du sicherst, gebe Ich dem Schwerte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Säen wirst du und nicht ernten, wirst Oliven treten und nicht mit Öl dich salben, und Most und doch nicht Wein trinken!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Und ihr haltet zu Omris Satzungen und allem Tun des Hauses Achab, und wandelt nach ihren Ratschlägen, auf daß Ich euch hingebe der Verwüstung, und die, so in ihr wohnen, dem Gezisch, und ihr die Schmach Meines Volkes tragt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Wehe mir, mir wird es wie beim Sammeln der Sommerfrüchte, wie wenn man nachliest in der Weinernte: keine Traube zum Essen. Nach der Frühfeige gelüstet meine Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Vergangen ist der Heilige von der Erde, und kein Redlicher ist da mehr unter den Menschen. Sie alle lauern auf Blut, sie jagen, jeder Mann den Bruder ins Garn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Beide Hände sind aus zum Bösestun statt Gutes zu tun. Der Oberste fordert und der Richter um Vergeltung, und der Große redet die Verstörtheit seiner Seele, und sie verflechten es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Der Gute von ihnen ist wie der Dorn, der Redliche wie die Dornhecke. Deiner Wächter Tag, deine Heimsuchung ist gekommen; nun ist Verworrenheit unter ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Glaubt dem Genossen nicht, vertraut nicht dem Stammhaupt. Vor ihr, die an deinem Busen liegt, hüte die Pforte deines Mundes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Denn der Sohn verunehrt den Vater, die Tochter steht wider ihre Mutter auf, die Schnur wider ihre Schwieger, Feinde des Mannes sind die Männer seines Hauses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'Ich aber spähe auf zu Jehovah, will warten auf den Gott meines Heils, mein Gott wird mich erhören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Sei nicht froh, meine Feindin, über mich! Bin ich gefallen, stehe ich wieder auf; sitze ich in Finsternis, so ist Jehovah mir ein Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Das Grollen Jehovahs will ich tragen; denn ich sündigte an Ihm, bis daß Er hadert meinen Hader, und mir Recht schafft, mich ans Licht herausbringt; ich werde Seine Gerechtigkeit sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'Daß meine Feindin es sehe und Scham decke sie, die zu mir sprach: Wo ist Jehovah, dein Gott? Meine Augen werden auf sie sehen; nun werden sie zerstampft wie der Kot der Gassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Der Tag ist da, deine Mauern zu bauen, an jenem Tag wird ferne sein die Satzung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'An jenem Tag kommt man bis zu dir von Aschur und Ägyptens Städten, und von Ägypten und bis zum Flusse und vom Meer zum Meer und von Berg zu Berg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'Aber zur Verwüstung wird das Land um seiner Bewohner willen, ob ihrer Werke Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, 'Weide dein Volk mit deiner Rute, die Herde deines Erbes, die einsam im Walde wohnt, inmitten Karmels; in Baschan sollen sie weiden und in Gilead, wie in der Ewigkeit Tagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Wie in den Tagen, da du auszogst aus dem Land Ägypten, will Ich es Wunder sehen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Es werden es die Völkerschaften sehen und sich schämen mit aller ihrer Macht, sie werden die Hand auf den Mund legen und ertauben ihre Ohren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'Sie werden Staub lecken wie die Schlange, wie die Kriechtiere der Erde hervorzittern aus ihren Verschlüssen, schaudernd sich nahen Jehovah, unserem Gotte, und sich fürchten vor Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Wer ist ein Gott wie Du, Der Missetat vergibt und vorbeigeht an der Übertretung dem Überreste Seines Erbes; der Seinen Zorn nicht immerfort festhält, weil Er Lust hat an Barmherzigkeit?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Er kehrt zurück, Sich unser zu erbarmen, unsere Missetaten zu unterwerfen; und Er wirft alle ihre Sünden in des Meeres Schlünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Du wirst dem Jakob Wahrheit geben, dem Abraham Barmherzigkeit, die Du seit der Vorzeit Tagen unseren Vätern geschworen hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Weissagung über Niniveh. Buch des Gesichtes Nachums, des Elkoschiters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Ein eifernder und rächender Gott ist Jehovah. Ein Rächer ist Jehovah, ist ergrimmt, ein Rächer ist Jehovah an Seinen Drängern, und trägt nach Seinen Feinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Jehovah ist langmütig und groß an Kraft und läßt nicht ungestraft. Jehovah, im Sturmwind und im Wetter ist Sein Weg, und die Wolke ist Seiner Füße Staub.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'Er bedroht das Meer und trocknet es aus, und läßt vertrocknen alle Flüsse; Baschan verschmachtet und Karmel und die Blüte des Libanon verschmachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Berge erbeben vor Seinem Angesicht, und die Hügel zerfließen, und vor Seinem Angesicht erhebt sich die Erde und die Welt, und die darin wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Wer wird stehen vor Seinem Unwillen? Und wer wird vor Seines Zornes Entbrennen bestehen? Sein Grimm ergießt sich wie Feuer, und die Felsen zerspringen vor Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Gut ist Jehovah als Stärke am Tag der Drangsal und kennt die, so auf Ihn sich verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Durch überströmende Flut macht Er ihrem Ort ein Ende, und Seinen Feinden setzt nach die Finsternis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Was erdenkt ihr wider Jehovah? Eine Vollendung macht Er. Die Drangsal ersteht nicht zweimal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Wie in Dornen verstrickt und wie vom Zechen berauscht, werden sie wie die verdorrte Stoppel völlig aufgefressen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Aus dir ging aus, der Böses wider Jehovah erdachte, Ruchloses beraten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'So spricht Jehovah: Und kommen sie in Vollzahl, und viele, so sollen sie weggeschoren werden und vorbei sein. Und habe Ich dich niedergedrückt, so werde Ich dich nicht mehr niederdrücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'Und nun breche Ich sein Jochholz ab von dir, und will abreißen deine Bande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'Und Jehovah gebeut über dir: Nicht soll hinfort von deinem Samen mehr gesät werden. Vom Hause deines Gottes rotte Ich das Schnitzbild und das Gußbild aus, Ich setze dir dein Grab, denn du wardst gering.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Siehe, auf den Bergen die Füße des Heilsboten, der Frieden verkündigte. Feiere du deine Feste, Jehudah, entrichte deine Gelübde; denn durch dich zieht nicht wiederum hindurch der Belial, er ist ganz ausgerottet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Herauf zieht der Zerstreuer vor dein Angesicht. Bewahrt das Bollwerk! Spähe auf den Weg, mache fest die Lenden, verstärke sehr die Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Denn Jehovah wendet zurück den Stolz Jakobs wie den Stolz Israels; denn die Ausleerer haben ausgeleert, und ihre Weinranken haben sie verdorben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Die Tartsche seiner Helden ist gerötet, die Männer der Tapferkeit sind im Scharlach; im Feuer der Fackeln ist der Streitwagen, am Tage, da er sich bereit macht, und die Lanzen geschwungen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'In den Gassen rasen die Streitwagen, sie rennen dahin auf den Straßen, ihr Aussehen ist wie das der Fackeln, wie die Blitze fahren sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Er gedenkt seiner Stattlichen, sie straucheln in ihrem Gehen, sie eilen nach der Mauer. Die Bedeckung wird bereit gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'Die Tore der Flüsse werden geöffnet, und der Palast zerfließt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Es ist beschlossen: Sie wird gefangen hinausgeführt, und ihre Mägde wehklagen wie die Stimme der Tauben, und schlagen auf ihr Herz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Und Niniveh war wie ein Teich von Wassern von den Tagen an, da es bestand, und sie fliehen: Stehet, stehet! Und niemand wendet sich um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Raubt Silber, raubt Gold, und kein Ende des Vorrats, eine Herrlichkeit an allen den kostbarsten Gefäßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Leerheit und Ausleerung und Ausräumung, und ein zerschmelzendes Herz, und Schlottern der Knie, und Pein in allen Landen, und alle Angesichter ziehen ihr Wangenrot ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Wo ist der Löwen Wohnstätte und die Weide der jungen Löwen, wo der Löwe, der alte Löwe und das Junge des Löwen sich ergingen, und niemand sie aufscheuchte!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Der Löwe zerfleischte genug für seinen Jungen, und erwürgte für seine alte Löwinnen, und füllte seine Höhlen mit dem Zerfleischten und seine Wohnstätte mit dem, was er zerfleischt. Siehe, Ich bin wider dich, spricht Jehovah der Heerscharen, und laß brennen mit Rauch seine Streitwagen, und deine jungen Löwen fresse das Schwert, und Ich rotte aus von der Erde dein Zerfleischtes, daß deiner Boten Stimme man nimmer hören soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Wehe der Stadt des Blutes! Ganz ist sie von Lug, von Räuberei erfüllt; sie weicht nicht vom Zerfleischen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Der Peitsche Stimme und die Stimme des Rasselns der Räder, und es wiehert das Roß und hüpft der Streitwagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Der Reiter, der heraufzieht, und die Flamme des Schwertes, und der Blitz des Spießes, und die vielen Erschlagenen, und der Haufen der Leichen, und kein Ende der Leiber, sie straucheln über ihre Leiber!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'Wegen der Menge der Buhlereien der Buhlerin, gut an Gnade, der Meisterin der Zaubereien, die mit ihren Buhlereien Völkerschaften verkaufte, und Familien mit ihren Zaubereien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Siehe, Ich bin wider dich, spricht Jehovah der Heerscharen, und will deine Säume aufdecken über dein Angesicht, und laß die Völkerschaften deine Blöße und die Königreiche deine Unehre sehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'Und will Abscheuliches auf dich werfen, dich verunehren und dich zur Schau stellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'Und es soll geschehen, daß alle, die dich sehen, von dir entfliehen und sagen: Verheeret ist Niniveh! Wer wird ihr Beileid zeigen, woher soll ich einen Tröster für dich suchen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Bist du besser denn No-Amon, das in den Nilströmen lag, Wasser rings um sie her; deren Vermögen das Meer war, und ihre Mauer aus dem Meere?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Kusch war seine Macht und Ägypten, und war kein Ende; Put und Lubim waren dir zum Beistand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Auch sie ging in Verbannung, in die Gefangenschaft; auch wurden ihre Kindlein zerschmettert an aller Gassen Ecken; um ihre Herrlichen warfen sie das Los, und all ihre Großen wurden mit Ketten gefesselt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Auch du wirst trunken, wirst dich verbergen und eine Schutzwehr suchen vor dem Feind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'All deine Festungen sind Feigenbäume mit Frühfeigen; so man sie schüttelt, fallen sie in den Mund des Essenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Siehe, dein Volk innerhalb deiner sind Weiber, deinen Feinden öffnet man die Tore deines Landes, Feuer frißt deine Riegel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Schöpfe dir Wasser der Belagerung. Mache stark deine Festungen. Komme in den Kot und zerstampfe den Ton, mache den Ziegelofen fest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Dort wird das Feuer dich fressen, das Schwert dich ausrotten, dich fressen wie die Grille; mache dich zahlreich wie die Grille, zahlreich wie die Heuschrekke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Du vermehrst deine Kaufleute mehr als des Himmels Sterne: die Grille rückt aus und fliegt davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Deine Diademträger sind wie die Heuschrecken, und deine Befehlshaber wie ein Heuschreckenschwarm eines Heuschreckenschwarms; sie lagern am kalten Tage an den Mauern. Geht die Sonne auf, so entfliehen sie, und man weiß nicht den Ort, wo sie gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Es schlummern deine Hirten, König Aschurs, da liegen deine Stattlichen, auf die Berge ist dein Volk zerstoben, und keiner bringt sie zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Für deinen Bruch gibt es kein Verharschen, heillos ist dein Schlag. Jeder, der das Gerücht von dir hört, klatscht über dir die Hände; denn über wen ist nicht beständig Böses von dir übergeflossen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Die Weissagung, die Chabakkuk, der Prophet, erschaute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Wie lange, Jehovah, soll ich aufschreien, und Du willst nicht hören, - schreien zu Dir: Gewalttat! und Du wirst nicht helfen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Warum läßt Du mich Unrecht sehen und Mühsal erblicken, und Verheerung und Gewalttat ist vor mir? Und Hader ist da, und das Rechten erhebt sich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Darum erstarrt das Gesetz und nimmermehr geht aus das Gericht; denn der Ungerechte umgibt den Gerechten. Darum geht aus ein verdrehtes Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Seht unter die Völkerschaften und blicket; erstaunet euch und staunet; denn ein Werk wirkt Er in euren Tagen. Erzählte man es, ihr würdet es nicht glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Denn siehe, Ich lasse aufstehen die Chaldäer, die bittere und eilige Völkerschaft, die hinzieht in des Landes Breiten, erblich zu besitzen Wohnungen, die nicht die ihrigen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Schrecklich und furchtbar ist es: ihr Recht und ihre Erhebung geht von ihnen selbst aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Und leichter sind den Parder ihre Rosse, und schärfer den Wölfe des Abends; und es zerstieben ihre Reiter. Und ihre Reiter kommen aus der Ferne, sie fliegen wie der Adler herbei, der zum Fraße sich sputet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Sie allesamt kommen zur Gewalttat, nach Osten steht ihrer Angesichter Streben; er sammelt Gefangene wie Sand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Und er verspottet die Könige, und Beherrscher sind ihm zum Gelächter; er lacht jeder Festung, und häuft Staub auf und erobert sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Dann dringt der Wind ein und geht vorbei, und er wird schuldig, dessen Kraft ihm zum Gotte ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Bist Du, Jehovah, nicht von der Vorzeit her mein Gott, mein Heiliger? Wir werden nicht sterben. Jehovah, Du hast ihn zum Gericht gesetzt und, o Fels, zur Rüge ihn gegründet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Deine Augen sind zu rein, daß Du das Böse nicht siehst, nicht blickst auf das Mühsal, warum erblickst Du die Treulosen; Du schweigst, wenn der Ungerechte den Gerechteren denn er verschlingt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'Und du machst den Menschen wie des Meeres Fische, wie das Kriechtier, das keinen Herrscher hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Er zieht jedes herauf an der Angel, er erhascht es in seinem Garn und sammelt es in sein Fischernetz. Darum ist er fröhlich und frohlockt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Darum opfert er seinem Garn und räuchert seinem Fischernetz, weil durch sie sein Teil ist fett und seine Speise üppig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Soll er darum sein Garn also leeren, und beständig die Völkerschaften erwürgen ohne Mitleid?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Ich stehe auf meiner Hut, und habe mich auf die Festung gestellt und spähe, um zu sehen, was Er in mir will reden, und was ich erwidern soll in meiner Rüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'Und Jehovah antwortete mir und sprach: Schreibe das Gesicht und grabe es auf Tafeln ein, daß es durchlaufe, wer es liest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Denn das Gesicht ist noch auf eine bestimmte Zeit und wird ausgesprochen am Ende und täuscht nicht. Wenn es säumt, so harre darauf, denn es kommt gewißlich und zögert nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Siehe, wer aufgetrieben ist, dessen Seele handelt nicht redlich in ihm; aber der Gerechte lebt in seinem Glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'Und ebenso wie der Wein berückt, so ist der übermütige Mann, und er verweilt nicht und macht breit wie die Hölle seine Seele, und ist wie der Tod und wird nicht satt, und versammelt zu sich alle Völkerschaften, und bringt zu sich zusammen alle Völker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Werden nicht alle diese einen Spruch erheben über ihn, und ein Spottlied, Rätsel über ihn, und sprechen: Wehe dem, der mehret was sein nicht ist. Wie lange? und er beschwert sich mit dichtem Kot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Werden nicht unversehens aufstehen, die dich beißen, und erwachen, die dich verschütteln, und du wirst ihnen zur Plünderung?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Denn du hast viele Völkerschaften ausgebeutet, alle die übrigen Völker sollen dich ausbeuten, ob dem Blute des Menschen, und der Gewalttat am Lande, an der Hauptstadt und allen, die darin wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Wehe ihm, der nach bösem Gewinn geizt für sein Haus, um in die Höhe sein Nest zu setzen, auf daß er sich errette von des Bösen Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Schande hast du deinem Haus beraten, daß du so viele Völker hast abgeschnitten und dich versündigt an deiner Seele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Denn der Stein schreit von der Wand, und ihm antwortet der Sparren von dem Holzwerk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Wehe dem, der die Stadt mit Blut baut, und die Hauptstadt mit Verkehrtheit festigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Ist es nicht so? Siehe, von Jehovah der Heerscharen geschieht es, daß Völker sich für das Feuer müde machen, und Volksstämme sich abmatten für das Leere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Denn voll wird werden die Erde von der Erkenntnis der Herrlichkeit Jehovahs, wie die Wasser sich decken über das Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Wehe dem, der seinen Genossen trinken läßt, der du aus deinem Schlauche einschenkst, und ihn auch berauschest, um auf ihre Blöße zu blicken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Satt wirst du an Unehre werden statt an Herrlichkeit. Trinke auch du und zeige die Vorhaut. Umgehen zu dir wird der Becher der Rechten Jehovahs, und Gespei der Unehre über deine Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Denn die Gewalttat des Libanon wird dich bedecken, und die Verheerung der Tiere sie entsetzen, ob dem Blute der Menschen und der Gewalttat am Lande, an der Hauptstadt und an allen, die darin wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Was nützt das Schnitzbild, daß sein Bildner es schnitzte, das Gußbild und der Lüge Unterweiser, daß seines Bildes Bildner ihm vertraut und macht stumme Götzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Wehe dem, der zum Holze spricht: Erwache!, zum stillen Stein: Wache auf! Er soll dich unterweisen! Siehe, in Gold und Silber ist es gefaßt, aber kein Geist ist in seinem Inneren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Aber Jehovah ist im Tempel Seiner Heiligkeit. Stille sei vor Seinem Angesicht die ganze Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Gebet Habakuks, des Propheten, auf Schigjonoth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Jehovah, Dein Gerücht habe ich gehört, ich fürchte mich. Jehovah, Dein Werk: inmitten der Jahre mache es lebendig, inmitten der Jahre mache es kund. Im Toben gedenke des Erbarmens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Gott kommt von Theman und der Heilige vom Berg Paran, Selah. Die Himmel deckt Seine Majestät, und Seines Lobes ist voll die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'Und ein Glanz wird es sein wie das Licht. Strahlen hat Er aus Seiner Hand, und allda ist die Umhüllung Seiner Stärke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Vor Ihm her geht die Pest, und von Seinen Füßen geht aus die Glut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Er steht und mißt die Erde; Er sieht und zerscheitert die Völkerschaften, die immerwährenden Berge zerstreuen sich, die Hügel der Ewigkeit beugen sich, Sein sind die Gänge der Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'Unterhalb Aven sehe ich die Zelte Kuschans. Die Zeltteppiche des Landes Midjans zittern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Ist wider die Flüsse entbrannt Jehovah, ist Dein Zorn wider die Flüsse, ist wider das Meer Dein Wüten, daß Du reitest auf Deinen Rossen? Dein Streitwagen ist Heil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Die Blöße Deines Bogens entblößt sich; Schwüre der Stämme sind der Spruch, Selah. Mit Flüssen spaltest Du die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Es sehen Dich, es kreißen die Berge; der Wasser Strömung geht dahin, der Abgrund gibt hervor seine Stimme; die Höhe erhebt ihre Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Die Sonne, der Mond standen in ihrem Wohnort; beim Lichte Deiner Pfeile gehen sie dahin, beim Glanz des Blitzes Deines Spießes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'Im Unwillen schreitest Du über das Land, im Zorn drischst Du Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Du ziehst aus, Dein Volk zu retten, zu retten Deinen Gesalbten; Du durchbohrst das Haupt vom Hause des Ungerechten, entblößest den Grund bis an den Hals; Selah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Mit seinen Stäben durchbrichst Du das Haupt seiner Ungläubigen. Sie stürmen daher, als wollten sie mich zerstreuen. Ihr Jauchzen ist, als würden sie den Elenden auffressen im Verborgenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Du trittst in das Meer mit Deinen Rossen, in den Schlamm vieler Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Ich hörte es, und mein Leib zitterte. Meine Lippen erklangen ob der Stimme. Fäulnis kommt in mein Gebein, und ich zitterte an meinem Platz, da ich ruhen werde am Tage der Drangsal, wenn heraufkommt gegen das Volk, der es angreift.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Denn nicht wird blühen der Feigenbaum, und kein Gewächs sein an den Weinstöcken, täuschen wird des Ölbaums Werk, und die Felder werden keine Speise bringen. Das Kleinvieh wird Er von der Hürde raffen, und in den Ställen wird kein Rind da sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'Ich aber will in Jehovah jauchzen, frohlocken in dem Gotte meines Heils.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Jehovah, der Herr, ist mein Vermögen und stellt meine Füße gleich den Hindinnen, und läßt mich treten auf meine Höhen. - Dem Sangmeister auf meinen Saitenspielen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Das Wort Jehovahs, welches geschah zu Zephanjah, dem Sohne Kuschis, des Sohnes Gedaljahs, des Sohnes Amarjahs, des Sohnes Chiskijahs, in den Tagen Joschijuhus, des Sohnes Amons, König von Jehudah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Ich raffe alles weg von der Fläche des Bodens, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Ich raffe weg Menschen und Vieh, raffe weg das Gevögel des Himmels und des Meeres Fische, und das Anstößige samt den Ungerechten, und rotte den Menschen aus von der Fläche des Bodens, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'Und recke Meine Hand aus über Jehudah, und über alle, die da wohnen in Jerusalem, und rotte aus von diesem Orte des Baals Überrest mit den Namen der Götzenpfaffen, mit den Priestern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'Und die auf den Dächern das Heer der Himmel anbeten, und die anbeten, die schwören bei Jehovah, und schwören bei ihrem König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'Und die von Jehovah zurückgewichen, und Jehovah nicht gesucht, und nicht nach Ihm gefragt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Seid stille vor dem Herrn Jehovah, denn Jehovahs Tag ist nahe; denn ein Opfer hat Jehovah bereitet, geheiligt, die von Ihm Gerufenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'Und an dem Tage von Jehovahs Opfer soll geschehen, daß Ich heimsuche die Obersten und die Königssöhne und alle, die in ausländisches Kleid sich kleiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'Und will heimsuchen an jenem Tag alle, die über die Schwelle springen, die, so ihres Herrn Haus mit Gewalttat und Betrug erfüllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'Und wird sein an jenem Tage, spricht Jehovah, die Stimme des Geschreis vom Tore der Fische und ein Geheul von dem zweiten, und großes Zerbrechen von den Hügeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Heult, die ihr in dem Machtesch wohnet; denn all das Volk der Händler ist untergegangen und ausgerottet alle, die beladen sind mit Silber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'Und zu der Zeit wird es geschehen, daß mit Leuchten Ich Jerusalem durchsuche, und die Leute heimsuche, die verhärtet auf ihren Hefen sitzen, die in ihrem Herzen sagen: Jehovah tut nicht Gutes und nicht Böses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'Und ihr Vermögen soll geplündert werden, und zur Verwüstung ihre Häuser. Und sie bauen Häuser, aber wohnen nicht darin, und pflanzen Weinberge und trinken nicht ihren Wein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Nahe ist der große Tag Jehovahs, nahe und eilt sehr: Die Stimme des Tages Jehovahs, bitterlich schreit dort auf der Held.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Ein Tag des Wütens ist jener Tag, ein Tag der Drangsal und der Angst, ein Tag des Tosens und des Getöses, ein Tag der Finsternis und der Dunkelheit, ein Tag der Wolke und des Wolkendunkels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'Ein Tag der Posaune und des Feldgeschreis über den festen Städten und den hohen Ecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'Und Ich werde die Menschen in Drangsal bringen; sie werden wie die Blinden umhergehen, weil sie wider Jehovah sündigten. Und ihr Blut soll hingeschüttet werden wie Staub und wie Kot ihr Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Weder ihr Silber, noch ihr Gold vermag sie zu erretten am Tage von Jehovahs Wüten, und mit Seines Eifers Feuer wird das ganze Land aufgefressen; denn eine Vollendung, ja eine bestürzende macht Er mit allen, die im Lande wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Sammelt euch zusammen, sammelt euch, o Völkerschaft, die nicht erblaßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'Ehe die Satzung gebiert, wie Spreu der Tag vorübergeht, ehe denn das Entbrennen des Zorns Jehovahs über euch komme, ehe der Tag des Zornes Jehovahs über euch komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Suchet Jehovah, alle ihr Sanftmütigen des Landes, die ihr nach Seinem Recht handelt! Suchet Gerechtigkeit, sucht Sanftmut, ob ihr vielleicht am Tage des Zorns Jehovahs verborgen werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Denn Gazah wird verlassen sein und Aschkelon verwüstet, Aschdod am hellen Mittag ausgetrieben und Ekron ausgewurzelt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Wehe euch, die ihr den Landstrich des Meeres bewohnt, du Völkerschaft der Kereter; wider euch ist Jehovahs Wort, Kanaan, der Philister Land, Ich werde dich zerstören, daß niemand da wohnen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'Und es soll der Landstrich am Meere zu Wohnorten, zu Ausgrabungen der Hirten und zu Hürden des Kleinviehs werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'Und soll der Landstrich dem Überrest des Hauses Jehudah werden, sie sollen darauf weiden, am Abend in den Häusern Aschkelons sich lagern; denn Jehovah, ihr Gott, wird sie heimsuchen und zurückwenden ihre Gefangenschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Ich habe Moabs Schmähen gehört und die Verhöhnungen der Söhne Amons, wie sie Mein Volk geschmäht und wider ihre Grenze sich groß gemacht haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Darum, bei Meinem Leben, spricht Jehovah der Heerscharen, der Gott Israels, wie Sodom soll Moab und wie Gomorrah Ammons Söhne werden, überlassen den Nesseln, und wo man gräbt Salz, und verwüstet ewiglich. Der Überrest von Meinem Volk soll sie berauben, und die übrigen Meiner Völkerschaft sollen sie beerben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'Dies wird ihnen für ihren Stolz, daß sie schmähten und sich groß machten über das Volk Jehovahs der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Furchtbar wird über ihnen Jehovah sein; denn alle Götter des Landes läßt Er dahinschwinden; und sie werden Ihn anbeten, jeder Mann aus seinem Orte, alle Inseln der Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Auch ihr, Kuschiter; durch Mein Schwert sollen sie erschlagen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'Und Er wird Seine Hand ausrecken über Mitternacht, und Aschur zerstören, und Niniveh legt Er in Verwüstung, dürre wie die Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'Und in ihrer Mitte werden Herden lagern, alles wilde Tiere der Völkerschaften, so der Pelikan und der Entenadler übernachten in ihren Knäufen; im Fenster singt eine Stimme, die Öde ist auf der Schwelle, denn die Zedernbretter hat Er bloßgelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'Das ist die Stadt, die jauchzende, die sicher dasaß, die in ihrem Herzen sprach: Ich bin es, und keine außer mir! Wie ward sie zur Verwüstung, zum Lagerplatz dem wilden Tier! Ein jeder, der an ihr vorübergeht, zischt, er schwenkt seine Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Wehe dir, du widerspenstige, du befleckte, du bedrückende Stadt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Sie hört nicht auf die Stimme, nimmt keine Zucht an, traut nicht auf Jehovah, naht nicht zu ihrem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Brüllende Löwen sind ihre Obersten in ihrer Mitte, ihre Richter Abendwölfe, die nichts bis zum Morgen überlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Ihre Propheten sind leichtfertig, Männer der Treulosigkeit; ihre Priester entweihen das Heilige, tun Gewalt an dem Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Jehovah ist gerecht in ihrer Mitte, tut nichts Verkehrtes; am Morgen, am Morgen gibt Er Sein Gericht ans Licht. Er läßt es nicht fehlen; aber der Verkehrte kennt keine Scham.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Ich rotte Völkerschaften aus, verwüstet sind ihre Ecken, Ich veröde ihre Gassen, so daß niemand vorübergeht, abgeödet sind ihre Städte, daß kein Mann da ist, daß keiner darin wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Ich sprach: Fürchte Mich nur, nimm Zucht an, und ihre Wohnstätte soll nicht ausgerottet werden, nach allem, das Ich über sie bestellt habe; doch früh aufstehend, verdarben sie ihr Tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Darum harrt auf Mich, spricht Jehovah, bis zu dem Tage, da Ich Mich aufmache zum Raub; denn Mein Gericht ist, daß Ich die Völkerschaften sammle, daß Ich die Königreiche zusammenbringe, auf daß Ich über sie ausschütte Meinen Unwillen, all Meines Zornes Entbrennung, daß in dem Feuer Meines Eiferns alles Land aufgefressen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Denn dann werde Ich Mich zu Völkern wenden mit lauter Lippe, daß sie alle den Namen Jehovahs anrufen und Ihm dienen mit einer Schulter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Von jenseits der Flüsse Kuschs, die so Mich anflehen, die Tochter Meiner Zerstreuten, sie werden Mir Geschenke herbeibringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'An jenem Tage mußt du dich nicht schämen ob all deiner Taten, wodurch du von Mir abgefallen bist; denn dann nehme Ich weg aus deiner Mitte die übermütig Jauchzenden, daß du nicht fürder mehr hoffärtig seist auf dem Berge meiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'Und Ich lasse verbleiben in deiner Mitte ein elendes und geringes Volk, und sie sollen sich verlassen auf den Namen Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Israels Überrest wird nichts Verkehrtes tun, und nichts Falsches reden. Und in ihrem Munde wird man nicht des Truges Zunge finden. Denn sie werden weiden und sich lagern, und niemand scheucht sie auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Lobsinge, du Tochter Zijons, rufe laut, Israel, sei fröhlich und jauchze von ganzem Herzen, Tochter Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Jehovah hat deine Gerichte weggenommen, hat abgewandt deinen Feind. Israels König ist Jehovah in deiner Mitte, kein Böses wirst du mehr fürchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'An jenem Tage wird man sprechen zu Jerusalem: Fürchte dich nicht! Laß deine Hände, Zijon, nicht erschlaffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Jehovah, dein Gott, ist in deiner Mitte, der Held, Der rettet. Er wird ob dir Sich freuen mit Fröhlichkeit, wird stille schweigen in Seiner Liebe, wird jubelnd frohlocken über dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Die, welche sich vom Festorte weg grämten, sammle Ich, sie waren fort von dir. Eine Last war auf ihr, eine Schmach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Siehe, Ich werde es tun zur selben Zeit mit allen deinen Bedrückern, und rette die, welche hinkt, bringe die Verstoßenen zusammen; und Ich setze dieselben zum Lobe und zum Namen in all dem Lande ihrer Scham.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Zu jener Zeit bringe Ich euch herein, und zu der Zeit bringe Ich euch zusammen; denn zum Namen und zum Lob gebe Ich euch unter allen Völkern der Erde, wenn Ich eure Gefangenschaft vor euren Augen zurückgewendet habe, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'Im zweiten Jahr des Königs Darius, im sechsten Monat, am ersten Tag des Monats geschah das Wort Jehovahs durch die Hand Chaggais, des Propheten, an Serubbabel, den Sohn Schealthiels, den Statthalter Jehudahs, und an Jehoschua, den Sohn Jehozadaks, den Hohenpriester, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'So spricht Jehovah der Heerscharen und sagt: Dies Volk spricht: Die Zeit ist nicht gekommen, die Zeit, Jehovahs Haus zu bauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'Und es geschah Jehovahs Wort durch die Hand Chaggais, des Propheten, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Ist die Zeit da für euch, daß ihr in euren getäfelten Häusern sitzet und dieses Haus ist verödet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Nun aber spricht Jehovah der Heerscharen also: Richtet euer Herz auf eure Wege!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Ihr sät viel und bringt wenig herein. Ihr esset, und nicht zur Sättigung; ihr trinkt, und nicht zur Trunkenheit, ihr kleidet euch und werdet nicht warm; und was ihr verdient, verdient ihr in einen löchrigen Beutel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'So spricht Jehovah der Heerscharen: Richtet euer Herz auf eure Wege!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Steigt auf den Berg und bringt Holz herein und baut das Haus, daß Ich daran Wohlgefallen habe und verherrlicht werde! spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Ihr wandtet euch auf viel, und siehe, es ward zu wenig; und ihr brachtet es zum Haus herein, und Ich blies darein. Warum? spricht Jehovah der Heerscharen. Um Meines Hauses willen, das verödet ist, und ihr laufet, jeder Mann nach seinem Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Darum verhalten die Himmel euch den Tau, und die Erde verhält ihr Gewächs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'Und Ich rief die Dürre über die Erde und über die Berge und über das Korn und über den Most und über das Öl und über das, was der Boden hervorbringt, und über Mensch, über Vieh, und über alle Arbeit der Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'Und Serubbabel, der Sohn Schealthiels, und Jehoschua, der Sohn Jehozadaks, der Hohepriester, und all der Überrest des Volkes hörten auf die Stimme Jehovahs, ihres Gottes, und auf die Worte Chaggais, des Propheten, wie ihn Jehovah, ihr Gott, hatte gesandt; und das Volk fürchtete sich vor dem Angesichte Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Und Chaggai, der Bote Jehovahs, sprach in der Botschaft Jehovahs zum Volk und sagte: Ich bin mit euch, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'Und Jehovah erregte den Geist Serubbabels, des Sohns Schealthiels, des Statthalters Jehudahs, und den Geist Jehoschuas, des Sohnes Jehozadaks, des Hohenpriesters, und den Geist all des Überrests vom Volk; und sie kamen und taten das Werk am Hause Jehovahs der Heerscharen, ihres Gottes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'Am vierundzwanzigsten Tag des Monats im sechsten im zweiten Jahr des Königs Darius.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Im siebenten, am einundzwanzigsten des Monats geschah das Wort Jehovahs durch die Hand Chaggais, des Propheten, und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Sprich doch zu Serubbabel, dem Sohn Schealthiels, dem Statthalter Jehudahs, und zu Jehoschua, dem Sohn Jehozadaks, dem Hohenpriester, und zu dem Überrest des Volkes und sprich:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Wer ist unter euch übriggeblieben, der dieses Haus in seiner ersten Herrlichkeit gesehen hat? Und wie seht ihr es jetzt? Ist es nicht im Vergleich wie nichts in euren Augen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Und nun sei stark, Serubbabel, spricht Jehovah, und sei stark, Jehoschua, Sohn Jehozadaks, du Hoherpriester, und sei stark, alles Volk des Landes, spricht Jehovah, und macht es; denn Ich bin mit euch, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Mit dem Worte, mit dem Ich mit euch abgeschlossen, da ihr aus Ägypten auszogt, und mit Meinem Geiste, der in eurer Mitte steht, fürchtet euch nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Denn so spricht Jehovah der Heerscharen: Noch ein Kleines ist es, so lasse Ich die Himmel und die Erde erbeben und das Meer und das Trockene.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'Und Ich lasse alle Völkerschaften erbeben, daß komme die Begehr aller Völkerschaften, und Ich erfülle dieses Haus mit Herrlichkeit, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Mein ist das Silber und Mein das Gold, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Größer wird sein die Herrlichkeit dieses späteren Hauses als die des ersten, spricht Jehovah der Heerscharen, und an diesem Orte will Ich Frieden geben, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Am vierundzwanzigsten des neunten im zweiten Jahr des Darius geschah das Wort Jehovahs durch die Hand Chaggais, des Propheten, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'So spricht Jehovah der Heerscharen: Frage doch die Priester über das Gesetz und sprich:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Siehe, ein Mann trägt Fleisch der Heiligkeit im Zipfel seines Kleides und berührt mit seinem Zipfel Brot und Gekochtes, und Wein und Öl, und irgendwelche Speise, wird es geheiligt? Und die Priester antworteten und sprachen: Nein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Und Chaggai sprach: Wo aber ein durch eine Seele Unreiner dieser irgendeines anrührt, wird es unrein? Und die Priester antworteten und sprachen: Es wird unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Und Chaggai antwortete und sprach: So ist dies Volk und so ist diese Völkerschaft vor Meinem Angesicht, spricht Jehovah, und so alles Tun ihrer Hände, und was sie allda darbringen, ist unrein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'Und nun richtet doch euer Herz darauf von dem Tage an und weiter: Ehe man Stein legt auf Stein am Tempel Jehovahs;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Vor diesem, kam man zum Kornhaufen von zwanzigen, so waren es zehn; kam man zur Kufe, um fünfzig zu schöpfen aus der Kelter, so waren es zwanzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Ich schlug euch mit Kornbrand, und mit Vergilbung und mit Hagel in allem Tun eurer Hände; und doch wollt ihr nicht zu Mir, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'So richtet euer Herz darauf von diesem Tage an und weiter, vom vierundzwanzigsten des neunten, von dem Tage an, da der Tempel Jehovahs gegründet ward, darauf richtet euer Herz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Ist nicht die Saat noch in dem Speicher? Und bis auf den Weinstock und den Feigenbaum und den Granatbaum und den Baum der Oliven, die nicht getragen, will Ich segnen von diesem Tage an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'Und es geschah das Wort Jehovahs zum zweitenmal an Chaggai am vierundzwanzigsten des Monats, und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Sprich zu Serubbabel, dem Statthalter Jehudahs, und sage: Ich lasse erbeben die Himmel und die Erde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'Und kehre um den Thron von Königreichen, und vernichte die Stärke der Königreiche der Völkerschaften, und kehre um die Streitwagen und die darin fahren; und das Roß und dessen Reiter sollen herabstürzen, der Mann durch das Schwert seines Bruders.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'An diesem Tage, spricht Jehovah der Heerscharen, nehme Ich dich, Serubbabel, Sohn Schealthiels, meinen Knecht, spricht Jehovah, und setze dich, wie den Siegelring; denn dich habe Ich erwählt, spricht Jehovah der Heerscharen..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Im achten Monat, im zweiten Jahr des Darius, geschah das Wort Jehovahs an Sacharjah, den Sohn Berechjahs, des Sohnes Iddos, den Propheten, und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Jehovah war sehr entrüstet über eure Väter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Du aber sprich zu ihnen: So spricht Jehovah der Heerscharen: Kehret zurück zu Mir, spricht Jehovah der Heerscharen, dann kehre Ich zurück zu euch, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Seid nicht wie eure Väter, denen die ersten Propheten zuriefen und sprachen: So spricht Jehovah der Heerscharen: Kehret doch zurück von euren bösen Wegen und euren bösen Werken, aber sie hörten nicht und merkten nicht auf Mich, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Wo sind nun eure Väter? Und die Propheten, leben sie ewig?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Doch Meine Worte und Meine Satzungen, die Ich Meinen Knechten, den Propheten, hatte geboten, erreichten sie eure Väter nicht? Und sie kehrten zurück und sprachen: Wie Jehovah der Herrscharen gesonnen uns zu tun nach unseren Wegen und nach unseren Werken, so hat Er mit uns getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Am vierundzwanzigsten Tage des elften Monats, welcher ist der Monat Schebat, im zweiten Jahr des Darius, geschah das Wort Jehovahs an Sacharjah, den Sohn Berechjahus, des Sohnes Iddos, an den Propheten, und Er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Ich sah in der Nacht, und siehe, ein Mann ritt auf einem roten Pferd, und er stand zwischen den Myrten, die in der Tiefe sind, und hinter ihm rote, braune und weiße Pferde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'Und ich sprach: Was sind diese, mein Herr? Und der Engel, der mit redete, sprach zu mir: Ich will dich sehen lassen, was diese sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'Und es hub an der Mann, der zwischen den Myrten stand, und sprach: Diese sind es, die Jehovah sandte, durch das Land zu ziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'Und sie antworteten dem Engel des Jehovah, der zwischen den Myrten stand, und sprachen: Wir sind durch das Land gezogen, und siehe, das Land wird bewohnt und rastet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Und es antwortete der Engel Jehovahs und sprach: Jehovah der Heerscharen, wie lange willst Du Dich nicht erbarmen Jerusalems und der Städte Jehudahs, gegen die Du diese siebzig Jahre ergrimmt bist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'Und es antwortete Jehovah dem Engel, der mit mir redete, gute Worte, tröstliche Worte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Und zu mir sprach der Engel, der mit mir redete: Rufe und sprich: So spricht Jehovah der Heerscharen: Ich eifere mit großem Eifer für Jerusalem und für Zijon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'Und Ich bin entrüstet mit großer Entrüstung wider die sorglosen Völkerschaften, indem Ich ein wenig entrüstet war, und sie zum Übel beistanden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Darum, so spricht Jehovah, kehre Ich zurück mit Erbarmen zu Jerusalem: Mein Haus, spricht Jehovah der Heerscharen, soll in ihm aufgebaut und die Meßschnur über Jerusalem ausgespannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Noch rufe und sprich: So spricht Jehovah der Heerscharen: Noch werden sich Meine Städte ausbreiten wegen des Guten, und Jehovah tröstet noch Zijon, und erwählt noch Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'Und ich hob meine Augen auf und sah, und siehe: vier Hörner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'Und ich sprach zu dem Engel, der mit mir redete: Was sind diese? Und er sprach zu mir: Dies sind die Hörner, die Jehudah, Israel und Jerusalem zersprengten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'Und Jehovah ließ mich vier Werkleute sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'Und ich sprach: Was sind diese gekommen zu tun? Und Er sprach, sprechend: Dies sind die Hörner, die Jehudah zersprengten, dermaßen, daß kein Mann das Haupt erhob. Und diese sind gekommen, diese aufzuscheuchen, niederzuwerfen die Hörner der Völkerschaften, die das Horn erhoben wider das Land Jehudah, um es zu zersprengen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Und ich hob meine Augen auf und sah, und siehe, da war ein Mann und eine Schnur zum Messen war in seiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Und ich sprach: Wohin gehst du? Und er sprach zu mir: Jerusalem zu messen, um zu sehen, was seine Breite und was seine Länge sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Und siehe, der Engel, der mit mir redete, ging hinaus, und ein anderer Engel kam heraus ihm entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Und er sprach zu ihm: Laufe, rede mit diesem Jüngling, sprechend: Als offen Land soll Jerusalem bewohnt werden ob der Menge von Mensch und Vieh in seiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Und Ich will, spricht Jehovah, ihm eine Mauer von Feuer ringsum sein und ihm zur Herrlichkeit sein in seiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Auf, auf! und fliehet aus dem Lande der Mitternacht! spricht Jehovah, denn wie die vier Winde der Himmel breite Ich euch aus, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'Auf Zijon, entrinne, die du bei Babels Tochter hast gewohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'Denn so spricht Jehovah der Heerscharen, nach der Verherrlichung hat Er mich zu den Völkerschaften gesandt, die euch ausgebeutet hatten; denn wer euch anrührt, der rührt Seinen Augapfel an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Denn siehe, Ich schwenke Meine Hand wider sie, daß sie zur Beute werden denen, die ihnen gedient, auf daß ihr erkennt, daß Jehovah der Heerscharen mich gesendet hat. Lobsinge und sei fröhlich, du Tochter Zijon; denn siehe, Ich komme und wohne in deiner Mitte, spricht Jehovah. Und viele Völkerschaften werden an jenem Tage Jehovah anhangen und Mein Volk werden; und Ich werde in deiner Mitte wohnen, auf daß du erkennst, daß Jehovah der Heerscharen mich zu dir gesendet hat. Und Jehovah erbet den Jehudah als sein Teil auf dem Boden der Heiligkeit und erwählt noch Jerusalem. Stille sei alles Fleisch vor dem Angesichte Jehovahs; denn Er ist aufgewacht aus der Wohnstätte Seiner Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'Und Er ließ mich Jehoschua, den Hohenpriester sehen, wie er vor dem Engel Jehovahs stand, und den Satan, der ihm zur Rechten stand, ihm zu widerstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'Und Jehovah sprach zum Satan: Jehovah bedrohe dich, Satan, ja, Jehovah bedrohe dich, Der Jerusalem erwählt hat. Ist dieser nicht ein Brand, aus dem Feuer entrissen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'Und Jehoschua war angetan mit schmutzigen Kleidern, und er stand vor dem Engel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'Und er hob an und sprach zu denen, die vor ihm standen, sprechend: Nehmt weg von ihm die schmutzigen Kleider; und sprach zu ihm: Siehe, Ich habe die Missetat von dir vorbeigehen lassen und dich bekleidet mit Feierkleidern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'Und Er sprach: setzet ihm einen reinen Kopfbund auf sein Haupt. Und sie setzten ihm einen reinen Kopfbund auf sein Haupt und zogen ihm Kleider an, und der Engel Jehovahs stand da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'Und es bezeugte der Engel Jehovahs den Jehoschua und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'So spricht Jehovah der Heerscharen: Wenn du in Meinen Wegen wandelst und wenn du Meiner Hut wartest, so sollst du auch Meinem Hause Recht sprechen und auch Meine Vorhöfe hüten, und Ich gebe dir Gänge zwischen den hier Stehenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'So höre denn, Jehoschua, Hoherpriester, du und deine Genossen, die vor dir sitzen, da sie Männer sind des Wahrzeichens: denn siehe, Ich lasse kommen Meinen Knecht, den Sproß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Denn siehe den Stein, den Ich vor Jehoschua legte, auf dem einen Stein sind sieben Augen. Siehe, Ich grabe selbst seine Eingrabung hinein, spricht Jehovah der Heerscharen, und lasse weichen die Missetat dieses Landes an einem Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'An jenem Tage, spricht Jehovah der Heerscharen, werdet ihr, jeder Mann seinem Genossen rufen unter den Weinstock und unter den Feigenbaum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'Und der Engel, der mit mir geredet, kehrte zurück und weckte mich auf wie einen Mann, der aus seinem Schlafe aufgeweckt wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'Und er sagte zu mir: Was siehst du? Und ich sagte: Ich sehe, und siehe, ein Leuchter, ganz von Gold, und sein Ölbehälter oben auf, und seine sieben Lampen darauf; sieben und sieben Gießröhren für die Lampen, die oben waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'Und zwei Ölbäume dabei, einer zur Rechten des Ölbehälters und einer zu seiner Linken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'Und ich hob an und sprach zu dem Engel, der mit mir redete, und sprach: Was sind diese, mein Herr?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'Und der Engel, der mit mir redete, antwortete und sprach zu mir: Weißt du nicht, was diese sind? Und ich sagte: Nein, mein Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Und er antwortete und sprach zu mir, sprechend: Dies Wort Jehovahs ist an Serubbabel, sprechend: Nicht durch Vermögen und nicht durch Kraft, sondern durch Meinen Geist, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Wer bist du, großer Berg? Vor Serubbabel wirst du eine Ebene, daß er herausbringe den Hauptstein mit dem Getöse: Gnade, Gnade ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Und es geschah Jehovahs Wort an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Die Hände Serubbabels gründeten dies Haus und seine Hände führen es aus. Und du sollst erkennen, daß Jehovah der Heerscharen mich zu euch gesendet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Denn wer will den Tag der kleinen Dinge verachten? Und sie sind fröhlich und sehen das Senkblei in Serubbabels Hand. Sieben sind diese, die Augen Jehovahs, sie durchstreifen die ganze Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'Und ich antwortete und sprach zu ihm: Was sollen diese zwei Ölbäume zur Rechten des Leuchters und zu seiner Linken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'Und ich hob zum zweitenmal an und sprach zu ihm: Was sind die zwei Beeren der Ölbäume, die zur Seite der zwei goldenen Röhren sind und aus sich das Gold leeren?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'Und Er sprach zu mir, sprechend: Weißt du nicht, was diese sind? Und ich sprach: Nein, mein Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, 'Und Er sprach: Dies sind die zwei Söhne des Ölbaums, die bei dem Herrn der ganzen Erde stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'Und ich wandte mich zurück und hob meine Augen auf und sah, und siehe, eine fliegende Schriftrolle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'Und Er sprach zu mir: Was siehst du? Und ich sprach: Ich sehe eine fliegende Schriftrolle. Ihre Länge ist zwanzig Ellen und ihre Breite zehn Ellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'Und Er sprach zu mir: Dies ist die Verwünschung, die ausgeht über die Angesichte des ganzen Landes: denn jeder, der da stiehlt, ist danach unschuldig wie sie, und jeder, der danach schwört, ist unschuldig wie sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Ich habe sie ausgehen lassen, spricht Jehovah der Heerscharen, daß sie eingehen soll in das Haus des Diebes und in das Haus dessen, der in Meinem Namen schwört zur Lüge, und sie soll herbergen inmitten seines Hauses, und auffressen dasselbe und sein Holz und seine Steine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Und der Engel, der mit mir redete, ging heraus und sprach zu mir: Hebe doch deine Augen auf, und siehe was da herausgeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Und ich sprach: Was ist das? und er sprach: Das ist das Ephah, das herauskommt. Und er sprach: Dies ist ihr Anblick im ganzen Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'Und siehe, ein Zentner Blei ward aufgehoben, und dieses eine Weib, das inmitten des Ephahs sitzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'Und er sprach: Dies ist die Ungerechtigkeit! und warf sie mitten in das Ephah, und warf das Bleigewicht auf seine Mündung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'Und ich hob meine Augen und sah, und siehe, zwei Weiber kamen hervor und Wind war in ihren Flügeln, und sie hatten zwei Flügel wie Flügel des Storches, und hoben das Ephah auf zwischen Erde und Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'Und ich sprach zu dem Engel, der mit mir redete: Wohin bringen sie das Ephah?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'Und er sprach zu mir: Um ihm ein Haus zu bauen im Lande Schinear. Und dort wird es gefestigt und in seiner Stätte niedergelassen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'Und ich wandte mich zurück und hob meine Augen auf und sah, und siehe, vier Streitwagen kamen zwischen den zwei Bergen hervor, und die Berge waren Berge von Erz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Am ersten Streitwagen waren rote Rosse und am zweiten Streitwagen schwarze Rosse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'Und am dritten Streitwagen weiße Rosse und am vierten Streitwagen getüpfelte starke Rosse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Und ich hob an und sprach zu dem Engel, der mit mir redete: Was sollen diese, mein Herr?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Und der Engel antwortete und sprach zu mir: Dies sind die vier Winde der Himmel, die ausgehen, nachdem sie bei dem Herrn der ganzen Erde gestanden haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Der, an dem die Schwarzen Pferde sind, zieht aus in das Land der Mitternacht, und die weißen ziehen hinter ihnen aus, und die getüpfelten ziehen in das Land des Südens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'Und die starken zogen aus und suchten zu gehen, um die Erde zu durchwandeln. Und er sprach: Gehet hin, durchwandelt die Erde, und sie durchwandelten die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'Und er schrie mir zu und redete zu mir, sprechend: Siehe, die ausziehen in das Land der Mitternacht, die lassen Meinen Geist ruhen im Land der Mitternacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'Und es geschah an mich das Wort Jehovahs, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Man nehme von den Weggeführten, von Cheldai, von Tobjahn und von Jedajah; und du sollst hineingehen an jenem Tag, und du sollst hineingehen in das Haus Joschijahs, des Sohnes Zephanjahs, die von Babel kommen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'Und du sollst Silber und Gold nehmen und sollst Kronen machen; und sollst eine setzen auf das Haupt Jehoschuas, des Sohnes Jehozadaks, des Hohenpriesters,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'Und sprechen sollst du zu ihm, sprechend: So spricht Jehovah der Heerscharen, sprechend: Siehe, ein Mann, Zemach ist sein Name, und es wird sprossen unter ihm, und er wird Jehovahs Tempel bauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'Und er wird Jehovahs Tempel bauen und wird Majestät tragen, und sitzen und herrschen auf seinem Thron, und er wird Priester sein auf seinem Thron, und ein Rat des Friedens wird zwischen beiden sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'Und die Kronen sollen für Chelem und Tobijah und Jedajah und Chen, Zephanjahs Sohn, als Angedenken in Jehovahs Tempel sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'Und die von ferne werden kommen, und im Tempel Jehovahs bauen, und ihr sollt wissen, daß Jehovah der Heerscharen mich an euch gesendet hat. Und das wird geschehen, wenn ihr hört auf die Stimme Jehovahs, eures Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Und es geschah im vierten Jahr des Königs Darius, daß das Wort Jehovahs geschah an Sacharjah am vierten des neunten Monats Chislev;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Und Bethel sandte Scharezer und RegemMelech und seine Leute, das Angesicht Jehovahs anzuflehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'Und zu sprechen zu den Priestern in dem Haus Jehovahs der Heerscharen und zu den Propheten, sprechend: Soll ich im fünften Monat weinen, und mich enthalten, wie ich nun etliche Jahre her getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'Und es geschah das Wort Jehovahs der Heerscharen an mich, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Sprich zu dem ganzen Volk des Landes und zu den Priestern, sprechend: Wenn ihr gefastet und geklagt habt im fünften und im siebenten diese siebzig Jahre her, habt ihr denn wirklich für mich gefastet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Und wenn ihr aßet und wenn ihr tranket, wart nicht ihr es, die da aßen, und ihr, die da tranken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Sind das nicht die Worte, die Jehovah durch die Hand der früheren Propheten ausrufen ließ, da Jerusalem bewohnt und behaglich war, und seine Städte ringsumher, und man noch im Mittagland und in der Niederung wohnte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'Und es geschah Jehovahs Wort zu Sacharjah, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'So spricht Jehovah der Heerscharen, sprechend: Richtet ein Gericht der Wahrheit und tut Barmherzigkeit und Erbarmen, jeder Mann mit seinem Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'Und drückt nicht die Witwe und die Waise, den Fremdling und den Elenden, und denkt in eurem Herzen nicht Böses, der Mann wider seinen Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Sie aber weigerten sich, darauf zu merken, und kehrten abtrünnig die Schulter zu, und machten ihre Ohren schwer, daß sie nicht hörten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'Und ihr Herz machten sie zu einem Diamant, daß sie nicht hörten auf das Gesetz und auf die Worte, die Jehovah der Heerscharen in Seinem Geist sandte durch die Hand der früheren Propheten, und groß war die Entrüstung von Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'Und so geschah, wie Er rief, und sie hörten nicht, so sollen sie rufen und Ich werde nicht hören, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'Und Ich zerstürmte sie über alle Völkerschaften, die sie nicht kannten, und das Land war verwüstet hinter ihnen, daß niemand hindurchging, noch zurückkehrte, und sie setzten das Land der Begehr in Verwüstung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'Und es geschah das Wort Jehovahs der Heerscharen, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'So spricht Jehovah der Heerscharen: Mit großem Eifer habe Ich für Zijon geeifert, und geeifert mit großem Grimm für dasselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'So spricht Jehovah: Ich kehre zurück auf Zijon, und wohne inmitten Jerusalems. Und nennen wird man Jerusalem die Stadt der Wahrheit, und den Berg Jehovahs der Heerscharen den Berg der Heiligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'So spricht Jehovah der Heerscharen: Wohnen werden noch Greise und Greisinnen in den Straßen Jerusalems, und der Mann mit seiner Stütze in seiner Hand, vor der Menge der Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'Und die Straßen der Stadt sollen voll sein von Knaben und Mädchen, die auf ihren Straßen spielen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'So spricht Jehovah der Heerscharen: Ja, wunderbar wird es in den Augen des Überrestes dieses Volkes sein in jenen Tagen. Wird es auch wunderbar in Meinen Augen sein? spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'So spricht Jehovah der Heerscharen: Siehe, Ich rette Mein Volk aus dem Lande des Aufgangs und aus dem Lande des Untergangs der Sonne;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'Und Ich will sie hereinbringen, daß sie wohnen in Jerusalems Mitte, und sie Mein Volk seien und Ich ihr Gott in Wahrheit und in Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'So spricht Jehovah der Heerscharen: Stärket eure Hände, ihr, die in diesen Tagen hört diese Worte aus dem Munde der Propheten, die da sind an dem Tage, da man den Grund zum Hause Jehovahs der Heerscharen legte, den Tempel aufzubauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Denn vor selbigen Tagen war kein Lohn für den Menschen, und war kein Lohn für das Vieh; und der, so da ausging, und der einging, hatte keinen Frieden von dem Dränger, und Ich entsandte alle Menschen, den Mann wider seinen Genossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Nun aber bin Ich nicht wie in früheren Tagen gegen den Überrest von diesem Volke, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Sondern sie sollen des Friedens Same sein, der Weinstock wird seine Frucht geben, und die Erde wird geben ihr Gewächs, und die Himmel geben ihren Tau. Und Ich will alles dies dem Überrest dieses Volkes zum Erbe geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'Und wird geschehen, wie ihr ein Fluch unter den Völkerschaften wart, Haus Jehudah und Haus Israel, so will Ich euch retten, daß ihr ein Segen werdet. Fürchtet euch nicht, stärkt eure Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Denn so spricht Jehovah der Heerscharen: Gleichwie Ich sann, euch Übles anzutun, weil eure Väter Mich entrüstet, spricht Jehovah der Heerscharen, und Mich nicht reuete:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'So will Ich zurückkehren, will in diesen Tagen sinnen, Jerusalem und dem Haus Jehudah Gutes zu tun. - Fürchtet euch nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'Dies sind die Dinge, die ihr tun sollt: Redet Wahrheit, der Mann mit seinem Genossen; die Wahrheit und das Gericht des Friedens richtet in euren Toren!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'Denkt nicht in eurem Herzen Böses, der Mann wider seinen Genossen; und liebt nicht den Schwur der Lüge; denn solches alles hasse Ich, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'Und es geschah das Wort Jehovahs der Heerscharen zu mir, sprechend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'So spricht Jehovah der Heerscharen: Das Fasten des vierten und das Fasten des fünften und das Fasten des siebenten und das Fasten des zehnten wird dem Hause Jehudah zur Freude und zur Fröhlichkeit und zu guten Festzeiten werden. Und die Wahrheit und den Frieden sollt ihr lieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'So spricht Jehovah der Heerscharen: Es werden noch Völker kommen und Bewohner vieler Städte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'Und werden gehen die Bewohner der einen zu der anderen, sprechend: Laßt uns gehen, um anzuflehen das Angesicht Jehovahs und zu suchen Jehovah der Heerscharen. Auch ich will gehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'Und viele Völker und zahlreiche Völkerschaften werden kommen, Jehovah der Heerscharen zu suchen in Jerusalem, und anzuflehen das Angesicht Jehovahs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'So spricht Jehovah der Heerscharen: In jenen Tagen werden anfassen zehn Männer aus allen Zungen der Völkerschaften, und sie werden anfassen den Rockflügel eines jüdischen Mannes, sprechend: Wir wollen mit euch gehen; denn wir hören, daß Gott mit euch ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Weissagung. Das Wort Jehovahs über das Land Chadrach, und Damask, Seinen Ruheplatz; denn auf Jehovah ist das Auge des Menschen und aller Stämme Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'Und auch über Chamath, das daran grenzt, Zor und Zidon; denn es war sehr weise.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'Und Zor baute sich ein Bollwerk, und häufte Silber wie Staub auf und pures Gold wie den Kot der Gassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Siehe, arm wird es der Herr machen, und sein Vermögen stürzen in das Meer, und es selber soll vom Feuer gefressen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Aschkelon sieht es und fürchtet sich, und Gazah, und ist sehr erschüttert, und Ekron; denn er schämt sich seines Verlasses, und der König von Gazah vergeht, und Aschkelon wird nicht bewohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'Und der Bastard wird in Aschdod wohnen, und der Philister Stolz rotte Ich aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'Und Ich will wegnehmen sein Blut aus seinem Munde, und seine Scheusale zwischen seinen Zähnen heraus. Und auch er verbleibt unserem Gott, und wird sein wie ein Stammhaupt in Jehudah, und Ekron wie der Jebusiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Und Ich beziehe ein Heerlager für Mein Haus, wegen des Heeres, das vorüberzieht und zurückkehrt, daß kein Fronvogt mehr es durchziehe; denn jetzt habe Ich es angesehen mit Meinen Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Frohlocke sehr, Tochter Zijons, rufe laut, Tochter Jerusalems. Siehe, dein König kommt zu dir. Ein Gerechter und Geretteter ist Er, demütig, und reitet auf einem Esel, und auf einem Füllen, dem Sohn der Eselinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'Und Ich rotte aus den Streitwagen aus Ephraim und das Roß aus Jerusalem, und ausgerottet wird des Streites Bogen, und Er wird Frieden reden zu den Völkerschaften; und Seine Herrschaft wird sein von Meer zu Meer und von dem Flusse bis an das Äußerste der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Auch dir entsende Ich durch deines Bundes Blut die Gebundenen aus der Grube, worin kein Wasser ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Kehrt zurück zur Feste, ihr Gebundenen der Hoffnung, auch heute sage Ich an, Ich will dir doppelt zurückgeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Denn Jehudah habe Ich Mir gespannt, und Ephraim erfüllt mit dem Bogen, und deine Söhne, Zijon, auferweckt mit deinen Söhnen, Javan, und will dich setzen zu einem Schwert des Helden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'Und über ihnen wird erscheinen Jehovah, und wie der Blitz geht aus Sein Pfeil, und der Herr Jehovah stößt in die Posaune, und geht dahin in des Südens Wetter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Jehovah der Heerscharen schirmt über sie, und sie fressen auf, und sie zerstampfen die Steine der Schleuder, und sie trinken, sie toben wie vom Wein. Und voll sind sie wie das Sprengbecken, wie die Ecksäulen des Altars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'Und retten wird sie an jenem Tag Jehovah, ihr Gott, Sein Volk wie eine Herde; denn Steine des Diadems sind sie, die auf Seinem Boden emporragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Denn wie groß ist Seine Güte, und wie groß Seine Schöne. Korn läßt Jünglinge und Most Jungfrauen heranwachsen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Bittet von Jehovah Regen zur Zeit des Spätregens, Jehovah, Der Gewölke macht, so gibt Er ihnen Regen in Güssen, jedem Mann Kraut im Felde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Denn Unrecht reden die Theraphim und die Wahrsager schauen Lüge, und Eitles reden die Träume, nichtig trösten sie. Darum ziehen sie aus wie Schafe, sie werden gedrückt, weil kein Hirte da ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Über die Hirten ist Mein Zorn entbrannt, und an den Böcken suche Ich heim; denn Jehovah der Heerscharen sucht heim Seine Herde, das Haus Jehudahs, und macht sie zum Rosse Seiner Majestät im Streite.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Aus Ihm ist der Eckstein, aus Ihm der Pflock, aus Ihm der Bogen des Streites, aus Ihm geht hervor jeder Treiber zumal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'Und werden sein wie die Helden, zertretend in den Kot der Gassen im Streite, und sie werden streiten, denn Jehovah ist mit ihnen, und beschämt werden, die reiten auf Rossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'Und mächtig mache Ich das Haus Jehudah, und das Haus Josephs rette Ich, und laß sie wohnen. Denn ihrer erbarme Ich Mich. Und sie sollen sein, als hätte Ich sie nicht verworfen; denn Ich, Jehovah, bin ihr Gott, und antworte ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'Und wie ein Held soll sein Ephraim, und ihr Herz wird fröhlich wie vom Wein, und ihre Söhne werden es sehen und fröhlich sein; und in Jehovah wird ihr Herz frohlocken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Ich locke sie und bringe sie zusammen, denn Ich löse sie ein, daß sie sich mehren, wie sie sich gemehrt hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'Und Ich säe sie unter die Völker, und in den Fernen gedenken sie Meiner, und sie leben mit ihren Söhnen und kehren zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Und Ich bringe sie zurück aus dem Lande Ägypten, und bringe sie aus Aschur zusammen, und bringe sie hinein in das Land Gilead und zum Libanon, und wird nicht genug für sie gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'Und Er zieht durch das Meer der Drangsal, und schlägt im Meere die Wogen, und werden austrocknen all die Schlünde des Stromes; und hinabgebracht wird Aschurs Stolz, und das Zepter Ägyptens wird weggenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'Und mächtig mache Ich sie in Jehovah, daß sie in Seinem Namen wandeln, spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Öffne deine Türen, Libanon, daß Feuer deine Zedern auffresse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Heule, Tanne, daß die Zeder ist gefallen, daß die Stattlichen verheert sind. Heult, ihr Eichen Baschans, daß der Wald Bazar herabgestürzt ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Die Stimme des Geheuls der Hirten, daß verheert ist ihr Prunk! Die Stimme des Brüllens der jungen Löwen, denn der Stolz des Jordan ist verheert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'So spricht Jehovah, mein Gott: Weide die Herde, die erwürgt wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'Die ihre Besitzer erwürgen und es für keine Schuld halten, und die, so sie verkaufen, sprechen: Gesegnet sei Jehovah, daß ich reich werde; und ihre Hirten bemitleiden sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Nicht mehr werde Ich bemitleiden die Bewohner des Landes, spricht Jehovah, und siehe, Ich überantworte die Menschen, jeden Mann in die Hand seines Genossen, und in die Hand seines Königs, daß sie das Land zerstoßen, und Ich errette nicht aus ihrer Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'Und ich weidete die Herde, die erwürgt wird, deshalb die Elenden der Herde, und nahm mir zwei Stöcke, den einen nannte ich Noam und den anderen nannte ich Choblim, und Ich weidete die Herde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'Und ich schaffte die drei Hirten weg in einem Monat, und meine Seele ward ungeduldig ob ihnen, und auch ihre Seele ward meiner überdrüssig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Und ich sprach: Ich mag euch nicht weiden. Wer sterben will, der sterbe, wer weggeschafft werden soll, der werde weggeschafft, und von dem Überrest esse das eine das Fleisch des anderen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'Und ich nahm meinen Stock Noam und zerhieb ihn, um zunichte zu machen meinen Bund, den ich mit allen Völkern schloß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'Und er ward zunichte an jenem Tag, und so erkannten die Elenden der Herde, die auf mich hielten, daß es das Wort Jehovahs war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'Und ich sprach zu ihnen: Wenn es gut ist in euren Augen, gebt mir meinen Lohn, wo nicht, so unterlasset es. Und sie wogen mir meinen Lohn, dreißig Silberlinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Und Jehovah sprach zu mir: Wirf dem Töpfer hin den vortrefflichen Wert, zu dem Ich von ihnen geschätzt ward. Und ich nahm die dreißig Silberlinge, und warf sie in Jehovahs Haus dem Töpfer hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Und ich zerhieb meinen zweiten Stock Choblim, um zunichte zu machen die Brüderschaft zwischen Jehudah und Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Und Jehovah sprach zu mir: Nimm dir noch das Gerät eines närrischen Hirten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Denn siehe, Ich lasse aufstehen einen Hirten in dem Land, der das Verschollene nicht heimsucht, das Junge nicht sucht, und das Zerbrochene nicht heilt, das Stehende nicht versorgt, das Fleisch des Gemästeten aber aufißt und seine Klauen abreißt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Wehe dem nichtsnutzigen Hirten, der die Herde verläßt; das Schwert über seinen Arm, und über sein rechtes Auge! Sein Arm verdorre und sein rechtes Auge werde trübe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Weissagung. Das Wort Jehovahs über Israel. Es spricht Jehovah, Der die Himmel ausspannt und die Erde gründet, und den Geist des Menschen in seinem Inneren bildet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Siehe, Ich mache Jerusalem zum Taumelbecken für alle Völker ringsumher, und auch für Jehudah wird sie es sein bei der Belagerung wider Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'Und es geschieht am selben Tag, daß Ich Jerusalem zum Laststein mache allen Völkern; alle, die daran aufladen, werden sich daran zerschneiden, und alle Völkerschaften der Erde werden sich versammeln wider dasselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'An selbigem Tage, spricht Jehovah, schlage Ich mit Stumpfsinn jeglich Roß, und mit Wahnsinn den, der darauf reitet, und über das Haus Jehudah tue Ich Meine Augen auf, und jeglich Roß der Völker werde Ich mit Blindheit schlagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'Und Jehudahs Stammhäupter werden in ihrem Herzen sprechen: Mächtig mache ich mir Jerusalems Bewohner durch Jehovah der Heerscharen, ihren Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'An jenem Tage werde Ich die Stammhäupter Jehudahs machen wie ein Feuerbecken unter Holzstücken und wie eine Feuerfackel in der Garbe, daß sie zur Rechten und zur Linken alle Völker ringsumher auffressen, und wohnen wird noch Jerusalem an seine Stelle in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'Und Jehudahs Zelte wird Jehovah zuerst retten, daß nicht der Ruhm des Hauses David und der Ruhm von Jerusalems Bewohnern groß tue wider Jehudah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'An jenem Tage wird Jehovah schirmen den Bewohner Jerusalems, daß, wer da strauchelt unter ihnen, wird sein an jenem Tage wie David, und das Haus Davids wird sein wie Gott, wie Jehovahs Engel vor ihrem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'Und an selbigem Tage wird geschehen, daß Ich suche alle Völkerschaften zu vernichten, die wider Jerusalem kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'Und Ich gieße aus über Davids Haus und über den Bewohner Jerusalems den Geist der Gnade und des Flehens, und sie werden zu Mir aufblicken, Den sie durchstochen haben, und klagen um Ihn, wie man klagt um den Einzigen, und bitterlich weinen um Ihn, wie man bitterlich weint um den Erstgeborenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'An jenem Tag wird die Klage groß sein in Jerusalem, wie die Klage bei Hadadrimmon in der Talebene Megiddo.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'Und klagen wird das Land, Familien um Familien besonders, die Familie des Hauses David besonders und ihre Weiber besonders, die Familie des Hauses Nathan besonders und ihre Weiber besonders;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'Die Familie des Hauses Levi besonders und ihre Weiber besonders; die Familie Schimei besonders und ihre Weiber besonders.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'Alle Familien, die verblieben sind, Familien um Familien besonders und ihre Weiber besonders.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'An jenem Tage wird dem Hause Davids und Jerusalems Bewohner ein Born geöffnet werden wider die Sünde und wider die Beflekkung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'Und es geschieht an jenem Tag, spricht Jehovah der Heerscharen, daß Ich die Namen der Götzenbilder aus dem Land ausrotten werde, daß man ihrer nicht mehr gedenkt; und auch die Propheten und den unreinen Geist will Ich dahingehen lassen aus dem Lande;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'Und wird geschehen, daß, so ein Mann noch weissagt, sein Vater und seine Mutter, die ihn gezeugt, zu ihm sprechen: Du sollst nicht leben; denn Lüge redest du im Namen Jehovahs; und werden ihn durchstechen, sein Vater und seine Mutter, die ihn gezeugt, ob seinem Weissagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'Und wird an jenem Tag geschehen, daß die Propheten sich schämen, ein jeder Mann ob seinem Gesicht, wenn er weissagt, und nicht mehr den härenen Mantel anziehen, um zu täuschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'Und er wird sagen: Ich bin kein Prophet, ich bin ein Mann, der den Boden baut, denn mich hatte ein Mensch verkauft in meiner Jugend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'Und sagt man zu ihm: Was sind das für Schläge zwischen deinen Händen?, so wird er sagen: Die schlug man mir im Hause derer, die mich lieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Auf, Schwert, wache auf wider Meinen Hirten und wider den Mann Meiner Gemeinschaft! spricht Jehovah der Heerscharen; schlage den Hirten, daß die Herde sich zerstreue, so will Ich Meine Hand zu den Geringen zurückwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'Und soll im ganzen Land geschehen, spricht Jehovah, daß je zwei Teile darin ausgerottet werden, daß sie verscheiden, und das Drittel darin übrigbleibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'Und das Drittel will Ich ins Feuer hineinbringen und will sie läutern, wie man Silber läutert, und will sie prüfen, wie man prüft das Gold. Es ruft Meinen Namen an, und Ich antworte ihm, Ich spreche: Mein Volk ist es; und es spricht: Jehovah, mein Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Siehe, ein Tag kommt dem Jehovah, da man die Beute teilt in deiner Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'Und Ich versammle alle Völkerschaften nach Jerusalem zum Streit, und die Stadt wird erobert und die Häuser werden geplündert und die Weiber geschändet, und die Hälfte der Stadt zieht in die Verbannung hinaus, aber das übrige des Volkes wird nicht ausgerottet aus der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'Und wider diese Völkerschaften wird ausziehen Jehovah und streiten, wie am Tage, da Er stritt am Tage des Kampfes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'Und Seine Füße werden an jenem Tag auf dem Berg der Ölbäume stehen, der vor Jerusalem gen Osten ist. Und der Berg der Ölbäume wird sich spalten in seine Hälfte gen Aufgang und zum Meere hin in eine sehr große Schlucht, und eine Hälfte des Berges weicht hin gen Mitternacht, und seine Hälfte gen Mittag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'Und ihr werdet fliehen durch die Schlucht Meiner Berge; denn die Schlucht der Berge wird reichen bis Azal; und ihr flieht, wie ihr geflohen seid vor dem Erdbeben in den Tage Ussijahs, des Königs von Jehudah, und es kommt Jehovah, mein Gott; all Seine Heiligen mit Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'Und es geschieht an jenem Tage: kein Licht wird sein, nur Kälte und Frost.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'Und es wird ein Tag sein, - dem Jehovah ist er bekannt - nicht Tag und nicht Nacht, und zur Zeit des Abends wird Licht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'Und es geschieht an jenem Tag, daß lebendige Wasser ausgehen von Jerusalem, zur Hälfte nach dem vorderen Meere und zur Hälfte nach dem hinteren Meer. Im Sommer und im Winter wird es sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'Und König wird Jehovah sein über die ganze Erde. An jenem Tage wird Jehovah einer sein, und Sein Name einer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'Das ganze Land wird ringsum sein wie das Gefilde von Geba bis nach Rimmon, mittäglich von Jerusalem, und es wird erhöht sein und bewohnt sein an seiner Stelle, vom Tore Benjamins bis zum Orte des ersten Tores bis zum Tore der Ecken und dem Turm Chananeels bis zu den Kelterkufen des Königs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'Und sie werden darin wohnen, und kein Bann wird mehr sein, und man wohnt in Jerusalem in Sicherheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'Dies aber wird die Plage sein, womit Jehovah plagt alle Völker, die wider Jerusalem ausrücken: sein Fleisch schwindet dahin, da er noch auf seinen Füßen steht, und seine Augen schwinden dahin in ihren Höhlen, und seine Zunge schwindet dahin in ihrem Munde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'Und an jenem Tage wird geschehen, daß viel Toben von Jehovah unter ihnen sein wird: und der Mann wird die Hand seines Genossen erfassen, und seine Hand steigt auf über die Hand seines Genossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Und auch Jehudah wird wider Jerusalem streiten; und gesammelt wird das Vermögen aller Völkerschaften ringsumher, sehr viel Gold und Silber und Kleider.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'Und ebenso wird sein die Plage des Rosses, des Maultiers, des Kamels und des Esels, und alles Viehs, das in jenen Heerlagern ist, wie diese Plage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'Und wird geschehen, daß alle von allen Völkerschaften, die übrigblieben, die wider Jerusalem gekommen waren, heraufziehen werden von Jahr zu Jahr, um anzubeten den König Jehovah der Heerscharen, und das Fest der Laubhütten zu feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Und es soll geschehen, wer von den Familien der Erde nicht heraufzieht nach Jerusalem, um den König Jehovah der Heerscharen anzubeten, auf ihnen wird kein Regen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'Und wenn die Familie Ägypten nicht heraufzieht, und nicht kommt, und nicht mit ihnen ist, so wird sein die Plage, womit Jehovah die Völkerschaften schlägt, die nicht heraufzogen, das Fest der Laubhütten zu feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'Das wird die Sünde Ägyptens sein, und die Sünde all der Völkerschaften, die nicht heraufzogen, das Fest der Laubhütten zu feiern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'An jenem Tage wird sein auf den Glöckchen der Rosse: Heiligkeit dem Jehovah! Und die Töpfe werden sein im Haus Jehovahs wie die Sprengbecken vor dem Altar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'Und jeder Topf in Jerusalem und in Jehudah wird Heiligkeit sein dem Jehovah der Heerscharen; und alle, die opfern, werden kommen und davon nehmen und darin kochen, und wird kein Kanaaniter mehr im Hause Jehovahs der Heerscharen sein an jenem Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Weissagung. Wort Jehovahs an Israel durch die Hand Maleachis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Ich habe euch geliebt, spricht Jehovah; und ihr sprecht: Worin hast Du uns geliebt? Ist Esau nicht Jakobs Bruder? spricht Jehovah. Und Jakob liebte Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Und Esau haßte Ich und machte seine Berge zur Verwüstung und sein Erbe den Drachen der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'So Edom spricht: Wir sind zerschlagen, aber wir kehren zurück und bauen die Verödungen, spricht Jehovah der Heerscharen also: Sie bauen, und Ich reiße ein, und man wird sie die Grenze der Ungerechtigkeit nennen und das Volk, gegen das Jehovah ergrimmt ist ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'Und eure Augen sollen es sehen, und ihr sollt sprechen: Groß ist Jehovah, über die Grenze Israels hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Ein Sohn ehrt den Vater und seinen Herrn der Knecht. Bin Ich aber Vater, wo ist Meine Herrlichkeit? Und bin Ich Herr, wo ist die Furcht vor Mir, spricht Jehovah der Heerscharen zu euch, ihr Priester, die ihr verachtet Meinen Namen. Und ihr sprecht: Worin verachten wir Deinen Namen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Ihr bringt beflecktes Brot herzu auf Meinen Altar und sprecht: Womit beflecken wir Dich? Damit, daß ihr sagt: Der Tisch Jehovahs, er ist verächtlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'Und wenn ihr herzubringt Blindes zum Opfer, ist das nicht böse? Und wenn ihr herzubringt Lahmes und Krankes, ist das nicht böse? Bringe es doch deinem Statthalter dar, ob er wohl Gefallen an dir hat? Ob er dein Angesicht erhebt? spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'Und nun, fleht doch zu Gottes Angesicht, daß Er uns gnädig sei. Von eurer Hand ist solches geschehen, erhebt Er wohl euer Angesicht? spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Wäre doch einer unter euch, der die Torflügel gar zuschlösse, daß ihr nicht umsonst Meinen Altar anzündet. Ich habe an euch keine Lust, spricht Jehovah der Heerscharen, und ein Speiseopfer aus eurer Hand ist Mir nicht wohlgefällig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Denn vom Aufgang der Sonne und bis zu ihrem Niedergang ist groß Mein Name unter den Völkerschaften, und an jedem Ort wird Meinem Namen Räucherwerk dargebracht und reines Speiseopfer; denn groß ist Mein Name unter den Völkerschaften, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'Ihr aber entweiht ihn, wenn ihr sprecht: Der Tisch Jehovahs, der ist befleckt, und sein Gewächs, seine Speise ist verächtlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'Und ihr sprecht: Siehe, welche Mühsal, und achtet es gering, spricht Jehovah der Heerscharen, und ihr habt Entrissenes und Lahmes und Krankes hereingebracht, und es als Speiseopfer hereingebracht. Und Ich soll Wohlgefallen daran haben aus eurer Hand? spricht Jehovah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Darum verflucht sei, wer da trüglich handelt und in seiner Herde hat ein Männliches, und dem Herrn gelobt und opfert ein Verdorbenes; denn ein großer König bin Ich, spricht Jehovah der Heerscharen, und Mein Name ist furchtbar unter den Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'Und nun an euch, ihr Priester, ist dies Gebot:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Wenn ihr nicht hört und nicht zu Herzen nehmt, daß ihr Meinem Namen Herrlichkeit gebt, spricht Jehovah der Heerscharen, so sende Ich wider euch die Verwünschung, und verfluche eure Segnungen, und Ich habe sie auch verflucht, weil ihr es nicht zu Herzen nehmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Seht, Ich bedrohe wider euch den Samen und sprenge Unrat über eure Angesichter, denn Unrat eurer Feste, und man wird euch zu denselben wegnehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'Und ihr werdet erkennen, daß Ich solches Gebot an euch gesandt, auf daß Mein Bund mit Levi sein sollte, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Mein Bund war mit ihm, der des Lebens und des Friedens, und Ich gab sie ihm zur Furcht, und er fürchtete Mich und war zerknirscht vor Meinem Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Das Gesetz der Wahrheit war in seinem Munde, und Verkehrtheit ward nicht gefunden auf seinen Lippen; in Frieden und Geradheit wandelte er mit Mir, und brachte viele von der Missetat zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Denn die Lippen des Priesters sollen der Erkenntnis hüten, und das Gesetz sollen sie von seinem Munde suchen; denn ein Bote Jehovahs der Heerscharen ist er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'Ihr aber seid vom Weg abgewichen, habt viele im Gesetz straucheln lassen, ihr habt den Bund des Levi verdorben, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Und auch Ich habe euch verächtlich und niedrig gemacht allem Volk, gleichwie ihr Meine Wege nicht haltet und die Person anseht im Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Haben wir alle nicht einen Vater? Hat nicht ein Gott uns geschaffen? Warum handeln wir treulos, der Mann an seinem Bruder, und entweihen unserer Väter Bund?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Treulos geworden ist Jehudah, Greuliches geschah in Israel und in Jerusalem, denn Jehudah hat entweiht die Heiligkeit Jehovahs; denn er liebte und vermählte sich mit der Tochter eines ausländischen Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Ausrotten wird Jehovah den Mann, der das tut, der wacht und antwortet aus Jakobs Zelten, und der dem Jehovah der Heerscharen Speiseopfer herzubringt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'Und dies tut ihr zum zweiten: ihr bedeckt mit Tränen den Altar Jehovahs, mit Weinen und Jammer, daß Er nicht mehr zu dem Speiseopfer Sich wendet und Wohlgefälliges annimmt aus eurer Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Und ihr sprecht: Warum? Darum, daß Jehovah Zeuge ist zwischen dir und dem Weibe deiner Jugend, der du treulos bist geworden, und doch ist sie deine Gefährtin und deines Bundes Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Und das tat nicht einer, und der Überrest, in dem der Geist war. Und was dann der eine, der Gottes Samen suchte? Darum hütet euch in eurem Geist, daß keiner dem Weibe seiner Jugend treulos wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Denn Er haßt das Entlassen, spricht Jehovah, der Gott Israels, und Gewalttat bedeckt seinen Anzug, spricht Jehovah der Heerscharen; darum hütet euch in eurem Geist, daß ihr nicht treulos handelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Ihr habt durch eure Worte ermüdet den Jehovah und ihr sprecht: Womit ermüdeten wir Ihn? Damit, daß ihr sagt: Jeder, der Böses tut, ist in Jehovahs Augen gut, und Er hat an ihnen Lust; oder: Wo ist der Gott des Gerichts?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Siehe, Ich sende Meinen Boten, und er räumt den Weg vor Meinem Angesicht, und plötzlich wird kommen in Seinen Tempel der Herr, Den ihr sucht, und der Bote des Bundes, an Dem ihr Lust habt; siehe, Er kommt, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Und wer hält aus den Tag Seines Kommens, und wer besteht bei Seinem Erscheinen? Denn wie des Goldschmieds Feuer ist Er, wie der Walker Lauge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'Und sitzen wird Er, schmelzend und reinigend das Silber, und wird reinigen die Söhne Levis und abtreiben sie wie Gold und wie Silber, und sie werden dem Jehovah herbeibringen Speiseopfer in Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Und angenehm wird dann Jehovah sein das Speiseopfer Jehudahs und Jerusalems, wie in der Urzeit Tagen und in der Vorzeit Jahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'Und nahen werde Ich euch zum Gericht, und Ich werde eilig Zeuge sein wider die Zauberer und die Ehebrecher und die zur Lüge schwören und erpressen den Lohn des Lohnarbeiters, die Witwe und die Waise und den Fremdling beugen und Mich nicht fürchten, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Denn Ich, Jehovah, ändere Mich nicht; darum seid ihr, Söhne Jakobs, nicht alle worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Seit eurer Väter Tagen seid ihr von Meinen Satzungen abgewichen und habt sie nicht gehalten. Kehrt zurück zu Mir, so will Ich wieder zu euch zurückkehren, spricht Jehovah der Heerscharen. Ihr aber sprecht: Worin sollen wir zurückkehren?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Berückt wohl ein Mensch Gott? daß ihr wollt Mich berücken und ihr sprecht: Worin berückten wir Dich? im Zehnten und im Hebeopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'Mit Verwünschung seid ihr verflucht, und ihr wollt Mich berücken, die ganze Völkerschaft?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Bringt herein alle den Zehnten in das Schatzhaus, auf daß Ausbeute sei in Meinem Hause, und prüft Mich doch damit, spricht Jehovah der Heerscharen, ob Ich euch nicht des Himmels Fenster öffne, und Segen für euch ausleere bis zum Überfluß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'Und Ich bedrohe für euch den Fresser, daß er des Bodens Frucht euch nicht verderbe, und euch nicht fehltrage der Weinstock auf dem Felde, spricht Jehovah der Heerscharen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'Und alle Völkerschaften werden euch selig preisen, denn ein Land der Lust sollt ihr sein, spricht Jehovah der Heerscharen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Stark waren wider Mich eure Worte, spricht Jehovah, und ihr sprecht: Was haben wir wider Dich geredet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Ihr sprachet: Eitel ist es, zu dienen Gott, und welcher Gewinn ist, daß wir Seine Verordnung halten und wir Leid tragend einhergehen vor dem Angesicht Jehovahs der Heerscharen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Und nun preisen wir selig die Vermessenen. Sie wurden auch aufgebaut, die Ungerechtigkeit taten; auch versuchten sie Gott und entrannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Dann aber redeten miteinander die, so Jehovah fürchteten, ein Mann mit seinem Genossen, und Jehovah merkte auf und hörte, und es ward vor Seinem Angesicht geschrieben ein Gedenkbuch über die, so den Jehovah fürchten und an Seinen Namen denken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'Und sie sollen Mir, spricht Jehovah der Heerscharen, für den Tag, den Ich mache, ein Eigentum sein, und Ich will sie bemitleiden, wie ein Mann bemitleidet seinen Sohn, der ihm dient.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Und ihr werdet zurückkehren und sehen, wie es ist zwischen dem Gerechten und dem Ungerechten, zwischen dem, der Gott dient und dem, der Ihm nicht dient. Denn siehe, es kommt der Tag, der wie der Ofen brennt; und alle Vermessenen und die, so Ungerechtigkeit taten, sind Stoppel, und der Tag, der kommt, entflammt sie, spricht Jehovah der Heerscharen, und weder Wurzel, noch Ast wird er denselben hinterlassen. Euch aber, die ihr Meinen Namen fürchtet, wird aufgehen die Sonne der Gerechtigkeit, und Heilung unter ihren Flügeln, und ihr geht aus und wachset heran wie die Mastkälber. Und die Gottlosen werdet ihr daniedertreten; denn Asche sollen sie unter den Sohlen eurer Füße sein an dem Tage, den Ich mache, spricht Jehovah der Heerscharen. Gedenkt an das Gesetz des Moses, Meines Knechtes, das Ich ihm gebot auf Choreb an ganz Israel, an die Satzungen und Rechte. Siehe, Ich sende euch Elijah, den Propheten, bevor da kommt der Tag Jehovahs, der große und furchtbare. Und er wird das Herz der Väter zu den Söhnen zurückwenden, und das Herz der Söhne zu ihren Vätern, auf daß Ich nicht komme und schlage mit dem Banne das Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Das Buch von der Geburt Jesu Christi, des Sohnes Davids, des Sohnes Abrahams.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham zeugte Isaak. Isaak aber zeugte Jakob. Jakob aber zeugte Judas und seine Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Judas aber zeugte Phares und Zara von der Thamar. Phares aber zeugte Esrom. Esrom aber zeugte Aram.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aram aber zeugte Aminadab. Aminadab aber zeugte Naasson, Naasson aber zeugte Salmon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmon aber zeugte Boas von der Rachab. Boas aber zeugte Obed von der Ruth, Obed aber zeugte den Jesse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'Jesse aber zeugte den König David. Aber der König David zeugte Salomoh von dem Weibe des Uriah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomoh aber zeugte Roboam. Roboam aber zeugte Abia. Abia aber zeugte Asa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Asa aber zeugte Josaphat. Josaphat aber zeugte Joram. Joram aber zeugte Osiah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Osiah aber zeugte Joatham. Joatham aber zeugte Achas. Achas aber zeugte Ezechias.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezechias aber zeugte Manasseh. Manasseh aber zeugte Amon. Amon aber zeugte Josias.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'Josias aber zeugte Jechonjas und seine Brüder zur Zeit der Umsiedelung nach Babylon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Nach der Umsiedelung nach Babylon aber zeugte Jechonjas den Salathiel, Salathiel aber zeugte Zorobabel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobabel aber zeugte Abiud. Abiud aber zeugte Eliakim. Eliakim aber zeugte Azor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Azor aber zeugte Zadok. Zadok aber zeugte Achim. Achim aber zeugte Eliud.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliud aber zeugte Eleasar. Eleasar aber zeugte Matthan. Matthan aber zeugte Jakob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'Jakob aber zeugte Joseph, den Mann der Maria, von welcher Jesus, Der da heißt Christus, geboren ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Alle die Geschlechter nun von Abraham bis David sind vierzehn Geschlechter; und von David bis zur Umsiedelung nach Babylon vierzehn Geschlechter; und von der Umsiedelung nach Babylon bis auf Christus sind es vierzehn Geschlechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Die Geburt Jesu Christi aber war also. Als nämlich Maria, Seine Mutter, dem Joseph verlobt war, fand sich, ehe sie zusammen kamen, daß sie vom Heiligen Geist empfangen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Joseph aber, ihr Mann, da er gerecht war, und sie nicht beschimpfen wollte, war willens, sie insgeheim zu entlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'Während er aber also gedachte, siehe, da erschien ihm der Engel des Herrn im Traum und sprach: Joseph, Sohn Davids, fürchte dich nicht, Maria, dein Weib zu dir zu nehmen; denn das in ihr Gezeugte ist von dem Heiligen Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Sie aber wird einen Sohn gebären, und Seinen Namen sollst du Jesus heißen; denn Er wird Sein Volk von seinen Sünden retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Dies alles ist aber geschehen, auf daß erfüllt würde, was vom Herrn durch den Propheten gesprochen worden, welcher sagt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, 'Siehe, die Jungfrau wird empfangen und einen Sohn gebären; und sie sollen Seinen Namen heißen Emmanuel, welches ist verdolmetscht: Gott mit uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Vom Schlafe erwacht aber tat Joseph, wie ihm der Engel des Herrn verordnet hatte, und nahm sein Weib zu sich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'Und er erkannte sie nicht bis sie ihren erstgeborenen Sohn geboren hatte, und hieß Seinen Namen Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Als aber Jesus zu Bethlehem in Judäa geboren ward in den Tagen des Königs Herodes, siehe, da kamen Weise aus dem Morgenland nach Jerusalem, und sagten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'Wo ist der zum König der Juden Geborene? Denn wir haben seinen Stern gesehen im Morgenlande und sind gekommen, ihn anzubeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Da aber der König Herodes das hörte, erbebte er und ganz Jerusalem mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'Und er versammelte alle Hohepriester und Schriftgelehrte des Volkes und erfragte von ihnen, wo der Christus sollte geboren werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Sie aber sagten ihm: Zu Bethlehem in Judäa; denn also ist geschrieben durch den Propheten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, 'Und du, Bethlehem, im Lande Juda, bist mitnichten die kleinste unter den Fürsten Judas; denn aus dir wird ausgehen der Fürst, der Mein Volk Israel weiden wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Da ließ Herodes die Weisen insgeheim rufen und erkundete von ihnen genau die Zeit, da der Stern erschien;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'Und schickte sie nach Bethlehem und sprach: Ziehet hin und erforschet genau wegen dem Kindlein, wenn ihr es aber gefunden habt, so saget es mir an, daß auch ich komme und es anbete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Als sie aber den König gehört hatten, zogen sie hin; und siehe, der Stern, den sie im Morgenland gesehen, ging vor ihnen her, bis er kam und stand oben über der Stelle, da das Kindlein war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Da sie aber den Stern sahen, freuten sie sich mit sehr großer Freude.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'Und sie gingen in das Haus und fanden das Kindlein mit Seiner Mutter Maria, und fielen nieder und beteten Es an und taten ihre Schätze auf und brachten Ihm Gaben dar, Gold und Weihrauch und Myrrhen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'Und da sie im Traume angewiesen wurden, sich nicht wieder zu Herodes zu wenden, zogen sie auf einem anderen Wege in ihr Land zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Nachdem sie aber fortgezogen waren, siehe, da erscheint der Engel des Herrn dem Joseph im Traum und sagt: Mache dich auf, nimm das Kindlein und Seine Mutter zu dir und fliehe nach Ägypten und sei dort, bis Ich es dir sage: denn Herodes wird nach dem Kindlein suchen, um Es umzubringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'Er aber machte sich auf, nahm das Kindlein und Seine Mutter zu sich bei Nacht und entwich nach Ägypten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'Und er war da bis zum Tode des Herodes, auf daß erfüllt würde, was vom Herrn gesprochen wurde durch den Propheten, der da sagt: Aus Ägypten habe Ich Meinen Sohn gerufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Da Herodes sah, daß er von den Weisen verspottet war, ward er gar sehr ergrimmt, sandte aus und ließ in Bethlehem und an allen seinen Grenzen alle Kinder von zwei Jahren und darunter umbringen, nach der Zeit, die er von den Weisen genau erkundet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Da ward erfüllt, das da gesagt ist durch den Propheten Jeremias, welcher sagt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, 'In Rama ward eine Stimme gehört: Viel Klagen und Weinen und Jammern: Rachel weinte um ihre Kinder und wollte sich nicht trösten lassen, denn sie sind nicht mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Als aber Herodes gestorben war, siehe, da erscheint der Engel des Herrn dem Joseph im Traum in Ägypten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Und spricht: Mache dich auf, nimm das Kindlein und Seine Mutter zu dir und ziehe hin in das Land Israel, denn sie sind gestorben, die dem Kinde nach dem Leben trachteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'Er aber machte sich auf, nahm das Kindlein und Seine Mutter zu sich und ging in das Land Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Wie er aber hörte, daß Archelaus anstatt seines Vaters Herodes König über Judäa sei, fürchtete er sich, dahin zu gehen; aber da er im Traum angewiesen ward, zog er in die Gegend von Galiläa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'Und er kam dahin und wohnte in der Stadt genannt Nazareth, auf daß erfüllt würde, was durch die Propheten gesagt worden ist: Er soll ein Nazarener heißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'In jenen Tagen aber trat Johannes der Täufer auf und predigte in der Wüste Judäas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'Und sprach: Tut Buße, denn das Reich der Himmel hat sich genaht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'Denn er ist es, von dem der Prophet Jesajas gesagt hat und gesprochen: Die Stimme eines, der schreit in der Wüste: Bereitet den Weg des Herrn und machet Seine Steige gerade.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'Er aber, Johannes, hatte eine Kleidung von Kamelhaaren und einen ledernen Gürtel um seine Lenden; seine Nahrung aber war Heuschrecken und wilder Honig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Da zog denn Jerusalem und ganz Judäa und die ganze Umgegend des Jordan zu ihm hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'Und wurden von ihm im Jordan getauft, und bekannten ihre Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Da er aber viele der Pharisäer und Sadduzäer zu seiner Taufe kommen sah, sprach er zu ihnen: Ihr Otterngezüchte, wer hat euch denn gewiesen, vor dem zukünftigen Zorne zu fliehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'So tut den Früchte würdig der Buße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'Und meinet nicht, ihr dürfet in euch sagen: Wir haben Abraham zum Vater; denn ich sage euch: Gott kann Abraham aus diesen Steinen da Kinder erwecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Es liegt aber auch schon die Axt an der Wurzel der Bäume. Jeglicher Baum nun, der nicht gute Frucht trägt, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Ich taufe euch zwar im Wasser zur Buße; Der aber nach mir kommt, ist stärker, denn ich, Dem ich nicht genugsam bin, die Schuhe zu tragen, Der wird euch mit dem Heiligen Geist und mit Feuer taufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'Er hat die Wurfschaufel in Seiner Hand und wird Seine Tenne durch und durch reinigen und Seinen Weizen in die Scheune sammeln, die Spreu aber in unauslöschlichem Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Alsdann kommt Jesus aus Galiläa herbei an den Jordan zu Johannes, um Sich von ihm taufen zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Johannes aber wehrte Ihm und sprach: Ich bedarf, daß ich von Dir getauft werde, und Du kommst zu mir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jesus aber antwortete und sprach zu ihm: Laß es jetzt zu, denn so gebührt es uns, alle Gerechtigkeit zu erfüllen. Da ließ er es Ihm zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'Und da Jesus getauft war, stieg Er alsbald herauf aus dem Wasser, und siehe, die Himmel taten sich Ihm auf, und Er sah den Geist Gottes wie eine Taube herabsteigen und auf Ihn kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'Und siehe, eine Stimme sprach aus den Himmeln: Dies ist Mein geliebter Sohn, an Dem Ich Wohlgefallen habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Da ward Jesus vom Geist in die Wüste hinaufgeführt, auf daß Er vom Teufel versucht würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'Und da Er vierzig Tage und vierzig Nächte gefastet hatte, hungerte Ihn danach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Und der Versucher kam herzu und sprach zu Ihm: Wenn Du Gottes Sohn bist, so sprich, daß diese Steine sollen Brot werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'Er aber antwortete und sprach: Es ist geschrieben: Der Mensch soll nicht allein vom Brote leben, sondern von jeglichem Wort, das durch den Mund Gottes ausgeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Da nimmt Ihn der Teufel mit sich in die heilige Stadt und stellt Ihn auf die Zinne des Tempels,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'Und spricht zu Ihm: Wenn Du Gottes Sohn bist, so wirf Dich hinab; denn es ist geschrieben, daß Er Seinen Engeln gebieten wird ob Dir, und sie sollen Dich auf den Händen tragen, auf daß Du Deinen Fuß nicht an einen Stein stoßest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Sprach zu ihm Jesus: Wiederum ist geschrieben: du sollst den Herrn, deinen Gott, nicht versuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Wiederum nimmt Ihn der Teufel mit sich auf einen ungemein hohen Berg und zeigt Ihm alle Reiche der Welt und ihre Herrlichkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'Und spricht zu Ihm: Dies alles will ich Dir geben, wenn Du niederfällst und mich anbetest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Da spricht zu ihm Jesus: Geh\' hinweg hinter Mich, Satan, denn es ist geschrieben: Du sollst den Herrn, deinen Gott, anbeten und Ihm allein dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Da verläßt Ihn der Teufel, und siehe, Engel kamen herzu und bedienten Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Als Er aber hörte, daß Johannes überantwortet ward, zog Er hin nach Galiläa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'Und Er verließ Nazareth, kam und wohnte in Kapernaum, das am Meere ist, in den Grenzen Sebulons und Nephthalims.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'Auf daß erfüllt würde, was gesagt wird durch den Propheten Jesajas, der da spricht:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, 'Das Land Sebulon und das Land Nephthalim am Wege des Meeres jenseits des Jordan und Galiläa der Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'Das Volk, das im Finstern saß, hat ein großes Licht gesehen, und denen, die in der Landschaft und dem Schatten des Todes saßen, ist ein Licht aufgegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Von da an fing Jesus an zu predigen und zu sprechen: Tut Buße, denn das Reich der Himmel hat sich genaht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Wie Jesus aber an dem Meere Galiläas wandelte, sah er zwei Brüder, Simon, genannt Petrus, und seinen Bruder Andreas, wie sie ein Fischnetz in das Meer warfen; denn sie waren Fischer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'Und Er spricht zu ihnen: Kommet her, Mir nach, und Ich will euch zu Menschenfischern machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Sie aber verließen alsbald die Netze und folgten Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'Und Er ging von dannen weiter und sah zwei andere Brüder, Jakobus, den des Zebedäus, und Johannes, seinen Bruder, in dem Fahrzeug mit Zebedäus, ihrem Vater, wie sie ihre Netze zurichteten, und Er rief sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Sie aber verließen alsbald das Fahrzeug und ihren Vater und folgten Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'Und Jesus zog umher in ganz Galiläa, lehrte in ihren Synagogen und predigte das Evangelium von dem Reiche und heilte alle Krankheit und alles Siechtum im Volke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'Und Sein Gerücht ging hin in ganz Syrien, und sie brachten Ihm alle Leidende, die mit mancherlei Krankheiten und Qualen behaftet waren, und Besessene und Mondsüchtige und Gichtbrüchige, und Er heilte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'Und es folge Ihm nach viel Volks von Galiläa und den zehn Städten, und von Jerusalem und von Judäa, und von jenseits des Jordan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Als Er aber das Gedränge sah, stieg Er auf den Berg, und als Er Sich niedersetzte, kamen Seine Jünger herzu zu Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'Und Er tat Seinen Mund auf, lehrte sie und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Selig sind, die im Geiste arm sind, denn das Reich der Himmel ist ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Selig sind, die da Leid tragen, denn sie sollen getröstet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Selig sind die Sanftmütigen, denn sie werden das Land ererben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Selig sind, die da hungert und dürstet nach Gerechtigkeit, denn sie sollen satt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Selig sind die Barmherzigen, denn sie werden Barmherzigkeit erlangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Selig sind, die reinen Herzens sind, denn sie werden Gott schauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Selig sind die Friedensstifter, denn sie werden Gottes Söhne heißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Selig sind, die um Gerechtigkeit willen verfolgt werden, denn das Reich der Himmel ist ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Selig seid ihr, wenn sie euch schelten und verfolgen und reden allerlei Übles wider euch um Meinetwillen, so sie daran lügen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Freuet euch und frohlocket, denn viel ist eures Lohns in den Himmeln; denn also verfolgten sie die Propheten, die vor euch gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Ihr seid das Salz der Erde; so aber das Salz fade wird, womit soll man salzen? Es ist zu nichts mehr nütze, als daß man es hinausirft, und es von den Menschen niedergetreten wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Ihr seid das Licht der Welt. Eine Stadt, die auf dem Berge liegt, kann nicht verborgen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Noch zündet man eine Kerze an und setzt sie unter einen Scheffel, sondern auf einen Leuchter, und sie leuchtet allen, die im Hause sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Also lasset euer Licht leuchten vor den Menschen, daß sie eure guten Werke sehen und euren Vater in den Himmeln verherrlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Denket nicht, daß Ich gekommen sei, das Gesetz oder die Propheten aufzulösen; Ich bin nicht gekommen aufzulösen, sondern zu erfüllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Denn wahrlich sage Ich euch: Bis daß Himmel und Erde vergehen, soll kein Jod noch ein Strichlein vom Gesetz vergehen, bis daß alles geschehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Wer nun eins dieser kleinsten Gebote löset, und lehret die Menschen also, wird der Kleinste heißen im Reiche der Himmel; wer aber tut und lehrt, der wird groß heißen im Reiche der Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Denn Ich sage euch: Es sei denn, daß eure Gerechtigkeit weit übertreffe die der Schriftgelehrten und Pharisäer, so werdet ihr nicht in das Reich der Himmel eingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Ihr habt gehört, daß zu den Alten gesagt ist: Du sollst nicht morden; wer aber mordet, der soll dem Gericht verfallen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'Ich aber sage euch: Wer seinem Bruder zürnt, ist dem Gericht verfallen; wer aber zu seinem Bruder sagt: Raka, der verfällt dem Rat; wer aber sagt: Du Narr, der verfällt der Hölle des Feuers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Wenn du denn deine Gabe auf dem Altar darbringst, und allda gedenkst, daß dein Bruder etwas wider dich hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'So laß allda vor dem Altar deine Gabe und geh erst hin und versöhne dich mit deinem Bruder und dann komm und bringe deine Gabe dar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Sei willfährig gegen deinen Widersacher, schnell, während du mit ihm auf dem Wege bist, auf daß dich der Widersacher nicht dem Richter überantworte und der Richter dich überantworte dem Amtsdiener und du in das Gefängnis geworfen werdest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Wahrlich, Ich sage dir, du wirst nicht von dannen herauskommen, bis daß du auch den letzten Heller bezahlst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Ihr habt gehört, daß zu den Alten gesagt ist: Du sollst nicht ehebrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'Ich aber sage euch, daß, wer ein Weib ansieht, um ihrer zu begehren, der hat schon mit ihr die Ehe gebrochen in seinem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Ärgert dich aber dein rechtes Auge, so reiß es aus und wirf es von dir; denn es ist dir zuträglicher, daß eins deiner Glieder verderbe, denn daß dein ganzer Leib in die Hölle geworfen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'Und ärgert dich deine rechte Hand, so haue sie ab und wirf sie von dir; denn es ist dir zuträglicher, daß eins deiner Glieder verderbe, denn daß dein ganzer Leib in die Hölle geworfen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Es ist aber gesagt worden: Wer sich von seinem Weibe scheidet, der gebe ihr einen Scheidebrief.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'Ich aber sage euch: Wer sich von seinem Weibe scheidet, es sei denn wegen Buhlerei, der macht, daß sie die Ehe bricht; und wer eine Geschiedene freit, der bricht die Ehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Wiederum habt ihr gehört, daß zu den Alten gesagt ist: Du sollst keinen falschen Eid tun, sondern dem Herrn deinen Eid halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'Ich aber sage euch: Ihr sollt gar nicht schwören, weder bei dem Himmel, denn er ist Gottes Thron;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'Noch bei der Erde, denn sie ist Seiner Füße Schemel; noch bei Jerusalem, denn sie ist des großen Königs Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'Auch nicht bei deinem Haupt sollst du schwören, denn du kannst nicht ein Haar weiß oder schwarz machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Euer Wort aber sei: Ja, ja, nein, nein. Was weiter ist, das ist vom Übel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Ihr habt gehört, daß gesagt ist: Augâ¬Ü um Auge und Zahn um Zahn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'Ich aber sage euch: Ihr sollt dem Übel nicht widerstehen; sondern so dir einer einen Streich gibt auf deinen rechten Backen, dem wende den andern auch zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'Dem, der mit dir rechten und dir den Rock nehmen will, dem laß auch das Oberkleid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'So dich einer eine Meile nötigt, gehe mit ihm zwei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Gib dem, der dich bittet, und wende dich nicht ab von dem, der von dir entlehnen will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Ihr habt gehört, daß gesagt ist: Du sollst deinen Nächsten lieben und deinen Feind hassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'Ich aber sage euch: Liebet eure Feinde, segnet, die euch fluchen, tut wohl denen, die euch hassen, und betet für die, welche euch beleidigen und verfolgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'Auf daß ihr Söhne werdet eures Vaters in den Himmeln; denn Er läßt Seine Sonne aufgehen über Schlechte und Gute, und läßt regnen über Gerechte und Ungerechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Denn so ihr liebet, die euch lieben, was für Lohn habt ihr? Tun nicht dasselbe auch die Zöllner?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'Und wenn ihr nur eure Brüder grüßet, was tut ihr weiteres? Tun nicht die Zöllner auch also?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'So sollt nun ihr vollkommen sein, gleichwie euer Vater in den Himmeln vollkommen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Habt acht auf euer Almosen, daß ihr es nicht gebet vor den Menschen, um von ihnen angesehen zu werden: ihr habt anders keinen Lohn bei eurem Vater in den Himmeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Wenn du aber Almosen gibst, laß nicht vor dir her posaunen, wie die Heuchler tun in den Synagogen und in den Gassen, auf daß sie von den Leuten verherrlicht werden. Wahrlich, Ich sage euch, sie haben ihren Lohn dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Wenn du aber Almosen gibst, laß deine linke Hand nicht wissen, was deine rechte tut;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'Auf daß dein Almosen im Verborgenen sei, und dein Vater, Der in das Verborgene sieht, wird dir es selber vergelten öffentlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'Und wenn du betest, sollst du nicht sein wie die Heuchler, die da gerne in den Synagogen und an den Ecken der Straßen stehen und beten, damit sie vor den Menschen scheinen. Wahrlich, Ich sage euch, sie haben ihren Lohn dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Wenn du aber betest, so gehe ein in deine Kammer und verschließe deine Tür und bete zu deinem Vater im Verborgenen. Und dein Vater, Der in das Verborgene sieht, wird es dir vergelten öffentlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Wenn ihr aber betet, sollt ihr nicht plappern wie die Heiden, denn sie meinen, sie werden erhört, wenn sie viele Worte machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Seid denn ihnen nicht ähnlich; denn euer Vater weiß, was ihr bedürfet, ehe denn ihr Ihn bittet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Darum sollt ihr also beten: Unser Vater in den Himmeln. Geheiligt werde Dein Name;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Dein Reich komme. Dein Wille geschehe, wie im Himmel, also auch auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Gib uns heute unser tägliches Brot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'Und vergib uns unsre Schulden, wie auch wir vergeben unsern Schuldnern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'Und führe uns nicht in Versuchung, sondern errette uns von dem Übel; denn Dein ist das Reich und die Kraft und die Herrlichkeit in Ewigkeit. Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Denn so ihr den Menschen ihre Fehle vergebt, so wird euch euer himmlischer Vater auch vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Wenn ihr aber den Menschen ihre Fehle nicht vergebet, so wird euer Vater eure Fehle auch nicht vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Wenn ihr aber fastet, sehet nicht düster drein, wie die Heuchler; denn sie entstellen ihre Angesichter, auf daß sie vor den Menschen scheinen mit ihrem Fasten. Wahrlich, Ich sage euch, sie haben ihren Lohn dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Wenn du aber fastest, salbe dein Haupt und wasche dein Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'Auf daß du nicht vor den Menschen scheinst mit deinem Fasten, sondern vor deinem Vater im Verborgenen; und dein Vater, Der in das Verborgene sieht, wird es dir vergelten öffentlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Speichert euch nicht Schätze auf Erden, wo sie Motte und Rost fressen, und wo Diebe einbrechen und stehlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'Speichert euch aber Schätze auf im Himmel, wo weder Motte noch Rost sie frißt, und wo Diebe nicht einbrechen noch stehlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Denn wo euer Schatz ist, da ist auch euer Herz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Des Leibes Leuchte ist das Auge. Wenn nun dein Auge einfältig ist, so ist dein ganzer Leib licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Wenn aber dein Auge arg ist, so ist dein ganzer Leib finster. Wenn nun das Licht in dir Finsternis ist, wie groß ist die Finsternis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Niemand kann zwei Herren dienen; denn entweder wird er den einen hassen und den andern lieben; oder wird er dem einen anhangen und den andern verachten. Ihr könnt nicht Gott dienen und dem Mammon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Darum sage Ich euch: Sorget nicht für eure Seele, was ihr essen und was ihr trinken werdet; noch für euren Leib, was ihr antun werdet. Ist nicht die Seele mehr als die Nahrung und der Leib mehr als die Kleidung?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Seht das Gevögel des Himmels an, sie säen nicht, sie ernten nicht, auch sammeln sie nicht in Scheunen, und euer himmlischer Vater nähret sie doch. Seid ihr nicht mehr denn sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Wer von euch kann mit Sorgen seinem Wuchse eine Elle hinzutun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'Und was sorget ihr für die Kleidung? Betrachtet die Lilien des Feldes, wie sie wachsen; sie mühen sich nicht ab, auch spinnen sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'Ich aber sage euch: Auch Salomoh in all seiner Herrlichkeit war nicht umkleidet wie derselben eine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'So denn Gott das Gras des Feldes, das heute da ist und morgen in den Ofen geworfen wird, also ankleidet, um wie viel mehr euch, ihr Kleingläubigen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Deshalb sollt ihr nicht sorgen und sagen: Was sollen wir essen, was sollen wir trinken, womit sollen wir uns umkleiden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Nach solch allem trachten die Heiden; denn euer himmlischer Vater weiß ja, daß ihr dies alles bedürfet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Trachtet am ersten nach dem Reiche Gottes und nach Seiner Gerechtigkeit; dann wird euch dies alles hinzugetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Darum sorget nicht für den morgenden Tag; denn der morgende Tag wird für das Seine sorgen. Genug für den Tag ist sein Böses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Richtet nicht, auf daß ihr nicht gerichtet werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Denn mit welcherlei Gericht ihr richtet, werdet ihr gerichtet werden, und mit welcherlei Maß ihr messet, wird euch gemessen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Was siehst du aber den Splitter in deines Bruders Auge, den Balken aber in deinem Auge gewahrst du nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Oder wie willst du zu deinem Bruder sagen: Laß mich, ich will dir den Splitter aus deinem Auge herausziehen? und siehe, der Balken ist in deinem Auge!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Du Heuchler, ziehe zuerst den Balken aus deinem Auge heraus, und dann magst du zusehen, wie du den Splitter aus deines Bruders Auge herausziehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Gebt das Heilige nicht den Hunden, und werfet eure Perlen nicht vor die Schweine, auf daß sie solche nicht mit ihren Füßen niedertreten und sich umwenden und euch zerreißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Bittet, und euch wird gegeben. Suchet, und ihr werdet finden. Klopfet an, und euch wird aufgetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Denn wer da bittet, der empfängt, und wer da sucht, der findet, und wer da anklopft, dem wird aufgetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Oder welcher Mensch ist unter euch, der, so ihn sein Sohn um Brot bäte, ihm einen Stein gäbe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'Oder der, wenn er ihn um einen Fisch bäte, ihm eine Schlange gäbe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'So denn ihr, die ihr arg seid, euren Kindern gute Gaben zu geben wisset, wie viel mehr wird euer Vater in den Himmeln Gutes geben denen, die Ihn bitten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Alles nun, das ihr wollet, daß euch die Menschen tun sollen, das tuet auch ihr ihnen, denn das ist das Gesetz und die Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Gehet ein durch das enge Tor; denn das Tor ist weit und der Weg ist breit, der ins Verderben hinführt, und wenige sind ihrer, die ihn durch eingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'Eng aber ist das Tor und schmal der Weg, der zum Leben hinführt, und wenige sind ihrer, die ihn finden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Nehmt euch in acht vor den falschen Propheten, die in Schafskleidern zu euch kommen, inwendig aber sind sie reißende Wölfe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'An ihren Früchten sollt ihr sie erkennen. Liest man auch Trauben von Dornen, oder Feigen von Disteln?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Also bringt jeglicher gute Baum gute Früchte; der faule Baum aber bringt schlechte Früchte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Ein guter Baum kann nicht schlechte Früchte bringen, und ein fauler Baum kann nicht gute Früchte bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Jeglicher Baum, der nicht gute Frucht bringt, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Darum an ihren Früchten sollt ihr sie erkennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Es wird nicht jeder, der zu Mir sagt: Herr, Herr, ins Reich der Himmel eingehen; sondern der den Willen tut Meines Vaters in den Himmeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Viele werden zu Mir an jenem Tage sagen: Herr, Herr, haben wir nicht in Deinem Namen geweissagt? und in Deinem Namen Dämonen ausgetrieben, und haben wir nicht in Deinem Namen viele Wundertaten getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'Und dann werde Ich ihnen bekennen: Ich habe euch nie erkannt. Weichet von Mir, die ihr Unrecht wirket.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Jeden nun, der diese Meine Worte hört und tut sie, will Ich einem klugen Manne vergleichen, der sein Haus auf den Felsen baute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'Und der Platzregen kam herab, und die Ströme kamen und die Winde wehten und stießen wider das Haus, und es fiel nicht; denn es war auf den Felsen gegründet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'Und jeder, der diese Meine Worte hört und tut sie nicht, ist einem törichten Manne zu vergleichen, der sein Haus auf den Sand baute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'Und der Platzregen kam herab und die Ströme kamen und die Winde wehten und stießen gegen das Haus, und es fiel, und sein Fall war groß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'Und es geschah, da Jesus diese Worte vollendet hatte, staunte das Volk über Seine Lehre;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'Denn Er lehrte sie wie einer, der Gewalt hat, und nicht wie die Schriftgelehrten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'Da Er aber vom Berge herabstieg, folgte Ihm viel Volks nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'Und siehe, ein Aussätziger kam und betete Ihn an und sprach: Herr, so Du willst, kannst Du mich reinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'Und Jesus streckte Seine Hand aus, berührte ihn und sprach: Ich will; sei gereinigt! Und alsbald war sein Aussatz gereinigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'Und Jesus spricht zu ihm: Siehe, sage es niemand, sondern gehe hin, zeige dich dem Priester, und bringe die Gabe dar, die Moses verordnet hat, zum Zeugnis für sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Als Jesus aber einging nach Kapernaum, kam zu Ihm ein Hauptmann, flehte Ihn an,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'Und sagte: Herr, mein Knabe liegt im Hause gichtbrüchig danieder, schrecklich gequält.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Und Jesus spricht zu ihm: Ich will kommen und ihn heilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'Und der Hauptmann antwortete und sprach: Herr, ich bin nicht genugsam, daß Du unter mein Dach eingehst; sondern sprich nur ein Wort, so wird mein Knabe gesund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Denn auch ich bin ein Mensch unter Obergewalt, und habe Kriegsknechte unter mir, und wenn ich zu einem sage: ziehe hin! so zieht er hin, und zum andern: komm! so kommt er, und zu meinem Knechte: tue das! so tut er es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Da aber Jesus dies hörte, verwunderte Er Sich und sprach zu denen, die Ihm nachfolgten: Wahrlich, Ich sage euch: Auch nicht in Israel habe Ich solchen Glauben gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Aber Ich sage euch: Viele werden kommen vom Aufgang und vom Niedergang und mit Abraham und Isaak und Jakob sich niederlegen im Reiche der Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'Die Söhne des Reichs aber werden hinausgeworfen in die äußerste Finsternis. Dort wird sein Heulen und Zähneknirschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'Und Jesus sprach zu dem Hauptmann: Gehe hin, und wie du geglaubt hast, soll dir werden. Und der Knabe ward gesund zur selbigen Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'Und als Jesus in des Petrus Haus kam, sah Er seine Schwieger liegen, und sie hatte Fieber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'Und Er berührte ihre Hand, und das Fieber verließ sie, und sie machte sich auf und bediente sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Als es aber Abend war, brachten sie viele Besessene zu Ihm, und Er trieb die Geister aus mit einem Wort, und Er heilte alle Leidenden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'Auf daß erfüllt würde, was durch den Propheten Jesajas gesagt ward, der spricht: Er hat unsere Gebrechen auf Sich genommen und unsere Krankheiten getragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Als Jesus aber das viele Gedränge um Sich sah, befahl Er, jenseits hinüber zu fahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Und es kam einer, ein Schriftgelehrter, und sprach zu Ihm: Lehrer, ich will Dir nachfolgen, wo Du auch hingehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'Und Jesus spricht zu ihm: Die Füchse haben Baue, und das Gevögel des Himmels Nester; des Menschen Sohn aber hat nicht, wo Er Sein Haupt hinlege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'Ein anderer von Seinen Jüngern aber sprach zu Ihm: Herr, gestatte mir, daß ich zuerst hingehe und meinen Vater begrabe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Jesus aber sprach zu ihm: Folge du Mir nach und lasse die Toten ihre Toten begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'Und als Er in das Fahrzeug einstieg, folgten Ihm Seine Jünger nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'Und siehe, es erhob sich ein großes Ungestüm in dem Meere also, daß das Fahrzeug von den Wellen bedeckt ward. Er aber schlief.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'Und die Jünger kamen hinzu, weckten Ihn auf und sagten: Herr, rette uns, wir verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'Und Er spricht zu ihnen: Was seid ihr furchtsam, ihr Kleingläubigen? Dann stand Er auf, bedrohte die Winde und das Meer, und es ward eine große Windstille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Die Menschen aber verwunderten sich und sagten: Welcher Art ist Der, daß Ihm Winde und Meer gehorchen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'Und als Er hinüberkam in die Landschaft der Gardarener, kamen Ihm zwei Besessene entgegen, die aus den Grüften herauskamen, und ungemein unbändig waren, so daß niemand vermochte jenes Weges vorbeizugehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'Und siehe da, sie schrien und sagten: Was haben wir mit Dir, Jesus, Du Sohn Gottes? Bist Du hierher gekommen, uns vor der Zeit zu quälen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'Es war aber ferne von ihnen ein Trieb vieler Schweine auf der Weide.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Die Dämonen aber flehten Ihn an und sagten: Wenn Du uns austreibst, so gestatte uns, in den Trieb der Schweine hinzufahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'Und Er sprach zu ihnen: Fahret hin! Da kamen sie heraus und fuhren in den Trieb der Schweine. Und siehe da, der ganze Trieb von Schweinen stürzte sich von der Anhöhe hinab in das Meer und kam um in dem Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Und die sie weideten, flohen und gingen hin in die Stadt und sagten an alles, und auch über die Besessenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'Und siehe, da kam die ganze Stadt heraus, Jesus entgegen, und da sie Ihn sahen, flehten sie Ihn an, Er möchte von ihren Grenzen weitergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'Und Er stieg ein in das Fahrzeug, fuhr hinüber und kam in Seine eigene Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'Und siehe, da brachten sie zu Ihm einen Gichtbrüchigen, der auf einem Bette daniederlag. Und da Jesus ihren Glauben sah, sprach er zu dem Gichtbrüchigen: Sei getrost, mein Kind, deine Sünden sind dir vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'Und siehe, einige Schriftgelehrten sprachen bei sich: Dieser lästert Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'Und da Jesus ihre Gedanken sah, sprach Er: Warum gedenkt ihr Arges in euren Herzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Denn was ist leichter zu sagen: Die Sünden sind dir vergeben, oder zu sagen: Mache dich auf und wandle?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Auf daß ihr aber wisset, daß des Menschen Sohn Gewalt hat auf Erden, Sünden zu vergeben: Mache dich auf, hebe dein Bett auf und gehe hin in dein Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'Und er machte sich auf und ging hin in sein Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Da aber das Gedränge dies sah, verwunderten sie sich und verherrlichten Gott, Der solche Gewalt den Menschen gegeben habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'Und da Jesus von dannen vorüberging, sah Er einen Menschen am Zolle sitzen, Matthäus genannt, und Er sprach zu Ihm: Folge Mir nach! Und er stand auf und folgte ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'Und es geschah, als Er im Hause zu Tische lag, siehe, da kamen viele Zöllner und Sünder und legten sich mit Jesus und Seinen Jüngern zu Tische.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'Wie dies die Pharisäer sahen, sprachen sie zu Seinen Jüngern: Warum ißt euer Lehrer mit den Zöllnern und Sündern?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Jesus aber hörte es und sprach zu ihnen: Die Starken bedürfen des Arztes nicht, sondern die Leidenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Gehet aber hin und lernet, was das ist: Ich will Barmherzigkeit und nicht Opfer; denn Ich bin nicht gekommen, Gerechte, sondern Sünder zur Buße zu rufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Da kamen des Johannes Jünger herzu zu Ihm und sagten: Warum fasten wir und die Pharisäer so viel, und Deine Jünger fasten nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'Und Jesus sprach zu ihnen: Können die Söhne des Brautgemachs trauern, solange der Bräutigam bei ihnen ist? Es werden aber Tage kommen, da der Bräutigam von ihnen hinweggenommen wird, und dann werden sie fasten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Niemand setzt einen Fleck ungewalkten Tuches auf ein altes Kleid; denn sein Füllwerk nimmt von dem Kleide und der Riß wird schlimmer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Auch fasset man nicht neuen Wein in alte Schläuche, sonst zerreißen die Schläuche und der Wein wird verschüttet und die Schläuche verderben; sondern man fasset neuen Wein in neue Schläuche, und beide werden miteinander erhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Während Er solches zu ihnen redete, siehe, da kam der Obersten einer, fiel vor Ihm nieder und sagte: Meine Tochter ist eben jetzt gestorben; aber komm, lege Deine Hand auf sie, und sie wird leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'Und Jesus machte Sich auf, folgte Ihm nach und Seine Jünger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'Und siehe, eine Weib, das zwölf Jahre den Blutfluß hatte, trat von hinten herzu und berührte den Saum Seines Kleides.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Denn sie sagte bei sich selbst: Wenn ich nur Sein Kleid berühre, so bin ich gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Jesus aber wandte Sich um und sah sie und sprach: Sei getrost, Meine Tochter, dein Glaube hat dir geholfen. Und dem Weib ward geholfen zur selbigen Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'Und Jesus kam in das Haus des Obersten und sah die Pfeifer und das lärmende Gedränge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'Und Er sprach zu ihnen: Weichet, denn das Mägdlein ist nicht gestorben, sondern es schlummert. Und sie verlachten Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Als aber das Gedränge hinausgetrieben war, ging Er hinein, ergriff sie bei der Hand, und das Mägdlein richtete sich auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'Und das Gerücht davon ging aus in dasselbige ganze Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'Und da Jesus von dannen weiterging, folgten Ihm zwei Blinde nach, schrien und sprachen: Sohn Davids, erbarme Dich unser!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Als Er aber in das Haus kam, kamen die Blinden her zu Ihm, und Jesus spricht zu ihnen: Glaubet ihr, daß Ich solches tun kann? Sie sprachen zu Ihm: Ja, Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Da berührte Er ihre Augen und sprach: Nach eurem Glauben geschehe euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'Und ihre Augen wurden aufgetan. Und Jesus drohte ihnen und sprach: Sehet zu, daß es niemand erfahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Sie aber gingen aus und machten Ihn ruchbar in selbigem ganzen Lande.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Als sie aber ausgingen, siehe, da brachen sie einen Menschen zu Ihm herbei, der stumm und besessen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'Und als der Dämon ausgetrieben war, redete der Stumme. Und die Menge verwunderte sich, und sie sprachen: Noch nie ist solches in Israel erschienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Die Pharisäer aber sagten: Durch den Obersten der Dämonen treibt Er die Dämonen aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'Und Jesus zog in allen Städten und Flecken umher, lehrte in ihren Synagogen und predigte das Evangelium des Reichs und heilte alle Krankheit und alles Siechtum im Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Und da Er das Gedränge sah, jammerte Ihn derselben, daß sie so verschmachtet und dahingeworfen wären, wie Schafe, die keinen Hirten haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Da spricht Er zu Seinen Jüngern: Viel ist der Ernte, aber wenige sind der Arbeiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Darum flehet zum Herrn der Ernte, daß Er Arbeiter in Seine Ernte ausschicke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'Und Er rief Seine zwölf Jünger zu Sich, und gab ihnen Gewalt über unreine Geister, sie auszutreiben, und alle Krankheit und alles Siechtum zu heilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Die Namen der zwölf Apostel aber sind diese: Der erste Simon, genannt Petrus, und Andreas, sein Bruder; Jakobus, des Zebedäus, und Johannes, sein Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Philippus und Bartholomäus, Thomas und Matthäus, der Zöllner, Jakobus, des Alphäus und Lebbäus, mit dem Zunamen Thaddäus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon, der Kananite, und Judas Ischariot, der Ihn auch verriet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Diese Zwölfe sandte Jesus aus, entbot ihnen und sprach: Gehet nicht hin auf den Weg der Heiden und in eine Stadt der Samariter gehet nicht ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'Zieht vielmehr hin zu den verlorenen Schafen des Hauses Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Wenn ihr aber hinzieht, predigt und sprechet: Das Reich der Himmel hat sich genaht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Heilt die Siechen, reinigt Aussätzige, weckt Tote auf, treibt Dämonen aus. Umsonst habt ihr empfangen, umsonst gebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ihr sollt nicht besitzen Gold noch Silber, noch Erz in euren Gürteln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'Keine Tasche auf den Weg, noch zwei Röcke, noch Sandalen, noch Stab; denn der Arbeiter ist seiner Nahrung wert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'Wo ihr aber in eine Stadt oder in einen Flecken eingeht, erforschet, wer darin ist, der es wert ist, und dort bleibt, bis ihr von dannen ausgeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'So ihr aber in das Haus eingeht, grüßet dasselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'Und so das Haus es wert ist, komme euer Friede auf dasselbe. Ist es aber nicht wert, so wende sich euer Friede zurück zu euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'Und so euch einer nicht aufnimmt, noch auf eure Worte hört, so geht aus jenem Hause oder jener Stadt hinaus und schüttelt den Staub eurer Füße ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Wahrlich, Ich sage euch: Es wird dem Lande der Sodomer und Gomorrer erträglicher sein am Tage des Gerichts, als jener Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Siehe, Ich sende euch aus wie Schafe mitten unter Wölfe. Seid denn klug, wie die Schlangen, und ohne Falsch, wie die Tauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Nehmt euch aber in acht vor den Menschen; denn sie werden euch überantworten ihren Räten und euch geißeln in ihren Synago- gen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Und sie werden euch wegen Meiner vor Fürsten und Könige führen, zum Zeugnis über sie und über die Heiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Wenn sie euch aber überantworten, so sorget nicht, wie oder was ihr reden sollt; denn es wird euch zu jener Stunde gegeben werden, was ihr reden sollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Denn nicht ihr seid es, die das reden, sondern der Geist eures Vaters ist es, der in euch redet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Es wird aber ein Bruder den Bruder und der Vater das Kind zum Tode überantworten; und Kinder werden gegen Eltern aufstehen und sie zum Tode bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'Und ihr werdet gehaßt werden von allen um Meines Namens willen; wer aber beharrt bis ans Ende, der wird gerettet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Wenn sie euch aber verfolgen in einer Stadt, so flieht in die andere, denn wahrlich, Ich sage euch: Ihr werdet mit den Städten Israels nicht zu Ende sein, bis des Menschen Sohn kommen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Der Jünger ist nicht über dem Lehrer, noch der Knecht über seinem Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Es ist genug für den Jünger, daß er sei wie sein Lehrer, und der Knecht wie sein Herr. Haben sie den Hausherrn Beelzebub geheißen, wieviel mehr seine Hausgenossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Darum fürchtet euch nicht vor ihnen; denn nichts ist verdeckt, das nicht offenbar würde, und nichts verborgen, das man nicht erkennen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Was Ich euch sage in der Finsternis, das sprechet im Licht, und was ihr höret in das Ohr, das predigt auf den Dächern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'Und fürchtet euch nicht vor denen, die den Leib töten, die Seele aber nicht töten können. Fürchtet euch aber vielmehr vor dem, der Seele und Leib in der Hölle verderben kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Verkauft man nicht zwei Sperlinge um einen Pfennig? Und keiner derselben fällt zur Erde ohne euren Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Es sind aber auch die Haare eures Hauptes alle gezählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Darum fürchtet euch nicht. Ihr seid mehr, denn viele Sperlinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Einen jeden, der Mich bekennt vor den Menschen, den will Ich auch bekennen vor Meinem Vater in den Himmeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Wer Mich aber verleugnet vor den Menschen, den werde Ich auch verleugnen vor Meinem Vater in den Himmeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Denket nicht, daß Ich gekommen bin, Frieden auf die Erde zu bringen. Ich bin nicht gekommen, Frieden zu bringen, sondern das Schwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Denn Ich bin gekommen, den Menschen mit seinem Vater zu entzweien und die Tochter mit ihrer Mutter, und die Schnur mit ihrer Schwieger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'Und die Feinde des Menschen werden seine eigenen Hausgenossen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Wer Vater oder Mutter mehr lieb hat, denn Mich, der ist Meiner nicht wert; und wer Sohn oder Tochter mehr lieb hat, denn Mich, der ist Meiner nicht wert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'Und wer nicht sein Kreuz auf sich nimmt und hinter Mir nachfolgt, der ist Meiner nicht wert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Wer seine Seele findet, der wird sie verlieren; und wer seine Seele verliert um Meinetwillen, der wird sie finden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Wer euch aufnimmt, der nimmt Mich auf, und wer Mich aufnimmt, der nimmt Den auf, Der Mich ausgesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Wer einen Propheten aufnimmt in eines Propheten Namen, wird eines Propheten Lohn empfangen, und wer einen Gerechten aufnimmt in eines Gerechten Namen, wird eines Gerechten Lohn empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'Und wer einen dieser Kleinen nur mit einem Kelch kalten tränkt in eines Jüngers Namen, wahrlich, Ich sage euch, er wird seinen Lohn nicht verlieren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'Und es geschah, da Jesus Seine Verordnungen an Seine zwölf Jünger vollendet hatte, ging Er von dannen weiter, um in ihren Städten zu lehren und zu predigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Da aber Johannes im Kerker Christi Werke hörte, schickte er zwei seiner Jünger,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'Und ließ Ihm sagen: Bist Du, Der da kommen soll, oder sollen wir einen andern erwarten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'Und Jesus antwortete und sprach zu ihnen: Ziehet hin und saget dem Johannes an, was ihr hört und seht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Blinde sehen und Lahme wandeln, Aussätzige werden rein und Taube hören, Tote werden auferweckt und den Armen wird das Evangelium gepredigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'Und selig ist, wer sich nicht an Mir ärgert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'Als diese aber hingingen, fing Jesus an zu dem Gedränge von Johannes zu sprechen: Was seid ihr hinausgegangen in die Wüste anzusehen? ein Rohr, das vom Winde hin und her geweht wird?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Oder was seid ihr ausgegangen zu sehen? einen Menschen mit weichen Kleidern umkleidet? Siehe, die da weiche tragen, sind in der Könige Häuser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Aber was seid ihr ausgegangen zu sehen? einen Propheten? Ja, Ich sage euch: Und einen, der weit mehr ist denn ein Prophet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Denn dieser ist es, von dem geschrieben ist: Siehe, Ich sende Meinen Boten aus vor Deinem Angesicht, der den Weg vor Dir zurüsten soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Wahrlich, Ich sage euch: Es ist unter denen, die von Weibern geboren sind, kein Größerer erweckt worden, denn Johannes der Täufer; aber wer im Reiche der Himmel kleiner ist, ist größer denn er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Aber von den Tagen Johannes des Täufers bis hierher leidet das Reich der Himmel Gewalt, und die Gewalttätigen erhaschen es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Denn alle Propheten und das Gesetz bis auf Johannes haben geweissagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'Und, so ihr es aufnehmen wollt: er ist Elias, der da kommen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Wer Ohren hat zu hören, der höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Wem aber soll Ich dieses Geschlecht vergleichen? Es ist den Kindern ähnlich, die im Markte sitzen und ihren Gesellen zurufen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'Und sagen: Wir haben euch gepfiffen, und ihr habt nicht getanzt. Wir haben euch geklagt, und ihr habt nicht gejammert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Denn Johannes kam, aß nicht und trank nicht; und sie sagen: Er hat einen Dämon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Des Menschen Sohn kam, Er aß und trank; und sie sagen: Siehe, der Mensch ist ein Fresser und Weintrinker, der Zöllner und Sünder Freund - und gerechtfertigt wurde die Weisheit von ihren Kindern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Alsdann fing Er an, die Städte zu schelten, in denen die meisten Seiner Wunderkräfte geschahen, daß sie nicht Buße getan:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Wehe dir, Chorazin, wehe dir, Bethsaida. Wären die Wunderkräfte, die in euch geschahen, in Tyrus und Sidon geschehen, sie hätten längst in Sack und Asche Buße getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Aber Ich sage euch: Es wird Tyrus und Sidon erträglicher sein am Tage des Gerichts, denn euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'Und du, Kapernaum, die du bis an den Himmel erhöht bist, du wirst bis in die Hölle hinabgestoßen werden, denn so geschehen wären in Sodom die Wunderkräfte, die in dir geschahen, wäre dasselbe wohl noch bis auf diesen Tag geblieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Aber Ich sage euch: Es wird dem Lande der Sodomer am Tage des Gerichts erträglicher sein, als dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'Zur selben Zeit antwortete Jesus und sprach: Ich bekenne Dich, Vater, Herr des Himmels und der Erde, daß Du dies vor den Weisen und Verständigen verborgen und den Unmündigen geoffenbart hast;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'Ja, Vater, daß also geschah, war wohlgefällig vor Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Alles ist Mir von Meinem Vater überantwortet; und niemand kennt den Sohn, denn nur der Vater, noch kennt jemand den Vater, denn nur der Sohn, und wem der Sohn willens ist, es zu offenbaren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Kommet her zu Mir alle, die ihr mühselig und beladen seid, und Ich will euch Ruhe schaffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Nehmet auf euch Mein Joch und lernet von Mir; denn Ich bin sanftmütig und von Herzen demütig, und ihr werdet Ruhe finden für eure Seelen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Denn Mein Joch ist sanft und Meine Last ist leicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'Zu der Zeit ging Jesus am Sabbath durch die Saatfelder, Seine Jünger aber waren hungrig und fingen an, Ähren auszuraufen und zu essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Da aber die Pharisäer das sahen, sprachen sie zu Ihm: Siehe, Deine Jünger tun, was nicht erlaubt ist zu tun am Sabbath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'Er aber sprach zu ihnen: Habt ihr nicht gelesen, was David tat, als ihn und die mit ihm waren hungerte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'Wie er in das Gotteshaus hineinging und die Schaubrote aß, die ihm nicht erlaubt war zu essen, noch denen, die mit ihm waren, sondern nur allein den Priestern?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Oder habt ihr nicht im Gesetz gelesen, daß die Priester am Sabbath im Heiligtum den Sabbath entweihen und schuldlos sind?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Ich aber sage euch, daß hier ist ein Größerer denn das Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Wenn ihr aber erkannt hättet, was das ist: â¬~Ich will Barmherzigkeit und nicht Opferâ¬S, so hättet ihr die Schuldlosen nicht verurteilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Denn des Menschen Sohn ist Herr auch des Sabbaths.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'Und da Er von dannen weiterging, kam Er in ihre Synagoge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'Und siehe, da war ein Mensch, der hatte eine verdorrte Hand. Und sie fragten Ihn und sagten: Ist es erlaubt, am Sabbath zu heilen? auf daß sie Ihn anklagen könnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'Er aber sprach zu ihnen: Welcher Mensch ist von euch, der ein Schaf hat und wenn dieses am Sabbath in eine Grube fällt, es nicht ergreift und heraufhebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'Wieviel aber ist der Mensch mehr denn ein Schaf? Darum ist es erlaubt, am Sabbath Gutes zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Alsdann spricht Er zu dem Menschen: Recke deine Hand aus! Und er reckte sie aus, und sie war wiederhergestellt, gesund wie die andere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Die Pharisäer aber gingen hinaus und hielten eine Beratung über Ihn, wie sie Ihn umbrächten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Da aber Jesus es erkannte, entwich Er von dannen; und es folgte Ihm viel Gedränge nach, und Er heilte sie alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'Und Er bedrohte sie, sie sollten Ihn nicht kundbar machen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'Auf daß erfüllt würde, was durch Jesaja, den Propheten, gesagt wird, der da spricht:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, 'Siehe, das ist Mein Knecht, Den Ich erwählt habe, Mein Geliebter, an Dem Meine Seele Wohlgefallen hat. Ich will Meinen Geist auf Ihn legen, und Er soll den Völkerschaften das Gericht ansagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Nicht zanken noch aufschreien soll Er, noch soll man Seine Stimme auf den Straßen hören!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Ein zerknicktes Rohr wird Er nicht zerbrechen, und den glimmenden Docht wird Er nicht auslöschen, bis daß Er hervorbringet zum Siege das Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'Und auf Seinen Namen sollen die Völkerschaften hoffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Da brachte man zu Ihm einen Besessenen, der blind und stumm war, und Er heilte ihn, so daß der Blinde und Stumme beides redete und sah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'Und all das Gedränge war außer sich, und sie sprachen: Ist das nicht der Sohn Davids?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Als es aber die Pharisäer hörten, sagten sie: Der treibt die Dämonen nicht aus, denn durch Beelzebul, den Obersten der Dämonen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'Jesus aber, Der ihre Gedanken sah, sprach zu ihnen: Jegliches Reich, das wider sich selbst geteilt ist, wird wüste; und jegliche Stadt oder jegliches Haus, das wider sich selbst geteilt ist, wird nicht stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'Und wenn der Satan den Satan austreibt, so ist er wider sich selbst geteilt. Wie kann dann sein Reich bestehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'Und wenn Ich durch Beelzebul die Dämonen austreibe, durch wen treiben eure Söhne sie aus? Darum werden sie eure Richter sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Wenn Ich aber die Dämonen durch den Geist Gottes austreibe, so ist ja das Reich Gottes über euch herbeigekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Oder wie kann einer in das Haus des Starken hineinkommen und ihn seiner Gefäße berauben, wofern er nicht zuvor den Starken gebunden hat? Dann kann er ihm sein Haus berauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Wer nicht mit Mir ist, der ist wider Mich, und wer nicht mit Mir sammelt, der verstreut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Deshalb sage Ich euch: Jede Sünde und Lästerung mag den Menschen vergeben werden; aber die Lästerung des Geistes wird den Menschen nicht vergeben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'Und wer ein Wort spricht wider des Menschen Sohn, dem wird vergeben werden; wer aber wider den Heiligen Geist spricht, dem wird nicht vergeben werden, weder in diesem Zeitlauf, noch im zukünftigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Machet entweder den Baum gut und seine Frucht gut, oder macht den Baum faul und seine Frucht faul. Denn an der Frucht erkennt man den Baum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Ihr Otterngezüchte, wie könnt ihr Gutes reden, während ihr arg seid? Denn aus dem Überfluß des Herzens redet der Mund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Der gute Mensch bringt Gutes hervor aus dem guten Schatz des Herzens, und der schlechte Mensch aus dem schlechten Schatz bringt Schlechtes hervor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Ich sage euch aber: Von jeder müßigen Rede, welche die Menschen reden, müssen sie Rechenschaft geben am Tage des Gerichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Denn aus deinen Worten wirst du gerechtfertigt und aus deinen Worten wirst du verurteilt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Da antworteten einige der Schriftgelehrten und Pharisäer und sprachen: Lehrer, wir wollten ein Zeichen von Dir sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'Er aber antwortete und sprach zu ihnen: Ein schlechtes und ehebrecherisches Geschlecht trachtet nach einem Zeichen, und es soll ihm kein Zeichen gegeben werden, denn das Zeichen Jonas, des Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Denn wie Jonas drei Tage und drei Nächte im Bauche des Walfisches war, so wird des Menschen Sohn drei Tage und drei Nächte im Herzen der Erde sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Die Männer aus Niniveh werden im Gericht gegen dieses Geschlecht aufstehen und es verdammen; denn auf die Predigt des Jonas taten sie Buße, und siehe, hier ist mehr denn Jonas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Die Königin vom Mittag wird im Gericht wider dies Geschlecht auftreten und es verdammen; denn sie kam vom Äußersten der Erde, Salomohs Weisheit zu hören. Und siehe, hier ist mehr denn Salomoh.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Wenn aber der unreine Geist von dem Menschen ausgeht, so geht er durch wasserlose Orte, sucht Ruhe und findet sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Dann sagt er: Ich will umkehren in mein Haus, davon ich ausgegangen bin. Und wenn er kommt, findet er es leerstehend, gekehrt und geschmückt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Da geht er hin und nimmt zu sich sieben andere Geister, schlechter denn er, und sie gehen ein und wohnen da, und es wird das Letzte jenes Menschen schlimmer denn sein Erstes. So wird es auch mit diesem argen Geschlecht ergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Während Er noch so mit dem Volke redete, siehe, da standen Seine Mutter und Seine Brüder außen, und suchten mit Ihm zu reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'Einer aber sprach zu Ihm: Siehe, Deine Mutter und Deine Brüder stehen draußen und suchen mit Dir zu reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'Er aber antwortete und sprach zu dem, der zu Ihm sprach: Wer ist Meine Mutter, und wer sind Meine Brüder?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'Und Er reckte Seine Hand aus über Seine Jünger und sprach: Siehe da, Meine Mutter und Meine Brüder!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Denn wer den Willen tut Meines Vaters in den Himmeln, der ist Mir Bruder und Schwester und Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'An demselben Tage ging Jesus hinaus aus dem Hause und setzte Sich ans Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'Und es sammelte sich viel Gedränge zu Ihm, so daß Er in ein Schiff einstieg, Sich niederzusetzen; und all das Gedränge stand am Ufer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'Und Er redete vieles zu ihnen in Gleichnissen und sprach: Siehe, es ging der Sämann aus zu säen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'Und indem er säte, fiel einiges an den Weg; und es kam das Gevögel und fraß es auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Anderes aber fiel auf das Steinigte, wo es nicht viel Erde hatte, und ging alsbald auf, weil es nicht tiefe Erde hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Als aber die Sonne aufging, ward es versengt; und weil es nicht Wurzel hatte, verdorrte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Anderes aber fiel auf die Dornen, und die Dornen stiegen auf und erstickten es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Anderes aber fiel auf gutes Land und gab Frucht: einiges hundertfältig, einiges sechzigfältig, einiges aber dreißigfäl- tig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Wer Ohren hat zu hören, der höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'Und es kamen die Jünger herzu und sprachen zu Ihm: Warum redest Du zu ihnen in Gleichnissen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'Er aber antwortete und sprach zu ihnen: Euch ist gegeben, die Geheimnisse des Reiches der Himmel zu erkennen, jenen aber ist es nicht gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Denn wer da hat, dem wird gegeben, daß er Überfluß habe; wer aber nicht hat, von dem wird auch, das er hat, genommen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Darum rede Ich in Gleichnissen zu ihnen; denn sehend sehen sie nicht, und hörend hören sie nicht, noch verstehen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'Und an ihnen wird die Weissagung des Propheten Jesajas erfüllt, die sagt: Hörend werdet ihr hören und nicht verstehen, und sehend werdet ihr sehen und nicht vernehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Denn das Herz dieses Volkes ist verstockt, und mit ihren Ohren hören sie schwer, und sie drücken die Augen zu, damit sie nicht sehen mit den Augen und hören mit den Ohren und mit dem Herzen verstehen und umkehren und Ich sie gesund mache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Selig aber sind eure Augen, daß sie sehen, und eure Ohren, daß sie hören;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Denn wahrlich, Ich sage euch, daß viele Propheten und Gerechte haben begehrt zu sehen, was ihr seht, und haben es nicht gesehen, und zu hören, was ihr hört, und haben es nicht gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'So hört ihr denn das Gleichnis von dem Sämann!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Wenn jemand das Wort von dem Reiche hört und nicht versteht, so kommt der Arge und erhascht, was in seinem Herzen gesät ist. Dieser ist es, der an dem Wege gesät ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Der aber, der auf das Steinigte gesät worden, ist der, welcher das Wort hört, und es alsbald mit Freuden aufnimmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'Aber er hat keine Wurzel in sich, sondern ist zeitweilig; so aber Trübsal oder Verfolgung geschieht um des Wortes willen, so ärgert er sich alsbald.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Der aber, der in die Dornen gesät worden, ist der, welcher das Wort hört; und die Sorge dieses Zeitlaufs, und der Betrug des Reichtums erstickt das Wort, und es wird unfruchtbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Der aber auf das gute Land gesät ist, ist der, so das Wort hört und versteht, und der dann Frucht trägt; und der eine bringt hundertfältig, der andere aber sechzigfältig, der andere aber dreißigfältig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Er legte ihnen ein anderes Gleichnis vor und sprach: Das Reich der Himmel gleicht einem Menschen der guten Samen in sein Feld säte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Während aber die Menschen schlummerten, kam sein Feind und säte Unkraut mitten unter den Weizen und ging hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Als aber die Saat hervorsproßte und Frucht brachte, da erschien auch das Unkraut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Die Knechte aber des Hausherrn kamen herzu und sprachen zu ihm: Herr, hast du nicht guten Samen in dein Feld gesät? Woher hat er nun das Unkraut?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'Er aber sprach zu ihnen: Ein feindseliger Mensch hat das getan. Die Knechte aber sprachen zu ihm: Willst du nun, daß wir hingehen und es zusammenlesen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'Er aber sprach: Nein, auf daß ihr nicht, wenn ihr das Unkraut zusammenleset, zugleich damit den Weizen ausreutet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Lasset beide zusammen wachsen bis zur Ernte, und zur Zeit der Ernte will ich den Schnittern sagen: Leset erst das Unkraut zusammen und bindet es in Bündel, um es zu verbrennen; den Weizen aber sammelt in meine Scheune.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Ein anderes Gleichnis legte Er ihnen vor und sagte: Das Reich der Himmel ist gleich einem Senfkorn, das ein Mensch nahm und auf sein Feld säte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'Welches zwar kleiner ist als alle Samen, wenn es aber erwächst, ist es das größte unter den Gartenkräutern, und wird ein Baum, so daß das Gevögel des Himmels kommt und in seinen Zweigen nistet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Ein anderes Gleichnis redete Er zu ihnen: Das Reich der Himmel ist gleich einem Sauerteig, den ein Weib nahm und in drei Maß Mehl barg, bis daß es ganz durchsäuert war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Dieses alles redete Jesus in Gleichnisse zu dem Volk, und ohne Gleichnis redete Er nicht zu ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'Damit erfüllt würde, was durch den Propheten gesagt ist, der da spricht: Ich will Meinen Mund auftun in Gleichnissen. Ich will aussprechen, was seit Gründung der Welt verborgen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Da entließ Jesus das Volk und kam in das Haus, und Seine Jünger kamen zu Ihm und sprachen: Deute uns das Gleichnis von dem Unkraut des Feldes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'Er aber antwortete und sprach zu ihnen: Der den guten Samen sät, ist des Menschen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'Das Feld ist die Welt. Der gute Same, das sind die Söhne des Reiches; das Unkraut aber sind die Söhne des Argen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'Der Feind aber, der es säte, ist der Teufel. Die Ernte aber ist die Vollendung des Zeitlaufs; die Schnitter aber sind die Engel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Wie nun das Unkraut zusammengelesen und im Feuer verbrannt wird, so wird es bei der Vollendung dieses Zeitlaufs geschehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Der Sohn des Menschen wird Seine Engel aussenden, und sie werden aus Seinem Reiche zusammenlesen alle Ärgernisse und die da Unrecht tun;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'Und werden sie in den Feuerofen werfen. Dort wird sein Heulen und Zähneknirschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Dann werden die Gerechten hervorleuchten, wie die Sonne, im Reiche ihres Vaters. Wer Ohren hat zu hören, der höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Wiederum gleicht das Reich der Himmel einem Schatze, der in dem Felde verborgen liegt, den ein Mensch findet und verbirgt und in seiner Freude hingeht und alles, was er hat, verkauft und dieses Feld kauft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Wiederum ist das Reich der Himmel gleich einem Menschen, einem Kaufmann, der schöne Perlen sucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'Wenn der eine kostbare Perle gefunden, geht er hin, verkauft alles, was er hat, und kauft dieselbige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Wiederum ist das Reich der Himmel gleich einem Zugnetze, das ins Meer geworfen ward und allerlei Gattung zusammensammelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Welches sie, wenn es voll ist, ans Ufer heraufziehen, und sich niedersetzen und lesen die guten zusammen in Gefäße, die faulen aber werfen sie hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'So wird es sein bei der Vollendung des Zeitlaufs. Die Engel werden ausgehen und ausscheiden die Schlechten aus der Mitte der Gerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'Und werden sie in den Feuerofen werfen. Dort wird sein Weinen und Zähneknirschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Spricht zu ihnen Jesus: Habt ihr das alles verstanden? Sie sagen zu Ihm: Ja, Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'Er aber sprach zu ihnen: Deshalb ist jeder Schriftgelehrte, der für das Reich der Himmel unterrichtet worden, gleich einem Menschen, einem Hausherrn, der aus seinem Schatz Neues und Altes hervorbringt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'Und es geschah, da Jesus diese Gleichnisse vollendet hatte, begab Er Sich von dannen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'Und kam in Seine Vaterstadt und lehrte sie in ihrer Synagoge, also daß sie staunten und sagten: Woher hat dieser solche Weisheit und Wunderkräfte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Ist Der nicht des Zimmermanns Sohn? Wird nicht Seine Mutter Maria genannt und Seine Brüder Jakobus und Joses, und Simon, und Judas?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'Und sind nicht Seine Schwestern alle bei uns? Woher kommt Ihm denn alles dies?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'Und sie ärgerten sich an Ihm. Jesus aber sprach zu ihnen: Ein Prophet ist nicht ohne Ehre, außer in seiner Vaterstadt und in seinem Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'Und Er tat daselbst nicht viele Wundertaten um ihres Unglaubens willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'Zu der Zeit hörte Herodes, der Vierfürst, das Gerücht von Jesus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'Und er sprach zu seinen Knechten: Dies ist Johannes, der Täufer. Der ist von den Toten auferweckt, und darum wirken solche Wunderkräfte ihn Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Denn Herodes hatte lassen Johannes ergreifen, ihn binden und ins Gefängnis legen wegen der Herodias, des Weibes seines Bruders Philippus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Denn Johannes sagte ihm: Es ist dir nicht erlaubt, daß du sie habest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'Und da er ihn töten wollte, fürchtete er sich vor dem Volke, denn sie hielten ihn für einen Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Da sie aber das Geburtsfest des Herodes begingen, tanzte die Tochter der Herodias in ihrer Mitte und gefiel dem Herodes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'Darum beteuerte er mit einem Eide, ihr zu geben, um was sie nur bitten würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Sie aber, von ihrer Mutter angetrieben, spricht: Gib mir her auf einer Platte das Haupt Johannes, des Täufers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'Und der König ward betrübt, aber wegen des Eides und derer, die mit zu Tische lagen, befahl er, es ihr zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'Und er schickte hin und ließ Johannes im Gefängnis enthaupten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'Und sein Haupt ward auf einer Platte gebracht und dem Mägdlein gegeben, und sie brachte es ihrer Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'Und seine Jünger kamen herbei, hoben den Leib auf und begruben ihn, und kamen, und sagten es Jesus an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Und wie Jesus das hörte, entwich Er von dannen in einem Schiff an einen wüsten Ort besonders. Und als das Gedränge es hörte, folgten sie Ihm zu Fuß aus den Städten nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'Und als Er ausstieg, sah Er das viele Gedränge, und es jammerte Ihn derselben, und Er heilte ihre Siechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Als es aber Abend ward, kamen Seine Jünger zu ihm und sprachen: Der Ort ist wüste, und die Stunde ist schon vergangen. Entlasse das Gedränge, daß sie in die Flecken hingehen und sich Speise kaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Jesus aber sprach zu ihnen: Sie haben nicht nötig, wegzugehen. Gebt ihr ihnen zu essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Sie aber sagten zu Ihm: Wir haben nichts hier, denn fünf Brote und zwei Fische.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'Er aber sprach: Bringt sie zu Mir hierher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Und Er befahl dem Volke, sich auf das Gras hinzulegen, nahm die fünf Brote und die zwei Fische, blickte auf zum Himmel, dankte, brach und gab den Jüngern die Brote, die Jünger aber dem Volke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'Und es aßen alle und wurden satt, und sie hoben auf, was übrigblieb an Brocken, zwölf volle Körbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Die aber gegessen hatten, waren bei fünftausend Männer, ohne Weiber und Kinder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'Und alsbald nötigte Jesus die Jünger in das Fahrzeug einzusteigen und vor Ihm hinüberzufahren, bis daß Er das Volk entlassen hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'Und nachdem Er das Volk entlassen, stieg Er auf den Berg besonders, um zu beten. Als es aber Abend ward, war Er daselbst allein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Das Fahrzeug aber war schon mitten auf dem Meer und litt Not von den Wellen; denn der Wind war entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Aber um die vierte Wache der Nacht kam Jesus hin zu ihnen, wandelnd auf dem Meere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'Und da die Jünger Ihn auf dem Meere wandeln sahen, erbebten sie und sagten: Es ist ein Gespenst; und schrien auf vor Furcht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Alsbald aber redete Jesus zu ihnen und sprach: Seid getrost, Ich bin es! Fürchtet euch nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Petrus aber antwortete Ihm und sprach: Herr, bist Du es, so befiehl mir, zu Dir auf das Wasser zu kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'Er aber sprach: Komm! Und Petrus stieg hinab aus dem Fahrzeug und wandelte auf dem Wasser, um zu Jesus zu kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Da er aber den starken Wind sah, fürchtete er sich, und da er anfing, zu versinken, schrie er und sprach: Herr, rette mich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Alsbald aber reckte Jesus die Hand aus, ergriff ihn und sprach zu ihm: Kleingläubiger, warum zweifeltest du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'Und als sie ins Schiff eingestiegen waren, legte sich der Wind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Die im Fahrzeug aber kamen, beteten Ihn an und sprachen: Du bist wahrlich Gottes Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'Und sie fuhren hinüber und kamen in das Land Gennesaret.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'Und als die Leute an selbigem Orte Ihn erkannten, sandten sie in jene ganze Umgegend aus und brachten alle Leidende zu Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'Und flehten Ihn an, daß sie nur Seines Kleides Saum berührten, und so viele Ihn berührten, wurden gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Da kamen die Schriftgelehrten und Pharisäer aus Jerusalem herbei zu Jesus und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Warum übertreten Deine Jünger die Überlieferung der Ältesten? Denn sie waschen ihre Hände nicht, wenn sie Brot essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'Er aber antwortete und sprach zu ihnen: Warum übertretet auch ihr das Gebot Gottes, um eurer Überlieferung willen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Denn Gott hat geboten und gesagt: Ehre Vater und Mutter; und wer Vater oder Mutter flucht, der soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Ihr aber sagt: Wer zum Vater oder zur Mutter sagt: Es ist eine Gabe, was du von mir zum Nutzen gehabt hättest; der wird sicherlich nicht seinen Vater oder seine Mutter ehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'Und ihr habt so das Gebot Gottes um eurer Überlieferung willen ungültig gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Ihr Heuchler, schön hat von euch Jesajas geweissagt und gesprochen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, 'Es nahet Mir dieses Volk mit dem Munde und ehret Mich mit den Lippen; aber ihr Herz ist weit weg von Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Aber vergeblich verehren sie Mich, weil sie solche Lehre lehren, die Gebote der Menschen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'Und Er rief das Volk zu Sich und sprach zu ihnen: Höret und verstehet es!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Nicht was zum Munde eingeht, macht den Menschen gemein, sondern was vom Munde ausgeht, das macht den Menschen gemein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Da kamen Seine Jünger herbei und sagten zu Ihm: Weißt Du, daß die Pharisäer, da sie das Wort hörten, sich ärgerten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'Er aber antwortete und sprach: Jegliche Pflanze, die Mein himmlischer Vater nicht gepflanzt hat, wird ausgereutet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Lasset sie. Sie sind blinde Wegweiser der Blinden. Wenn aber ein Blinder einem Blinden den Weg weiset, werden beide in die Grube fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Petrus aber antwortete und sprach zu Ihm: Deute uns dieses Gleichnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Er aber sprach: Dann seid auch ihr unverständig?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Begreifet ihr noch nicht, daß alles, was zum Munde eingeht, das geht in den Bauch, und wird in den Abzug geworfen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Was aber vom Munde ausgeht, das kommt aus dem Herzen, und das macht den Menschen gemein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Denn aus dem Herzen kommen hervor schlechte Gedanken, Morde, Ehebrüche, Buhlereien, Diebereien, falsche Zeugnisse, Lästerungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'Das ist es, was den Menschen gemein macht; das Essen mit ungewaschenen Händen aber macht den Menschen nicht gemein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'Und Jesus ging aus von dannen und entwich in die Gegend von Tyrus und Sidon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'Und siehe, ein kanaanitisches Weib kam von jenen Grenzen heraus, schrie Ihm laut zu und sprach: Erbarme Dich meiner, Herr, Du Sohn Davids, meine Tochter ist übel besessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'Er aber antwortete ihr kein Wort. Und Seine Jünger kamen zu Ihm, baten Ihn und sagten: Entlasse sie; denn sie schreit uns nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'Er aber antwortete und sprach: Ich bin nur abgesandt zu den verlorenen Schafen des Hauses Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Sie aber kam, fiel vor Ihm nieder und sprach: Herr, hilf mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'Er aber antwortete und sprach: Es ist nicht schön, daß man der Kinder Brot nehme, und werfe es vor die Hündchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Sie aber sprach: Ja, Herr, und doch essen die Hündchen von den Brosamen, die von ihrer Herren Tische fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Da antwortete Jesus und sprach zu ihr: O Weib, dein Glaube ist groß. Dir geschehe, wie du willst. Und ihre Tochter ward gesund zur selbigen Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'Und Jesus ging weiter von dannen und kam an das Meer von Galiläa und stieg auf den Berg hinauf und setzte Sich allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'Und es kam zu Ihm viel Volks, und sie hatten mit sich Lahme, Blinde, Stumme, Krüppel und viele andere und warfen sie dahin zu Seinen Füßen, und Er heilte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'So daß sich das Volk verwunderte, da sie sahen Stumme reden, Krüppel gesund werden, Lahme wandeln und Blinde sehen; und sie verherrlichten den Gott Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Jesus aber rief Seine Jünger herbei und sprach: Mich jammert des Volkes, daß sie nun schon drei Tage bei Mir verharren und nichts zu essen haben; und ungegessen will Ich sie nicht von Mir lassen, auf daß sie nicht auf dem Wege verschmachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'Und Seine Jünger sprechen zu Ihm: Woher soll uns in der Wüste so viel Brot werden, um so viel Volk zu sättigen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'Und Jesus spricht zu ihnen: Wie viele Brote habt ihr? Sie aber sagten: Sieben und einige Fischlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'Und Er befahl dem Volk, sich auf die Erde niederzulassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'Und Er nahm die sieben Brote und die Fische, dankte, brach sie und gab sie Seinen Jüngern, die Jünger aber dem Volke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'Und sie aßen alle und wurden satt; und hoben auf das übrige der Brocken, sieben volle Weidenkörbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Die aber gegessen hatten, waren viertausend Männer ohne die Weiber und Kinder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Und da Er das Volk entlassen hatte, stieg Er ein in das Fahrzeug und kam in die Grenzen von Magdala.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'Und die Pharisäer und Sadduzäer kamen herzu, Ihn zu versuchen, und baten, daß Er ihnen ein Zeichen vom Himmel zeige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'Er antwortete ihnen aber und sprach: Wenn es Abend wird, sprechet ihr: Gut Wetter! denn der Himmel rötet sich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'Und am Morgen: Sturmwetter heute! denn der Himmel rötet sich und ist düster. Ihr Heuchler, das Aussehen des Himmels wisset ihr zu unterscheiden, aber die Zeichen der Zeit könnet ihr nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Ein arges und ehebrecherisches Geschlecht sucht ein Zeichen; und es soll ihm kein Zeichen gegeben werden, als das Zeichen Jonas, des Propheten. Und Er verließ sie und ging weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'Und als Seine Jünger hinüberkamen, hatten sie vergessen, Brote mit sich zu nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Jesus aber sprach zu ihnen: Sehet zu, daß ihr euch vor dem Sauerteig der Pharisäer und Sadduzäer in acht nehmet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Sie aber bedachten bei sich und sagten: Das ist es, daß wir kein Brot mit uns genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Jesus aber erkannte es und sagte: Was bedenket ihr bei euch, ihr Kleingläubigen, daß ihr kein Brot mit euch genommen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Begreifet ihr noch nicht? Gedenket ihr nicht der fünf Brote für die Fünftausend, und wieviel Körbe ihr aufnahmet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'Auch nicht an die sieben Brote für die Viertausend, und wieviel Weidenkörbe ihr da aufnahmet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Wie? Begreifet ihr nicht, daß Ich nicht wegen dem Brote zu euch sagte, ihr sollet euch vor dem Sauerteig der Pharisäer und Sadduzäer in acht nehmen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Jetzt verstanden sie, daß Er ihnen nicht sagte, sie sollten sich vor dem Sauerteig des Brotes in acht nehmen, sondern vor der Lehre der Pharisäer und Sadduzäer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Da Jesus aber in die Gegend von Cäsarea Philippi kam, fragte Er Seine Jünger und sagte: Wer sagen die Menschen, daß des Menschen Sohn sei?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Sie aber sagten: Die einen sagen, Du seist Johannes der Täufer, andere aber Elias; aber andere, Jeremias, oder der Propheten einer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Spricht Er zu ihnen: Wer sagt aber ihr, daß Ich sei?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Simon Petrus aber antwortete und sprach: Du bist Christus, der Sohn des lebendigen Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'Und Jesus antwortete und sprach zu ihm: Selig bist du, Simon Bar Jona; denn Fleisch und Blut hat dir das nicht geoffenbart, sondern Mein Vater in den Himmeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Und Ich aber sage dir: Du bist Petrus, und auf diesen Felsen werde Ich Meine Kirche bauen, und die Tore der Hölle sollen sie nicht überwältigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'Und Ich will dir die Schlüssel des Reiches der Himmel geben; und was du auf Erden binden wirst, das soll in den Himmeln gebunden sein; und was du auf Erden lösen wirst, das soll in den Himmeln gelöst sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Da verbot Er Seinen Jüngern, sie sollten niemand sagen, daß Er Jesus der Christus sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Von da an fing Jesus an, Seinen Jüngern zu zeigen, daß Er müßte hingehen nach Jerusalem, und von den Ältesten und Hohenpriestern und Schriftgelehrten vieles leiden, und getötet werden und am dritten Tage auferweckt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'Und Petrus nahm Ihn zu sich und fing an, Ihn zu bedrohen und sprach: Herr, schone Dich! das geschehe Dir nur nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'Er aber wandte Sich und sagte zu Petrus: Gehe hinweg, hinter Mich, Satan, du bist mir ein Ärgernis, denn du sinnest nicht, was von Gott sondern was von Menschen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Dann sprach Jesus zu Seinen Jüngern: Wer Mir folgen will, verleugne sich selbst, und nehme sein Kreuz auf sich und folge Mir nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Denn wer seine Seele retten will, der wird sie verlieren; wer aber seine Seele verliert um Meinetwillen, der wird sie finden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Denn was nützete es dem Menschen, so er die ganze Welt gewönne, nähme aber Schaden an seiner Seele? Oder was kann der Mensch geben zur Lösung seiner Seele?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Denn des Menschen Sohn wird kommen in der Herrlichkeit Seines Vaters mit Seinen Engeln, und dann wird Er einem jeglichen nach seinem Tun vergelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Wahrlich, Ich sage euch: Es sind welche, die hier stehen, die den Tod nicht schmecken werden, bis daß sie des Menschen Sohn in Seinem Reiche kommen sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'Und nach sechs Tagen nimmt Jesus zu Sich Petrus und Jakobus und Johannes, seinen Bruder, und bringt sie hinauf auf einen hohen Berg besonders.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'Und Er ward verwandelt vor Ihnen, und Sein Angesicht leuchtete wie die Sonne, und Seine Kleider wurden weiß wie das Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'Und siehe, es erschien ihnen Moses und Elias, und sie unterredeten sich mit Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Petrus aber antwortete und sprach zu Jesus: Herr, hier ist uns gut sein. Wenn Du willst, so wollen wir hier drei Hütten machen, Dir eine, und Moses eine, und Elias eine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Während er noch redete, siehe, da überschattete sie eine lichte Wolke; und siehe, eine Stimme aus der Wolke sprach: Dies ist Mein geliebter Sohn, an Dem Ich Wohlgefallen habe: Ihn sollt ihr hören!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Und da das die Jünger hörten, fielen sie auf ihr Angesicht und fürchteten sich sehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'Jesus aber kam herzu und berührte sie und sprach: Stehet auf und fürchtet euch nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Als sie aber ihre Augen aufhoben, sahen sie niemand als Jesus allein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'Und wie sie vom Berge herabstiegen, gebot ihnen Jesus und sprach: Saget niemand von dem Gesichte, bis daß des Menschen Sohn von den Toten auferstanden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'Und Seine Jünger fragten Ihn und sprachen: Was sagen denn die Schriftgelehrten, daß Elias zuvor kommen müsse?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'Jesus aber antwortete und sprach zu ihnen: Elias kommt zwar zuerst, und wird alles herstellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Aber Ich sage euch: Elias ist schon gekommen; und sie erkannten ihn nicht, sondern taten mit ihm, was sie wollten. Also wird auch des Menschen Sohn von ihnen leiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Da verstanden die Jünger, daß Er zu ihnen von Johannes dem Täufer sprach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'Und da sie zum Gedränge kamen, kam ein Mensch zu Ihm, fiel vor Ihm auf die Knie,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'Und sprach: Herr, erbarme Dich meines Sohnes; denn er ist mondsüchtig und hat ein böses Leiden; denn oft fällt er ins Feuer, und oft ins Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'Und ich brachte ihn zu Deinen Jüngern, und sie konnten ihn nicht heilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Jesus aber antwortete und sprach: O ihr ungläubiges und verkehrtes Geschlecht, wie lange soll Ich bei euch sein? Wie lange soll Ich euch ertragen? Bringet Mir ihn her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'Und Jesus bedrohte ihn, und der Dämon fuhr aus von ihm. Und der Knabe war geheilt von selbiger Stunde an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Da kamen die Jünger zu Jesus besonders und sprachen: Warum konnten wir ihn nicht austreiben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'Jesus aber sprach zu ihnen: Eures Unglaubens wegen; denn wahrlich, Ich sage euch, wenn ihr Glauben habt wie ein Senfkorn, so möget ihr zu diesem Berge sagen: Versetze dich von hinnen dorthin, so wird er sich versetzen, und nichts wird euch unmöglich sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Diese Gattung aber fährt nur durch Beten und Fasten aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Während sie aber in Galiläa umherwandelten, sprach Jesus zu ihnen: Es wird geschehen, daß des Menschen Sohn in die Hände der Menschen überantwortet wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'Und sie werden Ihn töten, aber am dritten Tage wird Er auferweckt werden. Und sie wurden sehr betrübt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Als sie aber nach Kapernaum kamen, kamen die, so die Doppeldrachmen einnahmen, herzu zu Petrus und sprachen: Entrichtet euer Lehrer die Doppeldrachme?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Er sagt: Ja. Und als er ins Haus hineinkam, kam ihm Jesus zuvor und sprach: Was meinst du, Simon? Von wem nehmen die Könige der Erde Zoll oder Steuer? Von ihren Söhnen, oder von den Fremden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Spricht zu Ihm Petrus: Von den Fremden. Da sprach Jesus zu ihm: Also sind die Söhne frei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Damit wir sie aber nicht ärgern, gehe du ans Meer, wirf die Angel und nimm den ersten Fisch, der heraufsteigt, tue ihm den Mund auf und du wirst einen Stater finden. Nimm ihn und gib ihnen den für Mich und für dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Zur selben Stunde kamen die Jünger zu Jesus und sagten: Wer ist wohl der Größte im Reiche der Himmel?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'Und Jesus rief eine Kindlein zu Sich und stellte es in ihre Mitte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'Und sprach: Wahrlich, Ich sage euch: Wenn ihr nicht umkehret und werdet wie die Kindlein, so werdet ihr mitnichten in das Reich der Himmel kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Wer nun sich selbst erniedrigt, wie dieses Kindlein, der ist der Größte im Reich der Himmel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'Und wer aufnimmt ein solches Kindlein in Meinem Namen, der nimmt Mich auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Wer aber ärgert einen dieser Kleinen, die an Mich glauben, dem wäre zuträglicher, daß ein Eselsmühlstein an seinen Hals gehängt und er versenkt würde in des Meeres Tiefe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Wehe der Welt, der Ärgernisse halben. Es ist wohl notwendig, daß Ärgernisse kommen; aber wehe demselbigen Menschen, durch den das Ärgernis kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Ärgert dich aber deine Hand, oder dein Fuß, so haue sie ab und wirf sie von dir; es ist dir besser, lahm oder ein Krüppel zum Leben einzugehen, als daß du zwei Hände oder zwei Füße habest und werdest ins ewige Feuer geworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'Und so dein Auge dich ärgert, reiß es aus und wirf es von dir: es ist dir besser, einäugig zum Leben einzugehen, als daß du zwei Augen habest und werdest in die Hölle des Feuers geworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Sehet zu, daß ihr nicht einen dieser Kleinen verachtet; denn Ich sage euch, ihre Engel schauen allezeit in den Himmeln das Angesicht Meines Vaters in den Himmeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Denn des Menschen Sohn ist gekommen, das Verlorene zu retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Was meint ihr? Wenn ein Mensch hundert Schafe hätte, und eines davon geht irre, würde er nicht die neunundneunzig auf den Bergen lassen und hingehen und suchen, das da irre gegangen ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'Und wenn es sich begibt, daß er dasselbe findet, wahrlich, Ich sage euch: er freut sich über demselben mehr, als über die neunundneunzig, die nicht irre gegangen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'So ist es nicht der Wille vor eurem Vater in den Himmeln, daß eines dieser Kleinen verloren werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Sündigt aber dein Bruder gegen dich, so gehe hin und rüge ihn zwischen dir und ihm allein. Hört er auf dich, so hast du deinen Bruder gewonnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Hört er aber nicht auf dich, so nimm noch einen oder zwei mit dir, auf daß die ganze Rede auf zweier oder dreier Zeugen Mund bestehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Hört er aber auch sie nicht, so sage es der Gemeinde. Hört er aber auch auf die Gemeinde nicht, so sei er dir wie der Heide und der Zöllner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Wahrlich, Ich sage euch: Was ihr auf Erden binden werdet, das soll im Himmel gebunden sein, und was ihr auf Erden lösen werdet, soll auch im Himmel gelöst sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Wiederum sage Ich euch: Wenn zwei von euch auf Erden übereinstimmen über irgendeine Sache, um was sie bitten, so soll es ihnen geschehen von Meinem Vater in den Himmeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Denn wo zwei oder drei versammelt sind in Meinem Namen, da bin Ich mitten unter ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Da kam Petrus zu Ihm und sprach: Wie oft mag mein Bruder wider mich sündigen, und ich ihm vergeben? Bis zu sieben Mal?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Spricht zu ihm Jesus: Ich sage dir, nicht bis zu sieben Mal, sondern bis zu siebzig mal sieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Darum ist das Reich der Himmel gleich einem Menschen, einem Könige, der mit seinen Knechten Rechnung abhalten wollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'Da er aber anfing abzurechnen, ward einer vor ihn gebracht, ein Schuldner von zehntausend Talenten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Da er aber nicht hatte, zu bezahlen, befahl sein Herr, ihn und sein Weib und die Kinder und alles, das er hatte, zu verkaufen und zu bezahlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Da fiel denn der Knecht nieder, betete ihn an und sprach: Herr, habe Langmut mit mir, und ich will dir alles bezahlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Da jammerte es aber den Herrn desselbigen Knechts, und er gab ihn los und vergab ihm das Anlehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Wie aber dieser Knecht hinauskam, fand er einen seiner Mitknechte, der ihm hundert Denare schuldete; und er ergriff ihn, würgte ihn und sprach: Bezahle mir, was du mir schuldig bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Der Mitknecht fiel denn nieder, flehte ihn an und sprach: Habe Langmut mit mir, und ich will dir alles bezahlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'Er aber wollte nicht, sondern ging hin und warf ihn ins Gefängnis, bis daß er bezahlete, was er schuldig war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Da aber seine Mitknechte sahen, was geschehen war, wurden sie sehr betrübt, und sie gingen und berichteten ihrem Herrn alles, was geschehen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Da rief ihn sein Herr zu sich und sprach zu ihm: Du schlechter Knecht, ich habe dir alle jene Schuld vergeben, weil du mich anflehtest;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'Hättest du nicht auch Erbarmen mit deinem Mitknechte haben sollen, wie auch ich mich deiner erbarmte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'Und sein Herr ward zornig und überantwortete ihn den Peinigern, bis daß er alles bezahlete, was er ihm schuldete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'So wird auch Mein himmlischer Vater euch tun, wenn ihr nicht vergebet von eurem Herzen ein jeglicher seinem Bruder seine Fehler.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'Und es geschah, als Jesus diese Worte vollendet hatte, begab Er Sich aus Galiläa und kam in die Grenzen Judäas jenseits des Jordans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'Und es folgte Ihm viel Volk nach, und Er heilte sie daselbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'Und es kamen herzu zu Ihm die Pharisäer, versuchten Ihn und sagten zu Ihm: Ist es dem Menschen erlaubt, aus jeglicher Ursache sich von seinem Weibe zu scheiden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'Er aber antwortete und sprach zu ihnen: Habt ihr nicht gelesen, daß Er, Der sie von Anfang gemacht hat, sie als Mann und Weib gemacht hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'Und Er sprach: Darum soll der Mensch Vater und Mutter verlassen und seinem Weibe anhangen. Und die zwei werden ein Fleisch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'So daß sie nicht mehr zwei, sondern ein Fleisch sind. Was nun Gott zusammengefügt, daß soll der Mensch nicht trennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Sprechen sie zu Ihm: Warum hat dann Moses geboten, einen Scheidebrief zu geben und sie zu entlassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Er spricht zu ihnen: Um eurer Hartherzigkeit willen hat euch Moses gestattet, eure Weiber zu entlassen; von Anfang an aber ist es nicht also gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Ich sage euch aber: Wer sein Weib entläßt, es sei denn um der Buhlerei willen, und eine andere freit, der bricht die Ehe, und wer eine Geschiedene freit, bricht die Ehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Sprechen zu Ihm Seine Jünger: Ist die Sache des Menschen mit dem Weibe so, dann ist es nicht zuträglich, zu freien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'Er aber sprach zu ihnen: Nicht alle fassen dieses Wort, sondern die, denen es gegeben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'Denn es sind Verschnittene, die von der Mutter Leib so geboren wurden, und sind Verschnittene, die von den Menschen verschnitten wurden, und sind Verschnittene, die um des Reiches der Himmel willen sich selbst verschnitten haben. Wer es fassen kann, der fasse es!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Da wurden Kindlein zu Ihm gebracht, auf daß Er die Hände auf sie legete und betete; die Jünger aber bedrohten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Jesus aber sprach: Lasset die Kindlein und wehret ihnen nicht zu Mir zu kommen; denn solcher ist das Reich der Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'Und da Er die Hände auf sie gelegt, zog Er von dannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'Und siehe, es kam einer herzu und sprach zu Ihm: Guter Lehrer, was soll ich Gutes tun, auf daß ich ewiges Leben habe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'Er aber sagte ihm: Was heißest du Mich gut? Niemand ist gut, denn der eine Gott. Willst du aber ins Leben eingehen, so halte die Gebote.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Er spricht zu Ihm: Welche? Jesus aber sprach: Das: du sollst nicht morden; du sollst nicht ehebrechen; du sollst nicht stehlen; du sollst kein falsch Zeugnis geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'Ehre Vater und Mutter; und du sollst deinen Nächsten lieben, wie dich selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Spricht zu Ihm der Jüngling: Alles das habe ich gehalten von meiner Jugend auf. Was mangelt mir noch?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jesus sprach zu ihm: Wenn du willst vollkommen sein, gehe hin, verkaufe, was du hast, und gib den Armen, und du wirst einen Schatz im Himmel haben, und komm her, folge Mir nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Als aber der Jüngling das Wort hörte, ging er betrübt weg; denn er hatte viel Besitztum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Jesus aber sprach zu Seinen Jüngern: Wahrlich, Ich sage euch: Es ist schwer, daß ein Reicher ins Reich der Himmel eingehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Wiederum aber sage Ich euch: Es ist leichter, daß ein Kamel durch ein Nadelöhr durchgehe, denn daß ein Reicher ins Reich Gottes eingehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'Da aber die Jünger das hörten, staunten sie sehr und sagten: Wer kann dann gerettet werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jesus aber blickte sie an und sprach zu ihnen: Bei Menschen ist dies unmöglich, bei Gott aber sind alle Dinge möglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Da antwortete Petrus und sprach zu Ihm: Siehe, wir haben alles verlassen und sind dir nachgefolgt. Was wird uns wohl werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jesus aber sprach zu ihnen: Wahrlich, Ich sage euch, daß ihr, die ihr Mir seid nachgefolgt in der Wiedergeburt, wenn des Menschen Sohn sitzen wird auf dem Throne Seiner Herrlichkeit, auch ihr sitzen werdet auf zwölf Thronen und richten die zwölf Stämme Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'Und jeder, der Häuser, oder Brüder, oder Schwestern, oder Vater, oder Mutter, oder Weib, oder Kinder, oder Felder verläßt um Meines Namens willen, der soll es hundertfältig empfangen und das ewige Leben ererben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'Aber viele, welche Erste sind, werden Letzte, und Letzte werden Erste sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Denn das Reich der Himmel ist gleich einem Menschen, einem Hausherrn, der mit dem Morgen ausging, Arbeiter in seinen Weinberg zu dingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'Er ward aber mit den Arbeitern eins über einen Denar den Tag, und sandte sie aus in seinen Weinberg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'Und um die dritte Stunde ging er aus und sah andere müßig im Markte stehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'Und derselbe sprach: Gehet auch ihr hin in den Weinberg, und was gerecht ist, will ich euch geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'Sie aber gingen hin. Um die sechste und die neunte Stunde ging er wieder aus und tat gleich also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Als er aber um die elfte Stunde ausging, fand er andere müßig stehen und sprach zu ihnen: Was steht ihr so den ganzen Tag mü-ßig?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Sie sagen zu ihm: Es hat uns niemand gedungen. Sagt er zu ihnen: Gehet auch ihr hin in den Weinberg, und was gerecht ist, sollt ihr empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Als es Abend geworden, spricht der Herr des Weinbergs zu seinem Schaffner: Rufe die Arbeiter und gib ihnen den Lohn, und fange bei den letzten an bis zu den ersten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'Als die von der elften Stunde kamen, empfingen sie jeder seinen Denar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Da aber die ersten kamen, dachten sie, sie würden mehr empfangen; aber auch sie empfingen jeder seinen Denar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Wie sie aber den empfingen, murrten sie wider den Hausherrn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'Und sagten: Die letzten da haben nur eine Stunde gearbeitet, und du hast sie uns gleich gemacht, die des Tages Bürde und Hitze getragen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'Er aber antwortete und sprach zu einem von ihnen: Gesell, ich bin dir nicht ungerecht, bist du nicht mit mir um einen Denar eins geworden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Nimm das Deine und gehe hin; ich will aber diesem letzten geben wie auch dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Oder ist mir nicht erlaubt, mit dem Meinen zu tun, was ich will? Ist dein Auge arg, weil ich gut bin?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'So werden die Letzten Erste, und die Ersten Letzte sein; denn viele sind berufen, aber wenige sind auserwählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'Und Jesus zog hinauf nach Jerusalem, und nahm die zwölf Jünger besonders zu Sich auf dem Wege und sagt zu ihnen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Siehe, wir ziehen nach Jerusalem hinauf, und des Menschen Sohn wird den Hohenpriestern und Schriftgelehrten überantwortet werden, und sie werden Ihn zum Tode verdammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'Und sie werden Ihn den Heiden überantworten, zu verspotten und zu geißeln und zu kreuzigen; und am dritten Tage wird Er auferstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Da kam die Mutter der Söhne des Zebedäus mit ihren Söhnen zu Ihm, fiel vor Ihm nieder und bat etwas von Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'Er aber sprach zu ihr: Was willst du? Sie spricht zu Ihm: Sage, daß diese meine zwei Söhne sitzen in Deinem Reiche, der eine zu Deiner Rechten, der andere zu Deiner Linken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Jesus aber antwortete und sprach: Ihr wisset nicht, um was ihr bittet. Könnt ihr den Kelch trinken, den Ich trinken werde, oder getauft werden mit der Taufe, da Ich mit getauft werde? Sie sprechen zu Ihm: Wir können es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Und Er spricht zu ihnen: Meinen Kelch sollt ihr trinken, und mit der Taufe, mit der Ich getauft werde, sollt ihr getauft werden; aber das Sitzen zu Meiner Rechten und zu Meiner Linken ist nicht Mein zu geben, außer denen, welchen es von Meinem Vater bereitet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'Und als die zehn das hörten, wurden sie unwillig über die zwei Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Jesus aber rief sie zu Sich und sprach: Ihr wisset, daß die Obersten der Völkerschaften herrschen über sie und die Großen Gewalt üben über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'So soll es nicht sein unter euch; sondern wer unter euch will groß werden, der soll euer Diener sein,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'Und wer unter euch will der Erste sein, der sei euer Knecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Wie des Menschen Sohn nicht gekommen ist, Sich dienen zu lassen, sondern zu dienen und Sein Leben zur Lösung zu geben für viele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'Und als sie von Jericho auszogen, folgte Ihm viel Volk nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'Und siehe, zwei Blinde saßen am Wege, und da sie hörten, daß Jesus vorübergehe, schrien sie und sprachen: Erbarme Dich unser, Herr, Du Sohn Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Das Volk aber bedrohte sie, daß sie stilleschweigen sollten. Sie aber schrien umso mehr: Ach, Herr, Du Sohn Davids, erbarme Dich unser!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'Und Jesus blieb stehen und rief ihnen und sprach: Was wollt ihr, daß Ich euch tun soll?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Sie sprachen zu Ihm: Herr, daß unsere Augen aufgetan werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Es jammerte aber Jesus, und Er berührte ihre Augen; und alsbald wurden ihre Augen sehend, und sie folgen Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'Und als sie sich Jerusalem nahten und nach Bethphage an den Ölberg kamen, da sandte Jesus zwei Jünger aus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'Und sprach zu ihnen: Gehet hin in den Flecken, der euch gegenüber ist, und alsbald werdet ihr eine Eselin finden angebunden, und ein Füllen bei ihr. Löset sie und führet sie zu Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'Und wenn euch jemand etwas sagt, sollt ihr sagen: Der Herr bedarf ihrer; alsbald aber wird er sie senden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'Alles dies geschah, auf daß erfüllt würde, was durch den Propheten gesagt ist, der da spricht:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, 'Saget der Tochter Zion: Siehe, dein König kommt zu dir sanftmütig und reitet auf einem Esel und auf einem Füllen, dem Sohn eines Lasttiers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'Die Jünger aber gingen hin und taten, wie ihnen Jesus verordnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'Sie führten die Eselin und das Füllen herbei und legten ihre Kleider auf sie, und Er setzte Sich darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Die meisten vom Volke aber streuten ihre Kleider auf den Weg; andere aber schnitten Zweige von den Bäumen und streuten sie auf den Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'Das Volk aber, das voranzog, und das nachfolgte, schrie und sprach: Hosianna dem Sohne Davids! Gesegnet sei, Der da kommt in dem Namen des Herrn! Hosianna in den Höhen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'Und als Er in Jerusalem einzog, ward die ganze Stadt bewegt und sagte: Wer ist Der?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Das Volk aber sagte: Das ist Jesus, der Prophet aus Nazareth in Galiläa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'Und Jesus ging hinein in das Heiligtum Gottes und trieb aus alle Verkäufer und Käufer im Heiligtum und stieß die Tische der Wechsler um und die Stühle derer, die Tauben verkauften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'Und spricht zu ihnen: Es ist geschrieben: Mein Haus soll ein Bethaus heißen; ihr aber machtet es zu einer Räuberhöhle!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'Und es kamen zu Ihm Blinde und Lahme in das Heiligtum, und Er heilte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Da aber die Hohenpriester und die Schriftgelehrten die Wunder sahen, die Er tat, und die Kinder im Heiligtum schreien und sagen: Hosianna dem Sohne Davids!, wurden sie unwillig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'Und sprachen zu Ihm: Hörst Du, was diese sagen? Jesus aber sprach zu ihnen: Ja, habt ihr nie gelesen: aus dem Munde der Unmündigen und Säuglinge hast Du Dir Lob zugerichtet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'Und Er verließ sie und ging hinaus aus der Stadt nach Bethanien und übernachtete allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Als Er aber am Morgen wieder in die Stadt ging, hungerte Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'Und da Er einen Feigenbaum am Wege sah, ging Er auf denselben zu und fand nichts an ihm, denn allein Blätter, und spricht zu ihm: Nimmer werde Frucht aus dir in Ewigkeit! Und sogleich verdorrte der Feigenbaum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'Und da es die Jünger sahen, verwunderten sie sich und sprachen: Wie ist der Feigen- baum so bald verdorrt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jesus aber antwortete und sprach zu ihnen: Wahrlich, Ich sage euch: So ihr Glauben habt, und zweifelt nicht, so werdet ihr nicht nur solches mit dem Feigenbaum tun; sondern so ihr zu diesem Berge sprechet: Hebe dich auf und wirf dich ins Meer, so wird es geschehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'Und alles, was ihr bitten werdet im Gebet, so ihr glaubet, werdet ihr es empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'Und als Er in das Heiligtum kam, kamen zu Ihm, als Er lehrte, die Hohenpriester und die Ältesten des Volkes und sprachen: Aus was für Gewalt tust Du das? Und wer hat Dir diese Gewalt gegeben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jesus aber antwortete und sprach zu ihnen: Ich will euch auch ein Wort fragen; wenn ihr Mir es sagt, werde Ich euch auch sagen, aus welcher Gewalt Ich dies tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Die Taufe des Johannes, woher war sie? Vom Himmel oder von Menschen? Sie aber bedachten bei sich und sagten: Wenn wir sprechen: Vom Himmel, so wird Er zu uns sagen: Warum habt ihr ihm denn nicht geglaubt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Sagen wir aber: Von Menschen, so fürchten wir das Volk; denn alle halten den Johannes für einen Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'Und sie antworteten Jesus und sagten: Wir wissen es nicht. Da sprach auch Er zu ihnen: Dann sage Ich euch auch nicht, aus was für Gewalt Ich dies tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Was meint ihr aber? Ein Mensch hatte zwei Kinder, und er ging herzu zum ersten und sagte: Kind, geh heute hin und arbeite in meinem Weinberg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'Der antwortete aber und sprach: Ich will nicht. Danach reute es ihn aber, und er ging hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'Und er kam herzu zum zweiten und sprach ebenso. Der aber antwortete und sprach: Ja,, Herr, und ging nicht hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Welcher von den zweien hat den Willen des Vaters getan? Sie sprachen zu Ihm: Der erste. Spricht Jesus zu ihnen: Wahrlich, Ich sage euch: Die Zöllner und Buhlerinnen kommen vor euch ins Reich Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Denn Johannes kam zu euch auf dem Wege der Gerechtigkeit, und ihr glaubtet ihm nicht; die Zöllner aber und die Buhlerinnen glaubten ihm; ihr aber sahet es und es reute euch nicht danach, so daß ihr ihm geglaubt hättet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Höret ein anderes Gleichnis. Es war ein Mensch, ein Hausherr, der pflanzte einen Weinberg und umgab ihn mit einem Zaun, grub darin eine Kelter, und baute einen Turm, und gab ihn an Weingärtner aus und zog über Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Als aber die Jahreszeit der Früchte nahte, sandte er seine Knechte aus an die Weingärtner, um seine Früchte zu empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'Die Weingärtner aber nahmen seine Knechte, stäupten den einen, den andern aber töteten sie, einen andern aber steinigten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Wiederum sandte er andere Knechte ab, mehr denn der ersten waren. Und sie taten ihnen gleich also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Danach sandte er seinen eigenen Sohn an sie und sagte: Vor meinen Sohn werden sie sich scheuen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Als die Weingärtner aber den Sohn sahen, sprachen sie untereinander: Dies ist der Erbe, kommet, lasset uns ihn töten und sein Erbe für uns behalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Und sie nahmen ihn, warfen ihn zum Weinberg hinaus und töteten ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Wenn nun der Herr des Weinberges kommt, was wird er diesen Weingärtnern tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Sie sprachen zu ihm: Er wird die Bösen böse verderben und den Weinberg an andere Weingärtner ausgeben, die ihm in ihren Jahreszeiten die Früchte übergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Spricht Jesus zu ihnen: Habt ihr nie in den Schriften gelesen: Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein geworden? Vom Herrn ist das geworden und ist wunderbar vor unseren Augen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Darum sage Ich euch: Das Reich Gottes wird von euch weggenommen und einer Völkerschaft gegeben werden, die seine Früchte bringt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'Und wer auf diesen Stein fällt, wird zerschellt werden, auf den er aber fällt, den wird er zerschmettern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'Und da die Hohenpriester und Pharisäer Seine Gleichnisse hörten, erkannten sie, daß Er von ihnen sprach;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'Und da sie suchten, Ihn zu ergreifen, fürchteten sie sich vor dem Gedränge, da es Ihn für einen Propheten hielt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'Und Jesus antwortete und sprach wiederum in Gleichnissen zu ihnen und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Das Reich der Himmel ist gleich einem Menschen, einem Könige, der seinem Sohne Hochzeit machte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'Und er sandte seine Knechte aus, um zu rufen die zur Hochzeit Berufenen, und sie wollten nicht kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Wiederum sandte er andere Knechte aus und sprach: Saget den Berufenen: Siehe, mein Mahl habe ich bereitet, meine Ochsen und das Mastvieh sind geschlachtet und alles bereit. Kommet zur Hochzeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Aber sie achteten nicht darauf und gingen hin, der eine auf sein eigenes Feld, der andere seinem Handel nach;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Die übrigen aber ergriffen seine Knechte, beschimpften und töteten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Als der König aber das hörte, ward er zornig und schickte seine Heere aus, brachte die Mörder um und verbrannte ihre Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Dann spricht er zu seinen Knechten: Die Hochzeit ist zwar bereit, aber die Berufenen waren es nicht wert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'So gehet denn an die Kreuzwege der Straßen und rufet, wen ihr findet, zur Hochzeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'Und jene Knechte gingen aus auf die Wege, versammelten alle, die sie fanden, Schlechte und Gute, und die Hochzeit war voll derer, die zu Tische lagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Als der König aber hineinkam, um anzusehen, die zu Tische lagen, sah er daselbst einen Menschen, der hatte keine hochzeitliche Kleidung angetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'Und er spricht zu ihm: Geselle, wie bist du hier hereingekommen und hast keine hochzeitliche Kleidung? Er aber verstummte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Da sprach der König zu den Dienern: Bindet ihm Füße und Hände, werfet ihn in die äußerste Finsternis hinaus; da wird sein Weinen und Zähneknirschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Denn viele sind berufen, aber wenige sind auserwählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Da gingen die Pharisäer hin und hielten Beratung, wie sie Ihn im Worte verstrickten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'Und sandten ihre Jünger aus mit den Herodianern zu Ihm, die sprachen: Lehrer, wir wissen, daß Du wahrhaftig bist und den Weg Gottes in Wahrheit lehrst und Dich um niemand kümmerst; denn Du siehst nicht auf das Angesicht der Menschen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'So sage uns denn, was dünkt Dich? Ist es erlaubt, daß man dem Kaiser die Steuer gebe, oder nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Jesus aber erkannte ihre Bosheit und sprach: Was versucht ihr Mich, ihr Heuchler?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Zeigt Mir die Münze der Steuer. Sie aber brachten Ihm einen Denar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'Und Er spricht zu ihnen: Wessen Bild und Überschrift ist dies?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Sie sagten zu Ihm: Des Kaisers. Da spricht Er zu ihnen: So gebt denn dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'Und wie sie das hörten, verwunderten sie sich, verließen Ihn und gingen weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'An demselben Tage kamen die Sadduzäer zu Ihm, die da sagen, es sei keine Auferstehung, und fragten Ihn:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'Lehrer, Moses hat gesagt: Wenn einer stirbt und hat keine Kinder, so soll sein Bruder sein Weib zur Schwiegerehe nehmen und seinem Bruder Samen erwecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Es waren aber bei uns sieben Brüder; und der erste freite und starb, und da er keinen Samen hatte, ließ er sein Weib seinem Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Desgleichen auch der zweite, und der dritte, bis zum siebenten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Zuletzt nach allen starb auch das Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Bei der Auferstehung nun, wessen Weib unter den sieben wird sie sein? Denn alle haben sie gehabt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jesus aber antwortete und sprach zu ihnen: Ihr irret, da ihr nicht wisset die Schriften, noch die Kraft Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Denn bei der Auferstehung freien sie nicht, noch lassen sie sich freien, sondern sind wie die Engel Gottes im Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Wegen der Auferstehung der Toten aber, habt ihr nicht gelesen, was euch von Gott gesagt wird, Der da spricht:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, 'Ich bin der Gott Abrahams, und der Gott Isaaks und der Gott Jakobs? Gott ist nicht ein Gott der Toten, sondern der Lebendigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'Und als das Volk dies hörte, staunte es über Seine Lehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Als aber die Pharisäer hörten, wie Er die Sadduzäer zum Verstummen gebracht hatte, versammelten sie sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'Und einer von ihnen, ein Gesetzlehrer, fragte Ihn, um Ihn zu versuchen, und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Lehrer, welches ist das große Gebot im Gesetz?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Jesus aber sprach zu ihm: Du sollst den Herrn deinen Gott lieben mit deinem ganzen Herzen und mit deiner ganzen Seele und mit deinem ganzen Gemüte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Dies ist das erste und große Gebot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Das zweite aber ist ihm ähnlich: Du sollst deinen Nächsten lieben, wie dich selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'An diesen zwei Geboten hängt das ganze Gesetz und die Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Als aber die Pharisäer versammelt waren, fragte sie Jesus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'Und sagte: Was dünkt euch von Christus? Wessen Sohn ist Er?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Sie sagten zu Ihm: Davids. Spricht Er zu ihnen: Wie heißt ihn dann David im Geiste Herr, wenn er sagt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, 'Der Herr sprach zu meinem Herrn: Setze Dich zu Meiner Rechten, bis daß Ich Deine Feinde zum Schemel Deiner Füße lege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Wenn nun David Ihn Herr heißt, wie ist Er sein Sohn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'Und niemand konnte Ihm ein Wort antworten; auch wagte von dem Tage an niemand mehr, Ihn zu fragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Da redete Jesus zu dem Volk und zu Seinen Jüngern,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'Und sagte: Auf Moses Stuhl sitzen die Schriftgelehrten und die Pharisäer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Alles nun, was sie euch sagen, daß ihr halten sollet, das haltet und tut; nach ihren Werken aber tut nicht; denn sie sagen es, tun es aber nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Sie binden schwere und kaum erträgliche Lasten und legen sie auf der Menschen Schultern; sie aber wollen sie mit keinem Finger regen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Alle ihre Werke aber tun sie, um von den Leuten angesehen zu werden. Sie machen ihre Denkzettel breit und vergrößern die Säume an ihren Kleidern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'Sie haben gern den ersten Platz bei Gastmählern, und die ersten Sitze in den Synagogen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'Und die Begrüßungen auf den Märkten, und daß die Menschen sie Rabbi, Rabbi hei-ßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Aber ihr sollt euch nicht Rabbi nennen lassen; denn Einer ist euer Lehrmeister, Christus; ihr alle aber seid Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'Und ihr sollt niemand auf Erden euren Vater heißen; denn Einer ist euer Vater, Der in den Himmeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Auch Lehrmeister sollt ihr euch nicht heißen lassen; denn Einer ist euer Lehrmeister, Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'Aber der Größte unter euch soll euer Deiner sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Wer sich aber selbst erhöht, der wird erniedrigt, und wer sich selbst erniedrigt, der wird erhöht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Ihr verschließet das Reich der Himmel vor den Menschen; denn ihr kommt nicht hinein; und die hineingehen möchten, lasset ihr nicht hineingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Wehe aber euch Schriftgelehrte und Pharisäer, ihr Heuchler; denn ihr esset der Witwen Häuser auf und machet zum Vorwand lange Gebete, dafür werdet ihr ein noch schwerer Gericht empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler; denn ihr durchziehet das Meer und das Trockene, um einen einzigen Proselyten zu machen; und wenn er es geworden ist, macht ihr ihn zu einem Sohn der Hölle, doppelt mehr, als ihr selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Wehe euch, blinde Wegweiser, die ihr sprecht: Wer beim Tempel schwört, das ist nichts; wer aber beim Golde des Tempels schwört, der schuldet es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Ihr Narren und Blinde! Was ist den größer? das Gold oder der Tempel, der das Gold heiligt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'Und: Schwört einer beim Altar, so ist es nichts; schwört er aber bei der Gabe, die darauf ist, so schuldet er es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Ihr Narren und Blinde! Was ist denn größer, die Gabe oder der Altar, der die Gabe heiligt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Wer denn bei dem Altar schwört, schwört bei ihm und bei allem, was darauf ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'Und wer beim Tempel schwört, der schwört bei ihm und Dem, Der darin wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'Und wer bei dem Himmel schwört, der schwört bei dem Throne Gottes und bei Dem, Der darauf sitzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Ihr verzehntet Minze und Anis und Kümmel; das Schwerere des Gesetzes, das Gericht, und die Barmherzigkeit und den Glauben habt ihr verlassen. Dies sollte man tun und das andere nicht lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Blinde Wegweiser, die ihr Mücken wegseihet, aber Kamele verschlinget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Ihr reinigt das Äußere des Kelches und der Schüssel; inwendig aber sind sie voll Raubes und Unmäßigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Blinder Pharisäer, reinige zuerst das Innere des Kelches und der Schüssel, auf daß auch das Äußere derselben rein werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Wehe, euch Schriftgelehrte und Pharisäer, ihr Heuchler; denn ihr gleicht übertünchten Grabstätten, die auswendig schön erscheinen, inwendig aber voller Totengebeine und aller Unreinigkeit sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'So erscheint auch ihr von außen den Menschen als gerecht, indes ihr inwendig erfüllt seid von Heuchelei und Unrecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Wehe euch, Schriftgelehrte und Pharisäer, ihr Heuchler! Ihr baut die Grabstätten der Propheten und schmückt die Grüfte der Gerechten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'Und sprechet: Wären wir in den Tagen unserer Väter gewesen, so wären wir nicht mit ihnen Teilhaber am Blute der Propheten gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Damit bezeugt ihr selber, daß ihr Söhne der Mörder der Propheten seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Und ihr erfüllt das Maß eurer Väter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Ihr Schlangen, ihr Geschlecht der Ottern, wie solltet ihr dem Gerichte der Hölle entfliehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Darum siehe, Ich sende aus an euch Propheten und Weise und Schriftgelehrte, und ihr werdet derer etliche töten und kreuzigen, und etliche davon in euren Synagogen geißeln und verfolgen von Stadt zu Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'Auf daß über euch komme all das gerechte Blut, das vergossen ist auf Erden, vom Blute des gerechten Abel bis auf das Blut Zacharias, des Sohnes von Barachjas, den ihr zwischen dem Tempel und dem Altar gemordet habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Wahrlich, Ich sage euch, solches alles wird kommen über dies Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jerusalem, Jerusalem, die du tötest die Propheten und steinigst, die zu dir gesandt werden! Wie oft habe Ich deine Kinder versammeln wollen, wie eine Henne ihre Küchlein unter die Flügel versammelt, und ihr habt nicht gewollt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Siehe, euer Haus wird euch wüste gelassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Denn Ich sage euch: Ihr werdet Mich von jetzt an nicht mehr sehen, bis ihr sprechet: Gesegnet sei, der da kommt im Namen des Herrn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'Und Jesus ging hinaus und ging weg von dem Heiligtum, und Seine Jünger kamen herzu, um Ihm die Gebäude des Heiligtums zu zeigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'Jesus aber sprach zu ihnen: Sehet ihr nicht alles dies? Wahrlich, Ich sage euch: Kein Stein wird hier auf dem Steine gelassen, der nicht niedergerissen würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Als Er Sich aber auf dem Ölberg niedergesetzt hatte, kamen die Jünger zu Ihm besonders und sprachen: Sage uns, wann dies sein wird, und was das Zeichen Deiner Ankunft und der Vollendung des Zeitlaufes sein wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'Und Jesus antwortete und sprach zu ihnen: Sehet zu, daß euch niemand irreführe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Denn viele werden kommen unter Meinem Namen und sagen: Ich bin Christus, und werden viele irreführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Ihr werdet aber von Kriegen und Kriegserüchten hören; sehet zu, daß euch nicht bange wird; denn das muß alles geschehen; aber noch ist das Ende nicht da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Denn es wird erweckt werden Völkerschaft wider Völkerschaft, und Königreich wider Königreich. Und es wird an verschiedenen Orten Hungersnot und Pestilenz und Erdbeben sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Alles dies aber ist nur der Anfang der Wehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Alsdann werden sie euch in Trübsal überantworten, und euch töten; und ihr werdet von allen Völkerschaften gehaßt werden um Meines Namens willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'Und viele werden Ärgernis nehmen und einander überantworten und einander hassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'Und viele falsche Propheten werden erweckt werden und viele irreführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'Und weil das Unrecht sich mehrt, wird die Liebe vieler erkalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Wer aber beharrt bis ans Ende, der wird errettet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'Und dieses Evangelium vom Reiche wird im ganzen Erdkreis gepredigt werden zum Zeugnis über alle Völkerschaften, und dann wird das Ende kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Wenn ihr nun sehen werdet den Greuel der Verwüstung, von dem durch den Propheten Daniel gesagt ist, am heiligen Orte stehen wer es liest, der merke auf;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'Dann sollen die, so in Judäa sind, fliehen auf die Berge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'Wer auf dem Dache ist, steige nicht hinab, etwas aus seinem Hause zu nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'Und wer auf dem Felde ist, kehre nicht um hinter sich, seine Kleider zu nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Wehe aber den Schwangeren und den Säugenden in jenen Tagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Betet aber, daß eure Flucht nicht im Winter oder am Sabbath geschehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Denn dann wird große Trübsal sein, wie sie seit Anfang der Welt bis jetzt nicht war, und auch nicht werden wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'Und würden diese Tage nicht verkürzt, so würde kein Fleisch gerettet werden; aber um der Auserwählten willen werden diese Tage verkürzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Wenn dann einer euch sagen wird: Siehe, hier ist Christus, oder da, so glaubt es nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Denn es werden falsche Christi und falsche Propheten auftreten und große Zeichen und Wunder geben, so daß, wenn es möglich wäre, sie selbst die Auserwählten irreführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Siehe, Ich habe es euch vorhergesagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Wenn sie euch dann sagen: Siehe, in der Wüste ist Er! so geht nicht hinaus; siehe, in den Kammern ist Er, so glaubt es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Denn wie der Blitz ausgeht vom Aufgang und scheint bis zum Niedergang, so wird auch die Ankunft des Menschen Sohnes sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Denn wo das Aas ist, da sammeln sich die Adler.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Alsbald aber nach der Trübsal jener Tage wird die Sonne verfinstert werden, und der Mond seinen Schein nicht geben, und die Sterne werden vom Himmel fallen, und die Kräfte der Himmel werden erschüttert werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'Und dann wird das Zeichen des Menschen Sohnes im Himmel erscheinen, und dann werden alle Stämme der Erde jammern und des Menschen Sohn kommen sehen auf den Wolken des Himmels mit Kraft und großer Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'Und Er wird Seine Engel aussenden mit großer Posaunenstimme, und sie werden Seine Auserwählten zusammenversammeln aus den vier Winden von einem Ende der Himmel bis an das andere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Vom Feigenbaum aber lernt das Gleichnis: Wenn sein Zweig schon saftig wird und die Blätter hervortreibt, erkennt ihr, daß der Sommer nahe ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'So sollt auch ihr, wenn ihr alles dies seht, erkennen, daß es nahe vor der Tür ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Wahrlich, Ich sage euch, dies Geschlecht wird mitnichten vergehen, bis daß dies alles geschehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Himmel und Erde werden vergehen, aber Meine Worte werden nicht vergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Von jenem Tag und der Stunde aber weiß niemand, auch die Engel in den Himmeln nicht, sondern allein Mein Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Wie die Tage Noachs waren, so wird auch die Ankunft des Menschen Sohnes sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Denn wie sie waren in den Tagen vor der Sündflut: sie aßen und tranken, sie freiten und ließen freien bis zu dem Tage, da Noach in die Arche einging,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'Und erkannten es nicht, bis die Sündflut kam und sie alle wegnahm: so wird auch die Ankunft des Menschen Sohnes sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Dann werden zwei auf dem Felde sein, der eine wird angenommen, der andere gelassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Zwei mahlen in der Mühle; die eine wird angenommen, die andere gelassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'So wachet denn: weil ihr nicht wisset, zu welcher Stunde euer Herr kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Das aber erkennet, daß, wenn der Hausherr wüßte, um welche Nachtwache der Dieb kommt, er wohl wachte und ihn nicht ins Haus einbrechen ließe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Deshalb seid auch ihr bereit; denn des Menschen Sohn kommt zu einer Stunde, da ihr es nicht meinet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Wer ist wohl der treue und kluge Knecht, den sein Herr über sein Gesinde setzte, um ihnen zur rechten Zeit die Nahrung zu geben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Selig ist jener Knecht, den sein Herr, wenn er kommt, findet also tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Wahrlich, Ich sage euch: Er wird ihn über alle seine Habe setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'So aber jener böse Knecht spricht in seinem Herzen: Mein Herr verziehet zu kommen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'Und fängt an, seine Mitknechte zu schlagen, und zu essen und zu trinken mit den Trunkenen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'So wird der Herr jenes Knechtes kommen an einem Tage, an dem er es nicht erwartet, und zu einer Stunde, die er nicht erkennt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'Und wird ihn zerscheitern und ihm sein Teil mit den Heuchlern anweisen. Da wird sein Weinen und Zähneknirschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Dann ist das Reich der Himmel zehn Jungfrauen zu vergleichen, die ihre Lampen nahmen und ausgingen, dem Bräutigam entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Fünf derselben aber waren klug und fünf töricht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Die töricht waren, nahmen ihre Lampen, aber sie nahmen kein Öl mit sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Die klugen aber nahmen Öl in ihren Gefäßen mit ihren Lampen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Da aber der Bräutigam verzog, nickten alle ein und schlummerten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Um Mitternacht aber ward ein Geschrei: Siehe, der Bräutigam kommt, zieht aus, ihm entgegen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Da erwachten alle diese Jungfrauen und schmückten ihre Lampen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Die törichten aber sprachen zu den klugen: Gebt uns von eurem Öl, denn unsre Lampen erlöschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Die klugen aber antworteten und sagten: Nicht doch! da möchte es uns und euch nicht genügen. Geht vielmehr zu denen, die es verkaufen, und kauft euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Während sie aber hingingen zu kaufen, kam der Bräutigam; und die bereit waren, gingen mit ihm zur Hochzeit ein und die Tür ward verschlossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Danach kamen auch die übrigen Jungfrauen und sagten: Herr, Herr! Tue uns auf!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'Er aber antwortete und sprach: Wahrlich, ich sage euch, ich kenne euch nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Wachet also, denn ihr wisset den Tag und die Stunde nicht, da des Menschen Sohn kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'So wie ein Mensch, der über Land zog, seine eigenen Knechte rief und ihnen seine Habe übergab;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'Und dem einen gab er fünf Talente, einem aber zwei, einem aber ein Talent, jedem nach seinen eigenen Kräften, und zog alsbald über Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Der aber die fünf Talente empfangen hatte, ging hin und arbeitete damit und gewann fünf andere Talente.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Desgleichen auch der mit den zweien, und auch er gewann zwei andere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Der aber das eine empfangen hatte, ging hin und grub in der Erde, und verbarg das Silber seines Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Nach langer Zeit aber kommt der Herr dieser Knechte und hält mit ihnen Rechnung ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'Und es kam herzu, der die fünf Talente empfangen, und brachte fünf andere Talente dazu, und sprach: Herr, fünf Talente hast du mir übergeben; siehe, ich habe fünf andere Talente zu denselben gewonnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Sein Herr sprach zu ihm: Wohl, du guter und getreuer Knecht; du warst über weniges getreu, ich werde dich über vieles setzen; gehe ein zur Freude deines Herrn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Da kam aber auch herzu, der die zwei Talente empfangen hatte, und sprach: Herr, zwei Talente hast du mir übergeben; siehe, zwei andere Talente habe ich zu denselben gewonnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Sprach zu ihm sein Herr: Wohl, du guter und getreuer Knecht; du warst über weniges getreu, ich werde dich über vieles setzen. Gehe ein zur Freude deines Herrn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Da kam aber auch herzu, der das eine Talent empfangen hatte, und sprach: Herr, ich kannte dich, daß du ein harter Mensch bist, erntest, wo du nicht gesät, und sammelst, wo du nicht ausgestreut hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'Und ich fürchtete mich, ging hin, und verbarg dein Talent in der Erde; siehe, da hast du das deine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Sein Herr aber antwortete und sprach zu ihm: Du schlechter und träger Knecht! Wußtest du, daß ich ernte, wo ich nicht gesät, und sammle, wo ich nicht ausgestreut habe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'Du hättest denn sollen mein Silber bei den Wechslern einlegen; und bei meinem Kommen hätte ich das Meinige mit Zins zurückerhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Nehmt denn von ihm das Talent und gebt es dem, der zehn Talente hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Denn jedem, der da hat, wird gegeben, und er wird Überfluß haben; von dem aber, der nicht hat, von dem wird auch genommen, was er hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'Und den unnützen Knecht werfet hinaus in die äußerste Finsternis. Da wird sein Weinen und Zähneknirschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Wenn aber des Menschen Sohn in Seiner Herrlichkeit kommen wird, und alle die heiligen Engel mit Ihm, dann wird Er sitzen auf dem Thron Seiner Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'Denn alle Völkerschaften werden vor Ihm versammelt werden, und Er wird sie voneinander ausscheiden, wie der Hirte die Schafe von den Böcken ausscheidet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'Und Er wird die Schafe zu Seiner Rechten, die Böcke aber zu Linken stellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Dann wird der König zu denen auf Seiner Rechten sprechen: Kommt her, ihr Gesegneten Meines Vaters! Ererbet das Reich, das euch bereitet ist von der Gründung der Welt an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Denn Ich hungerte, und ihr gabt Mir zu essen. Ich dürstete, und ihr habt Mich getränkt. Ich war ein Fremdling, und ihr habt Mich aufgenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'Ich war nackt, und ihr habt Mich umkleidet, Ich war krank, und ihr besuchtet Mich. Ich bin im Gefängnis gewesen, und ihr seid zu Mir gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Dann werden Ihm die Gerechten antworten und sagen: Herr, wann sahen wir Dich hungrig und nährten Dich, oder durstig und tränkten Dich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Wann sahen wir Dich einen Fremdling und nahmen Dich auf? oder nackt und umkleideten Dich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Wann sahen wir Dich krank oder im Gefängnis und sind zu Dir gekommen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'Und der König wird ihnen antworten und sprechen: Wahrlich, Ich sage euch: Was ihr an einem der kleinsten dieser Meiner Brüder getan, das habt ihr Mir getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Dann wird Er zu denen auf der Linken sprechen: Geht hinweg von Mir, ihr Verfluchten, in das ewige Feuer, das bereitet ist dem Teufel und seinen Engeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Denn Ich war hungrig, und ihr gabt Mir nichts zu essen; Ich dürstete, und ihr tränktet Mich nicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'Ich war ein Fremdling, und ihr habt Mich nicht aufgenommen, nackt, und ihr habt Mich nicht umkleidet; krank, und im Gefängnis, und ihr habt Mich nicht besucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Dann werden auch sie antworten und sagen: Herr, wann sahen wir Dich hungrig oder durstig, oder fremd, oder nackt, oder krank oder im Gefängnis, und haben Dich nicht bedient?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Da wird Er ihnen antworten und sprechen: Wahrlich, Ich sage euch, was ihr dieser Kleinsten einem nicht getan, das habt ihr auch Mir nicht getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'Und sie werden hingehen zur ewigen Strafe; die Gerechten aber in das ewige Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'Und es geschah, da Jesus alle diese Worte vollendet hatte, sprach Er zu Seinen Jüngern:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Ihr wisset, daß nach zwei Tagen Pascha wird; und des Menschen Sohn wird überantwortet, daß Er gekreuzigt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Da versammelten sich die Hohenpriester und die Schriftgelehrten und die Ältesten des Volkes in dem Hof des Hohenpriesters, genannt Kaiaphas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'Und berieten sich, wie sie Jesus mit Trug ergriffen und töteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Sie sprachen aber: Nicht am Fest, damit nicht ein Getümmel werde unter dem Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Da Jesus aber in Bethanien, im Hause Simons des Aussätzigen war,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'Kam zu Ihm ein Weib, das hatte eine Alabasterbüchse kostbarer Salbe und goß sie über Sein Haupt, da Er zu Tische lag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Da das aber die Jünger sahen, wurden sie unwillig und sprachen: Wozu diese Verschwendung?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'Denn man hätte die Salbe um vieles verkaufen und es den Armen geben können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Da das Jesus erkannte, sprach Er zu ihnen: Was bietet ihr dem Weibe Ungelegenheiten? Denn ein gutes Werk hat sie an Mir gewirkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Denn die Armen habt ihr allezeit bei euch, Mich aber habt ihr nicht allezeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Daß sie diese Salbe auf Meinen Leib goß, das hat sie für Mein Begräbnis getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Wahrlich, Ich sage euch: Wo in der ganzen Welt dies Evangelium gepredigt wird, wird man auch reden von dem, was sie getan hat, zu ihrem Gedächtnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Da ging einer von den Zwölfen, genannt Judas Ischariot, hin zu den Hohenpriestern,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'Und sprach: Was wollt ihr mir geben, daß ich Ihn euch überantworte? Sie aber bestimmten ihm dreißig Silberlinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'Und von da an suchte er eine gute Gelegenheit, daß er Ihn verriete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Aber am ersten des Ungesäuerten kamen die Jünger zu Jesus und sagten: Wo willst Du, daß wir Dir bereiten, das Paschalamm zu essen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'Er aber sprach: Geht hin in die Stadt zu einem und sagt ihm: der Lehrer sagt: Meine Zeit ist nahe; bei dir halte Ich das Pascha mit Meinen Jüngern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'Und die Jünger taten, wie ihnen Jesus verordnet hatte, und bereiteten das Pascha.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Als es aber Abend geworden, legte Er Sich mit den Zwölfen zu Tisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'Und da sie aßen, sprach Er: Wahrlich, Ich sage euch: Einer von euch wird Mich verraten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'Und sie wurden sehr betrübt, fingen an, ein jeglicher von ihnen, zu Ihm zu sagen: Ich bin es doch nicht, Herr?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'Er aber antwortete und sprach: Der mit Mir die Hand in die Schale eintaucht, der wird Mich verraten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Des Menschen Sohn geht zwar dahin, wie es von Ihm geschrieben ist; aber wehe jenem Menschen, durch den des Menschen Sohn verraten wird. Es wäre solchem Menschen besser, er wäre nie geboren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Judas aber, der Ihn verriet, antwortete und sprach: Ich bin es doch nicht, Rabbi? Er spricht zu ihm: Du hast es gesagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Da sie aber aßen, nahm Jesus das Brot, und segnete, brach es, und gab es den Jüngern und sprach: Nehmet, esset, das ist Mein Leib!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'Und Er nahm den Kelch, dankte, und gab ihnen den und sprach: Trinket alle daraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'Denn das ist Mein Blut, das des Neuen Bundes, das für viele vergossen wird zur Vergebung der Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Aber Ich sage euch, Ich werde von nun an von diesem Gewächse des Weinstocks mitnichten trinken, bis zu dem Tage, da Ich es neu mit euch trinken werde in Meines Vaters Reiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'Und nach dem Lobgesang gingen sie hinaus an den Ölberg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Dann spricht Jesus zu ihnen: Ihr werdet euch in dieser Nacht alle an Mir ärgern; denn es ist geschrieben: Ich werde den Hirten schlagen und die Schafe der Herde werden sich zerstreuen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Wenn Ich aber auferweckt bin, werde Ich euch nach Galiläa vorangehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Petrus aber antwortete und sprach zu Ihm: Wenn sich auch alle an Dir ärgern, so will doch ich mich nimmermehr ärgern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jesus sprach zu ihm: Wahrlich, Ich sage dir, in dieser selben Nacht, ehe der Hahn kräht, wirst du Mich dreimal verleugnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Spricht zu Ihm Petrus: Und wenn ich auch mit Dir sterben müßte, werde ich Dich mitnichten verleugnen, desgleichen sprachen auch alle Jünger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Da kommt Jesus mit ihnen an einen Hof, Gethsemane genannt, und spricht zu den Jüngern: Setzet euch hier, indes Ich dort hingehe und bete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'Und Er nahm mit Sich Petrus und die zwei Söhne des Zebedäus und fing an Sich zu betrüben und zu zagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Dann spricht Er zu ihnen: Meine Seele ist tief betrübt bis in den Tod. Bleibet hier und wachet mit Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'Und Er ging ein wenig vor, fiel auf Sein Angesicht, betete und sprach: Mein Vater, so es möglich ist, laß diesen Kelch an Mir vorübergehen, doch nicht, wie Ich will, sondern wie Du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'Und Er kommt zu den Jüngern und findet sie schlummernd, und spricht zu Petrus: So vermochtet ihr denn nicht eine Stunde mit Mir zu wachen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Wachet und betet, auf daß ihr nicht in Versuchung kommt. Der Geist zwar ist willig, aber das Fleisch ist schwach,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Und Er ging wieder zum zweiten Male hin, betete und sprach: Mein Vater, kann dieser Kelch nicht an Mir vorübergehen, Ich trinke ihn denn, so geschehe Dein Wille!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'Und Er kommt und findet sie abermals schlummernd; denn die Augen waren ihnen beschwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'Und Er ließ sie und ging wieder hin und betete zum dritten Male, indem Er dieselben Worte sprach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Da kommt Er zu Seinen Jüngern und spricht zu ihnen: So schlummert denn ferner und ruhet aus. Siehe, die Stunde ist nahe, und des Menschen Sohn wird in die Hände der Sünder überantwortet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Macht euch auf, laßt uns gehen! Siehe, er ist nahe, der Mich verrät.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'Und als Er noch redete, siehe, da kam Judas, einer der Zwölfe, und mit ihm vieles Gedränge mit Schwertern und Knitteln von den Hohenpriestern und Ältesten des Volkes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Der Ihn verriet hatte ihnen aber ein Zeichen gegeben und gesagt: Der, Den ich küssen werde, Der ist es, Den ergreifet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'Und alsbald kam er zu Jesus herbei und sprach: Sei gegrüßt, Rabbi! und küßte Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jesus aber sprach zu ihm: Weshalb bist du hier, Geselle? Da kamen sie herzu, legten die Hände an Jesus und ergriffen Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'Und siehe, einer von denen, die bei Jesus waren, reckte die Hand aus, zog sein Schwert heraus und schlug des Hohenpriesters Knecht und hieb ihm das Ohr ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Da spricht Jesus zu ihm: Stecke dein Schwert an seinen Ort; denn alle, die das Schwert nehmen, sollen durch das Schwert umkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Oder meinst du, Ich könnte nicht eben jetzt Meinen Vater anflehen, und Er würde Mir mehr den zwölf Legionen Engel zustellen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Wie würden die Schriften dann erfüllt, daß es also geschehen muß?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'Zur selben Stunde sprach Jesus zu dem Gedränge: Wie gegen einen Räuber seid ihr gegen Mich mit Schwertern und Knitteln ausgezogen, um Mich zu fangen. Täglich saß Ich bei euch und lehrte im Heiligtum, und ihr habt Mich nicht ergriffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Dies alles aber ist geschehen, daß die Schriften der Propheten erfüllt würden. Da verließen Ihn alle Seine Jünger und flohen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Die aber Jesus ergriffen hatten, führten Ihn hin zum Hohenpriester Kaiaphas, wo sich die Schriftgelehrten und die Ältesten versammelt hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'Petrus aber folgte Ihm nach von weitem bis in den Hof des Hohenpriesters, ging hinein und setzte sich zu den Amtsdienern, um das Ende zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Die Hohenpriester aber und die Ältesten und der ganze Rat suchten falsches Zeugnis wider Jesus, um Ihn zum Tode zu bringen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'Und sie fanden keines; und obgleich viele falsche Zeugen herzukamen, fanden sie keines. Danach kamen aber zwei falsche Zeugen herzu und sagten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'Dieser hat gesagt: Ich kann den Tempel Gottes niederreißen und in drei Tagen ihn aufbauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'Und der Hohepriester stand auf und sprach zu Ihm: Antwortest Du nichts auf das, was diese wider Dich zeugen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Jesus aber schwieg stille. Und der Hohepriester antwortete und sprach zu Ihm: Ich beschwöre Dich bei Gott dem Lebendigen, daß Du uns sagst, ob Du Christus, der Sohn Gottes bist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Spricht zu ihm Jesus: Du hast es gesagt. Doch sage Ich euch: Hinfort werdet ihr des Menschen Sohn sitzen sehen zur Rechten der Kraft und kommen auf den Wolken des Himmels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Da zerriß der Hohepriester seine Kleider und sprach: Er hat gelästert. Was bedürfen wir noch Zeugen? Seht, nun habt ihr Seine Lästerung gehört!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Was dünkt euch? Sie aber antworteten und sprachen: Er ist des Todes schuldig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Da speieten sie Ihm ins Angesicht und schlugen Ihn mit Fäusten. Etliche aber gaben Ihm Backenstreiche,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'Und sprachen: Weissage uns, Christus! Wer hat dich geschlagen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Petrus aber saß draußen in dem Hof; und eine Magd kam zu ihm und sprach: Auch du warst mit Jesus, dem Galiläer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'Er aber leugnete vor allen und sprach: Ich weiß nicht, was du sagst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Als er aber in das Tor hinauskam, sah ihn eine andere und sagte zu denen, die daselbst waren: Auch der da war mit Jesus, dem Nazarener.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'Und er leugnete wiederum mit einem Schwur: Ich kenne den Menschen nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Ein wenig danach aber kamen die dort Stehenden herzu und sprachen zu Petrus: Wahrlich, auch du bist einer von ihnen, denn auch deine Sprache macht dich kennbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Da fing er an, sich zu verwünschen und zu schwören: Ich kenne den Menschen nicht. Und alsbald krähte der Hahn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'Und Petrus gedachte der Rede Jesu, da Er zu ihm sprach: Ehe der Hahn kräht, wirst du Mich dreimal verleugnen. Und er ging hinaus und weinte bitterlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Als es aber Morgen ward, hielten alle Hohenpriester und die Ältesten des Volkes eine Beratung über Jesus, daß sie Ihn zum Tode brächten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'Und sie banden Ihn, führten Ihn hin und überantworteten Ihn dem Landpfleger Pontius Pilatus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Da Judas, der Ihn verriet, sah, daß Er verurteilt war, reute es ihn, und er brachte die dreißig Silberlinge zurück den Hohenpriestern und den Ältesten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'Und sprach: Ich habe gesündigt, daß ich unschuldig Blut verraten. Sie aber sagten: Was geht das uns an? Sieh du zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'Und er warf die Silberlinge dahin in den Tempel, entwich, ging hin und erhängte sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Die Hohenpriester aber nahmen die Silberlinge und sprachen: Es ist nicht erlaubt, sie in den Opferkasten zu werfen, weil es Schatzung des Blutes ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Sie hielten aber eine Beratung und kauften damit den Töpferacker zu einem Begräbnis für Fremde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Daher jenes Feld bis auf den heutigen Tag der Blutacker heißt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Da wurde erfüllt, was durch den Propheten Jeremias gesprochen ist, der sagt: Und sie nahmen die dreißig Silberlinge, die Schatzung dessen, der schätzt wurde, den sie sich schätzen ließen von den Söhnen Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'Und gaben sie für den Töpferacker, wie mir der Herr verordnet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'Jesus aber stand vor dem Landpfleger, und der Landpfleger fragte Ihn und sprach: Bist Du der Juden König? Jesus aber sprach zu ihm: Du sagst es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'Und da Er verklagt ward von den Hohenpriestern und den Ältesten, antwortete Er nichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Da spricht Pilatus zu Ihm: Hörst Du nicht, was sie wider Dich zeugen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'Und Er antwortete ihm nicht auf eine Rede, also daß sich der Landpfleger ungemein verwunderte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Der Landpfleger hatte aber die Gewohnheit, dem Gedränge auf das Fest einen Gefangenen loszugeben, welchen sie wollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Sie hatten aber gerade einen besonderen Gefangenen, genannt Barabbas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Da sie nun versammelt waren, sprach Pilatus zu ihnen: Welchen wollt ihr, daß ich euch losgebe? Barabbas oder Jesus, Der da genannt wird Christus?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Denn er wußte, daß sie Ihn aus Neid überantwortet hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Indem er aber auf dem Richtstuhle saß, sandte sein Weib zu ihm und sagte: Habe du nichts zu tun mit diesem Gerechten; denn ich habe heute viel erlitten im Traum wegen Seiner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'Die Hohenpriester aber und die Ältesten überredeten das Gedränge, daß sie um Barabbas bitten sollten, Jesum aber umbrächten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Der Landpfleger aber antwortete und sprach zu ihnen: Welchen wollt ihr von den zweien, daß ich euch losgebe? Sie aber sprachen: Barabbas!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Spricht Pilatus zu ihnen: Was soll ich denn mit Jesus tun, Der Christus genannt wird? Sie sprachen alle: Er soll gekreuzigt werden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Der Landpfleger aber sprach: Was hat Er denn Böses getan? Sie aber schrien viel mehr und sprachen: Er soll gekreuzigt werden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Da Pilatus aber sah, daß es nicht nützte, sondern des Getümmels mehr ward, nahm er Wasser, wusch sich die Hände vor dem Gedränge und sprach: Ich bin unschuldig an dem Blute dieses Gerechten! Seht ihr zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'Und das ganze Volk antwortete und sprach: Sein Blut sei auf uns und unseren Kindern!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Da gab er ihnen Barabbas los, Jesus aber ließ er geißeln und überantwortete Ihn, daß Er gekreuzigt würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Da nahmen die Kriegsknechte des Landpflegers Jesus in das Richthaus und versammelten die ganze Kohorte über Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'Und sie zogen Ihn aus und legten Ihm einen Scharlachmantel um;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'Und sie flochten einen Krone von Dornen und setzten sie Ihm auf Sein Haupt, und ein Rohr in Seine Rechte, fielen auf das Knie vor Ihm und verspotteten Ihn und sagten: Sei gegrüßt, König der Juden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'Und speieten Ihn an und nahmen das Rohr und schlugen Ihn auf Sein Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'Und als sie Ihn verspottet hatten, zogen sie Ihm den Mantel aus, und taten Ihm Seine Kleider an und führten Ihn ab, daß sie Ihn kreuzigten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Indem sie aber hinauszogen, fanden sie einen Menschen von Kyrene mit Namen Simon; den nötigten sie, Sein Kreuz zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'Und als sie an den Ort kamen, genannt Golgatha, das heißt Schädelstätte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'Gaben sie Ihm Essig, mit Galle vermischt, zu trinken, und als Er es kostete, wollte Er nicht trinken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Als sie Ihn aber gekreuzigt hatten, verteilten sie Seine Kleider unter sich, indem sie das Los warfen; auf daß erfüllt würde, was durch den Propheten gesagt ist: Sie verteilten Meine Kleider unter sich, und warfen das Los über Meinen Rock.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'Und sie saßen da und bewachten Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'Und über Seinem Haupte setzten sie in einer Aufschrift die Ursache Seines Todes: Dies ist Jesus, der Juden König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Alsdann wurden mit Ihm gekreuzigt zwei Räuber, einer zur Rechten, und einer zur Linken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'Die aber vorübergingen, lästerten Ihn, indem sie ihre Köpfe schüttelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'Und sagten: Der Du den Tempel niederreißt und in drei Tagen aufbaust, rette Dich Selber! Wenn Du Gottes Sohn bist, so steige herab von dem Kreuz!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Desgleichen verspotteten Ihn auch die Hohenpriester mit den Schriftgelehrten und Ältesten und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Andere hat Er gerettet, Sich Selbst kann Er nicht retten! Wenn Er Israels König ist, so steige Er nun herab vom Kreuz, und wir wollen Ihm glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Er hat auf Gott vertraut! Der errette Ihn nun, wenn Er Ihn will. Denn Er hat gesagt: Ich bin Gottes Sohn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Ebenso aber schmähten Ihn auch die Räuber, die mit Ihm gekreuzigt waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Aber von der sechsten Stunde an ward Finsternis über das ganze Land bis zur neunten Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'Um die neunte Stunde aber schrie Jesus auf mit großer Stimme und sprach: Eli, Eli lama sabachthani, das ist: Mein Gott, Mein Gott, warum hat Du Mich verlassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'Einige aber der dort Stehenden, da sie es hörten, sagten: Er ruft den Elias herbei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'Und alsbald lief einer von ihnen und nahm einen Schwamm, füllte ihn mit Essig, legte ihn um ein Rohr und tränkte Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Die übrigen aber sagten: Halt, laß sehen, ob Elias kommt, Ihn zu retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Jesus aber schrie abermals mit großer Stimme und gab den Geist auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'Und siehe, der Vorhang des Tempels zerriß entzwei von oben bis unten, und die Erde bebte und die Felsen zerrissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'Und die Grüfte taten sich auf und viele Leiber der entschlafenen Heiligen wurden auferweckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'Und gingen aus von den Grüften und kamen nach Seiner Auferstehung herein in die heilige Stadt und erschienen vielen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Da aber der Hauptmann und die mit ihm Jesus bewachten sahen das Erdbeben und das, was geschah, fürchteten sie sich sehr und sprachen: Fürwahr, Dieser war Gottes Sohn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Es waren aber da viele Frauen, die von weitem zuschauten; die Jesus aus Galiläa nachgefolgt waren, um Ihm Dienste zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Und unter ihnen waren Maria von Magdala, und Maria, des Jakobus und des Joses Mutter und die Mutter der Söhne des Zebedäus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Als es aber Abend ward, kam ein reicher Mensch von Arimathäa, mit Namen Joseph, der auch ein Jünger Jesu war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Dieser ging herbei zu Pilatus und bat um den Leib Jesu. Da befahl Pilatus, daß der Leib ihm sollte übergeben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'Und Joseph nahm den Leib, wickelte ihn ein in reine Leinwand,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'Und legte ihn in seine neue Gruft, die er hatte in den Fels hauen lassen, und wälzte einen großen Stein vor die Tür zu der Gruft und ging weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Es war aber dort Maria von Magdala und die andere Maria, die saßen der Grabstätte gegenüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Am folgenden Tag aber, der nach dem Rüsttag ist, versammelten sich die Hohenpriester und die Pharisäer zu Pilatus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'Und sagten: Herr, wir erinnern uns, daß dieser Verführer, da Er noch lebte, gesagt hat: Nach drei Tagen werde Ich auferweckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'So befiehl denn, daß man sich der Grabstätte bis zum dritten Tag versichere, auf daß nicht Seine Jünger kommen, Ihn stehlen und dem Volke sagen: Er ist von den Toten auferweckt! und die letzte Verführung schlimmer werde als die erste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilatus sprach zu ihnen: Ihr sollt eine Wache haben, geht hin und versichert euch, wie ihr es wisset.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Sie aber gingen hin, versicherten sich der Grabstätte und mit der Wache versiegelten sie den Stein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Spät aber am Sabbath, als schon der erste Wochentag dämmern wollte, kam Maria von Magdala und die andere Maria, die Grabstätte zu beschauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'Und siehe, das geschah ein großes Erdbeben; denn der Engel des Herrn stieg vom Himmel herab, kam hinzu, wälzte den Stein weg von der Tür und setzte sich darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Er war aber anzusehen wie ein Blitz und sein Kleid weiß wie Schnee.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'Aber aus Furcht vor ihm erbebten, die es bewachten, und wurden wie tot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Der Engel aber hob an und sprach zu den Weibern: Fürchtet euch nicht; denn ich weiß, daß ihr Jesus den Gekreuzigten sucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Er ist nicht hier; denn Er ist auferweckt, wie Er gesagt hat. Kommt her, und seht den Ort, da der Herr gelegen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'Und geht schnell hin und sagt Seinen Jüngern, daß Er von den Toten auferweckt ist. Und siehe, Er geht vor euch hin nach Galiläa. Dort werdet ihr Ihn sehen. Siehe, ich habe es euch gesagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'Und sie gingen schnell hinaus von der Gruft mit Furcht und großer Freude und liefen, es Seinen Jüngern anzusagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'Wie sie aber hingingen, es Seinen Jüngern anzusagen, begegnete ihnen Jesus und sprach: Seid gegrüßt! Sie aber kamen herzu, ergriffen Seine Füße und beteten Ihn an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Da spricht Jesus zu ihnen: Fürchtet euch nicht! Geht hin und sagt Meinen Brüdern an, daß sie nach Galiläa hingehen, und dort werden sie Mich sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Während sie aber hingingen, siehe, da kamen einige von der Wache in die Stadt und sagten den Hohenpriestern an alles, was geschehen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'Und sie versammelten sich mit den Ältesten und faßten einen Beschluß und gaben den Kriegsknechten Silbers genug,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'Und sprachen: Sagt, Seine Jünger sind in der Nacht gekommen und haben Ihn gestohlen, während wir schliefen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'Und wenn der Landpfleger davon hört, wollen wir ihn überreden, und euch außer Sorge setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Sie aber nahmen die Silberlinge und taten, wie sie gelehrt waren. Und solches Wort ist bei den Juden ruchbar bis auf den heutigen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Die elf Jünger aber gingen hin nach Galiläa auf den Berg, wohin sie Jesus beschieden hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'Und da sie Ihn sahen, fielen sie vor Ihm nieder; einige aber zweifelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'Und Jesus kam zu ihnen, redete mit ihnen und sprach: Mir ist gegeben alle Gewalt im Himmel und auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Darum gehet hin und macht zu Jüngern alle Völkerschaften und taufet sie im Namen des Vaters und des Sohnes und des Heiligen Geistes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'Und lehret sie halten alles, was Ich euch geboten habe. Und siehe, Ich bin mit euch alle Tage bis zur Vollendung des Zeitlaufs. Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Anfang des Evangeliums von Jesus Christus, dem Sohne Gottes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Wie geschrieben ist im Propheten Jesajas: Siehe, Ich sende Meinen Engel aus vor Deinem Angesicht, der Deinen Weg zurüste vor Dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Die Stimme eines Rufenden in der Wüste: Bereitet den Weg des Herrn, machet gerade Seine Pfade.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'Johannes war in der Wüste, taufte und predigte die Taufe der Buße zur Vergebung der Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'Und es ging zu ihm hinaus die ganze judäische Landschaft und die von Jerusalem, und ließen sich alle von ihm taufen im Flusse Jordan, indem sie ihre Sünden bekannten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Johannes aber war bekleidet mit Kamelshaaren und mit einem ledernen Gürtel um seine Lenden und aß Heuschrecken und wilden Honig,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'Und predigte und sprach: Es kommt Einer nach mir, Der stärker ist, denn ich, und Dem ich nicht genugsam bin, mich zu bücken und den Riemen Seiner Schuhe zu lösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Ich zwar habe euch mit Wasser getauft; aber Er wird euch mit dem Heiligen Geiste taufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'Und in jenen Tagen geschah es, daß Jesus von Nazareth in Galiläa kam und Sich von Johannes im Jordan taufen ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'Und alsbald, als Er aus dem Wasser heraufstieg, sah Er die Himmel sich teilen und den Geist wie ein Taube auf Sich herniederkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'Und eine Stimme geschah aus den Himmeln: Du bist Mein geliebter Sohn, an Dem Ich Wohlgefallen habe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'Und alsbald trieb Ihn der Geist hinaus in die Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'Und Er war allda in der Wüste vierzig Tage, versucht von dem Satan, und Er war mit den wilden Tieren; und die Engel dienten Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Nachdem aber Johannes überantwortet war, kam Jesus nach Galiläa und predigte das Evangelium vom Reiche Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'Und sprach: Die Zeit ist erfüllt und das Reich Gottes hat sich genahet. Tut Buße und glaubet an das Evangelium.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Da Jesus aber am galiläischen Meer wandelte, sah Er Simon und Andreas, seinen Bruder, die ein Fischnetz im Meer ausbreiteten; denn sie waren Fischer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'Und Jesus sprach zu ihnen: Kommet Mir nach, und Ich will euch zu Menschenfischern machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'Und alsbald verließen sie ihre Netze und folgten Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'Und da Er von dannen ein wenig weiter ging, sah Er Jakobus, des Zebedäus Sohn, und Johannes, seinen Bruder, und sie richteten im Fahrzeug ihre Netze zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'Und alsbald rief Er ihnen. Und sie ließen ihren Vater Zebedäus in dem Fahrzeug mit den Mietlingen und gingen hin, Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'Und sie gingen hinein nach Kapernaum, und alsbald ging Er hinein am Sabbath in die Synagoge und lehrte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'Und sie staunten über Seine Lehre; denn Er lehrte sie als einer, der Gewalt hat, und nicht wie die Schriftgelehrten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'Und in ihrer Synagoge war ein Mensch mit einem unreinen Geist, und er schrie auf,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'Und sagte: Laß uns, was haben wir mit Dir Jesus von Nazareth? Du bist gekommen, uns zu verderben. Ich weiß, wer Du bist! - Der Heilige Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'Und Jesus bedrohte ihn und sprach: Verstumme und gehe aus von ihm!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'Und der unreine Geist zerrte ihn hin und her, schrie mit großer Stimme und ging aus von ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'Und alle waren bestürzt, so daß sie untereinander sich befragten und sprachen: Was ist das? Was für eine neue Lehre ist das? Mit Gewalt gebeut Er sogar den unreinen Geistern und sie gehorchen Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'Das Gerücht von Ihm ging aber alsbald aus in die ganze Umgegend von Galiläa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'Und sie gingen aus alsbald aus der Synagoge und kamen in das Haus des Simon und Andreas mit Jakobus und Johannes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Simons Schwiegermutter aber lag am Fieber danieder; und alsbald sagten sie Ihm von ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'Und Er kam herzu, richtete sie auf und ergriff sie bei ihrer Hand; und alsbald verließ sie das Fieber; und sie bediente sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Als es aber Abend ward, da die Sonne unterging, trugen sie alle die Leidenden und die Besessenen zu Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'Und die ganze Stadt sammelte sich zusammen an der Tür.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'Und Er heilte viele Leidende, mit allerlei Krankheiten; und Er trieb viele Dämonen aus, und ließ die Dämonen nicht reden, denn sie kannten Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'Und des Morgens, da es noch gar Nacht war, stand Er auf, ging hinaus und kam an einen wüsten Ort und betete daselbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'Simon aber, und die mit Ihm waren, setzten Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'Und da sie Ihn fanden, sagen sie zu Ihm: Alle suchen Dich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'Und Er spricht zu ihnen: Lasset uns in die benachbarten Dörfer gehen, auf daß Ich auch dort predige; denn dazu bin Ich ausgegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Und Er predigte in ihren Synagogen in ganz Galiläa und trieb die Dämonen aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'Und es kommt ein Aussätziger zu Ihm, fleht Ihn an und fällt zu Seinen Knien und spricht zu Ihm: Wenn Du willst, kannst Du mich reinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'Es jammerte aber Jesus, Er streckte die Hand aus, berührte ihn und sprach zu ihm: Ich will, sei gereinigt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'Und als Er so gesprochen, ging der Aussatz alsbald von ihm, und er war geeinigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'Und Er drohte ihm und trieb ihn alsbald hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'Und spricht zu ihm: Siehe zu, sage niemand etwas; sondern gehe hin, zeige dich dem Priester, und bringe dar für deine Reinigung, was Moses verordnet hat, ihnen zum Zeugnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'Da er aber hinauskam, fing er an, viel davon zu verkündigen und das Wort ruchbar zu machen, so daß Er hinfort nicht mehr öffentlich in eine Stadt eingehen konnte, sondern außen an wüsten Orten war; und sie kamen zu Ihm von überall her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'Und nach einigen Tagen ging Er wieder hinein nach Kapernaum, und man hörte, daß Er zu Hause war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'Und alsbald versammelten sich viele, so daß sie auch an der Tür nicht mehr Platz hatten, und Er redete zu ihnen das Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Und es kamen etliche zu Ihm, die brachten einen Gichtbrüchigen zu Ihm, von vieren getragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'Und da sie wegen dem Gedränge Ihm nicht nahe kommen konnten, deckten sie das Dach ab, wo Er war, und gruben es auf, und ließen das Tragbett hinab, auf dem der Gichtbrüchige daniederlag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Da aber Jesus ihren Glauben sieht, spricht Er zu dem Gichtbrüchigen: Mein Kind, dir sind deine Sünden vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Es waren aber allda einige von den Schriftgelehrten, die saßen und bedachten in ihren Herzen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Was redet dieser solche Lästerung! Wer kann Sünden vergeben, denn der Eine Gott?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'Und Jesus erkannte alsbald in Seinem Geiste, daß sie solches bei sich bedachten, und sprach zu ihnen: Was bedenket ihr solches in euren Herzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Was ist leichter zu dem Gichtbrüchigen zu sagen: Dir sind die Sünden vergeben, oder zu sagen: Mache dich auf, nimm dein Tragbett auf und wandle!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Damit ihr aber wisset, daß des Menschen Sohn Gewalt hat, auf Erden Sünden zu vergeben, [spricht Er zu dem Gichtbrüchigen]:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Ich sage dir: Mache dich auf, nimm dein Tragbett auf, und geh hin in dein Haus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'Und alsbald machte er sich auf, nahm sein Tragbett auf und ging vor allen hinaus, so daß sie alle außer sich waren, Gott verherrlichten und sprachen: So etwas haben wir noch nie gesehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'Und Er ging wieder hinaus an das Meer, und all das Gedränge kam zu Ihm, und Er lehrte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'Und wie Er vorüberging, sah Er Levi, des Alphäus Sohn, am Zoll sitzen, und spricht zu ihm: Folge Mir nach! Und er stand auf und folgte Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'Und da Er Sich zu Tische legte in seinem Hause, geschah es, daß auch viele Zöllner und Sünder mit Jesus und Seinen Jüngern zu Tische lagen; denn es waren ihrer viele, und sie folgten Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'Und da die Schriftgelehrten und Pharisäer sahen, daß Er mit Sündern und Zöllnern aß, sprachen sie zu Seinen Jüngern: Warum ißt und trinkt Er mit Sündern und Zöllnern?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'Und Jesus hört es und spricht zu ihnen: Die Starken bedürfen des Arztes nicht, sondern die Leidenden. Ich bin nicht gekommen, Gerechte, sondern Sünder zur Buße zu rufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Und die Jünger des Johannes und die Pharisäer waren am Fasten; und sie kommen und sprechen zu Ihm: Warum fasten die Jünger des Johannes und die der Pharisäer, Deine Jünger aber fasten nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'Und Jesus sagte zu ihnen: Können die Hochzeitsleute fasten, während der Bräutigam bei ihnen ist? Die Zeit, so sie den Bräutigam bei sich haben, können sie nicht fasten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Es werden aber Tage kommen, da der Bräutigam von ihnen weggenommen wird, und dann an jenem Tage werden sie fasten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Niemand näht einen Flecken ungewalkten Tuches auf ein altes Kleid. Sonst aber reißt das neue Füllwerk von alten ab, und der Riß wird schlimmer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'Und niemand fasset neuen Wein in alte Schläuche; sonst aber zerreißt der neue Wein die Schläuche und der Wein wird verschüttet und die Schläuche kommen um; sondern man muß den neuen Wein in neue Schläuche fassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'Und es geschah, daß Er am Sabbath durch die Saaten hinging; und Seine Jünger fingen an während des Gehens die Ähren auszuraufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Und die Pharisäer sprachen zu Ihm: Siehe, was tun sie am Sabbath, das nicht erlaubt ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'Und Er sprach zu ihnen: Habt ihr niemals gelesen, was David tat, da er es bedurfte und ihn, und die mit ihm waren, hungerte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Wie er in das Haus Gottes hineinging unter dem Hohenpriester Abjathar, und die Schaubrote aß, die niemandem erlaubt ist zu essen als den Priestern, und auch denen gab, die mit ihm waren?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'Und Er sprach zu ihnen: Der Sabbath ist um des Menschen willen gemacht, nicht der Mensch um des Sabbaths willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'So ist denn des Menschen Sohn Herr auch des Sabbaths.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'Und Er ging abermals hinein in die Synagoge; und es war da ein Mensch, der hatte eine verdorrte Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'Und sie hielten auf Ihn, ob Er ihn am Sabbath heilen würde, auf daß sie eine Anklage wider Ihn hätten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'Und Er spricht zu dem Menschen, der die verdorrte Hand hatte: Tritt hervor in die Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'Und Er spricht zu ihnen: Ist es erlaubt am Sabbath Gutes zu tun oder Böses zu tun, die Seele zu retten oder zu töten? Sie aber schwiegen still.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'Und Er blickte sie rings umher mit Zorn an und war betrübt über die Verstocktheit ihres Herzens; da sprach Er zu dem Menschen: Strecke deine Hand aus! Und er streckte sie aus, und seine Hand ward wiederhergestellt, gesund wie die andere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'Und die Pharisäer gingen hinaus und hielten alsbald mit den Herodianern einen Rat über Ihn, wie sie Ihn umbrächten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'Und Jesus entwich mit Seinen Jüngern ans Meer; und eine große Menge aus Galiläa folgte Ihm nach und von Judäa,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'Und von Jerusalem, und von Idumäa und jenseits des Jordan und von denen um Tyrus und Sidon kam eine große Menge zu Ihm, da sie hörten, was Er tat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'Und Er sagte Seinen Jüngern, sie sollten ein Schifflein für Ihn bereithalten, des Gedränges wegen, daß sie Ihn nicht drängeten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Denn Er heilte viele, so daß über Ihn herfielen, die Plagen hatten, auf daß sie Ihn anrührten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'Und die unreinen Geister, wenn sie Ihn schauten, fielen vor Ihm nieder, schrien und sagten: Du bist der Sohn Gottes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'Und Er bedrohte sie sehr, daß sie Ihn nicht sollten kundbar machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'Und Er stieg hinauf auf den Berg und rief zu Sich, welche Er wollte; und sie gingen zu Ihm hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'Und Er bestellte zwölf, daß sie bei Ihm wären, und daß Er sie aussendete, zu predigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'Und daß sie Gewalt hätten, die Krankheiten zu heilen und die Dämonen auszutreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Und dem Simon legte Er den Namen Petrus bei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'Und Jakobus, den Sohn des Zebedäus, und Johannes, den Bruder des Jakobus, und Er legte ihnen die Namen Boanerges, d.h. Donnersöhne bei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'Und Andreas und Philippus und Bartholomäus und Matthäus, und Thomas und Jakobus, des Alphäus Sohn, und Thaddäus und Simon, den Kananiten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'Und Judas Ischariot, der Ihn auch verriet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'Und sie gingen nach Hause; und es kam wieder ein Gedränge zusammen, also daß sie nicht einmal das Brot essen konnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'Als das die Seinigen hörten, gingen sie aus, Ihn zu ergreifen; denn, sagten sie, Er ist außer sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'Und die Schriftgelehrten, die von Jerusalem herabgekommen waren, sagten: Er hat den Beelzebul! und: Durch den Obersten der Dämonen treibt Er die Dämonen aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'Und Er rief sie zu Sich und sprach zu ihnen in Gleichnissen: Wie kann Satan den Satan austreiben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'Und wenn ein Reich wider sich selbst zerteilt wird, so kann solches Reich nicht bestehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'Und so ein Haus wider sich selbst zerteilt wird, so kann solches Haus nicht bestehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'So kann auch der Satan, wenn er wider sich selbst aufstünde und zerteilt wäre, nicht bestehen, sondern hätte ein Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Keiner kann dem Starken in sein Haus hineinkommen und ihm den Hausrat rauben, er binde denn zuvor den Starken. Und dann vermag er sein Haus zu berauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Wahrlich, Ich sage euch: Alle Sünden werden den Söhnen der Menschen vergeben, und die Lästerungen, damit sie lästern;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'Wer aber den Heiligen Geist lästert, der hat keine Vergebung ewiglich, sondern ist dem ewigen Gericht verfallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Denn sie sagten: Er hat einen unreinen Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'Und Seine Mutter und Seine Brüder kamen und standen außen und sandten zu Ihm, Ihn zu rufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'Und das Gedränge saß um Ihn her, und sie sagten Ihm: Siehe, Deine Mutter und Deine Brüder draußen suchen Dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'Und Er antwortete ihnen und sprach: Wer ist Meine Mutter und Meine Brüder?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'Und Er blickte umher auf die, so um Ihn saßen im Kreise, und sprach: Siehe da, Meine Mutter und Meine Brüder!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Denn wer Gottes Willen tut, der ist Mein Bruder und Meine Schwester und Meine Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'Und Er fing abermals an zu lehren an dem Meer. Und es versammelte sich viel Volk, also daß Er in ein Fahrzeug einstieg, und auf dem Meere saß; und das ganze Gedränge war auf dem Lande am Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'Und Er lehrte sie vieles in Gleichnissen und sprach zu ihnen in Seiner Lehre:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Höret zu: Siehe, es ging der Sämann aus zu säen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'Und es geschah, indem er säte, fiel etliches an den Weg; und das Gevögel des Himmels kam und fraß es auf;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'Anderes aber fiel auf das Steinichte, wo es nicht viel Erde hatte, und es ging alsbald auf, darum daß es nicht tiefe Erde hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Da aber die Sonne aufging, ward es versengt, und weil es nicht Wurzel hatte, verdorrte es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'Und anderes fiel in die Dornen, und die Dornen gingen auf und erstickten es, und es gab keine Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'Und anderes fiel auf gutes Land und gab Frucht, die da aufging und wuchs, und trug eins dreißigfältig, und eins sechzigfältig, und eins hundertfältig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'Und Er sprach: Wer Ohren hat zu hören, der höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'Und als Er allein war, fragten Ihn, die um Ihn waren, samt den Zwölfen um dieses Gleichnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'Und Er sprach zu ihnen: Euch ist gegeben, das Geheimnis des Reiches Gottes zu erkennen; denen draußen aber geschieht das alles in Gleichnissen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'Auf daß sie sehen und nicht erkennen, und hören und nicht verstehen, auf daß sie sich nicht bekehren und ihre Sünden ihnen vergeben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'Und Er sprach zu ihnen: Wisset ihr dieses Gleichnis nicht? und wie wollet ihr alle die Gleichnisse erkennen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Der Sämann säet das Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Das aber sind die, so am Wege sind, wo das Wort gesät wird; und wenn sie es gehört haben, kommt alsbald der Satan und nimmt das Wort hinweg, das in ihre Herzen gesät war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'Und desgleichen sind die, bei denen aufs Steinichte gesät wird, solche, welche das Wort, wenn sie es hören, alsbald mit Freuden aufnehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'Und haben nicht Wurzel in ihnen, sondern sind wetterwendisch; wenn Trübsal oder Verfolgung um des Wortes willen kommt, so nehmen sie alsbald ein Ärgernis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'Und diese sind es, die in die Dornen gesät sind; diese hören das Wort;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'Und die Sorgen dieses Zeitlaufs und der Betrug des Reichtums und die anderen Begierden kommen herein und ersticken das Wort, und es wird fruchtlos.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'Und diese sind es, die auf eine gutes Land gesät sind, die das Wort hören und annehmen und tragen Frucht, der eine dreißigfältig, und der eine sechzigfältig, und der eine hundertfältig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'Und Er sprach zu ihnen: Kommt auch die Kerze, daß man sie unter den Scheffel oder unter die Bank setze und nicht vielmehr daß man sie auf den Leuchter aufsetze?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Denn nichts ist verborgen, das nicht kundbar würde, und nichts so heimlich, daß es nicht an die Offenheit käme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Wer Ohren hat zu hören, der höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'Und Er sprach zu ihnen: Sehet zu, was ihr höret; Mit welchem Maß ihr messet, wird euch gemessen, und wird euch, die ihr höret, noch hinzugetan werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Denn wer da hat, dem wird gegeben werden; und wer nicht hat, von dem wird man wegnehmen auch das er hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'Und Er sprach: Mit dem Reich Gottes ist es also, wie wenn der Mensch Samen wirft aufs Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'Und schlummert und steht auf Nacht und Tag; und der Same sproßt hervor und schießt auf, er selbst weiß nicht wie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Denn die Erde bringt von selbst die Frucht, zuerst das Gras, dann die Ähre, dann den vollen Weizen in der Ähre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Wenn aber die Frucht sich ergibt, so sendet er alsbald die Sichel, weil die Ernte dasteht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'Und Er sprach: Womit wollen wir das Reich Gottes vergleichen? In welchem Gleichnis wollen wir es darstellen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Es ist wie ein Senfkorn: Wenn es in die Erde gesät wird, so ist es kleiner als alle Samen auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'Und wenn es gesät ist, so steigt es auf und wird größer als alle Gartenkräuter und gewinnt große Zweige, also daß das Gevögel des Himmels kann unter seinem Schatten wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'Und in vielen solchen Gleichnissen sagte Er ihnen das Wort, so wie sie es hören konnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Ohne Gleichnis aber redete Er nicht zu ihnen; legte Seinen Jüngern aber insonderheit alles aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'Und an demselben Tage, da es Abend geworden, sprach Er zu ihnen: Lasset uns jenseits hinüberfahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'Und sie entließen das Gedränge, und nahmen Ihn mit sich, wie Er im Schifflein war; und es waren aber noch andere Schifflein bei Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Und es ward ein Wirbel eines großen Windes, und warf die Wellen in das Schifflein, also daß es schon sich füllte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'Und Er war im Hinterteil des Fahrzeuges und schlummerte auf einem Kopfkissen. Und sie wecken Ihn und sagen zu Ihm: Lehrer, kümmert es Dich nicht, daß wir verderben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'Und Er stand auf, bedrohte den Wind und sprach zu dem Meere: Schweig still und verstumme! Und der Wind legte sich, und es ward eine große Windstille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'Und Er sprach zu ihnen: Was seid ihr so furchtsam? Wie? habt ihr keinen Glauben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'Sie aber fürchteten sich mit großer Furcht, und sprachen zueinander: Wer ist wohl Der, daß auch der Wind und das Meer Ihm gehorchen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'Und sie kamen jenseits des Meeres in die Gegend der Gadarener.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'Und als Er aus dem Fahrzeug herauskam, begegnete Ihm alsbald aus den Grüften ein Mensch mit einem unreinen Geiste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'Der hatte seinen Aufenthalt in den Grüften, und niemand konnte ihn binden, auch nicht mit Ketten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'Denn er war oft mit Fußeisen und Ketten gebunden; und hatte die Ketten zerrissen und die Fußeisen zerrieben; und niemand vermochte ihn zu bändigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'Und allezeit, Nacht und Tag, war er in den Grüften und auf den Bergen, schrie, und zerschlug sich mit Steinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Als er aber Jesus sah von weitem, lief er und fiel vor Ihm nieder,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'Und schrie mit großer Stimme und sagte: Was habe ich mit Dir zu schaffen, Jesus, Du Sohn Gottes, des Allerhöchsten? Ich beschwöre dich bei Gott, daß Du mich nicht quälst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Denn Er sprach zu ihm: Fahre aus, unreiner Geist, von dem Menschen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'Und Er fragte ihn: Was ist dein Name? Und er antwortete und sprach: Legion ist mein Name; denn unser sind viele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'Und er bat Ihn sehr, Er möchte sie nicht aus der Gegend aussenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Es war aber dort am Berg ein großer Trieb Schweine auf der Weide;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'Und alle die Dämonen baten Ihn und sagten: Schicke uns in die Schweine, daß wir in sie eingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'Und alsbald gestattete es ihnen Jesus. Und die unreinen Geister gingen aus und gingen ein in die Schweine, und der Trieb stürzte von der Anhöhe ins Meer und sie ertranken im Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'Die sie aber hüteten, flohen und sagten es an in der Stadt und auf den Feldern. Und sie kamen heraus, um zu sehen, was da geschehen war;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'Und sie kamen zu Jesus und schauten den Besessenen, der die Legion gehabt hatte, da sitzen bekleidet und vernünftig, und sie fürchteten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'Und die es gesehen hatten, erzählten ihnen, wie es mit dem Besessenen und bei den Schweinen geschehen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'Und sie fingen an, Ihn zu bitten, Er möchte aus ihren Grenzen weggehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'Und da Er in das Schifflein einstieg, bat Ihn der Besessene, daß er dürfte bei Ihm sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Jesus aber ließ es ihm nicht zu, sondern sprach zu ihm: Gehe hin in dein Haus zu den Deinen und sage ihnen an, was der Herr an dir getan, und daß Er Sich deiner erbarmt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'Und Er ging hin und fing an zu verkündigen in den zehn Städten, was Jesus an ihm getan hatte, und alle verwunderten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'Und als Jesus wieder in dem Schifflein ans jenseitige Ufer hinübergefahren war, versammelte sich viel Gedränge zu Ihm, und Er war an dem Meere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'Und siehe, da kommt einer von den Obersten der Synagoge mit Namen Jairus, und da er Ihn sieht, fällt er Ihm zu Füßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'Und bat Ihn sehr und sprach: Mein Töchterlein ist in den letzten Zügen! Komm doch und lege die Hände auf sie, auf daß sie gerettet werde, und lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'Und Er ging hin mit ihm; und vieles Gedränge folgte Ihm nach, und sie drängten Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'Und ein Weib war da, die hatte zwölf Jahre den Blutfluß,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'Und hatte viel von vielen Ärzten erlitten, und all das Ihre ausgegeben, ohne daß es ihr etwas genützt hätte; ja es war eher noch schlimmer mit ihr geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'Da sie von Jesus hörte, kam sie im Gedränge von hinten zu und berührte Sein Kleid;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Denn sie sprach: Wenn ich nur Seine Kleider berühre, so werde ich gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'Und alsbald vertrocknete der Brunn ihres Blutes, und sie erkannte an ihrem Leibe, daß sie von ihrer Plage gesund war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'Und Jesus erkannte alsbald an Sich die Kraft, die von Ihm ausgegangen war, wandte Sich um im Gedränge und sprach: Wer hat Meine Kleider berührt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'Und Seine Jünger sagten zu Ihm: Siehst Du nicht, wie das Gedränge auf Dich zudrängt, und Du sagst: Wer hat Mich berührt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'Er aber blickte um Sich, die zu sehen, die dies getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Das Weib aber, welches wußte, was an ihr geschehen war, fürchtete sich und zitterte, kam und fiel vor Ihm nieder und sagte Ihm die ganze Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'Er aber sprach zu ihr: Tochter, dein Glaube hat dich gerettet! Gehe hin im Frieden und sei gesund von deiner Plage!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Da Er noch redete, kamen etliche vom Obersten der Synagoge und sagten: Deine Tochter ist gestorben. Was bemühst du noch den Lehrer?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Jesus aber hörte alsbald das Wort, das geredet worden, und sprach zu dem Obersten der Synagoge: Fürchte nicht, glaube nur!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'Und Er ließ niemand Ihm zugleich nachfolgen außer Petrus und Jakobus und Johannes, den Bruder des Jakobus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'Und Er kommt in das Haus des Obersten der Synagoge und schaut das Getümmel und die da viel weinten und klagten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'Und Er geht hinein und spricht zu ihnen: Was lärmet und weinet ihr? Das Kindlein ist nicht gestorben, sondern es schlummert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'Und sie verlachten Ihn. Er aber treibt sie alle hinaus, nimmt zu Sich den Vater des Kindleins und die Mutter und die mit Ihm waren, und tritt hinein, da das Kindlein lag;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'Und ergreift das Kindlein bei der Hand und spricht zu ihm: Talitha, kumi! das ist verdolmetscht: Mägdlein,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'Und alsbald stand das Mägdlein auf und wandelte; denn es war zwölf Jahre alt. Und sie entsetzten sich mit großem Entsetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'Und Er verbot ihnen streng, daß niemand es erfahren solle, und sagte, sie sollten ihr zu essen geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'Und Er ging hinaus von dannen und kam in Seine Vaterstadt, und Seine Jünger folgen Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'Und da es Sabbath ward, fing Er an zu lehren in der Synagoge, und viele, die Ihn hörten, staunten und sagten: Woher hat Dieser solches und was ist das für eine Weisheit, die Ihm gegeben ist, und daß solche Wunderkräfte durch Seine Hände geschehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Ist Der nicht der Zimmermann, Marias Sohn, der Bruder des Jakobus und des Joses und des Judas und des Simon? Und sind nicht Seine Schwestern hier bei uns? Und sie ärgerten sich an Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Jesus aber sprach zu ihnen: Ein Prophet ist nirgends ohne Ehre, als in seiner Vaterstadt und bei den Verwandten und in seinem Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'Und Er konnte dort keine einzige Wundertat tun, außer daß Er einigen Siechen die Hände auflegte und sie heilte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'Und Er verwunderte Sich über ihren Unglauben. Und Er zog umher in den Flecken im Umkreis und lehrte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'Und Er rief die Zwölfe zu Sich, und fing an sie je zwei und zwei auszusenden und gab ihnen Gewalt über die unreinen Geister;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'Und entbot ihnen, sie sollten nichts mit sich auf den Weg nehmen, denn allein einen Stab; keine Tasche, kein Brot, kein Kupfer in den Gürtel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'Sondern sie sollten sich Sohlen unterbinden, und nicht zwei Röcke anziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'Und Er sagte ihnen: Wenn ihr in ein Haus eingehet, so bleibet allda, bis ihr von dannen ausziehet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'Und welche euch nicht aufnehmen, noch euch hören, da ziehet aus von dannen und schüttelt den Staub unter euren Füßen ab zum Zeugnis über sie. Wahrlich, Ich sage euch, es wird Sodom und Gomorrah am Tage des Gerichts erträglicher sein denn selbiger Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'Und sie zogen aus und predigten, man solle Buße tun,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'Und trieben viele Dämonen aus und salbten viele Sieche mit Öl und heilten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'Und König Herodes hörte davon,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Andere sagten: Es ist Elias; andere aber sagten: Er ist ein Prophet, oder wie der Propheten einer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Als es aber Herodes hörte, sprach er: Dies ist Johannes, den ich enthauptet habe; der ist von den Toten auferweckt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Denn er, Herodes, hatte ausgesandt und den Johannes ergriffen und im Gefängnis gebunden, wegen der Herodias, dem Weibe des Philippus, seines Bruders; denn er hatte sie gefreit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Denn Johannes sagte zu Herodes: Es ist dir nicht erlaubt, deines Bruders Weib zu haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Herodias aber stellte ihm nach und wollte ihn töten und konnte nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Denn Herodes fürchtete den Johannes, weil er wußte, daß er ein gerechter und heiliger Mann war; und erhielt ihn, und hörte auf ihn in vielem, das er tat, und hörte ihn gerne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'Und es kam ein gelegener Tag, als Herodes an seinem Geburtsfest seinen Großen und Obersten und den Ersten in Galiläa ein Gastmahl machte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'Und der Herodias Tochter kam herein und tanzte, und gefiel dem Herodes und denen, die mit zu Tische lagen. Da sprach der König zu dem Mägdlein: Bitte von mir, was du willst, und ich will es dir geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'Und er schwur ihr: Was du von mir bittest, will ich dir geben, bis auf die Hälfte meines Reiches.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Sie aber ging hinaus und sprach zu ihrer Mutter: Was soll ich bitten? Die aber sprach: Das Haupt Johannes des Täufers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'Und sie kam alsbald eilig herein zum Könige, bat und sprach: Ich will, daß du mir unverzüglich das Haupt Johannes des Täufers auf einer Platte gebest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'Und der König ward sehr betrübt, aber um des Eidschwurs willen und derer, die mit zu Tische lagen, wollte er sie nicht beiseite setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'Und der König sandte alsbald einen von der Leibwache aus und verordnete sein Haupt herzubringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'Er aber ging hin, enthauptete ihn im Gefängnis und brachte sein Haupt auf einer Platte und gab es dem Mägdlein, und das Mägdlein gab es ihrer Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'Und als seine Jünger es hörten, kamen sie, und nahmen seine Leiche und legten sie in eine Gruft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'Und die Apostel versammelten sich zu Jesus und sagten an alles, was sie getan und was sie gelehrt hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'Und Er sprach zu ihnen: Kommet ihr selber besonders an einen wüsten Ort und ruhet ein wenig aus. Denn es waren derer, die da kamen und gingen, so viele, daß sie nicht gelegene Zeit zum Essen hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Und sie gingen hin im Schifflein besonders an einen wüsten Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'Und das Gedränge sah sie hingehen, und viele erkannten Ihn und liefen zu Fuß dahin aus allen Städten und kamen vor ihnen an und kamen zu Ihm zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'Und Jesus kam heraus und sah das viele Gedränge, und es jammerte Ihn derselben, daß sie wie Schafe waren, die keinen Hirten haben, und Er fing an, sie vieles zu lehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'Da es aber schon spät an der Stunde war, kamen Seine Jünger zu Ihm und sagten: Der Ort ist wüste, und es ist schon spät an der Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'Entlasse sie, daß sie rings umher in die Felder und in die Dörfer gehen und sich Brot kaufen, denn sie haben nichts zu essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'Er aber antwortete und sprach zu ihnen: Gebet ihr ihnen zu essen! Und sie sagten zu Ihm: Sollen wir hingehen und um zweihundert Denare Brot kaufen, und ihnen zu essen geben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'Er aber sprach zu ihnen: Wie viele Brote habt ihr? Gehet hin und sehet. Und da sie es erfahren, sagten sie: Fünf, und zwei Fische.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'Und Er verordnete ihnen allen, sich zu lagern nach Tischgesellschaften und Tischgesellschaften auf dem grünen Grase.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'Und sie ließen sich nieder in Abteilungen von je hundert und je fünfzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'Und Er nahm die fünf Brote und die zwei Fische, blickte zum Himmel auf und segnete, und brach die Brote und gab sie Seinen Jüngern, daß sie ihnen vorlegten; auch die zwei Fische teilte Er unter sie alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'Und sie aßen alle und wurden satt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'Und sie hoben auf zwölf Körbe voll Brocken, und von den Fischen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'Und es waren derer, welche die Brote gegessen hatten, fünftausend Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'Und alsbald nötigte Er Seine Jünger, in das Schifflein einzusteigen und voraus zu fahren hinüber nach Bethsaida, bis Er Selbst das Gedränge entlassen hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'Nachdem Er sie verabschiedet hatte, ging Er hin auf den Berg, zu beten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'Und es ward Abend, und das Schifflein war mitten auf dem Meere, und Er allein auf dem Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'Und Er sah, daß sie Not hatten im Rudern, weil der Wind ihnen entgegen war. Und Er kam um die vierte Wache der Nacht zu ihnen, und wandelte auf dem Meere, und wollte an ihnen vorübergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Da sie Ihn aber auf dem Meer wandeln sahen, meinten sie, es wäre ein Gespenst, und schrien auf:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'Denn alle sahen Ihn und erbebten. Und Er redete alsbald mit ihnen und sprach zu ihnen: Seid getrost; Ich bin es, fürchtet euch nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'Und Er stieg zu ihnen ein in das Schifflein, und der Wind legte sich. Und sie waren außer sich und verwunderten sich ungemein, über die Maßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'Denn sie verstanden nicht trotz der Brote; denn ihr Herz war verstockt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'Und sie fuhren hinüber und kamen an das Land Genesareth und landeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'Und da sie aus dem Schifflein kamen, erkannten sie Ihn alsbald,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'Und liefen in der ganzen dortigen Gegend umher und fingen an, die Leidenden auf Tragbetten umherzutragen, wo sie hörten, daß Er war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'Und wo Er in Flecken oder Städte oder Felder einging, legten sie die Siechen auf die Marktplätze hin, und baten Ihn, daß sie auch nur Seines Kleides Saum berühren dürften; und so viele als Ihn berührten, wurden gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'Und es versammelten sich zu Ihm die Pharisäer und etliche von den Schriftgelehrten, die von Jerusalem gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Und da sie sahen, daß etliche Seiner Jünger mit gemeinen, das ist ungewaschenen Händen das Brot aßen, tadelten sie es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Denn die Pharisäer und alle Juden essen nicht, sie hätten sich denn bis zum Gelenk die Hände gewaschen, indem sie an der Überlieferung der Ältesten halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'Auch vom Markte ab, essen sie nicht, bevor sie sich gewaschen haben. Und ist sonst noch vieles, das sie zu halten angenommen haben, das Waschen der Kelche und der Krüge und eherner Gefäße und Bänke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'Danach fragten Ihn die Pharisäer und die Schriftgelehrten: Warum wandeln Deine Jünger nicht nach der Überlieferung der Ältesten, sondern essen das Brot mit ungewaschenen Händen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'Er aber antwortete und sprach zu ihnen: Schön hat Jesajas über euch Heuchler geweissagt, wie geschrieben ist: Dieses Volk ehrt Mich mit den Lippen, ihr Herz aber ist ferne, weg von Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'Umsonst aber verehren sie Mich und lehren Lehren, die Gebote der Menschen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Denn ihr verlasset das Gebot Gottes, und ergreifet die Überlieferung von Menschen, das Waschen der Krüge und Kelche, und tut viel andere solche Dinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'Und Er sprach zu ihnen: Gar schön setzt ihr das Gebot Gottes beiseite, damit ihr eure Überlieferung haltet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Denn Moses sprach: Ehre deinen Vater und deine Mutter, und wer dem Vater oder der Mutter flucht, der soll des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Ihr aber sagt: Wenn ein Mensch zum Vater oder zur Mutter spricht: Korban, was du von mir zu Nutzen gehabt hättest;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'So lasset ihr ihn hinfort nichts mehr für seinen Vater oder seine Mutter tun,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Und machet das Wort Gottes ungültig durch eure Überlieferung, die ihr überliefert habt, und solches tut ihr vieles dergleichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'Und Er rief das ganze Gedränge herbei und sprach zu ihnen: Höret Mir alle zu und verstehet es:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Es ist nichts außerhalb des Menschen, so es in ihn eingeht, das ihn gemein machen kann; was aber von ihm ausgeht, das ist es, das den Menschen gemein macht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Wer Ohren hat zu hören, der höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'Und als Er vom Gedränge weg ins Haus einging, fragten Ihn Seine Jünger über das Gleichnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Und Er sprach zu ihnen: So seid auch ihr unverständig? Begreifet ihr nicht, daß alles, was von außen in den Menschen eingeht, ihn nicht gemein machen kann?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'Denn es geht nicht in sein Herz ein, sondern in den Bauch, und geht aus in den Abzug, der alle Speisen reinigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Er sprach aber: Was vom Menschen ausgeht, das macht den Menschen gemein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Denn von innen, aus dem Herzen der Menschen gehen aus die bösen Gedanken, Ehebrüche, Hurereien, Mordtaten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'Diebereien, Habsucht, Schlechtigkeit, Trug, Unzucht, ein übles Auge, Lästerung, Hoffart, Unvernunft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'All dieses Schlechte kommt von innen heraus und macht den Menschen gemein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'Und Er stand auf und ging weg von dannen in die Grenzen von Tyrus und Sidon; und Er ging ein in ein Haus und wollte es niemand erfahren lassen; und Er konnte nicht verborgen bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Denn ein Weib, deren Töchterlein einen unreinen Geist hatte, hörte von Ihm, kam und fiel Ihm zu Füßen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Sie war aber ein griechisches Weib, eine Syrophönizierin von Geschlecht und bat Ihn, daß Er den Dämon von ihrer Tochter austriebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Jesus aber sprach zu ihr: Laß zuerst die Kinder satt werden; es ist nicht schön, daß man den Kindern das Brot nehme und werfe es vor die Hündlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Sie antwortete aber und sprach zu Ihm: Ja, Herr, und doch essen die Hündlein unter dem Tische von den Brosamen der Kindlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'Und Er sprach zu ihr: Um dieses Wortes willen gehe hin; der Dämon ist von deiner Tochter ausgegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'Und sie ging hin in ihr Haus und fand, daß der böse Geist ausgegangen war und ihre Tochter auf dem Bette lag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'Und Er zog wieder aus von den Grenzen von Tyrus und Sidon und kam an das galiläische Meer mitten in die Grenzen der zehn Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'Und sie bringen Ihm einen Tauben, der kaum reden konnte, und flehen Ihn an, daß Er die Hand auf ihn legete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'Und Er nahm ihn beiseite vom Gedränge besonders, legte ihm Seine Finger in seine Ohren, und spützete und berührte seine Zunge,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'Und Er blickte auf zum Himmel, seufzte und sprach zu ihm: Ephphatha, das ist, tue dich auf!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'Und alsbald tat sich sein Gehör auf und das Band seiner Zunge löste sich, und er redete recht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'Und Er verbot ihnen, es jemand zu sagen. Je mehr Er ihnen aber verbot, desto weit mehr verkündeten sie es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'Und sie waren über die Maßen erstaunt und sprachen: Er hat alles wohl gemacht; die Tauben macht Er hören und die Sprachlosen reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'In jenen Tagen, als sehr viel Volk da war, und sie nichts zu essen hatten, rief Jesus Seine Jünger zu Sich und sprach zu ihnen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Mich jammert des Volkes; denn es sind schon drei Tage, daß sie bei Mir verharren, und haben nichts zu essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'Und wenn Ich sie ungegessen nach ihrem Hause entlasse, so werden sie auf dem Wege verschmachten; denn ihrer sind einige von weit her gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Und Seine Jünger antworteten Ihm: Woher kann man hier in der Wüste diese mit Broten sättigen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'Und Er fragte sie: Wie viele Brote habt ihr? Sie aber sprachen: Sieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'Und Er entbot dem Gedränge, sich auf die Erde niederzulassen; und Er nahm die sieben Brote, dankte, brach sie und gab sie Seinen Jüngern, daß sie selbige vorlegten; und sie legten sie dem Volke vor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'Auch hatten sie etliche Fischlein; und Er segnete sie und sagte, daß sie auch diese vorlegen sollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'Sie aber aßen und wurden satt, und hoben sieben Weidenkörbe mit Brocken auf, die übergeblieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Es waren aber bei viertausend, die gegessen hatten, und Er entließ sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'Und alsbald stieg Er mit Seinen Jüngern ein in ein Schifflein und kam in die Gegend von Dalmanutha.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'Und die Pharisäer kamen heraus und fingen an, sich mit Ihm zu befragen und ersuchten von Ihm ein Zeichen vom Himmel, daß sie Ihn versuchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'Und Er seufzt auf in Seinem Geiste und spricht: Was suchet dies Geschlecht ein Zeichen? Wahrlich, Ich sage euch: Es wird diesem Geschlechte kein Zeichen gegeben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'Und Er verließ sie, stieg wieder ein in das Schifflein und ging weg hinüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'Und sie hatten vergessen, Brot mit sich zu nehmen; und hatten nicht mehr denn ein Brot mit sich im Schifflein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Und Er verbot ihnen und sprach: Sehet zu, hütet euch vor dem Sauerteig der Pharisäer und dem Sauerteig des Herodes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'Und sie besprachen untereinander und sagten: Weil wir kein Brot haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'Und Jesus vernahm es und sprach zu ihnen: Warum besprecht ihr euch, daß ihr kein Brot habt? Begreift ihr noch nicht, noch verstehet ihr? Ist euer Herz noch verstockt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Habet Augen und sehet nicht, habet Ohren und höret nicht und gedenket nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Als Ich die fünf Brote unter die fünftausende brach, wie viele Körbe voll Brocken hobet ihr auf? Sie sprachen zu Ihm: Zwölf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Als aber die sieben unter die viertausend, wie viele Weidenkörbe voll Brocken hobet ihr auf? Sie sagten: Sieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'Und Er sprach zu ihnen: Wie? Verstehet ihr es nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'Und Er kommt nach Bethsaida; und sie bringen zu Ihm einen Blinden, und flehen Ihn an, daß Er ihn berührete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'Und Er nahm den Blinden bei der Hand, führte ihn hinaus aus dem Flecken, und spützete in seine Augen, legte die Hände auf ihn und fragte ihn, ob er etwas sähe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'Und er blickte auf und sprach: Ich sehe die Menschen wie Bäume umherwandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Da legte Er ihm abermals die Hände auf seine Augen, und hieß ihn aufblicken, und er war wieder hergestellt und sah alles deutlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'Und Er sandte ihn nach seinem Hause uns sprach: Gehe nicht ein in den Flecken und sage es auch niemand im Flecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'Und Jesus ging aus und Seine Jünger in die Flecken von Cäsarea Philippi, und auf dem Wege fragte Er Seine Jünger und sprach zu ihnen: Wer sagen die Menschen, daß Ich sei?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Sie aber antworteten: Johannes der Täufer, und andere: Elias; andere aber: der Propheten einer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'Und Er sprach zu ihnen: Ihr aber, wer saget ihr, daß Ich bin? Petrus aber antwortete und sprach zu Ihm: Du bist der Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'Und Er bedrohte sie, daß sie niemand von Ihm sagen sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'Und Er fing an, sie zu lehren, daß des Menschen Sohn vieles erleiden und von den Ältesten und Hohenpriestern und Schriftgelehrten verworfen und getötet werden müsse und nach drei Tagen auferstehen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'Und das Wort redete Er frei heraus. Und Petrus nahm Ihn zu sich, und fing an, Ihn zu bedrohen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'Er aber wandte Sich um, und da Er Seine Jünger sah, bedrohte Er Petrus und sprach: Gehe hin, hinter Mich, Satan! Denn du sinnest nicht was von Gott, sondern was von Menschen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'Und Er rief das Gedränge samt Seinen Jüngern zu Sich und sprach zu ihnen: Wer Mir nachfolgen will, der verleugne sich selbst, und nehme sein Kreuz auf, und folge Mir nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Denn wer seine Seele retten will, der wird sie verlieren, wer aber seine eigene Seele verliert um Meiner und des Evangeliums willen, der wird sie retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Denn was nützete es dem Menschen, so er die ganze Welt gewönne und nähme Schaden an seiner Seele?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Oder was kann denn der Mensch geben zur Lösung seiner Seele?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Denn wer sich Mein und Meiner Worte schämt in diesem ehebrecherischen und sündhaften Geschlecht, dessen wird Sich auch des Menschen Sohn schämen, wenn Er in der Herrlichkeit Seines Vaters mit den heiligen Engeln kommen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'Und Er sprach zu ihnen: Wahrlich, Ich sage euch: Es sind etliche von denen, die hier stehen, die den Tod nicht schmecken werden, bis daß sie das Reich Gottes in Kraft kommen sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'Und nach sechs Tagen nahm Jesus Petrus, Jakobus und Johannes mit Sich und führte sie hinauf auf einen hohen Berg besonders alleine und verwandelte Sich vor ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'Und Seine Kleider wurden glänzend, ungemein weiß, wie der Schnee, daß sie kein Walker auf Erden kann so weiß machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'Und es erschien ihnen Elias mit Moses, und sie unterredeten sich mit Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'Und Petrus antwortete und sprach zu Jesus: Rabbi, hier ist gut sein für uns. Und lasset uns drei Hütten machen, Dir eine, Moses eine und Elias eine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Denn er wußte nicht, was er redete; denn sie waren außer sich vor Furcht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'Und es ward eine Wolke, die überschattete sie, und aus der Wolke kam eine Stimme, die sprach: Dies ist Mein geliebter Sohn, Den höret!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'Und plötzlich, da sie um sich blickten, sahen sie niemand mehr, sondern allein Jesus bei ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Da sie aber vom Berge herabstiegen, verbot Er ihnen, jemand zu erzählen, was sie gesehen hatten, bis daß des Menschen Sohn von den Toten auferstanden wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'Und sie behielten das Wort für sich und befragten sich, was dieses Auferstehen von den Toten sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'Und sie fragten Ihn und sagten: Die Schriftgelehrten sagen, Elias müsse zuvor kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'Er aber antwortete und sprach zu ihnen: Elias kommt zwar zuerst und stellt alles her. Und wie ist es geschrieben von des Menschen Sohn? - daß Er viel leiden und für nichts geachtet werden soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Aber Ich sage euch: Elias ist auch gekommen, und sie haben ihm getan, was sie wollten, wie von ihm geschrieben steht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'Und als Er zu Seinen Jüngern kam, sah Er viel Gedränge um sie her und Schriftgelehrte, die sich mit ihnen befragten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'Und alsbald, da all das Gedränge Ihn sah, wurde ihnen bange, und sie liefen herbei und begrüßten Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'Und Er fragte die Schriftgelehrten: Worüber befragt ihr euch mit ihnen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'Und einer aus dem Gedränge antwortete und sprach: Lehrer, ich habe meinen Sohn zu Dir hergebracht, der hat einen sprachlosen Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'Und wo er ihn übernimmt, reißt er ihn, und er schäumt und knirscht mit den Zähnen und zehret ab. Und ich sprach mit Deinen Jüngern, daß sie ihn austrieben, und sie vermochten es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'Er aber antwortete ihm und sprach: O du ungläubig Geschlecht, wie lange soll Ich bei euch sein? Wie lange soll Ich euch ertragen? Bringt ihn her zu Mir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'Und sie brachten ihn zu Ihm. Und als er Ihn sah, zerrte der Geist ihn alsbald, und er fiel zu Erde, wälzte sich und schäumte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'Und Er fragte seinen Vater: Wie lange Zeit ist es, daß das mit ihm geworden? Er aber sprach: Von Kind auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'Und oft hat er ihn ins Feuer und ins Wasser geworfen, daß er ihn umbrächte. Wenn Du aber kannst, so hilf uns und erbarme Dich unser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jesus aber sprach zu ihm: Wenn du glauben könntest! Alle Dinge sind möglich für den, der da glaubt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Und alsbald schrie der Vater des Knäbleins mit Tränen und sprach: Ich glaube, Herr, hilf meinem Unglauben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Da aber Jesus sah, daß das Gedränge zusammenlief, bedrohte Er den unreinen Geist und sprach zu ihm: Du sprachloser und tauber Geist, Ich befehle dir, gehe aus von ihm, und geh nimmer in ihn ein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'Und er schrie und zerrte ihn sehr und ging aus. Und er ward wie tot, so daß viele sagten: Er ist gestorben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Jesus aber ergriff ihn bei der Hand und richtete ihn auf; und er stand auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'Und als Er ins Haus einging, fragten Ihn Seine Jünger besonders: Warum konnten wir ihn nicht austreiben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'Und Er sprach zu ihnen: Diese Art kann nicht anders als durch Gebet und Fasten ausgehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'Und von dannen gingen sie aus und zogen hin durch Galiläa, und Er wollte nicht, daß es jemand wisse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Denn Er belehrte Seine Jünger und sagte ihnen: Des Menschen Sohn wird in der Menschen Hände überantwortet werden, und sie werden Ihn töten, und nachdem Er getötet worden, wird Er am dritten Tage auferstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Sie aber verstanden die Rede nicht und fürchteten sich, Ihn zu fragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'Und Er kam nach Kapernaum; und als Er zu Hause war, fragte Er sie: Worüber besprachet ihr euch miteinander auf dem Wege?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Sie aber schwiegen stille; denn sie hatten auf dem Wege unter sich besprochen, welcher der Größte wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'Und Er setzte Sich, rief die Zwölfe und sprach zu ihnen: So einer will der Erste sein, der soll der Letzte von allen und aller Diener sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'Und Er nahm ein Kindlein, stellte es mitten unter sie, und schloß es in Seine Arme und sprach zu ihnen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Wer eines dieser Kindlein aufnimmt in Meinem Namen, der nimmt Mich auf, und wer Mich aufnimmt, der nimmt nicht Mich auf, sondern Den, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Johannes aber antwortete Ihm und sprach: Lehrer, wir sahen einen, der trieb in Deinem Namen Dämonen aus, der uns nicht nachfolgt, und wir wehrten es ihm, darum daß er uns nicht nachfolgt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Jesus aber sprach: Wehret ihm nicht; denn es ist keiner, der in Meinem Namen Wundertaten tut, und wird bald Böses von Mir sprechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Denn wer nicht wider uns ist, der ist für uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Denn wer euch tränket mit einem Kelche Wasser in Meinem Namen, weil ihr des Christus seid, wahrlich, Ich sage euch, er wird seinen Lohn nicht verlieren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'Wer aber einem der Kleinen, die an Mich glauben, Ärgernis gibt, dem wäre besser, daß ihm ein Mühlstein um seinen Hals umgehängt und er ins Meer geworfen würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'Und so dich deine Hand ärgert, so haue sie ab. Es ist dir besser, daß du ein Krüppel zum Leben eingehest, denn daß du zwei Hände habest und in die Hölle ins unauslöschliche Feuer weggehest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, 'Wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'Und ärgert dich dein Fuß, so haue ihn ab. Es ist dir besser, daß du lahm zum Leben eingehest, denn daß du zwei Füße habest, und werdest in die Hölle ins unauslöschliche Feuer geworfen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, 'Wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'Und ärgert dich dein Auge, so wirf es aus. Es ist dir besser, daß du einäugig ins Reich Gottes eingehest, denn daß du zwei Augen habest, und werdest in die Hölle des Feuers geworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'Wo ihr Wurm nicht stirbt und das Feuer nicht erlischt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Denn ein jeglicher soll mit Feuer gesalzen, und alles Opfer mit Salz gesalzen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Das Salz ist gut, wenn aber das Salz salzlos wird, womit wollet ihr es würzen? Habt Salz in euch und habt Frieden miteinander!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'Und von dannen machte Er Sich auf und kam in die Grenzen Judäas durch die Gegenden jenseits des Jordan; und ein Gedränge zog wieder zusammen, Ihm zu, und wie Er gewohnt war, lehrte Er sie wieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'Und die Pharisäer kamen herzu und fragten Ihn, ob es einem Manne erlaubt sei, sich von seinem Weibe zu scheiden, und versuchten Ihn damit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'Er aber antwortete und sprach zu ihnen: Was hat euch Moses geboten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Sie aber sprachen: Moses hat gestattet einen Scheidebrief zu schreiben und sich zu scheiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Und Jesus antwortete und sprach zu ihnen: Um eures Herzens Härtigkeit willen hat Moses euch solch Gebot geschrieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Von Anfang der Schöpfung an aber machte Gott sie männlich und weiblich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, 'Darum soll der Mensch Vater und Mutter verlassen und seinem Weibe anhangen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'Und die zwei sollen sein ein Fleisch. So sind sie denn nicht mehr zwei, sondern ein Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Was denn Gott zusammengefügt hat, das soll der Mensch nicht trennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'Und im Hause fragten Ihn Seine Jünger abermals über dasselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Und Er sprach zu ihnen: Wer sich von seinem Weibe scheidet und freiet eine andere, der bricht die Ehe an ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'Und so sich ein Weib scheidet von ihrem Manne und freiet einen anderen, die bricht die Ehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'Und sie brachten Kindlein herzu, daß Er sie berührete. Die Jünger aber bedrohten die, so sie herbrachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Da es aber Jesus sah, ward Er unwillig und sprach zu ihnen: Lasset die Kindlein zu Mir kommen und wehret ihnen nicht; denn solcher ist das Reich Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Wahrlich, Ich sage euch: Wer das Reich Gottes nicht aufnimmt, wie ein Kindlein, der wird nicht hineinkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'Und Er schloß sie in Seine Arme, legte die Hände auf sie und segnete sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'Und da Er hinauskam auf den Weg, lief einer herzu, fiel vor Ihm auf die Knie und fragte Ihn: Guter Lehrer, was soll ich tun, daß ich das ewige Leben ererbe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Jesus aber sprach zu ihm: Was nennst du Mich gut? Niemand ist gut, den der Eine, Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Du weißt die Gebote: Du sollst nicht ehebrechen, du sollst nicht morden, du sollst nicht stehlen, du sollst kein falsch Zeugnis geben, du sollst nicht übervorteilen. Ehre deinen Vater und die Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'Er aber antwortete und sprach zu Ihm: Lehrer, das hab ich alles gehalten von meiner Jugend auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Jesus aber blickte ihn an, und liebte ihn und sprach zu ihm: Eins mangelt dir. Gehe hin, verkaufe, was du hast, und gib es den Armen, so wirst du einen Schatz im Himmel haben; und komme her, folge Mir nach und nimm das Kreuz auf dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Er aber ward düster über dem Worte und ging betrübt weg; denn er hatte viel Besitztum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'Und Jesus blickte umher und sprach zu Seinen Jüngern: Wie schwer ist es, daß die, so Vermögen haben, ins Reich Gottes eingehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Die Jünger aber waren bestürzt über Seine Worte; Jesus aber antwortete wieder und sprach zu ihnen: Kinder, wie schwer ist es, daß die auf das Vermögen vertrauen, ins Reich Gottes kommen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Es ist leichter, daß ein Kamel durch das Öhr der Nadel durchgehe, denn daß ein Reicher ins Reich Gottes komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Sie aber staunten über die Maßen und sagten untereinander: Wer kann dann gerettet werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jesus aber blickte sie an und sprach: Bei Menschen ist es unmöglich, aber nicht bei Gott; denn bei Gott sind alle Dinge möglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Da antwortete Petrus und sagte zu Ihm: Siehe, wir haben alles verlassen und sind Dir nachgefolgt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jesus antwortete und sprach: Wahrlich, Ich sage euch, es ist niemand, der um Meinetwillen und um des Evangeliums willen Haus, oder Brüder, oder Schwestern, oder Vater, oder Mutter, oder Weib, oder Kinder, oder Felder verlassen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'Der nicht hundertfältig empfinge jetzt in dieser Zeit Häuser und Brüder und Schwestern und Mütter und Kinder und Felder mit Verfolgungen und in dem zukünftigen Zeitlauf ewiges Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Viele aber, welche die ersten sind, werden letzte sein, und die letzten werden erste sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Sie waren aber auf dem Wege hinaufzugehen nach Jerusalem, und Jesus ging ihnen voran, und sie waren bestürzt und folgten Ihm nach und fürchteten sich. Und Er nahm wieder die Zwölfe zu Sich, und fing an, ihnen zu sagen, was sich mit Ihm zutragen würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Siehe, wir gehen hinauf nach Jerusalem, und des Menschen Sohn wird den Hohenpriestern und den Schriftgelehrten überantwortet werden, und sie werden Ihn zum Tode verdammen und Ihn den Heiden überantworten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'Und sie werden Ihn verspotten und Ihn geißeln, und Ihn anspeien und Ihn töten; und am dritten Tage wird Er auferstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'Und es kamen zu Ihm Jakobus und Johannes, die Söhne des Zebedäus, und sprachen: Lehrer, wir wollen, daß Du uns tust, um was wir bitten werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'Er aber sprach zu ihnen: Was wollt ihr, daß ich euch tun solle?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Sie aber sagten zu Ihm: Gib uns, daß wir sitzen, einer zu Deiner Rechten und einer zu Deiner Linken in Deiner Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Jesus aber sprach zu ihnen: Ihr wisset nicht, was ihr bittet. Könnet ihr den Kelch trinken, den Ich trinke, und mit der Taufe euch taufen lassen, mit der Ich getauft werde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Sie aber sprachen zu Ihm: Wir können es. Jesus aber sprach zu ihnen: Den Kelch zwar, den Ich trinke, werdet ihr trinken, und mit der Taufe, mit der Ich getauft werde, getauft werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Das Sitzen aber zu Meiner Rechten und zu Meiner Linken ist nicht Mein, zu geben, außer denen es bereitet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'Und da die Zehn das hörten, fingen sie an unwillig zu werden über Jakobus und Johannes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Jesus aber rief sie zu Sich und sprach zu ihnen: Ihr wisset, daß die, so als Oberste gelten, über die Völkerschaften herrschen, und ihre Großen Gewalt üben über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Also aber sei es nicht bei euch. Sondern wer groß unter euch sein will, der soll euer Diener sein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'Und wer unter euch der Erste sein will, der soll aller Knecht sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Denn auch des Menschen Sohn ist nicht gekommen, Sich dienen zu lassen, sondern zu dienen und Seine Seele zu geben für viele zur Lösung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'Und sie kamen nach Jericho. Und wie Er aus Jericho auszog mit Seinen Jüngern und Gedränge genug, saß am Wege des Timäus Sohn, Bartimäus der Blinde, und bettelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'Und als der hörte, daß es Jesus der Nazarener war, fing er an zu schreien und zu sagen: Sohn Davids, Jesus, erbarme Dich mein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'Viele aber bedrohten ihn, er solle stillschweigen. Er aber schrie viel mehr: Sohn Davids, erbarm Dich mein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'Und Jesus stand stille und sagte, man solle ihn rufen. Und sie riefen dem Blinden und sagten zu ihm: Sei getrost, mache dich auf; Er ruft dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'Der aber warf sein Kleid ab, stand auf und kam zu Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'Und Jesus antwortete und sprach zu ihm: Was willst du, daß Ich dir tun soll? Der Blinde aber sprach zu Ihm: Rabbuni, daß ich sehend werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'Jesus aber sprach zu ihm: Gehe hin; dein Glaube hat dich gerettet. Und alsbald ward er sehend und folgte Ihm nach auf dem Wege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'Und als sie nahe zu Jerusalem kamen nach Bethphage und Bethanien, an den Ölberg, sandte Er Seiner Jünger zwei,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'Und sprach zu ihnen: Gehet hin in den Flecken, der euch gegenüber ist; und wie ihr hineinkommet, werdet ihr alsbald ein Füllen angebunden finden, auf dem kein Mensch gesessen hat. Löset es und führet es her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'Und so jemand zu euch sagen wird: Was tut ihr das? so sprechet: Der Herr bedarf seiner, so sendet er es alsbald her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'Sie aber gingen hin und fanden das Füllen an der Tür angebunden draußen am Scheideweg und lösten es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'Und einige von denen, die da standen, sprachen zu ihnen: Was machet ihr, daß ihr das Füllen löset?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Sie aber sprachen zu ihnen, wie Jesus ihnen gebot, und sie ließen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'Und sie führten das Füllen zu Jesus, und warfen ihre Kleider darauf, und Er setzte Sich auf dasselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Viele aber streuten ihre Kleider auf den Weg; andere aber schnitten Zweige von den Bäumen ab und streuten sie auf den Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'Und die vorangingen und die nachfolgten, schrien und sprachen: Hosiannah! Gesegnet sei, Der da kommt im Namen des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Gesegnet sei das Reich, das da kommt in dem Namen des Herrn, unseres Vaters David; Hosiannah in den Höhen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'Und Jesus zog ein in Jerusalem und in das Heiligtum, und nachdem Er alles umher angeschaut, ging Er, da es schon spät an der Stunde war, mit den Zwölfen hinaus nach Bethanien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'Und am folgenden Tag, da sie von Bethanien ausgegangen waren, hungerte Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'Und Er sah von weitem einen Feigenbaum, der Blätter hatte, ging hin, ob Er wohl etwas auf ihm fände. Und da Er dahin kam, fand Er nichts denn Blätter; denn es war noch nicht die Jahreszeit für Feigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'Und Jesus hob an und sprach zu ihm: Nie mehr esse von dir jemand Frucht in Ewigkeit! Und Seine Jünger hörten es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'Und sie kamen nach Jerusalem, und Er ging ein in das Heiligtum und fing an, die im Heiligtum verkauften und kauften, auszutreiben; und die Tische der Wechsler und die Stühle der Taubenhändler stieß Er um;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'Und Er ließ nicht zu, daß jemand ein Gefäß durch das Heiligtum trug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'Und lehrte und sprach zu ihnen: Ist nicht geschrieben: Mein Haus soll für alle Völkerschaften ein Bethaus heißen? Ihr aber habt eine Räuberhöhle daraus gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'Und die Hohenpriester und die Schriftgelehrten hörten es und trachteten, wie sie Ihn umbrächten; denn sie fürchteten Ihn, weil das ganze Gedränge staunte ob Seiner Lehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'Und als es spät wurde, ging Er hinaus aus der Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'Und da sie am Morgen vorüberkamen, sahen sie den Feigenbaum von der Wurzel auf verdorrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'Und Petrus gedachte daran und sagte zu Ihm: Rabbi, siehe, der Feigenbaum, dem Du fluchtest, ist verdorrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Und Jesus antwortete und sprach zu ihnen: Habt Glauben an Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Denn wahrlich, sage Ich euch: Wer zu diesem Berge spricht: Hebe dich auf und wirf dich ins Meer, und zweifelt nicht in seinem Herzen, sondern glaubt, daß, was er spricht, geschehe, so wird ihm geschehen, was er gesprochen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Darum sage Ich euch: Alles, was ihr bittet im Gebet, glaubet, daß ihr es empfanget, so wird es euch werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'Und wenn ihr steht und betet, so vergebt, wenn ihr etwas wider jemand habt, auf daß auch euer Vater in den Himmeln euch eure Fehle vergebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, 'Vergebt ihr aber nicht, so wird euer Vater in den Himmeln eure Fehle auch nicht vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'Und sie kommen abermals nach Jerusalem. und als Er im Heiligtum wandelte, kamen zu Ihm die Hohenpriester und die Schriftgelehrten und die Ältesten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'Und sagten zu Ihm: Aus was für Gewalt tust Du das? Und wer hat Dir diese Gewalt gegeben, daß Du solches tust?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jesus aber antwortete und sprach zu ihnen: Ich will euch auch ein Wort fragen, und wenn ihr Mir antwortet, so will auch Ich euch sagen, aus was für Gewalt Ich dieses tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Die Taufe des Johannes, war sie aus dem Himmel, oder von Menschen? Antwortet Mir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'Und sie bedachten bei sich und sprachen: Sagen wir: Aus dem Himmel, so wird Er sagen: Warum habt ihr ihm nicht geglaubt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Sagen wir aber: Von Menschen, so fürchteten sie das Volk; denn sie hielten alle dafür, daß Johannes wirklich ein Prophet war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Und sie antworteten und sagten zu Jesus: Wir wissen es nicht. Und Jesus antwortete und sprach zu ihnen: So sage Ich euch auch nicht, aus was für Gewalt Ich solches tue..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'Und Er fing an, zu ihnen in Gleichnissen zu sprechen: Ein Mensch pflanzte einen Weinberg, und umgab ihn mit einem Zaun, und grub einen Keltertrog aus, und baute einen Turm, und gab ihn an Weingärtner aus und zog über Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'Und zur Jahreszeit sandte er einen Knecht an die Weingärtner, daß er von den Weingärtnern von der Frucht des Weinbergs empfange.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Sie aber nahmen ihn, stäupten ihn und sandten ihn leer von dannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'Und abermals sandte er zu ihnen einen anderen Knecht. Und diesem zerwarfen sie den Kopf mit Steinen und sandten ihn entehrt von dannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'Und er sandte abermals einen anderen. Und diesen töteten sie; und viele andere; etliche stäupten, etliche aber töteten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Da hatte er noch seinen einzigen geliebten Sohn, auch den sandte er zuletzt an sie ab, indem er sagte: Vor meinem Sohne werden sie sich scheuen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Aber jene Weingärtner sprachen zueinander: Das ist der Erbe, kommet, lasset uns ihn töten, und das Erbe ist unser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Und sie griffen ihn, töteten ihn, und warfen ihn zum Weinberg hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Was wird nun der Herr des Weinberges tun? Er wird kommen, die Weingärtner umbringen und den Weinberg anderen geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Habt ihr nicht gelesen diese Schrift: Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein geworden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'Vom Herrn ist das geschehen, und es ist wunderbar in unseren Augen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'Und sie trachteten danach, daß sie Ihn ergriffen, und fürchteten sich vor dem Gedränge. Denn sie erkannten, daß Er gegen sie das Gleichnis gesprochen hatte. Und sie ließen von Ihm und gingen weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'Und sie sandten etliche von den Pharisäern und den Herodianern an Ihn, auf daß sie Ihn im Worte fingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'Sie kamen aber und sprachen zu Ihm: Lehrer, wir wissen, daß Du wahrhaftig bist, und daß Du Dich um niemand kümmerst; denn Du blickst nicht auf das Angesicht der Menschen, sondern lehrst den Weg Gottes nach der Wahrheit. Ist es erlaubt, daß man dem Kaiser die Steuer gibt, oder nicht? Sollen wir sie geben oder nicht geben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'Er aber sah ihre Heuchelei und sprach zu ihnen: Was versuchet ihr Mich? Bringet Mir einen Denar, daß Ich ihn sehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Sie aber brachten einen. Und Er sprach zu ihnen: Wessen ist das Bild und die Überschrift? Sie aber sagten zu Ihm: Des Kaisers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Und Jesus antwortete und sagte zu ihnen: So gebet hin dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist. Und sie verwunderten sich über Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'Und die Sadduzäer kamen zu Ihm, die da sagen, es sei keine Auferstehung, und fragten Ihn und sagten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Lehrer, Moses hat uns geschrieben: Wenn jemandes Bruder stirbt und hinterläßt ein Weib, läßt aber keine Kinder, da soll sein Bruder dessen Weib nehmen und seinem Bruder Samen erwecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Nun waren sieben Brüder. Und der erste nahm ein Weib, starb und ließ keinen Samen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'Und der zweite nahm sie und starb, und auch er ließ keinen Samen; desgleichen auch der dritte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'Und die sieben nahmen sie und ließen keinen Samen; und zuletzt von allen starb auch das Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'In der Auferstehung nun, wenn sie auferstanden sind, wessen Weibe wird sie sein unter ihnen? Denn die sieben haben sie zum Weibe gehabt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Und Jesus antwortete und sprach zu ihnen: Irret ihr nicht darum, daß ihr die Schriften und die Kraft Gottes nicht wisset?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Denn wenn sie von den Toten auferstehen, freien sie nicht, noch lassen sie sich freien, sondern sind wie die Engel in den Himmeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Was aber die Toten anlangt, daß sie auferweckt werden, habt ihr nicht in Moses Buch gelesen, bei dem Dornbusch, wie Gott zu ihm sprach und sagte: Ich bin der Gott Abrahams und der Gott Isaaks und der Gott Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'Er ist nicht Gott der Toten, sondern der Lebendigen Gott. Ihr gehet sehr irre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'Und es kam einer der Schriftgelehrten herzu, der ihre Besprechung gehört hatte, und sah, daß Er ihnen fein geantwortet hatte, und fragt Ihn: Welches ist das erste Gebot von allen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jesus aber antwortete ihm: Das erste Gebot von allen ist: Höre, Israel, der Herr unser Gott ist ein einiger Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'Und du sollst lieben den Herrn deinen Gott von deinem ganzen Herzen und von deiner ganzen Seele und von deiner ganzen Gesinnung und mit deiner ganzen Stärke. Dies ist das erste Gebot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Und das zweite ist ihm ähnlich, dieses: Du sollst deinen Nächsten lieben wie dich selbst. Kein ander Gebot ist größer denn diese.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'Und der Schriftgelehrte sprach zu Ihm: Schön, o Lehrer, nach der Wahrheit hast Du gesprochen; denn es ist ein Gott und ist kein anderer außer Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'Und Ihn lieben von ganzem Herzen, und von ganzem Verstande, und von ganzer Seele, und mit aller Stärke, und den Nächsten lieben, wie sich selbst, das ist mehr als alle Brandopfer und Schlachtopfer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'Und da Jesus sah, daß er vernünftig antwortete, sprach Er zu ihm: Du bist nicht weit vom Reiche Gottes; und niemand wagte Ihn mehr zu fragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'Und Jesus hob an und sprach, da Er lehrte im Heiligtum: Wie sagen die Schriftgelehrten Christus sei Davids Sohn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Hat doch David selbst im heiligen Geist gesprochen: Der Herr sprach zu meinem Herrn: Setze dich zu Meiner Rechten, bis daß Ich lege Deine Feinde zum Schemel Deiner Füße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'David selbst nun nennt Ihn Herr, und woher ist Er sein Sohn? Und viel Volk hörte Ihm gerne zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'Und in Seiner Lehre sprach Er zu ihnen: Sehet euch vor vor den Schriftgelehrten, die da wollen in langen Gewändern umherwandeln und sich auf den Marktplätzen grüßen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'Und die wollen die ersten Sitze in den Synagogen, und bei den Gastmählern die ersten Plätze haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'Sie essen der Witwen Häuser auf, und zum Vorwande beten sie lange; sie werden um so schwereres Gericht empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'Und Jesus hatte Sich gegenüber dem Schatzkasten gesetzt und schaute, wie das Volk Kupfergeld in den Schatzkasten warf. Und viele Reiche legten viel ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'Und es kam eine arme Witwe, die legte zwei Scherflein ein, die einen Heller machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'Und Er rief Seine Jünger zu Sich und sprach zu ihnen: Wahrlich, Ich sage euch, diese arme Witwe da hat mehr als sie alle eingelegt, die da in den Schatzkasten einlegten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'Denn alle legten von ihrem Überflusse ein; sie aber hat von ihrer Notdurft alles, was sie hatte, all ihren Lebensunterhalt eingelegt..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'Und wie Er aus dem Heiligtum ausging, sprach einer Seiner Jünger zu Ihm: Lehrer, sieh! was für Steine! Und was für Gebäude!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'Und Jesus antwortete und sprach zu ihm: Siehst du diese großen Gebäude? Kein Stein wird auf dem Steine gelassen, der nicht niedergerissen würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'Und als Er Sich auf dem Ölberg, dem Heiligtum gegenüber niedergesetzt hatte, fragten Ihn Petrus und Jakobus, und Johannes und Andreas besonders:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Sag uns, wann wird das geschehen? Und was wird das Zeichen sein, daß alles das vollendet werde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Jesus aber antwortete ihnen und fing an zu sagen: Sehet euch vor, daß niemand euch irreführe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Denn viele werden kommen in Meinem Namen und sagen: Ich bin es, und werden viele irreführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Wenn ihr aber hört von Kriegen und Kriegsgerüchten, so lasset euch nicht bange werden; denn es muß geschehen; aber noch ist das Ende nicht da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Denn Völkerschaft wird sich wider Völkerschaft aufmachen, und Königreich wider Königreich. Und Erdbeben werden an verschiedenen Orten geschehen und Hungersnot und Bewegungen sein. Das ist der Anfang der Wehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Ihr aber sehet euch vor! Denn sie werden euch vor Ratsversammlungen und in den Synagogen überantworten, ihr werdet gestäupt und vor Statthalter und Könige gestellt werden um Meinetwillen, zum Zeugnis über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'Und in allen Völkerschaften muß zuerst das Evangelium gepredigt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Wenn sie euch nun führen, euch zu überantworten, so sorget nicht voraus, was ihr reden sollet, noch sinnet nach; sondern was euch zu jener Stunde wird gegeben werden, das redet; denn nicht ihr seid es, die da reden, sondern der Heilige Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Der Bruder aber wird den Bruder, und der Vater das Kind zum Tode überantworten, und Kinder werden wider die Eltern aufstehen und sie zum Tode bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'Ihr werdet von allen gehaßt werden um Meines Namens willen; wer aber beharrt bis ans Ende, der wird gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'Wenn ihr aber den Greuel der Verwüstung, von dem der Prophet Daniel gesprochen, stehen sehet, da, wo er nicht sollte, - wer es liest, der merke auf - dann sollen fliehen, die in Judäa sind, auf die Berge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'Und wer auf dem Dache ist, steige nicht herab in das Haus, und gehe nicht hinein, etwas aus seinem Hause zu holen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'Und wer auf dem Felde ist, der kehre nicht hinter sich um, sein Kleid zu holen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Aber wehen den Schwangeren und Säugenden in jenen Tagen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Betet aber, daß eure Flucht nicht geschehe im Winter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Denn selbige Tage werden eine Trübsal sein, wie nie eine solche gewesen ist seit dem Anfang der Schöpfung, die Gott geschaffen hat, bis jetzt, und auch nicht werden wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'Und hätte der Herr die Tage nicht verkürzt, so würde kein Fleisch gerettet; aber um der Auserwählten willen, die Er auserwählt hat, hat Er die Tage verkürzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'Und wenn dann einer zu euch sagt: Siehe, hier ist Christus! oder: siehe, da ist Er, so glaubet nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Denn es werden falsche Christi und falsche Propheten auftreten und Zeichen und Wunder geben, um, so es möglich wäre, selbst die Auserwählten irre zu führen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'Ihr aber, sehet euch vor; siehe, Ich habe euch alles vorhergesagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Aber in selbigen Tagen nach selbiger Trübsal wird die Sonne verfinstert werden, und der Mond seinen Schein nicht geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'Und die Sterne des Himmels werden herunterfallen, und die Kräfte der Himmel werden erschüttert werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'Und dann werden sie sehen des Menschen Sohn kommen in den Wolken mit großer Kraft und Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'Und dann wird Er Seine Engel senden und versammeln Seine Auserwählten von den vier Winden von dem Ende der Erde bis zum Ende des Himmels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Von dem Feigenbaum aber lernt das Gleichnis; Wenn sein Zweig schon saftig wird, und die Blätter hervortreibt, erkennt ihr, daß der Sommer nahe ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Also auch ihr, wenn ihr seht, daß solches geschieht, erkennt, daß es nahe vor der Türe ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Wahrlich, Ich sage euch, daß dies Geschlecht nicht vergeht, bis daß dies alles geschehen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Himmel und Erde werden vergehen, aber Meine Worte vergehen nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Um selbigen Tag aber und um die Stunde weiß niemand, auch die Engel im Himmel nicht, noch der Sohn, sondern nur der Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Sehet euch vor, wachet und betet; denn ihr wisset nicht, wann die Zeit ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Wie ein Mann, der über Land zog, der sein Haus verlassen, und seinen Knechten die Gewalt, einem jeglichen sein Werk gegeben hatte, und dem Türhüter geboten, daß er wachen sollte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'So wachet nun; denn ihr wisset nicht, wann der Herr des Hauses kommt, ob am Abend, oder um Mitternacht, oder ob um den Hahnenschrei, oder des Morgens;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'Auf daß er nicht plötzlich komme und finde euch schlummernd.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Was Ich aber euch sage, das sage Ich allen: Wachet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Nach zwei Tagen aber war Pascha und das Fest des Ungesäuerten. Und die Hohenpriester und die Schriftgelehrten suchten, wie sie Ihn mit Trug ergriffen und töteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Sie sagten aber: Nicht am Fest, daß nicht ein Getümmel im Volk werde!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'Und da Er in Bethanien im Hause Simons des Aussätzigen zu Tische lag, kam ein Weib, die hatte eine Alabasterbüchse mit Salbe von echter köstlicher Narde, und sie zerbrach die Alabasterbüchse und goß sie auf Sein Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Es waren aber etliche da, die wurden unwillig bei sich und sprachen: Wozu ist diese Verschwendung der Salbe geworden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Diese Salbe konnte man um mehr den dreihundert Denare verkaufen und es den Armen geben; und sie ergrimmten über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Jesus aber sprach: Lasset sie! - Was belästigt ihr sie? Sie hat ein schönes Werk an Mir gewirkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Denn die Armen habt ihr allezeit bei euch, und wenn ihr wollt, könnt ihr ihnen Gutes tun; Mich aber habt ihr nicht allezeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Sie hat getan, was sie vermochte. Sie ist zuvorgekommen, Meinen Leib zum Begräbnisse zu salben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Wahrlich, Ich sage euch: Wo in aller Welt dieses Evangelium gepredigt wird, da wird man auch von dem, was sie getan, reden zu ihrem Gedächtnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'Und Judas Ischariot, einer von den Zwölfen, ging hin zu den Hohenpriestern, daß er Ihn denselben überantworte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Als sie aber das hörten, freuten sie sich und versprachen, ihm Silber zu geben. Und er trachtete danach, wie er Ihn mit guter Gelegenheit überantworte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'Und am ersten Tage des Ungesäuerten, da sie das Pascha schlachteten, sprachen Seine Jünger zu Ihm: Wo willst Du, daß wir hingehen zu bereiten, daß Du das Pasche essest?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'Und Er sendet zwei Seiner Jünger und spricht zu ihnen: Gehet hin in die Stadt, und es wird euch ein Mensch begegnen, der einen Krug mit Wasser trägt; folget ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'Und wo er eingeht, da saget dem Hausherrn: Der Lehrer läßt dir sagen: Wo ist die Herberge, darin Ich das Pascha mit Meinen Jüngern esse?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'Und der wird euch einen großen bepolsterten Obersaal zeigen, der bereit ist. Daselbst bereitet es für uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'Und Seine Jünger gingen aus und kamen in die Stadt und fanden es, wie Er ihnen gesagt hatte, und bereiteten das Pascha.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'Und als es Abend ward, kam Er mit den Zwölfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'Und da sie bei Tische lagen und aßen, sprach Jesus: Wahrlich, Ich sage euch: Einer von euch, der mit Mir isset, wird Mich verraten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Sie aber fingen an betrübt zu werden und einer nach dem anderen zu Ihm zu sagen: Doch nicht ich? und ein anderer: Doch nicht ich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'Er aber antwortete und sprach zu ihnen: Einer aus den Zwölfen, der mit Mir in die Schale eintaucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Des Menschen Sohn geht zwar hin, wie es von Ihm geschrieben steht. Aber wehe demselben Menschen, durch den des Menschen Sohn verraten wird. Es wäre selbigen Menschen besser, er wäre nicht geboren worden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'Und da sie aßen, nahm Jesus Brot, segnete es, brach es, und gab es ihnen und sprach: Nehmet, esset! Das ist Mein Leib;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'Und Er nahm den Kelch, dankte und gab ihnen den, und sie tranken alle daraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'Und Er sprach zu ihnen: Dies ist Mein Blut, das des neuen Bundes, das für viele vergossen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Wahrlich, Ich sage euch: Ich werde hinfort nicht mehr von dem Gewächse des Weinstocks trinken, bis auf selbigen Tag, da Ich es neu trinke im Reiche Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'Und nach dem Lobgesang gingen sie hinaus an den Ölberg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'Und Jesus spricht zu ihnen: In dieser Nacht werdet ihr euch alle an Mir ärgern; denn es ist geschrieben: Ich werde den Hirten schlagen, und die Schafe werden sich zerstreuen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Aber wenn Ich auferweckt werde, will Ich euch vorangehen nach Galiläa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Petrus aber sprach zu Ihm: Wenn sich auch alle ärgern werden, so doch ich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Und Jesus sprach zu ihm: Wahrlich, Ich sage dir: Heute in dieser Nacht, ehe denn der Hahn zweimal kräht, wirst du Mich dreimal verleugnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'Er aber sprach noch darüber: Wenn ich auch mit Dir sterben müßte, so werde ich Dich doch nicht verleugnen. Desgleichen aber sprachen auch alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'Und sie kommen zu dem Hofe, mit Namen Gethsemane. Und Er sprach zu Seinen Jüngern: Setzet euch allda, bis Ich bete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'Und Er nimmt Petrus und Jakobus und Johannes mit Sich, und fing an, zu bangen und zu zagen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'Und Er sprach zu ihnen: Meine Seele ist tief betrübt bis in den Tod. Bleibet hier und wachet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Und Er ging ein wenig vor, fiel auf die Erde und betete, daß, so es möglich wäre, die Stunde von Ihm vorüberginge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'Und Er sprach: Abba, Vater. Alles ist Dir möglich, nimm diesen Kelch hinweg von Mir; doch nicht was Ich will, sondern was Du.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'Und Er kommt und findet sie schlummernd und spricht zu Petrus: Simon, schlummerst du? Vermochtest du nicht eine Stunde zu wachen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Wachet und betet, daß ihr nicht in Versuchung eingehet; der Geist zwar ist willig, aber das Fleisch ist schwach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'Und Er ging wieder hin, betete und sprach dieselben Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'Und Er kehrte zurück und fand sie abermals schlummernd; denn ihr Augen waren beschwert, und sie wußten nicht, was sie Ihm antworten sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'Und Er kommt zum dritten Mal und spricht zu ihnen: Schlummert nun ferner und ruhet euch aus! - Es ist dahin! Die Stunde ist gekommen. Siehe, des Menschen Sohn wird in die Hände der Sünder überantwortet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Macht euch auf, laßt uns gehen! Siehe, der Mich verrät, hat sich genaht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'Und alsbald während Er noch redete, trat herzu Judas, einer von den Zwölfen, und viel Gedränge mit ihm mit Schwertern und Knitteln, von den Hohenpriestern und den Schriftgelehrten und den Ältesten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Der Verräter aber hatte ihnen ein Merkzeichen gegeben und gesagt: Welchen ich küssen werde, Der ist es, ergreifet und führet Ihn sicher weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'Und da er kam, kam er alsbald heran, zu Ihm und sprach: Rabbi, Rabbi, und küßte Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Sie aber legten ihre Hände an Ihn und ergriffen Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Einer aber derer, die dabei standen, zog das Schwert, und schlug nach dem Knecht des Hohenpriesters und hieb ihm das Ohr ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'Und Jesus hob an und sprach zu ihnen: Wie gegen einen Räuber seid ihr ausgezogen mit Schwertern und mit Knitteln, Mich gefangenzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Täglich war Ich bei euch im Heiligtum und lehrte, und ihr ergriffet Mich nicht; aber - auf daß die Schriften erfüllet werden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'Und sie verließen Ihn alle und flohen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'Und ein gewisser Jüngling folgte Ihm nach, der hatte eine Leinwand auf den bloßen Leibe umgeworfen, und die Jünglinge ergriffen ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'Der aber ließ die Leinwand zurück und entfloh ihnen nackt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'Und sie führten Jesus weg zu dem Hohenpriester, und alle die Hohenpriester und die Ältesten und die Schriftgelehrten kamen bei ihm zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'Und Petrus folgte Ihm nach von weitem, bis hinein in den Hof des Hohenpriesters, und er saß bei den Amtsdienern und wärmte sich bei dem Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'Die Hohenpriester aber und der ganze Rat suchten Zeugnis wider Jesus, auf daß sie Ihn zum Tode brächten, fanden aber keines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Denn viele gaben falsches Zeugnis wider Ihn; aber die Zeugnisse waren nicht gleich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'Und einige standen auf und gaben falsch Zeugnis wider Ihn und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Wir hörten Ihn sagen: Ich will diesen mit Händen gemachten Tempel niederreißen und binnen drei Tagen einen anderen bauen, nicht mit Händen gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Aber auch so war ihr Zeugnis nicht gleich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'Und der Hohepriester stand in ihrer Mitte auf, fragte Jesus und sprach: Antwortest Du nichts auf das, was diese wider Dich zeugen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'Er aber schwieg stille und antwortete nicht. Wieder fragte Ihn der Hohepriester und sprach zu Ihm: Bist du Christus, der Sohn des Gesegneten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Jesus aber sprach: Ich bin. Und ihr werdet sehen des Menschen Sohn sitzen zur Rechten der Kraft und kommen mit des Himmels Wolken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Der Hohepriester aber zerriß seine Röcke und sprach: Was bedürfen wir noch Zeugen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Ihr habt die Lästerung gehört. Wie scheint es euch? Sie aber verurteilten Ihn alle, daß Er dem Tode verfallen wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'Und es fingen einige an, Ihn anzuspeien, und Ihm das Angesicht zu umhüllen, und Ihn mit Fäusten zu schlagen und zu Ihm zu sagen: Weissage. Und die Amtsdiener gaben Ihm Backenstreiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'Und während Petrus unten in dem Hofe war, kam eine der Mägde des Hohenpriesters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'Und da sie den Petrus sich wärmen sah, blickte sie ihn an und sprach: Auch du warst mit Jesus dem Nazarener.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'Er aber leugnete und sprach: Ich weiß nicht und verstehe nicht, was du sagst; und ging hinaus in den Vorhof, und ein Hahn krähte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'Und die Magd sah ihn wiederum und fing an und sprach zu den Dabeistehenden: Dieser ist von ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'Er aber leugnete abermals; und nach einer kleinen Weile sprachen abermals die Dabeistehenden zu Petrus: Wahrhaftig, du bist von ihnen; du bist ja ein Galiläer, und deine Sprache lautet so.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'Er aber fing an, sich zu verwünschen und zu schwören: Ich kenne diesen Menschen nicht, von Welchem ihr sprechet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'Und der Hahn krähte zum zweiten Mal. Und Petrus gedachte der Rede, die Jesus zu ihm sprach: Ehe der Hahn zum zweiten Mal kräht, wirst du Mich drei Mal verleugnen; und er hob an zu weinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'Und alsbald am Morgen hielten die Hohenpriester mit den Ältesten und den Schriftgelehrten und dem ganzen Rate eine Beratung, banden Jesus, führten Ihn ab und überantworteten Ihn dem Pilatus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'Und Pilatus fragte Ihn: Bist Du der Juden König? Er aber antwortete und sprach zu ihm: Du sagst es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'Und die Hohenpriester klagten Ihn über vieles an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Pilatus aber fragte Ihn wieder und sagte: Antwortest Du nicht? Siehe, wie vieler Dinge sie Dich anklagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Jesus aber antwortete nicht mehr, so daß sich Pilatus verwunderte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Auf das Fest aber gab er ihnen einen Gefangenen los, um welchen sie ihn baten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Es war aber einer, genannt Barabbas, mit den Aufrührern gebunden, die bei dem Aufruhr einen Mord begangen hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'Und das Volk zog hinauf und fing an ihn zu bitten, daß er ihnen täte, wie immer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Pilatus aber antwortete ihnen und sprach: Wollet ihr, daß ich euch den König der Juden losgebe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Denn er erkannte, daß die Hohenpriester Ihn aus Neid überantwortet hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Aber die Hohenpriester wiegelten das Gedränge auf, daß er ihnen eher Barabbas losgäbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilatus aber antwortete und sprach wiederum zu ihnen: Was wollet ihr denn, daß ich mit Dem tue, Den ihr den König der Juden nennt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Sie aber schrien wieder: Kreuzige Ihn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Pilatus aber sprach zu ihnen: Was hat Er denn Böses getan? Sie aber schrien noch mehr: Kreuzige Ihn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilatus aber war willens, dem Gedränge ein Genüge zu tun, und gab ihnen Barabbas los und überantwortete Jesus, nachdem er Ihn gegeißelt, daß Er gekreuzigt würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'Die Kriegsknechte aber führten Ihn ab, hinein in den Hof, der das Prätorium ist, und riefen die ganze Kohorte zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'Und sie zogen Ihm einen Purpur an, und flochten eine Dornenkrone und setzten sie Ihm auf;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'Und fingen an, Ihn zu grüßen: Gegrüßet seist Du, König der Juden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'Und schlugen Ihn mit einem Rohr auf das Haupt, und spieen Ihn an, und fielen auf die Knie und beteten Ihn an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'Und da sie Ihn verspottet hatten, zogen sie Ihm den Purpur aus, und zogen Ihm Seine eigenen Kleider an, und führten Ihn hinaus, daß sie Ihn kreuzigten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'Und sie nötigten einen, Simon von Kyrene, den Vater des Alexander und Rufus, der vorüberging und vom Felde kam, daß er Ihm das Kreuz trüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'Und sie führten Ihn auf die Stätte Golgatha, das ist verdolmetscht Schädelstätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'Und sie gaben Ihm Myrrhenwein zu trinken, Er aber nahm ihn nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'Und da sie Ihn gekreuzigt hatten, zerteilten sie Seine Kleider, indem sie das Los über sie warfen, wer etwas nehmen solle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Es war aber die dritte Stunde, und sie kreuzigten Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'Und über Ihm war geschrieben die Überschrift von dem, wessen man Ihm Schuld gab: Der König der Juden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'Und mit Ihm kreuzigten sie zwei Räuber, einen zur Rechten, und einen Ihm zur Linken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'Und die Schrift ward erfüllt, die da sagt: Er ward unter die Missetäter gerechnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'Und die da vorübergingen, lästerten Ihn, schüttelten ihre Köpfe und sagten: Ei, Du, Der Du den Tempel niedereißest und in drei Tagen bauest,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'Rette Dich nun Selber und steige herab vom Kreuz!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Desgleichen spotteten auch die Hohenpriester untereinander mit den Schriftgelehrten und sagten: Er hat anderen geholfen, Sich Selber kann Er nicht helfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Der Christus, der König von Israel! Er steige jetzt herab von dem Kreuz, auf daß wir es sehen und glauben! Auch die mit Ihm Gekreuzigten schmähten Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'Da es aber die sechste Stunde geworden, ward eine Finsternis über das ganze Land bis zur neunten Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'Und um die neunte Stunde schrie Jesus mit großer Stimme und sprach: Elohi, Elohi, lammah sabachthani!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'Und etliche der Dabeistehenden, die dies hörten, sprachen: Siehe, Er ruft dem Elias!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Einer aber lief und füllte einen Schwamm mit Essig, legte ihn um ein Rohr, tränkte Ihn, und sagte: Lasset mich, wir wollen sehen, ob Elias kommt, Ihn herbzunehmen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Jesus aber schrie mit großer Stimme und hauchte aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'Und der Vorhang des Tempels riß entzwei von oben bis unten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Der Hauptmann aber, der dabeistand, Ihm gegenüber, sprach, als Er mit solchem Schrei verschied: Wahrhaftig, dieser Mensch war Gottes Sohn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Es waren aber auch Weiber da, die von ferne zuschauten, unter denen war Maria von Magdala, und Maria, des jüngeren Jakobus und des Joses Mutter, und Salome;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'Die Ihm auch, da Er in Galiläa war, nachfolgten und Ihm dienten, und viele andere, die mit Ihm herauf nach Jerusalem gekommen waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'Und da es schon Abend ward,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'Kam Joseph von Arimathäa, ein angesehener Ratsherr, der auch selbst auf das Reich Gottes wartete; der wagte es und ging hinein zu Pilatus und bat um den Leib Jesu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilatus aber wunderte sich, daß Er schon gestorben wäre, und rief den Hauptmann zu sich und fragte ihn, ob Er schon eine Zeit lang gestorben wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'Und da er es vom Hauptmann erfahren, schenkte er Joseph den Leib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'Und er kaufte eine Leinwand, und nahm Ihn herab, wickelte Ihn in die Leinwand, und legte Ihn in eine Gruft, die aus einem Felsen gehauen war, und wälzte einen Stein auf die Tür der Gruft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Aber Maria von Magdala und Maria, des Joses Mutter, schauten, wo Er hingelegt wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'Und als der Sabbath vorüber war, kauften Maria von Magdala und Maria, die Mutter des Jakobus, und Salome Spezereien, auf daß sie kämen und Ihn salbten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'Und sehr früh, am ersten Tage nach dem Sabbath, kamen sie zur Gruft, da die Sonne aufging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'Und sprachen untereinander: Wer wird uns den Stein von der Türe der Gruft wälzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'Wie sie aber aufblickten, erschauen sie, daß der Stein schon weggewälzt war; denn er war sehr groß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'Und wie sie in die Gruft hineinkamen, sahen sie einen Jüngling zur Rechten sitzen, der war mit einem weißen Gewande angetan, und sie wurden bestürzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'Er aber sprach zu ihnen: Seid nicht bestürzt! Ihr suchet Jesus, den Nazarener, den Gekreuzigten. Er ist auferweckt! Er ist nicht hier! Siehe den Ort, da sie Ihn hinlegten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Gehet aber hin und sagt es Seinen Jüngern und Petrus, daß Er euch vorangeht nach Galiläa. Dort werdet ihr Ihn sehen, wie Er euch gesagt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'Und sie gingen schnell hinaus und flohen aus der Gruft; es war sie aber ein Zittern und Entsetzen angekommen, und sie sagten niemand etwas; denn sie fürchteten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Da Er aber am Morgen am ersten des Sabbaths war auferstanden, erschien Er zuerst der Maria von Magdala, von der Er sieben Dämonen ausgetrieben hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Sie ging und sagte es denen an, die mit Ihm gewesen waren; die trauerten und weinten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'Und selbige, da sie hörten, daß Er lebe und von ihr gesehen worden sei, glaubten nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Danach aber offenbarte Er Sich zweien von ihnen unter anderer Gestalt, da sie wandelten und über Feld gingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'Und selbige gingen hin und sagten es den übrigen an; auch ihnen glaubten sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Danach, als die Elf zu Tische lagen, offenbarte Er Sich und schalt ihren Unglauben und ihre Herzenshärtigkeit, daß sie denen, die Ihn auferweckt gesehen, nicht geglaubt hätten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'Und Er sprach zu ihnen: Gehet hin in alle Welt und predigt das Evangelium aller Kreatur.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Wer da glaubt und getauft wird, der wird gerettet werden, wer aber nicht geglaubt hat, der wird verdammt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Denen aber, die da glauben, werden diese Zeichen folgen: Sie werden in Meinem Namen Dämonen austreiben, mit neuen Zungen reden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'Schlangen aufheben, und wenn sie etwas Tödliches trinken, wird es ihnen nicht schaden; auf die Siechen werden sie die Hände auflegen, so werden sie gesund werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'Der Herr aber, nachdem Er zu ihnen geredet hatte, ward aufgehoben in den Himmel und sitzet zur Rechten Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Jene aber gingen aus und predigten aller Orten, und der Herr wirkte mit ihnen und bekräftigte das Wort durch die darauffolgenden Zeichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Sintemal es viele unternommen haben, eine Erzählung der bei uns sich erfüllten Dinge darzustellen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'Wie solche uns überliefert haben, die von Anfang an Augenzeugen und Diener des Wortes geworden sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'So schien es auch mir gut, nachdem ich alles von Anbeginn genau verfolgt hatte, solches für dich, bester Theophilus, der Reihe nach zu schreiben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'Auf daß du über die Worte, in denen du unterrichtet worden, Gewißheit erfahrest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'In den Tagen Herodes, König von Judäa, war ein Priester mit Namen Zacharias, von der Abteilung Abiah, und sein Weib war von den Töchtern Aharons, und ihr Name war Elisabeth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Sie waren aber beide gerecht vor Gott und wandelten untadelhaft in allen Geboten und Rechten des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'Und sie hatten kein Kind, weil Elisabeth unfruchtbar und beide in ihren Tagen vorgeschritten waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Und es geschah, als er nach der Ordnung seiner Abteilung den Priesterdienst hatte vor Gott,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'Daß ihn nach der Gewohnheit des Priestertums das Los traf, zu räuchern, und er ging hinein in den Tempel des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'Und die ganze Menge des Volkes war draußen und betete zur Stunde der Räucherung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Es erschien ihm aber der Engel des Herrn, der stand zur Rechten des Rauchaltars.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'Und Zacharias erbebte, als er ihn sah, und eine Furcht fiel auf ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Der Engel aber sprach zu ihm: Fürchte dich nicht, Zacharias! denn dein Flehen ist erhört, und dein Weib Elisabeth wird dir einen Sohn gebären, und du sollst seinen Namen Johannes heißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'Und er wird dir zur Freude und zum Frohlocken sein; und viele werden ob seiner Geburt sich freuen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Denn er wird groß sein vor dem Herrn; und Wein und starke Getränke wird er nicht trinken, und vom Heiligen Geist erfüllt werden noch im Leibe seiner Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'Und wird viele der Söhne Israels zum Herrn, ihrem Gott, bekehren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Und er wird vorangehen vor Ihm, in dem Geist und der Kraft des Elias, die Herzen der Väter zu den Kindern und Ungehorsame zur Gesinnung der Gerechten zu bekehren, zu bereiten dem Herrn ein zugerüstetes Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Und Zacharias sprach zu dem Engel: Woran soll ich das erkennen? Denn ich bin alt und mein Weib ist vorgeschritten in ihren Tagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'Und der Engel antwortete und sprach zu ihm: Ich bin Gabriel, der vor Gott steht, und bin gesandt, zu dir zu reden und dir diese gute Botschaft zu bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'Und siehe, du wirst stilleschweigen und nicht reden können bis zu dem Tage, da dies geschieht, darum, daß du nicht geglaubt hast meinen Worten, die zu ihrer bestimmten Zeit erfüllt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'Und das Volk wartete auf Zacharias und verwunderte sich, daß er im Tempel verzog.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Als er aber herauskam, konnte er nicht zu ihnen reden; und sie erkannten, daß er im Tempel eine Erscheinung gesehen hatte; und er winkte ihnen und verblieb stumm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'Und es geschah, da die Tage seines Amtes erfüllt waren, ging er hin in sein Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'Nach diesen Tagen aber empfing Elisabeth, sein Weib, und verbarg sich fünf Monate, indem sie sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'Also hat mir der Herr getan in den Tagen, da Er mich ansah, und meine Schmach unter den Menschen von mir wegnahm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'Im sechsten Monat aber ward der Engel Gabriel von Gott gesandt in eine Stadt in Galiläa, mit Namen Nazareth,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'Zu einer Jungfrau, die verlobt war einem Manne namens Joseph vom Hause Davids. Und der Name der Jungfrau war Maria.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, 'Und da der Engel zu ihr eintrat, sprach er: Gegrüßet seiest du, Begnadigte! Der Herr ist mit dir, du Gesegnete unter den Weibern!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Da sie ihn aber sah, erbebte sie über sein Wort und bedachte, was das für ein Gruß wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'Und der Engel sprach zu ihr: Fürchte dich nicht, Maria; denn du hast Gnade gefunden bei Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'Und siehe, du wirst empfangen im Leibe und einen Sohn gebären, und du sollst Seinen Namen Jesus heißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Der wird groß sein und der Sohn des Höchsten heißen, und der Herr Gott wird Ihm den Thron Davids, seines Vaters, geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'Und Er wird König sein über das Haus Jakobs in die Ewigkeiten, und Seines Königtums wird kein Ende sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Maria aber sprach zu dem Engel: Wie soll das sein, sintemal ich keinen Mann kenne?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'Und der Engel antwortete und sprach zu ihr: Der Heilige Geist wird über dich kommen, und die Kraft des Höchsten wird dich überschatten; darum wird auch das Heilige, das aus dir geboren wird, Sohn Gottes heißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'Und siehe, Elisabeth, deine Verwandte, hat auch einen Sohn empfangen in ihrem Alter, und dies ist bei ihr, die unfruchtbar hieß, der sechste Monat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Denn bei Gott ist kein Ding unmöglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Maria aber sprach: Siehe, die Magd des Herrn. Mir geschehe nach deiner Rede. Und der Engel ging weg von ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Maria aber stand in selbigen Tagen auf und ging mit Eile ins Gebirge, in eine Stadt in Judah;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'Und kam in das Haus des Zacharias und grüßte Elisabeth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'Und es geschah, als Elisabeth den Gruß Marias hörte, hüpfte das Kindlein in ihrem Leib; und Elisabeth ward vom Heiligen Geist erfüllt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'Und rief aus mit großer Stimme und sprach: Gesegnet bist du unter den Weibern, und gesegnet die Frucht deines Leibes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'Und woher ist mir das, daß die Mutter meines Herrn zu mir kommt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Denn siehe, wie mir die Stimme deines Grußes in meine Ohren drang, hüpfte frohlockend das Kindlein in meinem Leib!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'Und selig bist du, die du geglaubt hast, daß, was zu dir vom Herrn geredet worden, vollbracht werden wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'Und Maria sprach: Meine Seele erhebet den Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'Und mein Geist frohlocket über Gott, meinen Heiland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'Daß Er die Niedrigkeit Seiner Magd hat angesehen; denn siehe, von nun an werden alle Geschlechter mich selig preisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'Denn Großes hat an mir getan, Der da Kraft hat, und heilig ist Sein Name.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'Und Seine Barmherzigkeit ist in die Geschlechter der Geschlechter für die, so Ihn fürchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Er übet Macht mit Seinem Arm; Er zerstreut, die hoffärtig sind in der Gesinnung ihres Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Er bringt die Gewalthaber herab von den Thronen und erhöht die Niedrigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Er füllt die Hungernden mit Gutem, und sendet die Reichen leer hinweg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Er nimmt Sich an Seines Dieners Israel, daß Er gedächte der Barmherzigkeit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Wie Er geredet hat zu unseren Vätern, dem Abraham und seinem Samen in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Maria aber blieb bei ihr bei drei Mona- ten, und sie kehrte zurück in ihr Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'Elisabeth aber ward die Zeit erfüllt, daß sie gebären sollte, und sie gebar einen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'Und ihre Nachbarn und ihre Verwandten hörten, daß der Herr Seine große Barmherzigkeit an ihr getan, und freuten sich mit ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'Und es geschah am achten Tage, daß sie kamen, das Kindlein zu beschneiden, und sie hießen ihn nach seines Vaters Namen Zacharias.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'Und seine Mutter antwortete und sprach: Mitnichten, sondern Johannes soll er heißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'Und sie sprachen zu ihr: Es ist niemand in deiner Verwandtschaft, der nach diesem Namen hieße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'Sie winkten aber seinem Vater, wie er ihn wollte heißen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'Und er bat um ein Täfelchen und schrieb und sprach: Johannes ist sein Name. Und sie verwunderten sich alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'Und zugleich ward ihm der Mund aufgetan und seine Zunge, und er redete und segnete Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'Und es kam eine Furcht auf alle, die um sie her wohnten, und in dem ganzen Gebirge Judäas redete man über alle diese Dinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'Und alle, die es hörten, nahmen es sich zu Herzen und sagten: Was wird wohl aus diesem Kindlein werden? Denn die Hand des Herrn war mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'Und sein Vater Zacharias ward vom Heiligen Geiste erfüllt, weissagte und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Gesegnet sei der Herr, der Gott Israels! Denn Er hat heimgesucht und Erlösung bereitet Seinem Volke,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'Und uns auferweckt ein Horn des Heils im Hause Davids, Seines Dieners,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, 'Wie Er geredet hat durch den Mund Seiner heiligen Propheten von Ewigkeit her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'Zur Rettung von unseren Feinden und aus der Hand aller, die uns hassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'Und Barmherzigkeit an unseren Vätern zu tun, und Seines heiligen Bundes zu gedenken,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'Des Eides, den Er Abraham, unserem Vater, geschworen hat, uns zu geben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'Daß wir ohne Furcht, entrissen aus der Hand unserer Feinde, Ihm dienten');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'In Heiligkeit und Gerechtigkeit vor Seinem Angesicht all unsere Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'Und du, Kindlein, wirst ein Prophet des Höchsten heißen; denn du wirst vorangehen vor dem Angesicht des Herrn, daß du Ihm Seine Wege bereitest;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'Und Erkenntnis des Heils gebest Seinem Volke zur Vergebung ihrer Sünden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'Durch die innige Barmherzigkeit unseres Gottes, mit der uns heimgesucht hat der Aufgang aus den Höhen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'Auf daß Er erschiene denen, die da sitzen in der Finsternis und im Schatten des Todes, um unsere Füße auf den Weg des Friedens zu richten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Das Knäblein aber wuchs und ward mächtig im Geist; und er war in den Wüsten bis zu dem Tage, da er sich vor Israel zeigen sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'In selbigen Tagen aber geschah es, daß vom Kaiser Augustus eine Vorschrift ausging, daß der ganze Erdkreis sich sollte schätzen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'Diese Schätzung war die erste, da Quirinius Landpfleger in Syrien war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'Und es gingen alle, sich schätzen zu lassen, jeder in seine eigene Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Joseph aber ging auch hinauf aus Galiläa, aus der Stadt Nazareth nach Judäa in die Stadt Davids, welche Bethlehem heißt, weil er aus dem Haus und dem Geschlechte Davids war,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'Um sich mit Maria, seinem verlobten Weibe, welche schwanger war, schätzen zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Es geschah aber, als sie daselbst waren, daß die Tage erfüllt wurden, da sie gebären sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'Und sie gebar ihren erstgeborenen Sohn, und wickelte Ihn in Windeln und legte Ihn hin in die Krippe, weil sie keinen Platz in der Herberge hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'Und es waren in selbiger Gegend Hirten auf dem Felde, die hüteten der Hut ihrer Herde bei Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'Und siehe, des Herrn Engel stand bei ihnen, und die Herrlichkeit des Herrn umleuchtete sie; und sie fürchteten sich mit großer Furcht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'Und der Engel sprach zu ihnen: Fürchtet euch nicht! Denn siehe, ich verkündige euch große Freude, die allem Volk sein wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Denn heute ist euch ein Heiland geboren, Welcher ist Christus der Herr, in der Stadt Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'Und das habt zum Zeichen: Ihr werdet finden ein Kindlein in Windeln gewickelt und in einer Krippe liegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'Und plötzlich war bei dem Engel die Menge der himmlischen Heerscharen, die lobten Gott und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Ehre sei Gott in den Höhen und Frieden auf Erden, unter Menschen ein Wohlgefallen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'Und es geschah, da die Engel von ihnen gen Himmel weggingen, sagten auch die Menschen, die Hirten, zueinander: Lasset uns hingehen nach Bethlehem und sehen die Geschichte, die dort geschehen ist, die der Herr uns hat kundgetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'Und sie kamen eilig und fanden beide, Maria und Joseph; dazu das Kindlein in der Krippe liegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Als sie es aber gesehen, machten sie kund die Rede, die über dieses Kindlein zu ihnen war geredet worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'Und alle, die es hörten, verwunderten sich über das, was die Hirten zu ihnen redeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Maria aber behielt alle diese Reden und erwog sie in ihrem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'Und die Hirten kehrten zurück, verherrlichten und lobten Gott über alles, das sie gehört und gesehen hatten, wie es zu ihnen geredet war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'Und da die acht Tage erfüllt waren, um das Kindlein zu beschneiden, war Sein Name geheißen Jesus, wie Er vom Engel war gehei-ßen worden, ehe denn Er im Mutterleib empfangen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'Und da die Tage ihrer Reinigung nach dem Gesetze des Moses erfüllt waren, brachten sie Ihn hinauf gen Jerusalem, um Ihn dem Herrn darzustellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'Wie im Gesetze des Herrn ist geschrieben: Jegliches Männliche, das den Mutterschoß auftut, soll dem Herrn geheiligt heißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'Und das Opfer zu geben, nach dem, so im Gesetze des Herrn gesagt ist: Ein Paar Turteltauben, oder zwei junge Tauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'Und siehe, da war ein Mensch in Jerusalem, mit Namen Simeon; und dieser Mensch war gerecht und gottesfürchtig, und wartete auf den Trost Israels; und der Heilige Geist war auf ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'Und ihm war vom Heiligen Geiste eine Antwort geworden, er werde den Tod nicht sehen, er hätte denn zuvor den Christ des Herrn gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'Und er kam im Geiste in das Heiligtum; und als die Eltern des Knäblein Jesus hereinbrachten, auf daß sie für Ihn täten, wie man pflegt nach dem Gesetz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'Da nahm er Ihn in seine Arme, und segnete Gott und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Nun entlässest Du Deinen Knecht im Frieden, o Herr, nach Deiner Rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'Denn meine Augen haben Dein Heil gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'Welches Du Angesichts aller Völker bereitet hast,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'Ein Licht zur Offenbarung für die Völkerschaften und zur Herrlichkeit Deines Volkes Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'Und Sein Vater und Seine Mutter verwunderten sich über das, was von Ihm geredet wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'Und Simeon segnete sie und sprach zu Maria, Seiner Mutter: Siehe, Dieser liegt da zum Falle und zum Auferstehen vieler in Israel und zu einem Zeichen, dem widersprochen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, 'Und ein Schwert wird dir durch deine Seele hindurchgehen, auf daß aus vielen Herzen die Gedanken offenbar werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'Es war auch da Hannah, eine Prophetin, eine Tochter Phanuels, vom Stamm Asser, die war in viele Tage vorgerückt, und hatte sieben Jahre mit einem Manne gelebt nach ihrer Jungfrauschaft;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'Und war eine Witwe bei vierundachtzig Jahren und wich nicht vom Heiligtum, und diente mit Fasten und Flehen Nacht und Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'Auch sie stand dabei zu der Stunde, lobpreiste den Herrn und redete von Ihm zu allen, die in Jerusalem auf die Erlösung warteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'Und da sie alles nach dem Gesetze des Herrn vollendet hatten, kehrten sie zurück nach Galiläa in ihre Stadt Nazareth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'Das Knäblein aber wuchs und ward mächtig am Geist, erfüllt mit Weisheit, und die Gnade Gottes war auf Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'Und es gingen Seine Eltern jedes Jahr gen Jerusalem auf das Paschafest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'Und da Er zwölf Jahre wurde, da sie nach der Gewohnheit des Festes hinauf gen Jerusalem gingen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'Und da sie die Tage vollbracht hatten und zurückkehrten, blieb der Knabe Jesus zurück in Jerusalem, und Joseph und Seine Mutter wußten es nicht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Dachten aber, Er wäre in der Reisegesellschaft, und kamen eines Tages Weg, und suchten Ihn unter den Verwandten und Bekannten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'Und da sie Ihn nicht fanden, kehrten sie zurück gen Jerusalem und suchten Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'Und es geschah nach dreien Tagen, daß sie Ihn fanden im Heiligtum, wie Er inmitten der Lehrer saß und ihnen zuhörte und sie fragte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Es waren aber alle, die Ihn hörten, außer sich über Seinen Verstand und Seine Antworten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'Und da sie Ihn sahen, staunten sie, und Seine Mutter sprach zu Ihm: Kind, warum hast Du uns das getan? Siehe, Dein Vater und ich haben Dich mit Schmerzen gesucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'Und Er sprach zu ihnen: Was ist es, daß ihr Mich suchtet? Wußtet ihr nicht, daß Ich sein muß in dem, das Meines Vaters ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'Und sie verstanden nicht die Rede, die Er zu ihnen redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Und Er zog mit ihnen hinab und kam gen Nazareth und war ihnen untertan. Und Seine Mutter behielt alle diese Reden in ihrem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'Jesus aber nahm zu an Weisheit und an Wuchs und Gnade bei Gott und den Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Im fünfzehnten Jahre aber der Regierung des Kaisers Tiberius, da Pontius Pilatus Landpfleger war von Judäa, und Herodes Vierfürst von Galiläa, sein Bruder, Philippus, aber Vierfürst von Ituräa und von der Gegend Trachonitis, und Lysanias Vierfürst von Abilene.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'Unter den Hohenpriestern Hannas und Kajaphas geschah die Rede Gottes zu Johannes, dem Sohn des Zacharias, in der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'Und er kam in all die Umgegend des Jordan und predigte die Taufe der Buße zur Vergebung der Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'Wie geschrieben ist im Buch der Worte des Propheten Jesajas, der da sagt: Die Stimme eines Rufenden in der Wüste: Bereitet den Weg des Herrn, machet Seine Pfade gerade!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Jegliches Tal soll ausgefüllt und aller Berg und Hügel erniedrigt, und was krumm ist, soll gerade, und was rauh ist, zu ebenen Wegen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'Und alles Fleisch soll das Heil Gottes sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Er sprach nun zu dem Gedränge, das herauszog, um sich von ihm taufen zu lassen: Ihr Otterngezüchte, wer hat euch gewiesen, vor dem kommenden Zorn zu fliehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'So tut nun würdige Früchte der Buße und fanget nicht an, in euch zu sagen: Wir haben Abraham zum Vater; denn ich sage euch: Gott kann aus diesen Steinen dem Abraham Kinder erwecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Schon ist aber auch die Axt den Bäumen an die Wurzel gelegt. Jeglicher Baum nun, der nicht gute Frucht trägt, wird abgehauen und ins Feuer geworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'Und es fragte ihn das Gedränge und sprach: Was sollen wir denn tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Er antwortete aber und sprach zu ihnen: Wer zwei Röcke hat, der gebe dem ab, der keinen hat, und wer Speise hat, der tue ähnliches.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Es kamen aber auch Zöllner, sich taufen zu lassen, und sprachen zu ihm: Lehrer, was sollen wir tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'Er aber sprach zu ihnen: Fordert nicht mehr ein, denn euch verordnet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Es fragten ihn aber auch Kriegsleute und sagten: Und was sollen wir tun? Und er sprach zu ihnen: Tut niemand Gewalt an und gebet niemand fälschlich an, und lasset euch an eurem Solde genügen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Da das Volk aber in Erwartung war, und alle in ihrem Herzen von Johannes dachten, ob er nicht Christus wäre,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'Antwortete Johannes allen und sprach: Ich taufe euch zwar mit Wasser; aber es kommt ein Stärkerer denn ich, Dem ich nicht genugsam bin, die Riemen Seiner Schuhe zu lösen, Der wird euch mit Heiligem Geiste und mit Feuer taufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'Der hat die Wurfschaufel in Seiner Hand, und wird Seine Tenne fegen, und den Weizen in Seine Scheune sammeln, die Spreu aber mit unauslöschlichem Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Vieles nun, auch anderes ermahnte er das Volk, da er die gute Botschaft verkündete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Der Vierfürst Herodes aber, der von ihm gerügt ward ob Herodias, seines Bruders Weib, und ob all des Übels, das Herodes getan,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'Tat zu dem allen auch dieses hinzu, daß er den Johannes ins Gefängnis einschloß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Es geschah aber, da alles Volk sich taufen ließ, und Jesus Sich taufen ließ und betete, daß sich der Himmel auftat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'Und der Heilige Geist in leibhafter Gestalt wie eine Taube auf Ihn herabstieg, und eine Stimme vom Himmel geschah und sprach: Du bist Mein geliebter Sohn! An Dir habe Ich Wohlgefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'Und Jesus Selbst war bei dreißig Jahren alt, da Er anfing, und war, wie man dachte, ein Sohn Josephs, des Eli,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Des Matthat, des Levi, des Melchi, des Jannah, des Joseph;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Des Mattathiah, des Amos, des Nahum, des Esli, des Naggai;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Des Maath, des Mattathiah, des Semei, des Joseph, des Judah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Des Johannah, des Resa, des Zorobabel, des Salathiel, des Neri;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Des Melchi, des Addi, des Kosam, des Elmodam, des Er,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Des Jose, des Elieser, des Jorim, des Matthat, des Levi,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'Des Simeon, des Judah, des Joseph, des Jonan, des Eliakim,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Des Melea, des Mainan, des Mattatha, des Nathan, des David,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Des Isai, des Obed, des Boas, des Salmon, des Nahasson,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Des Amminadab, des Aram, des Esrom, des Perez, des Judah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Des Jakob, des Isaak, des Abraham, des Tharah, des Nachor,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Des Seruch, des Regu, des Peleg, des Eber, des Selah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Des Kainan, des Arphachschad, des Sem, des Noach, des Lamech,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Des Methusalach, des Henoch, des Jared, des Maleleel, des Kainan,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Des Enosch, des Seth, des Adam, der war Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Jesus aber, voll des Heiligen Geistes, kehrte zurück vom Jordan und ward vom Geist in die Wüste geführt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'Und ward vierzig Tage vom Teufel versucht; und aß nichts in selbigen Tagen; und als sie vollendet waren, hungerte Ihn danach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'Und der Teufel sprach zu Ihm: Wenn Du Gottes Sohn bist, so sprich zu diesem Steine, daß er Brot werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'Und Jesus antwortet ihm und sprach: Es ist geschrieben: Der Mensch lebt nicht vom Brot allein, sondern von jeglicher Rede Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'Und der Teufel führte Ihn auf einen hohen Berg und zeigte Ihm alle Reiche des Erdkreises in einem Augenblick der Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'Und der Teufel sprach zu Ihm: All diese Gewalt will ich Dir geben und ihre Herrlichkeit; denn mir ist sie übergeben, und ich gebe sie, wem ich will:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'So Du nun vor mir anbetest, soll es alles Dein sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'Und Jesus antwortete ihm und sprach: Gehe weg hinter Mich, Satanas. Es ist geschrieben: Du sollst den Herrn, deinen Gott, anbeten und Ihm allein dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'Und er führte Ihn gen Jerusalem und stellte Ihn auf die Zinne des Heiligtums und sprach zu Ihm: Bist du Gottes Sohn, so wirf Dich von hinnen hinab;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'Denn es ist geschrieben: Er wird Seinen Engeln über Dir gebieten, daß sie Dich bewahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'Und auf den Händen sollen sie Dich tragen, daß Du Deinen Fuß nicht an einen Stein stoßest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'Und Jesus antwortete und sprach zu ihm: Es ist gesagt: Du sollst den Herrn, deinen Gott, nicht versuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'Und da der Teufel alle Versuchung vollendet hatte, wich er auf einige Zeit von Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'Und Jesus kehrte in des Geistes Kraft nach Galiläa zurück und das Gerücht über Ihn ging aus in die ganze Umgegend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'Und Er Selbst lehrte in ihren Synagogen, von jedermann verherrlicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'Und Er kam gen Nazareth, wo Er erzogen ward, und ging nach Seiner Gewohnheit am Tage der Sabbathe in die Synagoge und stand auf, um zu lesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'Und man übergab Ihm das Buch des Propheten Jesajas, und Er schlug das Buch auf und fand den Ort, wo geschrieben ist:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, 'Der Geist des Herrn ist auf Mir, darum hat Er Mich gesalbt, daß Ich den Armen die gute Botschaft verkündige, Er hat Mich gesandt, gesund zu machen, die zerknirschten Herzens sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'Zu verkündigen den Gefangenen Freisetzung und den Blinden, daß sie wieder sehen sollen, die Zerschlagenen freigesetzt auszusenden, das angenehme Jahr des Herrn zu verkündigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'Und Er tat das Buch zu, gab es dem Diener zurück und setzte Sich nieder; und aller Augen in der Synagoge sahen fest auf Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'Er aber fing an zu ihnen zu sprechen: Heute ist diese Schrift vor euren Ohren erfüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'Und alle gaben Ihm Zeugnis und verwunderten sich über die Worte der Gnade, die aus Seinem Munde ausgingen, und sprachen: Ist das nicht Josephs Sohn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'Und Er sprach zu ihnen: Ihr werdet allerdings zu Mir sagen das Gleichnis: Arzt, heile dich selber. Welche große Dinge wir von Dir, als in Kapernaum geschehen, gehört haben, die tue auch hier in Deiner Vaterstadt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Aber Er sprach: Wahrlich sage Ich euch: Kein Prophet ist angenehm in seiner Vaterstadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'In Wahrheit aber sage Ich euch: Viele Witwen waren in Israel in den Tagen des Elias, da der Himmel für drei Jahre und sechs Monate verschlossen war, so daß eine große Hun- gersnot im ganzen Lande war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'Und keiner von ihnen ward Elias gesandt, als nach Sarepta im Sidonischen, zu einer Frau, die eine Witwe war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'Und viele Aussätzige waren in Israel unter dem Propheten Elischa und keiner von ihnen ward gereinigt, als der Syrer Naeman.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'Und alle in der Synagoge, als sie dies hörten, wurden von Grimm erfüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'Und standen auf und warfen Ihn zur Stadt hinaus und führten Ihn an den Abhang des Berges, auf dem ihre Stadt gebaut war, um Ihn hinabzustürzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Aber Er ging mitten durch sie und ging hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'Und Er kam hinab nach Kapernaum, einer Stadt in Galiläa, und lehrte sie an den Sabbathen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'Und sie staunten über Seine Lehre; denn Sein Wort war mit Gewalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'Und in der Synagoge war ein Mensch, der hatte den Geist eines unreinen Dämons, und schrie auf mit großer Stimme:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'Und sagte: Laß ab, was haben wir mit Dir zu schaffen, Jesus von Nazareth? Du bist gekommen, uns zu verderben. Ich weiß, wer Du bist - der Heilige Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'Und Jesus bedrohte ihn und sprach: Verstumme und fahre aus von ihm! Und der Dämon warf ihn hin mitten unter sie, fuhr aus von ihm, und tat ihm keinen Schaden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'Und sie alle waren in Bestürzung, und sie unterredeten sich miteinander und sagten: Was ist dies Wort? Er gebietet mit Gewalt und Kraft den unreinen Geistern und sie fahren aus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'Und das Gerücht über Ihn ging aus in jeden Ort der Umgegend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Er aber stand auf und kam von der Synagoge in Simons Haus. Siemons Schwiegermutter aber war mit einem heftigen Fieber behaftet, und sie baten Ihn für sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'Und Er stand über Ihr, bedrohte das Fieber, und es verließ sie. Sie aber stand sogleich auf und bediente sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Als aber die Sonne unterging, brachten alle die, so Sieche hatten, mit allerlei Krankheiten behaftet, dieselben zu Ihm. Er aber legte einem jeglichen von ihnen die Hände auf und heilte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Es gingen aber auch von vielen Dämonen aus, die schrien und sprachen: Du bist Christus, der Sohn Gottes. Und Er bedrohte sie und ließ sie nicht reden, weil sie wußten, daß Er Christus war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Da es aber Tag ward, ging Er hinaus und kam an einen wüsten Ort; und das Volk suchte Ihn, und sie kamen zu Ihm und hielten Ihn auf, daß Er nicht sollte von ihnen gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'Er aber sprach zu ihnen: Auch den anderen Städten muß Ich die gute Botschaft von dem Reiche Gottes verkünden; denn dazu bin Ich ausgesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'Und Er predigte in den Synagogen von Galiläa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Es geschah aber, daß die Menge Ihn drängte, um das Wort Gottes zu hören; und Er stand am See Gennesareth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'Und Er sah zwei Schifflein am See stehen; die Fischer aber waren davon ausgestiegen und wuschen die Netze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'Er stieg aber in der Schifflein eines, das des Simon war, und bat ihn, ein wenig vom Lande abzufahren, und Er setzte Sich und lehrte vom Schifflein aus das Gedränge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'Als Er aber zu reden aufhörte, sprach Er zu Simon: Fahre ab auf die Tiefe und lasset da eure Netze hinab zum Fang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'Und Simon antwortete und sprach zu Ihm: Meister, die ganze Nacht über mühten wir uns ab und fingen nichts; auf Deine Rede aber will ich das Netz hinablassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'Und als sie es getan, umschlossen sie eine große Menge Fische, aber ihr Netz zerriß;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'Und sie winkten ihren Mitgenossen im anderen Schifflein zu, sie sollten kommen und ihnen mithelfen; und sie kamen und füllten beide Schifflein, also daß sie gar tief gingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Als aber Simon Petrus dies sah, fiel er zu den Knien Jesu und sprach: Herr, gehe von mir hinaus; denn ich bin ein sündiger Mann!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Denn eine Bestürzung erfaßte ihn und alle, die mit ihm waren, über dem Fange der Fische, den sie gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'Desgleichen auch den Jakobus und den Johannes, die Söhne des Zebedäus, Simons Teilhaber. Und Jesus sprach zu Simon: Fürchte dich nicht. Von nun an sollst du ein Fänger von Menschen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'Und sie führten die Schifflein ans Land, verließen alles und folgten Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'Und es geschah, als er in einer der Städte war, und siehe, da war ein Mann voll Aussatzes. Und als er Jesus sah, fiel er auf sein Angesicht und flehte Ihn an und sprach: Herr, so Du willst, kannst Du mich reinigen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'Und Er reckte die Hand aus, berührte ihn und sprach: Ich will, sei gereinigt! Und alsbald ging der Aussatz weg von ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'Und Er gebot ihm, daß er es niemand sage, sondern: Gehe hin und zeige dich dem Priester, und bringe für deine Reinigung dar, wie Moses verordnet hat, ihnen zum Zeugnisse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Es ging aber das Wort über Ihn aus; und viel Gedränge kam zusammen, Ihn zu hören, und sich von ihren Gebrechen von Ihm heilen zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'Er aber entwich in die Wüste und betete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'Und es geschah an einem der Tage, daß Er lehrte, und es saßen da Pharisäer und Gesetzlehrer, die aus allen Flecken von Galiläa und Judäa und von Jerusalem gekommen waren, und die Kraft des Herrn war da, daß Er sie gesund machte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'Und siehe, da brachten Männer einen Menschen, der gichtbrüchig war, auf einem Bette, und suchten, wie sie ihn hineinbrächten und vor Ihn legeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'Da sie aber vor dem Gedränge nicht fanden, wie sie ihn hineinbrächten, stiegen sie hinauf auf das Dach und ließen ihn mit dem Bett durch die Ziegel hinab in die Mitte vor Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'Und da Er ihren Glauben sah, sprach Er zu ihm: Mensch, dir sind deine Sünden vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Und die Schriftgelehrten und die Pharisäer fingen an bei sich zu bedenken und sprachen: Wer ist der, daß er Lästerungen redet? Wer kann Sünden vergeben, denn allein Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Da aber Jesus ihre Gedanken erkannte, antwortete Er und sprach zu ihnen: Was bedenket ihr solches in euren Herzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Was ist leichter, zu sagen: Dir sind deine Sünden vergeben, oder zu sagen: Mache Dich auf und wandle?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Auf daß ihr aber wisset, daß des Menschen Sohn Gewalt hat auf Erden, Sünden zu vergeben: Ich sage dir: Mache dich auf, nimm dein Bett auf und gehe in dein Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'Und sogleich stand er auf, vor ihnen, nahm auf, worauf er gelegen, ging in sein Haus und verherrlichte Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'Und Entsetzen erfaßte alle, und sie verherrlichten Gott, und wurden erfüllt von Furcht und sprachen: Wir haben heute Außerordentliches gesehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'Und danach ging Er aus und sah einen Zöllner, mit Namen Levi, am Zollhaus sitzen und sprach zu ihm: Folge Mir nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'Und er verließ alles, stand auf und folgte Ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'Und Levi machte Ihm ein großes Mahl in seinem Hause, und es war viel Gedränge von Zöllnern und anderen, die mit ihnen zu Tische lagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'Und die Pharisäer und die Schriftgelehrten unter ihnen murrten wider Seine Jünger und sprachen: Warum esset und trinket ihr mit den Zöllnern und Sündern?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'Und Jesus antwortete und sprach zu ihnen: Die Gesunden bedürfen des Arztes nicht, sondern die Leidenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Ich bin nicht gekommen, die Gerechten, sondern die Sünder zur Buße zu rufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'Sie aber sprachen zu Ihm: Warum fasten die Jünger des Johannes häufig und machen Gebete, desgleichen auch die der Pharisäer, die Deinigen dagegen essen und trinken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Er aber sprach zu ihnen: Könnet ihr die Söhne des Brautgemachs, solange der Bräutigam bei ihnen ist, fasten lassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Es werden aber Tage kommen, da der Bräutigam von ihnen weggenommen wird, in selbigen Tagen werden sie dann fasten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Er sagte aber auch ein Gleichnis zu ihnen: Niemand setzt ein Flickstück von einem neuen Kleid auf ein altes Kleid; sonst zerreißt er das neue, und mit dem alten stimmt das Flickstück vom neuen nicht zusammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'Auch tut niemand neuen Wein in alte Schläuche; sonst zersprengt der neue Wein die Schläuche, und wird selber verschüttet, und die Schläuche kommen um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'Sondern neuen Wein muß man in neue Schläuche fassen, und beide werden zusammen erhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'Auch will niemand, der alten getrunken, alsbald neuen; denn der alte, sagt er, ist milder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Es geschah aber auf einen Sabbath, den zweiten nach dem ersten, daß Er durch das Saatfeld hindurchging, und Seine Jünger rauften die Ähren aus und aßen sie und zerrieben dieselben mit den Händen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Etliche aber der Pharisäer sprachen zu ihnen: Was tut ihr, das nicht erlaubt ist, an den Sabbathen zu tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'Und Jesus antwortete und sprach zu ihnen: Habt ihr nicht auch das gelesen, was David tat, da ihn hungerte und die mit ihm waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Wie er in das Haus Gottes einging und die Schaubrote nahm und aß, und auch denen, die mit ihm waren, gab, die doch niemandem als den Priestern allein erlaubt ist zu essen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'Und Er sprach zu ihnen: Des Menschen Sohn ist Herr auch des Sabbaths.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'An einem anderen Sabbath aber geschah, daß Er in die Synagoge einging und lehrte. Und da war ein Mensch, und dessen rechte Hand war verdorrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Die Schriftgelehrten und die Pharisäer aber hielten auf Ihn, ob Er am Sabbathe heilen würde, auf daß sie eine Anklage gegen Ihn fänden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'Er aber wußte ihre Gedanken und sprach zu dem Menschen, der die verdorrte Hand hatte: Richte dich auf und stelle dich in die Mitte! Und er stand auf und stand da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Nun sprach Jesus zu ihnen: Ich frage euch: Was ist erlaubt an Sabbathen zu tun, Gutes tun oder Böses tun, das Leben zu retten oder zu verderben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'Und Er blickte auf sie alle umher und sprach zu dem Menschen: Strecke deine Hand aus! Er aber tat also, und seine Hand war wiederhergestellt, gesund, wie die andere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'Sie aber waren ganz von Sinnen, und besprachen sich untereinander, was sie mit Jesus tun wollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'In diesen Tagen aber geschah es, daß Er auf den Berg hinausging, zu beten; und Er war die ganz Nacht hindurch im Gebete zu Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'Und da es Tag ward, rief Er Seine Jünger zu Sich und erwählte aus ihnen zwölf, die Er auch Apostel benannte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simon, den Er auch Petrus benannte, und seinen Bruder Andreas, Jakobus und Johannes, Philippus und Bartholomäus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matthäus und Thomas, Jakobus, den Sohn des Alphäus, und Simon, den man Zelotes hieß;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Judas, des Jakobus Sohn, und Judas Iskarioth, der auch zum Verräter wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'Und mit ihnen stieg Er hinab und stand auf einem ebenen Platz, und ein Gedränge Seiner Jünger und eine große Menge des Volkes aus ganz Judäa und Jerusalem und der Meeresküste von Tyrus und Sidon,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'Die gekommen waren, Ihn zu hören und von ihren Krankheiten zu gesunden, und die von unreinen Geistern bedrängt waren, und sie wurden geheilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'Und all das Gedränge suchte Ihn zu berühren; denn es ging eine Kraft von Ihm aus und machte alle gesund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'Und Er hob Seine Augen auf über Seine Jünger und sprach: Selig seid ihr Armen; denn das Reich Gottes ist euer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Selig seid ihr, die ihr jetzt hungert; denn ihr sollt gesättigt werden. Selig seid ihr, die ihr jetzt weinet; denn ihr sollt lachen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Selig seid ihr, wenn euch die Menschen hassen und wenn sie euch von sich ausscheiden und schmähen und euren Namen als übel verwerfen um des Menschen Sohnes willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Freuet euch am selbigen Tage und hüpfet; denn siehe, eures Lohnes ist viel in dem Himmel; denn also haben ihre Väter den Propheten getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Wehe dagegen euch Reichen; denn ihr habt euren Trost dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Wehe euch, ihr jetzt völlig Gesättigten; denn ihr werdet hungern. Wehe euch, die ihr jetzt lachet; denn ihr werdet trauern und weinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Wehe euch, wenn alle Menschen schön von euch sprechen; denn so taten ihre Väter den falschen Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Euch aber sage Ich, die ihr höret: Liebet eure Feinde; tut wohl denen, die euch hassen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'Segnet, die euch fluchen. Betet für die, so euch beleidigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Dem, der dich schlägt auf den Backen, biete den andern auch dar; und dem, der dir das Oberkleid nimmt, wehre auch den Rock nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Gib jedem, der dich bittet. Und nimmt dir einer das Deine, so fordere es nicht wieder ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'Und wie ihr wollet, daß euch die Menschen tun, tut auch ihr ihnen desgleichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'Und so ihr liebet, die euch lieben, was für Dank habt ihr davon? Denn auch die Sünder lieben die, so sie lieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'Und so ihr Gutes tut denen, die euch Gutes tun, was für Dank habt ihr davon? Dasselbe tun ja auch die Sünder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'Und so ihr leihet denen, von denen ihr es wieder zu empfangen hoffet, was für Dank habt ihr? Denn auch die Sünder leihen den Sündern, auf daß sie das gleiche wieder empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Liebet vielmehr eure Feinde und tut Gutes und leihet, wo ihr nichts dafür hoffet, und eures Lohnes wird viel sein, und ihr werdet Söhne des Höchsten sein; denn Er ist gütig auch gegen die Undankbaren und Schlechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Darum seid mitleidig, wie auch euer Vater mitleidig ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'Und richtet nicht, so werdet ihr auch nicht gerichtet. Verurteilt nicht, so werdet ihr auch nicht verurteilt. Erlasset, so wird auch euch erlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Gebet, so wird euch gegeben. Ein gut, gedrückt und gerüttelt und überflüssig Maß wird man in den Schoß euch geben; denn mit demselben Maß, womit ihr messet, wird man euch wieder messen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Er sagte ihnen aber ein Gleichnis: Kann auch ein Blinder einem Blinden den Weg weisen? Werden nicht beide in die Grube fallen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Ein Jünger ist nicht über seinem Lehrer; ist er aber ganz unterrichtet, so wird er sein gleich wie sein Lehrer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Was blickst du aber auf den Splitter in deines Bruders Auge, gewahrst aber nicht des Balkens im eigenen Auge?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Oder wie kannst du zu deinem Bruder sagen: Bruder, laß mich, ich will dir den Splitter in deinem Auge herausziehen, und du erblickst den Balken in deinem Auge nicht? Du Heuchler, ziehe zuvor den Balken aus deinem Auge heraus, und dann wirst du recht sehen, wie du den Splitter aus deines Bruders Auge herausziehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Denn es ist kein guter Baum, der faule Frucht bringt, noch ein fauler Baum, der gute Frucht bringt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Denn ein jeglicher Baum wird an seiner eigenen Frucht erkannt; denn von Dornen sammelt man nicht Feigen, noch liest man Trauben vom Dornbusch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Der gute Mensch bringt Gutes hervor aus dem guten Schatz seines Herzens, und der schlechte Mensch bringt Schlechtes hervor aus dem schlechten Schatz seines Herzens; denn aus dem Überfließen des Herzens redet der Mensch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Was heißet ihr Mich aber: Herr, Herr! und tuet nicht, was Ich sage?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Wer zu Mir kommt und höret Meine Worte und tut sie, von dem will Ich euch zeigen, wem er ähnlich ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Er ist ähnlich einem Menschen, der ein Haus baute, der ausgrub und tief ging und legte den Grund auf den Felsen. Da aber eine Überschwemmung ward und der Strom sich an selbigem Hause brach, vermochte er es nicht zu erschüttern; denn es war auf den Felsen gegründet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Wer aber hört und nicht tut, der ist ähnlich einem Menschen, der sein Haus ohne Grund auf die Erde baute. An ihm brach sich der Strom, und es fiel alsobald, und der Bruch selbigen Hauses ward groß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Nachdem Er aber alle diese Reden vor den Ohren des Volkes vollendet hatte, ging Er hinein gen Kapernaum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Der Knecht eines Hauptmannes aber, der von diesem geehrt wurde, war leidend und war am Sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Als er aber von Jesus hörte, sandte er Älteste der Juden an Ihn und ließ Ihn bitten, zu kommen und seinen Knecht zu retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Da sie aber zu Jesus herzutraten, flehen sie Ihn angelegentlich an und sprachen: Er ist es würdig, daß Du ihm solches erbietest;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'Denn er liebt unsere Völkerschaft, und er selbst hat uns die Synagoge gebaut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'Jesus aber ging mit ihnen; da Er aber nicht mehr ferne von dem Hause weg war, schickte der Hauptmann Freunde zu Ihm und ließ Ihm sagen: Herr, bemühe Dich nicht; denn ich bin nicht genugsam, daß Du unter mein Dach eingehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Darum habe ich mich auch nicht für würdig erachtet, daß ich zu Dir käme. Sprich aber ein Wort, so wird mein Knecht gesund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Denn auch ich bin ein Mensch, der Obergewalt untertan, und habe Kriegsknechte unter mir; und sage ich zu einem: Gehe hin, so geht er; und zu einem andern: Komm her, so kommt er; und zu meinem Knechte: Tue das, so tut er es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Da aber Jesus solches hörte, verwunderte Er Sich sein, und wandte Sich um zu dem Gedränge, das Ihm nachfolgte, und sprach: Ich sage euch, solchen Glauben habe Ich selbst in Israel nicht gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'Und die Abgesandten kehrten ins Haus zurück und fanden den siechen Knecht gesund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'Und es geschah in der Folge, daß Er in eine Stadt zog, die hieß Nain, und viele Seiner Jünger gingen mit Ihm, und viel Gedränge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Wie Er aber dem Tor der Stadt nahte, siehe, da trug man einen Toten heraus, welcher der einzige Sohn seiner Mutter war, und sie war eine Witwe und ein großes Gedränge aus der Stadt mit ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'Und da sie der Herr sah, jammerte Ihn derselben, und Er sprach zu ihr: Weine nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'Und Er kam hinzu und berührte den Sarg, und die ihn trugen, standen. Und Er sprach: Jüngling, Ich sage dir: Richte dich auf!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'Und der Tote saß auf und fing an zu reden, und Er gab ihn seiner Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Und alle überkam eine Furcht, und sie verherrlichten Gott und sprachen: Ein großer Prophet ist unter uns erwecket, und Gott hat Sein Volk heimgesucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'Und dieses Wort über Ihn ging aus in ganz Judäa und in die ganze Umgegend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'Und dem Johannes sagten seine Jünger das alles an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'Und Johannes rief zwei seiner Jünger zu sich, schickte sie an Jesus und sprach: Bist Du, Der da kommen soll, oder sollen wir eines andern warten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Die Männer aber kamen her zu Ihm und sprachen: Johannes, der Täufer, hat uns zu Dir gesandt und läßt Dir sagen: Bist Du, Der da kommen soll, oder sollen wir eines andern warten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'Zur selbigen Stunde aber heilte Er viele von Krankheiten und Plagen und bösen Geistern und schenkte vielen Blinden das Gesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'Und Jesus antwortete und sprach zu ihnen: Gehet hin und saget dem Johannes an, was ihr gesehen und gehört habt: Die Blinden sehen wieder, die Lahmen wandeln, die Aussätzigen werden rein, die Tauben hören, die Toten werden auferweckt und den Armen wird das Evangelium gepredigt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'Und selig ist, wer sich nicht an Mir ärgert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'Als aber die Boten des Johannes abgingen, fing Er an über Johannes zu dem Gedränge zu sprechen: Was seid ihr in die Wüste hinausgegangen euch anzusehen? Ein Rohr, das vom Winde geschüttelt wird?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Oder was seid ihr hinausgegangen zu sehen? Einen Menschen, mit weichen Kleidern umkleidet? Siehe, die in herrlichen Kleidern und in Üppigkeit leben, sind in den königlichen Palästen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Oder was seid ihr hinausgegangen zu sehen? Einen Propheten? Ja, Ich sage euch, und der noch mehr ist, denn ein Prophet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Er ist es, von dem geschrieben ist: Siehe, Ich sende Meinen Engel vor Deinem Angesichte her, der Deinen Weg vor Dir zurüsten soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Denn Ich sage euch: Unter den von Weibern Geborenen ist kein größerer Prophet, denn Johannes, der Täufer. Aber der Kleinste im Reiche Gottes ist größer denn er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'Und alles Volk, das ihn hörte, und die Zöllner rechtfertigten Gott und ließen sich taufen mit der Taufe des Johannes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'Die Pharisäer aber und die Gesetzeslehrer setzten den Rat Gottes für sich beiseite und ließen sich nicht von ihm taufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Aber der Herr sprach: Wem soll Ich nun die Menschen dieses Geschlechts vergleichen und wem sind sie ähnlich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Sie sind den Kindlein ähnlich, die im Markte sitzen, und einander zurufen und sagen: Wir haben euch gepfiffen und ihr habt nicht getanzt; wir haben vor euch geklagt und ihr habt nicht geweint.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Denn Johannes, der Täufer, ist gekommen, aß kein Brot und trank keinen Wein, und ihr saget: Er hat einen Dämon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Des Menschen Sohn ist gekommen, ißt und trinkt, und ihr sagt: Siehe, der Mensch ist ein Fresser und Weintrinker, der Zöllner und Sünder Freund!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'Und die Weisheit wird gerechtfertigt von allen Kindern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Es bat Ihn aber einer der Pharisäer, daß Er bei ihm äße; und Er ging ein in des Pharisäers Haus und ließ Sich nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'Und siehe, ein Weib in der Stadt, die eine Sünderin war, erfuhr, daß Er in des Pharisäers Hause zu Tische lag, brachte eine Alabasterbüchse mit Salbe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'Und stand hinten zu Seinen Füßen, weinte und fing an, Seine Füße mit den Tränen zu benetzen, und wischte sie ab mit den Haaren ihres Hauptes, und küßte Seine Füße und salbte sie mit der Salbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Als dies der Pharisäer, der Ihn gerufen hatte, sah, sprach er bei sich selbst und sagte: Wenn dieser ein Prophet wäre, so erkennete Er wohl, wer und was für ein Weib die ist, die Ihn berührt, daß sie eine Sünderin ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'Und Jesus antwortete und sprach zu ihm: Simon, ich habe dir etwas zu sagen: Er aber spricht: Sag an, Lehrer!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Ein Gläubiger hatte zwei Schuldleute; der eine schuldete ihm fünfhundert Denare, der andere aber fünfzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Da sie aber nicht hatten zu bezahlen, schenkte er es beiden. Sage nun, welcher von ihnen wird ihn mehr lieben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Simon aber antwortete und sagte: Ich nehme an, der, dem er mehr geschenkt hat. Er aber sprach zu ihm: Du hast recht gerichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'Und Er wandte Sich zu dem Weibe und sprach zu Simon: Siehst du dieses Weib? Ich kam herein in dein Haus. Du hast Mir kein Wasser für Meine Füße gegeben; sie aber hat Meine Füße mit den Tränen benetzt und mit den Haaren ihres Hauptes abgewischt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Du hast Mir keinen Kuß gegeben; sie aber hat, seit sie hereingekommen ist, nicht abgelassen, Meine Füße zu küssen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Du hast Mein Haupt nicht mit Öl gesalbt; sie aber hat Meine Füße mit Salbe gesalbt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Um dessentwillen sage Ich dir: Ihr sind ihre vielen Sünden vergeben, weil sie viel geliebt hat. Wem aber wenig vergeben wird, der liebt wenig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Er sprach aber zu ihr: Deine Sünden sind dir vergeben!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'Und die, so mit ihm zu Tische lagen, fingen an bei sich zu sprechen: Wer ist Der, daß Er auch Sünden vergibt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'Er aber sprach zu dem Weibe: Dein Glaube hat dich gerettet; gehe hin im Frieden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'Und es geschah in der Folge, daß Er umherzog durch Stadt und Flecken, predigte und die gute Botschaft vom Reiche Gottes verkündigte, und die Zwölfe mit Ihm;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'Und etliche Weiber, die durch Ihn von üblen Geistern und Gebrechen geheilt worden waren, Maria, die man Magdalena heißt, von der sieben Dämonen ausgefahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Und Johanna, das Weib von Chuza, dem Schaffner des Herodes, und Susanna, und viele andere, die Ihm von ihren Gütern Dienstleistung taten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Da nun viel Volk zusammenkam und die, so aus den Städten Ihm zuzogen, sprach Er durch ein Gleichnis:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Es ging der Sämann aus, seinen Samen zu säen; und da er säte, fiel etliches an den Weg und ward niedergetreten, und das Gevögel des Himmels fraß es auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'Und anderes fiel auf den Felsen, und da es aufwuchs, verdorrte es, weil es keine Feuchtigkeit hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'Und etliches fiel mitten unter die Dornen, und die Dornen wuchsen mit auf und erstickten es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'Und etliches fiel auf das gute Land, wuchs auf und trug hundertfältige Frucht. Da Er das sagte, rief Er: Wer Ohren hat zu hören, der höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Seine Jünger aber fragten Ihn und sprachen: Was ist wohl dieses Gleichnis?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'Er aber sprach; Euch ist gegeben, die Geheimnisse des Reiches Gottes zu erkennen, den übrigen aber in Gleichnissen; daß sie sehen und nicht sehen, hören und nicht verstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Das ist aber das Gleichnis: Der Same ist das Wort Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'Die am Wege sind die, so es hören; dann kommt der Teufel und nimmt das Wort aus ihrem Herzen weg, auf daß sie nicht glauben und gerettet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'Die aber auf dem Felsen sind die, so das Wort, wenn sie es hören, mit Freuden aufnehmen, und diese haben keine Wurzel. Eine Zeitlang glauben sie, und in der Zeit der Versuchung weichen sie ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Das aber in die Dornen fiel, das sind die, so es hören, aber hingehen unter den Sorgen und den Reichtümern und Vergnügungen des Lebens und werden erstickt und bringen nichts zur Reife.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Das aber auf gutem Lande sind die, so das Wort in schönem, gutem Herzen anhören und behalten, und Frucht bringen mit Geduld.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Niemand aber zündet eine Kerze an und verdeckt sie mit einem Gefäß oder setzt sie unter ein Bett, sondern er setzt sie auf den Leuchter auf, so daß die, so hereinkommen, das Licht sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Denn nichts ist verborgen, das nicht wird offenbar werden, und nichts heimlich, das nicht bekannt wird und an das Offenbare kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'So sehet nun zu, wie ihr höret; denn wer da hat, dem wird gegeben werden, und wer da nicht hat, dem wird auch das, was er zu haben meint, weggenommen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Es traten aber Seine Mutter und Seine Brüder herzu zu Ihm und konnten vor dem Gedränge nicht zu Ihm gelangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'Und man sagte Ihm an: Deine Mutter und Deine Brüder stehen draußen und wollen Dich sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'Er aber antwortete und sprach zu ihnen: Meine Mutter und Meine Brüder sind die, so Gottes Wort hören und tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Und es geschah an der Tage einem, daß Er und Seine Jünger in ein Schifflein einstiegen und Er sprach zu ihnen: Wir wollen hinüber über den See fahren; und sie fuhren ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Da sie aber schifften, schlief Er ein; und es fuhr ein Wirbel eines Windes in den See herab, und sie wurden überschüttet und waren in Gefahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'Sie aber kamen herzu, weckten Ihn auf und sprachen: Meister, Meister, wir sind verloren! Er aber machte Sich auf, bedrohte den Wind und die Wogen des Wassers; und sie hörten auf, und es ward eine Windstille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Er aber sprach zu ihnen: Wo ist euer Glaube? Sie fürchteten sich aber, und verwundert sagten sie zueinander: Wer ist wohl Dieser, Daß Er den Winden und dem Wasser gebietet und sie Ihm gehorchen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'Und sie schifften hin in die Gegend der Gadarener, das Galiläa gegenüber ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Da Er aber hinaus ans Land kam, kam Ihm ein Mann aus der Stadt entgegen, der von langer Zeit her von Dämonen besessen war und kein Kleid antat und in keinem Hause blieb, sondern in den Grüften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Wie der aber Jesus sah, schrie er auf, fiel vor Ihm nieder und sprach mit großer Stimme: Was habe ich mit Dir zu schaffen, Jesus, Du Sohn des höchsten Gottes? Ich flehe Dich, quäle mich nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Denn Er entbot dem unreinen Geiste, aus dem Menschen auszufahren; er hatte ihn viele Male erhascht, und er ward mit Ketten gebunden und mit Fußeisen verwahrt; und er zerriß die Bande, und ward von dem Dämon in die Wüsten getrieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Jesus aber fragte ihn und sprach: Was ist dein Name? Er aber sprach: Legion; denn viele Dämonen waren in ihn gefahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'Und er flehte Ihn an, daß Er sie nicht heißen möchte in den Abgrund abfahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Es war aber daselbst ein großer Trieb von Schweinen, die am Berge weideten, und sie flehten Ihn an, daß Er ihnen gestatte, in selbe zu fahren. Und Er gestattete es ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'Die Dämonen aber fuhren aus von dem Menschen und fuhren in die Schweine und der Trieb stürzte sich von der Anhöhe in den See und ertrank.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Da aber die Hüter sahen, was geschah, flohen sie und sagten es in der Stadt an und auf den Feldern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Sie aber kamen heraus, um zu sehen, was geschehen war, und kamen zu Jesus und fanden den Menschen, von dem die Dämonen ausgefahren waren, bekleidet und vernünftig zu Jesu Füßen sitzen, und sie fürchteten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Und die es gesehen hatten, sagten ihnen an, wie der Besessene war gerettet worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'Und die gesamte Menge aus der Umgegend der Gadarener bat Ihn, daß Er von ihnen wegginge; denn sie waren von großer Furcht erfaßt. Er aber stieg ein in das Schifflein und kehrte zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Der Mann aber, von dem die Dämonen waren ausgefahren, flehte Ihn an, daß er dürfte bei Ihm sein. Jesus aber entließ ihn und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Kehre zurück in dein Haus und erzähle, wie große Dinge Gott an dir getan hat. Und er ging hin und verkündigte in der ganzen Stadt, wie große Dinge Jesus ihm getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Es geschah aber, als Jesus zurrückkehrte, daß das Gedränge Ihn aufnahm, denn alle warteten auf Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'Und siehe, da kam ein Mann mit Namen Jairus, der auch ein Oberster der Synagoge war, und fiel zu Jesu Füßen und flehte Ihn an, daß Er in sein Haus kommen möchte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Denn er hatte eine einzige Tochter bei zwölf Jahren, und diese war am Sterben. Und da Er hinging, drängte Ihn das Gedränge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'Und ein Weib hatte den Blutfluß seit zwölf Jahren, und hatte all ihr Vermögen an Ärzte aufgewendet, und konnte von keinem geheilt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'Die kam von hinten herzu, berührte den Saum Seines Kleides und sogleich hörte ihr Blutfluß auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'Und Jesus sprach: Wer hat Mich angerührt? Da aber alle es leugneten, sprach Petrus und die mit ihm waren: Das Gedränge beengt und drückt Dich, und Du sagst: Wer hat Mich angerührt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Jesus aber sprach: Es hat Mich jemand angerührt; denn Ich habe erkannt, daß eine Kraft von Mir ausging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Da das Weib aber sah, daß es nicht verborgen war, kam sie zitternd, und fiel vor Ihm nieder und sagte vor allem Volke an, warum sie Ihn angerührt habe, und daß sie sogleich gesund worden sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'Er aber sprach zu ihr: Sei getrost Tochter! Dein Glaube hat dich gerettet. Gehe hin im Frieden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Indem Er noch redete, kam einer vom Synagogenobersten und sprach zu diesem: Deine Tochter ist gestorben; bemühe den Lehrer nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Jesus aber hörte es, antwortete ihm und sprach: Fürchte dich nicht, glaube nur, so wird sie gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Als Er aber in das Haus kam, ließ Er keinen hineingehen, außer Petrus und Johannes, und Jakobus und den Vater des Kindes und die Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Es weinten aber alle und jammerten um sie. Er aber sprach: Weinet nicht; sie ist nicht gestorben, sondern schlummert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'Und sie verlachten Ihn, denn sie wußten, daß sie gestorben war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'Er aber trieb sie alle hinaus und ergriff sie bei der Hand, rief und sprach: Mädchen, richte dich auf!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'Und ihr Geist kehrte zurück und sie stand sogleich auf. Und er verordnete, daß man ihr zu essen gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'Ihre Eltern aber waren außer sich. Er entbot ihnen aber, daß sie niemand sagen sollten, was geschehen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Da rief Er aber die Zwölfe zusammen, gab ihnen Kraft und Gewalt über alle Dämonen, und die Krankheiten zu heilen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'Und sandte sie aus, das Reich Gottes zu predigen und die Siechen gesund zu machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'Und sprach zu ihnen: Nehmet nichts mit auf den Weg, keinen Stab noch Tasche, noch Brot, noch Silber, noch sollt ihr je zwei Röcke haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'Und wenn ihr in ein Haus eingehet, so bleibet allda, und ziehet von dannen aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'Und wo sie euch nicht aufnehmen, da geht hinaus von selbiger Stadt und schüttelt den Staub von euren Füßen ab, zum Zeugnis über sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'Und sie gingen aus und durchzogen die Flecken, predigten das Evangelium und heilten überall.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Herodes, der Vierfürst, aber hörte, was alles von Ihm geschah und war betroffen; denn die einen sagten: Johannes ist von den Toten auferweckt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'Andere aber: Elias ist erschienen; andere aber: Einer der alten Propheten ist auferstanden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'Und Herodes sprach: Den Johannes ließ ich enthaupten; wer ist aber Der, von Dem ich solches höre? Und er trachtete Ihn zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'Und die Apostel kehrten zurück und erzählten Ihm, was sie getan hätten; und Er nahm sie zu Sich und entwich besonders an einen wüsten Ort bei einer Stadt, die da heißet Bethsaida.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Das Gedränge aber erfuhr es und folgte Ihm nach. Und Er nahm sie an, redete zu ihnen vom Reiche Gottes und machte die, so des Heilens bedürftig waren, gesund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'Der Tag aber fing an sich zu neigen; die Zwölfe aber kamen herzu und sprachen zu Ihm: Entlasse das Gedränge, daß sie in die umliegenden Flecken und auf die Felder gehen, auf daß sie Herberge und Beköstigung finden; denn hier sind wir an einem wüsten Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'Er aber sprach zu ihnen: Gebet ihr ihnen zu essen! Sie aber sprachen: Wir haben nicht mehr denn fünf Brote und zwei Fische; es sei denn, daß wir hingehen und für all dies Volk Speise kaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Denn es waren bei fünftausend Männer. Er sprach aber zu Seinen Jüngern: Lasset sie sich in Lager zu fünfzig niederlagern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'Und sie taten also, und ließen alle sich niederlagern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Er aber nahm die fünf Brote und die zwei Fische, blickte zum Himmel auf, segnete sie und brach und gab sie den Jüngern, daß sie dem Gedränge vorlegten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'Und sie aßen und wurden alle satt; und wurde aufgehoben, was ihnen überblieb von Brocken, zwölf Körbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'Und es geschah, da Er allein war und betete, und Seine Jünger mit Ihm waren, fragte Er sie und sprach: Wer sagt das Gedränge, daß Ich sei?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Sie aber antworteten und sagten: Johannes der Täufer; andere aber: Elias; andere aber: einer der alten Propheten sei auferstanden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Er aber sprach zu ihnen: Wer saget ihr aber, daß Ich sei? Petrus aber antwortete und sprach: Der Christus Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'Er aber bedrohte sie und entbot ihnen, es niemand zu sagen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'Und sprach: Denn des Menschen Sohn muß viel leiden und von den Ältesten und Hohenpriestern und Schriftgelehrten verworfen und getötet werden, und am dritten Tage auferweckt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Er sprach aber zu allen: Wer Mir folgen will, der verleugne sich selbst, nehme täglich sein Kreuz auf und folge Mir nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Denn wer sein Leben retten will, der wird es verlieren; wer aber sein Leben verlieren wird um Meinetwillen, der wird es retten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Denn was nützt es dem Menschen, wenn er die ganze Welt gewinnt, sich selbst aber verliert oder Schaden nimmt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Denn wer sich Mein und Meiner Worte schämt, dessen wird Sich des Menschen Sohn auch schämen, wenn Er kommen wird in Seiner und des Vaters und der heiligen Engel Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Aber in Wahrheit sage Ich euch: Es sind etliche von denen, die hier stehen, die den Tod nicht schmecken werden, bis daß sie das Reich Gottes sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Es geschah aber bei acht Tagen nach diesen Worten, daß Er Petrus und Johannes und Jakobus zu Sich nahm und stieg hinauf auf den Berg, um zu beten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'Und es geschah, wie Er betete, ward das Aussehen Seines Angesichtes ein anderes, und Seine Kleidung weiß strahlend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'Und siehe, zwei Männer unterredeten sich mit Ihm, welches Moses und Elias waren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Welche in Herrlichkeit gesehen, von Seinem Ausgang sprachen, den Er in Jerusalem erfüllen sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'Petrus aber und die mit ihm waren, wurden von Schlaf beschwert; da sie aber erwachten, sahen sie Seine Herrlichkeit, und die zwei Männer bei Ihm stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'Und es geschah, da sie sich von Ihm trennten, sprach Petrus zu Jesus: Meister, hier ist es gut sein für uns, und wir wollen drei Hütten machen, Dir eine, und Moses eine und Elias eine, - er wußte nicht, was er sagte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Während er aber dieses sprach, kam eine Wolke und überschattete sie. Sie aber fürchteten sich, als jene in die Wolke eingingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'Und aus der Wolke geschah eine Stimme, die sprach: Dies ist Mein geliebter Sohn, Ihn höret!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'Und als die Stimme geschah, fand Sich Jesus allein. Und sie schwiegen und sagten in jenen Tagen niemand etwas an von dem, das sie gesehen hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Es geschah aber vom folgenden Tage, da sie vom Berge herabkamen, kam ihnen viel Gedränge entgegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'Und siehe, ein Mann aus dem Gedränge schrie auf und sprach: Lehrer, ich flehe dich an, blicke auf meinen Sohn; denn er ist mein einziger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'Und siehe, ein Geist erfaßt ihn, und plötzlich schreit er, und er zerrt ihn mit Schäumen und kaum weicht er von ihm, wenn er ihn zerschlägt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'Und ich flehte zu Deinen Jüngern, sie möchten ihn austreiben, und sie konnten nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Jesus aber antwortete und sprach: O du ungläubig und verkehrt Geschlecht! Wie lange soll Ich bei euch sein und euch ertragen? Führe deinen Sohn hierher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'Als er aber nah herkam, riß ihn der Dämon und zerrte ihn herum. Jesus aber bedrohte den unreinen Geist, und machte den Knaben gesund und übergab ihn seinem Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'Alle aber staunten über die Größe Gottes. Während aber alle sich wunderten über alles, was Jesus tat, sprach Er zu Seinen Jüngern:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Nehmet zu Ohren diese Worte: Denn des Menschen Sohn wird in der Menschen Hände überantwortet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Aber sie verstanden diese Rede nicht, und es etwa vor ihnen verdeckt, daß sie solche nicht wahrnahmen. Und sie fürchteten sich, Ihn über diese Rede zu fragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Es kam in ihnen auch der Gedanke auf, welcher unter ihnen wohl der Größte wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Da aber Jesus ihres Herzens Gedanken sah, nahm Er ein Kindlein herbei, und stellte es neben Sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'Und sprach zu ihnen: Wer dieses Kindlein aufnimmt in Meinem Namen, der nimmt Mich auf, und wer Mich aufnimmt, der nimmt Den auf, Der Mich gesandt hat; denn der, so der Kleinste ist unter euch allen, der wird groß sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Johannes aber antwortete und sprach: Meister, wir sahen einen, der trieb in Deinem Namen Dämonen aus; und wir wehrten es ihm, weil er nicht mit uns nachfolgt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Und Jesus sprach zu ihm: Wehret ihm nicht; denn wer nicht wider uns ist, der ist für uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Es geschah aber, als die Tage sich erfüllten, daß Er sollte hinaufgenommen werden, und Er Sein Angesicht fest gerichtet hatte, gen Jerusalem zu ziehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'Da sandte Er Boten vor Seinem Angesicht; und die gingen hin und kamen in einen samaritischen Flecken, um für Ihn zu bereiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Und sie nahmen Ihn nicht auf, weil Sein Angesicht gewendet war, gen Jerusalem zu ziehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Da aber Seine Jünger Jakobus und Johannes dies sahen, sprachen sie: Herr, willst Du, daß wir sagen, daß Feuer vom Himmel herabkomme und sie verzehre, wie auch Elias tat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'Er aber wandte Sich um, bedrohte sie und sprach: Wisset ihr nicht, wessen Geistes ihr seid?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Denn des Menschen Sohn ist nicht gekommen, die Seelen der Menschen zu verderben, sondern zu retten. Und sie zogen in einen anderen Flecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'Es geschah aber, als sie auf dem Wege waren, sprach einer zu Ihm: Herr, ich will dir nachfolgen, wo Du hingehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'Und Jesus sprach zu ihm: Die Füchse haben Baue, und das Gevögel des Himmels Nester; aber des Menschen Sohn hat nicht, wo Er Sein Haupt hinlege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'Zu einem anderen aber sagte Er: Folge du Mir nach! Der aber sprach: Herr, gestatte mir, daß ich zuerst hingehe, meinen Vater zu begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'Aber Jesus sprach zu ihm: Laß die Toten ihre Toten begraben. Du aber gehe hin und verkündige das Reich Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Ein anderer aber sprach auch: Ich, Herr, will Dir nachfolgen. Gestatte aber zuerst, von denen, die in meinem Hause sind, mich zu verabschieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Jesus aber sprach zu ihm: Keiner, der die Hand an den Pflug legt und nach hinten blickt, ist tauglich für das Reich Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Danach aber bestellte der Herr noch siebzig andere, und sandte sie zu je zwei vor Seinem Angesicht in jede Stadt und jeden Ort, dahin Er Selbst kommen wollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'Er sprach dann zu ihnen: Der Ernte zwar ist viel, aber der Arbeiter wenig. Flehet denn zum Herrn der Ernte, daß Er Arbeiter in Seine Ernte ausschicke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Gehet hin! Siehe, Ich sende euch, wie Lämmer mitten unter Wölfe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Traget keinen Beutel, noch Tasche, noch Schuhe, und grüßet niemand auf dem Wege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'In welches Haus ihr aber eingehet, sprechet zuerst: Friede diesem Hause!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'Und wenn allda ein Sohn des Friedens ist, so wird euer Friede auf ihm ruhen, wo aber nicht, so wird er sich wieder zu euch wenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'In demselben Hause aber bleibet. Esset und trinket, was sie haben; denn der Arbeiter ist Seines Lohnes wert. Geht nicht von Haus zu Hause über.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'Und wo ihr in eine Stadt eingehet, und sie euch aufnehmen, da esset, was euch wird vorgelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'Und heilet die Siechen in ihr, und sprechet zu ihnen: Das Reich Gottes hat sich euch genaht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'So ihr aber in eine Stadt kommt, und sie euch nicht aufnehmen, da geht heraus auf ihre Straßen und sprechet:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Auch den Staub, der sich von eurer Stadt an uns gehängt hat, wischen wir ab auf euch. Aber das sollt ihr erkennen, daß euch das Reich Gottes nahe gewesen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Das aber sage Ich euch: Es wird Sodom an jenem Tage erträglicher sein, denn solcher Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Wehe dir, Chorazin, wehe dir, Bethsaida! denn wären in Tyrus und Sidon die Wundertaten geschehen, die in euch geschehen sind, sie hätten längst im Sack und in der Asche gesessen und Buße getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Doch Tyrus und Sidon wird es erträglicher sein im Gericht, als euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'Und du, Kapernaum, die du bis zum Himmel erhöhet worden, wirst bis in die Hölle hinabgestoßen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Wer euch hört, hört Mich; und wer euch verwirft, verwirft Mich, wer aber Mich verwirft, verwirft Den, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Die Siebzig aber kehrten zurück mit Freude und sagten: Herr, auch die Dämonen sind uns untertan in Deinem Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'Er sprach aber zu ihnen: Ich schaute den Satan wie einen Blitz aus dem Himmel fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Siehe, Ich gebe euch Gewalt, auf Schlangen und Skorpione zu treten, und über die ganze Kraft des Feindes, und nichts wird euch schädigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Doch freuet euch nicht darüber, daß euch die Geister untertan sind; freuet euch aber, daß eure Namen in den Himmeln geschrieben sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'Zu der Stunde frohlockte Jesus im Geist und sprach: Ich bekenne Dich, Vater, Herr des Himmels und der Erde, daß Du solches vor Weisen und Verständigen verheimlicht und Unmündigen geoffenbart hast. Ja, Vater, also ward es vor Dir wohlgefällig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Alles ist Mir von Meinem Vater übergeben, und niemand erkennt, wer der Sohn ist, denn nur der Vater, und wer der Vater ist, denn der Sohn, und wem der Sohn willens ist, es zu offenbaren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'Und Er wandte Sich an Seine Jünger besonders und sprach: Selig sind die Augen, die erblicken, was ihr erblickt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Denn Ich sage euch: Viele Propheten und Könige wollten sehen, was ihr erblickt, und haben es nicht gesehen, und hören, was ihr hört, und haben es nicht gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'Und siehe, da stand ein Gesetzlehrer auf, Ihn zu versuchen und sprach: Lehrer, was muß ich tun, daß ich das ewige Leben ererbe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'Er aber sprach zu ihm: Was ist im Gesetz geschrieben? Wie liesest du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'Er aber antwortete und sprach: Du sollst den Herrn, deinen Gott, lieben von deinem ganzen Herzen und von deiner ganzen Seele und von deiner ganzen Stärke und von deinem ganzen Gemüte, und deinen Nächsten wie dich selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Er aber sprach zu ihm: Du hast recht geantwortet. Tue das, so wirst du leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'Der aber wollte sich rechtfertigen und sprach zu Jesus: Und wer ist mein Nächster?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Jesus aber nahm es auf und sprach: Es war ein Mensch, der ging hinab von Jerusalem nach Jericho und fiel unter Räuber. Die zogen ihn auch aus, schlugen ihn wund und gingen weg und ließen ihn halbtot liegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Durch Zufall aber ging ein Priester desselben Weges hinab, und da er ihn sah, ging er vorüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Desgleichen aber auch ein Levit. Als er an den Ort gelangte, kam er, sah ihn und ging vorüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Ein Samariter aber reiste und kam an ihn heran, sah ihn, und es jammerte ihn seiner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'Und er kam hinzu, verband ihm die Wunden und goß Öl und Wein darauf; er setzte ihn aber auf sein eigen Lasttier, führte ihn in eine Herberge und pflegte seiner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Und da er am anderen Tage auszog, zog er zwei Denare heraus, gab sie dem Gastwirt und sprach zu ihm: Pflege sein, und was du etwa mehr aufwendest, will ich dir bezahlen, wenn ich wiederkomme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Welcher nun dieser drei, dünkt dir, war der Nächste dem, der unter die Räuber fiel?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'Er aber sprach: Der Barmherzigkeit an ihm tat. Da sprach Jesus zu ihm: So gehe auch du hin und tue desgleichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Es geschah aber, da sie hinzogen, kamen sie in einen Flecken. Da war aber ein Weib mit Namen Martha, die nahm Ihn auf in ihr Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'Und sie hatte eine Schwester, die Maria hieß. Und diese setzte sich zu Jesu Füßen und hörte auf Sein Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'Martha aber machte sich sehr zu schaffen mit vielem Dienen. Sie trat aber hinzu und sprach: Herr, kümmerst Du Dich nicht darum, daß mich meine Schwester allein läßt bei der Bedienung? Sage ihr doch, daß sie mit mir angreife.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Jesus aber antwortete und sprach zu ihr: Martha, Martha, du sorgest und beunruhigst dich um vieles.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'Eins aber ist Not. Maria aber hat das gute Teil erwählt, das soll nicht von ihr weggenommen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'Und es geschah, als Er an einem Orte war und betete, wie Er aufgehört hatte, sprach Seiner Jünger einer zu Ihm: Herr, lehre uns beten, so wie auch Johannes seine Jünger gelehrt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, 'Er aber sprach zu ihnen: Wenn ihr betet, so sprechet: Unser Vater in den Himmeln, geheiligt werde Dein Name. Dein Reich komme. Dein Wille geschehe, wie im Himmel, also auch auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Gib uns unser täglich Brot jeden Tag!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, 'Und vergib uns unsere Sünden; denn auch wir vergeben einem jeden, der uns schuldig ist. Und bringe uns nicht in Versuchung, sondern errette uns vom Übel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'Und Er sprach zu ihnen: Wer von euch hat einen Freund und geht zu ihm um Mitternacht und spricht zu ihm: Freund, leihe mir drei Brote!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'Denn mein Freund ist zu mir hergekommen von der Reise und ich habe nichts, ihm vorzusetzen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Und jener drinnen würde antworten und sagen: Mache mir keine Ungelegenheiten; die Tür ist schon verschlossen, und meine Kindlein sind bei mir zu Bette; ich kann nicht aufstehen und dir geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Ich sage euch: Wenn er auch nicht aufsteht und gibt ihm, weil er sein Freund ist, so wird er doch wegen seiner Unverschämtheit aufstehen und ihm geben, soviel er bedarf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'Und Ich sage euch: Bittet, so wird euch gegeben; suchet, so werdet ihr finden; klopfet an, so wird euch aufgetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Denn jeder, der bittet, der empfängt, und wer da sucht, der findet, und wer da anklopft, dem wird aufgetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Wo ist aber unter euch ein Vater, der dem Sohne, so er ihn um Brot bäte, einen Stein übergäbe? oder auch ihm, so er um einen Fische bäte, statt eines Fisches eine Schlange übergäbe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'Oder ihm, so er ihn um ein Ei bäte, ihm einen Skorpion übergäbe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'So nun ihr, die ihr doch arg seid, wisset euren Kindern gute Gaben zu geben, wieviel mehr wird der Vater aus dem Himmel den Heiligen Geist geben denen, die Ihn darum bitten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'Und Er trieb einen Dämon aus, und der war stumm. Es geschah aber, als der Dämon ausgefahren war, daß der Stumme redete. Und das Gedränge verwunderte sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'Etliche aber unter ihnen sagten: Durch Beelzebul, der Dämonen Obersten, treibt Er die Dämonen aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Andere aber versuchten Ihn und begehrten ein Zeichen aus dem Himmel von Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'Er aber wußte ihre Gedanken und sprach zu ihnen: Jegliches Reich, das gegen sich selbst sich zerteilt, wird wüste, und so Haus ist wider Haus, fällt es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Wenn aber der Satan auch gegen sich selbst zerteilt ist, wie kann sein Reich bestehen - weil ihr sagt, Ich treibe die Dämonen aus durch Beelzebul?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'Wenn Ich aber die Dämonen durch Beelzebul austreibe, durch wen treiben dann eure Söhne sie aus? Darum werden sie eure Richter sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Wenn Ich aber durch Gottes Finger die Dämonen austreibe, so ist ja das Reich Gottes über euch herbeigekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Wenn der Starke gewappnet seinen Hof hütet, so bleibt das Seinige im Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'Wenn aber ein Stärkerer denn er über ihn kommt und ihn überwindet, so nimmt er ihm seine Waffenrüstung weg, auf die er vertraute, und verteilt die Beute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Wer nicht mit Mir ist, der ist wider Mich, und wer nicht mit Mir sammelt, der zerstreut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Wenn der unreine Geist vom Menschen ausgefahren ist, durchzieht er wasserlose Orte, sucht Ruhe und findet sie nicht; da spricht er: Ich will zurückkehren in mein Haus, daraus ich ausgegangen bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'Und wenn er kommt, findet er es gekehrt und geschmückt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Dann geht er hin und nimmt zu sich sieben andere Geister, ärger denn er, und sie gehen ein und wohnen daselbst, und es wird das Letzte bei selbigen Menschen ärger, als das Erste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Und es geschah, da Er solches redete, erhob ein Weib aus dem Gedränge die Stimme und sprach zu Ihm: Selig ist der Leib, der Dich getragen, und die Brüste, die Du gesogen hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'Er aber sprach: Selig sind vielmehr, die das Wort Gottes hören und bewahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Als aber das Gedränge hinzuströmte, fing Er an zu sprechen: Dies Geschlecht ist arg; es sucht ein Zeichen, und kein Zeichen soll ihm gegeben werden, denn nur das Zeichen Jonas, des Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Denn wie Jonas den Nineviten zum Zeichen ward, so soll es auch des Menschen Sohn sein diesem Geschlechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Die Königin von Mittag wird im Gericht auftreten mit den Männern dieses Geschlechtes und sie verdammen; denn sie kam von den Enden der Erde, Salomohs Weisheit zu hören; und siehe, hier ist mehr den Salomoh!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Die Männer von Nineveh werden aufstehen im Gericht mit diesem Geschlecht und es verdammen; denn sie taten Buße auf die Predigt des Jonas; und siehe, hier ist mehr denn Jonas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Niemand zündet aber eine Kerze an und setzt sie ins Verborgene oder unter den Scheffel, sondern auf den Leuchter, daß die, so eintreten, den Schein erblicken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Das Licht des Leibes ist das Auge. Wenn dein Auge einfältig ist, so ist auch dein ganzer Leib licht; so aber dein Auge böse ist, ist auch dein Leib finster.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'So schaue denn darauf, daß nicht das Licht in dir Finsternis sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Wenn nun dein Leib ganz licht ist, und kein finsteres Teil darin ist, so wird er dann ganz licht sein, wie wenn das Licht mit seinem Strahle dich erleuchtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Da Er aber redete, bat Ihn ein Pharisäer, Er möchte bei ihm frühstücken. Und Er ging hinein und ließ Sich nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Da das der Pharisäer sah, verwunderte er sich, daß Er Sich nicht vor dem Mahle gewaschen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Der Herr aber sprach zu ihm: Ihr Pharisäer reinigt wohl das Auswendige des Kelches und der Platte, das Inwendige bei euch ist aber soll von Raub und Schlechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Ihr Toren, hat nicht der das Auswendige machte, auch das Inwendige gemacht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Gebt jedoch Almosen von dem, was da ist, und siehe, alles ist rein für euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Aber wehe euch Pharisäern, daß ihr verzehntet die Minze und die Raute und jegliches Gartenkraut, und geht vorbei an dem Gericht und der Liebe zu Gott. Dies sollte man tun und jenes nicht lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Wehe euch Pharisäern, daß ihr liebt den ersten Sitz in den Synagogen und die Grüße auf dem Markte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Wehe euch Schriftgelehrten und Pharisäern, ihr Heuchler, daß ihr seid wie ungesehene Gräber, und die Menschen wandeln darüber und wissen es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Da antwortete einer der Gesetzlehrer und sprach zu Ihm: Lehrer, indem Du solches sagst, beschimpfst Du auch uns!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'Er aber sprach: Wehe auch euch Gesetzlehrern, daß ihr die Menschen mit unerträglichen Lasten belastet, und ihr selbst regt die Lasten mit keinem eurer Finger an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Wehe euch, die ihr baut die Grüfte der Propheten, eure Väter aber haben sie getötet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'Damit bezeugt ihr und habt Wohlgefallen mit ihnen an den Werken eurer Väter; denn sie töteten sie zwar, ihr aber bauet ihre Grüfte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Darum spricht auch die Weisheit Gottes: Ich sende an sie Propheten und Apostel; und sie werden etliche von ihnen töten und verfolgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'Damit von diesem Geschlecht gefordert werde das Blut aller Propheten, das seit der Gründung der Welt vergossen ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'Von Abels Blut bis auf das Blut des Zacharias, der zwischen dem Altar und dem Hause umgebracht wurde. Ja, Ich sage euch, von diesem Geschlecht wird es gefordert werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Wehe euch Gesetzlehrern, daß ihr den Schlüssel der Erkenntnis habt weggenommen. Ihr selbst seid nicht hineingekommen und habt den Hineinkommenden gewehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Da Er solches zu ihnen sprach, fingen die Schriftgelehrten und die Pharisäer an, Ihm hart zuzusetzen und Ihn über vielerlei auszulocken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'Indem sie Ihm auflauerten und danach trachteten, ob sie aus Seinem Munde etwas erjagen könnten, daß sie Ihn verklageten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Als das Gedränge zu Zehntausenden sich versammelte, so daß sie einander niedertraten, fing Er an zu Seinen Jünger zu sagen: Zum ersten nehmet euch in acht vor dem Sauerteig der Pharisäer, welcher ist Heuchelei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Nichts ist verdeckt, das nicht aufgedeckt werden, und verborgen, das nicht erkannt werden wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Weshalb, was ihr im Finstern gesprochen habt, wird im Licht gehört werden. Und was ihr in den Kammern ins Ohr geredet habt, wird auf den Dächern gepredigt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Ich aber sage euch, Meinen Freunden: Fürchtet euch nicht vor denen, die den Leib töten, nach dem aber nichts weiter haben, das sie tun können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Ich will euch aber weisen, vor wem ihr euch zu fürchten habt. Fürchtet euch vor Dem, Der, nachdem Er getötet hat, die Gewalt hat, in die Hölle zu werfen. Ja, Ich sage euch, vor Dem fürchtet euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Verkauft man nicht fünf Sperlinge um zwei Pfennige, und doch ist keiner derselben vor Gott vergessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'Aber auch die Haare eures Hauptes sind alle gezählt. Darum fürchtet euch nicht; ihr seid mehr wert, denn viele Sperlinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Ich sage euch aber: Jeder, der Mich bekennt vor den Menschen, den wird auch des Menschen Sohn bekennen vor den Engeln Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'Wer Mich aber vor den Menschen verleugnet hat, der wird auch vor den Engel Gottes verleugnet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'Und jeder, der ein Wort spricht wider des Menschen Sohn, dem soll es vergeben werden; wer aber wider den Heiligen Geist lästert, dem soll es nicht vergeben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Wenn sie euch aber vor die Synagogen und die Obrigkeiten und Gewalten führen, so sorget nicht, wie oder womit ihr euch verantworten oder was ihr sprechen sollet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'Denn der Heilige Geist wird euch zur selben Stunde lehren, was ihr sprechen müßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Einer aber aus dem Gedränge sagte zu Ihm: Lehrer, sage meinem Bruder, daß er das Erbe mit mir teilen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'Er aber sprach zu ihm: Mensch, wer hat Mich zum Rechtsprecher oder Erbteiler über euch gesetzt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'Er sprach aber zu ihnen: Sehet zu und hütet euch vor der Habsucht. Denn niemand hat das Leben in dem Überfluß aus seiner Habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Er aber sagte ihnen ein Gleichnis und sprach: Es war ein reicher Mann, dem hatte sein Acker wohl getragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'Und er bedachte bei sich und sprach: Was soll ich tun? Denn ich habe nicht, wo ich meine Früchte hinsammle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'Und er sagte: Das will ich tun: ich will meine Scheunen abbrechen und größere bauen, und all meinen Ertrag und meine Güter allda sammeln,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'Und werde meiner Seele sagen: Seele, du hast nun viele Güter auf viele Jahre daliegen. Ruhe aus, iß, trink und sei fröhlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Gott aber sprach zu ihm: Du Tor, heute Nacht wird man deine Seele von dir abfordern. Wessen wird dann sein, das du bereitet hast?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'So ist es mit dem, der sich Schätze sammelt und ist nicht reich in Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Er sagte aber zu Seinen Jüngern: Darum sage Ich euch: Sorget nicht für eure Seele, was ihr essen, noch für euren Leib, was ihr antun sollet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Die Seele ist mehr denn die Nahrung, und der Leib mehr denn die Kleidung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Betrachtet die Raben; sie säen nicht, sie ernten nicht, sie haben keine Kammer noch Scheune, und Gott ernährt sie. Wieviel mehr seid ihr als das Gevögel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Wer von euch aber kann mit seinem Sorgen seinem Wuchse eine Elle zusetzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'So ihr denn das Geringste nicht könnt, warum sorgt ihr um das Übrige?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Betrachtet die Lilien, wie sie wachsen. Sie mühen sich nicht ab, noch spinnen sie! Aber Ich sage euch, daß auch Salomoh in all seiner Herrlichkeit nicht umkleidet war, wie deren eine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Wenn aber Gott das Gras, das heute auf dem Felde ist und morgen in den Ofen geworfen wird, also ankleidet, wieviel mehr euch, ihr Kleingläubigen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'So fraget denn auch ihr nicht, was ihr essen oder was ihr trinken werdet, und seid nicht im Zweifel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'Nach solchem allem trachten die Heiden der Welt. Euer Vater aber weiß, daß ihr dessen bedürfet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Trachtet vielmehr nach dem Reich Gottes, so wird euch dies alles hinzugetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Fürchte dich nicht, du kleines Herdlein; denn es ist eures Vaters Wohlgefallen, euch das Reich zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Verkaufet, was ihr habt, und gebt Almosen. Machet euch Beutel, die nicht altern, einen Schatz in den Himmeln, der nicht versiegt, wo der Dieb nicht naht, noch die Motte verdirbt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Denn wo euer Schatz ist, da wird auch euer Herz sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Eure Lenden seien umgürtet, und lasset eure Kerzen brennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'Und seid ihr ähnlich den Menschen, die auf ihren Herrn warten, wenn er aufbricht von der Hochzeit, daß, wenn er kommt und anklopft, sie ihm alsbald auftun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Selig selbige Knechte, die der Herr, so er kommt, wachend findet. Wahrlich, Ich sage euch, er umgürtet sich, läßt sie zu Tische gehen, und kommt herzu und bedient sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'Und so er in der zweiten Wache und in der dritten Wache kommt und findet sie also: selig sind selbige Knechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Dieses aber erkennet: Wenn der Hausherr wüßte, zu welcher Stunde der Dieb käme, so bliebe er wach und ließe nicht in sein Haus einbrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'So seid denn auch ihr bereit; denn des Menschen Sohn wird kommen zu einer Stunde, da ihr es nicht meinet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Petrus aber sprach zu Ihm: Herr, sagst Du dieses Gleichnis für uns, oder auch für alle?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Der Herr aber sprach: Wer ist wohl der treue und kluge Haushalter, den der Herr über sein Gesinde setzen wird, auf daß er ihnen zur bestimmten Zeit den Mundbedarf gebe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Selig ist selbiger Knecht, den sein Herr findet also tun, wenn er kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'In Wahrheit, Ich sage euch, er wird ihn über all seine Habe setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Wenn aber selbiger Knecht in seinem Herzen spricht: Mein Herr verzieht zu kommen, und fängt an, die Knechte und die Mägde zu schlagen und zu essen und zu trinken und sich zu berauschen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'So wird der Herr desselbigen Knechts kommen an einem Tage, an dem er es nicht erwartet, und zu einer Stunde, die er nicht weiß, und ihn zerscheitern und ihm sein Teil setzen mit den Ungetreuen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Selbiger Knecht aber, der seines Herrn Willen wußte und sich nicht bereitete, und nicht nach seinem Willen tat, wird viel Streiche erleiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'Der es aber nicht wußte, aber doch tat, was der Streiche wert ist, wird wenig Streiche leiden. Bei einem jeglichen aber, dem viel gegeben ist, von dem wird man viel suchen, und bei dem man viel niedergelegt hat, von dem wird man mehr fordern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Ich bin gekommen, ein Feuer auf die Erde zu werfen, und was wollte Ich, als daß es schon angezündet wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'Ich habe aber eine Taufe, mit der Ich getauft werde, und wie bin Ich bedrängt, bis sie vollendet ist!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Meinet ihr, Ich sei hergekommen, Frieden zu geben auf Erden? Nein, sage Ich euch, sondern Zerteilung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Von nun an werden fünf in einem Hause zerteilt sein, drei wider zwei, und zwei wider drei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'Der Vater wird entzweit sein mit dem Sohn und der Sohn mit dem Vater, die Mutter mit der Tochter und die Tochter mit der Mutter, die Schwieger mit ihrer Schnur und die Schnur mit ihrer Schwieger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Er sprach aber auch zu dem Gedränge: Wenn ihr eine Wolke vom Niedergang aufgehen sehet, so saget ihr alsbald: Es kommt ein Platzregen! Und es geschieht also.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'Und wenn der Mittagswind weht, saget ihr: Es wird eine Hitze! Und es geschieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Ihr Heuchler, das Gesichte der Erde und des Himmel wisset ihr zu prüfen; wie aber ist es, daß ihr diese Zeit nicht prüfet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Warum richtet ihr von euch selbst aus nicht, was gerecht ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Denn wenn du mit deinem Widersacher vor die Obrigkeit hingehst, so befleißige dich, noch auf dem Wege von ihm loszuwerden, auf daß er dich nicht vor den Richter hinunterschleppe, und der Richter dich dem Gerichtsdiener übergebe und der Gerichtsdiener dich ins Gefängnis werfe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Ich sage dir: Du wirst von dannen nicht herauskommen, bis daß du auch den letzten Heller bezahlst hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Es waren aber zur selben Zeit etliche da, die sagten Ihm an von den Galiläern, deren Blut Pilatus mit ihren Opfern vermischte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'Und Jesus antwortete und sprach zu ihnen: Meint ihr, diese Galiläer seien Sünder gewesen vor allen Galiläern, weil sie solches erlitten haben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Nein, sage Ich euch, sondern wenn ihr nicht Buße tut, werdet ihr alle auch also umkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Oder meint ihr, daß jene achtzehn, auf die der Turm in Siloam fiel und sie tötete, seien Schuldner gewesen vor allen Menschen, die in Jerusalem wohnen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Nein, sage Ich euch; sondern wenn ihr nicht Buße tut, werdet ihr alle auch also umkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Er sagte ihnen aber dies Gleichnis: Es hatte einer einen Feigenbaum, der in seinem Weinberg gepflanzt war, und kam und suchte Frucht darauf und fand keine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Er sprach aber zu dem Weinbauer: Siehe, drei Jahre komme ich und suche Frucht darauf und finde sie nicht. Haue ihn ab, was versperrt er das Land?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'Der aber antwortete und sagte zu ihm: Herr, laß ihn noch dieses Jahr, bis daß ich um ihn grabe und Dünger hinwerfe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'Ob er dann Frucht bringt. Wo aber nicht, so haue ihn künftighin ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Er lehrte aber in einer der Synagogen am Sabbath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'Und siehe, da war ein Weib, das hatte achtzehn Jahre einen Geist des Gebrechens, und war zusammengekrümmt und konnte sich nicht völlig aufrichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Da aber Jesus sie sah, rief Er sie herzu und sprach zu ihr: Weib, du bist erlöst von deinem Gebrechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'Und Er legte die Hände auf sie; und sogleich wurde sie gerade und verherrlichte Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Der Oberste der Synagoge aber antwortete, unwillig, daß Jesus auf den Sabbath heilte, und sprach zu dem Gedränge: Sechs Tage sind es, an denen man arbeiten soll. An diesen kommt und lasset euch heilen, und nicht am Tage des Sabbaths.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Da antwortete ihm der Herr und sprach: Du Heuchler, löst nicht jeder von euch am Sabbath seine Ochsen oder Esel von der Krippe und führt ihn hin, ihn zu tränken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Diese aber, die eine Tochter Abrahams ist, die der Satan nun, siehe, achtzehn Jahre gebunden hatte, sie sollte nicht am Tage des Sabbaths von diesem Bande gelöst werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'Und da Er solches sprach, mußten sich schämen alle Seine Widersacher; und das ganze Gedränge freute sich über all das Herrliche, das von Ihm geschah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Er aber sprach: Wem ist das Reich Gottes gleich, und wem soll Ich es vergleichen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Es ist gleich einem Senfkorn, das ein Mensch nahm und warf es in seinen Garten. Und es wuchs und ward zu einem großen Baum, so daß das Gevögel des Himmels in seinen Zweigen wohnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'Und abermals sprach Er: Wem soll Ich das Reich Gottes vergleichen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Es ist gleich einem Sauerteig, den ein Weib nahm und in drei Seahs Mehl verbarg, bis daß das Ganze durchsäuert war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'Und Er durchzog Städte und Flecken und lehrte, und machte die Reise nach Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Es sprach aber einer zu Ihm: Herr, sind es wenige, die gerettet werden? Er aber sprach zu ihnen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Ringet danach, daß ihr eingeht durch das enge Tor; denn viele, sage Ich euch, werden versuchen, einzugehen und werden es nicht vermögen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Wenn der Hausherr sich aufgemacht hat und die Tür verschlossen hat, und ihr anfanget, draußen zu stehen und an die Tür zu klopfen, und sagt: Herr, Herr, tue uns auf! Und er wird antworten und zu euch sagen: Ich kenne euch nicht, woher ihr seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Dann werdet ihr anfangen zu sagen: Wir haben vor dir gegessen und getrunken und in unseren Straßen hast du gelehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Und er wird sprechen: Ich sage euch: Ich kenne euch nicht, woher ihr seid. Weichet von mir alle, die Ungerechtigkeit wirken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Da wird sein Heulen und Zähneknirschen, wenn ihr sehen werdet Abraham und Isaak und Jakob und alle die Propheten im Reiche Gottes, ihr aber werdet hinausgeworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'Und kommen werden vom Aufgang und Niedergang und von Mitternacht und Mittag und im Reiche Gottes zu Tische liegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'Und siehe, es sind Letzte, die Erste sein werden, und sind Erste, die Letzte sein werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'An selbigen Tage kamen einige Pharisäer herzu und sprachen zu Ihm: Gehe hinaus und ziehe von hinnen; denn Herodes will Dich töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'Und Er sprach zu ihnen: Geht hin und sagt diesem Fuchs: Siehe, Ich treibe Dämonen aus und vollbringe Heilungen heute und morgen, und am dritten Tage werde Ich vollendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Doch muß Ich heute und morgen und am folgenden Tage hinziehen; denn es tut es nicht, daß ein Prophet umkomme außerhalb Jerusalems.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jerusalem, Jerusalem, die du tötest die Propheten und steinigst, die zu dir gesandt werden. Wie oft habe Ich deine Kinder versammeln wollen, wie die Henne ihr Brut unter die Flügel, und ihr habt nicht gewollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Siehe, euer Haus wird euch wüste gelassen. Aber Ich sage euch: Ihr werdet Mich nicht sehen, bis es kommen wird, daß ihr sagt: Gesegnet sei, Der da kommt im Namen des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'Und es geschah, daß Er in das Haus eines der Obersten der Pharisäer kam, am Sabbath das Brot zu essen; und sie hielten auf Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'Und siehe, da war vor Ihm ein Mensch, der war wassersüchtig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'Und Jesus antwortete und sprach zu den Gesetzlehrern und Pharisäern und sagte: Ist es erlaubt, am Sabbath zu heilen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Sie waren aber stille. Und Er nahm ihn, machte ihn gesund und entließ ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'Und Er antwortete und sprach zu ihnen: Welcher ist unter euch, dem ein Esel oder ein Ochs in den Brunnen fällt, und der ihn nicht alsbald heraufzieht am Tage des Sabbaths?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'Und sie vermochten Ihm nicht darauf zu entgegnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Er aber sagte denen, die gerufen waren, ein Gleichnis, da Er bemerkte, daß sie sich die ersten Plätze auswählten, und sprach zu ihnen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Wenn du von jemand zur Hochzeit gerufen wirst, so laß dich nicht nieder an den ersten Platz. Es möchte sonst ein Geehrterer denn du von ihm gerufen sein,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'Und der, so dich und ihn gerufen hat, kommen und zu dir sagen: Gib diesem den Platz, da du dann beschämt den letzten Platz einnehmen müßtest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Sondern wenn du geladen wirst, gehe hin, laß dich an den letzten Platz nieder, auf daß, wenn der kommt, der dich geladen hat, er zu dir spreche: Rücke weiter hinauf, mein Freund, und du dann Ehre habest vor denen, die mit dir zu Tische liegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Denn wer sich selbst erhöht, der wird erniedrigt, und wer sich selbst erniedrigt, der wird erhöht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Er sprach aber auch zu dem, der Ihn geladen hatte: Wenn du ein Mittagsmahl oder ein Abendmahl machst, so rufe nicht deine Freunde noch deine Brüder, noch deine Verwandten, noch reiche Nachbarn, auf daß nicht etwa auch sie dich wieder laden, und dir Vergeltung werde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Sondern wenn du ein Mahl machst, so rufe Arme, Krüppel, Lahme, Blinde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'Und du wirst selig sein; weil sie nichts haben, es dir zu vergelten; denn bei der Auferstehung der Gerechten wird es dir vergolten werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Als solches aber einer derer, die mit zu Tische lagen, hörte, sprach er zu Ihm: Selig ist, der das Brot isset im Reiche Gottes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'Er aber sprach zu ihm: Es war ein Mensch, der machte ein großes Abendmahl und lud viele ein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'Und zur Stunde des Abendmahls sandte er seinen Knecht aus und ließ denen, die geladen waren, sagen: Kommet, denn alles ist schon bereitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'Und sie fingen alle übereins an, sich zu entschuldigen. Der erste sagte ihm: Ich habe ein Feld gekauft und muß notwendig hinausgehen, es zu besehen. Ich bitte dich, entschuldige mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'Und ein anderer sagte: Ich habe fünf Joch Ochsen gekauft, und gehe hin, sie zu prüfen. Ich bitte dich, entschuldige mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Und ein anderer sagte: Ich habe ein Weib gefreit, und darum kann ich nicht kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'Und selbiger Knecht trat herzu und sagte solches seinem Herrn an. Da ward der Hausherr zornig und sprach zu seinem Knecht: Gehe schnell hinaus auf die Straßen und die Gassen der Stadt und führe die Armen und die Krüppel und die Blinden und die Lahmen hier herein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'Und der Knecht sprach: Herr, es ist geschehen, wie du verordnet hast, und es ist noch Platz da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Und der Herr sprach zu dem Knecht: Gehe hinaus auf die Wege und die Zäune und nötige sie hereinzukommen, auf daß mein Haus voll werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Denn ich sage euch, daß keiner selbiger Männer, die geladen worden, mein Abendmahl kosten soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Es zog aber viel Gedränge mit Ihm, und Er wandte Sich, und sprach zu ihnen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'So jemand zu Mir kommt und haßt nicht seinen Vater und die Mutter und das Weib und die Kinder und die Brüder und die Schwestern, ja selbst auch seine eigene Seele, der kann Mein Jünger nicht sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Und wer nicht sein Kreuz trägt und Mir nachkommt, der kann Mein Jünger nicht sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Denn wer von euch, der einen Turm bauen will, setzt sich nicht zuvor hin und berechnet die Kosten, ob er es hat zur Ausführung?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'Auf daß nicht, so er den Grund gelegt, und nicht vermag es zu vollenden, alle, die es schauen, anfangen, ihn zu verspotten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'Und zu sagen: Dieser Mensch fing an zu bauen, und vermochte es nicht zu vollenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Oder, wo ist ein König, der hinzieht, um mit einem anderen König im Krieg zusammenzutreffen, und sich nicht zuvor hinsetzt und berät, ob er kann mit Zehntausenden begegnen dem der mit Zwanzigtausenden über ihn kommt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Ist er es aber nicht, so sendet er, da er noch ferne ist, eine Gesandtschaft und bittet um Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Also ist es mit jeglichem unter euch: so er nicht alles, das er besitzt, aufgibt, kann er nicht Mein Jünger sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Das Salz ist gut; so aber das Salz fade wird, womit wird man es würzen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Es ist weder für das Land, noch für den Düngerhaufen tauglich. Hinaus wirft man es! Wer Ohren hat zu hören, der höre!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Es nahten sich Ihm aber alle Zöllner und Sünder, auf daß sie Ihn hörten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'Und die Pharisäer und die Schriftgelehrten murrten durcheinander und sagten: Dieser nimmt die Sünder an und ißt mit ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'Er aber sagte ihnen dies Gleichnis und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Welcher Mensch von euch, der hundert Schafe hat und eines derselben verliert, verläßt nicht die neunundneunzig in der Wüste, und geht hin nach dem verlorenen, bis daß er es finde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'Und wenn er es gefunden hat, legt er es mit Freuden auf seine Schultern;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'Und wenn er nach Hause kommt, ruft er die Freunde und Nachbarn zusammen und spricht zu ihnen: Freuet euch mit mir, ich habe mein Schaf gefunden, das verloren war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Ich sage euch: So wird Freude sein im Himmel über einen Sünder, der Buße tut, mehr denn über neunundneunzig Gerechte, die der Buße nicht bedürfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Oder welches Weib ist, das zehn Drachmen hat, wenn sie eine Drachme verliert, die nicht eine Kerze anzündet und das Haus kehrt und fleißig sucht, bis daß sie sie findet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'Und wenn sie dieselbe gefunden hat, ruft sie die Freundinnen und Nachbarinnen zusammen und spricht: Freuet euch mit mir, denn ich habe die Drachme gefunden, die ich verloren hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Also, sage Ich euch, wird Freude sein vor den Engeln Gottes über einen Sünder, der Buße tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'Er sprach aber: Ein Mensch hatte zwei Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'Und der Jüngere von ihnen sprach zum Vater: Gib mir, Vater, den Teil des Guts, der mich trifft. Und er verteilte unter sie das Vermögen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'Und nicht viel Tage danach sammelte der jüngere Sohn alles zusammen und zog fort in eine ferne Landschaft und vergeudete da sein Gut mit schwelgendem Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'Als er aber all das Seine verausgabt hatte, ward eine starke Hungersnot in selbiger Landschaft, und er fing an Mangel zu leiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'Und er ging hin und hängte sich an einen der Bürger derselbigen Landschaft. Und der schickte ihn auf seine Felder, die Schweine zu hüten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'Und er begehrte, seinen Magen mit Schoten zu füllen, welche die Schweine fraßen; aber niemand gab sie ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Da kam er aber zu sich selber und sprach: Wie viele Mietlinge meines Vaters haben Brot im Überfluß, und ich verderbe vor Hunger!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Ich will aufstehen und zu meinem Vater hingehen und zu ihm sagen: Vater, ich habe gesündigt am Himmel und vor dir;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'Und ich bin hinfort nicht mehr wert, daß ich dein Sohn heiße. Mache mich wie einen deiner Mietlinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'Und er stand auf und kam zu seinem Vater. Da er aber noch weit weg war, sah ihn sein Vater, und es jammerte ihn; und er lief, fiel ihm um den Hals und küßte ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'Der Sohn aber sprach zu ihm: Vater, ich habe gesündigt am Himmel und vor dir; ich bin nicht mehr wert, daß ich dein Sohn heiße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Der Vater aber sprach zu seinen Knechten: Bringt das erste Gewand und tut es ihm an, und gebt ihm einen Ring an die Hand und Schuhe an die Füße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'Und bringt das Mastkalb her, und schlachtet es. Und lasset uns essen und fröhlich sein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'Denn dieser mein Sohn war tot und ist wieder lebendig. Er war verloren und ist gefunden. Und sie fingen an, fröhlich zu werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'Sein ältester Sohn aber war auf dem Felde, und wie der kam und dem Hause nahte, hörte er Musik und Reigen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'Und er rief zu sich der Knechte einen und fragte, was das wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'Der aber sagte ihm: Dein Bruder ist gekommen, und dein Vater hat das Mastkalb geschlachtet, weil er ihn gesund wieder empfangen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'Er ward aber zornig und wollte nicht hineingehen. Da ging sein Vater denn hinaus und flehte ihn an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'Er aber antwortete und sprach zu dem Vater: Siehe, so viele Jahre diene ich dir und habe nie dein Gebot übergangen, und noch nie hast du mir einen Bock gegeben, daß ich mit meinen Freunden fröhlich wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Nun aber dieser dein Sohn gekommen ist, der dein Vermögen mit Buhlerinnen aufgegessen, hast du ihm das Mastkalb geschlachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'Er sprach aber zu ihm: Kind, du bist allzeit bei mir, und all das Meine ist dein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Man mußte aber fröhlich sein und sich freuen, daß dieser dein Bruder tot war und ist wieder lebendig, und daß er verloren war und wieder gefunden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Er sprach aber auch zu Seinen Jüngern: Es war ein reicher Mensch, der hatte einen Haushalter; der ward vor ihm bezichtigt, daß er seine Habe verschleudere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'Und er rief ihn und sprach zu ihm: Wie ist es, daß ich dieses von dir höre? Gib Rech- nung von deiner Haushaltung, denn du kannst nicht mehr haushalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'Der Haushalter aber sprach bei sich: Was soll ich tun? Mein Herr nimmt mir die Haushaltung ab. Zu graben vermag ich nicht, zu betteln schäme ich mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Ich weiß, was ich tue, wenn ich vom Haushalt abtreten muß, auf daß sie mich in ihre Häuser aufnehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'Und er rief einen jeglichen der Schuldleute seines Herrn zu sich und sprach zu dem ersten: Wieviel schuldest du meinem Herrn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'Er aber sprach: Hundert Bath Öl. Und er sprach zu ihm: Nimm deinen Brief und setze dich und schreibe schnell fünfzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Danach sprach er zu einem andern: Aber du, wieviel bist du schuldig? Dieser aber sagte: Hundert Kor Weizen. Und er sprach zu ihm: Nimm deinen Brief und schreibe achtzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'Und der Herr lobte den ungerechten Haushalter, daß er klüglich getan habe; denn die Söhne dieses Zeitlaufes sind klüger, als die Söhne des Lichts in ihrem Geschlechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Und Ich sage auch euch: Machet euch Freunde mit dem Mammon der Ungerechtigkeit, auf daß, wenn es mit euch zu Ende geht, sie euch aufnehmen in die ewigen Hütten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Wer im Geringsten treu ist, ist auch in vielem treu; und wer im Geringsten ungerecht ist, ist auch in vielem ungerecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'So ihr nun in dem ungerechten Mammon nicht treu waret, wer wird euch das Wahre anvertrauen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'Und so ihr in dem Fremden nicht treu waret, wer wird euch das Eure geben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Kein Hausknecht kann zwei Herren dienen; denn entweder wird er den einen hassen und den andern lieben; oder dem einen anhangen und den andern verachten. Ihr könnt nicht Gott und dem Mammon dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Es hörten aber solches alles auch die Pharisäer, die geldsüchtig waren, und sie spotteten Ihn aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'Und Er sprach zu ihnen: Ihr seid es, die sich rechtfertigen vor den Menschen; Gott aber erkennt eure Herzen; denn was hoch ist unter Menschen, ist ein Greuel vor Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Das Gesetz und die Propheten waren bis auf Johannes; von da an wird das Reich Gottes verkündigt, und jeder dringt mit Gewalt hinein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Es ist aber leichter, daß Himmel und Erde vergehen, denn daß ein Strichlein vom Gesetz fiele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Jeder, der sich von seinem Weibe scheidet und eine andere freit, bricht die Ehe, und jeder, der eine vom Mann Geschiedene freit, bricht die Ehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Es war aber ein reicher Mensch, und er kleidete sich in Purpur und Byssus, lebte alle Tage fröhlich und glänzend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'Es war aber ein Armer, mit Namen Lazarus, der war voller Schwären vor sein Tor hingeworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'Und er begehrte sich zu sättigen von den Brosamen, die von des Reichen Tische fielen; doch kamen auch die Hunde, die seine Schwären beleckten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Und es geschah, daß der Arme starb und von den Engeln in Abrahams Schoß hingetragen ward. Der Reiche aber starb auch und ward begraben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'Und er hob seine Augen auf in der Hölle, da er in Qualen war, sah Abraham von weitem und Lazarus in seinem Schoß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'Und er rief und sprach: Vater Abraham, erbarme dich mein, und schicke Lazarus, daß er die Spitze seines Fingers in Wasser tauche und mir die Zunge abkühle; denn ich leide Pein in dieser Flamme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Abraham aber sprach: Gedenke, Kind, du hast dein Gutes in deinem Leben emp- fangen, und Lazarus dagegen Böses. Nun aber wird er getröstet, du aber gepeinigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'Und über alles dies ist eine große Kluft befestigt, zwischen uns und euch, so daß die, so wollten von hinnen zu euch hinübergehen, nicht können, und auch nicht die von dannen zu uns herüberkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Er aber sprach: So bitte ich dich nun, Vater, du wollest ihn in meines Vaters Haus schicken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Denn ich habe fünf Brüder; auf daß er es ihnen ernstlich bezeuge, damit sie nicht auch kommen an diesen Ort der Qual.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Spricht zu ihm Abraham: Sie haben Moses und die Propheten. Auf die sollen sie hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'Er aber sprach: Nein, Vater Abraham. Aber wenn einer von den Toten zu ihnen hinginge, da werden sie Buße tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Er aber sprach zu ihm: Wenn sie auf Moses und die Propheten nicht hören, so werden sie sich auch nicht überzeugen lassen, wenn einer von den Toten aufersteht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Er sprach aber zu Seinen Jüngern: Es ist unmöglich, daß nicht Ärgernisse kommen; aber wehe dem, durch den sie kommen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Es wäre ihm nützlicher, so ein Mühlstein um seinen Hals umgehängt und er ins Meer dahingeworfen würde, denn daß er dieser Kleinen einen ärgerte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Habt Acht auf euch! So aber dein Bruder wider dich sündigt, so verweise es ihm; und so er Buße tut, vergib ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'Und wenn er siebenmal des Tages an dir sündiget, und siebenmal des Tages zu dir sich umwendete und sagt: Ich tue Buße, so sollst du ihm vergeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Und die Apostel sprachen zum Herrn: Lege uns Glauben zu!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Der Herr aber sprach: Wenn ihr Glauben habt wie ein Senfkorn, so sprächet ihr zu diesem Maulbeerfeigenbaume: Entwurzle dich und pflanze dich ins Meer! und er würde euch gehorchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Welcher aber ist unter euch, der einen Knecht hat, der ihm pflügt oder weidet, der, wenn er hereinkommt vom Felde, zu ihm sagt: Komm alsbald her und laß dich zu Tische nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Wird er nicht vielmehr zu ihm sagen: Bereite, was ich zu Abend esse, und umgürte dich, bediene mich, bis ich gegessen und getrunken habe, und danach iß und trink du!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Wird er demselbigen Knechte danken, daß er tat, was verordnet war? Ich meine nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'So auch ihr: Wenn ihr alles getan habt, was euch verordnet war, sprechet: Wir sind unnütze Knechte. Wir haben getan, was wir zu tun schuldig waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'Und es geschah, da Er nach Jerusalem zog, kam Er mitten durch Samarien und Galiläa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'Und wie er in einen Flecken kam, begegneten Ihm zehn aussätzige Männer, die standen von ferne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'Und sie erhoben die Stimme und sprachen: Jesus, Meister, erbarme Dich unser!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'Und da Er sie sah, sprach Er zu ihnen: Gehet hin, zeigt euch den Priestern! Und es geschah, da sie hingingen, wurden sie gereinigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Einer aber aus ihnen, da er sah, daß er gesund geworden, kehrte zurück, und mit großer Stimme verherrlichte er Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'Und fiel auf das Angesicht zu Seinen Füßen und dankte Ihm. Und der war ein Samariter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Jesus aber antwortete und sprach: Sind nicht die zehn gereinigt worden? Wo sind aber die neune?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Haben sich sonst keine gefunden, die zurückkehrten und Gott die Herrlichkeit gäben, denn dieser Fremdling?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'Und Er sprach zu ihm: Stehe auf, gehe hin! dein Glaube hat dich gerettet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Von den Pharisäern aber befragt: Wann kommt das Reich Gottes? antwortete Er ihnen und sprach: Das Reich Gottes kommt nicht augenfällig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'Sie werden auch nicht sagen: Siehe, hier! oder: Siehe, dort! denn siehe, das Reich Gottes ist inwendig in euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Er sprach aber zu den Jüngern: Es werden Tage kommen, da ihr werdet begehren, einen der Tage des Menschensohnes zu sehen, und werdet ihn nicht sehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'Und sie werden zu euch sagen: Siehe, hier! oder: Siehe, da! Gehet nicht hin, und folget ihnen nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Denn gleichwie der Blitz unter dem Himmel hervorstrahlend, leuchtet hin unter dem Himmel, also wird des Menschen Sohn an Seinem Tage sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Zuerst aber muß Er viel leiden und verworfen werden von diesem Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'Und wie es geschah in den Tagen Noachs, also wird es sein in den Tagen des Menschensohns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'Sie aßen, sie tranken, sie freiten, sie ließen sich freien bis zu dem Tage, da Noach in die Arche einging, und die Flut kam und sie alle verdarb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Desgleichen auch, wie es geschah in den Tagen Lots: Sie aßen, sie tranken, sie kauften, sie verkauften, sie pflanzten, sie bauten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'An dem Tage aber, da Lot aus Sodom ausging, regnete es vom Himmel Feuer und Schwefel und verdarb sie alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Ebenso wird es sein an dem Tage, da des Menschen Sohn wird geoffenbart werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Wer an selbigem Tage auf dem Dache ist, und sein Gerät im Hause, der steige nicht herab, es zu holen, und wer auf dem Felde ist desgleichen, der kehre nicht zurück nach dem, was dahinten ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Gedenket an Lots Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Wer seine Seele zu retten sucht, der wird sie verlieren, und wer sie verloren hat, der wird sie lebendig erhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Ich sage euch: In selbiger Nacht werden zwei auf einem Bette sein. Einer wird angenommen, und der andere gelassen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Zwei werden beieinander mahlen. Die eine wird angenommen, und die andere gelassen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, 'Zwei werden auf dem Felde sein. Der eine wird angenommen, und der andere gelassen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'Und sie antworteten und sagten zu Ihm: Wo, Herr? Er aber sprach zu ihnen: Wo der Leib ist, da sammeln sich die Adler.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Er sagte ihnen aber auch ein Gleichnis dafür, daß man allezeit beten und nicht verzagen sollte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Und sprach: Es war in einer Stadt ein Richter, der Gott nicht fürchtete, noch den Menschen scheute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Es war aber in selbiger Stadt eine Witwe, und die kam zu ihm und sprach: Räche mich an meinem Widersacher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'Und er wollte eine Zeitlang nicht. Danach aber sprach er bei sich: Wenn ich mich auch vor Gott nicht fürchte, noch vor dem Menschen scheue,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'Weil mir diese Witwe Ungelegenheit macht, will ich sie rächen, daß sie nicht am Ende kommt und mir ins Gesicht fährt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'Der Herr aber sagte: Ihr hört, was der Richter der Ungerechtigkeit sagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Sollet aber Gott nicht Rache verschaffen Seinen Auserwählten, die zu Ihm rufen Tag und Nacht, und Langmut mit ihnen haben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Ich sage euch, daß Er ihnen schnell Rache verschaffen wird. Doch wenn des Menschen Sohn kommt, wird Er wohl Glauben finden auf Erden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Er sagte aber auch über etliche, die auf sich selbst vertrauen, daß sie gerecht wären und die übrigen mißachteten, dies Gleichnis:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Zwei Menschen gingen hinauf in das Heiligtum, zu beten, der eine ein Pharisäer, und der andere ein Zöllner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Der Pharisäer stand da für sich und betete also: Ich danke Dir, Gott, daß ich nicht bin wie die übrigen Menschen, Räuber, Ungerechte, Ehebrecher, oder auch wie dieser Zöllner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Ich faste zweimal in der Woche und verzehnte alles, was ich besitze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Und der Zöllner stand von weitem und wollte auch nicht die Augen aufheben zum Himmel, sondern schlug an seine Brust und sprach: Gott, sei mir Sünder gnädig!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Ich sage euch: Dieser ging hinab in sein Haus gerechtfertigt mehr denn jener; denn wer sich selbst erhöht, der wird erniedrigt werden, wer aber sich selbst erniedrigt, der wird erhöht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Sie brachten auch Kindlein zu Ihm her, daß Er sie berühren möchte. Als die Jünger sie aber sahen, bedrohten sie dieselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'Jesus aber rief sie zu Sich und sprach: Lasset die Kindlein zu Mir kommen und wehret ihnen nicht; denn solcher ist das Reich Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Wahrlich, Ich sage euch: Wer das Reich Gottes nicht aufnimmt wie ein Kindlein, der wird nicht darein eingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'Und es fragte Ihn ein Oberster und sprach: Guter Lehrer, was muß ich tun, daß ich das ewige Leben ererbe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Jesus aber sprach zu ihm: Was nennst du Mich gut? Niemand ist gut, denn der alleinige Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Du weißt die Gebote: Du sollst nicht ehebrechen, du sollst nicht morden, du sollst nicht stehlen, du sollst kein falsch Zeugnis reden. Ehre deinen Vater und die Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'Er aber sprach: Dies alles habe ich gehalten von meiner Jungend auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'Als Jesus aber dies hörte, sprach Er zu ihm: Eines fehlt dir noch: Verkaufe alles, was du hast, und gib es den Armen hin, und du wirst einen Schatz im Himmel haben, und komm her und folge Mir nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'Da er aber das hörte, ward er sehr betrübt; denn er war sehr reich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Da aber Jesus sah, daß er sehr betrübt wurde, sprach Er: Wie schwer ist es für die, so Vermögen haben, in das Reich Gottes einzugehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Denn es ist leichter, daß ein Kamel durch ein Nadelöhr eingehe, denn daß ein Reicher in das Reich Gottes eingehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Da sprachen aber die, so es hörten: Wer kann dann gerettet werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'Er aber sprach: Was unmöglich ist bei Menschen, ist möglich bei Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'Petrus aber sprach: Siehe, wir haben alles verlassen und sind Dir nachgefolgt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'Er aber sprach zu ihnen: Wahrlich, Ich sage euch: Es ist niemand, der Haus oder Eltern oder Brüder oder Weib oder Kinder verläßt um des Reiches Gottes willen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'Der es nicht vielfältig wieder empfängt in dieser Zeit, und in dem zukünftigen Zeitlauf das ewige Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Er aber nahm zu Sich die Zwölfe und sprach zu ihnen: Siehe, wir ziehen hinauf gen Jerusalem, und es wird alles vollendet werden, was durch die Propheten über des Menschen Sohn geschrieben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Denn Er wird den Heiden überantwortet und verspottet und beschimpft und angespieen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'Und sie werden Ihn geißeln und töten, und am dritten Tage wird Er auferstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'Und sie verstanden davon nichts, und diese Rede war ihnen verborgen, und sie erkannten nicht, was gesagt ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Es geschah aber, da Er Jericho nahte, daß ein Blinder am Wege saß und bettelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Da er aber hörte, daß ein Gedränge durchzog, erfragte er, was das wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Sie sagten ihm aber an, daß Jesus der Nazarener vorbeigehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'Und er schrie und sprach: Jesus, Sohn Davids, erbarme dich meiner!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'Und die, so voran zogen, bedrohten ihn, er solle stillschweigen. Er aber schrie noch viel mehr: Sohn Davids, erbarme Dich meiner!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Jesus aber blieb stehen und befahl, ihn zu Ihm zu führen; da er aber sich nahte, fragte Er ihn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Und sprach: Was willst du, daß Ich dir tun soll? Er aber sprach: Herr, daß ich sehend werde!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'Und Jesus sprach zu ihm: Sei sehend; dein Glaube hat dich gerettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'Und sogleich ward er sehend, folgte Ihm nach und verherrlichte Gott. Und alles Volk, das es sah, gab Gott Lob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'Und Er kam hinein und ging durch Jericho.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'Und siehe, da war ein Mann, der mit Namen Zachäus hieß; und er war Oberzöllner, und er war reich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'Und er suchte Jesus zu sehen, wer Er wäre, und konnte nicht vor dem Gedränge; denn er war klein von Wuchs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'Und er lief voraus vornhin und stieg auf einen Maulbeerfeigenbaum, auf daß er Ihn sähe; weil Er allda vorbeiziehen sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'Und da Jesus an den Ort kam, blickte Er auf, sah ihn und sprach zu ihm: Zachäus, steige eilends herab; denn heute muß Ich in deinem Hause bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'Und er stieg eilends hernieder und nahm Ihn auf mit Freuden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'Und die es sahen, murrten alle und sagten: Bei einem sündhaften Manne ist Er zur Einkehr eingegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Zachäus aber stand und sprach zum Herrn: Siehe, Herr, die Hälfte meiner Habe gebe ich den Armen, und so ich jemand in etwas betrogen, gebe ich es vierfältig wieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Jesus aber sprach zu ihm: Heute ist diesem Hause Heil geworden, sintemal auch er ein Sohn Abrahams ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Denn des Menschen Sohn ist gekommen, zu suchen und zu retten, das verloren ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Da sie aber solches hörten, fuhr Er fort und sagte ein Gleichnis, darum, daß Er nahe bei Jerusalem war, und sie meinten, daß das Reich Gottes sogleich erscheinen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Er sprach nun: Ein wohlgeborener Mensch zog in eine ferne Landschaft, um ein Reich zu empfangen und dann zurückzukehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'Er rief aber zehn seiner Knechte und gab ihnen zehn Pfunde und sprach zu ihnen: Handelt damit, bis ich komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Seine Bürger aber haßten ihn und sandten eine Gesandtschaft hinter ihm und her und sprachen: Wir wollen nicht, daß dieser über uns König sei;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'Und es geschah, da er wiederkam, als er das Reich an sich genommen, daß er sagte, man solle ihm diese Knechte rufen, denen er das Silber gegeben hatte, auf daß er erführe, wieviel ein jeder erhandelt hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'Da trat aber herzu der erste uns sprach: Herr, dein Pfund hat zehn Pfund dazu erworben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'Und er sprach zu ihm: Wohlan, guter Knecht! weil du bist im Geringsten treu gewesen, sollst du Gewalt über zehn Städte haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'Und der zweite kam und sprach: Herr, dein Pfund hat fünf Pfund, gewonnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'Er sprach aber auch zu diesem: Und du sollst über fünf Städte sein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'Und ein anderer kam und sprach: Herr, siehe, dein Pfund, das ich im Schweißtuche daliegen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Denn ich fürchtete dich, weil du ein strenger Mensch bist. Du nimmst, das du nicht hingelegt, und erntest, das du nicht gesät hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Er aber sprach zu ihm: Aus deinem Munde richte ich dich, du schlimmer Knecht! Du wußtest, daß ich ein strenger Mensch bin, nehme, was ich nicht hingelegt, und ernte, was ich nicht gesät habe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'Und warum hast du mein Silber nicht auf die Wechselbank gegeben? So hätte ich es, wann ich gekommen wäre, mit Zins eingefordert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'Und er sprach zu den Dabeistehenden: Nehmt das Pfund von ihm weg und gebt es dem, der zehn Pfunde hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'Und sie sagten zu ihm: Herr, er hat zehn Pfunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Denn Ich sage euch: Wer da hat, dem wird gegeben werden; wer aber nicht hat, dem wird auch weggenommen werden, das er hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'Aber jene meine Feinde, die nicht wollen, daß ich König sei über sie, führet her und schlaget sie nieder vor mir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'Und als Er solches gesprochen hatte, zog Er voran auf Seinem Zug hinauf gen Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'Und es geschah, als Er nahe an Bethphage und Bethania, an den Berg, den man Ölberg heißt, kam, sandte Er zwei Seiner Jünger ab,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'Und sprach: Gehet hin in den Flecken gegenüber von euch, und wenn ihr hineinkommt, werdet ihr ein Füllen angebunden finden, auf dem noch nie ein Mensch gesessen ist. Löst es und führt es her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'Und wenn euch jemand fragt: Warum löst ihr es? so sprechet also zu ihm: Der Herr bedarf seiner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'Und die so gesandt waren, gingen hin und fanden es, wie Er ihnen gesagt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Als sie aber das Füllen lösten, sprachen dessen Herren zu ihnen: Warum löst ihr das Füllen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Sie aber sagten: Der Herr bedarf seiner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'Und sie führten es zu Jesus und warfen ihre Kleider auf das Füllen und setzten Jesus darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Da Er aber dahinzog, breiteten sie ihre Kleider unter Ihm auf den Weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'Und da Er Sich bereits dem Abhang des Ölberges nahte, fing die ganze Menge der Jünger an, freudig mit großer Stimme Gott zu loben über alle die Wundertaten, die sie gesehen hatten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'Und sprachen: Gesegnet sei der König, der da kommt im Namen des Herrn! Friede im Himmel und Herrlichkeit in den Höhen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'Und etliche der Pharisäer aus dem Gedränge sprachen zu Ihm: Lehrer, bedrohe deine Jünger!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'Und Er antwortete und sprach zu ihnen: Ich sage euch, wenn diese stilleschwiegen, so würden die Steine schreien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'Und wie Er Sich näherte, sah Er die Stadt an und weinte über sie,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'Und sprach: Wenn du erkenntest, auch du, noch an diesem deinem Tage, was für deinen Frieden ist! Nun aber ist es vor deinen Augen verborgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Denn es werden Tage über dich kommen, da deine Feinde einen Wall um dich aufwerfen, und dich ringsum umringen, und dich von allen Seiten bedrängen werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'Und sie werden dich und deine Kinder in dir zu Boden reißen und keinen Stein in dir auf dem Steine lassen, darum, daß du die Zeit deiner Heimsuchung nicht erkannt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'Und Er ging in das Heiligtum und fing an, die Verkäufer und Käufer darin auszutreiben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'Und sprach zu ihnen: Es ist geschrieben: Mein Haus ist ein Bethaus, ihr aber habt es zu einer Räuberhöhle gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'Und Er lehrte täglich im Heiligtum; die Hohenpriester aber und die Schriftgelehrten und die Vornehmsten des Volkes trachteten danach, daß sie Ihn umbrächten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'Und sie fanden nicht, was sie tun sollten; denn das ganze Volk hing Ihm an und hörte auf Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'Und es geschah an einem jener Tage, als Er das Volk im Heiligtum lehrte und das Evangelium verkündigte, da traten die Hohenpriester und die Schriftgelehrten samt den Ältesten zu Ihm,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'Und sprachen zu Ihm und sagten: Sage uns, aus was für Gewalt tust Du das? Oder wer ist es, der Dir diese Gewalt gegeben hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Er aber antwortete und sprach zu ihnen: Ich will euch auch ein Wort fragen, und sagt Mir:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Die Taufe des Johannes, war sie vom Himmel oder von Menschen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'Sie aber überlegten es sich bei sich und sagten: Sprechen wir: Vom Himmel, so wird Er sagen: Warum glaubtet ihr ihm dann nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Sprechen wir aber: Von Menschen, so wird alles Volk uns steinigen; denn es ist überzeugt, daß Johannes ein Prophet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'Und sie antworteten, sie wüßten es nicht, woher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'Und Jesus sprach zu ihnen: So sage Ich euch auch nicht, aus was für Gewalt Ich das tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Er fing aber an, dieses Gleichnis zum Volk zu sagen: Ein Mensch pflanzte einen Weinberg und gab ihn an Weingärtner aus und zog für geraume Zeit über Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'Und zur bestimmten Zeit sandte er einen Knecht an die Weingärtner, auf daß sie ihm von der Frucht des Weinberges gäben. Die Weingärtner aber stäupten ihn und sandten ihn leer hinweg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'Und er schickte noch einen anderen Knecht; auch den stäupten und beschimpften sie und sandten in leer hinweg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'Und er schickte noch eine dritten; aber auch diesen verwundeten sie und warfen ihn hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Der Herr des Weinberges aber sprach: Was soll ich tun? Ich will meinen geliebten Sohn schicken; vielleicht, wenn sie den sehen, scheuen sie sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Da die Weingärtner ihn aber sahen, bedachten sie bei sich und sprachen: Dies ist der Erbe. Kommt, lasset uns ihn töten, auf daß das Erbe unser werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'Und sie warfen ihn hinaus aus dem Weinberg und töteten ihn. Was wird ihnen nun der Herr des Weinberges tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Er wird kommen und diese Weingärtner umbringen und den Weinberg andern geben. Da sie aber das hörten, sprachen sie: Das werde doch nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'Er aber blickte sie an und sprach: Was ist denn das, das geschrieben ist: Der Stein, den die Bauleute verworfen haben, der ist zum Eckstein geworden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Jeder, der auf diesen Stein fällt, der wird zerschellen; auf den er aber fällt, den wird er zerschmettern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'Und die Hohenpriester und die Schriftgelehrten trachteten danach, daß sie zur selben Stunde Hand an Ihn legten, und sie fürchteten das Volk; denn sie erkannten, daß Er auf sie dieses Gleichnis gesagt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'Und sie hielten auf Ihn und sandten Laurer aus, die sich stellen sollten, als ob sie gerecht wären, auf daß sie Ihn in einem Worte fingen und sie Ihn der Obrigkeit und der Gewalt des Landpflegers überantworten könnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'Und sie fragten Ihn und sprachen: Lehrer, wir wissen, daß Du recht sprichst und lehrst, und nicht auf das Angesicht siehst, sondern nach der Wahrheit den Weg Gottes lehrst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Ist es uns erlaubt, dem Kaiser den Schoß zu geben, oder nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Er aber gewahrte ihre Arglist und sprach zu ihnen: Was versuchet ihr Mich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Zeigt Mir einen Denar! Wessen Bildnis und Überschrift hat er? Sie aber antworteten und sagten: Des Kaisers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'Er aber sprach zu ihnen: So gebet denn dem Kaiser, was des Kaisers ist, und Gott, was Gottes ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'Und sie vermochten nicht, Ihn in der Rede zu fangen vor dem Volk, und verwunderten sich über Seine Antwort und schwiegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'Da kamen aber etliche der Sadduzäer herzu, die da widersprechen, daß eine Auferstehung sei, fragten Ihn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'Und sprachen: Lehrer, Moses hat uns geschrieben: So jemandes Bruder stirbt, der ein Weib hat, und dieser kinderlos stirbt, soll sein Bruder dessen Weib nehmen und seinem Bruder Samen erwecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Nun waren sieben Brüder. Und der erste nahm ein Weib und starb kinderlos.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'Und der zweite nahm das Weib, und dieser starb kinderlos.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'Und der dritte nahm sie, desgleichen aber auch die sieben, und hinterließen keine Kinder und starben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Zuletzt von allen starb auch das Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'In der Auferstehung nun, wessen Weib wird sie sein von diesen? Denn die sieben haben sie zum Weibe gehabt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'Und Jesus antwortete und sprach zu ihnen: Die Söhne dieses Zeitlaufs freien und lassen sich freien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Die aber gewürdigt werden, jenen Zeitlauf und die Auferstehung von den Toten zu erlangen, die werden weder freien, noch sich freien lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'Noch können sie mehr sterben; denn sie sind den Engeln gleich, und sind Söhne Gottes, da sie Söhne der Auferstehung sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Daß aber die Toten auferweckt werden, hat auch Moses angezeigt bei dem Dornbusch, wenn er den Herrn nennt den Gott Abrahams und den Gott Isaaks und den Gott Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Gott aber ist nicht der Toten, sondern der Lebendigen; denn sie leben Ihm alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Da antworteten aber etliche der Schriftgelehrten und sagten: Lehrer, Du hast wohl gesprochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Sie wagten es aber nicht mehr, Ihn irgend etwas zu fragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Er sprach aber zu ihnen: Wie sagen sie denn, Christus sei Davids Sohn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'Und David selbst sagt in dem Buch der Psalmen: Der Herr sprach zu meinem Herrn: Setze Dich zu Meiner Rechten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'Bis daß Ich lege Deine Feinde zum Schemel Deiner Füße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'David nennt Ihn also Herr. Und wie ist er denn Sein Sohn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'Da aber alles Volk zuhörte, sprach Er zu Seinen Jüngern:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Nehmt euch in Acht vor den Schriftgelehrten, die da wollen in Gewändern wandeln und gern haben die Begrüßungen auf den Märkten und die ersten Sitze in den Synagogen und die ersten Plätze bei den Gastmählern;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'Welche die Häuser der Witwen aufessen und zum Vorwande lange beten. Diese werden desto schwereres Gericht empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Als Er aber aufblickte, sah Er, wie die Reichen ihre Gaben in den Schatzkasten einlegten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Er sah aber auch eine dürftige Witwe, die legte zwei Scherflein ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'Und Er sprach: Wahrlich, Ich sage euch, diese arme Witwe hat mehr denn alle eingelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'Denn diese alle haben von ihrem Überflusse zu den Gaben Gottes eingelegt. Sie aber hat von ihrem Mangel allen ihren Unterhalt, den sie hatte, eingelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'Und als einige vom Heiligtum sagten, daß es mit schönen Steinen und Weihgeschenken geschmückt wäre, sprach Er:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Was ihr schaut: Da werden Tage kommen, in denen nicht Stein auf Stein gelassen wird, der nicht niedergerissen würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'Sie fragten Ihn aber und sagten: Lehrer, wann wird dies nun sein? Und welches ist das Zeichen, wann das geschehen wird?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'Er aber sprach: Seht zu, daß ihr nicht irre geführt werdet; denn viele werden kommen auf Meinen Namen und sprechen: Ich bin es, und die bestimmte Zeit hat sich genaht. Geht ihnen nicht nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Wenn ihr aber von Kriegen und Zerrüttungen hört, so erschreckt nicht; denn solches muß erst geschehen; aber das Ende ist nicht alsbald da.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Dann sprach Er zu ihnen: Völkerschaft wird wider Völkerschaft und Reich wider Reich auftreten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'Große Erdbeben an Orten und Teuerungen und Pestilenzen werden sein, und große Schrecknisse und Zeichen vom Himmel geschehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'Vor alle dem aber werden sie ihre Hände an euch legen, und euch verfolgen, indem sie euch an Synagogen und in Gefängnisse überantworten, und ihr vor Könige und Landpfleger geführt werdet um Meines Namens willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'Es wird aber euch zu einem Zeugnisse geraten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Nehmt es euch nun zu Herzen, daß ihr nicht voraussorgt, wie ihr euch verantworten möget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'Denn Ich will euch Mund und Weisheit geben, der alle eure Widersacher nicht werden widersprechen, noch widerstehen können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Ihr werdet aber auch überantwortet werden von Eltern und Brüdern, und Verwandten und Freunden, und sie werden euer etliche zum Tode bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'Und ihr werdet gehaßt werden von allen um Meines Namens willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Und kein Haar von eurem Haupte soll verloren gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'In eurer Geduld besitzt ihr eure Seelen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Wenn ihr aber Jerusalem von Heerlagern umringt seht, dann erkennt, daß seine Verwüstung sich genaht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Dann sollen die, so in Judäa sind, fliehen auf die Berge, und die mitten darin sind, entweichen von dannen; und die in den Landschaften sind, gehen nicht hinein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Denn das sind die Tage der Rache, auf daß erfüllt werde alles, was geschrieben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Wehe aber den Schwangeren und den Säugenden in jenen Tagen! denn große Not wird sein auf Erden, und Zorn wider dieses Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'Und durch des Schwertes Schärfe werden sie fallen und gefangen geführt unter alle Völkerschaften, und zertreten werden wird Jerusalem von den Völkerschaften, bis auch der Völkerschaften bestimmte Zeiten erfüllt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'Und es werden Zeichen sein in Sonne und Mond und Sternen und auf Erden wird sein Bedrängnis der Völkerschaften mit Verzweiflung ob des brausenden Meeres und den Wogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'Die Menschen werden entseelt vor Furcht und Erwartung der Dinge, die da über den Erdkreis kommen werden; denn der Himmel Kräfte werden erschüttert werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'Und dann werden sie des Menschen Sohn kommen sehen in einer Wolke mit Kraft und großer Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Wenn dies anfängt zu geschehen, so richtet euch auf und erhebet eure Häupter, denn eure Erlösung naht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'Und Er sagte ihnen eine Gleichnis: Seht den Feigenbaum und alle Bäume.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'Wenn sie jetzt hervorknospen, seht ihr von euch selber und erkennt, daß bereits der Sommer nahe ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'So auch ihr: Wenn ihr seht, daß dies geschieht, so erkennt, daß das Reich Gottes nahe ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Wahrlich, Ich sage euch: Dieses Geschlecht wird nicht vergehen, bis alles dies geschieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Himmel und Erde werden vergehen, aber Meine Worte werden nicht vergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Aber habt Acht auf euch, daß eure Herzen nicht beschwert werden mit Völlerei und Trunkenheit und Sorgen um den Unterhalt, und jener Tag nicht plötzlich dastehe über euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Denn wie ein Fallstrick wird er über alle kommen, die auf dem Angesicht der ganzen Erde wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'So wachet denn alle Zeit, und flehet, daß ihr gewürdigt werdet, diesem allem, das da geschehen soll, zu entfliehen und zu stehen vor des Menschen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'Er war aber die Tage über im Heiligtum und lehrte, nachts aber ging Er hinaus und übernachtete auf dem Berge, so man den Ölberg heißt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'Und alles Volk kam frühe zu Ihm ins Heiligtum, um Ihn zu hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Es nahte aber das Fest der ungesäuerten Brote, genannt das Pascha.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'Und die Hohenpriester und die Schriftgelehrten trachteten danach, wie sie Ihn umbrächten; denn sie fürchteten sich vor dem Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Es fuhr aber der Satan ein in Judas, der Iskariot hieß, der aus der Zahl der Zwölfe war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'Und er ging hin und unterredete sich mit den Hohenpriestern und den Hauptleuten, wie er Ihn ihnen überantworten wollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'Und sie freuten sich und kamen überein, ihm Silber zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'Und er sagte zu und suchte eine gute Gelegenheit, Ihn ohne Gedränge zu überantworten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Es kam aber der Tag der ungesäuerten Brote, an dem das Pascha geschlachtet werden sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'Und Er sandte Petrus und Johannes und sprach: Ziehet hin, bereitet uns das Pascha, auf daß wir es essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Sie aber sagten zu Ihm: Wo willst Du, daß wir es bereiten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'Er aber sagte zu ihnen: Siehe, wenn ihr in die Stadt hineinkommt, wird euch ein Mensch begegnen, der einen Krug mit Wasser trägt. Dem folgt nach in das Haus, da er hineingeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'Und ihr sollt dem Hausherrn des Hauses sagen: Der Lehrer läßt dir sagen: Wo ist die Herberge, da Ich mit Meinen Jüngern das Pascha essen kann?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'Und er wird euch einen großen bepolsterten Obersaal zeigen. Dort bereitet es!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Sie aber gingen hin und fanden es, wie Er ihnen gesagt hatte, und bereiteten das Pascha.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'Und da die Stunde kam, ließ Er Sich nieder und mit Ihm die zwölf Apostel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'Und Er sprach zu ihnen: Mit Verlangen habe Ich begehrt, dies Pascha mit euch zu essen, ehe denn Ich leide.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'Denn Ich sage euch, daß Ich nicht mehr davon essen werde, bis es erfüllt wird im Reiche Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'Und Er empfing den Kelch, dankte und sprach: Nehmet dies und verteilet es unter euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Denn Ich sage euch, daß Ich von dem Gewächse des Weinstocks nicht mehr trinken werde, bis das Reich Gottes komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'Und Er nahm Brot, dankte, brach es und gab es ihnen und sprach: Dies ist Mein Leib, der für euch gegeben wird, das tut zu Meinem Gedächtnisse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Desselbigen gleichen auch den Kelch, nach dem Abendmahl, und sprach: Dieser Kelch ist der neue Bund in Meinem Blute, das für euch vergossen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Doch siehe, die Hand dessen, der Mich verrät, ist mit Mir über Tisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Und zwar geht des Menschen Sohn hin, wie es bestimmt ist; doch wehe demselbigen Menschen, durch den Er verraten wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'Sie aber fingen an, untereinander sich zu befragen, wer es wohl wäre unter ihnen, der solches tun würde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Es ward aber auch ein Wettstreit unter ihnen, welcher von ihnen für den Größten zu halten wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'Er aber sprach zu ihnen: Die Könige der Völkerschaften herrschen über sie, und die Gewalt haben über sie, heißen sie Wohltäter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Ihr aber nicht also; sondern der Größte unter euch werde wie der Jüngste; und der Leiter wie der Diener.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Denn welcher ist der größere? der zu Tische liegt, oder der bedient? Ist es nicht der, so zu Tische liegt? Ich aber bin in eurer Mitte, wie einer, der dient.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'Ihr aber seid es, die in Meinen Versuchungen bei Mir geblieben seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'Und so bescheide Ich euch das Reich, wie Mir es Mein Vater beschieden hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'Daß ihr essen und trinken sollt an Meinem Tisch in Meinem Reich, und sitzen auf Thronen und richten die zwölf Stämme Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Der Herr aber sprach: Simon, Simon, siehe, der Satan hat sich auch ausgebeten, um euch zu sichten, wie den Weizen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'Ich aber habe für dich gefleht, damit dein Glaube nicht zu Ende gehe; und wenn du dereinst dich bekehrst, so festige du deine Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'Er aber sprach zu Ihm: Herr, ich bin bereit, mit Dir ins Gefängnis und in den Tod zu gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'Er aber sprach: Ich sage dir, Petrus, der Hahn wird heute nicht krähen, ehe denn du dreimal verleugnet hast, daß du Mich kennst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'Und Er sprach zu ihnen: Wenn Ich euch aussandte ohne Beutel und Tasche und Schuhe, hat euch je etwas gemangelt? Sie aber sprachen: Nichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'Da sprach Er zu ihnen: Nun aber, wer einen Beutel hat, der nehme ihn, desgleichen auch die Tasche. Und wer keine hat, der verkaufe sein Kleid und kaufe ein Schwert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Denn Ich sage euch: Es muß auch das noch an Mir vollendet werden, das geschrieben steht: Und Er ist unter die Missetäter gerechnet! Denn das, was Mich angeht, hat ein Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Sie sprachen aber: Herr, siehe, hier sind zwei Schwerter. Er aber sprach zu ihnen: Es ist genug!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'Und Er ging hinaus und nach Seiner Gewohnheit ging Er hin an den Ölberg; es folgten Ihm aber auch Seine Jünger nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'Als Er aber an den Ort kam, sprach Er zu ihnen: Betet, daß ihr nicht in Versuchung kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'Und Er riß Sich los von ihnen bei einem Steinwurf, fiel auf die Knie und betete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'Und Er sprach: Vater, bist Du willens, so laß diesen Kelch an Mir vorübergehen! Doch nicht Mein Wille, sondern der Deinige geschehe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Es erschien Ihm aber ein Engel vom Himmel und stärkte Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'Und es geschah, daß Er mit dem Tode rang, und betete insbrünstiger. Sein Schweiß aber ward wie Blutstropfen, die zur Erde hinabfallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'Und Er stand auf vom Gebet und kam zu Seinen Jüngern und fand sie schlummernd vor Betrübnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'Und Er sprach zu ihnen: Was schlummert ihr? Steht auf und betet, auf daß ihr nicht in Versuchung kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Da Er aber noch redete, siehe, da kam ein Gedränge, und einer von den Zwölfen, Judas genannt, ging vor ihnen her und nahte sich Jesus, Ihn zu küssen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Jesus aber sprach zu ihm: Judas, verrätst du des Menschen Sohn mit einem Kuß?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Da aber die, so um Ihn waren, sahen, was da werden wollte, sprachen sie zu Ihm: Herr, sollen wir mit dem Schwert dreinschlagen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'Und einer von ihnen schlug des Hohenpriesters Knecht und hieb ihm das rechte Ohr ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Jesus aber antwortete und sprach: Lasset es so weit sein! Und Er berührte sein Ohr und heilte ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'Jesus aber sprach zu den Hohenpriestern und den Hauptleuten des Heiligtums und den Ältesten, die über Ihn hergekommen waren: Wie gegen einen Räuber seid ihr mit Schwertern und Knitteln ausgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Täglich war Ich bei euch im Heiligtum, und ihr habt keine Hand gegen Mich ausgereckt. Aber dies ist eure Stunde und die Gewalt der Finsternis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'Sie nahmen Ihn aber und führten Ihn und brachten Ihn in das Haus des Hohenpriesters hinein. Petrus aber folgte nach von weitem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'Sie hatten aber mitten im Hof ein Feuer angezündet, und setzten sich zusammen, und Petrus setzte sich in ihre Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Als ihn aber eine Magd beim Lichte sitzen sah, sah sie ihn fest an und sprach: Dieser war auch mit Ihm!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'Er aber verleugnete Ihn und sprach: Weib, ich kenne Ihn nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'Und nach einer Weile sah ihn ein anderer und sagte: Auch du bist einer von ihnen! Petrus aber sprach: Mensch, ich bin es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'Und nach Verlauf von etwa einer Stunde bekräftigte es ein anderer und sprach: Wahrhaftig, der da ist auch mit Ihm gewesen; denn er ist ja auch ein Galiläer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Petrus aber sprach: Mensch, ich weiß nicht, was du sagst. Und sogleich, da er noch redete, krähte der Hahn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'Und der Herr wandte Sich und blickte Petrus an, und Petrus gedachte an das Wort des Herrn, als Er zu ihm gesprochen: Ehe der Hahn kräht, wirst du Mich dreimal verleugnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'Und Petrus ging hinaus und weinte bitterlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'Und die Männer, die Jesus festhielten, verspotteten und stäupten Ihn;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'Und sie umhüllten Ihn, schlugen Ihn ins Angesicht, und fragten ihn und sagten: Weissage, wer ist es, der Dich schlug?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'Und vieles andere sprachen sie lästernd wider Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'Und als es Tag ward, versammelten sich die Ältesten des Volkes, die Hohenpriester und Schriftgelehrten, führten Ihn hinauf in ihren Rat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Und sprachen: Bist Du Christus, so sage es uns! Er aber sprach zu ihnen: Sage Ich es euch, so glaubet ihr nicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'Wenn Ich euch auch fragte, so würdet ihr Mir nicht antworten, noch Mich losgeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Von nun wird des Menschen Sohn sitzen zur Rechten der Kraft Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'Sie aber sprachen alle: So bist Du den Gottes Sohn? Er aber sprach zu ihnen: Ihr sagt es; denn Ich bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'Sie aber sprachen: Was bedürfen wir weiter Zeugnis? Denn wir selbst haben es aus Seinem Mund gehört!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'Und ihre ganze Menge stand auf, und sie führten Ihn zu Pilatus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'Sie fingen aber an, Ihn zu verklagen, und sagten: Den haben wir gefunden, daß Er unsere Völkerschaft verkehrt und ihr wehrt, dem Kaiser den Schoß zu geben, indem Er sagt, Er sei Christus, ein König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'Pilatus aber fragte Ihn und sprach: Bist Du der Juden König? Er aber antwortete ihm und sprach: Du sagst es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Pilatus aber sprach zu den Hohenpriestern und zu dem Gedränge: Ich finde keine Schuld an diesem Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Sie aber bestanden darauf und sagten: Er wiegelt das Volk auf, indem Er durch ganz Judäa hin lehrt und in Galiläa angefangen hat bis hierher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Als Pilatus aber von Galiläa hörte, fragte er, ob der Mensch ein Galiläer wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'Und da er erfuhr, daß Er aus des Herodes Gebiete war, schickte er Ihn hin an Herodes, der in selbigen Tagen selbst auch in Jerusalem war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Herodes aber freute sich ungemein, da er Jesus sah; denn er hatte Ihn schon längst sehen wollen, weil er viel von Ihm hörte, und er hoffte, er würde ein Zeichen von Ihm sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'Und er fragte Ihn mit vielen Worten; Er antwortete ihm aber nichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'Aber die Hohenpriester und die Schriftgelehrten standen und verklagten Ihn heftig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Herodes aber mit seinen Kriegsleuten verachtete und verspottete Ihn, umkleidete Ihn mit glänzenden Anzuge, und schickte Ihn an Pilatus zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'Auf selbigen Tag wurden Pilatus und Herodes Freunde miteinander; denn zuvor waren sie in Feindschaft gegeneinander gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'Pilatus aber rief die Hohenpriester und die Obersten und das Volk zusammen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'Und sprach zu ihnen: Ihr habt diesen Menschen vor mich gebracht, als mache Er das Volk abwendig; und siehe, ich selbst habe Ihn vor euch verhört und an diesem Menschen nichts gefunden, das Ihn dessen schuldig machte, was ihr gegen Ihn klagt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Herodes aber auch nicht; denn ich schickte euch an ihn, und siehe, Er hat nichts dargetan, was des Todes wert wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Darum will ich Ihn züchtigen und losgeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, 'Es war aber Not, daß er ihnen auf das Fest einen losgebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Sie aber schrien in ganzer Menge und sagten: Nimm diesen weg, gib uns aber Barabbas los!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Dieser aber war wegen eines Aufstandes, so in der Stadt geschah, und eines Mordes wegen ins Gefängnis geworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilatus rief nun abermals ihnen zu und wollte Jesus losgeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Sie aber riefen ihm zu und sprachen: Kreuzige, kreuzige Ihn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'Er aber sprach zum drittenmal zu ihnen: Was hat denn Dieser Böses getan? Ich habe keine Todesschuld an Ihm gefunden, darum will ich Ihn züchtigen und losgeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'Sie aber lagen ihm an mit lauten Stimmen und baten, daß Er gekreuzigt würde. Und ihre und der Hohenpriester Stimmen wurden immer stärker.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'Pilatus aber urteilte, daß nach ihrer Bitte geschehen sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'Er gab aber den los, der wegen Aufstand und Mord ins Gefängnis geworfen war, um den sie baten; Jesus aber übergab er ihrem Willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'Und da sie Ihn abführten, erfaßten sie einen Simon von Kyrene, der vom Felde kam, und legten ihm das Kreuz auf, daß er es hinter Jesus hertrüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Es folgte Ihm aber eine große Menge des Volkes und Weiber nach, welche jammerten und um Ihn klagten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Jesus aber wandte Sich um zu ihnen und sprach: Ihr Töchter von Jerusalem! Weinet nicht über Mich; weinet vielmehr über euch selbst und über eure Kinder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Denn siehe, es kommen Tage, in denen sie sagen werden: Selig sind die Unfruchtbaren und die Leiber, die nicht geboren, und die Brüste, die nicht gesäugt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Dann werden sie anfangen und zu den Bergen sagen: Fallet über uns! und zu den Hügeln: Bedecket uns!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Denn wenn sie solches tun am grünen Holz, was will mit dem dürren werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Es wurden aber auch zwei andere, Übeltäter, hingeführt, daß sie mit Ihm umge- bracht würden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'Und als sie an den Ort hinkamen, den man heißt Schädelstätte, kreuzigten sie Ihn allda und die Übeltäter, den einen zur Rechten, den anderen aber zu Linken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'Jesus aber sprach: Vater, vergib ihnen; denn sie wissen nicht, was sie tun. Sie zerteilten aber Seine Kleider und warfen das Los darum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'Und das Volk stand da und schaute zu; die Obersten aber mit ihnen spotteten Ihn auch aus und sagten: Andere hat Er gerettet; Er rette Sich selber; so Dieser ist Christus, der Auserwählte Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Aber auch die Kriegsknechte verspotteten Ihn, kamen herzu und brachten Ihm Essig herbei,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'Und sprachen: Wenn Du der Juden König bist, so rette Dich selber!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Es war aber auch eine Überschrift über Ihm, geschrieben in griechischer, lateinischer und hebräischer Schrift: Dies ist der Juden König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'Einer aber der Übeltäter, die gehängt waren, lästerte Ihn und sprach: Wenn Du der Christus bist, so rette Dich Selbst und uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Der andere aber antwortete, und bedrohte ihn und sagte: Fürchtest du dich nicht vor Gott, der du doch in gleicher Verurteilung bist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'Und wir zwar gerechter Weise; denn wir empfangen, was unsere Taten wert sind; Dieser aber hat nichts Ungehöriges getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'Und zu Jesus sprach er: Gedenke meiner, Herr, wenn Du in Dein Reich kommst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'Und Jesus sprach zu ihm: Wahrlich, Ich sage dir, heute wirst du mit Mir im Paradiese sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'Es war aber um die sechste Stunde, und es ward eine Finsternis über das ganze Land bis zur neunten Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'Und die Sonne ward verfinstert, und der Vorhang des Tempels riß mitten entzwei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'Und Jesus rief mit großer Stimme und sprach: Vater, in Deine Hände befehle Ich Meinen Geist. Und als Er das gesagt hatte, hauchte Er aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Da aber der Hauptmann sah, was geschah, verherrlichte er Gott und sprach: In der Tat, dieser Mensch war gerecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'Und all das Gedränge, das zum Schauen herbeigekommen war, da sie schauten, was geschah, schlugen sie an ihre Brust und kehrten zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Es standen aber von weitem alle Seine Bekannten und die Weiber, die Ihm aus Galiläa nachgefolgt waren, und sahen das an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'Und siehe, ein Mann mit Namen Joseph, der ein Ratsherr war, ein guter und gerechter Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, 'Er hatte ihrem Ratschluß und ihrem Tun nicht beigestimmt aus Arimathäa, einer Stadt der Juden, der selber auch auf das Reich Gottes wartete,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'Der ging hin zu Pilatus und bat um den Leib Jesu;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'Und er nahm ihn ab, wickelte ihn in feine Leinwand und legte ihn in eine aus dem Felsen ausgehauene Gruft, darin niemand je gelegen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'Und es war Rüsttag und der Sabbath brach an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Es folgten aber auch die Weiber nach, die mit Ihm aus Galiläa gekommen waren, und schauten die Gruft, und wie Sein Leib gelegt ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'Sie kehrten aber zurück und bereiteten Spezereien und Salben, und waren den Sabbath über stille nach dem Gebote.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'Am ersten Wochentage aber, tief in der Frühe, kamen sie zur Gruft und brachten die Spezereien, die sie bereitet hatten, und etliche mit ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Sie fanden aber den Stein von der Gruft weggewälzt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'Und gingen hinein und fanden den Leib des Herrn Jesus nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'Und es geschah, da sie darüber betroffen waren, und siehe, da standen zwei Männer in strahlendem Anzuge bei ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Und da sie sich fürchteten und ihr Angesicht zur Erde neigten, sprachen sie zu ihnen: Was suchet ihr den Lebendigen bei den Toten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Er ist nicht hier, sondern ist auferweckt! Gedenket, wie Er zu euch redete, da Er noch in Galiläa war,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'Und sagte: Des Menschen Sohn muß in die Hände sündhafter Menschen überantwortet und gekreuzigt werden und am dritten Tage auferstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'Und sie gedachten Seiner Reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'Und sie kehrten zurück von der Gruft und sagten das alles den Elfen und allen übrigen an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Dies waren aber Maria von Magdala und Johannah und Maria, des Jakobus Mutter, und die übrigen mit ihnen, die solches den Aposteln sagten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'Und ihre Reden erschienen vor ihnen wie ein Märchen, und sie glaubten ihnen nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'Petrus aber stand auf, lief zu der Gruft, bückte sich hinein und sah die leinenen Tücher alleine liegen, und ging weg und verwunderte sich über das Geschehene.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'Und siehe, zwei von ihnen gingen hin an demselbigen Tag nach einem Flecken, der sechzig Stadien von Jerusalem entfernt war, mit Namen Emmaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'Und sie unterhielten sich miteinander über alles, das sich zugetragen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'Und es geschah, als sie sich so unterhielten und sich befragten, daß Jesus zu ihnen nahte, und mit ihnen dahinging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Aber ihre Augen wurden festgehalten, daß sie Ihn nicht erkannten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'Er aber sprach zu ihnen: Was sind diese Worte, die ihr da miteinander wechselt beim Wandeln und sehet düster?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Der eine aber, mit Namen Kleopas, antwortete und sprach zu Ihm: Bist du der einzige Fremdling in Jerusalem, der nicht weiß, was in diesen Tagen allda geschehen ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Und Er sprach zu ihnen: Welches? Sie aber sprachen zu Ihm: Das über Jesus, den Nazarener, Welcher war ein Mann, ein Prophet, kräftig in Werk und Wort vor Gott und allem Volk;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'Wie Ihn unsere Hohenpriester und Obersten zum Urteil des Todes überantwortet und gekreuzigt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Wir aber hofften, daß Er Der sei, Der Israel erlösen sollte. Und es ist bei alledem heute der dritte Tag, daß solches geschehen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Aber es haben uns auch einige Weiber von den unseren außer uns gebracht, die in der Frühe zur Gruft kamen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'Und da sie Seinen Leib allda nicht gefunden, kommen sie und sagen, sie hätten auch eine Erscheinung von Engeln gesehen, die sagen, Er lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'Und etliche derer, die mit uns sind, gingen hin zur Gruft, und fanden es so, wie die Weiber gesagt; Ihn aber sahen sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'Und Er sprach zu ihnen: O ihr Unsinnigen und träg von Herzen zu glauben an alles, das die Propheten geredet haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Mußte nicht Christus solches leiden und eingehen zu Seiner Herrlichkeit?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'Und Er fing an mit Moses und allen Propheten und legte ihnen in allen Schriften aus, was über Ihn geschrieben war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'Und sie nahten sich dem Flecken, wohin sie gingen; und Er tat, als wollte Er fürder ziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'Und sie drangen in Ihn und sprachen: Bleibe bei uns; denn es ist gegen Abend und der Tag hat sich geneigt. Und Er ging hinein, bei ihnen zu bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'Und es geschah, als Er Sich mit ihnen niedergelassen, nahm Er das Brot, segnete und brach es, und gab es ihnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'Da wurden aber ihre Augen geöffnet und sie erkannten Ihn. Und Er ward ihnen unsichtbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'Und sie sprachen zueinander: Brannte nicht unser Herz in uns, wie Er zu uns redete auf dem Wege und uns die Schrift auftat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'Und sie standen auf zur selbigen Stunde und kehrten nach Jerusalem zurück und fanden die Elf und die mit ihnen waren, beisammen versammelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Und sie sprachen: Der Herr ist in der Tat auferstanden und dem Simon erschienen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'Und sie taten kund, was auf dem Wege geschehen, und wie Er von ihnen beim Brechen des Brotes erkannt worden wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Während sie aber solches redeten, stand Jesus Selbst in ihrer Mitte und sprach zu ihnen: Friede sei mit euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'Sie erschraken aber und fürchteten sich und meinten einen Geist zu schauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'Und Er sprach zu ihnen: Was erbebet ihr, und warum steigen solche Gedanken in euren Herzen auf?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Seht Meine Hände und Meine Füße! daß Ich Selbst es bin. Befühlt Mich und seht! denn ein Geist hat nicht Fleisch und Bein, wie ihr schaut, daß Ich habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'Und da Er dies gesprochen hatte, zeigte Er ihnen die Hände und die Füße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Als sie aber vor Freuden noch nicht glaubten und sich verwunderten, sprach Er zu ihnen: Habt ihr etwas Speise hier?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Sie aber gaben Ihm einen Teil eines gebratenen Fisches und von einer Honigwabe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'Und Er nahm es vor ihnen und aß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Er sprach aber zu ihnen: Das sind die Worte, die Ich zu euch redete, da Ich noch bei euch war, daß alles erfüllt werden müßte, was in Moses Gesetz und in den Propheten und den Psalmen von Mir geschrieben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Dann tat Er ihnen das Verständnis auf, daß sie die Schriften verstünden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'Und sprach zu ihnen: So ist geschrieben, und also mußte Christus leiden und am dritten Tage von den Toten auferstehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'Und gepredigt werden in Seinem Namen Buße und Vergebung der Sünden unter allen Völkerschaften, anfangend in Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Ihr aber seid dessen Zeugen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'Und siehe, Ich sende auf euch die Verheißung Meines Vaters; ihr aber sollt bleiben in der Stadt Jerusalem, bis daß ihr mit Kraft aus den Höhen angetan werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Er führte sie aber hinaus bis gen Bethanien, hob Seine Hände auf und segnete sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'Und es geschah, da Er sie segnete, schied Er von ihnen und ward in den Himmel hinaufgetragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'Und sie beteten Ihn an und kehrten mit großer Freude nach Jerusalem zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'Und sie waren allezeit im Heiligtum, lobten und segneten Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'Im Anfang war das Wort, und das Wort war bei Gott und Gott war das Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Dasselbe war im Anfang bei Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Alles ist durch dasselbe geworden, und ohne dasselbe ist nichts geworden, das geworden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'In Ihm war Leben, und das Leben war das Licht der Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'Und das Licht scheint in der Finsternis, und die Finsternis hat es nicht begriffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Es ward ein Mensch von Gott gesandt, mit Namen Johannes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Derselbe kam zum Zeugnis, daß er von dem Lichte zeugete, auf daß alle durch ihn glaubten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'Er war nicht das Licht, sondern sollte zeugen von dem Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Das war das wahrhaftige Licht, das jeden Menschen erleuchtet, der in die Welt kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Er war in der Welt, und die Welt ist durch Ihn geworden, aber die Welt erkannte Ihn nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'Er kam in Sein Eigenes, aber die Eigenen nahmen Ihn nicht auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'Wie viele Ihn aber aufnahmen, denen gab Er Gewalt, Gottes Kinder zu werden, denen, die an Seinen Namen glauben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'Welche nicht aus dem Geblüt, noch aus dem Willen des Fleisches, noch aus dem Willen eines Mannes, sondern aus Gott geboren sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'Und das Wort ward Fleisch, und wohnte unter uns, und wir schauten Seine Herrlichkeit, eine Herrlichkeit als des Eingeborenen vom Vater, voller Gnade und Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Johannes zeugt von Ihm, ruft und spricht: Dieser war es, von Dem ich sagte: Der nach mir kommt, ist vor mir gewesen; denn Er war eher, denn ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'Und aus Seiner Fülle haben wir alle genommen, und Gnade um Gnade.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Denn das Gesetz ist durch Moses gegeben, die Gnade und Wahrheit durch Jesus Christus geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Niemand hat Gott je gesehen; der eingeborene Sohn, Der in des Vaters Schoße ist, Der hat Ihn kundgemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'Und dies ist das Zeugnis des Johannes, als die Juden aus Jerusalem Priester und Leviten absandten, daß sie ihn fragten: Wer bist du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'Und er bekannte und leugnete nicht, und er bekannte: Ich bin nicht der Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'Und sie fragten ihn: Was denn? Bist du Elias? Und er spricht: Ich bin es nicht. Bist du der Prophet? Und er antwortete: Nein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Da sprachen sie zu ihm: Wer bist du? auf daß wir Antwort geben denen, die uns geschickt haben. Was sagst du von dir selbst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Er sprach: Ich bin die Stimme eines, der da ruft in der Wüste: Machet gerade den Weg des Herrn, wie Jesajah, der Prophet, gesagt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Und die Abgesandten waren von den Pharisäern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'Und sie fragten ihn und sagten zu ihm: Was taufst du dann, wenn du nicht Christus bist, noch Elias, noch der Prophet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Johannes antwortete ihnen und sprach: Ich taufe mit Wasser, aber in eurer Mitte steht Einer, Den ihr nicht kennt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'Er ist es, Der nach mir kommt, Welcher vor mir gewesen ist, Dem ich nicht wert bin, die Schuhriemen zu lösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'Dies geschah in Bethanien, jenseits des Jordan, wo Johannes taufte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Am folgenden Tag sieht Johannes Jesu zu ihm kommen und spricht: Siehe, das Lamm Gottes, das der Welt Sünde wegnimmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Dieser ist es, von Dem ich gesagt habe: Nach mir kommt ein Mann, Der vor mir gewesen ist; denn Er war eher denn ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'Und ich kannte Ihn nicht; aber damit Er Israel offenbar würde, darum bin ich gekommen, mit dem Wasser zu taufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'Und Johannes zeugte und sprach: Ich sah den Geist wie eine Taube herabfahren vom Himmel, und er blieb auf Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'Und ich kannte ihn nicht; aber Der mich schickte, zu taufen mit Wasser, Derselbe sprach zu mir: Auf wen du siehst den Geist herabfahren und auf Ihm bleiben, Derselbige ist es, Der mit dem Heiligen Geist tauft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'Und ich habe es gesehen und bezeugt, daß Dieser ist der Sohn Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Des folgenden Tages stand Johannes wiederum da, und zwei von seinen Jüngern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'Und wie er Jesus wandeln sah, spricht er: Siehe, das Lamm Gottes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'Und die zwei Jünger hörten ihn reden und folgten Jesus nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Jesus aber wandte Sich um und sah sie Sich nachfolgen und sprach zu ihnen: Was sucht ihr? Sie aber sprachen zu Ihm: Rabbi, das ist verdolmetscht Lehrer. Wo verbleibst Du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Er spricht zu ihnen: Kommt und seht. Sie kamen und sahen, wo Er verblieb, und blieben selbigen Tag bei Ihm; es war um die zehnte Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Andreas, der Bruder des Simon Petrus, war einer von den zweien, die es von Johannes hörten und Ihm nachfolgten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Dieser findet am ersten seinen eigenen Bruder Simon und spricht zu ihm: Wir haben den Messias welches ist verdolmetscht, der Christus gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Und er führte ihn zu Jesus. Jesus aber blickte ihn an und sprach: Du bist Simon, Jonahs Sohn, du sollst Kephas heißen, was verdolmetscht ist: Petrus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Am folgenden Tage wollte Er nach Galiläa ausziehen; und Er findet Philippus, und Jesus spricht zu ihm: Folge Mir nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Philippus aber war von Bethsaida, aus der Stadt des Andreas und Petrus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Philippus findet Nathanael und spricht zu ihm: Wir haben Den gefunden, von Dem Moses im Gesetz und die Propheten geschrieben, Jesus, Josephs Sohn von Nazareth.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Und Nathanael sprach zu ihm: Kann aus Nazareth etwas Gutes sein? Spricht zu ihm Philippus: Komm und siehe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jesus sieht Nathanael zu Ihm kommen und spricht zu ihm: Siehe da, wahrhaftig ein Israelite, in dem kein Trug ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Nathanael spricht zu Ihm: Woher erkennst Du mich? Jesus antwortete und sprach zu ihm: Ehe dir Philippus rief, da du unter dem Feigenbaum warst, sah Ich dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Nathanael antwortete und sprach zu Ihm: Rabbi, Du bist Gottes Sohn, Du bist der König von Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jesus antwortete und sprach zu ihm: Weil Ich dir sagte, Ich sah dich unter dem Feigenbaum, glaubst du? Du wirst Größeres, denn dieses sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'Und Er spricht zu ihm: Wahrlich, wahrlich, Ich sage euch: Von nun an werdet ihr sehen den Himmel aufgetan und die Engel Gottes aufsteigen und herabsteigen auf des Menschen Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'Und am dritten Tage war eine Hochzeit zu Kana in Galiläa; und die Mutter Jesu war daselbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Aber auch Jesus und Seiner Jünger waren auf die Hochzeit geladen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'Und da es an Wein mangelte, spricht die Mutter Jesu zu Ihm: Sie haben keinen Wein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'Spricht zu ihr Jesus: Weib, was ist Mein und dein? Meine Stunde ist noch nicht gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Spricht Seine Mutter zu den Dienern: Was Er euch sagt, das tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Es waren aber allda sechs steinerne Wasserkrüge gesetzt für die Reinigung der Juden, von denen jeder zwei oder drei Eimer faßte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Jesus spricht zu ihnen: Machet die Wasserkrüge voll mit Wasser! Und sie machten sie voll bis oben an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'Und Er spricht zu ihnen: Schöpft nun und bringt es dem Speisemeister. Und sie brachten es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Wie aber der Speisemeister das Wasser, das Wein geworden, kostete und er wußte nicht, woher er war; die Diener aber, die das Wasser geschöpft hatten, wußten es, ruft der Speisemeister den Bräutigam,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'Und spricht zu ihm: Jedermann setzt zuerst den guten Wein vor, und wenn sie wohl getrunken haben, dann den geringeren; du hast den guten Wein bis jetzt behalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Diesen Anfang Seiner Zeichen tat Jesus zu Kana in Galiläa und offenbarte Seine Herrlichkeit. Und Seine Jünger glaubten an Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Nach diesem zog Er hinab gen Kapernaum, Er und Seine Mutter und Seine Brüder und Seine Jünger, und sie blieben allda nicht viele Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'Und der Juden Pascha war nahe, und Jesus zog hinauf nach Jerusalem;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'Und fand im Heiligtum, die da Ochsen und Schafe und Tauben verkauften, und die Wechsler sitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'Und Er machte eine Geißel aus Stricken und trieb alle hinaus aus dem Heiligtum, und auch die Schafe und Ochsen, und verschüttete den Geldwechslern die Münze, und stieß die Tische um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'Und zu den Verkäufern der Tauben sprach Er: Nehmt diese von dannen, und macht nicht Meines Vaters Haus zum Haus des Handels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Seine Jünger aber gedachten daran, daß geschrieben ist: Der Eifer um Dein Haus verzehret Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Die Juden antworteten nun und sprachen zu Ihm: Was für ein Zeichen zeigst Du uns, daß Du solches tust?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jesus antwortete und sprach zu ihnen: Brechet diesen Tempel ab, und in drei Tagen will Ich ihn aufrichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Da sprachen die Juden: Sechsundvierzig Jahre sind an diesem Tempel gebaut worden, und Du willst ihn in drei Tagen aufrichten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Er aber sprach vom Tempel Seines Leibes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Als Er dann von den Toten auferweckt war, gedachten Seine Jünger daran, daß Er solches gesagt hatte, und sie glaubten der Schrift und dem Worte, das Jesus sprach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Da Er aber zu Jerusalem war am Pascha auf dem Feste, glaubten viele an Seinen Namen, da sie die Zeichen schauten, die Er tat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'Er aber, Jesus, vertraute Sich ihnen nicht, weil Er alle erkannte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'Und weil Er nicht bedurfte, daß jemand zeugte von dem Menschen; denn Er erkannte Selbst, was im Menschen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Es war aber ein Mensch aus den Pharisäern, mit Namen Nikodemus, ein Oberster der Juden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Dieser kam zu Ihm bei Nacht und sprach zu Ihm: Rabbi, wir wissen, daß Du ein Lehrer bist, von Gott gekommen; denn niemand kann solche Zeichen tun, die Du tust, es sei denn Gott mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jesus antwortete und sprach zu ihm: Wahrlich, wahrlich, Ich sage dir: Es sei denn, daß jemand von neuem geboren werde, so kann er das Reich Gottes nicht sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Nikodemus spricht zu Ihm: Wie kann ein Mensch geboren werden, wenn er ein Greis ist? Kann er zum zweiten Mal in seiner Mutter Leib eingehen und geboren werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jesus antwortete: Wahrlich, wahrlich, Ich sage dir: Es sei denn, daß jemand aus Wasser und Geist geboren werde, so kann er nicht in das Reich Gottes eingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Was aus dem Fleisch geboren ist, ist Fleisch; und was aus dem Geist geboren ist, ist Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Verwundere dich nicht, daß Ich zur dir gesagt habe: Ihr müsset von neuem geboren werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Der Wind weht, wo er will, und du hörst seine Stimme, weißt aber nicht, von wannen er kommt, und wohin er geht. Also ist ein jeglicher, der aus dem Geist geboren ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikodemus antwortete und sprach zu Ihm: Wie kann solches geschehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jesus antwortete und sprach zu ihm: Bist du ein Lehrer Israels, und erkennst das nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Wahrlich, wahrlich, Ich sage dir: Wir reden, was wir wissen, und zeugen, das wir gesehen haben, und ihr nehmt unser Zeugnis nicht an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Wenn Ich vom Irdischen zu euch sprach, und ihr glaubt nicht, wie werdet ihr glauben, wenn Ich euch von Himmlischem sagen würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'Und niemand ist in den Himmel aufgestiegen, außer Der, so aus dem Himmel herabgestiegen ist, des Menschen Sohn, Der in dem Himmel ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'Und wie Moses in der Wüste die Schlange erhöhte, also muß des Menschen Sohn erhöht werden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'Auf daß jeder, der an Ihn glaubt, nicht verloren werde, sondern das ewige Leben habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Denn also hat Gott die Welt geliebt, daß Er Seinen eingeborenen Sohn gab, auf daß jeder, der an Ihn glaubt, nicht verloren werde, sondern das ewige Leben habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Denn Gott hat Seinen Sohn nicht in die Welt gesandt, daß Er die Welt richte, sondern daß die Welt durch Ihn gerettet werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Wer an Ihn glaubt, wird nicht gerichtet; wer aber nicht glaubt, ist schon gerichtet, weil er nicht geglaubt hat an den Namen des eingeborenen Sohnes Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Das ist aber das Gericht, daß das Licht in die Welt gekommen ist und die Menschen die Finsternis mehr liebten, denn das Licht; denn ihre Werke waren schlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Denn jeder, der Arges tut, haßt das Licht und kommt nicht zum Licht, auf daß seine Werke nicht gerügt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'Wer aber die Wahrheit tut, der kommt zum Licht, damit seine Werke offenbar werden, weil sie in Gott gewirkt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Danach kam Jesus und Seine Jünger in das jüdische Land und verweilte daselbst mit ihnen und taufte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Johannes aber taufte auch zu Enon, nahe bei Salim, weil viel Wasser daselbst war; und sie traten herzu und ließen sich taufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Denn Johannes war noch nicht ins Gefängnis geworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Es ward nun eine Streitfrage von den Jüngern des Johannes mit den Juden über Reinigung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'Und sie kamen zu Johannes und sagten zu ihm: Rabbi, Der mit dir jenseits des Jordan war, für Den du zeugtest, siehe, Der tauft und alle kommen zu Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Johannes antwortete und sprach: Der Mensch kann nichts nehmen, es werde ihm denn aus dem Himmel gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Ihr selbst seid mir Zeugen, daß ich gesagt habe: Ich bin nicht Christus, sondern vor Ihm hergesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Wer die Braut hat, ist Bräutigam; der Freund des Bräutigams aber, der dasteht und ihn hört, freut sich mit Freude ob der Stimme des Bräutigams. Diese meine Freude ist nun erfüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'Er muß wachsen, ich aber muß abnehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Der von oben kommt, ist über alle. Wer von der Erde ist, der ist aus der Erde und redet aus der Erde. Der aus dem Himmel kommt, ist über alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'Und was Er gesehen und gehört hat, davon zeugt Er; und Sein Zeugnis nimmt niemand an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Wer Sein Zeugnis annimmt, der hat besiegelt, daß Gott wahrhaftig ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Denn Der, Den Gott gesandt hat, redet die Reden Gottes; denn Gott gibt Ihm den Geist nicht nach Maß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Der Vater liebt den Sohn und hat alles in Seine Hand gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Wer an den Sohn glaubt, hat ewiges Leben; wer aber nicht an den Sohn glaubt, der wird das Leben nicht sehen; sondern der Zorn Gottes bleibt auf ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Da nun der Herr erkannte, daß die Pharisäer gehört hatten, daß Jesus mehr Jünger mache und taufe, denn Johannes -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, 'Obwohl Jesus Selber nicht taufte, sondern Seine Jünger -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'Verließ Er Judäa und ging wieder hin nach Galiläa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Er mußte aber durch Samarien durchziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Er kam nun in eine Stadt von Samarien, genannt Sychar, nahe bei dem Grundstück, das Jakob seinem Sohne Joseph gegeben hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Es war aber daselbst Jakobs Quelle. Jesus nun, also müde von der Reise, setzte Sich an die Quelle. Es war um die sechste Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Da kommt ein Weib aus Samaria, Wasser zu schöpfen. Jesus spricht zu ihr: Gib Mir zu trinken;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Denn Seine Jünger waren in die Stadt weggegangen, um Nahrung zu kaufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Spricht nun das samaritische Weib zu Ihm: Wie bittest Du, Der Du ein Jude bist, von mir, die ich ein samaritisch Weib bin, zu trinken? Denn die Juden haben keinen Verkehr mit den Samaritern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jesus antwortete und sprach zu ihr: Wenn du wüßtest die Gabe Gottes, und wer Der ist, Der zu dir sagt: Gib Mir zu trinken - du hättest Ihn gebeten, und Er hätte dir lebendiges Wasser gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Sagt das Weib zu Ihm: Herr, Du hast nichts zum Schöpfen, und der Brunnen ist tief. Woher hast Du dann das lebendige Wasser?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Bist du größer denn unser Vater Jakob, der uns den Brunnen gab, und selbst daraus trank, er und seine Söhne und sein Vieh?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jesus antwortete und sprach zu ihr: Jeden, der von diesem Wasser trinkt, wird wieder dürsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'Wer aber von dem Wasser trinkt, das Ich ihm geben werde, den wird nicht dürsten in Ewigkeit; sondern das Wasser, das Ich ihm geben werde, wird in ihm eine Quelle Wassers werden, das ins ewige Leben quillt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Spricht zu Ihm das Weib: Herr, gib mir dieses Wasser, auf daß mich nicht dürste, und ich nicht hierher kommen müsse zu schöpfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Spricht zu ihr Jesus: Gehe hin, rufe deinen Mann und komme her!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Das Weib antwortete und sprach: Ich habe keinen Mann. Spricht Jesus zu ihr: Du hast gut gesagt: Ich habe keinen Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Denn fünf Männer hast du gehabt; und der, den du jetzt hast, ist nicht dein Mann. Das hast du wahr gesagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Spricht das Weib zu Ihm: Herr, ich schaue, daß Du ein Prophet bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Unsere Väter haben auf diesem Berge angebetet; und ihr sagt, Jerusalem sei der Ort, da man anbeten müsse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Spricht Jesus zu ihr: Weib, glaube Mir, es kommt eine Stunde, da ihr weder auf diesem Berge, noch in Jerusalem den Vater anbeten werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Ihr betet an, was ihr nicht wisset, wir beten an, was wir wissen; denn das Heil ist aus den Juden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Aber es kommt die Stunde und ist jetzt, daß die wahren Anbeter den Vater im Geist und in der Wahrheit anbeten werden; denn auch der Vater sucht solche, die Ihn also anbeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Gott ist ein Geist; und die Ihn anbeten, müssen Ihn im Geist und in der Wahrheit anbeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Spricht zu Ihm das Weib: Ich weiß, daß der Messias kommt, Den man Christus nennt. Wenn Selbiger kommt, wird Er uns alles ansagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Jesus spricht zu ihr: Ich bin es, Der mit dir redet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'Und über dem kamen Seine Jünger und waren verwundert, daß Er mit einem Weibe redete. Keiner jedoch sagte: Was suchst Du? ober: Warum redest Du mit ihr?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Das Weib ließ denn ihren Wasserkrug und kam hin in die Stadt und sagte zu den Menschen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Kommet, sehet einen Menschen, Der mir alles gesagt hat, was ich getan habe. Ob Dieser nicht der Christus ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'Und sie gingen hinaus aus der Stadt und kamen zu Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'In der Zwischenzeit aber baten Ihn die Jünger und sprachen: Rabbi, iß!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'Er aber sprach zu ihnen: Ich habe eine Speise zu essen, die ihr nicht wisset.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Da sprachen Seine Jünger untereinander: Hat ihm jemand zu essen gebracht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Jesus spricht zu ihnen: Meine Speise ist, daß Ich den Willen tue Dessen, Der Mich gesandt hat, und Sein Werk vollbringe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Saget ihr nicht, daß es noch vier Monate sind, bis die Ernte kommt? Siehe, Ich sage euch: Hebet eure Augen auf und sehet die Äcker an, wie sie schon weiß zur Ernte sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Und wer da erntet, empfängt Lohn und sammelt Frucht zum ewigen Leben, auf daß sich miteinander freuen, der da säet und der da erntet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Denn hierin ist das Wort wahr: Ein anderer ist es, der sät, und ein anderer, der erntet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Ich habe euch gesandt, zu ernten, womit ihr euch nicht abgemüht habt. Andere haben sich abgemüht, und ihr seid in ihre Arbeit eingetreten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Aus jener Stadt aber glaubten viele der Samariter an Ihn wegen des Wortes des Weibes, das da zeugte: Er hat mir alles gesagt, was ich getan habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Wie nun die Samariter zu Ihm kamen, baten sie Ihn, bei ihnen zu bleiben, und Er blieb zwei Tage daselbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'Und viel mehr glaubten um Seines Wortes willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'Und sagten zu dem Weibe: Wir glauben nicht mehr wegen deiner Rede; denn wir selbst haben gehört und wissen, daß Dieser wahrlich ist der Welt Heiland, Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Aber nach zwei Tagen zog Er aus von dannen und kam hin nach Galiläa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Denn Jesus Selbst zeugte, daß ein Prophet in seiner eigenen Vaterstadt keine Ehre hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Als Er nun nach Galiläa kam, nahmen Ihn die Galiläer auf, da sie alles gesehen hatten, was Er zu Jerusalem an dem Feste getan hatte; denn auch sie waren zum Feste gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'Er kam nun wieder nach Kana in Galiläa, wo Er das Wasser zu Wein gemacht hatte; und es war daselbst ein Königlicher, dessen Sohn krank war in Kapernaum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Als dieser hörte, daß Jesus aus Judäa nach Galiläa gekommen sei, ging er hin zu Ihm und bat Ihn, Er möchte hinabkommen und seinen Sohn gesund machen; denn er war am Sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Da sprach Jesus zu ihm: Wenn ihr nicht Zeichen und Wunder seht, glaubt ihr nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Spricht zu Ihm der Königliche: Herr, komme hinab, ehe denn mein Knäblein stirbt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Spricht Jesus zu ihm: Ziehe hin, dein Sohn lebt. Und der Mensch glaubte dem Worte, das Jesus zu ihm sprach, und zog hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Und wie er schon hinabging, kamen ihm seine Knechte entgegen und sagten ihm an und sprachen: Dein Knabe lebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Er erfragte nun von ihnen die Stunde, da es besser mit ihm wurde. Und sie sagten zu ihm: Gestern zur siebenten Stunde verließ ihn das Fieber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Da erkannte der Vater, daß es um dieselbe Stunde war, da Jesus zu ihm sprach: Dein Sohn lebt! und er glaubte und sein ganzes Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'Dies ist wiederum das zweite Zeichen, das Jesus tat, da Er aus Judäa nach Galiläa kam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Danach war ein Fest der Juden, und Jesus zog hinauf nach Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'Es ist aber in Jerusalem beim Schaftor ein Teich, auf Hebräisch mit Zunamen Bethesda, der fünf Hallen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'In diesen lag danieder eine große Menge Kranker, Blinder, Lahme, Abgezehrter; die warteten auf die Bewegung des Wassers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Denn zur bestimmten Zeit stieg ein Engel hinab in den Teich und bewegte das Wasser. Der erste nun, der nach der Bewegung des Wassers hineinstieg, ward gesund, mit welcherlei Krankheit er auch behaftet war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Es war aber ein Mensch daselbst, der achtunddreißig Jahre ein Gebrechen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Da Jesus diesen daniederliegen sah, und erkannte, daß er schon viele Zeit so war, spricht Er zu ihm: Willst du gesund werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Der Kranke antwortete Ihm: Herr, ich habe keinen Menschen, der mich, wenn das Wasser bewegt wird, in den Teich brächte, und bis ich komme, steigt ein anderer vor mir hinab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Jesus spricht zu ihm: Stehe auf, nimm dein Bett auf und wandle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'Und alsbald ward der Mensch gesund, und hob sein Bett auf und wandelte. Es war aber Sabbath an selbigen Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Da sagten die Juden zu dem Geheilten: Es ist Sabbath, es ist dir nicht erlaubt, das Bett zu tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'Er antwortete ihnen: Der mich gesund machte, Selbiger sprach zu mir: Nimm dein Bett und wandle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Da fragten sie ihn: Wer ist der Mensch, der zu dir sagte: Nimm dein Bett auf und wandle?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Der gesund Gewordene aber wußte nicht, wer es wäre; denn Jesus hatte Sich wegbegeben, weil ein Gedränge an dem Ort war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Danach fand ihn Jesus in dem Heiligtum und sprach zu ihm: Siehe, du bist gesund geworden! Sündige nicht mehr, damit dir nichts Schlimmeres geschehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Der Mensch ging hin und sagte den Juden an, daß Jesus es wäre, Der ihn gesund gemacht habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'Und darum verfolgten die Juden Jesus und suchten Ihn zu töten, daß Er dies am Sabbath getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Jesus aber antwortete ihnen: Mein Vater wirkt bis jetzt, und Ich wirke auch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Darum nun trachteten die Juden noch mehr, Ihn zu töten, daß Er nicht allein den Sabbath brach, sondern auch Gott Seinen eigenen Vater nannte und Sich Gott gleich machte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Da antwortete Jesus und sprach zu ihnen: Wahrlich, wahrlich, Ich sage euch: Der Sohn kann nichts von Ihm Selber tun, als was Er sieht den Vater tun; denn was Derselbige tut, das tut desgleichen auch der Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Denn der Vater hat den Sohn lieb und zeigt Ihm alles, was Er tut, und wird Ihm größere Werke denn diese zeigen, daß ihr euch verwundern werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Denn wie der Vater die Toten auferweckt und sie lebendig macht, also macht auch der Sohn lebendig, wen Er will;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Denn der Vater richtet niemand, sondern hat alles Gericht dem Sohne gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'Auf daß alle den Sohn ehren, wie sie den Vater ehren. Wer den Sohn nicht ehrt, der ehrt den Vater nicht, Der Ihn gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Wahrlich, wahrlich, Ich sage euch: Wer Mein Wort hört und glaubt an Den, Der Mich gesandt hat, der hat ewiges Leben und kommt nicht ins Gericht, sondern ist vom Tode zum Leben übergegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Wahrlich, wahrlich, Ich sage euch: Es kommt die Stunde und ist jetzt, daß die Toten die Stimme des Sohnes Gottes hören, und die, so sie hören werden, leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Denn wie der Vater Leben hat in Sich Selbst, so hat Er auch dem Sohne gegeben, Leben in Ihm Selbst zu haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'Und hat Ihm Gewalt gegeben, auch Gericht zu halten, weil Er des Menschen Sohn ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Verwundert euch dessen nicht; denn es kommt die Stunde, in der alle, so in den Gräbern sind, Seine Stimme hören werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'Und werden hervorgehen, die da Gutes getan haben, in die Auferstehung des Lebens, die aber Arges getan haben, in die Auferstehung des Gerichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Ich kann nichts von Mir Selber tun; wie Ich höre, so richte Ich, und Mein Gericht ist gerecht; weil Ich nicht suche Meinen Willen, sondern den Willen Dessen, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Wenn Ich von Mir Selber zeuge, so ist Mein Zeugnis nicht wahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Ein Anderer ist es, Der von Mir zeugt, und Ich weiß, daß das Zeugnis, das Er von Mir zeugt, wahr ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Ihr habt an Johannes gesandt, und er hat für die Wahrheit gezeugt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Ich aber nehme kein Zeugnis von einem Menschen, sondern spreche solches, auf daß ihr gerettet werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'Selbiger war die brennende und scheinende Leuchte, ihr aber wolltet zur Stunde in seinem Lichte frohlocken!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Ich aber habe ein größeres Zeugnis, denn das des Johannes; denn die Werke, die Mir der Vater zu vollbringen gegeben hat, dieselben Werke, die Ich tue, zeugen von Mir, daß der Vater Mich entsendet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'Und der Vater Selbst, Der Mich gesandt hat, hat von Mir gezeugt; ihr habt nie weder Seine Stimme gehört, noch Seine Gestalt gesehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'Und Sein Wort habt ihr nicht in euch bleibend, weil ihr an Ihn, Den Er entsandt hat, nicht glaubt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Forschet in den Schriften, denn ihr meint in ihnen das ewige Leben zu haben; und dieselbigen sind es, die von Mir zeugen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'Und ihr wollet nicht zu Mir kommen, auf daß ihr Leben habet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Ich nehme nicht Ehre von Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Euch aber erkenne Ich, daß ihr die Liebe Gottes nicht in euch habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Ich bin in Namen Meines Vaters gekommen, und ihr nehmt Mich nicht an. So ein anderer in seinem eigenen Namen kommt, den werdet ihr annehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Wie könnt ihr glauben, die ihre Ehre voneinander annehmt, und die Ehre von dem alleinigen Gott nicht sucht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ihr sollt nicht meinen, daß Ich euch bei dem Vater anklagen werde; es ist einer, der euch anklagt, Moses, auf den ihr gehofft habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Denn wenn ihr Moses glaubtet, so glaubtet ihr wohl Mir; denn von Mir hat derselbige geschrieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Wenn ihr aber seinen Schriften nicht glaubt, wie werdet ihr Meinen Reden glauben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Nach diesem fuhr Jesus hin über das galiläische Meer bei Tiberias.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'Und es folgte Ihm viel Gedränge nach, weil sie Seine Zeichen sahen, die Er an den Siechen tat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Jesus aber ging hinauf auf den Berg und setzte Sich daselbst mit Seinen Jüngern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Es war aber nahe dem Pascha, dem Fest der Juden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Da hob Jesus Seine Augen auf, und wie Er sah, daß viel Gedränge zu Ihm kam, sprach Er zu Philippus: Woher kaufen wir Brote, daß diese essen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'Das sagte Er aber, ihn zu versuchen; denn Er wußte, was Er tun werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Philippus antwortete Ihm: Für zweihundert Denare Brote genügt nicht für sie, daß jeder auch nur ein wenig nähme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Spricht zu Ihm einer Seiner Jünger, Andreas, der Bruder des Simon Petrus:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Es ist ein Knäblein hier, das hat fünf Gerstenbrote und zwei Fischlein; aber was ist das unter so viele?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Jesus aber sprach: Lasset die Menschen sich niederlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Jesus aber nahm die Brote, und dankte und gab sie den Jüngern hin, die Jünger aber an die, so sich niedergelassen hatten; desgleichen auch von den Fischlein, so viel sie wollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Als sie aber gesättigt waren, sprach Er zu Seinen Jüngern: Sammelt die überbleibenden Brocken, damit nichts verderbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Sie sammelten nun und machten zwölf Körbe voll mit Brocken, die den Gespeisten von den fünf Gerstenbroten übriggeblieben waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Da nun die Menschen das Zeichen sahen, das Jesus tat, sprachen sie: Das ist in Wahrheit der Prophet, der in die Welt kommen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Als aber Jesus erkannte, daß sie kommen und Ihn erhaschen wollten, um Ihn zum König zu machen, entwich Er abermals auf den Berg, Er alleine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Wie es aber Abend wurde, stiegen Seine Jünger hinab ans Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'Und stiegen ein in das Schifflein und kamen über das Meer gen Kapernaum. Und es war schon finster geworden und Jesus war nicht zu ihnen gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'Und das Meer ward von einem großen Wind, der wehte, aufgeregt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Als sie nun fünfundzwanzig oder dreißig Stadien gerudert hatten, schauen sie Jesus auf dem Meere wandeln und nahe an das Schiff kommen, und sie fürchteten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'Er sprach aber zu ihnen: Ich bin es, fürchtet euch nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Sie wollten Ihn nun ins Schiff nehmen; aber alsbald war das Schiff an dem Lande, dahin sie fuhren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Am folgenden Tage sah nun das Volk, das diesseits des Meeres stand, daß kein anderes Schifflein daselbst war, außer dem einen, in das Seine Jünger eingestiegen waren, und daß Jesus nicht mit Seinen Jüngern in das Schiff eingestiegen war, sondern Seine Jünger allein weggegangen waren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, 'Es kamen aber andere Schifflein aus Tiberias nahe an den Ort, wo sie unter der Danksagung des Herrn das Brot gegessen hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'Da das Volk nun sah, daß Jesus nicht da war, noch Seine Jünger, stiegen auch sie ein in die Schiffe und kamen nach Kapernaum und suchten Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'Und da sie Ihn jenseits des Meeres fanden, sagten sie zu Ihm: Rabbi, wann bist Du hergekommen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Jesus antwortete ihnen und sprach: Wahrlich, wahrlich, Ich sage euch: Ihr suchet Mich, nicht weil ihr Zeichen saht, sondern weil ihr von den Broten aßet und seid satt geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Wirket nicht die Speise, die verdirbt, sondern die Speise, die bleibt ins ewige Leben, die des Menschen Sohn euch geben wird; denn Diesen hat Gott, der Vater, besiegelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Da sagten sie zu Ihm: Was sollen wir tun, daß wir die Werke Gottes wirken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jesus antwortete und sprach zu ihnen: Dies ist das Werk Gottes, daß ihr glaubt an Ihn, Den Selbiger gesendet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Da sprachen sie zu Ihm: Was tust Du nun für Zeichen, auf daß wir es sehen und Dir glauben? Was wirkst Du?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Unsere Väter aßen das Manna in der Wüste, wie geschrieben ist: Er gab ihnen Brot aus dem Himmel zu essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Da sprach Jesus zu ihnen: Wahrlich, wahrlich, Ich sage euch: Moses hat euch nicht das Brot aus dem Himmel gegeben; sondern Mein Vater gibt euch das wahre Brot aus dem Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Denn das Brot Gottes ist Er, Der aus dem Himmel herabsteigt und der Welt Leben gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Da sagten sie zu Ihm: Herr, gib uns allezeit solches Brot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jesus aber spricht zu ihnen: Ich bin das Brot des Lebens. Wer zu Mir kommt, den wird nicht hungern, und wer an Mich glaubt, den wird nimmermehr dürsten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Aber Ich habe es euch gesagt: Ihr habt Mich gesehen, und ihr glaubt nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Alles, was Mir der Vater gibt, kommt zu Mir, und den, der zu Mir kommt, werde Ich nicht hinausstoßen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Denn Ich bin vom Himmel herabgekommen, nicht daß Ich Meinen Willen tue, sondern den Willen Dessen, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'Das aber ist der Wille des Vaters, Der Mich gesandt hat, daß Ich nichts verliere von allem, das Er Mir gegeben hat, sondern daß Ich es am letzten Tage auferstehen lasse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Dies aber ist der Wille Dessen, Der Mich gesandt hat, daß ein jeder, der den Sohn schaut und an Ihn glaubt, ewiges Leben habe, und Ich ihn auferstehen lasse am letzten Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Da murrten die Juden über Ihn, weil Er sagte: Ich bin das Brot, das aus dem Himmel herabgekommen ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'Und sagten: Ist dieser nicht Jesus, der Sohn Josephs, dessen Vater und Mutter wir kennen? Wie sagt dieser nun: Ich bin vom Himmel herabgekommen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jesus antwortete nun und sprach zu ihnen: Murret nicht untereinander.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Es kann niemand zu Mir kommen, es sei denn, daß der Vater, Der Mich gesandt hat, ihn ziehe. Und Ich lasse ihn auferstehen am letzten Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Es ist in den Propheten geschrieben: Und sie werden alle von Gott gelehrt sein. Jeder, der vom Vater gehört und gelernt hat, kommt zu Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Nicht daß jemand den Vater gesehen hätte außer Ihm, Der von Gott ist; Dieser hat den Vater gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Wahrlich, wahrlich, Ich sage euch: Wer an Mich glaubt, der hat ewiges Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Ich bin das Brot des Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Eure Väter haben das Manna in der Wüste gegessen und sind gestorben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Das ist das Brot, das aus dem Himmel herabkommt, daß einer davon esse und nicht sterbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Ich bin das lebendige Brot, das aus dem Himmel herabgekommen. Wenn einer von diesem Brot isset, so wird er in Ewigkeit leben; das Brot aber, das Ich ihm geben werde, ist Mein Fleisch, das Ich für das Leben der Welt geben werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Da stritten die Juden denn untereinander und sagten: Wie kann Dieser uns das Fleisch zu essen geben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jesus sprach nun zu ihnen: Wahrlich, wahrlich, Ich sage euch: Wenn ihr nicht esset das Fleisch des Menschensohnes und trinket Sein Blut, so habt ihr kein Leben in euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Wer Mein Fleisch isset und trinket Mein Blut, hat ewiges Leben, und Ich lasse ihn am letzten Tage auferstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Denn Mein Fleisch ist wahrhaftig eine Speise und Mein Blut ist wahrhaftig ein Trank.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Wer Mein Fleisch isset und trinket Mein Blut, der bleibt in Mir und Ich in ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Wie Mich der lebendige Vater entsendet hat, und Ich durch den Vater lebe, so wird auch, wer Mich isset, leben durch Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Dies ist das Brot, das aus dem Himmel herabgekommen ist, nicht wie eure Väter das Manna aßen und starben. Wer dieses Brot isset, wird leben in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'Dies sagte Er in einer Synagoge, da Er in Kapernaum lehrte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Viele nun von Seinen Jüngern, die das hörten, sagten: Dies ist ein hartes Wort, wer kann es hören?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Da aber Jesus in Sich wußte, daß Seine Jünger darüber murrten, sprach Er zu ihnen: Ärgert euch das?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Wenn ihr nun schauen werdet, des Menschen Sohn dahin aufsteigen, wo Er zuvor gewesen ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Der Geist ist es, der lebendig macht, das Fleisch nützet nichts. Die Reden, die Ich zu euch rede, sind Geist und sind Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Es sind aber etliche von euch, die nicht glauben; denn Jesus wußte von Anfang an, welche nicht glaubten, und wer Ihn verraten werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'Und Er sprach: Darum habe Ich euch gesagt, daß niemand kann zu Mir kommen, es sei ihm denn von Meinem Vater gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Von dem an gingen viele Seiner Jünger weg hinter sich und wandelten nicht mehr mit Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Da sprach Jesus zu den Zwölfen: Wollt ihr nicht auch hingehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Da antwortete Ihm Simon Petrus: Herr, zu wem sollten wir hingehen? Du hast Reden des ewigen Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'Und wir haben geglaubt und erkannt, daß Du bist der Christus, der Sohn des lebendigen Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Jesus antwortete ihnen: Habe Ich nicht euch Zwölfe auserwählt, und einer aus euch ist ein Teufel?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'Er sprach aber von Judas, Simons Sohn, Iskariot. Denn dieser war daran, Ihn zu verraten, und war einer von den Zwölfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'Nach diesem wandelte Jesus in Galiläa, denn Er wollte nicht in Judäa wandeln; weil die Juden Ihn zu töten suchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Es war aber nahe das Fest der Juden, die Laubhütten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Da sagten zu Ihm Seine Brüder: Ziehe von dannen und gehe hin nach Judäa, auf daß auch Deine Jünger die Werke sehen, die Du tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Denn niemand tut etwas im Verborgenen und will selbst offenkundig sein. Wenn Du solches tust, so offenbare Dich Selbst der Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Denn auch Seine Brüder glaubten nicht an Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Spricht Jesus nun zu ihnen: Meine Zeit ist noch nicht da; eure Zeit aber ist allezeit bereit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Euch kann die Welt nicht hassen, Mich aber hasset sie, weil Ich zeuge von ihr, daß ihre Werke schlecht sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Geht ihr hinauf auf dieses Fest. Ich gehe noch nicht hinauf auf dieses Fest, weil Meine Zeit noch nicht erfüllt ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'Da Er aber dies zu ihnen gesagt hatte, blieb Er in Galiläa.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Als aber Seine Brüder hinaufgegangen waren, da ging auch Er hinauf auf das Fest, nicht öffentlich, sondern gleichsam im Verborgenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Die Juden nun suchten Ihn auf dem Feste und sagten: Wo ist Jener?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'Und es war viel Gemurmel über Ihn in dem Gedränge. Die einen sagten: Er ist gut. Andere aber sagten: Nein, sondern Er führt die Menge irre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Keiner jedoch redete frei heraus über Ihn aus Furcht vor den Juden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Als aber schon die Mitte des Festes war, ging Jesus hinauf in das Heiligtum und lehrte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'Und die Juden verwunderten sich und sagten: Wie weiß Der die Schriften, da Er sie nicht gelernt hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Jesus antwortete ihnen und sprach: Meine Lehre ist nicht Mein, sondern Dessen, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'So jemand will Seinen Willen tun, der wird erkennen von der Lehre, ob sie von Gott ist, oder ob Ich von Mir Selber rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Wer von sich selbst redet, der sucht seine eigene Ehre, wer aber die Ehre dessen sucht, der ihn gesandt hat, der ist wahrhaftig, und es ist keine Ungerechtigkeit in ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Hat nicht Moses euch das Gesetz gegeben? Und keiner von euch tut das Gesetz. Was sucht ihr Mich zu töten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Das Gedränge antwortete und sagte: Du hast einen Dämon. Wer sucht Dich zu töten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jesus antwortete und sprach zu ihnen: Ein einziges Werk habe Ich getan, und ihr verwundert euch alle darob.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Moses hat euch die Beschneidung gegeben, nicht daß sie von Moses ist, sondern von den Vätern, und ihr beschneidet einen Menschen am Sabbath.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'So nun ein Mensch Beschneidung empfängt am Sabbath, auf daß das Gesetz des Mose nicht gebrochen werde, was seid ihr erbittert über Mich, daß Ich einen ganzen Menschen habe am Sabbath gesund gemacht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Richtet nicht nach dem Ansehen, sondern richtet ein gerechtes Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Da sprachen nun etliche aus denen von Jerusalem: Ist das nicht Der, Den sie zu töten suchen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'Und siehe, Er redet frei heraus und sie sagen Ihm nichts. Haben die Obersten wahrhaftig erkannt, daß Dieser wahrhaftig der Messias ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Aber von Dem wissen wir, von wannen Er ist. Wenn aber der Christus kommt, erkennt niemand, von wannen Er ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Da rief Jesus, in dem Heiligtum lehrend, und sprach: Wohl kennt ihr Mich und wißt, von wannen Ich bin. Und von Mir Selbst bin Ich nicht gekommen, sondern es ist ein Wahrhaftiger, Der Mich gesandt hat, Den ihr nicht kennt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Ich aber kenne Ihn, weil Ich von Ihm bin, und Er Mich entsandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Da suchten sie Ihn zu greifen; und keiner legte Hand an Ihn, weil Seine Stunde noch nicht gekommen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Viele aber aus dem Gedränge glaubten an Ihn und sagten: Wenn Christus kommt, wird Er mehr Zeichen tun, als diese, so Dieser tat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Die Pharisäer hörten, daß das Gedränge solches über Ihn murmelte; und die Pharisäer und Hohenpriester entsandten Amtsdiener, daß sie Ihn griffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Jesus sprach nun zu ihnen: Noch eine kleine Zeit bin Ich bei euch und gehe dann hin zu Dem, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Ihr werdet Mich suchen und nicht finden, und wo Ich bin, da könnt ihr nicht hinkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Da sprachen die Juden zueinander: Wohin will Dieser ziehen, daß wir Ihn nicht finden sollten? Will Er unter die Zerstreuten bei den Griechen ziehen, und die Griechen lehren?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Was ist dieses Wort, daß Er sagt: Ihr werdet Mich suchen und nicht finden; und wo Ich bin, könnt ihr nicht hinkommen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'An dem letzten, dem großen Tage des Festes aber stand Jesus auf und rief und sprach: Wen da dürstet, der komme zu Mir und trinke!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Wer an Mich glaubt, aus dessen Leib werden, wie die Schrift sagt, Ströme lebendigen Wassers fließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'Dies sagte Er aber von dem Geiste, den empfangen würden die, so an Ihn glaubeten; denn der Heilige Geist war noch nicht, weil Jesus noch nicht verherrlicht war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Viele nun aus dem Gedränge, die das Wort hörten, sagten: Dies ist wahrhaftig der Prophet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Andere sagten: Dies ist der Christus! Andere aber sagten: Kommt denn der Christus aus Galiläa?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Sagt nicht die Schrift, daß Christus aus dem Samen Davids, und von dem Flecken Bethlehem, wo David war, kommen wird?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Da entstand ein Zwiespalt wegen Seiner unter dem Gedränge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'Es wollten Ihn aber ihrer einige greifen; aber keiner legte die Hände an Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'Da kamen die Amtsdiener zu den Hohenpriestern und Pharisäern, und diese sagten zu ihnen: Warum habt ihr Ihn nicht hergeführt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Die Amtsdiener antworteten: Es hat noch nie ein Menschen so geredet, wie dieser Mensch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Da antworteten ihnen die Pharisäer: Seid auch ihr irre geführt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Glaubt auch einer von den Obersten oder von den Pharisäern an Ihn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Aber das Gedränge da, welches das Gesetz nicht erkennt, ist verflucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Spricht zu ihnen Nikodemus, der des Nachts zu Ihm gekommen, und einer von ihnen war:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Richtet unser Gesetz den Menschen, ehe man ihn zuvor gehört und erkannt hat, was er tut?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Sie antworteten und sagten zu ihm: Bist du auch aus Galiläa? Forsche und siehe, daß kein Prophet aus Galiläa auferweckt worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'Und ein jeglicher ging hin in sein Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Jesus aber ging hin nach dem Ölberge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'In der Frühe aber kam Er wieder herzu in das Heiligtum, und alles Volk kam zu Ihm, und Er setzte Sich nieder und lehrte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Die Schriftgelehrten aber und die Pharisäer führten ein Weib zu Ihm, das im Ehebruch festgenommen worden, und stellen sie in die Mitte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'Und sprechen zu Ihm: Lehrer, dieses Weib ist auf der Tat selbst im Ehebruch festgenommen worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'Ihm Gesetz aber hat Moses uns geboten, solche zu steinigen. Was sagst Du nun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'Das sprachen sie aber, Ihn zu versuchen, auf daß sie Ihn anklagen könnten. Jesus aber bückte Sich nieder und schrieb mit dem Finger in die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Als sie aber anhielten, Ihn zu fragen, richtete Er Sich auf und sprach zu ihnen: Wer von euch ohne Sünde ist, der werfe zuerst den Stein auf sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'Und Er bückte Sich wieder nieder und schrieb in die Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Als sie aber das hörten und von ihrem Gewissen gerügt wurden, gingen sie einer nach den anderen hinaus, anfangend am Ältesten bis auf den Letzten. Und Jesus ward allein gelassen und das Weib in der Mitte stehend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Jesus aber richtete Sich auf, und da Er niemand sah außer dem Weibe, sagte Er zu ihr: Weib, wo sind sie, deine Verkläger? Hat dich niemand verdammt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Sie aber sagte: Niemand, Herr. Jesus aber sprach zu ihr: So verdamme Ich dich auch nicht. Gehe hin und sündige nicht mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Jesus redete nun abermals zu ihnen und sprach: Ich bin das Licht der Welt. Wer Mir nachfolgt, der wird nicht im Finstern wandeln, sondern das Licht des Lebens haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Da sagten die Pharisäer zu Ihm: Du zeugst von Dir Selbst. Dein Zeugnis ist nicht wahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jesus antwortete und sagte zu ihnen: Und wenn Ich auch von Mir Selbst zeuge, so ist Mein Zeugnis wahr; weil Ich weiß, von wannen Ich komme und wohin Ich gehe; ihr aber wisset nicht, von wannen Ich komme, und wohin Ich gehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Ihr richtet nach dem Fleisch; ich richte niemand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Und wenn Ich aber richte, so ist Mein Gericht wahr; denn Ich bin nicht allein, sondern Ich und der Vater, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Auch ist in eurem Gesetz geschrieben, daß zweier Menschen Zeugnis wahr ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Ich bin, Der Ich von Mir Selbst zeuge, und der Vater, Der Mich gesandt hat, zeugt von Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Da sagten sie zu Ihm: Wo ist Dein Vater? Jesus antwortete: Ihr kennt weder Mich noch Meinen Vater. Wenn ihr Mich kennetet, so kennetet ihr auch Meinen Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Diese Reden redete Er am Schatzkasten, da Er lehrte im Heiligtum, und niemand griff Ihn, weil Seine Stunde noch nicht gekommen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'Abermals sprach nun Jesus zu ihnen: Ich gehe hin und ihr werdet Mich suchen und in eurer Sünde sterben. Wo Ich hingehe, da könnt ihr nicht hinkommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Da sagten die Juden: Will Er Sich Selbst töten, daß Er sagt: Wo Ich hingehe, da könnt ihr nicht hinkommen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'Und Er sprach zu Ihnen: Ihr seid von unten her, Ich bin von oben. Ihr seid aus dieser Welt, Ich bin nicht aus dieser Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'So habe Ich euch gesagt: Ihr werdet in euren Sünden sterben; denn so ihr nicht glaubt, daß Ich bin, so werdet ihr in euren Sünden sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Da sagten sie zu Ihm: Wer bist Du denn? Und Jesus sprach zu ihnen: Was Ich euch auch von Anfang an gesagt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Ich habe viel von euch zu reden und zu richten; aber Der Mich gesandt hat, ist wahrhaftig; und was Ich von Ihm gehört habe, das spreche Ich zur Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Sie erkannten nicht, daß Er vom Vater zu ihnen redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Da sagte Jesus zu ihnen: Wenn ihr des Menschen Sohn erhöht habt, dann werdet ihr erkennen, daß Ich bin und nichts von Mir Selber tue, sondern wie Mich Mein Vater gelehrt hat, solches rede Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'Und Der Mich gesandt hat, ist mit Mir. Der Vater hat Mich nicht allein gelassen, weil Ich allezeit tue, was Ihm gefällig ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Als Er so zu ihnen redete, glaubten viele an Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Da sprach Jesus zu den Juden, die an Ihn glaubten: Wenn ihr in Meinem Worte bleibt, dann seid ihr wahrhaftig Meine Jünger,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'Und werdet die Wahrheit erkennen, und die Wahrheit wird euch frei machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Sie antworteten Ihm: Wir sind Abrahams Samen, und sind niemals jemandes Knechte gewesen. Wie sprichst Du: Ihr werdet frei werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jesus antwortete ihnen: Wahrlich, wahrlich, Ich sage euch: Wer die Sünde tut, der ist der Sünde Knecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Der Knecht aber bleibt nicht ewiglich im Hause; der Sohn bleibt ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Wenn euch nun der Sohn frei macht, so werdet ihr in der Tat frei sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Ich weiß, daß ihr Abrahams Samen seid. Aber ihr sucht Mich zu töten, weil Mein Wort in euch nicht haftet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Ich rede, was Ich bei Meinem Vater gesehen habe; auch ihr nun tut, was ihr bei eurem Vater gesehen habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Sie antworteten und sagten zu Ihm: Abraham ist unser Vater. Spricht zu ihnen Jesus: Wäret ihr Abrahams Kinder, tätet ihr wohl Abrahams Werke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Nun aber sucht ihr Mich zu töten, einen Menschen, der Ich die Wahrheit zu euch geredet, die Ich von Gott gehört habe. Solches hat Abraham nicht getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Ihr tut die Werke eures Vaters. Da sprachen sie zu Ihm: Wir sind nicht aus Buhlerei geboren. Wir haben einen Vater - Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Da sprach Jesus zu ihnen: Wäre Gott euer Vater, dann liebtet ihr Mich; denn aus Gott bin Ich ausgegangen und komme Ich; denn Ich bin nicht von Mir Selbst gekommen, sondern Er hat Mich entsandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Warum erkennt ihr Meine Rede nicht? Weil ihr Mein Wort nicht hören könnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Ihr seid aus dem Vater dem Teufel, und nach eures Vaters Begierden wollt ihr tun. Derselbige war von Anfang ein Menschenmörder, und ist nicht in der Wahrheit bestanden, weil keine Wahrheit in ihm ist. Wenn er Lüge redet, redet er aus dem Eigenen, weil er ein Lügner ist und der Vater derselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Mir aber, weil Ich die Wahrheit rede, glaubt ihr nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Wer von euch kann Mich einer Sünde überführen? Sage Ich aber die Wahrheit, warum glaubt ihr Mir nicht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Wer aus Gott ist, hört die Reden Gottes; darum hört ihr nicht, weil ihr nicht aus Gott seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Da antworteten die Juden und sagten zu Ihm: Haben wir nicht recht gesagt, daß Du ein Samariter bist und einen Dämon hast?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jesus antwortete: Ich habe keinen Dämon, sondern Ich ehre Meinen Vater, ihr aber verunehret Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Ich suche nicht Meine Ehre; es ist einer, der sie sucht und richtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Wahrlich, wahrlich, Ich sage euch: So einer Mein Wort hält, der wird den Tod nicht schauen ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Da sprachen die Juden zu Ihm: Nun haben wir erkannt, daß Du einen Dämon hast; Abraham ist gestorben und die Propheten, und Du sagst: Wenn einer Mein Wort hält, der wird den Tod nicht schmecken ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Bist Du größer, denn unser Vater Abraham, der gestorben ist? Und die Propheten sind gestorben. Wozu machst Du Dich Selbst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jesus antwortete: So Ich Mich Selbst verherrliche, so ist Meine Herrlichkeit nichts. Mein Vater ist es, Der Mich verherrlicht, von Dem ihr sagt, Er sei euer Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'Und ihr habt Ihn nicht erkannt; Ich aber kenne Ihn; und so Ich sagte, Ich kenne Ihn nicht, so wäre Ich ein Lügner, wie ihr; aber Ich kenne Ihn und halte Sein Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, euer Vater, frohlockte, daß er Meinen Tag sehen sollte, und er sah ihn und freute sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Da sagten zu Ihm die Juden: Du hast noch keine fünfzig Jahre und hast Abraham gesehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jesus spricht zu ihnen: Wahrlich, wahrlich, Ich sage euch: Ehe denn Abraham ward, bin Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Da hoben sie Steine auf, daß sie auf Ihn würfen. Jesus aber verbarg Sich und ging hinaus aus dem Heiligtum, indem Er mitten durch sie hinging; und ging so vorüber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'Und da Er vorüberging, sah Er einen Menschen, blind von Geburt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'Und Seine Jünger fragten Ihn und sagten: Rabbi, wer hat gesündigt, dieser da oder seine Eltern, daß er blind geboren ward?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jesus antwortete: Weder dieser hat gesündigt, noch seine Eltern, sondern daß die Werke Gottes an ihm geoffenbart würden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Ich muß wirken die Werke Dessen, Der Mich gesandt hat, während es Tag ist. Es kommt eine Nacht, da niemand wirken kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Solange Ich bin in der Welt, bin Ich das Licht der Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Da Er solches gesprochen hatte, spützte Er auf die Erde und machte aus dem Speichel einen Teig und strich den Teig auf die Augen des Blinden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'Und sprach zu ihm: Gehe hin, wasche dich im Teich Siloah - das ist verdolmetscht Entsandt. Da ging er weg und wusch sich und kam sehend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'Die Nachbarn nun und die, so ihn früher sahen, daß er ein Bettler war, sagten: Ist das nicht der, welcher dasaß und bettelte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Einige sagten: Er ist es. Andere aber: Er ist ihm ähnlich. Er aber sagte: Ich bin es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Da sagten sie zu ihm: Wie wurden dir die Augen aufgetan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'Derselbe antwortete und sagte: Ein Mensch, der Jesus genannt wird, machte einen Teig und bestrich mir damit die Augen und sprach zu mir: Gehe hin an den Teich Siloah und wasche dich. Ich aber ging hin, wusch mich und ward sehend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Da sagten sie zu ihm: Wo ist Der? Er sagt: Ich weiß es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Da führten sie ihn, der weiland blind war, zu den Pharisäern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Es war aber Sabbath, da Jesus den Teig machte und ihm die Augen auftat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Da fragten ihn auch die Pharisäer abermals, wie er sehend wurde. Er aber sagte ihnen: Einen Teig legte Er mir auf die Augen und ich wusch mich und sehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Etliche nun aus den Pharisäern sagten: Dieser Mensch ist nicht von Gott, weil Er den Sabbath nicht hält. Andere sagten: Wie kann ein sündhafter Mensch solche Zeichen tun? Und es war ein Zwiespalt unter ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Sie sprachen wiederum zu dem Blinden: Was sagst du von Ihm, daß Er dir die Augen auftat? Er aber sprach: Er ist ein Prophet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Nun glaubten die Juden nicht von ihm, daß er blind war und sehend wurde, bis daß sie riefen die Eltern dessen, der sehend geworden war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'Und sie fragten sie und sprachen: Ist dies euer Sohn, von dem ihr sagt, er sei blind geboren? Wie ist er denn jetzt sehend?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Seine Eltern antworteten ihnen und sprachen: Wir wissen, daß dieser unser Sohn ist, und daß er blind geboren ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'Wie er aber nun sehend ist, wissen wir nicht; oder wer ihm seine Augen aufgetan hat, wissen wir nicht. Er selbst hat das Alter, fragt ihn. Er wird für sich selber reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'Solches sagten seine Eltern, weil sie sich vor den Juden fürchteten; denn die Juden waren schon dahin übereingekommen, daß, so jemand Ihn als Christus bekennete, er solle aus der Synagoge gestoßen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Darum sagten seine Eltern: Er hat das Alter, fragt ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Da riefen sie zum andern Mal den Menschen, der blind gewesen, und sprachen zu ihm: Gib Gott die Ehre! Wir wissen, daß dieser Mensch ein Sünder ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'Derselbe antwortete nun und sprach: Ob Er ein Sünder ist, weiß ich nicht. Eins weiß ich, daß ich blind war, und nun sehend bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Sie sprachen aber zu ihm abermals: Was tat Er dir? Wie tat Er deine Augen auf?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Er antwortete ihnen: Ich habe es euch schon gesagt, und ihr habt nicht gehört. Warum wollt ihr es abermals hören? Wollt auch ihr Seine Jünger werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Da schimpften sie auf ihn und sagten: Du bist Sein Jünger; wir aber sind Moses Jünger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Wir wissen, daß mit Moses Gott geredet hat. Von Dem aber wissen wir nicht, von wannen Er ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Der Mensch antwortete und sprach zu ihnen: Das ist doch wunderbar, daß ihr nicht wisset, von wannen Er ist, und Er hat mir die Augen aufgetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Wir wissen aber, daß Gott die Sünder nicht hört; wenn aber einer gottesfürchtig ist und Seinen Willen tut, den hört Er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Von Anbeginn an ist nicht erhört, daß einer einem Blindgeborenen die Augen hat aufgetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Wäre Dieser nicht von Gott, so hätte Er nichts tun können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Sie aber antworteten und sagten zu ihm: Du bist ganz in Sünden geboren und lehrest uns? Und sie stießen ihn hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jesus hörte, daß sie ihn hinausgestoßen hatten, und Er fand ihn und sprach zu ihm: Glaubst du an den Sohn Gottes?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'Jener antwortete und sagte: Wer ist es, Herr, daß ich an Ihn glaube?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jesus aber sprach zu ihm: Du hast ihn gesehen, und Der mit dir redet, Der ist es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'Er aber sprach: Ich glaube, Herr! und betete Ihn an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'Und Jesus sprach: Ich bin zum Gericht in diese Welt gekommen, auf daß, die da nicht sehen, sehen, und die da sehen, blind werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'Und solches hörten etliche aus den Pharisäern, die bei Ihm waren, und sagten zu Ihm: Sind wir denn auch blind?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jesus sprach zu ihnen: Wenn ihr blind wäret, so hättet ihr keine Sünde; nun ihr aber saget: Wir sehen, so bleibt denn eure Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Wahrlich, wahrlich, Ich sage euch: Wer nicht durch die Tür in den Schafstall eingeht, sondern anderswo einsteigt, ist ein Dieb und ein Räuber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Wer aber durch die Tür eingeht, der ist der Hirte der Schafe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Dem tut der Türhüter auf, und die Schafe hören auf seine Stimme und er ruft seine eigenen Schafe mit Namen und führt sie aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Und wenn er die eigenen Schafe hinausgeführt hat, geht er vor ihnen her, und die Schafe folgen ihm nach, weil sie seine Stimme kennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'Einem Fremden aber werden sie nicht nachfolgen, sondern fliehen von ihm, weil sie des Fremden Stimme nicht kennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'Diese Gleichnisrede sprach Jesus zu ihnen, jene aber erkannten nicht, was es war, das Er zu ihnen redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Da sprach Jesus abermals zu ihnen: Wahrlich, wahrlich, Ich sage euch: Ich bin die Tür der Schafe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Alle, die vor Mir gekommen, sind Diebe und Räuber. Aber die Schafe hörten nicht auf sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Ich bin die Tür. So jemand durch Mich eingeht, der wird gerettet werden, und wird eingehen und ausgehen und Weide finden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Der Dieb kommt nicht, denn daß er stehle und schlachte und verderbe. Ich bin gekommen, auf daß sie Leben und Überfluß haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Ich bin der gute Hirte. Der gute Hirte läßt sein Leben für die Schafe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Der Mietling aber, und der nicht Hirte ist, dem die Schafe nicht eigen sind, schaut den Wolf kommen, und verläßt die Schafe und flieht, und der Wolf erhascht und zerstreut die Schafe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'Der Mietling aber flieht, weil er ein Mietling ist und sich nicht um die Schafe kümmert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Ich bin der gute Hirte und erkenne die Meinen, und werde erkannt von den Meinen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'Wie Mich Mein Vater erkennt, und Ich den Vater erkenne. Und Ich lasse Mein Leben für die Schafe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'Und andere Schafe habe Ich, die nicht aus diesem Stalle sind; auch sie muß Ich führen, und sie werden Meine Stimme hören, und wird eine Herde, ein Hirte werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Darum liebt Mich der Vater, daß Ich Mein Leben lasse, auf daß Ich es wieder nehme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Niemand nimmt es Mir weg; sondern Ich lasse es von Mir Selber. Ich habe Gewalt, es zu lassen, und habe Gewalt, es wiederum zu nehmen. Dies Gebot habe Ich von Meinem Vater empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Da ward wiederum ein Zwiespalt unter den Juden wegen dieser Worte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Viele von ihnen aber sagten: Er hat einen Dämon und ist unsinnig. Was hört ihr Ihn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Andere sagten: Das sind nicht Reden eines Besessenen. Kann ein Dämon den Blinden die Augen auftun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Es war aber Tempelweihe in Jerusalem und war Winter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'Und Jesus wandelte umher im Heiligtum in der Halle Salomohs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Da umringten Ihn die Juden und sagten zu Ihm: Wie lange hältst Du unsre Seelen auf? Bist Du der Christus, so sage es uns frei heraus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Jesus antwortete ihnen: Ich habe es euch gesagt, und ihr glaubt nicht. Die Werke, die Ich tue in Meines Vaters Namen, die zeugen von Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Aber ihr glaubt nicht; denn ihr seid nicht von Meinen Schafen, wie Ich euch gesagt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Meine Schafe hören Meine Stimme, und Ich erkenne sie, und sie folgen Mir nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'Und Ich gebe ihnen ewiges Leben, und sie werden in Ewigkeit nicht verloren werden, und niemand wird sie aus Meiner Hand reißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Mein Vater, Der sie Mir gegeben hat, ist größer, denn alle; und niemand kann sie Meinem Vater aus der Hand reißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Ich und der Vater sind eins.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Da trugen die Juden abermals Steine herbei, um Ihn zu steinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Jesus antwortete ihnen: Viele gute Werke habe Ich euch gezeigt von Meinem Vater. Ob welchem dieser Werke steinigt ihr Mich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Die Juden antworteten Ihm und sagten: Ob einem guten Werke steinigen wir Dich nicht, sondern der Lästerungen wegen, und daß Du, ein Mensch, Dich Selbst zum Gotte machst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jesus antwortete ihnen: Ist nicht in eurem Gesetz geschrieben: Ich habe gesagt: Ihr seid Götter?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'So Er die Götter nennt, zu denen das Wort Gottes geschah - und die Schrift kann nicht gebrochen werden -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'Wie sagt ihr zu Dem, Den der Vater geheiligt und in die Welt entsandt hat: Du lästerst, weil Ich sage: Ich bin Gottes Sohn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Wenn Ich nicht die Werke Meines Vaters tue, so glaubet Mir nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'Tue Ich sie aber, wenn ihr auch Mir nicht glaubt, so glaubt den Werken; auf daß ihr erkennt und glaubt, daß in Mir der Vater ist, und Ich in Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'Da suchten sie abermals Ihn zu greifen; und Er entging aus ihren Händen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'Und ging wiederum hin über den Jordan, an den Ort, wo Johannes zuerst taufte, und blieb allda,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'Und viele kamen zu Ihm und sagten: Johannes hat zwar kein Zeichen getan, aber alles, was Johannes von Diesem gesagt hat, ist wahr gewesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'Und viele allda glaubten an Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Es war aber einer krank, Lazarus von Bethanien, aus dem Flecken Marias und Marthas, ihrer Schwester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Maria war es aber, die den Herrn mit Salbe salbte und Seine Füße mit ihren Haaren abwischte. Derselbigen Bruder Lazarus war krank.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Da sandten die Schwestern an Ihn und ließen Ihm sagen: Herr, siehe, der, den Du lieb hast, ist krank.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Da Jesus aber es hörte, sprach Er: Diese Krankheit ist nicht zum Tode, sondern um der Herrlichkeit Gottes willen, auf daß der Sohn Gottes durch sie verherrlicht werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Jesus aber liebte Martha und ihre Schwester und Lazarus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Als Er nun hörte, daß er krank war, da blieb Er zwei Tage an dem Ort, da Er war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Danach nach diesem spricht Er zu den Jüngern: Lasset uns wiederum nach Judäa ziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Die Jünger sagen zu Ihm: Rabbi, eben erst suchten die Juden Dich zu steinigen; und Du gehst wieder dahin?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jesus antwortete: Sind nicht zwölf Stunden des Tages? Wenn einer am Tage wandelt, stößt er sich nicht, weil er das Licht dieser Welt sieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'Wandelt jemand aber in der Nacht, dann stößt er sich; denn das Licht ist nicht ihn ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'Solches sprach Er, und danach sagt Er zu ihnen: Lazarus, unser Freund, schlummert, aber Ich ziehe hin, um ihn aus dem Schlafe zu wecken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Sprechen nun Seine Jünger: Herr, wenn er schlummert, so wird er gerettet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Jesus aber hatte von seinem Tode gesprochen. Sie meinten aber, Er spreche von dem Schlummern des Schlafes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Da sagte ihnen nun Jesus frei heraus: Lazarus ist gestorben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'Und Ich freue Mich um euretwegen, daß Ich nicht dort gewesen bin, auf daß ihr glaubt; aber lasset uns zu ihm ziehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Da sprach Thomas, genannt Didymus, zu seinen Mitjüngern: Lasset auch uns ziehen, daß wir mit Ihm sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Als nun Jesus kam, fand Er, daß er schon vier Tage in der Gruft lag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Bethanien aber war nahe bei Jerusalem, bei fünfzehn Stadien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'Und viele von den Juden waren zu denen bei Martha und Maria gekommen, um sie zu vertrösten über ihrem Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Als nun Martha hörte, daß Jesus komme, ging sie Ihm entgegen; Maria aber saß im Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Martha sprach nun zu Jesus: Herr, wärest Du hier gewesen, mein Bruder wäre wohl nicht gestorben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'Aber auch nun weiß ich, daß, worum Du Gott bitten wirst, wird Dir Gott geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Spricht Jesus zu ihr: Dein Bruder wird auferstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Spricht Martha zu Ihm: Ich weiß, daß er auferstehen wird in der Auferstehung am letzten Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Jesus sprach zu ihr: Ich bin die Auferstehung und das Leben! Wer an Mich glaubt, wird leben, wenn er auch stürbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'Und wer da lebt und an Mich glaubt, der wird nicht sterben in Ewigkeit. Glaubst Du das?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Sie spricht zu Ihm: Ja, Herr, ich glaube, daß Du bist der Christus, der Sohn Gottes, Der in die Welt kommen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'Und als sie das gesagt hatte, ging sie hin und rief insgeheim ihrer Schwester Maria und sprach: Der Lehrer ist da und ruft dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Als diese es hörte, machte sie sich schnell auf und kam zu Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Jesus war aber noch nicht in den Flecken gekommen, sondern war an dem Orte, wo Ihm Martha entgegenkam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Da nun die Juden, die bei ihr im Hause waren und sie vertrösteten, sahen, daß Maria eilig aufstand und hinausging, folgten sie ihr nach und sprachen: Sie geht hin zur Gruft, um dort zu weinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Wie nun Maria dahin kam, wo Jesus war, und Ihn sah, fiel sie zu Seinen Füßen und sprach zu Ihm: Herr, wärest Du da gewesen, mein Bruder wäre wohl nicht gestorben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Wie Jesus nun sie weinen sah, und die Juden weinen, die mit ihr gekommen waren, ergrimmte Er im Geiste und Er Selbst erbebte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'Und sprach: Wo habt ihr ihn hingelegt? Sie sagen zu Ihm: Herr, komm und siehe es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Und Jesus gingen die Augen über.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Da sagten die Juden: Siehe, wie hat Er ihn so lieb gehabt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'Einige aber aus ihnen sagten: Konnte Er, Der dem Blinden die Augen aufgetan hat, nicht machen, daß auch dieser nicht stürbe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'Jesus ergrimmte nun wiederum in Sich und kam zu der Gruft. Es war aber eine Höhle und ein Stein lag darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jesus sprach: Hebt den Stein weg! Spricht zu Ihm die Schwester des Verstorbenen, Martha: Herr, er riecht schon; denn es ist der vierte Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Spricht Jesus zu ihr: Sagte Ich dir nicht, wenn du glaubtest, würdest du die Herrlichkeit Gottes sehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Sie hoben nun den Stein weg, da der Verstorbene lag. Jesus aber hob die Augen auf und sprach: Vater, Ich danke Dir, daß Du Mich gehört hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Ich wußte aber, daß Du Mich allezeit hörst; aber wegen des Gedränges, das umhersteht, habe Ich gesprochen, auf daß sie glauben, daß Du Mich entsandt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'Und als Er dies gesagt hatte, schrie Er laut mit großer Stimme: Lazarus, komm heraus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'Und der Verstorbene kam heraus, an Füßen und Händen mit Binden gebunden, und sein Gesicht war mit einem Schweißtuch umbunden. Spricht Jesus zu ihnen: Löset ihn und lasset ihn hingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Viele nun aus den Juden, die zu Martha gekommen und angesehen hatten, was Er tat, glaubten an Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'Etliche aber aus ihnen gingen hin zu den Pharisäern und sagten ihnen, was Jesus getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Da versammelten die Hohenpriester und die Pharisäer den Rat und sprachen: Was tun wir, dieweil dieser Mensch viele Zeichen tut?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Lassen wir Ihn also, dann werden alle an Ihn glauben, und die Römer kommen und nehmen uns beides, den Ort und die Völkerschaft weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'Einer aber aus ihnen, Kaiaphas, der selbigen Jahres Hoherpriester war, sprach zu ihnen: Ihr wißt nichts,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'Noch bedenkt ihr, daß es zuträglich für uns ist, ein Mensch sterbe für das Volk, und daß nicht die ganze Völkerschaft verderbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Dies sprach er aber nicht von ihm selbst; sondern weil er selbigen Jahres Hoherpriester war, weissagte er, daß Jesus für die Völkerschaft sterben würde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'Und nicht nur für die Völkerschaft allein, sondern daß Er auch die zerstreuten Kinder Gottes in eins zusammenführete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Von selbigen Tage nun ratschlagten sie, daß sie ihn töteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Jesus wandelte nun nicht mehr frei heraus unter den Juden, sondern ging von dannen weg in die Gegend nahe bei der Wüste in eine Stadt, genannt Ephraim, und verweilte allda mit Seinen Jüngern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Es war aber nahe das Pascha der Juden, und viele aus der Gegend gingen vor dem Pascha hinauf nach Jerusalem, um sich zu reinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Sie suchten nun Jesus und sprachen zueinander, wie sie in dem Heiligtum standen: Was dünket euch? Daß Er wohl nicht auf das Fest kommen wird?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Es hatten aber beide, die Hohenpriester und die Pharisäer ein Gebot geben, so jemand erfahre, wo Er wäre, sollte er es anzeigen, daß sie Ihn griffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Sechs Tage vor dem Pascha kam Jesus nun nach Bethanien, wo Lazarus war, der Verstorbene, den Er von den Toten auferweckt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'Daselbst machten sie Ihm nun ein Abendmahl, und Martha diente, Lazarus aber war deren einer, die mit Ihm zu Tische waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Da nahm Maria ein Pfund echter kostbarer Nardensalbe und salbte die Füße Jesu und trocknete Seine Füße mit ihren Haaren; das Haus aber ward erfüllt von dem Geruch der Salbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Da sagte einer von Seinen Jüngern, Judas, Simons Sohn, Iskariot, der Ihn hernach verriet:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Warum hat man diese Salbe nicht verkauft um dreihundert Denare und den Armen gegeben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'Dies sagte er aber, nicht weil er sich um die Armen kümmerte, sondern weil er ein Dieb war und den Beutel hatte, und trug, was eingelegt ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Jesus sagte nun: Lasse sie! Sie hat es für den Tage Meines Begräbnisses behalten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Denn die Armen habt ihr allezeit bei euch, Mich aber habt ihr nicht allezeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Da erfuhr viel Volks der Juden, daß Er daselbst war, und sie kamen, nicht um Jesus willen allein, sondern auch, daß sie Lazarus sähen, den Er von den Toten auferweckt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Die Hohenpriester aber berieten sich, daß sie auch den Lazarus töteten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'Weil viele der Juden um Seinetwillen hingingen und an Jesus glaubten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Am folgenden Tage, da viel Volk, das zum Feste gekommen war, hörte, daß Jesus nach Jerusalem komme;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'Nahmen sie Zweige von Palmen und gingen hinaus Ihm entgegen und schrien: Hosianna! Gesegnet sei, der da kommt im Namen des Herrn! der König Israels!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'Jesus aber fand ein Eselein, und saß darauf, wie geschrieben ist:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, 'Fürchte dich nicht, Tochter Zion! Siehe, dein König kommt, sitzend auf einem Eselfüllen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Solches erkannten Seine Jünger zuerst nicht; als Jesus aber verherrlicht war, da dachten sie daran, daß solches über Ihn geschrieben war, und sie solches Ihm getan hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Das Gedränge nun, das mit Ihm war, zeugte, daß Er Lazarus aus der Gruft gerufen und ihn von den Toten auferweckt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Darum ging Ihm auch das Gedränge entgegen, da sie hörten, Er hätte solches Zeichen getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Die Pharisäer sprachen nun untereinander: Da schauet ihr, daß nichts nützet; siehe, die Welt geht Ihm nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Es waren aber etliche Griechen aus denen, die hinaufkamen, um am Feste anzubeten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Diese nun kamen zu Philippus von Bethsaida in Galiläa, und baten ihn und sprachen: Herr, wir wollten Jesus sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Philippus kommt und sagt es dem Andreas, und wiederum Andreas und Philippus sagen es Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Jesus aber antwortete ihnen und sagte: Die Stunde ist gekommen, daß des Menschen Sohn verherrlicht werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Wahrlich, wahrlich, Ich sage euch: Es sei denn, daß das Weizenkorn in die Erde fällt und stirbt, bleibt es allein; so es aber stirbt, so trägt es viele Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Wer sein Leben lieb hat, der verliert es; und wer sein Leben haßt in dieser Welt, der wird es bewahren zum ewigen Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Wer Mir dienen will, der folge Mir nach, und wo Ich bin, da soll Mein Diener auch sein; und wenn einer Mir dient, so wird ihn der Vater ehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Jetzt ist Meine Seele erschüttert. Und was soll Ich sagen? Vater, rette Mich aus dieser Stunde! Aber dafür bin Ich in diese Stunde gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Vater, verherrliche Deinen Namen! Da kam eine Stimme aus dem Himmel: Ich habe ihn verherrlicht und werde ihn abermals verherrlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Das Gedränge nun, das da stand und es hörte, sagte: Es ward ein Donner. Andere sagten: Ein Engel hat mit Ihm geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jesus antwortete und sprach: Nicht um Meinetwillen ist diese Stimme geschehen, sondern um euretwillen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Jetzt ist das Gericht dieser Welt. Jetzt wird der Fürst dieser Welt hinausgestoßen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'Und Ich, wenn Ich erhöht werde von der Erde, werde alle zu Mir ziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'Dies sagte Er aber, indem Er anzeigte, welches Todes Er sterben würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Da antwortete Ihm des Gedränge: Wir haben aus dem Gesetz gehört, daß Christus in Ewigkeit bleibt. Und wie sagst Du, daß des Menschen Sohn erhöht werden muß? Wer ist dieser Menschensohn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Jesus sprach nun zu ihnen: Noch eine kleine Zeit ist das Licht bei euch. Wandelt, solange ihr das Licht habt, daß euch die Finsternis nicht überfalle. Und wer in der Finsternis wandelt, der weiß nicht, wohin er geht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Solange ihr das Licht habt, glaubt an das Licht, auf daß ihr Söhne des Lichtes werdet. Solches redete Jesus, und ging weg und verbarg Sich vor ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'Obgleich Er aber so viel Zeichen vor ihnen getan, glaubten sie doch nicht an Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'Auf daß das Wort des Propheten Jesajas erfüllt werde, das er sagte: Herr, wer hat unserer Rede geglaubt? Und wem ist des Herrn Arm geoffenbart worden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Deshalb konnten sie nicht glauben, weil Jesajas abermals sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, 'Er hat geblendet ihre Augen, und ihr Herz verstockt, daß sie nicht sehen mit den Augen und mit dem Herzen begreifen und umkehren, und Ich sie gesund mache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'Solches sagte Jesajas, als er Seine Herrlichkeit sah und von Ihm redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Gleichwohl glaubten auch der Obersten viele an Ihn, bekannten es aber nicht, um der Pharisäer willen, auf daß sie nicht aus der Synagoge gestoßen würden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Denn sie liebten die Ehre der Menschen mehr, denn die Ehre Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Jesus aber schrie und sprach: Wer an Mich glaubt, glaubt nicht an Mich, sondern an Den, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'Und wer Mich schaut, der schaut Den, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Ich bin ein Licht in die Welt gekommen, auf daß alle, die an Mich glauben, nicht in der Finsternis bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'Und wenn einer Meine Reden hört, und nicht glaubt, richte Ich ihn nicht; denn Ich bin nicht gekommen, daß Ich die Welt richte, sondern daß Ich die Welt rette.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Wer Mich verwirft und Meine Reden nicht annimmt, der hat einen, der ihn richtet; das Wort, das Ich geredet habe, das wird ihn richten am letzten Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Denn Ich habe nicht von Mir Selber geredet, sondern der Vater, Der Mich gesandt, hat Selbst Mir ein Gebot gegeben, was Ich sagen und was Ich reden soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'Und Ich weiß, daß Sein Gebot ist ewiges Leben. Was Ich nun rede: wie Mir der Vater gesagt hat, so rede Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Vor dem Fest des Pascha aber, da Jesus wußte, daß Seine Stunde gekommen war, daß Er aus dieser Welt zum Vater übergehen sollte, da Er Seine Eigenen in der Welt geliebt hatte, liebte Er sie bis ans Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'Und als das Abendmahl gehalten wurde, und der Teufel dem Judas, Simons Sohn, Iskariot, schon ins Herz gegeben hatte, daß er Ihn verriete,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'Da Jesus wußte, daß Ihm der Vater alles in die Hände gegeben hatte, und daß Er von Gott ausgegangen war, und zu Gott hinging,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'Machte Er Sich auf vom Abendmahl und legte Seine Oberkleider ab, nahm ein leinenes Tuch und umgürtete Sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Dann goß Er Wasser in das Waschbecken und fing an, den Jüngern die Füße zu waschen, und mit dem leinenen Tuch, womit Er umgürtet war, zu trocknen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Da kam Er zu Simon Petrus; und selbiger spricht zu Ihm: Herr, Du solltest mir die Füße waschen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jesus antwortete und sprach zu ihm: Was Ich tue, weißt du jetzt nicht, wirst es aber hernach erfahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Spricht zu Ihm Petrus: In Ewigkeit sollst Du die Füße mir nicht waschen! Jesus antwortete ihm: Wenn Ich dich nicht wasche, so hast du keinen Teil an Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Spricht zu Ihm Simon Petrus: Herr, nicht meine Füße allein, sondern auch die Hände und das Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Jesus spricht zu ihm: Wer gebadet ist, der bedarf mehr nicht, denn die Füße zu waschen; sondern er ist ganz rein; und ihr seid rein, aber nicht alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Denn Er kannte Seinen Verräter. Darum sagte Er: Ihr seid nicht alle rein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Als Er nun ihr Füße gewaschen und Seine Oberkleider wieder genommen hatte, ließ Er Sich wiederum nieder und sprach zu ihnen: Erkennt ihr, was Ich euch getan habe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Ihr heißet Mich Lehrer und Herr, und ihr sagt recht; denn Ich bin es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'So nun Ich, der Herr und Lehrer, euch die Füße wusch, solltet auch ihr einander die Füße waschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Ein Beispiel habe Ich euch gegeben, daß, wie Ich euch getan habe, auch ihr tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Wahrlich, wahrlich, Ich sage euch: Der Knecht ist nicht größer, denn sein Herr, noch der Gesandte größer, denn der ihn gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'So ihr solches wisset, selig seid ihr, so ihr es tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Ich spreche nicht von euch allein. Ich weiß, welche Ich erwählt habe. Aber daß die Schrift erfüllt werde: Der Mein Brot ißt, hat seine Ferse wider Mich erhoben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Schon jetzt sage Ich es euch, ehe denn es geschieht, auf daß, wenn es geschehen ist, ihr glaubt, daß Ich bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Wahrlich, wahrlich, Ich sage euch: Wer den aufnimmt, den Ich senden werde, der nimmt Mich auf; wer aber Mich aufnimmt, der nimmt Den auf, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Als Jesus dies gesagt hatte, erbebte Er im Geist und zeugte und sprach: Wahrlich, wahrlich, Ich sage euch: Einer aus euch wird Mich verraten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Da sahen die Jünger einander an und waren im Zweifel, von wem Er spreche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Es lag aber einer aus Seinen Jüngern am Busen Jesu, den Jesus liebte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Dem winkte nun Simon Petrus, er sollte erfragen, wer wohl der wäre, von dem Er spräche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'Derselbige neigte sich nach der Brust Jesu und spricht zu Ihm: Herr, wer ist es?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jesus antwortet: Der ist es, dem Ich den Bissen eintauche und gebe. Und Er tauchte den Bissen ein und gab ihn dem Judas, Simons Sohn, Iskariot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'Und nach dem Bissen fuhr der Satan ein in ihn. Jesus sagt nun zu ihm: Was du tust, das tue schnell!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Keiner aber derer, die mit zu Tische waren, erkannte, wozu Er ihm dies sagte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Denn etliche meinten, da Judas den Beutel hatte, Jesus sage zu ihm: Kaufe, was wir aufs Fest bedürfen; oder, er sollte den Armen etwas geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Da jener aber den Bissen genommen hatte, ging er alsbald hinaus. Es war aber Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Als er nun hinausgegangen war, sprach Jesus: Jetzt ist des Menschen Sohn verherrlicht, und Gott ist verherrlicht in Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Ist Gott in Ihm verherrlicht, so wird Ihn auch Gott in Ihm Selbst verherrlichen, und wird Ihn alsbald verherrlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Kindlein, noch eine kleine Weile bin Ich bei euch. Ihr werdet Mich suchen, und, wie Ich zu den Juden sagte: Wo Ich hingehe, dahin könnt ihr nicht kommen, also sage Ich auch jetzt zu euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Ein neu Gebot gebe Ich euch, daß ihr euch untereinander liebt, wie Ich euch geliebt habe, auf daß auch ihr einander liebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'Daran werden alle erkennen, daß ihr Meine Jünger seid, so ihr Liebe untereinander habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Simon Petrus spricht zu Ihm: Herr, wo gehst Du hin? Jesus antwortet ihm: Wo Ich hingehe, dahin kannst du Mir jetzt nicht nachfolgen. Danach aber wirst du Mir nachfolgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Spricht zu Ihm Petrus: Herr, warum kann ich Dir jetzt nicht nachfolgen? Ich will mein Leben für Dich lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jesus antwortete ihm: Du willst dein Leben für Mich lassen? Wahrlich, wahrlich, Ich sage dir: Der Hahn wird nicht krähen, bis du Mich dreimal verleugnet hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Euer Herz erbebe nicht! Glaubt an Gott und glaubt an Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'In Meines Vaters Hause sind viele Wohnungen. Wäre dem nicht so, Ich hätte es euch gesagt. Ich gehe hin, euch eine Stätte zu bereiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'Und wenn Ich hingehe und euch eine Stätte bereite, komme Ich wieder und werde euch zu Mir mitnehmen, auf daß ihr seid, wo Ich bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'Und wo Ich hingehe, wisset ihr, und den Weg wisset ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Spricht zu Ihm Thomas: Herr, wir wissen nicht, wo Du hingehst; und wie können wir den Weg wissen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Spricht zu ihm Jesus: Ich bin der Weg und die Wahrheit und das Leben; niemand kommt zum Vater, denn durch Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Erkennetet ihr Mich, so erkennetet ihr auch wohl Meinen Vater; und von nun an erkennet ihr Ihn und habt Ihn gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Spricht zu Ihm Philippus: Herr, zeige uns den Vater, und es genügt uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Spricht zu ihm Jesus: So lange Zeit bin Ich bei euch, und du erkennst Mich nicht Philippus? Wer Mich gesehen hat, der hat den Vater gesehen. Und wie sagst du: Zeige uns den Vater?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Glaubst du nicht, daß Ich in dem Vater bin und der Vater in Mir ist? Die Reden, die Ich zu euch rede, rede Ich nicht von Mir; der Vater aber, Der in Mir bleibt, Der tut die Werke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Glaubt Mir, daß Ich im Vater bin und der Vater in Mir ist; wo nicht, so glaubt Mir um der Werke willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Wahrlich, wahrlich, Ich sage euch: Wer an Mich glaubt, wird auch die Werke tun, die Ich tue, und wird noch größere tun, denn diese; denn Ich gehe zu Meinem Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'Und um was immer ihr bitten werdet in Meinem Namen, das will Ich tun, auf daß der Vater in dem Sohn verherrlicht werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Wenn ihr um etwas bitten werdet in Meinem Namen, so will Ich es tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Wenn ihr Mich liebt, so haltet Meine Gebote.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'Und Ich werde den Vater bitten, und Er wird euch einen anderen Beistand geben, daß er bei euch bleibe ewiglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Den Geist der Wahrheit, den die Welt nicht empfangen kann, weil sie ihn nicht schaut und nicht erkennt. Ihr aber erkennt ihn, weil er bei euch bleibt, und in euch sein wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Ich will euch nicht Waisen lassen; Ich komme zu euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Noch um ein Kleines, und die Welt schaut Mich nicht mehr. Ihr aber schaut Mich; denn Ich lebe und ihr sollt leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'An selbigen Tage werdet ihr erkennen, daß Ich in Meinem Vater bin und ihr in Mir, und Ich in euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Wer Meine Gebote hat und sie hält, der ist es, der Mich liebt, und wer Mich liebt, der wird von Meinen Vater geliebt werden, und Ich werde ihn lieben und Mich ihm offenbaren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Spricht zu Ihm Judas: Herr, wie geschieht es, daß Du Dich uns willst offenbaren, und nicht der Welt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jesus antwortete und sprach zu ihm: Wenn jemand Mich liebt, wird er Mein Wort halten; und Mein Vater wird ihn lieben, und Wir werden zu ihm kommen und Wohnung bei ihm machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Wer Mich nicht liebt, hält Meine Worte nicht. Und das Wort, das ihr hört, ist nicht Mein, sondern des Vaters, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'Solches habe Ich zu euch geredet, weil Ich noch bei euch blieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Der Beistand aber, der Heilige Geist, den der Vater in Meinem Namen senden wird, der wird euch alles lehren, und euch an alles erinnern, was Ich euch gesagt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Friede lasse Ich euch, Meinen Frieden gebe Ich euch; nicht wie die Welt gibt, gebe Ich euch. Euer Herz erbebe nicht und zage nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Ihr habt gehört, daß Ich zu euch gesagt habe: Ich gehe hin und komme zu euch. Liebtet ihr Mich, so freuetet ihr euch wohl, daß Ich sagte: Ich gehe hin zum Vater; denn der Vater ist größer, denn Ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'Und Ich habe es euch jetzt gesagt, ehe denn es geschieht, auf daß ihr glaubt, wenn es geschieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Ich werde nicht mehr viel mit euch reden; denn es kommt der Fürst der Welt, und hat nichts an Mir;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'Damit aber die Welt erkenne, daß Ich den Vater liebe und also tue, wie Mir der Vater geboten hat. Machet euch auf, und lasset uns von hinnen gehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Ich bin der wahrhaftige Weinstock und Mein Vater ist der Weingärtner.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Eine jegliche Rebe an Mir, die nicht Frucht trägt, nimmt Er weg, und eine jegliche, die da Frucht trägt, reinigt Er, daß sie mehr Frucht trage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Ihr seid schon rein durch das Wort, das Ich zu euch geredet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Bleibt in Mir, und Ich in euch. Gleichwie die Rebe keine Frucht tragen kann von ihr selber, sie bleibe denn am Weinstock, so auch ihr nicht, ihr bleibt denn in Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Ich bin der Weinstock, ihr die Reben. Wer in Mir bleibt und Ich in ihm, der trägt viele Frucht; denn ohne Mich könnt ihr nichts tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Wer nicht in Mir bleibt, der wird hinausgeworfen wie die Rebe und verdorrt, und sie sammeln sie und werfen sie ins Feuer, und sie brennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Wenn ihr in Mir bleibt und Meine Reden in euch bleiben, so sollt ihr bitten, was ihr wollt, und es wird euch geschehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'Darin wird Mein Vater verherrlicht, daß ihr viele Frucht traget und Meine Jünger werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Wie Mich Mein Vater geliebt hat, so habe Ich euch auch geliebt. Bleibet in Meiner Liebe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Wenn ihr Meine Gebote haltet, so werdet ihr in Meiner Liebe bleiben, wie Ich die Gebote Meines Vaters gehalten habe und in Seiner Liebe bleibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'Solches habe Ich zu euch geredet, auf daß Meine Freude in euch bleibe und eure Freude erfüllt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Das ist Mein Gebot, daß ihr einander liebt, wie Ich euch geliebt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Größere Liebe hat niemand denn die, daß er sein Leben für seine Freunde läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Ihr seid Meine Freunde, wenn ihr tut, was Ich euch gebiete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Ich nenne euch hinfort nicht Knechte; denn der Knecht weiß nicht, was sein Herr tut, sondern habe euch Freunde genannt, weil Ich alles, was Ich von Meinem Vater gehört, euch kundgetan habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Ihr habt Mich nicht erwählt, sondern Ich habe euch erwählt, und euch eingesetzt, daß ihr hingehet und Frucht traget, und eure Frucht bleibe, auf daß, was immer ihr vom Vater in Meinem Namen bittet, Er es euch gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'Das gebiete Ich euch, daß ihr einander liebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'So euch die Welt haßt, so erkennet, daß sie Mich vor euch gehaßt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Wäret ihr aus der Welt, so hätte die Welt das Eigene lieb. Nun ihr aber nicht aus der Welt seid, sondern Ich euch auserwählt habe, aus der Welt, darum haßt euch die Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Gedenket an das Wort, das Ich zu euch sprach: Der Knecht ist nicht größer, denn sein Herr. Verfolgten sie Mich, so werden sie auch euch verfolgen. Hielten sie Mein Wort, so werden sie auch eures halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Aber solches alles werden sie euch tun um Meines Namens willen, weil sie Den nicht kennen, Der Mich gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Wäre Ich nicht gekommen und hätte zu ihnen geredet, so hätten sie keine Sünde; nun aber haben sie keinen Vorwand für ihre Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Wer Mich haßt, der haßt auch Meinen Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Hätte Ich die Werke nicht getan unter ihnen, die kein anderer tat, so hätten sie keine Sünde. Nun aber haben sie sie gesehen und hassen beide, Mich und Meinen Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Jedoch es sollte das Wort erfüllt werden, das in ihrem Gesetz geschrieben ist: Umsonst haßten sie Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Wenn aber der Beistand kommen wird, den Ich euch vom Vater senden werde - der Geist der Wahrheit, der vom Vater ausgehtder wird zeugen von Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'Und auch ihr werdet zeugen, weil ihr vom Anfang an bei Mir seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'Dies habe Ich zu euch geredet, auf daß ihr kein Ärgernis nehmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Sie werden euch aus der Synagoge stoßen. Ja, es kommt die Stunde, da jeder, der euch tötet, meint, er bringe Gott einen Dienst damit dar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'Und solches werden sie tun, weil sie weder den Vater noch Mich erkannt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Ich habe aber solches zu euch geredet, auf daß, wenn die Stunde kommt, ihr gedenket, daß ich es euch gesagt habe. Ich sagte euch solches von Anfang nicht, weil Ich bei euch war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'Jetzt aber gehe Ich hin zu Dem, Der Mich gesandt hat, und keiner von euch fragt Mich: Wo gehst Du hin?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Sondern weil Ich solches zu euch geredet habe, hat Betrübnis euer Herz erfüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Aber Ich sage euch die Wahrheit: Es ist zuträglich für euch, daß Ich hingehe; denn so Ich nicht weggehe, wird der Beistand nicht zu euch kommen; wenn Ich aber gehe, werde Ich ihn zu euch senden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'Und wenn er kommt, wird er die Welt überführen von der Sünde und von der Gerechtigkeit, und vom Gericht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'Von der Sünde, daß sie nicht glauben an Mich;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'Von der Gerechtigkeit, daß Ich zu Meinem Vater hingehe, und ihr Mich nicht mehr schauet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'Von dem Gericht, daß der Fürst dieser Welt gerichtet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Ich habe euch noch vieles zu sagen, aber ihr könnt es jetzt nicht tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Wenn aber jener, der Geist der Wahrheit, kommen wird, so wird er euch in alle Wahrheit leiten; denn er wird nicht von sich selber reden, sondern was er hören wird, wird er reden, und was da kommen wird, wird er euch ansagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'Derselbe wird Mich verherrlichen; denn von dem Meinigen wird er nehmen und es euch ansagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Alles, was der Vater hat, ist Mein. Darum sagte Ich, daß er von dem Meinigen nehmen und es euch ansagen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Über ein Kleines, so schauet ihr Mich nicht, und wiederum über ein Kleines, so werdet ihr Mich sehen; denn Ich gehe hin zum Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Da sprachen etliche Seiner Jünger untereinander: Was ist das, daß Er zu uns sagt: über ein Kleines, so schauet ihr Mich nicht, und wiederum über ein Kleines, so werdet ihr Mich sehen? und: Ich gehe hin zum Vater?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Sie sagten nun: Was ist das, daß Er sagt: Über ein Kleines? Wir wissen nicht, was Er redet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jesus erkannte nun, daß sie Ihn fragen wollten, und sagte zu ihnen: Darüber forschet ihr miteinander, daß Ich sagte: Über ein Kleines schauet ihr Mich nicht, und abermals über ein Kleines, so werdet ihr Mich sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Wahrlich, wahrlich, Ich sage euch: Ihr werdet weinen und klagen, aber die Welt wird sich freuen. Ihr werdet euch betrüben, aber eure Betrübnis wird zur Freude werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Das Weib hat Betrübnis, wenn sie gebären soll; denn ihre Stunde ist gekommen; wenn sie aber das Knäblein geboren hat, gedenkt sie nicht mehr der Trübsal vor Freude, daß ein Mensch in die Welt geboren ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Auch ihr nun habt jetzt Betrübnis; aber Ich werde euch wiederum sehen, und euer Herz wird sich freuen, und niemand nimmt eure Freude weg von euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'Und an selbigem Tage werdet ihr Mich nichts fragen. Wahrlich, wahrlich, Ich sage euch: Was irgend ihr den Vater bitten werdet in Meinem Namen, wird Er euch geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Bisher habt ihr um nichts gebeten in Meinem Namen. Bittet, so werdet ihr empfangen, daß eure Freude erfüllt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'Solches habe Ich zu euch in Gleichnisreden geredet; aber es kommt die Stunde, da Ich nicht mehr in Gleichnisreden zu euch reden, sondern euch frei heraus von dem Vater ansagen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Am selben Tage sollt ihr in Meinem Namen bitten, und Ich sage euch nicht, daß Ich den Vater für euch bitten werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Denn der Vater Selbst hat euch lieb, weil ihr Mich lieb hattet, und geglaubt habt, daß Ich von Gott ausgegangen bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Ich bin vom Vater ausgegangen und in die Welt gekommen, wiederum verlasse Ich die Welt und gehe zum Vater hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Sagen Seine Jünger zu Ihm: Siehe, jetzt redest Du frei heraus und sprichst nicht mehr in Gleichnisreden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Jetzt wissen wir, daß Du alles weißt und nicht bedarfst, daß Dich jemand frage. Darum glauben wir, daß Du von Gott ausgegangen bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Jesus antwortete ihnen: Eben jetzt glaubet ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Siehe, es kommt die Stunde und ist jetzt gekommen, daß ihr zerstreut werdet, ein jeglicher in das Eigene, und ihr Mich allein lasset; und Ich bin nicht allein, denn der Vater ist mit Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'Solches habe Ich zu euch geredet, auf daß ihr in Mir Frieden habet. In der Welt habt ihr Trübsal; aber seid getrost, Ich habe die Welt überwunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'Solches redete Jesus und hob Seine Augen auf gen Himmel und sprach: Vater, die Stunde ist gekommen. Verherrliche Deinen Sohn, auf daß auch Dein Sohn Dich verherrliche;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'Wie Du Ihm Gewalt über alles Fleisch gegeben hast, auf daß Er ewiges Leben gebe allen, die Du Ihm gegeben hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Das ist aber das ewige Leben, daß sie Dich, den allein wahren Gott, und Den Du entsandt hast, Jesus Christus, erkennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Ich habe Dich auf Erden verherrlicht, Ich habe das Werk vollbracht, das Du Mir zu tun gegeben hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'Und nun verherrliche Mich, Du Vater, bei Dir Selbst mit der Herrlichkeit, die Ich bei Dir hatte, ehe denn die Welt war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Ich habe Deinen Namen geoffenbart den Menschen, die Du aus der Welt Mir gegeben hast. Sie waren Dein, und Du hast sie Mir gegeben, und sie haben Dein Wort gehalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Nun haben sie erkannt, daß alles, was Du Mir gegeben hast, von Dir ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'Denn die Reden, die Du Mir gegeben hast, habe Ich ihnen gegeben, und sie haben sie angenommen und wahrhaftig erkannt, daß Ich von Dir bin ausgegangen, und haben geglaubt, daß Du Mich entsandt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Ich bitte für sie. Nicht für die Welt bitte Ich, sondern für die, so Du Mir gegeben hast, weil sie Dein sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'Und alles, was Mein ist, das ist Dein, und was Dein ist, das ist Mein, und Ich bin verherrlicht in ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'Und Ich bin nicht mehr in der Welt, und sie sind in der Welt; und Ich komme zu Dir. Heiliger Vater, erhalte sie in Deinem Namen, die Du Mir gegeben hast, daß sie eins seien, gleichwie Wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Solange Ich bei ihnen war in der Welt, erhielt Ich sie in Deinem Namen; die Du Mir gegeben hast, habe Ich bewahrt, und ist keiner von ihnen verloren, als der Sohn des Verderbens, auf daß die Schrift erfüllt würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Nun aber komme Ich zu Dir, und rede solches in der Welt, damit sie Meine Freude erfüllt in Sich haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Ich habe ihnen Dein Wort gegeben, und die Welt haßt sie, weil sie nicht aus der Welt sind, wie Ich nicht aus der Welt bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Ich bitte nicht, daß Du sie aus der Welt wegnehmest, sondern daß Du sie erhaltest vor dem Übel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Sie sind nicht aus der Welt, gleichwie Ich nicht aus der Welt bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Heilige sie in Deiner Wahrheit! Dein Wort ist Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Wie Du Mich in die Welt entsandt hast, habe auch Ich sie in die Welt entsandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'Und für sie heilige Ich Mich, auf daß auch sie geheiligt seien in der Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Aber nicht für diese allein bitte Ich, sondern auch für die, so durch ihr Wort an Mich glauben werden:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'Auf daß alle eins seien, wie Du, Vater, in Mir und Ich in Dir, daß auch sie in Uns eins seien, auf daß die Welt glaube, daß Du Mich entsandt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'Und die Herrlichkeit, die Du Mir gegeben hast, habe Ich ihnen gegeben; auf daß sie eins seien, wie Wir eins sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Ich in ihnen, und Du in Mir; auf daß sie vollendet seien in eins, und daß die Welt erkenne, daß Du Mich entsandt und sie geliebt hast, wie Du Mich geliebt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Vater, Ich will, daß, wo Ich bin, auch die bei Mir seien, die Du Mir gegeben hast, auf daß sie Meine Herrlichkeit schauen, die Du Mir gegeben hast, weil Du vor Gründung der Welt Mich geliebt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Gerechter Vater! und die Welt hat Dich nicht erkannt; Ich aber habe Dich erkannt, und diese haben erkannt, daß Du Mich entsandt hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'Und Ich habe ihnen Deinen Namen kundgetan und werde ihn kundtun, auf daß die Liebe, mit der Du Mich geliebt hast, in ihnen sei, und Ich in ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Da Jesus solches gesprochen hatte, ging Er hinaus mit Seinen Jüngern über den Bach Kidron. Da war ein Garten, und in diesen ging Er und Seine Jünger hinein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Judas aber, der Ihn verriet, wußte auch den Ort, weil Jesus Sich mit Seinen Jüngern oft daselbst versammelt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Judas nahm nun die Kohorte und Amtsdiener der Hohenpriester und Pharisäer und kam dahin mit Fackeln und Lampen und Waffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jesus nun, Der alles wußte, was über Ihn kommen sollte, kam heraus und sprach zu ihnen: Wen sucht ihr?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Sie antworteten Ihm: Jesus, den Nazarener. Spricht zu ihnen Jesus: Ich bin es. Judas aber, der Ihn verriet, stand auch bei ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Wie Er nun zu ihnen sprach: Ich bin es! wichen sie zurück und fielen zu Boden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Da fragte Er sie abermals: Wen sucht ihr? Sie aber sagten: Jesus, den Nazarener.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jesus antwortete: Ich habe euch gesagt, daß Ich es bin. Wenn ihr nun Mich suchet, so lasset diese hingehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Auf daß erfüllt würde das Wort, das Er gesprochen: Ich habe derer keinen verloren, die Du Mir gegeben hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'Simon Petrus nun, der ein Schwert hatte, zog es heraus, schlug nach dem Knechte des Hohenpriesters und hieb ihm das rechte Ohr ab. Der Name des Knechtes aber war Malchus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Da sprach Jesus zu Petrus: Stecke das Schwert hinein in die Scheide! Soll Ich den Kelch nicht trinken, den Mir der Vater gegeben hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Die Kohorte nun und der Oberhauptmann und die Amtsdiener der Juden ergriffen Jesus und banden Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'Und sie führten Ihn weg zuerst zu Hannas; denn er war der Schwiegervater des Kaiaphas, der selbigen Jahres Hoherpriester war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Kaiaphas aber war es, der den Juden zuriet, es wäre zuträglich, daß ein Mensch umkäme für das Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Simon Petrus aber folgte Jesus nach, und ein anderer Jünger. Selbiger Jünger aber war dem Hohenpriester bekannt und ging mit Jesus hinein in des Hohenpriesters Hof.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Petrus aber stand draußen vor der Tür. Da ging der andere Jünger, der dem Hohenpriester bekannt war, hinaus und sprach mit der Türhüterin und führte Petrus herein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Da sprach die Magd, die Türhüterin, zu Petrus: Bist du nicht auch von den Jüngern dieses Menschen? Spricht er: Ich bin es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'Die Knechte und Amtsdiener aber standen an einem Kohlenfeuer, das sie gemacht hatten, denn es war kalt, und wärmten sich. Petrus aber stand bei ihnen und wärmte sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Der Hohepriester fragte nun Jesus über Seine Jünger und über Seine Lehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jesus antwortete ihm: Ich habe frei heraus geredet zu der Welt. Ich habe allezeit in der Synagoge und im Heiligtum gelehrt, wo alle Juden zusammenkommen und habe nichts im Verborgenen geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Was fragst du Mich? Frage die, so gehört haben, was Ich zu ihnen redete. Siehe, dieselben wissen, was Ich sagte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Da Er solches sagte, gab einer der Amtsdiener, der dabeistand, Jesus einen Backenstreich und sagte: Antwortest Du also dem Hohenpriester?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jesus antwortete ihm: Habe Ich böse geredet, so zeuge von dem Bösen, habe Ich aber wohl geredet, was schlägst du Mich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Hannas sandte Ihn gebunden zu Kaiaphas, dem Hohenpriester.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Simon Petrus aber stand und wärmte sich: Da sagten sie zu ihm: Bist nicht auch du von Seinen Jüngern? Er leugnete und sagte: Ich bin es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Spricht zu ihm einer der Knechte des Hohenpriesters, ein Verwandter dessen, dem Petrus das Ohr abhieb: Sah ich dich nicht in dem Garten bei Ihm?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Da leugnete Petrus abermals, und alsbald krähte der Hahn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'Da führten sie Jesus von Kaiaphas in das Richthaus. Es war aber am Morgen. Und sie gingen nicht selbst hinein in das Richthaus, auf daß sie sich nicht verunreinigten, sondern das Pascha essen möchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilatus kam dann heraus zu ihnen und sprach: Was für Klage bringt ihr wider diesen Menschen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Sie antworteten und sprachen zu ihm: Wäre Dieser nicht ein Übeltäter, wir hätten Ihn dir nicht überantwortet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Da sprach Pilatus zu ihnen: Nehmt ihr Ihn und richtet Ihn nach eurem Gesetz. Da sprachen die Juden zu ihm: Es ist uns nicht erlaubt, jemand zu töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Auf daß erfüllt würde das Wort Jesu, das Er sprach, indem Er anzeigte, welches Todes Er sterben würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilatus ging nun wiederum hinein in das Richthaus und rief Jesus und sprach zu Ihm: Bist Du der Juden König?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jesus antwortete ihm: Sagst du solches von dir selbst, oder haben dir es andere von Mir gesagt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilatus antwortete: Bin Ich ein Jude? Deine Völkerschaft und die Hohenpriester haben Dich mir überantwortet. Was hast Du getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jesus antwortete: Mein Reich ist nicht aus dieser Welt. Wäre Mein Reich aus dieser Welt, so würden Meine Diener ringen, daß Ich den Juden nicht überantwortet würde. Nun ist aber Mein Reich nicht von hinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Da sprach Pilatus zu Ihm: Also bist Du König? Jesus antwortete: Du sagst es. Ich bin König. Ich bin dazu geboren und bin dazu in die Welt gekommen, daß Ich für die Wahrheit zeuge. Jeder, der aus der Wahrheit ist, hört Meine Stimme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Spricht Pilatus zu Ihm: Was ist Wahrheit? Und da er das gesagt hatte, ging er wiederum hinaus zu den Juden und sagte zu ihnen: Ich finde keine Schuld an Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Ihr habt aber eine Gewohnheit, daß ich einen auf das Pascha losgebe. Seid ihr nun willens, daß ich euch den König der Juden losgebe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Da schrien sie wiederum alle laut: Nicht Diesen, sondern Barabbas. Barabbas aber war ein Räuber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Da nahm denn Pilatus Jesus und geißelte Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'Und die Kriegsknechte flochten eine Krone aus Dornen, setzten sie Ihm auf das Haupt und legten Ihm ein purpurnes Oberkleid um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'Und sprachen: Gegrüßet seist Du, König der Juden! und gaben Ihm Backenstreiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilatus kam nun wiederum heraus und sprach zu ihnen: Sehet, ich führe Ihn heraus zu euch, damit ihr erkennt, daß ich keine Schuld an Ihm finde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Jesus kam nun heraus und trug die Dornenkrone und das Oberkleid von Purpur. Und er sprach zu ihnen: Sehet, der Mensch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Als Ihn nun die Hohenpriester und die Amtsdiener sahen, schrien sie laut und sprachen: Kreuzige, kreuzige Ihn! Spricht Pilatus zu ihnen: Nehmet ihr Ihn und kreuziget Ihn; denn ich finde kein Schuld an Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Die Juden antworteten ihm: Wir haben ein Gesetz, und nach unserem Gesetz muß Er sterben; denn Er hat Sich Selbst zu Gottes Sohn gemacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Da nun Pilatus dieses Wort hörte, fürchtete er sich noch mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'Und ging abermals in das Richthaus hinein und sprach zu Jesus: Woher bist Du? Jesus aber gab ihm keine Antwort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Da sprach Pilatus zu Ihm: Redest Du nicht mit mir? Weißt du nicht, daß ich Gewalt habe, Dich zu kreuzigen, und Gewalt habe, Dich loszugeben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jesus antwortete: Du hättest keine Gewalt über Mich, wenn sie dir nicht von oben gegeben wäre. Darum hat der, so Mich dir überantwortet hat, größere Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Daraufhin suchte Pilatus Ihn loszugeben; die Juden aber schrien und sprachen: Gibst du Diesen los, so bist du des Kaisers Freund nicht; wer sich zum König macht, der spricht wider den Kaiser!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Als Pilatus nun dieses Wort hörte, führte er Jesus heraus und setzte sich auf den Richt- stuhl an den Ort, den man nennt Lithostroton, auf Hebräisch aber Gabbatha.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Es war aber Rüsttag des Paschas, die Stunde aber um die sechste. Und er spricht zu den Juden: Seht, euer König!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Sie aber schrien laut: Weg, weg! Kreuzige Ihn! Spricht zu ihnen Pilatus: Soll ich euren König kreuzigen? Die Hohenpriester antworteten: Wir haben keinen König, als den Kaiser!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Da übergab er Ihn nun denselben, daß Er gekreuzigt würde. Sie nahmen aber Jesus mit und führten Ihn fort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'Und Er trug Sein Kreuz und ging hinaus zur sogenannten Schädelstätte, auf Hebräisch genannt Golgatha.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Allda kreuzigten sie Ihn und mit Ihm zwei andere zu beiden Seiten, Jesus aber in der Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Pilatus aber schrieb auch eine Überschrift und setzte sie auf das Kreuz. Es war aber geschrieben: Jesus der Nazarener, der König der Juden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Diese Überschrift nun lasen viele der Juden; denn der Ort, da Jesus gekreuzigt ward, war nahe bei der Stadt, und es war auf hebräisch, griechisch und römisch geschrieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Da sagten die Hohenpriester der Juden zu Pilatus: Schreibe nicht König der Juden, sondern daß Er sagte: Ich bin der König der Juden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilatus antwortete: Was ich geschrieben habe, das habe ich geschrieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Die Kriegsknechte nun, da sie Jesus gekreuzigt hatten, nahmen Seine Kleider und machten vier Teile, jedem Kriegsknecht ein Teil, und den Leibrock. Der Leibrock aber war ungenäht, von oben an ganz durchhin gewirkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Da sagten sie zueinander: Den wollen wir nicht zerstücken, sondern darum losen, wessen er sein soll, so daß die Schrift erfüllt würde, die da sagt: Sie zerteilten Meine Kleider unter sich, und über Meinen Rock warfen sie das Los. Solches denn taten die Kriegsknechte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Es standen aber beim Kreuze Jesu Seine Mutter und die Schwester Seiner Mutter, Maria, des Klopas Weib, und Maria aus Magdala.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Da nun Jesus die Mutter sah, und den Jünger, den Er liebte, dabeistehen, spricht Er zu Seiner Mutter: Weib, siehe, dein Sohn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Dann spricht Er zu dem Jünger: Siehe, deine Mutter. Und von selbiger Stunde an nahm sie der Jünger zu sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Danach spricht Jesus, da Er wußte, daß schon alles vollendet war, auf daß die Schrift ganz erfüllt würde: Mich dürstet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Es stand nun ein Gefäß voll Essig da. Sie aber füllten einen Schwamm mit Essig, legten diesen um einen Ysopstengel und brachten es an Seinen Mund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Da nun Jesus den Essig genommen hatte, sprach Er: Es ist vollendet! und Er neigte das Haupt und gab den Geist auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Die Juden nun, damit die Leiber nicht am Sabbath am Kreuze blieben denn es war Rüsttag, weil der Tag selbigen Sabbaths groß war, baten den Pilatus, er möchte ihre Beine zerbrechen und sie wegnehmen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Da kamen denn die Kriegsknechte und zerbrachen dem ersten die Beine, und dem anderen, der mit Ihm gekreuzigt worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Als sie aber zu Jesus kamen und sahen, daß Er schon gestorben war, zerbrachen sei Ihm die Beine nicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'Sondern einer der Kriegsknechte stach Ihm mit dem Speer in Seine Seite, und es kam alsbald Blut und Wasser heraus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'Und der es gesehen hat, der hat gezeugt, und wahrhaftig ist sein Zeugnis, und selbiger weiß, daß er Wahres sagt, auf daß auch ihr glaubt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Solches geschah aber, daß die Schrift erfüllt werde: Kein Bein an Ihm soll zerbrochen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'Und wiederum sagt eine andere Schrift: Sie sollen sehen, in wen sie gestochen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Danach aber bat den Pilatus Joseph von Arimathäa, der ein Jünger Jesu war, aber ein verborgener aus Furcht vor den Juden, daß er den Leib Jesu abnehmen dürfte; und Pilatus gestattete es. Da kam er und nahm den Leib Jesu ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Es kam aber auch Nikodemus, der zuerst des Nachts zu Jesus gekommen war, und brachte eine Mischung von Myrrhen und Aloe bei hundert Pfund.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Sie nahmen nun den Leib Jesu und banden ihn in leinene Tücher samt den Spezereien, wie es der Juden Gewohnheit ist beim Begräbnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Es war aber an dem Orte, wo Er gekreuzigt ward, ein Garten, und in dem Garten eine neue Gruft, in die noch niemand je gelegt worden war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Darein legten sie nun Jesus wegen des Rüsttages der Juden, weil die Gruft nahe wahr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'Am ersten der Wochentage aber kommt Maria Magdalena des Morgens, da es noch finster war, an die Gruft, und sieht, daß der Stein von der Gruft weggenommen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Sie läuft nun und kommt zu Simon Petrus und zu dem anderen Jünger, den Jesus lieb hatte, und sagt ihnen: Sie haben den Herrn aus der Gruft weggenommen, und wir wissen nicht, wo sie Ihn hingelegt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Da ging Petrus und der andere Jünger hinaus, und sie kamen an die Gruft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Die beiden liefen aber zugleich, und der andere Jünger lief vor, schneller denn Petrus, und kam zuerst an die Gruft;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'Und bückt sich hinein und sieht die leinenen Tücher liegen; er ging jedoch nicht hinein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Nun kommt Simon Petrus, der ihm nachfolgte, und ging hinein in die Gruft, und sieht die leinenen Tücher liegen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'Und das Schweißtuch, das auf Seinem Haupte war, nicht bei den leinen Tüchern liegen, sondern besonders an einem Ort zusammengewickelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Da ging denn auch der anderer Jünger, der zuerst zur Gruft gekommen war, hinein, und sah und glaubte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Denn sie wußten noch nicht die Schrift, daß Er müßte von den Toten auferstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'Da gingen die Jünger nun wieder weg heim.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Maria aber stand an der Gruft und weinte draußen. Als sie nun weinte, bückte sie sich hinein in die Gruft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'Und schaut zwei Engel in weißen Gewändern sitzen; einen am Haupte und den einen zu den Füßen, da der Leib Jesu gelegen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'Und diese sagen zu ihr: Weib, was weinst du? Sie sagt zu ihnen: Sie haben meinen Herrn weggenommen, und ich weiß nicht, wo sie Ihn hingelegt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'Und als sie solches gesagt hatte, wandte sie sich hinter sich, und schaut Jesus dastehen, und wußte nicht, daß es Jesus sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Spricht Jesus zu ihr: Weib, was weinst du? Wen suchst du? Sie, meinend, daß es der Gärtner sei, spricht zu Ihm: Herr, wenn du Ihn fortgetragen hast, sage mir, wo du Ihn hingelegt hast; und ich will Ihn holen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Spricht zu ihr Jesus: Maria! Sie wendet sich um und spricht zu Ihm: Rabbuni, das ist: Lehrer!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Spricht zu ihr Jesus: Berühre Mich nicht, denn Ich bin noch nicht aufgestiegen zu Meinem Vater; gehe aber hin zu Meinen Brüdern und sage ihnen: Ich steige auf zu Meinem Vater und zu eurem Vater und zu Meinem Gott und zu eurem Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Maria Magdalena kommt und sagt es den Jüngern an, daß sie den Herrn gesehen, und daß Er solches zu ihr gesagt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Als es nun Abend war am selbigen ersten Tage der Woche, und die Türen, wo die Jünger versammelt waren, aus Furcht vor den Juden verschlossen waren, kam Jesus und stand in der Mitte und sprach zu ihnen: Friede sei mit euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'Und als Er das sagte, zeigte Er ihnen Seine Hände und Seine Seite. Da freuten sich die Jünger, als sie den Herrn sahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Da sprach Jesus abermals zu ihnen: Friede sei mit euch! Gleichwie Mich der Vater entsendet hat, so sende Ich euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'Und da Er solches gesagt hatte, hauchte Er sie an und sprach zu ihnen: Nehmet hin den Heiligen Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Welchen ihr die Sünden erlasset, denen sind sie erlassen; welchen ihr sie behaltet, denen sind sie behalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Thomas aber, einer aus den Zwölfen, genannt Didymus, war nicht bei ihnen, als Jesus kam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Da sagten die anderen Jünger zu ihm: Wir haben den Herrn gesehen! Er aber sprach zu ihnen: Es sei denn, daß ich in Seinen Händen das Nägelmal sehe, und meinen Finger lege in das Nägelmal und lege mein Hand in Seine Seite, werde ich es nicht glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'Und nach acht Tagen waren Seine Jünger wiederum drinnen, und Thomas mit ihnen. Kommt Jesus bei verschlossenen Türen, und stand in der Mitte und sprach: Friede sei mit euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Dann spricht er zu Thomas: Reiche deinen Finger her und siehe Meine Hände, und reiche deine Hand her und lege sie in Meine Seite, und sei nicht ungläubig, sondern gläubig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Thomas antwortete und sprach zu Ihm: Mein Herr und mein Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Spricht Jesus zu ihm: Weil du Mich gesehen hast, Thomas, hast du geglaubt. Selig sind, die nicht sehen und glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'Viele andere Zeichen nun tat Jesus vor Seinen Jüngern, die nicht geschrieben sind in diesem Buche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'Diese aber sind geschrieben, damit ihr glaubt, daß Jesus ist der Christ, der Sohn Gottes, auf daß ihr glaubt und Leben habt in Seinem Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Danach offenbarte Sich Jesus den Jüngern abermals am Meer von Tiberias. Er offenbarte Sich aber also:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Es waren beisammen Simon Petrus und Thomas, genannt der Zwilling, und Nathanael aus Kana in Galiläa und die Söhne des Zebedäus und zwei andere von Seinen Jüngern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Spricht zu ihnen Simon Petrus: Ich gehe hin fischen. Sie sagen zu ihm: Wir gehen auch mit dir. Sie gingen hinaus und stiegen alsbald in ein Schiff, fingen aber nichts in selbiger Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Als es aber schon Morgen geworden, stand Jesus am Ufer; die Jünger aber wußten nicht, daß es Jesus war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Spricht zu ihnen Jesus: Kindlein, habt ihr nichts zu essen? Sie antworteten Ihm: Nein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'Er aber sagte zu ihnen: Werfet das Netz zu rechten Seite des Schiffes, und ihr werdet finden. Da warfen sie es aus und vermochten es nicht mehr zu ziehen vor der Menge der Fische.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Da spricht selbiger Jünger, den Jesus liebte, zu Petrus: Es ist der Herr! Da Simon Petrus hörte, daß es der Herr wäre, gürtete er sich den Überwurf um - denn er war nackt -und warf sich ins Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'Die anderen Jünger aber kamen in dem Schifflein denn sie waren nicht weit vom Lande, sondern etwa zweihundert Ellen und schleppten das Netz mit den Fischen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Wie sie nun ans Land ausstiegen, sehen sie ein Kohlenfeuer angelegt und ein Fischlein darauf liegen und Brot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Spricht Jesus zu ihnen: Bringet nun von den Fischlein, die ihr gefangen habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Petrus stieg hinein und zog das Netz ans Land voll großer Fische hundertdreiundfünfzig. Und wiewohl es so viele waren, zerriß das Netz nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Spricht Jesus zu ihnen: Kommt her und frühstückt! Keiner der Jünger aber wagte Ihn zu fragen: Wer bist Du? Da sie wußten, daß es der Herr war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Da kommt Jesus und nimmt das Brot und gibt es ihnen, desgleichen auch das Fischlein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'Dies war nun das dritte Mal, daß Jesus Sich Seinen Jüngern offenbarte, nachdem Er von den Toten auferweckt ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Als sie nun gefrühstückt hatten, spricht Jesus zu Simon Petrus: Simon Jona, liebst du Mich mehr denn diese? Er spricht zu ihm: Ja, Herr, Du weißt, daß ich Dich lieb habe. Spricht Er zu ihm: Weide Meine Lämmlein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Spricht Er wieder zum zweitenmal zu ihm: Simon Jona, liebst du Mich? Spricht er zu Ihm: Ja, Herr, du weißt, daß ich Dich lieb habe. Spricht Er zu ihm: Hüte Meine Schafe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Spricht Er zum drittenmal zu ihm: Simon Jona, hast du Mich lieb? Petrus ward betrübt, daß Er zum dritten Male zu ihm sagte: Hast du Mich lieb? Und er sprach zu Ihm: Herr, du weißt alle Dinge, Du erkennst, daß ich Dich lieb habe. Sagt Jesus zu ihm: Weide Meine Schafe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Wahrlich, wahrlich, Ich sage dir: Da du jünger warst, gürtetest du dich selbst und wandeltest, wo du wolltest. Wenn du aber alt bist, wirst du deine Hände ausrecken, und ein anderer wird dich gürten und bringen, wo du nicht hin willst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'Dies sagte Er aber, um anzuzeigen, mit welchem Tode er Gott verherrlichen würde. Und als Er solches gesprochen hatte, sagte Er zu ihm: Folge Mir nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Petrus aber wandte sich um und erblickte den Jünger nachfolgen, den Jesus liebte, der auch beim Abendmahl sich nach Seiner Brust neigte, und sprach: Herr, wer ist es, der Dich verrät?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Wie Petrus diesen sieht, spricht er zu Jesus: Herr, was aber soll dieser?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Spricht zu ihm Jesus: Wenn Ich will, daß dieser bleibe, bis daß Ich komme, was ist das Dir? Folge du Mir nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Da ging denn dieses Wort aus unter die Brüder, daß dieser Jünger nicht stürbe. Und Jesus hatte ihm nicht gesagt, daß er nicht sterbe, sondern: Wenn Ich will, daß dieser bleibe, bis daß Ich komme, was ist das dir?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Dies ist der Jünger, der darüber zeugt und dies geschrieben hat, und wir wissen, daß sein Zeugnis wahr ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Es sind aber auch viele andere Dinge, die Jesus getan hat, welche, so man sie sollte einzeln beschreiben, erachte ich, die Welt selbst würde die Bücher nicht fassen, die zu schreiben wären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'In meiner ersten Schrift habe ich, mein Thophilus, von alle dem berichtet, was Jesus von Anfang an tat und lehrte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'Bis zu dem Tag, da Er emporgenommen ward, nachdem Er durch den Heiligen Geist den Aposteln, die Er erwählt hatte, Befehle gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'Welchen Er Sich auch nach Seinem Leiden lebend darstellte in vielen Bezeugungen, indem Er ihnen vierzig Tage lang erschien und über das Reich Gottes mit ihnen redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'Und als Er sie um Sich versammelt hatte, befahl Er ihnen, nicht von Jerusalem zu weichen, sondern auf die Verheißung des Vaters zu warten, â¬Sdie ihr von Mir gehört habtâ¬_.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'Denn Johannes taufte mit Wasser; ihr aber sollt nicht lange nach diesen Tagen mit dem Heiligen Geist getauft werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Die also zusammengekommen waren, fragten Ihn und sagten: Herr, wirst Du auf diese Zeit das Reich wieder für Israel aufrichten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'Er aber sprach zu ihnen: Euch steht es nicht zu, Zeit oder Stunde zu wissen, die der Vater für Seine Macht bestimmt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'Ihr werdet aber die Kraft des über euch kommenden Heiligen Geistes empfangen und Mir Zeugen sein in Jerusalem und in ganz Judäa und Samarien und bis an das Ende der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'Und da Er solches gesprochen, ward Er zusehends aufgehoben, und eine Wolke nahm Ihn vor ihren Augen weg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'Und wie sie, während Er auffuhr gen Himmel, Ihm nachsahen, siehe, da standen zwei Männer in weißen Kleidern vor ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'Die sprachen: Männer von Galiläa, was steht ihr hier und schaut gen Himmel? Dieser Jesus, Der von euch ist aufgenommen gen Himmel empor, wird wiederkommen, wie ihr Ihn gen Himmel fahren sahet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Sie kehrten sodann von dem Berge, dem sogenannten Eläon, der nahe bei Jerusalem liegt und nur einen Sabbathweg entfernt ist, nach Jerusalem zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'Und als sie hineinkamen, stiegen sie auf den Söller, wo sie wohnten, Petrus und Jakobus und Johannes und Andreas, Philippus und Thomas, Bartholomäus und Matthäus, Jakobus des Alphäus und Simon, der Eiferer, und Judas des Jakobus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Diese alle hielten einmütig an im Gebet und Flehen mit den Weibern und Maria, der Mutter Jesus, und mit Seinen Brüdern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'In dieses Tagen trat Petrus inmitten der Jünger auf und sprach: es waren etwa hundertzwanzig beisammen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Männer, Brüder, es mußte das Wort der Schrift erfüllt werden, das der Heilige Geist durch den Mund Davids über Judas geweissagt hat, der ein Wegweiser ward denen, die Jesus gefangennahmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Er war uns beigezählt und hatte das Los dieses Dienstes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Dieser nun hat erworben den Acker für den Lohn der Ungerechtigkeit, hat sich erhängt und ist mitten entzwei geborsten und ward all sein Eingeweide ausgeschüttet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'Und es ward kund allen, die zu Jerusalem wohnen, so daß der Acker in ihrer Mundart Hakeldama, das ist Blutacker, genannt worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Denn es steht geschrieben im Psalmbuch: Ihre Behausung soll wüste werden, und niemand sein, der darin wohne, und sein Amt ein anderer empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'So muß denn einer der Männer, welche die ganze Zeit über, die der Herr Jesus unter uns ist aus- und eingegangen, mit uns gewesen sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'Anfangend von der Taufe des Johannes bis auf den Tag, da Er vor uns aufgenommen ward, ein Zeuge Seiner Auferstehung mit uns werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'Und sie stellten zwei, Joseph, genannt Barsabas, mit dem Zunamen Justus, und Matthias dar;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'Beteten und sprachen: Herr, aller Herzenskündiger, zeige an, welchen Du von diesen zweien auserwählt hast,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'Daß er empfange das Los dieses Dienstes und Apostelamtes, davon Judas abgewichen ist, daß er hinginge an seinen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'Und sie warfen das Los über sie, und das Los fiel auf Matthias, und er ward den elf Aposteln zugezählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'Und als der Tag der Pfingsten erfüllt ward, waren sie alle einmütig beisammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Da geschah plötzlich ein Brausen vom Himmel wie eines gewaltig daherfahrenden Windes, und erfüllte das ganze Haus, wo sie saßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'Und es erschienen ihnen Zungen wie Feuer, die sich verteilten, und er setzte sich auf jeden von ihnen, und alle wurden vom Heiligen Geiste erfüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'Und fingen an mit anderen Zungen zu reden, je nachdem der Geist sie antrieb zu sprechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Es hielten sich aber Juden in Jerusalem auf, gottesfürchtige Männer aus allerlei Volk, das unter dem Himmel ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Als nun dieses Sausen geschah, kam die Menge zusammen und sie waren erstaunt, da jeder sie seine eigene Mundart sprechen hörte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'Und sie entsetzten sich alle und fragten einander verwundert: Siehe, sind nicht alle, die da sprechen, Galiläer?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'Und wie hören denn wir sie sprechen ein jeglicher in seiner Sprache, in der er geboren ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parther und Meder und Elamiter und die wir wohnen in Mesopotamien und Judäa und Kappadozien, Pontus und Asien,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Und Phrygien und Pamphylien, Ägypten und den Gegenden Libyens um Cyrene und die Ausländer von Rom,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Juden und Judengenossen, Kreter und Araber? Wir hören sie mit unseren Zungen die großen Taten Gottes preisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'Sie entsetzten sich alle und wußten nicht es zu deuten, indem einer zum anderen sprach: Was will das werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'Andere aber hatten ihren Spott und sagten: Sie sind voll süßen Weines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Da trat Petrus auf mit den Elfen, erhob seine Stimme und redete zu ihnen: Männer von Judah, und ihr alle, die ihr in Jerusalem wohnt, das sei euch kundgetan und schenkt Gehör meinen Worten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Die da sind fürwahr nicht, wie ihr wähnt, betrunken, sintemal es die dritte Stunde am Tage ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'Vielmehr tritt ein, was durch den Propheten Joel gesagt worden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, 'In den letzten Tagen wird geschehen, spricht Gott, daß Ich von Meinen Geist ausgießen werde über alles Fleisch, und weissagen werden eure Söhne und Töchter, und eure Jünglinge Gesichte sehen, und die Alten Traumgesichte haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'Und auf Meine Knechte und Mägde werde Ich in jenen Tagen von Meinem Geist ausgießen, daß sie weissagen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'Und Ich werde Wunder tun am Himmel oben, und Zeichen unten auf Erden mit Blut, Feuer und Rauchdampf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'Die Sonne soll sich in Finsternis verkehren und der Mond in Blut, ehe denn der große und herrliche Tag des Herrn kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'Und soll geschehen, daß, wer den Namen des Herrn anruft, gerettet wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Ihr Männer von Israel, hört diese Worte: Jesus von Nazareth, den Mann von Gott unter euch beglaubigt mit Taten, Wundern und Zeichen, die Gott durch Ihn in eurer Mitte tat, wie denn ihr selbst es wisset.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'Diesen habt ihr, als Er euch durch Gottes Ratschluß und Vorhersehung in eure Gewalt gegeben worden, durch gottlose Hände ans Kreuz geschlagen und zum Tode gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Ihn hat Gott auferweckt, und gelöst die Schmerzen des Todes, wie es denn nicht möglich war, daß Er von ihnen sollte gehalten werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'Denn David sagt von Ihm: Ich sah den Herrn vor mir immerdar; denn Er ist mir zur Rechten, auf daß ich nicht wanke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Deshalb freute sich mein Herz und frohlockte meine Zunge; zudem wird auch mein Fleisch in Hoffnung ruhen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'Du wirst meine Seele nicht in der Hölle lassen, nicht zugeben, daß Dein Heiliger Verwesung sehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Du hast mir kund getan die Wege des Lebens, und erfüllst mich mit Freuden vor Deinem Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Männer, Brüder! sintemal ich mit allem Freimut zu euch von unserem Erzvater David reden darf, daß er gestorben und begraben worden, und seine Grabstätte bei uns sich findet bis auf diesen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Da er nun ein Prophet war und eingedenk, daß ihm Gott mit einem Eide verheißen hatte, daß von der Frucht seiner Lenden Einer auf seinem Throne sitzen werde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'Hat er vorhergesehen und geredet von Christus Auferstehung, daß Seine Seele nicht in der Hölle gelassen und Sein Fleisch die Verwesung nicht sehen würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Diesen Jesus hat Gott auferweckt, dessen wir alle Zeugen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Nun Er zur Rechten Gottes erhöht ist, und die Verheißung des Heiligen Geistes vom Vater empfangen hat, hat Er ausgegossen das, was ihr seht und hört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Denn David ist nicht in den Himmel aufgestiegen; er selbst aber spricht: Der Herr sprach zu meinem Herrn: Setze Dich zu Meiner Rechten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'Bis daß Ich Deine Feinde Dir als Schemel zu Füßen lege.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'So erkenne denn das ganze Haus Israel mit Gewißheit, daß Gott diesen Jesus, Den ihr gekreuzigt, zum Herrn und Christus gemacht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Da sie das hörten, ging es ihnen durch das Herz, und sie sprachen zu Petrus und den anderen Aposteln: Was sollen wir tun, ihr Männer und Brüder?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Petrus aber sprach zu ihnen: Tut Buße und lasse sich ein jeder von euch taufen auf den Namen von Jesus Christus zur Vergebung der Sünden, so werdet ihr die Gabe des Heiligen Geistes empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Denn für euch und eure Kinder ist diese Verheißung, und für alle, die noch ferne sind, so viel ihrer der Herr, unser Gott, herzurufen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'Und mit vielen anderen Worten bezeugte er und ermahnte sie, indem er sprach: Rettet euch von diesem verkehrten Geschlecht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Sie nahmen seine Rede bereitwillig an und ließen sich taufen, und an jenem Tage wurden bei dreitausend Seelen hinzugetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Sie hielten aber an der Lehre der Apostel und an der Gemeinschaft und am Brotbrechen und am Gebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Es kam aber über alle Seelen eine Furcht, und viele Wunder und Zeichen geschahen durch die Apostel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Alle aber, die gläubig geworden waren, hielten zusammen und hatten alle Dinge gemein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'Güter und Habe verkauften sie und verteilten an alle, je wie einer dessen bedürftig war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'Alltäglich beharrten sie einmütig im Tempel, brachen hin und wieder das Brot in den Häusern,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'Hielten ihre Mahle in Fröhlichkeit und Einfalt des Herzens, lobpreisten Gott und hatten Gunst bei dem ganzen Volk. Der Herr aber mehrte täglich die Zahl der Geretteten in der Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Petrus aber und Johannes gingen zusammen hinauf in den Tempel um die neunte Stunde, da man zu beten pflegte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'Und es war ein Mann, lahm von Mutterleib, der ließ sich hertragen, und sie setzten ihn täglich vor des Tempels Pforte, die da heißt die schöne, damit er Almosen bettelte von denen, die in den Tempel gingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Da dieser nun Petrus und Johannes sah, wie sie eben in den Tempel treten wollten, bat er um ein Almosen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Petrus aber sah ihn fest an mit Johannes und sprach: Sieh uns an!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'Er aber schaute auf sie, indem er erwartete, daß er etwas empfinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Petrus aber sprach: Silber und Gold habe ich nicht; was ich aber habe, das gebe ich dir: Im Namen des Jesus Christus von Nazareth stehe auf und wandle!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'Und er griff ihn bei der rechten Hand und richtete ihn auf. Alsbald wurden seine Füße und Knöchel fest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'Und er sprang auf, stand und wandelte umher, und trat mit ihnen in den Tempel, wandelte umher und sprang und lobte Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'Und alles Volk sah ihn umherwandeln und Gott lobpreisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'Und sie erkannten ihn, daß er der war, der um Almosen an der schönen Pforte des Tempels saß, und wurden voll Staunens und waren vor Verwunderung außer sich über dem, was sich mit ihm hatte zugetragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Da sich der Lahme, der nun gesund geworden, zu Petrus und Johannes hielt, lief alles Volk voll Erstaunens nach der Halle, die da heißt Salomohs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Da das Petrus sah, hob er an zum Volke: Ihr Männer von Israel, was verwundert ihr euch über diesen? Oder warum richtet ihr eure Blicke auf uns, als hätten wir durch eigene Kraft und Frömmigkeit bewirkt, daß dieser gehen kann?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Der Gott Abrahams und Isaaks und Jakobs, der Gott unserer Väter, hat Seinen Sohn Jesus verherrlicht, Welchen ihr habt überantwortet und verleugnet vor dem Angesichte des Pilatus, obschon dieser beschlossen hatte, Denselben freizulassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'Ihr aber verleugnetet den Heiligen und Gerechten, und verlangtet, man solle euch den Mörder freigeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Aber den Fürsten des Lebens habt ihr getötet, Ihn aber hat Gott von den Toten erweckt, dessen wir Zeugen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'Und um des Glaubens willen an Seinen Namen hat diesen, den ihr seht und kennt, Sein Name gestärkt und der durch ihn bewirkte Glaube ihm vor euer aller Augen die Vollkraft seiner Glieder geschenkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Und nun, Brüder, weiß ich, daß ihr es aus Unwissenheit getan habt, sowie auch eure Obern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Gott aber ließ so, was Er durch den Mund aller Seiner Propheten voraus verkündigt hatte, daß Christus müßte leiden, in Erfüllung gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'So tut nun Buße und bekehrt euch, auf daß eure Sünden ausgetilgt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'Auf daß da kommen Zeiten der Erquikkung vor dem Angesicht des Herrn, und daß Er euch den vorher verkündigten Jesus Christus senden wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'Welchen indessen der Himmel aufnehmen mußte, bis zu den Zeiten der Wiederbringung aller Dinge, wovon Gott durch den Mund Seiner heiligen Propheten von Anbeginn gesprochen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Denn Moses hat zu den Vätern gesprochen: Der Herr, euer Gott, wird euch aus euren Brüdern einen Propheten wie mich erwecken. Auf Ihn sollt ihr hören in allem, was Er zu euch reden wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Es wird aber geschehen, daß jegliche Seele, die nicht auf selbigen Propheten hören wird, aus dem Volke ausgerottet wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Und alle Propheten von Samuel an und hernach, soviel deren geredet, haben auch diese Tage voraus verkündigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Ihr seid die Söhne der Propheten und des Bundes, den Gott mit unseren Vätern geschlossen hat, da Er zu Abraham sprach: Durch deinen Samen sollen alle Geschlechter der Erde gesegnet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Euch zuvörderst hat Gott Seinen Sohn erweckt und gesandt, euch zu segnen, so ein jeglicher umkehrt von seinen Übeltaten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Als sie so zu dem Volke redeten, traten zu ihnen die Priester und der Tempelhauptmann und die Sadduzäer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'Die es verdroß, daß sie das Volk lehrten und an Jesus die Auferstehung von den Toten verkündigten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'Und legten die Hände an sie und nahmen sie in Gewahrsam für den morgenden Tag; denn es war schon Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Aber viele von denen, so die Rede gehört, wurden gläubig, und die Zahl der Männer ward bei fünftausend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Am Morgen aber versammelten sich die Obern und Ältesten und die Schriftgelehrten gen Jerusalem,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'Und Hannas, der Hohepriester, und Kaiaphas und Johannes und Alexander; und so viel ihrer vom Geschlechte der Hohenpriester waren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'Und ließen sie vorführen in ihre Mitte und fragten sie: Aus welcher Macht und in wessen Namen habt ihr das getan?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Da ward Petrus vom Heiligen Geist erfüllt und sprach zu ihnen: Ihr Obern des Volkes und ihr Ältesten Israels!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Wenn wir heute verhört werden wegen der Wohltat an einem Kranken und durch wen er ist gesund geworden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'So sei euch allen und allem Volke Israel kundgetan, daß er durch den Namen des Jesus Christus von Nazareth, Den ihr gekreuzigt habt, Den Gott von den Toten auferweckt hat, durch Diesen der Mann gesund vor euren Augen steht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'Das ist der Stein, den die Bauleute verworfen haben, der zum Eckstein geworden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'Und ist in keinem anderen das Heil; denn kein anderer Name unter dem Himmel ist den Menschen gegeben, durch den wir könnten selig werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Da sie nun die Freimütigkeit des Petrus und Johannes sahen, und wußten, daß sie ungelehrte Leute und Laien waren, verwunderten sie sich denn sie kannten sie, daß sie mit Jesus gewesen waren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Und den Mann, der geheilt worden war, bei ihnen stehen, wußten sie nichts dagegen zu sagen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Sondern hießen sie aus der Versammlung abtreten, berieten sich miteinander und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'Was fangen wir mit diesen Leuten an? Denn ein kundbares Zeichen ist durch sie geschehen, und offenbar vor den Augen aller, die in Jerusalem wohnen, und wir können es nicht verleugnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Damit es sich aber nicht weiter unter dem Volk verbreite, wollen wir sie ernstlich bedrohen, daß sie hinfort niemanden von diesem Namen sagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'Und riefen sie herein und geboten ihnen, durchaus im Namen Jesus nicht zu reden, noch zu lehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'Petrus aber und Johannes antworteten ihnen und sprachen: Richtet selbst, ob es recht ist vor Gott, daß wir euch mehr gehorchen als Gott;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Denn wir können nicht schweigen von dem, was wir gesehen und gehört haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Sie bedrohten sie aber noch weiter, und ließen sie dann gehen, da sie nichts fanden, wie sie sie bestrafen könnten, um des Volkes willen; denn sie priesen alle Gott ob dem, das geschehen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Denn der Mann, an dem dieses Heilwunder geschehen, war über vierzig Jahre alt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Als man sie freigelassen, kamen sie zu den Ihrigen und verkündeten, was die Hohenpriester und Ältesten zu ihnen gesagt hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Da sie das hörten, erhoben sie einmütig ihre Stimme zu Gott und sprachen: Herr, Gott, Der den Himmel und die Erde und das Meer und alles, was darin ist, geschaffen hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'Der Du durch den Mund Davids, Deines Knechtes, gesprochen hast: Warum tobten die Völker, und sannen Eitles die Völkerschaften?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Die Könige der Erde sind aufgetreten und die Fürsten versammelt zu Hauf wider den Herrn und Seinen Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Es haben sich in Wahrheit versammelt wider Deinen heiligen Sohn Jesus, Den Du gesalbt hast, Herodes und Pontius mit den Heiden und denen vom Volk Israel,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'Zu tun, was Deine Hand und Dein Rat zuvor bestimmt hatte, was geschehen sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'Und nun, Herr, siehe an ihre Drohungen und verleih Deinen Knechten, mit allem Freimut zu reden Dein Wort;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 'Und strecke Deine Hand aus zur Heilung, und laß Zeichen und Wunder durch den Namen Deines heiligen Sohnes Jesus geschehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'Und als sie so beteten, erbebte die Stätte, da sie versammelt waren, und alle wurden des Heiligen Geistes voll, und verkündeten mit Freimut das Wort Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Die Menge aber der Gläubigen war ein Herz und eine Seele, auch sagte keiner von seinen Gütern, daß sie sein wären, vielmehr hatten sie alles miteinander gemein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'Und mit großer Kraft gaben die Apostel Zeugnis von der Auferstehung des Herrn Jesus, und war große Gnade bei ihnen allen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Es war auch keiner unter ihnen, der Mangel litt; denn wie viele derselben Grundstücke oder Häuser besaßen, die verkauften dieselben und brachten den Erlös des Verkauften,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'Und legten es zu den Füßen der Apostel, und wurde davon einem jeden gegeben, so viel er bedurfte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'So tat Joses, von den Aposteln Barnabas benannt, was verdolmetscht heißt: Sohn des Trostes, ein Levit, aus Zypern gebürtig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'Er hatte ein Grundstück, verkaufte es, brachte das Geld und legte es zu den Füßen der Apostel nieder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'Ein Mann aber, mit Namen Ananias, verkaufte mit seinem Weibe Sapphira ein Gut,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'Und behielt mit Wissen seines Weibes von dem Erlös zurück, brachte einen Teil und legte ihn zu den Füßen der Apostel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Petrus aber sprach: Ananias, warum hat der Satan dein Herz erfüllt, daß du den Heiligen Geist belogest und von dem Erlös des Grundstückes zurückbehieltest?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Blieb es nicht, unverkauft, dein eigen, und verkauft in deiner Gewalt? Was hast du den solches in deinem Herzen beschlossen? Du hast nicht Menschen, sondern Gott belogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Da Ananias diese Worte hörte, fiel er nieder und gab den Geist auf. Und es kam eine große Furcht über alle, die es hörten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Es standen aber die Jüngeren auf, nahmen ihn bei Seite, trugen ihn hinaus und begruben ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Es begab sich aber nach Verlauf von etwa drei Stunden, daß sein Weib, die nichts von dem Vorgefallenen wußte, eintrat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Da hob Petrus an zu ihr: Sage mir, habt ihr das Grundstück so teuer verkauft? Sie sprach: Ja, so teuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Petrus aber sprach zu ihr: Was seid ihr übereingekommen, den Geist des Herrn zu versuchen? Siehe, die Füße derer, die deinen Mann begruben, sind vor der Tür und werden dich hinaustragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'Da stürzte sie alsbald zu seinen Füßen nieder und gab den Geist auf. Da traten die Jünglinge ein, fanden sie tot, trugen sie fort und begruben sie bei ihrem Manne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'Und es kam eine große Furcht über die ganze Gemeinde und über alle, die solches hörten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Es geschahen aber durch die Hände der Apostel viele Zeichen und Wunder unter dem Volke, und sie waren alle einmütig beisammen in Salomohs Halle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'Von den übrigen aber wagte keiner sich ihnen zuzugesellen, aber das Volk hielt große Dinge auf sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'Es wurden aber eine Menge Männer und Weiber, die an den Herrn glaubten, hinzugetan;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'So daß man die Kranken auf die Gassen herausbrachte und auf Tragstellen und Betten niederließ, auf daß, wenn Petrus käme, auch nur sein Schatten ihrer einen überschattete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Es kamen auch viele aus den Städten umher nach Jerusalem, und brachten Kranke und die von unsauberen Geistern geplagt wurden, und alle wurden geheilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Da erhob sich aber der Hohepriester und alle, die mit ihm waren, und die Sekte der Sadduzäer, und wurden voll Eifers,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'Und legten ihre Hände an die Apostel und brachten sie in öffentlichen Gewahrsam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Der Engel des Herrn aber tat während der Nacht die Türen des Gefängnisses auf, führte sie heraus und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Gehet hin, stehet in dem Tempel und redet zum Volke alle die Worte dieses Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Da sie das gehört hatten, gingen sie in aller Frühe in den Tempel und lehrten. Der Hohepriester aber kam herbei und die mit ihm waren, und beriefen den Hohen Rat und alle Ältesten der Söhne Israels und schickten nach dem Gefängnis, um sie vorführen zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'Als aber die Diener kamen, fanden sie dieselben nicht im Gefängnis, kehrten wieder und verkündigten es,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'Und sprachen: Das Gefängnis haben wir mit allem Fleiß verschlossen gefunden und die Hüter standen vor den Türen; da wir aber auftaten, fanden wir niemand darin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Wie sie diese Reden hörten, wurden der Oberpriester, der Tempelhauptmann und die Hohenpriester betreten und wußten nicht, was doch das werden sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Da kam jemand und sagte ihnen an: Siehe, die Männer, die ihr ins Gefängnis geworfen, sind im Tempel, stehen und lehren das Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Da ging der Tempelhauptmann mit den Gerichtsdienern ab, und führte sie herbei, nicht mit Gewalt; denn sie fürchteten sich vor dem Volke, sie möchten gesteinigt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'Und da sie selbige brachten, stellten sie sie vor den Hohen Rat, und der Hohepriester befragte sie,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'Und sprach: Haben wir euch nicht ernstlich untersagt, in diesem Namen zu lehren? Und siehe, ihr habt ganz Jerusalem mit eurer Lehre erfüllt, und wollt das Blut dieses Menschen auf uns bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Da antworteten Petrus und die Apostel und sprachen: Man muß Gott mehr gehorchen als den Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Der Gott unserer Väter hat Jesus auferweckt, Den ihr zum Tode gebracht und ans Kreuz geschlagen habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Diesen hat Gott mit Seiner Rechten zu einem Fürsten und Heiland erhöht, zu geben Israel Buße und Vergebung der Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'Und wir sind über diese Dinge Seine Zeugen, und der Heilige Geist, den Gott gegeben hat denen, die Ihm gehorchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Da sie dies hörten, schnitt es ihnen durchs Herz, und sie gedachten, sie umzubringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Da stand aber in dem Hohen Rat ein Pharisäer auf, mit Namen Gamaliel, ein Schriftgelehrter, der bei allem Volk in Achtung stand, und hieß die Apostel für eine Weile abführen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'Und sprach zu ihnen: Männer von Israel, nehmet euch wohl in Acht, was ihr mit diesen Männern tun wollet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Vor diesen Tagen stand Theudas auf und gab vor, er sei etwas, und es hingen ihm eine Anzahl Männer an, bei vierhundert; der ward erschlagen, und alle, die sich zu ihm hielten, sind zerstreut und zunichte geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Nach ihm stand der Galiläer Judas auf, in den Tagen der Schatzung, und brachte viel Volks zum Abfall. Auch er kam um, und alle, die zu ihm hielten, wurden zerstreut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'Und nun sage ich euch, befasset euch nicht mit diesen Leuten, und lasset sie gehen! Ist dieses Vorgehen, oder dies Werk von Menschen, so wird es untergehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'Ist es aber von Gott, so könnt ihr sie nicht unterdrücken, auf daß ihr nicht als solche erfunden werdet, die wider Gott streiten wollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'Da fielen sie ihm zu und riefen den Aposteln, stäupten sie und verboten ihnen, sie sollten nicht reden im Namen Jesus, und gaben sie frei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Sie aber verließen den Hohen Rat hocherfreut, daß sie gewürdigt wurden, um dieses Namens willen Schmach zu erleiden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'und hörten nicht auf, alle Tage im Tempel und in den Häusern zu lehren und das Evangelium von Jesus Christus zu predigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'Als in diesen Tagen die Zahl der Jünger sich mehrte, entstand ein Murren unter den griechischen Juden gegen die Hebräer, daß bei der täglichen Handreichung ihre Witwen hintangesetzt würden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'Da riefen die Zwölf die Menge der Jünger zusammen und sprachen: Es will sich nicht geziemen, daß wir das Wort Gottes hintansetzen und Tische besorgen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Darum, ihr Brüder, sehet euch nach sieben Männern um, die ein gutes Gerücht unter euch haben und voll Heiligen Geistes und Weisheit sind, die wir zu diesem Behufe bestellen mögen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'Wir aber wollen anhalten am Gebet und am Dienste des Wortes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'Und die Rede gefiel der ganzen Gemeinde wohl, und sie wählten Stephanus, einen Mann voll Glaubens und Heiligen Geistes, und Philippus und Prochorus, Nikanor und Timon und Parmenas und Nikolaus, einen Proselyten aus Antiochia.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Diese stellten sie vor die Apostel, und nachdem sie gebetet hatten, legten sie ihnen die Hände auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'Und das Wort Gottes nahm zu und die Zahl der Jünger mehrte sich sehr in Jerusalem, auch eine große Menge Priester nahm den Glauben an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Stephanus aber, voll Gnade und Kraft, tat große Wunder und Zeichen unter dem Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'Da standen etliche auf aus der Schule der sogenannten Libertiner, Cyrenäer und Alexandriner und derer aus Cilicien und Asien, und stritten mit Stephanus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Und vermochten nicht der Weisheit und dem Geist, womit er redete, zu widerstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Sie stifteten dann aber Männer auf, die vorgaben: Wir haben ihn wider Moses und Gott Lästerworte reden hören;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Und hetzten das Volk und die Ältesten und die Schriftgelehrten auf, traten hinzu, schleppten ihn fort, und brachten ihn vor den Hohen Rat und stellten falsche Zeugen auf, die aussagten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'Dieser Mensch hört nicht auf, wider die heilige Stätte und das Gesetz Lästerworte zu reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Denn wir hörten ihn sagen: Jesus, der Nazarener da, wird diese Stätte zerstören und die Satzungen ändern, die uns Moses übergeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'Und alle, die im Rate saßen, richteten ihre Blicke auf ihn und sahen sein Angesicht, wie eines Engels Angesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'Da sprach der Hohepriester: Ist dem also?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'Da sprach er: Männer, Brüder und Väter, höret: Der Gott der Herrlichkeit erschien unserem Vater Abraham, da er in Mesopotamien war, eher er sich in Charan niederließ;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'Und sprach zu ihm: Gehe aus deinem Lande und aus deiner Verwandtschaft hin in ein Land, das Ich dir zeigen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Da zog er aus von der Chaldäer Land und ließ sich in Charan nieder; und von dannen nach dem Tode seines Vaters führte Er ihn über in dieses Land, darin ihr nun wohnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'Und gab ihm kein Besitztum darin, auch nicht eines Fußes breit; verhieß aber, es ihm und seinen Samen nach ihm zum Besitze zu geben, als er noch kein Kind hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Es redete aber Gott also: Dein Same wird ein Fremdling sein in einem fremden Lande, und sie werden ihn dienstbar machen und mißhandeln vierhundert Jahre lang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Aber Ich werde das Volk, dem sie dienen, richten, sprach Gott: Und danach werden sie ausziehen und Mir an dieser Stätte dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'Und gab ihm den Bund der Beschneidung; und so zeugte er Isaak und beschnitt ihn am achten Tage, und Isaak den Jakob, und Jakob die zwölf Erzväter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'Und die Erzväter neideten Joseph und verkauften ihn nach Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'Aber Gott war mit ihm, und errettete ihn aus all seinen Trübsalen und schenkte ihm Gnade und Weisheit vor Pharao, dem König Ägyptens, daß er ihn setzte zum Fürsten über Ägypten und über sein ganzes Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Da kam eine Teuerung über ganz Ägyptenland und Kanaan und eine große Trübsal, und unsere Väter fanden nicht Nahrung genug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Jakob aber hörte, daß Korn in Ägypten wäre und sandte unsere Väter aus aufs erste Mal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'Und beim anderen Mal ward Joseph von seinen Brüdern erkannt und ward dem Pharao Josephs Geschlecht offenbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Joseph sandte aus und ließ seinen Vater Jakob und sein ganzes Geschlecht, fünfundsiebzig Seelen, zu sich rufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'Und Jakob zog hinab nach Ägypten und starb allda, er und unsere Väter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'Und sie wurden herübergebracht nach Sichem und in der Grabstätte beigesetzt, die Abraham um Geld von den Kindern Hemors zu Sichem erkauft hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Wie nun die Zeit der Verheißung nahte, die Gott dem Abraham geschworen hatte, wuchs das Volk und mehrte sich in Ägypten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'Bis daß ein anderer König aufkam, der nichts von Joseph wußte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Dieser handelte arglistig gegen unser Geschlecht und tat übel an unseren Vätern, so daß man die Kindlein aussetzen mußte, und nicht am Leben lassen durfte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'Zu der Zeit ward Moses geboren und war schön vor Gott, und ward drei Monate in seines Vaters Haus ernährt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'Als er aber ausgesetzt ward, hob ihn die Tochter Pharaos auf und ließ ihn für sich zum Sohne auferziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'Und Moses ward unterrichtet in aller Weisheit der Ägypter und war kräftig in Worten und Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Da er aber volle vierzig Jahre alt war, kam ihm in den Sinn, nach seinen Brüdern, den Söhnen Israels, zu sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'Und er sah, wie einer mißhandelt wurde und verteidigte ihn, und nahm Rache für den, dem Leid geschah, indem er den Ägypter erschlug.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Er meinte aber, seine Brüder verstünden, daß Gott durch seine Hand ihnen Heil gäbe; aber sie verstunden es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'Am anderen Tag traf er sie, wie sie sich stritten und trieb sie zum Frieden an und sagte: Ihr Männer seid Brüder, warum tut ihr einander Unrecht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Der aber dem anderen Unrecht tat, stieß ihn von sich und sagte: Wer hat dich zum Herrn und Richter über uns bestellt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Willst du mich umbringen, wie du gestern den Ägypter hast umgebracht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Da floh Moses über dieser Rede und hielt sich in Midjan auf und zeugte daselbst zwei Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'Und als die vierzig Jahre um waren, erschien ihm in der Wüste am Berge Sinai der Engel des Herrn in einer Feuerflamme in dem Busch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Da es Moses sah, wunderte er sich über das Gesicht, und da er hinzutreten wollte, um es sich anzusehen, geschah die Stimme des Herrn zu ihm:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, 'Ich bin der Gott deiner Väter, der Gott Abrahams, und der Gott Isaaks, und der Gott Jakobs. Moses aber erzitterte und wagte nicht mehr hinzuschauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Der Herr aber sprach zu ihm: Ziehe deine Schuhe von den Füßen; denn die Stätte, da du stehst, ist heiliges Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Ich habe wohl gesehen die Mißhandlung Meines Volks in Ägypten und ihr Seufzen gehört, und bin herabgekommen, sie zu befreien, und nun komm her, Ich will dich hin nach Ägypten senden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Diesen Moses, den sie verleugnet und gesagt hatten: Wer hat dich zum Herrn und Richter gesetzt, diesen sandte Gott als Herrn und Erlöser durch die Hand des Engels, Der ihm erschien in dem Busche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Dieser führte sie aus und tat Wunder und Zeichen in Ägyptenland, im Roten Meer und in der Wüste vierzig Jahre lang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Dies ist der Moses, der zu den Söhnen Israels gesprochen hat: Gott, der Herr, wird euch aus euren Brüdern einen Propheten erwecken, gleich wie mich; Ihn sollt ihr hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Dieser ist es, Der in der Gemeinde in der Wüste war mit dem Engel, Der zu ihm redete auf dem Berg Sinai, und mit unseren Vätern, Welcher empfing das lebendige Wort, um es uns mitzuteilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'Dem unsere Väter nicht untertan sein wollten, sondern sich abkehrten von Ihm und mit ihren Herzen sich Ägypten zuwendeten und zu Aharon sagten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'Mache uns Götter, die vor uns herziehen; denn was aus diesem Moses, der uns aus Ägyptenland führte, geworden ist, wissen wir nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'Und sie machten sich in selbigen Tagen ein Kalb und brachten dem Götzenbild Opfer, und freuten sich der Werke ihrer Hände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Gott aber wandte Sich ab und gab sie hin, daß sie dem Himmelsheere dienten, wie im Buche der Propheten geschrieben steht: Brachtet ihr Mir, ihr vom Hause Israel, in der Wüste je Schlacht- und Brandopfer die vierzig Jahre lang?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'Und ihr truget daher das Zelt Molochs und das Sternbild eures Gottes Remphan, die Gußbilder, die ihr gemacht, um sie anzubeten; Ich aber werde euch über Babylon hinaus in Gefangenschaft führen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Das Zelt des Zeugnisses war inmitten unserer Väter in der Wüste, so wie es zu machen verordnet hatte, Der mit Moses redete, nach dem Vorbilde, das er gesehen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Welches auch unsere Väter überkamen und hineinbrachten mit Joschua in das Besitztum der Heiden, die Gott vor dem Angesicht unserer Väter ausstieß, bis auf die Tage Davids.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'Dieser fand Gnade vor Gott und erbat sich eine Zeltwohnung zu finden für den Gott Jakobs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'Salomoh aber erbaute Ihm ein Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Aber der Höchste wohnt nicht in Tempeln, von Menschenhänden gemacht, wie der Prophet spricht:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, 'Der Himmel ist Mein Thron und die Erde Meiner Füße Schemel, was wollt ihr Mir für ein Haus bauen, spricht der Herr, oder welches ist die Stätte, da Ich ruhen möchte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Hat nicht Meine Hand alles dies gemacht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Ihr Halsstarrigen und Unbeschnittenen an Herz und Ohren, immer widerstrebt ihr dem Heiligen Geist, wie eure Väter, also auch ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Welchen Propheten haben eure Väter nicht verfolgt, und getötet die, so die Zukunft des Gerechten verkündeten, dessen Verräter und Mörder ihr nunmehr geworden seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'Ihr, die ihr das Gesetz durch die Dienstleistungen von Engeln empfangen und nicht bewahrt habt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Da sie solches hörten, ergrimmten sie in ihren Herzen und knirschten mit den Zähnen wider ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'Er aber voll Heiligen Geistes schaute an den Himmel auf und sah die Herrlichkeit Gottes, und Jesus zur Rechten Gottes stehen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'Siehe, ich sehe die Himmel aufgetan und des Menschen Sohn zur Rechten Gottes stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'Sie aber schrien mit lauter Stimme, hielten sich die Ohren zu und stürmten einmütig auf ihn ein, stießen ihn zur Stadt hinaus und steinigten ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'Und die Zeugen legten ihre Kleider zu den Füßen eines Jünglings nieder, der Saulus hieß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'Und so steinigten sie den Stephanus, indem er betete und sprach: Herr Jesus, nimm meinen Geist auf!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'Er aber beugte seine Knie und rief mit lauter Stimme: Herr, rechne ihnen diese Sünde nicht auf. Und da er so gesprochen, entschlief er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Saulus hatte Wohlgefallen an seiner Hinrichtung; es erhob sich am selben Tag eine große Verfolgung über die Gemeinde in Jerusalem. Alle zerstreuten sich in die Lande Judäas und Samariens, die Apostel ausgenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Den Stephanus aber bestatteten gottesfürchtige Männer und hielten eine große Klage über ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'Saulus aber wütete gegen die Gemeinde, trat in ihre Häuser ein, schleppte Männer und Weiber hervor und überantwortete sie ins Gefängnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Die Zerstreuten gingen indessen nach allen Richtungen hin und verkündeten das Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'Philippus aber kam hinab in eine Stadt in Samarien und predigte dort Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'Und das Volk schenkte den Worten, die von Philippus gesprochen wurden, einmütig Gehör, da sie auch die Zeichen, die er tat, sahen und hörten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Denn die unsauberen Geister, von denen viele besessen waren, schrien mit lauter Stimme und fuhren aus, auch viele Gichtbrüchige und Lahme wurden geheilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'Und war eine große Freude in selbiger Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Es war aber ein Mann mit Namen Simon in der Stadt, der zuvor Zauberei trieb und das Volk Samarias in Erstaunen setzte, indem er vorgab, er wäre etwas Großes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'Und alle, groß und klein, hielten sich an ihn und sagten: Der ist die große Kraft Gottes, wie sie es nannten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Sie hielten sich aber zu ihm, weil er sie lange Zeit durch seine Zauberei in Erstaunen gesetzt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Als sie aber dem Philippus, der die Heilsbotschaft über das Reich Gottes und den Namen von Jesus Christus verkündigte, Glauben schenkten, ließen sie sich, Männer und Weiber, taufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Simon selbst ward gläubig, ließ sich taufen und hielt sich zu Philippus, und da er die Wundertaten und großen Zeichen sah, die da geschahen, geriet er in Erstaunen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Als die Apostel in Jerusalem hörten, daß Samarien das Wort Gottes angenommen habe, sandten sie Petrus und Johannes zu ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'Als sie hinabkamen, beteten sie über sie, daß sie den Heiligen Geist empfingen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Denn er war noch über keinen von ihnen gekommen, sie waren bloß auf den Namen des Herrn Jesus getauft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Dann legten sie die Hände auf sie und sie empfingen den Heiligen Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Als Simon sah, daß durch Auflegung der Hände der Apostel der Heilige Geist verliehen werde, brachte er ihnen Geld und sagte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'Gebt auch mir diese Macht, daß, so ich einem die Hände auflege, derselbe den Heiligen Geist empfange.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Petrus aber sprach zu ihm: Daß du verdammt seiest mit deinem Gelde, weil du die Gabe Gottes wähntest mit Geld erlangen zu können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Du hast weder Teil noch Erbe an diesem Worte; denn dein Herz ist nicht gerade vor Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'So kehre denn um und bitte Gott, ob Er dir vergeben möchte die Tücke deines Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Denn ich sehe, du bist voll bitterer Galle und in die Bande des Frevels geraten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Da hob Simon an und sprach: Betet ihr für mich zum Herrn, daß nichts von dem, wovon ihr gesprochen, über mich komme!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Sie aber, da sie das Wort des Herrn bezeugt und verkündet hatten, kehrten nach Jerusalem zurück und predigten die Heilsbotschaft in vielen Flecken der Samariter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Ein Engel des Herrn aber redete zu Philippus und sagte: Mache dich auf und ziehe gen Mittag, auf den Weg, der von Jerusalem hinab nach Gaza führt, der ist öde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'Und er machte sich auf und ging dahin; und siehe, ein äthiopischer Mann, ein Eunuche, ein Gewaltiger Kandaces, der Königin der Äthiopier, der über ihren ganzen Schatz gesetzt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'Und nach Jerusalem gekommen war, um anzubeten, war auf dem Heimweg, und las auf seinem Wagen sitzend den Propheten Jesajah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Da sprach der Geist zu Philippus: Tritt hinzu und halte dich zu diesem Wagen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Philippus lief hinzu und hörte ihn lesen im Propheten Jesajah und sprach: Verstehst du auch, was du liest?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'Er aber sprach: Wie könnte ich, so mich nicht jemand zurecht weiset? und lud den Philippus ein, aufzusteigen und sich zu ihm zu setzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Die Stelle der Schrift, die er eben las, lautete: Wie ein Schaf ward Er zur Schlachtbank geführt, und wie ein Lamm vor dem Scherer verstummt, also tut Er Seinen Mund nicht auf,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'Durch Seine Erniedrigung ist das Gericht aufgehoben. Wer wird Sein Geschlecht kundbar machen, weil von der Erde Sein Leben weggenommen wird?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Da hob der Eunuche an und sprach zu Philippus: Bitte, sage mir an, von wem spricht der Prophet? - Von ihm selber, oder von einem anderen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Philippus aber tat seinen Mund auf, fing mit der Schriftstelle an und verkündete ihm die Heilsbotschaft von Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Wie sie so ihres Weges dahinzogen, kamen sie an ein Wasser. Und der Kämmerer spricht: Siehe, da ist Wasser, was hindert es, daß ich mich taufen lasse?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, 'Philippus aber sprach: Wenn du von ganzem Herzen glaubst, so ist es erlaubt. Er aber antwortete und sprach: Ich glaube, daß Jesus Christus der Sohn Gottes ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'Und er ließ den Wagen halten; und beide stiegen hinab in das Wasser, Philippus und der Kämmerer, und er taufte ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Da sie aber aus dem Wasser heraufstiegen, entrückte der Geist des Herrn den Philippus und der Kämmerer sah ihn nicht mehr; er zog aber seines Weges mit Freuden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'Philippus aber ward gefunden in Asdod und wandelte umher und verkündete das Evangelium in allen Städten, bis er kam gen Cäsarea.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Saulus aber schnaubte noch Drohung und Mord wider die Jünger des Herrn und trat zu dem Hohenpriester,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'Und erbat sich von ihm Briefe nach Damaskus an die Synagogen, auf daß, so er etwelche fände auf dem Wege, er sie, Männer und Weiber, gebunden gen Jerusalem führete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Und da er auf dem Wege war und nahe zu Damaskus kam, umblitzte ihn plötzlich ein Licht vom Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'Er stürzte zu Boden und hörte eine Stimme, die ihm zurief: Saul, Saul, was verfolgst du Mich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'Er aber sprach: Wer bist Du, Herr? Der Herr sprach: Ich bin Jesus, Den du verfolgst; es wird dir schwer werden, wider den Stachel zu löcken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Und er sprach mit Zittern und Zagen: Herr, was willst Du, daß ich tue? Der Herr sprach zu ihm: Mache dich auf und gehe hin in die Stadt, da wird man dir sagen, was du tun sollst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Die Männer aber, die mit ihm zogen, standen sprachlos da; denn sie hörten zwar die Stimme, sahen aber niemand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'Saulus aber richtete sich auf von der Erde, und da seine Augen sich auftaten, sah er niemand. Da nahmen sie ihn bei der Hand und führten ihn nach Damaskus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'Drei Tage lang sah er nicht, aß und trank nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Es war aber ein Jünger in Damaskus, mit Namen Ananias, und der Herr sprach zu ihm in einem Gesichte: Ananias! Er sprach: Siehe, hier bin ich, Herr!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'Der Herr sprach zu ihm: Mache dich auf und gehe hin in die Straße, die man die gerade nennt, und frage in dem Hause des Judas nach einem, mit Namen Saul aus Tarsus; denn siehe, er betet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'Und hat gesehen im Gesicht einen Mann mit Namen Ananias eintreten, und ihm die Hand auflegen, auf daß er wieder sehend werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Da antwortete Ananias: Herr, ich habe von vielen gehört, wieviel Übles dieser Mann deinen Heiligen in Jerusalem getan hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'Und allhier hat er Vollmacht von den Hohenpriestern, alle zu binden, die deinen Namen anrufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Der Herr aber sprach zu ihm: Gehe hin, denn er ist Mir ein auserwähltes Werkzeug, Meinen Namen vor Völker und Könige und die Kinder Israels zu tragen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Denn Ich werde ihm zeigen, wieviel er für Meinen Namen leiden muß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'Da ging Ananias hin und kam in das Haus und legte ihm die Hände auf und sprach: Bruder Saul, der Herr hat mich gesandt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'Und alsbald fiel es wie Schuppen von seinen Augen, und er ward wieder sehend, und stand auf und ließ sich taufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'Und er nahm Speise zu sich und stärkte sich; und war etliche Tage bei den Jüngern in Damaskus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'Und alsbald predigte er in den Synagogen von Jesus, daß dieser ist der Sohn Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'Und alle, die ihn hörten, erstaunten und sagten: Ist das nicht der, so in Jerusalem wütete gegen alle, die diesen Namen anriefen, und hierher zu dem Ende gekommen war, sie gebunden an die Hohenpriester zu überantworten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Saul aber ward mehr und mehr gekräftigt, so daß er die Juden, die in Damaskus wohnten, überführte, und erwies, daß dieser ist der Christ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Wie aber viele Tage um waren, hielten die Juden einen Rat, wie sie ihn umbrächten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'Ihr Anschlag aber ward dem Saul kundgetan. sie hielten jedoch Tag und Nacht die Tore bewacht, um ihn umzubringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'Da nahmen ihn die Jünger und ließen ihn in einem Korb von der Mauer hinab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Als Saulus in Jerusalem ankam, versuchte er, sich an die Jünger zu halten; alle aber fürchteten ihn, indem sie nicht glaubten, daß er ein Jünger wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Barnabas aber nahm ihn zu sich, und führte ihn zu den Aposteln und erzählte ihnen, wie er auf dem Wege den Herrn gesehen, und Dieser zu ihm gesprochen habe, und wie er in Damaskus frei Jesus Namen verkündete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'Und er ging aus und ein mit ihnen und verkündigte frei den Namen des Herrn Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Auch redete und stritt er mit den griechischen Juden; diese aber trachteten danach, wie sie ihn umbrächten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Als die Brüder davon hörten, geleiteten sie ihn hinab nach Cäsarea und entsandten ihn nach Tarsus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'So hatten nun die Gemeinden in ganz Judäa, Galiläa und Samaria Frieden, erbauten sich, und wandelten in der Furcht des Herrn und mehrten sich unter dem Beistand des Heiligen Geistes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Da begab sich, daß Petrus sie alle heimsuchte und auch zu den Heiligen kam, die in Lydda wohnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'Allda fand er einen Mann, mit Namen Aeneas, der acht Jahre gichtbrüchig auf dem Bette darniedergelegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'Und Petrus sprach zu ihm: Aeneas, Jesus Christus heilt dich, stehe auf und mache dir dein Bett zurecht! Und alsbald stand er auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'Und alle, die ihn Lydda und Saron wohnten, sahen ihn und bekehrten sich zum Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'Zu Joppe aber war eine Jüngerin mit Namen Tabitha, das verdolmetscht heißt Dorkas. Diese war voll guter Werke und Wohltätigkeit, die sie erwies.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Es begab sich aber in selbigen Tagen, daß sie erkrankte und starb. Da wuschen sie selbige und legten sie auf den Söller.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Da Lydda nahe bei Joppe war, sandten die Jünger auf die Nachricht, daß Petrus allda wäre, zwei Männer an ihn, mit der Bitte unverweilt zu ihnen herüberzukommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Petrus stand auf und ging mit ihnen. Als er ankam, führten sie ihn auf den Söller und alle Witwen umstanden ihn, weinten und zeigten ihm die Röcke und Gewänder, welche die Reh gemacht, während sie bei ihnen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Petrus hieß sie alle hinausgehen, kniete nieder und betete, und wandte sich dann zu der Leiche und sprach: Tabitha, stehe auf! Sie tat ihre Augen auf, und da sie den Petrus sah, setzte sie sich auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'Er gab ihr die Hand und richtete sie auf, rief die Heiligen und die Witwen herein und stellte sie lebend dar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'Und es ward bekannt in ganz Joppe, und viele glaubten an den Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Petrus aber blieb viele Tage in Joppe bei Simon, einem Gerber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Es war ein Mann zu Cäsarea, mit Namen Cornelius, ein Hauptmann von der sogenannten italischen Kohorte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'Fromm und gottesfürchtig mit seinem ganzen Hause, der dem Volke viele Wohltaten erwies und stets zu Gott betete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Dieser sah in einem Gesichte um die neunte Stunde des Tages offenbarlich einen Engel bei sich eintreten und zu ihm sprechen: Cornelius!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'Er aber sah ihn an, erschrak und sprach: Was ist es Herr? Er sprach zu ihm: Deine Gebete und Almosen sind hinaufgekommen zum Gedächtnis vor Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'Und nun sende Männer nach Joppe und entbiete zu dir Simon, der zubenannt wird Petrus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'Welcher ist zur Herberge bei einem Gerber Simon, dessen Haus am Meere liegt. Der wird dir sagen, was du tun sollst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Als der Engel, der mit ihm redete, hinwegegegangen war, rief er zwei seiner Knechte und einen gottesfürchtigen Kriegsknecht, von denen, die ihm aufwarteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'Und erzählte ihnen alles und entsandte sie gen Joppe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'Des anderen Tages, während sie auf dem Wege waren und der Stadt nahten, stieg Petrus hinauf auf den Söller, um zu beten, um die sechste Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Da ward er hungrig und wollte etwas essen; während sie aber zurichteten, fiel er in eine Entzückung,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'Und sah den Himmel aufgetan, und ein Gefäß zu ihm herabsinken, wie ein großes Linnentuch, das an den vier Enden gebunden war und auf den Boden hernieder gelassen ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'Darin waren allerlei vierfüßige Tiere der Erde und Gewild und Kriechtiere und Vögel des Himmels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'Und es geschah eine Stimme zu ihm: Stehe auf, Petrus, schlachte und iß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Petrus aber sprach: Nimmermehr, Herr! noch nie habe ich etwas Gemeines oder Unreines gegessen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'Und eine Stimme sprach zum andern Mal zu ihm: Was Gott hat rein gemacht, das achte du nicht für gemein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'Dies geschah zu drei Malen, und das Gefäß ward wieder gen Himmel emporgenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Als aber Petrus bei sich selbst nachsann, was wohl das Gesichte, das er gesehen, zu bedeuten hätte, siehe, da fragten die, so von Cornelius abgesandt waren, nach dem Hause Simons und standen vor dem Tor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'Riefen und erkundigten sich, ob Simon, mit dem Zunamen Petrus, allda zur Herberge wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Als Petrus immer noch über das Gesichte nachdachte, sprach der Geist zu ihm: Siehe, drei Männer fragen nach dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'So mache dich auf, steige hinab, und ziehe mit ihnen, und bedenke nicht lange, denn Ich habe sie gesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'Da stieg Petrus hinab zu den Männern, die Cornelius an ihn abgesendet hatte, und sprach: Siehe, ich bin es, nach dem ihr fraget; was ist die Sache, darum ihr hier seid?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Sie aber sprachen: Der Hauptmann Cornelius, ein gerechter und gottesfürchtiger Mann, der bei allem Volke der Juden ein gutes Zeugnis hat, ward von einem heiligen Engel angewiesen, dich in sein Haus rufen zu lassen, auf daß er Worte von dir höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Da rief er sie herein zu sich und bewirtete sie. Des andern Tages zog Petrus mit ihnen, und zwei der Brüder aus Joppe gingen mit ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'Am andern Tag kamen sie nach Cäsarea. Cornelius wartete auf sie und hatte seine Verwandten und vertrauten Freunde zusammengerufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'Als Petrus eintrat, kam ihm Cornelius entgegen, fiel ihm zu Füßen und betete ihn an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Petrus aber richtete ihn auf und sprach: Stehe auf! auch ich bin ein Mensch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'Als er sich mit ihm besprochen hatte, trat er ein und fand ihrer viele versammelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'Er sprach zu ihnen: Ihr wisset, daß es einem jüdischen Manne nicht erlaubt ist, sich einem Fremden zuzugesellen und Gemeinschaft mit ihm zu haben; aber mir hat Gott gezeigt, daß ich keinen Menschen sollte gemein oder unrein heißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Darum bin ich auch unweigerlich gekommen, als man mich beschied; ich frage nun, zu welchem Ende ihr mich beschieden habt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'Da sprach Cornelius: Bis zu dieser Stunde sind es vier Tage, daß ich fastete; und um die neunte Stunde betete ich in meinem Hause, und siehe, da stand ein Mann vor mir in glänzendem Gewand,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'Und sprach: Cornelius, dein Gebet ist erhört, und deiner Almosen ist gedacht worden vor Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'So sende nun nach Joppe und laß rufen Simon, mit dem Zunamen Petrus. Dieser ist zur Herberge im Hause des Gerbers Simon am Meer; wenn dieser kommt, so wird er dich berichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Da sandte ich von Stund an zu dir, und du hast wohlgetan, daß du gekommen bist; nun sind wir alle vor Gott hier gegenwärtig, zu hören alles, was dir von Gott ward aufgetragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Da tat Petrus seinen Mund auf und sprach: In Wahrheit erfahre ich nun, daß Gott die Person nicht ansieht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'Sondern unter allem Volk ein jeglicher, der Ihn fürchtet und recht tut, der ist Ihm wohlgefällig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'Das Wort nun, das Er den Söhnen Israels zugesendet hat, indem Er Frieden verkündete durch Jesus Christus:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Ihr wisset, was nach der Taufe, die Johannes predigte, durch das ganze jüdische Land geschehen ist, und in Galiläa seinen Anfang genommen hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'Wie Jesus von Nazareth, Den Gott mit dem Heiligen Geist und Wunderkraft gesalbt hat, umhergezogen ist, und hat wohlgetan, und alle gesund gemacht, die von dem Teufel überwältigt waren; denn Gott war mit Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'Und wir sind alle Zeugen dessen, was Er im Lande der Juden und in Jerusalem getan hat. Ihn haben sie zum Tode gebracht und an das Kreuz geheftet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Diesen hat Gott am dritten Tage auferweckt und Ihn lassen offenbar werden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'Nicht allem Volk, sondern uns, den Zeugen, die von Gott vorerwählt worden, uns, die wir mit Ihm gegessen und getrunken haben, nachdem Er von den Toten auferstanden war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'Und Er hat uns geboten, dem Volke zu predigen und bezeugen, daß Er ist von Gott verordnet zum Richter der Lebendigen und der Toten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Für Ihn zeugen alle Propheten, daß durch Seinen Namen jeder, der an Ihn glaubt, Vergebung der Sünden empfangen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Während Petrus noch diese Worte redete, fiel der Heilige Geist auf alle, die das Wort hörten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'Und es entsetzten sich die Gläubigen aus der Beschneidung, die mit Petrus gekommen waren, daß auch auf die Heiden die Gabe des Heiligen Geistes ausgegossen ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'Denn sie hörten sie mit Zungen reden und Gott lobpreisen. Da nahm Petrus wieder das Wort:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Mag auch jemand das Wasser vorenthalten, daß die nicht getauft werden, die, wie auch wir, den Heiligen Geist empfangen haben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'Und er befahl, sie zu taufen im Namen des Herrn. Sie baten ihn sodann, noch einige Tage zu bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Die Apostel und die Brüder in Judäa hörten, daß auch die Heiden das Wort Gottes angenommen hätten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Und als Petrus hinauf nach Jerusalem kam, stritten die aus der Beschneidung mit ihm und sagten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'Du bist zu Männern eingegangen, welche die Vorhaut haben, und hast gegessen mit ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Petrus aber hob an und berichtete ihnen den Verlauf der Dinge also:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Ich war in der Stadt Joppe im Gebet und sah in einer Entzückung ein Gesicht: ein Gefäß wie ein großes Linnentuch kam vom Himmel herab und ward an vier Enden niedergelassen und kam bis zu mir,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'Ich sah darauf hin, ward gewahr, und sah vierfüßige Tiere der Erde und Gewild und Kriechtiere und Gevögel des Himmels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Da hörte ich eine Stimme zu mir sprechen: Stehe auf, Petrus, schlachte und iß!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'Ich sprach aber: Nimmermehr, Herr, denn noch nie ist Gemeines oder Unreines in meinen Mund gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Zum zweitenmal aber kam eine Stimme vom Himmel: Was Gott rein gemacht, das mache du nicht gemein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'Dies geschah zu drei Malen; und alles ward wieder in den Himmel hinaufgezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'Und siehe, zur selben Stunde standen drei Männer vor dem Hause, darin ich war. Sie waren von Cäsarea an mich abgesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'Der Geist aber hieß mich ohne Bedenken mit ihnen gehen; es kamen aber mit mir auch die sechs Brüder da, und wir traten in das Haus des Mannes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'Und er sagte uns an, wie er einen Engel in seinem Hause stehen sah, und derselbe zu ihm sprach: Sende nach Joppe und rufe Simon, mit dem Zunamen Petrus, zu dir,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'Der wird Worte zu dir reden, durch die du mit deinem ganzen Haus wirst selig werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Als ich nun anfing zu reden, fiel der Heilige Geist auf sie, wie auch auf uns am Anfang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Da gedachte ich an das Wort des Herrn, das Er sprach: Johannes hat mit Wasser getauft, ihr aber sollt mit dem Heiligen Geiste getauft werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'So nun Gott ihnen die gleiche Gabe verlieh, wie auch uns, die an den Herrn Jesus Christus glaubten, wie hätte ich vermocht, Gott zu wehren?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Als sie diese Worte hörten, gaben sie sich zufrieden, lobten Gott und sprachen: So hat denn Gott auch den Heiden die Buße zum Leben gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Die nun, welche sich zerstreut hatten wegen der Verfolgung, die sich über Stephanus erhob, zogen umher bis Phönizien, Zypern und Antiochia, und trugen niemand, als Juden, das Wort vor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Es waren aber etliche unter ihnen, Männer aus Zypern und Cyrene, die nach Antiochia kamen und auch zu den Griechen redeten und die Heilsbotschaft vom Herrn Jesus verkündeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'Und die Hand des Herrn war mit ihnen, und eine große Zahl ward gläubig und bekehrte sich zum Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'Es kam aber die Rede davon der Gemeinde in Jerusalem zu Ohren, und sie sandten Barnabas ab, daß er bis nach Antiochien zöge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Als er dahin kam und die Gnade Gottes sah, ward er erfreut, und ermahnte alle, mit Festigkeit des Herzens beim Herrn zu verharren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Denn er war ein wackerer Mann und voll Heiligen Geistes und Glaubens, und eine große Menge ward dem Herrn zugetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Von da ging er aus gen Tarsus, um Saul aufzusuchen; und da er ihn gefunden, führte er ihn gen Antiochia.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Ein ganzes Jahr blieben sie mit der Gemeinde zusammen, lehrten viel Volk, und brachten es dahin, daß die Jünger in Antiochia zuerst Christen genannt wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'In selbigen Tagen aber kamen Propheten von Jerusalem herab nach Antiochien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'Einer von ihnen, mit Namen Agabus, trat auf und deutete durch den Geist, daß über alles Land eine große Teuerung kommen würde, die auch eintrat unter Claudius.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Von den Jüngern aber beschloß ein jeder, je nach seinem Vermögen eine Unterstützung zu senden den Brüdern, die in Judäa wohnten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'Was sie auch taten, indem sie solche durch Barnabas und Saulus absendeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'Um selbige Zeit ließ der König Herodes Hand an einige von der Gemeinde legen und sie peinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'Den Jakobus aber, des Johannes Bruder, ließ er mit dem Schwert hinrichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'Und da er sah, daß es den Juden gefiel, fuhr er fort und ließ Petrus in Verhaft nehmen. - Es waren gerade die Tage der ungesäuerten Brote.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'Er griff ihn, legte ihn ins Gefängnis und überantwortete ihn einer vierfachen Wache von Kriegsknechten, indem er ihn nach dem Osterfest dem Volk vorführen wollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Petrus ward in Gewahrsam gehalten, die Gemeinde aber betete inbrünstig zu Gott für ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Als aber Herodes ihn eben vorführen wollte, schlief Petrus in selbiger Nacht, an zwei Ketten gelegt, zwischen zwei Kriegsknechten, auch hielten Hüter Wache vor der Tür des Gefängnisses.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'Und siehe, ein Engel des Herrn erschien, und ein Licht leuchtete in dem Gemach. Er schlug Petrus an die Seite, weckte ihn auf und sprach: Mache dich auf in Eile! und es fielen die Ketten ihm von den Händen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Und der Engel sprach zu ihm: Umgürte dich und binde die Sohlen unter! Und er tat also; und er sprach zu ihm: Wirf deinen Mantel um und folge mir!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'Er ging hinaus und folgte ihm, wußte aber nicht, daß ihm in Wirklichkeit so durch den Engel geschah, sondern meinte, es sei ein Traumgesicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Sie gingen durch die erste und zweite Wache und gelangten an das eiserne Tor, das nach der Stadt führte, das öffnete sich ihnen von selbst; und sie traten hinaus und gingen eine Gasse weit, und alsbald entwich der Engel von ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'Als nun Petrus zu sich kam, sprach er: Nun weiß ich wahrhaftig, daß der Herr Seinen Engel gesandt und mich aus der Hand des Herodes und aus allem Warten des Volkes der Juden gerettet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'Und als er sich so besann, kam er an das Haus der Maria, der Mutter des Johannes, mit dem Zunamen Markus, wo viele beisammen waren und beteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Als aber Petrus an das Hoftor klopfte, trat eine Magd mit Namen Rhode herzu, um zu hören, wer es sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'Und da sie die Stimme des Petrus erkannte, tat sie vor Freude das Tor nicht auf, lief hinein und verkündete, Petrus stünde vor dem Tor.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Sie aber sprachen zu ihr: Du bist von Sinnen. Sie aber bestand darauf, es sei also. Da sagten sie: Es ist sein Engel!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'Petrus aber fuhr fort zu klopfen; da taten sie auf und waren außer sich vor Erstaunen, als sie ihn vor sich sahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Er aber winkte ihnen mit der Hand, zu schweigen, und erzählte ihnen, wie ihn der Herr aus dem Gefängnis geführt hätte, und sprach: Verkündet dies dem Jakobus und den Brüdern! Er entfernte sich und begab sich an einen anderen Ort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Als es Tag ward, war kein geringer Schrecken unter den Kriegsknechten, wie es doch mit Petrus ergangen wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Als Herodes nach ihm sandte und man ihn nicht fand, hielt er Gericht über die Wachen, und ließ sie zum Tode führen, und begab sich von Judäa nach Cäsarea und verweilte allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Er hatte aber einen Groll wider die Tyrier und Sidonier; diese jedoch erschienen einmütig vor ihm, brachten Blastus, des Königs Kämmerer, auf ihre Seite, und baten um Frieden, weil ihr Land sich von dem des Königs nährte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'Am anberaumten Tage erschien Herodes im königlichen Gewand und setzte sich auf den Richtstuhl und hielt eine Anrede an sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Da rief das Volk: Das ist eines Gottes Stimme und nicht eines Menschen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Da schlug ihn alsbald der Engel des Herrn, dafür, daß er nicht Gott die Ehre gab; er ward von den Würmern gefressen und verschied.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'Das Wort Gottes aber nahm zu und mehrte sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnabas aber und Saulus kehrten, nachdem sie die Handreichung ausgerichtet, zurück nach Jerusalem und nahmen mit sich Johannes, der den Zunamen Markus führt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Es waren aber in Antiochia in der dortigen Gemeinde Propheten und Lehrer, Barnabas und Simeon, mit dem Zunamen Niger, Lucius aus Cyrene und Manahen, Milchbruder des Vierfürsten Herodes, und Saulus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Da sie aber dem Herrn dienten und fasteten, sprach der Heilige Geist zu ihnen: Sondert mir Barnabas und Saulus zu dem Werk aus, für das ich sie berufen habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Da fasteten und beteten sie und legten ihnen die Hände auf und entließen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Diese nun, vom Heiligen Geist ausgesandt, kamen hinab nach Seleucia und fuhren von da nach Zypern ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'In Salamis angekommen, predigten sie das Wort Gottes in den Synagogen der Juden und hatten den Johannes als Gehilfen mit sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'Sie durchzogen die ganze Insel bis nach Paphos, wo sie einen Zauberer und falschen Propheten fanden, der ein Jude war und der Barjesus hieß,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'Der war bei dem Proconsul Sergius Paulus, einem verständigen Mann. Dieser ließ Barnabas und Saulus vor sich rufen und begehrte das Wort Gottes zu hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Es widerstand ihnen aber der Zauberer Elymas, denn so wird dessen Name verdolmetscht, und suchte den Statthalter vom Glauben abzuwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Saulus aber, der auch Paulus heißt, vom Heiligen Geist erfüllt, schaute ihn an,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'Und sprach: O du, voll aller Arglist und Schalkheit, Kind des Teufels, Feind aller Gerechtigkeit, wirst du nicht aufhören, die geraden Wege des Herrn zu verkehren?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'Und siehe, die Hand des Herrn ist über dir und du sollst blind sein und die Sonne nicht schauen eine Zeitlang. Und von Stund an fiel auf ihn Dunkelheit und Finsternis, und er tappte umher und suchte Handleiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Als der Statthalter sah, was geschehen war, glaubte er und war von Staunen erfüllt über die Lehre des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Paulus aber, und die mit ihm waren, schifften sich von Paphos ein und kamen nach Perge in Pamphylien. Johannes aber schied von ihnen und kehrte zurück nach Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Sie aber zogen von Perge weiter und gelangten nach Antiochia in Pisidien und begaben sich am Sabbathtage in die Synagoge und setzten sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Nach Lesung des Gesetzes und der Propheten ließen ihnen die Vorsteher der Synagoge sagen: Männer, Brüder, habt ihr ein Wort der Ermahnung an das Volk, so sprecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Da stand Paulus auf, winkte mit der Hand und sprach: Männer von Israel, und die ihr Gott fürchtet, höret zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Der Gott dieses Volkes hat unsere Väter erwählt und das Volk während ihres Aufenthaltes in Ägyptenland erhöht und mit hohem Arm sie von da ausgeführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'Und hat sie bei vierzig Jahren gepflegt und ernährt in der Wüste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'Und nachdem Er sieben Völker im Lande Kanaan vertilgt, gab Er ihnen ihr Land nach dem Los zum Erbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'Und danach gab Er ihnen bei vierhundertfünfzig Jahren Richter bis auf den Propheten Samuel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'Von da an verlangten sie einen König, und Gott gab ihnen Saul, den Sohn von Kis, einen Mann aus dem Stamme Benjamin, vierzig Jahre lang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'Und nachdem Er diesen weggetan, stellte Er für sie David als König auf und zeugte für ihn: Ich habe David, den Sohn Jesses gefunden, einen Mann nach Meinem Herzen, der allen Meinen Willen tun soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Aus dessen Samen ließ Gott nach der Verheißung Jesus zum Retter für Israel kommen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'Nachdem Johannes vor Seinem Auftreten dem ganzen Volke Israel die Taufe der Buße gepredigt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Wie nun Johannes seinen Lauf erfüllte, sprach er: Für wen haltet ihr mich? Ich bin es nicht; aber siehe, es kommt nach mir Einer, Dem ich nicht wert bin, den Schuhriemen aufzulösen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Männer, Brüder, Söhne vom Geschlecht Abrahams, und die unter euch Gott fürchten, an euch ist das Wort dieses Heils gesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Denn die in Jerusalem wohnen und ihre Oberen haben Ihn verkannt und damit die Stimmen der Propheten, die jeden Sabbath vorgelesen werden, durch ihre Verurteilung in Erfüllung gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'Obwohl sie keine Schuld des Todes an Ihm fanden, verlangten sie von Pilatus, daß Er zum Tode gebracht würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'Als sie alles, was von Ihm geschrieben steht, erfüllt hatten, nahmen sie Ihn vom Kreuz und legten Ihn in das Grab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'Gott aber hat Ihn von den Toten auferweckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'Er ist viele Tage erschienen denen, die mit Ihm aus Galiläa nach Jerusalem hinaufgezogen und nun Seine Zeugen sind vor dem Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'Und auch wir verkünden euch die frohe Botschaft der Verheißung, die den Vätern geworden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'Daß solche Gott uns, deren Kindern, durch die Auferweckung Jesu erfüllt hat, wie im zweiten Psalm geschrieben steht: Mein Sohn bist Du, Ich habe heute Dich gezeugt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Daß Er Ihn aber von den Toten auferweckt, und Er nimmer sollte zur Verwesung wiederkehren, hat Er mit den Worten ausgesprochen: Das Heilige Davids, das Unverbrüchliche will Ich euch geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Deshalb sagt Er auch an einer anderen Stelle: Du wirst nicht zulassen, daß Dein Heiliger die Verwesung sehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'Denn David, da er zu seiner Zeit dem Willen Gottes gedient hatte, ist entschlafen und zu seinen Vätern versammelt worden, und hat die Verwesung gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Er aber, Den Gott hat auferweckt, hat die Verwesung nicht gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'So sei euch denn kundgetan, Männer und Brüder, daß durch Diesen euch Vergebung der Sünden verkündigt wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'Und von allem, davon ihr im Gesetz Moses nicht konntet gerechtfertigt werden, wird in Diesem ein jeglicher, der da glaubt, gerechtfertigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Seht nun zu, daß nicht über euch komme, was in den Propheten gesagt worden ist:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, 'Seht, ihr Verächter, erstaunt und werdet zuschanden; denn Ich tue ein Werk in euren Tagen, an das ihr nicht glauben werdet, so es euch einer erzählt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Als nun die Juden aus der Synagoge kamen, baten die Heiden, daß ihnen auf den folgenden Sabbath diese Worte geredet würden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'Als nun die Synagoge auseinanderging, folgten viele Juden und gottesfürchtige Proselyten Paulus und Barnabas. Diese redeten zu ihnen und vermahnten sie, in der Gnade Gottes zu beharren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'Und am folgenden Sabbath versammelte sich beinahe die ganze Stadt, um das Wort Gottes zu hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Da nun die Juden die Menge Volks sahen, wurden sie voll Neides und widersprachen dem, was von Paulus gesagt wurde, widersprachen und lästerten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'Paulus aber und Barnabas erklärten frei öffentlich: Zu euch mußte zuerst das Wort Gottes geredet werden; nun ihr es aber von euch stoßt, und euch selbst nicht würdig erachtet des ewigen Lebens, siehe, so wenden wir uns zu den Heiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Denn also hat uns der Herr geboten: Ich habe Dich zum Licht für die Heiden gesetzt, auf daß Du zum Heile werdest bis an das Ende der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Da dies die Heiden hörten, freuten sie sich und priesen das Wort des Herrn und wurden gläubig alle, so bestimmt waren zum ewigen Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Und des Herrn Wort verbreitete sich durch das ganze Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Die Juden aber reizten auf die frommen und ehrbaren Weiber und die Oberen der Stadt und erregten eine Verfolgung wider Paulus und Barnabas, und stießen sie zu ihren Grenzen hinaus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'Sie aber schüttelten den Staub von ihren Füßen über sie und kamen nach Ikonium.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Die Jünger aber wurden voll Freude und Heiligen Geistes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Es geschah nun zu Ikonium, daß sie in der Synagoge der Juden zusammenkamen und also redeten, daß eine große Menge Juden und Griechen gläubig wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Die ungläubigen Juden aber reizten und erbitterten die Gemüter der Heiden wider die Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Sie blieben allda geraume Zeit und predigten im Vertrauen auf den Herrn, Der das Wort Seiner Gnade bezeugte, indem Er durch ihre Hände Zeichen und Wunder geschehen ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Die Menge der Stadt aber teilte sich; und die einen hielten es mit den Juden, die anderen mit den Aposteln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Als sich nun ein Sturm erhob von seiten der Heiden und der Juden mit ihren Oberen, um sie zu mißhandeln und zu steinigen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'Wurden sie dessen inne und flüchteten in die Städte Lykaoniens, gen Lystra und Derbe und die Umgegend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'Und sie predigten daselbst das Evangelium.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'In Lystra saß ein Mann, seiner Füße nicht mächtig und lahm von Mutterleibe, der noch nie gegangen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Der hörte Paulus reden, und als er ihn anblickte und ihm ansah, daß er Glauben hatte, ihm könnte geholfen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'Sprach er mit lauter Stimme: Stehe aufrecht auf deine Füße! und er sprang auf und wandelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Da aber die Menge sah, was Paulus getan hatte, erhoben sie ihre Stimme und riefen auf lykaonisch: Die Götter sind in Menschengestalt zu uns herabgekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'Und nannten Barnabas Zeus, Paulus aber Hermes, weil er das Wort führte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'Der Priester des Zeus aber, der vor der Stadt war, brachte Stiere und Kränze an das Tor und wollte mit der Menge opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Da die Apostel Barnabas und Paulus es hörten, zerrissen sie ihre Kleider, sprangen unter die Menge und riefen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'Und sprachen: Männer, was macht ihr da? Auch wir sind sterbliche Menschen, wie ihr, und ermahnen euch, von diesen falschen Dingen euch abzukehren zu dem lebendigen Gott, Der Himmel und Erde und Meer und alles, was darin ist, geschaffen hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'Der in vergangenen Zeiten alle Völker ihre eigenen Wege wandeln ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Obwohl Er Sich nicht unbezeugt gelassen, indem Er Gutes tat, uns vom Himmel Regen und fruchtbare Zeiten gab und unsere Herzen mit reichlicher Speise und Freude erquickte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'Kaum konnten sie mit diesen Worten die Menge abhalten, ihnen zu opfern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Es kamen aber aus Antiochia und Ikonium Juden, die das Volk überredeten, den Paulus steinigten, und ihn, da sie meinten, er wäre tot, zur Stadt hinausschleppten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Da ihn aber die Jünger umringten, stand er auf, und ging in die Stadt. Des anderen Tages aber begab er sich mit Barnabas gen Derbe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'Und nachdem sie selbiger Stadt das Evangelium verkündigt und viele zu Jüngern gemacht hatten, kehrten sie wieder um nach Lystra, Ikonium und Antiochia;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'Stärkten die Gemüter der Jünger und ermahnten sie, im Glauben zu beharren, und daß wir durch viele Trübsale in das Reich Gottes eingehen müßten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'Sie bestellten ihnen in den Gemeinden Älteste, beteten und fasteten und empfahlen sie dem Herrn, an Den sie gläubig geworden waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'Sie zogen sodann durch Pisidien und kamen nach Pamphylien;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'Redeten in Perge das Wort und begaben sich hinab nach Attalia.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'Und von dannen schifften sie nach Antiochia, von wo sie für das Werk, das sie ausgerichtet hatten, der Gnade Gottes waren übergeben worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Als sie da ankamen, versammelten sie die Gemeinde und verkündeten, wie viel Gott mit ihnen getan, und wie Er den Heiden die Tür zum Glauben aufgetan hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'Sie verweilten geraume Zeit allda bei den Jüngern..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'Es kamen etliche herab von Judäa und wollten die Brüder lehren: Wenn ihr euch nicht nach dem Gesetz Moses beschneiden lasset, so könnt ihr nicht selig werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Da sich nun nicht geringe Unruhe erhob, und Paulus und Barnabas mit ihnen in Streit gerieten, beschloß man, Paulus und Barnabas und einige andere aus ihrer Mitte wegen dieser Streitfrage an die Apostel und Ältesten nach Jerusalem abzuordnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Die Gemeinde gab ihnen das Geleit, und sie zogen durch Phönizien und Samarien, erzählten von der Bekehrung der Heiden und erregten große Freude bei allen Brüdern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Als sie nach Jerusalem kamen, wurden sie von der Gemeinde und den Aposteln und Ältesten empfangen und verkündeten, wie viel Gott mit ihnen ausgerichtet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Da traten etliche auf von der Sekte der Pharisäer, die gläubig geworden waren, und sagten: Man muß sie beschneiden und ihnen anbefehlen, Mose Gesetz zu halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'Die Apostel und Ältesten aber traten nun zusammen, um die Sache in Betrachtung zu nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Da nun viel darüber gestritten wurde, trat Petrus auf und sprach zu ihnen: Männer, Brüder, ihr wißt, daß vor längerer Zeit Gott unter uns verordnet hat, daß durch meinen Mund die Heiden das Wort des Evangeliums hören und gläubig werden sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'Und Gott, der Herzenskündiger, zeugte für sie, indem Er ihnen, wie uns, den Heiligen Geist gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'Und hat nicht zwischen uns und ihnen unterschieden, indem Er durch den Glauben ihre Herzen gereinigt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Was versucht ihr nun Gott, daß ihr dem Nacken der Jünger ein Joch wollt auflegen, das weder unsere Väter noch wir zu tragen vermochten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Vielmehr glauben wir, daß wir durch die Gnade des Herrn Jesus, so wie jene, selig werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Da schwieg die ganze Versammlung und hörte, wie Barnabas und Paulus erzählten, wie viel Zeichen und Wunder Gott durch sie unter den Heiden getan hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Nachdem sie ausgeredet hatten, hob Jakobus an: Männer, Brüder, hört mir zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simon hat erzählt, wie es Gott zuerst gefallen hat, aus den Heiden ein Volk auf Seinen Namen anzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'Auch stimmen damit überein die Worte der Propheten, wie denn geschrieben steht:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, 'Danach will Ich wiederkommen und aufbauen das zerfallene Zelt Davids und will seine Trümmer wieder aufbauen und dasselbe aufrichten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'Auf daß die übrigen Menschen den Herrn suchen, sowie alle die Völkerschaften, die nach Meinem Namen werden genannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'So spricht der Herr, Der alles dies kund tut von Ewigkeit her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Darum halte ich dafür, daß man denen aus der Heidenwelt, die sich zu Gott bekehren, keine Beschwerde mache;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'Sondern ihnen schreibe, sie sollten sich der Befleckungen der Götzenmahle, der Hurerei, des Erstickten und des Blutes enthalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Denn Moses hat von alten Zeiten her in jeder Stadt solche, die ihn verkündigen und wird an jedem Sabbath in den Synagogen gelesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Hierauf fanden die Apostel und die Ältesten samt der ganzen Gemeinde für gut, aus ihrer Mitte Männer zu wählen und sie mit Paulus und Barnabas nach Antiochia zu senden, nämlich Judas, mit dem Zunamen Barsabas, und Silas, Männer, die bei den Brüdern in Ansehen standen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'Und schrieben ihnen durch sie also: Die Apostel und die Ältesten und die Brüder entbieten den Brüdern aus dem Heidentum in Antiochia, Syrien und Cilicien ihren Gruß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Weil wir gehört haben, daß etliche der Unseren hinausgingen und euch in Unruhe versetzten und mit Lehren eure Gemüter verwirrten und sagten: Ihr müßtet euch beschneiden lassen und das Gesetz halten, ohne daß wir ihnen Auftrag gegeben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'Hat es uns gut gedünkt, einmütig versammelt, Männer zu erwählen und an euch zu senden mit unseren Geliebten Barnabas und Paulus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'Männer, die dem Namen unseres Herrn Jesus Christus ihr Leben geweiht haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'So haben wir nun Judas und Silas abgesandt, die auch mündlich dasselbe verkündigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Denn es hat dem Heiligen Geist und uns gefallen, euch keine weitere Bürde aufzulegen, als nur die drei notwendigen Stücke:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'Daß ihr euch enthaltet der Götzenmahle, des Blutes, des Erstickten und der Hurerei. Wenn ihr euch deren enthaltet, so wird es euch wohlergehen. Gehabt euch wohl!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Als diese abgefertigt waren, kamen sie nach Antiochia, versammelten die Menge und übergaben den Brief.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Als sie solchen lasen, freuten sie sich über den Trost.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'Judas und Silas, die selbst Propheten waren, ermahnten die Brüder mit vielen Reden und bestärkten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'Als sie eine Zeitlang dort sich aufgehalten, wurden sie von den Brüdern mit Segenswünschen entlassen an die Apostel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, 'Silas zog vor, dort zu bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'Paulus aber und Barnabas verweilten in Antiochia, lehrten und predigten samt vielen anderen das Wort des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Nach einiger Zeit sagte Paulus zu Barnabas: Wir wollen umkehren und von Stadt zu Stadt, wo wir das Wort des Herrn verkündigt haben, nachsehen, wie es um die Brüder steht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnabas aber war Rats, sie sollten auch Johannes, mit dem Zunamen Markus, mit sich nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Paulus aber achtete es für besser, ihn, der in Pamphylien von ihnen gewichen und nicht mit ihnen zum Werke gezogen, nicht mitzunehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'Sie gerieten scharf aneinander, also, daß sie sich voneinander trennten, und Barnabas Markus zu sich nahm und nach Zypern schiffte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'Paulus aber wählte Silas und zog aus, von den Brüdern der Gnade Gottes empfohlen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'Er nahm seinen Weg durch Syrien und Cilicien und bestärkte die Gemeinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Er kam hinab gen Derbe und Lystra, und siehe, daselbst war ein Jünger mit Namen Timotheus, der Sohn eines jüdischen gläubigen Weibes, hatte aber einen Griechen zum Vater.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'Der hatte ein gutes Zeugnis von den Brüdern in Lystra und Ikonium.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Von dem wollte Paulus, daß er mitzöge, und nahm und beschnitt ihn, wegen der Juden, die an selbigen Orten waren; denn alle wußten, daß sein Vater ein Grieche war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Wie sie nun durch die Städte zogen, teilten sie ihnen zur Beachtung die Verordnungen mit, die von den Aposteln und Ältesten in Jerusalem festgesetzt worden waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Die Gemeinden wurden im Glauben bestärkt und nahmen täglich zu an der Zahl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'Da sie aber Phrygien und das galatische Land durchzogen hatten, wehrte ihnen der Heilige Geist, das Wort Gottes in Asien zu verkündigen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'Als sie gen Mysien kamen versuchten sie nach Bithynien zu ziehen, aber auch dies ließ ihnen der Geist nicht zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'So gingen sie an Mysien vorbei und wandten sich nach Troas hinab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'Und Nachts erschien dem Paulus ein Gesicht: Ein mazedonischer Mann stand da, bat ihn und sprach: Komm nach Mazedonien hinüber und hilf uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'So wie er das Gesicht gesehen, trachteten wir alsbald nach Mazedonien zu kommen, indem wir schlossen, daß der Herr uns berufen hätte, denen dort das Evangelium zu predigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Wir fuhren denn von Troas ab und gelangten geraden Weges nach Samothrace, am folgenden Tage nach Neapolis,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'Und von da nach Philippi, das eine Hauptstadt Teils von Mazedonien und eine Pflanzstadt ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'Wir verweilten in selbiger Stadt einige Tage; am Sabbathtage aber gingen wir hinaus vor die Stadt an den Fluß, da man zu beten pflegte, setzten uns und redeten zu den Weibern, die dort waren zusammengekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'Und ein Weib mit Namen Lydia, eine Purpurhändlerin aus der Stadt Thyatira, die Gott fürchtete, hörte zu; und ihr tat der Herr das Herz auf, daß sie dem, was Paulus redete, Gehör gab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Als aber sie und ihr Haus getauft ward, bat sie und sprach: Wenn ihr erachtet habt, daß ich an den Herrn gläubig bin, so tretet in mein Haus ein und bleibt allda; und sie nötigte uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Es geschah aber, da wir zum Gebet gingen, daß uns eine Magd begegnete, die einen Wahrsagergeist hatte und ihren Herren durch Wahrsagen großen Gewinn brachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Diese folgte Paulus und uns nach und schrie: Diese Menschen sind Knechte des höchsten Gottes, die euch den Weg des Heils verkündigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'Dies tat sie viele Tage. Dem Paulus war das lästig, und er wandte sich um und sprach zu dem Geiste: Ich gebiete dir im Namen Jesu Christi, daß du von ihr ausfahrst. Und er fuhr aus von ihr zur selbigen Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Da aber ihre Herren sahen, daß ihnen ihre Hoffnung auf Gewinn entging, ergriffen sie Paulus und Silas und schleppten sie auf den Markplatz vor die Oberen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'Und stellten sie vor die Stadtrichter und sagten: Diese Menschen stiften Unruhen in unserer Stadt und sind Juden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'Und verkündigen Gebräuche, die uns nicht geziemt anzunehmen, noch auszuüben, weil wir Römer sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'Auch stand das Volk wider sie auf, und die Stadtrichter ließen ihnen die Kleider abreißen und sie geißeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'Und nachdem sie ihnen viele Streiche gegeben, warfen sie dieselben ins Gefängnis und befahlen dem Kerkermeister, daß er sie wohl bewahrete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Als dieser solchen Befehl erhielt, führte er sie in das innerste Gefängnis und legte ihre Füße in den Stock.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Um Mitternacht aber beteten Paulus und Silas und lobpriesen Gott, und es hörten ihnen die Gefangenen zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Da entstand plötzlich ein gewaltiges Erdbeben, so daß die Grundfesten des Gefängnisses erschüttert wurden, und alsbald sprangen alle Türen auf, und aller Bande entfielen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Der Kerkermeister fuhr aus dem Schlafe auf, und da er die Türen des Gefängnisses offen sah, zog er sein Schwert und wollte sich entleiben, indem er meinte, die Gefangenen wären entflohen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Paulus aber rief mit lauter Stimme: Tue dir kein Leid, denn wir sind alle hier!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'Darauf ließ er Lichter bringen, sprang hinein und fiel Paulus und Silas zitternd zu Füßen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'Und führte sie heraus und sprach: Ihr Herren, was muß ich tun, daß ich selig werde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Sie antworteten: Glaube an den Herrn Jesus Christus, so wirst du und dein Haus selig werden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'Und sie redeten zu ihm und allen, die in seinem Hause waren, das Wort des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'Und er nahm sie zur selben Stunde in der Nacht zu sich und wusch ihnen die Striemen ab, und ließ sich alsbald mit seinem ganzen Hause taufen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'Und er führte sie in sein Haus, bereitete ihnen ein Mahl und freute sich mit seinem ganzen Hause, daß er an Gott gläubig geworden war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Als es Tag ward, schickten die Stadtrichter die Gerichtsdiener und ließen sagen: Laß die Leute los.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Da verkündete der Kerkermeister dem Paulus diese Worte: Die Stadtrichter haben hergesandt, daß ihr sollt losgelassen werden; nun könnt ihr ausziehen und im Frieden eure Wege gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Paulus aber ließ ihnen sagen: Man hat uns, die wir Römer sind, ohne Verhör öffentlich gegeißelt, in das Gefängnis geworfen, und will uns nun heimlich fortschicken; nicht also, sie mögen selbst kommen und uns hinausführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Die Gerichtsdiener hinterbrachten den Stadtrichtern diese Worte, und diese gerieten in Furcht, da sie hörten, daß sie Römer wären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'Sie kamen und redeten ihnen zu, führten sie heraus und baten sie, die Stadt zu verlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Da traten sie aus dem Gefängnis und begaben sich zu der Lydia, sahen die Brüder, ermahnten sie und zogen aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'Sie nahmen ihren Weg über Amphipolis und Apollonia und kamen nach Thessalonich, wo die Synagoge der Juden war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'Paulus ging nach seiner Gewohnheit zu ihnen und besprach sich drei Sabbathe mit ihnen aus den Schriften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'Er erschloß sie ihnen und legte ihnen dar, daß der Christus mußte leiden und von den Toten auferstehen, und daß Dieser ist eben der Jesus Christus, Den ich euch verkündige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'Und etliche unter ihnen ließen sich überzeugen, und hielten sich zu Paulus und Silas, auch eine große Menge der gottesfürchtigen Griechen, und der vornehmsten Frauen nicht wenige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Die ungläubigen Juden aber, voll Neides, nahmen etliche schlechte Leute vom Marktpöbel zu sich, erregten einen Auflauf und setzten die Stadt in Bewegung. Sie zogen vor Jasons Haus, und suchten sie unter die Menge zu führen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Da sie sie aber nicht fanden, schleppten sie Jason und etliche Brüder vor die Stadtober- sten und schrien: Diese, die den ganzen Erdkreis aufregen, sind auch hierher gekommen, und sie hat Jason zur Herberge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'Diese alle handeln den Verordnungen des Kaisers entgegen, und sagen: Ein anderer -Jesus - sei König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'So brachten sie das Volk und die Stadtobersten, die solches hörten, in Aufregung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'Nachdem sie aber von Jason und den anderen Sicherheit genommen, entließen sie dieselben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Die Brüder aber entließen alsbald in der Nacht Paulus und Silas gen Beröa. Als sie dort angekommen waren, begaben sie sich in die Synagoge der Juden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Diese waren besser gesinnt, als die in Thessalonich, und nahmen das Wort mit aller Bereitwilligkeit auf und forschten täglich in den Schriften, ob es sich also verhielte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'Viele von ihnen wurden gläubig, und auch von den griechischen ehrbaren Frauen und Männern nicht wenige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Als aber die Juden in Thessalonich erfuhren, daß auch in Beröa das Wort Gottes von Paulus verkündigt wurde, kamen sie und bewegten auch dort das Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Die Brüder aber schafften Paulus alsbald fort an das Meer; Silas aber und Timotheus blieben allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Die aber Paulus geleiteten, führten ihn bis nach Athen und gingen wieder ab, mit dem Auftrag an Silas und Timotheus, daß sie ehestens zu ihm kommen sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Während Paulus sie in Athen erwartete, ergrimmte sein Geist in ihm, wie er die Stadt so voller Götzenbilder sah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Und er redete nun in der Synagoge zu den Juden und Gottesfürchtigen, und auf dem Markte den ganzen Tag zu denen, die sich herzufanden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'Etliche aber der Epikureer und der stoischen Philosophen stritten sich mit ihm, und einige sagten: Was will doch dieser Schwätzer da; andere: Er will fremde Götter bei uns ankündigen; weil er ihnen von Jesus und der Auferstehung predigte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'Sie aber nahmen ihn und führten ihn auf den Areopag und sprachen: Können wir erfahren, was das für eine neue Lehre ist, die du vorträgst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Denn du bringst ganz neue Dinge vor unsere Ohren, und wir wollen hören, wie es sich damit verhält.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Alle Athener und auch die Fremden, die sich allda aufhielten, hatten für nichts mehr Sinn, als von etwas Neuem zu reden oder zu hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Paulus trat denn mitten auf dem Areopag auf und sprach: Ihr Männer von Athen, ich sehe, daß ihr vor allen anderen gottesfürchtig seid;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Denn wie ich so herumging und eure Götterbilder ansah, traf ich auch auf einen Altar mit der Inschrift: Dem unbekannten Gott. Diesen nun, Den ihr, ohne Ihn zu kennen, verehrt, verkündige ich euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Der Gott, Der die Welt und alles darin geschaffen hat, ist der Herr des Himmels und der Erde, wohnt nicht in Tempeln, mit Händen gemacht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'Auch wird Er nicht von Menschenhänden bedient, als bedürfte Er jemandes, da Er Selbst allen Leben, Odem und alle Dinge gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'Auch ließ Er, aus einem Blute entsprossen, das Geschlecht aller Menschen auf dem ganzen Erdboden wohnen, indem Er bestimmte Zeiten und die Grenzen ihrer Wohnsitze festsetzte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'Auf daß sie Gott suchten, ob sie Ihn nicht irgendwo mit Händen greifen und finden könnten, obwohl Er von keinem unter uns ferne ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Denn in Ihm leben, weben und sind wir, wie auch etliche eurer Dichter gesagt haben: Wir sind Seines Geschlechtes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'So wir nun vom Geschlechte Gottes sind, sollten wir nicht meinen, daß die Gottheit dem Gold, Silber oder Stein, einem Meißelbild der Kunst oder menschlicher Einbildung gleiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Die Zeiten der Unwissenheit übersehend, kündigt Gott jetzt allen Menschen an, daß sie Buße tun sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'Darum hat Er einen Tag gesetzt, an dem Er den ganzen Erdkreis mit Gerechtigkeit richten will, durch einen Mann, den Er verordnet und vor allen beglaubigt hat, da Er Ihn von den Toten auferweckte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Da sie von der Auferstehung der Toten hörten, spotteten einige; andere aber sagten: Wir wollen dich darüber ein anderes Mal weiter hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'Und so trat denn Paulus aus ihrer Mitte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'Einige Männer aber hielten sich zu ihm und glaubten, darunter auch der Areopagite Dionysius, und eine Frau, mit Namen Damaris, und andere mit ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Hierauf schied Paulus von Athen und kam nach Korinth;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'Und fand allda einen Juden, mit Namen Aquila, aus Pontus gebürtig, der kurz zuvor mit seinem Weibe Priscilla aus Italien gekommen war, weil Claudius alle Juden aus Rom ausgewiesen hatte. Zu diesen ging er ein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'Und weil er gleichen Handwerks war, blieb er bei ihnen und arbeitete; denn sie waren ihres Handwerks Zeltmacher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'Jeden Sabbath aber besprach er sich in der Synagoge mit Juden und Griechen und überzeugte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Als aber Silas und Timotheus aus Mazedonien kamen, ward Paulus im Geiste von dem Worte gedrungen, und bezeugte eifrig Jesus Christus vor den Juden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Da sie sich ihm aber widersetzten und lästerten, schüttelte er seine Kleider aus und sprach zu ihnen: Euer Blut komme auf euer Haupt! ich bin rein. Von nun an wende ich mich zu den Heiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'Und er wandte sich von dannen, und kam in das Haus eines Mannes, mit Namen Justus, der gottesfürchtig war und dessen Haus an die Synagoge stieß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Crispus aber, der Vorsteher der Synagoge, glaubte mit seinem ganzen Haus an den Herrn, und viele Korinther, die ihn hörten, wurden gläubig, und ließen sich taufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Der Herr aber sprach in einem Gesicht in der Nacht zu Paulus: Fürchte dich nicht, sondern rede und schweige nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'Denn Ich bin mit dir, niemand soll sich an dir vergreifen und dir ein Leid zufügen; denn Ich habe viel Volks in dieser Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'Er blieb daselbst ein Jahr und sechs Monate und lehrte sie das Wort Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Während aber Gallio Statthalter von Achaja war, traten die Juden sämtlich wider Paulus auf und führten ihn vor den Richterstuhl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'Und sprachen: Dieser überredet die Leute, dem Gesetz zuwider Gott zu verehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Da wollte Paulus den Mund auftun, aber Gallio sprach zu den Juden: Wenn es ein Frevel oder ein schlechtes Bubenstück wäre, ihr Juden, so würde ich billigerweise euch anhören,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'Nun es sich aber um Streitfragen über Lehre, Namen und euer Gesetz handelt, mögt ihr selbst zusehen. Ich will darüber nicht zu Gericht sitzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'Und er trieb sie fort vom Richterstuhl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Da ergriffen alle den Synagogenvorsteher Sosthenes, und schlugen ihn vor dem Richterstuhl, und Gallio kümmerte sich nicht darum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Paulus blieb noch viele Tage dort, und nahm dann Abschied von den Brüdern, und ging zu Schiff nach Syrien, und mit ihm Priscilla und Aquila, der sich in Kenchrea das Haupt scheren ließ; denn er hatte ein Gelübde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Sie fuhren an das Land nach Ephesus, und dort ließ er sie; er selbst aber ging in die Synagoge, und besprach sich mit den Juden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Als sie ihn baten, länger bei ihnen zu bleiben, lehnte er es ab,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'Und verabschiedete sich von ihnen, indem er sagte: Ich muß durchaus auf das kommende Fest in Jerusalem sein, werde aber, so Gott will, wieder zu euch kommen, und so fuhr er wieder ab von Ephesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'Er fuhr an das Land gen Cäsarea, ging hinauf und grüßte die Gemeinde, und begab sich sodann hinab nach Antiochia.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'Hier verweilte er einige Zeit, zog dann aus und reiste von Ort zu Ort durch das galatische Land und Phrygien, indem er überall die Jünger bestärkte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Es kam aber ein gewisser Jude, mit Namen Apollos, aus Alexandria gebürtig, ein beredter Mann, mächtig in der Schrift, gen Ephesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Dieser war in der Lehre des Herrn unterrichtet, redete und lehrte voll Begeisterung treulich vom Herrn, wußte aber nur von der Taufe des Johannes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'Dieser redete mit Freimut in der Synagoge. Ihn hörten Aquila und Priscilla, nahmen ihn zu sich und legten ihm noch genauer den Weg Gottes aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Da er nach Achaja reisen wollte, munterten ihn die Brüder auf und schrieben den Jüngern, daß sie ihn aufnehmen sollten. Als er ankam, half er viel denen, die gläubig geworden durch die Gnade Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Denn er widerlegte die Juden öffentlich auf das nachdrücklichste, indem er aus der Schrift bewies, daß Jesus der Christ sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Es begab sich aber, während Apollos in Korinth war, daß Paulus, nachdem er landeinwärts gezogen, nach Ephesus kam.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'Hier fand er etliche Jünger und fragte sie: Habt ihr, als ihr gläubig wurdet, den Heiligen Geist empfangen? Sie sagten ihm: Wir haben nicht einmal gehört, ob ein Heiliger Geist sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'Da fragte er sie: Auf was seid ihr denn getauft worden? Sie antworteten: Auf die Taufe des Johannes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Da sprach Paulus: Johannes hat mit der Taufe der Buße getauft, und dem Volk gesagt, sie sollten an Den glauben, Der nach ihm komme, das heißt an Jesus, daß Er Christus sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Als sie solches hörten, ließen sie sich auf den Namen des Herrn Jesus taufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'Da Paulus ihnen die Hände auflegte, kam der Heilige Geist auf sie, und sie redeten mit Zungen und weissagten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Der Männer aber waren es bei zwölfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'Er ging nun in die Synagoge und redete dort frei drei Monate, indem er sich mit ihnen besprach, und sie vom Reich Gottes zu überzeugen suchte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Als aber ein Teil verstockt blieb und nicht glauben wollte, vielmehr die Lehre vor der Menge verleumdete, ließ er von ihnen ab, und sonderte die Jünger ab, indem er in der Schule eines gewissen Tyrannus mit ihnen redete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'Dies geschah zwei Jahre lang, so daß alle, die in Asia wohnten, das Wort des Herrn hörten, Juden und Griechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'Und Gott wirkte durch die Hände des Paulus außerordentliche Wundertaten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'So daß sie von seinem Leib weg Schweißtücher oder Binden auf die Kranken legten, und die Krankheiten von ihnen wichen und böse Geister ausfuhren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Da unterfingen sich einige der umherziehenden jüdischen Beschwörer, über die, so böse Geister hatten, den Namen des Herrn Jesus zu nennen und zu sagen: Ich beschwöre euch bei dem Jesus, den Paulus verkündigt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Es waren sieben Söhne eines jüdischen Hohenpriesters Skewah, die solches taten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Der böse Geist aber antwortete und sprach: Den Jesus kenne ich, auch weiß ich von Paulus; wer seid aber ihr?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'Und der Mensch, in dem der böse Geist war, sprang auf sie los, bemächtigte sich ihrer und überwältigte sie, so daß sie nackt und verwundet aus selbigem Hause entflohen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'Solches ward kund allen Juden und Griechen, die in Ephesus wohnten; und sie alle gerieten in Furcht, und der Name des Herrn Jesus wurde hoch gepriesen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Und viele derer, die gläubig geworden waren, kamen und bekannten und verkündeten, was sie früher ausgerichtet hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'Viele derer, die solch unnützes Zeug getrieben, brachten die Bücher zusammen, und verbrannten sie vor aller Augen; auch berechneten sie ihre Einnahmen und fanden des Geldes fünfzigtausend Drachmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'So gewaltig wuchs das Wort des Herrn und nahm überhand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'Als solches vollbracht war, setzte sich Paulus vor im Geiste, nach einer Reise durch Mazedonien und Achaja sich nach Jerusalem zu wenden, und sprach: Nachdem ich dort gewesen bin, muß ich auch Rom sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Er sandte zwei von denen, die ihm dienten, Timotheus und Erastus, nach Mazedonien voraus; er selbst aber verzog noch eine Zeitlang in Asien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Um selbige Zeit entstand eine nicht geringe Bewegung über dem Weg des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Denn ein Silberschmied, mit Namen Demetrius, der silberne Tempelchen der Diana fertigte, gab den Arbeitern viel zu verdienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'Diese nun und alle, die dabei zu tun hatten, versammelte er und sprach: Ihr wißt, Männer, daß wir von dieser Arbeit unseren Wohlstand haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'Ihr seht aber und hört, daß nicht allein in Ephesus, sondern auch beinahe in ganz Asien dieser Paulus viel Volks abwendig gemacht hat, indem er sagt: Das sind keine Götter, die mit Händen gemacht sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Nicht allein ist dieser unser Erwerb in Gefahr in Verruf zu kommen, sondern es wird auch der Tempel der großen Göttin Diana für nichts geachtet, und ihre Majestät, die ganz Asien und der Weltkreis verehrt, vernichtet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Als sie solches hörten, wurden sie entrüstet und riefen: Groß ist die Diana der Epheser!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'Und die ganze Stadt geriet in Verwirrung, sie stürmten einmütig in das Theater und rissen die Mazedonier Gajus und Aristarchus, des Paulus Gefährten, mit sich dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Da Paulus unter das Volk treten wollte, ließen es ihm die Jünger nicht zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Auch einige der Asiarchen, die ihm befreundet waren, ließen ihn verwarnen, sich nicht in das Theater zu wagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Die einen schrien dies, die anderen anderes; denn die Versammlung war in Verwirrung, und die Mehrzahl wußte nicht, warum sie zusammengekommen wären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'Da zogen sie aus der Menge Alexander hervor, den die Juden vorschoben. Alexander aber machte eine Bewegung mit der Hand und wollte vor dem Volke Verantwortung tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Da sie aber hörten, daß er ein Jude sei, erhob sich eine Stimme von allen, indem sie bei zwei Stunden schrien: Groß ist die Diana der Epheser!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Der Kanzler aber beschwichtigte das Volk und sprach: Männer von Ephesus, wo ist ein Mensch auf Erden, der nicht wüßte, daß die Stadt der Epheser Tempelwärterin der großen Diana und des himmlischen Bildes ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Da dies nun unwidersprechlich ist, so gebührt es uns, ruhig zu bleiben und nichts Übereiltes zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Ihr habt diese Männer vorgeführt, die weder Tempelräuber noch Lästerer eurer Göttin sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Hat aber Demetrius und seine Kunstgenossen eine Sache wider einen, so hält man ja Gerichte und hat Statthalter, da mögen sie einander Rede stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Habt ihr noch weitere Beschwerden, so wird es in der gesetzlichen Versammlung erledigt werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Denn wir stehen in Gefahr, wegen des heutigen Auftritts des Aufruhrs angeklagt zu werden, ohne daß ein Grund vorliegt, mit dem wir diesen Auflauf verantworten könnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, 'Damit ließ er die Versammlung auseinandergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Nachdem dieser Aufruhr gestillt war, rief Paulus die Jünger zusammen, nahm Abschied und machte sich auf, nach Mazedonien zu reisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'Wie er durch selbige Lande kam, ermahnte er sie mit vielen Worten, und gelangte dann nach Griechenland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'Nachdem er allda drei Monate verzogen und ihm dann, wie er im Begriff war nach Syrien abzufahren, von den Juden nachgestellt wurde, war der Rats, über Mazedonien zurückzukehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Es folgte ihm aber bis nach Asien Sopater, des Pyrrhus Sohn, von Beröa, Aristarchus und Secundus von den Thessalonichern, Gajus von Derbe und Timotheus, Tychikus und Trophimus aus Asien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Diese reisten voraus und erwarteten uns in Troas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'Wir aber fuhren nach den Tagen der ungesäuerten Brote von Philippi ab, und kamen in fünf Tagen zu ihnen nach Troas, woselbst wir sieben Tage verweilten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'Am ersten Wochentage aber waren die Jünger beisammen, das Brot zu brechen, und Paulus hielt eine Ansprache an sie, weil er am morgenden Tage abreisen wollte, und dehnte seinen Vortrag bis um Mitternacht aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'Es waren aber viele Lampen auf dem Söller, da wir versammelt waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Da saß ein junger Mensch, mit Namen Eutychus, am Fenster, und sank in einen tiefen Schlaf, weil Paulus so lange redete, und fiel, vom Schlaf bewältigt, vom dritten Stockwerk hinab und ward tot aufgehoben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Paulus aber stieg hinab, legte sich über ihn und umfaßte ihn und sprach: Macht euch keine Unruhe; denn seine Seele ist noch in ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Er stieg wieder hinauf, brach das Brot, aß, und redete dann noch lange bis zu Tagesanbruch. Dann reiste er ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'Den Jungen aber brachte man lebendig herauf, und sie waren nicht wenig getröstet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'Wir aber waren voraus nach dem Schiff gegangen und nach Assos gefahren, wo wir Paulus aufnehmen sollten; denn so hatte er es angeordnet, da er zu Land dahin reisen wollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Als er in Assos bei uns eintraf, nahmen wir ihn zu uns, und kamen nach Mitylene.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'Von dannen schifften wir ab, und kamen am folgenden Tag auf der Höhe von Chios an; am anderen Tag legten wir in Samos an und blieben in Trogyllion, und gelangten am Tage darauf nach Milet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Denn Paulus hatte beschlossen, an Ephesus vorüberzufahren, um sich nicht in Asien aufzuhalten; denn er hatte Eile, um noch, wo möglich, am Pfingsttage in Jerusalem zu sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Von Milet schickte er nach Ephesus und entbot die Ältesten der Gemeinde zu sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Als sie zu ihm kamen, sprach er zu ihnen: Ihr wißt, wie ich vom ersten Tage an, da ich nach Asien gekommen, allezeit bei euch war,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'Und dem Herrn diente mit aller Demut und unter Tränen und Anfechtungen, die mir durch die Nachstellungen der Juden widerfuhren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'Wie ich euch nichts, das zu eurem Besten diente, vorenthielt, daß ich es euch nicht verkündet und euch gelehrt hätte öffentlich und in den Häusern umher;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'Und Juden und Griechen zur Umkehr zu Gott und zum Glauben an unseren Herrn Jesus Christus vermahnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'Und siehe, ich reise nun, gebunden im Geiste, nach Jerusalem, und weiß nicht, was mir daselbst widerfahren wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'Außer daß mir der Heilige Geist von Stadt zu Stadt bezeugt und sagt, daß Bande und Drangsale meiner warten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Aber ich achte deren keines, auch gilt mir mein Leben nichts für mich selbst, um meinen Lauf mit Freuden zu vollenden und im Dienste, den ich vom Herrn Jesu empfangen, das Evangelium der Gnade Gottes zu bezeugen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'Und nun siehe, ich weiß, daß ihr alle, denen ich auf meinen Reisen das Reich Gottes verkündigt, mein Angesicht nicht wieder sehen werdet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Darum bezeuge ich euch am heutigen Tage, daß ich rein bin von aller Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'Denn ich habe euch nichts vorenthalten, daß ich nicht den ganzen Ratschluß Gottes verkündet hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'So habt nun Acht auf euch selbst und auf die ganze Herde, über die euch der Heilige Geist zu Vorstehern gesetzt hat, um zu weiden die Kirche Gottes, die Er Sich durch Sein eigen Blut erworben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Denn das weiß ich, daß nach meinem Scheiden reißende Wölfe werden unter euch kommen, die der Herde nicht schonen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'Selbst aus eurer Mitte werden Männer aufstehen, die verkehrte Dinge reden, um die Jünger an sich zu ziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Darum wachet und seid eingedenk, daß ich drei Jahre lang Tag und Nacht nicht aufhörte, einen jeden mit Tränen zu vermahnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'Und nun empfehle ich euch, Brüder, Gott und dem Worte Seiner Gnade, Ihm, Der mächtig ist, euch weiter zu erbauen und euch ein Erbteil unter allen Heiligen zu verleihen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Silber oder Gold oder Kleidung habe ich von niemand begehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'Ihr wißt selbst, daß diese meine Hände für meine und meiner Gefährten Bedürfnisse gesorgt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'Ich habe euch in allem gezeigt, daß man also arbeiten müsse, und sich der Schwachen annehmen, stets eingedenk der Worte des Herrn Jesus, daß Er sprach: Geben ist seliger denn nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'Und als er solches gesprochen, kniete er nieder mit ihnen allen und betete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'Es war aber viel Weinens unter allen, und sie fielen Paulus um den Hals und küßten ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'Am meisten aber betrübten sie sich darüber, daß er sagte, sie würden sein Angesicht nicht mehr schauen. Sie geleiteten ihn in das Schiff.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Nachdem wir von ihnen geschieden, gingen wir in die See und fuhren stracken Laufs gen Kos, und am folgenden Tage gen Rhodus und von dannen gen Patara.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'Und da wir ein Schiff fanden, das nach Phönizien überfuhr, stiegen wir ein und fuhren ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Als wir Zypern ansichtig wurden, ließen wir es links liegen, fuhren nach Syrien und landeten in Tyrus, wo das Schiff ausladen sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'Wir suchten die Jünger auf und blieben allda sieben Tage. Sie sagten Paulus durch den Geist, er sollte nicht nach Jerusalem ziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Als wir die Tage dort zugebracht, zogen wir aus und machten uns auf den Weg, und alle begleiteten uns mit Weibern und Kindern bis vor die Stadt, knieten nieder am Gestade und beteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'Nachdem wir voneinander Abschied genommen, traten wir in das Schiff, sie aber kehrten nach Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Wir vollendeten unsere Fahrt und landeten in Ptolemais, begrüßten dort die Brüder und blieben einen Tag bei ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'Am folgenden Tage zogen wir aus, und kamen gen Cäsarea, und begaben uns in das Haus des Evangelisten Philippus, der einer der Sieben war, und blieben bei ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Derselbige hatte vier Töchter, die Jungfrauen waren und weissagten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Da wir mehrere Tage dort blieben, kam ein Prophet, mit Namen Agabus, von Judäa herab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'Als er zu uns kam, nahm er des Paulus Gürtel, band sich Hände und Füße und sprach: So spricht der Heilige Geist: Den Mann, dem dieser Gürtel gehört, werden so die Juden in Jerusalem binden und in der Heiden Hände überantworten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Da wir solches hörten, baten wir samt denen, die aus selbigem Orte waren, ihn, er sollte nicht hinauf nach Jerusalem ziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Paulus aber antwortete: Was tut ihr, daß ihr da weint und mir das Herz schwer macht? denn ich bin bereit, in Jerusalem für den Namen des Herrn Jesus nicht allein mich binden zu lassen, sondern auch zu sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'Da er sich nicht abbringen ließ, gaben wir uns zufrieden und sprachen: Es geschehe der Wille des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'Nach diesen Tagen brachen wir auf und zogen hinauf gen Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Es gingen aber mit uns einige der Jünger von Cäsarea und führten uns zu einem alten Jünger, Mnason aus Zypern, bei dem wir herbergen sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Da wir nach Jerusalem kamen, nahmen uns die Brüder freundlich auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'Am anderen Tage ging Paulus mit uns zu Jakobus und alle Ältesten kamen auch dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'Und als er sie gegrüßt hatte, erzählte er im einzelnen alles, was Gott unter den Heiden durch seine Dienstleistung getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Als sie das hörten, lobpriesen sie Gott, sagten ihm aber: Du siehst, Bruder, wie viel tausend Juden gläubig geworden, aber alle noch Eiferer für das Gesetz sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Nun sind sie über dich berichtet worden, du lehrst alle Juden unter den Heiden, sie sollten von Moses abfallen, ihre Kinder nicht mehr beschneiden, auch nicht mehr die Satzungen halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Was ist nun zu tun? Die Menge wird jedenfalls zusammenkommen; denn sie werden hören, daß du gekommen bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'So tue nun, was wir dir sagen: Wir haben vier Männer, die ein Gelübde auf sich haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'Diese nimm zu dir und heilige sie mit dir, und wende die Kosten für sie auf, daß sie ihr Haupt scheren lassen, und alle werden erkennen, daß nichts an dem sei, was über dich berichtet wurde, daß du vielmehr selbst auch nach dem Gesetz wandelst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Den gläubigen Heiden aber haben wir geschrieben und beschlossen, sie brauchten nichts dergleichen zu halten, ausgenommen, daß sie sich hüten sollten vor Götzenopfer, vor Blut, vor Ersticktem und vor Hurerei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Da nahm Paulus die Männer zu sich, heiligte sich am anderen Tag mit ihnen, und begab sich in den Tempel, indem er ankündigte, daß er die Tage der Heiligung aushielte, bis für jeden von ihnen das Opfer dargebracht wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Als nun die sieben Tage beinahe vorbei waren, brachten die Juden aus Asien, die ihn im Tempel sahen, das ganze Volk wider ihn auf, legten die Hände an ihn und schrien:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'Ihr Männer von Israel, kommt zu Hilfe! Das ist der Mensch, der überall jedermann lehrt wider das Volk, das Gesetz und diese Stätte; überdies hat er auch Griechen in den Tempel geführt, und diese Stätte entweiht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Sie hatten nämlich den Epheser Trophimus mit ihm in der Stadt gesehen, und meinten, Paulus hätte ihn in den Tempel geführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'Die ganze Stadt war in Aufregung, es entstand ein Volksauflauf, und sie griffen Paulus und schleppten ihn zum Tempel hinaus, und alsbald wurden die Türen geschlossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Da sie ihn aber töten wollten, ward dem Obersten der Kohorte angezeigt, daß ganz Jerusalem in Aufruhr sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Dieser nahm alsbald Kriegsleute und Centurionen und eilte auf sie zu. Da sie den Obersten und die Kriegsleute sahen, hörten sie auf, den Paulus zu schlagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Da trat der Oberste hinzu, griff ihn und ließ ihm zwei Ketten anlegen, und fragte, wer er wäre und was er getan hätte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'Der eine schrie dies, der andere das in der Menge. Da er aber wegen des Lärmens nichts Gewisses erfahren konnte, ließ er ihn in das Standlager führen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'Als er an die Treppen kam, geschah es, daß wegen des Andrangs der Menge die Kriegsleute ihn tragen mußten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'Denn die Volksmenge folgte nach und schrie: Weg mit ihm!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Als man den Paulus in das Standlager abführen wollte, sprach er zu dem Obersten: Ist es mir erlaubt, mit dir zu sprechen? Er fragte: Verstehst du griechisch?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Bist du nicht der Ägypter, der in diesen Tagen einen Aufruhr erregte und die viertausend Meuchelmörder in die Wüste geführt hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Paulus aber sagte: Ich bin ein jüdischer Mann aus Tarsus in Cilicien, Bürger einer nicht unansehnlichen Stadt. Ich bitte dich, laß mich zu dem Volk reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'Als er es ihm erlaubte, trat Paulus vor auf die Stufen und winkte dem Volk mit der Hand. Als eine große Stille eintrat, redete er zu ihnen auf hebräisch und sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Brüder und Väter, vernehmt meine Verantwortung, die ich jetzt an euch richte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Da sie hörten, daß er hebräisch zu ihnen redete, wurden sie noch stiller.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Er sprach: Ich bin ein jüdischer Mann, geboren zu Tarsus in Cilicien, aber erzogen in dieser Stadt zu den Füßen Gamaliels, unterrichtet nach der Strenge des väterlichen Gesetzes, und war ein Eiferer Gottes, wie ihr alle heute noch seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'Auch habe ich diesen Weg verfolgt bis zum Tode, band und überantwortete in das Gefängnis Männer und Weiber;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'Wie mir auch der Hohepriester und die Gesamtheit der Ältesten bezeugen muß, von denen ich mit Briefen an die Brüder gen Damaskus reiste, um auch die dortigen gebunden nach Jerusalem zur Bestrafung abzuführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Da geschah es, wie ich dahinzog und nahe zu Damaskus kam, da umstrahlte mich am Mittag plötzlich ein starkes Licht vom Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'Ich fiel zu Boden und hörte eine Stimme, die zu mir sprach: Saul, Saul, was verfolgst du Mich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Ich aber antwortete: Wer bist Du, Herr? Und Er sprach zu mir: Ich bin Jesus von Nazareth, Den du verfolgst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Die aber mit mir waren, sahen das Licht und gerieten in Furcht; die Stimme aber Dessen, Der mit mir redete, hörten sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'Ich aber sprach: Was soll ich tun, Herr? Der Herr aber sprach zu mir: Stehe auf und gehe nach Damaskus, da wird man dir sagen von allem, was dir verordnet ist, zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Da ich aber nicht sehen konnte nach jenem Lichtglanz, ward ich an der Hand geleitet von denen, die mit mir waren, und kam gen Damaskus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Es war aber allda ein gottesfürchtiger Mann nach dem Gesetze, Ananias, der bei allen Juden, die dort wohnten, ein gutes Zeugnis hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'Der kam zu mir, trat vor mich und sprach: Bruder Saul, siehe auf; und ich sah zur selben Stunde auf zu ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'Er aber sprach: Der Gott unserer Väter hat dich verordnet, Seinen Willen zu erkennen und den Gerechten zu sehen, und die Stimme Seines Mundes zu hören;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'Denn du sollst Ihm vor allen Menschen ein Zeuge sein dessen, was du gesehen und gehört hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'Und nun, was verziehst du? Stehe auf und laß dich taufen und deine Sünden abwaschen und rufe Seinen Namen an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Es geschah aber, da ich zurückkam gen Jerusalem und im Tempel betete, daß ich entzückt ward und Ihn schaute,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'Da Er zu mir sprach: Eile und verlaß ungesäumt Jerusalem, weil sie dein Zeugnis von mir nicht annehmen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'Und ich sprach: Herr, sie selbst wissen, daß ich die, so an Dich glaubten, in das Gefängnis warf und in den Synagogen geißeln ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'Und als das Blut deines Zeugen Stephanus vergossen ward, stand auch ich dabei und hatte Wohlgefallen an seinem Tode und verwahrte denen, die ihn töteten, die Kleider.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'Da sprach Er zu mir: Gehe hin; denn Ich will dich fern unter die Heiden senden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'Sie hörten ihn an bis auf dieses Wort, da erhoben sie ihre Stimme und schrien: Fort von der Welt mit einem solchen Menschen; er verdient nicht, daß er am Leben bleibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Da sie so schrien und ihre Kleider emporwarfen und Staub in die Luft streuten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'Befahl der Oberste, ihn in das Lager zu führen und durch Geißeln zum Geständnis zu bringen, auf daß er erführe, um welcher Ursache willen sie so wider ihn schrien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Als sie ihn aber für die Riemen darstreckten, sprach Paulus zu dem dabeistehenden Hauptmann: Ist es euch erlaubt, einen römischen Mann und dazu ohne Urteil und Recht zu geißeln?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Da das der Hauptmann hörte, ging er zu dem Obersten und hinterbrachte es ihm und sagte: Was willst du tun? der Mann da ist ja Römer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Da kam der Oberste herbei und sprach zu ihm: Sage mir, bist du ein Römer? Er antwortete: Ja.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'Darauf sagte der Oberste: Ich habe dieses Bürgerrecht für eine große Summe erworben. Paulus aber sprach: Ich aber bin als solcher geboren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Da traten die, so ihn peinigen sollten, alsbald von ihm ab, und der Oberste fürchtete sich, da er nun wußte, daß er Römer war und er ihn gebunden hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Am folgenden Tage wollte er Gewißheit haben, warum er von den Juden angeklagt wäre, ließ ihm die Fesseln abnehmen, berief die Hohenpriester und den gesamten Rat, führte Paulus hinab und ließ ihn vor sie treten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Mit festem Blick schaute Paulus auf den Rat und sprach: Männer, Brüder, ich habe mit allem guten Gewissen bis auf diesen Tag vor Gott gewandelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Der Hohepriester Ananias aber hieß, die neben ihm standen, ihn auf den Mund schlagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Da sprach Paulus zu ihm: Gott wird dich schlagen, du übertünchte Wand! Und du sitzest, mich zu richten nach dem Gesetz und heißt mich schlagen wider das Gesetz!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Die Umstehenden aber sprachen: Schiltst du den Hohenpriester Gottes?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Da sprach Paulus: Ich wußte nicht, Brüder, daß es der Hohepriester ist; es steht ja geschrieben: den Führer deines Volkes sollst du nicht schmähen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Da aber Paulus wußte, daß ein Teil Sadduzäer war, der andere Pharisäer, rief er in dem Rat: Männer, Brüder, ich bin ein Pharisäer und eines Pharisäers Sohn, wegen der Hoffnung der Auferstehung der Toten werde ich gerichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Wie er das sagte, entstand ein Zwiespalt unter den Pharisäern und Sadduzäern, und die Versammlung teilte sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Denn die Sadduzäer sagen, es gebe keine Auferstehung, keinen Engel, keinen Geist, die Pharisäer aber bekennen beides.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'Da entstand nun ein großer Lärm, und die Schriftgelehrten von der Partei der Pharisäer standen auf, stritten und sagten: Wir finden nichts Arges an diesem Menschen; wenn aber ein Geist oder ein Engel zu ihm sprach, so können wir mit Gott nicht streiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Da aber der Lärm zu groß ward, besorgte der Oberste, Paulus möchte von ihnen zerrissen werden, und befahl der Mannschaft, ihn aus ihrer Mitte wegzunehmen und in das Lager zu führen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'In der folgenden Nacht aber erschien ihm der Herr und sprach: Sei getrost, Paulus! Denn wie du für Mich in Jerusalem gezeugt hast, so sollst du auch in Rom zeugen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Wie es aber Tag ward, verschworen sich etliche Juden und verbannten sich, weder zu essen, noch zu trinken, bis daß sie Paulus umgebracht hätten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Es waren ihrer mehr denn vierzig, die sich so verschworen');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Diese traten vor die Hohenpriester und die Ältesten und sprachen: Wir haben uns verflucht und verschworen, nichts zu kosten, bis wir Paulus getötet haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'So tut nun kund dem Obersten samt dem Rat, daß er ihn morgen zu euch herabführen sollte, weil ihr seinen Fall genauer untersuchen wollet; wir aber sind bereit, ihm, ehe er herzutritt, niederzustoßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Als aber der Sohn der Schwester des Paulus von dem Anschlag hörte, kam er, ging hinein in das Lager und sagte es Paulus an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Paulus ließ einen der Hauptleute zu sich rufen und sagte: Führe den jungen Menschen da zu dem Obersten; denn er hat ihm eine Anzeige zu machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'Der nahm ihn nun, führte ihn zum Obersten und sagte: Der gefangene Paulus ließ mich zu sich rufen, und bat mich, den jungen Menschen da zu dir zu führen, er habe dir etwas zu sagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'Da nahm ihn der Oberste bei der Hand, trat mit ihm beiseite und fragte ihn: Was ist es, das du mir zu berichten hast?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'Er aber sagte: Die Juden sind eins geworden, dich zu bitten, Paulus morgen in den Rat herabzuführen, als hätten sie vor, seine Angelegenheit genauer zu untersuchen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Du aber traue ihnen nicht; denn mehr denn vierzig Männer unter ihnen halten auf ihn, und haben sich verbannt, weder zu essen noch zu trinken, bis daß sie ihn umgebracht hätten, und sind schon bereit und warten auf Nachricht von dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Der Oberste entließ nun den Jungen und verbot ihm, weiter zu sagen, daß er ihm diese Anzeige machte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'Er ließ nun zwei der Hauptleute rufen und sagte: Haltet zweihundert Kriegsknechte bereit, daß sie nach Cäsarea ziehen, und mit ihnen siebzig Reiter und zweihundert Schleuderer, auf die dritte Stunde der Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'Auch sollten sie Tiere bereithalten, um Paulus daraufzusetzen und ihn wohlbewahrt zum Landpfleger Felix zu bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'Auch schrieb er einen Brief, der also lautete:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Claudius Lysias entbietet dem edlen Landpfleger Felix seinen Gruß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Diesen Mann, der vor den Juden ergriffen und beinahe umgebracht worden wäre, habe ich mit der Mannschaft herausgerissen, da ich erfuhr, daß er ein Römer ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Da ich die Ursache erfahren wollte, warum sie ihn anklagten, ließ ich ihn vor ihren Rat bringen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'Und befand, daß er wegen Fragen ihres Gesetzes angeschuldigt ward, aber keines Verbrechens, das des Todes oder der Bande wert ist, schuldig war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Da mir aber angezeigt wurde, daß von den Juden ein Anschlag gegen ihn gemacht worden, schicke ich ihn alsbald an dich, und beschied seine Ankläger, dir vorzutragen, was sie wider ihn hätten. Gehab dich wohl!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Die Kriegsleute nahmen nun, wie ihnen befohlen war, Paulus, und führten ihn in der Nacht nach Antipatris.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'Des anderen Tages ließen sie die Reiter mit ihm weiterziehen und wandten wieder um nach dem Lager.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Da sie nach Cäsarea kamen, übergaben sie dem Landpfleger das Schreiben und überantworteten ihm Paulus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Als der Landpfleger den Brief las, fragte er, aus welcher Provinz er wäre, und erfuhr, daß er aus Cilicien sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'Da sprach er: Ich will dich verhören, wenn deine Ankläger angekommen sind; und ließ ihn im Palaste des Herodes verwahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Nach fünf Tagen begab sich der Hohepriester Ananias mit den Ältesten und einem Redner Tertullus hinab, allwo sie vor dem Landpfleger wider Paulus auftraten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Als er vorgerufen ward, fing der Redner seine Anklage damit an, daß er sprach:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'Daß wir in tiefem Frieden leben durch dich, und unser Volk durch deine Vorsorge sich besserer Einrichtungen erfreut, edelster Felix, erkennen wir allezeit und allenthalben auf das dankbarste an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Auf daß ich dich aber nicht zu lange aufhalte, bitte ich dich, uns nach deiner Güte kürzlich anzuhören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Wir haben diesen Mann als verderblich erfunden, und daß er unter allen Juden in der Welt Unruhen erregt und der Anführer der Sekte der Nazarener ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'Der auch versucht hat, den Tempel zu entweihen, worauf wir ihn ergriffen und nach unserem Gesetz richten wollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'Da erschien der Oberste Lysius mit vieler Mannschaft und führte ihn weg aus unseren Händen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'Und hieß seine Ankläger vor dich kommen. Von ihm kannst du selbst, wenn du ihn hören willst, erfahren, wessen wir ihn anklagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'Auch die Juden fielen mit ein und bestätigten, daß es sich also verhielte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Als der Landpfleger Paulus winkte, zu reden, begann er: Da ich weiß, daß du seit vielen Jahren unter diesem Volke Richter bist, so verantworte ich mich umso getroster.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'Du kannst erfahren, daß es nicht mehr denn zwölf Tage sind, seit ich gen Jerusalem gekommen bin anzubeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'Auch haben sie mich nicht erfunden, daß ich im Tempel mit jemand redete, noch einen Auflauf der Menge in den Synagogen oder in der Stadt erregte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'Auch können sie das, was sie mir Schuld geben, nicht beweisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'Soviel aber bekenne ich dir, daß ich nach dem Lehrwege, den sie eine Sekte nennen, dem Gott meiner Väter diene und an alles glaube, was in dem Gesetz und den Propheten geschrieben steht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'Indem ich dieselbe Hoffnung auf Gott habe, welche diese selbst auch haben, daß eine Auferstehung der Toten, sowohl der Gerechten als der Ungerechten, zukünftig sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'Deshalb befleißige ich mich auch gegen Gott und die Menschen, allenthalben ein reines Gewissen zu erhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Nach mehreren Jahren kam ich hin, um meinem Volke Almosen und Opfer zu bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'Dabei fanden sie mich, wie ich mich im Tempel heiligte, ohne Ruhestörung oder Getümmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'Das aber waren etliche Juden aus Asien. Die hätten vor dir auftreten und mich verklagen sollen, so sie etwas gegen mich hätten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Oder die da sollen selbst sagen, was für eine Schuld sie gegen mich fanden, als ich vor dem Rat stand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'Außer etwa wegen der einzigen Rede, da ich unter ihnen stand und rief: Ich werde heute wegen der Auferstehung der Toten vor euch gerichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Als Felix solches hörte, beschied er sie auf weiteres, weil er näheres über die Lehre wußte, und sagte: Wenn der Oberste Lysias herabkommt, will ich über eure Sache erkennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'Dem Hauptmann aber befahl er, ihn in Gewahrsam zu halten, ihn aber gelinde zu behandeln und keinem der Seinen zu wehren, ihm zu Dienste zu sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'Nach etlichen Tagen aber kam Felix mit seinem Weibe Drusilla, die eine Jüdin war, ließ Paulus rufen und hörte ihn über den Glauben an Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Als er aber von Rechtschaffenheit und Keuschheit und künftigem Gericht redete, ward Felix betreten und sagte: Gehe vorerst hin. Wenn ich gelegene Zeit habe, will ich dich wieder rufen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Er hoffte auch daneben, daß ihm von Paulus Geld gegeben würde, um ihn loszulassen. Weshalb er ihn öfter kommen ließ, und sich mit ihm besprach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Da aber zwei Jahre um waren, erhielt Felix den Porcius Festus zum Nachfolger. Da Felix aber den Juden eine Gunst erzeigen wollte, ließ er den Paulus gefangen zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Da nun Festus in die Provinz gekommen war, zog er nach drei Tagen von Cäsarea hinauf gen Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'Da erschienen vor ihm die Hohenpriester und die Vornehmsten der Juden wider Paulus und baten um Gunst wider ihn, daß er ihn ließe nach Jerusalem bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'Sie hatten nämlich einen Anschlag gemacht, daß sie ihn unterwegs umbrächten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Festus antwortete nun, Paulus würde ja in Cäsarea in Gewahrsam gehalten; er selbst werde in kurzem dahin abreisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Die nun von euch die Vollmacht haben, die sollen mit mir hinabziehen, und, wenn etwelches Unrecht an dem Manne ist, es klagend wider ihn vorbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'Nachdem er sich nicht mehr denn acht oder zehn Tage bei ihnen aufgehalten hatte, begab er sich hinab gen Cäsarea, setzte sich tags darauf auf den Richtstuhl und ließ Paulus vorführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Als er vorkam, umstanden ihn die Juden, die von Jerusalem herabgekommen waren, und brachten viele schwere Beschuldigungen vor, die sie nicht beweisen konnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'Als er sich dahin verantwortete: Ich habe weder gegen das Gesetz der Juden, noch gegen den Tempel, noch gegen den Kaiser etwas verbrochen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Antwortete Festus, der den Juden eine Gunst erzeigen wollte, dem Paulus und sagte: Willst du nach Jerusalem hinaufziehen und dich dort darüber von mir richten lassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Darauf sprach Paulus: Ich stehe vor dem Richterstuhl des Kaisers, und muß allda gerichtet werden. Den Juden habe ich kein Leid getan, wie auch du auf das beste einsiehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Wenn ich nun schuldig bin und etwas getan habe, das den Tod verdient, so weigere ich mich nicht zu sterben; wenn aber nichts an dem ist, dessen mich diese beschuldigen, so darf mich ihnen niemand preisgeben; ich appelliere an den Kaiser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Da besprach sich Festus mit dem Rat und gab den Bescheid: An den Kaiser hast du appelliert, zum Kaiser sollst du ziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Nach etlichen Tagen kam der König Agrippa und Bernice herab nach Cäsarea, um Festus zu begrüßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Da sie sich mehrere Tage daselbst aufhielten, legte Festus dem König den Fall mit Paulus vor und sagte: Da ist ein Mann, den Felix mir gefangen hinterlassen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Wegen dessen der Hohepriester und die Ältesten der Juden bei mir, als ich nach Jerusalem kam, Klage führten, und um ein Urteil wider ihn baten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Ich antwortete ihnen, daß es nicht Römersitte ist, einen Menschen aus Gunst zu verurteilen, ehe denn der Verklagte seinen Klägern gegenübergestellt wäre und Gelegen- heit hätte, sich gegen die Anklage zu verteidigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Als sie sich nun hier eingefunden, setzte ich mich ohne Aufschub am folgenden Tag auf den Richterstuhl und ließ den Mann vorführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Die Ankläger traten auf, brachten aber keinerlei Schuld vor, deren ich mich versah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'Wohl hatten sie einige Streitpunkte in betreff ihrer besonderen Gottesverehrung und über einen Jesus, der gestorben, und von dem Paulus sagte, Er lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Da ich aber von der Frage über diesen Gegenstand nichts verstand, fragte ich, ob er nach Jerusalem reisen und sich allda darüber wollte richten lassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Als aber Paulus begehrte, für das Erkenntnis des Kaisers in Haft zu bleiben, hieß ich ihn in Gewahrsam halten, bis daß ich ihn an den Kaiser absenden könnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Da bemerkte Agrippas dem Festus: Ich möchte den Menschen gern auch selber hören. Er sagte: Morgen sollst du ihn hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Am anderen Tage nun kam Agrippa und Bernice mit großem Gepränge und betraten den Verhörsaal mit den Kriegsobersten und den angesehensten Männern der Stadt, und auf Befehl des Festus ward Paulus vorgeführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'Da sprach Festus: König Agrippa und ihr Männer alle, die ihr mit uns hier zugegen seid, da seht ihr den Mann, um den mich die ganze Menge der Juden zu Jerusalem und hier angegangen und geschrien hat, daß er nicht länger am Leben bleiben dürfte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Da ich aber fand, daß er nichts getan hatte, das des Todes wert ist, und er an den Kaiser appellierte, habe ich beschlossen, ihn abzusenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'Da ich nun nichts Bestimmtes habe, das ich dem Herrn schriebe, lasse ich ihn vor euch führen, und vornehmlich vor dich, König Agrippa, auf daß ich nach geschehenem Verhöre etwas zu schreiben wüßte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Denn es scheint mir ungereimt, einen Gefangenen einzuliefern, ohne die Klagepunkte wider ihn anzugeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agrippa aber sprach zu Paulus: Es ist dir erlaubt, für dich zu reden. Da verantwortete sich Paulus, indem er die Hand ausreckte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Ich achte mich glücklich, König Agrippa, daß ich mich heute über alles, dessen ich von den Juden beschuldigt werde, vor dir verantworten soll;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'Zumal da du alle Sitten und Streitfragen der Juden kennst; darum bitte ich dich, du wollest mich geduldig anhören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Mein Leben von Jugend auf, wie ich es von Anbeginn unter meinem Volke zu Jerusalem geführt, kennen alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'Die Juden, die mich vorher von Anfang an gekannt haben müßten, wenn sie zeugen wollten, mir bezeugen, daß ich nach der strengsten Sekte unserer Religion als Pharisäer gelebt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'Und nun stehe ich hier, und werde angeklagt über der Hoffnung auf die Verheißung, die von Gott unseren Vätern geworden ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'Und welche die zwölf Stämme unseres Volkes, Tag und Nacht angelegentlich betend, zu erlangen hoffen; über diese Hoffnung werde ich, König Agrippa, von den Juden angeklagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Warum wird es bei euch für unglaublich geachtet, daß Gott Tote auferweckt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Zwar meinte ich auch bei mir selbst, ich müßte vieles wider den Namen des Jesus von Nazareth tun;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'Was ich denn auch in Jerusalem tat, und viele Heilige ins Gefängnis verschloß, wozu ich Vollmacht von den Hohenpriestern empfing, und stimmte mit, daß sie zum Tode gebracht wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'Und in allen Synagogen ließ ich sie züchtigen, und zwang sie zu lästern, und wütete im Übermaß, und verfolgte sie bis in die fremden Städte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'Während ich so mit Vollmacht und im Auftrag der Hohenpriester nach Damaskus reiste,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'Sah ich, o König, mitten am Tage auf dem Wege, wie mich, und die mit mir reisten, ein Licht umstrahlte, das heller war, denn der Sonnenglanz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'Da wir alle zur Erde fielen, hörte ich eine Stimme, die in hebräischer Sprache zu mir redete und sagte: Saul, Saul, was verfolgst du Mich? Es wird dir schwer werden, wider den Stachel zu löcken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Ich aber sprach: Wer bist Du, Herr? Der Herr aber sprach. Ich bin Jesus, Den du verfolgst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Aber stehe auf und tritt auf deine Füße; denn dazu bin Ich dir erschienen, daß Ich dich zum Diener und Zeugen dessen bestelle, was du gesehen hast und weshalb Ich dir ferner erscheinen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'Und will dich erretten vor dem Volk und von den Heiden, unter die Ich dich jetzt sende;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'Ihnen die Augen aufzutun, auf daß sie umkehren aus der Finsternis in das Licht, und aus der Gewalt des Satans zu Gott, auf daß sie Vergebung der Sünden und ein Erbteil unter den Heiligen durch den Glauben an Mich erlangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Deshalb, König Agrippa, war ich der himmlischen Erscheinung nicht ungehorsam,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'Sondern kündigte zuerst denen in Damaskus und Jerusalem und dem ganzen Lande Judäa und den Heiden an, sie sollten Buße tun, und umkehren zu Gott und der Buße würdige Werke tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Um deswillen haben mich die Juden im Tempel ergriffen und suchten mich zum Tode zu bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Aber es ward mir Hilfe von Gott zuteil, und ich stehe bis auf diesen Tag, wohlbezeugt bei Kleinen und bei Großen, indem ich nichts spreche, als was die Propheten und Moses als zukünftig vorausgesagt haben:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'Daß Christus würde leiden, und der Erste sein aus der Auferstehung der Toten, dem Volk und den Heiden Licht zu verkündigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Da er sich also verantwortete, sprach Festus mit lauter Stimme: Paulus, du rasest; dein vieles Wissen bringt dich zum Wahnsinn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Er aber sprach: Ich rase nicht, edelster Festus, sondern spreche Worte der Wahrheit und Nüchternheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Denn um diese Dinge weiß der König wohl, zu dem ich auch freimütig rede; denn ich glaube nicht, daß ihm von diesem allem etwas in irgendeiner Hinsicht verborgen blieb; denn solches ist nicht im Winkel geschehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Glaubst du, König Agrippa, den Propheten? Ich weiß, daß du glaubst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Agrippa aber sprach zu Paulus: Es fehlt wenig, so überredest du mich, ein Christ zu werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Paulus aber sagte: Ich möchte wohl zu Gott beten, daß weder viel noch wenig fehlte, daß nicht allein du, sondern auch alle, die mich heute hören, solche würden, wie ich bin, diese Bande ausgenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'Und da er solches gesagt hatte, stand der König und der Landpfleger und Bernice und die mit ihnen saßen, auf,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'Entfernten sich, redeten miteinander und sprachen: Dieser Mensch tut nichts, was Tod oder Fesseln verdiente.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agrippa sagte nun zu Festus: Dieser Mann hätte können freigegeben werden, wenn er sich nicht auf den Kaiser berufen hätte..');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Als nun entschieden ward, daß wir nach Italien schiffen sollten, übergaben sie Paulus und etliche andere Gefangene einem Hauptmann mit Namen Julius, von der kaiserlichen Kohorte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'Wir betraten nun ein adramyttisches Schiff, um die Asien entlang gelegenen Orte zu befahren, und segelten ab; auch war mit uns Aristarchus aus Thessalonich in Mazedonien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'Am anderen Tag liefen wir zu Sidon ein, und Julius war freundlich gegen Paulus und erlaubte ihm, zu den Freunden zu gehen und seiner zu pflegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'Und von dannen stießen wir ab und schifften unter Zypern hin, weil uns die Winde entgegen waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'Und durchschifften das Meer von Cilicien und Pamphylien und kamen gen Myra in Lycien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'Und daselbst fand der Hauptmann ein Schiff von Alexandrien, das nach Italien fuhr, und lud uns darauf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Da wir in vielen Tagen nur langsam weiterfuhren, und mit Mühe gen Knidus gekommen waren, da der Wind uns nicht anließ, fuhren wir unter Kreta hin bei Salmone vorbei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'Mit Mühe fuhren wir der Küste entlang und kamen an einen Ort, der Schönhafen hieß, in dessen Nähe die Stadt Lasäa lag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Da nun viel Zeit vergangen und es bereits gefährlich war zu schiffen, weil auch schon die Fastenzeit vorüber war, vermahnte sie Paulus und sprach zu ihnen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'Ihr Männer, ich sehe, daß die Fahrt nicht nur mit Ungemach und vielem Verlust, sowohl der Ladung als des Schiffes, sondern auch unseres Lebens verbunden sein wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Aber der Hauptmann glaubte dem Steuermann und dem Schiffsherrn mehr, als den Worten des Paulus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'Und da der Hafen zum Wintern ungelegen war, wurden die meisten Rats, von dannen zu fahren, um, wo möglich, nach Phönix, einem Hafen von Kreta gegen Südwest und gegen Nordwest, zu gelangen, um dort zu überwintern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Da aber gelinder Südwind eingetreten war, glaubten sie ihres Vorsatzes Herr geworden zu sein, lichteten die Anker und fuhren näher an Kretas Küste hin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Es dauerte aber nicht lange, da stieß ein Sturmwind, den sie Euroklydon nennen, gegen die Insel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Als aber das Schiff mit fortgerissen ward und dem Wind nicht widerstehen konnte, gaben wir uns preis und fuhren dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Wir liefen aber gegen eine kleine Insel, mit Namen Klauda, und konnten kaum des Bootes mächtig werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'Da sie es aufgehoben hatten, wandten sie Schutzmittel an und untergürteten das Schiff; und weil sie fürchteten, auf die Syrte verschlagen zu werden, strichen sie die Segel und trieben so dahin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'Da wir aber vom Sturm hin und her geworfen wurden, warfen sie am folgenden Tag einen Teil der Ladung über Bord.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'Und am dritten Tag warfen wir mit eigenen Händen die Schiffsgerätschaft aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Da aber mehrere Tage weder Sonne noch Gestirn zu sehen war und ein gewaltiger Sturm wütete, verschwand vollends alle Hoffnung auf Rettung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'Da man lange nichts gegessen hatte, trat Paulus ins Mittel und sprach: Männer, man hätte mir folgen und nicht von Kreta abfahren sollen, was uns dieses Ungemachs und Verlustes überhoben hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'Und nun ermahne ich euch, getrosten Muts zu sein; wir werden kein Leben, nur das Schiff verlieren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Heute Nacht erschien mir ein Engel des Gottes, Dem ich angehöre und Dem ich auch diene, und sprach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'Fürchte dich nicht, Paulus, du mußt vor den Kaiser treten; und siehe, Gott hat dir alle geschenkt, die mit dir zu Schiffe sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Darum seid guten Mutes, Männer, denn ich vertraue dem Gott, daß es also geschehen wird, wie mir gesagt ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Wir müssen aber an eine Insel auffahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Da aber die vierzehnte Nacht kam und wir im adriatischen Meere umhertrieben, meinten die Schiffsleute um die Mitternacht, daß sie an ein Land kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'Und da sie das Senkblei auswarfen, fanden sie zwanzig Klafter, und als sie eine Strecke weiterfuhren und wieder auswarfen, fanden sie fünfzehn Klafter Tiefe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'Weil sie nun fürchteten, auf Felsenriffe zu geraten, warfen sie vom Hinterteil des Schiffes vier Anker aus, und wünschten, daß es Tag werden möchte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Da die Schiffleute aber aus dem Schiff zu entfliehen suchten, und unter dem Vorwand, sie wollten vom Vorderschiff Anker auswerfen, das Boot ins Meer niederließen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'Sprach Paulus zu dem Hauptmann und den Kriegsleuten: Wenn diese nicht im Schiff bleiben, so könnt ihr nicht gerettet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Da hieben die Kriegsleute die Taue des Bootes ab und ließen es fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Bis es nun Tag wurde, forderte Paulus alle auf, Speise zu sich zu nehmen, und sagte: Vierzehn Tage lang habt ihr ungegessen zugewartet und nichts zu euch genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Deshalb ermahne ich euch, Speise zu euch zu nehmen; denn dies trägt zu eurer Erhaltung bei, denn kein Haar von eurem Haupte wird verlorengehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'Da er solches gesprochen, nahm er Brot, dankte Gott im Angesichte aller, brach es und fing an zu essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Da faßten sie alle Mut und nahmen auch Speise zu sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Unser waren aber auf dem Schiff zweihundertsechsundsiebzig Seelen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'Da sie nun satt waren, erleichterten sie das Schiff und warfen den Mundvorrat ins Meer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Da es nun Tag ward, erkannten sie das Land nicht, wurden aber eines Busens gewahr, der ein flaches Ufer hatte, auf das sie das Schiff wo möglich antreiben wollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'Und so kappten sie die Anker und ließen sie im Meer, indem sie zugleich die Bande der Steuerruder lösten, das Braamsegel spannten, und fuhren dem Strande zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Sie gerieten aber auf einen Ort, der auf zwei Seiten Meer hatte, und stießen das Schiff auf, so daß das Vorderteil unbeweglich aufsaß, das Hinterteil aber von der Gewalt der Fluten auseinanderging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Die Kriegsleute faßten nun den Entschluß, die Gefangenen zu töten, damit keiner durch Schwimmen entkäme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Der Hauptmann aber wollte Paulus retten, und verhinderte sie an ihrem Vorhaben, und hieß die, so schwimmen könnten, zuerst sich ins Wasser werfen, um an das Land zu kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'Die anderen sollten auf Brettern oder auf anderen Stücken des Schiffes das gleiche tun; und so geschah es, daß alle glücklich das Land erreichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'Als wir uns nun gerettet hatten, erfuhren wir, daß die Insel Melite hieß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Die Inselbewohner erzeigten uns ungewöhnliche Leutseligkeit, zündeten ein Feuer an und nahmen uns alle wegen des eingetretenen Regens und der Kälte bei sich auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Da aber Paulus einen Haufen Reiser zusammenraffte und sie auf das Feuer legte, kam eine Otter wegen der Hitze daraus hervor und hängte sich ihm an die Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Als die Inselbewohner das Tier an seiner Hand hängen sahen, sagten sie zueinander: Dieser Mensch ist ganz gewiß ein Mörder, den die Rachegöttin nicht am Leben ließ, ob er gleich aus dem Meere sich gerettet hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Er schleuderte nun das Tier in das Feuer und erlitt keinen Schaden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Sie erwarteten aber, daß er aufschwellen oder sogleich tot niederfallen würde. Da sie aber lange warteten und sahen, daß es ihm keinen Schaden tat, wurden sie anderen Glaubens und sagten, er wäre ein Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'In der Nähe des Ortes hatte der vornehmste Mann auf der Insel, mit Namen Publius, Ländereien, nahm uns auf und bewirtete uns freundlich drei Tage lang.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Es traf sich, daß der Vater des Publius Fieberanfälle hatte und an der Ruhr darniederlag. Paulus ging zu ihm hinein, betete, legte ihm die Hände auf und heilte ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'Da dies geschehen war, kamen auch die anderen Kranken der Insel zu ihm und ließen sich heilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Und sie erwiesen uns viele Ehre und brachten uns, da wir abfuhren was wir bedurften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'Nach drei Monaten gingen wir in einem Schiff von Alexandrien, das auf der Insel überwinterte und das Abzeichen der Zwillinge führte, auf die See.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'Als wir in Syrakus landeten, blieben wir allda drei Tage,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Schifften von da herum und liefen in Rhegium ein, und da nach einem Tage sich ein Südwind erhob, kamen wir am anderen Tag nach Puteoli.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Fanden allda Brüder und wurden gebeten, sieben Tage bei ihnen zu bleiben, und so gingen wir dann nach Rom ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'Und von dort kamen die Brüder, da sie von uns hörten, uns bis gen Appifer und Tretabern entgegen. Da Paulus sie sah, dankte er Gott und gewann Zuversicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Als wir in Rom ankamen, überantwortete der Hauptmann die Gefangenen dem Obersten der Leibwache; dem Paulus aber ward erlaubt, für sich zu bleiben mit dem Kriegsknechte, der ihn bewachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Drei Tage darauf lud er die angesehensten Juden zu sich ein; und da sie zusammenkamen, sprach er zu ihnen: Ihr Männer und Brüder! Ich habe nichts gegen das Volk, noch wider die väterlichen Gesetze getan, darob ich von Jerusalem aus als Gefangener in die Hände der Römer überantwortet wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Als diese mich verhört hatten, wollten sie mich freigeben, weil keine Schuld des Todes an mir erfunden wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Da die Juden aber dawider sprachen, sah ich mich genötigt, an den Kaiser zu appellieren, nicht, als ob ich Klage gegen mein Volk führen wollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Aus diesem Grunde habe ich mir erbeten, euch zu sehen und zu euch zu sprechen; denn um der Hoffnung Israels willen trage ich diese Kette.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Sie aber sprachen zu ihm: Wir haben weder ein Schreiben über dich aus Judäa erhalten, noch ist ein Bruder gekommen, der Böses über dich verkündigt oder geredet hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Wir wollen aber von dir hören, auf was du hältst; denn wir haben von dieser Sekte gehört, daß sie überall Widerspruch findet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'Sie bestimmten ihm einen Tag, und es kamen noch mehrere zu ihm in die Herberge, denen er das Reich Gottes nachdrücklich bezeugte und auslegte, und er suchte sie zu überzeugen von Jesus aus dem Gesetz Moses und aus den Propheten, vom frühen Morgen bis an den Abend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'Die einen glaubten dem, was er sagte, die anderen aber glaubten nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'Sie wurden untereinander uneins, und gingen weg, nachdem Paulus noch die eine Rede getan: Wohl hat der Heilige Geist durch den Propheten Jesajah zu unseren Vätern geredet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'Und gesagt: Gehe hin zu diesem Volke und sprich: Ihr werdet hören, aber nicht verstehen, werdet sehen, aber nicht einsehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Denn das Herz dieses Volkes ist verstockt, und schwer hören sie mit den Ohren, und drücken ihre Augen zu, daß sie nicht sehen mit ihren Augen und hören mit den Ohren und verstehen mit dem Herzen und umkehren, und Ich sie heile.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'So sei euch nun kundgetan, daß zu den Heiden das Heil Gottes gesandt worden ist, und sie werden darauf hören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, 'Da er solches geredet hatte, gingen die Juden fort und hatten viel Streitens unter sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'Er blieb zwei ganze Jahre in seinem eigenen Geding und nahm alle auf, die zu ihm einkamen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'Predigte das Reich Gottes und lehrte von Jesus Christus mit aller Freimütigkeit ungehindert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Paulus, ein Knecht Jesu Christi, zum Apostel berufen, ausgesondert zum Evangelium Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'Welches Er zuvor verheißen hat durch Seine Propheten in heiligen Schriften,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'Von dem Sohne, Der aus dem Samen Davids geboren worden nach dem Fleisch,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'Aber wunderkräftig Sich als Sohn Gottes erwiesen hat nach dem Geiste der Heiligkeit durch die Auferstehung von den Toten, als Jesus Christus, unseren Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Durch Den wir empfangen haben Gnade und Apostelamt, Gehorsam des Glaubens für Seinen Namen unter allen Völkern zu bewir- ken,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'Unter denen auch ihr Berufene von Jesus Christus seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'An alle in Rom befindliche Geliebte Gottes und berufene Heilige. Gnade euch und Friede von Gott unserem Vater und dem Herrn Jesus Christus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Zuvörderst danke ich meinem Gott durch Jesus Christus um euer aller willen, daß euer Glaube in aller Welt verkündigt wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Denn Gott ist mein Zeuge, Dem ich diene in meinem Geist durch das Evangelium Seines Sohnes, wie ich euer unablässig gedenke,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'Und allezeit in meinen Gebeten flehe, ob mir wohl das Glück werde, nach dem Willen Gottes zu euch zu kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Denn mich verlangt, euch zu sehen, auf daß ich euch etwas geistiger Gnadengabe mitteile, damit ihr gestärkt werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'Damit meine ich, daß ich an euch ermuntert werde durch unseren gemeinsamen Glauben, den euren und den meinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Ich will euch aber nicht verhalten, Brüder, daß ich mir oft vorgesetzt hatte und bis jetzt immer verhindert wurde, zu euch zu kommen, auf daß ich auch unter euch einige Frucht hätte, gleich wie unter den übrigen Völkern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Denn ich bin ein Schuldner sowohl der Griechen, als der Nichtgriechen, der Weisen und der Unverständigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'So bin ich denn, soviel an mir ist, bereit, auch euch in Rom das Evangelium zu verkündigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Denn ich schäme mich der Heilsbotschaft von Christus nicht, weil sie eine Kraft Gottes ist, und Heil bringt allen, die daran glauben, Juden zunächst und Griechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Weil die Gerechtigkeit Gottes in ihr geoffenbart wird, aus Glauben in Glauben, wie denn geschrieben steht: Der Gerechte wird durch seinen Glauben leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Denn der Zorn Gottes wird geoffenbart vom Himmel über alle Gottlosigkeit und Ungerechtigkeit der Menschen, welche die Wahrheit durch Ungerechtigkeit aufhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'Denn daß ein Gott ist, ist ihnen offenbar, weil Gott es ihnen geoffenbart hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Denn Sein Unschaubares wird von der Schöpfung der Welt an durch das Erschaffene erschaut, und mit der Vernunft wahrgenommen, Seine ewige Kraft und Göttlichkeit, so daß sie keine Entschuldigung haben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Weil sie Gott kannten; sie priesen Ihn aber nicht als Gott, noch dankten sie, sondern ließen sich betören in ihren Gedanken und ihr unverständiges Herz verfinsterte sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Während sie sagten, sie wären weise, wurden sie Toren,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'Und vertauschten die Herrlichkeit des unvergänglichen Gottes mit Bildern vergänglicher Menschen, Vögel, vierfüßiger und kriechender Tiere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Weshalb sie Gott auch hingab in die Gelüste ihrer Herzen, in Unzucht, so daß sie ihre Leiber untereinander entehrten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'Als welche die Wahrheit Gottes umtauschten für die Lüge, und die Schöpfung mehr als den Schöpfer, Der doch in Wahrheit ewiglich zu preisen ist, anbeteten und verehrten. Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Darum gab sie Gott in schandbare Leidenschaften hin; denn ihre Weiber verwandelten den natürlichen Genuß in unnatürlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'Desgleichen auch die Männer den natürlichen Umgang mit dem Weibe verließen und in geiler Lust gegeneinander entbrannten, und Männer mit Männern schändliche Unzucht trieben, und den verdienten Lohn ihres Irrwahns, wie es denn sein sollte, an sich selbst empfingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'Und gleich wie sie die Erkenntnis Gottes verwarfen, gab sie Gott dahin ihrem verkehrten Sinn, zu tun, was sich nicht gebührte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'So daß sie aller Ungerechtigkeit, Hurerei, Schlechtigkeit, Habsucht und Bosheit sich ergaben, voll Neides, Mordsucht, Zänkerei, Arglist und Tücke;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'Ohrenbläser, Verleumder, Gottverhaßte, Übermütige, Hoffärtige, Ruhmredige, Unheilstifter, den Eltern Ungehorsame,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'Unbesonnene, unverträgliche, lieblose, unbarmherzige Menschen wurden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'Die, obgleich sie wußten, was vor Gott recht ist, daß die, welche solches tun, des Todes würdig sind, dasselbige nicht nur selbst tun, sondern auch an denen, die es tun, Gefallen finden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Darum kannst du dich, o Mensch, wer du auch bist, der da richtet, nicht entschuldigen; denn indem du den anderen richtest, sprichst du dir selbst das Urteil, weil du, der du richtest, dasselbe tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Wir wissen aber, daß Gott über die, welche solches tun, gerechtes Urteil spricht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Denkst du aber, o Mensch, daß du, der du richtest die, so solches tun, und dasselbe tust, dem Gerichte Gottes entfliehen werdest?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Oder achtest du gering den Reichtum seiner Güte, Geduld und Langmut, indem du verkennst, daß die Güte Gottes dich zur Buße treibt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Du aber häufst nach deiner Verstocktheit und deinem unbußfertigen Herzen dir selbst Zorn auf den Tag des Zorns und der Offenbarung des gerechten Gerichtes Gottes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'Welcher einem jeglichen geben wird nach seinen Werken,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'Denen, die durch Beharrlichkeit im guten Werk nach Herrlichkeit, Ehre und Unvergänglichkeit strebten, ewiges Leben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'Denen aber, die parteisüchtig sind und der Wahrheit nicht gehorchen, gehorchen aber der Ungerechtigkeit, Zorn und Entrüstung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Drangsal und Angst über alle Menschenseelen, die Böses tun, zuerst den Juden und den Griechen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'Herrlichkeit aber und Ehre und Frieden einem jeglichen, der das Gute tut, den Juden zuerst und den Griechen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'Denn es ist kein Ansehen der Person bei Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Denn alle, die ohne das Gesetz gesündigt haben, werden ohne das Gesetz verlorengehen, und alle, die unter dem Gesetz gesündigt, werden durch das Gesetz gerichtet werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Weil nicht die Hörer des Gesetzes vor Gott gerecht sind, sondern die Täter des Gesetzes werden gerechtfertigt werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Denn so die Heiden, die das Gesetz nicht haben, von Natur tun, was das Gesetz will, so sind diese, die das Gesetz nicht haben, sich selbst Gesetz,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'Als die da zeigen, des Gesetzes Werk sei in ihre Herzen geschrieben, weil zugleich ihr Gewissen ihnen Zeugnis gibt und ihre Gedanken sich untereinander anklagen oder auch entschuldigen],');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'An dem Tage, da Gott das Verborgene der Menschen durch Jesus Christus richten wird, laut meines Evangeliums.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Wenn du nun ein Jude heißest und dich auf das Gesetz verläßt und dich Gottes rühmst,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'Und kennst den Willen Desselben, und aus dem Gesetz unterrichtet prüfen kannst, was Recht und Unrecht ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'Und dir getraust ein Führer der Blinden zu werden, ein Licht derer, die in Finsternis sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'Ein Erzieher der Unverständigen, ein Lehrer der Einfältigen, der den Inbegriff der Erkenntnis und der Wahrheit in dem Gesetz hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'Warum belehrst du, der du andere belehrst, dich selber nicht? Du predigst, man solle nicht stehlen, und stiehlst!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'Du sagst, man soll nicht ehebrechen, und brichst die Ehe! Du sprichst deinen Abscheu vor Götzen aus und bist ein Tempelräuber?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'Du rühmst dich des Gesetzes, und schändest Gott durch Übertretung des Gesetzes?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Denn euretwegen wird der Name Gottes gelästert unter den Heiden, wie die Schrift sagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Die Beschneidung hat zwar ihren Nutzen, wenn du das Gesetz hältst; bist du aber ein Übertreter des Gesetzes, so ist deine Beschneidung zur Vorhaut geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'So nun die Vorhaut die Rechte des Gesetzes hält, wird ihm da die Vorhaut nicht für eine Beschneidung angerechnet werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'Wird also nicht die natürliche Vorhaut, die das Gesetz vollbringt, dich richten, der du bei dem Buchstaben und der Beschneidung ein Übertreter des Gesetzes bist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Denn der ist noch kein rechter Jude, der auswendig ein Jude ist, auch ist das keine Beschneidung, die nur auswendig am Fleisch geschieht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'Sondern der ist ein Jude, der inwendig ein Jude ist, und die wahre Beschneidung ist die des Herzens, im Geist und nicht im Buchstaben; ein solcher hat sein Lob nicht von Menschen, sondern von Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Was hat nun der Jude voraus, oder was nützt die Beschneidung?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Viel in alle Wege. Zum ersten ist ihnen anvertraut, was Gott gesprochen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Denn wie? Wenn welche nicht glaubten, so wird doch ihr Unglaube die Glaubhaftigkeit Gottes nicht aufheben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Das sei ferne! Gott muß wahrhaftig sein, wenn auch jeder Mensch unwahr ist, wie geschrieben steht: Auf daß du gerecht erscheinst in deinen Worten, und Sieger bleibst, wenn du zu Gericht gehst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Wenn aber unsere Ungerechtigkeit Gottes Gerechtigkeit ins Licht stellt, was sagen wir dann? Ist Gott ungerecht, daß Er Zorn verhängt? Ich spreche nach menschlicher Weise.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Das sei ferne! Wie könnte sonst Gott die Welt richten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Denn wenn die Wahrhaftigkeit Gottes durch meine Unwahrheit größer erschienen ist zu Seiner Verherrlichung, warum werde ich dann noch als Sünder gerichtet?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'Und warum sollen wir nicht tun, wie man uns verleumdet, und wie einige behaupten, daß wir sagen: Laßt uns das Böse tun, auf daß Gutes herauskomme? Solcher Verdammung wäre gerecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Wie nun? Haben wir etwas voraus? Gar nichts; denn wir haben oben bewiesen, daß Juden und Griechen allzumal Sünder sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'Wie denn geschrieben steht: Da ist keiner, der gerecht wäre, auch nicht einer;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'Keiner, der verständig wäre, keiner, der nach Gott fragete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'Alle sind abgewichen, zumal untüchtig geworden. Da ist keiner, der Gutes täte, auch nicht einer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Ihr Schlund ist ein offenes Grab. Mit ihren Zungen reden sie trüglich, Otterngift ist unter ihren Lippen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Ihr Mund ist voll Fluchens und Bitterkeit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Schnell sind ihre Füße zum Blutvergie-ßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Elend und Herzeleid ist auf ihren Wegen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'Und den Weg des Friedens haben sie nicht kennengelernt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Es ist keine Furcht Gottes vor ihren Augen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Wir wissen aber, daß alles, was das Gesetz sagt, es denen sagt, die unter dem Gesetz sind, auf daß aller Mund verstumme und alle Welt vor Gott straffällig sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Weil durch des Gesetzes Werke kein Fleisch vor Ihm gerechtfertigt werden wird; denn durch das Gesetz kommt Erkenntnis der Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Nun aber ist ohne das Gesetz die Gerechtigkeit Gottes geoffenbart, bezeugt von dem Gesetz und den Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'Die Gerechtigkeit Gottes aber durch den Glauben an Jesus Christus erstreckt sich zu allen und auf alle, die da glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'Denn es ist kein Unterschied, weil alle sündigten und ermangeln des Ruhms vor Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'Indem sie unverdient gerechtfertigt werden durch Seine Gnade, durch die Erlösung in Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'Den Gott in Seinem Blut als Sühnmittel durch den Glauben hingestellt hat, um Seine Gerechtigkeit zu zeigen, durch die Erlassung vorhergegangener Sünden, vermöge der Nachsicht Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'Zum Beweis Seiner Gerechtigkeit in jetziger Zeit, so daß Er gerecht sei und gerecht mache den, der da ist im Glauben an Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Wo bleibt nun das Rühmen? Es ist ausgeschlossen. Durch welches Gesetz?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'So halten wir denn dafür, daß der Mensch durch den Glauben gerecht werde ohne des Gesetzes Werke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Oder ist Er allein der Juden Gott? nicht auch der Heiden? Ja, auch der Heiden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'Sintemal es ein alleiniger Gott ist, Der die Beschneidung gerecht macht durch den Glauben, und die Vorhaut durch den Glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Heben wir denn nun das Gesetz durch den Glauben auf? Das sei ferne! wir richten vielmehr das Gesetz auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Was wollen wir denn sagen von unserem Vater Abraham, daß er dem Fleische nach erlangt habe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Denn wenn Abraham durch Werke gerechtfertigt ward, so hatte er Ruhm, aber nicht bei Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Denn was sagt die Schrift? Abraham glaubte Gott, und es ward ihm zur Gerechtigkeit gerechnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'Dem aber, der Werke tut, wird der Lohn nicht aus Gnade zugerechnet, sondern aus Schuldigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Dem aber, der nicht Werke tut, aber an Den glaubt, Der den Gottlosen gerecht macht, wird sein Glaube zur Gerechtigkeit gerechnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Wie denn auch David den Menschen selig preist, dem Gott Gerechtigkeit zurechnet ohne Werke:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, 'Selig sind die, denen die Missetaten vergeben und deren Sünden bedeckt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Selig ist der Mann, dem der Herr die Sünde nicht zurechnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Geht nun dieses Seligpreisen auf die Beschneidung oder auch auf die Vorhaut? Denn wir sagen, daß dem Abraham der Glaube zur Gerechtigkeit gerechnet ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Wie ward er ihm nun angerechnet? In der Beschneidung, oder in der Vorhaut? nicht in der Beschneidung, sondern in der Vorhaut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'Und das Zeichen der Beschneidung empfing er als Siegel der Gerechtigkeit des Glaubens in der Vorhaut, auf daß er Vater würde aller derer, die da glauben in der Vorhaut, auf daß auch ihnen die Gerechtigkeit zugerechnet werde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'Und auch Vater der Beschneidung denen, die nicht nur in der Beschneidung sind, sondern auch in die Fußstapfen ihres Vaters Abraham treten, da dieser noch in der Vorhaut Glauben bewies.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Denn nicht durch das Gesetz ist dem Abraham oder seinem Samen die Verheißung geworden, daß er Erbe der Welt werden sollte, sondern durch die Gerechtigkeit des Glaubens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Denn wenn die, welche das Gesetz haben, Erben sind, so ist der Glaube zunichte gemacht und die Verheißung aufgehoben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Weil das Gesetz Zorn bewirkt; wo aber kein Gesetz ist, da ist auch keine Übertretung,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Darum ward sie gegeben wegen des Glaubens, auf daß die Verheißung aus Gnade allem Samen gesichert wäre, nicht allein dem, der unter dem Gesetz ist, sondern auch dem, der den Glauben Abrahams hat, der unser aller Vater ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, 'Wie denn geschrieben steht: Ich habe dich zum Vater vieler Völker gemacht; vor dem Gott, Dem er Glauben schenkte, Der die Toten lebendig macht, und das, was nicht ist, ins Dasein ruft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'Der gegen Hoffnung auf Hoffnung glaubte, daß er Vater vieler Völker werden würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'Und weil er nicht nachließ im Glauben und nicht in Betracht nahm seinen bereits abgestorbenen Leib, weil er schon hundert Jahre alt war, und auf den abgestorbenen Mutterleib der Sarah,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'Zweifelte er nicht ungläubig an der Verheißung Gottes, sondern blieb stark im Glauben, und gab Gott die Ehre;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'Und war voll überzeugt, daß Er, was Er verheißen, auch zu erfüllen die Macht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Darum ward es ihm auch zur Gerechtigkeit gerechnet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Aber es ward nicht allein um seinetwillen geschrieben, daß es ihm zugerechnet wurde, sondern auch um unsertwillen, denn es wird zugerechnet werden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'So wir an Den glauben, Der unseren Herrn Jesus von den Toten auferweckt hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'Der um unserer Übertretungen willen hingegeben ward, und um unserer Rechtfertigung willen auferweckt worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Nun wir denn sind gerechtfertigt aus dem Glauben, so haben wir Frieden mit Gott durch unseren Herrn Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'Durch Den wir auch durch den Glauben Zugang zu dieser Gnade haben, in der wir stehen, und der Hoffnung uns rühmen auf die Herrlichkeit bei Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Nicht allein aber das, sondern wir rühmen uns auch der Drangsale, weil wir wissen, daß die Drangsal Beharrlichkeit erwirkt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'Beharrlichkeit aber bewirkt Bewährung, Bewährung aber Hoffnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'Hoffnung aber läßt nicht zuschanden werden; denn die Liebe Gottes ist ausgegossen in unsere Herzen durch den Heiligen Geist, der uns gegeben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Ist doch Christus, da wir noch schwach waren zur Zeit, für Gottlose gestorben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'Denn für einen Gerechten stirbt nicht leicht jemand; ja für den Guten könnte jemand sein Leben lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Darum erweist Gott Seine Liebe gegen uns, daß Christus, da wir noch Sünder waren, für uns gestorben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Um so viel mehr werden wir, die wir nun durch Sein Blut gerechtfertigt sind, durch Ihn vom Zorn erlöst werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Denn wenn wir, da wir noch Feinde waren, mit Gott durch den Tod Seines Sohnes versöhnt worden sind, werden wir, nunmehr versöhnt, durch Sein Leben beseligt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Nicht allein aber das, sondern wir rühmen uns auch Gottes durch unseren Herrn Jesus Christus, durch Den wir die Versöhnung erlangt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Darum wie durch einen Menschen die Sünde in die Welt gekommen und durch die Sünde der Tod, und ist so der Tod zu allen Menschen hindurchgedrungen, weil sie alle gesündigt haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'Denn bis auf das Gesetz war die Sünde in der Welt; die Sünde wird aber nicht zugerechnet, wo kein Gesetz ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Aber der Tod herrschte von Adam bis auf Moses, auch über die, die nicht in gleicher Übertretung wie Adam gesündigt hatten, der ein Vorbild des Künftigen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Jedoch verhält es sich nicht wie mit der Übertretung ebenso auch mit der Gnadengabe; denn wie durch die Übertretung des einen die vielen gestorben sind, so ist doch um so viel mehr die Gnade und die Gabe Gottes durch die Gnade des einen Menschen, Jesus Christus, den vielen im Übermaß zuteil geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'Und nicht verhält sich die Gnadengabe, wie bei dem einen, der gesündigt hatte; denn die Schuld von dem einen gereichte zur Verdammnis, die Gnadengabe aber nach vielen Übertretungen zur Rechtfertigung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Denn wenn durch des einen Übertretung mittelst des einen der Tod herrschte, so werden um so viel mehr die, welche die Fülle der Gnade und die Gabe der Gerechtigkeit empfangen, durch den einen Jesus Christus im Leben herrschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Wie nun durch eine Übertretung die Verdammnis zu allen Menschen gekommen ist, so ist auch des Einen Rechtfertigung für alle Menschen zur Rechtfertigung des Lebens geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Denn wie durch den Ungehorsam des einen Menschen die vielen Sünder geworden sind, so werden auch durch den Gehorsam des Einen die vielen gerecht gemacht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'Das Gesetz trat noch daneben ein, auf daß die Übertretung gehäuft würde; da aber die Sünde sich häufte, da ward die Gnade noch überschwenglicher,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'Auf daß, wie die Sünde durch den Tod herrschte, also auch die Gnade durch unseren Herrn Jesus Christus durch Gerechtigkeit zum ewigen Leben herrschte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Was sollen wir nun sagen? Sollen wir in der Sünde beharren, auf daß die Gnade überschwenglicher werde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Das sei ferne! Wie sollten wir, die wir der Sünde abgestorben sind, noch in ihr leben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Oder wisset ihr nicht, daß, wie viele von uns auf Jesus Christus getauft worden sind, die sind auf Seinen Tod getauft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Mitbegraben sind wir denn mit Ihm durch die Taufe auf den Tod, auf daß, wie Christus durch die Herrlichkeit des Vaters von den Toten auferweckt worden, also auch wir in einem neuen Leben wandeln;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Denn sind wird durch die Ähnlichkeit des Todes auf das innigste mit Ihm verbunden, so werden wir es auch in der Auferstehung sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'Wir wissen ja, daß unser alter Mensch mitgekreuzigt worden ist, auf daß der Leib der Sünde zerstört würde, damit wir nicht mehr der Sünde dieneten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Denn wer gestorben ist, der ist von der Sünde freigesprochen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Sind wir aber mit Christus gestorben, so glauben wir, daß wir mit Ihm auch leben werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'Indem wir wissen, daß Christus, von den Toten auferweckt, nicht mehr stirbt. Der Tod hat keine Macht mehr über Ihn;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Denn was gestorben ist, ist der Sünde gestorben ein für alle Mal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Also auch ihr: achtet euch der Sünde abgestorben und lebet Gott in Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'So lasset nun die Sünde in eurem sterblichen Leibe nicht herrschen, daß ihr in seinen Lüsten ihr gehorchtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Auch gebt nicht eure Glieder der Sünde zu Werkzeugen der Ungerechtigkeit hin, sondern begebt euch selbst Gott, als die aus Toten lebendig geworden, und eure Glieder zu Werkzeugen der Gerechtigkeit für Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Denn die Sünde wird nicht herrschen über euch, weil ihr nicht unter dem Gesetz seid, sondern unter der Gnade.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Wie nun? sollen wir sündigen, weil wir nicht unter dem Gesetz, sondern unter der Gnade sind? Das sei ferne!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Wisset ihr nicht, daß, wem ihr euch zu Knechten zum Gehorsam begebt, ihr dessen Knechte seid, dem ihr gehorcht? entweder der Sünde, zum Tode; oder des Gehorsams, zur Gerechtigkeit?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'Gott aber sei Dank, daß ihr, die ihr Knechte der Sünde waret, nun von Herzen gehorcht habt der Lehre, die euch zuteil geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'Von der Sünde frei gemacht, seid ihr Knechte der Gerechtigkeit geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Ich spreche auf menschliche Weise zu euch wegen der Schwachheit eures Fleisches; so wie ihr eure Glieder zum Dienst der Unreinheit von einer Gesetzwidrigkeit zur anderen hingegeben hattet, so gebt nun eure Glieder in den Dienst der Gerechtigkeit zur Heiligung hin;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Denn als ihr Knechte der Sünde waret, waret ihr Freie in Hinsicht der Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Welche Frucht hattet ihr da? Solche, deren ihr euch jetzt schämt; denn ihr Ende ist der Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Nun ihr aber von der Sünde frei und Gottes Knechte geworden seid, habt ihr eure Frucht zur Heiligung, ihr Ende aber ist ewiges Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Denn der Sünde Sold ist der Tod, aber die Gnadengabe Gottes ist das ewige Leben in unserem Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Oder wisset ihr nicht, meine Brüder - ich rede zu denen, die das Gesetz kennen - daß das Gesetz über den Menschen herrscht, so lange er lebt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Denn das Weib unter dem Mann ist durch das Gesetz an den Mann gebunden, so lange er lebt. Wenn der Mann aber stirbt, so ist sie von dem Gesetz in bezug auf den Mann entbunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Für eine Ehebrecherin wird sie gelten, wenn sie bei Lebzeiten des Mannes einem anderen Manne sich hingibt; wenn aber der Mann gestorben ist, so ist sie frei von dem Gesetz, so daß sie keine Ehebrecherin ist, wenn sie mit einem anderen Manne lebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'So seid denn auch ihr, meine Brüder, dem Gesetz getötet durch den Leib Christi, auf daß ihr eines anderen seid, des von den Toten Auferweckten, damit wir für Gott Frucht bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Denn da wir im Fleische waren, da waren die Leidenschaften der Sünde, die durch das Gesetz sich regten, in unseren Gliedern wirksam, daß wir dem Tode Frucht brächten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Nun aber sind wir des Gesetzes erledigt, da wir dem, das uns gefangen hielt, gestorben sind; so daß wir im neuen Geiste und nicht im alten Buchstaben dienen sollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Was sollen wir nun sagen? Ist das Gesetz Sünde? Das sei ferne! Aber ich erkannte die Sünde nur durch das Gesetz; denn ich wußte nichts von der Sündhaftigkeit der Lust, wenn das Gesetz nicht sagte: Laß dich nicht gelüsten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Die Sünde nahm Anlaß von dem Gebot, und erregte in mir jegliche Lust, denn ohne Gesetz war die Sünde tot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'So lebte ich denn ohne das Gesetz; da aber das Gebot kam, lebte die Sünde in mir auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'Da starb ich hin, und es fand sich, daß das Gebot für das Leben mir zum Tode ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Denn die Sünde ward veranlaßt durch das Gebot und verführte mich und tötete mich durch dasselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'So ist denn allerdings das Gesetz heilig, und das Gebot heilig und gerecht und gut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Ist also, was gut war, für mich zum Tode geworden? das sei ferne! aber die Sünde; auf daß sie als Sünde erscheine, indem sie durch das Gute den Tod bewirkte, und damit die Sünde durch das Gebot noch viel sündiger würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Denn wir wissen, daß das Gesetz geistig ist, ich aber bin fleischlich, unter die Sünde verkauft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Denn, was ich tue, weiß ich nicht; denn ich tue nicht, was ich will, sondern was ich hasse, das tue ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Wenn ich nun das, was ich nicht will, tue, so stimme ich dem Gesetz bei, daß es recht ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'So tue denn nicht mehr ich dasselbe, sondern die Sünde, die in mir wohnt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Denn ich weiß, daß Gutes nicht in mir wohnt, das heißt in meinem Fleische; denn das Wollen ist vorhanden bei mir, das Vollbringen des Rechten finde ich nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Denn das Gute, das ich will, das tue ich nicht, sondern das Böse, das ich nicht will, das tue ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'So ich aber tue, was ich nicht will, so tue nicht ich dasselbe mehr, sondern die Sünde, die in mir wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'So finde ich nun in mir, der ich das Rechte tun will, das Gesetz, daß mir das Böse anhängt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Denn ich habe Lust an Gottes Gesetz nach dem inwendigen Menschen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'Ich sehe aber ein anderes Gesetz in meinen Gliedern, das dem Gesetz meiner Vernunft entgegenkämpft und mich gefangennimmt unter das Gesetz der Sünde, das in meinen Gliedern gilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Ich elender Mensch, wer wird mich erlösen von dem Leibe dieses Todes?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Ich danke Gott durch unseren Herrn Jesus Christus; ich diene mit meiner Vernunft dem Gesetz Gottes, mit dem Fleisch aber dem Gesetz der Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'So gibt es denn keine Verdammnis für die, so in Jesus Christus sind, weil sie nicht nach dem Fleisch, sondern nach dem Geist wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Denn das Gesetz des Geistes, des Lebens in Jesus Christus, hat mich frei gemacht von dem Gesetz der Sünde und des Todes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Denn was dem Gesetz unmöglich war, weil es durch das Fleisch geschwächt war, das tat Gott, und sandte Seinen Sohn in der Gestalt des sündhaften Fleisches, und um der Sünde willen verurteilte Er die Sünde in dem Fleisch;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'Auf daß die Rechtfertigung des Gesetzes an uns, die wir nicht nach dem Fleisch, sondern nach dem Geist wandeln, erfüllt würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Denn die da nach dem Fleisch sind, die sind fleischlich gesinnt, die aber nach dem Geist sind, die sind geistlich gesinnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Denn fleischlich gesinnt sein ist Tod, geistlich gesinnt sein aber ist Leben und Friede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'Weil fleischlich gesinnt sein ist, eine Feindschaft wider Gott, da es sich nicht dem Gesetz Gottes unterwirft, und es auch nicht kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Die aber im Fleisch sind, können Gott nicht gefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'Ihr aber seid nicht im Fleisch, sondern im Geist, wenn anders der Geist Gottes in euch wohnt; wenn aber einer Christi Geist nicht hat, so ist er nicht Sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Ist aber Christus in euch, so ist der Leib zwar tot um der Sünde willen, der Geist aber ist Leben um der Gerechtigkeit willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'So aber der Geist Dessen, Der Jesus von den Toten auferweckt hat, in euch wohnt, so wird Der, Der Christus von den Toten auferweckt hat, auch eure sterblichen Leiber lebendig machen durch Seinen Geist, der in euch wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Deshalb sind wir, meine Brüder, nicht dem Fleisch schuldig, nach dem Fleisch zu leben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'Denn wenn ihr nach dem Fleisch lebt, so werdet ihr sterben; so ihr aber durch den Geist die Werke des Fleisches tötet, werdet ihr leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Denn die vom Geist Gottes angetrieben werden, sind alle Gottes Kinder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Denn ihr habt nicht den Geist der Knechtschaft empfangen, um euch wieder zu fürchten, sondern ihr habt den Geist der Kindschaft empfangen, in dem wir Abba, Vater! rufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Derselbe Geist gibt Zeugnis unserem Geist, daß wir Kinder Gottes sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Sind wir denn Kinder, so sind wir auch Erben, Erben Gottes und Miterben Christi, wenn wir anders mit Ihm leiden, auf daß wir mit Ihm auch verherrlicht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Denn ich halte dafür, daß dieser Zeit Leiden nicht wert sind der Herrlichkeit, die an uns soll geoffenbart werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Denn das Harren der Schöpfung wartet auf die Offenbarung der Kinder Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Weil die Schöpfung der Nichtigkeit unterworfen ward, nicht aus eigener Wahl, sondern von Dem, Der sie derselben unterwarf, auf Hoffnung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'Daß auch sie, die Schöpfung, von der Knechtschaft der Vergänglichkeit befreit, und in die Freiheit der Herrlichkeit der Kinder Gottes werden würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Denn wir wissen, daß bisher noch die ganze Schöpfung mit stöhnt, und mit im Kreißen begriffen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Nicht allein aber sie, sondern auch wir selbst, die wir des Geistes Erstlinge haben, auch wir stöhnen, indem wir der Kindschaft der Erlösung unseres Leibes harren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'Denn wir sind zwar gerettet in der Hoffnung; die Hoffnung aber, die man sieht, ist keine Hoffnung, denn wie kann man das hoffen, was man schon sieht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'So wir aber auf das hoffen, was wir nicht sehen, so warten wir mit Beharrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Gleichermaßen aber hilft auch der Geist unseren schwachen Zuständen auf; denn wir wissen nicht, um was wir beten sollen, wie es sich gebührt, aber der Geist selbst verwendet sich für uns mit unaussprechlichem Seufzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Der aber die Herzen erforscht, weiß, wie der Geist gesinnt ist, weil er die Heiligen Gott gefällig vertritt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Wir wissen aber, daß denen, die Gott lieben, alle Dinge zum Besten dienen, denen, die nach Ratschluß berufen sind;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Denn die, welche Er zuvor erkannt hatte, bestimmte Er auch voraus, daß sie gleich gestaltet sein sollten dem Ebenbilde Seines Sohnes, auf daß Er der Erstgeborene unter vielen Brüdern wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'Welche Er aber voraus bestimmt hatte, diese berief Er auch, und die Er berufen hatte, die hat Er auch gerechtfertigt, die Er aber gerechtfertigt, die hat Er auch verherrlicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Was wollen wir nun dazu sagen? Ist Gott für uns, wer mag wider uns sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'Wie sollte Er, Der Seines eigenen Sohnes nicht verschont, sondern Ihn für uns alle dahingegeben hat, wie sollte Er uns mit Ihm nicht alles schenken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Wer wird die Auserwählten Gottes anklagen? Gott ist es, Der da gerecht macht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Wer will verdammen? Christus ist hier, Der gestorben ist, ja vielmehr Der auch auferweckt ist, und zur Rechten Gottes ist und uns vertritt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Wer will uns scheiden von der Liebe Christi? Trübsal, oder Angst, oder Verfolgung, oder Hunger, oder Blöße, oder Gefahr, oder Schwert?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Wie denn geschrieben steht: Um deinetwillen werden wir den ganzen Tag hingemordet, sind wir wie Schlachtschafe geachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Aber in alledem siegen wir überschwenglich durch Ihn, Der uns geliebt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Ja, ich bin des Glaubens, daß weder Tod noch Leben, weder Engel, noch Herrschaften, noch Gewalten, weder Gegenwärtiges, noch Zukünftiges,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'Weder Hohes, noch Niederes, noch irgendein Geschöpf uns scheiden kann von der Liebe Gottes, die in unserem Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Ich sage die Wahrheit in Christus: Ich lüge nicht, mein Gewissen ist mein Zeuge im Heiligen Geist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'Daß ich großen Schmerz habe und ohne Unterlaß bekümmert bin in meinem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Denn gerne wollte ich mich verbannen lassen von Christus für meine Brüder, die mir dem Fleische nach verwandt sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'Die da sind von Israel, welche die Kindschaft und Herrlichkeit und den Bund und die Gesetzgebung und den Gottesdienst und die Verheißungen haben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'Denen die Väter angehören, und von denen dem Fleische nach Christus herkommt, Der da Gott ist über alle, hochgelobt in Ewigkeit! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Aber dem ist nicht also, daß Gottes Verheißung darum aus sei; denn nicht alle von Israel sind Israel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'Auch sind nicht alle Kinder, weil sie von Abrahams Samen sind, sondern: nach Isaak soll der Same dir genannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'Das ist: nicht die dem Fleische nach Kinder sind, sind damit Gottes Kinder, sondern die Kinder der Verheißung werden für Samen gerechnet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Denn dies ist ein Wort der Verheißung: Um diese Zeit will Ich wiederkommen, und Sarah soll einen Sohn haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Und dies nicht allein, sondern auch Rebecka, die von einem, unserem Vater Isaak, empfangen hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Denn noch ehe sie geboren waren und weder Gutes noch Böses getan hatten');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'Der Größere soll dem Kleineren dienstbar werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Wie denn geschrieben steht: Jakob habe Ich geliebt, Esau aber gehaßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Was wollen wir nun sagen: Ist Gott ungerecht? Das sei ferne!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Denn zu Moses spricht Er: Wem Ich gnädig bin, dem bin Ich gnädig, und wessen Ich Mich erbarme, dessen erbarme Ich Mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'So kommt es also nicht auf den Wollenden oder Laufenden, sondern auf den erbarmenden Gott an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Denn die Schrift sagt zu Pharao: Eben darum habe Ich dich erweckt, daß Ich an dir Meine Macht zeige und Mein Name auf der ganzen Erde verkündigt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Er erbarmt Sich nun, wessen Er will, und verstockt, wen Er will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Du wirst nun zu mir sagen: Was schilt Er denn einen? Denn wer konnte jemals Seinem Willen widerstehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Wer bist du denn, Mensch, der du mit Gott rechten willst? Spricht je ein Werk zu seinem Meister: Warum machtest du mich so?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Oder hat der Töpfer nicht Macht über den Ton, aus demselben Teige ein Gefäß zu Ehren, ein anderes zu Unehren zu machen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Wenn nun Gott Zorn zeigen und Seine Macht kundtun wollte, so hat Er mit aller Langmut getragen Gefäße des Zorns, die zur Verdammnis zugerichtet waren,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'Und auf daß Er kund täte den Reichtum Seiner Herrlichkeit an Gefäßen der Barmherzigkeit, die Er voraus zur Herrlichkeit bereitet hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'Als welche Er uns auch berufen hat, nicht bloß aus den Juden, sondern auch aus den Heiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'Wie Er denn auch im Hoschea spricht: Ich will Mein Volk nennen, das nicht Mein Volk war, und die Nichtgeliebte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'Und soll geschehen an dem Ort, da ihnen gesagt ward: Ihr seid nicht Mein Volk, daß sie sollen Söhne des lebendigen Gottes genannt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Jesajah aber ruft über Israel, wenn auch die Zahl der Söhne Israels wie der Sand am Meer wäre, so wird doch nur ein Überrest gerettet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Denn Er vollendet den Spruch und faßt ihn kurz in Gerechtigkeit; denn den kurzgefaßten Spruch vollbringt der Herr auf der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'Und wie Jesajah vorausgesagt hat: Wenn uns der Herr Zebaoth nicht Samen übriggelassen hätte, so wären wir wie Sodom und Gomorrah gleich geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Was wollen wir nun sagen? Daß die Heiden, die nicht nach Gerechtigkeit strebten, Gerechtigkeit erlangten, Gerechtigkeit aber, die aus dem Glauben kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'Israel aber hat nach dem Gesetz der Gerechtigkeit gestrebt, und ist nicht zum Gesetz der Gerechtigkeit gelangt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Warum? Darum, daß sie nicht aus dem Glauben, sondern aus Werken des Gesetzes dieselbe suchten. Sie haben sich an dem Stein des Anstoßes gestoßen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'Wie denn geschrieben steht: Siehe, Ich setze in Zion den Stein des Anstoßes und den Fels des Ärgernisses, und wer an ihn glaubt, der soll nicht zuschanden werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Meines Herzens Wunsch, Brüder, und mein Flehen zu Gott ist für das Heil Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Denn ich gebe ihnen das Zeugnis, daß sie für Gott eifern, aber mit Unverstand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Denn sie kennen die Gerechtigkeit Gottes nicht, und suchen die eigene Gerechtigkeit aufzurichten, und haben sich so der Gerechtigkeit Gottes nicht unterworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Das Ende des Gesetzes ist Christus zur Gerechtigkeit für einen jeden, der an Ihn glaubt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Denn Moses schreibt wohl von der Gerechtigkeit aus dem Gesetz: Welcher Mensch diese Dinge tut, der wird durch sie leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Die Gerechtigkeit aus dem Glauben aber spricht also: Sprich nicht in deinem Herzen: Wer will hinauffahren gen Himmel? Das heißt: Christus herabzuholen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'Oder wer will hinab in den Abgrund fahren? Das heißt: Christus von den Toten heraufzuholen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Aber was sagt sie? Das Wort ist dir nahe in deinem Munde und in deinem Herzen, das ist das Wort des Glaubens, das wir predigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Wenn du mit deinem Munde Jesus als den Herrn bekennst, und in deinem Herzen glaubst, daß Ihn Gott von den Toten auferweckt hat, so wirst du selig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'Denn so man mit dem Herzen glaubt, so wird man gerecht, und so man mit dem Munde bekennt, so wird man selig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Denn die Schrift sagt: Ein jeder, der auf Ihn vertraut, wird nicht zuschanden werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Es ist ja kein Unterschied zwischen dem Juden und dem Griechen; alle haben denselben Herrn, Der reich ist für alle, die Ihn anrufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Denn jeder, der den Namen des Herrn anruft, soll gerettet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Denn wie werden sie einen anrufen, an den sie nicht glauben? Wie werden sie glauben an einen, von dem sie nicht gehört haben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'Wie werden sie von einem hören ohne einen, der ihnen predigt? Wie wird man ihnen predigen, wenn man nicht abgeordnet ist, wie denn geschrieben steht: Wie lieblich sind die Füße derer, die da Frieden verkündigen, die da gute Botschaft bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Allein nicht alle haben auf die gute Botschaft gehört, denn Jesajahs spricht: Herr, wer hat auf unsere Botschaft gehört?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Der Glaube kommt aus der Verkündigung, die Verkündigung aber aus dem Worte Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Ich aber sage: Haben sie es etwa nicht gehört? Ihr Stimme ist in alle Lande ausgegangen, und ihre Worte bis an der Welt Enden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Ich aber sage: Hat sie Israel nicht erkannt? Gleich Moses spricht: Ich will euch eifern lassen gegen ein Volk, das nicht Mein Volk ist, gegen ein unverständig Volk sollt ihr in Zorn geraten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'Jesajahs sagt gar: Ich ward gefunden von denen, die Mich nicht suchten, und ward offenbar denen, die nicht nach Mir fragten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Zu Israel aber spricht Er: Den ganzen Tag habe Ich Meine Hände ausgereckt gegen ein Volk, das Mir nicht gehorchen will und widerspricht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'So sage ich nun: Hat Gott Sein Volk verstoßen? Mitnichten, ich bin ja selbst ein Israelite vom Samen Abrahams, aus dem Stamme Benjamin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Gott hat Sein Volk, das Er zuerst auserwählt hatte, nicht verstoßen; oder wißt ihr nicht, was die Schrift bei Elias sagt, wie er vor Gott gegen Israel auftritt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, 'Herr, Deine Propheten haben sie getötet und Deine Altäre umgestürzt, und ich bin allein übriggeblieben, und auch mir stehen sie nach dem Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Was wird ihm aber zur Antwort? Ich habe Mir übriggelassen siebentausend Männer, die ihre Knie vor dem Baal nicht gebeugt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'So ist nun auch in der jetzigen Zeit nach der Auswahl der Gnade ein Überrest geblieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Ist es aber aus Gnade, so ist es nicht der Werke wegen, da die Gnade sonst aufhört, Gnade zu sein. Wenn aber um der Werke willen, so ist es nicht mehr Gnade, sonst ist das Werk nicht mehr Werk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Wie nun? Was Israel sucht, das hat es nicht erlangt, die Auswahl aber hat es erlangt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'Die übrigen sind verstockt geblieben, wie denn geschrieben steht: Gott hat ihnen den Geist der Betäubung gegeben, Augen, daß sie nicht sehen, und Ohren, daß sie nicht hören, bis auf den heutigen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'Und David spricht: Ihr Tisch werde ihnen zum Fallstrick und zur Berückung und zum Anstoß und zur Vergeltung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'Laß ihre Augen sich verdunkeln, daß sie nicht sehen, und beuge allezeit ihren Rükken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Ich sage nun: Mußten sie darum straucheln, daß sie fallen sollten? Das sei ferne! Vielmehr kam durch ihren Fall das Heil zu den Heiden, auf daß sie ihnen nacheifern sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Wenn aber ihr Fall der Reichtum der Welt geworden ist, und ihre geringe Zahl den Heiden zugute kam, um wie viel mehr würde ihre Vollzahl zugute kommen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'Euch, den Heiden, sage ich: Weil ich Heidenapostel bin, will ich mein Amt preisen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'Ob ich etwa mein Fleisch zum Eifer reizen und etliche derselben retten könnte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Denn wenn ihre Verwerfung die Erlösung der Welt geworden ist, was wird ihre Annahme anderes werden, denn ein Aufleben vom Tode?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Ist das Erstlingsbrot heilig, so wird der Teig heilig, und ist die Wurzel heilig, so sind es auch die Zweige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Sind nun etliche der Zweige ausgebrochen, und du, der du vom wilden Ölbaum bist, wirst unter sie gepfropft, und bist der Wurzel und der Fettigkeit des Ölbaums teilhaftig geworden, so rühme dich nicht wider die Zweige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'Rühmst du dich aber wider sie, so trägst du ja die Wurzel nicht, sondern die Wurzel dich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Du wirst wohl sagen: Zweige wurden abgeschnitten, auf daß ich eingepfropft würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Schon recht, sie wurden ihres Unglaubens wegen ausgeschnitten, du aber stehst durch deinen Glauben. Überhebe dich nicht, sondern sei auf deiner Hut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Denn wenn Gott der naturwüchsigen Zweige nicht verschonte, so möchte Er auch dein nicht verschonen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'So siehe denn die Güte und die Strenge Gottes an - gegen die Gefallenen die Strenge, gegen dich die Güte, wenn du bei der Güte verbleibst, sonst wirst auch du ausgeschnitten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Und jene, wenn sie nicht bei ihrem Unglauben verbleiben, werden eingepfropft werden: Gott kann sie ja wohl wieder einpfropfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Denn wenn du aus dem von Natur wilden Ölbaum ausgeschnitten und gegen deine Natur auf den edlen Ölbaum gepfropft worden bist, um wieviel mehr können nicht ursprünglich edle Zweige in ihren eigenen Ölbaum eingepfropft werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Denn ich will euch, Brüder, das Geheimnis nicht vorenthalten auf daß ihr euch nicht selbst für klug haltet, daß von seiten eines Teils bei Israel eine Verstockung eingetreten ist, bis daß die Vollzahl der Heiden eingegangen wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'Und so wird dann ganz Israel erlöst werden, wie geschrieben steht: Aus Zion wird kommen, Der da erlöse, und abwenden von Jakob die Gottlosigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'Das ist Mein Bund mit ihnen, wenn Ich ihre Sünden werde weggenommen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'In Hinsicht des Evangeliums sind sie Feinde um euretwillen, nach der Auswahl aber sind sie geliebt um der Väter willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Denn Gottes Gnadengaben und Berufung mögen Ihn nicht gereuen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Denn wie ihr einst Gott nicht glaubtet, nun aber Erbarmung fandet durch den Unglauben dieser,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'So sind auch diese nun ungläubig geworden, auf daß durch das Erbarmen gegen euch auch sie Erbarmung fänden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Denn Gott hatte alle unter den Unglauben beschlossen, auf daß Er Sich ihrer aller erbarmete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'O! welche Tiefe des Reichtums und der Weisheit und Erkenntnis Gottes! Wie unerforschlich sind Seine Gerichte und wie unergründlich sind Seine Wege!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Denn wer hat des Herrn Sinn erkannt, oder wer ist Sein Ratgeber gewesen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'Oder wer hat Ihm vorhergegeben, daß Ihm vergolten würde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Denn von Ihm und durch Ihn und für Ihn sind alle Dinge; Ihm sei Ehre in Ewigkeit! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Ich ermahne euch nun, Brüder, durch die Barmherzigkeit Gottes, daß ihr eure Leiber hingebet, als ein lebendiges, heiliges, Gott wohlgefälliges Opfer zu eurem geistigen Gottesdienst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'Und stellet euch nicht dieser Welt gleich, sondern bildet euch um durch die Erneuerung eures Sinnes, auf daß ihr prüfen möget, welches da sei der gute, der wohlgefällige und der vollkommene Gotteswille.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Denn ich sage vermöge der mir verliehenen Gnade einem jeglichen unter euch, daß er nicht weiter von sich halte, denn sich es gebührt zu halten, sondern daß er sich bescheiden soll, je nach dem Maß des Glaubens, das ihm Gott zugeteilt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Denn gleich wie wir an dem einen Körper viele Glieder, alle Glieder aber nicht die gleiche Verrichtung haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'Also sind wir viele ein Leib in Christus, aber jeder einzelne ist des anderen Glied,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Indem wir je nach der uns verliehenen Gnade verschiedene Gaben haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'Hat jemand die Gabe der Weissagung, so geschehe sie nach dem Maß seines Glaubens. Hat jemand ein Amt, so warte er des Amtes. Hat er zu lehren, so warte er der Lehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'Oder ermahnt einer, so ermahne er treulich. Hat einer von dem Seinen milde Gaben zu geben, so gebe er in Einfalt. Hat er vorzustehen, so tue er es mit Eifer. Hat er für Leidende zu sorgen, so tue er es mit Freundlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Eure Liebe sei ungeheuchelt, verabscheut das Böse, hanget dem Guten an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Eure Bruderliebe untereinander sei herzlich. Gehe einer dem anderen voran in der Achtung gegen ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'Lasset nicht nach an Eifer. Seid brünstig im Geist. Schicket euch in die Zeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'Seid fröhlich in Hoffnung, geduldig in Trübsal, haltet an am Gebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'Nehmt euch der Notdurft der Heiligen an, fleißiget euch der Gastfreundschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Segnet, die euch verfolgen! Segnet, und verwünschet nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Seid fröhlich mit den Fröhlichen, und weinet mit den Weinenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Seid einträchtig untereinander. Trachtet nicht nach Hohem, sondern haltet euch zu den Niedrigen. Bildet euch nicht zu viel ein auf euch selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Vergeltet niemand Böses mit Bösem. Befleißigt euch des Guten vor aller Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Womöglich haltet, so viel an euch ist, mit allen Menschen Frieden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Rächt euch nicht selbst, Geliebte, sondern gebt Raum dem Zorne; denn es steht geschrieben: Mein ist die Rache; Ich will vergelten, spricht der Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'So nun deinen Feind hungert, so speise ihn, dürstet ihn, so tränke ihn; denn wenn du das tust, wirst du feurige Kohlen auf sein Haupt sammeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Laß dich nicht das Böse überwinden, sondern überwinde das Böse mit Gutem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Jedermann sei untertan den Obrigkeiten, die Gewalt über ihn haben; denn es ist keine Obrigkeit außer von Gott. Und die bestehenden Obrigkeiten sind von Gott verordnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Wer sich daher der Obrigkeit widersetzt, widerstrebt der Ordnung Gottes; die aber widerstreben, ziehen sich selbst ihr Urteil zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Denn die Gewalt haben, sind nicht den guten Werken, sondern den bösen ein Schrekken. Willst du die Gewalt nicht fürchten, so tue Gutes, und du wirst noch Lob von ihr haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Denn sie ist Gottes Dienerin dir zu Gute; tust du aber Böses, so fürchte dich; denn nicht umsonst führt sie das Schwert; denn sie ist Gottes Dienerin, eine Rächerin zur Strafe für den, der das Böse tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Darum tut es Not, daß man untertan ist, nicht allein um der Strafe willen, sondern auch aus Gewissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Deshalb zahlt ihr ja auch Steuern; denn sie sind Gottes Dienstleute, die ihres Amtes warten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'So gebt nun allen, was ihr zu geben schuldig seid: Steuer dem, der die Steuer, Zoll dem, der den Zoll, Ehrerbietung dem, der Ehrerbietung, Achtung dem, der Achtung zu fordern hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Bleibt niemand etwas schuldig, außer daß ihr einander liebet, denn wer den anderen liebt, hat das Gesetz erfüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Denn die Gebote: Du sollst nicht ehebrechen, nicht töten, nicht stehlen, kein falsch Zeugnis reden, dich nicht gelüsten lassen, und so noch ein anderes Gebot ist, sind in dem einen zusammengefaßt: Du sollst deinen Nächsten lieben wie dich selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Die Liebe tut dem Nächsten nichts Böses; so ist nun die Liebe des Gesetzes Erfüllung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'Und dies darum, da wir die Zeit wissen, daß bereits die Stunde da ist, daß wir aus dem Schlaf erwachen; denn jetzt ist uns das Heil näher, als da wir gläubig wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Die Nacht ist vorbei, der Tag ist herbeigekommen; so laßt uns nun die Werke der Finsternis von uns tun und die Rüstung des Lichts anlegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Lasset uns ehrbar wandeln, als am Tage, nicht in Schmausereien und Trinkgelagen, nicht in Unzucht und Schwelgerei, nicht in Hader und Eifersucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'Laßt uns vielmehr den Herrn Jesus Christus anziehen, und nicht den Wollüsten des Fleisches dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'Den Schwachen im Glauben nehmt auf, ohne Streit über Meinungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Der eine glaubt, alles essen zu dürfen, der Schwächere ißt nur Gemüse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Wer da ißt, verachte den nicht, der nicht ißt; der aber nicht ißt, richte den nicht, der da ißt; denn Gott hat ihn angenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Wer bist du, daß du einen fremden Knecht richtest? Seinem eigenen Herrn steht oder fällt er, er wird aber wohl stehend erhalten werden; denn Gott vermag ihn aufrecht zu erhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Der eine entscheidet sich für einen Tag vor dem anderen; der andere hält jeden Tag gleich heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Der auf den Tag hält, tut es dem Herrn, und wer nicht auf den Tag hält, hält nicht darauf, auch dem Herrn. Wer da ißt, ißt dem Herrn, denn er dankt Gott, und wer nicht ißt, ißt nicht, auch dem Herrn, und dankt Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Denn keiner von uns lebt ihm selber und keiner stirbt ihm selber.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Leben wir, so leben wir ja dem Herrn, und sterben wir, so sterben wir dem Herrn; wir mögen also leben oder sterben, so sind wir des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'Denn dazu ist Christus auch gestorben und auferstanden und wieder in das Leben getreten, daß Er sowohl über Tote als Lebendige Herr sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Du aber, was richtest du deinen Bruder? oder auch du, was verachtest du deinen Bruder? Wir werden ja alle vor den Richterstuhl Christus treten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Denn es steht geschrieben: So wahr Ich lebe, spricht Jehovah, alle Knie sollen sich Mir beugen, und alle Zungen Gott bekennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'So wird denn ein jeglicher von uns für sich selber Gott Rechenschaft geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Darum lasset uns nicht mehr einander richten, sondern richtet vielmehr, ob wir nicht dem Bruder Anstoß oder Ärgernis geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Ich weiß und bin überzeugt im Herrn Jesus, daß nichts an und für sich gemein ist, es sei denn für den gemein, der es dafür erachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Wenn aber dein Bruder ob deiner Speise sich betrübt, so wandelst du nicht mehr nach der Liebe. Verdirb doch nicht durch deine Speise den, für den Christus gestorben ist!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Laß darum euer Gutes nicht verlästert werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Denn das Reich Gottes ist nicht Essen und Trinken, sondern Gerechtigkeit und Friede und Freude im Heiligen Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Denn wer darin Christus dient, ist Gott wohlgefällig und den Menschen wert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Laßt uns daher nach dem streben, was zum Frieden und zu gegenseitiger Erbauung dient.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Zerstöre darum nicht der Speise wegen Gottes Werk. Alles ist zwar rein, wird aber zur Sünde dem Menschen, der durch das Essen Anstoß gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Es ist besser, du ißt kein Fleisch und trinkst keinen Wein, und tust nichts, daran dein Bruder Anstoß oder Ärgernis und Schaden nimmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Hast du Glauben? Habe ihn für dich vor Gott! Selig, wer nicht Gericht hält über sich selbst bei dem, was er billigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Wer aber im Zweifel ist, der, wenn er doch ißt, ist verurteilt, weil er nicht aus gutem Glauben gehandelt hat. Alles, was nicht aus Glauben geschieht, ist Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Wir aber, die wir stark sind, sollen die Schwächen der Nichtstarken tragen und nicht aus Selbstgefälligkeit handeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Ein jeder von uns suche seinem Nächsten zu gefallen zum Guten, zur Erbauung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Denn auch Christus hatte nicht an Ihm selber Gefallen, sondern, wie geschrieben steht: Die Schmähungen derer, die dich schmähen, sind auf Mich gefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Denn was vorher geschrieben worden ist, ist uns zur Lehre geschrieben, auf daß wir durch die Beharrlichkeit und die Tröstung der Schriften Hoffnung haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'Der Gott der Beharrlichkeit und des Trostes gebe euch, daß ihr nach dem Sinn von Jesus Christus einträchtig untereinander seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'Auf daß ihr einmütig mit einem Munde Gott und den Vater unseres Herrn Jesus Christus lobet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Darum nehmt einander an, gleich wie auch Christus euch zum Lobe Gottes angenommen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Ich will aber sagen, daß Jesus Christus ein Diener der Beschneidung geworden ist, um der Wahrhaftigkeit Gottes willen, zu bestätigen die Verheißungen an die Väter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'Daß die Heiden aber Gott loben um der Barmherzigkeit willen, wie geschrieben steht: Darum will ich dich loben unter den Heiden und deinem Namen lobsingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'Und abermals heißt es: Frohlocket ihr Heiden mit Seinem Volke!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'Und abermals: Lobet den Herrn alle Völker und lobpreiset Ihn alle Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'Und abermals spricht Jesajah: Es wird da sein die Wurzel Isais, und Der aufstehen wird, zu herrschen über die Heiden. Auf Ihn werden die Heiden hoffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Der Gott der Hoffnung aber erfülle euch mit aller Freude und Frieden im Glauben, daß ihr der Hoffnung durch die Kraft des Heiligen Geistes die Fülle habet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Ich selbst, meine Brüder, bin von euch überzeugt, daß ihr voller Güte seid, erfüllt mit aller Erkenntnis, und im Stande, einander zu ermahnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Doch wollte ich mir herausnehmen, euch freimütig zu schreiben, Brüder, zum Teil, um euch zu erinnern, um der Gnade willen, die mir von Gott verliehen worden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'Daß ich ein Diener von Jesus Christus unter den Heiden sein soll, priesterlich zu wirken am Evangelium Christus, auf daß das Opfer der Heiden genehm sei und durch den Heiligen Geist gesegnet werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Darum darf ich mich rühmen in Jesus Christus, was die Sache Gottes anbelangt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Aber ich vermesse mich nicht, etwas zu sagen, das Christus nicht durch mich gewirkt hätte, um die Heiden durch Wort und Werk gehorsam zu machen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'Durch Kraft der Zeichen und Wunder, und durch die Kraft des Geistes Gottes, so daß ich von Jerusalem und den umliegenden Landen bis nach Illyrien das Evangelium allenthalben verkündigt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'Auch predigte ich geflissentlich das Evangelium nicht da, wo Christus schon verkündigt worden, um nicht auf einen von anderen gelegten Grund zu bauen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'Sondern, wie geschrieben steht, denen nicht zuvor davon verkündet worden, die sollen es sehen, und die nicht davon gehört haben, sollen es vernehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'Darum ich auch vielmal verhindert worden bin, zu euch zu kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Nun ich aber nicht mehr Gelegenheit habe in diesen Gegenden, aber Verlangen trage von vielen Jahren her, zu euch zu kommen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'So hoffe ich, wenn ich nach Spanien gehe, auf der Durchreise euch zu sehen, und allda dorthin ein Geleite von euch zu erhalten, wenn ich mich zuerst meinerseits an euch ersättigt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Jetzt aber reise ich im Dienste für die Heiligen nach Jerusalem.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Denn die in Mazedonien und Achaja fanden sich geneigt, eine gemeinsame Leistung für die Armen der Heiligen in Jerusalem zu leisten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Sie taten so aus freien Stücken, auch sind sie ihre Schuldner; denn da sie die Heiden an ihren geistigen Gütern Teilnehmen ließen, so sind diese auch schuldig, ihnen im Leiblichen zu Hilfe zu kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Wenn ich nun solches ausgerichtet und ihnen den Betrag eingehändigt habe, will ich bei euch durchreisen nach Spanien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Ich weiß aber, daß ich, wenn ich zu euch komme, mit dem vollen Segen des Evangeliums von Christus kommen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Ich bitte euch nun, meine Brüder, bei unserem Herrn Jesus Christus und der Liebe des Geistes, mit mir zu ringen in Gebeten vor Gott für mich,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'Daß ich errettet werde aus den Händen der Ungläubigen in Judäa, und daß meine Dienstleistung in Jerusalem genehm sei den Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'Auf daß ich, so Gott will, in Freuden zu euch komme und mich mit euch erquicke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'Der Gott aber des Friedens sei mit euch allen. Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Ich empfehle euch unsere Schwester Phöbe, welche ist im Dienste der Gemeinde in Kenchreä,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'Daß ihr sie aufnehmt im Herren, so wie es Heiligen geziemt, und ihr beisteht in allem, worin sie eurer Hilfe bedarf; denn sie hat vielen und auch mir Fürsorge geleistet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Grüßet die Prisca und den Aquila, meine Gehilfen in Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'Welche für mein Leben ihre Nacken preisgegeben, denen nicht allein ich danke, sondern auch alle Gemeinden der Heiden] und ihre Haus-Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'Grüßet meinen geliebten Epänetus, welcher ist der Erstling Achajas in Asien an Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Grüßet Maria, die so viele Mühe mit uns gehabt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Grüßet Andronikus und Junias, meine Verwandten und Mitgefangenen, die rühmlich bekannt sind unter den Aposteln und vor mir in Christus gewesen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Grüßet Amplias, meinen Geliebten im Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Grüßet Urbanus, unseren Gehilfen in Christus, und meinen geliebten Stachys.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Grüßet Apelles, den Bewährten in Christus, grüßet die vom Hause des Aristobulus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Grüßet Herodion, meinen Verwandten, grüßet die vom Hause des Narcissus, die in dem Herrn sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Grüßet die Tryphäna und die Tryphosa, die in dem Herrn gearbeitet haben. Grüßet die geliebte Persis, die viel im Herrn gearbeitet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Grüßet Rufus, den Auserwählten im Herrn, und seine und meine Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Grüßet Asynkritus, Phlegon, Hermas, Patrobas, Hermes, und die Brüder bei ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Grüßet Philologus und Julia, Nereus und seine Schwester und Olympas und alle Heiligen bei ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Grüßet euch untereinander mit dem heiligen Kuß. Alle Christengemeinden grüßen euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Ich ermahne euch, Brüder, daß ihr ein Auge habt auf die, so da Spaltungen und Ärgernis wider die Lehre anrichten, die ihr gelernt habt; und kehrt euch ab von ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Denn solche dienen nicht unserem Herrn Christus, sondern ihrem Bauche, und täuschen durch wohlgesetzte Reden und schöne Worte die Herzen der Arglosen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Denn euer Gehorsam ist allen zu Ohren gekommen, darum freue ich mich euer; ich wünsche aber, daß ihr weise seid zum Guten, wie ihr lauter seid in bezug auf das Böse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Aber der Gott des Friedens wird den Satan bald unter eure Füße treten. Die Gnade unseres Herrn Jesus Christus sei mit euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Es grüßen euch Timotheus, mein Mitarbeiter, und Lucius und Jason und Sosipater, meine Verwandten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Ich Tertius, der ich diesen Brief geschrieben habe, grüße euch in dem Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Es grüßt euch Gajus, mein und der ganzen Gemeinde Gastfreund, auch grüßet euch Erastus, der Stadtkämmerer, und der Bruder Quartus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Die Gnade unseres Herrn Jesus Christus sei mit euch allen! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Dem aber, Der euch befestigen kann kraft meines Evangeliums und der Predigt von Jesus Christus, durch die Offenbarung des Geheimnisses, das ewige Zeiten verschwiegen geblieben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'Nun aber geoffenbart und durch die prophetischen Schriften auf Befehl des ewigen Gottes zu gläubiger Annahme allen Heiden kund gemacht worden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'Dem allein weisen Gott sei Ehre durch Jesus Christus in Ewigkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Paulus, durch den Willen Gottes zum Apostel Jesu Christi berufen, und Sosthenes, der Bruder,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'An die Gemeinde Gottes in Korinth, die Geheiligten in Jesus Christus, die berufenen Heiligen, samt allen, die den Namen unseres Herrn Jesus Christus anrufen, an allen Orten, wo sie und wir sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Gnade sei mit euch und Friede von Gott, unserem Vater und Herrn Jesus Christus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Ich danke meinem Gott allezeit eurethalben für die Gnade Gottes, die euch in Jesus Christus verliehen worden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'Daß ihr durch Ihn in allen Stücken reich geworden seid an aller Lehre und aller Erkenntnis;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'Wie denn das Zeugnis von Christus unter euch fest geworden ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'So daß es bei euch an keinerlei Segnung mangelt, weil ihr harret auf die Offenbarung unseres Herrn Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'Der euch auch standhaft erhalten wird bis ans Ende, so daß ihr am Tage unseres Herrn Jesus Christus unsträflich erscheint.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Gott ist getreu, durch Den ihr zur Gemeinschaft mit Seinem Sohn Jesus Christus, unserem Herrn, berufen seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Ich ermahne euch aber, meine Brüder, beim Namen unseres Herrn Jesus Christus, daß ihr alle eines Sinnes seid und keine Spaltungen unter euch aufkommen lasset, sondern daß ihr in gleichem Sinn und gleicher Meinung, zusammenhaltet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Denn mir ist kund geworden über euch durch die von Chloes Haus, daß Streitigkeiten unter euch stattfinden, meine Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Ich aber meine das, daß jeglicher unter euch sagt: Ich halte mich an Paulus, ich an Apollos, ich an Kephas, ich an Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Ist denn Christus geteilt? ist Paulus für euch gekreuzigt worden, oder seid ihr auf des Paulus Namen getauft?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Ich danke Gott, daß ich keinen von euch getauft habe außer Crispus und Gajus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'So daß keiner sagen kann, ich hätte auf meinen Namen getauft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Doch ja, das Haus des Stephanas taufte ich auch, sonst weiß ich keinen anderen, den ich getauft hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Denn Christus hat mich nicht gesandt zu taufen, sondern das Evangelium zu predigen, nicht mit Redeweisheit, auf daß Christus Kreuz nicht leer ausginge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Denn das Wort vom Kreuz ist zwar den Verlorenen eine Torheit, uns aber, den Geretteten, eine Kraft Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Denn es steht geschrieben: Ich will zunichte machen die Weisheit der Weisen und zuschanden den Verstand der Verständigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Wo ist ein Weiser, wo ein Schriftgelehrter, wo ein gelehrter Streiter dieser Welt? Hat nicht Gott die Weisheit dieser Welt zur Torheit gemacht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Denn weil die Welt durch ihre Weisheit Gott in der Weisheit Gottes nicht erkannte, hat es Gott gefallen, durch die Predigt');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Weil die Juden Zeichen fordern und die Griechen nach Weisheit fragen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Wir aber Christus den Gekreuzigten predigen, den Juden ein Ärgernis, den Griechen aber eine Torheit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'Denen selbst aber, die berufen sind, Juden sowohl als Griechen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Denn das Törichte, das von Gott kommt, ist weiser, als die Menschen sind, und das Schwache, das von Gott kommt, ist stärker, als die Menschen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Denn seht eure Berufung an, Brüder; nicht viele sind weise nach dem Fleisch, nicht viele Mächtige, nicht viele Edelgeborene');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'Sondern was töricht ist vor der Welt, hat Gott auserwählt, auf daß Er die Weisen zuschanden mache, und das Schwache vor der Welt hat Gott auserwählt, daß Er das Starke zuschanden mache;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'Und das Unedelgeborene vor der Welt und das für nichts Geachtete und das Geltungslose, auf daß Er zunichte mache, was etwas ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'Auf daß kein Fleisch vor Gott sich rühme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Aus Ihm aber seid ihr in Jesus Christus, Der uns von Gott zur Weisheit, zur Gerechtigkeit, zur Heiligung und Erlösung geworden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'Auf daß, wie geschrieben steht: Wer sich rühmt, sich rühme im Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Auch ich, da ich zu euch kam, bin nicht gekommen mit hoher Rede oder Weisheit, euch das Zeugnis von Gott zu verkündigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Denn ich nahm mir nicht vor, unter euch etwas wissen zu wollen, außer von Jesus Christus und zwar dem Gekreuzigten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'Und ich war vielmehr bei euch in Schwachheit und in viel Furcht und Zittern;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'Und mein Wort und meine Predigt bestand nicht in Überredungen der Weisheit, sondern in Darstellung des Geistes und der Kraft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'Auf daß euer Glaube nicht beruhe auf menschlicher Weisheit, sondern auf der Kraft Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Wir reden aber Weisheit unter Vollkommenen, nicht eine Weisheit dieser Welt, auch nicht der Häupter dieser Welt, die zunichte werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'Wir reden vielmehr Gottes Weisheit, als ein Geheimnis, sie, die verborgen war, die aber Gott vor Anbeginn der Zeitläufe vorherbestimmt hat zu unserer Herrlichkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'Die keiner von den Oberen dieser Welt erkannt hat; denn hätten sie diese erkannt, so hätten sie den Herrn der Herrlichkeit nicht gekreuzigt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, 'Sondern wie geschrieben steht: Was kein Auge gesehen und kein Ohr gehört hat, und in keines Menschen Herz gekommen ist, hat Gott denen, die ihn lieben, zubereitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Uns aber hat es Gott durch Seinen Geist geoffenbart; denn der Geist erforscht alles, auch die Tiefen der Gottheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Denn welcher Mensch weiß, was des Menschen ist, außer der Geist des Menschen, der in ihm ist? So weiß auch niemand, was Gottes ist, außer der Geist Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Wir aber haben empfangen, nicht den Geist der Welt, sondern den Geist aus Gott, auf daß wir wüßten, was uns von Gott verliehen worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'Und das reden wir auch, nicht in Worten, die von menschlicher Weisheit gelehrt, sondern wie sie vom Geist gelehrt worden sind, indem wir Geistiges mit Geistigem verbinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Der natürliche Mensch nimmt nicht an, was vom Geiste Gottes ist, denn es ist ihm eine Torheit, und er kann es nicht erkennen, denn es muß geistig aufgefaßt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Der Geistige beurteilt alles, er selbst aber wird von keinem beurteilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Denn wer hätte des Herrn Sinn erkannt, der Ihn unterwiese? Wir aber haben Christus Sinn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Auch ich, Brüder, konnte nicht mit euch reden als mit Geistigen, sondern als mit Fleischlichen, wie mit Kindern in Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Milch gab ich euch zu trinken, keine');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'Weil ihr noch fleischlich seid; denn da unter euch noch Eifersucht, Streit und Spaltungen sind, seid ihr da nicht fleischlich und wandelt nach Menschenweise?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Denn wenn einer sagt: Ich bin paulisch, ein anderer: Ich bin apollisch, seid ihr da nicht fleischlich?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Wer ist nun Paulus, wer Apollos? Diener sind sie, durch die ihr seid gläubig geworden, wie es einem jeden der Herr gegeben hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'Ich habe gepflanzt, Apollos hat begossen, Gott aber hat das Gedeihen gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'So ist nun weder der da pflanzt, noch der da begießt, etwas, sondern Gott, Der das Gedeihen gibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Der aber pflanzt und der begießt, sind eins, jeder wird seinen Lohn empfangen nach seiner eigenen Arbeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Denn wir sind Gottes Mitarbeiter; Gottes Ackerfeld, Gottes Gebäude seid ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Nach der Gnade Gottes, die mir zuteil geworden, habe ich wie ein weiser Baumeister den Grund gelegt, ein anderer baut darauf, ein jeglicher aber sehe zu, wie er darauf baue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Einen anderen Grund kann keiner legen, als den, der schon liegt, welcher ist Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Wenn einer aber auf diesen Grund baut Gold, Silber, kostbare Steine, Holz, Heu, Stoppel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'So wird eines jeglichen Werk offenbar werden; denn der Tag wird es kundtun, weil es sich durch das Feuer offenbart; und welcherlei eines jeglichen Werk sei, wird das Feuer bewähren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Wenn eines Werk, das er darauf gebaut hat, bleiben wird, wird er Lohn empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'Geht eines Werk im Feuer auf, so wird er dessen verlustig werden; er selbst wird gerettet werden, aber wie durch das Feuer hindurch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Wisset ihr nicht, daß ihr Gottes Tempel seid und der Geist Gottes in euch wohnt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'So einer den Tempel Gottes verdirbt, den wird Gott verderben, denn der Tempel Gottes ist heilig, wie denn auch ihr ein solcher seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Niemand täusche sich; wenn einer vermeint weise zu sein unter euch in dieser Welt, der werde ein Tor, auf daß er');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Denn dieser Welt Weisheit ist Torheit bei Gott; denn es steht geschrieben: Er fängt die Weisen in ihrer List.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'Und abermals: Der Herr kennt die Gedanken der Weisen, daß sie eitel sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Darum rühme sich keiner der Menschen, denn alles ist euer,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'Sei es nun Paulus, oder Apollos, oder Kephas, oder die Welt, oder Leben, oder Tod, Gegenwärtiges, oder Zukünftiges: alles ist euer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'Ihr aber gehört Christus, Christus aber Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Dafür erachte man uns: für Christus Diener und für Verwalter der Geheimnisse Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Übrigens fordert man von den Verwaltern, daß einer treu erfunden werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Mir ist es ein Geringes, daß ich von euch oder von einem menschlichen');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'Ich bin mir wohl nichts bewußt, aber damit bin ich nicht gerechtfertigt; wer mich aber richtet, ist der Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Darum richtet nichts vor der Zeit, bis der Herr komme, Der auch das in Dunkelheit Verborgene an das Licht bringen und die Ratschläge der Herzen offenbaren wird, und dann wird jedem von Gott sein Lob zuteil werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'Dies, meine Brüder, habe ich euretwegen auf mich und Apollos gedeutet, daß ihr an uns lernt, nicht höher von euch zu halten, denn in der Schrift gestattet ist, auf daß sich nicht einer um jemandes willen über den anderen erhebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Denn wer gibt dir den Vorzug? Was hast du, das du nicht empfangen hast? Wenn du es aber empfangen hast, was rühmst du dich, als hättest du es nicht empfangen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Schon gesättigt, schon reich seid ihr geworden, seid ohne uns Könige; und wäret ihr Könige, auf daß wir mit euch herrschten!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Denn mich bedünkt, daß Gott uns, die Apostel, als Geringste, als dem Tod Verfallene dargestellt hat, weil wir der Welt und Engeln und Menschen ein Schauspiel geworden sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Wir sind Toren um Christus willen, ihr aber seid weise in Christus; wir schwach, ihr aber stark; ihr seid hoch geehrt, wir ungeehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Bis auf diese Stunde leiden wir Hunger und Durst, sind nackend, werden geschlagen und haben keine bleibende Stätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'Wir mühen uns ab, arbeiten mit unseren eigenen Händen, werden geschmäht und segnen, werden verfolgt und dulden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'Wir werden gelästert, aber wir flehen');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Nicht schreibe ich dies, um euch zu beschämen, sondern als meine lieben Kinder ermahne ich euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Denn wenn ihr auch zehntausend Zuchtmeister hättet in Christus, so habt ihr doch nicht viele Väter; denn in Jesus Christus habe ich euch gezeugt durch das Evangelium.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Darum ermahne ich euch, ahmt mir nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Deshalb habe ich auch Timotheus zu euch gesandt, der mein geliebtes und treues Kind im Herrn ist; er wird euch erinnern an meine Wege in Christus, wie ich überall in jeglicher Gemeinde lehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Etliche blähen sich auf, in der Meinung, daß ich nicht zu euch käme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Ich werde aber in Bälde zu euch kommen, so der Herr will, und sehen, nicht ihr Gerede, sondern ihre Wirkungskraft;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Denn nicht in Worten, sondern in Kraft besteht das Reich Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Was wollt ihr? Soll ich mit der Rute kommen, oder mit Liebe und dem Geist der Sanftmut?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Überhaupt hört man bei euch von Hurerei und gar von solcher Hurerei, die selbst unter den Heiden nicht zu finden ist, daß einer das Weib seines Vaters habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'Und ihr seid noch aufgeblasen, und habt nicht vielmehr Leid getragen, auf daß der, welcher solches Werk getan hat, aus eurer Mitte geschafft würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Ich wenigstens, obschon mit dem Leibe abwesend, bin im Geiste gegenwärtig, habe bereits als gegenwärtig beschlossen, den, der solches verübt hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'Im Namen unseres Herrn Jesus Christus, mit euch im Geiste versammelt und mit der Kraft unseres Herrn Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'Dem Satan zu übergeben zum Verderben des Fleisches, auf daß der Geist am Tage unseres Herrn Jesus gerettet werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Euer Ruhm ist nicht fein; wisset ihr nicht, daß ein wenig Sauerteig den ganzen Teig durchsäuert!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Darum schafft den alten Sauerteig hinaus, auf daß ihr ein neuer Teig seiet, gleich wie ihr noch ungesäuert seid; denn wir haben auch unser Osterlamm, das für uns geopfert worden, Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'Darum lasset uns Ostern halten, nicht mit dem alten Sauerteig, noch mit dem Sauerteig der Bosheit und des Lasters, sondern mit dem Ungesäuerten der Lauterkeit und Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Ich habe euch in dem Briefe geschrieben, ihr sollt keinen Verkehr mit Hurern haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'Damit meine ich gar nicht Hurer dieser Welt oder Habsüchtige oder Raubgierige oder Götzendiener; denn da müßtet ihr ja aus der Welt scheiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'Jetzt aber schreibe ich euch, ihr sollt keinen Umgang haben mit einem, der sich Bruder nennt, wenn er ein Hurer oder Habsüchtiger oder Götzendiener oder Lästerer oder Trunkenbold oder Raubgieriger ist; mit einem solchen sollt ihr auch nicht einmal essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Denn was sollte ich auch die draußen richten? Richtet ihr nicht, die drinnen sind?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Die draußen wird Gott richten; schafft ihr aus eurer Mitte die, so böse sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Wagt es einer unter euch, der einen Rechtshandel gegen einen anderen hat, zu rechten vor den Ungerechten und nicht vor den Heiligen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Wisset ihr nicht, daß die Heiligen die Welt richten werden? Und wenn durch euch die Welt gerichtet wird, seid ihr da nicht gut genug, auch die geringsten Dinge zu richten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Wisset ihr nicht, daß wir Engel richten werden, wieviel mehr Zeitliches?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Wen ihr nun über Zeitliches Gerichte habt, so setzet ihr die von der Gemeinde für nichts geachteten [Heiden] zu Richtern?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Zur Beschämung sage ich euch das; ist denn gar kein Weiser unter euch, der zwischen Bruder und Bruder richten könnte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Sondern ein Bruder rechtet mit dem Bruder, und dazu vor Ungläubigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Es ist schon überhaupt ein Nachteil für euch, daß ihr Rechtsstreite untereinander habt; warum laßt ihr euch nicht lieber Unrecht tun, warum euch nicht lieber beeinträchtigen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Aber ihr tut Unrecht und übervorteilt, und dazu tut ihr solches an Brüdern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Wisset ihr nicht, daß Ungerechte das Reich Gottes nicht ererben werden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'Lasset euch nicht beirren; weder Hurer, noch Götzendiener, noch Ehebrecher, noch Unenthaltsame, noch Knabenschänder, noch Diebe, noch Habsüchtige, noch Trunkenbolde, noch Lästerer, noch Raubgierige werden das Reich Gottes ererben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'Denn dergleichen waren etliche von euch; aber ihr seid rein gewaschen, geheiligt, und durch den Namen des Herrn Jesus und durch den Geist unseres Gottes gerechtfertigt worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Ich habe Macht zu allem; aber es frommt nicht alles. Ich habe Macht zu allem, aber ich lasse mich nicht davon bewältigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Die Speisen sind für den Magen und der Magen für die Speisen; aber Gott wird diesen und jene vernichten, der Leib aber ist nicht für die Hurerei, sondern für den Herrn und der Herr für den Leib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Gott hat sowohl den Herrn auferweckt, als Er auch uns auferwecken wird durch Seine Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Wisset ihr nicht, daß eure Leiber Christus Glieder sind? Soll ich nun Christus Glieder nehmen und sie zu Hurengliedern machen? Das sei ferne!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Oder wisset ihr nicht, daß, wer einer Hure anhängt, ein Leib mit ihr ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'Wer aber dem Herrn anhängt, ist ein');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Fliehet die Hurerei! Jede Sünde, die ein Mensch begeht, ist außerhalb des Leibes, wer aber hurt, der sündigt wider seinen eigenen Leib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Oder wisset ihr nicht, daß euer Leib ein Tempel des Heiligen Geistes ist, den ihr von Gott habt, und daß ihr nicht euch selbst zugehört?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Denn ihr seid um einen teuren Preis erkauft; darum so preiset Gott an eurem Leib und in eurem Geiste, welche sind Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Was das anlangt, worüber ihr mir geschrieben habt, so ist es dem Menschen gut, wenn er kein Weib berührt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'Der Hurerei wegen aber habe ein jeglicher sein Weib, und eine jegliche habe ihren eigenen Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Der Mann leiste dem Weibe die eheliche Pflicht, desgleichen auch das Weib dem Manne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Das Weib ist seines Leibes nicht mächtig, sondern der Mann, desgleichen auch der Mann seines Leibes nicht mächtig ist, sondern das Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Es entziehe sich keines dem anderen, es sei denn mit gegenseitiger Einwilligung eine Zeitlang, auf daß ihr euch der Andacht widmet; und dann seid wieder beisammen, auf daß euch der Satan wegen eurer Unenthaltsamkeit nicht in Versuchung führe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'Solches sage ich euch empfehlungsweise, nicht als Befehl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Ich wollte zwar, daß alle Menschen wären wie ich; aber ein jeglicher hat seine eigene Gabe von Gott, der eine so, der andere so.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Den Ledigen aber und den Witwen sage ich, es wäre gut für sie, wenn sie bleiben wie ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Wenn sie sich aber nicht enthalten können, so mögen sie freien; denn es ist besser freien, als von Begierde brennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Den Ehelichen aber gebiete nicht ich, sondern der Herr, daß das Weib sich nicht von dem Manne scheide.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, 'Hat sie sich aber geschieden, so bleibe sie unverehelicht, oder sühne sich mit dem Manne aus, und der Mann soll auch sein Weib nicht entlassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Den anderen aber sage ich, nicht der Herr: So ein Bruder ein ungläubiges Weib hat, und sie ist zufrieden bei ihm zu wohnen, der entlasse sie nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'Und ein Weib, das einen ungläubigen Mann hat, trenne sich nicht von ihm, so er sich es gefallen läßt, mit ihr zusammen zu wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Denn der ungläubige Mann ist geheiligt durch das Weib, und das ungläubige Weib ist geheiligt durch den Mann, sonst wären ja eure Kinder unrein; nun aber sind sie heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Will aber der ungläubige Mann sich trennen, so mag er sich trennen; der Bruder oder die Schwester ist in solchen Fällen nicht sklavisch gebunden; denn Gott hat uns im Frieden berufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Denn wie weißt du, Weib, ob du den Mann nicht zum Heile führst? oder weißt du, Mann, ob du dein Weib nicht zum Heile führst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Wie einen jeden Gott begabt hat, wie einen jeden Gott berufen hat, also wandle er, und so verordne ich in allen Gemeinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Ist einer beschnitten berufen, so ziehe er keine Vorhaut; ist er in der Vorhaut berufen, so lasse er sich nicht beschneiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Die Beschneidung ist nichts und die Vorhaut ist nichts, sondern das Halten der Gebote Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Ein jeglicher bleibe in dem Beruf, darin er berufen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Bist du als Knecht berufen, so laß dich es nicht kümmern; kannst du aber frei werden, so mache dir es zu Nutze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Denn wer im Herrn als Knecht berufen ist, der ist ein Freigelassener des Herrn, desgleichen auch einer, der als Freier berufen ist, ist ein Knecht von Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Ihr seid um einen teuren Preis erkauft, werdet nicht Knechte der Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Ein jeder von euch, Brüder, bleibe bei Gott in dem Beruf, darinnen er berufen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Die Jungfrauen anlangend, habe ich kein Gebot vom Herrn, ich will aber, als vom Herrn begnadigt, treu zu sein, meinen Rat erteilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'So meine ich nun, wegen der gegenwärtigen Notstände, es sei gut für den Menschen, so zu bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Bist du an ein Weib gebunden, so suche nicht von ihr loszuwerden; bist du eines Weibes ledig, so suche kein Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'So du aber gefreit hast, so hast du nicht gesündigt, und wenn die Jungfrau gefreit hat, so hat sie nicht gesündigt; Trübsal im Fleisch aber werden solche haben, ich möchte euch gerne verschonen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'So viel aber sage ich, meine Brüder, die Zeit ist kurz; die, welche Weiber haben, seien darum, als hätten sie keine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'Und die da weinen, als weinten sie nicht, und die sich freuen, als freuten sie sich nicht, und die da kaufen, als behielten sie es nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'Und die, so dieser Welt genießen, als genössen sie ihrer nicht; denn die Gestalt dieser Welt vergeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Ich wünschte aber, daß ihr ohne Sorgen wäret. Wer unverheiratet ist, der sorgt für das, was dem Herrn angehört, wie er dem Herrn gefallen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Wer aber gefreit hat, der sorgt für das, was der Welt angehört, wie er dem Weib gefalle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Es ist ein Unterschied zwischen dem Weib und der Jungfrau: Die nicht gefreit hat, sorgt für das, was dem Herrn angehört, daß sie am Leib und Geist heilig sei, die aber gefreit hat, sorgt für das, was der Welt ange- hört, wie sie dem Mann gefalle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'Solches aber sage ich zu eurem Besten, nicht als ob ich euch eine Schlinge überwerfen wollte, sondern weil ihr so anständiger, beharrlicher und ungehindert dem Herrn dienen könnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'Wenn aber einer denkt, es gehe nicht wohl an, daß er seine Tochter zu alt werden lasse, und sie die besten Jahre übergehe, und es mag nicht anders sein, so tue er, was er will, er sündigt nicht, er lasse sie freien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Wenn aber einer fest steht in seinem Sinn, ohne eine Nötigung zu haben, und freien Willen hat, und solches in seinem Herzen beschließt, der tut wohl daran, seine Tochter also bleiben zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Wer daher heiraten läßt, der tut wohl, und wer nicht heiraten läßt, tut besser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Ein Weib ist gebunden, solange ihr Mann lebt; wenn aber ihr Mann entschläft, so ist sie frei und kann heiraten wen sie will, nur daß es im Herrn geschehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Doch ist sie nach meiner Meinung glücklicher, wenn sie so bleibt, ich denke aber auch den Geist Gottes zu haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Das Götzenopfer anlangend, wissen wir,-daß wir alle Erkenntnis haben; die Erkenntnis aber bläht auf, die Liebe erbaut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'So aber jemand sich dünken läßt, er wisse etwas, der hat noch nicht einmal erkannt, wie man etwas erkennen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'So aber jemand Gott liebt, der ist von Ihm erkannt. -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'So wissen wir nun vom Essen der Götzenopfer, daß ein Götze nichts ist in der Welt, und daß es keinen anderen Gott gibt, als den Einen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Denn obgleich es dem Namen nach sowohl im Himmel als auf Erden welche gibt wie es denn viele Götter und viele Herren gibt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'So haben wir doch nur einen Gott, den Vater, von Dem alle Dinge sind und wir in Ihm, und einen Herrn, Jesus Christus, durch Den alle Dinge sind, und wir durch Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Aber nicht in allen ist die Erkenntnis; denn etliche essen noch das Opferfleisch mit der Vorstellung, daß es Götzen gäbe, und ihr noch schwaches Gewissen wird dadurch befleckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Das Essen gibt vor Gott keinen Wert; denn wenn wir essen, sind wir nicht mehr, noch sind wir geringer, wenn wir nicht essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Seht aber zu, daß die Freiheit, die ihr euch erlaubt, den Schwachen nicht zum Anstoß werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Denn so einer dich, der du die Erkenntnis hast, in einem Götzentempel zu Tische sieht, wird nicht sein Gewissen, da er noch schwach ist, veranlaßt werden Götzenopfer zu speisen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Und so kommt über deiner Erkenntnis der schwache Bruder, für den Christus gestorben, zu Fall.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Wenn ihr aber so gegen eure Brüder sündigt und verletzt ihr noch schwaches Gewissen, so sündigt ihr an Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Darum, so mein Essen meinem Bruder ein Ärgernis gibt, so wollte ich nimmermehr Fleisch essen, auf daß ich meinem Bruder kein Ärgernis gebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Bin ich nicht frei? Bin ich nicht ein Apostel? Habe ich nicht Jesus Christus, unseren Herrn, gesehen? Seid ihr nicht mein Werk im Herrn?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Bin ich anderen nicht Apostel, so bin ich es doch euch; denn das Siegel meines Apostelamtes seid ihr in dem Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Solches ist meine Verantwortung gegen die, so mich richten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Haben wir nicht die Freiheit, zu essen und zu trinken?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Haben wir nicht auch das Recht, eine Schwester als Weib mit umher zu führen, wie auch die anderen Apostel und die Brüder des Herrn und Kephas tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Oder haben wir, ich und Barnabas, allein nicht das Recht, nicht zu arbeiten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Wer zieht ins Feld mit eigener Beköstigung? Wer pflanzt einen Weinberg und ißt nicht von seiner Frucht? Oder wer hütet nicht eine Herde und genießt nicht von der Milch der Herde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Sage ich dies nur nach Menschenweise, oder sagt es nicht auch das Gesetz?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'In Moses Gesetz steht geschrieben: Du sollst dem Ochsen, der da drischt, nicht das Maul verbinden. Sorget Gott für die Ochsen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Oder sagt er es vielmehr um unsertwillen? Von uns ja steht geschrieben, daß, der da pflügt, soll auf Hoffnung pflügen, und der da drischt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Wenn wir für euch das Geistige gesät haben, ist es da etwas Großes, wenn wir von euch euer Leibliches ernten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Wenn andere dieses Recht bei euch genießen, warum nicht vielmehr wir? Aber wir haben solches Recht nicht angesprochen, sondern halten alles aus, auf daß wir dem Evangelium Christi kein Hindernis bereiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Wisset ihr nicht, daß die, so für das Heiligtum arbeiten, vom Tempel gespeist werden? die so des Altars warten, ihren Anteil am Altaropfer haben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Also hat auch der Herr verordnet, daß die, so das Evangelium verkündigen, vom Evangelium leben sollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Ich aber habe deren nichts angesprochen, ich schreibe das nicht, daß es mit mir also gehalten werden sollte, denn es wäre mir lieber, ich stürbe, als daß mir einer meinen Ruhm zunichte machte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Denn wenn ich das Evangelium predige, habe ich keinen Ruhm, denn ich muß so tun; denn wehe mir, wenn ich es nicht sollte predigen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Tue ich es gerne, so habe ich Lohn; tue ich es ungern, so bin ich doch mit dem Haushalteramte betraut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Was ist denn nun mein Lohn? Daß ich das Evangelium predige und das Evangelium von Christus unentgeltlich gebe, so daß ich bei Verkündigung des Evangeliums nicht mein Recht anspreche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Denn obgleich ich frei bin von allen, habe ich mich allen zum Knechte gemacht, auf daß ich desto mehrere gewinne;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'Und bin den Juden geworden wie ein Jude, auf daß ich Juden gewönne; denen, die unter dem Gesetz stehen, wie einer, der unter dem Gesetz steht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'Den nicht unter dem Gesetz Stehenden bin ich gesetzlos geworden');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'Den Schwachen bin ich geworden wie ein Schwacher, auf daß ich die Schwachen gewönne; ich bin allen alles geworden, auf daß ich irgendwie welche errettete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Solches tue ich um des Evangeliums willen, um ein Mitteilhaber an demselben zu werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Wisset ihr nicht, daß die, so auf der Rennbahn laufen, zwar alle laufen, einer aber den Preis erhält? So laufet denn so, daß ihr ihn erhaltet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Jedem Wettkämpfer ist Enthaltsamkeit vonnöten. Diese tun es, auf daß sie einen vergänglichen Siegeskranz erlangen, wir aber einen unvergänglichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Ich laufe denn nicht ins Ungewisse, und kämpfe so, indem ich nicht in die Luft schlage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'Sondern ich zerschlage mir den Leib und führe ihn gefangen, auf daß ich, indem ich anderen predige, nicht selbst verwerflich werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Ich will nicht, Brüder, daß ihr vergeßt, wie alle unsere Väter unter der Wolke waren, und alle durch das Meer gingen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'Und alle mit der Wolke und dem Meer auf Moses getauft wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'Und haben alle einerlei geistige Speise gegessen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'Und haben alle denselben geistigen Trank getrunken;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Aber an der Mehrzahl derselben hatte Gott kein Wohlgefallen; denn sie wurden in der Wüste niedergestreckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'Solches ist aber uns zum Vorbild geschehen, daß wir uns nicht gelüsten lassen des Bösen, wie jene sich gelüsten ließen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Werdet also nicht Götzendiener, wie ein Teil von jenen, wie geschrieben steht: Das Volk ließ sich nieder zu essen und zu trinken, und stand auf, um zu spielen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Lasset auch nicht huren, wie von ihnen etliche hurten, so daß an einem Tage dreiundzwanzigtausend fielen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Und lasset uns nicht Christus versuchen, so wie etliche von jenen');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Murret auch nicht, wie etliche von jenen murrten, und durch den Verderber umkamen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'Solches alles ist jenen als Vorbildern widerfahren, es wurde aber uns zur Verwarnung geschrieben, auf die das Ende der Zeiten gekommen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Darum, wer sich läßt dünken, er stehe, mag zusehen, daß er nicht falle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Es hat euch noch keine andere als menschliche Versuchung betroffen, Gott aber ist getreu, Der euch nicht läßt versuchen über euer Vermögen, sondern mit der Versuchung auch den Ausgang schafft, daß ihr es könnt ertragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Darum, meine Geliebten, fliehet vor dem Götzendienst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Ich spreche zu euch, als zu Verständigen; beurteilt ihr, was ich sage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Der gesegnete Kelch, den wir segnen, ist er nicht die Gemeinschaft von Christus Blut, das Brot, welches wir brechen, ist es nicht die Gemeinschaft von Christus Leib?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Denn ein Brot ist es, ein Leib sind wir, die vielen; denn wir alle haben Teil an dem einen Brot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Seht an Israel nach dem Fleische; sind nicht alle, so da die Opfer essen, Teilhaber an dem Altar?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Was will ich denn nun sagen? Daß der Götze etwas ist, oder daß das Götzenopfer etwas ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Aber so viel sage ich, daß, was die Heiden opfern, sie den bösen Geistern opfern und nicht Gott, Nun will ich nicht, daß ihr Gemeinschaft habt mit dem, was der bösen Geister ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Ihr könnt nicht den Kelch des Herrn trinken und den Kelch der bösen Geister. Ihr könnt nicht teilnehmen am Tische des Herrn und am Tische der bösen Geister.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Oder wollen wir den Herrn zum Unwillen reizen? Sind wir stärker denn Er?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Wir haben zwar die Freiheit, alles zu tun, aber es frommt nicht alles. Ich habe Freiheit zu allem, aber nicht alles erbaut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Niemand habe sich selbst, sondern den anderen im Auge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Alles, was auf dem Markt feil ist, esset, ohne nachzuforschen aus Gewissensbedenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Denn die Erde ist des Herrn und was darinnen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'So euch aber einer der Ungläubigen einlädt, und ihr wollt hingehen, so esset alles, was euch vorgesetzt wird, und forscht nicht nach aus Gewissensbedenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'So euch aber einer sagt: Das ist Götzenfleisch, so esset es nicht, wegen dessen, der es euch ansagt, und aus Gewissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'Unter Gewissen meine ich nicht euer eigenes, sondern das des anderen; denn warum soll ich meine Freiheit von dem Gewissen des anderen richten lassen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Wenn ich es mit Danksagung genieße, warum sollte ich gelästert werden über dem, dafür ich danke?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Mögt ihr nun essen oder trinken oder sonst etwas tun, so tut alles zur Ehre Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Gebt weder den Juden, noch den Griechen, noch der Gemeinde Gottes ein Ärgernis,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'Gleich wie auch ich allen alles zu Gefallen tue, und nicht suche, was mir, sondern was den vielen frommt, damit sie selig werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Folget meinem Beispiel, wie ich Christus Beispiel folge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Ich lobe euch aber, Brüder, daß ihr in allem mein gedenkt, und daß ihr die Überlieferungen festhaltet, wie ich sie euch überliefert habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Ich gebe euch aber zu wissen, daß jeglichen Mannes Haupt Christus ist, des Weibes Haupt aber der Mann, Christus Haupt aber Gott ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Ein jeglicher Mann, der da betet oder weissagt, und hat etwas auf dem Haupt, der schändet sein Haupt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Ein jegliches Weib aber, das da betet oder weissagt mit unbedecktem Haupt, die schändet ihr Haupt; denn es ist ebenso, als wäre sie geschoren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Wenn sie sich aber nicht bedeckt, so lasse sie sich auch das Haar abschneiden; so es aber einem Weibe übel ansteht, das Haar abgeschnitten oder geschoren zu haben, so bedecke sie sich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Der Mann aber soll das Haupt nicht bedecken, denn er ist Gottes Ebenbild und Ehre, das Weib aber ist des Mannes Ehre;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Denn der Mann ist nicht vom Weibe, sondern das Weib vom Manne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'Denn der Mann ist nicht um des Weibes willen, sondern das Weib um des Mannes willen geschaffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Darum soll das Weib das Zeichen einer Gewalt auf dem Haupt haben um der Engel willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Doch ist weder das Weib ohne den Mann, noch der Mann ohne das Weib in dem Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Denn wie das Weib vom Manne ist, so ist der Mann durch das Weib, alles aber von Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Urteilt selbst, ob es einem Weibe ziemt, unbedeckt zu Gott zu beten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Oder lehrt euch nicht selbst die Natur, daß es dem Mann eine Unehre ist, langes Haar zu tragen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'Und dem Weibe es eine Zierde ist, so sie langes Haar trägt? denn das Haar ist ihr statt eines Schleiers gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'So aber einem von euch beliebt, streitsüchtig zu sein,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Indem ich euch dieses anempfehle, kann ich nicht loben, daß ihr nicht zum Besseren, sondern zum Schlimmeren zusammenkommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Zum ersten nämlich höre ich, daß, wenn ihr zusammenkommt in der Gemeinde, Spaltungen unter euch seien, und ich glaube es zum Teil,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Denn es müssen ja Parteiungen unter euch sein, auf daß die Gutgesinnten unter euch zutage kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Wenn ihr nun zusammenkommt, so geschieht es nicht, ein dem Herrn geweihtes Mahl zu halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'Denn ein jeglicher nimmt sein eigenes Mahl vorher beim Essen, und der eine ist hungrig, der andere ist trunken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Habt ihr denn nicht Häuser zum Essen und Trinken, oder verachtet ihr die Gemeinde Gottes und beschämt die, so nichts haben? Was soll ich euch sagen? Soll ich euch loben? Hierin lobe ich euch nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Denn ich habe das von dem Herrn empfangen, was ich euch gegeben habe: Daß der Herr Jesus in der Nacht, da Er verraten ward, das Brot nahm;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'Dankte und brach es und sprach: Nehmet, esset, dies ist Mein Leib, der für euch gebrochen wird. Solches tut zu Meinem Gedächtnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Desgleichen auch den Kelch nach dem Abendmahl und sprach: Dieser Kelch ist der neue Bund in Meinem Blute. Solches tut, sooft ihr es trinkt, zu Meinem Gedächtnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Denn so oft ihr dieses Brot eßt und diesen Kelch trinkt, sollt ihr des Herrn Tod verkündigen, bis daß Er kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Wer nun unwürdig dieses Brot ißt und den Kelch des Herrn trinkt, der versündigt sich an dem Leib und dem Blute des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Der Mensch prüfe sich selbst, und so esse er von dem Brot und trinke von dem Kelch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'Denn wer da unwürdig ißt und trinkt, der ißt und trinkt sich selbst ein Strafgericht damit, daß er den Leib des Herrn nicht unterscheidet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Darum sind so viele Schwache und Kranke unter euch, und ein gut Teil schläft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Denn so wir uns selber richteten, würden wir nicht gerichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Werden wir aber gerichtet, so werden wir vom Herrn gezüchtigt, damit wir nicht mit der Welt verurteilt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Darum, meine Brüder, wenn ihr zu einem Mahle zusammenkommt, so wartet aufeinander.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Wenn einer Hunger hat, der esse zu Haus, auf daß ihr nicht [für euch] zum Strafgericht zusammenkommt. Das übrige will ich ordnen, wenn ich komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'Was die Geistesgaben anlangt, Brüder, so will ich euch nicht in Ungewißheit lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Ihr wißt, daß ihr Heiden waret und zu den stummen Götzen, wie man eben euch führte, hingeführt wurdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Darum tue ich euch kund, daß niemand, der im Geiste Gottes redet, spricht: Verflucht ist Jesus; und niemand Jesus einen Herrn heißen kann, er rede denn durch den Heiligen Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'Es gibt aber Unterschiede in den Gnadengaben, es ist jedoch ein und derselbe Geist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'Auch gibt es Unterschiede in den Ämtern, aber es ist ein Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'Und es gibt Unterschiede in den Wirkungen; aber es ist ein und derselbe Gott, Der alles in allen wirkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'Einem jeglichen aber wird gegeben eine Kundgebung des Geistes zu einer Nutzwirkung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Denn dem einen wird gegeben durch den Geist die Rede der Weisheit, dem anderen die Rede der Erkenntnis, nach demselben Geist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'Einem anderen der Glaube durch denselben Geist; einem anderen die Gaben der Heilung durch denselben Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'Einem anderen die Gabe, Wunder zu tun, einem anderen Weissagung, einem anderen Geister zu unterscheiden, einem anderen mancherlei Zungen, wieder einem anderen Auslegung der Zungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'Das alles aber wirkt ein und derselbe Geist, der einem jeden insbesondere zuteilt, wie er will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Gleichwie nämlich der Leib ein und derselbe ist und viele Glieder hat, alle Glieder aber des einen Leibes, wiewohl ihrer viele sind, einen Leib bilden: also auch Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Denn durch den einen Geist sind wir alle zu einem Leib getauft, wir seien Juden oder Griechen, Knechte oder Freie, und alle sind wir mit einem Geist getränkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Denn der Leib ist nicht ein Glied, sondern viele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'So aber der Fuß spräche: Ich bin keine Hand, so bin ich kein Teil des Leibes; sollte er darum kein Teil des Leibes sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'Und so das Ohr spräche: Weil ich kein Auge bin, darum bin ich kein Teil des Leibes; sollte es darum kein Teil des Leibes sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Wenn der ganze Leib Auge wäre, wo bliebe das Gehör? Wenn er ganz Gehör wäre, wo bliebe der Geruch?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Nun hat aber Gott ein jegliches der Glieder am Leibe so gesetzt, wie Er gewollt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Wenn alle ein Glied wären, wo bliebe der Leib?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Nun sind aber der Glieder viele, aber es ist ein Leib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Es kann das Auge nicht zur Hand sagen: Ich bedarf deiner nicht, oder das Haupt zu den Füßen: Ich bedarf euer nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Sondern vielmehr sind die Glieder des Leibes, welche die schwächeren zu sein scheinen, notwendig;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'Und denjenigen, die wir für die unansehnlicheren am Körper halten, legen wir noch größeren Wert bei, und die unanständigeren kleiden wir um so mehr;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'Denn die uns wohl anstehen, bedürfen es nicht. Aber Gott hat den Leib also zusammengesetzt, daß Er dem dürftigeren Teile am meisten Ehre gab,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'Auf daß nicht eine Spaltung am Leibe wäre und die Glieder eins für das andere gleiche Sorge trügen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'Und so ein Glied leidet, leiden alle Glieder mit, und so ein Glied gepriesen wird, teilen alle Glieder die Freude.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Ihr aber seid der Leib Christi und Glieder, jeder nach seinem Teil.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'Und Gott hat die einen in der Gemeinde gesetzt für das erste zu Aposteln, fürs zweite zu Propheten, fürs dritte zu Lehrern, dann die Wunderkräfte, dann die Heilkräfte, Hilfeleistungen, Vorstände, Zungengaben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Sind alle Apostel? Alle Propheten? Alle Lehrer?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'Haben alle Wunderkräfte? Alle Heilgaben? Reden alle mit Zungen? Haben alle die Auslegungsgabe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Strebt aber alle nach den besten Gaben, und ich zeige euch den allerbesten Weg dazu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Wenn ich mit Menschen- und mit Engelzungen redete, und hätte der Liebe nicht, so wäre ich ein tönend Erz oder eine klingende Schelle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'Und wenn ich weissagen könnte und wüßte alle Geheimnisse und hätte alle Erkenntnis und allen Glauben, also daß ich Berge versetzte, und hätte der Liebe nicht, so wäre ich nichts.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'Und wenn ich alle meine Habe spendete und ließe meinen Leib brennen und hätte der Liebe nicht, so wäre mir es nichts nütze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Die Liebe ist langmütig, wohlwollend; die Liebe eifert nicht, die Liebe prahlt nicht, sie bläht sich nicht auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'Sie stellt sich nicht ungebärdig, sie sucht nicht das Ihre, läßt sich nicht erbittern, trachtet nicht nach Schaden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'Sie freut sich nicht über Ungerechtigkeit, freut sich aber der Wahrheit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'Sie verträgt alles, glaubt alles, hofft alles, sie duldet alles.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Die Liebe hört nimmer auf, wenn auch Weissagungen vergehen, Zungen aufhören werden und Erkenntnis ein Ende nimmt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Denn unser Wissen ist Stückwerk und unser Weissagen ist Stückwerk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'Wenn aber kommen wird das Vollkommene, dann hat es ein Ende mit dem Stückwerk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Da ich ein Kind war, da redete ich wie ein Kind, dachte wie ein Kind, urteilte wie ein Kind; da ich aber ein Mann ward, tat ich ab, was kindisch war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Wir sehen jetzt durch einen Spiegel in dunklen Worten, dann aber von Angesicht zu Angesicht. Jetzt noch erkenne ich stückweise, dann aber werde ich recht erkennen, wie auch ich erkannt worden bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Nun aber bleibt Glaube, Hoffnung, Liebe, diese drei, die größte aber unter ihnen ist die Liebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Jaget der Liebe nach! Befleißigt euch der Geistesgaben, vornehmlich aber, daß ihr weissagt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Denn der in Zungen redet, der redet nicht zu Menschen, sondern zu Gott; denn niemand versteht es, und er redet im Geiste Geheimnisse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'Wer aber weissagt, der redet zu den Menschen zur Erbauung, zur Ermahnung und zur Tröstung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Wer in Zungen redet, erbaut sich selbst; wer aber weissagt, erbaut die Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Ich wollte, daß ihr alle in Zungen redetet, mehr aber noch, daß ihr weissagtet; denn größer ist, der da weissagt, denn der da in Zungen redet, es sei denn, daß er es auch auslege, auf daß die Gemeinde davon erbaut werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Nun aber, Brüder, wenn ich zu euch käme und in Zungen redete, was würde ich euch nützen, wofern ich nicht zu euch redete in Offenbarung oder in Erkenntnis oder Weissagung oder durch Lehre?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Verhält es sich doch so schon bei leblosen Dingen, die einen Ton von sich geben; wenn die Töne sich nicht unterscheiden, wie kann man wissen, was geflötet oder aufgespielt wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Wenn die Trompete einen unbestimmten Ton gibt, wer wird sich zum Streit rüsten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'So auch ihr, wenn ihr mit Zungen redet und keine verständliche Rede von euch gebt, wie kann man verstehen, was geredet wird? Ihr redet in den Wind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Es gibt, meine ich, so verschiedene Arten von Sprachen in der Welt, und keine derselben ist unverständlich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'So ich nun nicht die Bedeutung der Sprache verstehe, so bin ich dem Redenden ein Barbar, und der da redet, ist in meinem Sinn ein Barbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Also auch ihr, weil ihr euch fleißigt der geistigen Gaben, strebt danach, daß ihr reich seid zur Erbauung der Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Darum, wer in Zungen redet, der bete, daß er es auszulegen vermöge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Denn wenn ich in Zungen bete, so betet mein Geist, mein Verstand aber bleibt unfruchtbar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Was folgt nun? Ich werde beten im Geist, werde aber auch beten mit dem Verstand. Ich werde lobsingen im Geist, werde aber auch mit dem Verstand lobsingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Denn wenn du im Geiste danksagst, wie kann der, so an der Stelle des Laien sitzt, zu deiner Danksagung sein Amen sprechen? Er weiß ja nicht, was du sagst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Du magst wohl recht schön danksagen; aber der andere wird davon nicht erbaut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Ich danke meinem Gott, daß ich mehr als ihr alle in Zungen rede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'Aber in der Gemeinde will ich lieber fünf Worte mit meinem Verstand reden, auf daß ich auch andere unterweise, als zehntausend Worte in Zungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Brüder, werdet nicht Kinder an eurem Verstand, sondern seid kindlich gegen das Böse, am Verstande aber werdet reif.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'Im Gesetz steht geschrieben: Ich werde in fremden Zungen und in fremden Lippen zu diesem Volk sprechen, und nicht einmal so werden sie auf mich hören, spricht der Herr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Darum sind die Zungen zum Zeichen, nicht den Gläubigen, sondern den Ungläubigen; die Weissagung aber nicht für die Ungläubigen, sondern für die Gläubigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Wenn nun die ganze Gemeinde zusammenkäme und alle redeten in Zungen, es kämen aber Laien oder Ungläubige hinzu, würden sie da nicht sagen; daß ihr von Sinnen seid?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'So aber alle weissageten, und es käme ein Ungläubiger oder Laie hinzu, so würde er von allen gerügt und von allen gerichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'Und so würde das Verborgene seines Herzens offenbar, und er auf sein Angesicht niederfallen und vor Gott anbeten, und bekennen, daß in Wahrheit Gott in euch ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Wie ist es denn nun, Brüder? Wenn ihr zusammenkommt, so hat jeder von euch einen Psalm, eine Lehre, eine Zunge, eine Offenbarung, eine Auslegung; lasset alles dies zur Erbauung dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Wenn einer in Zungen redet, so mögen je zwei oder höchstens drei nacheinander reden; einer lege aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Ist aber kein Ausleger da, so schweige jener in der Gemeinde. Er rede zu sich und zu Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Weissager aber sollen zwei oder drei reden, und die anderen sollen urteilen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'So aber einem anderen, der da sitzt, eine Offenbarung wird, so schweige der erste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Denn ihr könnt alle nacheinander weissagen, auf daß alle lernen und alle ermahnt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'Die Geister der Propheten sind den Propheten untertan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'Denn Gott ist nicht ein Gott der Unordnung, sondern des Friedens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Wie in allen Gemeinden der Heiligen, sollen eure Weiber schweigen; denn es ist ihnen nicht verstattet, zu reden. Sie sollen untertan sein, wie auch das Gesetz sagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'Wollen sie Belehrung haben, so mögen sie ihre Männer zu Hause fragen; denn es ziemt sich nicht für Weiber, in der Versammlung zu sprechen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Oder ist von euch das Wort Gottes ausgegangen, oder ist es allein zu euch gelangt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'So einer unter euch glaubt, ein Prophet zu sein oder geistige Gaben zu besitzen, der erkenne, was ich euch schreibe, denn es sind des Herrn Gebote.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Wer es nicht einsehen will, der sehe es nicht ein!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Darum, meine Brüder, befleißigt euch der Weissagung und wehret nicht, in Zungen zu reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Lasset aber alles wohlanständig und ordentlich zugehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Ich erinnere euch, Brüder, an das Evangelium, das ich euch verkündet habe, und das ihr auch angenommen habt, und bei dem ihr beharret.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'Durch welches ihr auch selig werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Denn ich habe euch als Hauptlehre vorgetragen, was auch ich als solche empfangen habe, daß Christus für unsere Sünden gestorben ist, nach der Schrift.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'Und daß Er begraben und am dritten Tage auferweckt worden ist, nach der Schrift.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'Und daß Er von Kephas, danach von den Zwölfen gesehen worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Danach ward Er von mehr denn fünfhundert Brüdern zumal gesehen, von denen die meisten noch leben, etliche aber entschlafen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Danach ward Er gesehen von Jakobus, sodann von allen Aposteln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'Zuletzt unter allen ist Er auch von mir, als einer unzeitigen Geburt, gesehen worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Denn ich bin der geringste unter den Aposteln, als der ich nicht wert bin, ein Apostel zu heißen, darum, daß ich die Gemeinde Gottes verfolgt hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'Aber durch die Gnade Gottes bin ich, was ich bin, und Seine Gnade ist an mir nicht vergeblich gewesen, denn ich habe viel mehr als sie alle gearbeitet; nicht aber ich, sondern die Gnade Gottes, die mit mir ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Es sei nun ich oder jene: also predigen wir, und also habt ihr geglaubt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'So aber Christus gepredigt wird, daß Er von den Toten auferstanden ist, wie sagen denn etliche unter euch, es gebe keine Auferstehung der Toten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Wenn die Auferstehung der Toten nichts ist, so ist auch Christus nicht auferstanden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'Ist aber Christus nicht auferstanden, so ist unsere Predigt eitel und auch euer Glaube eitel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Auch würden wir als falsche Zeugen Gottes erfunden, die wir wider Gott gezeugt hätten, Er habe Christus auferweckt, Den Er nicht auferweckt hätte, sofern die Toten ja nicht auferweckt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Denn so die Toten nicht auferweckt werden, so ist auch Christus nicht auferweckt worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'Ist aber Christus nicht auferweckt worden, so ist euer Glaube eitel, und ihr seid noch in euren Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'So sind denn auch die, so in Christus entschlafen sind, verloren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Wenn wir nur für dieses Leben unsere Hoffnung auf Christus gesetzt haben, so sind wir elender, als alle Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Nun ist aber Christus von den Toten auferstanden, als Erstling der Entschlafenen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Weil ja durch einen Menschen der Tod und durch einen Menschen die Auferstehung der Toten kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Denn gleich wie sie in Adam alle sterben, so werden sie in Christus alle lebendig gemacht werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Jeder aber in seiner Ordnung; als Erstling Christus, danach, die Christus angehören bei Seiner Wiederkunft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'Alsdann das Ende, wenn Er das Reich Gott und dem Vater übergibt, wenn Er alle Herrschaft, Macht und Gewalt zunichte gemacht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Denn Er muß herrschen, bis daß Er alle Feinde unter Seine Füße gelegt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'Als letzter Feind wird der Tod vernichtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Denn Er hat alles unter Seine Füße gelegt; wenn Er aber sagt, daß Er Sich alles unterworfen hat, so ist offenbar, daß ausgenommen ist der, so Ihm alles unterworfen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Wenn Ihm aber alles untertan ist, dann unterwirft sich der Sohn selbst Ihm, der Ihm alles unterworfen hat, auf daß Gott sei alles in allen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Was machen sonst die, so sich taufen lassen für die Toten, wenn die Toten gar nicht auferstehen, warum lassen sie sich doch taufen für sie?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Und was setzen auch wir uns stündlich Gefahren aus?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Bei dem Ruhme, den ich wegen euer in unserem Herrn Jesus Christus habe, ich sterbe täglich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Wenn ich nach Menschenweise in Ephesus mit Tieren gekämpft habe, was habe ich davon, so die Toten nicht auferstehen? Lasset uns essen und trinken, denn morgen sind wir tot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Lasset euch nicht irreführen; schlechte Gesellschaft verdirbt gute Sitten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Seid recht nüchtern und sündigt nicht, denn gewisse Leute haben keine Kenntnis Gottes, ich sage euch das zur Beschämung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Es sagt vielleicht jemand: Wie können Tote auferstehen? und mit welcherlei Leib kommen sie?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Du Tor! was du säst, wird nicht lebendig, es sterbe denn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'Und was du säst - nicht den Leib, der werden wird, säst du, sondern ein nacktes Korn, etwa Weizen oder sonst eines.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'Gott aber gibt ihm einen Leib, wie er gewollt hat, einem jeglichen Samen seinen eigenen Leib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Nicht alles Fleisch ist einerlei Fleisch, ein anderes ist das der Menschen, ein anderes das des Viehs, ein anderes der Fische, ein anderes der Vögel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'Und es gibt himmlische Körper und es gibt irdische Körper; aber eine andere Herrlichkeit ist die der himmlischen, eine andere die der irdischen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Eine andere Herrlichkeit ist die der Sonne und eine andere Herrlichkeit die des Mondes und eine andere Herrlichkeit die der Sterne, denn ein Stern übertrifft den anderen an Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'So ist es auch mit der Auferstehung der Toten. Es wird gesät in Verwesung und wird auferweckt in Unverweslichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'Es wird gesät in Unehre, und wird auferweckt in Herrlichkeit. Es wird gesät in Schwachheit und auferweckt in Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'Es wird gesät ein natürlicher Leib und wird auferstehen ein geistiger Leib. Es gibt einen natürlichen Leib, und gibt einen geistigen Leib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'So steht auch geschrieben: Es ward der erste Mensch Adam zu einer lebendigen Seele. Der letzte Adam zu einem lebendig machenden Geist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Aber der geistige ist nicht der erste, sondern der natürliche, danach der geistige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Der erste Mensch ist von der Erde, irdisch, der andere Mensch ist der Herr aus dem Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Welcherlei der Irdische ist, solcherlei sind auch die Irdischen, und welcherlei der Himmlische ist, also sind auch die Himmlischen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'Und wie wir das Bild des Irdischen getragen haben, so werden wir auch das Bild des Himmlischen tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'Soviel aber sage ich, Brüder, daß Fleisch und Blut das Reich Gottes nicht ererben können, noch die Verwesung die Unverweslichkeit ererbt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Siehe, ich sage euch ein Geheimnis: Wir werden nicht alle entschlafen, alle aber verwandelt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'Im Nu, im Augenblick, bei der letzten Posaune');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'Denn dieses Verwesliche muß Unverweslichkeit anziehen, und dieses Sterbliche Unsterblichkeit anziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Wenn aber dies Verwesliche Unverweslichkeit anzieht, und dies Sterbliche Unsterblichkeit anzieht, dann wird das Wort in Erfüllung gehen, das geschrieben steht: Der Tod ist verschlungen in den Sieg.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Tod, wo ist dein Stachel? Hölle, wo ist dein Sieg?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Der Stachel des Todes aber ist die Sünde, die Macht der Sünde aber ist das Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Gott aber sei Dank, Der uns den Sieg gegeben hat durch unseren Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Darum, meine geliebten Brüder, seid fest, unbeweglich, nehmt immer mehr zu in dem Werke des Herrn und seid eingedenk, daß eure Arbeit in dem Herrn nicht vergeblich ist!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'Was die Beisteuer für die Heiligen anlangt, so tut auch ihr, wie ich den Gemeinden in Galatien anbefohlen habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Auf jeglichen ersten Wochentag lege bei sich selbst ein jeglicher unter euch zu Haus etwas beiseite, und spare es auf, was ihm gut dünkt, damit nicht erst, wenn ich komme, die Sammlungen vor sich gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Wenn ich dann komme, will ich diejenigen, die ihr für geeignet anseht, mit Briefen senden, daß sie eure Liebesgabe nach Jerusalem überbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'Falls es aber wert ist, daß auch ich hingehe, sollen sie mit mir reisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Ich werde aber zu euch kommen, wenn ich durch Mazedonien gereist bin; denn durch Mazedonien werde ich gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'Bei euch aber werde ich vielleicht bleiben, oder auch den Winter zubringen, auf daß ihr mich begleitet, wo ich hinziehen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Denn ich will euch nicht bloß im Vorbeigehen sehen, weil ich hoffe, eine Zeitlang bei euch zu bleiben, so es der Herr zuläßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Bis zu Pfingsten werde ich aber zu Ephesus bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Denn ein großes Tor für Wirksamkeit hat sich mir aufgetan, und der Gegner sind viele.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Wenn Timotheus kommt, so sorgt dafür, daß er ungescheut bei euch sei, denn er arbeitet am Werke des Herrn, wie auch ich, daß ihn niemand gering schätze.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'Geleitet ihn dann im Frieden, auf daß er zu mir komme, denn ich erwarte ihn mit den Brüdern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Von Bruder Apollos aber wisset, daß ich ihm viel zugeredet habe, mit den Brüdern zu euch zu kommen, aber es war durchaus nicht sein Wille, daß er jetzt käme; er wird aber kommen, wenn es ihm gelegen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Seid wachsam, steht fest im Glauben; seid Männer und werdet stark.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Lasset alles in Liebe geschehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Ich bitte euch, Brüder: Ihr kennt das Haus des Stephanas, wie es der Erstling in Achaja war, und sie sich den Heiligen zum Dienst gewidmet haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'Auf daß auch ihr solchen an die Hand geht und allen, die mit ihnen wirken und arbeiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Ich freue mich über die Gegenwart des Stephanas, Fortunatus und Achaikus, denn sie ersetzten mir eure Abwesenheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'Denn sie erquickten meinen Geist und den euren; haltet sie in Ehren!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Es grüßen euch die Gemeinden Asiens, es grüßen euch vielmal im Herrn Aquilas und Priscilla mit der Gemeinde in ihrem Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Es grüßen euch alle Brüder, grüßet einander mit dem heiligen Kuß!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Mein Gruß mit meiner Hand Paulus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'So einer ohne Liebe zu dem Herrn Jesus Christus ist, der sei dem Untergang verfallen! Maran atha.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Die Gnade unseres Herrn Jesus Christus sei mit euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Meine Liebe ist mit euch allen in Christus Jesus. Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Paulus, ein Apostel Jesu Christi durch den Willen Gottes, und Timotheus, der Bruder, an die Gemeinde Gottes in Korinth, samt allen Heiligen in ganz Achaja:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Gruß euch und Friede von Gott unserem Vater und Herrn Jesus Christus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Gelobt sei Gott und der Vater unseres Herrn Jesus Christus, der Vater der Barmherzigkeit und der Gott allen Trostes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'Der uns tröstet in aller unserer Trübsal, so daß wir auch euch trösten können in aller Trübsal, mit dem Trost, womit wir selbst von Gott getröstet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Denn gleichwie wir viel von Christus Leiden haben, also haben wir auch durch Christus des Trostes viel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Haben wir aber Trübsal, so geschieht es zu eurem Trost und Heil; oder werden wir getröstet, so geschieht es auch zum Trost für euch, der sich wirksamer erweist in Ertragung derselben Leiden, die auch wir erleiden. Auch steht unsere Hoffnung fest euretwegen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'Weil wir wissen, daß ihr, wie der Leiden, so auch des Trostes teilhaftig seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Denn wir wollen euch nicht vorenthalten, Brüder, welche Trübsal uns in Asien widerfahren ist, daß wir über die Maßen und über Vermögen beschwert wurden, also, daß wir selbst am Leben verzweifelten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'Und hatten bei uns selbst das Todesurteil gesprochen, auf daß wir nicht auf uns selbst vertraueten, sondern auf den Gott, Der die Toten auferweckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'Der uns von solchem Tode errettet hat und errettet; und wir haben auf Ihn die Hoffnung gesetzt, daß Er auch ferner uns erretten wird,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'Indem auch ihr durch euer Gebet uns unterstützt, auf daß für die Gnadengabe, die uns durch vieler Gebet zuteil geworden ist, auch von vielen unsertwegen gedankt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Denn das ist unser Ruhm, das Zeugnis unseres Gewissens, daß wir in Einfalt und gottgefälliger Lauterkeit');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Denn wir schreiben euch nichts anderes, als was ihr leset und auch selbst erkennt, und wie ich hoffe, bis an das Ende erkennen werdet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'Wie ihr auch zum Teil schon erkannt habt, daß wir euer Ruhm sind, wie auch ihr der unsrige seid, auf den Tag des Herrn Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'Und auf dieses Vertrauen hin wollte ich früher zu euch kommen, auf daß ihr abermals eine Wohltat empfinget,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'Und von euch nach Mazedonien reisen, und wieder von Mazedonien aus zu euch kommen, und mich von euch nach Judäa geleiten lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Habe ich, als ich diesen Vorsatz faßte, mich des Leichtsinns schuldig gemacht? oder fasse ich meine Vorsätze nach dem Fleisch, so daß das Ja oder Nein bei mir stünde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Aber Gott ist getreu und so war mein Wort an euch nicht Ja und Nein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Denn Gottes Sohn, Jesus Christus, Der unter euch durch uns gepredigt worden ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Denn so viele Verheißungen Gottes da sind, die sind in Ihm Ja, und in Ihm Amen, zur Verherrlichung Gottes durch uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Gott aber ist es, Der uns mit euch im Glauben an Jesus Christus befestigt und uns gesalbt hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'Der uns besiegelt, und das Pfand des Geistes in unsere Herzen gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'Ich rufe aber Gott zum Zeugen auf über meine Seele, daß ich euch schonen wollte, indem ich nicht nach Korinth gekommen bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Nicht als ob wir Herrschaft über euren Glauben ansprächen, sondern weil wir Mithelfer eurer Freude sind; denn ihr steht ja fest im Glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Ich nahm mir aber vor, nicht abermals in Traurigkeit zu euch zu kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Denn wenn ich euch betrübe, wer ist denn da, der mir Freude machen sollte, als die von mir betrübt worden sind; und dasselbige habe ich euch geschrieben, auf daß ich nicht, wenn ich käme, Traurigkeit haben müßte durch diejenigen, die mir Freude machen sollten; denn ich bin von euch allen überzeugt, daß meine Freude euer aller Freude ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'Denn ich schrieb euch in großer Bedrängnis und Angst des Herzens unter vielen Tränen, nicht damit ihr solltet betrübt werden, sondern damit ihr die absonderliche Liebe erkennt, die ich zu euch habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'So aber jemand Betrübnis angerichtet hat, der hat nicht mich betrübt, sondern teilweise');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Es ist aber für solchen genug, daß er von der Mehrzahl so gestraft worden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'So daß ihr dagegen vielmehr ihm vergebt und ihn tröstet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'auf daß er nicht in allzu große Traurigkeit versinke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Darum ermahne ich euch, ihm einen Beweis der Liebe zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Denn darum hatte ich euch geschrieben, um zu erkennen, ob ihr Probe haltet und in allem Folge leistet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Dem ihr aber vergebt, dem vergebe auch ich; denn so ich etwas vergeben habe, so habe ich es um euretwillen vor Christus Angesicht vergeben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'Auf daß wir nicht vom Satan übervorteilt werden; denn uns ist nicht unbewußt, was er im Sinne hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'Da ich aber gen Troas kam zur Verkündigung des Evangeliums von Christus, und obgleich mir eine Tür aufgetan war im Herrn, so hatte ich doch keine Ruhe in meinem Geist, weil ich meinen Bruder Titus nicht fand;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'Sondern nahm Abschied von ihnen und fuhr nach Mazedonien ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Aber Gott sei gedankt, Der uns immer in Christus triumphieren läßt, und durch uns allerorten den Wohlgeruch der Erkenntnis desselben offenbart.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Denn wir sind ein Wohlgeruch Christi für Gott, beides, bei den Erlösten und den Verlorenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'Diesen ein Geruch des Todes zum Tode, jenen ein Geruch des Lebens zum Leben, und wer ist hierzu tüchtig?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Denn wir fälschen nicht, wie so viele, das Wort Gottes, sondern reden in Christus als aus Lauterkeit und als aus Gott, vor Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Heben wir denn abermals an, uns selbst zu empfehlen, oder bedürfen wir, wie etliche, der Empfehlungsbriefe an euch, oder Empfehlungsbriefe von euch?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'Unser Brief seid ihr, in unsere Herzen geschrieben, der von aller Welt erkannt und gelesen wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'Da es ist offenbar worden, daß ihr Christus Brief seid, von uns ausgefertigt, geschrieben nicht mit Tinte, sondern mit dem Geist des lebendigen Gottes, nicht auf steinerne Tafeln, sondern auf fleischerne Tafeln des Herzens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Eine solche Zuversicht haben wir durch Christus auf Gott;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Nicht daß wir tüchtig wären von uns selber, etwas zu urteilen als aus uns selbst, sondern unsere Tüchtigkeit ist von Gott,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'Der auch uns tüchtig gemacht hat zu Dienern eines neuen Bundes, nicht des Buchstabens, sondern des Geistes; denn der Buchstabe tötet, der Geist aber macht lebendig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'So aber der Dienst des Todes, mit Buchstaben in Steine gegraben, in Glanz erschien, so daß die Söhne Israels das Angesicht Moses wegen des Glanzes seines Angesichts, der doch vergänglich war, nicht anschauen konnten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'Wie sollte nicht der Dienst des Geistes noch viel mehr im Glanze sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Denn wenn der Dienst der Verdammnis Glanz ist, wieviel reicher ist an Glanz der Dienst der Gerechtigkeit!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'Denn das in diesem Betreff in Glanz Gesetzte ist gegenüber dem überschwenglichen Glanze nicht im Glanz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'Denn wenn das Vergängliche schon im Glanz war, so ist noch vielmehr im Glanz das, so da bleibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Weil wir nun solche Hoffnung haben, sprechen wir uns mit aller Freimütigkeit aus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'Und tun nicht wie Moses, der eine Decke vor sein Angesicht nahm, auf daß die Söhne Israels nicht das Ende des Vergänglichen anschauen sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Verstockt hingegen wurden ihre Gedanken; bis auf heute bleibt dieselbe Decke unaufgedeckt beim Lesen in dem alten Bunde, wird aber durch Christus weggetan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'Aber bis auf den heutigen Tag hängt, wenn im Moses gelesen wird, eine Decke vor ihrem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Wenn es sich aber bekehrt zum Herrn, wird die Decke weggenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Denn der Herr ist der Geist; wo aber der Geist des Herrn ist, da ist Freiheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'Nun aber schauen wir alle mit aufgedecktem Angesicht wie im Spiegel die Herrlichkeit des Herrn, indem wir selbst von Herrlichkeit zu Herrlichkeit zu demselben Bilde umgestaltet werden, als vom Herrn, Welcher der Geist ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Weil wir nun solches Amt haben, nach der Barmherzigkeit, die uns ist zuteil geworden, werden wir nicht zaghaft;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'Sondern haben von uns abgewiesen, was die Scham verbirgt, indem wir nicht wandeln in Schalkheit, noch das Wort Gottes verfälschen, sondern empfehlen uns durch das Offenbaren der Wahrheit an jedes Menschen Gewissen, im Angesichte Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Ist aber unser Evangelium auch noch verdeckt, so ist es verdeckt in denen, die verlorengehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'Weil in diesen der Gott dieser Welt die Gedanken der Ungläubigen verblendet hat, so daß das Licht des Evangeliums von Christi Herrlichkeit, Welcher ist das Bild Gottes, nicht scheinen kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Denn wir predigen nicht uns selbst, sondern Jesus Christus, daß Er der Herr ist, wir aber eure Knechte sind um Jesus willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Denn der Gott, Der aus der Finsternis Licht hervorleuchten hieß, ist es, Der es leuchten ließ in unsere Herzen, damit die Erkenntnis der Herrlichkeit Gottes im Angesicht Jesus Christi leuchtete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Wir haben aber diesen Schatz in irdischen Gefäßen, auf daß die Überschwenglichkeit der Kraft erscheine als von Gott, nicht von uns, ausgehend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Auf alle Weise bedrängt, aber nicht geängstet; zaghaft, aber nicht verzagend; verfolgt, aber nicht verlassen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'Zu Boden geworfen, aber nicht umkommend:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'So tragen wir allezeit Jesus Sterben an unserem Leibe umher, damit Jesus Leben an unserem Leibe geoffenbart werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Denn wir, die wir leben, werden um Jesus willen in den Tod gegeben, auf daß auch das Leben Jesus an unserem sterblichen Fleische offenbar werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Darum ist der Tod an uns wirksam, an euch aber das Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'Weil wir aber denselben Geist des Glaubens haben, gemäß dem, was geschrieben steht: ich glaube, darum rede ich, glauben auch wir, und darum reden wir auch,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'Indem wir wissen, daß Er, Der den Herrn Jesus auferweckt hat, auch uns auferwecken und uns lebendig darstellen wird samt euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Denn alles geschieht um euretwillen, auf daß die Gnade durch die vielen die Danksagung zur Verherrlichung Gottes um so überschwenglicher mache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Deshalb sind wir nicht zaghaft; sondern wenn auch unser äußerer Mensch aufgerieben wird, so wird doch der innere Mensch von Tag zu Tag erneuert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Denn die augenblickliche, leichte Trübsal erwirkt für uns ein ewiges, überschwengliches Maß von Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'Weil wir nicht auf das Sichtbare, sondern auf das Unsichtbare sehen. Denn das Sichtbare ist zeitlich, das Unsichtbare aber ist ewig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Denn wir wissen, daß, wenn unsere irdische Zeltbehausung zerfällt, wir eine Behausung von Gott, eine nicht mit Händen gemachte, ewige Behausung, im Himmel haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Denn in diesem seufzen wir und sehnen uns, in die Behausung, die vom Himmel ist, einzuziehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'So wir bekleidet sind und nicht nackt erfunden werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Denn solange wir in dieser Hütte sind, seufzen wir und fühlen uns beschwert, nicht als ob wir wollten ausgekleidet, sondern überkleidet werden, auf daß das Sterbliche vom Leben verschlungen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Der uns für dasselbige vorbereitet hat, ist Gott, Der uns auch das Unterpfand des Geistes gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'So sind wir nun allezeit getrost und wissen, daß, solange wir im Leibe daheim sind, wir noch fern vom Herrn in der Fremde wandern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, 'Denn wir wandeln im Glauben, nicht im Schauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'Wir sind aber getrost, und haben Lust aus dem Körper auszuwanden und daheim zu sein bei dem Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Darum beeifern wir uns auch, ob wir daheim oder noch auf der Wanderung sind, Ihm wohlgefällig zu sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Denn wir müssen alle offenbar werden vor dem Richterstuhle Christus, auf daß ein jeglicher empfange, was er bei Leibes Leben getan, und je wie er gehandelt hat, es sei gut oder böse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Weil wir denn wissen, daß der Herr zu fürchten ist, so überzeugen wir Menschen, vor Gott aber sind wir offenbar; ich hoffe aber, daß wir auch in euren Gewissen offenbar geworden sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Denn wir wollen uns nicht abermals vor euch loben, sondern euch Ursache geben, euch unser zu rühmen, auf daß ihr Grund habt wider die, so sich im Äußeren rühmen und nicht nach dem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Denn gehen wir zu weit, so tun wir es für Gott; bescheiden wir uns, so tun wir es für euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Denn Christi Liebe hält uns in Schranken, weil wir also urteilen, daß, wenn einer für alle gestorben ist, so sind mithin alle gestorben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'Und Er ist für alle gestorben, auf daß die, so da leben, nicht mehr ihnen selbst leben, sondern Dem, Der für sie gestorben und auferstanden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Darum kennen wir von nun an keinen mehr dem Fleische nach, wenn wir aber auch Christus dem Fleische nach gekannt haben, so kennen wir Ihn jetzt nicht mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Wenn somit einer in Christus ist, so ist er eine neue Schöpfung; das Alte ist vergangen, siehe, alles ist neu geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'Alles aber ist von Gott, Der uns mit Sich durch Jesus Christus versöhnt und uns das Amt der Versöhnung verliehen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Denn Gott war in Christus und versöhnte die Welt mit Ihm selber, und rechnete ihnen ihre Sünden nicht auf, und hat auf uns das Wort der Versöhnung gelegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'So sind wir nun Botschafter an Christus Statt, indem Gott durch uns vermahnt; so bitten wir euch denn an Christus Statt: Lasset euch versöhnen mit Gott!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Denn Er hat Ihn, Der von keiner Sünde wußte, für uns zur Sünde gemacht, auf daß wir in Ihm die Gerechtigkeit Gottes würden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'Wir ermahnen euch nun als Mitarbeiter, daß ihr die Gnade Gottes nicht vergeblich empfanget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'Denn Er spricht: Ich habe dich zur Zeit der Gnade erhört, und dir am Tage des Heils geholfen. Seht, jetzt ist die Zeit der Gnade, jetzt ist der Tag des Heils.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'Wir geben niemand Ärgernis, auf daß unser Amt kein Vorwurf treffe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'Sondern erweisen uns in allen Dingen als Diener Gottes, durch große Standhaftigkeit in Drangsalen, Ängsten und Nöten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'Unter Schlägen, in Gefängnissen, in Aufständen, in Mühseligkeiten, in Nachtwachen, in Fasten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'In Sittenreinheit, in Erkenntnis, in Langmut, in Freundlichkeit, im Heiligen Geist, in ungeheuchelter Liebe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'In wahrhaftiger Lehre, in der Kraft Gottes, durch die Waffen der Gerechtigkeit zu Schutz und Trutz;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'Durch Ehre und Schande, durch bösen und durch guten Leumund, als Verführer und als Wahrhaftige,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'Als Verkannte, und doch bekannt, als sterbend und siehe, wir leben, als Gezüchtige und doch nicht Ertötete,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'Als Betrübte und die doch allezeit fröhlich sind, als Arme, die aber viele reich machen, als solche, die nichts haben und doch alles besitzen. -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Unser Mund, Korinther, hat sich gegen euch aufgetan; unser Herz ist erweitert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Ihr habt in uns keinen engen Raum, habt aber engen Raum in euren Herzen. Zur Wiedervergeltung -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'Ich rede zu euch, wie zu meinen Kindern - lasset es auch bei euch weiter werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ziehet nicht am unrechten Joch mit den Ungläubigen; denn was hat die Gerechtigkeit gemein mit der Ungerechtigkeit? Welche Gemeinschaft ist zwischen dem Licht und der Finsternis?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Wie stimmt Christus mit Belial? Oder was hat der Gläubige zu schaffen mit dem Ungläubigen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'Wie kann der Tempel Gottes mit Götzenbildern in einen Vergleich kommen? Ihr seid ja der Tempel des lebendigen Gottes, wie Gott spricht: Ich will in ihnen wohnen und unter ihnen wandeln, und will ihr Gott sein und sie sollen Mein Volk sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Darum entfernt euch aus ihrer Mitte, und sondert euch ab von ihnen! spricht der Herr, und rührt das Unreine nicht an, so will Ich euch annehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'Und will euch Vater sein, und ihr sollt mir Söhne und Töchter sein, spricht der Herr, der Allmächtige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Weil wir nun solche Verheißungen haben, Geliebte, wollen wir uns reinhalten von aller Befleckung des Fleisches und des Geistes, und in der Furcht Gottes die Heiligung zur Vollendung bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Fasset uns wohl! wir haben niemand Unrecht getan, niemand beschädigt, niemand übervorteilt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Dies sage ich nicht, um euch zu verurteilen; denn ich habe euch oben gesagt, daß wir euch in unseren Herzen tragen, und mit euch leben und sterben möchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Ich habe viel freudige Zuversicht zu euch, viel Rühmens über euch, bin voll des Trostes und über die Maßen mit Freuden erfüllt, trotz all unserer Drangsal.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Denn da wir nach Mazedonien kamen, hatte unser Fleisch keine Ruhe; alles drängte auf uns ein, von außen Kämpfe, von innen Anfechtungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Aber Gott, Der die Niedrigen aufrichtet, hat auch uns durch Titus Ankunft getröstet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'Aber nicht bloß durch seine Ankunft, sondern auch durch den Trost, der ihm zuteil ward über euch, indem er uns Meldung tat von eurem Verlangen, Bedauern und eurem Eifer für mich, so daß ich mich noch mehr freute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Darum, wenn ich euch auch in dem Brief betrübt habe, so reut es mich jetzt doch nicht, wenn es mich auch gereut hätte; denn ich sehe, daß jener Brief euch nur eine Zeitlang betrübt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Ich freue mich nun, nicht, daß ihr betrübt worden, sondern daß ihr betrübt worden seid zur Sinnesänderung; denn ihr seid betrübt worden nach dem Willen Gottes, auf daß ihr von uns aus ja in keinem Stücke Schaden nähmet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Denn die Betrübnis nach Gottes Willen wirkt Reue zur Seligkeit, die niemand zu bereuen hat, die Betrübnis der Welt aber bewirkt den Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Siehe, eben das, daß ihr nach dem Willen Gottes betrübt worden seid, welchen Eifer hat es in euch angeregt, ja Entschuldigung, ja Unwillen, Furcht, Verlangen, Eifer, Ahndung! Ihr habt euch in allen Stücken erwiesen, daß ihr rein seid in der Sache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Darum, wenn ich euch auch geschrieben habe, so ist es doch nicht geschehen wegen dessen, der unrecht getan, noch wegen dessen, dem Unrecht getan worden ist, sondern deswegen, daß unser Eifer für euch bei euch vor Gott geoffenbart würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Darum sind wir über eurer Tröstung getröstet worden, unsere Freude aber ward noch ungemein erhöht über der Freude des Titus, daß sein Gemüt an euch allen erquickt worden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Denn ich bin in dem, was ich gegen ihn von euch gerühmt habe, nicht zuschanden geworden, vielmehr ist alles, was ich in Wahrheit zu euch geredet habe, somit auch unser Rühmen bei Titus, Wahrheit geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'Und sein Innerstes ist euch noch mehr zugetan, wenn er euer aller Gehorsam gedenkt, wie ihr ihn mit Furcht und Zittern aufgenommen habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Ich freue mich, daß ich mich in allem auf euch verlassen kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'Ich tue euch, Brüder, kund die Gnade Gottes, die sich in den Gemeinden Mazedoniens erwiesen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'Daß in viel Drangsalsprüfung die Überschwenglichkeit ihrer Freude und die tief hinabreichende Armut sich überschwenglich erwiesen in reicher Mildtätigkeit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Denn nach Vermögen [das bezeuge ich], ja über Vermögen waren sie willfährig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'Und erbaten sich auf das angelegentlichste von uns die Gunst der Teilnahme an der Beisteuer für die Heiligen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'Ja, über unser Erwarten ergaben sie sich vor allem dem Herrn und uns nach dem Willen Gottes, zum Dienste hin;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'So daß wir Titus baten, daß er, wie er schon angefangen, auch unter euch diese Liebesgabe ausrichtete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Aber wie ihr in allen Stücken reich seid im Glauben und in der Lehre und Erkenntnis, und in jeglichem Eifer und auch in eurer Liebe gegen uns, so seid nun auch überschwenglich in diesem Liebeswerk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Ich sage dies nicht, als ob ich gebieten wollte, sondern weil andere so eifrig sich bewiesen, möchte ich die Aufrichtigkeit auch eurer Liebe prüfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Ihr kennt ja die Gnade unseres Herrn Jesus Christus, Der, ob Er gleich reich war, um euretwillen Armut litt, auf daß ihr durch Seine Armut reich würdet und ich gebe euch hierin meinen Rat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'Denn dies frommt euch, die ihr nicht allein im Tun, sondern auch im Gernetun seit vorigem Jahr einen Anfang gemacht habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Nun aber vollbringt auch das Tun, daß ihr, so wie eine Geneigtheit des Wollens da war, so auch es nach Vermögen vollbringt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Denn so die Geneigtheit vorhanden ist, je nach Vermögen zu tun, so ist sie Gott angenehm, nicht nach dem sie nicht vermag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Nicht, daß ihr, damit es anderen leichter würde, Mangel littet, sondern daß eine Gleichheit wäre;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'So diene denn zur Zeit euer Überfluß ihrem Mangel, auf daß auch ihr Überfluß eurem Mangel diene, und so eine Gleichheit eintrete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'Wie denn geschrieben steht: Der viel gesammelt, hatte nicht mehr, und der wenig gesammelt, hatte nicht weniger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Gott aber sei Dank, Der eben solchen Fleiß für euch dem Titus in das Herz gegeben hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'Denn er folgte nicht nur meiner Aufforderung, sondern ging noch mit mehr Eifer aus freien Stücken zu euch ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Wir haben ihm aber einen Bruder beigegeben, der das Lob hat am Evangelium bei allen Gemeinden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'Nicht allein aber das, sondern er ist auch von den Gemeinden zu unserem Gefährten in diesem Liebeswerk aufgestellt, das von uns zur Ehre des Herrn und zum Beweis unseres guten Willens ausgerichtet wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'Wir sahen darauf, daß uns bei solcher reichen Beisteuer, die von uns betrieben wird, nicht jemand Übles nachrede.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'Und haben Vorsorge getroffen, daß es redlich zugehe, nicht allein vor dem Herrn, sondern auch vor Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Auch haben wir mit ihnen noch unseren Bruder gesandt, dessen Eifer wir oft in vielen Stücken bewährt gefunden, und der bei dem großen Zutrauen zu euch noch viel eifriger geworden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Sei es, daß ich für Titus rede, so ist er mein Genosse und Mitarbeiter bei euch; sei es, daß es Brüder von uns sind, Abgeordnete der Gemeinden, Christus eine Ehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Gebt an ihnen nun Beweise eurer Liebe und bestätigt Angesichts der Gemeinden unser rühmendes Zeugnis über euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Denn von solcher Beisteuer für die Heiligen brauche ich nicht weiter an euch zu schreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'Denn ich kenne eure Bereitwilligkeit, deren ich vor den Mazedoniern rühmend gedenke, daß Achaja schon voriges Jahr dazu Vorbereitung getroffen hat; und euer Eifer hat allgemein aufgemuntert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'Ich habe die Brüder gesandt, auf daß mein Rühmen von euch in diesem Stück nicht zunichte werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'Auf daß, wie ich sagte, ihr vorbereitet wäret, und wir [ich will nicht sagen ihr], wenn Mazedonier mit mir kämen und euch unvorbereitet fänden, mit solch zuversichtlichem Rühmen zuschanden würden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Ich habe es daher für nötig erachtet, die Brüder zu ersuchen, daß sie zu euch voranzögen, um euren vorher verheißenen Segen in Empfang zu nehmen und ihn bereit zu halten, auf daß es so als ein Segen und nicht als eine Erpressung angesehen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'Da gilt der Spruch: Wer da kärglich sät, der wird kärglich ernten, und wer da sät im Segen, der wird auch ernten im Segen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Ein jeglicher gebe, wie ihn das Herz treibt, nicht mit Widerwillen oder als Nötigung; denn einen fröhlichen Geber hat Gott lieb.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Gott ist aber mächtig, euch allerlei Gnade in reichem Maße zu erteilen, und daß ihr allerwege in allen Dingen volle Genüge habt und reich seiet zu allerlei gutem Werke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'Wie geschrieben steht: Er hat ausgesät und den Armen gegeben; Seine Gerechtigkeit bleibt in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Der aber Samen reicht dem, der da sät, und Brot zur Speise, wird auch eure Saat mehren und die Früchte eurer Gerechtigkeit gedeihen lassen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'Daß ihr reich werdet in allen Dingen für jegliches Werk der Herzenseinfalt, die durch uns Dank gegen Gott bewirkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Denn die Handreichung dieser Beisteuer hilft nicht nur den Bedürfnissen der Heiligen ab, sondern ist auch überschwenglich durch viele Danksagungen gegen Gott,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'Die für diese Beweise der Dienstleistung Gott preisen wegen des Gehorsams gegen das Evangelium von Christus, das ihr bekennt, und wegen eurer herzlichen Mildtätigkeit gegen sie und gegen alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'Indem auch sie mit Gebet für euch sich nach euch sehnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Gott aber sei Dank für Seine unaussprechliche Gabe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Ich Paulus aber, der ich persönlich unter euch gering, abwesend aber dreist bin, ermahne euch bei Christus Sanftmut und Seiner Milde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Ich bitte euch, daß ich nicht gegenwärtig dreist auftreten müsse mit der Zuversichtlichkeit, mit der ich dreist zu sein erachte gegen gewisse Leute, die von uns glauben, daß wir nach fleischlicher Weise wandelten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Denn obgleich wir im Fleische wandeln, so streiten wir doch nicht nach dem Fleische.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, 'Denn die Waffen unseres Kampfes sind nicht fleischlich, sondern mächtig für Gott zur Niederreißung von Bollwerken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'Die wir Anschläge und alles Hohe, das sich wider die Erkenntnis Gottes erhebt, zerstören, und alles Denken unter Christus Gehorsam gefangennehmen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'Und bereit sind, allen Ungehorsam zu strafen, wenn euer Gehorsam sich durch die Tat bewährt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Seht ihr auf das Äußere? Traut jemand sich zu, daß er Christus angehöre, der denke wieder von selber, daß, wie er Christus angehört, also auch wir ihm angehören.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Und wenn ich noch etwas weiter mich rühmte von unserer Gewalt, die uns der Herr gegeben hat zu eurer Erbauung, und nicht zu eurer Zerstörung, so werde ich nicht zuschanden werden:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'Auf daß ich nicht scheine, euch durch die Briefe schrecken zu wollen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Denn die Briefe, sagt einer, sind gewichtig und nachdrücklich, aber die leibliche Gegenwart ist schwach und die Rede kraftlos.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'Ein solcher denke, daß, wie wir abwesend in den Briefen mit Worten sind, so dürften wir auch wohl anwesend mit der Tat sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Denn wir unterfangen uns nicht, uns denen, die sich selbst loben, beizuzählen oder zu vergleichen; aber weil sie sich an sich selbst messen und sich allein mit sich vergleichen, tun sie unverständig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'Wir aber wollen uns nicht ins Ungemessene rühmen, sondern nach dem Maß des Bereichs, das uns Gott zugemessen hat, auch bis zu euch reichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Denn nicht, als wären wir solche, die nicht zu euch hinreichen, überstrecken wir uns selbst; denn wir sind bis zu euch gelangt mit dem Evangelium von Christus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'Und wir rühmen uns nicht im Übermaß fremder Arbeit, sind aber der Hoffnung, daß wir, wenn euer Glaube zunimmt, nach unserer Richtschnur an euch noch weiter gelangen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'Und auch über euch hinaus das Evangelium predigen und uns nicht innerhalb eines fremden Gebietes dessen rühmen, das schon fertig ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Wer sich aber rühmt, der rühme sich des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Denn darum, daß einer sich selbst lobt, ist er noch nicht bewährt, sondern daß ihn der Herr lobt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'Ich wollte, ihr hieltet mir ein wenig Torheit zugut, und ihr tut es wohl auch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Denn ich eifere um euch mit dem Eifer Gottes, denn ich habe euch einem Manne verlobt, um eine reine Jungfrau Christus zuzuführen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Ich fürchte aber, daß, wie die Schlange Eva durch ihre List verführte, auch euer Sinn berückt und von dem einfältigen Glauben an Christus abgewendet werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Denn wenn der Nächste, so da kommt, einen anderen Jesus predigte, als wir gepredigt haben, oder ihr einen anderen Geist empfinget, den ihr von uns nicht empfangen habt, oder ein anderes Evangelium, das ihr nicht angenommen hattet, so würdet ihr es euch recht schön gefallen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Denn ich erachte, ich stehe in nichts zurück hinter den hohen Aposteln:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Denn wenn ich auch ein Laie bin im Reden, so bin ich es doch nicht in der Erkenntnis; vielmehr sind wir in allem vor allen bei euch offenbar geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Oder habe ich Unrecht getan, daß ich mich selbst erniedrigte, auf daß ihr erhöht würdet, daß ich euch unentgeltlich das Evangelium Gottes verkündigt habe?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Auch habe ich andere Gemeinden beraubt, indem ich Sold von ihnen genommen, daß ich euch dienete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'Und während ich bei euch war und Mangel litt, bin ich niemand zur Last gefallen; denn meinem Mangel halfen die Brüder ab, die aus Mazedonien kamen, und in allen Stücken bin ich euch nicht lästig geworden, und werde es auch in Zukunft so halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'So wahr die Wahrheit von Christus in mir ist, soll mir dieser Ruhm nicht verwehrt werden, solange ich in den Landen Achajas bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Warum? Weil ich euch nicht liebe? Gott weiß es.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Was ich aber tue, will ich auch ferner tun, daß ich denen den Anlaß abschneide, die einen Anlaß suchen, auf daß sie in dem, dessen sie sich rühmen, erfunden werden gleich wie wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Denn diese Afterapostel sind trügliche Arbeiter, welche die Gestalt von Christus Aposteln annehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'Auch ist es kein Wunder, denn der Satan selbst gestaltet sich in einen Engel des Lichtes um.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Darum ist es nun nichts Großes, wenn auch seine Diener sich in Diener der Gerechtigkeit umgestalten, deren Ende auch ihren Werken entsprechen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Ich sage abermals: Niemand halte mich für unverständig; wenn aber doch, so nehmt mich als einen solchen Unverständigen an, daß auch ich mich ein wenig rühmen darf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Was ich jetzt rede, rede ich nicht als aus dem Herrn, sondern wie im Unverstand bei diesem Gegenstande des Rühmens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Weil viele sich rühmen nach dem Fleische, will auch ich mich rühmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Denn ihr hört ja gerne Unverständige an, weil ihr so verständig seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Ihr lasset euch ja gefallen, wenn einer euch zu Sklaven macht, wenn einer euch aufzehrt, euch fängt, sich erhebt, euch ins Angesicht schlägt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Ich sage das zur Schmach, wie auch, daß wir darin schwach gewesen sind; worin aber einer kühn ist - ich spreche wieder im Unverstand - da bin auch ich kühn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Hebräer sind sie? Auch ich. Israeliten sind sie? Auch ich. Abrahams Samen sind sie? Auch ich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Christi Diener sind sie? - ich rede wieder im Unverstand: - Ich noch mehr. Ich bin in mehr Mühsalen gewesen, in Streichen über die Maßen, in mehr Kerkern, oft in Todesnöten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Von den Juden habe ich fünfmal vierzig Streiche weniger einen empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'Bin dreimal gestäupt, einmal gesteinigt worden, habe dreimal Schiffbruch gelitten, habe einen Tag und eine Nacht in Meerestiefen zugebracht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'Bin oft auf Reisen gewesen, in Gefahren auf Flüssen, in Gefahren vor Mördern, in Gefahren unter Stammgenossen, in Gefahren unter Heiden, in Gefahren in der Stadt, in Gefahren in der Wüste, in Gefahren auf dem Meer, in Gefahren unter falschen Brüdern;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'In Mühsal und Elend, in häufigen Nachtwachen, in Hunger und Durst, oftmals in Fasten, in Frost und Blöße;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Ohne was sich sonst zuträgt, der tägliche Überlauf, die Sorge für alle die Gemeinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Wer ist schwach, daß ich nicht schwach werden dürfte? Wer wird geärgert, daß ich nicht entbrennen sollte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'So ich mich je rühmen sollte, will ich mich meiner Schwachheit rühmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Gott und der Vater unseres Herrn Jesus Christus, Der sei hochgelobt in Ewigkeit, weiß, daß ich nicht lüge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'In Damaskus ließ der Präfekt des Königs Aretas die Stadt der Damasker schließen und wollte meiner habhaft werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'Und ich ward in einem Korb aus einem Fenster an der Stadtmauer hinabgelassen und entrann seinen Händen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Das Rühmen ist mir ja nichts nütze; doch will ich auf Gesichte und Offenbarungen des Herrn kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Ich weiß einen Menschen in Christus, der vor vierzehn Jahren - ist er im Leibe gewesen, so weiß ich es nicht, ist er außer dem Leibe gewesen, so weiß ich es auch nicht; Gott weiß es -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'Bis in den dritten Himmel entrückt ward,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'Und dort unaussprechliche Worte hörte, die ein Mensch nicht sagen kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'Über solchem will ich mich rühmen; für mich selbst aber will ich mich nicht rühmen, es sei denn meiner Schwachheiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Denn so ich mich rühmen wollte, wäre ich darum noch nicht unverständig, denn ich würde die Wahrheit reden; ich enthalte mich aber dessen, damit nicht jemand mich höher achte, als er an mir sieht und von mir hört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'Und auf daß ich mich nicht der überschwenglichen Offenbarungen überheben möchte, ward mir ein Pfahl ins Fleisch gegeben, ein Satansengel, daß er mich mit Fäusten schlage, auf daß ich mich nicht überhebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Darüber habe ich dreimal zum Herrn gefleht, daß er von mir wiche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'Und Er hat zu mir gesagt: Laß dir an Meiner Gnade genügen; denn Meine Kraft ist in den Schwachen mächtig. Darum will ich mich am liebsten rühmen der Schwachheiten, auf daß Christus Kraft in mir wohne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Deshalb bin ich guten Mutes in Schwachheiten, in Schmachen, in Nöten, in Verfolgungen, in Bedrängnissen um Christus willen; denn wenn ich schwach bin, dann bin ich stark.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Ich bin unverständig geworden über meinem Rühmen; ihr habt mich dazu genötigt. Denn ich sollte von euch gelobt werden, weil ich in nichts den hohen Aposteln nachstehe, wenn ich gleich nichts bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Denn die Zeichen des Apostels sind unter euch geschehen, mit Erduldung von allerlei Leiden, mit Zeichen und Wundern und Krafterweisungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Denn worin seid ihr den anderen Gemeinden nachgestanden, es sei denn darin, daß ich selbst euch nicht zur Last gefallen bin? Haltet mir dieses Unrecht zugute.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Siehe, ich bin bereit, ein drittes Mal zu euch zu kommen, und werde euch nicht beschwerlich fallen; denn es ist mir nicht um das Eurige, sondern um euch zu tun; denn nicht die Kinder haben für die Eltern, sondern die Eltern für die Kinder Schätze zu sammeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'Ich aber will recht gern Opfer bringen, und ein Opfer werden für eure Seelen; wenn ich auch, der ich euch überschwenglich liebe, weniger geliebt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Aber ich habe euch vielleicht keine Kosten gemacht, bin dagegen schlau genug gewesen, euch mit Hinterlist zu fangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Habe ich durch einen von denen, die ich zu euch sandte, euch übervorteilt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Ich forderte Titus auf und sandte den Bruder mit ihm - hat euch etwa Titus übervorteilt, sind wir nicht in einem Geiste gewandelt, nicht in die gleichen Fußstapfen getreten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Glaubt ihr abermals, daß wir gegen euch uns verantworten wollen? Vor Gott in Christus reden wir das alles, Geliebte, zu eurer Erbauung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Denn ich fürchte, daß ich, wenn ich komme, euch nicht so finden möchte, wie ich wünschte, und ich von euch nicht so erfunden werde, wie ihr mich wünschet; daß Hader, Eifersucht, Ärgernisse, Streitigkeiten, Verleumdungen, Ohrenbläsereien, Aufgeblasenheiten und Verwirrungen stattgegriffen haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'Daß, wenn ich abermals komme, mein Gott mich bei euch demütige, und ich Leid tragen müsse über viele, die zuvor gesündigt und nicht Buße getan haben für die Unreinheit, Hurerei und Schwelgerei, deren sie sich schuldig machten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Ich komme nun zum dritten Mal zu euch, und auf zweier oder dreier Zeugen Munde soll jegliche Sache bestehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Ich habe es vorhergesagt und wiederhole es [als wäre ich gegenwärtig] noch einmal [und vorerst abwesend,] für die, so vorher gesündigt und für alle anderen, daß, wenn ich wiederkomme, ich nicht schonen will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'Weil ihr eine Bewährung des in mir redenden Christus verlangt, Der an euch nicht unkräftig, sondern mächtig ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Denn wenn Er auch in der Schwachheit gekreuzigt wurde, so lebt Er doch in der Kraft Gottes, so sind wir nämlich schwach in Ihm, werden aber vermöge der Kraft Gottes mit Ihm für euch leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Prüfet euch selbst, ob ihr im Glauben seid! Bewährt euch selbst! oder erkennt ihr nicht an euch selbst, daß Jesus Christus in euch ist, wofern ihr nicht etwa in der Probe nicht besteht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Ich hoffe aber, daß ihr erkennen werdet, daß wir nicht unbewährt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Ich bete aber zu Gott, daß Er euch nichts Unrechtes tun lasse, nicht damit wir als bewährt erscheinen, sondern damit ihr das Rechte tut, und wir vielmehr wie unbewährt seien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Denn wir können nichts wider die Wahrheit, sondern für die Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Wir freuen uns ja, wenn wir die Schwachen sind, ihr aber stark seid; dafür beten wir sogar, daß ihr vollkommen seiet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Darum schreibe ich dies noch abwesend, auf daß ich nicht anwesend scharf verfahren müßte, nach der Gewalt, die mir der Herr verliehen hat, zur Erbauung und nicht zur Zerstörung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Im übrigen, Brüder, freut euch, werdet vollkommen, laßt euch ermahnen, seid einträchtig, haltet Frieden, so wird der Gott der Liebe und des Friedens mit euch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Grüßet einander mit dem heiligen Kuß, es grüßen euch alle Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Die Gnade des Herrn Jesus Christus, und die Liebe Gottes, und die Gemeinschaft des Heiligen Geistes sei mit euch allen! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, '');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Paulus, Apostel, nicht von Menschen, noch durch einen Menschen, sondern durch Jesus Christus und Gott Vater, Der Ihn von den Toten auferweckt hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'Und alle Brüder, die bei mir sind, an die Gemeinden in Galatien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Gnade euch und Friede von Gott dem Vater und unserem Herrn Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'Der Sich für unsere Sünden hingegeben hat, auf daß Er uns erlöse von der gegenwärtigen argen Welt nach dem Willen Gottes und unseres Vaters,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'Welchem sei Ehre in alle Ewigkeit! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Mich wundert, daß ihr euch von dem, der euch zu Christus Gnade berufen hat, so bald habt abwenden lassen zu einem anderen Evangelium.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'So es doch kein anderes gibt und nur etliche da sind, die euch verwirren und das Evangelium von Christus verkehren wollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Aber wenn auch wir oder ein Engel vom Himmel euch ein anderes Evangelium verkündigte, als wir euch verkündigt haben, der sei verflucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Wie ich schon gesagt, sage ich euch abermals: Wenn euch einer ein anderes Evan- gelium predigt, als ihr empfangen habt, der sei verflucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Rede ich jetzt Menschen oder Gott zu Dienst, oder suche ich Menschen zu gefallen? Wenn ich Menschen gefallen wollte, so wäre ich Christus Knecht nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Ich tue euch aber kund, Brüder, daß das Evangelium, das von mir gepredigt worden, nicht menschlicher Art ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'Denn ich habe es auch nicht von einem Menschen empfangen, noch erlernt, sondern durch die Offenbarung von Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Denn ihr habt ja wohl von meinem Wandel im Judentum gehört, daß ich die Gemeinde von Christus über die Maßen verfolgte und zu zerstören suchte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'Und es im Judentum vielen meines Alters in meinem Volke zuvor tat und ein heftigerer Eiferer für meine väterlichen Überlieferungen ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Als es aber Gott wohlgefiel, Der mich von Mutterleibe an ausersehen und durch Seine Gnade berufen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'Seinen Sohn in mir zu offenbaren, daß ich Ihn unter den Heiden verkündigen sollte; so ging ich schnurstracks, ohne mit Fleisch und Blut zu Rate zu gehen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'Oder mich nach Jerusalem an die zu wenden, die vor mir Apostel waren, sondern begab mich nach Arabien und kehrte von da wieder gen Damaskus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Dann nach drei Jahren zog ich hinauf nach Jerusalem, um Petrus kennenzulernen, und blieb bei ihm fünfzehn Tage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Einen anderen Apostel bekam ich nicht zu Gesicht außer Jakobus, den Bruder des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'Was ich euch aber schreibe, siehe, bei Gott, ich lüge nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Danach kam ich in die Gegenden von Syrien und Cilicien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Ich war aber den christlichen Gemeinden in Judäa persönlich unbekannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'Sie hatten nur von mir gehört: Der früher uns verfolgte, predigt jetzt den Glauben, den er weiland verstörte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'Und sie priesen Gott über mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Nach vierzehn Jahren zog ich abermals hinauf gen Jerusalem mit Barnabas, und nahm auch Titus mit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Ich zog aber hinauf infolge einer Offenbarung und legte ihnen das Evangelium vor, das ich unter den Heiden verkündige, insbesondere aber den Angesehenen, daß ich nicht etwa vergeblich liefe oder gelaufen wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Aber nicht einmal Titus, der mit mir war, obgleich er Grieche war, ward gezwungen, sich beschneiden zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'Es waren aber falsche Brüder eingeschlichen und hatten sich eingedrängt, um der Freiheit aufzulauern, die wir in Jesus Christus haben, auf daß sie uns wieder unter das Joch brächten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'Diesen gaben wir aber keinen Augenblick nach, daß wir uns unterwürfen, auf daß die Wahrheit des Evangeliums bei euch verbliebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Anlangend diejenigen, die obenan standen, - welcherlei sie früher gewesen, geht mich nicht an, Gott sieht die Person des Menschen nicht an - haben mir diese Oberen keine andere Weisung gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'Sondern im Gegenteil, da sie sahen, daß mir das Evangelium an die Vorhaut, so wie Petrus an die Beschneidung anvertraut war;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, 'Wie denn, Der mit Petrus kräftig gewesen ist für das Apostelamt unter der Beschneidung, auch mit mir kräftig war unter den Heiden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'Da erkannten die Gnade, die mir zuteil geworden, Jakobus und Kephas und Johannes, die als die Säulen angesehen waren, reichten mir und Barnabas die Rechte zur Gemeinschaft, daß wir für die Heiden und sie für die Beschneidung predigten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'Nur sollten wir der Armen gedenken, was ich auch fleißig getan habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Als aber Kephas nach Antiochien kam, widersprach ich ihm ins Angesicht, da er als verurteilt erschien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Denn ehe etliche von Jakobus kamen, aß er mit den Heiden; da sie aber kamen, zog er sich zurück und sonderte sich ab, aus Furcht vor denen in der Beschneidung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'Und auch die übrigen Juden heuchelten mit ihm, also, daß auch Barnabas mit zur Heuchelei verleitet wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Als ich aber sah, daß sie nicht auf geradem Wege nach der Wahrheit des Evangeliums wandelten, sprach ich zu Kephas, in aller Gegenwart: Wenn du, der du ein Jude bist, heidnisch, nicht jüdisch lebst, wie willst du die Heiden zwingen, jüdisch zu leben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Wiewohl wir von Natur Juden und nicht von Heiden her Sünder sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'Doch, weil wir wissen, daß der Mensch nicht durch die Werke des Gesetzes gerecht wird, sondern durch den Glauben an Jesus Christus, haben auch wir an Jesus Christus geglaubt, auf daß wir durch den Glauben an Christus gerechtfertigt würden und nicht durch des Gesetzes Werke; denn durch des Gesetzes Werke wird kein Fleisch gerechtfertigt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Sollten wir aber, die wir in Christus suchen gerechtfertigt zu werden, selbst auch als Sünder erfunden werden? Ist darum Christus der Sünde Diener? Das sei ferne!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Denn wenn ich das, was ich zerstört hatte, wieder aufbaue, so erweise ich mich selbst als Übertreter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Denn ich bin durch das Gesetz dem Gesetz gestorben, auf daß ich Gott lebete; ich bin mit Christus gekreuzigt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'Ich lebe, aber nicht mehr ich, wohl aber lebt Christus in mir. Was ich aber jetzt lebe im Fleische, lebe ich im Glauben an den Sohn Gottes, Der mich geliebt und Sich für mich hingegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Nicht verwerfe ich die Gnade Gottes, denn wenn durch das Gesetz Gerechtigkeit kommt, so ist Christus ohne Grund gestorben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'O ihr unverständigen Galater! Wer hat euch bezaubert,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'Dies nur wünschte ich von euch zu erfahren: Habt ihr den Geist empfangen durch des Gesetzes Werke, oder durch die Predigt des Glaubens?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Seid ihr so unverständig? Im Geist habt ihr angefangen und werdet jetzt mit dem Fleische zur Vollendung gebracht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'So viel habt ihr denn vergeblich erlitten? Ja, wenn es auch nur vergeblich wäre?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'Der euch nun den Geist verleiht und Wunder unter euch wirkt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Wie Abraham Gott glaubte und es ihm zur Gerechtigkeit angerechnet wurde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'So erkennt ihr nun, daß, die im Glauben sind, Abrahams Söhne sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Die Schrift aber hat vorausgesehen, daß Gott die Heiden durch den Glauben rechtfertigt, und verhieß dem Abraham: In dir sollen alle Heiden gesegnet werden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Darum werden, die im Glauben sind, mit dem gläubigen Abraham gesegnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Denn diejenigen, die mit den Werken des Gesetzes umgehen, sind unter dem Fluche; denn es steht geschrieben: Verflucht ist jeder, der nicht an allem dem hält, was in dem Buche des Gesetzes geschrieben ist, auf daß er es tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Daß durch das Gesetz keiner vor Gott gerechtfertigt wird, ist offenbar, weil der durch den Glauben Gerechte leben wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'Das Gesetz ist aber nicht vom Glauben her, sondern der sie tut, wird leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Christus hat uns vom Fluche des Gesetzes losgekauft, indem Er für uns zum Fluch geworden ist; denn es steht geschrieben: Der am Kreuz hängt, ist verflucht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'Auf daß der Segen Abrahams durch Jesus Christus auf die Heiden käme, damit wir die Verheißung des Geistes durch den Glauben empfingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Ich will nach Menschenweise reden, Brüder: Schon eines Menschen Bund, der rechtskräftig geworden, stößt niemand um, noch tut man etwas hinzu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Nun sind dem Abraham und seinem Samen Verheißungen geworden. Es heißt nicht: den Samen, als ob von vielen, sondern dem Samen als von einem, und deinem Samen, welcher ist Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'Ich sage aber soviel: Den Bund, der von Gott auf Christus rechtskräftig geworden, macht das Gesetz, das vierhundertdreißig Jahre darauf gegeben worden ist, nicht ungültig, so daß es die Verheißung aufhöbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Denn wenn das Besitztum aus dem Gesetz kommt, so kommt es nicht mehr aus der Verheißung; Gott aber hat es dem Abraham durch die Verheißung geschenkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Was soll nun das Gesetz? Es war der Übertretungen wegen gegeben, bis der Same käme, dem die Verheißung geworden, und ist angeordnet von Engeln durch eines Vermittlers Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Der Vermittler ist aber nicht für einen; Gott aber ist Einer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Ist nun das Gesetz wider die Verheißungen Gottes? Das sei ferne! Wenn ein Gesetz gegeben wäre, das lebendig machen könnte, so käme allerdings aus dem Gesetz die Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Nun hat aber die Schrift alles der Sünde unterworfen, auf daß die Verheißung durch den Glauben an Jesus Christus den Gläubigen gegeben würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Ehe denn der Glaube kam, wurden wir unter dessen Botmäßigkeit in Verschluß gehalten für den Glauben, der geoffenbart werden sollte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Das Gesetz ist somit unser Zuchtmeister geworden für Christus, auf daß wir durch den Glauben gerechtfertigt würden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'Nun aber der Glaube gekommen ist, stehen wir nicht mehr unter dem Zuchtmeister.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Denn ihr seid alle Söhne Gottes durch den Glauben an Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Denn wie viele euer auf Christus getauft sind, die haben Christus angezogen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Da ist kein Jude, kein Grieche, da ist kein Knecht, kein Freier, da ist kein Mann, noch Weib: denn ihr alle seid eins in Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Seid ihr aber Christi, so seid ihr ja Abrahams Samen, und Erben nach der Verhei-ßung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Ich sage aber, solange der Erbe noch ein Kind ist, ist zwischen ihm und einem Knechte kein Unterschied, obgleich er Herr von allem ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'Er steht unter Vormündern und Verwaltern bis zu der vom Vater bestimmten Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'So waren auch wir, solange wir unmündig waren, unter den Buchstaben der Welt geknechtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'Als aber die Zeit erfüllt ward, sandte Gott Seinen Sohn, von einem Weibe geboren, dem Gesetze untertan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'Auf daß Er die, so unter dem Gesetze waren, loskaufete, und wir die Kindschaft empfingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Weil ihr denn Kinder seid, hat Gott den Geist Seines Sohnes in eure Herzen gesendet, der da ruft: Abba, lieber Vater!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'So bist du nun nicht mehr Knecht, sondern Sohn; so du aber Sohn bist, so bist du auch Erbe Gottes durch Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Aber zu der Zeit, da ihr Gott nicht kanntet, dientet ihr denen, die von Natur nicht Götter sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'Nun ihr aber Gott erkannt habt, ja vielmehr von Gott erkannt worden seid, wie wollt ihr euch denn wieder zu den schwachen und ärmlichen Anfängen zurückwenden und denselben wieder von neuem dienen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Ihr haltet auf Tage, Neumonde und Feste und Sabbathjahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Ich fürchte für euch, daß ich möchte vergeblich an euch gearbeitet haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Werdet doch wie ich, weil auch ich wie ihr geworden bin, Brüder, ich bitte euch; ihr habt mir nichts zu Leide getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Ihr wisset, daß ich in der Schwachheit des Fleisches euch zuerst das Evangelium predigte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'Und daß ihr meine Probe nicht von euch gewiesen und verschmäht, sondern mich wie einen Engel Gottes, wie Jesus Christus selbst aufgenommen habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Wie war es aber, daß ihr euch so glücklich prieset? Ja, ich bezeuge euch, daß ihr, wo möglich, euch die Augen ausgerissen und mir gegeben hättet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Bin ich denn euer Feind geworden, daß ich euch die Wahrheit vorhalte?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Sie beeifern sich um euch, nicht in guter Absicht, sondern wollen euch von mir ausschließen, so daß ihr um sie sollet eifern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Es ist immerhin gut, wenn man sich um des Guten willen beeifert, und nicht bloß, wenn ich bei euch bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Meine Kindlein, die ich von neuem mit Schmerzen gebäre, bis daß Christus in euch eine Gestalt gewinne!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'Ich wollte aber, ich wäre gleich bei euch und könnte in einem anderen Tone zu euch reden; denn ich bin an euch irre geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Sagt mir, ihr, die ihr unter dem Gesetze sein wollt, hört ihr nicht das Gesetz?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Es steht ja geschrieben, daß Abraham zwei Söhne hatte, einen von der Magd, den anderen von der Freien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Aber der von der Magd ist nach dem Fleische geboren, der von der Freien hingegen nach der Verheißung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'Diese Dinge sind vorbildlich, denn sie sind zwei Bünde; einer vom Berge Sinai her gebiert zur Knechtschaft, welcher ist Hagar.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Denn Hagar heißt der Berg Sinai in Arabien und kommt überein mit dem jetzigen Jerusalem, denn dieses ist in Dienstbarkeit mit seinen Kindern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'Aber das Jerusalem, das droben ist, ist die Freie, und diese ist unsere Mutter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Denn es steht geschrieben: Frohlocke, du Unfruchtbare, die nicht gebiert! Brich in Jubel aus du, die nicht kreißet; denn der Kinder der Einsamen sind viel mehr als der, die den Mann hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Wir aber, Brüder, sind dem Isaak nach der Verheißung Kinder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Aber wie damals der nach dem Fleisch Geborene den nach dem Geist Geborenen verfolgte, so geht es auch jetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Aber was sagt die Schrift? Treibe die Magd aus und ihren Sohn; denn der Sohn der Magd soll nicht erben mit dem Sohn der Freien!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'So sind wir denn, Brüder, nicht Kinder der Magd, sondern der Freien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'So besteht nun in der Freiheit, die Christus für euch gewonnen hat, und lasset euch nicht wieder unter das Joch der Knechtschaft spannen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Siehe ich, Paulus, sage euch, daß, wenn ihr euch beschneiden lasset, Christus euch nichts nützen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'Ich bezeuge abermals einem jeden, der sich beschneiden läßt, daß er verpflichtet ist, das ganze Gesetz zu halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Ihr alle, die ihr durch das Gesetz gerecht werden wollt, seid von Christus abgefallen und der Gnade verlustig geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Denn wir harren vermöge des Geistes der Hoffnung auf Gerechtigkeit aus dem Glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Denn in Jesus Christus gilt weder Beschneidung, noch Vorhaut, sondern der Glaube, der durch die Liebe tätig ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Ihr ward auf dem rechten Wege. Wer hat euch aufgehalten, daß ihr der Wahrheit nicht folgt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'Diese Überredung kommt nicht von Dem, Der euch berufen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Ein wenig Sauerteig säuert schon den ganzen Teig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Ich versehe mich zu euch in dem Herrn, daß ihr nicht anders gesinnt sein werdet. Wer euch aber irre macht, der wird die Schuld tragen, er sei, wer er wolle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Ich aber, Brüder, wenn ich Beschneidung noch predige, warum werde ich noch verfolgt? Dann ist ja das Ärgernis des Kreuzes aufgehoben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'Ach möchten sie sich noch dazu verschneiden lassen, die euch so in Unruhe bringen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Ihr seid ja zur Freiheit berufen, Brüder, nur nicht zur Freiheit, als zu einem Anlaß für das Fleisch, sondern daß einer durch Liebe dem anderen diene.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Denn das ganze Gesetz ist in einem Gebot enthalten, in dem: Du sollst deinen Nächsten lieben, wie dich selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'So ihr euch aber untereinander beißet und auffresset, so seht wohl zu, daß ihr nicht gar voneinander verschlungen werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Ich meine aber: Wandelt im Geist, so werdet ihr die Begierde des Fleisches nicht vollbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Denn das Fleisch gelüstet wider den Geist, und der Geist wider das Fleisch; dieselben streiten wider einander, daß ihr nicht tut, was ihr wollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Wenn ihr euch aber von dem Geist führen lasset, so seid ihr nicht unter dem Gesetz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Offenbar aber sind die Werke des Fleisches, als da sind: Ehebruch, Hurerei, Unzucht, Schwelgerei,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'Götzendienst, Zauberei, Feindschaft, Hader, Eifersucht, Leidenschaft, Streitsucht, Zwietracht, Parteisucht, Mißgunst, Mordsucht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'Zechen, Schwärmgelage und dergleichen, von denen ich euch vorhersage, und auch schon früher gesagt habe, daß die, welche solches tun, das Reich Gottes nicht ererben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Die Frucht des Geistes aber ist Liebe, Freude, Friede, Langmut, Güte, Wohlwollen, Treue, Sanftmut, Enthaltsamkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'Wider solche ist das Gesetz nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Die aber Christus angehören, haben das Fleisch gekreuzigt samt den Lüsten und Begierden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'So wir aber im Geist leben, so lasset uns auch im Geiste wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Lasset uns nicht nach eitler Ehre trachten, einander nicht aufreizen, einander nicht neiden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Brüder, so jemand von einem Fehl übereilt wird, so bringt solchen ihr, die ihr geistig gesinnt seid, im Geiste der Sanftmut wieder zurecht, und siehe auf dich selbst, daß du nicht auch versucht werdest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Einer trage des anderen Last, so werdet ihr Christus Gesetz erfüllen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Denn so einer sich läßt dünken, er sei etwas, so er doch nichts ist, der betört sich selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'Ein jeder prüfe sein eigen Werk, und dann wird er sein Rühmen für sich und nicht für andere haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Denn ein jeglicher soll seine eigene Last tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'Gemeinschaft aber habe der, so in der Lehre unterrichtet wird, mit dem, der ihn unterrichtet, in allen Gütern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Irrt euch nicht, Gott läßt Sich nicht spotten; denn was der Mensch sät, das wird er ernten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Wer auf sein eigen Fleisch sät, der wird von dem Fleisch Verderben ernten. Wer aber auf den Geist sät, der wird von dem Geist ewiges Leben ernten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Lasset uns aber im Gutestun nicht müde werden; denn zu seiner Zeit werden wir, wenn wir nicht laß werden, auch ernten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Lasset uns denn, nun wir Zeit haben, allen Gutes tun, allermeist aber den Glaubensgenossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Seht, mit wie großen Buchstaben ich eigenhändig schreibe:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Diejenigen, die im Fleisch einen guten Anschein haben wollen, wollen euch die Beschneidung aufnötigen, nur um nicht wegen Christus Kreuz verfolgt zu werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Denn auch sie selbst, die sich beschneiden lassen, halten das Gesetz nicht, sondern wollen nur, daß ihr euch beschneiden lasset, auf daß sie sich eures Fleisches rühmen können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'Es sei aber ferne von mir, mich zu rühmen, denn allein des Kreuzes unseres Herrn Jesus Christus, durch Den mir die Welt gekreuzigt ist, und ich der Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Denn in Jesus Christus gilt weder Beschneidung noch Vorhaut etwas, sondern die neue Schöpfung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'Und wie viele nach dieser Richtschnur wandeln, über die komme Friede und Erbarmen als über das Israel Gottes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'Hinfort mache mir niemand mehr Beschwerde, denn ich trage die Mahlzeichen des Herrn Jesus an meinem Leibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Die Gnade unseres Herrn Jesus Christus sei mit eurem Geiste, Brüder! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Paulus, ein Apostel Jesu Christi durch den Willen Gottes, an die Heiligen zu Ephesus und Gläubigen an Jesus Christus:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Gnade sei mit euch und Friede von Gott unserem Vater und dem Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Gelobt sei Gott und der Vater unseres Herrn Jesus Christus, Der uns mit allerlei geistigen Segnungen an himmlischen Gütern durch Christus gesegnet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'Wie Er uns denn erwählt hat durch Ihn, vor Gründung der Welt, damit wir heilig und tadellos wären vor Ihm in der Liebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'Indem Er uns vorherbestimmt hat zur Kindschaft durch Jesus Christus für Ihn Selbst nach dem Wohlgefallen Seines Willens;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'Zum Lob der Herrlichkeit Seiner Gnade, womit Er uns begnadigt hat in dem Geliebten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'An Dem wir haben die Erlösung durch Sein Blut, die Vergebung der Sünden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'Nach dem Reichtum Seiner Gnade, die uns überschwenglich zuteil wurde in jeglicher Weisheit und Einsicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'Indem Er uns das Geheimnis Seines Willens nach Seinem Wohlgefallen kund tat, nach welchem Er bei Sich beschlossen hatte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'In Hinsicht auf die Veranstaltung der Erfüllung der Zeiten, alles im Himmel und auf Erden in Christus zusammenzufassen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'In Ihm, durch Den wir auch zum Erbteil gekommen, die wir zuvor verordnet sind nach dem Ratschlusse Dessen, Der alle Dinge wirkt nach dem Rat Seines Willens;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'Auf daß wir zum Lobe Seiner Herrlichkeit dienten, die wir zuvor auf Christus gehofft haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'In Dem auch ihr, da ihr das Wort der Wahrheit, das Evangelium eures Heils gehört und an Ihn geglaubt habt, versiegelt worden seid mit dem Heiligen Geiste der Verheißung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'Welcher ist das Pfand unseres Erbes, auf die Erlösung des Eigentums zum Preis Seiner Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Darum auch ich, nachdem ich von eurem Glauben an den Herrn Jesus bei euch, und von eurer Liebe zu allen Heiligen gehört habe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'Nicht aufhöre zu danken für euch, indem ich euer in meinem Gebete gedenke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'Daß der Gott unseres Herrn Jesus Christus, der Vater der Herrlichkeit, euch gebe den Geist der Weisheit und der Offenbarung zu Seiner Erkenntnis;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'Und erleuchte die Augen eures Verständnisses, auf daß ihr seht, welches da ist die Hoffnung Seiner Berufung, und welches da ist der Reichtum der Herrlichkeit Seines Erbes unter den Heiligen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'Und welches da ist die überschwengliche Größe Seiner Macht an uns, die wir glauben vermöge der Wirksamkeit Seiner gewaltigen Kraft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'Die Er in Christus gewirkt hat, da Er Ihn von den Toten auferweckt und zu Seiner Rechten im Himmel gesetzt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'Hoch über alle Obrigkeit und Gewalt, Macht, Herrschaft, und über alle Namen, die genannt werden mögen, nicht allein in dieser Welt, sondern auch in der zukünftigen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'Und hat alle Dinge unter Seine Füße gelegt, und Ihn zum Haupt gesetzt über alles in der Gemeinde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'Welche ist Sein Leib und die Fülle Dessen, Der alles in allem erfüllt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Und auch euch, die ihr tot waret durch Übertretungen und Sünden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'In denen ihr nach dem Lauf dieser Welt dereinst gewandelt habt, nach dem Fürsten der Macht, der in der Luft herrscht, nach dem Geiste, der jetzt sein Werk hat in den Kindern des Unglaubens,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'Unter denen auch wir alle dereinst wandelten in den Lüsten unseres Fleisches, indem wir den Willen des Fleisches und der Gedanken taten, und von Natur Kinder des Zorns waren, gleich den anderen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Aber Gott, Der reich ist an Barmherzigkeit, hat durch Seine große Liebe, womit Er uns geliebt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'Auch uns, die wir tot waren durch Übertretungen, mit Christus lebendig gemacht -denn aus Gnaden seid ihr selig geworden -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'Und hat uns mit auferweckt, und mit gesetzt in den Himmel in Jesus Christus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'Auf daß Er in den zukünftigen Zeiten erzeige den überschwenglichen Reichtum Seiner Gnade, durch Seine Güte gegen uns in Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Denn aus Gnade seid ihr selig geworden durch den Glauben, und dies nicht aus euch');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'Nicht aus Werken, auf daß sich nicht jemand rühme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Denn wir sind Sein Werk, geschaffen in Jesus Christus zu guten Werken, für die Gott uns vorbereitet hat, daß wir darin wandeln sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Darum gedenket, daß ihr einst Heiden waret am Fleisch, und Vorhaut genannt wurdet von denen, die nach dem Fleische Beschneidung genannt wurden, so durch Menschenhand geschieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'Daß ihr zu jener Zeit außerhalb Christus waret, fremd dem Bürgerrechte Israels und fremd dem Bunde der Verheißung, ohne Hoffnung und ohne Gott in der Welt lebtet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Nun aber in Jesus Christus seid ihr, die früher fern gestanden, durch Christus Blut nahe getreten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Denn Er ist unser Friede, Der aus den beiden eins gemacht, und abgebrochen hat die Scheidewand der Umzäunung,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 'Da Er in Seinem Fleisch die Feindschaft, das Gesetz der Gebote in den Satzungen aufhob, damit Er aus den zweien in Ihm Selbst einen neuen Menschen schaffte und Frieden stiftete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'Und daß Er beide in einem Leibe durch das Kreuz mit Gott versöhnete, indem Er die Feindschaft an demselben ertötete;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'Und ist gekommen und hat den Frieden verkündigt euch, die ihr ferne waret, und denen, die nahe waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'Weil wir durch Ihn beide in einem Geiste den Zutritt zum Vater haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'So seid ihr nun nicht mehr Fremdlinge und Beisaßen, sondern Mitbürger der Heiligen und Hausgenossen Gottes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'Aufgebaut auf den Grund der Apostel und Propheten, indem Jesus Christus Selbst der Eckstein ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'Durch den das ganze Gebäude zusammengehalten wird und wächst zu einem heiligen Tempel im Herrn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'In dem auch ihr mit erbaut werdet zu einer Behausung Gottes im Geiste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Um deswillen bin ich, Paulus, der Gefangene von Jesus Christus für euch Heiden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'Sofern ihr gehört habt von dem Amt der Gnade Gottes, die mir für euch zuteil geworden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'Daß mir durch Offenbarung, wie ich oben kürzlich geschrieben habe, das Geheimnis kund geworden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'Daran ihr, so ihr es leset, inne werden könnt mein Verständnis des Geheimnisses von Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'Welches in früheren Zeiten den Menschenkindern nicht kund getan worden, wie es nun Seinen heiligen Aposteln und Propheten durch den Geist geoffenbart wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'Daß nämlich die Heiden Miterben und Miteinverleibte und Mitteilhaber Seiner Verheißung seien in Christus durch das Evangelium,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'Dessen Diener ich geworden bin nach Gabe der Gnade Gottes, die mir nach der Kraftwirkung Seiner Macht zuteil geworden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Mir, dem allergeringsten aller Heiligen, ist diese Gnade zuteil geworden, unter den Heiden den unergründlichen Reichtum von Christus zu verkündigen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'Und alle zu erleuchten, welches die Anordnung sei, die in Hinsicht auf das Geheimnis, das von Ewigkeit her in Gott verborgen gewesen, Der alle Dinge durch Jesus Christus geschaffen hat, getroffen ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'Auf daß jetzt kund würde den Mächten und Gewalten im Himmel an der Gemeinde die mannigfaltige Weisheit Gottes;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'Nach dem Ratschlusse der Ewigkeit, den Er in Jesus Christus unserem Herrn ausgeführt hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'In Dem wir haben die Freudigkeit und den Zutritt in Zuversicht durch den Glauben an Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Darum bitte ich euch, über meinen Drangsalen zu eurem Besten, die ja euch zur Herrlichkeit gereichen, nicht den Mut zu verlieren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Deshalb beuge ich meine Knie vor dem Vater unseres Herrn Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'Welcher der rechte Vater ist über alles, was da Kinder heißt, im Himmel und auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'Daß Er euch nach dem Reichtum Seiner Herrlichkeit Kraft gebe, zu erstarken durch Seinen Geist am inneren Menschen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'Auf daß Christus durch den Glauben in euren Herzen wohne, damit ihr in Liebe gewurzelt und gegründet seid;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'So daß ihr völlig im Stande seid, mit allen Heiligen zu begreifen, welches die Breite, die Länge und die Tiefe und Höhe sei;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'Und zu erkennen Christus Liebe, so alle Erkenntnis übersteigt, auf daß ihr der ganzen Fülle Gottes in vollem Maße teilhaftig werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Ihm aber, Der weit über alles überschwenglich mehr tun kann, als wir bitten und verstehen, vermöge der in uns wirkenden Kraft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'Ihm sei Ehre in der Gemeinde in Jesus Christus auf alle Menschengeschlechter in Zeit und Ewigkeit! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'So ermahne ich, der Gefangene im Herrn, euch, daß ihr möget wandeln würdig des Berufs, dazu ihr berufen seid,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'Mit aller Demut und Sanftmut, mit Geduld, daß ihr einander in Liebe vertraget,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'Und euch befleißigt, zu erhalten die Einigkeit des Geistes durch das Band des Friedens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Ein Leib und ein Geist, wie ihr auch berufen seid in einerlei Hoffnung eurer Berufung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'Ein Herr, ein Glaube, eine Taufe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'Ein Gott und Vater aller, Der da ist über euch alle und durch euch alle und in euch allen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Einem jeglichen unter uns aber ist die Gnade nach dem Maß von Christus Gabe gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Darum spricht Er: Er ist aufgefahren in die Höhe und hat gefangen geführt die Gefangenen, und den Menschen Geschenke gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Was heißt aber aufgefahren anderes, als daß Er zuvor in die untersten Teile der Erde hinabgefahren war?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'Er, Der hinabgefahren, ist auch aufgefahren über alle Himmel, auf daß Er alles erfüllete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'Und Er hat die einen zu Aposteln, andere zu Propheten, zu Evangelisten, wieder andere zu Hirten und Lehrern bestellt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'Auf daß die Heiligen für das Werk des Dienstes zur Erbauung von Christus Leib zugerichtet würden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'Bis daß wir alle gelangen in der Einheit des Glaubens und in der Erkenntnis des Sohnes Gottes zu männlicher Reife, zum vollen Maße von Christi Leib,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'Auf daß wir nicht mehr Kinder bleiben, und von jeglichem Wind der Lehre geschaukelt und gewiegt werden durch das betrügliche Spiel der Menschen und die Arglist der Verführung,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'Sondern wahrhaftig seien in der Liebe und wachsen in allen Stücken an Dem, Der das Haupt ist, Christus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'Aus Dem der ganze Leib zusammengefügt und verbunden durch alle die Gelenke der Handreichung, nach der einem jeglichen zugeteilten Wirksamkeit, das Wachstum des Leibes vollbringt, zu Seiner Erbauung in Liebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'So sage ich nun und ermahne im Herrn, daß ihr nicht mehr wandeln sollt wie die anderen Heiden wandeln, in der Eitelkeit ihres Sinnes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'Die verfinstert sind am Verstand, entfremdet dem Leben aus Gott wegen der in ihnen herrschenden Unwissenheit durch die Verstocktheit ihres Herzens,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'Die in Stumpfsinn sich ergeben der Sinnenlust, und Gewinnsucht und allerlei Unfläterei treiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Ihr habt Christus nicht also erlernt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'Wenn anders ihr Ihn gehört und von Ihm gelehrt worden seid, wie in Jesus Wahrheit ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'Daß ihr ablegen sollt in Hinsicht eures früheren Wandels den alten Menschen, der durch trügerische Lüste sich verdarb;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'Und erneuert werdet nach Geist und Gesinnung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'Und anzieht den neuen Menschen, der nach Gott geschaffen ist in Rechtschaffenheit und Heiligkeit der Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Darum tut ab die Lüge, und ein jeglicher rede die Wahrheit mit seinem Nächsten, weil wir untereinander Glieder sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Zürnet ihr, so sündigt nicht. Lasset die Sonne nicht über eurem Zorne untergehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'Und gebt dem Teufel nicht Raum in euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Wer gestohlen hat, der stehle nicht mehr, sondern arbeite und schaffe mit den Händen etwas Gutes, auf daß er habe mitzuteilen dem Dürftigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Laßt kein unnützes Geschwätz aus eurem Munde gehen, sondern wenn irgend etwas gut zur Erbauung und Besserung ist; auf daß es wohltätig sei dem Hörenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'Und betrübt nicht den Heiligen Geist Gottes, mit dem ihr versiegelt seid auf den Tag der Erlösung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Alle Bitterkeit, Leidenschaftlichkeit und Zorn, Geschrei und Lästerung lasset ferne sein von euch, samt aller Bosheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Seid vielmehr untereinander freundlich, barmherzig, vergebt einer dem anderen, gleich wie Gott euch vergeben hat in Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'So eifert nun Gott nach als Seine lieben Kinder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'Und wandelt in der Liebe, wie auch Christus euch geliebt und Sich hingegeben hat für uns, zur Gabe und zum Opfer, Gott zum lieblichen Geruch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Hurerei aber und jegliche Unreinheit und Habsucht muß unerhört sein unter euch,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'Schandbarkeit, leichtfertige törichte Reden, die unziemlich sind; vielmehr Dankbarkeit gegen Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'Denn das sollt ihr wissen, daß kein Hurer oder Unreiner oder Habsüchtiger, der ja einem Götzen dient, ein Erbteil hat in Christi und Gottes Reich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Lasset euch von keinem mit eitlen Worten täuschen, denn um dieser willen kommt der Zorn Gottes über die Kinder des Unglaubens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Darum habt keine Gemeinschaft mit ihnen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Denn zuvor ward ihr Finsternis, jetzt aber seid ihr Licht in dem Herrn. Wandelt als Kinder des Lichtes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, 'Denn die Frucht des Geistes erscheint in allerlei Güte, Gerechtigkeit und Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'Und prüfet, was dem Herrn wohlgefällig ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'Und habt keine Gemeinschaft mit den unfruchtbaren Werken der Finsternis; rügt sie vielmehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'Denn was im Geheimen von ihnen geschieht, muß man sich schämen auch nur zu sagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Alles aber, wenn es gerügt wird vom Lichte, wird offenbar, denn alles, was offenbar gemacht wird, ist Licht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Darum spricht Er: Wache auf, du Schläfer, und stehe auf von den Toten, so wird dich Christus erleuchten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'So seht nun zu, wie ihr vorsichtig wandelt, nicht wie Unweise, sondern als Weise.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'Und nehmt der Zeit wahr, denn es ist böse Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Seid darum nicht unverständig, sondern versteht, was des Herrn Wille ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'Berauscht euch nicht im Wein, worin Ausschweifung liegt, sondern werdet des Geistes voll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'Und unterhaltet euch untereinander mit Psalmen und Lobgesängen und geistlichen Liedern, singt und spielt dem Herrn in eurem Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'Und sagt allezeit Dank Gott und dem Vater für alles im Namen unseres Herrn Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'Indem ihr einander willfahret in der Furcht Christi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Ihr Weiber seid untertan euren Männern wie dem Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'Denn der Mann ist des Weibes Haupt, wie auch Christus das Haupt der Gemeinde ist: Er ist des Leibes Heiland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Wie aber die Gemeinde Christus untertan ist, also auch die Weiber ihren Männern in allen Stücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Ihr Männer liebt eure Weiber, gleich wie auch Christus die Gemeinde geliebt, und Sich für sie hingegeben hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'Auf daß Er sie heiligte, nachdem Er sie durch das Wasserbad im Wort gereinigt hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'Damit Er Sich eine Gemeinde darstelle ohne Flecken oder Runzel oder dergleichen, sondern daß sie heilig und unsträflich sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Also sollen die Männer ihre Weiber lieben wie ihre eigenen Leiber. Wer sein Weib liebt, liebt sich selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'Denn niemand hat je sein eigen Fleisch gehaßt, sondern nährt und pflegt es, gleich wie auch Christus die Gemeinde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'Weil wir Glieder sind Seines Leibes, von Seinem Fleisch und von Seinem Gebein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, 'Darum wird ein Mensch Vater und Mutter verlassen und seinem Weibe anhangen, und werden die zwei ein Fleisch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Dies Geheimnis ist groß, ich sage es aber auf Christus und die Gemeinde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Doch auch ihr sollt ein jeglicher sein Weib so lieb haben, als sich selbst; das Weib aber fürchte den Mann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Ihr Kinder, gehorcht euren Eltern in dem Herrn; denn das ist gerecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, 'Ehre Vater und Mutter! Das ist das erste Gebot mit der Verheißung:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, 'Auf daß dir es wohlergehe und du lange lebest auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'Und ihr Väter, reizt eure Kinder nicht zum Zorn, sondern erzieht sie in Zucht und Zurechtweisung des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Ihr Knechte, gehorcht mit Furcht und Zittern in Einfalt eures Herzens den leiblichen Herren, als Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'Nicht mit Augendienerei, um Menschen zu gefallen, sondern als Christus Knechte, indem ihr den Willen Gottes tut von Herzen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'Indem ihr gutwillig dient, als dem Herrn und nicht den Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'Denn ihr wißt ja, was ein jeder Gutes tut, das wird er vom Herrn empfangen, er sei ein Knecht oder ein Freier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'Und ihr Herren, tut das gleiche gegen sie, und unterlaßt das Drohen, und seid eingedenk, daß ihr und euer Herr im Himmel ist, und bei Ihm kein Ansehen der Person ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Zuletzt, Brüder, erstarket im Herrn vermöge Seiner Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Ziehet die Rüstung Gottes an, auf daß ihr bestehen könnt gegen die listigen Anläufe des Teufels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Denn wir haben nicht mit Fleisch und Blut zu kämpfen, sondern mit den Mächten, mit den Gewalten, mit den Herren der Welt, die in der Finsternis dieser Welt herrschen, mit den bösen Geistern unter dem Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Um deswillen greifet zur Rüstung Gottes, auf daß ihr am bösen Tage widerstehen und alles wohl ausrichten und das Feld behaupten möget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'So steht nun und habt eure Lenden umgürtet mit Wahrheit, und angetan mit dem Panzer der Gerechtigkeit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'Und eure Füße besohlt in Bereitschaft für das Evangelium des Friedens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'Gegen alles ergreift den Schild des Glaubens, mit dem ihr alle feurigen Pfeile des Teufels auslöschen könnt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'Und nehmt den Helm des Heils und das Schwert des Geistes, welches ist das Wort Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'Und mit allem Flehen und Bitten betet in allem Anliegen im Geiste und bleibt zu dem Ende wach und fleht anhaltend für alle Heiligen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'Auch für mich, daß mir Rede verliehen werde beim Auftun meines Mundes, mit Freimut das Geheimnis des Evangeliums kundzutun,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'Für das ich die Botschaft überbringe in Ketten, auf daß ich es freimütig verkündige, wie sich es für mich gebührt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Auf daß aber auch ihr wisset, wie es um mich steht, und was ich schaffe, wird euch alles berichten Tychikus, der geliebte Bruder und treue Diener im Herrn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'Den ich eben deshalb an euch abgesendet habe, daß ihr erfahret, wie es um uns steht, und daß er eure Herzen tröste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Friede den Brüdern und Liebe mit Glauben von Gott dem Vater und unserem Herrn Jesus Christus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Die Gnade sei mit allen, die unseren Herrn Jesus Christus lieben unwandelbar! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Paulus und Timotheus, Knechte Jesu Christi an alle Heiligen in Christi Jesu zu Philippi, samt Vorständen und Diakonen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Gnade euch, und Friede von Gott unserem Vater und dem Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Ich danke meinem Gott, sooft ich euer Gedenke,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'Was ich allezeit tue in jeglichem Gebet für euch und alle, und mit Freuden bete ich');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'Über eurer Gemeinschaft am Evangelium von ersten Tage an bis heute;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'Indem ich der Zuversicht bin, daß, Der in euch das gute Werk angefangen hat, es auch vollführen wird bis zum Tage Jesu Christi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'Wie es denn recht und billig ist, daß ich so von euch allen denke, weil ich euch im Herzen trage, in meinen Banden und bei der Verteidigung und Bestätigung des Evangeliums, als die ihr alle mit mir der Gnade teilhaftig seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Denn Gott ist mein Zeuge, wie sehr mich nach euch allen verlangt in der innigen Liebe Jesu Christi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'Und darum bete ich, daß eure Liebe mehr und mehr reich werde an aller Erkenntnis und Einsicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'Daß ihr prüfen möget, was recht und unrecht ist, auf daß ihr lauter und unanstößig seid auf den Tag von Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'Erfüllt mit Früchten der Gerechtigkeit, durch Jesus Christus, zur Ehre und zum Lobe Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Ich tue euch aber zu wissen, Brüder, daß, was mit mir geschehen ist, nur mehr zur Förderung des Evangeliums geraten ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'Also daß meine Bande offenbar geworden sind in Christus im ganzen Prätorium und sonst überall,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'Und die meisten Brüder in dem Herrn durch meine Bande Zuversicht gewonnen und desto kühner geworden sind, furchtlos das Wort zu verkünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Zwar gibt es auch einige, die Christus des Neides und Streites wegen verkünden, andere aber auch tun es aus guter Meinung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Die es aus Liebe tun, wissen, daß ich um des Evangeliums willen zur Verantwortung da bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'Die es aus Streitsucht tun, verkündigen Christus in unlauterer Absicht, um mich in meinen Banden in Trübsal zu bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Was tut es aber, wenn nur jedenfalls, sei es aus Heuchelei oder in Wahrheit, Christus verkündigt wird; und darüber freue ich mich und werde mich freuen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Denn ich weiß, daß mir dies durch euer Gebet und den Beistand des Geistes Jesu Christi zum Heile gereichen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'Nach meiner Zuversicht und Hoffnung, daß ich in keinerlei Stück zuschanden werde, und daß mit aller Freimütigkeit, wie immer, so auch jetzt Christus verherrlicht werden soll an meinem Leibe, sei es im Leben oder durch den Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Denn Christus ist mein Leben, und Sterben ist mein Gewinn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Wenn aber im Fleische leben dazu dient, meinem Werk Frucht zu bringen, so weiß ich nicht, was ich wählen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Denn es drängt mich von beiden Seiten, ich habe Lust abzuscheiden und bei Christus zu sein; was auch viel besser für mich wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'Aber es ist notwendiger euretwegen, daß ich im Fleische bleibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'Und soviel weiß ich mit Zuversicht, daß ich bleiben und bei euch allen verbleiben werde, zu eurer Förderung und Freudigkeit im Glauben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'Damit ihr euch, so ich wieder zu euch komme, in Jesus Christus an mir rühmen möget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'So wandelt nur würdig des Evangeliums Christi, auf daß, ob ich komme und euch sehe, oder abwesend von euch höre, ihr fest steht in einem Geiste und einem Sinn, und samt uns kämpft für den Glauben an das Evangelium.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'Und euch in keinem Stück abschrecken lasset von den Widersachern, was für sie zum Verderben, euch aber zum Heile dient, und das von Gott aus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'Denn euch ward vergönnt um Christus willen, nicht allein an Ihn zu glauben, sondern auch um Seinetwillen zu leiden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'Und habt denselben Kampf, wie ihr ihn an mir gesehen habt und nun von mir hört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Ist nun eine Ermahnung in Christus, ist ein Trost der Liebe, ist eine Gemeinschaft des Geistes, ist herzliche Liebe und Barmherzigkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'So machet meine Freude dadurch vollkommen, daß ihr eines Sinnes seid, gleiche Liebe zu einander habt, einmütig und einträchtig seid,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'Nichts tut aus Streitsucht oder Eitelkeit, sondern in Demut, so daß einer den anderen höher achte, denn sich selbst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Und ein jeglicher nicht auf das Seine sehe, sondern auch auf das, was des anderen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'Seid derselben Gesinnung, wie auch Jesus Christus war,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'Der, ob Er wohl in göttlicher Gestalt war, es nicht für einen Raub achtete, Gott gleich zu sein;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'Sondern Sich entäußerte, Knechtsgestalt annahm, und ward wie andere Menschen, und im Äußeren wie ein Mensch erfunden wurde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'Er erniedrigte Sich und ward gehorsam bis zum Tode, ja zum Tod am Kreuz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Weshalb Ihn auch Gott erhöht, und Ihm einen Namen verliehen hat, der über alle Namen ist:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'Auf daß im Namen Jesus sich beugen sollen alle Knie derer, die im Himmel und auf Erden und unter der Erde sind;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'Und alle Zungen bekennen sollen, daß Jesus Christus der Herr ist, zur Verherrlichung Gottes des Vaters.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Darum, meine Geliebten, so wie ihr allezeit gehorsam gewesen seid, nicht allein in meiner Gegenwart, sondern nun vielmehr in meiner Abwesenheit, so schafft, daß ihr selig werdet, mit Furcht und Zittern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Denn Gott ist es, Der in euch wirkt, beides, das Wollen und das Vollbringen, wie es Ihm wohlgefällt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Tut alles ohne Murren und Bedenklichkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'Auf daß ihr seid tadellos und lauter, Gottes Kinder, unsträflich inmitten des entarteten und verkehrten Geschlechts, unter dem ihr leuchtet, wie Himmelslichter in der Welt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'Indem ihr haltet ob dem Worte des Lebens, zum Ruhme für mich, auf den Tag Christi, daß ich nicht vergeblich gelaufen bin, noch umsonst gearbeitet habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Und wenn mein Blut auch vergossen wird am Altardienst eures Glaubens, so freue ich mich, und freue mich mit euch allen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Desgleichen sollt auch ihr euch freuen, euch freuen mit mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Ich hoffe im Herrn Jesus, daß ich Timotheus bald könne zu euch senden, damit auch ich guten Mutes werde, wenn ich erfahre, wie es bei euch steht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Denn ich habe keinen, der so ganz meines Sinnes wäre, und so redlich um euch sorgen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'Denn sie suchen alle das Ihre, nicht das, was Jesus Christus zugehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Ihr werdet seine Tüchtigkeit inne werden; denn wie ein Kind mit dem Vater, hat er mit mir am Evangelium gedient.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Ich hoffe ihn von Stund an senden zu können, wenn ich absehe, wie es mit mir geht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Ich vertraue aber zum Herrn, daß auch ich selbst bald kommen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Ich habe aber für nötig erachtet, den Bruder Epaphroditus zu euch zu senden, der mein Mitarbeiter und Mitstreiter, und euer Bote, und Diener meiner Notdurft ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'Weil ihn nach euch allen verlangte, und ihn bekümmerte, daß ihr gehört habt, daß er krank war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'Auch lag er krank auf den Tod, aber Gott hat Sich über ihn erbarmt, aber nicht allein über ihn, sondern auch über mich, auf daß ich nicht Betrübnis über Betrübnis hätte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Ich habe um so weniger gesäumt, ihn an euch abgehen zu lassen, auf daß ihr ihn seht und wieder fröhlich werdet, und ich weniger betrübt wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'So nehmt ihn nun auf im Herrn und mit aller Freude, und haltet solche Männer in Ehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'Denn wegen Christi Werk ist er dem Tod so nahe gekommen und hat sein Leben gering geachtet, auf daß er mir an eurer Statt Handreichung leiste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'So freut euch nun, Brüder, im Herrn! Daß ich euch immer das gleiche schreibe, verdrießt mich nicht und dient zu eurer Befestigung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Hütet euch vor den Hunden, hütet euch vor den schlimmen Arbeitern, hütet euch vor der Zerschneidung!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Denn wir sind die Beschneidung, die wir Gott im Geiste dienen, und deren Ruhm Jesus Christus ist und die wir nicht auf Fleisch vertrauen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'Wiewohl auch ich auf Fleisch vertrauen könnte, und noch dazu mehr:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'Bin am achten Tage beschnitten, vom Geschlechte Israel, aus Benjamins Stamm, ein Hebräer, von Hebräern gezeugt, in Hinsicht des Gesetzes ein Pharisäer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'In Hinsicht des Eifers ein Verfolger der Gemeinde, in Hinsicht der Gerechtigkeit nach dem Gesetze tadellos.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Aber was mir Gewinn war, das habe ich wegen Christus für Schaden erachtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Ja ich erachte noch alles für Schaden wegen der alles übertreffenden Erkenntnis meines Herrn Jesus Christus, um Dessentwillen ich alles für Schaden und Unrat erachte, auf daß ich Christus gewinne,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'Und in Ihm erfunden werde und nicht meine Gerechtigkeit habe, die aus dem Gesetz, sondern die durch den Glauben an Christus kommt, die Gerechtigkeit, die von Gott um des Glaubens willen zuteil wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'Um Ihn zu erkennen, und die Kraft Seiner Auferstehung und die Gemeinschaft Seiner Leiden, und daß ich Ihm ähnlich werde im Tode,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'Ob ich möchte zur Auferstehung der Toten gelangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Nicht daß ich es schon ergriffen hätte, oder schon vollendet wäre, ich jage ihm aber nach, ob ich es möchte ergreifen, nachdem ich auch von Jesus Christus ergriffen worden bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Ich erachte, Brüder, von mir selbst noch nicht, daß ich es ergriffen habe. Eins aber sage ich: Ich vergesse, was dahinten ist, und strecke mich aus nach dem, was vorne ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'Und jage dem Ziele zu nach dem Siegespreis der himmlischen Berufung Gottes in Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Wie viele nun von uns vollkommen sind, die sollen so gesinnt sein, und die noch anderes denken, denen wird Gott darüber auch noch die rechte Einsicht verleihen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Doch laßt uns das, zu dem wir gelangt sind, zur Richtschnur unseres Sinnes und Wandels nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Folgt mit mir nach, Brüder, und seht auf die, die also wandeln, wie ihr uns zum Vorbild habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Denn viele wandeln, wie ich euch oftmals sagte und nun mit Tränen wiederhole, als Feinde von Christi Kreuz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'Deren Endziel ist Verdammnis, denen der Bauch ihr Gott ist, und die eine Ehre in der Schande suchen, und deren Sinn nur auf Irdisches gerichtet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Denn unser Wandel ist im Himmel, von wannen wir auch unseren Heiland, den Herrn Jesus Christus erwarten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'Der den Leib unserer Erniedrigung umgestalten wird, um ihn dem Leibe Seiner Herrlichkeit gleich zu gestalten, mittelst der Kraft, durch die Er alles Sich untertänig machen kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Darum, geliebte Brüder, nach denen mich verlangt, ihr, meine Freude und meine Krone, steht fest im Herrn, Geliebte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Die Evodia ermahne ich und die Syntyche ermahne ich, einträchtig zu sein in dem Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'Ja, ich bitte auch dich, mein treuer Geselle, nimm dich ihrer an, die samt mir für das Evangelium gekämpft haben, mit Clemens und meinen anderen Mitarbeitern, deren Namen im Buche des Lebens stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Freut euch im Herrn allewege, und abermals sage ich: Freuet euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Eure Mildtätigkeit werde allen Menschen kund. Der Herr ist nahe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Sorget um nichts, sondern lasset in allen Dingen, im Gebet und im Flehen mit Danksagung eure Anliegen vor Gott kund werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'Und der Friede Gottes, der höher ist, als alle Vernunft, bewahre eure Herzen und Gedanken in Christus Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Weiter, Brüder, was wahrhaftig ist, was ehrbar, was gerecht, was rein, was lieblich ist, was wohl lautet, was irgendwie tugendhaft und löblich ist, dem denket nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Was ihr gelernt und empfangen und gehört und gesehen habt an mir, das tut, so wird der Gott des Friedens mit euch sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Ich bin höchlich erfreut in dem Herrn, daß ihr zu Kräften gekommen seid, mir beistehen zu können, woran ihr auch früher dachtet, wozu ihr aber die Mittel nicht hattet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Ich sage das nicht, als ob ich Mangel gelitten hätte; denn ich habe gelernt, mir mit dem, was ich habe, genügen zu lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Denn ich weiß mich in Niedrigkeit zu schicken, und im Glück mich zurechtzufinden. Ich bin auf alle Dinge eingelernt, kann mich satt essen und hungern, übrig haben und Mangel leiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Ich vermag alles durch Den, Der mir dazu das Vermögen gibt, Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Ihr habt aber wohlgetan, daß ihr euch meiner Trübsal angenommen habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Ihr Philipper wisset aber selbst, daß im Anfang des Evangeliums, da ich von Mazedonien auszog, keine Gemeinde sich mit mir in die Kosten geteilt hat, außer ihr allein,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'Daß ihr nach Thessalonich mir zu meinem Notbedarf einmal, und danach abermals beigesteuert habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Nicht daß ich die Gabe suche, sondern ich wünsche, daß überflüssige Frucht euch zuteil werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Denn ich habe genug und übergenug, da ich durch Epaphroditus das empfangen habe, was von euch kam, als lieblichen Geruch, als angenehmes Opfer, Gott wohlgefällig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Mein Gott aber verleihe euch reichlich all euren Bedarf aus Seinem Reichtum durch die Herrlichkeit in Christo Jesu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Unserem Gott und Vater aber sei Ehre von Ewigkeit zu Ewigkeit. Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Grüßet alle Heiligen in Christus Jesus, es grüßen euch die Brüder, die bei mir sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Es grüßen euch alle Heiligen, sonderlich aber die aus des Kaisers Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Die Gnade unseres Herrn Jesu Christi sei mit euch allen! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Paulus, ein Apostel Jesu Christi durch den Willen Gottes, und Timotheus, der Bruder,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'An die Heiligen zu Kolossä und die gläubigen Brüder in Christus: Gnade euch und Friede von Gott unserem Vater und dem Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Wir danken Gott und dem Vater unseres Herrn Jesus Christus allezeit im Gebet für euch,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'Weil wir von eurem Glauben an Jesus Christus und von eurer Liebe zu allen Heiligen gehört haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'Wegen der Hoffnung, die im Himmel auf euch gesetzt wird, von der ihr zuvor gehört habt im Wort der Wahrheit im Evangelium,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'Das zu euch, sowie in alle Welt gekommen, und Früchte trägt und wächst, wie auch unter euch, von dem Tage an, da ihr die Gnade Gottes in der Wahrheit gehört und erkannt habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'Wie ihr denn gelehrt worden seid von Epaphras, unserem geliebten Mitknecht, der für euch ein treuer Diener Christus ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'Und uns auch eure Liebe im Geist kundgetan hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Weshalb auch wir, von dem Tage an, da wir es hörten, nicht aufhören für euch zu beten und zu bitten, daß ihr erfüllt werdet mit der Erkenntnis Seines Willens in aller Weisheit und geistigen Einsicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'Auf daß ihr wandelt würdig des Herrn, zu allem Wohlgefallen, Frucht bringend in jeglichem guten Werk, und wachsend in der Erkenntnis Gottes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'Und mit aller Kraft angetan werdet, vermöge der Macht Seiner Herrlichkeit, für jedwede Ausdauer und Langmut mit Freuden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'Und Dank sagt dem Vater, Der uns tüchtig gemacht hat zur Teilnahme am Erbe der Heiligen im Licht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'Der uns errettet hat aus der Gewalt der Finsternis, und eingeführt in das Reich des Sohnes Seiner Liebe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'An Dem wir haben die Erlösung durch Sein Blut, die Vergebung der Sünden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'Welcher ist das Ebenbild des unsichtbaren Gottes, der Erstgeborene aller Schöpfung!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'Denn durch Ihn ist alles erschaffen in den Himmeln und auf Erden, das Sichtbare und das Unsichtbare, seien es Throne oder Herrschaften oder Obrigkeiten oder Gewalten, alles ist durch Ihn und für Ihn geschaffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'Und Er Selbst ist vor allem und alles hat Seinen Bestand in Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'Und Er ist das Haupt des Leibes der Gemeinde; Welcher ist der Anfang, der Erstgeborene von den Toten, damit Er unter allen der Erste sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Weil es Ihm wohlgefiel, daß in Ihm alle Fülle wohnen sollte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'Und durch Ihn alles mit Ihm Selbst versöhnt würde, indem Er Friede machte durch das Blut Seines Kreuzes, durch Ihn, sowohl auf Erden, als in den Himmeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Und auch euch, die ihr ehedem entfremdet in feindlicher Gesinnung und in bösen Werken ward,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'Hat Er nun versöhnt in dem Leibe Seines Fleisches durch den Tod, auf daß Er euch heilig, tadellos und unsträflich vor Sein Angesicht stellete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'So ihr anders im Glauben festgegründet und beständig bleibt und euch nicht erschüttern lasset in der Hoffnung des Evangeliums, das ihr gehört habt und welches in der ganzen Schöpfung unter dem Himmel verkündet wird, und dessen Diener ich, Paulus, geworden bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Nun freue ich mich in meinen Leiden zu eurem Besten, und mache voll, was noch an meinem Fleische gemangelt hat an Christi Drangsalen für Seinen Leib, welcher ist die Gemeinde,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'Deren Diener ich geworden bin, vermöge des mir für euch übergebenen Predigtamtes Gottes, das Wort Gottes auszurichten,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'Das Geheimnis, das von Ewigkeiten und Geschlechtern her verborgen gewesen, nun aber Seinen Heiligen geoffenbart worden ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'Denen Gott wollte kundtun den Reichtum der Herrlichkeit dieses Geheimnisses unter den Heiden, welches ist Christus in euch, die Hoffnung der Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'Den wir verkündigen, indem wir alle Menschen vermahnen und alle Menschen lehren in aller Weisheit, auf daß wir alle Menschen in Christus vollkommen darstellen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'Wofür auch ich arbeite, ringend nach Seiner Kraft, die in mir kräftiglich wirksam ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Denn ich will euch zu wissen tun, mit welcher Sorge ich kämpfe um euch und die zu Laodicea und alle, die mein Angesicht im Fleische nicht gesehen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'Auf daß ihre Herzen gestärkt und in Liebe verbunden werden zu allem Reichtum des vollen Verständnisses, zu erkennen das Geheimnis Gottes sowohl des Vaters, als das von Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'Worin alle Schätze der Weisheit und der Erkenntnis verborgen liegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'Ich sage dies aber, auf daß euch niemand durch Verführungskünste betöre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Denn ob ich gleich im Fleische abwesend bin, so bin ich doch im Geiste mit euch, und sehe mit Freuden eure Ordnung und Festigkeit in eurem Glauben an Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'So wie ihr nun den Herrn Jesus Christus angenommen habt, so wandelt in Ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'Seid eingewurzelt und auferbaut in Ihm und befestigt euch im Glauben, wie ihr gelehrt worden seid, zunehmend in demselben mit Danksagung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'So seht zu, daß euch niemand hinreiße durch Weltweisheit und eitlen Trug nach Menschensatzungen über die Anfänge der Welt und nicht nach Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'Denn in Ihm wohnt die ganze Fülle der Gottheit leibhaftig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'Und ihr seid vollkommen in Ihm, Welcher ist das Haupt aller Macht und Gewalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'In Dem ihr auch beschnitten seid, nicht durch Beschneidung mit Menschenhänden, sondern durch Ablegung des fleischlichen Leibes, durch die Beschneidung von Christus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'In Dem ihr mitbegraben seid in der Taufe, in der ihr auch mit auferstanden seid durch den Glauben an die Kraft Gottes, Der Ihn von den Toten auferweckt hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'Und hat euch, die ihr tot ward, in den Übertretungen und in der Vorhaut eures Fleisches, mit Ihm lebendig gemacht, indem Er uns alle Übertretungen vergab,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'Und alle Handschrift des Gesetzes, die gegen uns zeugte, auslöschte, und hat sie weggeräumt, und an das Kreuz geheftet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'Und die Mächte und Gewalten entwaffnet, öffentlich zur Schau geführt und an Ihm Selbst über sie einen Triumph gehalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'So lasset euch nun von niemand richten wegen Essens oder Trinkens, oder über Fasten, Neumonden oder Sabbathen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'Welches alles der Schattenriß des Zukünftigen ist. Der Leib selbst aber ist in Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Lasset euch von keinem das Ziel verrükken, indem er in Demut und Verehrung der Engel sich auf Dinge einläßt, die er nicht gesehen hat, und sich ohne Ursache in seinem fleischlichen Sinne aufbläht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'Und sich nicht hält an das Haupt, aus dem der ganze Leib, durch Gelenke und Bande verbunden und zusammengehalten, Wachstum aus Gott erhält.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'So ihr nun mit Christus den Anfangsgründen der Welt abgestorben seid, warum lasset ihr euch, als lebtet ihr noch in der Welt, Satzungen aufdringen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, 'Rühre nicht an, koste nicht, betaste nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, 'Lauter Dinge, deren Gebrauch Verderben bringen soll, nach den Satzungen und Lehren der Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'Was freilich einen Schein der Weisheit hat, in selbstgewähltem Gottesdienst, in Demut und Kasteiung des Körpers, das doch keinerlei Wert hat zu Befriedigung des Fleisches.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Seid ihr nun mit Christus auferweckt, so trachtet nach dem, was droben ist, wo Christus zur Rechten Gottes sitzt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'Trachtet nach dem, was droben ist, und nicht nach dem, was auf Erden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Ihr seid ja gestorben, und euer Leben ist mit Christus verborgen in Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Wann Christus, unser Leben, geoffenbart wird, dann werdet ihr auch mit Ihm in Herrlichkeit offenbar werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'So tötet nun eure Glieder, die da irdisch sind, Hurerei, Unreinheit, Leidenschaft, böse Lust, Habsucht, die Götzendienst sind;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'Um derentwillen der Zorn Gottes über die Kinder des Unglaubens kommt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'In denen auch ihr einst gewandelt habt, als ihr unter ihnen lebtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Nun aber legt auch ihr alles ab, Zorn, Unmut, Bosheit, Lästerung, schandbare Worte, die aus eurem Munde gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'Belügt einander nicht! Zieht den alten Menschen mit seinen Werken aus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'Und zieht den neuen an, der erneuert wird zur Erkenntnis nach dem Ebenbilde Dessen, Der ihn geschaffen hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'Da gilt nicht Heide, noch Jude, noch Beschneidung, noch Vorhaut, noch Ausländer, Skythe, Knecht, noch Freier, sondern alles und in allen ist Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'So zieht nun an, als Gottes Auserwählte, Heilige und Geliebte, herzliches Erbarmen, Wohlwollen, Demut, Sanftmut und Langmut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'Seid verträglich gegeneinander und haltet einander etwas zugut, wenn einer etwas gegen den anderen zu klagen hat, wie Christus auch euch vieles vergeben hat, so tut auch ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'Über alles dieses aber');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'Und Christi Friede herrsche in euren Herzen, wozu ihr auch berufen seid in einem Leib, und seid dankbar dafür.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Das Wort Christi wohne reichlich unter euch in aller Weisheit, lehrt und ermahnt einander mit Psalmen, Lobgesängen und geistlichen Liedern und singt in Dankbarkeit dem Herrn in euren Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'Und alles, was ihr tut in Wort oder Tat, das tut alles im Namen des Herrn Jesus, indem ihr Gott dem Vater durch Ihn dankt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Ihr Weiber, seid untertan euren Männern in dem Herrn, wie es sich gebührt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Ihr Männer, liebt eure Weiber und werdet nicht bitter gegen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Ihr Kinder, gehorcht in allem euren Eltern, denn dies ist dem Herrn wohlgefällig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Ihr Väter, reizt eure Kinder nicht, daß sie nicht mutlos werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Ihr Knechte, gehorcht in allen Stücken euren leiblichen Herren, nicht mit Augendienerei, als wolltet ihr Menschen gefallen, sondern in Einfalt des Herzens und aus Gottesfurcht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Und alles, was ihr tut, das tut von Herzen, als dem Herrn und nicht den Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'Und seid eingedenk, daß ihr von dem Herrn empfangen werdet die Vergeltung des Erbes; denn dem Herrn Christus dient ihr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Wer aber Unrecht tut, der wird empfangen, was er Unrecht getan, und da findet kein Ansehen der Person statt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Ihr Herren, erweiset den Knechten, was dem Recht und der Gleichheit gemäß ist, und seid eingedenk, daß auch ihr einen Herrn in dem Himmel habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'Haltet an am Gebet, seid wachsam und sagt Dank.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'Betet zugleich auch für uns, daß Gott uns eine Tür eröffne für das Wort, zu reden das Geheimnis von Christus, um Dessentwillen ich auch in Banden bin,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'Auf daß ich es so offenbare, wie mir zu reden geziemt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'Verhaltet euch weislich gegen die, so draußen sind, so daß ihr die rechte Zeit abwartet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Eure Rede sei immer wohlgefällig, mit Salz gewürzt, daß ihr wisset, wie ihr einem jeglichen zu antworten habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Wie es um mich steht, wird euch Tychikus, der geliebte Bruder und treue Diener und Mitknecht im Herrn, genau berichten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'Ich habe ihn eben darum zu euch gesendet, damit er erfahre, wie es mit euch geht, und eure Herzen tröste;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'Samt Onesimus, dem getreuen und geliebten Bruder, der von den euren ist; sie werden euch alles kundtun, was bei uns vorgeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Es grüßt euch Aristarchus, mein Mitgefangener, und Markus, der Vetter des Barnabas, in betreff dessen ihr Aufträge empfangen habt. Wenn er zu euch kommt, nehmt ihn auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'Und Jesus, der da heißt Justus, die aus der Beschneidung sind, welche allein meine Mitarbeiter für das Reich Gottes und mir zur Erquickung geworden sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Es grüßt euch Epaphras, der zu den euren gehört, ein Knecht von Christus, der allezeit für euch ringt in Gebeten, auf daß ihr als vollkommen besteht und erfüllt mit allem Willen Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Ich gebe ihm das Zeugnis, daß er großen Eifer für euch und für die in Laodicea und in Hierapolis hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Es grüßt euch Lukas, der Arzt, der Geliebte, und Demas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Grüßet die Brüder zu Laodicea und den Nymphas, und die Gemeinde in seinem Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'Und wenn der Brief bei euch gelesen ist, so sorgt dafür, daß er auch in der Gemeinde der Laodiceer gelesen werde, und daß ihr auch den von Laodicea zu lesen bekommt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'Und sagt dem Archippus: Warte des Dienstes, den du vom Herrn empfangen hast, daß du ihn ausrichtest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Der Gruß von meiner, des Paulus, Hand, Gedenket meiner Bande. Die Gnade sei mit euch! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Paulus, Silvanus und Timotheus an die Gemeinde der Thessalonicher in Gott dem Vater und dem Herrn Jesus Christus: Gnade sei mit euch und Friede von Gott unserem Vater und dem Herrn Jesus Christus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Wir danken Gott allezeit für euch alle, indem wir euer in unseren Gebeten ohne Unterlaß gedenken,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'Eingedenk eures Werkes im Glauben, und eurer Arbeit in der Liebe, und eurer Beharrlichkeit in der Hoffnung auf unseren Herrn Jesus Christus vor Gott, unserem Vater;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'Weil wir wissen, von Gott geliebte Brüder, eure Erwählung,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'Daß unser Evangelium bei euch nicht allein im Wort, sondern auch in der Kraft und im Heiligen Geist und in großer Zuversicht besteht, wie ihr selbst wißt, wie wir uns unter euch zu eurem Besten erwiesen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'Und ihr seid unsere und des Herrn Nacheiferer geworden und habt das Wort unter vieler Trübsal mit Freude des Heiligen Geistes aufgenommen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'Also, daß ihr allen Gläubigen in Mazedonien und Achaja Vorbilder geworden seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Denn von euch ist das Wort des Herrn erschollen, nicht allein in Mazedonien und in Achaja, sondern euer Glaube an Gott ist auch allerorten ausgekommen, so daß wir nicht nötig haben, etwas davon zu sagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Denn sie selbst verkündigen von uns, welchen Eingang wir bei euch hatten, und wie ihr euch von den Abgöttern zu Gott bekehrt habt, um dem lebendigen und wahren Gott zu dienen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'Und Seinen Sohn, Den Er von den Toten auferweckt, Jesus, Der uns von dem zukünftigen Zorn errettet, aus dem Himmel zu erwarten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Ihr wißt ja selbst, Brüder, daß unser Auftreten bei euch nicht vergeblich gewesen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'Wie wir, obwohl wir zuvor in Philippi Leiden und Schmach, wie ihr wißt, erduldet hatten, dennoch im Vertrauen auf unseren Gott unter vielem Kampfe euch das Evangelium freimütig verkündigt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Denn unsere Ermahnung kommt nicht aus Irrwahn, Unlauterkeit oder Arglist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'Sondern wie wir von Gott bewährt erfunden wurden, daß uns das Evangelium anvertraut wurde, also reden wir nicht als solche, die Menschen, sondern Gott gefallen wollen, Der unsere Herzen prüft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Denn wir sind, wie ihr wißt, nie mit Schmeichelworten umgegangen, noch hatten wir habsüchtige Absichten, Gott ist unser Zeuge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'Auch haben wir nicht Ehre bei Menschen gesucht, weder bei euch, noch bei anderen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Wir hätten als Christi Apostel uns bei euch ein Gewicht geben können, allein wir blieben anspruchslos und benahmen uns in eurer Mitte, wie eine Amme ihre Kindlein pflegt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'Also hatten wir unsere Lust an euch, und es machte uns Freude, euch nicht nur das Evangelium Gottes mitzuteilen, sondern auch unser Leben hinzugeben, weil wir euch liebgewonnen hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Denn ihr erinnert euch, Brüder, noch wohl unserer Mühe und Beschwerde, wie wir Tag und Nacht arbeiteten, um keinem von euch beschwerlich zu fallen, und euch das Evangelium Gottes verkündeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Ihr seid Zeugen und Gott, wie heilig, gerecht und unsträflich wir vor euch, die ihr glaubtet, gewesen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'Wie ihr denn wißt, daß wir einen jeglichen unter euch, wie ein Vater seine Kinder, ermahnt und ermuntert,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'Und beschworen haben, zu wandeln würdig Gottes, Der euch in Sein Reich und Seine Herrlichkeit berufen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Weshalb wir auch ohne Unterlaß Gott danken, daß ihr das Wort der Predigt von Gott von uns empfangen und nicht als Menschenwort aufgenommen habt, sondern so wie es wirklich ist, als Wort Gottes, welches auch in euch, die ihr glaubt, sich wirksam erweist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Denn ihr, Brüder, seid Nacheiferer der Gemeinden Gottes Judäas in Jesus Christus geworden, weil auch ihr gleiches von euren Volksgenossen erlitten habt, wie auch sie von den Juden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'Die sogar den Herrn Jesus und ihre eigenen Propheten getötet und uns verfolgt haben, und Gott mißfällig und aller Menschen Feinde sind;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'Die uns wehren, zu den Heiden zu sprechen, daß diese selig werden, so daß sie das Maß ihrer Sünden voll machen; aber der Zorn Gottes ist endlich über sie gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Wir aber, Brüder, die wir auf eine Zeitlang euer beraubt waren, von Angesicht, nicht dem Herzen nach, sehnten uns um so mehr mit großem Verlangen, euer Angesicht wiederzusehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Darum wollten wir');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Denn wer ist die Hoffnung, oder Freude, oder Krone unseres Rühmens, so nicht auch ihr es seid, vor unserem Herrn Jesus Christus bei Seiner Wiederkunft?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Ja, ihr seid unsere Herrlichkeit und Freude.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Darum konnten wir es nicht länger ertragen und wollten lieber allein in Athen bleiben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'Und haben Timotheus, unseren Bruder und Mitarbeiter Gottes im Evangelium Christi, gesandt, daß er euch stärke und ermahne in Ansehung eures Glaubens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'Damit niemand wanke in diesen Bedrängnissen; ihr wißt ja selbst, daß wir dazu bestimmt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Und als wir bei euch waren, sagten wir es euch ja voraus, daß wir würden in Trübsal kommen, wie es denn geschah und euch bekannt ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Darum konnte ich es nicht länger ertragen, und schickte ihn ab, auf daß ich erführe, wie es mit eurem Glauben steht, ob nicht etwa der Versucher euch versucht habe und unsere Arbeit vereitelt wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Nun aber, da Timotheus von euch zu uns gekommen und uns über euren Glauben und eure Liebe frohe Botschaft brachte, und daß ihr uns immer noch in gutem Andenken habt, und Verlangen tragt, uns zu sehen, wie denn auch uns verlangt, euch zu sehen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'Da sind wir denn über euch, Brüder, bei aller unserer Trübsal und Not durch euren Glauben getröstet worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'Denn nun leben wir auf, weil ihr im Herrn beständig seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Denn wie können wir Gott genug danken für all die Freude, die wir euretwegen vor unserem Gott empfinden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'Tag und Nacht bitten wir angelegentlichst, daß wir euer Angesicht sehen dürften, um das, was noch mangelt an eurem Glauben, voll zu machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'Er Selbst aber, unser Gott und Vater und unser Herr Jesus Christus bahne unseren Weg zu euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Euch aber lasse der Herr zunehmen und überschwenglich werden in der Liebe zueinander und gegen jedermann wie denn auch wir gegen euch gesinnt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'Daß Er eure Herzen stärke und ihr unsträflich seid in der Heiligkeit vor Gott und unserem Vater, auf die Zukunft unseres Herrn Jesus Christus mit allen Seinen Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Weiter denn bitten und ermahnen wir euch, Brüder, in dem Herrn, daß ihr, gleich wie ihr von uns empfangen habt, wie ihr sollt wandeln und Gott gefallen, darin immer völliger werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Ihr wißt ja, welche Vorschriften wir euch durch den Herrn Jesus gegeben haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'Denn dies ist der Wille Gottes, eure Heiligung, daß ihr euch der Hurerei enthaltet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'Und ein jeglicher von euch wisse, sein Gefäß in Zucht und Ehren zu erhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'Nicht in Leidenschaft der Begierde wie die Heiden, die von Gott nichts wissen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'Und daß keiner übergreife und seinen Bruder im Handel übervorteile; denn der Herr ist Rächer über alles dies, wie wir euch auch vorher gesagt und bezeugt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Denn Gott hat uns nicht zur Unreinheit, sondern zur Heiligung berufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Wer daher dies verwirft, der verwirft nicht Menschen, sondern Gott, Der Seinen Heiligen Geist in uns gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'Über brüderliche Liebe brauche ich euch nicht zu schreiben; denn ihr seid von Gott Selbst gelehrt, einander zu lieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'Und das tut ihr ja auch an allen Brüdern in ganz Mazedonien; wir ermahnen euch aber, Brüder, daß ihr immer noch völliger werdet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'Und euch beeifert, ruhig zu bleiben, das eurige zu tun, und mit euren eigenen Händen zu arbeiten, wie wir euch anempfohlen haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'Auf daß ihr ehrbarlich wandelt vor denen, die draußen sind, und niemandes bedürft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Wir wollen euch aber, Brüder, nicht in Unkunde lassen über die, so da entschlafen, auf daß ihr euch nicht betrübt, wie die anderen, die keine Hoffnung haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Denn wie wir glauben, daß Jesus Christus gestorben und auferstanden ist, also wird auch Gott die Entschlafenen durch Jesus Christus zu Sich nehmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'Denn soviel sagen wir mit dem Worte des Herrn, daß wir, die Lebenden, die überbleiben bis zur Wiederkunft des Herrn, den Entschlafenen nicht zuvorkommen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Denn Er Selbst, der Herr, wird mit einem gegebenen Losungsruf und der Stimme des Erzengels und der Posaune Gottes vom Himmel herniederkommen, und die Toten in Christus werden zuerst auferstehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'Danach wir, die wir leben und überbleiben, werden zugleich mit denselben in den Wolken in die Luft dem Herrn entgegengerückt werden, und so werden wir dann allezeit bei dem Herrn sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'So tröstet euch nun mit diesen Worten untereinander!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'Über Zeit und Zeitumstände, Brüder, ist nicht Not, euch zu schreiben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'Ihr wißt ja selbst genau, daß der Tag des Herrn kommen wird wie ein Dieb in der Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Denn wenn sie sagen: Es ist Friede, ist keine Gefahr, so steht plötzlich das Verderben vor der Tür, wie die Wehen vor dem Weib, das gebären soll; und sie können nicht entfliehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Ihr aber, Brüder, seid nicht in Finsternis, so daß euch der Tag wie der Dieb überfalle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'Ihr alle seid ja Kinder des Lichts und Kinder des Tags; wir sind nicht von der Nacht, noch von der Finsternis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'So laßt uns denn nicht schlafen, wie die anderen, sondern wachen und nüchtern sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Denn die da schlafen, schlafen in der Nacht, und die da trunken sind, sind trunken in der Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Wir aber, die wir vom Tage sind, wollen nüchtern sein, mit dem Panzer des Glaubens und der Liebe angetan, und mit dem Helm der Hoffnung zur Seligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Denn Gott hat uns nicht gesetzt zum Zorn, sondern zur Erlangung der Seligkeit durch unseren Herrn Jesus Christus, Der für uns gestorben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'Auf daß wir, ob wir wachen oder schlafen, zugleich mit Ihm leben sollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Darum ermahnt einander und erbaue einer den anderen, wie ihr denn auch tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Wir bitten euch aber, Brüder, daß ihr sorgt für die, welche an euch arbeiten und euch vorstehen in dem Herrn und euch vermahnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'Und haltet sie hoch in eurer Liebe, um ihres Werkes willen. Haltet Frieden untereinander.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Wir ermahnen euch aber, liebe Brüder, weiset zurecht die Unordentlichen, tröstet die Kleinmütigen, nehmt euch der Schwachen an, seid langmütig gegen alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Seht darauf, daß keiner Böses mit Bösem vergelte, sondern jagt allezeit dem Guten nach, beides, untereinander und gegen jedermann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Seid allezeit frohen Mutes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'Betet ohne Unterlaß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'Seid dankbar in allen Dingen, denn das ist der Wille Gottes in Christus Jesus an euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Den Geist dämpfet nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'Mißachtet nicht Weissagungen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Sondern prüft alles, das Gute behaltet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Meidet allen bösen Schein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'Er aber, der Gott des Friedens, heilige euch durch und durch, und Geist, Seele und Leib möge an euch völlig unsträflich erhalten werden für die Zukunft unseres Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Treu ist Er, Der euch ruft, und wird es auch vollbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Brüder, betet für uns!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Grüßet alle Brüder mit dem heiligen Kuß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Ich beschwöre euch bei dem Herrn, daß ihr diesen Brief alle heiligen Brüder lesen lasset.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Die Gnade unseres Herrn Jesu Christi sei mit euch! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Paulus und Silvanus und Timotheus an die Gemeinde der Thessalonicher in Gott unserem Vater und Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Gnade sei mit euch und Friede von Gott unserem Vater und unserem Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Danken müssen wir Gott allezeit um euch, liebe Brüder, wie es sich gebührt, daß euer Glauben immer mehr zunimmt, und die Liebe eines jeglichen unter euch allen gegeneinander wächst,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'Also daß wir uns euer rühmen in den Gemeinden Gottes über eurer Beharrlichkeit und eurem Glauben, in allen euren Verfolgungen und Trübsalen, die ihr erduldet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'Was anzeigt, daß Gott gerecht richtet, so daß ihr würdig werdet des Reiches Gottes, über dem ihr auch leidet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'Zumal es gerecht ist vor Gott, daß Er denen, die euch Trübsal bereiten, Trübsal vergelte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'Und euch, die ihr bedrängt werdet, Ruhe mit uns, bei der Offenbarung des Herrn Jesus vom Himmel mit den Engeln Seiner Kraft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'In Feuerflammen, Rache nehmend an denen, so Gott nicht erkennen, und die nicht dem Evangelium unseres Herrn Jesus Christus Gehorsam leisten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'Welche die Strafe erleiden, ewiges Elend von dem Angesichte des Herrn und der Herrlichkeit Seiner Macht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'Wenn Er kommen wird, um in Seinen Heiligen verherrlicht und in allen Gläubigen');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Darum beten wir auch allezeit für euch, daß unser Gott euch würdig erachte der Berufung, und jedwedes Wohlgefallen am Guten und das Werk des Glaubens mit Kraft zur Erfüllung bringe;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'Auf daß der Name unseres Herrn Jesus Christus in euch verherrlicht werde, und ihr in Ihm, nach der Gnade unseres Gottes und Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Wir bitten euch aber, Brüder, in betreff der Wiederkunft unseres Herrn Jesus Christus und unserer Hinführung zu Ihm,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'Daß ihr euch nicht sogleich abwenden lasset aus eurer Gesinnung, noch beunruhigen durch einen Geist, noch durch Wort, noch durch Schreiben, als von uns kommend, als ob der Tag des Herrn nahe bevorstehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Laßt euch von niemand irgendwie verführen; denn erst muß der Abfall kommen, und der Mensch der Sünde, der Sohn des Verderbens, offenbar werden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'Welcher sich auflehnt und erhebt über alles, was Gott und Anbetung heißt, und sich als Gott in den Tempel Gottes setzt und sich selbst für Gott erklärt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Gedenkt ihr noch, daß ich euch solches sagte, als ich noch bei euch war?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'Auch wißt ihr, was es noch aufhält, daß Er in Seiner Zeit Sich offenbart.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Denn das Geheimnis der Ruchlosigkeit ist schon in Wirksamkeit, bis nur erst der, so es aufhält, aus dem Wege ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'Und dann wird der Ruchlose offenbar werden, den der Herr mit dem Hauche Seines Mundes vertilgen und durch die Erscheinung Seiner Gegenwart zunichte machen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'Seine Ankunft aber geschieht nach der Wirksamkeit des Satans in allerlei Lügenkraft, in Zeichen und Wundern,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'Und mit allerlei Verführung zur Ungerechtigkeit unter den Verlorenen, dafür, daß sie die Liebe zur Wahrheit nicht aufkommen ließen, auf daß sie gerettet würden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'Und darum wird Gott über sie die Kraft der Verführung kommen lassen, so daß sie der Lüge glauben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'Auf daß gerichtet werden alle, die nicht an die Wahrheit glaubten, sondern an der Ungerechtigkeit Wohlgefallen hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Wir aber müssen allezeit Gott danken für euch, Brüder, die ihr vom Herrn geliebt seid, daß euch Gott von Anfang an durch die Heiligung des Geistes zur Seligkeit auserwählt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'Wozu Er euch berufen hat durch unser Evangelium, auf daß ihr zur Herrlichkeit unseres Herrn Jesus Christus gelangen könnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'So steht nun fest, Brüder, und haltet an den Überlieferungen, die ihr durch unser Wort oder durch Briefe gelehrt worden seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Er aber, unser Herr Jesus Christus und Gott und unser Vater, Der uns geliebt und ewigen Beistand und gute Hoffnung nach Seiner Gnade verliehen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'Der tröste eure Herzen und befestige euch in jeglichem guten Wort und Werk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Weiter, Brüder, betet für uns, daß das Wort des Herrn sich verbreite und verherrlicht werde, so wie bei euch;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'Und daß wir erlöst werden von den mißliebigen und argen Menschen; denn der Glaube ist nicht jedermanns Ding.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Der Herr aber ist treu, Der wird euch stärken und bewahren vor dem Argen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Wir haben im Herrn das Vertrauen zu euch, daß ihr, was wir euch anbefehlen, auch tut und tun werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Der Herr aber lenke eure Herzen zur Liebe Gottes und zur Beharrlichkeit in Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Wir anempfehlen euch aber, Brüder, im Namen des Herrn Jesus Christus, daß ihr euch von jeglichem Bruder zurückzieht, der unordentlich und nicht nach der Vorschrift lebt, die er von uns empfangen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Ihr wißt ja selbst, wie ihr uns nachleben sollt, denn wir haben unter euch nicht unordentlich gelebt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'Auch haben wir nicht jemandes Brot umsonst gegessen, sondern mit Mühe und Beschwerde Tag und Nacht gearbeitet, um keinem unter euch beschwerlich zu werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'Nicht als ob wir dazu kein Recht gehabt hätten, sondern um euch ein Vorbild zu geben, daß ihr uns nachleben sollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Denn als wir bei euch waren, stellten wir auf, daß einer, der nicht arbeiten will, auch nicht essen soll;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Weil wir hören, daß etliche unter euch unordentlich wandeln, nicht arbeiten, sondern unnütze Dinge treiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Solchen aber anempfehlen wir und vermahnen sie durch unseren Herrn Jesus Christus, daß sie geruhig arbeiten und ihr eigenes Brot essen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Ihr aber, Brüder, seid unverdrossen im Gutestun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'So aber jemand sich an unser Wort in dem Brief nicht kehrt, den zeichnet an, und habt keine Gemeinschaft mit ihm, daß er sich schämen muß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'Doch haltet ihn nicht als Feind, sondern vermahnt ihn als einen Bruder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'Er aber, der Herr des Friedens, gebe euch allezeit und allenthalben Frieden, der Herr sei mit euch allen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Der Gruß ist von meiner, Paulus eigener Hand, und ist euch das Zeichen in allen Briefen. Also schreibe ich:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Die Gnade unseres Herrn Jesus Christi sei mit euch allen. Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Paulus, ein Apostel Jesu Christi, auf Befehl Gottes unseres Heilandes und Christus Jesus, Der unsere Hoffnung ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'An Timotheus den rechtschaffenen Sohn im Glauben: Gnade, Barmherzigkeit, Friede von Gott unserem Vater und Jesus Christus unserem Herrn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Wie ich dich ermahnt habe, in Ephesus zu bleiben, da ich auf der Reise nach Mazedonien war, um gewissen Leuten zu verwehren, daß sie nicht afterlehren,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'Auch nicht Acht hätten auf Fabeln und auf Geschlechtsregister, die kein Ende haben und mehr zu Streitigkeiten führen als zu göttlicher Erbauung im Glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Der Endzweck der Lehre ist ja: Liebe aus reinem Herzen und gutem Gewissen und ungeheucheltem Glauben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'Wovon einige abgewichen sind, und zu unnützem Geschwätz sich gewendet haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'Wollen der Schrift Meister sein und verstehen nicht was sie sagen oder aufstellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Wir wissen aber, daß das Gesetz gut ist, wenn es einer gesetzmäßig anwendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'Und so viel weiß ich, daß für den Gerechten kein Gesetz gegeben ist, sondern für die Ungerechten und Ordnungsfeinde, für Gottlose und Sünder, Unheilige und Ungeistliche, für Vater- und Muttermörder, Totschläger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'Für Hurer, Knabenschänder, Menschendiebe, Lügner, Meineidige und was sonst der gesunden Lehre zuwider läuft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'Nach dem Evangelium der Herrlichkeit des seligen Gottes, das mir anvertraut worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Und ich danke Dem, Der mir die Kraft dazu gegeben, unserem Herrn Jesus Christus, daß Er mich für treu erachtet und mich ins Amt gesetzt hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'Mich, der ich vorher ein Lästerer, Verfolger und Schmäher war, aber ich fand Erbarmen, weil ich es unwissend im Unglauben tat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'Aber die Gnade unseres Herrn mit dem Glauben und der Liebe in Jesus Christus war um so überschwenglicher.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Das ist ja gewißlich wahr und ein teuer, wertes Wort, daß Jesus Christus in die Welt gekommen ist, die Sünder selig zu machen, unter denen ich der vornehmste bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Aber darum ist mir Barmherzigkeit widerfahren, daß an mir zuerst Jesus Christus erzeigte Seine Langmut, zum Vorbild denen, die an Ihn glauben würden zum ewigen Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Aber dem König der Ewigkeiten, dem unvergänglichen, unsichtbaren, alleinigen Gott sei Ehre und Herrlichkeit von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'Dies Gebot empfehle ich dir, mein Sohn Timotheus, nach den vorausgegangen Prophezeiungen über dich, daß du in denselben kämpfest den guten Kampf,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'Und habest einen guten Glauben, und ein gut Gewissen, welches gewisse Leute von sich gestoßen und am Glauben Schiffbruch gelitten haben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'Unter denen ist Hymenäus und Alexander, die ich dem Satan übergeben habe, auf daß sie gezüchtigt würden, nicht mehr zu lästern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'So ermahne ich nun, daß man vor allen Dingen zuerst tue Bitte, Gebet, Fürbitte, Danksagung für alle Menschen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'Für Könige und alle, die obenan stehen, auf daß wir ein geruhiges und stilles Leben führen, in aller Gottseligkeit und Ehrbarkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'Denn solches ist gut und wohlgefällig vor Gott, unserem Heiland,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'Der will, daß allen Menschen geholfen werde, und sie zur Erkenntnis der Wahrheit kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Denn es ist ein Gott, auch ein Mittler zwischen Gott und den Menschen, ein Mensch Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'Der Sich Selbst gegeben hat für alle zur Erlösung, daß es zu seiner Zeit bezeugt würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'Wofür ich zum Herold und Apostel gesetzt bin ich sage die Wahrheit');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'So will ich nun, daß die Männer allerorten beten, indem sie heilige Hände aufheben, ohne Zorn und böse Gedanken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Desgleichen sollen die Weiber mit anständigem Wesen, mit Zucht und Sittsamkeit sich schmücken, nicht mit künstlichem Kopfputz, mit Gold oder Perlen oder kostbarem Gewand,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'Sondern, wie es sich ziemt für Weiber, die sich zur Gottseligkeit bekennen, durch gute Werke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Ein Weib lerne in der Stille in aller Unterordnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Einem Weibe aber gestatte ich nicht, zu lehren, auch nicht, daß sie den Mann beherrsche, und sie soll sich ruhig verhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Denn Adam wurde zuerst geschaffen, hernach Eva.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'Auch wurde Adam nicht verführt, sondern das Weib ließ sich verführen und hat die Übertretung begangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'Sie wird aber selig werden durch Kindergebären, wenn sie im Glauben und in der Liebe und in der Heiligung und Sittsamkeit beharrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Das ist gewißlich wahr: So einer ein Bischofsamt begehrt, der begehrt ein köstlich Werk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Ein Bischof soll unsträflich sein, eines Weibes Mann, nüchtern, besonnen, ehrbar, gastfrei, lehrfähig;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'Kein Weinsäufer, kein Raufbold,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'Der seinem eigenen Hause wohl vorsteht und gehorsame Kinder hat, mit aller Ehrbarkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, 'So jemand seinem eigenen Hause nicht weiß vorzustehen, wie wird er für eine Gemeinde Gottes sorgen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'Kein Neuling, auf daß er sich nicht aufblase und nicht dem Urteil des Teufels verfalle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Er muß aber auch ein gutes Zeugnis haben von denen draußen, auf daß er nicht der Lästerung anheimfalle, und in den Fallstrick des Teufels gerate;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Desgleichen sollen die Diakone ehrbar sein, nicht doppelzüngig, nicht vielem Weintrinken ergeben, nicht nach schändlichem Gewinn trachten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'Sie sollen das Geheimnis des Glaubens in reinem Gewissen bewahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'Auch sollen sie erst erprobt werden, dann in das Amt treten, wenn sie unsträflich waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Die Weiber sollen gleichermaßen ehrbar sein, keine Lästerzungen, nüchtern und treu in allen Dingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Die Diakone sollen ein Weib haben, Haus und Kinder in Zucht halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Wenn sie ihrem Amte wohl vorstehen, gelangen sie auf eine Ehrenstufe und zu vieler Zuversicht im Glauben in Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'Solches schreibe ich an dich und hoffe in nächster Zeit zu dir zu kommen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'So ich aber verzöge, sollst du wissen, wie du dich zu verhalten hast im Hause Gottes, das ist die Gemeinde des lebendigen Gottes, als ein Pfeiler und eine Stütze der Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'Und anerkanntermaßen ist das Geheimnis der Gottseligkeit groß: Gott ist im Fleisch geoffenbart, gerechtfertigt im Geist, erschaut von Engeln, gepredigt unter Heiden, geglaubt in der Welt, aufgenommen in die Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Der Geist sagt ausdrücklich, daß in späteren Zeiten etliche vom Glauben abfallen und Irrgeistern und Lehren der Teufel anhangen werden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'Mittelst der Heuchelei von Lügenrednern, die in ihrem eigenen Gewissen gebrandmarkt sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'Die verbieten ehelich zu werden und gewisse Speisen zu genießen, die doch Gott geschaffen hat, daß sie mit Danksagung genossen werden von den Gläubigen und von denen, so die Wahrheit erkannt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Denn alles, was Gott erschaffen hat, ist gut, und nichts verwerflich, so es mit Danksagung empfangen wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'Denn es wird geheiligt durch das Wort Gottes und Gebet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'Wenn du den Brüdern solches vorhältst, so wirst du ein guter Diener Jesu Christi sein, auferzogen in den Worten des Glaubens und der rechten Lehre, der du gefolgt bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Habe nichts zu schaffen mit ungeistlichen Altweiberfabeln, übe dich selbst aber in der Gottseligkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'Die leibliche Übung ist wenig nütze, aber die Gottseligkeit ist zu allen Dingen nütze und hat die Verheißung dieses und des zukünftigen Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Dies ist gewißlich wahr, und ein teuer, wertes Wort.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Denn dafür mühen wir uns und lassen uns schmähen, daß wir auf den lebendigen Gott gehofft, Welcher ist der Heiland aller Menschen, besonders der Gläubigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Solches gebiete und lehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Niemand müsse deine Jugend verachten; sondern werde ein Vorbild der Gläubigen in der Lehre, im Wandel, in der Liebe, im Geist, im Glauben, in der Keuschheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Halte an mit Lesen, Ermahnen, mit Lehren, bis ich komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Laß nicht unbenützt die Gabe in dir, die dir gegeben ist, für Weissagung mit Handauflegung der Ältesten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Dies lasse dir angelegen sein, dabei bleibe, auf daß dein Fortschritt in allen Dingen sichtbar werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Habe Acht auf dich selbst, und auf die Lehre! Verbleibe dabei; denn wenn du solches tust, wirst du dir selbst und denen, die dich hören, zum Heile werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Fahre nicht aus gegen einen Alten, sondern ermahne ihn als einen Vater, jüngere als Brüder,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'Alte Frauen als Mütter, jüngere als Schwestern, in aller Sittsamkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Ehre Witwen, die rechte Witwen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'So aber eine Witwe Kinder oder Enkel hat, so sollen diese zuerst lernen ihr eigen Haus Gott wohlgefällig bestellen und ihren Eltern ihre Liebe vergelten, denn dies ist vor Gott angenehm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Die aber eine rechte Witwe und vereinsamt ist, hat ihre Hoffnung auf Gott gesetzt und beharrt in Bitten und Gebeten Tag und Nacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'So sie aber in Wollüsten lebt, ist sie lebendig tot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Solches gebiete, auf daß sie untadelhaft leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Wenn aber einer die Seinen, sonderlich seine Hausgenossen, nicht versorgt, der hat den Glauben verleugnet und ist ärger als ein Ungläubiger.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Nimm eine Witwe in die Zahl auf, die nicht unter sechzig Jahren,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'Ihrem Manne treu geblieben ist, und das Zeugnis guter Werke hat, wenn sie Kinder auferzogen, gastfrei gewesen ist, Heiligen die Füße gewaschen, Bedrängten Handreichung getan hat und jeglichem guten Werke nachgekommen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Die jungen Witwen aber halte fern; denn wenn sie lüstern geworden sind wider Christus, so wollen sie freien,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'Und fallen in Verantwortung, daß sie das erste Versprechen gebrochen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Auch sind sie lässig, lernen umlaufen in den Häusern, und tun nicht nur nichts, sondern sind auch schwatzhaft und fürwitzig und reden, was sie nicht sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Ich will, daß die Jüngeren freien, Kinder haben, einem Haushalt vorstehen, dem Widersacher keinen Anlaß zur Lästerung geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Denn schon sind etliche zurückgewichen, dem Satan nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Wenn ein Gläubiger oder eine Gläubige Witwen hat, so sollen sie für sie sorgen, und die Gemeinde nicht beschweren, auf daß sie denen, so rechte Witwen sind, genügen mögen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Die Ältesten, die würdig vorstehen, halte man doppelt in Ehren, absonderlich die, so in Wort und Lehre arbeiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Denn die Schrift sagt: Du sollst dem Ochsen, der da drischt, nicht das Maul verbinden. Und: Der Arbeiter ist seines Lohnes wert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Gegen einen Ältesten nimm keine Klage an, außer vor zwei oder drei Zeugen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Die Fehlenden weise zurecht vor allen, auf daß auch die anderen Furcht haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Ich beschwöre dich vor Gott und dem Herrn Jesus Christus und den auserwählten Engeln, daß du solches beobachtest, ohne Vorurteil und nichts tust aus Gunst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Lege niemand zu bald die Hände auf, und mache dich nicht fremder Sünden teilhaftig. Halte dich selber keusch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Trinke nicht mehr bloß Wasser, sondern nimm ein wenig Wein wegen deines Magens und deiner häufigen Anfälle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Einiger Menschen Sünden sind offenbar vor dem Gericht, andere kommen erst zutage durch dasselbe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Desgleichen sind auch gute Werke schon bekannt, und die anderen können nicht verborgen bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Die Knechte, die unter dem Joch sind, sollen ihre Herren aller Ehre wert erachten, auf daß nicht der Name Gottes und die Lehre verlästert werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Die aber gläubige Herren haben, sollen dieselben nicht verachten, weil sie Brüder sind, sondern um so mehr dienstwillig sein, weil sie gläubig und geliebt und der Gnade teilhaftig sind. Solches lehre und ermahne dazu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'So jemand anders lehrt und bleibt nicht bei den heilsamen Worten unseres Herrn Jesus Christus und bei der Lehre der Gottseligkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'Der ist verblendet und weiß nichts, sondern siecht an Streitfragen und Wortkämpfen, aus denen entspringt Neid, Streitsucht, Lästerung, böser Argwohn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'Unnütze Wortzänkereien von Menschen, deren Verstand verschroben und der Wahrheit verschlossen ist, die da meinen, Gottseligkeit sei ein Gewerbe. Halte dich ferne von ihnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Es ist aber ein großer Gewinn um die Gottseligkeit, die sich genügen läßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Denn wir haben nichts in die Welt gebracht, und offenbar ist, daß wir auch nichts mit hinausnehmen können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'Wenn wir aber Nahrung und Kleidung haben, so lasset uns daran begnügen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Die da reich werden wollen, fallen in Versuchung und Stricke und viel törichte und schädliche Lüste, welche die Menschen ins Elend und Verderben stürzen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Denn Geiz ist eine Wurzel alles Übels; diejenigen, die geldgierig und vom Glauben irre gegangen sind, haben sich selbst viele Schmerzen bereitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Aber du, Gottesmensch, fliehe solches, jage nach der Gerechtigkeit, der Gottseligkeit, dem Glauben, der Liebe, der Beharrlichkeit, der Sanftmut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Kämpfe den guten Kampf des Glaubens, erfasse das ewige Leben, für das du berufen bist und bekannt hast das gute Bekenntnis vor vielen Zeugen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Ich gebiete dir vor Gott, Der alles lebendig macht, und vor Jesus Christus, Der vor Pontius Pilatus das gute Bekenntnis bezeugt hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'Daß du haltest das Gebot unbefleckt, untadelhaft bis auf die Erscheinung unseres Herrn Jesus Christus;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'Welche zu Seiner Zeit zeigen wird der selige und alleinige Gewalthaber, der König der Könige und der Herr der Herren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'Der allein Unsterblichkeit hat, Der in unzugänglichem Lichte wohnt, Den kein Mensch gesehen hat, noch sehen kann, Ihm sei Ehre und ewige Herrschaft! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Den Reichen dieser Welt gebiete nicht hochmütig zu sein, noch Hoffnung zu setzen auf den unsicheren Reichtum, sondern auf den lebendigen Gott, Der uns alles reichlich zum Genusse darbietet;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'Daß sie Gutes tun, reich werden an guten Werken, freigebig, mitteilsam seien,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'Und sich Schätze sammeln als guten Grund für die Zukunft, auf daß sie das wahre Leben erfassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'O Timotheus, bewahre, was dir anvertraut ist, und mache dir nichts zu schaffen mit den gottlosen, leeren Reden und Streitfragen der fälschlich sogenannten Wissenschaft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'Die etliche vorgeben und vom Glauben abgewichen sind. Die Gnade sei mit euch! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Paulus, ein Apostel Jesu Christi durch den Willen Gottes, nach der Verheißung des Lebens in Christo Jesu, an seinen geliebten Sohn Timotheus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Gnade, Barmherzigkeit, Friede von Gott dem Vater, und unserem Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Ich danke Gott, Dem ich diene mit reinem Gewissen, von meinen Voreltern her, daß ich ohne Unterlaß dein gedenke in meinen Gebeten Tag und Nacht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'Weil ich mich sehne, dich zu sehen, eingedenk deiner Tränen, auf daß ich mit Freude erfüllt würde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'Denn ich gedenke an deinen ungeheuchelten Glauben, der zuerst gewohnt hat in deiner Großmutter Lois und deiner Mutter Eunike; ich bin aber gewiß, daß er auch in dir wohnt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Weshalb ich dich erinnere, daß du anfachst die Gabe Gottes, die durch Auflegung meiner Hände in dir ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Denn Gott hat uns nicht gegeben den Geist der Furcht, sondern der Kraft und der Liebe und der Zucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'So schäme dich nun nicht des Zeugnisses von unserem Herrn, noch auch meiner, der gefangen ist um Seinetwillen, sondern trage mit die Leiden für das Evangelium vermöge der Kraft Gottes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'Der uns erlöst und berufen hat mit heiligem Ruf, nicht nach unseren Werken, sondern nach Seinem Ratschluß, und der uns in Christus Jesus vor ewigen Zeiten verliehenen Gnade,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'Die aber jetzt geoffenbart ist durch die Erscheinung unseres Heilandes Jesus Christus, Der dem Tode die Macht genommen, und Leben und Unvergänglichkeit an das Licht gebracht hat durch das Evangelium,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'Für welches ich bestellt bin als Herold, Apostel und Lehrer der Heiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Um welcher Ursache willen ich auch solches erleide, aber ich schäme mich dessen nicht; denn ich weiß, an Wen ich geglaubt habe, und bin gewiß, daß Er mächtig ist, das mir Anvertraute zu bewahren bis auf jenen Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Halte an dem Vorbild der Heilsworte, die du von mir gehört in Glaube und Liebe in Christus Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Bewahre den kostbaren, dir anvertrauten Schatz durch den Heiligen Geist, der in uns wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'Du weißt, daß sich von mir abgewendet haben alle in Asien, unter denen ist Phygellus und Hermogenes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Der Herr schenke Barmherzigkeit dem Hause des Onesiphorus! Denn er hat mich oft erquickt, und hat sich meiner Kette nicht geschämt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'Sondern da er in Rom war, suchte er mich auf das Fleißigste und fand mich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, 'Der Herr lasse ihn an jenem Tage Barmherzigkeit finden vom Herrn; und wie große Dienste er in Ephesus geleistet hat, weißt du am besten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Du nun, mein Sohn, erstarke in der Gnade in Christo Jesu!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'Und was du von mir gehört hast vor vielen Zeugen, das vertraue treuen Menschen, die da tüchtig sind, auch andere zu lehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Du nun ertrage das Ungemach als ein wackerer Streiter Jesu Christi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Keiner, der Kriegsdienste tut, mengt sich in die Händel des Lebens, auf daß er dem gefalle, der ihn in Dienst genommen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Wenn einer aber auch kämpft, so wird er doch nicht gekrönt, er habe denn recht gekämpft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Der arbeitende Ackersmann soll der Früchte am ersten genießen; merke dir, was ich sage!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Der Herr aber möge dir in allen Dingen Einsicht verleihen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Halte im Gedächtnis Jesus Christus, Der von den Toten auferweckt worden aus dem Samen Davids, nach meinem Evangelium;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'Über dem ich leide bis zu Banden, wie ein Übeltäter, aber das Wort Gottes ist nicht in Banden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Darum erleide ich alles um der Auserwählten willen, auf daß auch sie des Heils in Christus Jesus mit ewiger Herrlichkeit teilhaftig werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Gewißlich wahr ist das Wort: Sterben wir mit, so werden wir auch mitleben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'Wenn wir ausharren, so werden wir auch mitherrschen; verleugnen wir, so wird auch Er uns verleugnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'Wenn wir nicht treu sind, so bleibt doch Er treu, Er kann Sich Selbst nicht verleugnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Daran erinnere sie, indem du den Herrn zum Zeugen aufrufst, sie sollten kein Wortgezänke führen, das zu nichts nütze ist und nur der Zuhörer Sinn verkehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Sei beflissen, dich vor Gott zu bewähren als einen Arbeiter, der sich nicht schämen darf, der mit dem Worte der Wahrheit recht umgeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Halte dich fern von ungeistlichen, losen Reden; denn sie helfen nur weiter in der Gottlosigkeit;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'Und ihr Wort frißt um sich, wie der Krebs. Unter denen ist Hymenäus und Philetus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'Die von der Wahrheit abgewichen sind und sagen, die Auferstehung sei schon geschehen, und etliche in ihrem Glauben irre machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Aber der feste Grund Gottes besteht, und hat dieses Siegel: Der Herr kennt die Seinen, und von der Ungerechtigkeit stehe ab, wer immer den Namen des Herrn nennt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'In einem großen Hause aber sind nicht allein goldene und silberne Gefäße, sondern auch hölzerne und irdene, einige zu edlerem und einige zu unedlerem Gebrauch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Wenn nun jemand sich rein hält von diesen, so wird er ein Gefäß zur Ehre, geweiht und brauchbar für den Hausherrn und bereitet zu jeglichem guten Werk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Fliehe aber die jugendlichen Lüste, jage nach der Gerechtigkeit, dem Glauben, der Liebe, dem Frieden mit denen, die von reinem Herzen den Herrn anrufen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Aber der törichten und albernen Streitfragen entschlage dich; denn du weißt, daß sie Wortkämpfe erzeugen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Ein Knecht aber des Herrn soll nicht streiten, sondern liebreich sein gegen alle, tüchtig zum Lehren und Böses ertragen können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'Er soll mit Sanftmut die Widerspenstigen zurechtweisen, ob ihnen vielleicht Gott den Sinn zur Buße kehre, daß sie die Wahrheit erkennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'Und wieder zu sich kommen aus der Schlinge des Teufels, in der sie von ihm für seinen Willen gefangengehalten wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'Das aber sollst du wissen, daß in den letzten Tagen arge Zeiten kommen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Denn die Menschen werden sein eigenliebig, habsüchtig, ruhmredig, hoffärtig, Lästerer, den Eltern ungehorsam, undankbar, gottlos,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'Lieblos, unversöhnlich, Verleumder, unkeusch, unbändig, dem Guten feind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'Verräterisch, verwegen, aufgeblasen, Sinnenlust mehr liebend denn Gott;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'Die sich den Schein der Gottseligkeit geben, aber deren Kraft verleugnen; von solchen wende dich ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Zu diesen gehören die, so sich in die Häuser schleichen und die Weiblein an sich fesseln, die, mit Sünden beladen, von mancherlei Lüsten getrieben werden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'Die immerdar lernen und doch nie zur Erkenntnis der Wahrheit gelangen können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Gleichwie Jannes und Jambres dem Mose widerstanden, also widerstehen auch diese der Wahrheit. Es sind Menschen verkehrten Sinnes, unbewährt im Glauben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Aber sie werden es nicht in die Länge treiben; denn ihre Torheit wird allen offenbar werden, wie auch jener geworden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Du aber bist meiner Lehre, meinem Wandel, meinem Ratschluß, meinem Glauben, meiner Langmut, meiner Liebe, meiner Beständigkeit gefolgt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'Ja meinen Verfolgungen, meinen Leiden, die mir widerfahren sind zu Antiochia, Ikonium und Lystra, welche Verfolgungen ich ertrug, und aus allen hat mich der Herr errettet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Und alle, die in Christus Jesus gottselig leben wollen, müssen Verfolgungen erleiden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Mit den Bösen aber wird es je länger je ärger werden; sie werden irre führen und selbst in der Irre gehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Du aber verbleibe bei dem, was du gelernt, und wovon du eine gewisse Überzeugung erlangt hast, da du ja weißt, von wem du es gelernt hast,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'Und da du von Kindheit auf die heiligen Schriften kennst, die dich zur Seligkeit mittelst des Glaubens an Jesus Christus unterweisen können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Alle Schrift, von Gott eingegeben, ist nütze zur Lehre, zur Rüge, zur Besserung, zur Zucht in der Gerechtigkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'Auf daß der Mensch aus Gott vollkommen zu jeglichem guten Werk geschickt sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Ich beschwöre dich nun vor Gott und Jesus Christus, Der da richten wird die Lebendigen und die Toten bei Seiner Erscheinung und in Seinem Reiche:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Predige das Wort, halte damit an zur gelegenen oder ungelegenen Zeit, rüge, warne, ermahne mit aller Langmut und Lehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Denn es wird eine Zeit kommen, wo sie die gesunde Lehre nicht ertragen, sondern nach eigenen Gelüsten sich mit Lehrern umgeben werden, die ihre Ohren kitzeln,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'Und werden die Ohren von der Wahrheit abwenden und sich Märchen zuwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Du aber bleibe nüchtern in allem, ertrage Beschwerde, verrichte das Werk eines Evangelisten und tue, was deines Amtes ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Denn schon werde ich geopfert und die Stunde meines Hinscheidens naht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Ich habe einen guten Kampf gekämpft, ich habe den Lauf vollendet, ich habe den Glauben bewahrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'Schon liegt für mich bereit die Krone der Gerechtigkeit, die mir an jenem Tage der Herr, Der gerechte Richter, geben wird, aber nicht allein mir, sondern allen, die Seine Erscheinung lieb haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Beeile dich, daß du bald zu mir kommst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'Denn Demas hat mich verlassen und diese Welt lieb gewonnen, und ist gezogen nach Thessalonich, Crescens nach Galatien, Titus nach Dalmatien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Lukas ist allein bei mir, Markus nimm zu dir, und bringe ihn mit dir, er ist mir nützlich zum Dienst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tychikus habe ich nach Ephesus gesandt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Den Mantel, den ich bei Karpus in Troas gelassen, bringe mit, wenn du kommst, auch die Bücher, sonderlich aber die Pergamentrollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Alexander, der Schmied, hat mir viel Böses erwiesen; der Herr vergelte ihm nach seinen Werken!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Auch du hüte dich vor ihm; denn er ist unseren Worten sehr entgegengetreten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'In meiner ersten Verantwortung stand mir niemand zur Seite; alle verließen mich möge es ihnen nicht angerechnet werden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Der Herr aber stand mir bei und schenkte mir Kraft, auf daß durch mich die Predigt bestätigt würde und alle Heiden sie hörten, und ich bin aus des Löwen Rachen erlöst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Und der Herr wird mich erlösen von allem Übel und mich retten in Sein Himmelreich. Ihm sei Ehre von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Grüße Prisca und Aquila und das Haus des Onesiphorus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erastus blieb in Korinth, den Trophimus ließ ich krank in Milet zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Beeile dich, daß du noch vor dem Winter kommst. Es grüßt dich Eubulus und Pudens und Linus und Claudia und die Brüder alle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Der Herr Jesus Christus sei mit deinem Geiste! Die Gnade sei mit euch!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Paulus, Knecht Gottes, Apostel Jesu Christi, nach dem Glauben der Auserwählten Gottes und der Erkenntnis der Wahrheit, die zur Gottseligkeit führt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'Auf Hoffnung des ewigen Lebens, das der Gott, Der nicht trügt, vor ewigen Zeiten verheißen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'Aber zu Seiner Zeit Sein Wort geoffenbart hat durch die Predigt, die mir vertraut worden ist nach dem Befehle Gottes, unseres Heilandes:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Titus, meinem rechtschaffenen Sohn im gemeinsamen Glauben, Gnade, Barmherzigkeit, Friede von Gott dem Vater und dem Herrn Jesus Christus, unserem Heiland.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Ich ließ dich deshalb in Kreta, daß du das noch übrige in Ordnung brächtest und in den Städten Älteste bestelltest, wie ich dir geboten hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'Wenn einer unbescholten, eines Weibes Mann ist, gläubige Kinder hat, und die nicht im Geruche der Schwelgerei und unordentlichen Wandels stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Denn ein Bischof soll unbescholten sein, als ein Haushalter Gottes, nicht anmaßend, leidenschaftlich, dem Trunk ergeben, streitsüchtig, nicht schändlichem Gewinn nachgehend,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'Sondern gastfrei, allen Guten befreundet, besonnen, gerecht, heilig, enthaltsam,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'Und halte an dem Wort und der zuverlässigen Lehre, auf daß er tüchtig sei, auch in der heilsamen Lehre zu ermahnen und die, so widersprechen, zurechtzuweisen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Denn es gibt viele, die sich der Lehre nicht fügen wollen, unnütze Schwätzer und Verführer, besonders solche aus der Beschneidung, die man zum Schweigen bringen muß;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'Sie verwirren ganze Häuser, und lehren, was nichts taugt, um schmählichen Gewinnes willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'So sagte einer von ihnen, ihr eigener Prophet: Die Kreter sind immer Lügner, böse Tiere, faule Bäuche.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'Dies Zeugnis ist wahr; deshalb weise sie strenge zurecht, auf daß sie im Glauben gesund seien,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'Nicht auf jüdische Irrlehren und Satzungen von Menschen hören, die sich von der Wahrheit abwenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Den Reinen ist alles rein, den Befleckten aber und Ungläubigen ist nichts rein, sondern ihr Verstand und Gewissen sind befleckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Sie sagen, sie kennen Gott, verleugnen Ihn aber mit den Werken, sind greuelhaft und ungehorsam und zu allem guten Werke untüchtig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Du aber sprich, was der gesunden Lehre angemessen ist:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Zu den alten Männern, sie sollen nüchtern, würdig, besonnen, gesund im Glauben, in der Liebe, in der Standhaftigkeit sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'Zu den betagten Frauen desselben gleichen, daß sie sich benehmen sollen, wie es Heiligen geziemt, nicht lästern, nicht vielem Wein sich ergeben, gute Lehren erteilen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'So daß sie die jungen Weiber lehren, ihre Männer und Kinder zu lieben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'Sittsam, keusch, häuslich, gütig, ihren Männern untertan zu sein, auf daß nicht das Wort Gottes verlästert werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Die jungen Männer aber ermahne gleichfalls zur Besonnenheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'In allen Dingen stelle dich selbst als Muster guter Werke dar mit unverfälschter Lehre und würdevollem Betragen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'Mit gesundem, untadelhaftem Worte, so daß der Widersacher sich schämen müsse, und uns nichts Unrechtes nachreden könne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Zu den Knechten, daß sie ihren Herren untertan und in allen Stücken wohlgefällig sein und nicht widersprechen sollen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'Nichts veruntreuen, sondern alle gute Treue erweisen, auf daß sie die Lehre Gottes unseres Heilandes zieren in allen Stücken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Denn die heilsame Gnade Gottes ist für alle Menschen erschienen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'Indem sie uns anhält, der Gottlosigkeit und allen weltlichen Gelüsten zu entsagen, und sittsam, gerecht und gottselig zu leben in dieser Welt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'Und zu warten der seligen Hoffnung auf die Erscheinung der Herrlichkeit des großen Gottes und unseres Heilandes Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'Der Sich Selbst für uns hingegeben hat, auf daß Er uns erlösete von aller Ungerechtigkeit, und Sich weihete zum Eigentum ein Volk, das eifrig wäre zu guten Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'Solches rede, ermahne und schärfe ein mit allem Ernst. Niemand müsse dich verachten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Dringe darauf, daß sie den Obrigkeiten und Gewalten untertan sein, Gehorsam leisten, zu allem guten Werke bereit sein sollen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'Daß sie niemand verlästern, nicht streitsüchtig, sondern nachgiebig sein, alle Sanftmut beweisen sollen gegen alle Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Denn auch wir waren vordem unverständig, ungehorsam, irrgläubig, frönten mancherlei Begierden und Wollüsten, lebten in Bosheit und Neid, wurden gehaßt und haßten einander.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Als aber die Güte und Menschenfreundlichkeit Gottes unseres Heilandes erschien,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'Erlöste Er uns, nicht um der Werke der Gerechtigkeit willen, die wir getan, sondern aus Barmherzigkeit durch das Bad der Wiedergeburt und Erneuerung des Heiligen Geistes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'Den Er reichlich über uns ausgegossen hat durch unseren Heiland Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'Auf daß wir, durch Seine Gnade gerechtfertigt, nach der Hoffnung Erben werden des ewigen Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Diese Lehre ist gewißlich wahr, und ich wünsche, daß du darüber eine feste Überzeugung gewinnst, auf daß die, so an Gott glauben, sich befleißigen, gute Werke zu tun. Solches ist gut und nützt den Menschen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'Aber mit den törichten Streitfragen und Geschlechtsregistern, Zänkereien und Streitereien über das Gesetz habe du nichts zu tun; denn sie sind unnütz und eitel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Einen parteisüchtigen Menschen weise ab, wenn du ihn ein- oder zweimal zurechtgewiesen hast,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'Und sei versichert, daß ein solcher verkehrt ist und sündigt, und sich selbst verurteilt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Wenn ich Artemas oder Tychicus zu dir sende, so beeile dich, zu mir nach Nikopolis zu kommen; denn ich gedenke dort über den Winter zu bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Sorge auf das Beste für das Geleit des Gesetzgelehrten Zenas und des Apollos, auf daß ihnen nichts mangle.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Es mögen aber auch die unseren lernen gute Werke üben, wo man ihrer bedarf, auf daß sie nicht unfruchtbar seien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Es grüßen dich alle, die bei mir sind. Grüße die, so uns lieben im Glauben. Die Gnade sei mit euch allen! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Paulus, der Gefangene Jesus Christi, und Timotheus, der Bruder, an den geliebten Philemon, unseren Mitarbeiter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'Und an die geliebte Appia und unseren Streitgenossen Archippus und die Gemeinde in deinem Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Gnade sei mit euch und Friede von Gott, unserem Vater und Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Ich danke allezeit meinem Gott, indem ich deiner in meinen Gebeten gedenke,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'Weil ich höre von deiner Liebe zu allen Heiligen und deinem Glauben an den Herrn Jesus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'Daß dein Glaube, den du mit uns teilst, sich wirksam erweise durch die Erkenntnis all des Guten, das in uns ist, für Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Denn wir haben große Freude und viel Trost durch deine Liebe, daß die Herzen der Heiligen durch dich, Bruder, erquickt worden sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Wiewohl ich mir in Christus getraute, dir zu gebieten, was Pflicht für dich ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'So wende ich mich doch lieber an deine Liebe als der alte Paulus, und der jetzt wegen Jesus Christus in Banden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'Ich bitte dich für meinen Sohn Onesimus, den ich in meinen Banden gezeugt habe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'Der dir früher unnütz war, nun aber dir und mir wohl nütze ist; den sende ich zurück.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'Du aber nimm ihn, das ist mein eigen Herz, wieder an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Gern hätte ich ihn bei mir behalten, daß er mir in den Banden statt deiner für das Evangelium Dienste tue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'Aber ohne deine Genehmigung wollte ich nichts tun, auf daß dein Gutes nicht gezwungen, sondern freiwillige Entschließung wäre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Vielleicht ist er nur darum eine Zeitlang von dir getrennt worden, auf daß du ihn auf ewig wieder habest,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'Nun nicht mehr als einen Knecht, sondern mehr denn einen Knecht, als einen lieben Bruder, sonderlich mir, wieviel mehr aber dir, sowohl im Fleische, als im Herrn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'So du mich nun für deinen Genossen hältst, so nimm ihn auf wie mich selbst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'So er dir aber Schaden getan hat, oder etwas schuldig ist, so rechne das mir zu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'Ich Paulus habe es mit eigener Hand geschrieben, ich will es bezahlen; nicht zu sagen, daß du dich selbst mir schuldig bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Ja, Bruder, gönne mir diesen Gewinn an dir in dem Herrn; erquicke mein Herz in dem Herrn!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Ich schreibe dir im Vertrauen auf deinen Gehorsam und weiß, du wirst mehr tun, denn ich sage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Halte mir auch eine Herberge bereit, denn ich hoffe, daß ich durch eure Gebete euch werde wieder geschenkt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Es grüßt dich Epaphras, mein Mitgefangener in Christus Jesus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'Markus, Aristarchus, Demas, Lukas, meine Mitarbeiter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Die Gnade unseres Herrn Jesus Christus sei mit eurem Geiste! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Nachdem vor Zeiten Gott vielfältig und auf verschiedene Weise zu den Vätern durch die Propheten geredet hatte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'So hat Er in den letzten Tagen zu uns geredet durch den Sohn, Den Er zum Erben über alles gesetzt, durch Den Er auch die Welten erschaffen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'Welcher, weil Er der Abglanz Seiner Herrlichkeit und das Ebenbild Seines Wesens und durch das Wort Seiner Kraft der Träger aller Dinge ist, und');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'Und ist um so viel höher geworden denn die Engel, einen je höheren Namen Er von ihnen ererbt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Denn zu welchem Engel hat Er je gesagt: Du bist Mein Sohn, heute habe Ich dich gezeugt? und abermals: Ich werde Ihm Vater sein, und Er wird Mir Sohn sein?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'Und abermals, wann Er den Erstgeborenen eingeführt hat in die Welt, dann spricht Er: Und es sollen Ihn anbeten alle Engel Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'Und von den Engeln sagte Er zwar: Er macht Seine Engel zu Winden und Seine Diener zu Feuerflammen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'Vom Sohn aber: Gott, Dein Thron währt in Zeit und Ewigkeit, das Zepter Deines Reiches ist ein Zepter der Geradheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Du hast geliebt Gerechtigkeit und gehaßt Ungerechtigkeit, darum hat Dich Gott, Dein Gott, gesalbt mit dem Öl der Freuden über Deine Genossen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'Und Du, Herr, hast am Anfang die Erde gegründet und Werke Deiner Hände sind die Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'Sie werden vergehen, Du aber bleibst, und sie werden alle veralten wie ein Kleid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'Wie ein Gewand wirst Du sie aufrollen, und sie werden verwandelt werden; Du aber bist Derselbe, und Deine Jahre nehmen kein Ende.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Zu welchem der Engel hat Er je gesagt: Setze Dich zu Meiner Rechten, bis Ich Deine Feinde zum Schemel Deiner Füße lege?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Sind sie nicht allzumal dienstbare Geister, und werden ausgesandt zum Dienst um derer willen, die ererben sollen die Seligkeit?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Darum müssen wir um so mehr achten auf das, was wir hören, damit wir nicht darum kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Denn so das Wort, durch die Engel gesprochen, bestätigt worden ist, und jegliche Übertretung und aller Ungehorsam den verdienten Lohn empfangen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'Wie wollen wir entfliehen, so wir eine so wichtige Heilslehre mißachtet haben, die zuerst durch den Herrn gepredigt und von denen, die sie gehört, für uns bestätigt worden ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'Indem Gott es mitbezeugte mit Zeichen, Wundern und mancherlei Kräften und mit Austeilung des Heiligen Geistes nach Seinem Willen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Denn Er hat nicht den Engeln untergetan die zukünftige Welt, von der wir reden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Vielmehr hat irgendwo einer bezeugt und gesagt: Was ist der Mensch, daß seiner Du gedenkst, und des Menschen Sohn, daß Du nach Ihm siehst?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Du hattest Ihn auf eine kurze Zeit unter die Engel erniedrigt, hast Ihn dann aber mit Herrlichkeit und Würde gekrönt und über die Werke Deiner Hände gesetzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'Du hast alles unter Seine Füße gelegt. Denn da Er Ihm alles hat untergetan, hat Er nichts gelassen, das Ihm nicht untertan wäre. Jetzt aber sehen wir noch nicht, daß Ihm alles untertan ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'Ihn aber, Jesus, Der auf kurze Zeit unter die Engel erniedrigt war, auf daß Er durch die Gnade Gottes für alle den Tod schmecke, sehen wir nun durch Sein Todesleiden mit Preis und Herrlichkeit gekrönt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Denn es ziemte, Den, für Den und durch Den alles ist, nachdem Er viele Söhne zur Herrlichkeit geführt, den Führer zu ihrem Heil durch Leiden zur Vollendung zu bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Denn Er, der Heiligende, und die da geheiligt werden, sind alle aus Einem, aus welcher Ursache Er keinen Anstand nimmt, sie Brüder zu nennen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, 'Und spricht: Ich will Meinen Brüdern Deinen Namen verkündigen und mitten in der Gemeinde Dir lobsingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'Und abermals: Ich werde Mein Vertrauen auf Ihn setzen. Und abermals: Siehe, Ich und die Kindlein, die Gott Mir gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Weil nun die Kindlein Fleisch und Blut gemein haben, so hat auch Er gleichermaßen an denselben teilgenommen, auf daß Er durch den Tod den, der Macht hatte über den Tod, das ist den Teufel, überwände,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'Und erlöste die, so durch Furcht des Todes ihr Leben lang in Knechtschaft gehalten waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Denn Er nimmt Sich nirgends der Engel an, sondern des Samens Abrahams nimmt Er Sich an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Darum mußte Er auch in allem den Brüdern gleich werden, auf daß Er barmherzig wäre und vor Gott ein treuer Hoherpriester würde, um die Sünden des Volkes zu sühnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Denn worin Er Selbst gelitten hat und versucht worden ist, darin kann Er denen helfen, die in Versuchung kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Darum, ihr heiligen Brüder, die ihr teilhabt an der himmlischen Berufung, schaut hin auf den Apostel und Hohenpriester unseres Bekenntnisses, Jesus Christus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'Der da treu ist dem, der Ihn bestellt, wie auch Moses in seinem ganzen Hause.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Denn Er ist höherer Herrlichkeit denn Moses gewürdigt worden, sofern der, so das Haus baut, größeren Wert hat, als das Haus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Denn ein jegliches Haus wird von jemand bereitet, Der aber alles bereitet hat, ist Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'Und Moses war treu in seinem ganzen Hause, als ein Diener, zum Zeugnis dessen, das verkündet werden sollte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Christus aber als Sohn über das eigene Haus, Dessen Haus wir sind, so wir anders das Vertrauen und den Ruhm der Hoffnung bis an das Ende festhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Darum, wie der Heilige Geist spricht: Heute, so ihr hören werdet Seine Stimme,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'So verstockt eure Herzen nicht, wie es geschah bei der Erbitterung am Tage der Versuchung in der Wüste;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'Da eure Väter Mich versuchten, Mich auf die Probe stellten, und doch vierzig Jahre Meine Werke sahen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Darum ward Ich entrüstet wider dies Geschlecht und sprach: Ihr Herz irrt immer ab. Sie aber erkannten Meine Wege nicht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'So daß Ich schwur in Meinem Grimm, sie sollten nicht zu Meiner Ruhe eingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Seht zu, meine Brüder, daß nicht bei einem unter euch ein arges Herz des Unglaubens sich finde, das da abtrünnig würde von dem lebendigen Gott;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'Sondern ermahnt euch jeden Tag untereinander, solange es heute heißt, daß nicht einer unter euch durch den Trug der Sünde verstockt werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Denn wir sind Christus Mitgenossen geworden, wenn anders wir bei dem angefangenen Werk beständig sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'Solange es heißt: Heute, so ihr Seine Stimme hört, so verstockt eure Herzen nicht, wie bei der Erbitterung geschah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Denn wer waren die, welche die');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Über welche war Er entrüstet die vierzig Jahre lang? Waren es nicht solche, deren Leiber in der Wüste ihr Grab gefunden?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Welchen schwur Er, daß sie nicht zu Seiner Ruhe eingehen sollten, wenn nicht den Ungehorsamen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'Und wir sehen, daß sie ihres Unglaubens wegen nicht hineinkommen konnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'So lasset uns Sorge tragen, daß wir die Verheißung, zu Seiner Ruhe einzugehen, nicht versäumen, und unser keiner dahinten bleibe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Denn es ist auch uns verkündigt wie jenen, aber das Wort der Verkündigung half jenen nichts, da es sich nicht mit dem Glauben derer, die es hörten, verband.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Denn wir, die wir geglaubt haben, gehen in die Ruhe ein, wie Er spricht: Wie Ich schwur in Meinem Zorn, sie sollten nicht zu Meiner Ruhe eingehen; obschon die Werke seit Gründung der Welt vollendet waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'Denn Er sprach an einer Stelle von dem siebenten Tage also: Und Gott ruhte am siebenten Tage von allen Seinen Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'Und an dieser Stelle abermals: Sie sollen nicht zu Meiner Ruhe eingehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Weil es also vorbehalten ist, daß etliche zu derselben eingehen sollten, und die, denen es zuerst verheißen war, ihres Unglaubens wegen nicht dazu gekommen sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'Bestimmte Er abermals einen Tag, indem Er nach so langer Zeit durch David sagte: Heute, wie gesagt ist, heute, so ihr Seine Stimme hören werdet, verstockt eure Herzen nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Denn so Josua sie hätte zur Ruhe gebracht, so würde Er hernach von keinem anderen Tag gesprochen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Es ist also noch eine Sabbathruhe vorhanden für das Volk Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Denn wer zu Seiner Ruhe eingegangen ist, ruht auch selbst von seinen Werken, wie auch Gott von den Seinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'So lasset uns nun Fleiß tun, einzugehen zu dieser Ruhe, auf daß nicht einer ein warnendes Beispiel dieses Ungehorsams werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Denn das Wort Gottes ist lebendig und kräftig, und schärfer als irgendein zweischneidig Schwert, und dringt hindurch durch Mark und Bein, bis daß es Seele und Geist zerschneide, und ist ein Richter der Gedanken und Gesinnungen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'Und ist kein Geschöpf vor Ihm unsichtbar, alles bloß und aufgedeckt vor Dessen Augen, zu Dem wir reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Weil wir denn einen großen Hohenpriester haben, Der durch die Himmel hindurchgegangen ist, Jesus, den Sohn Gottes, so lasset uns festhalten an dem Bekenntnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Denn wir haben nicht einen Hohenpriester, der nicht könnte mitfühlen mit unseren Schwachheiten, weil Er versucht worden ist in allen Stücken gleich wie wir, doch ohne Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'So lasset uns denn mit Vertrauen hinzutreten vor den Gnadenthron, auf daß wir Erbarmen und Gnade finden auf die Zeit, da uns Hilfe vonnöten ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Denn ein jeglicher Hohepriester, aus den Menschen genommen, wird aufgestellt für Menschen, in ihren Angelegenheiten bei Gott Gaben und Opfer für Sünden darzubringen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'Und kann milde sein gegen Unwissende und Irrende, weil auch er der Schwachheit teilhaftig ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'Und muß um dieser willen, wie für das Volk, so auch für sich selbst Sündopfer darbringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'Und niemand nimmt sich selbst die Ehre, sondern muß wie Aharon von Gott dazu berufen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Also hat auch Christus nicht Sich Selbst in die Ehre eingesetzt, Hoherpriester zu werden, sondern Der zu Ihm gesprochen hat: Mein Sohn bist Du, heute habe Ich Dich gezeugt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Wie Er auch an einer anderen Stelle sagt: Du bist Priester in Ewigkeit, nach der Ordnung Melchisedeks.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'Und Er hat in den Tagen Seines Fleisches Gebet und Flehen an Den, Der Ihn vom Tode retten konnte, mit lautem Rufe und mit Tränen dargebracht und ist erhört worden wegen Seiner Frömmigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'Und wiewohl Er Gottes Sohn war, hat Er doch an dem, was Er litt, Gehorsam gelernt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'Und da Er ist vollendet, ist Er allen, die Ihm gehorsam sind, Urheber ewiger Seligkeit geworden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'Erklärt von Gott zum Hohenpriester nach der Ordnung Melchisedeks.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'Davon hätten wir wohl viel zu reden, aber es ist schwer auszulegen, weil ihr wieder so träge zum Verständnis geworden seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Denn da ihr längst solltet Meister sein der Zeit nach, bedürft ihr selber wieder Belehrung über die Anfangsgründe der Lehre Gottes, und seid solche geworden, daß ihr Milch und nicht feste Speise bedürfet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Denn wer noch Milch haben muß, der ist noch unerfahren im Worte der Gerechtigkeit, denn er ist noch unmündig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Feste Speise gehört den Vollkommenen, die durch Übung eine schärfere Fassungskraft haben zur Unterscheidung von dem, was recht und unrecht ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Darum wollen wir die Anfangslehre von Christus beiseite lassen, und uns zum Vollkommeneren wenden, ohne uns noch einmal mit der Grundlage der Bekehrung von toten Werken, dem Glauben an Gott,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'Der Taufe, der Lehre, der Auflegung der Hände, der Auferstehung der Toten und dem ewigen Gerichte zu befassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'Und das wollen wir tun, wenn anders Gott es uns verleiht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Denn es ist unmöglich, die, so einmal erleuchtet worden und die himmlische Gabe geschmeckt haben, und des Heiligen Geistes teilhaftig geworden sind,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'Zudem noch geschmeckt haben das herrliche Gotteswort, die Kräfte der zukünftigen Welt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'Wo sie wiederum abgefallen, zu erneuern zur Buße, als die in ihnen selbst den Sohn Gottes kreuzigen und zum Gespötte haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Denn eine Erde, die den oft über sie kommenden Regen trinkt, und denen, für die sie auch bebaut wird, nützliche Gewächse trägt, empfängt Segen von Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Die aber, so Dornen und Disteln trägt, ist unnütz und dem Fluche nahe; ihr Ende ist, daß man sie ausbrennt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Wir versehen uns aber zu euch, Geliebte, eines Besseren, und das zum Heile führt, obwohl wir also reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Denn Gott ist nicht ungerecht, daß Er vergäße eures Werkes und eurer Liebtätigkeit, die ihr an Seinem Namen bewiesen, da ihr den Heiligen Dienst geleistet habt, und noch leistet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Wir wünschten aber, daß jeder von euch denselben Eifer beweise, die Hoffnung bis ans Ende voll zu bewahren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'Daß ihr nicht müde werdet, sondern nacheifert im Glauben und in der Ausdauer denen, so die Verheißung ererben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Denn als Gott dem Abraham eine Verheißung machte, schwur Er, da Er bei nichts Höherem schwören konnte, bei Sich Selbst,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'Und sprach: Wahrlich, Ich will dich reichlich segnen und vermehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'Und so harrte er aus, und erlangte, was ihm verheißen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Die Menschen schwören bei dem Höheren, und der Eid macht bei ihnen allem Streit ein Ende durch diese Bekräftigung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Darum, da Gott wollte den Erben der Verheißung die Unwandelbarkeit Seines Ratschlusses dartun, hat Er ihn durch einen Eid vermittelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'Auf daß zwei unwandelbare Stücke, bei denen nicht möglich ist, daß Gott lügen könnte, einen starken Trost gewähren uns, die wir unsere Zuflucht nehmen zu der uns gewährten Hoffnung, und an ihr halten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'Die wir haben als sicheren und zuverlässigen Anker der Seele, der auch hineinreicht in das Inwendige des Vorhangs;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'Dahin auch unser Vorgänger Jesus für uns eingegangen, Der nach der Ordnung Melchisedeks Hoherpriester in Ewigkeit geworden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Dieser Melchisedek war nämlich König zu Salem, ein Priester Gottes, des Allerhöchsten, der dem Abraham entgegenging, als er aus der Schlacht wider die Könige siegreich zurückkehrte, und ihn segnete;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'Dem auch Abraham von allem den Zehnten gab. Auf das erste wird er verdolmetscht König der Gerechtigkeit; sodann aber ist er auch König von Salem, das ist König des Friedens,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'Ohne Vater, ohne Mutter, ohne Geschlechtsnachweis, und hat weder Anfang der Tage noch Ende des Lebens, ein Abbild des Sohnes Gottes, bleibt Er Priester in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Ihr seht aber, wie groß Er ist, Dem auch der Erzvater Abraham den Zehnten von der Beute gibt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'Zwar haben die von den Kindern Levi, so die Priesterwürde empfangen, ein Gebot, nach dem Gesetz vom Volk, das heißt von ihren Brüdern, den Zehnten zu nehmen, wiewohl auch sie aus den Lenden Abrahams gekommen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'Aber Er, Dessen Geschlecht unter ihnen nicht aufgeführt wird, nahm den Zehnten von Abraham, und segnete den, der die Verheißung hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'Nun ist es ohne allen Widerspruch also, daß das Geringere von dem Besseren gesegnet wird,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'Und hier nehmen den Zehnten sterbliche Menschen, dort aber Einer, von Dem bezeugt wird, daß Er lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'Und durch Abraham wird sozusagen auch von Levi, der den Zehnten nimmt, der Zehnte genommen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'Denn er war noch in den Lenden des Vaters, da ihm Melchisedek entgegenging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Wäre nun die Vollendung durch das levitische Priestertum geschehen');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Denn wo das Priestertum verändert wird, da wird notwendig auch das Gesetz verändert,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Denn Der, von Dem solches gesagt wird, gehört zu einem anderen Stamm, aus dem nie einer am Altar zu tun gehabt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Es ist ja offenbar, daß unser Herr aus Judah hervorgegangen ist, über welchem Stamm Moses in bezug auf das Priestertum nichts geredet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'Und es ist noch viel mehr offenbar, wenn nach der Ordnung Melchisedeks ein anderer Priester aufkommt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'Der es nicht nach dem Gesetz eines fleischlichen Gebotes geworden ist, sondern nach der Kraft unvergänglichen Lebens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'Denn Er bezeugt: Du bist Priester in Ewigkeit nach der Ordnung Melchisedeks.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'Denn es findet eine Aufhebung des früheren Gebotes statt, weil es zu schwach und unwirksam');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, 'Das Gesetz brachte ja nichts zur Vollendung und es erfolgt die Einführung einer besseren Hoffnung, durch die wir uns Gott nahen dürfen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'Und inwiefern dies nicht ohne eidliche Zusicherung geschieht jene sind ja ohne Eidschwur Priester geworden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, 'Er aber mit einem Eidschwur durch Den, Der da zu Ihm spricht: Der Herr hat geschworen, und es wird Ihn nicht gereuen: Du bist Priester in Ewigkeit nach der Ordnung Mel- chisedeks],');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'In sofern auch ist Jesus eines um so besseren Bundes Bürge geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'Und jener sind viele, die Priester wurden, darum, daß sie durch den Tod es nicht bleiben durften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'Er aber hat dadurch, daß Er es in Ewigkeit bleibt, ein unvergängliches Priestertum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Darum kann Er auch ganz und gar erretten diejenigen, die durch Ihn vor Gott treten, da Er ewiglich lebt und Sich ihrer annehmen kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Denn ein solcher Hoherpriester ziemte uns, heilig, unschuldig, unbefleckt, von den Sündern abgesondert, höher denn die Himmel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'Der nicht, wie jene Hohenpriester, erst für die eigenen Sünden, dann für die des Volkes täglich Opfer darzubringen hatte; denn dies tat Er ein für allemal, indem Er Sich Selbst darbrachte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Denn das Gesetz bestellt Menschen zu Hohenpriestern, die Schwachheit an sich haben, das Wort aber der eidlichen Verhei-ßung, die später als das Gesetz gemacht wurde, den Sohn, Der ewiglich vollendet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Der Inbegriff dieser Reden aber ist: Wir haben einen solchen Hohenpriester, Der da sitzt zur Rechten auf dem Throne der Majestät in den Himmeln;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'Als Priester des Heiligen und des wahren Versammlungszeltes, welches der Herr und nicht ein Mensch aufgerichtet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Denn jeglicher Hohepriester wird eingesetzt, Gaben und Opfer darzubringen. Darum muß auch Er etwas haben darzubringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Denn wenn Er auf Erden wäre, so wäre Er nicht einmal Priester, weil Priester da sind, die nach dem Gesetz die Gaben opfern,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Die ihr Amt tun nach dem Vorbild und Schatten der himmlischen Dinge, wie Moses angewiesen worden, da er das Zelt aufrichten sollte: Siehe zu, heißt es, daß du alles nach dem Vorbilde machst, das dir auf dem Berge gezeigt worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Nun hat Er aber ein höheres Priesteramt überkommen, weil Er eines herrlicheren Bundes Vermittler ist, der auf höhere Verhei-ßungen gegründet ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Denn wäre der erste untadelig gehalten worden, so hätte ein zweiter nicht stattgefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Denn strafend spricht Er zu ihnen: Siehe, es kommen Tage, spricht der Herr, da Ich mit dem Hause Israel und dem Hause Judah einen neuen Bund aufrichten werde;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'Nicht nach dem Bunde, den Ich mit ihren Vätern schloß am Tage, da Ich sie bei der Hand nahm, um sie aus Ägyptenland auszuführen; denn sie blieben nicht bei Meinem Bunde, und darum hatte Ich Mich ihrer nicht mehr angenommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Denn das ist der Bund, den Ich mit dem Hause Israel nach selbigen Tagen schließen will, spricht der Herr: Ich will Meine Gesetze in ihren Sinn legen und sie in ihre Herzen schreiben. Ich will ihr Gott sein, und sie sollen Mein Volk sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'Und es wird keiner seinen Nächsten, keiner seinen Bruder lehren und sagen: Lerne den Herrn kennen; denn alle, groß und klein, werden Mich kennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Denn Ich will gnädig sein ihren Übertretungen, und ihrer Sünden nicht mehr gedenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Wenn Er von einem neuen spricht, so hat Er den ersten für veraltet erklärt; was aber veraltet und überjährt ist, das ist seinem Ende nahe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Zwar hatte auch der erste Satzungen des Gottesdienstes und ein äußerliches Heiligtum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Denn es war da das Vorzelt aufgeschlagen, in dem sich der Leuchter und der Tisch und die Schaubrote befanden, und diese heißen das Heilige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Hinter dem zweiten Vorhang war das Zelt, das da heißt das Allerheiligste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'Dies enthielt den goldenen Rauchaltar und die allenthalben mit Gold überzogene Bundeslade, in der ein goldener Krug mit dem Manna und Aharons Stab, der gegrünt hatte, und die Bundestafeln sich befanden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'Oben darüber waren die Cherube der Herrlichkeit, die den Gnadenstuhl überschatteten, wovon jetzt insonderheit nicht zu reden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Da nun solches also eingerichtet ist, so treten die Priester immer in das Vorzelt und verrichten den Dienst allda.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'In das hintere tritt allein der Hohepriester einmal im Jahr, nicht ohne Blut, das er für seine und des Volkes unwissentliche Übertretungen darbringt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'Womit der Heilige Geist bedeutet, daß der Weg zum Heiligtum noch nicht geoffenbart sei, solange das vordere Zelt noch bestände.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'Dieses ist ein Sinnbild auf die gegenwärtige Zeit, in welcher Gaben und Opfer dargebracht werden, die den, der Gott damit dient, im Gewissen noch nicht können vollkommen beruhigen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'Die nur mit Speise und Trank und mancherlei Waschungen und äußerlichen Satzungen bis zur Zeit der Besserung auferlegt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Christus aber ist gekommen als Hoherpriester der zukünftigen Güter und trat durch das größere und vollkommenere Zelt, das nicht mit Händen gemacht, das heißt nicht von dieser Welt ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'Ist auch nicht durch das Blut von Böcken und Kälbern, sondern durch Sein eigen Blut ein- für allemal eingetreten in das Heiligtum und hat ewige Erlösung zuwege gebracht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Denn wenn das Blut der Ochsen und Böcke und die Asche von der Kuh, auf die Verunreinigten gesprengt, zur leiblichen Reinheit heiligt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'Wieviel mehr wird das Blut von Christus, Der Sich unbefleckt durch den ewigen Geist Gott dargebracht hat, unser Gewissen reinigen von toten Werken, dem lebendigen Gott zu dienen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'Und darum ist Er der Vermittler eines neuen Bundes, dadurch, daß ein Tod erfolgte zur Erlösung von den unter dem ersten Bunde begangenen Übertretungen, auf daß die Berufenen das verheißene ewige Erbe empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Denn wo ein Testament ist, da muß der Tod dessen beigebracht werden, der das Testament gemacht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'Denn ein Testament tritt inkraft durch den Tod und hat keine Kraft, wenn der noch lebt, der es gemacht hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Daher auch das erste nicht ohne Blut gestiftet ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Denn nachdem alles Gebot nach dem Gesetz von Moses an das Volk ausgesprochen war, nahm er das Blut der Kälber und Böcke mit Wasser, Purpurwolle und Ysop, und besprengte das Buch und alles Volk mit den Worten:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, 'Das ist das Blut des Bundes, den Gott euch verordnet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'Und das Zelt und alle Geräte des Gottesdienstes besprengte er gleichfalls mit dem Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'Und wird fast alles dem Gesetz zufolge mit Blut gereinigt, und ohne Vergießung von Blut geschieht keine Vergebung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'So mußten nun die Vorbilder der Dinge in den Himmeln mit solchem gereinigt werden, die himmlischen Dinge aber mit besseren Opfern, denn diese sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Denn nicht in dieses mit Händen gemachte Heiligtum, das Vorbild des Wahrhaftigen, sondern in den Himmel selbst ist Christus eingetreten, um vor Gottes Angesicht für uns zu erscheinen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'Noch auch, daß Er Sich mehrmals opfere, wie der Hohepriester einmal des Jahres mit fremdem Blut in das Heiligtum eintritt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, 'Sonst hätte Er seit Anfang der Welt oft Leiden müssen; nun aber ist Er bei Vollendung der Zeitläufe einmal zur Erlassung der Sünde durch Sein Opfer offenbar worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'Und wie den Menschen beschieden ist, einmal zu sterben, danach aber das Gericht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'Also ist Christus einmal geopfert, um die Sünden vieler zu tilgen, und wird zum zweitenmal erscheinen ohne Sünden denen, die auf Ihn warten zu ihrem Heile.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Denn das Gesetz stellt nur den Schatten der zukünftigen Güter, nicht das Bild der Dinge selber dar, und kann durch dieselben jährlichen Opfer, die man fort und fort darbringt, die Herzunahenden nicht vollkommen machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Hätte ihre Darbringung nicht aufgehört, weil sie, einmal gereinigt, kein Bewußtsein der Sünden mehr behalten hätten?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'So aber wurde jährlich durch sie das Gedächtnis der Sünden aufgefrischt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Denn es ist unmöglich, daß das Blut von Ochsen und Böcken Sünden wegnimmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Darum spricht Er, wie Er in die Welt kommt: Opfer und Gabe hast Du nicht gewollt, den Leib aber hast Du Mir zubereitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'An Brandopfern aber und Sündopfern hast Du kein Gefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'Da sprach Ich: Siehe, Ich komme - im Buche steht von Mir geschrieben - Deinen Willen, o Gott, zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Zuvor hatte Er gesagt: Opfer und Gabe, und Brandopfer und Sündopfer hast Du nicht gewollt, noch hast Du Gefallen daran');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'Dann sprach Er: Siehe, Ich komme, o Gott, Deinen Willen zu tun. Er hebt das erste auf, um das andere einzusetzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Durch diesen Willen sind wir geheiligt, durch das einmalige Opfer des Leibes Jesu Christi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'Und jeglicher Priester steht täglich da, verrichtet seinen Dienst und bringt wiederholt dieselben Opfer dar, die doch nimmermehr Sünden wegnehmen können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'Er aber, der ein Opfer für die Sünden dargebracht, sitzt für immer zur Rechten Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'Und wartet hinfort, bis Seine Feinde zum Schemel Seiner Füße gelegt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Denn mit einem Opfer hat Er für immer zur Vollendung geführt, die da geheiligt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Es zeugt für uns aber auch der Heilige Geist; denn, nachdem Er vorhergesagt hatte:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, 'Das ist der Bund, den Ich nach diesen Tagen mit ihnen schließen werde, spricht der Herr: Ich gebe Meine Gesetze in ihre Herzen, und will sie in ihre Gedanken schreiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'Und ihrer Sünden und Übertretungen will Ich nicht mehr gedenken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Wo aber derselben Vergebung ist, da ist kein Opfer für die Sünde mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Weil wir denn, Brüder, die Freiheit des Eintritts in das Heiligtum durch Jesu Blut haben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'Den Er für uns eingeweiht hat, als einen neuen, zum Leben führenden Weg, durch den Vorhang, das heißt durch Sein Fleisch hindurch,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'Und haben einen Hohenpriester über das Haus Gottes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'So lasset uns hinzutreten mit wahrhaftigem Herzen und völligem Glauben, da wir am Herzen besprengt');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'Und lasset uns, ohne zu wanken, festhalten an dem Bekenntnis; denn treu ist Er, Der die Verheißungen gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'Und lasset uns aufeinander achten, und einander zur Liebe und zu guten Werken anspornen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'Und nicht unsere eigene Versammlung verlassen, wie etliche tun, und das um so mehr, als wir sehen, wie der Tag immer näher rückt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Denn so wir vorsätzlich sündigen, nachdem wir zur Erkenntnis der Wahrheit gekommen sind, ist kein anderes Opfer mehr für Sünden zu erwarten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'Wohl aber droht ein schreckliches Gericht und ein eiferndes Feuer, das die Widerwärtigen verzehren wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Wer Moses Gesetz übertreten, muß ohne Erbarmen auf die Aussage zweier oder dreier Zeugen des Todes sterben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'Wieviel ärgere Strafe meint ihr, wird der zu erleiden haben, der den Sohn Gottes mit Füßen tritt, und das Blut des neuen Bundes, wodurch er geheiligt worden, entheiligt, und den Geist der Gnade lästert?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Wir kennen ja Den, Welcher spricht: Mein ist die Rache, Ich will vergelten, spricht der Herr - und abermals: Der Herr wird richten Sein Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Schrecklich ist es, in die Hände des lebendigen Gottes zu fallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Gedenkt aber an die vorigen Tage, in denen ihr nach der Erleuchtung einen großen Leidenskampf bestanden habt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'Indem ihr teils in Zuständen der Schmach und der Drangsale zur Schau gestellt wurdet, teils an anderen, die solches erlitten, Anteil nahmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Denn ihr hattet Anteil genommen an den Gefangenen, und den Raub eurer Güter frohen Mutes ertragen, als die da wußten, daß sie in sich selbst ein besseres, bleibendes Gut in den Himmeln haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'So werfet nun euer Vertrauen nicht weg, das eine große Belohnung hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Denn Geduld ist euch Not, auf daß ihr den Willen Gottes tut und die Verheißung empfanget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Denn noch über eine kleine Weile, so wird Der, Der da kommen soll, kommen und nicht verziehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Mein Gerechter aber wird aus dem Glauben leben, und: Wenn er davon zurückweicht, so hat meine Seele kein Gefallen an ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Wir aber sind nicht von denen, die da zurückweichen in die Verdammnis, sondern von denen, die durch den Glauben das Leben gewinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Es ist aber der Glaube eine Zuversicht dessen, das man hofft, eine Überzeugung von Dingen, die man nicht sieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Durch ihn haben die Alten Zeugnis erhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Durch den Glauben erkennen wir, daß die Welten durch Gottes Wort bereitet worden sind, so daß das, was gesehen wird, nicht geworden ist aus Dingen, die da erscheinen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Durch den Glauben hat Abel Gott ein größeres Opfer dargebracht denn Kain, durch den bezeugt wurde, daß er gerecht war, da Gott über seine Opfergaben zeugte, und durch ihn redet Er noch jetzt nach seinem Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Durch den Glauben ward Enoch entrückt, auf daß er den Tod nicht sähe, und ward nicht erfunden, darum, daß ihn Gott entrückt hatte; denn vor seiner Entrückung ist bezeugt, daß er Gott wohlgefällig war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Ohne Glauben aber ist es unmöglich, Gott zu gefallen, denn wer zu Gott kommen will, der muß glauben, daß Er ist, und denen, die Ihn suchen, ein Vergelter wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Durch den Glauben hat Noach, über das noch Unsichtbare belehrt, sich vorgesehen, und die Arche zur Rettung seines Hauses zubereitet, und durch ihn verdammte er die Welt, und er ward nach seinem Glauben der Gerechtigkeit teilhaftig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Durch den Glauben gehorchte Abraham, da er berufen ward auszuziehen in das Land, das er als Erbe überkommen sollte, und er zog aus und wußte nicht, wohin er käme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Durch den Glauben lebte er als Fremdling in dem Lande der Verheißung, und wohnte mit Isaak und Jakob, den Miterben derselben Verheißung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'Denn er wartete auf jene festgegründete Stadt, deren Baumeister und Schöpfer Gott ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Durch den Glauben erhielt selbst Sarah Kraft zur Empfängnis, und über ihr Alter hinaus gebar sie, weil sie Ihn, Der es verhei-ßen, für wahrhaftig hielt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Darum sind auch von einem, der schon abgelebt, so viele entsprossen wie die Sterne am Himmel und wie der Sand am Rande des Meeres, der nicht zu zählen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'Diese alle sind gestorben im Glauben, ehe sie die Verheißungen empfangen; sie schauten sie aber von ferne, und begnügten sich dabei und bekannten, daß sie Fremdlinge und Beisaßen im Lande wären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Denn die solches sprachen, gaben zu verstehen, daß sie ein Vaterland suchen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'Und hätten sie das gemeint, von dem sie ausgezogen waren, so hätten sie ja Zeit gehabt, wieder umzukehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'So aber sehnen sie sich nach einem besseren, das ist dem himmlischen. Darum schämt Sich auch Gott ihrer nicht, Sich ihren Gott nennen zu lassen; denn Er hat ihnen eine Stadt bereitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Durch Glauben hat Abraham, da er versucht ward, den Isaak dargebracht, und wollte den Eingeborenen hingeben, er, der schon die Verheißungen empfangen hatte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'Von dem gesagt war: Nach Isaak soll dir der Same genannt werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'Indem er dachte, daß Gott auch von den Toten erwecken könnte, weshalb er ihn, eben weil er ihn hingegeben hatte, wieder erhielt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Durch den Glauben erteilte Isaak im Hinblick auf die Zukunft seinen Segen an Jakob und Esau.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Durch den Glauben segnete Jakob auf dem Totenbett die beiden Söhne Josephs und betete sodann, auf die Spitze seines Stabes gelehnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Durch den Glauben gedachte Joseph, da er starb des Auszugs der Söhne Israels, und gab Befehl über seine Gebeine.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Durch den Glauben ward Moses, da er geboren ward, von seinen Eltern drei Monate lang verborgen gehalten, als sie sahen, daß er ein so anmutiges Kindlein war; und sie fürchteten sich nicht vor dem Befehle des Königs.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Durch den Glauben weigerte sich Moses, ein Sohn der Tochter Pharaos zu heißen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'Und wollte lieber mit dem Volk Gottes Ungemach erdulden, als den zeitlichen Genuß der Sünde haben;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'Und achtete höher denn die Schätze Ägyptens Christi Schmach, denn er sah an die Belohnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Durch den Glauben verließ er Ägypten, und fürchtete nicht den Zorn des Königs; denn er hielt fest an dem Unsichtbaren, als sähe er Ihn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Im Glauben hat er das Paschah und die Besprengung des Blutes angeordnet, auf daß nicht der Würger der Erstgeburten sie antastete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Im Glauben gingen sie durch das Rote Meer, wie über trockenes Land, und die Ägypter versuchten es auch und wurden verschlungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Durch den Glauben fielen die Mauern Jerichos, nachdem man sieben Tage um selbige gezogen war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Durch den Glauben kam die Hure Rahab nicht um mit den Ungläubigen, weil sie die Kundschafter friedlich aufgenommen hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'Und was soll ich weiter sagen? Die Zeit würde mir zu kurz, wenn ich von Gideon und Barak und Simson und Jephtha und David und Samuel und den Propheten erzählen sollte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'Welche durch den Glauben Königreiche bezwangen, Gerechtigkeit übten, Verheißungen erlangten, Löwen den Rachen verstopften,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'Des Feuers Gewalt auslöschten, der Schärfe des Schwertes entrannen, in Zuständen der Schwäche gekräftigt, zum Streite gestärkt wurden, die Heere der Feinde niederschlugen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'Weiber haben durch Auferstehung ihre Toten wieder erhalten, andere wurden auf die Folter gespannt, indem sie keine Freilassung annahmen, auf daß sie die bessere Auferstehung empfingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'Andere erduldeten Verhöhnungen und Geißelung, dazu Bande und Gefängnis;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'Sie wurden gesteinigt, zersägt, zerstochen, fielen durch das Schwert, gingen in Schafpelzen, in Ziegenfellen umher, hatten mit Mangel, Trübsal und Ungemach zu kämpfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, 'Sie, deren die Welt nicht wert war, sind in Wüsten, auf Bergen, in Höhlen und Klüften der Erde umhergeirrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'Und diese alle haben sich durch Glauben bewährt und trugen die Verheißung nicht davon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'Darum, daß für uns Gott Besseres zuvor vorgesehen hat, auf daß sie nicht ohne uns zur Vollendung gelangten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Darum lasset uns, weil wir eine solche Menge Zeugen vor uns haben, ablegen jegliche Bürde und Sünde, die uns so leicht gefangen hält, und mit Beharrlichkeit den uns verordneten Wettlauf beginnen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'Und aufsehen zu Ihm, Dem Anfänger und Vollender des Glaubens, zu Jesus, Der für die Ihm vorgehaltene Freude das Kreuz erduldete, Der Schmach nicht achtete, und jetzt zur Rechten des Thrones Gottes sitzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Gedenkt an Ihn, Der solchen Widerspruch von den Sündern wider Sich erduldet hat, auf daß ihr den Mut nicht sinken lasset und verzagt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Denn ihr habt im Kampfe wider die Sünde noch nicht bis auf das Blut widerstanden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'Und ihr habt bereits die Ermahnung vergessen, die zu euch als Kindern spricht: Mein Sohn, achte nicht gering die Züchtigung des Herrn, und verzage nicht, wenn du von Ihm gestraft wirst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Denn welchen der Herr lieb hat, den züchtigt Er, und gibt Streiche jeglichem Sohn, den Er aufnimmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'So ihr nun in der Züchtigung ausharrt, so verfährt Gott mit euch als mit Söhnen; denn wo ist ein Sohn, den der Vater nicht züchtigt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'So ihr aber ohne Züchtigung bleibt, deren alle teilhaftig werden, so seid ihr Bastarde und keine Söhne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Wir hatten nun unsere leiblichen Väter zu Züchtigern und scheuten uns vor ihnen; wollten wir da nicht viel mehr dem Vater der Geister untertan sein, auf daß wir das Leben haben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Jene züchtigen uns nach Gutdünken eine kurze Zeit, Er aber zu unserem Besten, auf daß wir Teil hätten an Seiner Heiligung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Alle Züchtigung aber, wenn sie da ist, scheint uns nicht erfreulich, sondern trübselig; danach aber gewährt sie denen, die sich einüben ließen, die Friedensfrucht der Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Darum richtet wieder auf die lässigen Hände und die erschlafften Knie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'Und macht gerade Bahn euren Füßen, auf daß nicht, was lahm ist, ausgereckt werde, sondern zurechtkomme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Strebt nach Frieden mit allen, und nach der Heiligung, ohne die niemand den Herrn schauen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'Und seht darauf, daß nicht einer hinter der Gnade Gottes zurückbleibe, auf daß keine Wurzel der Bitterkeit aufsprosse und Unfrieden anrichte und viele von ihr angesteckt werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'Daß keiner sei ein Hurer, oder ein Unheiliger wie Esau, der für eine Speise seine Erstgeburt hingab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Ihr wißt ja, daß er auch hernach, als er den Segen zu erlangen wünschte, verworfen ward; denn er fand keinen Raum zur Buße, wiewohl er mit Tränen nach ihr verlangte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Denn ihr seid nicht hinzugetreten zu einem Berge, den man antasten kann und der mit Feuer brennt, noch zu dem Dunkel und der Finsternis und dem Ungewitter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'Noch zu dem Hall der Posaune und zur Stimme der Worte, deren Hörer sich verbaten, daß weiter zu ihnen geredet werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, 'Denn sie vermochten nicht zu ertragen, was da verordnet wurde. Und wenn ein Tier den Berg anrührte, sollte es gesteinigt oder mit eine Geschoß getötet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'Und so furchtbar war die Erscheinung, daß Moses sprach: Ich bin voll Furcht und Zitterns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'Sondern ihr seid hinzugetreten zum Zionsberge, zur Stadt des lebendigen Gottes, zum himmlischen Jerusalem und zu den Myriaden von Engeln,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'Und zur Versammlung und Gemeinde der Erstgeborenen, die in dem Himmel angeschrieben sind, und zu Gott, dem Richter aller, und zu den Geistern vollendeter Gerechter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'Und zu Jesus, dem Vermittler eines neuen Bundes, Der durch das Blut der Besprengung besser redet, denn Abels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Sehet zu, daß ihr euch nicht weigert, Den zu hören, Der jetzt zu euch redet; denn wenn jene nicht entrannen, die den auf Erden Redenden nicht hören wollten, so werdet ihr noch viel weniger entrinnen, wenn ihr euch von Dem abwendet, Der vom Himmel aus zu euch spricht,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Dessen Stimme damals die Erde bewegte, jetzt aber hat Er verheißen: Noch einmal bewege Ich nicht allein die Erde, sondern auch den Himmel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'Dies noch einmal aber bedeutet die Veränderung dessen, was erschüttert wird, als etwas, das vor sich geht, auf daß Bestand habe das, was nicht bewegt wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Darum lasset uns, weil wir ein unerschütterliches Reich empfangen, damit unseren Dank beweisen, daß wir mit Zucht und Ehrfurcht Gott wohlgefällig dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'Denn unser Gott ist ein verzehrend Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Beharret in brüderlicher Liebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Haltet auf Gastfreundschaft; durch sie haben ohne ihr Wissen manche schon Engel beherbergt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Nehmt euch der Gefangenen an, als wäret ihr mitgefangen, der Leidenden als solche, die selbst noch im Leibe wallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Die Ehe soll durchaus in Ehren gehalten werden und das Ehebett unbefleckt; Hurer und Ehebrecher wird Gott richten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Euer Wandel sei ohne Geiz; lasset euch begnügen an dem, was da ist, denn Er Selbst hat gesagt: Ich will dich nicht verlassen, noch versäumen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Darum dürfen wir getrost sagen: Der Herr ist mein Helfer, und ich will mich nicht fürchten. Was sollte mir ein Mensch tun?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Gedenket an eure Vorsteher, die euch das Wort Gottes verkündigt haben. Schaut auf den Ausgang ihres Wandels und eifert ihrem Glauben nach!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jesus Christus gestern und heute und derselbe auch in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Lasset euch nicht durch die vielerlei fremdartigen Lehren irre machen; denn es ist ein köstlich Ding, das Herz durch die Gnade zu stärken, nicht durch Speisen, von denen keinen Nutzen hatten, die damit umgingen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Wir haben einen Altar, von dem nicht essen dürfen, die dem Zelt dienen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Denn welcher Tiere Blut als Sündopfer vom Hohenpriester in das Heiligtum hineingetragen wird, derselbigen Leiber werden außerhalb des Lagers verbrannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'Darum hat auch Jesus, auf daß Er das Volk durch Sein eigen Blut heiligte, außerhalb des Tores gelitten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'So lasset uns denn zu Ihm hinaus vor das Lager gehen, und Seine Schmach tragen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Denn wir haben hier keine bleibende Stadt, sondern die zukünftige suchen wir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'So lasset uns nun durch Ihn Gott darbringen Lobopfer allezeit, das heißt: die Frucht der Lippen, die Seinen Namen bekennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Lasset nicht ab, wohlzutun und mitzuteilen; denn an solchen Opfern hat Gott Wohlgefallen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Folget euren Vorstehern und gebt ihnen nach; denn sie wachen über eure Seelen, als die da Rechenschaft geben sollen, auf daß sie es mit Freuden tun und nicht mit Seufzen; denn das frommt euch nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Betet für uns; denn wir sind guter Zuversicht, daß wir ein gut Gewissen haben, und fleißigen uns in allen Stücken, einen guten Wandel zu führen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Ich bitte euch aber um so mehr, solches zu tun, auf daß ich desto eher wieder zu euch komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Der Gott des Friedens aber, Der von den Toten heraufgeführt hat den großen Hirten der Schafe durch das Blut des ewigen Bundes, unseren Herrn Jesus,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'Der mache euch fertig in jeglichem guten Werk, zu tun Seinen Willen, und schaffe in euch, was vor Ihm wohlgefällig ist, durch Jesus Christus, Welchem sei Ehre in alle Ewigkeit! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Ich ermahne euch aber, Brüder, lasset das Wort der Ermahnung an euch kommen; denn ich habe euch nur kurz geschrieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Wisset, daß Bruder Timotheus freigegeben ist; mit ihm werde ich, wenn er bald kommt, euch sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Grüßet alle eure Vorsteher und alle Heiligen, es grüßen euch die aus Italien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Die Gnade sei mit euch allen! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakobus, ein Knecht Gottes und des Herrn Jesu Christi, entbietet den zwölf Stämmen in der Zerstreuung seinen Gruß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Achtet es, meine Brüder, für eitel Freude, wenn ihr in mancherlei Anfechtungen fallet,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'Und wisset, daß die Prüfung eures Glaubens Standhaftigkeit bewirkt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Standhaftigkeit aber soll ihr Werk vollkommen machen, auf daß ihr seid vollkommen und vollendet, und es an nichts fehlen lasset.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'So aber einem unter euch an Weisheit gebricht, so bitte er Gott darum, Der da einfältig jedem gibt und keinem es aufrückt, so wird sie ihm gegeben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Er bitte aber im Glauben und zweifle nicht; denn der, so da zweifelt, gleicht der Meereswoge, die, vom Winde ergriffen, hinund hergeworfen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Ein solcher Mensch wähne ja nicht, daß er etwas vom Herrn empfangen werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'Ein wankelmütiger Mensch ist unbeständig auf allen seinen Wegen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Der niedrige Bruder aber rühme sich seiner Hoheit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'Und der Reiche rühme sich seiner Niedrigkeit; denn wie die Blume des Grases wird er vergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Die Sonne geht auf mit ihrer Glut und dörrt das Gras, und seine Blume fällt ab, und mit ihrer Pracht ist es zu Ende; also vergeht auch der Reiche mitten in seinem Treiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Glücklich ist der Mann, der in der Versuchung aushält; denn wenn er sich bewährt, empfängt er den Siegeskranz des Lebens, den der Herr denen, die Ihn lieben, verheißen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Niemand sage, wenn er versucht wird, daß er von Gott versucht werde; denn Gott wird nicht versucht vom Bösen, und versucht auch Selber niemand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Sondern ein jeglicher wird versucht, wenn er von seiner eigenen Lust fortgerissen und verlockt wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'Danach, wenn die Lust empfangen hat, gebiert sie die Sünde, die Sünde aber, wenn sie vollendet ist, gebiert den Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Irrt euch nicht, geliebte Brüder!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Alle gute Gabe und alle vollkommene Gabe kommt von oben herab vom Vater der Lichter, bei Dem ist keine Wandlung, noch wechselnde Beschattung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Aus freiem Ratschluß hat Er uns durch das Wort der Wahrheit geboren, auf daß wir wären Erstlinge Seiner Geschöpfe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Darum, geliebte Brüder, sei jeder Mensch schnell zum Hören, langsam aber zum Reden, langsam zum Zorn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'Denn des Menschen Zorn tut nicht, was vor Gott recht ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Darum legt ab alle Unsauberkeit und allen Auswuchs der Bosheit, und nehmt in Sanftmut auf die euch eingepflanzte Lehre, die eure Seelen retten kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Seid aber Täter des Wortes und nicht Hörer allein, womit ihr euch selbst betrügt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Denn so jemand das Wort hört und nicht tut, gleicht er einem Manne, der sein leiblich Angesicht im Spiegel beschaut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'Denn nachdem er sich beschaut hat, geht er davon, und vergißt alsbald, wie er aussah.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Wer aber in das vollkommene Gesetz der Freiheit hineingeschaut und dabei beharrt hat, und kein vergeßlicher Hörer, sondern ein wirklicher Täter geworden ist, der wird selig durch sein Tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'So aber einer sich dünkt gottesfürchtig zu sein und hält seine Zunge nicht im Zaum, sondern täuscht sich über sein Herz, dessen Gottesfurcht ist eitel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Eine reine und unbefleckte Gottesfurcht ist vor Gott dem Vater die, daß man die Waisen und Witwen in ihrer Trübsal heimsucht, und sich unbefleckt von der Welt erhält.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Meine Brüder, haltet nicht dafür, daß der Glaube an Jesus Christus, unseren Herrn der Herrlichkeit, Ansehen der Person leide.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Denn so in eure Versammlung ein Mann käme mit goldenem Ring und in prächtigem Kleide, es käme aber auch ein Armer in schlechtem Kleide;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'Und ihr sähet auf den, der das prächtige Kleid trägt, und sagtet zu ihm: Mache es dir hier bequem; und sagtet zu dem Armen: Stehe dort hin oder setze dich hier vor meinen Fußschemel;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'Machtet ihr da keinen Unterschied bei euch, und würdet Richter argen Sinnes?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Hört, meine geliebten Brüder! Hat Gott nicht die Armen dieser Welt auserwählt, als reich an Glauben und Erben des Reiches, das Er denen, so Ihn lieben, verheißen hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Ihr aber hättet dem Armen Unehre angetan. Sind es nicht die Reichen, die euch drükken mit ihrer Gewalt und euch vor die Gerichte ziehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Lästern sie nicht den guten Namen, wonach ihr genannt seid?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'So ihr vollbringt das königliche Gesetz nach der Schrift: Liebe deinen Nächsten wie dich selbst, so tut ihr wohl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'So ihr aber die Person anseht, begeht ihr eine Sünde und werdet vor dem Gesetz als Übertreter gestraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Denn so einer das ganze Gesetz hält, und verstößt an einem, verschuldet er sich an allen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'Denn Der da gesagt hat: Du sollst nicht ehebrechen, hat auch gesagt: Du sollst nicht töten. So du nun nicht ehebrichst, tötest aber, bist du ein Übertreter des Gesetzes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Also redet und also tut, als die da sollen nach dem Gesetz der Freiheit gerichtet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Denn ein unbarmherzig Gericht ergeht über den, der nicht Barmherzigkeit geübt hat, und Barmherzigkeit rühmt sich wider das Gericht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Denn was hilft es einem, meine Brüder, so er sagt, er habe Glauben, und hat doch keine Werke; kann der Glaube ihn selig machen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'So aber ein Bruder oder eine Schwester nackt und bloß wäre und an der täglichen Nahrung Mangel litte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'Und einer unter euch zu ihnen spräche: Geht hin im Frieden, wärmt euch und sättigt euch, ihr gäbet ihm aber nicht, was des Leibes Notdurft wäre, was hülfe das?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'So ist auch der Glaube, wenn er nicht Werke hat, an und für sich tot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Aber es sagt vielleicht einer: Du hast den Glauben, und ich habe die Werke - zeige mir deinen Glauben an deinen Werken, so will auch ich dir an meinen Werken meinen Glauben zeigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Du glaubst, daß nur ein Gott ist. Du tust wohl daran; die Teufel glauben es auch und zittern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Willst du aber wissen, du eitler Mensch, daß der Glaube ohne Werke tot ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Ist nicht Abraham, unser Vater, durch Werke gerecht geworden, weil er seinen Sohn Isaak auf den Opferaltar dargebracht hat?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Da siehst du, daß der Glaube mit seinen Werken mitwirkte und durch die Werke der Glaube vollkommen ward.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'Und so ist die Schrift erfüllt worden, die da sagt: Abraham hat Gott geglaubt, und es ward ihm zur Gerechtigkeit gerechnet, und er ward ein Freund Gottes genannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'So seht ihr nun, daß der Mensch durch Werke gerecht wird, und nicht durch den Glauben allein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Gleicherweise die Hure Rahab, ist sie nicht durch die Werke gerecht geworden, weil sie die Boten aufnahm und auf einem anderen Wege wieder entkommen ließ?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Denn gleichwie der Leib ohne den Geist tot ist, also ist auch der Glaube tot ohne die Werke.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Es sollten nicht so viele Lehrer sein wollen; ihr wißt ja, daß die Verantwortung um so größer für euch ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'Denn wir fehlen alle mannigfaltig. Wer aber auch in keinem Worte fehlt, der ist ein vollkommener Mann und ist imstande, auch den ganzen Leib im Zaum zu halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Siehe, den Pferden legen wir den Zaum ins Maul, daß sie uns gehorchen, und wir lenken ihren ganzen Leib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Siehe, die Schiffe, obwohl sie so groß sind und von heftigen Winden umhergetrieben werden, werden doch von dem so kleinen Ruder gelenkt, wohin der Steuermann will.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'So ist auch die Zunge ein kleines Glied und richtet Großes an. Siehe, welch einen Wald ein kleines Feuer anzündet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Auch die Zunge ist ein Feuer, eine Welt der Ungerechtigkeit; sie stellt sich so zu unseren Gliedern, daß sie den ganzen Leib befleckt und von der Geburt an das Lebensrad entzündet und selbst von der Hölle entzündet wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Denn jegliches Geschlecht der Tiere, der Vögel, der Kriechtiere und der Seetiere wird gezähmt und ist gezähmt von dem menschlichen Geschlecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'Die Zunge aber vermag kein Mensch zu zähmen, dies unwiderstehliche Übel voll tödlichen Giftes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Mit ihr loben wir Gott, den Vater, und mit ihr fluchen wir den Menschen, die nach dem Bilde Gottes geschaffen sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'Aus einem Munde geht hervor Segen und Fluch. So sollte es nicht sein, meine Brüder.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Quillt wohl die Quelle aus derselben Öffnung Süßes und Bitteres hervor?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'Kann wohl, liebe Brüder, ein Feigenbaum Oliven, oder ein Weinstock Feigen tragen? So kann auch eine Quelle nicht salziges und süßes Wasser geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Wer ist weise und verständig unter euch? der zeige mit seinem guten Lebenswandel seine Werke in der Sanftmut der Weisheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Habt ihr aber bitteren Eifer und Streitsucht in eurem Herzen, so lasset das Rühmen und lügt nicht wider die Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'Das ist keine Weisheit, die von oben kommt, sondern eine irdische, natürliche, teuflische.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Denn wo Neid und Streitsucht ist, da ist Unordnung und eitel böses Ding.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Die Weisheit aber, die von oben kommt, ist vor allem rein, sodann friedfertig, sanft, nachgiebig, lenksam, voll Erbarmens und guter Früchte, macht keinen Unterschied und ist ungeheuchelt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Die Frucht der Gerechtigkeit aber wird gesät in Frieden von denen, die Frieden halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Woher kommen Streitereien und Kämpfe unter euch? Woher anders als aus euren Lüsten, die da streiten in euren Gliedern wider einander?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Ihr begehrt und könnt es nicht gewinnen, ihr neidet und eifert und könnt es nicht erlangen, ihr kämpft und streitet und habt es nicht, darum, daß ihr nicht bittet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Ihr bittet und empfangt nicht, weil ihr für euch übel bittet, auf daß ihr es in euren Lüsten vergeuden könnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Ihr Ehebrecher und Ehebrecherinnen, wißt ihr nicht, daß der Welt Freundschaft Gottes Feinschaft ist; wer nun der Welt Freund sein will, der wird Gottes Feind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Oder meint ihr, daß die Schrift umsonst spreche! Eifernd begehrt sie des Geistes, den Er in uns wohnen ließ.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Er gibt aber größere Gnade; darum heißt es: Gott widersteht den Hoffärtigen, aber den Demütigen gibt Er Gnade.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'So seid denn Gott untertänig. Widersteht dem Teufel, so flieht er von euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Naht euch Gott, so naht Er Sich euch; reinigt die Hände, ihr Sünder, und haltet eure Herzen rein, ihr Wankelmütigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Fühlt euer Elend, trauert und weint. Euer Lachen wandle sich in Klage und eure Freude in Betrübnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Demütigt euch vor dem Herrn, so wird Er euch erhöhen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Redet einander nicht Übles nach, Brüder. Wer seinem Bruder Übles nachredet und seinen Bruder richtet, der redet wider das Gesetz und richtet das Gesetz. Wenn du aber das Gesetz richtest, so bist du kein Täter des Gesetzes, sondern Richter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Es ist nur ein Gesetzgeber, Der lossprechen und verdammen kann. Wer bist du aber, der du den anderen richtest?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Wohlan nun ihr, die ihr sagt: Heute oder morgen wollen wir in die oder die Stadt gehen, wollen daselbst ein Jahr hantieren und gewinnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'Und ihr wißt doch nicht, wie es morgen steht; denn was ist euer Leben? Ein Dunst ist es, der eine kleine Weile erscheint und dann vergeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Ihr solltet vielmehr sagen: So der Herr will und wir am Leben bleiben, wollen wir dies oder das tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Nun aber rühmt ihr euch in eurem Übermut. All solches Rühmen aber ist vom Übel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Wer da weiß Gutes zu tun und tut es nicht, dem ist es Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Wohlan denn ihr Reichen, weint und heult über euer Elend, das über euch kommen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Euer Reichtum verschwindet, eure Gewänder werden von Motten zerfressen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Euer Gold und Silber ist verrostet, und ihr Rost wird euch zum Zeugnis sein und wird euer Fleisch fressen wie ein Feuer. Ihr habt in den letzten Tagen Schätze gehäuft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Siehe, der Lohn der Arbeiter, die für euch eure Lande abgemäht, und den ihr verkürzt habt, schreit, und das Schreien der Schnitter ist vor die Ohren des Herrn Zebaoth gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'Ihr ließet euch wohlsein auf Erden und habt geschwelgt, habt euch weidlich gemästet wie am Tag des Schlachtopfers.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Ihr habt den Gerechten verurteilt, gemordet; er widersteht euch nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'So haltet denn geduldig aus, liebe Brüder, bis zur Zukunft des Herrn. Siehe, der A-ckersmann wartet auf die köstliche Frucht des Feldes und geduldet sich, bis er Frühregen und Spätregen empfängt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'So geduldet denn auch ihr euch, und festigt eure Herzen; denn die Zukunft des Herrn ist nahe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Klagt nicht über einander, Brüder, auf daß ihr nicht verdammt werdet; siehe, der Richter steht vor der Tür.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Nehmt euch zum Muster im Leiden und in der Geduld die Propheten, die im Namen des Herrn zu euch geredet haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Siehe, wir preisen selig die, so ausharren; von der Standhaftigkeit Hiobs habt ihr gehört, und das Ende des Herrn habt ihr gesehen; denn der Herr ist von großer Gnade und Barmherzigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Vor allen Dingen aber, meine Brüder, schwört nicht, weder bei dem Himmel, noch bei der Erde, noch einen anderen Schwur. Bei euch aber sei ja: ja, nein: nein, auf daß ihr nicht dem Gericht verfallet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Leidet jemand unter euch, der bete, ist er wohlgemut, so singe er Psalmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Ist jemand krank unter euch, so rufe er zu sich die Ältesten der Gemeinde, und die sollen beten über ihn und ihn salben mit Öl im Namen des Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'Und das Gebet des Glaubens wird dem Kranken helfen und der Herr wird ihn aufrichten, und so er Sünden begangen hat, wird ihm vergeben werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Bekennt einander eure Übertretungen und betet füreinander, daß euch Heil widerfahre; das Gebet des Gerechten vermag viel, wenn es ernstlich ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elias war ein Mensch gleich wie wir, und betete ein Gebet, daß es nicht regnen sollte, und es regnete nicht im Lande drei Jahre und sechs Monate.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'Und er betete abermals, und der Himmel gab Regen und die Erde brachte ihre Frucht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Brüder, so einer unter euch von der Wahrheit abirrete, und es brächte ihn jemand zurück,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'Der wisse, daß, wer einen Sünder von seinem Irrweg zurückbringt, eine Seele vom Tod errettet und damit eine Menge Sünden bedeckt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Petrus, ein Apostel Jesu Christi, an die auserwählten Fremdlinge in der Zerstreuung in Pontus, Galatien, Kappadocien, Asien und Bithyninen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'Nach dem Ratschlusse Gottes des Vaters durch die Heiligung des Geistes zum Gehorsam und zur Besprengung mit dem Blute Jesu Christi. Gnade und Friede werde euch in Fülle zuteil!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Gelobt sei Gott und der Vater unseres Herrn Jesus Christus, Der uns nach Seiner großen Barmherzigkeit durch die Auferstehung Jesu Christi von den Toten wiedergeboren hat zu einer lebendigen Hoffnung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'Auf ein unvergängliches, unbeflecktes und unverwelkliches Erbteil, das im Himmel aufbehalten ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'Für euch, die ihr durch die Kraft Gottes mittelst des Glaubens bewahrt werdet für die Seligkeit, die bereit steht, daß sie in der letzten Zeit geoffenbart werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'Worüber ihr frohlockt, wenn ihr auch jetzt eine kleine Zeit');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'Auf daß euer Glaube bewährt und viel köstlicher erfunden werde, als das vergängliche, durch Feuer bewährte Gold, zu Lob, Preis und Herrlichkeit bei der Offenbarung Jesu Christi.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'Den ihr liebet, ohne Ihn gesehen zu haben, an Den ihr, ohne Ihn jetzt zu sehen, glaubt, und frohlocket mit unaussprechlicher und herrlicher Freude,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'Indem ihr als Ziel eures Glaubens der Seelen Seligkeit davontraget;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'Nach welcher Seligkeit die Propheten, die von der euch bestimmten Gnade weissagten, eifrig gesucht und geforscht haben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'Indem sie nachforschten, auf welche oder welcherlei Zeit Christi Geist deutete, der in ihnen war, und die Christus bevorstehenden Leiden und die darauf folgenden Herrlichkeiten voraus bezeugte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Denen geoffenbart worden, daß nicht ihnen selbst, sondern euch zugut kommen sollte, was euch nun durch die, so euch durch den vom Himmel gesandten Heiligen Geist das Evangelium predigten, verkündigt worden ist, in das hineinzuschauen Engel selbst verlangt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Darum umgürtet die Lenden eures Gemütes, seid nüchtern, und setzt eure volle Hoffnung auf die Gnade, die euch durch die Erscheinung von Jesus Christus dargebracht wird;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'Als Kinder des Gehorsams, indem ihr euch nicht mehr richtet nach den Lüsten in eurer früheren Unwissenheit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'Sondern nach dem Heiligen, Der euch berufen hat, auf daß auch ihr in all eurem Wandel heilig werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'Weil geschrieben steht: Ihr sollt heilig sein, denn Ich bin heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'Und wenn ihr Den als Vater anruft, Der ohne Ansehen der Person richtet, nach eines jeglichen Werk, so wandelt in Furcht die Zeit eurer Pilgerschaft,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'Indem ihr ja wißt, daß ihr nicht mit vergänglichem Silber oder Gold von eurem eitlen, von den Vätern angeborenen Wandel erlöst seid,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'Sondern mit dem teuren Blut Christi als eines fehllosen und unbefleckten Lammes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'Der vor Gründung der Welt dazu vorausbestimmt war, und in diesen letzten Zeiten um euretwillen Sich geoffenbart hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'Die ihr durch Ihn glaubt an Gott, Der Ihn von den Toten auferweckt und Ihm Herrlichkeit verliehen hat, so daß ihr Glauben und Hoffnung auf Gott haben möchtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Und heiligt eure Seelen im Gehorsam gegen die Wahrheit durch den Geist zu ungeheuchelter Bruderliebe und habt aus reinem Herzen einander inbrünstig lieb,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'Als die da wiedergeboren sind nicht aus vergänglichem, sondern aus unvergänglichem Samen, durch das lebendige Wort Gottes, das da ewiglich bleibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Denn alles Fleisch ist wie Gras, und all seine Herrlichkeit wie die Blume des Grases: Das Gras verdorrt und seine Blume fällt ab.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'Aber des Herrn Wort bleibt in Ewigkeit. Das ist aber das Wort, das euch verkündigt worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'So legt nun ab alle Bosheit, allen Trug, alle Heuchelei und Mißgunst, Lästerung;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'Als neugeborene Kindlein verlangt nach vernünftiger, lauterer Milch, auf daß ihr durch dieselbe zur Seligkeit gedeiht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'So ihr anders schon geschmeckt habt, wie gütig der Herr ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'Zu Dem ihr hinzutretet, als zu einem lebendigen Steine, der von den Menschen verworfen, aber bei Gott auserwählt und in Ehren ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'Und auch ihr seid wie lebendige Steine, aufgebaut zu einem geistigen Haus, einem heiligen Priestertum, um geistige Opfer darzubringen, die durch Jesus Christus Gott wohlgefällig sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Darum steht in der Schrift: Siehe, Ich lege auf Zion einen auserwählten, köstlichen Eckstein, und wer an ihn glaubt, wird nicht zuschanden werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Euch nun, die ihr glaubt, ist er köstlich, denen aber, die nicht glauben, ist er der Stein, den die Bauleute verworfen haben und der zum Eckstein geworden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'Ein Stein des Anstoßes und ein Fels zum Ärgernis für die, welche sich am Wort stoßen und nicht an dasselbe glauben, wozu sie auch bestimmt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Ihr aber seid ein auserwählt Geschlecht, ein königlich Priestertum, ein heilig Volk, das Volk des Eigentums, daß ihr verkündigen sollt die Tugenden Dessen, Der euch aus der Finsternis in Sein wunderbares Licht berufen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'Die ihr vordem kein Volk ward, nun aber ein Volk Gottes, vordem nicht begnadigt, nun aber begnadigt seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Geliebte, ich ermahne euch als Fremdlinge und Pilger, euch fleischlicher Lüste zu enthalten, die wider die Seele streiten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'Führt einen guten Lebenswandel unter den Heiden, auf daß, wo sie euch Übles nachreden als Übeltätern, sie eure guten Werke sehen und Gott preisen am Tage der Heimsuchung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'So seid nun untertan aller menschlichen Ordnung um des Herrn willen, sowohl dem König, der die oberste Gewalt hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'Als auch den Statthaltern, die von ihm ausgesandt sind zur Bestrafung der Übeltäter und zum Lobe der Rechtschaffenen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Denn so ist es der Wille Gottes, daß ihr durch Gutestun die Unwissenheit der unverständigen Menschen zum Schweigen bringt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'Als Freie und nicht als ob ihr die Freiheit zum Deckmantel der Bosheit gebraucht, sondern als die Knechte Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Haltet jedermann in Ehren, liebet die Brüderschaft, fürchtet Gott, ehrt den König.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Ihr Knechte, seid untertan in aller Furcht den Herren, nicht allein den gütigen und gelinden, sondern auch den wunderlichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Denn das ist Gnade, wenn einer aus Gewissenhaftigkeit gegen Gott Widerwärtigkeiten erträgt und ungerecht leidet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Denn was ist das für ein Ruhm, so ihr Unrecht tut und dafür Streiche zu erdulden habt; aber wenn ihr Recht tut und Leiden erduldet, das ist Gnade bei Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Denn dazu seid ihr berufen; hat ja auch Christus für euch gelitten und euch ein Vorbild gelassen, daß ihr Seinen Fußstapfen nachfolgen sollt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'Er, Der keine Sünde getan, in Dessen Mund auch kein Trug erfunden worden ist;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'Der nicht wieder schalt, da Er gescholten ward, nicht drohte, da Er litt; es Dem, Der da gerecht richtet, anheim stellte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'Der unsere Sünden Selbst an Seinem Leibe an das Holz hinauf nahm, auf daß wir, den Sünden abgestorben, der Gerechtigkeit leben, durch Dessen Wunden ihr geheilt worden seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Denn ihr ward wie die Schafe, die in der Irre gehen, seid nun aber zum Hirten und Bischof eurer Seelen zurückgekehrt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Desgleichen sollen die Weiber ihren Männern untertan sein, auf daß auch die, so noch nicht an das Wort glauben, durch der Weiber Wandel ohne Wort gewonnen werden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'Wenn sie auf euren keuschen, gottesfürchtigen Wandel sehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Darum sei ihr Schmuck nicht der äußere, bestehend in Haarflechten, im Anlegen von Goldgeschmeide, oder in Gewändern,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'Sondern der verborgene Mensch des Herzens, in unvergänglichem Wesen, mit sanftem und stillem Geiste, der köstlich ist vor den Augen Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Denn also haben sich vor Zeiten die heiligen Weiber geschmückt, die ihre Hoffnung auf Gott setzten und ihren Männern untertan waren,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'Wie Sarah Abraham untertan war und ihn Herr nannte, deren Töchter ihr geworden seid, so ihr wohl tut und euch vor keinem Schrecknisse fürchtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Desgleichen ihr Männer, geht mit ihnen verständig um, als mit dem schwächeren Werkzeug, und beweist ihnen Ehre als Miterben der Gnade des Lebens, auf daß euer Gebet Erhörung finde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Seid überhaupt allesamt gleichen Sinnes, teilnehmend, brüderlich, barmherzig und wohlwollend.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'Vergeltet nicht Böses mit Bösem, nicht Scheltwort mit Scheltwort, segnet vielmehr und seid eingedenk, daß ihr dazu berufen seid, daß ihr Segen ererbet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Denn wer des Lebens froh sein und gute Tage sehen will, der bewahre seine Zunge vor Bösem und seine Lippen, daß sie nichts Trügliches reden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'Er wende sich ab vom Bösen und tue Gutes, suche Frieden und jage ihm nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Denn die Augen des Herrn merken auf die Gerechten, und Seine Ohren auf ihr Gebet; das Angesicht des Herrn wendet sich wider die, so Böses tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'Und wer ist, der euch Übles tun könnte, so ihr dem Guten nachkommt?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Und ob ihr auch leidet um der Gerechtigkeit willen, so seid ihr doch selig; fürchtet euch aber nicht vor dem, womit sie euch schrecken wollen, und seid unverzagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Christus den Herrn aber haltet heilig in euren Herzen; seid allezeit bereit, jedem Rede zu stehen, der von euch Grund fordert für die Hoffnung, die in euch ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'Und das mit Sanftmut und Ehrfurcht vor Gott, indem ihr ein gutes Gewissen habt, daß sie, die von euch Übles reden als von Übeltätern, darob zuschanden werden, daß sie euren guten Wandel in Christus geschmäht haben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Denn es ist besser, so es Gottes Wille ist, daß ihr leidet ob dem Gutestun, denn ob dem Übeltun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Weil auch Christus einmal für unsere Sünden gelitten hat, der Gerechte für die Ungerechten, auf daß Er uns zu Gott brächte, und ist getötet worden dem Leibe nach, und lebendig gemacht nach dem Geiste,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'In welchem Er auch hingegangen ist und den Geistern im Gefängnis gepredigt hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'Die vordem ungläubig waren, da Gottes Langmut harrte in den Tagen Noachs, als man die Arche zurichtete, in die wenige, das heißt nur acht');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'Welches nun auch euch selig macht im Gegenbild der Taufe, nicht als die Abwaschung des Unrats am Fleische, sondern als der Bund eines guten Gewissens mit Gott durch die Auferstehung Jesu Christi;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'Der zur Rechten Gottes ist, nachdem Er in den Himmel aufgefahren, wo die Engel, Gewalten und Kräfte Ihm untertänig sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Weil nun Christus für uns dem Fleische nach gelitten hat, so wappnet auch ihr euch mit dem gleichen Gedanken. Denn der am Fleische gelitten hat, ist abgebracht vom Sündigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'Daß er hinfort, solange er noch im Fleische lebt, nicht menschlichen Lüsten, sondern dem Willen Gottes lebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Denn es ist genug, daß wir die vergangene Zeit des Lebens nach dem Willen der Heiden in Ausschweifungen, Wollüsten, Trunksucht, Schwelgereien, Zechgelagen, greulichen Abgöttereien hingebracht haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'Das befremdet sie, daß ihr nicht mehr in demselben wüsten, unordentlichen Wesen mit ihnen fortlaufet, und da lästern sie euch;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Sie müssen aber Rechenschaft geben Dem, Der nun bereit ist zu richten die Lebendigen und die Toten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Denn dazu ist auch den Toten das Evangelium gepredigt worden, auf daß sie als Menschen nach dem Fleische gerichtet würden, im Geiste aber Gott wohlgefällig leben könnten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Es ist aber das Ende aller Dinge nahe gekommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'So seid nun mäßig und nüchtern zum Gebet. Vor allem aber habt eine herzliche Liebe zueinander; denn die Liebe deckt auch der Sünden Menge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Seid gastfrei untereinander, ohne Murren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Und dient einander, ein jeglicher mit der Gabe, die er empfangen hat, als gute Haushalter der mannigfaltigen Gnade Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'So einer redet, rede er nach Gottes Wort. So jemand ein Amt hat, so warte er des Amtes nach dem Vermögen, das Gott ihm gibt, auf daß in allen Dingen Gott durch Jesus Christus gepriesen werde, Welchem sei Ehre und Gewalt von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Lasset euch nicht befremden, Geliebte, daß unter euch das Feuer der Prüfung für euch auskommt, als ob euch etwas Absonderliches widerführe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'Freut euch vielmehr darüber, auf daß ihr, inwieweit ihr an Christus Leiden teilhaben dürft, euch auch bei der Offenbarung Seiner Herrlichkeit freuen und frohlocken mögt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Selig seid ihr, wenn ihr über Christus Namen geschmäht werdet, weil der Geist der Herrlichkeit und Gottes sich auf euch niederläßt; denn von ihnen wird Er verlästert, in euch aber verherrlicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Niemand unter euch leide als ein Mörder oder Dieb oder Übeltäter oder als einer, der sich in fremde Händel mischt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'Leidet er aber als Christ, so schäme er sich dessen nicht, sondern preise Gott dafür.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Denn es ist die Zeit, da das Gericht anfängt an dem Hause Gottes; wenn aber zuerst bei uns, was wird es für ein Ende nehmen bei denen, die dem Evangelium Gottes nicht glauben?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'Und so der Gerechte kaum erhalten wird, wo wird der Gottlose und Sünder zu stehen kommen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Darum sollen die, so da leiden nach dem Willen Gottes, Ihm, Dem treuen Schöpfer, ihre Seelen empfehlen und Gutes tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Die Ältesten, die unter euch sind, ermahne ich als Mitältester und Zeuge von Christus Leiden und Teilhaber der Herrlichkeit, die geoffenbart werden soll:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Weidet die Herde Gottes, die euch anvertraut ist, und haltet Aufsicht, nicht zwangsweise, sondern williglich, auch nicht schändlichen Gewinnes wegen, sondern aus Herzensgrund;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'Nicht wie solche, die über die ihnen Zugewiesenen herrschen, sondern der Herde Vorbilder werden wollen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'So werdet ihr, wenn der Erzhirte kommt, einen unverwelklichen Ehrenkranz erhalten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Desgleichen ihr Jüngere seid untertan den Ältesten. Ihr allesamt, willfahrt einander und haltet fest an der Demut, denn Gott widersteht den Hoffärtigen, aber den Demütigen gibt Er Gnade.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'So demütigt euch nun unter die gewaltige Hand Gottes, daß Er euch erhöhe zu Seiner Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'Alle eure Sorge werfet auf Ihn; denn Er sorgt für euch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Seid nüchtern und wachet, denn euer Widersacher, der Teufel, geht umher wie ein brüllender Löwe, und sucht, wen er verschlinge.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'Widersteht ihm fest im Glauben und seid eingedenk, daß dieselben Leiden auch über eure Brüder in der Welt ergehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Aber der Gott aller Gnade, Der euch berufen hat zu Seiner ewigen Herrlichkeit in Christo Jesu, wird euch, nachdem ihr eine kleine Zeit gelitten habt, vollbereiten, stärken, kräftigen, auf festen Grund stellen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Ihm sei Ehre und Macht von Ewigkeit zu Ewigkeit! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Durch Silvanus, euren treuen Bruder, wie ich achte, habe ich dies wenige geschrieben, um euch zu ermahnen und zu bezeugen, daß dies die wahre Gnade Gottes ist, bei der ihr beharren sollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Es grüßt euch die miterwählte');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Grüßet einander mit dem Kusse der Liebe. Friede sei mit euch allen, die in Christo Jesu sind! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Petrus, ein Knecht und Apostel Jesu Christi, denen, die mit uns durch die Gerechtigkeit unseres Gottes und Heilandes Jesus Christus den gleich teuren Glauben erlangt haben:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Gnade und Friede werde euch in Fülle zuteil durch die Erkenntnis Gottes und Jesus, unseres Herrn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'Weil uns Seine göttliche Kraft alles Vermögen zum Leben und zur Gottseligkeit geschenkt hat, durch die Anerkennung Dessen, Der uns durch Seine Herrlichkeit und Tugend berufen hat,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'Mittelst welcher Er uns die herrlichsten und köstlichsten Verheißungen gegeben hat, auf daß ihr durch sie, nachdem ihr dem Verderben der Weltlust entronnen, göttlichen Wesens teilhaftig würdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'So wendet denn allen Fleiß an, daß ihr durch den Glauben an Ihn Kraft zur Tugend, und durch die Kraft zur Tugend Erkenntnis,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'Und durch die Erkenntnis Selbstbezwingung, und durch die Selbstbezwingung Standhaftigkeit,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'Und durch die Standhaftigkeit Gottseligkeit, und durch die Gottseligkeit Bruderliebe, und durch die Bruderliebe Liebe');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Denn wo solches bei euch ist, und immer mehr wird, läßt es euch nicht lässig noch unfruchtbar bleiben für die Erkenntnis unseres Herrn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Wer aber solches nicht hat, der ist blödsichtig, blind und vergißt, sich von seinen vorigen Sünden zu reinigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Darum fleißigt euch, Brüder, desto mehr, eure Berufung und Erwählung fest zu machen; denn so ihr solches tut, werdet ihr nimmermehr zu Fall kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Denn so wird euch in reichem Maße die Gnade zuteil, zum ewigen Reiche unseres Herrn und Heilandes Jesus Christus einzugehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Darum will ich nicht unterlassen, euch immer daran zu erinnern, obwohl ihr es schon wißt und in der euch gewordenen Wahrheit befestigt seid.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Denn ich halte es für Pflicht, solange ich in dieser Hütte bin, euch durch Mahnungen wach zu erhalten;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'Weil ich weiß, daß ich diese meine Hütte bald verlassen muß, wie mir auch unser Herr Jesus Christus kundgetan hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Ich will mich aber fleißigen, daß ihr nach meinem Hinscheiden dessen allezeit eingedenk bleibt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Denn wir sind keinen schlau ersonnenen Märchen gefolgt, da wir euch die Kraft und Zukunft von Jesus Christus kund getan, und sind Augenzeugen Seiner Herrlichkeit geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Denn Er empfing von Gott dem Vater Ehre und Preis, da unter herrlichem Glanze die Stimme von oben erscholl: Dies ist Mein lieber Sohn, an Dem Ich Wohlgefallen habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'Und diese Stimme haben wir gehört, wie sie vom Himmel herabkam, da wir mit Ihm auf dem heiligen Berge waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'Und wir haben ein noch festeres prophetisches Wort, auf das zu achten ihr wohl tut, als auf ein Licht, das da scheint an einem dunklen Ort, bis der Tag anbricht und der Morgenstern aufgeht in euren Herzen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'Und das sollt ihr vor allem wissen, daß jegliche Prophezeiung der Schrift nicht aus eigener Deutung geschieht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Denn es ist noch keine Weissagung aus menschlichem Willen hervorgebracht worden, sondern, vom Heiligen Geist getrieben, haben heilige Männer Gottes geredet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Es waren aber auch falsche Propheten unter dem Volk, wie auch unter euch falsche Lehrer sein werden, die verderbliche Sekten nebenbei einführen und den Herrn, Der sie erkauft hat, verleugnen und eine schnelle Verdammnis über sich herbeiführen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'Und viele werden ihnen ins Verderben nachfolgen, durch die der Weg der Wahrheit wird verlästert werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'Und aus Gewinnsucht wollen sie euch mit Trugreden überlisten; aber das längst über sie verhängte Urteil säumt nicht, und ihre Verdammnis schlummert nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Hat doch Gott der Engel, die gesündigt hatten, nicht verschont, sondern sie in Ketten der Finsternis in den Höllengrund verstoßen und dort lassen zum Gericht aufbewahren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'Und hat nicht der alten Welt verschont, sondern nur Noach, den Prediger der Gerechtigkeit, selbacht erhalten, über die Welt der Gottlosen aber die Sündflut herbeigeführt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'Auch hat Er die Städte Sodom und Gomorrah in Asche gelegt, umgekehrt und verdammt, und damit ein warnendes Beispiel für Gottlose gesetzt, die hernach kommen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'Und hat erlöst den gerechten Lot, dem die zügellosen Leute mit ihrem unzüchtigen Wandel alles Leid angetan;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, 'Denn dem Gerechten, der unter ihnen wohnte, daß er es mit ansehen und hören mußte, quälten sie die gerechte Seele von Tag zu Tag mit ihren ungerechten Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Der Herr weiß die Gottseligen aus der Anfechtung zu erlösen, die Ungerechten aber auf den Tag des Gerichtes zur Peinigung aufzubewahren;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'Allermeist aber die, so nach dem Fleische ihrer unreinen Lust nachgehen, die Seine Herrschermacht verachten und in frecher Selbstgefälligkeit sich nicht scheuen, das, was herrlich ist, zu verlästern,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'So doch die Engel, die größer an Stärke und Macht sind, gegen sie vor dem Herrn kein lästerndes Urteil fällen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Aber sie sind wie unvernünftige, sinnliche Tiere, zum Fang und zur Schlachtung geboren, lästern, davon sie nichts wissen, und werden in ihrer Verderbnis umkommen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'Und so den Lohn der Ungerechtigkeit davontragen, weil sie ihre zeitliche Lust in sinnlichem Wohlleben finden, diese Schandund Lasterbuben, die sich noch auf ihre Betrügereien etwas zugute tun und mit euch schmausen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'Deren Augen voll Ehebruchs sind, die sich von der Sünde nicht abbringen lassen, und unbefestigte Seelen verlocken, deren Herz voll verschmitzter Habgier ist, Kinder des Fluches,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'Die den geraden Weg verlassen, in der Irre gehen, und in dem Irrweg Bileams, des Sohnes Beors, folgen, den nach dem Lohne der Ungerechtigkeit gelüstete;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'Er hatte aber eine Zurechtweisung für seine Übertretung; denn das stumme, lastbare Tier redete mit Menschenstimme und wehrte der Torheit des Propheten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Das sind Brunnen ohne Wasser, Wolken, vom Wirbelwind umgetrieben, denen der Finsternis ewiges Dunkel vorbehalten ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Denn sie reden hohle Worte, da nichts dahinter ist, reizen durch fleischliche Lüste und Ausschweifungen solche an, die denen, welche auf Irrwegen gehen, schon entronnen waren,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'Und verheißen ihnen Freiheit, indes sie selbst Knechte des Verderbens sind; denn wem einer untertan ist, dessen Knecht ist er.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Denn so sie den Befleckungen der Welt durch die Erkenntnis des Herrn und Heilandes Jesus Christus entgangen, aber wieder in solche hineingezogen werden und ihnen erliegen, ist mit ihnen das letzte ärger geworden, als das erste.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Denn es wäre ihnen besser gewesen, wenn sie den Weg der Gerechtigkeit nicht erkannt hätten, als daß sie, nachdem sie ihn erkannt, von dem heiligen Gebot, das ihnen gegeben ist, sich wieder abkehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Dann trifft bei ihnen das wahre Sprichwort ein: Der Hund frißt wieder, was er gespieen hat, und das Schwein wälzt sich nach der Schwemme wieder im Kot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Dies, Geliebte, ist schon der zweite Brief, den ich euch schreibe, darin ich euch erinnere und ermahne zu lauterem Sinn,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'Eingedenk zu sein der Worte, die euch zuvor von den heiligen Propheten gesagt worden sind, und unseres Gebotes, die wir Apostel des Herrn und Heilandes sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'Und daß ihr vor allen Dingen wisset, daß in den letzten Tagen Spötter kommen werden, die mit ihrem Gespött nach ihren eigenen Gelüsten wandeln und sagen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'Wo ist die Verheißung Seiner Zukunft? Denn seit die Väter entschlafen sind, bleibt alles, wie es seit Anfang der Schöpfung gewesen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Aber denen, die solches aufstellen wollen, ist unbekannt, daß Himmel von Alters her waren, und die Erde durch das Wort Gottes aus dem Wasser und durch Wasser erstanden ist,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'Durch welches');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'Die jetzigen Himmel aber und die Erde werden durch Sein Wort aufbewahrt und für das Feuer behalten auf den Tag des Gerichts und der Verdammnis der gottlosen Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'Eins aber sei euch unverhalten, Geliebte, daß ein Tag vor dem Herrn ist wie tausend Jahre, und tausend Jahre wie ein Tag.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Der Herr verzieht nicht mit Seiner Verhei-ßung, wie etliche es für einen Verzug erachten, sondern hat Geduld mit uns, und will nicht, daß etwelche verlorengehen, sondern daß sich alle zur Buße kehren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Es wird aber der Tag des Herrn kommen wie ein Dieb in der Nacht, an dem die Himmel rauschend dahinfahren, ihre Grundstoffe brennen und zergehen, und die Erde mit den Gebilden auf ihr im Feuer aufgehen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'So nun all das vergeht, wie sehr müßt ihr euch befleißigen, in heiligem Wandel und in Gottseligkeit zu erscheinen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'Indem ihr erwartet und beschleunigt die Zukunft des Tages des Herrn, an dem die Himmel im Feuer zergehen und die Grundstoffe brennend zerschmelzen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Wir erwarten nach Seiner Verheißung neue Himmel und eine neue Erde, in denen Gerechtigkeit wohnt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Darum, Geliebte, weil ihr solches erwartet, befleißigt euch, daß ihr vor Ihm unbefleckt und unsträflich im Frieden erfunden werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'Und die Langmut unseres Herrn erachtet als Heil, gleichwie auch unser geliebter Bruder Paulus nach seiner ihm verliehenen Weisheit euch geschrieben hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'Wie er auch in allen den Briefen tut, wenn er davon redet; wo einiges schwer zu verstehen ist, was Ungelehrige und Unbefestigte verdrehen, wie auch die anderen Schriften, zu ihrer eigenen Verdammnis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Ihr aber, Geliebte, die ihr dies zuvor wißt, seid auf eurer Hut, daß ihr nicht durch die Irrlehre ruchloser Leute mitverführt und aus eurer eigenen festen Stellung hinweggerückt werdet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'Wachset vielmehr in der Gnade und Erkenntnis unseres Herrn und Heilandes Jesus Christus! Ihm sei Ehre nun und in alle Ewigkeit! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Was da von Anfang war, was wir gehört und mit unseren Augen gesehen, was wir beschaut und mit unseren Händen betastet haben vom Worte des Lebens -');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, 'Und das Leben erschien, und wir haben es gesehen und bezeugen und verkündigen euch das Leben, das ewig ist, das beim Vater war und uns erschienen ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'Was wir gesehen und gehört haben, verkündigen wir euch, auf daß auch ihr mit uns Gemeinschaft habet; und unsere Gemeinschaft ist mit dem Vater und mit Seinem Sohn Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'Und solches schreiben wir euch, auf daß eure Freude vollkommen sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'Und das ist die Verkündigung, die wir von Ihm gehört haben und euch verkündigen, daß Gott ein Licht und in Ihm keine Finsternis ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Wenn wir sagen, daß wir Gemeinschaft mit Ihm haben, und wandeln in der Finsternis, so lügen wir und tun die Wahrheit nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'So wir aber im Licht wandeln, wie Er im Licht ist, so haben wir Gemeinschaft miteinander, und das Blut Seines Sohnes Jesus Christus reinigt uns von aller Sünde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'So wir sagen, wir haben keine Sünde, so täuschen wir uns selbst, und die Wahrheit ist nicht in uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'So wir aber unsere Sünden bekennen, so ist Er treu und gerecht, daß Er uns die Sünden vergibt und uns reinigt von aller Ungerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'So wir sagen, wir hätten nicht gesündigt, so machen wir Ihn zum Lügner, und Sein Wort ist nicht in uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Meine Kindlein, solches schreibe ich euch, auf daß ihr nicht sündigt; und so einer gesündigt hat, haben wir einen Beistand beim Vater, Jesus Christus, den Gerechten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'Und Er ist die Versöhnung für unsere Sünden, nicht allein aber für die unseren, sondern auch für die der ganzen Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'Und daran erkennen wir, daß wir Ihn erkannt haben, so wir Seine Gebote halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Wer da sagt: Ich kenne Ihn, und hält Seine Gebote nicht, der ist ein Lügner und in solchem ist die Wahrheit nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'Wer aber Sein Wort hält, in dem ist in Wahrheit die Liebe vollkommen geworden. Daran erkennen wir, daß wir in Ihm sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Wer da sagt, er bleibe in Ihm, der muß auch wandeln, gleich wie Er gewandelt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Brüder, ich schreibe euch kein neu Gebot, sondern ein alt Gebot, das ihr von Anfang an hattet; und das alte Gebot ist das Wort, das ihr von Anfang an gehört habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Wiederum schreibe ich euch ein neu Gebot, das wahr ist in Ihm und in euch; denn die Finsternis geht vorbei und das wahre Licht scheint bereits.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Wer da sagt, er sei im Licht, und haßt seinen Bruder, der ist noch in der Finsternis.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Wer seinen Bruder liebt, der bleibt im Licht, und kein Ärgernis ist in ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Wer aber seinen Bruder haßt, der ist in der Finsternis und wandelt in der Finsternis, und weiß nicht, wohin er geht, weil die Finsternis seine Augen verblendet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Ich schreibe euch, Kindlein, weil die Sünden euch um Seines Namens willen vergeben sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Ich schreibe euch, Väter, weil ihr Den, Der von Anfang ist, erkannt habt. Ich schreibe euch, Jüngere, weil ihr den Bösen überwunden habt. Ich schreibe euch, Kindlein, weil ihr den Vater erkannt habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Ich habe euch, Väter, geschrieben, weil ihr Den, Der von Anfang ist, erkannt habt. Ich habe euch, Jüngere, geschrieben, weil ihr stark seid und das Wort Gottes in euch bleibt und ihr den Bösen überwunden habt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Habt nicht lieb die Welt, noch was in der Welt ist. So jemand die Welt lieb hat, in dem ist die Liebe des Vaters nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Denn alles, was in der Welt ist, des Fleisches Lust und der Augen Lust und die Hoffart des Lebens, ist nicht vom Vater, sondern von der Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'Und die Welt vergeht mit ihrer Lust; wer aber den Willen Gottes tut, der bleibt in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Kindlein, es ist die letzte Stunde; und wie ihr gehört habt, daß der Widerchrist kommt, so sind auch jetzt schon viele Widerchristen gekommen. Daran erkennen wir, daß es um die letzte Stunde ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Von uns sind sie ausgegangen, sie waren aber nicht von uns; denn wenn sie von uns gewesen wären, so wären sie bei uns geblieben; aber es sollte offenbar werden, daß sie nicht alle von uns sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'Und ihr habt die Weihe vom Heiligen und wißt alles.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Ich habe nicht an euch geschrieben, als ob ihr die Wahrheit nicht wüßtet, sondern weil ihr sie wißt, und daß keine Lüge aus der Wahrheit kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Denn wer ist der Lügner, wo nicht der, so da leugnet, daß Jesus der Christ ist? Der ist der Widerchrist, der den Vater und den Sohn verleugnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Jeder, der den Sohn verleugnet, hat auch den Vater nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Was ihr denn von Anfang gehört habt, das bleibe in euch. Wenn in euch bleibt, was ihr von Anfang an gehört habt, so werdet ihr auch in dem Sohne und in dem Vater bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'Und das ist die Verheißung, die Er uns verheißen hat, das ewige Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'Solches habe ich euch geschrieben wegen derer, die euch verführen wollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'Und die Salbung, die ihr von Ihm empfangen habt, bleibt in euch, und ihr bedürft nicht, daß euch jemand lehre, sondern wie eben die Salbung euch belehrt über alles, so ist sie auch wahr und ist keine Lüge, und wie sie euch gelehrt hat, so bleibt dabei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'Und nun, Kindlein, bleibt in Ihm, auf daß wir, wenn Er erscheinen wird, freudige Zuversicht haben, und bei Seiner Zukunft vor Ihm nicht zuschanden werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'So ihr nun wißt, daß Er gerecht ist, erkennt auch, daß jeder, der die Gerechtigkeit übt, aus Ihm geboren ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Seht, welche Liebe uns der Vater erzeigt hat, daß wir sollten Gottes Kinder heißen. Darum erkennt uns die Welt nicht, weil sie Ihn nicht erkannt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Geliebte, wir sind nun Gottes Kinder, und noch ist nicht offenbar, was wir sein werden. Wir wissen aber, daß wir, wenn Er erscheinen wird, Ihm gleich sein werden; denn wir werden Ihn sehen, wie Er ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'Und ein jeglicher, der solche Hoffnung auf Ihn hat, reinigt sich, gleich wie Er rein ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Jeder, der Sünde tut, übertritt das Gesetz, und die Sünde ist Übertretung des Gesetzes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'Und ihr wißt, daß Er erschienen ist, auf daß Er unsere Sünden wegnehme, und in Ihm keine Sünde ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Jeder, der in Ihm bleibt, sündigt nicht. Jeder, der sündigt, hat Ihn nicht gesehen, noch Ihn erkannt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Kindlein, laßt euch von niemand irre führen. Wer tut, was recht ist, ist gerecht, gleich wie Er gerecht ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'Wer Sünde tut, ist vom Teufel; denn der Teufel sündigt von Anfang. Dazu ist der Sohn Gottes erschienen, daß Er die Werke des Teufels zerstöre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Jeder, der aus Gott geboren ist, tut keine Sünde, weil Sein Same in ihm bleibt, und er kann nicht sündigen, weil er aus Gott geboren ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'Daran sind offenbar die Kinder Gottes und die Kinder des Teufels. Jeder, der nicht recht tut und seinen Bruder nicht liebt, ist nicht aus Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Denn das ist die Botschaft, die ihr von Anfang gehört habt, daß wir einander lieben sollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'Nicht wie Kain, der aus dem Argen war und seinen Bruder mordete. Und warum hat er ihn gemordet? Weil seine Werke böse waren, die seines Bruders aber gerecht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Verwundert euch nicht, meine Brüder, daß euch die Welt haßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Wir wissen, daß wir aus dem Tod ins Leben übergegangen sind; denn wir lieben die Brüder. Wer den Bruder nicht liebt, der bleibt im Tode.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Jeder, der seinen Bruder haßt, ist ein Mörder, und ihr wißt, daß in keinem Mörder das ewige Leben bleiben kann.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'Daran haben wir die Liebe erkannt, daß Er Sein Leben für uns gelassen. Auch wir sollen für die Brüder das Leben lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Wenn aber einer dieser Welt Güter hat und sieht seinen Bruder Not leiden, und verschließt sein Herz vor ihm, wie bleibt da die Liebe Gottes in ihm?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Meine Kindlein, laßt uns nicht lieben mit Worten, noch mit der Zunge, sondern mit der Tat und mit der Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'Und dadurch erkennen wir, daß wir aus der Wahrheit sind und können unsere Herzen vor Ihm beruhigen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'Daß, wenn uns unser Herz verdammt, Gott größer ist, denn unser Herz und alle Dinge erkennt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Geliebte, wenn uns unser Herz nicht verdammt, dann haben wir ein freudiges Vertrauen zu Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'Und alles, was wir von Ihm erbitten, erlangen wir von Ihm, weil wir Seine Gebote halten, und tun, was vor Ihm wohlgefällig ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'Und das ist Sein Gebot, daß wir an den Namen Seines Sohnes Jesus Christus glauben und einander lieben, wie Er uns geboten hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'Wer Seine Gebote hält, der bleibt in Ihm und Er in ihm. Und daran erkennen wir, daß Er in uns bleibt, an dem Geiste, den Er uns gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Geliebte, glaubt nicht jeglichem Geiste, sondern prüft die Geister, ob sie von Gott sind; denn viele falsche Propheten sind in die Welt ausgegangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'Daran erkennt den Geist Gottes: Jeder Geist, der da bekennt, daß Jesus Christus ist in das Fleisch gekommen, ist von Gott;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, 'Und ein jeglicher Geist, der Jesus Christus nicht als ins Fleisch gekommen bekennt, der ist nicht von Gott, und das ist der');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Ihr seid aus Gott, Kindlein, und habt sie überwunden, denn Der in euch ist, ist größer, als der in der Welt ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Sie sind von der Welt, darum reden sie von der Welt und die Welt hört auf sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Wir sind von Gott; wer Gott erkennt, der hört auf uns; wer nicht aus Gott ist, hört nicht auf uns. Daran erkennen wir den Geist der Wahrheit und den Geist der Irrlehre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Geliebte, laßt uns einander lieben; denn die Liebe ist aus Gott und der da liebt, ist aus Gott geboren und erkennt Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Wer nicht liebt, hat Gott nicht erkannt; denn Gott ist die Liebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'Darin hat sich die Liebe Gottes an uns geoffenbart, daß Gott Seinen eingeborenen Sohn in die Welt gesendet hat, daß wir durch Ihn leben sollten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'Darin besteht die Liebe, nicht daß wir Gott liebten, sondern daß Er uns liebte und Seinen Sohn zur Versöhnung für unsere Sünden gesandt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Geliebte, wenn uns nun Gott also geliebt hat, so sollen auch wir einander lieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Niemand hat Gott jemals geschaut. So wir einander lieben, so bleibt Gott in uns und Seine Liebe ist völlig in uns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'Daran erkennen wir, daß wir in Ihm bleiben, und Er in uns, daß Er uns von Seinem Geist gegeben hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'Und wir haben geschaut und zeugen, daß der Vater den Sohn als Heiland der Welt gesendet hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Wer nun bekennt, daß Jesus der Sohn Gottes ist, in dem bleibt Gott, und er in Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'Und wir haben die Liebe, so Gott zu uns hat, erkannt, und an sie geglaubt. Gott ist Liebe, und wer in der Liebe bleibt, bleibt in Gott und Gott in ihm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'Daran ist die Liebe völlig in uns, auf daß wir freudiges Vertrauen haben am Tage des Gerichts, weil, wie Er ist, so auch wir in dieser Welt sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Furcht ist nicht in der Liebe, sondern völlige Liebe treibt die Furcht aus; denn Furcht hat Strafe, und wer sich fürchtet, ist nicht vollkommen in der Liebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Laßt uns Ihn lieben, denn Er hat uns zuerst geliebt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'So jemand spricht: Ich liebe Gott, und haßt seinen Bruder, der ist ein Lügner; denn wer seinen Bruder nicht liebt, den er sieht, wie kann er Gott lieben, Den er nicht sieht?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'Und dies Gebot haben wir von Ihm, daß, wer Gott liebt, auch seinen Bruder liebe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Wer da glaubt, daß Jesus ist der Christ, Der ist aus Gott geboren; und wer da liebt Den, der Ihn gezeugt hat, der liebt auch Den, Der aus Ihm geboren ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'Daran erkennen wir, daß wir Gottes Kinder lieben, wenn wir Gott lieben und Seine Gebote halten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Denn das ist die Liebe zu Gott, daß wir Seine Gebote halten; und Seine Gebote sind nicht schwer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Denn alles, was aus Gott geboren ist, überwindet die Welt, und unser Glaube ist der Sieg, der die Welt überwunden hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Wer anders überwindet die Welt, wo nicht der, so da glaubt, daß Jesus der Sohn Gottes ist?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Dieser ist es, Der da gekommen ist mit Wasser und Blut, Jesus Christus, nicht mit Wasser allein, sondern mit Wasser und Blut, und der Geist ist es, der da zeugt, weil der Geist die Wahrheit ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'Denn drei sind, die da zeugen im Himmel: der Vater, das Wort und der Heilige Geist, und diese drei sind eins.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Und drei sind, die da zeugen auf Erden: der Geist und das Wasser und das Blut, und diese drei sind eins.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'So wir der Menschen Zeugnis annehmen, so ist Gottes Zeugnis noch größer; denn das ist Gottes Zeugnis, das Er von Seinem Sohne gezeugt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Wer da glaubt an den Sohn Gottes, der hat das Zeugnis in ihm selber; wer nicht an Gott glaubt, der hat Ihn zum Lügner gemacht, weil er nicht geglaubt hat an das Zeugnis, das Gott von Seinem Sohn gezeugt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'Und das ist das Zeugnis, daß Gott uns das ewige Leben gegeben hat, und solches Leben ist in Seinem Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Wer den Sohn hat, der hat das Leben; wer den Sohn Gottes nicht hat, der hat das Leben nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'Solches habe ich euch geschrieben, die ihr an den Namen des Sohnes Gottes glaubt, auf daß ihr wißt, daß ihr ewiges Leben habt, und auf daß ihr glaubt an den Namen des Sohnes Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'Und das ist die freudige Zuversicht, die wir zu Ihm haben, daß, so wir etwas bitten nach Seinem Willen, Er uns erhört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'Und so wir wissen, daß Er uns erhört in dem, um was wir Ihn auch bitten mögen, so wissen wir, daß wir das von Ihm Erbetene erlangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Wenn einer seinen Bruder eine Sünde begehen sieht, nicht zum Tode, so mag er bitten und Er wird ihm Leben schenken, denen, die da sündigen nicht zum Tode. Es gibt aber eine Sünde zum Tode, dafür sage ich nicht, daß er bitten soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Alles Unrecht ist Sünde, aber es gibt eine Sünde, die nicht zum Tode ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Wir wissen, daß, wer von Gott geboren ist, nicht sündigt, daß vielmehr der von Gott Geborene sich bewahrt und der Arge ihn nicht antastet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Wir wissen, daß wir aus Gott sind und die ganze Welt im Argen liegt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Wir wissen aber, daß der Sohn Gottes gekommen ist und uns Einsicht gegeben hat, daß wir den Wahrhaftigen erkennen, und so sind wir in dem Wahrhaftigen, in Seinem Sohne Jesus Christus. Dieser ist der wahrhaftige Gott und das ewige Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Kindlein, hütet euch vor den Abgöttern! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Der Älteste an die auserwählte Kyria und an ihre Kinder, die ich liebe in Wahrheit, und nicht allein ich, sondern auch alle, welche die Wahrheit erkannt haben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'Um der Wahrheit willen, die in uns bleibt und bei uns sein wird in Ewigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Gnade, Barmherzigkeit, Friede von Gott dem Vater und von dem Herrn Jesus Christus, dem Sohn des Vaters, in Wahrheit und Liebe sei mit dir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Ich freute mich sehr, daß ich von deinen Kindern solche gefunden habe, die in der Wahrheit wandeln, wie wir das Gebot vom Vater empfangen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'Und nun bitte ich dich, Kyria, nicht als ob ich dir ein neu Gebot schriebe, sondern eines, das wir von Anfang an hatten, daß wir einander lieben sollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'Und das ist die Liebe, daß wir wandeln nach Seinen Geboten. Das ist das Gebot, wie ihr von Anfang angehört habt, daß ihr darin wandeln sollt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Denn viele Verführer sind in die Welt gekommen, die Jesus Christus nicht bekennen als in das Fleisch gekommen. Dies ist der Verführer und der Widerchrist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Seht euch vor, daß wir nicht verlieren, was wir erarbeitet haben, sondern vollen Lohn empfangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Wer darüber hinaus will und nicht bei der Lehre Christi bleibt, der hat Gott nicht; wer aber bei der Lehre Christi bleibt, der hat sowohl den Vater als den Sohn.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Wenn einer zu euch kommt und diese Lehre nicht bringt, den nehmt nicht in das Haus und grüßt ihn auch nicht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'Denn wer ihn begrüßt, der nimmt Teil an seinen bösen Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Ich hätte euch noch viel zu schreiben, aber ich wollte nicht mit Papier und Tinte, hoffe aber zu euch zu kommen und mündlich davon zu reden, auf daß unsere Freude vollkommen sei.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Es grüßen dich die Kinder deiner Schwerster, der Auserwählten. Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Der Älteste an den geliebten Gajus, den ich liebe in Wahrheit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Geliebter, ich wünsche, daß es dir in allen Stücken wohl gehe, und du gesund seiest wie es deiner Seele wohl ergeht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Es freute mich sehr, als Brüder kamen und deiner Wahrhaftigkeit Zeugnis gaben, wie du denn in der Wahrheit wandelst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Ich habe keine größere Freude denn die, daß ich höre, wie meine Kinder in der Wahrheit wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Geliebter, du handelst treulich in dem, was du an den Brüdern, und zumal an denen tust, die aus der Ferne kommen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'Und die von deiner Liebe vor der Gemeinde Zeugnis gaben, und du wirst wohl tun, wenn du ihnen auf eine Gottes würdige Weise forthilfst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Denn um Seines Namens willen sind sie ausgegangen und haben von den Heiden nichts genommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'So gebührt es uns denn, solche aufzunehmen, auf daß wir der Wahrheit Vorschub tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Ich schrieb an die Gemeinde, aber Diotrephes, der unter ihnen will der Erste sein, nimmt uns nicht an.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Darum, wenn ich komme, will ich ihn vermahnen ob seinen Werken, die er tut, indem er übel von uns spricht, und es nicht dabei bewenden läßt, und die Brüder nicht annimmt, und die, so es tun wollen, aus der Gemeinde stößt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Geliebter, folge nicht dem Bösen nach, sondern dem Guten. Wer Gutes tut, ist aus Gott, wer Böses tut, hat Gott nicht geschaut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demetrius hat von jedermann ein gutes Zeugnis, und von der Wahrheit selbst, und auch wir zeugen');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Ich hätte dir noch viel zu schreiben, allein ich will es nicht mit Tinte und Feder tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'Ich hoffe, dich bald zu sehen, und dann wollen wir es mündlich besprechen. Friede sei mit dir! Es grüßen dich die Freunde. Grüße die Freunde, jeden mit Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Judas, ein Knecht von Jesus Christus');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Barmherzigkeit und Friede und Liebe werde euch in vollem Maße zuteil!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Geliebte, indem ich allen Fleiß tat, euch von dem gemeinschaftlichen Heile zu schreiben, hielt ich es für nötig, euch mit solcher Schrift zu ermahnen, daß ihr für den den Geheiligten verliehenen Glauben kämpft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Denn es sind etliche Menschen eingeschlichen, die vor Zeiten schon bezeichnet sind für dieses Gericht, Gottlose, welche die Gnade unseres Gottes zur Zielscheibe des Mutwillens machen und den alleinigen Herrscher, Gott und unseren Herrn Jesus Christus, verleugnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Ich will euch aber erinnern an das, was ihr selbst schon wißt, daß der Herr einmal das Volk aus Ägyptenland gerettet, zum anderen Mal aber, die da nicht glaubten, vertilgt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'Und Engel, die ihren ersten Stand nicht behaupteten, sondern ihre Behausung verließen, zum Gericht des großes Tages in ewigen Banden in Finsternis behalten hat;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Wie auch Sodom und Gomorrah und die umliegenden Städte, die gleicherweise wie diese Unzucht getrieben, und unnatürlicher Wollust nachgegangen waren, als');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Gleicherweise ergeht es denn auch denen, die in ihrem Lusttaumel das Fleisch beflecken, keine Herrschergewalt anerkennen und das Herrliche lästern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Der Erzengel Michael aber, der mit dem Teufel über den Leib des Moses rechtete und stritt, wagte nicht das Urteil der Lästerung zu fällen, sondern sprach: Der Herr richte dich!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Diese aber lästern in Dingen, die sie nicht kennen; was sie aber auf sinnliche Weise wie die unvernünftigen Tiere natürlich erkennen, dadurch bereiten sie sich Verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Wehe ihnen, daß sie auf dem Wege Kains wandelten und in den Irrtum Balaams des Lohnes wegen gerieten und in dem Aufruhr Korachs umkamen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Diese sind bei euren Liebesmahlen Klippen; sie schmausen mit euch ohne Scheu, tun sich gütlich, sind Wolken ohne Wasser, von Winden umgetrieben, Bäume, die keine Frucht getragen, keine tragen können, zweimal gestorben, ausgewurzelt,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'Wilde Meereswellen, die ihre eigene Schande ausschäumen, Irrsterne, denen das Dunkel der Finsternis in Ewigkeit aufbehalten ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Es hat solchen auch Enoch, der siebente von Adam, geweissagt, wenn er spricht: Siehe, der Herr kommt mit viel tausend Heiligen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'Gericht zu halten über alle, und zur Strafe zu ziehen alle Gottlosen unter ihnen für alle Werke ihrer Gottlosigkeit, die sie verübt, und für alle die harten Reden, welche gottlose Sünder wider Ihn ausgestoßen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Diese murren und klagen immer und leben nach ihren Lüsten, und ihr Mund ist voll hoher Dinge, während sie des eigenen Vorteils wegen den Leuten ins Angesicht schön tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Ihr aber, Geliebte, seid eingedenk der Worte, welche die Apostel unseres Herrn Jesus Christus zu euch gesprochen haben,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'Wenn sie euch sagten, daß in der letzten Zeit Spötter auftreten werden, die nach den Lüsten ihrer Gottlosigkeiten wandeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Diese sind es, die da Trennungen machen, sinnliche Leute, die den Geist nicht haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Ihr aber, Geliebte, erbaut euch in eurem hochheiligen Glauben durch den Heiligen Geist und betet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'Erhaltet euch in der Liebe Gottes, und seid gewärtig der Barmherzigkeit unseres Herrn Jesus Christus zum ewigen Leben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'Und die einen behandelt milde, indem ihr einen Unterschied macht;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'Die anderen rettet, indem ihr sie durch Furcht aus dem Feuer emporrafft, und auch das von dem Fleisch befleckte Kleid haßt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Ihm aber, Der euch kann behüten vor dem Fall und stellen vor Seine Herrlichkeit unsträflich mit Frohlocken,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'Dem allein weisen Gott, unserem Heilande, sei Herrlichkeit und Majestät, Macht und Gewalt, nun und in alle Ewigkeiten! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Die Offenbarung von Jesus Christus, welche Gott Ihm gab, Seinen Knechten zu zeigen, was in Bälde geschehen soll, und Er deutete es, da Er durch Seinen Engel an Seinen Knecht Johannes entsandte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'Welcher bezeugte das Wort Gottes und das Zeugnis von Jesus Christus, was er alles gesehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Selig, wer da liest, und die da hören die Worte der Weissagung, und was in ihr geschrieben ist, halten; denn die Zeit ist nahe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Johannes an die sieben Gemeinden in Asien: Gnade sei euch und Friede von Ihm, Der da ist, und Der da war, und Der da kommt, und von den sieben Geistern, die vor Seinem Throne sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'Und von Jesus Christus, Der da ist der treue Zeuge, der Erstgeborene aus den Toten und der Oberste der Könige der Erde, Der uns liebt und uns in Seinem Blute von unseren Sünden gewaschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'Und uns zu Königen und zu Priestern Gott und Seinem Vater gemacht. Ihm sei die Herrlichkeit und Macht in die Zeitläufe der Zeitläufe! Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Siehe, Er kommt mit den Wolken und sehen wird Ihn jegliches Auge, auch die Ihn durchstochen haben, und jammern werden ob Ihm alle Stämme der Erde. Ja, Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Ich bin das Alpha und das Omega, der Anfang und das Ende, spricht der Herr, Der da ist, und Der da war, und Der da kommt, der Allmächtige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Ich, Johannes, der auch euer Bruder und Teilhaber an der Trübsal und am Reich und an der geduldigen Erwartung von Jesus Christus ist, war auf der Insel, die Patmos heißt, um des Wortes Gottes willen, und des Zeugnisses von Jesus Christus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Ich war im Geist am Tage des Herrn, und hörte hinter mir eine große Stimme, als eine Posaune.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'Die sprach: Ich bin das Alpha und das Omega, der Erste und der Letzte, und was Du siehst, schreibe in ein Buch und sende es den Gemeinden in Asien gen Ephesus und gen Smyrna und gen Pergamus und gen Thyatira und gen Sardes und gen Philadelphia und gen Laodikia.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'Und ich wandte mich um, zu sehen die Stimme, die mit mir redete, und da ich mich umwandte, sah ich sieben goldene Leuchter,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'Und inmitten der sieben Leuchter Einen, Der dem Menschensohne ähnlich war, mit einem Talar angetan, und um die Brust mit einem goldenen Gürtel umgürtet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Sein Haupt aber und die Haare weiß, wie weiße Wolle, wie Schnee, und Seine Augen wie eine Feuerflamme,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'Und Seine Füße ähnlich dem Glüherz, wie im Ofen geglüht, und Seine Stimme, wie die Stimme vieler Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'Und Er hatte in Seiner rechten Hand sieben Sterne, und aus Seinem Munde ging aus ein scharfes, zweischneidiges Schwert, und Sein Angesicht, wie die Sonne leuchtet in ihrer Kraft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'Und da ich Ihn sah, fiel ich wie tot zu Seinen Füßen; und Er legte Seine rechte Hand auf mich und sprach zu mir: Fürchte dich nicht. Ich bin der Erste und der Letzte,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'Und der Lebendige. Und Ich ward tot und siehe, Ich bin lebendig in die Zeitläufe der Zeitläufe. Amen. Und Ich habe die Schlüssel der Hölle und des Todes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Schreibe, was du gesehen hast, und was da ist, und was zukünftig nach diesem geschehen wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'Das Geheimnis der sieben Sterne, die du in Meiner Rechten sahst, und die sieben goldenen Leuchter: Die sieben Sterne sind Engel der sieben Gemeinden und die sieben Leuchter, die du gesehen hast, sind die sieben Gemeinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Dem Engel der Gemeinde in Ephesus schreibe: Das sagt, Der die sieben Sterne in Seiner Rechten festhält und in der Mitte der sieben goldenen Leuchter wandelt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Ich kenne deine Werke und dein Mühen und deine Geduld, und daß du die Bösen nicht tragen kannst und daß du hast geprüft die, so da sagen, sie seien Apostel, und es nicht sind, und hast sie als Lügner erfunden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'Und hast getragen und hast Geduld und hast um Meines Namens willen dich abgemüht und bist nicht müde geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Aber Ich habe wider dich, daß du deine erste Liebe verlassen hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Bedenke denn, wovon du abgefallen bist; und tue Buße und tue die ersten Werke; wo aber nicht, so komme Ich schnell über dich und rücke deinen Leuchter von seinem Ort, wenn du nicht Buße tust.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Doch hast du dies, daß du die Werke der Nikolaiten hassest, welche auch Ich hasse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt: Dem Überwinder will Ich zu essen geben vom Baume des Lebens, der in der Mitte des Paradieses Gottes ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'Und dem Engel der Gemeinde in Smyrna schreibe: Das sagt der Erste und der Letzte, Der tot ward und lebt:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Ich weiß deine Werke und die Trübsal und die Armut und die Lästerung derer, die da sagen, sie seien Juden, und sind keine, sondern eine Synagoge des Satans.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Fürchte dich vor deren keinem, das du leiden wirst. Siehe, der Teufel wird etliche von euch ins Gefängnis werfen, auf daß ihr versucht werdet; und ihr werdet Trübsal haben zehn Tage. Sei getreu bis zum Tod, und Ich will dir die Krone des Lebens geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Wer ein Ohr hat, der höre, was der Geist zu den Gemeinden sagt: Der Überwinder soll nicht geschädigt werden vom zweiten Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'Und dem Engel der Gemeinde in Pergamus schreibe: Das sagt, Der das scharfe, zweischneidige Schwert hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Ich weiß deine Werke, und wo du wohnst, wo des Satans Thron ist; und du hältst fest an Meinem Namen und hast nicht verleugnet den Glauben an Mich auch in den Tagen, wo Antipas, Mein treuer Zeuge, bei euch, da Satan wohnt, getötet worden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Aber Ich habe einiges wider dich: daß du daselbst hast, die an der Lehre Bileams festhalten, der den Balak lehrte, vor die Söhne Israels ein Ärgernis zu legen, daß sie Götzenopfer aßen und Buhlerei trieben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'So hast auch du solche, die an der Lehre der Nikolaiten festhalten, was Ich hasse.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Tue Buße, sonst aber komme Ich schnell zu dir, und streite wider sie mit dem Schwert Meines Mundes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt: Dem Überwinder will Ich von dem verborgenen Manna zu essen geben und will ihm einen weißen Stein geben, und auf dem Stein einen neuen Namen geschrieben, den niemand erkennt, als der ihn empfängt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'Und dem Engel der Gemeinde in Thyatira schreibe: Das sagt der Sohn Gottes, Der Augen hat wie eine Feuerflamme, und Füße ähnlich dem Glüherz.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Ich weiß deine Werke, und deine Liebe, und deine Dienstleistung, und deinen Glauben, und deine Geduld, und deine Werke, und daß der letzten mehr sind als der ersten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Aber Ich habe einiges wider dich, daß du das Weib Jesabel, die da sagt, sie sei eine Prophetin, Meine Knechte lehren und zur Buhlerei und zum Essen von Götzenopfern irreführen lässest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'Und Ich habe ihr Zeit gegeben, für ihre Buhlerei Buße zu tun, und sie hat nicht Buße getan.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Siehe, Ich werfe sie in ein Bett, und in große Trübsal, die mit ihr die Ehe brechen, wenn sie nicht Buße tun von ihren Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'Und ihre Kinder will Ich mit dem Tode töten; und erkennen sollen alle Gemeinden, daß Ich es bin, Der Nieren und Herzen erforscht, und einem jeden von euch nach euren Werken geben werde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Euch aber sage Ich und den übrigen in Thyatira, so viele als diese Lehre nicht haben, und welche die Tiefen des Satanas, wie sie es nennen, nicht erkannt haben, Ich will keine andere Last auf euch werfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Doch was ihr habt, an dem haltet fest, bis daß Ich komme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'Wer überwindet und hält Meine Werke bis ans Ende, dem will Ich Gewalt über die Völkerschaften geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'Und mit eisernem Stabe soll er sie weiden, und wie Töpfergeschirr sollen sie zerschlagen werden,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'Wie auch Ich von Meinem Vater empfangen habe; und Ich werde ihm geben den Morgenstern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'Und dem Engel der Gemeinde in Sardes schreibe: Das sagt, Der die sieben Geister Gottes und die sieben Sterne hat: Ich weiß deine Werke, daß du den Namen hast, daß du lebst, und bist tot.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Sei wachsam und mache fest, was übrig ist und sterben will; denn Ich habe deine Werke nicht voll gefunden vor Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Gedenke denn, wie du es empfangen und gehört hast, und halte es und tue Buße. Wenn du nun nicht wachest, so werde Ich über dich kommen, wie ein Dieb, und du wirst nicht erkennen, zu welcher Stunde Ich werde über dich kommen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Du hast auch in Sardes wenige Namen, die ihre Kleider nicht befleckten, und sie werden in weißen Kleidern mit Mir wandeln, weil sie es wert sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Wer überwindet, soll mit weißen Kleidern umkleidet werden; und Ich werde seinen Namen nicht auswischen aus dem Buche des Lebens, und werde seinen Namen bekennen vor Meinem Vater und vor Seinen Engeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'Und dem Engel der Gemeinde in Philadelphia schreibe: Das sagt der Heilige, der Wahrhaftige, Der den Schlüssel Davids hat, Der auftut, und niemand verschließt, und verschließt, und niemand tut auf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Ich weiß deine Werke. Siehe, Ich habe vor dir eine geöffnete Tür gegeben, und niemand kann sie verschließen, weil du eine kleine Kraft hast, und hast Mein Wort gehalten und Meinen Namen nicht verleugnet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Siehe, Ich will aus Satans Synagoge geben, die sagen, sie seien Juden, und sind es nicht, sondern lügen. Siehe, Ich will machen, daß sie kommen und vor deinen Füßen anbeten und erkennen, daß Ich dich geliebt habe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Weil du das Wort Meiner Geduld behalten hast, will auch Ich dich behalten vor der Stunde der Versuchung, die über den ganzen Erdkreis kommen wird, zu versuchen, die auf Erden wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Siehe, Ich komme schnell. Halte fest, was du hast, auf daß niemand deine Krone nehme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Den Überwinder will Ich zur Säule in Meines Gottes Tempel machen, und er soll nicht mehr hinausgehen, und Ich will auf ihn schreiben den Namen Meines Gottes und den Namen der Stadt Meines Gottes, des neuen Jerusalem, das aus dem Himmel von Meinem Gotte herabsteigt, und Meinen neuen Namen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'Und dem Engel der Gemeinde in Laodikia schreibe: Das sagt der Amen, der treue und wahrhaftige Zeuge, der Anfang der Schöpfung Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Ich weiß deine Werke, daß du weder kalt noch warm bist. Wärest du doch kalt oder warm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'So aber, da du lau bist, und weder kalt noch warm, will Ich dich ausspeien aus Meinem Munde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Daß du sagst: Ich bin reich, und bin reich geworden, und bedarf nichts, und du weißt nicht, daß du elend und jämmerlich und arm und blind und nackend bist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'Ich rate dir, kaufe von Mir Gold, durch Feuer geläutert, auf daß du reich werdest, und weiße Kleider, auf daß du umkleidest werdest, und die Schande deiner Blöße nicht offenbar werde, und Augensalbe, deine Augen damit einzusalben, auf daß du sehen mögest.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Wen Ich lieb habe, den rüge und züchtige Ich. Beeifre dich denn und tue Buße.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Siehe, Ich stehe an der Tür und klopfe an. So jemand Meine Stimme hört und die Tür auftut, zu dem gehe Ich ein und halte Abendmahl mit ihm und er mit Mir.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Dem Überwinder will Ich geben, auf Meinem Thron mit Mir zu sitzen, wie Ich überwunden und mit Meinem Vater auf Seinem Thron gesessen bin.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Wer ein Ohr hat, der höre, was der Geist den Gemeinden sagt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Danach sah ich, und siehe, eine Tür hatte sich im Himmel aufgetan. Und die erste Stimme, die ich wie eine Posaune mit mir reden hörte, sagte: Steige hier herauf, und ich will dir zeigen, was nach diesem geschehen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Und alsbald war ich im Geiste; und siehe! ein Thron war gestellt im Himmel, und auf dem Throne saß Einer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'Und Der da saß, war ähnlich im Ansehen wie der Stein Jaspis und Sarder, und rings um den Thron ein Farbenbogen, ähnlich einem Smaragd im Ansehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'Und rings um den Thron vierundzwanzig Throne; und auf den Thronen sah ich sitzen die vierundzwanzig Ältesten; diese waren umkleidet mit weißen Kleidern und hatten goldene Kronen auf ihren Häuptern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'Und aus dem Thron gehen Blitze und Stimmen und Donner aus, und vor dem Throne brennen sieben Fackeln von Feuer, welche die sieben Geister Gottes sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'Und vor dem Throne ein gläsern Meer, ähnlich dem Kristall. Und inmitten des Throns und rings um den Thron vier Tiere voller Augen vorn und hinten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'Und das erste Tier glich einem Löwen, und das zweite Tier glich einem Kalb, und das dritte Tier hatte das Angesicht wie ein Mensch, und das vierte Tier glich einem fliegenden Adler.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'Und die vier Tiere hatten, jedes für sich, je sechs Flügel ringsum, und waren innen voller Augen und hatten keine Ruhe Tag und Nacht, und sagten: Heilig, heilig, heilig ist der Herr, Gott, der Allmächtige, Der da war und Der da ist und Der da kommt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'Und da die Tiere Herrlichkeit und Ehre und Danksagung gaben Dem, Der auf dem Throne sitzt, Der da lebt in die Zeitläufe der Zeitläufe,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'Fielen die vierundzwanzig Ältesten vor dem auf dem Throne Sitzenden nieder und beteten an Ihn, Der in die Zeitläufe der Zeitläufe lebt, und warfen ihre Kronen vor den Thron und sprachen:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Herr, Du bist würdig, zu nehmen die Herrlichkeit und die Ehre und die Kraft, denn Du hast alle Dinge geschaffen, und durch Deinen Willen sind sie und wurden sie geschaffen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'Und ich sah in der Rechten Dessen, Der auf dem Throne saß, ein Buch, inwendig und auswendig beschrieben, versiegelt mit sieben Siegeln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'Und ich sah einen starken Engel mit großer Stimme ausrufen: Wer ist würdig, das Buch aufzutun und seine Siegel zu lösen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'Und niemand im Himmel, noch auf Erden, noch unter der Erde konnte das Buch auftun und hineinsehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'Und ich weinte sehr, daß niemand würdig gefunden wurde, das Buch aufzutun und zu lesen, noch hineinzusehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'Und einer von den Ältesten sprach zu mir: Weine nicht! Siehe, der Löwe, der da ist aus dem Stamme Juda, die Wurzel Davids, hat überwunden, das Buch aufzutun und seine sieben Siegel zu lösen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'Und ich sah, und siehe, inmitten des Throns und der vier Tiere und inmitten der Ältesten stand ein Lamm, als wäre es erschlagen, das hatte sieben Hörner und sieben Augen, welche sind die sieben Geister Gottes, ausgesandt in die ganze Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'Und es kam und nahm das Buch aus der Rechten Dessen, Der auf dem Throne saß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'Und da es das Buch nahm, fielen die vier Tiere und die vierundzwanzig Ältesten vor das Lamm. Sie hatten jeder Harfen und goldene Schalen voll Räucherwerks, welches sind die Gebete der Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'Und singen ein neues Lied und sagen: Du bist würdig, das Buch zu nehmen und seine Siegel aufzutun; denn du wardst erschlagen und hast uns für Gott erkauft mit Deinem Blute aus allerlei Stamm und Zunge und Volk und Völkerschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'Und uns unsrem Gotte zu Königen und Priestern gemacht, und regieren werden wir auf Erden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'Und ich sah, und hörte die Stimme vieler Engel rings um den Thron und die Tiere und die Ältesten, und ihre Zahl war Myriaden von Myriaden und Tausende von Tausenden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'Und sie sagten mit großer Stimme: Würdig ist das Lamm, das erschlagene, zu nehmen die Kraft und Reichtum und Weisheit und Stärke und Ehre und Herrlichkeit und Segen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'Und alles Geschaffene, das da ist im Himmel und auf Erden und unter der Erde, und die im Meere sind, und alles, was in denselben ist, hörte ich sagen: Dem, Der auf dem Throne sitzt und dem Lamme sei der Segen und die Ehre und die Herrlichkeit und die Macht in die Zeitläufe der Zeitläufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'Und die vier Tiere sprachen: Amen! Und die vierundzwanzig Ältesten fielen nieder und beteten an Ihn, Der da lebt in die Zeitläufe der Zeitläufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'Und ich sah, wie das Lamm das erste der Siegel auftat, und hörte eines von den Tieren wie mit des Donners Stimme sagen: Komm und siehe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'Und ich sah, und siehe! ein weißes Pferd, und der darauf saß, hatte einen Bogen, und ihm ward eine Krone gegeben, und er zog aus als Überwinder, und um zu überwinden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'Und da es das zweite Siegel auftat, hörte ich das zweite Tier sagen: Komm und siehe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'Und es ging ein anderes, feuerrotes Pferd hervor, und dem darauf Sitzenden ward gegeben, den Frieden von der Erde zu nehmen, daß sie einander erschlugen; und es ward ihm ein großes Schwert gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'Und da es das dritte Siegel auftat, hörte ich das dritte Tier sagen: Komm und siehe! Und ich sah, und siehe! ein schwarzes Pferd, und der darauf saß, hatte eine Waage in seiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'Und ich hörte eine Stimme inmitten der vier Tiere sagen: Ein Maß Weizen um einen Denar und drei Maß Gerste um einen Denar. Und das Öl und den Wein sollst du nicht schädigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'Und da es das vierte Siegel auftat, hörte ich die Stimme des vierten Tieres sagen: Komm und siehe!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'Und ich sah, und siehe! ein fahles Pferd, und der Name dessen, der darauf saß, war der Tod, und die Hölle folgte mit ihm nach. Und ihm ward Gewalt gegeben über den vierten Teil der Erde, zu töten durch das Schwert und durch Hunger und durch Tod und durch die wilden Tiere der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'Und als es das fünfte Siegel auftat, sah ich unterhalb des Altars die Seelen derer, die um des Wortes Gottes und um des Zeugnisses willen, das sie hatten, erschlagen wurden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'Und sie schrien mit großer Stimme und sagten: Wie lange, o Herr, Du Heiliger und Wahrhaftiger, richtest Du nicht und rächst unser Blut an den Bewohnern der Erde?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'Und es ward ihnen, einem jeglichen, weißes Gewand gegeben und ihnen gesagt, sie sollten noch eine kleine Zeit ruhen, bis auch vollzählig würden ihre Mitknechte, und ihre Brüder, die auch wie sie sollten getötet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'Und ich sah, da es das sechste Siegel auftat, und siehe! da ward ein großes Erdbeben, und die Sonne ward schwarz, wie ein härener Sack, und der Mond ward wie Blut,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'Und die Sterne des Himmels fielen auf die Erde, wie der Feigenbaum seine unreifen Feigen abwirft, wenn er von einem großen Winde geschüttelt wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'Und der Himmel entwich wie ein zusammengerolltes Buch, und jeder Berg und Insel wurden von ihren Orten gerückt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'Und die Könige der Erde und die Großen und die Reichen und die Kriegsobersten, und die Mächtigen, und jeder Knecht, und jeder Freie verbargen sich in die Höhlen und in die Felsen der Berge;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'Und sprachen zu den Bergen und den Felsen: Fallet über uns, und verberget uns vor dem Angesichte Dessen, Der auf dem Throne sitzt, und vor dem Zorne des Lammes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'Denn gekommen ist der große Tag Seines Zornes. Und wer kann bestehen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'Und hierauf sah ich vier Engel auf den vier Ecken der Erde stehen, welche die vier Winde der Erde festhielten, auf daß kein Wind bliese über das Land oder über das Meer oder über irgendeinen Baum.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'Und ich sah einen anderen Engel vom Aufgang der Sonne aufsteigen, der das Siegel des lebendigen Gottes hatte. Und er schrie mit großer Stimme den vier Engeln, denen gegeben war, das Land und das Meer zu schädigen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'Und er sprach: Schädigt nicht das Land, noch das Meer, noch die Bäume, bis wir die Knechte unseres Gottes auf ihren Stirnen besiegelt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'Und ich hörte die Zahl der Besiegelten: Hundertvierundvierzigtausend Besiegelte aus jedem Stamme der Söhne Israels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Aus dem Stamme Judah zwölftausend Besiegelte; aus dem Stamme Ruben zwölftausend Besiegelte; aus dem Stamme Gad zwölftausend Besiegelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'Aus dem Stamme Ascher zwölftausend Besiegelte; aus dem Stamme Naphthali zwölftausend Besiegelte; aus dem Stamme Menascheh zwölftausend Besiegelte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'Aus dem Stamme Simeon zwölftausend Besiegelte; aus dem Stamme Levi zwölftausend Besiegelte; aus dem Stamme Isaschar zwölftausend Besiegelte;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'Aus dem Stamme Sebulon zwölftausend Besiegelte; aus dem Stamme Joseph zwölftausend Besiegelte; aus dem Stamme Benjamin zwölftausend Besiegelte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Nach diesem sah ich, und siehe! eine große Menge, die niemand zählen konnte, aus allen Völkerschaften und Stämmen, und Völkern und Zungen vor dem Thron und vor dem Lamme stehen, mit weißen Gewändern umkleidet und Palmen in ihren Händen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'Und sie schrien mit großer Stimme und sprachen: Heil unserem Gott, Der da sitzt auf dem Thron, und dem Lamme!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'Und alle Engel standen rings um den Thron und die Ältesten und die vier Tiere und fielen vor dem Throne auf ihr Angesicht und beteten Gott an,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'Und sprachen: Amen, der Segen und die Herrlichkeit, und die Weisheit, und die Danksagung, und die Ehre, und die Kraft und die Stärke sei unserem Gott in die Zeitläufe der Zeitläufe. Amen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'Und einer von den Ältesten antwortete und sprach zu mir: Wer sind die, so mit weißen Gewändern umkleidet sind, und woher sind sie gekommen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'Und ich sprach zu ihm: Herr, du weißt es. Und er sprach zu mir: Die sind es, die aus der großen Trübsal kommen, und die ihre Gewänder ausgewaschen und ihre Gewänder im Blute des Lammes weiß gemacht haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Darum sind sie vor dem Throne Gottes und dienen Ihm Tag und Nacht in Seinem Tempel, und Der auf dem Throne sitzt, wird über ihnen wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Nicht mehr werden sie hungern, noch mehr dürsten, noch wird auf sie die Sonne, noch irgendeine Hitze fallen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'Denn das Lamm, das inmitten des Thrones ist, wird sie weiden, und zu lebendigen Quellen der Wasser leiten; und Gott wird alle Tränen von ihren Augen abwischen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'Und als es das siebente Siegel auftat, ward im Himmel eine Stille bei einer halben Stunde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'Und ich sah die sieben Engel, die vor Gott stehen, und es wurden ihnen sieben Posaunen gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'Und ein anderer Engel kam und stellte sich an den Altar und hatte ein goldenes Räucherfaß. Und ihm wurde viel Räuchwerk gegeben, um es zu geben mit den Gebeten aller Heiligen auf dem goldenen Altar vor dem Throne.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'Und es stieg auf der Rauch des Räuchwerks mit den Gebeten der Heiligen aus der Hand des Engels vor Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'Und der Engel nahm das Räuchfaß und füllte es aus dem Feuer des Altars und warf es auf die Erde; und es geschahen Stimmen und Donner und Blitze und Erdbeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'Und die sieben Engel, welche die sieben Posaunen hatten, bereiteten sich zu posaunen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'Und der erste Engel posaunte, und es ward Hagel und Feuer mit Blut vermischt und wurde geworfen auf die Erde, und der dritte Teil der Bäume verbrannte, und alles grüne Gras verbrannte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'Und der zweite Engel posaunte, und es war, als würde ein großer Berg mit Feuer brennend ins Meer geworfen, und der dritte Teil des Meeres ward Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'Und der dritte Teil der Geschöpfe im Meer, die Seelen hatten, starb, und der dritte Teil der Schiffe wurde verdorben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'Und der dritte Engel posaunte, und es fiel ein großer Stern aus dem Himmel, brennend wie eine Fackel, und er fiel auf den dritten Teil der Flüsse und auf die Quellen der Wasser.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'Und der Name des Sterns heißt Wermut, und der dritte Teil der Wasser ward Wermut, und viele Menschen starben von den Wassern, denn sie waren bitter geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'Und der vierte Engel posaunte, und geschlagen ward der dritte Teil der Sonne, und der dritte Teil des Mondes, und der dritte Teil der Sterne, so daß der dritte Teil derselben verfinstert ward, und der Tag sein drittes Teil nicht schien, und die Nacht desgleichen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'Und ich sah und hörte mitten am Himmel einen Engel fliegen und mit großer Stimme sagen: Wehe, wehe, wehe denen, die auf Erden wohnen, wegen der übrigen Stimmen der Posaunen der drei Engel, die posaunen werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'Und der fünfte Engel posaunte, und ich sah einen Stern aus dem Himmel zur Erde fallen, und es ward ihm der Schlüssel des Brunnens des Abgrundes gegeben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'Und er tat den Brunnen des Abgrundes auf; und ein Rauch stieg auf aus dem Brunnen, wie der Rauch eines großen Ofens, und die Sonne und die Luft wurden verfinstert von dem Rauche des Brunnens.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'Und aus dem Rauche kamen Heuschrekken hervor auf die Erde, und es ward ihnen Gewalt gegeben, wie die Skorpione der Erde Gewalt haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'Und es ward ihnen gesagt, daß sie nicht sollten schädigen das Gras der Erde, noch irgend etwas Grünes, noch irgendwelchen Baum, sondern bloß die Menschen, die das Siegel Gottes nicht auf ihren Stirnen haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'Und es ward ihnen gegeben, daß sie sie nicht töteten, sondern sie fünf Monate quälten, und die Qual war wie die Qual vom Skorpion, wenn er einen Menschen sticht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'Und in jenen Tagen werden die Menschen den Tod suchen und ihn nicht finden; und zu sterben begehren, und der Tod wird vor ihnen fliehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'Und die Gestalten der Heuschrecken glichen zum Streit bereiteten Rossen, und auf ihren Häuptern hatten sie Kronen, dem Golde gleichend, und ihre Angesichter wie der Menschen Angesichter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'Und sie hatten Haare wie der Weiber Haare, und ihre Zähne waren wie der Löwen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'Und hatten Panzer, wie eiserne Panzer, und das Rauschen ihrer Flügel war wie das Rasseln von Streitwagen vieler Rosse, die in den Streit rennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'Und Schwänze haben sie gleich den Skorpionen, und Stacheln waren an ihren Schwänzen, und hatten Gewalt, die Menschen fünf Monate zu schädigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'Und hatten über sich einen König, den Engel des Abgrundes, dessen Namen im Hebräischen ist Abaddon, und im Griechischen hat er den Namen Apollyon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Das eine Wehe ist vergangen. Siehe, es kommen noch zwei Wehe danach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'Und der sechste Engel posaunte; und ich hörte eine Stimme aus den vier Hörnern des goldenen Altars vor Gott,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'Die sagte zu dem sechsten Engel, der die Posaune hatte: Löse die vier Engel, die an dem großen Fluß Euphrat gebunden sind!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'Und die vier Engel wurden gelöst, welche auf Stunde und Tag und Monat und Jahr bereit waren, den dritten Teil der Men- schen zu töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'Und die Zahl der Heerscharen der Reiterei waren zwei Myriaden von Myriaden. Und ich hörte ihre Zahl.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'Und so sah ich die Rosse im Gesichte; und die auf ihnen saßen, hatten feuerrote, purpurblaue und schwefelfarbige Panzer; und die Häupter der Rosse waren wie der Löwen Häupter; und aus ihrem Munde ging aus Feuer, Rauch und Schwefel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Und durch diese drei wurde das Drittel der Menschen getötet; durch das Feuer und durch den Rauch und durch den Schwefel, so aus ihrem Munde ausging.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Denn ihre Gewalt ist in ihrem Munde. Denn ihre Schwänze sind gleich Schlangen und haben Häupter; und mit diesen schädigen sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'Und die übrigen von den Menschen, die durch diese Plagen nicht getötet wurden, noch Buße taten für die Werke ihrer Hände, so daß sie nicht anbeteten die Dämonen, und die goldenen und die silbernen, und die ehernen und die steinernen und die hölzernen Götzen, die weder sehen, noch hören, noch wandeln können.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'Und taten nicht Buße für ihre Morde, noch für ihre Zaubereien, noch für ihre Buhlerei, noch für ihre Diebereien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'Und ich sah einen anderen starken Engel aus dem Himmel herabsteigen, mit einer Wolke umkleidet, und ein Farbenbogen über seinem Haupt, und sein Angesicht wie die Sonne, und seine Füße wie Feuersäulen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'Und in seiner Hand hatte er ein Büchlein aufgetan und setzte seinen rechten Fuß auf das Meer, den linken aber auf das Land.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'Und er schrie mit großer Stimme, wie ein Löwe brüllt. Und da er schrie, redeten die sieben Donner ihre Stimmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'Und als die sieben Donner ihre Stimme geredet hatten, wollte ich schreiben; und ich hörte eine Stimme aus dem Himmel zu mir sagen: Versiegle, was die sieben Donner geredet haben, und schreibe dasselbige nicht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'Und der Engel, den ich auf dem Meere und auf dem Lande stehen sah, hob auf seine Hand gen Himmel,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'Und schwur bei Dem, Der da lebt in die Zeitläufe der Zeitläufe, Der den Himmel und was darinnen ist, und die Erde und was darin ist, und das Meer und was darin ist, geschaffen hat, daß keine Zeit mehr sein soll;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'Sondern in den Tagen der Stimme des siebenten Engels, wann er posaunen wird, wird auch vollendet sein das Geheimnis Gottes, wie Er Seinen Knechten, den Propheten, verkündigt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'Und die Stimme, die ich aus dem Himmel gehört, redete abermals mit mir und sprach: Gehe hin, nimm das Büchlein, aufgetan in der Hand des Engels, der auf dem Meer und auf dem Lande steht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'Und ich ging hin zu dem Engel und sagte zu ihm: Gib mir das Büchlein, und er spricht zu mir: Nimm, iß es auf. Und deinen Leib wird es bitter machen, aber in deinem Munde süß sein wie Honig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'Und ich nahm das Büchlein aus der Hand des Engels und aß es auf; und in meinem Munde war es süß, wie Honig; und da ich es gegessen hatte, ward mein Leib bitter.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'Und er spricht zu mir: Du mußt abermals weissagen über Völker und Völkerschaften und Zungen und viele Könige.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'Und mir ward ein Rohr gegeben gleich einem Stabe, und gesagt: Mache dich auf, und miß den Tempel Gottes und den Altar und die darin anbeten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'Und den Vorhof, der außerhalb des Tempels ist, wirf hinaus und miß ihn nicht, weil er den Heiden gegeben ist; und sie werden die heilige Stadt zertreten zweiundvierzig Monate.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'Und Meinen zwei Zeugen will Ich es geben, daß sie, mit Säcken umkleidet, tausendzweihundertsechzig Tage weissagen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'Dies sind die zwei Ölbäume und die zwei Leuchter, die vor dem Gott der Erde stehen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'Und wenn einer sie will schädigen, so geht Feuer aus ihrem Munde aus und verzehrt ihre Feinde; und wenn jemand sie will schädigen, so muß er also getötet werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Diese haben Gewalt, den Himmel zu verschließen, daß in den Tagen ihrer Weissagung der Schauer nicht regne; und haben Gewalt über die Wasser, sie in Blut umzuwandeln, und die Erde zu schlagen mit allerlei Plage, so oft sie nur wollen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'Und wenn sie ihr Zeugnis vollendet haben, wird das Tier, das aus dem Abgrund aufsteigt, Krieg mit ihnen führen und sie überwinden und sie töten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'Und ihre Leichen werden sein auf der Straße der großen Stadt, die geistig Sodom und Ägypten heißt, wo auch unser Herr gekreuzigt worden ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'Und von den Völkern und Stämmen und Zungen und Völkerschaften werden welche deren Leichen drei und einen halben Tag sehen, und werden ihre Leichen nicht in die Grüfte legen lassen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'Und die auf Erden wohnen, werden sich über sie freuen und fröhlich sein und einander Geschenke schicken, weil diese zwei Propheten quälten, die auf Erden wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'Und nach den drei und einen halben Tag kam der Geist des Lebens aus Gott in sie hinein, und sie standen auf ihre Füße, und große Furcht fiel auf die, so es schauten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'Und sie hörten eine große Stimme aus dem Himmel ihnen sagen: Steiget hier herauf. Und sie stiegen auf in den Himmel in der Wolke, und ihre Feinde schauten sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'Und zur selben Stunde ward ein großes Erdbeben, und der zehnte Teil der Stadt fiel, und wurden getötet in dem Erdbeben Namen von Menschen siebentausend. Und die übrigen gerieten in Furcht und gaben Herrlichkeit dem Gott des Himmels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Das zweite Wehe ist vergangen. Siehe, das dritte Wehe kommt schnell.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'Und der siebente Engel posaunte, und es wurden große Stimmen im Himmel, die sprachen: Die Reiche der Welt sind unseres Herrn und seines Christus geworden, und Er wird regieren in die Zeitläufe der Zeitläufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'Und die vierundzwanzig Ältesten, die vor Gott auf ihren Thronen saßen, fielen auf ihre Angesichte und beteten Gott an,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Und sagten: Wir danken Dir, Herr, Gott, Allmächtiger, Der da ist, und Der da war, und Der da kommt, daß Du Deine große Kraft an Dich genommen und Dein Reich angetreten hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'Und die Völkerschaften zürnten, und gekommen ist Dein Zorn und die Zeit der Toten, zu richten und den Lohn zu geben Deinen Knechten, den Prophe- ten und den Heiligen, und denen, die Deinen Namen fürchten, den Kleinen und den Großen und zu verderben, welche die Erde verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'Und der Tempel Gottes ward aufgetan im Himmel, und ward gesehen Seine Bundeslade in Seinem Tempel; und es geschahen Blitze und Stimmen und Donner und Erdbeben und großer Hagel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'Und ein großes Zeichen erschien am Himmel: ein Weib, von der Sonne umkleidet, und der Mond unter ihren Füßen, und auf ihrem Haupte eine Krone von zwölf Sternen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'Und sie war schwanger, schrie in Wehen und quälte sich, zu gebären.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'Und ein anderes Zeichen ward im Himmel gesehen, und siehe, ein großer, feuerroter Drache, der hatte sieben Häupter und zehn Hörner und auf seinen Häuptern sieben Diademe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'Und sein Schwanz zog den dritten Teil der Sterne des Himmels nach sich und warf sie auf die Erde. Und der Drache stand vor dem Weib, da sie gebären wollte, um ihr Kind, wenn sie geboren hätte, aufzufressen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'Und sie gebar ein Männliches, einen Sohn, der alle die Völkerschaften mit eisernem Stabe weiden sollte; und ihr Kind ward entrückt zu Gott und Seinem Thron.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'Und das Weib floh in die Wüste, wo sie einen Ort hat, der von Gott bereitet worden, auf daß man sie allda tausendzweihundertsechzig Tage ernährete.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'Und es ward Krieg in dem Himmel; Michael und seine Engel führten Krieg mit dem Drachen, und der Drache führte Krieg und seine Engel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'Und sie vermochten es nicht, und ward ihre Stätte im Himmel nicht mehr gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'Und der große Drache, die alte Schlange, die da heißt Teufel und Satan, der den ganzen Erdkreis irreführte, wurde auf die Erde geworfen, und mit ihm wurden seine Engel ausgeworfen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'Und ich hörte eine große Stimme im Himmel, die sagte: Nun ist das Heil und die Kraft und das Reich unseres Gottes und die Gewalt Seines Christus geworden. Denn hinabgeworfen ist der Verkläger unserer Brüder, der Tag und Nacht sie vor unserem Gott verklagte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'Und sie haben ihn überwunden durch das Blut des Lammes, und durch das Wort ihres Zeugnisses, und ihre Seele nicht geliebt bis in den Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Darum seid fröhlich, ihr Himmel und die darin wohnen. Wehe den Bewohnern der Erde und des Meeres, daß zu euch hinabstieg der Teufel, und hat einen großen Grimm, da er weiß, daß er wenig Zeit hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'Und da der Drache sah, daß er auf die Erde geworfen war, verfolgte er das Weib, das den Sohn geboren hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'Und dem Weibe wurden zwei Flügel des großen Adlers gegeben, auf daß sie in die Wüste flöge an ihren Ort, um daselbst ernährt zu werden vor dem Angesicht der Schlange eine Zeit und Zeiten und eine halbe Zeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'Und die Schlange warf aus hinter dem Weibe her Wasser aus ihrem Munde, wie einen Strom, um sie im Strome fortzuschwemmen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'Und die Erde half dem Weibe; und die Erde tat ihren Mund auf und verschlang den Strom, den der Drache aus seinem Munde auswarf.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'Und der Drache ward zornig über das Weib, und ging hin, Krieg zu führen mit den übrigen von ihrem Samen, welche die Gebote Gottes halten und das Zeugnis von Jesus Christus haben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'Und ich stand auf den Sand des Meeres und sah aus dem Meer ein Tier aufsteigen, das hatte sieben Häupter und zehn Hörner, und auf seinen Hörnern zehn Diademe, und auf seinen Häuptern Namen der Lästerung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'Und das Tier, das ich sah, glich einem Pardel, und seine Füße waren wie die eines Bären, und sein Maul wie eines Löwen Maul. Und der Drache gab ihm seine Kraft und seinen Thron und große Gewalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'Und ich sah eines seiner Häupter wie auf den Tod verwundet, und die Todeswunde ward geheilt. Und die ganze Erde wunderte sich hinter dem Tiere her.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'Und sie beteten den Drachen an, der dem Tier die Gewalt gab, und das Tier beteten sie an und sprachen: Wer ist dem Tier gleich? Und wer kann mit ihm Krieg führen?');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'Und es ward ihm ein Maul gegeben, große Dinge zu reden und Lästerungen, und die Gewalt gegeben, zweiundvierzig Monate so zu tun.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'Und es tat sein Maul auf zur Lästerung wider Gott, zu lästern Seinen Namen und Seine Hütte und die im Himmel wohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'Und es ward ihm gegeben, mit den Heiligen Krieg zu führen und sie zu überwinden, und ihm Gewalt gegeben über jeglichen Stamm und jede Zunge und Völkerschaft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'Und es werden es anbeten alle, die auf Erden wohnen, deren Name nicht im Buch des Lebens des Lammes geschrieben ist, das erschlagen worden seit der Gründung der Welt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Hat jemand ein Ohr, der höre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Wer in Gefangenschaft führt, der geht in Gefangenschaft hin, so jemand mit dem Schwert tötet, der muß mit dem Schwert getötet werden. Hier ist die Geduld und der Glaube der Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'Und ich sah ein anderes Tier aus der Erde aufsteigen; und es hatte zwei Hörner, wie ein Lamm, und redete wie ein Drache.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'Und es tut alle die Gewalt des ersten Tieres vor ihm und macht, daß die Erde, und die auf ihr wohnen, das erste Tier anbeten, dessen Todeswunde geheilt worden war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'Und es tut große Zeichen, so daß es vor den Menschen auch Feuer vom Himmel auf die Erde fallen läßt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'Und führt irre, die auf Erden wohnen, durch die Zeichen, die ihm gegeben wurden vor dem Tiere zu tun, und sagt denen, die auf Erden wohnen, sie sollten dem Tiere, das die Wunde vom Schwert hatte und lebte, ein Bild machen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'Und es ward ihm gegeben, dem Bilde des Tieres Geist zu geben, so daß das Bild des Tieres auch redet, und macht, daß die, so das Bild des Tieres nicht anbeten, getötet werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'Und macht, daß es allen, den Kleinen und den Großen, und den Reichen und den Armen, und den Freien und den Knechten ein Malzeichen auf ihre rechte Hand oder auf ihre Stirnen gibt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'Und daß keiner kaufen oder verkaufen kann, wenn er nicht das Malzeichen oder den Namen des Tieres oder die Zahl seines Namens hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Hier ist die Weisheit. Wer Verständnis hat, berechne die Zahl des Tieres, denn es ist eines Menschen Zahl und seine Zahl ist sechshundertsechsundsechzig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'Und ich sah, und siehe! Das Lamm stand auf dem Berge Zion und mit ihm hundertvierundvierzigtausend, die den Namen Seines Vaters an ihren Stirnen geschrieben hatten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'Und ich hörte eine Stimme aus dem Himmel, wie die Stimme vieler Wasser, und wie die Stimme eines großen Donners. Und die Stimme, die ich hörte, war wie von Harfenspielern, die auf ihren Harfen spielen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'Und sie sangen als wie ein neues Lied vor dem Thron und vor den vier Tieren und den Ältesten, und niemand konnte das Lied lernen, als die hundertvierundvierzigtausend, die erkauft sind von der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Diese sind es, die sich nicht mit Weibern befleckt haben; denn Jungfrauen sind sie. Diese sind es, die dem Lamm nachfolgen, wo es hingeht. Diese sind aus den Menschen als Erstlinge Gott und dem Lamme erkauft.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'Und in ihrem Munde ward kein Trug erfunden; denn sie sind tadellos vor dem Throne Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'Und ich sah einen anderen Engel mitten durch den Himmel fliegen, der ein ewiges Evangelium hatte, zu verkündigen denen, die auf der Erde wohnen, und jeder Völkerschaft, und Stamm, und Zunge, und Volk.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'Und sagte mit großer Stimme: Fürchtet Gott, und gebet Ihm Herrlichkeit, daß die Stunde Seines Gerichts gekommen ist, und betet Ihn an, Der den Himmel und die Erde und das Meer und die Quellen der Wasser geschaffen hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'Und ein anderer Engel folgte nach, der sprach: Gefallen, gefallen ist Babylon, die große Stadt! weil sie aus dem Wein ihres Grimmes ihrer Buhlerei alle Völkerschaften getränkt hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'Und ihnen folgte ein dritter Engel nach, und sprach mit großer Stimme: So jemand das Tier anbetet und sein Bild, und ein Malzeichen nimmt auf seine Stirne oder auf seine Hand,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'Soll auch er trinken vom Wein des Grimmes Gottes, der lauter eingeschenkt ist im Kelche Seines Zorns, und soll mit Feuer und Schwefel gequält werden vor den heiligen Engeln und vor dem Lamme.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'Und der Rauch ihrer Qual steigt auf in die Zeitläufe der Zeitläufe, und keine Ruhe haben Tag und Nacht die, so das Tier anbeten und sein Bild, und so jemand das Malzeichen seines Namens annimmt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Hier ist die Geduld der Heiligen, hier sind die, so Gottes Gebote halten und den Glauben an Jesus.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'Und ich hörte eine Stimme aus dem Himmel zu mir sagen: Schreibe: Selig sind die Toten, die in dem Herrn sterben, von nun an! Ja, spricht der Geist, auf daß sie ruhen von ihren Mühsalen. Ihre Werke aber folgen mit ihnen nach.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'Und ich sah, und siehe, eine weiße Wolke, und auf der Wolke saß einer, der dem Menschensohne glich, der hatte eine goldene Krone auf dem Haupt und eine scharfe Sichel in seiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'Und ein anderer Engel kam aus dem Tempel heraus und schrie mit großer Stimme dem zu, der auf der Wolke saß: Lege deine Sichel an und ernte; denn die Stunde für die Ernte ist gekommen, weil die Ernte der Erde ist dürre geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'Und der auf der Wolke saß, schlug mit seiner Sichel an die Erde an, und die Erde ward geerntet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'Und ein anderer Engel kam heraus aus dem Tempel im Himmel, und auch er hatte eine scharfe Sichel.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'Und ein anderer Engel ging aus dem Altar hervor, der hatte Gewalt über das Feuer, und rief dem, der die scharfe Sichel hatte, mit großem Geschrei und sprach: Lege deine scharfe Sichel an und lies die Trauben des Weinstocks der Erde; denn seine Beeren sind reif geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'Und der Engel schlug seine Sichel an die Erde und las den Weinstock der Erde und warf es in die große Kelter des Grimmes Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'Und getreten ward die Kelter außerhalb der Stadt; und es kam Blut heraus aus der Kelter bis an die Zügel der Pferde, auf tausendsechshundert Stadien.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'Und ich sah ein anderes Zeichen im Himmel, groß und wunderbar, sieben Engel, welche die sieben letzten Plagen hatten; denn in ihnen ist der Grimm Gottes vollendet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'Und ich sah wie ein gläsern Meer mit Feuer vermischt, und die so siegten über das Tier und über sein Bild und über sein Malzeichen, und über die Zahl seines Namens, standen am gläsernen Meer und hatten Harfen Gottes,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'Und sangen das Lied Moses, des Knechtes Gottes, und das Lied des Lammes und sprachen: Groß und wunderbar sind Deine Werke, Herr, Gott, Allmächtiger! gerecht und wahrhaftig Deine Wege, Du König der Heiligen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Wer sollte Dich nicht fürchten, Herr, und Deinen Namen verherrlichen? Denn Du allein bist heilig. Denn alle Völkerschaften werden kommen und vor Dir anbeten; denn Deine Urteile sind offenbar geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'Und nach dem sah ich, und siehe, es ward aufgetan der Tempel der Hütte des Zeugnisses im Himmel,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'Und heraus kamen die sieben Engel, welche die sieben Plagen hatten, aus dem Tempel, angetan mit reiner, glänzender Leinwand, und umgürtet um die Brust mit goldenen Gürteln.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'Und eines von den vier Tieren gab den sieben Engeln sieben goldene Schalen voll vom Grimme des Gottes, Der da lebt in die Zeitläufe der Zeitläufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'Und der Tempel ward des Rauches voll von der Herrlichkeit Gottes und von Seiner Kraft, und niemand konnte in den Tempel eingehen, bis daß die sieben Plagen der sieben Engel vollendet waren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'Und ich hörte eine große Stimme aus dem Tempel zu den sieben Engeln sagen: Gehet hin und gießet die Schalen des Grimmes Gottes auf die Erde aus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'Und der erste ging hin und goß seine Schale auf die Erde aus, und es ward böses und arges Geschwür an den Menschen, die das Malzeichen des Tieres hatten und sein Bild anbeteten.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'Und der zweite Engel goß seine Schale in das Meer aus; und es ward Blut wie eines Toten, und alle lebendige Seele starb in dem Meere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'Und der dritte Engel goß seine Schale in die Flüsse und in die Quellen der Wasser aus, und sie wurden Blut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'Und ich hörte den Engel der Wasser sagen: O Herr, gerecht bist Du, Der da ist und Der da war, und der Heilige, daß Du solches gerichtet hast.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'Denn sie haben das Blut der Heiligen und der Propheten vergossen, und Du gabst ihnen Blut zu trinken; denn sie sind es wert.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'Und ich hörte einen anderen aus dem Altar sagen: Ja, Herr, Gott, Allmächtiger! Wahrhaftig und gerecht sind Deine Gerichte!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'Und der vierte Engel goß seine Schale aus auf die Sonne; und es ward ihm gegeben, die Menschen mit Hitze zu schlagen durch Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'Und die Menschen entbrannten mit großer Hitze und lästerten den Namen Gottes, Der Gewalt über diese Plagen hat, und sie taten nicht Buße, Ihm die Herrlichkeit zu geben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'Und es goß der fünfte Engel seine Schale auf den Thron des Tieres aus; und sein Reich ward verfinstert, und sie zerbissen vor Schmerz ihre Zungen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'Und lästerten den Gott des Himmels ob ihren Schmerzen und ob ihren Geschwüren, und taten nicht Buße von ihren Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'Und der sechste Engel goß seine Schale auf den großen Strom Euphrat aus, und sein Wasser vertrocknete, auf daß der Weg der Könige vom Aufgang der Sonne bereitet würde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'Und ich sah aus dem Munde des Drachen, und aus dem Munde des Tieres und aus dem Munde des falschen Propheten drei unreine Geister, ähnlich Fröschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'Denn sie sind die Geister von Dämonen, welche Zeichen tun, welche ausgehen zu den Königen des Landes und des ganzen Erdkreises, sie zu versammeln zum Kriege auf jenen großen Tag Gottes, des Allmächtigen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, 'Siehe, Ich komme wie ein Dieb! Selig, wer da wacht und seine Kleider hält, daß er nicht nackend wandle, und man seine Blöße sehe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'Und sie versammelten sie an den Ort, der heißt auf hebräisch Harmageddon.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'Und der siebente Engel goß seine Schale in die Luft aus. Und es ging eine große Stimme von dem Tempel des Himmels, vom Throne aus und sprach: Es ist geschehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'Und es geschahen Blitze und Stimmen und Donner, und ein so großes Erdbeben, desgleichen nicht gewesen ist, seit Menschen geworden auf Erden, ein solches Erdbeben also groß.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'Und die große Stadt wurde zu drei Teilen, und es fielen die Städte der Völkerschaften. Und Babylon, der großen, ward gedacht vor Gott, ihr zu geben den Kelch des Weins des Grimmes Seines Zorns.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'Und jegliche Insel floh, und Berge wurden nicht mehr gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'Und großer Hagel, wie zentnerschwer, fiel aus dem Himmel auf die Menschen. Und die Menschen lästerten Gott ob der Plage des Hagels, weil sehr groß war seine Plage.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'Und es kam einer der sieben Engel, welche die sieben Schalen hatten, und redete mit mir und sagte: Komm her, ich will dir das Gericht der großen Buhlerin zeigen, die auf den vielen Wassern sitzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 'Mit welcher haben gebuhlt die Könige der Erde, und es sind von dem Wein ihrer Buhlerei trunken worden die, so die Erde bewohnen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'Und er brachte mich im Geist weg in eine Wüste; und ich sah ein Weib auf einem scharlachroten Tiere sitzen, das voll von Namen der Lästerung war und sieben Häupter und zehn Hörner hatte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'Und das Weib war mit Purpur und Scharlach umkleidet, und übergoldet mit Gold und kostbaren Steinen und Perlen; sie hatte einen goldenen Becher in ihrer Hand, der voll von Greueln und Unreinheit ihrer Buhlerei war.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'Und auf ihrer Stirne war ein Name geschrieben: Geheimnis! Babylon, die große, die Mutter der Buhlereien und der Greuel der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'Und ich sah das Weib trunken vom Blute der Heiligen und vom Blute der Zeugen Jesu. Und da ich sie sah, verwunderte ich mich mit großer Verwunderung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'Und der Engel sprach zu mir: Warum verwunderst du dich? Ich will dir sagen das Geheimnis des Weibes und des Tieres, das sie trägt, das die sieben Häupter und die zehn Hörner hat.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Das Tier, das du gesehen hast, war, und ist nicht, und wird aus dem Abgrund heraufsteigen und ins Verderben fortgehen. Und verwundern werden sich, die auf der Erde wohnen, deren Namen nicht geschrieben sind im Buche des Lebens von Gründung der Welt an, wenn sie das Tier sehen, das war und nicht ist und dennoch ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Hier ist der Sinn, der Weisheit hat; die sieben Häupter sind sieben Berge, worauf das Weib sitzt; und sind sieben Könige,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'Die fünfe sind gefallen, und der eine ist, der andere ist noch nicht gekommen, und wenn er kommt, muß er ein wenig bleiben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'Und das Tier, das war und nicht ist, ist auch selbst der achte, und ist von den sieben und geht hin ins Verderben.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'Und die zehn Hörner, die Du gesehen, sind zehn Könige, welche das Reich noch nicht empfangen haben, sondern Gewalt wie Könige eine Stunde empfangen mit dem Tier.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Diese haben eine Meinung, und übergeben dem Tiere ihre Kraft und Gewalt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Diese werden mit dem Lamme kriegen, und das Lamm wird sie überwinden, denn es ist der Herr der Herren und der König der Könige; und die mit Ihm sind Berufene und Auserwählte und Getreue.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'Und er spricht zu mir: Die Wasser, die du gesehen, wo die Buhlerin sitzt, sind Völker und Volksmengen und Völkerschaften und Zungen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'Und die zehn Hörner, die du gesehen auf dem Tiere, diese werden die Buhlerin hassen, und werden sie wüste machen und bloß, und ihr Fleisch essen und sie mit Feuer verbrennen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Denn Gott hat es in ihre Herzen gegeben, Seine Meinung zu tun, und zu tun eine Meinung, und ihr Reich dem Tiere zu geben, bis vollendet werden die Reden Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'Und das Weib, das du gesehen, ist die große Stadt, welche das Reich hat über die Könige der Erde.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Und nach diesem sah ich einen anderen Engel aus dem Himmel herabsteigen, der hatte große Gewalt, und die Erde ward erleuchtet von seiner Herrlichkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'Und er rief in Stärke, mit großer Stimme und sprach: Gefallen, gefallen ist Babylon, die große! und ein Wohnplatz von Dämonen, und ein Gefängnis jedes unreinen Geistes, und ein Gefängnis jedes unreinen und verhaßten Vogels geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Denn von dem Weine des Grimmes ihrer Buhlerei haben alle Völkerschaften getrunken, und die Könige der Erde haben mit ihr gebuhlt, und die Kaufleute der Erde sind von der Kraft ihrer Üppigkeit reich geworden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'Und ich hörte eine andere Stimme aus dem Himmel sprechen: Gehet aus von ihr, Mein Volk, auf daß ihr nicht teilhabet an ihren Sünden, und daß ihr nicht von ihren Plagen empfanget.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'Denn ihre Sünden reichten bis an den Himmel, und ihrer Ungerechtigkeiten hat Gott gedacht.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Vergeltet ihr, wie auch sie euch vergalt. Und verdoppelt ihr das Doppelte nach ihren Werken; mischt in dem Kelche, in dem sie gemischt, ihr das Doppelte!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Wieviel sie sich verherrlichte und schwelgte, so viel gebt ihr Qual und Trauer; weil sie in ihrem Herzen sprach: Ich sitze als Königin, und Witwe bin ich nicht, und Trauer werde ich nicht sehen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Darum an einem Tage sollen ihre Plagen kommen, Tod und Trauer und Hungersnot! und im Feuer soll sie verbrannt werden; denn stark ist der Herr, Gott, Der sie richtet!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'Und weinen werden und jammern über sie die Könige der Erde, die mit ihr gebuhlt und geschwelgt, wenn sie den Rauch von ihrem Brande erblicken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'Sie werden ferne stehen aus Furcht vor ihrer Qual, und sagen: Wehe, wehe, die große Stadt Babylon, die starke Stadt! Denn in einer Stunde ist dein Gericht gekommen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'Und die Kaufleute der Erde weinen und trauern über sie, weil niemand mehr ihre Ware kauft:');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'Die Ware von Gold und Silber und kostbarem Stein und Perlen und Byssus und Purpur und Seide und Scharlach, und alles Thynenholz, und alles Geräte von Elfenbein, und alles Geräte von kostbarstem Holze, und von Erz, und von Eisen, und von Marmor;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'Und Zimt und Räuchwerk, und Salbe und Weihrauch, und Wein und Öl, und Semmelmehl und Weizen, und Rinder und Schafe, und Rosse und Wagen, und Leiber und Seelen von Menschen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'Und das Obst, deiner Seele Begehr, ist von dir weggegangen, und alles Fette und Glänzende ist von dir weggegangen, und du wirst es nicht mehr finden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Und deren Kaufleute, die von ihr reich geworden, werden von ferne stehen aus Furcht vor ihrer Qual, weinen und klagen,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'Und sagen: Wehe! Wehe! Die große Stadt, die sich mit Byssus und Purpur und Scharlach umkleidete, und mit Gold sich übergoldete und mit kostbarem Steine und Perlen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'Denn in einer Stunde ist solcher Reichtum verwüstet! Und alle Steuerleute, und all die Gesellschaft auf den Schiffen, und die Schiffsleute und alle, die auf dem Meere ihr Werk haben, standen von weitem,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'Und schrien, da sie den Rauch ihres Brandes sahen, und sprachen: Wer war gleich dieser großen Stadt!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'Und sie warfen Staub auf ihre Häupter und schrien weinend und trauernd: Wehe! Wehe! Die große Stadt, in der alle, die Schiffe auf dem Meere hatten, von deren Kostbarkeit reich geworden sind! Denn in einer Stunde ist sie wüste geworden!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Seid fröhlich über sie, du Himmel, und ihr heiligen Apostel und Propheten; denn Gott hat gerichtet über sie für euch das Gericht!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'Und ein starker Engel hob auf einen Stein wie ein großer Mühlstein, und warf ihn in das Meer und sprach: So wird mit Ungestüm die große Stadt Babylon hinabgeworfen, und nimmermehr gefunden werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'Und die Stimme der Harfenspieler und Sänger und der Flötenspieler und Posaunenbläser wird nicht mehr in dir gehört! Und kein Künstler irgendeiner Kunst wird mehr in dir gefunden, und die Stimme der Mühle in dir nicht mehr gehört.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'Und kein Licht der Lampe leuchte mehr in dir! Und nimmer soll in dir die Stimme eines Bräutigams und einer Braut gehört werden! Denn deine Kaufleute waren die Großen der Erde; denn alle Völkerschaften wurden durch deine Zauberei irregeführt;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'Und in ihr wurde das Blut der Propheten und Heiligen und aller Erschlagenen auf Erden gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'Nach diesem hörte ich wie eine große Stimme einer großen Volksmenge in dem Himmel sagen: Hallelujah! Das Heil und die Herrlichkeit, und die Ehre und die Kraft dem Herrn, unserem Gotte!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'Denn wahrhaftig und gerecht sind Seine Gerichte! Denn Er hat die große Buhlerin gerichtet, welche die Erde mit ihrer Buhlerei verdarb, und gerächt das Blut Seiner Knechte von ihrer Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'Und sie sprachen zum zweitenmal: Hallelujah! Und ihr Rauch steigt auf in die Zeitläufe der Zeitläufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'Und die vierundzwanzig Ältesten und die vier Tiere fielen nieder und beteten an Gott, Der auf dem Throne saß, und sprachen: Amen. Hallelujah!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'Und vom Thron ging aus eine Stimme und sagte: Lobet unseren Gott, alle Seine Knechte und die Ihn fürchten, die Kleinen und die Großen!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'Und ich hörte, wie eine Stimme einer großen Volksmenge und wie die Stimme vieler Wasser und wie die Stimme starker Donner sagen: Hallelujah! denn der Herr, Gott, der Allmächtige, regiert!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Lasset uns freuen und frohlocken und Ihm die Herrlichkeit geben; denn die Hochzeit des Lammes ist gekommen, und Sein Weib hat Sich bereitet.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'Und ihr ward gegeben, sich zu umkleiden mit reinem und glänzendem Byssus denn der Byssus ist die Gerechtigkeit der Heiligen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'Und er sagte mir: Schreibe: Selig sind, die zum Hochzeitsmahl des Lammes berufen sind. Und er sagte mir: Dies sind die wahrhaftigen Worte Gottes!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'Und ich fiel hin vor seinen Füßen, ihn anzubeten. Und er sagte mir: Siehe zu, tue das nicht! Ich bin dein und deiner Brüder Mitknecht, die ihr Jesu Zeugnis habt. Gott bete an!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'Und ich sah den Himmel aufgetan, und siehe, ein weißes Roß, und Der darauf saß, heißt Treu und Wahrhaftig, und richtet und krieget mit Gerechtigkeit.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Und Seine Augen sind wie eine Feuerflamme, und auf Seinem Haupte viele Diademe. Er hatte einen Namen geschrieben, den niemand weiß, außer Ihm;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'Und Er war umkleidet mit einem Kleid, in Blut getaucht, und Sein Name heißt: Das Wort Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'Und die Heere im Himmel folgten Ihm nach auf weißen Rossen, mit weißem und reinem Byssus angetan;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'Und aus Seinem Munde geht aus ein scharfes Schlachtschwert, auf daß Er die Völkerschaften damit schlage, und Er wird sie mit eisernem Stabe weiden, und Er Selbst tritt die Kelter des Grimms und des Zornes Gottes, des Allmächtigen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'Und Er hat auf Seinem Kleid und auf Seiner Hüfte einen Namen geschrieben: König der Könige und Herr der Herren.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'Und ich sah einen Engel in der Sonne stehen, und er schrie mit großer Stimme und sprach zu allen Vögeln, die mitten am Himmel fliegen: Kommet her und versammelt euch zum großen Mahle Gottes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'Auf daß ihr esset Fleisch der Könige, und Fleisch der Kriegsobersten, und Fleisch der Starken, und Fleisch der Rosse und derer, die darauf sitzen, und Fleisch aller Freien und Knechte, und der Kleinen und der Großen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'Und ich sah das Tier und die Könige der Erde und ihre Heere versammelt, Krieg zu führen mit dem, Der auf dem Rosse saß, und mit Seinem Heer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'Und es ward gegriffen das Tier und mit ihm der falsche Prophet, der die Zeichen vor ihm tat, womit er die irreführte, die das Malzeichen des Tieres angenommen, und die sein Bild anbeteten. Lebendig wurden diese beide in den See des Feuers geworfen, der mit Schwefel brennt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'Und die übrigen wurden getötet mit dem Schlachtschwerte des auf dem Rosse Sitzenden, das aus Seinem Munde ausging. Und alle Vögel wurden gesättigt von ihrem Fleisch.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'Und ich sah einen Engel aus dem Himmel herabsteigen, der hatte den Schlüssel des Abgrundes und eine große Kette auf seiner Hand.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'Und er griff den Drachen, die alte Schlange, welche ist der Teufel und der Satan, und band ihn tausend Jahre;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Und warf ihn in den Abgrund und verschloß ihn und versiegelte über ihm, damit er die Völkerschaften nicht weiter irreführte, bis die tausend Jahre vollendet wären, und danach muß er auf eine kleine Zeit gelöst werden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'Und ich sah Throne, und sie setzten sich darauf, und es ward ihnen gegeben das Gericht und die Seelen derer, die um des Zeugnisses Jesu und des Wortes Gottes willen unter dem Beile fielen, und die das Tier und sein Bild nicht angebetet, noch das Malzeichen an ihre Stirn und auf ihre Hand angenommen; und sie lebten und regierten mit Christus die tausend Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Die übrigen aber von den Toten lebten nicht auf, bis daß die tausend Jahre vollendet wären. Dies ist die erste Auferstehung.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Selig und heilig ist, wer teilhat an der ersten Auferstehung. Über diese hat der zweite Tod keine Gewalt! Sondern sie sollen Priester Gottes und des Christus sein, und mit Ihm regieren tausend Jahre.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'Und wenn die tausend Jahre vollendet sind, wird der Satan aus seinem Gefängnis gelöst werden;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'Und wird ausgehen irrezuführen die Völkerschaften in den vier Ecken der Erde, den Gog und den Magog, sie zum Kriege zu versammeln, deren Zahl ist wie der Sand am Meere.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'Und sie zogen herauf über die Breite der Erde und umringten das Lager der Heiligen und die geliebte Stadt. Und es kam Feuer von Gott aus dem Himmel herab und verzehrte sie.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'Und der Teufel, der sie irreführte, ward in den See von Feuer und Schwefel geworfen, wo auch das Tier und der Lügenprophet sind, und sie werden Tag und Nacht gequält werden in die Zeitläufe der Zeitläufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'Und ich sah einen weißen, großen Thron, und Den, Der darauf saß, vor Dessen Angesicht die Erde und der Himmel flohen; und keine Stätte ward für sie gefunden.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'Und ich sah die Toten, kleine und große, vor Gott stehen, und Bücher wurden aufgetan; und ein anderes Buch ward aufgetan, welches das des Lebens ist; und die Toten wurden gerichtet aus dem, was in den Büchern geschrieben war, nach ihren Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'Und das Meer gab die Toten, die in ihm waren, und der Tod und Hölle gaben die Toten, die in ihnen waren, und sie wurden gerichtet, jeder nach seinen Werken.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'Und der Tod und die Hölle wurden in den See von Feuer geworfen. Dies ist der zweite Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'Und so jemand nicht gefunden ward geschrieben im Buche des Lebens, der ward geworfen in den See von Feuer.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'Und ich sah einen neuen Himmel und eine neue Erde; denn der erste Himmel und die erste Erde waren vergangen und das Meer ist nicht mehr.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'Und ich, Johannes, sah die heilige Stadt, das neue Jerusalem, von Gott aus dem Himmel herabsteigen, zubereitet wie eine Braut, für ihren Mann geschmückt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'Und ich hörte eine große Stimme aus dem Himmel sagen: Siehe, die Hütte Gottes bei den Menschen! Und Er wird bei ihnen wohnen, und sie werden Sein Volk sein, und Er Selbst wird bei ihnen sein, ihr Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'Und Gott wird abwischen jede Träne von ihren Augen, und der Tod wird nicht mehr sein, kein Trauern, kein Geschrei, keine Mühsal wird mehr sein; denn das Erste ist vergangen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'Und es sprach, Der auf dem Throne saß: Siehe, Ich mache alles neu. Und Er spricht zu mir: Schreibe, denn diese Worte sind wahrhaftig und getreu.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'Und Er sprach zu mir: Es ist geschehen. Ich bin das Alpha und das Omega, der Anfang und das Ende. Ich werde dem Dürstenden geben aus dem Quell des Wassers des Lebens umsonst.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Wer überwindet, der soll alles ererben, und Ich werde ihm Gott sein, und er soll Mir Sohn sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Den Zaghaften aber und den Untreuen und den Greuelhaften, und den Mördern, und den Buhlern, und den Zauberern und Götzendienern, und allen Lügnern wird ihr Teil im See, der mit Feuer und Schwefel brennt, welcher ist der zweite Tod.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'Und es kam zu mir einer der sieben Engel, welche die sieben Schalen voll der sieben letzten Plagen hatten, und redete mit mir und sagte: Komm, ich will die zeigen die Braut, des Lammes Weib.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'Und er entrückte mich im Geist auf einen großen und hohen Berg und zeigte mir die große Stadt, das heilige Jerusalem, aus dem Himmel herabsteigen von Gott.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'Sie hatte die Herrlichkeit Gottes, und Ihr Licht glich dem kostbarsten Steine, wie dem Stein Jaspis, der wie Kristall glänzt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'Und sie hatte eine große und hohe Mauer und hatte zwölf Tore und über den Toren zwölf Engel, und Namen darauf geschrieben, welche sind die der zwölf Stämme der Söhne Israels,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'Von Aufgang drei Tore, von Mitternacht drei Tore, von Mittag drei Tore, von Niedergang drei Tore.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'Und die Mauer der Stadt hatte zwölf Gründe und in diesen die Namen der zwölf Apostel des Lammes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'Und der mit mir redete, hatte ein goldenes Rohr, damit er die Stadt und ihre Tore und ihre Mauer messe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'Und die Stadt liegt viereckig; und ihre Länge ist so viel als auch die Breite. Und er maß die Stadt mit dem Rohr zu zwölftausend Stadien. Ihre Länge und Breite und Höhe sind gleich.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'Und er maß ihre Mauer hundertvierundvierzig Ellen, das Maß eines Menschen, welches ist das eines Engels.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'Und der Aufbau der Mauer war aus Jaspis und die Stadt reines Gold, ähnlich dem reinen Glas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Und die Gründe der Mauer der Stadt waren mit allerlei kostbarem Gestein geschmückt; der erste Grund war ein Jaspis, der zweite ein Saphir, der dritte ein Chalzedon, der vierte ein Smaragd,');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'Der fünfte ein Sardonyx, der sechste ein Sarder, der siebente ein Chrysolith, der achte ein Beryll, der neunte ein Topas, der zehnte ein Chrysopras, der elfte ein Hyazinth, der zwölfte ein Amethyst;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'Und die zwölf Tore zwölf Perlen. Ein jedes der Tore war aus einer Perle, und die Straße der Stadt reines Gold, wie durchscheinendes Glas.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'Und einen Tempel sah ich nicht in ihr; denn der Herr, Gott der Allmächtige, ist ihr Tempel, und das Lamm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'Und die Stadt bedarf nicht der Sonne, noch des Mondes, daß sie in ihr scheinen; denn die Herrlichkeit Gottes hat sie erleuchtet, und ihre Leuchte ist das Lamm.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'Und die Völkerschaften derer, die gerettet werden, werden in ihrem Lichte wandeln und die Könige der Erde ihre Herrlichkeit und Ehre in sie bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'Und ihre Tore werden nicht verschlossen werden des Tags denn Nacht wird da nicht sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'Und sie werden die Herrlichkeit und die Ehre der Völkerschaften in sie bringen.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'Und nicht wird in sie eingehen etwas Gemeines, und das da Greuel tut und Lüge; sondern die geschrieben sind im Lebensbuch des Lammes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'Und er zeigte mir einen reinen Strom von Lebenswasser, glänzend wie Kristall, ausgehend vom Throne Gottes und des Lammes.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Inmitten ihrer Straße und des Stroms hier und dort der Baum des Lebens, welcher zwölf Früchte trägt, jeden einzelnen Monat seine Frucht gebend, und die Blätter des Baumes sind zur Heilung der Völkerschaften.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'Und nichts Verbanntes wird mehr sein; und der Thron Gottes und des Lammes wird in ihr sein und Seine Knechte werden Ihm dienen;');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'Und werden sehen Sein Angesicht, und Sein Name wird auf ihren Stirnen sein.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'Und Nacht wird dort nicht sein, noch bedürfen sie einer Leuchte oder des Lichts der Sonne; denn der Herr Gott wird sie erleuchten, und sie werden regieren in die Zeitläufe der Zeitläufe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'Und er sprach zu mir: Diese Worte sind getreu und wahrhaftig. Und der Herr, der Gott der heiligen Propheten, hat Seinen Engel ausgesandt, Seinen Knechten zu zeigen, was schnell geschehen soll.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'Und siehe: Ich komme schnell. Selig, wer hält die Worte der Weissagung dieses Buches.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'Und ich, Johannes, sah das und hörte es, und als ich gehört und gesehen, fiel ich hin, anzubeten vor den Füßen des Engels, der mir dieses zeigte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'Und er spricht zu mir: Siehe zu, tue es nicht! Denn ich bin dein Mitknecht und der deiner Brüder, der Propheten, und derer, welche die Worte dieses Buches halten. Gott bete an!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'Und er spricht zu mir: Versiegle nicht die Worte der Weissagung dieses Buchs; denn die Zeit ist nahe.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Wer ungerecht ist, werde ferner ungerecht, und der Unreine werde ferner unrein. Und der Gerechte werde ferner gerecht, und der Heilige ferner heilig.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Und siehe, Ich komme schnell und Mein Lohn mit Mir, um jedem zu vergelten, wie sein Werk sein wird.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Ich bin das Alpha und das Omega, der Anfang und das Ende, der Erste und der Letzte.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Selig sind, die Seine Gebote tun, auf daß ihre Macht sei am Baume des Lebens, und sie durch die Tore eingehen in die Stadt.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Draußen aber sind die Hunde, und die Zauberer und die Buhler, und die Mörder und die Götzendiener und jeder, der die Lüge liebt und tut.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Ich, Jesus, habe Meinen Engel gesandt, euch dies an die Gemeinden zu bezeugen. Ich bin die Wurzel und das Geschlecht Davids, der glänzende Morgenstern.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'Und der Geist und die Braut sagen: Komm! Und wer es hört, der spreche: Komm! Und wen dürstet, der komme, und wer es will, der nehme das Wasser des Lebens umsonst!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Denn Ich bezeuge jedem, der die Worte der Weissagung dieses Buches hört: So jemand zu demselben hinzusetzt, so wird Gott auf ihn legen die Plagen, die in diesem Buche geschrieben sind.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'Und wenn jemand wegnimmt von den Worten des Buches dieser Weissagung, so wird Gott wegnehmen sein Teil vom Buche des Lebens, und von der heiligen Stadt, und von dem, was in diesem Buche geschrieben ist.');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'Es spricht, Der solches zeuget: Ja, Ich komme schnell, Amen! Ja, komm, Herr Jesus!');
INSERT INTO `GerTafel_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Die Gnade unseres Herrn Jesus Christus sei mit euch allen! Amen.');
